DROP TABLE IF EXISTS `CzeCSP_verses`;
DROP TABLE IF EXISTS `CzeCSP_books`;


            CREATE TABLE IF NOT EXISTS `translations` (
                `translation` VARCHAR(255) PRIMARY KEY,
                `title` VARCHAR(255),
                `license` TEXT
            );
            

            VALUES ('CzeCSP', '# CzeCSP: Czech Český studijní překlad', 'Creative Commons: BY-NC-ND 4.0')
            ON DUPLICATE KEY UPDATE
                `title` = VALUES(`title`),
                `license` = VALUES(`license`);
            

            CREATE TABLE `CzeCSP_books` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `name` VARCHAR(255)
            );
            

            CREATE TABLE `CzeCSP_verses` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `book_id` INT,
                `chapter` INT,
                `verse` INT,
                `text` TEXT,
                FOREIGN KEY (book_id) REFERENCES `CzeCSP_books`(id)
            );
            
