INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Na počátku stvořil Bůh nebesa a zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Země byla ⌈pustá a prázdná,⌉ temnota byla nad hlubinou a ⌈Duch Boží⌉ se vznášel nad vodami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'I řekl Bůh: Budiž světlo! A bylo světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Bůh viděl, že světlo je dobré, a oddělil Bůh světlo od tmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Bůh nazval světlo dnem a tmu nazval nocí; a byl večer a bylo ráno, jeden den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'I řekl Bůh: Budiž klenba uprostřed vod a nechť odděluje vody od vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Bůh tedy udělal klenbu a oddělil vody, které byly pod klenbou, od vod, které byly nad klenbou. A stalo se tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Bůh nazval klenbu nebesy; a byl večer a bylo ráno, den druhý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'I řekl Bůh: Ať se vody pod nebesy shromáždí na jedno místo a ukáže se souš. A stalo se tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Bůh nazval souš zemí a nahromaděné vody nazval moři. Bůh viděl, že to bylo dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'I řekl Bůh: Ať země dá vyrašit trávě, zeleni vysévající semeno, ovocnému stromoví nesoucímu na zemi ovoce podle svého druhu, ve kterém je jeho semeno. A stalo se tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Země vydala trávu, zeleň vysévající semeno podle svého druhu a stromoví nesoucí ovoce, ve kterém je jeho semeno podle jeho druhu. Bůh viděl, že to bylo dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'A byl večer a bylo ráno, den třetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'I řekl Bůh: Ať jsou světla na nebeské klenbě, aby oddělovala den od noci a byla na znamení, k určování časů, dnů a let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'A ať jsou světly na nebeské klenbě, aby svítila na zemi. A stalo se tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Bůh udělal dvě veliká světla: Větší světlo, ⌈aby vládlo ve dne,⌉ a menší světlo, ⌈aby vládlo v noci,⌉ a hvězdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Bůh je dal na nebeskou klenbu, aby svítila na zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'a aby ⌈ovládala den a noc⌉ a oddělovala světlo od tmy. Bůh viděl, že to bylo dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'A byl večer a bylo ráno, den čtvrtý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'I řekl Bůh: Ať se vody hemží ⌈živou havětí⌉ a ať létavci létají nad zemí pod nebeskou klenbou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Bůh stvořil veliké draky a všechny pohyblivé formy života, jimiž se začaly hemžit vody, podle jejich druhů, také každého okřídleného létavce podle jeho druhu. Bůh viděl, že to bylo dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'A Bůh je požehnal slovy: Ploďte a množte se a naplňte vody v mořích; a létavci ať se rozmnoží na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'A byl večer a bylo ráno, den pátý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'I řekl Bůh: Ať země vydá formy života podle jeho druhu: Dobytek, plazy a zemskou zvěř podle svého druhu. A stalo se tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Bůh učinil zemskou zvěř podle jejího druhu, dobytek podle jeho druhu a každého zemského plaza podle jeho druhu. Bůh viděl, že to bylo dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'I řekl Bůh: Učiňme člověka ⌈k našemu obrazu, jako naši podobu,⌉ aby panovali nad mořskými rybami, nad nebeským ptactvem, nad dobytkem a nad celou zemí i nad všemi plazy pohybujícími se na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Bůh stvořil člověka ke svému obrazu, stvořil ho k obrazu Božímu, stvořil je ⌈muže a ženu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Bůh je požehnal a řekl jim: Ploďte a množte se a naplňte zemi, podmaňte si ji a panujte nad mořskými rybami, nad nebeským ptactvem a nad vším živým, co se na zemi hýbe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'A Bůh řekl: Hle, dal jsem vám každou rostlinu mající semena na povrchu celé země a každý strom, na němž je ovoce mající semena. To budete mít za pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Veškeré zemské zvěři, všemu nebeskému ptactvu a všemu pohybujícímu se na zemi, v čem je živá duše, jsem dal za pokrm každou zelenou rostlinu. A stalo se tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Bůh viděl všechno, co učinil, a hle, bylo to velmi dobré. A byl večer a bylo ráno, den šestý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Tak byla dokončena nebesa a země i všechny jejich zástupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Sedmého dne Bůh dokončil své dílo, které konal, a sedmého dne přestal s veškerým svým dílem, které konal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Bůh sedmý den požehnal a posvětil ho, protože v něm přestal s veškerým svým dílem, které Bůh stvořil a učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Toto je rodopis nebes a země, když byly stvořeny. V den, kdy Hospodin Bůh učinil zemi a nebesa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'na zemi ještě nebylo žádné polní křoví ani ještě nevzcházela žádná polní zeleň, protože Hospodin Bůh nesesílal na zemi déšť a nebyl člověk, aby zemi obdělával,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'ale pramen vystupoval ze země a zavlažoval celý zemský povrch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Hospodin Bůh vytvořil člověka z prachu ze země, a do jeho chřípí vdechl dech života; a člověk se stal živou duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'A Hospodin Bůh vysadil zahradu v Edenu na východě a umístil tam člověka, kterého vytvořil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Hospodin Bůh dal ze země vyrůst veškerému stromoví žádoucímu na pohled a dobrému k jídlu, stromu života uprostřed zahrady a stromu poznání dobrého a zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Z Edenu vytéká řeka, aby napájela zahradu. Odtamtud se rozděluje a tvoří čtyři ramena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'První se jmenuje Píšon, to obtéká celou zemi Chavílu, kde je zlato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Zlato té země je ryzí. Je tam také bdelium a kámen karneol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Druhá řeka se jmenuje Gíchón: ta obtéká celou zemi Kúš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Třetí řeka se jmenuje Chidekel: ta teče na východ od Asýrie. Čtvrtá řeka je Eufrat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Hospodin Bůh vzal člověka a umístil ho v zahradě v Edenu, aby ji obdělával a střežil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'A Hospodin Bůh člověku přikázal: Ze všeho stromoví zahrady směle jez,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'ale ze stromu poznání dobrého a zlého, z toho nejez. Neboť v den, kdy bys z něho jedl, ⌈jistě zemřeš.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'I řekl Hospodin Bůh: Není dobré, aby byl člověk samoten. Učiním mu pomoc jako jeho protějšek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Hospodin Bůh vytvořil ze země všechnu polní zvěř a všechno nebeské ptactvo a přivedl je k člověku, aby viděl, jak je nazve. A jak člověk každou živou duši nazval, takové bylo její jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'A člověk pojmenoval všechen dobytek a nebeské ptactvo i všechnu polní zvěř, ale pro člověka se nenalezla pomoc jako jeho protějšek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Hospodin Bůh tedy uvrhl na člověka hluboký spánek, a zatímco spal, vzal jedno z jeho žeber a to místo uzavřel masem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'A Hospodin Bůh vybudoval z žebra, které vzal z člověka, ženu a přivedl ji k člověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Člověk řekl: Teď je to kost z mých kostí a maso z mého masa! Bude se nazývat ženou, protože byla vzata z muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Proto muž opustí svého otce i svou matku a přilne ke své ženě a budou jedno tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'A oba, člověk i jeho žena, byli nazí a nestyděli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Had byl nejchytřejší ze vší polní zvěře, kterou Hospodin Bůh učinil. Řekl ženě: Opravdu Bůh řekl: Nejezte ze žádného stromu v zahradě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Žena hadovi odpověděla: Z ovoce stromů v zahradě jíst můžeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Ale o ovoci stromu, který je uprostřed zahrady, Bůh řekl: Nejezte z něho, ani se ho nedotýkejte, jinak zemřete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Had ženě řekl: Jistě nezemřete,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'neboť Bůh ví, že v den, kdy z něho budete jíst, se vaše oči otevřou a budete jako Bůh, budete znát dobré a zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Žena viděla, že je to strom dobrý k jídlu a lákavý pro oči, strom žádoucí pro získání moudrosti. Vzala z jeho ovoce a jedla. Dala také svému muži, který byl s ní, a jedl i on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Oběma se otevřely oči a poznali, že jsou nazí. Sešili tedy fíkové listí a udělali si ⌈bederní roušky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Pak uslyšeli hlas Hospodina Boha, procházejícího se po zahradě ⌈v denním větru,⌉ a ukryli se člověk i jeho žena před tváří Hospodina Boha uprostřed stromoví zahrady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Hospodin Bůh zavolal na člověka a zeptal se ho: Kde jsi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'On odpověděl: Slyšel jsem tvůj hlas v zahradě a bál jsem se, protože jsem nahý; proto jsem se schoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'I řekl: Kdo ti pověděl, že jsi nahý? Nejedl jsi ze stromu, z něhož jsem ti zakázal jíst?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Člověk odpověděl: Žena, kterou jsi dal, aby byla se mnou, ta mi dala z toho stromu, a já jsem jedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Nato Hospodin Bůh ženě řekl: Cos to učinila? Žena řekla: Had mě podvedl a já jsem jedla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'A Hospodin Bůh řekl hadovi: Protože jsi to učinil, buď ⌈proklet a vyvržen od všech zvířat a od veškeré polní zvěře,⌉ budeš se plazit po břiše a žrát prach po všechny dny svého života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'A položím nepřátelství mezi tebe a ženu a mezi símě tvé a símě její; ono tobě rozdrtí hlavu a ty jemu rozdrtíš patu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Ženě řekl: Velice rozmnožím ⌈tvé strádání a tvou úzkost,⌉ v bolestech budeš rodit děti; budeš dychtit po svém muži, ale on bude nad tebou vládnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'A Adamovi řekl: Protože jsi uposlechl svou ženu a jedl jsi ze stromu, o kterém jsem ti přikázal: Z toho nejez, budiž kvůli tobě prokleta země: S námahou z ní budeš jíst po všechny dny svého života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Bude ti vydávat trní a bodláčí a budeš jíst polní rostliny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'V potu své tváře budeš jíst chléb, dokud se nenavrátíš do země, neboť jsi z ní vzat. Prach jsi a do prachu se navrátíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'A člověk svou ženu pojmenoval Eva, protože ona se stala matkou všech živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'A Hospodin Bůh udělal Adamovi a jeho ženě kožené suknice a oblékl je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'I řekl Hospodin Bůh: Hle, člověk je jako jeden z nás v tom, že zná dobré a zlé. Ať teď nevztáhne ruku, aby vzal a jedl také ze stromu života a žil navěky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Proto Hospodin Bůh poslal člověka pryč ze zahrady Eden, aby obdělával zemi, z níž byl vzat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Vyhnal ho a postavil od východu k zahradě Eden cheruby s míhajícím se plamenným mečem, aby střežili cestu ke stromu života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'I poznal člověk svou ženu Evu a ta otěhotněla a porodila Kaina. Řekla: ⌈Vytvořila jsem muže s Hospodinem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Dále porodila jeho bratra Ábela. Ábel se stal pastýřem ovcí, ale Kain se stal rolníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, '⌈Po nějakém čase⌉ se stalo, že Kain přinesl z plodů země ⌈obětní dar⌉ Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'I Ábel obětoval, avšak on přinesl z prvorozených svého stáda a z nich ty tučné části. A Hospodin shlédl na Ábela a na jeho obětní dar,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'ale na Kaina a na jeho obětní dar neshlédl. Kain vzplanul velikým hněvem a jeho tvář opadla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Hospodin Kainovi řekl: Proč jsi vzplanul hněvem a proč tvoje tvář opadla?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Cožpak ⌈nebudeš pozdvižen,⌉ budeš–li jednat správně? A jestli nebudeš jednat správně, ve dveřích číhá hřích. Dychtí po tobě, ale ty nad ním máš vládnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Kain řekl svému bratru Ábelovi: ⌈ Pojďme na pole.⌉ A stalo se, když byli na poli, že Kain povstal proti svému bratru Ábelovi a zabil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Hospodin řekl Kainovi: Kde je tvůj bratr Ábel? On odpověděl: Nevím. Cožpak jsem strážcem svého bratra?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Hospodin řekl: Cos to udělal? Slyš, krev tvého bratra ke mně křičí ze země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'A nyní budeš proklet ⌈ a vyvržen ze⌉ země, která otevřela svá ústa, aby ze tvé ruky přijala krev tvého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Když budeš obdělávat zemi, již ti nevydá svou sílu. Budeš na zemi bezdomovcem a tulákem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Kain Hospodinu odpověděl: Můj trest je větší, než se dá unést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Hle, dnes jsi mne vyhnal z povrchu země a před tvou tváří se budu muset ukrývat. Budu na zemi bezdomovcem a tulákem a každý, kdo mě najde, mne bude moci zabít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Hospodin mu řekl: ⌈Ne tak.⌉ Kdokoliv by Kaina zabil, přivodí si sedminásobnou pomstu. A Hospodin vložil na Kaina znamení, aby ho nikdo, kdo ho najde, nezabil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Kain odešel od Hospodina a pobýval v zemi Nódu na východ od Edenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'I poznal Kain svou ženu, ta otěhotněla a porodila Henocha. Pak stavěl město a nazval jméno toho města podle jména svého syna Henocha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Henochovi se narodil Írad, Írad zplodil Mechújáela, Mechújáel zplodil Metúšáela, Metúšáel zplodil Lámecha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lámech si vzal dvě ženy. Jméno jedné bylo Áda a jméno druhé Sila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Áda porodila Jábala, který se stal otcem těch, kdo bydlí ve stanu a chovají dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Jeho bratr se jmenoval Júbal. Ten se stal otcem všech hrajících na lyru a flétnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'A Sila, ta také porodila: Túbal–kaina, ⌈kováře všech bronzových a železných nástrojů.⌉ Túbal–kainova sestra byla Naama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'I řekl Lámech svým ženám: Ádo a Silo, slyšte můj hlas! Ženy Lámechovy, naslouchejte mé řeči! Neboť ⌈jsem zabil muže za svou modřinu, chlapce za svůj šrám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Jestliže Kain bude pomstěn sedminásobně, Lámech sedmdesátisedminásobně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Adam znovu poznal svou ženu, ta porodila syna a dala mu jméno Šét, neboť řekla: Bůh mi vložil dalšího potomka místo Ábela, jehož zabil Kain.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'A Šétovi, také jemu se narodil syn. Dal mu jméno Enóš. Tehdy začalo vzývání Hospodinova jména.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Toto je záznam Adamova rodopisu. V den, kdy Bůh stvořil člověka, učinil ho v podobě Boží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'muže a ženu je stvořil. V den, kdy je stvořil, je požehnal a nazval ⌈je Adam.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'I žil Adam sto třicet let a zplodil syna ke své podobě jako svůj obraz. Dal mu jméno Šét.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Po zplození Šéta bylo Adamových dnů osm set let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Všech dnů, kdy Adam žil, bylo devět set třicet let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Šét žil sto pět let a zplodil Enóše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Po zplození Enóše žil Šét osm set sedm let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Všech Šétových dnů bylo devět set dvanáct let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enóš žil devadesát let a zplodil Kénana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Po zplození Kénana žil Enóš osm set patnáct let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Všech Enóšových dnů bylo devět set pět let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kénan žil sedmdesát let a zplodil Mahalalela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Po zplození Mahalalela žil Kénan osm set čtyřicet let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Všech Kénanových dnů bylo devět set deset let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalalel žil šedesát pět let a zplodil Jereda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Po zplození Jereda žil Mahalalel osm set třicet let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Všech Mahalalelových dnů bylo osm set devadesát pět let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jered žil sto šedesát dva let a zplodil Henocha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Po zplození Henocha žil Jered osm set let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Všech Jeredových dnů bylo devět set šedesát dva let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henoch žil šedesát pět let a zplodil Metúšelacha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Po zplození Metúšelacha chodil Henoch s Bohem tři sta let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Všech Henochových dnů bylo tři sta šedesát pět let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Henoch chodil s Bohem a už nebyl, protože ho Bůh vzal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Metúšelach žil sto osmdesát sedm let a zplodil Lámecha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Po zplození Lámecha žil Metúšelach sedm set osmdesát dva let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Všech Metúšelachových dnů bylo devět set šedesát devět let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lámech žil sto osmdesát dva let a zplodil syna');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'a dal mu jméno Noe se slovy: Ten nám dá odpočinutí od našeho díla a od námahy našich rukou, od země, kterou Hospodin proklel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Po zplození Noeho žil Lámech pět set devadesát pět let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Všech Lámechových dnů bylo sedm set sedmdesát sedm let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Když bylo Noemu pět set let, zplodil Noe Šéma, Cháma a Jefeta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Když se lidé začali na zemi množit a rodily se jim dcery,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, '⌈synové Boží⌉ viděli, že lidské dcery jsou hezké, a brali si za ženy všechny, které si přáli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'A Hospodin řekl: Můj duch nebude ⌈v člověku⌉ přebývat navěky, protože je tělo. Jeho dnů bude sto dvacet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'V oněch dnech byli na zemi obři -- a také potom, když synové Boží vcházeli k lidským dcerám a ty jim rodily; to jsou ti dávní hrdinové, věhlasní muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'I viděl Hospodin, jak mnoho je na zemi lidského zla a že všechno zaměření úmyslů jejich srdce je napořád jenom zlé,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'a Hospodin litoval, že na zemi učinil člověka, a trápil se ve svém srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Hospodin řekl: Vyhladím z povrchu země člověka, kterého jsem stvořil, vyhladím člověka i zvěř, plazy i nebeské ptactvo, protože lituji, že jsem je učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Ale Noe ⌈nalezl milost⌉ v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Toto je rodopis Noeho: Noe byl muž spravedlivý, bezúhonný ve své generaci; Noe chodil s Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Noe zplodil tři syny: Šéma, Cháma a Jefeta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Země však byla před Bohem zkažená; země byla plná násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Bůh hleděl na zemi, a hle, byla zkažená, protože všechno tvorstvo na zemi pokazilo svou cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'I řekl Bůh Noemu: Přede mne ⌈přišel konec všeho těla,⌉ protože země je plná jejich násilí. Hle, zničím je spolu se zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Udělej si archu z goferového dřeva. V arše udělej komůrky a ⌈vysmol ji smolou⌉ zevnitř i zvnějšku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'A udělej ji takto: Délka archy bude tři sta loket, její šířka padesát loket a její výška třicet loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'U archy udělej světlík a ukonči ho loket odshora. Vchod archy umísti v jejím boku a udělej v ní dolní, druhé a horní podlaží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'A hle, já přivedu potopu, vody na zemi, abych zničil pod nebem všechno tvorstvo, v němž je duch života. Všechno, co je na zemi, zahyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Ale s tebou ustanovím svou smlouvu. Vejdeš do archy ty a s tebou tvoji synové, tvá žena i ženy tvých synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'A ze všeho živého, z veškerého tvorstva, uvedeš pár od každého druhu do archy, aby s tebou zůstal naživu; budou to samec a samice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Z ptactva podle jeho druhů, ze zvěře podle jejích druhů a ze všech zemských plazů podle jejich druhů pár od každého druhu přijdou k tobě, aby byli zachováni při životě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'A ty si seber ze všech druhů potravy, co se dá jíst, a shromáždi to k sobě. Bude to k jídlu pro tebe i pro ně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'A Noe to udělal. Udělal všechno tak, jak mu Bůh přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Pak Hospodin řekl Noemu: Vejdi ty a celá tvá rodina do archy, neboť jsem viděl, že v této generaci jsi přede mnou spravedlivý jen ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Ze všech čistých zvířat vezmeš s sebou ⌈po sedmi⌉ párech, vždy ⌈samce a jeho samici,⌉ a ze zvířat, která nejsou čistá, pár, ⌈samce a jeho samici.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Také z nebeského ptactva ⌈po sedmi⌉ párech, samce a samici, aby na povrchu celé země zůstalo naživu potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Protože již za sedm dnů sešlu na zemi déšť trvající čtyřicet dní a čtyřicet nocí a vyhladím z povrchu země vše živé, jež jsem učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'A Noe udělal všechno, jak mu Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noemu bylo šest set let, když nastala potopa, vody na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'I vešel Noe a jeho synové, jeho žena i ženy jeho synů s ním před vodami potopy do archy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Z čistých zvířat i ze zvířat, která nejsou čistá, z ptactva i ze všeho, co se hýbe na zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'vždy ⌈po párech⌉ vešli k Noemu do archy, samec a samice tak, jak Bůh přikázal Noemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'I stalo se za sedm dnů, že vody potopy přišly na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'V šestistém roce života Noeho, ve druhém měsíci v sedmnáctém dni měsíce -- v tom dni se rozevřely všechny prameny veliké hlubiny a uvolnily se nebeské průduchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'A na zemi nastal déšť trvající čtyřicet dnů a čtyřicet nocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Právě toho dne vešli Noe i Šém, Chám a Jefet, synové Noeho, žena Noeho a tři ženy jeho synů s nimi do archy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'oni i všechna zvěř podle svých druhů, všechen dobytek podle svých druhů, všichni plazi pohybující se na zemi, podle svých druhů, všichni létavci podle svých druhů, každý pták, každý okřídlenec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Vešli k Noemu do archy po párech ze všeho tvorstva, v němž byl duch života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Přicházeli vždy samec a samice z veškerého tvorstva; vešli tak, jak mu Bůh přikázal. A Hospodin za ním zavřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Potopa na zemi trvala čtyřicet dnů, voda přibývala, zvedla archu a ta stoupala od země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Vody se na zemi rozmáhaly a velmi přibývaly a archa plula po povrchu vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Vody se na zemi převelice rozmáhaly, až byly přikryty všechny vysoké hory všude pod nebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Vody se rozmohly na patnáct loket výše, když byly přikryty hory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'A zahynulo všechno tvorstvo pohybující se na zemi -- ptactvo, dobytek i zvěř, veškerá havěť hemžící se na zemi i všichni lidé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Všechno, co mělo ve svém chřípí dech života, všechno, co bylo na souši, zemřelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Tak Bůh vyhladil vše živé z povrchu země od lidí až po zvěř, po plazy a po nebeské ptactvo, vše bylo smeteno ze země. Zůstal jenom Noe a to, co bylo s ním v arše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'A vody se nad zemí rozmáhaly sto padesát dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Bůh však pamatoval na Noeho, na všechnu zvěř i na všechen dobytek, který byl s ním v arše, a Bůh nechal nad zemí vanout vítr a vody opadaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Prameny hlubiny a nebeské průduchy byly zacpány a déšť z nebe byl zadržen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'A voda ze země postupně a vytrvale ustupovala, takže po sto padesáti dnech vody ubylo');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'a v sedmém měsíci sedmnáctého dne toho měsíce archa spočinula na pohoří Ararat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Vody postupně ubývalo až do desátého měsíce. Prvního dne desátého měsíce se ukázaly vrcholky hor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'A po čtyřiceti dnech Noe otevřel v arše okno, které udělal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'a vypustil havrana, který ⌈odlétal a vracel se,⌉ dokud voda ze země nevyschla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Pak vypustil holubici, aby viděl, zda už voda ustoupila z povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Ale holubice nenalezla pro svou nohu místo odpočinku a vrátila se k němu do archy, protože voda ještě byla na povrchu celé země. Vztáhl ruku, vzal ji a přinesl ji k sobě do archy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, '⌈Dychtivě čekal⌉ ještě dalších sedm dní a znovu z archy vypustil holubici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Holubice se k němu k večeru vrátila, a hle, v zobáku měla ⌈čerstvě utržený⌉ olivový list. Noe poznal, že voda ze země ustoupila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Čekal ještě dalších sedm dnů a vypustil holubici, ale již se k němu znovu nevrátila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'V šestistém prvém roce života Noeho v prvním dni prvního měsíce voda ze země začala osychat. Noe sundal příkrov archy a viděl, hle, povrch země osychal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Ve druhém měsíci, ve dvacátém sedmém dni měsíce země vyschla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'I promluvil Bůh k Noemu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Vyjdi z archy ty a s tebou tvá žena i tvoji synové a ženy tvých synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Vyveď s sebou všechno živé, co je s tebou ze všeho tvorstva: ptactvo, dobytek a všechny plazy pohybující se na zemi; ať se na zemi hemží, rozplodí se a rozmnoží se na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'A Noe vyšel a s ním jeho synové, jeho žena i ženy jeho synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Všechna zvěř, všichni plazi a všichni létavci -- všechno, co se hýbe na zemi -- vyšli podle svých čeledí z archy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Noe pak ⌈postavil Hospodinu oltář⌉ a vzal ze všeho čistého dobytka a ze všeho čistého ptactva a přinesl na oltáři zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'I ucítil Hospodin příjemnou vůni a řekl ⌈si v⌉ srdci: Již nikdy neprokleji zemi kvůli člověku, protože zaměření lidského srdce je od jeho mládí zlé, a už nikdy nepobiji všechno živé tak, jak jsem učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Po všechny dny země nikdy nepřestane setba ani žeň, chlad ani žár, léto ani zima, den ani noc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Pak Bůh požehnal Noeho a jeho syny a řekl jim: Ploďte a množte se a naplňte zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Bázeň před vámi a děs z vás padne na všechnu zemskou zvěř a na všechno nebeské ptactvo, na vše, co se hýbe na zemi, i na všechny mořské ryby: Jsou dány do vaší ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Všechno živé, co se hýbe, budete mít za pokrm. Jako jsem vám dal zelené rostliny, tak vám dávám všechno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Jen maso ⌈s jeho životem,⌉ s jeho krví, nejezte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Ano, vaši krev, krev vašich životů budu vyhledávat. Budu ji vyhledávat od každého zvířete. I od člověka -- to jest od jeho bratra -- budu vyhledávat život člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Kdo prolévá krev člověka, jiným člověkem bude prolita krev jeho. Vždyť k obrazu Božímu učinil Bůh člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ale vy se ploďte a množte, hemžete se na zemi a rozmnožte se na ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'A Bůh řekl Noemu a s ním jeho synům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Hle, já ustanovuji svou smlouvu s vámi a s vaším potomstvem po vás');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'a s každou živou duší, která je s vámi, s ptactvem, s dobytkem a s veškerou zemskou zvěří s vámi; ode všech, kdo vyšli z archy, ⌈po všechnu zvěř země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ustanovuji s vámi svou smlouvu, že již nevyhladím všechno tvorstvo vodami potopy a že už nebude potopa, která by zničila zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'A Bůh řekl: Toto je ⌈znamení smlouvy,⌉ kterou kladu mezi sebe a vás i každou živou duši, která je s vámi, pro věčné generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Na oblak jsem dal duhu, která bude znamením smlouvy mezi mnou a zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Když zahalím zemi oblakem a na oblaku se ukáže duha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'připomenu si svou smlouvu mezi mnou a vámi i každou živou duší v celém tvorstvu a voda se již nestane potopou, aby zničila všechno tvorstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Když bude na oblaku duha, spatřím ji a připomenu si věčnou smlouvu mezi Bohem a každou živou duší v celém tvorstvu, které je na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'A Bůh řekl Noemu: Toto je znamení smlouvy, kterou jsem ustanovil mezi sebou a vším tvorstvem, které je na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Synové Noeho, kteří vyšli z archy, byli: Šém, Chám a Jefet. Chám byl otec Kenaana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Tito tři byli synové Noeho a z nich se zalidnila celá země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, '⌈Noe byl rolník a první vysázel⌉ vinici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Jednou pil víno, opil se a obnažil se uprostřed svého stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Chám, otec Kenaana, viděl nahotu svého otce a oznámil to venku svým dvěma bratrům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Ale Šém a Jefet vzali plášť, položili si ho na ramena, šli pozpátku a zakryli nahotu svého otce. Jejich tváře byly odvrácené, takže nahotu svého otce neviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Když se Noe probral ze svého vína a dozvěděl se, co mu jeho nejmladší syn provedl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'řekl: Buď proklet Kenaan! Ať je svým bratrům ⌈posledním z otroků.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Dále řekl: Požehnán buď Hospodin, Bůh Šémův. Ať je Kenaan jejich otrokem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Ať Bůh rozšíří Jefeta, ať přebývá ve stanech Šémových a ať je Kenaan jejich otrokem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Po potopě byl Noe živ tři sta padesát let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Všech dnů Noeho bylo devět set padesát let, a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Toto je rodopis Noeho synů, Šéma, Cháma a Jefeta. Po potopě se jim narodili synové:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Synové Jefetovi: Gomer, Magóg a Mádaj, Jávan a Túbal, Mešek a Tíras.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Synové Gomerovi: Aškenaz, Rífat a Togarma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Synové Jávanovi: Elíša a Taršíš, Kitejci a Dódanci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Z těch se rozptýlily přímořské národy ve svých zemích, každý podle svého jazyka a podle svých čeledí ve svých národech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Dále synové Chámovi: Kúš, Misrajim, Pút a Kenaan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'A synové Kúšovi: Seba a Chavíla, Sabta, Raema a Sabteka. Synové Raemovi: Šeba a Dedán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Kúš pak zplodil Nimroda. On ⌈první se stal⌉ hrdinou na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'On byl mocný lovec před Hospodinem; proto se říká: Mocný lovec před Hospodinem jako Nimrod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Počátkem jeho království byl Babylon, Erech, Akad a Kalné v zemi Šineáru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Z této země vyšel do Asýrie, kde postavil Ninive i Rechobót–ír a Kelach');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'a Resen mezi Ninivem a Kelachem -- to je velké město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Misrajim zplodil Lúďany a Anámce, Lehábany a Naftúchany,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Patrúsany, Kaslúchany (z nichž vyšli Pelištejci) a Kaftórce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kenaan zplodil Sidóna, svého prvorozeného, a Chéta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Jebúsejce, Emorejce a Girgašejce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Chivejce, Arkejce a Síňana,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arváďana, Semárce a Chamáťana, a potom se kenaanské čeledi rozptýlily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Pomezí Kenaanců se táhlo od Sidónu, kudy se chodí ku Geraru, až ke Gaze; dále kudy se chodí k Sodomě, Gomoře, Admě, Sebójimu až k Leše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Tito jsou synové Chámovi podle svých čeledí a jazyků, na svých územích a ve svých národech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Také Šémovi, ⌈staršímu bratru Jefetovu,⌉ se narodili synové. Byl otcem všech synů Heberových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Synové Šémovi: Élam a Ašúr, Arpakšád, Lúd a Aram.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'A synové Aramovi: Ús a Chúl, Geter a Maš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpakšád zplodil Šelacha a Šelach zplodil Hebera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Heberovi se narodili dva synové. Jméno jednoho bylo Peleg (protože v jeho dnech byla rozdělena země) a jméno jeho bratra bylo Joktán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktán pak zplodil Almódada a Šelefa, Chasarmáveta a Jeracha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadórama, Úzala a Diklu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Óbala, Abímaela a Šebu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ofíra, Chavílu a Jóbaba; ti všichni jsou synové Joktánovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Jejich sídliště se táhlo od Méši, kudy se chodí k Sefáru, hoře na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Tito jsou synové Šémovi podle svých čeledí a jazyků, na svých územích podle svých národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Tyto jsou čeledi synů Noeho podle svých rodopisů ve svých národech. Z těch se po potopě rozptýlily národy po zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Celá země byla jedné řeči a jedněch slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Jak táhli od východu, nalezli v šineárské zemi pláň a tam se usadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Řekli jeden druhému: Nuže, ⌈udělejme cihly a důkladně je vypalme.⌉ A měli cihlu místo kamene a asfalt měli místo malty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'A řekli: Nuže, vybudujme si město a věž, jejíž vrchol bude v nebi, a uděláme si jméno, abychom se nerozptýlili po celém povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Hospodin sestoupil, aby viděl to město a věž, které lidští synové stavěli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Hospodin řekl: Hle, jsou jeden lid a všichni mají jednu řeč, a toto je začátek jejich činnosti. Tak pro ně nebude nemožné nic, co si usmyslí udělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Nuže, sestupme a zmaťme tam jejich řeč, takže jeden nebude rozumět řeči druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Tak je odtamtud Hospodin rozptýlil po celém povrchu země, a přestali stavět to město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Proto nazvali jeho jméno Bábel, neboť tam Hospodin zmátl řeč celé země a odtamtud je Hospodin rozptýlil po celém povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Toto je rodopis Šémův: Šémovi bylo sto let, když zplodil Arpakšáda; bylo to dva roky po potopě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Po zplození Arpakšáda žil Šém pět set let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arpakšád žil třicet pět let a zplodil Šelacha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Po zplození Šelacha žil Arpakšád čtyři sta tři let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Šelach žil třicet let a zplodil Hebera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Po zplození Hebera žil Šelach čtyři sta tři let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Heber žil třicet čtyři let a zplodil Pelega.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Po zplození Pelega žil Heber čtyři sta třicet let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg žil třicet let a zplodil Reúa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Po zplození Reúa žil Peleg dvě stě devět let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Reú žil třicet dva let a zplodil Serúga.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Po zplození Serúga žil Reú dvě stě sedm let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serúg žil třicet let a zplodil Náchora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Po zplození Náchora žil Serúg dvě stě let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Náchor žil dvacet devět let a zplodil Teracha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Po zplození Teracha žil Náchor sto devatenáct let a zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Terach žil sedmdesát let a zplodil Abrama, Náchora a Hárana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Toto je rodopis Terachův: Terach zplodil Abrama, Náchora a Hárana. Háran zplodil Lota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Háran zemřel před svým otcem Terachem ve své rodné zemi v chaldejském Úru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram a Náchor si vzali ženy: Jméno Abramovy ženy bylo Sáraj a jméno Náchorovy ženy Milka, dcera Hárana, otce Milky a Jisky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sáraj však byla neplodná, neměla dítě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Terach vzal svého syna Abrama, svého vnuka Lota, syna Háranova, svou snachu Sáraj, ženu svého syna Abrama, a vyšli spolu z chaldejského Úru, aby šli do kenaanské země. Přišli až do Cháranu a tam se usídlili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Terachových dnů bylo dvě stě pět let, když Terach v Cháranu zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Hospodin řekl Abramovi: Odejdi ze své země, ze svého příbuzenstva a ⌈z domu svého otce⌉ do země, kterou ti ukážu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'A učiním tě ⌈velkým národem,⌉ požehnám tě a tvé ⌈jméno učiním velkým,⌉ ⌈a buď⌉ požehnáním!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Požehnám těm, kdo žehnají tobě, a na toho, kdo tě proklíná, uvedu prokletí. V tobě budou požehnány všechny čeledi země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'A Abram šel tak, jak mu Hospodin řekl, a s ním šel Lot. Abramovi bylo sedmdesát pět let, když vyšel z Cháranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Abram vzal svou ženu Sáraj, Lota, syna svého bratra, a všechen majetek, jejž nabyli, i lidi, které získali v Cháranu, a vyšli, aby se ubírali do kenaanské země. I přišli do kenaanské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Abram prošel zemi až do místa Šekemu, až k dubu v Móre. Tehdy byli v zemi Kenaanci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'I ukázal se Abramovi Hospodin a řekl: Tuto zemi dám tvému semeni. Pak tam postavil oltář Hospodinu, který se mu ukázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Odtamtud táhl k pohoří východně od Bét–elu a postavil svůj stan. Na západ měl Bét–el a na východ Aj; tam postavil Hospodinu oltář a vzýval Hospodinovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Pak Abram vyrazil a stále táhl k Negebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Pak v zemi nastal hlad. Abram sestoupil do Egypta, aby tam pobýval jako cizinec, protože hlad v zemi byl tíživý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Když se přiblížil k Egyptu, řekl své ženě Sáraji: Hle, vím, že jsi žena ⌈krásného vzhledu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Když tě Egypťané uvidí a řeknou: To je jeho žena, pak mě zabijí a tebe nechají naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Říkej prosím, že jsi má sestra, aby se mi díky tobě vedlo dobře a aby kvůli tobě má duše zůstala naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Když přišel Abram do Egypta, Egypťané uviděli tu ženu, jak velice je krásná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Když ji spatřila faraonova knížata, chválila ji u faraona. Žena byla vzata do paláce faraona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'který kvůli ní Abramovi prokázal dobro: dostal brav, skot a osly, otroky a otrokyně, oslice a velbloudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Faraona a jeho dům však Hospodin zasáhl velikými ranami pro Sáraj, ženu Abramovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Farao si zavolal Abrama a řekl: Cos mi to provedl? Proč jsi mi neoznámil, že je to tvá žena?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Proč jsi řekl: Je to má sestra, takže jsem si ji vzal za ženu? Nuže, zde je tvá žena. Vezmi si ji a jdi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'A farao o něm dal příkaz svým mužům, a poslali pryč jej i jeho ženu se vším, co měl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Tak vystoupil Abram z Egypta se svou ženou i se vším, co měl, do Negebu. Byl s ním i Lot.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram ⌈ měl velké množství⌉ dobytka, stříbra i zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'A postupoval po svých denních pochodech od Negebu až k Bét–elu, až na místo mezi Bét–elem a Ajem, kde byl zprvu jeho stan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'k místu oltáře, který tam na počátku udělal. Tam Abram vzýval Hospodinovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Také Lot, který putoval s Abramem, měl ovce, skot a stany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Ale země ⌈jim nestačila,⌉ aby bydleli spolu, protože jejich majetek byl tak velký, že nemohli bydlet spolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Až nastal spor mezi pastýři dobytka Abramova a pastýři dobytka Lotova. (V zemi tenkrát bydleli Kenaanci a Perizejci.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Abram řekl Lotovi: Ať není svár mezi mnou a tebou a mezi mými pastýři a tvými pastýři, neboť jsme muži bratři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Což před tebou není celá země? Odděl se prosím ode mne: Jestliže půjdeš nalevo, dám se napravo, jestliže napravo, dám se nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Lot ⌈pozvedl oči⌉ a spatřil celou jordánskou rovinu, kudy se chodí do Sóaru, že je celá dobře zavlažovaná -- bylo to dříve, než Hospodin zničil Sodomu a Gomoru -- že je jako Hospodinova zahrada, jako egyptská země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Lot si tedy vybral celou jordánskou rovinu a vyrazil na východ. Tak se jeden od druhého oddělili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram pobýval v kenaanské zemi a Lot pobýval ve městech roviny a ⌈přiblížil své stany až k⌉ Sodomě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Sodomští lidé však byli před Hospodinem velice zlí a hříšní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Poté, co se Lot od něho odloučil, Hospodin Abramovi řekl: Nuže, pozvedni oči a z místa, kde jsi, se podívej ⌈na sever a na jih, na východ i na západ,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'protože celou tu zemi, kterou vidíš, dám tobě a tvému potomstvu až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'A tvého potomstva učiním jako prachu země. Jestliže někdo bude moci spočítat prach země, tak bude spočteno i tvé potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Vstaň a procházej zemí ⌈křížem krážem,⌉ protože ji dám tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Tak Abram ⌈putoval se stany,⌉ přišel, aby pobýval u Mamreho dubů, které jsou v Chebrónu; tam postavil Hospodinu oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Ve dnech šineárského krále Amráfela, elasarského krále Arjóka, élamského krále Kedorlaómera a gójimského krále Tideála se stalo, že');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'vedli válku proti sodomskému králi Bérovi a gomorskému králi Biršovi, ademskému králi Šineábovi, sebójskému králi Šemeberovi a králi Bely, což je Sóar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Tito všichni se spojili v údolí Sidímu, což je Solné moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Dvanáct let sloužili Kedorlaómerovi, ale třináctého roku se vzbouřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Ve čtrnáctém roce přitáhl Kedorlaómer a králové, kteří byli s ním, a pobili Refájce v Aštarót–karnajimu, Zuzejce v Hámu, Emejce v Šáve–kirjatajimu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'a Chorejce v jejich pohoří Seíru až k El–páranu, který je proti pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Když se vraceli, přitáhli k Énmišpátu, což je Kádeš, a pobili vše na poli Amálekovců a také Emorejce, kteří sídlili v Chasesón–támaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Vytáhl tedy král sodomský, král gomorský, král ademský, král sebójský a král Bely, což je Sóar, a sešikovali se proti nim k boji v údolí Sidímu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'proti élamskému králi Kedorlaómerovi, gójimskému králi Tideálovi, šineárskému králi Amráfelovi a elasarskému králi Arjókovi -- čtyři králové proti pěti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Údolí Sidím bylo plné asfaltových studní; když král sodomský a gomorský utíkali, zapadli ⌈do nich.⌉ Ti, co zůstali naživu, utekli do hor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Pak nepřátelé pobrali všechen majetek Sodomy a Gomory i všechnu potravu a odtáhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Vzali také Abramova synovce Lota s jeho majetkem -- bydlel totiž v Sodomě -- a odtáhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Pak přišel jeden uprchlík a oznámil to Hebreji Abramovi. Ten přebýval u dubů Emorejce Mamreho, bratra Eškólova a bratra Anérova; ti byli ⌈ s Abramem spojeni smlouvou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Když Abram uslyšel, že jeho bratr byl vzat do zajetí, shromáždil tři sta osmnáct svých ⌈oddaných mužů⌉ zrozených v jeho domě a pronásledoval nepřátele až k Danu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'V noci proti nim se svými otroky rozdělil své síly a pobíjel je; pronásledoval je až po Chóbu, která je ⌈severně od⌉ Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Donesl zpět všechen majetek, také svého bratra Lota s jeho majetkem přivedl zpět, také ženy a lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Po jeho návratu z pobití Kedorlaómera a králů, kteří byli s ním, vyšel mu vstříc sodomský král do údolí Šáve, což je Královské údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Také Malkísedek, král Šálemu, přinesl chléb a víno. Byl knězem Boha Nejvyššího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'A požehnal mu slovy: Požehnán buď Abram Bohu Nejvyššímu, ⌈Tvůrci nebes i země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'A požehnán buď Bůh Nejvyšší, který vydal tvé protivníky do tvé ruky. Nato mu Abram dal desátek ze všeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Sodomský král Abramovi řekl: Dej mi lidi a majetek si vezmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram však sodomskému králi odpověděl: ⌈Pozvedl jsem ruku⌉ k Hospodinu Bohu Nejvyššímu, Tvůrci nebes a země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'že z ničeho, co je tvé, nevezmu ani šňůru nebo řemínek u sandálů, abys neřekl: Já jsem učinil Abrama bohatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Nechci nic, pouze to, co snědli mládenci, a podíl mužů, kteří šli se mnou: Anér, Eškól a Mamre, ti ať vezmou svůj podíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Po těchto událostech se stalo k Abramovi ve vidění Hospodinovo slovo: Neboj se, Abrame, já jsem tvůj štít, tvá přehojná odměna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Ale Abram řekl: ⌈Panovníku Hospodine,⌉ co mi chceš dát? Vždyť já odcházím bezdětný a ⌈nárok na můj dům bude mít ⌉ damašský Elíezer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Abram ještě řekl: Hle, nedal jsi mi potomka, a tak ⌈bude mým dědicem⌉ ⌈potomek mého domu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'A hle, stalo se k němu Hospodinovo slovo: Ten nebude tvým dědicem, nýbrž ten, kdo vyjde ze tvých beder, bude tvým dědicem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Vyvedl ho ven a řekl: Jen pohleď na nebesa a spočítej hvězdy, budeš–li je moci spočítat. A řekl mu: Tak bude tvé potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'I uvěřil Abram Hospodinu a on mu to počítal za spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'A řekl mu: Já jsem Hospodin, který jsem tě vyvedl z chaldejského Úru, abych ti tuto zemi dal do vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Odpověděl: Panovníku Hospodine, podle čeho poznám, že ji obdržím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'I řekl mu: Vezmi pro mne tříletou jalovici, tříletou kozu, tříletého berana a hrdličku s holoubětem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Vzal tedy pro něho všechna tato zvířata, rozpůlil je a dal jednu jejich část naproti druhé. Ptáky nerozetnul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Dravci se slétali na mrtvoly, ale Abram je odháněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'A když zapadalo slunce, na Abrama padl hluboký spánek, a hle, padala na něho hrůza a veliká temnota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'A Hospodin Abramovi řekl: S jistotou věz, že tvé potomstvo bude cizincem v zemi, která nebude jejich, a budou tam otročit a budou pokořováni čtyři sta let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Avšak národ, kterému budou otročit, budu soudit a potom vyjdou s velikým majetkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'A ty vejdeš ke svým otcům v pokoji; budeš pohřben v dobrém stáří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Až čtvrtá generace se sem navrátí, protože až potud nebude dovršena vina Emorejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Pak zapadlo slunce a nastal soumrak, a hle, kouřící pec a ohnivá pochodeň, která prošla mezi těmi díly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'V onen den Hospodin uzavřel s Abramem smlouvu slovy: Tvému potomstvu dám tuto zemi od egyptské řeky až k té veliké řece, řece Eufratu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Kénijce, Kenazejce a Kadmónce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Chetejce, Perizejce a Refájce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Emorejce, Kenaance, Girgašejce a Jebúsejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sáraj, Abramova žena, mu nerodila. Měla však egyptskou otrokyni jménem Hagar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Sáraj řekla Abramovi: Hle, Hospodin ⌈mi zabránil rodit.⌉ Vejdi prosím k mé otrokyni, snad ⌈budu mít dítě⌉ z ní. Abram Sáraj uposlechl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Abramova žena Sáraj tedy na konci desíti let Abramova pobývání v kenaanské zemi vzala svou otrokyni, Egypťanku Hagar, a dala ji svému muži Abramovi za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Vešel k Hagar a ta otěhotněla. Když viděla, že otěhotněla, ⌈přestala si své paní vážit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Sáraj pak řekla Abramovi: ⌈Ty můžeš za ⌉ mé příkoří! Já jsem ti dala do klína svou otrokyni, a když viděla, že otěhotněla, ⌈přestala si mě vážit.⌉ Ať Hospodin ⌈vykoná soud⌉ mezi mnou a tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram Sáraji odpověděl: Vždyť tvá otrokyně je ve tvé moci, nalož s ní, jak uznáš za správné. Sáraj ji pak pokořovala tak, že od ní Hagar utekla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Hospodinův anděl ji nalezl v pustině u vodního pramene, u pramene na cestě do Šúru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'a řekl: Hagaro, otrokyně Sáraje, odkud jsi přišla a kam jdeš? Odpověděla: Utíkám od své paní Sáraje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Hospodinův anděl jí řekl: Navrať se ke své paní a pokoř se pod její ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'A Hospodinův anděl jí řekl: Velice rozmnožím tvé potomstvo, takže pro množství nebude moci být spočítáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Dále jí Hospodinův anděl řekl: Hle, jsi těhotná a porodíš syna; dáš mu jméno Izmael, protože Hospodin naslouchal tvému soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Bude to člověk jako divoký osel, jeho ruka bude proti všem a ruka všech bude proti němu. Usídlí se naproti všem svým bratřím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Hagar dala Hospodinu, který k ní promluvil, jméno: Ty jsi Bůh vidění. Neboť si řekla: Což jsem zde také nepohlédla za tím, kdo mě uviděl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Proto se ta studna nazývá Bér–lachaj–rói. Ta je mezi Kádešem a Beredem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Pak Hagar porodila Abramovi syna a Abram svého syna, kterého porodila Hagar, pojmenoval Izmael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abramovi bylo osmdesát šest let, když mu Hagar porodila Izmaela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Když bylo Abramovi devadesát devět let, ukázal se mu Hospodin a řekl mu: Já jsem Bůh Všemohoucí. ⌈Choď přede mnou⌉ a buď bezúhonný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ustanovím svou smlouvu mezi sebou a tebou a převelice tě rozmnožím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Tu Abram ⌈padl na tvář⌉ a Bůh s ním dále mluvil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '⌈Já jsem.⌉ Zde je moje smlouva s tebou. Staneš se otcem množství národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Tvé jméno již nebude Abram, ale tvé jméno bude Abraham, protože jsem tě učinil otcem množství národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Převelice tě rozplodím a učiním z tebe národy, i králové z tebe vyjdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Ustanovím svou smlouvu mezi sebou a tebou a tvým potomstvem po tobě ⌈ z generace na generaci⌉ za smlouvu věčnou, abych byl Bohem tvým i tvého potomstva po tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'A tobě a tvému potomstvu po tobě dám zemi, ⌈kde jsi hostem,⌉ celou kenaanskou zemi, do věčného vlastnictví. A budu jejich Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'A Bůh řekl Abrahamovi: A ty zachovávej mou smlouvu, ty i tvé potomstvo po tobě ⌈ z generace na generaci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Toto je má smlouva mezi mnou a vámi a tvým potomstvem po tobě, kterou budete zachovávat: Každý mužského pohlaví mezi vámi musí být obřezán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Obřežte si maso své předkožky a to bude znamením smlouvy mezi mnou a vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, '⌈Po všechny vaše generace⌉ bude ve věku osmi dnů mezi vámi obřezán každý mužského pohlaví, doma zrozený i koupený za stříbro od kteréhokoli cizince, který není z tvého potomstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Musí být obřezán zrozený ve tvém domě stejně jako koupený za tvé stříbro a znamení mé smlouvy na vašem těle bude ⌈ znamením věčné⌉ smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Neobřezaný mužského pohlaví, který nedá obřezat maso své předkožky, takový člověk bude ze svého lidu vyhlazen. Porušil mou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Potom Bůh řekl Abrahamovi: Ohledně tvé ženy Sáraje, nebudeš ⌈ji již nazývat⌉ Sáraj, ale její jméno bude Sára.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Požehnám ji a také z ní ti dám syna. Požehnám ji a ⌈budou z ní národy,⌉ budou z ní králové národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Abraham padl na tvář a smál se. Řekl si v srdci: Cožpak se stoletému může něco narodit? A Sára bude snad v devadesáti letech rodit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'A řekl Bohu: Kéž by Izmael byl živ ⌈před tebou!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Ale Bůh odpověděl: Kdepak, tvá žena Sára ti porodí syna a dáš mu jméno Izák. S ním ustanovím svou smlouvu jako smlouvu věčnou pro jeho potomstvo po něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'A ohledně Izmaela jsem tě vyslyšel. Hle, požehnám ho, rozplodím ho a převelice ho rozmnožím. Zplodí dvanáct knížat a učiním z něj veliký národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Ale svou smlouvu ustanovím s Izákem, kterého ti porodí Sára v příštím roce o tomto čase.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Tu Bůh dokončil rozhovor s Abrahamem a vystoupil od něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Pak Abraham vzal svého syna Izmaela i všechny zrozené ve svém domě i všechny koupené za stříbro, všechny členy Abrahamova domu mužského pohlaví, a obřezal maso jejich předkožky ještě tentýž den tak, jak mu Bůh řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham byl ve věku devadesáti devíti let, když bylo obřezáno maso jeho předkožky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Jeho syn Izmael byl ve věku třinácti let, když bylo obřezáno maso jeho předkožky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Právě tentýž den byl obřezán Abraham i jeho syn Izmael');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'i všichni muži z jeho domu, doma zrození i koupení za stříbro od cizince, byli obřezáni s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'I ukázal se mu Hospodin u Mamreho dubů, když seděl u vchodu do stanu za denního žáru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Když ⌈pozvedl oči⌉ a rozhlédl se, hle, tři muži stáli proti němu. Když je uviděl, běžel jim od vchodu do stanu vstříc, poklonil se až k zemi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'a řekl: Panovníku, jestliže jsem nyní nalezl ve tvých očích milost, nepomíjej prosím svého otroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Nechám přinést trochu vody, abyste si mohli umýt nohy, a odpočiňte si pod stromem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Vezmu trochu jídla, abyste se posilnili. Potom půjdete dál. Vždyť proto procházíte kolem svého otroka! Řekli: Udělej, jak jsi řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham pospíchal do stanu k Sáře a řekl: Rychle zadělej tři míry jemné mouky a udělej podpopelné chleby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'A Abraham běžel k dobytku, vzal jemné a hezké tele a dal ho mládenci, aby ho rychle připravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Potom vzal máslo, mléko a tele, které připravil, a předložil jim to. Zatímco jedli, stál u nich pod stromem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Zeptali se ho: Kdepak je tvá žena Sára? Odpověděl: Zde ve stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Jeden řekl: Jistě se k tobě vrátím ⌈ napřesrok o tomto čase,⌉ a hle, tvá žena Sára bude mít syna. (A Sára poslouchala u vchodu do stanu za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham i Sára byli staří, pokročilého věku. Sáře již přestal běh ženský.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Sára se v nitru zasmála: Poté, co jsem zestárla, se mi dostane rozkoše! I můj pán je už starý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Hospodin řekl Abrahamovi: Proč se to Sára smála a říkala si: Cožpak budu opravdu rodit, když jsem stará?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Je snad nějaká věc pro Hospodina nesnadná? V určený čas se k tobě vrátím, ⌈ napřesrok o tomto čase,⌉ a Sára bude mít syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Ale Sára to zapřela: Nesmála jsem se, protože se bála. On řekl: Kdepak, přece ses smála.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Pak se odtamtud muži zvedli a pohlédli směrem k Sodomě. Abraham šel s nimi, aby je vyprovodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'A Hospodin řekl: Cožpak budu před Abrahamem tajit, co chci udělat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Abraham se jistě stane velikým a mocným národem a budou v něm požehnány všechny národy země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Neboť ⌈jsem se s ním sblížil, takže⌉ přikáže svým synům a svému domu po sobě, aby zachovávali ⌈Hospodinovu cestu⌉ a konali ⌈spravedlnost a právo,⌉ aby Hospodin Abrahamovi naplnil to, co o něm řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'I řekl Hospodin: ⌈Křik proti Sodomě⌉ a Gomoře je tak velký a jejich hřích tak přetěžký,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'že musím sestoupit a podívat se, zdali jednají zcela podle toho křiku, který se ke mně donesl. A jestli ne, zjistím to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Muži se odtamtud obrátili a šli k Sodomě, ale Abraham ještě stál před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Abraham přistoupil a řekl: Cožpak s ničemou vyhladíš i spravedlivého?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Možná je uprostřed toho města padesát spravedlivých. Cožpak ho přece vyhladíš a neodpustíš tomu místu kvůli padesáti spravedlivým, kteří jsou uprostřed něho?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Ať je to od tebe vzdáleno, abys učinil takovou věc, že bys usmrtil spravedlivého s ničemou, takže by na tom spravedlivý byl tak jako ničema. Ať je to od tebe vzdáleno! Cožpak soudce celé země nebude jednat podle práva?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Hospodin odpověděl: Jestliže najdu v Sodomě uprostřed města padesát spravedlivých, odpustím kvůli nim celému tomu místu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham pokračoval a řekl: Hle, dovolím si mluvit k Panovníkovi, ačkoliv jsem prach a popel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Možná, že do padesáti spravedlivých bude chybět pět. Zničíš pro těch pět celé město? Odpověděl: Nezničím, najdu–li tam čtyřicet pět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Ještě dále k němu mluvil slovy: Možná se jich tam najde čtyřicet. Odpověděl: Pro těch čtyřicet to neučiním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Pak řekl: Ať se Panovník nerozzlobí, že ještě mluvím. Možná se jich tam najde třicet. Odpověděl: Neučiním to, najdu–li tam třicet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Nato řekl: Hle, dovolím si mluvit k Panovníkovi. Možná se jich tam najde dvacet. Odpověděl: Nezničím je kvůli těm dvaceti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Potom řekl: Ať se Panovník nerozhněvá, když promluvím ještě jednou. Možná se jich tam najde deset. Odpověděl: Nezničím je kvůli těm deseti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Když dokončil rozhovor s Abrahamem, Hospodin odešel; a Abraham se vrátil do svého domova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Dva andělé přišli večer do Sodomy, když Lot seděl v sodomské bráně. Lot je uviděl, povstal jim vstříc, poklonil se tváří k zemi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'a řekl: Moji páni, zajděte prosím do domu svého otroka a přenocujte a umyjte si nohy. Časně ráno pak půjdete svou cestou. Odpověděli: Nikoli, jenom přenocujeme na náměstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Velmi je nutil, takže zašli k němu a vešli do jeho domu. Připravil jim jídlo, napekl nekvašené chleby a jedli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Dříve nežli ulehli, muži města, muži Sodomy, mládenci i starci, všechen lid bez výjimky, obklíčili dům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'pokřikovali na Lota a říkali mu: Kde jsou ti muži, kteří k tobě v noci přišli? Vyveď je k nám, ať je poznáme!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot k nim vyšel ke vchodu, zavřel za sebou dveře');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'a řekl: Prosím, moji bratři, nepáchejte takové zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Podívejte, mám dvě dcery, které ⌈nepoznaly muže,⌉ nyní vám je vyvedu a učiňte s nimi, co vám bude libo. Jenom nic nedělejte těmto mužům, vždyť proto vešli do stínu mého přístřeší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Odpověděli: Kliď se! A říkali: Sám tu zůstává jako host a troufá si nás soudit! Tak s tebou naložíme hůř než s nimi! A velice tlačili na toho muže, na Lota, a pokoušeli se vylomit dveře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Nato muži zevnitř vztáhli ruce, vtáhli Lota k sobě do domu, zavřeli dveře');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'a muže u vchodu domu ⌈od nejmenšího až do největšího⌉ ranili slepotou, že nedokázali nalézt vchod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Potom muži Lotovi řekli: Koho tu ještě máš? Zetě, syny a dcery i všechny, které máš ve městě, vyveď z tohoto místa!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Neboť zničíme toto místo, protože veliký je před Hospodinem ⌈křik proti němu,⌉ takže nás Hospodin poslal, abychom je zničili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Lot tedy vyšel a mluvil ke svým zeťům, kteří si měli vzít jeho dcery, a říkal: ⌈Vstaňte a ⌉ vyjděte z tohoto místa, protože Hospodin město zničí! Ale jeho ženichům to připadalo, jako by žertoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Když vyšla jitřenka, andělé naléhali na Lota: ⌈Vstaň a ⌉ vezmi svou ženu a obě své dcery, které jsou zde, ať nejsi smeten ⌈za vinu⌉ toho města!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Když váhal, muži z Hospodinova soucitu s ním uchopili jeho ruku, ruku jeho ženy i ruku obou jeho dcer, vyvedli ho a zanechali ho venku za městem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'A když je vyváděli pryč, jeden řekl: Uteč do bezpečí, abys zachránil svou duši. Nehleď zpět a nezastavuj se nikde v rovině. Uteč do hor, ať nejsi smeten.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lot jim odpověděl: Prosím ne, Panovníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Hle, nyní tvůj otrok nalezl milost ve tvých očích a veliké je tvé milosrdenství, které jsi mi prokázal, když jsi zachoval mou duši při životě. Ale já nebudu moci uniknout do hor, aby na mne nedolehla ta zhouba, a zemřel bych.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Jen pohleď na toto město. Je dosti blízko, abych tam utekl, a je nepatrné. Dovol, ať tam uteču do bezpečí! Copak není nepatrné? A má duše zůstane naživu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'I řekl mu: Dobře, ⌈vyhovím ti⌉ i v této věci. Město, o kterém jsi mluvil, nevyvrátím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Rychle tam uteč do bezpečí, protože nemohu nic dělat, dokud tam nevejdeš. Proto se to město jmenuje Sóar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Slunce právě vyšlo nad zemí, když Lot vešel do Sóaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'A Hospodin seslal na Sodomu a na Gomoru déšť ⌈síry a ohně.⌉ Bylo to ⌈od Hospodina⌉ z nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Tak vyvrátil tato města a celou tu rovinu, i všechny obyvatele těch měst, i vše, co rostlo na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Lotova žena pohleděla zpět a stala se solným sloupem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham časně ráno spěchal k místu, kde stál před Hospodinem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'a pohlédl na Sodomu a Gomoru a na celé území té roviny a spatřil, jak ze země vystupuje dým, jako dým z hrnčířské pece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Stalo se však, když Bůh ničil města té roviny, že Bůh pamatoval na Abrahama a poslal Lota ze středu zkázy, když vyvracel města, v nichž Lot pobýval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot vystoupil ze Sóaru a usadil se v horách a s ním jeho dvě dcery. Bál se totiž bydlet v Sóaru. Usadil se tedy v jeskyni, on i jeho dvě dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Tu prvorozená řekla té mladší: Náš otec je starý a v zemi není muž, aby k nám podle způsobu celé země vešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Pojď, dáme otci napít vína a budeme s ním ležet, ať zachováme při životě potomstvo ze svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Daly tedy otci té noci pít víno. Pak vešla prvorozená a ležela se svým otcem. Nepoznal, když ulehla, ani když vstala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Příští den prvorozená řekla té mladší: Hle, včera jsem ležela s otcem. Dáme mu pít víno také tuto noc a vejdi a lež s ním, abychom ze svého otce zachovaly při životě potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Také oné noci daly otci pít víno a ta mladší přišla a ležela s ním. Nepoznal, když ulehla, ani když vstala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Tak obě Lotovy dcery otěhotněly se svým otcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Prvorozená porodila syna a pojmenovala ho Moáb. On je otcem Moábců až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'A ta mladší, ta také porodila syna a pojmenovala ho Ben–amí. On je otcem synů Amónových až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Abraham odtamtud odtáhl do ⌈území Negebu⌉ a pobýval mezi Kádešem a Šúrem. Když pobýval jako cizinec v Geraru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'řekl Abraham o své manželce Sáře: Je to má sestra. A Abímelek, král Geraru, pro Sáru poslal a vzal si ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'K Abímelekovi přišel v noci ve snu Bůh a řekl mu: Hle, zemřeš kvůli ženě, kterou sis vzal. Je provdaná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Ale Abímelek se k ní nepřiblížil a řekl: Panovníku, vybiješ i spravedlivý národ?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Což mi on neřekl: Je to má sestra? A také ona sama řekla: Je to můj bratr. ⌈S bezúhonným srdcem⌉ a v čistotě rukou jsem to udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'A Bůh mu ve snu odpověděl: Já jsem také věděl, žes to udělal s bezúhonným srdcem, a já sám jsem tě zadržel, abys proti mně nezhřešil. Proto jsem tě nenechal se jí dotknout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'A teď navrať ženu toho muže, neboť je to prorok. Bude se za tebe modlit, a budeš žít. Jestliže ji však nenavrátíš, věz, že jistě zemřeš ty i všichni, kdo ti patří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Abímelek časně ráno vstal, svolal všechny své otroky a pověděl jim všechny tyto věci. Ti muži dostali veliký strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Abímelek zavolal Abrahama a řekl mu: Cos nám to provedl? Čím jsem se vůči tobě prohřešil, že jsi na mne a na mé království uvedl tak veliký hřích? Zachoval ses ke mně tak, jak se nejedná!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Abímelek se ještě Abrahama zeptal: Co jsi sledoval tím, žes udělal takovou věc?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham odpověděl: Řekl jsem si, že na tomto místě jistě není ⌈bázeň před Bohem⌉ a že mne kvůli mé ženě zabijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Opravdu je i mou sestrou. Je dcerou mého otce, avšak není dcerou mé matky a stala se mou ženou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Ale když mne Bůh vyvedl z domu mého otce do neznáma, řekl jsem jí: Na každém místě, kamkoli přijdeme, ⌈mi prokaž tu laskavost,⌉ že o mně řekneš: Je to můj bratr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Abímelek vzal tedy brav a skot, otroky a otrokyně a dal je Abrahamovi a navrátil mu jeho ženu Sáru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Pak Abímelek řekl: Hle, má ⌈země je před tebou; usaď⌉ se, kde je ti libo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Sáře pak řekl: Hle, dal jsem tvému bratrovi tisíc šekelů stříbra. To pro tebe bude ⌈potvrzením cti⌉ před všemi, kteří jsou s tebou, takže před všemi jsi ospravedlněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'A Abraham se modlil k Bohu a Bůh uzdravil Abímeleka, jeho ženu i jeho otrokyně, a ⌈ mohly mít děti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Hospodin totiž zcela uzavřel každé lůno v Abímelekově domě kvůli Abrahamově ženě Sáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Hospodin navštívil Sáru, jak řekl, a splnil Sáře to, co prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sára otěhotněla a porodila Abrahamovi v jeho stáří syna v určeném čase, o kterém s ním mluvil Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abraham dal svému synu, který se mu narodil, kterého mu Sára porodila, jméno Izák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Když bylo Izákovi osm dní, Abraham svého syna obřezal, tak jak mu Bůh přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abrahamovi bylo sto let, když se mu narodil syn Izák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Sára řekla: Bůh mi způsobil smích. Každý, kdo o tom uslyší, se bude smát se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Ještě řekla: Kdo by jen pověděl Abrahamovi, že Sára bude kojit! A přece jsem mu v jeho stáří porodila syna!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Dítě rostlo a bylo odstaveno. V den Izákova odstavení udělal Abraham velkou hostinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Když Sára viděla, že se syn Egypťanky Hagary, kterého Abrahamovi porodila, Izákovi posmívá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'řekla Abrahamovi: Vyžeň tuto otrokyni i jejího syna, neboť syn této otrokyně nebude dědicem spolu s mým synem Izákem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, '⌈Abraham byl z toho velmi skleslý:⌉ byla to záležitost jeho syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Bůh však Abrahamovi řekl: Nebuď skleslý kvůli chlapci a své otrokyni. Poslechni Sáru ve všem, co ti říká, protože v Izákovi bude povoláno tvé símě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Syna otrokyně také učiním národem, protože je tvým potomkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Abraham vstal časně ráno, vzal chléb a měch vody a dal to Hagaře. ⌈Položil jí to na ramena a poslal ji s dítětem⌉ pryč. Odešla a bloudila v pustině Beer–šeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Když voda v měchu došla, odložila dítě pod jedno křoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Odešla a posadila se naproti opodál na dostřel luku, neboť si řekla: Nebudu se dívat na smrt toho dítěte. Tak seděla naproti, ⌈pozvedla hlas a plakala.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Bůh uslyšel hlas chlapce. Boží anděl zavolal na Hagaru z nebes a řekl jí: Co je ti, Hagaro? Neboj se, protože Bůh slyšel hlas chlapce tam, kde je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Vstaň, zvedni chlapce a pevně ho drž ⌈ za ruku,⌉ protože z něj učiním velký národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Tu jí Bůh ⌈otevřel oči⌉ a uviděla studnu s vodou. Šla, naplnila měch vodou a dala chlapci napít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Bůh byl s chlapcem, když vyrůstal. Usadil se v pustině a stal se velkým lukostřelcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Bydlel v Páranské pustině a matka mu vybrala ženu z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'V té době řekl Abímelek a Píkol, velitel jeho armády, Abrahamovi: ⌈Bůh je s tebou⌉ ve všem, co děláš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Nyní mi tu přísahej při Bohu, že ⌈si budeš počínat věrně⌉ vůči mně a vůči mému nástupci i mému následníku; tak jako jsem prokázal laskavost tobě, budeš ji prokazovat i mně a zemi, v níž jsi pobýval jako cizinec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'A Abraham řekl: ⌈Ano, přísahám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Abraham však Abímeleka pokáral ohledně studny s vodou, kterou uchvátili Abímelekovi otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abímelek odpověděl: Nevím, kdo tu věc udělal. Ani ty jsi mi to neoznámil a ani já jsem o tom dodnes neslyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Abraham tedy vzal brav a skot, dal to Abímelekovi a uzavřeli spolu smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Abraham postavil sedm oveček ze stáda zvlášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Abímelek se Abrahama zeptal: Co s těmi sedmi ovečkami, které jsi postavil zvlášť?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'On odpověděl: Těch sedm oveček si ode mne vezmi, aby mi byly na svědectví, že tuto studnu jsem vyhloubil já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Proto nazval ono místo Beer–šeba, protože tam oba přísahali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Tak uzavřeli smlouvu v Beer–šebě. Abímelek s velitelem své armády Píkolem vstali a navrátili se do pelištejské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham pak vysadil v Beer–šebě tamaryšek a vzýval tam jméno Hospodina, Boha věčného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Abraham pobýval v pelištejské zemi jako cizinec po mnohé dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Po těch událostech se stalo, že Bůh Abrahama zkoušel. Řekl mu: Abrahame! On odpověděl: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Bůh řekl: Nuže, vezmi svého syna, svého jediného, jehož miluješ, Izáka, a jdi do země Mórija. Tam ho obětuj jako zápalnou oběť na jedné z hor, o níž ti povím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Abraham vstal časně ráno, osedlal osla, vzal s sebou dva své služebníky a svého syna Izáka, naštípal dříví k zápalné oběti a ⌈vydal se⌉ k místu, o kterém mu řekl Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Třetího dne, když Abraham pozvedl oči, uviděl v dáli to místo');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'a řekl svým služebníkům: Zůstaňte tady s oslem a já s chlapcem půjdeme až tam. Pokloníme se Bohu a vrátíme se k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Potom vzal Abraham dříví k zápalné oběti a naložil je na svého syna Izáka. Vzal s sebou také oheň a nůž. A šli oba spolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Tu Izák řekl svému otci Abrahamovi: Otče? Abraham řekl: Tady jsem, synu. Izák řekl: Zde je oheň a dříví, ale kde je beránek k zápalné oběti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham odpověděl: Bůh si opatří beránka k zápalné oběti, můj synu. A šli oba spolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Když přišli na místo, o kterém mu řekl Bůh, Abraham tam postavil oltář, připravil dříví, svázal svého syna Izáka a položil ho na oltář na dříví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Pak vztáhl ruku a vzal nůž, aby zabil svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Vtom na něho zavolal Hospodinův anděl z nebes: Abrahame, Abrahame! Odpověděl: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'I řekl: Nevztahuj ruku na chlapce a nic mu nedělej, protože teď jsem poznal, že jsi bohabojný a že jsi mi neodepřel svého syna, svého jediného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Abraham pozvedl oči a uviděl, že se jeden beran zachytil za rohy v houštině. Šel, vzal toho berana a obětoval ho v zápalnou oběť místo svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'A Abraham pojmenoval ono místo: Hospodin opatří. Odtud se dodnes říká: Na hoře ⌈Hospodinově se opatří.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Hospodinův anděl zavolal z nebes na Abrahama podruhé');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'a řekl: Při sobě jsem přísahal, je ⌈Hospodinův výrok:⌉ Protože jsi učinil tuto věc a neodepřel jsi mi svého jediného syna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'proto tě jistě požehnám a tvé símě velice rozmnožím jako nebeské hvězdy a jako písek na mořském břehu. Tvé símě zdědí bránu svých nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Ve tvém semeni ⌈si budou žehnat všechny národy⌉ země, protože jsi mne uposlechl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Pak se Abraham navrátil ke svým služebníkům a vydali se společně do Beer–šeby. A Abraham bydlel v Beer–šebě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Po těchto událostech bylo Abrahamovi oznámeno: Hle, také Milka porodila tvému bratru Náchorovi syny:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Prvorozeného Úsa, jeho bratra Búza a Kemúela, otce Aramova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Keseda, Chazóa, Pildáše, Jidláfa a Betúela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Betúel pak zplodil Rebeku. Těchto osm porodila Milka Abrahamovu bratru Náchorovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'A jeho konkubína jménem Reúma také porodila: Tabecha, Gachama, Tachaše a Maaku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, '⌈Sára byla živa⌉ sto dvacet sedm let; to byla léta života Sáry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Sára zemřela v Kirjat–arbě, což je Chebrón v kenaanské zemi, a Abraham přišel, aby pro Sáru naříkal a oplakával ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Pak od své zemřelé vstal a promluvil k Chetejcům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Jsem u vás cizinec a příchozí. Prodejte mi u sebe do vlastnictví hrob, abych pohřbil svou zemřelou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Chetejci Abrahamovi odpověděli:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Slyš nás, pane: Jsi uprostřed nás kníže Boží! Pohřbi svou zemřelou v nejlepším z našich hrobů. Nikdo z nás ti neodepře svůj hrob, abys tam mohl pohřbít svou zemřelou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Tu Abraham vstal a poklonil se lidu té země, Chetejcům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'a promluvil k nim: Jestliže to je vaším přáním, abych tu pohřbil svou zemřelou, vyslyšte mne a zasaďte se za mne u Efróna, syna Sócharova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'aby mi prodal svou jeskyni v Makpele, která je na konci jeho pole. Ať mi ji prodá za plnou cenu do vlastnictví mezi vámi jako hrob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, '(Efrón však seděl mezi Chetejci.) Efrón chetejský Abrahamovi před Chetejci, před všemi, kdo vcházejí do brány jeho města, odpověděl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nikoli, pane, vyslechni mne. Prodám ti to pole a prodám ti i jeskyni, která je na něm. Před očima synů svého lidu ti ji prodám, pohřbi svou zemřelou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Abraham se poklonil před lidem té země');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'a promluvil k Efrónovi před lidem té země: ⌈Kdybys tak vyslechl ty mě!⌉ Zaplatím ti cenu toho pole. Přijmi to ode mne, abych tam mohl pohřbít svou zemřelou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Efrón Abrahamovi odpověděl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Vyslechni mě, pane. Pozemek je za čtyři sta šekelů stříbra. Co je to pro tebe a pro mě? Pohřbi tam svou zemřelou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham Efróna uposlechl a odvážil ⌈mu cenu,⌉ již vyslovil před Chetejci: Čtyři sta šekelů stříbra podle obvyklé obchodní váhy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Tak Efrónovo pole v Makpele proti Mamre -- pole s jeskyní, která je na něm, i všechno stromoví, které je na poli na celém jeho pomezí okolo -- připadlo');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'do Abrahamova majetku před zraky Chetejců, všech, kdo vcházejí do brány města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Potom Abraham svou ženu Sáru pohřbil v jeskyni na poli v Makpele naproti Mamre -- to je Chebrón -- v kenaanské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Tak připadlo to pole s jeskyní na něm od Chetejců Abrahamovi do vlastnictví jako hrob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham byl již starý, pokročilého věku a Hospodin mu ve všem požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'I řekl Abraham svému otroku, nejstaršímu svého domu, který vládl vším, co mu patřilo: Vlož teď ruku pod má bedra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Zapřísahám tě při Hospodinu, Bohu nebes i Bohu země, že nevybereš ženu pro mého syna z dcer Kenaanců, uprostřed nichž bydlím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'ale půjdeš do mé rodné země a k mému příbuzenstvu a vybereš ženu pro mého syna Izáka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Ten otrok mu řekl: Možná mne ta žena nebude chtít do této země následovat. Určitě mám přivést zpět tvého syna do země, odkud jsi vyšel?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham mu řekl: Měj se na pozoru, abys tam mého syna nepřivedl nazpět!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, '⌈Hospodin, Bůh nebes,⌉ který mne vzal z domu mého otce a z ⌈mé rodné země⌉ a který ke mně promluvil a přísahal mi: Tvému potomstvu dám tuto zemi, on před tebou pošle svého anděla, a tak odtamtud vezmeš ženu pro mého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'A kdyby tě ta žena nechtěla následovat, budeš této mé přísahy zproštěn. Jenom tam mého syna nevoď zpátky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Ten otrok tedy vložil ruku pod bedra svého pána Abrahama a tu věc mu odpřisáhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Pak ten otrok vzal z velbloudů svého pána deset kusů a odešel, s sebou měl všelijaké ⌈vzácné dary⌉ svého pána. Vydal se do ⌈Aramského Dvojříčí,⌉ do města Náchorova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Navečer, v době, kdy ženy vycházely čerpat vodu, nechal odpočinout velbloudy venku za městem u studny s vodou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'a řekl: Hospodine, Bože mého pána Abrahama, způsob to dnes prosím při mně a prokaž milosrdenství mému pánu Abrahamovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Stojím zde u pramene vody a dcery mužů toho města vycházejí čerpat vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Ať dívka, jíž řeknu: Nakloň prosím džbán, abych se napil, a ona odpoví: Napij se a také tvé velbloudy napojím, ⌈je ta, kterou ⌉ jsi určil pro svého otroka Izáka. Podle toho poznám, že jsi mému pánu prokázal milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Ještě nedomluvil, když tu vycházela Rebeka, která se narodila Betúelovi, synu Milky, ženy Abrahamova bratra Náchora, a na rameni měla džbán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Ta dívka byla velmi hezkého vzhledu, panna, muž ji dosud nepoznal. Sestoupila k prameni, naplnila džbán a vystoupila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Otrok jí vyběhl naproti a řekl: Dej mi prosím napít ⌈trochu vody⌉ ze džbánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Odpověděla: Napij se, můj pane. A rychle sundala džbán na ruku a dala mu napít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Když se napil, řekla: Načerpám i tvým velbloudům, dokud se nenapijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'A rychle vylila džbán do žlabu a běhala stále znovu ke studni čerpat, dokud ne načerpala pro všechny jeho velbloudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Muž na ni mlčky pozorně hleděl, aby poznal, zda Hospodin dopřeje jeho cestě úspěch, či nikoli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Když přestali velbloudi pít, vzal muž zlatý nosní kroužek o váze ⌈půl šekelu⌉ a pro její ruce dva náramky o váze deseti šekelů zlata');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'a zeptal se: Čí jsi dcera? Pověz mi prosím, je–li v domě tvého otce pro nás místo k přenocování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Odpověděla mu: Jsem dcera Betúela, syna Milky, kterého porodila Náchorovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'A pokračovala: Slámy i krmiva je u nás mnoho a také místo k přenocování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Muž poklekl, klaněl se Hospodinu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'a řekl: Požehnán buď Hospodin, Bůh mého pána Abrahama, který od mého pána ⌈neodňal své milosrdenství⌉ a věrnost. Vždyť mě Hospodin na cestě vedl přímo do domu bratrů mého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'A dívka běžela a oznámila tyto věci v domě své matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebeka měla bratra jménem Lában. Lában běžel ven k prameni za tím mužem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Když totiž viděl nosní kroužek a náramky na rukou své sestry a slyšel slova své sestry Rebeky: Toto mi ten muž říkal ..., tedy šel za tím mužem. A hle, on stál při velbloudech u pramene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Řekl mu: Pojď, požehnaný Hospodinův! Proč bys stál venku? Připravil jsem dům i místo pro velbloudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Muž vešel do domu a odstrojil velbloudy. Pak dal Lában velbloudům slámu a krmivo a dal také vodu k umytí nohou jeho i nohou mužů, kteří byli s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Když před něj prostřeli, aby pojedl, řekl: Nebudu jíst, dokud nepromluvím o svých záležitostech. Řekl: Mluv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Řekl tedy: Jsem Abrahamův otrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Hospodin mému pánu velmi požehnal, takže je bohatý. Dal mu brav a skot, stříbro a zlato, otroky a otrokyně, velbloudy a osly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Žena mého pána Sára porodila mému pánu ve svém stáří syna. Jemu dal všechno, co má.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Můj pán mne zapřisáhl slovy: Nevybereš ženu pro mého syna z dcer Kenaanců, v jejichž zemi bydlím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'nýbrž půjdeš do domu mého otce, k mé rodině a tam vybereš ženu pro mého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Řekl jsem svému pánu: Možná mne ta žena nebude následovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Odpověděl mi: Hospodin, před nímž chodím, pošle s tebou svého anděla a dopřeje tvé cestě úspěch. A ty vybereš pro mého syna ženu z mé rodiny a z domu mého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Jen tehdy budeš zproštěn mé přísahy, když přijdeš k mé rodině a jestliže ti ji nedají, budeš mé přísahy zproštěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Když jsem dnes přišel k tomu prameni, řekl jsem: Hospodine, Bože mého pána Abrahama, jestliže opravdu dopřáváš úspěch mé cestě, na které se nacházím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'hle, stojím tu u pramene vody. Ať dívka, která vyjde čerpat vodu a které řeknu: Dej mi prosím napít trochu vody ze džbánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'a ona mi odpoví: Napij se ty a také pro tvé velbloudy načerpám, to ať je žena, kterou Hospodin určil pro syna mého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Ještě jsem v srdci nedomluvil, když tu vycházela Rebeka a na rameni měla džbán. Sestoupila k prameni a nabrala vodu. Řekl jsem jí: Dej mi prosím napít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Rychle sundala džbán a řekla: Napij se a také tvé velbloudy napojím. Napil jsem se a napojila i velbloudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Zeptal jsem se jí: Čí jsi dcera? Odpověděla: Dcera Betúela, syna Náchorova, kterého mu porodila Milka. Pak jsem jí dal kroužek na nos a náramky na ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'A poklekl jsem a klaněl jsem se Hospodinu. Dobrořečil jsem Hospodinu, Bohu mého pána Abrahama, že mě vedl po pravé cestě, abych přivedl dceru bratra mého pána pro jeho syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'A nyní mi oznamte, chcete–li mému pánu prokázat milosrdenství a věrnost; jestli ne, oznamte mi to také, abych se obrátil napravo nebo nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Lában i Betúel odpověděli: Ta věc vyšla od Hospodina. Nemůžeme ti říct ⌈ani ano ani ne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Hle, Rebeka je ⌈před tebou.⌉ Vezmi ji a jdi, ať se stane ženou syna tvého pána, tak jak řekl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Když Abrahamův otrok uslyšel jejich slova, poklonil se před Hospodinem až k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Pak otrok vyňal stříbrné a zlaté předměty a šaty a dal je Rebece, také dal ⌈vzácné dary⌉ jejímu bratrovi a její matce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'A jedli a pili on i muži, kteří byli s ním, a přenocovali. Když ráno vstali, řekl: Propusťte mne k mému pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Její bratr a matka však odpověděli: Ať s námi děvče zůstane pár dnů, řekněme deset, a potom půjde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Ale on jim řekl: Nezdržujte mě, když Hospodin dopřál mé cestě úspěch. Propusťte mě, abych mohl jít ke svému pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Řekli: Zavoláme dívku a zeptáme se jí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Zavolali tedy Rebeku a zeptali se jí: Půjdeš s tímto mužem? Odpověděla: Půjdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Propustili tedy svou sestru Rebeku a její chůvu, i Abrahamova otroka a jeho muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Požehnali Rebece a říkali jí: Naše sestro, ať z tebe vzejdou ⌈tisíce desetitisíců⌉ a tvé potomstvo ať obsadí bránu svých nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Pak Rebeka i její služky vstaly, nasedly na velbloudy a následovaly toho muže. Tak ⌈vybral Abrahamův otrok⌉ Rebeku a šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Izák přišel z Bér–lachaj–rói, bydlel totiž na území Negebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Když se schylovalo k večeru, Izák se šel procházet po poli. Pozvedl oči a tu spatřil přicházející velbloudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'I Rebeka pozvedla oči a uviděla Izáka. Seskočila z velblouda');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'a zeptala se otroka: Kdo je tamten muž, který nám jde po poli vstříc? Otrok odpověděl: To je můj pán. Vzala tedy závoj a zahalila se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Otrok pak vypravoval Izákovi všechny věci, které vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Izák uvedl Rebeku do stanu své matky Sáry a vzal si ji. Stala se jeho ženou a Izák si ji zamiloval. Tak po smrti své matky došel útěchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham si pak znovu vzal ženu; jmenovala se Ketúra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'A porodila mu Zimrána a Jokšána, Medána a Midjána, Jišbaka a Šúacha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jokšán zplodil Šebu a Dedána. Synové Dedánovi byli Ašúrejci, Letúšejci a Leumejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Synové Midjánovi byli Éfa a Éfer, Chanók, Abída a Eldáa. Tito všichni byli synové Ketúry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Abraham dal Izákovi všechno, co měl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'A synům konkubín, které měl, dal Abraham dary a ještě za svého života je poslal od svého syna Izáka na východ do východní země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Toto jsou léta Abrahamova života, jichž se dožil: sto sedmdesát pět let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'A dokonal Abraham a zemřel v utěšených šedinách, starý, sytý dnů, a byl připojen ke svému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Jeho synové Izák a Izmael ho pohřbili v jeskyni Makpele na poli Chetejce Efróna, syna Sócharova, která je naproti Mamre.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'To pole koupil Abraham od Chetejců. Je tam pohřben Abraham i jeho žena Sára.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Po Abrahamově smrti Bůh požehnal jeho synu Izákovi. Izák sídlil u Bér–lachaj–rói.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Toto je rodopis Abrahamova syna Izmaela, kterého Abrahamovi porodila Egypťanka Hagar, otrokyně Sáry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'A toto jsou jména Izmaelových synů, jmenovitě podle jejich rodopisů: Prvorozený Izmaelův Nebajót, Kédar, Adbeel, Mibsám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Mišma, Dúma a Masa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Chadad a Téma, Jetúr, Náfiš a Kedma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Toto jsou Izmaelovi synové a toto jejich jména podle jejich dvorců a podle jejich hradišť, dvanáct knížat jejich kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'A toto jsou léta Izmaelova života: sto třicet sedm let. I dokonal a zemřel a byl připojen ke svému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Jeho potomci se usídlili od ⌈Chavíly až po Šúr,⌉ který je naproti Egyptu, ⌈ kudy se chodí⌉ do Ašúru -- usídlil se naproti všem svým bratřím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Toto je rodopis Abrahamova syna Izáka: Abraham zplodil Izáka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Izákovi bylo čtyřicet let, když si vzal za ženu Rebeku, dceru Aramejce Betúela z Paddan–aramu, sestru Aramejce Lábana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Izák ⌈naléhavě prosil⌉ Hospodina za svou ženu, protože byla neplodná. Hospodin se dal pohnout jeho prosbami a jeho žena Rebeka otěhotněla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Ale děti se v jejím nitru kopaly. Řekla si tedy: Je –li tomu tak, k čemu ⌈mi to je?⌉ A šla se dotázat Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Hospodin jí řekl: Dva národy jsou ve tvém nitru, dvojí lid z tvého lůna se navzájem oddělí. Jeden lid bude silnější než lid druhý a ⌈starší bude sloužit mladšímu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Když se jí naplnily dny ku porodu, hle, v jejím lůnu byla dvojčata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'První vyšel celý ryšavý, chlupatý jako kožich. Dali mu jméno Ezau.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Potom vyšel jeho bratr a rukou držel Ezaua za patu. Dali mu jméno Jákob. Když se narodili, bylo Izákovi šedesát let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Když mládenci vyrostli, stal se Ezau mužem znalým lovu, mužem divočiny, kdežto Jákob mužem mírným, bydlícím ve stanech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Izák ⌈měl rád⌉ Ezaua, protože ⌈ rád jídal⌉ zvěřinu, zatímco Rebeka milovala Jákoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Jednou Jákob uvařil jídlo, když vtom přišel Ezau z pole a byl vyčerpaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Ezau Jákobovi řekl: Dej mi teď zhltnout trochu toho rudého, zde toho rudého, neboť jsem vyčerpaný. Proto ho pojmenovali Edóm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Ale Jákob řekl: Prodej mi teď své prvorozenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Ezau odpověděl: Hle, já se blížím k smrti, k čemu mi je prvorozenství?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jákob řekl: Přísahej mi teď. I přísahal mu a prodal své prvorozenství Jákobovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Jákob tedy dal Ezauovi chléb a jídlo z čočky. Ten pojedl, napil se, vstal a šel. Tak Ezau pohrdl prvorozenstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Pak nastal v zemi hlad -- jiný než ten první hlad, který byl za dnů Abrahamových -- a Izák šel k pelištejskému králi Abímelekovi do Geraru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Tehdy se mu ukázal Hospodin a řekl: Nesestupuj do Egypta. Přebývej v zemi, kterou ti určím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Pobývej v této zemi jako cizinec. Budu s tebou a požehnám ti. Neboť tobě a tvému potomstvu dám všechny tyto země a naplním přísahu, kterou jsem přísahal tvému otci Abrahamovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Rozmnožím tvé potomstvo jako nebeské hvězdy a dám tvému semeni všechny tyto země. Ve tvém semeni ⌈si budou žehnat všechny národy⌉ země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'protože mne Abraham uposlechl a zachovával, co jsem mu uložil, ⌈mé příkazy, má ustanovení⌉ a mé zákony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Tak se Izák usadil v Geraru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Když se místní muži vyptávali na jeho ženu, říkal: Je to má sestra, protože se bál říci: Moje žena, neboť si myslel: Aby mne místní muži kvůli Rebece nezabili, protože byla hezkého vzhledu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Jednou, když už tam byli dlouhou dobu, vyhlédl pelištejský král Abímelek z okna a uviděl, hle, Izák se svou ženou Rebekou laškuje!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Abímelek si zavolal Izáka a řekl: Hle, je to jistě tvá žena. Jak to, žes říkal: Je to má sestra? Izák mu odpověděl: Protože jsem si říkal: Jen abych kvůli ní nezemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abímelek řekl: Cos nám to udělal? Málem někdo z lidu spal s tvou ženou a uvedl bys na nás vinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Abímelek tedy přikázal všemu lidu: Ten, kdo by se dotkl tohoto muže nebo jeho ženy, bude jistě usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Izák v té zemi zasel a sklidil onen rok stonásobně. Hospodin mu požehnal');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'a on se vzmáhal a stále bohatl, až byl velmi bohatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Měl stáda bravu a skotu a mnoho čeledi a Pelištejci mu záviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'A všechny studny, které vykopali otroci jeho otce za dnů jeho otce Abrahama, Pelištejci ucpali a naplnili hlínou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Pak Abímelek řekl Izákovi: Odejdi od nás, protože ses stal mnohem mocnější než my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Izák odtamtud odešel, utábořil se v Gerarském údolí a usídlil se tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Potom Izák znovu vykopal vodní studny, které vykopali za dnů jeho otce Abrahama a které po Abrahamově smrti Pelištejci ucpali. Dal jim stejná jména, jaká jim dal jeho otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Když Izákovi otroci kopali v tom údolí, našli tam studnu pramenité vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Gerarští pastýři se přeli s Izákovými pastýři: Ta voda je naše! Proto Izák dal té studni jméno Esek, protože se s ním hádali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Vykopali tedy další studnu, ale přeli se i o ni. Proto ji nazval Sitná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Pak táhl odtud dále, vykopal další studnu a o ni se nepřeli. Nazval ji Rechobót a řekl: Vždyť teď nám Hospodin rozšířil prostor, abychom se rozplodili na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Odtud vystoupil do Beer–šeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Té noci se mu ukázal Hospodin a řekl: Já jsem Bůh tvého otce Abrahama. Neboj se, protože já jsem s tebou a požehnám ti a rozmnožím tvé potomstvo kvůli svému otroku Abrahamovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Izák tam vybudoval oltář a vzýval Hospodinovo jméno. Postavil tam svůj stan a jeho otroci tam vykopali studnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Tu k němu přišel Abímelek z Geraru se svým přítelem Achuzatem a s Píkolem, velitelem své armády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Izák se jich zeptal: Proč jste ke mně přišli? Vždyť jste mě nenáviděli a poslali jste mě od sebe pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Odpověděli: Jasně jsme uviděli, že Hospodin je s tebou, a řekli jsme si, ať je mezi námi přísaha, mezi námi a tebou. Uzavřeme s tebou smlouvu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, '⌈že nám neučiníš nic ⌉ zlého, tak jako jsme se nedotkli tebe a tak jako jsme ti prokazovali jen dobro a propustili jsme tě v pokoji. Ty jsi nyní požehnaný Hospodinův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'I připravil jim hostinu; a jedli a pili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Časně ráno vstali, přísahali jeden druhému a Izák je propustil. Odešli od něho v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Toho dne přišli Izákovi otroci a pověděli mu o studni, kterou kopali. Řekli mu: Našli jsme vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Nazval ji tedy Šibea. Proto je jméno toho města Beer–šeba až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Když bylo Ezauovi čtyřicet let, vzal si za ženu Jehúditu, dceru Chetejce Beera, a Basematu, dceru Chetejce Elóna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Ty byly pro Izáka a Rebeku ⌈hořkým trápením.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Když Izák zestárl a zeslábl mu zrak, takže neviděl, stalo se, že zavolal svého staršího syna Ezaua a řekl mu: Můj synu. Odpověděl mu: Zde jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'A řekl: Hle, jsem starý a neznám den své smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Nuže nyní vezmi svou výstroj, toulec a luk, vyjdi na pole a ulov mi nějakou zvěřinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Pak mi připrav lahůdku, jakou miluji, a přines mi ji k jídlu, abych ti požehnal, dříve než zemřu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebeka však poslouchala, když Izák mluvil se svým synem Ezauem. Ezau odešel na pole, aby ulovil zvěřinu, kterou by přinesl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'a Rebeka řekla svému synu Jákobovi: Zrovna jsem poslouchala tvého otce, když mluvil s tvým bratrem Ezauem a říkal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Přines mi zvěřinu a připrav mi k jídlu lahůdku, abych ti před Hospodinem požehnal, dříve než zemřu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Nyní synu, uposlechni mne v tom, co ti přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Běž teď ke stádu, přines mi odtamtud dvě pěkná kůzlata a já z nich tvému otci připravím lahůdku, jakou miluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Pak ji odneseš otci k jídlu, aby ti požehnal, dříve než zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jákob své matce Rebece odpověděl: Jenže můj bratr Ezau je chlupatý člověk a já hladký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Třeba si na mne otec sáhne a budu mu připadat jako posměvač; pak na sebe uvedu prokletí, a ne požehnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Matka mu řekla: Tvé prokletí ať padne na mě, synu. Jen mne poslechni a jdi mi je přinést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Tak šel, vzal je a přinesl své matce. Matka připravila lahůdku, jakou jeho otec miloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Rebeka pak vzala šaty svého staršího syna Ezaua, nejdražší, jaké měla doma, a oblékla je svému mladšímu synu Jákobovi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'a kůže z kůzlat mu připevnila na ruce a na hladký krk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Pak dala připravenou lahůdku a chléb do rukou svého syna Jákoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'On vstoupil ke svému otci a řekl: Otče. Odpověděl: Zde jsem. Který jsi, můj synu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'A Jákob řekl svému otci: Já jsem Ezau, tvůj prvorozený. Udělal jsem, jak jsi mi řekl. Teď vstaň, posaď se a pojez z mé zvěřiny, abys mi požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Izák však svému synu řekl: Co to, žes tak rychle něco našel, synu? Jákob odpověděl: Protože mi to dopřál Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Izák řekl Jákobovi: Pojď přece blíž, ať na tebe synu sáhnu, jsi–li ty můj syn Ezau nebo ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Tedy Jákob přistoupil ke svému otci Izákovi, ten na něho sáhl a řekl: Ten hlas je hlas Jákobův, ale ruce jsou ruce Ezauovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Nepoznal ho, protože jeho ruce byly chlupaté jako ruce jeho bratra Ezaua, a požehnal mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Ještě se zeptal: Ty jsi skutečně můj syn Ezau? Odpověděl: Jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'I řekl: Předlož mi to, ať pojím z úlovku svého syna, abych ti požehnal. Předložil mu to a on jedl a přinesl mu víno a on pil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Potom mu jeho otec Izák řekl: Nuže přistup, synu, a polib mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'I přistoupil a políbil ho. Izák ucítil vůni jeho šatů a požehnal mu slovy: Hle, vůně mého syna je jako vůně pole, které požehnal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Bůh ti dá z rosy nebes i ze žírnosti země, také hojnost obilí a nového vína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, '⌈Národy ti budou sloužit a lidé se ti budou klanět, staň se pánem svým bratrům a budou se ti klanět synové⌉ tvé matky. Ti, kteří tě proklínají, jsou prokletí a ti, kteří ti žehnají, jsou požehnaní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Jakmile Izák Jákobovi přestal žehnat, jen co Jákob odešel od svého otce Izáka, stalo se, že jeho bratr Ezau přišel z lovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'A také on připravil lahůdku, přinesl svému otci a řekl mu: Kéž můj otec vstane a pojí z úlovku svého syna, abys mi požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Jeho otec Izák mu řekl: Kdo jsi? Odpověděl: Já jsem tvůj syn Ezau, tvůj prvorozený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Izák ⌈se strašně roztřásl⌉ a řekl: Kdo to tedy byl, kdo ulovil zvěřinu a přinesl mi? Pojedl jsem ze všeho dříve, než jsi přišel, a požehnal jsem mu. A bude požehnaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Když Ezau uslyšel slova svého otce, dal se do hrozného a hořkého křiku a řekl svému otci: Požehnej mně, také mně, otče!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'On odpověděl: Tvůj bratr lstivě přišel a zmocnil se tvého požehnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Ezau řekl: Ne nadarmo má jméno Jákob, vždyť mě již dvakrát podrazil! Zmocnil se mého prvorozenství, a hle, teď se zmocnil mého požehnání! A zeptal se: Copak jsi už pro mne nezachoval požehnání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Izák Ezauovi odpověděl: Hle, ustanovil jsem ho tvým pánem. Všechny jeho bratry jsem mu dal za otroky. I obilím a novým vínem jsem ho zaopatřil. Co tedy mám učinit pro tebe, můj synu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Ezau řekl svému otci: Cožpak máš jen to jedno požehnání, otče? Požehnej mně, také mně, otče! A Ezau ⌈pozvedl hlas a rozplakal se.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Jeho otec Izák mu pak odpověděl: Hle, tvé sídlo bude bez žírnosti země a bez nebeské rosy shůry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Budeš živ ze svého meče, ale svému bratru budeš sloužit. Když se budeš toulat, strhneš jeho jho ze své šíje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Pro to požehnání, kterým mu otec požehnal, Ezau na Jákoba zanevřel. Ezau si pro sebe řekl: Blíží se dny smutku pro mého otce, pak zabiji svého bratra Jákoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Rebece byla oznámena slova jejího staršího syna Ezaua. ⌈Dala si zavolat⌉ svého mladšího syna Jákoba a řekla mu: Hle, tvůj bratr Ezau ⌈ti chystá pomstu a chce tě zabít.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Nuže, synu, poslechni mě a vstaň, uteč k mému bratru Lábanovi do Cháranu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'a zůstaň u něj nějakou dobu, dokud neustoupí hněv tvého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Až se hněv tvého bratra od tebe odvrátí a zapomene, co jsi mu provedl, pošlu pro tebe a vezmu tě odtamtud. Proč bych měla ztratit vás oba v jediném dni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Potom Rebeka řekla Izákovi: Jsem znechucená životem kvůli Chetejkám. Jestli si Jákob vezme ženu z dcer této země, Chetejku jako jsou tyto, nač je mi život?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Izák si pak zavolal Jákoba, požehnal mu a přikázal mu: Neber si ženu z dcer kenaanských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Hned odejdi do Paddan–aramu do domu Betúela, otce tvé matky, a odtamtud si vyber ženu, z dcer Lábana, bratra tvé matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'A Bůh Všemohoucí tě požehná, rozplodí tě a rozmnoží, a staneš se shromážděním národů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, '⌈a dá ti⌉ požehnání Abrahamovo, tobě i tvému potomstvu s tebou, abys získal do vlastnictví zemi ⌈svého putování,⌉ kterou Bůh dal Abrahamovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Izák pak Jákoba propustil a on odešel do Paddan–aramu k Lábanovi, synu Aramejce Betúela, bratra Jákobovy a Ezauovy matky Rebeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Ezau viděl, že Izák Jákobovi požehnal a poslal ho do Paddan–aramu, aby si tam vzal ženu. Když mu žehnal, přikázal mu: Neber si ženu z dcer kenaanských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'A viděl, že Jákob otce a matku poslechl a odešel do Paddan–aramu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Ezau také viděl, že dcery kenaanské ⌈se jeho otci Izákovi nelíbí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Ezau tedy šel k Izmaelovi a přibral si ke svým ženám za manželku Machalatu, dceru Abrahamova syna Izmaela, sestru Nebajótovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jákob odešel z Beer–šeby a šel do Cháranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Dorazil na jedno místo a přenocoval tam, protože slunce zapadlo. Vzal na tom místě nějaký kámen, dal si ho pod hlavu a na tom místě ulehl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'A měl sen: Hle, na zemi stál žebřík, jehož vrchol dosahoval do nebes. A hle, po něm vystupovali a sestupovali Boží andělé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Vtom nad ním stál Hospodin a řekl: Já jsem Hospodin, Bůh tvého otce Abrahama a Bůh Izákův. Zemi, na níž ležíš, dám tobě a tvému potomstvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Tvého potomstva bude jako prachu země. Rozhojníš se na západ i na východ, na sever i na jih. V tobě a v tvém semeni budou požehnány všechny čeledi země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'A hle, já jsem s tebou. Budu tě chránit, kamkoli půjdeš, a přivedu tě zpět do této země, protože tě neopustím, dokud nevykonám to, co jsem ti řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Když se Jákob probral ze spánku, řekl: Jistě je na tomto místě Hospodin a já jsem to nevěděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Bál se a řekl: ⌈Jak hrozné je ⌉ toto místo! Cožpak to není dům Boží? Není to nebeská brána?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Jákob vstal časně ráno, vzal kámen, který si dal pod hlavu, a postavil ho jako posvátný sloup. Na jeho vrchol vylil olej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'A pojmenoval to místo Bét–el. Původně se však to město jmenovalo Lúz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Potom Jákob učinil slib: Jestliže bude Bůh se mnou, bude mě chránit na této cestě, kterou se ubírám, a dá mi chléb k jídlu a oděv k oblékání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'takže se vrátím v pokoji do domu svého otce, bude Hospodin mým Bohem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'a ten kámen, který jsem postavil jako posvátný sloup, bude domem Božím. A ze všeho, co mi dáš, ti jistě dám desátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, '⌈Potom se Jákob zvedl⌉ a šel do země ⌈synů východu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Tu se podíval a uviděl studnu v poli a při ní tam odpočívala tři stáda ovcí. Z té studny se totiž napájela stáda a na otvoru studny ležel velký kámen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Když se tam všechna stáda shromáždila, odvalovali kámen z otvoru studny a dávali ovcím pít. Pak vraceli kámen na otvor studny, zpět na jeho místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Jákob se jich zeptal: Odkud jste, bratři? Odpověděli: Jsme z Cháranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Zeptal se jich: Znáte Lábana, syna Náchorova? Řekli: Známe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Dále se jich zeptal: ⌈Jak se mu daří?⌉ Odpověděli: Dobře. Hle, jeho dcera Ráchel přichází se stádem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Tu řekl: Hle, ještě je jasný den, ještě není čas shromažďovat dobytek. Napojte ovce a jděte je pást.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Odpověděli: Nemůžeme, dokud nebudou shromážděna všechna stáda a nebude odvalen kámen z otvoru studny. Pak napojíme ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Ještě s nimi mluvil, když přišla Ráchel s ovcemi svého otce; byla totiž pastýřkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Jakmile Jákob uviděl Ráchel, dceru Lábana, bratra své matky, a ovce Lábana, bratra své matky, přistoupil, odvalil kámen z otvoru studny a napojil ovce Lábana, bratra své matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Nato Jákob Ráchel políbil, pozvedl hlas a rozplakal se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Pak Jákob Ráchel oznámil, že je příbuzný jejího otce, že je synem Rebeky. Ona běžela a oznámila to svému otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Jakmile Lában uslyšel zprávu o Jákobovi, synu své sestry, vyběhl mu vstříc, objal ho a políbil a uvedl ho do svého domu. On pak to všechno vypravoval Lábanovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Lában mu pak řekl: Ty jsi vskutku ⌈má kost a moje tělo.⌉ I pobyl u něho po dobu jednoho měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Pak Lában Jákobovi řekl: Budeš mi snad sloužit zadarmo, protože jsi můj příbuzný? Oznam mi, jaká bude tvá odměna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Lában měl dvě dcery. Starší se jmenovala Lea a mladší se jmenovala Ráchel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea měla vlídné oči, ale Ráchel byla ⌈krásné postavy a krásného vzhledu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Jákob miloval Ráchel, proto řekl: Sedm let ti budu sloužit za tvou mladší dceru Ráchel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Lában odpověděl: Lépe, když ji dám tobě, než kdybych ji dal někomu jinému. Zůstaň u mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Jákob tedy sloužil za Ráchel sedm let, ale připadalo mu to jako několik dnů, protože ji miloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Potom Jákob řekl Lábanovi: Dej mi mou ženu -- protože dny mé služby se už naplnily -- ⌈abych k ní vešel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Lában shromáždil všechny místní lidi a uspořádal hostinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Večer pak vzal svou dceru Leu a uvedl ji k Jákobovi. A on k ní vešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Lában jí dal svou služku Zilpu, aby byla služkou jeho dcery Ley.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Nastalo ráno a Jákob uviděl, že je to Lea. Řekl Lábanovi: Cos mi to provedl? Což jsem u tebe nesloužil za Ráchel? Proč jsi mě podvedl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Lában odpověděl: U nás se to nedělá, aby se mladší provdala před prvorozenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Vyplň této mé dceři svatební týden, ať ti dáme také tu druhou za službu, kterou budeš u mne sloužit ještě dalších sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jákob to tak udělal a vyplnil jí svatební týden. Pak mu Lában dal za ženu svou dceru Ráchel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'A své dceři Ráchel za služku dal Lában svou služku Bilhu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Jákob vešel také k Ráchel, avšak Ráchel miloval víc než Leu. A sloužil u něho ještě dalších sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Když Hospodin viděl, že Lea není milována, otevřel její lůno, kdežto Ráchel zůstala neplodná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Lea otěhotněla, porodila syna a dala mu jméno Rúben, neboť si řekla: Hospodin viděl mé soužení; a: Teď si mě můj muž zamiluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Otěhotněla znovu, porodila syna a řekla: Hospodin slyšel, že nejsem milovaná, a dal mi ještě tohoto, a dala mu jméno Šimeón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Otěhotněla znovu, porodila syna a řekla: Tentokrát už se ke mně můj muž připojí, protože jsem mu porodila tři syny. Proto se jmenuje Lévi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'A otěhotněla znovu, porodila syna a řekla: Tentokrát budu vzdávat chválu Hospodinu. Proto mu dala jméno Juda. Potom přestala rodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Když Ráchel viděla, že Jákobovi neporodila děti, záviděla své sestře a řekla Jákobovi: Dej mi děti, nebo zemřu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jákob vzplál proti Ráchel hněvem a řekl: Což jsem na místě Boha, který ti odepřel plod lůna?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Odpověděla: Zde je má služebnice Bilha. Vejdi k ní, aby porodila na má kolena, a tak i já ⌈budu mít od ní dítě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Dala mu tedy svou služku Bilhu za ženu a Jákob k ní vešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bilha otěhotněla a porodila Jákobovi syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Ráchel pak řekla: Bůh mi zjednal právo, vyslyšel i můj hlas a dal mi syna. Proto mu dala jméno Dan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Ráchelina služka Bilha znovu otěhotněla a porodila Jákobovi druhého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Ráchel řekla: Úporné ⌈zápasy jsem vybojovala⌉ se svou sestrou a zdolala jsem ji; dala mu tedy jméno Neftalí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Lea viděla, že přestala rodit, tedy vzala svou služku Zilpu a dala ji Jákobovi za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Leina služka Zilpa porodila Jákobovi syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Lea řekla: Mám štěstí! A dala mu jméno Gád.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Pak Leina služka Zilpa porodila Jákobovi druhého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'A Lea řekla: ⌈Je to pro mne blaho,⌉ neboť mě ženy ⌈budou nazývat šťastnou!⌉ A dala mu jméno Ašer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Jednou v době ⌈sklizně pšenice⌉ Rúben šel a našel na poli ⌈jablíčka lásky⌉ a přinesl je své matce Lee. Ráchel Lee řekla: Dej mi, prosím, z jablíček lásky od svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Ona jí odpověděla: To je ti málo, vzít mi muže, že mi chceš vzít i jablíčka lásky od mého syna? Ráchel řekla: Za jablíčka lásky od tvého syna tedy bude spát tuto noc s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Když Jákob přicházel večer z pole, vyšla mu Lea naproti a řekla: ⌈ Musíš vejít⌉ ke mně, protože jsem tě opravdu najala za jablíčka lásky od svého syna. Spal tedy onu noc s ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'A Bůh Leu vyslyšel, otěhotněla a porodila Jákobovi pátého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Lea řekla: Bůh mi dal odměnu, že jsem dala svou služku svému muži. A dala mu jméno Isachar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lea znovu otěhotněla a porodila Jákobovi šestého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Tehdy Lea řekla: Bůh mě obdařil dobrým darem; tentokrát mě můj muž vyvýší, protože jsem mu porodila šest synů. A dala mu jméno Zabulón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Potom porodila dceru a dala jí jméno Dína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Bůh pamatoval na Ráchel, vyslyšel ji a otevřel její lůno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Otěhotněla, porodila syna a řekla: Bůh odňal mou potupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Dala mu jméno Josef se slovy: Kéž mi Hospodin přidá dalšího syna!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Když Ráchel porodila Josefa, řekl Jákob Lábanovi: Propusť mě, ať odejdu ⌈na své místo⌉ a do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Vydej mi mé ženy a děti, za něž jsem ti sloužil, a půjdu. Vždyť ty sám víš, jakou službu jsem ti prokazoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Lában mu odpověděl: Kéž bych ⌈nalezl milost v tvých očích⌉ a zůstal bys. ⌈V kalichu jsem viděl,⌉ že mi kvůli tobě Hospodin požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Dále řekl: Urči si svou mzdu u mne a dám ti ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Jákob mu odpověděl: Ty víš, jak jsem ti sloužil a jak se mnou tvůj dobytek prospíval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Vždyť to málo, co jsi měl před mým příchodem, se rozhojnilo v množství a Hospodin ti žehnal na každém mém kroku. Kdy již budu pracovat také pro svou rodinu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Zeptal se: ⌈Co ti mám dát?⌉ Jákob odpověděl: Nedávej mi nic. Pokud pro mne uděláš tuto věc, budu znovu pást a střežit tvé ovce:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, '⌈Projdu dnes celé tvé stádo a vezmu⌉ z něho všechny ovce skvrnité a strakaté, všechny načernalé ovce mezi jehňaty a strakaté a skvrnité kusy mezi kozami. To bude má mzda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Má spravedlnost bude pro mne od zítřejšího dne svědčit tak, že když přijdeš ⌈prohlédnout mou mzdu,⌉ všechno, co z koz nebude skvrnité či strakaté a mezi jehňaty načernalé, bude u mne pokládáno za kradené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Lában řekl: Dobrá, ať se stane podle tvého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Ale ještě toho dne odstranil pruhované a strakaté kozly a všechny skvrnité a strakaté kozy, všechno, co mělo na sobě něco bílého, a všechna načernalá jehňata a předal je do rukou svých synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, '⌈Pak je vzdálil od Jákoba⌉ tři dny cesty, zatímco Jákob pásl zbývající Lábanovo stádo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Jákob si pak vzal čerstvé pruty styraxu, mandloně a platanu a oloupal na nich bílé pruhy, takže odkryl to, co bylo na prutech bílé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'A pruty, které oloupal, položil v napajedlech na vodních žlabech, kam přicházely ovce pít, aby byly naproti ovcím, které se pářily, když přicházely pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Když se ovce či kozy pářily před pruty, rodily pruhovaná, skvrnitá a strakatá jehňata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Jákob ta jehňata odděloval; ovce z Lábanova bravu stavěl směrem k pruhovaným a všem načernalým. Tak si připravil svá samostatná stáda, která nepřipojil k ovcím Lábanovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'A kdykoliv se pářily statné ovce či kozy, Jákob pokládal pruty před oči stáda do napajedel, aby se pářily u prutů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'U slabých ovcí pruty nepokládal. Tak připadly ty slabé Lábanovi a statné Jákobovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Tak ten muž převelice zbohatl. Patřilo mu mnoho bravu, služky a otroci, velbloudi i osli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Jákob uslyšel slova Lábanových synů: Jákob vzal všechno, co bylo našeho otce! A z toho, co bylo našeho otce, si nahromadil všechno toto bohatství!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'I na Lábanově tváři Jákob viděl, že už vůči němu nebyl takový jako dříve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Tu řekl Hospodin Jákobovi: Navrať se do země svých otců a do svého rodiště; já budu s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Jákob ⌈si tedy dal zavolat⌉ Ráchel a Leu na pole ke svému stádu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'a řekl jim: Vidím na tváři vašeho otce, že už vůči mně není takový jako dříve, avšak Bůh mého otce byl se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Vy však víte, že jsem vašemu otci sloužil celou svojí silou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Avšak váš otec ⌈si ze mne tropil žerty,⌉ desetkrát změnil mou mzdu, ale Bůh mu nedovolil mi uškodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Když řekl: Tvou mzdou budou skvrnité, všechny ovce rodily skvrnité; když řekl: Tvou mzdou budou pruhované, všechny ovce rodily pruhované.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Bůh odňal dobytek vašemu otci a dal ho mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'I stalo se v době páření ovcí, že jsem pozvedl oči a ve snu jsem viděl, že berani, kteří skákali na ovce, byli pruhovaní, skvrnití a strakatí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Pak mi Boží anděl ve snu řekl: Jákobe! Odpověděl jsem: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'On pokračoval: Nuže pozvedni oči a viz: Všichni berani, kteří skákají na ovce, jsou pruhovaní, skvrnití a strakatí. Viděl jsem totiž všechno, co ti Lában provádí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Já jsem Bůh z Bét–elu, kde jsi pomazal posvátný sloup a kde jsi mi učinil slib. Teď vstaň, odejdi z této země a navrať se do své rodné země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Ráchel a Lea mu odpověděly: Máme snad ještě dědičný podíl v domě svého otce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Cožpak nás nepovažuje za cizinky? Vždyť nás prodal a ⌈peníze dočista utratil!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Ano, všechno bohatství, které Bůh odňal našemu otci, patří nám a našim dětem. Nyní tedy udělej všechno, co ti Bůh řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Nato Jákob vstal, posadil své děti a ženy na velbloudy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'a sehnal všechen svůj dobytek a všechen svůj majetek, jejž nabyl, dobytek a zboží, které nabyl v Paddan–aramu, aby šel ke svému otci Izákovi do kenaanské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Když Lában odešel stříhat ovce, Ráchel ukradla domácí bůžky, které patřily jejímu otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'A Jákob oklamal Aramejce Lábana, když mu neoznámil, že utíká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Tak utekl se vším, co měl. Vstal, přebrodil Řeku a ⌈vydal se směrem⌉ ke gileádskému pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Třetího dne bylo Lábanovi oznámeno, že Jákob utekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Tedy vzal s sebou své příbuzné, ⌈po sedm⌉ dní ho pronásledoval a dostihl ho v gileádském pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'K Aramejci Lábanovi přišel ve snu v noci Bůh a řekl mu: Měj se na pozoru, abys ⌈nepromlouval k Jákobovi ani dobro ani zlo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Lában dostihl Jákoba, když Jákob postavil svůj stan na hoře. I Lában se svými příbuznými tábořil v gileádském pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Lában se Jákoba zeptal: Cos to udělal, žes mne oklamal a mé dcery jsi odvedl jako ⌈válečné zajatce?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Proč ⌈jsi potají utekl⌉ a oklamals mne? Neoznámils mi to, abych tě mohl propustit s radostí a zpěvy, s tamburínou a lyrou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Ani jsi mě nenechal políbit mé vnuky a dcery. Tentokrát bylo tvé jednání bláznivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Je v mé moci naložit s vámi zle. Ale včera mi Bůh vašeho otce řekl: Měj se na pozoru, abys nepromlouval k Jákobovi ani dobro ani zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Když už jsi chtěl odejít, protože jsi velice toužil po otcovském domě, proč jsi ukradl mé bohy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jákob na to Lábanovi odpověděl: Protože jsem se bál, neboť jsem si myslel, abys mi neuchvátil své dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'U koho najdeš své bohy, ten nezůstane naživu. Před našimi příbuznými prozkoumej, co tvého je u mne, a vezmi si to. Jákob totiž nevěděl, že je Ráchel ukradla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Lában tedy vešel do stanu Jákobova, do stanu Leina, i do stanu obou služebnic, ale nic nenašel. Pak vyšel z Leina stanu a vešel do stanu Ráchelina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Ráchel však vzala domácí bůžky, vložila je do velbloudího sedla a posadila se na ně. Lában prohledal celý stan, ale nic nenašel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Ráchel řekla svému otci: Ať ⌈se můj pán nerozzlobí,⌉ že nemohu ve tvé přítomnosti povstat, protože mám to, co mívají ženy. Vše prohledal, ale domácí bůžky nenašel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Tu Jákob vzplanul hněvem a začal se s Lábanem přít. Říkal mu: Jaké je mé přestoupení? Jaký je můj hřích, žes mě tak pronásledoval?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Když jsi prohledal všechny mé věci, cos ze všech ⌈svých věcí⌉ našel? Polož to sem před bratry mé i bratry své, ať mezi námi dvěma rozsoudí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Těchto dvacet let jsem u tebe. Tvé ovce ani kozy nepotratily, berany z tvého stáda jsem nejídal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Rozsápané zvíře jsem ti nepřinášel, sám jsem nesl ztrátu; vyžadoval jsi ode mne to, co bylo ukradeno ve dne i co bylo ukradeno v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Ve dne mě stravovalo horko a v noci mráz, spánek prchal od mých očí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'To bylo mých dvacet let ve tvém domě: Čtrnáct let jsem ti otročil za tvé dvě dcery a šest let za tvůj brav, ale mou mzdu jsi změnil desetkrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Kdyby Bůh mého otce, Bůh Abrahamův a strach Izákův nebyl ⌈se mnou,⌉ propustil bys mě teď s prázdnou. Bůh viděl mé soužení a námahu mých rukou a včera rozsoudil. –');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Lában na to Jákobovi odpověděl: Tyto dcery jsou moje dcery a tyto děti jsou moje děti, tento brav je můj brav a všechno, co vidíš, je mé. Ale co mohu dnes udělat pro tyto své dcery nebo pro děti, které porodily?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Nuže pojď, já a ty uzavřeme smlouvu, a bude na svědectví mezi mnou a tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Jákob tedy vzal kámen a vztyčil ho jako pamětní sloup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Pak řekl svým bratrům: Nasbírejte kameny. Vybrali kameny, udělali hromadu a tam na té hromadě pojedli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Lában ji nazval Jegar–sahaduta a Jákob ji nazval Gal–ed.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'A Lában řekl: Tato hromada je dnes svědectvím mezi mnou a tebou. Proto se jmenuje Gal–ed,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'a také Mispa, neboť řekl: Ať Hospodin drží hlídku mezi mnou a tebou, až budeme jeden před druhým ukryti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Jestliže budeš mé dcery pokořovat nebo si vezmeš ženy mimo mé dcery, byť by nikdo nebyl s námi, pohleď, Bůh je svědkem mezi mnou a tebou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Lában ještě řekl Jákobovi: Viz tuto hromadu a viz pamětní sloup, jež jsem vztyčil mezi sebou a tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Svědkem je tato hromada a svědkem je ten pamětní sloup, že já tuto hromadu nepřekročím ke zlému k tobě, a že ty tuto hromadu a tento pamětní sloup nepřekročíš ke zlému ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Ať Bůh Abrahamův a ⌈Bůh Náchorův, Bůh jejich otce soudí⌉ mezi námi! A Jákob přísahal při strachu svého otce Izáka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Pak Jákob obětoval na hoře oběť a zavolal své příbuzné, aby jedli chléb. Jedli chléb a přenocovali na té hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Když Lában vstal časně ráno, políbil své vnuky a své dcery a požehnal jim. Pak Lában odešel a navrátil se do svého bydliště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'I Jákob šel svou cestou. Tu se s ním potkali Boží andělé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Když je spatřil, Jákob řekl: To je tábor Boží! A pojmenoval ono místo Machanajim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Jákob poslal před sebou posly ke svému bratru Ezauovi do země Seíru na edómské území');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'a přikázal jim: Toto řekněte mému pánu Ezauovi: Toto vzkazuje tvůj otrok Jákob: Byl jsem hostem u Lábana a prodléval jsem tam až dosud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Mám voly a osly, ovce, otroky a otrokyně. Posílám posly, abych to oznámil svému pánu a nalezl milost ve tvých očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Poslové se vrátili k Jákobovi se slovy: Přišli jsme k tvému bratru Ezauovi, a již ti jde naproti se čtyřmi sty mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Jákob dostal velký strach a bylo mu úzko. I rozdělil lid, který byl s ním, i brav, skot a velbloudy do dvou táborů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'neboť si řekl: Když Ezau přijde k jednomu táboru a pobije ho, zbylý tábor bude moci uniknout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Pak Jákob řekl: Bože mého otce Abrahama a Bože mého otce Izáka, Hospodine, který jsi mi řekl: Navrať se do své země, do svého rodiště a prokáži ti dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Nejsem hoden všeho milosrdenství a veškeré věrnosti, jež jsi svému otroku prokázal. Vždyť s holí jsem přešel tento Jordán a teď mám dva tábory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Vysvoboď mě prosím z ruky mého bratra, z ruky Ezaua, neboť se ho bojím, aby nepřišel a nezabil mne, matku nad syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Vždyť ty jsi řekl: Určitě ti prokáži dobro a učiním tvé potomstvo jako mořský písek, který pro množství nemůže být spočítán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Onu noc tam zůstal a pak vybral z toho, co měl s sebou, dar pro svého bratra Ezaua:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Dvě stě koz a dvacet kozlů, dvě stě ovcí a dvacet beranů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'třicet velbloudic se sajícími mláďaty, čtyřicet krav a deset býků, dvacet oslic a deset oslů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'A ⌈každé stádo⌉ zvlášť předal do rukou svých otroků a řekl jim: Jděte přede mnou a ponechte odstup mezi ⌈jednotlivými stády.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'A prvnímu přikázal: Až se s tebou setká můj bratr Ezau a zeptá se tě, čí jsi, kam jdeš a čí jsou ta zvířata před tebou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'odpovíš: Patří tvému otroku Jákobovi; je to dar poslaný mému pánu Ezauovi. A hle, také on jde za námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Přikázal také druhému i třetímu a všem, kdo šli za stády: Takovým způsobem budete mluvit s Ezauem, až ho potkáte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'A ještě řeknete: Hle, tvůj otrok Jákob jde za námi, protože si řekl: Usmířím ho darem, který půjde přede mnou, a potom uvidím jeho tvář; snad ⌈mne milostivě přijme.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Dar ⌈ho tedy předcházel,⌉ zatímco on tuto noc zůstal v táboře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Té noci vstal, vzal své dvě ženy a své dvě služky i svých jedenáct chlapců a přešel brod v Jaboku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Vzal je a převedl je přes potok a převedl všechno, co měl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Pak Jákob zůstal sám a zápasil s ním nějaký muž až do východu jitřenky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Když viděl, že ho nepřemůže, udeřil ho do kyčelního kloubu, a Jákobovi se vykloubil kyčelní kloub, když s ním zápasil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Pak muž řekl: Pusť mě, neboť vyšla jitřenka. Jákob odpověděl: Nepustím tě, pokud mi nepožehnáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'I řekl mu: Jaké je tvé jméno? Odpověděl: Jákob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Nato řekl: Tvé jméno již nebude Jákob, ale Izrael. Protože jsi zápasil s Bohem i s lidmi a obstál jsi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Jákob se ještě vyptával: Oznam mi prosím své jméno. On řekl: Nač to, že se vyptáváš na mé jméno? A požehnal mu tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Jákob to místo pojmenoval Peníel, neboť řekl: Viděl jsem Boha tváří v tvář a můj život byl zachráněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Vycházelo mu slunce, když procházel Penúel; ale byl kulhavý kvůli své kyčli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'Proto synové Izraelovi až dodnes nejedí šlachu, která je nad kyčelním kloubem, protože udeřil Jákoba do kyčelního kloubu, do té šlachy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jákob pozvedl oči, a hle, viděl přicházet Ezaua a s ním čtyři sta mužů. I rozdělil děti mezi Leu, Ráchel a obě služky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Služky a jejich děti umístil dopředu, Leu a její děti potom a Ráchel s Josefem poslední.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Sám šel před nimi a sedmkrát se poklonil až k zemi, než se ke svému bratru přiblížil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Ezau mu však běžel vstříc, objal ho, padl mu kolem krku a políbil ho. Oba plakali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Pak Ezau pozvedl zrak, uviděl ženy a děti a zeptal se: Koho to tu máš? Jákob odpověděl: Děti, kterými Bůh milostivě obdaroval tvého otroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Nato přistoupily služky se svými dětmi a poklonily se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Přistoupila také Lea se svými dětmi a poklonily se a potom přistoupil Josef a Ráchel a poklonili se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Ezau se zeptal: ⌈Co míníš ⌉ ⌈vším tím táborem,⌉ který jsem potkal? Jákob odpověděl: Chci nalézt milost v očích svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Ezau řekl: Mám hojnost, bratře, ať ti zůstane to, co je tvé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Ale Jákob řekl: Ne, prosím, jestliže jsem nyní nalezl milost v tvých očích, přijmi ten dar ode mne, neboť jsem viděl tvou tvář, jako bych viděl tvář Boží, a laskavě jsi mne přijal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Přijmi prosím mé požehnání, které jsem ti přinesl; neboť Bůh mi byl milostiv a mám všechno. Nutil ho, až to přijal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Ezau řekl: Vyrazme a pojďme. Já půjdu ⌈před tebou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Jákob mu odpověděl: Můj pán ví, že děti jsou ještě útlé a ⌈mám tu ⌉ ovce a krávy krmící mladé. Kdyby je ostře hnali jediný den, celé to stádo by uhynulo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Ať jde, prosím, můj pán před svým otrokem, a já budu postupovat pozvolna podle kroku dobytka, jenž je přede mnou, a podle kroku dětí, dokud nepřitáhnu ke svému pánu do Seíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Ezau řekl: Dovol, ať u tebe ponechám některé z lidí, kteří jsou se mnou. Jákob odpověděl: Nač to? Jen když naleznu milost v očích svého pána!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Tak se toho dne Ezau navrátil svou cestou do Seíru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jákob však odtáhl do Sukótu a postavil si dům a pro svůj dobytek udělal stánky. Proto se to místo nazývá Sukót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Potom, když přišel z Paddan–aramu, Jákob pokojně přišel do města Šekemu, které je v kenaanské zemi. Utábořil se před městem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'a od synů Chamóra, otce Šekemova, koupil za sto kesít díl pole, na kterém postavil svůj stan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'A postavil tam oltář a nazval ho Bůh je Bohem Izraelovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dína, dcera Ley, kterou porodila Jákobovi, si vyšla, aby se podívala na dcery té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Uviděl ji ⌈Šekem, syn Chivejce Chamóra, knížete⌉ té země, zmocnil se jí, ležel s ní a znásilnil ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, '⌈Přilnul svou duší⌉ k Díně, dceři Jákobově. Miloval tu dívku a mluvil k jejímu srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'A svému otci Chamórovi Šekem řekl: Vezmi mi toto děvče za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Když Jákob uslyšel, že Šekem poskvrnil jeho dceru Dínu, jeho synové byli s jeho dobytkem na poli. Jákob mlčel až do jejich příchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Šekemův otec Chamór vyšel k Jákobovi, aby s ním promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Synové Jákobovi přišli z pole, jakmile o tom uslyšeli. Ti muži byli hluboce zarmouceni a vzpláli velikým hněvem. Vždyť spáchal hanebnost v Izraeli, když ležel s dcerou Jákobovou. To se nemělo stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Chamór s nimi mluvil takto: Můj syn Šekem ⌈přilnul celou duší⌉ k vaší dceři. Dejte mu ji, prosím, za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'A spřízněte se s námi; své dcery dávejte nám a berte si naše dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Zůstaňte u nás. Celá země je před vámi: Pobývejte v ní, procházejte jí a natrvalo se v ní usaďte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'A Šekem řekl jejímu otci a jejím bratrům: Kéž naleznu milost ve vašich očích! A co mi řeknete, to vám dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Stanovte mi jakkoli vysoké odstupné a dar. Dám, cokoli mi řeknete, jen mi dejte tu dívku za ženu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Jákobovi synové však na to Šekemovi a jeho otci Chamórovi odpověděli lstivě, protože poskvrnil jejich sestru Dínu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Řekli jim: Nemůžeme udělat takovou věc, abychom svou sestru dali někomu, kdo není obřezán, protože pro nás to je potupa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Jen tak budeme s vámi souhlasit, když budete jako my tím, že každý mužského pohlaví bude u vás obřezán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Pak vám budeme dávat své dcery a budeme si brát vaše dcery, zůstaneme u vás a staneme se jedním lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'A jestli nás neuposlechnete a neobřežete se, vezmeme svou dceru a půjdeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Jejich slova se Chamórovi a Chamórovu synu Šekemovi líbila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Mládenec neváhal a vykonal tu věc, protože měl zalíbení v Jákobově dceři. Byl nejváženější z celého otcovského domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Chamór a jeho syn Šekem přišli do brány svého města a promluvili k mužům města:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Tito muži jsou vůči nám přátelští. Ať pobývají v zemi a procházejí jí, vždyť země je před nimi dosti rozlehlá. Jejich dcery si budeme brát za ženy a své dcery budeme dávat jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Ale jen tak budou s námi ti muži souhlasit, aby zůstali u nás a abychom se stali jedním lidem, když každý mužského pohlaví u nás bude obřezán, tak jako jsou obřezáni oni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Jejich stáda, jejich zboží a všechen jejich dobytek, což to nebude naše? Jen s nimi souhlasme a zůstanou u nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'A všichni, kdo vycházeli do brány jeho města, uposlechli Chamóra a jeho syna Šekema. Všichni mužského pohlaví se dali obřezat, všichni, kdo vycházeli do brány jeho města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Třetího dne pak, když měli bolesti, vzali dva Jákobovi synové, Šimeón a Lévi, bratři Díny, každý svůj meč, přišli do města, které se cítilo bezpečně, a povraždili všechny mužského pohlaví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Také Chamóra a jeho syna Šekema zabili ostřím meče, vzali z Šekemova domu Dínu a odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Jákobovi synové přišli na pobité a vyplenili to město, kde poskvrnili jejich sestru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Pobrali jejich brav, skot i jejich osly, co bylo ve městě i co bylo na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Zajali a ukořistili všechen jejich majetek, všechny ⌈malé děti⌉ a ženy, všechno, co bylo v domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Jákob řekl Šimeónovi a Lévimu: Uvalili jste na mne zkázu, když jste mne zošklivili u obyvatel země, u Kenaanců a Perizejců. Nás je malý počet. Shromáždí–li se proti mně a pobijí–li mne, budu vyhlazen já i můj dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Oni však odpověděli: Cožpak směl jednat s naší sestrou jako s nevěstkou? –');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'I řekl Bůh Jákobovi: Vstaň, vystup do Bét–elu a usaď se tam. Postav tam oltář Bohu, který se ti ukázal, když jsi utíkal před svým bratrem Ezauem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Jákob tedy řekl svému domu i všem, kteří byli s ním: Odstraňte ze svého středu cizí bohy, očistěte se a změňte svůj oděv,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'vstaňme a vystupme do Bét–elu. Tam udělám oltář Bohu, který mi odpověděl ve dni mého soužení a byl se mnou na cestě, kterou jsem šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Nato dali Jákobovi všechny cizí bohy, které měli, a kroužky, které měli v uších, a Jákob je skryl pod terebintem, který je u Šekemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Potom vyrazili a Boží děs padl na okolní města, takže syny Jákobovy nepronásledovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Tak přišel Jákob, on i všechen lid, který byl s ním, do Lúzu v kenaanské zemi, což je Bét–el.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Postavil tam oltář a nazval to místo El Bét–el, protože tam se mu zjevil Bůh, když utíkal před svým bratrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Potom zemřela Rebečina chůva Debóra a byla pohřbena dole u Bét–elu pod dubem. Dal mu jméno ⌈Alón Bakhúth.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Bůh se Jákobovi ukázal znovu po jeho příchodu z Paddan–aramu a požehnal ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Bůh mu řekl: Tvé jméno je Jákob. Tvé jméno již nebude Jákob, ale tvé jméno bude Izrael. Tak mu dal jméno Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Ještě mu Bůh řekl: Já jsem Bůh Všemohoucí. Rozploď a rozmnož se; národ, ba shromáždění národů z tebe vzejde; i králové vzejdou z tvých beder.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'A zemi, kterou jsem dal Abrahamovi a Izákovi, dám tobě. Také tvému potomstvu po tobě dám tuto zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Potom Bůh vystoupil od něho z místa, kde s ním mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'A Jákob na místě, kde s ním mluvil, postavil posvátný sloup, kamenný posvátný sloup, a vylil na něj litou oběť a polil jej olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Jákob dal místu, kde s ním Bůh mluvil, jméno Bét–el.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Pak odtáhli z Bét–elu. Byl to ještě ⌈kus cesty⌉ do Efraty, když Ráchel začala rodit. Měla velmi těžký porod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'V nejtěžší chvíli jejího porodu jí porodní bába řekla: Neboj se, protože máš zase syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Když její duše vycházela -- neboť umírala -- dala mu jméno Ben–óni, ale otec ho nazval Benjamín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Ráchel zemřela a byla pohřbena u cesty do Efraty, což je Betlém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Jákob nad jejím hrobem postavil pamětní sloup. To je pamětní sloup Ráchelina hrobu až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Pak Izrael odtáhl a postavil svůj stan za Migdal–ederem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Stalo se, když Izrael přebýval v oné zemi, že Rúben šel a spal s Bilhou, konkubínou svého otce, a Izrael se to doslechl. Jákobových synů bylo dvanáct:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Synové Ley: Jákobův prvorozený Rúben, Šimeón, Lévi a Juda, Isachar a Zabulón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Synové Ráchel: Josef a Benjamín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Synové Rácheliny služky Bilhy: Dan a Neftalí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'A synové Leiny služky Zilpy: Gád a Ašer. Toto jsou Jákobovi synové, kteří se mu narodili v Paddan–aramu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Pak Jákob přišel ke svému otci Izákovi do Mamre do Kirjat–arby, což je Chebrón, kde pobývali Abraham i Izák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Izákovi bylo sto osmdesát let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'I dokonal Izák a zemřel a byl připojen ke svému lidu, starý a sytý dnů. Jeho synové Ezau a Jákob ho pohřbili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Toto je rodopis Ezauův, to jest Edómův:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ezau si vzal ženy z dcer kenaanských: Ádu, dceru Chetejce Elóna, a Oholíbamu, dceru Anovu, vnučku Chivejce Sibeóna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'a Basematu, dceru Izmaelovu, sestru Nebajótovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Áda Ezauovi porodila Elífaza a Basemat porodila Reúela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholíbama porodila Jeúše, Jaelama a Kóracha. To jsou Ezauovi synové, kteří se mu narodili v kenaanské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ezau vzal své ženy, své syny a dcery, všechny lidi svého domu, svůj dobytek i všechnu zvěř a veškeré své zboží, jež nabyl v kenaanské zemi, a odešel do jiné země od svého bratra Jákoba,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'protože jejich majetek byl příliš velký, aby bydleli spolu, a země, ⌈kde byli hosty,⌉ ⌈jim nemohla stačit⌉ kvůli jejich stádům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Ezau tedy pobýval v pohoří Seíru; Ezau je Edóm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Toto je rodopis Ezaua, otce Edómců v pohoří Seíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Toto jsou jména Ezauových synů: Elífaz, syn Ezauovy ženy Ády, Reúel, syn Ezauovy ženy Basematy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Synové Elífazovi jsou: Téman, Ómar, Sefó, Gátam a Kenaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timna byla konkubína Ezauova syna Elífaza. Ta Elífazovi porodila Amáleka. To jsou vnuci Ezauovy ženy Ády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'A toto jsou synové Reúelovi: Nachat, Zerach, Šama a Miza. To jsou vnuci Ezauovy ženy Basematy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'A toto jsou synové Ezauovy ženy Oholíbamy, dcery Anovy, vnučky Sibeónovy: Porodila Ezauovi Jeúše, Jaelama a Kóracha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Toto jsou náčelníci Ezauových potomků. Synové Elífaza, Ezauova prvorozeného: Náčelník Téman, náčelník Ómar, náčelník Sefó, náčelník Kenaz,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, '⌈náčelník Kórach,⌉ náčelník Gátam, náčelník Amálek. To jsou Elífazovi náčelníci v edómské zemi, to jsou synové Ády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'A toto jsou synové Ezauova syna Reúela: Náčelník Nachat, náčelník Zerach, náčelník Šama, náčelník Miza. To jsou Reúelovi náčelníci v edómské zemi, to jsou vnuci Ezauovy ženy Basematy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'A toto jsou synové Ezauovy ženy Oholíbamy: Náčelník Jeúš, náčelník Jaelam, náčelník Kórach. To jsou náčelníci Anovy dcery Oholíbamy, ženy Ezauovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'To jsou synové Ezaua, to je Edóma, a to jsou jejich náčelníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Toto jsou synové Chorejce Seíra, původní obyvatelé té země: Lótan, Šóbal, Sibeón a Ana,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Díšon, Eser a Díšan. To jsou Seírovi synové, chorejští náčelníci v edómské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Lótanovi synové jsou Chorí a Hémam; Lótanova sestra je Timna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'A toto jsou synové Šóbalovi: ⌈Alván, Manachat, Ébal, Šefó⌉ a Ónam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Toto jsou synové Sibeónovi: Aja a Ana. To je ten Ana, který nalezl v pustině ⌈horká zřídla,⌉ když pásl osly svého otce Sibeóna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'A toto jsou potomci Anovi: Díšon a Anova dcera Oholíbama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Toto jsou synové Díšanovi: Chemdán, Ešbán, Jitrán a Keran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Toto jsou synové Eserovi: Bilhán, Zaavan a Akan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Toto jsou synové Díšanovi: Ús a Aran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Toto jsou chorejští náčelníci: náčelník Lótan, náčelník Šóbal, náčelník Sibeón, náčelník Ana,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'náčelník Díšon, náčelník Eser, náčelník Díšan. To jsou chorejští náčelníci podle seznamu jejich náčelníků v zemi Seíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Toto jsou králové, kteří kralovali v edómské zemi, dříve než nějaký král kraloval synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'V Edómu kraloval Bela, syn Beórův, a jeho město se jmenovalo Dinhaba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Když Bela zemřel, stal se po něm králem Jóbab, syn Zerachův, z Bosry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Když Jóbab zemřel, stal se po něm králem Chúšam z témanské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Když Chúšam zemřel, stal se po něm králem Hadad, syn Bedadův, který pobil Midjánce na moábském poli. Jeho město se jmenovalo Avít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Když Hadad zemřel, stal se po něm králem Samla z Masreky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Když Samla zemřel, stal se po něm králem Šaúl z Rechobótu na řece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Když Šaúl zemřel, stal se po něm králem Baal–chanan, syn Akbórův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Když Akbórův syn Baal–chanan zemřel, stal se po něm králem Hadar. Jeho město se jmenovalo Paí a jeho žena se jmenovala Mehétabel, dcera Matredy, dcera Mezahabova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Toto jsou jména Ezauových náčelníků podle jejich čeledí a podle jejich území, jmenovitě: náčelník Timna, náčelník Alva, náčelník Jetet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'náčelník Oholíbama, náčelník Éla, náčelník Pínon,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'náčelník Kenaz, náčelník Téman, náčelník Mibsár,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'náčelník Magdíel a náčelník Íram. To jsou edómští náčelníci podle svých sídel v zemi jejich vlastnictví. To je Ezau, otec Edómců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jákob se usadil v zemi putování svého otce, v zemi kenaanské.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Toto je rodopis Jákobův. Sedmnáctiletý Josef pásl s bratry ovce. ⌈Mládenec byl se syny⌉ žen svého otce, Bilhy a Zilpy. Josef o nich přinesl jejich otci zlou zprávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Izrael miloval Josefa nade všechny své syny, protože byl jeho synem ve stáří, a udělal mu ⌈bohatě vyšívanou suknici.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Když jeho bratři viděli, že ho otec miluje nade všechny bratry, začali ho nenávidět a nedokázali s ním pokojně promluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Jednou měl Josef sen a pověděl ho svým bratrům. Nenáviděli ho pak ještě více.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Řekl jim: Poslechněte si prosím sen, který jsem měl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Hle, vázali jsme na poli snopy. Tu můj snop povstal a zůstal stát, a vaše snopy obcházely kolem a klaněly se mému snopu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Bratři mu řekli: Opravdu budeš nad námi kralovat? Skutečně nám budeš vládnout? A nenáviděli ho kvůli jeho snům a kvůli jeho slovům ještě více.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Měl znovu jiný sen a vyprávěl ho svým bratrům: Hle, znovu jsem měl sen, a v něm se mi klanělo slunce, měsíc a jedenáct hvězd.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Vyprávěl ho otci a bratrům. Otec ho okřikl: Jakýs to měl sen? Cožpak snad přijdeme já, tvá matka a tvoji bratři, abychom se ti klaněli k zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Bratři na něho žárlili, ale otec to zachovával v mysli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Bratři pak odešli, aby pásli ovce svého otce v Šekemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Izrael řekl jednou Josefovi: Což nepasou tvoji bratři v Šekemu? Pojď, pošlu tě k nim. Řekl mu: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Izrael mu řekl: Jdi se prosím podívat, jak se daří tvým bratrům a ovcím a přines mi zprávu. Tak ho poslal z chebrónského údolí a on přišel do Šekemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Když bloudil tou krajinou, potkal ho nějaký muž a zeptal se ho: Co hledáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Odpověděl: Hledám své bratry. Pověz mi, prosím, kde pasou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Ten muž mu řekl: Odtáhli odsud, protože jsem je slyšel říkat: Pojďme do Dótanu. Josef šel za svými bratry a nalezl je v Dótanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Oni ho viděli zpovzdálí, dříve než se k nim přiblížil, a záludně se proti němu domluvili, že ho usmrtí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Říkali jeden druhému: Hle, mistr snů přichází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Nuže pojďte, zabijme ho a hoďme ho do jedné z těchto cisteren a řekneme, že ho sežrala divá zvěř. A uvidíme, co bude z jeho snů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Uslyšel to Rúben a zachránil ho z jejich ruky. Řekl: ⌈Nezabíjejme ho!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Dále jim Rúben řekl: Neprolévejte krev. Hoďte ho do té cisterny v pustině, ale ruku na něho nevztahujte. To řekl, aby ho vysvobodil z jejich ruky, aby ho přivedl zpět k jeho otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Jakmile Josef přišel k bratrům, svlékli z Josefa ⌈jeho suknici,⌉ tu bohatě vyšívanou suknici, kterou měl na sobě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'a vzali Josefa a hodili ho do cisterny. Byla to prázdná cisterna, nebyla v ní voda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Pak se posadili, aby pojedli chléb. Když pozvedli oči, tu uviděli karavanu Izmaelitů přicházející z Gileádu. Jejich velbloudi nesli ladanum, balzám a myrhu dolů do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Tu řekl Juda svým bratrům: Jaký zisk z toho bude, když zabijeme svého bratra a utajíme jeho krev?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Pojďte, prodáme ho Izmaelitům, ale svou ruku na něho nevztahujme; vždyť to je náš bratr a naše tělo. Bratři Judu poslechli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Když procházeli kolem midjánští obchodníci, vytáhli a vyndali Josefa z cisterny a prodali ho Izmaelitům za dvacet šekelů stříbra. Ti přivedli Josefa do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Pak se Rúben navrátil k cisterně a uviděl, že Josef v cisterně není. Roztrhl své roucho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'vrátil se ke svým bratrům a říkal: Ten chlapec už tu není. A co já, kam já půjdu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Nato vzali Josefovu suknici, zabili kozla a namočili suknici do krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Tu bohatě vyšívanou suknici ⌈nechali přinést⌉ ke svému otci se slovy: Toto jsme nalezli. Prozkoumej to, prosíme. Je to suknice tvého syna, nebo není?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Poznal ji a řekl: To je suknice mého syna Josefa! Sežrala ho divá zvěř! Josef je jistě rozsápán!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Jákob roztrhl své roucho, vzal si přes bedra pytlovinu a po mnoho dní truchlil pro svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Všichni jeho synové a všechny jeho dcery povstali, aby ho potěšili, ale nechtěl se dát potěšit a říkal: Truchlící sestoupím ke svému synovi do podsvětí. Tak nad ním plakal jeho otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Midjánci Josefa prodali do Egypta faraonovu ⌈dvornímu úředníku⌉ Potífarovi, veliteli tělesné stráže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'V té době se stalo, že Juda odešel od svých bratrů a uchýlil se až k adulamskému muži jménem Chíra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Juda tam spatřil dceru kenaanského muže jménem Šúa. Vzal si ji za ženu a vešel k ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Otěhotněla a porodila syna. Juda mu dal jméno Ér.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Pak znovu otěhotněla, porodila syna a dala mu jméno Ónan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'A ještě znovu porodila syna a dala mu jméno Šela. ⌈Bylo to ⌉ v Kezíbu, když ho porodila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Pak Juda vybral pro Éra, svého prvorozeného, ženu jménem Támar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Ale Judův prvorozený Ér byl zlý v Hospodinových očích a Hospodin ho usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'I řekl Juda Ónanovi: Vejdi k ženě svého bratra a splň vůči ní švagrovskou povinnost; vzbuď svému bratru potomka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Ónan věděl, že ten potomek nebude patřit jemu, proto když vcházel k ženě svého bratra, vypouštěl semeno na zem, aby nedal potomka svému bratru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'To, co páchal, bylo v Hospodinových očích zlé. Proto usmrtil i jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Juda pak řekl své snaše Támaře: Usaď se jako vdova v domě svého otce, dokud nevyroste můj syn Šela. Říkal si však: Aby také on nezemřel jako jeho bratři. Támar tedy šla a usadila se v otcovském domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Uplynulo mnoho dní a Judova žena, dcera Šúova, zemřela. Když se Juda utěšil, šel se svým adulamským přítelem Chírou ke střihačům svých ovcí do Timny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Támaře bylo oznámeno: Hle, tvůj tchán jde do Timny stříhat ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Odložila tedy své vdovské šaty, zakryla se závojem, úplně se zahalila a posadila se u vstupu do Énajimu, který je na cestě do Timny. Viděla totiž, že Šela vyrostl a ona mu nebyla dána za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Juda ji spatřil a považoval ji za nevěstku, protože měla zakrytou tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Naklonil se k ní u cesty a řekl: Pojď, chci k tobě vejít. (Nevěděl totiž, že je to jeho snacha.) Odpověděla: Co mi dáš, když ke mně vejdeš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Řekl: Pošlu kůzle ze stáda. Odpověděla: Dej však zástavu, než je pošleš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Řekl: Jakou zástavu ti mám dát? Odpověděla: Svůj pečetní prsten, šňůrku a hůl, kterou máš v ruce. Dal jí to, vešel k ní, a ona s ním otěhotněla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Pak vstala, odešla, odložila závoj a oblékla si vdovské šaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda pak poslal ⌈svého adulamského přítele s kůzletem,⌉ aby vzal od té ženy zástavu, ale nenašel ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Vyptával se mužů v tom místě: Kde je ta chrámová nevěstka, která byla v Énajimu u cesty? Odpovídali: Žádná chrámová nevěstka tu nebyla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Vrátil se k Judovi a řekl: Nenašel jsem ji. Také muži v tom místě říkali, že tam žádná chrámová nevěstka nebyla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juda řekl: Ať si to vezme; jen abychom nebyli v pohrdání. Vždyť jsem jí to kůzle poslal, ale tys ji nenašel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Asi po třech měsících bylo Judovi oznámeno: Tvá snacha Támar se dopustila smilstva, a hle, také je ze smilstva těhotná. Juda odpověděl: Vyveďte ji, ať je upálena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Když ji vyváděli, vzkázala svému tchánovi: Jsem těhotná s mužem, kterému patří tyto věci. A pokračovala: Prozkoumej, prosím, komu patří tento ⌈pečetní prsten,⌉ šňůrka a tato hůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juda to prozkoumal a řekl: Je spravedlivější než já, neboť jsem ji nedal svému synu Šelovi. A už ji znovu nepoznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Když nastal čas jejího porodu, hle, v jejím lůnu byla dvojčata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Stalo se, když rodila, že jedno vystrčilo ruku. Porodní bába vzala karmínový provázek, přivázala mu ho na ruku a řekla: Toto vyjde první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Avšak když vtáhl ruku zpět, hle, vyšel jeho bratr. Řekla: Jakou trhlinu jsi pro sebe protrhl? I dali mu jméno Peres.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Potom vyšel jeho bratr, který měl na ruce karmínový provázek. Jemu dali jméno Zerach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Josef byl přiveden dolů do Egypta. Od Izmaelitů, kteří ho tam odvedli, ho koupil faraonův dvorní úředník, Egypťan Potífar, velitel tělesné stráže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'A Hospodin byl s Josefem, a proto ⌈byl úspěšný člověk.⌉ Zůstal v domě svého egyptského pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Jeho pán viděl, že Hospodin je s ním a že všemu, co dělá, Hospodin dopřává v jeho rukou úspěch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Josef nalezl v jeho očích milost a sloužil jemu samému. Potífar ho ustanovil nad svým domem a všechno, co měl, svěřil do Josefových rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'A od té doby, co ho ustanovil nad svým domem a nade vším, co měl, Hospodin kvůli Josefovi Egypťanovu domu žehnal. Hospodinovo požehnání bylo na všem, co měl, jak v domě, tak na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Všechno, co měl, zanechal v Josefových rukou a nestaral se s ním o nic kromě chleba, který jídal. Josef byl ⌈krásné postavy a krásného vzhledu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Stalo se po těch věcech, že žena jeho pána pozvedla k Josefovi oči a řekla: Lehni si se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'On však odmítl a ženě svého pána řekl: Hle, ⌈když jsem zde,⌉ můj pán se nestará o to, co se v domě děje, a všechno, co má, svěřil do mých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Nikdo není v tomto domě větší než já a nevyňal z mé správy nic kromě tebe, protože jsi jeho žena. Jak bych mohl spáchat takové zlo a zhřešit proti Bohu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'I když mluvila k Josefovi den co den, neuposlechl ji, aby k ní ulehl a byl s ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Jednoho dne přišel do domu, aby dělal svou práci, a nikdo z domácích v domě nebyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Tu ho uchopila za oděv se slovy: Lehni si se mnou! Zanechal svůj oděv v její ruce, utíkal a odešel ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Když viděla, že zanechal svůj oděv v její ruce a utekl ven,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'svolala své domácí a říkala jim: Podívejte, přivedl nám hebrejského muže, aby s námi laškoval! Přišel ke mně, aby se mnou ležel, ale hlasitě jsem křičela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Když uslyšel, že jsem ⌈začala hlasitě křičet,⌉ zanechal svůj oděv u mě, utíkal a odešel ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Nechala si jeho oděv u sebe, dokud jeho pán nepřišel domů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'a povídala mu totéž: Přišel ke mně ten hebrejský otrok, kterého jsi nám přivedl, a chtěl se mnou laškovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Ale když jsem ⌈začala hlasitě křičet,⌉ zanechal svůj oděv u mne a utekl ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Když jeho pán slyšel slova své ženy, která mu říkala: To a to mi tvůj otrok udělal, vzplanul hněvem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'vzal ho a uvrhl ho do věznice, do místa, kde byli vězněni královští vězni. Tak se tam ocitl ve věznici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Ale Hospodin byl s Josefem a rozprostřel nad ním milosrdenství a dal mu milost v očích velitele věznice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Velitel věznice svěřil všechny vězně ve věznici do Josefových rukou, takže řídil všechno, co se tam dělalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Velitel věznice nedohlížel na nic, co bylo v jeho rukou, protože Hospodin byl s ním. Co Josef činil, tomu Hospodin dopřával úspěch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'I stalo se po těch událostech, že se číšník egyptského krále a pekař prohřešili proti svému pánu, egyptskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'A farao se rozhněval na své dva dvorní úředníky, na vrchního číšníka a na vrchního pekaře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'a dal je do vazby v domě velitele tělesné stráže, do věznice, kde byl vězněn Josef.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Velitel tělesné stráže určil Josefa k nim, aby jim sloužil. Tak byli ve vazbě nějaký čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Oba měli sen. Oba měli sen téže noci; ⌈sen každého měl svůj význam,⌉ sen číšníka i pekaře egyptského krále, kteří byli ve věznici vězněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Když k nim Josef ráno přišel a uviděl je, hle, byli skleslí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Zeptal se tedy faraonových dvorních úředníků, kteří s ním byli ve vazbě v domě jeho pána: Proč jsou dnes vaše tváře tak skleslé?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Odpověděli mu: Oba jsme měli sen a není, kdo by jej vyložil. Josef jim řekl: Což nenáleží výklad Bohu? Prosím, vyprávějte mi je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Tedy vrchní číšník vyprávěl Josefovi svůj sen a říkal mu: Ve svém snu jsem před sebou uviděl vinnou révu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'a na té révě tři ratolesti. Jakmile vypučela, vyrazily její květy a zrály její vinné hrozny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'V ruce jsem měl faraonův pohár, bral jsem hrozny, vymačkal jsem je do faraonova poháru a podal jsem pohár faraonovi do ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Josef mu řekl: Toto je výklad snu. Tři ratolesti jsou tři dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Během tří dnů farao povýší tvou hlavu a vrátí tě do tvého úřadu. A budeš podávat faraonův pohár do jeho ruky podle původního práva, když jsi byl jeho číšníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Jen si na mě vzpomeň, až se ti dobře povede, a prokaž mi, prosím, milosrdenství: zmiň se o mně faraonovi a nechej mě vyjít z tohoto domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Vždyť jsem byl vskutku ukraden z hebrejské země a ani zde jsem se nedopustil ničeho, zač by mne měli vsadit do žaláře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Když vrchní pekař viděl, že vyložil sen dobře, řekl Josefovi: Také já jsem ve svém snu něco viděl: Hle, tři koše pečiva byly na mé hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'V nejhořejším koši bylo jídlo pro faraona -- různé pekařské výtvory, a ptáci je jedli z koše na mé hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Josef odpověděl slovy: Toto je výklad snu. Tři koše jsou tři dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Během tří dnů farao povýší tvou hlavu od tebe a pověsí tě na dřevo. Ptáci z tebe budou jíst maso.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Stalo se třetího dne -- v den faraonových narozenin, že udělal hostinu všem svým otrokům a mezi svými otroky povýšil hlavu vrchního číšníka i hlavu vrchního pekaře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Vrchního číšníka navrátil do jeho úřadu, a podával pohár do faraonovy ruky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'a vrchního pekaře pověsil, tak jak jim vyložil Josef.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Vrchní číšník však na Josefa nepamatoval, ale zapomněl na něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Po dvou letech se stalo, že farao měl sen: Hle, stál u Nilu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Vtom z Nilu vystoupilo sedm tučných krav krásného vzhledu, které se pásly v sítině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'A tu za nimi z Nilu vystoupilo sedm jiných krav, ošklivého vzhledu a vychrtlých, a postavily se vedle krav na břehu Nilu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'A ty vychrtlé krávy ošklivého vzhledu sežraly těch sedm tučných krav krásného vzhledu. Pak farao procitl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Nato usnul a měl druhý sen: Hle, na jednom stéble vyrůstalo sedm klasů, plných a pěkných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'A hle, za nimi vyráželo sedm klasů řídkých, spálených východním větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'A ty řídké klasy pohltily těch sedm klasů plných a silných. Farao procitl a hle, byl to sen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Ráno byl jeho duch rozrušen. ⌈Dal si tedy zavolat⌉ všechny egyptské kouzelníky a mudrce. Farao jim vypravoval své sny, ale nebyl, kdo by je faraonovi vyložil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Tu k faraonovi promluvil vrchní číšník: Musím dnes připomenout své hříchy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Farao se rozhněval na své otroky a dal mne a vrchního pekaře do vazby v domě velitele tělesné stráže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Téže noci jsme měli sen, já i on. Každému z nás se zdál sen, který měl svůj význam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Byl tam s námi hebrejský mládenec, otrok velitele tělesné stráže. Jemu jsme je vyprávěli a on nám naše sny vyložil. Každému vyložil jeho sen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'A jak nám je vyložil, tak se stalo: mě farao do úřadu vrátil a jeho pověsil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Farao ⌈si dal zavolat⌉ Josefa. Rychle ho přivedli ze žaláře. Oholil se, vyměnil si oděv a přišel k faraonovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Farao Josefovi řekl: Měl jsem sen a není, kdo by ho vyložil. Ale o tobě jsem slyšel, že když vyslechneš sen, můžeš ho vyložit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Josef faraonovi odpověděl: Ne já, ale Bůh dá odpověď k faraonovu prospěchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Farao tedy Josefovi řekl: Ve svém snu, hle, stál jsem na břehu Nilu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Vtom z Nilu vystoupilo sedm tučných krav krásného vzezření, které se pásly v sítině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'A tu za nimi vystoupilo sedm jiných krav, ubohých, velmi ošklivého vzezření a vyzáblých. Takovou ošklivost jsem neviděl v celé egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'A ty vyzáblé a ošklivé krávy sežraly těch sedm prvních tučných krav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'I když se dostaly do jejich břicha, nebylo znát, že do nich vešly, a jejich vzhled byl špatný tak jako na počátku. Pak jsem procitl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Nato jsem ve snu viděl, hle, sedm klasů vyrůstalo na jednom stéble, plných a pěkných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'A hle, za nimi vyráželo sedm klasů jalových, řídkých, spálených východním větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'A ty řídké klasy pohltily těch sedm pěkných klasů. Pověděl jsem to kouzelníkům, ale význam mi nikdo neoznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Josef faraonovi řekl: Faraonův sen je jeden a týž: Bůh faraonovi oznámil to, co bude dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Těch sedm pěkných krav je sedm let, i těch sedm pěkných klasů je sedm let. Je to jeden sen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'A sedm krav vyzáblých a ošklivých, vystupujících za nimi, je sedm let. Také sedm klasů prázdných, spálených východním větrem, je sedm let hladu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'To je to, co jsem řekl faraonovi: Bůh faraonovi ukázal, co bude dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Hle, přichází sedm let velké hojnosti po celé egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Po nich však nastane sedm let hladu a v egyptské zemi bude všechna ta hojnost zapomenuta; hlad bude zemi ničit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Pak nebude v zemi znát nic z té hojnosti kvůli hladu, který bude potom, protože bude velmi tíživý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'A sen se faraonovi opakoval dvakrát, protože ta věc je Bohem pevně stanovena a Bůh ji pospíchá vykonat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nuže tedy, ať si farao vyhlédne ⌈rozumného a moudrého muže⌉ a ustanoví ho nad egyptskou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Ať farao zřídí a ustanoví nad zemí dohlížitele a v sedmi letech hojnosti vybírá pětinu úrody egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Ať shromažďují všechnu potravu těchto přicházejících dobrých let. Ať shromažďují zrno k jídlu ve městech pod moc faraonovu a střeží je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'To jídlo bude zásobou pro zemi na sedm let hladu, která budou v egyptské zemi. Tak země nebude hladem zničena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Tato řeč ⌈se líbila faraonovi i všem⌉ jeho otrokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'I řekl farao svým otrokům: Zda se najde někdo podobný tomuto muži, v němž je ⌈Duch Boží?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Farao tedy řekl Josefovi: Potom, co ti Bůh dal toto všechno poznat, nikdo není tak rozumný a moudrý jako ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ty budeš nad mým palácem a podle tvých příkazů se bude řídit všechen můj lid. Budu tě převyšovat pouze trůnem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Dále farao Josefovi řekl: Hle, ustanovil jsem tě nad celou egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Nato farao sňal z ruky svůj pečetní prsten a dal ho na ruku Josefovu, oblékl mu roucho z jemného plátna a na jeho šíji vložil zlatý řetěz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Potom ho dal vozit ve svém druhém voze a provolávat před ním: Na kolena! Tak ho ustanovil nad celou egyptskou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Farao ještě Josefovi řekl: Já jsem farao. A bez tebe nikdo v celé egyptské zemi nezvedne ruku ani nohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Farao dal Josefovi jméno Safenat Paneach a dal mu za ženu Asenatu, dceru Potífery, kněze z Ónu. Pak Josef vyšel procestovat egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Josefovi bylo třicet let, když stál před faraonem, egyptským králem. Pak Josef vyšel od faraona a procházel celou egyptskou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'A v sedmi letech hojnosti vydávala země přebohatou úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Shromažďoval tedy všechnu potravu, která byla sedm let v egyptské zemi, a ukládal ji ve městech. Uvnitř každého města ukládal potravu z jeho polí, která byla kolem něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Tak Josef nashromáždil obilí jako mořského písku, veliké množství, takže přestal počítat, protože ho bylo bezpočtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Dříve než přišel rok hladu, Josefovi se narodili dva synové, které mu porodila Asenat, dcera Potífery, kněze z Ónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Josef dal prvorozenému jméno Manases, neboť řekl: Bůh mi dal zapomenout na všechno mé trápení a na celý dům mého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'A druhému dal jméno Efrajim, neboť řekl: Bůh mě učinil plodným v zemi mého soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Když sedm let hojnosti, která byla v egyptské zemi, pominulo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'začalo přicházet sedm let hladu, jak řekl Josef. Nastal hlad ve všech zemích, ale v celé egyptské zemi byl chléb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Když celá egyptská země hladověla a lid křičel k faraonovi o chléb, farao řekl celému Egyptu: Jděte k Josefovi a udělejte, co vám řekne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Hlad byl po celé zemi. Josef otevřel všechny sýpky a prodával Egypťanům obilí. A hlad se v egyptské zemi rozmáhal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'A všechny země přicházely do Egypta k Josefovi nakupovat obilí, protože hlad se rozmohl po celém světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Když Jákob viděl, že v Egyptě je obilí, řekl svým synům: Proč civíte jeden na druhého?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'A řekl: Hle, slyšel jsem, že v Egyptě je obilí. Sestupte tam a nakupte tam pro nás obilí, abychom zůstali naživu a nezemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Deset Josefových bratří tedy sestoupilo, aby v Egyptě nakoupili obilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Josefova bratra Benjamína Jákob s jeho bratry neposlal, protože si říkal: Jen aby ho nepotkalo neštěstí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Izraelovi synové přišli nakupovat obilí spolu s dalšími, kteří také šli, protože v kenaanské zemi byl hlad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Josef byl pánem nad zemí, byl tím, kdo prodával všemu lidu země. Josefovi bratři přišli a klaněli se mu tváří k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Když Josef spatřil své bratry, poznal je, ale nedal se jim poznat a mluvil s nimi tvrdě. Řekl jim: Odkud jste přišli? Odpověděli: Z kenaanské země, abychom nakoupili potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Josef své bratry poznal, ale oni ho nepoznali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Tu si Josef vzpomněl na sny, které o nich měl. Řekl jim: Jste zvědové! Přišli jste, abyste viděli ⌈nechráněná místa⌉ země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Odpověděli mu: Ne, pane, tvoji otroci přišli, aby nakoupili potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Všichni jsme synové jednoho muže. Jsme poctiví lidé, tvoji otroci nejsou zvědové!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Řekl jim: Ne, neboť jste přišli, abyste viděli nechráněná místa země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Odpověděli: Nás, tvých otroků, bylo dvanáct bratrů, synů jednoho muže v kenaanské zemi. A hle, nejmladší je dnes s naším otcem a jeden už není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'A Josef jim řekl: Je to tak, jak jsem vám říkal: Jste zvědové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Tak budete přezkoušeni: Jakože živ je farao, nevyjdete odsud, pokud váš nejmladší bratr nepřijde sem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Pošlete jednoho z vás, ať přivede vašeho bratra, zatímco vy budete spoutáni. Tak budou přezkoušena vaše slova, máte–li pravdu. Jestli ne, jakože živ je farao, jste zvědové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Pak je ⌈dal spolu⌉ na tři dny do vazby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Třetího dne jim Josef řekl: Udělejte toto a zůstanete naživu; já se bojím Boha:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Jste–li poctiví, jeden váš bratr zůstane spoután ve vašem vězení a vy jděte a přineste svým hladovějícím rodinám obilí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'a svého nejmladšího bratra přiveďte ke mně. Tak se vaše slova potvrdí a nezemřete. I učinili tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'A říkali jeden druhému: Jistě neseme vinu za svého bratra. Viděli jsme soužení jeho duše, když nás prosil o milost, a nevyslyšeli jsme ho. Proto na nás přišlo toto soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Rúben jim odpověděl: Což jsem vám neříkal, abyste proti chlapci nehřešili? Ale neposlechli jste. A hle, již je jeho krev vyhledávána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Oni však nevěděli, že Josef rozumí, protože mezi nimi byl tlumočník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Odvrátil se od nich a plakal. Pak se k nim obrátil, mluvil s nimi, vybral z nich Šimeóna a před jejich očima ho svázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Pak Josef přikázal, aby jejich nádoby naplnili obilím a aby vrátili každému jeho peníze do jeho pytle a aby jim dali potravu na cestu. Když jim to udělali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'naložili své obilí na osly a vyšli odtamtud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Když jeden otevřel svůj pytel, aby v tábořišti dal svému oslu krmivo, uviděl své peníze. Hle, byly nahoře v jeho žoku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'A řekl svým bratrům: Mé peníze jsou zpět! Zase zde v mém žoku! ⌈Byli ohromeni strachem⌉ a roztřeseně se obraceli jeden na druhého se slovy: Co nám to Bůh udělal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Když přišli do kenaanské země ke svému otci Jákobovi, oznámili mu všechno, co se jim přihodilo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Ten muž, pán země, s námi mluvil tvrdě a pokládal nás za zvědy ve své zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Řekli jsme mu: Jsme poctiví, nejsme zvědové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Bylo nás dvanáct bratrů, synů našeho otce. Jeden už není a nejmladší je teď s naším otcem v kenaanské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Ten muž, pán země, nám odpověděl: Podle toho poznám, že jste poctiví. Jednoho svého bratra ponechte u mě a vezměte obilí pro své hladovějící rodiny a jděte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Pak přiveďte svého nejmladšího bratra ke mně. Tak poznám, že nejste zvědové, ale jste poctiví. Vašeho bratra vám vydám a budete moci procházet zemí jako kupci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Potom se stalo, když vyprazdňovali své pytle, hle, každý měl svůj váček s penězi ve svém pytli! Když oni i jejich otec uviděli váčky peněz, dostali strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Jejich otec Jákob jim řekl: Připravujete mě o děti! Josef není, Šimeón není, a teď vezmete Benjamína! ⌈Všechno to na mě dopadá!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Rúben svému otci řekl: Dva mé syny můžeš dát usmrtit, jestliže ho nepřivedu k tobě. Svěř ho do mých rukou a já ho přivedu zpět k tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Ale Jákob řekl: Můj syn s vámi nesestoupí, protože jeho bratr je mrtev a on zůstal sám. Kdyby ho potkalo neštěstí na cestě, kterou půjdete, s žalem byste přivedli mé šediny dolů do podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Hlad v zemi byl tíživý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Když dojedli obilí, které přivezli z Egypta, otec jim řekl: Nakupte nám znovu trochu potravy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Juda mu odpověděl: Ten muž nás výslovně varoval slovy: Nespatříte mou tvář, ne bude –li váš bratr s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Jestliže pošleš našeho bratra s námi, sestoupíme do Egypta a nakoupíme ti potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Ale jestli ho nepošleš, nesestoupíme, protože ten muž nám řekl: Neuvidíte mou tvář, ne bude –li váš bratr s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Nato Izrael řekl: Proč jste mi způsobili takové zlo, že jste tomu muži oznámili, že máte dalšího bratra?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Odpověděli: Ten muž se nás zevrubně vyptával na naše příbuzenstvo, ptal se: Žije ještě váš otec? Máte ještě bratra? Oznamovali jsme mu to na jeho přímé otázky. Cožpak jsme jen tušili, že řekne: Přiveďte svého bratra sem dolů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Pak Juda řekl svému otci Izraelovi: Pošli chlapce se mnou, ať vstaneme a vyjdeme, abychom zůstali naživu a nezemřeli my ani ty ani naše děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Já se za něho zaručím, ode mě ho budeš vyžadovat. Jestliže ho nepřivedu k tobě a nepostavím ho před tebe, budu před tebou navždy vinen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Neboť kdybychom neváhali, už bychom tu byli dvakrát zpátky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Jejich otec Izrael jim řekl: Když je to tak, udělejte tedy toto: Vezměte z ⌈nejlepších plodů⌉ země do svých nádob a sneste tomu muži jako dar trochu balzámu, trochu medu, ladanum, myrhu, pistácie a mandle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Vezměte s sebou dvojnásobně peněz. Peníze, které byly zpět navráceny nahoru do vašich žoků, vlastnoručně vraťte; možná to byl omyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Vezměte svého bratra, vstaňte a vraťte se k tomu muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'A Bůh Všemohoucí kéž vám dá dojít slitování před tím mužem, a on vám propustí vašeho druhého bratra i Benjamína. A já, jestli se stanu bezdětným, stanu se bezdětným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Ti muži tedy vzali ten dar, vzali s sebou dvojnásobně peněz i Benjamína, vstali a sestoupili do Egypta a postavili se před Josefem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Když Josef uviděl Benjamína s nimi, řekl ⌈správci svého domu:⌉ Uveď ty muže do domu a ⌈nechej něco porazit a připravit,⌉ protože ti muži budou se mnou v poledne jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Ten člověk udělal, co Josef řekl, a uvedl muže do Josefova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Ti dostali strach, že byli přivedeni do Josefova domu, a říkali si: Kvůli těm penězům, které byly na počátku navráceny do našich žoků, jsme přivedeni, aby se na nás vrhli, aby se nás zmocnili a aby nás vzali za otroky i s našimi osly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Přistoupili tedy k muži, který byl správcem Josefova domu, a mluvili s ním ve vchodu domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Říkali: Dovol, pane, poprvé jsme sem sestoupili, abychom nakoupili potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'A když jsme přišli do tábořiště a otevřeli své žoky, hle každý měl své peníze nahoře ve svém žoku, peníze v plné váze. Donesli jsme je zpět s sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'A další peníze jsme přinesli s sebou, abychom nakoupili potravu. Nevíme, kdo nám dal naše peníze do žoků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Odpověděl: Buďte klidní, nebojte se. Váš Bůh, Bůh vašeho otce vám dal skrytý poklad do vašich žoků; vaše peníze se ke mně dostaly. Pak k nim vyvedl Šimeóna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Potom ten člověk uvedl muže do Josefova domu, podal vodu, aby si umyli nohy, a dal krmivo jejich oslům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Oni připravili ten dar, než Josef v poledne přišel, protože slyšeli, že tam budou jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Když Josef přišel domů, přinesli mu dar, který vzali s sebou do domu, a klaněli se mu k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Zeptal se, jak se jim daří, a řekl: Daří se dobře vašemu starému otci, o kterém jste mluvili? Je ještě naživu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Odpověděli: Tvému otroku, našemu otci, se daří dobře. Je ještě živ. Pak poklekli a klaněli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Pozvedl oči a uviděl svého bratra Benjamína, syna své matky, a zeptal se: Toto je váš nejmladší bratr, o kterém jste mi říkali? A řekl: Bůh ti buď milostiv, můj synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Josef pospíchal pryč, protože se roznítila jeho náklonnost k bratrovi a chtěl plakat. Vešel tedy do pokoje a tam se rozplakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Pak si umyl tvář a vyšel. Se sebeovládáním řekl: Předkládejte jídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Předkládali zvlášť jemu, zvlášť jim a zvlášť Egypťanům, kteří jedli s ním; Egypťané totiž nemohou jíst s Hebreji, protože to je pro Egypťany ohavnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Seděli před ním od prvorozeného podle jeho prvorozenství až po nejmladšího podle jeho mládí a ti muži užasle hleděli jeden na druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Nechal jim od sebe nosit čestné porce a Benjamínova porce byla pětkrát větší než porce jich všech; a pili s ním, až se opili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Josef přikázal ⌈správci svého domu:⌉ Naplň žoky těchto mužů potravou tak, jak budou moci unést, a vlož peníze každého nahoru do jeho žoku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Můj kalich, ten stříbrný kalich, vlož s penězi za jeho obilí nahoru do žoku toho nejmladšího. Správce učinil všechno, co Josef řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Když se ráno rozjasnilo, byli ti muži propuštěni i se svými osly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Vyšli z města, ještě nebyli daleko, a Josef řekl ⌈správci svého domu:⌉ Vstaň, pronásleduj tyto muže a až je dostihneš, řekni jim: Proč jste za dobro odplatili zlem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Což to není kalich, z něhož pije můj pán? Vždyť z něho on věští! Tím, co jste učinili, jste spáchali zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Když je dostihl, řekl jim ona slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Odpověděli mu: Proč můj pán mluví taková slova? Ať je to od tvých otroků vzdáleno, aby učinili něco takového!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Hle, peníze, které jsme nalezli nahoře ve svých žocích, jsme ti přinesli zpět z kenaanské země. Jak bychom mohli z domu tvého pána ukrást stříbro nebo zlato?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'U koho z tvých otroků se to nalezne, ten ať zemře, a také my se staneme otroky mého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Odpověděl: Tedy dobrá, bude to podle vašich slov: U koho se to najde, ten bude mým otrokem a vy budete volni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Tu každý rychle sundal na zem svůj žok a každý svůj žok otevřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Prohlídka začala u nejstaršího a skončila u nejmladšího. Kalich se našel v Benjamínově žoku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Roztrhli svá roucha, každý naložil svého osla a vraceli se do města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Když Juda a jeho bratři přišli do Josefova domu, on tam ještě byl. Tu padli před ním na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'A Josef jim řekl: Jaký skutek jste to provedli? Což nevíte, že muž jako já dokáže věštit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda odpověděl: Co můžeme mému pánu říci? Co máme povídat? A jak se ospravedlníme? Bůh postihl provinění tvých otroků. Hle, jsme otroky mého pána, i my, i ten, u něhož se nalezl kalich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Josef odpověděl: Ať je to ode mne vzdáleno, abych to učinil. Muž, u něhož se ten kalich našel, ten bude mým otrokem, a vy jděte v pokoji ke svému otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Juda k němu přistoupil a řekl: Dovol, prosím, můj pane, ať tvůj otrok promluví k svému pánu; ať tvůj hněv nevzplane proti tvému otroku, protože ty jsi jako farao.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Můj pán se svých otroků ptal: Máte otce nebo bratra?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Řekli jsme mému pánu: Máme starého otce a malého chlapce, který se mu narodil ve stáří. Jeho bratr je mrtev a po své matce zůstal on sám; jeho otec ho miluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Řekl jsi svým otrokům: Přiveďte ho ke mně dolů, ať ⌈ho uvidím na vlastní oči.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Odpověděli jsme mému pánu, že chlapec nemůže opustit svého otce. Kdyby opustil svého otce, on by zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Řekl jsi svým otrokům: Jestliže váš nejmladší bratr nesestoupí s vámi, nespatříte již moji tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Když jsme vystoupili ke tvému otroku, mému otci, oznámili jsme mu slova mého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Potom náš otec řekl: Nakupte nám znovu trochu potravy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Odpověděli jsme: Nemůžeme tam sestoupit. Pouze bude–li náš nejmladší bratr s námi, pak sestoupíme, neboť nemůžeme spatřit tvář toho muže, pokud náš nejmladší bratr nebude s námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'A tvůj otrok, můj otec, nám řekl: Vy víte, že mi má žena porodila dva syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Jeden mi odešel. Volal jsem: Jistě byl rozsápán, byl rozsápán! Až dosud jsem ho neviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'A i tohoto ode mne berete? Potká–li ho neštěstí, se zármutkem přivedete mé šediny dolů do podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'A teď, když přijdu k tvému otroku, svému otci, a chlapec, na němž otcova duše lpí, nebude s námi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'když otec uvidí, že s námi chlapec není, zemře. Tak tvoji otroci přivedou šediny tvého otroka, našeho otce, s žalem dolů do podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Vždyť tvůj otrok se za chlapce svému otci zaručil slovy: Jestliže ho nepřivedu k tobě, budu před svým otcem navždy vinen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Nyní tedy prosím, ať tvůj otrok zůstane místo toho chlapce za otroka mému pánu a ten chlapec ať se vrátí se svými bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Vždyť jak bych mohl přijít ke svému otci, když by chlapec nebyl se mnou? Ať nehledím na zlo, které by postihlo mého otce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Josef se už přede všemi, kdo kolem něho stáli, nemohl ovládat a zvolal: Všichni ode mne odejděte! Nikdo u něho tedy nezůstal, když se dal Josef svým bratrům poznat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Tu se dal do hlasitého pláče. Slyšeli to Egypťané a slyšel o tom faraonův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Josef bratrům řekl: Já jsem Josef. Je můj otec ještě naživu? Ale jeho bratři mu nebyli schopni odpovědět, protože z něho byli vyděšeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Josef tedy bratrům řekl: Jen ke mně přistupte. Když přistoupili, řekl: Já jsem Josef, váš bratr, kterého jste prodali do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'A teď se netrapte a nehněvejte se ⌈na sebe,⌉ že jste mne sem prodali. Neboť Bůh mne poslal před vámi pro zachování života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Protože to byly dva roky hladu v zemi, ale orba a žeň nebude ještě pět let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Bůh mne poslal před vámi, ⌈aby zajistil váš ostatek⌉ na zemi a aby vás zachoval při životě pro veliké vysvobození.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Nyní tedy ne vy jste mě sem poslali, nýbrž Bůh. On mě učinil otcem faraonovi, pánem celého jeho domu a vládcem celé egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Rychle vystupte k otci a řekněte mu: Toto vzkazuje tvůj syn Josef: Bůh mě učinil pánem celého Egypta. Neotálej a sestup ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Usadíš se v zemi Gošenu a budeš blízko mě ty, tvoji synové i synové tvých synů, tvůj brav i tvůj skot a vše, co máš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Budu se tam o tebe starat, protože bude ještě pět let hladu, abys nezchudl ty, tvůj dům ani nic z toho, co máš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Hle, vidí to vaše oči i oči mého bratra Benjamína, že ⌈já sám ⌉ k vám mluvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Povězte otci o vší mé slávě v Egyptě a o všem, co jste viděli. Pospěšte si a přiveďte otce sem dolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Tu padl na šíji svého bratra Benjamína a rozplakal se. I Benjamín plakal na jeho šíji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Pak políbil všechny bratry a plakal při nich. Teprve potom s ním jeho bratři byli schopni mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Když ve faraonově domě slyšeli zprávu, že přišli Josefovi bratři, bylo to ⌈milé faraonovi i jeho⌉ otrokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Farao Josefovi řekl: Řekni svým bratrům: Udělejte toto: Naložte náklad na svůj dobytek, jděte rychle do kenaanské země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'vezměte svého otce a své rodiny a přijďte ke mně. Dám vám to nejlepší z egyptské země a budete jíst tuk země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Dále máš přikázáno jim říct: Udělejte toto: Vezměte si z egyptské země vozy pro své děti a ženy a naložte svého otce a přijďte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Nelitujte svého zařízení, protože to nejlepší z celé egyptské země bude vaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'A Izraelovi synové tak učinili. Josef jim podle faraonova příkazu vydal vozy a dal jim zásobu potravin na cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Každému z nich dal proměnný oděv a Benjamínovi dal tři sta šekelů stříbra a pět proměnných oděvů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'A svému otci poslal toto: Deset oslů nesoucích ⌈nejlepší věci⌉ Egypta a deset oslic nesoucích obilí, chléb a potraviny pro otce na cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Když bratry propouštěl a oni odcházeli, řekl jim: Nedrážděte se po cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'I vystoupili z Egypta a přišli do kenaanské země ke svému otci Jákobovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'A oznámili mu: Josef ještě žije a nadto je vládcem celé egyptské země. Jeho srdce zůstalo netečné, protože jim nevěřil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Když mu vyprávěli všechno, co jim Josef říkal, a když viděl vozy, které ⌈pro něho⌉ Josef poslal, duch jejich otce Jákoba ožil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Izrael zvolal: Stačí! Můj syn Josef ještě žije! Půjdu a uvidím ho, dříve než zemřu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Izrael vyrazil se vším, co měl. Když přišel do Beer–šeby, obětoval oběti Bohu svého otce Izáka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Tu Bůh k Izraelovi v nočním vidění promluvil: Jákobe, Jákobe! On odpověděl: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Bůh řekl: Já jsem Bůh, Bůh tvého otce. Neboj se sestoupit do Egypta, protože tam z tebe učiním velký národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Já sestoupím do Egypta s tebou a já tě jistě zase vyvedu. A Josef položí ruku na tvé oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Jákob se tedy z Beer–šeby zvedl a Izraelovi synové naložili svého otce Jákoba, své malé děti a své ženy na vozy, které ⌈pro ně⌉ farao poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Vzali také svá stáda a svůj majetek, jejž nabyli v kenaanské zemi, a vešli do Egypta, Jákob a všechno jeho potomstvo s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Své syny a syny svých synů i své dcery a dcery svých synů -- všechno své potomstvo přivedl s sebou do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Toto jsou jména Izraelových synů, kteří přišli do Egypta: Jákob a jeho synové: Jákobův prvorozený Rúben');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'a Rúbenovi synové Chanók, Palú, Chesrón a Karmí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Šimeónovi synové: Jemúel, Jamín a Óhad, Jakín, Sóchar a Šaúl, syn Kenaanky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Synové Léviho: Geršón, Kehat a Merarí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Judovi synové: Ér, Ónan a Šela, Peres a Zerach; Ér a Ónan však zemřeli v kenaanské zemi. Synové Peresovi byli Chesrón a Chámul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Isacharovi synové: Tóla, Púva, Jób a Šimrón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Zabulónovi synové: Sered, Elón a Jachleel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'To jsou synové Ley, které porodila Jákobovi v Paddan–aramu, a také jeho dceru Dínu. Všech jeho synů a dcer bylo třicet tři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gádovi synové: Sifjón a Chagí, Šúni a Esbón, Éri, Aródi a Aréli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Ašerovi synové: Jimna a Jišva, Jišví a Bería a jejich sestra Serach. Beríovi synové byli Cheber a Malkíel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'To jsou synové Zilpy, kterou dal Lában své dceři Lee. Porodila je Jákobovi, šestnáct duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Synové Jákobovy ženy Ráchel: Josef a Benjamín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Josefovi se v egyptské zemi narodil Manases a Efrajim, které mu porodila Asenat, dcera Potífery, kněze z Ónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'A Benjamínovi synové: Bela, Beker a Ašbel, Géra a Naamán, Échi a Róš, Mupím, Chupím a Ard.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'To jsou synové Ráchelini, kteří se narodili Jákobovi; celkem čtrnáct duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Synové Danovi: Chúšim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Neftalího synové: Jachseel, Gúní, Jeser a Šilem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'To jsou synové Bilhy, kterou dal Lában své dceři Ráchel; porodila je Jákobovi, celkem sedm duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Všech, kdo přišli s Jákobem do Egypta, kteří pocházeli z jeho beder, kromě žen Jákobových synů, bylo celkem šedesát šest duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'A Josefovi synové, kteří se mu narodili v Egyptě, byli dva, tedy všech duší Jákobova domu, které vstoupily do Egypta, bylo sedmdesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Jákob poslal před sebou k Josefovi Judu, aby ⌈mu ukazoval cestu⌉ do Gošenu. Když vešli do země Gošenu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Josef zapřáhl svůj vůz a vyrazil do Gošenu naproti svému otci Izraelovi. Když se mu ukázal, padl mu kolem krku a dlouho na jeho šíji plakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Izrael řekl Josefovi: Teď můžu zemřít, potom, co jsem viděl tvoji tvář, protože jsi dosud živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Josef pak řekl svým bratrům a rodině svého otce: Půjdu to oznámit faraonovi. Řeknu mu: Moji bratři a rodina mého otce, kteří byli v kenaanské zemi, přišli ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Ti muži jsou pastýři ovcí, jsou to lidé zabývající se dobytkem. Přivedli své ovce a skot a všechno, co mají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'A když vás farao zavolá a zeptá se, jaké je vaše zaměstnání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'řeknete: Tvoji otroci jsou od svého mládí až dosud lidé zabývající se dobytkem, my i naši otcové, to abyste mohli zůstat v zemi Gošenu. Všichni pastýři ovcí jsou totiž Egypťanům odporní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Josef pak šel a oznámil faraonovi: Můj otec a bratři se svým bravem a skotem a vším, co mají, přišli z kenaanské země a jsou v zemi Gošenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Vzal pět mužů ze svých bratrů a postavil je před faraona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Farao jeho bratrům řekl: Jaké je vaše zaměstnání? Odpověděli faraonovi: Tvoji otroci jsou pastýři ovcí, my i naši otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'A řekli faraonovi: Přišli jsme, abychom jako cizinci pobývali v zemi, protože v kenaanské zemi je tíživý hlad a není pastva pro ovce tvých otroků. Nuže dovol, aby tvoji otroci pobývali v zemi Gošenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Farao řekl Josefovi: Tvůj otec a tvoji bratři přišli k tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egyptská země je před tebou. Svého otce a své bratry usídli v nejlepší zemi. Mohou bydlet v zemi Gošenu. A jestli znáš mezi nimi zdatné muže, ustanov je ⌈správci nad mým dobytkem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Pak Josef přivedl svého otce Jákoba, postavil ho před faraona a Jákob faraonovi požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Farao Jákobovi řekl: Kolik je let tvého života?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jákob faraonovi odpověděl: Času mého putování bylo sto třicet let. Nemnohá a zlá byla léta mého života a nedosahují let života mých otců v čase jejich putování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Pak Jákob faraonovi požehnal a odešel z faraonovy přítomnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Josef usídlil svého otce a své bratry a dal jim v egyptské zemi do vlastnictví půdu v nejlepší části země, v zemi Ramesesu, tak jak farao přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'A Josef zásoboval svého otce, bratry a celý dům svého otce potravou ⌈podle jejich počtu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Chléb nebyl v celé zemi, protože hlad byl velmi tíživý, a egyptská země i kenaanská země byly hladem zcela vyčerpány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Tak Josef shromáždil všechny peníze, které se nacházely v egyptské i v kenaanské zemi, za obilí, které nakupovali. Ty peníze Josef odvedl do faraonova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Když došly v egyptské a v kenaanské zemi peníze, všichni Egypťané přicházeli k Josefovi a říkali: Dej nám chléb! Proč máme před tebou umírat jen proto, že je konec s penězi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Josef řekl: Dejte svá stáda. Když je konec s penězi, dám vám chléb za vaše stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Přiváděli tedy k Josefovi svá stáda a Josef jim vydával chléb za koně nebo za stádo bravu, za stádo skotu nebo za osly. Tak je v tom roce zaopatřoval chlebem za všechna jejich stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Když ten rok uplynul, přicházeli k němu v dalším roce a říkali mu: Nebudeme před svým pánem tajit, že kromě toho, že došly peníze, i stáda dobytka náleží našemu pánu. Nezůstalo nám před naším pánem nic jiného než naše těla a naše půda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Proč ti máme před očima umírat my i naše půda? Kup nás i naši půdu za chléb a budeme i se svou půdou faraonovými otroky. Vydej zrno a zůstaneme naživu a nezemřeme a půda nebude opuštěná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Josef tedy kupoval všechnu egyptskou půdu pro faraona, neboť každý Egypťan prodával své pole, protože hlad na ně těžce doléhal. Tak se země ⌈dostala faraonovi,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'a lid, ten ⌈převedl k městům⌉ od jednoho konce egyptského území až po druhý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Pouze půdu kněží nekoupil, protože kněží měli příděl od faraona a jedli příděl, který jim farao dával. Proto neprodávali svou půdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Josef pak řekl lidu: Hle, dnes jsem vás i vaši půdu koupil faraonovi. Zde máte zrno a půdu osejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'A při sklizni budete dávat pětinu faraonovi a čtyři díly budou vaše k osetí pole, k jídlu pro vás a pro ty, kdo jsou ve vašich domech, a k jídlu pro vaše malé děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Odpověděli: Zachoval jsi nás při životě! Kéž nalézáme milost v očích svého pána! Budeme faraonovými otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'A Josef to určil jako ustanovení o egyptské půdě, platné až do tohoto dne: Pětinou patří faraonovi. Jen půda samotných kněží faraonovi nepatřila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Izrael pobýval v egyptské zemi, v zemi Gošenu; uchytili se v ní, byli plodní a velice se rozmnožili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Jákob žil v egyptské zemi sedmnáct let. Jákobových dnů, let jeho života bylo sto čtyřicet sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Když se přiblížil čas Izraelovy smrti, zavolal si svého syna Josefa a řekl mu: Jestliže jsem nyní nalezl milost ve tvých očích, vlož, prosím, ruku pod má bedra, a prokaž mi milosrdenství a věrnost: Prosím, nepohřbívej mě v Egyptě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Až ⌈ulehnu se svými otci,⌉ odnes mě z Egypta a pohřbi mě v jejich hrobě. Josef odpověděl: Ano, učiním podle tvého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'I řekl: Přísahej mi. A on mu přísahal. A Izrael se poklonil nad hlavou lůžka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Po těch věcech se stalo, že Josefovi řekli: Tvůj otec je nemocen. Vzal tedy s sebou své dva syny Manasesa a Efrajima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Když Jákobovi oznámili: Hle, přišel k tobě tvůj syn Josef, Izrael se vzchopil a posadil se na lůžku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Pak Jákob Josefovi řekl: Bůh Všemohoucí se mi ukázal v Lúzu v kenaanské zemi, požehnal mi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'a řekl mi: Hle, rozplodím a rozmnožím tě a učiním tě shromážděním národů a tvému potomstvu po tobě dám tuto zemi do věčného vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'A teď, tvoji dva synové, kteří se ti narodili v egyptské zemi do mého příchodu k tobě do Egypta, budou moji. Efrajim a Manases pro mne budou jako Rúben a Šimeón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'A děti, které zplodíš po nich, budou tvoje; pod jménem svých bratrů budou uvedeny ve svém dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Když jsem šel z Paddan–aramu, zemřela mi Ráchel na cestě v kenaanské zemi, ještě kus cesty do Efraty. Pohřbil jsem ji tam u cesty do Efraty, což je Betlém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Když Izrael uviděl Josefovy syny, zeptal se: Kdo je to?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Josef otci odpověděl: To jsou moji synové, které mi zde Bůh dal. Izrael řekl: Vezmi je ke mně, ať jim požehnám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Izraelovy oči byly stářím zakalené a dobře neviděl. Josef je k němu tedy přivedl a on je políbil a objal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'A Josefovi Izrael řekl: Nedoufal jsem, že ještě uvidím tvou tvář, a hle, Bůh mi dal spatřit i tvé potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Nato je Josef odtáhl od jeho kolen a ⌈poklonil se tváří⌉ k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Pak je Josef oba vzal, Efrajima svou pravicí proti Izraelově levici a Manasesa svou levicí proti Izraelově pravici a přivedl je blíž k němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'I vztáhl Izrael pravici a položil na hlavu Efrajima, který byl mladší, a levici na hlavu Manasesa. Zkřížil ruce, přestože Manases byl prvorozený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Potom Josefovi požehnal a řekl: Bůh, před nímž chodili moji otcové Abraham a Izák, Bůh, který je mým pastýřem od počátku až do tohoto dne,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'anděl, který mě ochraňoval ode všeho zlého, ať požehná tyto chlapce, ať je v nich jmenováno jméno mé a jméno mých otců Abrahama a Izáka. Ať se velice rozmnoží v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Když Josef viděl, že otec položil pravou ruku na Efrajimovu hlavu, ⌈nelíbilo se mu to ⌉ a uchopil otcovu ruku, aby ji přemístil z hlavy Efrajimovy na hlavu Manasesovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Josef otci řekl: Ne tak, otče, vždyť tento je prvorozený. Vlož pravici na jeho hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Jeho otec odmítl a řekl: Vím, můj synu, vím. I on se stane lidem a také on bude veliký. Avšak jeho mladší bratr bude větší než on a jeho potomstvo naplní národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'A požehnal jim toho dne se slovy: Tebou bude takto Izrael žehnat: Kéž tě Bůh učiní jako Efrajima a Manasesa! Tak postavil Efrajima před Manasesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Potom Izrael řekl Josefovi: Hle, umírám. Ale Bůh bude s vámi a přivede vás zpět do země vašich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'A já jsem ti nad tvé bratry dal jeden díl, který jsem vzal z ruky Emorejců mečem a lukem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'I povolal Jákob své syny a řekl: Shromážděte se, abych vám oznámil, co vás potká v posledních dnech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Shromážděte se a slyšte, synové Jákobovi, naslouchejte svému otci Izraelovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rúbene, tys můj prvorozený, má síla a prvotina mé mužnosti; výtečný v důstojnosti a výtečný v moci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Spustil ses jako voda, už nebudeš výtečný, protožes vstoupil na lože svého otce. Tehdy jsi je znesvětil. -- Vstoupil na mé lože.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Šimeón a Lévi jsou bratři; jejich nože jsou nástroji násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Do důvěrného společenství s nimi nevcházej, má duše, s jejich shromážděním se nesjednocuj, má slávo, protože ve svém hněvu zabili muže a pro zábavu ochromili býka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Proklet buď jejich hněv -- tak prudký, a jejich zuřivost -- tak krutá. Rozdělím je v Jákobovi a rozptýlím je v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Ty, Judo, tvoji bratři ti budou vzdávat chválu, tvá ruka bude na šíji tvých nepřátel. Budou se ti klanět synové tvého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Jsi lví mládě, Judo. ⌈Z kořisti jsi vyrostl,⌉ můj synu. Schoulil se, ulehl jako lev či jako lvice. Kdo ho přinutí povstat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Neodstoupí žezlo od Judy ani palcát ⌈od jeho nohou,⌉ dokud nepřijde ⌈ ten, kterému patří⌉ a ⌈jehož budou poslouchat národy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Přivazuje k vinnému keři své oslátko, k vybranému vínu mládě své oslice. Ve víně pere svůj oděv, v krvi hroznů své roucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Oči ⌈temnější než víno a zuby bělejší než⌉ mléko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulón se usídlí u mořského pobřeží, bude u přístavu lodí a jeho bok bude k Sidónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isachar je kostnatý osel, který leží mezi dvěma břemeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Když viděl, jak dobré je odpočinutí a jak nádherná je země, sklonil záda, aby nosil náklad, a dal se zotročit k nuceným pracím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan zjedná právo svému lidu jako jeden z kmenů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan bude hadem na cestě, rohatou zmijí na stezce, která kouše koně u kopyta, až jezdec padne nazpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Na tvou záchranu očekávám, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gád -- napadne jej horda, on však napadne její zadní voj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Ašer, jeho pokrm bude tučný, on bude dodávat královské lahůdky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Neftalí je vypuštěná laň. Vydává laskavá slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Josef je ⌈úrodný výhonek,⌉ úrodný výhonek nad pramenem, jeho ⌈ratolesti rostly⌉ přes zeď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Střelci ho provokovali, stříleli a zanevřeli na něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Ale ⌈jeho luk zůstal pevný a jeho paže byly obratné⌉ od Mocného Jákobova, odkud je Pastýř, Kámen Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'od Boha tvého otce, který ti pomáhá, a Všemohoucího, který ti požehná požehnáními nebes shůry, požehnáními hlubiny ležící dole, požehnáními prsů a lůna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Požehnání tvého otce převládla nad požehnáními ⌈Hóra až k hranicím⌉ pahorků věčných. Kéž spočinou na Josefově hlavě a na temenu nazíra mezi jeho bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamín je dravý vlk. Ráno požírá kořist a k večeru dělí lup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Ti všichni představují dvanáct kmenů Izraele, a toto je to, co jim řekl jejich otec, když jim žehnal. Každému z nich žehnal ⌈podle jeho požehnání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Potom jim přikázal toto: Já ⌈budu připojen ke svému lidu.⌉ Pohřběte mě k mým otcům v jeskyni, která je na poli Chetejce Efróna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'v jeskyni, která je na poli Makpele naproti Mamre v kenaanské zemi, kterou Abraham koupil spolu s polem od Chetejce Efróna do vlastnictví jako hrob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Tam pohřbili Abrahama a jeho ženu Sáru, tam pohřbili Izáka a jeho ženu Rebeku a tam jsem pohřbil Leu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'To pole s jeskyní na něm bylo získáno od Chetejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Když Jákob dokončil příkazy svým synům, vtáhl nohy do postele, skonal a byl připojen ke svému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Josef padl na tvář svého otce, plakal nad ním a líbal ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Pak přikázal svým otrokům lékařům, aby jeho otce balzamovali. Lékaři tedy Izraele balzamovali');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'plných čtyřicet dnů, protože taková je plná doba pro balzamování. A Egypťané nad ním plakali sedmdesát dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Přešly dny jeho oplakávání a Josef pověděl faraonovu domu: Jestliže jsem nalezl milost ve vašich očích, řekněte, prosím, faraonovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Otec mě zapřísahal slovy: Hle, umírám. Pohřbi mě tam, v mém hrobě, který jsem si vykopal v kenaanské zemi. Nyní dovol, abych vystoupil, pohřbil svého otce a vrátil se zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'A farao řekl: Vystup a pohřbi svého otce, tak jak tě zapřísahal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Josef tedy vyšel, aby pohřbil svého otce, a vyšli s ním všichni faraonovi otroci, starší jeho domu, a všichni starší egyptské země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'celý dům Josefův, jeho bratři a dům jeho otce. Pouze své malé děti, brav a skot zanechali v zemi Gošenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Vytáhla s ním také vozba a jezdci -- byl to ohromný doprovod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Přišli až k ⌈humnu Atádu,⌉ které je za Jordánem, a naříkali tam velikým a velmi žalostným kvílením; uspořádal svému otci sedmidenní smuteční obřad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Když obyvatelé té země, Kenaanci, viděli smuteční obřad na humně Atádu, řekli: To je ohromný smutek pro Egypťany. Proto mu dali jméno Ábel–misrajim, který je za Jordánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Pak mu jeho synové učinili tak, jak jim přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Jeho synové ho odnesli do kenaanské země a pohřbili ho v jeskyni na poli v Makpele naproti Mamre, kterou s tím polem koupil Abraham do vlastnictví jako hrob od Chetejce Efróna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Když pohřbil otce, vrátil se Josef do Egypta, on, jeho bratři a všichni, kteří s ním vystoupili pohřbít jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Když Josefovi bratři viděli, že je jejich otec mrtev, řekli si: Co když na nás Josef zanevře a zcela nám odplatí všechno to zlo, které jsme mu způsobili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Vzkázali tedy Josefovi: Tvůj otec před svou smrtí přikázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Josefovi řekněte toto: Ach odpusť, prosím, svým bratrům přestoupení a jejich hřích, neboť ti způsobili zlo; tak odpusť, prosím, otrokům Boha tvého otce jejich přestoupení. Když mu to řekli, Josef se rozplakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Pak přišli také jeho bratři, padli před ním a řekli: Hle, jsme tvoji otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Ale Josef jim odpověděl: Nebojte se. Cožpak jsem na místě Boha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vy jste proti mně sice zamýšleli zlo, Bůh to však zamýšlel k dobru, aby vykonal to, co je dnes, aby zachoval při životě početný lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'A tak se už nebojte. Já se budu starat o vás i o vaše malé děti. Tak je utěšoval a ⌈mluvil k jejich srdci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Josef pak pobýval v Egyptě, on i dům jeho otce; a Josef žil sto deset let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Josef viděl Efrajimovy syny do třetí generace. Také synové Makíra, syna Manasesova, se narodili ⌈na Josefova kolena.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Pak Josef řekl svým bratrům: Já umírám, ale Bůh vás jistě navštíví a vyvede vás z této země do země, kterou přisáhl dát Abrahamovi, Izákovi a Jákobovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'A zapřisáhl syny Izraelovy slovy: Bůh vás jistě navštíví, a pak odsud vyneste mé kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'A Josef zemřel ve věku sto deseti let. Balzamovali ho a položili do rakve v Egyptě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Toto jsou jména Izraelových synů, kteří přišli do Egypta. Přišli s Jákobem, každý se svou rodinou:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rúben, Šimeón, Lévi a Juda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isachar, Zabulón a Benjamín,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan a Neftalí, Gád a Ašer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Všech, kdo vyšli z Jákobových beder, bylo sedmdesát. Josef byl už v Egyptě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Pak zemřel Josef a všichni jeho bratři a celá ta generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Ale synové Izraele ⌈se plodili, hemžili a množili,⌉ a bylo jich velmi mnoho, takže ta země byla jimi naplněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'V Egyptě pak povstal nový král, který Josefa neznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'A řekl svému lidu: Hle, lid synů Izraele je početnější a mocnější než my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Nuže, jednejme s ním chytře, aby se dále nemnožil, a když by vypukla proti nám válka, aby se i on nepřidal k těm, kdo nás nenávidí, a bojoval by proti nám, a vyšel by ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Ustanovili tedy nad ním pracovní dozorce, aby jej utlačovali těžkými robotami. Stavěli faraonovi města skladů Pitom a Rameses.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Ale čím víc jej utlačovali, tím víc se množil a rozmáhal. Egypťané se začali synů Izraele děsit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Syny Izraele tedy surově nutili otročit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Ztrpčovali jim život tvrdou otročinou s hlínou a cihlami a všelijakými polními pracemi -- veškerou otročinou, ke které je surově nutili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Pak egyptský král přikázal hebrejským porodním bábám -- jedna se jmenovala Šifra a druhá Púa --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'toto: Když pomáháte při porodu Hebrejkám, hleďte na porodní stoličku: Bude–li to syn, usmrťte ho, bude–li to dcera, ať zůstane naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Porodní báby se však bály Boha a nepočínaly si podle toho, co jim řekl egyptský král, ale nechávaly chlapce naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Egyptský král si porodní báby zavolal a zeptal se jich: Proč to děláte, že necháváte chlapce naživu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Porodní báby faraonovi odpověděly: Hebrejky nejsou jako egyptské ženy, ale jsou plné života. Dříve než k nim porodní bába přijde, porodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'A Bůh prokázal těm porodním bábám dobro. Lid se dále množil a byl velmi zdatný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'A stalo se, protože se ty porodní báby bály Boha, že jim dal rodiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Pak farao přikázal všemu svému lidu: Každého syna, který se jim narodí, hoďte do Nilu, každou dceru nechejte naživu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Šel jeden muž z domu Léviho a vzal si za ženu lévijskou dceru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Žena otěhotněla a porodila syna. Když viděla, že je pěkný, skrývala ho tři měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Déle ho však nemohla skrývat, vzala pro něho papyrový košík, vymazala ho asfaltem a smolou, vložila do něj dítě a položila do rákosí ke břehu Nilu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Opodál se postavila jeho sestra, aby zjistila, co se s ním stane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Pak sestoupila faraonova dcera, aby se umývala v Nilu, zatímco její dívky se procházely na břehu Nilu. Když mezi rákosím uviděla košík, poslala svou otrokyni, aby jej přinesla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Když jej otevřela, uviděla dítě, byl to plačící chlapec. Měla s ním soucit a řekla: To je z hebrejských dětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Jeho sestra se pak faraonovy dcery zeptala: Mám jít a zavolat ti kojnou z hebrejských žen, aby ti dítě kojila?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Faraonova dcera jí odpověděla: Jdi. Dívka šla a zavolala matku dítěte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Faraonova dcera jí řekla: Vezmi toto dítě, odkoj mi ho a já ⌈ti dám odměnu.⌉ Žena tedy vzala dítě a kojila ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Když chlapec povyrostl, přivedla ho k faraonově dceři, a stal se jejím synem. Pojmenovala ho Mojžíš. Řekla: Vždyť jsem ho vytáhla z vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'I stalo se v době, kdy Mojžíš vyrostl, že vyšel ke svým bratrům a sledoval jejich těžké roboty. Tu zahlédl Egypťana, jak bije Hebreje, jednoho z jeho bratrů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Ohlédl se sem i tam, a když viděl, že tam nikdo není, zabil Egypťana a ukryl ho v písku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Když vyšel druhého dne, uviděl dva Hebreje, jak se rvou. Řekl útočníkovi: Proč biješ svého druha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Ten odpověděl: Kdo tě ustanovil vládcem a soudcem nad námi? Hodláš mne zabít, tak jako jsi zabil toho Egypťana? Mojžíš dostal strach a řekl si: Jistě je ta věc už známá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Když farao o té věci uslyšel, chtěl Mojžíše zabít. Mojžíš však před faraonem utekl a pobýval v midjánské zemi, usadil se u jedné studny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Midjánský kněz měl sedm dcer. Ty přišly, čerpaly vodu a naplnily napajedla, aby napojily ovce svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Tu přišli pastýři a vyháněli je. Mojžíš vstal, pomohl jim a napojil ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Když přišly ke svému otci Reúelovi, zeptal se: Proč jste dnes přišly tak brzy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Odpověděly: Nějaký Egypťan nás vysvobodil od pastýřů a také nám ochotně načerpal vodu a napojil ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Nato se zeptal svých dcer: A kde je? Proč jenom jste tam toho muže zanechaly? Zavolejte ho, ať pojí chléb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Mojžíš byl ochoten u toho muže zůstat a on dal Mojžíšovi svou dceru Siporu za manželku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Ta porodila syna a Mojžíš mu dal jméno Geršóm, neboť řekl: Byl jsem hostem v cizí zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Po dlouhé době egyptský král zemřel, ale synové Izraele dále vzdychali kvůli té otročině a volali o pomoc. Jejich volání o pomoc kvůli té otročině vystoupilo k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Bůh uslyšel jejich sténání a připomenul si svou smlouvu s Abrahamem, s Izákem a s Jákobem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'a Bůh pohleděl na syny Izraelovy a Bůh se jich ujal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mojžíš pásl ovce svého tchána, midjánského kněze Jitra. Jednou vedl ovce za pustinu a přišel k Boží hoře, k Chorébu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'I ukázal se mu Hospodinův anděl v ohnivém plameni zprostřed keře. Mojžíš hleděl, hle, keř planul ohněm, ale nebyl stravován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Mojžíš si řekl: Odbočím a prohlédnu si ten veliký úkaz, proč ten keř neshoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Když Hospodin viděl, že odbočil, aby se podíval, zavolal na něho Bůh z prostřed keře: Mojžíši, Mojžíši! Ten odpověděl: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'I řekl: Nepřibližuj se sem! Zuj si z nohou sandály, protože místo, na kterém stojíš, je půda svatá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Dále řekl: Já jsem Bůh tvého otce, Bůh Abrahamův, Bůh Izákův a Bůh Jákobův. Mojžíš si skryl tvář, protože se bál pohlédnout na Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Hospodin pak řekl: Dobře jsem viděl soužení svého lidu, který je v Egyptě, a slyšel jsem jejich volání kvůli jeho utlačovatelům. Vždyť vím o jeho bolestech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Sestoupil jsem, abych ho vysvobodil z moci Egypťanů a abych ho z oné země vyvedl do země dobré a rozlehlé, do země oplývající mlékem a medem, na místo Kenaanců, Chetejců, Emorejců, Perizejců, Chivejců a Jebúsejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Vždyť volání synů Izraele se nyní doneslo ke mně, a také jsem viděl útisk, kterým je Egypťané utiskují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Nuže pojď, pošlu tě k faraonovi, abys vyvedl můj lid, syny Izraele, z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Ale Mojžíš Bohu řekl: Kdo jsem já, abych šel k faraonovi a abych vyvedl syny Izraele z Egypta?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Tedy odpověděl: Vždyť budu s tebou. A toto ⌈ti bude znamením,⌉ že jsem tě poslal já: Až vyvedeš lid z Egypta, budete Bohu sloužit na této hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Ale Mojžíš Bohu odvětil: Hle, přijdu k synům Izraele a řeknu jim: Bůh vašich otců mě k vám poslal. Až se mě zeptají, jaké je jeho jméno, co jim odpovím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Bůh Mojžíšovi odpověděl: ⌈JSEM, KTERÝ JSEM.⌉ A pokračoval: Toto řekneš synům Izraele: JSEM mě poslal k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Bůh ještě Mojžíšovi řekl: Toto řekneš synům Izraele: Hospodin, Bůh vašich otců, Bůh Abrahamův, Bůh Izákův a Bůh Jákobův mě poslal k vám. Toto je mé jméno navěky, toto je mé připomenutí z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Jdi a shromáždi ⌈izraelské starší⌉ a řekni jim: Ukázal se mi Hospodin, Bůh vašich otců, Bůh Abrahamův, Izákův a Jákobův se slovy: Dobře jsem si všímal vás i toho, co se vám děje v Egyptě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'a řekl jsem: Vyvedu vás z egyptského soužení do země Kenaanců, Chetejců, Emorejců, Perizejců, Chivejců a Jebúsejců, do země oplývající mlékem a medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Poslechnou tě a půjdeš ty a izraelští starší k egyptskému králi a řeknete mu: Setkal se s námi Hospodin, ⌈Bůh Hebrejů.⌉ A tak dovol, ať jdeme třídenní cestou do pustiny obětovat Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Já však vím, že vás egyptský král nenechá jít bez zásahu mocné ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Proto vztáhnu svou ruku a budu bít Egypt všemi svými divy, které uprostřed něho učiním. Potom vás propustí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'A způsobím tomuto lidu přízeň v očích Egypťanů, takže když budete odcházet, nebudete odcházet s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Ale každá žena si vyžádá od sousedky a od příchozí ve svém domě stříbrné a zlaté předměty a oděvy. Naložíte to na své syny a dcery a vypleníte Egypt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mojžíš však odpověděl: Co jestli mi neuvěří a neposlechnou mě? Vždyť řeknou: Neukázal se ti Hospodin!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Ale Hospodin mu řekl: Co je to ve tvé ruce? Odpověděl: Hůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Hospodin řekl: Hoď ji na zem. Hodil ji na zem a stala se hadem. Mojžíš před ním utíkal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Pak Hospodin Mojžíšovi řekl: Vztáhni ruku a chyť ho za ocas! Vztáhl ruku, chytil ho a v jeho ruce se stal holí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Aby uvěřili, že se ti ukázal Hospodin, Bůh jejich otců, Bůh Abrahamův, Bůh Izákův a Bůh Jákobův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Hospodin mu ještě řekl: Dej ruku za ňadra. I dal ruku za ňadra. Když ji vyndal, hle, jeho ruka byla malomocná, bílá jako sníh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Nato řekl: Vrať ruku zpět za ňadra. Vrátil ruku zpět za ňadra, a když ji vyndal ven, tu byla znovu jako jeho tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'I stane se, když ti neuvěří a neuposlechnou první znamení, že uvěří dalšímu znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'I stane se, když neuvěří ani na tato dvě znamení a neposlechnou tě, vezmeš vodu z Nilu a vyleješ ji na ⌈suchou zem.⌉ A voda, kterou vezmeš z Nilu, se na ⌈suché zemi⌉ změní v krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mojžíš Hospodinu odpověděl: Dovol, Panovníku, nikdy jsem nebyl ⌈výmluvným člověkem,⌉ ani předtím, ani od té doby, co jsi promluvil ke svému otroku, protože jsem těžkopádných úst a těžkopádného jazyka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Hospodin mu však řekl: Kdo dal člověku ústa? Či kdo učiní němého nebo hluchého, vidícího nebo slepého? Zdali ne já, Hospodin?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Nyní tedy jdi, a já budu s tvými ústy a budu tě učit, co máš mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Nato odpověděl: Dovol, Panovníku, pošli prosím, ⌈ někoho jiného, koho pošleš.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Hospodin vzplanul proti Mojžíšovi hněvem a řekl: Cožpak není lévita Áron tvůj bratr? Vím, že on umí dobře mluvit! Nadto hle, vychází ti naproti a když tě uvidí, bude se ze srdce radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Budeš k němu mluvit a vložíš slova do jeho úst. A já budu s tvými ústy i s jeho ústy a budu vás učit, co budete mít dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'On bude za tebe mluvit k lidu. On bude tobě ústy a ty budeš jemu Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'A tuto hůl si vezmi do ruky. Budeš jí činit znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Mojžíš odešel, vrátil se ke svému tchánovi Jitrovi a řekl mu: Dovol, abych šel a navrátil se ke svým bratrům, kteří jsou v Egyptě, a uviděl, zda jsou ještě naživu. Jitro Mojžíšovi odpověděl: Jdi v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Pak Hospodin v Midjánu Mojžíšovi řekl: Jdi, navrať se do Egypta, protože již zemřeli všichni lidé, kteří ti usilovali o život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Mojžíš tedy vzal svou ženu a syny, posadil je na osla a vracel se do egyptské země. Do ruky si Mojžíš vzal Boží hůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Hospodin ještě řekl Mojžíšovi: Až se vrátíš do Egypta, ⌈hleď si všech divů, které jsem vložil do tvé ruky, a učiň je⌉ před faraonem. Já však posilním jeho srdce, takže lid nepropustí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Pak řekneš faraonovi: Toto praví Hospodin: Izrael je můj prvorozený syn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Řekl jsem ti: Propusť mého syna, aby mi sloužil, ale odmítl jsi ho propustit. Hle, zabiji tvého prvorozeného syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'I stalo se cestou v tábořišti, že ho potkal Hospodin a chtěl ho usmrtit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Tu vzala Sipora ostrý pazourek, odřízla předkožku svého syna, dotkla se jeho nohou a řekla: Jsi ⌈mi ženichem krve.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'A Hospodin ho nechal. Tehdy řekla: ženich krve, kvůli obřízce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Hospodin řekl Áronovi: Jdi do pustiny naproti Mojžíšovi. Šel, potkal ho u hory Boží a políbil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'A Mojžíš Áronovi oznámil všechna ⌈slova Hospodina, který ho poslal,⌉ a všechna znamení, která mu přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Pak šel Mojžíš s Áronem a shromáždili všechny starší synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Áron říkal všechna slova, která Hospodin řekl Mojžíšovi, a on činil ta znamení před očima lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'A lid uvěřil. ⌈Když slyšeli,⌉ že Hospodin navštívil syny Izraele a že pohleděl na jejich soužení, poklekli a klaněli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Potom Mojžíš a Áron předstoupili a řekli faraonovi: Toto praví ⌈Hospodin, Bůh Izraele:⌉ Propusť můj lid, ať mi v pustině slaví svátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Ale farao odpověděl: Kdo je Hospodin, jejž bych měl uposlechnout a propustit Izrael? Neznám Hospodina a také Izrael nepropustím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Tedy řekli: Setkal se s námi Bůh Hebrejů. Dovol, ať jdeme třídenní cestou do pustiny a obětujeme Hospodinu, svému Bohu, aby nás nezasáhl morem nebo mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Ale egyptský král jim odpověděl: Mojžíši a Árone, proč odvádíte lid od jejich díla? Jděte ke svým robotám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Faraon dále řekl: Hle, lidu země je teď mnoho a odradili byste je od jejich robot!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Toho dne farao přikázal nadřízeným v lidu a jeho správcům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Už nedávejte lidu slámu k výrobě cihel jako dříve. Ať sami jdou a nasbírají si slámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'A uložte jim stejné množství cihel, jaké dělali dříve. Neubírejte jim, protože jsou líní, proto křičí: Pojďme obětovat svému Bohu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Ať na ty muže těžce dolehne otročina, ⌈aby měli co dělat⌉ a nezajímali se o klamná slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Poháněči lidu a jeho správci tedy vyšli a řekli lidu: Toto praví farao: Už vám nebudu dávat slámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Sami si jděte sbírat slámu, kde ji najdete, avšak z vašeho úkolu se nic neubere.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Lid se rozprchl po celé egyptské zemi, aby sbíral ⌈ na strništích⌉ slámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Poháněči je nutili: Dokončete každý den své denní dílo, tak jako když sláma byla!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, '⌈Izraelští správci,⌉ které nad nimi ustanovili faraonovi poháněči, byli biti se slovy: Proč jste včera ani dnes nedokončili své určené množství cihel, tak jako dříve?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, '⌈Izraelští správci⌉ tedy přišli a úpěnlivě volali k faraonovi: Proč takto nakládáš se svými otroky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Tvým otrokům nedávají slámu a říkají nám: Dělejte cihly! Hle, tví otroci jsou biti, ⌈ale vinen je tvůj vlastní lid.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'On odpověděl: Jste lenoši líní! Proto říkáte: Pojďme obětovat Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'A teď běžte pracovat! Sláma vám dávána nebude, ale míru cihel budete dodávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, '⌈Izraelští správci⌉ viděli, že je s nimi zle, když bylo řečeno: Nesmíte ubírat ze svého každodenního množství cihel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Když vycházeli od faraona, potkali Mojžíše a Árona, kteří ⌈na ně čekali.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Řekli jim: Ať Hospodin na vás pohlédne a soudí, protože jste ⌈nás zošklivili⌉ v očích faraona i jeho otroků a dali jste do jejich rukou meč, aby nás zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Mojžíš se navrátil k Hospodinu a řekl: Panovníku, proč jsi ublížil tomuto lidu? Proč jenom jsi mě poslal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Od chvíle, kdy jsem přišel k faraonovi, abych mluvil ve tvém jménu, jednal s tímto lidem zle, a vůbec jsi svůj lid nevysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Hospodin Mojžíšovi odvětil: Nyní uvidíš, co učiním faraonovi, že kvůli silné ruce je propustí, ba kvůli silné ruce je vyžene ze své země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'I promluvil Bůh k Mojžíšovi a řekl mu: Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ukázal jsem se Abrahamovi, Izákovi a Jákobovi jako Bůh Všemohoucí, ale svým jménem Hospodin jsem jim nebyl znám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Ustanovil jsem s nimi také svou smlouvu, že jim dám kenaanskou zemi, zemi jejich putování, v níž pobývali jako cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Já jsem také slyšel sténání synů Izraele, jež Egypťané nutili otročit, a připomenul jsem si svou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Proto řekni synům Izraele: Já jsem Hospodin. Vyvedu vás zpod jha egyptských robot, vysvobodím vás z vaší otročiny. Ujmu se vás vztaženou paží ve velikých soudech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'A přijmu vás za svůj lid a budu vaším Bohem, a poznáte, že já Hospodin jsem váš Bůh, který vás vyvádí zpod jha egyptských robot.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Uvedu vás do země, o které jsem pozvednutím ruky přísahal, že ji dám Abrahamovi, Izákovi a Jákobovi. Vám ji dám do vlastnictví. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mojžíš takto mluvil k synům Izraele, ale neposlouchali Mojžíše pro malomyslnost a tvrdou otročinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, '⌈Pak Hospodin k Mojžíšovi promluvil:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Jdi a promluv k faraonovi, egyptskému králi, ať propustí syny Izraele ze své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Ale Mojžíš před Hospodinem říkal: Hle, synové Izraele mi nenaslouchali a jak mi bude naslouchat farao, nadto jsem ⌈ člověk neobratných úst!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Ještě Hospodin promluvil k Mojžíšovi a k Áronovi a ⌈dal jim příkaz⌉ ⌈pro syny Izraele a⌉ pro faraona, egyptského krále, aby vyvedl syny Izraele z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Toto jsou předáci ⌈domu svých otců:⌉ synové Rúbena, Izraelova prvorozeného: Chanók a Palú, Chesrón a Karmí. To jsou čeledi Rúbenovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Synové Šimeónovi: Jemúel, Jamín, Óhad, Jakín, Sóchar a Šaúl, syn Kenaanky. To jsou čeledi Šimeónovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'A toto jsou jména synů Léviho podle svých rodopisů: Geršón, Kehat a Merarí. ⌈Lévi žil⌉ sto třicet sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Synové Geršónovi: Libní a Šimeí podle svých čeledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Synové Kehatovi: Amrám, Jishár, Chebrón a Uzíel. Kehat žil sto třicet tři let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'A synové Merarího: Machlí a Muší. To jsou čeledi Léviho podle svých rodopisů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amrám si vzal za ženu Jókebed, svou tetu. Ta mu porodila Árona a Mojžíše. Amrám žil sto třicet sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Synové Jishárovi: Kórach, Nefeg a Zikrí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Synové Uzíelovi: Míšael, Elsáfan a Sitrí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Áron si vzal za ženu Elíšebu, dceru Amínadabovu, sestru Nachšónovu. Ta mu porodila Nádaba a Abíhúa, Eleazara a Ítamara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Synové Kórachovi: Asír, Elkána a Abíasaf. To jsou čeledi Kórachovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleazar, syn Áronův, si vzal za ženu jednu z dcer Pútíelových. Ta mu porodila Pinchasa. To jsou předáci lévijských rodů podle svých čeledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'To je ten Áron a Mojžíš, jimž Hospodin řekl: Vyveďte syny Izraele po oddílech z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'To oni mluvili k faraonovi, egyptskému králi, aby vyvedli syny Izraele z Egypta. Ten Mojžíš a Áron.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'To bylo tehdy, když Hospodin mluvil k Mojžíšovi v egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Hospodin promluvil k Mojžíšovi: Já jsem Hospodin. Řekni faraonovi, egyptskému králi, všechno, co ti říkám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Ale Mojžíš před Hospodinem řekl: Hle, jsem člověk neobratných úst. Jak mi bude farao naslouchat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'I řekl Hospodin Mojžíšovi: Pohleď, dal jsem tě faraonovi za Boha a tvůj bratr Áron bude tvým prorokem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Ty budeš mluvit všechno, co ti přikáži, a tvůj bratr Áron bude mluvit k faraonovi, aby propustil syny Izraele ze své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Já však zatvrdím faraonovo srdce a ačkoli rozmnožím svá znamení a své divy v egyptské zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'faraon vás neuposlechne. Avšak položím na Egypt svou ruku a vyvedu svůj lid, své oddíly synů Izraele z egyptské země skrze veliké soudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'A Egypťané poznají, že já jsem Hospodin, když vztáhnu ruku na Egypt a vyvedu syny Izraele z jejich středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mojžíš a Áron tak tedy učinili; jak jim Hospodin přikázal, tak učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mojžíšovi bylo osmdesát let a Áronovi bylo osmdesát tři let, když mluvili k faraonovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'I řekl Hospodin Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Když k vám farao promluví slovy: Učiňte nějaký div, řekneš Áronovi: Vezmi svou hůl a pohoď ji před faraonem. Stane se drakem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Mojžíš a Áron přišli k faraonovi a udělali to tak, jak Hospodin přikázal: Áron pohodil před faraonem a před jeho otroky svou hůl, a stala se drakem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Farao zavolal také mudrce a čaroděje, a také oni, egyptští kouzelníci, učinili svými čáry totéž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Pohodili všichni své hole a ty se staly draky. Hůl Áronova však jejich hole pohltila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Faraonovo srdce se však posilnilo a neuposlechl je, tak jak pověděl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Pak Hospodin řekl Mojžíšovi: Faraonovo srdce je tvrdé, nechce lid propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Jdi k faraonovi ráno, když vychází k vodě. ⌈Čekej na něho⌉ na břehu Nilu a do ruky si vezmi hůl, která se změnila v hada.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'A řekni mu: Hospodin, Bůh Hebrejů, mě k tobě poslal se slovy: Propusť můj lid, ať mi v pustině slouží! Ale až dosud jsi neuposlechl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Toto praví Hospodin: Podle toho poznáš, že já jsem Hospodin: Hle, holí, kterou mám v ruce, udeřím do vody v Nilu, a změní se v krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Ryby v Nilu uhynou a Nil bude páchnout, takže Egypťané nebudou schopni vodu z Nilu pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Pak Hospodin řekl Mojžíšovi: Řekni Áronovi: Vezmi svou hůl a vztáhni ruku nad egyptské vody. Nad jejich řeky, nad jejich kanály i nad jejich jezera a nad každou jejich vodní nádrž. Stanou se krví. Krev bude v celé egyptské zemi i v dřevěných a v kamenných nádobách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mojžíš a Áron učinili tak, jak Hospodin přikázal. Áron zvedl hůl a udeřil do vody v Nilu před očima faraona a jeho otroků, a všechna voda v Nilu se změnila v krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Ryby v Nilu uhynuly a Nil páchl, takže Egypťané nemohli vodu z Nilu pít. Krev byla v celé egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'I egyptští kouzelníci učinili tak ⌈svým tajným uměním.⌉ Faraonovo srdce se posilnilo a neuposlechl je, tak jak pověděl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Farao se obrátil a odešel domů, a ⌈nepřiložil srdce ani k tomu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'A všichni Egypťané kopali kolem Nilu, aby získali pitnou vodu, protože vodu z Nilu nemohli pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'I naplnilo se sedm dní potom, co Hospodin zasáhl Nil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, 'I řekl Hospodin Mojžíšovi: Jdi k faraonovi a řekni mu: Toto praví Hospodin: Propusť můj lid, ať mi slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, 'Pokud se budeš zdráhat jej propustit, hle postihnu celé tvé území žábami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, 'Nil se bude hemžit žábami. Vylezou a proniknou do tvého paláce, do tvé ložnice a na tvé lůžko; do domů tvých otroků a tvého lidu, do tvých pecí i do tvých díží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, 'Po tobě, po tvém lidu a po všech tvých otrocích polezou žáby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Hospodin řekl Mojžíšovi: Řekni Áronovi: Vztáhni ruku se svou holí nad řeky, nad kanály a nad jezera a vyveď žáby na egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'I vztáhl Áron ruku nad vody Egypta a vystoupily žáby a pokryly egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'I kouzelníci učinili tak svým tajným uměním a vyvedli žáby na egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Farao zavolal Mojžíše a Árona a řekl: Proste Hospodina, aby mě a můj lid zbavil žab. Pak propustím lid, aby obětovali Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Mojžíš řekl faraonovi: ⌈Máš přede mnou výsadu určit,⌉ na kdy mám za tebe, za tvé otroky a za tvůj lid prosit, aby byly žáby vyhlazeny od tebe a ze tvých paláců. Zůstanou jen v Nilu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Farao řekl: Na zítra. Mojžíš odpověděl: Stane se podle tvého slova, abys poznal, že není nikdo jako Hospodin, náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Žáby se stáhnou od tebe, od tvých paláců, od tvých otroků a od tvého lidu, zůstanou jen v Nilu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Mojžíš s Áronem odešel od faraona a Mojžíš úpěnlivě volal k Hospodinu kvůli těm žábám, které na faraona uvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Hospodin učinil podle Mojžíšova slova a žáby z domů, z nádvoří a z polí vymřely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Vršili je na hromady a hromady, až celá země páchla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Když farao uviděl, že nastala úleva, zatvrdil své srdce a neuposlechl je, tak jak pověděl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'I řekl Hospodin Mojžíšovi: Řekni Áronovi: Vztáhni svou hůl a udeř do prachu na zemi a stanou se z něj komáři po celé egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'A učinili tak: Áron vztáhl ruku se svou holí a udeřil do prachu na zemi a na lidech i na dobytku se objevili komáři. Ze všeho prachu na zemi se stali komáři po celé egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'I kouzelníci učinili tak svým tajným uměním, aby vyvedli komáry, ale nedokázali to. A komáři byli na lidech i na dobytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Kouzelníci faraonovi řekli: To je prst Boží! Ale faraonovo srdce se posilnilo a neuposlechl je, tak jak pověděl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'I řekl Hospodin Mojžíšovi: Časně ráno se postav před faraona, když vychází k vodě, a řekni mu: Toto praví Hospodin: Propusť můj lid, ať mi slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Jestliže můj lid nepropustíš, hle, pošlu na tebe, na tvé otroky, na tvůj lid a do tvých paláců mouchy. Domy Egypťanů budou plné much, dokonce i ta půda, na níž jsou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'V ten den oddělím území Gošen, na němž zůstává můj lid. Tam mouchy nebudou, abys poznal, že já jsem Hospodin uprostřed země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Učiním rozdíl mezi svým lidem a tvým lidem. Zítra nastane toto znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'A Hospodin učinil tak. Obtížné mouchy přitáhly do faraonova paláce a domu jeho otroků a na celou egyptskou zemi. Kvůli těm mouchám byla země zničena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Farao povolal Mojžíše a Árona a řekl: Jděte a obětujte svému Bohu zde v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mojžíš odpověděl: Tak jednat by nebylo správné, protože budeme Hospodinu, našemu Bohu, obětovat to, co je Egypťanům ohavností; jestliže budeme před jejich očima obětovat to, co je Egypťanům ohavností, což nás neukamenují?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Půjdeme třídenní cestou pustinou a budeme obětovat Hospodinu, svému Bohu, tak, jak nám řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Farao tedy řekl: Já vás propustím, abyste v pustině obětovali Hospodinu, svému Bohu, jen nechoďte příliš daleko. Proste za mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Mojžíš odpověděl: Když od tebe odejdu, budu prosit Hospodina a zítra mouchy od faraona, od jeho otroků a od jeho lidu odletí. Jen ať nás farao znovu nepodvede, aby nepropustil lid obětovat Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Pak Mojžíš odešel od faraona a naléhavě prosil Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Hospodin pak učinil podle Mojžíšova slova a mouchy od faraona, od jeho otroků a od jeho lidu odletěly, nezůstala ani jedna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Ale farao i tentokrát zatvrdil své srdce a nepropustil lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'I řekl Hospodin Mojžíšovi: Jdi k faraonovi a pověz mu: Toto praví Hospodin, Bůh Hebrejů: Propusť můj lid, ať mi slouží!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Jestliže se je budeš zdráhat propustit a stále je budeš držet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'hle, Hospodinova ruka dopadne na tvůj dobytek, který je na poli, na koně, na osly, na velbloudy, na skot i na brav s velmi těžkým morem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'A Hospodin učiní rozdíl mezi dobytkem Izraele a dobytkem Egypta: Ze všeho dobytka synů Izraele neuhyne ani kus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Hospodin také určil čas: Tuto věc Hospodin učiní v zemi zítra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Příští den Hospodin tu věc učinil a všechen dobytek Egypťanů uhynul, ale z dobytka synů Izraele neuhynul ani jeden kus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Farao ⌈ to dal zjistit,⌉ a hle, z izraelského dobytka neuhynul ani jeden kus. Faraonovo srdce však zůstalo zatvrzelé a lid nepropustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'I řekl Hospodin Mojžíšovi a Áronovi: Vezměte si plné hrsti sazí z hrnčířské pece a ať je Mojžíš rozhazuje k nebi před očima faraona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Stanou se prachem po celé egyptské zemi a vyvolají na lidech i na dobytku v celé egyptské zemi vředy hnisavých neštovic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Vzali tedy saze z hrnčířské pece, postavili se před faraona a Mojžíš je rozhazoval k nebi. Na lidech i na dobytku se objevily vředy hnisavých neštovic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Ani kouzelníci nebyli schopni se postavit před Mojžíše kvůli vředům, protože vředy byly na kouzelnících i na celém Egyptě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Ale Hospodin posilnil faraonovo srdce, takže je neuposlechl, tak jak Hospodin Mojžíšovi pověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'I řekl Hospodin Mojžíšovi: Časně ráno se postav před faraona a řekni mu: Toto praví Hospodin, Bůh Hebrejů: Propusť můj lid, ať mi slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Protože tentokrát pošlu do tvého srdce, na tvé otroky a na tvůj lid všechny své rány, abys poznal, že na celé zemi není nikdo jako já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Vždyť už jsem vztáhl ruku a kdybych tím morem ranil tebe a tvůj lid, byl bys vyhlazen ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Avšak proto jsem tě zachoval, abych ti ukázal svou moc a aby se o mém jménu vyprávělo po celé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Stále vystupuješ proti mému lidu povýšeně a ne chceš ho propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Hle, zítra o tomto čase sešlu ⌈tak ohromné⌉ krupobití, že podobné v Egyptě nebylo ode dne jeho založení až dosud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Nuže, pošli rychle do bezpečí dobytek a všechno, co máš na poli. Všechno, lidé i dobytek, co se bude nacházet na poli a nebude shromážděno v domě, když na to spadne to krupobití, zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kdo z faraonových otroků se bál Hospodinova slova, zahnal své otroky a svůj dobytek do domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Kdo ⌈si však nevzal k srdci⌉ Hospodinovo slovo, zanechal své otroky a dobytek na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Hospodin pak řekl Mojžíšovi: Vztáhni ruku k nebi a dopadne krupobití na celou egyptskou zemi. Na lidi, na dobytek i na všechnu polní zeleň v egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Mojžíš vztáhl svou hůl k nebi a Hospodin způsobil hřmění a krupobití a oheň sestupoval na zem. Tak Hospodin seslal krupobití na egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'A nastalo krupobití a oheň se blýskal uprostřed toho krupobití, ⌈tak ohromného,⌉ že podobné nebylo v celé egyptské zemi od té doby, co se Egypt stal národem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Krupobití po celé egyptské zemi potlouklo všechno, co zůstalo na poli, od lidí až po dobytek; krupobití potlouklo všechnu polní zeleň a polámalo všechny polní stromy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Pouze v zemi Gošenu, kde žili synové Izraele, krupobití nebylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Farao ⌈si dal zavolat⌉ Mojžíše a Árona a řekl jim: Tentokrát jsem zhřešil. Hospodin je spravedlivý. Já a můj lid jsme ničemové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Proste Hospodina. Dost již bylo Božího hřmění a krupobití. Propustím vás, nebudete tu déle zůstávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mojžíš mu odpověděl: Jakmile vyjdu z města, vztáhnu své dlaně k Hospodinu. Hřmění přestane a krupobití už nebude, abys poznal, že země je Hospodinova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Vím však, že ty a tvoji otroci ještě nemáte bázeň před Hospodinem Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Len a ječmen je potlučený, protože ječmen byl už v klasu a len byl v květu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Ale pšenice a špalda nebyly potlučeny, protože jsou pozdní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Mojžíš vyšel od faraona z města a vztáhl dlaně k Hospodinu. Hřmění a krupobití přestalo a déšť se již na zem neřinul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Když farao viděl, že přestal déšť, krupobití i hřmění, dále hřešil a zatvrdil své srdce on i jeho otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Faraonovo srdce se posilnilo a nepropustil syny Izraele, tak jak promluvil Hospodin prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Hospodin řekl Mojžíšovi: Jdi k faraonovi, protože já jsem zatvrdil srdce jeho i srdce jeho otroků, abych ⌈před ním⌉ učinil tato svá znamení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'a abys mohl vyprávět svému synu a synu svého syna, jak jsem Egypťany znevažoval, a o mých znameních, která jsem mezi nimi učinil, abyste poznali, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Mojžíš a Áron přišli k faraonovi a řekli mu: Toto praví Hospodin, Bůh Hebrejů: Jak dlouho budeš odmítat se přede mnou pokořit? Propusť můj lid, ať mi slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Jestliže se však budeš zdráhat propustit můj lid, hle, zítra přivedu kobylky na tvé území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Přikryjí povrch země, takže nebude možno zemi ani spatřit. Sežerou zbytek, který vyvázl, který vám zůstal po krupobití, sežerou všechny stromy, které vám vyrážejí na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Také naplní tvé domy a domy všech tvých otroků, domy všech Egypťanů tak, jak to nezažili tvoji otcové ani otcové tvých otců od doby, kdy byli na zemi, až do tohoto dne. Potom se obrátil a odešel od faraona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Faraonovi otroci mu řekli: Jak dlouho nám ten člověk bude ostnem? Propusť ty lidi, ať slouží Hospodinu, svému Bohu. Což ještě nechápeš, že Egypt hyne?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Mojžíš a Áron byli přivedeni zpět k faraonovi a on jim řekl: Jděte, služte Hospodinu, svému Bohu. Kdo všechno má jít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mojžíš odpověděl: Půjdeme se svými mladými i starými; půjdeme se svými syny i dcerami, se svým bravem i skotem, protože máme svátek Hospodinův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Farao jim odpověděl: Hospodin bude s vámi tak, když vás propustím s vašimi dětmi. Prohlédněte, ⌈to jste si předsevzali zlou věc.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Ne tak! Jen jděte vy muži a služte Hospodinu. Vždyť o to jste usilovali! Nato je vyhnali od faraona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'I řekl Hospodin Mojžíšovi: Vztáhni ruku nad egyptskou zemi kvůli kobylkám, aby přitáhly na egyptskou zemi a sežraly všechnu zemskou zeleň, všechno, co zůstalo po krupobití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Mojžíš tedy vztáhl svou hůl nad egyptskou zemi a Hospodin vedl východní vítr na zemi celý ten den a celou noc. Když nastalo ráno, východní vítr přinesl kobylky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Kobylky vytáhly na celou egyptskou zemi a usadily se na celém egyptském území. Bylo to hrozně tíživé. Před tím nebyla taková záplava kobylek jako tato, ani po ní už taková nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Pokryly povrch celé země, takže země ztemněla, a sežraly všechnu zemskou zeleň a všechno ovoce na stromech, které ⌈zbylo po⌉ krupobití. Nezůstalo nic zeleného na stromech a nic ze zeleně na poli v celé egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Farao rychle zavolal Mojžíše a Árona a řekl: Zhřešil jsem proti Hospodinu, vašemu Bohu, a proti vám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Proto sejměte prosím ještě tentokrát můj hřích a proste Hospodina, svého Boha, aby odvrátil ode mne aspoň toto umírání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Mojžíš odešel od faraona a naléhavě prosil Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'A Hospodin změnil vítr na velmi silný západní vítr, odnesl kobylky a vehnal je do Rákosového moře. Na celém egyptském území nezůstala ani jediná kobylka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Ale Hospodin posilnil faraonovo srdce a on syny Izraele nepropustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Hospodin pak řekl Mojžíšovi: Vztáhni ruku k nebi a nastane temnota v egyptské zemi, temnota, ⌈kterou lze cítit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Mojžíš tedy vztáhl ruku k nebi a na tři dny nastala nejtemnější temnota v celé egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Neviděli jeden druhého a nikdo tři dny nevyšel ze svého místa, avšak všichni synové Izraele měli světlo ve svých sídlištích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Farao zavolal Mojžíše a řekl: Jděte, služte Hospodinu, pouze svůj brav a skot ponechejte zde. Také vaše děti půjdou s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mojžíš však odpověděl: Ty sám nám dáš s sebou oběti a zápaly, abychom je připravili Hospodinu, svému Bohu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'I náš dobytek půjde s námi. Nezůstane tu ani pazneht, protože z toho vezmeme, abychom sloužili Hospodinu, svému Bohu. My nevíme, čím budeme sloužit Hospodinu, dokud tam nepřijdeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Nato Hospodin posilnil faraonovo srdce a on je nechtěl propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Farao mu tedy řekl: Jdi ode mne! Dávej si pozor, abys už nespatřil mou tvář, protože v den, kdy spatříš mou tvář, zemřeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mojžíš odpověděl: Jak jsi řekl. Už více nespatřím tvou tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Hospodin pak řekl Mojžíšovi: Ještě jednu ránu uvedu na faraona a na Egypt; potom vás odsud propustí. Nejenže vás zcela propustí, rázně vás odsud vyžene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Nyní domluv lidu, ať si každý muž vyžádá od svého souseda a každá žena od své sousedky stříbrné a zlaté předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'A Hospodin dal lidu přízeň v očích Egypťanů. Také Mojžíš byl velmi významným mužem v egyptské zemi, v očích faraonových otroků i v očích lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Mojžíš řekl: Toto praví Hospodin: Kolem půlnoci vyjdu doprostřed Egypta');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'a všechno prvorozené v egyptské zemi zemře. Od prvorozeného syna faraona, který sedí na svém trůnu, až do prvorozeného syna služky, která je za ručním mlýnkem; také všechno prvorozené z dobytka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'A nastane veliký křik po celé egyptské zemi, že jemu podobného ještě nebylo a již nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Ale proti nikomu ze synů Izraele ani pes ⌈nenaostří svůj jazyk,⌉ proti člověku ani zvířeti, abyste poznali, že Hospodin učiní rozdíl mezi Egyptem a Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Ale všichni tito tvoji otroci sestoupí ke mně a budou se mi klanět se slovy: Vyjdi ty i všechen lid, který ⌈ chodí ve tvých šlépějích.⌉ Potom vyjdu. Nato vyšel od faraona s planoucím hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Hospodin pak řekl Mojžíšovi: Farao vás neposlechne, aby se mé divy rozmnožily v egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Mojžíš a Áron tedy učinili všechny tyto divy před faraonem, ale Hospodin posilnil faraonovo srdce, takže nepropustil syny Izraele ze své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'I řekl Hospodin Mojžíšovi a Áronovi v egyptské zemi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Tento měsíc bude pro vás počátkem měsíců. Bude pro vás prvním měsícem roku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Vyhlaste celé pospolitosti Izraele: Desátého dne tohoto měsíce ať si každý vezme beránka na otcovský dům, beránka na rodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'A kdyby rodina byla na beránka příliš malá, ať si přibere souseda nejblíže svému domu do počtu duší. Každý bude započten na beránka podle toho, co kdo sní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Budete mít beránka bez vady, ročního samce; vyberete ho z beránků nebo z kůzlat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'A bude ve vaší péči až do čtrnáctého dne tohoto měsíce. Potom ho celé shromáždění pospolitosti Izraele k večeru zabije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Pak vezmou z krve a dají na obě veřeje a na nadpraží domů, v nichž ho budou jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Té noci budou jíst maso; budou je jíst pečené na ohni s nekvašenými chleby a hořkými bylinami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Nebudete jíst z něho nic syrového ani vařeného ve vodě, ale pouze pečené na ohni i hlavu s hnáty a s vnitřnostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Nic z něho neponecháte do rána. Co z něho zůstane do rána, to spálíte ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'A budete ho jíst takto: Bedra budete mít přepásaná, sandály na nohou a hůl v ruce. Budete ho jíst ve spěchu. Bude to velikonoční oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'A té noci projdu egyptskou zemí a pobiji v egyptské zemi všechno prvorozené od lidí až po dobytek. Vykonám soudy nad všemi bohy Egypta. Já, Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Krev na domech, v nichž budete, bude vaším znamením; když uvidím tu krev, pominu vás a nebude mezi vámi zhoubná pohroma, když budu bít egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Tento den se pro vás stane dnem památným a budete ho slavit jako Hospodinův svátek; po všechny své generace ho budete slavit jako ⌈věčné ustanovení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sedm dnů budete jíst nekvašený chléb. Hned první den odstraníte kvas ze svých domů, protože každý, kdo by jedl něco kvašeného od prvního dne až do sedmého dne, takový člověk bude vyhlazen z Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Prvního dne budete mít svaté shromáždění, i sedmého dne budete mít svaté shromáždění. V nich nebude konána žádná práce, pouze co budete každý jíst, jenom to si připravíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Budete zachovávat svátek nekvašených chlebů, protože právě v tento den jsem vyvedl vaše oddíly z egyptské země; tento den budete zachovávat po všechny své generace jako věčné ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'V prvním měsíci od čtrnáctého dne měsíce večer budete jíst nekvašené chleby až do večera dvacátého prvního dne toho měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sedm dnů se ve vašich domech nenajde kvas. Protože každý, kdo by jedl něco kvašeného, takový člověk bude vyhlazen z pospolitosti Izraele, jak příchozí, tak domorodec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nic kvašeného nebudete jíst. Kdekoli budete přebývat, budete jíst nekvašené chleby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Mojžíš tedy svolal všechny izraelské starší a řekl jim: Vyberte si a vezměte jehně po svých rodinách a zabijte velikonoční oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Vezmete svazek yzopu, namočíte do krve v misce a z krve v misce nanesete na nadpraží a na obě veřeje. A nikdo z vás ať nevyjde ze dveří svého domu až do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Když bude Hospodin procházet, aby postihl Egypt, a uvidí krev na nadpraží a na obou veřejích, pomine Hospodin ty dveře a nedovolí ničiteli vstoupit do vašeho domu, aby vás postihl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Tuto věc budeš zachovávat jako ustanovení pro sebe a pro své syny až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Až vejdete do země, kterou vám dá Hospodin tak, jak prohlásil, budete zachovávat tuto službu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'A až se vás vaši synové budou ptát, co pro vás tato služba znamená,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'odpovíte: To je velikonoční oběť Hospodinu, který pominul domy synů Izraele v Egyptě, když postihl Egypťany a naše domy uchránil. Tu lid poklekl a klaněl se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Synové Izraele šli a učinili tak, jak Hospodin přikázal Mojžíšovi a Áronovi; přesně tak učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'O půlnoci se stalo, že Hospodin v egyptské zemi pobil všechno prvorozené od prvorozeného syna faraona, který seděl na svém trůnu, až po prvorozeného zajatce, který seděl v žaláři, i všechno prvorozené z dobytka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Tu farao té noci vstal, i všichni jeho otroci, i všichni Egypťané, a v Egyptě nastal veliký křik, protože nebyl dům, ve kterém by nebyl někdo mrtvý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Ještě v noci zavolal Mojžíše a Árona a řekl: Vstaňte a odejděte zprostřed mého lidu vy i synové Izraele. Jděte a služte Hospodinu, jak jste říkali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Vezměte také svůj brav a svůj skot, tak jak jste řekli, a jděte. Požehnejte také mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Egypťané naléhali na lid, aby je rychle poslali ze země, protože si říkali: Všichni zemřeme!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Lid tedy vzal své těsto ještě nevykynuté, díže zavinuté v pláštích na ramenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Synové Izraele také učinili podle Mojžíšova slova a vyžádali si od Egypťanů stříbrné a zlaté předměty a oděvy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'a Hospodin dal lidu přízeň v očích Egypťanů, takže jim vyhověli. Tak vyplenili Egypt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Synové Izraele vyrazili z Ramesesu do Sukótu v počtu kolem šesti set tisíc pěších mužů, kromě žen a dětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Vyšlo s nimi také množství přimíšeného lidu, brav a skot, veliké množství dobytka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Z těsta, které vynesli z Egypta, napekli nekvašené podpopelné chleby, protože nevykynulo. Když byli vypuzeni z Egypta, nemohli otálet a nepřipravili si ani potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Doba, po kterou synové Izraelovi pobývali v Egyptě, byla čtyři sta třicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Když uplynulo čtyři sta třicet let, právě ten den vyšly všechny Hospodinovy oddíly z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'To byla noc ⌈Hospodinova bdění, aby⌉ je vyvedl z egyptské země. A tato noc je Hospodinova -- noc bdění pro všechny syny Izraele po všechny generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Hospodin řekl Mojžíšovi a Áronovi: Toto je ustanovení o velikonočním beránku: Žádný cizinec z něho nebude jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Ale každý otrok, muž koupený za peníze, když jsi ho obřezal, potom bude z něho jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Příchozí ani najatý z něho jíst nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Bude sněden v tomtéž domě, nic z jeho masa nevyneseš ven z domu; žádnou kost v něm nezlámete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toto bude dělat celá pospolitost Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Bude–li u tebe pobývat cizinec a bude chtít slavit velikonoční oběť Hospodinu, musí se dát obřezat všichni jeho lidé mužského pohlaví. Potom se přiblíží, aby ji slavil, a bude jako domorodec. Ale žádný neobřezanec nebude z ní jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Stejný zákon bude platit pro domorodce i pro cizince, který bude pobývat mezi vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Pak všichni synové Izraele učinili tak, jak Hospodin přikázal Mojžíšovi a Áronovi; přesně tak učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'A právě ten den Hospodin vyvedl syny Izraele po jejich oddílech z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Pak Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Posvěť mi mezi syny Izraele všechno prvorozené otvírající každé lůno, z lidí i z dobytka; patří to mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Mojžíš tedy lidu řekl: Pamatujte na tento den, kdy jste vyšli z Egypta z domu otroctví, neboť silnou rukou vás Hospodin vyvedl z toho místa. Proto nebudete jíst nic kvašeného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Dnes vycházíte, v měsíci ábíbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Až tě Hospodin uvede do země Kenaanců, Chetejců, Emorejců, Chivejců a Jebúsejců, o které přísahal tvým otcům, že ti ji dá, do země oplývající mlékem a medem, budeš v tomto měsíci konat tuto službu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sedm dnů budeš jíst nekvašené chleby; sedmý den bude Hospodinův svátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Nekvašené chleby se budou jíst po sedm dnů. Neukáže se u tebe nic kvašeného, ani se u tebe na celém tvém území neukáže kvas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'A v onen den svému synu oznámíš: To je kvůli tomu, co mi Hospodin prokázal, když jsem vycházel z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'A budeš to mít za znamení na ruce a za připomínku mezi očima, aby Hospodinův zákon byl ve tvých ústech, protože silnou rukou tě Hospodin vyvedl z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'A toto ustanovení budeš zachovávat v jeho určený čas ⌈rok co rok.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Až tě Hospodin uvede do země Kenaanců, jak přísahal tobě a tvým otcům, a až ti ji dá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'pak všechno, co otvírá lůno, převedeš Hospodinu. Všechno prvorozené z tvého dobytka, co bude mužského pohlaví, bude patřit Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Každého prvorozeného osla vyplatíš beránkem, a nemůžeš–li vyplatit, zlomíš mu vaz. Každého prvorozeného mezi svými syny vyplatíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Až se tě později tvůj syn zeptá, co to znamená, řekneš mu: Silnou rukou nás Hospodin vyvedl z Egypta, z domu otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'A protože se farao zatvrdil a nechtěl nás propustit, Hospodin pobil v egyptské zemi všechno prvorozené, od prvorozených u lidí až po prvorozené z dobytka. Proto všechny samce otvírající lůno obětuji Hospodinu a každého prvorozeného ze svých synů vyplácím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Bude to znamením na tvé ruce a značkou mezi tvýma očima, protože silnou rukou nás Hospodin vyvedl z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Když farao propustil lid, Bůh je nevedl cestou do pelištejské země, i když byla kratší. Bůh totiž řekl: Aby lid nelitoval, když uvidí hrozící boj, a nevrátil se do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Bůh tedy vedl lid oklikou, pustinou k Rákosovému moři. Tak synové Izraele vystoupili sešikovaní z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Mojžíš s sebou vzal Josefovy kosti, protože Josef syny Izraele slavnostně zapřísahal slovy: Bůh vás jistě navštíví, pak s sebou odsud vyneste mé kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'I vyrazili ze Sukótu a utábořili se v Étamu na okraji pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Hospodin šel před nimi ve dne v oblakovém sloupu, aby je cestou vedl, a v noci v ohnivém sloupu, aby jim svítil; tak mohli jít ve dne i v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Neodňal od lidu oblakový sloup ve dne, ani ohnivý sloup v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Promluv k synům Izraele, ať se obrátí a utáboří se před Pí–chírótem, mezi Migdólem a mořem; utáboříte se před Baal–sefónem, naproti němu u moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'A farao si o synech Izraele řekne: Zmateně se v zemi potulují, zavřela se nad nimi pustina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Pak posilním faraonovo srdce a bude vás pronásledovat; oslavím se na faraonovi i na celém jeho vojsku a Egypťané poznají, že já jsem Hospodin. A tak to učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Když bylo egyptskému králi oznámeno, že lid utekl, srdce faraona a jeho otroků se obrátilo proti lidu a řekli: Co jsme to udělali, že jsme Izraele propustili z otroctví?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Zapřáhl tedy svůj vůz a svůj lid vzal s sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Vzal šest set vybraných vozů a všechny další egyptské vozy s kapitánem na každém z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Hospodin posilnil srdce faraona, egyptského krále, takže syny Izraele pronásledoval. Synové Izraele vycházeli ⌈se vztyčenou hlavou⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'a Egypťané je pronásledovali a dostihli je tábořící u moře -- všechny koně a vozy faraonovy, jeho jezdci a jeho vojsko -- u Pí–chírótu před Baal–sefónem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Když se farao přiblížil, synové Izraele pozdvihli oči, a hle, Egypťané táhli za nimi. Synové Izraele dostali veliký strach a úpěnlivě volali k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Říkali Mojžíšovi: Což nebyly v Egyptě hroby, žes nás vzal zemřít do pustiny? Cos nám to udělal, žes nás vyvedl z Egypta?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Zdali to není to, co jsme ti říkali v Egyptě: Nech nás, ať otročíme Egypťanům, protože je pro nás lepší otročit Egypťanům, nežli zemřít v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mojžíš však lidu řekl: Nebojte se, stůjte a hleďte na Hospodinovu záchranu, kterou vám dnes způsobí, protože Egypťany, které vidíte dnes, již nikdy více neuvidíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Hospodin bude bojovat za vás a vy budete mlčet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Hospodin řekl Mojžíšovi: Proč ke mně úpěnlivě voláš? Řekni synům Izraele, ať vyrazí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'A ty zvedni svou hůl, vztáhni ruku nad moře a rozděl je, aby synové Izraele prošli prostředkem moře po suchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'A já, hle, posilním srdce Egypťanů, že půjdou za nimi, a oslavím se na faraonovi a na celém jeho vojsku, na jeho vozech i na jeho jezdcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'A Egypťané poznají, že já jsem Hospodin, až se oslavím na faraonovi, na jeho vozech a na jeho jezdcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Tu se anděl Boží, který šel před izraelským táborem, odtrhl a šel za nimi, a oblakový sloup se z jejich čela odtrhl a postavil se za ně');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'a vešel mezi egyptský tábor a izraelský tábor; jednomu byl oblakem a temnotou a druhému osvěcoval noc. Jeden se k druhému nepřiblížil po celou noc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Mojžíš pak vztáhl ruku nad moře a Hospodin silným východním větrem rozháněl moře po celou noc a obrátil moře v souš. Tak byly vody rozděleny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Synové Izraele šli prostředkem moře po suchu a vody jim byly hradbou napravo i nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Egypťané je pronásledovali -- všechny faraonovy koně, jeho vozy a jeho jezdci -- a vešli za nimi doprostřed moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'V čase ranní hlídky Hospodin pohlédl na egyptský tábor z ohnivého a oblakového sloupu a přivedl egyptský tábor do zmatku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Vyvrátil kola u jejich vozů, takže je vedli s obtížemi. Nato si Egypťané řekli: Utečme před Izraelci, protože Hospodin bojuje s nimi proti Egypťanům!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Tu Hospodin řekl Mojžíšovi: Vztáhni ruku nad moře, ať se vody vrátí na Egypťany, na jejich vozy a na jejich jezdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Mojžíš vztáhl ruku nad moře a moře se před rozbřeskem navrátilo do svého normálního stavu. Egypťané mu utíkali vstříc. Tak Hospodin uvrhl Egypťany doprostřed moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Vody se navrátily a přikryly vozy a jezdce, všechny z faraonova vojska, kteří vešli za Izraelci do moře. Nezůstal z nich ani jediný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Ale synové Izraele šli po suchu uprostřed moře a vody jim byly hradbou napravo i nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Onoho dne Hospodin zachránil Izraele z moci Egypťanů. Izrael viděl Egypťany mrtvé na břehu moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Tak Izrael uviděl velikou moc, kterou Hospodin prokázal na Egypťanech. Lid se bál Hospodina a uvěřil Hospodinu a jeho otroku Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Tehdy Mojžíš a synové Izraele zpívali Hospodinu tuto píseň: Budu zpívat Hospodinu, protože se slavně vyvýšil; koně i s jezdcem uvrhl do moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Má síla a píseň je Hospodin, stal se mojí záchranou. On je můj Bůh, budu ho oslavovat, Bůh mého otce, budu ho vyvyšovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Hospodin je válečník, Hospodin je jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Faraonovy vozy a jeho vojsko vrhl do moře, jeho nejlepší kapitáni utonuli v moři Rákosovém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, '⌈Mořské vlny⌉ je přikryly, klesli do hlubin jako kámen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Tvá pravice, Hospodine, se proslavila silou, tvá pravice, Hospodine, zdrtila nepřítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Svou velikou vznešeností jsi strhl své protivníky, vypustil jsi svůj planoucí hněv, strávil je jako strniště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Dechem tvého chřípí se navršily vody, proudy zůstaly stát jako val, mořské vlny ztuhly uprostřed moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Nepřítel si řekl: Budu je pronásledovat, dostihnu je, budu dělit kořist a má touha se na nich naplní; vytasím meč a má ruka si je podrobí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Zadul jsi svým dechem a moře je přikrylo. Potopili se jako olovo v majestátných vodách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Kdo je mezi bohy jako ty, Hospodine? Kdo je jako ty, vznešený v svatosti, budící bázeň slavnými skutky, činící divy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Vztáhl jsi svou pravici a země je pohltila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Svým milosrdenstvím jsi vedl tento lid, který jsi vykoupil, svou silou jsi ho přiváděl k svému svatému příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Uslyší o tom národy a budou se třást, bolest zachvátí obyvatele Pelišteje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Tehdy se zděsí edómští náčelníci, moábské mocnáře, ty zachvátí chvění; všichni obyvatelé Kenaanu propadnou malomyslnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Padne na ně hrůza a strach, pro velikost tvé paže strnou jako kámen, dokud nepřejde tvůj lid, Hospodine, dokud nepřejde lid, který sis získal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Přivedeš a vysadíš je na ⌈horu svého dědictví,⌉ na místo, kterés, Hospodine, připravil ke svému bydlení, do svatyně, Panovníku, kterou založily tvé ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Hospodin bude kralovat navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Když faraonovi koně s vozy a s jezdci vešli do moře, Hospodin na ně obrátil mořské vody, kdežto synové Izraele šli prostředkem moře po suchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Tu prorokyně Mirjam, sestra Áronova, vzala do ruky tamburínu a všechny ženy vyšly za ní s tamburínami a s tanci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Mirjam s nimi zpívala: Zpívejte Hospodinu, protože se slavně vyvýšil, koně i s jezdcem uvrhl do moře!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Mojžíš pak vyvedl Izrael od Rákosového moře a vytáhli do pustiny Šúr. Pustinou šli tři dny a nenalezli vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Pak přišli do Mary, ale nemohli vodu z Mary pít, protože byla hořká. Proto se nazývá Mara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'A lid reptal proti Mojžíšovi: Co budeme pít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Mojžíš tedy úpěnlivě volal k Hospodinu a Hospodin mu ukázal dřevo, které hodil do vody a voda zesládla. Tam jim předložil ustanovení a nařízení a tam je zkusil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Řekl: Jestliže opravdu budeš poslouchat Hospodina, svého Boha, a dělat to, co je v jeho očích správné, naslouchat jeho příkazům a zachovávat všechna jeho ustanovení, žádnou nemoc, kterou jsem vložil na Egypt, na tebe nevložím, protože já jsem Hospodin, který tě uzdravuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Pak přišli do Élimu, kde bylo dvanáct vodních pramenů a sedmdesát palem. Tam u vody se utábořili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Když vyrazili z Élimu, přišla celá pospolitost synů Izraele do pustiny Sín, která je mezi Élimem a Sínajem, patnáctý den druhého měsíce od jejich vyjití z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'A celá pospolitost synů Izraele reptala v pustině proti Mojžíšovi a proti Áronovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Synové Izraele jim říkali: Kéž bychom zemřeli Hospodinovou rukou v egyptské zemi, když jsme sedávali nad hrnci masa a jídali jsme chléb do sytosti! Protože jste nás vyvedli do této pustiny, abyste celé toto shromáždění nechali zemřít hlady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Hospodin řekl Mojžíšovi: Hle, sešlu vám z nebe chléb a lid bude vycházet a sbírat pro svou každodenní potřebu, abych ho vyzkoušel, bude–li chodit podle mého zákona nebo ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'I stane se šestého dne, když budou připravovat, co přinesou, bude toho dvojnásobně, než co budou sbírat jiné dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Mojžíš a Áron všem synům Izraele řekli: Večer tedy poznáte, že vás Hospodin vyvedl z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'A ráno uvidíte Hospodinovu slávu, protože slyšel vaše reptání proti Hospodinu. Vždyť co jsme my, že reptáte proti nám?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Dále Mojžíš řekl: Když vám Hospodin dá večer k jídlu maso a ráno chléb k nasycení, poznáte, že Hospodin slyšel vaše reptání, jímž jste proti němu reptali. Vždyť co jsme my? Vaše reptání nebylo proti nám, ale proti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Áronovi pak Mojžíš řekl: Řekni celé pospolitosti synů Izraele: Přistupte před Hospodina, protože slyšel vaše reptání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'A když Áron mluvil k celé pospolitosti synů Izraele, obrátili se k pustině, a tu se v oblaku ukázala Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Nato Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Slyšel jsem reptání synů Izraele. Pověz jim toto: K večeru budete jíst maso a ráno se nasytíte chlebem. Tak poznáte, že já jsem Hospodin, váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Večer přitáhly křepelky a pokryly tábor. Ráno zas byla vrstva rosy okolo tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Vrstva rosy se odpařila a hle, na povrchu pustiny leželo něco jemného křupavého, jemného jako jíní na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Když to synové Izraele viděli, říkali jeden druhému: ⌈Man hú?⌉ Nevěděli totiž, co to je. Mojžíš jim řekl: To je chléb, který vám Hospodin dal k jídlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'To je to, o čem Hospodin přikázal: Nasbírejte toho každý podle toho, co sníte. Vezmete si každý podle počtu lidí ve svém stanu, ómer na hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Synové Izraele tak učinili a nasbírali jedni více a jiní méně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Pak odměřili po ómeru. Nepřebylo tomu, kdo měl více, a ten, kdo měl méně, neměl nedostatek. Každý nasbíral podle toho, co snědl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Mojžíš jim řekl: Nikdo si nic z toho neponechejte do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Ale neposlechli Mojžíše a někteří si něco z toho ponechali do rána. To však zčervivělo a zasmrádlo. Mojžíš se proto na ně rozhněval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Tedy to sbírali ráno co ráno, každý podle toho, co snědl. Když začalo hřát slunce, rozplynulo se to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'A šestého dne nasbírali dvojnásobné množství potravy, dva ómery na osobu. Všichni ⌈předáci pospolitosti⌉ přišli a oznámili to Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Odpověděl jim: To je to, co promluvil Hospodin: Zítra bude odpočinutí -- svatá sobota Hospodinova. To, co máte napéct, napečte a to, co máte uvařit, uvařte a vše, co bude přebývat, si uložte a uchovejte do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Uložili to tedy do rána tak, jak Mojžíš přikázal, a nezasmrádlo to, ani v tom nebyly larvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Mojžíš pak řekl: Snězte to dnes, protože dnes je sobota Hospodinova. Dnes na poli nic nenaleznete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Šest dní to budete sbírat, ale sedmý den je sobota, v ní nic nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Když sedmého dne přesto někteří z lidu vyšli sbírat, nic nenašli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Hospodin řekl Mojžíšovi: Jak dlouho budete odmítat zachovávat mé příkazy a zákony?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Hleďte, vždyť Hospodin vám dal sobotu, proto vám šestého dne dává pokrm na dva dny. Zůstaňte každý, kde jste, ať nikdo sedmého dne nevychází ze svého místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Lid tedy sedmého dne odpočíval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Dům izraelský to pojmenoval mana. Bylo to bílé jako koriandrové zrno a chutnalo to jako koláč s medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Mojžíš řekl: Toto je věc, kterou přikázal Hospodin: Naplňte tím ómer, aby to bylo uchováno pro vaše generace, aby viděly chléb, kterým jsem vás krmil v pustině, když jsem vás vyvedl z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Mojžíš pak řekl Áronovi: Vezmi jeden džbán, dej tam plný ómer many a ulož ho před Hospodinem, aby to bylo uchováno pro vaše generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Tak, jak Hospodin přikázal Mojžíšovi, Áron to uložil před truhlou svědectví, aby to bylo uchováno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Synové Izraele jedli manu čtyřicet let, dokud nepřišli do obydlené země; jedli manu, dokud nepřišli na okraj země Kenaanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ómer je desetina éfy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Celá pospolitost synů Izraele odtáhla z pustiny Sínu po svých denních pochodech podle Hospodinova příkazu, až se utábořili v Refídímu a lid tam neměl vodu k pití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Lid se přel s Mojžíšem. Říkali: Dej nám vodu k pití! Mojžíš jim odpověděl: Proč se se mnou přete? Proč pokoušíte Hospodina?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Ale lid tam žíznil po vodě a reptal proti Mojžíšovi. Říkali: Proč jsi nás vyvedl z Egypta? Abys nás, naše syny i náš dobytek nechal zemřít žízní?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mojžíš úpěnlivě volal k Hospodinu slovy: Co budu dělat s tímto lidem? Ještě málo a budou mne kamenovat!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Hospodin Mojžíšovi odpověděl: Předstup před lid a vezmi s sebou některé z izraelských starších. Také svou hůl, s níž jsi udeřil Nil, si vezmi do ruky a jdi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Hle, budu tam stát před tebou na skále na Chorébu. Udeříš do skály a vyjde z ní voda, aby lid mohl pít. Mojžíš to učinil před očima izraelských starších.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'To místo pojmenoval Massa a Meriba kvůli při synů Izraele a kvůli jejich pokoušení Hospodina slovy: Je Hospodin uprostřed nás, nebo není?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Pak přitáhl Amálek a v Refídímu bojoval s Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Mojžíš řekl Jozuovi: Vyber nám muže a jdi bojovat s Amálekem. Zítra budu stát na vrcholu kopce s Boží holí v ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Jozue udělal, jak mu Mojžíš řekl, a bojoval s Amálekem. Mojžíš, Áron a Chúr vystoupili na vrchol kopce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Když Mojžíš držel ruku nahoře, vítězil Izrael, a když ruku spustil, vítězil Amálek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Když Mojžíšovi ruce ochably, vzali kámen a položili pod něho, aby se na něj posadil, a Áron a Chúr podpírali jeho ruce jeden z jedné a ⌈druhý z druhé⌉ strany, takže jeho ruce zůstaly pevné až do západu slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Tak Jozue porazil Amáleka a jeho lid ostřím meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Hospodin řekl Mojžíšovi: Zapiš to na památku do knihy a vštěp Jozuovi do uší, že zcela vymažu památku na Amáleka zpod nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'I postavil Mojžíš oltář a pojmenoval jej: Hospodin je má korouhev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'A řekl: Neboť ⌈ruka je vztažena k Hospodinovu trůnu.⌉ Hospodinův boj bude proti Amálekovi z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Midjánský kněz Jitro, Mojžíšův tchán, slyšel o všem, co Bůh učinil pro Mojžíše a pro svůj lid Izrael, že Hospodin vyvedl Izrael z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Mojžíšův tchán Jitro vzal Mojžíšovu ⌈propuštěnou ženu Siporu⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'a její dva syny. Jméno prvního bylo Geršóm, neboť řekl: Byl jsem hostem v cizí zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'a jméno druhého Elíezer, neboť řekl: Bůh mého otce byl mou pomocí a vysvobodil mě od faraonova meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Přišel tedy jeho tchán Jitro s jeho syny a jeho ženou k Mojžíšovi do pustiny, kde on tábořil u Boží hory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Vzkázal Mojžíšovi: Já, tvůj tchán Jitro přicházím k tobě; také tvá žena a oba její synové s ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Mojžíš vyšel vstříc svému tchánovi, poklonil se a políbil ho. Zeptali se jeden druhého, jak se daří, a vešli do stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Mojžíš pak vyprávěl svému tchánovi o všem, co Hospodin učinil faraonovi a Egypťanům kvůli Izraeli, o všech těžkostech, které je cestou postihly, a jak je Hospodin vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jitro se radoval ze všeho dobrého, co Hospodin Izraeli učinil, a že ho vysvobodil z ruky Egypťanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Nato Jitro prohlásil: Požehnán buď Hospodin, který vás vysvobodil z ruky Egypťanů a faraona, a který vysvobodil tento lid z područí Egypta!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Teď vím, že Hospodin je větší nad všechny bohy, protože v tom, čím se vyvyšovali, je pře mohl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'A Mojžíšův tchán Jitro vzal zápal a oběti pro Boha. Přišel také Áron a všichni izraelští starší, aby jedli pokrm s Mojžíšovým tchánem před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Nazítří se Mojžíš posadil, aby soudil lid. Lid stál před Mojžíšem od rána až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Mojžíšův tchán viděl všechno, co s lidem dělal, a řekl: Co to s lidem děláš? Proč zasedáš jen ty a všechen lid před tebou stojí od rána až do večera?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mojžíš svému tchánovi odpověděl: To lid ke mně přichází, aby hledal Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Když mají nějakou záležitost, přijdou ke mně a já rozsoudím mezi jedním a druhým. Oznamuji jim Boží ustanovení a zákony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Mojžíšův tchán mu odpověděl: To není dobré, jak si počínáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Zcela se vyčerpáš jak ty, tak i tento lid, který je s tebou: Je to pro tebe příliš těžké. Nemůžeš to dělat sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Teď mě poslechni, poradím ti a Bůh bude s tebou: Ty ⌈zastupuj lid⌉ před Bohem a jejich záležitosti ty přinášej Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Budeš je vyučovat ustanovením a zákonům a oznamovat jim cestu, po níž mají chodit, a skutky, jež mají činit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Ty si ze všeho lidu vyhlédni muže zdatné, bohabojné, muže spolehlivé, kteří nenávidí nekalý zisk, a ustanov je nad nimi za správce nad tisíci, nad sty, nad padesáti a nad deseti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Budou soudit lid každého času, takže každou velkou záležitost přinesou k tobě a každou menší záležitost rozsoudí sami. Tak si ulehčíš a ponesou břímě s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Jestliže to tak uděláš, a Bůh ti to tak přikazuje, budeš schopen obstát a také všechen tento lid se dostane na své místo v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mojžíš uposlechl svého tchána a udělal všechno, co řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Mojžíš tedy vybral zdatné muže z celého Izraele a učinil je předáky lidu, správci nad tisíci, nad sty, nad padesáti a nad deseti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Ti soudili lid každého času: Těžkou záležitost přinesli k Mojžíšovi a všechny malé záležitosti soudili sami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Mojžíš pak propustil svého tchána a on si šel do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Třetího měsíce po vyjití synů Izraele z egyptské země, v tentýž den, přišli do Sínajské pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Odtáhli z Refídímu, přišli do Sínajské pustiny a v té pustině se utábořili; Izrael se tam utábořil naproti hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Mojžíš vystoupil k Bohu a Hospodin na něho z hory zavolal: Toto řekneš ⌈domu Jákobovu⌉ a oznámíš synům Izraele:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Sami jste viděli, jak jsem naložil s Egyptem, ale vás jsem nesl na orlích křídlech a přinesl jsem vás k sobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Nyní tedy, budete–li mne opravdu poslouchat a budete–li zachovávat moji smlouvu, budete mým zvláštním vlastnictvím mezi všemi národy, i když moje je celá země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Ale vy budete mým královstvím kněží a svatým národem. Toto jsou slova, která budeš říkat synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Mojžíš přišel, povolal starší lidu a předložil jim všechna tato slova, která mu Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Všechen lid společně odpověděl: Vše, co Hospodin promluvil, budeme plnit. Mojžíš přinesl slova lidu zpět k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Hospodin řekl Mojžíšovi: Hle, přijdu k tobě v hustém oblaku, aby lid slyšel, když s tebou budu mluvit, a aby ti navždy věřili. A Mojžíš oznámil Hospodinu slova lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Hospodin řekl Mojžíšovi: Jdi k lidu a posvěcuj je dnes i zítra. Ať si vyperou oděvy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'a jsou připraveni k třetímu dni, protože třetího dne Hospodin před očima všeho lidu sestoupí na horu Sínaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Vyznač hranici lidu dokola a řekni: Mějte se na pozoru, abyste nevystupovali na horu, nebo se dotkli jejího okraje. Každý, kdo by se dotkl hory, bude jistě usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ruka se jí nedotkne, proto musí být ukamenováno nebo zastřeleno šípem, ať dobytče nebo člověk, nezůstane naživu. Až táhle zatroubí beraní roh, pak budou oni vystupovat na horu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mojžíš sestoupil z hory k lidu, posvěcoval lid, a oni si vyprali oděvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'I řekl lidu: Buďte připraveni za tři dny. Nepřistupujte k ženě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Třetího dne, když nastalo jitro, se na hoře objevilo hřmění, blesky a ohromný oblak a ozval se velmi silný zvuk beraního rohu. Všechen lid v táboře se třásl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Mojžíš vyvedl lid z tábora vstříc Bohu a oni se postavili na úpatí hory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Celá hora Sínaj byla zahalená kouřem, protože na ni sestoupil Hospodin v ohni. Vystupoval z ní kouř jako kouř z hrnčířské pece a celá hora se velice třásla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Zvuk beraního rohu byl stále silnější a silnější, Mojžíš mluvil a Bůh mu hlasitě odpovídal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Hospodin sestoupil na horu Sínaj, na vrchol hory; pak Hospodin zavolal Mojžíše na vrchol hory a Mojžíš vyšel vzhůru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Hospodin řekl Mojžíšovi: Sestup a varuj lid, aby nezkoušeli proniknout k Hospodinu, aby ho viděli, aby jich mnoho nepadlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Také kněží, kteří přistupují k Hospodinu, se musí posvětit, aby se na ně Hospodin neobořil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mojžíš řekl Hospodinu: Lid nemůže vystoupit na horu Sínaj, protože jsi nás sám varoval slovy: Vyznač hranici kolem hory a posvěť ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'A Hospodin mu řekl: Jdi, sestup a zase vystoupíš ty a Áron s tebou. Avšak kněží a lid ať nezkouší proniknout a vystoupit k Hospodinu, aby se na ně neobořil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Mojžíš tedy sestoupil k lidu a řekl jim to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Potom Bůh vyhlásil ⌈všechna tato slova.⌉ Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Já ⌈Hospodin jsem tvůj Bůh,⌉ který jsem tě vyvedl z egyptské země, z domu otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Nebudeš mít jiné bohy vedle mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Neuděláš si tesanou modlu ani jakékoliv zpodobení toho, co je nahoře na nebi nebo dole na zemi či ve vodě pod zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Nebudeš se jim klanět a nebudeš jim otročit, neboť já Hospodin, tvůj Bůh, jsem Bůh žárlivý, který s trestem navštěvuji vinu otců na synech i na třetí a na čtvrté generaci těch, kdo mě nenávidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'ale prokazuji milosrdenství tisícům těch, kdo mne milují a zachovávají mé příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Nebudeš brát jméno Hospodina, svého Boha, nadarmo, protože Hospodin nenechá bez trestu toho, kdo bere jeho jméno nadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Pamatuj na sobotní den, abys ho posvětil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Šest dní budeš pracovat a dělat všechnu svou práci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'ale sedmý den je sobota patřící Hospodinu, tvému Bohu. Nebudeš dělat žádnou práci ty ani tvůj syn ani tvá dcera, tvůj otrok ani tvá otrokyně, tvé zvíře ani tvůj příchozí, který je ve tvých branách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'protože šest dní Hospodin dělal nebesa a zemi, moře a všechno, co je v nich, a sedmý den odpočinul. Proto Hospodin požehnal sobotní den a posvětil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Cti svého otce a svou matku, aby se prodloužily tvé dny na zemi, kterou ti dává Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Nebudeš vraždit!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Nebudeš cizoložit!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Nebudeš krást!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Nebudeš vydávat proti svému bližnímu falešné svědectví!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Nebudeš dychtit po domě svého bližního. Nebudeš dychtit po ženě svého bližního ani po jeho otroku ani po jeho otrokyni ani po jeho býku ani po jeho oslu, vůbec po ničem, co patří tvému bližnímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Všechen lid sledoval hřmění a blýskání, zvuk beraního rohu a horu zahalenou kouřem. Když to lid sledoval, roztřásli se a zůstali stát opodál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Řekli Mojžíšovi: Mluv s námi ty a budeme naslouchat. Ať s námi nemluví Bůh, abychom nezemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mojžíš lidu odpověděl: Nebojte se, protože Bůh přišel, aby vás vyzkoušel a aby na vás byla bázeň před ním, abyste nehřešili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Lid zůstal stát opodál a Mojžíš přistoupil k ⌈husté temnotě,⌉ kde byl Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Hospodin řekl Mojžíšovi: Toto řekneš synům Izraele: Sami jste viděli, že jsem s vámi mluvil z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Neuděláte si vedle mne bohy stříbrné, neuděláte si ani bohy zlaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Uděláš mi oltář z hlíny a budeš na něm obětovat své zápaly a své pokojné oběti, svůj brav a svůj skot. Na každém místě, kde nechám připomínat své jméno, přijdu k tobě a požehnám ti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Jestliže mi uděláš oltář z kamenů, nesmíš používat kameny tesané, protože když se nad ním rozeženeš svým dlátem, znesvětíš ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'A nebudeš vystupovat na můj oltář po stupních, aby se na něm neodhalovala tvá nahota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'A toto jsou nařízení, která jim předložíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Když koupíš hebrejského otroka, šest let bude sloužit, ale sedmého roku odejde na svobodu bez výkupného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Jestliže přišel sám, sám odejde, jestliže byl ženatý, odejde jeho žena s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Jestliže mu jeho pán dal ženu a ta mu porodila syny či dcery, ta žena a její děti budou patřit jejímu pánu a on odejde sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Jestliže však otrok výslovně řekne: ⌈Mám rád⌉ svého pána, svou ženu a své syny, ne chci odejít svobodný,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'přivede ho jeho pán před Boha, přivede ho ke dveřím či veřejím, jeho pán mu propíchne šídlem ucho a on mu bude sloužit navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Když někdo prodá svou dceru za otrokyni, neodejde tak, jako odcházejí otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Jestliže se znelíbí svému pánu, který ji určil pro sebe, dovolí ji vykoupit. Cizímu lidu nemá právo ji prodat, protože vůči ní jednal věrolomně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Jestliže ji určí svému synovi, bude s ní jednat podle práva dcer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Jestliže si přibere jinou, neukrátí ji o maso, oděv ani ⌈manželské právo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Jestliže jí nebude plnit tyto tři povinnosti, může odejít bez výkupného, bez placení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kdokoliv by někoho udeřil, takže by zemřel, jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Jestliže však na něj nečíhal, ale Bůh dopustil, že padl do jeho ruky, ustanovím ti místo, kam bude moci utéct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Jestliže by však někdo jednal zlostně proti svému bližnímu a úkladně ho zabil, odtrhni ho od mého oltáře, aby zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Ten, kdo udeří svého otce či matku, jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Kdo by ukradl člověka, ať ho prodá či bude u něj nalezen, jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Ten, kdo by proklel svého otce či matku, jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Když se budou muži přít a jeden udeří druhého kamenem či pěstí, takže nezemře, ale ulehne do postele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'pokud vstane a bude chodit venku o holi, potom ten, kdo udeřil, zůstane bez trestu. Pouze zaplatí odškodné a ⌈úplné vyléčení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Když někdo udeří svého otroka či otrokyni holí, takže zemře pod jeho rukou, jistě bude pomstěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Pokud však otrok den či dva zůstane, nebude pomstěn, neboť je jeho majetkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Když se budou muži rvát a postihnou těhotnou ženu, takže vyjde její dítě, ale nestane se neštěstí, jistě zaplatí pokutu, jak mu stanoví manžel té ženy; dá, ⌈co bylo určeno.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Jestliže se stane neštěstí, dáš život za život,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'oko za oko, zub za zub, ruku za ruku, nohu za nohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'spáleninu za spáleninu, modřinu za modřinu, šrám za šrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Když někdo zasáhne oko svého otroka či oko své otrokyně a zničí ho, za jeho oko jej propustí na svobodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Jestliže vyrazí zub svému otrokovi anebo své otrokyni, za jeho zub jej propustí na svobodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Když býk potrká muže či ženu, takže zemře, musí být býk ukamenován a jeho maso se nebude jíst. Majitel býka bude nevinný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Jestliže byl býk trkavý již někdy dříve, jeho majiteli to bylo dosvědčeno, ale nehlídal ho, a býk usmrtil muže či ženu, bude býk ukamenován a také jeho majitel bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Jestliže mu bude stanoveno výkupné, dá cenu za svůj život, zcela tak, jak mu bude stanoveno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Jestliže potrká syna nebo dceru, naloží se s ním podle tohoto právního nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Jestliže býk potrká otroka či otrokyni, dá jeho pánovi třicet stříbrných šekelů a býk bude ukamenován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Když někdo otevře jámu nebo někdo vykope jámu a nezakryje ji, takže tam spadne býk nebo osel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'majitel jámy zaplatí jeho majiteli náhradu ve stříbře a mrtvé zvíře bude patřit jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Když něčí býk potrká sousedova býka, takže zemře, živého býka prodají a ⌈cenu za něj⌉ si rozdělí a také mrtvého si rozdělí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Kdyby bylo známo, že býk byl trkavý již někdy dříve a jeho majitel ho nehlídal, jistě nahradí býka za býka a mrtvé zvíře bude patřit jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, 'Když někdo ukradne býka či ovci a porazí ji nebo prodá, náhradou dá pět býků za býka a čtyři ovce za ovci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Jestliže bude dopaden zloděj při vloupání a bude bit, takže zemře, nebude za něj prolita krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Jestliže ⌈to bude po východu slunce,⌉ bude za něj prolita krev. Zloděj musí ztrátu plně nahradit. Pokud nic nemá, bude za svou krádež prodán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Jestliže se u něj skutečně nalezne živé to, co ukradl, -- ať býk, osel či ovce -- nahradí to dvojnásobně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Když někdo ⌈nechá spásat pole či vinici a pustí⌉ svůj dobytek pást se na cizí pole, nahradí to tím nejlepším ze svého pole či ze své vinice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Když vyšlehne oheň, zasáhne trní a stráví stoh, nepožaté obilí či pole, pak ten, kdo požár zapříčiní, musí plně nahradit to, co bylo spáleno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Když dá někdo svému bližnímu do úschovy stříbro nebo nějaké předměty a bude to z domu toho muže ukradeno, pak pokud bude zloděj dopaden, nahradí to dvojnásobně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Jestliže nebude zloděj dopaden, předstoupí majitel domu před Boha, nevztáhl–li ruku na práci svého bližního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Při každé zpronevěře -- ohledně býka, osla, ovce, oděvu, ohledně jakékoliv ztracené věci, o které někdo řekne: To je ono -- přijde záležitost těch dvou před Boha. Koho Bůh prohlásí vinným, ten ztrátu svému bližnímu dvojnásobně nahradí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Když někdo dá svému bližnímu do úschovy osla, býka, ovci či jakékoliv zvíře a to zemře, bude zraněno či odvlečeno a nikdo to neviděl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, '⌈Hospodinova přísaha⌉ bude mezi těmi dvěma, že nevztáhl ruku na práci svého bližního. Jeho majitel to přijme a držitel nebude nic nahrazovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Jestliže mu to však skutečně ukradli, nahradí to jeho majiteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Jestliže to bylo opravdu roztrháno na kusy, přinese mu důkaz a rozsápané zvíře nebude nahrazovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Když si někdo vyžádá dobytče od svého bližního, to bude zraněno nebo zemře a majitel u toho nebude, musí ztrátu plně nahradit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Jestliže u toho jeho majitel bude, nebude ztrátu nahrazovat. Jestliže si je pronajal, ztráta je kryta odměnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Když někdo svede pannu, která není zasnoubená, a bude s ní spát, jistě za ni zaplatí věno, aby se stala jeho ženou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Jestliže mu ji její otec rozhodně odmítne dát, odváží stříbro jako věno za pannu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Čarodějnici nenecháš naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Každý, kdo obcuje se zvířetem, bude jistě usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Ten, kdo obětuje jiným bohům než Hospodinu samému, bude zasvěcen zkáze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Nebudeš utiskovat příchozího ani ho nebudeš utlačovat, neboť jste byli příchozími v egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Žádnou vdovu ani sirotka nebudete utlačovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Jestliže bys ho přece utlačoval, takže by ke mně úpěnlivě volal, jistě vyslyším jeho volání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'vzplanu hněvem a pobiji vás mečem, takže se vaše ženy stanou vdovami a vaši synové sirotky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Jestliže půjčíš peníze mému lidu, chudému, který je s tebou, nebudeš vůči němu jednat jako lichvář, neuložíš mu úrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Jestliže vezmeš do zástavy plášť svého bližního, do západu slunce mu ho vrať,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'neboť je to jeho jediná přikrývka, je to jeho plášť pro jeho tělo. V čem by jinak spal? I stane se, že bude ke mně úpěnlivě volat a vyslyším ho, neboť jsem milostivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Nebudeš proklínat Boha ani předáka ve svém lidu nebudeš proklínat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Neopozdíš se s obětí ze svého plného výnosu a své šťávy. Svého prvorozeného syna dáš mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Tak naložíš i se svým býkem a se svou ovcí: sedm dní bude u své matky a osmého dne jej dáš mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Budete mým svatým lidem. Nebudete jíst maso zvířete rozsápaného na poli, ale hodíte ho psovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Nebudeš šířit klamnou zprávu. ⌈Nepřipojíš se k ničemovi,⌉ abys byl zlovolným svědkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, '⌈Nepůjdeš s davem za špatnostmi.⌉ Nebudeš svědčit při sporu tak, že se nakloníš k většině a převrátíš právo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'ani nebudeš nadržovat chudému při jeho sporu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Když narazíš na býka svého nepřítele nebo jeho osla, který se zatoulal, jistě mu ho přivedeš zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Když uvidíš osla toho, kdo tě nenávidí, ležícího pod svým břemenem, nenecháš ho samotného, ale jistě ho spolu s ním dáš do pořádku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Nepřevrátíš právo svého nuzného při jeho sporu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Drž se vpovzdálí od lživého slova. Nevinného a spravedlivého nezabiješ, neboť ničemu neospravedlním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Nepřijmeš úplatek, neboť úplatek oslepuje ty, jež vidí, a podvrací jednání spravedlivých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Nebudeš utlačovat příchozího. Vy rozumíte duši příchozího, neboť jste byli příchozími v egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Šest let budeš osévat svou zemi a sklízet její úrodu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'ale sedmého ji ⌈necháš ladem a nebudeš ji sklízet.⌉ Budou z ní jíst chudí ze tvého lidu a to, co po nich zbude, sežere polní zvěř. Tak naložíš i se svou vinicí a olivovým hájem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Šest dní budeš konat své dílo, a sedmého dne přestaneš, aby odpočinul tvůj býk i tvůj osel. Oddechne si i syn tvé otrokyně a příchozí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Dávejte pozor na všechno, co jsem vám řekl. Jméno cizích bohů nebudete připomínat, nebude slyšet ze tvých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Třikrát za rok mi budeš slavit svátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Budeš zachovávat svátek nekvašených chlebů. Po sedm dní budeš jíst nekvašené chleby, jak jsem ti přikázal, v určený čas měsíce ábíbu, neboť v něm jsi vyšel z Egypta. Ať se nikdo neukáže přede mnou s prázdnou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'budeš zachovávat i svátek žně prvotin z plodů svého díla, z toho co zaseješ na poli, a svátek sklizně na konci roku, kdy sklidíš z pole plody svého díla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Třikrát za rok se ukáže každý, kdo je u tebe mužského pohlaví, před Panovníkem Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Nebudeš obětovat krev mé oběti spolu s kvašeným. Nezůstane do rána tuk mé sváteční oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, '⌈ To nejlepší⌉ z prvotin své země přineseš do domu Hospodina, svého Boha. Nebudeš vařit kůzle v mléce jeho matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Hle, posílám před tebou anděla, aby tě střežil na cestě a přivedl tě na místo, které jsem připravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Měj se před ním na pozoru a poslouchej ho. ⌈Neprovokuj ho,⌉ neboť nesejme vaše přestoupení, protože mé jméno je v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Když ho však budeš bedlivě poslouchat a plnit vše, co říkám, stanu se nepřítelem tvých nepřátel a protivníkem tvých protivníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Neboť můj anděl půjde před tebou a přivede tě k Emorejcům, Chetejcům, Perizejcům, Kenaancům, Chivejcům a Jebúsejcům a já je vyhladím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Nebudeš se klanět jejich bohům a nebudeš jim otročit, ani nebudeš jednat podle jejich skutků, ale dočista je zboříš a úplně roztřískáš jejich posvátné sloupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Budete sloužit Hospodinu, svému Bohu, a on požehná tvému chlébu i tvé vodě. Odstraním ze tvého středu nemoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Nebude ve tvé zemi ženy, která by potratila, ani neplodné; a naplním počet tvých dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, '⌈Hrůzu ze mě⌉ pošlu před tebou, do zmatku přivedu každý národ, ⌈ke kterému přijdeš,⌉ a způsobím, že všichni tví nepřátelé se dají před tebou na útěk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Pošlu před tebou děs a vyžene před tebou Chivejce, Kenaance a Chetejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Nevyženu je před tebou v jednom roce, jinak by byla země zcela opuštěná a ⌈bylo by proti tobě mnoho polní zvěře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Vyženu je před tebou kousek po kousku, dokud se nerozplodíš a ne rozdělíš zemi do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Stanovím tvé území od Rákosového moře až po moře Pelištejců, od pustiny až k Řece, neboť vydám do vaší ruky obyvatele země a vyženu je před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Neuzavřeš smlouvu s nimi ani s jejich bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Nebudou pobývat ve tvé zemi, aby tě nesvedli k hříchu vůči mně. Když bys sloužil jejich bohům, stalo by se ti to léčkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Potom Mojžíšovi řekl: Vystup k Hospodinu, ty a Áron, Nádab a Abíhú a sedmdesát ze starších Izraele, a ⌈budete se klanět zpovzdálí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Jen Mojžíš sám přistoupí k Hospodinu. Ostatní nepřistoupí a lid s ním nevyjde nahoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mojžíš přišel a vyprávěl lidu všechna Hospodinova slova a všechna nařízení. Všechen lid jednohlasně odpověděl a řekl: Všechna slova, která Hospodin promluvil, budeme plnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Mojžíš zapsal všechna Hospodinova slova. Časně ráno vstal, postavil oltář pod horou a dvanáct posvátných sloupů za dvanáct kmenů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'A poslal mládence ze synů Izraele, a ti přinesli zápalné oběti a obětovali Hospodinu býčky jako pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Mojžíš vzal polovinu krve a nalil do mís a polovinou krve pokropil oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Potom vzal knihu smlouvy a přečetl lidu. Ten řekl: Všechno, co Hospodin promluvil, budeme plnit a poslouchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Mojžíš vzal krev, pokropil lid a řekl: Hle, krev smlouvy, kterou s vámi Hospodin uzavřel podle všech těchto slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Nato vystoupil Mojžíš i Áron, Nádab i Abíhú a sedmdesát ze starších Izraele');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'a viděli Boha Izraele a pod jeho nohama cosi podobného safírové dlažbě, průzračné jako samo nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Ale proti nejpřednějším ze synů Izraele nevztáhl ruku; ačkoliv spatřili Boha, jedli a pili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Hospodin řekl Mojžíšovi: Vystup ke mně na horu a zůstaň tam; dám ti kamenné desky, zákon a příkaz, které jsem napsal k jejich poučení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Potom vstal Mojžíš i jeho služebník Jozue a Mojžíš vystoupil na Boží horu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Starším však řekl: Zůstaňte zde, dokud se k vám nevrátíme. Áron a Chúr jsou zde s vámi; kdo by měl nějakou záležitost, přistoupí k nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Mojžíš vystoupil na horu a horu zakryl oblak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Na hoře Sínaj spočívala Hospodinova sláva a po šest dní ji zakrýval oblak. Sedmého dne Hospodin zavolal na Mojžíše z oblaku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Hospodinova sláva vypadala před očima synů Izraele jako stravující oheň na vrcholu hory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Mojžíš vešel do oblaku a vystoupil na horu. Mojžíš byl na hoře čtyřicet dní a čtyřicet nocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Promluv k synům Izraele, aby pro mě vybrali dar; od každého, ⌈koho podněcuje srdce,⌉ vyberete můj dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Toto je dar, který od nich vyberete: zlato, stříbro a bronz,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'přízi modrou, purpurovou a karmínovou, jemné plátno a kozí srst,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, '⌈načerveno zbarvené⌉ beraní kůže, tachaší kůže a akáciové dřevo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'olej ke svícení, balzámy na olej pomazání a na vonné kadidlo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'kameny karneolové a další kameny pro vsazování do efódu a náprsníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'A ať mi udělají svatyni a budu přebývat uprostřed nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Právě tak, jak ti ukazuji vzor příbytku a vzor všech jeho předmětů, tak to učiníte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Udělají truhlu z akáciového dřeva dva a půl lokte dlouhou, loket a půl širokou a loket a půl vysokou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Potáhneš ji čistým zlatem, zevnitř i zvnějšku ji potáhneš a uděláš jí kolem dokola zlatou obrubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Odliješ pro ni čtyři zlaté kruhy a dáš je na čtyři její nohy -- dva kruhy na jeden bok a dva kruhy na druhý bok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Uděláš též tyče z akáciového dřeva a potáhneš je zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Tyče prostrčíš do kruhů po bocích truhly, aby se na nich mohla truhla nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Tyče zůstanou v kruzích truhly, nebudou se z ní vytahovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Do truhly pak vložíš svědectví, které ti dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Uděláš slitovnici z čistého zlata dva a půl lokte dlouhou a loket a půl širokou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Uděláš dva zlaté cheruby; uděláš je jako tepanou práci na obou koncích slitovnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Jednoho cheruba udělej na jednom konci a druhého cheruba na druhém konci. Na slitovnici uděláte cheruby na obou jejích koncích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Cherubové budou mít křídla roztažená vzhůru; svými křídly budou zastírat slitovnici; budou obráceni jeden k druhému; tváře cherubů budou upřeny na slitovnici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Dáš slitovnici nahoru na truhlu a do truhly vložíš svědectví, které ti dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Tam se s tebou budu setkávat a ze slitovnice mezi dvěma cheruby, kteří jsou na truhle svědectví, s tebou budu mluvit o všem, co ti přikáži pro syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Uděláš stůl z akáciového dřeva dva lokte dlouhý, loket široký a loket a půl vysoký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Potáhneš ho čistým zlatem a uděláš mu kolem dokola zlatou obrubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Uděláš mu rám na dlaň široký kolem dokola a jeho rámu uděláš zlatou obrubu kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Uděláš mu čtyři zlaté kruhy a kruhy upevníš na čtyři rohy na čtyřech jeho nohách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Kruhy budou vedle rámu jako místo pro tyče, aby se mohl stůl nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Uděláš tyče z akáciového dřeva a potáhneš je zlatem. Na nich se bude stůl nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Uděláš k němu mísy, kadidlové pánvičky, konve a obětní misky, s nimiž jsou vylévány lité oběti; uděláš je z čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Na stůl budeš dávat předkladný chléb, aby byl přede mnou ustavičně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Pak uděláš svícen z čistého zlata. Jako tepaná práce bude udělán svícen. Jeho podstavec a jeho ramena, jeho kalichy, hlavice i květy budou ⌈z jednoho kusu s ním.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Šest ramen bude vycházet z jeho stran -- tři ramena svícnu z jedné strany a tři ramena svícnu z druhé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Tři kalichy ⌈v podobě mandloňového květu⌉ budou na jednom rameni -- hlavice a květ -- a tři kalichy v podobě mandloňového květu budou na druhém rameni -- hlavice a květ. Tak to bude na šesti ramenech vycházejících ze svícnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Na samotném svícnu budou čtyři kalichy v podobě mandloňového květu -- jeho hlavice a jeho květy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'hlavice bude pod dvěma rameny z něj vycházejícími, další hlavice bude pod dalšími dvěma rameny z něj vycházejícími a další hlavice bude pod dalšími dvěma rameny z něj vycházejícími, tedy u šesti ramen vycházejících ze svícnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Jejich hlavice a jejich ramena budou z jednoho kusu s ním, všechno jako tepaná práce z jednoho kusu čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Uděláš sedm jeho lamp a jeho lampy se nasadí a budou osvěcovat prostor před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Také kleště a pánvičky na uhlíky k němu budou z čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Bude zhotoven se všemi těmito předměty z talentu čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Hleď, abys je udělal podle jejich vzoru, který ti byl ukázán na hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Příbytek uděláš z deseti stanových plachet z jemně tkaného plátna, z příze modré, purpurové a karmínové; ⌈uděláš na nich cheruby⌉ jako ⌈umělecké dílo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Délka jedné stanové plachty bude dvacet osm loket a šířka jedné stanové plachty bude čtyři lokte. Všechny stanové plachty budou mít stejný rozměr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pět stanových plachet bude spojeno ⌈jedna k druhé⌉ a dalších pět stanových plachet bude spojeno ⌈jedna k druhé.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Uděláš poutka z modré příze na okraji jedné stanové plachty na konci jednoho spojeného kusu a stejně to uděláš na okraji poslední stanové plachty na spojeném kusu druhém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Padesát poutek uděláš na stanové plachtě jedné a padesát poutek uděláš na konci stanové plachty, která budou na druhém spojeném kusu. Poutka budou jedno naproti druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Uděláš padesát zlatých sponek a spojíš stanové plachty sponkami jednu ke druhé, takže z toho bude jeden příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Uděláš stanové plachty z kozí srsti pro stan nad příbytkem. Uděláš jedenáct takových stanových plachet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Délka jedné stanové plachty bude třicet loket a šířka jedné stanové plachty bude čtyři lokte; jedenáct stanových plachet bude mít stejný rozměr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Spojíš pět stanových plachet zvlášť a šest stanových plachet zvlášť. Šestou stanovou plachtu vepředu před stanem zdvojíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Uděláš padesát poutek na okraji jedné stanové plachty, té poslední, u jednoho spojeného kusu, a padesát poutek na okraji stanové plachty u druhého spojeného kusu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Uděláš padesát bronzových sponek a prostrčíš sponky do poutek; spojíš stan, takže z toho bude jeden celek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Přebývající závěs ze stanových plachet stanu, polovinu přebývající stanové plachty, necháš viset na zadní části příbytku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'loket z jedné strany a loket z druhé strany z přebývající délky stanové plachty. Stan bude viset přes boky příbytku z jedné i z druhého strany a zakrývat ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Uděláš pro stan také přikrývku z načerveno zbarvených beraních kůží a nahoru přikrývku z tachaších kůží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Uděláš pro příbytek stojaté desky z akáciového dřeva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Deset loket bude délka desky a loket a půl bude šířka každé desky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Každá deska bude mít dva čepy, jeden spojený s druhým. Tak to uděláš na všech deskách příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Uděláš desky pro příbytek: dvacet desek pro stranu jižní na jihu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Také uděláš čtyřicet stříbrných podstavců pod těch dvacet desek, dva podstavce pod jednu desku pro oba její čepy a dva podstavce pod druhou desku pro oba její čepy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Pro druhý bok příbytku, na severní stranu, též dvacet desek');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'a čtyřicet stříbrných podstavců k nim, dva podstavce pod jednu desku a dva podstavce pod druhou desku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Pro zadní stranu příbytku na západě uděláš šest desek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'A dvě desky uděláš do rohů příbytku na zadní straně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Budou dvojité odzdola a společně budou končit na vrchu do jednoho kruhu. Tak to bude s oběma, v obou rozích budou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Bude tedy osm desek a stříbrné podstavce k nim, šestnáct podstavců, dva podstavce pod jednu desku a dva podstavce pod druhou desku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Uděláš závory z akáciového dřeva; pět pro desky na jedné straně příbytku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'pět závor pro desky na druhé straně příbytku a pět závor pro desky na zadní straně příbytku, na západě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Prostřední závora bude sahat uprostřed desek od jednoho kraje k druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Desky potáhneš zlatem, k nim uděláš zlaté kruhy jako držáky pro závory a závory potáhneš zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Příbytek postavíš podle ⌈nařízení pro něj,⌉ které ti bylo ukázáno na hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Uděláš oponu z příze modré, purpurové a karmínové a z jemně tkaného plátna; na ní budou vytvořeni cherubové jako umělecké dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Upevníš ji na čtyři sloupy z akáciového dřeva potažené zlatem, se zlatými háky postavené na čtyřech stříbrných podstavcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Upevníš oponu na sponky a vneseš tam za oponu truhlu svědectví. Opona bude pro vás oddělovat svatyni od nejsvětějšího místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Dáš slitovnici na truhlu svědectví na nejsvětějším místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Postavíš stůl ven před oponu a svícen naproti stolu na jižní straně příbytku; stůl dáš na severní stranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Uděláš oponu pro vchod do stanu z příze modré, purpurové a karmínové a z jemně tkaného plátna, jako dílo výšivkáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Uděláš pro oponu pět sloupů z akáciového dřeva a potáhneš je zlatem a zlaté háky k nim a odliješ pro ně pět bronzových podstavců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Uděláš oltář z akáciového dřeva. Pět loket bude dlouhý a pět loket široký -- oltář bude čtvercový -- a tři lokte vysoký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Uděláš mu rohy ve čtyřech jeho rozích; jeho rohy budou ⌈z jednoho kusu s ním.⌉ Potáhneš ho bronzem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'A uděláš k němu hrnce na čištění od popela, lopaty, misky, vidlice a pánvičky na uhlíky. Všechny předměty k němu uděláš z bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Uděláš pro něj rošt udělaný jako mřížka z bronzu. Na tu mřížku uděláš čtyři bronzové kruhy na čtyři její konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Dáš ji zezdola pod okraj oltáře; mřížka bude až do poloviny oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Uděláš tyče pro oltář, tyče z akáciového dřeva a potáhneš je bronzem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Jeho tyče se vloží do kruhů; tyče budou na obou stranách oltáře, když se bude přenášet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Uděláš ho dutý z desek. Jak ti bylo ukázáno na hoře, tak to udělají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Uděláš také nádvoří příbytku: na straně jižní na jihu závěsy nádvoří z jemně tkaného plátna sto loket dlouhé na jedné straně');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'i dvacet sloupů k nim a dvacet bronzových podstavců k nim, háky na sloupech a obruče k nim ze stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Totéž podél strany severní: závěsy sto loket dlouhé, dvacet sloupů k nim a dvacet bronzových podstavců k nim a háky na sloupech a obruče k nim ze stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Po šířce nádvoří na západní straně: závěsy padesát loket, deset sloupů k nim a deset podstavců k nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Šířka nádvoří na straně východní na východě: padesát loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Patnáct loket závěsů na jedné straně, tři sloupy k nim a tři podstavce k nim');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'a na druhé straně patnáct loket závěsů, tři sloupy k nim a tři podstavce k nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Pro bránu nádvoří: oponu dvacet loket z příze modré, purpurové a karmínové a z jemně tkaného plátna, dílo výšivkáře; čtyři sloupy k ní a čtyři podstavce k nim');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'všechny sloupy nádvoří dokola budou obepnuty stříbrem, háky k nim budou ze stříbra a podstavce k nim z bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Nádvoří bude dlouhé sto loket, ⌈široké padesát⌉ a vysoké pět loket; bude z jemně tkaného plátna a podstavců z bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Všechny předměty příbytku pro všechnu jeho službu, všechny jeho kolíky a všechny kolíky nádvoří budou z bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'A ty přikážeš synům Izraele, aby ti přinesli čistý panenský olivový olej ke svícení, aby se mohly trvale zapalovat lampy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Ve stanu setkávání venku před oponou, která je před truhlou svědectví, je bude připravovat Áron a jeho synové od večera do rána před Hospodinem. To je ⌈věčné ustanovení⌉ mezi syny Izraele pro všechna jejich pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '⌈Nech před sebe přistoupit⌉ ze synů Izraele svého bratra Árona a s ním jeho syny, aby ⌈mi sloužili jako kněží:⌉ Árona a Áronovy syny Nádaba, Abíhúa, Eleazara a Ítamara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Uděláš ⌈svatá roucha⌉ pro svého bratra Árona ke ⌈cti a k okrase.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Promluvíš ke všem zručným lidem, které jsem naplnil ⌈duchem moudrosti,⌉ aby udělali Áronova roucha a posvětili ho, aby mi sloužil jako kněz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'A toto jsou roucha, která udělají: náprsník, efód, plášť, tkanou suknici, turban a šerpu. Udělají svatá roucha pro tvého bratra Árona a pro jeho syny, aby mi sloužil jako kněz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Vezmou zlato, přízi modrou, purpurovou a karmínovou a jemné plátno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Udělají efód ze zlata, z příze modré, purpurové a karmínové a z jemně tkaného plátna jako umělecké dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Bude mít dva nárameníky připojené na jeho dvou koncích a tak bude spojen dohromady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, '⌈Ozdobný pás⌉ jeho efódu, který je na něm, bude udělán jako on z jednoho kusu s ním -- ze zlata, příze modré, purpurové a karmínové a z jemně tkaného plátna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Vezmeš dva karneolové kameny a vyryješ na ně jména Izraelových synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Šest jejich jmen na jeden kámen a šest zbývajících jmen na druhý kámen podle jejich narození.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Jako kamenorytcem vytvořený pečetní nápis vyryješ na ty dva kameny jména Izraelových synů. Vsadíš je do zlatých obrouček');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'a vložíš oba kameny na nárameníky efódu jako připomínkové kameny synů Izraele. Áron bude nosit jejich jména před Hospodinem na obou ramenech jako připomínku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Uděláš zlaté obroučky');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'a dva řetízky z čistého zlata; uděláš je spletené ⌈jako se vytváří provázky⌉ a upevníš tyto provázkové řetízky na obroučky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Uděláš náprsník rozhodnutí jako umělecké dílo; uděláš ho jako efód -- uděláš ho ze zlata, příze modré, purpurové a karmínové a z jemně tkaného plátna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Bude čtvercový a dvojitý, píď dlouhý a píď široký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Vsadíš do něj vsazené kameny, čtyři řady kamenů; řada rubín, topas a smaragd bude řada první;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'řada druhá -- malachit, safír a jaspis;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'řada třetí -- opál, achát a ametyst');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'a řada čtvrtá -- chryzolit, karneol a onyx. Budou vsazeny do zlata ve svých obroučkách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Kamenů bude podle jmen Izraelových synů, dvanáct, podle jejich jmen; jako pečetní nápis bude každý podle svého jména pro dvanáct kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Uděláš k náprsníku řetízky z čistého zlata spletené jako se vytváří provázky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Uděláš k náprsníku dva zlaté kroužky a upevníš ty dva kroužky na oba okraje náprsníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Dva zlaté provázky upevníš ke dvěma kroužkům na okraji náprsníku');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'a druhé dva konce obou provázků upevníš ke dvěma obroučkám a dáš dopředu na nárameníky efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Uděláš dva zlaté kroužky a umístíš je na dva okraje náprsníku, na vnitřní okraj, který je na straně efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Uděláš dva zlaté kroužky a upevníš je na dva nárameníky efódu zepředu zezdola u spojeného kusu nad ozdobný pás efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Náprsník přivážou modrou šňůrkou z jeho kroužků na kroužky efódu, aby byl nad ozdobným pásem efódu; náprsník nebude odstávat od efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Áron bude nosit jména Izraelových synů na náprsníku rozhodnutí na svém srdci, když bude vcházet do svatyně, jako ustavičnou připomínku před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Do náprsníku rozhodnutí vložíš urím a tumím a budou na Áronově srdci, když bude vcházet před Hospodina. Áron bude ustavičně nosit rozhodnutí pro syny Izraele na svém srdci před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Uděláš plášť efódu, celý z modré příze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Uprostřed bude mít otvor pro hlavu; lem na otvoru bude kolem dokola tkaný, bude mít okraj jako kožený pancíř, aby se nemohl roztrhnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Na jeho spodním lemu uděláš granátová jablka z příze modré, purpurové a karmínové, kolem dokola na jeho lemu a mezi nimi budou dokola zlaté zvonečky:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'zlatý zvoneček a granátové jablko, zlatý zvoneček a granátové jablko budou kolem dokola na lemu pláště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Plášť bude na Áronovi, když bude sloužit, aby byl slyšet jeho zvuk, když bude vcházet do svatyně před Hospodina a když bude vycházet, aby nezemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Uděláš květ z čistého zlata a vyryješ na něj pečetní nápis: Svatý Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Dáš ho na modrou šňůrku a bude na turbanu, bude vepředu na turbanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Bude na Áronově čele, aby Áron mohl nést provinění ohledně svatých věcí, které synové Izraele zasvěcují, při všech svých svatých darech. Bude ustavičně na jeho čele, aby došli zalíbení před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, '⌈Utkáš vzorovanou⌉ suknici z jemného plátna, uděláš turban z jemného plátna a uděláš šerpu jako dílo výšivkáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'I Áronovým synům uděláš suknice, uděláš pro ně šerpy a uděláš jim klobouky ke cti a k okrase.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Oblékneš to svému bratru Áronovi a s ním jeho synům, pomažeš je, zmocníš je a posvětíš je, aby mi sloužili jako kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Udělej jim lněné spodky, aby zakrývaly jejich nahé tělo; budou sahat od beder až po stehna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Budou na Áronovi a na jeho synech, když budou vcházet do stanu setkávání nebo přistupovat k oltáři, aby sloužili ve svatyni, tak aby nenesli vinu a ne zemřeli. To je věčné ustanovení pro něj a pro jeho potomstvo po něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Toto s nimi uděláš, abys je posvětil, aby mi sloužili jako kněží: Vezmi jednoho býčka a dva berany bez vady,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'nekvašený chléb, nekvašené bochníky namísené s olejem, nekvašené placky pomazané olejem; uděláš je z jemné pšeničné mouky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Dáš je do jednoho koše a přineseš je v koši -- a k tomu toho býčka a dva berany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'I Árona a jeho syny přivedeš ke vchodu do stanu setkávání. Umyješ je vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Vezmeš roucha a oblékneš Áronovi suknici, plášť efódu, efód a náprsník a zavážeš ho ⌈ozdobným pásem⌉ efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Na hlavu mu položíš turban a upevníš na turbanu svatou čelenku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Vezmeš olej pomazání, vyleješ mu ho na hlavu a pomažeš ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Přivedeš i jeho syny a oblékneš jim suknice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Přepásáš je šerpou, Árona a jeho syny, a přivážeš jim klobouky. Jim bude patřit kněžství jako věčné ustanovení. Zasvětíš Árona a jeho syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Přivedeš býčka před stan setkávání a Áron se svými syny položí ruce na hlavu býčka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Pak zabiješ býčka před Hospodinem u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Vezmeš trochu krve z býčka a dáš ji prstem na rohy oltáře a všechnu ostatní krev vyleješ ke spodku oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Vezmeš všechen tuk pokrývající vnitřnosti, jaterní lalok, obě ledviny a tuk, který je na nich, a budeš to obětovat na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Maso býčka, jeho kůži a jeho výměty spálíš ohněm ⌈venku za táborem.⌉ To je ⌈oběť za hřích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Pak vezmeš jednoho berana a Áron se svými syny položí ruce na hlavu berana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Zabiješ berana, vezmeš jeho krev a pokropíš s ní oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Berana rozsekáš na díly, vnitřnosti a hnáty umyješ a dáš na jeho díly a jeho hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Budeš obětovat celého berana na oltáři. To je zápalná oběť Hospodinu, příjemná vůně; to je ohnivá oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Vezmeš druhého berana a Áron se svými syny na hlavu toho berana položí ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Zabiješ berana, vezmeš trochu jeho krve a dáš na lalůček Áronova pravého ucha i na lalůček pravého ucha jeho synů, na palec jejich pravé ruky a palec jeho pravé nohy a pokropíš krví oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Vezmeš trochu z krve na oltáři a oleje pomazání a stříkneš na Árona a jeho roucha a na jeho syny a roucha jeho synů s ním. Tak bude posvěcen on a jeho roucha, jeho synové a roucha jeho synů s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Vezmeš z berana tuk, tučný ocas, tuk pokrývající vnitřnosti, jaterní lalok, obě ledviny a tuk, který je na nich, a pravou kýtu, neboť to je beran zasvěcení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'a jeden bochník chleba, jeden bochník chleba s olejem, jednu placku z koše s nekvašenými chleby, který je před Hospodinem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'a to všechno dáš do ruky Árona a do ruky jeho synů a zamáváš s tím před Hospodinem jako mávanou obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Vezmeš to z jejich ruky a budeš to obětovat na oltáři jako zápalnou oběť, jako příjemnou vůni před Hospodinem. To je ohnivá oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Vezmeš také hrudí z Áronova berana zasvěcení a zamáváš s ním před Hospodinem jako s mávanou obětí; bude patřit tobě jako podíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Posvětíš hrudí mávané oběti a kýtu daru pozdvihování, kterými bylo máváno a pozdvihováno z berana zasvěcení Árona a jeho synům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'To bude patřit Áronovi a jeho synům jako věčný příděl od synů Izraele, neboť to je dar pozdvihování. Dar pozdvihování bude od synů Izraele z obětního hodu jejich pokojných obětí jako jejich dar pozdvihování Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Áronova svatá roucha zůstanou jeho synům po něm, aby v nich byli pomazáváni a zasvěcováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sedm dní je bude oblékat kněz, který nastoupí na jeho místo z jeho synů, když bude vcházet do stanu setkávání, aby sloužil ve svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Vezmeš berana zasvěcení a uvaříš jeho maso na svatém místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'U vchodu do stanu setkávání bude Áron se svými syny jíst maso z berana a chléb, který bude v koši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Ti mohou jíst věci, s nimiž byl vykonán obřad smíření, aby byli zasvěceni a posvěceni. Nikdo jiný je jíst nebude, protože jsou svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Jestliže zůstane něco z masa zasvěcení a z chleba až do rána, spálíš to, co zbude, ohněm; nebude se to jíst, protože je to svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'S Áronem a s jeho syny naložíš takto, právě tak, jak jsem ti přikázal; sedm dní je budeš zasvěcovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Denně budeš připravovat býčka k oběti za hřích na smíření; očistíš oltář od hříchu, když za něj vykonáš obřad smíření a pomažeš ho, abys ho posvětil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sedm dní budeš konat obřad smíření za oltář. Posvětíš ho a oltář bude nejsvětějším místem. Cokoliv se dotkne oltáře, bude svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'A toto budeš připravovat na oltáři: dva roční beránky denně, ustavičně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Jednoho beránka připravíš ráno a druhého beránka připravíš navečer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Desetinu éfy jemné mouky namísené se čtvrtinou hínu panenského oleje a jako litou oběť čtvrtinu hínu vína na jednoho beránka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Druhého beránka připravíš navečer, jako ranní přídavnou oběť a jako patřičnou litou oběť ji připravíš -- jako příjemnou vůni, ohnivou oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'To bude ustavičná zápalná oběť pro všechna vaše pokolení u vchodu do stanu setkávání před Hospodinem, kde se s vámi budu setkávat, abych tam k tobě mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Tam se budu setkávat se syny Izraele a ⌈ stan bude posvěcen mou⌉ slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Posvětím stan setkávání a oltář a posvětím Árona a jeho syny, aby mi sloužili jako kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Budu přebývat uprostřed synů Izraele a budu jejich Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'A poznají, že já Hospodin jsem jejich Bůh, který jsem je vyvedl z egyptské země, abych přebýval uprostřed nich. Já Hospodin jsem jejich Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Uděláš oltář, místo pro pálení kadidla; uděláš ho z akáciového dřeva,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'loket dlouhý a loket široký -- bude čtvercový, dva lokte vysoký; jeho rohy budou z jednoho kusu s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Potáhneš ho čistým zlatem -- jeho vrch, jeho stěny kolem dokola i jeho rohy -- a uděláš mu kolem dokola zlatou obrubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Též dva zlaté kruhy uděláš pro něj pod jeho obrubou; uděláš je na obou jeho bocích, na obou stranách. To budou držáky pro tyče, aby se na nich mohl nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Uděláš tyče z akáciového dřeva a potáhneš je zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Dáš ho před oponu, která je před truhlou svědectví, před slitovnici, která je nad svědectvím, kde se s tebou budu setkávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Áron na něm bude pálit vonné kadidlo. Bude ho pálit ráno co ráno, když bude čistit lampy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'a bude ho pálit navečer, když bude Áron zapalovat lampy; to bude ustavičná oběť kadidla před Hospodinem pro všechny vaše generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Nebudete na něm přinášet cizí kadidlo ani zápalnou či přídavnou oběť, ani na něm nebudete vylévat litou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Jednou v roce vykoná Áron na jeho rozích obřad smíření. S krví smírčí oběti za hřích bude na něm konat obřad smíření po vaše všechny generace. Je to Hospodinova nejsvětější věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Když ⌈učiníš soupis⌉ synů Izraele a spočítáš je, dá každý výkupné za svou duši Hospodinu, když je spočítáš, aby mezi nimi nenastala pohroma, když je spočítáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Toto dá každý, kdo přechází ke spočítaným: polovinu šekelu podle šekelu svatyně (šekel je dvacet gér); polovina šekelu je dar pozdvihování pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Každý, kdo přechází ke spočítaným, od dvacetiletých výše, dá Hospodinův dar pozdvihování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bohatý nedá více a chudý nedá méně než polovinu šekelu, když budou dávat dar pozdvihování Hospodinu na obřad smíření za vaše duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Vezmeš stříbro smíření od synů Izraele a dáš ho na službu stanu setkávání. Bude pro syny Izraele jako připomínka před Hospodinem na usmíření pro vaše duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Uděláš bronzovou nádrž s bronzovým podstavcem pro umývání. Dáš ji mezi stan setkávání a oltář a dáš do ní vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Áron a jeho synové si vodou z ní budou umývat ruce a nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Když budou vcházet do stanu setkávání, umyjí se vodou, aby nezemřeli; nebo když budou přistupovat k oltáři, aby sloužili a pálili ohnivou oběť Hospodinu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'umyjí si ruce a nohy, aby nezemřeli. Bude to pro ně věčné ustanovení, pro něj i pro jeho potomky, po všechny jejich generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Vezmi si nejlepší balzámy: pět set šekelů tekuté myrhy, polovinu, tedy dvě stě padesát šekelů vonné skořice a dvě stě padesát šekelů vonného koření');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'a pět set šekelů kasie podle šekelu svatyně a hín olivového oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Uděláš z toho svatý olej pomazání, míchanou mast, jako dělají mastičkáři. To bude svatý olej pomazání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Pomažeš s ním stan setkávání a truhlu svědectví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'stůl a všechno jeho náčiní, svícen a jeho náčiní, oltář pro kadidlo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'oltář pro zápalnou oběť a všechno jeho náčiní, nádrž a její podstavec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Posvětíš je a budou to nejsvětější věci. Cokoliv se jich dotkne, bude svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Pomažeš také Árona a jeho syny a posvětíš je, aby mi sloužili jako kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'A synům Izraele řekneš: Toto bude můj svatý olej pomazání po všechny vaše generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Na lidské tělo se nebude běžně mazat a jemu podobný olej stejného složení nebudete připravovat. Je svatý, bude pro vás svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Kdokoliv by připravil olej jemu podobný anebo dal z něho na někoho nepatřičného, bude vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Hospodin řekl Mojžíšovi: Vezmi si vonné látky: pryskyřici, onychu a galbanum, tyto vonné látky a čisté kadidlo; ⌈budou v poměru jedna ku jedné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Uděláš z toho míchané kadidlo jako dělají mastičkáři, posolené, čisté, svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Trochu z něj důkladně rozdrtíš a dáš trochu před svědectví ve stanu setkávání, kde se s tebou budu setkávat. Bude to pro vás svatosvatá věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Nebudete si připravovat kadidlo stejného složení jako to kadidlo, které uděláš; bude pro tebe svaté pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Kdokoliv by připravil jemu podobné, aby se s ním voněl, bude vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Hleď, povolal jsem jmenovitě Besaleela, syna Urího, syna Chúrova, z pokolení Judova');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'a naplnil jsem ho Božím Duchem, ⌈moudrostí, rozumností, poznáním⌉ pro každou práci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'aby vymýšlel nápady pro práci se zlatem, stříbrem a bronzem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'pro řezání kamene ke vsazování, pro vyřezávání dřeva, pro práci na jakémkoliv díle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'A hle, já jsem k němu ustanovil Oholíaba, syna Achísamakova z pokolení Danova, a do srdce ⌈všech zručných lidí ⌉ jsem dal moudrost, aby učinili vše, co jsem ti přikázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Stan setkávání, truhlu pro svědectví, slitovnici, která je na ni, a všechny předměty stanu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'stůl a jeho náčiní, čistý svícen a všechno jeho náčiní, oltář pro kadidlo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'oltář pro zápalnou oběť a všechno jeho náčiní, nádrž a její podstavec,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'jemně tkaná roucha, svatá roucha pro kněze Árona a roucha jeho synů, aby sloužili jako kněží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'olej pomazání a vonné kadidlo pro svatyni. Ať udělají všechno tak, jak jsem ti přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Hospodin řekl Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Promluv k synům Izraele: Jistě budete zachovávat mé soboty, neboť to je znamení mezi mnou a vámi po všechny vaše generace, abyste věděli, že já Hospodin vás posvěcuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Budete zachovávat sobotu, neboť je pro vás svatá. Ten, kdo by ji znesvětil, jistě bude usmrcen; ano, každý, kdo by v ní dělal nějakou práci, takový člověk bude vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Po šest dní se bude konat práce a sedmý den bude nejsvětější sobota, svatá Hospodinu. Každý, kdo by dělal práci v sobotní den, jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Ať synové Izraele zachovávají sobotu a slaví sobotu po všechny své generace jako věčnou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Bude věčným znamením mezi mnou a syny Izraele, neboť v šesti dnech Hospodin učinil nebesa a zemi a sedmý den přestal a oddechl si.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Když s ním na hoře Sínaj domluvil, dal Mojžíšovi dvě desky svědectví, kamenné desky popsané Božím prstem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Když lid viděl, že Mojžíš ⌈otálí sestoupit⌉ z hory, shromáždil se proti Áronovi a řekl mu: Vstaň a udělej nám bohy, kteří půjdou před námi. Vždyť o tom Mojžíšovi, muži, který nás vyvedl z egyptské země, -- nevíme, co se s ním stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Áron jim odpověděl: Strhněte zlaté kroužky, které jsou na uších vašich žen, vašich synů a vašich dcer a přineste mi to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Všechen lid strhl zlaté kroužky, které měli na uších, a přinesli to Áronovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Vzal to od nich, odlil to do formy a udělal slité tele. Nato oni řekli: Izraeli, toto jsou tvoji bohové, kteří tě vyvedli z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Když to Áron viděl, postavil před ním oltář. Pak Áron zvolal: Zítra bude Hospodinův svátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Příštího dne časně vstali, obětovali zápalné oběti a přinesli pokojné oběti. Pak se lid usadil, aby jedli a pili; načež vstali, aby dováděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Hospodin promluvil k Mojžíšovi: Jdi, sestup dolů, neboť tvůj lid, který jsi vyvedl z egyptské země, propadl zvrácenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Rychle se odvrátili od cesty, kterou jsem jim přikázal; udělali si slité tele, klaněli se mu, obětovali mu a říkali: Izraeli, toto jsou tvoji bohové, kteří tě vyvedli z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Hospodin řekl Mojžíšovi: Díval jsem se na tento lid. Hle, je to lid tvrdé šíje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Nyní mě nech, abych vzplanul hněvem proti nim a skoncoval s nimi. Tebe však učiním velkým národem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mojžíš se snažil udobřit Hospodina, svého Boha, a řekl: Hospodine, proč vzplanul tvůj hněv proti tvému lidu, který jsi vyvedl z egyptské země velkou silou a mocnou rukou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Proč by měli Egypťané říkat: Se zlým úmyslem je vyvedl, aby je pobil v horách a vyhubil je z povrchu země? Odvrať se od svého planoucího hněvu a lituj zla vůči svému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Pamatuj na Abrahama, Izáka a Izraele, své otroky, kterým jsi při sobě přísahal a řekl jsi jim: Rozmnožím vaše potomstvo jako nebeské hvězdy a celou tuto zemi, o níž jsem promluvil, dám vašemu potomstvu a dostanou ji navěky do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'A Hospodin litoval zla, které promluvil, že učiní svému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mojžíš se vydal na cestu a sestupoval z hory. V ruce měl dvě desky svědectví, desky popsané z obou stran; byly popsány z jedné i druhé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Ty desky byly Boží dílo, to písmo bylo Boží písmo, vyryté na deskách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Když Jozue uslyšel halas lidu, jak křičí, řekl Mojžíšovi: V táboře je válečný křik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'On řekl: Není to křik vítězů ani křik poražených, slyším křik zpívajících!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'I stalo se, když se přiblížil k táboru a uviděl tele a tance, vzplanul Mojžíš hněvem, odhodil desky z rukou a roztřískal je pod horou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Vzal tele, které udělali, spálil ho ohněm, drtil ho, až ho rozdrtil, rozsypal ho na hladinu vody a dal pít synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Mojžíš řekl Áronovi: Co ti ten lid udělal, že jsi na něj uvedl tak velký hřích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Áron odpověděl: Ať můj pán neplane hněvem. Ty znáš tento lid, že je nakloněn ke zlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Řekli mi: Udělej nám bohy, kteří půjdou před námi. Vždyť o tom Mojžíšovi, muži, který nás vyvedl z egyptské země, nevíme, co se s ním stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Odpověděl jsem jim: Kdo má zlato, strhněte ho. Dali mi ho, hodil jsem ho do ohně a vyšlo z toho toto tele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Když Mojžíš viděl, že je lid bez zábran -- protože Áron ho nechal bez zábran ku posměchu jejich protivníků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'postavil se Mojžíš do brány tábora a zavolal: Kdo je Hospodinův, ke mně. Shromáždili se k němu všichni synové Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'On jim řekl: Toto praví Hospodin, Bůh Izraele: Připašte si každý meč k boku, projděte tábor sem a tam od brány k bráně a zabíjejte každý svého bratra, každý svého přítele, každý svého příbuzného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Synové Léviho učinili podle Mojžíšova příkazu a onoho dne padlo z lidu asi tři tisíce mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Mojžíš řekl: Zasvěťte se dnes Hospodinu, neboť každý byl proti svému synovi a proti svému bratru, aby vám dnes dal požehnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'I stalo se příštího dne, že Mojžíš řekl lidu: Zhřešili jste velkým hříchem. Nyní vystoupím k Hospodinu, snad získám smíření za váš hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Mojžíš se vrátil k Hospodinu a řekl: Ach, tento lid zhřešil velkým hříchem. Udělali si zlaté bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Nuže, jestli sejmeš jejich hřích, bude dobře, jestli ne, vymaž mě ze své knihy, kterou jsi napsal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Hospodin Mojžíšovi odpověděl: Kdo proti mně zhřešil, toho vymažu ze své knihy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Nyní jdi a veď lid, kam jsem ti řekl. Hle, můj anděl půjde před tebou. Ale v den svého navštívení je navštívím s trestem za jejich hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Hospodin postihl lid za to, co udělali s teletem, které udělal Áron.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Hospodin promluvil k Mojžíšovi: Jdi a vytáhni odsud, ty i lid, který jsi vyvedl z egyptské země, do země, o níž jsem přísahal Abrahamovi, Izákovi a Jákobovi slovy: Tvému potomstvu ji dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Pošlu před tebou anděla a vyženu Kenaance, Emorejce, Chetejce, Perizejce, Chivejce a Jebúsejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Jdi do země oplývající mlékem a medem. Ale já nevytáhnu ve tvém středu, neboť jsi lid tvrdé šíje. Jinak bych s tebou po cestě skoncoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Když lid uslyšel tuto ⌈špatnou zprávu,⌉ truchlili a ⌈nebrali na sebe ozdoby.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Hospodin totiž řekl Mojžíšovi: Řekni synům Izraele: Jste lid tvrdé šíje. Půjdu– li jediný okamžik ve tvém středu, skoncuji s tebou. Nyní sundej ze sebe své ozdoby, abych poznal, jak mám s tebou naložit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Tak se synové Izraele od hory Choréb zbavili svých ozdob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mojžíš vzal stan a postavil ho venku za táborem, daleko od tábora, a nazval ho stanem setkávání. Každý, kdo hledal Hospodina, vycházel ke stanu setkávání, který byl venku za táborem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'I stalo se, když Mojžíš vycházel ke stanu, že všechen lid povstával, zůstali stát každý u vchodu do svého stanu a hleděli za Mojžíšem, dokud nevešel do stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'A kdykoli Mojžíš vcházel do stanu, sestupoval oblakový sloup a zastavil se u vchodu do stanu; a Hospodin mluvil s Mojžíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Když všechen lid viděl oblakový sloup stojící u vchodu do stanu, všechen lid povstal a klaněli se, každý u vchodu do svého stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Hospodin mluvil s Mojžíšem tváří v tvář, tak jako mluví člověk se svým přítelem. Pak se vrátil do tábora, ale jeho služebník Jozue, syn Núnův, mládenec, se od stanu nevzdaloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Mojžíš řekl Hospodinu: Pohleď, ty mi říkáš: Vyveď tento lid, ale nedal jsi mi poznat, koho se mnou pošleš. Také jsi řekl: Znám tě jménem, ano nalezl jsi milost v mých očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Nuže, jestliže jsem opravdu nalezl milost ve tvých očích, dej mi poznat svou cestu, abych tě poznal a abych nalezl milost ve tvých očích a pohleď, že tento národ je tvým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Odpověděl: Moje přítomnost půjde s tebou a dám ti odpočinek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'I řekl mu: Jestliže tvá přítomnost nepůjde s námi, nevyváděj nás odsud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Podle čeho se přece pozná, že jsem nalezl milost ve tvých očích, já i tvůj lid? Cožpak ne podle toho, že půjdeš s námi, takže budeme odlišeni, já a tvůj lid, od všech národů, které jsou na povrchu země?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Hospodin řekl Mojžíšovi: I to, o čem jsi promluvil, učiním, neboť jsi nalezl milost v mých očích a znám tě jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'On řekl: Ukaž mi svou slávu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Odpověděl: Nechám projít kolem tebe všechnu svou dobrotu a zavolám před tebou jméno Hospodin. Smiluji se, nad kým se smiluji, a slituji se, nad kým se slituji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Řekl: Nemůžeš vidět mou tvář, neboť člověk mě nemůže vidět a zůstat naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'A Hospodin řekl: Zde je místo u mě; zůstaň stát na skále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'I stane se, až bude přecházet má sláva, postavím tě do skalní dutiny a položím na tebe svou dlaň, dokud nepřejdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Pak sejmu svou dlaň a uvidíš má záda, ale má tvář nebude vidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Hospodin řekl Mojžíšovi: Vytesej si dvě kamenné desky stejné jako ty první, a napíši na desky slova, která byla na prvních deskách, jež jsi roztřískal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Buď ráno připraven. Vystoupíš ráno na horu Sínaj a zůstaneš tam přede mnou stát na vrcholu hory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Nikdo s tebou nevystoupí a nikdo se neukáže na celé hoře; ani brav či skot se nebude pást směrem k té hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Mojžíš vytesal dvě kamenné desky, stejné jako ty první, časně z rána vstal a vystoupil na horu Sínaj, jak mu Hospodin přikázal, a vzal s sebou dvě kamenné desky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Hospodin sestoupil v oblaku, stál tam s ním a zavolal jméno Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Hospodin prošel kolem něho a zavolal: Hospodin, Hospodin, Bůh soucitný a milostivý, pomalý k hněvu, hojný v milosrdenství a věrnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'zachovává milosrdenství tisícům, snímá vinu, přestoupení a hřích, jistě však nenechá viníka bez trestu, navštěvuje s trestem vinu otců na synech i na synech synů, na třetí i čtvrté generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Mojžíš rychle poklekl na zem, klaněl se');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'a řekl: Jestliže jsem nalezl milost ve tvých očích, Panovníku, ať jde Panovník v našem středu, přestože je to lid tvrdé šíje. Odpusť naši vinu a náš hřích a přijmi nás do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'On řekl: Hle, uzavírám smlouvu: Před celým tvým lidem učiním divy, jaké nebyly stvořeny na celé zemi ani v žádném národě. A celý národ, uprostřed něhož jsi, uvidí Hospodinovo dílo, protože to, co s tebou učiním, bude vzbuzovat hrůzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Dbej na to, co ti dnes přikazuji. Hle, vyženu před tebou Emorejce, Kenaance, Chetejce, Perizejce, Chivejce a Jebúsejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Měj se na pozoru, abys neuzavřel smlouvu s obyvateli země, do níž jdeš, jinak budou léčkou ve tvém středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Naopak jejich oltáře strhněte, jejich posvátné sloupy roztřískejte, jejich posvátné kůly pokácejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Nebudete se klanět jinému bohu, neboť Hospodin, jehož jméno je Žárlivý, je Bůh žárlivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Neuzavírej smlouvu s obyvateli země; budou chodit smilnit za svými bohy, budou obětovat svým bohům a pozvou tě, budeš jíst z jejich obětních hodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'A budeš si brát z jejich dcer pro své syny a jejich dcery budou chodit smilnit za svými bohy a přivedou tvé syny, aby chodili smilnit za jejich bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Slité bohy si nedělej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Budeš zachovávat svátek nekvašených chlebů. Po sedm dní budeš jíst nekvašené chleby, jak jsem ti přikázal, v určený čas měsíce ábíbu, neboť v měsíci ábíbu jsi vyšel z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Všechno, co otvírá lůno, patří mně; každý samec ze tvého dobytka, prvorozené ze skotu i ovcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Prvorozeného osla vykoupíš ovcí. Jestliže ho nevykoupíš, zlomíš mu vaz. Každého prvorozeného ze svých synů vykoupíš. Nikdo se neukáže přede mnou s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Šest dní budeš pracovat a sedmý den přestaneš. I při orbě a při žni přestaneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Budeš slavit svátek týdnů, prvotin pšeničné žně a svátek sklizně na konci roku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Třikrát za rok se každý, kdo je u tebe mužského pohlaví, ukáže před Panovníkem Hospodinem, Bohem Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Neboť vyženu před tebou pohanské národy a rozšířím tvé území a nikdo nebude dychtit po tvé zemi, když budeš třikrát za rok vystupovat, aby ses ukázal před Hospodinem, svým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Nebudeš obětovat krev mé oběti ⌈spolu s⌉ kvašeným. Nezůstane do rána nic z oběti svátku Velikonoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, '⌈ To nejlepší z prvotin své země přineseš do domu Hospodina, svého Boha. Nebudeš vařit kůzle v mléce jeho matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Hospodin řekl Mojžíšovi: Napiš si tato slova, neboť podle těchto slov jsem uzavřel smlouvu s tebou a s Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Byl tam s Hospodinem čtyřicet dní a čtyřicet nocí; chléb nejedl a vodu nepil a napsal na desky slova smlouvy, Deset slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'I stalo se, když Mojžíš sestupoval z hory Sínaj -- dvě desky svědectví byly v Mojžíšově ruce, když sestupoval z hory -- že Mojžíš nevěděl, že kůže jeho tváře září od toho, jak s ním mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Když Áron a všichni synové Izraele uviděli Mojžíše, a hle, kůže jeho tváře zářila, báli se k němu přiblížit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mojžíš však na ně zavolal a Áron i všichni předáci v pospolitosti se k němu vrátili; Mojžíš k nim promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Potom přistoupili všichni synové Izraele a on jim vydal příkazy, vše, co s ním mluvil Hospodin na hoře Sínaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Když s nimi Mojžíš domluvil, dal si na tvář závoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Kdykoli přicházel Mojžíš před Hospodina, aby s ním mluvil, sundával si závoj, dokud nevyšel. Když vyšel, a mluvil k synům Izraele to, co mu bylo přikázáno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'synové Izraele viděli Mojžíšovu tvář, že kůže Mojžíšovy tváře zářila. Mojžíš si tedy bral závoj zpět na tvář, dokud s ním nešel mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Mojžíš svolal celou pospolitost synů Izraele a řekl jim: Toto jsou slova, která Hospodin přikázal, abyste je plnili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Po šest dní se bude konat práce a sedmý den bude pro vás svatá, nejsvětější sobota Hospodinu. Každý, kdo by v ní dělal práci, bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Nebudete zapalovat oheň v žádném ze svých sídel v sobotní den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Mojžíš řekl celé pospolitosti synů Izraele: Toto přikázal Hospodin:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Vyberte mezi sebou dar pro Hospodina. Každý, kdo je ochotného srdce, přinese Hospodinův dar: zlato, stříbro a bronz,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'přízi modrou, purpurovou a karmínovou, jemné plátno a kozí srst,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'načerveno zbarvené beraní kůže, tachaší kůže a akáciové dřevo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'olej ke svícení, balzámy na olej pomazání a na vonné kadidlo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'kameny karneolové a další kameny pro vsazování do efódu a náprsníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Ať všichni zruční lidé mezi vámi přijdou a dělají vše, co Hospodin přikázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Příbytek, jeho stan, jeho přikrývku, jeho sponky, jeho desky, jeho závory, jeho sloupy a jeho podstavce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'truhlu a její tyče, slitovnici a zakrývající oponu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'stůl a jeho tyče, všechno jeho náčiní, předkladný chléb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'svícen na svícení a jeho náčiní, jeho lampy a olej ke svícení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'oltář pro kadidlo a jeho tyče, olej pomazání a vonné kadidlo, oponu vchodu pro vchod do příbytku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'oltář pro zápalnou oběť a k němu bronzový rošt, jeho tyče a všechno jeho náčiní, nádrž a její podstavec,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'závěsy nádvoří, jeho sloupy a jeho podstavce, oponu brány do nádvoří,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'kolíky příbytku a kolíky nádvoří i jejich lana,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'jemně tkaná roucha pro službu ve svatyni, svatá roucha pro kněze Árona a roucha pro jeho syny, aby sloužili jako kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Pak celá pospolitost synů Izraele odešla od Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Potom přišli všichni, které ponoukalo jejich srdce, a všichni, které podněcoval jejich duch, a přinesli Hospodinův dar na práci na stanu setkávání, na všechnu jeho službu i na svatá roucha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Muži i ženy, všichni ochotného srdce přišli a přinesli sponky, náušnice, prsteny a řetízky, všelijaké zlaté předměty, každý, kdo zamával zlatem jako mávanou obětí pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'A všichni, kdo měli u sebe přízi modrou, purpurovou a karmínovou, jemné plátno, kozí srst, načerveno zbarvené beraní kůže a kůže tachaší, je přinesli;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'všichni, kdo přinášeli dar stříbra a bronzu, přinášeli to jako Hospodinův dar; a všichni, kdo měli u sebe akáciové dřevo pro všechno dílo služby, to přinesli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Všechny zručné ženy předly svýma rukama a přinesly, co napředly, příze modré, purpurové a karmínové i jemné plátno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Všechny ženy, které ponoukalo jejich srdce k zručnosti, předly kozí srst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Předáci přinášeli kameny karneolové a kameny pro vsazování do efódu a náprsníku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'také balzámy a olej: ke svícení, na olej pomazání a na vonné kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Synové Izraele, všichni muži a ženy, které podněcovalo jejich srdce, aby něco přinesli na všechnu práci, kterou prostřednictvím Mojžíše Hospodin přikázal vykonat, přinesli dobrovolnou oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Mojžíš řekl synům Izraele: Hleďte, Hospodin povolal jmenovitě Besaleela, syna Urího, syna Chúrova, z pokolení Judova');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'a naplnil ho Božím Duchem, moudrostí, rozumností a poznáním pro každou práci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'aby vymýšlel plány pro práci se zlatem, stříbrem a bronzem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'pro řezání kamene ke vsazování, pro vyřezávání dřeva, pro práci na jakémkoliv důmyslném díle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Dal mu do srdce také schopnost učit, jemu i Oholíabovi, synu Achísamakovu z pokolení Danova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Naplnil je zručností dělat všechnu práci řemeslnou, uměleckou a výšivkářskou na přízi modrou, purpurovou, karmínovou i na jemné plátno, stejně jako práci tkalcovskou -- aby konali veškerou práci a vymýšleli nápady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Besaleel s Oholíabem a všemi zručnými lidmi, jimž dal Hospodin zručnost a rozumnost, aby věděli, jak udělat všechno dílo služby svatyně, ať dělají všechno, co Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Mojžíš potom povolal Besaleela a Oholíaba a všechny zručné lidi, kterým dal Hospodin do srdce moudrost, všechny, které ponoukalo srdce přistoupit k práci a konat ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Vzali od Mojžíše všechny dary, které synové Izraele přinesli na dílo služby svatyně, aby je vykonali. Synové Izraele mu však dál ráno co ráno přinášeli dobrovolné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'A proto přišli všichni zruční lidé, kteří konali veškeré dílo svatyně, každý od své práce, kterou konal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'a říkali Mojžíšovi: Lid přináší víc, nežli je třeba na službu pro dílo, které Hospodin přikázal vykonat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Nato Mojžíš přikázal a nechal v táboře rozhlásit: Muž ani žena ať již nepřipravují zásobu na dar svatyně. A lid přestal přinášet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Byla již dostatečná zásoba, aby bylo vykonáno veškeré dílo a ještě zbylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Nato všichni zruční lidé ⌈zapojení do práce⌉ udělali příbytek z deseti stanových plachet z jemně tkaného plátna, z příze modré, purpurové a karmínové; Besaleel na nich udělal cheruby jako umělecké dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Délka jedné stanové plachty byla dvacet osm loket a šířka jedné stanové plachty byla čtyři lokte; všechny stanové plachty měly stejný rozměr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Pět stanových plachet spojil jednu k druhé a dalších pět stanových plachet spojil jednu k druhé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Udělal poutka z modré příze na okraji jedné stanové plachty na konci jednoho spojeného kusu a tak to udělal na okraji poslední stanové plachty na spojeném kusu druhém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Padesát poutek udělal na stanové plachtě jedné a padesát poutek udělal na konci stanové plachty, která byla na druhém spojeném kusu; poutka byla jedno naproti druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Udělal padesát zlatých sponek a spojil stanové plachty sponkami jednu k druhé, takže z toho byl jeden příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Udělal stanové plachty z kozí srsti pro stan nad příbytkem. Udělal jedenáct takových stanových plachet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Délka jedné stanové plachty byla třicet loket a šířka jedné stanové plachty byla čtyři lokty. Jedenáct stanových plachet mělo stejný rozměr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Spojil pět stanových plachet zvlášť a šest stanových plachet zvlášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Udělal padesát poutek na okraji poslední stanové plachty u jednoho spojeného kusu a udělal padesát poutek na okraji stanové plachty druhého spojeného kusu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Udělal padesát bronzových sponek a spojil stan, takže z toho byl jeden celek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Udělal přikrývku na stan z načerveno zbarvených beraních kůží a nahoru přikrývku z tachaších kůží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Udělal pro příbytek stojaté desky z akáciového dřeva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Deset loket byla délka desky a loket a půl šířka každé desky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Každá deska měla dva čepy, jeden spojený s druhým. Tak to udělal na všech deskách příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Udělal desky pro příbytek: dvacet desek pro jižní stranu na jihu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Také udělal čtyřicet stříbrných podstavců pod těch dvacet desek, dva podstavce pod jednu desku pro oba její čepy a dva podstavce pod druhou desku pro oba její čepy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Pro druhý bok příbytku, na severní stranu, udělal též dvacet desek');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'a čtyřicet stříbrných podstavců k nim, dva podstavce pod jednu desku a dva podstavce pod druhou desku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Pro zadní stranu příbytku na západě udělal šest desek');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'a dvě desky udělal do rohů příbytku na zadní straně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Byly dvojité odzdola a společně končily na vrchu do jednoho kruhu. Tak to udělal s oběma v obou rozích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Tedy bylo osm desek a stříbrné podstavce k nim, šestnáct podstavců, ⌈ po dvou podstavcích⌉ pod každou desku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Udělal závory z akáciového dřeva; pět pro desky na jedné straně příbytku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'pět závor pro desky na druhé straně příbytku a pět závor pro desky na zadní straně příbytku na západě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Udělal prostřední závoru procházející uprostřed desek z jednoho kraje na druhý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Desky potáhl zlatem, k nim udělal zlaté kruhy jako držáky pro závory a závory potáhl zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Udělal oponu z příze modré, purpurové a karmínové a z jemně tkaného plátna; na ní udělal cheruby jako umělecké dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Udělal pro ni čtyři sloupy z akáciového dřeva a potáhl je zlatem, udělal k nim zlaté háky a odlil k nim čtyři stříbrné podstavce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Udělal oponu pro vchod do stanu z příze modré, purpurové a karmínové a z jemně tkaného plátna, jako dílo výšivkáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Pět sloupů pro ni a háky k nim a potáhl jejich hlavice a jejich obruče zlatem. Pět jejich podstavců bylo z bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Besaleel udělal truhlu z akáciového dřeva dva a půl lokte dlouhou, loket a půl širokou a loket a půl vysokou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Potáhl ji čistým zlatem zevnitř i zvnějšku a udělal jí kolem dokola zlatou obrubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Odlil pro ni čtyři zlaté kruhy na její čtyři nohy -- dva kruhy na jeden bok a dva kruhy na druhý bok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Udělal tyče z akáciového dřeva a potáhl je zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Tyče prostrčil do kruhů po bocích truhly, aby se na nich truhla mohla nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Udělal slitovnici z čistého zlata dva a půl lokte dlouhou a loket a půl širokou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Udělal dva zlaté cheruby, udělal je jako tepanou práci na obou koncích slitovnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Jednoho cheruba na jednom konci a druhého cheruba na druhém konci. Na slitovnici udělal cheruby na obou jejich koncích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Cherubové měli křídla roztažená vzhůru; svými křídly zastírali slitovnici; byli obráceni jeden k druhému; tváře cherubů byly upřeny na slitovnici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Udělal stůl z akáciového dřeva dva lokte dlouhý, loket široký a loket a půl vysoký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Potáhl ho čistým zlatem a udělal mu kolem dokola zlatou obrubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Udělal mu rám na dlaň široký kolem dokola a jeho rámu udělal zlatou obrubu kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Odlil pro něj čtyři zlaté kruhy a upevnil kruhy na čtyři rohy, které jsou na čtyřech nohách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Kruhy byly vedle rámu jako místo pro tyče, aby se mohl stůl nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Udělal tyče z akáciového dřeva a potáhl je zlatem, aby se mohl stůl nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Udělal náčiní, které je na stole, mísy, kadidlové pánvičky, obětní misky a konve, s nimiž jsou vylévány lité oběti; udělal je z čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Udělal svícen z čistého zlata; udělal svícen jako tepanou práci. Jeho podstavec a jeho ramena, jeho kalichy, jeho hlavice i jeho květy byly z jednoho kusu s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Šest ramen vycházelo z jeho stran -- tři ramena svícnu z jedné strany a tři ramena svícnu z druhé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Tři kalichy v podobě mandloňového květu byly na jednom rameni -- hlavice a květ -- a tři kalichy v podobě mandloňového květu na druhém rameni -- hlavice a květ. Tak to bylo na šesti ramenech vycházejících ze svícnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Na samotném svícnu byly čtyři kalichy v podobě mandloňového květu -- jeho hlavice a jeho květy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'hlavice byla pod dvěma rameny z něj vycházejícími, další hlavice pod dalšími dvěma rameny z něj vycházejícími a další hlavice byla pod dalšími dvěma rameny z něj vycházejícími, tedy u šesti ramen vycházejících z něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Jejich hlavice a jejich ramena byly z jednoho kusu s ním, všechno jako tepaná práce z jednoho kusu čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Udělal sedm jeho lamp a kleště a pánvičky na uhlíky k němu z čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Udělal ho se vším náčiním k němu z talentu čistého zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Udělal oltář pro kadidlo z akáciového dřeva, loket dlouhý a loket široký -- byl čtvercový, dva lokte vysoký a z jednoho kusu s ním byly jeho rohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Potáhl ho čistým zlatem -- jeho vrch, jeho stěny kolem dokola i jeho rohy -- a udělal mu kolem dokola zlatou obrubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Též dva zlaté kruhy udělal pro něj pod jeho obrubu na obou bocích, na obou jeho stranách jako držáky pro tyče, aby se na nich mohl nosit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Udělal tyče z akáciového dřeva a potáhl je zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Udělal svatý olej pomazání a čisté vonné kadidlo jako to dělají mastičkáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Udělal oltář pro zápalnou oběť z akáciového dřeva, pět loket dlouhý a pět loket široký -- byl čtvercový a tři lokte vysoký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Udělal mu rohy ve čtyřech jeho rozích; jeho rohy byly z jednoho kusu s ním. Potáhl ho bronzem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Udělal všechno náčiní pro oltář -- hrnce, lopaty, misky, vidlice a pánvičky na uhlíky. Všechno náčiní k němu udělal z bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Udělal pro oltář rošt udělaný jako mřížka z bronzu pod jeho okraj zezdola až do jeho poloviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Odlil čtyři kruhy na čtyři konce bronzového roštu jako držáky pro tyče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Udělal tyče z akáciového dřeva a potáhl je bronzem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Tyče prostrčil do kruhů na bocích oltáře, aby se na nich mohl přenášet. Udělal ho dutý z desek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Udělal bronzovou nádrž a její bronzový podstavec ze zrcadel žen, které konaly službu u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Udělal také nádvoří: na straně jižní na jihu -- závěsy nádvoří z jemně tkaného plátna, sto loket,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'dvacet sloupů k nim a dvacet bronzových podstavců k nim; háky na sloupech a obruče k nim ze stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Na straně severní: sto loket, dvacet sloupů k nim a dvacet bronzových podstavců k nim a háky na sloupech a obruče k nim ze stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Na straně západní: závěsy, padesát loket, deset sloupů k nim a deset podstavců k nim a háky na sloupech a obruče k nim ze stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Na straně východní na východě: padesát loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Patnáct loket závěsů na jedné straně, tři sloupy k nim a tři podstavce k nim');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'a na straně druhé -- na jedné i druhé straně brány nádvoří -- patnáct loket závěsů a tři sloupy k nim a tři podstavce k nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Všechny závěsy nádvoří kolem dokola byly z jemně tkaného plátna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Podstavce pro sloupy byly z bronzu, háky na sloupech a obruče k nim ze stříbra, jejich hlavice byly potaženy stříbrem, všechny sloupy nádvoří byly obepnuty stříbrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Opona brány do nádvoří byla jako dílo výšivkáře z příze modré, purpurové a karmínové, z jemně tkaného plátna, dvacet loket dlouhá, pět loket vysoká i široká jako závěsy nádvoří;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'čtyři sloupy k nim a čtyři podstavce k nim byly z bronzu, háky k nim byly ze stříbra, obložení hlavic a obruče k nim byly ze stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Všechny kolíky pro příbytek a pro nádvoří kolem dokola byly z bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Toto je výčet předmětů příbytku, příbytku svědectví, který byl spočítán podle Mojžíšova příkazu jako služba Lévijců pod vedením kněze Ítamara, syna Áronova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Besaleel, syn Urího, syn Chúrův, z pokolení Judova, udělal vše, co přikázal Hospodin Mojžíšovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'a s ním Oholíab, syn Achísamakův, z pokolení Danova, řemeslník, umělec a výšivkář na přízi modré, purpurové a karmínové a na jemném plátně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Všeho zlata použitého pro práci na všem díle svatyně -- totiž zlata mávané oběti -- bylo dvacet devět talentů a sedm set třicet šekelů podle šekelu svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Stříbro od spočítaných z pospolitosti bylo sto talentů a tisíc sedm set sedmdesát pět šekelů podle šekelu svatyně --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, '⌈půl šekelu⌉ na hlavu, polovina šekelu podle šekelu svatyně za každého, kdo přešel ke spočítaným od dvacetiletých výše, totiž šest set tři tisíc pět set padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Sto talentů stříbra bylo na odlití podstavců svatyně a podstavců pro oponu, sto podstavců ze sta talentů, talent na podstavec');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'a tisíc sedm set sedmdesát pět šekelů použil na háky na sloupy, potáhl jejich hlavice a spojil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Bronzu z mávané oběti bylo sedmdesát talentů a dva tisíce čtyři sta šekelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Udělal z něj podstavce ke vchodu do stanu setkávání, bronzový oltář a k němu bronzový rošt a všechno náčiní oltáře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'podstavce pro nádvoří kolem dokola, podstavce brány nádvoří, všechny kolíky příbytku a všechny kolíky nádvoří kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Z příze modré, purpurové a karmínové udělali ⌈jemně tkaná⌉ roucha pro službu ve svatyni. Udělali také svatá roucha pro Árona, ⌈jak přikázal Hospodin Mojžíšovi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Udělal efód ze zlata, z příze modré, purpurové a karmínové a z jemně tkaného plátna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Vytepali zlaté pláty, nastříhali na nitky, aby je zpracovali do příze modré, purpurové a karmínové a do jemného plátna jako umělecké dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Udělali k němu připojené nárameníky; na dvou svých koncích byl spojen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Ozdobný pás jeho efódu, který je na něm, byl udělán jako on z jednoho kusu s ním -- ze zlata, příze modré, purpurové, karmínové a jemně tkaného plátna, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Udělali karneolové kameny a vsadili je do zlatých obrouček; byly na ně vyryty pečetní nápisy se jmény Izraelových synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Vložili je na nárameníky efódu jako připomínkové kameny synů Izraele, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Udělal náprsník jako umělecké dílo; byl udělán jako efód -- ze zlata, z příze modré, purpurové a karmínové a z jemně tkaného plátna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Byl čtvercový a dvojitý; udělali náprsník píď dlouhý a píď široký, dvojitý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Vsadili do něj čtyři řady kamenů; řada rubín, topas a smaragd byla řada první;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'řada druhá -- malachit, safír a jaspis;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'řada třetí -- opál, achát a ametyst');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'a řada čtvrtá -- chryzolit, karneol a onyx. Byly vsazeny do zlatých obrouček ve svých obroučkách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Kamenů bylo podle jmen Izraelových synů dvanáct, podle jejich jmen; jako pečetní nápis byl každý podle svého jména pro dvanáct kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Udělali k náprsníku řetízky z čistého zlata spletené jako se vytvářejí provázky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Udělali dvě zlaté obroučky a dva zlaté kroužky a upevnili ty dva kroužky na oba okraje náprsníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Dva zlaté provázky upevnili ke dvěma kroužkům na okrajích náprsníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Druhé dva konce obou provázků upevnili ke dvěma obroučkám a dali je dopředu na nárameníky efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Udělali dva zlaté kroužky a umístili je na dva okraje náprsníku, na vnitřní okraj, který byl na straně efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Udělali dva zlaté kroužky a upevnili je na dva nárameníky efódu zepředu zezdola u spojeného kusu nad ozdobný pás efódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Náprsník přivázali modrou šňůrkou z jeho kroužků na kroužky efódu, aby byl nad ozdobným pásem efódu. Náprsník neodstával od efódu, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Udělali plášť efódu jako dílo tkalce, celý z modré příze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Plášť měl uprostřed otvor jako okraj koženého pancíře; kolem dokola byl na otvoru lem, aby se nemohl roztrhnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Na lemu pláště udělal granátová jablka z příze modré, purpurové a karmínové, tkaná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Udělali zvonečky z čistého zlata a zvonečky upevnili mezi granátová jablka na lem pláště kolem dokola, mezi granátová jablka:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'zvoneček a granátové jablko, zvoneček a granátové jablko kolem dokola na lem pláště pro službu, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Udělali suknice z jemného plátna jako dílo tkalce pro Árona a pro jeho syny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'turban z jemného plátna, ozdobné klobouky z jemného plátna, lněné spodky z jemně tkaného plátna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'šerpu z jemně tkaného plátna, příze modré, purpurové a karmínové, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Udělali květ z čistého zlata, svatou čelenku, a napsali na něj zápis, pečetní nápis: Svatý Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Dali na něj modrou šňůrku, aby jej upevnili nahoru na turban, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Tak byla dokončena všechna práce na příbytku stanu setkávání. Synové Izraele udělali všechno tak, jak přikázal Hospodin Mojžíšovi; tak to udělali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Potom přinesli příbytek Mojžíšovi, stan i všechno jeho náčiní: jeho sponky, jeho desky, jeho závory, jeho sloupy a jeho podstavce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'přikrývku z beraních kůží načerveno zbarvenou, přikrývku z kůží tachaších a zakrývající oponu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'truhlu svědectví, její tyče a slitovnici,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'stůl se vším jeho náčiním, předkladný chléb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'čistý svícen, jeho lampy, lampy v patřičném pořádku, a všechno jeho náčiní a olej ke svícení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'zlatý oltář, olej pomazání a vonné kadidlo, oponu pro vchod do stanu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'bronzový oltář, k němu bronzový rošt, jeho tyče a všechno jeho náčiní, nádrž a její podstavec,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'závěsy nádvoří, jeho sloupy, jeho podstavce, oponu pro bránu do nádvoří, jeho lana, jeho kolíky a všechna náčiní pro službu příbytku stanu setkávání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'jemně tkaná roucha pro službu ve svatyni, svatá roucha pro kněze Árona a roucha pro jeho syny, aby sloužili jako kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Tak, jak přikázal Hospodin Mojžíšovi, tak udělali synové Izraele všechnu práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Mojžíš si prohlédl všechnu práci a hle, udělali ji tak, jak Hospodin přikázal; tak ji udělali; a Mojžíš jim požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'V den prvního měsíce, prvního dne toho měsíce, postavíš příbytek stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Postavíš tam truhlu svědectví a zahalíš truhlu oponou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Vneseš stůl a narovnáš, ⌈jak to má být.⌉ Vneseš svícen a nasadíš jeho lampy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Dáš zlatý oltář pro kadidlo před truhlu svědectví a umístíš oponu vchodu do příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Dáš oltář pro zápalnou oběť před vchod do příbytku stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Dáš nádrž mezi stan setkávání a oltář a dáš do ní vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Postavíš nádvoří kolem dokola a upevníš oponu brány do nádvoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Vezmeš olej pomazání a pomažeš příbytek a všechno, co je v něm; posvětíš ho a všechno jeho náčiní a bude svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Pomažeš oltář pro zápalnou oběť a všechno jeho náčiní; posvětíš oltář a oltář bude nejsvětější.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Pomažeš nádrž s jejím podstavcem a posvětíš ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Přivedeš Árona a jeho syny ke vchodu do stanu setkávání a umyješ je vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Oblékneš Áronovi svatá roucha, pomažeš ho a posvětíš ho, aby mi sloužil jako kněz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Přivedeš i jeho syny, oblékneš jim suknice');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'a pomažeš je, jako jsi pomazal jejich otce, aby mi sloužili jako kněží. Toto jejich pomazání bude pro věčné kněžství jim a všem jejich pokolením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Mojžíš udělal všechno tak, jak mu přikázal Hospodin; tak to udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'I stalo se, že prvního měsíce ve druhém roce, prvního dne toho měsíce byl příbytek postaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Mojžíš postavil příbytek, položil jeho podstavce, umístil jeho desky, vložil jeho závory a postavil jeho sloupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Rozprostřel na příbytek stan a položil na něj nahoru přikrývku stanu, jak Hospodin přikázal Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Vzal svědectví a dal je do truhly, položil tyče na truhlu a dal slitovnici nahoru na truhlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Vnesl truhlu do příbytku a umístil zakrývající oponu, aby zastírala truhlu svědectví, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Dal stůl do stanu setkávání na severní stranu příbytku ven před oponu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'a narovnal na něj před Hospodinem chléb, jak to má být, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Umístil svícen do stanu setkávání naproti stolu na jižní stranu příbytku');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'a nasadil před Hospodinem lampy, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Umístil zlatý oltář do stanu setkávání před oponu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'a obětoval na něm vonné kadidlo, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Umístil oponu vchodu do příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Oltář pro zápalnou oběť umístil ke vchodu do příbytku stanu setkávání a obětoval na něm oběť zápalnou a přídavnou, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Umístil nádrž mezi stan setkávání a oltář a dal do ní vodu na umývání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Mojžíš, Áron a jeho synové si v ní umývali ruce a nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Když vcházeli do stanu setkávání a když se přibližovali k oltáři, umývali se, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Postavil nádvoří kolem příbytku a oltáře a upevnil oponu brány do nádvoří. Tak Mojžíš dokončil práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Oblak zakryl stan setkávání a Hospodinova sláva naplnila příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Mojžíš nemohl vejít do stanu setkávání, neboť na něm spočíval oblak a Hospodinova sláva naplnila příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Když se zvedl oblak z příbytku, synové Izraele vyráželi ke všem svým denním pochodům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'A když se oblak nezvedl, nevyrazili, dokud se nezvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Neboť Hospodinův oblak byl nad příbytkem ve dne a oheň byl na něm v noci před očima celého domu Izraele po všechny jejich denní pochody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Tu zavolal Hospodin na Mojžíše a promluvil k němu ze stanu setkávání takto:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Promluv k synům Izraele a řekni jim: Když chce někdo z vás přinést ⌈obětní dar⌉ Hospodinu, přinesete svůj obětní dar z dobytka, ze skotu nebo z bravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Bude –li jeho obětním darem zápalná oběť ze skotu, přivede samce bez vady. Přivede jej ke vchodu do stanu setkávání, aby nalezl zalíbení před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Položí ruku na hlavu zápalné oběti; ta bude za něj laskavě přijata a získá pro něj smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Pak zabije tele před Hospodinem a ⌈synové Áronovi, kněží,⌉ přinesou krev a krví ze všech stran pokropí oltář, který je u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Stáhne zápalnou oběť a rozseká ji na díly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Synové kněze Árona dají oheň na oltář a narovnají dříví na oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Synové Áronovi, kněží, narovnají díly, hlavu a lůj na dříví, které je na ohni na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Vnitřnosti a hnáty však umyje vodou a kněz to všechno bude obětovat na oltáři. To je zápalná oběť, ohnivá oběť, příjemná vůně Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Bude –li jeho obětní dar z bravu, z ovcí či koz, přivede jako zápalnou oběť samce bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Zabije ho před Hospodinem na severní straně oltáře a synové Áronovi, kněží, pokropí jeho krví oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Rozseká ho na díly. S jeho hlavou a lojem je kněz narovná na dříví, které je na ohni na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Vnitřnosti a hnáty umyje vodou a kněz to všechno přinese a bude obětovat na oltáři. To je zápalná oběť, ohnivá oběť, příjemná vůně Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Bude –li jeho obětním darem Hospodinu zápalná oběť z ptactva, přinese svůj obětní dar z hrdliček či z holoubat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Kněz ho přinese k oltáři, nehtem mu natrhne hlavu a bude obětovat na oltáři. Jeho krev nechá vykapat na stěnu oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Odstraní vole s vývržkem a odhodí to východně vedle oltáře, tam, kde je popel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Roztrhne ho za křídla, ale nerozdělí ho. Kněz ho bude obětovat na oltáři na dříví, které je na ohni. To je zápalná oběť, ohnivá oběť, příjemná vůně Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Když někdo chce přinést Hospodinu jako obětní dar přídavnou oběť, jeho obětním darem bude jemná mouka. Vyleje na ni olej a dá na ni kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Přinese ji synům Áronovým, kněžím. Kněz z toho vezme plnou hrst jemné mouky a oleje se vším kadidlem a bude to obětovat na oltáři jako pamětní dar, ohnivou oběť, příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'To, co z přídavné oběti zbude, patří Áronovi a jeho synům jako nejsvětější věc z ⌈Hospodinových ohnivých obětí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Když přineseš jako obětní dar přídavnou oběť z něčeho upečeného v peci, bude to z jemné mouky: bochníky nekvašených chlebů namísené s olejem či placky nekvašených chlebů pomazané olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Bude –li tvým obětním darem přídavná oběť pečená na ploché pánvi, bude z jemné mouky namísená s olejem, nekvašená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Rozdrobíš ji na kousky a vyleješ na ni olej. To je přídavná oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Bude –li tvým obětním darem přídavná oběť připravená v pánvi s víkem, připraví se z jemné mouky s olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Potom přídavnou oběť, která byla připravena z těchto věcí, přineseš Hospodinu. Přineseš ji knězi a on ji předloží na oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Kněz odebere z přídavné oběti pamětní dar a bude ji obětovat na oltáři jako ohnivou oběť, příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'To, co z přídavné oběti zbude, patří Áronovi a jeho synům jako nejsvětější věc z Hospodinových ohnivých obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Žádná přídavná oběť, kterou přinesete Hospodinu, nebude připravena z kvašeného; neboť nic z kvasu ani nic z medu nebudete obětovat jako ohnivou oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Můžete je přinést Hospodinu jako obětní dar z prvotin, ale nepřijdou na oltář jako příjemná vůně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Každý obětní dar své přídavné oběti osolíš solí. Nenecháš svou přídavnou oběť bez soli smlouvy svého Boha. S každým svým obětním darem přineseš sůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Přineseš–li Hospodinu přídavnou oběť z prvotin, přineseš jako přídavnou oběť ze svých prvotin klasy pražené na ohni a drcené zrní z čerstvého obilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Dáš na ni olej a položíš na ni kadidlo. To je přídavná oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Kněz z ní bude obětovat pamětní dar -- část z jejího drceného zrní a z jejího oleje se vším kadidlem -- jako ohnivou oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Bude –li jeho obětním darem obětní hod pokojné oběti, jestliže chce přinést ze skotu samce či samici, přinese před Hospodina zvíře bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Položí ruku na hlavu svého obětního daru a zabije ho u vchodu do stanu setkávání. Synové Áronovi, kněží, pokropí krví oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Z obětního hodu pokojné oběti přinese jako ohnivou oběť Hospodinu tuk pokrývající vnitřnosti a všechen tuk, který je na vnitřnostech;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'obě ledviny a tuk, který je na nich a na slabinách, a jaterní lalok, který odstraní s ledvinami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Synové Áronovi to budou obětovat na oltáři se zápalnou obětí, která je na dříví na ohni, jako ohnivou oběť, příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Bude –li jeho obětní dar pro obětní hod pokojné oběti pro Hospodina z bravu, přinese samce či samici bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Přináší–li jako svůj obětní dar jehně, přinese ho před Hospodina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'na hlavu svého obětního daru položí ruku a zabije ho před stanem setkávání. Synové Áronovi pokropí krví oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Z obětního hodu pokojné oběti přinese jako ohnivou oběť Hospodinu jeho tuk: celý tučný ocas, který odstraní u kostrče, tuk pokrývající vnitřnosti a všechen tuk, který je na vnitřnostech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'obě ledviny a tuk, který je na nich a na slabinách, a jaterní lalok, který odstraní s ledvinami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Kněz to bude obětovat na oltáři jako pokrm ohnivé oběti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Bude –li jeho obětním darem koza, přivede ji před Hospodina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'položí ruku na její hlavu a zabije ji před stanem setkávání. Synové Áronovi pokropí její krví oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Z ní přinese svůj obětní dar jako ohnivou oběť Hospodinu: tuk pokrývající vnitřnosti a všechen tuk, který je na vnitřnostech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'obě ledviny a tuk, který je na nich a na slabinách, a jaterní lalok, který odstraní s ledvinami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Kněz je bude obětovat na oltáři jako pokrm ohnivé oběti, příjemnou vůni. Všechen tuk patří Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'To je ⌈věčné ustanovení⌉ pro vaše generace ve všech vašich sídlech: nebudete jíst žádný tuk a žádnou krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, '⌈Hospodin promluvil k Mojžíšovi:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Promluv k synům Izraele: Když někdo nedopatřením zhřeší proti jakémukoliv Hospodinovu příkazu o věcech, které se ne smí dělat, a přestoupí jediný z nich:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Zhřeší–li pomazaný kněz, ⌈takže padne vina na lid,⌉ za svůj hřích, kterým zhřešil, přivede Hospodinu jako oběť za hřích býčka bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Přivede býčka před Hospodina ke vchodu do stanu setkávání, položí ruku na hlavu býčka a zabije býčka před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Pomazaný kněz vezme trochu krve z býčka a přinese ji do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Potom kněz namočí prst do krve a sedmkrát stříkne před Hospodinem trochu krve na oponu svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Kněz dá před Hospodinem trochu krve na rohy oltáře pro vonné kadidlo, který je ve stanu setkávání, a všechnu ostatní krev z býčka vyleje ke spodku oltáře pro zápalnou oběť, který je u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Vybere z býčka oběti za hřích všechen jeho tuk -- tuk pokrývající vnitřnosti a všechen tuk, který je na vnitřnostech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'obě ledviny a tuk, který je na nich a na slabinách, a jaterní lalok, který odstraní s ledvinami --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'tak jako se vybírá z býka obětního hodu pokojné oběti -- a kněz to bude obětovat na oltáři pro zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Kůži z býčka a všechno jeho maso s hlavou, hnáty, vnitřnostmi a výměty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'celý zbytek býčka vynese ven za tábor na čisté místo, kam se vysypává popel, a spálí ho ohněm na dříví; spálí ho tam, kde se vysypává popel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Pobloudí–li ⌈celá pospolitost Izraele⌉ a ta věc bude skrytá před zraky shromáždění, přestoupí– li jediný ze všech Hospodinových příkazů, který se ne smí přestoupit, a proviní se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'potom však bude odhalen hřích, kterým zhřešili, přivede shromáždění býčka jako oběť za hřích; přivedou ho před stan setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Starší pospolitosti položí před Hospodinem ruce na hlavu býčka a někdo býčka před Hospodinem zabije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Pomazaný kněz přinese trochu krve z býčka do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Potom kněz namočí prst do krve a sedmkrát stříkne před Hospodinem na oponu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Trochu krve dá na rohy oltáře, který je před Hospodinem ve stanu setkávání, a všechnu ostatní krev vyleje ke spodku oltáře pro zápalnou oběť, který je u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Všechen jeho tuk z něj vybere a obětuje na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Naloží s býčkem jako naložil s býčkem oběti za hřích; tak s ním naloží. Kněz za ně vykoná obřad smíření a bude jim odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Vynese býčka ven za tábor a spálí ho jako spálil toho předchozího býčka. To je oběť za hřích shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Když zhřeší předák a nedopatřením přestoupí jediný ze všech příkazů Hospodina, svého Boha, který se ne smí přestoupit a tak se proviní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'anebo když mu bude oznámen jeho hřích, kterým zhřešil, přivede jako svůj obětní dar kozla, samce bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Položí ruku na hlavu kozla a zabije ho tam, kde se zabíjejí zápalné oběti před Hospodinem. To je oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Kněz vezme trochu krve z oběti za hřích na prst, dá na rohy oltáře pro zápalnou oběť a ostatní krev vyleje ke spodku oltáře pro zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Všechen tuk obětuje na oltáři jako tuk obětního hodu pokojné oběti. Kněz za něj vykoná obřad smíření za jeho hřích a bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Jestliže někdo z lidu země nedopatřením zhřeší tím, že přestoupí jediný z Hospodinových příkazů, který se ne smí přestoupit, a tak se proviní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'anebo když mu bude oznámen jeho hřích, kterým zhřešil, přivede jako svůj obětní dar kozu, samici bez vady, za svůj hřích, kterým zhřešil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Položí ruku na hlavu oběti za hřích a tu oběť za hřích zabije tam, kde se zabíjejí zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Kněz vezme trochu její krve na prst, dá na rohy oltáře pro zápalnou oběť a všechnu ostatní krev vyleje ke spodku oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Všechen její tuk vyjme, tak jako se vyjímá tuk z obětního hodu pokojné oběti. Kněz ji pak bude obětovat na oltáři jako příjemnou vůni Hospodinu. Tak za něj kněz vykoná obřad smíření a bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Jestliže přinese na svůj obětní dar beránka jako oběť za hřích, přinese samici bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Položí ruku na hlavu oběti za hřích a zabije ji jako oběť za hřích tam, kde se zabíjejí zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Kněz vezme trochu krve z oběti za hřích na prst, dá ji na rohy oltáře pro zápalnou oběť a všechnu ostatní krev vyleje ke spodku oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Všechen její tuk vyjme, tak jako se vyjímá tuk z ovce obětního hodu pokojné oběti. Kněz ji pak bude obětovat na oltáři s Hospodinovými ohnivými oběťmi. Tak kněz vykoná obřad smíření za něj, za jeho hřích, kterým zhřešil, a bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Jestliže někdo zhřeší tím, že slyší kletbu, je svědkem, viděl to či se to dozvěděl a neoznámí to, ponese vinu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'nebo když se někdo dotkne čehokoli nečistého, ať zdechliny nečisté zvěře či zdechliny nečistého dobytka či zdechliny nečistého hmyzu, ačkoliv mu to bylo skryto, nese vinu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'nebo když se někdo dotkne lidské nečistoty, jakékoliv nečistoty, kterou se může znečistit, ačkoliv mu to bylo skryto, ale potom se to dozví, nese vinu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'nebo když někdo přísahá a nerozvážně vysloví svými rty, že udělá něco zlého či dobrého, cokoliv, co může člověk s přísahou nerozvážně vyslovit, ačkoliv mu to bylo skryto, ale potom se to dozví, nese vinu v jediné z těchto věcí --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'i stane se, když se proviní v jediné z těchto věcí, musí vyznat to, v čem zhřešil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'a za svůj hřích, kterým zhřešil, přinese Hospodinu svou oběť za vinu, samici z bravu, ovci nebo kozu jako oběť za hřích a kněz za něj vykoná obřad smíření za jeho hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Jestliže jeho ⌈prostředky nestačí⌉ na ovci, přinese Hospodinu jako oběť za vinu, kterou se prohřešil, dvě hrdličky nebo dvě holoubata, jedno jako oběť za hřích a druhé jako zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Přinese je knězi a ten přinese jako první to, které je k oběti za hřích. Nehtem mu natrhne hlavu od šíje, ale neoddělí ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Trochu krve z oběti za hřích stříkne na stěnu oltáře a zbytek krve nechá vykapat ke spodku oltáře. To je oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Druhé připraví jako zápalnou oběť podle nařízení. Kněz za něj vykoná obřad smíření za jeho hřích, kterým zhřešil, a bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Jestliže jeho prostředky nestačí na dvě hrdličky nebo dvě holoubata, přinese jako svůj obětní dar za hřích, kterým zhřešil, jako oběť za hřích, desetinu éfy jemné mouky. Nevyleje na ni olej ani na ni nedá kadidlo, neboť je to oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Přinese ji knězi a kněz z toho vezme plnou hrst jako pamětní dar a bude to obětovat na oltáři s Hospodinovými ohnivými oběťmi. To je oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Kněz za něj vykoná obřad smíření za jeho hřích, kterým zhřešil proti některé z těchto věcí, a bude mu odpuštěno. Zbytek bude patřit knězi jako přídavná oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Když se někdo zpronevěří věrolomností a zhřeší nedopatřením proti Hospodinovým svatým věcem, přinese Hospodinu jako svou oběť za vinu z bravu berana bez vady podle tvého výměru v šekelech stříbra podle šekelu svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'To, čím se prohřešil vůči svatým věcem, nahradí, přidá k tomu pětinu a dá to knězi. Kněz za něj vykoná obřad smíření s beranem jako obětí za vinu a bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Jestliže někdo zhřeší a přestoupí jakýkoliv z Hospodinových příkazů o věcech, které se ne smí dělat, ačkoliv o tom nevěděl, provinil se a ponese svou vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Přinese knězi z bravu berana bez vady podle tvého výměru jako oběť za vinu. Kněz za něj vykoná obřad smíření za jeho nedopatření, kterým pobloudil, ačkoliv o tom nevěděl, a bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'To je oběť za vinu; vskutku se provinil proti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, 'Když někdo zhřeší a zpronevěří se proti Hospodinu věrolomností, takže svému druhovi zapře něco, co má uložené nebo svěřené do zástavy nebo lup či to, co získal vydíráním svého druha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'nebo nalezne ztracenou věc a zapře ji, anebo křivě přísahá o jakékoliv z těchto věcí, které může člověk spáchat a zhřešit proti nim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'i stane se potom, když zhřešil a nese vinu, že vrátí ⌈lup, který uchvátil, anebo to, co získal vydíráním, kterého se dopustil, nebo to, co má uložené, jež mu bylo svěřeno,⌉ anebo ztracenou věc, kterou nalezl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'nebo cokoliv, o čem lživě přísahal; nahradí to doposledka, přidá k tomu svou pětinu a dá to tomu, komu to patří, v den ⌈své oběti za vinu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'A Hospodinu přinese svou oběť za vinu: z bravu berana bez vady podle tvého výměru ke knězi jako oběť za vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'Kněz za něj vykoná obřad smíření před Hospodinem a bude mu odpuštěno cokoliv, co spáchal a čím se provinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Přikaž Áronovi a jeho synům: Toto je zákon o zápalné oběti: Zápalná oběť bude na ohništi na oltáři po celou noc až do rána a oltářní oheň na něm bude stále hořet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Kněz si obleče svůj lněný oděv, na tělo si obleče lněné spodky a vybere popel, na který oheň strávil zápalnou oběť na oltáři, a položí ho vedle oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Potom si svlékne své roucho, oblékne si jiné roucho a vynese popel ven za tábor na čisté místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Oheň na oltáři bude stále hořet, neuhasne. Kněz na něm ráno co ráno zapálí dříví, připraví na něm zápalnou oběť a bude na něm obětovat tuk pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Oheň na oltáři bude hořet ustavičně, neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'A toto je zákon o přídavné oběti: Synové Áronovi ji budou přinášet před Hospodina před oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Kněz z toho odebere hrst jemné mouky přídavné oběti, trochu jejího oleje a všechno kadidlo, které je na přídavné oběti, a bude to obětovat na oltáři jako příjemnou vůni, jako pamětní dar Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'To, co z ní zbude, budou jíst Áron a jeho synové. Bude se to jíst jako nekvašené chleby na svatém místě; budou to jíst na nádvořích stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Nebude se to péct kvašené. Dal jsem jim to jako jejich podíl ze svých ohnivých obětí. Je to nejsvětější věc stejně jako oběť za hřích a oběť za vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Bude ji jíst každý mužského pohlaví mezi syny Áronovými. To je věčné ustanovení pro vaše generace o ohnivých obětech Hospodinových. Cokoliv se jich dotkne, bude svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Toto je obětní dar Árona a jeho synů, který budou přinášet Hospodinu v den svého pomazání: desetinu éfy jemné mouky jako ustavičnou přídavnou oběť, polovinu ráno a polovinu večer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Připraví se na ploché pánvi s olejem, smažená. Přídavnou oběť přineseš nadrobenou na kousky; přineseš ji jako příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Připraví ji kněz pomazaný namísto něj z jeho synů. To je věčné ustanovení -- jako celopal to bude obětováno Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Každá přídavná oběť kněze bude celopalem; nebude se jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Promluv k Áronovi a k jeho synům: Toto je zákon o oběti za hřích: Na místě, kde se zabíjí zápalná oběť, se bude před Hospodinem zabíjet oběť za hřích. Je to nejsvětější věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Sní ji kněz, který ji obětuje jako oběť za hřích. Sní se na svatém místě, na nádvoří stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Cokoliv se dotkne jejího masa, bude svaté, a když by stříklo trochu její krve na roucho, to, na co stříkne, vypereš na svatém místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Hliněná nádoba, ve které se to vařilo, se rozbije, a jestliže se to vařilo v nádobě měděné, vydrhne se a opláchne vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Bude ji jíst každý mužského pohlaví mezi kněžími; je to nejsvětější věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Avšak žádná oběť za hřích, z jejíž krve je přineseno do stanu setkávání k vykonání obřadu smíření ve svatyni, se nebude jíst; spálí se ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Toto je zákon o oběti za vinu. Je to nejsvětější věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Na místě, kde se zabíjejí zápalné oběti, se budou zabíjet oběti za vinu. Jejich krví se pokropí oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Přinese všechen její tuk: tučný ocas, tuk pokrývající vnitřnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'obě ledviny a tuk, který je na nich a na slabinách, a jaterní lalok, který odstraní s ledvinami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Kněz to bude obětovat na oltáři jako ohnivou oběť Hospodinu. To je oběť za vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Bude ji jíst každý mužského pohlaví mezi kněžími. Bude se jíst na svatém místě; je to nejsvětější věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Pro oběť za hřích i pro oběť za vinu je jeden zákon: Bude patřit knězi, který s ní vykoná obřad smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Knězi, který přináší něčí zápalnou oběť, jemu bude patřit kůže zápalné oběti, kterou přinesl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Každá přídavná oběť, která se peče v peci, vše, co se připravuje na ploché pánvi s víkem a na pánvi, bude patřit knězi, který ji přináší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Každá přídavná oběť namísená s olejem i suchá bude patřit všem synům Áronovým, jednomu jako druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Toto je zákon o obětním hodu pokojné oběti, který se přináší Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Jestliže ho přináší jako oběť díků, přinese ⌈spolu s⌉ obětí díků bochníky nekvašených chlebů namísené s olejem a placky nekvašených chlebů pomazané olejem a jemnou mouku smaženou jako bochníky namísené s olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Vedle bochníků přinese jako svůj obětní dar kvašený chléb, spolu s obětí díků své pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Přinese z něj vždy jeden z každého obětního daru jako dar pozdvihování Hospodinu. Bude to patřit knězi, který kropil krví pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Maso oběti díků jeho pokojné oběti se sní v den jeho obětního daru; neponechá se z něj nic do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Jestliže je jeho obětním darem slíbená nebo dobrovolná oběť, sní se v den, kdy přinese svou oběť, a to, co z ní zbude, se sní druhého dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'To, co z masa obětního hodu zbude do třetího dne, se spálí ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Jestliže by přece někdo jedl z masa obětního hodu jeho pokojné oběti třetího dne, ten, kdo ji přinesl, nenalezne zalíbení, nepřičte se mu k dobru, bude to znehodnocené a ten, kdo by z ní jedl, ponese svou vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Maso, které se dotklo čehokoliv nečistého, se nebude jíst, spálí se ohněm. Co se týče masa, každý, kdo je čistý, smí jíst maso.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Člověk, který by jedl maso z obětního hodu pokojné oběti patřící Hospodinu, a jeho nečistota byla na něm, takový člověk ať je vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Když by se člověk dotkl čehokoliv nečistého, lidské nečistoty nebo nečistého zvířete či čehokoliv nečistého hodného opovržení, a jedl by z masa obětního hodu pokojné oběti patřící Hospodinu, takový člověk ať je vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Promluv k synům Izraele: Nebudete jíst žádný tuk z býka, ovce či kozla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Tuk mršiny a rozsápaného zvířete ať se použije pro jakoukoliv potřebu, jíst ho však jistě nebudete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Neboť každý, kdo by jedl tuk ze zvířete, z něhož se přináší ohnivá oběť Hospodinu, člověk, který by jej jedl, ať je vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'V žádném ze svých sídel nebudete jíst žádnou krev, z ptáka ani z dobytka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Každý člověk, který by jedl jakoukoliv krev, takový člověk ať je vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Promluv k synům Izraele: Ten, kdo přináší Hospodinu obětní hod své pokojné oběti, přinese Hospodinu obětní dar z obětního hodu své pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Jeho ruce přinesou Hospodinovy ohnivé oběti. Tuk přinese s hrudím; hrudí, aby se s ním mávalo jako mávanou obětí před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Kněz bude obětovat tuk na oltáři a hrudí bude patřit Áronovi a jeho synům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Pravou kýtu dáte knězi jako dar pozdvihování ze svých obětních hodů pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Tomu ze synů Áronových, kdo přináší krev pokojné oběti a tuk, tomu bude patřit jako podíl pravá kýta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Neboť hrudí z mávané oběti a kýtu z daru pozdvihování jsem vzal synům Izraele z jejich obětních hodů pokojné oběti a dal jsem je knězi Áronovi a jeho synům jako věčný příděl od synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'To je ⌈posvěcená část ⌉ Árona a posvěcená část jeho synů z Hospodinových ohnivých obětí ode dne, kdy je nechal přistupovat, aby sloužili Hospodinu jako kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'To Hospodin přikázal, aby se jim dávalo, ode dne, kdy je pomazal, jako věčný příděl od synů Izraele pro jejich pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Toto je zákon o zápalné oběti, o přídavné oběti, o oběti za hřích, o oběti za vinu, o oběti zasvěcování a o obětním hodu pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'To Hospodin přikázal Mojžíšovi na hoře Sínaj v den, kdy na Sínajské pustině přikázal synům Izraele přinášet jejich obětní dar Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Vezmi Árona a s ním jeho syny i roucha, olej pomazání, býčka pro oběť za hřích, dva berany a koš nekvašených chlebů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'a svolej celou pospolitost ke vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mojžíš učinil, jak mu Hospodin přikázal, a pospolitost se shromáždila ke vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Mojžíš řekl pospolitosti: Toto je to, co Hospodin přikázal udělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Nato Mojžíš přivedl Árona a jeho syny a umyl je vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Dal na něj suknici, přepásal ho šerpou, oblékl mu plášť, dal na něj efód, přepásal ho ozdobným pásem efódu a zavázal ho s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Položil na něj náprsník a dal do náprsníku urím a tumím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Na hlavu mu položil turban a dopředu na turban vložil zlatý květ, svatou čelenku, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Pak vzal Mojžíš olej pomazání a pomazal příbytek a vše, co v něm bylo; posvětil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Sedmkrát jím stříkl na oltář a pomazal oltář i všechno jeho náčiní, nádrž i její podstavec, aby je posvětil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Áronovi na hlavu vylil trochu oleje pomazání a pomazal ho, aby ho posvětil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Nato Mojžíš přivedl Áronovy syny, oblékl jim suknice, přepásal je šerpou a přivázal jim klobouky, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Potom přivedl býčka pro oběť za hřích a Áron se svými syny položil ruce na hlavu býčka pro oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Když ho zabil, vzal Mojžíš krev a dal ji prstem na rohy oltáře kolem dokola a tak očistil oltář od hříchu. Krev vylil ke spodku oltáře. Tak ho posvětil, když za něj vykonal obřad smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Když vzal všechen tuk, který byl na vnitřnostech, jaterní lalok, obě ledviny a tuk na nich, obětoval to Mojžíš na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Avšak býčka -- jeho kůži, jeho maso a jeho výměty -- spálil ohněm venku za táborem, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Potom přivedl berana pro zápalnou oběť a Áron se svými syny položil ruce na hlavu berana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Když ho zabil, Mojžíš pokropil krví oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Berana rozsekal na díly a Mojžíš obětoval hlavu, díly a lůj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Vnitřnosti a hnáty umyl vodou a Mojžíš obětoval celého berana na oltáři. To byla zápalná oběť pro příjemnou vůni, to byla ohnivá oběť Hospodinu, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Pak přivedl druhého berana, berana zasvěcení, a Áron se svými syny položil ruce na hlavu berana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Když ho zabil, vzal Mojžíš trochu jeho krve a dal ji na lalůček Áronova pravého ucha, na palec jeho pravé ruky a na palec jeho pravé nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Nato přivedl Áronovy syny a Mojžíš dal trochu krve na lalůček jejich pravého ucha, na palec jejich pravé ruky a na palec jejich pravé nohy. Potom Mojžíš pokropil krví oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Vzal tuk, tučný ocas, všechen tuk, který je na vnitřnostech, jaterní lalok, obě ledviny a jejich tuk a pravou kýtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Z koše s nekvašenými chleby, který byl před Hospodinem, vzal jeden nekvašený bochník, jeden bochník chleba s olejem a jednu placku a položil to na tučné části a na pravou kýtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'To všechno dal do rukou Árona a do rukou jeho synů a zamával tím před Hospodinem jako mávanou obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Potom to Mojžíš vzal z jejich rukou a obětoval na oltáři se zápalnou obětí. To jsou oběti zasvěcování pro příjemnou vůni, to je ohnivá oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Mojžíš vzal hrudí a zamával jím před Hospodinem jako mávanou obětí. To byl díl z berana zasvěcení pro Mojžíše, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Mojžíš vzal trochu oleje pomazání a trochu krve, která byla na oltáři, a stříkl na Árona a jeho roucha a na jeho syny a roucha jeho synů s ním. Tak posvětil Árona a jeho roucha a s ním jeho syny a roucha jeho synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Mojžíš řekl Áronovi a jeho synům: U vchodu do stanu setkávání uvařte maso a snězte ho tam s chlebem, který je v koši zasvěcení, jak jsem přikázal: Snědí ho Áron a jeho synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'To, co z masa a chleba zbude, spálíte ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Ze vchodu do stanu setkávání neodejdete po sedm dní, až do dne, kdy se naplní dny vašeho zasvěcování, neboť za sedm dní budete zasvěceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Jak ⌈se stalo⌉ dnes, tak Hospodin přikázal jednat, abyste pro sebe získali smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'U vchodu do stanu setkávání zůstanete ve dne v noci po sedm dní a budete ⌈konat Hospodinovu službu,⌉ abyste nezemřeli, neboť tak mi bylo přikázáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'A Áron se svými syny učinil všechno, co Hospodin přikázal prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'I stalo se osmého dne, že Mojžíš zavolal Árona, jeho syny a izraelské starší');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'a řekl Áronovi: Vezmi si tele k oběti za hřích a berana k zápalné oběti, oboje bez vady, a přines je před Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Synům Izraele řekni: Vezměte si kozla k oběti za hřích, tele a beránka, oba roční, bez vady, k zápalné oběti');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'i býka a berana k pokojné oběti, abyste je obětovali před Hospodinem, a také přídavnou oběť namísenou s olejem, neboť dnes se vám ukáže Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Vzali tedy to, co přikázal Mojžíš, před stan setkávání, celá pospolitost předstoupila a postavili se před Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Mojžíš řekl: Toto je to, co přikázal Hospodin, abyste učinili a ukázala se vám Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Mojžíš řekl Áronovi: Přistup k oltáři a obětuj svou oběť za hřích i svou zápalnou oběť a vykonej obřad smíření za sebe i za lid; obětuj obětní dar lidu a vykonej za ně obřad smíření, jak přikázal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Áron přistoupil k oltáři a zabil své tele k oběti za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Áronovi synové mu přinesli krev, on namočil prst do krve, dal na rohy oltáře a krev vylil ke spodku oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Tuk, ledviny a jaterní lalok z oběti za hřích obětoval na oltáři, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Maso a kůži spálil ohněm venku za táborem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Potom zabil zápalnou oběť, Áronovi synové mu podali krev a on s ní pokropil oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Podali mu též zápalnou oběť rozsekanou na díly a hlavu a on to obětoval na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Vnitřnosti a hnáty umyl a obětoval na oltáři se zápalnou obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Přinesl též obětní dar lidu. Vzal kozla lidu k oběti za hřích, zabil ho a obětoval ho na očištění od hříchu jako předchozí oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Přinesl i zápalnou oběť a obětoval ji podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Přinesl přídavnou oběť, ⌈vzal z ní plnou hrst⌉ a obětoval na oltáři, kromě ranní zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Zabil býka a berana obětního hodu pokojné oběti za lid. Áronovi synové mu podali krev a on s ní pokropil oltář ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Tučné části z býka a berana -- tučný ocas, ⌈to, co přikrývá vnitřnosti,⌉ ledviny a jaterní lalok');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, '-- tyto tučné části položili na hrudí a Áron obětoval tučné části na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Hrudím a pravou kýtou zamával před Hospodinem jako mávanou obětí, jak přikázal Mojžíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Áron pozvedl ruce k lidu, požehnal jim a po obětování oběti za hřích, zápalné a pokojné oběti sestoupil dolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Mojžíš a Áron vešli do stanu setkávání. Když vyšli, požehnali lidu a Hospodinova sláva se ukázala všemu lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Od Hospodina vyšlehl oheň a strávil na oltáři zápalnou oběť i tučné části. Všechen lid to viděl, výskali a padli na tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Nato Áronovi synové Nádab a Abíhú vzali každý svou kadidelnici, dali do nich oheň, položili na něj kadidlo a přinesli před Hospodina cizí oheň, jak jim nepřikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'I vyšlehl oheň od Hospodina a strávil je; zemřeli před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Mojžíš řekl Áronovi: ⌈To je to, co promluvil Hospodin:⌉ Prostřednictvím těch, kteří se ke mně přibližují, ⌈dosvědčím svou svatost⌉ a oslavím se před vším lidem. Áron mlčel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mojžíš zavolal Míšaela a Elsáfana, syny Áronova strýce Uzíela, a řekl jim: Přistupte a odneste své bratry od svatyně ven za tábor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Přistoupili tedy a odnesli je v jejich suknicích ven za tábor, jak řekl Mojžíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Pak řekl Mojžíš Áronovi a jeho synům Eleazarovi a Ítamarovi: Nerozpouštějte si vlasy na hlavě a netrhejte své roucho, abyste nezemřeli a Hospodin se ne rozhněval na celou pospolitost. Vaši bratři, celý dům Izraele, budou oplakávat ⌈spálené ohněm,⌉ který Hospodin zapálil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Neodcházejte od vchodu do stanu setkávání, jinak zemřete, neboť je na vás Hospodinův olej pomazání. I udělali podle Mojžíšova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Hospodin promluvil k Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Nebudeš pít víno ani pivo, ty ani tví synové s tebou, když budete přicházet do stanu setkávání, abyste nezemřeli. To je věčné ustanovení pro vaše potomky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Budete rozlišovat mezi svatým a obyčejným, mezi nečistým a čistým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Budete vyučovat syny Izraele všem ustanovením, která k vám Hospodin promluvil prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Mojžíš promluvil k Áronovi a k jeho zbývajícím synům Eleazarovi a Ítamarovi: Vezměte přídavnou oběť, která z Hospodinových ohnivých obětí zbyla, a jezte ji nekvašenou vedle oltáře, neboť je to nejsvětější věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Budete ji jíst na svatém místě, neboť je to příděl tvůj a příděl tvých synů z Hospodinových ohnivých obětí, protože tak mi bylo přikázáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Hrudí z mávané oběti a kýtu z daru pozdvihování budete jíst na čistém místě, ty a s tebou tvoji synové a tvé dcery, neboť je to příděl tvůj a příděl tvých synů, který byl dán z obětních hodů pokojné oběti synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Kýtu z daru pozdvihování a hrudí z mávané oběti přinesou spolu s tučnými částmi ohnivých obětí, jimiž má být máváno jako mávanou obětí před Hospodinem. Bude to věčným přídělem pro tebe a pro tvé syny s tebou, jak přikázal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Mojžíš se velmi vyptával na kozla k oběti za hřích a hle, byl již spálen. Nato se rozhněval na zbývající Áronovy syny, Eleazara a Ítamara, a řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Proč jste nesnědli oběť za hřích na svatém místě? Vždyť je to nejsvětější věc a dal ji vám, abyste sňali vinu pospolitosti a vykonali za ni obřad smíření před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Hle, její krev nebyla vnesena dovnitř svatyně. Jistě jste ji měli sníst ve svatyni, jak jsem přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Áron Mojžíšovi odpověděl: Hle, dnes přinesli svou oběť za hřích a svou zápalnou oběť před Hospodinem, a postihlo mě něco takového. Kdybych dnes jedl oběť za hřích, líbilo by se to Hospodinu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Když to Mojžíš slyšel, líbilo se mu to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Hospodin promluvil k Mojžíšovi a Áronovi a řekl jim:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Promluvte k synům Izraele: Toto jsou živočichové, které budete jíst ze všech zvířat, která jsou na zemi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Všechna, která mají rozdělená kopyta, zcela rozdvojená kopyta, přežvýkavce mezi zvířaty, ty jezte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Z přežvýkavců a z těch, kteří mají rozdělená kopyta, však nejezte tyto: velblouda, protože je přežvýkavec, ale kopyta nemá rozdělená. Je pro vás nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Ani damana, protože je přežvýkavec, ale nemá rozdělená kopyta. Je pro vás nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Ani zajíce, protože je přežvýkavec, ale nemá rozdělená kopyta. Je pro vás nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Ani vepře, protože má rozdělená kopyta, zcela rozdvojená kopyta, ale vůbec nepřežvykuje. Je pro vás nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Jejich maso nejezte a jejich zdechlin se nedotýkejte. Jsou pro vás nečistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Ze všeho, co je ve vodě, jezte toto: všechno ve vodě, v mořích i v potocích, co má ploutve a šupiny, to jezte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'a všechno, co nemá ploutve a šupiny, ať v mořích či potocích, jakákoliv vodní havěť a cokoliv živého ve vodě, je pro vás hodné opovržení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Budou pro vás hodní opovržení. Jejich maso nejezte a jejich zdechliny si ošklivte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Všechno ve vodě, co nemá ploutve a šupiny, je pro vás hodné opovržení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Z ptáků si ošklivte tyto -- nejedí se, jsou hodní opovržení: orla, supa, orlovce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'luňáka červeného, luňáka černého a luňáky všeho druhu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'všechny druhy havranů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'pštrosa, sovu, racka, sokoly všeho druhu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'sýčka, kormorána, výra,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'sovu pálenou, pelikána, mrchožrouta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'čápa, volavky všeho druhu, dudka a netopýra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Všechen okřídlený hmyz chodící po čtyřech je pro vás hodný opovržení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Jenom tyto budete jíst ze všeho okřídleného hmyzu chodícího po čtyřech: Ty, které mají stehýnka nad nohama a skáčou s nimi po zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Budete z nich jíst tyto: kobylky arbe všeho druhu, kobylky soleám všeho druhu, kobylky chargól všeho druhu a kobylky chágáb všeho druhu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Všechen ostatní okřídlený hmyz, který má čtyři nohy, je pro vás hodný opovržení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Těmi se poskvrníte; každý, kdo by se dotkl jejich zdechliny, bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'A každý, kdo by nesl jejich zdechlinu, si vypere šaty; bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Všechna zvířata, která mají rozdělená kopyta, ale ne zcela rozdvojená, a nejsou přežvýkavci, jsou pro vás nečistá. Každý, kdo by se jich dotkl, bude nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Všechno, co mezi všemi živočichy chodícími po čtyřech chodí po rukou, je pro vás nečisté. Každý, kdo by se dotkl jejich zdechliny, bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Kdo by nesl jejich zdechlinu, vypere si šaty; bude nečistý až do večera. Jsou pro vás nečistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Tito jsou pro vás nečistí mezi havětí hemžící se na zemi: krtek, myš, ještěrky všeho druhu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'gekon turecký, ještěrka, gekon, scink a chameleon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Tito jsou pro vás nečistí mezi vší havětí. Každý, kdo by se jich dotkl, ⌈když pojdou,⌉ bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Cokoliv, na co padne některé z nich, ⌈když pojdou,⌉ bude nečisté -- jakýkoliv dřevěný předmět či oděv, kůže nebo pytlovina, jakékoliv náčiní, s nímž se koná práce, bude vloženo do vody -- do večera to bude nečisté, až pak to bude čisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Jakákoliv hliněná nádoba, do níž spadne některé z nich, všechno, co je v ní, bude nečisté a nádobu rozbijete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Jakékoliv jídlo, které se jí a na které přijde voda, bude nečisté a jakýkoliv nápoj, který se pije z jakékoliv znečištěné nádoby, bude nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'A na cokoliv spadne některá z jejich zdechlin, to bude nečisté. Pec i krb se zboří; jsou nečisté a nečisté pro vás zůstanou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'pouze pramen a cisterna s nahromaděnou vodou budou čisté. Kdo by se však dotkl jejich zdechlin, bude nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Když spadne některá z jejich zdechlin na jakékoliv semeno, na setbu, která se vysévá, bude čistá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Když však bude na semeno dána voda a spadne na něj některá z jejich zdechlin, bude to pro vás nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Když uhyne některé ze zvířat, která máte k jídlu, ten, kdo by se dotkl jeho zdechliny, bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Kdo by jedl z jeho zdechliny, vypere si šaty a bude nečistý až do večera. Kdo by nesl jeho zdechlinu, vypere si šaty a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Všechna havěť hemžící se po zemi, je hodná opovržení, nejí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Ze vší havěti hemžící se po zemi nebudete jíst nic, co se plazí po břiše, nic, co chodí po čtyřech ani cokoliv, co má mnoho nohou, protože je to hodné opovržení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Nečiňte sami sebe hodné opovržení žádnou hemžící se havětí, neposkvrňujte se jimi, takže byste jimi byli poskvrněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Neboť ⌈já Hospodin jsem váš Bůh.⌉ Posvěťte se a buďte svatí, neboť já jsem svatý. Neposkvrňujte sami sebe žádnou havětí plazící se po zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Neboť já Hospodin jsem vás vyvedl z egyptské země, abych byl ⌈vaším Bohem.⌉ Buďte svatí, neboť já jsem svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Toto je zákon o zvířatech, ptactvu a vší živé duši pohybující se ve vodě a o každé duši hemžící se po zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Budete rozlišovat mezi nečistým a čistým a mezi živočichy, kteří se jedí, a živočichy, kteří se nejedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Promluv k synům Izraele: Když žena počne a porodí chlapce, bude nečistá sedm dní; bude nečistá jako po dobu své menstruační nečistoty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Osmého dne bude obřezáno maso jeho předkožky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Třicet tři dní zůstane v očišťování od krve. Nedotkne se ničeho svatého a nevejde do svatyně, dokud se nenaplní dny jejího očišťování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Pokud porodí děvče, bude nečistá dva týdny jako při menstruaci a šedesát šest dní zůstane v očišťování od krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Když se naplní dny jejího očišťování za syna či dceru, přinese knězi ke vchodu do stanu setkávání ročního beránka jako zápalnou oběť a holoubě či hrdličku jako oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Kněz to přinese před Hospodina, vykoná za ni obřad smíření a bude čistá od svého krvotoku. Toto je zákon o rodičce chlapce či děvčete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Jestliže její ⌈prostředky nestačí⌉ na ovci, vezme dvě hrdličky nebo dvě holoubata, jedno jako zápalnou oběť a druhé jako oběť za hřích. Kněz za ni vykoná obřad smíření a bude čistá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Když bude mít někdo na kůži svého těla otok nebo vyrážku či světlou skvrnu a může se změnit na kůži jeho těla v ránu malomocenství, ať je přiveden ke knězi Áronovi či k některému z jeho synů, kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Kněz si prohlédne ránu na kůži jeho těla. Jestliže chlupy na ráně zbělely a rána vypadá hlubší než kůže jeho těla, je to rána malomocenství. Když to kněz uvidí, prohlásí ho za nečistého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Jestliže světlá skvrna na kůži jeho těla je bílá, ale nevypadá hlubší než kůže a jeho chlupy nezbělely, kněz uzavře člověka postiženého touto ranou na sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Sedmého dne ho kněz prohlédne, a jestliže mu rána připadá stejná, nerozšířila se po kůži, kněz ho uzavře na dalších sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Kněz ho prohlédne opět sedmého dne, a jestliže rána je vybledlá, nerozšířila se rána po kůži, kněz ho prohlásí za čistého; je to vyrážka. On si vypere šaty a bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Jestliže se však vyrážka dále šíří po kůži i poté, co se ukázal knězi ke svému očištění, ukáže se knězi opět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Když kněz uvidí, že se vyrážka po kůži rozšířila, prohlásí ho kněz za nečistého; je to malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Když bude na někom rána malomocenství, ať je přiveden ke knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Kněz ho prohlédne, a když je na kůži bílý otok, který zbělel chlupy a na otoku je živé maso,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'je to chronické malomocenství na kůži jeho těla. Kněz ho prohlásí za nečistého; neuzavře ho, protože je nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Jestliže se malomocenství rozbují dále po kůži, malomocenství pokryje celou kůži člověka postiženého ranou od hlavy až k chodidlům, ⌈všude, kam kněz dohlédne,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'a kněz vidí, že malomocenství pokrylo celé jeho tělo, prohlásí člověka postiženého ranou za čistého; celý zbělel, je čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'V den, kdy by se na něm ukázalo živé maso, bude nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Když kněz uvidí živé maso, prohlásí jej za nečistého. Živé maso je nečisté; je to malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Nebo když živé maso zase zbělí, přijde ke knězi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'kněz ho prohlédne, a jestliže rána zbělí, kněz prohlásí člověka postiženého ranou za čistého; je čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Když se stane, že tělo, na jehož kůži byl vřed, se uzdraví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'ale potom se na místě vředu objeví bílý otok nebo červenobílá světlá skvrna, ukáže se knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Kněz ho prohlédne, a jestliže to vypadá nižší než kůže a chlupy zbělely, kněz ho prohlásí za nečistého. Je to rána malomocenství rozbujelá na vředu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Když kněz uvidí, že chlupy na něm nejsou bílé, není to nižší než kůže a je to vybledlé, uzavře ho kněz na sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Jestliže se dále rozšíří po kůži, prohlásí ho kněz za nečistého; je to rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Jestliže však zůstane světlá skvrna na svém místě, nerozšíří se, je to jizva vředu. Kněz ho prohlásí za čistého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Nebo když bude mít nějaké tělo na kůži spáleninu a na spálenině se objeví červenobílá či bílá světlá skvrna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'kněz ji prohlédne. Jestliže chlupy na světlé skvrně zbělely a vypadá to hlubší než kůže, je to malomocenství rozbujelé na spálenině. Kněz ho prohlásí za nečistého; je to rána malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Jestliže kněz uvidí, že chlupy na světlé skvrně nejsou bílé, není to nižší než kůže a je to vybledlé, uzavře ho kněz na sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Sedmého dne jej kněz prohlédne, a jestliže se to dále rozšíří po kůži, prohlásí ho kněz za nečistého; je to rána malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Jestliže zůstane světlá skvrna na svém místě, nerozšíří se po kůži a je to vybledlé, je to otok na spálenině. Kněz ho prohlásí za čistého; neboť je to jizva na spálenině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Když bude mít muž či žena ránu na hlavě nebo na bradě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'kněz ránu prohlédne. Jestliže to vypadá hlubší než kůže, jsou na tom chlupy nažloutlé a jemné, prohlásí ho kněz za nečistého. Je to ekzém, je to malomocenství na hlavě či bradě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Když kněz uvidí ránu ekzému, že nevypadá hlubší než kůže a chlupy na ní nejsou černé, uzavře kněz postiženého ranou ekzému na sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Sedmého dne kněz ránu prohlédne. Jestliže se ekzém nerozšířil, nejsou na něm nažloutlé chlupy a ekzém nevypadá hlubší než kůže,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'dotyčný se oholí, ale místo postižené ekzémem si neoholí. Kněz uzavře člověka postiženého ekzémem na dalších sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Sedmého dne kněz ekzém prohlédne. Jestliže se ekzém po kůži nerozšíří a nevypadá hlubší než kůže, kněz ho prohlásí za čistého. On si vypere šaty a bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Jestliže se však ekzém po jeho očištění po kůži dále nerozšíří,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'kněz ho prohlédne. Jestliže se ekzém po kůži rozšířil, kněz si nebude všímat nažloutlých chlupů, je nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Jestliže ⌈mu ale ekzém bude připadat stejný,⌉ vyrostly na něm černé chlupy, ekzém se uzdravil, je čistý. Kněz ho prohlásí za čistého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Když bude mít muž či žena na kůži svého těla světlé skvrny, bílé světlé skvrny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'kněz to prohlédne. Jestliže jsou na kůži jeho těla světlé skvrny vybledlé, bílé, je to vyrážka rozbujelá na kůži; postižený je čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Když muž na hlavě olysá a je plešatý, je čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Jestliže na skráních vepředu olysá a je plešatý na čele, je čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Když se však objeví na lysém místě vzadu či na pleši vepředu červenobílá rána, je to malomocenství, které vyrazilo na lysém místě vzadu či na pleši vepředu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Kněz ho prohlédne. Jestliže má červenobílou ránu otoku na lysém místě vzadu či na pleši vepředu a vypadá to jako malomocenství na kůži těla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'je člověkem postiženým malomocenstvím; je nečistý. Kněz ho jistě prohlásí za nečistého; na hlavě má ránu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Co se týče toho, kdo je postižen ranou malomocenství, jeho šaty budou roztržené, vlasy na jeho hlavě budou rozpuštěné, bude si zakrývat vous a bude volat: Nečistý, nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Nečistý bude po všechny dny, kdy na něm bude rána. Je nečistý, bude bydlet o samotě, jeho místo k bydlení bude venku za táborem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, '⌈Když se rána malomocenství objeví na oděvu,⌉ na oděvu vlněném či oděvu lněném,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'na tkanině či na pletenině ze lnu nebo z vlny či na kůži anebo na jakémkoliv koženém výrobku');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'a bude ta rána na oděvu, na kůži, na tkanině, na pletenině či na jakémkoliv koženém předmětu zelenkavá anebo načervenalá, je to rána malomocenství, ukáže se to knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Kněz věc postiženou ranou prohlédne a uzavře ji na sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Sedmý den prohlédne věc postiženou ranou. Když se rána rozšířila po oděvu, tkanině či pletenině nebo po kůži a jakémkoliv výrobku, který se dělá z kůže, je to zhoubná rána malomocenství, je to nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Spálí oděv, tkaninu či pleteninu z vlny či ze lnu či jakýkoliv předmět z kůže, na němž bude rána, neboť je to zhoubné malomocenství. Spálí se to ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Jestliže kněz uvidí, že se rána nerozšířila po oděvu, tkanině či pletenině nebo jakémkoliv koženém předmětu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'vydá kněz příkaz, aby se vypralo to, na čem je rána, a on to uzavře na dalších sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Kněz prohlédne věc postiženou ranou poté, co byla vyprána. Jestliže rána nezměnila vzhled, i když se rána nerozšířila, je to nečisté. Spálíš to ohněm. Je to zažrané, ať na líci či na rubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Jestliže však kněz uvidí, že rána je vybledlá poté, co to bylo vypráno, odtrhne to z oděvu či z kůže, tkaniny nebo pleteniny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Jestliže se to objeví znovu na oděvu, tkanině či pletenině nebo jakémkoliv koženém předmětu a bují to, spálíš ohněm to, na čem je rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Oděv, tkanina či pletenina nebo jakýkoliv kožený předmět, který vypereš a rána z nich zmizí, se vypere podruhé a bude to čisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Toto je zákon o ráně malomocenství na oděvu vlněném či lněném nebo tkanině či pletenině nebo jakémkoliv koženém předmětu -- jak prohlásit něco za čisté nebo nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Toto je zákon o malomocném v den jeho očišťování, kdy bude přiveden ke knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Kněz vyjde ven za tábor. Když kněz uvidí, že rána malomocenství byla na člověku postiženém malomocenstvím uzdravena,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'kněz přikáže přinést za toho, kdo je očišťován, dva čisté živé ptáky, cedrové dřevo, karmínové barvivo a yzop.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Pak kněz přikáže zabít jednoho ptáka nad hliněnou nádobou s pramenitou vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Toho živého ptáka vezme spolu s cedrovým dřevem, karmínovým barvivem a yzopem a ponoří je s živým ptákem do krve ptáka zabitého nad pramenitou vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Sedmkrát stříkne na toho, kdo je očišťován od malomocenství, prohlásí ho za čistého a propustí živého ptáka do otevřené krajiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Ten, kdo se očišťuje, si vypere oděv, oholí si všechny vlasy, umyje se vodou a bude čistý. Potom vejde do tábora a zůstane po sedm dní mimo svůj stan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Sedmého dne si oholí všechny vlasy na hlavě, vousy i obočí, prostě si oholí všechny chlupy, vypere si oděv, umyje si tělo vodou a bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Osmého dne vezme dva beránky bez vady, jednu roční ovečku bez vady, tři desetiny éfy jemné mouky jako přídavnou oběť namísenou s olejem a jeden log oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Kněz, který očišťuje, postaví toho, kdo je očišťován, s těmito věcmi před Hospodina ke vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Kněz vezme jednoho beránka a přinese ho s logem oleje jako oběť za vinu a zamává s nimi před Hospodinem jako s obětí mávanou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Beránka zabije na místě, kde se zabíjí oběť za hřích a zápalná oběť, na místě svatém, neboť jak oběť za hřích, tak i oběť za vinu patří knězi; je to nejsvětější věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Kněz vezme trochu krve z oběti za vinu a dá na lalůček pravého ucha toho, kdo je očišťován, na palec jeho pravé ruky a na palec jeho pravé nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Kněz vezme z logu oleje a vyleje to do své levé dlaně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Kněz namočí pravý prst v oleji, který má na levé dlani, a sedmkrát stříkne před Hospodinem prstem z oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Ze zbytku oleje, který má na dlani, dá kněz na lalůček pravého ucha toho, kdo je očišťován, na palec jeho pravé ruky a na palec jeho pravé nohy, na krev z oběti za vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Zbývající olej, který má na dlani, dá kněz na hlavu toho, kdo je očišťován. Tak za něj kněz vykoná obřad smíření před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Kněz vykoná oběť za hřích a vykoná obřad smíření za toho, kdo je očišťován ze své nečistoty; potom zabije zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Kněz přinese zápalnou i přídavnou oběť na oltáři. Kněz za něj vykoná obřad smíření a bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Jestliže je chudý a jeho prostředky nestačí, vezme jednoho beránka k oběti za vinu jako mávanou oběť, aby za něj vykonal obřad smíření, a jednu desetinu jemné mouky namísenou s olejem k přídavné oběti a log oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Dvě hrdličky nebo dvě holoubata, jak stačí jeho prostředky; a bude jedno na oběť za hřích a druhé na zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Osmého dne je přinese knězi ke vchodu do stanu setkávání před Hospodina ke svému očištění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Kněz vezme beránka k oběti za vinu a log oleje a zamává s nimi před Hospodinem jako mávanou obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Když zabije beránka k oběti za vinu, vezme kněz trochu krve z oběti za vinu a dá na lalůček pravého ucha toho, kdo je očišťován, na palec jeho pravé ruky a na palec jeho pravé nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Trochu oleje vyleje kněz do své levé dlaně');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'a sedmkrát stříkne před Hospodinem pravým prstem z oleje, který má na levé dlani.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Potom dá kněz trochu oleje, který má na dlani, na lalůček pravého ucha toho, kdo je očišťován, na palec jeho pravé ruky a na palec jeho pravé nohy, na místo, kde je krev z oběti za vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Zbývající olej, který má na dlani, dá kněz na hlavu toho, kdo je očišťován. Tak za něj vykoná obřad smíření před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Pak připraví jednu z hrdliček nebo jedno z holoubat, na které stačí jeho prostředky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, '⌈jak stačí jeho prostředky,⌉ jedno jako oběť za hřích a druhé jako zápalnou oběť spolu s přídavnou obětí. Tak kněz vykoná před Hospodinem obřad smíření za toho, kdo je očišťován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Toto je zákon pro toho, kdo je postižen ranou malomocenství a jehož prostředky nestačí na jeho očištění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Až vejdete do kenaanské země, kterou vám dávám do vlastnictví, a já dám ránu malomocenství na nějaký dům v zemi vašeho vlastnictví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'ten, komu dům patří, přijde a oznámí knězi: Objevilo se mi na domě něco jako rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Kněz vydá příkaz, aby vyprázdnili dům, dříve nežli kněz přijde prohlédnout ránu. Tak nebude nečistého nic, co je v domě. Potom přijde kněz prohlédnout dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Když prohlédne ránu a uvidí, že na zdech domu je rána jako zelenkavé anebo načervenalé důlky a vypadají hlubší nežli zeď,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'vyjde kněz z domu ke vchodu do domu a uzavře dům na sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Sedmého dne se kněz vrátí a prohlédne to. Jestliže se rána rozšířila po zdech domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'přikáže, aby vytrhli kameny, na nichž je rána, a hodili je ven za město na nečisté místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Dům dá uvnitř kolem dokola oškrábat a omítku, kterou oškrábali, vysypou ven za město na nečisté místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Pak vezmou jiné kameny a dají je na místo těch prvních kamenů a také vezmou jinou omítku a omítnou dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Jestliže se rána vrátí a rozbují v domě poté, co vytrhli kameny, oškrábali dům a znovu omítli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'přijde kněz, prohlédne ho, a jestliže se rána na domě rozšíří, je to zhoubné malomocenství na domě; je nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Dům bude stržen -- jeho kámen, jeho dřevo i všechna omítka z domu -- a bude vynesen ven za město na nečisté místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Ten, kdo by vešel do domu kdykoliv v době, kdy je uzavřen, bude až do večera nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'A ten, kdo by spal v tom domě, vypere si oděv i ten, kdo by jedl v tom domě, vypere si oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Jestliže však kněz vejde a uvidí, že se rána na domě poté, co byl dům omítnut, nerozšířila, prohlásí kněz dům za čistý, neboť se rána uzdravila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Aby očistil dům od hříchu, vezme dva ptáky, cedrové dřevo, karmínové barvivo a yzop.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Pak zabije jednoho ptáka nad hliněnou nádobou s pramenitou vodou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'vezme cedrové dřevo, yzop, karmínové barvivo a živého ptáka, ponoří je do krve zabitého ptáka a do pramenité vody a stříkne sedmkrát na dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Tak dům krví toho ptáka, pramenitou vodou, živým ptákem, cedrovým dřevem, yzopem a karmínovým barvivem očistí od hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Živého ptáka propustí ven za město do otevřené krajiny, vykoná za dům obřad smíření a bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Toto je zákon pro všechny rány malomocenství a ekzémy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'pro malomocenství na oděvu i na domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'pro otok, vyrážku a světlou skvrnu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'pro poučení, kdy je něco nečisté a kdy čisté. Toto je zákon o malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Promluvte k synům Izraele a řekněte jim: Když bude nějaký muž trpět výtokem ze svého údu, pro svůj výtok je nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'A takto to bude s jeho nečistotou při jeho výtoku: Ať jeho úd vypouští výtok nebo jeho úd výtok zadržuje, je to jeho nečistota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Každé lože, na které ulehne muž trpící výtokem, bude nečisté a každý předmět, na který usedne, bude nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Kdokoliv se dotkne jeho lože, vypere si oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Ten, kdo si sedne na předmět, na který usedl trpící výtokem, vypere si oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Kdo se dotkne těla muže trpícího výtokem, vypere si oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Když muž trpící výtokem plivne na čistého, ten si vypere oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Každé sedlo, na kterém pojede muž trpící výtokem, bude nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Každý, kdo se dotkne čehokoliv, co bylo pod ním, bude nečistý až do večera, a kdo ponese takové věci, vypere si oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Každý, koho se dotkne muž trpící výtokem, aniž by si opláchl ruce vodou, si vypere oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Hliněná nádoba, které se dotkne muž trpící výtokem, se rozbije a jakýkoliv dřevěný předmět se opláchne vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Když bude muž trpící výtokem zbaven svého výtoku, odpočítá si sedm dní pro své očišťování, vypere si oděv, umyje si tělo pramenitou vodou a bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Osmého dne si vezme dvě hrdličky nebo dvě holoubata, přijde před Hospodina ke vchodu do stanu setkávání a dá je knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Kněz je bude obětovat: jedno jako oběť za hřích a druhé jako zápalnou oběť. Tak kněz za něj, kvůli jeho výtoku, vykoná obřad smíření před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, '⌈Když vyjde z muže⌉ výron semene, umyje si vodou celé tělo a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Každý oděv a každý kus kůže, na němž bude výron semene, se vypere ve vodě a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Když muž ulehne s ženou a dojde k výronu semene, umyjí se oba vodou a budou nečistí až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Když bude mít žena výtok a její výtok v jejím těle bude krvavý, sedm dní bude ⌈ve své nečistotě⌉ a každý, kdo se jí dotkne, bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Všechno, na co si lehne ⌈ve své nečistotě,⌉ bude nečisté a všechno, na co si sedne, bude nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Každý, kdo se dotkne jejího lože, si vypere oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Každý, kdo se dotkne jakéhokoliv předmětu, na který usedla, si vypere oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Jestliže se dotkne něčeho, co bylo na loži či na předmětu, na kterém seděla, bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Pokud s ní přece někdo ulehne, její nečistota se dostane na něj, bude nečistý po sedm dní a každé lože, na kterém bude ležet, bude nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Když bude mít žena výtok krve po mnoho dní, mimo čas své nečistoty, anebo když bude mít výtok po době své nečistoty -- po všechny dny výtoku své nečistoty bude jako ve dnech své nečistoty; bude nečistá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Každé lože, na které ulehne po ⌈všechny dny⌉ svého výtoku, bude pro ni jako lože její nečistoty a každý předmět, na který usedne, bude nečistý jako nečistota její menstruace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Každý, kdo se jich dotkne, bude nečistý, vypere si oděv, umyje se vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Jestliže bude zbavena svého výtoku, odpočítá si sedm dní a potom bude čistá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Osmého dne si vezme dvě hrdličky nebo dvě holoubata a přinese je knězi ke vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Kněz bude obětovat jedno jako oběť za hřích a druhé jako zápalnou oběť. Tak za ni kvůli výtoku její nečistoty kněz vykoná obřad smíření před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Oddělíte syny Izraele od jejich nečistoty, aby nezemřeli kvůli své nečistotě, když by znečistili můj příbytek, který je uprostřed nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Toto je zákon o muži trpícím výtokem, o tom, ze kterého vychází výron semene, který ho poskvrňuje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'o ženě poskvrněné svou nečistotou -- o tom, kdo má výtok, ať muž či žena, a o muži, který spí s nečistou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Hospodin promluvil k Mojžíšovi po smrti dvou synů Áronových, kteří zemřeli, když předstoupili před Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Hospodin řekl Mojžíšovi: Promluv ke svému bratru Áronovi, ať nevchází kdykoli se mu zachce do svatyně za oponu před slitovnici, která je na truhle, aby nezemřel, neboť se ukazuji v oblaku nad slitovnicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Jen takto ať vejde Áron do svatyně: s býčkem k oběti za hřích a s beranem k zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Obleče si svatou lněnou suknici a na jeho těle budou lněné spodky. Přepásá se lněnou šerpou a omotá si lněný turban. To jsou svatá roucha. Umyje si tělo vodou a pak se obleče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Od pospolitosti synů Izraele vezme dva kozly k oběti za hřích a jednoho berana k zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Áron přivede svého býčka k oběti za hřích a vykoná obřad smíření za sebe a za svůj dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Pak vezme dva kozly a postaví je před Hospodina ke vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Áron o ty dva kozly hodí losy, jeden los pro Hospodina a druhý pro Azázela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Áron přivede kozla, na kterého vyšel los pro Hospodina, a obětuje ho jako oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Kozel, na kterého vyšel los pro Azázela, bude postaven živý před Hospodina, aby ⌈na něm vykonal obřad smíření⌉ a poslal ho Azázelovi do pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Áron přivede svého býčka k oběti za hřích a vykoná obřad smíření za sebe a za svůj dům a zabije svého býčka k oběti za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Vezme plnou kadidelnici řeřavého uhlí z oltáře před Hospodinem a dvě plné hrsti jemného vonného kadidla a přinese to za oponu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Kadidlo dá na oheň před Hospodinem a oblak z kadidla zakryje slitovnici, která je na svědectví, takže nezemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Vezme trochu krve z býčka a stříkne prstem na přední stranu slitovnice na východě a před slitovnicí stříkne prstem trochu krve sedmkrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Potom zabije kozla k oběti za hřích, který je za lid, přinese jeho krev za oponu a s jeho krví udělá to, co udělal s krví býčka: stříkne ji na slitovnici a před slitovnici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Takto zprostí svatyni od nečistot synů Izraele a jejich přestoupení, od jakýchkoliv jejich hříchů. Totéž učiní pro stan setkávání, který zůstává s nimi uprostřed jejich nečistot.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Nikdo nebude ve stanu setkávání, když vejde, aby vykonal obřad smíření ve svatyni, dokud nevyjde. Tak vykoná obřad smíření za sebe, za svůj dům a za celé shromáždění Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Potom vyjde k oltáři, který je před Hospodinem, a vykoná za něj obřad smíření. Vezme trochu krve z býčka a trochu krve z kozla a dá na rohy oltáře kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Sedmkrát na něj stříkne prstem trochu krve a tak ho očistí a posvětí od nečistot synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Když dokončí obřad smíření za svatyni, stan setkávání a oltář, přivede živého kozla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Áron položí obě ruce na hlavu živého kozla, vyzná nad ním všechny viny synů Izraele a všechna jejich přestoupení, jakýkoliv jejich hřích, dá je na hlavu kozla a pošle ho prostřednictvím připraveného muže do pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Kozel na sobě ponese všechny jejich viny do nepřístupné země. ⌈V pustině kozla vypustí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Potom Áron vejde do stanu setkávání, svlékne si lněné roucho, které si oblékl, když vešel do svatyně, a zanechá ho tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Umyje si tělo vodou na svatém místě, oblékne si svůj oděv, vyjde a připraví svou zápalnou oběť a zápalnou oběť lidu a vykoná obřad smíření za sebe a za lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Tuk z oběti za hřích bude obětovat na oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Ten, kdo poslal kozla pro Azázela, si vypere oděv, umyje si tělo vodou a potom vstoupí do tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Býčka k oběti za hřích a kozla k oběti za hřích, jejichž krev byla vnesena k vykonání obřadu smíření do svatyně, vynese ven za tábor a ohněm spálí jejich kůži, jejich maso a jejich výměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Ten, kdo je spálí, si vypere oděv, umyje si tělo vodou a potom vstoupí do tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'A toto bude pro vás věčné ustanovení: sedmého měsíce, desátého dne toho měsíce budete pokořovat ⌈své duše⌉ a nebudete konat žádnou práci -- ani domorodec ani příchozí, který pobývá uprostřed vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Protože tohoto dne za vás vykoná obřad smíření, aby vás očistil od všech vašich hříchů. Budete před Hospodinem čistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Je to pro vás ⌈nejsvětější sobota⌉ a budete pokořovat své duše; to je věčné ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Obřad smíření vykoná kněz, který je pomazán a zasvěcen, aby sloužil jako kněz namísto svého otce, a oblékl lněné roucho, svaté roucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Vykoná obřad smíření za nejsvětější místo i za stan setkávání a za oltář vykoná obřad smíření a za kněze a všechen lid shromáždění vykoná obřad smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Toto bude pro vás věčné ustanovení: vykonat obřad smíření za syny Izraele, za všechny jejich hříchy jednou za rok. A on učinil tak, jak Hospodin přikázal Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Promluv k Áronovi a jeho synům a ke všem synům Izraele a řekni jim: Toto je to, co přikázal Hospodin:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Když kdokoliv z domu izraelského zabije býka nebo ovci či kozla v táboře nebo když ho zabije venku za táborem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'a nepřinese ho ke vchodu do stanu setkávání, aby ho obětoval jako obětní dar Hospodinu před Hospodinův příbytek, bude se to onomu muži počítat jako krveprolití; prolil krev. Takový člověk ať je vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'To proto, aby synové Izraele přinášeli své oběti, které obětují v otevřené krajině, -- přinášeli je Hospodinu ke vchodu do stanu setkávání ke knězi a obětovali je jako pokojné oběti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Kněz pokropí krví Hospodinův oltář u vchodu do stanu setkávání a tuk bude obětovat jako příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Nebudou již obětovat své oběti běsům, za nimiž chodili smilnit. Toto bude pro ně věčné ustanovení po všechna jejich pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Řekni jim: Když kdokoliv z domu izraelského nebo z příchozích, kteří pobývají mezi nimi, přinese zápalnou oběť anebo obětní hod');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'a nepřinese ji ke vchodu do stanu setkávání, aby ji obětoval Hospodinu, takový člověk ať je vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Když by kdokoliv z domu izraelského nebo z příchozích, kteří pobývají mezi nimi, jedl jakoukoliv krev, obrátím svou tvář proti tomu, kdo by jedl krev, a vyhladím jej zprostřed svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Neboť život těla je v krvi a já jsem vám ji dal na oltář k získání smíření pro vás, neboť je to krev, která získává pro člověka smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Proto jsem řekl synům Izraele: Nikdo z vás nebude jíst krev, ani příchozí, který pobývá mezi vámi, nebude jíst krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Když kdokoliv ze synů Izraele nebo z příchozích, kteří pobývají mezi nimi, uloví zvěřinu nebo ptáka, který se jí, vyleje jeho krev a přikryje ji hlínou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Neboť život každého těla je jeho krev. Proto jsem řekl synům Izraele: Krev žádného těla nebudete jíst, neboť život každého těla je jeho krev. Každý, kdo by ji jedl, ať je vyhlazen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Každý člověk, který by jedl zdechlinu nebo rozsápané zvíře, ať je to domorodec nebo příchozí, si vypere oděv, umyje se vodou a bude nečistý až do večera. Pak bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Pokud si je nevypere a neumyje si tělo, ponese svou vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Promluv k synům Izraele a řekni jim: Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Podle činů egyptské země, ve které jste sídlili, nejednejte, ani podle činů kenaanské země, do níž vás přivádím, nejednejte a podle jejich ustanovení nežijte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Plňte má nařízení, zachovávejte má ustanovení a žijte podle nich. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Zachovávejte má ustanovení a nařízení; když je člověk plní, bude skrze ně žít. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nikdo z vás se nepřiblíží k žádnému ⌈svému pokrevnímu příbuznému,⌉ aby odhalil jeho nahotu. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Nahotu svého otce, to je nahotu své matky, neodhalíš. Je to tvá matka, neodhalíš její nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Nahotu ženy svého otce neodhalíš; je to nahota tvého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Nahotu své sestry, dcery svého otce nebo své matky, ať narozené v domě či mimo něj -- neodhalíš jejich nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Nahotu dcery svého syna ani své dcery -- jejich nahotu neodhalíš, neboť jsou tvojí nahotou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Nahotu dcery ženy svého otce, narozené tvému otci -- je to tvá sestra, neodhalíš její nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Neodhalíš nahotu sestry svého otce; je to příbuzná tvého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Neodhalíš nahotu sestry své matky, neboť je to příbuzná tvé matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Neodhalíš nahotu bratra svého otce -- nepřiblížíš se k jeho ženě; je to tvá teta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Neodhalíš nahotu své snachy; je to žena tvého syna, neodhalíš její nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Neodhalíš nahotu ženy svého bratra; je to nahota tvého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Neodhalíš nahotu ženy i její dcery, ani si nevezmeš dceru jejího syna či její dcery, abys odhalil její nahotu -- jsou to příbuzné; je to hanebnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Nevezmeš si ženu k její sestře jako rivalku, abys odhalil její nahotu za jejího života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Nepřiblížíš se k ženě v době její menstruační nečistoty, abys odhalil její nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'S ženou svého druha nebudeš mít pohlavní styk, aby ses s ní poskvrnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Nikoho ze svého potomstva nenecháš provést ohněm Molekovi; neznesvětíš jméno svého Boha. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'S mužem nebudeš souložit jako se souloží s ženou; je to ohavnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'S žádným zvířetem nebudeš mít pohlavní styk, aby ses s ním poskvrnil; ani žena se nepostaví před zvíře, aby s ním obcovala; je to zvrhlost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Neposkvrníte se žádnou z těchto věcí, neboť všemi těmito věcmi se poskvrňovaly národy, které před vámi vyháním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Protože se země poskvrnila, navštívil jsem ji s trestem za její provinění a země vyvrhla své obyvatele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Vy však zachovávejte má ustanovení a má nařízení a nepáchejte nic z těchto ohavností -- ani domorodec, ani příchozí, který pobývá uprostřed vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Neboť všechny tyto ohavnosti páchali lidé země, kteří byli před vámi, a země se poskvrnila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Ať vás země nevyvrhne, když byste ji znečistili, jako vyvrhla národ, který byl před vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Neboť každý, kdo by páchal nějakou z těchto ohavností, všichni ti, kdo je páchají, ať jsou vyhlazeni zprostřed mého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Zachovávejte můj řád, abyste nepáchali nic z těchto ohavných zvyklostí, které se páchaly před vámi, a neposkvrňujte se jimi. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Promluv k celé pospolitosti synů Izraele a řekni jim: Buďte svatí, neboť já, Hospodin, váš Bůh, jsem svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Každý ať se bojí své matky a svého otce a zachovávejte mé soboty -- ⌈já Hospodin jsem váš Bůh.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Neobracejte se k nicotnostem a nedělejte si slité bohy. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Když obětujete Hospodinu obětní hod pokojné oběti, obětujte ho tak, abyste došli zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Bude se jíst v den vaší oběti i druhý den, ale co zbude do třetího dne, spálí se ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Jestliže by přece někdo jedl třetího dne, bude to znehodnocené, nenalezne zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Ten, kdo by ho jedl, ponese svou vinu, protože znesvětil to, co je svaté pro Hospodina. Takový člověk ať je vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Když budete sklízet žeň své země, nevyžínej zcela rohy svého pole a nesbírej klasy po své žni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Svou vinici nepaběrkuj a ⌈spadlé bobule⌉ své vinice nesbírej. Nech je pro chudého a příchozího. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Nekraďte, nezapírejte a nelžete jeden druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Nepřísahejte lživě v mém jménu, ať ne znesvětíš jméno svého Boha. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Neutlačuj svého bližního a neokrádej ho. Výdělek najatého ať u tebe nezůstane do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Neproklínej hluchého a nedávej překážku před slepého, ale boj se svého Boha. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Při soudu nejednejte špatně: nestraň chudému ani nenadržuj vysoko postavenému. Svého druha suď spravedlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Nechoď pomlouvat mezi svým lidem. ⌈Nestav se na krev svého bližního.⌉ Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Neměj ve svém srdci nenávist vůči svému bratrovi. Přísně pokárej svého druha, ať kvůli němu neneseš hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Nemsti se a nehněvej se na syny svého lidu, ale miluj svého bližního jako sebe samého. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Zachovávej má ustanovení. Nenechej pářit svůj dobytek dvojího druhu. Neosévej své pole semenem dvojího druhu. Ať na tebe nepřijde oděv z dvojího druhu vlákna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Když muž ulehne s ženou a bude mít výron semene a ta otrokyně byla určena muži, nebyla ovšem ještě vykoupena ani jí nebyla dána svoboda, bude dána náhrada, ale nebudou usmrceni, protože nebyla svobodná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'On přinese Hospodinu ke vchodu do stanu setkávání svou oběť za vinu, berana jako oběť za vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Kněz za něj před Hospodinem vykoná obřad smíření s beranem jako s obětí za vinu, za jeho hřích, kterým zhřešil, a jeho hřích, kterým zhřešil, mu bude odpuštěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Až přijdete do země a vysadíte ⌈všelijaké ovocné stromoví,⌉ ⌈necháte jeho ovoce nesklizené,⌉ po tři roky bude pro vás nejedlé, nebude se jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Čtvrtého roku bude všechno jeho ovoce ⌈svaté ke slavnosti⌉ pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'V pátém roce budete jíst jeho ovoce. Tak vám bude dále přinášet svou úrodu. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Nejezte nic s krví. Nevěštěte a nezabývejte se hadačstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Nestříhejte si dokola skráně své hlavy a nekaz si skráně své brady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Zářezy kvůli mrtvému si nedávejte na tělo ani tetování si nedávejte na sebe. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Neznesvětíš svou dceru tím, že ⌈bys z ní udělal prostitutku,⌉ aby země nesmilnila a ne naplnila se hanebností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Zachovávejte mé soboty a mějte v úctě mou svatyni. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Neobracejte se k duchům zemřelých a nevyhledávejte věštce, abyste se jimi poskvrňovali. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Před šedinami povstaň, cti starce a boj se svého Boha. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Když bude s tebou ve tvé zemi pobývat příchozí, neutiskujte ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Příchozí, který s vámi pobývá jako cizinec, na tom bude jako domorodec mezi vámi. Miluj ho jako sebe, protože jste byli příchozími v egyptské zemi. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Nejednejte špatně ⌈při rozhodování míry, váhy a objemu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Budete mít spravedlivé váhy, spravedlivé závaží, spravedlivou míru a spravedlivý hín. Já Hospodin jsem váš Bůh, který vás vyvedl z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Zachovávejte všechna má ustanovení, všechna má nařízení a plňte je. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Řekni synům Izraele: Když kdokoliv ze synů Izraele nebo z příchozích, kteří pobývají v Izraeli, vydá někoho ze svého potomstva Molekovi, jistě bude usmrcen; ať na něj lid země hází kamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'A já obrátím svou tvář proti takovému člověku a vyhladím jej zprostřed jeho lidu, neboť vydal někoho ze svého potomstva Molekovi, a tak znečistil mou svatyni a znesvětil mé svaté jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Jestliže by lid země přece nad tímto mužem, když vydal někoho ze svého potomstva Molekovi, přivřel oko a neusmrtil ho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'obrátím svou tvář proti tomu muži a proti jeho čeledi já a vyhladím zprostřed jejich lidu jej i všechny, kdo smilnili s ním tím, že smilnili s Molekem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'A jestliže se nějaký člověk obrátí k duchům zemřelých a věštcům, aby s nimi smilnil, proti takovému člověku obrátím svou tvář a vyhladím jej zprostřed jeho lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Posvěťte se a buďte svatí, neboť já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Zachovávejte má ustanovení a plňte je. Já Hospodin vás posvěcuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Kdyby kdokoliv proklel svého otce nebo svou matku, jistě bude usmrcen. Proklel svého otce či svou matku, jeho krev je na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Kdyby někdo zcizoložil s provdanou ženou, ⌈kdyby někdo zcizoložil s ženou⌉ svého bližního, jistě bude usmrcen -- cizoložník i cizoložnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Kdyby někdo ležel s ženou svého otce a tak odhalil nahotu svého otce, jistě budou usmrceni oba, jejich krev je na nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Kdyby někdo ležel se svou snachou, jistě budou oba usmrceni. Spáchali zvrhlost, jejich krev je na nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Kdyby muž souložil s mužem jako se souloží s ženou, oba spáchali ohavnost; jistě budou usmrceni, jejich krev je na nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Kdyby si muž vzal ženu a její matku, je to hanebnost. Ohněm budou spáleni on i ony, aby nebyla hanebnost ve vašem středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Kdyby měl muž pohlavní styk se zvířetem, jistě bude usmrcen a to zvíře zabijete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Kdyby se žena přiblížila k jakémukoliv zvířeti, aby s ním obcovala, zabiješ tu ženu i to zvíře. Jistě budou usmrceni, jejich krev je na nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Kdyby si muž vzal svou sestru, dceru svého otce nebo své matky, viděl by její nahotu a ona by viděla jeho nahotu, je to hanba. Před očima synů svého lidu budou vyhlazeni. Odhalil nahotu své sestry, ponese svou vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Kdyby muž ležel s ženou poskvrněnou menstruací, odhalil by její nahotu, obnažil její pramen a ona by odhalila ⌈pramen své krve,⌉ oba budou vyhlazeni zprostřed svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Neodhalíš nahotu sestry své matky nebo svého otce, neboť takový člověk obnažil svou příbuznou. Ponesou svou vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Kdyby muž ležel se svou tetou, odhalil nahotu svého strýce, ponesou svůj hřích, zemřou bezdětní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Kdyby si muž vzal ženu svého bratra, je to nečistota. Odhalil nahotu svého bratra; zůstanou bezdětní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Zachovávejte všechna má ustanovení a všechna má nařízení a plňte je, aby vás nevyvrhla země, do které vás přivádím, abyste v ní sídlili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Nežijte podle ustanovení národa, který před vámi vyháním, neboť oni činili všechny tyto věci, takže jsem jimi opovrhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Ale vám jsem řekl: Vy obsaďte jejich zemi, dám vám ji, abyste ji obsadili, zemi oplývající mlékem a medem. Já Hospodin jsem váš Bůh, který jsem vás oddělil od národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Rozlišujte mezi zvířaty čistými a nečistými, mezi ptáky nečistými a čistými. Nečiňte sami sebe hodnými opovržení zvířaty ani ptáky ani ničím, co se hýbe na zemi a co jsem pro vás oddělil za nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Budete svatí pro mě, neboť já, Hospodin, jsem svatý a oddělil jsem vás z národů, abyste byli moji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Muž či žena, v nichž bude duch zemřelých nebo duch věštecký, budou jistě usmrceni; bude se na ně házet kamení, jejich krev je na nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Hospodin řekl Mojžíšovi: Promluv ke kněžím, synům Áronovým, a řekni jim: Nikdo se nebude poskvrňovat s mrtvým mezi svým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Pouze svým ⌈nejbližším příbuzným⌉ -- svou matkou, svým otcem, svým synem, svou dcerou, svým bratrem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'a svou sestrou, která je panna, ⌈svou příbuznou,⌉ která se neprovdala, se může poskvrnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Neposkvrní se jako manžel mezi svým lidem, aby se ne znesvětil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Nebudou si vyholovat lysinu na hlavě ani si holit skráně brady ani si dělat zářezy na těle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Budou svatí svému Bohu a neznesvětí jméno svého Boha, protože přinášejí Hospodinovy ohnivé oběti, pokrm svého Boha; proto budou svatí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Nevezmou si ženu prostitutku či znesvěcenou ani si nevezmou ženu zapuzenou jejím mužem, neboť kněz je svatý svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Pokládej ho za svatého, neboť přináší pokrm tvého Boha. Bude pro tebe svatý, neboť já, Hospodin, který vás posvěcuji, jsem svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Když se dcera kněze znesvětí smilstvem, znesvětí svého otce; bude upálena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Kněz, který je největší mezi svými bratry, na jehož hlavu byl vylit olej pomazání a byl zasvěcen, aby oblékl roucho, si nebude rozpouštět vlasy na hlavě a neroztrhne své roucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'K žádnému mrtvému člověku nepřijde, ani svým otcem či matkou se neposkvrní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Nevyjde ze svatyně a neznesvětí svatyni svého Boha, neboť je na něm zasvěcení olejem pomazání jeho Boha. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Vezme si ženu v jejím panenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Vdovu, zapuzenou nebo znesvěcenou prostitutku, žádnou takovou si nevezme. Vezme si za ženu pouze pannu ze svého lidu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'aby neznesvětil své potomstvo ve svém lidu, neboť já Hospodin ho posvěcuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Promluv k Áronovi: Po všechna pokolení nikdo z tvého potomstva, na kom bude vada, nebude přistupovat, aby přinášel pokrm svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Jistě nepřistoupí nikdo, na kom bude vada: člověk slepý ani chromý ani s rozděleným nosem či ⌈příliš dlouhou⌉ končetinou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'nikdo, kdo má zlomenou nohu či zlomenou ruku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'hrbatý nebo zakrnělý nebo se skvrnou na oku nebo s hnisavou ranou nebo s lišejem či s rozdrcenými varlaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nikdo z potomstva kněze Árona, na kom je vada, nepřistoupí, aby přinášel Hospodinovy ohnivé oběti. Má vadu, nepřistoupí, aby přinášel pokrm svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Pokrm svého Boha z nejsvětějších věcí i ze svatých věcí jíst může,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'avšak k oponě nepřijde a k oltáři nepřistoupí, protože má vadu. Neznesvětí mou svatyni, protože já Hospodin je posvěcuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Tak promluvil Mojžíš k Áronovi a jeho synům a ke všem synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Promluv k Áronovi a jeho synům, aby se svatými dary synů Izraele, které mi posvěcují, jednali s úctou, aby neznesvětili mé svaté jméno. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Řekni jim: Kdokoliv ze všech vašich potomků ve vašich pokoleních by přistoupil ke svatým darům, jež synové Izraele zasvěcují Hospodinu, a byla na něm nečistota, takový člověk bude přede mnou vyhlazen. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Kdokoliv z potomstva Áronova by byl postižen malomocenstvím či trpěl výtokem, nebude jíst ze svatých věcí, dokud nebude čistý. Ten, kdo by se dotkl čehokoliv znečištěného mrtvým nebo muže, z něhož vyšel výron semene,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'nebo ten, kdo by se dotkl jakékoliv havěti, která je pro něj nečistá, nebo člověka, který je pro něj nečistý jakoukoliv nečistotou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'ten, kdo by se toho dotkl, bude nečistý až do večera a nebude jíst ze svatých věcí, dokud si neumyje tělo vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Až zajde slunce, bude čistý, potom může jíst ze svatých věcí, neboť je to jeho pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Zdechlinu ani rozsápané zvíře nebude jíst, aby se s ním poskvrnil. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Ať zachovávají můj řád, aby na sobě nenesli hřích a nezemřeli kvůli němu, protože by to znesvětili. Já jsem Hospodin, který je posvěcuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Nikdo cizí nebude jíst ⌈svaté věci.⌉ Ani příchozí u kněze či najatý nebude jíst svaté věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Když ale kněz koupí někoho za stříbro do vlastnictví, ten může z toho jíst a také potomci jeho domu mohou jíst z jeho pokrmu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Když se dcera kněze vdá za někoho cizího, nebude jíst ze svatých darů pozdvihování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Když však dcera kněze ovdoví či bude zapuzená a nebude mít potomka a vrátí se do domu svého otce jako v mládí, může jíst z pokrmu svého otce. Ale nikdo cizí z toho jíst nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Jestliže by někdo jedl svaté věci nedopatřením, přidá k tomu pětinu a dá ty svaté věci knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Neznesvětí svaté dary synů Izraele, které Izraelci přinášejí Hospodinu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'takže by na ně uvalili ⌈trest za provinění,⌉ že jedli jejich svaté dary; neboť já jsem Hospodin, který je posvěcuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Promluv k Áronovi, k jeho synům a ke všem synům Izraele a řekni jim: Když bude kdokoliv z domu Izraele a z příchozích v Izraeli přinášet svůj obětní dar za jakýkoliv slib či jakoukoliv dobrovolnou oběť, která se Hospodinu přináší jako zápalná oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'abyste došli zalíbení, musí to být samec bez vady ze skotu, ovcí nebo koz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Nic, na čem je vada, nebudete přinášet, neboť byste nedošli zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Když někdo chce přinést Hospodinu obětní hod pokojné oběti jako splnění zvláštního slibu či jako dobrovolnou oběť ze skotu nebo bravu, bude to zvíře bez vady, abyste došli zalíbení; nebude na něm žádná vada.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Slepé nebo se zlomeninou nebo zmrzačené nebo s bradavicí nebo s hnisavou ranou nebo s lišejem, takové nepřinesete Hospodinu; z nich nebudete dávat ohnivé oběti Hospodinu na oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Býka nebo ovci s příliš dlouhými či zakrslými končetinami můžeš obětovat jako dobrovolnou oběť, ale jako splnění slibu nenajde zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Zvíře s rozmáčknutými, rozdrcenými, odtrženými či odříznutými varlaty nepřinesete Hospodinu; ve své zemi to nebudete dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Ani od cizince nepřinesete pokrm svému Bohu z ničeho takového, neboť je na nich poškození, je na nich vada, nezískají vám zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Když se narodí býček nebo jehně nebo kůzle, bude sedm dní pod svou matkou; od osmého dne a nadále získá zalíbení jako obětní dar ohnivé oběti pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Nezabijete krávu či ovci a s ní její mládě v jeden den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Když obětujete Hospodinu oběť díků, obětujte ji tak, abyste došli zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Ať se sní v ten den, neponechte z ní nic do rána. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Zachovávejte mé příkazy a plňte je. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Neznesvěcujte mé svaté jméno, abych byl posvěcen mezi syny Izraele. Já jsem Hospodin, který vás posvěcuji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'který jsem vás vyvedl z egyptské země, abych byl vaším Bohem. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Promluv k synům Izraele a řekni jim: Toto jsou Hospodinovy svátky, které budete svolávat, svatá shromáždění -- to jsou mé svátky:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Šest dní se bude vykonávat práce a sedmého dne je nejsvětější sobota, svaté shromáždění. Nebudete dělat žádnou práci, je to Hospodinova sobota ve všech vašich sídlech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Toto jsou Hospodinovy svátky, svatá shromáždění, která budete svolávat v jejich určený čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Prvního měsíce, čtrnáctého dne toho měsíce navečer je velikonoční oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Patnáctého dne toho měsíce je Hospodinův svátek nekvašených chlebů. Po sedm dní budete jíst nekvašené chleby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Prvního dne budete mít svaté shromáždění. Nebudete dělat žádnou ⌈všední práci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Po sedm dní budete přinášet Hospodinu ohnivé oběti; sedmého dne bude svaté shromáždění. Nebudete dělat žádnou všední práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Promluv k synům Izraele a řekni jim: Až vejdete do země, kterou vám dávám, a sklidíte její žeň, přinesete první snop ze své žně knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'On zamává snopem před Hospodinem, abyste došli zalíbení; druhého dne po sobotě s ním kněz zamává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'V den, kdy zamáváte snopem, připravíte ročního beránka bez vady jako zápalnou oběť Hospodinu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'a jako patřičnou přídavnou oběť dvě desetiny éfy jemné mouky namísené s olejem jako ohnivou oběť, příjemnou vůni Hospodinu, a jako patřičnou litou oběť čtvrtinu hínu vína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Chléb, pražené zrní ani čerstvé obilí nebudete jíst až do toho dne, kdy svému Bohu přinesete obětní dar. To je věčné ustanovení pro vaše generace ve všech vašich sídlech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Ode dne, kdy jste přinesli snop jako mávanou oběť, od druhého dne po sobotě si odpočítáte sedm týdnů. Musí být úplné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Spočítáte padesát dní až do druhého dne po sedmé sobotě a přinesete Hospodinu novou přídavnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Ze svých sídel přinesete dva chleby jako mávanou oběť; budou ze dvou desetin éfy jemné mouky, kvašené se budou péct jako prvotiny Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Spolu s chlebem přinesete sedm ročních beránků bez vady, jednoho býčka a dva berany. To bude zápalná oběť Hospodinu s patřičnou přídavnou a litou obětí, ohnivá oběť, příjemná vůně Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Připravíte též jednoho kozla jako oběť za hřích a dva roční beránky jako obětní hod pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Kněz s nimi zamává před Hospodinem spolu s chlebem z prvotin jako mávanou obětí, spolu s dvěma beránky. Budou svaté Hospodinu, pro kněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Právě v ten den svoláte a budete mít svaté shromáždění. Nebudete dělat žádnou všední práci. To je věčné ustanovení ve všech vašich sídlech pro vaše generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'A když budete sklízet žeň své země, nevyžínej zcela rohy svého pole a nesbírej klasy po své žni. Nech je pro chudého a příchozího. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Promluv k synům Izraele: Sedmého měsíce, prvního dne toho měsíce budete mít odpočinutí, památku troubení, svaté shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Nebudete dělat žádnou všední práci a přinesete Hospodinu ohnivé oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Desátého dne toho sedmého měsíce bude den smíření. Budete mít svaté shromáždění; budete pokořovat své duše a přinesete Hospodinu ohnivé oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Právě tohoto dne nebudete dělat žádnou práci, neboť je to den smíření, aby za vás byl vykonán obřad smíření před Hospodinem, vaším Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Neboť kdokoliv by se nepokořil právě toho dne, bude vyhlazen ze svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Kdokoliv by dělal jakoukoliv práci právě v ten den, toho odstraním zprostřed jeho lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nebudete dělat žádnou práci. To je věčné ustanovení pro vaše generace ve všech vašich sídlech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Je to pro vás nejsvětější sobota; budete pokořovat své duše. Večer devátého dne toho měsíce, od večera až do večera ⌈budete zachovávat svoji sobotu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Promluv k synům Izraele: Patnáctého dne sedmého měsíce je svátek stánků po sedm dní pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Prvního dne bude svaté shromáždění. Nebudete dělat žádnou všední práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Po sedm dní budete přinášet Hospodinu ohnivé oběti. Osmého dne budete mít svaté shromáždění a přinesete Hospodinu ohnivé oběti. Bude shromáždění, nebudete dělat žádnou všední práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Toto jsou Hospodinovy svátky, které budete svolávat jako svatá shromáždění, abyste přinášeli Hospodinu ohnivé oběti -- oběť zápalnou, oběť přídavnou, obětní hod a úlitby ⌈ podle každodenního určení,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'kromě Hospodinových sobot, kromě vašich darů, kromě všech vašich slíbených obětí a kromě všech vašich dobrovolných obětí, které dáváte Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Patnáctého dne sedmého měsíce, když seberete úrodu země, jistě budete slavit Hospodinův svátek po sedm dní. Prvního dne bude odpočinutí a osmého dne bude odpočinutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Prvního dne si vezmete plody ušlechtilých stromů, palmové ratolesti, větve listnatých stromů a potočních topolů a budete se radovat před Hospodinem, svým Bohem, po sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Budete jej slavit jako Hospodinův svátek po sedm dní v roce. To je věčné ustanovení pro vaše generace; v sedmém měsíci ho budete slavit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Ve stáncích budete bydlet po sedm dní; všichni domorodci v Izraeli budou bydlet ve stáncích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'aby vaše generace poznaly, že jsem nechal bydlet syny Izraele ve stanech, když jsem je vyvedl z egyptské země. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Tak Mojžíš vyhlásil synům Izraele Hospodinovy svátky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Přikaž synům Izraele, aby ti přinesli čistý panenský olivový olej ke svícení, aby se mohly trvale zapalovat lampy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Venku, před oponou svědectví, ve stanu setkávání je bude Áron trvale připravovat před Hospodinem od večera do rána. To je věčné ustanovení pro všechny vaše generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Na čistém svícnu bude trvale připravovat lampy před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Pak vezmeš jemnou mouku a napečeš z ní dvanáct bochníků; každý bochník bude ze dvou desetin éfy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Položíš je do dvou řad, šest v řadě, na čistý stůl před Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Vedle každé řady dáš čisté kadidlo a bude to u chleba jako pamětní dar, ohnivá oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, '⌈Sobotu co sobotu⌉ to bude trvale připravovat před Hospodinem; to je mezi syny Izraele věčná smlouva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Bude to patřit Áronovi a jeho synům a budou to jíst na svatém místě, protože to bude pro něj nejsvětější věc z Hospodinových ohnivých obětí; to je věčné ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Syn Izraelky, který byl synem Egypťana, vyšel mezi syny Izraele. A tento syn Izraelky a nějaký Izraelec se v táboře rvali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Syn Izraelky se rouhal Jménu a proklínal. Nato ho přivedli k Mojžíšovi. Jeho matka se jmenovala Šelomít, dcera Dibrího, z pokolení Danova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Nechali ho u stráže, aby zjistili rozhodnutí podle Hospodinova příkazu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Vyveď toho, kdo proklínal, ven za tábor. Všichni, kdo ho slyšeli, položí ruce na jeho hlavu a celá pospolitost ho ukamenuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'A k synům Izraele promluv: Každý, kdo by proklínal svého Boha, ponese trest za svůj hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'A ten, kdo se rouhá Hospodinovu jménu, bude jistě usmrcen; celá pospolitost ho jistě ukamenuje. Příchozí i domorodec, jestliže se rouhá Jménu, bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Když někdo zabije jakéhokoliv člověka, jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Kdo zabije zvíře, nahradí ho: život za život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Když někdo ⌈způsobí újmu⌉ svému druhovi, jak učinil, tak bude učiněno jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Zlomenina za zlomeninu, oko za oko, zub za zub; jakou újmu způsobil člověku, taková bude způsobena jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kdo zabije zvíře, nahradí ho; kdo zabije člověka, bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Budete mít jedno právo -- příchozí bude jako domorodec, neboť já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Mojžíš promluvil k synům Izraele a ti vyvedli toho, kdo proklínal, ven za tábor a házeli na něj kamení. Synové Izraele učinili tak, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Hospodin promluvil k Mojžíšovi na hoře Sínaj:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Promluv k synům Izraele a řekni jim: Až vejdete do země, kterou vám dávám, bude země zachovávat odpočinek pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Šest let budeš osévat své pole, šest let budeš prořezávat svou vinici a shromažďovat její úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Sedmého roku bude mít země ⌈sobotu odpočinutí,⌉ odpočinek pro Hospodina. Nebudeš osévat své pole ani prořezávat svou vinici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'To, co samo vyrostlo po tvé žni, nebudeš sklízet a hrozny ⌈z neobdělané vinice⌉ nebudeš sbírat. Země bude mít rok odpočinutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Úrodu z odpočinku země budete mít za pokrm -- ty, tvůj otrok, tvá otrokyně, tvůj najatý dělník i příchozí, který u tebe pobývá jako cizinec,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'tvůj dobytek i zvěř, která je v tvé zemi, bude mít k jídlu všechnu její úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Odpočítáš si sedm let odpočinku, sedmkrát sedm let, a doba sedm let odpočinku ti dá čtyřicet devět let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Necháš zaznít troubení beraního rohu sedmého měsíce, desátého dne toho měsíce. V den smíření necháte zaznít beraní roh po celé své zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Posvětíte ⌈padesátý rok⌉ a vyhlásíte v zemi propuštění pro všechny její obyvatele. Bude to pro vás ⌈milostivé léto,⌉ kdy se vrátíte každý na své vlastnictví, každý se vrátíte ke své čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Padesátý rok budete mít milostivé léto; nebudete zasévat, nebudete sklízet to, co samo vyroste, a nebudete sbírat víno z neobdělaných vinic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Neboť je to milostivé léto; bude pro vás svaté. Budete jíst úrodu přímo z pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'V tomto milostivém létě se vrátíte každý na své vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Když budete prodávat zboží svému druhovi nebo od svého druha něco kupovat, nebudete utiskovat ⌈jeden druhého.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Podle počtu roků po milostivém létě budeš kupovat od svého druha a podle počtu let úrody ti on bude prodávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, '⌈Čím více let, tím navýšíš jeho kupní cenu, čím méně let, tím zmenšíš jeho kupní cenu,⌉ neboť je to počet úrod, které ti prodává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Nebudete utiskovat ⌈jeden druhého,⌉ ale budeš se bát svého Boha, neboť já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Plňte má ustanovení, má nařízení zachovávejte a plňte je. Tak budete bydlet v zemi v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Země vydá své ovoce a budete jíst do sytosti a budete v ní bydlet v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'A když se zeptáte: Co budeme jíst v sedmém roce, když nebudeme zasévat ani sklízet svoji úrodu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Přikáži svému požehnání pro vás v šestém roce, takže vydá úrodu na tři roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Když budete zasévat v osmém roce, budete jíst ze staré úrody až do devátého roku; dokud nepřijde její úroda, budete jíst ze staré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Země se nebude prodávat natrvalo, protože země patří mně; vy jste u mě jen ⌈hosté a příchozí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'V celé zemi svého vlastnictví ustanovíte výkupní právo pro zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Když tvůj bratr zchudne a prodá něco ze svého vlastnictví, ať přijde jeho nejbližší příbuzný a vykoupí prodanou věc svého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Když někdo nemá příbuzného, ale ⌈nabude prostředky⌉ a ⌈získá dostatek⌉ k vykoupení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'spočítá roky od prodeje, vrátí zbytek muži, kterému to prodal, a vrátí se na své vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Pokud jeho prostředky nestačí na to, aby mu to vrátil, zůstane prodaná věc u kupujícího až do milostivého léta, ale v milostivém létě to uvolní a on se vrátí na své vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Když někdo prodá obytný dům ve městě s hradbami, jeho výkupní právo bude až do konce roku jeho prodeje; rok bude jeho výkupní právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Jestliže ho však nekoupí zpět dříve, nežli se naplní celý rok, zůstane dům, který je ve městě s hradbami, natrvalo kupujícímu, jemu i jeho pokolením; v milostivém létě nebude uvolněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Domy ve dvorcích, které nemají kolem sebe hradby, se budou počítat k polnostem země. Mají výkupní právo, v milostivém létě budou uvolněny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Města Lévijců, domy ve městech jejich vlastnictví, budou navždy výkupním právem Lévijců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Cokoliv by někdo z Lévijců nárokoval, bude to uvolněno -- prodej domu ve městě jeho vlastnictví -- v milostivém létě, neboť domy ve městech Lévijců jsou jejich vlastnictvím uprostřed synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Polnost pastviny u jejich měst se však nebude prodávat, neboť je jejich věčným vlastnictvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Když tvůj bratr zchudne a ⌈nedostává se mu prostředků vůči tobě,⌉ ujmi se ho jako hosta či příchozího, ať žije u tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Neber od něj lichvu ani úrok, ale boj se svého Boha; tvůj bratr ať žije u tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Své stříbro mu nedávej na lichvu ani své jídlo za příplatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Já Hospodin jsem váš Bůh, který jsem vás vyvedl z egyptské země, abych vám dal kenaanskou zemi a byl vaším Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Když tvůj bratr u tebe zchudne a prodá se ti, nezotročuj ho otrockou prací.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Bude u tebe jako najatý dělník či příchozí; bude u tebe sloužit až do milostivého léta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Pak od tebe odejde, on i jeho synové s ním, a vrátí se ke své čeledi, vrátí se k vlastnictví svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Jsou to moji otroci, které jsem vyvedl z egyptské země. Nebudou prodáváni ⌈ jako se prodávají⌉ otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Nebudeš nad ním panovat surově, ale budeš se bát svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Svého otroka a svou otrokyni, které budeš mít, -- od národů, které jsou okolo vás, od nich můžete kupovat otroky a otrokyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'I od synů příchozích, kteří s vámi pobývají jako cizinci, od nich můžete kupovat i od jejich rodin, které jsou s vámi, které oni zplodili ve vaší zemi; a budou vaším vlastnictvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Můžete je rozdělit do dědictví pro své syny po sobě jako dědičné vlastnictví; je můžete navždy zotročit. Ale nad svými bratry, syny Izraele, jeden nad druhým nebudeš panovat surově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Když host či příchozí u tebe ⌈nabude prostředků⌉ a tvůj bratr u něj zchudne a prodá se hostu či příchozímu u tebe nebo potomku z čeledi hosta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'poté, co se prodal, bude mít výkupní právo. Někdo z jeho bratrů jej vykoupí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'nebo jeho strýc či syn jeho strýce ho vykoupí nebo někdo z jeho pokrevních příbuzných, z jeho rodiny ho vykoupí; nebo když ⌈nabude prostředků,⌉ vykoupí se sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'S tím, kdo ho koupil, spočítá dobu od roku, kdy se mu prodal, až do milostivého léta a ⌈jeho prodejní cena⌉ bude podle počtu let, jako by byl v té době u něj najatým dělníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Pokud je ještě mnoho let, vrátí podle nich jeho výkupné z ⌈jeho kupní ceny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Jestliže zůstává málo let do milostivého léta, spočítá to s ním a podle jeho let vrátí své výkupné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Jako dělník najatý z roku na rok bude u něj; nebude nad ním panovat surově ⌈ze tvého pohledu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Pokud nebude takto vykoupen, bude uvolněn v milostivém létě, on i jeho synové s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Neboť synové Izraele jsou moji otroci; jsou to moji otroci, které jsem vyvedl z egyptské země. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Nedělejte si nicotnosti ani tesané modly, nestavte si posvátné sloupy ani si nepokládejte ve své zemi ⌈kamenné obrazy,⌉ abyste se jim klaněli. Neboť já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Zachovávejte mé soboty a mějte v úctě mou svatyni. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Jestliže budete žít podle mých ustanovení, zachovávat mé příkazy a plnit je,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'dám vám deště v jejich čas, země vydá svou úrodu a polní stromy vydají své ovoce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'výmlat u vás dosáhne až k vinobraní a vinobraní dosáhne až k setbě. Budete jíst chléb svůj do sytosti a budete bydlet ve své zemi v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Dám v zemi pokoj, ulehnete a nikdo vás nevyděsí. Způsobím, že ze země zmizí divá zvěř a meč nebude procházet vaší zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Budete pronásledovat své nepřátele a padnou před vámi mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Pět z vás bude pronásledovat sto a sto z vás bude pronásledovat deset tisíc. Vaši nepřátelé padnou před vámi mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Obrátím se k vám, rozplodím vás a rozmnožím a ustanovím s vámi svou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Budete jíst staré, dlouho uložené zrno a staré budete vyklízet před novým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Učiním si mezi vámi příbytek a má duše si vás nezoškliví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Budu se mezi vámi procházet, budu vaším Bohem a vy budete mým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Já Hospodin jsem váš Bůh, který jsem vás vyvedl z egyptské země, abyste již nebyli jejich otroky. Zlomil jsem kolíky vašeho jha a dal jsem vám chodit zpříma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Jestliže mě však nebudete poslouchat a nebudete plnit všechny tyto příkazy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'jestliže zavrhnete má ustanovení a vaše duše si zoškliví má nařízení, takže nebudete plnit všechny mé příkazy a porušíte mou smlouvu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'tak já naložím s vámi takto: Ustanovím nad vámi děs, úbytě a horečku, která hubí oči a stravuje život. Zasejete své semeno zbytečně -- pohltí to vaši nepřátelé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Obrátím svou tvář proti vám, budete poraženi od svých nepřátel; ti, kdo vás nenávidí, budou nad vámi panovat a budete utíkat, i když vás nikdo nebude honit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Jestliže mě ani potom nebudete poslouchat, budu vás dále káznit sedminásobně za vaše hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Zlomím vaši silnou pýchu a učiním vaše nebe jako ze železa a vaši zemi jako z bronzu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'takže vaše síla vyjde naprázdno. Vaše země nevydá svou úrodu a stromy země nevydají své ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Jestliže ⌈se budete vůči mně stavět nepřátelsky⌉ a nebudete mě chtít poslouchat, přidám vám sedminásobně ran podle vašich hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Pošlu na vás polní zvěř a ta vás učiní bezdětnými, vyhladí váš dobytek a bude vás umenšovat, takže vaše cesty budou zpustošeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Jestliže se ani tím nedáte ode mě pokárat a budete se vůči mně stavět nepřátelsky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'také já se budu vůči vám stavět nepřátelsky, ano, zasáhnu vás sedminásobně za vaše hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Přivedu na vás meč pomsty, který pomstí smlouvu. Shromáždíte–li se do svých měst, pošlu do vašeho středu mor a budete vydáni do ruky nepřítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Když vám zlomím hůl chleba, deset žen vám bude péct chléb v jedné peci a přinesou vám zpět chléb na váhu, takže budete jíst, ale nenasytíte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Jestliže mě ani potom nebudete poslouchat a budete se vůči mně stavět nepřátelsky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'budu se i já vůči vám stavět nepřátelsky a s hněvem, ano, budu vás kárat sedminásobně za vaše hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Budete jíst maso svých synů a budete jíst maso svých dcer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Zničím vaše návrší, vyhladím vaše kadidlové oltáře, na mrtvoly vašich bůžků položím vaše mrtvoly a má duše si vás zoškliví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Vaše města proměním v trosky, zpustoším vaše svatyně a ⌈nebudu moci cítit vaši příjemnou vůni.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Zpustoším zemi, takže se jí budou hrozit vaši nepřátelé, kteří v ní budou bydlet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Rozptýlím vás mezi národy, vytasím za vámi meč, vaše země se stane pustinou a vaše města se stanou troskami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Tehdy si země vynahradí svůj odpočinek, po celou dobu svého zpustošení, kdy vy budete v zemi svých nepřátel. Tehdy země odpočine a vynahradí si svůj odpočinek');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'po celou dobu svého zpustošení bude odpočívat tak, jak neodpočívala o vašich sobotách, když jste v ní sídlili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, '⌈Co se týče⌉ těch, kdo z vás zůstanou, přivedu v zemích jejich nepřátel malomyslnost do jejich srdcí, takže je zažene zvuk odvátého listí; budou utíkat jako se utíká před mečem, padnou, i když je nikdo nebude honit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Budou klopýtat jeden přes druhého, jako se klopýtá před mečem, i když je nikdo nebude honit. Nebudete mít sílu obstát před svými nepřáteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Zahynete mezi národy, země vašich nepřátel vás pohltí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'A ti, kdo z vás zůstanou, budou chřadnout pro své provinění v zemích svých nepřátel a také pro provinění svých otců budou chřadnout spolu s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Jestliže však vyznají vinu svou a vinu svých otců, svou věrolomnost, kterou se zpronevěřili vůči mně, takže se vůči mně stavěli nepřátelsky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, '(také já jsem se stavěl vůči nim nepřátelsky a přivedl jsem je do země jejich nepřátel), tehdy se jejich neobřezané srdce pokoří a tehdy vynahradí své provinění,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'a já budu pamatovat na svou smlouvu s Jákobem. I na svou smlouvu s Izákem i na svou smlouvu s Abrahamem budu pamatovat a na zemi budu pamatovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Země bude jimi opuštěna, vynahradí si svůj odpočinek, když bude zpustošena, bez nich, a oni si vynahradí své provinění právě proto, že zavrhli má nařízení a jejich duše si zošklivila má ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Ale i přesto, že budou v zemi svých nepřátel, nezavrhnu je a nezošklivím si je zcela, takže bych porušil svou smlouvu s nimi, neboť já Hospodin jsem jejich Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Budu kvůli nim pamatovat na smlouvu s jejich předky, které jsem vyvedl z egyptské země před zraky národů, abych byl jejich Bohem. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Toto jsou ustanovení, nařízení a zákony, které ustanovil Hospodin mezi sebou a syny Izraele na hoře Sínaj prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Promluv k synům Izraele a řekni jim: Když někdo učiní zvláštní slib a zasvětí Hospodinu duše podle tvého výměru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'bude tvůj výměr tento: za muže ve věku od dvaceti let do věku šedesáti let bude tvůj výměr padesát šekelů stříbra podle šekelu svatyně;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'pokud je to žena, bude tvůj výměr třicet šekelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Pokud je ve věku od pěti let do dvaceti let, bude tvůj výměr za muže dvacet šekelů a za ženu deset šekelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Pokud je ve věku od měsíce do pěti let, bude tvůj výměr za muže pět šekelů stříbra a za ženu bude tvůj výměr tři šekely stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Pokud je ve věku od šedesáti let výše, bude tvůj výměr za muže patnáct šekelů a za ženu deset šekelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Pokud je zchudlý a nestačí na tvůj výměr, postaví ho před kněze a kněz ⌈mu vyměří jeho zasvěcení.⌉ Kněz mu vyměří podle toho, na co stačí prostředky toho, kdo učinil slib.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Pokud je to zvíře, které ⌈se přináší⌉ Hospodinu jako obětní dar, všechno, co se z něj dává Hospodinu, bude svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Nenahradí ho ani ho nezamění dobré za špatné ani špatné za dobré. Pokud by přece zaměnil zvíře za zvíře, bude svaté to první i vyměněné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Pokud je to jakékoliv zvíře nečisté, které se nepřináší jako obětní dar Hospodinu, postaví to zvíře před kněze');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'a kněz to vyměří, ⌈jestli je dobré či špatné.⌉ Jak to kněz vyměří, tak to bude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, '⌈Pokud by ho chtěl vykoupit,⌉ přidá k výměru jednu pětinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Když někdo zasvětí svůj dům jako svatý Hospodinu, kněz ho vyměří, jestli je dobrý či špatný. Jak to kněz vyměří, tak to zůstane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Pokud by ten, kdo ho zasvětil, chtěl svůj dům vykoupit, přidá pětinu ⌈k jeho vyměřené ceně⌉ a bude jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Pokud někdo zasvětí Hospodinu pole ze svého vlastnictví, bude tvůj výměr podle zrna k jeho osetí: plocha osetá chómerem ječmene bude za padesát šekelů stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Jestliže zasvětí své pole od milostivého léta, zůstane to podle tvého výměru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Pokud zasvětí své pole po milostivém létě, spočítá mu kněz cenu podle let zbývajících do milostivého léta a bude to ubráno z výměru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Pokud by ten, kdo ho zasvětil, ⌈chtěl pole vykoupit,⌉ přidá pětinu k jeho vyměřené ceně a připadne jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Jestliže však pole nevykoupí, a prodá pole někomu jinému, nebude ho moci již vykoupit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Pole uvolněné v milostivém létě se stane svaté pro Hospodina, stejně jako pole, které bylo zasvěceno zkáze; stane se vlastnictvím kněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Pokud někdo zasvětí Hospodinu pole koupené, které není polem z jeho vlastnictví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'kněz mu spočítá hodnotu výměru až do milostivého léta a ještě v ten den dá ten výměr jako svatou věc Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'V milostivém létě se vrátí pole tomu, od koho jej koupil, jehož vlastnictvím země byla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Každý tvůj výměr bude v šekelech svatyně. Dvacet gér bude jeden šekel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Avšak prvorozené ze zvířat, které jako prvorozené patří Hospodinu, nikdo nemůže zasvětit; ať býk či ovce, patří Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Pokud je to z nečistého zvířete, může být vykoupeno podle tvého výměru a přidá se k tomu pětina. Pokud nebude vykoupeno, prodá se podle tvého výměru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Avšak nic zasvěceného zkáze, co někdo zasvětil zkáze pro Hospodina, nic z toho, co někdo má, ať člověk, zvíře či pole jeho vlastnictví, nebude moci být prodáno ani vykoupeno. Cokoliv zasvěcené zkáze je nejsvětější věcí pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Nikdo z lidí zasvěcených zkáze nebude moci být vykoupen; jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Celý desátek země, ať ze semena země či z ovoce stromů, patří Hospodinu. Je to svatá věc pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Pokud by někdo chtěl vykoupit něco ze svého desátku, přidá k tomu pětinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Celý desátek ze skotu a bravu, všechno, co prochází pod pastýřskou holí, každý desátý bude svatou věcí pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Nebude se zkoumat, jestli je dobrý či špatný, ani ho nezamění. Pokud by jej přece zaměnil, bude svatý ten první i vyměněný. Nemůže to být vykoupeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Toto jsou příkazy, které dal Hospodin Mojžíšovi pro syny Izraele na hoře Sínaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, '⌈Hospodin promluvil k Mojžíšovi⌉ v Sínajské pustině ve stanu setkávání prvního dne druhého měsíce ve druhém roce po jejich vyjití z egyptské země:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '⌈Učiňte soupis⌉ celé pospolitosti synů Izraele podle jejich čeledí, podle ⌈domu jejich otců,⌉ podle ⌈počtu jmen všech mužského pohlaví, hlavu za hlavou,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'od věku dvaceti let výše, všech v Izraeli schopných táhnout s armádou. Spočítejte je podle jejich oddílů, ty a Áron.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'S vámi bude vždy jeden muž za pokolení, ten, který je předákem v domě svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Toto jsou jména mužů, kteří povstanou s vámi: za Rúbena Elísúr, syn Šedeúrův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'za Šimeóna Šelumíel, syn Suríšadajův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'za Judu Nachšón, syn Amínadabův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'za Isachara Netanel, syn Súarův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'za Zabulóna Elíab, syn Chelónův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'za syny Josefovy, za Efrajima Elíšama, syn Amíhudův, za Manasesa Gamlíel, syn Pedásurův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'za Benjamína Abídan, syn Gideoního;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'za Dana Achíezer, syn Amíšadajův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'za Ašera Pagíel, syn Okranův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'za Gáda Eljásaf, syn Deúelův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'za Neftalího Achíra, syn Énanův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Toto byli povolaní z pospolitosti, předáci otcovských pokolení, vůdci izraelských rodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Mojžíš a Áron vzali tyto muže, kteří byli jmenovitě určeni,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'a prvního dne druhého měsíce svolali celou pospolitost a lidé se dávali zapsat podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, hlava za hlavou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'jak přikázal Hospodin Mojžíšovi. Spočítal je v Sínajské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, '⌈ Výsledek byl tento:⌉ synové Rúbena, Izraelova prvorozeného, byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen, hlava za hlavou, všichni mužského pohlaví od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'spočítaných z pokolení Rúbenova bylo čtyřicet šest tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Synové Šimeónovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, spočítaní podle počtu jmen, hlava za hlavou, všichni mužského pohlaví od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'spočítaných z pokolení Šimeónova bylo padesát devět tisíc tři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Synové Gádovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'spočítaných z pokolení Gádova bylo čtyřicet pět tisíc šest set padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Synové Judovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'spočítaných z pokolení Judova bylo sedmdesát čtyři tisíc šest set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Synové Isacharovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'spočítaných z pokolení Isacharova bylo padesát čtyři tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Synové Zabulónovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'spočítaných z pokolení Zabulónova bylo padesát sedm tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Synové Josefovi: Synové Efrajimovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'spočítaných z pokolení Efrajimova bylo čtyřicet tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Synové Manasesovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'spočítaných z pokolení Manasesova bylo třicet dva tisíc dvě stě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Synové Benjamínovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'spočítaných z pokolení Benjamínova bylo třicet pět tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Synové Danovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'spočítaných z pokolení Danova bylo šedesát dva tisíc sedm set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Synové Ašerovi byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'spočítaných z pokolení Ašerova bylo čtyřicet jeden tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Synové Neftalího byli uvedeni ve svých rodopisech podle svých čeledí, podle domu svých otců, podle počtu jmen od věku dvaceti let výše, všichni schopní táhnout s armádou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'spočítaných z pokolení Neftalího bylo padesát tři tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Toto jsou ti, kdo byli spočítáni, které spočítali Mojžíš a Áron a izraelští předáci, dvanáct mužů; jeden muž byl vždy za dům svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'To byli všichni spočítaní synové Izraele podle domu svých otců od věku dvaceti let výše, všichni schopní v Izraeli táhnout s armádou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Všech spočítaných bylo šest set tři tisíc pět set padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Avšak Lévijci podle pokolení svých otců nebyli mezi ně počítáni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Pouze pokolení Léviho nepočítej a nečiň jejich soupis mezi syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Nýbrž ustanov Lévijce nad příbytkem svědectví, nad všemi jeho předměty a nade vším, co k němu patří. Oni budou nosit příbytek a všechny jeho předměty, ⌈budou v něm konat bohoslužbu⌉ a budou tábořit kolem příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Když bude mít příbytek vyrazit na cestu, Lévijci ho složí, a když bude mít příbytek tábořit, Lévijci ho postaví. Když by se přiblížil někdo jiný, bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Synové Izraele budou tábořit každý ve svém táboře, každý pod svou zástavou podle svých oddílů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Avšak Lévijci ať táboří kolem příbytku svědectví, aby na pospolitost synů Izraele nedopadlo rozhořčení. Lévijci budou konat službu příbytku svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Synové Izraele učinili všechno tak, jak přikázal Hospodin Mojžíšovi. Tak to učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Synové Izraele budou tábořit každý pod svou zástavou, podle znamení domu svých otců; budou tábořit stranou kolem stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, '⌈Na východě, k východu slunce,⌉ bude tábořit zástava tábora Judova podle jejich oddílů. Předákem synů Judových bude Nachšón, syn Amínadabův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, '⌈Spočítaných v jeho oddílech je sedmdesát⌉ čtyři tisíc šest set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Vedle něj bude tábořit pokolení Isacharovo. Předákem synů Isacharových bude Netanel, syn Súarův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Spočítaných v jeho oddílech je padesát čtyři tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Pokolení Zabulónovo. Předákem synů Zabulónových bude Elíab, syn Chelónův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Spočítaných v jeho oddílech je padesát sedm tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Všech spočítaných v táboře Judejců podle jejich oddílů je sto osmdesát šest tisíc čtyři sta. Vyrazí jako první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Na jihu bude zástava tábora Rúbenova podle jejich oddílů. Předákem synů Rúbenových bude Elísúr, syn Šedeúrův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Spočítaných v jeho oddílech je čtyřicet šest tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Vedle něj bude tábořit pokolení Šimeónovo. Předákem synů Šimeónových je Šelumíel, syn Suríšadajův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Spočítaných v jeho oddílech je padesát devět tisíc tři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Pokolení Gádovo. Předákem synů Gádových bude Eljásaf, syn Reúelův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Spočítaných v jeho oddílech je čtyřicet pět tisíc šest set padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Všech spočítaných v táboře Rúbenovců podle jejich oddílů je sto padesát jedna tisíc čtyři sta padesát. Vyrazí jako druzí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Potom vyrazí stan setkávání, tábor Lévijců, mezi tábory. Jak budou tábořit, tak vyrazí, jeden vedle druhého, podle svých zástav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Na západě bude zástava tábora Efrajimova podle jejich oddílů. Předákem synů Efrajimových bude Elíšama, syn Amíhudův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Spočítaných v jeho oddílech je čtyřicet tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Vedle něj bude pokolení Manasesovo. Předákem synů Manasesových bude Gamlíel, syn Pedásurův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Spočítaných v jeho oddílech je třicet dva tisíc dvě stě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Pokolení Benjamínovo. Předákem synů Benjamínových bude Abídan, syn Gideoního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Spočítaných v jeho oddílech je třicet pět tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Všech spočítaných v táboře Efrajimově podle jejich oddílů je sto osm tisíc jedno sto. Vyrazí jako třetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Na severu bude zástava tábora Danova podle jejich oddílů. Předákem synů Danových bude Achíezer, syn Amíšadajův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Spočítaných v jejich oddílech je šedesát dva tisíc sedm set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Vedle něj bude tábořit pokolení Ašerovo. Předákem synů Ašerových bude Pagíel, syn Okranův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Spočítaných v jeho oddílech je čtyřicet jeden tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Pokolení Neftalího. Předákem synů Neftalího bude Achíra, syn Énanův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Spočítaných v jeho oddílech je padesát tři tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Všech spočítaných v táboře Danově je sto padesát sedm tisíc šest set. Vyrazí jako poslední podle svých zástav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Toto jsou spočítaní synové Izraele podle domu svých otců. Všech spočítaných v táborech podle jejich oddílů bylo šest set tři tisíc pět set padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Lévijci však nebyli počítáni mezi syny Izraele, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Synové Izraele učinili všechno tak, jak přikázal Hospodin Mojžíšovi. Tak tábořili podle svých zástav a tak vyráželi každý podle své čeledi, podle domu svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Toto je rodopis Árona a Mojžíše, ⌈tehdy, když⌉ Hospodin promluvil k Mojžíšovi na hoře Sínaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Toto jsou jména synů Áronových: prvorozený Nádab, dále Abíhú, Eleazar a Ítamar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Toto jsou jména synů Áronových, pomazaných kněží, které zasvětil, aby sloužili jako kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nádab a Abíhú zemřeli před Hospodinem, když přinesli v Sínajské pustině před Hospodina cizí oheň. Syny neměli. Jako kněží tedy sloužili v přítomnosti svého otce Árona Eleazar a Ítamar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Předveď pokolení Léviho a postav ho před kněze Árona, aby mu sloužili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Budou ⌈konat službu pro něj a pro celou pospolitost⌉ před stanem setkávání a vykonávat službu příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Budou dbát na všechny předměty stanu setkávání a službu synů Izraele a vykonávat službu příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Dej Lévijce Áronovi a jeho synům; budou mu zcela darováni od synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Árona a jeho syny ustanov, aby dbali na své kněžství. Když by se přiblížil někdo jiný, bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Hle, vzal jsem Lévijce zprostřed synů Izraele namísto všech prvorozených, otvírajících lůno, mezi syny Izraele. Lévijci budou patřit mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Neboť mně patří všechno prvorozené. Tehdy, když jsem v egyptské zemi pobil všechno prvorozené, zasvětil jsem pro sebe všechno prvorozené v Izraeli, ⌈člověka i zvíře.⌉ Budou patřit mně. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Hospodin promluvil k Mojžíšovi v Sínajské pustině:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Spočítej syny Léviho podle domu jejich otců, podle jejich čeledí. Spočítej všechny mužského pohlaví od věku jednoho měsíce výše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Mojžíš je tedy spočítal podle Hospodinova příkazu, jak mu bylo přikázáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Toto byli synové Léviho podle svých jmen: Geršón, Kehat a Merarí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Toto jsou jména synů Geršónových podle jejich čeledí: Libní a Šimeí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Synové Kehatovi podle svých čeledí: Amrám, Jishár, Chebrón a Uzíel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Synové Merarího podle svých čeledí: Machlí a Muší. Toto jsou čeledi Léviho podle domu svých otců:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Geršónovi patřila čeleď Libního a čeleď Šimeího. To jsou čeledi Geršónovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Spočítaných podle počtu všech mužského pohlaví od věku jednoho měsíce výše, spočítaných bylo sedm tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Geršónské čeledi tábořily za příbytkem na západě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Předákem domu otce Geršónovců byl Eljásaf, syn Láelův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, '⌈Služba synů Geršónových ve stanu setkávání zahrnovala ⌉ příbytek, stan, jeho přikrývku a oponu vchodu do stanu setkávání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'i závěsy nádvoří, oponu vchodu do nádvoří, které je kolem příbytku a oltáře, a jeho lana pro všechnu práci ⌈ kolem toho.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Kehatovi patřila čeleď Amrámců, čeleď Jishárců, čeleď Chebrónců a čeleď Ozíelců. Toto jsou čeledi Kehatovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Počet všech mužského pohlaví od věku jednoho měsíce výše byl osm tisíc šest set těch, kteří konali službu při svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Čeledi synů Kehatových tábořily na jižní straně příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Předákem domu otce čeledí Kehatovců byl Elísáfan, syn Uzíelův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Jejich služba zahrnovala truhlu, stůl, svícen, oltáře a předměty svatyně, s kterými konali bohoslužbu, oponu a všechnu práci ⌈ kolem toho.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Předákem lévijských předáků byl kněz Eleazar, syn Áronův; dohlížel nad těmi, kteří konali službu při svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Merarímu patřila čeleď Machlího a čeleď Mušího. Toto jsou čeledi Meraríjců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Spočítaných podle počtu všech mužského pohlaví od věku jednoho měsíce výše bylo šest tisíc dvě stě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Předákem domu otce čeledí Merarího byl Súríel, syn Abíchajilův. Tábořily na severní straně příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Povinnost služby synů Merarího zahrnovala desky příbytku, jeho závory, jeho sloupy, jeho podstavce, všechny jeho předměty a všechnu práci kolem toho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'sloupy kolem nádvoří, jejich podstavce, kolíky a lana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Před příbytkem na východě, před stanem setkávání k východu slunce, tábořili Mojžíš a Áron i jeho synové, kteří konali službu při svatyni jako službu synů Izraele. Když by se přiblížil někdo jiný, měl být usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Všech spočítaných Lévijců, které spočítal Mojžíš a Áron na Hospodinův příkaz podle jejich čeledí, všech mužského pohlaví od věku jednoho měsíce výše bylo dvacet dva tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Hospodin řekl Mojžíšovi: Spočítej všechny prvorozené mužského pohlaví mezi syny Izraele od věku jednoho měsíce výše a učiň jejich jmenovitý výčet');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'a vezmi Lévijce pro mne -- já jsem Hospodin -- namísto všech prvorozených mezi syny Izraele i dobytek Lévijců namísto všech prvorozených mezi dobytkem synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Mojžíš spočítal všechny prvorozené mezi syny Izraele, jak mu Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Jmenovitý počet všech prvorozených mužského pohlaví od věku jednoho měsíce výše, jak byli spočítáni, byl dvacet dva tisíc dvě stě sedmdesát tři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Vezmi Lévijce namísto všech prvorozených mezi syny Izraele i dobytek Lévijců namísto jejich dobytka. Lévijci budou patřit mně. Já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Jako výkupné za těch dvě stě sedmdesát tři, kteří mezi syny Izraele přebývají nad Lévijce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'vyber ⌈po pěti⌉ šekelech na hlavu; vyber to podle šekelu svatyně, dvacet gér na šekel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Dej to stříbro Áronovi a jeho synům jako výkupné za ty, kteří přebývají nad jejich počet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Mojžíš vybral stříbro jako výkupné od těch, kteří přebývali nad ⌈vykoupené Lévijci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Od prvorozených synů Izraele vybral stříbro, tisíc tři sta šedesát pět šekelů podle šekelu svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Mojžíš pak dal výkupné stříbro Áronovi a jeho synům podle Hospodinova příkazu, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '⌈Učiň soupis⌉ synů Kehatových mezi syny Léviho podle jejich čeledí podle domu jejich otců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'od věku třiceti let výše až do věku padesáti let, všech, kteří přicházejí do služby, aby konali práci při stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Toto bude služba synů Kehatových při stanu setkávání: ⌈nejsvětější věci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Když bude mít tábor vyrazit na cestu, vejde Áron a jeho synové, sundají zakrývající oponu a přikryjí s ní truhlu svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Dají na ni přikrývku z tachaší kůže, nahoře rozprostřou pokrývku celou z modré příze a vloží její tyče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Na stůl pro předkladné chleby rozprostřou pokrývku z modré příze a dají na něj mísy, kadidlové pánvičky, obětní misky a konve pro lité oběti; chléb ať je na něm ustavičně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Rozprostřou na to karmínovou pokrývku, přikryjí ho přikrývkou z tachaší kůže a vloží jeho tyče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Potom vezmou pokrývku z modré příze, přikryjí svícen ke svícení, jeho lampy, jeho kleště, jeho pánvičky na uhlíky a všechny nádoby na olej, s kterými při něm konají bohoslužbu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'dají ho i všechny jeho předměty na přikrývku z tachaší kůže a dají na nosítka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Na zlatý oltář rozprostřou pokrývku z modré příze, přikryjí ho přikrývkou z tachaší kůže a vloží jeho tyče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Vezmou všechny ⌈předměty pro bohoslužbu,⌉ se kterými slouží ve svatyni, dají na pokrývku z modré příze, přikryjí je přikrývkou z tachaší kůže a dají na nosítka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, '⌈Očistí oltář od popela⌉ a rozprostřou na něj purpurovou pokrývku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Dají na něj všechny jeho předměty, se kterými na něm konají bohoslužbu -- pánvičky na uhlíky, vidlice, lopaty, misky a všechny oltářní předměty -- rozprostřou na něj přikrývku z tachaší kůže a vloží jeho tyče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Když Áron a jeho synové dokončí přikrývání svatyně a všech předmětů svatyně, když bude mít tábor vyrazit na cestu, potom přijdou synové Kehatovi, aby to nesli. Nedotknou se svatých věcí, aby ne zemřeli. ⌈Toto budou⌉ nosit synové Kehatovi ve stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Kněz Eleazar, syn Áronův, bude dohlížet na olej ke svícení, vonné kadidlo, ustavičnou přídavnou oběť a olej pomazání; bude dohlížet na celý příbytek a vše, co je v něm, na svatyni i její předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Nenechte vyhladit kmen čeledí Kehatovců zprostřed Lévijců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Takto s nimi jednejte a zůstanou naživu, nezemřou, když by se přiblížili k nejsvětějším věcem: Áron a jeho synové přijdou a ustanoví jednoho každého do jeho služby a jeho nošení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Kehatovci však ať nevejdou, aby se dívali během přikrývání svatých věcí, jinak zemřou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Učiň také soupis synů Geršónových podle domu jejich otců podle jejich čeledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Spočítej je od věku třiceti let výše až do věku padesáti let, všechny, kteří přicházejí konat službu, vykonávat službu ve stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Toto bude služba geršónských čeledí při službě a nošení:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Budou nosit stanové plachty příbytku, stan setkávání, jeho přikrývku a tachaší přikrývku, která je na něm nahoře, oponu vchodu do stanu setkávání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'závěsy nádvoří i oponu brány do nádvoří, které je kolem příbytku a oltáře, jeho lana a všechny předměty k práci s nimi; ať konají všechno, co ⌈se s nimi dělá.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Všechna služba synů Geršónových při všem jejich nošení a při vší jejich službě bude vykonávána podle příkazu Árona a jeho synů. Ustanovte je do služby všeho jejich nošení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Toto bude služba čeledí synů Geršónových ve stanu setkávání. Jejich služba bude pod vedením kněze Ítamara, syna Áronova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Spočítej syny Merarího podle jejich čeledí podle domu jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Spočítej je od věku třiceti let výše až do věku padesáti let, všechny, kteří přicházejí do služby, aby vykonávali službu při stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Toto bude služba jejich nošení při vší jejich službě ve stanu setkávání: desky příbytku a jeho závory, jeho sloupy a podstavce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'sloupy okolního nádvoří, jejich podstavce, jejich kolíky a lana spolu se všemi jejich předměty a vší jejich službou. Jmenovitě určete předměty služby jejich nošení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Toto bude služba čeledí synů Merarího při vší jejich službě ve stanu setkávání pod vedením kněze Ítamara, syna Áronova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Mojžíš, Áron a předáci pospolitost spočítali syny Kehatovy podle jejich čeledí a podle domu jejich otců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'od věku třiceti let výše až do věku padesáti let, všechny, kteří přicházejí do služby a práce ve stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Spočítaných podle jejich čeledí bylo dva tisíce sedm set padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Toto byli spočítaní z čeledí Kehatových, všichni, kdo sloužili ve stanu setkávání, které spočítali Mojžíš a Áron podle Hospodinova příkazu prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Spočítaní ze synů Geršónových podle jejich čeledí a podle domu jejich otců');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'od věku třiceti let výše až do věku padesáti let, všichni, kteří přicházejí do služby a práce ve stanu setkávání:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Spočítaných podle jejich čeledí a podle domu jejich otců bylo dva tisíce šest set třicet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Toto byli spočítaní z čeledí synů Geršónových, všichni, kdo sloužili ve stanu setkávání, které spočítali Mojžíš a Áron podle Hospodinova příkazu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Spočítaní z čeledí synů Merarího podle jejich čeledí a podle domu jejich otců');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'od věku třiceti let výše až do věku padesáti let, všichni, kteří přicházejí do služby a práce ve stanu setkávání:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Spočítaných podle jejich čeledí bylo tři tisíce dvě stě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Toto byli spočítaní z čeledí synů Merarího, které spočítali Mojžíš a Áron podle Hospodinova příkazu prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Všech spočítaných, které spočítali Mojžíš, Áron a předáci Izraele, Lévijců podle jejich čeledí a podle domu jejich otců');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'od věku třiceti let výše až do věku padesáti let, všech, kteří přicházejí vykonávat ⌈jednotlivé služby⌉ a službu nošení ve stanu setkávání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'spočítaných bylo osm tisíc pět set osmdesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Spočítal je podle Hospodinova příkazu prostřednictvím Mojžíše jednoho každého podle jeho služby a jeho nošení; spočítal je, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Přikaž synům Izraele, aby poslali pryč z tábora všechny postižené malomocenstvím, všechny trpící výtokem a všechny, kteří jsou nečistí kvůli mrtvému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Pošlete pryč ⌈muže i ženu,⌉ pošlete je ven z tábora, aby neznečišťovali své tábory, uprostřed nichž já přebývám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Synové Izraele to udělali a poslali je ven z tábora. Jak promluvil Hospodin k Mojžíšovi, tak synové Izraele udělali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Promluv k synům Izraele: Když muž či žena spáchají ⌈nějaký hřích⌉ proti člověku a zpronevěří se vůči Hospodinu věrolomností, takový člověk ponese vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Musí vyznat svůj hřích, který spáchal, ⌈to, čím se provinil, doposledka vrátit,⌉ přidat k tomu pětinu a dát tomu, proti komu se provinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Jestliže ten muž nemá příbuzného, kterému by vrátil to, čím se provinil, bude to vráceno Hospodinu pro kněze -- kromě berana smíření, s nímž bude za něj vykonán obřad smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Každý dar pozdvihování ze všech svatých darů synů Izraele, který přinesou knězi, bude patřit jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Svaté dary od kohokoliv budou patřit jemu; co kdo dá knězi, bude patřit jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Promluv k synům Izraele a řekni jim: Kdyby žena nějakého muže sešla na scestí a zpronevěřila se vůči němu věrolomností,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'takže by s ní ležel muž a došlo k výronu semene, ale bylo by to skryto před očima jejího muže, zůstala by ukryta, ačkoliv se poskvrnila, protože proti ní nebyl svědek a nebyla chycena,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'jestliže na muže přijde žárlivost, vzplane žárlivostí vůči své ženě a ona se poskvrnila anebo na něj přijde žárlivost, vzplane žárlivostí vůči své ženě, ale ona se neposkvrnila,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'ten muž přivede svou ženu ke knězi a přinese za ni obětní dar: desetinu éfy ječné mouky. Nevyleje na ni olej ani na ni nedá kadidlo, protože je to obětní dar žárlivosti, obětní dar památky připomínající vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Kněz ji přivede a postaví ji před Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Kněz vezme svatou vodu do hliněné nádoby. Pak vezme kněz trochu prachu, který bude na podlaze příbytku, a dá jej do vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Kněz postaví tu ženu před Hospodina, rozpustí vlasy na hlavě té ženy a dá jí do ruky připomínkový obětní dar, to je obětní dar žárlivosti. A v rukou kněze bude hořká voda působící prokletí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Kněz ji zapřisáhne a řekne ženě: Jestliže s tebou neležel muž a jestliže jsi nesešla na scestí nečistoty, zatímco pod léháš svému muži, buď zproštěna účinku této hořké vody působící prokletí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Jestliže jsi však sešla na scestí, zatímco pod léháš svému muži, jestliže ses poskvrnila a ⌈měl s tebou pohlavní styk někdo⌉ kromě tvého muže --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'kněz zapřisáhne tu ženu přísahou prokletí a řekne ženě -- ať tě Hospodin uprostřed tvého lidu učiní prokletím a přísahou, když ti dá Hospodin propadlá bedra a vyduté lůno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Ať tato voda působící prokletí pronikne do tvých vnitřností, aby tvé lůno vydulo a tvá bedra propadla. A žena řekne: Amen, Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Kněz napíše tato prokletí do knihy a pak je smyje do hořké vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Dá ženě vypít tu hořkou vodu působící prokletí a voda působící prokletí vejde do ní ⌈k hořkosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Potom vezme kněz z rukou ženy obětní dar žárlivosti, zamává obětním darem před Hospodinem a přinese ho na oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Kněz vezme z obětního daru hrst jako pamětní dar a obětuje ho na oltáři. Potom dá ženě vypít tu vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Když jí dá vypít tu vodu, stane se, že jestliže se poskvrnila a zpronevěřila se vůči svému muži věrolomností, vejde do ní voda působící prokletí a způsobí hořkost, její břicho bude vyduté a její bedra propadlá. I stane se ta žena prokletím uprostřed svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Jestliže se však ta žena neposkvrnila a je čistá, zůstane bez trestu a schopná mít potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Toto je zákon o žárlivosti, když žena sejde na scestí, zatímco pod léhá svému muži, a poskvrní se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'anebo muž, na kterého přijde žárlivost, vzplane žárlivostí vůči své ženě -- ať postaví ženu před Hospodina a kněz s ní naloží podle tohoto zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Muž bude zproštěn viny, ale ta žena ponese svou vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Promluv k synům Izraele a řekni jim: Když muž či žena učiní zvláštní slib a jako nazír se zasvětí Hospodinu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'bude se naprosto zdržovat vína a piva, nebude pít vinný ocet ani ocet z opojného nápoje, nebude pít žádnou hroznovou šťávu a nebude jíst hrozny čerstvé ani sušené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Po všechny dny svého nazírství nebude jíst nic, co bylo získáno z vinné révy, ani ⌈nezralé hrozny,⌉ ani semeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Po všechny dny jeho nazírského slibu nepřijde břitva na jeho hlavu; dokud se nenaplní dny, na které se zasvětil Hospodinu, bude svatý, nechá si volně růst vlasy na hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Po všechny dny svého zasvěcení Hospodinu se nepřiblíží k mrtvému člověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Neposkvrní se ani se svým otcem, matkou, bratrem či sestrou, když zemřou, neboť má na hlavě zasvěcení svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Po všechny dny svého nazírství bude svatý Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Když by v okamžiku a náhle vedle něj zemřel mrtvý a znečistil by tak jeho posvěcenou hlavu, oholí si hlavu v den svého očišťování; oholí si ji v sedmý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Osmého dne přinese dvě hrdličky nebo dvě holoubata ke knězi do vchodu stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Kněz ať připraví jedno jako oběť za hřích a jedno jako zápalnou oběť a vykoná za něj obřad smíření, protože zhřešil kvůli mrtvému. V onen den posvětí svou hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Zasvětí Hospodinu dny svého nazírství. Přivede ročního beránka jako oběť za vinu. Dřívější dny propadnou, protože poskvrnil své nazírství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Toto je zákon o nazírovi: V den, kdy se naplní dny jeho nazírství, přivede ho do vchodu stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Jako svůj obětní dar přivede Hospodinu jednoho ročního beránka bez vady jako zápalnou oběť, jednu roční ovečku bez vady jako oběť za hřích a jednoho berana bez vady jako pokojnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Dále koš nekvašených chlebů, totiž bochníky z jemné mouky namísené s olejem, nekvašené placky pomazané olejem a patřičné přídavné oběti a lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Kněz to přinese před Hospodina a připraví jeho oběť za hřích a jeho zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Berana připraví jako pokojnou oběť pro Hospodina s košem nekvašených chlebů. Kněz též připraví jeho přídavnou oběť a jeho litou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Nazír si u vchodu do stanu setkávání oholí svou posvěcenou hlavu, vlasy ze své posvěcené hlavy vezme a dá je do ohně pod pokojnou obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Kněz vezme uvařenou plec z berana, jeden nekvašený bochník z koše, jednu nekvašenou placku a dá to nazírovi do rukou poté, co si oholil svou posvěcenou hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Kněz s nimi zamává před Hospodinem jako mávanou obětí. Je to svatá věc; patří to knězi spolu s hrudím mávané oběti a kýtou daru pozdvihování. Potom může nazír pít víno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'To je zákon o nazírovi, který slíbí svůj obětní dar Hospodinu za své zasvěcení, kromě toho co může udělat navíc. Podle svého slibu, který učinil, tak ať učiní, podle zákona o svém zasvěcení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Promluv k Áronovi a jeho synům slovy: Takto budete žehnat synům Izraele. Říkejte jim:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Ať ti Hospodin žehná a chrání tě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Ať nad tebou Hospodin rozjasní svou tvář a je ti milostiv!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Ať k tobě Hospodin pozvedne svou tvář a ⌈zahrne tě pokojem!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Budou klást mé jméno na syny Izraele a já jim požehnám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'I stalo se v den, kdy Mojžíš dokončil stavění příbytku, že ho pomazal a posvětil i všechny jeho předměty a také oltář a všechny jeho předměty. Když je pomazal a posvětil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'přiblížili se izraelští předáci (to byli předáci domu svých otců, předáci pokolení, ustanovení nad spočítanými)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'a přinesli před Hospodina svůj obětní dar: Šest krytých vozů a dvanáct býků -- vůz na dva předáky a na každého jednoho býka. Přivedli je před příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Hospodin řekl Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Vezmi to od nich a budou k užití při službě stanu setkávání; dej je Lévijcům, každému podle jejich služby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Mojžíš tedy vzal vozy a býky a dal je Lévijcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dva vozy a čtyři býky dal synům Geršónovým podle jejich služby');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'a čtyři vozy a osm býků dal synům Merarího podle jejich služby pod vedením kněze Ítamara, syna Áronova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Synům Kehatovým nedal nic, protože ⌈jim patřila⌉ služba svatých věcí, aby je nosili na ramenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Předáci přinesli dar k posvěcení oltáře v den jeho pomazání. Předáci přinesli svůj obětní dar před oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Hospodin řekl Mojžíšovi: ⌈Každého dne přinese vždy jeden předák⌉ svůj obětní dar k posvěcení oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'I stalo se, že prvního dne přinesl svůj obětní dar Nachšón, syn Amínadabův, za pokolení Judovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Jeho obětním darem bylo: jedna stříbrná mísa o váze sto třiceti šekelů, jedna stříbrná miska o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'jedna kadidlová pánvička o váze deseti šekelů zlata, plná kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'jeden býček, jeden beran a jeden roční beránek na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'jeden chlupatý kozel na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'a na pokojnou oběť dva býci, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Nachšóna, syna Amínadabova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Druhého dne přinesl dar Netanel, syn Súarův, předák Isacharův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Netanela, syna Súarova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Třetího dne předák synů Zabulónových Elíab, syn Chelónův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Elíaba, syna Chelónova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Čtvrtého dne předák synů Rúbenových Elísúr, syn Šedeúrův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Elísúra, syna Šedeúrova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Pátého dne předák synů Šimeónových Šelumíel, syn Suríšadajův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Šelumíla, syna Suríšadajova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Šestý den předák synů Gádových Eljásaf, syn Deúelův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Eljásafa, syna Deúelova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Sedmého dne předák synů Efrajimových Elíšama, syn Amíhudův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Elíšamy, syna Amíhudova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Osmého dne předák synů Manasesových Gamlíel, syn Pedásurův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
