INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Devátého dne předák synů Benjamínových Abídan, syn Gideoního,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
