INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Abídana, syna Gideoního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Desátého dne předák synů Danových Achíezer, syn Amíšadajův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Achíezera, syna Amíšadajova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Jedenáctého dne předák synů Ašerových Pagíel, syn Okranův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Pagíela, syna Okranova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Dvanáctého dne předák synů Neftalího Achíra, syn Énanův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'přinesl svůj obětní dar: jednu stříbrnou mísu o váze sto třiceti šekelů, jednu stříbrnou misku o váze sedmdesáti šekelů podle šekelu svatyně, obě plné jemné mouky namísené s olejem na přídavnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'jednu kadidlovou pánvičku o váze deseti šekelů zlata, plnou kadidla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'jednoho býčka, jednoho berana a jednoho ročního beránka na zápalnou oběť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'jednoho chlupatého kozla na oběť za hřích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'a na pokojnou oběť dva býky, pět beranů, pět kozlů a pět ročních beránků. To byl obětní dar Achíry, syna Énanova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'To byl obětní dar posvěcení oltáře v den jeho pomazání od izraelských předáků: dvanáct stříbrných mís, dvanáct stříbrných misek, dvanáct zlatých kadidlových pánviček --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'každá mísa o váze sto třiceti šekelů stříbra a každá miska o váze sedmdesáti šekelů, celkem stříbrné nádoby o váze tisíc čtyři sta šekelů podle šekelu svatyně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'dvanáct zlatých kadidlových pánviček, plných kadidla, po deseti šekelech na kadidlovou pánvičku podle šekelu svatyně, všeho zlata na kadidlových pánvičkách bylo sto dvacet šekelů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'všeho skotu na zápalnou oběť bylo dvanáct býčků, dvanáct beranů a dvanáct ročních beránků, jejich dar na oběť za hřích byl dvanáct chlupatých kozlů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'všeho skotu na pokojnou oběť bylo dvacet čtyři býčků, šedesát beranů, šedesát kozlů a šedesát ročních beránků. To byl dar k posvěcení oltáře po jeho pomazání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Když vcházel Mojžíš do stanu setkávání, aby mluvil s Bohem, slyšel hlas mluvící k němu ze slitovnice, která byla na truhle svědectví mezi dvěma cheruby, a mluvil k němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Promluv k Áronovi a řekni mu: Když budeš nasazovat lampy, ať sedm lamp osvěcuje místo před svícnem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Áron tak učinil. Nasadil lampy dopředu před svícen, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Svícen byl udělán takto: Byla to tepaná práce ze zlata, od podstavce až po květ to byla tepaná práce; podle podoby, již ukázal Hospodin Mojžíšovi, tak udělal svícen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Vezmi Lévijce zprostřed synů Izraele a očisti je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Nalož s nimi takto, abys je očistil: pokrop je vodou očištění, ať přejedou břitvou po celém těle a vyperou si šaty, aby se očistili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Ať vezmou býčka a jako přídavnou oběť jemnou mouku namísenou s olejem a ty vezmi druhého býčka jako oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Přiveď Lévijce před stan setkávání a svolej celou pospolitost synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Přiveď Lévijce před Hospodina a synové Izraele na Lévijce vloží ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Áron ať obětuje Lévijce před Hospodinem jako mávanou oběť od synů Izraele, aby mohli vykonávat Hospodinovu službu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Lévijci ať vloží ruce na hlavy býčků a ty připrav jednoho jako oběť za hřích a druhého jako zápalnou oběť pro Hospodina, abys vykonal obřad smíření za Lévijce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Potom postav Lévijce před Árona a před jeho syny a obětuj je jako mávanou oběť pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Odděl Lévijce zprostřed synů Izraele; Lévijci budou moji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Potom, až je očistíš a obětuješ jako mávanou oběť, ať Lévijci ⌈vejdou, aby sloužili ve stanu⌉ setkávání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'neboť jsou zcela darováni mně zprostřed synů Izraele namísto všeho, co otvírá lůno, namísto všeho prvorozeného ze synů Izraele, vzal jsem si je pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Neboť mně patří vše prvorozené ze synů Izraele, z lidí i zvířat. Tehdy, když jsem v egyptské zemi pobil všechno prvorozené, zasvětil jsem je pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Vzal jsem si Lévijce místo všeho prvorozeného ze synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Dal jsem Lévijce jako dar Áronovi a jeho synům zprostřed synů Izraele, aby vykonávali službu synů Izraele ve stanu setkávání a získávali smíření pro syny Izraele, aby nenastala pohroma mezi syny Izraele, když by se synové Izraele přiblížili ke svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Mojžíš, Áron a celá pospolitost synů Izraele naložili s Lévijci tak, jak přikázal Hospodin Mojžíšovi o Lévijcích -- tak s nimi synové Izraele naložili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Lévijci se očistili od hříchu, vyprali si šaty a Áron je obětoval před Hospodinem jako mávanou oběť; Áron za ně vykonal obřad smíření, aby je očistil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Potom vešli Lévijci vykonávat svou službu ve stanu setkávání před Áronem a před jeho syny. Jak Hospodin Mojžíšovi o Lévijcích přikázal, tak s nimi naložili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Toto je nařízení o Lévijcích: Od věku dvaceti pěti let výše bude přicházet konat službu při práci stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Ale ve věku padesáti let odstoupí ze služebního oddílu a nebude již sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Ať slouží svým bratrům ve stanu setkávání, kteří konají službu, službu však konat nebude. Takto nalož s Lévijci ohledně jejich služby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Hospodin promluvil k Mojžíšovi v Sínajské pustině v prvním měsíci druhého roku po jejich vyjití z egyptské země:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '⌈Ať synové Izraele slaví v určený čas Velikonoce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Budete je slavit navečer čtrnáctého dne toho měsíce v jejich určený čas, budete je slavit ⌈zcela podle ustanovení⌉ ⌈a nařízení o nich.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Mojžíš tedy promluvil k synům Izraele, aby slavili Velikonoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'I slavili Velikonoce prvního měsíce, čtrnáctého dne toho měsíce navečer v Sínajské pustině. Synové Izraele učinili všechno tak, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Stalo se však, že někteří muži byli nečistí kvůli mrtvému člověku a nemohli onoho dne slavit Velikonoce. Předstoupili proto onoho dne před Mojžíše a Árona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Ti muži mu řekli: Jsme nečistí kvůli mrtvému člověku. Proč bychom měli být zbaveni možnosti přinést Hospodinův obětní dar v určený čas spolu se syny Izraele?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mojžíš jim řekl: Zůstaňte tu a já budu poslouchat, co vám Hospodin přikáže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Promluv k synům Izraele: Každý člověk, který bude mezi vámi či vašimi potomky nečistý kvůli mrtvému nebo bude na daleké cestě, bude slavit velikonoční oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Budou ji slavit druhého měsíce čtrnáctého dne navečer, budou ji jíst s nekvašenými chleby a hořkými bylinami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Neponechají z ní nic do rána, nezlámou na ní kost. Budou ji slavit zcela podle ustanovení o velikonoční oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Ten, kdo by byl čistý a nebyl by na cestě a upustil by od slavení velikonoční oběti, takový člověk ať je vyhlazen ze svého lidu, protože nepřinesl v určený čas Hospodinův obětní dar. Takový muž ponese následky svého hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Jestliže s vámi bude pobývat příchozí a bude slavit velikonoční oběť Hospodinu, ať ji slaví podle ustanovení o velikonoční oběti a podle nařízení o ní. Budete mít jedno ustanovení, jak pro příchozího, tak pro domorodce v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'V den, kdy byl příbytek postaven, přikryl příbytek, totiž stan svědectví, oblak a od večera až do rána býval nad příbytkem v podobě ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tak tomu bývalo ustavičně: přikrýval ho oblak a v noci měl podobu ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Kdykoli se oblak ze stanu zvedl, synové Izraele vyrazili, a na místě, kde oblak spočíval, tam synové Izraele tábořili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Podle Hospodinova příkazu synové Izraele vyráželi a podle Hospodinova příkazu tábořili. Tábořili po všechny dny, kdy oblak spočíval nad příbytkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Když se oblak nad příbytkem zdržoval mnoho dnů, synové Izraele konali Hospodinovu službu a neputovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Stávalo se, že oblak byl nad příbytkem několik dní -- tehdy podle Hospodinova příkazu tábořili a podle Hospodinova příkazu vyráželi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'A stávalo se, že oblak byl od večera do rána a ráno se oblak zvedl, takže vyrazili. Ať to bylo ve dne či v noci, když se oblak zvedl, vyrazili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Ať to bylo dva dny, měsíc či rok, když oblak spočíval nad příbytkem, synové Izraele tábořili a nevyrazili, a když se zvedl, vyrazili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Podle Hospodinova příkazu tábořili a podle Hospodinova příkazu vyráželi; zachovávali Hospodinův řád, podle Hospodinova příkazu prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Udělej dvě stříbrné trubky. Udělej je jako tepanou práci. ⌈Budeš je mít⌉ ke svolávání pospolitosti a k odchodu táborů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Když na ně zatroubí, sejde se k tobě celá pospolitost u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Jestliže však zatroubí jen na jednu, sejdou se k tobě předáci, vůdci izraelských rodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Když zatroubíte poplašně, vyrazí tábory tábořící na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Když zatroubíte poplašně podruhé, vyrazí tábory tábořící na jihu. Na jejich odchod ať troubí poplašně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'kdežto při svolávání shromáždění zatrubte, ale ne poplašně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Na trubky ať troubí synové Áronovi, kněží. Bude to věčné ustanovení pro vás i pro vaše potomky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'A když ve své zemi vytáhnete do boje proti protivníkovi, který vás bude utlačovat, trubte poplašně na trubky. Tak budete připomenuti před Hospodinem, svým Bohem, a budete zachráněni od svých nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'I v den vaší radosti, o určených svátcích či na počátku novoluní trubte na trubky nad svými zápalnými oběťmi i nad svými pokojnými oběťmi. Tak se stanou vaší připomínkou před vaším Bohem. ⌈Já Hospodin jsem ⌉ váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'I stalo se v druhém roce, v druhém měsíci, dvacátého dne toho měsíce, že se zvedl oblak z ⌈příbytku svědectví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Synové Izraele vyrazili ze Sínajské pustiny ke svým denním pochodům. Oblak potom spočinul v Páranské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Vyrazili poprvé podle Hospodinova příkazu prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'První vyrazila zástava tábora synů Judových podle svých oddílů. Nad jeho oddíly byl Nachšón, syn Amínadabův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Nad oddílem pokolení synů Isacharových byl Netanel, syn Súarův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'a nad oddílem pokolení synů Zabulónových byl Elíab, syn Chelónův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Když byl složen příbytek, vyrazili synové Geršónovi a synové Merarího, kteří nesli příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Potom vyrazila zástava tábora Rúbenovců podle svých oddílů. Nad jeho oddílem byl Elísúr, syn Šedeúrův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Nad oddílem pokolení synů Šimeónových byl Šelumíel, syn Suríšadajův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'a nad oddílem pokolení synů Gádových byl Eljásaf, syn Deúelův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Nato vyrazili Kehatovci, kteří nesli svatyni. Do jejich příchodu už byl příbytek postaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Potom vyrazila zástava tábora synů Efrajimových podle svých oddílů. Nad jeho oddílem byl Elíšama, syn Amíhudův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Nad oddílem pokolení synů Manasesových byl Gamlíel, syn Pedásurův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'a nad oddílem pokolení synů Benjamínových byl Abídan, syn Gideoního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Potom vyrazila zástava tábora synů Danových podle svých oddílů, která uzavírala všechny tábory. Nad jeho oddílem byl Achíezer, syn Amíšadajův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Nad oddílem pokolení synů Ašerových byl Pagíel, syn Okranův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'a nad oddílem pokolení synů Neftalího byl Achíra, syn Énanův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Toto byl způsob odchodu synů Izraele podle jejich oddílů, když vyráželi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Mojžíš řekl Chóbabovi, synu Midjánce Reúela, svému tchánovi: Vyrážíme k místu, o němž Hospodin řekl: Dám vám ho. Pojď s námi a prokážeme ti dobro, protože Hospodin vyhlásil dobro o Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'On mu odpověděl: Nepůjdu, nýbrž půjdu do své země a do svého příbuzenstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Mojžíš však řekl: Neopouštěj nás, prosím, neboť ty víš, kde můžeme v pustině tábořit; budeš našima očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'I stane se, když půjdeš s námi, že to dobro, které Hospodin prokáže nám, my prokážeme tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'I vyrazili z Hospodinovy hory tři dny cesty a truhla Hospodinovy smlouvy vyrazila před nimi na tři dny cesty, aby jim vyhledala místo odpočinku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Hospodinův oblak byl nad nimi ve dne, když vyrazili z tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'I stalo se, když truhla vyrazila, že Mojžíš řekl: Povstaň, Hospodine, ať se tvoji nepřátelé rozprchnou, ti, kdo tě nenávidí, ať před tebou utečou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'A když spočinula, říkal: Navrať se, Hospodine, k desetitisícům izraelských tisíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'I stalo se, že si lid velmi stěžoval Hospodinu. Hospodin to slyšel a vzplanul jeho hněv. Vzplanul proti nim Hospodinův oheň a strávil konec tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Nato lid křičel k Mojžíšovi. Mojžíš se modlil k Hospodinu a oheň uhasl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'I pojmenovali to místo Tabéra, neboť proti nim vzplanul Hospodinův oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Lůza, která byla mezi nimi, plála touhou, takže i synové Izraele znovu plakali a říkali: ⌈Kdo nás nakrmí masem?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Vzpomínáme na ryby, které jsme jedli zadarmo v Egyptě, na okurky, melouny, pórek, cibuli a česnek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'A teď ⌈jsme vyschlí,⌉ nevidíme nic než jen tu manu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Mana byla jako koriandrové semeno, vypadala jako bdelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Lid chodíval sem a tam, sbíral ji, mlel na ručních mlýncích nebo drtil v hmoždíři, vařil v hrnci a dělal z ní podpopelné chleby. Chutnalo to jako olejový koláč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Když padala na tábor v noci rosa, padala na něj i mana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Když Mojžíš slyšel plakat lid podle jeho čeledí, každého u vchodu do jeho stanu, a Hospodin vzplanul velikým hněvem, Mojžíšovi se to nelíbilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Mojžíš řekl Hospodinu: Proč jsi naložil se svým otrokem zle? Proč jsem nenalezl milost ve tvých očích, že jsi na mě vložil břemeno všeho tohoto lidu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Což jsem já počal všechen tento lid? Zdalipak jsem jej já porodil, abys mi řekl: Nes ho v náruči, tak jako vychovatel nosí kojence, do země, o které jsem přísahal jeho otcům?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Odkud mám vzít maso, abych ho dal všemu tomuto lidu, když přede mnou pláče a říká: Dej nám maso, abychom se najedli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Já sám nemohu unést všechen tento lid, neboť je na mě příliš těžký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Pokud se mnou takto jednáš, raději mě, prosím, zabij, jestliže jsem nalezl milost ve tvých očích, ať se ne musím dívat na své trápení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Hospodin řekl Mojžíšovi: Shromáždi mi sedmdesát mužů z izraelských starších, o kterých víš, že jsou staršími lidu a jeho správci. Vezmi je ke stanu setkávání, aby se tam s tebou postavili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Sestoupím a budu tam s tebou mluvit. Vezmu z Ducha, který je na tobě, a vložím ho na ně. Ponesou břemeno lidu s tebou a neponeseš ho ty sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'A lidu řekni: Posvěťte se na zítra a budete jíst maso, protože jste plakali k Hospodinu se slovy: Kdo nás nakrmí masem? Vždyť nám bylo v Egyptě dobře. Hospodin vám dá maso a najíte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nebudete jíst jen jeden den, ani dva dny, ani pět dní, ani deset dní, ani dvacet dní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'ale celý měsíc, až vám poleze z chřípí a bude vám odporné, protože jste pohrdli Hospodinem, který je uprostřed vás, a plakali jste před ním se slovy: Proč jenom jsme vyšli z Egypta?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Mojžíš řekl: Šest set tisíc pěších je v lidu, uprostřed něhož jsem, a ty říkáš: Dám jim maso a budou ho jíst celý měsíc?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Cožpak se pro ně bude zabíjet brav a skot, aby to pro ně stačilo? Nebo se pro ně mají pochytat všechny mořské ryby, aby to pro ně stačilo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Hospodin Mojžíšovi odpověděl: Cožpak ⌈je Hospodinova ruka krátká?⌉ Nuže, uvidíš, jestli se ti mé slovo uskuteční, či nikoli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Mojžíš vyšel a promluvil k lidu Hospodinova slova. Pak shromáždil sedmdesát mužů ze starších lidu a postavil je okolo stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Hospodin sestoupil v oblaku, promluvil k němu a vzal z Ducha, který byl na něm, a dal ho na sedmdesát mužů ze starších. I stalo se, když na nich Duch spočinul, že prorokovali, ale znovu již ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Dva muži zůstali v táboře -- jeden se jmenoval Eldád a druhý se jmenoval Médád. I na nich spočinul Duch -- byli totiž mezi zapsanými, ale nevyšli ke stanu -- a prorokovali v táboře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Přiběhl mládenec a oznámil to Mojžíšovi: Eldád a Médád prorokují v táboře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Ozval se Jozue, syn Núnův, který sloužil Mojžíšovi od svého mládí, a řekl: Můj pane, Mojžíši, zadrž je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mojžíš mu řekl: Ty žárlíš kvůli mně? Kéž by všechen Hospodinův lid byli proroci, když by Hospodin na ně dal svého Ducha!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Mojžíš se odebral do tábora, on i izraelští starší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'I strhl se vítr od Hospodina, přinesl křepelky od moře a svrhl je na tábor na den cesty na jednu stranu a na den cesty na druhou stranu kolem tábora a to na dva lokte vysoko nad povrch země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Lid povstal a celý ten den a celou noc i celý druhý den sbíral křepelky; i ten, kdo se spokojil s málem, nasbíral deset chómerů. A rozprostřeli je všude okolo tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Ještě měli maso mezi zuby, dříve nežli ho rozžvýkali, Hospodin vzplanul hněvem proti lidu; Hospodin ranil lid převelikou ranou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Pojmenovali to místo Kibrót–taava, protože tam pohřbili lid, který byl žádostivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Z Kibrót–taavy vyrazil lid do Chaserótu a zůstali v Chaserótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Tehdy Mirjam mluvila s Áronem proti Mojžíšovi ohledně kúšské ženy, kterou si vzal; vzal si totiž kúšskou ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Říkali: Cožpak Hospodin mluvil pouze a jenom skrze Mojžíše? Což nemluvil také skrze nás? Hospodin to slyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Mojžíš byl velmi pokorný muž, více než všichni lidé, kteří byli na povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Hospodin hned řekl Mojžíšovi, Áronovi a Mirjamě: Vyjděte všichni tři ke stanu setkávání. Všichni tři vyšli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Hospodin sestoupil v oblakovém sloupu, zastavil se u vchodu do stanu, zavolal Árona a Mirjam a oni oba vyšli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Hospodin řekl: Poslyšte má slova: Kdyby byl mezi vámi ⌈prorok Hospodinův,⌉ dám se mu poznat ve vidění, budu s ním mluvit ve snu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Ne tak s mým otrokem Mojžíšem; je věrný v celém mém domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'S ním mluvím ⌈tváří v tvář,⌉ zřetelně, ne v hádankách, hledí na Hospodinovu podobu. Jak to, že jste se nebáli mluvit proti mému otroku Mojžíšovi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Hospodin proti nim planul hněvem a odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Když oblak od stanu odstoupil, hle, Mirjam byla malomocná, jako sníh. Áron na Mirjam pohleděl, a hle, byla malomocná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Áron řekl Mojžíšovi: Dovol, můj pane, nevkládej na nás, prosím, trest za hřích, když jsme jednali hloupě a zhřešili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Ať není jako mrtvý, jenž když vyjde z lůna matky, polovina jeho těla je strávena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Mojžíš volal úpěnlivě k Hospodinu: Bože, uzdrav ji, prosím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Hospodin řekl Mojžíšovi: Kdyby jí otec naplival do tváře, což by nenesla hanbu po sedm dní? Ať je sedm dní zavřena venku za táborem a potom ať se připojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Mirjam byla tedy zavřena sedm dní venku za táborem a lid nevyrazil, dokud se Mirjam nepřipojila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Potom lid vyrazil z Chaserótu a utábořili se v Páranské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Pošli muže, aby prozkoumali kenaanskou zemi, kterou dávám synům Izraele. Pošlete vždy jednoho muže za otcovské pokolení, samé předáky mezi vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Mojžíš je poslal z Páranské pustiny podle Hospodinova příkazu. Všichni tito muži byli předáci synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Toto jsou jejich jména: Za pokolení Rúbenovo Šamúa, syn Zakúrův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'za pokolení Šimeónovo Šafat, syn Chóríův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'za pokolení Judovo Káleb, syn Jefunův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'za pokolení Isacharovo Jigál, syn Josefův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'za pokolení Efrajimovo Hóšea, syn Núnův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'za pokolení Benjamínovo Paltí, syn Rafúův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'za pokolení Zabulónovo Gadíel, syn Sódíův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'za pokolení Josefovo, za pokolení Manasesovo Gadí, syn Súsíův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'za pokolení Danovo Amíel, syn Gemalíův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'za pokolení Ašerovo Setúr, syn Michaelův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'za pokolení Neftalího Nachbí, syn Vofsíův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'za pokolení Gádovo Geúel, syn Makíův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Toto jsou jména mužů, které poslal Mojžíš, aby prozkoumali zemi. Hóšeu, syna Núnova, nazval Mojžíš Jozue.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Když je Mojžíš posílal, aby prozkoumali kenaanskou zemi, řekl jim: Jděte vzhůru Negebem a vyjděte do pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Prohlédněte zemi, jaká je, i lid, který v ní bydlí, zdali je silný či malátný, je–li ho málo či mnoho;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'a jaká je země, ve které bydlí, -- je–li dobrá či zlá; a jaká jsou města, ve kterých bydlí, jsou –li jako tábor či opevněná;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'a jaká je země -- úrodná či neúrodná; jsou–li v ní stromy či ne. Počínejte si zmužile a vezměte z plodů té země. Byl právě čas raných hroznů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Vyšli a prozkoumali zemi od pustiny Sinu až k Rechóbu a Lebo–Chamátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Šli vzhůru Negebem a přišli až do Chebrónu. Tam byli Achíman, Šéšaj a Talmaj, potomci Anákovi. (Chebrón byl vybudován sedm let před egyptským Sóanem.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Když přišli až do údolí Eškólu, uřízli tam ratolest s jedním vinným hroznem -- dva ho museli nést na sochoru, a několik granátových jablek a fíků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'To místo se nazývá údolí Eškólu právě kvůli hroznu, který tam synové Izraele uřízli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Po čtyřiceti dnech se vrátili z průzkumu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Šli, až přišli k Mojžíšovi, Áronovi a celé pospolitosti synů Izraele do Kádeše v Páranské pustině. Přinesli zprávu jim a celé pospolitosti a ukázali jim ovoce té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Vyprávěli mu: Přišli jsme do země, do níž jsi nás poslal. Ano, oplývá mlékem a medem a toto je její ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Nicméně lid, který sídlí v zemi, je silný a města jsou opevněná a velmi velká. A také jsme tam viděli potomky Anákovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Na ⌈území Negebu⌉ sídlí Amálekovci, v pohoří sídlí Chetejci, Jebúsejci a Emorejci a u moře a podél Jordánu sídlí Kenaanci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Káleb uklidňoval lid před Mojžíšem slovy: Směle pojďte vzhůru, obsadíme ji, jistě přemůžeme její obyvatele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Muži, kteří šli s ním, však říkali: Nedokážeme táhnout proti tomu lidu, neboť je silnější nežli my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Pomluvili zemi, kterou prozkoumali, když říkali synům Izraele: Země, kterou jsme procházeli, abychom ji prozkoumali, je země požírající své obyvatele a všechen lid, který jsme v ní viděli, jsou obrovití muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Viděli jsme tam obry -- synové Anákovi totiž pocházejí z obrů -- a připadali jsme si jako kobylky a takoví jsme byli i v jejich očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Celá pospolitost ⌈pozvedla a vydávala svůj hlas.⌉ Lid oné noci plakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Všichni synové Izraele reptali proti Mojžíšovi a Áronovi. Celá pospolitost jim říkala: Kéž bychom byli zemřeli v egyptské zemi anebo ⌈kéž bychom zemřeli v této pustině!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Proč nás Hospodin přivedl do této země, abychom padli mečem? Naše ženy a malé děti se stanou kořistí. Nebylo by pro nás lepší vrátit se do Egypta?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'A říkali jeden druhému: Ustanovme si vůdce a vraťme se do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Mojžíš a Áron padli na tvář před celým shromážděním pospolitosti synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Jozue, syn Núnův, a Káleb, syn Jefunův, z těch kteří prozkoumali zemi, roztrhli svá roucha');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'a říkali celé pospolitosti synů Izraele: Země, kterou jsme prošli, abychom ji prozkoumali, je převelice dobrá země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Jestliže v nás Hospodin najde zalíbení, přivede nás do této země a dá nám ji -- zemi, která oplývá mlékem a medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Jenom se nebouřete proti Hospodinu! A lidu té země se nebojte, vždyť jsou pro nás jako chleba. Jejich ochrana od nich odstoupila, ale s námi je Hospodin, nebojte se jich!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Když celá pospolitost říkala, že ⌈na ně budou házet kamení,⌉ všem synům Izraele se u stanu setkávání ukázala Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Hospodin řekl Mojžíšovi: Jak dlouho mě bude tento lid znevažovat? Jak dlouho mi nebudou věřit přes všechna znamení, která jsem uprostřed nich učinil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Pobiji je morem a vyvlastním je, z tebe však udělám větší a mocnější národ, nežli jsou oni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Mojžíš nato řekl Hospodinu: Když se o tom doslechnou Egypťané, z jejichž středu jsi svou silou vyvedl tento lid,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'řeknou to obyvatelům této země. Slyšeli, že ty, Hospodine, jsi uprostřed tohoto lidu, že ty, Hospodine, ses ukazoval ⌈tváří v tvář,⌉ že tvůj oblak stál nad nimi a že v oblakovém sloupu jsi před nimi chodil ve dne a v ohnivém sloupu v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Když usmrtíš tento lid do jednoho muže, národy, které slyšely zprávu o tobě, řeknou:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Protože Hospodin nebyl schopen přivést tento lid do země, kterou jim odpřisáhl, pobil je v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Ať se nyní, prosím, ukáže, že je veliká Panovníkova síla, tak jak jsi řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Hospodin je pomalý k hněvu a hojný v milosrdenství, odpouští vinu a přestoupení. Jistě však nenechá viníka bez trestu, ale navštěvuje s trestem vinu otců na synech, na třetí i čtvrté generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Odpusť, prosím, vinu tohoto lidu podle svého velkého milosrdenství, tak jako jsi odpouštěl tomuto lidu od Egypta až doposud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Hospodin řekl: Na tvé slovo odpouštím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Avšak jakože jsem živ, Hospodinova sláva naplní celou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Žádný z mužů, kteří viděli mou slávu a má znamení, která jsem činil v Egyptě a v pustině, a pokoušeli mě takto desetkrát a neuposlechli mě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'neuvidí zemi, kterou jsem odpřisáhl jejich otcům; žádný, kdo mnou pohrdal, ji neuvidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Avšak svého otroka Káleba, protože ⌈smýšlel jinak⌉ a šel za mnou naplno, toho přivedu do země, do níž vešel, a jeho potomstvo si ji podrobí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'V údolí sídlí Amálekovci a Kenaanci. Zítra se obraťte a vyrazte do pustiny směrem k Rákosovému moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Jak dlouho se mám zabývat s touto zlou pospolitostí, která proti mně reptá? Slyšel jsem reptání synů Izraele, kterým proti mně reptali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Řekni jim: Jakože jsem živ, je Hospodinův výrok, naložím s vámi tak, jak ⌈jste mě prosili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'V této pustině padnou vaše mrtvoly, všichni vaši spočítaní v celém počtu od dvacetiletých výše, kteří reptali proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Nevejdete do země, o níž jsem pozvednutím ruky přísahal, že v ní budete přebývat -- jenom Káleb, syn Jefunův, a Jozue, syn Núnův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Vaše malé děti, o nichž jste řekli, že se stanou kořistí, ty tam přivedu a poznají zemi, kterou jste vy pohrdli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Vaše mrtvoly padnou v této pustině');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'a vaši synové budou pastýři v pustině po čtyřicet let a ponesou vaše smilstvo, dokud v pustině nepadnou všechny vaše mrtvoly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Podle počtu dnů, v nichž jste prozkoumali zemi, čtyřicet dnů, za každý den jeden rok po čtyřicet let ponesete své viny a poznáte mou nelibost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Já Hospodin jsem promluvil: Takto naložím s celou touto zlou pospolitostí těch, kteří se proti mně smluvili: Zahynou v této pustině, tady zemřou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Ti muži, které Mojžíš poslal prozkoumat zemi, kteří se vrátili a podnítili celou pospolitost k reptání proti němu tím, že pomluvili tu zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'ti muži, kteří zle pomlouvali zemi, zemřeli ranou od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Jedině Jozue, syn Núnův, a Káleb, syn Jefunův, zůstali naživu z oněch mužů, kteří šli prozkoumat zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Mojžíš promluvil tato slova ke všem synům Izraele a lid velmi truchlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Časně zrána vstali, aby vystoupili na vrchol pohoří se slovy: ⌈Zde jsme,⌉ vytáhněme na to místo, o kterém Hospodin mluvil. Ano, zhřešili jsme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mojžíš však řekl: Proč jenom přestupujete Hospodinův příkaz? To se nezdaří!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Netáhněte, neboť Hospodin není ve vašem středu! Ať nejste poraženi od svých nepřátel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'vždyť jsou tam před vámi Amálekovci a Kenaanci -- padnete mečem. Protože jste se od Hospodina odvrátili, Hospodin s vámi nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Oni si však troufali vystoupit na vrchol pohoří, ale truhla Hospodinovy smlouvy ani Mojžíš se nepohli ze středu tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Tu sestoupili Amálekovci a Kenaanci, kteří v tom pohoří bydleli, a pobíjeli je a rozháněli je až po Chormu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Promluv k synům Izraele a řekni jim: Až vejdete do země, ⌈ kde budete přebývat⌉ a kterou vám dávám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'a budete připravovat Hospodinu ohnivou oběť ze skotu nebo z bravu -- ať zápalnou oběť či obětní hod jako splnění zvláštního slibu či jako dobrovolnou oběť či ve vaše svátky -- a tak budete připravovat příjemnou vůni Hospodinu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'ať přinese ten, kdo přináší svůj obětní dar Hospodinu, jako přídavnou oběť desetinu éfy jemné mouky namísené se čtvrtinou hínu oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Jako litou oběť připrav čtvrtinu hínu vína k zápalné oběti či obětnímu hodu na každého beránka');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'anebo na berana připrav jako přídavnou oběť dvě desetiny éfy jemné mouky namísené s třetinou hínu oleje');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'a jako litou oběť přines třetinu hínu vína jako příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Když budeš připravovat tele jako zápalnou oběť či obětní hod jako splnění zvláštního slibu či pokojnou oběť Hospodinu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'ať jsou s teletem přineseny jako přídavná oběť tři desetiny éfy jemné mouky namísené s polovinou hínu oleje');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'a jako litou oběť přines polovinu hínu vína. To bude k ohnivé oběti jako příjemná vůně Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Takto se to bude dělat s každým býkem anebo beranem nebo ⌈beránky či kůzlaty,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'podle počtu, který připravíte; takto budete jednat s každým podle jejich počtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Každý domorodec bude takto činit tyto věci, když bude přinášet ohnivou oběť jako příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'A když bude ve vašich budoucích pokoleních s vámi pobývat příchozí anebo kdokoli ve vašem středu a bude připravovat ohnivou oběť jako příjemnou vůni Hospodinu -- jak to činíte vy, tak ať to činí i on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Ve shromáždění bude stejné ustanovení pro vás i pro příchozího, který mezi vámi pobývá, jako věčné ustanovení pro všechna vaše pokolení; jako vy tak i příchozí bude před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Stejný zákon a stejné nařízení bude pro vás i pro příchozího, který s vámi pobývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Promluv k synům Izraele a řekni jim: Až vejdete do země, do níž vás přivádím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'když budete jíst z pokrmu země, přinášejte Hospodinu dar pozdvihování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Jako prvotinu ze svého těsta přineste bochník jako dar pozdvihování; přineste ho jako dar pozdvihování z humna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Z prvotiny svého těsta dávejte Hospodinu dar pozdvihování po všechna svá pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Kdybyste však pobloudili a nesplnili všechny tyto příkazy, které promluvil Hospodin k Mojžíšovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'vše, co vám Hospodin přikázal prostřednictvím Mojžíše ode dne, kdy Hospodin vydal příkaz a nadále ve všech vašich pokoleních,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'jestliže se to stalo ⌈ne před očima⌉ pospolitosti, bylo to vykonáno nedopatřením, připraví celá pospolitost jednoho býčka jako zápalnou oběť, jako příjemnou vůni Hospodinu, i patřičnou přídavnou oběť a litou oběť podle nařízení a jednoho chlupatého kozla jako oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Kněz vykoná obřad smíření za celou pospolitost synů Izraele a bude jim odpuštěno, neboť to bylo nedopatření a oni přinesli svůj obětní dar, ohnivou oběť Hospodinu a svou oběť za hřích před Hospodina za své nedopatření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Bude odpuštěno celé pospolitosti synů Izraele i příchozímu, který pobývá uprostřed nich, neboť se to stalo všemu lidu nedopatřením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Jestliže však zhřeší nedopatřením jeden člověk, přivede jako oběť za hřích roční kozu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Kněz vykoná obřad smíření za toho člověka, který pobloudil, když nedopatřením zhřešil vůči Hospodinu; vykoná za něj obřad smíření a bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Pro domorodce mezi syny Izraele i pro příchozího, který pobývá uprostřed nich, budete mít jeden zákon, pro toho, kdo jednal nedopatřením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Avšak člověk, který by jednal z povýšenosti -- ať domorodec či příchozí -- utrhá Hospodinu; takový člověk ať je vyhlazen zprostřed svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Protože pohrdl Hospodinovým slovem a porušil jeho příkaz, takový člověk ať je jistě vyhlazen, ⌈ je na něm vina.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Když byli synové Izraele v pustině, našli muže, který sbíral v sobotní den dříví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Ti, kdo ho našli, jak sbírá dříví, ho přivedli k Mojžíšovi, Áronovi a celé pospolitosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Nechali ho u stráže, protože nebylo rozhodnuto, co se s ním má dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Hospodin řekl Mojžíšovi: Ten muž bude jistě usmrcen! Ať na něj celá pospolitost venku za táborem hází kamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Celá pospolitost ho vyvedla ven za tábor, házeli na něj kamení, takže zemřel, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Hospodin řekl Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Promluv k synům Izraele a řekni jim, aby si po všechna pokolení dělali na okrajích roucha třásně a dávali na okrajové třásně modrou šňůrku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Budete mít třásně, takže když je uvidíte, vzpomenete si na všechny Hospodinovy příkazy a budete je plnit a nebudete zkoumavě následovat své srdce a své oči, ⌈za nimiž byste chodili smilnit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Takto si budete připomínat a plnit všechny mé příkazy a budete svatí svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Já Hospodin jsem váš Bůh, který vás vyvedl z egyptské země, abych byl vaším Bohem. Já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Kórach, syn Jishára, syna Kehata, syna Léviho, přibral Dátana a Abírama, syny Elíabovy, i Óna, syna Peletova, Rúbenovce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'a povstali proti Mojžíšovi spolu s dvěma sty padesáti muži ze synů Izraele, předáky pospolitosti, vyvolenými shromáždění, ⌈věhlasnými muži.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Shromáždili se proti Mojžíšovi a Áronovi a řekli jim: Už dost! Vždyť celá pospolitost, všichni jsou svatí a Hospodin je uprostřed nich. Proč se povyšujete nad ⌈Hospodinovo shromáždění?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Když to Mojžíš uslyšel, padl na tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Potom promluvil ke Kórachovi a k celé jeho pospolitosti: Ráno Hospodin ukáže, kdo mu patří, kdo je svatý a komu dovolí přiblížit se k němu. Koho vyvolí, tomu dovolí přiblížit se k němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Toto učiňte: Vezměte si kadidelnice, Kórach a celá jeho pospolitost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'zítra do nich dejte oheň a položte na ně kadidlo před Hospodinem. Ten muž, kterého Hospodin vyvolí, ten je svatý. Už dost, synové Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Mojžíš řekl Kórachovi: Slyšte, synové Léviho!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Je vám to málo, že vás Bůh Izraele oddělil z pospolitosti Izraele a nechal vás přistupovat k sobě, abyste konali službu Hospodinova příbytku, stáli před pospolitostí a sloužili jim?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Nechal přistupovat tebe a s tebou všechny tvé bratry, syny Léviho, a teď usilujete také o kněžství?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Proto jste se ty a celá tvoje pospolitost smluvili proti Hospodinu? Co je Áron, že proti němu reptáte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Mojžíš si dal zavolat Dátana a Abírama, syny Elíabovy, ale oni řekli: Nepřijdeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Je to málo, že jsi nás vyvedl ze země oplývající mlékem a medem, abys nás usmrtil v pustině, že nad námi chceš ještě takto vládnout?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Vůbec jsi nás nepřivedl do země oplývající mlékem a medem ani jsi nám nedal do dědictví pole a vinice. ⌈Chceš těmto mužům vyloupat oči?⌉ Nepřijdeme!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Mojžíš se velice rozzlobil a řekl Hospodinu: Nehleď na jejich přídavnou oběť! Nevzal jsem od nich ani jediného osla, nikomu z nich jsem nespáchal zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Kórachovi Mojžíš řekl: Ty a celá tvá pospolitost buďte zítra před Hospodinem -- ty ⌈s nimi⌉ a Áron.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Vezměte si každý kadidelnici, dejte do nich kadidlo a přineste každý svou kadidelnici před Hospodina, dvě stě padesát kadidelnic, i ty i Áron, každý svou kadidelnici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Vzali si tedy každý svou kadidelnici, dali do ní oheň, položili na ně kadidlo a postavili se ke vchodu do stanu setkávání, i Mojžíš a Áron.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Když proti nim Kórach svolal celou pospolitost ke vchodu do stanu setkávání, ukázala se celé pospolitosti Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Hospodin promluvil k Mojžíšovi a Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Oddělte se od této pospolitosti, v okamžiku s nimi skoncuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Oni padli na tvář a řekli: Bože, ⌈Bože duchů⌉ celého tvorstva, zhřešil jeden muž, a ty se budeš hněvat na celou pospolitost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Promluv k pospolitosti: Odtáhněte z okolí příbytku Kórachova, Dátanova a Abíramova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Mojžíš vstal a šel k Dátanovi a Abíramovi. Za ním šli izraelští starší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Pak promluvil k pospolitosti: Odstupte od stanů těchto ničemných mužů a nedotýkejte se ničeho, co jim patří, jinak budete smeteni kvůli všem jejich hříchům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Odtáhli tedy z okolí příbytku Kórachova, Dátanova a Abíramova. Dátan a Abíram vyšli a postavili se u vchodu do svých stanů, spolu s svými ženami, syny a malými dětmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Mojžíš řekl: Podle toho poznáte, že mě poslal Hospodin, abych učinil všechny tyto skutky, a ne ⌈já sám:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Jestliže tito zemřou smrtí všech lidí a ⌈postihne je úděl⌉ všech lidí, neposlal mě Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Jestliže však Hospodin stvoří ⌈něco nového,⌉ země otevře svůj chřtán, pohltí je i všechno, co jim patří, a sestoupí zaživa do podsvětí, poznáte, že tito muži znevážili Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'I stalo se, když domluvil všechna tato slova, že se země pod nimi rozpoltila,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'země otevřela svůj chřtán, pohltila je i jejich domy i všechny lidi, kteří patřili ke Kórachovi, i všechen jejich majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Oni i všichni, kdo k nim patřili, sestoupili zaživa do podsvětí, země je přikryla a zmizeli zprostřed shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Všichni Izraelci, kteří byli okolo nich, před jejich křikem utekli, neboť si řekli: Jinak země pohltí i nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'I vyšlehl oheň od Hospodina a strávil těch dvě stě padesát mužů, kteří přinesli kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Řekni knězi Eleazarovi, synu Áronovu, ať vynese kadidelnice ze spáleniště, neboť jsou svaté, a oheň rozmetej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Z kadidelnic těch, kdo zhřešili proti svým duším, z nich ať udělají tepané pláty k potažení oltáře, neboť je přinesli před Hospodina a jsou svaté. Ať jsou znamením pro syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Kněz Eleazar vzal bronzové kadidelnice, které přinesli ti, kdo byli spáleni, a vytepali z nich pláty k potažení oltáře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'jako připomínku pro syny Izraele, aby se nepřibližoval nikdo cizí, kdo není z potomstva Áronova, a ne pálil kadidlo před Hospodinem a aby nedopadl jako Kórach a jeho pospolitost -- jak k němu promluvil Hospodin prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Příštího dne celá pospolitost synů Izraele reptala proti Mojžíšovi a Áronovi slovy: Vy jste usmrtili Hospodinův lid!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'I stalo se, když se shromáždila ta pospolitost proti Mojžíšovi a Áronovi, že pohleděli ke stanu setkávání a hle, zakryl ho oblak a ukázala se Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Mojžíš a Áron šli před stan setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Vzdalte se zprostřed této pospolitosti, v okamžiku s nimi skoncuji! Oni padli na tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Mojžíš řekl Áronovi: Vezmi kadidelnici, dej do ní oheň z oltáře a polož kadidlo! Jdi rychle k pospolitosti a vykonej za ně obřad smíření, protože vyšlehl hněv od Hospodina, pohroma začala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Áron vzal to, co Mojžíš řekl, a běžel doprostřed shromáždění. A hle, pohroma v lidu již začala. Položil kadidlo a vykonal obřad smíření za lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Postavil se mezi mrtvé a živé a rána byla zadržena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 14, 'Mrtvých při té ráně bylo čtrnáct tisíc sedm set, kromě těch kdo zemřeli kvůli Kórachově záležitosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 15, 'Áron se pak vrátil k Mojžíšovi ke vchodu do stanu setkávání. Rána byla zadržena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 16, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 17, 'Promluv k synům Izraele a vezmi od nich po ⌈jedné holi⌉ za otcovský dům, od všech jejich předáků podle domu jejich otců, dvanáct holí. Jméno každého napiš na jeho hůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 18, 'Jméno Áronovo napiš na hůl Léviho, neboť bude jedna hůl za předáka domu jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 19, 'Ulož je ve stanu setkávání před svědectvím, kde se s vámi setkávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 20, 'I stane se, že hůl muže, kterého vyvolím, vypučí a zbavím se reptání synů Izraele, kteří proti vám reptali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 21, 'Mojžíš promluvil k synům Izraele a všichni jejich předáci mu dali hůl, za každého předáka hůl, za jednoho předáka podle domu jejich otců, dvanáct holí. Áronova hůl byla mezi jejich holemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 22, 'Mojžíš uložil hole před Hospodinem ve stanu svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 23, 'Příštího dne se stalo, že když Mojžíš vešel do stanu svědectví, hle, Áronova hůl za dům Léviho vypučela, vydala květ, květ rozkvetl a dozrály mandle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 24, 'Mojžíš vynesl všechny hole pryč od Hospodina ke všem synům Izraele. Viděli to a vzali si každý svou hůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 25, 'Hospodin řekl Mojžíšovi: Vrať Áronovu hůl před svědectví, aby se zachovala jako znamení synům vzpoury, aby přestalo jejich reptání přede mnou a nezemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 26, 'Mojžíš to udělal, jak mu Hospodin přikázal; tak to udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 27, 'Synové Izraele řekli Mojžíšovi: Hle, skonáme, zahyneme, všichni zahyneme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 28, 'Každý, kdo by se jen přiblížil k Hospodinovu příbytku, zemře. Což opravdu dočista zahyneme?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Hospodin řekl Áronovi: Ty a tvoji synové a dům tvého otce s tebou ponesete vinu spojenou se svatyní, ty a tvoji synové s tebou ponesete vinu spojenou s vaším kněžstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Také své bratry z pokolení Léviho, z kmene svého otce, přiveď s sebou. Připojí se k tobě a budou ti sloužit, zatímco ty a tvoji synové s tebou budete před stanem svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Budou konat službu pro tebe a službu celého stanu. Avšak k předmětům svatyně a k oltáři se nepřiblíží, aby nezemřeli ani oni ani vy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Připojí se k tobě a budou konat službu stanu setkávání a všechnu práci stanu. Nikdo jiný se k vám nepřiblíží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Vy budete konat službu svatyně a službu oltáře, aby na syny Izraele již nedopadlo rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Hle, vzal jsem vaše bratry Lévijce zprostřed synů Izraele jako dar pro vás, jako ty, kteří jsou dáni Hospodinu, aby konali práci stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Ty a tvoji synové s tebou dbejte na své kněžství ohledně všech věcí oltáře a ohledně toho, co je uvnitř za oponou, a tak služte. Jako ⌈darovanou službu⌉ vám dávám vaše kněžství. Když by se někdo jiný přiblížil, bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Hospodin promluvil k Áronovi: Hle, dal jsem ti službu svých darů pozdvihování ze všech svatých darů synů Izraele. Dal jsem je jako díl tobě a tvým synům jako věčný příděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Toto bude patřit tobě z nejsvětějších darů, ⌈ které nepřijdou na oheň:⌉ Každý jejich obětní dar ze všech jejich přídavných obětí, ze všech jejich obětí za hřích a ze všech jejich obětí za vinu, které mi přinesou jako nejsvětější dar, bude pro tebe a tvé syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Budeš ho jíst na nejsvětějším místě; každý mužského pohlaví ho bude jíst. Bude to pro tebe svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Také toto ti bude patřit: Dar pozdvihování z jejich darů, ze všech mávaných obětí synů Izraele. Dal jsem je tobě a tvým synům i tvým dcerám s tebou jako věčný příděl. Každý, kdo je ve tvém domě čistý, to smí jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Všechno to nejlepší z oleje, všechno to nejlepší z nového vína a obilí -- jejich prvotiny, které dají Hospodinu -- jsem dal tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Prvotiny ze všeho, co je v jejich zemi, co budou přinášet Hospodinu, budou patřit tobě. Každý, kdo je ve tvém domě čistý, to smí jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Všechno, co bylo v Izraeli zasvěceno zkáze, bude patřit tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Všechno, co otvírá lůno ze všeho tvorstva a co se přináší Hospodinu, ať z lidí či ze zvířat, bude patřit tobě. Avšak prvorozené z lidí jistě vykoupíš a také prvorozené z nečistých zvířat vykoupíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Jistě ho vykoupíš od věku jednoho měsíce podle svého výměru pěti šekely stříbra podle šekelu svatyně; ten je dvacet gér.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Avšak prvorozeného býka, prvorozenou ovci či prvorozeného kozla nevykoupíš; jsou svatí. Jejich krví pokropíš oltář a jejich tuk obětuješ jako ohnivou oběť, jako příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Jejich maso bude patřit tobě -- jak hrudí z mávané oběti, tak i pravá kýta bude patřit tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Všechny dary pozdvihování ze svatých darů, které synové Izraele přinášejí Hospodinu, jsem dal tobě a tvým synům i tvým dcerám s tebou jako věčný příděl. Je to věčná smlouva soli před Hospodinem pro tebe a pro tvé potomstvo s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Hospodin řekl Áronovi: V jejich zemi neobdržíš dědictví ani ti nebude patřit podíl uprostřed nich. Já jsem tvůj podíl a tvé dědictví uprostřed synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Hle, synům Léviho jsem dal do dědictví ⌈celý desátek⌉ v Izraeli jako náhradu za jejich službu, kterou vykonávají, službu při stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Synové Izraele se již nepřiblíží ke stanu setkávání, aby nenesli trest za hřích a nezemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Lévijci budou vykonávat službu při stanu setkávání, oni ponesou jejich vinu. To je věčné ustanovení po všechny vaše generace. Proto neobdrží dědictví uprostřed synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Protože desátek synů Izraele, který budou přinášet Hospodinu jako dar pozdvihování, jsem dal Lévijcům do dědictví, proto jsem o nich řekl: Uprostřed synů Izraele neobdrží dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Promluv k Lévijcům a řekni jim: Když přijmete od synů Izraele desátek, který jsem vám od nich dal jako váš dědičný podíl, přineste z něj Hospodinův dar pozdvihování, desátek z desátku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Váš dar pozdvihování vám bude počítán jako obilí z humna a jako plný výnos z lisu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tak přineste i vy Hospodinův dar pozdvihování ze všech svých desátků, které přijmete od synů Izraele, a dejte z toho Hospodinův dar pozdvihování knězi Áronovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Ze všech svých darů přineste celý Hospodinův dar pozdvihování, ze všeho to nejlepší, to, co je z toho svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Dále jim řekni: Když budete přinášet to nejlepší z něj, bude se to Lévijcům počítat jako výnos humna a jako výnos lisu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Můžete to jíst na jakémkoliv místě, vy i váš dům, protože je to vaše mzda jako náhrada za vaši službu při stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Neponesete za to hřích, když z toho přinesete to nejlepší. ⌈Tak neznesvětíte svaté dary synů Izraele a nezemřete.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Hospodin promluvil k Mojžíšovi a k Áronovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Toto je ustanovení zákona, které přikázal Hospodin: Pověz synům Izraele, aby k tobě přivedli rudou krávu bez vady, na které není vada a na kterou ne bylo vloženo jho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Dejte ji knězi Eleazarovi. Ten ať ji vyvede ven za tábor a ať ji zabijí v jeho přítomnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Kněz Eleazar ať vezme na svůj prst trochu její krve a stříkne krví sedmkrát směrem k přední straně stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Pak ať spálí krávu před jeho zrakem -- její kůži, maso a krev spálí spolu s jejími výměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Kněz ať vezme ⌈cedrové dřevo, yzop a karmínové barvivo⌉ a hodí to doprostřed ohně s krávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Kněz si vypere šaty, umyje si tělo vodou a potom vejde do tábora; avšak kněz bude až do večera nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Ten, kdo ji spálil, si vypere ve vodě šaty, umyje si tělo vodou a bude nečistý až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Pak čistý člověk sebere popel z krávy a uloží ho venku za táborem na čisté místo. Bude pro pospolitost synů Izraele uchován na očistnou vodu; je to na očištění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Ten, kdo sebere popel z krávy, si vypere šaty a bude nečistý až do večera. To bude věčné ustanovení pro syny Izraele i pro příchozího, který mezi nimi pobývá jako cizinec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kdo by se dotkl ⌈těla jakéhokoliv mrtvého člověka,⌉ bude po sedm dnů nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Třetího dne a sedmého dne se očistnou vodou očistí od hříchu a bude čistý. Jestliže se třetího a sedmého dne neočistí od hříchu, nebude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Kdokoliv by se dotkl ⌈těla mrtvého člověka,⌉ který zemřel, a neočistil by se od hříchu, znečistí Hospodinův příbytek. Takový člověk ať je z Izraele vyhlazen, neboť nebyl pokropen očistnou vodou. Bude nečistý, jeho nečistota bude stále na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Toto je zákon o člověku, který zemře ve stanu: Každý, kdo přijde do stanu, a každý, kdo je ve stanu, bude po sedm dní nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Každá otevřená nádoba, která na sobě nemá připevněné víko, bude nečistá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Kdokoliv by se ⌈v otevřené krajině⌉ dotkl zabitého mečem anebo mrtvého, lidských kostí či hrobu, bude po sedm dní nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Ať se vezme pro nečistého trochu popela z ohně očištění a dá se na něj pramenitá voda do nádoby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Potom ať vezme čistý člověk yzop, ponoří do vody a pokropí stan, všechny nádoby a lidi, kteří tam byli, i toho, kdo se dotkl kostí či zabitého, mrtvého či hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Čistý pokropí nečistého třetího dne i dne sedmého a tak jej sedmého dne očistí od hříchu. Vypere si šaty a umyje se vodou a večer bude čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Ten, kdo by byl nečistý a neočistil by se od hříchu, takový člověk ať je vyhlazen zprostřed shromáždění, protože znečistil Hospodinovu svatyni. Nebyl pokropen očistnou vodou, je nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Toto bude pro ně věčné ustanovení. Ten, kdo kropí očistnou vodou, si vypere šaty. Ten, kdo se dotkl očistné vody, bude do večera nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Čehokoliv by se nečistý dotkl, bude nečisté, a kdokoliv by se ho dotkl, bude až do večera nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Prvního měsíce přišli synové Izraele, celá ta pospolitost, na pustinu Sin a lid pobýval v Kádeši. Tam zemřela Mirjam a byla tam pohřbena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Pospolitost neměla vodu, a tak se shromáždili proti Mojžíšovi a Áronovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Lid se přel s Mojžíšem. Říkali: Kéž bychom zahynuli, když zahynuli naši bratři před Hospodinem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Proč jste přivedli ⌈Hospodinovo shromáždění⌉ do této pustiny, abychom tady zemřeli my i náš dobytek?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Proč jste nás vyvedli z Egypta, abyste nás přivedli na toto zlé místo? Není to místo zrna a fíků, vinné révy a granátových jablek, ani zde není voda na pití!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Mojžíš a Áron odešli od shromáždění ke vchodu do stanu setkávání a padli na tvář. I ukázala se jim Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Vezmi hůl, svolej pospolitost, ty i tvůj bratr Áron, a promluvte před jejich zrakem ke skále a vydá vodu. Vyvedeš jim vodu ze skály a dáš napít pospolitosti i jejich dobytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Mojžíš vzal hůl před Hospodinem, jak mu přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Mojžíš s Áronem svolali shromáždění před skálu a řekl jim: Teď poslyšte, vy vzpurníci. Copak vám máme vyvést vodu z této skály?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Mojžíš pozvedl ruku, dvakrát udeřil svou holí do skály i vyšlo množství vody a napila se pospolitost i jejich dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Hospodin však řekl Mojžíšovi a Áronovi: Protože jste mi nevěřili a nedosvědčili jste moji svatost před očima synů Izraele, proto nepřivedete toto shromáždění do země, kterou jsem jim dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Toto jsou Vody sváru, kde synové Izraele vedli při s Hospodinem a on se mezi nimi posvětil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Mojžíš poslal z Kádeše posly k edómskému králi: Toto praví tvůj bratr Izrael: Ty znáš všechny těžkosti, které nás postihly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Naši otcové sestoupili do Egypta; pobývali jsme v Egyptě po mnoho dní. Egypťané s námi a s našimi otci jednali zle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Když jsme křičeli k Hospodinu, uslyšel náš hlas, poslal anděla a vyvedl nás z Egypta. Hle, jsme v Kádeši, v městě na okraji tvého území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Dovol, ať projdeme tvou zemí. Nepotáhneme polem ani vinicí, nebudeme pít vodu ze studní; půjdeme královskou cestou, neuhneme napravo ani nalevo, dokud neprojdeme tvým územím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Edóm mu však odpověděl: ⌈Neprojdeš skrze mě,⌉ jinak proti tobě vytáhnu s mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Synové Izraele mu řekli: Půjdeme vzhůru po silnici, a jestliže se napijeme tvé vody, my a náš dobytek, ⌈zaplatíme za ni.⌉ Nic jiného, jenom chceme pěšky projít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'On ale odpověděl: Neprojdeš. A Edóm proti němu vytáhl s množstvím lidu a s ⌈velkou mocí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Edóm odmítl nechat Izrael projít přes své území a Izrael před ním uhnul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Synové Izraele, celá ta pospolitost, vyrazili z Kádeše a přišli na horu Hór.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Hospodin řekl Mojžíšovi a Áronovi na hoře Hór, na hranici edómské země:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Áron bude připojen ke svému lidu -- nevejde do země, kterou jsem dal synům Izraele, protože jste se vzepřeli mému příkazu při Vodách sváru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Vezmi Árona a jeho syna Eleazara a vyveď je na horu Hór.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Svlékni Áronovi jeho roucho a oblékni jej jeho synu Eleazarovi. Áron bude připojen ke svému lidu, zemře tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Mojžíš učinil, jak Hospodin přikázal. Před očima celé pospolitosti vystoupili na horu Hór.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Mojžíš svlékl Áronovi jeho roucho a oblékl jej jeho synu Eleazarovi. Áron tam zemřel na vrcholu hory. Mojžíš pak s Eleazarem sestoupil z hory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Když celá pospolitost viděla, že Áron skonal, celý dům izraelský oplakával Árona po třicet dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Když se kenaanský král Aradu sídlící v Negebu doslechl, že Izrael jde směrem k Atarímu, bojoval proti Izraeli a zajal z něj zajatce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Tehdy učinil Izrael slib Hospodinu: Jestliže opravdu vydáš tento lid do mé ruky, zasvětím jejich města zkáze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Hospodin vyslyšel Izrael a vydal mu Kenaance; i zasvětil je a jejich města zkáze. To místo pojmenovali Chorma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Pak vyrazili z hory Hóru směrem k Rákosovému moři, aby obešli edómskou zemi. Lid se stal cestou netrpělivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Lid mluvil proti Bohu a proti Mojžíšovi: Proč jste nás vyvedli z Egypta, abychom zemřeli v pustině? Vždyť tu není chléb ani voda. Znechutili jsme si tuto mizernou stravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Hospodin poslal na lid ohnivé hady a ti lid kousali. Mnoho lidu z Izraele pomřelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Lid přišel k Mojžíšovi a řekl: Zhřešili jsme, když jsme mluvili proti Hospodinu a proti tobě. Modli se k Hospodinu, aby od nás ty hady odstranil. Mojžíš se za lid modlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Hospodin řekl Mojžíšovi: Udělej si ohnivého hada a umísti ho na korouhev. I stane se, že každý kdo je kousnut, když se na něj podívá, zůstane naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Mojžíš udělal bronzového hada a umístil ho na korouhev. I stalo se, když had někoho uštkl a ten se podíval na bronzového hada, že zůstal naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Synové Izraele vyrazili a utábořili se v Obótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Pak vyrazili z Obótu a utábořili se v Ijé–abárímu, v pustině, která je naproti Moábu na východu slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Odtamtud vyrazili a utábořili se v údolí Zeredu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Odtamtud vyrazili a utábořili se za Arnónem, který je v pustině vycházející z emorejského území, neboť Arnón je moábskou hranicí mezi Moábem a Emorejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Proto se říká v Knize Hospodinových bojů: ... Vahéb v Súfě a údolí Arnónu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'sráz údolí, který se sklání k osadě Aru a opírá se o hranici Moábu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Odtamtud vyrazili do Beéru. To je ten Beér, kde Hospodin řekl Mojžíšovi: Shromáždi lid a dám jim vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Tehdy zpíval Izrael tuto píseň: Vytryskni, studno! Zpívejte o ní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'o studni, již vyhloubili předáci, šlechtici z lidu ji vykopali palcátem a svými holemi. A z pustiny vyrazili do Matany,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'z Matany do Nachaliélu, z Nachaliélu do Bamótu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'z Bamótu do údolí, které je na moábském území u vrcholu Pisgy, jež shlíží směrem k Ješímónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Izrael poslal posly k emorejskému králi Síchonovi se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Dovol, ať projdu tvou zemí. Neuhneme do pole ani vinice, nebudeme pít vodu ze studní; půjdeme královskou cestou, dokud neprojdeme tvým územím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Síchon však nedovolil Izraeli projít svým územím. Síchon shromáždil všechen svůj lid, vytáhl proti Izraeli do pustiny, přišel do Jahasu a bojoval proti Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Izrael ho pobil ostřím meče a obsadil jeho zemi od Arnónu až po Jabok, až k synům Amónovým, neboť hranice synů Amónových byla pevná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Izrael zabral všechna tato města. Izrael sídlil ve všech emorejských městech, v Chešbónu i ve všech jeho vesnicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Chešbón byl totiž městem emorejského krále Síchona. Ten bojoval proti dřívějšímu moábskému králi a vzal z jeho ruky celou jeho zemi až po Arnón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Proto ti, kdo užívají pořekadla, říkají: Pojďme do Chešbónu! Ať je zbudováno a upevněno město Síchonovo!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Neboť vyšlehl oheň z Chešbónu, plamen z města Síchonova a strávil Ar Moáb, pány arnónských návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Běda tobě, Moábe, zahynul lid Kemóšův! Učinil své syny utečenci a své dcery uvrhl do zajetí emorejského krále Síchona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, '⌈Stříleli jsme na ně;⌉ zahynul Chešbón až po Díbón. Pustošili jsme až po Nófach, který je u Médeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Izrael pobýval v zemi Emorejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Potom poslal Mojžíš prozkoumat Jaezer. Dobyli jeho vesnice a podrobili si Emorejce, kteří tam byli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Pak se vydali na cestu a táhli směrem k Bášanu. Bášanský král Óg se vším svým lidem vytáhl proti nim do boje k Edreí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Hospodin řekl Mojžíšovi: Neboj se ho, neboť jsem vydal do tvé ruky jej, všechen jeho lid i jeho zemi. Nalož s ním tak, jak jsi naložil s emorejským králem Síchonem sídlícím v Chešbónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'I pobíjeli ho, jeho syny a všechen jeho lid, až mu nezůstal nikdo, kdo by přežil, a obsadili jeho zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Synové Izraele vyrazili a utábořili se v moábských stepích na druhé straně Jordánu u Jericha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Balák, syn Sipórův, viděl všechno, co učinil Izrael Emorejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Moáb měl z lidu velký strach, neboť ho bylo mnoho. Moáb se synů Izraele děsil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Moáb řekl midjánským starším: Tento dav teď ⌈dočista spase⌉ všechno kolem nás, tak jako býk dočista spásá polní zeleň. Toho času byl moábským králem Balák, syn Sipórův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Ten poslal posly k Bileámovi, synu Beórovu, do Petóru, který je u Řeky, v zemi synů jeho lidu, aby ho zavolal se slovy: Hle, z Egypta vyšel národ a hle, pokryl tvář země a pobývá naproti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Nuže, prosím, pojď, proklej mi tento lid, neboť je mocnější nežli já. Snad ho potom budu moci pobít a vyhnat ze země. Vím totiž, že koho požehnáš, bude požehnán a koho prokleješ, bude proklet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Starší moábští a starší midjánští šli a měli s sebou odměnu za věštění. Přišli k Bileámovi a pověděli mu Balákova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'On jim řekl: Zůstaňte zde přes noc a odpovím vám to, co ke mně Hospodin promluví. Moábská knížata pobyla u Bileáma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Bůh přišel k Bileámovi a zeptal se ho: Kdo jsou ti muži u tebe?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileám Bohu odpověděl: Moábský král Balák, syn Sipórův, je ke mně poslal se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Je tu ten lid, který vyšel z Egypta a pokryl tvář země. Nuže pojď a proklej mi ho. Snad budu moci proti němu bojovat a vyhnat ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Bůh nato Bileámovi řekl: Nechoď s nimi a neproklínej tento lid, protože je požehnaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Ráno Bileám vstal a řekl Balákovým knížatům: Jděte do své země, protože Hospodin mi nechce dovolit jít s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Moábská knížata vstala, přišla k Balákovi a řekla: Bileám nechce s námi jít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Balák poslal další knížata, početnější a váženější nežli ta první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Když přišla k Bileámovi, řekla mu: Toto praví Balák, syn Sipórův: Nezdráhej se, prosím, přijít ke mně!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Převelice tě poctím a všechno, co mi řekneš, udělám. Pojď, prosím, proklej mi tento lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bileám odpověděl Balákovým otrokům: I kdyby mi dal Balák ⌈všechno stříbro a zlato, které je v jeho domě,⌉ nemohl bych přestoupit příkaz Hospodina, svého Boha, a udělat cokoliv ⌈malého či velkého.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Nicméně pobuďte tu i vy přes noc, abych se dozvěděl, co dalšího ke mně Hospodin promluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Bůh přišel k Bileámovi v noci a řekl mu: Když tě přišli tito muži zavolat, vstaň a jdi s nimi. Avšak uděláš pouze to, co ti povím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Bileám ráno vstal, osedlal svou oslici a šel s moábskými knížaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Bůh vzplanul hněvem, že Bileám šel; Hospodinův anděl se mu postavil do cesty jako protivník. On jel na své oslici a s ním byli dva jeho služebníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Oslice uviděla Hospodinova anděla, jak stojí na cestě a v ruce má tasený meč. Oslice uhnula z cesty a šla polem. Bileám však oslici bil, aby se vrátila na cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Pak se Hospodinův anděl postavil na pěšině mezi vinicemi; ⌈na jedné i druhé straně byla zeď.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Když oslice uviděla Hospodinova anděla, přitiskla se ke zdi a přitlačila ke zdi Bileámovu nohu. On ji znovu bil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Hospodinův anděl znovu přešel a postavil se na úzkém místě, kde nebylo možné uhnout napravo ani nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Když oslice uviděla Hospodinova anděla, lehla si pod Bileámem. Bileám vzplanul hněvem a bil oslici holí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Hospodin otevřel oslici ústa a ta řekla Bileámovi: Co jsem ti udělala, že jsi mě takto třikrát bil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileám oslici řekl: Vždyť se mi vysmíváš! Kdybych měl s sebou meč, tak bych tě teď zabil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Oslice Bileámovi řekla: Což nejsem tvá oslice? Jezdil jsi na mně odjakživa až dodnes. Měla jsem ve zvyku ti něco takového dělat? Odpověděl: Ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Hospodin odkryl Bileámovi oči, takže uviděl Hospodinova anděla, jak stojí na cestě a v ruce má tasený meč. Poklekl a poklonil se ⌈tváří k zemi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Hospodinův anděl se ho zeptal: Proč jsi takto třikrát bil svou oslici? Hle, já jsem vyšel jako tvůj protivník, neboť ⌈tato cesta je přede mnou pochybená.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Oslice mě uviděla a takto třikrát přede mnou uhnula. Kdyby přede mnou neuhnula, ano, tebe bych teď zabil, a ji bych nechal naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Bileám řekl Hospodinovu poslu: Zhřešil jsem, neboť jsem nevěděl, že ty stojíš proti mně na cestě. Nyní, jestliže ⌈je to zlé ve tvých očích,⌉ vrátím se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Hospodinův anděl řekl Bileámovi: Jdi s těmi muži. Ovšem jenom to slovo, které k tobě budu mluvit, to budeš mluvit. Bileám tedy šel s Balákovými knížaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Když se Balák doslechl, že Bileám přichází, vyšel mu vstříc do ⌈moábského města,⌉ které je na hranici Arnónu na konci území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Balák Bileámovi řekl: Cožpak jsem k tobě neposlal, aby tě zavolali? Proč jsi ke mně nepřišel? Opravdu tě nedokážu poctít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Bileám řekl Balákovi: Hle, teď jsem k tobě přišel. Budu ale moci vůbec něco promluvit? Slovo, které Bůh vloží do mých úst, to budu mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Bileám šel potom s Balákem a přišli do Kirjat–chusót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Balák obětoval skot a brav a poslal Bileámovi a knížatům, která byla s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'I stalo se ráno, že Balák vzal Bileáma a přivedl ho do Bamót–baalu, takže odtamtud viděl okraj lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Bileám řekl Balákovi: Postav mi zde sedm oltářů a připrav mi zde sedm býčků a sedm beranů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balák udělal to, co Bileám řekl. Pak Balák s Bileámem obětovali na každém oltáři býčka a berana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Nato řekl Bileám Balákovi: Postůj u své zápalné oběti, zatímco já odejdu. Snad ⌈se se mnou Hospodin setká⌉ a to, co mi ukáže, ti oznámím. Potom odešel na holé návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Bůh se setkal s Bileámem a ten mu řekl: Sedm oltářů jsem připravil a obětoval jsem na každém oltáři býčka a berana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Hospodin vložil Bileámovi do úst slovo a řekl mu: Vrať se k Balákovi a promluv takto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Vrátil se k němu a tam u jeho zápalné oběti stál on i všechna moábská knížata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'I pronesl svou průpověď: Z Aramu mě přivedl Balák, z východních hor moábský král: Pojď a proklej mi Jákoba, pojď a zlořeč Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Jak mohu proklínat, když ho Bůh neproklel, jak mohu zlořečit, když Hospodin nezlořečí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Jak na něj hledím z vrcholu skal, pozoruji jej z návrší, hle, je to lid, který bude přebývat ⌈odděleně, mezi⌉ národy nebude počítán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kdo spočítá Jákobův prach, kdo sečte čtvrtinu Izraele? Kéž by zemřela má duše smrtí přímých a můj konec ať je jako jeho!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Balák řekl Bileámovi: Cos mi to provedl? Nechal jsem tě přivést, abys proklel mé nepřátele, a hle, ty jim jen žehnáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Odpověděl: Což ne musím dbát na to, abych promluvil to, co mi Hospodin vloží do úst?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Potom mu Balák řekl: Pojď, prosím, se mnou na jiné místo, odkud ho uvidíš -- jenom jeho okraj uvidíš, celého ho neuvidíš -- a odtamtud mi ho proklej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Vzal ho do Sedesófímu na vrchol Pisgy. Postavil sedm oltářů a na každém oltáři obětoval býčka a berana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Bileám řekl Balákovi: Postůj zde u své zápalné oběti a já se s ním setkám tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Hospodin se setkal s Bileámem, vložil mu do úst slovo a řekl: Vrať se k Balákovi a promluv takto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Přišel k němu a tam u jeho zápalné oběti stál on a s ním moábská knížata. Balák se ho zeptal: Co promluvil Hospodin?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Nato pronesl svou průpověď: Vstaň, Baláku, a slyš, naslouchej mi, synu Sipórův!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Bůh není člověk, aby lhal, ani syn člověka, aby litoval. Což by on řekl a neučinil, promluvil a nenaplnil to?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Hle, dostal jsem příkaz žehnat; on požehnal, ne mohu to změnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Není vidět neštěstí v Jákobovi, nelze zahlédnout trápení v Izraeli. Hospodin, jeho Bůh, je s ním, královský pokřik je v něm slyšet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Bůh, který ho vyvedl z Egypta, je pro něj jako roh divokého tura.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Vždyť není zaklínadlo proti Jákobovi, není věštba proti Izraeli. Nyní bude řečeno o Jákobovi a o Izraeli: Hle, co Bůh vykonal!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Hle, povstává lid jako lvice, zvedá se jako lev. Neulehne, dokud nesežere kořist a ne napije se krve pobitých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Balák řekl Bileámovi: ⌈Když ho tedy neproklínáš, tak mu aspoň nežehnej!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileám Balákovi odpověděl: Což jsem ti neřekl: Vše, co Hospodin promluví, to učiním?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Balák řekl Bileámovi: Pojď, prosím, vezmu tě na jiné místo. Snad se to bude Bohu líbit a prokleješ mi ho odtamtud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Balák vzal Bileáma na vrchol Peóru, který shlíží směrem k Ješímónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Bileám řekl Balákovi: Postav mi zde sedm oltářů a připrav mi zde sedm býčků a sedm beranů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balák udělal to, co Bileám řekl, a obětoval na každém oltáři býčka a berana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Bileám viděl, že v ⌈Hospodinových očích je dobré⌉ žehnat Izraeli, a proto nešel jako předtím vyhlašovat zaklínadla, ale obrátil svou tvář k pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Bileám pozvedl oči a uviděl Izrael, jak přebývá ⌈podle svých kmenů,⌉ i spočinul na něm Boží Duch');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'a pronesl svou průpověď: Výrok Bileáma, syna Beórova, výrok muže se zavřeným okem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'výrok toho, jenž slyší Boží řeč, který vidí vidění Všemohoucího, padá ⌈a má otevřené oči:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Jak dobré jsou tvé stany, Jákobe, tvé příbytky, Izraeli!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Jako údolí se vinou, jako zahrady podél řeky, jako aloe, jež vysadil Hospodin, jako cedry u vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Poplyne voda z jeho věder a jeho semeno bude u množství vody. Jeho král bude vyvýšen nad Agaga a jeho království bude povzneseno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Bůh, který ho vyvedl z Egypta, je pro něj jako rohy divokého tura. Pohltí národy, své protivníky, jejich kosti rozhryže, srazí je svými šípy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Schoulil se a ulehl jako lev, jako lvice. Kdo ji přinutí povstat? Ti, kdo tobě budou žehnat, budou požehnáni, ti, kdo tě budou proklínat, budou prokleti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Balák vzplanul hněvem proti Bileámovi a tleskl rukama. Řekl Bileámovi: Zavolal jsem tě, abys proklel mé nepřátele, a hle, už třikrát jsi jen žehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Tak běž domů! Řekl jsem, že tě velice poctím, ale Hospodin ti poctu odepřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileám řekl Balákovi: Cožpak jsem také neřekl tvým poslům, které jsi ke mně poslal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'I kdyby mi dal Balák všechno stříbro a zlato, které je v jeho domě, nemohl bych přestoupit Hospodinův příkaz a udělat cokoliv dobrého či zlého ⌈z vlastního rozmaru.⌉ To, co Hospodin promluví, to budu mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Nyní tedy půjdu ke svému lidu. Pojď, poučím tě o tom, co tento lid učiní v budoucích dnech tvému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Nato pronesl svou průpověď: Výrok Bileáma, syna Beórova, výrok muže se zavřeným okem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'výrok toho, jenž slyší Boží řeči a zná poznání Nejvyššího, který vidí vidění Všemohoucího, padá a má otevřené oči:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Vidím ho, není to teď, sleduji ho, není to hned: Vyjde hvězda z Jákoba, povstane žezlo z Izraele a probodne skráně Moába, temeno všech synů Šétových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edóm se stane jeho vlastnictvím, i Seír, jeho nepřátelé, se stanou jeho vlastnictvím, ale Izrael si bude počínat udatně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Bude panovat ten, jenž vzejde z Jákoba, a odstraní z města ⌈ty, kteří přežili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Potom uviděl Amáleka a pronesl svou průpověď: Amálek je první z národů, ale jeho konec bude záhuba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Potom uviděl Kénijce a pronesl svou průpověď: Tvé sídlo je pevné, postavil sis hnízdo na skále,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'a přece přijde Kain vniveč; za jak dlouho tě Ašúr odvede?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'A pronesl svou průpověď: Běda! Kdo zůstane naživu, když Bůh toto učiní?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Lodě přijdou od Kitejců a pokoří Ašúra, pokoří Hebera a také on skončí v záhubě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Bileám vstal, šel a vrátil se domů. Také Balák šel svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Když pobýval Izrael v Šitímu, začal lid smilnit s moábskými ženami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Ty volaly lid k obětem svým bohům a lid jedl a klaněl se jejich bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Izrael se spřáhl s Baal–peórem a Hospodin vzplanul proti Izraeli hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Hospodin řekl Mojžíšovi: Vezmi všechny předáky lidu a pověs je před Hospodinem na slunci, aby se od Izraele odvrátil Hospodinův planoucí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Mojžíš řekl izraelským soudcům: Zabijte každý ty své muže, kteří se spřáhli s Baal–peórem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Vtom přišel kdosi ze synů Izraele a přivedl ke svým bratrům Midjánku před očima Mojžíše a před očima celé pospolitosti synů Izraele, zatímco oni plakali u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Když to uviděl kněz Pinchas, syn Eleazara, syna Áronova, vstal zprostřed pospolitosti, vzal oštěp,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'šel za tím Izraelcem do ženské části stanu a oba je probodl -- toho Izraelce i tu ženu až do jejího břicha. Tak zadržel tu ránu od synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Mrtvých při té ráně bylo dvacet čtyři tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Kněz Pinchas, syn Eleazara, syna Áronova, odvrátil můj hněv od synů Izraele, když uprostřed nich horlil mou horlivostí, takže jsem ve své žárlivosti neskoncoval se syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Proto řekni: Hle, ustanovuji s ním smlouvu pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Jemu a jeho potomstvu po něm bude věčnou smlouvou kněžství, protože horlil pro svého Boha a vykonal obřad smíření za syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Jméno zabitého izraelského muže, který byl zabit s Midjánkou, bylo Zimrí, syn Salův, předák otcovského domu Šimeónovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Jméno zabité midjánské ženy bylo Kozbí, dcera Súrova; ten byl kmenovým předákem otcovského domu v Midjánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Utlačujte Midjánce a pobijte je,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'neboť oni utlačovali vás svými podvody, když s vámi jednali podvodně v záležitosti Peóra a v záležitosti Kozbí, dcery midjánského předáka, své sestry, která byla zabita v den rány za Peórovu záležitost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 19, 'I stalo se po té ráně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'že Hospodin řekl Mojžíšovi a knězi Eleazarovi, synu Áronovu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Učiňte soupis celé pospolitosti synů Izraele od věku dvaceti let výše podle domu jejich otců, všech schopných v Izraeli táhnout s armádou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'I promluvil k nim Mojžíš s knězem Eleazarem v moábských stepích u Jordánu naproti Jerichu a řekli:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Spočítejte lid od dvaceti let věku výše -- tak jak přikázal Hospodin Mojžíšovi. A toto jsou synové Izraele, kteří vyšli z egyptské země:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Rúben, Izraelův prvorozený. Synové Rúbenovi: podle Chanóka čeleď Chanókovců, podle Palúa čeleď Palúovců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'podle Chesróna čeleď Chesrónců, podle Karmího čeleď Karmíovců —');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'toto jsou čeledi Rúbenovců. Spočítaných bylo čtyřicet tři tisíc sedm set třicet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Synové Palúovi: Elíab.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Synové Elíabovi: Nemúel, Dátan a Abíram. To byli Dátan a Abíram, vyvolení pospolitosti, kteří se hádali s Mojžíšem a Áronem v Kórachově pospolitosti, když se hádala s Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Země otevřela svůj chřtán a pohltila je i Kóracha, když zemřela pospolitost, když oheň strávil dvě stě padesát mužů. I stali se výstražným znamením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Ale synové Kórachovi nezemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Synové Šimeónovi podle svých čeledí: podle Nemúela čeleď Nemúelovců, podle Jamína čeleď Jamínovců, podle Jakína čeleď Jakínovců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'podle Zeracha čeleď Zerachejců, podle Šaúla čeleď Šaúlovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Toto jsou čeledi Šimeónovců: dvacet dva tisíc dvě stě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Synové Gádovi podle svých čeledí: podle Sefóna čeleď Sefónců, podle Chagího čeleď Chagíjců, podle Šúniho čeleď Šúnijců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Podle Ozního čeleď Ozníjců, podle Ériho čeleď Érijců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'podle Aróda čeleď Aródovců, podle Aréliho čeleď Arélijců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Toto jsou čeledi synů Gádových, jak byly spočítány: čtyřicet tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Synové Judovi: Ér a Ónan. Ér i Ónan zemřeli v kenaanské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Synové Judovi podle svých čeledí byli: podle Šély čeleď Šélovců, podle Peresa čeleď Peresovců, podle Zeracha čeleď Zerachejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Synové Peresovi byli: podle Chesróna čeleď Chesrónců, podle Chámula čeleď Chámulovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Toto jsou čeledi Judejců, jak byly spočítány: sedmdesát šest tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Synové Isacharovi podle svých čeledí: podle Tóly čeleď Tólaovců, podle Púvy čeleď Púvaovců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'podle Jašúba čeleď Jašúbců, podle Šimróna čeleď Šimrónců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Toto jsou čeledi Isacharovců, jak byly spočítány: šedesát čtyři tisíc tři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Synové Zabulónovi podle svých čeledí: podle Sereda čeleď Seredovců, podle Elóna čeleď Elónců, podle Jachleela čeleď Jachleelců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Toto jsou čeledi Zabulónovců, jak byly spočítány: šedesát tisíc pět set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Synové Josefovi podle svých čeledí, Manases a Efrajim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Synové Manasesovi: podle Makíra čeleď Makírovců; Makír zplodil Gileáda, podle Gileáda čeleď Gileádovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Toto jsou synové Gileádovi: podle Íezera čeleď Íezerovců, podle Cheleka čeleď Chelekovců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'podle Asríela čeleď Asríelovců, podle Šekema čeleď Šekemovců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'podle Šemídy čeleď Šemídovců, podle Chefera čeleď Cheferovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Selofchad, syn Cheferův, neměl syny, ale jenom dcery. Selofchadovy dcery se jmenovaly: Machla, Nóa, Chogla, Milka a Tirsa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Toto jsou čeledi Manasesovy, jak byly spočítány: padesát dva tisíc sedm set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Toto jsou synové Efrajimovi podle svých čeledí: podle Šútelacha čeleď Šútelachovců, podle Bekera čeleď Bekerovců, podle Tachana čeleď Tachanovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Toto jsou synové Šútelachovi: podle Érana čeleď Éranovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Toto jsou čeledi synů Efrajimových, jak byly spočítány: třicet dva tisíc pět set. To jsou synové Josefovi podle svých čeledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Synové Benjamínovi podle svých čeledí: Podle Bely čeleď Belovců, podle Ašbela čeleď Ašbelovců, podle Achírama čeleď Achíramců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'podle Šefúfama čeleď Šefúfamců, podle Chúfama čeleď Chúfamců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Synové Belovi byli: Ard a Naamán. Podle Arda čeleď Ardejců, podle Naamána čeleď Naamánců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Toto jsou synové Benjamínovi podle svých čeledí, jak byli spočítáni: čtyřicet pět tisíc šest set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Toto jsou synové Danovi podle svých čeledí: podle Šúchama čeleď Šúchamců. Toto jsou čeledi Danovy podle svých čeledí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'všechny čeledi Šúchamců, jak byly spočítány: šedesát čtyři tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Synové Ašerovi podle svých čeledí: podle Jimny čeleď Jimnajců, podle Jišvího čeleď Jišvíjců, podle Beríy čeleď Beríjců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Podle synů Beríových: podle Chebera čeleď Cheberovců, podle Malkíela čeleď Malkíelovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Ašerova dcera se jmenovala Serach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Toto jsou čeledi synů Ašerových, jak byly spočítány: padesát tři tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Synové Neftalího podle svých čeledí: podle Jachasíela čeleď Jachasíelců, podle Gúního čeleď Gúníjců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'podle Jesera čeleď Jeserovců, podle Šiléma čeleď Šilémovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Toto jsou čeledi Neftalího podle svých čeledí, jak byly spočítány: čtyřicet pět tisíc čtyři sta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Toto jsou spočítaní synové Izraele: šest set jeden tisíc sedm set třicet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Těmto bude rozdělena země do dědictví podle jmenovitého výčtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Většímu dáš větší dědictví, menšímu dáš menší dědictví. Každému bude dáno dědictví podle počtu jeho spočítaných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Země bude rozdělena losem, podle jmen svých otcovských pokolení obdrží dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Podle losu bylo rozděleno dědictví, mezi většího i menšího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'A toto jsou spočítaní Lévijci podle svých čeledí: podle Geršóna čeleď Geršónovců, podle Kehata čeleď Kehatovců a podle Merarího čeleď Meraríjců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Toto jsou čeledi Lévijců: čeleď Libníjců, čeleď Chebrónců, čeleď Machlíjců, čeleď Mušíjců, čeleď Kórachovců. Kehat zplodil Amráma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Amrámova žena se jmenovala Jókebed, dcera Léviho, která se narodila Lévimu v Egyptě. Porodila Amrámovi Árona, Mojžíše a jejich sestru Mirjam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Áronovi se narodil Nádab, Abíhú, Eleazar a Ítamar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Nádab a Abíhú však zemřeli, když přinesli před Hospodina cizí oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Jejich spočítaných bylo dvacet tři tisíc, všichni mužského pohlaví od jednoho měsíce výše. Nebyli totiž počítáni mezi syny Izraele, protože jim nebylo dáno dědictví mezi syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Toto jsou ti, které spočítal Mojžíš s knězem Eleazarem, když počítali syny Izraele v moábských stepích u Jordánu naproti Jerichu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Mezi nimi nebyl nikdo ze spočítaných Mojžíšem a knězem Áronem, když počítali syny Izraele v Sínajské pustině,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'neboť Hospodin o nich řekl: Jistě zemřou v této pustině. Nezůstal z nich nikdo, kromě Káleba, syna Jefunova, a Jozua, syna Núnova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'I předstoupily dcery Selofchada, syna Chefera, syna Gileáda, syna Makíra, syna Manasesa, z čeledi Manasesa, syna Josefova. Toto jsou jména jeho dcer: Machla, Nóa, Chogla, Milka a Tirsa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Postavily se před Mojžíše, před kněze Eleazara, před předáky a celou pospolitost ke vchodu do stanu setkávání a řekly:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Náš otec zemřel v pustině, ale nebyl v pospolitosti, která se smluvila proti Hospodinu, v pospolitosti Kórachově, nýbrž zemřel za svůj hřích. Neměl však syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Proč by mělo být vynecháno jméno našeho otce z jeho čeledi proto, že neměl syna? Dej nám vlastnictví mezi bratry našeho otce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mojžíš přinesl jejich právní záležitost před Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'A Hospodin řekl Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Selofchadovy dcery promluvily správně. Rozhodně jim dej dědičné vlastnictví mezi bratry jejich otce, převeď na ně dědictví jejich otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'A k synům Izraele promluv takto: Jestliže někdo zemře a nemá syna, převedete jeho dědictví na jeho dceru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Pokud neměl dceru, dáte jeho dědictví jeho bratrům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Pokud neměl bratry, dáte jeho dědictví bratrům jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'A pokud neměl jeho otec bratry, dáte jeho dědictví jeho nejbližšímu příbuznému z jeho čeledi; dostane ho do vlastnictví. Toto bude právním ustanovením pro syny Izraele, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Hospodin řekl Mojžíšovi: Vystup do tohoto pohoří Abarím a podívej se na zemi, kterou jsem dal synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Až se na ni podíváš, také ty budeš připojen ke svému lidu, tak jako byl připojen tvůj bratr Áron,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'protože jste se vzepřeli mému příkazu v pustině Sinu, při sváru pospolitosti a ne dosvědčili jste moji svatost pomocí vod před jejich očima. Toto jsou vody sváru v Kádeši v pustině Sinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Mojžíš promluvil k Hospodinu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Ať Hospodin, Bůh duchů celého tvorstva, ustanoví nad pospolitostí muže,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'který by vycházel před nimi a vcházel a který by je vyváděl a přiváděl. Ať není Hospodinova pospolitost jako ovce, které nemají pastýře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Hospodin řekl Mojžíšovi: Vezmi si Jozua, syna Núnova, muže, v němž je duch, a vlož na něj ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Postav ho před kněze Eleazara a před celou pospolitost a ustanov ho před jejich očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Vlož na něj ze své důstojnosti, aby ho poslouchala celá pospolitost synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Postaví se ovšem před kněze Eleazara a ten se pro něj bude před Hospodinem doptávat na rozhodnutí pomocí urím. Na jeho příkaz budou vycházet a na jeho příkaz budou vcházet, on i všichni synové Izraele s ním, celá pospolitost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mojžíš udělal tak, jak mu Hospodin přikázal. Vzal Jozua, postavil ho před kněze Eleazara a před celou pospolitost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'vložil na něj ruce a ustanovil ho, jak promluvil Hospodin prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Přikaž synům Izraele a řekni jim: Dbejte, abyste mi přinášeli v určený čas můj obětní dar, můj pokrm, jako mé ohnivé oběti, jako příjemnou vůni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Řekni jim: Toto je ohnivá oběť, kterou budete přinášet Hospodinu: Dva roční beránky bez vady denně jako ustavičnou zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Jednoho beránka připravíš ráno a druhého beránka připravíš navečer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'A jako přídavnou oběť desetinu éfy jemné mouky namísené se čtvrtinou hínu panenského oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'To je ustavičná zápalná oběť ustanovená na hoře Sínaj jako příjemná vůně, ohnivá oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'A k tomu patřičná litá oběť: čtvrtina hínu na každého beránka. Litou oběť opojného nápoje Hospodinu vylij ve svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Druhého beránka připravíš navečer -- připravíš to stejně jako ranní přídavnou oběť a stejně jako patřičnou litou oběť, jako ohnivou oběť, příjemnou vůni Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'V sobotní den: dva roční beránky bez vady a dvě desetiny jemné mouky namísené s olejem jako přídavnou oběť a patřičnou litou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'To je sobotní zápalná oběť v každou sobotu kromě ustavičné zápalné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Na počátku vašich měsíců přinesete jako zápalnou oběť Hospodinu dva býčky, jednoho berana a sedm ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'a jako přídavnou oběť na každého býčka tři desetiny jemné mouky namísené s olejem a jako přídavnou oběť na každého berana dvě desetiny jemné mouky namísené s olejem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'a jako přídavnou oběť na každého beránka jednu desetinu jemné mouky namísené s olejem. To bude zápalná oběť, příjemná vůně, ohnivá oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Patřičné lité oběti budou: Polovina hínu vína na býčka, třetina hínu na berana a čtvrtina hínu na beránka. To je měsíční zápalná oběť v každém měsíci po všechny měsíce v roce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'A jeden chlupatý kozel jako oběť za hřích bude Hospodinu připraven kromě ustavičné zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Prvního měsíce, čtrnáctého dne toho měsíce, bude velikonoční oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Patnáctého dne toho měsíce bude svátek; po sedm dní se budou jíst nekvašené chleby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Prvního dne bude svaté shromáždění. Nebudete dělat žádnou všední práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Jako ohnivou oběť, zápalnou oběť Hospodinu, přinesete dva býčky, jednoho berana a sedm ročních beránků; budou bez vady!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Jako patřičnou přídavnou oběť připravíte jemnou mouku namísenou s olejem, tři desetiny na býčka, dvě desetiny na berana;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'jednu desetinu připravíš na každého beránka ze sedmi beránků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'K tomu jednoho kozla jako oběť za hřích k vykonání obřadu smíření za vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Kromě ranní zápalné oběti, která je ustavičnou zápalnou obětí, připravíte toto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'To budete připravovat denně po sedm dní jako pokrm ohnivé oběti, příjemnou vůni Hospodinu; to se bude připravovat kromě ustavičné zápalné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'A sedmého dne budete mít svaté shromáždění. Nebudete dělat žádnou všední práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'V den prvotin, kdy přinesete Hospodinu novou přídavnou oběť, ve váš svátek týdnů budete mít svaté shromáždění. Nebudete dělat žádnou všední práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Jako zápalnou oběť, příjemnou vůni Hospodinu, přinesete dva býčky, jednoho berana a sedm ročních beránků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'A jako patřičnou přídavnou oběť jemnou mouku namísenou s olejem, tři desetiny na každého býčka, dvě desetiny na každého berana');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'a jednu desetinu na každého beránka ze sedmi beránků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'K tomu jednoho chlupatého kozla k vykonání obřadu smíření za vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'To připravíte kromě ustavičné zápalné oběti a patřičné přídavné oběti -- budou bez vady -- a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Sedmého měsíce, prvního dne toho měsíce, budete mít svaté shromáždění; nebudete dělat žádnou všední práci. Budete mít den troubení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Jako zápalnou oběť, příjemnou vůni Hospodinu, připravíte jednoho býčka, jednoho berana a sedm ročních beránků bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'A jako patřičnou přídavnou oběť jemnou mouku namísenou s olejem -- tři desetiny na býčka, dvě desetiny na berana');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'a jednu desetinu na každého beránka ze sedmi beránků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'K tomu jednoho chlupatého kozla jako oběť za hřích k vykonání obřadu smíření za vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'To kromě měsíční zápalné oběti a patřičné přídavné oběti, ustavičné zápalné oběti a patřičných litých obětí podle nařízení o nich, jako příjemnou vůni, ohnivou oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Desátého dne sedmého měsíce budete mít svaté shromáždění a budete pokořovat své duše. Nebudete dělat žádnou práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Jako zápalnou oběť Hospodinu, příjemnou vůni, přinesete jednoho býčka, jednoho berana, sedm ročních beránků -- budou bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'a jako patřičnou přídavnou oběť jemnou mouku namísenou s olejem -- tři desetiny na býčka, dvě desetiny na jednoho berana');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'a jednu desetinu na každého beránka ze sedmi beránků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'k tomu jednoho chlupatého kozla jako oběť za hřích kromě oběti za hřích na smíření, ustavičné zápalné oběti, patřičné přídavné oběti a patřičných litých obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Patnáctého dne sedmého měsíce budete mít svaté shromáždění. Nebudete dělat žádnou všední práci. Po sedm dní budete slavit svátek Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Jako zápalnou oběť, ohnivou oběť, příjemnou vůni Hospodinu přinesete třináct býčků, dva berany a čtrnáct ročních beránků -- budou bez vady,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'a jako patřičnou přídavnou oběť jemnou mouku namísenou s olejem -- tři desetiny na každého býčka ze třinácti býčků, dvě desetiny na každého berana ze dvou beranů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'a jednu desetinu na každého beránka ze čtrnácti beránků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'K tomu jednoho chlupatého kozla jako oběť za hřích kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Druhého dne: dvanáct býčků, dva berany, čtrnáct ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'a patřičnou přídavnou oběť, patřičné lité oběti na býčky, na berany a na beránky v patřičném počtu podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'K tomu jednoho chlupatého kozla jako oběť za hřích kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičných litých obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Třetího dne: jedenáct býčků, dva berany, čtrnáct ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'a patřičnou přídavnou oběť, patřičnou litou oběť na býčky, na berany a na beránky v patřičném počtu podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'K tomu jednoho kozla jako oběť za hřích kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Čtvrtého dne: deset býčků, dva berany, čtrnáct ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'a patřičnou přídavnou oběť, patřičné lité oběti na býčky, na berany a na beránky v patřičném počtu podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'K tomu jednoho chlupatého kozla jako oběť za hřích kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Pátého dne: devět býčků, dva berany, čtrnáct ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'a patřičnou přídavnou oběť, patřičné lité oběti na býčky, na berany a na beránky v patřičném počtu podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'K tomu jednoho kozla jako oběť za hřích kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Šestého dne: osm býčků, dva berany, čtrnáct ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'a patřičnou přídavnou oběť, patřičné lité oběti na býčky, na berany a na beránky v patřičném počtu podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'K tomu jednoho kozla jako oběť za hřích kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Sedmého dne: sedm býčků, dva berany, čtrnáct ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'a patřičnou přídavnou oběť, patřičnou litou oběť na býčky, na berany a na beránky v patřičném počtu podle nařízení o nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'K tomu jednoho kozla kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Osmého dne budete mít shromáždění. Nebudete dělat žádnou všední práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Jako zápalnou oběť, ohnivou oběť, příjemnou vůni Hospodinu přinesete jednoho býčka, jednoho berana, sedm ročních beránků bez vady');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'a patřičnou přídavnou oběť a patřičné lité oběti na býčka, na berana a na beránky v patřičném počtu podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'K tomu jednoho kozla jako oběť za hřích kromě ustavičné zápalné oběti, patřičné přídavné oběti a patřičné lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Toto připravíte Hospodinu o svých svátcích kromě svých slíbených a dobrovolných obětí jako své zápalné oběti, přídavné oběti, lité oběti a pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Mojžíš řekl synům Izraele všechno, co Hospodin Mojžíšovi přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Nato Mojžíš promluvil k předákům pokolení synů Izraele: ⌈Toto je to, co přikázal⌉ Hospodin:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Jestliže muž učiní slib Hospodinu či složí přísahu, že ⌈bere na sebe závazek,⌉ ať nezruší své slovo; splní vše, co vyšlo z jeho úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Jestliže však žena učiní slib Hospodinu a vezme na sebe závazek v domě svého otce ve svém mládí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'když její otec uslyší její slib a její závazek, který na sebe vzala, a když k tomu bude její otec mlčet, všechny její sliby platí a každý závazek, který na sebe vzala, platí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Jestliže jí však její otec v den, kdy uslyší všechny její sliby a její závazky, které na sebe vzala, zabrání, neplatí to a Hospodin jí odpustí, protože její otec jí zabránil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Jestliže se vdá a budou na ní její sliby či ⌈unáhlený výrok,⌉ kterým se zavázala,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'a její muž to uslyší, jestliže v den, kdy to uslyší, k tomu bude mlčet, její sliby platí i její závazek, který na sebe vzala, platí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Jestliže jí však její muž v den, kdy to uslyší, zabrání a zruší její slib, který je na ní, a unáhlený výrok, kterým se zavázala, Hospodin jí odpustí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Slib vdovy či zapuzené ženy, vše, co na sebe vzala, platí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Jestliže učiní slib či vezme na sebe s přísahou závazek v domě svého muže');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'a její muž to uslyší, bude k tomu mlčet a nezabrání jí, všechny její sliby platí i každý závazek, který na sebe vezme, platí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Jestliže je však její muž v den, kdy to uslyší, zruší, vše, co vyšlo z jejích rtů jako její slib či jako závazek, neplatí, její muž je zrušil a Hospodin jí odpustí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Každý slib a každý přísežný závazek k sebepokoření ať potvrdí její muž nebo ať její muž zruší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Jestliže k tomu bude její muž do druhého dne zarytě mlčet, učiní platnými všechny její sliby anebo všechny její závazky, které jsou na ní. Učinil je platnými, neboť v den, kdy to uslyšel, k tomu mlčel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Jestliže je však zruší později, než to uslyšel, ponese její vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Toto jsou ustanovení, která přikázal Hospodin Mojžíšovi, mezi mužem a jeho ženou a mezi otcem a jeho dcerou, dokud je ve svém mládí v domě svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Jistě pomsti syny Izraele na Midjáncích; potom budeš připojen ke svému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Mojžíš promluvil k lidu: Vyzbrojte mezi sebou muže pro ⌈válečné tažení,⌉ aby padli na Midjánce a vykonali na Midjáncích Hospodinovu pomstu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Pošlete na válečné tažení vždy po tisíci mužích z pokolení za každé izraelské pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Tak bylo vybráno z izraelských rodů tisíc za pokolení, dvanáct tisíc vojenských ozbrojenců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Mojžíš je poslal na válečné tažení, tisíc za pokolení, a s nimi Pinchasa, syna Eleazarova, jako kněze na válečném tažení, který s sebou měl posvátné předměty a poplašné trubky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Nato vytáhli do boje proti Midjáncům, jak přikázal Hospodin Mojžíšovi, a pobili všechny mužského pohlaví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Kromě jiných pobitých zabili midjánské krále Evího, Rekema, Súra, Chúra a Rebu a také Bileáma, syna Beórova, zabili mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Synové Izraele zajali midjánské ženy, jejich malé děti, všechen jejich dobytek i všechna jejich stáda a uloupili všechen jejich majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Všechna jejich města, v místech kde sídlili, a všechna jejich hradiště spálili ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Pobrali všechnu kořist a všechen lup z lidí i z dobytka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Přivedli zajatce, lup a kořist k Mojžíšovi, ke knězi Eleazarovi a k pospolitosti synů Izraele do tábora v moábských stepích u Jordánu naproti Jerichu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Mojžíš, kněz Eleazar a všichni předáci pospolitosti jim vyšli naproti ven za tábor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Mojžíš se rozhněval na ustanovené nad vojskem, velitele nad tisíci a velitele nad sty, kteří přicházeli z válečného tažení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Mojžíš jim řekl: Vy jste nechali naživu všechny ženy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Vždyť to byly ony, kdo podle Bileámova slova podnítily syny Izraele k věrolomnosti vůči Hospodinu v Peórově záležitosti, takže na Hospodinovu pospolitost dopadla rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Nyní proto zabijte všechny chlapce mezi dětmi a zabijte všechny ženy, které poznaly soulož s mužem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Všechny ⌈mladé ženy,⌉ které nepoznaly soulož s mužem, nechte naživu pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Vy pak se po sedm dní utábořte venku za táborem. Každý, kdo někoho zabil, a každý, kdo se dotkl zabitého, se bude třetího a sedmého dne očišťovat od hříchu, vy i vaši zajatci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Očistěte od hříchu všechny oděvy, všechny kožené předměty, vše vyrobené z kozí srsti a všechny dřevěné předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Kněz Eleazar řekl vojákům, kteří vytáhli do boje: Toto je ustanovení zákona, které přikázal Hospodin Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Ovšem zlato, stříbro, bronz, železo, cín a olovo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'všechny věci, které procházejí ohněm, provedete ohněm a budou čisté; avšak musí být očištěny od hříchu očistnou vodou. Všechno, co neprochází ohněm, provedete vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Sedmého dne si vyperete šaty a budete čistí. Potom smíte vejít do tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Hospodin řekl Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Ty s knězem Eleazarem a s předáky rodů pospolitosti učiň soupis zajatého lupu, lidí i dobytka');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'a rozděl lup mezi ty, kteří se zapojili do boje a vytáhli na válečné tažení, a mezi celou pospolitost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Vyber dávku pro Hospodina: Od bojovníků, kteří vytáhli na válečné tažení, po jednom z pěti set -- z lidí, ze skotu, z oslů a z ovcí;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'vezměte to z jejich poloviny a dej to knězi Eleazarovi jako Hospodinův dar pozdvihování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'A z té poloviny pro syny Izraele vezmi po jednom z padesáti, z lidí, ze skotu, z oslů a z ovcí, ze všeho dobytka, a dej to Lévijcům, kteří konají službu v Hospodinově příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Mojžíš a kněz Eleazar učinili tak, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Zbytek lupu z kořisti, kterou ukořistil ⌈válečný lid,⌉ byl: šest set sedmdesát pět tisíc ovcí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'sedmdesát dva tisíc býků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'šedesát jeden tisíc oslů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'a lidí, žen, které nepoznaly soulož s mužem, celkem třicet dva tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Poloviční podíl těch, kteří vytáhli na válečné tažení, byl tento počet: tři sta třicet sedm tisíc pět set ovcí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'a dávka z ovcí pro Hospodina byla šest set sedmdesát pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'býků bylo třicet šest tisíc a dávka z nich pro Hospodina sedmdesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'oslů bylo třicet tisíc pět set a dávka z nich pro Hospodina šedesát jeden;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'lidí bylo šestnáct tisíc a dávka z nich pro Hospodina byla třicet dva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Mojžíš dal dávku jako Hospodinův dar pozdvihování knězi Eleazarovi tak, jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Z poloviny pro syny Izraele, kterou Mojžíš oddělil od části pro muže, kteří vytáhli do boje');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '-- tato polovina pro pospolitost byla: tři sta třicet sedm tisíc pět set ovcí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'třicet šest tisíc býků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'třicet tisíc pět set oslů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'a šestnáct tisíc lidí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, '-- z této poloviny pro syny Izraele vzal Mojžíš po jednom z padesáti, z lidí i z dobytka, a dal to Lévijcům, kteří konají službu v Hospodinově příbytku, tak jak přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Ustanovení, kteří byli nad vojenskými oddíly, velitelé nad tisíci a velitelé nad sty, přistoupili k Mojžíšovi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'a řekli Mojžíšovi: Tvoji otroci učinili soupis bojovníků, kteří jsou pod naším velením, a nikdo z nás nechybí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Přinesli jsme Hospodinův obětní dar, každý to, co našel: zlaté předměty, spony a náramky, pečetní prsteny, náušnice a řetízky k vykonání obřadu smíření za nás před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Mojžíš a kněz Eleazar od nich vzali to zlato, všelijaké umně vyrobené předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Všechno zlato od velitelů nad tisíci a velitelů nad sty, které přinesli jako dar pozdvihování Hospodinu, vážilo šestnáct tisíc sedm set padesát šekelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Vojáci loupili každý pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Mojžíš a kněz Eleazar vzali to zlato od velitelů nad tisíci a nad sty a přinesli ho do stanu setkávání jako připomínku synů Izraele před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Synové Rúbenovi a synové Gádovi měli množství dobytka, bylo ho bezpočet. Když uviděli zemi Jaezer a zemi Gileád, hle, to místo bylo místem vhodným pro dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Synové Gádovi a synové Rúbenovi proto šli a řekli Mojžíšovi, knězi Eleazarovi a předákům pospolitosti:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarót, Díbón, Jaezer, Nimrá, Chešbón, Eleále, Sebám, Nebó a Beón --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'země, kterou Hospodin vybil před pospolitostí Izraele, je zemí vhodnou pro dobytek a tvoji otroci mají dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'A dále řekli: Jestliže jsme nalezli milost ve tvých očích, ať je tato země dána tvým otrokům do vlastnictví. Nepřeváděj nás přes Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mojžíš odpověděl synům Gádovým a synům Rúbenovým: Cožpak vaši bratři půjdou do boje a vy zůstanete zde?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Proč berete synům Izraele odvahu, aby přešli do země, kterou jim dal Hospodin?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Tak jednali vaši otcové, když jsem je poslal z Kádeš–barneje, aby prohlédli zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Prošli až do údolí Eškólu, prohlédli zemi a vzali synům Izraele odvahu, aby šli do země, kterou jim dal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Onoho dne vzplanul Hospodin hněvem a přísahal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Muži, kteří vyšli z Egypta, od dvacetiletých výše, neuvidí zemi, o níž jsem přísahal Abrahamovi, Izákovi a Jákobovi, protože nešli za mnou naplno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'kromě Kenazejce Káleba, syna Jefunova, a Jozua, syna Núnova, protože ti šli naplno za Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Proto Hospodin vzplanul hněvem proti Izraelcům, nechal je bloudit čtyřicet let pustinou, dokud nebyla zcela vyhlazena celá generace, která ⌈páchala to, co je zlé v Hospodinových očích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'A hle, povstali jste vy, potomstvo hříšníků, na místo svých otců, abyste ještě zvýšili Hospodinův planoucí hněv proti Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Když se od něj odvrátíte, ponechá ho nadále v pustině a zničíte celý tento lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Nato k němu přistoupili a řekli: Postavíme zde ohrady pro svůj dobytek a města pro své děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'My sami se však rychle vyzbrojíme a půjdeme před syny Izraele, dokud je nepřivedeme na jejich místo, zatímco naše děti zůstanou v opevněných městech chráněny před obyvateli této země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nevrátíme se do svých domovů, dokud synové Izraele neobdrží každý své dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Neobdržíme dědictví s nimi za Jordánem a tam dále, protože jsme dostali své dědictví na druhé straně Jordánu na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Mojžíš jim řekl: Jestliže budete jednat, jak jste řekli, jestliže se vyzbrojíte před Hospodinem do boje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'celé vaše vojsko projde Jordán před Hospodinem, dokud před sebou nepodrobí své nepřátele');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'a dokud země ne bude podmaněna před Hospodinem, a teprve potom se vrátíte, tehdy budete nevinní před Hospodinem a před Izraelem a tato země se stane vaším vlastnictvím před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Pokud však nebudete takto jednat, hle, zhřešíte proti Hospodinu a vězte, že váš hřích vás dostihne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Postavte si města pro své děti a ohrady pro svůj brav a splňte to, co vyšlo z vašich úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Synové Gádovi a synové Rúbenovi řekli Mojžíšovi: Tvoji otroci udělají to, co pán přikazuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Naše děti, naše ženy, naše stáda a všechen náš dobytek zůstane tam v gileádských městech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'ale tvoji otroci, všichni vojenští ozbrojenci, projdou před Hospodinem do boje, jak říká pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Potom o nich Mojžíš vydal příkaz knězi Eleazarovi, Jozuovi, synu Núnovu, a předákům rodů pokolení synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Mojžíš jim řekl: Jestliže synové Gádovi a synové Rúbenovi projdou s vámi Jordánem, všichni ozbrojenci, do boje před Hospodinem, až bude země před vámi podmaněna, dejte jim do vlastnictví gileádskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Jestliže však s vámi ozbrojenci neprojdou, ať mají vlastnictví mezi vámi v kenaanské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Synové Gádovi a synové Rúbenovi odpověděli: Jak Hospodin promluvil o tvých otrocích, tak uděláme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Projdeme jako ozbrojenci před Hospodinem do kenaanské země a budeme mít dědičné vlastnictví zde za Jordánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Jim, synům Gádovým, synům Rúbenovým a polovině kmene Manasesa, syna Josefova, dal Mojžíš království emorejského krále Síchona a království bášanského krále Óga, zemi s jejími městy a územím okolo měst té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Synové Gádovi postavili Díbón, Atarót, Aróer,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atarót–šófan, Jaezer, Jogbohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bét–nimru a Bét–háran, opevněná města a ohrady pro ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Synové Rúbenovi postavili Chešbón, Eleále, Kirjátajim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebó, Baal–meón -- se změněnými jmény -- i Sibmu a přejmenovali města, která postavili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Synové Makíra, syna Manasesova, táhli do Gileádu, dobyli ho a podrobili si Emorejce, kteří v něm byli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Mojžíš dal Gileád Makírovi, synu Manasesovu, a on ⌈v něm sídlil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jaír, syn Manasesův, šel a dobyl jejich vesnice a pojmenoval je Chavót–Jaír.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nóbach šel a dobyl Kenat a jeho vesnice a pojmenoval ho podle svého jména Nóbach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Toto jsou zastávky synů Izraele, jak táhli z egyptské země podle svých oddílů pod vedením Mojžíše a Árona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Mojžíš na Hospodinův příkaz zapsal jejich výchozí body podle jejich zastávek. Toto jsou jejich zastávky podle jejich výchozích bodů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Vyrazili z Ramesesu prvního měsíce, patnáctého dne prvního měsíce; druhého dne po Velikonocích vytáhli synové Izraele ⌈se vztyčenou hlavou⌉ před očima celého Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Egypťané mezitím pohřbívali ty, které Hospodin mezi nimi pobil, všechny prvorozené; také nad jejich bohy vykonal Hospodin soud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Synové Izraele vyrazili z Ramesesu a utábořili se v Sukótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Vyrazili ze Sukótu a utábořili se v Étamu, který je na okraji pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Vyrazili z Étamu a obrátili se k Pí–chírótu, který je směrem k Baal–sefónu, a utábořili se před Migdólem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Vyrazili z Pene–chírótu, prošli středem moře do pustiny, šli tři dny Étamskou pustinou a utábořili se v Maře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Vyrazili z Mary, přišli do Élimu -- v Élimu bylo dvanáct vodních pramenů a sedmdesát palem -- a utábořili se tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Vyrazili z Élimu a utábořili se u Rákosového moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Vyrazili od Rákosového moře a utábořili se v Sínské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Vyrazili ze Sínské pustiny a utábořili se v Dofce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Vyrazili z Dofky a utábořili se v Alúši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Vyrazili z Alúše a utábořili se v Refídímu. Nebyla tam voda pro lid, aby se napil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Vyrazili z Refídímu a utábořili se v Sínajské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Vyrazili ze Sínajské pustiny a utábořili se v Kibrót–taavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Vyrazili z Kibrót–taavy a utábořili se v Chaserótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Vyrazili z Chaserótu a utábořili se v Ritmě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Vyrazili z Ritmy a utábořili se v Rimón–peresu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Vyrazili z Rimón–peresu a utábořili se v Libně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Vyrazili z Libny a utábořili se v Rise.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Vyrazili z Risy a utábořili se v Kehelatě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Vyrazili z Kehelaty a utábořili se na hoře Šeferu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Vyrazili z hory Šeferu a utábořili se v Charadě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Vyrazili z Charady a utábořili se v Makhelótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Vyrazili z Makhelótu a utábořili se v Tachatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Vyrazili z Tachatu a utábořili se v Terachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Vyrazili z Terachu a utábořili se v Mitce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Vyrazili z Mitky a utábořili se v Chašmóně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Vyrazili z Chašmóny a utábořili se v Moserótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Vyrazili z Moserótu a utábořili se v Bené–jaakánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Vyrazili z Bené–jaakánu a utábořili se v Chór–gidgádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Vyrazili z Chór–gidgádu a utábořili se v Jotbatě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Vyrazili z Jotbaty a utábořili se v Abróně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Vyrazili z Abróny a utábořili se v Esjón–geberu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Vyrazili z Esjón–geberu a utábořili se v pustině Sinu, to je Kádeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Vyrazili z Kádeše a utábořili se na hoře Hóru, na okraji edómské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Kněz Áron vystoupil podle Hospodinova příkazu na horu Hór a zemřel tam ve čtyřicátém roce po vyjití synů Izraele z egyptské země, v pátém měsíci, prvního dne toho měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Áronovi bylo sto dvacet tři let, když zemřel na Hóru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Kenaanský král Aradu, který sídlil v Negebu v kenaanské zemi, se doslechl, že synové Izraele táhnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Vyrazili z hory Hóru a utábořili se v Salmóně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Vyrazili ze Salmóny a utábořili se v Púnónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Vyrazili z Púnónu a utábořili se v Obótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Vyrazili z Obótu a utábořili se v Ijé–abárímu na moábské hranici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Vyrazili z Ijímu a utábořili se v Díbón–Gádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Vyrazili z Díbón–Gádu a utábořili se v Almón–diblatajimu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Vyrazili z Almón–diblatajimu a utábořili se v pohoří Abarím proti Nebó.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Vyrazili z pohoří Abarímu a utábořili se v moábských stepích u Jordánu naproti Jerichu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Tábořili u Jordánu od Bét–ješimótu až k Ábel–šitímu v moábských stepích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Hospodin promluvil k Mojžíšovi v moábských stepích u Jordánu naproti Jerichu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Promluv k synům Izraele a řekni jim: Až projdete Jordánem do kenaanské země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'vyžeňte před sebou všechny obyvatele země, zničte všechny jejich obrazy, všechny jejich lité modly zničte a všechna jejich návrší zpustošte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Podrobte si tu zemi a sídlete v ní, neboť vám jsem dal tu zemi, abyste ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Rozdělte zemi do dědictví losem podle svých čeledí; většímu dejte větší dědictví a menšímu dejte menší dědictví. Kam komu padne los, to bude jeho. Rozdělte dědictví podle otcovských pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Jestliže však nevyženete před sebou obyvatele země, ti, které z nich ponecháte, se stanou trny ve vašich očích a ostny ve vašich bocích a v zemi, ve které budete sídlit, vás budou utlačovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'I stane se, že jak jsem zamýšlel naložit s nimi, tak naložím s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Přikaž synům Izraele a řekni jim: Až přijdete do kenaanské země, toto bude ta země, která vám připadne do dědictví, kenaanská země s jejími hranicemi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Vaše jižní strana bude od pustiny Sinu podél Edómu. Vaše jižní hranice začne na východě od okraje Solného moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Vaše hranice se stočí k jihu k průsmyku Akrabim, bude procházet Sinem. Na jihu bude sahat ke Kádeš–barneji, táhnout se do Chasar–adáru a procházet do Asmónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Hranice se bude stáčet od Asmónu k egyptskému potoku a bude sahat k moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Za západní hranici budete mít Velké moře. To bude vaší západní hranicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'A toto bude vaší severní hranicí: Od Velkého moře potáhnete linii k hoře Hóru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Od hory Hóru potáhnete linii do Lebo–Chamátu, hranice bude sahat k Sedadu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Hranice se potáhne k Zifrónu a bude sahat k Chasar–énanu. To bude vaše severní hranice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Východní hranici si vyznačíte od Chasar–énanu k Šefámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Hranice bude sestupovat z Šefámu do Ribly východně od Ajinu, potom bude hranice sestupovat dolů a dotkne se na východě břehu Kineretského moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Dále bude sestupovat hranice dolů k Jordánu a sahat k Solnému moři. To bude vaše země s jejími hranicemi kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'I přikázal Mojžíš synům Izraele: Toto je země, kterou rozdělíte losem do dědictví, jak přikázal Hospodin dát ji devíti a půl pokolením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Neboť pokolení synů Rúbenových podle domu svých otců a pokolení synů Gádových podle domu svých otců dostala své dědictví, i polovina pokolení Manasesova ho již dostala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Dvě a půl pokolení již dostala své dědictví na druhé straně Jordánu, východně od Jericha, na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Toto jsou jména mužů, kteří vám rozdělí zemi do dědictví: kněz Eleazar a Jozue, syn Núnův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'A přiberou po jednom předáku z pokolení, aby rozdělili zemi do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Toto jsou jména těch mužů: z pokolení Judova Káleb, syn Jefunův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'z pokolení synů Šimeónových Samuel, syn Amíhudův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'z pokolení Benjamínova Elídad, syn Kislónův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'z pokolení synů Danových předák Bukí, syn Joglího;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'ze synů Josefových z pokolení synů Manasesových předák Chaníel, syn Efódův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'z pokolení synů Efrajimových předák Kemúel, syn Šiftánův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'z pokolení synů Zabulónových předák Elísáfan, syn Parnakův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'z pokolení synů Isacharových předák Paltíel, syn Azanův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'z pokolení synů Ašerových předák Achíhúd, syn Šelomího;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'z pokolení synů Neftalího předák Pedahél, syn Amíhudův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'To jsou ti, kterým Hospodin přikázal, aby synům Izraele rozdělili dědictví v kenaanské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Hospodin promluvil k Mojžíšovi v moábských stepích u Jordánu naproti Jerichu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Přikaž synům Izraele, aby dali Lévijcům ze svého dědičného vlastnictví města k bydlení. A také dejte Lévijcům pastviny okolo měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Města budou pro ně k bydlení a jejich pastviny budou pro jejich dobytek, jejich stáda a pro všechna jejich zvířata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Městské pastviny, které dáte Lévijcům, budou sahat tisíc loket na všechny strany od městské zdi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Venku za městem odměříte dva tisíce loket na stranu východní, dva tisíce loket na stranu jižní, dva tisíce loket na stranu západní, dva tisíce loket na stranu severní a město bude uprostřed. To budou jejich městské pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Města, která dáte Lévijcům, budou zahrnovat šest útočištných měst, která ustanovíte, aby tam mohl utéct vrah, a k nim přidáte dvaačtyřicet dalších měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Všech měst, která dáte Lévijcům, bude osmačtyřicet; města sama a jejich pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Co se týče měst, která dáte z vlastnictví synů Izraele, od velkého dáte více a od menšího dáte méně; každý dá ze svých měst Lévijcům podle svého dědictví, které obdrží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Hospodin promluvil k Mojžíšovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Promluv k synům Izraele a řekni jim: Až projdete Jordánem do kenaanské země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'zřídíte si města, která budou vašimi útočištnými městy, kam bude moci utéct vrah, který nedopatřením zabil člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Ta města vám budou útočištěm před mstitelem, takže vrah nezemře, dokud se nepostaví před pospolitostí k soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Toto jsou města, která ustanovíte: budete mít šest útočištných měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Tři města ustanovíte na druhé straně Jordánu a tři města ustanovíte v kenaanské zemi; to budou útočištná města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Pro syny Izraele, pro hosta i pro příchozího mezi nimi bude těchto šest měst útočištěm, aby tam mohl utéct každý, kdo nedopatřením zabil člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Jestliže ho udeří železným předmětem, takže zemře, je vrahem; ten vrah bude jistě usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Jestliže ho udeří kamenem, kterým je možno usmrtit, a on skutečně zemře, je vrahem; ten vrah bude jistě usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Anebo jestliže ho udeří dřevěným předmětem, kterým je možno usmrtit, a on skutečně zemře, je vrahem; ten vrah bude jistě usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Vraha usmrtí krevní mstitel; jakmile ho potká, usmrtí ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Jestliže někdo srazí někoho z nenávisti či na něj hodí něco se zlým úmyslem, takže zemře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'anebo jej z nepřátelství udeří rukou, takže zemře, ten, kdo zabil, bude jistě usmrcen, je vrahem. Krevní mstitel toho vraha usmrtí, jakmile ho potká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Jestliže však někdo srazí někoho náhle bez nepřátelství či na něj hodí jakýkoliv předmět bez zlého úmyslu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'anebo na něj nechá z nepozornosti padnout jakýkoliv kámen, kterým je možno usmrtit, takže zemře, ačkoliv nebyl jeho nepřítelem a neusiloval o jeho zlo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'tehdy bude pospolitost soudit mezi tím, kdo zabil, a krevním mstitelem podle těchto právních nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Pospolitost vysvobodí vraha z ruky krevního mstitele a pospolitost jej přivede zpět do jeho útočištného města, kam utekl. V něm zůstane do smrti velekněze, který byl pomazán posvátným olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Jestliže však vrah vyjde z území svého útočištného města, kam utekl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'a dopadne jej krevní mstitel mimo území jeho útočištného města, pokud krevní mstitel vraha zabije, není na něm krev,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'neboť vrah musí zůstat ve svém útočištném městě až do smrti velekněze a teprve po smrti velekněze se může vrátit do země svého vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Toto bude vaše právní ustanovení pro všechna vaše pokolení ve všech vašich sídlech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Kdokoliv by zabil člověka, podle svědectví svědků bude ten vrah zabit. Jeden svědek nebude vypovídat proti člověku, aby byl usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Nevezmete výkupné za život vraha. Je to ⌈ničema vinný smrtí;⌉ jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Nevezmete výkupné za toho, který utekl do svého útočištného města, aby se mohl vrátit a bydlet ve své zemi před smrtí vele kněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Neznesvětíte zemi, ve které jste, neboť krev znesvěcuje zemi a země nebude usmířena za krev, která v ní byla vylita, jinak než krví toho, kdo ji prolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Neznečistíš zemi, ve které sídlíte, v níž já přebývám, neboť já Hospodin přebývám uprostřed synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Tehdy předstoupili předáci rodů z čeledí synů Gileáda, syna Makíra, syna Manasesova, z čeledí synů Josefových a promluvili před Mojžíšem a před předáky, vůdci rodů synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Řekli: Mému pánu Hospodin přikázal, aby dal synům Izraele zemi do dědictví losem, a mému pánu bylo Hospodinem přikázáno, aby dal dědictví našeho bratra Selofchada jeho dcerám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Jestliže se provdají za někoho z příslušníků jiného kmene synů Izraele, jejich dědictví bude ubráno z dědictví našich otců a bude přidáno k dědictví pokolení, k němuž budou patřit; a naše losem přidělené dědictví bude ukráceno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'A jestliže budou mít synové Izraele ⌈milostivé léto,⌉ potom bude jejich dědictví přidáno k dědictví pokolení, k němuž budou patřit, a dědictví pokolení našich otců bude ukráceno o jejich dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Nato Mojžíš přikázal synům Izraele podle Hospodinova příkazu: Pokolení synů Josefových mluví správně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Toto je to, co Hospodin přikázal dcerám Selofchadovým: Mohou se provdat za koho je jim libo, pokud se provdají do čeledi náležející k pokolení jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Dědictví synů Izraele ne smí přejít od pokolení k pokolení, ale každý ze synů Izraele se přidrží dědictví pokolení svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Každá dcera, která obdrží dědictví z pokolení synů Izraele, se provdá do jedné z čeledí náležející k pokolení jejího otce, aby synové Izraele obdrželi každý dědictví svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Dědictví ne smí přejít od pokolení k pokolení, ale každé pokolení synů Izraele se přidrží svého dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Jak Hospodin Mojžíšovi přikázal, tak dcery Selofchadovy učinily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Machla, Tirsa, Chogla, Milka a Nóa, dcery Selofchadovy, se provdaly za syny svých strýců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Provdaly se do čeledi synů Manasesa, syna Josefova, a jejich dědictví zůstalo v pokolení čeledi jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Toto jsou příkazy a nařízení, která dal Hospodin synům Izraele prostřednictvím Mojžíše v moábských stepích u Jordánu naproti Jerichu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Toto jsou slova, která mluvil Mojžíš k celému Izraeli za Jordánem, v pustině, v Arabě naproti Súfu, mezi Páranem a Tófelem, Lábanem, Chaserótem a Dí–zahabem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Od Chorébu směrem k pohoří Seíru až do Kádeš–barneje to je jedenáct dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'I stalo se ve čtyřicátém roce, v jedenáctém měsíci, prvního dne toho měsíce, že Mojžíš pověděl synům Izraele všechno, co ⌈mu pro ně Hospodin přikázal,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'poté, co pobil emorejského krále Síchona sídlícího v Chešbónu a bášanského krále Óga sídlícího v Aštarótu a v Edreí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Za Jordánem, v moábské zemi, začal Mojžíš vysvětlovat tento zákon:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '⌈Hospodin, náš Bůh,⌉ k nám promluvil na Chorébu: ⌈Dost dlouho jste pobývali⌉ na této hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, '⌈Vydejte se na cestu,⌉ vyrazte a jděte do pohoří Emorejců, ke všem jejich sousedům, do Araby, do pohoří, do Šefely, do Negebu a na pobřeží moře, do kenaanské země a Libanonu, až k Veliké řece, řece Eufratu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Pohleď, dal jsem před vás tu zemi. Jděte a obsaďte zemi, o které Hospodin přísahal vašim ⌈otcům, Abrahamovi, Izákovi a Jákobovi,⌉ že ji dá jim a jejich potomstvu po nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'V té době jsem vám řekl: Nemohu vás sám unést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Hospodin, váš Bůh, vás rozmnožil, ano je vás dnes tolik jako hvězd na nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Ať vám Hospodin, Bůh vašich otců, ještě tisíckrát přidá a požehná vám, tak jak vám řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Jak ale mohu sám unést vaši zátěž, vaše břemena a vaše spory?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Vyberte si ⌈ve svých kmenech⌉ moudré, rozumné a znalé muže a ustanovím je za vaše předáky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Nato jste mi odpověděli: To, co jsi řekl, abychom učinili, je dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Vzal jsem tedy předáky vašich kmenů, moudré a znalé muže, a ustanovil jsem je předáky nad vámi, veliteli ⌈ nad tisíci, veliteli nad sty, veliteli nad padesáti, veliteli nad deseti⌉ a správci nad vašimi kmeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'V té době jsem přikázal vašim soudcům: Vyslechněte ⌈své bratry⌉ a suďte spravedlivě mezi člověkem a jeho bratrem i příchozím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Při soudu ⌈nestraňte lidem,⌉ vyslechněte ⌈malého i velkého.⌉ Nemějte strach z člověka, neboť soud patří Bohu. Záležitost, která bude pro vás příliš těžká, předneste mně a já ji vyslechnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'V té době jsem vám přikázal ⌈všechno, co⌉ máte dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Vyrazili jsme z Chorébu a šli jsme celou tou velkou a obávanou pustinou, kterou jste viděli cestou k emorejskému pohoří, jak nám přikázal Hospodin, náš Bůh, až jsme došli do Kádeš–barneje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Řekl jsem vám: Přišli jste až k emorejskému pohoří, které vám dává Hospodin, náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Pohleď, Hospodin, tvůj Bůh, před tebe dal zemi. Vytáhni a obsaď ji, jak ti řekl Hospodin, Bůh tvých otců. Neboj se a neděs se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Přistoupili jste všichni ke mně a řekli jste: Pošleme před sebou muže, aby pro nás proslídili zemi a přinesli nám zpět zprávu o cestě, kterou máme táhnout, a o městech, do kterých máme vejít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, '⌈Líbilo se mi to⌉ a vybral jsem z vás dvanáct mužů, jednoho muže za každý kmen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, '⌈Vydali se na cestu,⌉ stoupali do pohoří a přišli až do údolí Eškólu. Prozkoumali ho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'vzali s sebou z ovoce té země a zanesli to k nám. Přinesli nám zprávu se slovy: Země, kterou nám dává Hospodin, náš Bůh, je dobrá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Nechtěli jste však vytáhnout a vzpírali jste se příkazu Hospodina, svého Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'reptali jste ⌈ve svých stanech⌉ a říkali jste: Hospodin nás měl v nenávisti, vyvedl nás z egyptské země, aby nás vydal do ruky Emorejců a vyhladil nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Kam to táhneme? Naši bratři ⌈oslabovali naše srdce⌉ slovy: Je tam lid větší a vyšší nežli my, jsou tam města velká a opevněná až k nebesům; viděli jsme tam dokonce i potomky Anákovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Nato jsem vám řekl: Nemějte strach a nebojte se jich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Hospodin, váš Bůh, který jde před vámi, on bude bojovat za vás, stejně jako jednal s vámi před vašima očima v Egyptě');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'a v pustině, kde jsi viděl, jak tě Hospodin, tvůj Bůh, nesl, jako nosí člověk svého syna, po celou cestu, kterou jste šli, až jste přišli na toto místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, '⌈Navzdory tomu všemu⌉ jste nevěřili Hospodinu, svému Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'který šel cestou před vámi, aby vám vyhledal místo k táboření a aby vám ukázal cestu, po které byste měli jít -- ohněm v noci a oblakem ve dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Když Hospodin uslyšel křik vašich slov, rozhněval se a přísahal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Nikdo z lidí této zlé generace neuvidí tu dobrou zemi, o které jsem přísahal, že ji dám vašim otcům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'kromě Káleba, syna Jefunova. Ten ji uvidí, jemu a jeho synům dám zemi, na kterou vstoupil, protože ⌈šel naplno⌉ za Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Také na mě se Hospodin kvůli vám rozhněval a řekl: Ani ty tam nevejdeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Jozue, syn Núnův, který ⌈ti slouží,⌉ ten tam vejde. Jej posilni, neboť on dá zemi Izraeli do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Vaše malé děti, o kterých jste říkali, že se stanou kořistí, a vaši synové, kteří dnes nerozeznají dobré a zlé, ti tam vejdou, jim ji dám a oni ji obsadí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Vy ⌈se však vydejte na cestu⌉ zpět a vyrazte do pustiny směrem k Rákosovému moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Nato jste mi odpověděli: Zhřešili jsme proti Hospodinu. Vytáhneme a budeme bojovat, jak přikázal Hospodin, náš Bůh. Připásali jste si každý své válečné zbraně a ⌈lehkomyslně jste vytáhli⌉ do pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Hospodin mi řekl: Řekni jim: Netáhněte a nebojujte, protože já nejsem uprostřed vás; ať nejste poraženi od svých nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Mluvil jsem k vám, ale neposlouchali jste. Vzepřeli jste se Hospodinovu příkazu, ⌈jednali jste povýšeně a vytáhli⌉ jste do pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Emorejci sídlící v onom pohoří vytáhli proti vám, pronásledovali vás, jako to dělávají včely, a rozehnali vás od Seíru až po Chormu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, '⌈Když jste se vrátili, plakali jste⌉ před Hospodinem, ale Hospodin neslyšel váš hlas, nenaslouchal vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Zůstali jste v Kádeši po mnoho dní, ⌈asi tak rok jste tam ⌉ zůstali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Pak ⌈jsme se vydali na cestu⌉ a vyrazili jsme do pustiny směrem k Rákosovému moři, jak mi řekl Hospodin, a obcházeli jsme po mnoho dní pohoří Seír.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Tu mi Hospodin řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Už dost dlouho jste obcházeli toto pohoří. Vydejte se na sever.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'A lidu přikaž: Budete procházet územím svých ⌈bratrů, synů Ezauových,⌉ sídlících v Seíru. Bojí se vás, tak se mějte velmi na pozoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, '⌈Nepouštějte se s nimi do boje,⌉ protože vám z jejich země nedám ani stopu, neboť pohoří Seír jsem dal do vlastnictví Ezauovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Jídlo od nich získávejte za stříbro, ⌈abyste se mohli najíst,⌉ a také vodu si od nich opatřujte za stříbro, abyste se mohli napít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Vždyť Hospodin, tvůj Bůh, ti požehnal ⌈při všem⌉ díle tvých rukou. ⌈Zná tvou cestu⌉ touto velkou pustinou. Těchto čtyřicet let byl ⌈Hospodin, tvůj Bůh, s tebou,⌉ a ⌈neměl jsi v ničem nedostatek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Tak jsme šli dál od svých bratrů, synů Ezauových, sídlících v Seíru, ⌈cestou přes Arabu,⌉ Élat a Esjón–geber. Pak jsme se obrátili a ⌈šli jsme směrem k ⌉ moábské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Tu mi Hospodin řekl: Nenapadej Moábce a nepouštěj se s nimi do boje, protože z jejich země ti nedám nic do vlastnictví, neboť Ar jsem dal do vlastnictví ⌈synům Lotovým.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Předtím v něm sídlili Emejci, velký a početný lid, vysoký jako Anákovci;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'byli také považováni za Refájce jako Anákovci, ale Moábci je nazývali Emejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'V Seíru předtím sídlili Chorejci. Ale synové Ezauovi je vypudili, vyhladili je před sebou a sídlili tam místo nich, stejně jako to udělali Izraelci se zemí svého vlastnictví, kterou jim Hospodin dal.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Nyní vstaňte a přejděte potok Zered. Tak jsme přešli potok Zered.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Doba, po kterou jsme šli z Kádeš–barneje, než jsme přešli potok Zered, byla třicet osm let, dokud nebyla z tábora zcela vyhlazena celá generace bojovníků, tak jak jim Hospodin přísahal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Ano, Hospodinova ruka byla proti nim, aby je vyhlazovala z tábora, až byli zcela vyhlazeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'I stalo se, když vymřeli všichni ti bojovníci z lidu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'že ke mně Hospodin promluvil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Dnes ⌈procházíš územím⌉ Moábu, územím Aru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Až se přiblížíš k synům Amónovým, nenapadej je, nepouštěj se s nimi do boje, protože ze země synů Amónových ti nedám nic do vlastnictví, neboť jsem ji dal do vlastnictví synům Lotovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Také ta byla považována za zemi Refájců. Předtím v ní sídlili Refájci. Amónci je nazývali Zamzumci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Byl to velký a početný lid, vysoký jako Anákovci. Ale Hospodin je před nimi vyhladil, takže je vypudili a sídlili tam místo nich,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'stejně jako to udělal pro syny Ezauovy, sídlící v Seíru, když před nimi vyhladil Chorejce, takže je vypudili a sídlili tam místo nich až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Avíjce sídlící ve dvorcích až po Gazu vyhladili Kaftórci, kteří vyšli z Kaftóru, a sídlili místo nich.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Vstaňte, vyrazte a přejděte potok Arnón. Pohleď, vydal jsem do tvé ruky Emorejce Síchona, krále Chešbónu, i jeho zemi. Začni ji obsazovat a pusť se s ním do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Dnes začnu dávat ⌈strach a bázeň z tebe⌉ na národy pod celým nebem. Když uslyší ⌈zprávu o tobě,⌉ budou se před tebou třást a svíjet bolestí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Nato jsem poslal z pustiny Kedemótu posly k chešbónskému králi Síchonovi s ⌈úmluvou o pokoji:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Chci projít tvou zemí, půjdu ⌈přímo po cestě,⌉ neodbočím napravo ani nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Budeš mi prodávat jídlo za stříbro, abych se mohl najíst, i vodu mi budeš dávat za stříbro, abych se mohl napít. Jenom chci pěšky projít --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, '(stejně tak vůči mně jednali synové Ezauovi sídlící v Seíru a Moábci sídlící v Aru) -- dokud nepřejdu Jordán do země, kterou nám dává Hospodin, náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Chešbónský král Síchon nás však nechtěl nechat projít ⌈jeho zemí,⌉ protože Hospodin, tvůj Bůh, zatvrdil jeho ducha a upevnil jeho srdce, aby ho vydal do tvé ruky, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Hospodin mi řekl: Pohleď, začal jsem ti dávat Síchona a jeho zemi. Začni obsazovat ⌈jeho zemi a získej ji do vlastnictví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Když Síchon ⌈se vším svým lidem⌉ vytáhl proti nám do boje k Jahasu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Hospodin, náš Bůh, nám ho vydal a pobili jsme jej i jeho syny i všechen jeho lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'V té době jsme dobyli všechna jeho města a každé město jsme zasvětili zkáze, muže, ženy i malé děti. Nenechali jsme nikoho přežít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Jenom dobytek jsme zabrali pro sebe a kořist z měst, která jsme dobyli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Od Aróeru, který je na ⌈břehu potoka⌉ Arnónu, města, které je v údolí, až po Gileád, nebylo město, které by před námi bylo v bezpečí; vše nám Hospodin, náš Bůh, vydal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Pouze k zemi synů Amónových ses nepřiblížil, na celou stranu potoka Jaboku ani k městům v pohoří; vše, jak přikázal Hospodin, náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Pak jsme se vydali na cestu a vytáhli jsme směrem k Bášanu. Bášanský král Óg ⌈se vším svým lidem⌉ vytáhl proti nám do boje k Edreí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Hospodin mi řekl: Neboj se ho, neboť jsem vydal do tvé ruky jej, všechen jeho lid i jeho zemi. ⌈Nalož s ním tak, jak jsi naložil⌉ s emorejským králem Síchonem sídlícím v Chešbónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'A Hospodin, náš Bůh, vydal do naší ruky také bášanského krále Óga i všechen jeho lid. Pobíjeli jsme ho, až mu nezůstal nikdo, kdo by přežil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'V té době jsme dobyli všechna jeho města; nebylo město, které bychom jim nevzali, šedesát měst, celou oblast Argóbu, Ógovo království v Bášanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Všechno to byla města opevněná vysokými hradbami s vraty a závorami. Mimo to velmi mnoho nehrazených měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Zasvětili jsme je zkáze tak, jako jsme to učinili s chešbónským králem Síchonem; zasvětili jsme zkáze každé město, muže, ženy i malé děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Ale všechen dobytek a kořist z těch měst jsme zabrali pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'V té době jsme zabrali zemi od dvou emorejských králů, kteří sídlili za Jordánem, od potoka Arnónu až k hoře Chermónu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Sidónci nazývají Chermón Sirjón a Emorejci ho nazývají Senír),');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, '-- všechna města náhorní roviny, celý Gileád, celý Bášan až po Salku a Edreí, města Ógova království v Bášanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '(Pouze bášanský král Óg totiž zůstal ze zbytku Refájců. Hle, jeho pohovka, železná pohovka je přece v Rabě synů Amónových; je ⌈devět loket dlouhá a čtyři lokte široká⌉ podle ⌈běžné míry.)⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'V té době jsme obsadili tuto zemi: Území od Aróeru, který je u potoka Arnónu, a polovinu pohoří Gileádu i jeho města jsem dal Rúbenovcům a Gádovcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Zbytek Gileádu a celý Bášan, Ógovo království, jsem dal polovině kmene Manasesova. (⌈Celá oblast Argóbu,⌉ celý Bášan se nazývá zemí Refájců.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaír, syn Manasesův, zabral celou oblast Argóbu až ke ⌈gešúrejskému a maakatskému území⌉ a nazval ho -- totiž Bášan -- podle svého jména Chavót–Jaír, jak je tomu až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Makírovi jsem dal Gileád.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Rúbenovcům a Gádovcům jsem dal území od Gileádu až k potoku Arnónu (střed údolí jako hranici), až k potoku Jaboku, k hranici synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Také Araba a Jordán byly hranicí od Kineretu až k moři Araby, Solnému moři, pod srázy Pisgy na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'V té době jsem vám přikázal: Hospodin, váš Bůh, vám dal tuto zemi, abyste ji obsadili. Ale všichni bojovníci půjdou ozbrojeni před svými bratry, syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Jenom ⌈vaše ženy, malé děti a váš dobytek⌉ -- vím, že máte mnoho dobytka -- zůstanou ve vašich městech, která jsem vám dal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'dokud Hospodin ne dá odpočinek vašim bratrům, jako dal vám, a také oni ne obsadí zemi, kterou vám Hospodin, váš Bůh, dává za Jordánem. Pak se každý vrátíte ke svému vlastnictví, které jsem vám dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'V té době jsem přikázal Jozuovi: Tvé oči viděly vše, co Hospodin, váš Bůh, učinil těmto dvěma králům. Tak učiní Hospodin všem královstvím, ⌈do kterých půjdeš.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Nebojte se jich, neboť Hospodin, váš Bůh, bude bojovat za vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'V té době jsem prosil Hospodina o smilování slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Panovníku Hospodine, ty jsi začal svému otroku ukazovat svou velikost a svou mocnou ruku. ⌈Jaký bůh na nebesích a na zemi by⌉ mohl činit ⌈skutky a udatné činy jako jsou tvoje?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Dovol, abych šel dál a uviděl tu dobrou zemi, která je za Jordánem, to dobré pohoří a Libanon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Hospodin se na mě kvůli vám nazlobil a nevyslyšel mě. Hospodin mi řekl: Dost. ⌈Již o tom se mnou nemluv.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Vystup na vrchol Pisgy a ⌈pozvedni oči⌉ ⌈na západ,⌉ na sever, na jih a na východ. Podívej se na vlastní oči, protože tento Jordán nepřejdeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Dej však příkaz Jozuovi, posilni ho a upevni ho, protože on půjde před tímto lidem, on jim dá do dědictví zemi, kterou uvidíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Zůstali jsme v údolí naproti Bét–peóru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Nyní slyš, Izraeli, ustanovení a nařízení, která vás učím plnit, abyste zůstali naživu, šli a obsadili zemi, kterou vám dává Hospodin, Bůh vašich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Nic nepřidávejte k tomu, co vám přikazuji, ani z toho nic neubírejte, ale zachovávejte příkazy Hospodina, svého Boha, které vám dávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vaše oči viděly, co Hospodin učinil kvůli Baal–peórovi, jak každého, kdo šel za Baal–peórem, Hospodin, tvůj Bůh, ze tvého středu vyhladil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Zatímco vy, kteří lnete k Hospodinu, svému Bohu, vy všichni jste dnes naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Pohleď, učil jsem vás ustanovení a nařízení, jak mi přikázal Hospodin, můj Bůh, abyste je plnili v zemi, do které jdete, abyste ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Zachovávejte a plňte je, protože to je vaše moudrost a vaše rozumnost před očima národů, které když uslyší všechna tato ustanovení, řeknou: Tento velký národ je vskutku moudrý a rozumný lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Vždyť ⌈jaký jiný velký národ má bohy tak blízko sebe,⌉ jako je Hospodin, náš Bůh, kdykoliv k němu voláme?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'A jaký jiný velký národ má tak spravedlivá ustanovení a nařízení jako je celý tento zákon, který před vás dnes kladu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Jenom se měj na pozoru a velmi střež svou duši, abys nezapomněl ty věci, které viděly tvé oči a aby po všechny dny tvého života nevymizely ze tvého srdce, ale poučuj o nich své syny a své vnuky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, '⌈ Pamatuj na den,⌉ kdy jsi stál před Hospodinem, svým Bohem, na Chorébu, a kdy mi Hospodin řekl: Shromáždi mi lid a oznámím jim svá slova, ⌈aby se mě učili bát⌉ po všechny dny, co budou naživu na zemi, a učili tomu i své syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Přistoupili jste a stáli pod horou. Hora plála ohněm doprostřed nebes, byla tma, oblak a hustá temnota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Hospodin k vám mluvil z ohně. Slyšeli jste zvuk slov, ovšem podobu jste neviděli, nic než hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Oznámil vám svou smlouvu, kterou vám přikázal plnit, Deset slov, a napsal je na dvě kamenné desky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Mně v té době Hospodin přikázal, abych vás učil ustanovení a nařízení, abyste je plnili v zemi, do které procházíte Jordánem, abyste ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, '⌈Kvůli svým životům se mějte velmi na pozoru,⌉ -- neboť jste neviděli žádnou podobu v den, kdy k vám Hospodin mluvil na Chorébu z ohně --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'abyste nejednali zvráceně a ne udělali si tesanou modlu jakékoli podoby, žádnou sochu: Napodobeninu muže či ženy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'napodobeninu žádného zvířete, které je na zemi, ani napodobeninu žádného okřídleného ptáka, který létá po nebi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'napodobeninu ničeho plazícího se po zemi, ani napodobeninu žádné ryby, která je ve vodě ⌈pod zemí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Ani nepozvedej své oči k nebesům, aby ses díval na slunce, měsíc a hvězdy, celý nebeský zástup a nechal se svést, klaněl se jim a sloužil jim, protože Hospodin, tvůj Bůh, je přidělil všem národům pod celým nebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Vás však Hospodin vzal a vyvedl vás z pece na tavení železa, z Egypta, abyste ⌈byli jeho lidem, dědictvím,⌉ jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Hospodin se na mě kvůli vám rozhněval a přísahal, že neprojdu Jordánem a nevejdu do té dobré země, kterou ti Hospodin, tvůj Bůh, dává do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Ano, já zemřu v této zemi, neprojdu Jordánem, ale vy projdete a obsadíte tuto dobrou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Mějte se na pozoru, abyste nezapomněli na smlouvu Hospodina, svého Boha, kterou s vámi uzavřel, a ne udělali si tesanou modlu jakékoliv podoby, jak ti přikázal Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Vždyť Hospodin, tvůj Bůh, je stravující oheň, žárlivý Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Jestliže až zplodíte syny a vnuky a budete dlouho usazeni v zemi, budete jednat zvráceně a uděláte si tesanou modlu jakékoliv podoby, spácháte to, co je zlé v očích Hospodina, svého Boha, a rozzlobíte ho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'povolávám dnes proti vám za svědky nebesa i zemi, že jistě rychle vyhynete ze země, do které procházíte Jordánem, abyste ji obsadili. ⌈Nedožijete se v ní mnoha dní,⌉ ale jistě budete vyhubeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Hospodin vás rozptýlí mezi národy a zůstanete v malém počtu mezi národy, kam vás Hospodin zažene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Tam budete sloužit bohům, dílu lidských rukou, dřevu a kameni, kteří nevidí ani neslyší, nejedí ani nečichají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Tam budete hledat Hospodina, svého Boha, a nalezneš ho, když ho budeš hledat ⌈celým svým srdcem a celou svou duší. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Až ⌈budeš v tísni⌉ a ⌈dopadnou na tebe⌉ všechny tyto věci, ⌈v posledních dnech⌉ se navrátíš k Hospodinu, svému Bohu, a jej budeš poslouchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Vždyť Hospodin, tvůj Bůh, je Bůh soucitný, neopustí tě a nezničí tě, nezapomene na smlouvu s tvými otci, kterou jim odpřisáhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Jen se vyptávej na dřívější časy, které byly před tebou, od doby, kdy Bůh stvořil člověka na zemi, ⌈od jednoho konce nebes až na druhý,⌉ zda se stalo něco tak velkého nebo jestli ⌈ někdo slyšel⌉ něco takového?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Cožpak nějaký národ slyšel Boží hlas mluvící z ohně, jako jsi slyšel ty, a zůstal naživu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Nebo zkusil ⌈ nějaký bůh⌉ jít a vzít si národ z jiného národa skrze zkoušky, znamení, divy a boj, mocnou rukou a vztaženou paží, skrze ⌈velké činy vzbuzující bázeň,⌉ jak to všechno pro vás činil Hospodin, tvůj Bůh, před tvýma očima v Egyptě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tobě bylo ⌈dáno vidět a poznat,⌉ že Hospodin je Bůh a nikdo jiný kromě něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Z nebes k tobě nechal zaznít svůj hlas, aby tě poučil, na zemi ti ukázal svůj velký oheň, z ohně jsi slyšel jeho slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'A protože miloval tvé otce, vyvolil jejich potomstvo po nich. On sám tě svou velkou silou vyvedl z Egypta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'vyhnal před tebou národy větší a mocnější než jsi ty, aby tě přivedl do jejich země a dal ti ji do dědictví, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Uznej tedy dnes a ⌈připomínej si ve svém srdci,⌉ že Hospodin je Bůh nahoře na nebi i dole na zemi a žádný jiný není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Zachovávej jeho ustanovení a jeho příkazy, které ti dnes dávám, aby se vedlo dobře tobě i tvým synům po tobě a aby ⌈ses dožil mnoha dní⌉ v zemi, kterou ti Hospodin, tvůj Bůh, dává pro všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tehdy Mojžíš oddělil tři města za Jordánem směrem na východ slunce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'aby tam mohl utéct vrah, který neúmyslně zabije svého bližního, aniž by byl jej dříve předtím nenáviděl. Uteče do jednoho z těchto měst a zůstane naživu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Beser v pustině, v zemi náhorní roviny pro Rúbenovce, Rámot v Gileádu pro Gádovce a Gólan v Bášanu pro Manasesovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Toto je zákon, který předložil Mojžíš synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Toto jsou svědectví, ustanovení a nařízení, která vyhlásil Mojžíš synům Izraele, když vyšli z Egypta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'za Jordánem, v údolí naproti Bét–peóru, v zemi emorejského krále Síchona sídlícího v Chešbónu, kterého pobil Mojžíš a synové Izraele, když vyšli z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Obsadili jeho zemi i zemi bášanského krále Óga, dvou emorejských králů, kteří byli za Jordánem směrem na východ slunce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'od Aróeru, který je na břehu potoka Arnónu, až k hoře Síonu, což je Chermón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'celou Arabu za Jordánem na východě až k moři Araby pod srázy Pisgy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Mojžíš svolal celý Izrael a řekl jim: Slyš, Izraeli, ustanovení a nařízení, která ⌈k vám⌉ dnes mluvím. ⌈Učte se je, zachovávejte a plňte je.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Hospodin, náš Bůh, s námi uzavřel na Chorébu smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ne jenom s našimi otci uzavřel Hospodin tuto smlouvu, ale s námi všemi, kteří jsme tu dnes naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Tváří v tvář s vámi Hospodin mluvil na hoře z ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(Stál jsem v té době mezi Hospodinem a vámi, abych vám oznámil Hospodinovo slovo, neboť jste se báli ohně a nevystoupili jste na horu.) Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Já Hospodin jsem tvůj Bůh, který tě ⌈vyvedl z egyptské země,⌉ z domu otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Nebudeš mít ⌈jiné bohy⌉ ⌈vedle mne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Neuděláš si tesanou modlu ⌈jakékoliv podoby toho, co je ⌉ nahoře na nebi nebo dole na zemi či ve vodě pod zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Nebudeš se jim klanět a nebudeš jim sloužit, neboť já Hospodin, tvůj Bůh, jsem Bůh žárlivý, který s trestem navštěvuji vinu otců na synech i na třetí a čtvrté generaci těch, kdo mě nenávidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'ale prokazuji milosrdenství tisícům těch, kdo mě milují a zachovávají mé příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Nebudeš brát jméno Hospodina, svého Boha, nadarmo, protože Hospodin nenechá bez trestu toho, kdo bere jeho jméno nadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, '⌈Zachovávej sobotní den a posvěť ho,⌉ jak ti přikázal Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Šest dní budeš pracovat a dělat všechnu svou práci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'ale sedmý den je sobota patřící Hospodinu, tvému Bohu. Nebudeš dělat žádnou práci ty ani tvůj syn a tvá dcera ani tvůj otrok a tvá otrokyně ani tvůj býk a tvůj osel, žádné tvé zvíře ani tvůj ⌈příchozí, který je ve tvých branách,⌉ aby odpočinul tvůj otrok a tvá otrokyně tak jako ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Vzpomeň, že jsi byl otrokem v egyptské zemi a že tě Hospodin, tvůj Bůh, odtamtud vyvedl mocnou rukou a vztaženou paží. Proto ti Hospodin, tvůj Bůh, přikázal zachovávat sobotní den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Cti svého otce i svou matku, jak ti přikázal Hospodin, tvůj Bůh, aby ⌈se prodloužily tvé dny⌉ a aby se ti dobře vedlo v zemi, kterou ti dává Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Nebudeš vraždit!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Nebudeš cizoložit!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Nebudeš krást!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Nebudeš vypovídat proti svému bližnímu falešné svědectví!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Nebudeš žádostiv ženy svého bližního! Nebudeš dychtit po domě svého bližního ani po jeho poli, jeho otroku ani jeho otrokyni, jeho býku ani jeho oslu, po ničem, co patří tvému bližnímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Tato slova promluvil Hospodin velkým hlasem k celému vašemu shromáždění na hoře z ohně, oblaku a husté temnoty a nic nepřidal. Zapsal je na dvě kamenné desky a dal mi je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'I stalo se, když jste slyšeli ten hlas z temnoty -- zatímco hora plála ohněm -- že jste ke mně přistoupili, všichni předáci vašich kmenů a vaši starší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'a řekli jste: Hle, Hospodin, náš Bůh, nám ukázal svou slávu a svou velikost a slyšeli jsme jeho hlas z ohně. Dnes jsme viděli, že Bůh může mluvit s člověkem a ten zůstane naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Teď však proč bychom měli zemřít? Vždyť nás stráví tento velký oheň. Jestliže budeme ještě dále poslouchat hlas Hospodina, svého Boha, zemřeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Vždyť kdo ⌈z těla⌉ slyšel hlas živého Boha mluvícího z ohně jako my a zůstal naživu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Přistup ty a poslouchej všechno, co bude říkat Hospodin, náš Bůh. Ty nám pak řekneš všechno, co Hospodin, náš Bůh, poví tobě. Vyslechneme to a budeme dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Hospodin slyšel ⌈vaše slova,⌉ když jste ke mně mluvili, a Hospodin mi řekl: Slyšel jsem slova tohoto lidu, která k tobě mluvili. ⌈Řekli všechno dobře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, '⌈Kéž by se stalo, že by měli taková srdce,⌉ báli se mě a po všechny dny zachovávali všechny mé příkazy, aby se navěky vedlo dobře jim i jejich synům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Jdi a řekni jim: Vraťte se ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Ale ty tady zůstaň se mnou. Povím ti všechny příkazy, ustanovení a nařízení, která je budeš učit, aby je plnili v zemi, kterou jim dávám, aby ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Zachovávejte a plňte je, jak vám přikázal Hospodin, váš Bůh. Neodvracejte se ⌈napravo ani nalevo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, '⌈Choďte jenom po té cestě, kterou⌉ vám přikázal Hospodin, váš Bůh, abyste zůstali naživu, bylo vám dobře a dožili jste se mnoha dní v zemi, kterou obsadíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Toto jsou příkazy, ustanovení a nařízení, která mi Hospodin, váš Bůh, přikázal vás učit, abyste je plnili v zemi, do které procházíte Jordánem, abyste ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Aby ses bál Hospodina, svého Boha, a po všechny dny svého života zachovával všechna jeho ustanovení a jeho příkazy, které ti přikazuji, ty i tvůj syn i tvůj vnuk, aby se prodloužily tvé dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Poslouchej je, Izraeli, ⌈zachovávej a plň⌉ je, aby se ti vedlo dobře a velmi jste se rozmnožili v zemi ⌈oplývající mlékem a medem,⌉ jak ti řekl Hospodin, Bůh tvých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, '⌈Slyš, Izraeli,⌉ ⌈Hospodin je náš Bůh, Hospodin jediný.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Miluj Hospodina, svého Boha, celým svým srdcem, celou svou duší a celou svou silou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, '⌈Ať jsou tato slova, která ti dnes přikazuji, ve tvém srdci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Opakuj je svým synům, mluv o nich, když pobýváš ⌈ve svém domě,⌉ i když chodíš po cestě, když ležíš, i když vstáváš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Přivaž je jako znamení na ruku, ať jsou značkou ⌈mezi tvýma očima.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Napiš je na veřeje svého domu a na své brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'I stane se, až tě Hospodin, tvůj Bůh, přivede do země, o které přísahal tvým otcům, ⌈Abrahamovi, Izákovi a Jákobovi,⌉ že ti ji dá -- zemi, kde jsou velká a dobrá města, která jsi nestavěl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'domy plné ⌈všelijakých dobrých věcí,⌉ které jsi nenaplnil, vykopané studny, které jsi nevykopal, vinice a olivové háje, které jsi nevysadil, -- až se najíš a nasytíš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'měj se na pozoru, abys nezapomněl na Hospodina, který tě vyvedl z egyptské země, z domu otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Hospodina, svého Boha, se boj, jemu služ a v jeho jménu přísahej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Nechoďte za jinými bohy, ⌈za bohy⌉ národů, které jsou okolo vás,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'neboť Hospodin, tvůj Bůh, ve tvém středu, je Bůh žárlivý. Jinak vzplane hněv Hospodina, tvého Boha, proti tobě a vyhladí tě z povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Nezkoušejte Hospodina, svého Boha, jako jste ho zkoušeli v Masse.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Bedlivě zachovávejte příkazy Hospodina, svého Boha, jeho svědectví a ustanovení, která vám přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Dělej, co je správné a dobré v Hospodinových očích, aby se ti vedlo dobře a abys šel a obsadil tu dobrou zemi, o které Hospodin přísahal tvým otcům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, '⌈a abys vypudil⌉ všechny tvé nepřátele před tebou, jak Hospodin řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Až se tě tvůj syn později zeptá: Co znamenají ta svědectví, ustanovení a nařízení, která vám Hospodin, váš Bůh, přikázal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Odpověz svému synovi: Byli jsme v Egyptě faraonovými otroky, ale Hospodin nás z Egypta mocnou rukou vyvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Hospodin dal před našima očima velká a zlá znamení a divy na Egypt, na faraona a celý jeho dům');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'a nás odtamtud vyvedl, aby nás přivedl sem a dal nám zemi, o které přísahal našim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Hospodin nám přikázal, abychom plnili všechna tato ustanovení a báli se Hospodina, svého Boha, aby se nám dobře dařilo po všechny dny a zůstali jsme naživu, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, '⌈ To nám přinese⌉ spravedlnost, když budeme zachovávat a plnit každý tento příkaz před Hospodinem, svým Bohem, jak nám přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Až tě Hospodin, tvůj Bůh, přivede do země, do které jdeš, abys ji obsadil, a vyžene před tebou početné národy, Chetejce, Girgašejce, Emorejce, Kenaance, Perizejce, Chivejce a Jebúsejce, sedm národů početnějších a mocnějších nežli ty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'až ti je Hospodin, tvůj Bůh, vydá a pobiješ je, zcela je zasvěť zkáze. Neuzavírej s nimi smlouvu a neslituj se nad nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Nespřízňuj se s nimi, ⌈nedávej svou dceru jeho synu⌉ a neber jeho dceru pro svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Jinak odvrátí tvého syna ⌈ode mě,⌉ budou sloužit jiným bohům, Hospodinův hněv vzplane proti vám a rychle tě vyhladí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Naopak jim proveďte toto: Jejich oltáře strhněte, jejich posvátné sloupy roztřískejte, jejich posvátné kůly pokácejte a jejich tesané modly spalte ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Vždyť ty jsi svatým lidem Hospodinu, svému Bohu; tebe Hospodin, tvůj Bůh, vyvolil ze všech národů, které jsou na povrchu země, abys byl jeho ⌈lidem, jeho vlastnictvím.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ne proto, že byste byli početnější nežli všechny národy, k vám Hospodin přilnul a vyvolil vás -- vždyť vás bylo nejméně ze všech národů --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'ale ze své lásky ⌈k vám⌉ a aby zachoval přísahu, kterou přísahal vašim otcům, vás Hospodin vyvedl mocnou rukou a vykoupil tě z domu otroctví, z ruky faraona, egyptského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Věz, že Hospodin, tvůj Bůh, je Bůh, Bůh věrný, který zachovává smlouvu a milosrdenství tisícům generací těch, kdo ho milují a zachovávají jeho příkazy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'a odplácí tomu, kdo ho nenávidí, ⌈do jeho tváře⌉ ⌈a vyhubí jej.⌉ Neopozdí se vůči tomu, kdo ho nenávidí, do jeho tváře mu odplatí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Zachovávej příkazy, ustanovení a nařízení, která ti dnes přikazuji, ⌈a plň je.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Za to, že budete poslouchat tato nařízení, zachovávat je a plnit, Hospodin, tvůj Bůh, ti bude zachovávat smlouvu a milosrdenství, jak přísahal tvým otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Bude tě milovat, žehnat ti a rozmnoží tě. Požehná plodu tvého lůna i plodu tvé země, tvému obilí, tvému novému vínu, tvému oleji, vrhu tvého dobytka i přírůstku tvého stáda v zemi, o které přísahal tvým otcům, že ti ji dá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Požehnaný budeš nade všechny národy. Nebude neplodný či neplodná ⌈u tebe⌉ ani u tvého dobytka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Hospodin od tebe odvrátí každou nemoc. ⌈Žádnou ze zlých chorob Egypta, které jsi poznal, nevloží na tebe,⌉ ale dá je na všechny, kdo tě nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Pohlť všechny národy, které ti Hospodin, tvůj Bůh, dává. Ať se nad nimi tvé oko neslituje. Nesluž jejich bohům, nebo to pro tebe bude léčkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Kdyby sis ⌈řekl ve svém srdci:⌉ Tyto národy jsou početnější nežli já. Jak bych si je mohl podrobit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Neboj se jich. Stále pamatuj na to, co Hospodin, tvůj Bůh, učinil faraonovi a celému Egyptu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Ty velké zkoušky, které viděly tvé oči, znamení a divy, mocnou ruku a vztaženou paži, kterou tě Hospodin, tvůj Bůh, vyvedl. Tak Hospodin, tvůj Bůh, učiní všem národům, jichž se bojíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Hospodin, tvůj Bůh, na ně pošle dokonce i děs, dokud nevyhynou ti, kteří zůstali a skryli se před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Neměj z nich strach, neboť Hospodin, tvůj Bůh, je ve tvém středu, Bůh velký a hrozný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Hospodin, tvůj Bůh, vyžene tyto národy před tebou ⌈kousek po kousku.⌉ Nemůžeš s nimi skoncovat rychle, jinak by se proti tobě rozmnožila polní zvěř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Hospodin, tvůj Bůh, ti je vydá, uvrhne je do velkého zmatku, až budou vyhlazeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Vydá do tvé ruky jejich krále, odstraníš jejich jméno zpod nebes. Nikdo se proti tobě nepostaví, dokud je nevyhladíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Tesané modly jejich bohů spalte ohněm. Nedychti po stříbru a zlatu, které je na nich, a ne ber si ho, jinak ⌈se na něj chytíš.⌉ Je to ohavností pro Hospodina, tvého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Nevnášej do svého domu žádnou ohavnost, ať se ne dostaneš pod klatbu jako ona. Naprosto si to oškliv a zcela tím opovrhuj, vždyť je ⌈to pod klatbou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Každý příkaz, který ti dnes přikazuji, zachovávejte a plňte, abyste zůstali naživu a rozmnožili se, šli a obsadili zemi, kterou Hospodin odpřisáhl vašim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Pamatuj na celou cestu, kterou tě Hospodin, tvůj Bůh, vedl těchto čtyřicet let pustinou, aby tě pokořil, vyzkoušel a poznal, co je ve tvém srdci, jestli budeš zachovávat jeho příkazy, nebo ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Pokořil tě, nechal tě hladovět, a pak tě krmil manou, kterou jsi neznal a kterou neznali tvoji otcové, aby tě přivedl k poznání, že člověk nežije jenom chlebem, ale že člověk žije vším, co vychází z Hospodinových úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Tvůj plášť se na tobě neobnosil, tvoje nohy neopuchly po těchto čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Věz tedy ve svém srdci, že tak jako člověk vychovává svého syna, tak Hospodin, tvůj Bůh, vychovává tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Zachovávej příkazy Hospodina, svého Boha, ⌈abys chodil po jeho cestách a bál⌉ se ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Vždyť Hospodin, tvůj Bůh, tě přivádí do dobré země, země s potoky plnými vody, s prameny a se zřídly vyvěrajícími ⌈v údolích⌉ a horách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'do země pšenice a ječmene, révy, fíkovníků a granátovníků, do země ⌈olivových hájů, oleje⌉ a medu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'do země, kde ⌈nebudeš jíst pokrm v chudobě,⌉ kde nebudeš mít ničeho nedostatek, do země, jejíž kameny obsahují železo a z jejíchž hor ⌈ můžeš těžit⌉ měď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Až se najíš a nasytíš, dobrořeč Hospodinu, svému Bohu, za tu dobrou zemi, kterou ti dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Měj se na pozoru, ⌈abys nezapomněl⌉ na Hospodina, svého Boha, ⌈a ne přestal zachovávat⌉ jeho příkazy, nařízení a ustanovení, která ti dnes dávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, '⌈Jinak se najíš a nasytíš,⌉ postavíš si hezké domy a zabydlíš se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'rozmnoží se tvůj ⌈skot a brav,⌉ přibude ti stříbra a zlata a ⌈všeho budeš mít hodně,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'ale tvé srdce se potom pozdvihne a zapomeneš na Hospodina, svého Boha, -- který tě vyvedl z egyptské země, z domu otroctví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'který tě vodil velkou a obávanou pustinou, krajinou ohnivých hadů a štírů, vyprahlou zemí, kde není voda, který ti vyvedl vodu z tvrdé skály,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'který tě v pustině krmil manou, kterou neznali tvoji otcové, aby tě pokořil a vyzkoušel a nakonec ti prokázal dobro --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'a ⌈řekneš si v srdci:⌉ Tento majetek ⌈jsem si získal svou mocí a silou své ruky!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Pamatuj tehdy na Hospodina, svého Boha, že on ti dává moc získat majetek, aby naplnil svou smlouvu, kterou odpřisáhl tvým otcům, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'I stane se, když opravdu zapomeneš na Hospodina, svého Boha, půjdeš za jinými bohy, budeš jim sloužit a klanět se jim, varuji vás dnes, že jistě zahynete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Jako národy, které Hospodin před vámi vyhubil, tak zahynete, za to, že jste neuposlechli Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Slyš, Izraeli, ⌈teď projdeš⌉ Jordánem, abys šel obsadit národy větší a mocnější než jsi ty, města velká a opevněná až k nebesům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Potomci Anákovců jsou lidem velkým a vysokým; ⌈víš přece a slyšel jsi⌉ říkat: Kdo se může postavit proti synům Anákovým?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Věz tedy dnes, že Hospodin, tvůj Bůh, ten, který prochází před tebou, je oheň stravující. On je vyhladí, on je před tebou pokoří. Podrobíš si je a rychle je vyhubíš, tak jak ti Hospodin řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Až je Hospodin, tvůj Bůh, před tebou vypudí, neříkej si v srdci: Pro mou spravedlnost mě Hospodin přivedl, abych obsadil tuto zemi. Pro ničemnost těchto národů je Hospodin před tebou vyhání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ne pro svou spravedlnost a přímost svého srdce jdeš obsadit jejich zemi, ale pro ničemnost těchto národů je Hospodin, tvůj Bůh, před tebou vyhání a aby se naplnilo slovo, které Hospodin odpřisáhl tvým otcům, Abrahamovi, Izákovi a Jákobovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Věz tedy, že ne pro tvou spravedlnost ti Hospodin, tvůj Bůh, dává tuto dobrou zemi, abys ji obsadil. Vždyť jsi lidem tvrdé šíje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Vzpomeň si a nezapomeň, jak jsi v pustině podněcoval Hospodina, svého Boha, ke hněvu. Ode dne, kdy jsi vyšel z egyptské země, až do ⌈svého příchodu⌉ na toto místo, jste se vůči Hospodinu vzpírali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Na Chorébu jste podnítili Hospodina ke hněvu, takže se na vás Hospodin rozhněval a chtěl vás vyhladit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Když jsem vystoupil na horu, abych přijal kamenné desky, desky smlouvy, kterou s vámi Hospodin uzavřel, pobyl jsem na hoře čtyřicet dní a čtyřicet nocí. Nejedl jsem chléb a nepil jsem vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Hospodin mi dal dvě kamenné desky popsané Božím prstem a na nich byla všechna slova, která ⌈k vám⌉ Hospodin na hoře promluvil z ohně v den shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'I stalo se, že po čtyřiceti dnech a čtyřiceti nocích mi Hospodin dal dvě kamenné desky, desky smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Hospodin mi řekl: Vstaň a rychle odsud sestup, protože tvůj lid, který jsi vyvedl z Egypta, propadl zvrácenosti. Rychle se odvrátili od cesty, kterou jsem jim přikázal, a udělali si litou modlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Hospodin mi řekl: Díval jsem se na tento lid. Hle, je to lid tvrdé šíje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Nech mě, ať je vyhladím a jejich jméno vymažu zpod nebes; tebe však učiním mocnějším a početnějším národem nežli je tento.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, '⌈Vydal jsem se na cestu⌉ a sestoupil jsem z hory -- zatímco hora plála ohněm -- a dvě desky smlouvy ⌈ jsem měl ve svých rukou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Podíval jsem se a uviděl jsem, že jste zhřešili proti Hospodinu, svému Bohu, a udělali jste si slité tele. Rychle jste se odvrátili od cesty, kterou vám Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Uchopil jsem obě desky, odhodil jsem je ze svých rukou a před vašima očima jsem je roztřískal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, '⌈Padl jsem a ležel ⌉ před Hospodinem a jako předtím jsem čtyřicet dní a čtyřicet nocí nejedl chléb a nepil vodu -- to kvůli tomu vašemu hříchu, kterým jste zhřešili, když jste páchali to, co je zlé v Hospodinových očích, a provokovali jste ho k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Lekal jsem se hněvu a zloby, kterou se na vás Hospodin rozhněval a chtěl vás vyhladit. Hospodin mě i tentokrát vyslyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'I na Árona se Hospodin velmi rozhněval a chtěl ho vyhladit. Proto jsem se v té době modlil také za Árona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, '⌈Váš hřích,⌉ který jste udělali, to tele, jsem vzal, spálil ho ohněm, rozbil ho, drtil, až bylo zcela rozdrceno na prach. Ten prach jsem hodil do potoka, ⌈který teče⌉ z hory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Také v Tabéře, v Masse a v Kibrót–taavě jste Hospodina podněcovali ke hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'A když vás Hospodin poslal z Kádeš–barneje se slovy: Vytáhněte a obsaďte zemi, kterou jsem vám dal, vzepřeli jste se příkazu Hospodina, svého Boha, nevěřili jste mu a neuposlechli jste ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Vzpírali jste se vůči Hospodinu od doby, co vás znám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Když jsem ležel před Hospodinem těch čtyřicet dní a čtyřicet nocí (kdy jsem padl, protože Hospodin řekl, že vás chce vyhladit),');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'modlil jsem se k Hospodinu: Panovníku Hospodine, neznič svůj lid, své dědictví, které jsi vykoupil svou velikostí, jež jsi vyvedl z Egypta mocnou rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Pamatuj na své otroky, na Abrahama, Izáka a Jákoba. Nehleď na tvrdost tohoto lidu, na jeho ničemnost a hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Ať neřeknou obyvatelé země, ze které jsi nás vyvedl: Hospodin je nebyl schopen přivést do země, o které jim řekl. Z nenávisti k nim je vyvedl, aby je v pustině usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Jsou přece tvým lidem, tvým dědictvím, které jsi vyvedl svou velkou mocí a vztaženou paží!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'V té době mi Hospodin řekl: Vytesej si dvě kamenné desky, stejné jako ty první, a vystup ke mně na horu. Udělej si i dřevěnou truhlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Napíši na ty desky slova, která byla na prvních deskách, jež jsi roztřískal, a vložíš je do truhly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Udělal jsem truhlu z akáciového dřeva a vytesal jsem dvě kamenné desky, stejné jako ty první. Vystoupil jsem na horu a ty dvě desky jsem vzal s sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'On napsal na desky stejný ⌈zápis, jako ten první,⌉ Deset slov, která k vám Hospodin na hoře promluvil z ohně v den shromáždění. Pak mi je Hospodin dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Vydal jsem se na cestu, sestoupil z hory a vložil jsem desky do truhly, kterou jsem udělal. Zůstaly tam, jak mi přikázal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Synové Izraele vyrazili z Beerót–bene–jaakanu do Mósery. Tam zemřel Áron a byl tam pohřben. Jeho syn Eleazar sloužil jako kněz místo něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Odtamtud vyrazili do Gudgódu a z Gudgódu do Jotbaty, do země potoků plných vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'V té době Hospodin oddělil kmen Léviho, aby nosili ⌈truhlu Hospodinovy smlouvy⌉, stáli před Hospodinem, sloužili mu a žehnali v jeho jménu, jak je tomu až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Proto neměl Lévi podíl a dědictví se svými bratry. Hospodin je jeho dědictvím, jak k němu promluvil Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Já jsem zůstal na hoře jako poprvé čtyřicet dní a čtyřicet nocí. Hospodin mě vyslyšel také tentokrát. Hospodin tě již nechtěl zničit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Hospodin mi řekl: Vstaň, ⌈jdi na odchodu⌉ před lidem. Ať vejdou a obsadí zemi, o které jsem přísahal jejich otcům, že jim ji dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nuže, Izraeli, co od tebe žádá Hospodin, tvůj Bůh? Jenom aby ses bál Hospodina, svého Boha, chodil po všech jeho cestách, miloval ho a sloužil Hospodinu, svému Bohu, celým svým srdcem a celou svou duší');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'a zachovával Hospodinovy příkazy a jeho ustanovení, která ti dnes přikazuji, aby ti bylo dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Hle, Hospodinu, tvému Bohu, patří nebesa i nebesa nebes, země i všechno, co je na ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Avšak jenom k tvým otcům Hospodin přilnul, zamiloval si je a vyvolil jejich potomstvo po nich, totiž vás, ze všech národů, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Obřežte proto předkožku svého srdce a nezatvrzujte již svou šíji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Vždyť Hospodin, váš Bůh, je Bohem bohů a Pánem pánů, Bohem velkým, mocným a hrozným, který ⌈nikomu nestraní⌉ a nepřijímá úplatek,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'zjednává právo sirotkovi a vdově, miluje příchozího a dává mu pokrm a oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Proto milujte příchozího, neboť jste byli příchozími v egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Hospodina, svého Boha, se boj, jemu služ, k němu přilni a v jeho jménu přísahej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'On je tvá chvála, on je tvým Bohem, který ⌈pro tebe⌉ učinil tyto velké a hrůzu vzbuzující činy, které viděly tvé oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'V sedmdesáti lidech sestoupili tvoji otcové do Egypta, a teď tě Hospodin, tvůj Bůh, ⌈proměnil v takové množství,⌉ jako je hvězd na nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Miluj Hospodina, svého Boha, a zachovávej jeho řád, jeho ustanovení, jeho nařízení a jeho příkazy po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Rozumějte tedy dnes, že to ne byli vaši ⌈synové, kteří by poznali a viděli⌉ kázeň Hospodina, vašeho Boha, -- jeho velikost, jeho mocnou ruku a vztaženou paži,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'jeho znamení a skutky, které učinil uprostřed Egypta faraonovi, egyptskému králi, i celé jeho zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'to, co učinil egyptskému vojsku, jeho koňům a jeho vozbě, jak nad nimi nechal proudit vodu Rákosového moře, když vás pronásledovali a Hospodin je zničil, jak je tomu až dodnes,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'to, co učinil v pustině vám, než jste přišli až na toto místo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'to, co učinil Dátanovi a Abíramovi, synovi Elíaba, syna Rúbenova, když uprostřed celého Izraele země otevřela svá ústa a pohltila je i jejich rodiny, jejich stany i vše živé v jejich šlépějích, --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'ale vaše oči viděly všechny ty velké Hospodinovy skutky, které učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Zachovávejte každý příkaz, který ti dnes přikazuji, abyste byli silní, vešli a obsadili zemi, do které procházíte Jordánem, abyste ji obsadili,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'a aby se prodloužily dny v zemi, o které Hospodin přísahal vašim otcům, že ji dá jim a jejich potomstvu, zemi oplývající mlékem a medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Neboť země, do které přicházíš, abys ji obsadil, není jako egyptská země, z níž jste vyšli, kde zaseješ semeno a ⌈ musíš šlapat a zavlažovat⌉ ji jako zelinářskou zahradu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Země, do které procházíte Jordánem, abyste ji obsadili, je zemí hor a údolí; ⌈pije vodu deště⌉ z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Zemí, o kterou se stará Hospodin, tvůj Bůh. Oči Hospodina, tvého Boha, jsou na ni stále upřeny, od počátku až do konce roku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'I stane se, jestliže budete opravdu poslouchat mé příkazy, které vám dnes přikazuji, budete milovat Hospodina, svého Boha, a sloužit mu celým svým srdcem a celou svou duší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'že dám ⌈vaší zemi ve svůj čas déšť⌉ ⌈podzimní i jarní⌉ a sklidíš své obilí, nové víno i svůj olej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Dám také zeleň na tvé pole pro tvůj dobytek, najíš se a nasytíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Mějte se na pozoru, aby se vaše srdce nedalo svést a ne odvrátili jste se, ne sloužili jiným bohům a ne klaněli se jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Nebo proti vám vzplane Hospodinův hněv, uzavře nebesa, nebude déšť, země nevydá svou úrodu a z té dobré země, kterou vám Hospodin dává, rychle vyhynete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Vložte tato má slova do svého srdce a do své duše. Přivažte si je jako znamení na ruku, ať jsou značkou mezi vašima očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Učte je své syny -- mluv o nich, když pobýváš ve svém domě, i když chodíš po cestě, když ležíš i když vstáváš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Napište je na veřeje svého domu a na své brány,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'aby se rozmnožily vaše dny a dny vašich synů v zemi, o které Hospodin přísahal vašim otcům, že jim ji dá, tak jako ⌈dny nebes⌉ nad zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Jestliže budete bedlivě zachovávat každý tento příkaz, který vám přikazuji, budete– li jej plnit, milovat Hospodina, svého Boha, chodit po všech jeho cestách a přilnete k němu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Hospodin před vámi vyžene všechny tyto národy a obsadíte národy větší a mocnější, než jste vy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Každé místo, na které šlápne vaše noha, bude patřit vám; od pustiny až k Libanonu, od Řeky, řeky Eufratu, až k Západnímu moři bude vaše území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nikdo se proti vám nepostaví. Hospodin, váš Bůh, dá strach a bázeň z vás na povrch celé země, na kterou šlápnete, tak jak vám řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Pohleď, kladu dnes před vás požehnání a kletbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Požehnání, když budete poslouchat příkazy Hospodina, svého Boha, které vám dnes přikazuji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'a kletbu, jestliže nebudete poslouchat příkazy Hospodina, svého Boha, a odvrátíte se od té cesty, kterou vám dnes přikazuji, a půjdete za jinými bohy, které jste neznali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'I stane se, až tě Hospodin, tvůj Bůh, přivede do země, kterou jdeš obsadit, že budeš dávat požehnání na hoře Gerizímu a kletbu na hoře Ébalu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Jsou přece za Jordánem, směrem na západ slunce, v zemi Kenaanců sídlících v Arabě, naproti Gilgálu, blízko dubů v Móre.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Až projdete Jordánem, abyste vešli a obsadili zemi, kterou vám dává Hospodin, váš Bůh, obsadíte ji a usídlíte se v ní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'zachovávejte a plňte všechna ustanovení a nařízení, která před vás dnes kladu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Toto jsou ustanovení a nařízení, která budete zachovávat a plnit v zemi, již dal Hospodin, Bůh tvých otců, tobě, abys ji obsadil, po všechny dny, co budete živi na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Zcela zničte všechna místa, kde národy, jež obsadíte, sloužily svým bohům -- na vysokých horách, na návrších a pod každým zeleným stromem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Strhněte jejich oltáře, roztřískejte jejich posvátné sloupy, jejich posvátné kůly spalte ohněm, tesané modly jejich bohů pokácejte a odstraňte jejich jméno z onoho místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, '⌈Nepočínejte si takto vůči⌉ Hospodinu, svému Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'ale vyhledejte místo, které Hospodin, váš Bůh, vyvolí ze všech vašich kmenů, aby si tam učinil jméno a tam přebýval, a tam choď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Tam přinášejte své zápalné oběti a obětní hody, své desátky a dary pozdvihování svých rukou, své slíbené a dobrovolné oběti i prvorozené ze svého skotu a bravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Tam jezte vy i vaše rodiny před Hospodinem, svým Bohem, a radujte se ze všeho zisku svých rukou, protože ti požehnal Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Nejednejte tak, jak tady dnes jednáme my, kdy každý dělá to, co ⌈je správné v jeho očích,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'neboť jste dosud nevešli do odpočinutí a do dědictví, které ti dává Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Až přejdete přes Jordán a budete sídlit v zemi, kterou vám Hospodin, váš Bůh, dává do dědictví a dá vám odpočinek od všech vašich okolních nepřátel a budete bydlet v bezpečí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'pak na místo, které Hospodin, váš Bůh, vyvolí, aby tam přebývalo jeho jméno, budete přinášet všechno, co vám přikazuji: Své zápalné oběti, své obětní hody, své desátky, dary pozdvihování svých rukou a všechno nejlepší ze svých slíbených obětí, jež jste slíbili Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Budete se radovat před Hospodinem, svým Bohem, vy i vaši synové, vaše dcery, vaši otroci, vaše otrokyně i Lévijec, který je ve vašich branách, protože s vámi nemá podíl a dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Měj se na pozoru, abys nepřinášel své zápalné oběti na jakémkoliv místě, které si vyhlédneš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'ale jenom na místě, které Hospodin vyvolí v jednom ze tvých kmenů, tam přinášej své zápalné oběti, tam dělej všechno, co ti přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, '⌈Ovšem zcela podle touhy své duše⌉ ⌈ můžeš zabíjet⌉ a jíst maso ⌈ve všech svých branách⌉ podle požehnání Hospodina, tvého Boha, které ti dal. Nečistý i čistý smí z toho jíst jako z gazely či z jelena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Pouze krev nejezte. Vylej ji na zem jako vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Ve svých branách nesmíš jíst desátek ze svého obilí, z nového vína a oleje ani z prvorozených ze svého skotu a bravu, jakékoliv ⌈slíbené oběti,⌉ které jsi slíbil, ani dobrovolné oběti či dary pozdvihování tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Ale jez je před Hospodinem, svým Bohem, jenom na místě, které Hospodin, tvůj Bůh, vyvolí -- ty i tvůj syn, tvá dcera, tvůj otrok, tvá otrokyně i Lévijec, který je ve tvých branách, a raduj se před Hospodinem, svým Bohem, ze všeho zisku svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Měj se na pozoru, abys nezanedbával Lévijce po všechny dny, které budeš žít ve své zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Až Hospodin, tvůj Bůh, rozšíří tvé území tak, jak ti řekl, a povíš si: Chci jíst maso, protože tvá duše bude toužit jíst maso, jez maso zcela podle touhy své duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Když bude od tebe daleko to místo, které Hospodin, tvůj Bůh, vyvolí, aby si tam učinil jméno, zabíjej ze svého skotu a bravu, který ti Hospodin dal, tak jak jsem ti přikázal, a jez ve svých branách zcela podle touhy své duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Avšak jako se jí gazela či jelen, tak z toho smíš jíst; smí z toho jíst nečistý i čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Pouze ⌈buď pevný v tom,⌉ abys nejedl krev, protože krev je život. Nejez život s masem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Nejez ji. Vylej ji na zemi jako vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Nejez ji, aby se vedlo dobře tobě i tvým synům po tobě, když budeš dělat to, co je správné v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Pouze své ⌈posvátné maso,⌉ které budeš mít, a své slíbené oběti vezmi a přines na místo, které Hospodin vyvolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Připrav své zápalné oběti, maso i krev, na oltář Hospodina, svého Boha. Krev tvých obětních hodů se vyleje na oltář Hospodina, tvého Boha, a maso sněz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Zachovávej a poslouchej všechna tato slova, která ti přikazuji, aby se vedlo dobře tobě i tvým synům po tobě až navěky, když budeš dělat to, co je dobré a správné v očích Hospodina, tvého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Až Hospodin, tvůj Bůh, před tebou vyhladí národy, které přicházíš obsadit, až je obsadíš a usídlíš se v jejich zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'měj se na pozoru, aby ses nechytil do pasti ⌈ a ne následoval je,⌉ poté, co před tebou byli vyhlazeni, a nevyptával ses na jejich bohy se slovy: Jak sloužily tyto národy svým bohům? Budu to tak dělat i já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, '⌈Nejednej tak vůči⌉ Hospodinu, svému Bohu. Vždyť oni dělali kvůli svým bohům všechno, co je pro Hospodina ohavností, co nenávidí. Ano, dokonce své syny a své dcery spalují kvůli svým bohům ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, '⌈Všechno, co⌉ vám přikazuji, to zachovávejte a plňte. Nic k tomu nepřidávej ani z toho nic neubírej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Jestliže ve tvém středu povstane prorok či ⌈ten, kdo má sen,⌉ a ⌈učiní pro tebe⌉ znamení nebo div,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'i kdyby se naplnilo to znamení nebo div, které ti řekl se slovy: Pojďme za jinými bohy, (které jsi neznal) a služme jim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'neuposlechni slova toho proroka či toho, kdo má sen, protože Hospodin, váš Bůh, vás zkouší, aby poznal, jestli milujete Hospodina, svého Boha, celým svým srdcem a celou svou duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Za Hospodinem, svým Bohem, jděte, jeho se bojte, jeho příkazy zachovávejte, jej poslouchejte, jemu služte a k němu přilněte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Takový prorok či ten, kdo měl sen, ať je usmrcen, neboť naváděl ke vzpouře proti Hospodinu, vašemu Bohu, který vás vyvedl z egyptské země a vykoupil tě z domu otroctví. ⌈ Chtěl tě svést⌉ z cesty, po které ti Hospodin, tvůj Bůh, přikázal jít. Tak ⌈vyhlaď zlo ze svého středu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Kdyby tě tvůj bratr, syn tvé matky, nebo tvůj syn nebo tvá dcera nebo ⌈žena tvého klína⌉ nebo tvůj ⌈přítel, který ti je drahý jako tvůj život,⌉ tajně naváděl slovy: Pojďme sloužit jiným bohům, které jsi neznal ty ani tvoji otcové,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'některým z bohů národů, které jsou okolo vás, ať jsou blízko tebe či daleko od tebe, z jednoho konce země až na druhý,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'nesvoluj mu, neposlouchej ho, ať se nad ním tvé oko neslituje, neměj soucit a nekryj ho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'ale rozhodně ho zabij. Ať je tvá ruka jako první proti němu, abys ho usmrtil, a potom ruka všeho lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Ukamenuj ho, ať zemře, protože tě chtěl svést od Hospodina, tvého Boha, který tě vyvedl z egyptské země, z domu otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, '⌈Když o tom všichni Izraelci uslyší,⌉ budou se bát a takovou zlou věc ve tvém středu již páchat nebudou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, '⌈Kdyby ses v některém z měst, která ti Hospodin, tvůj Bůh, dává, abys tam sídlil, doslechl,⌉ že');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'ze tvého středu vyšli nějací ničemníci a svedli obyvatele svého města slovy: Pojďme sloužit jiným bohům, které jste neznali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'vyšetři to, prověř a dobře se vyptej. Jestliže by to byla ⌈pravda, jistá věc,⌉ a ve tvém středu byla spáchána tato ohavnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'jistě pobij obyvatele toho města ostřím meče. Ostřím meče zasvěť zkáze je, vše, co je v něm, i jeho dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Všechnu ⌈kořist z něj⌉ shromáždi doprostřed náměstí a město i všechnu kořist z něj spal ohněm jako dokonalou oběť Hospodinu, svému Bohu. ⌈Stane se⌉ věčnou ruinou, nebude již zbudováno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Ať ⌈ve tvé ruce neulpí⌉ nic z toho, co bylo zasvěceno zkáze, aby se Hospodin odvrátil od svého planoucího hněvu, dal ti dojít slitování, měl s tebou slitování a rozmnožil tě tak, jak přísahal tvým otcům --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 19, 'když uposlechneš Hospodina, svého Boha, budeš zachovávat všechny jeho příkazy, které ti dnes přikazuji, a budeš dělat to, co je správné v očích Hospodina, tvého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Jste synové Hospodina, svého Boha. Kvůli zemřelému si nezasazujte rány ani si nedělejte lysinu mezi očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Vždyť jsi svatým lidem Hospodinu, svému Bohu, tebe Hospodin vyvolil ze všech národů, které jsou na povrchu země, abys byl jeho lidem, jeho vlastnictvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Nejez nic ohavného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Toto jsou zvířata, která budete jíst: býka, ovce a kozy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'jelena, gazelu, srnce, divokou kozu, antilopu, ⌈divokou ovci⌉ a horskou kozu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'tedy všechna zvířata, která mají rozdělená kopyta, obě kopyta zcela rozdvojená, přežvýkavce mezi zvířaty. Ta jezte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Z přežvýkavců a těch, kteří mají rozdělená, rozdvojená kopyta, však nejezte tyto: velblouda, zajíce a damana, protože jsou to přežvýkavci, ale kopyta rozdělená nemají. Jsou pro vás nečistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Ani vepře, neboť má kopyta rozdělená, ale nepřežvykuje. Je pro vás nečistý. Jejich maso nejezte a jejich zdechlin se nedotýkejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Ze všeho, co je ve vodě, jezte toto: Všechno, co má ploutve a šupiny, jezte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'a všechno, co nemá ploutve a šupiny, nejezte. Je to pro vás nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Všechny čisté ptáky jezte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Nejezte z nich tyto: orla, supa, orlovce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, '⌈luňáka červeného,⌉ ⌈luňáka černého,⌉ luňáky ⌈všeho druhu,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, '⌈žádný druh havrana,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'pštrosa, sovu, racka, sokoly všeho druhu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'sýčka, výra, sovu pálenou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'pelikána, mrchožrouta a kormorána,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'čápa, volavky všeho druhu, dudka, netopýra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Také ⌈všechen okřídlený hmyz⌉ je pro vás nečistý. ⌈ Ať se nejí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Všechny čisté ptáky jezte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Nejezte žádnou zdechlinu. Dej ji příchozímu, který je ve tvých branách, ať ji sní, nebo prodej cizinci, ale ty jsi svatým lidem Hospodinu, svému Bohu. Nevař kůzle v mléce jeho matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Jistě dávej desátek ze vší úrody svého semena, to, co ⌈přináší pole,⌉ ⌈rok co rok.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Na místě, které on vyvolí, aby tam přebývalo jeho jméno, jez před Hospodinem, svým Bohem, desátek ze svého obilí, z nového vína a oleje a z prvorozených svého skotu a bravu, aby ses naučil bát se Hospodina, svého Boha, po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Když by cesta byla pro tebe dlouhá, takže bys nebyl schopen to donést, protože místo, které Hospodin, tvůj Bůh, vyvolí, aby si tam učinil jméno, je od tebe daleko a protože ti Hospodin, tvůj Bůh, požehnal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, '⌈proměň to ve stříbro,⌉ ⌈vezmi zabalené stříbro s sebou,⌉ jdi na místo, které Hospodin, tvůj Bůh, vyvolí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'a dej stříbro za všechno, po čem tvá duše touží, za skot a brav, víno a pivo, za cokoliv, co si přeje tvá duše. Tam jez před Hospodinem, svým Bohem, a raduj se ty i tvá rodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Lévijce, který je ve tvých branách, nezanedbávej, protože s tebou nemá podíl ani dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Vždy ⌈po třetím roce⌉ přines celý desátek ze své úrody toho roku a zanech je ve svých branách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Ať přijde Lévijec, protože s tebou nemá podíl a dědictví, i příchozí, sirotek a vdova, kteří jsou ve tvých branách, a nechť jedí a nasytí se, aby ti Hospodin, tvůj Bůh, požehnal v každém díle tvých rukou, které konáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Vždy po sedmém roce proveď prominutí dluhu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Toto je způsob prominutí dluhu: Každý věřitel ať promine to, co půjčil svému bližnímu; ať ⌈nevystavuje svého bližního a svého bratra útlaku,⌉ protože bylo vyhlášeno prominutí dluhu kvůli Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Cizince můžeš vystavovat útlaku, ale jestliže máš něco u svého bratra, promiň mu to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Nicméně nebudeš mít mezi sebou nuzného, protože Hospodin ti jistě požehná v zemi, kterou ti Hospodin, tvůj Bůh, dává za dědictví, abys ji obsadil --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'pokud ovšem opravdu uposlechneš Hospodina, svého Boha, a budeš zachovávat a plnit každý tento příkaz, který ti dnes přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Vždyť Hospodin, tvůj Bůh, ti požehná, tak jak ti řekl. Budeš půjčovat mnohým národům, ale sám si nebudeš půjčovat, budeš vládnout nad mnohými národy, ale ony nad tebou nebudou vládnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Když by byl u tebe nuzný -- někdo ze tvých bratrů, v některé ze tvých bran ve tvé zemi, kterou ti dává Hospodin, tvůj Bůh, -- nezatvrzuj své srdce a nezavírej svou ruku před svým nuzným bratrem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'ale jistě pro něj otevři svou ruku a rozhodně mu půjč podle míry jeho nouze, to, v čem má nedostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Měj se na pozoru, aby ve tvém srdci nebylo něco ničemného, když by sis říkal: Blíží se rok sedmý, rok prominutí dluhu a abys ⌈ne byl lakomý⌉ vůči svému nuznému bratrovi a nic bys mu nedal. Volal by proti tobě k Hospodinu a ⌈dopadl by na tebe trest za hřích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Dej mu rád a ⌈tvé srdce ať není zlé,⌉ když mu budeš dávat, protože kvůli tomu ti Hospodin, tvůj Bůh, požehná při všem tvém díle a při všem podnikání tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Nuzný totiž nevymizí ze země. Proto ti přikazuji: Jistě otvírej svou ruku pro svého bratra, pro ⌈chudého a nuzného⌉ ve své zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Jestliže ti bude prodán tvůj bratr, Hebrej či Hebrejka, bude ti sloužit šest let a v sedmém roce ho propusť ⌈ na svobodu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Až ho budeš propouštět na svobodu, nepropusť ho s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Štědře ho zaopatři ze svého stáda, ze svého ⌈humna i lisu;⌉ dej mu z toho, čím ti Hospodin, tvůj Bůh, požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Pamatuj, že jsi byl otrokem v egyptské zemi, a Hospodin, tvůj Bůh, tě vykoupil. Proto ti dnes toto přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'I stane se, jestliže ti řekne: Ne chci od tebe odejít, neboť si zamiloval tebe i tvou rodinu, jelikož mu je u tebe dobře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'potom vezmi šídlo, ⌈probodni mu ucho na dveřích⌉ a stane se navěky tvým otrokem. Tak jednej také se svou otrokyní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Ať ti to nepřipadá těžké propustit ho na svobodu, neboť ti sloužil po šest let dvojnásobně nežli za mzdu najatý; a Hospodin, tvůj Bůh, ti požehná při všem, co budeš dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Všechno prvorozené mužského pohlaví, co se narodí ve tvém skotu a bravu, zasvěť Hospodinu, svému Bohu. Nepracuj se svým prvorozeným býkem a nestříhej prvorozeného ze svých ovcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Sněz to rok co rok před Hospodinem, svým Bohem, na místě, které Hospodin vyvolí, ty i tvá rodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Jestliže však na něm bude vada, bude chromé či slepé, s jakoukoliv vážnou vadou, neobětuj ho Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Sněz ho ve svých branách; smí z toho jíst nečistý i čistý jako z gazely či z jelena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Pouze jeho krev nejez. Vylej ji na zemi jako vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Zachovávej měsíc ábíb a slav Velikonoce Hospodinu, svému Bohu, protože v měsíci ábíbu tě Hospodin, tvůj Bůh, vyvedl v noci z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Na místě, které Hospodin vyvolí, aby tam přebývalo jeho jméno, obětuj jako velikonoční oběť Hospodinu, svému Bohu, brav a skot.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Nejez ⌈k němu⌉ nic kvašeného; po sedm dní k němu jez nekvašené chleby, chléb soužení, protože jsi ve spěchu vyšel z egyptské země, abys pamatoval na den, kdy jsi vyšel z egyptské země, po všechny dny svého života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Na celém tvém území ať u tebe po sedm dní není vidět kvas; z masa, které obětuješ večer prvního dne, nezůstane nic do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Nesmíš obětovat velikonoční oběť v některé ze svých bran, které ti Hospodin, tvůj Bůh, dává,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'ale jenom na místě, které Hospodin, tvůj Bůh, vyvolí, aby tam přebývalo jeho jméno, tam obětuj velikonoční oběť, večer, ⌈po západu⌉ slunce, v čase, kdy jsi vyšel z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Uvař ho a sněz na místě, které Hospodin, tvůj Bůh, vyvolí a ráno se vydej na cestu a jdi ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Šest dní jez nekvašený chléb a sedmého dne ať je shromáždění Hospodinu, tvému Bohu; nedělej žádnou práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Spočítej si sedm týdnů. Začni počítat sedm týdnů tehdy, když je prvně položen srp na nepožaté obilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Potom slav svátek týdnů Hospodinu, svému Bohu, a dávej dobrovolné oběti podle míry, jakou ti Hospodin, tvůj Bůh, požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Raduj se před Hospodinem, svým Bohem, ty i tvůj syn, tvá dcera, tvůj otrok, tvá otrokyně i Lévijec, který je ve tvých branách, příchozí, sirotek i vdova, kteří jsou ve tvém středu, na místě, které Hospodin, tvůj Bůh, vyvolí, aby tam přebývalo jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Pamatuj, že jsi byl otrokem v Egyptě, a zachovávej a plň tato ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Svátek stánků slav po sedm dní, když sklidíš úrodu ze svého humna a lisu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Raduj se ⌈ze svého⌉ svátku ty i tvůj syn, tvá dcera, tvůj otrok, tvá otrokyně i Lévijec, příchozí, sirotek a vdova, kteří jsou ve tvých branách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Po sedm dní slav svátek Hospodinu, svému Bohu, na místě, které Hospodin vyvolí, protože Hospodin, tvůj Bůh, ti požehná ve vší tvé úrodě a při všem díle tvých rukou. Jen buď radostný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Třikrát za rok ať se každý, ⌈ kdo je u tebe⌉ mužského pohlaví, ukáže před Hospodinem, tvým Bohem, na místě, které vyvolí -- při svátku nekvašených chlebů, při svátku týdnů a při svátku stánků. Ať se neukáže před Hospodinem s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Ale každý ⌈se svým darem,⌉ podle požehnání Hospodina, tvého Boha, které ti dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Ve všech svých branách, které ti Hospodin, tvůj Bůh, dává, si pro své kmeny ustanov soudce a správce. Ať soudí lid spravedlivým soudem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Nepřevracej právo a nestraň lidem. Nepřijímej úplatek, protože úplatek oslepuje oči moudrých a podvrací ⌈jednání spravedlivých.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Následuj spravedlnost, ⌈ a jen ⌉ spravedlnost, abys ⌈zůstal naživu⌉ a obsadil zemi, kterou ti Hospodin, tvůj Bůh, dává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Nevysazuj si ⌈žádný strom jako posvátný kůl⌉ vedle oltáře Hospodina, svého Boha, který si uděláš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Nestav si posvátný sloup. To Hospodin, tvůj Bůh, nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Neobětuj Hospodinu, svému Bohu, býka ani ovci, na kterých je vada, cokoliv špatného, protože je to pro Hospodina, tvého Boha, ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Jestliže by se ve tvém středu, v některé z tvých bran, které ti Hospodin, tvůj Bůh, dává, našel muž či žena, kteří by spáchali to, co je zlé v očích Hospodina, tvého Boha, přestoupili by jeho smlouvu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'šli a sloužili jiným bohům, klaněli se jim, před sluncem či měsícem či celým nebeským zástupem, což jsem nepřikázal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'a pokud by ti to bylo oznámeno anebo by ses o tom doslechl, dobře to vyšetři. Jestliže by to byla pravda, jistá věc, a v Izraeli byla spáchána tato ohavnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'vyveď onoho muže nebo onu ženu, kteří spáchali ⌈to zlo,⌉ ke svým branám, muže či ženu, a ukamenuj je, ⌈ať zemřou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Ten, kdo má zemřít, ať je usmrcen ⌈podle svědectví⌉ dvou nebo tří svědků. Ať není usmrcen podle svědectví jediného svědka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Ruka svědků ať je proti němu jako první, aby ho usmrtili, a potom ruka všeho lidu. Tak vyhlaď zlo ze svého středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Jestliže by byla záležitost pro tebe příliš nesnadná k rozhodnutí -- ohledně ⌈různých krveprolití,⌉ ⌈různých právních nároků⌉ a ⌈různých ublížení,⌉ ⌈sporných záležitostí⌉ ve tvých branách -- vstaň a vystup na místo, které Hospodin, tvůj Bůh, vyvolí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'jdi k lévijským kněžím a k soudci, který bude v oněch dnech, vyptej se jich a oni ti oznámí rozsudek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Pak jednej podle toho, co ti oznámí na tom místě, které Hospodin vyvolí. Zachovávej a plň vše tak, jak tě vyučí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Podle poučení, kterým tě vyučí, podle rozsudku, který ti řeknou, jednej. Neodvracej se od toho, co ti oznámí, napravo ani nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Člověk, který by jednal domýšlivě, a neposlechl kněze, jenž tam stojí a slouží Hospodinu, tvému Bohu, či soudce, takový člověk ať zemře. Tak ⌈vyhlaď zlo z Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Když o tom všichni lidé uslyší, budou se bát a nebudou již jednat povýšeně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Až přijdeš do země, kterou ti Hospodin, tvůj Bůh, dává, obsadíš ji a usadíš se v ní a řekneš si: Ustanovím si nad sebou krále jako všechny národy, které jsou okolo mě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'pak rozhodně ustanov králem nad sebou toho, koho Hospodin, tvůj Bůh, vyvolí. Ustanov nad sebou krále ze svých bratří. Nesmíš si nad sebou určit cizince, který není tvým bratrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Jen ať nemá mnoho koní a neposílá lid zpět do Egypta, aby si obstarali mnoho koní. Hospodin vám přece řekl: Již nikdy se nevracejte touto cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Ať nemá mnoho žen, aby se neodvrátilo jeho srdce, ani příliš mnoho stříbra a zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Až usedne na ⌈svůj královský trůn,⌉ ať ⌈si před lévijskými kněžími napíše⌉ do knihy opis tohoto zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Ať je u něj a ať si v něm čte po všechny dny svého života, aby se naučil bát Hospodina, svého Boha, zachovávat všechna slova tohoto zákona a tato ustanovení a plnit je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Ať není jeho srdce povýšené nad jeho bratry a ať se neodvrátí od příkazů ⌈napravo ani nalevo,⌉ aby ⌈prodloužil dny nad svým královstvím⌉ uprostřed Izraele on i jeho synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Lévijští kněží, celý kmen Léviho, ať nemá podíl a dědictví s Izraelem. Ať jedí ohnivé oběti Hospodina, ⌈jeho dědictví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Ať nemá dědictví uprostřed svých bratří. Hospodin je jeho dědictvím, jak mu řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Toto je to, na co mají kněží právo od lidu, od těch, kdo obětují oběti, ať býka či ovci: Knězi se dá plec, čelisti a žaludek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Prvotinu svého obilí, nového vína a oleje i prvotinu stříže ze svých ovcí dej jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Vždyť jej Hospodin, tvůj Bůh, vyvolil ze všech tvých kmenů, aby stál po všechny dny a sloužil v Hospodinově jménu on i jeho synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Když přijde Lévijec z některé ze tvých bran, z celého Izraele, kde pobýval, na místo, které Hospodin vyvolí, (může přijít zcela podle touhy své duše),');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'ať koná bohoslužbu ve jménu Hospodina, svého Boha, jako všichni jeho bratři Lévijci, kteří stojí a slouží před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, '⌈ Ať požívají všichni stejný díl,⌉ bez ohledu na zisk z prodeje ⌈otcovského dědictví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Až přijdeš do země, kterou ti Hospodin, tvůj Bůh, dává, neuč se jednat podle ohavností oněch pohanských národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Ať se ⌈u tebe⌉ nenajde ten, kdo by provedl svého syna či svou dceru ohněm, věštec přinášející věštby, hadač ani ten, kdo vykládá znamení, ani čaroděj');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'ani zaklínač ani ten, kdo se doptává ducha zemřelého, ani věštec ani ten, kdo se dotazuje mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Vždyť každý, kdo dělá takové věci, je ohavností pro Hospodina. Kvůli těmto ohavnostem je před tebou Hospodin, tvůj Bůh, vyhání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Buď bezúhonný vůči Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Ano, tyto národy, které obsadíš, poslouchají hadače a věštce. ⌈Ale co se tebe týče,⌉ tobě to Hospodin, tvůj Bůh, nedovolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Hospodin, tvůj Bůh, ti ustanoví proroka jako jsem já ze tvého středu, ze tvých bratří. Jeho poslouchejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, '⌈Právě to⌉ jsi žádal od Hospodina, svého Boha, na Chorébu v den shromáždění: ⌈Ne chci již slyšet⌉ hlas Hospodina, svého Boha, a ⌈ne chci už vidět⌉ tento velký oheň, abych nezemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Nato mi Hospodin řekl: ⌈Dobře to pověděli.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Ustanovím jim proroka z jejich bratří, jako jsi ty. Dám svá slova do jeho úst a poví jim všechno, co mu přikáži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'I stane se, že toho, kdo neuposlechne má slova, která promluví v mém jménu, ⌈toho sám povolám k odpovědnosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Ovšem prorok, který by jednal povýšeně a mluvil v mém jménu slovo, které jsem mu promluvit nepřikázal, anebo by mluvil ve jménu jiných bohů, takový prorok zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Možná ⌈si v srdci řekneš:⌉ Jak poznáme slovo, které Hospodin nepromluvil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'To, co promluví prorok v Hospodinově jménu, a nestane se to, jestliže se to slovo nenaplní, nepromluvil to Hospodin. Ten prorok to řekl v domýšlivosti; neměj z něj strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Až Hospodin, tvůj Bůh, vyhladí národy, jejichž zemi ti Hospodin, tvůj Bůh, dává, obsadíš je a usídlíš se v jejich městech a v jejich domech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'odděl si tři města v zemi, kterou ti Hospodin, tvůj Bůh, dává, abys ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, '⌈Připrav si cestu⌉ a na tři části rozděl území své země, kterou ti Hospodin, tvůj Bůh, dá do dědictví, aby tam mohl utéct každý vrah.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Toto je případ vraha, který tam může utéct a zůstane naživu: Ten, kdo zabije svého bližního neúmyslně, aniž by jej byl dříve předtím nenáviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Někdo například vejde se svým bližním do lesa těžit dřevo. Jak se jeho ruka rozmáchne sekerou, aby kácel strom, železo se vysmekne z násady, zasáhne jeho bližního, takže zemře -- ten může utéct do jednoho z těchto měst a zůstane naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Jinak bude krevní mstitel vraha pronásledovat, neboť je jeho srdce rozpálené, dostihne ho, protože cesta je dlouhá, zabije ho, i když mu ne náleží ⌈rozsudek smrti,⌉ jelikož ho dříve předtím neměl v nenávisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Proto ti přikazuji: Odděl si tři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Jestliže Hospodin, tvůj Bůh, rozšíří tvé území, jak přísahal tvým otcům, a dá ti celou zemi, o níž řekl, že ji dá tvým otcům --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'pokud budeš zachovávat každý tento příkaz a plnit to, co ti dnes přikazuji, totiž abys miloval Hospodina, svého Boha, a chodil po jeho cestách po všechny dny -- pak přidej k těmto třem ještě tři další města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Ať není prolita nevinná krev ve tvé zemi, kterou ti Hospodin, tvůj Bůh, dává do dědictví. Spočinula by na tobě prolitá krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Jestliže se však stane, že někdo, kdo nenávidí svého bližního, na něj nastraží léčku, povstane proti němu, ubije ho, takže zemře, a pak uteče do jednoho z těchto měst,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'starší jeho města pro něj pošlou, nechají ho odtamtud přivést, vydají ho do ruky krevního mstitele a zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Ať se nad ním tvé oko neslituje. Tak vyhlaď z Izraele krev nevinného a bude ti dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Neposouvej mezník svého bližního, který postavili předkové ve tvém dědictví, jež zdědíš v zemi, kterou ti Hospodin, tvůj Bůh, dává, abys ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ať nepovstane proti nikomu jediný svědek kvůli žádnému provinění a pro žádný hřích, kvůli jakémukoliv hříchu, kterým zhřeší. Případ ať je potvrzen podle svědectví dvou nebo tří svědků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Jestliže povstane proti někomu zlovolný svědek, aby ⌈ho obvinil ze vzpoury,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'ať se ti dva muži, kteří mají spor, postaví před Hospodina, před kněze a soudce, kteří jsou v oněch dnech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'nechť to soudcové dobře vyšetří a jestliže je ten svědek falešným svědkem, falešně vypovídal proti svému bratru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'proveďte mu to, co zamýšlel provést svému bratrovi. Tak vyhlaď zlo ze svého středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Když o tom ostatní uslyší, budou se bát a takové zlo již více ve tvém středu páchat nebudou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Ať se tvé oko neslituje: Život za život, oko za oko, zub za zub, ruku za ruku, nohu za nohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Když vytáhneš do boje proti svému nepříteli a uvidíš koně a vozbu, lid početnější, než jsi ty, neboj se jich, neboť s tebou je Hospodin, tvůj Bůh, který tě ⌈vyvedl z egyptské země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'I stane se, když se přiblížíte k boji, že přistoupí kněz, promluví k lidu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'a řekne jim: Slyš Izraeli! Blížíte se dnes do boje proti svým nepřátelům. Vaše srdce ať neochabne! Nebojte se, ⌈nepodléhejte panice⌉ a nemějte z nich strach,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'protože Hospodin, váš Bůh, jde s vámi, aby bojoval za vás proti vašim nepřátelům a ⌈zachránil vás.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Potom nechť správcové promluví k lidu takto: ⌈Postavil někdo⌉ nový dům, ale nezasvětil ho? Ať jde a vrátí se domů, jinak by mohl zemřít v boji a zasvětil by ho někdo jiný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Vysadil někdo vinici, ale neužíval ji? Ať jde a vrátí se domů, jinak by mohl zemřít v boji a užíval by ji někdo jiný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Zasnoubil se někdo s ženou, ale nevzal si ji? Ať jde a vrátí se domů, jinak by mohl zemřít v boji a vzal by si ji někdo jiný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Nechť správcové dále promluví k lidu a řeknou: Bojí se někdo a ⌈má slabé srdce?⌉ Ať jde a vrátí se domů, aby ⌈neoslabil srdce svých bratří tak, jako je jeho srdce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Až správcové domluví k lidu, ustanoví do čela lidu velitele armády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Když se přiblížíš k nějakému městu, abys proti němu bojoval, ⌈vyzvi ho k míru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'I stane se, jestliže ti odpoví mírem a otevře ti, potom všechen lid, který v něm bude, ti bude vydán na nucené práce a bude ti sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Jestliže s tebou neuzavře mír, ale pustí se s tebou do boje, oblehni ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Až jej Hospodin, tvůj Bůh, vydá do tvé ruky, pobij všechny, kdo jsou v něm mužského pohlaví, ostřím meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Pouze ženy, malé děti, dobytek a všechno, co bude ve městě, celou kořist z něj zaber pro sebe. Jez z kořisti svých nepřátel, které ti Hospodin, tvůj Bůh, vydal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tak jednej se všemi městy, jež jsou od tebe velmi vzdálená, která ⌈nepatří k městům⌉ těchto národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Pouze ⌈ve městech⌉ těchto národů, které ti Hospodin, tvůj Bůh, dává do dědictví, nenech při životě ⌈nic, co má dech.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Zcela zasvěť zkáze Chetejce a Emorejce, Kenaance a Perizejce, Chivejce a Jebúsejce, tak jak ti přikázal Hospodin, tvůj Bůh,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'aby vás neučili dělat všechny své ohavnosti, které dělali kvůli svým bohům, takže byste zhřešili proti Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Když bys obléhal město po mnoho dní, abys proti němu bojoval a zmocnil se ho, nenič jeho stromy a ne rozháněj se proti nim sekerou; jez z nich, ale nevytínej je. Cožpak je polní strom člověkem, ⌈abys ho obléhal?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Pouze stromy, o kterých víš, že nejsou ovocné stromy, ty můžeš zničit, pokácet a postavit si obležení kolem města, které se s tebou pustilo do boje, dokud ne padne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Jestliže se v zemi, kterou ti Hospodin, tvůj Bůh, dává, abys ji obsadil, najde zabitý, ležící na poli, a neví se, kdo ho zabil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'ať vyjdou tvoji starší a soudcové a odměří vzdálenost do měst, která jsou v okolí zabitého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Když se zjistí město, které je nejblíže k zabitému, vezmou starší toho města jalovici, s níž se ještě nepracovalo, která netáhla ve jhu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Starší toho města přivedou jalovici dolů ke stále proudícímu potoku, kde se nepracovalo ani neselo, a tam u potoka zlomí jalovici vaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Nato přistoupí kněží, synové Léviho, protože je Hospodin, tvůj Bůh, vyvolil, aby mu sloužili a aby žehnali v Hospodinově jménu, a ⌈podle jejich příkazu⌉ se bude řešit každý spor a každé ublížení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Pak si všichni starší toho města, ⌈které je⌉ nejblíže k zabitému, nad jalovicí, jíž byl u potoka zlomen vaz, umyjí ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Promluví a řeknou: Naše ruce neprolily tuto krev a naše oči nic neviděly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, '⌈Daruj smíření⌉ svému lidu Izraeli, který jsi vykoupil, Hospodine, a ⌈nepřičítej svému⌉ lidu Izraeli nevinnou krev. A budou usmířeni za krveprolití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Takto vyhladíš nevinnou krev ze svého středu, neboť uděláš to, co je správné v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Když vytáhneš do boje proti svým nepřátelům a Hospodin, tvůj Bůh, je vydá do tvé ruky, zajmeš zajatce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'a pak uvidíš mezi zajatci ženu krásného vzezření, zatoužíš po ní a budeš si ji chtít vzít za ženu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'přiveď ji do svého domu, ať si ostříhá hlavu, ořeže nehty');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'a sejme ze sebe svůj zajatecký oděv. Ať zůstane ve tvém domě a po dobu jednoho měsíce pláče nad svým otcem a svou matkou. Potom k ní můžeš vejít, budeš jejím manželem a ona ⌈se stane tvou ženou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'I stane se, jestliže ⌈v ní již nebudeš mít zalíbení,⌉ že ji propustíš podle jejího přání. Nesmíš ji však prodat za stříbro. Ne smíš s ní zacházet krutě, protožes ji ponížil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Jestliže bude mít muž dvě ženy, jednu milovanou a druhou nenáviděnou, a milovaná i nenáviděná mu porodí syny, ale prvorozeným bude syn nenáviděné,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'i stane se v den, kdy bude svým synům dávat do dědictví to, co mu patří, že nesmí ⌈jednat jako s prvorozeným⌉ se synem milované oproti synu nenáviděné, který je prvorozený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Ale za prvorozeného uzná syna nenáviděné a dá mu dva díly ze všeho, co má, neboť on je prvotina jeho síly, jemu patří právo prvorozeného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Jestliže bude mít někdo umíněného a vzpurného syna, který neposlouchá svého otce a svou matku, a přestože ho kárají, je neposlouchá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'ať ho jeho otec a matka uchopí a vyvedou ho ke starším jeho města, do brány jeho místa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'a řeknou starším jeho města: Tento náš syn je umíněný a vzpurný, neposlouchá nás. Je to žrout a pijan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Všichni muži jeho města nechť na něj házejí kamení, aby zemřel. Tak vyhlaď zlo ze svého středu. Všichni Izraelci o tom ⌈uslyší a budou se bát.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Jestliže ⌈někdo spáchá⌉ hřích, za který je hoden rozsudku smrti, ať je usmrcen; pověs ho na strom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Nenech jeho mrtvolu na stromě přes noc, ale jistě ho pohřbi v ten den, neboť na pověšeném je Boží kletba. Neznečisti svou zemi, kterou ti Hospodin, tvůj Bůh, dává do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '⌈Když uvidíš býka svého bratra či jeho ovci, jak se zaběhly, nebuď lhostejný vůči nim,⌉ ale určitě je přiveď nazpět svému bratru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Jestliže tvůj bratr ne žije blízko tebe nebo jej neznáš, vezmi je do svého domu. Ať jsou u tebe, dokud je tvůj bratr nevyhledá. Pak mu je vrať.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tak to udělej s jeho oslem, tak to udělej s jeho oděvem, tak to udělej s každou ztracenou věcí svého bratra, která se mu ztratí a nalezneš ji. Nesmíš být lhostejný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, '⌈Když uvidíš osla svého bratra či jeho býka, jak padli na cestě, nebuď lhostejný⌉ vůči nim, ale spolu s ním jim určitě pomoz vstát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Ať není oblečení muže na ženě a muž nechť neobléká oděv ženy, protože každý, kdo dělá takové věci, je ohavností pro Hospodina, tvého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Když se před tebou po cestě, na nějakém stromě či na zemi naskytne ptačí hnízdo s mláďaty nebo vejci a matka bude sedět na mláďatech nebo na vejcích, neber matku s mláďaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Matku jistě propusť a vezmi si jen mláďata, aby se ti dobře vedlo a dožil ses mnoha dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Když si postavíš nový dům, udělej na střeše zábradlí, abys neuvedl na svůj dům vinu za prolitou krev, když by z něho někdo spadl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Neosévej svou vinici dvojím druhem semene, jinak plný výnos semene, které jsi zasel, i úroda vinice propadne svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Neorej s býkem a oslem společně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Neoblékej si oděv vyrobený z míšených vláken, vlny a lnu zároveň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Udělej si střapce na čtyřech cípech svého oděvu, kterým se přikrýváš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Jestliže si muž vezme ženu, vejde k ní, a pak ji začne nenávidět,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, '⌈vznese proti ní křivé obvinění,⌉ ⌈způsobí jí špatnou pověst⌉ a řekne: Vzal jsem si tuto ženu a když jsem se k ní přiblížil, ⌈nenašel jsem u ní známky panenství,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'potom otec dívky a její matka vezmou a přinesou důkazy panenství té dívky do brány ke starším města');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'a otec dívky řekne starším: Dal jsem svou dceru tomuto muži za ženu a on ji začal nenávidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Hle, vznesl křivé obvinění se slovy: Nenašel jsem u tvé dcery známky panenství. Zde je důkaz panenství mé dcery. A rozprostřou před staršími města roucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Nato ať starší onoho města vezmou muže a pokárají ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, '⌈Budou ho pokutovat sto stříbrnými⌉ a dají je otci dívky, protože ten muž způsobil izraelské panně zlou pověst. Zůstane jeho ženou, po celý svůj život ji nesmí propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Jestliže se však to obvinění ukázalo jako pravdivé a nenašel se důkaz panenství dívky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'pak ať vyvedou dívku ke vchodu do domu jejího otce, muži jejího města ji ukamenují a zemře, protože spáchala hanebnost v Izraeli, když smilnila v domě svého otce. Tak vyhlaď zlo ze svého středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Když bude muž dopaden, jak spí s provdanou ženou, ať oba zemřou -- muž, který spal s ženou, i ta žena. Tak ⌈vyhlaď zlo z Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Jestliže bude dívka, panna zasnoubena muži a potká ji ve městě muž a bude s ní spát,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'vyveďte oba do brány onoho města, ukamenujte je, ať zemřou; dívka proto, že ve městě nekřičela, a muž proto, že znásilnil ženu svého bližního. Tak vyhlaď zlo ze svého středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Jestliže však potká muž zasnoubenou dívku na poli, ten muž se jí zmocní a bude s ní spát, ať zemře jenom ten muž, který s ní spal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Dívce ale nic nedělej. Dívce nenáleží trest smrti, protože to je případ, jako když někdo povstane proti svému bližnímu a zavraždí ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Protože ji potkal na poli, zasnoubená dívka křičela, ale nebyl, kdo by ji zachránil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Jestliže potká muž dívku, pannu, která není zasnoubená, zmocní se jí, bude s ní spát a budou dopadeni,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'ten muž, který s ní spal, dá otci dívky padesát stříbrných. Stane se jeho ženou za to, že ji znásilnil, a nesmí ji po celý svůj život propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Ať si nikdo nevezme ženu svého otce a ⌈neodhalí cíp roucha svého otce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Ať nevejde do ⌈Hospodinova shromáždění⌉ ⌈ten, kdo má rozdrcená varlata ⌉ či odříznutý ⌈mužský úd.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ať nevejde do Hospodinova shromáždění potomek ze smilstva, ani jeho desáté pokolení ať nevejde do Hospodinova shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Ať nevejde do Hospodinova shromáždění ⌈Amónec ani Moábec,⌉ ani jejich desáté pokolení nikdy nevejde do Hospodinova shromáždění,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'protože vám nevyšli vstříc s chlebem a vodou po cestě, když jste vyšli z Egypta, a najali proti tobě Bileáma, syna Beórova, z Petóru v Aramském Dvojříčí, aby tě proklel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Hospodin, tvůj Bůh, však nechtěl Bileáma poslouchat a Hospodin, tvůj Bůh, ti změnil kletbu v požehnání, protože si tě Hospodin, tvůj Bůh, zamiloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Neusiluj nikdy o ⌈jejich pokoj a dobro⌉ po ⌈všechny své dny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Neopovrhuj Edómcem, protože je to tvůj bratr. Neopovrhuj Egypťanem, protože jsi byl příchozím v jeho zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Synové, kteří se jim narodí, jejich třetí pokolení, mohou vejít do Hospodinova shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Když vytáhneš s vojskem proti svým nepřátelům, měj se na pozoru před ⌈každou špatností.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Jestliže bude ⌈mezi vámi⌉ muž, který bude nečistý kvůli noční příhodě, ať odejde ven z tábora. Nesmí hned vejít do tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, '⌈Když se bude schylovat k večeru, umyje se⌉ vodou a po západu slunce smí vejít do tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Venku za táborem měj vyhrazené místo a tam odcházej konat potřebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Ve svém nářadí měj kolík. Když si venku dřepneš, vyhrab s ním jamku a zase svou nečistotu zakryj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Vždyť Hospodin, tvůj Bůh, se prochází uprostřed tvého tábora, aby tě vysvobodil a dal ti tvé nepřátele. Proto ať je tvůj tábor svatý. Ať u tebe nevidí nic hanebného, aby se od tebe ne odvrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Nevydávej otroka jeho pánu, když se chce u tebe ⌈před svým pánem zachránit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Ať zůstane ⌈u tebe,⌉ ve tvém středu, na místě, které si vybere, v některé ze tvých bran, jež se mu líbí. Neutiskuj ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Ať žádná z dcer Izraele není chrámovou nevěstkou ani žádný ze synů Izraele chrámovým smilníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Nenos do domu Hospodina, svého Boha, mzdu prostitutky ani úhradu psa jako naplnění jakéhokoliv slibu, neboť obojí je ohavností pro Hospodina, tvého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Neber úrok od svého bratra, úrok z peněz, úrok z jídla, úrok z jakékoliv věci, která se půjčuje na úrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Od cizince můžeš brát úrok, ale od svého bratra úrok neber, aby ti Hospodin, tvůj Bůh, požehnal při všem podnikání tvých rukou v zemi, do které jdeš, abys ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Když učiníš slib Hospodinu, svému Bohu, neváhej ho splnit, neboť Hospodin, tvůj Bůh, ho od tebe jistě vyžádá a byl by na tobě hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Jestliže se však vyhneš slibování, nebude na tobě hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Zachovej, co vyšlo ze tvých rtů, a splň, co jsi dobrovolně slíbil Hospodinu, svému Bohu, co jsi prohlásil svými ústy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Když vejdeš do vinice svého bližního, jez hrozny podle svého přání do sytosti. Nedávej je však do své nádoby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 26, 'Když vejdeš do nepožatého obilí svého bližního, trhej klasy rukou, nerozháněj se však na nepožaté obilí svého bližního srpem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Jestliže si muž vezme ženu, bude jejím manželem, ale pak se stane, že nenalezne milost v jeho očích, protože u ní našel nějakou hanebnost, napíše jí rozlukový lístek, dá jí ho a propustí ji ze svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Odejde z jeho domu, půjde a bude patřit jinému muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Když ji ten poslední muž začne nenávidět, napíše jí rozlukový lístek, dá jí ho a propustí ji ze svého domu, anebo jestliže ten poslední muž, který si ji vzal za ženu, zemře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'její první manžel, který ji propustil, si ji nesmí znovu vzít, aby byla jeho ženou, poté, co byla poskvrněna. Byla by to ohavnost před Hospodinem. Neuvaluj hřích na zemi, kterou ti Hospodin, tvůj Bůh, dává do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Jestliže ⌈se muž nově ožení,⌉ ať netáhne s armádou a ⌈není mu vůbec nic uloženo.⌉ Na jeden rok ať je volný pro svůj dům a ⌈dělá radost své ženě,⌉ kterou si vzal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Nikdo ať nebere do zástavy ruční mlýnek ani vrchní mlýnský kámen, neboť by vzal do zástavy život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Jestliže bude někdo dopaden, že ukradl někoho ze svých bratří, ze synů Izraele, krutě s ním zacházel nebo ho prodal, takový zloděj ať zemře. Tak vyhlaď zlo ze svého středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Při ráně malomocenství se měj na pozoru, abys pečlivě zachovával a plnil všechno, co vás budou lévijští kněží učit. Jak jsem jim přikázal, tak to zachovávejte a plňte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Pamatuj na to, co Hospodin, tvůj Bůh, učinil Mirjamě po cestě, když jste vyšli z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Když půjčuješ svému bližnímu na dluh, nevcházej do jeho domu, abys vzal zástavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Stůj venku a muž, kterému půjčuješ, ať ti přinese zástavu ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Ale jestliže je to chudý člověk, ne choď spát s jeho zástavou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Jistě mu zástavu po západu slunce vrať, aby ulehl ve svém plášti a žehnal ti. A ⌈tobě to bude před Hospodinem, tvým Bohem, počteno za spravedlnost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Neutlačuj najatého dělníka, ⌈chudého a nuzného⌉ ze svých bratří ani příchozího, který je ve tvé zemi, ve tvých branách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'V týž den mu dej jeho mzdu, ať nad ní nezapadne slunce, protože je chudý a ⌈pozvedá k ní svou duši.⌉ Ať nevolá proti tobě k Hospodinu a ne dopadne na tebe trest za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Ať nejsou usmrceni otcové za syny a synové ať nejsou usmrceni za otce. Každý ať je usmrcen za svůj hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Nepřevracej právo příchozího a sirotka, neber do zástavy oděv vdovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Pamatuj, že jsi byl otrokem v Egyptě a Hospodin, tvůj Bůh, tě odtamtud vykoupil. Proto ti přikazuji, abys toto plnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Když budeš sklízet svou žeň na poli a zapomeneš na poli snop, nevracej se, abys ho vzal. Bude patřit příchozímu, sirotkovi a vdově, aby ti Hospodin, tvůj Bůh, požehnal při všem díle tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Když budeš srážet svou olivu, ⌈neprohlížej po sobě větve.⌉ To bude patřit příchozímu, sirotkovi a vdově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Když budeš sbírat víno ze své vinice, nepaběrkuj po sobě. To bude patřit příchozímu, sirotkovi a vdově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Pamatuj, že jsi byl otrokem v egyptské zemi. Proto ti přikazuji, abys plnil toto slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Když nastane spor mezi muži, přistoupí k soudu a soudci jim zjednají právo, ať spravedlivého prohlásí za spravedlivého a ničemu prohlásí vinným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'I stane se, jestliže ⌈si ničema zaslouží rány,⌉ soudce ho nechá lehnout a bude před ním bit podle své ničemnosti ⌈ patřičným počtem ran.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, '⌈ Může dostat čtyřicet ran,⌉ ne více; ať ⌈nedostane více ran než⌉ tyto, příliš mnoho ran, jinak by byl tvůj bratr ve tvých očích zlehčen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Nedávej náhubek býku, když mlátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Když budou bratři bydlet pospolu, jeden z nich zemře a nemá syna, ať se žena zemřelého nevdá mimo rodinu, za cizího muže. Ať k ní vejde její švagr, vezme si ji za ženu a splní vůči ní švagrovskou povinnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'I stane se, že prvorozený, kterého porodí, ⌈dá povstat jménu⌉ jeho zemřelého bratra, aby nebylo vymazáno jeho jméno z Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Jestliže si ten muž nebude chtít vzít svou švagrovou, ať vystoupí jeho švagrová do brány ke starším a řekne: Můj švagr odmítá dát povstat jménu svého bratra v Izraeli, nechce vůči mně splnit švagrovskou povinnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Starší jeho města ho zavolají a promluví s ním. Jestliže si bude stát na svém a řekne: Nechci si ji vzít,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'ať k němu jeho švagrová před očima starších přistoupí, zuje sandál z jeho nohy, plivne mu do tváře a poví: Takto se jedná s mužem, který ne chce vystavět dům svého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Bude se v Izraeli nazývat: Dům vyzutého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Jestliže se budou spolu muži rvát ⌈jeden s druhým⌉ a přistoupí žena jednoho z nich, aby vysvobodila svého muže z ruky toho, kdo ho bije, vztáhne ruku a uchopí ho za ohanbí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'usekni jí ruku; ať se tvé oko neslituje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Neměj ve svém měšci ⌈dvojí závaží,⌉ velké a malé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Neměj doma ⌈dvě míry,⌉ velkou a malou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Měj závaží správné a spravedlivé, měj míru správnou a spravedlivou, aby se prodloužily tvé dny v zemi, kterou ti Hospodin, tvůj Bůh, dává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Neboť pro Hospodina, tvého Boha, je ohavností každý, kdo dělá takové věci, každý, kdo páchá špatnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Pamatuj na to, co ti po cestě, když jste vyšli z Egypta, udělal Amálek:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Jak tě cestou potkal a zničil tvůj zadní voj, všechny ⌈slabé opozdilce⌉ za tebou. Ty jsi byl vyčerpaný a unavený, ale on se nebál Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Proto až ti Hospodin, tvůj Bůh, dopřeje odpočinutí od všech tvých okolních nepřátel v zemi, kterou ti Hospodin, tvůj Bůh, dává do dědictví, abys ji obsadil, vymaž Amálekovu památku zpod nebes. Nezapomeň!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Až přijdeš do země, kterou ti Hospodin, tvůj Bůh, dává do dědictví, obsadíš ji a usídlíš se v ní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'vezmi z prvotin všech plodů země, které sklidíš ze své země, kterou ti Hospodin, tvůj Bůh, dává. Vlož to do koše a jdi na místo, které Hospodin, tvůj Bůh, vyvolí, aby tam přebývalo jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Jdi ke knězi, který bude v těch dnech, a řekni mu: Dosvědčuji dnes před Hospodinem, tvým Bohem, že jsem vešel do země, o které Hospodin přísahal našim otcům, že nám ji dá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Kněz ať od tebe vezme koš a položí ho před oltář Hospodina, tvého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Vypovídej před Hospodinem, svým Bohem: Můj otec byl kočovným Aramejcem. Sestoupil do Egypta a pobýval tam ⌈jako malá hrstka.⌉ Stal se tam však velkým, mocným a početným národem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Egypťané s námi jednali zle, pokořovali nás a vkládali na nás tvrdou otročinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Když jsme křičeli k Hospodinu, ⌈Bohu našich otců,⌉ Hospodin slyšel náš hlas a pohlédl na naše soužení, naše trápení a na náš útlak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Hospodin nás vyvedl z Egypta mocnou rukou a vztaženou paží, s velkými, bázeň vzbuzujícími činy, se znameními a divy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Přivedl nás na toto místo a dal nám tuto zemi, zemi oplývající mlékem a medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'A nyní hle, přinesl jsem prvotinu plodů země, kterou jsi mi dal, Hospodine. Polož to před Hospodina, svého Boha, klaň se před Hospodinem, svým Bohem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'a raduj se ze všeho dobrého, co Hospodin, tvůj Bůh, dal tobě a tvému domu -- ty, lévita i příchozí, který je ve tvém středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Až v třetím roce, roce desátku, dokončíš odvádění celého desátku ze své úrody a dáš to lévitovi, příchozímu, sirotkovi a vdově, aby jedli ve tvých branách a nasytili se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'řekni před Hospodinem, svým Bohem: Vyklidil jsem z domu to, co bylo svaté, a dal jsem to lévitovi, příchozímu, sirotkovi a vdově, zcela podle tvého příkazu, který jsi mi dal. Nepřestoupil jsem tvé příkazy a nezapomněl na ně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Nejedl jsem z toho v čas smutku, nevyklidil jsem z toho nic, když jsem byl nečistý a nedal jsem z toho nic mrtvému. Uposlechl jsem Hospodina, svého Boha, a učinil jsem všechno, co jsi mi přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Shlédni ze svého svatého příbytku, z nebes, a požehnej svému lidu Izraeli i zemi, kterou jsi nám dal, jak jsi přísahal našim otcům, zemi oplývající mlékem a medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Dnes ti Hospodin, tvůj Bůh, přikazuje, abys plnil tato ustanovení a nařízení. Zachovávej a plň je celým svým srdcem a celou svou duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Dnes jsi vyhlásil o Hospodinu, že bude tvým Bohem a že budeš chodit po jeho cestách, zachovávat jeho ustanovení, příkazy a nařízení a že ho budeš poslouchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'A Hospodin ti dnes vyhlásil, že budeš jeho lidem, jeho vlastnictvím, jak ti řekl, když budeš zachovávat všechny jeho příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'A vyvýší tě nad všechny národy, které učinil, ke své chvále, věhlasu a slávě, abys byl svatým lidem Hospodinu, svému Bohu, jak řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Mojžíš s izraelskými staršími lidu přikázal: Zachovávejte každý příkaz, který vám dnes přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'V den, kdy projdete Jordánem do země, kterou ti Hospodin, tvůj Bůh, dává, postav si velké kameny a nabíli je vápnem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Až projdeš, napiš na ně všechna slova tohoto zákona, abys vešel do země, kterou ti Hospodin, tvůj Bůh, dává, do země oplývající mlékem a medem, jak ti řekl Hospodin, Bůh tvých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Až projdete Jordánem, postavte tyto kameny, o kterých vám dnes dávám příkaz, na hoře Ébalu a nabíli je vápnem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Postav tam oltář Hospodinu, svému Bohu, oltář z kamenů. ⌈Neopracovávej je železným nástrojem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Postav oltář Hospodina, svého Boha, z neporušených kamenů a přines na něm zápalné oběti Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Obětuj také pokojné oběti, jez je tam a raduj se před Hospodinem, svým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Napiš na ty kameny všechna slova tohoto zákona jasně a správně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Mojžíš s lévijskými kněžími promluvil k celému Izraeli: Zmlkni a slyš, Izraeli! Stal ses dnes lidem Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Uposlechni Hospodina, svého Boha, a plň jeho příkazy a ustanovení, která ti dnes přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'V onen den Mojžíš přikázal lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Až projdete Jordánem, tito ať se postaví na hoře Gerizímu a žehnají lidu: Šimeón, Lévi, Juda, Isachar, Josef a Benjamín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'A tito ať se postaví na hoře Ébalu k proklínání: Rúben, Gád, Ašer, Zabulón, Dan a Neftalí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Lévité ať promluví a zvýšeným hlasem řeknou všem izraelským mužům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Proklet buď muž, který si učiní tesanou či litou modlu, ohavnost pro Hospodina, dílo řemeslníkových rukou, a tajně si ji uloží. A všechen lid ať odpoví: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Proklet buď ten, kdo znevažuje svého otce a svou matku. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Proklet buď ten, kdo posouvá mezník svého bližního. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Proklet buď ten, kdo zavádí slepého ⌈z cesty.⌉ A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Proklet buď ten, kdo převrací právo příchozího, sirotka a vdovy. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Proklet buď ten, kdo spí s ženou svého otce, neboť odhalil cíp roucha svého otce. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Proklet buď ten, kdo obcuje s jakýmkoliv zvířetem. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Proklet buď ten, kdo spí se svou sestrou, dcerou svého otce či své matky. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Proklet buď ten, kdo spí se svou tchýní. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Proklet buď ten, kdo tajně ubije svého bližního. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Proklet buď ten, kdo vezme úplatek, aby zabil ⌈člověka a prolil nevinnou krev.⌉ A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Proklet buď ten, kdo nenaplní slova tohoto zákona a ne splní je. A všechen lid ať řekne: Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'I stane se, jestliže opravdu uposlechneš Hospodina, svého Boha, a budeš zachovávat a plnit všechny jeho příkazy, které ti dnes přikazuji, Hospodin, tvůj Bůh, tě vyvýší nad všechny národy země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, '⌈Přijdou na tebe⌉ všechna tato požehnání, dostihnou tě, jestliže uposlechneš Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Požehnaný budeš ve městě, požehnaný budeš na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Požehnaný bude plod tvého lůna, plod tvé země, plod tvé zvěře, vrh tvého dobytka i přírůstek tvého stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Požehnaný bude tvůj koš i tvá díže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Požehnaný budeš, když budeš ⌈vcházet a požehnaný budeš, když budeš vycházet.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Hospodin dá, že tvoji nepřátelé, kteří povstanou proti tobě, budou od tebe poraženi. Jednou cestou proti tobě vytáhnou, ale sedmi cestami budou před tebou utíkat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Hospodin přikáže, aby s tebou bylo požehnání ve tvých sýpkách a při všem podnikání tvých rukou. Požehná ti v zemi, kterou ti Hospodin, tvůj Bůh, dává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Hospodin si tě ustanoví za svatý lid, jak ti přísahal, když budeš zachovávat příkazy Hospodina, svého Boha, a chodit po jeho cestách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Všechny národy země uvidí, žes ⌈byl nazván Hospodinovým jménem⌉ a budou se tě bát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Hospodin ti daruje hojnost dobrého v plodu tvého lůna, v plodu tvé zvěře i v plodu tvé země v zemi, o které Hospodin přísahal tvým otcům, že ti ji dá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Hospodin ti otevře svou hojnou pokladnici, nebesa, aby dal tvé zemi ve svůj čas déšť a požehnal každé dílo tvých rukou. Budeš půjčovat mnohým národům, ale sám si nebudeš půjčovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Hospodin tě učiní ⌈hlavou, a ne ocasem.⌉ Budeš pouze nahoře a nebudeš dole, jestliže budeš poslouchat příkazy Hospodina, svého Boha, které ti dnes přikazuji, abys je zachovával a plnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Neodvracej se od žádného ze slov, která vám dnes přikazuji, napravo ani nalevo, abys šel za jinými bohy a sloužil jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'I stane se, jestliže neuposlechneš Hospodina, svého Boha, abys zachovával a plnil všechny jeho příkazy a ustanovení, která ti dnes přikazuji, že na tebe přijdou všechny tyto kletby a dostihnou tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Prokletý budeš ve městě, prokletý budeš na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Prokletý bude tvůj koš i tvá díže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Prokletý bude plod tvého lůna, plod tvé země, vrh tvého dobytka i přírůstek tvého stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Prokletý budeš, když budeš vcházet, a prokletý budeš, když budeš vycházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Hospodin na tebe pošle kletbu, zmatek a nezdar při všem podnikání tvé ruky, které budeš konat, dokud nebudeš vyhlazen, dokud nevyhyneš rychle kvůli svým zvráceným činům, kterými jsi mě opustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Hospodin tě bude stíhat morem, dokud ⌈tě nevyhubí⌉ ze země, do které jdeš, abys ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Hospodin tě bude bít ⌈úbytěmi, horečkou,⌉ zápalem, horkostí, mečem, ⌈obilnou rzí a snětí;⌉ budou tě pronásledovat, dokud nevyhyneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Nebe, které je nad tvou hlavou, ⌈bude jako z mědi⌉ a země, která je pod tebou, jako ze železa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Hospodin promění déšť pro tvou zemi v prach a z nebe bude na tebe padat hlína, dokud nebudeš vyhlazen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Hospodin dá, že budeš od svých nepřátel poražen. Jednou cestou proti nim vytáhneš, sedmi cestami budeš před nimi utíkat. I staneš se úděsem pro všechna království země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Tvoje mrtvola se stane potravou všeho nebeského ptactva a zemské zvěře a nebude, kdo by je vyplašil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Hospodin tě bude bít egyptskými vředy a nádory, hnisavými ranami a svrabem, ze kterých se nebudeš moci uzdravit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Hospodin tě bude bít šílenstvím, ⌈slepotou a pomateností⌉ mysli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Budeš tápat za poledne jako tápe slepý za tmy, a ⌈nebudeš moci najít cestu.⌉ Budeš stále utlačován a okrádán po všechny dny, a nebude, kdo by ti pomohl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Zasnoubíš se s ženou, a někdo jiný s ⌈ní bude⌉ spát. Postavíš dům, a nebudeš v něm sídlit. Vysadíš vinici, a nebudeš ji užívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Tvůj býk bude poražen před tvýma očima, a nebudeš ho jíst. Bude ti ukraden tvůj osel, a nevrátí se ti. Tvé stádo bude dáno tvým nepřátelům, a nebude, kdo by ti pomohl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tvoji synové a tvé dcery budou dány cizímu lidu, tvé oči se budou na to dívat a celou dobu po nich toužit, a nebude to ⌈ve tvé moci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Plod tvé země a všechen tvůj výtěžek pohltí lid, který neznáš, a po všechny dny budeš jenom utlačován a vydírán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Budeš třeštit z ⌈toho, co tvé oči uvidí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Hospodin tě bude bít na kolenou a na stehnech zlými vředy, ze kterých se nebudeš moci uzdravit, od ⌈paty až k hlavě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Hospodin přivede tebe i krále, jehož nad sebou ustanovíš, k národu, který jsi neznal ty ani tvoji otcové, a budeš tam sloužit jiným bohům, dřevu a kameni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Staneš se hrůzou, pořekadlem a posměškem mezi všemi národy, kam tě Hospodin zažene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Přineseš na pole mnoho semene, ale sklidíš málo, protože to sežerou kobylky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Vysadíš vinice a budeš je obdělávat, ale víno pít nebudeš a hrozny nesklidíš, protože to sežerou červi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Budeš mít olivové háje na celém svém území, ale olejem se nepomažeš, protože olivy opadají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Zplodíš syny a dcery, ale nebudou tvoji, protože půjdou do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Všechny tvé stromy a plody tvé země si podrobí brouci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Příchozí, který je ve tvém středu, bude nad tebe stoupat výš a výš, ale ty budeš klesat níž a níž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Bude ti půjčovat, ale ty mu půjčovat nebudeš. On bude hlavou a ty budeš ocasem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Přijdou na tebe všechny tyto kletby, budou tě pronásledovat a dostihnou tě, dokud nebudeš vyhlazen, protože jsi neuposlechl Hospodina, svého Boha, abys zachovával jeho příkazy a ustanovení, která jsem ti dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Budou při tobě a tvém potomstvu navěky jako znamení a div.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Protože jsi nesloužil Hospodinu, svému Bohu, s radostí a vděčným srdcem v hojnosti všeho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'budeš sloužit svým nepřátelům, které na tebe Hospodin pošle, v hladu a žízni, nahotě a nedostatku všeho. Vloží na tvou šíji železné jho, dokud tě nevyhladí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Hospodin proti tobě přivede národ zdaleka, z konce země, který poletí jako orel, národ, jehož jazyku nerozumíš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'národ surový, který nebere ohled na starce a nad chlapci se neslitovává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Bude jíst plody tvé zvěře a plody tvé země, dokud nebudeš vyhlazen. Neponechá ti obilí, nové víno ani olej, vrh tvého dobytka ani přírůstek tvého stáda, dokud tě nevyhubí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Způsobí ti soužení ve všech tvých branách, dokud nepadnou tvé vysoké a pevné hradby, na které spoléháš v celé své zemi. Způsobí ti soužení ve všech tvých branách, v celé tvé zemi, kterou ti dal Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'V obležení a v úzkosti, kterou ti tvůj nepřítel přivodí, budeš jíst plody svého lůna, maso svých synů a dcer, které ti dal Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Nejvlídnější a nejzhýčkanější muž ⌈u tebe⌉ ⌈bude příliš lakomý⌉ vůči svému bratru i ženě svého klína a zbytku svých synů, které ponechá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'aby dal někomu z nich z masa svých synů, které bude jíst. Nic jiného mu totiž nezůstalo, kvůli obležení a úzkosti, kterou ti přivodí tvůj nepřítel ve všech tvých branách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Nejvlídnější a nejzhýčkanější žena u tebe, která ⌈není zvyklá⌉ kvůli zhýčkanosti a vlídnosti ani dát ⌈svou nohu⌉ na zem, ⌈bude lakomá⌉ vůči muži svého klína, vůči svému synu a své dceři,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'vůči svému plodovému koláči, který vyšel mezi jejíma nohama a vůči svým synům, které porodí, protože je tajně sní kvůli nedostatku všeho v obležení a úzkosti, kterou ti přivodí tvůj nepřítel ve tvých branách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Jestliže nebudeš zachovávat a plnit všechna slova tohoto zákona zapsaná v této knize a bát se tohoto váženého a hrozného jména, bát se Hospodina, svého Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Hospodin způsobí podivuhodné rány tobě i tvému potomstvu, velké a trvalé rány, zlé a trvalé nemoci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Přivede na tebe všechny egyptské choroby, kterých se lekáš a dolehnou na tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Také všechny nemoci a všechny rány, které nejsou zapsány v knize tohoto zákona na tebe Hospodin přivede, dokud nebudeš vyhlazen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Zůstane vás malá hrstka, místo aby vás bylo tolik, jako hvězd na nebi, protože jsi neuposlechl Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'I stane se, že tak jako nad vámi Hospodin jásal, když vám prokazoval dobro a rozmnožoval vás, tak bude nad vámi Hospodin jásat, když vás bude hubit a když vás bude vyhlazovat a budete vyrváni ze země, do které jdeš, abys ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Hospodin tě rozptýlí mezi všechny národy z jednoho konce země až na druhý a budeš tam sloužit jiným bohům, které jsi neznal ty ani tvoji otcové, dřevu a kameni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Mezi těmi národy se neusadíš a nebude tam místo odpočinku pro tvou nohu, ale Hospodin ti tam dá třesoucí se srdce, hasnoucí oči a zoufalou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Tvůj život bude držet na vlásku. Budeš se lekat ⌈v noci i ve dne⌉ a ⌈nebudeš si jistý vlastním životem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Ráno řekneš: ⌈Kéž by tak byl⌉ večer: A večer řekneš: Kéž by tak bylo ráno -- pro strach svého srdce, kterým se budeš bát, a kvůli tomu, co tvé oko uvidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Hospodin tě přivede na lodích zpět do Egypta, cestou, o které jsem ti řekl, že ji již nikdy neuvidíš. Tam se budete nabízet svým nepřátelům na prodej za otroky a otrokyně, a nebude, kdo by vás koupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 69, 'Toto jsou slova smlouvy, kterou Hospodin přikázal Mojžíšovi uzavřít se syny Izraele v moábské zemi, kromě smlouvy, kterou s nimi uzavřel na Chorébu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Mojžíš svolal celý Izrael a řekl jim: Vy jste viděli všechno, co Hospodin před vašima očima učinil v egyptské zemi faraonovi, všem jeho otrokům a celé jeho zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'ty velké zkoušky, které viděly vaše oči, ta velká znamení a divy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Hospodin vám však až dodnes nedal srdce, které chápe, oči, které vidí, a uši, ⌈které slyší.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Vedl jsem vás čtyřicet let pustinou a vaše pláště se na vás neobnosily ani tvoje sandály se na tvé noze neobnosily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Chléb jste nejedli a víno ani pivo jste nepili, abyste poznali, že já Hospodin jsem váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Když jste přišli na toto místo, vytáhl proti nám do boje chešbónský král Síchon a bášanský král Óg, ale pobili jsme je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Zabrali jsme jejich zemi a dali ji do dědictví Rúbenovcům, Gádovcům a polovině kmene Manasesova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Proto zachovávejte slova této smlouvy a plňte je, abyste měli úspěch ve všem, co budete dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Stojíte dnes všichni před Hospodinem, svým Bohem, předáci vašich kmenů, vaši starší, vaši správci, všichni muži Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'vaše malé děti, vaše ženy i tvůj příchozí, který je ve tvém táboře, od dřevorubce až po nosiče vody,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'abys vstoupil do smlouvy Hospodina, svého Boha, i pod jeho prokletí, které s tebou Hospodin, tvůj Bůh, dnes uzavírá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'aby si tě dnes ustanovil za svůj lid a on byl tvým Bohem, jak k tobě promluvil a jak přísahal tvým otcům, Abrahamovi, Izákovi a Jákobovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Ne jenom s vámi samotnými uzavírám tuto smlouvu a toto prokletí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'ale jak s tím, který tu dnes s námi stojí před Hospodinem, naším Bohem, tak i s tím, který tu dnes s námi není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Vždyť víte, jak jsme pobývali v egyptské zemi a jak jsme procházeli mezi národy, kterými jste procházeli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'a viděli jste jejich ohavné modly a jejich bůžky -- dřevo a kámen, stříbro a zlato, které mají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Ať není mezi vámi muž či žena či rodina či kmen, jehož srdce by se dnes odvrátilo od Hospodina, našeho Boha, aby šel sloužit bohům oněch národů. Ať není mezi vámi kořen plodící jed a pelyněk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'I stane se, když někdo takový uslyší slova tohoto prokletí, že si bude blahořečit a řekne: ⌈Bude se mi dařit dobře,⌉ i když budu ⌈žít podle svého umíněného srdce⌉ -- tak zničí ⌈zavlažovanou i vyprahlou zem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Hospodin mu nebude chtít odpustit, ale tehdy vzplane Hospodinův hněv a jeho žárlivost proti tomuto muži, dolehne na něj každé prokletí zapsané v této knize a Hospodin vymaže jeho jméno zpod nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Hospodin ho oddělí ke zlému ode všech kmenů Izraele podle všech prokletí smlouvy zapsané v této knize zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Pak se bude ptát budoucí generace vašich synů, kteří povstanou po vás, i cizinec, který přijde ze vzdálené země a uvidí rány této země a její nemoci, které na ni Hospodin sešle,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'kdy celá země bude spálena sírou a solí, nebude oseta a nebude dávát vzrůst, nebude na ní vzcházet ani žádná zeleň -- jako po vyvrácení Sodomy a Gomory, Admy a Sebójimu, které Hospodin vyvrátil svým hněvem a svou zlobou --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'ano, všechny národy se budou ptát: Proč tohle Hospodin této zemi provedl? Nač tento velký planoucí hněv?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'A bude se odpovídat: Protože opustili smlouvu Hospodina, Boha svých otců, kterou s nimi uzavřel, když je vyvedl z egyptské země;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'šli a sloužili jiným bohům, klaněli se jim, před bohy, které neznali a které jim nepřidělil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Hospodinův hněv vzplál proti této zemi a přivedl na ni každou kletbu zapsanou v této knize.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Hospodin je v hněvu, zlobě a velkém rozhořčení vyrval z jejich země a uvrhl je do jiné země, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Skryté věci patří Hospodinu, našemu Bohu, odhalené pak nám a našim synům až navěky, abychom plnili všechna slova tohoto zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'I stane se, když ⌈na tebe přijdou⌉ všechny tyto věci, požehnání i kletby, které jsem ti předložil, a ⌈připomeneš si je ve svém srdci⌉ mezi všemi národy, kam tě Hospodin, tvůj Bůh, zahnal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'navrátíš se k Hospodinu, svému Bohu, a uposlechneš ho, jak ti dnes přikazuji, ty i tvoji synové, celým svým srdcem a celou svou duší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Hospodin, tvůj Bůh, změní tvůj úděl, slituje se nad tebou a znovu tě shromáždí ze všech národů, kam tě Hospodin, tvůj Bůh, rozptýlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'I kdyby byli tvoji zapuzení na konci nebes, také odtamtud tě Hospodin, tvůj Bůh, shromáždí, i odtamtud tě dovede.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Hospodin, tvůj Bůh, tě přivede do země, kterou obsadili tvoji otcové, a obsadíš ji. Prokáže ti dobro a rozmnoží tě víc než tvé otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Hospodin, tvůj Bůh, obřeže tvé srdce a srdce tvého potomstva, abys miloval Hospodina, svého Boha, celým svým srdcem a celou svou duší a byl živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Hospodin, tvůj Bůh, dá všechna tato prokletí na tvé nepřátele a na ⌈ty, kdo tě nenávidí a pronásledují.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Ty však se navrátíš, uposlechneš Hospodina a budeš plnit všechny jeho příkazy, které ti dnes přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Hospodin, tvůj Bůh, ti daruje hojnost k dobrému při všem díle tvých rukou, v plodu tvého lůna, v plodu tvé zvěře i v plodu tvé země, neboť Hospodin nad tebou bude znovu jásat k dobrému, jako jásal nad tvými otci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'když uposlechneš Hospodina, svého Boha, budeš zachovávat jeho příkazy a ustanovení zapsaná v této knize zákona a navrátíš se k Hospodinu, svému Bohu, celým svým srdcem a celou svou duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Vždyť tento příkaz, který ti dnes přikazuji, není pro tebe nepochopitelný ani vzdálený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Není na nebesích, abys mohl říct: Kdo ⌈z nás⌉ vystoupí na nebesa, aby ⌈jej pro nás vzal,⌉ ⌈oznámil nám ho a my jej plnili?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Ani není za mořem, abys mohl říct: Kdo z nás přejde na druhou stranu moře, aby jej pro nás vzal, oznámil nám ho a my jej plnili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Vždyť to slovo je velmi blízko tebe, ve tvých ústech a ve tvém srdci, abys ho plnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Pohleď, předložil jsem ti dnes život a dobro i smrt a zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'To ti dnes přikazuji, abys miloval Hospodina, svého Boha, chodil po jeho cestách a zachovával jeho příkazy, ustanovení a nařízení. Tak zůstaneš naživu, rozmnožíš se a Hospodin, tvůj Bůh, ti požehná v zemi, do které jdeš, abys ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Jestliže se však tvé srdce odvrátí, nebudeš poslouchat, necháš se svést, budeš se klanět jiným bohům a sloužit jim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'oznamuji vám dnes, že jistě zahynete a nedožijete se mnoha dní v zemi, do které procházíš Jordánem a jdeš, abys ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Povolávám dnes proti vám za svědky nebesa i zemi. Předložil jsem ti život a smrt, požehnání a kletbu. Zvol si život, abys zůstal naživu ty i tvé potomstvo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, '⌈a miluj⌉ Hospodina, svého Boha, jej poslouchej a přilni k němu. Vždyť on je tvůj život a dá ti dlouhá léta, abys bydlel v zemi, o které Hospodin přísahal tvým otcům, Abrahamovi, Izákovi a Jákobovi, že jim ji dá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Mojžíš šel a pověděl tato slova celému Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Řekl jim: Je mi dnes sto dvacet let, nemohu již vycházet a vcházet a Hospodin mi řekl: Nepřejdeš přes tento Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Hospodin, tvůj Bůh, půjde před tebou; on před tebou vyhladí tyto národy a obsadíš je. Jozue půjde před tebou, jak řekl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Hospodin s nimi učiní to, co učinil s emorejskými králi Síchonem a Ógem a s jejich zemí, když je vyhladil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Až vám je Hospodin vydá, naložte s nimi zcela podle příkazu, který jsem vám dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Posilněte se a buďte odvážní. Nebojte se a nemějte z nich strach, neboť Hospodin, tvůj Bůh, půjde s tebou. Nenechá tě klesnout a neopustí tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Potom Mojžíš zavolal Jozua a před očima celého Izraele mu řekl: Posilni se a buď odvážný, neboť ty půjdeš s tímto lidem do země, o které Hospodin přísahal jejich otcům, že jim ji dá. Ty jim ji dáš do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Hospodin půjde před tebou, on ⌈bude s tebou,⌉ nenechá tě klesnout a neopustí tě. Neboj se a neděs se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Mojžíš zapsal tento zákon a dal ho kněžím, synům Léviho, kteří nosí truhlu Hospodinovy smlouvy, a všem izraelským starším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Mojžíš jim přikázal: Po sedmi letech, v určený čas roku prominutí dluhu, při svátku stánků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'když se celý Izrael přijde ukázat před Hospodinem, tvým Bohem, na místě, které vyvolí, čti tento zákon před celým Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Shromáždi lid, muže, ženy, malé děti i příchozího, který je ve tvých branách, aby poslouchali a učili se bát Hospodina, vašeho Boha, a zachovávali a plnili všechna slova tohoto zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Také jejich synové, kteří ho neznají, ať poslouchají a učí se bát Hospodina, vašeho Boha, po všechny dny, co budete naživu v zemi, do které procházíte Jordánem, abyste ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Hospodin dále Mojžíšovi řekl: Hle, ⌈blíží se dny, kdy zemřeš.⌉ Zavolej Jozua, postavte se ve stanu setkávání a ustanovím ho. Mojžíš šel s Jozuem a postavili se ve stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Hospodin se ukázal ve stanu v oblakovém sloupu. Oblakový sloup zůstal stát u vchodu do stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Hospodin Mojžíšovi řekl: Hle, brzy ulehneš ⌈se svými⌉ otci. Tento lid pak povstane a bude chodit smilnit za cizími bohy v zemi, do které jdeš. Opustí mě a zruší mou smlouvu, kterou jsem s nimi uzavřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'V onen den vzplane proti němu můj hněv, opustím je a skryji před nimi svou tvář. Bude k požírání, potkají ho mnohá trápení a soužení. V onen den řekne: ⌈Což to není kvůli tomu,⌉ že můj Bůh není v mém středu, že mě potkala tato trápení?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'V onen den jistě skryji svou tvář kvůli všemu zlu, které spáchal, když se obrátil k jiným bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Nyní ⌈jim napiš⌉ tuto píseň a nauč ji syny Izraele, vlož ji do jejich úst, aby tato píseň byla mým svědkem proti synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Vždyť ho přivedu do země, o které jsem přísahal jeho otcům, do země oplývající mlékem a medem. Ale až se nají, nasytí a bude prospívat, obrátí se k jiným bohům a budou jim sloužit. Mě zneváží a poruší mou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'I stane se, že až ho potkají mnohá trápení a soužení, tato píseň bude před ním svědčit jako svědek, protože ⌈nebude zapomenuta z úst jeho potomstva.⌉ Neboť znám jeho smýšlení, podle kterého už nyní jedná, ještě dříve nežli ho přivedu do země, o které jsem přísahal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Mojžíš napsal v onen den tuto píseň a učil ji syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Pak dal příkaz Jozuovi, synu Núnovu: Posilni se a buď odvážný, neboť ty přivedeš syny Izraele do země, o které jsem jim přísahal. Já ⌈budu s tebou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'I stalo se, když Mojžíš zcela dopsal do knihy slova tohoto zákona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'že přikázal lévitům nosícím truhlu Hospodinovy smlouvy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Vezměte tuto knihu zákona a položte ji po boku truhly smlouvy Hospodina, svého Boha. Bude tam proti tobě jako svědek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Vždyť já znám tvou vzpouru a tvou tvrdou šíji! Jestliže jste se vzpírali vůči Hospodinu nyní, když ještě žiji s vámi, tím spíše po mé smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Shromážděte ke mně všechny starší svých kmenů a své správce, abych ⌈k nim⌉ promluvil tato slova a povolal proti nim za svědky nebesa i zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Neboť vím, že po mé smrti se jistě vrhnete do zkázy, odvrátíte se od cesty, kterou jsem vám přikázal a postihne vás v budoucích dnech zlo, protože budete páchat to, co je zlé v Hospodinových očích, a budete ho provokovat k hněvu dílem svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Mojžíš mluvil k celému shromáždění Izraele slova této písně až do konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Naslouchejte, nebesa, budu mluvit, slyš, země, řeč mých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Jako déšť ať kane má nauka, jak rosa ať plyne má řeč, jako sprška na trávu a jako přeháňka na zeleň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, '⌈Vyhlašuji Hospodinovo jméno.⌉ Vzdejte čest našemu Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Skála -- jeho dílo je bezúhonné, ano, všechny jeho cesty jsou spravedlivé. On je Bůh věrný a není v něm špatnost, je spravedlivý a přímý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, '⌈Jednali vůči němu zvráceně,⌉ ⌈ ke své potupě nejsou jeho syny,⌉ zvrácená a zkažená generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Takto odplácíte Hospodinu, lide bláznivý a nemoudrý? Cožpak není on tvým otcem, který tě vytvořil, který tě učinil a upevnil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Vzpomeň na dávné dny, zvažuj roky ⌈ z generace na generaci.⌉ Zeptej se svého otce, ať ti poví, svých starců, ať ti řeknou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Když dával Nejvyšší národům dědictví, když rozděloval syny člověka, ustanovil hranice národů podle počtu synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Vždyť Hospodinovým podílem je jeho lid, Jákob ⌈jeho dědičným dílem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Nalezl ho v pusté zemi, v pustotě, blouznění pusté krajiny. Obklopil ho, ⌈pečoval o něj,⌉ střežil ho jako zřítelnici svého oka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Jako orel dává do pohybu své hnízdo, vznáší se nad svými mláďaty, roztáhne svá křídla, uchopí je a nese je na svých perutích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Hospodin sám ho vedl, cizí bůh s ním nebyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Nechal ho jet po návrších země, sytil ho polními plodinami, krmil ho medem ze skály a olejem z tvrdého skalního útesu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'kravským máslem a ovčím sýrem, s tukem jehňat, bášanskými berany a kozly, ⌈tím nejlepším z⌉ pšenice, pil jsi krev hroznů -- ⌈šumivé víno.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Ješúrún ztučněl a zpychl -- ztučněl jsi, ztloustl a stal ses nadutým. Opustil Boha, který ho učinil, jednal opovržlivě vůči Skále své záchrany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Dráždili ho k žárlivosti cizími bohy, ohavnostmi ho provokovali ke hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Obětovali démonům, ⌈ kteří nejsou Bohem,⌉ bohům, jež neznali, novým, kteří nedávno přišli, o nichž vaši otcové nic nevěděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Skálu, která tě zplodila, jsi oklamal, zapomněl jsi na Boha, který tě zrodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Hospodin to viděl a ⌈opovrhl jimi kvůli provokaci svých synů a dcer.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Řekl: Skryji před nimi svou tvář, uvidím, jaký bude jejich konec. Vždyť jsou obojakou generací, syny, u nichž není věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Oni mě dráždili k žárlivosti těmi, jež nejsou Bohem, provokovali mě ke hněvu svými nicotnostmi. Také já je budu dráždit k žárlivosti těmi, jež nejsou lidem, skrze bláznivý národ je budu provokovat ke hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Mým hněvem byl zanícen oheň, plane až do nejhlubšího podsvětí a stráví zemi i její úrodu, spálí základy hor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Navrším na ně zlé věci, ⌈skoncuji s nimi svými⌉ šípy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Budou vysíleni hladem, ⌈postiženi morem⌉ a krutou zhoubou; pošlu na ně zuby zvěře spolu s jedem ⌈těch, co se plazí prachem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Venku bude činit bezdětným meč a ⌈v pokojích⌉ hrůza, bude ničit jak mládence tak i pannu, kojence i muže v šedinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Řekl bych: Vyhladím je, odstraním jejich památku ⌈mezi lidmi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Ale obávám se provokace nepřítele, aby si jejich protivníci nemysleli, aby neřekli: Naše ruka se vyvýšila, nic z toho neudělal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Jsou národem, kterému chybí rada, ⌈není v něm rozumnost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Kdyby byli moudří, ⌈pochopili by to,⌉ porozuměli by svému konci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Jak by mohl jeden pronásledovat tisíc a dva zahnat na útěk deset tisíc? ⌈Což to není tak, že⌉ jejich Skála je prodala, Hospodin je vydal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Vždyť jejich skála není jako naše Skála, jak soudí i naši nepřátelé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Vždyť jejich réva je ze sodomské révy, z gomorských polí. Jejich hrozny jsou jedovaté hrozny, mají trpká zrnka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Jejich víno je dračím jedem, krutým jedem kobry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Což to není u mě uchováno, zapečetěno v mých pokladnicích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mně patří pomsta a odplata, v čase, kdy klopýtne jejich noha, neboť den jejich pohromy je blízko, ⌈to, co na ně má přijít,⌉ si pospíší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Vždyť Hospodin ⌈zjedná právo svému lidu⌉ a nad svými otroky pocítí lítost, když uvidí, že odešla jejich moc a ne zůstal ⌈zadržovaný ani propuštěný.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Řekne: Kde jsou jejich bohové, skála, v níž měli útočiště,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'kteří jedli tuk jejich obětí a pili víno jejich úliteb? Ať povstanou a pomohou vám, ať jsou vám úkrytem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Nyní pohleďte, že já, já jsem to, a není Bůh ⌈mimo mě.⌉ Já ⌈nechávám zemřít⌉ a oživuji, zdeptal jsem, já i uzdravím; není, kdo by vysvobodil z mé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Vždyť ⌈pozvedám svou ruku⌉ k nebesům a pravím: Jakože jsem živ navěky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'když nabrousím svůj blýskavý meč a má ruka se chopí práva, odpovím pomstou svým protivníkům a těm, kdo mě nenávidí, odplatím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Opiji své šípy krví, když můj meč bude požírat maso, krví pobitých a zajatců, vlasatých vůdců nepřítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Jásejte, národy, spolu s jeho lidem, neboť krev svých otroků pomstí a pomstou odplatí svým protivníkům, své zemi a svému lidu daruje smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Mojžíš šel a promluvil všechna slova této písně k lidu, on i Jozue, syn Núnův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Když Mojžíš domluvil všechna tato slova k celému Izraeli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'řekl jim: ⌈Vezměte si k srdci všechna slova,⌉ která vám dnes dosvědčuji a přikazujte svým synům, aby zachovávali a plnili všechna slova tohoto zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Vždyť to není pro vás nicotná věc, ale je to váš život; tímto způsobem prodloužíte dny v zemi, do které procházíte Jordánem, abyste ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Právě v ten den ⌈Hospodin promluvil k Mojžíšovi:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Vystup do tohoto pohoří Abarím, na horu Nebó, která je v moábské zemi, naproti Jerichu, a podívej se na kenaanskou zemi, kterou dávám do vlastnictví synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Na hoře, na kterou vystoupíš, zemřeš a budeš připojen ke svému lidu, tak jako zemřel tvůj bratr Áron na hoře Hóru a byl připojen ke svému lidu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'protože jste mi byli nevěrní uprostřed synů Izraele u Vod sváru v Kádeši v pustině Sinu, když jste nedosvědčili moji svatost uprostřed synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Odtud uvidíš tu zemi, ale nevejdeš tam, do té země, kterou dávám synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Toto je požehnání, kterým požehnal Mojžíš, muž Boží, synům Izraele před svou smrtí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Řekl: Hospodin přišel ze Sínaje, zazářil na ně ze Seíru, zaskvěl se z hory Páranu, přišel ⌈s desetitisíci svatých,⌉ z jeho pravice byl pro ně ⌈ohnivý zákon.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Ano, miluješ lidi, všichni jeho svatí jsou ve tvé ruce. ⌈Shromažďují se kolem tvých nohou,⌉ přijímá tvé výroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mojžíš nám dal zákon, jako vlastnictví Jákobova shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Stal se králem v Ješúrúnovi, když se shromáždili předáci lidu, ⌈izraelské kmeny byly pospolu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ať žije Rúben a nezemře, ačkoliv je v malém počtu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, '⌈Toto pověděl o Judovi:⌉ ⌈Slyš, Hospodine,⌉ Judův hlas, přiveď ho k jeho lidu, jeho ruce ⌈povedou za něj při,⌉ buď pomocí proti jeho protivníkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'O Lévim řekl: Tvoje tumím a urím ať jsou s každým tvým věrným, kterého jsi vyzkoušel v Masse, s kterým jsi vedl při u Vod sváru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'který řekl o svém otci a své matce: ⌈Neohlížím se na ně,⌉ ⌈svým bratrům nestranil⌉ a ke svým synům se neznal, ale zachovali tvou řeč a tvou smlouvu střežili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Budou Jákoba vyučovat tvým nařízením, Izrael tvému zákonu; ⌈budou předkládat kadidlo před tvůj nos⌉ a celopal na tvůj oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Požehnej, Hospodine, jeho majetku, kéž si oblíbíš dílo jeho rukou. Zdeptej bedra jeho protivníků i těch, kdo ho nenávidí, takže nepovstanou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'O Benjamínovi řekl: Miláček Hospodinův bude přebývat u něho v bezpečí, každý den ho chrání, přebývá na jeho ramenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'O Josefovi řekl: ⌈Požehnána buď od Hospodina jeho země⌉ vzácnými dary nebes, rosou i hlubinou, co leží dole,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'vzácnými dary výnosů slunce i vzácnými dary ⌈toho, co dávají⌉ měsíce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'nejlepším dávnověkých hor, vzácnými dary věčných návrší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'vzácnými dary země a ⌈vším, co ji naplňuje,⌉ přízní Toho, kdo přebývá v keři. Ať toto přijde na Josefovu hlavu, na temeno nazíra mezi jeho bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, '⌈Jeho důstojnost je jako důstojnost prvorozeného býka,⌉ jeho rohy jsou jako rohy divokého tura; nabere na ně národy, všechny najednou, až do končin země. To jsou desetitisíce Efrajimovy, to jsou tisíce Manasesovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'O Zabulónovi řekl: Raduj se, Zabulóne, při svém vycházení, Isachare, ve svých stanech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Svolají národy na horu, tam budou obětovat spravedlivé oběti, neboť budou sát hojnost moří, poklady skryté v písku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'O Gádovi řekl: Požehnaný je ten, kdo rozšiřuje Gáda. Usídlil se jako lvice, rozsápe paži i hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Vyhlédl si pro sebe ⌈ to nejlepší,⌉ neboť tam byl uchován díl velitele. ⌈Přišel s předáky⌉ lidu, vykonal Hospodinovu spravedlnost a jeho soudy s Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'O Danovi řekl: Dan je lvím mládětem, které vyskočí z Bášanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'O Neftalím řekl: Neftalí, nasycený přízní a plný Hospodinova požehnání, obsaď ⌈moře i jih.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'O Ašerovi řekl: Nejpožehnanější ze synů ať je Ašer. Nechť nalezne zalíbení svých bratrů a noří svou nohu do oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Tvé závory ať jsou železné a bronzové a ⌈tvá síla trvá po všechny tvé dny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Nikdo není jako Bůh, Ješúrúne, který jezdí na nebesích tobě ku pomoci, ve své velebnosti na oblacích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Příbytkem je Bůh dávnověký, pod tebou jsou paže věčné. Vyhnal před tebou nepřítele, řekl: Vyhlaď!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Izrael přebývá v bezpečí, o samotě Jákobův pramen, v zemi obilí a nového vína, ano, jeho nebesa kanou rosu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Jsi blahoslavený, Izraeli, kdo je jako ty, lid zachráněný Hospodinem, ⌈tvým ochranným štítem⌉ a ⌈vítězným mečem.⌉ Tví nepřátelé ti budou podlézat a ty budeš šlapat po jejich návrších.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Mojžíš pak vystoupil z moábských pustin na horu Nebó, na vrchol Pisgy, který je naproti Jerichu, a Hospodin mu ukázal celou zemi: Gileád až po Dan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, '⌈celého Neftalího,⌉ území Efrajima a Manasesa, celé území Judy až k Západnímu moři,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Negeb i Rovinu, jerišskou pláň a Palmové město, až k Sóaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Hospodin mu řekl: Toto je země, o které jsem přísahal Abrahamovi, Izákovi a Jákobovi: Dám ji tvému potomstvu. Ukázal jsem ti ji na vlastní oči, ale nevejdeš tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Mojžíš, otrok Hospodinův, tam v moábské zemi zemřel podle Hospodinova příkazu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Pohřbil ho v údolí v moábské zemi naproti Bét–peóru a nikdo neví o jeho hrobu až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Mojžíšovi bylo sto dvacet let, ⌈když zemřel;⌉ jeho zrak nezeslábl a ⌈síla ho neopustila.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Synové Izraele plakali nad Mojžíšem v moábských pustinách třicet dní. Pak dny pláče a smutku pro Mojžíše skončily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Jozue, syn Núnův, byl plný ducha moudrosti, protože na něj Mojžíš položil své ruce. Synové Izraele ho poslouchali a činili to, co Hospodin Mojžíšovi přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'V Izraeli již nepovstal prorok jako Mojžíš, ⌈který by znal Hospodina⌉ tváří v tvář,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'se všemi těmi znameními a divy, které jej Hospodin poslal učinit v egyptské zemi faraonovi, všem jeho otrokům a celé jeho zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'se vší mocnou rukou a se všemi těmi ⌈velkými, bázeň vzbuzujícími činy,⌉ které Mojžíš učinil před očima celého Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'I stalo se po smrti Mojžíše, otroka Hospodinova, že Hospodin řekl Jozuovi, synu Núnovu, služebníku Mojžíšovu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mojžíš, můj otrok, zemřel. Nyní tedy vstaň, přejdi tento Jordán, ty a všechen tento lid, do země, kterou jim, synům Izraele, dávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Každé místo, na které šlápne vaše chodidlo, jsem vám dal, jak jsem to prohlásil před Mojžíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Od pustiny a tohoto Libanonu až k veliké řece, řece Eufratu, celá ⌈země Chetejců⌉ až k Velikému moři na západ slunce bude vaším územím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nikdo se proti tobě nepostaví po všechny dny tvého života. Jako jsem byl s Mojžíšem, budu i s tebou. Nenechám tě klesnout ani tě neopustím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, '⌈Posilni se a buď odvážný,⌉ protože ty dáš lidu do dědictví tuto zemi, o které jsem přísahal jejich otcům, že jim ji dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Hlavně se posilni a buď velmi odvážný, ⌈abys zachovával a plnil celý zákon,⌉ jak ti přikázal Mojžíš, můj otrok. Neodvrať se od něj napravo ani nalevo, abys ⌈rozumně jednal⌉ všude, kam půjdeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, '⌈Kniha tohoto zákona ať se nevzdálí od tvých úst.⌉ ⌈Budeš nad ním rozjímat ve dne i v noci,⌉ ⌈abys zachovával a konal všechno,⌉ co je v něm zapsáno, protože tehdy ⌈dosáhneš na své cestě úspěchu⌉ a tehdy budeš rozumně jednat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Vždyť jsem ti přikázal: Posilni se a buď odvážný, neměj strach a neděs se, protože Hospodin, tvůj Bůh, bude s tebou ⌈všude, kam⌉ půjdeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Poté Jozue přikázal správcům lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Projděte středem tábora a přikažte lidu: Připravte si zásobu potravin, protože za tři dny budete procházet tímto Jordánem, abyste šli obsadit zemi, kterou vám Hospodin, váš Bůh, dává, abyste ji obsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Rúbenovcům, Gádovcům a polovině kmene Manasesova pak Jozue řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Vzpomeňte si na slovo, které vám přikázal Mojžíš, otrok Hospodinův: Hospodin, váš Bůh, vám dopřává odpočinutí a dá vám tuto zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vaše ženy, vaše malé děti a vaše stáda zůstanou v zemi, kterou vám dal Mojžíš na druhé straně Jordánu, a vy, všichni ⌈udatní hrdinové,⌉ projdete sešikováni před svými bratry a pomůžete jim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'dokud Hospodin ne dá odpočinek vašim bratrům tak jako vám a dokud ne obsadí také oni zemi, kterou jim dává Hospodin, váš Bůh. Potom se navrátíte do země, kterou jste obsadili vy, a obsadíte, co vám Mojžíš, otrok Hospodinův, dal na druhé straně Jordánu na východu slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Nato Jozuovi odpověděli: Vykonáme vše, jak jsi nám přikázal, a do všeho, do čeho nás pošleš, půjdeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Budeme tě poslouchat, ⌈stejně jako⌉ jsme poslouchali Mojžíše; jenom ať je Hospodin, tvůj Bůh, s tebou, tak jako byl s Mojžíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Každý, kdo se bude vzpírat tvým příkazům a neuposlechne tvá slova ve všem, co mu přikážeš, bude usmrcen. Hlavně se posilni a buď odvážný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'I poslal Jozue, syn Núnův, ze Šitímu tajně dva zvědy se slovy: Jděte, prohlédněte si tu zemi i Jericho. Šli tedy, přišli do domu prostitutky jménem Rachab a ulehli tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Tu bylo řečeno králi Jericha: Hle, teď v noci sem přišli muži ze synů Izraele, aby proslídili zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Jerišský král tedy poslal k Rachabě se slovy: Vyveď ty ⌈příchozí, kteří vstoupili do tvého domu,⌉ protože přišli, aby proslídili celou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Ta žena však oba muže vzala a skryla je. Řekla: Ti muži ke mně opravdu přišli, ale nevěděla jsem, odkud jsou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Za tmy, když nastal čas zavřít bránu, ti muži odešli. Nevím, kam šli. Rychle je pronásledujte; však je dostihnete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Ona je pak vyvedla na střechu a ukryla je mezi snopky lnu, které měla na střeše rozprostřené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'A ti muži je pronásledovali jordánskou cestou k brodům. Potom, jakmile za nimi pronásledovatelé vyšli, zavřeli bránu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Oni ještě ani neulehli, a ona k nim vystoupila na střechu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'A řekla těm mužům: Poznala jsem, že vám Hospodin dal zemi, že na nás padla hrůza ⌈ z vás⌉ a že kvůli vám všichni obyvatelé země ⌈propadli malomyslnosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Vždyť jsme slyšeli, jak před vámi Hospodin nechal vyschnout vody Rákosového moře, když jste vycházeli z Egypta, a co jste udělali dvěma emorejským králům, kteří sídlili na druhé straně Jordánu, Síchonovi a Ógovi; jak jste je zasvětili zkáze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Když jsme to slyšeli, naše srdce se rozplynulo a ⌈nikdo už strachem z vás ani nedýchal,⌉ protože Hospodin, váš Bůh, je Bůh nahoře na nebesích i dole na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Nuže, přísahejte mi, prosím, při Hospodinu, že když jsem vám prokázala milosrdenství, prokážete také vy milosrdenství domu mého otce a dáte mi spolehlivé znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'A necháte žít mého otce i matku, mé bratry i sestry a ⌈všechno, co jim⌉ patří, a vysvobodíte naše duše od smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Nato jí ti muži odpověděli: Nechť naše duše zemře namísto vás. Pokud nevyzradíte tuto naši úmluvu ⌈a stane se,⌉ že nám Hospodin dá zemi, prokážeme ti milosrdenství a věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Potom je nechala sestoupit ⌈po provaze⌉ z okna, ⌈protože její dům byl v hradební zdi. Bydlela na hradbách.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'A řekla jim: ⌈Na to pohoří⌉ jděte, ať na vás nenarazí pronásledovatelé. Ukryjete se tam na tři dny, dokud se pronásledovatelé nevrátí, a potom půjdete svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Muži jí řekli: Budeme zproštěni této tvé přísahy, kterou jsi nás zapřisáhla, za této podmínky:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Hle, přicházíme do země. Přivážeš provázek z těchto karmínových šňůr do okna, z něhož jsi nás nechala sestoupit, a shromáždíš svého otce, matku, bratry a celý dům svého otce k sobě do domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, '⌈A krev každého, kdo vyjde ze dveří tvého domu na ulici, spočine na jeho hlavě a my budeme nevinní, ale krev každého, kdo bude s tebou v domě, spočine na naší hlavě,⌉ jestliže na něho dopadne něčí ruka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Jestliže však vyzradíš tuto naši úmluvu, budeme zproštěni tvé přísahy, jíž jsi nás zapřisáhla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Nato řekla: Tak to bude, podle vašich slov. Propustila je a oni šli. Potom přivázala do okna karmínový provázek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Tak šli, až došli na to pohoří a zůstali tam tři dny, dokud se pronásledovatelé ne vrátili. Ačkoliv pronásledovatelé ⌈prohledali celou cestu,⌉ nikoho nenašli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Pak se oba muži vrátili. Sestoupili z pohoří, přebrodili se, přišli k Jozuovi, synu Núnovu, a vyprávěli mu o všem, co je potkalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'A řekli Jozuovi: Hospodin vydal do naší ruky celou zemi a také všichni obyvatelé té země z nás ⌈propadli malomyslnosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Časně ráno pak Jozue vstal. Vyrazili ze Šitímu a přišli až k Jordánu, on a všichni synové Izraele. Tam přenocovali, dříve nežli se měli přebrodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, '⌈Když uplynuly⌉ tři dny, stalo se, že správci prošli středem tábora');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'a přikázali lidu: Jakmile uvidíte truhlu smlouvy Hospodina, svého Boha, a lévijské kněze, kteří ji nesou, i vy vyrazíte ze svého místa a půjdete za ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Avšak mezi tebou a mezi ní bude vzdálenost v míře asi dvou tisíc loket. Nepřibližujte se k ní, abyste tak poznali cestu, po které půjdete, protože po té cestě jste nikdy dříve neprocházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Jozue pak lidu řekl: Posvěťte se, neboť zítra učiní Hospodin uprostřed vás obdivuhodné věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'A kněžím Jozue řekl: Pozdvihněte truhlu smlouvy a přejděte před lidem. I pozdvihli truhlu smlouvy a šli před lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Nato řekl Hospodin Jozuovi: Tohoto dne tě začnu vyvyšovat v očích celého Izraele, takže poznají, že tak jako jsem byl s Mojžíšem, budu s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'A ty přikážeš kněžím nesoucím truhlu smlouvy: Jakmile přijdete až k okraji jordánských vod, zastavíte se v Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Jozue pak řekl synům Izraele: Přistupte sem a poslyšte slovo Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Jozue dále řekl: Po tomto poznáte, že živý Bůh je uprostřed vás a úplně vám podrobí ⌈Kenaance, Chetejce, Chivejce, Perizejce, Girgašejce i Emorejce a Jebúsejce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Hle, truhla smlouvy Pána celé země prochází před vámi do Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Nuže, vezměte za sebe dvanáct mužů z kmenů Izraele, ⌈ po jednom muži za každý kmen.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'A stane se, jakmile spočinou ve vodách Jordánu chodidla kněží nesoucích truhlu Hospodina, Pána celé země, že se jordánské vody roztrhnou, vody sestupující odshora, a zůstanou stát jako jednolitý val.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'A stalo se, když lid ⌈vytáhl ze svých stanů,⌉ aby prošel Jordánem, a kněží nesoucí truhlu smlouvy před lidem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'jakmile přišli, nesouce truhlu, až k Jordánu a nohy kněží nesoucích truhlu se namočily na okraji vod (Jordán se rozlil nad celý svůj břeh po všechny dny žní),');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'tu se zastavily vody, sestupující odshora, povstaly jako jednolitý val velmi daleko od města Adamu, které je poblíž Saretánu, a ty, které odtékají k moři Araby, Solnému moři, se ztratily, ustoupily a lid prošel naproti Jerichu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Kněží nesoucí truhlu smlouvy Hospodinovy zůstali stát pevně na suché zemi uprostřed Jordánu a všichni Izraelci procházeli po suché zemi, dokud neprošel celý ten národ Jordánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'I stalo se, jakmile prošel celý národ Jordánem, že Hospodin řekl Jozuovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Vyberte si z lidu dvanáct mužů, ⌈ po jednom muži z každého kmene,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'a přikažte jim: Vyneste si odsud zprostřed Jordánu, ze stanoviště, kde pevně stály nohy kněží, dvanáct kamenů. Vezmete je s sebou a ponecháte je v tábořišti, ve kterém se na noc utáboříte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Jozue tedy svolal těch dvanáct mužů, které určil ze synů Izraele, po jednom muži z každého kmene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Jozue jim řekl: Projděte před truhlou Hospodina, svého Boha, doprostřed Jordánu a vyzdvihněte si pro vás každý na rameno jeden kámen podle počtu kmenů synů Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'aby to bylo znamením uprostřed vás. Neboť vaši synové se zítra zeptají: K čemu máte tyto kameny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Tehdy jim povíte, jak ustoupily vody Jordánu před truhlou Hospodinovy smlouvy, když procházela Jordánem. Jordánské vody ustoupily a tyto kameny zůstanou na památku pro syny Izraele až na věky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Synové Izraele tedy učinili tak, jak Jozue přikázal, a vynesli dvanáct kamenů zprostřed Jordánu, jak to Hospodin vyhlásil před Jozuem, podle počtu kmenů synů Izraele, vzali si je s sebou do tábořiště a ponechali je tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, '⌈Jozue postavil dvanáct kamenů uprostřed Jordánu na stanovišti nohou kněží nesoucích truhlu smlouvy.⌉ Zůstaly tam až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'A kněží nesoucí truhlu stáli uprostřed Jordánu, dokud se nesplnilo každé slovo, které Jozuovi přikázal Hospodin, aby pověděl lidu všechno, co Jozuovi přikázal Mojžíš. Lid ⌈si pospíšil a prošel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'I stalo se, že jakmile přestal procházet všechen lid a prošla Hospodinova truhla a kněží před lidem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'prošli i synové Rúbenovi, synové Gádovi a polovina kmene Manasesova sešikováni před syny Izraele, jak jim to nakázal Mojžíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Asi čtyřicet tisíc vojenských ozbrojenců prošlo před Hospodinem do boje na jerišské stepi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'V onen den dal Hospodin Jozuovi vzrůst v očích celého Izraele a báli se ho, tak jako se báli Mojžíše po všechny dny jeho života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Tu Hospodin Jozuovi řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Přikaž kněžím nesoucím truhlu svědectví, ať vystoupí z Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Jozue tedy kněžím přikázal: Vystupte z Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Potom se stalo, jakmile kněží nesoucí truhlu Hospodinovy smlouvy vystoupili zprostřed Jordánu a chodidla kněží se dotkla suché země, že se jordánské vody navrátily na své místo a vyšly jako dříve nad celý svůj břeh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Když lid vystoupil desátého dne ⌈prvního měsíce⌉ z Jordánu, utábořili se v Gilgálu na východním okraji Jericha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Oněch dvanáct kamenů, které vzali z Jordánu, pak Jozue postavil v Gilgálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'A synům Izraele řekl: Až se vaši synové zítra zeptají svých otců: Co je tohle za kameny?,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'oznámíte svým synům: Izrael prošel tímto Jordánem po suchu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'když Hospodin, váš Bůh, před vámi nechal vyschnout jordánské vody, dokud jste neprošli, stejně jako to Hospodin, váš Bůh, učinil s Rákosovým mořem, které nechal vyschnout před námi, dokud jsme neprošli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'aby poznaly všechny národy země ruku Hospodinovu, jak je silná, abyste se báli Hospodina, svého Boha, po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'I stalo se, jakmile uslyšeli všichni emorejští králové, kteří sídlili na západě na druhé straně Jordánu, a všichni králové kenaanští, kteří sídlili u moře, o tom, jak Hospodin nechal vyschnout jordánské vody před syny Izraele, dokud neprošli, že se jejich srdce rozplynulo a před syny Izraele už ⌈byli bez dechu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'V onen čas řekl Hospodin Jozuovi: Zhotov si pazourkové nože a znovu, podruhé, obřež syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Jozue si tedy zhotovil pazourkové nože a syny Izraele obřezal u Návrší předkožek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'A toto je důvod, proč je Jozue obřezal: Všechen lid, který vyšel z Egypta, ti, kdo byli mužského pohlaví, všichni bojovníci, zemřeli v pustině na cestě po svém vyjití z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Neboť všichni v tom lidu, který vyšel, byli obřezáni, ale všechen lid zrozený v pustině na cestě, potom, co vyšli z Egypta, ti nebyli obřezáni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Synové Izraele totiž po pustině chodili čtyřicet let, až i vymřel celý ten národ, bojovníci, kteří vyšli z Egypta, kteří neuposlechli Hospodina, a jimž se Hospodin zapřísahal, že jim nedovolí spatřit zemi, o níž Hospodin přísahal jejich otcům, že nám ji dá, zemi oplývající mlékem a medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Dal ale povstat jejich synům namísto nich. Ty Jozue obřezal; byli totiž neobřezaní, protože je cestou neobřezávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'I stalo se, jakmile byl všechen národ hotov s obřezáváním, že zůstali ⌈na svém místě⌉ v táboře, dokud se nezotavili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Tu řekl Hospodin Jozuovi: Dnes jsem od vás odvalil egyptskou potupu. A nazval ono místo jménem Gilgál až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Synové Izraele tedy tábořili v Gilgálu a čtrnáctého dne v měsíci slavili večer Velikonoce na jerišských stepích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Od druhého dne Velikonoc jedli z výtěžku země nekvašené chleby a pražené zrní, právě tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Od druhého dne přestala i mana, když jedli z výtěžku té země. Synové Izraele už neměli manu, ale v onom roce jedli z úrody kenaanské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'I stalo se, když byl Jozue u Jericha, že pozvedl své oči, rozhlédl se a hle, naproti němu stojí muž a v ruce má tasený meč. Jozue šel k němu a zeptal se ho: Jsi s námi, nebo s našimi protivníky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'On řekl: Ne. Jsem přece velitel Hospodinova zástupu. Právě jsem přišel. Nato Jozue padl tváří k zemi a klaněl se. Zeptal se ho: Co můj Pán promluví ke svému otroku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Velitel Hospodinova zástupu Jozuovi odpověděl: Zuj si z nohou sandály, neboť místo, na němž stojíš, je svaté. A Jozue tak učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jericho se tehdy zavíralo a bylo uzavřeno před syny Izraele. Nikdo nevycházel ani nevcházel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Ale Hospodin Jozuovi řekl: Pohleď, vydal jsem ti do ruky Jericho i jeho krále s udatnými hrdiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Obejdete tedy město. Všichni bojovníci ať to město jednou obkrouží. Takto to budeš dělat šest dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'A sedm kněží pozdvihne před truhlou sedm beraních rohů. Sedmého dne obejdete město sedmkrát a kněží zatroubí na rohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'I stane se, až se táhle zatroubí na beraní roh, jakmile uslyšíte zvuk rohu, že všechen lid spustí velký křik, hradba toho města se na svém místě zhroutí a lid tam vystoupí, každý přímo vpřed.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Jozue, syn Núnův, tedy svolal kněze a řekl jim: Pozdvihněte truhlu smlouvy. Sedm kněží pak pozdvihne sedm beraních rohů před Hospodinovou truhlou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Potom řekl lidu: Jděte a obejděte město a vojsko ať projde před Hospodinovou truhlou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'I stalo se, jak to Jozue lidu řekl. Sedm kněží nesoucích sedm beraních rohů prošlo před Hospodinem, troubili na rohy a truhla Hospodinovy smlouvy šla za nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Vojsko šlo před kněžími troubícími na rohy a shromáždění se ubíralo za truhlou, tak šli a troubili na rohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Lidu pak Jozue přikázal: Nebudete křičet, ani ne necháte zaznít svůj hlas a z vašich úst nevyjde slovo až do dne, kdy vám řeknu: Křičte. Pak budete křičet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Nechal tehdy obejít Hospodinovu truhlu kolem města jednou dokola. Potom přišli do tábora a přenocovali v táboře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Jozue časně zrána vstal a kněží pozdvihli Hospodinovu truhlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'A sedm kněží nesoucích sedm beraních rohů před Hospodinovou truhlou stále šlo, troubili na rohy a vojsko šlo před nimi. Shromáždění šlo stále za Hospodinovou truhlou, troubíc na rohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Druhý den opět město jednou obešli a vrátili se do tábora. Takto si počínali šest dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Sedmého dne pak časně vstali, jakmile vyšla jitřenka, a obcházeli město podle tohoto nařízení sedmkrát. Pouze v onen den obešli město sedmkrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'I stalo se, když kněží po sedmé zatroubili na rohy, že Jozue řekl lidu: Spusťte křik, protože Hospodin vám město vydal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'A to město bude zasvěceno zkáze pro Hospodina, ono i každý, kdo je v něm. Pouze Rachab, ta prostitutka, zůstane naživu, ona a každý, kdo je s ní v domě, neboť ukryla posly, které jsme poslali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Hlavně ⌈se ale chraňte před klatbou, ať nevykonáte klatbu, ne vezmete z klatby, ne vystavíte klatbě⌉ izraelský tábor a ne uvalíte na něj zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'A veškeré stříbro, zlato a bronzové a železné nádoby jsou svaté pro Hospodina. Půjde to na Hospodinův poklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Tu lid spustil křik, zatroubili na rohy a stalo se, jakmile lid uslyšel zvuk rohu, že spustil velký povyk, hradba se zhroutila na svém místě, lid vystoupil do města, každý přímo vpřed, a to město dobyli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'A zasvětili zkáze ostřím meče všechno, co bylo ve městě, ⌈muže i ženy, mládence i starce i býky, ovce a osly.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Oběma mužům, kteří prozkoumali zemi, pak Jozue řekl: Jděte do domu té prostitutky a vyveďte odtamtud tu ženu a každého, kdo k ní patří, podle toho, co jste jí odpřisáhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Ti mládenci, zvědové, tedy vešli a vyvedli Rachabu i jejího otce, matku, bratry a každého, koho měla; všechny její příbuzné vyvedli a ponechali je venku za izraelským táborem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Potom spálili ohněm to město i všechno, co v něm bylo. Pouze stříbro, zlato a bronzové a železné nádoby zanechali na poklad Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Ale prostitutku Rachabu i dům jejího otce a všechno, co jí patřilo, Jozue nechal žít. Pobývala uprostřed Izraele až do tohoto dne, protože ukryla posly, které Jozue poslal, aby prozkoumali Jericho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'I zapřisáhl se Jozue v onen čas: ⌈Prokletý je před Hospodinem⌉ ten muž, který povstane a vystaví toto město Jericho. Na svém prvorozeném položí jeho základy a na svém nejmenším postaví jeho vrata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'A Hospodin byl s Jozuem a pověst o něm se rozšířila do celé té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Synové Izraele se však zpronevěřili věrolomností při klatbě. Akán, syn Karmího, syna Zabdího, syna Zeracha z pokolení Judova, vzal z toho, co bylo zasvěceno zkáze, a Hospodinův hněv vzplanul proti synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Jozue poslal muže z Jericha do Aje, který leží u Bét–ávenu na východ od Bét–elu, a řekl jim: Vystupte a prozkoumejte tu zemi. Ti muži vystoupili a prozkoumali Aj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Když se vrátili k Jozuovi, řekli mu: Ať netáhne všechen lid. Asi dva tisíce nebo tři tisíce mužů ať vytáhnou a pobijí Aj. ⌈Nevyčerpávej všechen lid, vždyť je jich tam málo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Tehdy tam vytáhly asi tři tisíce mužů z lidu, před muži z Aje však utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'A muži z Aje z nich pobili asi třicet šest mužů; pronásledovali je před branou až k Šebárímu a pobili je na svahu. Srdce lidu se rozplynulo a bylo ⌈jako voda.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Tu Jozue roztrhl své roucho a padl tváří k zemi před Hospodinovou truhlou až do večera, on a izraelští starší, a házeli si prach na hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'A Jozue řekl: ⌈Ach, Panovníku Hospodine,⌉ proč jsi vlastně převedl tento lid přes Jordán? Abys nás vydal do ruky Emorejců k naší záhubě? Kéž bychom se byli odhodlali a zůstali na druhé straně Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Dovol Panovníku, co mám říci potom, co se Izrael ⌈dal na útěk⌉ před svými nepřáteli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Až to uslyší Kenaanci a všichni obyvatelé té země, obklíčí nás a vyhladí naše jméno ze země. Co pak učiníš pro své veliké jméno?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Nato Hospodin Jozuovi řekl: Vstaň, proč takhle ležíš na tváři?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Izrael zhřešil a přestoupili také mou smlouvu, kterou jsem jim dal. Vzali také z toho, co bylo zasvěceno zkáze, také kradli, také zapírali a uložili to také mezi své věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Proto nebudou moci synové Izraele obstát před svými nepřáteli. Obrátí se před svými nepřáteli na útěk, protože se stali klatbou. Už s vámi nebudu, pokud nevyhladíte klatbu ze svého středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Vstaň, posvěť lid a řekneš: Posvěťte se na zítra, protože toto řekl Hospodin, Bůh Izraele: Uprostřed tebe, Izraeli, je to, co je zasvěceno zkáze. Nemůžeš obstát před svými nepřáteli, dokud neodstraníte věc zasvěcenou zkáze ze svého středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Budete tedy ráno přistupovat podle svých kmenů a zůstane ten kmen, který Hospodin označí. Bude přistupovat po čeledích a ta čeleď, kterou Hospodin označí, bude přistupovat po rodinách a ta rodina, kterou Hospodin označí, bude přistupovat po mužích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'A kdo bude označen kvůli klatbě, bude spálen ohněm, on i všechno, co mu patří, protože přestoupil Hospodinovu smlouvu a protože se dopustil v Izraeli bláznovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Jozue časně ráno vstal a předvedl Izrael podle jeho kmenů. Byl označen kmen Juda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Předvedl tedy judskou čeleď a označil čeleď Zerachejců. Předvedl čeleď Zerachejců po mužích a označen byl Zabdí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Pak předvedl jeho rodinu po mužích a označen byl Akán, syn Karmího, syna Zabdího, syna Zeracha z pokolení Judova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Jozue Akánovi řekl: Můj synu, přiznej přece slávu Hospodinu, Bohu Izraele, vzdej mu chválu a oznam mi konečně, co jsi spáchal. Nezatajuj to přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Akán Jozuovi odpověděl. Řekl: Proti Hospodinu, Bohu Izraele, jsem opravdu zhřešil já a udělal jsem to a to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Uviděl jsem mezi kořistí jeden hezký šineárský plášť, dvě stě šekelů stříbra a jeden zlatý jazyk o váze padesáti šekelů. Dychtil jsem po těch věcech a vzal jsem je. Hle, je to ukryto v zemi uprostřed mého stanu a to stříbro je pod tím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Jozue tedy poslal posly. Běželi do toho stanu a vida: Bylo to ukryto v jeho stanu a stříbro bylo pod tím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Tak ty věci zprostřed stanu vzali, přinesli je k Jozuovi a ke všem synům Izraele a vysypali je před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Nato Jozue vzal Akána, syna Zerachova, i to stříbro, ten plášť a ten zlatý jazyk i jeho syny a dcery a jeho ⌈skot, osly a brav⌉ i jeho stan a všechno, co mu patřilo. Celý Izrael byl s ním a vyvedli je do údolí Akóru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Jozue řekl: Jakou zkázu jsi uvalil na nás, takovou zkázu uvalí Hospodin v tento den na tebe. Všechen Izrael na něho házel kamení. Spálili je ohněm a ukamenovali je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Potom na něj postavili velkou haldu kamení až do tohoto dne. Hospodin se odvrátil od svého planoucího hněvu; kvůli tomu nazval ono místo jménem údolí Akór až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Tu řekl Hospodin Jozuovi: Neboj se ani se neděs. Vezmi s sebou všechen ⌈bojeschopný lid⌉ a povstaň, vytáhni proti Aji. Pohleď, vydal jsem do tvé ruky krále Aje, jeho lid, jeho město a jeho zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'A naložíš s Ajem a s jeho králem tak, jak jsi naložil s Jerichem a s jeho králem; pouze kořist z něj a jeho dobytek zaberete pro sebe. Postav si k městu zezadu zálohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Jozue tedy vstal a s ním i všechen bojeschopný lid, aby táhli na Aj. Jozue vybral třicet tisíc mužů, udatných hrdinů, a v noci je tam poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Přikázal jim: Hleďte vy, kdo číháte proti městu ze zadní strany města, příliš se od města nevzdalujte. Vy všichni budete připravení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'A já i všechen lid, který je se mnou, se přiblížíme k městu. Bude to tak, že proti nám vytáhnou jako poprvé a my budeme před nimi utíkat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Potom vyjdou za námi, až je i odlákáme od města, protože řeknou: Utíkají před námi tak jako poprvé. A my před nimi budeme utíkat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Vy pak povstanete ze zálohy, obsadíte to město a Hospodin, váš Bůh, vám ho vydá do ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'A tehdy, jakmile se města zmocníte, spálíte to město ohněm. Provedete to podle Hospodinova slova. Hleďte, to jsem vám přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Jozue je tedy poslal a oni šli do zálohy a usadili se mezi Bét–elem a Ajem na západ od Aje. Jozue oné noci zůstal uprostřed lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Ráno si Jozue přivstal a vykonal přehlídku lidu. Potom k Aji v čele lidu stoupal on sám s izraelskými staršími.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'I všechen bojeschopný lid, který byl s ním, ti vytáhli a přiblížili se, až se dostali před město, a utábořili se na sever od Aje. Mezi ním a Ajem bylo údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Potom vzal asi pět tisíc mužů a postavil je do zálohy mezi Bét–elem a Ajem na západ od města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Lid se rozložil, celý tábor, který byl na sever od města, i jeho zadní voj na západ od města. Jozue oné noci vyšel doprostřed údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'I stalo se, jakmile to uviděl král Aje, že si muži města pospíšili, časně vstali a vytáhli Izraeli vstříc do bitvy, on i všechen jeho lid, ke střetnutí před Arabou. On nevěděl, že je proti němu ze zadní strany města záloha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Když byli Jozue a celý Izrael od nich napadeni, utíkali cestou k pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Tu se shromáždili všichni z lidu, kteří byli v Aji, aby je pronásledovali. Pronásledovali tedy Jozua a byli odříznuti od města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'V Aji a Bét–elu nezůstal jediný muž, který by nevytáhl za Izraelem. Zanechali město otevřené a pronásledovali Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Tehdy Hospodin Jozuovi řekl: Vztáhni srpáč, který máš ve své ruce, proti Aji, neboť jej vydám do tvé ruky. Jozue tedy vztáhl srpáč, který měl ve své ruce, proti městu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Nato záloha rychle povstala ze svého místa. Vyběhli, ⌈jakmile vztáhl⌉ svou ruku, přišli do města a obsadili ho, pospíšili si a město zapálili ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Muži z Aje se ohlédli za sebe a hle, uviděli, jak kouř vystoupil z města k nebesům, ale nebylo v jejich silách, aby utíkali tam ani tam. Lid utíkající do pustiny se obrátil proti pronásledovateli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Jozue a všechen Izrael viděli, že záloha obsadila město a že z města vystoupil kouř. Vraceli se tedy zpět a pobíjeli muže z Aje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'A ti z města jim vyšli naproti, takže byli v sevření Izraele z jedné i z druhé strany. Pobíjeli je, aniž by z nich nechali někoho přežít nebo uniknout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Krále Aje však chytili živého a přivedli jej k Jozuovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'I stalo se, jakmile Izrael přestal zabíjet veškeré obyvatele Aje na poli v pustině, v níž je pronásledovali (všichni padli ostřím meče, do svého úplného vyhlazení), že se všichni z Izraele vrátili do Aje a vybili ho ostřím meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'V onen den bylo všech padlých ⌈mužů i žen⌉ dvanáct tisíc, všichni lidé z Aje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Jozue nespustil ruku, ve které vztáhl srpáč, dokud nezasvětil zkáze všechny obyvatele Aje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Pouze dobytek a kořist z onoho města zabrali Izraelci pro sebe, podle Hospodinova slova, které Jozuovi přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Jozue Aj spálil a proměnil ho ve věčnou hromadu sutě, spoušť až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'A krále Aje pověsil na dřevo ⌈až do večerního času.⌉ ⌈Když slunce zapadalo,⌉ dal Jozue příkaz, aby jeho mrtvolu sundali z toho stromu, pohodili ji ke vchodu městské brány a postavili na něj velkou haldu kamení až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tehdy postavil Jozue oltář pro Hospodina, Boha Izraele, na hoře Ébalu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'jak to přikázal Mojžíš, otrok Hospodinův, synům Izraele, jak je napsáno v knize Mojžíšova zákona: Oltář z neporušených kamenů, ⌈které neopracovávalo železo.⌉ I přinesli na něm zápalné oběti pro Hospodina a obětovali pohostinné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'A sepsal tam na těch kamenech opis Mojžíšova zákona, který jej zapsal před syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'A všechen Izrael i jeho starší, správcové a jeho soudcové při tom stáli z jedné i z druhé strany truhly před lévijskými kněžími nesoucími truhlu Hospodinovy smlouvy, stejně příchozí jako domorodec, polovina z nich směrem k hoře Gerizím a polovina z nich směrem k hoře Ébal, jak to přikázal Mojžíš, otrok Hospodinův, aby nejprve žehnali izraelskému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Potom vyhlásil veškerá slova zákona, požehnání i kletbu, ⌈tak, jak je to zapsáno⌉ v knize zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Nebylo slova ze všech, jež přikázal Mojžíš, které by Jozue nevyhlásil před celým shromážděním Izraele, i ženám, malým dětem a příchozím poutníkům uprostřed nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'I stalo se, jakmile to uslyšeli všichni králové, kteří sídlili na druhé straně Jordánu v pohoří, v podhůří a na celém pobřeží Velikého moře směrem k Libanonu, král chetejský a emorejský, kenaanský, perizejský, chivejský a jebúsejský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'že ⌈se společně shromáždili,⌉ aby vedli válku s Jozuem a s Izraelem pod jedním velením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Když se obyvatelé Gibeónu doslechli, co Jozue provedl s Jerichem a s Ajem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'tu také oni jednali chytře, šli a vydávali se za posly. Vzali na své osly opotřebované pytle a opotřebované, popraskané a svazované vinné měchy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'na nohách měli opotřebované a spravované sandály, na sobě opotřebované pláště a veškerý chléb z jejich zásob byl suchý, ⌈ až se drolil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Tak šli k Jozuovi do tábora v Gilgálu a řekli jemu i izraelským mužům: Přišli jsme ze vzdálené země, nyní tedy s námi uzavřete smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Nato izraelští muži Chivejcům odpověděli: Vy možná pobýváte ⌈mezi námi.⌉ Jak s ⌈vámi máme uzavřít⌉ smlouvu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Tu řekli Jozuovi: Jsme tví otroci. A Jozue se jich zeptal: Kdo jste a odkud přicházíte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Odpověděli mu: Tví otroci přišli z velmi vzdálené země kvůli jménu Hospodina, tvého Boha, neboť jsme uslyšeli zvěst o něm a o všem, co učinil v Egyptě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'a o všem, co učinil dvěma emorejským králům na druhé straně Jordánu, Síchonovi, králi Chešbónu, a Ógovi, králi bášanskému, v Aštarótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Naši starší i všichni obyvatelé naší země nám tedy řekli: Vezměte ⌈si s sebou⌉ zásobu potravin na cestu, jděte jim naproti a řeknete jim: Jsme vaši otroci, nyní s námi uzavřete smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Tento náš chléb jsme s sebou vzali do zásoby ještě horký z našich domů v den, kdy jsme se vydávali na cestu k vám, a nyní hle, vyschl, ⌈ jen se drolí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'A hle, i tyto vinné měchy, které jsme naplnili jako nové, popraskaly. I tyto naše pláště a naše sandály se obnosily, protože cesta byla velmi dlouhá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Muži si tedy vzali z jejich zásob, aniž se zeptali na Hospodinův příkaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Jozue s nimi dojednal pokoj a uzavřel s nimi smlouvu, že jim daruje život, a předáci obce jim to odpřisáhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, '⌈Když však uplynuly⌉ tři dny poté, co s nimi uzavřeli smlouvu, stalo se, že se doslechli, že jsou nedaleko od nich a pobývají ⌈mezi nimi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Synové Izraele vyrazili a třetího dne přišli k jejich městům. Byla to města Gibeón, Kefíra, Beerót a Kirjat–jearím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Synové Izraele je však nepobili, neboť jim předáci obce přísahali při Hospodinu, Bohu Izraele, a tak reptali, celá obec, proti těm předákům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Nato řekli všichni předáci celé obci: My jsme jim přísahali při Hospodinu, Bohu Izraele. Nyní tedy na ně nemůžeme sáhnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Provedeme s nimi tohle: Zachováme je při životě a nedopadne na nás rozhořčení kvůli přísaze, kterou jsme jim odpřisáhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Předáci jim řekli: Ať zůstanou naživu. I stali se z nich dřevorubci a čerpali vodu pro celou obec, jak jim to předáci nakázali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Jozue na ně zavolal a promluvil k nim: Proč jste nás podvedli? Že prý: Jsme od vás velmi vzdálení. A přitom bydlíte mezi námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Nyní jste tedy prokletí a ⌈nepřestanete být otroky,⌉ dřevorubci a nosiči vody pro dům mého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Nato Jozuovi odpověděli. Řekli: Jelikož bylo tvým otrokům dobře známo, co přikázal Hospodin, tvůj Bůh, svému otroku Mojžíšovi, že vám dá celou zemi a že před vámi vyhladí všechny obyvatele té země, proto jsme se hrozně báli před vámi o své duše a provedli jsme tuto věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Nuže, hle, jsme ve tvé ruce. ⌈Udělej, co je ve tvých očích dobré a správné nám provést.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'I naložil s nimi tak a vysvobodil je z ruky synů Izraele, takže je nezabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Jozue je v onen den nechal těžit dřevo a čerpat vodu pro obec a pro Hospodinův oltář až do tohoto dne na místě, které vybere.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Jakmile jeruzalémský král Adonísedek uslyšel, že Jozue dobyl Aj a zasvětil ho zkáze (tak, jak naložil s Jerichem a s jeho králem, tak naložil s Ajem a s jeho králem) a že obyvatelé Gibeónu uzavřeli mír s Izraelem a zůstali mezi nimi, stalo se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'že se hrozně bál, protože Gibeón bylo velké město, jako jedno z měst královských, a protože bylo větší nežli Aj a všichni jeho muži byli hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Tu vzkázal Adonísedek, král Jeruzaléma, k chebrónskému králi Hóhamovi, k jarmútskému králi Pirámovi, k lakíšskému králi Jafíovi a k eglónskému králi Debírovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Vystupte ke mně a pomozte mi, ať pobijeme Gibeón, protože uzavřel mír s Jozuem a se syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Pět emorejských králů se tedy shromáždilo a vytáhli: Král Jeruzaléma, král Chebrónu, král Jarmútu, král Lakíše, král Eglónu, oni a všechna jejich vojska, utábořili se u Gibeónu a bojovali proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Tu vzkázali gibeónští muži Jozuovi do tábora v Gilgálu: Nespouštěj svou ruku ze svých otroků. Vystup rychle k nám, zachraň nás a pomoz nám, vždyť se proti nám shromáždili všichni emorejští králové sídlící v pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Jozue tedy vytáhl z Gilgálu, on a s ním všechen bojeschopný lid i všichni udatní hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'A Hospodin Jozuovi řekl: Neboj se jich, neboť jsem ti je vydal do ruky, nikdo z nich před tebou neobstojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Jozue k nim přišel náhle; celou noc táhl z Gilgálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Hospodin je přivedl před Izraelem do zmatku a pobil je v Gibeónu velkou porážkou. Pronásledoval je směrem ke svahu u Bét–chorónu a pobíjel je až do Azeky a Makedy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'I stalo se při jejich útěku před Izraelem, když byli na svahu u Bét–chorónu, že na ně ⌈Hospodin svrhl z nebes velké kameny⌉ až do Azeky, a umírali. Těch, kteří zemřeli ⌈prostřednictvím kamenného⌉ krupobití, bylo více než těch, jež zabili synové Izraele mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Jozue tehdy promluvil k Hospodinu, v den, kdy Hospodin vydal Emorejce před syny Izraele, a řekl ⌈před zraky⌉ Izraelců: Zůstaň stát, slunce, v Gibeónu! I ty, měsíci, v údolí Ajalónu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Tu slunce zůstalo stát a měsíc se zastavil, dokud se národ ne pomstil svým nepřátelům. Což není zapsáno v knize Jašarově: I zastavilo se slunce v polovině nebes a nespěchalo k západu po celý den?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'A nebylo dne jako onen den před ním ani po něm, aby Hospodin tak vyslyšel volání člověka, neboť Hospodin bojoval za Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Potom se vrátil Jozue a s ním celý Izrael do tábora v Gilgálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Oněch pět králů tehdy uteklo a ukryli se v Makedě v jeskyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Tu bylo Jozuovi oznámeno: Našlo se těch pět králů, jak se skrývají v jeskyni v Makedě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Jozue nato řekl: Přivalte k ústí té jeskyně velké kameny a určete k ní muže, aby je střežili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ale vy neustávejte, pronásledujte své nepřátele, ať jim ⌈zničíte zadní voj.⌉ Nedovolte jim vejít do jejich měst, protože je Hospodin, váš Bůh, vydal do vaší ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'I stalo se, jakmile je přestal Jozue a synové Izraele ⌈stíhat zdrcující⌉ porážkou až do jejich úplného vyhlazení, že z nich vyvázli někteří, kteří přežili, a dostali se do opevněných měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Pak se vrátili, všechen lid, v pokoji do tábora k Jozuovi v Makedě. Nikdo proti synům Izraele nenaostřil svůj jazyk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Potom Jozue řekl: Otevřete ústí jeskyně a vyveďte ke mně z jeskyně těchto pět králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Učinili tak a vyvedli k němu z jeskyně těchto pět králů: Krále jeruzalémského, krále chebrónského, krále jarmútského, krále lakíšského a krále eglónského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'I stalo se, jakmile vyvedli k Jozuovi tyto krále, že Jozue zavolal na všechny izraelské muže a řekl vůdcům bojovníků, kteří šli s ním: Přistupte a položte své nohy na šíje těmto králům. Přistoupili tedy a položili své nohy na jejich šíje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Jozue jim řekl: ⌈Nebojte se a neděste se, posilněte se a buďte odvážní,⌉ neboť takto naloží Hospodin se všemi vašimi nepřáteli, s nimiž vedete válku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Potom je Jozue dal zabít, nechal je zemřít a pověsil je na pět kůlů. Byli na těch kůlech pověšení až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'I stalo se v době západu slunce, že Jozue dal příkaz, sundali je z těch kůlů a pohodili je do jeskyně, do níž se ukryli, a položili velké kameny na ústí té jeskyně právě až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'V onen den Jozue dobyl i Makedu a vybil ji ostřím meče i s jejím králem. Zasvětil je i všechno živé, co v ní bylo, zkáze. Nenechal nikoho přežít a s králem Makedy naložil tak, jak naložil s jerišským králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Potom přešel Jozue a celý Izrael s ním z Makedy do Libny a bojoval s Libnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Také tu Hospodin vydal Izraeli do ruky i s jejím králem. Vybil ostřím meče ji i všechno živé, co v ní bylo. Nenechal v ní nikoho přežít a naložil s jejím králem tak, jak naložil s králem Jericha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Pak Jozue a s ním celý Izrael přešel z Libny do Lakíše, utábořil se u něj a bojoval proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Hospodin vydal Izraeli do ruky i Lakíš. Dobyl jej druhého dne a vybil ho ostřím meče i veškerý život, který v něm byl, zcela tak, jak naložil s Libnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Tehdy vytáhl Horám, král Gezeru, Lakíši na pomoc, ale Jozue pobil jej i jeho lid, aniž by z něj nechal někoho přežít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Jozue a s ním celý Izrael potom přešel z Lakíše do Eglónu, utábořili se u něj a bojovali proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'V onen den jej dobyli a vybili ho ostřím meče. Všechno živé, co v něm bylo, zasvětil v onen den zkáze zcela tak, jak naložil s Lakíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Pak Jozue a celý Izrael s ním vytáhl z Eglónu do Chebrónu a bojovali proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'A dobyli jej a vybili ho ostřím meče i jeho krále, všechna jeho města a všechno živé, co v něm bylo. Nenechal nikoho přežít, zcela tak, jak naložil s Eglónem, a zasvětil zkáze jej a všechno živé, co v něm bylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Jozue a celý Izrael s ním se potom obrátil k Debíru a bojoval proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'A dobyl jej i s jeho králem a všechna jeho města, vybili je ostřím meče a všechno živé, co v něm bylo, zasvětili zkáze. Nenechal nikoho přežít. Tak, jak naložil s Chebrónem, tak naložil s Debírem a s jeho králem; tak, jak naložil i s Libnou a s jejím králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Tak pobil Jozue celou zemi, pohoří i jih, Šefelu i srázy, a všechny jejich krále. Nenechal nikoho přežít a všechno, co dýchalo, zasvětil zkáze, jak to přikázal Hospodin, Bůh Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Jozue je vybil od Kádeš–barneje až po Gazu a celou zemi Gošen až do Gibeónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Jozue tak všechny tyto krále a jejich zemi naráz dobyl, protože Hospodin, Bůh Izraele, bojoval za Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Jozue a celý Izrael s ním se pak vrátil do Gilgálu do tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'I stalo se, jakmile to uslyšel chasórský král Jabín, že vzkázal k madónskému králi Jóbabovi, k šimrónskému králi a k akšáfskému králi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'a ke králům ze severu v pohoří, v Arabě jižně od Kineretu, v podhůří a v Dórských návrších na západě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Kenaanci byli na východě a na západě, Emorejci, Chetejci, Perizejci a Jebúsejci v pohoří a Chivejci pod Chermónem v zemi Mispě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Tehdy vytáhli, oni a veškerá jejich vojska s nimi, lid na množství početný jako písek, který je na mořském břehu, i koní a vozby velmi mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Všichni tito králové se dohodli, přišli a utábořili se společně u vod Merómu, aby s Izraelem bojovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Tu řekl Hospodin Jozuovi: ⌈Neboj se jich,⌉ neboť já je zítra touto dobou všechny uvrhnu probodené před Izrael. Jejich koně ochromíš a jejich válečné vozy spálíš ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Jozue a všechen bojeschopný lid s ním na ně tedy náhle přitáhl k vodám Merómu a napadli je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Hospodin je vydal Izraeli do ruky. Pobíjeli je a pronásledovali je až k velkému Sidónu, do Misrefót–majimu a až na pláň Mispu na východě. Pobíjeli je, aniž by z nich nechal někoho přežít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'A Jozue s nimi naložil podle toho, co mu řekl Hospodin: Jejich koně ochromil a jejich válečné vozy spálil ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Jozue se v onen čas navrátil zpět, dobyl Chasór a jeho krále zabil mečem, protože Chasór byl předtím hlavou všech těchto království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'A pobili všechno živé, co v něm bylo, ostřím meče vykonali klatbu. Nezůstalo naživu nic, co dýchalo; Chasór spálil ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'A všechna města těchto králů a všechny jejich krále Jozue dobyl a vybil je ostřím meče. Zasvětil je zkáze, jak to přikázal Mojžíš, otrok Hospodinův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Izrael ovšem nespálil žádná města, která stojí na hromadě sutě, kromě Chasóru. Pouze ten Jozue spálil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Všechnu kořist z těchto měst a dobytek jim synové Izraele zabrali. Každého člověka ovšem zabili ostřím meče, až je vyhladili. Neponechali z nich žádného, kdo dýchal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Jak to přikázal Hospodin svému otroku Mojžíšovi, tak přikázal Mojžíš Jozuovi a Jozue tak učinil. Neubral jediné slovo ze všech, která Hospodin Mojžíšovi přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'A tak Jozue zabral celou tuto zemi: Pohoří a celý Negeb, celou zemi Gošen a Šefelu, Arabu a izraelské pohoří i jeho podhůří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Od hory Chalak zvedající se k Seíru a až k Baal–gádu v libanonském údolí pod pohořím Chermón. Všechny jejich krále zajal, pobil je a usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Jozue vedl se všemi těmito králi válku po mnoho dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Nebylo města, které by se syny Izraele uzavřelo mír, kromě chivejských obyvatel Gibeónu. Všechna je zabrali bojem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Neboť se to stalo od Hospodina, že ⌈posilnil jejich srdce,⌉ aby vyvolali válku s Izraelem, aby na ně uvalil klatbu, ⌈aby pro ně nebylo smilování, aby⌉ je vyhladil, jak to Hospodin přikázal Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'V onen čas přišel Jozue a vyhladil Anákovce z pohoří, z Chebrónu, z Debíru, z Anábu, z celého judského pohoří a z celého izraelského pohoří. Jozue je zasvětil zkáze spolu s jejich městy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'V zemi synů Izraele nezbyl žádný z Anákovců, zůstali pouze v Gaze, v Gatu a v Ašdódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Jozue zabral celou tu zemi podle všech slov, která Hospodin promluvil k Mojžíšovi. Jozue ji předal Izraeli do dědictví, jejich kmenům, podle jejich podílů, a země měla klid od války.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'A toto jsou králové té země, které synové Izraele pobili a obsadili jejich zemi na druhé straně Jordánu na východě slunce, od ⌈potoka Arnónu až k hoře Chermónu⌉ a celou Arabu na východě:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Emorejský král Síchon sídlící v Chešbónu vládnoucí od Aróeru, který je na břehu potoka Arnónu, od středu toho údolí a poloviny Gileádu až k potoku Jabok, který tvoří hranici synů Amónových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'a od Araby na východ až ke Kineretskému moři a až k moři Araby, Solnému moři, na východ směrem k Bét Ješimótu a z jihu pod srázy Pisgy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Dále území bášanského krále Óga ze zbytku Refájců sídlícího v ⌈Aštarótu a v Edreí⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'a vládnoucího nad horou Chermónem, nad Salkou a nad celým Bášanem až ke ⌈gešúrejské a maakatské hranici⌉ a nad polovinou Gileádu k hranici chešbónského krále Síchona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mojžíš, otrok Hospodinův, a synové Izraele je pobili a Mojžíš, otrok Hospodinův, jej dal do vlastnictví Rúbenovcům, Gádovcům a polovině kmene Manasesova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'A toto jsou králové země, které Jozue se syny Izraele pobil na druhé straně Jordánu ⌈na západě, od Baal–gádu v libanonském údolí⌉ až k hoře Chalak zvedající se k Seíru. Jozue ji dal izraelským kmenům do vlastnictví podle jejich podílů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'v pohoří a v podhůří, ve stepi a ve srázech, v pustině a na jihu, zemi chetejskou, emorejskou a kenaanskou, perizejskou, chivejskou a jebúsejskou. Tedy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Král Jericha jeden, král Aje, jenž leží poblíž Bét–elu, jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'král Jeruzaléma jeden, král Chebrónu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'král Jarmútu jeden, král Lakíše jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'král Eglónu jeden, král Gezeru jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'král Debíru jeden, král Gederu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'král Chormy jeden, král Aradu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'král Libny jeden, král Adulámu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'král Makedy jeden, král Bét–elu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'král Tapúachu jeden, král Cheferu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'král Afeku jeden, král ze Šáronu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'král Mádónu jeden, král Chasóru jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'král Šimrón Merónu jeden, král Akšáfu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'král Taanaku jeden, král Megida jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'král Kedeše jeden, král Jokneámu u Karmelu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'král Dóru na Dórském návrší jeden, král národů z Gilgálu jeden,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'král Tirsy jeden; všech králů: třicet jedna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Jozue ⌈zestárl a dosáhl pokročilého věku. Hospodin⌉ mu řekl: Ty jsi zestárl, dosáhl jsi pokročilého věku, ale zůstalo ještě velmi mnoho země k obsazení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Toto je země, která zůstává: Všechny oblasti Pelištejců a celá oblast gešúrejská;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'od Šíchoru, který je na čele Egypta, až po území Ekrónu na sever patřící Kenaancům se počítá pět pelištejských vladařů: Obyvatelů Gazy a Ašdóďanů, Aškalóňanů, Gaťanů a Ekróňanů, ⌈a také Avijci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Na jihu⌉ pak celá kenaanská země a Meára, která patří Sidóncům, až do Afeku, až k emorejské hranici');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'a gebalská země a celý Libanon na východ slunce od Baal–gádu pod horou Chermón, až k Lebo–Chamátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Všichni obyvatelé pohoří od Libanonu až k Misrefót–majimu, všichni Sidónci; já je synům Izraele podrobím. Pouze ji přiděl Izraeli do dědictví, jak jsem ti přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Nuže, rozděl tuto zemi do dědictví devíti kmenům a polovině kmene Manasesova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'S ním přijali Rúbenovci a Gádovci své dědictví, které jim dal Mojžíš na druhé straně Jordánu na východě, jak jim to ustanovil Mojžíš, otrok Hospodinův:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Od Aróeru, který je na břehu potoka Arnónu, a od města, jež leží uprostřed toho údolí, celou médebskou rovinu až k Díbónu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'a všechna města emorejského krále Síchona, který kraloval v Chešbónu, až k hranici synů Amónových');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'a Gileád, gešúrejské a maakatské území, celé pohoří Chermón a celý Bášan až do Salky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'celé království Óga v Bášanu, který kraloval v Aštarótu a v Edreí. Ten zůstal ze zbytku Refájců. Mojžíš je pobil a podrobil si je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Synové Izraele si však nepodrobili Gešúrejce a Maakaťany. Gešúr a Maakat tedy pobývá uprostřed Izraele až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Pouze kmeni Lévi nedal dědictví. Ohnivé oběti Hospodina, Boha Izraele, to je jeho dědictví, jak to o něm prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Mojžíš tedy pokolení synů Rúbenových, jejich čeledím, dal');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'a dostalo se jim území od Aróeru, který je na břehu potoka Arnónu, i město, které leží uprostřed toho údolí, a celá rovina u Médeby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Chešbón a všechna jeho města, která jsou v rovině, Díbón, Bamót–baal, Bét–baal–meón');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'i Jahas, Kedemót a Méfaat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjatajim, Sibma a Seret–šachar na hoře v údolí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bét–peór, srázy Pisgy a Bét–ješimót,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'všechna města na náhorní rovině a celé království emorejského krále Síchona, jenž kraloval v Chešbónu, kterého zabil Mojžíš, jej i midjánské předáky Evího, Rekema, Súra, Chúra a Rebu, Síchonovy vazaly sídlící v té zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Také Bileáma, syna Beórova, toho věštce, synové Izraele zabili mečem s ostatními probodenými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Hranicí synů Rúbenových byl Jordán a ostatní hranice. Toto bylo dědictví synů Rúbenových pro jejich čeledi; města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Pokolení Gádovu, Gádovým synům, Mojžíš dal pro jejich čeledi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'a dostalo se jim území Jaezeru a všechna města Gileádu a polovina země synů Amónových až k Aróeru, který je naproti Rabě');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'a od Chešbónu až k výšině Mispy a Betonímu a od Machanajimu až k hranici u Debíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'V údolí dále Bét–rám a Bét–nimra, Sukót a Safón, zbytek království chešbónského krále Síchona, Jordán a hranice až k okraji Kineretského moře na východ za Jordánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Toto je dědictví synů Gádových pro jejich čeledi, města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Mojžíš dal polovině kmene Manasesova a polovině pokolení synů Manasesa se dostalo pro jejich čeledi toto:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Jejich území se táhlo od Machanajimu: Celý Bášan, celé království bášanského krále Óga a všechna Jaírova tábořiště, která jsou v Bášanu; šedesát měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'A polovina Gileádu, Aštarót a Edreí, města Ógova království v Bášanu pro syny Makíra, syna Manasesova; polovině Makírových synů pro jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Toto jsou území, která Mojžíš přidělil do dědictví v moábských stepích z druhé strany Jordánu u Jericha na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Kmenu Léviho však Mojžíš dědictví nedal. Hospodin, Bůh Izraele, on je jejich dědictvím, jak to o nich prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'A toto jsou území, která zdědili synové Izraele v kenaanské zemi, jež jim přidělili do dědictví kněz Eleazar, Jozue, syn Núnův, a přední otcové pokolení synů Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'podle losu jejich dědictví, jak to ⌈přikázal Hospodin prostřednictvím Mojžíše,⌉ pro devět a půl pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Neboť Mojžíš dal dědictví dvěma a půl pokolením na druhé straně Jordánu; Lévijcům však uprostřed nich dědictví nedal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Synové Josefovi totiž tvořili dvě pokolení: Manases a Efrajim. Lévijcům nedali podíl v zemi, jenom města k bydlení a pastviny pro jejich stáda a pro jejich dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Jak to Hospodin přikázal Mojžíšovi, tak synové Izraele učinili a rozdělili si tu zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Synové Judovi pak přistoupili k Jozuovi v Gilgálu a Kenazejec Káleb, syn Jefunův, mu řekl: Ty znáš to slovo, které promluvil Hospodin k Mojžíšovi, muži Božímu, ohledně mě a ohledně tebe v Kádeš–barneji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Bylo mi čtyřicet let, když mě Mojžíš, otrok Hospodinův, poslal z Kádeš–barneje, abych prozkoumal zemi, a já jsem mu přinesl zpět zprávu tak, jak to bylo v mém srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Moji bratři, kteří vytáhli se mnou, sice rozložili srdce lidu, ale já jsem ⌈šel naplno⌉ za Hospodinem, svým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Tu Mojžíš v onen den přísahal: Cožpak ta země, na kterou šlápla tvá noha, nebude za dědictví pro tebe a pro tvé syny až navěky, protože jsi ⌈šel naplno⌉ za Hospodinem, mým Bohem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Nuže hle, Hospodin mě nechal žít, jak to prohlásil. Čtyřicet pět let uplynulo od té doby, co Hospodin promluvil toto slovo k Mojžíšovi, když šel Izrael po pustině, a nyní hle, já jsem dnes ve věku osmdesáti pěti let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Ještě dnes jsem tak silný jako v den, kdy mě Mojžíš poslal. Jaká byla moje síla tehdy, taková je moje síla i nyní, do boje i k vycházení a ke vcházení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Nuže, dej mi toto pohoří, o kterém Hospodin promluvil v onen den, neboť ty jsi v onen den slyšel, že tam jsou Anákovci a velká opevněná města. Snad bude Hospodin se mnou a podrobím si je, jak to Hospodin prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Poté mu Jozue požehnal a dal Chebrón Kálebovi, synu Jefunovu, do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Proto se dostal Chebrón Kenazejci Kálebovi, synu Jefunovu, do dědictví až do tohoto dne, protože ⌈šel naplno⌉ za Hospodinem, Bohem Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Jméno Chebrónu bylo předtím Kirjat–arba. Ten Arba byl největší člověk mezi Anákovci. Země pak měla klid od války.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Pro pokolení synů Judových padl los pro jejich čeledi u hranice Edómu a pustiny Sinu na jih, od jižní končiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Dostalo se jim území Negebu od břehu Solného moře, od jazyku obráceného k jihu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Vychází od Negebu k ⌈průsmyku Akrabim,⌉ prochází do Sinu a stoupá od jihu ke Kádeš–barneji, prochází Chesrónem, stoupá k Adáru a stáčí se do Karky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Pak prochází do Asmónu, přechází egyptský potok a výběžky hranice dosahují směrem k moři. Toto bude pro vás jižní hranice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Hranicí na východ potom bude Solné moře až ke břehu Jordánu a hranice k severní straně půjde od mořského jazyku od jordánského břehu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Hranice opět stoupá k Bét–chogle a prochází od severu k Bét–arabě, potom stoupá ke kameni Bohana, syna Rúbenova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Hranice dále stoupá k Debíru z údolí Akóru a obrací se na sever ke Gilgálu, naproti Adumímskému svahu, který leží jižně od potoka. Dále prochází k vodám Én–šemeše a její výběžky dosahují k Én–rogelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Hranice dále stoupá údolím Hinómova syna od jihu k jebúsejskému hřebeni, což je Jeruzalém. Potom stoupá k vrcholu hory, která je naproti Hinómovu údolí na západ a která je na okraji údolí Refájců na sever.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Dále hranice zabočuje od vrcholu té hory k prameni vod Neftóachu a vybíhá k městům pohoří Efrónu a pak zabočuje k Baale, což je Kirjat–jearím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Hranice se stáčí od Baaly na západ k pohoří Seíru a prochází od severu k úbočí hory Jearímu, což je Kesalón, sestupuje do Bét–šemeše a prochází Timnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Dále hranice vybíhá k úbočí Ekrónu na sever. Potom zabočuje k Šikerónu, prochází Baalskou horou, vybíhá k Jabneelu a výběžky hranice dosahují směrem k moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Západní hranice přechází k Velkému moři a další hranici. Toto je hranice synů Judových ze všech stran pro jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'A Kálebovi, synu Jefunovu, dal podíl uprostřed synů Judových podle Hospodinova příkazu k Jozuovi, Kirjat–arbu (město Arby, otce Anákova), což je Chebrón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Káleb odtamtud vyhnal tři syny Anákovy: Šéšaje, Achímana a Talmaje, zplozené Anákem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Vystoupil odtamtud k obyvatelům Debíru -- jméno Debíru bylo předtím Kirjat–sefer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Káleb řekl: Kdo přepadne Kirjat–sefer a dobude ho, tomu dám svou dceru Aksu za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Obsadil ho Otníel, syn ⌈Kenazův, Kálebův bratr.⌉ Dal mu tedy svou dceru Aksu za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'I stalo se, když přišla, že jej navedla, aby žádal od jejího otce pole. Sesedla z osla a Káleb se jí zeptal: ⌈Jaké máš⌉ přání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Nato řekla: Dej mi požehnání, protože ⌈jsi mě provdal do jižní země,⌉ dej mi vodní nádrže. Dal jí tedy horní i dolní nádrže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Toto je dědictví pokolení synů Judových pro jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Města na okraji pokolení synů Judových u edómské hranice na jihu byla: Kabseel, Eder a Jagúr,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kína, Dímóna a Adeáda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedeš, Chasór a Jitnán,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zíf, Telem a Bealót,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Chasór–chadata a Kerijót Chesrón, což je Chasór,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amám, Šema a Mólada,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Chasar–gada, Chešmón a Bét–pelet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Chasar–šúal, Beer–šeba a Bizjótja,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijím a Esem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltólad, Kesíl a Chorma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Siklag, Madmana a Sansana,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaót, Šilchím, Ajin a Rimón; celkem dvacet devět měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'V podhůří: Eštaól, Sorea a Ašna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanóach a Én–ganím, Tapúach a Énam,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmút a Adulám, Sóko a Azeka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Šaarajim a Adítajim, Gedera a Gederótajim; čtrnáct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan, Chadaša a Migdal–gad,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilean, Mispa a Jokteel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakíš, Boskat a Eglón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabón, Lachmas a Kitlíš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederót, Bét–dágón, Naama a Makeda; šestnáct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter a Ašan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiftách, Ašna a Nesíb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Keíla, Akzíb a Maréša; devět měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekrón, jeho vesnice a jeho dvorce;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'od Ekrónu až k moři vše, co leží poblíž Ašdódu, a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Ašdód se svými vesnicemi a jeho dvorce, Gaza se svými vesnicemi a její dvorce až k egyptskému potoku a Velikému moři a k hranici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'V pohoří potom Šamír, Jatír a Sóko,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Dana a Kirjat–sana, což je Debír,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anáb, Eštemo a Aním,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gošen, Cholón a Gílo; jedenáct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Dúma a Ešeán,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janím, Bét–tapúach a Afeka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Chumta, Kirjat–arba, což je Chebrón, a Síor; devět měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maón, Karmel, Zíf a Júta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jizreel, Jokdeám a Zanóach,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajin, Gibea a Timna; deset měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Chalchúl, Bét–súr a Gedór,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarat, Bét–anót a Eltekón; šest měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat–baal, což je Kirjat–jearím, a Raba; dvě města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'V pustině Bét araba, Midín a Sekaka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibšán, Ír–melach a Én–gedí; šest měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Ale jebúsejské obyvatele Jeruzaléma si synové Judovi nebyli schopni podrobit, a tak ⌈Jebúsejci pobývali se syny Judovými v Jeruzalémě až do tohoto dne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Pro syny Josefovy vyšel los od Jordánu u Jericha k jerišským vodám na východě, pustina vystupující od Jericha k bételskému pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Dále vychází z Bét–elu do Lúzu a prochází k arkijské hranici do Atarótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Pak sestupuje na západě k jaflétejské hranici až k hranici Dolního Bét–chorónu a až ke Gezeru a její výběžky dosahují k moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Tak obdrželi dědictví Josefovi synové Manases a Efrajim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Synům Efrajimovým připadlo území pro jejich čeledi. Hranice jejich dědictví došla na východ od Atarót–adaru až k Hornímu Bét–chorónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Hranice vybíhá k moři u Mikmetatu od severu, pak se stáčí na východ k Taanat–šílu a prochází jím od východu k Janóachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Od Janóachu sestupuje k Atarótu a k Naaře, zasahuje do Jericha a vybíhá k Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Od Tapúachu jde hranice na západ k potoku Káně a její výběžky dosahují k moři. Toto je dědictví pokolení synů Efrajimových pro jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Dále ta města, která byla oddělena pro syny Efrajimovy uprostřed dědictví synů Manasesových, všechna města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Nepodrobili si však Kenaance sídlící v Gezeru a ti Kenaanci pobývali uprostřed Efrajima až do tohoto dne a byli přinuceni sloužit na nucených pracích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Padl i los pro Manasesovo pokolení, neboť je Josefův prvorozený: Pro Makíra, Manasesova prvorozeného, Gileádova otce, on byl totiž bojovník. Připadl mu Gileád a Bášan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dostalo se i na zbývající Manasesovy syny a na jejich čeledi: Na syny Abíezerovy, syny Chelekovy, syny Asríelovy, syny Šekemovy, syny Cheferovy a syny Šemídaovy. Toto jsou potomci Manasesa, syna Josefova, mužského pohlaví, podle svých čeledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Avšak Selofchad, syn Chefera, syna Gileáda, syna Makíra, syna Manasesova, neměl syny, nýbrž pouze dcery. Toto jsou jména jeho dcer: Machla a Nóa, Chogla, Milka a Tirsa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Ty přistoupily před kněze Eleazara, před Jozua, syna Núnova, a před předáky se slovy: Hospodin Mojžíšovi přikázal, aby nám dal dědictví mezi našimi bratry. Dal jim tedy podle Hospodinova příkazu dědictví mezi bratry jejich otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Manasesovi pak připadlo deset dílů, mimo gileádskou a bášanskou zemi, která leží na druhé straně Jordánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'protože Manasesovy dcery obdržely dědictví mezi jeho syny a gileádská země připadla zbývajícím Manasesovým synům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Manasesova hranice vedla od ⌈Ašer Mikmetatu,⌉ který leží naproti Šekemu, a postupovala napravo k obyvatelům Én–tapúachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Manasesovi patřilo území Tapúachu, ale Tapúach u Manasesovy hranice patřil synům Efrajimovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Hranice dále sestupuje k potoku Káně. Na jih od potoka mezi městy Manasesovými leží další města a ta patří Efrajimovi. Manasesova hranice vede severně od potoka a svými výběžky dosahuje k moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Na jihu patří Efrajimovi, na severu patří Manasesovi a jeho hranicí je moře. ⌈Do Ašera zasahují od⌉ severu a do Isachara z východu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Manasesovi pak u Isachara a u Ašera patřil Bét–šeán a jeho vesnice, Jibleám a jeho vesnice, obyvatelé Dóru a jeho vesnic, obyvatelé Én–dóru a jeho vesnic, obyvatelé Taanaku a jeho vesnic a obyvatelé Megida a jeho vesnic, ta tři návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Synové Manasesovi si však tato města nebyli schopni podrobit a Kenaanci si ⌈v této zemi⌉ umínili zůstat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Avšak když se stalo, že ⌈se synové Izraele vzmohli a vydali Kenaance na nucené práce, ale úplně si je nepodrobili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Synové Josefovi pak promluvili k Jozuovi: Proč jsi nám dal za dědictví jeden los a jeden díl, když jsme početný lid? Až doposud nám Hospodin takto žehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Jozue jim však odpověděl: Pokud jste početný lid, vytáhněte do lesa a vykácíte si ho pro sebe, tam v zemi Perizejců a Refájců, když je pro vás efrajimské pohoří těsné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Synové Josefovi nato řekli: To pohoří pro nás nebude stačit a v celém kenaanském osídlení v údolní zemi mají železné vozy, ti, kdo jsou v Bét–šeánu a jeho vesnicích, i ti, kdo jsou v údolí Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Jozue odpověděl domu Josefovu, Efrajimovi a Manasesovi: Jsi početný lid a máš velkou sílu; nedostane se ti pouze jeden los.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Vždyť ti bude patřit pohoří. Protože je zalesněné, vykácíš ho a jeho končiny se stanou tvým vlastnictvím, neboť si Kenaance podrobíš, ačkoliv mají železné vozy a i když jsou silní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Pak se shromáždili do Šíla, celá obec synů Izraele, postavili tam stan setkávání a země byla před nimi podmaněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Mezi syny Izraele však zbylo sedm kmenů, kterým nepřidělili jejich dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Tu řekl Jozue synům Izraele: ⌈Jak dlouho⌉ budete otálet, než půjdete obsadit zemi, kterou vám dal Hospodin, Bůh vašich otců?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Určete si tři muže za každý kmen, abych je mohl poslat. Ať povstanou, projdou skrze zemi, sepíšou o ní zápis podle svého dědictví a přijdou ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Pak si ji rozdělí na sedm dílů. Juda zůstane na svém území od jihu a dům Josefův zůstane na svém území od severu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Vy rozepíšete tu zemi na sedm dílů a přinesete zápis sem ke mně. Já pro vás vrhnu los zde před Hospodinem, naším Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Lévijci totiž nemají mezi vámi podíl, protože jeho dědictvím je Hospodinovo kněžství. Gád, Rúben a polovina kmene Manasesova přijali své dědictví na druhé straně Jordánu na východě, které jim dal Mojžíš, otrok Hospodinův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Ti muži povstali a šli. Jozue přikázal těm, kdo odcházeli, aby rozepsali zemi: Jděte, projděte zemí, sepište o ní zápis a vraťte se ke mně. Hodím vám los před Hospodinem tady v Šílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Muži tedy šli, procházeli skrze zemi a rozepsali ji do listiny podle měst po sedmi dílech. Potom přišli k Jozuovi do tábora v Šílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Jozue jim v Šílu hodil los před Hospodinem. Jozue tam synům Izraele rozdělil zemi podle jejich podílů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'I zvedl se los pokolení synů Benjamínových pro jejich čeledi a území jejich losu vyšlo mezi syny Judovými a syny Josefovými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Připadla jim hranice na severní straně od Jordánu; hranice pak stoupá od severu k jerišskému hřebeni, dále do pohoří na západ a její výběžky dosahují k betávenské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Odtud prochází hranice k Lúzu, k úbočí na jih od Lúzu, což je Bét–el; pak sestupuje k Atarót–adaru proti hoře, která je na jih od Dolního Bét–chorónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Hranice dále zabočuje a stáčí se na západní straně k jihu od hory, která je směrem k Bét–chorónu na jih, a její výběžky dosahují ke Kirjat–baalu, což je Kirjat–jearím, město synů Judových. Toto je západní strana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Jižní strana se potom rozkládá od okraje Kirjat–jearímu, hranice vybíhá na západ a dále vybíhá k prameni vod Neftóachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Potom hranice sestupuje k okraji hory, která leží směrem k údolí Hinómova syna, které je v údolí Refájců na severu, pak sestupuje Hinómovým údolím k jebúsejskému hřebeni na jih a sestupuje k Én–rogelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Zabočuje od severu a vybíhá k Én–šemeši, dále vybíhá ke Gelílótu, který je proti Adumímskému svahu, a sestupuje ke kameni Bohana, syna Rúbenova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Prochází k úbočí naproti Arabě na sever a sestupuje do Araby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Potom hranice prochází k úbočí Bét–chogly na sever a výběžky hranice dosahují k severnímu jazyku Solného moře u jordánského břehu na jihu. Toto je jižní hranice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'A Jordán jej ohraničuje na východní straně. Toto je dědictví synů Benjamínových pro jejich čeledi podle svých hranic kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Pokolení synů Benjamínových a jejich čeledím pak připadla města: Jericho, Bét–chogla a Emek–kesis,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bét–araba, Semárajim a Bét–el,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avím, Para a Ofra,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefar–amóní, Ofní a Geba; dvanáct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeón, Ráma a Beerót,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mispa, Kefíra a Mósa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel a Tarala,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Sela–elef, Jebús, což je Jeruzalém, Gibea a Kirjat; čtrnáct měst a jejich dvorce. Toto je dědictví synů Benjamínových pro jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'I vyšel druhý los pro Šimeóna, pro pokolení synů Šimeónových a jejich čeledi. Dostalo se jim dědictví uprostřed dědictví synů Judových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Připadla jim do dědictví Beer–šeba, Šeba a Mólada,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Chasar–šúal, Bála a Esem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltólad, Betúl a Chorma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Siklag, Bét–markabót a Chasar–súsa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Bét–lebaót a Šarúchen; třináct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ajin, Rimón, Eter a Ašan; čtyři města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'A všechny dvorce, které jsou kolem těchto měst až po Baalat–beer a Ramat–negeb. Toto je dědictví pokolení synů Šimeónových pro jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Dědictví synů Šimeónových bylo vzato z dílu synů Judových. Jelikož podíl synů Judových byl pro ně velký, synové Šimeónovi obdrželi dědictví uprostřed jejich dědičného podílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'I byl vytažen třetí los pro syny Zabulónovy a jejich čeledi. Hranice jejich dědictví dosahovala až k Sarídu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Jejich hranice stoupá na západ k Mareále, zasahuje do Dabešetu a k potoku, který je naproti Jokneámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Pak se od Sarídu vrací přímo k východu slunce na území Kislót–táboru, vybíhá k Daberatu a stoupá k Jafíe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Odtud prochází přímo na východ do Gat–chéferu a Et–kasínu a vybíhá k Rimónu se zabočením k Néji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Dále se hranice stáčí od severu k Chanatónu a její výběžky dosahují do údolí Jiftach–elu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Zahrnuje i Katat, Nahalal, Šimrón, Jidalu a Bét–lechem; dvanáct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Toto je dědictví synů Zabulónových pro jejich čeledi: Tato města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Pro Isachara vyšel čtvrtý los, pro syny Isacharovy a jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Jejich hranice dosahovala do Jizreelu a zahrnovala Kesulót a Šúnem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Chafarajim, Šíon a Anacharat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabít, Kišjón a Ebes,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remet, Én–ganím, Én–chada a Bét–pases.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Hranice zasahuje do Tábora, Šachasímu a Bét–šemeše a výběžky jejich hranice dosahují k Jordánu; šestnáct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Toto je dědictví pokolení synů Isacharových pro jejich čeledi: Města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'I vyšel pátý los pro pokolení synů Ašerových a jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Jejich hranicí byl: Chelkat a Chalí, Beten a Akšáf,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alamelek, Ameád a Mišál. Hranice zasahuje do Karmelu na západ a do Šíchor–libnátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Pak se obrací na východ slunce k Bét–dágonu, zasahuje do Zabulóna a do údolí Jiftach–elu na sever, Bét Emeku a Neíelu a vybíhá zleva ke Kabúlu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebrónu, Rechóbu, Chamónu a Káně až k velkému Sidónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Hranice se opět obrací k Rámě a až k opevněnému městu Týru, potom se hranice obrací k Chose a její výběžky dosahují k moři od Chebelu do Akzíbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Dále Uma, Afek a Rechób; dvacet dva měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Toto je dědictví pokolení synů Ašerových pro jejich čeledi: Tato města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Pro syny Neftalího vyšel šestý los, pro syny Neftalího a jejich čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Jejich hranice vede z Chelefu, od dubu v Saananímu, dále přes Adamí–nekeb a Jabneel až k Lakúmu a svými výběžky dosahuje k Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Pak se hranice obrací na západ k Aznót–táboru, vychází odtud k Chukóku a zasahuje do Zabulóna od jihu, do Ašera zasahuje od západu a do Judy u Jordánu na východu slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Zahrnuje i opevněná města: Sidím, Ser a Chamát, Rakat a Kineret,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adamu, Rámu a Chasór,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedeš, Edreí a Én–chasór,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jirón a Migdal–el, Chorem, Bét–anat a Bét–šemeš; devatenáct měst a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Toto je dědictví pokolení synů Neftalího pro jejich čeledi: Města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Pro pokolení synů Danových a pro jejich čeledi vyšel sedmý los.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Hranicí jejich dědictví byla: Sorea, Eštaól a Ír–šemeš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Šaalabín, Ajalón a Jitla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elón, Timna a Ekrón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibetón a Baalat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehúd, Bené–berak a Gat–rimón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'dále vody Jarkónu a Rakónu s územím směrem k Jafě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, '⌈Synové Danovi však přišli o své území.⌉ Synové Danovi tedy vytáhli, bojovali s Lešemem, dobyli jej a vybili ho ostřím meče, obsadili ho, usadili se v něm a nazvali Lešem jménem Dan podle jména Dana, svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Toto je dědictví pokolení synů Danových pro jejich čeledi: Tato města a jejich dvorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'A dokončili přidělování země do dědictví podle jejích hranic. Jozuovi, synu Núnovu, dali synové Izraele dědictví mezi sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Na příkaz Hospodinův mu dali město, o které požádal: Timnat–serach v efrajimském pohoří. Vystavěl to město a usadil se v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Toto jsou dědičné podíly, které kněz Eleazar, Jozue, syn Núnův, a předáci rodů pokolením synů Izraele přidělili losem v Šílu před Hospodinem u vchodu do stanu setkávání. Tak dokončili dělení země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'I promluvil Hospodin k Jozuovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Promluv k synům Izraele takto: Ustanovte pro sebe útočištná města, o kterých jsem s vámi mluvil prostřednictvím Mojžíše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'aby tam utekl ⌈vrah, který zabije člověka nedopatřením, neúmyslně.⌉ Budou vám útočištěm před ⌈krevním mstitelem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Vrah uteče do jednoho z těchto měst, postaví se u vchodu do městské brány a přednese starším onoho města své záležitosti. Poté jej vezmou do města k sobě, poskytnou mu místo a bude pobývat s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'A když ho bude pronásledovat krevní mstitel, nevydají toho vraha do jeho ruky, protože svého bližního zabil neúmyslně, aniž by ho někdy dříve nenáviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'V onom městě bude bydlet, dokud se nepostaví před shromáždění k soudu, až do smrti velekněze, který bude v oněch dnech. Tehdy se vrah navrátí a přijde do svého města a do svého domu, do města, odkud utekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Tak posvětili Kedeš v Galileji v pohoří neftalíjském, Šekem v pohoří efrajimském a Kirjat–arbu, což je Chebrón, v pohoří judském.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'A na druhé straně Jordánu na východ od Jericha přidělili Beser v pustině na rovině od pokolení Rúbenova, Rámot v Gileádu od pokolení Gádova a Gólan v Bášanu od pokolení Manasesova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Toto byla města určená pro všechny syny Izraele i pro příchozího, pobývajícího mezi nimi jako cizinec, aby tam mohl utéci každý, kdo nedopatřením zabil člověka. Nezemře rukou krevního mstitele, dokud se nepostaví před shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Předáci lévijských rodů přistoupili ke knězi Eleazarovi, k Jozuovi, synu Núnovu, a k předákům rodů pokolení synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'A promluvili k nim v Šílu v kenaanské zemi: ⌈Hospodin přikázal prostřednictvím Mojžíše,⌉ aby nám byla dána města k bydlení a jejich pastviny pro náš dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Synové Izraele tedy dali Lévijcům ze svého dědictví podle Hospodinova příkazu tato města a jejich pastviny:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Los vyšel čeledím Kehatovců. Synům kněze Árona se dostalo mezi Lévijci pomocí losu třináct měst od pokolení Judova, od pokolení Šimeónova a od pokolení Benjamínova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'A zbývajícím synům Kehatovým pomocí losu deset měst od čeledí pokolení Efrajimova, od pokolení Danova a od poloviny pokolení Manasesova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Synům Geršónovým pomocí losu třináct měst od čeledí pokolení Isacharova, od pokolení Ašerova, od pokolení Neftalího a od poloviny pokolení Manasesova v Bášanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Synům Merarího pro jejich čeledi dvanáct měst od pokolení Rúbenova, od pokolení Gádova a od pokolení Zabulónova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Synové Izraelovi přidělili Lévijcům tato města a jejich pastviny pomocí losu, jak to přikázal Hospodin prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Od pokolení synů Judových a od pokolení synů Šimeónových jim přidělili tato města, která budou jmenovitě vyhlášena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Dostala se synům Áronovým z čeledí Kehatovců ze synů Léviho, protože jim padl los nejdříve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Dali jim Kirjat–arbu, město otce Anákova, což je Chebrón, v judském pohoří a jeho pastviny okolo něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Pole toho města a jeho dvorce však dali Kálebovi, synu Jefunovu, do jeho vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Synům kněze Árona dali jako útočištné město pro vraha Chebrón a jeho pastviny, Libnu a její pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jatír a jeho pastviny, Eštemóu a její pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Cholón a jeho pastviny, Debír a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ajin a jeho pastviny, Jutu a její pastviny a Bét–šemeš a jeho pastviny; devět měst od těchto dvou kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Dále od pokolení Benjamínova: Gibeón a jeho pastviny, Gebu a její pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatót a jeho pastviny a Almón a jeho pastviny; čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Všechna města kněží, synů Áronových: Třináct měst a jejich pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Čeledím synů Kehatových, Lévijcům zbývajícím ze synů Kehatových, pak připadla města jejich losu od pokolení Efrajimova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Dali jim jako útočištné město pro vraha Šekem a jeho pastviny v efrajimském pohoří, Gezer a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibsajim a jeho pastviny a Bét–chorón a jeho pastviny; čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Dále od pokolení Danova: Elteke a jeho pastviny, Gibetón a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalón a jeho pastviny a Gat–rimón a jeho pastviny; čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Od poloviny pokolení Manasesova: Taanak a jeho pastviny a Gat–rimón a jeho pastviny; dvě města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Všechna města pro čeledi zbývajících synů Kehatových: Deset a jejich pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Synům Geršónovým z lévijských čeledí od poloviny pokolení Manasesova: Jako útočištné město pro vraha Gólan v Bášanu a jeho pastviny a Beešteru a její pastviny; dvě města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Dále od pokolení Isacharova: Kišjón a jeho pastviny, Daberat a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmút a jeho pastviny a Én–ganím a jeho pastviny; čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Dále od pokolení Ašerova: Mišál a jeho pastviny, Abdón a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Chelkat a jeho pastviny a Rechób a jeho pastviny; čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Dále od pokolení Neftalího: Jako útočištné město pro vraha Kedeš v Galileji a jeho pastviny, Chamót–dór a jeho pastviny a Kartan a jeho pastviny; tři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Všechna města Geršónovců pro jejich čeledi: Třináct měst a jejich pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Čeledím synů Merarího, zbývajícím Lévijcům od pokolení Zabulónova: Jokneám a jeho pastviny, Kartu a její pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimnu a její pastviny a Nahalal a jeho pastviny; čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Dále od pokolení Rúbenova: Beser a jeho pastviny, Jahas a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemót a jeho pastviny a Méfaat a jeho pastviny; čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Od pokolení Gádova: Jako útočištné město pro vraha Rámot v Gileádu a jeho pastviny, Machanajim a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Chešbón a jeho pastviny a Jaezer a jeho pastviny; celkem čtyři města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Všechna města pro syny Merarího, pro jejich čeledi zbývající z lévijských čeledí: Připadlo jim losem dvanáct měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Všech lévijských měst uprostřed vlastnictví synů Izraele: Čtyřicet osm měst a jejich pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Tato města budou město jako město a jeho pastviny okolo něho. Tak je tomu se všemi těmito městy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Hospodin tedy dal Izraeli veškerou zemi, o níž přísahal, že ji dá jejich otcům. Obsadili ji a usadili se v ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'A Hospodin jim dal odpočinek od jejich okolí podle všeho, o čem přísahal jejich otcům. Nepostavil se proti nim nikdo ze všech jejich nepřátel. Všechny jejich nepřátele jim Hospodin vydal do ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Nezapadlo nic ze žádného dobrého slova, které promluvil Hospodin k domu izraelskému. Všechno se to naplnilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Tehdy Jozue svolal Rúbenovce, Gádovce a polovinu pokolení Manasesova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Řekl jim: Vy jste zachovávali vše, co vám přikázal Mojžíš, otrok Hospodinův, a uposlechli jste mne ve všem, co jsem vám přikázal já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Neopustili jste své bratry po tyto mnohé dny až dodnes, ale dbali jste na dodržování příkazu Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Nyní dal Hospodin, váš Bůh, odpočinek vašim bratrům, jak to o nich prohlásil. Teď se tedy obraťte a jděte do svých stanů, do země svého vlastnictví, kterou vám dal Mojžíš, otrok Hospodinův, na druhé straně Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Pouze velmi dbejte, abyste konali příkaz a zákon, který vám dal Mojžíš, otrok Hospodinův, abyste milovali Hospodina, svého Boha, a chodili po všech jeho cestách a abyste zachovávali jeho příkazy, přilnuli k němu a sloužili mu celým svým srdcem a celou svou duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Pak jim Jozue požehnal, propustil je a oni odešli ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Polovině kmene Manasesova dal tedy Mojžíš území v Bášanu a jeho druhé polovině dal Jozue spolu s jejich bratry území na druhé straně Jordánu směrem na západ. Pak také, když je Jozue propustil k jejich stanům, požehnal jim');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'a řekl jim: S mnohými poklady se navraťte ke svým stanům, s velkým množstvím dobytka, se stříbrem, se zlatem, s bronzem, se železem a s velkým množstvím plášťů, rozdělte si kořist po svých nepřátelích se svými bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Nato se obrátili synové Rúbenovi, synové Gádovi a polovina kmene Manasesova a odešli od synů Izraele ze Šíla, které je v zemi kenaanské, aby šli do země Gileádu, do země svého vlastnictví, v níž se uchytili na Hospodinův příkaz vydaný prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Když přišli k jordánským krajům, které leží v kenaanské zemi, postavili tam synové Rúbenovi, synové Gádovi a polovina kmene Manasesova nad Jordánem oltář, oltář velký na pohled.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Tu se synové Izraele doslechli: Hle, synové Rúbenovi, synové Gádovi a polovina kmene Manasesova postavili oltář směrem ke kenaanské zemi, k jordánským krajům, k protilehlé straně území synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Synové Izraele se to doslechli a shromáždili se, celá obec synů Izraele, do Šíla, aby na ně vytáhli s armádou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'I poslali synové Izraele k synům Rúbenovým, k synům Gádovým a k polovině kmene Manasesova do země Gileádu Pinchasa, syna kněze Eleazara');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'a s ním deset předáků, jeden předák za každý otcovský dům, za všechna pokolení Izraele. Byli každý hlavou svého otcovského domu pro izraelské rody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Přišli k synům Rúbenovým, k synům Gádovým a k polovině kmene Manasesova do země Gileádu a takto s nimi promluvili:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Toto prohlásili všichni, celá Hospodinova pospolitost: Co je tohle za věrolomnost, kterou jste se zpronevěřili Bohu Izraele, abyste se dnes odvrátili od Hospodina, když jste pro sebe zbudovali oltář, abyste se dnes vzbouřili proti Hospodinu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Cožpak je pro nás málo mít Peórovu zvrácenost, od které jsme nebyli očištěni až do tohoto dne a pro níž se stala pohroma v Hospodinově obci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'A vy se dnes odvrátíte od Hospodina! Stane se, že vy se dnes vzbouříte proti Hospodinu a zítra se on rozhněvá na celou izraelskou obec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Jestliže je ovšem země vašeho vlastnictví nečistá, přejděte si do země vlastnictví Hospodinova, kde se usídlil příbytek Hospodinův, a uchyťte se mezi námi. Ale nebuřte se proti Hospodinu a nepobuřujte nás tím, že pro sebe stavíte oltář mimo oltář Hospodina, našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Cožpak se Akán, syn Zerachův, nezpronevěřil věrolomností při klatbě a na celou izraelskou obec ne dopadlo ⌈rozhořčení a ten muž sám nevydechl ⌈kvůli své zvrácenosti⌉ naposled?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Nato synové Rúbenovi, synové Gádovi a polovina kmene Manasesova odpověděli. Promluvili s předáky izraelských rodů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Bůh Bohů Hospodin, Bůh Bohů Hospodin to ví a Izrael ať to pozná: Jestliže jsme ve vzpouře nebo ve věrolomnosti proti Hospodinu, nezachraňuj nás tohoto dne,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'abychom pro sebe stavěli oltář a odvrátili se od Hospodina. A jestliže jsme to udělali, abychom na něm přinášeli zápalnou a přídavnou oběť, anebo abychom na něm konali obětní hody pohostinných obětí, to ať Hospodin sám posoudí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Zdalipak jsme však toto neučinili v obavě z toho, že zítra řeknou vaši synové našim synům: Co je vám do Hospodina, Boha Izraele?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Hospodin ustanovil Jordán jako hranici mezi námi a mezi vámi, synové Rúbenovi a synové Gádovi; vy nemáte podíl v Hospodinu. A tak odradí vaši synové naše syny, aby se nebáli Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'I řekli jsme si: Učiňme nyní pro sebe to, že vybudujeme oltář, ne pro zápalnou oběť ani pro obětní hod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Neboť bude svědkem mezi námi a vámi a mezi našimi pokoleními po nás, abychom konali službu Hospodinu před jeho obličejem svými zápalnými oběťmi, obětními hody a svými pohostinnými oběťmi. A vaši synové neřeknou zítra našim synům: Vy nemáte podíl v Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Řekli jsme si: Když se stane, že to zítra povědí nám a našim pokolením, odpovíme: Podívejte se na napodobeninu Hospodinova oltáře, kterou zhotovili naši otcové ne pro zápalnou oběť ani pro obětní hod, neboť je svědkem mezi námi a vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Ať je to od nás vzdáleno, že by se někdo z nás vzbouřil proti Hospodinu a odvrátil se dnes od Hospodina, aby stavěl oltář pro zápalnou oběť, pro přídavnou oběť a pro obětní hod mimo oltář Hospodina, našeho Boha, který je před jeho příbytkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'I vyslechl kněz Pinchas, předáci obce a vůdcové izraelských rodů, kteří byli s ním, slova, která promluvili synové Rúbenovi, synové Gádovi a synové Manasesovi, a v jejich očích to bylo dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Tu řekl ⌈Pinchas, syn kněze Eleazara,⌉ synům Rúbenovým, synům Gádovým a synům Manasesovým: Dnes jsme poznali, že Hospodin je mezi námi. Když jste se nezpronevěřili Hospodinu touto věrolomností, tehdy jste vysvobodili syny Izraele z Hospodinovy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Potom se vrátil Pinchas, syn kněze Eleazara, a předáci od synů Rúbenových a od synů Gádových ze země Gileádu do země kenaanské k synům Izraele a donesli jim zpět zprávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Ta zpráva byla dobrá v očích synů Izraele a synové Izraele dobrořečili Bohu. Neříkali už, že na ně vytáhnou s armádou, aby zničili zemi, ve které synové Rúbenovi a synové Gádovi pobývají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Synové Rúbenovi a synové Gádovi pak oltář pojmenovali, protože je svědkem mezi námi, že Hospodin je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'I stalo se po mnoha dnech poté, co dal Hospodin Izraeli odpočinek od všech jejich okolních nepřátel, že Jozue ⌈zestárl a dosáhl pokročilého věku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Tehdy Jozue svolal celý Izrael, jeho starší, jeho předáky, jeho soudce a jeho správce a řekl jim: Já jsem zestárl a dosáhl jsem pokročilého věku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'A vy jste viděli všechno, co učinil Hospodin, váš Bůh, se všemi těmito národy před vámi, neboť Hospodin, váš Bůh, bojoval za vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Pohleďte, ⌈předal jsem⌉ vám tyto zbylé národy do dědictví pro vaše kmeny od Jordánu a všechny národy, které jsem vyhladil, až k Velikému moři na západ slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'A Hospodin, váš Bůh, on je od vás vypudí, vyžene je před vámi a obsadíte jejich zemi, jak to Hospodin, váš Bůh, o vás prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Velmi se posilněte, abyste zachovávali a konali všechno, co je zapsáno v knize Mojžíšova zákona, abyste se od něj neodvrátili napravo ani nalevo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'abyste ⌈se nesměšovali s těmito zbylými národy.⌉ Nebudete připomínat jméno jejich bohů, ⌈nenecháte v něm přísahat,⌉ nebudete jim sloužit a nebudete se ⌈jim klanět.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Neboť jestliže přilnete k Hospodinu, svému Bohu, jak jste to činili až do tohoto dne');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'a Hospodin vám podrobil ⌈velké a mocné národy⌉, a pokud jde o vás, nikdo před vámi až do tohoto dne neobstál,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'tak jeden muž z vás bude pronásledovat tisíc, protože Hospodin, váš Bůh, on bojuje za vás, jak to o vás prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, '⌈Budete se tedy mít kvůli svému životu velmi na pozoru,⌉ abyste milovali Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Neboť jestliže se opravdu odvrátíte a přilnete ke zbytku těchto národů, těch, kteří zůstali s vámi, spřízníte se s nimi a vejdete k nim a oni k vám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'jistě poznáte, že Hospodin, váš Bůh, nebude pokračovat v tom, aby tyto národy před vámi podrobil, a budou pro vás pastí a léčkou, bičem na vašich bocích a trny ve vašich očích, dokud se neztratíte z této dobré země, kterou vám dal Hospodin, váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Hle, já dnes odcházím cestou všeho pozemského. Poznáte celým svým srdcem a celou svou duší, že nezapadlo jediné ze všech těch dobrých slov, která o vás prohlásil Hospodin, váš Bůh; všechna se při vás naplnila, nezapadlo z toho jediné slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'A stane se, že tak jako se při vás naplnilo každé dobré slovo, které o vás prohlásil Hospodin, váš Bůh, tak při vás Hospodin naplní každé zlé slovo, dokud vás nevyhladí z této dobré země, kterou vám Hospodin, váš Bůh, dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Když budete přestupovat smlouvu Hospodina, svého Boha, kterou vám přikázal, a půjdete, budete sloužit jiným bohům a budete se jim klanět, tehdy proti vám vzplane Hospodinův hněv a rychle zmizíte z dobré země, kterou vám dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Jozue pak shromáždil všechny izraelské kmeny do Šekemu a svolal starší Izraele, jeho předáky, jeho soudce a jeho správce a oni se postavili před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Jozue řekl všemu lidu: Toto praví Hospodin, Bůh Izraele: Vaši otcové pobývali odedávna na druhé straně řeky Eufratu -- Terach, otec Abrahamův a otec Náchorův -- a sloužili jiným bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Vzal jsem vašeho otce Abrahama z druhé strany řeky a provedl jsem jej celou kenaanskou zemí, rozmnožil jsem jeho potomstvo a dal jsem mu Izáka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Izákovi jsem dal Jákoba a Ezaua. Ezauovi jsem dal pohoří Seír, aby je obsadil. Jákob a jeho synové sestoupili do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Poslal jsem Mojžíše a Árona, porazil jsem Egypt tím, co jsem učinil uprostřed něj, a potom jsem vás vyvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Když jsem vyvedl vaše otce z Egypta, přišli jste k moři a Egypťané vaše otce pronásledovali s vozbou a na koních k Rákosovému moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Když křičeli k Hospodinu, položil mezi tebe a Egypťany temnotu, přivedl na ně moře a přikryl je. Vaše oči viděly, co jsem učinil v Egyptě, a mnoho dnů jste pobývali v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Pak jsem vás přivedl do země Emorejců, kteří sídlí na druhé straně Jordánu, bojovali s vámi a vydal jsem vám je do ruky, obsadili jste jejich zemi a vyhladil jsem je před vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Potom povstal ⌈moábský král Balák, syn Sipórův,⌉ bojoval proti Izraeli, poslal pro Bileáma, syna Beórova, a povolal ho, aby vás proklel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Nechtěl jsem však Bileáma slyšet, a tak vám stále žehnal a já jsem vás vysvobodil z jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Pak jste přešli Jordán a přišli jste k Jerichu. Bojovali proti vám emorejští, perizejští, kenaanští, chetejští, girgašejští, chivejští a jebúsejští občané Jericha a já jsem vám je vydal do ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Poslal jsem před vámi děs a vyhnal je před vámi, dva emorejské krále, nikoli vaším mečem ani vaším lukem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Dal jsem vám zemi, ve které ses nenamáhal a města, která jste nestavěli, a usadili jste se v nich. Jíte z vinic a olivových hájů, které jste nesázeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Nuže, bojte se Hospodina a služte mu bezúhonně a věrně. Odstraňte bohy, kterým sloužili vaši otcové za řekou a v Egyptě, a služte Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Jestliže je však ve vašich očích nežádoucí, abyste sloužili Hospodinu, vyberte si dnes, komu budete sloužit: Zda bohům, kterým sloužili vaši otcové, když byli za řekou, nebo zda bohům Emorejců, když sídlíte v jejich zemi. Já a můj dům budeme sloužit Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Nato lid odpověděl. Řekl: Ať je to od nás vzdáleno, že bychom opustili Hospodina, abychom sloužili jiným bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Vždyť Hospodin, náš Bůh, je ten, kdo vyvedl nás a naše otce z egyptské země, z domu otroctví, a který učinil před našima očima tato velká znamení a zachoval nás na celé cestě, po které jsme šli, a mezi všemi národy, uprostřed nichž jsme procházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Hospodin od nás vyhnal všechny ty národy a ⌈emorejského obyvatele⌉ té země. Také my budeme sloužit Hospodinu, protože on je náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Tu řekl Jozue lidu: Nebudete schopni sloužit Hospodinu, protože on je svatý Bůh. On je žárlivý Bůh, nesnese vaše přestoupení a vaše hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Když opustíte Hospodina a budete sloužit cizím bohům, odvrátí se a zle s vámi naloží, skoncuje s vámi i poté, co vám prokazoval dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Ale lid řekl Jozuovi: Nikoli, vždyť budeme sloužit Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Jozue tedy řekl lidu: Jste svědky sami proti sobě, že vy jste si vybrali Hospodina, abyste mu sloužili. Oni řekli: Jsme svědky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Nuže, odstraňte cizí bohy, které máte mezi sebou, a nakloňte své srdce k Hospodinu, Bohu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'A lid Jozuovi řekl: Hospodinu, svému Bohu, budeme sloužit a jeho hlas budeme poslouchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Jozue v onen den uzavřel s lidem smlouvu a předložil mu v Šekemu ⌈ustanovení a právní⌉ nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Jozue pak zapsal tato slova do knihy Božího zákona, vzal velký kámen a postavil ho tam pod terebint, který stojí v Hospodinově svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Nato Jozue řekl všemu lidu: Hle, tento kámen bude mezi námi na svědectví, protože on slyšel všechny řeči, které s námi Hospodin mluvil. Bude mezi vámi na svědectví, ať nelžete proti svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Potom Jozue lid propustil, každého k jeho dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'I stalo se po těchto událostech, že Jozue, syn Núnův, otrok Hospodinův, zemřel ve věku sto deseti let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'A pohřbili ho na území jeho dědictví v Timnat–serachu, který je v efrajimském pohoří severně od hory Gaaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Izrael sloužil Hospodinu po všechny Jozuovy dny a po všechny dny starších, kteří ⌈Jozua přežili⌉ a kteří znali celé Hospodinovo dílo, jež vykonal pro Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Josefovy kosti, které vynesli synové Izraele z Egypta, pohřbili v Šekemu na dílu pole, který koupil Jákob od synů Chamóra, otce Šekemova, za sto kesít, a dostaly se synům Josefovým do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Zemřel i Eleazar, syn Áronův, a pohřbili jej na návrší jeho syna Pinchasa, které mu bylo dáno v efrajimském pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'I stalo se po smrti Jozua, že se synové Izraele doptávali Hospodina: Kdo z nás vytáhne proti Kenaancům ⌈jako první,⌉ aby s nimi vedl válku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'A Hospodin odpověděl: Vytáhne Juda. Hle, vydal jsem tu zemi do jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Juda řekl svému bratru Šimeónovi: Vytáhni se mnou do území mého losu a bojujme proti Kenaancům. A já s tebou také půjdu do území tvého losu. Šimeón šel tedy s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Juda vytáhl a Hospodin vydal Kenaance a Perizejce do jejich rukou. Pobili je v Bezeku, deset tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Přitom nalezli v Bezeku Adoní–bezeka, bojovali proti němu a pobili Kenaance a Perizejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Adoní–bezek však utekl a oni jej pronásledovali. Chytili ho a usekli mu palce na rukou i na nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Adoní–bezek nato řekl: Sedmdesát králů s useknutými palci na rukou a na nohou sbírávalo pod mým stolem. Jak jsem jednal já, tak mi Bůh odplatil. Přivedli ho do Jeruzaléma a tam zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Synové Judovi bojovali proti Jeruzalému, dobyli jej, vybili ho ostřím meče a město podpálili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Potom synové Judovi sestoupili do boje s Kenaanci sídlícími na pohoří, v Negebu a v Šefele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Tak táhl Juda proti Kenaancům, sídlícím v Chebrónu (jméno Chebrónu bylo předtím Kirjat–arba) a pobili Šéšaje, Achímana a Talmaje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Odtud táhl proti obyvatelům Debíru (jméno Debíru bylo předtím Kirjat–sefer).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Tehdy řekl Káleb: Kdo přepadne Kirjat–sefer a dobude ho, tomu dám svou dceru Aksu, za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Dobyl ho Otníel, syn ⌈Kenazův, mladší bratr Káleba,⌉ a on mu dal svou dceru Aksu za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'I stalo se, když přišla, že jej navedla, aby žádal od jejího otce pole. Sesedla z osla a Káleb se jí zeptal: ⌈Jaké máš⌉ přání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Odpověděla mu: Dej mi požehnání, protože ⌈jsi mě provdal do jižní země,⌉ dej mi vodní nádrže. Káleb jí tedy dal horní i dolní nádrže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Synové Kénijce, Mojžíšova tchána, vytáhli z Ír–hatmarímu se syny Judovými do judské pustiny, která je ⌈na jih od Aradu,⌉ putovali a usadili se s tím lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'A Juda šel se svým bratrem Šimeónem, pobili Kenaance sídlící v Sefatu a zasvětili je zkáze. Potom nazvali to město jménem Chorma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Juda také dobyl Gazu a její území, Aškalón a jeho území a Ekrón a jeho území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Hospodin byl s Judou a ten si podrobil pohoří. Ale ne byl schopen podrobit si obyvatele údolí, protože měli železné vozy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Kálebovi dali Chebrón, jak to Mojžíš vyhlásil, a on odtamtud vyhnal tři syny Anákovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Avšak Jebúsejce, obyvatele Jeruzaléma, si synové Benjamínovi nepodrobili a Jebúsejci pobývali se syny Benjamínovými v Jeruzalémě až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Také dům Josefův vystoupil k Bét–elu a Hospodin byl s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Dům Josefův pak ⌈provedl v Bét–elu průzkum;⌉ jméno toho města bylo předtím Lúz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Průzkumníci viděli muže vycházejícího z města a řekli mu: Ukaž nám teď průchod do města a my ti prokážeme milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Ukázal jim tedy průchod do města. Oni to město vybili ostřím meče, ale toho muže a celou jeho rodinu propustili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'A ten muž šel do chetejské země, vystavěl město a nazval je jménem Lúz. To je jeho jméno až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manases si však nepodrobil Bét–šeán a jeho vesnice, Taanak a jeho vesnice, obyvatele Dóru a jeho vesnic, obyvatele Jibleámu a jeho vesnic a obyvatele Megida a jeho vesnic. Kenaanci si tedy umínili v této zemi zůstat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'I stalo se, když se Izrael vzmohl, že uložil Kenaancům nucené práce, ale úplně si je nepodrobil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Ani Efrajim si nepodrobil Kenaance, sídlící v Gezeru a Kenaanci pobývali uprostřed něj v Gezeru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulón si nepodrobil obyvatele Kitrónu a obyvatele Nahalólu. Kenaanci pobývali uprostřed nich a byli vydáni na nucené práce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Ašer si nepodrobil obyvatele Aka, obyvatele Sidónu, Achlábu, Akzíbu, Chelby, Afíku a Rechóbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Ášerovci tak sídlili uprostřed Kenaanců usazených v zemi, protože si je nepodrobili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Neftalí si nepodrobil obyvatele Bét–šemeše a obyvatele Bét–anatu a pobýval mezi Kenaanci usazenými v té zemi. Obyvatelé Bét–šemeše a Bét–anatu jim byli vydáni na nucené práce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Emorejci zatlačili syny Danovy do pohoří, neboť jim nedovolili sestupovat do údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Emorejci si tedy umínili zůstat v Har–cheresu, v Ajalónu a v Šaalbímu. Těžce na ně dolehla ruka domu Josefova a byli vydáni na nucené práce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Emorejská hranice vedla od ⌈průsmyku Akrabim,⌉ od Sély až nahoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Hospodinův anděl pak vystoupil z Gilgálu do Bokímu a řekl: Vyvedl jsem vás z Egypta a přivedl jsem vás do země, o které jsem přísahal vašim otcům a řekl jsem: Navěky nezruším svou smlouvu s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Vy naopak neuzavřete smlouvu s obyvateli této země. Jejich oltáře strhnete. Ale neuposlechli jste mě. Co jste to provedli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, '⌈Však jsem také řekl:⌉ Nevyženu je před vámi. Budou vám ostnem v boku a jejich bohové budou pro vás léčkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'I stalo se, když Hospodinův anděl mluvil tato slova ke všem synům Izraele, že lid pozvedl hlas a rozplakal se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'A nazvali ono místo jménem Bokím a obětovali tam Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Když Jozue propustil lid, synové Izraele odešli každý do svého dědictví, aby ⌈tu zemi obsadili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Lid sloužil Hospodinu po všechny Jozuovy dny a všechny dny starších, kteří ⌈Jozua přežili⌉ a kteří spatřili celé to velké Hospodinovo dílo, jež vykonal pro Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Jozue, syn Núnův, otrok Hospodinův, zemřel ve věku sto deseti let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Pohřbili ho na území jeho dědictví v Timnat–cheresu, v efrajimském pohoří severně od hory Gaaš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'A také celá ona generace byla připojena ke svým otcům. Po nich potom povstala jiná generace, která neznala Hospodina ani dílo, jež pro Izrael vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Synové Izraele páchali to, co je ⌈zlé v Hospodinových očích,⌉ a sloužili baalům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Opustili Hospodina, Boha svých otců, který je vyvedl z egyptské země, a chodili za jinými bohy z bohů těch národů, které byly okolo nich, ⌈klaněli se jim⌉ a provokovali Hospodina ke hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Opustili Hospodina a sloužili Baalovi a Aštoretě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on je vydal do ruky pustošitelů, kteří je plenili. Vydal je do ruky jejich okolním nepřátelům a nemohli už před svými nepřáteli obstát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Všude, kam vytáhli, byla ⌈Hospodinova ruka proti nim⌉ ke zlému, jak to Hospodin prohlásil a jak jim to Hospodin odpřisáhl. Bylo jim velmi úzko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Hospodin tedy dával povstat soudcům a ti je zachraňovali z ruky jejich pustošitelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Ale ani své soudce neposlouchali, protože chodili smilnit za jinými bohy a klaněli se jim. Odvrátili se rychle od té cesty, po níž chodili jejich otcové v poslušnosti Hospodinových příkazů. Oni tak nejednali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'A když Hospodin dával kvůli nim povstat soudcům, ⌈byl Hospodin s tím⌉ soudcem a zachraňoval je z ruky jejich nepřátel po všechny dny toho soudce, neboť Hospodin se slitovával kvůli jejich sténání před jejich utiskovateli a poháněči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Když však soudce zemřel, stalo se, že se navrátili zpět a ⌈vrhali se do zkázy⌉ více než jejich otcové, chodili za jinými bohy, sloužili jim a klaněli se jim. Nevzdali se svých činů ani svých zatvrzelých cest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on řekl: Kvůli tomu, že tento národ přestoupil mou smlouvu, kterou jsem dal jejich otcům, a neposlechli mě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'ani já je už nenechám podrobit si nikoho z národů, které Jozue zanechal, než zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'To abych jejich prostřednictvím Izrael zkoušel, zda budou zachovávat Hospodinovu cestu, aby po ní chodili, jak to zachovávali jejich otcové, nebo ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Tak Hospodin ponechal tyto národy, aniž by si je rychle podrobili, ani je ne vydal do Jozuovy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'A toto jsou národy, které Hospodin ponechal, aby jejich prostřednictvím zkoušel Izrael, všechny, kteří nepoznali žádné boje o Kenaan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'aby generace synů Izraele poznaly aspoň pro své poučení, co je válka, aspoň ti, kteří ji předtím nepoznali:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Pět pelištejských vladařů a všechny Kenaance, Sidónce a Chivejce sídlící na libanonském pohoří od hory Baal–chermón až k Lebo–Chamátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Zůstali, aby byl skrze ně Izrael zkoušen, aby se poznalo, budou–li poslouchat Hospodinovy příkazy, které dal jejich otcům ⌈prostřednictvím Mojžíše.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'A synové Izraele bydleli uprostřed ⌈Kenaanců, Chetejců a Emorejců, Perizejců, Chivejců a Jebúsejců.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Brali si jejich dcery za ženy a své dcery dávali jejich synům a sloužili jejich bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Synové Izraele páchali to, co je zlé v Hospodinových očích, zapomínali na Hospodina, svého Boha, a sloužili baalům a ašerám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on je vydal do ruky Kúšana Rišátajimského, krále Aramského Dvojříčí. Synové Izraele sloužili Kúšanovi Rišátajimskému osm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Synové Izraele volali k Hospodinu o pomoc a Hospodin dal pro syny Izraele povstat zachránci. Zachránil je Otníel, syn ⌈Kenazův, mladší bratr Káleba.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Spočinul na něm Duch Hospodinův a on Izrael soudil. Vytáhl do boje a Hospodin vydal do jeho ruky aramejského krále Kúšana Rišátajimského. Jeho ruka na Kúšana Rišátajimského mocně dolehla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'A země měla čtyřicet let klid. Otníel, syn Kenazův, pak zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Avšak synové Izraele dále páchali to, co je zlé v Hospodinových očích, a Hospodin posilnil moábského krále Eglóna proti Izraeli kvůli tomu, že páchali to, co je v Hospodinových očích zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Ten k sobě shromáždil syny Amónovy a Amálekovy. Vytáhl, přepadl Izrael a obsadili Ír–hatmarím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Synové Izraele pak sloužili moábskému králi Eglónovi osmnáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Synové Izraele tedy volali k Hospodinu o pomoc a Hospodin dal pro ně povstat zachránci Ehúdovi, synu Géry, ⌈syna Ben jamínova,⌉ muži ⌈nevládnoucímu pravou rukou.⌉ Jeho prostřednictvím poslali synové Izraele moábskému králi Eglónovi dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Ehúd si zhotovil dvojsečný meč gomer dlouhý a připásal si ho pod šaty na pravý bok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'I přinesl moábskému králi Eglónovi dar. Eglón byl hrozně tlustý muž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'A stalo se, když předal dar, že Ehúd propustil lid, který ten dar nesl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Sám se vrátil od tesaných obrazů u Gilgálu a řekl: Mám pro tebe tajné poselství, králi. On řekl: Tiše! Všichni, kdo stáli kolem něho, od něj odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Ehúd před něj předstoupil, když seděl v chladné horní místnosti, kterou měl pouze pro sebe. Ehúd řekl: Mám pro tebe Boží slovo. On nato povstal z křesla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'A Ehúd vztáhl svou levou ruku, vzal ten meč od pravého boku a vrazil mu ho do břicha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Za čepelí pronikl také jílec a tuk se za čepelí zavřel, protože nevytáhl meč z břicha. Vyšel zadem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Ehúd pak vyšel na chodbu, zavřel za sebou dveře horní místnosti a zamkl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Jakmile odešel, vstoupili jeho otroci, podívali se a hle, dveře horní místnosti byly zamčeny. Řekli si: On jistě ⌈koná potřebu⌉ v chladném pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Přešlapovali tam až hanba, avšak hle, nikdo dveře horní místnosti neotvírá. Vzali klíč, otevřeli a hle, jejich pán leží na zemi mrtvý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehúd unikl. Zatímco otáleli, on prošel kolem tesaných obrazů a unikl do Seíry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'I stalo se, když přišel, že zatroubil na beraní roh na efrajimském pohoří, synové Izraele s ním sestoupili z pohoří a on byl v jejich čele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Řekl jim: Pospěšte za mnou, protože Hospodin vám vydal do ruky vaše moábské nepřátele. Sestoupili za ním a dobyli jordánské brody na Moábovi. A nedovolili nikomu projít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'V onen čas pobili z Moábu okolo deseti tisíc mužů, samé urostlé a zdatné muže. Nikdo neunikl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'V onen den byl Moáb pokořen pod mocí Izraele a země měla osmdesát let klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Po něm byl Šamgar, syn Anatův. Pobil Pelištejce, šest set mužů, bodcem na skot. Také on zachránil Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Synové Izraele však dále páchali to, co je zlé v Hospodinových očích. Ehúd zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Hospodin je vydal do ruky kenaanského krále Jabína, jenž kraloval v Chasóru, a velitele jeho armády Sísery sídlícího v Charošet–hagójímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'A synové Izraele křičeli k Hospodinu. Vždyť Jabín měl devět set železných vozů a dvacet let syny Izraele násilím utlačoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'V oné době soudila Izrael Debóra, prorokyně, žena Lapidótova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Ta sedávala pod Debóřinou palmou mezi Rámou a Bét–elem v efrajimském pohoří. Synové Izraele za ní přicházeli k soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Ta poslala a povolala Báraka, syna Abínoamova, z neftalíjské Kedeše, a řekla mu: Což nepřikázal Hospodin, Bůh Izraele: Jdi, vytáhneš na horu Tábor a vezmeš s sebou deset tisíc mužů ze synů Neftalího a ze synů Zabulóna?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Já k tobě přivedu k potoku Kíšón Síseru, velitele Jabínovy armády, jeho vozy a jeho dav a vydám ti ho do ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Bárak jí odpověděl: Pokud půjdeš se mnou, i já půjdu. Nepůjdeš–li se mnou, nepůjdu ani já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Ona řekla: Určitě půjdu s tebou, jenomže na cestě, po které ty půjdeš, ti nebude patřit sláva, protože Hospodin vydá Síseru do ruky ženy. Debóra vstala a šla s Bárakem do Kedeše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Bárak svolal Zabulóna a Neftalího do Kedeše. ⌈V jeho stopách⌉ vytáhlo deset tisíc mužů. Debóra vytáhla s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'A Kénijec Cheber se odloučil od Kajina, od synů Mojžíšova tchána Chóbaba, a postavil svůj stan až k dubu v Saananímu, který je u Kedeše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Síserovi oznámili, že Bárak, syn Abínoamův, vystoupil na horu Tábor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Sísera svolal veškerou svou vozbu, devět set železných vozů, a všechen lid, který byl s ním, z Charošet–hagójímu k potoku Kíšón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Debóra řekla Bárakovi: Vstaň, protože toto je den, v němž Hospodin vydal Síseru do tvé ruky. Cožpak nevyšel Hospodin před tebou? A Bárak sestoupil z hory Tábor a za ním deset tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Hospodin přivedl před Bárakem do zmatku Síseru a celou vozbu a celý tábor na ostří meče. Sísera sestoupil z válečného vozu a utíkal pěšky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'A Bárak pronásledoval vozbu a vojsko až do Charošet–hagójímu. Celé Síserovo vojsko padlo ostřím meče; nezůstal ani jediný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'A Sísera utíkal pěšky ke stanu Jáely, ženy Kénijce Chebera, protože mezi chasórským králem Jabínem a domem Kénijce Chebera vládl pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Jáel vyšla Síserovi naproti a řekla mu: Zajdi, můj pane, zajdi ke mně, neboj se. Zašel tedy k ní do stanu a ona jej přikryla houní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Řekl jí: Dej mi prosím napít trochu vody, protože mám žízeň. Otevřela měch s mlékem, dala mu napít a přikryla jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Řekl jí: Postav se u vchodu do stanu, a když někdo přijde, bude se tě vyptávat a řekne: Není tu někdo? Odpovíš: Není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Jáel, žena Cheberova, vzala stanový kolík a do ruky uchopila kladivo. Přišla potají k němu a vrazila mu ten kolík do spánku, až proniknul do země. On tvrdě spal, byl totiž unavený; tak zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'A hle, Bárak pronásledoval Síseru. Jáel mu vyšla naproti a řekla mu: Pojď, ukážu ti muže, kterého hledáš. Vešel k ní a hle, Sísera leží mrtev a ve spánku má kolík.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'V onen den Bůh pokořil kenaanského krále Jabína před syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Ruka synů Izraele doléhala stále a tvrdě na kenaanského krále Jabína, až i kenaanského krále Jabína vyhladili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'V onen den zpívala Debóra a Bárak, syn Abínoamův:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Když jsou v Izraeli volně rozpuštěné vlasy, když se lid dobrovolně rozhodl, dobrořečte Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Slyšte králové, naslouchejte mocnáři! Já Hospodinu, já jemu chci zpívat. Budu opěvovat Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Hospodine, když jsi vycházel ze Seíru, když jsi vykročil z edómské krajiny, třásla se země a také z nebes kanula, ano z mračen kanula voda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Hory se potácely před Hospodinem, tím ze Sínaje, před Hospodinem, Bohem Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Ve dnech Šamgara, syna Anatova, ve dnech Jáely, zpustly stezky a poutníci na pěšinách chodili stezkami křivolakými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Vymizeli venkované v Izraeli, vymizeli až do chvíle, kdy jsem povstala já, Debóra, kdy jsem povstala, matka v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Zvolí– li si nové bohy, tehdy je válka v branách. Zdalipak se ukáže štít a oštěp mezi čtyřiceti tisíci v Izraeli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mé srdce je s veliteli Izraele, s dobrovolníky z lidu. Dobrořečte Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vy, kdo jezdíte na bělavých oslicích, vy, kdo sedáváte na kobercích, i vy, poutníci na cestě, přemýšlejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Daleko od hlasu střelců mezi napajedly, tam si budou připomínat Hospodinovy spravedlivé činy, spravedlivé činy vůči jeho venkovanům v Izraeli. Tehdy sestoupil k branám Hospodinův lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Probuď se, probuď, Debóro, probuď se, probuď, přednes píseň. Vstaň, Báraku, a zajmi své zajatce, synu Abínoamův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Tehdy sestoupil ten, který přežil, k vznešeným. Hospodinův lid sestoupil ke mně jako hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Z Efrajima vyšli ti, jejichž kořen byl v Amálekovi. Za tebou šel Benjamín s tvým lidem. Z Makíra sestoupili velitelé a ze Zabulóna ti, kdo nosí velitelské žezlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'A má knížata z Isachara šla spolu s Debórou; Isachar stejně jako Bárak byl poslán v jeho stopách do údolí. V Rúbenových oddílech byla velká vymezování mínění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Proč jsi zůstal mezi ohradami? Abys naslouchal hvízdání na stáda? Rúbenovy oddíly měly velká zpytování mínění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gileád se usídlil na druhé straně Jordánu. A proč Dan pobývá na lodích? Ašer se usadil na pobřeží moře, bydlí nad svými přístavy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zabulón je lid, který vydal svou duši na smrt. Rovněž Neftalí na výšinách krajiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Přišli králové a bojovali. Tehdy bojovali kenaanští králové v Taanaku u vod Megida. Nekalý zisk stříbra nepobrali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Z nebes bojovaly hvězdy, ze svých drah bojovaly se Síserou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Potok Kíšón je odplavil, potok prastarý, potok Kíšón. Šlapej, má duše, mocně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Tehdy se otloukla koňská kopyta od dusání, dusání jeho hřebců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Proklejte Meróz, praví Hospodinův anděl, prokletím proklejte jeho obyvatele, protože nepřišli na pomoc Hospodinu, na pomoc Hospodinu jako hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Požehnána buď mezi ženami Jáel, žena Kénijce Chebera, mezi ženami ve stanu buď požehnána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'On si vyžádal vodu, ona mu dala mléko, smetanu podala ve džbánu vznešených.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Rukou svou po kolíku sáhla a pravicí svou na kladivo pro těžce pracující a udeřila Síseru. Roztříštila mu hlavu, probodla a prorazila mu spánek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Mezi nohama jí klesl, padl, složil se. Mezi nohama jí klesl, padl. Kde klesl, tam padl zmordovaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Za oknem vyhlížela, za okenní mříží naříkala Síserova matka: Proč otálí jeho vůz s příjezdem, proč se opozdila kola jeho válečných vozů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Její moudré kněžny jí odpovědí, ona si také bude připomínat své řeči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Cožpak nenaleznou a ne budou dělit kořist? ⌈Souložnici nebo dvě⌉ ⌈pro každého předáka,⌉ kořist -- barvené šaty pro Síseru, kořist -- utkané barvené šaty, utkané barvené šaty ⌈na šíje,⌉ kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tak ať zahynou všichni tví nepřátelé, Hospodine, ale ti, kdo jej milují, budou jako slunce vycházející ve své síle. Země měla čtyřicet let klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Synové Izraele pak páchali to, co je zlé v Hospodinových očích a Hospodin je vydal do ruky Midjánců na sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Ruka Midjánců mocně dolehla na Izrael. Synové Izraele pro sebe kvůli Midjáncům upravili soutěsky, které byly v horách, jeskyně a pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Když Izrael zasel, stávalo se, že vytáhli Midjánci, Amálekovci a synové východu a vyrazili proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Utábořili se proti nim a ničili úrodu země, až tam, kudy se jde do Gazy a neponechali v Izraeli obživu, ovci, býka ani osla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Neboť oni vytáhli se svým dobytkem a svými stany a přihnali se jako celé hejno kobylek. Bylo jich i jejich velbloudů bezpočet a přišli do země, aby ji zničili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Izrael byl od Midjánců úplně zubožený. Synové Izraele volali k Hospodinu o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'I stalo se, že synové Izraele volali k Hospodinu o pomoc kvůli Midjáncům');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'a Hospodin poslal k synům Izraele proroka. Ten jim řekl: Toto praví Hospodin, Bůh Izraele: Já jsem vás vyvedl z Egypta, vyvedl jsem vás z domu otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Vysvobodil jsem vás z ruky Egypťanů a z ruky všech vašich utiskovatelů, vyhnal jsem je před vámi a dal jsem vám jejich zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'A řekl jsem vám: Já Hospodin jsem váš Bůh, nebojte se bohů Emorejců, v jejichž zemi bydlíte. Ale neuposlechli jste mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'I přišel Hospodinův anděl a posadil se pod terebintem, který je v Ofře, která patří Jóašovi Abíezerskému. Jeho syn Gedeón mlátil pšenici v lisu na víno, aby ji uchránil před Midjánci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Hospodinův anděl se mu ukázal a řekl mu: Hospodin s tebou, udatný hrdino.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Nato mu Gedeón odpověděl: Dovol, můj pane, pokud je Hospodin s námi, proč nás potom postihlo toto všechno a kde jsou všechny jeho obdivuhodné činy, o kterých nám vyprávěli naši otcové, když říkali: Cožpak nás Hospodin nevyvedl z Egypta? Jenže teď nás Hospodin opustil a vydal nás do ruky Midjánců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Hospodin se k němu obrátil a řekl: Jdi v této své síle a zachráníš Izrael z ruky Midjánců. Což jsem tě neposlal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'On se ho zeptal: Dovol, Panovníku, čím zachráním Izrael? Vždyť můj rod je v Manasesovi nejslabší a já jsem ten nejmenší v domě svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Tu mu Hospodin odpověděl: Protože budu s tebou, pobiješ Midjánce jako jediného muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'On jej požádal: Jestliže jsem opravdu nalezl milost ve tvých očích, učiň pro mě znamení, že se mnou mluvíš ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Nevzdaluj se, prosím, odsud, dokud se k tobě ne vrátím, ne přinesu svou přídavnou oběť a ne předložím ti ji. Řekl mu: Já zůstanu dokud se nevrátíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gedeón tedy šel a připravil kůzle a nekvašené chleby z éfy mouky. Maso položil do koše, vývar nalil do hrnce, přinesl to k němu pod terebint a nabídl mu to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Boží anděl mu řekl: Vezmi to maso a nekvašené chleby, předlož to u této skály, ale vývar vylej. I učinil tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Hospodinův anděl vztáhl konec hole, kterou měl v ruce, a dotkl se masa a nekvašených chlebů. Ze skály vystoupil oheň a strávil to maso a nekvašené chleby. Hospodinův anděl mu pak zmizel z očí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Gedeón zjistil, že to byl Hospodinův anděl. Gedeón řekl: Běda mi, Panovníku Hospodine, protože jsem spatřil Hospodinova anděla tváří v tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Hospodin mu však odpověděl: Pokoj tobě, neboj se, nezemřeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Gedeón tam postavil Hospodinu oltář a nazval jej: Hospodin je pokoj. Až do tohoto dne je stále v Abíezerské Ofře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'I stalo se oné noci, že mu Hospodin řekl: Vezmi býčka, býka, který patří tvému otci, ba toho druhého sedmiletého býčka. Zboříš Baalův oltář, který patří tvému otci, a pokácíš posvátný kůl, který je u něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Dále postavíš patřičným způsobem oltář Hospodinu, svému Bohu, na vrcholu této skály. Vezmeš toho druhého býčka a přineseš zápalnou oběť na dříví z toho posvátného kůlu, který pokácíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Gedeón vzal deset mužů ze svých otroků a učinil, jak mu Hospodin pověděl. I stalo se, protože se to kvůli domu svého otce a kvůli mužům toho města bál provést ve dne, že to vykonal v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Muži města časně ráno vstali a hle: Baalův oltář byl stržen a posvátný kůl, jenž u něj stával, byl skácen a druhý býček byl obětovaný na oltáři, který tu byl vybudován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Tu se ptali jeden druhého: Kdo provedl něco takového? Pátrali, hledali a řekli: Tohle provedl Gedeón, syn Jóášův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Nato řekli muži toho města Jóašovi: Vyveď svého syna. Ať zemře, protože strhl Baalův oltář a pokácel posvátný kůl, který byl u něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Ale Jóaš odpověděl všem, kteří se proti němu postavili: Cožpak vy ⌈povedete při za⌉ Baala? Vy ho snad budete zachraňovat? Kdo za něho povede při, bude do rána usmrcen. Jestliže on je bůh, povede při za sebe; strhl přece jeho oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'I nazval jej v onen den Jerubaalem se slovy: Ať s ním vede při Baal, vždyť mu strhl oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Tehdy se všichni Midjánci, Amálekovci a synové východu společně shromáždili, přebrodili a utábořili v údolí Jizreel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'A Duch Hospodinův vyzbrojil Gedeóna. Ten zatroubil na beraní roh a Abíezerovci se za ním shromáždili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Poslal posly po celém Manasesovi a on se také shromáždil za ním; poslal posly i k Ašerovi, k Zabulónovi a k Neftalímu a vyšli jim naproti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Potom Gedeón Bohu řekl: Jestliže ⌈chceš zachránit⌉ Izrael mým prostřednictvím, jak jsi to prohlásil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'hle, pokládám na humno ovčí rouno. Pokud bude rosa pouze na tom rouně a všude na zemi sucho, poznám, že mým prostřednictvím zachráníš Izrael, jak jsi to prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'I stalo se tak. Příštího dne časně vstal a vymačkal rouno. Vyždímal z toho rouna rosu, plný džbán vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Avšak Gedeón Bohu řekl: Kéž proti mně nevzplane tvůj hněv. Nech mě promluvit ještě jednou. Dovol, prosím, abych to zkusil s rounem už jen jednou. Nechť je, prosím, suché pouze to rouno a ⌈všude na⌉ zemi je rosa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'A Bůh tak oné noci učinil. Samo rouno bylo suché, kdežto všude na zemi byla rosa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Časně ráno vstal Jerubaal, tedy Gedeón, a všechen lid, který byl s ním, a utábořili se u Én–charódu. Tábor Midjánců byl u něho v údolí severně od návrší Móre.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Hospodin však Gedeónovi řekl: Je s tebou příliš mnoho lidu, než abych dal Midjánce do jejich ruky. Jinak by se Izrael vůči mně vychloubal: Zachránila mě má ruka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'A teď k lidu ihned provolej: Kdo se bojí a třese, ať se vrátí a vzdálí z pohoří Gileádu. Nato se vrátilo z lidu dvacet dva tisíce a deset tisíc zůstalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Ale Hospodin Gedeónovi řekl: Ještě je lidu mnoho. Nech je sestoupit k vodě, ať ti je tam přečistím. I stane se toto: O kom ti řeknu: Tenhle půjde s tebou, ten s tebou půjde, a každý, o kom ti řeknu: Tenhle s tebou nepůjde, ten nepůjde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Nechal tedy sestoupit lid k vodě a Hospodin Gedeónovi řekl: Každého, kdo bude chlemtat vodu jazykem, tak jako chlemtá pes, toho postavíš zvlášť a také každého, kdo si klekne k pití na kolena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Počet chlemtajících, kteří si podávali rukou do úst, byl tři sta mužů. Všechen ostatní lid si k pití vody klekl na kolena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Nato Hospodin Gedeónovi řekl: Prostřednictvím těch tří set chlemtajících mužů vás zachráním a vydám Midjánce do tvé ruky. Všechen lid ať odejde, každý do svého domova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Ti, kdo zůstali, si vzali s sebou zásobu potravin lidu a jejich beraní rohy. Všechny izraelské muže poslal pryč, každého k jeho stanům. Podržel si jenom tři sta mužů. Midjánský tábor byl pod ním v údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'I stalo se oné noci, že mu Hospodin řekl: Vstaň, sestup do tábora, protože jsem ti ho vydal do ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'A pokud se bojíš sestoupit sám, sestup do tábora se svým služebníkem Púrou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'a uslyšíš, co budou mluvit. Potom se posilní tvé ruce a sestoupíš do tábora. Sestoupil tedy on i jeho služebník Púra ke kraji ⌈vojenských oddílů,⌉ které byly v táboře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Midjánců, Amálekovců a všech synů východu ležících v údolí bylo co do množství jako kobylek a jejich velbloudů co do množství bylo bezpočet jako písku, který je na mořském břehu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Gedeón přišel a hle, muž vypráví svému příteli sen. Říkal: Poslyš, měl jsem sen a v něm se valí pecen ječného chleba na midjánský tábor až ke stanu a udeřil do něj, až spadl, převrátil ho vzhůru nohama a ten stan se zhroutil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Jeho přítel odpověděl. Řekl: Tohle neznamená nic jiného než meč izraelského muže Gedeóna, syna Jóášova. Bůh mu vydal do ruky Midjánce i celý tábor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'I stalo se, jakmile Gedeón uslyšel vyprávění toho snu a jeho výklad, že se poklonil. Vrátil se do izraelského tábora a řekl: Vstaňte, protože Hospodin vydal midjánský tábor do vaší ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Rozdělil tři sta mužů do tří oddílů, dal jim všem do ruky beraní rohy, prázdné džbány a uvnitř těch džbánů byly pochodně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'A řekl jim: Sledujte mě a dělejte to stejně jako já. Hle, půjdu na kraj tábora a bude to tak, ⌈že co⌉ udělám já, uděláte stejně i vy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Až zatroubím na beraní roh já a všichni, kdo jsou se mnou, zatroubíte také vy na beraní rohy okolo celého tábora a zavoláte: Za Hospodina a za Gedeóna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Gedeón přišel se stem mužů, kteří byli s ním, na kraj tábora na počátku prostřední noční hlídky, ⌈jakmile zcela postavili⌉ stráže. Zatroubili na beraní rohy a rozbili džbány, které měli v rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'I tři oddíly zatroubily na beraní rohy, rozbily džbány a uchopily do levé ruky pochodně a do pravé ruky beraní rohy, aby troubily, a zavolaly: Meč za Hospodina a za Gedeóna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Postavili se každý na své místo okolo tábora a celý tábor běžel, křičeli a utíkali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Tři sta beraních rohů troubilo a Hospodin obrátil meč ⌈jednoho proti druhému,⌉ a to v celém táboře. Tábor utíkal až do Bét–šity k Seréře, až k břehu Ábel–mechóly u Tabbátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, '⌈Byli svoláni izraelští muži⌉ z Neftalího, z Ašera a z celého Manasesa a pronásledovali Midjánce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Gedeón poslal posly po celém efrajimském pohoří se slovy: Sestupte vstříc Midjáncům a obsaďte jim vody až k Bét–báře a Jordán. ⌈Byli svoláni všichni efrajimští muži⌉ a obsadili vody až k Bét–báře a Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Přitom zajali dvě midjánská knížata, Óréba a Zéba. Oréba zabili na Cúr Órébu a Zéba zabili v Jekeb Zébu. Pronásledovali Midjánce a hlavu Óréba a Zéba přinesli Gedeónovi přes Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Avšak efrajimští muži mu řekli: ⌈Jak jsi to s námi jednal,⌉ že jsi nás nezavolal, když jsi šel do boje s Midjánci? A silně se s ním přeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Nato jim odpověděl: Co jsem teď učinil takového jako vy? Což nejsou Efrajimovy paběrky lepší než Abíezerovo vinobraní?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Do vaší ruky dal Bůh midjánská knížata Óréba a Zéba. Co jsem mohl udělat jako vy? Tehdy ochabl jejich hněv proti němu, ⌈když promluvil tato slova.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Gedeón přišel k Jordánu a prošel jím se třemi sty muži, kteří byli s ním, vyčerpaní, pronásledující nepřítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Požádal tedy muže ze Sukótu: Dejte, prosím, po bochníku chleba lidu, který jde v mých stopách, protože jsou vyčerpaní. Pronásleduji midjánské krále Zebacha a Salmunu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Ale sukótská knížata odpověděla? Cožpak je pěst Zebacha a Salmuny již ve tvé ruce, že máme dát tvé armádě chléb?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Nato Gedeón řekl: Za tohle zmlátím vaše tělo stepním trním a bodláky, až dá Hospodin Zebacha a Salmunu do mé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Vystoupil odtamtud do Penúelu a promluvil k nim podobně. Muži z Penúelu mu odpověděli stejně, jako odpověděli muži sukótští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Také mužům v Penúelu řekl: Až se v pokoji navrátím, strhnu tuto věž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zebach a Salmuna byli v Karkóru a s nimi jejich vojska, okolo patnácti tisíc, všichni, kteří zbyli z celého vojska synů východu. Padlých bylo sto dvacet tisíc mužů schopných tasit meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Gedeón vytáhl cestou těch, kdo přebývají ve stanech na východ od Nóbachu a Jogbohy, a přepadl tábor, právě když ten tábor spočíval v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Zebach a Salmuna utíkali a on je pronásledoval. Zajal oba midjánské krále, Zebacha a Salmunu, a celé vojsko uvedl v paniku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Když se Gedeón, syn Jóášův, vracel z té bitvy ⌈od svahu Cheresu,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'zajal mládence ze sukótských mužů, vyptával se ho a on pro něho sepsal knížata Sukótu a jeho starší, sedmdesát sedm mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Pak přišel k sukótským mužům a řekl: Zde jsou Zebach a Salmuna, pro které jste mě hanobili slovy: Cožpak je pěst Zebacha a Salmuny již ve tvé ruce, že máme dát tvým unaveným mužům chléb?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'A vzal starší toho města a stepní trní a bodláky a dal jimi sukótským mužům ⌈za vyučenou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Strhl i věž v Penúelu a zabil muže toho města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Potom se zeptal Zebacha a Salmuny: Jak vypadali ti muži, které jste zabili na Táboře? Odpověděli: Jaký jsi ty, takoví byli oni, všichni podle vzezření královští synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'On řekl: To byli mí bratři, synové mé matky. Jakože živ je Hospodin: Kdybyste je nechali žít, nezabil bych vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'A Jeterovi, svému prvorozenému, řekl: Vstaň, zabij je. Ale ten chlapec nevytáhl svůj meč, neboť se bál. Byl totiž ještě malý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Tu řekl Zebach a Salmuna: Vstaň ty a zasáhni nás, vždyť ⌈jaký muž, taková jeho síla.⌉ Gedeón tedy vstal, zabil Zebacha a Salmunu a vzal si půlměsíčky, které měli na šíjích jejich velbloudi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Izraelští muži pak Gedeónovi řekli: Vládni nad námi ty i tvůj syn a také ⌈tvůj vnuk,⌉ protože jsi nás zachránil z ruky Midjánců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Ale Gedeón jim odpověděl: Nebudu nad vámi vládnout já, ani můj syn nad vámi ne bude vládnout. Nad vámi bude vládnout Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Gedeón jim dále řekl: Dovolte mi přednést vám prosbu: Dejte mi každý kroužek ze své kořisti. Měli totiž zlaté kroužky, protože tamti byli Izmaelité.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Oni odpověděli: Rádi dáme. Rozprostřeli plášť a hodili tam všichni kroužek ze své kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Váha těch zlatých kroužků, které si vyžádal, byla tisíc sedm set šekelů zlata mimo ty půlměsíčky, náušnice a roucha z purpuru, která měli na sobě midjánští králové, a mimo náhrdelníky, které visely na šíjích jejich velbloudů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gedeón ⌈z toho udělal efód,⌉ postavil ho ve svém městě, v Ofře, a všichni z Izraele tam za ním chodili smilnit, takže se stal Gedeónovi a jeho domu léčkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Tehdy byli Midjánci před syny Izraele pokořeni a již nepozdvihli hlavu. Země měla v Gedeónových dnech čtyřicet let klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Jerubaal, syn Jóášův, pak odešel a usadil se ve svém domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Gedeón měl dále sedmdesát synů, vzešlých z jeho beder, protože měl mnoho žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Také jeho konkubína, kterou měl v Šekemu, mu porodila syna a tomu dal jméno Abímelek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Nakonec Gedeón, syn Jóášův, zemřel v utěšených šedinách a byl pohřben do hrobu svého otce Jóaše v Abíezerské Ofře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'I stalo se, jakmile Gedeón zemřel, že se synové Izraele odvrátili, chodili smilnit za baaly a ustanovili Baal–beríta svým bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Synové Izraele si nepamatovali na Hospodina, svého Boha, který je vysvobozoval z ruky všech jejich okolních nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Ani ne prokázali milosrdenství domu Jerubaala Gedeóna za veškeré dobro, jež vykonal pro Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abímelek, syn Jerubaalův, pak šel do Šekemu k bratrům své matky a promluvil k nim a ke vší čeledi z domu rodu své matky:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Promluvte prosím ke všem občanům Šekemu: Co je pro vás lepší? Má nad vámi vládnout sedmdesát mužů, samí synové Jerubaalovi? Co kdyby nad vámi vládl jediný muž? Vzpomeňte si, že jsem vaše kost a vaše tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Když o něm bratři jeho matky promluvili ke všem občanům Šekemu všechna tato slova, jejich srdce se naklonilo za Abímelekem, protože si řekli: Je to náš bratr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Dali mu sedmdesát šekelů stříbra z chrámu Baal–beríta a Abímelek si za ně najal ničemné a bezohledné muže, kteří ho následovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'A přišel do Ofry, do domu svého otce, a zabil své bratry, syny Jerubaalovy, sedmdesát mužů na jednom kameni. Zůstal Jótam, nejmladší syn Jerubaalův, protože se ukryl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Pak se shromáždili všichni občané Šekemu a celé Bét–miló. Šli a ustanovili Abímeleka za krále u dubu, který stojí v Šekemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Když to oznámili Jótamovi, šel a postavil se na vrchol hory Gerizím, pozvedl svůj hlas a zavolal. Řekl jim: Poslouchejte mě, občané Šekemu, a vás nechť vyslechne Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Tak se jednou sešly stromy, aby nad sebou pomazaly krále, a řekly olivě: Kraluj nad námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Oliva jim však pravila: Cožpak bych se vzdala své tučnosti, pro kterou mě oslavují bohové i lidé, a šla se kymácet nad stromy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Stromy tedy řekly fíkovníku: Pojď ty, kraluj nad námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'I fíkovník jim odpověděl: Cožpak bych se vzdal své sladkosti a svého dobrého ovoce a šel se kymácet nad stromy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Nato řekly stromy révě: Pojď ty, kraluj nad námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Rovněž réva jim pravila: Cožpak bych se vzdala svého mladého vína, které dává radost bohům i lidem, a šla se kymácet nad stromy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Ještě řekly všechny stromy bodláku: Pojď ty, kraluj nad námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'A bodlák stromům odpověděl: Jestliže mě opravdu chcete pomazat za krále nad sebou, přijďte a schovejte se v mém stínu. Pokud ne, ať vyjde z bodláku oheň a stráví libanonské cedry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Nyní, jestliže jste si počínali věrně a bezúhonně, když jste ustanovili Abímeleka králem, pokud jste prokázali dobro Jerubaalovi a jeho domu a naložili jste s ním ⌈podle toho, co vykonaly jeho ruce,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '-- můj otec přece bojoval za vás, ⌈dal v sázku svou duši⌉ a vysvobodil vás z ruky Midjánců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'ale vy jste dnes povstali proti domu mého otce, zabili jste jeho syny, sedmdesát mužů, na jednom kameni a králem nad občany Šekemu jste ustanovili Abímeleka, syna jeho služebnice, protože je to váš bratr --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'jestliže jste tedy věrně a bezúhonně jednali s Jerubaalem a s jeho domem tohoto dne, radujte se z Abímeleka a také on ať se raduje z vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Pokud tomu tak není, ať vyjde z Abímeleka oheň a stráví občany Šekemu a Bét–miló a ať vyjde oheň z občanů Šekemu a z Bét–miló a stráví Abímeleka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Potom Jótam utekl, prchal pryč od svého bratra Abímeleka, odešel do Beéru a bydlel tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Abímelek vládl nad Izraelem tři roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Bůh pak poslal mezi Abímeleka a občany Šekemu zlého ducha a občané Šekemu se k Abímelekovi zachovali zrádně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'To pro násilí spáchané na sedmdesáti Jerubaalových synech, aby jejich krev dopadla na jejich bratra Abímeleka, který je zabil, a na občany Šekemu, kteří posilnili jeho ruce, aby zabil své bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Občané Šekemu mu nastražili zálohy na vrcholech hor a okrádali každého, kdo procházel po cestě kolem nich. Abímelekovi to bylo oznámeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Tehdy přišel Gaal, syn Ebedův, a jeho bratři a procházeli Šekemem. Občané Šekemu mu důvěřovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Vyšli na pole a sbírali víno ze svých vinic, šlapali ho a uspořádali slavnost. Vstoupili do chrámu svého boha, jedli a pili a proklínali Abímeleka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Tehdy řekl Gaal, syn Ebedův: Kdo je Abímelek a kdo jsou ⌈šekemští, že jim⌉ budeme sloužit? Což to není syn Jerubaalův a není Zebúl jeho dohlížitel? Služte mužům Chamóra, otce Šekemova. Proč my máme sloužit jemu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, '⌈Kéž bych měl tento lid pod svým velením,⌉ abych Abímeleka odstranil! Abímelekovi řekl: Rozmnož svou armádu a vytáhni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Když Zebúl, kníže města, uslyšel slova Gaala, syna Ebedova, vzplanul jeho hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'A poslal k Abímelekovi tajně posly se slovy: Hle Gaal, syn Ebedův, a jeho bratři přicházejí do Šekemu. Pozor na ně! Pobuřují město proti tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Nuže, vstaň v noci, ty i lid, který je s tebou, a nastraž v poli zálohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'A časně ráno, jakmile vyjde slunce, vstaneš, vtrhneš do města a hle, on a lid, jenž je s ním, vytáhne ⌈proti tobě⌉ a ty s ním naložíš, ⌈jak se ti namane⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'V noci tedy Abímelek a všechen lid, který byl s ním, vstal a nastražili na Šekem zálohu -- čtyři oddíly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Když Gaal, syn Ebedův, vyšel a postavil se do vchodu městské brány, Abímelek a lid, který byl s ním, vstal ze zálohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Gaal ten lid spatřil a řekl Zebúlovi: Podívej se, lid sestupuje z vrcholů hor. Ale Zebúl mu odpověděl: Vidíš jen stín hor, podobný mužům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal však ⌈mluvil stále dál.⌉ Řekl: Hle, lid sestupuje ze ⌈středu země⌉ a jeden oddíl přichází od cesty k dubu věštců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Nato mu Zebúl řekl: Kde jsou tedy tvá ústa, kterými jsi prohlásil: Kdo je Abímelek, že mu máme sloužit? Cožpak tohle není ten lid, kterým jsi kvůli němu pohrdl? Vytáhni už konečně a bojuj proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Gaal tedy vytáhl v čele šekemských občanů a bojoval proti Abímelekovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Abímelek jej však pronásledoval a on před ním utekl. Padlo mnoho probodených až po vchod do brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Abímelek se usadil v Arúmě a Zebúl Gaala a jeho bratry vyhnal, takže nezůstali v Šekemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'I stalo se příštího dne, že lid vyšel na pole. Oznámili to Abímelekovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Ten vzal lid, rozdělil je do tří oddílů a v poli nastražil zálohu. Rozhlédl se a hle, lid vychází z města. Povstal proti nim a pobil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abímelek a oddíly, které byly s ním, vtrhly a postavily se ke vchodu do městské brány. Další dva oddíly pak vtrhly na všechny, kdo byli na poli, a pobily je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abímelek proti městu bojoval celý den, dobyl to město a lid, jenž byl v něm, zabil. Město zbořil a posypal ho solí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Když to uslyšeli všichni občané šekemské věže, vešli do sklepení chrámu El–beríta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Abímelekovi bylo oznámeno, že se shromáždili všichni občané šekemské věže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Tu Abímelek vystoupil na horu Salmón, on i všechen lid, který byl s ním. Abímelek ⌈s sebou⌉ vzal sekery, usekl větev ze stromu, zvedl ji a položil si ji na rameno. Lidu, který byl s ním, řekl: Co jste viděli, že jsem udělal, pospěšte si a udělejte to jako já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Také všechen lid tedy usekl každý svou větev, šli za Abímelekem, položili je na sklepení a zapálili nad nimi ⌈ na tom sklepení oheň.⌉ Tak zemřeli také všichni lidé ze šekemské věže, asi tisíc mužů a žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Potom šel Abímelek do Tebesu, utábořil se u Tebesu a dobyl jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Uprostřed toho města byla pevná věž. Tam utekli všichni muži a ženy, všichni občané města, zavřeli za sebou a vystoupili na střechu té věže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Abímelek přišel k věži, bojoval proti ní a přistoupil až ke vchodu té věže, aby ji spálil ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Vtom svrhla jedna žena Abímelekovi na hlavu vrchní mlýnský kámen a prorazila mu lebku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Rychle zavolal na služebníka, svého zbrojnoše, a řekl mu: Vytáhni svůj meč a usmrť mě. Jinak o mně budou říkat: Zabila jej žena. Jeho služebník jej tedy probodnul a on zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Když izraelští muži viděli, že Abímelek zemřel, odešli každý do svého domova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Tak Bůh odplatil Abímelekovi za zlo, jež spáchal proti svému otci, když zabil svých sedmdesát bratrů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Také všechno zlo šekemských mužů Bůh obrátil na jejich hlavu a přišla na ně kletba Jótama, syna Jerubaalova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Po Abímelekovi pak povstal k záchraně Izraele isacharský muž Tóla, syn Púy, syna Dódova. Ten bydlel v Šamíru v efrajimském pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Soudil Izrael dvacet tři let. Zemřel a byl pohřben v Šamíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Po něm povstal Jaír Gileádský a soudil Izrael dvacet dva let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Ten měl třicet synů, jezdících na třiceti oslech a patřilo jim třicet měst. Podle nich nazývají Jaírova tábořiště, která jsou v zemi Gileádu, až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Jaír zemřel a byl pohřben v Kamónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'A synové Izraele dále páchali to, co je zlé v Hospodinových očích, sloužili baalům a aštoretám, bohům aramejským, bohům sidónským, bohům moábským, bohům synů Amónových a bohům Pelištejců. Opustili Hospodina a nesloužili mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Tehdy vzplanul proti Izraeli Hospodinův hněv a on je vydal do ruky Pelištejců a do ruky synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, '⌈Stírali a svírali⌉ syny Izraele od onoho roku po osmnáct let, všechny syny Izraele, kteří sídlili na druhé straně Jordánu v emorejské zemi, jež leží v Gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Synové Amónovi přešli Jordán, aby bojovali také proti Judovi, proti Benjamínovi a proti Efrajimovu domu. Izraelcům bylo velmi úzko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Synové Izraele tehdy volali k Hospodinu o pomoc: Zhřešili jsme proti tobě, vždyť jsme opustili našeho Boha a sloužili jsme baalům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Nato Hospodin synům Izraele odpověděl: Od Egypťanů, od Emorejců, od synů Amónových a od Pelištejců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Sidónců, Amálekovců a Maónců, když vás utlačovali a křičeli jste ke mně, ne zachraňoval jsem vás snad z jejich ruky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Jenže vy jste mě opustili a sloužili jste jiným bohům. Proto vás ⌈už nebudu⌉ zachraňovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Jděte a volejte o pomoc k bohům, které jste si vyvolili. Oni ať vás zachrání v době vašeho soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Avšak synové Izraele řekli Hospodinu: Zhřešili jsme, nalož s námi zcela tak, jak je dobré ve tvých očích. Jen nás, prosíme, tohoto dne vysvoboď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Pak odstranili ze svého středu cizí bohy, sloužili Hospodinu a jeho duše ⌈se ustrnula nad⌉ trápením Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Synové Amónovi byli svoláni a utábořili se v Gileádu. Synové Izraele se také shromáždili a utábořili se v Mispě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Tu lidé -- gileádská knížata -- říkali jeden druhému: Muž, který začne bojovat proti synům Amónovým, se stane předákem všech obyvatel Gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jiftách Gileádský byl udatný hrdina a byl synem prostitutky. Jiftácha zplodil Gileád.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'I Gileádova žena mu porodila syny. Když synové té ženy vyrůstali, Jiftácha vyhnali. Řekli mu: Neobdržíš dědictví v domě našeho otce, protože jsi synem jiné ženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Jiftách před svými bratry utekl a bydlel v zemi Tóbu. K Jiftáchovi se seběhli ničemní muži a podnikali s ním výpady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'I stalo se po několika dnech, že synové Amónovi bojovali s Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Pak se stalo, když už synové Amónovi bojovali s Izraelem, že přišli gileádští starší, aby vzali Jiftácha ze země Tóbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Řekli Jiftáchovi: Pojď, ⌈staneš se naším vůdcem.⌉ Bojujme proti synům Amónovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Nato Jiftách gileádským starším odpověděl: Cožpak jste mě vy neměli v nenávisti a ne vyhnali jste mě z domu mého otce? Proč jste teď, když je vám úzko, přišli za mnou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Gileádští starší Jiftáchovi řekli: Proto jsme se nyní obrátili na tebe. Půjdeš s námi, budeš bojovat proti synům Amónovým a staneš se naším předákem nade všemi obyvateli Gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Tu Jiftách gileádským starším řekl: Jestliže mě pohnete k návratu, ⌈abych bojoval⌉ proti synům Amónovým a Hospodin je přede mnou vydá, já budu vaším velitelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Gileádští starší Jiftáchovi odpověděli: Hospodin bude mezi námi svědkem, jestliže to neprovedeme podle tvého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Jiftách tedy šel s gileádskými staršími a lid jej ustanovil nad sebou za předáka a za vůdce. Jiftách přednesl všechna svá slova před Hospodinem v Mispě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Potom poslal Jiftách posly ke králi synů Amónových se slovy: ⌈Co proti mně máš,⌉ že jsi ke mně přitáhl, abys vedl válku proti mé zemí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Král synů Amónových Jiftáchovým poslům odpověděl: Vždyť Izrael zabral mou zemi, když vystupoval z Egypta, od Arnónu až po Jabok a až k Jordánu. Nuže, vrať ji zpět v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jiftách pak poslal zase znovu posly ke králi synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'A řekl mu: Toto prohlásil Jiftách: Izrael nezabral moábskou zemi ani zemi synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Protože když vystupovali z Egypta, šel Izrael pustinou až k Rákosovému moři a přišel do Kádeše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Tu poslal Izrael posly k edómskému králi se slovy: Dovol, ať jen projdu tvou zemí. Ale edómský král je nevyslyšel. Také k moábskému králi poslal, ale ani ten nesvolil, a tak Izrael zůstal v Kádeši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Šel pustinou, obešel edómskou zemi a moábskou zemi a přišel k moábské zemi od východu slunce. Utábořili se na druhé straně Arnónu. Nevstoupili na moábské území, protože Arnón je hranicí Moábu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Pak poslal Izrael posly k emorejskému králi Síchonovi, králi Chešbónu. Izrael mu řekl: Dovol, ať jen projdeme tvou zemí až na moje území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Ani Síchon Izraeli nevěřil, že jen projde jeho územím. Síchon shromáždil všechen svůj lid, utábořili se v Jahasu a bojoval s Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'A Hospodin, Bůh Izraele, vydal Síchona a všechen jeho lid Izraeli do ruky a pobili je. Izrael obsadil celou zemi Emorejců, obyvatel oné země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Obsadili veškeré emorejské území od Arnónu až k Jaboku a od pustiny až k Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Nuže, Hospodin, Bůh Izraele, podrobil Emorejce svému izraelskému lidu, a ty že ho obsadíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Což neobsadíš to, co ti podrobí Kemóš, tvůj bůh, právě a jen to? Vše, co podrobil Hospodin, náš Bůh, nám, to obsadíme my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Nuže, cožpak jsi opravdu lepší než moábský král Balák, syn Sipórův? Cožpak opravdu vedl při s Izraelci, bojoval snad vážně proti nim?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Když bydlel Izrael v Chešbónu a v jeho vesnicích, v Aróeru a v jeho vesnicích a ve všech městech, která jsou vedle Arnónu, tři sta let, proč jste je nedobyli zpět během oné doby?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Já jsem se vůči tobě neprohřešil, avšak ty proti mně pácháš zlo, ⌈když proti mně chceš vést⌉ válku. Ať dnes Hospodin rozhodne jako soudce mezi syny Izraele a mezi syny Amónovými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Ale král synů Amónových neposlechl Jiftáchova slova, která mu vzkázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Tu na Jiftáchovi spočinul Duch Hospodinův. Táhl Gileádem a Manasesem, táhl i Mispou gileádskou a z Mispy gileádské táhl k synům Amónovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Jiftách tehdy učinil slib Hospodinu. Řekl: Jestliže opravdu vydáš syny Amónovy do mé ruky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'stane se toto: Cokoli vycházející, co mi vyjde naproti ze dveří mého domu, až se v pokoji navrátím od synů Amónových, bude patřit Hospodinu a přinesu to jako zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Potom Jiftách táhl k synům Amónovým, aby proti nim bojoval, a Hospodin je vydal do jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'A pobíjel je od Aróeru, až tam, kudy se jde do Minítu, dvacet měst až po Ábel–keramím, tuze velkou porážkou. Synové Amónovi byli před syny Izraele pokořeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Když přicházel Jiftách do Mispy ke svému domu, hle, jeho dcera mu vyšla naproti s tamburínkami a s tanci. Neměl mimo ni syna ani dceru, pouze ji, jedináčka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'I stalo se, jak ji uviděl, že roztrhl své roucho a řekl: Běda, má dcero, nadobro jsi mě srazila. Ty ⌈na mě přivádíš zkázu.⌉ Já jsem se zavázal Hospodinu svými ústy a nemohu to vzít zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Nato mu řekla: Můj otče, zavázal ses Hospodinu svými ústy. Nalož se mnou podle toho, co vyšlo z tvých úst, poté, co za tebe Hospodin vykonal pomstu nad tvými nepřáteli ze synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Dále svému otci řekla: Ať je se mnou uzavřena tato úmluva: Nech mi dva měsíce. Chci odejít se svými přítelkyněmi, budu se rozplývat nářkem na horách a budu oplakávat své panenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Odpověděl jí: Jdi. Dal jí na to dva měsíce a ona šla se svými přítelkyněmi a oplakávala v horách své panenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'I stalo se po dvou měsících, když se navrátila k svému otci, že s ní naložil podle svého slibu, který dal. Ona nepoznala muže. Stalo se pak v Izraeli zvykem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'že se ⌈rok co rok⌉ dcery Izraele scházely, aby si připomínaly dceru Jiftácha Gileádského po čtyři dny v roce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Efrajimští ⌈muži byli svoláni, táhli⌉ na sever a řekli Jiftáchovi: Proč jsi táhl bojovat proti synům Amónovým, a nás jsi nezavolal, abychom šli s tebou? Tvůj dům nad tebou spálíme ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Nato jim Jiftách řekl: Byl jsem mužem velikého sporu, já a můj lid, se syny Amónovými. Volal jsem k vám o pomoc, ale nezachránili jste mě z jejich ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Když jsem viděl, že mě nezachráníte, ⌈vystavil jsem tedy svůj život nebezpečí,⌉ táhl jsem na syny Amónovy a Hospodin mi je vydal do ruky. Proč jste na mě tohoto dne vytáhli, abyste proti mně bojovali?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Pak Jiftách shromáždil všechny gileádské muže, bojoval s Efrajimem a gileádští muži pobili Efrajimce, protože řekli: Vy Gileáďané jste efrajimští uprchlíci ⌈uprostřed Efrajima a uprostřed Manasesa.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Gileád dobyl na Efrajimovi jordánské brody. Kdykoli se stalo, že efrajimští uprchlíci říkali: Chci se přebrodit, tu jim gileádští muži odpověděli: Ty jsi Efratejec? Pokud řekl: Nejsem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'poručili mu: Tak řekni: Šibbolet. Pokud řekl: Sibbolet a nedokázal to vyslovit správně, chytili ho a zabili ho tam u jordánských brodů. V oné době padlo z Efrajima čtyřicet dva tisíce mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jiftách soudil Izrael šest let. I zemřel Jiftách Gileádský a byl pohřben v jednom z gileádských měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Po něm soudil Izrael Ibsán z Bét–lechemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Ten měl třicet synů. Třicet dcer vyvdal pryč a třicet dcer přivedl pro své syny odjinud. Izrael soudil sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'I zemřel Ibsán a byl pohřben v Bét–lechemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Po něm soudil Izrael Elón Zabulónský. Soudil Izrael deset let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'I zemřel Elón Zabulónský a byl pohřben v Ajalónu v zabulónské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Po něm soudil Izrael Abdón, syn Hiléla Pireatónského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Ten měl čtyřicet synů a třicet vnuků jezdících na sedmdesáti oslech. Soudil Izrael osm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'I zemřel Abdón, syn Hiléla Pireatónského, a byl pohřben v Pireatónu v efrajimské zemi v Amáleckém pohoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Synové Izraele dále páchali to, co je v Hospodinových očích zlé, a Hospodin je vydal na čtyřicet let do ruky Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Byl jeden muž ze Soreje z danovské čeledi jménem Manóach. Jeho žena byla neplodná a nerodila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Té ženě se ukázal Hospodinův anděl a řekl jí: Jen pohleď: Jsi neplodná a nerodila jsi, ale otěhotníš a porodíš syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Nuže, měj se bedlivě na pozoru: Nebudeš pít víno ani pivo a nebudeš jíst nic nečistého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Neboť hle, budeš těhotná a porodíš syna. Na jeho hlavu nevstoupí břitva, protože ten chlapec bude od těhotenství Boží nazír. On začne zachraňovat Izrael z ruky Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Ta žena šla a řekla svému muži: Přišel ke mně muž Boží. Jeho vzhled byl jako vzhled Božího anděla, velmi hrozný. Nezeptala jsem se ho, odkud je, ani on mi neoznámil své jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'A řekl mi: Hle, ty budeš těhotná a porodíš syna. Teď nebudeš pít víno ani pivo a nebudeš jíst žádnou nečistotu, protože ten chlapec bude Boží nazír od samého těhotenství až do dne své smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Nato Manóach naléhavě prosil Hospodina. Řekl: Dovol, můj Pane, prosím, ať muž Boží, kterého jsi poslal, přijde znovu k nám a poučí nás, co máme udělat s tím narozeným chlapcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'A Bůh Manóacha vyslyšel. Boží anděl přišel znovu k té ženě, když pobývala na poli a její muž Manóach s ní nebyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Ta žena si tedy pospíšila, běžela a oznámila to svému muži. Řekla mu: Hle, ukázal se mi ten muž, jenž ke mně onehdy přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Tu Manóach vstal a šel za svou ženou, přišel k tomu muži a zeptal se ho: Ty jsi ten muž, který mluvil s touto ženou? On odpověděl: To jsem já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Manóach řekl: Nechť se nyní naplní tvá slova přikazující, jaké je ⌈nařízení o tom chlapci⌉ a ⌈jeho díle.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Hospodinův anděl Manóachovi řekl: Ať se ta žena má na pozoru před vším, o čem jsem jí řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Nepojí z ničeho, co pochází z vinné révy. Nebude pít víno ani pivo a nebude jíst žádnou nečistotu. Vše, co jsem jí přikázal, ať zachovává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Manóach pak Hospodinovu andělu řekl: Dovol, ať tě zdržíme a připravíme ti kůzle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Hospodinův anděl Manóachovi odpověděl: Pokud mě zdržíš, nepojím z tvého pokrmu, ale připravíš–li Hospodinu zápalnou oběť, přines ji. Manóach totiž nevěděl, že je to Hospodinův anděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Manóach se pak Hospodinova anděla zeptal: Jak zní tvé jméno? Ať tě poctíme, až se naplní tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Ale Hospodinův anděl mu odpověděl: Proč se ptáš na mé jméno? Je podivuhodné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Manóach tedy vzal kůzle a přídavnou oběť a přinesl to na skálu Hospodinu. Ten ⌈se ukázal jako podivuhodný ve svém působení a Manóach a jeho žena to viděli.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'I stalo se, když stoupal plamen od oltáře k nebesům, že i Hospodinův anděl vystoupil v plameni z oltáře. Když to Manóach a jeho žena viděli, padli tváří k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Více se už Hospodinův anděl Manóachovi a jeho ženě neukazoval. Tehdy Manóach poznal, že to byl Hospodinův anděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Tu Manóach řekl své ženě: Jistě zemřeme, protože jsme viděli Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Ale jeho žena mu odpověděla: Kdyby se Hospodinu zalíbilo nás usmrtit, nepřijal by z naší ruky zápalnou a přídavnou oběť, ani by nám ne ukázal všechny tyto věci a nezvěstoval by nám po celý ten čas něco takového.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Ta žena pak porodila syna a nazvala ho jménem Samson. Chlapec vyrůstal a Hospodin mu žehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'A Hospodinův Duch jej začal ponoukat v táboře Danovců mezi Soreou a Eštaólem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Tehdy Samson sestoupil do Timny a spatřil v Timně ženu z pelištejských dcer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Vystoupil tedy odtamtud a oznámil to svému otci a své matce. Řekl: Uviděl jsem v Timně ženu z pelištejských dcer. Nuže, vezměte ji pro mě za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Jeho otec a matka mu však řekli: Cožpak se nenajde žena mezi dcerami tvých bratrů a v celém mém lidu, že si jdeš vzít ženu z neobřezaných Pelištejců? Ale Samson svému otci odpověděl: Tu pro mě vezmi, protože ona je v mých očích ta pravá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Jeho otec ani matka nevěděli, že je od Hospodina, protože on hledá u Pelištejců příležitost. V oné době Pelištejci vládli nad Izraelci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'I sestoupil Samson, jeho otec i matka do Timny a přišli až k vinicím u Timny a hle, potkal se s ním mladý řvoucí lev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Tu jej uchvátil Duch Hospodinův a on ho roztrhl, jako by roztrhl kůzle, ačkoliv neměl nic v ruce. Svému otci ani matce nepověděl, co udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Pak sestoupil dolů a promluvil s tou ženou; v Samsonových očích to byla ta pravá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Po několika dnech se opět vrátil, aby si ji vzal. Přitom odbočil, aby se podíval na zdechlinu toho lva, a vida: V těle toho lva byl roj včel a med.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Tak si ho vyškrábl na dlaň a ⌈dal se při chůzi do jídla.⌉ Přišel k svému otci a matce, dal jim to a oni jedli. Nepověděl jim však, že ten med vyškrábl ze lvího těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Jeho otec pak sestoupil k té ženě a Samson tam uspořádal hostinu, protože tak to mládenci dělávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'I stalo se, jak ho uviděli, že vybrali třicet společníků a ti zůstali s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Samson jim řekl: Dovolte, ať vám dám hádanku. Jestliže mi s jistotou sdělíte ⌈její řešení⌉ za sedm dnů hostiny a uhodnete– li, dám vám třicet košil a třicet proměnných rouch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Jestliže mi ho ale nebudete schopni oznámit, dáte vy mně třicet košil a třicet proměnných rouch. Řekli mu: Dej nám svou hádanku, poslechneme si ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Řekl jim tedy: Ze žrouta vyšla potrava a ze silného vyšla sladkost. Tři dny nebyli schopni oznámit řešení té hádanky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Když nastal sedmý den, řekli Samsonově ženě: Přemluv svého muže, ať nám sdělí řešení té hádanky, jinak spálíme tebe i dům tvého otce ohněm. Copak jste nás svolali kvůli našemu ožebračení? ⌈ To snad ne?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Samsonova žena se před ním rozplakala a řekla: ⌈Vůbec mě nemáš rád,⌉ nemiluješ mě. Synům mého lidu jsi dal hádanku a mně jsi nesdělil její řešení. Řekl jí: Hle, svému otci ani své matce jsem ho nesdělil, a tobě ho mám sdělit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'A plakala před ním těch sedm dnů, kdy měli svou hostinu. Sedmý den se stalo, že jí ho sdělil, protože na něho naléhala. I sdělila řešení té hádanky synům svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Muži toho města mu pak sedmého dne, dříve než zapadlo slunko, řekli: Co je sladší než med a co silnější než lev? Odpověděl jim: Kdybyste neorali s mou jalovicí, mou hádanku byste neuhodli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Tu jej uchvátil Duch Hospodinův a sestoupil do Aškalónu. Pobil z nich třicet mužů, pobral jejich výstroj a dal proměnná roucha těm, kdo sdělili řešení hádanky. Pak vzplanul jeho hněv a on vystoupil do domu svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Samsonova žena se potom dostala jeho příteli, který mu byl společníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'I stalo se po několika dnech ve dnech sklizně pšenice, že Samson navštívil svou ženu s kůzletem. Řekl: Chci vejít ke své ženě do pokoje. Ale její otec mu nedovolil vejít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Její otec dále řekl: Říkal jsem si stále, že jsi ji opravdu neměl rád, a dal jsem ji tvému společníkovi. Což není její mladší sestra hezčí než ona? Nechť je tvá místo ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Ale Samson jim řekl: Tentokrát jsem vůči Pelištejcům nevinný, když s nimi zle naložím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Tu Samson šel a polapil tři sta lišek. Vzal pochodně, obrátil ocas k ocasu a umístil jednu pochodeň doprostřed mezi ty dva ocasy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Pak zapálil na pochodních oheň a vypustil je do nepožatého obilí Pelištejců. Tak zapálil vše -- od stohu přes nepožaté obilí až po vinici i olivový háj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Pelištejci se ptali: Kdo tohle udělal? A lidé říkali: Samson, zeť toho Timnaťana, protože vzal jeho ženu a dal ji jeho společníkovi. A tak Pelištejci vyšli a upálili ji i jejího otce ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Nato jim Samson řekl: Pokud budete páchat něco takového, tak nepřestanu, dokud se vám ne pomstím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'A zbil je, ⌈hlava nehlava,⌉ velkou ranou. Pak sestoupil dolů a usadil se ve skalní strži Étamu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Pelištejci však vytáhli, utábořili se v Judsku a rozložili se v Lechí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Judští muži se ptali: Proč jste proti nám vytáhli? Odpověděli: Abychom spoutali Samsona. Vytáhli jsme, abychom mu provedli to, co on provedl nám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Tři tisíce mužů z Judska tedy sestoupilo ke skalní strži Étamu a řekli Samsonovi: Cožpak jsi nevěděl, že nad námi vládnou Pelištejci? Co jsi nám to provedl? Odpověděl jim: To, co provedli mně, to jsem i já provedl jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Řekli mu: Sestoupili jsme, abychom tě spoutali, abychom tě vydali Pelištejcům do ruky. Nato jim řekl Samson: Přísahejte mi, že vy proti mně nezasáhnete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Prohlásili tedy před ním: Ne, jenom tě pevně svážeme a vydáme tě do jejich ruky. Určitě tě neusmrtíme. Svázali ho do dvou nových popruhů a odvedli ho od té skály.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Když přicházel k Lechí, Pelištejci ⌈ho přivítali řevem.⌉ Vtom ho uchvátil Duch Hospodinův a popruhy, které měl na pažích, byly jako knoty, které se spálily v ohni, a pouta se mu uvolnila z rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Pak našel čerstvou oslí čelist, vztáhl ruku, zmocnil se jí a pobil s ní tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Tehdy Samson pravil: Oslí čelistí ⌈hromadu, dvě hromady,⌉ oslí čelistí pobil jsem tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'I stalo se, když domluvil, že odhodil tu čelist z ruky a nazval ono místo Rámat–lechí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Pak dostal velkou žízeň a volal k Hospodinu. Řekl: Ty jsi vložil do ruky svého otroka tuto velikou spásu a teď tu zemřu žízní a padnu do ruky těch neobřezanců!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'A Bůh rozpoltil prohlubeň, která je v Lechí. Vyšla z ní voda, on se napil, jeho duch se navrátil a ⌈ožil. Proto ji nazval⌉ jménem Pramen volajícího, jenž je v Lechí až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Soudil potom Izrael za dnů Pelištejců dvacet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Potom šel Samson do Gazy. Uviděl tam prostitutku a vešel k ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Obyvatelům Gazy bylo řečeno: Přišel sem Samson. Obcházeli a číhali na něho celou noc v bráně toho města a celou tu noc tiše vyčkávali se slovy: Až do svítání a pak ho zabijeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Samson však ležel jen do půlnoci. Uprostřed noci vstal, uchopil ⌈vrata městské brány a obě veřeje a vyrazil je i se závorou.⌉ Položil si je na ramena a vynesl na vrchol hory, která se tyčí směrem k Chebrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'I stalo se potom, že se zamiloval do ženy v údolí Sorék jménem Delíla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Vypravili se k ní tedy pelištejští vladaři a řekli jí: Umluv ho a zjisti, v čem spočívá jeho velká síla a čím jej přemůžeme a svážeme, abychom ho pokořili. My ti dáme každý tisíc sto šekelů stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'A tak Delíla řekla Samsonovi: Pověz mi, prosím, v čem spočívá tvá velká síla a čím můžeš být spoután, abys byl poražen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Samson jí pověděl: Jestliže mě svážou sedmi syrovými lany, která nebyla vysušena, zeslábnu a budu jako kterýkoli jiný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Pelištejští vladaři jí tedy přinesli sedm syrových lan, která nebyla vysušena, a těmi ho svázala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Ti, kdo na něj číhali, seděli u ní v pokoji. Řekla mu: Jdou na tebe Pelištejci, Samsone! Zpřetrhal ta lana, jako se přetrhne šňůrka z koudele, když se přiblíží k ohni, a jeho síla nebyla odhalena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Nato Delíla Samsonovi řekla: Vida, podváděl jsi mě a vykládal jsi mi lži. Nyní mi prosím pověz, čím můžeš být spoután.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Řekl jí: Jestliže mě pevně svážou novými popruhy, s nimiž nebyla konána práce, zeslábnu a budu jako kterýkoli jiný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Delíla tedy vzala nové popruhy a svázala ho jimi. Pak mu řekla: Jdou na tebe Pelištejci, Samsone! Ti, kdo na něj číhali, seděli v pokoji. Ale on je na svých pažích zpřetrhal jako šňůry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Delíla nato Samsonovi řekla: Až doposud jsi mě podváděl a vykládal jsi mi lži. Pověz mi, čím můžeš být spoután. Řekl jí: Stačí, když vetkáš sedm pramenů vlasů mé hlavy do osnovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Upevnila osnovu ještě kolíkem a řekla mu: Jdou na tebe Pelištejci, Samsone! On se probral ze spánku a vytrhl ten kolík, člunek i osnovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Nato mu řekla: Jak můžeš říkat: Miluji tě, když tvé srdce není se mnou? Takhle jsi mě třikrát podvedl a nepověděl jsi mi, v čem spočívá tvá velká síla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'I stalo se, když na něho naléhala svými slovy celé dny, dotírala na něho, že se jeho duše k smrti unavila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Tu jí otevřel celé své srdce a řekl jí: Na mou hlavu nevstoupila břitva, protože od lůna své matky jsem Boží nazír. Pokud bych byl oholen, odstoupí ode mě má síla, zeslábnu a budu jako každý jiný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Když Delíla viděla, že jí otevřel celé své srdce, vzkázala a zavolala pelištejské vladaře: Tentokrát přijďte, protože mi otevřel celé své srdce. Pelištejští vladaři k ní přišli a přinesli s sebou stříbro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'I uspala jej na svých kolenou, pak zavolala jednoho muže a nechala oholit sedm pramenů vlasů jeho hlavy. ⌈Začala ho ponižovat⌉ a jeho síla od něj odstoupila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Opět řekla: Jdou na tebe Pelištejci, Samsone! Probral se ze spánku a řekl si: Vyjdu z toho jako toli krát předtím a otřepu se. On nevěděl, že se od něj Hospodin odvrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Pelištejci ho chytili, vyloupali mu oči, zavedli ho do Gazy a svázali ho bronzovými okovy. Byl přinucen mlít ve vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Tam, kde byl oholen, mu ale vlasy na hlavě začaly dorůstat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Pelištejští vladaři se shromáždili, aby obětovali velký obětní hod pro svého boha Dágona a pro radost. Řekli: Náš bůh nám vydal do ruky našeho nepřítele Samsona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Když ho lid viděl, chválil svého boha, neboť řekl: Náš bůh nám vydal do ruky našeho nepřítele a pustošitele naší země, který rozmnožil naše pobité.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'I stalo se, ⌈když jim bylo dobře u srdce,⌉ že řekli: Zavolejte Samsona, ať nás baví. Zavolali tedy Samsona z vězení, dováděl před nimi a postavili ho mezi sloupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Tu řekl Samson mládenci, který ho držel za ruku: Pusť mě a nech mě ohmatat ty sloupy, kterými je dům držen, ať se o ně opřu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Ten dům byl plný mužů a žen, byli tam všichni pelištejští vladaři a na střeše asi tři tisíce mužů a žen, kteří se dívali, jak je Samson baví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'I volal Samson k Hospodinu. Řekl: Panovníku Hospodine, rozpomeň se, prosím, na mě a posilni mě, prosím, ještě tentokrát, Bože, ať se Pelištejcům pomstím jedinou pomstou za obě své oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Pak Samson pevně objal oba prostřední sloupy, kterými byl dům držený, a vzepřel se o ně, o jeden svou pravicí a o druhý svou levicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Samson řekl: Ať má duše zemře s Pelištejci. Napnul sílu a ten dům spadl na vladaře a na všechen lid, který v něm byl. Mrtvých, které usmrtil při svém skonu, bylo více, než těch, které usmrtil za svého života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Potom sestoupili jeho bratři a celý dům jeho otce, vyzvedli ho, vynesli a pohřbili ho mezi Soreou a Eštaólem do hrobu jeho otce Manóacha. On soudil Izrael dvacet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Byl jeden muž z efrajimského pohoří jménem Míkajáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Ten řekl své matce: Tisíc sto šekelů stříbra, které ti bylo vzato a ty jsi kvůli němu vyslovila kletbu a také jsi mi ji řekla, hle, to stříbro je u mě. Vzal jsem ho já. Jeho matka řekla: Můj synu, ⌈jsi požehnaný Hospodinu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'A vrátil těch tisíc sto šekelů stříbra své matce. Jeho matka řekla: To stříbro jsem cele oddělila pro Hospodina od sebe svému synovi, aby zhotovil tesanou a litou modlu. Nyní ti je vracím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'On to stříbro vrátil své matce. Jeho matka vzala dvě stě šekelů stříbra, dala ho zlatníkovi a ten mu zhotovil tesanou a litou modlu, která stála v Míkajášově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Ten muž Míka měl dům bohů, zhotovil si efód a domácího bůžka. Zplnomocnil jednoho ze svých synů a ten se mu stal knězem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'V oněch dnech ne byl v Izraeli král; každý dělal, co bylo v jeho očích správné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Byl pak jeden mládenec z judského Betléma, z Judovy čeledi. Byl to lévita pobývající tam jako cizinec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Ten muž odešel z města, z judského Betléma, aby jako cizinec pobýval, kde se naskytne, a přišel do efrajimského pohoří až k Míkovu domu, ⌈jak konal svou pouť.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Tu se ho Míka zeptal: Odkud přicházíš? Řekl mu: Jsem lévita z judského Betléma a putuji, abych jako cizinec pobýval, kde se naskytne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Nato mu Míka řekl: Zůstaň se mnou a buď mi otcem a knězem. Já ti dám deset šekelů stříbra na rok, ⌈řádné ošacení⌉ a stravu. Lévita tedy šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'A lévita byl ochoten u toho muže zůstat. Ten mládenec pro něho byl jako jeden z jeho synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Míka lévitu zplnomocnil, on se stal jeho kněžským služebníkem a zůstal v Míkově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Míka tehdy řekl: Nyní jsem poznal, že mi Hospodin bude prokazovat dobro, protože se u mě stal knězem ten lévita.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'V oněch dnech ne byl v Izraeli král. A v oněch dnech pro sebe danovský kmen hledal dědictví, aby se usídlil, protože mu až do onoho dne nepřipadlo mezi izraelskými kmeny nic do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Synové Danovi tedy poslali pět mužů ze své čeledi, bojovníků ze svých končin ze Soreje a z Eštaólu, aby prozkoumali zemi a aby ji důkladně prohlédli. Řekli jim: Jděte a důkladně prohlédněte tu zemi. Přišli do efrajimského pohoří až k Míkovu domu a nocovali tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Když byli u Míkova domu, všimli si hlasu toho lévijského mládence. Zašli tam a zeptali se ho: Kdo tě sem přivedl? Co tady děláš? Co to tu máš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Odpověděl jim: To a to se mnou Míka dojednal, najal mě a já jsem se mu stal knězem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Nato mu řekli: Prosíme, doptávej se Boha, ať poznáme, zdali dopřeje úspěch naší cestě, po níž jdeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Kněz jim řekl: Jděte v pokoji. Vaše cesta, po níž půjdete, je před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Těch pět mužů šlo, přišli do Lajiše a viděli lid, který v něm byl poklidný, bydlel v bezpečí po způsobu Sidónců a byl bezstarostný. Nikdo v zemi nepotupoval úmluvu, ne získával vlastnictví mocí. Byli daleko od Sidónců a neměli s nikým úmluvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Vrátili se ke svým bratrům do Soreje a Eštaólu. Jejich bratři se jich zeptali: ⌈Jak jste na tom?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Odpověděli: Vstaňte a vytáhneme proti nim, protože jsme viděli tu zemi a hle, je velmi dobrá, ale vy jste neteční. Nebuďte líní jít, vstoupit do té země a obsadit ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Až vytáhnete, přijdete k bezstarostnému lidu a země je rozlehlá na všechny strany, vždyť Bůh ji vydal do vaší ruky -- místo, kde není nouze vůbec v ničem, co bývá na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'I vyrazilo odtamtud z danovské čeledi, ze Soreje a z Eštaólu, šest set mužů, přepásaných válečnými zbraněmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Vytáhli a utábořili se u Kirjat–jearímu v Judsku. Kvůli tomu nazvali ono místo Danovský tábor a je tomu tak až do tohoto dne. Všimněte si ho za Kirjat–jearímem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Odtamtud prošli efrajimským pohořím a přišli až k Míkovu domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Tu promluvilo těch pět mužů, kteří se vydali prozkoumat zemi Lajiš. Řekli svým bratrům: Zdalipak víte, že je v těchto domech efód, domácí bůžek a tesaná a litá modla? Nuže, rozvažte, co provedete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Zašli tam tedy, přišli k domu toho lévijského mládence, k domu Míkovu, a ⌈zeptali se ho, jak se mu daří,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'zatímco šest set mužů z Danových synů, přepásaných válečnými zbraněmi, stálo u vchodu do brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Pak vystoupilo těch pět mužů, kteří se vydali prozkoumat zemi. Přišli tam, vzali tu tesanou modlu a efód, domácího bůžka i litou modlu. Kněz přitom stál u vchodu do brány se šesti sty muži, přepásanými válečnými zbraněmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Když ti muži vešli do Míkova domu a vzali tesanou modlu, efód, domácího bůžka a litou modlu, zeptal se jich kněz: Co to děláte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Odpověděli mu: Mlč, polož si ruku na ústa a pojď s námi. Buď nám otcem a knězem. Co je lepší: Abys byl knězem domu jednoho muže, nebo abys byl knězem kmene a čeledi v Izraeli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'To se srdci toho kněze líbilo. Vzal efód, domácího bůžka a tesanou modlu a vstoupil mezi lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Nato se obrátili a vyšli. Malé děti, dobytek a cenný majetek umístili před sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Vzdálili se od Míkova domu a tu se shromáždili muži z domů, které stály u domu Míkova, a stíhali syny Danovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Křičeli na syny Danovy. Ti se ohlédli a řekli Míkovi: Jaké máš přání, že ses shromáždil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Odpověděl jim: Vzali jste mé bohy, které jsem zhotovil, a kněze a odešli jste. Co se mnou bude dál? Jak se mě můžete ptát: Jaké máš přání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Nato mu synové Danovi řekli: Nezvyšuj na nás hlas, jinak se na vás vrhnou rozhořčení muži a ztratíš život svůj i život svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Synové Danovi pak šli svou cestou. Když Míka viděl, že jsou silnější než on, obrátil se a vrátil se domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Oni vzali s sebou to, co si Míka zhotovil, a kněze, kterého měl, a přitáhli k Lajiši na poklidný a bezstarostný lid. Pobili je ostřím meče a město spálili ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'A nebyl, kdo by město vysvobodil, protože bylo daleko od Sidónu a neměli s nikým úmluvu. Bylo v údolí u Bét–rechóbu. Synové Danovi to město opět postavili a usadili se v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Tehdy nazvali to město jménem Dan podle jména svého otce Dana, který se narodil Izraelovi. Původně však mělo to město jméno Lajiš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Synové Danovi tam tu tesanou modlu postavili pro sebe a Jónatan, syn Geršóma, syna Mojžíšova, on i jeho synové se stali kněžími pro danovský kmen až do dne vystěhování té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Míkovu tesanou modlu, kterou zhotovil, tam měli pro sebe umístěnou po všechny dny, kdy byl dům Boží v Šílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'I stalo se ⌈v oněch dnech, kdy ne byl v Izraeli král,⌉ že nějaký lévita pobývající jako cizinec v odlehlých končinách efrajimského pohoří si vzal konkubínu z judského Betléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Jeho konkubína ⌈mu byla nevěrná,⌉ odešla od něj do domu svého otce do judského Betléma a zůstala tam po dobu čtyř měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Tu její muž vstal a šel za ní, promluvit k jejímu srdci, aby se navrátila. Byl s ním jeho služebník a oslí spřežení. I uvedla jej do domu svého otce. Když ho otec té dívky spatřil, zaradoval se, že se s ním setkává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Jeho tchán, otec dívky, ho přemluvil, a tak s ním tři dny pobyl. Jedli, pili a nocovali tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'I stalo se čtvrtého dne, když časně ráno vstali a povstal k odchodu, že otec dívky řekl svému zeťovi: Posilni se kouskem chleba a potom půjdete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Zůstali tedy, ti dva spolu jedli a pili a otec dívky tomu muži řekl: Prosím, buď tak laskav a přenocuj, ⌈ať je ti dobře u srdce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Ten muž vstal k odchodu, ale jeho tchán ho přinutil, a tak se vrátil a znovu tam přenocoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Pátý den vstal k odchodu časně zrána. Otec té dívky řekl: Posilni se přece a zdržte se, než den pokročí. A oba pojedli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Když vstal ten muž k odchodu, on i jeho konkubína a jeho služebník, tu mu řekl jeho tchán, otec dívky: Podívej se přece, den se nachýlil ⌈a nastává večer.⌉ Ano, zůstaňte přece přes noc, dnes si lehněte. Přenocuj tady, ⌈ať je ti dobře u srdce⌉ a zítra časně vstanete na svou cestu a odejdeš ke svému stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Muž ale nechtěl přenocovat. Vstal, vyšel a přišel až naproti Jebúsu, což je Jeruzalém, a s ním osedlané oslí spřežení a jeho konkubína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Byli u Jebúsu a den velmi pokročil. Tu řekl služebník svému pánu: Pojďme prosím, zajděme do tohoto jebúsejského města a přenocujme v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Jeho pán mu odpověděl: Nezajdeme do města cizozemců, kteří nejsou ze synů Izraele. Projdeme až do Gibeje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'A řekl svému služebníku: Pojď, přiblížíme se k jednomu z těch míst. Přenocujeme v Gibeji nebo v Rámě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Prošli tedy tím místem, šli a slunce jim zapadlo u Gibeje, která patří Benjamínovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'A odbočili tam, aby došli do Gibeje a přenocovali. Přišel a posadil se na náměstí toho města, ale nebyl nikdo, kdo by je přijal do domu, aby mohli přenocovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Vtom hle, nějaký stařec přichází večer z pole od svého díla. Ten muž byl z efrajimského pohoří a jako cizinec pobýval v Gibeji. Muži toho místa byli ovšem synové Ben jamínovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Když pozvedl své oči a spatřil toho muže, poutníka, na náměstí města, zeptal se ten starý muž: Kam jdeš a odkud přicházíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Odpověděl mu: Procházíme z judského Betléma až do odlehlých končin efrajimského pohoří, odkud pocházím. Šel jsem do judského Betléma, jsem poutník, a teď jdu do Hospodinova domu. Není však, kdo by mě přijal do domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Mám i slámu a krmivo pro naše osly a také chléb a víno mám pro sebe i pro tvou služebnici a pro služebníka, kterého mají tví otroci s sebou. Vůbec v ničem nemám nouzi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Nato řekl ten stařec: Pokoj tobě. Jen uval všechnu svou nouzi na mě. Jenom nezůstávej přes noc na náměstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Přivedl ho do svého domu, namíchal krmení pro osly a umyli si nohy. Pak jedli a pili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Když se posilňovali, hle, muži toho města, ničemníci, obklíčili dům, tloukli na dveře a volali na starce, vlastníka domu: Vyveď toho muže, který přišel do tvého domu, ať ho poznáme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Vlastník domu k nim vyšel a řekl jim: Ne, bratři moji, nepáchejte přece zlo poté, co tento muž přišel do mého domu. Nedopouštějte se takového bláznovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Zde je má dcera, panna, a jeho konkubína. Ihned je vyvedu. Ponižte je a udělejte s nimi, co je vám libo, ale proti tomuto muži se nedopouštějte žádného takového bláznovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Ti muži ho však nechtěli poslechnout. Tu se ten muž chopil své konkubíny a vyvedl ji k nim na ulici. Poznali ji a vyžívali se na ní celou noc až do rána a propustili ji ⌈při východu⌉ jitřenky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Ráno ta žena přišla nazpět a zhroutila se u vchodu do domu toho muže, kde byl její pán. Ležela tam až do svítání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Její pán ráno vstal, otevřel dveře domu a vyšel, aby se vydal na cestu, a hle, žena, jeho konkubína, leží u vchodu do domu a její ruce jsou na prahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Řekl jí: Vstaň a půjdeme, ale ona neodpovídala. Vzal ji tedy na osla. I vstal ten muž a vydal se k domovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Když přišel do svého domu, vzal nůž, uchopil konkubínu, rozsekal ji podle jejích kostí na dvanáct dílů a rozeslal ji po celém území Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Ať každý, kdo to vidí, řekne: Nestalo se ani nebylo viděno něco takového ode dne, kdy vyšli synové Izraele z egyptské země, až do tohoto dne. ⌈Zvažte to,⌉ poraďte se a vyslovte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Tehdy přišli všichni synové Izraele a obec se shromáždila jako jeden muž od Danu až po Beer–šebu i zemi Gileád k Hospodinu do Mispy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Vůdcové všeho lidu ze všech izraelských kmenů se postavili ve shromáždění Božího lidu, čtyři sta tisíc mužů, pěšáků schopných tasit meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Synové Benjamínovi slyšeli, že synové Izraele vytáhli do Mispy. Synové Izraele se ptali: Povězte, jak se stalo takové zlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Nato odpověděl lévita, muž té zavražděné ženy. Řekl: Já jsem se svou konkubínou přišel přenocovat do Gibeje, která patří Benjamínovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Občané Gibeje však proti mně povstali a obklíčili kvůli mně v noci dům. Mě zamýšleli zabít a mou konkubínu ponižovali, až zemřela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Tu jsem svou konkubínu uchopil, rozsekal jsem ji na kusy a poslal jsem ji na celé území izraelského dědictví, protože oni spáchali v Izraeli hanebnost a bláznovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Hle, vy všichni jste synové Izraele; ujměte se tady té záležitosti a učiňte rozhodnutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Tehdy všechen lid povstal jako jeden muž se slovy: Nikdo nepůjdeme ke svému stanu a nikdo neodejdeme do svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Nuže, toto je věc, kterou provedeme s Gibejí: Potáhneme proti ní podle losu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Vezmeme tedy deset mužů ze sta od každého z izraelských kmenů a sto z tisíce a tisíc z desetitisíce, aby vzali zásobu potravin pro lid, který přitáhne na Benjamínovu Gebu, aby s ní naložil podle všeho bláznovství, které spáchala v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Tak ⌈se odebrali všichni izraelští muži⌉ k tomu městu jako jeden muž -- spojenci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Dále poslaly izraelské kmeny muže do všech Benjamínových kmenů se slovy: ⌈Jaké zlo se to u vás stalo?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Nyní tedy vydejte ty ničemníky, kteří jsou v Gibeji. Usmrťme je a vyhlaďme zlo z Izraele. Ale synové Benjamínovi nechtěli uposlechnout své bratry, syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Pak se synové Benjamínovi shromáždili z měst do Gibeje, aby vytáhli do boje se syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'V onen den bylo napočítáno synů Benjamínových z měst dvacet šest tisíc mužů schopných tasit meč, mimo sedmi set vybraných mužů, kteří byli napočítáni z obyvatel Gibeje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Ze všeho tohoto lidu bylo vybráno sedm set mužů ⌈nevládnoucích pravou rukou;⌉ každý z nich vrhal z praku kámen nachlup přesně a neminul cíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Izraelských mužů bylo napočítáno mimo Benjamínců čtyři sta tisíc mužů schopných tasit meč; všichni to byli bojovníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Povstali, vystoupili do Bét–elu a doptávali se Boha. Synové Izraele se ptali: Kdo z nás má vytáhnout jako první do bitvy se syny Benjamínovými? Hospodin odpověděl: Juda půjde jako první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Ráno tedy synové Izraele povstali a utábořili se u Gibeje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Pak ⌈vytáhli izraelští muži⌉ do bitvy s Benjamínci. Izraelští muži se proti nim sešikovali k bitvě u Gibeje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Vtom vytáhli synové Benjamínovi z Gibeje a srazili v Izraeli v onen den dvacet dva tisíc mužů k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Ale lid, izraelští muži, se posilnili a znovu se sešikovali k boji na místě, kde se sešikovali prvního dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Tehdy synové Izraele přišli a plakali před Hospodinem až do večera a doptávali se Hospodina: To se máme znovu pustit do boje se syny svého bratra Benjamína? Hospodin řekl: Vytáhněte proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Synové Izraele se tedy druhého dne přiblížili k synům Benjamínovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'I druhého dne jim Benjamín vytáhl naproti z Gibeje a srazil mezi syny Izraele znovu k zemi osmnáct tisíc mužů. Ti všichni byli ozbrojeni mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Tu vystoupili všichni synové Izraele a všechen lid, přišli do Bét–elu, plakali a pobývali tam před Hospodinem. V onen den se postili až do večera a přinesli před Hospodina zápalné a pohostinné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Pak se synové Izraele doptávali Hospodina; v oněch dnech tam byla truhla Boží smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'A Pinchas, syn Eleazara, syna Áronova, před ní v oněch dnech stál se slovy: To máme stále znovu táhnout do boje se syny svého bratra Benjamína, nebo máme přestat? Hospodin řekl: Vytáhněte, protože zítra ho vydám do tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Izrael pak umístil v okolí Gibeje zálohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Třetího dne vytáhli synové Izraele proti synům Benjamínovým a sešikovali se u Gibeje jako dvakrát předtím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'I synové Benjamínovi vytáhli naproti tomu lidu, odlákáni od města, a začali pobíjet některé z toho lidu, probodávat je jako již dvakrát předtím. Na silnicích, z nichž jedna vystupuje do Bét–elu a druhá do Gibeje, zůstalo v poli asi třicet mužů z Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Tu synové Benjamínovi řekli: Jsou před námi poraženi jako předtím. Synové Izraele však řekli: Utíkejme, odlákáme je od města k silnicím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'A všichni izraelští muži vstali ze svého místa a sešikovali se v Baal–támaře, zatímco se izraelská záloha vyřítila ze svého místa z Gebské planiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Odnaproti přitáhlo ke Gibeji deset tisíc mužů vybraných z celého Izraele. Rozpoutala se těžká bitva a oni nevěděli, že je zasáhla zhouba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'I porazil Hospodin Benjamína před Izraelem. Synové Izraele v onen den uvrhli do zkázy dvacet pět tisíc a sto mužů z Benjamína. Ti všichni byli ozbrojeni mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Synové Benjamínovi viděli, že jsou poraženi. Izraelští muži přenechali Benjamínovi území, protože spoléhali na zálohu, kterou umístili proti Gibeji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Tu ti ze zálohy přispěchali a vtrhli do Gibeje. Záloha vytáhla a pobila celé město ostřím meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Izraelští muži měli se zálohou určené znamení: Nechte z města vystupovat mnoho kouře, abyste jim dali znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Izraelští muži se v boji obrátili a Benjamínci začali pobíjet probodené z izraelských mužů, asi třicet mužů, protože si řekli: Jistě je před námi nadobro poražen jako v té první bitvě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Tehdy začalo vystupovat z města znamení -- sloup kouře. Benjamín se za ním ohlédl a hle, celé to město stoupalo v plamenech k nebesům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Tu se ⌈izraelští muži obrátili a muži Benjamínovi se vyděsili,⌉ protože zjistili, že je zasáhla zhouba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Obrátili se před izraelskými muži směrem do pustiny, ale válečná vřava jim byla v patách a ti, kteří vyšli z měst, je sráželi v jejich středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Obklíčili Benjamína, pronásledovali ho bez odpočinutí, šlapali mu na paty až před Gibeu na východu slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Tak padlo z Benjamína osmnáct tisíc mužů. Byli to samí bojovníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Ostatní se obrátili a utíkali do pustiny ke skále Rimónu. Dohledali z nich na silnicích pět tisíc mužů, ⌈stíhali je⌉ až ke Gideómu a pobili z nich dva tisíce mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Všech padlých z Benjamína bylo v onen den dvacet pět tisíc mužů schopných tasit meč. Byli to samí bojovníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Šest set mužů se však obrátilo a utíkali do pustiny ke skále Rimónu. Pobývali ve skále Rimónu čtyři měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Izraelští muži se pak vrátili k synům Benjamínovým a pobili je ostřím meče, muže z města, stejně jako zvíře, stejně jako všechno, co se našlo. Také všechna města, ⌈která objevili,⌉ podpálili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'A všichni izraelští muži v Mispě přísahali: Nikdo z nás nedá Benjamínci za ženu svou dceru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Potom lid přišel do Bét–elu, seděli tam až do večera před Bohem, ⌈pozvedli svůj hlas a dali se do velkého pláče.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'A ptali se: Hospodine, Bože Izraele, proč se tohle stalo v Izraeli, aby byl dnes od Izraele odečten jeden kmen?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'I stalo se příštího dne, že lid časně ráno vstal, postavili tam oltář a přinesli zápalné a pohostinné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Synové Izraele se pak zeptali: Kdo ze všech izraelských kmenů nevystoupil k Hospodinu do shromáždění? Protože byla vydána veliká přísaha proti tomu, kdo by nevystoupil k Hospodinu do Mispy: Jistě bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Synové Izraele totiž litovali svého bratra Benjamína a říkali: Dnes byl od Izraele odseknut jeden kmen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Co pro ně uděláme, pro ty zbývající Benjamínce, aby měli ženy? My jsme přece přísahali při Hospodinu, že jim nedáme za ženy žádné z našich dcer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'A ptali se: Kdo jako jediný z izraelských kmenů nevystoupil k Hospodinu do Mispy? A hle, z Jábeše v Gileádu nepřišel do tábora na shromáždění nikdo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Byl tedy spočítán lid a vida: Nikdo z obyvatel Jábeše v Gileádu tam nebyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'A tak tam poslali z obce dvanáct tisíc mužů z bojovníků a přikázali jim: Jděte, pobijete obyvatele Jábeše v Gileádu ostřím meče, rovněž ženy a malé děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Toto je věc, kterou učiníte každému muži a každé ženě, která poznala ulehnutí s mužem -- zasvětíte je zkáze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'I nalezli mezi obyvateli Jábeše v Gileádu čtyři sta dívek, panen, které nepoznaly muže při ulehnutí s mužem, a přivedli je do tábora v Šílu, které je v kenaanské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Celá obec pak vzkázala a promluvila k synům Benjamínovým, kteří byli ve skále Rimónu. Vyhlásili jim pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'V onen čas se tedy Benjamínci vrátili. Dali jim ženy, které zachovali při životě mezi ženami z gileádského Jábeše, ale tolik jich pro ně nenašli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Lid Benjamína litoval, protože Hospodin způsobil mezi izraelskými kmeny trhlinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Nato se starší obce zeptali: Jak to uděláme se ženami pro ty zbývající, když byly ženy z Benjamína vyhubeny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Řekli tedy: Benjamínovi náleží vlastnictví uprchlíka. Kmen nebude z Izraele vymazán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'My jim však nemůžeme dát ženy ze svých dcer, neboť synové Izraele přísahali: Proklet buď ten, kdo dá ženu Benjamínci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Pak řekli: Hle, ⌈rok co rok⌉ se koná Hospodinův svátek v Šílu, které je severně od Bét–elu, na východ slunce od silnice, která vystupuje z Bét–elu do Šekemu, a na jih od Lebóny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'A synům Benjamínovým přikázali: Jděte, budete číhat ve vinicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Budete se dívat a hle, až vyjdou šíloské dcery plesat v tancích, vyrazíte z vinic a chytíte si každý svou ženu ze šíloských dcer. Pak odejdete do benjamínské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'A stane– li se, že přijdou jejich otcové nebo bratři, aby s námi vedli spor, řekneme jim: Slitujte se nad námi kvůli nim, vždyť jsme nevzali pro každého ženu v boji. Protože vy jste jim je v pravý čas nedali, proviníte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Synové Benjamínovi tak učinili a unesli ženy podle svého počtu z tanečnic, které uchvátili. Potom odešli a navrátili se ke svému dědictví. Postavili města a usadili se v nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'A tak se v onen čas odtamtud synové Izraele rozešli, každý ke svému kmeni a ke své čeledi. Odešli odtamtud každý ke svému dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, '⌈V oněch dnech ne byl v Izraeli král; každý dělal, co bylo v jeho očích správné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'I stalo se za dnů, kdy soudili soudcové a v zemi nastal hlad, že jeden muž odešel z judského Betléma, aby pobýval jako cizinec na moábských polích -- on, jeho žena i jeho dva synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Jméno toho muže bylo Elímelek, jméno jeho ženy Noemi a jména jeho dvou synů Machlón a Kiljón, Efratejci z judského Betléma. Přišli na moábská pole a přebývali tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Potom Elímelek, Noemin muž, zemřel a ona zůstala sama se svými dvěma syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Ti si vzali moábské ženy (jméno jedné bylo Orpa a jméno té druhé Rút) a pobývali tam asi deset let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Pak zemřeli dokonce i ti dva, Machlón a Kiljón, a tak ta žena zůstala sama bez svých dvou dětí a bez svého muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Tu povstala ona i její snachy a navrátila se z moábských polí. V moábské krajině se totiž doslechla, že Hospodin navštívil svůj lid, ⌈aby mu dal chléb.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Odešla z toho místa, kde přebývala, a její dvě snachy s ní. Vydaly se na cestu zpět do judské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Tehdy řekla Noemi svým dvěma snachám: Jděte, vraťte se každá do domu své matky. Ať vám Hospodin prokáže milosrdenství, podobně jako jste vy jednaly s těmi, kdo zemřeli, i se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Hospodin vám dá, abyste nalezly odpočinutí každá v domě svého muže. A políbila je. Ony ⌈pozvedly svůj hlas a rozplakaly se.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Řekly jí: Přece se spolu s tebou vrátíme ke tvému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Ale Noemi odpověděla: Vraťte se moje dcery. Proč byste chodily se mnou? Cožpak se mi znovu objeví v lůně synové a budou vám dáni za muže?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Vraťte se moje dcery, jděte, protože už jsem stará. Nejsem na vdávání. I kdybych si namlouvala: Mám naději a dokonce ⌈se této noci vdala⌉ a navíc bych zplodila syny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'zdali proto budete trpělivě čekat až do doby, kdy vyrostou? Cožpak se kvůli tomu budete zdráhat vdát? Ne, moje dcery, vždyť ⌈je mi tuze hořko, více než vám,⌉ protože na mě dopadla Hospodinova ruka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Ony nato ⌈pozvedly svůj hlas a znovu se rozplakaly.⌉ Orpa svou tchýni políbila, ale Rút ⌈k ní přilnula.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Ta řekla: Hle, tvá švagrová se obrátila ke svému lidu a ke svým bohům. Obrať se i ty za svou švagrovou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Avšak Rút odpověděla: ⌈Nenaléhej na mě,⌉ abych tě opustila a odvrátila se od cesty za tebou, protože ⌈kam půjdeš, půjdu i já, a kde zůstaneš,⌉ zůstanu také; tvůj lid bude mým lidem a tvůj Bůh mým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Kde zemřeš, zemřu já a tam budu pohřbena. Ať mi tak učiní Hospodin a ještě přidá, že jedině smrt ⌈mě od tebe oddělí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Noemi viděla, že je odhodlaná jít s ní, a přestala ji přemlouvat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Tak šly obě dvě, až přišly do Betléma. I stalo se, jakmile přišly do Betléma, že se kvůli nim shluklo celé to město a ženy řekly: Není tohle Noemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Ona jim však odpověděla: Nenazývejte mě Noemi. Nazývejte mě Mara, protože mi Všemohoucí způsobil velikou hořkost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Já jsem odešla plná a Hospodin mě přivedl zpět prázdnou. Proč mě nazýváte Noemi, když Hospodin svědčí proti mně a Všemohoucí se mnou zle jedná?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'A tak se Noemi vrátila a s ní se vrátila její snacha, Moábka Rút, z moábských polí. Přišly do Betléma na počátku sklizně ječmene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Noemi měla příbuzného ze strany svého muže, ⌈mocného a zdatného člověka⌉ z Elímelekovy čeledi jménem Bóaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Moábka Rút řekla Noemi: Dovol, ať jdu na pole a posbírám klasy za někým, v jehož očích naleznu milost. A ona jí odpověděla: Běž, má dcero.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Šla, až došla na pole, a sbírala za ženci. Ocitla se náhodou na dílu pole patřícím Bóazovi, jenž byl z Elímelekovy čeledi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Bóaz právě přišel z Betléma a řekl žencům: ⌈Hospodin s vámi.⌉ Oni mu odpověděli: Hospodin ti požehnej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Bóaz se pak zeptal svého služebníka, který byl ustanoven nad ženci: Čí je tahle dívka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'A ten nad ženci ustanovený služebník mu odpověděl. Řekl: To je moábská dívka, která se vrátila spolu s Noemi z moábské krajiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Řekla mi: Dovol, ať sbírám a shromáždím, co zbylo ⌈v pokosech⌉ za ženci. ⌈Přišla a zůstala tu od samého rána až do této chvíle.⌉ Jen ⌈chvilku pobyla doma.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Bóaz řekl Rút: Slyšela jsi přece, má dcero, ať nechodíš sbírat na jiné pole. Již odsud neodcházej. Přidrž se nyní mých služek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Zaměř své oči na pole, které budou sklízet, a choď za nimi. Vždyť přikazuji služebníkům, aby se tě nedotýkali. A budeš– li mít žízeň, jdi k nádobám a napij se z té, kterou služebníci načerpají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Tehdy padla na tvář, poklonila se k zemi a zeptala se ho: Jak to, že jsem nalezla milost ve tvých očích, že sis mě všiml, i když jsem cizinka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Bóaz jí odpověděl. Řekl: Je mi dobře známo všechno, co jsi udělala pro svou tchýni po smrti svého muže; že jsi opustila svého otce, svou matku i svou rodnou zemi a odešla k lidu, který jsi nikdy dříve neznala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Ať Hospodin odplatí tvůj skutek a ať je dovršená tvá odměna od Hospodina, Boha Izraele, pod jehož křídla jsi přišla najít útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Nato řekla: ⌈Kéž naleznu milost ve tvých očích,⌉ můj pane, protože jsi mne potěšil a protože ⌈jsi mluvil k srdci⌉ své otrokyně, ačkoliv já nejsem rovna žádné tvé otrokyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'V době jídla jí Bóaz řekl: Přistup sem, pojez chléb a namoč si sousto v octě. Posadila se poblíž ženců. Nabídl jí pražené zrní a ona pojedla, nasytila se a ještě jí zbylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Pak vstala, aby sbírala. Bóaz přikázal svým služebníkům: I když bude sbírat ⌈v pokosech,⌉ neponižujte ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Spíš pro ni i schválně upouštějte z hrstí a nechte ji, ať sbírá a nenapomínejte ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Tak sbírala na poli až do večera a to, co nasbírala, vymlátila. Byla toho asi éfa ječmene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Odnesla si to a přišla do města. Když její tchýně viděla, co nasbírala, a když vyndala a dala jí, co jí zbylo po nasycení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'tu se jí tchýně zeptala: Kde jsi dnes sbírala, kde jsi pracovala? Buď požehnán ten, kdo si tě všiml. Oznámila tedy tchýni, u koho pracovala: Jméno toho muže, u kterého jsem dnes pracovala, zní Bóaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Nato Noemi své snaše řekla: On ⌈je požehnaný Hospodinu,⌉ který neodňal své milosrdenství živým ani mrtvým. Noemi jí dále řekla: Ten muž je náš příbuzný, je jedním z našich vykupitelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Moábka Rút pak řekla: Dokonce mi pověděl i toto: Přidrž se služebníků, které mám, dokud nebude celá moje sklizeň dokončena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Tehdy Noemi řekla své snaše Rút: Dobře, má dcero, že budeš vycházet s jeho služkami a nebudou na tebe dorážet na jiném poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Přidržela se tedy Bóazových služek, aby sbírala, až do konce sklizně ječmene a pšenice. Přitom bydlela se svou tchýní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Její tchýně Noemi jí řekla: Má dcero, ne měla bych snad pro tebe vyhledat místo odpočinku, kde by se ti dobře vedlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Vždyť Bóaz, s jehož služkami jsi byla, je náš příbuzný. Pohleď, v noci bude provívat na humně ječmen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Umyj se tedy, pomaž se, vezmi na sebe své oděvy a sestup na humno, ale nedávej se tomu muži poznat, ⌈dokud nedojí a nedopije.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Až si půjde lehnout, zjisti místo, kde leží, jdi, odhal jeho nohy a ulehni. On ti oznámí, co máš dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Ona jí nato odpověděla: Udělám všechno, co mi řekneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Pak sestoupila na humno a udělala všechno, co jí její tchýně přikázala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Bóaz pojedl, napil se a ⌈bylo mu dobře u srdce.⌉ Potom si šel lehnout na kraj hromady obilí. A ona potají přišla, odhalila jeho nohy a ulehla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'I stalo se uprostřed noci, že se ten muž otřásl, převalil se a vida: V nohách mu leží žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Zeptal se: Kdo jsi? Ona odpověděla: Jsem Rút, tvá služebnice. ⌈Rozprostři své křídlo nad⌉ svou služebnicí, vždyť jsi vykupitel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'On nato řekl: ⌈Jsi požehnaná Hospodinu,⌉ má dcero. Dobře jsi udělala. Tvé poslední milosrdenství je větší nežli první, když nechodíš za mládenci, ať chudými či bohatými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'A nyní se, má dcero, neboj. Udělám pro tebe všechno, co řekneš, protože ⌈celé naše město⌉ ví, že jsi zdatná žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Ano, opravdu jsem vykupitel. Je však ještě jiný vykupitel, bližší než já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Zůstaň tu přes noc. A ráno, jestliže ⌈tě on vykoupí,⌉ dobře, ať vykoupí. A pokud si tě nebude přát vykoupit, vykoupím tě tedy já, jakože živ je Hospodin. Spi až do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'A tak spala do rána v jeho nohách. Vstala však dříve, než by někdo mohl rozeznat svého bližního. Bóaz si myslel: Jen ať se nikdo nedozví, že na humno přišla žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Řekl ještě: Podej mi plachetku, kterou máš na sobě, a podrž ji. Podržela ji tedy a on naměřil ⌈šest měr ječmene⌉ a naložil to na ni. ⌈Pak šel do města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Ona přišla⌉ ke své tchýni a ta se zeptala: ⌈Jak jsi na tom,⌉ má dcero? Ona jí oznámila vše, jak s ní ten muž jednal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Řekla: Dal mi těchto šest měr ječmene, neboť mi pověděl: Nepůjdeš ke své tchýni s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Noemi pravila: Musíš počkat, má dcero, než se dozvíš, jak ta záležitost dopadne, protože ten muž nebude mít klid, pokud tu záležitost dnes nedotáhne do konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Bóaz mezitím vystoupil do brány a posadil se tam. Vykupitel, o němž Bóaz mluvil, tudy zrovna procházel. Zavolal tedy: Hej ty, zajdi sem a posaď se tu někde. A on zašel a usedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Bóaz přibral deset mužů ze starších toho města a řekl jim: Zasedněte tu. Oni se posadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Tomu vykupiteli řekl: Noemi, která se vrátila z moábské krajiny, prodává díl pole, které patřilo našemu bratru Elímelekovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'A tak jsem si řekl, že ⌈ti to dám na vědomí:⌉ Kup jej před těmito přísedícími a před staršími mého lidu. Jestliže vykoupíš, vykup. Ale pokud nevykoupíš, oznam mi to, ⌈ať to vím. Vždyť⌉ není, kdo ho smí vykoupit, kromě tebe a mne po tobě. On odpověděl: Já jej vykoupím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Bóaz řekl: V den, kdy koupíš to pole z ruky Noemi, ⌈kupuješ je i s Moábkou Rút,⌉ ženou zemřelého, abys dal povstat jménu zemřelého v jeho dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Ten vykupitel odpověděl: Nemohu to pro sebe vykoupit, jinak uvrhnu do zkázy vlastní dědictví. ⌈Nárokuj pro sebe mé výkupní právo⌉ ty, protože já vykoupit nemohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Dříve se dělalo v Izraeli při vykupování a při směně toto: Na potvrzení každého jednání zul jeden svůj sandál a dal ho druhému. Toto bývalo osvědčení v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Vykupitel tedy řekl Bóazovi: Kup to pro sebe. A zul si sandál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Bóaz řekl starším a všemu lidu: Jste mi dnes svědky, že jsem koupil z ruky Noemi všechno, co patřilo Elímelekovi, a všechno, co patřilo Kiljónovi a Machlónovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Také Machlónovu ženu, Moábku Rút, jsem koupil za ženu pro sebe, abych dal povstat jménu zemřelého v jeho dědictví a aby nebylo vyhlazeno jméno zemřelého z jeho bratrů a z ⌈jeho domovského města.⌉ Dnes jste toho svědky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Nato řekl všechen lid, který byl v bráně, a starší: ⌈ Jsme svědky.⌉ Dej Hospodin té ženě, která přichází do tvého domu, aby byla jako Ráchel a jako Lea, které obě vystavěly Izraelův dům. Jednej v Efratě udatně a zjednej si v Betlémě jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Ať je tvůj dům z potomstva, které ti Hospodin dá z této dívky, jako dům Peresa, kterého porodila Támar Judovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Tak si Bóaz vzal Rút a stala se jeho ženou. Vešel k ní a Hospodin jí dal otěhotnět a ona porodila syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Ženy tehdy řekly Noemi: Požehnaný Hospodin, jenž ti dnes neodepřel vykupitele. Ať se jeho jméno vyhlašuje v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'I stane se obnovením tvé duše, aby pečoval o tvé šediny, protože ho porodila tvá snacha, která tě miluje. Ona je pro tebe lepší než sedm synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Noemi dítě vzala, položila si ho na klín a stala se mu vychovatelkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'A sousedky mu daly jméno se slovy: Noemi se narodil syn. A nazvaly ho jménem Obéd. On je otec Jišaje, otce Davidova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'A toto je rodopis Peresův: Peres zplodil Chesróna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Chesrón zplodil Ráma, Rám zplodil Amínadaba,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amínadab zplodil Nachšóna, Nachšón zplodil Salmu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmón zplodil Bóaza, Bóaz zplodil Obéda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obéd zplodil Jišaje, Jišaj zplodil Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Byl jeden muž, z Ramatajim–sófímu, z ⌈Efrajimského pohoří,⌉ který se jmenoval Elkána, syn Jerocháma, syna Elíhúa, syna Tochúa, syna Súfova, Efratejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Měl dvě ženy: Jméno jedné bylo Chana, jméno druhé Penina. Penina měla děti, ale Chana děti neměla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Tento muž přicházel ⌈rok co rok⌉ ze svého města, aby se klaněl a obětoval Hospodinu zástupů v Šílu. Tam byli Hospodinovými kněžími dva synové Élího, Chofní a Pinchas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Stávalo se v den, kdy Elkána obětoval, že dával své ženě Penině a všem jejím synům i jejím dcerám díly z oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Ale Chaně dával ⌈dvojnásobný díl,⌉ protože Chanu miloval; Hospodin však zavřel její lůno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Její protivnice ji velmi provokovala ke hněvu, jen aby ji rozzlobila kvůli tomu, že Hospodin zavřel její lůno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'To se dělo rok co rok; pokaždé, když přicházela do Hospodinova domu, takto ji provokovala ke hněvu. Proto Chana plakala a nejedla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Její muž Elkána jí řekl: Chano, proč pláčeš? Proč nejíš? Proč jsi skleslá na mysli? Cožpak nejsem pro tebe lepší nežli deset synů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, '⌈Po jednom takovém jídle a pití⌉ v Šílu Chana vstala. (Kněz Élí seděl na stolci u veřejí Hospodinova chrámu.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'V duši měla hořkost, modlila se k Hospodinu a velmi plakala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Učinila slib. Řekla: Hospodine zástupů, jestliže opravdu pohlédneš na soužení své otrokyně a vzpomeneš na mě, nezapomeneš na svou otrokyni a dáš své otrokyni ⌈mužského potomka,⌉ dám ho Hospodinu pro všechny dny jeho života a břitva nepřijde na jeho hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Stalo se, že když ⌈se zabrala do modlitby⌉ před Hospodinem, Élí pozoroval její ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Chana mluvila ve svém srdci, jenom její rty se pohybovaly, ale její hlas slyšet nebylo. Proto si o ní Élí myslel, že je opilá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Élí jí řekl: Jak dlouho budeš opilá? ⌈Odlož to víno!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Chana odpověděla: Ne, můj pane. Jsem žena ⌈obtížená na duchu.⌉ Nepila jsem víno ani pivo, ale vylévala jsem svou duši před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Nepokládej svou otrokyni za ničemnici, neboť doposud jsem mluvila ⌈kvůli množství otravování a provokací vůči mně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Élí odpověděl: ⌈Jdi v pokoji!⌉ Ať ti Bůh Izraele dá to, co jsi od něj žádala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Řekla: Kéž tvá služka nalezne ⌈milost ve tvých očích!⌉ Potom ta žena šla svou cestou, najedla se a její tvář už nebyla smutná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Časně ráno vstali, poklonili se před Hospodinem a vraceli se zpět, až přišli do svého domu v Rámě. Elkána poznal svou ženu Chanu a Hospodin si na ni vzpomněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Stalo se ⌈na konci roku,⌉ že Chana otěhotněla a porodila syna. Pojmenovala ho Samuel, neboť řekla: Vyžádala jsem si ho od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Potom ten muž Elkána šel s celým svým domem, aby obětoval Hospodinu každo roční oběť a splnil svůj slib.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Chana však nešla, protože řekla svému muži: Až bude chlapec odstaven, tehdy ho přivedu, aby se ukázal ⌈před Hospodinem⌉ a zůstal tam navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Nato jí její muž Elkána řekl: Udělej, co je ⌈ti libo.⌉ Zůstaň, dokud ho ne odstavíš. Jen ať Hospodin naplní své slovo. Žena tedy zůstala a kojila svého syna, dokud ho ne odstavila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Když ho odstavila, přivedla ho s sebou, k tomu tři býčky, jednu éfu mouky a měch vína. Přivedla ho do Hospodinova domu v Šílu. ⌈Chlapec byl ještě malý.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Zabili býčka a přivedli chlapce k Élímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Řekla: Dovol, můj pane! Jakože jsi živ, můj pane, já jsem ta žena, která tu stála u tebe a modlila se k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Modlila jsem se za tohoto chlapce a Hospodin mi dal to, co jsem od něj žádala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Proto jsem ho také propůjčila, po všechny dny, co bude žít, je propůjčen Hospodinu. A klaněli se tam Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Chana se takto modlila: Mé srdce se veselí z Hospodina, můj roh se pozvedá dík Hospodinu, má ústa se otevírají dokořán na mé nepřátele, neboť se raduji ze tvé záchrany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Nikdo ne ní svatý jako Hospodin, ano ne ní kromě tebe, ⌈ne ní taková skála⌉ jako náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, '⌈Nemnožte povýšená slova,⌉ drzost ať ne vyjde z vašich úst, vždyť Hospodin je Bohem poznání, ⌈on zvažuje⌉ činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Luky hrdinů jsou zlomeny, ale ti, kdo klopýtali, se přepásali udatností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, '⌈ Ti, kdo byli nasyceni,⌉ jsou najati za pokrm, ti, kdo byli hladoví, přestali hladovět. Dokonce neplodná posedmé rodí, a ta, která měla mnoho synů, vadne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Hospodin usmrcuje i oživuje, přivádí do podsvětí i vyvádí z něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Hospodin činí chudým i zbohacuje, ponižuje i povyšuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Pozvedá chudého z prachu, vytahuje nuzného ze smetiště, aby je posadil se šlechtici a dal jim do dědictví ⌈slavný trůn.⌉ Neboť Hospodinu patří sloupy země, na ně položil svět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Chrání nohy svých věrných, ale ničemové zahynou v temnotě, neboť člověk nezvítězí vlastní silou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, '⌈Ti, kdo vedou při s Hospodinem,⌉ budou otřeseni, zahřmí proti nim ⌈z nebes,⌉ Hospodin bude soudit končiny země, dá sílu svému králi a vyvýší roh svého pomazaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Elkána šel ⌈do svého domu v Rámě⌉ a chlapec sloužil Hospodinu v přítomnosti kněze Élího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Synové Élího byli ničemníci, neznali Hospodina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, '⌈ani kněžské nařízení pro lid. Kdykoliv⌉ někdo obětoval oběť, ještě když se maso vařilo, přicházel kněžský mládenec s trojzubou vidlicí v ruce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'vrazil ji do pekáče nebo do kotlíku nebo do kotle nebo do hrnce a všechno, co vidlice vytáhla, bral si kněz pro sebe. ⌈Takto jednali vůči všem Izraelcům,⌉ kteří tam do Šíla přicházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Dokonce dříve než obětovali tuk, přicházel kněžský mládenec a říkal tomu, kdo obětoval: Dej maso na pečeni pro kněze. Nevezme od tebe maso vařené, ale syrové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Když mu ten člověk řekl: Nejprve musí být obětován tuk, pak si vezmi to, po čem dychtíš, mládenec říkal: Ne, ale dej teď! Jestliže ne dáš, vezmu si to násilím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Hřích těchto mládenců byl před Hospodinem velmi veliký, protože tito muži opovrhovali Hospodinovou přídavnou obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel však sloužil před Hospodinem, chlapec přepásaný lněným efódem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Jeho matka mu dělávala malý plášť a přinášela mu ho ⌈rok co rok,⌉ když přicházela se svým mužem obětovat každo roční oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Élí požehnal Elkánovi a jeho ženě slovy: Ať ti Hospodin dá potomstvo z této ženy namísto toho, kterého vyžádala Hospodinu. Potom šli na ⌈své místo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Hospodin navštívil Chanu, otěhotněla a porodila tři syny a dvě dcery. Chlapec Samuel vyrůstal ⌈s Hospodinem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Élí byl velmi starý. Slyšel o všem, co páchali jeho synové celému Izraeli, i o tom, že spávali s ženami, které konaly službu u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Řekl jim: Proč děláte takové věci? ⌈Od všeho tohoto lidu slyším o vašem zlém jednání!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ne, moji synové! To ne ní dobrá zpráva, ⌈která, jak slyším, koluje mezi Hospodinovým lidem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Jestliže člověk zhřeší proti člověku, přimluví se za něj Bůh. Ale jestliže někdo zhřeší proti Hospodinu, kdo se přimluví za něj? Ale neuposlechli svého otce, neboť Hospodin se rozhodl je usmrtit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Chlapec Samuel rostl v postavě i ⌈oblibě jak u Hospodina, tak i u lidí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'I přišel k Élímu muž Boží a řekl mu: ⌈Toto praví Hospodin:⌉ Cožpak jsem se jasně ne zjevil ⌈domu tvého otce,⌉ když byli v Egyptě, v domě faraonově?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Ze všech izraelských kmenů jsem si ho vyvolil za kněze, aby obětoval na mém oltáři, pálil kadidlo a nosil přede mnou efód. Domu tvého otce jsem dal všechny ohnivé oběti ⌈synů Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Proč pohrdáte mým obětním hodem a přídavnou obětí, které jsem přikázal ve svém příbytku? Ctil jsi své syny víc než mě, když jste tloustli nejlepším ze všech přídavných obětí Izraele, mého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Proto je toto výrok Hospodina, Boha Izraele: Opravdu jsem řekl: Tvůj dům a dům tvého otce bude přicházet ⌈přede mne⌉ navěky. Ale nyní je toto Hospodinův výrok: Ať je to ode mne vzdáleno, protože ty, kdo mne ctí, poctím, ale ti, kdo mnou opovrhují, budou prokleti!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Hle, přicházejí dny, kdy ⌈odejmu tvou sílu⌉ a sílu domu tvého otce, takže ⌈ve tvém domě nebude stařec.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Uvidíš tíseň v mém příbytku při všem, co bude v Izraeli dáno do pořádku; ⌈ve tvém domě nebude po všechny dny stařec.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Nevyhladím ti od svého oltáře každého, abych skoncoval s tvýma očima a utrápil tvou duši, a všechen přírůstek tvého domu zemře v mužném věku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'A znamením ti bude to, co přijde na tvé dva syny, na Chofního a Pinchasa: Oba zemřou v jeden den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Ustanovím si však věrného kněze, který bude jednat podle mého srdce a podle mé duše. Postavím mu trvalý dům a bude přicházet před mého pomazaného po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'I stane se, že každý, kdo bude ze tvého domu ponechán, přijde se mu klanět za trochu peněz a bochník chleba a řekne: Připoj mě, prosím, k jedné z kněžských skupin, abych mohl jíst kousek chleba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Chlapec Samuel sloužil Hospodinu v přítomnosti Élího. V oněch dnech bylo Hospodinovo slovo vzácné a vidění nebylo obvyklé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, '⌈V onom čase⌉ se stalo, že Élí ležel na svém místě; jeho oči už začínaly slábnout, takže neviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Boží lampa ještě nezhasla a Samuel ležel v Hospodinově chrámě, kde byla Boží truhla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Tehdy Hospodin zavolal Samuela a on odpověděl: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Pak běžel k Élímu a řekl: Tady jsem, volal jsi mě? On však řekl: Nevolal jsem. Vrať se a lehni si. Šel a lehl si.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Hospodin zavolal znovu: Samueli! Samuel vstal, šel k Élímu a řekl: Tady jsem. Volal jsi mě? On však řekl: Nevolal, můj synu. Vrať se a lehni si.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel ještě neznal Hospodina a Hospodinovo slovo mu ještě nebylo zjeveno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Znovu, potřetí, zavolal Hospodin Samuela. On vstal, šel k Élímu a řekl: Tady jsem. Volal jsi mě? Vtom Élí pochopil, že chlapce volá Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Nato Élí Samuelovi řekl: Jdi a lehni si. A jestliže tě bude volat, řekni: Mluv, Hospodine, neboť tvůj otrok slyší. Samuel šel a lehl si na své místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Potom přišel Hospodin, stál tam a zavolal ⌈jako předtím:⌉ ⌈Samueli, Samueli!⌉ Samuel řekl: Mluv, neboť tvůj otrok slyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Hospodin Samuelovi řekl: Hle, učiním v Izraeli něco takového, že každému, kdo o tom uslyší, bude znít v obou uších.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'V onen den naplním na Élím všechno, co jsem promluvil proti jeho domu, od začátku až do konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Oznámil jsem mu, že budu soudit jeho dům navěky za vinu, ⌈ o které věděl; vždyť⌉ jeho synové ⌈proklínali Boha,⌉ ale nenapomenul je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Proto jsem přísahal domu Élího: Navěky nebude smířena vina domu Élího ani obětním hodem ani přídavnou obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel ležel až do rána, kdy otevřel dveře Hospodinova domu. Samuel se Élímu bál vidění oznámit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Élí však Samuela zavolal a řekl: Samueli, můj synu. On řekl: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Řekl: ⌈Co ti to říkal?⌉ Prosím, nic přede mnou nezatajuj! Ať tak Bůh učiní tobě a ještě přidá, jestliže přede mnou zatajíš ⌈něco z toho všeho, co ti říkal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Samuel mu tedy všechno oznámil a nic před ním nezatajil. Élí pak řekl: On je Hospodin. ⌈ Ať učiní,⌉ co je dobré v jeho očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel vyrůstal a Hospodin byl s ním. Žádné z jeho slov nenechal padnout na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Celý Izrael ⌈od Danu až po Beer–šebu⌉ věděl, že Samuel ⌈ je věrný Hospodinův prorok.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Hospodin se nadále ukazoval v Šílu, neboť v Šílu se Hospodin zjevil Samuelovi Hospodinovým slovem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Samuelovo slovo se stalo celému Izraeli. Izrael vytáhl do boje proti Pelištejcům. Utábořili se u Eben–ezeru a Pelištejci se utábořili v Afeku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Pelištejci se sešikovali proti Izraeli, strhl se boj a Izrael byl od Pelištejců poražen; pobili ⌈na bojišti na poli⌉ asi čtyři tisíce mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Lid přišel do tábora a izraelští starší řekli: Proč nás dnes Hospodin ⌈porazil před Pelištejci?⌉ Vezměme si ze Šíla truhlu Hospodinovy smlouvy. Ať přijde ⌈mezi nás⌉ a zachrání nás z moci našich nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Lid poslal do Šíla a přinesli odtamtud truhlu smlouvy Hospodina zástupů, sedícího na cherubech. S truhlou Boží smlouvy tam byli dva synové Élího, Chofní a Pinchas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Stalo se, že když přišla truhla Hospodinovy smlouvy do tábora, ⌈všichni Izraelci spustili velký válečný křik,⌉ až se země třásla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Když Pelištejci uslyšeli zvuk toho křiku, řekli: Co znamená zvuk toho velkého křiku v táboře Hebrejů? Pak se dozvěděli, že do tábora přišla Hospodinova truhla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Pelištejci dostali strach, neboť si řekli: Bůh přišel do tábora. Řekli také: Běda nám, neboť nikdy předtím se nestalo něco takového.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Běda nám! Kdo nás vysvobodí z ruky těchto vznešených bohů? To jsou ti bohové, kteří pobili Egypťany všelijakými ranami v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Posilněte se a vzmužte se, Pelištejci, jinak budete sloužit Hebrejům tak, jak oni sloužili vám! Vzmužte se a bojujte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Pelištejci bojovali a Izrael byl poražen, všichni utíkali ke svým stanům. Byla to ⌈hrozně veliká porážka.⌉ Z Izraele padlo třicet tisíc pěšáků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Boží truhla byla vzata a dva synové Élího, Chofní a Pinchas, zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Jeden Benjamínec utekl z bojiště a dostal se ten den do Šíla. Měl roztržené šaty a na hlavě prsť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Když přišel, hle, Élí seděl na stolci u cesty a vyhlížel, protože ⌈se v srdci třásl⌉ o Boží truhlu. Když ten muž přišel a oznámil zprávu ve městě, ⌈celé město⌉ volalo o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Když Élí uslyšel zvuk volání, řekl: Co je to za rachot? Ten muž ⌈rychle přišel⌉ a oznámil to Élímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Élímu bylo devadesát osm let, jeho oči byly strnulé, takže neviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Ten muž řekl Élímu: Přicházím z bojiště. Utekl jsem dnes z bojiště. Élí řekl: ⌈Co se stalo,⌉ můj synu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, '⌈Ten, kdo přinesl novinu,⌉ odpověděl: Izrael utekl před Pelištejci a ⌈na lid dopadla⌉ veliká rána. Také tvoji dva synové, Chofní a Pinchas, zemřeli a Boží truhla byla vzata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Stalo se, že když vzpomenul Boží truhlu, Élí spadl nazad ze stolce u brány, ⌈zlomil si vaz⌉ a zemřel, protože byl starý a těžký muž. Soudil Izrael čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Jeho snacha, Pinchasova žena, byla těhotná a před porodem. Když uslyšela zprávu o tom, že Boží truhla byla vzata a že zemřel její tchán i její muž, sklonila se a porodila, protože ⌈ji přepadly⌉ křeče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, '⌈Když umírala,⌉ řekly jí ty, které stály kolem ní: Neboj se, protože jsi porodila syna. Neodpověděla, ani si toho nevšímala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Chlapce nazvala Í–kabód a řekla: Odstěhovala se sláva z Izraele. To kvůli tomu, že byla vzata Boží truhla, kvůli svému tchánovi a svému muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Řekla: Odstěhovala se sláva z Izraele, protože byla vzata Boží truhla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Když se Pelištejci zmocnili Boží truhly, přenesli ji z Eben–ezeru do Ašdódu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Pelištejci tedy vzali Boží truhlu, přinesli ji do Dágonova domu a postavili ji vedle Dágona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Když Ašdóďané příštího dne časně vstali, hle, Dágon ležel ⌈tváří k zemi⌉ před Hospodinovou truhlou. Vzali Dágona a vrátili ho na jeho místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Když příštího dne časně ráno vstali, hle, Dágon ležel tváří k zemi před Hospodinovou truhlou; Dágonova hlava a obě ruce jeho paží ležely uraženy na prahu. Jen ⌈Dágonův trup zůstal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Proto v Ašdódu až dodnes Dágonovi kněží a nikdo, kdo vchází do Dágonova domu, nešlape na Dágonův práh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Hospodinova ruka těžce dolehla na Ašdóďany; zpustošil je a ⌈ranil je nádory, Ašdód i jeho území.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Když ašdódští muži uviděli, ⌈že to je tak,⌉ řekli: Ať truhla Boha Izraele nezůstává s námi, neboť jeho ruka tvrdě dolehla na nás a na našeho boha Dágona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Poslali posly, shromáždili k sobě všechna pelištejská knížata a řekli: Co máme udělat s truhlou Boha Izraele? Odpověděli: Ať je truhla Boha Izraele přenesena do Gatu. Tak přenesli truhlu Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Potom, co ji přenesli, se stalo, že Hospodinova ruka dopadla na město a způsobila hrozně velký zmatek. Ranil muže toho města ⌈od nejmenšího do největšího⌉ a vyrazily se jim nádory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Tak poslali Boží truhlu do Ekrónu. Stalo se, že když přišla Boží truhla do Ekrónu, Ekróňané volali: Přenesli k nám truhlu Boha Izraele, aby usmrtili nás i náš lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Poslali posly, shromáždili všechna pelištejská knížata a řekli: Pošlete truhlu Boha Izraele pryč. Ať se navrátí na své místo, ⌈aby neusmrtila⌉ nás ani náš lid. Neboť v celém městě byl smrtelný zmatek, Boží ruka tam dolehla velmi těžce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Ti muži, kteří nezemřeli, byli raněni nádory, takže volání města o pomoc vystupovalo k nebesům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Hospodinova truhla byla na pelištejském území sedm měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Pak Pelištejci svolali kněze a věštce a řekli: Co máme udělat s Hospodinovou truhlou? Poučte nás, jak ji máme poslat na její místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Odpověděli: Když budete posílat truhlu Boha Izraele pryč, neposílejte ji s prázdnou, nýbrž určitě ji vraťte s obětí za vinu. Tehdy budete uzdraveni a ⌈bude vám dáno poznat,⌉ proč se jeho ruka od vás neodvrátila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Nato řekli: ⌈Jakou oběť za vinu s ní máme poslat?⌉ Odpověděli: Podle počtu pelištejských knížat pět zlatých nádorů a pět zlatých myší, neboť stejná rána dopadla na všechny i na vaše knížata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Udělejte obrazy svých nádorů a obrazy svých myší, které ničí zemi, a vzdejte slávu Bohu Izraele. Snad nadlehčí svou ruku nad vámi, nad vašimi bohy a nad vaší zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Proč byste měli zatvrdit svá srdce, jako je zatvrdili Egypťané a faraon? Když se jim Bůh naposmíval, cožpak je nepropustili a oni ne odešli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Nyní tedy vezměte a připravte nějaký nový vůz, dvě krávy po otelení, na které ještě nebylo vloženo jho, zapřáhněte krávy do vozu, ale jejich telata od nich odveďte domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Potom vezměte Hospodinovu truhlu a dejte ji na vůz. Zlaté předměty, které s ní vrátíte jako oběť za vinu, položte do brašny po jejím boku a pošlete ji pryč, ať jde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'A dívejte se: Když vyrazí směrem ke svému území do Bét–šemeše, způsobil nám toto velké zlo on; jestliže ne, poznáte, že na nás neudeřila jeho ruka, stalo se nám to náhodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Muži tak učinili. Vzali dvě krávy po otelení, zapřáhli je do vozu, ale jejich telata zavřeli doma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Na vůz položili Hospodinovu truhlu a brašnu se zlatými myšmi i obrazy svých nádorů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Krávy šly přímo cestou na Bét–šemeš, šly po stejné silnici a stále bučely, neodbočily na pravo ani na levo. Pelištejská knížata šla za nimi až k území Bét–šemeše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Bétšemešané sklízeli v údolí pšenici. Když pozvedli oči, uviděli truhlu a zaradovali se, že ji vidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Vůz vjel na pole Jóšuy Bétšemešského a zastavil se tam. Byl tam velký kámen. Rozštípali dříví z vozu a přinesli krávy jako zápalnou oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Lévité sundali Hospodinovu truhlu i brašnu, která byla s ní a v níž byly zlaté předměty, a položili na to velký kámen. V ten den bétšemešští muži přinesli zápalné oběti a obětovali obětní hody Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Pět pelištejských knížat to vidělo a vrátilo se v ten den do Ekrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Toto jsou zlaté nádory, které Pelištejci poslali Hospodinu jako oběť za vinu: Jeden za Ašdód, jeden za Gazu, jeden za Aškalón, jeden za Gat a jeden za Ekrón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'A zlaté myši podle počtu všech pelištejských měst, patřících pěti knížatům, od opevněného města až k nehrazené vesnici. Ten velký kámen, na kterém ponechali Hospodinovu truhlu, je až dodnes svědkem na poli Jóšuy Bétšemešského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Hospodin pak zabil některé z bétšemešských mužů, protože se podívali do Hospodinovy truhly. Zabil v lidu sedmdesát mužů ⌈ z padesáti tisíc mužů.⌉ A lid truchlil, protože Hospodin ranil lid velikou ranou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Bétšemešští muži řekli: Kdo může obstát před Hospodinem, tímto svatým Bohem? Ke komu půjde od nás?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Nato poslali posly k obyvatelům Kirjat–jearímu se slovy: Pelištejci vrátili Hospodinovu truhlu. Přijďte a vezměte ji k sobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Muži z Kirjat–jearímu přišli a vzali Hospodinovu truhlu. Přenesli ji do Abínádabova domu na kopci a jeho syna Eleazara posvětili, aby Hospodinovu truhlu střežil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Stalo se, že ode dne, kdy truhla ⌈ začala pobývat⌉ v Kirjat–jearímu, ⌈uplynulo mnoho dní,⌉ přešlo dvacet let a celý dům izraelský se roztoužil po Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Samuel řekl celému domu izraelskému: Jestliže se celým svým srdcem navracíte k Hospodinu, odstraňte ze svého středu cizí bohy a aštarty. ⌈Připravte své srdce pro Hospodina,⌉ služte jemu samotnému a vysvobodí vás z ruky Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Nato synové Izraele odstranili baaly a aštarty a sloužili Hospodinu samotnému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Samuel řekl: Shromážděte celý Izrael do Mispy. Budu se za vás modlit k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Shromáždili se do Mispy, čerpali vodu a vylévali ji před Hospodinem. Postili se v ten den a říkali tam: Zhřešili jsme proti Hospodinu. A Samuel soudil syny Izraele v Mispě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Když Pelištejci uslyšeli, že se synové Izraele shromáždili do Mispy, vytáhla pelištejská knížata proti Izraeli. Když to synové Izraele uslyšeli, báli se Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Synové Izraele řekli Samuelovi: ⌈Nepřestávej za nás volat o pomoc⌉ k Hospodinu, našemu Bohu, ⌈aby nás zachránil⌉ z ruky Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel vzal jedno jehně sající mléko a přinesl ho jako ⌈dokonalou zápalnou oběť⌉ Hospodinu. Pak Samuel volal o pomoc k Hospodinu za Izrael a Hospodin mu odpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Stalo se, že když Samuel přinesl zápalnou oběť, Pelištejci se blížili do boje proti Izraeli. Hospodin však v onen den hlasitě zahřměl proti Pelištejcům, přivedl je do zmatku a byli od Izraele poraženi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Izraelští muži vytáhli z Mispy, pronásledovali Pelištejce a pobíjeli je až pod Bét–kar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Samuel pak vzal jeden kámen, položil ho mezi Mispu a Šén a pojmenoval jej Eben–ezer -- Kámen pomoci. Řekl: Až potud nám Hospodin pomáhal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Pelištejci byli pokořeni a nadále už nevcházeli na izraelské území. Hospodinova ruka dopadala na Pelištejce po ⌈všechny Samuelovy dny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Města, která Pelištejci vzali od Izraele, se navrátila zpět Izraeli, od Ekrónu až po Gat. I jejich okolní území Izrael vysvobodil z ruky Pelištejců. Rovněž byl pokoj mezi Izraelem a Emorejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'A Samuel soudil Izrael po všechny dny svého života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Rok co rok chodíval na okružní cestu do Bét–elu, do Gilgálu a do Mispy a na všech těchto místech soudil Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Pak se navracel do Rámy, neboť tam byl jeho dům; i tam soudil Izrael. Postavil tam také oltář Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Stalo se, že když Samuel zestárl, ustanovil za soudce nad Izraelem své syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Jméno jeho prvorozeného syna bylo Jóel a jméno druhého Abijáš; byli soudci v Beer–šebě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Jeho synové však nechodili po jeho cestě, hnali se za nekalým ziskem, brali úplatek a převraceli právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Všichni izraelští starší se shromáždili a přišli k Samuelovi do Rámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Řekli mu: Hle, ty jsi zestárl a tvoji synové nechodí po tvých cestách. Ustanov nyní nad námi krále, aby nás soudil, ⌈jako tomu je u všech národů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, '⌈Samuelovi se to nelíbilo,⌉ že řekli: ⌈Ustanov nad námi⌉ krále, aby nás soudil. Tak se Samuel modlil k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Hospodin řekl Samuelovi: Uposlechni lid ve všem, co ti řekl, protože nezavrhli tebe, ale zavrhli mě, abych nekraloval nad nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, '⌈Stejně jako jednali⌉ ode dne, kdy jsem je vyvedl z Egypta, až dodnes, kdy mě opouštěli a sloužili jiným bohům; tak činí i tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Nyní je však uposlechni, jenom je naléhavě varuj a oznam jim právo krále, který nad nimi bude kralovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Samuel řekl všechna Hospodinova slova lidu, který od něj žádal krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Řekl: Toto bude právo krále, který nad vámi bude kralovat: Vezme vaše syny a ustanoví si je ⌈na své válečné vozy a na své jezdecké koně⌉ a budou běhat před jeho válečnými vozy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Ustanoví si je za velitele nad tisíci a nad padesáti, také aby orali jeho pole a sklízeli jeho žeň, aby zhotovovali jeho válečné zbraně a výstroj jeho vozů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'A vaše dcery vezme za mastičkářky, kuchařky a pekařky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Vezme vaše nejlepší pole, vinice a olivové háje a dá je svým otrokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Bude brát desátky z vašeho zrní a vašich vinic a dá je svým dvorním úředníkům a otrokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Vezme vaše otroky a vaše služky, vaše nejlepší mládence a vaše osly a podrobí je práci pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Bude brát desátky z vašeho stáda a stanete se jeho otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'V onen den budete volat o pomoc kvůli svému králi, kterého jste si zvolili, ale Hospodin vám v onen den neodpoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Lid však nechtěl uposlechnout Samuela a řekli: Ne! ⌈Ať je⌉ nad námi král!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'I my budeme jako všechny národy. Náš král nás bude soudit, bude před námi vycházet a bojovat naše boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Samuel vyslechl všechna slova lidu a pověděl je Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Hospodin Samuelovi řekl: Uposlechni je a ustanov nad nimi krále. Samuel izraelským mužům řekl: Jděte každý do svého města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Byl muž z kmene Benjamín, jménem Kíš, syn Abíela, syna Seróra, syna Bekórata, syna Afíacha, Benjamínec, udatný hrdina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Ten měl syna jménem Saul, hezkého mládence; nikdo ze synů Izraele nebyl hezčí nežli on. ⌈Od ramen vzhůru⌉ převyšoval všechen lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Saulovu otci Kíšovi se ztratily oslice. Kíš tedy řekl svému synu Saulovi: Vezmi si s sebou jednoho ze služebníků, vstaň a jdi hledat ty oslice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Prošel Efrajimské pohoří, prošel zemi Šališa, ale nenašli je. Pak prošli zemi Šaalím, a zase nic. Prošel i zemi Benjamín, ale nenašli je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Když přišli do země Súf, řekl Saul svému služebníkovi, který byl s ním: Pojď se vrátit, jinak si můj otec přestane dělat starosti o oslice a bude se obávat o nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Ten mu řekl: Podívej, v tomto městě je muž Boží. Je to vážený muž. Všechno, co vysloví, se jistě naplní. Pojďme nyní tam. Snad nám oznámí cestu, po které bychom měli jít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Saul nato svému služebníkovi řekl: ⌈Tak pojďme! Ale⌉ co tomu muži přineseme? Vždyť nám došel chléb v brašnách a ne máme dárek, abychom ho muži Božímu přinesli. Co máme s sebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Služebník znovu Saulovi odpověděl: ⌈Vida, mám u sebe⌉ čtvrt šekelu stříbra. Dám jej muži Božímu, aby nám oznámil naši cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Když se šel někdo dotázat Boha, říkalo se dříve v Izraeli: ⌈Nuže, pojďme⌉ k vidoucímu. Dnešní prorok se totiž dříve nazýval vidoucí.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul nato svému služebníkovi řekl: ⌈Dobře jsi promluvil.⌉ ⌈Nuže, pojďme.⌉ Šli tedy do města, kde byl muž Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Jak vystupovali po svahu do města, potkali děvčata, která vyšla čerpat vodu. Zeptali se jich: Je zde vidoucí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Odpověděla jim: Ano, je; zrovna před tebou. Tak si pospěš, neboť dnes přišel do města, protože dnes má lid na návrší obětní hod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Jakmile přijdete do města, tak ho najdete, dříve nežli vystoupí na návrší, aby jedl. Lid totiž nebude jíst, dokud ne přijde, jelikož on žehná obětnímu hodu. Potom budou jíst ti, kdo jsou pozváni. Nyní vystupte, neboť ještě dnes ho najdete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Vystoupili tedy k městu a když vcházeli do města, Samuel zrovna vycházel proti nim, aby vystoupil na návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Den předtím, nežli Saul přišel, Hospodin ⌈odhalil Samuelovo ucho⌉ a řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '⌈Zítra touto dobou⌉ k tobě pošlu muže ze země Benjamín. Pomaž ho za vévodu nad ⌈mým lidem Izraelem.⌉ On zachrání můj lid z ruky Pelištejců, protože jsem pohleděl na svůj lid, neboť jeho volání proniklo ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Když Samuel uviděl Saula, Hospodin mu pověděl: Tak to je ten muž, o němž jsem ti řekl: Ten bude vládnout nad mým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Saul pak přistoupil v bráně k Samuelovi a řekl: Pověz mi, prosím, kde je dům vidoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel Saulovi odpověděl: Já jsem vidoucí. Vystup přede mnou na návrší a pojezte dnes se mnou. Ráno tě propustím a oznámím ti vše, co ⌈ máš na⌉ srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'A ⌈o oslice, které se ti ⌈před třemi⌉ dny ztratily, se neobávej,⌉ protože se našly. ⌈Po kom však nejvíce touží Izrael?⌉ ⌈Cožpak ne po tobě⌉ a po celém domě tvého otce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul odpověděl: Cožpak nejsem Benjamínec z nejmenšího izraelského kmene a není má čeleď nejmenší ze všech čeledí kmene Benjamín? Proč mi říkáš takovou věc?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel pak vzal Saula a jeho služebníka, přivedl je do síně a dal jim místo v čele těch, kdo byli pozváni. Bylo tam asi třicet mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Samuel řekl kuchaři: Podej ten díl, který jsem ti dal a o němž jsem ti řekl: Ulož ho u sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Kuchař vytáhl kýtu, s tím, co bylo na ní, položil před Saula a Samuel řekl: Podívej, co zůstalo! Vezmi si a jez. Vždyť to bylo uchováno pro tebe na toto setkání, když jsem řekl: Pozval jsem lid. Tak Saul pojedl v ten den se Samuelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Když sestoupili z návrší do města, Samuel si povídal se Saulem na střeše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Časně vstali. Stalo se, když vycházela jitřenka, že Samuel zvolal na Saula na střeše: Vstaň a propustím tě. Saul vstal a oba, on i Samuel, vyšli ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Když sestupovali na konec města, Samuel řekl Saulovi: Řekni služebníkovi, aby šel dál před námi. -- ⌈A on šel dál. Ale⌉ ty se na chvíli zastav. Oznámím ti Boží slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Potom vzal Samuel lahvičku s olejem, vylil ho na jeho hlavu, políbil ho a řekl: Hospodin tě pomazal za vévodu nad svým dědictvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Až dnes půjdeš ode mě, potkáš dva muže u Ráchelina hrobu na území Benjamínově v Selsachu. Řeknou ti: Oslice, které jsi šel hledat, se našly. Hle, tvůj otec nechal být záležitost s oslicemi a obává se o vás. Říká si: Co mám udělat ⌈pro svého syna?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Odtamtud jdi dál, až přijdeš k dubu Tábor. Tam tě potkají tři muži, vystupující k Bohu do Bét–elu. Jeden ponese tři kůzlata, druhý ponese tři bochníky chleba a třetí ponese měch vína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Zeptají se tě, ⌈jak se ti daří,⌉ a dají ti dva chleby. Vezmi si to od nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Potom jdi ⌈ do Gibeje Boží,⌉ kde je pelištejská posádka. I stane se, když vstoupíš do toho města, že potkáš skupinu proroků, jak sestupují z návrší, ⌈ mají před sebou⌉ harfu, tamburínu, flétnu a lyru, a prorokují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Uchvátí tě Duch Hospodinův, budeš prorokovat s nimi a budeš změněn v jiného muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'I stane se, až se na tobě naplní tato znamení, učiň, co ⌈se ti naskytne,⌉ protože Bůh je s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Sestup přede mnou do Gilgálu a hle, já sestoupím k tobě, abych přinesl zápalné oběti a obětoval pokojné oběti. Sedm dnů budeš čekat, až k tobě přijdu a oznámím ti, co máš dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'I stalo se, že když se obrátil, aby šel od Samuela, Bůh mu změnil srdce v jiné a v onen den se naplnila všechna ta znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Když přišli do Gibeje, hle, skupina proroků šla proti nim; uchvátil ho ⌈Duch Boží⌉ a prorokoval s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Stalo se, že všichni, kteří ho dávno předtím znali, viděli, že prorokuje s proroky; lidé říkali jeden druhému: Co se to stalo s Kíšovým synem? Cožpak je také Saul mezi proroky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Kdosi odtamtud odpověděl: A ⌈kdo je jejich otec?⌉ Proto se stalo příslovím: Cožpak je také Saul mezi proroky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Když přestal prorokovat, přišel na návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Saulův strýc jemu a jeho služebníkovi řekl: Kde jste chodili? Odpověděl: Hledali jsme oslice a když jsme viděli, že nikde nejsou, šli jsme k Samuelovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Saulův strýc řekl: Pověz mi, co vám Samuel říkal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul svému strýci odpověděl: S jistotou nám oznámil, že se našly oslice. O kralování, o němž Samuel mluvil, mu nic neoznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Pak Samuel svolal lid k Hospodinu do Mispy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Synům Izraele řekl: Takto praví Hospodin, Bůh Izraele: Já jsem vyvedl Izrael z Egypta, vysvobodil jsem vás z ruky Egypťanů a z moci všech království, která vás utiskovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Vy však jste teď zavrhli svého Boha, který vás zachraňoval ze všech vašich nouzí a soužení, a řekli jste: Ne, ale ustanov nad námi krále. Nyní se tedy postavte před Hospodinem podle svých kmenů a podle rodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Samuel předvedl všechny izraelské kmeny a losem byl vybrán kmen Benjamín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Předvedl kmen Benjamín po čeledích a losem byla vybrána čeleď Matrí; tam byl losem vybrán Saul, syn Kíšův. Hledali ho, ale nebyl nalezen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Doptávali se znovu Hospodina: Přišel sem již ten muž? Hospodin řekl: Hle, skrývá se u výstroje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Běželi tedy a dovedli jej odtamtud. Když se postavil uprostřed lidu, od ramen vzhůru převyšoval všechen lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Samuel řekl všemu lidu: Vidíte, koho si Hospodin vyvolil? Není ⌈mu podobného⌉ mezi vším lidem. A všechen lid křičel: Ať žije král!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Nato Samuel promluvil k lidu o královském právu, zapsal je do knihy a ponechal před Hospodinem. Pak Samuel propustil všechen lid, každého do jeho domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Také Saul šel do svého domu v Gibeji. Šli s ním i ti udatní muži, jejichž srdcí se Bůh dotkl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Ničemníci však říkali: Jak nás může tenhle zachránit? Pohrdli jím a nepřinesli mu dar. On ale mlčel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Náchaš Amónský vytáhl a utábořil se u Jábeše v Gileádu. Všichni jábešští muži řekli Náchašovi: Uzavři s námi smlouvu a budeme ti sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Náchaš Amónský jim odpověděl: Uzavřu s vámi smlouvu tak, že vám každému vyloupnu pravé oko a uvedu potupu na celý Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Jábešští starší mu řekli: Nech nám sedm dnů, abychom poslali posly po celém území Izraele. Jestliže nebude nikdo, kdo by nás zachránil, vyjdeme k tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Když přišli poslové do Gibeje Saulovy, povídali ⌈tyto věci⌉ lidu. Všechen lid ⌈pozvedl svůj hlas a rozplakali se.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Saul zrovna přicházel za skotem z pole. Zeptal se: Co je lidu, že pláče? Oni mu vypravovali slova jábešských mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Když Saul uslyšel tato slova, uchvátil ho Duch Boží a velice ⌈vzplál hněvem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Vzal spřežení skotu, rozsekal ho na kusy a poslal po poslech po celém izraelském území se slovy: Kdo nevytáhne za Saulem a Samuelem, toto se stane s jeho skotem. Na lid padl strach z Hospodina a vytáhli ⌈jako jeden muž.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Spočítal je v Bezeku. Synů Izraele bylo ⌈tři sta tisíc a judských mužů třicet tisíc.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Poslům, kteří přišli, řekli: Mužům z Jábeše v Gileádu řekněte toto: Zítra za slunečního žáru se vám dostane záchrany. Poslové šli, oznámili to jábešským mužům a ti se radovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Potom jábešští muži řekli Náchašovi: Zítra k vám vyjdeme a dělejte si s námi, ⌈co je vám libo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Příštího dne se stalo, že Saul rozdělil lid do tří oddílů. Za ⌈ranní hlídky⌉ vešli do tábora a pobíjeli Amónovce až do denního žáru. Stalo se, že ti, kteří zůstali, se rozprchli a nezůstali z nich ani dva pospolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Lid řekl Samuelovi: Kdo to povídal: Saul že by měl nad námi kralovat? Vydejte ty muže, ať je usmrtíme!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Saul však řekl: Dnes ať není nikdo usmrcen. Vždyť dnes Hospodin způsobil Izraeli záchranu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Samuel řekl lidu: Nuže, pojďme do Gilgálu a obnovíme tam kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Všechen lid pak šel do Gilgálu a ustanovili tam před Hospodinem Saula králem a obětovali tam před Hospodinem pokojné oběti. Saul i všichni izraelští muži se tam převelice radovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Samuel řekl ⌈celému Izraeli:⌉ Hle, uposlechl jsem vás ve všem, co jste mi řekli, a ustanovil jsem nad vámi krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Nyní hle, král ⌈bude chodit před vámi.⌉ Já jsem zestárl a zešedivěl a moji synové jsou zde s vámi. ⌈Chodil jsem před vámi⌉ od svého mládí až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Zde jsem. Vypovídejte proti mně před Hospodinem a před jeho pomazaným. Komu jsem vzal býka či komu jsem vzal osla? Koho jsem utlačoval? Koho jsem vydíral? ⌈Od koho⌉ jsem vzal úplatek, abych kvůli němu přivřel oko? Vrátím vám to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Odpověděli: Neutlačoval jsi nás ani jsi nás nevydíral, ani jsi ⌈od nikoho⌉ nic nevzal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Řekl jim: Hospodin je svědkem proti vám a svědkem je dnes jeho pomazaný, že jste ⌈u mne⌉ nic nenalezli. A lid řekl: Je svědkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel dále řekl lidu: Ten Hospodin, který ustanovil Mojžíše a Árona a který vyvedl vaše otce z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Nyní se postavte. Budu se s vámi soudit před Hospodinem za všechny Hospodinovy spravedlivé činy, které činil s vámi a s vašimi otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Když přišel Jákob do Egypta a vaši otcové volali k Hospodinu o pomoc, Hospodin poslal Mojžíše a Árona, kteří vyvedli vaše otce z Egypta a usídlili je na tomto místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Oni však na Hospodina, svého Boha, zapomněli. Proto je vydal do ruky Sísery, velitele chasórské armády, do ruky Pelištejců a do ruky moábského krále, kteří proti nim bojovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Pak volali k Hospodinu o pomoc a říkali: Zhřešili jsme, protože jsme opustili Hospodina a sloužili jsme baalům a aštartám. Nyní však nás ⌈vysvoboď z ruky našich nepřátel⌉ a budeme sloužit tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Hospodin poslal Jerubaala, Bedána, Jiftácha a Samuela a vysvobodil vás z ruky vašich okolních nepřátel a bydleli jste v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Když jste viděli, že Náchaš, král synů Amónových, táhne proti vám, řekli jste mi: Ne, ať nad námi kraluje král, ačkoliv Hospodin, váš Bůh, je vaším králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Teď se podívejte, král, kterého jste si zvolili, kterého jste si vyžádali, podívejte, Hospodin nad vámi ustanovil krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Jestliže se budete bát Hospodina a budete mu sloužit, budete ho poslouchat a nebudete se vzpírat Hospodinovým příkazům, jestliže budete vy i král, který nad vámi kraluje, následovat Hospodina, svého Boha, bude dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Jestliže však nebudete poslouchat Hospodina a budete vzpurní vůči Hospodinovým příkazům, bude Hospodinova ruka proti vám a proti vašim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Nyní se tedy postavte a dívejte se na tu velkou věc, kterou Hospodin učiní před vašima očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Není dnes sklizeň pšenice? Budu volat k Hospodinu, aby dal hromobití a déšť. Pak poznáte a uvidíte, jak velké v Hospodinových očích je vaše zlo, které jste spáchali, když jste si vyžádali krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Samuel potom volal k Hospodinu a Hospodin v onen den dal hromobití a déšť. Všechen lid se proto velice bál Hospodina i Samuela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Všechen lid řekl Samuelovi: Modli se za své otroky k Hospodinu, svému Bohu, abychom nezemřeli, neboť jsme ke všem svým hříchům přidali další zlo, že jsme si vyžádali krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel řekl lidu: Nebojte se! Spáchali jste sice všechno toto zlo; avšak ⌈neodvracejte se od Hospodina,⌉ ale ⌈služte Hospodinu⌉ ⌈celým svým srdcem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Neodvracejte se, abyste šli za marnostmi, které neprospějí ani nevysvobodí, protože jsou to marnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Vždyť kvůli svému velkému jménu Hospodin nezanechá svůj lid, neboť ⌈Hospodin se odhodlal⌉ učinit ⌈si z vás svůj lid.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Co se mě týče, ať je ode mě vzdáleno to, abych hřešil proti Hospodinu a přestal se za vás modlit. Budu vás učit dobré a přímé cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Jen se bojte Hospodina a služte mu věrně celým svým srdcem. Vždyť se podívejte, co velkého ⌈s vámi⌉ učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Jestliže však budete stále páchat zlo, budete smeteni jak vy, tak i váš král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saulovi bylo třicet let, když se stal králem, a kraloval nad Izraelem čtyřicet dva let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Saul si vybral tři tisíce mužů z Izraele. Dva tisíce jich bylo se Saulem v Mikmásu a v bételském pohoří a tisíc jich bylo s Jónatanem v Gibeji Benjamínově. Zbytek lidu poslal pryč, všechny k jejich stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Jónatan pobil pelištejskou posádku, která byla v Gebě. Pelištejci o tom uslyšeli. Saul dal zatroubit na beraní roh po celé zemi se slovy: Ať to Hebrejové slyší!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'A ⌈celý Izrael uslyšel⌉ slova: Saul pobil pelištejskou posádku a Izrael se Pelištejcům zošklivil. Nato byl svolán lid za Saulem do Gilgálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Pelištejci se shromáždili, aby bojovali s Izraelem -- třicet tisíc vozů, šest tisíc jezdců a lidu takové množství jako písku na mořském břehu. Vytáhli a utábořili se v Mikmásu na východ od Bét–ávenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Když Izraelci viděli, že jsou v tísni -- neboť ⌈lid byl vystaven tlaku,⌉ lid se ukryl do jeskyní, do houští, do skal, do sklepení a cisteren.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Někteří Hebrejové přešli Jordán do země Gád a Gileád. Saul byl ale ještě v Gilgálu a všechen ⌈lid, který šel za ním, se třásl strachy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Čekal sedm dnů, čas určený Samuelem. Samuel však do Gilgálu nepřišel a lid od něj postupně prchal pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Saul řekl: Přineste ke mně zápalnou a pokojnou oběť. Pak přinesl zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Stalo se, že když dokončil přinášení zápalné oběti, tak Samuel přišel. Saul mu vyšel naproti, aby ho pozdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Samuel řekl: Co jsi to udělal? Saul odpověděl: Když jsem viděl, že lid ode mě postupně prchá pryč, že ty jsi nepřišel v určené dny a Pelištejci se shromažďují v Mikmásu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'řekl jsem si: Teď Pelištejci sestoupí proti mně do Gilgálu a já jsem si ⌈neudobřil Hospodinovu tvář.⌉ Tak jsem se odvážil a přinesl jsem zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel řekl Saulovi: Jednal jsi bláznivě, že jsi nezachoval příkaz Hospodina, svého Boha, který ti dal. Vždyť tak by Hospodin upevnil tvé království nad Izraelem navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Teď ale tvé království neobstojí. Hospodin si vyhledal muže podle svého srdce a ustanovil ho vévodou nad svým lidem, protože jsi nezachoval to, co ti Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Potom Samuel vstal a vystoupil z Gilgálu do Gibeje Benjamínovy. Saul spočítal lid, který byl s ním; bylo tam asi šest set mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul a jeho syn Jónatan i lid, který byl s nimi, se usídlil v Gebě Benjamínově, zatímco Pelištejci se utábořili v Mikmásu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Z pelištejského tábora vytáhli nájezdníci ve třech oddílech. Jeden oddíl se obrátil směrem k Ofře v zemi Šúal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'druhý oddíl se obrátil směrem k Bét–chorónu a třetí oddíl se obrátil směrem k území, které shlíží do údolí Seboím v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'V celé izraelské zemi nebyl žádný kovář, protože Pelištejci řekli: Ať si Hebrejové nedělají meče ani kopí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Všichni Izraelci sestupovali k Pelištejcům, aby si nechali naostřit svou radlici, motyku, sekeru či srp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Jeden pím bylo za naostření radlic a motyk, ⌈za trojzubec,⌉ sekery a za nasazení bodce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'V čas boje se stalo, že u nikoho z lidu, který byl se Saulem a s Jónatanem, nebyl meč ani kopí; měl je pouze Saul a jeho syn Jónatan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Pelištejská hlídka vyšla k mikmáskému průsmyku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Jednoho dne se stalo, že Jónatan, syn Saulův, řekl služebníkovi, který nosil jeho výstroj: Pojď, projdeme k pelištejské hlídce, která je na druhé straně. Svému otci to však neoznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul pobýval na konci Gibeje pod granátovníkem, který byl v Migrónu. Lidu, který byl s ním, bylo asi šest set mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Byl tam také Achijáš, syn Achítúba, bratra Í–kabóda, syna Pinchasa, syna Élího, Hospodinova kněze v Šílu, který nosil efód. Lid nevěděl, že Jónatan odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, '⌈V průsmyku,⌉ kterým chtěl Jónatan projít k pelištejské hlídce, byl skalní výběžek z jedné strany a skalní výběžek z druhé strany. Jeden se jmenoval Bóses a druhý se jmenoval Sené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Jeden výběžek vyčníval od severu naproti Mikmásu a druhý od jihu naproti Gebě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Jónatan řekl služebníkovi, svému zbrojnoši: Pojď, projdeme k hlídce těch neobřezanců. Snad pro nás Hospodin něco udělá. Neboť ⌈Hospodinu ne může nic zabránit,⌉ aby zachránil skrze mnoho nebo skrze málo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Jeho zbrojnoš mu řekl: Udělej vše, co ⌈ máš na srdci.⌉ Vzhůru! Hle, já jsem s tebou ⌈tak, jak to máš na srdci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jónatan řekl: Tak projdeme k těm mužům a ukážeme se jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Jestliže nám řeknou: Zůstaňte stát, dokud k vám ne dorazíme, zůstaneme stát na svém místě a nepůjdeme k nim nahoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Jestliže však řeknou: Pojďte k nám nahoru, půjdeme, protože Hospodin je ⌈vydal do naší ruky⌉ a toto nám bude znamením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Oba se tedy ukázali pelištejské hlídce a Pelištejci řekli: Podívejte, Hebrejové vycházejí z děr, do kterých se ukryli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Muži z hlídky promluvili k Jónatanovi a jeho zbrojnoši: Vylezte k nám a my vám ukážeme! Jónatan řekl svému zbrojnoši: Lez za mnou, protože Hospodin je vydal do moci Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Jónatan ⌈lezl vzhůru po rukou a po nohou⌉ a jeho zbrojnoš za ním. Pelištejci padali před Jónatanem a jeho zbrojnoš je za ním usmrcoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'To byla první porážka, ve které Jónatan a jeho zbrojnoš pobili asi dvacet mužů na ⌈pozemku asi poloviny akru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, '⌈Na tábor, na pole i na všechen lid padl strach.⌉ Dokonce i hlídka a nájezdníci se třásli. Země se třásla. Bylo to ⌈třesení od Boha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Saulovi strážní v Gibeji Benjamínově ⌈viděli, jak dav⌉ prchá a utíká na všechny strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Saul řekl lidu, který byl s ním: Spočítejte se a podívejte se, kdo od nás odešel. Spočítali se a hle, nebyl tam Jónatan a jeho zbrojnoš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Saul řekl Achijášovi: Přines Boží truhlu. Boží truhla totiž byla v onom čase se syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Stalo se, že zatímco Saul mluvil s knězem, rachot, který byl v pelištejském táboře, stále rostl a vzmáhal se. Proto Saul řekl knězi: Odtáhni svou ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Saul a všechen lid, který byl s ním, se shromáždil a přišel až k tomu boji. A hle, tam byl meč jednoho proti druhému, hrozně velký zmatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Hebrejové, kteří byli předtím s Pelištejci a vytáhli s nimi ze všech stran do tábora, i oni se teď vrátili, aby byli s Izraelem, který byl se Saulem a Jónatanem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Všichni izraelští muži, kteří se skrývali v Efrajimském pohoří, uslyšeli, že Pelištejci utekli a také oni je stíhali v boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'V onen den Hospodin zachránil Izrael. Bitva pokročila za Bét–áven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'V onen den byli Izraelci vystaveni tlaku. Saul zapřisáhl lid slovy: Prokletý buď muž, který do večera, dříve než se pomstím na svých nepřátelích, pojí pokrm. Nikdo z lidu neokusil pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Potom všechen lid ⌈vstoupil do lesa⌉ a na zemi byl med.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Když přišel lid ⌈do lesa,⌉ zrovna tekl med, ale nikdo nezvedal svou ruku k ústům, protože se lid bál přísahy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jónatan to však neslyšel, když jeho otec zapřísahal lid, vztáhl konec hole, kterou měl v ruce, a ponořil ji do plástve medu. Vrátil ruku zpět k ústům a jeho oči se rozzářily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Někdo z lidu mu pověděl: Tvůj otec rozhodně zapřísahal lid slovy: Prokletý buď muž, který dnes pojí pokrm, takže lid je unaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Jónatan řekl: Můj otec trápí zemi. Jen se podívej, jak se mi rozzářily oči, protože jsem okusil trochu tohoto medu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Tím spíše, kdyby se dnes lid dobře najedl z kořisti svých nepřátel, kterou nalezl. Ale kvůli tomu nebyla porážka Pelištejců tak velká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'V onen den pobíjeli Pelištejce od Mikmásu do Ajalónu a lid byl hrozně unaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Lid se vrhl proto na kořist, brali ovce, býky i telata a zabíjeli je na zemi. Tak lid jedl maso i s krví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Oznámili to Saulovi slovy: Hle, lid hřeší proti Hospodinu tím, že jí maso i s krví. On řekl: Zachovali jste se nevěrně. Přivalte ke mně ihned velký kámen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Pak Saul řekl: Rozejděte se mezi lid a řekněte jim: Přiveďte ke mně každý svého býka a svou ovci, zabíjejte je zde a jezte, abyste nehřešili proti Hospodinu tím, že byste jedli maso i s krví. Té noci tedy přivedl všechen lid každý vlastnoručně svého býka a zabíjeli je tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Saul postavil oltář Hospodinu. ⌈Tehdy začal stavět oltáře⌉ Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Potom Saul řekl: Sestupme v noci za Pelištejci a budeme je plenit až do svítání. Neponechme nikoho z nich. Odpověděli: Učiň všechno, co je ⌈ti libo.⌉ Kněz však řekl: Přistupme sem k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Saul se doptával Boha: Mám sestoupit za Pelištejci? Vydáš je do moci Izraele? Ale on mu v ten den neodpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Saul řekl: Přistupte sem všichni vůdcové lidu. Zkoumejte a zjistěte, jak ⌈dnes došlo k tomuto hříchu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Neboť jakože je živ Hospodin, který zachraňuje Izrael, i kdyby to bylo kvůli mému synu Jónatanovi, jistě zemře. Nikdo ze všeho lidu mu neodpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Nato řekl celému Izraeli: Vy buďte na jedné straně a já se svým synem Jónatanem budeme na straně druhé. Lid řekl Saulovi: Učiň, co je ti libo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Saul řekl ⌈Hospodinu: Bože Izraele,⌉ dej, ať se ukáže bezúhonný. Losem byl vybrán Jónatan a Saul, a lid vyšel bez viny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul řekl: Nechte padnout los mezi mnou a mým synem Jónatanem. Losem byl vybrán Jónatan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Nato řekl Saul Jónatanovi: Oznam mi, co jsi udělal. Jónatan mu oznámil: Ano, koncem hole, kterou jsem měl v ruce, okusil jsem trochu medu. Ať tedy zemřu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Saul řekl: Ať tak Bůh učiní i mně a ještě přidá, jestliže ne zemřeš, Jónatane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Lid však řekl Saulovi: Cožpak zemře Jónatan, který způsobil tuto velkou záchranu v Izraeli? Ať je to od tebe vzdáleno. Jakože živ je Hospodin, ať nespadne ani vlas z jeho hlavy na zem, neboť to dnes učinil s pomocí Boží. Tak lid vykoupil Jónatana, a nezemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Saul pak ⌈přestal Pelištejce pronásledovat ⌉ a Pelištejci utekli na své území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Když Saul získal kralování nad Izraelem, bojoval proti všem svým okolním nepřátelům -- proti Moábcům, proti synům Amónovým, proti Edómcům, proti králům Sóby a proti Pelištejcům. Kamkoli se obrátil, vítězil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Počínal si udatně, pobil Amálekovce a vysvobodil Izrael z moci ⌈těch, kdo ho plenili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Saulovi synové byli Jónatan, Jišví a Malkíšúa. Jeho dvě dcery se jmenovaly: prvorozená Mérab a mladší Míkal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Saulova žena se jmenovala Achínoam, dcera Achímaasova. Velitel jeho armády se jmenoval Abínér, syn Néra, Saulova strýce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Kíš, otec Saulův, a Nér, otec Abnérův, byli syny Abíelovými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Po všechny Saulovy dny ⌈trvaly prudké boje⌉ proti Pelištejcům. ⌈Proto si Saul vyhlédl všechny hrdiny⌉ a ⌈všechny bojovníky⌉ a shromáždil je k sobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel řekl Saulovi: Mne Hospodin poslal, abych tě pomazal za krále nad jeho lidem, nad Izraelem. Nyní tedy uposlechni Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Toto praví Hospodin zástupů: ⌈Všímal jsem si toho,⌉ co učinili Amálekovci Izraeli, jak se mu postavili do cesty, když táhl z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Nyní jdi, pobij Amálekovce a ⌈zasvěťte zkáze⌉ všechno, co jim patří. Neměj s nimi soucit, ale usmrť ⌈muže i ženy,⌉ děti i kojence, býky i ovce, velbloudy i osly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul tedy svolal lid a spočítal ho v Telaímu: Dvě stě tisíc pěšáků a deset tisíc ⌈judských mužů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Pak Saul přitáhl k amáleckému městu a číhal v údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Saul řekl Kénijcům: Jděte, stáhněte se a odejděte od Amálekovců, ať vás nesmetu spolu s nimi. Vy jste prokázali milosrdenství všem synům Izraele, když táhli z Egypta. Kénijci se tedy od Amálekovců stáhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Saul pak pobíjel Amálekovce od Chavíly až do Šúru, který je ⌈směrem k⌉ Egyptu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Amáleckého krále Agaga chytil živého, ale všechen lid zasvětil zkáze ostřím meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Saul a lid měl soucit s Agagem, s nejlepšími kusy ovcí a vykrmenými býky, s jehňaty a se vším, co bylo hodnotné, a nechtěli je zasvětit zkáze; zasvětili zkáze všechno opovržené a bezcenné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'I stalo se Hospodinovo slovo k Samuelovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Lituji, že jsem ustanovil Saula za krále, neboť se ode mě odvrátil a nenaplnil mé slovo. Samuel se rozzlobil a celou noc volal k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Časně zrána Samuel vstal, aby se setkal se Saulem. Samuelovi bylo oznámeno: Saul přišel na Karmel a postavil si pomník. Potom se obrátil, šel dál a sestoupil do Gilgálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Když přišel Samuel k Saulovi, Saul mu řekl: ⌈Jsi požehnaný Hospodinu.⌉ Naplnil jsem Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel nato řekl: A co to bečení ovcí, jež zní v mých uších, a bučení býků, které slyším?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul odpověděl: Přivedli od Amálekovců ⌈to, s čím⌉ měl lid soucit, nejlepší kusy ovcí a býků, aby to obětovali Hospodinu, tvému Bohu, a zbytek jsme zasvětili zkáze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Samuel řekl Saulovi: Nech toho. Oznámím ti, co ke mně této noci promluvil Hospodin. Odpověděl mu: Mluv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel nato řekl: I když ⌈jsi malý ve svých očích,⌉ jsi hlavou izraelských kmenů. Hospodin tě pomazal za krále nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Hospodin tě poslal na cestu a řekl: Jdi a zasvěť zkáze amálecké hříšníky. Bojuj proti nim, dokud s nimi neskoncuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Proč jsi neuposlechl Hospodina, ale vrhl ses na kořist a spáchal jsi to, co je zlé v Hospodinových očích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Saul odpověděl Samuelovi: Uposlechl jsem Hospodina a šel jsem na cestu, na kterou mě Hospodin poslal. Přivedl jsem amáleckého krále Agaga a Amálekovce jsem zasvětil zkáze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Lid vzal z kořisti ovce a býky, nejlepší z toho, co bylo zasvěceno zkáze, aby to obětovali Hospodinu, tvému Bohu, v Gilgálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Samuel řekl: Má Hospodin zalíbení v zápalech a obětech jako v poslouchání Hospodina? Hle, poslouchat je lepší než oběť, dávat pozor je víc než tuk beranů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Protože vzpoura je jako hřích věštby a vzdor je jako zlo domácích bůžků. Protože jsi zavrhl Hospodinovo slovo, on zavrhl tebe, ⌈abys nebyl králem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Saul řekl Samuelovi: Zhřešil jsem, neboť jsem překročil Hospodinův příkaz i tvoje slova; protože jsem se bál lidu, uposlechl jsem ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Nyní však sejmi, prosím, můj hřích a vrať se se mnou, abych se poklonil Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel Saulovi odpověděl: Nenavrátím se s tebou. Protože jsi zavrhl Hospodinovo slovo, Hospodin zavrhl tebe, abys nebyl králem nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Když se Samuel obrátil k odchodu, uchopil Saul cíp jeho pláště a ten se odtrhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Nato mu Samuel řekl: Dnes od tebe Hospodin odtrhl izraelské království a dal ho tvému bližnímu, lepšímu, nežli jsi ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Sláva Izraele nebude lhát a nebude litovat, protože není člověk, aby litoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Saul řekl: Zhřešil jsem. Nyní mě však, prosím, pocti před staršími mého lidu i před Izraelem a vrať se se mnou, abych se poklonil Hospodinu, tvému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Samuel se vrátil, šel za Saulem a Saul se poklonil Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Pak Samuel řekl: Přiveďte ke mně amáleckého krále Agaga. Agag k němu šel v poutech. Řekl si: Jistě ustoupila hořká smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel řekl: Jako tvůj meč činil ženy bezdětnými, tak bude učiněna bezdětnou nad jiné ženy tvá matka. Nato Samuel v Gilgálu před Hospodinem rozsekal Agaga na kusy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Potom Samuel šel do Rámy a Saul šel do svého domu v Gibeji Saulově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Samuel již Saula neviděl až do dne své smrti, ale truchlil nad Saulem. A Hospodin litoval, že ustanovil Saula králem nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Hospodin řekl Samuelovi: Jak dlouho budeš truchlit nad Saulem? Já jsem ho zavrhl, aby nekraloval nad Izraelem. Naplň svůj roh olejem a jdi. Posílám tě k Jišajovi Betlémskému, protože mezi jeho syny jsem si vyhlédl krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel řekl: Jak mohu jít? Saul o tom uslyší a zabije mě. Hospodin řekl: Vezmi s sebou jalovici a řekni: Přišel jsem obětovat Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Pozvi Jišaje k oběti a já ti oznámím, co máš udělat. Pomažeš mi toho, o kterém ti řeknu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel udělal to, co Hospodin ⌈řekl, a přišel⌉ do Betléma. Starší města mu šli vyděšeni naproti a zeptali se: ⌈Přicházíš v pokoji?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Odpověděl: V pokoji. Přišel jsem obětovat Hospodinu. Posvěťte se a pojďte se mnou k oběti. Posvětil i Jišaje a jeho syny a pozval je k oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Stalo se, že když přišli, uviděl Elíaba a řekl si: Jistě je před Hospodinem jeho pomazaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Hospodin však Samuelovi řekl: Nehleď na jeho vzhled ani na jeho velkou výšku, neboť jsem ho zavrhl, jelikož se ⌈ne dívám na to, na co⌉ se dívá člověk. Vždyť člověk se dívá na to, co má před očima, ale Hospodin se dívá na srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Jišaj zavolal Abínádaba a předvedl ho před Samuela. Ten řekl: Ani toho Hospodin nevyvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Jišaj předvedl Šamu, ale Samuel řekl: Ani toho Hospodin nevyvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Jišaj předvedl před Samuela svých sedm synů, avšak Samuel Jišajovi řekl: Hospodin je nevyvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Nato řekl Samuel Jišajovi: ⌈ To jsou všichni mládenci?⌉ Odpověděl: Ještě nejmladší. Zrovna pase ovce. Samuel řekl Jišajovi: Pošli pro něj a nech ho přivést, neboť nezasedneme, dokud sem ne přijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Poslal pro něj a přivedl ho. Byl ryšavý, s krásnýma očima a hezkého vzhledu. Hospodin řekl: Vstaň a pomaž ho, neboť to je on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Samuel vzal roh s olejem a pomazal ho uprostřed jeho bratrů. Od onoho dne i nadále Davida uchvacoval Duch Hospodinův. Samuel vstal a šel do Rámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Duch Hospodinův odstoupil od Saula a děsil ho zlý duch od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Saulovi otroci mu řekli: Hle, děsí tě zlý duch od Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Ať jen řekne náš pán svým otrokům, kteří ⌈ti slouží,⌉ ať vyhledají někoho, kdo umí hrát na lyru. A když se stane, že na tebe přijde zlý duch od Boha, bude hrát svou rukou a bude ti dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Saul řekl svým otrokům: Vyhlédněte mi někoho, kdo dobře hraje, a přiveďte mi ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Jeden ze služebníků odpověděl: Hle, viděl jsem syna Jišaje Betlémského, který je schopný hrát; je to ⌈udatný hrdina,⌉ bojovník, rozumný v řeči, pohledný muž a Hospodin je s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Nato Saul poslal k Jišajovi posly se slovy: Pošli mi svého syna Davida, který je u ovcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Jišaj vzal osla, chléb a měch s vínem, jedno kůzle a poslal to Saulovi po svém synu Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'David přišel k Saulovi a ⌈sloužil mu.⌉ Saul si ho velmi zamiloval a David se stal jeho zbrojnošem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Saul poslal k Jišajovi se slovy: Ať mi David slouží, protože nalezl ⌈milost v mých očích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Stávalo se, že když přišel na Saula duch od Boha, David bral lyru a hrál svojí rukou. Saulovi se ulevovalo a bylo mu dobře a zlý duch od něho odstupoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Pelištejci shromáždili svá vojska k boji. Shromáždili se v Sóku, které je v Judsku, a utábořili se u Efes–damímu mezi Sókem a Azekou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Také Saul a Izraelci se shromáždili, utábořili se v údolí Éla a sešikovali se k boji proti Pelištejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Pelištejci stáli na hoře z jedné strany a Izraelci stáli na hoře z druhé strany. Mezi nimi bylo údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Z pelištejských vojsk vycházel soubojový zápasník jménem Goliáš z Gatu, vysoký šest loket a jednu píď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Na hlavě měl bronzovou přilbu a oblékal si šupinový pancíř. ⌈Pancíř vážil⌉ pět tisíc šekelů bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Na nohou měl bronzové holenice a na ramenou bronzový srpáč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Násada jeho kopí byla jako tkalcovské vratidlo a hrot jeho kopí vážil šest set šekelů železa. Před ním šel štítonoš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Stál a volal na izraelské řady. Říkal jim: Proč vycházíte a šikujete se k boji? Cožpak nejsem já Pelištejec a vy otroci Saulovi? Pověřte někoho, ať ke mně sestoupí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Jestliže se mnou dokáže bojovat a zabije mě, budeme vašimi otroky. Jestliže já přemohu jeho a zabiju jej, budete našimi otroky a budete nám sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Pak ten Pelištejec řekl: Dnes potupím izraelské řady. Vydejte mi někoho, ať spolu bojujeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Když Saul a ⌈celý Izrael⌉ uslyšeli tato Pelištejcova slova, třásli se a hrozně se báli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David byl synem Efratejce z judského Betléma jménem Jišaj, který měl osm synů. Za dnů Saulových byl ten muž již pokročilého věku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Tři nejstarší Jišajovi synové šli se Saulem do boje. Jména tří synů, kteří šli do boje, byla: Prvorozený Elíab, druhý po něm Abínádab a třetí Šama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David byl nejmladší. Tři nejstarší šli se Saulem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'David odcházel od Saula a vracel se, aby v Betlémě pásl ovce svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Mezitím Pelištejec přistupoval ráno i večer a takto se stavěl po čtyřicet dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Jišaj řekl svému synu Davidovi: Vezmi svým bratrům éfu tohoto praženého zrní a těchto deset chlebů a rychle jim to zanes do tábora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Těchto deset kusů sýra odnes veliteli nad tisícem. ⌈Zjisti, jak se daří tvým bratrům,⌉ a ⌈vezmi od nich znamení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul, oni a ⌈všichni Izraelci⌉ jsou v údolí Éla a ⌈vedou válku⌉ s Pelištejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'David časně ráno vstal, zanechal ovce hlídači, naložil zásoby a šel, jak mu Jišaj přikázal. Když přišel k ležení, vojsko vycházelo do řad a spustilo válečný křik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Izraelci a Pelištejci se sešikovali řada proti řadě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'David zanechal věci u strážce výstroje a běžel k řadě. Když přišel, vyptával se svých bratrů, jak se jim daří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Zatímco s nimi mluvil, zrovna vystoupil z pelištejských řad soubojový zápasník jménem Goliáš, Pelištejec z Gatu, a říkal stejná slova jako předtím. David to slyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Když všichni Izraelci uviděli toho muže, utekli před ním a hrozně se báli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Izraelci říkali: Viděli jste toho muže, který vystoupil? Vystupuje, aby hanobil Izrael. Stane se proto, že toho, kdo ho zabije, král odmění velikým bohatstvím, dá mu svou dceru a ⌈dům jeho otce⌉ učiní v Izraeli svobodným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'David se zeptal mužů, kteří stáli ⌈u něj:⌉ Co že získá ten, kdo zabije tohoto Pelištejce a odstraní potupu od Izraele? Vždyť kdo je ten neobřezaný Pelištejec, že tupí řady živého Boha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Lid mu odpověděl ⌈stejnými slovy jako předtím:⌉ Toto získá ten, kdo ho zabije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Když jeho nejstarší bratr Elíab slyšel, jak mluví s muži, vzplál proti Davidovi hněvem a řekl: Proč jsi přišel? Komu jsi zanechal těch několik ovcí v pustině? Znám tvou domýšlivost a ⌈zkaženost tvého srdce.⌉ Přišel jsi totiž, aby ses díval na bitvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David řekl: Co jsem teď udělal? ⌈Vždyť jsem se jen ptal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Obrátil se od něj k někomu jinému a zeptal se ⌈stejnými slovy jako předtím.⌉ Lid mu odpověděl ⌈stejnými slovy jako poprvé.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Když se proslechla slova, která David promluvil, oznámili to Saulovi a ten si ho nechal přivést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'David řekl Saulovi: ⌈Ať kvůli němu nikdo neklesá na mysli.⌉ Tvůj otrok půjde a bude bojovat s tímto Pelištejcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul řekl Davidovi: Nemůžeš jít proti tomu Pelištejci a bojovat s ním. Vždyť jsi jen chlapec, a on je bojovníkem od svého mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Nato David řekl Saulovi: Tvůj otrok byl pastýřem ovcí svého otce. Když přišel lev či medvěd a odnesl ovci ze stáda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'vyrazil jsem za ním, bil jsem ho a vysvobodil jsem ji z jeho tlamy. Když proti mně povstal, chytil jsem ho za čelist a bil jsem ho, až jsem ho usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Tvůj otrok zabil jak lva, tak i medvěda a tento neobřezaný Pelištejec dopadne jako jeden z nich, protože tupil řady živého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'David dále řekl: Hospodin, který mě vysvobodil z moci lva i z moci medvěda, ten mě vysvobodí z ruky tohoto Pelištejce. Saul tedy řekl Davidovi: Jdi a Hospodin buď s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Pak Saul oblékl Davida do svého odění, na hlavu mu dal bronzovou přilbu a oblékl mu pancíř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'David si připásal na odění jeho meč a zkoušel chodit, protože ⌈ na to nebyl zvyklý.⌉ David řekl Saulovi: Nemohu v tom chodit, protože na to nejsem zvyklý. Proto si to David ze sebe sundal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Do ruky si vzal hůl, z potoka si vybral pět oblázků, uložil je do pastýřské brašny, kterou měl, a v ní do váčku; v ruce měl prak. Tak se blížil k Pelištejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Mezitím Pelištejec postupoval a stále se blížil k Davidovi. Před ním šel štítonoš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Když se Pelištejec podíval a uviděl Davida, pohrdl jím, protože to byl jen chlapec, ryšavý, krásného vzhledu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Pelištejec řekl Davidovi: Cožpak jsem pes, že jdeš proti mně s holí? Nato Pelištejec Davida proklel při svých bozích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Pak řekl Pelištejec Davidovi: Pojď ke mně a vydám tvé tělo nebeskému ptactvu a polní zvěři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'David Pelištejci odpověděl: Ty jdeš proti mně s mečem, kopím a srpáčem, ale já jdu proti tobě ve jménu Hospodina zástupů, Boha izraelských řad, kterého jsi tupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Dnes tě Hospodin vydá do mé ruky. Zabiju tě a srazím ti hlavu. Dnes vydám mrtvoly pelištejského vojska nebeskému ptactvu a zemské zvěři. A tak celý svět pozná, že s Izraelem je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'A ⌈celé toto shromáždění⌉ pozná, že Hospodin nezachraňuje mečem ani kopím. Neboť tento boj ⌈je Hospodinův⌉ a on vás vydá do naší ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Pak se stalo, že když Pelištejec dále postupoval a blížil se proti Davidovi, David rychle běžel na bojiště proti Pelištejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'David ⌈sáhl rukou⌉ do brašny, vzal odtamtud kámen, vrhl jej z praku a udeřil Pelištejce do čela. Kámen mu prorazil čelo, takže padl tváří k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Tak David ⌈přemohl Pelištejce prakem a kamenem, ubil Pelištejce a usmrtil⌉ ho. ⌈David ne měl v ruce⌉ meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Potom David přiběhl, postavil se nad Pelištejcem, vzal jeho meč, vytáhl ho z pochvy, usmrtil jej a usekl mu s ním hlavu. Když Pelištejci viděli, že je jejich hrdina mrtev, utíkali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, '⌈Izraelci a Judejci⌉ vstali, křičeli a pronásledovali Pelištejce až do Gatu, až k branám Ekrónu. Pobití Pelištejci padali cestou z Šaarajimu až do Gatu a Ekrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Pak se Izraelci vrátili z pronásledování Pelištejců a vyplenili jejich tábor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'David vzal hlavu toho Pelištejce a přinesl ji do Jeruzaléma, ale jeho zbraně uložil ve svém stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Když Saul viděl Davida, jak jde proti tomu Pelištejci, řekl veliteli armády Abnérovi: Čí syn je tento chlapec, Abnére? Abnér odpověděl: Jakože jsi živ, králi, nevím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Král řekl: Zeptej se, čí syn je ten mladík.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Proto když se vracel David ⌈z boje proti Pelištejci,⌉ Abnér ho vzal a přivedl ho před Saula. Hlavu toho Pelištejce měl ještě v ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Saul se ho zeptal: Čí jsi syn, chlapče? David odpověděl: Syn tvého otroka Jišaje Betlémského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Stalo se, že když David domluvil se Saulem, Jónatanova duše se spojila s duší Davidovou. Jónatan si ho zamiloval jako ⌈sebe sama.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Saul ho v onen den přijal do služby a nedovolil mu vrátit se do domu jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Jónatan uzavřel s Davidem smlouvu, protože ho miloval jako sám sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Pak si Jónatan svlékl roucho, které měl na sobě, a dal ho Davidovi. Dal mu také své odění, svůj meč i luk a svůj pás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'David vytáhl, kamkoli ho Saul poslal, a všude měl úspěch. Proto ho Saul ustanovil nad bojovníky. To ⌈se líbilo všemu lidu i Saulovým otrokům.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Stalo se, že jak přicházeli, když se David vracel ⌈z boje proti Pelištejci,⌉ ženy ze všech izraelských měst vyšly vstříc králi Saulovi, aby zpívaly a tančily s tamburínami, s radostí a s triangly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Radující se ženy zpívaly: Saul pobil své tisíce a David své desetitisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Saul se velice rozzlobil a ⌈nelíbilo se mu to.⌉ Řekl: Davidovi přiřkly desetitisíce a mně přiřkly tisíce. Už mu chybí jen království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Od onoho dne Saul ⌈hleděl na Davida s podezřením.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Příštího dne se stalo, že Saula uchvátil zlý duch od Boha a choval se uvnitř paláce jako prorok. David hrál svou rukou na loutnu jako každý den. Saul měl v ruce kopí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Vtom Saul vrhl kopí, neboť si řekl: ⌈Přibodnu Davida ke stěně.⌉ David však před ním dvakrát uhnul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Saul se Davida bál, protože ⌈s ním byl Hospodin,⌉ kdežto od Saula odstoupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Proto ho Saul od sebe odstranil a ustanovil ho velitelem nad tisícem, aby ⌈vycházel a vcházel před lidem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Stalo se, že David měl ⌈na všech svých cestách⌉ úspěch a Hospodin byl s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Když Saul viděl, že má David velký úspěch, měl z něho strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Celý Izrael i Juda však Davida miloval, protože ⌈před nimi vycházel a vcházel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Saul řekl Davidovi: Zde je má starší dcera Mérab. Dám ti ji za ženu. Jenom ⌈buď mým bojovníkem⌉ a bojuj ⌈Hospodinovy boje.⌉ Saul si totiž řekl: Ať proti němu není moje ruka. Ať je proti němu ruka Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'David ale Saulovi odpověděl: Kdo jsem já a co je můj rod, čeleď mého otce v Izraeli, abych se stal královým zetěm?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Tehdy, kdy měla být Saulova dcera Mérab dána Davidovi, se však stalo, že byla dána za ženu Adríelovi Mechólatskému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Pak se do Davida zamilovala Saulova dcera Míkal. Když to Saulovi oznámili, ⌈líbilo se mu to.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Saul řekl: Dám mu ji, stane se mu léčkou a bude proti němu ruka Pelištejců. Davidovi potom Saul řekl: Staň se dnes mým zetěm prostřednictvím druhé dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Svým otrokům Saul přikázal: Řekněte Davidovi potají toto: Podívej, král si tě oblíbil a všichni jeho otroci tě mají rádi. Staň se nyní královým zetěm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Saulovi otroci řekli tato slova Davidovi, ale David odpověděl: Připadá vám to snadné se stát královým zetěm? Vždyť já jsem chudý a bezvýznamný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Saulovi otroci Saulovi oznámili: ⌈David odpověděl tak a tak.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul nato řekl: Povězte Davidovi toto: Král ⌈netouží po⌉ věnu, ale po stu předkožek Pelištejců, aby se pomstil na králových nepřátelích. Saul totiž zamýšlel nechat Davida padnout rukou Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Jeho otroci oznámili tato slova Davidovi a Davidovi se to líbilo, že se stane královým zetěm. ⌈Nenaplnily se ani určené dny⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'a David vstal, vytáhl se svými muži a pobil ⌈dvě stě⌉ Pelištejců. David přinesl jejich předkožky a ⌈předložil je v plném počtu před krále,⌉ aby se stal královým zetěm. Saul mu pak dal svou dceru Míkal za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Když viděl Saul a poznal, že Hospodin je s Davidem a Saulova dcera Míkal ho miluje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'ještě více se Saul Davida bál a byl po všechen čas Davidovým nepřítelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Pelištejští velitelé dále vycházeli do boje. Pokaždé, když vytáhli, David měl větší úspěch než všichni Saulovi otroci. Proto ⌈bylo jeho jméno velmi vážené.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Saul řekl svému synu Jónatanovi a všem svým otrokům, aby Davida usmrtili. Ale Saulův syn Jónatan si Davida velmi oblíbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Jónatan Davidovi oznámil: Můj otec Saul tě chce usmrtit. Tak se měj ráno na pozoru; zůstaň v úkrytu, ať jsi schovaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Vyjdu a postavím se vedle svého otce na poli, kde budeš. Promluvím o tobě s otcem, a když ně co zjistím, oznámím ti to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Jónatan mluvil se svým otcem Saulem v Davidův prospěch a řekl mu: Ať král nezhřeší proti svému otroku Davidovi. Vždyť proti tobě nezhřešil a jeho skutky jsou pro tebe velmi prospěšné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, '⌈Vystavil svůj život nebezpečí,⌉ zabil Pelištejce a Hospodin způsobil velkou záchranu celému Izraeli. Viděl jsi to a radoval ses. Proč bys hřešil proti nevinné krvi a Davida bezdůvodně usmrtil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Saul uposlechl Jónatana a přísahal: Jakože živ je Hospodin, ne bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Jónatan zavolal Davida a oznámil mu všechna tato slova. Potom Jónatan přivedl Davida k Saulovi a býval v jeho přítomnosti jako předtím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Znovu došlo k válce. David vytáhl, aby bojoval proti Pelištejcům. ⌈Způsobil jim tak velkou porážku,⌉ že před ním utíkali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Na Saula ovšem padl zlý duch od Hospodina. Pobýval tehdy ve svém paláci, v ruce měl kopí a David hrál rukou na loutnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Saul chtěl Davida přibodnout kopím ke stěně. Ten ale před Saulem uhnul, takže Saul přibodl kopí do stěny. David té noci utekl a zachránil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Saul poslal k Davidovu domu posly, aby ho střežili a ráno jej usmrtili. Avšak Davidovi jeho žena Míkal oznámila: Jestliže si této noci nezachráníš život, zítra budeš mrtev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Míkal spustila Davida z okna a on vyšel, utekl a zachránil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Míkal vzala domácího bůžka, položila ho do postele, roušku z kozí srsti položila ⌈ do hlav⌉ a přikryla oděvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Když poslal Saul posly, aby Davida zajali, řekla: Je nemocen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Saul ovšem ty posly poslal, aby se na Davida podívali. Řekl: Přineste mi ho na posteli, abych ho mohl usmrtit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Když poslové přišli, uviděli, že na posteli je domácí bůžek a rouška z kozí srsti v hlavách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Saul se potom Míkal zeptal: Proč jsi mě takto podvedla a propustila jsi mého nepřítele, aby se zachránil? Míkal Saulovi odpověděla: On mi řekl: Propusť mě. ⌈Proč bych tě měl usmrtit?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David utekl, zachránil se a přišel k Samuelovi do Rámy. Oznámil mu všechno, co mu Saul udělal. Pak šel se Samuelem a pobýval v Nájótu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Saulovi bylo oznámeno: Hle, David je v Nájótu u Rámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Nato Saul poslal posly, aby Davida zajali. Když uviděli skupinu proroků, kteří prorokovali, a Samuela, který stál ⌈ustanoven nad nimi,⌉ na Saulovy posly padl ⌈Duch Boží⌉ a také oni prorokovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Když to Saulovi oznámili, poslal další posly, ale také oni prorokovali. Znovu, potřetí poslal Saul posly, ale také oni prorokovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Nakonec se do Rámy vydal sám. Když přišel k velké cisterně, která je v Sekú, zeptal se: Kde je Samuel a David? Kdosi řekl: Hle, jsou v Nájótu u Rámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Šel tedy směrem do Nájótu u Rámy a také na něj padl Duch Boží. Šel a přitom prorokoval, až přišel do Nájótu u Rámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Také on si svlékl oděv a také on prorokoval před Samuelem. Celý ten den a celou noc ležel nahý. Proto se říká: Cožpak je také Saul mezi proroky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David utekl z Nájótu u Rámy, ⌈přišel za Jónatanem a zeptal se:⌉ Co jsem udělal? Jaká je má vina a jaký je můj hřích vůči tvému otci, že usiluje o můj život?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Odpověděl mu: ⌈Ať je to od tebe vzdáleno,⌉ nezemřeš. Podívej, můj otec neudělá nic ⌈velkého ani malého,⌉ aniž by mi to prozradil. Proč by můj otec něco takového přede mnou skrýval? ⌈Není tomu tak.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'David se ještě zapřísahal: Tvůj otec dobře ví, že jsem ⌈nalezl milost ve tvých očích⌉ a řekl si: Ať se to Jónatan nedozví, jinak se bude trápit. Avšak jakože živ je Hospodin a jakože ⌈živ jsi ty,⌉ jen ⌈krok je mezi mnou a smrtí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jónatan Davidovi pověděl: ⌈Cokoliv řekneš,⌉ to pro tebe udělám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Nato David Jónatanovi řekl: Podívej, zítra je novoluní a já mám zasednout s králem k jídlu. Propusť mě, abych se až do třetího večera ukryl na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Jestliže ⌈mě bude tvůj otec postrádat,⌉ řekni: David si ode mě naléhavě vyžádal dovolení, aby si mohl odběhnout do svého města Betléma, neboť je tam každo roční oběť pro celou čeleď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Jestliže řekne: Dobře, ⌈ znamená to pokoj pro tvého otroka.⌉ Ale jestliže se velmi rozzlobí, věz, že ⌈je rozhodnut vykonat něco zlého.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Prokaž svému otroku milosrdenství, neboť jsi uvedl svého otroka v Hospodinovu smlouvu se sebou. Jestliže je na mně vina, usmrť mě ty. Proč bys mě vodil ke svému otci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jónatan odpověděl: Ať je to od tebe vzdáleno. Jestliže se opravdu dozvím, že ⌈můj otec je rozhodnut vykonat vůči tobě něco zlého,⌉ ⌈oznámím ti to.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'David se zeptal Jónatana: Kdo mi to oznámí, když ti tvůj otec odpoví tvrdě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jónatan řekl Davidovi: Pojď, vyjděme na pole. A oba vyšli na pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Jónatan řekl Davidovi: ⌈ Při Hospodinu, Bohu Izraele,⌉ zítra touto dobou či pozítří se vyptám svého otce. Jestliže ⌈bude s Davidem dobře,⌉ tehdy pošlu za tebou a prozradím ti to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Jestliže můj otec zamýšlí vůči tobě zlo, ať tak Hospodin učiní Jónatanovi a ještě přidá, pokud ti to ne prozradím a ne propustím tě, abys odešel v pokoji. Ať je Hospodin s tebou, tak jako byl s mým otcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Dokud ještě žiji, prokazuj mi ⌈Hospodinovo milosrdenství,⌉ ⌈abych nezemřel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Navěky ⌈neodejmi své milosrdenství mému domu, i potom, co Hospodin do jednoho vyhladí⌉ Davidovy nepřátele z povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Tak Jónatan uzavřel s domem Davidovým smlouvu a dodal: ⌈ Ať Hospodin vyžaduje její naplnění i skrze⌉ Davidovy nepřátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Jónatan znovu zapřísahal Davida při své lásce k němu, protože ho miloval ⌈ jako sám sebe.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Jónatan mu řekl: Zítra je novoluní. Budeš postrádán, protože tvé sedadlo bude prázdné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Třetího dne rychle sestup, jdi na místo, kde ses ukrýval v den činu, a zůstaň u ⌈kamene Ezelu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Já vystřelím tři šípy v tu stranu, jako bych střílel na terč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Pak zrovna pošlu služebníka se slovy: Jdi a najdi šípy. Jestliže služebníkovi jasně řeknu: Podívej, šípy jsou ⌈blíž k tobě,⌉ seber je, pak přijď, protože to znamená pokoj pro tebe a nic ti ne hrozí, jakože živ je Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Jestliže však mladíkovi řeknu: Podívej, šípy jsou ⌈dál od tebe,⌉ jdi, protože tě Hospodin posílá pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, '⌈ Ohledně věci, o které jsme se já a ty domluvili,⌉ ať je Hospodin svědkem mezi mnou a tebou navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'David se pak ukryl na poli. Když nastalo novoluní, král zasedl ⌈za stůl k jídlu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Král seděl na svém sedadle jako jindy, na sedadle u stěny. ⌈Když Jónatan vstal, Abnér si sedl⌉ Saulovi po boku. Davidovo místo bylo prázdné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul onen den nic nepověděl, neboť si řekl: ⌈ Něco se mu přihodilo,⌉ ⌈je nečistý, ano,⌉ není čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Stalo se, že příští den, druhý den ⌈nového měsíce,⌉ bylo Davidovo místo zase prázdné. Saul řekl Jónatanovi, svému synu: Proč nepřišel syn Jišajův ani včera ani dnes ke stolu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jónatan Saulovi odpověděl: David si ode mě naléhavě vyžádal dovolení jít do Betléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Řekl: Propusť mne, prosím, neboť máme ve městě ⌈rodinnou oběť⌉ a můj bratr mi to přikázal. A tak jestliže jsem nalezl milost ve tvých očích, nech mě odejít, abych viděl své bratry. Proto nepřišel ke královskému stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Saul vzplál proti Jónatanovi hněvem a řekl mu: Ty ⌈synu zvrácené odbojnice.⌉ Vždyť jsem to věděl, že je ti milý syn Jišajův, ke tvé hanbě a k hanbě nahoty tvé matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Vždyť po všechny dny, co bude syn Jišajův živ na zemi, nebudeš pevně stát ty ani tvé království. Teď pošli a doveď ho ke mně, protože ⌈je synem smrti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jónatan odpověděl svému otci Saulovi a řekl mu: Proč by měl být usmrcen? Co provedl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Saul po něm vrhl kopí, aby ho probodl. A tak Jónatan poznal, že jeho otec je rozhodnut Davida usmrtit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Jónatan planoucí hněvem vstal od stolu a druhý den měsíce nejedl pokrm, protože se trápil kvůli Davidovi, že ho jeho otec vystavil hanbě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Ráno se stalo, že Jónatan vyšel na pole na setkání s Davidem. Byl s ním mladý služebník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Řekl svému služebníkovi: Běž a najdi šípy, které vystřelím. Zatímco služebník běžel, vystřelil před něj šípy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Když služebník přišel na ⌈místo, kam dopadly šípy, které⌉ Jónatan vystřelil, Jónatan za služebníkem zavolal: Šípy jsou ještě dál od tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Jónatan za služebníkem zavolal: Rychle, pospěš si, neotálej! Jónatanův služebník posbíral šípy a přišel ke svému pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Služebník o ničem nevěděl. Jen Jónatan a David znali tu úmluvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Jónatan dal svou výstroj služebníkovi, který byl s ním, a řekl mu: Jdi a odnes to do města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Když služebník odešel, David vstal zpoza hromady, padl tváří k zemi a třikrát se poklonil. Jeden druhého políbili a jeden jako druhý plakali, ⌈ale David víc.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Jónatan řekl Davidovi: ⌈Jdi v pokoji,⌉ protože jsme si my dva přísahali v Hospodinově jménu slovy: Hospodin budiž svědkem mezi mnou a tebou i mezi potomstvem mým a tvým až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'David vstal a odešel. Jónatan šel do města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David přišel ke knězi Achímelekovi do Nóbu. Achímelek šel vyděšen Davidovi naproti a zeptal se ho: Proč jsi sám a není nikdo s tebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'David knězi Achímelekovi odpověděl: Král mi něco přikázal a řekl mi: Ať se nikdo nedozví nic o tom, s čím tě posílám a co jsem ti přikázal. Se služebníky se sejdu na určitém místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Nyní tedy, co máš ⌈po ruce?⌉ Dej mi pět chlebů nebo co se najde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Kněz Davidovi odpověděl: Nemám ⌈po ruce⌉ chléb obyčejný, jenom posvátný; pouze jestli se služebníci ⌈zdrželi styku s ženou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'David knězi odpověděl a řekl mu: ⌈Jistě, že jsme se zdrželi ženy⌉ již ⌈včera a předevčírem,⌉ kdy jsem vytáhl, a zbraně služebníků by byly svaté, i kdyby byla cesta obyčejná, tím spíše, když se dnes posvětili kvůli zbraním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Kněz mu tedy dal posvátný chléb, protože tam nebyl jiný chléb nežli předkladný, který byl vzat od Hospodina, aby byl položen horký chléb tehdy, když se bral starý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'V ten den tam byl zadržován před Hospodinem jeden ze Saulových otroků jménem Dóeg Edómský, předák Saulových pastýřů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'David se Achímeleka zeptal: Nemáš tu ⌈po ruce⌉ kopí či meč? Nevzal jsem si s sebou svůj meč ani jinou svou zbraň, protože králova záležitost byla naléhavá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Kněz odpověděl: Meč Pelištejce Goliáše, kterého jsi zabil v údolí Éla, je zde, zabalený do pláště za efódem. Jestli si ho chceš vzít, vezmi si ho, protože kromě tohoto zde jiný není. David nato řekl: Není ⌈mu podobného.⌉ Dej mi ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Potom David vstal a utekl v ten den před Saulem; přišel k Akíšovi, králi Gatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Akíšovi otroci mu řekli: Což to není David, král země? Což o něm nezpívali při tancích: Saul pobil své tisíce, ale David své desetitisíce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'David ⌈se těchto slov obával⌉ a hrozně se bál Akíše, krále Gatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'A tak ⌈před nimi předstíral, že je blázen,⌉ choval se u nich jako šílený, dělal značky na vrata brány a ⌈pouštěl sliny⌉ na svůj vous.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Akíš řekl svým otrokům: Tak se podívejte na toho potřeštěnce. Proč jste ho ke mně přivedli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 16, 'Nemám dost potřeštěnců, že jste přivedli tohoto, aby přede mnou třeštil? ⌈Proč tenhle přišel⌉ do mého paláce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Pak odtamtud David odešel a unikl do adulamské jeskyně. Když se o tom doslechli jeho bratři a celý dům jeho otce, přišli tam za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Shromáždili se k němu všichni, kdo byli v úzkostech, všichni, kdo měli dluh, a všichni, ⌈kdo měli hořkost v duši;⌉ a stal se jejich velitelem. Bylo s ním asi čtyři sta mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'David šel odtamtud do moábské Mispy a moábskému králi řekl: Dovol, ať můj otec a má matka přijdou a zůstanou u vás, dokud se ne dozvím, co ⌈pro mě⌉ Bůh učiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Nato je přivedl před moábského krále a pobývali u něho po všechny dny, co byl David v pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Avšak prorok Gád řekl Davidovi: Nepobývej v pevnosti: Odejdi a jdi do judské země. David tedy šel a přišel do cheretského lesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Saul se doslechl, že David a muži, kteří byli s ním, ⌈byli odhaleni.⌉ Saul tehdy seděl v Gibeji pod tamaryškem na výšině. V ruce měl své kopí a všichni jeho otroci stáli kolem něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Saul řekl svým otrokům, kteří stáli kolem něho: Poslyšte, Benjamínovci! Což vám všem dá ⌈syn Jišajův⌉ pole a vinice? Všechny vás ustanoví za velitele nad tisíci a velitele nad sty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Proto jste se všichni proti mně spikli? Nikdo ⌈mi ne prozradí,⌉ že můj syn uzavřel smlouvu se synem Jišajovým. Nikdo z vás ⌈se kvůli mně ne trápí⌉ a ne prozradí mi, že můj syn podporuje mého otroka proti mně, aby mi nastražil léčku, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Dóeg Edómský, který byl ustanoven nad Saulovými otroky, odpověděl: Viděl jsem syna Jišajova, jak přišel do Nóbu k Achímelekovi, synu Achítúbovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Ten se na něj doptával Hospodina, dal mu potraviny a také mu dal meč Pelištejce Goliáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Nato ⌈si dal král zavolat⌉ kněze Achímeleka, syna Achítúbova, a celý dům jeho otce, kněze, kteří byli v Nóbu. Všichni přišli ke králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Saul řekl: Poslyš, synu Achítúbův. On odpověděl: Zde jsem, můj pane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Saul mu řekl: Proč jste se proti mně spikli, ty a syn Jišajův, když jsi mu dal pokrm a meč a doptával ses na něj Boha, aby povstal proti mně a nastražil mi léčku, jak je tomu dnes?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Achímelek králi odpověděl: Kdo ze všech tvých otroků je věrný jako David? Je královým zetěm, velitelem tvé tělesné stráže a je vážený ve tvém domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, '⌈Což jsem se teprve dnes na něj začal doptávat⌉ Boha? ⌈Ať je to ode mě vzdáleno.⌉ Nechť král ⌈nepřičítá nic zlého ⌉ svému otroku ani celému domu mého otce, neboť tvůj otrok o celé této záležitosti nic neví, ⌈ani to nejmenší.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Král řekl: Jistě zemřeš, Achímeleku, ty i celý dům tvého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Běžcům, kteří stáli kolem něj, král řekl: Obraťte se a usmrťte Hospodinovy kněze, neboť také jejich ruka je s Davidem. Vždyť věděli, že ⌈je na útěku,⌉ a ⌈neprozradili mi to.⌉ Královi otroci však nechtěli vztáhnout ruku a zasáhnout proti Hospodinovým kněžím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Nato král řekl Dóegovi: Obrať se ty a zasáhni proti kněžím. Dóeg Edómský se obrátil, sám zasáhl proti kněžím a usmrtil v onen den osmdesát pět mužů, kteří nosili lněný efód.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'I kněžské město Nób vybil ostřím meče; ⌈muže i ženy,⌉ děti i kojence, býky, osly i ovce vybil ostřím meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Unikl jeden syn Achímeleka, syna Achítúbova, jménem Ebjátar, a utekl za Davidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Ebjátar Davidovi oznámil, že Saul zabil Hospodinovy kněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'David Ebjátarovi řekl: Věděl jsem v onen den, kdy tam byl Dóeg Edómský, že to určitě oznámí Saulovi. Já jsem ⌈vinen všemi zmařenými životy⌉ domu tvého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Pobývej se mnou. Neboj se, protože ten, kdo usiluje o můj život, usiluje i o tvůj život. U mne nalezneš ochranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Tehdy Davidovi oznámili: Hle, Pelištejci bojují proti Keíle a plení humna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'David se doptával Hospodina: Mám jít a pobít tyto Pelištejce? Hospodin Davidovi řekl: Jdi, pobij Pelištejce a zachraň Keílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Davidovi muži mu však řekli: Podívej, my se bojíme i tady v Judsku, tím spíše, když vytáhneme do Keíly ⌈na bojiště s Pelištejci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'David se tedy znovu doptával Hospodina. A Hospodin mu odpověděl: Vstaň a sestup do Keíly, protože vydám Pelištejce do tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Nato David se svými muži vytáhl do Keíly a bojoval proti Pelištejcům. Odehnal jejich dobytek a způsobil jim velikou porážku. Tak David zachránil obyvatele Keíly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Stalo se, že když Ebjátar, syn Achímelekův, utekl za Davidem do Keíly, vzal si s sebou efód.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Saulovi bylo oznámeno, že David přišel do Keíly. Saul řekl: Bůh ho vydal do mé ruky, protože se chytil, když vešel do města s vraty a závorami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Saul svolal všechen lid k boji, aby sestoupil ke Keíle a oblehl Davida a jeho muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Když se David dozvěděl, že Saul proti němu zamýšlí zlo, řekl knězi Ebjátarovi: Přines efód.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'David řekl: Hospodine, Bože Izraele, tvůj otrok se s jistotou doslechl, že Saul chce vytáhnout na Keílu, aby kvůli mně zničil město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Vydají mě občané Keíly do jeho ruky? Sestoupí Saul, tak jak se tvůj otrok doslechl? Hospodine, Bože Izraele, oznam to, prosím, svému otroku. Hospodin odpověděl: Sestoupí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Pak se David zeptal: Vydají občané Keíly mě a mé muže do Saulovy ruky? Hospodin odpověděl: Vydají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Nato vstal David se svými muži (asi šest set lidí), vytáhli z Keíly a ⌈chodili, kde se dalo.⌉ Když bylo Saulovi oznámeno, že David unikl z Keíly, zanechal tažení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'David pobýval v pustině v pevnostech a pobýval v horách v pustině Zífu. Saul ho po celý čas hledal, ale Bůh ho nevydal do jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'David zjistil, že Saul vytáhl, aby usiloval o jeho život (tehdy byl v pustině Zífu v Choreši).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Jónatan, syn Saulův, vstal a šel za Davidem do Choreše a ⌈posilnil jeho ruku⌉ v Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Řekl mu: Neboj se, protože ruka mého otce Saula tě nenalezne. Ty budeš kralovat nad Izraelem a já budu druhý po tobě. I můj otec Saul to ví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Oba uzavřeli smlouvu před Hospodinem. David pak pobýval v Choreši a Jónatan šel do svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Tehdy přišli za Saulem do Gibeje Zífejci se slovy: David se skrývá u nás v pevnostech v Choreši, na kopci Chakíle, který je na jih od Ješímónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, '⌈Kdykoliv se ti zlíbí⌉ přijít, králi, přijď. Na nás bude, abychom je vydali do královy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Saul odpověděl: Jste požehnaní Hospodinu, neboť máte se mnou soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Nuže jděte a znovu to prověřte. ⌈Zkoumejte a zjistěte⌉ místo, ⌈kudy chodí⌉ a kdo ho tam viděl, neboť mi bylo řečeno, že je velmi vychytralý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Prohlédněte a prozkoumejte všechny skrýše, ⌈kde se ukrývá.⌉ Pak se vraťte ke mně s prověřenými zprávami a půjdu s vámi. Jestliže je v zemi, vyhledám ho mezi všemi ⌈judskými rody.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Nato vstali a šli před Saulem do Zífu. David se svými muži byl v pustině Maónu, v stepi na jih od Ješímónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Když ho totiž Saul se svými muži šel hledat, Davidovi to oznámili, a ten proto sestoupil ke skále a pobýval v pustině Maónu. Jakmile se to Saul doslechl, pronásledoval Davida v pustině Maónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Saul šel po jedné straně hory a David se svými muži po druhé straně hory. David se snažil před Saulem rychle utéct, zatímco Saul se svými muži Davida s jeho muži obkličoval, aby je chytili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'K Saulovi však přišel posel se slovy: ⌈Rychle odtáhni,⌉ protože do země vtrhli Pelištejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Nato přestal Saul Davida pronásledovat a vytáhl proti Pelištejcům. Proto se toto místo nazývá ⌈Skála rozdělení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'David odtamtud vytáhl a pobýval v pevnostech Én–gedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Stalo se, že když se Saul vrátil z pronásledování Pelištejců, oznámili mu: Hle, David je v pustině Én–gedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Saul vzal tři tisíce mužů vybraných z celého Izraele a vydal se hledat Davida a jeho muže směrem ke Kozorožčím skalám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Když došel k ovčím ohradám u cesty, byla tam jeskyně. Saul do ní vstoupil, aby si ulevil. David se svými muži seděl vzadu v jeskyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Davidovi muži mu řekli: Hle, toto je den, o kterém ti Hospodin řekl: Hle, vydám tvého nepřítele do tvé ruky. Učiň mu to, co ⌈se ti líbí.⌉ David vstal a potají odřízl okraj Saulova pláště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Potom se však stalo, že ⌈Davida trápilo svědomí⌉ kvůli tomu, že odřízl okraj Saulova pláště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Svým mužům řekl: Ať je to ode mě vzdáleno kvůli Hospodinu, abych učinil něco takového svému pánu, Hospodinovu pomazanému, a vztáhl na něj ruku, neboť je to Hospodinův pomazaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Těmito slovy David bránil svým mužům a nedovolil jim povstat proti Saulovi. Saul vstal, vyšel z jeskyně a šel svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Potom vstal i David, vyšel z jeskyně a volal za Saulem: Můj pane a králi. Když se za ním Saul ohlédl, poklekl s tváří k zemi a klaněl se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Nato David Saulovi řekl: Proč posloucháš slova ⌈těch, kdo říkají:⌉ Hle, David usiluje o tvé zlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Hle, ⌈tvé oči v tento den viděly,⌉ že tě Hospodin dnes vydal v jeskyni do mé ruky. Říkali mi, abych tě zabil, ale slitoval jsem se nad tebou; řekl jsem: Nevztáhnu ruku na svého pána, neboť je to Hospodinův pomazaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Otče můj, pohleď a podívej se na okraj svého pláště v mé ruce. Když jsem odřízl okraj tvého pláště a nezabil tě, hleď se přesvědčit, že na mé ruce není zlo ani přestoupení. Nezhřešil jsem proti tobě, ale ty číháš na můj život, ⌈abys mě o něj připravil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Ať Hospodin soudí mezi mnou a tebou! Ať mě Hospodin pomstí na tobě, ale má ruka proti tobě nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Jak říká dávné přísloví: Od ničemů vychází ničemnost, ale má ruka proti tobě nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Proti komu vytáhl izraelský král? Koho pronásleduješ? Mrtvého psa? Jednu blechu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Ať je Hospodin soudcem a soudí mezi mnou a tebou! Ať pohlédne a vede můj spor a zjedná mi právo vůči tobě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Stalo se, že když David domluvil tato slova k Saulovi, Saul řekl: Je to tvůj hlas, můj synu Davide? Pak Saul ⌈pozvedl svůj hlas a rozplakal se.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Řekl Davidovi: Jsi spravedlivější nežli já, neboť jsi ⌈mi způsobil dobro,⌉ zatímco já ⌈jsem ti působil zlo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Dnes jsi dokázal, že jsi se mnou jednal dobře: Když mě Hospodin vydal do tvé ruky, nezabils mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Vždyť najde–li někdo svého nepřítele, propustí ho v dobrém? Ať ti odplatí Hospodin dobrem za to, co jsi mi dnes učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Nyní vím, že opravdu budeš kralovat a izraelské království ⌈ve tvé ruce⌉ obstojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Proto mi nyní ⌈přísahej při Hospodinu,⌉ že ne vyhladíš mé potomstvo po mně a nevyhladíš mé jméno z domu mého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'David Saulovi přísahal. Pak Saul odešel do svého paláce a David se svými muži šel do pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Když Samuel zemřel, shromáždil se celý Izrael, oplakával ho a pohřbili ho v jeho domě v Rámě. David pak vstal a odešel do Páranské pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'V Maónu byl nějaký muž, ⌈který měl statek⌉ na Karmelu. Ten muž byl velmi zámožný. Měl tři tisíce ovcí a tisíc koz. Tehdy byl na Karmelu stříhat své ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Ten muž se jmenoval Nábal a jeho žena se jmenovala Abígajil. Ta žena byla velmi ⌈rozumná a krásného vzezření,⌉ ale ten muž byl tvrdý a jeho činy zlé. Byl to Kálebovec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'David se v pustině doslechl, že Nábal stříhá své ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Nato David poslal deset služebníků. David služebníkům řekl: Vystupte na Karmel, jděte k Nábalovi a ⌈zeptejte se ho mým jménem, jak se mu daří.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Řekněte toto: Buď živ, ⌈pokoj tobě,⌉ pokoj tvému domu a pokoj všemu, co máš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Právě jsem slyšel, že máš stříž. Tví pastýři byli s námi a ⌈neubližovali jsme jim⌉ ani nic nepostrádali po všechny dny, co jsme byli na Karmelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Zeptej se svých služebníků a povědí ti to. Kéž naleznou služebníci milost ve tvých očích, neboť přišli ve slavnostní den. Dej prosím svým otrokům a svému synu Davidovi, co ⌈máš po ruce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Davidovi služebníci šli, pověděli Nábalovi všechna tato slova Davidovým jménem a čekali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nábal však Davidovým otrokům odpověděl: Kdo je David a kdo je syn Jišajův? Dnes je mnoho otroků, kteří utíkají od svých pánů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Mám snad vzít svůj chléb, svou vodu a maso z dobytka, který jsem porazil pro své střihače, a dát to mužům, o nichž nevím, odkud jsou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Davidovi služebníci se tedy obrátili a vrátili. Přišli a oznámili Davidovi všechna ta slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'David řekl svým mužům: Připásejte si každý svůj meč. Připásali si meč a také David si připásal svůj meč. Asi čtyři sta mužů šlo za Davidem a dvě stě jich zůstalo u výstroje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Jeden ze služebníků oznámil Nábalově ženě Abígajile: Hle, David poslal z pustiny posly, aby pozdravili našeho pána, ale on se na ně osopil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Ti muži ⌈ se k nám chovali velmi hezky,⌉ neubližovali nám a nic jsme nepostrádali po všechny dny, co jsme s nimi žili, když jsme byli na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Byli nám hradbou ⌈v noci i ve dne⌉ po všechny dny, co jsme byli s nimi a pásli ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Tak ⌈rozvaž a zjisti,⌉ co můžeš udělat, neboť na našeho pána a na celý jeho dům se hrne zlo. On je ničemník a nedá se s ním mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Abígajil rychle vzala dvě stě chlebů, dva měchy vína, pět upravených ovcí, pět měr praženého zrní, sto sušených hroznů, dvě stě koláčů z lisovaných fíků a naložila to na osly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Svým služebníkům řekla: Jděte přede mnou, já půjdu za vámi. Svému muži Nábalovi však nic neoznámila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Jela na oslu a sestupovala kryta horou a David se svými muži zrovna sestupovali proti ní. Setkala se s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'David si říkal: Ano, marně jsem střežil v pustině všechno, co patří tomuto muži, takže nic ze všeho, co mu patří, nepostrádal. Odplatil mi však zlem za dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Tak ať Bůh učiní Davidovým nepřátelům a ještě přidá, jestliže ze všech, kteří mu patří, ponechám do rána někoho ⌈močícího na stěnu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Když Abígajil uviděla Davida, rychle sesedla z osla, padla před Davidem na tvář a klaněla se k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Padla mu k nohám a řekla: ⌈Má, má je to vina,⌉ můj pane. Kéž smí k tobě tvá otrokyně promluvit, vyslechni slova své otrokyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Ať si můj pán nevšímá toho ničemníka Nábala. Vždyť ⌈je takový, jaké je jeho jméno.⌉ Jmenuje se Nábal (Pošetilec) a pošetilost je při něm. Já, tvoje otrokyně, jsem neviděla služebníky svého pána, které poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'A nyní, můj pane, jakože živ je Hospodin a jakože živ jsi ty, Hospodin tě zadržel, abys ne prolil krev a ne pomohl si vlastní rukou. Nuže ať jsou jako Nábal tvoji nepřátelé a ti, kdo usilují o zlo pro mého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Kéž tento dar, který přinesla tvá služka svému pánu, je nyní dán služebníkům, kteří chodí v šlépějích mého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Sejmi, prosím, přestoupení ze své otrokyně. Vždyť Hospodin jistě učiní mému pánu trvalý dům, neboť můj pán vede Hospodinovy boje a ⌈po všechny tvé dny⌉ se při tobě nenašlo nic zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Kdyby někdo povstal, aby tě pronásledoval a usiloval o tvůj život, život mého pána bude svázán do svazku žijících s Hospodinem, tvým Bohem, ale život tvých nepřátel vyvrhne jako z praku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Stane se, že až Hospodin mému pánu učiní všechno dobro, které o tobě vyhlásil, a ustanoví tě vévodou nad Izraelem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'ať to není pro tebe pokleskem ani ⌈výčitkou svědomí⌉ mého pána, že bezdůvodně prolil krev a že ⌈si můj pán sám pomohl.⌉ Až Hospodin prokáže mému pánu dobro, vzpomeň na svou otrokyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Nato David Abígajile odpověděl: ⌈Požehnaný je Hospodin, Bůh Izraele,⌉ že tě dnes poslal, ⌈ abys mi vyšla naproti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Požehnaná je tvá rozvaha a požehnaná jsi ty, že jsi mě dnes zadržela, abych ne prolil krev a ne pomohl si sám vlastní rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Ano, jakože živ je Hospodin, Bůh Izraele, který mě zadržel, abych ne spáchal zlo proti tobě, kdybys mi nevyšla rychle naproti, nezůstal by Nábalovi do svítání nikdo močící na stěnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'David si od ní vzal to, co mu přinesla, a řekl jí: Jdi v pokoji domů. Podívej, uposlechl jsem tě a ⌈beru na tebe ohled.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, '⌈Potom šla⌉ Abígajil k Nábalovi. Ten měl doma hostinu, ⌈jakou mívá král.⌉ ⌈Byl v dobrém rozmaru⌉ a hrozně opilý. Proto mu až do svítání vůbec nic neoznámila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Ráno, když ⌈Nábal vystřízlivěl,⌉ mu to všechno jeho žena pověděla. ⌈Selhalo mu⌉ srdce a ⌈ztuhl jako kámen.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Asi po deseti dnech se stalo, že Hospodin postihl Nábala a ten zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Když David uslyšel, že Nábal zemřel, řekl: Požehnaný je Hospodin, že se mě zastal ohledně Nábalovy potupy vůči mně a zadržel svého otroka, ⌈aby nespáchal zlo.⌉ Hospodin obrátil Nábalovo zlo na jeho hlavu. Nato David poslal k Abígajile se vzkazem, že si ji chce vzít za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Když přišli Davidovi otroci k Abígajile na Karmel, řekli jí: Poslal nás k tobě David, že si tě chce vzít za ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Ona vstala, poklonila se tváří k zemi a řekla: Hle, tvá otrokyně bude služkou a bude umývat nohy otroků svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Abígajil rychle vstala, vyjela na oslu a také pět jejích služek, které šly v jejích šlépějích. Tak odešla s Davidovými posly a stala se jeho ženou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David si vzal také Achínoamu z Jizreelu a obě byly jeho ženami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Saul však dal svou dceru Míkal, Davidovu ženu, Paltímu, synu Lajišovu, který byl z Galímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Tehdy přišli za Saulem do Gibeje Zífejci se slovy: David se skrývá na kopci Chakíla směrem k Ješímónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Saul vstal a sestoupil do pustiny Zífu -- spolu s ním tři tisíce mužů vybraných z Izraele -- aby hledal Davida v pustině Zífu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Saul se utábořil na kopci Chakíla u cesty směrem k Ješímónu. David pobýval v pustině. Když zjistil, že Saul za ním přišel do pustiny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'poslal David zvědy, aby se dozvěděl, že Saul opravdu přitáhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Potom David vstal a šel na místo, kde se utábořil Saul. David zjistil místo, kde spal Saul i Abnér, syn Nérův, velitel armády. Saul spal v ležení a lid tábořil kolem něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'David promluvil a zeptal se Chetejce Achímeleka a Abíšaje, syna Serújina, bratra Jóabova: Kdo se mnou sestoupí k Saulovi do tábora? Abíšaj řekl: Já s tebou sestoupím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'David s Abíšajem přišel v noci k lidu a hle, Saul ležel a spal v ležení a jeho kopí bylo zabodnuté v zemi u hlavy. Abnér a lid ležel kolem něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Abíšaj řekl Davidovi: Bůh dnes vydal tvého nepřítele do tvé ruky. Dovol, ať ho teď jednou ranou přibodnu kopím k zemi, ⌈druhou nebudu potřebovat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'David řekl Abíšajovi: Nezabíjej ho! Vždyť kdo může vztáhnout ruku na Hospodinova pomazaného a zůstat bez trestu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'David řekl: Jakože živ je Hospodin, jistě jej postihne Hospodin nebo přijde jeho den a zemře nebo vyjde do boje a bude smeten.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Ať je to ode mě vzdáleno kvůli Hospodinu, abych vztáhl ruku na Hospodinova pomazaného. Teď vezmi kopí, které je u jeho hlavy, a džbánek na vodu a pojďme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Nato vzal David kopí a džbánek na vodu od Saulovy hlavy a odešli. Nikdo je neviděl, nikdo se to nedozvěděl, nikdo se neprobudil, protože všichni spali, neboť na ně padl hluboký spánek od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Pak David přešel na protilehlou stranu a postavil se vpovzdálí na vrcholku hory, takže mezi nimi ⌈ byla velká vzdálenost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'David zavolal na lid a na Abnéra, syna Nérova: Odpověz, Abnére! Abnér odpověděl: Kdo jsi, že pokřikuješ na krále?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'David řekl Abnérovi: ⌈Jsi přece muž a nikdo není ⌉ v Izraeli jako ty. Proč jsi nestřežil svého pána a krále? ⌈Někdo z lidu⌉ přišel, aby zabil krále, tvého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'To ne ní dobré, co jsi učinil. Jakože je živ Hospodin, ⌈jste syny smrti,⌉ protože jste nestřežili svého pána, Hospodinova pomazaného. Podívej se teď, kde je královo kopí a džbánek na vodu, které byly u jeho hlavy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Když rozpoznal Saul Davidův hlas, řekl: Je to tvůj hlas, můj synu Davide? David odpověděl: Je to můj hlas, můj pane a králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Dále řekl: Proč můj pán pronásleduje svého otroka? Co jsem udělal? Jaké zlo je při mně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Nyní ať vyslechne můj pán a král slova svého otroka: Jestliže tě proti mně podněcuje Hospodin, ať přijme přídavnou oběť. Jestliže však lidé, ať jsou prokletí před Hospodinem, neboť mě dnes vyhnali, abych neměl podíl na Hospodinově dědictví, se slovy: Jdi sloužit jiným bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'A nyní ať nepadne má krev na zem ⌈pryč z Hospodinovy přítomnosti.⌉ Vždyť izraelský král vytáhl, aby hledal jednu blechu, jako se honí koroptev v horách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Nato Saul řekl: Zhřešil jsem. Vrať se, můj synu Davide. Neudělám ti již nic zlého, za to, že sis dnes ⌈vážil mého života.⌉ Ano, jednal jsem bláznivě a převelice jsem zbloudil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David odpověděl: Zde je ⌈královo kopí.⌉ Ať přijde někdo ze služebníků a vezme si ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Ať Hospodin odplatí každému za jeho spravedlnost a věrnost. Když tě dnes Hospodin vydal do mé ruky, nechtěl jsem vztáhnout ruku na Hospodinova pomazaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Zrovna tak jako ⌈jsem si dnes cenil tvého života,⌉ tak ať ⌈si cení Hospodin mého života⌉ a vysvobodí mě ze všeho soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul řekl Davidovi: Požehnaný jsi, můj synu Davide. ⌈Jistě to vykonáš a opravdu to dokážeš.⌉ David pak šel svou cestou a Saul se vrátil na své místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'David si pomyslel: ⌈Kteréhokoli dne mohu být smeten⌉ Saulovou rukou. ⌈Nejlepší by pro mě bylo, kdybych unikl⌉ do ⌈pelištejské země.⌉ Saul pak ⌈upustí od toho,⌉ aby mě znovu hledal po celém izraelském území; tak uniknu z jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Nato David vstal a šel se šesti sty muži, kteří byli s ním, k Akíšovi, synu Maókovu, králi Gatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Potom David pobýval u Akíše v Gatu, on i jeho muži, každý se svou rodinou, David se svými dvěma ženami, Achínoamou Jizreelskou a Abígajilou Karmelskou, dříve ženou Nábalovou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Když bylo oznámeno Saulovi, že David utekl do Gatu, již ho dále nehledal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'David řekl Akíšovi: Jestliže jsem našel nyní milost ve tvých očích, ať mi dají místo v některém z venkovských měst, abych se tam usadil. Proč by měl tvůj otrok bydlet s tebou v královském městě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Akíš mu dal v onen den Siklag. Proto patří Siklag judským králům dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, '⌈Doba, po kterou⌉ David pobýval na pelištejském území, byla ⌈ jeden rok⌉ a čtyři měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'David se svými muži vyrážel a napadal Gešúrejce, Girzejce a Amálekovce -- ti pobývali v zemi, kterou se od věků chodí do Šúru a až do egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Když David vybíjel zemi, nenechával při životě muže ani ženu, ale bral ovce, skot, osly, velbloudy i oděvy. Pak se vracel a přicházel k Akíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Když se Akíš ptal: Kam jste dnes vtrhli?, David odpovídal: Do Negebu Judova či do Negebu Jerachmeelců či do Negebu Kénijců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'David nenechával při životě muže ani ženu, a ne vodil je do Gatu. Říkal si: Jinak by nás udali slovy: Toto páchá David. To ⌈ bylo jeho zvykem⌉ po ⌈celou dobu,⌉ kdy pobýval na pelištejském území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Akíš Davidovi věřil. Říkal si: Jistě se zošklivil svému lidu, Izraelcům, a bude navěky ⌈mým otrokem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Stalo se v oněch dnech, že Pelištejci shromáždili svá vojska v armádu, aby bojovali proti Izraeli. Akíš Davidovi řekl: Jistě víš, že se mnou vytáhneš ve vojsku, ty i tvoji muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David Akíšovi odpověděl: Poznáš tedy, ⌈co dokáže⌉ tvůj otrok. Nato Akíš Davidovi řekl: Ustanovím tě tedy za svou ⌈tělesnou stráž⌉ ⌈ po všechny dny.⌉ –');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Když Samuel zemřel, celý Izrael ho oplakával. Pohřbili ho v Rámě, v jeho městě. Saul odstranil ze země ⌈ ty, kdo vyvolávají duchy zemřelých,⌉ a věštce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Pelištejci se shromáždili, vytáhli a utábořili se v Šúnemu. Saul shromáždil celý Izrael a utábořili se v Gilbóa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Když Saul uviděl pelištejské vojsko, bál se a celý se třásl strachy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Saul se doptával Hospodina, ale Hospodin mu neodpověděl ani skrze sny ani skrze urím ani skrze proroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Proto Saul řekl svým otrokům: Vyhledejte mi ženu, ⌈která vyvolává duchy⌉ zemřelých, abych mohl jít k ní a dotázat se jí. Jeho otroci mu řekli: Ano, žena, která vyvolává duchy zemřelých, je v Én–dóru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Saul se přestrojil a oblékl si jiné šaty. Pak se vydal na cestu spolu s dvěma muži a přišli v noci k té ženě. Řekl: Věšti mi skrze ducha zemřelého a vyvolej mi, koho ti řeknu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Žena mu řekla: Podívej, ty víš, co udělal Saul, jak vyhladil ze země ty, kdo vyvolávají duchy zemřelých, a věštce. Proč ⌈mě chceš chytit do pasti a usmrtit mě?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Saul jí přísahal při Hospodinu: Jakože živ je Hospodin, nepostihne tě za to trest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Nato se žena zeptala: Koho ti mám vyvolat? Odpověděl: Vyvolej mi Samuela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Když žena uviděla Samuela, hlasitě vykřikla. Pak řekla Saulovi: Proč jsi mě podvedl? Ty jsi Saul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Král jí řekl: Neboj se. Co vidíš? Žena řekla Saulovi: Vidím ⌈ bytost podobnou bohu⌉ vystupující ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Zeptal se jí: ⌈Jak vypadá?⌉ Odpověděla: Vystupuje starý muž, zahalený pláštěm. Když Saul poznal, že je to Samuel, poklekl s tváří k zemi a klaněl se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Samuel se zeptal Saula: Proč mě znepokojuješ a necháváš mě vyvolat? Saul odpověděl: ⌈Jsem ve veliké tísni.⌉ Bojují proti mně Pelištejci a Bůh ode mě odstoupil. Neodpovídá mi už ani prostřednictvím proroků ani skrze sny. Proto jsem tě zavolal, abys mi oznámil, co mám dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel řekl: Proč se mě ptáš, když Hospodin od tebe odstoupil a stal se tvým protivníkem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Hospodin učinil tak, jak promluvil mým prostřednictvím: Hospodin odtrhl království ⌈od tebe⌉ a dal ho tvému bližnímu, Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Protože jsi neuposlechl Hospodina a nevykonal jeho planoucí hněv nad Amálekovci, proto ti dnes Hospodin učinil toto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Také Izrael vydá Hospodin spolu s tebou do ruky Pelištejců. Zítra budeš ty i tvoji synové u mne. Také izraelské vojsko vydá Hospodin do ruky Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Saul ihned padl celou svou výškou k zemi; hrozně se bál ⌈Samuelových slov.⌉ ⌈Vůbec neměl sílu,⌉ protože celý den a celou noc nejedl pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Potom přišla k Saulovi ta žena, a když viděla, jak moc se děsí, řekla mu: Podívej, tvá služka tě uposlechla. ⌈Vystavila jsem svůj život nebezpečí⌉ a poslechla jsem slova, která jsi ke mně promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Nyní také ty uposlechni svou služku. ⌈Nachystám ti něco k jídlu.⌉ Pojez, ⌈posilni se a jdi⌉ svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'On odmítl a řekl: Nebudu jíst. Ale jeho otroci i ta žena ho nutili, takže je uposlechl. Vstal ze země a posadil se na postel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Žena měla doma ⌈vykrmené tele.⌉ Rychle ho zabila, vzala mouku, uhnětla a napekla z toho nekvašené chleby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Přinesla to ⌈Saulovi a jeho otrokům⌉ a ti se najedli. Pak vstali a té noci odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Pelištejci shromáždili všechna svá vojska do Afeku, kdežto Izraelci tábořili u pramene, který je v Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Pelištejská knížata pochodovala po stech a po tisících a na konci pochodoval David a jeho muži s Akíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Pelištejská knížata řekla: Co tihle Hebrejové? Akíš pelištejským knížatům odpověděl: To je přece David, otrok izraelského krále Saula, který byl ⌈se mnou⌉ rok či dva a neshledal jsem na něm nic zlého ode dne, kdy přeběhl, až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Ale pelištejská knížata se na něj rozhněvala a řekla mu: Pošli toho muže zpět, ať se vrátí na své místo, které jsi mu určil. Ať s námi netáhne do boje a nestane se naším protivníkem v boji. Jak by se mohl zalíbit svému pánu? Cožpak ne hlavami těchto mužů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Což to není David, o kterém zpívali při tancích: Saul pobil své tisíce, ale David své desetitisíce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Akíš zavolal Davida a řekl mu: Jakože živ je Hospodin, jsi přímý a líbilo by se mi, abys se mnou táhl ve vojsku. Neshledal jsem na tobě nic zlého ode dne, kdy jsi přišel ke mně, až dodnes. ⌈Nelíbíš se ale knížatům.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Proto se nyní vrať a ⌈jdi v pokoji.⌉ Nečiň to, co ⌈se nelíbí pelištejským knížatům.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David řekl Akíšovi: Co jsem ale udělal? Co jsi shledal na svém otroku ode dne, kdy jsem k tobě přišel, až dodnes, že ne mohu jít a bojovat proti nepřátelům svého pána a krále?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Akíš Davidovi odpověděl: Uznávám, že se mi líbíš jako posel Boží. Jenže pelištejská knížata řekla: Ať s námi netáhne do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Nuže, časně zrána vstaň, i otroci mého pána, kteří přišli s tebou. Vstaňte časně zrána, a jak se rozjasní, jděte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'David se svými muži časně vstal, aby zrána šli a vrátili se do ⌈pelištejské země.⌉ Ale Pelištejci táhli do Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Stalo se, že když David se svými muži přišel třetího dne do Siklagu, Amálekovci vtrhli do Negebu a do Siklagu. Přepadli Siklag a spálili ho ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Zajali ženy ⌈ a ty, kdo v něm byli, od nejmenšího do největšího.⌉ Nikoho neusmrtili, ale odvedli je a šli svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Když přišel David se svými muži k městu, uviděli, že je spáleno ohněm a jejich ženy, synové i dcery jsou vzati do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'David a lid, který byl s ním, ⌈pozvedl svůj hlas a plakali,⌉ až už neměli sílu plakat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Do zajetí byly vzaty i obě Davidovy ženy, Achínoam Jizreelská a Abígajil Karmelská, dříve žena Nábalova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Davidovi bylo velmi úzko, protože lid řekl, že ho ukamenují. Všemu lidu bylo totiž hořko v duši, každému kvůli svým synům a dcerám. Ale David se posilnil v Hospodinu, svém Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Pak řekl David knězi Ebjátarovi, synu Achímelekovu: Přines mi efód. Ebjátar přinesl Davidovi efód.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'David se doptával Hospodina: Mám pronásledovat tu loupežnou hordu? Dostihnu ji? Odpověděl mu: Pronásleduj, jistě ji dostihneš a jistě je vysvobodíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'David šel se šesti sty muži, kteří byli s ním, a přišli až k potoku Besór. Tam zůstali ⌈ti, kdo pozaostávali.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'David se čtyřmi sty muži pokračoval v pronásledování, ale dvě stě mužů, kteří byli příliš vyčerpaní, než aby mohli přejít potok Besór, tam zůstalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Na poli našli nějakého Egypťana a vzali ho k Davidovi. Dali mu pokrm, aby pojedl, a dali mu napít vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Dali mu koláč z lisovaných fíků a dva sušené hrozny. Pojedl a ožil, neboť ⌈tři dny a tři noci⌉ nejedl pokrm a nepil vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'David se ho zeptal: ⌈Čí jsi⌉ a odkud jsi? On ⌈odpověděl: Jsem egyptský služebník,⌉ otrok jednoho Amálekovce. Můj pán mě opustil, ⌈protože jsem před třemi dny onemocněl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Vtrhli jsme do Negebu Keretejců, do oblasti, která patří Judovi, a do Negebu Kálebova. Siklag jsme spálili ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David se ho zeptal: Zavedeš mě k té loupežné hordě. On odpověděl: Přísahej mi při Bohu, že mě neusmrtíš ani nevydáš do ruky mého pána, a zavedu tě k té loupežné hordě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Pak ho k nim zavedl, a hle, byli rozloženi všude po zemi, jedli, pili a slavili svátek nad vší tou velkou kořistí, kterou ⌈pobrali v⌉ pelištejské a judské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'David je pobíjel od soumraku až do večera druhého dne. Nikdo z nich neunikl, kromě čtyř set mládenců, kteří ⌈nasedli na velbloudy⌉ a utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'David vysvobodil všechno, co Amálekovci pobrali. Také obě své ženy David vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Nechybělo jim nic od nejmenšího do největšího, synové ani dcery, kořist a nic, co jim pobrali; David všechno přivedl zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'David pobral i všechen brav a skot. Hnali ten dobytek před sebou a říkali: To je Davidova kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'David přišel ke dvěma stům mužům, kteří byli příliš vyčerpaní, než aby mohli jít s Davidem, takže je nechali u potoka Besór. Ti vyšli Davidovi a lidu, který byl s ním, naproti. David přistoupil k lidu a zeptal se, jak se jim daří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Promluvili však všichni zlí muži a ničemníci mezi těmi, kdo táhli s Davidem, a říkali: Protože s námi netáhli, nedáme jim nic z kořisti, kterou jsme vysvobodili. Každý ať si odvede pouze svou ženu a své syny a ať jdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'David řekl: Nedělejte to, ⌈moji bratři, s tím,⌉ co nám dal Hospodin. Chránil nás a vydal do naší ruky loupežnou hordu, která vytáhla proti nám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Kdo vás v této věci uposlechne? Ať je podíl toho, kdo vytáhl do boje, stejný jako podíl toho, kdo zůstal u výstroje; ať se spolu rozdělí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'A bývalo tak od onoho dne i nadále; určil to za ustanovení a nařízení v Izraeli až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Když přišel David do Siklagu, poslal část z kořisti judským starším, svým přátelům, se slovy: Zde máte dar z kořisti Hospodinových nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Těm, kteří byli v Bét–elu, těm, kteří byli v Rámotu v Negebu, těm, kteří byli v Jatiru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'těm, kteří byli v Aróeru, těm, kteří byli v Sifmótu, těm, kteří byli v Eštemóe,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'těm, kteří byli v Rákalu, těm, kteří byli ve městech Jerachmeelců, těm, kteří byli ve městech Kénijců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'těm, kteří byli v Chormě, těm, kteří byli v Bór–ašanu, těm, kteří byli v Ataku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'těm, kteří byli v Chebrónu a na všech místech, kam chodíval David se svými muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Pelištejci bojovali proti Izraeli. Izraelci před Pelištejci utíkali a padali pobiti v pohoří Gilbóa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Pelištejci stíhali Saula a jeho syny. Pak zabili Pelištejci Jónatana, Abínádaba a Malkíšúu, Saulovy syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Bitva těžce dolehla na Saula. Našli ho lukostřelci a on ⌈se před luko střelci hrozně třásl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Saul řekl svému zbrojnoši: Vytáhni svůj meč a probodni mě s ním. Jinak přijdou ti neobřezanci, probodnou mě a budou se mi posmívat. Zbrojnoš ale nechtěl, protože se hrozně bál. Saul tedy vzal meč a padl na něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Když zbrojnoš viděl, že Saul je mrtev, také on padl na svůj meč a zemřel s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Tak zemřel Saul, jeho tři synové i jeho zbrojnoš a také všichni jeho muži společně v onen den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Když Izraelci, kteří byli na druhé straně údolí a za Jordánem, viděli, že Izraelci utekli a že Saul a jeho synové jsou mrtvi, opustili města a utekli. Pak přišli Pelištejci a usadili se v nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Příštího dne se stalo, že přišli Pelištejci, aby rabovali pobité. Našli Saula a jeho tři syny padlé v pohoří Gilbóa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Usekli mu hlavu, svlékli mu zbroj a poslali kolovat po pelištejské zemi a přinášet novinu v domě jejich modlářských zpodobenin i lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Pak jeho zbroj uložili v domě Aštarty a jeho tělo připevnili na hradby Bét–šanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Když o tom, co Pelištejci provedli Saulovi, uslyšeli obyvatelé Jábeše v Gileádu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'všichni bojovníci povstali, šli celou noc, vzali tělo Saula i těla jeho synů z hradeb Bét–šanu, a když přišli do Jábeše, spálili je tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Potom vzali jejich kosti, pohřbili je v Jábeši pod tamaryškem a postili se sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'I stalo se po Saulově smrti, když se David vrátil z ⌈boje proti Amálekovcům,⌉ že David zůstal dva dny v Siklagu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Třetího dne se stalo, že přišel kdosi ⌈ze Saulova vojska,⌉ měl roztržené roucho a na hlavě prsť. Když přišel k Davidovi, padl k zemi a poklonil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'David se ho zeptal: Odkud jdeš? Odpověděl mu: Unikl jsem z izraelského vojska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David se ho zeptal: Co se stalo? Pověz mi to. Řekl mu, že lid utekl z boje, mnozí z lidu padli a zemřeli a také Saul a jeho syn Jónatan jsou mrtvi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Nato se David zeptal mládence, který mu to oznámil: Jak víš, že Saul a jeho syn Jónatan jsou mrtvi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Mládenec, který mu to oznámil, odpověděl: Ocitl jsem se náhodou v pohoří Gilbóa, a hle, Saul se opíral o své kopí a vozba a jezdci ho stíhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Obrátil se, uviděl mě a zavolal na mě. Řekl jsem: Tady jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Zeptal se mě: Kdo jsi? Odpověděl jsem mu: Jsem Amálekovec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Řekl mi: Postav se nade mnou a usmrť mě, neboť mě postihla křeč, ale ještě je ve mně život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Postavil jsem se nad ním a usmrtil jsem ho, neboť jsem věděl, že již nebude žít poté, co padl. Potom jsem vzal korunu, která byla na jeho hlavě, a náramek, který měl na paži, a přinesl jsem je sem svému pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Nato David uchopil své roucho a roztrhl ho, stejně tak i všichni muži, kteří byli s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Bědovali, plakali a postili se až do večera kvůli Saulovi a jeho synu Jónatanovi, kvůli Hospodinovu lidu a kvůli domu izraelskému, že padli mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Mládence, který mu to oznámil, se David zeptal: Odkud jsi? Odpověděl: Jsem synem cizince, Amálekovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'David mu řekl: Jak to, že ses nebál vztáhnout ruku a zabít Hospodinova pomazaného?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Pak David zavolal jednoho ze služebníků a řekl: Přistup a ⌈zasáhni proti němu.⌉ On ho tedy bil, až zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'David mu řekl: Tvoje krev na tvou hlavu, neboť tvá ústa svědčí proti tobě, když jsi řekl: Já jsem usmrtil Hospodinova pomazaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'David zazpíval nad Saulem a jeho synem Jónatanem tento žalozpěv');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'a řekl, aby se Judejci učili Píseň o luku; ano, je zapsána v knize Jašarově:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Nádhera Izraele je pobita na tvých návrších; jak to, že padli hrdinové?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Neoznamujte to v Gatu, nezvěstujte na ulicích Aškalónu, jinak se budou radovat pelištejské dcery, jinak budou jásat dcery neobřezanců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Hory Gilbóa, ať na vás ne ní rosa ani déšť ani ⌈pole přinášející dávky,⌉ neboť tam byl zneuctěn štít hrdinů, štít Saulův leží nepomazán olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Bez krve pobitých, bez tuku hrdinů Jónatanův luk neustoupil zpět, Saulův meč nevracel se zpět s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul a Jónatan, milovaní a ⌈milí ve svém životě, ani ve své smrti⌉ nebyli rozděleni. Byli rychlejší nežli orlové, silnější nežli lvi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Dcery izraelské, plačte nad Saulem, který vás oblékal do karmínu ⌈a skvostu,⌉ jenž kladl zlaté ozdoby na váš oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Jak to, že padli hrdinové uprostřed boje, Jónatan leží pobit na tvých návrších?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, '⌈ Je mi úzko⌉ kvůli tobě, můj bratře Jónatane, byl jsi mi velmi milý. Tvá láska byla pro mě podivuhodnější nežli láska žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Jak to, že padli hrdinové, přišly vniveč válečné zbraně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'I stalo se potom, že se David doptával Hospodina: Mám jít do některého z judských měst? Hospodin mu odpověděl: Jdi. David se zeptal: Kam mám jít? Odpověděl: Do Chebrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'David tam šel a s ním také jeho dvě ženy, Achínoam Jizreelská a Abígajil Karmelská, dříve žena Nábalova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Muže, kteří byli s ním, vzal David také s sebou, každého s jeho rodinou, a usadili se v chebrónských městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Judští muži přišli a pomazali tam Davida za krále nad domem judským. Potom Davidovi oznámili, že muži z Jábeše v Gileádu pohřbili Saula.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Nato poslal David k mužům v Jábeši v Gileádu posly a řekl jim: Jste požehnaní Hospodinu, že jste prokázali svému pánu Saulovi toto milosrdenství a pohřbili ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Ať nyní Hospodin prokáže milosrdenství a věrnost vám a také já ⌈vám budu prokazovat⌉ dobro, že jste to učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Nyní posilněte své ruce a buďte udatní, protože váš pán Saul je mrtev, avšak mě dům judský pomazal za krále nad sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Ovšem Abnér, syn Nérův, velitel Saulovy armády, vzal Íš–bóšeta, syna Saulova, a přivedl ho do Machanajimu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Ustanovil ho králem nad Gileádem, nad Ašúrci, nad Jizreelem, nad Efrajimem, nad Benjamínem a nad celým Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Íš–bóšetovi, synu Saulovu, bylo čtyřicet let, když se stal králem nad Izraelem, a kraloval dva roky. Jenom dům judský byl za Davidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Doba, po kterou byl David králem v Chebrónu nad domem judským, byla sedm let a šest měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Abnér, syn Nérův, a otroci Íš–bóšeta, syna Saulova, vytáhli z Machanajimu do Gibeónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Také Jóab, syn Serújin, a Davidovi otroci vytáhli; setkali se u Gibeónského rybníka. Jedni zůstali na jedné straně rybníka, druzí na druhé straně rybníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Abnér řekl Jóabovi: Ať povstanou mládenci a utkají se před námi. Jóab odpověděl: Ať povstanou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Povstali tedy a předstoupili v počtu dvanáct za Benjamínce a Íš–bóšeta, syna Saulova, a dvanáct z Davidových otroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Jeden druhého uchopil za hlavu a vrazil mu meč do boku, takže padli zároveň. Proto se toto místo, které je v Gibeónu, nazývá Chelkat–súrím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Onoho dne došlo k velice tvrdému boji a Abnér s izraelskými muži byl od Davidových otroků poražen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Byli tam tři Serújini synové: Jóab, Abíšaj a Asáel. Asáel měl nohy rychlé jako ⌈nějaká gazela⌉ na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Asáel pronásledoval Abnéra a neuhnul přitom od Abnéra napravo ani nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abnér se za ním obrátil a zeptal se: To jsi ty, Asáeli? Odpověděl: Ano, já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abnér mu řekl: Uhni napravo nebo nalevo, chyť si ⌈jednoho z mládenců⌉ a vezmi si z ⌈něho kořist.⌉ Asáel však nechtěl od něj odbočit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abnér Asáelovi znovu pověděl: Odboč ode mě. Proč bych tě měl srazit k zemi? Jak bych se pak mohl ⌈ukázat před tvým⌉ bratrem Jóabem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Ale on nechtěl odbočit, a tak mu Abnér vrazil tupý konec kopí do břicha, takže ⌈jím kopí proniklo.⌉ Padl tam a namístě zemřel. I stalo se, že všichni, kdo přicházeli na místo, kde Asáel padl a zemřel, se zastavili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Ale Jóab a Abíšaj Abnéra pronásledovali. Když zapadalo slunce, dostali se na kopec Amá, který je u Gíachu, směrem ke Gibeónské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Synové Benjamínovi se shromáždili k Abnérovi, utvořili jeden oddíl a stáli na vrchu kopce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Abnér zavolal na Jóaba: Cožpak bude meč stále požírat? Což nevíš, že ⌈na konci bude hořkost?⌉ ⌈Kdy už řekneš lidu, aby přestal pronásledovat své bratry?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Jóab odpověděl: Jakože živ je Bůh, kdybys nepromluvil, až teprve ráno by lid ⌈přestal pronásledovat svého bratra.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Potom zatroubil Jóab na beraní roh, všechen lid se zastavil a už Izraelce nepronásledovali; dál již nebojovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abnér a jeho muži šli celou tu noc Arabou, přešli Jordán, ⌈prošli celý Bitrón⌉ a přišli do Machanajimu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Když se Jóab vrátil z pronásledování Abnéra, shromáždil všechen lid a pohřešoval z Davidových otroků devatenáct mužů a Asáela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Davidovi otroci pobili tři sta šedesát Benjamínců a Abnérových mužů, kteří zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Asáela odnesli a pohřbili ho v hrobě jeho otce, který je v Betlémě. Pak šli Jóab a jeho muži celou noc a ⌈ za úsvitu byli⌉ v Chebrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Boj mezi domem Saulovým a domem Davidovým trval dlouho. David se stále vzmáhal, kdežto dům Saulův stále slábl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Davidovi se v Chebrónu narodili synové: Jeho prvorozený byl Amnón s Achínoamou Jizreelskou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'jeho druhý syn byl Kileab s Abígajilou Karmelskou, dříve ženou Nábalovou, třetí byl Abšalóm, syn Maaky, dcery gešúrského krále Talmaje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'čtvrtý byl Adónijáš, syn Chagíty, pátý Šefatjáš, syn Abítaly,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'šestý Jitreám s Eglou, Davidovou ženou. Ti se narodili Davidovi v Chebrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Zatímco trval boj mezi domem Saulovým a domem Davidovým, Abnér ⌈se v domě Saulově vzmáhal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Saul měl konkubínu jménem Rispa, dceru Ajovu. Íš–bóšet řekl Abnérovi: Proč jsi vešel ke konkubíně mého otce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Abnér se kvůli Íš–bóšetovým slovům velice rozzlobil a řekl: Copak jsem ⌈psí hlava⌉ z Judska? Do dnes ⌈jednám věrně⌉ s domem Saula, tvého otce, vůči jeho bratrům i vůči jeho příteli a nevydal jsem tě do ruky Davida. A ty jsi mě dnes obvinil kvůli ženě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Tak ať Bůh učiní Abnérovi a ještě přidá, ⌈jestliže ne učiním Davidovi tak, jak mu přísahal Hospodin:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Odejmu království od domu Saulova a ustanovím Davidův trůn nad Izraelem a nad Judou, od Danu až po Beer–šebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Íš–bóšet již nedokázal Abnérovi ⌈nic odpovědět,⌉ ⌈protože se ho bál.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Abnér poslal k Davidovi místo sebe posly se slovy: Komu patří země? Uzavři se mnou smlouvu. Ano, má ruka bude s tebou, aby se k tobě obrátil celý Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Odpověděl: Dobře, uzavřu s tebou smlouvu. Ovšem jednu věc od tebe žádám: Neuvidíš mě, dokud nepřivedeš Míkal, Saulovu dceru, až přijdeš, abys mě viděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'David poslal posly k Íš–bóšetovi, synu Saulovu, se slovy: Dej mi mou ženu Míkal, kterou jsem si zasnoubil za sto pelištejských předkožek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Íš–bóšet pro ni poslal a vzal ji od muže, od Paltíela, syna Lajišova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Její muž šel s ní a stále za ní plakal až do Bachurímu. Abnér mu řekl: Jdi a vrať se. A tak se vrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, '⌈Abnér promluvil k⌉ izraelským starším: Již dříve předtím jste chtěli mít Davida za krále nad sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Nyní jednejte, neboť Hospodin řekl o Davidovi: Rukou svého otroka Davida zachráním svůj lid Izrael z ruky Pelištejců a z ruky všech jeho nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abnér promluvil také ⌈k Benjamíncům.⌉ Pak šel Abnér říct také Davidovi do Chebrónu vše, ⌈co bylo dobré v očích Izraele⌉ a v očích celého domu Benjamínova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Když přišel Abnér k Davidovi do Chebrónu, bylo s ním dvacet mužů. David uspořádal Abnérovi a mužům, kteří byli s ním, hostinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Abnér Davidovi řekl: Povstanu, půjdu a shromáždím k svému pánu a králi celý Izrael, aby s tebou uzavřeli smlouvu. Tak budeš kralovat nade vším, po čem toužíš. David pak Abnéra propustil a ten v pokoji odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'A hle, Davidovi otroci a Jóab přišli z loupežné výpravy a přinesli s sebou velkou kořist. Abnér již nebyl u Davida v Chebrónu, protože David ho propustil a on v pokoji odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Když Jóab a celá armáda, která byla s ním, přišli, Jóabovi ⌈bylo oznámeno:⌉ Ke králi přišel Abnér, syn Nérův. On ho propustil a ten v pokoji odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Nato vešel Jóab ke králi a řekl: Co jsi to udělal? Podívej, Abnér přišel k tobě -- proč jsi ho propustil, aby jen tak odešel?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Znáš přece Abnéra, syna Nérova. Přišel, aby tě podvedl, aby ⌈poznal tvé vycházení a vcházení,⌉ aby poznal všechno, co děláš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Když Jóab odešel od Davida, poslal za Abnérem posla, aby ho přivedli zpět od cisterny v Siře. Ale David o tom nevěděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Když se Abnér vrátil do Chebrónu, vtáhl ho Jóab do brány, aby s ním v soukromí promluvil. Udeřil ho tam do břicha, takže zemřel za prolitou krev jeho bratra Asáela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Když se o tom David později doslechl, řekl: Já i mé království jsme před Hospodinem navěky nevinni prolitou krví Abnéra, syna Nérova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Ať dopadne na hlavu Jóaba a na celý dům jeho otce. Ať není z domu Jóabova odňat trpící výtokem ani postižený malomocenstvím ani ⌈ muž, který uchopuje vřeteno,⌉ ani ten, kdo padá mečem, ani ten, kdo nemá pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Jóab a jeho bratr Abíšaj zabili Abnéra kvůli tomu, že v Gibeónu usmrtil v boji jejich bratra Asáela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'David řekl Jóabovi a všemu lidu, který byl s ním: Roztrhněte svá roucha, přepásejte se pytlovinou a bědujte v průvodu před Abnérem. Král David šel za márami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Tak pohřbili Abnéra v Chebrónu. Král ⌈pozvedl svůj hlas a plakal⌉ ⌈u Abnérova hrobu,⌉ a také všechen lid plakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Král zazpíval nad Abnérem žalozpěv: Což měl Abnér zemřít, jako umírá blázen?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Tvé ruce nebyly spoutány, tvé nohy nebyly dány do bronzových okovů; padl jsi, jako člověk padá ⌈rukou bídáků.⌉ A všechen lid nad ním dále plakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Všechen lid se snažil přimět Davida, aby během dne pojedl chléb, ale David přísahal: Tak ať mi učiní Bůh, a ještě přidá, jestliže před západem slunce okusím chléb či cokoliv jiného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Všechen lid to zpozoroval a ⌈líbilo se mu to.⌉ Všechno, co král dělal, se všemu lidu líbilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Onoho dne všechen lid a celý Izrael poznal, že od krále ⌈nevzešel úmysl ⌉ usmrtit Abnéra, syna Nérova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Král řekl svým otrokům: ⌈Což nevíte,⌉ že dnes padl v Izraeli velitel, a to velký?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Já jsem dnes slabý, ačkoliv pomazán za krále. A tito muži, synové Serújini, jsou ⌈tvrdší nežli já.⌉ Ať Hospodin odplatí ⌈tomu, kdo páchá zlo, podle jeho zla.⌉ –');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Když se Íš–bóšet, syn Saulův, doslechl, že Abnér v Chebrónu zemřel, jeho ruce ochably a celý Izrael se vyděsil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Saulův syn měl dva muže, velitele loupežných hord. Jeden se jmenoval Baana, druhý Rekáb, syn Rimóna Beerótského, ze synů Benjamínových. Beerót se totiž také počítá k Benjamínovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Beerótští utekli do Gitajimu a pobývají tam jako cizinci až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Jónatan, syn Saulův, měl syna chromého na nohy. Bylo mu pět let, když přišla z Jizreelu zpráva o Saulovi a Jónatanovi. Jeho vychovatelka ho vzala a utíkala. I stalo se, že jak při útěku pospíchala, spadl a zchroml. Jmenoval se Mefíbóšet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Synové Rimóna Beerótského, Rekáb a Baana, šli a za denního žáru vešli do Íš–bóšetova domu. Ten ⌈ležel za poledne na posteli.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Vešli dovnitř do domu, jako by si přišli vzít pšenici, a udeřili ho do břicha. Nato Rekáb a jeho bratr Baana unikli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Když vešli do domu, ležel na své posteli v ložnici. Bili ho, až ho usmrtili, a srazili mu hlavu. Pak jeho hlavu vzali a šli celou noc Arabou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Přinesli Íš–bóšetovu hlavu Davidovi do Chebrónu a řekli králi: Zde je hlava Íš–bóšeta, syna Saula, tvého nepřítele, který ⌈usiloval o tvůj život.⌉ Hospodin dal dnes mému pánu a králi pomstu nad Saulem a jeho potomstvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'David promluvil k Rekábovi a jeho bratru Baanovi, synovi Rimóna Beerótského, a řekl jim: Jakože živ je Hospodin, který vykoupil mou duši z každého soužení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'toho, kdo mi oznámil: Hle, Saul je mrtev! a který si připadal jako nositel dobré zprávy, toho jsem chytil a zabil ho v Siklagu; to jsem mu dal za jeho zprávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Tím spíše, když ⌈ničemní lidé⌉ zabili spravedlivého muže v jeho vlastním domě na jeho posteli, ⌈budu z vaší ruky teď požadovat odpovědnost za jeho krev⌉ a vyhladím vás ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'David dal služebníkům příkaz, aby je zabili; usekli jim ruce i nohy a pověsili je u rybníka v Chebrónu. Íš–bóšetovu hlavu vzali a pohřbili do Abnérova hrobu v Chebrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Všechny izraelské kmeny přišly k Davidovi do Chebrónu a řekly: Hle, jsme tvá kost a tvé tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Již dávno předtím, když byl králem nad námi ještě Saul, ty ⌈jsi vodil Izrael do boje i z boje.⌉ Hospodin ti řekl: Ty budeš pást můj lid Izrael, ty budeš vévodou nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Všichni izraelští starší přišli ke králi do Chebrónu a král David s nimi uzavřel před Hospodinem smlouvu. Pak pomazali Davida za krále nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Davidovi bylo třicet let, když se stal králem, a kraloval čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'V Chebrónu kraloval nad Judou sedm let a šest měsíců, v Jeruzalémě kraloval třicet tři let nad celým Izraelem i Judou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Král se svými muži vytáhl na Jeruzalém proti Jebúsejcům, obyvatelům té země. Ti řekli Davidovi: Nechoď sem, nebo tě odvrátí slepí a chromí se slovy: David sem nevstoupí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Ale David dobyl pevnost Sijón, to je ⌈Město Davidovo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'V onen den David řekl: Každý, kdo chce pobíjet Jebúsejce, ty chromé, slepé, ty, ⌈kdo nenávidí Davidovu duši,⌉ ať udeří skrze vodní kanál. Proto se říká: Slepí a chromí nevejdou do domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'David se usadil v pevnosti a nazval ji Město Davidovo. David ji vystavěl okolo, od Miló až dovnitř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'David táhl dál a stále se rozmáhal a Hospodin, Bůh zástupů, byl s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Týrský král Chíram poslal k Davidovi posly a cedrové dřevo, tesaře, kameníky, aby postavili Davidovi palác.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'David věděl, že Hospodin ho určil za krále nad Izraelem a že povznesl jeho království kvůli svému lidu Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Poté, co přišel David z Chebrónu, vzal si v Jeruzalémě další konkubíny a ženy a Davidovi se narodili další synové a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Toto jsou jména těch, kteří se mu narodili v Jeruzalémě: Šamúa, Šóbab, Nátan, Šalomoun,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibchár, Elíšúa, Nefeg, Jafía,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elíšama, Eljáda a Elífelet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Když se Pelištejci doslechli, že Davida pomazali za krále nad Izraelem, vytáhli všichni Pelištejci Davida hledat. Když se to David doslechl, sestoupil do pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Pelištejci přitáhli a rozložili se v údolí Refájců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'David se doptával Hospodina: Mám vytáhnout proti Pelištejcům? Vydáš je do mé ruky? Hospodin Davidovi odpověděl: Vytáhni, neboť jistě vydám Pelištejce do tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'David přišel do Baal–perasímu a pobil je tam. Řekl: Hospodin protrhl mé nepřátele přede mnou, jako ⌈voda protrhuje hráz.⌉ Proto pojmenoval to místo Baal–perasím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Zanechali tam své modlářské zpodobeniny a David se svými muži je odnesli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Pelištejci znovu vytáhli a rozložili se v údolí Refájců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'David se doptával Hospodina. Ten řekl: Netáhni. Obejdi je zezadu a přitáhni k nim směrem od balzámovníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'I stane se, až uslyšíš zvuk pochodování ve vrcholcích balzámovníků, tehdy jednej rozhodně, protože tehdy ⌈vytáhne Hospodin před tebou, aby pobil⌉ pelištejské vojsko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David učinil tak, jak ⌈mu Hospodin přikázal,⌉ a pobíjel Pelištejce od Geby až do Gezeru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'David znovu shromáždil všechny vybrané muže z Izraele, celkem třicet tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'David a všechen lid, který byl s ním, vstal a šel z Baalímu v Judsku, aby odtamtud přinesli Boží truhlu, ⌈která se nazývá jménem,⌉ jménem Hospodina zástupů, sedícího na cherubech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Naložili Boží truhlu na nový vůz a vezli ji z Abínádabova domu, který je na kopci. Ten nový vůz vedli Uza a Achjó, synové Abínádabovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Vezli ji z Abínádabova domu, který je na kopci, Uza šel u Boží truhly. Achjó šel před truhlou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'David a ⌈celý dům izraelský⌉ se radovali před Hospodinem a hráli na všelijaké nástroje z cypřišového dřeva, na lyry, harfy, tamburíny, chřestítka a činely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Když přišli k Nákonovu humnu, sáhl Uza na Boží truhlu a podržel ji, protože voli ⌈opustili cestu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Hospodinův hněv vzplál proti Uzovi a Bůh ho tam pro neúctu zabil. Zemřel tam u Boží truhly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'David se rozzlobil kvůli tomu, že ⌈se Hospodin prudce obořil na Uzu.⌉ To místo se nazývá dodnes Peres–uza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Toho dne se David začal bát Hospodina a řekl: Jak může vejít ke mně Hospodinova truhla?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Proto si David nechtěl Hospodinovu truhlu vzít k sobě do Města Davidova. David ji odsunul do domu Obéd–edóma Gatského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Hospodinova truhla zůstala v domě Obéd–edóma Gatského tři měsíce a Hospodin žehnal Obéd–edómovi i celému jeho domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Králi Davidovi bylo oznámeno: Hospodin kvůli Boží truhle požehnal domu Obéd–edóma i všemu, co mu patří. Nato David šel a s radostí vynesl Boží truhlu z domu Obéd–edómova do Města Davidova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'I stalo se, že když ⌈ti, kteří nesli⌉ Hospodinovu truhlu, ušli šest kroků, obětoval ⌈býka a vykrmené dobytče.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'David tancoval ze vší síly před Hospodinem; David byl přepásán lněným efódem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Tak David a celý dům izraelský přinášeli Hospodinovu truhlu s ⌈ radostným křikem⌉ a za zvuku beraního rohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'I stalo se, že když Hospodinova truhla vstupovala do Města Davidova, Míkal, dcera Saulova, se rozhlížela z okna a uviděla krále Davida, jak poskakuje a tancuje před Hospodinem, a pohrdla jím ve svém srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Přinesli Hospodinovu truhlu a postavili ji na její místo uprostřed stanu, který pro ni David postavil. Pak David přinesl před Hospodinem zápalné a pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Když David dokončil přinášení zápalných a pokojných obětí, požehnal lidu ve jménu Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Nato podělil všechen lid, celé množství Izraelců, ⌈muže i ženy,⌉ každému dal jeden bochník chleba, jeden ⌈datlový⌉ koláč a jeden hrozinkový koláč. Pak ⌈se všechen lid rozešel domů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Když se David vracel, aby pozdravil svou rodinu, vyšla mu naproti Míkal, dcera Saulova, a řekla: Jak ⌈se dnes izraelský král oslavil,⌉ když se dnes odhaloval před otrokyněmi svých otroků, jako se odhalují jen nějací blázni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'David Míkal odpověděl: Před Hospodinem, který mě vyvolil místo tvého otce a místo celého tvého domu a ustanovil mě vévodou nad Hospodinovým lidem, nad Izraelem, před Hospodinem se budu radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'I kdybych byl ještě více zlehčován a ⌈byl ponížený ve svých očích,⌉ otrokyněmi, o kterých jsi mluvila, jimi budu oslavován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Míkal, dcera Saulova, neměla děti až do dne své smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'I stalo se, když král sídlil ve svém domě a Hospodin mu dal odpočinek od všech jeho okolních nepřátel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'že řekl král proroku Nátanovi: Pohleď, já sídlím v cedrovém domě a Boží truhla sídlí pod stanovou plachtou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Nátan králi odpověděl: Jdi a učiň vše, co ⌈máš na srdci,⌉ protože ⌈Hospodin je s tebou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Oné noci se však stalo Hospodinovo slovo k Nátanovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Jdi a řekni mému otroku Davidovi: Toto praví Hospodin: ⌈Ty mi chceš postavit⌉ dům, abych v něm sídlil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Vždyť jsem nesídlil v domě ode dne, kdy jsem vyvedl Izraelce z Egypta, až dodnes, ale přecházel jsem ve ⌈stanu jako příbytku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Ať jsem přecházel se všemi Izraelci kudykoli, řekl jsem snad některému z izraelských kmenů, kterému jsem přikázal pást můj lid Izrael: Proč mi nepostavíte cedrový dům?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'A nyní toto pověz mému otroku Davidovi: Toto praví Hospodin zástupů: Vzal jsem tě z pastvin, od ⌈ chovu ovcí,⌉ abys byl vévodou nad mým lidem, nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Byl jsem s tebou, kamkoli jsi šel, a vyhladil jsem před tebou všechny tvé nepřátele. Učiním tvé jméno velké, jako je jméno velikánů na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Nachystám pro svůj lid Izrael území, zasadím ho, bude bydlet na svém místě a nebude se již třást. Bídáci ho nebudou již pokořovat jako na počátku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'ode dne, kdy jsem ustanovil soudce nad svým lidem Izraelem. Dám ti odpočinek od všech tvých nepřátel. Hospodin ti oznamuje, že on postaví dům tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Až se naplní tvé dny a ulehneš ⌈se svými otci,⌉ dám po tobě povstat tvému potomku, který vyjde ze tvých beder a upevním jeho království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'On postaví dům pro mé jméno a upevním ⌈jeho královský trůn⌉ navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Já ⌈budu jeho⌉ otcem a on ⌈bude mým⌉ synem. Když bude činit zlo, budu ho kárat ⌈lidskou holí a ranami lidských synů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Mé milosrdenství však od něj neodstoupí, jako jsem je odňal od Saula, kterého jsem před tebou odstranil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Trvalý bude tvůj dům i tvé království navěky před tebou, tvůj trůn bude navěky pevně stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Nátan Davidovi pověděl ⌈všechna tato slova⌉ a ⌈celé toto vidění.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Nato král David vešel, posadil se před Hospodinem a řekl: Kdo jsem já, Panovníku Hospodine, a co je můj dům, že jsi mě přivedl až sem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'I toto bylo ještě málo ve tvých očích, Panovníku Hospodine, a tak jsi promluvil ještě o domu svého otroka do vzdálené budoucnosti. ⌈ Ať je to poučením pro člověka,⌉ Panovníku Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Co ti může David ještě dále říct? Ty znáš svého otroka, Panovníku Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Kvůli svému slovu a podle svého srdce jsi učinil ⌈všechny tyto velké věci ⌉ a dal jsi to svému otroku poznat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Proto jsi veliký, Panovníku Hospodine. Ano, ⌈není nikdo jako ty⌉ a není Boha kromě tebe -- tak, jak jsme na vlastní uši slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'A kdo je jako tvůj lid Izrael, jediný národ na zemi, kterého šel Bůh vykoupit sobě za lid, a ⌈učinil si jméno,⌉ když vykonal pro ně velké a hrůzu vzbuzující činy, pro tvou zemi. Vyhnal jsi před svým lidem, který jsi vykoupil pro sebe z Egypta, ⌈národy a jejich bohy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Určil sis svůj lid Izrael za svůj lid navěky. Ty, Hospodine, ses stal jejich Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'A nyní, Hospodine Bože, naplň navěky slovo, které jsi promluvil o svém otroku a o jeho domě, a učiň, jak jsi prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, '⌈Tak bude⌉ tvé jméno veliké navěky, když budou říkat: Hospodin zástupů je Bůh nad Izraelem; a dům tvého otroka Davida bude pevně stát před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Ty, Hospodine zástupů, Bože Izraele, jsi odhalil uchu svého otroka a řekl jsi: Postavím ti dům. Proto tvůj otrok našel odvahu modlit se k tobě tuto modlitbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nyní, Panovníku Hospodine, ty jsi Bůh, tvá slova jsou pravdivá a promluvil jsi ke svému otroku toto dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Nyní ⌈rač požehnat⌉ dům svého otroka, aby byl navěky před tebou. Ty, Panovníku Hospodine, jsi promluvil a tvým požehnáním bude požehnán dům tvého otroka navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Potom se stalo, že David pobil Pelištejce a pokořil je. David vzal od Pelištejců Meteg–Ammá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Pobil i Moábce a odměřil je provazem, když je nechal lehnout na zem; odměřil dva provazy k usmrcení a celý provaz k zachování při životě. Moábci se stali Davidovými otroky a přinášeli dávky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David pobil také Hadad–ezera, syna Rechóbova, krále Sóby, když táhl obnovit svou moc u řeky Eufratu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'David mu zajal tisíc sedm set jezdců a dvacet tisíc pěšáků. David ochromil všechny koně k vozům a ponechal mu koně jen ke stu vozům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Aramejci z Damašku přitáhli Hadad–ezerovi, králi Sóby, na pomoc, ale David pobil z Aramejců dvacet dva tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Pak David umístil ⌈mezi Aramejce z Damašku⌉ posádku; Aramejci se stali Davidovými otroky a přinášeli dávky. Hospodin ⌈pomáhal Davidovi,⌉ kamkoli šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'David vzal zlaté štíty, které ⌈patřily Hadad–ezerovým otrokům,⌉ a přinesl je do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Z Betachu a Berótaje, Hadad–ezerových měst, vzal král David velké množství bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Když se Toí, král Chamátu, doslechl, že David pobil celé Hadad–ezerovo vojsko,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'poslal Toí svého syna Jórama ke králi Davidovi, aby ⌈se ho zeptal, jak se mu ⌉ daří, a poblahopřál mu, ⌈že bojoval proti Hadad–ezerovi a zabil ho.⌉ Toí totiž vedl války s Hadad–ezerem. Jóram ⌈s sebou⌉ přinesl stříbrné, zlaté a bronzové předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Také ty král David zasvětil Hospodinu spolu se stříbrem a zlatem, které zasvětil od všech národů, jež si podmanil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'od Aramejců, Moábců, synů Amónových, od Pelištejců, Amálekovců a z kořisti Hadad–ezera, syna Rechóbova, krále Sóby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'David ⌈si učinil jméno,⌉ když se vrátil ze svého boje proti Aramejcům v Solném údolí; bylo jich osmnáct tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Umístil v Edómu posádku, umístil posádku v celém Edómu a všichni Edómci se stali Davidovými otroky. Hospodin pomáhal Davidovi, kamkoli šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'David kraloval nad celým Izraelem. David ⌈vykonával právo⌉ a spravedlnost nad celým svým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Jóab, syn Serújin, byl nad armádou, Jóšafat, syn Achílúdův, byl kancléřem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Sádok, syn Achítúbův, a Achímelek, syn Ebjátarův, byli kněžími; Serajáš byl písařem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benajáš, syn Jójadův, ⌈ byl nad ⌉ Keretejci a Peletejci. Davidovi synové byli kněžími.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'David se zeptal: ⌈Zůstal ještě někdo⌉ z domu Saulova, abych mu prokázal milosrdenství kvůli Jónatanovi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Dům Saulův měl otroka jménem Síba. Zavolali ho k Davidovi. Král se ho zeptal: Ty jsi Síba? Odpověděl: Tvůj otrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Král se zeptal: Zůstal ještě někdo z domu Saulova, abych mu prokázal Boží milosrdenství? Síba králi odpověděl: Zůstal ještě Jónatanův syn, chromý na nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Král se ho zeptal: Kde je? Síba králi odpověděl: Je v domě Makíra, syna Amíelova, v Lódebaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Král David pro něj poslal a nechal si ho z domu Makíra, syna Amíelova, z Lódebaru přivést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Když Mefíbóšet, syn Jónatana, syna Saulova, přišel k Davidovi, padl na tvář a poklonil se. David řekl: Mefíbóšete! On odpověděl: Ano, tvůj otrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David mu řekl: Neboj se! Jistě ti prokážu milosrdenství kvůli tvému otci Jónatanovi a vrátím ti všechny polnosti tvého děda Saula. Trvale budeš jíst pokrm u mého stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Nato se Mefíbóšet poklonil a řekl: Co je tvůj otrok, že se zajímáš o ⌈mrtvého psa,⌉ jako jsem já?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Král zavolal Saulova služebníka Síbu a řekl mu: Všechno, co patřilo Saulovi a celému jeho domu, jsem dal vnukovi tvého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Ty se svými syny a svými otroky mu budeš obdělávat zemi a sklízet úrodu, aby vnuk tvého pána měl pokrm a jedl jej. Mefíbóšet, vnuk tvého pána, však bude jíst pokrm trvale u mého stolu. Síba měl patnáct synů a dvacet otroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Síba řekl králi: Všechno, co můj pán a král svému otroku přikázal, tvůj otrok učiní, ⌈ačkoliv Mefíbóšet jedl u mého⌉ stolu jako jeden z královských synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefíbóšet měl malého syna jménem Míka. Všichni obyvatelé Síbova domu byli Mefíbóšetovými otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Mefíbóšet bydlel v Jeruzalémě, protože jedl trvale u královského stolu; byl chromý na obě nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Potom se stalo, že zemřel král synů Amónových a po něm se stal králem jeho syn Chanún.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'David si řekl: ⌈Prokážu milosrdenství⌉ Chanúnovi, synu Náchašovu, jako jeho otec prokázal milosrdenství mně. A tak David poslal ⌈své otroky, aby mu jejich prostřednictvím poskytl útěchu⌉ nad jeho otcem. Když přišli Davidovi otroci do země synů Amónových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'knížata synů Amónových řekla svému pánu Chanúnovi: Připadá ti, že David chce uctít tvého otce, když ti poslal utěšitele? Což k tobě David neposlal své otroky, jen aby ⌈důkladně prohlédl⌉ město, aby ho prozkoumal a vyvrátil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Proto Chanún vzal Davidovy otroky, oholil polovinu jejich vousů, odřízl polovinu jejich roucha až po zadek a poslal je pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Když to Davidovi oznámili, poslal jim naproti, protože ti muži byli velice zhanobeni. Král řekl: Zůstaňte v Jerichu, dokud vám vousy nedorostou, a pak se vraťte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Synové Amónovi viděli, že se Davidovi znelíbili. Proto synové Amónovi poslali a najali si Aramejce z Bét–rechóbu a Aramejce ze Sóby, dvacet tisíc pěšáků, od krále z Maaky tisíc mužů a od Íš–tóba dvanáct tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Když se to David doslechl, poslal Jóaba a celou armádu hrdinů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Synové Amónovi vytáhli a sešikovali se k boji u vchodu do brány, ale Aramejci ze Sóby a Rechóbu, Íš–tób a Maaka byli zvlášť na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Když Jóab viděl, že je proti němu boj zpředu i zezadu, vybral ⌈všechny vybrané muže ⌉ z Izraele a sešikoval se proti Aramejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Zbytek lidu dal ⌈pod velení⌉ svého bratra Abíšaje, aby se sešikovali proti synům Amónovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Řekl: Když budou Aramejci silnější nežli já, přijdeš mi na pomoc, a když budou synové Amónovi silnější nežli ty, přijdu na pomoc já tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Buď silný a počínejme si zmužile za svůj lid a za města našeho Boha a Hospodin ať učiní, co je dobré v jeho očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Jóab a lid, který byl s ním, ⌈se pustil do boje⌉ proti Aramejcům, ale ti před ním utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Když synové Amónovi viděli, že Aramejci utíkají, utekli také před Abíšajem a vešli do města. Jóab se tedy vrátil od synů Amónových a vstoupil do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Když Aramejci viděli, že byli od Izraele poraženi, všichni se shromáždili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Hadad–ezer poslal posly a nechal přivést Aramejce, kteří byli v Zaeufratí. Přitáhli tedy do Chélamu. ⌈V jejich čele⌉ byl Šóbak, velitel Hadad–ezerovy armády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Když to bylo Davidovi oznámeno, shromáždil celý Izrael, přešel Jordán a přišel do Chélamu. Aramejci se proti Davidovi sešikovali a bojovali s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Aramejci však před Izraelem utekli. David zabil sedm set ⌈aramejských voza tajů ⌉ a čtyřicet tisíc jezdců. Ranil také velitele armády Šóbaka, který tam zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Když všichni králové, otroci Hadad–ezera, viděli, že byli od Izraele poraženi, uzavřeli s Izraelem mír a sloužili mu. Aramejci se již báli pomáhat synům Amónovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'I stalo se na ⌈přelomu roku,⌉ v době, kdy králové táhnou do boje, že David poslal Jóaba a s ním své otroky i celý Izrael, aby ničili syny Amónovy a oblehli Rabu. Ale David zůstal v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Navečer se stalo, že David vstal z postele a procházel se na střeše královského paláce. Ze střechy uviděl ženu, jak se umývá. Byla to žena velmi ⌈hezkého vzhledu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'David poslal posla poptat se na tu ženu. Posel řekl: To je přece Bat–šeba, dcera Elíamova, žena Chetejce Urijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'David poslal posly a nechal ji přivést. Když k němu přišla, spal s ní; právě se očistila od své nečistoty. Pak se vrátila domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Ta žena otěhotněla a dala Davidovi oznámit: Jsem těhotná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'David vzkázal Jóabovi: Pošli mi Chetejce Urijáše. Nato Jóab poslal Urijáše k Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Když k němu Urijáš přišel, David se zeptal, jak se daří Jóabovi, jak se daří lidu a jak se daří v boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'David Urijášovi řekl: ⌈Jdi domů⌉ a umyj si nohy. Když Urijáš odešel z královského paláce, šel za ním královský dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Urijáš si však lehl u vchodu do královského paláce se všemi otroky svého pána a nešel domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Davidovi oznámili: Urijáš nešel domů. David se Urijáše zeptal: Což jsi nepřišel z cesty? Proč jsi nešel domů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Urijáš Davidovi odpověděl: Truhla, Izraelci i Judejci zůstávají ve stanech a můj pán Jóab i otroci mého pána táboří na poli. A já bych měl jít domů, jíst a pít a spát se svou ženou? Jakože jsi živ ty a jakože je živa tvá duše, něco takového neučiním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'David řekl Urijášovi: Zůstaň tady ještě dnes a zítra tě propustím. Urijáš tedy zůstal v Jeruzalémě v ten den i druhý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'David ho pozval, ⌈jedl s ním⌉ a pil, až ho opil. Večer odešel, aby si lehl na své lože s otroky svého pána, ale domů nešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'I stalo se ráno, že napsal David Jóabovi dopis a poslal ho po Urijášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Do dopisu napsal toto: Dejte Urijáše do přední linie nejprudšího boje a pak od něj ustupte, aby byl zabit a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'I stalo se, že když Jóab obléhal město, dal Urijáše na místo, o kterém věděl, že jsou tam bojovníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Muži toho města vyrazili a bojovali s Jóabem a padli někteří z lidu, z Davidových otroků. Zemřel také Chetejec Urijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Jóab vzkázal oznámit Davidovi ⌈celou zprávu⌉ o bitvě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Přikázal poslovi: Až dopovíš králi ⌈celou zprávu⌉ o bitvě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'pokud vzplane králův hněv a řekne ti: Proč jste se přiblížili k městu, abyste bojovali? Což nevíte, že budou střílet z hradeb?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kdo zabil Abímeleka, syna Jerúbešetova? Což to ne byla žena, která na něj svrhla mlýnský kámen z hradby, takže zemřel v Tebesu? Proč jste se přiblížili k hradbám? Tehdy řekneš: Zemřel také tvůj otrok Chetejec Urijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Posel tedy šel, až přišel a oznámil Davidovi všechno, co mu Jóab vzkázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Posel řekl Davidovi: Ti muži ⌈nad námi vítězili⌉ a vytáhli proti nám do pole. ⌈Zahnali jsme je však⌉ až ke vstupu do brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Střelci ovšem stříleli na tvé otroky z hradeb a někteří z královských otroků zemřeli. Zemřel také tvůj otrok Chetejec Urijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'David řekl poslovi: Řekni Jóabovi toto: ⌈Nebuď kvůli tomu skleslý.⌉ Vždyť meč ⌈požírá hned toho, hned onoho.⌉ Zesil svůj boj proti městu a zboř ho. Takto ho posilni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Když Urijášova žena uslyšela, že její muž Urijáš je mrtev, oplakávala svého manžela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Když ⌈pominuly smuteční obřady,⌉ David pro ni poslal a vzal ji do svého domu. Stala se jeho ženou a porodila mu syna. To, co David spáchal, ⌈však bylo v Hospodinových očích zlé.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Hospodin poslal k Davidovi Nátana. Přišel k němu a řekl mu: V jednom městě byli dva muži; jeden bohatý a druhý chudý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Bohatý měl velmi mnoho ovcí a skotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Chudý neměl nic než jen jednu malou ovečku, kterou koupil. Živil ji, vyrůstala u něho spolu s jeho syny. Jídala jeho sousto chleba, pila z jeho poháru a spávala v jeho klíně. Měl ji jako dceru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Nějaký pocestný přišel k bohatému muži, ale tomu bylo líto vzít ze svých ovcí či ze svého skotu a připravit poutníkovi, který k němu přišel. Tak vzal ovečku chudého muže a připravil ji muži, který k němu přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'David proti tomu muži velice ⌈vzplál hněvem⌉ a řekl Nátanovi: Jakože živ je Hospodin, muž, který to spáchal, je ⌈synem smrti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'A tu ovečku nahradí čtyřnásobně za to, že toto spáchal, a protože neměl soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Nátan Davidovi řekl: Ty jsi ten muž! Toto praví Hospodin, Bůh Izraele: Já jsem tě pomazal za krále nad Izraelem. Já jsem tě vysvobodil ze Saulovy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Dal jsem ti dům tvého pána a ženy tvého pána do tvého klína. Dal jsem ti dům izraelský a judský. A kdyby to bylo málo, přidal bych ti to či ono.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Proč jsi pohrdl Hospodinovým slovem a spáchal jsi ⌈zlo v jeho očích?⌉ Chetejce Urijáše jsi zabil mečem a jeho manželku sis vzal za ženu; zabil jsi ho mečem synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nyní se meč navždy neodvrátí od tvého domu za to, že jsi mnou pohrdl a vzal sis manželku Chetejce Urijáše, aby byla tvou ženou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Toto praví Hospodin: Hle, já dám povstat proti tobě zlu z tvého domu. Před tvýma očima vezmu tvé ženy a dám je tvému bližnímu. Bude s tvými ženami spát ⌈za denního světla.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Ty jsi to sice spáchal tajně, já však to učiním před celým Izraelem a ⌈za denního světla.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'David řekl Nátanovi: Zhřešil jsem proti Hospodinu. Nátan Davidovi odpověděl: Hospodin také odňal tvůj hřích, nezemřeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Ovšem protože ⌈jsi touto věcí tolik znevážil Hospodina,⌉ syn, který se ti narodí, jistě zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Pak Nátan odešel domů. Hospodin postihl dítě, které porodila Urijášova žena Davidovi, takže těžce onemocnělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'David ⌈hledal Boha kvůli tomu chlapci.⌉ Postil se, šel, ⌈ulehl a spal⌉ na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Starší jeho domu k němu přistoupili, aby ho zvedli ze země, ale nechtěl, ani s nimi nepojedl pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Sedmého dne se stalo, že dítě zemřelo. Davidovi otroci se báli mu oznámit, že dítě zemřelo. Říkali: Když bylo dítě naživu, přemlouvali jsme ho, a neuposlechl nás. Jak bychom mu mohli říct, že dítě zemřelo? Mohl by učinit něco zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'David však viděl, že jeho otroci si něco šeptali, a pochopil, že dítě zemřelo. Proto se David svých otroků zeptal: Dítě zemřelo? Odpověděli: Zemřelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Nato David vstal ze země, umyl se, pomazal se olejem a vyměnil si oděv. Šel do Hospodinova domu a poklonil se. Pak přišel domů, a když požádal, předložili mu pokrm a pojedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Jeho otroci se ho zeptali: ⌈Co má znamenat to, co⌉ jsi učinil? Když bylo dítě naživu, postil ses a plakal, a jakmile dítě zemře, vstaneš a pojíš pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Odpověděl: Když bylo dítě naživu, postil jsem se a plakal, protože jsem si říkal: Kdo ví, snad se nade mnou Hospodin slituje a dítě bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Nyní zemřelo. Nač bych se měl postit? Což ho mohu zase přivést zpět? Já půjdu k němu, ale ono se ke mně nevrátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'David potěšil svou ženu Bat–šebu, vešel k ní a spal s ní. Porodila syna a pojmenoval ho Šalomoun. Hospodin si ho zamiloval');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'a vzkázal po proroku Nátanovi, aby ho pojmenoval Jedidjáš, kvůli Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Jóab bojoval proti Rabě synů Amónových a královské město dobyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Jóab poslal k Davidovi posly se slovy: Bojoval jsem proti Rabě a již jsem dobyl ⌈Vodní město.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Nyní shromáždi zbytek lidu, utáboř se proti městu a dobuď ho. Jinak dobudu město já a bude nazváno mým jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'David shromáždil všechen lid a vytáhl k Rabě. Bojoval proti ní a dobyl ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Korunu ⌈jejich krále⌉ vzal z jeho hlavy -- vážila talent zlata a byl na ní drahokam -- a spočinula na Davidově hlavě. Vynesl z města velmi mnoho kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Lid, který byl v něm, vyvedl a ustanovil, aby pracovali s pilou, železnými špičáky a železnými sekyrami, a přivedl je do cihelny. Tak jednal se všemi městy synů Amónových. David a všechen lid se pak vrátil do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Potom se stalo toto: Abšalóm, syn Davidův, měl krásnou sestru jménem Támar a Amnón, syn Davidův, se do ní zamiloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Amnónovi bylo tak úzko, že onemocněl kvůli své sestře Támar, protože byla pannou a Amnónovi připadalo nesnadné ⌈s ní něco mít.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Amnón měl přítele jménem Jónadab, syna Davidova bratra Šimey. Jónadab byl muž velmi chytrý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Ten se ho zeptal: Proč ty, královský syn, jsi ráno co ráno tak sklíčený? Pověz mi to! Amnón mu odpověděl: Zamiloval jsem se do Támary, sestry svého bratra Abšalóma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jónadab mu řekl: Lehni si na postel a dělej, že jsi nemocný. Až se tvůj otec na tebe přijde podívat, řekni mu: Ať přijde, prosím, má sestra Támar a dá mi pojíst pokrm. Ať dělá jídlo přede mnou, abych se mohl dívat. ⌈Od ní⌉ pojím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnón si lehl a dělal, že je nemocný. Když se na něj král přišel podívat, Amnón králi řekl: Ať přijde, prosím, má sestra Támar a udělá přede mnou dva koláčky. Od ní pojím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'David vzkázal Támaře do domu: Jdi prosím do domu svého bratra Amnóna a udělej mu jídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Támar šla do domu svého bratra Amnóna a on ležel. Vzala těsto, uhnětla, udělala před ním koláčky a upekla je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Pak vzala pánev a vyklopila před ním, ale on odmítl jíst. Amnón řekl: Ať ode mě všichni odejdou. Všichni od něj tedy odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Támaře Amnón řekl: Přines jídlo do pokoje, ať od tebe pojím. Támar vzala koláčky, které udělala, a přinesla je do pokoje svému bratru Amnónovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Když se však k němu přiblížila, aby jedl, uchopil ji a řekl jí: Pojď ⌈se mnou spát,⌉ má sestro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Odpověděla mu: Ne, můj bratře, neznásilňuj mě. Vždyť to se v Izraeli nedělá. Nepáchej takovou hanebnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Co se mě týče, ⌈kam přinesu svou potupu?⌉ A ty budeš v Izraeli vypadat jako nějaký hanebník. Promluv, prosím, nyní s králem, on mě tobě neodepře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'On ji ale nechtěl uposlechnout, přemohl ji, znásilnil ji a spal s ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Nato ⌈ji Amnón začal nenávidět velmi velkou nenávistí.⌉ Ano, nenávist, kterou ji nenáviděl, byla větší nežli láska, kterou ji miloval. Amnón jí řekl: ⌈Vstaň a odejdi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Ona mu řekla: Ne, ⌈můj bratře.⌉ Kdybys mě propustil, bylo by to větší zlo nežli to první, které jsi vůči mně spáchal. On ji však nechtěl poslouchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Zavolal služebníka, který mu sloužil, a řekl: Pošlete tuhle pryč ode mě a zavři za ní dveře na závoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Měla na sobě ⌈ dlouhé roucho s rukávy,⌉ neboť taková roucha oblékaly královské dcery panny. Když ji jeho služebník vyvedl ven a zavřel za ní dveře na závoru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Támar si dala popel na hlavu, roztrhla dlouhé roucho s rukávy, které měla na sobě, položila si ruku na hlavu, šla a stále naříkala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Její bratr Abšalóm se jí zeptal: Cožpak s tebou ne byl tvůj bratr Amnón? Teď ale, má sestro, umlkni. Je to tvůj bratr. ⌈Neber si to tak.⌉ Támar pak bydlela opuštěná v domě svého bratra Abšalóma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Když se král David o všech těch věcech doslechl, velice se rozzlobil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Abšalóm ovšem s Amnónem ⌈nemluvil ani ve zlém ani v dobrém.⌉ Nenáviděl totiž Amnóna za to, že znásilnil jeho sestru Támaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Po dvou letech se stalo, že Abšalóm měl stříž ovcí v Baal–chasóru, který je u Efrajima. Abšalóm pozval všechny královské syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Abšalóm přišel ke králi a řekl: Pohleď, tvůj otrok má stříž ovcí. Nechť jde král a jeho otroci s tvým otrokem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Král Abšalómovi odpověděl: Ne, můj synu, nechoďme všichni. Nebudeme tě zatěžovat. Ačkoliv ho nutil, nechtěl jít, ale požehnal mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Pak se Abšalóm ⌈zeptal: Ani můj bratr Amnón s námi ne může jít?⌉ Král mu řekl: Proč by měl jít s tebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Ale Abšalóm ho nutil, až s ním poslal Amnóna a všechny královské syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Potom dal Abšalóm svým služebníkům příkaz: Dívejte se, a až bude ⌈Amnón v dobrém rozmaru⌉ z vína a řeknu vám: Udeřte na Amnóna -- usmrťte ho a nebojte se. Vždyť jsem vám to přikázal já. Buďte silní a udatní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Abšalómovi služebníci provedli Amnónovi to, co Abšalóm přikázal. Nato všichni královští synové vstali, nasedli každý na svého mezka a utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Když byli na cestě, přišla k Davidovi zpráva: Abšalóm zabil všechny královské syny, nezůstal z nich ani jeden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Král povstal, roztrhl své roucho a lehl si na zem. Všichni jeho otroci stáli s roztrženými rouchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Nato promluvil Jónadab, syn Davidova bratra Šimey: Ať si můj pán nemyslí, že usmrtili všechny mládence, královské syny. Vždyť jenom Amnón zemřel. Vždyť ⌈Abšalóm byl rozhodnut⌉ ode dne, kdy Amnón znásilnil jeho sestru Támaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Tak ať si to můj pán a král ⌈ tak nebere⌉ a ne říká: Všichni královští synové jsou mrtví, protože zemřel jenom Amnón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Abšalóm utekl. Když strážný služebník pozvedl oči, uviděl, že právě ⌈cestou za ním⌉ přichází po úbočí hory množství lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Jónadab řekl králi: Pohleď, královští synové přicházejí. Jak řekl tvůj otrok, tak se stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Když domluvil, královští synové právě přišli. ⌈Pozvedli svůj hlas a plakali.⌉ Také král a všichni jeho otroci plakali velmi velkým pláčem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Abšalóm utekl a šel k Talmajovi, synu Amíhudovu, gešúrskému králi. David po všechny dny truchlil nad svým synem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Abšalóm utekl a šel do Gešúru. Zůstal tam tři roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Pak král David ⌈zatoužil jít⌉ za Abšalómem, neboť ⌈došel útěchy nad⌉ ⌈Amnónovou smrtí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Když Jóab, syn Serújin, poznal, že ⌈králova mysl je obrácena k⌉ Abšalómovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'poslal do Tekóje a nechal odtamtud přivést moudrou ženu. Řekl jí: Dělej, že truchlíš. Obleč si smuteční šaty, nemaž se olejem a chovej se jako žena, která po mnoho dní truchlí nad mrtvým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Jdi ke králi a řekni mu ⌈to a to.⌉ Jóab pak ⌈vložil slova do jejích úst.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Tekójská žena pak přišla ke králi, padla tváří k zemi, klaněla se a řekla: Pomoz, králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Král se jí zeptal: Co ⌈ je s tebou?⌉ Odpověděla: Ach, jsem vdova, můj muž zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Tvá služka měla dva syny. Rvali se spolu na poli a nebyl, ⌈kdo by je od sebe odtrhl.⌉ Jeden udeřil druhého a usmrtil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'A teď povstala celá rodina proti tvé služce a říkají: Vydej nám toho, kdo ubil svého bratra, a usmrtíme ho za život jeho bratra, kterého zabil, a vyhladíme i dědice. Tak by mi uhasili oharek, který zůstal, neponechali by mému muži na povrchu země jméno ani ostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Nato král ženě řekl: Jdi domů a já vydám o tobě příkaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Tekójská žena králi odpověděla: Na mně, můj pane a králi, ať je vina a na domu mého otce. Avšak král a jeho trůn ať je nevinný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Král řekl: Jestliže někdo promluví proti tobě, přiveď ho ke mně a nebude se tě již moci dotknout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Řekla: Ať král pamatuje na Hospodina, svého Boha, aby ne chtěl již krevní mstitel zabíjet a nevyhladili mého syna. Řekl: Jakože živ je Hospodin, tvému synovi nespadne na zem ani vlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Žena se zeptala: Smí tvá služka svému pánu a králi ještě něco říct? Odpověděl: Mluv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Žena řekla: A proč zamýšlíš něco takového proti Božímu lidu? Když král prohlásil něco takového, jako by nesl vinu za to, že ne dovolil navrátit se tomu, koho zapudil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Jistě zemřeme a budeme jako na zem vylitá voda, kterou ne lze sebrat. Bůh však neodejme život, ⌈má v úmyslu⌉ ⌈nezapudit od sebe zapuzeného.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Nuže, přišla jsem ke svému králi a pánu promluvit tuto řeč, protože mě lid zastrašoval. Tvá služka si říkala: Promluvím ke králi. Snad král učiní záměr své otrokyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Král vyslechne a vysvobodí svou otrokyni z moci muže, který chce vyhladit mě spolu s mým synem z Božího dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Tvá služka si říkala: Kéž mi slovo mého pána a krále přinese upokojení, vždyť můj pán a král je jako ⌈Boží posel,⌉ který rozumí dobru a zlu. Hospodin, tvůj Bůh, ať je s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Král promluvil a řekl ženě: Nezatajuj přede mnou nic, na co se tě zeptám. Žena odpověděla: Nechť mluví můj pán a král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Král se zeptal: Není v tom všem s tebou Jóab? Žena odpověděla: Jakože jsi živ, můj pane a králi, ⌈je to přesně tak, jak⌉ řekl můj pán a král. Tvůj otrok Jóab mi dal příkaz, on vložil do úst tvé služky všechna tato slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, '⌈Kvůli zvratu⌉ v té věci to tvůj otrok Jóab udělal. Můj pán je moudrý jako Boží anděl a ví všechno, co se děje na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Král řekl Jóabovi: Dobře, udělám to. Jdi a přiveď mládence Abšalóma zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Jóab padl tváří k zemi, klaněl se a dobrořečil králi. Jóab řekl: Dnes tvůj otrok ví, že nalezl milost ve tvých očích, můj pane a králi, protože král provedl záměr svého otroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Jóab vstal, šel do Gešúru a přivedl Abšalóma do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Král řekl: Ať se odebere do svého domu, mou tvář nezahlédne. Abšalóm se tedy odebral do svého domu a královu tvář nezahlédl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Nikdo v celém Izraeli nebyl ⌈ tak velmi opěvován pro svou krásu jako Abšalóm.⌉ ⌈Od paty až k hlavě⌉ na něm nebylo vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Když si nechával ostříhat hlavu -- bylo to vždy na konci roku, kdy se nechával ostříhat, protože ho vlasy tížily, takže se nechal ostříhat -- vlasy z jeho hlavy vážily dvě stě šekelů královské váhy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Abšalómovi se narodili tři synové a jedna dcera jménem Támar. Byla to žena krásného vzhledu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Abšalóm pobýval v Jeruzalémě dva roky, avšak královu tvář nezahlédl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Potom Abšalóm vzkázal pro Jóaba, aby ho poslal ke králi. Ten k němu ale nechtěl přijít. Vzkázal ještě podruhé, ale nechtěl přijít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Nato řekl svým otrokům: Podívejte, Jóabovo pole je vedle mého. Má tam ječmen. Jděte a zapalte ho. Abšalómovi otroci zapálili to pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Jóab vstal, šel domů k Abšalómovi a zeptal se ho: Proč tvoji otroci zapálili pole, které patří mně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Abšalóm Jóabovi odpověděl: Podívej, vzkázal jsem pro tebe se slovy: Přijď sem, abych tě poslal ke králi se slovy: Proč jsem měl přijít z Gešúru? Bylo by mi lépe, kdybych byl ještě tam. Teď chci vidět královu tvář. Anebo jestli je na mně vina, ať mě dá usmrtit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Jóab šel ke králi a oznámil mu to. Ten Abšalóma zavolal. Když přišel ke králi, klaněl se před králem ⌈tváří k⌉ zemi. A král Abšalóma políbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Později se stalo, že si Abšalóm pořídil válečný vůz, koně a padesát mužů, kteří před ním běhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Abšalóm časně vstával a postavil se u cesty do brány. I stávalo se, že na každého, kdo měl spor a šel za králem k soudu, Abšalóm volal: Z jakého jsi města? On odpovídal: Tvůj otrok je z jednoho z izraelských kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Abšalóm mu pak řekl: Podívej se, tvá záležitost je dobrá a správná, ale ⌈král nepověřil nikoho, kdo by tě vyslechl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Abšalóm řekl: ⌈Kdybych já byl ustanoven⌉ soudcem v zemi, každý, kdo by měl spor či ⌈právní záležitost,⌉ by mohl přijít ke mně a zjednal bych mu spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'A stávalo se, že když se někdo přiblížil, aby se mu klaněl, vztáhl ruku, uchopil ho a políbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Abšalóm ⌈takto jednal vůči všem Izraelcům,⌉ kteří přicházeli za králem k soudu. Tak Abšalóm ⌈oklamal Izraelce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Po čtyřiceti letech se stalo, že Abšalóm řekl králi: Dovol, ať jdu do Chebrónu splnit slib, který jsem učinil Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Tvůj otrok učinil totiž slib, když jsem bydlel v Gešúru v Aramu: Jestliže mě Hospodin přivede zpět do Jeruzaléma, budu sloužit Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Král mu řekl: Jdi v pokoji. Vstal tedy a šel do Chebrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Abšalóm poslal do všech izraelských kmenů zvědy se slovy: Až uslyšíte zvuk beraního rohu, řekněte: Abšalóm se stal v Chebrónu králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'S Abšalómem šlo z Jeruzaléma dvě stě mužů; byli pozváni a šli ve své bezúhonnosti, o ničem nevěděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Zatímco obětoval oběti, poslal Abšalóm pro Achítofela Gíloského, Davidova rádce, aby přišel ze svého města Gíla. Spiknutí sílilo a lidu s Abšalómem stále přibývalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'K Davidovi přišel posel se slovy: Srdce Izraelců ⌈je nakloněno Abšalómovi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'David řekl všem svým otrokům, kteří s ním byli v Jeruzalémě: Vstaňte a utečme, nebo nebudeme moci uniknout před Abšalómem. Rychle pojďme, jinak si pospíší, dostihne nás, přivede na nás zlo a vybije město ostřím meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Královi otroci králi odpověděli: ⌈Jak si přeje můj⌉ pán a král, hle, jsme tvoji otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Král ⌈a celý jeho dům odešel pěšky.⌉ Král však zanechal deset konkubín, aby pečovaly o dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Král a všechen lid odešel pěšky a zastavili se u posledního domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Všichni jeho otroci procházeli kolem něj; všichni Keretejci, všichni Peletejci a všichni Gaťané, šest set mužů, kteří ⌈šli pěšky⌉ z Gatu, procházeli před králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Král se zeptal Itaje Gatského: Proč bys šel s námi také ty? Vrať se a zůstaň s králem. Vždyť jsi cizinec, i ty jsi vystěhovalec ⌈ze svého domova.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Včera jsi přišel, a dnes tě mám nutit jít s námi? ⌈Jdu, ani nevím kam.⌉ Vrať se a vezmi s sebou své bratry. ⌈Milosrdenství a věrnost⌉ ať je s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Itaj králi odpověděl: Jakože živ je Hospodin a jakože živ je můj pán a král, tam, kde bude můj pán a král, ať umírat či žít, tam bude i tvůj otrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David řekl Itajovi: Jdi tedy dál. Šel pak Itaj Gatský a všichni jeho muži i všechny malé děti, které byly s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Celá země hlasitě plakala, když všechen lid procházel. I král přešel ⌈potok Kidrón⌉ a všechen lid šel směrem do pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, '⌈A hle, Sádok a všichni lévité, kteří byli s ním, nesli⌉ truhlu Boží smlouvy. Když Boží truhlu postavili, Ebjátar přinášel oběti, dokud všechen lid nevyšel z města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Král řekl Sádokovi: Dones Boží truhlu zpět do města. Jestliže naleznu milost v Hospodinových očích, přivede mě zpět a ukáže mi ji i svůj příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Jestliže však řekne: Nemám v tobě zalíbení, zde jsem, ať se mnou učiní, co ⌈je mu libo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Král dále knězi Sádokovi řekl: Podívej se, jen se vrať v pokoji do města a tvůj syn Achímaas a Jónatan, syn Ebjátarův, oba vaši synové ať se vrátí s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Podívejte se, já se budu zdržovat u ⌈stepních brodů,⌉ dokud od vás nepřijde zpráva, kterou byste mi oznámili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Sádok a Ebjátar donesli Boží truhlu zpět do Jeruzaléma a pobývali tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David pak vystupoval po svahu Olivové hory, vystupoval a plakal; hlavu měl zakrytou a šel bosý. Všechen lid, který byl s ním, všichni si zakryli hlavu, vystupovali vzhůru a při tom plakali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Davidovi bylo oznámeno, že Achítofel je mezi spiklenci s Abšalómem. Nato David řekl: Změň, prosím, Achítofelovu radu v bláznovství, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'I stalo se, že když David přišel na vrchol hory, kde se lidé klanějí Bohu, hle, šel mu naproti Chúšaj Arkijský s roztrženým rouchem a prstí na hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'David mu řekl: Jestliže půjdeš dál se mnou, budeš mi břemenem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Ale když se vrátíš do města a řekneš Abšalómovi: Budu tvým otrokem, králi; dříve jsem byl otrokem tvého otce, nyní budu tvým otrokem -- tehdy budeš moci zmařit Achítofelovu radu ⌈v můj prospěch.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Vždyť tam s tebou budou kněží Sádok a Ebjátar. ⌈Všechno, co⌉ se doslechneš z královského domu, oznam kněžím Sádokovi a Ebjátarovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'A jsou tam s nimi jejich dva synové, Sádokův Achímaas a Ebjátarův Jónatan. Vzkažte mi po nich všechno, co se doslechneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Davidův přítel Chúšaj přišel do města. Také Abšalóm přišel do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Když David přešel kousek za vrchol, hle, šel mu vstříc Síba, služebník Mefíbóšetův, s osedlaným oslím spřežením a na něm bylo dvě stě chlebů, sto ⌈sušených hroznů,⌉ sto ⌈ plodů letního ovoce⌉ a měch vína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Král se zeptal Síby: Na co to máš? Síba odpověděl: Osli jsou na jízdu pro královský dům, chléb a letní ovoce, aby mohli služebníci pojíst, a víno, aby se mohli napít unavení v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Král se dále zeptal: A kde je syn tvého pána? Síba králi odpověděl: Právě pobývá v Jeruzalémě. Řekl si totiž: Dnes mi dům izraelský vrátí království mého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Král řekl Síbovi: Hle, tvé je všechno, co patřilo Mefíbóšetovi. Síba odpověděl: Klaním se. Kéž naleznu milost ve tvých očích, můj pane a králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Když přišel král David k Bachurímu, právě odtamtud vycházel muž z čeledi domu Saulova jménem Šimeí, syn Gérův. Šel a přitom pronášel kletby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Házel kameny na Davida a na všechny otroky krále Davida, ačkoliv ⌈všechen lid⌉ a všichni hrdinové byli po jeho pravici i levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Při proklínání Šimeí volal toto: Táhni, táhni, ⌈krvelačný ničemníku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Hospodin ⌈ti odplatil⌉ za všechnu krev domu Saulova, na jehož místě kraluješ. Hospodin dal království do ruky tvého syna Abšalóma. Zde jsi ve svém trápení, protože jsi krvelačný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Abíšaj, syn Serújin, řekl králi: Proč by měl tento ⌈mrtvý pes⌉ proklínat mého pána a krále? Půjdu a srazím mu hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Král odpověděl: ⌈Co je vám do mě,⌉ synové Serújini? On proklíná, protože mu Hospodin řekl: Proklínej Davida, a kdo se může ptát: Proč to děláš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'David řekl Abíšajovi a všem svým otrokům: Vždyť i můj syn, který vzešel z mého nitra, usiluje o můj život. Čím spíše tento Benjamínec. Nechte ho být, ať proklíná, když mu to řekl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Snad Hospodin pohlédne na mé soužení a odplatí mi za jeho dnešní kletbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'David se svými muži šel dále svou cestou, zatímco Šimeí šel ⌈podél něj⌉ po svahu hory, stále proklínal a házel ⌈po něm⌉ kameny a hlínu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Král a všechen lid, který byl s ním, přišel vyčerpaný k Jordánu a tam si oddechli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Abšalóm i všechen lid, všichni Izraelci, přišli do Jeruzaléma; také Achítofel byl s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Stalo se, že když Davidův přítel Chúšaj Arkijský přišel k Abšalómovi, řekl Chúšaj Abšalómovi: ⌈ Ať žije král,⌉ ať žije král!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Abšalóm se zeptal Chúšaje: To je oddanost tvému příteli? Proč jsi nešel se svým přítelem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Chúšaj Abšalómovi odpověděl: Nikoli. Koho vyvolil Hospodin a tento lid, všichni Izraelci, ⌈s tím budu,⌉ s ním zůstanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, '⌈Komu jinému bych⌉ měl sloužit? Cožpak ne jeho synu? Jako jsem sloužil tvému otci, tak budu sloužit tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Abšalóm řekl Achítofelovi: Poraďte se, co máme dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Achítofel Abšalómovi odpověděl: Vejdi ke konkubínám svého otce, které ponechal, aby pečovaly o dům. Když celý Izrael uslyší, že ses znelíbil svému otci, posilní se ruce všech, kteří jsou s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Postavili Abšalómovi na střeše stan a Abšalóm vešel před očima celého Izraele ke konkubínám svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, '⌈Rada, kterou dal Achítofel,⌉ bývala v oněch dnech, jako když se někdo doptává na Boží slovo. Tak byla vážena každá Achítofelova rada jak Davidem, tak i Abšalómem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Achítofel dále Abšalómovi řekl: Dovol, abych vybral dvanáct tisíc mužů; povstanu a budu této noci pronásledovat Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, '⌈Přiženu se na něj,⌉ dokud je unavený a má malátné ruce. Vyděsím ho, takže všechen lid, který je s ním, uteče, a zabiju samotného krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'A všechen lid přivedu zpět k tobě. ⌈Ten, kterého usiluješ zabít, je jako návrat všech mužů.⌉ Všechen lid bude mít pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, '⌈Abšalómovi i všem izraelským starším se to líbilo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Abšalóm však řekl: Zavolejte také Chúšaje Arkijského. Poslechneme si, co řekne ještě on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Když přišel Chúšaj k Abšalómovi, Abšalóm mu řekl: Achítofel promluvil tak a tak. Máme ⌈udělat, co řekl?⌉ Pokud ne, mluv ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Chúšaj Abšalómovi odpověděl: Rada, kterou dal Achítofel, není tentokrát dobrá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Chúšaj dále řekl: Ty znáš svého otce i jeho muže, že jsou to hrdinové. ⌈Jsou rozhořčení⌉ jako medvědice na poli připravená o mláďata. Tvůj otec je bojovník, nebude nocovat s lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Hle, skrývá se teď ⌈v nějaké roklině⌉ či ⌈na nějakém jiném místě.⌉ ⌈ Kdyby se stalo, že by někdo z nich padl na počátku,⌉ ⌈ten, kdo to uslyší, si řekne:⌉ ⌈Lid, který jde za Abšalómem, utrpěl porážku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Pak i takový bojovník, který ⌈ je odvážný jako lev,⌉ jistě ochabne. Vždyť celý Izrael ví, že tvůj otec je hrdina a ⌈jsou s ním bojovníci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Proto radím, aby se k tobě shromáždil celý Izrael od Danu až po Beer–šebu, takové množství jako ⌈písku v moři,⌉ a ⌈ty sám⌉ táhni do bitvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Vytáhneme proti němu na nějaké z míst, kde se mohou nacházet, spočineme na něm, jako když rosa padá na zemi, a nezůstane ⌈on ani nikdo ze všech mužů, kteří jsou s ním.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Když se stáhne do města, všichni Izraelci přinesou k tomu městu provazy a odvlečou ho do údolí, ⌈až tam nebude⌉ ani kamínek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Abšalóm a všichni izraelští muži řekli: Rada Chúšaje Arkijského je lepší nežli rada Achítofelova. Tak Hospodin přikázal zmařit dobrou Achítofelovu radu, aby Hospodin přivedl na Abšalóma zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Chúšaj řekl kněžím Sádokovi a Ebjátarovi: Tak a tak radil Abšalómovi a izraelským starším Achítofel, tak a tak jsem radil já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Teď rychle vzkažte a oznamte Davidovi: Nezůstávej přes noc ⌈v pustých stepích,⌉ ale určitě ⌈jdi dál.⌉ Jinak bude pohlcen král i všechen lid, který je s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jónatan a Achímaas zůstali v Én–rogelu. Služka tedy šla a oznámila jim to. Oni pak šli, aby to oznámili králi Davidovi, neboť nemohli přijít a ukázat se ve městě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Uviděl je však nějaký chlapec a oznámil to Abšalómovi. Ti dva rychle šli a vstoupili do domu nějakého muže v Bachurímu, který měl na dvoře studnu. ⌈Vlezli do ní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Žena vzala přikrývku, rozprostřela ji na vrch studny a rozházela na ni zrna, takže nic nebylo znát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Abšalómovi otroci přišli domů k ženě a zeptali se: Kde je Achímaas a Jónatan? Žena jim odpověděla: ⌈Šli dál k zásobárně vody.⌉ Hledali je, ale nenašli, a tak se vrátili do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Stalo se, že potom, co odešli, vylezli muži ze studny, šli a oznámili to králi Davidovi. Řekli Davidovi: Vstaňte a přejděte rychle přes vodu, protože Achítofel radil takto proti vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'David a všechen lid, který byl s ním, vstal a přešel přes Jordán. Do svítání nechyběl ani jeden, kdo by nepřešel přes Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Když Achítofel viděl, že jeho rada nebyla vykonána, osedlal osla, vstal a šel domů do svého města. Dal příkazy ohledně svého domu a oběsil se. Zemřel a byl pohřben do hrobu svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David přišel do Machanajimu. Abšalóm přešel přes Jordán a s ním všichni izraelští muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Abšalóm ustanovil namísto Jóaba nad armádou Amasu. Amasa byl synem muže jménem Jitra Izraelský, který vešel k Abígale, dceři Náchašově, sestře Jóabovy matky Serúji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Izraelci s Abšalómem se utábořili v gileádské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Stalo se, že když přišel David do Machanajimu, přišli Šóbi, syn Náchašův, z Raby synů Amónových, Makír, syn Amíelův, z Lódebaru, a Barzilaj Gileádský z Rogelímu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'a toto vše -- lože, číše, hliněné nádoby, i pšenici, ječmen, mouku, pražené zrní, fazoli, čočku, pražené zrní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'i med, máslo, ovce a ⌈kravský sýr⌉ -- přinesli Davidovi a lidu, který byl s ním, aby mohli pojíst, protože si řekli: Lid je v pustině hladový, vyčerpaný a žíznivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'David spočítal lid, který byl s ním, a ustanovil nad nimi velitele nad tisíci a velitele nad sty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'David rozdělil lid takto: Třetinu ⌈pod velení⌉ Jóaba, třetinu pod velení Abíšaje, syna Serújina, bratra Jóabova, a třetinu pod velení Itaje Gatského. Král řekl lidu: Také já s vámi vytáhnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Lid řekl: Netáhni. Kdybychom museli utíkat, ⌈nebudou si nás všímat.⌉ I kdyby nás polovina zemřela, ⌈nebudou si nás všímat.⌉ Neboť ty jsi za deset tisíc z nás. Bude nyní lepší, když nám budeš ⌈na pomoc jako záloha⌉ z města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Král jim řekl: Učiním, co ⌈vám připadá nejlepší.⌉ Král se postavil u brány a všechen lid vycházel po stech a po tisících.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Král přikázal Jóabovi, Abíšajovi a Itajovi: Zacházejte ⌈kvůli mně⌉ s mládencem Abšalómem mírně. Všechen lid slyšel, co král přikázal všem velitelům ohledně Abšalóma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Lid vytáhl do pole proti Izraeli. V Efrajimském lese pak došlo k boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Izraelský lid tam byl od Davidových otroků poražen. V onen den tam došlo k velké porážce, padlo jich dvacet tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Boj se tam rozšířil po celém povrchu země a les onoho dne pohltil více lidu než požral meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Abšalóm se potkal s Davidovými otroky. Abšalóm jel na mezku. Když vjel mezek pod spleť větví velkého terebintu, jeho hlava se zachytila v terebintu a on se ocitl mezi nebem a zemí. Mezek, který byl pod ním, jel dál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Uviděl to nějaký muž a oznámil to Jóabovi: Viděl jsem Abšalóma viset na terebintu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Jóab se zeptal muže, který mu to oznámil: Když jsi ho viděl, tak proč jsi ho tam nesrazil k zemi? Dal bych ti deset šekelů stříbra a jeden pás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Ten muž však Jóabovi odpověděl: I kdyby mi bylo odváženo na ruku tisíc šekelů stříbra, nevztáhl bych ruku na královského syna. Vždyť ⌈jsme slyšeli, jak ⌉ král přikázal tobě, Abíšajovi a Itajovi: Zachovejte kvůli mně mládence Abšalóma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Kdybych ⌈ho podvedl,⌉ nic se před králem neskryje a ty bys stál stranou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Jóab řekl: Nebudu na tebe čekat. Vzal do ruky tři hole a vrazil je Abšalómovi do srdce, neboť byl uprostřed terebintu ještě živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Deset služebníků, Jóabových zbrojnošů, ho obklopilo a bili Abšalóma, až ho usmrtili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Jóab zatroubil na beraní roh a lid přestal Izraelce pronásledovat, protože Jóab lid zadržel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Vzali Abšalóma, hodili ho v lese do velké jámy a postavili na něj velmi velkou hromadu kamení. Všichni Izraelci utekli, každý ke svému stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Abšalóm pro sebe za svého života vzal a postavil sloup, který je v Údolí králů. Řekl si totiž: Nemám syna, díky němuž by bylo připomínáno mé jméno, a nazval ten sloup svým jménem. Dodnes se nazývá Abšalómův pomník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Achímaas, syn Sádokův, řekl: Poběžím a přinesu králi dobrou zprávu, že Hospodin mu zjednal právo vůči jeho nepřátelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Jóab mu nato řekl: Dnes nebudeš nosi telem dobré zprávy. Dobrou zprávu přines v jiný den. Dnes ji nezvěstuj, protože zemřel králův syn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Jóab řekl Kúšijci: Jdi a oznam králi, co jsi viděl. Kúšijec se před Jóabem poklonil a běžel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Achímaas, syn Sádokův, však pokračoval dál a řekl Jóabovi: Ať se stane, co se stane, ⌈také já poběžím⌉ za Kúšijcem. Jóab se zeptal: Nač bys běžel, můj synu? Nemáš dobrou zprávu, ⌈ abys něco získal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Ať se stane, co se stane, poběžím. Řekl mu: Tak běž! Achímaas běžel Jordánskou rovinou a předběhl Kúšijce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David seděl mezi dvěma branami. Strážný šel na střechu brány, na hradbu. Pozvedl oči a uviděl, že běží samotný muž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Strážný zavolal a oznámil to králi. Král řekl: Jestliže je sám, má dobrou zprávu. Postupoval a stále se blížil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Potom strážný uviděl, jak běží jiný muž. Strážný zavolal na vrátného: Podívej, běží samotný muž. Král řekl: I to je nositel dobré zprávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Strážný řekl: Vidím, že ⌈první běžec běží jako⌉ Achímaas, syn Sádokův. Král řekl: To je dobrý muž, přichází s dobrou zprávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Achímaas zvolal a řekl králi: Pokoj tobě. Poklonil se před králem tváří k zemi a řekl: Požehnaný je Hospodin, tvůj Bůh, jenž vydal ty, kteří pozvedli svou ruku proti mému pánu a králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Král se zeptal: Jak se daří mládenci Abšalómovi? Achímaas odpověděl: Když ⌈Jóab posílal králova otroka a mě, tvého otroka,⌉ viděl jsem velký dav, ale nevím, co to bylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Král řekl: Odstup a postav se sem. Odstoupil a zůstal stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Vtom přišel Kúšijec a řekl: Ať můj pán a král přijme dobrou zprávu, že Hospodin ti dnes zjednal právo vůči všem, kteří proti tobě povstali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Král se Kúšijce zeptal: Jak se daří mládenci Abšalómovi? Kúšijec odpověděl: Ať nepřátelé mého pána a krále i všichni, kdo povstali proti tobě ke zlému, dopadnou jako ten mládenec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Král byl otřesen, vstoupil do horní místnosti nad bránou, plakal, a jak šel, říkal: Můj synu Abšalóme, můj synu, můj synu Abšalóme. ⌈Kdybych tak mohl ⌉ zemřít namísto tebe, Abšalóme, můj synu, můj synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Jóabovi bylo oznámeno: Hle, král pláče a truchlí nad Abšalómem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Tak se záchrana v onen den změnila pro všechen lid ve smutek, neboť lid v onen den slyšel, že král se trápí nad svým synem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Lid se přikradl v onen den a vešel do města, jako se vkrádá lid, který se stydí, že utekl z boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Král skryl svou tvář a hlasitě naříkal: Můj synu Abšalóme, Abšalóme, můj synu, můj synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Jóab přišel domů ke králi a řekl: Zahanbil jsi dnes tvář všech svých otroků, kteří dnes zachránili život tvůj i život tvých synů a tvých dcer, život tvých žen a život tvých konkubín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Miluješ totiž ty, kdo tě nenávidí, a nenávidíš ty, kdo tě milují. Dnes jsi dokázal, že máš velitele a otroky za nic. Dnes vím, že kdyby byl Abšalóm živ a my všichni bychom byli dnes mrtvi, tak ⌈by ti to připadalo správné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Teď však vstaň, vyjdi a ⌈promluv k srdci⌉ svých otroků. Přísahám při Hospodinu, že nevyjdeš–li, nikdo s tebou přes noc ne zůstane a bude to pro tebe větší zlo nežli všechno to zlo, které na tebe přišlo od tvého mládí až doteď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Král tedy vstal a posadil se v bráně. Všemu lidu bylo oznámeno: Hle, král sedí v bráně a všechen lid přišel před krále. Izraelci však utekli, všichni ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Všechen lid ve všech izraelských kmenech se dohadoval; říkali: Král nás vysvobodil z ruky nepřátel, on nás zachránil z ruky Pelištejců. Nyní utekl ze země před Abšalómem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Avšak Abšalóm, kterého jsme nad sebou pomazali, zemřel v boji. Proč nyní mlčíme a ne přivedeme krále zpět?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Král David vzkázal kněžím Sádokovi a Ebjátarovi: Promluvte k judským starším slovy: Proč byste měli být poslední, kdo přivede krále zpět do jeho paláce? Záměr celého Izraele se totiž dostal domů ke králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Jste moji bratři, má kost a mé tělo. Proč byste měli být poslední, kdo přivedou krále zpět?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Amasovi pak řekněte: Což nejsi má kost a mé tělo? Tak ať mi učiní Bůh a ještě přidá, jestliže nebudeš ⌈ po všechny dny⌉ mým velitelem armády namísto Jóaba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Tak si naklonil srdce ⌈všech Judejců,⌉ jako by byli jeden muž, takže vzkázali králi: Vrať se ty i všichni tvoji otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Král se tedy vracel a přišel k Jordánu. Judejci přišli do Gilgálu a šli králi naproti, aby krále převedli přes Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Šimeí, syn Gérův, Benjamínec z Bachurímu, si pospíšil a sestoupil s Judejci naproti králi Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Bylo s ním tisíc mužů z Benjamína i Síba, služebník Saulova domu, a s ním patnáct jeho synů a dvacet jeho otroků. ⌈Dostali se k Jordánu⌉ před králem a');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'přešli brod, aby převedli královskou rodinu a udělali, co ⌈mu libo.⌉ Šimeí, syn Gérův, padl před králem, když chtěl přejít přes Jordán,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'a řekl králi: Ať můj pán ⌈nezamýšlí proti mně trest.⌉ Nevzpomínej na to, co zlého spáchal tvůj otrok v den, kdy můj pán a král vycházel z Jeruzaléma. Ať ⌈si to král nebere k srdci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Vždyť ⌈tvůj otrok ví,⌉ že jsem zhřešil. Pohleď, přišel jsem dnes z celého domu Josefova první, abych vyšel svému pánu a králi naproti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Abíšaj, syn Serújin, na to pověděl: Což nemá být Šimeí usmrcen za to, že proklínal Hospodinova pomazaného?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'David ale řekl: Co ⌈ je vám do mě, synové⌉ Serújini? ⌈Stanete se dnes mými protivníky?⌉ Dnes by měl být někdo v Izraeli usmrcen? Já přece vím, že dnes jsem se stal králem nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Pak řekl král Šimeímu: Nezemřeš. A král mu přísahal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'I Mefíbóšet, syn Saulův, vyšel králi naproti. Nepečoval o své nohy, neupravoval vous ani nepral své šaty ode dne, kdy král odešel, až do dne, kdy se v pokoji vrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'I stalo se, že když přišel do Jeruzaléma králi naproti, král se ho zeptal: Proč jsi nešel se mnou, Mefíbóšete?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'On odpověděl: Můj pane a králi, můj otrok mě podvedl. Tvůj otrok ⌈řekl: Osedlám si⌉ osla, pojedu na něm a půjdu s králem. Vždyť tvůj otrok je chromý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Ale Síba pomluvil tvého otroka mému pánu a králi. Můj pán a král je jako Boží anděl, dělej, ⌈co je ti libo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Vždyť ⌈celý dům mého otce byl hoden smrti⌉ od mého pána a krále. Ale ty jsi svého otroka určil mezi ty, kdo jedí u tvého stolu. ⌈Jaký bych měl mít další nárok⌉ volat ještě o pomoc ke králi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Král mu řekl: ⌈Proč bys ještě mluvil o svých záležitostech?⌉ Říkám, že ty a Síba si rozdělíte pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Mefíbóšet králi řekl: Ať si vezme klidně všechno. Hlavně, že se můj pán a král vrátil v pokoji domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'I Barzilaj Gileádský přišel z Rogelímu, ⌈přešel s králem přes Jordán, aby ho za Jordánem opustil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Barzilaj byl velmi starý, bylo mu osmdesát let. On pečoval o krále za jeho dočasného pobytu v Machanajimu, protože byl velmi zámožný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Král řekl Barzilajovi: Pojď se mnou a budu o tebe pečovat u sebe v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Barzilaj nato králi řekl: ⌈Jak dlouho budu živ,⌉ abych šel s králem do Jeruzaléma?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Je mi dnes osmdesát let. Což mohu rozeznat dobré od zlého? Může tvůj otrok vychutnat to, co jí, a to, co pije? Uslyší ještě hlas zpěváků a zpěvaček? Proč by měl tvůj otrok být ještě mému pánu a králi břemenem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Jen kousek půjde tvůj otrok s králem za Jordán. Proč by se mi král měl odplatit takovou odměnou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Dovol, ať se tvůj otrok vrátí, abych zemřel ve svém městě, ⌈kde je hrob⌉ mého otce a mé matky. Ale zde je tvůj otrok Kimhám. Ať jde s mým pánem a králem. Pro něj učiň, co ⌈je ti libo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Král řekl: Ať jde Kimhám se mnou. Já pro něj udělám, co ⌈ je ti libo.⌉ Učiním pro tebe všechno, co si ode mě přeješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Všechen lid přešel přes Jordán, i král přešel. Nato král Barzilaje políbil, požehnal mu a on se vrátil ⌈do svého domova.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Král šel dál do Gilgálu a Kimhám šel s ním. I všechen lid judský doprovázel krále a také polovina lidu izraelského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Vtom přišli ke králi všichni Izraelci a zeptali se krále: Proč tě naši bratři Judejci ukradli a převedli přes Jordán krále, jeho rodinu a s ním všechny Davidovy muže?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Všichni Judejci Izraelcům odpověděli: Vždyť král je náš příbuzný. Proč jste se kvůli tomu tak rozzlobili? Což jsme krále vyjedli? Nebo jsme si něco nepatřičně přivlastnili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 44, 'Izraelci Judejcům odpověděli: Máme u krále deset podílů. A také ⌈na Davida máme větší nárok než vy.⌉ Proč jste nás znevážili? Nemluvili jsme my první o tom, že přivedeme zpět svého krále? Řeč Judejců však byla tvrdší nežli řeč Izraelců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Naskytl se tam ničemník jménem Šeba, syn Bichrího, Benjamínec. Ten zatroubil na beraní roh a volal: Nemáme podíl v Davidovi ani dědictví v synu Jišajovu. Všichni ke svým stanům, Izraelci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Všichni Izraelci přešli od Davida k Šebovi, synu Bichrího, kdežto Judejci od Jordánu až k Jeruzalému se přidrželi svého krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'David přišel domů do Jeruzaléma. Král vzal deset konkubín, které ponechal, aby pečovaly o dům, a dal je do ⌈domu, kde je hlídala stráž.⌉ Pečoval o ně, ale nevešel k nim. Byly zadržovány až do dne své smrti, ⌈žily jako vdovy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Král řekl Amasovi: Za tři dny svolej ke mně Judejce a ty sám se sem dostav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Amasa tedy šel svolat Judejce, ale zmeškal čas, který mu určil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'David řekl Abíšajovi: Šeba, syn Bichrího, ⌈bude vůči nám nyní jednat hůř⌉ nežli Abšalóm. Vezmi ⌈otroky svého pána⌉ a pronásleduj ho. Jinak si najde opevněná města a ⌈zmizí nám z očí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Vytáhli za ním Jóabovi muži, Keretejci, Peletejci a všichni hrdinové. Vytáhli z Jeruzaléma pronásledovat Šebu, syna Bichrího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Když byli u velkého kamene, který je v Gibeónu, šel ⌈proti nim⌉ Amasa. Jóab měl přepásané odění na svůj oděv a na něm pás a meč v pochvě připevněný na bedrech. Když šel, meč vypadl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Jóab se Amasy zeptal: Jak se ti daří, můj bratře? Přitom Jóab uchopil pravou rukou Amasu za vousy, aby ho políbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa nedával pozor na meč v Jóabově ruce. Ten mu ho vrazil do břicha, takže jeho vnitřnosti vyhřezly na zem. Druhou ránu nepotřeboval a zemřel. Jóab a jeho bratr Abíšaj potom pronásledovali Šebu, syna Bichrího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Nad Amasou stál jeden z Jóabových služebníků a řekl: Kdo chce za Jóabem a kdo za Davidem, ať jde za Jóabem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa se válel v krvi uprostřed silnice. Ten muž viděl, že všechen lid zastavuje. Přenesl Amasu ze silnice na pole a hodil na něj roucho, protože viděl, že každý, kdo prochází kolem něj, se zastaví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Jakmile byl odstraněn ze silnice, šel každý dál za Jóabem pronásledovat Šebu, syna Bichrího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Ten prošel všechny izraelské kmeny až do Abel–bét–maaky. ⌈Všichni Bérejci se shromáždili⌉ a šli také za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Přitáhli a oblehli ho v Abel–bét–maace. Navršili proti městu obléhací násep, který stál proti valu. Všechen lid, který byl s Jóabem, dělal nájezdy, aby svrhl hradby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Nějaká moudrá žena z města zavolala: ⌈Poslyšte, poslyšte,⌉ řekněte Jóabovi: Přistup sem, ⌈ chci si s tebou promluvit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Přistoupil k ní a žena se ho zeptala: Ty jsi Jóab? Odpověděl: Ano, jsem. Řekla mu: Poslyš slova své otrokyně. Řekl: Poslouchám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Řekla: Dříve se říkávalo: Ať se doptávají v Abelu. Tak věc vyřídili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Já patřím k pokojným a věrným v Izraeli. Ty chceš usmrtit město, matku v Izraeli. Proč bys měl pohltit ⌈Hospodinovo dědictví?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Jóab odpověděl: Ať je to ode mě vzdáleno, ať je to vzdáleno, že bych chtěl něco pohltit či zničit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Tak to není, ale nějaký muž z Efrajimského pohoří jménem Šeba, syn Bichrího, pozvedl ruku proti králi Davidovi. Vydejte jej samotného a odtáhnu od města. Žena Jóabovi odpověděla: Hle, jeho hlava ti bude hozena za hradby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Žena přišla ⌈ve své moudrosti⌉ ke všemu lidu, usekli hlavu Šeby, syna Bichrího, a hodili ji Jóabovi. Ten zatroubil na beraní roh a rozešli se od města, každý ke svému stanu. Jóab se vrátil do Jeruzaléma ke králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Jóab byl nad celou izraelskou armádou. Benajáš, syn Jójadův, byl nad Keretejci a Peletejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adorám byl nad nucenými pracemi, Jóšafat, syn Achílúdův, byl kancléřem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Šeja byl písařem, Sádok a Ebjátar kněžími.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Také Íra Jaírský byl Davidovým knězem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Za dnů Davidových byl po tři roky hlad, rok co rok. Proto David hledal Hospodinovu přítomnost. Hospodin řekl: ⌈ Je to kvůli Saulovi a jeho krvelačnému domu,⌉ protože usmrtil Gibeóňany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Král zavolal Gibeóňany a mluvil k nim. (Gibeóňané nejsou ze synů izraelských, nýbrž ze zbytku Emorejců. Synové izraelští jim přísahali, že je nepobijí, Saul je však chtěl pobít, když vzplál horlivostí pro syny izraelské a judské.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'David se Gibeóňanů zeptal: Co mám pro vás udělat a čím si vás mohu usmířit, abyste žehnali Hospodinovu dědictví?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Gibeóňané mu odpověděli: Nechceme stříbro ani zlato od Saula a jeho domu ani nechceme, aby byl někdo v Izraeli usmrcen. Řekl: ⌈Cokoliv řeknete, to pro vás udělám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Řekli králi: Od muže, který nás zničil a zamýšlel nás vyhubit, ⌈abychom nezůstali nikde ⌉ na celém území Izraele --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'ať je nám vydáno sedm mužů z jeho synů a pověsíme je před Hospodinem v Gibeji Saula, ⌈Hospodinova vyvoleného.⌉ Král řekl: Vydám je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Král měl soucit s Mefíbóšetem, synem Jónatanovým, vnukem Saulovým, ⌈kvůli přísaze při Hospodinu,⌉ která byla mezi nimi, mezi Davidem a Jónatanem, synem Saulovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Král vzal dva syny Rispy, dcery Ajovy, které porodila Saulovi, Armóna a Mefíbóšeta, a pět synů Mérab, dcery Saulovy, které porodila Adríelovi, synu Barzilaje Mechólatského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'a dal je do ruky Gibeóňanů. Pověsili je na hoře před Hospodinem a padlo všech sedm spolu. Byli usmrceni v prvních dnech žně, na počátku sklizně ječmene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Rispa, dcera Ajova, vzala pytlovinu, roztáhla si ji na skálu, od počátku žně, dokud nebyla ⌈na ně vylita z nebes voda,⌉ a nedovolila nebeskému ptactvu na nich spočinout ve dne ani polní zvěři v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Davidovi bylo oznámeno, co učinila Rispa, dcera Ajova, konkubína Saulova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'David šel a vzal kosti Saula i kosti jeho syna Jónatana od občanů Jábeše v Gileádu, kteří je ukradli z náměstí v Bét–šanu, kam je pověsili Pelištejci v den, kdy Pelištejci ubili Saula v Gilbóa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Přinesli odtamtud kosti Saula i kosti jeho syna Jónatana a sebrali kosti těch, kdo byli pověšeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Pak pohřbili kosti Saula a jeho syna Jónatana v Sele v zemi Benjamín do hrobu jeho otce Kíše. Když učinili všechno, co král přikázal, potom se Bůh dal pohnout prosbami za zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Znovu došlo k boji Pelištejců s Izraelem. David vytáhl a s ním jeho otroci a bojovali s Pelištejci. David byl unaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Jišbí Benób, který byl z ⌈rodu Refájců,⌉ jehož kopí vážilo tři sta šekelů bronzu a jenž byl přepásán novým mečem, řekl, že ⌈Davida zabije.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Ale Abíšaj, syn Serújin, mu přišel na pomoc. Bil Pelištejce, až ho usmrtil. Tehdy ⌈Davida jeho muži zapřísahali:⌉ Netáhni s námi již do boje, abys nezhasil lampu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Potom se stalo, že došlo znovu k boji s Pelištejci v Góbu. Tehdy Sibekaj Chúšatský ubil Sáfa, který byl z rodu Refájců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Znovu došlo k boji s Pelištejci v Góbu. Elchánan, syn Jaare–Oregíma Betlémského, ubil Goliáše Gatského. Násada jeho kopí byla jako tkalcovské vratidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Znovu došlo k boji v Gatu. Byl tam obrovitý muž. ⌈ Na rukou i na nohou měl po šesti prstech,⌉ celkem dvacet čtyři. Také on se narodil Refájcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Když tupil Izrael, ubil ho Jónatan, syn Davidova bratra Šimey.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Tito čtyři ⌈se narodili Refájcům⌉ v Gatu. Padli rukou Davida a rukou jeho otroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'David pověděl Hospodinu slova této písně v den, kdy jej Hospodin vysvobodil z ruky všech jeho nepřátel i z ruky Saulovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Řekl: Hospodin je má skála a má tvrz, můj vysvoboditel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, '⌈Bůh je má skála,⌉ ⌈v něm mám útočiště;⌉ je můj štít a ⌈roh mé záchrany,⌉ můj nedobytný hrad a mé útočiště. Můj zachránce, zachraňuješ mě před násilím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, '⌈Volal jsem k Hospodinu, jenž je chvályhodný, a byl jsem zachráněn od svých nepřátel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Příboje smrti mě obstoupily, poděsily mě proudy ničemníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Ovinuly mě provazy podsvětí, potkaly mě léčky smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Ve své tísni jsem volal k Hospodinu, volal jsem ke svému Bohu. Ze svého chrámu uslyšel můj hlas, mé volání o pomoc proniklo k jeho uším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Země se zakymácela a zatřásla, zachvěly se základy nebes, zakymácely se, neboť vzplanul hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Z chřípí mu vystupoval dým, z úst stravující oheň, řeřavé uhlí od něj vzplálo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Roztáhl nebesa a sestupoval, pod nohama hustou temnotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Vsedl na cheruba a letěl, vznášel se na křídlech větru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Stánkem kolem sebe učinil temnotu, ⌈spoustu vody,⌉ hustá oblaka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Od záře před ním vzplálo řeřavé uhlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Hospodin zahřměl z nebes, Nejvyšší vydal svůj hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Poslal šípy a rozptýlil je, blesky a přivedl je do zmatku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Ukázaly se mořské toky, byly odhaleny základy světa, Hospodinovou hrozbou, dýchnutím dechu jeho chřípí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Vztáhl ruku z výšiny, uchopil mě a vytrhl mě z mocných vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Vysvobodil mě od mého mocného nepřítele, od těch, kdo mě nenáviděli, kdo byli silnější než já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Vyšli proti mně v den mé pohromy, Hospodin mi však byl oporou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Vyvedl mě do volnosti, vytrhl mě, neboť si mě oblíbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Hospodin mi odplatil podle mé spravedlnosti, odměnil mě podle čistoty mých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Vždyť jsem dbal na Hospodinovy cesty, ⌈nejednal jsem vůči svému Bohu ničemně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Všechna jeho nařízení jsou přede mnou, od jeho ustanovení jsem se neodvrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Byl jsem před ním bezúhonný, měl jsem se na pozoru, ⌈abych se neprovinil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Hospodin mi odplatil podle mé spravedlnosti, podle mé čistoty před jeho zrakem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, '⌈S věrným jednáš věrně,⌉ s bezúhonným člověkem bezúhonně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 's čistým jednáš čistě, se zvráceným ⌈se pouštíš do boje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Nuzný lid zachraňuješ, tvoje oči ⌈ jsou proti povýšeným,⌉ snižuješ je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ty jsi, Hospodine, mé světlo, Hospodin prozařuje mou temnotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'S tebou doženu loupežnou hordu, se svým Bohem přeskočím zeď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Bůh -- jeho cesta je bezúhonná, Hospodinova řeč je přečištěná, on je štítem všem, kteří v něm mají útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Kdo je Bůh kromě Hospodina? Kdo je skálou kromě našeho Boha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Bůh ⌈ je má mocná pevnost,⌉ mou cestu činí bezúhonnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Činí mé nohy podobné laním, staví mě na má návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Učí mé ruce boji, ⌈aby moje paže napjaly⌉ bronzový luk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Dal jsi mi ⌈štít své záchrany,⌉ ⌈tvá pokora mě činí⌉ velkým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, '⌈Činíš pode mnou prostor pro mé kroky,⌉ kotníky se mi nepodvrtnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Pronásledoval jsem své nepřátele, vyhladil jsem je, nepřestal jsem, dokud jsem s nimi ne skoncoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Skoncoval jsem s nimi, udolal jsem je, nepovstanou, padli mi pod nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Přepásal jsi mě udatností k boji, mé protivníky srazíš pode mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Dals mi vidět záda mých nepřátel, těch, kdo mě nenávidí, zničil jsem je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Vyhlíželi pomoc, ale zachránce nebyl, volali k Hospodinu, ale neodpověděl jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Rozdrtil jsem je jako prach země, rozmačkal jsem je a podupal jako bláto na ulicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Vytrhl jsi mě ze sporů mého lidu, zachoval jsi mě jako vůdce národů, lid, který jsem neznal, mi sloužil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, '⌈Podlézali mi⌉ cizinci, jakmile uslyšeli, uposlechli mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Cizinci zvadli, s třesením přišli ze svých pevností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Živ je Hospodin, požehnaná je má skála, vyvýšený je Bůh, ⌈skála mé záchrany,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Bůh, který mi dává pomstu, národy ⌈přivádí pode mě,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'vyvádí mě od mých nepřátel. Nad mé protivníky jsi mě vyvýšil, od násilníka jsi mě vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Proto ti, Hospodine, vzdám chválu mezi národy a budu opěvovat tvé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, '⌈ On je záchrannou věží svému králi,⌉ prokazuje milosrdenství svému pomazanému Davidovi a jeho potomstvu až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Toto jsou poslední Davidova slova: Výrok Davida, syna Jišajova, výrok muže ⌈ustanoveného Bohem,⌉ pomazaného Boha Jákobova, ⌈milého zpěváka písní⌉ Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Hospodinův Duch promluvil skrze mě, jeho řeč je na mém jazyku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Bůh Izraele řekl, skála Izraele ke mně promluvila: Ten, kdo vládne lidem spravedlivě, ten, kdo vládne v bázni před Bohem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'je jako svítání, když vychází slunce, ráno bez oblaků, ⌈od jeho záře po dešti vyrůstá tráva ze země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Není takový můj dům před Bohem? Vždyť se mnou učinil věčnou smlouvu ve všem připravenou a zachovanou. Všechna má záchrana, všechno, po čem toužím -- nezpůsobí on, aby to vyrašilo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Avšak všichni ničemníci jsou jako rozváté trní, neboť ⌈ je nelze vzít do ruky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Kdo se jich chce dotknout, vyzbrojí se železem či násadou kopí. Jistě budou na svém místě spáleni ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Toto jsou jména Davidových hrdinů: Jóšeb Bašebet Tachkemónský, vůdce kapitánů, ⌈který pozvedl své kopí⌉ proti osmi stům, jež naráz pobil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Po něm byl Eleazar, syn Dóda, syna Achóchiova. Byl mezi třemi hrdiny, jež byli s Davidem, když hanobili Pelištejce, kteří se tam shromáždili k boji. Když Izraelci ustupovali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'on vstal a pobíjel Pelištejce, až ⌈se jeho ruka unavila a přilnula k meči.⌉ Hospodin ⌈způsobil v onen den velkou záchranu.⌉ Lid se pak za ním vrátil, jen aby raboval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Po něm byl Šama, syn Ageho Hararského. Pelištejci se shromáždili v houf. Byl tam díl pole plný čočky. Lid před Pelištejci utekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Avšak on se postavil uprostřed toho pole, vysvobodil ho a pobíjel Pelištejce. Hospodin ⌈způsobil velkou záchranu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Tři ze třiceti vůdců sestoupili a přišli ve žni k Davidovi do adulamské jeskyně. Pelištejský houf tábořil v údolí Refájců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David byl tehdy v pevnosti a pelištejská hlídka byla tehdy v Betlémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'David zatoužil a řekl: ⌈Kdyby mi tak někdo dal⌉ napít vody z betlémské studny, která je u brány!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Ti tři hrdinové pronikli do pelištejského tábora, načerpali vodu z betlémské studny, která je u brány, vzali ji a přinesli Davidovi. Nechtěl ji však pít a vylil ji Hospodinu v úlitbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Řekl: Ať je to ode mě vzdáleno, Hospodine, abych učinil něco takového. Což ⌈ smím pít krev⌉ mužů, kteří šli s nasazením vlastního života? A nechtěl ji pít. To učinili ti tři hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abíšaj, bratr Jóabův, syn Serújin, byl vůdcem tří. Zamával svým kopím proti třem stům, jež pobil. Proslavil se mezi těmi třemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Z těch tří byl nejváženější a stal se jejich velitelem, ale ⌈těch tří nedosáhl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benajáš, syn Jójadův, byl bojovník z Kabseelu, který učinil mnoho mocných činů. Ten zabil dva ⌈ syny Aríele Moábského.⌉ On také přišel a ⌈v čase sněhu⌉ ubil lva uvnitř jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Zabil Egypťana, muže ⌈ zvláštního vzhledu.⌉ Egypťan měl v ruce kopí. On k němu přišel s holí, sebral kopí z Egypťanovy ruky a jeho vlastním kopím ho zabil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Tyto činy vykonal Benajáš, syn Jójadův, a proslavil se mezi těmi třemi hrdiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Mezi třiceti byl nejváženější, ale těch tří nedosáhl. David ho ustanovil nad svojí tělesnou stráží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Mezi těmi třiceti byl Asáel, bratr Jóabův, Elchánan, syn Dóda Betlémského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Šama Charódský, Elíka Charódský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Cheles Paltejský, Íra, syn Íkeše Tekójského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abíezer Anatótský, Mebúnaj Chúšatský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Salmón Achóchijský, Mahraj Netófský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Cheleb, syn Baany Netófského, Itaj, syn Ríbaje z Gibeje synů Benjamínových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benajáš Pireatónský, Hidaj z gaašských údolí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abí–albón Arbátský, Azmávet Barchúmský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljachba Šaalbónský, ze synů Jášena, Jónatan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Šama Hararský, Achíam, syn Šárara Hararského');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elífelet, syn Achasbaje, syna Maakaťanova, Elíam, syn Achítofela Gíloského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Chesraj Karmelský, Paaraj Arbejský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigál, syn Nátana ze Sóby, Baní Gádský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Selek Amónský, Nacharaj Beerótský, zbrojnoš Jóaba, syna Serújina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Íra Jitrejský, Gáreb Jitrejský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urijáš Chetejský. Všech bylo třicet sedm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Hospodinův hněv znovu vzplál proti Izraeli a podnítil proti nim Davida slovy: Jdi a spočítej ⌈Izrael a Judu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Král řekl Jóabovi, veliteli vojska, který byl ⌈s ním:⌉ Projdi nyní všechny izraelské kmeny od Danu až po Beer–šebu a spočítej lid, ⌈ať vím, kolik je lidu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Jóab králi řekl: Ať Hospodin, můj Bůh, přidá k lidu stokrát více než je tohoto a oči mého pána a krále to uvidí. Ale proč můj pán a král ⌈chce tuto věc?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Královo slovo však bylo ⌈vůči Jóabovi a vůči velitelům vojska pevné.⌉ A tak vyšel Jóab s veliteli vojska od krále spočítat ⌈izraelský lid.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Přešli Jordán a utábořili se u Aróeru, napravo od města, které je v gádském údolí, směrem k Jaezeru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Přišli do Gileádu, do země Tachtím–chodší. Přišli do Dan–jaanu a do okolí Sidónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Přišli do pevnosti Týru, do všech chivejských a kenaanských měst; došli na jih Judska, do Beer–šeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Prošli celou zemi a po devíti měsících a dvaceti dnech se vrátili do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Jóab udal králi počet sečteného lidu: V Izraeli bylo osm set tisíc bojovníků tasících meč, Judejců bylo pět set tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Avšak ⌈Davida trápilo svědomí⌉ potom, co sečetl lid. David řekl Hospodinu: Velmi jsem zhřešil tím, co jsem učinil. Nyní, Hospodine, odejmi, prosím, vinu svého otroka, neboť jsem jednal velice bláznivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Když David ráno vstal, stalo se Hospodinovo slovo k proroku Gádovi, Davidovu vidoucímu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Jdi a promluv k Davidovi: Toto praví Hospodin: ⌈Předkládám ti⌉ tři věci. Vyber si jednu z nich, ⌈kterou ti mám udělat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gád přišel k Davidovi a oznámil mu to. Zeptal se ho: Má na tebe přijít sedm let hladu ve tvé zemi? Nebo budeš utíkat tři měsíce před svými protivníky, kteří tě budou pronásledovat? Nebo mají nastat tři dny moru ve tvé zemi? Nyní ⌈rozvaž a rozhodni,⌉ co mám odpovědět tomu, kdo mě poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David Gádovi odpověděl: ⌈Jsem ve veliké tísni.⌉ Kéž padneme do Hospodinovy ruky, neboť jeho slitování je velké. Jenom ať nepadnu do ruky člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Hospodin uvedl mor na Izrael, od toho rána až do určeného času, a z lidu od Danu až po Beer–šebu zemřelo sedmdesát tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Když anděl vztáhl svou ruku na Jeruzalém, aby ho ničil, Hospodin litoval zla a řekl andělu, který působil zkázu mezi lidem: Dost. Nyní odtáhni svou ruku. Hospodinův anděl byl u humna Aravny Jebúsejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Když David uviděl anděla, který pobíjel lid, řekl Hospodinu: Hle, já jsem zhřešil, já jsem spáchal zlo. Ale tyto ovce, co provedly? Ať je tvá ruka proti mně a proti domu mého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'V onen den přišel k Davidovi Gád a řekl mu: Jdi a postav Hospodinu oltář na humně Aravny Jebúsejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'David šel podle Gádova slova, jak Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Aravna vyhlédl a uviděl krále i jeho otroky, jak k němu přicházejí. Nato Aravna vyšel a poklonil se králi tváří k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Pak se Aravna zeptal: Proč přišel můj pán a král ke svému otroku? David odpověděl: Abych od tebe koupil humno, postavil Hospodinu oltář a tak byla rána od lidu zadržena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Aravna řekl Davidovi: Ať si můj pán a král vezme a obětuje, co je ⌈mu libo.⌉ Pohleď, skot pro zápalnou oběť i smyky a ⌈dobytčí jha⌉ na dříví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Všechno toto ⌈dal Aravna králi.⌉ Potom Aravna králi řekl: Kéž si tě Hospodin, tvůj Bůh, oblíbí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Ale král řekl Aravnovi: Ne! Chci to od tebe koupit za kupní cenu. Nepřinesu Hospodinu, svému Bohu, zápalné oběti zadarmo. A David to humno a ten skot koupil za padesát šekelů stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'David tam postavil Hospodinu oltář a přinesl zápalné a pokojné oběti. Pak ⌈se Hospodin dal pohnout prosbami za zemi⌉ a rána byla od Izraele zadržena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Král David zestárl, ⌈dosáhl pokročilého věku.⌉ Přikryli ho rouchy, ale nemohl se zahřát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Jeho otroci mu řekli: Ať vyhledají mému pánu a králi dívku, pannu; ⌈ať slouží králi⌉ a je jeho opatrovnicí. Ať leží ve tvém klíně a můj pán a král se zahřeje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Hledali tedy po celém izraelském území krásnou dívku. Nalezli Abíšagu Šúnemitskou a přivedli ji ke králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Ta dívka byla převelice krásná. Stala se královou opatrovnicí, sloužila mu, ale král ⌈ji nepoznal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adónijáš, syn Chagítin, se vynášel slovy: Já budu kralovat. Pořídil si vozy, jezdce a padesát mužů, kteří běhali před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Jeho otec ho ⌈v životě⌉ nepokáral slovy: Proč jsi tohle provedl? Navíc byl velmi hezkého vzezření. Narodil se po Abšalómovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Domluvil se s Jóabem, synem Serújiným, a s knězem Ebjátarem, a ti Adónijášovi napomáhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Ale kněz Sádok, Benajáš, syn Jójadův, prorok Nátan, Šimeí a Reí i Davidovi hrdinové nebyli s Adónijášem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Adónijáš obětoval brav, skot a vykrmené dobytče u Eben–zócheletu, který je blízko Én–rogelu, a pozval všechny své bratry, královské syny, i všechny judské muže, královské otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Ale proroka Nátana, Benajáše, hrdiny ani svého bratra Šalomouna nepozval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Nátan řekl Bat–šebě, matce Šalomounově: Slyšelas, že Adónijáš, syn Chagítin, se stal králem? A náš pán David o tom neví!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, '⌈Nuže, dobře ti radím,⌉ zachraň život svůj i život svého syna Šalomouna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Jdi, ⌈a až přijdeš⌉ ke králi Davidovi, řekni mu: Ty jsi přece, můj pane a králi, přísahal své otrokyni slovy: Tvůj syn Šalomoun bude kralovat po mně, on usedne na můj trůn. Proč se stal králem Adónijáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'A když tam ještě budeš mluvit s králem, přijdu za tebou a potvrdím tvá slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Bat–šeba tedy vešla ke králi do pokoje. (Král velice zestárl a Abíšag Šúnemitská sloužila králi.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Bat–šeba poklekla a klaněla se králi. Král se zeptal: Co ⌈ je s tebou?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Odpověděla mu: Můj pane! Ty jsi své otrokyni přísahal při Hospodinu, svém Bohu: Tvůj syn Šalomoun bude kralovat po mně, on usedne na můj trůn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Ale nyní, pohleď, Adónijáš se stal králem a ty, můj pane a králi, o tom nevíš!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Obětoval množství skotu, vykrmeného dobytka a bravu, pozval všechny královské syny, kněze Ebjátara a velitele armády Jóaba, ale tvého otroka Šalomouna nepozval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'A nyní, můj pane a králi, oči všech Izraelců jsou upřeny na tebe, abys jim oznámil, kdo usedne na trůn mého pána a krále po něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Jinak se stane, až můj pán a král ulehne ⌈se svými⌉ otci, že já a můj syn Šalomoun budeme považováni za hříšníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Ještě když mluvila s králem, přišel prorok Nátan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Oznámili králi: Je zde prorok Nátan. Přišel před krále a poklonil se před králem tváří k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Nátan se zeptal: Můj pane a králi, ty jsi řekl: Adónijáš bude kralovat po mně, on usedne na můj trůn?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Neboť dnes sestoupil, aby obětoval množství skotu, vykrmeného dobytka a bravu, a pozval všechny královské syny, velitele armády a kněze Ebjátara. A teď jedí a pijí před ním a volají: Ať žije král Adónijáš!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Ale mě, tvého otroka, kněze Sádoka, Benajáše, syna Jójadova, ani tvého otroka Šalomouna nepozval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Stala se tato věc od mého pána a krále, aniž bys ⌈svým otrokům⌉ oznámil, kdo usedne na trůn mého pána a krále po něm?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Král David odpověděl: Zavolejte mi Bat–šebu! Přišla před krále a stála před králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Potom král přísahal: Jakože živ je Hospodin, který vykoupil mou duši z každého soužení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'tak jako jsem ti přísahal při Hospodinu, Bohu Izraele, slovy: Tvůj syn Šalomoun bude kralovat po mně, on usedne na můj trůn místo mě, tak dnes učiním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Bat–šeba poklekla s tváří k zemi, klaněla se králi a řekla: Ať žije můj pán a král David navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Nato král David řekl: Zavolejte mi kněze Sádoka, proroka Nátana a Benajáše, syna Jójadova. I přišli před krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Král jim řekl: Vezměte s sebou otroky svého pána, mého syna Šalomouna posaďte na mou mezkyni a přiveďte ho dolů ke Gichónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Tam ať ho kněz Sádok a prorok Nátan pomažou za krále nad Izraelem. Nato zatrubte na beraní roh a volejte: Ať žije král Šalomoun!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Pak vystupte za ním a on ať jde a usedne na můj trůn, on bude kralovat místo mě. Jej jsem ustanovil, aby byl vévodou nad Izraelem a Judou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Benajáš, syn Jójadův, králi odpověděl: Amen. Tak ať promluví Hospodin, Bůh mého pána a krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Jako byl Hospodin s mým pánem a králem, tak ať je s Šalomounem a ať vyvýší jeho trůn nad trůn mého pána a krále Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Kněz Sádok, prorok Nátan, Benajáš, syn Jójadův, a Keretejci i Peletejci sestoupili, posadili Šalomouna na mezkyni krále Davida a přivedli ho ke Gichónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Kněz Sádok vzal ze stanu roh s olejem a Šalomouna pomazal. Nato zatroubili na beraní roh a všechen lid volal: Ať žije král Šalomoun!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Všechen lid šel vzhůru za ním, lid hrál na flétny a převelice se radoval, až země jejich halasem pukala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Uslyšel to Adónijáš a všichni pozvaní, kteří byli s ním a už dojedli. Když Jóab uslyšel zvuk beraního rohu, zeptal se: Proč je ⌈ve městě takový velký halas?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Ještě když mluvil, přišel Jónatan, syn kněze Ebjátara. Adónijáš řekl: Pojď, vždyť jsi oddaný muž, jistě přinášíš dobrou zprávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Ale Jónatan Adónijášovi odpověděl: Kdepak, náš pán a král David ustanovil králem Šalomouna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Král s ním poslal kněze Sádoka, proroka Nátana, Benajáše, syna Jójadova, a Keretejce i Peletejce, posadili ho na královu mezkyni');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'a kněz Sádok a prorok Nátan ho pomazali v Gichónu za krále. Pak odtamtud šli radostně vzhůru a celé město se shluklo. To je ten halas, který jste slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Šalomoun již usedl na královský trůn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'A královi otroci již přišli poblahopřát našemu pánu a králi Davidovi slovy: Ať Bůh učiní jméno Šalomounovo větším nad tvé jméno a vyvýší jeho trůn nad tvůj trůn. A král se poklonil na své posteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Král také promluvil takto: ⌈Požehnaný je Hospodin, Bůh Izraele,⌉ že dal dnes ⌈toho, kdo usedl⌉ na můj trůn, a mé oči to vidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Nato všichni pozvaní, kteří byli s Adónijášem, vyděšeně vstali a šli každý svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adónijáš se bál Šalomouna, vstal, šel a chytil se rohů oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Šalomounovi bylo oznámeno: Hle, Adónijáš se bojí krále Šalomouna a chytil se rohů oltáře se slovy: Ať mi nejprve král Šalomoun odpřisáhne, že neusmrtí svého otroka mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Šalomoun řekl: Jestliže bude oddaný, nespadne mu ani vlas na zem. Ale jestliže ⌈při něm bude něco zlého,⌉ zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Král Šalomoun poslal, aby ho odvedli od oltáře. Když přišel a poklonil se před králem, Šalomoun mu řekl: Jdi domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Když se přiblížily dny, ⌈kdy měl David zemřít,⌉ vydal svému synu Šalomounovi příkaz:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Já jdu cestou ⌈všeho pozemského.⌉ Posilni se a vzmuž se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Zachovávej řád Hospodina, svého Boha, choď po jeho cestách a zachovávej jeho ustanovení, příkazy, nařízení a svědectví, jak je napsáno v Mojžíšově zákoně, abys měl úspěch ve všem, co budeš dělat a kamkoliv se obrátíš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'a aby Hospodin naplnil své slovo, které ke mně promluvil: Jestliže budou tvoji synové dbát na svou cestu a ⌈chodit přede mnou⌉ věrně, ⌈celým svým srdcem⌉ a celou svou duší, nebude ti vyhlazen muž z izraelského trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Ty také víš, co mi udělal Jóab, syn Serújin, co udělal dvěma velitelům izraelské armády, Abnérovi, synu Nérovu, a Amasovi, synu Jeterovu: Zabil je a prolil válečnou krev v míru a vložil válečnou krev na pás na svých bedrech a na boty na svých nohách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Učiň podle své moudrosti a nenech ⌈sestoupit jeho šediny v pokoji do podsvětí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Prokaž milosrdenství synům Barzilaje Gileádského, ať jsou mezi těmi, kdo jedí u tvého stolu, protože tak mi ⌈byli nablízku,⌉ když jsem utíkal před tvým bratrem Abšalómem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Hle, je u tebe Šimeí, syn Gérův, Benjamínec z Bachurímu. Ten mě proklínal hroznou kletbou v den, kdy jsem šel do Machanajimu. Pak mi vyšel vstříc k Jordánu a přísahal jsem mu při Hospodinu: Neusmrtím tě mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Nyní však ho nenech bez trestu. Vždyť jsi moudrý muž a víš, co mu máš udělat: Nech sestoupit jeho šediny do podsvětí v krvi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'David pak ulehl se svými otci a byl pohřben v Městě Davidově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Doba, po kterou David kraloval nad Izraelem, byla čtyřicet let. V Chebrónu kraloval sedm let a v Jeruzalémě kraloval třicet tři let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'A Šalomoun usedl na trůn svého otce Davida a jeho království se velice upevnilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Potom Adónijáš, syn Chagítin, přišel k Bat–šebě, matce Šalomounově. Zeptala se: Přicházíš v pokoji? Odpověděl: V pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Nato pravil: ⌈Chtěl bych ti něco říct.⌉ Řekla: Mluv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Řekl: Ty víš, že mně připadlo kralování, ⌈na mě byla zaměřena přízeň celého Izraele,⌉ abych kraloval, ale pak se odvrátilo kralování a připadlo mému bratru, protože mu připadlo od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, '⌈ O jednu věc tě nyní žádám.⌉ ⌈Neodmítni mě.⌉ Řekla mu: Mluv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Řekl: Promluv, prosím, s králem Šalomounem, neboť ⌈tebe neodmítne.⌉ Ať mi dá za ženu Abíšagu Šúnemitskou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Bat–šeba řekla: Dobře. Promluvím o tobě s králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Potom šla Bat–šeba ke králi Šalomounovi, aby s ním mluvila o Adónijášovi. Král vstal a šel jí naproti, poklonil se jí a usedl na svůj trůn. Nechal nachystat trůn pro královu matku a ona usedla po jeho pravici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Řekla: O jednu malou věc tě žádám. Neodmítni mě. Král jí řekl: Žádej, má matko, neodmítnu tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Řekla: Ať je dána Abíšag Šúnemitská za ženu tvému bratru Adónijášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Král Šalomoun své matce odpověděl: Proč žádáš Abíšagu Šúnemitskou pro Adónijáše? Žádej pro něj království! Vždyť on je můj bratr, starší nežli já. Pro něho a pro kněze Ebjátara a pro Jóaba, syna Serújina!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Nato král Šalomoun přísahal při Hospodinu slovy: Tak ať mi učiní Bůh, a ještě přidá, jestliže Adónijáš ⌈ ne vyslovil tuto věc ke své smrti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'A nyní jakože živ je Hospodin, který mě určil a nechal mě usednout na trůn mého otce Davida a postavil mi dům, jak promluvil, Adónijáš dnes bude usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Pak poslal král Šalomoun Benajáše, syna Jójadova; ten proti němu zasáhl, takže Adonijáš zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Knězi Ebjátarovi král řekl: Jdi do Anatótu, na svá pole, neboť jsi hoden smrti, ale dnes tě nedám usmrtit, protože jsi nosil truhlu Panovníka Hospodina před mým otcem Davidem a byl jsi pokořován vším tím, čím byl pokořován můj otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Šalomoun vyhnal Ebjátara, takže nebyl Hospodinovým knězem, aby se naplnilo Hospodinovo slovo, které promluvil o domu Élího v Šílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Když se dostala ta zpráva k Jóabovi (Jóab se totiž postavil za Adónijáše, ačkoliv za Abšalóma se nepostavil), utekl Jóab do Hospodinova stanu a chytil se rohů oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Králi Šalomounovi bylo oznámeno, že Jóab utekl do Hospodinova stanu a je u oltáře. Šalomoun poslal Benajáše, syna Jójadova, se slovy: Jdi a zasáhni proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benajáš vešel do Hospodinova stanu a řekl mu: Toto praví král: Odejdi. Odpověděl: Ne. Ať zemřu zde. Benajáš přinesl králi zprávu: Takto promluvil Jóab, toto mi odpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Král mu odpověděl: Učiň, jak řekl. Zasáhni proti němu a pohřbi ho. Tak odstraníš ode mě a z domu mého otce bezdůvodně prolitou krev, kterou prolil Jóab.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Hospodin vrátí na jeho hlavu ⌈krev, kterou prolil,⌉ když zasáhl proti dvěma mužům spravedlivějším a lepším, nežli je on, a zabil je mečem, aniž by o tom můj otec David věděl -- totiž Abnéra, syna Nérova, velitele izraelské armády, a Amasu, syna Jeterova, velitele judské armády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Jejich krev ať se vrátí navěky na hlavu Jóabovu a na hlavu jeho potomstva. Ale Davidovi, jeho potomstvu, jeho domu a jeho trůnu ať je navěky pokoj od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Benajáš, syn Jójadův, šel, zasáhl proti němu a usmrtil ho. Pak byl pohřben ve svém domě v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Na jeho místo ustanovil král nad armádou Benajáše, syna Jójadova, a kněze Sádoka král ustanovil namísto Ebjátara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Král ⌈dal zavolat⌉ Šimeího a řekl mu: Postav si v Jeruzalémě dům, pobývej tam a nikam odtud nevycházej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'I stane se, že v den, kdy vyjdeš a přejdeš přes potok Kidrón, to věz, že jistě zemřeš a tvá krev bude na tvé hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Šimeí králi řekl: ⌈Dobře jsi promluvil.⌉ Jak můj pán a král řekl, tak tvůj otrok učiní. Šimeí pak pobýval v Jeruzalémě po mnoho dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'I stalo se po třech letech, že Šimeímu utekli dva otroci k Akíšovi, synu Maakovu, králi Gatu. Šimeímu oznámili: Hle, tvoji otroci jsou v Gatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Šimeí vstal, osedlal svého osla a vydal se do Gatu k Akíšovi hledat své otroky. Pak Šimeí přišel a přivedl z Gatu své otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Šalomounovi bylo oznámeno, že Šimeí šel z Jeruzaléma do Gatu a vrátil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Král dal zavolat Šimeího a řekl mu: Což jsem tě nezapřísahal při Hospodinu a ne varoval tě slovy: V den, kdy vyjdeš a půjdeš někam, to věz, že jistě zemřeš? Odpověděl jsi mi: Dobře jsi promluvil, uposlechnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Proč jsi nedbal na přísahu Hospodinu a na příkaz, který jsem ti dal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Král dále Šimeímu řekl: Ty znáš ⌈a svědomí ti dosvědčuje všechno zlo,⌉ které jsi spáchal vůči mému otci Davidovi. Hospodin obrátil tvé zlo na tvou hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Ale král Šalomoun bude požehnaný a trůn Davidův bude pevně stát před Hospodinem navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Král vydal příkaz Benajášovi, synu Jójadovu, ten šel a zasáhl proti němu, takže zemřel. Tak se království v Šalomounově ruce upevnilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Šalomoun se pak spříznil s faraonem, egyptským králem, vzal si faraonovu dceru a přivedl ji do Města Davidova, dokud nedostavěl svůj dům a ⌈dům Hospodinův⌉ i hradby okolo Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Lid ovšem obětoval na návrších, protože do ⌈té doby⌉ nebyl postaven dům pro Hospodinovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Šalomoun miloval Hospodina a žil podle ustanovení svého otce Davida, ovšem na návrších obětoval a pálil oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Král šel do Gibeónu, aby tam obětoval, protože to bylo největší návrší. Šalomoun přinesl na tom oltáři tisíc zápalných obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'V Gibeónu se ukázal Hospodin Šalomounovi v noci ve snu. Bůh řekl: Žádej, co ti mám dát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Šalomoun řekl: Ty jsi ⌈prokázal svému⌉ otroku, mému otci Davidovi, velké milosrdenství, když před tebou chodil věrně a spravedlivě, s upřímným srdcem vůči tobě. Zachoval jsi mu toto velké milosrdenství a dal jsi mu syna, který sedí na jeho trůnu, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Nyní jsi, ⌈Hospodine, můj Bože,⌉ ustanovil svého otroka králem namísto mého otce Davida. Ale já jsem mladý chlapec, neumím vycházet a vcházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Tvůj otrok je uprostřed tvého lidu, který jsi vyvolil, početného lidu, jenž ne může být pro množství sečten ani spočítán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Dej svému otroku vnímavé srdce, aby mohl soudit tvůj lid a rozlišovat mezi dobrem a zlem. Vždyť kdo dokáže soudit tento tvůj ohromný lid?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, '⌈V Panovníkových očích to bylo dobré,⌉ že Šalomoun žádal o tuto věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Bůh mu řekl: Protože jsi žádal o tuto věc a nežádal jsi pro sebe ⌈dlouhý život,⌉ nežádal jsi pro sebe bohatství ani jsi nežádal o smrt svých nepřátel, ale žádal jsi pro sebe porozumění, abys rozuměl právu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'hle, učiním podle tvých slov: Ano, dám ti moudré a rozumné srdce, takže nebyl před tebou nikdo jako ty, ani po tobě nepovstane nikdo jako ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Také to, o co jsi nežádal, ti dám: Bohatství i slávu po ⌈všechny tvé dny,⌉ takže nebyl nikdo jako ty mezi králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Jestliže budeš chodit po mých cestách a zachovávat má ustanovení a mé příkazy tak, jak chodil tvůj otec David, prodloužím tvé dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Nato se Šalomoun probral, byl to sen. Šel do Jeruzaléma, postavil se před truhlu Panovníkovy smlouvy, přinesl zápalné oběti, vykonal pokojné oběti a uspořádal hostinu pro všechny své otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Tehdy přišly ke králi dvě prostitutky a postavily se před něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Jedna ta žena řekla: Dovol, můj pane. Já a tato žena bydlíme v jednom domě. Porodila jsem u ní v domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'I stalo se, že třetí den poté, co jsem porodila já, porodila i tato žena. Byly jsme spolu, nikdo jiný s námi v domě nebyl, jenom my dvě jsme byly v domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Syn této ženy v noci zemřel, protože ho zalehla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Pak uprostřed noci vstala, a když tvá otrokyně spala, vzala mého syna vedle mě, položila ho do svého klína a svého mrtvého syna položila do mého klína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Ráno jsem vstala, abych svého syna nakojila, a byl mrtev. Když jsem se na něj ráno podívala pozorně, uviděla jsem, že to není můj syn, kterého jsem porodila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Ta druhá žena ovšem řekla: Ne, ten živý je můj syn a ten mrtvý je tvůj syn. Ale ta první říkala: Ne, ten mrtvý je tvůj syn a ten živý je můj syn. Tak se před králem hádaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Nato král řekl: Tato říká: Ten živý, to je můj syn, a ten mrtvý je tvůj syn, a tato říká: Ne, ten mrtvý je tvůj syn a ten živý je můj syn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Král řekl: Podejte mi meč. Přinesli před krále meč');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'a král přikázal: Rozsekněte to živé dítě ve dví a dejte polovinu jedné a polovinu druhé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Avšak žena, které patřilo to živé dítě, promluvila ke králi, protože se v ní ⌈probudil soucit s⌉ jejím synem. Řekla: Dovol, můj pane, dejte jí to živé dítě, jenom ho neusmrcujte! Ale ta druhá řekla: Nebude ani moje, ani tvoje, rozsekněte ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Král nato odpověděl: Dejte jí to živé dítě a neusmrcujte ho. To je jeho matka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Když celý Izrael uslyšel o rozsudku, který král vynesl, báli se krále, protože viděli, že v něm je Boží moudrost k vykonávání práva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Král Šalomoun byl králem nad celým Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'A toto jsou knížata, která měl: Azarjáš, syn Sádokův, byl knězem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elíchoref a Achijáš, syn Šíšův, byli písaři; Jóšafat, syn Achílúdův, byl kancléřem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benajáš, syn Jójadův, byl nad armádou; Sádok a Ebjátar byli kněžími;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarjáš, syn Nátanův, byl nad ustanovenými správci, Zabúd, syn kněze Nátana, byl královým přítelem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Achíšar ⌈ byl nad domem⌉ a Adóníram, syn Abdův, byl nad nucenými pracemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Šalomoun měl dvanáct ustanovených správců ⌈nad celým Izraelem,⌉ kteří zásobovali krále a jeho dům; měsíc v roce bylo vždy na jednom z nich zásobování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'A toto jsou jejich jména: Ben–chúr v Efrajimském pohoří;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Ben–deker v Makacu, Šaalbímu, Bét–šemeši a Elón–bét–chánanu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ben–chesed v Arubótu (jemu patřilo Sóko a celá země Chefer);');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben–abínádab v celé ⌈Dórské pahorkatině.⌉ (Šalomounova dcera Táfat byla jeho ženou);');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, syn Achílúdův, v Taanaku, Megidu a celém Bét–šeánu, který je vedle Saretanu pod Jizreelem -- od Bét–šeánu k Ábel–mechóle až za Jokmeám;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ben–geber v Rámot–gileádu (jemu patřily vesnice Jaíra, syna Manasesova, které jsou v Gileádu; jemu patřila též oblast Argóbu, který je v Bášanu, šedesát velkých měst s hradbami a bronzovými závorami);');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Achínádab, syn Idův, v Machanajimu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achímaas v Neftalím (také on si vzal za ženu Šalomounovu dceru, Basematu);');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, syn Chúšajův, v Ašerovi a Bealótu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jóšafat, syn Parúachův, v Isacharovi;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Šimeí, syn Elův, v Benjamínovi;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, syn Uriův, v gileádské zemi, (zemi emorejského krále Síchona a bášanského krále Óga), a jedna posádka, která byla v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Judejců a Izraelců bylo tak velké množství jako písku v moři; jedli, pili a radovali se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Šalomoun byl vládcem nad všemi královstvími od řeky Eufratu po pelištejskou zemi a až k hranici Egypta. Přinášeli mu dávky a otročili Šalomounovi po všechny dny jeho života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, '⌈Šalomounovi na jeden den připadlo za pokrm⌉ třicet kórů jemné mouky a šedesát kórů obyčejné mouky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'deset ⌈tučných býků,⌉ dvacet býků z pastvy a sto ovcí, kromě jelenů, gazel, srnců a vykrmené drůbeže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Panoval nad celým Zaeufratím od Tifsachu až po Gazu, nad všemi králi Zaeufratí a ⌈na všech stranách⌉ měl pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Juda i Izrael pobýval v bezpečí, každý pod svou révou a pod svým fíkovníkem, od Danu až po Beer–šebu, po všechny Šalomounovy dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Šalomoun měl čtyřicet tisíc ⌈stájí pro koně ke svým vozům⌉ a dvanáct tisíc jezdců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Tito ustanovení správci zásobovali krále Šalomouna a všechny, kterým bylo dovoleno přicházet ke stolu krále Šalomouna, každý ve svém měsíci, a nedovolovali, aby něco chybělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Také ječmen a slámu pro koně a oře přiváželi na místo, kde byl, každý podle nařízení pro něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Bůh dal Šalomounovi moudrost, přemnoho rozumnosti a ⌈rozum tak nezměrný⌉ jako písek na mořském břehu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Šalomounova moudrost byla větší nežli moudrost všech synů východu, nad všechnu moudrost Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Byl moudřejší nežli všichni lidé, nežli Étan Ezrachejský a Héman, Kalkol a Darda, syn Machólův, a proslavil se mezi všemi okolními národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Vyslovil tři tisíce přísloví a bylo jeho písní tisíc a pět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Hovořil o stromech, od cedru, který je na Libanonu, až po yzop, který roste na zdi, hovořil o zvířatech, ptácích, plazech a rybách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'A přicházeli ze všech národů, aby poslouchali Šalomounovu moudrost, od všech králů země, kteří uslyšeli o jeho moudrosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Týrský král Chíram poslal k Šalomounovi své otroky, neboť uslyšel, že ho pomazali za krále namísto jeho otce. Chíram byl totiž po celou dobu Davidovým přítelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Šalomoun vzkázal Chíramovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Ty víš o mém otci Davidovi, že nemohl postavit dům pro jméno Hospodina, svého Boha, kvůli válkám, které ho obklopovaly, dokud mu Hospodin nevydal nepřátele pod nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Nyní mi Hospodin, můj Bůh, dal odpočinek všude kolem, nemám protivníka ani žádnou zlou okolnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, 'Proto hodlám postavit dům pro jméno Hospodina, svého Boha, jak prohlásil Hospodin mému otci Davidovi: Tvůj syn, kterého dám namísto tebe na tvůj trůn, ten postaví dům pro mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, 'Nyní přikaž, aby pro mě káceli cedry z Libanonu. Tvoji otroci budou s mými otroky a budu ti dávat mzdu pro tvé otroky, jak si řekneš. Vždyť víš, že mezi námi není nikdo, kdo by uměl kácet stromy jako Sidónci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, 'I stalo se, že když Chíram uslyšel Šalomounova slova, velice se zaradoval a řekl: Požehnaný je dnes Hospodin, že dal Davidovi moudrého syna nad tímto početným lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, 'Chíram vzkázal Šalomounovi: Uposlechnu, co jsi mi vzkázal, a udělám všechno, po čem toužíš ohledně cedrového a cypřišového dřeva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, 'Moji otroci je budou svážet z Libanonu k moři, já je svázané do voru nechám plavit po moři na místo, které mi určíš, tam je rozvážu a ty si je odvezeš. Ty zas budeš plnit mé přání a dávat potravu pro můj dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, 'Tak Chíram dával Šalomounovi cedrové a cypřišové dřevo zcela podle jeho přání');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, 'a Šalomoun dával Chíramovi dvacet tisíc kórů pšenice jako zásobu pro jeho dům a dvacet kórů panenského oleje. To dával Šalomoun Chíramovi rok co rok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, 'Hospodin dal Šalomounovi moudrost, jak mu řekl, a mezi Chíramem a Šalomounem byl pokoj, uzavřeli spolu smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, 'Král Šalomoun povolal na nucené práce muže z celého Izraele; nucené práce připadly na třicet tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, 'Poslal ⌈jich na Libanon deset tisíc, po měsíci se střídali.⌉ Měsíc byli na Libanonu a dva měsíce doma. Nad nucenými pracemi byl Adóníram.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, 'Šalomoun měl sedmdesát tisíc nosičů břemen a osmdesát tisíc kameníků v horách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, 'Kromě toho měl Šalomoun tři tisíce tři sta ustanovených předáků, kteří byli nad prací a panovali nad lidem, který konal práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, 'Král vydal příkaz, aby lámali velké a kvalitní kameny, aby byly základy domu položeny z tesaných kamenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, 'Tesali je stavitelé Šalomounovi a stavitelé Chíramovi i Gebalci. Tak připravovali dřevo a kameny na stavbu domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'I stalo se, že čtyři sta osmdesát let po vyjití synů Izraele z egyptské země, v měsíci zívu, což je druhý měsíc, ve čtvrtém roce, kdy kraloval Šalomoun nad Izraelem, začal stavět dům pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Dům, který král Šalomoun stavěl pro Hospodina, byl šedesát loket dlouhý, dvacet loket široký a třicet vysoký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Předsíň v průčelí chrámového domu byla dvacet loket dlouhá v průčelí široké strany domu a deset loket široká v průčelí domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Na domě udělal zúžená okna s ostěním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Ke zdi domu postavil přístavbu -- okolo zdí domu, okolo chrámu i svatyně; ze všech stran udělal ochozy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Spodní část přístavby byla pět loket široká, prostřední šest loket široká a vrchní sedm loket široká; protože učinil okolo domu zvenku římsy, trámy nezasahovaly do zdí domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Když byl dům stavěn, byl budován z hotového kamene, opracovaného již v lomu; kladiva ani sekery, žádný železný nástroj nebylo v domě slyšet, když byl stavěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Vchod do prostředního ochozu byl na pravé straně domu; točitým schodištěm se šlo na prostřední a z prostředního na vrchní ochoz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, '⌈Když dostavěl dům, obložil⌉ dům cedrovými trámy a prkny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'K celému domu postavil přístavbu pět loket vysokou a připojil ji k domu cedrovým dřevem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'I stalo se Hospodinovo slovo k Šalomounovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Co se týká tohoto domu, který stavíš: Jestliže budeš žít podle mých ustanovení, plnit má nařízení, zachovávat všechny mé příkazy a žít podle nich, naplním ⌈na tobě⌉ své slovo, které jsem promluvil k tvému otci Davidovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'a budu přebývat uprostřed synů Izraele a neopustím svůj lid Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Když ⌈Šalomoun dostavěl dům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'obložil⌉ zdi domu zevnitř cedrovými prkny, od podlahy domu až po zdi stropu obložil vnitřek dřevem. Podlahu domu obložil cypřišovými prkny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Dvacet loket od zadní části domu postavil příčku z cedrových prken, od podlahy, až kam sahaly zdi, a tak postavil vnitřek jako svatyni, jako nejsvětější místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Čtyřicet loket byl dům, to je chrám, vepředu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Cedr uvnitř domu měl řezby s ozdobami tykvovitými a v podobě rozvitých květů. Všechno bylo z cedru, kámen nebyl vidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'V nejvnitřnější části domu připravil svatyni, aby tam dal truhlu Hospodinovy smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Vnitřek svatyně byl dvacet loket dlouhý, dvacet loket široký a dvacet loket vysoký. Potáhl ji čistým zlatem a potáhl ⌈ i cedrový oltář.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Šalomoun potáhl dům uvnitř čistým zlatem, natáhl zlaté řetězy před svatyní a potáhl ji zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Celý dům potáhl zlatem, úplně celý dům, i celý oltář, který patřil ke svatyni, potáhl zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Udělal ve svatyni dva cheruby z olivového dřeva, deset loket vysoké.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Pět loket bylo jedno křídlo cheruba a pět loket druhé křídlo cheruba, deset loket bylo od konců jednoho křídla na konec druhého křídla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Deset loket měl druhý cherub, oba cherubové měli stejný rozměr a stejný tvar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Výška jednoho cheruba byla deset loket a tak i druhého cheruba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Cheruby dal doprostřed vnitřního domu. Cherubové rozprostírali křídla, takže se jedno křídlo dotýkalo jedné stěny a křídlo druhého cheruba se dotýkalo druhé stěny; jejich křídla se dotýkala uprostřed domu, křídlo křídla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'I cheruby potáhl zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Všechny stěny domu, zevnitř i zvenčí, dokola ozdobil vyřezávanými řezbami cherubů, palmových ozdob a rozvitých květů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'I podlahu domu potáhl zlatem, ⌈uvnitř i vně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Do vchodu svatyně udělal dveře z olivového dřeva; pilíř a veřeje ⌈ byly pěti hranné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Obě křídla dveří byla z olivového dřeva. Na ně vyřezal řezby cherubů, palmových ozdob a rozvitých květů a potáhl je zlatem. Na cheruby a palmové ozdoby nechal zlato přibít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Totéž udělal pro dveře do chrámu -- veřeje z olivového dřeva, ale čtyř hranné,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'a dvě křídla dveří z cypřišového dřeva. Dvě otočné části mělo jedno křídlo a dvě otočné části mělo druhé křídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Vyřezal na ně cheruby, palmové ozdoby a rozvité květy a potáhl zlatem patřičně přibitým na vyryté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Postavil vnitřní nádvoří ze tří řad tesaných kamenů a řady otesaných cedrových trámů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Základy Hospodinova domu byly položeny ve čtvrtém roce, v měsíci zívu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'a v jedenáctém roce, v měsíci búlu, což je osmý měsíc, dokončil dům se všemi jeho ⌈náležitostmi a vším uspořádáním.⌉ Stavěl ho sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Svůj dům stavěl Šalomoun třináct let, než ho celý dokončil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Postavil dům Libanonského lesa -- sto loket dlouhý, padesát loket široký a třicet loket vysoký, na čtyřech řadách cedrových sloupů, a otesané cedrové trámy byly na sloupech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Nahoře byl obložen cedrovým dřevem, prkny, která byla na čtyřiceti pěti sloupech, po patnácti v řadě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Okenních rámů byly tři řady, otvor proti otvoru třikrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Všechny vchody a veřeje byly čtvercové, otvor proti otvoru třikrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Sloupovou předsíň udělal padesát loket dlouhou a třicet loket širokou. Před ní byla předsíň a před ní byly sloupy a stříška.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Udělal též trůnní síň, kde soudil, tedy soudní síň. Obložil ji cedrovým dřevem od podlahy až ke stropu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Dům, ve kterém sídlil, na druhém nádvoří, od dělený od síně, byl udělán také tak. Podobný této síni udělal i dům pro faraonovu dceru, kterou si Šalomoun vzal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Všechny tyto budovy, od základu až po završení, z vnějšku až na velké nádvoří, byly postaveny z kvalitních kamenů, tesaných na míru a ⌈pilou ořezaných zevnitř i zvenčí. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Základy byly z kvalitních kamenů, z velkých kamenů, z kamenů o deseti a osmi loktech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'I nahoře byly kvalitní kameny tesané na míru a cedrové dřevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Velké nádvoří mělo dokola tři řady tesaných kamenů a řadu otesaných cedrových trámů, jako vnitřní nádvoří Hospodinova domu a předsíň domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Král Šalomoun poslal pro Chírama z Týru a nechal ho přivést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Byl synem vdovy z pokolení Neftalího a jeho otec byl Týřan, kovotepec. Byl plný moudrosti, rozumnosti a ⌈poznání, aby dělal veškerou⌉ práci s bronzem. Přišel ke králi Šalomounovi a konal všechnu ⌈práci pro něj.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Odlil dva bronzové sloupy; osmnáct loket byl vysoký jeden sloup a obepnula ho šňůra dvanácti loket; podobně i druhý sloup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Udělal dvě hlavice odlité z bronzu a dal je na vrchol sloupů. Pět loket byla vysoká jedna hlavice a pět loket byla vysoká i druhá hlavice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Udělal též ⌈proplétané mřížování⌉ a řetězovité ozdoby na hlavice, které byly na vrcholu sloupů -- sedm na jedné hlavici a sedm na druhé hlavici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Udělal sloupy tak, že dvě řady granátových jablek byly dokola na jednom mřížování, aby zakryl hlavice, které byly na vrcholu; tak udělal i s druhou hlavicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Hlavice, které byly na vrcholu sloupů v předsíni, měly liliovitou úpravu a měřily čtyři lokte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Hlavice na obou sloupech byly také nad vypuklinou, která byla na druhé straně mřížování, i vedle ní. Dvě stě granátových jablek bylo v řadách dokola na druhé hlavici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Postavil sloupy do předsíně chrámu. Postavil pravý sloup a nazval ho Jakín a postavil levý sloup a nazval ho Bóaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Na vrcholu sloupů byla liliovitá úprava. Tak byla dokončena práce na sloupech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Potom udělal odlité moře; deset loket bylo od okraje po okraj, dokola okrouhlé, pět loket bylo vysoké a ⌈obepnula ho dokola šňůra třiceti⌉ loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Pod jeho okrajem ho dokola obklopovaly tykvovité ozdoby, deset na loket, kolem dokola moře. Tykvovité ozdoby byly ve dvou řadách, odlité ⌈při odlévání moře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Stálo na dvanácti býcích: Tři byli obráceni na sever, tři byli obráceni na západ, tři byli obráceni na jih a tři byli obráceni na východ. Moře bylo nahoře na nich a všechny jejich zadky byly směrem dovnitř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Bylo na dlaň silné a jeho okraj byl udělán jako okraj poháru, do liliovitého květu. Pojalo dva tisíce batů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Potom udělal deset bronzových podstavců. Každý podstavec byl čtyři lokte dlouhý, čtyři lokte široký a tři lokte vysoký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, '⌈Podstavce byly udělány takto:⌉ Měly postranice a postranice byly mezi rámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Na postranicích, které byly mezi rámy, byli lvi, býci a cherubové, i na rámech nahoře. Dole pod lvy a býky byly udělány převislé věnce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Jeden podstavec měl čtyři bronzová kola a bronzové nápravy. Jeho čtyři nohy měly ramena zdola pod nádrží. Ramena byla odlita po každé s věnci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Jeho otvor zevnitř podstavce a nahoru měl loket. Jeho otvor byl okrouhlý, udělán tak, aby měl loket a půl. Také na jeho otvoru byly řezby. Jejich postranice byly čtvercové, nikoli okrouhlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Zespodu měly postranice čtyři kola. Osy kol byly na podstavcích. Výška jednoho kola byla loket a půl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Kola byla udělána jako kolo válečného vozu. Jejich osy, loukotě, paprsky a náboje byly všechny odlité.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Jeden podstavec měl čtyři ramena ve čtyřech rozích; z podstavce vycházela jeho ramena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Navrchu byl podstavec půl loktu vysoký a dokola okrouhlý; navrchu podstavce z něj vycházely jeho podpěry a postranice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Na plochy podpěr a na postranice vyryl cheruby, lvy a palmové ozdoby podle volného místa na každé a okolo věnce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Takto udělal deset podstavců. Všechny byly ⌈stejně odlité,⌉ měly stejný rozměr a stejný tvar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Udělal též deset bronzových nádrží. Každá nádrž pojala čtyřicet batů. Každá nádrž měla čtyři lokte. Každá nádrž byla na jednom z deseti podstavců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Pět podstavců dal na pravou stranu domu a pět na levou stranu domu. Moře dal na pravou stranu domu, z jihovýchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Chíram též udělal nádrže, lopaty a misky. Tak Chíram dodělal všechnu práci, kterou konal pro krále Šalomouna na Hospodinově domě:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Dva sloupy a kulovité hlavice, které byly na vrcholu obou sloupů, dvoje mřížování, aby zakrývalo obě kulovité hlavice, které byly na vrcholu sloupů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'čtyři sta granátových jablek pro dvoje mřížování, dvě řady granátových jablek pro jedno mřížování, aby zakrývaly obě kulovité hlavice, které byly na vrchu sloupů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'deset podstavců a deset nádrží na podstavce;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'jedno moře a dvanáct býků pod moře;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'hrnce, lopaty a misky. Všechny tyto předměty, které Chíram dělal pro krále Šalomouna na Hospodinově domě, byly z leštěného bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Král je odlil ve slévárně v Jordánské rovině mezi Sukótem a Saretánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Šalomoun nechal všechny předměty nezvážené, protože jich bylo převeliké množství. Váha bronzu se nedala zjistit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Šalomoun udělal všechny předměty, které byly v Hospodinově domě: Zlatý oltář a zlatý stůl, na kterém byl předkladný chléb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'svícny z čistého zlata -- pět napravo a pět nalevo před svatyní, květy, lampy a kleště ze zlata');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'číše, nůžky na knoty, misky, kadidlové pánvičky a pánvičky na uhlíky z čistého zlata; i zlaté čepy pro dveře vnitřního domu, nejsvětějšího místa, a pro dveře chrámového domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Tak byla dokončena všechna práce, kterou král Šalomoun dělal na Hospodinově domě. Pak Šalomoun přinesl svaté věci svého otce Davida -- stříbro, zlato a předměty -- a dal je do pokladnic Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Potom svolal Šalomoun izraelské starší, všechny vůdce pokolení a předáky rodů synů Izraele ke králi Šalomounovi do Jeruzaléma, aby přenesli truhlu Hospodinovy smlouvy z Města Davidova, to je ze Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Shromáždili se tedy ke králi Šalomounovi všichni izraelští muži ve svátek v měsíci etanímu, to je v měsíci sedmém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Když přišli všichni izraelští starší, kněží vzali truhlu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'a přenesli Hospodinovu truhlu. Stan setkávání a všechny svaté předměty, které byly ve stanu, přenesli kněží a lévité.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Král Šalomoun a celá pospolitost Izraele, která se k němu sešla, byli s ním před truhlou a obětovali brav a skot, který ne mohl být pro množství spočítán ani sečten.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Kněží přinesli truhlu Hospodinovy smlouvy na její místo do svatyně domu, na nejsvětější místo, pod křídla cherubů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Protože cherubové měli křídla roztažená nad místem truhly, zahalovali cherubové odshora truhlu i její tyče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Tyče byly dlouhé, takže konce tyčí byly vidět ze svatého místa před svatyní, ale nebyly vidět ven. Jsou tam až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'V truhle ⌈byly pouze⌉ dvě kamenné desky, které tam uložil Mojžíš na Chorébu, když Hospodin uzavřel smlouvu se syny Izraele potom, co vyšli z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'I stalo se, že když kněží vyšli ze svatého místa, naplnil Hospodinův dům oblak,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'takže kněží nemohli stát a sloužit kvůli oblaku, protože Hospodinova sláva naplnila Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tehdy Šalomoun řekl: Hospodin pravil, že bude přebývat v husté temnotě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Postavil jsem ti dům k přebývání, sídlo, kde bys pobýval navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Pak se král obrátil a požehnal celému shromáždění Izraele; celé shromáždění Izraele stálo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Řekl: Požehnán buď Hospodin, Bůh Izraele, který svými ústy promluvil k mému otci Davidovi a svou rukou to naplnil. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Ode dne, kdy jsem vyvedl svůj lid Izrael z Egypta, jsem nevyvolil žádné město ze všech izraelských kmenů pro stavbu domu, aby tam přebývalo mé jméno, ale vyvolil jsem Davida, aby byl nad mým lidem Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, '⌈Můj otec David měl na srdci⌉ postavit dům pro jméno Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Hospodin však mému otci Davidovi řekl: Když jsi měl ⌈na srdci⌉ postavit dům pro mé jméno, udělal jsi dobře, že jsi to měl na srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Ty ovšem nepostavíš ten dům, nýbrž tvůj syn, který vzejde z tvých beder, ten postaví dům pro mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Hospodin naplnil své slovo, které promluvil. Povstal jsem po svém otci Davidovi a usedl jsem na izraelský trůn, jak Hospodin promluvil, a postavil jsem dům pro jméno Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'A nachystal jsem tam místo pro truhlu, v níž je Hospodinova smlouva, kterou uzavřel s našimi otci, když je vyvedl z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Nato se Šalomoun před celým shromážděním Izraele postavil před Hospodinův oltář, vztáhl své dlaně k nebesům');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'a řekl: Hospodine, Bože Izraele, není Bůh jako ty nahoře na nebesích ani dole na zemi, který zachovává smlouvu a milosrdenství svým otrokům, kteří chodí před tebou celým svým srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Ty jsi zachoval svému otroku, mému otci Davidovi, to, cos mu řekl; promluvil jsi svými ústy a svou rukou jsi to naplnil, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nyní, Hospodine, Bože Izraele, zachovej svému otroku, mému otci Davidovi, to, cos mu řekl: Nebude ti vyhlazen přede mnou ten, kdo by seděl na izraelském trůnu, pokud ovšem budou tvoji synové dbát na svou cestu a chodit přede mnou tak, jak jsi chodil přede mnou ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nyní, Bože Izraele, kéž ⌈se ukáže jako spolehlivé⌉ tvé slovo, které jsi promluvil ke svému otroku, mému otci Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Což opravdu bude Bůh sídlit na zemi? Vždyť nebesa ani nebesa nebes tě ne mohou pojmout, tím méně tento dům, který jsem postavil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'A přece pohleď, Hospodine, můj Bože, na modlitbu svého otroka a na jeho úpěnlivou prosbu a vyslyš volání a modlitbu, kterou se dnes tvůj otrok před tebou modlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Kéž jsou tvé oči otevřené k tomuto domu ⌈nocí i dnem,⌉ k místu, o kterém jsi řekl: Tam bude přebývat mé jméno. Vyslyš modlitbu, kterou se tvůj otrok bude modlit na tomto místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Vyslyš úpěnlivou prosbu svého otroka a svého lidu Izraele, když se bude modlit na tomto místě, vyslyš na místě, kde sídlíš, na nebesích, vyslyš a odpusť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Jestliže někdo zhřeší proti svému bližnímu a ten na něm vymůže přísahu, aby přísahal, on přijde a vysloví přísahu před tvým oltářem v tomto domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'uslyš v nebesích, konej a zjednej právo svým otrokům: Ničemu prohlaš vinným a uval jeho cestu na jeho hlavu a spravedlivého prohlaš za spravedlivého a dej mu podle jeho spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Jestliže bude tvůj lid Izrael poražen od nepřítele, protože proti tobě zhřeší, ale pak se k tobě navrátí, vzdají chválu tvému jménu, budou se modlit a prosit tě v tomto domě o smilování,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'uslyš v nebesích, odpusť hřích svého lidu Izraele a přiveď je zpět do země, kterou jsi dal jejich otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Jestliže budou uzavřena nebesa a nebude déšť, protože proti tobě zhřeší, ale pak se budou na tomto místě modlit, vzdají chválu tvému jménu a odvrátí se od svého hříchu, protože je pokoříš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'uslyš v nebesích, odpusť hřích svých otroků a svého lidu Izraele, až je vyučíš dobré cestě, po níž by měli jít, a dej déšť na svou zemi, kterou jsi dal svému lidu do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Jestliže bude v zemi hlad, jestliže bude mor, obilná rez, sněť, jestliže budou kobylky arbe či kobylky chasíl, jestliže mu v zemi, v některém z jeho měst, jeho nepřítel způsobí soužení, ať je to jakákoliv rána, jakákoliv nemoc,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'každou modlitbu a každou úpěnlivou prosbu, která vzejde od kteréhokoliv člověka z celého tvého lidu Izraele -- znají přece každý ⌈ránu svého srdce⌉ -- když vztáhnou své dlaně k tomuto domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'vyslyš v nebesích, v sídle, kde pobýváš, odpusť, jednej a dej každému podle všech jeho cest, jak znáš jeho srdce -- vždyť ty jediný znáš srdce všech ⌈lidských synů⌉ --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'aby se tě báli po všechny dny, co budou naživu na povrchu země, kterou jsi dal našim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Také když cizinec, který není ze tvého lidu Izraele, přijde z daleké země kvůli tvému jménu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '-- neboť uslyší o tvém velkém jménu a tvé mocné ruce a vztažené paži -- přijde– li a bude se modlit v tomto domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'vyslyš v nebesích, v sídle, kde pobýváš, a učiň všechno, za co bude k tobě tento cizinec volat, aby všechny národy země poznaly tvé jméno, bály se tě jako tvůj lid Izrael a poznaly, že tento dům, který jsem postavil, ⌈se nazývá tvým jménem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Když tvůj lid vytáhne do boje proti svému nepříteli, cestou, kterou je pošleš, a budou se modlit k Hospodinu směrem k městu, které sis vyvolil, a domu, který jsem postavil pro tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'vyslyš v nebesích jejich modlitbu a jejich úpěnlivou prosbu a zjednej jim právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Když proti tobě zhřeší -- neboť není člověk, který by nezhřešil -- budeš se na ně hněvat, vydáš je nepříteli a jejich věznitelé je odvedou do nepřátelské země vzdálené či blízké,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'ale pak ⌈změní své smýšlení⌉ v zemi, kam byli odvedeni, obrátí se, budou tě v zemi svých věznitelů prosit o smilování slovy: Zhřešili jsme, spáchali jsme zlo a jednali ničemně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'a jestliže se k tobě obrátí ⌈celým svým srdcem⌉ a celou svou duší v zemi svých nepřátel, kteří je zajali, budou se k tobě modlit směrem ke své zemi, kterou jsi dal jejich otcům, k městu, které sis vyvolil, a k domu, který jsem postavil pro tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'vyslyš v nebesích, sídle, kde pobýváš, jejich modlitbu a jejich úpěnlivou prosbu, zjednej jim právo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'odpusť svému lidu, který proti tobě zhřešil, všechna jejich přestoupení, kterými se proti tobě bouřili, a dej jim dojít slitování před jejich vězniteli, aby s nimi měli slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Vždyť jsou tvým lidem a tvým dědictvím, které jsi vyvedl z Egypta, z pece na tavení železa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Nechť jsou tvé oči otevřené k úpěnlivé prosbě tvého otroka a k úpěnlivé prosbě tvého lidu Izraele a vyslyšíš je, kdykoliv budou k tobě volat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Vždyť jsi je oddělil pro sebe za dědictví ze všech národů země, jak jsi řekl prostřednictvím svého otroka Mojžíše, když jsi vyvedl naše otce z Egypta, Panovníku Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'I stalo se, když se Šalomoun domodlil k Hospodinu celou tuto modlitbu a úpěnlivou prosbu, že vstal od Hospodinova oltáře, kde klečel na kolenou a své dlaně rozprostíral k nebesům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'postavil se a hlasitě požehnal celému shromáždění Izraele:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Požehnán buď Hospodin, který dal odpočinutí svému lidu Izraeli, tak jak řekl. Nezapadlo jediné slovo ze všech jeho dobrých slov, která ⌈mluvil prostřednictvím⌉ svého otroka Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Ať je Hospodin, náš Bůh, s námi, jako byl s našimi otci, nechť nás neopustí ani nezanechá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Nechť ⌈nakloní naše srdce k sobě,⌉ abychom chodili po všech jeho cestách a zachovávali jeho příkazy, ustanovení a nařízení, která přikázal našim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Nechť jsou tato má slova, kterými jsem prosil před Hospodinem o smilování, dnem i nocí blízko Hospodinu, našemu Bohu, aby zjednal právo svému otroku a právo svému lidu Izraeli podle ⌈každodenní potřeby,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'aby všechny národy země poznaly, že Hospodin je Bůh a žádný jiný není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Nechť je vaše srdce ⌈cele s Hospodinem,⌉ naším Bohem, abyste žili podle jeho ustanovení a zachovávali jeho příkazy, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Nato král a celý Izrael s ním obětovali před Hospodinem oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Šalomoun obětoval jako pokojné oběti, které obětoval Hospodinu, dvacet dva tisíc býků a sto dvacet tisíc ovcí. Tak král a všichni synové Izraele zasvětili Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'V onen den král posvětil střed nádvoří, které je před Hospodinovým domem, neboť tam připravil oběti zápalné a přídavné i tučné části pokojných obětí, protože bronzový oltář, který je před Hospodinem, byl příliš malý, než aby pojal zápalné a přídavné oběti i tučné části pokojných obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Šalomoun a s ním celý Izrael, velké shromáždění lidí, kteří přišli od Lebo–Chamátu až po egyptský potok, slavil v ten čas před Hospodinem, naším Bohem, svátek po sedm dní a dalších sedm dní, celkem čtrnáct dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Osmého dne propustil lid. ⌈Dobrořečili králi⌉ a šli ke svým stanům radostně a s ⌈veselou myslí⌉ nad vším dobrem, které Hospodin učinil svému otroku Davidovi a svému lidu Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'I stalo se, když Šalomoun dostavěl Hospodinův dům, královský palác a ⌈všechno, co si Šalomoun přál a⌉ chtěl učinit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'že se ukázal Hospodin Šalomounovi podruhé, jako se mu ukázal v Gibeónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Hospodin mu řekl: Vyslyšel jsem tvou modlitbu a tvou úpěnlivou prosbu, kterou jsi prosil přede mnou o smilování: Posvětil jsem tento dům, který jsi postavil, aby tam bylo mé jméno navěky. Mé oči a mé srdce tam budou po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'A co se tebe týče, jestliže budeš přede mnou chodit, jako chodil tvůj otec David s bezúhonným srdcem a v přímosti, budeš činit všechno, co jsem ti přikázal, a zachovávat má ustanovení a má nařízení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'navěky upevním tvůj královský trůn nad Izraelem, jak jsem řekl tvému otci Davidovi: Nebude ti vyhlazen muž z izraelského trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Jestliže se však vy a vaši synové ode mě odvrátíte, nebudete zachovávat mé příkazy a má ustanovení, která jsem vám předložil, ale půjdete a budete sloužit jiným bohům a klanět se jim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'vyhladím Izrael z povrchu země, kterou jsem jim dal, a dům, který jsem posvětil pro své jméno, od sebe odvrhnu. Izrael se stane pořekadlem a posměškem mezi všemi národy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'a tento dům se stane sutinami. Každý, kdo bude procházet kolem něj, se zhrozí, podiví a zeptá se: Proč tohle Hospodin této zemi a tomuto domu provedl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'A ⌈bude se⌉ odpovídat: Protože opustili Hospodina, svého Boha, který vyvedl jejich otce z egyptské země, chytili se jiných bohů, klaněli se jim a sloužili jim, proto na ně Hospodin přivedl všechno toto zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'I stalo se po dvaceti letech, kdy Šalomoun stavěl oba domy, Hospodinův dům a královský palác,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'a týrský král Chíram dodával Šalomounovi cedrové a cypřišové dřevo i zlato, zcela podle jeho přání, že tehdy dal král Šalomoun Chíramovi dvacet měst na území Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Nato Chíram vyjel z Týru podívat se na města, která mu Šalomoun dal, ale nelíbila se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Zeptal se: Co je to za města, která jsi mi dal, můj bratře? A nazval je zemí Kabúl, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Pak poslal Chíram králi sto dvacet talentů zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Toto ⌈ bylo účelem⌉ nucených prací, které král Šalomoun uložil: Stavba Hospodinova domu a jeho domu, Miló, hradeb Jeruzaléma, Chasóru, Megida a Gezeru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '(Faraon, egyptský král, totiž vytáhl a dobyl Gezer; spálil ho ohněm, Kenaance, kteří bydleli ve městě, zabil a dal ho věnem své dceři, Šalomounově ženě.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Šalomoun tedy postavil Gezer, Dolní Bét–chorón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalat a Támar v pustině v judské zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'všechna města pro sklady, které patřily Šalomounovi, města pro vozbu, města pro koně a všechno, co si Šalomoun přál a co toužil postavit v Jeruzalémě, na Libanonu a na celém území jeho vlády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Všechen lid, který zbyl z Emorejců, Chetejců, Perizejců, Chivejců a Jebúsejců, z těch, kteří nebyli ze synů Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'jejich syny, kteří po nich v zemi zbyli, které synové Izraele nedokázali zasvětit zkáze, Šalomoun povolal, aby konali nucené práce, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Ale ze synů Izraele si Šalomoun nevzal otroky, protože oni byli bojovníky, jeho služebníky, jeho veliteli, jeho kapitány, veliteli jeho vozby a jeho jezdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Toto byla ustanovená knížata, která byla nad Šalomounovou prací: Pět set padesát těch, kteří panovali nad lidem, který konal práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Jakmile se faraonova dcera přestěhovala z Města Davidova do svého domu, který pro ni postavil, tehdy postavil Miló.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Šalomoun přinášel třikrát za rok zápalné a pokojné oběti na oltáři, který postavil Hospodinu, a s nimi pálil před Hospodinem i kadidlo. Tak dokončil dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Král Šalomoun si udělal loďstvo v Esjón–geberu, který je u Elótu na břehu Rákosového moře v edómské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Chíram poslal s loďstvem své otroky, námořníky znalé moře, aby byli s otroky Šalomounovými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Připluli do Ofíru, vzali odtamtud čtyři sta dvacet talentů zlata a přivezli králi Šalomounovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Když se královna ze Šeby doslechla zprávy o Šalomounovi ⌈ a že postavil dům pro Hospodinovo jméno,⌉ přišla ho vyzkoušet hádankami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Přijela do Jeruzaléma s ohromným majetkem -- velbloudi nesli balzámy, velké množství zlata a drahokamy. Přišla k Šalomounovi a mluvila s ním o všem, co měla na srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Šalomoun jí od pověděl na všechny otázky; nebylo nic, co by zůstalo králi skryto, na co by jí neodpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Když královna ze Šeby viděla všechnu Šalomounovu moudrost a dům, který postavil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'jídlo na jeho stole, sídlo jeho otroků, ⌈obsluhu jeho služebníků⌉ a jejich oděvy, jeho nápoje a jeho zápalné oběti, které přinášel v Hospodinově domě, ⌈byla bez dechu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Řekla králi: To, co jsem slyšela ve své zemi o tvých slovech a tvé moudrosti, je pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Nevěřila jsem těm zprávám, dokud jsem nepřišla a ne viděla to na vlastní oči. Hle, nebyla mi oznámena ani polovina. Moudrostí a blahobytem jsi předčil zvěsti, které jsem slyšela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Šťastní jsou tvoji muži a šťastní jsou tito tvoji otroci, kteří ⌈ti stále slouží⌉ a naslouchají tvé moudrosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Ať je požehnán Hospodin, tvůj Bůh, který si tě oblíbil a ustanovil tě na izraelský trůn. Protože si Hospodin zamiloval Izrael navěky, ustanovil tě za krále, abys vykonával právo a spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Pak dala králi sto dvacet talentů zlata a velké množství balzámů a drahokamů. Již nikdy nebylo přivezeno takové množství balzámu, jako dala královna ze Šeby králi Šalomounovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Také Chíramovo loďstvo, které dovezlo z Ofíru zlato, přivezlo z Ofíru velké množství almugínového dřeva a drahokamů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Král udělal z almugínového dřeva podpěry pro Hospodinův dům a pro královský palác i lyry a harfy pro zpěváky. Dodnes již nebylo přivezeno ani viděno takové množství almugínového dřeva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Král Šalomoun dal královně ze Šeby všechno, po čem toužila a oč požádala, kromě toho, co jí ⌈král Šalomoun dal sám od sebe.⌉ Pak se vydala na cestu a šla se svými otroky do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Váha zlata, které přivezli Šalomounovi v jednom roce, byla šest set šedesát šest talentů zlata,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'kromě toho, co přivezli kupci, a zisku od obchodníků a všech králů ⌈míšeného lidu ⌉ a místodržitelů země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Král Šalomoun udělal dvě stě velkých štítů z tepaného zlata -- šest set šekelů zlata dal na jeden velký štít --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'a tři sta malých štítů z tepaného zlata -- tři hřivny zlata dal na jeden malý štít. Král je dal do domu Libanonského lesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Král udělal velký trůn ze slonoviny a potáhl ho ryzím zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, '⌈K trůnu vedlo ⌉ šest schodů. Vrchol trůnu byl ze zadní strany okrouhlý a z jedné i druhé strany sedadla byla opěradla. Vedle opěradel stáli dva lvi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Stálo tam dvanáct lvů na šesti schodech z jedné i druhé strany. Nic takového nebylo zhotoveno v žádném království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Všechny nádoby na nápoje krále Šalomouna byly zlaté, všechny nádoby domu Libanonského lesa byly z čistého zlata. Nic nebylo ze stříbra, to bylo ve dnech Šalomounových považováno za nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Král měl na moři taršíšské loďstvo spolu s loďstvem Chíramovým. Jednou za tři roky taršíšské loďstvo připlouvalo a přiváželo zlato a stříbro, slonovinu, opice a paviány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Tak král Šalomoun převyšoval všechny krále země bohatstvím a moudrostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, '⌈ Lidé z celého světa⌉ vyhledávali Šalomounovu přítomnost, aby naslouchali jeho moudrosti, kterou mu Bůh vložil do srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Přinášeli každý svůj dar -- stříbrné a zlaté předměty, pláště, zbraně, balzámy, koně a mezky, a to rok co rok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Šalomoun nashromáždil vozy a koně a měl tisíc čtyři sta vozů a dvanáct tisíc jezdeckých koní. Přivedl je do měst pro vozy a ke králi do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Král učinil stříbro v Jeruzalémě tak hojné jako kamení a cedry tak početné jako sykomory v Šefele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Koně, které měl Šalomoun, se dováželi z Egypta a z Kue. Královští obchodníci je brali z Kue za pevnou cenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, '(Válečný vůz se z Egypta dovážel za šest set stříbrných a kůň za sto padesát.) Jejich prostřednictvím se takto vyvážely všem králům chetejským a aramejským.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Král Šalomoun miloval vedle faraonovy dcery mnoho žen cizinek -- Moábky, Amónky, Edómky, Sidóňanky a Chetejky --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'z národů, o kterých Hospodin synům Izraele řekl: Nevcházejte k nim a ony ať nevcházejí k vám. Jistě by odvrátily vaše srdce k chození ⌈za svými bohy.⌉ K nim Šalomoun přilnul a miloval je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Měl sedm set žen, kněžen, a tři sta konkubín; a jeho ženy odvrátily jeho srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'I stalo se v čase Šalomounova stáří, že jeho ženy odvrátily jeho srdce k chození za jinými bohy a jeho srdce nebylo cele s Hospodinem, jeho Bohem, jako bylo srdce jeho otce Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Šalomoun chodil za Aštoretou, bohyní Sidóňanů, a za Milkómem, ohavnou modlou Amónců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Šalomoun páchal to, co je zlé v Hospodinových očích, a nechodil cele za Hospodinem jako jeho otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Tehdy Šalomoun postavil na hoře, která je naproti Jeruzalému, návrší Kemóšovi, ohavné modle Moábců, a Molekovi, ohavné modle synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Tak učinil pro všechny své ženy cizinky, které pálily kadidlo a obětovaly svým bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Hospodin se na Šalomouna rozhněval, protože se jeho srdce odvrátilo od Hospodina, Boha Izraele, který se mu dvakrát ukázal');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'a dal mu ohledně této věci příkaz, aby nechodil za jinými bohy, ale on nezachoval to, co Hospodin přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Hospodin Šalomounovi řekl: Protože ⌈se s tebou stalo toto⌉ a nezachoval jsi mou smlouvu ani má ustanovení, která jsem ti přikázal, jistě od tebe odtrhnu království a dám je tvému otrokovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Avšak kvůli tvému otci Davidovi to neučiním za tvého života, odtrhnu je od tvého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Ovšem neodtrhnu celé království. Jeden kmen dám tvému synu kvůli svému otroku Davidovi a kvůli Jeruzalému, který jsem si vyvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Hospodin vzbudil Šalomounovi protivníka, Hadada Edómského. Byl z královského potomstva v Edómu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Stalo se totiž, když byl David v Edómu, že velitel armády Jóab vytáhl, aby pohřbil pobité, a zabil všechny mužského pohlaví v Edómu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Šest měsíců tam Jóab a celý Izrael zůstal, dokud nevyhladil všechny mužského pohlaví v Edómu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Hadad ⌈s některými edómskými muži, otroky svého otce,⌉ však utekl a šel do Egypta. Hadad byl ještě malý chlapec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Vystoupili z Midjánu a přišli do Páranu. Vzali s sebou z Páranu nějaké muže a šli do Egypta k faraonovi, egyptskému králi. Ten mu dal dům, určil mu pokrm a dal mu zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadad nalezl ve faraonových očích velkou milost, takže mu dal za ženu sestru své manželky, sestru královny Tachpenésy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Tachpenésina sestra mu porodila syna Genúbata a Tachpenésa ho vychovala ve faraonově domě. Genúbat pobýval ve faraonově domě spolu s faraonovými syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Když se v Egyptě Hadad doslechl, že David ulehl se svými otci a že zemřel velitel armády Jóab, řekl Hadad faraonovi: Propusť mne, abych šel do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Faraon se ho zeptal: Co ti u mě chybí? Proč chceš jít do své země? Odpověděl: Nic. Jenom mě propusť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Bůh mu též vzbudil protivníka Rezóna, syna Eljádova, který utekl od svého pána Hadad–ezera, krále Sóby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Shromáždil k sobě muže a stal se velitelem loupežné hordy, když je David pobíjel. Šli do Damašku, pobývali v něm a kralovali v Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Rezón byl protivníkem Izraele po všechny Šalomounovy dny a páchal zlo jako Hadad. Opovrhoval Izraelem a kraloval nad Aramem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jarobeám, syn Nebatův, Efratejec ze Seredy -- jehož matka se jmenovala Serúa a byla vdova -- Šalomounův otrok, pozvedl ruku proti králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Toto je způsob, jak pozvedl ruku proti králi: Šalomoun postavil Miló a uzavřel trhlinu města svého otce Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Ten Jarobeám byl udatný hrdina. Když Šalomoun viděl mládence, jak dělá svou práci, ustanovil ho nad vší nucenou prací domu Josefova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'I stalo se v onen čas, že Jarobeám vyšel z Jeruzaléma a po cestě ho potkal prorok Achijáš Šíloský. Byl zahalen do nového pláště. Ti dva byli na poli sami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Achijáš uchopil nový plášť, který měl na sobě, a roztrhal ho na dvanáct kusů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Pak řekl Jarobeámovi: Vezmi si deset kusů, neboť ⌈toto praví Hospodin,⌉ Bůh Izraele: Hle, odtrhnu království od Šalomouna a deset kmenů dám tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Jeden kmen bude mít on kvůli mému otroku Davidovi a kvůli Jeruzalému, městu, které jsem vyvolil ze všech izraelských kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'To proto, že mě opustili a klaněli se Aštoretě, bohyni Sidóňanů, a Kemóšovi, bohu Moábců, a Milkómovi, bohu synů Amónových, a nechodili po mých cestách a ne činili to, co je správné v mých očích, má ustanovení a má nařízení, jako jeho otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Nevezmu však od něj celé království, ⌈protože jsem ho určil za předáka⌉ po všechny dny jeho života kvůli svému otroku Davidovi, kterého jsem vyvolil a který zachoval mé příkazy a má ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Vezmu království od jeho syna a dám ho tobě -- deset kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Jeho synovi dám jeden kmen, aby můj otrok David měl po všechny dny lampu přede mnou v Jeruzalémě, městě, které jsem si vyvolil, aby tam bylo mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Tebe vezmu, abys kraloval nad vším, po čem toužíš, a budeš králem nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Jestliže uposlechneš vše, co ti přikazuji, budeš chodit po mých cestách, činit to, co je správné v mých očích, a zachovávat má ustanovení a mé příkazy, jak to činil můj otrok David, budu s tebou, postavím ti trvalý dům, jako jsem postavil Davidovi, a dám ti Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Pokořím sice Davidovo potomstvo kvůli ⌈tomu, co spáchal,⌉ avšak ne napořád.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Šalomoun chtěl Jarobeáma usmrtit. Jarobeám ale vstal, utekl do Egypta k egyptskému králi Šíšakovi a zůstal v Egyptě až do Šalomounovy smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Ostatní ⌈Šalomounovy činy,⌉ všechny věci, které činil, i jeho moudrost, jsou zapsány v knize ⌈Šalomounových letopisů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Doba, po kterou Šalomoun kraloval v Jeruzalémě nad celým Izraelem, byla čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Pak Šalomoun ulehl se svými otci a byl pohřben v městě svého otce Davida. Po něm se stal králem jeho syn Rechabeám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Rechabeám šel do Šekemu, neboť do Šekemu přišel celý Izrael, aby ho ustanovili králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Když se to Jarobeám, syn Nebatův, doslechl, byl ještě v Egyptě, kam utekl před králem Šalomounem. Jarobeám se totiž usadil v Egyptě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Poslali pro něj a zavolali ho. Jarobeám přišel s celým shromážděním Izraele a promluvili k Rechabeámovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Tvůj otec učinil naše jho těžkým. Ty nyní ulehči tvrdou otročinu svého otce a těžké jho, které na nás vložil, a budeme ti sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Odpověděl jim: Odejděte na tři dny a pak se ke mně vraťte. Nato lid odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Král Rechabeám se radil se staršími, kteří sloužili jeho otci Šalomounovi, dokud byl živ: Co radíte odpovědět tomuto lidu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Řekli mu: Jestliže dnes budeš služebníkem tomuto lidu a budeš jim sloužit, odpovíš jim a promluvíš k nim laskavá slova, budou po celou dobu tvými otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Nedbal na radu, ⌈kterou mu dali⌉ starci, a radil se s mladíky, kteří s ním vyrůstali a sloužili mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Zeptal se jich: Co vy radíte, abychom odpověděli tomuto lidu, který mi řekl: Ulehči jho, které na nás vložil tvůj otec?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Mladíci, kteří s ním vyrůstali, mu odpověděli: Toto pověz tomuto lidu, který ti řekl: Tvůj otec učinil naše jho těžkým, ty nám ulehči -- takto k nim promluv: Můj malík je tlustší nežli bedra mého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Nuže, můj otec na vás naložil těžké jho, a já k jeho jhu přidám. Můj otec vás káznil biči, já vás budu káznit důtkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Jarobeám a všechen lid přišel k Rechabeámovi třetího dne, tak jak král řekl: Třetího dne se ke mně vraťte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Král odpověděl lidu tvrdě a nedbal na radu, kterou mu dali starci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Promluvil k nim podle rady mladíků: Můj otec učinil vaše jho těžkým, a já k vašemu jhu přidám. Můj otec vás káznil biči, já vás budu káznit důtkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Král nevyslyšel lid, neboť ⌈nastal zvrat⌉ od Hospodina, aby naplnil své slovo, které Hospodin promluvil prostřednictvím Achijáše Šíloského k Jarobeámovi, synu Nebatovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Když celý Izrael viděl, že je král nevyslyšel, lid odpověděl králi slovy: Jaký máme podíl v Davidovi? Nemáme dědictví v synu Jišajovu! Ke svým stanům, Izraeli! Nyní si hleď svého domu, Davide! A Izrael šel ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Nad syny Izraele, kteří sídlili v judských městech, však kraloval Rechabeám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Král Rechabeám poslal Adoráma, který byl nad nucenými pracemi, ale celý Izrael na něj házel kamení, takže zemřel. Král Rechabeám honem vystoupil na vůz a utekl do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Tak se Izrael vzbouřil proti domu Davidovu, jak je tomu až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Když uslyšel celý Izrael, že se Jarobeám vrátil, poslali pro něj, pozvali ho do shromáždění a ustanovili ho králem nad celým Izraelem. Za domem Davidovým nešel nikdo, jenom sám kmen Juda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Když přišel Rechabeám do Jeruzaléma, shromáždil celý dům judský a kmen Benjamín, sto osmdesát tisíc vybraných bojovníků, aby bojovali s domem izraelským a navrátili království Rechabeámovi, synu Šalomounovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'I stalo se Boží slovo k Šemajášovi, muži Božímu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Řekni judskému králi Rechabeámovi, synu Šalomounovu, a celému domu judskému i Benjamínovi a ostatnímu lidu toto:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Toto praví Hospodin: Netáhněte a nebojujte se svými bratry, syny Izraele. Vraťte se všichni domů, neboť tato věc se stala ode mne. Poslechli Hospodinovo slovo, vrátili se a šli podle Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Jarobeám postavil Šekem v Efrajimském pohoří a sídlil v něm. Odtud vyšel a postavil Penúel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Jarobeám si ⌈v srdci řekl:⌉ Takto by se království mohlo vrátit k domu Davidovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Když bude tento lid přicházet konat oběti do Hospodinova domu v Jeruzalémě, vrátí se srdce tohoto lidu k jejich pánu, k judskému králi Rechabeámovi. Zabijí mě a vrátí se k judskému králi Rechabeámovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Král se poradil, udělal dvě zlatá telata a řekl lidu: Dost dlouho jste chodili do Jeruzaléma. ⌈Hle, toto jsou tvoji bohové,⌉ Izraeli, kteří tě vyvedli z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Jedno umístil do Bét–elu a druhé dal do Danu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'To se stalo hříchem, neboť lid chodil k jednomu až do Danu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Na návrších udělal svatyně a ze spodiny lidu ustanovil kněze, kteří nebyli ze synů Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Jarobeám ustanovil svátek v osmém měsíci, patnáctého dne toho měsíce, jako je svátek v Judsku, a přicházel k oltáři. Tak činil v Bét–elu a obětoval telatům, která udělal, a ustanovil v Bét–elu kněze na návrší, která udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Přišel k oltáři, který udělal v Bét–elu, patnáctého dne osmého měsíce, v měsíci, který si sám vymyslel. Ustanovil svátek pro syny Izraele a přišel k oltáři, aby pálil kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Právě když stál Jarobeám ⌈u oltáře,⌉ aby pálil kadidlo, hle, přišel z Judska do Bét–elu ⌈podle Hospodinova slova⌉ muž Boží');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'a volal proti oltáři podle Hospodinova slova: Oltáři, oltáři, toto praví Hospodin: Hle, Davidovu domu se zrodí syn jménem Jóšijáš a bude na tobě obětovat kněze návrší, kteří na tobě pálí kadidlo, a budou na tobě spáleny lidské kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'A učinil v onen den znamení se slovy: Toto je znamení, že promluvil Hospodin: Hle, oltář se roztrhne a popel, který je na něm, se rozsype.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'I stalo se, když uslyšel král slovo muže Božího, které volal proti oltáři v Bét–elu, že Jarobeám vztáhl svou ruku od oltáře se slovy: Chyťte ho. Ale jeho ruka, kterou proti němu vztáhl, odumřela a nemohl ji dát zpět k sobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Oltář se roztrhl a popel z oltáře se rozsypal jako znamení, které muž Boží učinil podle Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Král promluvil k muži Božímu a řekl: Udobři, prosím, Hospodina, svého Boha, a modli se za mě, ⌈aby se má ruka vrátila ke mně.⌉ Muž Boží udobřil Hospodina, ⌈ruka se vrátila ke králi⌉ a byla jako dříve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Nato král muži Božímu řekl: Pojď se mnou domů, posilni se a dám ti dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Muž Boží králi odpověděl: I kdybys mi dal polovinu svého domu, nepůjdu s tebou, nebudu jíst pokrm ani pít vodu na tomto místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Neboť toto mi bylo přikázáno podle Hospodinova slova: Nejez pokrm ani nepij vodu a nevracej se cestou, kterou jsi přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'A odešel jinou cestou a nevracel se cestou, po které přišel do Bét–elu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'V Bét–elu bydlel jeden starý prorok. Jeho ⌈synové přišli a vypravovali⌉ mu o všech skutcích, které muž Boží ten den v Bét–elu učinil, i slova, která mluvil ke králi. Když to svému otci vypravovali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'jejich otec se jich zeptal: Kterou cestou odešel? Jeho synové mu ukázali cestu, kterou muž Boží, jenž přišel z Judska, odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Řekl svým synům: Osedlejte mi osla. Osedlali mu osla a on na něj nasedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Vydal se za mužem Božím a našel ho sedět pod terebintem. Zeptal se ho: Ty jsi ten muž Boží, který přišel z Judska? Odpověděl: Jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Řekl mu: Pojď se mnou domů a pojez pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Odpověděl: Nemohu se vrátit s tebou ani jít s tebou. Nebudu jíst pokrm ani pít s tebou vodu na tomto místě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'neboť ⌈musím jednat⌉ podle Hospodinova slova: Nejez tam pokrm ani nepij vodu, nevracej se tak, že by ses ubíral cestou, po které jsi přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Řekl mu: Také já jsem prorok jako ty a promluvil ke mně anděl podle Hospodinova slova takto: Přiveď ho s sebou do svého domu. Ať pojí pokrm a napije se vody. Lhal mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'On se s ním vrátil, pojedl v jeho domě pokrm a napil se vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Když seděli u stolu, tu se stalo Hospodinovo slovo k proroku, který ho přivedl zpět,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'a zvolal na muže Božího, který přišel z Judska: Toto praví Hospodin: Protože ses vzepřel Hospodinovu příkazu a nedbal jsi na příkaz, který ti dal Hospodin, tvůj Bůh,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'ale vrátil ses a pojedl jsi chléb a napil ses vody na místě, o kterém ti řekl: Nejez tam pokrm ani nepij vodu, nepřijde tvá mrtvola do hrobu tvých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Potom, co pojedl pokrm a napil se, osedlal pro něj osla -- ⌈pro proroka, kterého⌉ přivedl zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'On vyjel, ale cestou ho dopadl lev a usmrtil ho. I stalo se, že jeho mrtvola byla pohozena na cestě. Osel stál vedle ní a také lev stál vedle mrtvoly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Vtom procházeli okolo nějací muži a viděli mrtvolu pohozenou na cestě i lva stojícího vedle mrtvoly. Přišli a povídali o tom ve městě, ve kterém bydlel ten starý prorok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Když se to doslechl ten prorok, který ho přivedl zpět z cesty, řekl: To je muž Boží, který se vzepřel Hospodinovu příkazu. Hospodin ho vydal lvu a ten ho roztrhal a usmrtil podle slova, které k němu Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Nato řekl svým synům: Osedlejte mi osla. Osedlali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Vyjel a našel prorokovu mrtvolu pohozenou na cestě i osla a lva stojící vedle mrtvoly. Lev nesežral mrtvolu ani neroztrhal osla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Prorok zvedl mrtvolu muže Božího, položil ji na osla a vezl ji zpět. ⌈Přišel do města toho starého proroka,⌉ naříkal nad ním a pohřbil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Položil jeho mrtvolu do svého hrobu a oplakávali ho: Běda, můj bratře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'I stalo se poté, co ho pohřbil, že řekl svým synům: Až zemřu, pohřběte mě do hrobu, ve kterém je pohřben muž Boží, vedle jeho kostí položte mé kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Neboť se jistě stane to, co volal podle Hospodinova slova proti oltáři, který je v Bét–elu, a proti všem svatyním návrší, které jsou v samařských městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Ani po této události se Jarobeám neodvrátil od své zlé cesty a nadále ze spodiny lidu ustanovoval kněze návrší. Toho, kdo chtěl, potvrdil, takže se stal jedním z kněží návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Tímto se stal dům Jarobeámův hříšným, aby byl vymazán a vyhlazen z povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'V té době onemocněl Abijáš, syn Jarobeámův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Jarobeám své ženě řekl: Vstaň, převleč se, aby ⌈ nikdo nepoznal,⌉ že jsi Jarobeámova žena, a jdi do Šíla. Tam je prorok Achijáš, který o mně pověděl, že budu králem nad tímto lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Vezmi si s sebou deset chlebů, koláčky, lahvici medu a jdi za ním. On ti oznámí, co se stane s chlapcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Jarobeámova žena to udělala. Vstala, šla do Šíla a vstoupila do Achijášova domu. Achijáš neviděl, protože jeho oči byly strnulé věkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Hospodin však řekl Achijášovi: Hle, přichází Jarobeámova žena, ⌈aby se tě dotázala⌉ ohledně svého syna, neboť je nemocen. To a to jí řekni. Až přijde, bude ⌈se vydávat za někoho jiného.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'I stalo se, když Achijáš uslyšel zvuk jejích kroků, jak vcházela do dveří, řekl: Vejdi, ženo Jarobeámova! Proč se vydáváš za někoho jiného? Jsem k tobě poslán s tvrdou odpovědí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Jdi a řekni Jarobeámovi: Toto praví Hospodin, Bůh Izraele: Protože jsem tě vyvýšil zprostřed lidu a ustanovil jsem tě vévodou nad svým lidem Izraelem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'odtrhl jsem království od domu Davidova a dal jsem ho tobě. Ale ty jsi nebyl jako můj otrok David, který zachovával mé příkazy, chodil za mnou ⌈celým svým srdcem⌉ a činil pouze to, co je správné v mých očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Páchal jsi ještě větší zlo nežli všichni, kdo byli před tebou. Šel jsi a učinil sis jiné bohy a lité modly a provokoval jsi mě k hněvu. Odvrhl jsi mě za svá záda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Proto hle, přivedu zlo na dům Jarobeámův a vyhladím Jarobeámovi ⌈močícího na stěnu,⌉ ⌈zadržovaného i propuštěného⌉ v Izraeli, vyhladím potomky domu Jarobeámova tak, jako se uklízejí výkaly, zcela je vyhladím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Toho, kdo zemře Jarobeámovi ve městě, sežerou psi, a toho, kdo zemře na poli, pohltí nebeské ptactvo, neboť Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Ty vstaň a jdi domů. Až vstoupí tvoje noha do města, chlapec zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Celý Izrael ho bude oplakávat a pohřbí ho. Tento jediný přijde Jarobeámovi do hrobu, protože pouze při něm bylo v domě Jarobeámově shledáno před Hospodinem, Bohem Izraele, něco dobrého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Hospodin si vzbudí krále nad Izraelem, který vyhladí dům Jarobeámův -- ⌈dnes, ba co, dokonce nyní!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Hospodin bude bít Izrael, takže se bude klátit jako třtina ve vodě. Vyrve Izrael z této dobré země, kterou dal jejich otcům a rozptýlí je za Řeku, protože si učinili posvátné kůly a tak provokovali Hospodina k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Vydá Izrael kvůli Jarobeámovým hříchům, kterými hřešil a kterými svedl k hříchu Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Jarobeámova žena vstala, šla a vešla do Tirsy. Když vcházela přes práh domu, chlapec zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Pohřbili ho a ⌈celý Izrael ho oplakával⌉ ⌈podle Hospodinova slova, které promluvil prostřednictvím⌉ svého otroka, proroka Achijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Ostatní Jarobeámovy činy, jak bojoval a kraloval, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Doba, po kterou Jarobeám kraloval, byla dvacet dva let. Pak ulehl se svými otci. Po něm se stal králem jeho syn Nádab.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Rechabeám, syn Šalomounův, kraloval v Judsku. Rechabeámovi bylo čtyřicet jedna let, když se stal králem, a sedmnáct let kraloval v Jeruzalémě, městě, které si Hospodin vyvolil ze všech izraelských kmenů, aby tam bylo jeho jméno. Jeho matka se jmenovala Naama Amónská.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Juda páchal to, co je zlé v Hospodinových očích. Svými hříchy, kterými hřešili, ho dráždili k žárlivosti víc než tím, co páchali jejich otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Také oni si postavili návrší, posvátné sloupy a posvátné kůly na každém vyvýšeném návrší a pod každým zeleným stromem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Dokonce i chrámoví smilníci byli v zemi. Páchali všechny ohavnosti pohanských národů, které Hospodin před syny Izraele vyhnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'I stalo se, že v pátém roce vlády krále Rechabeáma vytáhl proti Jeruzalému egyptský král Šíšak');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'a pobral poklady Hospodinova domu i poklady královského paláce, všechno to pobral. Vzal také všechny zlaté malé štíty, které udělal Šalomoun.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Král Rechabeám místo nich udělal štíty bronzové a svěřil je pod velení velitelů běžců, kteří střežili vchod do královského paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Pokaždé, když šel král do Hospodinova domu, přinášeli je běžci a pak je vraceli zpět do síně běžců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Ostatní Rechabeámovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Po celou dobu trval boj mezi Rechabeámem a Jarobeámem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Rechabeám ulehl se svými otci a byl pohřben se svými otci v Městě Davidově. Jeho matka se jmenovala Naama Amónská. Po něm se stal králem jeho syn Abijám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'V osmnáctém roce vlády krále Jarobeáma, syna Nebatova, se stal králem nad Judou Abijám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Kraloval v Jeruzalémě tři roky. Jeho matka se jmenovala Maaka, dcera Abíšalómova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, '⌈Chodil ve všech hříších⌉ svého otce, které on před ním páchal, a jeho srdce nebylo cele s Hospodinem, jeho Bohem, jako bylo srdce Davida, jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Avšak kvůli Davidovi mu Hospodin, jeho Bůh, dal lampu v Jeruzalémě, když po něm ⌈dal povstat⌉ jeho synu a upevnil Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Protože David činil to, co bylo správné v Hospodinových očích, a po všechny dny svého života se neodvrátil od ničeho, co mu přikázal, ⌈kromě záležitosti⌉ Urijáše Chetejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Boj mezi Rechabeámem a Jarobeámem trval po všechny dny jeho života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Ostatní Abijámovy činy, všechny věci, které činil, jsou zapsány v knize Letopisů judských králů. Mezi Abijámem a Jarobeámem trval boj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Abijám ulehl se svými otci a pohřbili ho v Městě Davidově. Po něm se stal králem jeho syn Ása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Ve dvacátém roce vlády izraelského krále Jarobeáma se stal judským králem král Ása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Kraloval v Jeruzalémě čtyřicet jedna let. Jeho matka se jmenovala Maaka, dcera Abíšalómova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Ása činil to, co je správné v Hospodinových očích, jako jeho otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Vyhnal ze země chrámové smilníky a odstranil všechny bůžky, které udělali jeho otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Tak i svou matku Maaku; odstranil ji z postavení královny, protože učinila ohavnou modlu pro Ašeru. Ása pokácel její ohavnou modlu a spálil ji v údolí Kidrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Návrší sice nebyla odstraněna, ovšem Ásovo srdce bylo po všechny jeho dny cele s Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Přinesl do Hospodinova domu svaté věci svého otce i své vlastní -- stříbro, zlato a různé předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Boj mezi Ásou a izraelským králem Baešou trval po všechny jejich dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Izraelský král Baeša vytáhl proti Judsku. Postavil Rámu, aby ⌈nedovolil judskému králi Ásovi vycházet a vcházet.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Ása vzal všechno stříbro a zlato ponechané v pokladnicích Hospodinova domu i poklady královského domu a dal je do ruky svých otroků. Král Ása je poslal Ben–hadadovi, synu Tabrimóna, synu Chezjóna, králi Aramu, sídlícímu v Damašku, se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Mezi mnou a tebou, mezi mým otcem a tvým otcem je smlouva. Hle, posílám ti dar, stříbro a zlato. Jdi a zruš svou smlouvu s izraelským králem Baešou, ať ode mě odtáhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Ben–hadad uposlechl krále Ásu; velitele vojsk, které měl, poslal proti izraelským městům a pobil Ijón, Dan, Ábel–bét–maaku a celý Kinerót s celým územím Neftalí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'I stalo se, když to uslyšel Baeša, že přestal stavět Rámu a usadil se v Tirse.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Král Ása ⌈oznámil v celém Judsku,⌉ takže nikdo nebyl toho zproštěn, aby odnesli z Rámy kameny i dřevo, ze kterého Baeša stavěl. Král Ása pak z toho postavil Gebu Benjamínovu a Mispu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Všechny ostatní Ásovy činy, všechny jeho ⌈udatné skutky ⌉ a všechny věci, které činil, i města, která postavil, jsou zapsána v knize Letopisů judských králů, ⌈kromě toho, že v čase svého⌉ stáří onemocněl na nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Pak Ása ulehl se svými otci a byl pohřben se svými otci v městě svého otce Davida. Po něm se stal králem jeho syn Jóšafat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nádab, syn Jarobeámův, se stal králem nad Izraelem v druhém roce vlády judského krále Ásy. Kraloval nad Izraelem dva roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Páchal to, co je zlé v Hospodinových očích, a chodil po cestě svého otce a v jeho hříchu, kterým svedl k hříchu Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Spikl se proti němu Baeša, syn Achijášův, z domu Isacharova. Baeša ho zabil u Gibetónu, který patřil Pelištejcům, když Nádab a celý Izrael obléhali Gibetón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Baeša ho usmrtil v třetím roce vlády judského krále Ásy a kraloval místo něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Když se stal králem, pobil celý dům Jarobeámův, neponechal Jarobeámovi nic, co má dech, zcela ho vyhladil podle Hospodinova slova, které promluvil prostřednictvím svého otroka Achijáše Šíloského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'To kvůli Jarobeámovým hříchům, kterými hřešil a kterými svedl k hříchu Izrael, a kvůli jeho provokacím, kterými provokoval ke hněvu Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Ostatní Nádabovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Boj mezi Ásou a izraelským králem Baešou trval po všechny jejich dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Ve třetím roce vlády judského krále Ásy se stal králem nad celým Izraelem Baeša, syn Achijášův; kraloval v Tirse dvacet čtyři let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Páchal to, co je zlé v Hospodinových očích, a chodil po cestě Jarobeáma a v jeho hříchu, kterým svedl k hříchu Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Stalo se Hospodinovo slovo k Jehúovi, synu Chananího, proti Baešovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Ačkoli jsem tě pozvedl z prachu a ustanovil jsem tě vévodou nad svým lidem Izraelem, chodil jsi po cestě Jarobeámově a svedl jsi k hříchu můj lid Izrael, takže mě provokovali svými hříchy k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Hle, vyhladím potomky Baešovy i potomky jeho domu a učiním s tvým domem to, co s domem Jarobeáma, syna Nebatova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Toho, kdo zemře Baešovi ve městě, sežerou psi, a toho, kdo mu zemře na poli, pohltí nebeské ptactvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Ostatní Baešovy činy, to, co činil, i jeho udatné skutky, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'I ulehl Baeša se svými otci a byl pohřben v Tirse. Po něm se stal králem jeho syn Éla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Tak i prostřednictvím proroka Jehúa, syna Chananího, se stalo Hospodinovo slovo proti Baešovi a proti jeho domu za všechno zlo, které páchal v Hospodinových očích, když ho provokoval k hněvu dílem svých rukou a byl jako dům Jarobeámův, i za to, že krále zabil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Ve dvacátém šestém roce vlády judského krále Ásy se stal králem nad Izraelem Éla, syn Baešův. Kraloval v Tirse dva roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Spikl se proti němu jeho otrok Zimrí, velitel poloviny vozby. Když byl král v Tirse a opíjel se v domě Arsy, který byl nad domem v Tirse,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zimrí přišel a ⌈bil ho, až ho usmrtil⌉ v dvacátém sedmém roce vlády judského krále Ásy a stal se po něm králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Když se stal králem a usedl na svůj trůn, pobil celý dům Baešův, neponechal mu ⌈močícího na stěnu⌉ ani jeho příbuzné, ani jeho přítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Zimrí vyhladil celý dům Baešův podle Hospodinova slova, které promluvil proti Baešovi prostřednictvím proroka Jehúa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'za všechny hříchy Baešovy i hříchy jeho syna Ély, kterými hřešili a sváděli Izrael k hříchu, když svými nicotnými modlami provokovali Hospodina, Boha Izraele, k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Ostatní Élovy činy, všechny věci, které činil, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'V dvacátém sedmém roce vlády judského krále Ásy se stal králem Zimrí. Kraloval v Tirse sedm dní. Lid tábořil u Gibetónu, který patřil Pelištejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Když se tábořící lid doslechl, že se Zimrí spikl a zabil krále, celý Izrael toho dne v táboře ustanovil králem Omrího, velitele armády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Omrí a s ním celý Izrael odtáhl od Gibetónu a oblehli Tirsu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'I stalo se, když Zimrí viděl, že město bylo dobyto, šel do pevnosti královského domu, zapálil nad sebou královský dům, a tak zemřel');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'za svoje hříchy, kterými hřešil, když páchal to, co je zlé v Hospodinových očích, a chodil po cestě Jarobeáma i v jeho hříchu, který činil, a sváděl Izrael ke hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Ostatní činy Zimrího i jeho spiknutí, které zosnoval, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Tehdy se izraelský lid rozdělil na dvě poloviny: Polovina lidu byla za Tibním, synem Ginatovým, aby ho ustanovila králem, a polovina za Omrím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Lid, který byl za Omrím, přemohl lid, který byl za Tibním, synem Ginatovým. Tibní zemřel a králem se stal Omrí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'V třicátém prvním roce vlády judského krále Ásy se stal králem nad Izraelem Omrí; kraloval dvanáct let. V Tirse kraloval šest let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Pak koupil od Šemera za dva talenty stříbra horu Samaří. Obstavěl horu a městu, které postavil, dal jméno Samaří podle jména pána té hory, Šemera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Omrí páchal to, co je zlé v Hospodinových očích, páchal větší zlo než všichni, kdo byli před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Chodil po všech cestách Jarobeáma, syna Nebatova, a v jeho hříchu, kterým svedl k hříchu Izrael, když svými nicotnými modlami provokovali Hospodina, Boha Izraele, k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Ostatní činy Omrího, které činil, i jeho udatné skutky, které vykonal, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Omrí ulehl se svými otci a byl pohřben v Samaří. Po něm se stal králem jeho syn Achab.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Achab, syn Omrího, se stal králem nad Izraelem v třicátém osmém roce vlády judského krále Ásy. Achab, syn Omrího, kraloval nad Izraelem v Samaří dvacet dva let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Achab, syn Omrího, páchal to, co je zlé v Hospodinových očích, víc než všichni, kdo byli před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Jako by to bylo málo, že chodil v hříších Jarobeáma, syna Nebatova, vzal si za ženu Jezábelu, dceru sidónského krále Etbaala, a chodil sloužit Baalovi a klanět se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Postavil Baalovi oltář v Baalově domě, který vybudoval v Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Achab též udělal posvátný kůl. Achab udělal ještě více, aby provokoval Hospodina, Boha Izraele, k hněvu, než všichni izraelští králové, kteří byli před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, '⌈V jeho dnech⌉ postavil Chíel Bételský Jericho. Na svém prvorozeném Abíramovi položil jeho základy a na svém nejmladším Segúbovi postavil jeho vrata podle Hospodinova slova, které promluvil prostřednictvím Jozua, syna Núnova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Elijáš Tišbejský z Tišbé v Gileádu řekl Achabovi: Jakože živ je Hospodin, Bůh Izraele, jemuž sloužím, v těchto letech nebude rosa ani déšť, jenom podle mého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'I stalo se k němu Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Jdi odsud, vydej se na cestu na východ a ukryj se u potoka Kerítu, který je naproti Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'I stane se, že budeš pít z potoka, a havranům jsem přikázal, aby tam o tebe pečovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'On šel a jednal podle Hospodinova slova. Odešel a pobýval u potoka Kerítu, který je naproti Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Havrani mu přinášeli chléb i maso ráno a chléb i maso večer a pil z potoka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Po nějakém čase se stalo, že potok vyschl, protože v zemi nebyl déšť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Stalo se k němu Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Vstaň, jdi do Sarepty, která patří Sidónu, a pobývej tam. Hle, přikázal jsem tam jedné vdově, aby o tebe pečovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Vstal tedy a odešel do Sarepty. Když přišel ke vchodu do města, uviděl tam vdovu, jak sbírá dříví. Zavolal na ni: Podej mi, prosím, trochu vody v nádobě, abych se napil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Když šla, aby to přinesla, zavolal na ni: Vezmi mi, prosím, s sebou i kousek chleba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Řekla: Jakože živ je Hospodin, tvůj Bůh, nemám ani koláček, jenom hrst mouky ve džbánu a trochu oleje ve džbánku. Podívej, sbírám pár kousků dříví, abych to šla udělat pro sebe a svého syna, sníme to a zemřeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elijáš jí řekl: Neboj se. Jdi a učiň podle svého slova. Avšak nejprve z toho udělej malý chléb pro mě a přines mi to. Pro sebe a pro svého syna udělej potom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Neboť toto praví Hospodin, Bůh Izraele: Mouka ve džbánu nedojde a oleje ve džbánku nebude nedostatek až do dne, kdy dá Hospodin déšť na povrch země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Šla a učinila podle Elijášova slova a jedla ona i on a její dům po mnoho dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Mouka ve džbánu nedošla a oleje ve džbánku nebyl nedostatek podle Hospodinova slova, které promluvil prostřednictvím Elijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Po těchto událostech se stalo, že syn té ženy, paní domu, onemocněl a jeho nemoc byla velmi těžká, takže v něm nezůstal dech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Žena řekla Elijášovi: Co ⌈ je ti do mě,⌉ muži Boží? Přišel jsi ke mně, abys mi připomenul mou vinu a usmrtil mého syna?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Odpověděl jí: Dej mi svého syna. Vzal ho z jejího klína, vynesl ho do horní místnosti, kde bydlel, a položil ho na svou postel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Potom volal k Hospodinu: Hospodine, můj Bože, což i se vdovou, u níž pobývám jako cizinec, naložíš zle a usmrtíš jejího syna?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Natáhl se třikrát na chlapce a volal k Hospodinu: Hospodine, můj Bože, ať se vrátí ⌈duše tohoto chlapce do jeho nitra.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Hospodin vyslyšel Elijáše, chlapcova duše se vrátila do jeho nitra a ožil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Elijáš vzal chlapce, snesl ho z horní místnosti do domu a dal ho jeho matce. Pak Elijáš řekl: Pohleď, tvůj syn žije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Žena Elijášovi odpověděla: ⌈Teď vím, že⌉ jsi Boží muž a Hospodinovo slovo ve tvých ústech je pravdivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Přešlo mnoho dní, když se třetího roku stalo Hospodinovo slovo k Elijášovi: Jdi, ukaž se Achabovi. Dám déšť na povrch země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Elijáš šel, aby se ukázal Achabovi. V Samaří byl krutý hlad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Achab si zavolal Obadjáše, který byl nad domem. Obadjáš se velmi bál Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Stalo se, že když Jezábel vyhlazovala Hospodinovy proroky, Obadjáš vzal sto proroků, ukryl je po padesáti v jeskyni a zásoboval je chlebem a vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Achab řekl Obadjášovi: Jdi v zemi ke všem pramenům vody a ke všem potokům. Snad se najde tráva, abychom zachovali koně a mezky při životě a ne museli vyhladit žádné ze zvířat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Rozdělili si zemi, aby jí procházeli. Achab šel sám jednou cestou a Obadjáš šel sám druhou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Když byl Obadjáš na cestě, hle, potkal ho Elijáš. Jakmile jej Obadjáš zpozoroval, padl na tvář a zeptal se: Jsi to ty, můj pane, Elijáši?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Odpověděl mu: Jsem. Jdi, pověz svému pánu: Je zde Elijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Nato on řekl: Čím jsem zhřešil, že dáváš svého otroka do ruky Achaba, aby mě usmrtil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Jakože živ je Hospodin, tvůj Bůh, není národ či království, kde by tě můj pán nenechal hledat. Když řekli: Není zde, nechal království či národ přísahat, že tě nenašli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'A ty nyní říkáš: Jdi, pověz svému pánu: Je zde Elijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'I stane se, až od tebe odejdu, že tě Hospodinův Duch odnese nevím kam. Já to půjdu oznámit Achabovi, on tě nenajde a zabije mě. Tvůj otrok se přece od svého mládí bojí Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Což nebylo oznámeno mému pánu, co jsem udělal, když Jezábel zabíjela Hospodinovy proroky? Ukryl jsem ⌈sto z Hospodinových proroků vždy po padesáti⌉ v jeskyni a zásoboval jsem je chlebem a vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'A ty nyní říkáš: Jdi, pověz svému pánu: Je zde Elijáš. Vždyť mě zabije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elijáš řekl: Jakože živ je Hospodin zástupů, jemuž sloužím, dnes se mu ukážu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Obadjáš šel vstříc Achabovi a oznámil mu to. Nato šel Achab vstříc Elijášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'I stalo se, když uviděl Achab Elijáše, Achab se ho zeptal: Jsi to ty, kdo ⌈přivádí zkázu na Izrael?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Odpověděl mu: Zkázu na Izrael nepřivádím já, ale ty a dům tvého otce, když opouštíte Hospodinovy příkazy a chodíte za baaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Nyní vzkaž a shromáždi ke mně na horu Karmel celý Izrael i čtyři sta padesát Baalových proroků a čtyři sta Ašeřiných proroků, kteří jídají u Jezábelina stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Achab vzkázal mezi všechny syny Izraele a shromáždil proroky na horu Karmel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Tehdy Elijáš přistoupil ke všemu lidu a řekl: Jak dlouho budete kulhat ⌈na dvě strany?⌉ Jestliže je Bohem Hospodin, jděte za ním, a jestliže Baal, jděte za ním. Lid mu nic neodpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Elijáš řekl lidu: Já sám jsem zůstal Hospodinovým prorokem a Baalových proroků je čtyři sta padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Ať nám jsou dáni dva býčci. Jednoho býčka ať si vyberou oni, rozsekají ho na kusy, položí na dříví, ale oheň ať nerozdělávají. Já připravím druhého býčka, dám ho na dříví, ale oheň nerozdělám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Pak vzývejte jméno ⌈svého boha⌉ a já budu vzývat jméno Hospodinovo. Bůh, který odpoví ohněm, ten je Bohem. Všechen lid odpověděl: Dobře jsi promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Elijáš řekl Baalovým prorokům: Vyberte si jednoho býčka a připravte ho první, protože vás je víc. Vzývejte jméno svého boha, ale oheň nerozdělávejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Nato vzali býčka, kterého jim dal, připravili ho a vzývali Baalovo jméno od rána až do poledne se slovy: Baale, odpověz nám! Ale ⌈žádný o hlas, nikdo neodpovídal. Přitom⌉ poskakovali kolem oltáře, který udělali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Když nastalo poledne, Elijáš se jim posmíval: Volejte hlasitě, vždyť je to bůh. Snad ⌈je zaneprázdněn⌉ nebo má nutkání. Třeba je na cestě. Možná spí, ať se probere.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Volali hlasitě a dle svého zvyku si zasazovali rány meči a oštěpy, až jim tekla krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Když přešlo poledne, ⌈chovali se jako proroci⌉ až do doby, kdy se přináší přídavná oběť, ale žádný o hlas, nikdo neodpovídal, nikdo tomu nevěnoval pozornost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Pak řekl Elijáš všemu lidu: Přistupte ke mně. Všechen lid k němu přistoupil. On opravil Hospodinův oltář, který byl pobořen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Elijáš vzal dvanáct kamenů podle počtu kmenů synů Jákoba, ke kterému se stalo Hospodinovo slovo: Budeš se jmenovat Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Z kamenů postavil oltář v Hospodinově jménu a udělal okolo oltáře příkop na dvě míry zrna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Narovnal dříví, rozsekal býčka na kusy a položil ho na dříví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Pak řekl: Naplňte čtyři džbány vodou a vylejte ji na zápalnou oběť i na dříví. Nato řekl: Udělejte to znovu. Udělali to znovu a on řekl: Udělejte to potřetí, a udělali to potřetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Voda tekla okolo oltáře a naplnila také příkop.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Když nastal čas přinášení přídavné oběti, přistoupil prorok Elijáš a řekl: Hospodine, Bože Abrahamův, Izákův a Izraelův, kéž se dnes pozná, že ty jsi Bůh v Izraeli a já jsem tvůj otrok a všechny tyto věci jsem učinil podle tvého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Odpověz mi, Hospodine, odpověz mi, ať tento lid pozná, že ty, Hospodine, jsi Bůh; a ty sám obracíš jejich srdce nazpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Nato spadl Hospodinův oheň a strávil zápalnou oběť i dříví, kameny a prach a vylízal vodu, která byla v příkopu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Když to všechen lid uviděl, padli na tvář a volali: Hospodin je Bůh, Hospodin je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elijáš jim řekl: Chyťte Baalovy proroky, nikdo z nich ať neunikne. Když je chytili, zavedl je Elijáš k potoku Kíšón a tam je pobil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Elijáš řekl Achabovi: Jdi, jez a pij, neboť ⌈slyším hukot deště.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Achab šel jíst a pít. Elijáš vystoupil na vrchol Karmelu, sklonil se k zemi a vložil svou tvář mezi kolena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Svému služebníkovi řekl: Jdi a podívej se směrem k moři. Šel, podíval se a řekl: Nic tam není. ⌈Řekl: Sedmkrát se vrať.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Když to bylo posedmé, řekl: Hle, oblak malý jako lidská dlaň vystupuje z moře. Řekl: Jdi a řekni Achabovi: Zapřáhni a jeď, ať tě nezadrží déšť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, '⌈Za chvíli⌉ se zatměla nebesa oblaky a větrem a nastal velký déšť. Achab nasedl a jel do Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Hospodinova ruka byla s Elijášem, takže si přepásal bedra a běžel před Achabem, až dorazil do Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Achab pověděl Jezábele všechno, co Elijáš udělal, i to, jak zabil mečem všechny proroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Jezábel poslala k Elijášovi posla se slovy: Tak ať mi učiní bohové, a ještě přidají, jestliže zítra touto dobou ne učiním tvou duši podobnou duši jednoho z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Když to uviděl, vstal a šel, aby ⌈zachránil svou duši,⌉ a přišel do Beer–šeby, která je v Judsku. Tam zanechal svého služebníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Sám pak šel do pustiny na den cesty. Přišel, posadil se pod jeden janovec a přál si zemřít: Už dost, Hospodine, vezmi mou duši, neboť nejsem lepší nežli moji otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Ulehl a usnul pod janovcem. Vtom se ho dotkl anděl a řekl mu: Vstaň a pojez.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Podíval se a uviděl, že u hlavy má chléb upečený na žhavém uhlí a džbánek vody. Najedl se a napil a znovu ulehl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Hospodinův anděl se ho dotkl zase, podruhé, a řekl: Vstaň a pojez, neboť je před tebou dlouhá cesta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Vstal, najedl se a napil a šel v síle toho pokrmu čtyřicet dní a čtyřicet nocí až na Boží horu Choréb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Vstoupil tam do jeskyně a nocoval tam. Vtom se k němu stalo Hospodinovo slovo. Řekl mu: Co ⌈ty tady,⌉ Elijáši?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Odpověděl: Velmi jsem horlil pro Hospodina, Boha zástupů, protože synové Izraele opustili tvou smlouvu, zbořili tvé oltáře a tvé proroky zabili mečem. Zůstal jsem já sám a také mně usilují o život, aby mi jej vzali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Řekl: Jdi a postav se na hoře před Hospodinem. A hle, Hospodin prošel kolem. Nastal velký a silný vítr, rozrážející hory a drtící skály před Hospodinem, ale Hospodin v tom větru nebyl. Po větru země třesení, ale Hospodin v tom země třesení nebyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Po země třesení oheň, ale Hospodin v tom ohni nebyl. Po ohni tichý a jemný hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Když ho Elijáš uslyšel, zavinul svou tvář pláštěm, šel a postavil se u vchodu do jeskyně; a hle stal se k němu hlas: Co ty tady, Elijáši?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Odpověděl: Velmi jsem horlil pro Hospodina, Boha zástupů, protože synové Izraele opustili tvou smlouvu, zbořili tvé oltáře a tvé proroky zabili mečem. Zůstal jsem já sám, a také mně usilují o život, aby mi jej vzali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Hospodin mu řekl: Jdi, vrať se svou cestou do damašské pustiny. A až tam přijdeš, pomaž Chazaela za krále nad Aramem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Jehúa, syna Nimšího, pomaž za krále nad Izraelem a Elíšu, syna Šáfatova z Ábel–mechóly, pomaž za proroka místo sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'I stane se, že kdo unikne před mečem Chazaelovým, toho usmrtí Jehú, a kdo unikne před mečem Jehúovým, toho usmrtí Elíša.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Ponechám však v Izraeli sedm tisíc -- všechna kolena, která se nesklonila před Baalem, a všechna ústa, která ho nelíbala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Nato odtamtud odešel a našel Elíšu, syna Šáfatova, který oral. Dvanáct jiter bylo před ním a on byl na dvanáctém. Elijáš prošel okolo něj a hodil na něj svůj plášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Opustil skot, běžel za Elijášem a řekl: Dovol, ať políbím svého otce a svou matku, a pak půjdu za tebou. Řekl mu: Jdi a vrať se pro to, co jsem ti učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Když se od něj vrátil, vzal dobytčí spřežení a zabil je; na dobytčím jhu uvařil ⌈jejich maso,⌉ dal lidu a najedli se. Pak vstal a šel za Elijášem a sloužil mu. –');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Aramejský král Ben–hadad shromáždil všechno své vojsko; bylo s ním třicet dva králů, koně i vozba. Vytáhl, oblehl Samaří a bojoval proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Poslal do města k izraelskému králi Achabovi posly');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'a řekl mu: Toto praví Ben–hadad: Mně patří tvé stříbro a tvé zlato, mně patří tvé ženy a tvoji nejlepší synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Izraelský král odpověděl: Jak jsi řekl, můj pane a králi, tobě patřím já i všechno, co mám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Poslové se vrátili a řekli: Toto praví Ben–hadad: Poslal jsem k tobě se slovy: Dej mi své stříbro a své zlato, své ženy i své syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Ale zítra touto dobou k tobě pošlu své otroky a prohledají tvůj dům i domy tvých otroků a všechno, co je vzácné tvým očím, vezmou s sebou a poberou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Izraelský král zavolal všechny starší země a řekl: ⌈Rozvažte a pohleďte,⌉ že tento muž usiluje o zlo. Vždyť ke mně poslal pro mé ženy a mé syny, pro mé stříbro a pro mé zlato a neodepřel jsem mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Všichni starší a všechen lid mu řekli: Neposlouchej ho a nepodvoluj se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Nato řekl Ben–hadadovým poslům: Řekněte mému pánu a králi: Všechno, co jsi vzkázal svému otroku poprvé, udělám, ale tuto věc učinit nemohu. Poslové odešli a takto odpověděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Ben–hadad mu vzkázal: Tak ať mi učiní bohové, a ještě přidají, jestliže bude dost prachu ze Samaří na hrst pro všechen lid, který jde v mých stopách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Izraelský král odpověděl: Řekněte mu: ⌈Ať se ten, kdo se opásává mečem, nechlubí jako ten, kdo si ho odepíná.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'I stalo se, když uslyšel tuto zprávu -- popíjel právě ⌈s králi⌉ ve stanech -- že řekl svým otrokům: ⌈Připravte se k útoku.⌉ A připravili se k útoku na město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'A hle, nějaký prorok přistoupil k izraelskému králi Achabovi a řekl: Toto praví Hospodin: Vidíš celý ten velký dav? Hle, vydám ho dnes do tvé ruky a poznáš, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Achab se zeptal: Skrze koho? Odpověděl: Toto praví Hospodin: Skrze služebníky velitelů provincií. Zeptal se: Kdo rozpoutá boj? Odpověděl: Ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Nato spočítal služebníky velitelů provincií a bylo jich dvě stě třicet dva. Po nich spočítal všechen lid. Všech synů Izraele bylo sedm tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Vytáhli za poledne, zatímco se Ben–hadad s třiceti dvěma králi, které měl na pomoc, ve stanech opíjeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Služebníci velitelů provincií vytáhli první. ⌈Ben–hadadovi vzkázali⌉ a oznámili: Ze Samaří vytáhli nějací muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Řekl: Jestliže vytáhli v pokoji, chyťte je živé, jestliže vytáhli k boji, živé je chyťte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Z města vytáhli tito: Služebníci velitelů provincií a za nimi vojsko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Muž pobíjel muže, Aramejci utíkali a Izraelci je pronásledovali. Aramejský král Ben–hadad se zachránil na koni s dalšími jezdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Izraelský král vyrazil, pobíjel koně i vozbu a způsobil Aramejcům velikou porážku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Potom přistoupil k izraelskému králi prorok a řekl mu: Jdi, vzchop se, zjisti a podívej se, co bys měl udělat, protože na přelomu roku proti tobě aramejský král vytáhne opět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Otroci aramejského krále mu řekli: Jejich Bůh je Bohem hor, proto nás přemohli. Když však s nimi budeme bojovat na rovině, přemůžeme je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Udělej tuto věc: Odstraň krále z jejich místa a ustanov místo nich místodržitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Připrav si vojsko, jako bylo vojsko, které ti padlo, koně za koně, vozy za vozy, a budeme s nimi bojovat na rovině a přemůžeme je. Uposlechl je a udělal to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Na přelomu roku se stalo, že Ben–hadad spočítal Aramejce a vytáhl k Afeku do boje s Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Synové Izraele se zformovali, zásobili a vytáhli proti nim. Synové Izraele se utábořili naproti nim jako dvě kozí stádečka, zatímco Aramejci naplnili zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Potom přistoupil muž Boží a řekl izraelskému králi: Toto praví Hospodin: Protože Aramejci řekli: Hospodin je Bohem hor a ne Bohem údolí, vydám celé toto velké množství do tvé ruky a poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Jedni tábořili proti druhým sedm dní. Sedmého dne se stalo, že bitva začala a synové Izraele pobíjeli Aramejce, sto tisíc pěšáků v jednom dni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Zbývající utíkali do Afeku, do vnitř města. Avšak hradby spadly na ⌈zbývajících dvacet sedm tisíc mužů.⌉ Ben–hadad utekl a vešel do města, do ⌈nejzazšího pokoje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Jeho otroci mu řekli: Hle, slyšeli jsme, že králové domu izraelského jsou milosrdní králové. Vložme na svá bedra žíněná roucha a na hlavy provazy a vyjděme k izraelskému králi. Snad nechá tvou duši při životě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Nato přepásali svá bedra žíněnými rouchy a na hlavy dali provazy. Tak šli k izraelskému králi a řekli mu: Tvůj otrok Ben–hadad řekl: Prosím, ať zůstane má duše naživu. Zeptal se: Žije ještě? Je mým bratrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Ti muži to vzali jako znamení, rychle ho vzali za slovo a řekli: Ano, Ben–hadad je tvým bratrem. Řekl: Jděte a přiveďte ho. Ben–hadad k němu vyšel a on ho vzal na vůz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Řekl mu: Města, která vzal můj otec od tvého otce, ti vrátím, a ty si můžeš udělat tržní ulice v Damašku, tak jako si je udělal můj otec v Samaří. Achab nato: S takovou smlouvou tě propustím. Uzavřel s ním smlouvu a propustil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Tehdy nějaký muž z prorockých žáků řekl svému druhovi podle Hospodinova slova: Udeř mě. Ale on ho nechtěl udeřit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Řekl mu: Protože jsi neuposlechl Hospodina, hle, až půjdeš ode mě, zabije tě lev. Šel od něj, dopadl ho lev a zabil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Potkal jiného muže a řekl: Udeř mě. Ten muž ho silně udeřil a zranil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Nato prorok šel a postavil se králi do cesty -- s obvazem na očích se učinil nepoznatelným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'I stalo se, když král procházel okolo, že úpěnlivě volal na krále: Tvůj otrok vytáhl do boje, a hle, kdosi zabočil, přivedl ke mně muže a řekl: Střež tohoto muže. Jestliže se ztratí, ⌈bude tvá duše místo jeho duše⌉, nebo odvážíš talent stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'I stalo se, když tvůj otrok dělal cosi tu a tam, že zmizel. Izraelský král mu řekl: ⌈Tím jsi nad sebou sám vynesl rozsudek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Sundal si rychle obvaz z očí a izraelský král poznal, že je jedním z proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Pak mu řekl: Toto praví Hospodin: Protože jsi propustil muže, kterého jsem zasvětil zkáze, stane se, že tvá duše bude namísto jeho duše a tvůj lid místo jeho lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Izraelský král jel do svého domu roztrpčený a nazlobený a přijel do Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Po těchto událostech se stalo toto: Nábot Jizreelský měl vinici v Jizreelu vedle paláce samařského krále Achaba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Achab řekl Nábotovi: Dej mi svou vinici a stane se mojí zelinářskou zahradou, protože je hned vedle mého domu. Dám ti místo ní vinici lepší nežli tato, anebo pokud by se ti to líbilo, dám ti její cenu ve stříbře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Nábot Achabovi odpověděl: Ať je to ode mě vzdáleno kvůli Hospodinu, abych ti dal dědictví svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Nato šel Achab domů roztrpčený a nazlobený kvůli tomu, že mu Nábot Jizreelský řekl: Nedám ti dědictví svých otců. Ulehl na postel, odvrátil tvář a ne chtěl jíst pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Přišla k němu jeho žena Jezábel a zeptala se ho: Proč je tvůj duch roztrpčený, že ani pokrm ne jíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Odpověděl jí: Protože jsem mluvil s Nábotem Jizreelským a řekl jsem mu: Dej mi svou vinici za stříbro, nebo jestli chceš, dám ti za ni jinou vinici; ale on řekl: Nedám ti svou vinici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Jeho žena Jezábel mu řekla: Ty nyní jednej s královskou autoritou nad Izraelem. Vstaň, pojez pokrm a buď ⌈dobré mysli.⌉ Já sama ti dám vinici Nábota Jizreelského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Pak napsala Achabovým jménem dopisy, zapečetila jeho pečetidlem a poslala dopisy starším a šlechticům z jeho města, kteří bydleli s Nábotem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Do dopisů napsala: Vyhlaste půst a Nábota nechte usednout do čela lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Nechte proti němu usednout dva muže ničemníky, aby proti němu svědčili: Zlořečil jsi Bohu i králi. Vyveďte ho a ukamenujte ho, ať zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Nato muži jeho města, starší a šlechtici, kteří bydleli v jeho městě, učinili, jak jim Jezábel vzkázala, jak bylo napsáno v dopisech, které jim poslala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Vyhlásili půst a posadili Nábota do čela lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Přišli dva muži ničemníci a posadili se naproti němu. Ničemníci svědčili před lidem proti Nábotovi slovy: Nábot zlořečil Bohu i králi. Pak ho vyvedli ven za město, ukamenovali ho a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Jezábele potom vzkázali: Nábot byl ukamenován a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'I stalo se, když Jezábel uslyšela, že Nábot byl ukamenován a zemřel, řekla Jezábel Achabovi: Vstaň a obsaď vinici Nábota Jizreelského, kterou ti nechtěl dát za stříbro, protože Nábot nežije, ale zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'I stalo se, když Achab uslyšel, že Nábot zemřel, vstal, aby sestoupil na vinici Nábota Jizreelského a obsadil ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'I stalo se Hospodinovo slovo k Elijáši Tišbejskému:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Vstaň a jdi naproti izraelskému králi Achabovi, který bydlí v Samaří. Hle, je na Nábotově vinici; sestoupil tam, aby ji obsadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Řekni mu: Toto praví Hospodin: Zavraždil jsi a obsazuješ? Řekni mu: Toto praví Hospodin: Na místě, na kterém chlemtali psi krev Nábotovu, budou psi chlemtat krev tvoji, ano tvoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Achab řekl Elijášovi: Našel jsi mě, můj nepříteli? On odpověděl: Našel, protože ses zaprodal, abys páchal to, co je zlé v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Hle, přivedu na tebe zlo, vyhladím tvé potomky, vyhladím Achabovi ⌈močícího na stěnu,⌉ zadržovaného i propuštěného v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Učiním s tvým domem to co s domem Jarobeáma, syna Nebatova, a s domem Baeši, syna Achijášova, kvůli provokacím, kterými jsi mě provokoval ke hněvu a sváděl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'A také o Jezábele Hospodin promluvil: Psi sežerou Jezábelu na valech Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Toho, kdo zemře Achabovi ve městě, sežerou psi, a toho, kdo zemře na poli, pohltí nebeské ptactvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Vskutku nikdo nebyl jako Achab, který se zaprodal, aby páchal to, co je zlé v Hospodinových očích, jak ho naváděla jeho žena Jezábel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Jednal velmi ohavně a chodil za bůžky, stejně jako to činili Emorejci, které Hospodin před syny Izraele vyhnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'I stalo se, když uslyšel Achab tato slova, roztrhl své roucho, vložil na své tělo žíněné roucho, postil se, spal v žíněném rouchu a chodil zasmušilý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'I stalo se Hospodinovo slovo k Elijáši Tišbejskému:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Viděl jsi, že se Achab přede mnou pokořil? Protože se přede mnou pokořil, nepřivedu to zlo za jeho života, ale přivedu to zlo na jeho dům za života jeho syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Uplynuly tři roky, kdy nebyla válka mezi Aramem a Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'I stalo se, že ve třetím roce přišel judský král Jóšafat k izraelskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Izraelský král řekl svým otrokům: Víte přece, že nám patří Rámot–gileád, a my jsme neteční, abychom jej vzali z ruky aramejského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Potom se zeptal Jóšafata: Půjdeš se mnou do boje proti Rámot–gileádu? Jóšafat izraelskému králi odpověděl: ⌈Jsem jako ty, můj lid jako tvůj lid a moje koně jako tvoje koně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Jóšafat dále izraelskému králi řekl: Dotaž se nejprve na Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Izraelský král shromáždil proroky, asi čtyři sta mužů, a zeptal se jich: Mám jít do boje proti Rámot–gileádu, nebo mám od toho upustit? Odpověděli: Vytáhni, Panovník ho vydá do královy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Jóšafat se zeptal: To už tady není žádný Hospodinův prorok, abychom se dotázali skrze něj?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Izraelský král Jóšafatovi odpověděl: Ještě je tu jeden muž, skrze nějž je možno dotázat se Hospodina, ale já ho nenávidím, protože mi neprorokuje dobro, nýbrž zlo: Míkajáš, syn Jimlův. Jóšafat řekl: Ať král takto nemluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Izraelský král zavolal jednoho dvorního úředníka a řekl: Rychle sem přiveď Míkajáše, syna Jimlova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Izraelský král a judský král Jóšafat seděli každý na svém trůnu, oblečeni v roucha, na prostranství u vchodu do samařské brány a všichni proroci před nimi prorokovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Sidkijáš, syn Kenaanův, si udělal železné rohy a řekl: Toto praví Hospodin: Těmito rohy budeš trkat Aramejce, dokud s nimi neskoncuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'A tak prorokovali všichni proroci: Vytáhni proti Rámot–gileádu a uspěješ. Hospodin ho vydá do královy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Posel, který šel Míkajášovi vstříc, mu řekl: Hle, ⌈proroci mluví jednomyslně⌉ dobro pro krále. Ať jsou tvoje slova jako řeč jednoho z nich. Mluv dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Míkajáš řekl: Jakože živ je Hospodin, to, co ke mně Hospodin promluví, to budu mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Když přišel ke králi, král se ho zeptal: Míkajáši, máme jít do boje proti Rámot–gileádu, nebo od toho máme upustit? Odpověděl mu: Vytáhni a uspěješ. Hospodin ho vydá do královy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Král mu řekl: Kolikrát tě mám zapřísahat ⌈při Hospodinově jménu,⌉ abys mi neříkal nic než pravdu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Nato Míkajáš řekl: Viděl jsem ⌈celý Izrael rozptýlený⌉ po horách jako ovce, které nemají pastýře. Hospodin řekl: Nemají pána. Ať se všichni vrátí domů v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Izraelský král řekl Jóšafatovi: Což jsem ti neříkal, že mi nebude prorokovat dobro, ale zlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Mikajáš dále řekl: Slyš tedy Hospodinovo slovo: Viděl jsem Hospodina sedícího na trůnu a celý nebeský zástup stál kolem něj, po jeho pravici a levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Hospodin řekl: Kdo přemluví Achaba, aby vytáhl a padl u Rámot–gileádu? Jeden říkal to a druhý říkal ono,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'až vyšel jeden duch, postavil se před Hospodinem a řekl: Já ho přemluvím. Hospodin se ho zeptal: Čím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Odpověděl: Vyjdu a stanu se lživým duchem v ústech všech jeho proroků. Hospodin řekl: Ty ho přemluvíš, ano, dokážeš to. Vyjdi a učiň to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'A hle, nyní dal Hospodin lživého ducha do úst všech těchto tvých proroků. Ale Hospodin promluvil zlo proti tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Tu přistoupil Sidkijáš, syn Kenaanův, udeřil Míkajáše po tváři a řekl: Jakým způsobem přešel Hospodinův Duch ode mě, aby mluvil skrze tebe?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Míkajáš řekl: Hle, uvidíš to v onen den, kdy vejdeš do nejzazšího pokoje, aby ses skryl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Izraelský král řekl: Chop se Míkajáše a odveď ho k veliteli města Amónovi a královskému synu Jóašovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Řekni jim: Toto praví král: Dejte ho do věznice a krmte ho ⌈troškou chleba a vody,⌉ dokud nepřijdu v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Míkajáš řekl: Jestliže se opravdu vrátíš v pokoji, nemluvil skrze mě Hospodin. A prohlásil: Slyšte, všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Nato vytáhl izraelský král s judským králem Jóšafatem proti Rámot–gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Izraelský král řekl Jóšafatovi: Chci se přestrojit a tak jít do boje, ale ty si obleč své roucho. Izraelský král se přestrojil a šel do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Aramejský král přikázal ⌈svým třiceti dvěma⌉ velitelům vozby: Nebojujte proti malému ani velkému, jenom proti samotnému izraelskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'I stalo se, když velitelé vozby uviděli Jóšafata, že si řekli: To je jistě izraelský král! A zabočili, aby bojovali proti němu. Jóšafat volal o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'I stalo se, když velitelé vozby viděli, že to není izraelský král, odvrátili se od něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Tu kdosi nahodile napjal luk a zasáhl izraelského krále mezi spoje pancíře. Král řekl svému vozataji: Obrať koně a odvez mě z bojiště, protože jsem raněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Zatímco boj onoho dne silně vzplál, král zůstal podepřený na voze naproti Aramejcům a večer zemřel. Krev z rány vytekla na podlahu vozu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Po západu slunce proběhlo vojskem volání: Každý do svého města, každý na své území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Tak král zemřel a byl přivezen do Samaří. Krále pohřbili v Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Když oplachovali vůz u samařského rybníka, psi chlemtali jeho krev (⌈tam, kde ⌉ se prostitutky umývaly), podle Hospodinova slova, které promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Ostatní Achabovy činy a všechny věci, které činil, dům ze slonoviny, který postavil, a všechna města, která postavil, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Achab ulehl se svými otci a po něm se stal králem jeho syn Achazjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Jóšafat, syn Ásův, se stal králem nad Judou ve čtvrtém roce vlády izraelského krále Achaba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Jóšafatovi bylo třicet pět let, když se stal králem, a dvacet pět let kraloval v Jeruzalémě. Jeho matka se jmenovala Azúba, dcera Šilchího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Chodil po všech cestách svého otce Ásy, neodvrátil se od nich a činil to, co je správné v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Ovšem návrší nebyla odstraněna; lid na návrších dál obětoval a pálil kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Jóšafat uzavřel s izraelským králem mír.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Ostatní Jóšafatovy činy a jeho udatné skutky, které vykonal, to jak bojoval, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Zbytek chrámových smilníků, kteří zůstali ze dnů jeho otce Ásy, vyhladil ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'V Edómu nebyl král, pouze králem ustanovený správce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Jóšafat si udělal taršíšské lodě, aby plul do Ofíru pro zlato. Ale neplul, protože se lodě v Esjón–geberu rozlámaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Tehdy Achazjáš, syn Achabův, řekl Jóšafatovi: Ať plují moji otroci na lodích s tvými otroky. Ale Jóšafat nechtěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Jóšafat ulehl se svými otci a byl pohřben se svými otci v městě Davida, svého otce. Po něm se stal králem jeho syn Jóram.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Achazjáš, syn Achabův, se stal králem nad Izraelem v Samaří v sedmnáctém roce vlády judského krále Jóšafata. Kraloval nad Izraelem dva roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Páchal to, co je zlé v Hospodinových očích, a chodil po cestě svého otce a po cestě své matky i po cestě Jarobeáma, syna Nebatova, který svedl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Sloužil Baalovi a skláněl se před ním a provokoval Hospodina, Boha Izraele, ke hněvu, stejně jako to činil jeho otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Po Achabově smrti se vzbouřil Moáb proti Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Achazjáš propadl ⌈skrz mřížoví⌉ ve své horní místnosti v Samaří a onemocněl. Poslal posly a řekl jim: Jděte a dotažte se Baal–zebúba, boha Ekrónu, jestli se z této nemoci zotavím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Ale Hospodinův anděl promluvil k Elijáši Tišbejskému: Vstaň, jdi naproti poslům samařského krále a řekni jim: Což není Bůh v Izraeli, že se jdete dotázat Baal–zebúba, boha Ekrónu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Proto ⌈takto praví Hospodin:⌉ Z postele, na kterou jsi vylezl, neslezeš, ale jistě zemřeš. A Elijáš šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Když se poslové vrátili ke králi, zeptal se jich: Proč jste se vrátili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Odpověděli mu: Šel nám naproti nějaký muž a řekl nám: Jděte, vraťte se ke králi, který vás poslal, a řekněte mu: Toto praví Hospodin: Což není Bůh v Izraeli, že posíláš dotázat se Baal–zebúba, boha Ekrónu? Proto z postele, na kterou jsi vylezl, neslezeš, ale jistě zemřeš:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Zeptal se jich: Jak vypadal ten muž, který vám šel naproti a řekl vám tato slova?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Odpověděli mu: Ten muž byl chlupatý a koženým pásem přepásán kolem beder. Řekl: To byl Elijáš Tišbejský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Poslal k němu velitele nad padesáti s jeho padesáti. Vystoupil k němu a hle, Elijáš seděl na vrcholu hory. Řekl mu: Muži Boží, král vzkazuje: Sestup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elijáš odpověděl a řekl veliteli nad padesáti: Jestliže jsem muž Boží, ať sestoupí oheň z nebes a stráví tebe i tvých padesát. Nato sestoupil oheň z nebes a strávil jej i jeho padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Král k němu znovu poslal jiného velitele nad padesáti s jeho padesáti. Ten promluvil a řekl mu: Muži Boží, toto přikázal král: Rychle sestup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elijáš odpověděl a řekl jim: Jestliže jsem muž Boží, ať sestoupí oheň z nebes a stráví tebe i tvých padesát. Sestoupil oheň Boží z nebes a strávil jej i jeho padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Král znovu poslal třetího velitele nad padesáti s jeho padesáti. Třetí velitel nad padesáti vystoupil, přišel, klekl před Elijášem na kolena, prosil ho o smilování a řekl mu: Muži Boží, ⌈važ si, prosím, mého života⌉ a života těchto tvých padesáti otroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Hle, sestoupil oheň z nebes a strávil dva předchozí velitele nad padesáti s jejich padesáti. Ale nyní si važ mého života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Hospodinův anděl k Elijáši promluvil: Sestup s ním, neboj se ho. Tak vstal a sestoupil s ním ke králi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'a řekl mu: Toto praví Hospodin: Protože jsi poslal posly dotázat se Baal–zebúba, boha Ekrónu, jako by nebyl Bůh v Izraeli, aby ses dotázal na jeho slovo, proto z postele, na kterou jsi vylezl, neslezeš, ale jistě zemřeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'A zemřel podle Hospodinova slova, které promluvil Elijáš. Po něm se stal králem Jóram ve druhém roce vlády judského krále Jórama, syna Jóšafatova, protože neměl syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Ostatní Achazjášovy činy, které činil, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'I stalo se, když měl Hospodin vzít Elijáše ve vichřici do nebes, že šel Elijáš s Elíšou z Gilgálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Elijáš řekl Elíšovi: Zůstaň tady, protože Hospodin mě poslal do Bét–elu. Elíša řekl: Jakože živ je Hospodin a jakože živ jsi ty, neopustím tě. Tak sestoupili do Bét–elu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Proročtí žáci, kteří byli v Bét–elu, vyšli k Elíšovi a zeptali se ho: Víš, že dnes Hospodin vezme tvého pána od tebe? Odpověděl: Také to vím, mlčte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Elijáš mu řekl: Elíšo, zůstaň tady, protože Hospodin mě poslal do Jericha. Elíša řekl: Jakože živ je Hospodin a jakože živ jsi ty, neopustím tě. Tak šli do Jericha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Proročtí žáci, kteří byli v Jerichu, přistoupili k Elíšovi a zeptali se ho: Víš, že dnes Hospodin vezme tvého pána od tebe? Odpověděl: Také to vím, mlčte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Elijáš mu řekl: Zůstaň tady, protože Hospodin mě poslal k Jordánu. Elíša řekl: Jakože živ je Hospodin a jakože živ jsi ty, neopustím tě. Tak šli spolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Padesát mužů z prorockých žáků šlo a postavilo se naproti zpovzdálí a oni dva stáli u Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Elijáš vzal svůj plášť, stočil ho, udeřil do vody a ta se rozdělila sem i tam. Pak přešli oba po suché zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'I stalo se, jak přecházeli, že Elijáš řekl Elíšovi: Žádej, co mám pro tebe udělat, dříve nežli budu od tebe vzat. Elíša řekl: Ať jsou na mně dva díly tvého ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Elijáš řekl: ⌈Požádal jsi o těžkou věc.⌉ Jestliže mě uvidíš, až budu od tebe brán, stane se ti tak. Jestliže ne uvidíš, nestane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Šli stále spolu a hovořili, a tu se objevil ohnivý vůz a ohniví koně, oddělili je od sebe a Elijáš vystoupil ve vichřici do nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Elíša to viděl a zvolal: Můj otče, můj otče! Vozbo Izraele a jeho jezdci! A pak ho již neviděl. Uchopil své roucho a roztrhl je na dva kusy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Potom zvedl Elijášův plášť, který z něj spadl, vracel se a zastavil se na břehu Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Vzal Elijášův plášť, který z něho spadl, udeřil do vody a řekl: Kde je Hospodin, Bůh Elijášův, ano, on? Když udeřil do vody, rozdělila se sem a tam a Elíša přešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Viděli ho proročtí žáci, kteří byli naproti v Jerichu, a řekli: Elijášův duch spočinul na Elíšovi. Šli mu naproti a poklonili se před ním k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Řekli mu: Hle, s tvými otroky je padesát mužů bojovníků, ať jdou a hledají tvého pána, zdali jej Hospodinův Duch neodnesl a ne hodil na nějakou horu či do nějakého údolí. Řekl: Neposílejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Nutili ho až hanba, takže nakonec řekl: Pošlete je. Poslali tedy padesát mužů a ti hledali tři dny, ale nenašli ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Vrátili se k němu, když byl ještě v Jerichu. Řekl jim: Což jsem vám neřekl: Nechoďte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Mužové města řekli Elíšovi: Hle, město ⌈ je dobré místo k bydlení,⌉ jak můj pán vidí, ale voda je špatná a země ⌈připravuje o děti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Řekl: Podejte mi novou mísu a dejte tam sůl. Podali mu to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Odešel ke zdroji vody, hodil tam sůl a řekl: Toto praví Hospodin: Uzdravuji tuto vodu. Ať již odtud nevzejde smrt ani potrat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'A až do tohoto dne je voda uzdravena, podle Elíšova slova, které promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Odtud šel do Bét–elu. Jak šel cestou, vyšli z města ⌈malí chlapci⌉ a posmívali se mu. Volali na něho: Pojď, plešatče, pojď, plešatče!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Ohlédl se za nimi, uviděl je a proklel je v Hospodinově jménu. Tu vyšly z lesa dvě medvědice a čtyřicet dva dětí z nich rozsápaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Odtamtud šel na horu Karmel a odtud se vrátil do Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Jóram, syn Achabův, se stal králem nad Izraelem v Samaří v osmnáctém roce vlády judského krále Jóšafata. Kraloval dvanáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Páchal to, co je zlé v Hospodinových očích, ovšem ne jako jeho otec a matka. Odstranil Baalův posvátný sloup, který udělal jeho otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Ke hříchům Jarobeáma, syna Nebatova, který svedl Izrael k hříchu, ovšem přilnul a neodvrátil se od nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Moábský král Méša byl chovatelem ovcí. Odváděl izraelskému králi sto tisíc jehňat a ⌈vlnu ze sta tisíc beranů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'I stalo se, když Achab zemřel, že se moábský král vzbouřil proti izraelskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Král Jóram vytáhl v tom čase ze Samaří a spočítal celý Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Když vytáhl, vzkázal judskému králi Jóšafatovi: Moábský král se proti mně vzbouřil. Vytáhneš se mnou do boje proti Moábu? Ten odpověděl: Vytáhnu; ⌈jsem jako ty, můj lid jako tvůj lid a moje koně jako tvoje koně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'A zeptal se: ⌈Kterou cestou⌉ vytáhneme? Odpověděl: Směrem do edómské pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Izraelský král tedy vytáhl s králem judským a králem edómským. Když obcházeli sedm dní kolem Mrtvého moře, neměli vodu pro vojsko ani pro dobytek, který šel v jejich stopách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Izraelský král řekl: Běda, neboť Hospodin zavolal tyto tři krále, aby je vydal do ruky Moábu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Na to řekl Jóšafat: Což tu není Hospodinův prorok, abychom se skrze něj dotázali Hospodina? Jeden z otroků izraelského krále odpověděl: Je zde Elíša, syn Šáfatův, který lil vodu na Elijášovy ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Jóšafat řekl: ⌈U něho⌉ je Hospodinovo slovo. Tak k němu izraelský král a Jóšafat i edómský král šli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Elíša řekl izraelskému králi: Co je mi do tebe? Jdi si k prorokům svého otce a k prorokům své matky. Izraelský král mu odpověděl: Ne, neboť Hospodin zavolal tyto tři krále, aby je vydal do ruky Moábu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elíša řekl: Jakože živ je Hospodin zástupů, kterému sloužím, kdybych nebral ohled na judského krále Jóšafata, ani bych se za tebou neohlédl, ani bych se na tebe nepodíval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Tak mi přiveďte hudebníka. I stalo se, když ten hudebník hrál, že na něm spočinula Hospodinova ruka');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'a řekl: Toto praví Hospodin: ⌈Udělejte v tomto údolí mnoho prohlubní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Neboť toto praví Hospodin: Neuvidíte vítr ani neuvidíte déšť, ale toto údolí se naplní vodou a budete pít vy, i vaše stáda a váš dobytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'I to je málo v Hospodinových očích; vydá Moába do vaší ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Vybijete ⌈všechna opevněná města⌉ a všechna nejlepší města, všechny dobré stromy porazíte, všechny vodní prameny zastavíte a všechna dobrá pole znehodnotíte kamením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'I stalo se ráno, když se přináší přídavná oběť, hle, voda tekla směrem od Edómu a země se naplnila vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Když celý Moáb uslyšel, že králové vytáhli, aby proti nim bojovali, svolali ⌈všechny, kdo se přepásávají pásem od nejmladších výše,⌉ a postavili se na hranici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Moábci vstali časně ráno, když slunce vyšlo nad vodou, ⌈a naproti viděli vodu rudou⌉ jako krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Řekli si: To je krev. Králové se jistě pobili, pozabíjeli jeden druhého. A teď na kořist, Moábe!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Když přišli k izraelskému táboru, Izraelci povstali a pobíjeli Moábce, takže před nimi utíkali. Pobíjeli je, až Moábce vybili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Města zbořili, na každé dobré pole hodili každý kámen, až ho zaplnili, každý vodní pramen zastavili, každý dobrý strom porazili. Jen hradba v Kír–charesetu zůstala; prakovníci ho obklíčili a udeřili na něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Když moábský král viděl, že boj je na něj příliš těžký, vzal s sebou sedm set mužů tasících meč, aby pronikl k edómskému králi, ale nedokázali to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Tak vzal svého prvorozeného syna, který se po něm měl stát králem, a přinesl ho na hradbách jako zápalnou oběť. Na Izrael dopadlo velké rozhořčení, takže od něj odtáhli a vrátili se do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Jedna žena z žen prorockých žáků úpěnlivě volala k Elíšovi: Tvůj otrok, můj muž, je mrtev. Ty víš, že se tvůj otrok bál Hospodina. Přišel však věřitel, aby si vzal mé dva chlapce za otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elíša se jí zeptal: Co mám pro tebe udělat? Pověz mi, co máš doma? Odpověděla: Tvá otrokyně nemá doma nic, jenom ⌈malý džbánek⌉ oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Nato řekl: Jdi, vyžádej si nádoby odjinud, od všech svých sousedů, prázdné nádoby. Nespokojuj se s málem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Pak jdi, zavři za sebou a za svými syny dveře a nalévej do všech těch nádob; plné dávej stranou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Odešla od něj a zavřela dveře za sebou a za svými syny. Oni k ní přinášeli nádoby a ona nalévala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'I stalo se, když byly nádoby plné, že řekla svému synovi: Přines mi další nádobu. Odpověděl jí: Další nádoba není. A olej přestal téct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Šla a oznámila to muži Božímu. Ten řekl: Jdi, prodej olej, zaplať svůj dluh a ty se svými syny budeš živa z toho, co zbude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'I stalo se jednoho dne, že přišel Elíša do Šúnemu. Tam byla zámožná žena a přemluvila ho, aby pojedl pokrm. I stalo se, že kdykoli šel kolem, zabočil tam, aby pojedl pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Proto řekla svému muži: Hle, vím, že je to svatý Boží muž. Chodí stále kolem nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Udělejme malou zděnou horní místnost a dejme mu tam postel, stůl, židli a svícen. I stane se, když k nám přijde, že ⌈si tam zajde.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'I stalo se v tom čase, že tam přišel, zašel si do horní místnosti a ulehl tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Svému služebníkovi Gecházímu řekl: Zavolej tu Šúnemanku. Zavolal ji a ona se ⌈k němu dostavila.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Řekl mu: Pověz jí: Hle, ⌈děláš si kvůli nám takovou starost.⌉ Co pro tebe mohu udělat? Mám se za tebe přimluvit u krále či u velitele armády? Odpověděla: Žiji mezi svým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Zeptal se: Co pro ni mohu udělat? Gechází odpověděl: Ach, nemá syna a její muž je starý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Nato řekl: Zavolej ji. Zavolal ji a ona zůstala stát ve dveřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Řekl: V tento čas, ⌈jako je čas živého,⌉ budeš objímat syna. Řekla: Ne, můj pane, muži Boží, nelži své otrokyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Ta žena otěhotněla a porodila syna v určený čas, jako je čas živého, jak jí Elíša pověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Chlapec vyrůstal. I stalo se jednoho dne, že šel za svým otcem, k žencům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Tu řekl otci: Moje hlava, moje hlava. Ten řekl služebníkovi: Odnes ho jeho matce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Ten ho vzal a přinesl ho jeho matce. Zůstal na jejích kolenou až do poledne a pak zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Ona vyšla nahoru, položila ho na postel muže Božího, zavřela za ním a odešla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Potom zavolala svého muže a řekla: Pošli mi jednoho ze služebníků a ⌈jednu z oslic.⌉ Poběžím k muži Božímu a vrátím se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Zeptal se: Proč za ním chceš dnes jít? Není novoluní ani sobota. Odpověděla: ⌈Pokoj tobě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Osedlala oslici a řekla svému služebníkovi: Žeň oslici a běž, nezdržuj kvůli mně jízdu, jen kdybych ti řekla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Jela, až přijela k muži Božímu na horu Karmel. I stalo se, když ji muž Boží z dálky uviděl, že řekl svému služebníkovi Gecházímu: Hle, to je ta Šúnemanka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Tak jí běž naproti a zeptej se jí: Jak se ti daří? Jak se daří tvému muži? Jak se daří chlapci? Ona odpověděla: Dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Když přišla na horu k muži Božímu, chytila ho za nohy. Gechází přistoupil, aby ji odstrčil, ale muž Boží řekl: Nech ji, neboť je jí hořko v duši a Hospodin to přede mnou skryl a neoznámil mi to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Ona řekla: Což jsem od svého pána žádala syna? Což jsem neříkala: Nevzbuzuj ve mně falešné naděje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Elíša řekl Gecházímu: Přepásej svá bedra, vezmi si s sebou moji hůl a jdi. Jestliže někoho potkáš, nezdrav ho a jestliže tě někdo pozdraví, neodpovídej mu. Polož mou hůl na chlapcův obličej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Chlapcova matka řekla: Jakože živ je Hospodin a jakože živ jsi ty, ⌈neodejdu od tebe.⌉ Nato vstal a šel za ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gechází je předešel, položil hůl na chlapcův obličej, ale žádný o hlas, nikdo tomu nevěnoval pozornost. Vrátil se mu naproti a oznámil mu: Chlapec se neprobudil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Elíša vešel do domu a hle, chlapec byl mrtev, položen na jeho posteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Když vešel, zavřel za oběma dveře a modlil se k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Pak vylezl na postel a lehl si na chlapce; položil svá ústa na jeho ústa, své oči na jeho oči, své dlaně na jeho dlaně. A jak se nad ním sklonil, chlapcovo tělo se zahřálo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Slezl, prošel se sem a tam po domě, vylezl nahoru, sklonil se nad ním a chlapec sedmkrát kýchl. Pak chlapec otevřel oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Elíša zavolal Gecházího a řekl: Zavolej tu Šúnemanku. Zavolal ji, a když přišla k němu, řekl: Vezmi si svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Když přišla, padla k jeho nohám, poklonila se k zemi, vzala svého syna a odešla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elíša se vrátil do Gilgálu. V zemi byl hlad. Proročtí žáci seděli před ním. Řekl svému služebníkovi: Postav velký hrnec a uvař pro prorocké žáky jídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Jeden z nich odešel do polí sbírat sléz. Našel ⌈polní popínavou rostlinu⌉ a posbíral z ní divoké tykve, plný svůj oděv. Přinesl to a nakrájel do hrnce s jídlem, ačkoliv to nevěděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Pak to nalévali mužům k jídlu. I stalo se, když jedli to jídlo, že začali křičet: Muži Boží, v hrnci je smrt. A nemohli to jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Nato řekl: Podejte mouku. Hodil ji do hrnce a řekl: Nalévejte lidem, ať jedí! A v hrnci už nic špatného nebylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Z Baal–šališi přišel nějaký muž a přinesl muži Božímu chléb z prvotin, dvacet ječných chlebů a čerstvé obilí v pytli. Elíša řekl: Dej to lidem, ať jedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Jeho služebník řekl: Jak to mohu dát před sto mužů? Ale on řekl: Dej to lidem, ať jedí, neboť toto praví Hospodin: ⌈Budou jíst a ještě zůstane.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Dal to tedy před ně, jedli a ještě zůstalo podle Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naamán, velitel armády aramejského krále, byl před svým pánem významným a vznešeným mužem, neboť skrze něj dal Hospodin Aramejcům záchranu. Ten muž byl ⌈udatný hrdina,⌉ ale byl postižen malomocenstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Když jednou Aramejci vytáhli na loupežnou výpravu, odvedli z izraelské země mladé děvče. Sloužilo pak Naamánově ženě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Řeklo své paní: Kéž by se můj pán dostal před proroka, který je v Samaří. Potom by ho zbavil malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Naamán šel a oznámil svému pánu: To děvče z izraelské země povídalo ⌈to a to.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Na to aramejský král řekl: Nuže, jdi, pošlu izraelskému králi dopis. Šel tedy a vzal s sebou deset talentů stříbra, šest tisíc šekelů zlata a deset proměnných rouch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Přinesl dopis izraelskému králi. V něm stálo toto: Až se k tobě dostane tento dopis, viz, že jsem k tobě poslal svého otroka Naamána, abys ho zbavil malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'I stalo se, když izraelský král přečetl ten dopis, že roztrhl své roucho a řekl: Což jsem Bůh, abych usmrcoval či zachovával při životě, že tento posílá ke mně, abych zbavil člověka malomocenství? ⌈Rozvažte a pohleďte,⌉ že proti mně hledá záminku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'I stalo se, když Elíša, muž Boží, uslyšel, že izraelský král roztrhl své roucho, vzkázal králi: Proč jsi roztrhl své roucho? Jen ať přijde ke mně, aby poznal, že je v Izraeli prorok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Když přišel Naamán se ⌈svými koňmi⌉ a s vozem, zastavil u vchodu do Elíšova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Elíša k němu poslal posla se slovy: Jdi a umyj se sedmkrát v Jordánu; tvé tělo se obnoví a budeš čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Naamán se rozhněval, odešel a řekl: Hle, říkal jsem si: Jistě vyjde, postaví se, bude vzývat jméno Hospodina, svého Boha, mávat rukou k místu a zbaví mě malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Což nejsou damašské řeky Abána a Parpar lepší nežli všechny vody izraelské? Cožpak jsem se ne mohl umýt v nich, abych byl čist? Obrátil se a v hněvu odcházel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Přistoupili jeho otroci a přemlouvali ho. Říkali: Můj otče, kdyby ti prorok pověděl nějakou velkou věc, cožpak bys to neudělal? Tím spíše, když ti řekl: Umyj se a budeš čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Sestoupil tedy, ponořil se sedmkrát do Jordánu podle slova muže Božího a jeho tělo se obnovilo a bylo jako tělo malého chlapce -- byl čist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Pak se vrátil k muži Božímu, on a celý jeho doprovod. Přišel, postavil se před ním a řekl: Hle, nyní vím, že na celé zemi není Bůh, jenom v Izraeli. A teď přijmi dar od svého otroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'On ale odpověděl: Jakože živ je Hospodin, kterému sloužím, nepřijmu. Ačkoliv ho nutil, aby přijal, on to odmítl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Nato Naamán řekl: Když ne, tak dovol, ať je tvému otroku dán náklad prsti, co unese pár mezků, neboť tvůj otrok již nebude připravovat zápalné oběti ani obětní hody jiným bohům, jenom Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Tuto věc ať Hospodin odpustí tvému otroku: Když můj pán přichází do domu Rimónova, aby se tam klaněl, opírá se o mou ruku a klaním se v domě Rimónově. Až se budu klanět v domě Rimónově, ať Hospodin odpustí tvému otroku tuto věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Odpověděl mu: ⌈Jdi v pokoji.⌉ Když od něho odešel ⌈na kus cesty,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Gechází, služebník Elíši, muže Božího, si řekl: Hle, můj pán ušetřil tohoto Aramejce Naamána a nepřijal od něj, co přivezl. Jakože živ je Hospodin, poběžím za ním a vezmu si od něj něco.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Tak se hnal Gechází za Naamánem. Když Naamán uviděl, že za ním někdo běží, ⌈ rychle seskočil⌉ z vozu a šel mu vstříc. Zeptal se: Vše ⌈v pořádku?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Odpověděl: Vše v pořádku. Můj pán mě poslal se slovy: Hle, přišli ke mně právě z Efrajimského pohoří dva mládenci z prorockých žáků. Dej jim, prosím, talent stříbra a dvě proměnná roucha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naamán odpověděl: Buď tak laskav, vezmi si dva talenty. Nutil ho a zabalil dva talenty stříbra do dvou vaků i dvě proměnná roucha a dal to dvěma svým služebníkům, aby to před ním nesli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Když přišel Géchazí na kopec, vzal si to od nich a uložil to v domě. Muže propustil a oni odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'On pak šel a postavil se před svým pánem. Elíša se ho zeptal: Odkudpak, Géchází? Odpověděl: Tvůj otrok nešel nikam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'On mu řekl: ⌈Nešel jsem v duchu s tebou,⌉ když ten muž sestoupil ze svého vozu a šel ti vstříc? Což je čas brát stříbro a brát roucha, ⌈olivové háje a vinice,⌉ brav a skot, otroky a otrokyně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Naamánovo malomocenství ulpí navěky na tobě a na tvém potomstvu. Nato od něj odešel postižen malomocenstvím, bílý jako sníh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Proročtí žáci řekli Elíšovi: Hle, místo, kde pobýváme před tebou, je pro nás těsné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Pojďme k Jordánu, vezměme odtamtud každý jeden trám a udělejme si tam místo k bydlení. Řekl: Jděte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Kdosi řekl: Buď tak laskav, prosím, a pojď se svými otroky. Odpověděl: Půjdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Šel tedy s nimi. Přišli k Jordánu a káceli stromy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'I stalo se, že kdosi porážel kmen a sekera spadla do vody. Křičel: Ach, můj pane, byla půjčená!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Muž Boží se zeptal: Kam spadla? Když mu to místo ukázal, uřízl kus dřeva, hodil ho tam a sekera vyplavala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Řekl: Vytáhni si ji. Vztáhl ruku a vzal si ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Když aramejský král vedl válku proti Izraeli, poradil se se svými otroky: Na tom a tom místě bude můj tábor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Muž Boží však izraelskému králi vzkázal: Měj se na pozoru, abys neprocházel tímto místem, neboť tam táboří Aramejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Izraelský král poslal posly na to místo, o kterém mu muž Boží pověděl a varoval ho, a měl se tam na pozoru; a to se stalo ne jednou či dvakrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, '⌈Mysl aramejského krále byla kvůli tomu rozbouřená.⌉ Zavolal své otroky a řekl jim: Proč mi neoznámíte, kdo z našich je s izraelským králem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Jeden z jeho otroků řekl: Nikoli, můj pane a králi, ale prorok Elíša, který je v Izraeli, oznamuje izraelskému králi věci, které mluvíš ve své ložnici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Řekl: Jděte a podívejte se, kde je. Pak pošlu a zajmu ho. Oznámili mu: Je v Dótanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Poslal tam koně a vozy, ohromné vojsko. Přitáhli v noci a obklíčili město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Služebník muže Božího vstal časně ráno, vyšel, a hle, ⌈vojsko bylo kolem města,⌉ koně i vozy. Jeho služebník se ho zeptal: Ach, můj pane, co budeme dělat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Odpověděl: Neboj se, protože ⌈s námi jich je víc než s nimi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Pak se Elíša modlil: Hospodine, otevři jeho oči, ať vidí. A Hospodin otevřel služebníkovy oči a viděl, hle, ⌈pohoří kolem Elíši bylo plné koní a ohnivých vozů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Jak k němu Aramejci sestupovali, modlil se Elíša k Hospodinu: Raň tento národ slepotou. A ranil je slepotou podle Elíšova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Elíša jim řekl: Toto není ta cesta a to město. Pojďte za mnou a přivedu vás k muži, kterého hledáte. Pak je přivedl do Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'I stalo se, když přišli do Samaří, že Elíša řekl: Hospodine, otevři jejich oči, ať vidí. Hospodin otevřel jejich oči a viděli, že jsou uprostřed Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Když je uviděl izraelský král, zeptal se Elíši: Mám je pobít, můj otče?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Odpověděl: Nepobíjej. Cožpak jsi je zajal svým mečem a lukem, že je chceš pobít? Předlož jim chléb a vodu, ať jedí a pijí a pak ať jdou ke svému pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Uspořádal jim velkou hostinu, jedli a pili a pak je propustil a oni šli ke svému pánu. A aramejské loupežné hordy již znovu do izraelské země nepřitáhly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'I stalo se později, že aramejský král Ben–hadad shromáždil celé své vojsko, vytáhl a oblehl Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'V Samaří nastal velký hlad. Hle, obléhali ho tak dlouho, že oslí hlava byla za osmdesát stříbrných a čtvrtina kabu ⌈holubího trusu⌉ za pět stříbrných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Když se jednou izraelský král procházel po hradbách, volala k němu úpěnlivě nějaká žena: Pomoz, můj pane a králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Odpověděl: Jestliže ti nepomůže Hospodin, odkud mám vzít pro tebe pomoc? Snad z ⌈humna či z lisu?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Král se jí pak zeptal: Co je ⌈s tebou?⌉ Odpověděla: Tato žena mi řekla: Dej svého syna a sníme ho dnes a mého syna sníme zítra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Uvařily jsme mého syna a snědly jsme ho. Další den jsem jí řekla: Dej svého syna a sníme ho. Ale ona svého syna ukryla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'I stalo se, když král uslyšel slova té ženy, že roztrhl své roucho; jak se procházel po hradbách, lid viděl, že má vespod na těle žíněné roucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Řekl: Tak ať mi učiní Bůh, a ještě přidá, jestliže dnes zůstane hlava Elíši, syna Šáfatova, na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elíša tehdy seděl ve svém domě a starší seděli s ním. Král poslal kohosi před sebou. Dříve nežli k němu posel přišel, řekl Elíša starším: Vidíte, že ten vrah poslal kohosi srazit mi hlavu? Hleďte, až přijde posel, zavřete dveře a držte ho za dveřmi. Což to není za ním zvuk kroků jeho pána?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Ještě s nimi mluvil, a tu k němu sestupoval posel a řekl: Hle, toto zlo je od Hospodina. Proč mám mít ještě naději v Hospodinu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Elíša řekl: ⌈Slyšte Hospodinovo slovo:⌉ Toto praví Hospodin: ⌈Zítra touto dobou⌉ bude v samařské bráně sea mouky za šekel a dvě sey ječmene za šekel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Nato promluvil k muži Božímu kapitán, o jehož ruku se král opíral, a řekl: Hle, i když Hospodin udělá průduchy do nebes, cožpak se to stane? Elíša odpověděl: Hle, uvidíš to na vlastní oči, ale jíst z toho nebudeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'U vchodu do brány byli čtyři malomocní muži. Řekli jeden druhému: Co tady sedíme, dokud nezemřeme?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Kdybychom si řekli: Pojďme do města, ve městě je hlad a zemřeme tam. Jestliže zůstaneme tady, také zemřeme. Nuže pojďme, přeběhneme do aramejského tábora. Jestliže nás nechají při životě, budeme žít; jestliže nás usmrtí, zemřeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Vstali tedy ⌈před rozedněním⌉ a šli do aramejského tábora. Když přišli na kraj aramejského tábora, hle, nikdo tam nebyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'To Panovník způsobil, že v aramejském táboře uslyšeli zvuk vozů, zvuk koní, zvuk velkého vojska, takže řekli jeden druhému: Hle, izraelský král proti nám najal krále chetejské a krále egyptské, aby proti nám vytáhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Vstali a utíkali ⌈před rozedněním.⌉ Opustili své stany, své koně a osly, celý tábor tak, jak byl, a utíkali, ⌈ aby si zachránili život.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Když přišli ti malomocní na kraj tábora, vešli do jednoho stanu, jedli, pili a vzali odtamtud stříbro, zlato a šaty. Pak odešli a schovali to. Nato se vrátili, vešli do jiného stanu, vzali i odtamtud, odešli a schovali to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Potom řekli jeden druhému: Nejednáme správně. Tento den je dnem dobré zprávy, a my mlčíme. Jestliže budeme čekat do svítání, dopadne na nás vina. Nuže, pojďme a oznámíme to v královském paláci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Šli tedy, zavolali vrátné města a oznámili jim: Přišli jsme do aramejského tábora, a hle, nikdo tam nebyl, ani hlásek člověka, jenom přivázaní koně a osli a stany tak, jak byly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Vrátní to vyhlásili, až to bylo oznámeno u vnitř královského paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Král v noci vstal a řekl svým otrokům: Povím vám, co nám udělali Aramejci: Vědí, že hladovíme. Vyšli z tábora, aby se skryli v poli. Řekli si: Až vyjdou z města, chytíme je živé a vejdeme do města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Jeden z jeho otroků odpověděl: Ať vezmou pět ze zbylých koní, kteří ⌈ve městě ⌉ zůstali, a budou jako celý izraelský dav, ⌈který ⌈ve městě ⌉ zůstal; budou jako celý izraelský dav, který⌉ zahynul. Pošleme je a uvidíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Vzali tedy dva koňské vozy a král je poslal za aramejským vojskem se slovy: Jděte a podívejte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Šli za nimi až k Jordánu, a hle, celá cesta byla plná šatů a předmětů, které Aramejci odhazovali, jak pospíchali. Poslové se vrátili a oznámili to králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Lid vyšel a plenili aramejský tábor. I stalo se, že sea mouky byla za šekel a dvě sey ječmene za šekel, podle Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Král ustanovil kapitána, o jehož ruku se opíral, nad bránou, ale lid ho v bráně ušlapal a zemřel, podle toho, co pověděl muž Boží, když promluvil, jakmile k němu přišel král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'I stalo se, když promluvil muž Boží ke králi slovy: Zítra touto dobou budou v samařské bráně dvě sey ječmene za šekel a sea mouky za šekel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'že promluvil k muži Božímu kapitán a řekl: Hle, i když Hospodin udělá průduchy do nebes, cožpak se to stane? A Elíša odpověděl: Hle, uvidíš to na vlastní oči, ale jíst z toho nebudeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'A stalo se mu tak: Lid ho ušlapal v bráně a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elíša promluvil k ženě, jejíhož syna oživil, a řekl: Vstaň a jdi, ty i tvůj dům, a pobývej jako cizinec, kde se dá, protože Hospodin vyhlásil hlad a již přišel na zemi na sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Žena vstala a učinila podle slova muže Božího: Šla ona i její dům a pobývala jako cizinec v pelištejské zemi po sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'I stalo se po sedmi letech, že se ta žena vrátila z pelištejské země a šla se na králi domáhat svého domu a svého pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Tehdy král hovořil s Gecházím, služebníkem muže Božího, a řekl: Vyprávěj mi o všech velkých činech, které Elíša učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Když vyprávěl králi o tom, jak oživil mrtvého, právě přišla ta žena, jejíhož syna oživil, aby se domáhala na králi svého domu a svého pole. Gechází řekl: Můj pane a králi, to je ta žena a to je její syn, kterého Elíša oživil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Král se na to té ženy vyptal a ona mu to vyprávěla. Pak jí král ustanovil jednoho dvorního úředníka a řekl mu: Vrať všechno, co jí patří; všechnu úrodu pole ode dne, kdy opustila zemi, až do nynějška.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Elíša přišel do Damašku. Aramejský král Ben–hadad byl nemocen. Bylo mu oznámeno: Přišel sem muž Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Král řekl Chazaelovi: Vezmi s sebou dar, jdi muži Božímu naproti a dotaž se skrze něj Hospodina slovy: Zotavím se z této nemoci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Chazael mu tedy šel naproti. Vzal s sebou dar, všelijaké dobré věci Damašku, náklad čtyřiceti velbloudů. Přišel, zastavil před ním a řekl: Tvůj syn, aramejský král Ben–hadad, mě k tobě poslal se slovy: Zotavím se z této nemoci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elíša mu odpověděl: Jdi, ⌈řekni mu: Určitě se zotavíš, ale Hospodin⌉ mi ukázal, že jistě zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, '⌈Jeho tvář strnula,⌉ ⌈předlouho na něj zíral⌉ a pak se muž Boží rozplakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Chazael se zeptal: Proč můj pán pláče? On odpověděl: Protože vím, co zlého spácháš vůči synům Izraele. Jejich pevnosti pošleš do ohně, jejich mládence pozabíjíš mečem, jejich děti rozdrtíš a jejich těhotné rozpáráš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Chazael řekl: Jak by mohl tvůj otrok, pouhý pes, udělat něco tak velkého? Elíša odpověděl: Hospodin mi ukázal, že budeš králem nad Aramem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Pak odešel od Elíši a přišel ke svému pánu. Ten se ho zeptal: Co ti říkal Elíša? Odpověděl: Řekl mi, že se určitě zotavíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Příštího dne se stalo, že vzal přikrývku, namočil do vody a rozprostřel na jeho tvář, takže zemřel. Chazael pak kraloval místo něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'V pátém roce vlády izraelského krále Jórama, syna Achabova, když byl Jóšafat judským králem, se stal judským králem král Jóram, syn Jóšafatův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Bylo mu třicet dva let, když se stal králem, a kraloval v Jeruzalémě osm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Chodil po cestě izraelských králů, tak jak to činil dům Achabův, protože Achabova dcera byla jeho ženou. Páchal to, co je zlé v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Hospodin však nechtěl zničit Judu kvůli svému otroku Davidovi, protože mu slíbil, že dá jemu i jeho synům lampu po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Za jeho dnů se Edómci ⌈vzbouřili proti judské moci⌉ a ustanovili nad sebou krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Jóram tehdy přitáhl k Sáíru a s ním celá vozba. I stalo se, že v noci vstal a udeřil na Edómce, kteří obkličovali jej i velitele vozby; ale lid utekl ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Proto se vzbouřili Edómci proti judské moci až do tohoto dne. Tak se v té době vzbouřila i Libna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Ostatní Jóramovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Jóram ⌈ulehl se svými otci⌉ a byl pohřben se svými otci v Městě Davidově. Po něm se stal králem jeho syn Achazjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'V dvanáctém roce vlády izraelského krále Jórama, syna Achabova, se stal judským králem král Achazjáš, syn Jóramův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Achazjášovi bylo dvacet dva let, když se stal králem, a kraloval v Jeruzalémě jeden rok. Jeho matka se jmenovala Atalja, dcera izraelského krále Omrího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Chodil po cestě domu Achabova a páchal to, co je zlé v Hospodinových očích, jako dům Achabův, protože byl zetěm domu Achabova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Vytáhl s Jóramem, synem Achabovým, k Rámot–gileádu do boje proti aramejskému králi Chazaelovi, ale Aramejci Jórama ranili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Nato se vrátil král Jóram do Jizreelu, aby se vyléčil z ran, ⌈které mu Aramejci způsobili⌉ v Rámě, když bojoval s aramejským králem Chazaelem. Judský král Achazjáš, syn Jóramův, se přišel na Jórama, syna Achabova, do Jizreelu podívat, protože byl nemocný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Prorok Elíša zavolal jednoho z prorockých žáků a řekl mu: Přepásej svá bedra, vezmi si s sebou tuto lahvičku s olejem a jdi do Rámot–gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Až tam přijdeš, vyhledej tam Jehúa, syna Jóšafata, syna Nimšího. Jdi, vezmi ho zprostřed jeho bratří a přiveď ho do nejzazšího pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Pak vezmi lahvičku s olejem, vylej mu ho na hlavu a řekni: Toto praví Hospodin: Mažu tě za krále nad Izraelem. Nato otevři dveře a utíkej, na nic nečekej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'A tak šel prorokův služebník do Rámot–gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Když přišel, uviděl tam sedět spolu velitele vojska. Řekl: Mám pro tebe slovo, veliteli. Jehú se zeptal: Pro koho z nás? Odpověděl: Pro tebe, veliteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Vstal, šel do domu a on vylil na jeho hlavu olej a řekl mu: Toto praví Hospodin, Bůh Izraele: Mažu tě za krále nad Hospodinovým lidem, nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Vybiješ dům Achaba, svého pána, a tak pomstím prolitou krev otroků proroků a prolitou krev všech Hospodinových otroků z ruky Jezábely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Vyhyne celý dům Achabův, vyhladím Achabovi ⌈močícího na stěnu,⌉ zadržovaného i propuštěného v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Naložím s domem Achabovým jako s domem Jarobeáma, syna Nebatova, a s domem Baeši, syna Achijášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'A Jezábelu sežerou psi na dílu pole v Jizreelu a nebude, kdo by ji pohřbil. Pak otevřel dveře a utekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Když Jehú vyšel k otrokům svého pána, zeptali se ho: Vše v pořádku? Proč k tobě přišel ten potřeštěnec? Odpověděl jim: Znáte toho muže a jeho řeči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Řekli mu: Klameš. Pověz nám to. Odpověděl: ⌈To a to⌉ mi řekl: Toto praví Hospodin: Mažu tě za krále nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Rychle vzali každý svůj šat, položili ho před něj na holé schody, zatroubili na beraní roh a volali: Jehú se stal králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Tak se Jehú, syn Jóšafata, syna Nimšího, spikl proti Jóramovi. (Tehdy Jóram, on a celý Izrael, chránil Rámot–gileád před aramejským králem Chazaelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Ale král Jóram se vrátil, aby se vyléčil v Jizreelu z ran, které mu způsobili Aramejci, když bojoval proti aramejskému králi Chazaelovi.) Jehú řekl: Jestliže je toto vaším přáním, ať nikdo neunikne z města, aby šel a oznámil to v Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Jehú nasedl a jel do Jizreelu, protože tam Jóram ležel a judský král Achazjáš se přišel na Jórama podívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Strážný stál na věži v Jizreelu a viděl přijíždět Jehúův houf. Řekl: Vidím houf lidí. Jóram nato řekl: Vezmi jezdce a pošli jim ho naproti; ať se zeptá, jestli je vše v pořádku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Jezdec na koni mu vyjel naproti a řekl: Takto se ptá král: Vše v pořádku? Jehú odpověděl: Co je ti do pořádku? Zařaď se za mě! Strážný oznámil: Posel dojel až k nim, ale nevrací se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Poslal druhého jezdce na koni. Přijel k nim a řekl: Takto se ptá král: Vše v pořádku? Jehú odpověděl: Co je ti do pořádku? Zařaď se za mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Strážný oznámil: Přijel až k nim, ale nevrací se. Ta jízda vypadá jako jízda Jehúa, syna Nimšího. Žene se ⌈jako šílený.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Jóram řekl: Zapřáhni. Zapřáhl jeho vůz a izraelský král Jóram i judský král Achazjáš vyjeli každý ve svém voze a jeli naproti Jehúovi. Potkali ho na poli Nábota Jizreelského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'I stalo se, když Jóram uviděl Jehúa, že se zeptal: Vše v pořádku, Jehú? On odpověděl: Jaký pořádek, dokud jsou zde smilstva tvé matky Jezábely a její mnohá kouzla?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Jóram obrátil koně, utíkal a volal na Achazjáše: Zrada, Achazjáši!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Jehú ⌈napjal luk⌉ a zasáhl Jórama mezi ramena. Šíp ⌈mu pronikl srdcem⌉ a on klesl do vozu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Jehú řekl svému kapitánovi Bidkarovi: Vezmi ho a hoď na díl pole Nábota Jizreelského. Vzpomeň, jak jsme spolu jezdili ve spřežení za jeho otcem Achabem a Hospodin nad ním vynesl tento výnos:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Jistě jsem včera spatřil prolitou krev Nábota a prolitou krev jeho synů, je Hospodinův výrok, a odplatím ti na tomto poli, je Hospodinův výrok. Nyní ho vezmi a hoď na to pole podle Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Když to judský král Achazjáš viděl, utíkal směrem k Bét–haganu. Ale Jehú jej pronásledoval a řekl: ⌈Také toho zabijte. Ranili ho ve voze⌉ na svahu Gúru, který je u Jibleámu. Utekl sice do Megida, ale tam zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Jeho otroci ⌈jej dovezli ve voze⌉ do Jeruzaléma a pohřbili ho v jeho hrobě s jeho otci v Městě Davidově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Achazjáš se stal králem nad Judou v jedenáctém roce vlády Jórama, syna Achabova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Jehú jel do Jizreelu. Když se o tom Jezábel doslechla, nalíčila si oči, upravila si hlavu a vyhlížela z okna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Když přijel Jehú do brány, zeptala se ho: Vše v pořádku, Zimrí, vrahu svého pána?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, '⌈Podíval se na okno⌉ a zavolal: Kdo je se mnou, kdo? Vyhlédli k němu dva nebo tři dvorní úředníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Řekl: Shoďte ji. Shodili ji a její krev vystříkla na zeď a na koně a ti ji ušlapali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Pak vešel, a když se najedl a napil, řekl: Postarejte se o tu proklatou a pohřběte ji, vždyť je to královská dcera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Šli, aby ji pohřbili, ale nenašli ji, jenom lebku, nohy a ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Vrátili se a oznámili mu to. Řekl: Takové bylo Hospodinovo slovo, které promluvil prostřednictvím svého otroka Elijáše Tišbejského: Na území Jizreelu budou žrát psi tělo Jezábely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'A Jezábelina mrtvola bude jako hnůj na povrchu země na území Jizreelu, takže nikdo ne bude moci říct: Toto je Jezábel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Achab měl v Samaří sedmdesát synů. Jehú napsal dopisy a poslal je do Samaří ⌈jizreelským knížatům,⌉ starším a ⌈Achabovým vychovatelům⌉ se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Nuže, jakmile se k vám dostane tento dopis -- jsou u vás přece synové vašeho pána, jsou u vás vozy a koně, opevněné město a zbroj --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'vyhlédněte si toho nejlepšího a nejvhodnějšího ze synů svého pána, ustanovte ho na trůn jeho otce a bojujte za dům svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Oni se však převelice báli; řekli si: Hle, dva králové před ním neobstáli, jak bychom mohli obstát my?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Proto ten, kdo byl nad domem, i ten, kdo byl nad městem, starší i vychovatelé vzkázali Jehúovi: Jsme tvoji otroci a všechno, co nám řekneš, uděláme. Neustanovíme si nikoho králem, dělej, co je ⌈ti libo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Napsal jim druhý dopis se slovy: Jestliže jste se mnou a posloucháte můj hlas, vezměte hlavy mužů, synů svého pána, a přineste mi je zítra touto dobou do Jizreelu. Královských synů bylo sedmdesát mužů a byli u významných lidí města, kteří je vychovávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'I stalo se, když se k nim dostal dopis, vzali královské syny, pobili sedmdesát mužů, jejich hlavy položili do košů a poslali mu je do Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Přišel posel a oznámil mu: Přinesli hlavy královských synů. On nato řekl: Složte je na dvě hromady u vchodu do brány až do rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'I stalo se ráno, že vyšel, postavil se a řekl všemu lidu: Jste nevinní. Hle, já jsem se spikl proti svému pánu a zabil jsem ho. Ale kdo zabil všechny tyto?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Uznejte tedy, že nic z Hospodinova slova, které Hospodin promluvil proti domu Achabovu, nepadlo na zem. Hospodin učinil, jak promluvil prostřednictvím svého otroka Elijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'A Jehú pobil všechny, kteří zůstali domu Achabovu v Jizreelu, všechny jeho významné lidi, přátele a kněze, až mu nezůstal nikdo, kdo by přežil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Potom vstal, odešel a šel do Samaří. Když byl na cestě u pastýřského Bét–ekedu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'potkal Jehú bratry judského krále Achazjáše. Zeptal se: Kdo jste? Odpověděli: Jsme Achazjášovi bratři a přišli jsme ⌈se zeptat, jak se daří⌉ synům krále a synům královny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Řekl: Chyťte je živé. Chytili je živé a pobili je v jámě u Bét–ekedu, čtyřicet dva mužů; nikoho z nich neponechali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Když šel Jehú odtamtud, potkal Jónadaba, syna Rekábova, jak jde proti němu. Pozdravil ho a zeptal se ho: ⌈Je tvé srdce upřímné tak, jako je mé srdce upřímné vůči tvému srdci?⌉ Jónadab odpověděl: Je. Jestliže je, podej mi ruku. Podal mu ruku a on ho vzal k sobě do vozu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Pak řekl: Pojeď se mnou a podívej se na mou horlivost pro Hospodina. A nechal ho jet ve svém voze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Když přijel do Samaří, pobil všechny, kteří zůstali Achabovi v Samaří, zcela ho vyhladil, podle Hospodinova slova, které promluvil k Elijášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Nato Jehú shromáždil všechen lid a řekl jim: Achab sloužil Baalovi málo, Jehú mu bude sloužit víc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Nuže zavolejte ke mně všechny Baalovy proroky, všechny, kdo mu otročí, všechny jeho kněze, nikdo ať nechybí, protože chystám velký obětní hod pro Baala. Ten, kdo by chyběl, nezůstane naživu. Jehú však jednal lstivě, aby vyhubil ty, kdo otročili Baalovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jehú řekl: Nachystejte shromáždění pro Baala! A bylo svoláno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Jehú vzkázal do celého Izraele a přišli všichni, kdo otročili Baalovi, nezůstal nikdo, kdo by nepřišel. Přišli do Baalova domu a Baalův dům se naplnil ⌈hlava na hlavu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Jehú řekl tomu, kdo byl nad šatnou: Přines oděv pro všechny, kdo otročí Baalovi. Přinesl jim oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Jehú s Jónadabem, synem Rekábovým, přišel do Baalova domu a řekl těm, kdo otročili Baalovi: Porozhlédněte se a podívejte se, zdali tu s vámi není někdo z otroků Hospodinových, zdali jsou zde jenom ti, kdo otročí Baalovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Když vešli obětovat ⌈oběti a zápaly,⌉ Jehú připravil venku osmdesát mužů a řekl: Ten, kdo by nechal uniknout někoho z mužů, jež přivedu do vašich rukou, svým životem zaplatí za jeho život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'I stalo se, když skončilo konání zápalné oběti, že řekl Jehú běžcům a kapitánům: Jděte a pobíjejte je, ať nikdo neodejde. Běžci a kapitáni je pobili ostřím meče a vyhodili ven; a pak šli do vnitřku Baalova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Vynesli posvátné sloupy Baalova domu a spálili je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Strhli Baalův posvátný sloup, strhli Baalův dům a učinili ho latrínou, jak je tomu až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Tak vyhladil Jehú Baala z Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Ovšem od hříchů Jarobeáma, syna Nebatova, který svedl Izrael k hříchu, se Jehú neodvrátil -- od zlatých telat, která byla v Bét–elu a v Danu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Hospodin řekl Jehúovi: Protože jsi jednal dobře a vykonal to, co je správné v mých očích, a naložil jsi s domem Achabovým právě tak, jak bylo v mém srdci, tvoji synové budou sedět na izraelském trůnu do čtvrtého pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Jehú však nedbal na to, aby chodil celým svým srdcem podle zákona Hospodina, Boha Izraele, a neodvrátil se od hříchů Jarobeáma, který svedl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'V den onen začal Hospodin osekávat Izrael. Chazael je pobíjel na celém území Izraele');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'od Jordánu na východ slunce, celou zemi Gileád, zemi Gádovců, Rúbenovců a Manasesovců, od Aróeru u potoka Arnónu, ke Gileádu a Bášanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Ostatní Jehúovy činy, všechny věci, které činil a všechny jeho udatné skutky, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'I ulehl Jehú se svými otci a pohřbili ho v Samaří. Po něm se stal králem jeho syn Jóachaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Doba, po kterou Jehú kraloval nad Izraelem v Samaří, byla dvacet osm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Když Atalja, matka Achazjášova, viděla, že její syn zemřel, povstala a zahubila všechno královské potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Ale Jóšeba, dcera krále Jórama, sestra Achazjášova, vzala Jóaše, syna Achazjášova, ukradla ho zprostřed královských synů, kteří byli usmrcováni, a dala jej i jeho kojnou do ložnice. Skryli ho před Ataljou, takže nebyl usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Byl s ní v Hospodinově domě ukryt po šest let, zatímco Atalja kralovala nad zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'V sedmém roce Jójada poslal posly, nechal přivést velitele nad sty, Karijce a běžce a zavedl je k sobě do Hospodinova domu. Uzavřel s nimi smlouvu a zapřisáhl je v Hospodinově domě. Pak jim ukázal královského syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Přikázal jim: Uděláte toto: Třetina z vás, kteří přicházíte v sobotu, budete na stráži královského paláce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'třetina v bráně Súr a třetina v bráně za běžci -- budete střídavě konat stráž domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Dvě družiny z vás, všichni, kteří odcházíte v sobotu, budou konat stráž v Hospodinově domě pro krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Obklopíte krále, každý se zbraní v ruce, a ten, kdo by prolomil řady, bude usmrcen. Buďte s králem při jeho vycházení i vcházení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Velitelé nad sty učinili všechno tak, jak přikázal kněz Jójada: Každý si vzal své muže -- ty, kteří přicházejí v sobotu do služby, s těmi, kteří odcházejí v sobotu ze služby -- a šli ke knězi Jójadovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Kněz dal velitelům nad sty kopí a štíty krále Davida, které byly v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Běžci stáli okolo krále každý se zbraní v ruce od pravé strany domu až k levé straně domu, u oltáře i u domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Jójada vyvedl králova syna, vložil na něj korunu a předal mu svědectví; ustanovili ho králem a pomazali ho, tleskali rukama a volali: Ať žije král!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Když Atalja uslyšela halas běžců a lidu, přišla k lidu do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Rozhlédla se a uviděla krále stojícího u sloupu, jak bylo zvykem, a velitele a trubače u krále i všechen lid země, jak se raduje a troubí na trubky. Atalja roztrhla své roucho a volala: Spiknutí, spiknutí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Kněz Jójada dal příkaz velitelům nad sty ustanoveným nad vojskem a řekl jim: Vyveďte ji z domu mezi řadami a toho, kdo půjde za ní, usmrťte mečem; kněz totiž řekl: Ať není usmrcena v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, '⌈Vztáhli na ni ruce⌉ a šla cestou, kudy vcházejí koně do královského paláce, a tam byla usmrcena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Jójada pak uzavřel smlouvu mezi Hospodinem a králem a lidem, že budou Hospodinovým lidem, a také mezi králem a lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, '⌈Všechen lid země⌉ vešel do Baalova domu a strhli ho; jeho oltáře a jeho obrazy zcela roztřískali a Baalova kněze Matána před oltáři zabili. Kněz Jójada ustanovil nad Hospodinovým domem dozorce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Vzal velitele nad sty, Karijce, běžce a všechen lid země a odvedli krále z Hospodinova domu a šli bránou běžců do královského paláce. I usedl na královský trůn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Všechen lid země se radoval a město mělo klid. Atalju usmrtili mečem v královském domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Jóašovi bylo sedm let, když se stal králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'V sedmém roce vlády Jehúa se Jóaš stal králem a kraloval v Jeruzalémě čtyřicet let. Jeho matka se jmenovala Sibja z Beer–šeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Jóaš činil po všechny své dny to, co je správné v Hospodinových očích, jak ho učil kněz Jójada.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Ovšem návrší nebyla odstraněna, lid na návrších dál obětoval a pálil kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Jóaš řekl kněžím: Všechno stříbro ze ⌈svatých věcí,⌉ které bude přineseno do Hospodinova domu -- stříbro ⌈procházejícího muže,⌉ stříbro lidí, jeho hodnota, všechno stříbro, které ⌈se někdo rozhodne dobrovolně⌉ přinést do Hospodinova domu --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'ať si berou kněží, každý od svého pokladníka, a ať opravují poškození domu, každé poškození, které se tam najde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'I stalo se v dvacátém třetím roce vlády krále Jóaše, že kněží neopravovali poškození domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Král Jóaš zavolal kněze Jójadu a další kněze a řekl jim: Proč neopravujete poškození domu? Již nebudete brát stříbro od svých pokladníků, pokud ho nechcete dávat na opravu poškození domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Kněží souhlasili, že nebudou brát stříbro od lidu a také nebudou opravovat poškození domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Kněz Jójada vzal jednu truhlu, vyvrtal do víka díru a dal ji vedle oltáře, napravo, kudy se vchází do Hospodinova domu. Kněží, strážci prahu, tam dávali všechno stříbro přinesené do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'I stalo se, když viděli, že je v truhle příliš mnoho stříbra, přišel královský písař a velekněz, zabalili a spočítali stříbro, které se v Hospodinově domě nacházelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Pak dávali odvážené stříbro do rukou dílovedoucích ustanovených nad Hospodinovým domem a ti ho rozdělovali tesařům a stavitelům, kteří pracovali na Hospodinově domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'zedníkům a kameníkům, na nákup dřeva a tesaných kamenů k opravě poškození Hospodinova domu a na každý výdaj na opravení domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Ze stříbra přineseného do Hospodinova domu se ovšem nedělaly stříbrné číše, nůžky na knoty, misky, trubky, žádné zlaté ani stříbrné předměty v Hospodinově domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'ale dávalo se dílovedoucím a ti z něj opravovali Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Od mužů, kterým dávali stříbro do rukou, aby je dali dílovedoucím, nepožadovali vyúčtování, protože jednali poctivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Stříbro z obětí za vinu a stříbro z obětí za hřích nebylo přinášeno do Hospodinova domu, patřilo kněžím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Tehdy vytáhl aramejský král Chazael, bojoval proti Gatu a dobyl ho. Pak se Chazael rozhodl vytáhnout proti Jeruzalému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Nato vzal judský král Jóaš všechny svaté věci, které posvětili jeho otcové, judští králové Jóšafat, Jóram a Achazjáš, a své vlastní svaté věci i všechno zlato, které se nacházelo v pokladnicích domu Hospodinova i domu královského, a poslal to aramejskému králi Chazaelovi. Ten od Jeruzaléma odtáhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Ostatní Jóašovy činy, všechny věci, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Avšak jeho otroci povstali, zosnovali spiknutí a zabili Jóaše v Bét–Miló na sestupu do Sily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'Zabili ho jeho otroci Józabad, syn Šimeátin, a Józabad, syn Šómerův. Zemřel a pohřbili ho s jeho otci v Městě Davidově. Po něm se stal králem jeho syn Amasjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'V dvacátém třetím roce vlády judského krále Jóaše, syna Achazjášova, se stal králem nad Izraelem v Samaří Jóachaz, syn Jehúův; kraloval sedmnáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Páchal to, co je zlé v Hospodinových očích, a následoval hříchy Jarobeáma, syna Nebatova, který svedl Izrael k hříchu, a neodvrátil se od nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Tehdy vzplál Hospodinův hněv proti Izraeli a vydal je po všechny ty dny do ruky aramejského krále Chazaela a do ruky Ben–hadada, syna Chazaelova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Jóachaz se snažil udobřit Hospodinovu tvář a Hospodin ⌈ho vyslyšel,⌉ protože viděl útlak Izraele, jak je aramejský král utlačoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Hospodin dal Izraeli zachránce, takže vyšli zpod moci Aramejců; a synové Izraele bydleli jako dříve ve svých stanech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Neodvrátili se ovšem od hříchů domu Jarobeáma, který svedl Izrael k hříchu, ale ⌈následovali je.⌉ Také posvátný kůl zůstal stát v Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Neponechal Jóachazovi vojenský lid, pouze padesát jezdců, deset vozů a deset tisíc pěšáků, neboť aramejský král je zničil a učinil je jako prach k zadupání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Ostatní Jóachazovy činy a všechny věci, které činil, a jeho udatné skutky jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Jóachaz ulehl se svými otci a pohřbili ho v Samaří. Po něm se stal králem jeho syn Jóaš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'V třicátém sedmém roce vlády judského krále Jóaše se stal králem nad Izraelem v Samaří Jóaš, syn Jóachazův. Kraloval šestnáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Páchal to, co je zlé v Hospodinových očích, neodvrátil se od všech hříchů Jarobeáma, syna Nebatova, který svedl Izrael k hříchu, ale následoval je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Ostatní Jóašovy činy, všechny věci, které činil, a jeho udatné skutky, jak bojoval s judským králem Amasjášem, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Jóaš ulehl se svými otci a na jeho trůn usedl Jarobeám. Jóaš byl pohřben v Samaří s izraelskými králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Elíša onemocněl nemocí, na kterou měl zemřít. Přišel k němu izraelský král Jóaš a rozplakal se nad ním. Řekl: Můj otče, můj otče! ⌈Vozbo Izraele⌉ a jeho jezdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elíša mu řekl: Vezmi luk a šípy. Vzal si luk a šípy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Potom řekl izraelskému králi: Vlož svou ruku na luk. Vložil svou ruku a Elíša položil své ruce na ruce královy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Řekl: Otevři okno na východ. Otevřel a Elíša řekl: Vystřel. Vystřelil a Elíša řekl: Šíp Hospodinovy záchrany a šíp ⌈záchrany proti Aramejcům.⌉ Zcela pobiješ Aramejce u Afeku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Pak řekl: Vezmi si šípy. Vzal si je a Elíša řekl izraelskému králi: Udeř do země. Udeřil třikrát a přestal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Muž Boží se na něj rozhněval a řekl: Měl jsi udeřit pět krát nebo šestkrát. Tak bys zcela pobil Aramejce. Nyní pobiješ Aramejce třikrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Elíša zemřel a pohřbili ho. Na počátku roku pronikly do země loupežné hordy Moábců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Jednou se stalo, že pohřbívali nějakého muže, když tu uviděli loupežnou hordu. Hodili toho muže do Elíšova hrobu ⌈a šli. Jakmile se ten muž dotkl⌉ Elíšových kostí, ožil a postavil se na nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Aramejský král Chazael utlačoval Izrael po všechny Jóachazovy dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Ale Hospodin jim byl milostiv, slitoval se nad nimi a ⌈pohleděl na ně⌉ kvůli své smlouvě s Abrahamem, Izákem a Jákobem; nechtěl je zničit a dosud je od ⌈sebe neodvrhl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Aramejský král Chazael zemřel a po něm se stal králem jeho syn Ben–hadad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Jóaš, syn Jóachazův, znovu vzal z ruky Ben–hadada, syna Chazaelova, města, která vzal z ruky jeho otce Jóachaza. Třikrát ho Jóaš pobil v boji a získal zpět izraelská města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'V druhém roce vlády izraelského krále Jóaše, syna Jóachazova, se stal králem Amasjáš, syn judského krále Jóaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Bylo mu dvacet pět let, když se stal králem, a kraloval v Jeruzalémě dvacet devět let. Jeho matka se jmenovala Jóadan z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Činil to, co je správné v Hospodinových očích, ovšem ne jako jeho otec David. Jednal stejně jako jednal jeho otec Jóaš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Ovšem návrší nebyla odstraněna, lid na návrších dál obětoval a pálil kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'I stalo se, když bylo království pevně v jeho ruce, že pobil své otroky, kteří zabili krále, jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Ale syny těch, kdo ho zabili, neusmrtil, jak je napsáno v knize Mojžíšova zákona, že přikázal Hospodin: ať nejsou usmrceni otcové kvůli synům a synové ať nejsou usmrceni kvůli otcům, ale každý ať je usmrcen za svůj hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Pobil deset tisíc Edómců v Solném údolí a zmocnil se v boji též Sély a pojmenoval ji Jokteel, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Tehdy poslal Amasjáš posly k izraelskému králi Jóašovi, synu Jóachaza, synu Jehúa, se slovy: Pojď, ⌈střetneme se tváří v tvář.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Izraelský král Jóaš vzkázal judskému králi Amasjášovi: Libanonské trní vzkázalo libanonskému cedru: Dej svou dceru mému synovi za ženu. Polní zvěř libanonská prošla a pošlapala to trní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, '⌈Protože jsi pobil Edómce,⌉ ⌈pozvedlo se tvé srdce.⌉ Oslavuj a zůstaň doma. Proč by ses měl zaplétat se zlem a padnout ty a Juda s tebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Ale Amasjáš neposlechl. Izraelský král Jóaš vytáhl a střetli se tváří v tvář s judským králem Amasjášem v Bét–šemeši v Judsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Juda byl od Izraele poražen a všichni utíkali ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Judského krále Amasjáše, syna Jóaše, syna Achazjášova, chytil izraelský král Jóaš v Bét–šemeši. Pak přitáhl do Jeruzaléma a protrhl jeruzalémské hradby od Efrajimské brány až k bráně Rohové, na čtyři sta loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Pobral všechno zlato a stříbro a všechny předměty, které se nacházely v Hospodinově domě a v pokladnicích královského paláce, i rukojmí a vrátil se do Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Ostatní Jóašovy činy, které činil a jeho udatné skutky, jak bojoval s judským králem Amasjášem, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Jóaš ulehl se svými otci a byl pohřben v Samaří s izraelskými králi. Po něm se stal králem jeho syn Jarobeám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Judský král Amasjáš, syn Jóašův, žil po smrti izraelského krále Jóaše, syna Jóachazova, patnáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Ostatní Amasjášovy činy jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Zosnovali však proti němu v Jeruzalémě spiknutí, a tak utekl do Lakíše. Poslali však za ním do Lakíše a usmrtili ho tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Naložili ho pak na koně a byl pohřben se svými otci v Jeruzalémě, Městě Davidově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Všechen judský lid vzal Azarjáše, kterému bylo šestnáct let, a ustanovili ho králem místo jeho otce Amasjáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'On vystavěl Élat a vrátil ho Judsku potom, co král Amasjáš ulehl se svými otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'V patnáctém roce vlády judského krále Amasjáše, syna Jóašova, se stal králem v Samaří Jarobeám, syn izraelského krále Jóaše. Kraloval čtyřicet jedna let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Páchal to, co je zlé v Hospodinových očích, neodvrátil se od všech hříchů Jarobeáma, syna Nebatova, který svedl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'On získal zpět izraelské území od Lebo–Chamátu až k moři Araby, podle slova Hospodina, Boha Izraele, které promluvil prostřednictvím svého otroka Jonáše, syna Amítajova, proroka z Gat–chéferu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Neboť Hospodin viděl soužení Izraele, jež bylo velmi trpké -- nebylo zadržovaného ani propuštěného, Izrael neměl pomocníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Hospodin nevyhlásil, že vymaže jméno Izrael zpod nebes, a proto je zachránil prostřednictvím Jarobeáma, syna Jóašova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Ostatní Jarobeámovy činy, všechny věci, které činil, i jeho udatné skutky, jak bojoval a získal zpět Damašek a Chamát ⌈pro Judu v Izraeli,⌉ jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Jarobeám ulehl se svými otci, s izraelskými králi. Po něm se stal králem jeho syn Zekarjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'V dvacátém sedmém roce vlády izraelského krále Jarobeáma se stal judským králem Azarjáš, syn Amasjášův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Bylo mu šestnáct let, když se stal králem, a kraloval v Jeruzalémě padesát dva let. Jeho matka se jmenovala Jekolja z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Činil to, co je správné v Hospodinových očích, stejně jako to činil jeho otec Amasjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Ovšem návrší nebyla odstraněna, lid na návrších dál obětoval a pálil kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Hospodin zasáhl krále, takže byl postižen malomocenstvím až do dne své smrti. Bydlel v odděleném domě a králův syn Jótam byl nad palácem a soudil lid země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Ostatní Azarjášovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Azarjáš ulehl se svými otci a pohřbili ho s jeho otci v Městě Davidově. Po něm se stal králem jeho syn Jótam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'V třicátém osmém roce vlády judského krále Azarjáše se stal králem nad Izraelem v Samaří Zekarjáš, syn Jarobeámův. Kraloval šest měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Páchal to, co je zlé v Hospodinových očích, tak jako to činil jeho otec. Neodvrátil se od hříchů Jarobeáma, syna Nebatova, který svedl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Spikl se proti němu Šalúm, syn Jábešův; ubil ho ⌈před lidem,⌉ usmrtil ho a stal se po něm králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Ostatní Zekarjášovy činy jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Takové bylo Hospodinovo slovo, které promluvil k Jehúovi: Tvoji synové do čtvrté generace budou sedět na izraelském trůnu. A stalo se tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Šalúm, syn Jábešův, se stal králem v třicátém devátém roce vlády judského krále Uzijáše. Kraloval v Samaří ⌈jeden měsíc.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Pak Menachém, syn Gadíův, vytáhl z Tirsy a přišel do Samaří; ubil v Samaří Šalúma, syna Jábešova, usmrtil ho a stal se po něm králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Ostatní Šalúmovy činy i spiknutí, které zosnoval, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Tehdy z Tirsy Menachém vybil Tifsach, všechno, co bylo v něm, i jeho území, protože mu neotevřeli. Vybil ho a všechny jeho těhotné rozpáral.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'V třicátém devátém roce vlády judského krále Azarjáše se stal králem nad Izraelem Menachém, syn Gadíův. Kraloval v Samaří deset let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Páchal to, co je zlé v Hospodinových očích. Po všechny své dny se neodvrátil od hříchů Jarobeáma, syna Nebatova, který svedl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Asyrský král Púl přitáhl proti zemi. Menachém dal Púlovi tisíc talentů stříbra, aby jeho ruce byly s ním a království se tak v jeho ruce upevnilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Menachém vybral to stříbro na Izraeli, ode všech ⌈zámožných lidí,⌉ aby dal asyrskému králi padesát šekelů stříbra za jednoho muže. Asyrský král se vrátil a nezůstal tam v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Ostatní Menachémovy činy, všechny věci, které činil, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menachém ulehl se svými otci. Po něm se stal králem jeho syn Pekachjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'V padesátém roce vlády judského krále Azarjáše se stal králem nad Izraelem Pekachjáš, syn Menachémův. Kraloval v Samaří dva roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Páchal to, co je zlé v Hospodinových očích. Neodvrátil se od hříchů Jarobeáma, syna Nebatova, který svedl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Spikl se proti němu jeho kapitán Pekach, syn Remaljášův. Ubil ho v Samaří v pevnosti královského domu s Argóbem a Arjéem. Bylo s ním padesát mužů ze synů Gileádových. Usmrtil ho a stal se králem místo něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Ostatní Pekachjášovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'V padesátém druhém roce vlády judském krále Azarjáše se stal králem nad Izraelem Pekach, syn Remaljášův. Kraloval v Samaří dvacet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Páchal to, co je zlé v Hospodinových očích. Neodvrátil se od hříchů Jarobeáma, syna Nebatova, který svedl Izrael k hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Ve dnech izraelského krále Pekacha přitáhl asyrský král Tiglat–pileser a zabral Ijón, Ábel–bét–maaku, Janóach, Kedeš, Chasór, Gileád, Galileu a celé území Neftalí a odvedl obyvatele do Asýrie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Hóšea, syn Élův, zosnoval spiknutí proti Pekachovi, synu Remaljášovu, a ubil ho, usmrtil ho a v dvacátém roce vlády Jótama, syna Uzijášova, se stal králem místo něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Ostatní Pekachovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'V druhém roce vlády izraelského krále Pekacha, syna Remaljášova, se stal judským králem Jótam, syn Uzijášův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Bylo mu dvacet pět let, když se stal králem, a kraloval v Jeruzalémě šestnáct let. Jeho matka se jmenovala Jerúša, dcera Sádokova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Činil to, co je správné v Hospodinových očích, jednal stejně jako jednal jeho otec Uzijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Ovšem návrší nebyla odstraněna, lid na návrší dál obětoval a pálil kadidlo. On postavil Horní bránu Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Ostatní Jótamovy činy, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'V oněch dnech začal Hospodin posílat proti Judovi aramejského krále Resína a Pekacha, syna Remaljášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Jótam ulehl se svými otci a byl pohřben se svými otci v městě svého otce Davida. Po něm se stal králem jeho syn Achaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 39, '');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'V sedmnáctém roce vlády Pekacha, syna Remaljášova, se stal judským králem Achaz, syn Jótamův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Achazovi bylo dvacet let, když se stal králem, a kraloval v Jeruzalémě šestnáct let. Nečinil to, co je správné v očích Hospodina, jeho Boha, jako to činil jeho otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Chodil po cestě izraelských králů, a dokonce provedl svého syna ohněm podle ohavností pohanských národů, které Hospodin před syny Izraele vyhnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Obětoval a pálil kadidlo na návrších a na kopcích a pod každým zeleným stromem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tehdy vytáhl aramejský král Resín a izraelský král Pekach, syn Remaljášův, do boje proti Jeruzalému; oblehli Achaza, ale nemohli ho dobýt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'V oné době získal aramejský král Resín pro Aramejce zpět Elót a Judejce z Elótu vyhnal. Do Élatu přišli Edómci a sídlí tam až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Achaz poslal posly asyrskému králi Tiglat–pileserovi se slovy: Jsem tvůj otrok a tvůj syn. Vytáhni a zachraň mě z ruky krále aramejského a z ruky krále izraelského, kteří povstali proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Achaz vzal stříbro a zlato, které se nacházelo v Hospodinově domě a v pokladnicích královského paláce, a poslal to jako dar asyrskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Asyrský král ho uposlechl. Asyrský král vytáhl proti Damašku, zmocnil se ho, jeho obyvatele odvedl do Kíru a Resína usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Král Achaz se vydal asyrskému králi Tiglat–pileserovi do Damašku naproti a uviděl oltář, který byl v Damašku. Král Achaz poslal knězi Urijášovi náčrt oltáře i plán pro celé jeho zpracování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Kněz Urijáš postavil oltář zcela podle toho, co poslal král Achaz z Damašku. Tak to kněz Urijáš udělal dříve, nežli král Achaz přišel z Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Když král z Damašku přišel, uviděl oltář, přistoupil k oltáři a přinesl na něm oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Obětoval svou zápalnou a přídavnou oběť, vylil svou litou oběť a pokropil ⌈oltář krví ze⌉ svých pokojných obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Bronzový oltář, který byl před Hospodinem, přemístil z průčelí domu (mezi novým oltářem a Hospodinovým domem) a dal ho na severní stranu od nového oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Král Achaz pak přikázal knězi Urijášovi: Na velkém oltáři obětuj ranní zápalnou oběť a večerní přídavnou oběť, zápalnou a přídavnou oběť krále a zápalnou oběť všeho lidu země, jejich přídavnou oběť i jejich litou oběť. Pokrop jej veškerou krví zápalné oběti a veškerou krví obětního hodu. Bronzový oltář mi bude k vyhledávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Kněz Urijáš udělal všechno tak, jak mu král Achaz přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Král Achaz usekl postranice podstavců a odstranil z nich nádrže; sundal také moře z bronzových býků, kteří byli pod ním, a dal ho na kamenný chodník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Též sobotní krytou chodbu, která byla v domě postavena, i královský vnější vchod odstranil z Hospodinova domu kvůli asyrskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Ostatní Achazovy činy, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Achaz ulehl se svými otci a byl pohřben se svými otci v Městě Davidově. Po něm se stal králem jeho syn Chizkijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'V dvanáctém roce vlády judského krále Achaza se stal králem nad Izraelem v Samaří Hóšea, syn Élův. Kraloval devět let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Páchal to, co je zlé v Hospodinových očích, ovšem ne jako izraelští králové, kteří byli před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Vytáhl proti němu asyrský král Šalmaneser. Hóšea se stal jeho otrokem a odváděl mu dávky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Asyrský král však odhalil Hóšeovo spiknutí, že totiž poslal posly k egyptskému králi Sóovi a neodvedl asyrskému králi dávku jako každý rok. Proto ho asyrský král zadržel a spoutal ho v žaláři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Asyrský král táhl celou zemí, přitáhl k Samaří a tři roky ho obléhal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'V devátém roce Hóšeovy vlády asyrský král Samaří dobyl, odvedl Izraelce do Asýrie a usídlil je v Chalachu, u řeky Chabóru v Gózanu a v městech médských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Stalo se to, protože synové Izraele hřešili proti Hospodinu, svému Bohu, který je vyvedl z egyptské země, z područí faraona, egyptského krále. Báli se jiných bohů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'a žili podle náboženských zvyklostí národů, které Hospodin před syny Izraele vyhnal, a podle ustanovení izraelských králů, která ustanovili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Synové Izraele konali proti Hospodinu, svému Bohu, nesprávné věci, a ve všech svých městech -- od strážní věže až po opevněné město -- si postavili návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Posvátné sloupy a posvátné kůly si postavili na každém vyvýšeném návrší a pod každým zeleným stromem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Tam na každém návrší pálili oběti jako národy, které před nimi Hospodin odvedl, a páchali zlé věci, aby Hospodina provokovali k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Sloužili bůžkům, o kterých Hospodin řekl: Nic takového nedělejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Hospodin varoval Izrael a Judu prostřednictvím všech proroků a všech vidoucích slovy: Odvraťte se od svých zlých cest a zachovávejte mé příkazy, má ustanovení zcela podle zákona, který jsem přikázal vašim otcům a který jsem jim poslal prostřednictvím svých otroků proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Neposlouchali však, nýbrž zatvrdili svou šíji jako ⌈jejich otcové,⌉ kteří nevěřili Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Zavrhli jeho ustanovení a jeho smlouvu, kterou uzavřel s jejich otci, i jeho napomenutí, kterými je napomínal. Chodili za nicotností a nicotností se stali, i za národy, které byly kolem nich a o nichž Hospodin přikázal, aby nejednali jako oni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Opustili všechny příkazy Hospodina, svého Boha, a udělali si lité modly, dvě telata, i posvátné kůly a klaněli se celému nebeskému zástupu a sloužili Baalovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Prováděli své syny a dcery ohněm, ⌈zabývali se věštěním⌉ a znameními, zaprodali se, aby páchali to, co je zlé v Hospodinových očích, a tak ho provokovali k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Hospodin se na Izrael velmi rozhněval, odstranil jej od své tváře; zůstal jenom sám kmen Juda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Ani Juda však nezachoval příkazy Hospodina, svého Boha. Žili podle ⌈ náboženských zvyklostí, které si Izrael ustanovil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Hospodin zavrhl celé potomstvo Izraele, pokořil je a vydal je do ruky pustošitelů, až je od sebe odvrhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Když odtrhl Izrael od domu Davidova, ustanovili si králem Jarobeáma, syna Nebatova. Jarobeám odvedl Izrael od následování Hospodina a svedl ho k velkému hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Synové Izraele pak následovali všechny hříchy Jarobeámovy, které páchal, a neodvrátili se od nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Nakonec Hospodin odstranil Izrael od své tváře, jak řekl prostřednictvím všech svých otroků proroků, a odvedl Izrael z jeho země do Asýrie, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Asyrský král přivedl lid z Babylona, z Kútu, Avy, Chamátu a Sefarvajimu a usídlil ho v samařských městech místo synů Izraele; obsadili Samaří a pobývali v jeho městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'I stalo se na počátku, co tam sídlili, že se nebáli Hospodina a Hospodin mezi ně poslal lvy a ti mezi nimi zabíjeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Tehdy řekli asyrskému králi: Národy, které jsi odvedl a usídlil v samařských městech, neznají nařízení Boha té země. Poslal mezi ně lvy a ti je usmrcují, protože neznají nařízení Boha té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Asyrský král přikázal: Přiveďte tam jednoho z kněží, které jste odtamtud odvedli. Ať jde, pobývá tam a ať je vyučuje nařízení Boha té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Přišel tedy jeden z kněží, ⌈kteří byli odvedeni⌉ ze Samaří, pobýval v Bét–elu a učil je, jak se mají bát Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, '⌈Každý národ⌉ si udělal své bohy a položili je ve svatyních návrší, které udělali Samařané; každý národ to udělal ve svých městech, kde pobývali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Muži z Babylonu si udělali Sukót–benóta, muži z Kútu si udělali Nergala, muži z Chamátu si udělali Ašímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Avíjci si udělali Nibchaza a Tartaka, Sefarvajimci spalovali své syny ohněm Adramelekovi a Anamelekovi, bohům Sefarvajimu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Báli se Hospodina, ale udělali si ze své spodiny kněze návrší. Ti za ně jednali ve svatyních návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Báli se Hospodina, ale otročili svým bohům podle nařízení národů, odkud byli odvedeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Dodnes jednají podle dřívějších nařízení, nebojí se Hospodina a nejednají podle ustanovení, nařízení, zákona a příkazů, které Hospodin přikázal synům Jákoba, jemuž dal jméno Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Hospodin s nimi uzavřel smlouvu a přikázal jim: Nebojte se jiných bohů, neklaňte se jim, neslužte jim a neobětujte jim;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'ale jenom Hospodina, který vás vyvedl z egyptské země velkou silou a vztaženou paží -- toho se bojte, jemu se klaňte a jemu obětujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Ta ustanovení, nařízení, zákony a příkazy, které vám napsal, zachovávejte a plňte po všechny dny. Nebojte se jiných bohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Na smlouvu, kterou s vámi uzavřel, nezapomínejte. Nebojte se jiných bohů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'ale jenom Hospodina, svého Boha, se bojte a on vás vysvobodí z ruky všech vašich nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Neposlechli, ale jednali podle svých dřívějších nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Tyto národy se bály Hospodina, ale otročily svým tesaným modlám; ano i jejich synové a synové jejich synů jednali tak, jako jednali jejich otcové, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'V třetím roce vlády izraelského krále Hóšey, syna Élova, se stal judským králem Chizkijáš, syn Achazův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Bylo mu dvacet pět let, když se stal králem, a kraloval v Jeruzalémě dvacet devět let. Jeho matka se jmenovala Abí, dcera Zekarjášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Činil to, co je správné v Hospodinových očích, stejně jako to činil jeho otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Odstranil návrší, roztřískal sloupy a pokácel ⌈posvátné kůly.⌉ Rozbil též bronzového hada, kterého udělal Mojžíš, protože až do oněch dnů mu synové Izraele obětovali. ⌈Nazývali ho⌉ Nechuštán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Důvěřoval Hospodinu, Bohu Izraele. Po něm nebyl nikdo jemu podobný mezi všemi judskými králi, ani před ním ne byli žádní takoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Přilnul k Hospodinu, neodvrátil se od něj a zachovával jeho příkazy, které dal Hospodin Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Hospodin byl s ním a kamkoli šel, měl úspěch. Vzbouřil se proti asyrskému králi a nesloužil mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Pobil Pelištejce až ke Gaze a jejímu území, od ⌈strážní věže až k opevněnému městu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'I stalo se ve čtvrtém roce vlády krále Chizkijáše -- to byl sedmý rok vlády izraelského krále Hóšey, syna Élova, že vytáhl asyrský král Šalmaneser proti Samaří a oblehl je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Dobyli ho po třech letech; v šestém roce vlády Chizkijáše, ten byl devátý rok vlády izraelského krále Hóšey, bylo Samaří dobyto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Asyrský král odvedl Izraelce do Asýrie a přivedl je do Chalachu a k řece Chabóru v Gózanu a do měst médských,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'protože neuposlechli Hospodina, svého Boha, ale přestoupili jeho smlouvu a všechno, co přikázal Mojžíš, otrok Hospodinův, neposlouchali a neplnili to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Ve čtrnáctém roce vlády krále Chizkijáše vytáhl asyrský král Sancheríb proti všem opevněným judským městům a zmocnil se jich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Judský král Chizkijáš vzkázal asyrskému králi do Lakíše: Prohřešil jsem se. Odvrať se ode mě a cokoli na mě vložíš, ponesu. Asyrský král judskému králi Chizkijášovi uložil tři sta talentů stříbra a třicet talentů zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Chizkijáš vydal všechno stříbro, které se nacházelo v Hospodinově domě a v pokladnicích královského paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'V oné době osekal Chizkijáš dveře Hospodinova chrámu a obložení, která judský král Chizkijáš sám potáhl, a dal je asyrskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Asyrský král poslal vojevůdce, vrchního úředníka a nejvyššího číšníka z Lakíše ke králi Chizkijášovi s ohromným vojskem do Jeruzaléma. Vytáhli a přišli k Jeruzalému; vytáhli, přišli a zastavili se u strouhy Horního rybníka na silnici k Valchářovu poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Zavolali krále; vyšli k nim Eljakím, syn Chilkijášův, který byl nad domem, písař Šebna a kancléř Jóach, syn Asafův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Nejvyšší číšník jim řekl: Povězte Chizkijášovi: Toto praví veliký král, král asyrský: Co to je za naději, v niž doufáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Myslíš si, že prázdné řeči jsou plánem a silou k boji? Nuže, na koho spoléháš, že ses proti mně vzbouřil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Hle, spoléháš na tu zlomenou třtinovou hůl -- na Egypt, o kterou když se člověk opře, pronikne do jeho ruky a probodne ji? Takový je faraon, egyptský král, pro všechny, kdo na něho spoléhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'A jestliže mi řeknete: Spoléháme na Hospodina, svého Boha! -- což to není on, jehož návrší a oltáře Chizkijáš odstranil a Judovi a Jeruzalému řekl: Před tímto oltářem v Jeruzalémě se klaňte!?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Tak se nyní vsaď s mým pánem, asyrským králem: Dám ti dva tisíce koní, jestlipak na ně budeš schopen dodat jezdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Jak bys mohl odrazit místodržitele, jednoho z nejmenších otroků mého pána, i když ses spolehl na Egypt, na vozbu a koně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Vytáhl jsem snad nyní proti tomuto místu bez Hospodina, abych ho ničil? Hospodin mi řekl: Vytáhni proti této zemi a znič ji!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Eljakím, syn Chilkijášův, Šebna a Jóach nejvyššímu číšníkovi řekli: Mluv přece ke svým otrokům aramejsky, vždyť my rozumíme. Nemluv k nám judsky před lidem, který je na hradbách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Nejvyšší číšník jim řekl: Což mě poslal můj pán mluvit tato slova jen ke tvému pánu a k tobě? Cožpak ne k těm mužům, kteří pobývají na hradbách a budou s vámi jíst svá lejna a pít ⌈svoji moč?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Nejvyšší číšník stál a hlasitě judsky volal. Říkal: Slyšte slovo velikého krále, krále asyrského:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Toto praví král: Ať vás Chizkijáš nepodvádí. Vždyť vás není schopen vysvobodit z mé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Ať ve vás Chizkijáš nevzbuzuje doufání v Hospodina slovy: Hospodin nás jistě vysvobodí; toto město nebude vydáno do ruky asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Neposlouchejte Chizkijáše, neboť toto praví asyrský král: Sjednejte se mnou pokoj, vyjděte ke mně a budete jíst každý ze své révy a ze svého fíkovníku a budete pít každý vodu ze své studny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'dokud ne přijdu a ne vezmu vás do země, podobné zemi vaší, země obilí a vína, země chleba a vinic, země olivového oleje a medu. Zůstanete naživu a nezemřete. Neposlouchejte Chizkijáše, když vás navádí slovy: Hospodin nás vysvobodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Cožpak některý z bohů národů vysvobodil svou zemi z ruky asyrského krále?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kde jsou bohové Chamátu a Arpádu? Kde bohové Sefarvajimu, Heny a Ivy? Jestlipak vysvobodili Samaří z mé ruky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Který ze všech bohů těchto zemí vysvobodil svou zemi z mé ruky? Jestlipak Hospodin vysvobodí Jeruzalém z mé ruky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Lid mlčel a nic mu neodpověděli, protože to byl králův příkaz: Neodpovídejte mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Eljakím, syn Chilkijášův, který byl nad domem, písař Šebna a kancléř Jóach, syn Asafův, šli k Chizkijášovi s roztrženými rouchy a oznámili mu slova nejvyššího číšníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'I stalo se, když to král Chizkijáš uslyšel, že roztrhl své roucho, zakryl se pytlovinou a vešel do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Pak poslal Eljakíma, který byl nad domem, písaře Šebnu a starší kněze zahalené v pytlovině k proroku Izajášovi, synu Amósovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Řekli mu: Toto praví Chizkijáš: Tento den je dnem soužení, trestu a znevážení, protože děti vešly do rodidel, ale není síla k porodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Snad Hospodin, tvůj Bůh, uslyší všechna slova Rabšaka, kterého jeho pán, asyrský král, poslal, aby hanobil živého Boha, a pokárá ho za slova, která Hospodin, tvůj Bůh, slyšel. Pozdvihni tedy modlitbu za ostatek, který se tu nachází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Když přišli otroci krále Chizkijáše k Izajášovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Izajáš jim řekl: Toto řekněte svému pánu: Toto praví Hospodin: Neboj se slov, která jsi slyšel, jimiž mi utrhali služebníci asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Hle, dám do něj ducha, že když uslyší zprávu, vrátí se do své země a nechám jej v jeho zemi padnout mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Když se nejvyšší číšník vrátil, nalezl asyrského krále, jak bojuje proti Libně. Slyšel totiž, že odtáhl od Lakíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Asyrský král uslyšel o kúšském králi Tirhákovi: Hle, vytáhl, aby s tebou bojoval. Nato znovu poslal k Chizkijášovi posly se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Takto promluvte k judskému králi Chizkijášovi: Ať tě tvůj Bůh, v něhož doufáš, nepodvádí slovy: Jeruzalém nebude vydán do ruky asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Hle, sám jsi slyšel, jak asyrští králové naložili se všemi těmi zeměmi, že je zasvětili zkáze. A ty bys byl vysvobozen?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Bohové národů, které moji otcové zničili -- bohové Gózanu, Cháranu, Resefu a synů Edenu, kteří byli v Telasáru -- vysvobodili je snad?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kde je král Chamátu, král Arpádu a král města Sefarvajimu, Heny a Ivy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Chizkijáš vzal od poslů dopis a přečetl ho. Pak Chizkijáš vstoupil do Hospodinova domu a rozprostřel ho před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Pak se Chizkijáš modlil před Hospodinem: Hospodine, Bože Izraele, sedící na cherubech, ty jediný jsi Bůh nad všemi královstvími země; ty jsi učinil nebesa i zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Nakloň, Hospodine, své ucho a slyš; otevři, Hospodine, své oči a pohleď! Slyš Sancheríbova slova, která vzkázal, aby hanobil živého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Hospodine, asyrští králové ty národy a jejich území opravdu zpustošili;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'a jejich bohy uvrhli do ohně, protože to nejsou bohové, nýbrž jen dílo lidských rukou, dřevo a kámen; proto je zničili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'A teď, Hospodine, náš Bože, zachraň nás z jeho ruky, aby všechna království země poznala, že ty jediný, Hospodine, jsi Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Izajáš, syn Amósův, vzkázal Chizkijášovi: Toto praví Hospodin, Bůh Izraele: Slyšel jsem, co ses ke mně modlil ohledně asyrského krále Sancheríba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Toto je slovo, které o něm řekl Hospodin: Pohrdá tebou, vysmívá se ti panna, dcera sijónská, potřásá za tebou hlavou dcera jeruzalémská.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Koho jsi tupil a komu jsi utrhal? Proti komu jsi pozvedl hlas? Vysoko jsi pozdvihl své oči, proti Svatému Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Skrze své posly jsi tupil Panovníka. Řekl sis: S množstvím svých vozů jsem vytáhl na výšiny hor, do nejvzdálenějších částí Libanonu; pokácel jsem jeho vysoké cedry, jeho nejlepší cypřiše; vstoupil jsem do jeho nejzazší výše, do jeho ⌈úrodné lesní zahrady.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Vykopal jsem studny a pil jsem ⌈cizí vodu,⌉ chodidly svých nohou jsem vysušil všechny egyptské řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Cožpak jsi neslyšel, že jsem to již dávno připravil, ode dnů dávnověku jsem to vytvořil? Nyní to naplňuji: Nastalo pustošení, opevněná města se hroutí v hromady kamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Jejich obyvatelé byli bezmocní, vyděšeni a zahanbeni, byli jako polní zeleň a zelené býlí, jako tráva na střechách a pole sežehnuté východním větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Tvé bydlení, tvé vycházení i vcházení znám, také tvé běsnění proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Protože tvé běsnění proti mně a tvá sebejistota vystoupila do mých uší, vložím ti kruh do nosu a uzdu do tvých pysků a odvedu tě zpět cestou, kterou jsi přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'A toto ti bude znamením: Tento rok se bude jíst to, co vyroste samo, v druhém roce to, co ještě z toho vyroste, a ve třetím roce zasévejte a sklízejte, vysazujte vinice a jezte jejich ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'A ti z domu judského, kteří vyváznou, ti pozůstalí, se opět zakoření dolů a ponesou ovoce vzhůru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'neboť z Jeruzaléma vyjde ostatek a ti, kteří vyváznou, z hory Sijón. Horlivost Hospodina zástupů to učiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Proto toto praví Hospodin o asyrském králi: Nevejde do tohoto města, ani šíp tam nevystřelí, nevyjde proti němu se štítem ani proti němu nenavrší násep.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Cestou, kterou přišel, se vrátí a do tohoto města nevejde, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Budu tomuto městu štítem, abych ho zachránil kvůli sobě a kvůli svému otroku Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'I stalo se oné noci, že vyšel Hospodinův anděl a pobil v asyrském táboře sto osmdesát pět tisíc mužů. Když lidé časně ráno vstali, hle, ti všichni byli ⌈dočista mrtví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'A asyrský král Sancheríb odtáhl, šel, vrátil se a pobýval v Ninive.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'I stalo se, když se klaněl v chrámu svého boha Nisrocha, že jeho synové Adramelek a Sareser ho zabili mečem a unikli do země Ararat. Po něm se stal králem jeho syn Esarchadón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'V oněch dnech Chizkijáš na smrt onemocněl. Přišel k němu prorok Izajáš, syn Amósův, a řekl mu: Toto praví Hospodin: Dej příkaz ohledně svého domu, protože zemřeš, nebudeš žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Nato Chizkijáš odvrátil tvář ke stěně a modlil se k Hospodinu slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ach, Hospodine, jen se rozpomeň, jak jsem chodil před tebou věrně a s celým srdcem a činil to, co je dobré v tvých očích. A Chizkijáš se dal do velkého pláče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'I stalo se, že Izajáš nevyšel ani z prostředního nádvoří, když se k němu stalo Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Vrať se a řekni Chizkijášovi, vévodovi mého lidu: Toto praví Hospodin, Bůh tvého otce Davida: Slyšel jsem tvou modlitbu, viděl jsem tvé slzy. Hle, uzdravím tě. Třetího dne vstoupíš do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Přidám ke tvým dnům patnáct let a vysvobodím z ruky asyrského krále tebe i toto město. Budu tomuto městu štítem kvůli sobě a kvůli svému otroku Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Pak Izajáš řekl: Vezměte placku sušených fíků. Vzali to a položili na vřed a král se zotavil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Chizkijáš se zeptal Izajáše: Co bude znamením, že mě Hospodin uzdraví a vstoupím třetího dne do Hospodinova domu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Izajáš odpověděl: Toto ti bude znamením od Hospodina, že Hospodin učiní to, co řekl: Má stín o deset stupňů postoupit, nebo se o deset stupňů vrátit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Chizkijáš řekl: Snadnější je, aby stín o deset stupňů pokročil. Ne, ať se stín vrátí o deset stupňů nazpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Prorok Izajáš volal k Hospodinu a on vrátil stín na stupních, po kterých sestoupil, na stupních Achazových, o deset stupňů nazpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'V té době babylonský král Beródak–baladán, syn Baladánův, poslal Chizkijášovi dopis a dar; slyšel totiž, že byl Chizkijáš nemocen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, '⌈Když o nich Chizkijáš uslyšel,⌉ ukázal jim celou klenotnici, stříbro a zlato, balzámy a vonný olej, zbrojnici a všechno, co se nacházelo v jeho skladech; nebylo nic, co by jim Chizkijáš ve svém paláci a v celém svém panství neukázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Pak přišel ke králi Chizkijášovi prorok Izajáš a zeptal se ho: Co říkali ti muži a odkud k tobě přišli? Chizkijáš odpověděl: Přišli z daleké země, z Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Nato se ho zeptal: Co viděli ve tvém paláci? Chizkijáš odpověděl: Viděli všechno, co je v mém paláci. Nebylo nic, co bych jim ve svých skladech neukázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Izajáš Chizkijášovi řekl: Slyš Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Hle, přicházejí dny, kdy všechno, co je ve tvém paláci a co až dodnes tvoji otcové nahromadili, bude odneseno do Babylona. Nic nezůstane, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'A vezmou z tvých synů, kteří z tebe vzejdou, které zplodíš, a stanou se dvorními úředníky v paláci babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Chizkijáš Izajášovi řekl: Hospodinovo slovo, které jsi vyslovil, je dobré. Řekl si totiž: Za mých dnů bude přece pokoj a bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Ostatní Chizkijášovy činy a všechny jeho udatné skutky, a jak udělal rybník a vodovod, aby přivedl do města vodu, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Chizkijáš ulehl se svými otci a po něm se stal králem jeho syn Menaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Menašemu bylo dvanáct let, když se stal králem, a kraloval v Jeruzalémě padesát pět let. Jeho matka se jmenovala Chefsíba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Páchal to, co je zlé v Hospodinových očích, podle ohavností pohanských národů, které Hospodin před syny Izraele vyhnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Znovu postavil návrší, která jeho otec Chizkijáš zničil, postavil oltáře Baalovi, udělal posvátný kůl, jak to udělal izraelský král Achab, klaněl se celému nebeskému zástupu a sloužil jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Postavil oltáře v Hospodinově domě, o kterém Hospodin řekl: V Jeruzalémě položím své jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Na obou nádvořích Hospodinova domu postavil oltáře pro celý nebeský zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Provedl svého syna ohněm, zabýval se hadačstvím a znameními, ustanovil ty, kdo vyvolávají duchy zemřelých, a věštce. ⌈Páchal mnoho⌉ toho, co je zlé v Hospodinových očích, a tak jej provokoval k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Tesanou modlu Ašery, kterou udělal, postavil v domě, o kterém Hospodin Davidovi a jeho synu Šalomounovi řekl: V tomto domě a v Jeruzalémě, který jsem vyvolil ze všech izraelských kmenů, postavím navěky své jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Nezpůsobím již, aby noha Izraelců prchala ze země, kterou jsem dal jejich otcům, pokud ovšem budou zachovávat a plnit všechno, co jsem jim přikázal, celý zákon, který jim přikázal můj otrok Mojžíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Ale neposlouchali. Menaše je svedl, takže páchali horší věci nežli národy, které Hospodin před syny Izraele vyhladil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Hospodin promluvil prostřednictvím svých otroků proroků:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Protože judský král Menaše páchal tyto ohavnosti, dělal horší věci nežli všechno, co páchali Emorejci, kteří byli před ním, a skrze své bůžky svedl k hříchu i Judu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'proto takto praví Hospodin, Bůh Izraele: Hle, přivedu na Jeruzalém a Judu takové zlo, že každému, kdo o tom uslyší, bude znít v obou uších.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, '⌈Roztáhnu na Jeruzalém měřicí šňůru Samaří a závaží domu Achabova⌉ a vytřu Jeruzalém, jako se vytírá mísa -- utřu a obrátím ⌈dnem vzhůru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Opustím ostatek svého dědictví a vydám je do ruky jejich nepřátel; stanou se kořistí a lupem pro všechny své nepřátele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'protože páchali to, co je zlé v mých očích, a provokovali mě k hněvu ode dne, kdy jejich otcové vyšli z Egypta, až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Menaše také prolil velmi mnoho nevinné krve, takže naplnil Jeruzalém ⌈ od jednoho konce k druhému⌉ -- kromě svého hříchu, že svedl Judu k páchání toho, co je zlé v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Ostatní Menašeho činy a všechny věci, které činil, i jeho hřích, kterým hřešil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Menaše ulehl se svými otci a byl pohřben v zahradě svého domu, v zahradě Uzově. Po něm se stal králem jeho syn Amón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amónovi bylo dvacet dva let, když se stal králem, a kraloval v Jeruzalémě dva roky. Jeho matka se jmenovala Mešulemet, dcera Charúsova z Jotby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Páchal to, co je zlé v Hospodinových očích, tak jako to činil jeho otec Menaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, '⌈Chodil po všech cestách, po kterých chodil jeho otec,⌉ a sloužil bůžkům, kterým sloužil jeho otec, a klaněl se jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Opustili Hospodina, ⌈Boha svých otců,⌉ a nechodili po Hospodinově cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Amónovi otroci se proti němu spikli a usmrtili krále v jeho domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Avšak lid země ubil všechny, kdo se proti králi Amónovi spikli. Lid země ustanovil králem místo něj jeho syna Jóšijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Ostatní Amónovy činy, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Pohřbili ho v jeho hrobě na Uzově zahradě. Po něm se stal králem jeho syn Jóšijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Jóšijášovi bylo osm let, když se stal králem, a kraloval v Jeruzalémě třicet jedna let. Jeho matka se jmenovala Jedída, dcera Adajášova z Boskatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Činil to, co je správné v Hospodinových očích, a chodil po všech cestách svého otce Davida, neodvrátil se ⌈napravo ani nalevo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'I stalo se v osmnáctém roce vlády krále Jóšijáše, že poslal král písaře Šáfana, syna Asaljáše, syna Mešulámova, do Hospodinova domu se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Zajdi k veleknězi Chilkijášovi, ať zváží stříbro přinesené do Hospodinova domu, jež sebrali strážci prahu od lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Ať ho dají do rukou dílovedoucích, ustanovených nad Hospodinovým domem, a ti ať ho dají těm, kdo dělají práci na Hospodinově domě, na opravu poškození domu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'tesařům, stavitelům, zedníkům a na nákup dřeva a tesaných kamenů k opravě domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Ale ať se jim nepočítá stříbro, které bylo vydáno do jejich rukou, protože jednají poctivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Velekněz Chilkijáš řekl písaři Šáfanovi: Našel jsem v Hospodinově domě knihu zákona. Chilkijáš dal knihu Šáfanovi a ten v ní četl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Písař Šáfan přišel ke králi a odpověděl králi slovy: Tvoji otroci roztavili stříbro, které se našlo v domě, a vydali ho do rukou dílovedoucích, ustanovených nad Hospodinovým domem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Pak písař Šáfan králi oznámil: Kněz Chilkijáš mi dal knihu. Nato z ní Šáfan před králem četl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'I stalo se, když král uslyšel slova knihy zákona, že ⌈roztrhl své roucho.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Potom král knězi Chilkijášovi, Achíkamovi, synu Šáfanovu, Akbórovi, synu Míkajášovu, písaři Šáfanovi a královskému otroku Asajáši přikázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Jděte a dotažte se Hospodina za mě, za lid a za celého Judu ohledně slov této nalezené knihy. Vždyť velká je Hospodinova zloba, která plane proti nám, protože naši otcové neposlouchali slova této knihy a ne plnili vše, co je v ní zapsáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Kněz Chilkijáš, Achíkam, Akbór, Šáfan a Asajáš tedy šli k prorokyni Chuldě, manželce strážce rouch Šalúma, syna Tikvy, syna Charchasova; bydlela v Jeruzalémě v Mišne. Promluvili s ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Ona jim řekla: Toto praví Hospodin, Bůh Izraele: Řekněte muži, který vás ke mně poslal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Toto praví Hospodin: Hle, přivedu na toto místo zlo a na jeho obyvatele všechna ⌈slova knihy,⌉ kterou četl judský král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Protože mě opustili a pálili oběti jiným bohům, aby mě provokovali k hněvu ⌈každým dílem⌉ svých rukou, má zloba plane proti tomuto místu a neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Judskému králi, který vás poslal dotázat se Hospodina, tomu řekněte toto: Takto praví Hospodin, Bůh Izraele, o věcech, které jsi slyšel:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Protože tvé srdce změklo a pokořil ses před Hospodinem, když jsi slyšel, co jsem promluvil proti tomuto místu a proti jeho obyvatelům -- že se stane hroznou pustinou a kletbou -- roztrhl jsi své roucho a plakal jsi přede mnou, také já jsem slyšel, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Proto hle, připojím tě ke tvým otcům a odebereš se do svého hrobu v pokoji. Tvé oči neuvidí nic z toho zla, které přivedu na toto místo. ⌈Přinesli tedy králi tuto zprávu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Král ⌈dal k sobě shromáždit⌉ všechny judské a jeruzalémské starší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Pak vystoupil král do Hospodinova domu a s ním všichni Judejci a všichni obyvatelé Jeruzaléma, kněží, proroci a všechen lid od nejmenšího do největšího; a četl jim všechna slova knihy smlouvy nalezené v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Král stál u sloupu a uzavřel před Hospodinem smlouvu, že půjde za Hospodinem, bude celým srdcem a celou duší zachovávat jeho příkazy, svědectví a ustanovení a naplňovat slova této smlouvy zapsaná v této knize. A všechen lid ⌈vstoupil do smlouvy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Nato král přikázal veleknězi Chilkijášovi, kněžím druhým v pořadí a strážcům prahu, aby vynesli z Hospodinova chrámu všechny předměty učiněné pro Baala, Ašeru a pro celý nebeský zástup. Spálil je venku za Jeruzalémem na polích Kidrónu a jejich prach odnesl do Bét–elu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Odstranil žrece, které ustanovili judští králové, ⌈aby pálili⌉ oběti na návrších v judských městech a v okolí Jeruzaléma, a ty, kdo obětovali Baalovi, slunci, měsíci, ⌈hvězdám zvěrokruhu⌉ a celému nebeskému zástupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Vynesl Ašeru z Hospodinova domu ven za Jeruzalém do údolí Kidrónu, spálil ji v údolí Kidrónu, rozdrtil na prach a její prach hodil na hroby ⌈obyčejných lidí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Strhl také domy chrámových smilníků, které byly v Hospodinově domě, kde ženy tkaly stany pro Ašeru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Přivedl všechny kněze z judských měst a znečistil návrší, kde kněží pálili oběť, od Geby až po Beer–šebu. Strhl též návrší bran u vchodu do brány velitele města Jóšuy, nalevo, když se vchází do městské brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Kněží návrší ovšem nevystupovali k Hospodinovu oltáři v Jeruzalémě, ale jedli nekvašené chleby spolu se svými bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Tófet, který je v údolí Hinómova syna, také znečistil, aby nikdo neprováděl svého syna či dceru ohněm Molekovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Odstranil též koně, které judští králové zasvětili slunci, od vchodu do Hospodinova domu, u komory dvorního úředníka Netan–meleka, která byla v parbaru; vozy zasvěcené slunci spálil ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Také oltáře, které byly na střeše Achazovy horní místnosti a jež udělali judští králové, i oltáře, které udělal Menaše na obou nádvořích Hospodinova domu, král strhl, rozdrtil je a jejich prach hodil do údolí Kidrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Také návrší, která byla naproti Jeruzalému na jih od ⌈Hory zkázy⌉ a jež postavil izraelský král Šalomoun pro Aštoretu, ohavnou modlu Sidóňanů, pro Kemóše, ohavnou modlu Moábců, a pro Milkóma, ohavnou modlu synů Amónových, král znečistil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Roztřískal posvátné sloupy, pokácel posvátné kůly a jejich místo naplnil lidskými kostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Také oltář, který byl v Bét–elu, návrší, které udělal Jarobeám, syn Nebatův, jenž svedl Izrael k hříchu, také tento oltář i návrší strhl; spálil návrší a rozdrtil na prach, i posvátný kůl spálil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Když se Jóšijáš ohlédl, uviděl hroby, které byly na té hoře; ⌈dal vzít⌉ kosti z hrobů, spálil je na oltáři a znečistil ho podle Hospodinova slova, které volal muž Boží, který vyhlásil tyto události.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Zeptal se: Co je to za náhrobek, který vidím? Mužové města mu odpověděli: To je hrob muže Božího, který přišel z Judska a vyhlásil tyto události, které jsi s bételským oltářem vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Řekl: Nechte ho být. Nikdo ať nehýbe s jeho kostmi. Tak zachránili jeho kosti i kosti proroka, který přišel ze Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Také všechny svatyně návrší, které byly v samařských městech a jež udělali izraelští králové, aby provokovali Hospodina k hněvu, Jóšijáš odstranil. Naložil s nimi stejně, jako to učinil v Bét–elu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Obětoval na oltářích všechny kněze návrší, kteří tam byli, spálil na nich lidské kosti a vrátil se do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Král přikázal všemu lidu: Slavte Velikonoce Hospodinu, svému Bohu, jak je zapsáno v této knize smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Takové Velikonoce se totiž neslavily ode dnů soudců, kteří soudili Izrael, a ani po všechny dny králů izraelských i králů judských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Ale v osmnáctém roce vlády krále Jóšijáše se slavily takové Velikonoce Hospodinu v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Také ty, kdo vyvolávají duchy zemřelých, a věštce, domácí bůžky, bůžky a všechny ohavné modly, které byly vidět v judské zemi a v Jeruzalémě, Jóšijáš vyhladil, aby naplnil slova zákona, zapsaná v knize, kterou našel kněz Chilkijáš v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Před ním nebyl takový král, který by se obrátil k Hospodinu celým svým srdcem, celou svou duší a celou svou silou zcela podle Mojžíšova zákona, a ani po něm nepovstal jemu podobný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Avšak Hospodin se neodvrátil od svého velkého planoucího hněvu, kterým vzplál proti Judovi za všechny provokace, kterými ho provokoval ke hněvu Menaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Hospodin řekl: Také Judu odstraním od své tváře, jako jsem odstranil Izrael, a zavrhnu toto město, které jsem vyvolil, Jeruzalém, i dům, o němž jsem řekl: Tam bude přebývat mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Ostatní Jóšijášovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Za jeho dnů vytáhl faraon Néko, egyptský král, ke králi asyrskému k řece Eufratu. Král Jóšijáš vytáhl proti němu, ale Néko ho usmrtil u Megida, jakmile ho uviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Jeho otroci ho dovezli ve voze mrtvého od Megida. Přivezli ho do Jeruzaléma a pohřbili ho v jeho hrobě. Lid země vzal Jóachaza, syna Jóšijášova, pomazali ho a ustanovili ho králem místo jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Jóachazovi bylo dvacet tři let, když se stal králem, a kraloval v Jeruzalémě tři měsíce. Jeho matka se jmenovala Chamútal, dcera Jeremjáše z Libny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Páchal to, co je zlé v Hospodinových očích, stejně jako to činili jeho otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Faraon Néko ho spoutal v Rible v zemi Chamátu, aby ne mohl kralovat v Jeruzalémě, a uložil zemi pokutu sto talentů stříbra a talent zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Faraon Néko ustanovil králem Eljakíma, syna Jóšijášova, místo jeho otce Jóšijáše. Jeho jméno změnil na Jójakím. Jóachaza vzal, odvedl ho do Egypta a tam zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Jójakím dal faraonovi stříbro a zlato; ⌈vyměřil ovšem zemi daň, aby mohl dát stříbro podle faraonova příkazu -- od každého z lidu země vymáhal stříbro a zlato podle svého výměru, aby to mohl dát faraonovi Nékovi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jójakímovi bylo dvacet pět let, když se stal králem, a kraloval v Jeruzalémě jedenáct let. Jeho matka se jmenovala Zebúda, dcera Pedajášova z Rúmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Páchal to, co je zlé v Hospodinových očích, stejně jako to činili jeho otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Za jeho dnů přitáhl babylonský král Nebúkadnesar a Jójakím byl tři roky jeho otrokem. Pak ⌈se proti němu znovu vzbouřil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Hospodin proti němu ale poslal loupežné hordy Chaldejců, loupežné hordy Aramejců, loupežné hordy Moábců a loupežné hordy synů Amónových. Poslal je proti Judsku, aby jej hubil ⌈podle Hospodinova slova, které promluvil prostřednictvím⌉ svých otroků proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Ano, stalo se to podle Hospodinova příkazu proti Judovi, aby ho odstranil od své tváře za hříchy Menašeho, za všechno, co páchal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'i za nevinnou krev, kterou prolil; naplnil Jeruzalém nevinnou krví a Hospodin to nechtěl odpustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Ostatní Jójakímovy činy a všechny věci, které činil, jsou zapsány v knize Letopisů judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Jójakím ulehl se svými otci a po něm se stal králem jeho syn Jójakín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Egyptský král již nikdy netáhl ze své země, protože babylonský král zabral od egyptského potoka až k řece Eufratu všechno, co patřilo egyptskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Jójakínovi bylo osmnáct let, když se stal králem, a kraloval v Jeruzalémě tři měsíce. Jeho matka se jmenovala Nechušta, dcera Elnátanova z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Páchal to, co je zlé v Hospodinových očích, stejně jako to činil jeho otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'V té době přitáhli otroci babylonského krále Nebúkadnesara k Jeruzalému a město bylo obleženo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Také babylonský král Nebúkadnesar přitáhl k městu, zatímco jeho otroci je obléhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Nato judský král Jójakín vyšel k babylonskému králi, on i jeho matka, jeho otroci, jeho knížata i jeho dvorní úředníci. Babylonský král ho zajal v osmém roce svého kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Vynesl odtamtud všechny poklady Hospodinova domu i poklady královského paláce a usekal všechny zlaté předměty, které udělal izraelský král Šalomoun v Hospodinově chrámu, tak, jak řekl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Odvedl celý Jeruzalém: Všechna knížata, všechny udatné hrdiny, deset tisíc vystěhovalců, i všechny řemeslníky a kováře; zůstal jenom chudý lid země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Odvedl do Babylona Jójakína, královu matku, královy ženy, jeho dvorní úředníky i mocnáře země; přivedl je jako vyhnance z Jeruzaléma do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Všechny bojovníky, sedm tisíc, řemeslníky a kováře, jeden tisíc, všechny hrdiny bojovníky babylonský král přivedl jako vyhnance do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Babylonský král ustanovil místo něj králem jeho strýce Matanjáše a změnil mu jméno na Sidkijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sidkijášovi bylo dvacet jedna let, když se stal králem, a kraloval v Jeruzalémě jedenáct let. Jeho matka se jmenovala Chamútal, dcera Jeremjáše z Libny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Páchal to, co je zlé v Hospodinových očích, stejně jako to činil Jójakím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Bylo to proto, že Hospodinův hněv byl proti Jeruzalému a proti Judovi, dokud je neodvrhl od své tváře. Sidkijáš se proti babylonskému králi vzbouřil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'V devátém roce jeho kralování, v desátém měsíci, desátého dne toho měsíce se stalo, že proti Jeruzalému přitáhl babylonský král Nebúkadnesar a celé jeho vojsko, utábořili se kolem něj a vystavěli proti němu ze všech stran obléhací val.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Město zůstalo v obležení až do jedenáctého roku vlády krále Sidkijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Devátého dne toho měsíce, když se ve městě rozmohl hlad a lid země neměl chléb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'hradby města byly prolomeny. Všichni bojovníci v noci vyšli bránou mezi dvěma hradbami u královské zahrady, přestože Chaldejci byli ze všech stran kolem města. Potom šli směrem k Arabě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Chaldejské vojsko pronásledovalo krále a dostihlo ho na jerišských pustinách; celé jeho vojsko se od něj rozprchlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Krále chytili a přivedli ho k babylonskému králi do Ribly. Tam nad ním vyslovili rozsudek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Sidkijášovy syny pobili před jeho očima. Sidkijášovy oči oslepil, svázal ho bronzovými okovy a přivedl ho do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'V pátém měsíci, sedmého dne toho měsíce -- to byl devatenáctý rok vlády babylonského krále Nebúkadnesara -- přišel do Jeruzaléma Nebúzaradán, velitel tělesné stráže a otrok babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Spálil Hospodinův dům i královský palác, všechny jeruzalémské domy, každý velký dům spálil ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Celé chaldejské vojsko, které bylo s velitelem tělesné stráže, strhlo hradby kolem Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Zbytek lidu, který ve městě zůstal, i přeběhlíky, kteří přeběhli k babylonskému králi, a zbytek davu velitel tělesné stráže Nebúzaradán odvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Ale některé z chudých země ponechal velitel tělesné stráže jako vinaře a rolníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Bronzové sloupy, které byly v Hospodinově domě, i podstavce a bronzové moře, které bylo v Hospodinově domě, Chaldejci roztřískali a bronz z nich odnesli do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Vzali hrnce, lopaty, nůžky na knoty, kadidlové pánvičky a všechny bronzové nádoby, s nimiž konali bohoslužby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Velitel tělesné stráže vzal i pánvičky na uhlíky a misky; co bylo ze zlata jako zlato, co bylo ze stříbra jako stříbro;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'i dva sloupy, jedno moře a podstavce, které udělal Šalomoun pro Hospodinův dům. Bronz ze všech těchto předmětů se nedal ani zvážit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Jeden sloup byl osmnáct loket vysoký a na něm byla bronzová hlavice; hlavice byla vysoká tři lokte. Kolem hlavice bylo mřížování a granátová jablka; to všechno bylo z bronzu. Takový byl i druhý sloup s mřížováním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Velitel tělesné stráže vzal vrchního kněze Serajáše, druhého kněze Sefanjáše a tři strážce prahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Z města vzal také jednoho dvorního úředníka, který byl dohlížitelem nad bojovníky, pět mužů z těch, kteří ⌈bývali v přítomnosti krále,⌉ kteří se nacházeli ve městě, i písaře velitele armády, jenž povolával do vojenské služby lid země, a šedesát mužů z lidu země, kteří se nacházeli ve městě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Velitel tělesné stráže Nebúzaradán je vzal a předvedl je babylonskému králi do Ribly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Babylonský král je pobil; usmrtil je v Rible v zemi Chamátu. Tak byl Juda odveden ze své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Nad lidem, který zůstal v judské zemi, který babylonský král Nebúkadnesar ponechal, ustanovil Gedaljáše, syna Achíkama, syna Šáfanova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Když všichni velitelé vojsk i jejich muži uslyšeli, že babylonský král ustanovil za správce Gedaljáše, přišli ke Gedaljášovi do Mispy, totiž Jišmael, syn Netanjášův, Jóchanan, syn Karéachův, Serajáš, syn Tanchumeta Netófského, Jaazanjáš, syn Maakaťanův, oni i jejich muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Gedaljáš jim a jejich mužům přísahal a řekl jim: Nebojte se ⌈chaldejských otroků.⌉ Pobývejte v zemi, služte babylonskému králi a povede se vám dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'V sedmém měsíci se stalo, že přišel Jišmael, syn Netanjáše, syna Elíšamova z královského potomstva, a s ním deset mužů, a Gedaljáše i Judejce a Chaldejce, kteří byli s ním v Mispě, ubili k smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Nato všechen lid od nejmenšího do největšího i velitelé vojsk povstali a odešli do Egypta, protože se báli Chaldejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'V třicátém sedmém roce vyhnanství judského krále Jójakína, ve dvanáctém měsíci, dvacátého sedmého dne toho měsíce se stalo, že babylonský král Evíl–merodak v roce, kdy se stal králem, omilostnil judského krále Jójakína a propustil ho z věznice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Mluvil s ním laskavě a jeho trůn ustanovil nad trůny králů, kteří s ním byli v Babyloně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Jójákín svlékl své vězeňské šaty a jídal po všechny dny svého života stále v jeho přítomnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Jeho zaopatření, stálé zaopatření, mu bylo poskytováno králem, každodenní podíl po všechny dny jeho života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Šét, Enóš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kénan, Mahalalel, Jered,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Metúšelach, Lámech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noe, Šém, Chám a Jefet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Synové Jefetovi: Gomer, Magóg, Mádaj, Jávan, Túbal, Mešek a Tíras.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Synové Gomerovi: Aškenaz, Rífat a Togarma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Synové Jávanovi: Elíša, Taršíš, Kitejci a Dódanci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Synové Chámovi: Kúš, Misrajim, Pút a Kenaan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Synové Kúšovi: Seba, Chavíla, Sabta, Raema a Sabteka. Synové Raemovi: Šeba a Dedán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kúš zplodil Nimroda. Ten se stal prvním hrdinou na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Misrajim zplodil Lúďany, Anámce, Lehábany, Naftúchany,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Patrúsany, Kaslúchany (z nich vzešli Pelištejci) a Kaftórce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kenaan zplodil Sidóna, svého prvorozeného, a Chéta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Jebúsejce, Emorejce, Girgašejce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Chivejce, Arkejce, Sínejce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvádejce, Semárejce a Chamátejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Synové Šémovi: Élam, Ašúr, Arpakšád, Lúd, Aram, Ús, Chúl, Geter a Mešek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arpakšád zplodil Šelacha, Šelach zplodil Hebera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Heberovi se narodili dva synové: První se jmenoval Peleg, (protože v jeho dnech byla rozdělena země), a jeho bratr se jmenoval Joktán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Joktán zplodil Almódada, Šelefa, Chasarmáveta, Jeracha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoráma, Úzala, Diklu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ébala, Abímaela, Šebu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofíra, Chavílu a Jóbaba. Ti všichni jsou synové Joktánovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Šém, Arpakšád, Šelach,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Heber, Peleg, Reú,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serúg, Náchor, Terach,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, to je Abraham.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Synové Abrahamovi: Izák a Izmael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Toto je jejich rodopis: Izmaelův prvorozený Nebajót, Kédar, Adbeel, Mibsám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Mišma, Dúma, Masa, Chadad, Téma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetúr, Náfiš a Kedma. Toto jsou synové Izmaelovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Synové Ketúry, Abrahamovy konkubíny: Porodila Zimrána, Jokšána, Medána, Midjána, Jišbaka a Šúacha. Synové Jokšánovi: Šeba a Dedán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Synové Midjánovi: Éfa, Éfer, Chanók, Abída a Eldáa. Ti všichni jsou synové Ketúry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham zplodil Izáka. Synové Izákovi: Ezau a Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Synové Ezauovi: Elífaz, Reúel, Jeúš, Jaelam a Kórach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Synové Elífazovi: Téman, Ómar, Sefí, Gátam, Kenaz, Timna a Amálek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Synové Reúelovi: Nachat, Zerach, Šama a Miza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Synové Seírovi: Lótan, Šóbal, Sibeón, Ana, Díšon, Eser a Díšan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Synové Lótanovi: Chorí a Hómam. Lótanova sestra: Timna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Synové Šóbalovi: Alján, Manachat, Ébal, Šefí a Ónam. Synové Sibeónovi: Aja a Ana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Synové Anovi: Díšon. Synové Díšonovi: Chamrán, Ešbán, Jitrán a Keran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Synové Eserovi: Bilhán, Zaavan a Jaakan. Synové Díšonovi: Ús a Aran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Toto jsou králové, kteří kralovali v edómské zemi, dříve než se kdo stal králem nad syny Izraele: Bela, syn Beórův; jeho město se jmenovalo Dinhaba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Když Bela zemřel, stal se po něm králem Jóbab, syn Zerachův, z Bosry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Když Jóbab zemřel, stal se po něm králem Chúšam z témanské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Když Chúšam zemřel, stal se po něm králem Hadad, syn Bedadův, který pobil Midjánce na moábském poli. Jeho město se jmenovalo Avít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Když Hadad zemřel, stal se po něm králem Samla z Masreky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Když Samla zemřel, stal se po něm králem Šaúl z Rechobótu na řece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Když zemřel Šaúl, stal se po něm králem Baal–chanan, syn Akbórův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Když Baal–chanan zemřel, stal se po něm králem Hadad. Jeho město se jmenovalo Paí a jeho žena se jmenovala Mehétabel, dcera Matredy, dcera Mezahabova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Pak zemřel Hadad. Edómskými náčelníky se stali náčelník Timna, náčelník Alva, náčelník Jetet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'náčelník Oholíbama, náčelník Éla, náčelník Pínon,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'náčelník Kenaz, náčelník Téman, náčelník Mibsár,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'náčelník Magdíel a náčelník Íram. To byli edómští náčelníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Toto jsou synové Izraelovi: Rúben, Šimeón, Lévi, Juda, Isachar, Zabulón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Josef, Benjamín, Neftalí, Gád a Ašer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Synové Judovi: Ér, Ónan, Šéla, tři, kteří se mu narodili z dcery Šúovy, Kenaanky. Ér, Judův prvorozený, byl v Hospodinových očích zlý a Hospodin ho usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Jeho snacha Támar mu porodila Peresa a Zeracha. Všech Judových synů bylo pět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Synové Peresovi: Chesrón a Chámul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Synové Zerachovi: Zimrí, ⌈Étan, Héman, Kalkol,⌉ Dára, celkem pět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Synové Karmího: Akár, který přivedl zkázu na Izrael, protože se zpronevěřil věrolomností při klatbě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Syn Étanův: Azarjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Synové Chesrónovi, kteří se mu narodili: Jerachmeel, Rám a Kelúbaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Rám zplodil Amínadaba, Amínadab zplodil Nachšóna, knížete synů Judových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nachšón zplodil Salmu, Salma zplodil Bóaza,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Bóaz zplodil Obéda, Obéd zplodil Jišaje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Jišaj zplodil svého prvorozeného Elíaba, druhého Abínádaba, třetího Šimeu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'čtvrtého Netanela, pátého Radaje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'šestého Osema a sedmého Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Jejich sestry byly Serúja a Abígajil. Synové Serújini: Abíšaj, Jóab, Asáel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abígajil porodila Amasu; Amasův otec byl Izmaelita Jeter.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Káleb, syn Chesrónův, zplodil děti se svojí ženou Azúbou a s Jeriótou. Toto jsou její synové: Ješer, Šóbab a Ardón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Když Azúba zemřela, Káleb si vzal Efratu. Ta mu porodila Chúra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Chúr zplodil Urího, Urí zplodil Besaleela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Potom vešel Chesrón k dceři Makíra, otce Gileádova. Vzal si ji, když mu bylo šedesát let. Porodila mu Segúba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segúb zplodil Jaíra. Tomu patřilo dvacet tři měst v gileádské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Gešúr a Aram jim však vzali Jaírovy vesnice, Kenat a jeho vesnice, šedesát měst. Všichni tito jsou synové Makíra, otce Gileádova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, '⌈Potom Chesrón v Káleb–Efratě zemřel,⌉ Chesrónova žena Abija mu porodila Ašchúra, otce Tekóova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Synové Jerachmeela, Chesrónova prvorozeného, byli: prvorozený Rám, Búna, Oren, Osem a Achijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerachmeel měl ještě další ženu jménem Atára. Ta byla matkou Ónama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Synové Ráma, Jerachmeelova prvorozeného, byli: Maas, Jamín a Eker.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Synové Ónamovi byli: Šamaj a Jáda. Synové Šamajovi: Nádab a Abíšúr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Abíšúrova žena se jmenovala Abíchajil. Porodila mu Achbána a Molída.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Synové Nádabovi: Seled a Apajim. Seled zemřel bezdětný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Synové Apajimovi: Jiší. Synové Jišího: Šešan. Synové Šešanovi: Achláj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Synové Jády, Šamajova bratra: Jeter a Jónatan. Jeter zemřel bezdětný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Synové Jónatanovi: Pelet a Záza. Toto byli synové Jerachmeelovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Šešan neměl syny, jenom dcery. Šešan měl egyptského otroka jménem Jarcha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Šešan tedy dal svou dceru svému otroku Jarchovi za ženu; porodila mu Ataje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Ataj zplodil Nátana, Nátan zplodil Zábada,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zábad zplodil Eflála, Eflál zplodil Obéda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obéd zplodil Jehúa, Jehú zplodil Azarjáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarjáš zplodil Chelese, Cheles zplodil Eleásu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleása zplodil Sismaje, Sismaj zplodil Šalúma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Šalúm zplodil Jekamjáše a Jekamjáš zplodil Elíšamu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Synové Káleba, bratra Jerachmeelova: Méša, jeho prvorozený, byl otcem Zífa; ⌈synové Maréši,⌉ otce Chebrónova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Synové Chebrónovi: Kórach, Tapúach, Rekem a Šema.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Šema zplodil Rachama, otce Jorkoámova, Rekem zplodil Šamaje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Syn Šamajův: Maón; Maón byl otcem Bét–súrovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Kálebova konkubína Éfa porodila Chárana, Mósu a Gázeza. Cháran zplodil Gázeza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Synové Johdajovi: Regem, Jótam, Géšan, Pelet, Éfa a Šaaf.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Kálebova konkubína Maaka porodila Šebera a Tirchanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Porodila také Šaafa, otce Madmanova, Ševu, otce Makbenova a otce Gibeova. Kálebova dcera byla Aksa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Toto byli synové Kálebovi. Synové Chúra, prvorozeného Efraty: Šóbal, otec Kirjat–jearímův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, otec Bét–lechemův, Cháref, otec Bét–gáderův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Synové Šóbala, otce Kirjat–jearímova, byli: Haróe, polovina Menúchoťanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Čeledi Kirjat–jearíma: Jitrejci, Pútejci, Šumatejci, Mišraejci, z nichž vzešli Soreatejci a Eštaólci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Synové Salmovi: Bét–lechem, Netófajci, Atrót–bét–jóab, polovina Manachaťanů a Sorejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Čeledi písařů, kteří bydleli v Jaebesu: Tireaťané, Šimeaťané, Súkaťané; to jsou Kénijci, pocházející z Chamáta, otce domu Rekábova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Toto jsou synové Davidovi, kteří se mu narodili v Chebrónu: Prvorozený Amnón s Achínoamou Jizreelskou, druhý Daniel s Abígajilou Karmelskou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'třetí Abšalóm, syn Maaky, dcery gešúrského krále Talmaje, čtvrtý Adónijáš, syn Chagíty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'pátý Šefatjáš s Abítalou, šestý Jitreám s jeho ženou Eglou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Těchto šest se mu narodilo v Chebrónu. Kraloval tam sedm let a šest měsíců. V Jeruzalémě kraloval třicet tři let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'A tito se mu narodili v Jeruzalémě: Šimea, Šóbab, Nátan, Šalomoun -- čtyři s Batšebou, dcerou Amíelovou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Jibchár, Elíšama, Elífelet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nógah, Nefeg, Jafía,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elíšama, Eljáda a Elífelet -- těchto devět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Tito všichni jsou synové Davidovi kromě synů konkubín. Támar byla jejich sestra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Syn Šalomounův byl Rechabeám a jeho syn Abijáš, jeho syn Ása, jeho syn Jóšafat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'jeho syn Jóram, jeho syn Achazjáš, jeho syn Jóaš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'jeho syn Amasjáš, jeho syn Azarjáš, jeho syn Jótam,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'jeho syn Achaz, jeho syn Chizkijáš, jeho syn Menaše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'jeho syn Amón, jeho syn Jóšijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Synové Jóšijášovi: Prvorozený Jóchanan, druhý Jójakím, třetí Sidkijáš, čtvrtý Šalúm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Synové Jójakímovi: Jeho syn Jekonjáš a jeho syn Sidkijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Synové Jekonjáše, vězně: Jeho syn Šealtíel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkíram, Pedajáš, Šenasar, Jekamjáš, Hóšama a Nedabjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Synové Pedajášovi: Zerubábel a Šimeí. Synové Zerubábelovi: Mešulámi a Chananjáš a jejich sestra Šelomít,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'potom Chašuba, Óhel, Berekjáš, Chasadjáš a Júšab–chesed -- těchto pět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Synové Chananjášovi: Pelatjáš a Ješajáš, synové Refajášovi, synové Arnánovi, synové Obadjášovi, synové Šekanjášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Synové Šekanjášovi: Šemajáš. Synové Šemajášovi: Chatúš, Jigál, Baríach, Nearjáš a Šafat -- těchto šest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Synové Nearjášovi: Eljóenaj, Chizkijáš a Azríkam -- tito tři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Synové Eljóenajovi: Hódavjáš, Eljašíb, Pelajáš, Akúb, Jóchanan, Delajáš a Ananí -- těchto sedm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Synové Judovi: Peres, Chesrón, Karmí, Chúr a Šóbal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reajáš, syn Šóbalův, zplodil Jachata, Jachat zplodil Achúmaje a Lahada. To jsou čeledi soreatejské.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Toto jsou synové Étama: Jizreel, Jišma a Jidbáš; jejich sestra se jmenovala Haslelponí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Penúel byl otec Gedórův a Ezer otec Chušův. Toto jsou synové Chúra, prvorozeného Efraty, otce Bét–lechemova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ašchúr, otec Tekóův, měl dvě ženy: Cheleu a Naaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naara mu porodila Achuzama, Chefera, Témního a Achaštarího. To jsou synové Naary.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Synové Cheley: Seret, Sochar a Etnán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Kós zplodil Anúba a Sóbebu a čeledě Acharchela, syna Harumova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jaebes byl váženější nežli jeho bratři. Jeho matka jej pojmenovala Jaebes se slovy: Vždyť jsem ho porodila v trápení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Ale Jaebes volal k Bohu Izraele: Požehnej mi a rozšiř mé území. Tvá ruka ať je se mnou. ⌈Učiň, ať jsem ochráněn ⌉ od zlého a nejsem trápen. A Bůh splnil to, oč žádal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Kelúb, bratr Šúchův, zplodil Mechíra; ten je otcem Eštóna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Eštón zplodil Bét–ráfu, Paséacha, Techinu, otce Ír–náchašova. To jsou mužové Réky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Synové Kenazovi: Otníel a Serajáš. Synové Otníelovi: Chatat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meónótaj zplodil Ofru, Serajáš zplodil Jóaba, otce Gé–charašímu (Údolí řemeslníků), neboť byli řemeslníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Synové Káleba, syna Jefunova: Irú, Éla a Naam. Synové Élovi: Kenaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Synové Jehalelélovi: Zíf, Zífa, Tírja a Asarel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Synové Ezrovi: Jeter, Mered, Éfer a Jalón. Otěhotněla a porodila Mirjama, Šamaje a Jišbácha, otce Eštemoova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Jeho žena Judejka porodila Jereda, otce Gedórova, Chebera, otce Sókova, a Jekutíela, otce Zanóachova. To jsou synové Bitji, dcery faraonovy, kterou si vzal Mered.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Synové ženy Hódijášovy, sestry Nachamovy: ⌈Otec Keíly Garmíťana⌉ a Eštemóa Maakaťan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Synové Šímónovi: Amnón, Rina, Ben–chanan a Tilón. Synové Jišího: Zóchet a Ben–zóchet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Synové Šély, syna Judova: Ér, otec Léka, Laeda, otec Maréši, a čeledi z dílny na mořské hedvábí v Bét–ašbeji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Jókím, mužové Kózeby, Jóaš a Saraf, kteří panovali v Moábu, a Jašubi–lechem. (⌈To jsou dávné události).⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'To byli hrnčíři, kteří bydleli v Netajímu a Gedeře. Pobývali tam u krále v jeho službě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Synové Šimeónovi: Nemúel, Jamín, Jaríb, Zerach a Šaúl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'jeho syn Šalúm, jeho syn Mibsám a jeho syn Mišma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Synové Mišmovi: Jeho syn Chamúel, jeho syn Zakúr a jeho syn Šimeí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Šimeí měl šestnáct synů a šest dcer. Jeho bratři však neměli mnoho synů. Celá jejich čeleď se nerozmnožila tak jako synové Judovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Sídlili v Beer–šebě, Móladě, Chasar–šúalu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Bilze, Esemu, Tóladu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Betúelu, Chormě, Siklagu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Bét–markabótu, Chasar–súsimu, Bét–bireji a Šaarajimu. To byla jejich města až do Davidova kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Jejich dvorce byly: Étam, Ajin, Rimón, Token a Ašan, těchto pět měst,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'a všechny jejich dvorce, které byly kolem těchto měst až k Baalu. To byla jejich sídla. ⌈Měli svoje rodokmeny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Dále Mešóbab, Jamlék a Jóša, syn Amasjášův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Jóel a Jehú, syn Jóšibjáše, syna Serajáše, syna Asíelova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljóenaj, Jaakoba, Ješochajáš, Asajáš, Adíel, Jesímiel, Benajáš');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'a Zíza, syn Šifího, syna Alóna, syna Jedajáše, syna Šimrího, syna Šemajášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Tito jmenovaní byli předáky ve svých čeledích a ⌈domy jejich otců⌉ se velice rozhojnily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Odešli ke Gedóru, až na východ údolí, aby hledali pastvu pro svá stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'A nalezli úrodnou a dobrou pastvu, zemi rozlehlou na všechny strany, poklidnou a pokojnou. Předtím tam bydleli někteří z Chámovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Tito jmenovitě zapsaní přišli ve dnech judského krále Chizkijáše, pobili jejich stany i Meúnejce, kteří se tam nacházeli, a zasvětili je zkáze, jak je tomu dodnes. Usídlili se tam místo nich, protože tam byla pastva pro jejich stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Někteří z nich, pět set mužů ze synů Šimeónových, šli do pohoří Seíru -- Pelatjáš, Nearjáš, Refajáš a Uzíel, syn Jišího, byli v jejich čele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Pobili ostatek těch, kteří vyvázli z Amálekovců, a zůstali tam až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Synové Rúbena, Izraelova prvorozeného; byl prvorozený, když však znesvětil lože svého otce, jeho prvorozenství bylo dáno synům Josefa, synům Izraelovým, a nebyl zapsán do rodokmene jako prvorozený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Ačkoliv se Juda rozmohl nad své bratry a vzešel z něho vévoda, prvorozenství dostal Josef.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Synové Rúbena, Izraelova prvorozeného: Chanók, Palú, Chesrón a Karmí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Synové Jóelovi: Jeho syn Šemajáš, jeho syn Góg, jeho syn Šimeí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'jeho syn Míka, jeho syn Reajáš, jeho syn Baal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'jeho syn Beera, kterého odvedl asyrský král Tilgat–pilneser; on byl předákem Rúbenovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Jeho bratři podle čeledí, jak byli zapsáni do rodokmenů podle svých rodů: Předák Jeíel, Zekarjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Bela, syn Azaza, syna Šemy, syna Jóelova; sídlil v Aróeru a až k Nebó a Baal–meónu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'na východě sídlil ⌈až k okraji pustiny⌉ táhnoucí se k řece Eufratu, protože jejich stáda se v gileádské zemi rozmnožila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Ve dnech Saulových vedli válku s Hagrejci, kteří padli do jejich ruky; potom sídlili v jejich stanech po celém povrchu země na východ od Gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Synové Gádovi sídlili naproti nim v bášanské zemi až po Salku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Předákem byl Jóel, druhý Šafam, potom Jaenaj a Šafat v Bášanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Jejich bratři podle domu svých otců: Michael, Mešulám, Šeba, Jóraj, Jaekán, Zía a Eber, těchto sedm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Toto jsou synové Abíchajila, syna Chúrího, syna Jaróacha, syna Gileáda, syna Michaela, syna Ješíšaje, syna Jachdóa, syna Búzova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Achí, syn Abdíela, syna Gúního, byl předákem v domě jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Sídlili v Gileádu, v Bášanu a v jeho vesnicích a na všech pastvinách Šáronu až kam sahaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Všichni byli zapsáni do rodokmene ve dnech judského krále Jótama a ve dnech izraelského krále Jarobeáma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Synové Rúbenovi, Gádovi a polovina kmene Manasesova byli bojovníci, muži, kteří nosili štít a meč, napínali luk a byli vycvičeni v boji; čtyřicet čtyři tisíc sedm set šedesát těch, kteří táhli s armádou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Vedli válku s Hagrejci, s Jetúrem, Náfišem a Nódabem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Dostalo se jim pomoci proti nim a Hagrejci i všichni, kdo byli s nimi, byli vydáni do jejich rukou, neboť volali k Bohu o pomoc v boji a on se dal pohnout jejich prosbami, protože na něj spoléhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Odvedli jejich stáda: Padesát tisíc jejich velbloudů, dvě stě padesát tisíc ovcí, dva tisíce oslů a sto tisíc lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Pobitých padlo mnoho, neboť ten boj byl od Boha. Pak tam sídlili místo nich až do vyhnanství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Potomci poloviny kmene Manasesova sídlili v zemi od Bášanu až po Baal–chermón a Senír, horu Chermón; bylo jich mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Toto jsou předáci domu jejich otců: Éfer, Jiší, Elíel, Azríel, Jeremjáš, Hódavjáš a Jachdíel, udatní hrdinové, ⌈věhlasní muži,⌉ předáci domu svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Zpronevěřili se však Bohu svých otců, smilnili s bohy národů země, které před nimi Bůh vyhladil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Bůh Izraele vzbudil ducha asyrského krále Púla a ducha asyrského krále Tilgat–pilnesera a odvedl je -- Rúbenovce, Gádovce a polovinu kmene Manasesova -- a přivedl je do Chalachu, Chabóru, Hary a k řece Gózanu, kde jsou až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, 'Synové Léviho: Geršón, Kehat a Merarí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, 'Synové Kehatovi: Amrám, Jishár, Chebrón a Uzíel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'Synové Amrámovi: Áron a Mojžíš, a Mirjam. Synové Áronovi: Nádab, Abíhú, Eleazar a Ítamar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, 'Eleazar zplodil Pinchasa, Pinchas zplodil Abíšúu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'Abíšúa zplodil Bukího, Bukí zplodil Uzího,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'Uzí zplodil Zerachjáše, Zerachjáš zplodil Merajóta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Merajót zplodil Amarjáše, Amarjáš zplodil Achítúba,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'Achítúb zplodil Sádoka, Sádok zplodil Achímaase,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'Achímaas zplodil Azarjáše, Azarjáš zplodil Jóchanana,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'Jóchanan zplodil Azarjáše (toho, který sloužil jako kněz v domě, jenž postavil Šalomoun v Jeruzalémě),');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'Azarjáš zplodil Amarjáše, Amarjáš zplodil Achítúba,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'Achítúb zplodil Sádoka, Sádok zplodil Šalúma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'Šalúm zplodil Chilkijáše, Chilkijáš zplodil Azarjáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'Azarjáš zplodil Serajáše, Serajáš zplodil Jósadaka;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'a Jósadak odešel, když Hospodin odvedl Judu a Jeruzalém do zajetí prostřednictvím Nebúkadnesara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Synové Léviho: Geršóm, Kehat a Merarí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Toto jsou jména synů Geršómových: Libní a Šimeí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Synové Kehatovi: Amrám, Jishár, Chebrón a Uzíel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Synové Merarího: Machlí a Muší. Toto jsou čeledi Léviho podle svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Geršómovi: Jeho syn Libní, jeho syn Jachat, jeho syn Zima,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'jeho syn Jóach, jeho syn Idó, jeho syn Zerach a jeho syn Jeotraj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Synové Kehatovi: Jeho syn Amínadab, jeho syn Kórach, jeho syn Asír,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'jeho syn Elkána, jeho syn Ebjásaf, jeho syn Asír,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'jeho syn Tachat, jeho syn Uríel, jeho syn Uzijáš a jeho syn Šaúl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Synové Elkánovi: Amasaj a Achímót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, '⌈Jeho syn Elkána,⌉ jeho syn Sófaj, jeho syn Nachat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'jeho syn Elíab, jeho syn Jerochám a jeho syn Elkána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Synové Samuelovi: Prvorozený Jóel ⌈a druhý⌉ Abijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Synové Merarího: Machlí, jeho syn Libní, jeho syn Šimeí, jeho syn Uza,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'jeho syn Šimea, jeho syn Chagijáš a jeho syn Asajáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'A toto jsou ti, které ustanovil David nad ⌈pěveckými družinami⌉ v Hospodinově domě ⌈od doby, kdy truhla získala místo odpočinku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Sloužili písněmi před příbytkem stanu setkávání až do doby, kdy Šalomoun postavil v Jeruzalémě Hospodinův dům; sloužili podle nařízení o jejich službě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Toto jsou ti, kteří sloužili, a jejich synové: Ze synů Kehatových: Zpěvák Héman, syn Jóela, syna Samuela,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'syna Elkány, syna Jerocháma, syna Elíela, syna Tóacha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'syna Súfa, syna Elkány, syna Machata, syna Amasaje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'syna Elkány, syna Jóela, syna Azarjáše, syna Sefanjáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'syna Tachata, syna Asíra, syna Ebjásafa, syna Kóracha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'syna Jishára, syna Kehata, syna Léviho, syna Izraelova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'A jeho bratr Asaf, stojící po jeho pravici: Asaf, syn Berekjáše, syna Šimey,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'syna Michaela, syna Baasejáše, syna Malkijáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'syna Etního, syna Zeracha, syna Adajáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'syna Étana, syna Zimy, syna Šimeího,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'syna Jachata, syna Geršóma, syna Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'A synové Merarího, jejich bratři, po levici: Étan, syn Kíšího, syna Abdího, syna Malúka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'syna Chašabjáše, syna Amasjáše, syna Chilkijáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'syna Amsího, syna Baního, syna Šemera,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'syna Machlího, syna Mušího, syna Merarího, syna Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Jejich bratři lévité byli ustanoveni pro všechnu službu v příbytku ⌈Božího domu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Áron a jeho synové pálili oběti na ⌈oltáři pro zápalné oběti⌉ a na ⌈oltáři pro kadidlo,⌉ ⌈při veškeré⌉ službě nejsvětějšího místa, aby získali smíření pro Izrael, tak jak přikázal Mojžíš, otrok Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Toto jsou synové Áronovi: Jeho syn Eleazar, jeho syn Pinchas, jeho syn Abíšúa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'jeho syn Bukí, jeho syn Uzí, jeho syn Zerachjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'jeho syn Merajót, jeho syn Amarjáš, jeho syn Achítúb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'jeho syn Sádok a jeho syn Achímaas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'A toto jsou jejich sídla podle jejich hradišť na jejich území: Synům Áronovým z čeledi Kehatovců -- protože jim padl los;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'dali jim Chebrón v judské zemi a jeho okolní pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Pole toho města a jeho dvorce však dali Kálebovi, synovi Jefunovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Synům Áronovým dali útočištná města Chebrón, Libnu a její pastviny, Jatir, Eštemóu a její pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Chílez a jeho pastviny, Debír a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Ašan a jeho pastviny, Bét–šemeš a jeho pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Z pokolení Benjamínova: Gebu a její pastviny, Alemeta a jeho pastviny, Anatót a jeho pastviny. Všech jejich měst bylo třináct podle jejich čeledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Zbývajícím synům Kehatovým z čeledi toho pokolení bylo losem přiděleno z poloviny pokolení Manasesova deset měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Synům Geršómovým podle jejich čeledí bylo přiděleno z pokolení Isacharova, z pokolení Ašerova, z pokolení Neftalího a z pokolení Manasesova v Bášanu třináct měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Synům Merarího pro jejich čeledi bylo losem přiděleno z pokolení Rúbenova, z pokolení Gádova a z pokolení Zabulónova dvanáct měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Synové Izraelovi přidělili Lévijcům města a jejich pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Přidělili losem z pokolení synů Judových, z pokolení synů Šimeónových a z pokolení synů Benjamínových tato města, která jsou vyjmenována.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Některým z čeledí synů Kehatových připadla města jejich území z pokolení Efrajimova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Dali jim útočištná města Šekem a jeho pastviny v Efrajimském pohoří, Gezer a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jokmeám a jeho pastviny, Bét–chorón a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Ajalón a jeho pastviny, Gat–rimón a jeho pastviny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'a z poloviny pokolení Manasesova: Anér a jeho pastviny a Bileám a jeho pastviny pro zbývající čeledi synů Kehatových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Synům Geršómovým -- z čeledi poloviny pokolení Manasesova: Gólan v Bášanu a jeho pastviny a Aštarót a jeho pastviny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'z pokolení Isacharova: Kedeš a jeho pastviny, Daberat a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Rámot a jeho pastviny a Aném a jeho pastviny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'z pokolení Ašerova: Mášal a jeho pastviny, Abdón a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Chukók a jeho pastviny a Rechób a jeho pastviny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'z pokolení Neftalího: Kedeš v Galileji a jeho pastviny, Chamón a jeho pastviny a Kirjatajim a jeho pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Zbývajícím synům Merarího -- z pokolení Zabulónova: Rimónó a jeho pastviny a Tábor a jeho pastviny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'na druhé straně Jordánu u Jericha, na východ od Jordánu, z pokolení Rúbenova: Beser v pustině a jeho pastviny, Jahas a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Kedemót a jeho pastviny a Méfaat a jeho pastviny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'z pokolení Gádova: Rámot v Gileádu a jeho pastviny, Machanajim a jeho pastviny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Chešbón a jeho pastviny a Jaezer a jeho pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Synové Isacharovi: Tóla, Púa, Jašúb a Šimrón, tito čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Synové Tólovi: Uzí, Refajáš, Jeríel, Jachmaj, Jibsám a Samuel, předáci domu svých otců patřícího Tólovi, udatní hrdinové podle svých rodů. Jejich počet ve dnech Davidových byl dvacet dva tisíc šest set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Synové Uzího: Jizrachjáš. Synové Jizrachjášovi: Michael, Obadjáš, Jóel a Jišijáš, těchto pět, všichni předáci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'K nim patřilo podle jejich rodů, podle domu jejich otců třicet šest tisíc mužů pro bojeschopné vojenské oddíly, protože měli mnoho žen a synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Jeho bratrů ze všech Isacharových čeledí, udatných hrdinů, bylo osmdesát sedm tisíc; všichni byli zapsáni do svých rodokmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Synové Benjamínovi: Bela, Beker a Jedíael, tito tři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Synové Belovi: Esbón, Uzí, Uzíel, Jerímót a Írí, těchto pět, předáci domu otců, udatní hrdinové; do jejich rodokmenů jich bylo zapsáno dvacet dva tisíc třicet čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Synové Bekerovi: Zemíra, Jóaš, Elíezer, Eljóenaj, Omrí, Jeremót, Abijáš, Anatót a Alemet; tito všichni jsou synové Bekerovi;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'byli zapsáni do rodokmenů podle svých rodů, předáci domu svých otců, udatní hrdinové -- dvacet tisíc dvě stě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Synové Jedíaelovi: Bilhán. Synové Bilhánovi: Jeúš, Benjamín, Ehúd, Kenaan, Zétan, Taršíš a Achíšachar;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'tito všichni jsou synové Jedíaelovi, předáci rodů, udatní hrdinové -- sedmnáct tisíc dvě stě těch, kteří táhli s armádou do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Šupím a Chupím byli synové Írovi, Chuším -- synové Achérovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Synové Neftalího: Jachasíel, Gúní, Jeser a Šalúm, synové Bilhy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Synové Manasesovi: Asríel, kterého porodila jeho konkubína, Aramejka; porodila též Makíra, otce Gileádova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Makír vzal ženu pro Chupíma a Šupíma; jeho sestra se jmenovala Maaka. Druhý se jmenoval Selofchad. Selofchad měl jenom dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Makírova žena Maaka porodila syna a dala mu jméno Pereš. Jeho bratr se jmenoval Šereš, jeho synové Úlam a Rekem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Synové Úlamovi: Bedán. To jsou synové Gileáda, syna Makíra, syna Manasesova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Jeho sestra Moleket porodila Íšhóda, Abíezera a Machlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Synové Šemídovi byli: Achján, Šekem, Likchí a Aníam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Synové Efrajimovi: Šútelach, jeho syn Bered, jeho syn Tachat, jeho syn Eleada, jeho syn Tachat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'jeho syn Zábad, jeho syn Šútelach, Ezer a Elead; zabili je však mužové Gatu zrození v té zemi, protože přišli, aby pobrali jejich stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Jejich otec Efrajim truchlil po mnoho dní a jeho bratři přišli, aby ho potěšili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Pak vešel ke své ženě, ta otěhotněla a porodila syna. Dal mu jméno Bería, protože ⌈se v jeho domě stalo neštěstí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Jeho dcerou byla Šeera; ta postavila Bét–chorón Dolní a Horní a Uzen–šeeru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Dále jeho syn Refach a Rešef, jeho syn Telach, jeho syn Tachan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'jeho syn Laedán, jeho syn Amíhud, jeho syn Elíšama,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'jeho syn Nún a jeho syn Jozue.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Jejich vlastnictví a jejich sídla: Bét–el a jeho vesnice, na východě Naarán, na západě Gezer a jeho vesnice, Šekem a jeho vesnice až k Aji a jeho vesnicím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'vedle území synů Manasesových Bét–šeán a jeho vesnice, Taanak a jeho vesnice, Megido a jeho vesnice a Dór a jeho vesnice. V těchto sídlili synové Josefa, syna Izraelova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Synové Ašerovi: Jimna, Jišva, Jišví, Bería a jejich sestra Serach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Synové Beríovi: Cheber a Malkíel; on je otec Birzavitův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Cheber zplodil Jafleta, Šómera, Chótama a jejich sestru Šúu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Synové Jafletovi: Pásak, Bimhál a Ašvát; to jsou synové Jafletovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Synové Šemerovi: Achí, Rohga, Jechuba a Aram.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Syn jeho bratra Helema: Sófach, Jimna, Šeleš a Ámal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Synové Sófachovi: Súach, Charnefer, Šúal, Berí, Jimrá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Beser, Hód, Šama, Šilša, Jitrán a Beéra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Synové Jeterovi: Jefune, Pispa a Ara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Synové Ulovi: Árach, Chaníel a Risja.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Ti všichni jsou synové Ašerovi, předáci domu otců, vybraní udatní hrdinové, přední z předáků. Do rodokmenů byli zapsáni ⌈podle vojenské bojeschopnosti;⌉ jejich počet byl dvacet šest tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamín zplodil svého prvorozeného Belu, druhého Ašbela, třetího Achracha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'čtvrtého Nóchu, pátého Ráfu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Bela měl syny: Adára, Géru, Abíhúda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abíšúu, Naamána, Achóacha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Géru, Šefúfana a Chúrama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Toto jsou synové Echúdovi -- byli to předáci rodů obyvatel Geby, kteří je odvedli do Manachatu --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naamán, Achijáš a Géra, který je odvedl. Zplodil Uzu a Achíchuda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Šacharajim zplodil syny na moábském poli, když poslal pryč své ženy Chušímu a Baaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Se svou ženou Chódeší zplodil Jóbaba, Sibju, Méšu, Malkáma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeúsa, Sakeju a Mirmu; toto jsou jeho synové, předáci rodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'S Chúšimou zplodil Abítúba a Elpaala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Synové Elpaalovi: Eber, Mišeám, Šemed, který postavil Óno a Lód s jeho vesnicemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'a Bería a Šema; byli to předáci rodů obyvatel Ajalónu; ti vyhnali obyvatele Gatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Achjó, Šášak, Jeremót,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadjáš, Arad, Eder,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michael, Jišpa a Jócha byli synové Beríovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Zebadjáš, Mešulám, Chizkí, Cheber,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jišmeraj, Jizliá a Jóbab byli synové Elpaalovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakím, Zikrí, Zabdí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elíenaj, Siletaj, Elíel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adajáš, Berajáš a Šimrat byli synové Šimeího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jišpán, Eber, Elíel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdón, Zikrí, Chánan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Chananjáš, Élam, Antótijáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdejáš a Penúel byli synové Šášakovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Šamšeraj, Šecharjáš, Ataljáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaarešjáš, Elijáš a Zikrí byli synové Jerochámovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Toto jsou předáci rodů podle svých rodů; tito předáci sídlili v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'V Gibeónu sídlil otec Gibeónův; jeho žena se jmenovala Maaka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Jeho prvorozený syn byl Abdón, dále Súr, Kíš, Baal, Nádab,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedór, Achjó a Zeker.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Miklót zplodil Šimeu. Také oni sídlili naproti svým bratrům v Jeruzalémě, se svými bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Nér zplodil Kíše, Kíš zplodil Saula, Saul zplodil Jónatana, Malkíšúu, Abínádaba a Ešbaala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Syn Jónatanův: Meríb–baal; Meríb–baal zplodil Míku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Synové Míkovi: Pítón, Melek, Taréa a Achaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Achaz zplodil Jójadu, Jójada zplodil Alemeta, Azmáveta a Zimrího. Zimrí zplodil Mósu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Mósa zplodil Bineu; jeho syn byl Ráfa, jeho syn Eleása, jeho syn Ásel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Ásel měl šest synů. Toto jsou jejich jména: Azríkam, Bokrú, Jišmael, Šearjáš, Obadjáš a Chánan. Ti všichni byli synové Áselovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Synové jeho bratra Ešeka: Jeho prvorozený Úlam, druhý Jeúš a třetí Elífelet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Synové Úlamovi byli udatní hrdinové, lukostřelci. Měli mnoho synů a vnuků, celkem sto padesát. Ti všichni byli ze synů Benjamínových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Všichni Izraelci byli zapsáni do rodokmenů. Ano, jsou zapsáni v Knize ⌈izraelských králů. Judejci byli odvedeni do Babylona pro svou věrolomnost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'První, kdo se znovu usídlili na svém vlastnictví, ve svých městech, byli Izraelci, kněží, lévité a chrámoví nevolníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'V Jeruzalémě sídlili někteří ze synů Judových, ze synů Benjamínových, ze synů Efrajimových a Manasesových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Útaj, syna Amíhuda, syna Omrího, syna Imrího, syna Baního ze synů Peresa, syna Judova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Ze Šíloanů prvorozený Asajáš a jeho synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Ze synů Zerachových Jeúel a jeho bratři, celkem šest set devadesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Ze synů Benjamínových Salú, syn Mešuláma, syna Hódavjáše, syna Hasenuova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'a Jibnejáš, syn Jerochámův, a Éla, syn Uzího, syna Mikrího, a Mešulám, syn Šefatjáše, syna Reúela, syna Jibnijášova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'a jejich bratři podle svých rodů, celkem devět set padesát šest. Ti všichni byli předáci rodů podle domu svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Z kněží: Jedajáš, Jójaríb, Jakín,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azarjáš, syn Chilkijáše, syna Mešuláma, syna Sádoka, syna Merajóta, syna Achítúba, představený Božího domu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Adajáš, syn Jerocháma, syna Pašchúra, syna Malkijáše, Maasaj, syn Adíela, syna Jachzéry, syna Mešuláma, syna Mešilemíta, syna Imerova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'a jejich bratři, předáci domu svých otců, celkem tisíc sedm set šedesát, udatní hrdinové pro dílo služby Božího domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Z lévitů: Šemajáš, syn Chašúba, syna Azríkama, syna Chašabjáše, ze synů Merarího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bakbakar, Chereš a Gálal, Matanjáš, syn Míky, syna Zikrího, syna Asafova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadjáš, syn Šemajáše, syna Gálala, syna Jedútúnova, a Berekjáš, syn Ásy, syna Elkánova, který sídlil v netófatských dvorcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Vrátní: Šalúm, Akúb, Talmón, Achíman a jejich bratři; Šalúm byl předákem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'a je až doposud v královské bráně na východě. Tito byli vrátní patřící k táboru synů Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Šalúm, syn Kórého, syna Ebjásafa, syna Kóracha, a jeho bratři domu jeho otce, Kórachovci byli ustanoveni nad dílem služby jako strážci prahů stanu; jejich otcové byli nad Hospodinovým táborem jako strážci vchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Předtím byl vévodou nad nimi Pinchas, syn Eleazarův; Hospodin byl s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zekarjáš, syn Mešelemjášův, byl vrátným u vchodu do stanu setkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Všech vybraných za vrátné prahů bylo dvě stě dvanáct. Byli zapsáni do rodokmenů ve svých dvorcích. Tyto určil David a vidoucí Samuel pro jejich poctivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Oni a jejich synové byli ustanoveni nad branami Hospodinova domu, stanového domu, jako stráž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Vrátní byli na čtyřech stranách: na východě, na západě, na severu a na jihu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Jejich bratři sídlící ve svých dvorcích měli ⌈čas od času⌉ přicházet na sedm dní, aby byli s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Protože byli poctiví, čtyři hlavní vrátní, lévité, byli ustanoveni nad komorami a nad pokladnicemi Božího domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Zůstávali přes noc v okolí Božího domu, neboť ⌈jim byla svěřena ⌉ stráž a ráno co ráno odemykali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Někteří z nich byli nad boho služebnými předměty -- podle počtu je přinášeli a podle počtu je odnášeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Někteří z nich byli pověřeni nad předměty a nad všemi posvátnými nádobami, nad moukou, vínem, olejem, kadidlem a balzámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Někteří ze synů kněží připravovali masti pro balzámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Matitjáš z lévitů, prvorozený Kórachovce Šalúma, byl stále nad ⌈pečením placek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Někteří ze synů Kehatových, z jejich bratrů, byli sobotu co sobotu nad přípravou předkladných chlebů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Toto jsou zpěváci, předáci lévijských rodů; zůstávali v síních, osvobozeni od jiné služby, protože ve dne v noci na nich spočívala služba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Toto jsou předáci lévijských rodů podle svých rodů. Tito předáci sídlili v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'V Gibeónu sídlil Jeíel, otec Gibeónův; jeho žena se jmenovala Maaka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Jeho prvorozený syn byl Abdón, dále Súr, Kíš, Baal, Nér, Nádab,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedór, Achjó, Zekarjáš a Miklót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Miklót zplodil Šimeama. Také oni sídlili naproti svým bratrům v Jeruzalémě, se svými bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Nér zplodil Kíše, Kíš zplodil Saula, Saul zplodil Jónatana, Malkíšúu, Abínádaba a Ešbaala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Jónatanův syn byl Meríb–baal; Merí–baal zplodil Míku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Synové Míkovi: Pítón, Melek, Tachréa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Achaz zplodil ⌈Jaeru, Jaera⌉ zplodil Alemeta, Azmáveta a Zimrího. Zimrí zplodil Mósu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Mósa zplodil Bineu; jeho syn byl Refajáš, jeho syn Eleása, jeho syn Ásel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Ásel měl šest synů. Toto jsou jejich jména: Azríkam, Bokrú, Jišmael, Šearjáš, Obadjáš a Chánan. Toto byli synové Áselovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Pelištejci bojovali proti Izraeli. Izraelci před Pelištejci utíkali a padali pobiti v pohoří Gilbóa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Pelištejci stíhali Saula a jeho syny. Pak zabili Pelištejci Jónatana, Abínádaba a Malkíšúu, Saulovy syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Bitva těžce dolehla na Saula. Našli ho lukostřelci a svíjel se bolestí, ⌈protože ho postřelili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Saul řekl svému zbrojnošovi: Vytáhni svůj meč a probodni mě s ním. Jinak přijdou ti neobřezanci a budou se mi posmívat. Ale zbrojnoš nechtěl, protože se hrozně bál. Saul tedy vzal meč a padl na něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Když viděl zbrojnoš, že Saul je mrtev, také on padl na meč a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Tak zemřel Saul i jeho tři synové, ⌈všichni z jeho domu⌉ zemřeli společně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Když Izraelci, kteří byli v údolí, viděli, že utekli a že Saul i jeho synové zemřeli, opustili svá města a utekli. Pelištejci přišli a bydleli v nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Příštího dne se stalo, že přišli Pelištejci, aby rabovali pobité. Našli Saula a jeho syny padlé v pohoří Gilbóa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Svlékli ho, odnesli jeho hlavu a jeho zbroj a poslali kolovat po pelištejské zemi, aby přinášeli novinu ⌈svým modlářským zpodobeninám⌉ a lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Jeho zbroj uložili v domě svého boha a jeho lebku připevnili v Dágonově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Když se všichni obyvatelé Jábeše v Gileádu doslechli o všem, co provedli Pelištejci Saulovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'všichni bojovníci povstali, odnesli tělo Saulovo i těla jeho synů, přinesli je do Jábeše a pohřbili jejich kosti pod terebintem v Jábeši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Saul zemřel pro svou věrolomnost, když se zpronevěřil Hospodinu, Hospodinovu slovu, které nezachoval, a také se doptával ducha zemřelého, aby se dotázal na radu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'a nedotazoval se Hospodina. On ho usmrtil a přenesl království na Davida, syna Jišajova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Všichni Izraelci se shromáždili k Davidovi do Chebrónu se slovy: Hle, jsme tvá kost a tvé tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Již dávno předtím, když byl ještě králem Saul, ty jsi vodil Izrael do boje i z boje. Hospodin, můj Bůh, ti řekl: Ty budeš pást můj lid Izrael, ty budeš vévodou nad mým lidem Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Všichni izraelští starší přišli ke králi do Chebrónu a David s nimi v Chebrónu uzavřel před Hospodinem smlouvu. Pomazali Davida za krále nad Izraelem ⌈podle Hospodinova slova⌉ prostřednictvím Samuela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Pak David a celý Izrael vytáhl na Jeruzalém, to je Jebús; tam byli Jebúsejci, obyvatelé té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Obyvatelé Jebúsu řekli Davidovi: Nevstoupíš sem. Ale David dobyl pevnost Sijón, to je Město Davidovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'David řekl: Ten, kdo udeří na Jebúsejce první, stane se předákem a velitelem. První vytáhl Jóab, syn Serújin, a stal se předákem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'A David se usadil v pevnosti, proto se nazývala Město Davidovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Postavil město všude kolem, od Miló na všechny strany. Zbytek města obnovil Jóab.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'David se stále rozmáhal a Hospodin zástupů byl s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Toto jsou předáci Davidových hrdinů, kteří ⌈ho podporovali⌉ v jeho kralování spolu s celým Izraelem, aby ho ustanovili králem podle Hospodinova slova o Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Toto je výčet Davidových hrdinů: Jášobeám, syn Chachmóního, vůdce kapitánů, který zamával svým kopím proti třem stům, jež naráz pobil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Po něm byl Eleazar, syn Dóda Achóchijského, který byl mezi těmi třemi hrdiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Byl s Davidem v Pas–damímu, když se tam Pelištejci shromáždili k boji. Byl tam díl pole plný ječmene. Lid před Pelištejci utekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Postavili se uprostřed toho pole, vysvobodili ho a Pelištejce pobili. Hospodin způsobil velkou záchranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Tři z těch třiceti vůdců sestoupili na skálu k Davidovi do adulamské jeskyně. Pelištejské vojsko tábořilo v údolí Refájců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David byl tehdy v pevnosti a pelištejská posádka byla tehdy v Betlémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'David zatoužil a řekl: Kdyby mi tak někdo dal napít vody z betlémské studny, která je u brány!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Ti tři pronikli do pelištejského tábora, načerpali vodu z betlémské studny, která je u brány, vzali ji a přinesli Davidovi. David však nechtěl pít a vylil ji Hospodinu v úlitbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Řekl: Ať je to ode mě vzdáleno, můj Bože, abych udělal něco takového. Což smím pít krev těchto mužů, ⌈ kteří šli s nasazením vlastního života?⌉ Vždyť ji přinesli s nasazením vlastního života. A nechtěl ji pít. To udělali ti tři hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abíšaj, bratr Jóabův, byl vůdcem tří. Zamával svým kopím proti třem stům, jež pobil. Proslavil se mezi těmi třemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Z těch tří byl váženější než druzí dva a stal se jejich velitelem, ale těch prvních tří nedosáhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benajáš, syn Jójadův, byl bojovník z Kabseelu, který učinil mnoho mocných činů. Ten zabil dva syny Aríele Moábského. On také přišel a v čase sněhu ubil lva uvnitř jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Zabil Egypťana, muže měřícího pět loket. Egypťan měl v ruce kopí jako tkalcovské vratidlo. On k němu přišel s holí, sebral kopí z Egypťanovy ruky a jeho vlastním kopím ho zabil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Tyto činy vykonal Benajáš, syn Jójadův, a proslavil se mezi třemi hrdiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Mezi třiceti byl nejváženější, ale těch tří nedosáhl. David ho ustanovil nad svou tělesnou stráží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Udatný hrdina: Asáel, bratr Jóabův, Elchánan, syn Dóda z Betléma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Šamót Harórský, Cheles Pelónský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Íra, syn Íkeše Tekójského, Abíezer Anatótský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibekaj Chúšatský, Ílaj Achóchijský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Mahraj Netófský, Cheled, syn Baany Netófského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ítaj, syn Ríbaje z Gibeje synů Benjamínových, Benajáš Pireatónský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Chúraj z gaašských údolí, Abíel Arbátský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmávet Bacharúmský, Eljachba Šaalbónský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'synové Hašema Gizónského, Jónatan, syn Šagéa Hararského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Achíam, syn Sakara Hararského, Elífal, syn Úrův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Chefer Mekeratský, Achijáš Pelónský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Chesró Karmelský, Naaraj, syn Ezbajův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Jóel, bratr Nátanův, Mibchár, syn Hagrího,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Selek Amónský, Nacharaj Beerótský, zbrojnoš Jóaba, syna Serújina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Íra Jitrejský, Gáreb Jitrejský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urijáš Chetejský, Zábad, syn Achlájův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adína, syn Šízy Rúbenského, vůdce Rúbenovců a nad třiceti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Chánan, syn Maakův, Jóšafat Mitnejský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzija Ašterátský, Šama a Jeíel, synové Chótama Aróerského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jedíael, syn Šimrího, a jeho bratr Jócha Tisejský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Elíel Machavímský, Jeríbaj a Jóšavjáš, synové Elnaamovi, Jitma Moábský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Elíel, Obéd a Jaasíel Mesóbajští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Tito přišli do Siklagu za Davidem, když se ještě skrýval před Saulem, synem Kíšovým; byli mezi hrdiny, kteří pomáhali v boji;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'byli ozbrojeni lukem a uměli používat pravou i levou ruku na vrhání kamenů i střílení šípů z luku; byli ze Saulových bratrů, z Benjamína:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Achíezer, vůdce, a Jóaš, synové Šemay Gibeatského, Jezíel a Pelet, synové Azmávetovi, Beraka, Jehú Anatótský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jišmajáš Gibeónský, hrdina mezi třiceti a nad třiceti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Jeremjáš, Jachazíel, Jóchanan, Józabad Gederatský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Eleúzaj, Jerímót, Bealjáš, Šemarjáš, Šefatjáš Charufský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Elkána, Jišijáš, Azarel, Jóezer, Jášobeám, Kórachovci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Jóela a Zebadjáš, synové Jerocháma z Gedóru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Z Gádovců přešli k Davidovi do pevnosti v pustině udatní hrdinové, bojeschopní vojáci, vyzbrojení ⌈štítem a oštěpem;⌉ vypadali jako lev a rychlí byli jako gazely na horách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Vůdce byl Ezer, druhý Obadjáš, třetí Elíab,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'čtvrtý Mišmana, pátý Jeremjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'šestý Ataj, sedmý Elíel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'osmý Jóchanan, devátý Elzabad,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'desátý Jeremjáš, jedenáctý Makbanaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Toto jsou vůdci armády ze synů Gádových. ⌈Nejmenší za sto,⌉ největší za tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'To jsou ti, kteří prošli Jordánem v prvním měsíci, kdy se rozlévá na oba své břehy, a vyhnali všechny žijící v údolích na východ a na západ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Přišli také někteří ze synů Benjamínových a Judejci do pevnosti k Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'David před ně vyšel a promluvil k nim: Jestliže ke mně přicházíte v pokoji, abyste mi pomohli, ⌈budu s vámi zajedno;⌉ jestliže však abyste mě zradili mým protivníkům, ačkoli na mých rukou není násilí, ať pohledí ⌈Bůh našich otců⌉ a rozsoudí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Duch vyzbrojil Amasaje, vůdce kapitánů, takže řekl: Tobě patříme, Davide, s tebou jsme, synu Jišajův. ⌈Pokoj, pokoj tobě,⌉ pokoj tvým pomocníkům, vždyť ti pomáhá tvůj Bůh. David je přijal a ustanovil je vůdci oddílů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Někteří z Manasesa přeběhli k Davidovi, když táhl s Pelištejci do boje proti Saulovi. Ale nepomáhali jim, neboť když se pelištejská knížata poradila, propustila ho se slovy: Přeběhl by s našimi hlavami ke svému pánu Saulovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Když šel do Siklagu, přeběhli k němu někteří z Manasesa: Adnach, Józabad, Jedíael, Michael, Józabad, Elíhú a Siletaj, předáci Manasesových rodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Ti přišli Davidovi na pomoc proti loupežné hordě, neboť byli všichni udatní hrdinové; stali se veliteli v armádě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Den co den přicházeli lidé Davidovi na pomoc, až bylo vojsko velké jako ⌈vojsko Boží.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Toto jsou počty vůdců vojenských ozbrojenců, kteří přišli k Davidovi do Chebrónu, aby na něj podle Hospodinova příkazu přenesli Saulovo království:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Synů Judových, kteří nosili ⌈štít a oštěp,⌉ bylo šest tisíc osm set vojenských ozbrojenců;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'ze synů Šimeónových sedm tisíc jedno sto udatných hrdinů pro vojenskou službu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'ze synů Léviho čtyři tisíce šest set;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Jójada, vévoda Áronovců, a s ním tři tisíce sedm set;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Sádok, mladý udatný hrdina, a dům jeho otce, dvacet dva velitelů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'ze synů Benjamínových, Saulových bratrů, tři tisíce; až doposud jich většina zachovávala službu domu Saulova;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'ze synů Efrajimových dvacet tisíc osm set udatných hrdinů, věhlasných mužů v domě jejich otců;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'z poloviny pokolení Manasesova osmnáct tisíc těch, kteří byli jmenovitě určeni, aby šli ustanovit Davida králem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'ze synů Isacharových, ⌈kteří byli schopni rozumět⌉ časům a věděli, co má Izrael dělat, dvě stě jejich předáků a všichni jejich bratři podle jejich příkazu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'ze Zabulóna ti, kteří táhli s armádou připraveni do boje s všelijakými válečnými zbraněmi, padesát tisíc, ⌈hotových nastoupit bez bázně a hany;⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'z Neftalího tisíc velitelů a s nimi třicet sedm tisíc mužů se štítem a kopím;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'z Danovců připravení do boje -- dvacet osm tisíc šest set;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'z Ašera ti, kteří táhli s armádou připravení do boje -- čtyřicet tisíc;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'z druhé strany Jordánu z Rúbenovců, Gádovců a poloviny kmene Manasesova se všelijakými ⌈vojenskými válečnými zbraněmi⌉ -- sto dvacet tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Všichni tito bojovníci hotoví nastoupit na bojiště přišli ⌈s celým srdcem⌉ do Chebrónu ustanovit Davida králem nad celým Izraelem. Také všichni ostatní Izraelci byli jednomyslní, že ustanoví Davida králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Byli tam s Davidem tři dny, jedli a pili, neboť jejich bratři jim to připravili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, 'A také jejich příbuzní až z Isachara, Zabulóna a Neftalího přiváželi potravu na oslech, velbloudech, mezcích a volech -- ⌈moučná jídla,⌉ koláče z lisovaných fíků, sušené hrozny, víno, olej, skot a brav v hojnosti, neboť v Izraeli byla radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'David se poradil s veliteli nad tisíci a nad sty, se všemi vévody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Pak řekl David celému shromáždění Izraele: Jestliže se vám to líbí a je to od Hospodina, našeho Boha, ⌈rozšiřme všude ⌉ vzkaz svým bratrům, kteří zůstali na různých územích Izraele, a s nimi kněžím a lévitům do jejich měst s okolními pastvinami, ať se k nám shromáždí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'a přeneseme truhlu našeho Boha k nám, neboť ve dnech Saulových jsme ji nevyhledávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Celé shromáždění řeklo, aby se to udělalo, protože ⌈se to všemu lidu⌉ líbilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'David shromáždil celý Izrael od egyptského Šíchoru až po Lebo–Chamát, aby přenesli z Kirjat–jearímu Boží truhlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'David a celý Izrael vystoupil do Baaly, do Kirjat–jearímu, který je v Judsku, aby odtamtud přenesli truhlu Boha, Hospodina sedícího na cherubech, která se nazývá jeho jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Naložili Boží truhlu na nový vůz a vezli z Abínádabova domu; Uza a Achjó vůz vedli');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'a David i celý Izrael se radovali před Bohem ze vší síly -- s písněmi, lyrami, harfami, tamburínami, činely a trubkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Když přišli ke Kidónovu humnu, vztáhl Uza ruku, aby podržel truhlu, protože voli opustili cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Hospodinův hněv vzplál proti Uzovi a zabil ho, protože vztáhl ruku na truhlu; zemřel tam před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'David se rozzlobil, že se Hospodin prudce obořil na Uzu a nazval to místo Peres–uza, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Toho dne se David začal bát Boha a řekl: Jak bych mohl k sobě přenést Boží truhlu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'A David nevzal truhlu k sobě do Města Davidova, ale odsunul ji do domu Obéd–edóma Gatského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Boží truhla zůstala s domem Obéd–edómovým tři měsíce a Hospodin žehnal domu Obéd–edóma i všemu, co mu patřilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Týrský král Chíram poslal k Davidovi posly a cedrové dřevo, kameníky a tesaře, aby mu postavili dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'David věděl, že Hospodin ho určil za krále nad Izraelem a že se jeho království velmi povzneslo kvůli jeho lidu Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'David si vzal v Jeruzalémě další ženy a David zplodil další syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Toto jsou jména dětí, které měl v Jeruzalémě: Šamúa, Šóbab, Nátan, Šalomoun,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibchár, Elíšúa, Elpelet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nógah, Nefeg, Jafía,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elíšama, Beeljáda, Elífelet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Když se Pelištejci doslechli, že David byl pomazán za krále nad celým Izraelem, všichni Pelištejci vytáhli Davida hledat. Když se to David doslechl, vytáhl proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Pelištejci přitáhli a vtrhli do údolí Refájců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'David se doptával Boha: Mám proti Pelištejcům vytáhnout? Vydáš je do mé ruky? Hospodin mu odpověděl: Vytáhni. Vydám je do tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Vytáhli do Baal–perasímu a tam je David pobil. A David řekl: Bůh protrhl mé nepřátele skrze mě jako voda protrhuje hráz. Proto pojmenovali to místo Baal–perasím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Zanechali tam své bohy a David přikázal, aby byli spáleni ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Pelištejci znovu vytáhli a vtrhli do údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'David se znovu doptával Boha a Bůh mu řekl: Netáhni za nimi. Obejdi je a přitáhni k nim směrem od balzámovníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'I stane se, až uslyšíš zvuk pochodování ve vrcholcích balzámovníků, tehdy vytáhni do boje, protože Bůh vytáhne před tebou, aby pobil pelištejské vojsko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'David učinil tak, jak mu Bůh přikázal, a pobíjeli pelištejské vojsko od Gibeónu až do Gezeru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, '⌈Davidovo jméno proniklo do všech zemí⌉ a Hospodin dal ⌈strach z něj⌉ na všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Postavil pro sebe domy v Městě Davidově a připravil místo pro Boží truhlu, postavil pro ni stan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Tehdy David řekl: Nikdo nesmí nosit Boží truhlu, jenom lévité, neboť je Hospodin vyvolil, aby nosili Hospodinovu truhlu a sloužili mu navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'David shromáždil celý Izrael do Jeruzaléma, aby přenesli Hospodinovu truhlu na místo, které pro ni připravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'David shromáždil syny Áronovy a lévity:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Ze synů Kehatových předáka Uríela a jeho bratry -- sto dvacet;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'ze synů Merarího předáka Asajáše a jeho bratry -- dvě stě dvacet;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'ze synů Geršómových předáka Jóela a jeho bratry -- sto třicet;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'ze synů Elísáfanových předáka Šemajáše a jeho bratry -- dvě stě;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'ze synů Chebrónových předáka Elíela a jeho bratry -- osmdesát;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'ze synů Uzíelových předáka Amínadaba a jeho bratry -- sto dvanáct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'David zavolal kněze Sádoka a Ebjátara i lévity Uríela, Asajáše, Jóela, Šemajáše, Elíela a Amínadaba');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'a řekl jim: Vy jste předáci lévijských rodů; posvěťte se, vy i vaši bratři, a přeneste truhlu Hospodina, Boha Izraele, na místo, které jsem pro ni připravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Protože jste tam předtím nebyli, Hospodin, náš Bůh, se na nás obořil, neboť ⌈jsme se ho nedotazovali na⌉ nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Kněží a lévité se posvětili, aby přenesli truhlu Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Synové Léviho nesli Boží truhlu tak, jak přikázal Mojžíš, podle Hospodinova slova: na svých ramenou na tyčích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'David řekl lévijským předákům, aby ustanovili své bratry zpěváky s hudebními nástroji, harfami, lyrami a zvučnými činely, aby pozvedli hlas ⌈s radostí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'A lévité ustanovili Hémana, syna Jóelova, a z jeho bratrů Asafa, syna Berekjášova; ze synů Merarího, svých bratrů, Étana, syna Kúšajášova;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'a s nimi své druhořadé bratry: Zekarjáše, Jaazíela, Šemiramóta, Jechíela, Uniho, Elíaba, Benajáše, Maasejáše, Matitjáše, Elífelehúa, Miknejáše, Obéd–edóma a Jeíela vrátné;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'zpěváky: Hémana, Asafa a Étana, aby zpívali s bronzovými činely;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zekarjáše, Azíela, Šemiramóta, Jechíela, Uniho, Elíaba, Maasejáše a Benajáše s harfami na alamót,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Matitjáše, Elífelehúa, Miknejáše, Obéd–edóma, Jeíela, Azazjáše s lyrami, aby vedli hudbu na šeminit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanjáš, lévijský předák, ⌈při nošení řídil přenášení,⌉ neboť ⌈byl zručný.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berekjáš a Elkána byli vrátnými u truhly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Kněží Šebanjáš, Jóšafat, Netanel, Amasaj, Zekarjáš, Benajáš a Elíezer troubili na trubky před Boží truhlou. Obéd–edóm a Jechijáš byli vrátnými u truhly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'David, izraelští starší a velitelé nad tisíci šli, aby ⌈s radostí⌉ přenesli truhlu Hospodinovy smlouvy z domu Obéd–edómova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Protože Bůh pomáhal lévitům, kteří nesli truhlu Hospodinovy smlouvy, obětovali sedm býčků a sedm beranů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'David byl zahalen pláštěm z mořského hedvábí, též všichni lévité, kteří nesli truhlu, zpěváci a Kenanjáš, předák zpěváků přenášení; a David měl na sobě lněný efód.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Celý Izrael přenášel truhlu Hospodinovy smlouvy s křikem a za zvuku beraního rohu, trubek, zvučných činelů, harf a lyr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'I stalo se, když truhla Hospodinovy smlouvy vešla do Města Davidova, že Míkal, dcera Saulova, se rozhlížela z okna a uviděla krále Davida, jak poskakuje a raduje se; a pohrdla jím ve svém srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Přenesli Boží truhlu, postavili ji uprostřed stanu, který pro ni David postavil, a obětovali před Bohem zápalné a pokojné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Když David dokončil přinášení zápalných a pokojných obětí, požehnal lidu v Hospodinově jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Pak podělil ⌈všechny Izraelce, muže i ženy,⌉ každému bochník chleba, datlový a hrozinkový koláč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Nato ustanovil některé z lévitů před Hospodinovu truhlu jako služebníky, aby ⌈vzdávali díky, chválili a připomínali⌉ Hospodina, Boha Izraele:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Předáka Asafa, druhého po něm Zekarjáše, Jeíela, Šemiramóta, Jechíela, Matitjáše, Elíaba, Benajáše, Obéd–edóma a Jeíela s hudebními nástroji, harfami a lyrami a Asafa se zvučnými činely');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'a kněze Benajáše a Jachazíela s trubkami, aby byli ustavičně před truhlou Boží smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Tehdy, v onen den, David poprvé ustanovil, aby byly vzdávány díky Hospodinu prostřednictvím Asafa a jeho bratrů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Vzdávejte chválu Hospodinu, vzývejte jeho jméno, oznamujte mezi národy jeho činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Zpívejte mu, opěvujte jej, přemýšlejte o všech jeho obdivuhodných činech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Chlubte se jeho svatým jménem, ať ⌈se raduje srdce⌉ těch, kdo hledají Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Hledejte Hospodina a jeho sílu, ustavičně vyhledávejte jeho tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Pamatujte na jeho obdivuhodné činy, které učinil, na jeho divy a rozsudky jeho úst,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'potomci Izraele, jeho otroka, synové Jákobovi, jeho vyvolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'On je Hospodin, náš Bůh, jeho rozhodnutí jsou po celé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Připomínejte navěky jeho smlouvu, slovo, které přikázal tisíci pokolení;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'smlouvu, kterou uzavřel s Abrahamem, jeho přísahu Izákovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'potvrdil ji jako ustanovení Jákobovi, jako smlouvu věčnou Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Řekl: Tobě dám kenaanskou zemi za váš dědičný díl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Na počet vás byla malá hrstka, pobývali jste v ní jako cizinci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'přecházeli z národa do národa, z království do jiného lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Nedovolil nikomu, aby je utlačoval, káral kvůli nim krále:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Nedotýkejte se mých pomazaných, mým prorokům neubližujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, '⌈Zpívej Hospodinu, celá země,⌉ zvěstujte den za dnem jeho záchranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Vypravujte mezi národy o jeho slávě, mezi všemi lidmi o jeho obdivuhodných činech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Vždyť ⌈Hospodin je velký,⌉ nejvýš chvályhodný, obávaný nad všechny bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Vždyť všichni bohové národů jsou nicotnosti, ale Hospodin ⌈učinil nebesa.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, '⌈Nádhera a důstojnost⌉ je před ním, síla a radost ⌈na jeho místě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Vzdejte Hospodinu, čeledi národů, vzdejte Hospodinu slávu a moc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Vzdejte Hospodinu slávu jeho jména, přineste dar, přijďte před něj, klaňte se Hospodinu v slávě svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, '⌈Svíjej se před ním, celá země.⌉ Ano, svět stojí pevně, nezhroutí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Ať se nebesa radují a země ať jásá; ať říkají mezi národy: ⌈Hospodin kraluje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Ať burácí moře i ⌈všechno, co je v něm;⌉ ať se veselí pole i všechno, co je na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Tehdy budou lesní stromy radostně volat před Hospodinem, že přichází soudit zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Vzdávejte Hospodinu díky, protože je dobrý, jeho milosrdenství je navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Říkejte: Zachraň nás, Bože, náš zachránce, shromáždi nás a vysvoboď nás z národů, abychom vzdávali díky tvému svatému jménu a uctívali tvou chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, '⌈Požehnán buď Hospodin, Bůh Izraele,⌉ od věků až navěky. A všechen lid řekl: Amen. Chvalte Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Tam před truhlou Hospodinovy smlouvy zanechal Asafa a jeho bratry, aby sloužili před truhlou ustavičně podle každodenního určení;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'dále Obéd–edóma a jeho šedesát osm bratrů, Obéd–edóma, syna Jedútúnova, a Chosu jako vrátné;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'kněze Sádoka a jeho bratry kněze před Hospodinovým příbytkem na návrší, které je v Gibeónu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'aby přinášeli zápalné oběti Hospodinu na ⌈oltáři pro zápalné oběti⌉ ustavičně, ráno i večer, podle všeho, co je zapsáno v Hospodinově zákoně, který přikázal Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'S nimi byli také Héman, Jedútún a ostatní vybraní, kteří byli jmenovitě určeni, aby vzdávali Hospodinu díky, protože jeho milosrdenství je navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Héman a Jedútún měli s sebou trubky, zvučné činely a nástroje pro písně Bohu; synové Jedútúnovi byli v bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Potom všechen lid odešel, každý domů, a David se vrátil, aby ⌈požehnal svému domu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'I stalo se, když David sídlil ve svém domě, že řekl David proroku Nátanovi: Hle, já sídlím v cedrovém domě a truhla Hospodinovy smlouvy je pod stanovou plachtou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Nátan Davidovi odpověděl: Učiň vše, co máš na srdci, protože Bůh je s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'V oné noci se stalo však Boží slovo k Nátanovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Jdi a řekni mému otroku Davidovi: Toto praví Hospodin: Ty mi nestav dům, abych v něm sídlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Vždyť jsem nesídlil v domě od toho dne, kdy jsem Izrael vyvedl, až do tohoto dne, ale přecházel jsem ze stanu do stanu a z příbytku do příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Ať jsem přecházel ⌈s celým Izraelem⌉ kudykoli, řekl jsem snad některému ze soudců Izraele, jež jsem ustanovil, aby pásli můj lid: Proč mi nepostavíte cedrový dům?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Nuže, toto pověz mému otroku Davidovi: Toto praví Hospodin zástupů: Vzal tě z pastvin, od chovu ovcí, abys byl vévodou nad mým lidem Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Byl jsem s tebou, kamkoli jsi šel, a vyhladil jsem před tebou všechny tvé nepřátele. Učiním tvé jméno, jako je jméno velikánů na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Nachystám pro svůj lid Izrael území, zasadím ho, bude bydlet na svém místě a nebude se již třást. Bídáci ho již nebudou odírat jako dříve,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'ode dnů, kdy jsem ustanovil soudce nad svým lidem Izraelem; pokořím všechny tvé nepřátele. Oznamuji ti, že dům ti postaví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'I stane se, až se naplní tvé dny, abys šel ke svým otcům, dám povstat tvému potomku po tobě, který bude ze tvých synů, a upevním jeho království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'On mi postaví dům a já upevním jeho trůn navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Já budu jeho otcem a on bude mým synem. Své milosrdenství od něj neodejmu, tak jak jsem odňal od toho, který byl před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Ustanovím ho ve svém domě a ve svém království navěky a jeho trůn bude pevně stát navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Všechna tato slova a celé toto vidění pověděl Nátan Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Nato král David vešel, posadil se před Hospodinem a řekl: Kdo jsem já, Hospodine Bože, a co je můj dům, že jsi mě přivedl až sem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'I toto bylo málo ve tvých očích, Bože, a promluvil jsi o domě svého otroka do vzdálené budoucnosti. ⌈Ukázal jsi mi, co touží člověk poznat,⌉ Hospodine Bože.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Co ti může David ještě dále říct o slávě tvého otroka? Ty svého otroka znáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Hospodine, kvůli svému otroku a podle svého srdce jsi učinil všechny tyto velké věci a dal jsi mu poznat všechny tyto velké skutečnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Hospodine, není nikdo jako ty, není Bůh kromě tebe -- tak, jak jsme na vlastní uši slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'A kdo je jako tvůj lid Izrael, jediný národ na zemi, kterého šel Bůh vykoupit sobě za lid, a učinil si jméno velkými a hrůzu vzbuzujícími činy, když jsi vyhnal národy před svým lidem, který sis vykoupil z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Učinil sis svůj lid Izrael navěky svým lidem a ty, Hospodine, ses stal jejich Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'A nyní, Hospodine, slovo, které jsi promluvil o svém otroku a o jeho domu, ať se ukáže jako spolehlivé navěky. Učiň, jak jsi prohlásil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'A jako spolehlivé a velké ať se ukáže tvé jméno navěky, když budou říkat: Hospodin zástupů, Bůh Izraele, je Bohem Izraele. A dům tvého otroka Davida bude pevně stát před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Vždyť ty, můj Bože, jsi odhalil uchu svého otroka, že mu postavíš dům. Proto našel tvůj otrok odvahu modlit se před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nyní, Hospodine, ty jsi Bůh a promluvil jsi o svém otroku tyto dobré věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Nyní jsi ráčil požehnat domu svého otroka, aby byl navěky před tebou. Když ty jsi Hospodine požehnal, bude požehnán navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Potom se stalo, že David pobil Pelištejce, pokořil je a vzal od Pelištejců Gat a jeho vesnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Pobil i Moábce a Moábci se stali Davidovými otroky a přinášeli dávky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David pobil také Hadad–ezera, krále Sóby, v Chamátu, když táhl upevnit svou moc u řeky Eufratu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'David mu zajal tisíc vozů, sedm tisíc jezdců a dvacet tisíc pěšáků. David ochromil všechny koně k vozům a ponechal mu koně jen ke stu vozům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Aramejci z Damašku přitáhli Hadad–ezerovi, králi Sóby, na pomoc, ale David pobil z Aramejců dvacet dva tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Pak David umístil mezi Aramejce z Damašku posádku, Aramejci se stali Davidovými otroky a přinášeli dávky. Hospodin pomáhal Davidovi, kamkoli šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'David vzal zlaté štíty, které měli Hadad–ezerovi otroci, a přinesl je do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Z Tibchatu a Kúnu, Hadad–ezerových měst, vzal David velmi mnoho bronzu, z něhož Šalomoun udělal bronzové moře, sloupy a bronzové předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Když se Toú, král Chamátu, doslechl, že David pobil celé vojsko Hadad–ezera, krále Sóby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'poslal ke králi Davidovi svého syna Hadoráma, aby se ho zeptal, jak se mu daří, a poblahopřál mu, že bojoval proti Hadad–ezerovi a zabil ho. Toú totiž vedl války s Hadad–ezerem. Hadorám s sebou přinesl všelijaké zlaté, stříbrné a bronzové předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Také ty král David zasvětil Hospodinu spolu se stříbrem a zlatem, které přinesl ze všech národů: od Edómců, Moábců, synů Amónových, od Pelištejců a Amálekovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Abíšaj, syn Serújin, pobil v Solném údolí osmnáct tisíc Edómců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Umístil v Edómu posádky a všichni Edómci se stali Davidovými otroky. Hospodin pomáhal Davidovi, kamkoli šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'David kraloval nad celým Izraelem a vykonával ⌈právo a spravedlnost⌉ nad vším svým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Jóab, syn Serújin, byl nad armádou, Jóšafat, syn Achílúdův, byl kancléřem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sádok, syn Achítúbův, a Abímelek, syn Ebjátarův, byli kněžími, Šavša byl písařem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benajáš, syn Jójadův, byl nad Keretejci a Peletejci a Davidovi synové byli první králi k ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Potom se stalo, že zemřel Náchaš, král synů Amónových, a po něm se stal králem jeho syn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'David si řekl: Prokážu milosrdenství Chanúnovi, synu Náchašovu, neboť jeho otec prokázal milosrdenství mně. A tak David poslal posly, aby mu poskytl útěchu nad jeho otcem. Když přišli Davidovi otroci do země synů Amónových k Chanúnovi, aby mu poskytli útěchu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'knížata synů Amónových řekla Chanúnovi: Připadá ti, že chce uctít tvého otce, když ti poslal utěšitele? Což nepřišli jeho otroci k tobě, jen aby důkladně prohlédli, vyvrátili a prozkoumali zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Chanún vzal Davidovy otroky, oholil je, odřízl polovinu jejich roucha až po zadek a poslal je pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, '⌈Kdosi šel a pověděl⌉ o těch mužích Davidovi. On jim poslal naproti, protože ti muži byli velice zhanobeni. Král řekl: Zůstaňte v Jerichu, dokud vám vousy nedorostou, a pak se vraťte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Synové Amónovi viděli, že se Davidovi znelíbili. Proto Chanún a synové Amónovi poslali tisíc talentů stříbra, aby si z Aramského Dvojříčí, z Aramské Maaky a ze Sóby najali vozy a jezdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Najali si třicet dva tisíc vozů, krále Maaky a jeho lid. Vytáhli a utábořili se před Médebou. Synové Amónovi se shromáždili ze svých měst a vytáhli do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Když se to doslechl David, poslal Jóaba a celou armádu hrdinů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Synové Amónovi vytáhli a sešikovali se k boji u vchodu do města. Ale králové, kteří přitáhli, byli zvlášť, na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Když Jóab viděl, že je proti němu boj z předu i zezadu, vybral všechny vybrané muže z Izraele a sešikoval se proti Aramejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Zbytek lidu dal pod velení svého bratra Abíšaje, aby se sešikovali proti synům Amónovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Řekl: Jestliže budou Aramejci silnější nežli já, přijdeš mi na pomoc. A jestliže budou synové Amónovi silnější nežli ty, pomůžu já tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Buď silný a počínejte si zmužile za svůj lid a za města našeho Boha. A Hospodin ať učiní, co je dobré v jeho očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Jóab a lid, který byl s ním, se pustil do boje proti Aramejcům, ale ti před ním utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Když synové Amónovi viděli, že Aramejci utíkají, také oni před jeho bratrem Abíšajem utekli a vešli do města. Jóab šel do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Když Aramejci viděli, že byli od Izraele poraženi, poslali posly a nechali přivést Aramejce, kteří byli v Zaeufratí. V jejich čele byl Šófak, velitel Hadad–ezerovy armády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Když to bylo Davidovi oznámeno, shromáždil celý Izrael, přešel Jordán, vytáhl proti nim a sešikoval se proti nim. David se sešikoval proti Aramejcům do boje a oni s ním bojovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Aramejci však před Izraelem utekli. David zabil sedm tisíc aramejských voza tajů, čtyřicet tisíc pěšáků. I velitele armády Šófaka usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Když Hadad–ezerovi otroci viděli, že byli od Izraele poraženi, uzavřeli s Davidem mír a sloužili mu. Aramejci již nechtěli synům Amónovým pomáhat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'I stalo se na přelomu roku, v době, kdy králové táhnou do boje, že Jóab vedl vojenské síly a ničil zemi synů Amónových. Přitáhl a oblehl Rabu, zatímco David zůstal v Jeruzalémě. Jóab přepadl Rabu a zbořil ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'David vzal korunu jejich krále z jeho hlavy; shledal, že váží talent zlata a byl na ní drahokam. Spočinula na Davidově hlavě. Vynesl z města velmi mnoho kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Lid, který byl v něm, vyvedl a ustanovil, aby pracovali s pilou, železnými špičáky a sekerami. Tak jednal David se všemi městy synů Amónových. David a všechen lid se pak vrátil do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Potom se stalo, že vypukl boj s Pelištejci v Gezeru. Tehdy Sibekaj Chúšatský ubil Sipaje z rodu Refájců a byli pokořeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Znovu došlo k boji s Pelištejci a Elchánan, syn Jaírův, ubil Lachmího, bratra Goliáše Gatského. Násada jeho kopí byla jako tkalcovské vratidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Znovu došlo k boji v Gatu. Byl tam obrovitý muž, který měl po šesti prstech, celkem dvacet čtyři. Také on se narodil Refájcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Když tupil Izrael, ubil ho Jónatan, syn Davidova bratra Šimey.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ti se narodili Refájcům v Gatu. Padli rukou Davida a rukou jeho otroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Satan povstal proti Izraeli a navedl Davida, aby spočítal Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'David řekl Jóabovi a ⌈knížatům lidu:⌉ Jděte a spočítejte Izrael od Beer–šeby až po Dan a přineste mi zprávu, ať vím, kolik jich je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Jóab řekl: Ať Hospodin přidá ke svému lidu stokrát víc, než ho je. Což nejsou, můj pane a králi, všichni otroky mého pána? Proč to chce můj pán udělat? Proč by měla být vina na Izraeli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Královo slovo však bylo vůči Jóabovi pevné. Jóab tedy vyšel, procházel celým Izraelem a vrátil se do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Jóab udal Davidovi počet sečteného lidu. Všech Izraelců byl milion sto tisíc mužů tasících meč a Judejců bylo čtyři sta sedmdesát tisíc mužů tasících meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Mezi Lévijci a Benjamínci nepočítal, protože Jóabovi se královo slovo ošklivilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Ta věc byla zlá v Božích očích a ranil Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Nato David řekl Bohu: Velmi jsem zhřešil, že jsem to udělal. Nyní odejmi, prosím, vinu svého otroka, neboť jsem jednal velice bláznivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Hospodin promluvil ke Gádovi, Davidovu vidoucímu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Jdi a promluv k Davidovi: Toto praví Hospodin: ⌈Předkládám ti⌉ tři věci. Vyber si jednu z nich, kterou ti mám udělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Gád přišel k Davidovi a řekl mu: Toto praví Hospodin: Vyber si:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Tři roky hladu nebo tři měsíce být ničen svými protivníky, kdy by tě stíhal meč tvých nepřátel, anebo tři dny Hospodinova meče a moru v zemi, kdy by Hospodinův anděl působil zkázu po celém území Izraele. Nyní se rozhodni, co mám odpovědět tomu, kdo mě poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David Gádovi odpověděl: Jsem ve veliké tísni. Kéž padnu do Hospodinovy ruky, neboť jeho slitování je velké. Jenom ať nepadnu do ruky člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Hospodin uvedl na Izrael mor a padlo z Izraele sedmdesát tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Bůh poslal do Jeruzaléma anděla, aby ho ničil. A když ničil, Hospodin to viděl, litoval toho zla a řekl andělu, který působil zkázu: Dost. Nyní odtáhni svou ruku. A Hospodinův anděl se zastavil u humna Ornána Jebúsejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'David pozvedl oči a uviděl Hospodinova anděla, jak stojí mezi zemí a nebem a v ruce má tasený meč, vztažený nad Jeruzalémem. David i starší přikrytí pytlovinou padli na svou tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'David řekl Bohu: Což jsem neřekl já, aby byl sečten lid? Já jsem zhřešil a spáchal velké zlo. Ale tyto ovce, co provedly? ⌈Hospodine, můj Bože,⌉ ať je tvá ruka proti mně a proti domu mého otce, ale na tvůj lid ať ne dopadne rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Hospodinův anděl řekl Gádovi, aby řekl Davidovi: Ať David jde a postaví Hospodinu oltář na humně Ornána Jebúsejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'David šel podle Gádova slova, které promluvil ⌈v Hospodinově jménu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Když se Ornán obrátil, uviděl toho anděla. Jeho čtyři synové, kteří byli s ním, se skrývali. Ornán mlátil pšenici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'David přišel až k Ornánovi. Když se Ornán ohlédl, uviděl Davida, vyšel z humna a klaněl se Davidovi tváří k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'David řekl Ornánovi: Dej mi místo, na kterém je humno, abych na něm mohl postavit Hospodinu oltář. Dej mi ho za plnou cenu stříbra, aby byla rána od lidu zadržena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornán řekl Davidovi: Vezmi si to. Ať můj pán a král udělá, co je ⌈mu libo.⌉ Pohleď, dám skot pro zápalnou oběť, smyky na dříví a pšenici pro přídavnou oběť. To všechno dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Král David řekl Ornánovi: Ne! Chci to koupit za plnou cenu stříbra. Vždyť ne mohu přinést Hospodinu to, co je tvé, či přinést zápalnou oběť získanou zadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'A David dal Ornánovi za to místo šest set šekelů váhy zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Pak tam David postavil Hospodinu oltář a přinesl zápalné a pokojné oběti. Volal k Hospodinu a on mu odpověděl ohněm z nebe, seslaným na ⌈oltář pro zápalné oběti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Hospodin řekl andělovi, aby vrátil svůj meč do pochvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'V oné době, když David viděl, že mu Hospodin odpověděl na humně Ornána Jebúsejského, ⌈obětoval tam.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Hospodinův příbytek, který udělal Mojžíš v pustině, i oltář pro zápalné oběti byl v oné době na návrší v Gibeónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Ale David nemohl jít před něj hledat Boha, protože se děsil meče Hospodinova anděla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'David řekl: Toto bude dům Hospodina Boha a toto bude oltář pro zápalné oběti pro Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'David přikázal, aby shromáždili cizince, kteří jsou v izraelské zemi, a ustanovil kameníky, aby tesali kameny tesané na míru pro stavbu Božího domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'David připravil též množství železa na hřebíky pro vrata bran a na skoby a bronzu takové množství, že se ne dalo zvážit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'a cedrového dřeva, že se ne dalo spočítat, neboť Sidónci a Týřané přiváželi Davidovi množství cedrového dřeva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'David si řekl: Můj syn Šalomoun je ⌈mladý a útlý⌉ a dům, který se má postavit Hospodinu, musí být zvlášť veliký, aby byl věhlasný a slavný po všech zemích. Musím pro něj udělat přípravy. A David připravil před svou smrtí množství materiálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Potom zavolal svého syna Šalomouna a přikázal mu, aby postavil dům pro Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'David řekl Šalomounovi: Můj synu, ⌈měl jsem na srdci⌉ postavit dům pro jméno Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Ale stalo se ke mně Hospodinovo slovo: Prolil jsi mnoho krve a vedl jsi velké války. Nestav dům pro mé jméno, neboť jsi prolil přede mnou mnoho krve na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Hle, narodí se ti syn. On bude mužem odpočinutí. Jemu dám odpočinek od všech jeho okolních nepřátel. Vždyť se bude jmenovat Šalomoun. V jeho dnech dám na Izrael pokoj a klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'On postaví dům pro mé jméno. On bude mým synem a já budu jeho otcem. Jeho královský trůn nad Izraelem upevním navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Nyní, můj synu, ať ⌈je Hospodin s tebou.⌉ Ať uspěješ a postavíš dům Hospodinu, svému Bohu, jak o tobě promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Jen ať ti Hospodin dá rozumnost a porozumění a ustanoví tě nad Izraelem, abys zachovával zákon Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Tehdy uspěješ, jestliže ⌈budeš zachovávat a plnit⌉ ustanovení a nařízení, která Hospodin přikázal Mojžíšovi pro Izrael. ⌈Posilni se a buď odvážný,⌉ neboj se a neděs se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Hle, ve svém soužení jsem pro Hospodinův dům připravil sto tisíc talentů zlata, milion talentů stříbra a takové množství bronzu a železa, že se ne dá zvážit. Také dřevo a kámen jsem připravil a ty k nim přidej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Je u tebe množství dělníků: lamači, kameníci a tes aři a všelijací zruční řemeslníci pro každou práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Zlata, stříbra, bronzu a železa je bezpočet. Povstaň a jednej a Hospodin ať je s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'A David přikázal všem izraelským knížatům, aby jeho synu Šalomounovi pomáhali:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Což není Hospodin, můj Bůh, s vámi a ne dal vám odpočinek ⌈všude⌉ kolem? Vždyť vydal obyvatele země do mé ruky a ⌈zemi si podmanil Hospodin a jeho lid.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Nyní přiložte své srdce a svou duši k hledání Hospodina, svého Boha. Povstaňte a stavte svatyni Hospodina Boha, aby byla přenesena truhla Hospodinovy smlouvy a posvátné Boží předměty do domu postaveného pro Hospodinovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Když David zestárl a byl sytý dnů, ustanovil králem nad Izraelem svého syna Šalomouna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Shromáždil všechna izraelská knížata, kněze a lévity.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Spočítali lévity od věku třiceti let výše a jejich počet, ⌈ hlava za hlavou,⌉ byl třicet osm tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Z nich bylo dvacet čtyři tisíc vedoucích nad službou Hospodinova domu, šest tisíc správců a soudců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'čtyři tisíce vrátných a čtyři tisíce chválících Hospodina na nástroje, které jsem udělal pro chválení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David je rozdělil po skupinách podle synů Léviho, Geršóna, Kehata a Merarího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Ke Geršónovcům: Laedán a Šimeí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Synové Laedánovi: předák Jechíel, Zétam a Jóel, tito tři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Synové Šimeího: Šelomít, Chazíel a Háran, tito tři. To byli předáci Laedánových rodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Synové Šimeího: Jachat, Zína, Jeúš a Bería. To byli čtyři synové Šimeího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jachat byl předákem, Zíza druhý. Jeúš a Bería neměli mnoho synů, byli bráni jako jeden otcovský dům, s jednou povinností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Synové Kehatovi: Amrám, Jishár, Chebrón a Uzíel, tito čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Synové Amrámovi: Áron a Mojžíš. Áron byl oddělen, aby posvěcoval nejsvětější věci, on i jeho synové navěky, aby pálili kadidlo před Hospodinem, sloužili mu a žehnali v jeho jménu navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Co se týče ⌈Mojžíše, muže Božího,⌉ jeho synové byli jmenováni u kmene Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Synové Mojžíšovi: Geršóm a Elíezer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Synové Geršómovi: předák Šebúel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Synové Elíezerovi byli: předák Rechabjáš. Elíezer neměl další syny, ale synů Rechabjášových bylo velmi mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Synové Jishárovi: předák Šelomít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Synové Chebrónovi: předák Jerijáš, druhý Amarjáš, třetí Jachazíel a čtvrtý Jekameám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Synové Uzíelovi: předák Míka, druhý Jišijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Synové Merarího: Machlí a Muší. Synové Machlího: Eleazar a Kíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleazar zemřel a neměl syny, jenom dcery. A tak si je vzali synové Kíšovi, jejich příbuzní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Synové Mušího: Machlí, Eder a Jeremót, tito tři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Toto jsou synové Léviho podle domu svých otců, předáci rodů, jak byli spočítáni podle počtu jmen, hlava za hlavou, ti, kteří konali práci služby Hospodinova domu od věku dvaceti let výše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Neboť David řekl: Hospodin, Bůh Izraele, dal odpočinek svému lidu a bude navěky přebývat v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'A tak nemusejí lévité nosit příbytek ani všechny předměty pro jeho službu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Neboť podle Davidových posledních slov byli synové Léviho počítáni od věku dvacet let výše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Jejich stanoviště bylo vedle synů Áronových v službě Hospodinova domu -- byli nad nádvořími, komorami, nad očišťováním všech svatých věcí a dílem služby Božího domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'nad předkladným chlebem, jemnou moukou pro přídavné oběti, plackami nekvašených chlebů, plochými pánvemi, mísením a všemi odměrkami objemu a mírami délky;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'ráno co ráno stáli a vzdávali díky a chválili Hospodina, a tak i večer,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'i při každém přinášení zápalných obětí Hospodinu, o sobotách, novoluních a svátcích podle počtu nařízeného pro ně, ustavičně před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, '⌈Konali tedy⌉ službu u stanu setkávání, službu u svatyně a službu u synů Áronových, svých bratrů, při službě Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Toto byly skupiny synů Áronových: Synové Áronovi: Nádab a Abíhú, Eleazar a Ítamar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Nádab a Abíhú zemřeli před svým otcem a neměli syny, takže jako kněží sloužili Eleazar a Ítamar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'David se Sádokem ze synů Eleazarových a Achímelekem ze synů Ítamarových je rozdělili podle jejich ⌈služebních povinností.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Shledalo se, že synů Eleazarových je více předních mužů, nežli synů Ítamarových a přidělili synům Eleazarovým šestnáct předáků podle domu otců a synům Ítamarovým osm podle domu jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Přidělili je losy, ty i ony, neboť byli předáky svatyně a předáky Božími ze synů Eleazarových i ze synů Ítamarových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Zapsal je písař Šemajáš, syn Netanelův, z lévitů, před králem, knížaty, knězem Sádokem a Achímelekem, synem Ebjátarovým, a předáky kněžských a lévijských rodů -- vždy jeden otcovský dům byl vytažen pro Eleazara a jeden byl vytažen pro Ítamara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'První los padl na Jójaríba, druhý na Jedajáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'třetí na Charima, čtvrtý na Seórima,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'pátý na Malkijáše, šestý na Mijamína,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'sedmý na Hakóse, osmý na Abijáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'devátý na Jéšuu, desátý na Šekanjáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'jedenáctý na Eljašíba, dvanáctý na Jakíma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'třináctý na Chupu, čtrnáctý na Ješebába,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'patnáctý na Bilgu, šestnáctý na Imera,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'sedmnáctý na Chezíra, osmnáctý na Hapisesa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'devatenáctý na Petachjáše, dvacátý na Ezechiele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'dvacátý první na Jakína, dvacátý druhý na Gamúla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'dvacátý třetí na Delajáše a dvacátý čtvrtý na Maazjáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Toto jsou jejich ⌈služební povinnosti,⌉ jak měli přicházet do Hospodinova domu podle nařízení daného jim prostřednictvím jejich otce Árona, jak mu přikázal Hospodin, Bůh Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Zbývající synové Léviho: ze synů Amrámových: Šúbael, ze synů Šúbaelových: Jechdejáš;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'z Rechabjáše, ze synů Rechabjášových: předák Jišijáš;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'z Jishárců: Šelomót, ze synů Šelomótových: Jachat;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'synové ⌈ Chebrónovi: předák ⌉ Jerijáš, druhý Amarjáš, třetí Jachazíel, čtvrtý Jekameám;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'synové Uzíelovi: Míka, ze synů Míkových: Šamír;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Míkův bratr: Jišijáš, ze synů Jišijášových: Zekarjáš;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'synové Merarího: Machlí a Muší; synové Jaazijáše, jeho syna;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'synové Merarího z jeho syna Jaazijáše: Šóham, Zakúr a Ibrí;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'z Machlího: Eleazar, který neměl syny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'z Kíše, synové Kíšovi: Jerachmeel;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'synové Mušího: Machlí, Eder a Jerímót. Toto jsou synové Léviho podle domu jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Také oni nechali padnout losy jako jejich bratři, synové Áronovi, před králem Davidem, Sádokem a Achímelekem, předáky kněžských a lévijských rodů, předákovi rodů stejně jako jeho nejmladšímu bratru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'David s veliteli armády oddělil pro službu syny Asafovy, Hémanovy a Jedútúnovy, aby prorokovali s lyrami, s harfami a činely. Počet těch, kteří konali dílo podle své služby, byl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Ze synů Asafových: Zakúr, Josef, Netanjáš a Asaréla. Synové Asafovi byli pod vedením Asafa, který prorokoval pod vedením krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Z Jedútúna, synové Jedútúnovi: Gedaljáš, Serí, Izajáš, Chašabjáš a Matitjáš, celkem šest, pod vedením svého otce Jedútúna, který prorokoval s lyrou za vzdávání díků a chválení Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Z Hémana, synové Hémanovi: Bukijáš, Matanjáš, Uzíel, Šebúel, Jerímót, Chananjáš, Chananí, Elíata, Gidaltí, Rómamtí–ezer, Jošbekáša, Malótí, Hótír a Machazíót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Všichni tito byli synové Hémana, králova vidoucího, podle Božích slov, aby byl pozdvižen jeho roh. Bůh dal Hémanovi čtrnáct synů a tři dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Všichni tito byli pod vedením svého otce pro zpěv v Hospodinově domě s činely, harfami a lyrami, pro službu Božího domu. ⌈Asaf, Jedútún a Héman byli pod vedením krále.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Jejich počet spolu s jejich bratry vycvičenými ve zpěvu Hospodinu, samí zkušení muži, byl dvě stě osmdesát osm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Losy pro službu nechali padnout jak pro malé, tak i velké, zkušené i učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'První los padl pro Asafa na Josefa; druhý na Gedaljáše, na něj, jeho bratry a syny, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'třetí na Zakúra, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'čtvrtý na Jisrího, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'pátý na Netanjáše, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'šestý na Bukijáše, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'sedmý na Jesarélu, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'osmý na Izajáše, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'devátý na Matanjáše, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'desátý na Šimeího, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'jedenáctý na Azarela, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'dvanáctý na Chašabjáše, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'třináctý na Šebúela, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'čtrnáctý na Matitjáše, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'patnáctý na Jeremóta, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'šestnáctý na Chananjáše, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'sedmnáctý na Jošbekášu, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'osmnáctý na Chananího, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'devatenáctý na Malótího, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'dvacátý na Elíatu, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'dvacátý první na Hótíra, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'dvacátý druhý na Gidaltího, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'dvacátý třetí na Machazíóta, jeho syny a bratry, dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'dvacátý čtvrtý na Rómamtí–ezera, jeho syny a bratry, dvanáct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Ke skupinám vrátných patřili: z Kórachovců: Mešelemjáš, syn Kórého, ze synů Asafových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Mešelemjáš měl syny: prvorozeného Zekarjáše, druhého Jedíaela, třetího Zebadjáše, čtvrtého Jatníela,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'pátého Élama, šestého Jóchanana a sedmého Eljóenaje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Obéd–edóm měl syny: prvorozeného Šemajáše, druhého Józabada, třetího Jóacha, čtvrtého Sakara, pátého Netanela,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'šestého Amíela, sedmého Isachara, osmého Peúltaje, neboť mu Bůh požehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Jeho synu Šemajášovi se narodili synové vládnoucí v domě svého otce, neboť to byli udatní hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Synové Šemajášovi: Otní, Refaúl, Obéd a Elzabad; jeho bratři Elíhú a Semakjáš byli udatní muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Tito všichni byli ze synů Obéd–edómových; jejich synové a bratři byli udatní muži, schopni ke službě, šedesát dva Obéd–edómovců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Mešelemjáš měl osmnáct synů a bratrů, udatných mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Chosa, ze synů Merarího, měl syny: Předáka Šimrího -- nebyl sice prvorozený, ale jeho otec jej ustanovil za předáka --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'druhého Chilkijáše, třetího Tebaljáše, čtvrtého Zekarjáše; všech synů a bratrů Chosových bylo třináct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Těmto skupinám vrátných podle mužů předáků byly dány služby jako jejich bratrům, aby sloužili v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Nechali padnout losy podle domu svých otců jak pro malé, tak i velké, pro ⌈ každou bránu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Los na Východní bránu padl pro Šelemjáše. Když nechali padnout los pro jeho syna Zekarjáše, rozumného rádce, jeho los padl na Severní bránu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Pro Obéd–edóma na Jižní bránu a pro jeho syny na sklady;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'pro Šupíma a pro Chosu na Západní bránu s bránou Šaleket na horní silnici; stráž vedle stráže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Na východě bylo šest lévitů, na severu denně čtyři, na jihu denně čtyři, pro sklady po dvou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'u parbaru na západě: čtyři na silnici a dva u parbaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Toto jsou skupiny vrátných ze synů Kórachových a ze synů Merarího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Další lévité: Achijáš byl nad poklady Božího domu a nad poklady svatých věcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Synové Laedánovi: synové Geršónovců patřící Laedánovi, předáci rodů Geršónovce Laedána -- Jechíelovci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Synové Jechíelovi: Zétami a jeho bratr Jóel byli nad poklady Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Z Amrámců, Jishárců, Chebrónců a Ozíelců');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'byl představeným nad poklady Šebúel, syn Geršóma, syna Mojžíšova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Jeho bratři z Elíezera: Jeho syn Rechabjáš, jeho syn Jóram, jeho syn Zikrí, jeho syn Izajáš, jeho syn Šelomít --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'tento Šelomít a jeho bratři byli nad všemi poklady svatých věcí, které zasvětil král David, předáci rodů, velitelé nad tisíci a nad sty, velitelé armády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Něco z bojů a kořisti zasvětili na opravu Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Všechno, co zasvětil vidoucí Samuel, Saul, syn Kíšův, Abnér, syn Nérův, i Jóab, syn Serújin, všechno, co bylo zasvěcené, bylo ve správě Šelomíta a jeho bratrů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Z Jishárců: Kenanjáš a jeho synové byli jako správci a soudci nad Izraelem pro službu mimo svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Z Chebrónců: Chašabjáš a jeho bratři, tisíc sedm set udatných mužů, byli dozorci nad Izraelem na západ od Jordánu pro veškeré dílo Hospodinovo i pro službu králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Z Chebrónců: předák Jerijáš; (co se týče Chebrónců, totiž jejich rodopisu otců: ve čtyřicátém roce Davidova kralování se hledalo a našli se mezi nimi udatní hrdinové v gileádském Jaezeru)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'jeho bratrů, udatných mužů, bylo dva tisíce sedm set předáků rodů. Ty král David ustanovil nad Rúbenovci, Gádovci a polovinou kmene Manasesova pro všechny záležitosti Boží i záležitosti královy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Synové Izraele podle jejich výčtu, předáci rodů, velitelé nad tisíci a nad sty a jejich správci, kteří sloužili králi ve všech věcech skupin, přicházející a vycházející měsíc co měsíc, po všechny měsíce roku; jeden oddíl měl dvacet čtyři tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Nad prvním oddílem v prvním měsíci byl Jášobeám, syn Zabdíelův; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Byl ze synů Peresových, předákem nad všemi veliteli armády v prvním měsíci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Nad oddílem druhého měsíce byl Dódaj Achóchijský; Miklót byl vévodou jeho oddílu; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Třetím velitelem armády v třetím měsíci byl Benajáš, syn vrchního kněze Jójady; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'To je ten Benajáš, hrdina mezi třiceti a nad třiceti; nad jeho oddílem byl jeho syn Amízábad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Čtvrtý ve čtvrtém měsíci byl Asáel, bratr Jóabův, a po něm jeho syn Zebadjáš; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Pátý v pátém měsíci byl Šamhút Jizrachejský; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Šestý v šestém měsíci byl Íra, syn Íkeše Tekójského; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Sedmý v sedmém měsíci byl Cheles Pelónský ze synů Efrajimových; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Osmý v osmém měsíci byl Sibekaj Chúšatský ze Zerachejců; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Devátý v devátém měsíci byl Abíezer Anatótský z Benjamínovců; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Desátý v desátém měsíci byl Mahraj Netófský ze Zerachejců; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Jedenáctý v jedenáctém měsíci byl Benajáš Pireatónský ze synů Efrajimových; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Dvanáctý ve dvanáctém měsíci byl Cheldaj Netófský z Otníela; jeho oddíl měl dvacet čtyři tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Nad izraelskými kmeny byli: nad Rúbenovci byl vévodou Elíezer, syn Zikrího; nad Šimeónovci Šefatjáš, syn Maakův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'nad Lévijci Chašabjáš, syn Kemúelův; nad Áronem Sádok;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'nad Judou Elíhú z Davidových bratrů; nad Isacharem Omrí, syn Michaelův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'nad Zabulónem Jišmajáš, syn Obadjášův; nad Neftalím Jerímót, syn Azríelův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'nad syny Efrajimovými Hóšea, syn Azazjášův; nad polovinou kmene Manasesova Jóel, syn Pedajášův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'nad polovinou Manasesa v Gileádu Jidó, syn Zekarjášův; nad Benjamínem Jaasíel, syn Abnérův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'nad Danem Azarel, syn Jerochámův. Toto jsou velitelé izraelských kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'David neuvedl počet dvacetiletých a mladších, neboť Hospodin řekl, že rozmnoží Izrael jako nebeské hvězdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Jóab, syn Serújin, začal sčítat, ale nedokončil to, neboť kvůli tomu dopadlo na Izrael rozhořčení. A tak se počet nedostal do knihy Letopisů krále Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Nad královskými sklady byl Azmávet, syn Adíelův. Nad sklady v zemi -- ve městech, na vesnicích a ve věžích byl Jónatan, syn Uzijášův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Nad ⌈venkovskými dělníky pro polní práci⌉ byl Ezrí, syn Kelúbův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Nad vinicemi byl Šimeí Rámatský; nad sklady vína, které jsou na vinicích, byl Zabdí Šifmejský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Nad olivovými háji a sykomorami, které jsou v Šefele, byl Baal–chanan Gederský. Nad sklady oleje byl Jóaš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Nad skotem pasoucím se v Šáronu byl Šitraj Šáronský. Nad skotem v údolích byl Šafat, syn Adlajův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Nad velbloudy byl Izmaelita Obíl. Nad oslicemi byl Jechdejáš Meronótský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Nad ovcemi byl Hagrejec Jazíz. Všichni tito byli předáky nad majetkem, který patřil králi Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jónatan, Davidův strýc, zkušený to člověk, byl rádcem a písařem. Jechíel, syn Chachmóního, byl s královskými syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achítofel byl královým rádcem. Chúšaj Arkijský byl královým přítelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Po Achítofelovi byl Jójada, syn Benajášův, a Ebjátar. Velitelem královy armády byl Jóab.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'David shromáždil do Jeruzaléma všechny izraelské velitele, velitele kmenů, velitele oddílů, kteří sloužili králi, velitele nad tisíci a velitele nad sty, předáky nad vším majetkem a dobytkem krále a jeho synů, spolu s dvorními úředníky, hrdiny, všechny zámožné lidi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Král David se postavil na nohy a řekl: Slyšte mě, mí bratři a můj lide! Měl jsem na srdci postavit dům odpočinutí pro truhlu Hospodinovy smlouvy, pro podnož nohou našeho Boha a udělal jsem přípravy ke stavbě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Bůh však mi řekl: Nestav dům pro mé jméno, neboť jsi bojovník a prolil jsi mnoho krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Hospodin, Bůh Izraele, si mě vyvolil z celého domu mého otce, abych byl navěky králem nad Izraelem. Vždyť Judu si vyvolil za vévodu a v domě Judově dům mého otce a mezi syny mého otce si oblíbil mě, aby mě ustanovil králem nad celým Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Ze všech synů -- a Hospodin mi dal mnoho synů -- si vyvolil mého syna Šalomouna, aby seděl na trůnu Hospodinova království nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Řekl mi: Tvůj syn Šalomoun, ten postaví můj dům a má nádvoří, neboť jeho jsem si vyvolil za syna a já budu jeho otcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Jeho království upevním navěky, jestliže bude pevný v tom, aby plnil mé příkazy a má nařízení jako dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nyní před očima celého Izraele, ⌈Hospodinova shromáždění,⌉ a před naším Bohem říkám: Zachovávejte a vyhledávejte všechny příkazy Hospodina, svého Boha, abyste zdědili tu dobrou zemi a dali ji do dědictví svým synům po vás navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'A ty, můj synu Šalomoune, poznávej Boha svého otce a služ mu celým srdcem a ochotnou duší, neboť Hospodin zkoumá každé srdce a zná každé zaměření myšlenek. Budeš–li jej hledat, dá se ti nalézt, opustíš–li ho, natrvalo tě odvrhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Nuže pohleď, že Hospodin si tě vyvolil, abys postavil dům pro svatyni. Posilni se a jednej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'David dal svému synu Šalomounovi plán předsíně, jeho budov, jeho pokladnic, jeho horních místností, jeho vnitřních pokojů a domu pro slitovnici,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'plán všeho, co měl na mysli: nádvoří Hospodinova domu, všechny okolní komory, pokladnice Božího domu a pokladnice svatých věcí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'oddíly kněží a lévitů, všechnu práci služby Hospodinova domu a všechny předměty služby Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Též váhu zlata na všechny zlaté předměty každé boho služby, váhu pro všechny stříbrné předměty a pro všechny předměty každé boho služby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'váhu zlata na zlaté svícny a jejich zlaté lampy s váhou pro každý svícen a jeho lampy i na stříbrné svícny s váhou pro svícen a jeho lampy podle služby každého svícnu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'váhu zlata na stoly pro předkladné chleby pro každý stůl, stříbra na stříbrné stoly,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'na vidlice, misky a konve z čistého zlata, váhu zlatých pohárů pro každý pohár a váhu stříbrných pohárů pro každý pohár,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'váhu přečištěného zlata na kadidlový oltář a zlata pro napodobeninu vozu cherubů s roztaženými křídly, zastírajícími truhlu Hospodinovy smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'To všechno bylo písemně, protože Hospodinova ruka byla nade mnou; on mi dal pochopit plán celého díla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'David řekl svému synu Šalomounovi: Posilni se, buď odvážný a jednej. Neboj se a neděs se, neboť Hospodin Bůh, můj Bůh, je s tebou. Nenechá tě klesnout a neopustí tě, dokud nedokončíš všechnu práci pro službu Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Zde jsou oddíly kněží a lévitů pro každou službu Božího domu; budou s tebou při každé práci, ke všemu ochotní a moudří, ke každé službě, a také předáci a všechen lid pro každý tvůj záměr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Nato král David řekl celému shromáždění: Můj syn Šalomoun, jehož jediného vyvolil Bůh, je mladý a útlý a dílo je veliké, neboť to není hrad pro člověka, ale pro Hospodina Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, '⌈Ze vší své síly⌉ jsem připravil pro dům svého Boha zlato na věci zlaté, stříbro na stříbrné, bronz na bronzové, železo na železné, dřevo na dřevěné, kameny karneolové a pro vsazování kameny antimonové a pestrobarevné, všelijaké drahokamy i množství mramoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Navíc, protože jsem si oblíbil dům svého Boha, z osobního vlastnictví zlata a stříbra jsem dal pro dům svého Boha kromě všeho, co jsem připravil pro dům svatyně:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Tři tisíce talentů zlata, zlata z Ofíru, sedm tisíc talentů přečištěného stříbra pro potažení stěn domů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'zlato na věci zlaté, stříbro na stříbrné a pro všechnu práci konanou řemeslníky. Kdo se dnes dobrovolně rozhodne otevřít ruku pro Hospodina?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Dobrovolně se rozhodli předáci rodů, velitelé izraelských kmenů, ⌈velitelé nad tisíci⌉ a nad sty a předáci nad prací pro krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Pro službu Božího domu dali pět tisíc talentů zlata a deset tisíc darejků, deset tisíc talentů stříbra, osmnáct tisíc talentů bronzu a sto tisíc talentů železa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Ten, kdo měl draho kamy, dal je do pokladu Hospodinova domu do správy Geršónovce Jechíela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Lid se radoval z jejich dobrovolného rozhodnutí, neboť se rozhodli dát Hospodinu dobrovolně a z celého srdce; také král David se převelice radoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Nato David dobrořečil Hospodinu před zraky ⌈celého shromáždění.⌉ David řekl: Požehnaný buď, Hospodine, Bože Izraele, našeho otce, od věků až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tobě, Hospodine, patří velikost, udatnost, sláva, síla i nádhera, ano všechno, co je na nebesích i na zemi. Tobě, Hospodine, patří království, vyvýšený jsi jako hlava nade všechno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, '⌈Bohatství i sláva⌉ jsou od tebe, ty vládneš nade vším, ve tvé ruce je ⌈síla a udatnost,⌉ ve tvé ruce je učinit velkým a posílit každého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nyní, Bože náš, ti vzdáváme díky a chválíme tvé slavné jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Vždyť kdo jsem já a kdo je můj lid, že bychom ⌈byli schopni⌉ ⌈se k něčemu takovému dobrovolně rozhodnout?⌉ Vždyť od tebe je všechno a ze tvé ruky jsme ti dali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Vždyť jsme před tebou ⌈hosté a příchozí⌉ jako všichni naši otcové; jako stín jsou naše dny na zemi, není naděje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Hospodine, Bože náš, celé toto bohatství, které jsme připravili, abychom ti postavili dům pro tvé svaté jméno, je ze tvé ruky, to všechno ti patří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Vím, můj Bože, že ty zkoumáš srdce a oblibuješ přímost. V přímosti svého srdce jsem se rozhodl dobrovolně dát toto všechno a nyní jsem s radostí viděl, že tvůj lid, který je zde, se rozhodl dát pro tebe dobrovolně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Hospodine, Bože Abrahama, Izáka a Izraele, našich otců, zachovej to navěky jako zaměření myšlenek srdce svého lidu a ⌈zaměř jejich srdce k sobě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'A mému synu Šalomounovi dej neporušené srdce, aby zachovával tvé příkazy, tvá svědectví a ustanovení, plnil to všechno a postavil ten hrad, pro který jsem udělal přípravy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Potom David řekl celému shromáždění: Dobrořečte Hospodinu, svému Bohu. Celé shromáždění tedy dobrořečilo Hospodinu, Bohu svých otců, poklekali a klaněli se Hospodinu a králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Druhý den obětovali Hospodinu obětní hody a přinášeli Hospodinu zápalné oběti -- tisíc býčků, tisíc beranů a tisíc beránků; též jejich litých obětí a obětních hodů bylo množství za celý Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'V onen den jedli a pili před Hospodinem s velikou radostí. Potom ustanovili podruhé Šalomouna, syna Davidova, králem a pomazali jej Hospodinu za vévodu a Sádoka za kněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Šalomoun seděl na Hospodinově trůnu jako král po svém otci Davidovi, dařilo se mu a celý Izrael ho poslouchal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Všichni předáci, hrdinové i všichni synové krále Davida se poddali králi Šalomounovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Hospodin učinil Šalomouna velmi velkým v očích celého Izraele a dal mu královský majestát, jaký před ním neměl žádný král nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'David, syn Jišajův, kraloval nad celým Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Doba, po kterou kraloval nad Izraelem, byla čtyřicet let. V Chebrónu kraloval sedm let a v Jeruzalémě kraloval třicet tři let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'I zemřel v utěšených šedinách, sytý dnů, bohatství a slávy. Po něm se stal králem jeho syn Šalomoun.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, '⌈První i poslední⌉ činy krále Davida jsou zapsány v letopisech vidoucího Samuela, v letopisech proroka Nátana a v letopisech vidoucího Gáda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'spolu se ⌈všemi jeho královskými a udatnými činy a událostmi té doby,⌉ které postihly jej, Izrael a všechna království země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Šalomoun, syn Davidův, ⌈si počínal ve svém království zmužile,⌉ neboť Hospodin, jeho Bůh, byl s ním a učinil ho velmi velkým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Šalomoun promluvil k celému Izraeli -- k velitelům nad tisíci a nad sty, k soudcům a ke všem předákům celého Izraele, předákům rodů --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'a pak šel Šalomoun a celé to shromáždění s ním na návrší v Gibeónu, neboť tam byl Boží stan setkávání, který udělal v pustině Mojžíš, otrok Hospodinův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Ale Boží truhlu přenesl David z Kirjat–jearímu na místo, které pro ni David připravil, když pro ni postavil v Jeruzalémě stan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Bronzový oltář, který udělal Besaleel, syn Urího, syna Chúrova, umístil před Hospodinův příbytek a tam se Šalomoun i to shromáždění dotazovali Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Šalomoun tam vystoupil před Hospodina k bronzovému oltáři, který byl ve stanu setkávání, a přinesl na něm tisíc zápalných obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'V oné noci se ukázal Šalomounovi Bůh a řekl mu: Žádej, co ti mám dát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Šalomoun Bohu řekl: Ty jsi prokázal mému otci Davidovi velké milosrdenství a ustanovil jsi mě po něm králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Nyní, Hospodine Bože, ať se ukáže jako spolehlivé tvé slovo vůči mému otci Davidovi, neboť ty jsi mě ustanovil králem nad lidem početným jako prach země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Nuže, dej mi moudrost a poznání, abych mohl ⌈vycházet před tímto lidem a vcházet,⌉ neboť kdo dokáže soudit tento tvůj velký lid?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Bůh Šalomounovi řekl: Protože jsi měl toto v srdci a nežádal jsi bohatství, poklady a slávu, ani smrt těch, kteří tě nenávidí, ba ani dlouhý život jsi nežádal, ale žádal jsi moudrost a poznání, abys dokázal soudit můj lid, nad nímž jsem tě ustanovil králem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'moudrost a poznání ti budou dány, ale dám ti také bohatství, poklady a slávu, jakou neměli králové před tebou a ani nebude mít žádný po tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Šalomoun pak odešel od stanu setkávání na návrší v Gibeónu do Jeruzaléma a kraloval nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Šalomoun nashromáždil vozy a koně a měl tisíc čtyři sta vozů a dvanáct tisíc jezdeckých koní. Umístil je ve městech pro vozy a u krále v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Král učinil stříbro a zlato v Jeruzalémě tak hojné jako kamení a cedry tak početné jako sykomory v Šefele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Koně, které měl Šalomoun, se dováželi z Egypta a z Kue. Královští obchodníci je brali z Kue za pevnou cenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Válečný vůz se z Egypta dovážel za šest set šekelů stříbra a kůň za sto padesát šekelů. Jejich prostřednictvím se tak vyváželi všem králům chetejským a aramejským.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, 'I řekl si Šalomoun, že postaví dům pro Hospodinovo jméno a svůj královský dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Šalomoun odpočítal sedmdesát tisíc nosičů a osmdesát tisíc kameníků v horách a tři tisíce šest set dozorců nad nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Šalomoun vzkázal týrskému králi Chúramovi: Jako ses zachoval vůči mému otci Davidovi a posílal jsi mu cedry, aby si postavil dům k bydlení, tak se zachovej i vůči mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Hle, chci postavit dům pro jméno Hospodina, svého Boha, abych mu jej zasvětil, aby se před ním pálilo vonné kadidlo, aby byly stále předkladné chleby i zápalné oběti ráno i večer, o sobotách, novoluních a svátcích Hospodina, našeho Boha; to je navěky nařízením pro Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Dům, který chci postavit, musí být velký, protože náš Bůh je větší nad všechny bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Kdo ⌈je schopen⌉ postavit mu dům, když nebesa ani nebesa nebes jej ne mohou pojmout? Kdo jsem já, že bych mu měl postavit dům, kromě místa, kde by se mohlo před ním pálit kadidlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Pošli mi nyní muže zručného v práci se zlatem, stříbrem, bronzem, železem, přízí purpurovou, karmínovou a modrou, znalého vyřezávat řezby, aby pracoval se zručnými muži, kteří jsou u mě v Judsku a v Jeruzalémě, které připravil můj otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Pošli mi dřevo cedrové, cypřišové a algumínové z Libanonu, protože vím, že tvoji otroci umějí kácet libanonské stromy. Hle, moji otroci budou s tvými otroky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'aby připravili množství dřeva, neboť dům, který chci postavit, musí být velký a obdivuhodný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Hle, pro dřevo rubce, kteří budou kácet stromy, pro tvé otroky, dám dvacet tisíc kórů drcené pšenice, dvacet tisíc kórů ječmene, dvacet tisíc batů vína a dvacet tisíc batů oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Týrský král Chúram odpověděl písemně a vzkázal Šalomounovi: Protože Hospodin miluje svůj lid, ustanovil tě nad ním králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Chúram dále řekl: ⌈Požehnán buď Hospodin, Bůh Izraele,⌉ který učinil nebesa i zemi, že dal králi Davidovi moudrého, ⌈rozumného a chápavého⌉ syna, jenž postaví dům pro Hospodina a svůj královský dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Nuže, posílám muže zručného a chápavého, Chúrama abího,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'syna ženy z dcer Danových, jehož otec byl Týřan, znalého pracovat se zlatem a stříbrem, bronzem, železem, kamenem i dřevem, přízí purpurovou, modrou, mořským hedvábím a látkou karmínovou i vyřezávat jakoukoliv řezbu a ztvárnit jakýkoliv nápad. Co se mu předloží, bude dělat se zručnými muži tvými a se zručnými muži mého pána, tvého otce Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Nyní ať můj pán pošle svým otrokům pšenici, ječmen, olej a víno, jak řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'My budeme kácet stromy z Libanonu zcela podle tvé potřeby a přivážet ti je na vorech po moři do Jafy a ty je budeš odvážet do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Šalomoun spočítal všechny cizince, kteří byli v izraelské zemi -- to bylo po sčítání, kterým je spočítal jeho otec David; bylo jich sto padesát tři tisíc šest set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Ustanovil z nich sedmdesát tisíc nosičů a osmdesát tisíc kameníků v horách a tři tisíce šest set dozorců, aby nutili lid pracovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Šalomoun začal stavět Hospodinův dům v Jeruzalémě na hoře Mórija, kde se Hospodin ukázal jeho otci Davidovi, na místě, které David připravil, na humně Ornána Jebúsejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Začal stavět druhého dne druhého měsíce ve čtvrtém roce svého kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Toto jsou základy, které Šalomoun položil pro stavbu Božího domu: délka v loktech podle původní míry šedesát loket a šířka dvacet loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Předsíň v průčelí chrámového domu ⌈byla dlouhá dvacet loket v průčelí široké strany domu;⌉ výška byla ⌈sto dvacet.⌉ Uvnitř ji potáhl čistým zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Velký dům obložil cypřišovým dřevem a obložil ho ryzím zlatem; na to dal palmové ozdoby a řetězy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Dům obložil drahokamy, aby byl slavný; zlato bylo zlato parvajimské.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Dům, trámy a prahy, jeho stěny a dveře obložil zlatem a na stěny vyryl cheruby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Pak udělal dům nejsvětějšího místa; jeho délka byla dvacet loket v průčelí široké strany domu a jeho šířka dvacet loket. Obložil ho ryzím zlatem, šesti sty talenty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Hřebíky vážily padesát šekelů zlata. Též horní místnosti obložil zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'V domě nejsvětějšího místa udělal dva cheruby, umělecké dílo; potáhli je zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Délka křídel cherubů byla dvacet loket. Jedno křídlo o pěti loktech se dotýkalo stěny domu a druhé křídlo o pěti loktech se dotýkalo křídla druhého cheruba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Křídlo druhého cheruba o pěti loktech se dotýkalo stěny domu a druhé křídlo o pěti loktech se dotýkalo křídla prvního cheruba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Roztažená křídla těchto cherubů měřila dvacet loket. Stáli na nohou a jejich tváře byly obráceny k domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Udělal oponu z modré, purpurové a karmínové příze a mořského hedvábí a vyhotovil na ni cheruby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Před domem udělal dva sloupy vysoké třicet pět loket a hlavici, která byla na obou vrcholech, vysokou pět loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Udělal řetězy jako ve svatyni a dal je na vrchol sloupů. Udělal sto granátových jablek a dal je na řetězy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Sloupy postavil před chrám, jeden napravo a druhý nalevo. Pravý nazval Jakín a levý Bóaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Udělal též bronzový oltář, dvacet loket dlouhý, dvacet loket široký a deset loket vysoký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Potom udělal odlité moře, deset loket bylo od okraje po okraj, dokola okrouhlé, pět loket bylo vysoké a obepnula ho dokola šňůra třiceti loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Kolem dokola pod ním ho obklopovalo zpodobení býků, deset na loket, kolem dokola moře. Býci byli ve dvou řadách, odlití při odlévání moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Stálo na dvanácti býcích: Tři byli obráceni na sever, tři byli obráceni na západ, tři byli obráceni na jih a tři byli obráceni na východ. Moře bylo nahoře na nich a všechny jejich zadky směřovaly dovnitř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Bylo na dlaň silné a jeho okraj byl udělán jako okraj poháru, do liliovitého květu. Pojalo ⌈tři tisíce batů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Udělal též deset nádrží k umývání a dal jich pět napravo a pět nalevo. V nich oplachovali předměty pro zápalnou oběť, ale pro umývání kněží bylo moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Udělal deset zlatých svícnů podle nařízení pro ně a dal je do chrámu, pět napravo a pět nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Udělal deset stolů a umístil je do chrámu, pět napravo a pět nalevo. Udělal též sto zlatých misek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Udělal nádvoří kněží a velké nádvoří i dveře k nádvoří a jejich křídla potáhl bronzem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Moře dal na pravou stranu, z jihovýchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Chúram též udělal hrnce, lopaty a misky. Tak Chúram dodělal práci, kterou konal pro krále Šalomouna na Božím domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Dva sloupy a kulovité hlavice, které byly na vrcholu obou sloupů, dvojí mřížování, aby zakrývalo obě kulovité hlavice, které byly na vrcholu sloupů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'čtyři sta granátových jablek pro dvoje mřížování, dvě řady granátových jablek pro jedno mřížování, aby zakrývalo obě kulovité hlavice, které byly na vrchu sloupů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'deset podstavců a deset nádrží na podstavce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'jedno moře a dvanáct býků pod ním,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'hrnce, lopaty a vidlice. Všechny předměty udělal Chúram abí králi Šalomounovi z leštěného bronzu pro Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Král je odlil do hliněných forem v Jordánské rovině mezi Sukótem a Saretánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Všech těchto předmětů udělal Šalomoun tak veliké množství, že váha bronzu se nedala zjistit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Šalomoun udělal všechny předměty, které byly v Božím domě: zlatý oltář, stoly a na nich předkladné chleby;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'svícny a jejich lampy z čistého zlata, aby hořely podle nařízení před svatyní;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'květy, lampy a kleště ze zlata, nejčistšího zlata;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'nůžky na knot, misky, kadidlové pánvičky, pánvičky na uhlíky z čistého zlata a dveře domu: jejich vnitřní křídla do nejsvětějšího místa a křídla chrámového domu byla ze zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Tak byla dokončena všechna práce, kterou Šalomoun dělal na Hospodinově domě. Pak Šalomoun přinesl svaté věci svého otce Davida -- stříbro, zlato a všechny předměty -- a dal je do pokladnice Božího domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Potom svolal Šalomoun izraelské starší, všechny předáky pokolení a předáky rodů synů Izraele do Jeruzaléma, aby přenesli truhlu Hospodinovy smlouvy z Města Davidova, to je ze Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Shromáždili se tedy ke králi všichni izraelští muži ve svátek, to je v měsíc sedmý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Když přišli všichni izraelští starší, lévité vzali truhlu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'a přenesli truhlu. Stan setkávání a všechny svaté předměty, které byly ve stanu, ty přenesli lévijští kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Král Šalomoun a celá pospolitost Izraele, která se k němu sešla, byli před truhlou a obětovali brav a skot, který ne mohl být pro množství spočítán ani sečten.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Kněží přinesli truhlu Hospodinovy smlouvy na její místo do svatyně domu, na nejsvětější místo, pod křídla cherubů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Protože cherubové měli křídla roztažená nad místem pro truhlu, zakrývali cherubové odshora truhlu i její tyče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Tyče byly dlouhé, takže konce tyčí vyčnívající z truhly byly vidět před svatyní, ale nebyly vidět ven. Jsou tam až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'V truhle byly pouze dvě desky, které tam Mojžíš dal na Chorébu, když Hospodin uzavřel smlouvu se syny Izraele, potom, co vyšli z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'I stalo se, když vyšli kněží ze ⌈svatého místa⌉ -- všichni kněží, co tam byli, se totiž posvětili ⌈bez ohledu na rozdělení do skupin⌉ --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'všichni lévijští zpěváci -- Asaf, Héman, Jedútún a jejich synové a bratři oblečení do mořského hedvábí s činely, harfami a lyrami stáli na východ od oltáře a s nimi sto dvacet kněží troubících na trubky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'I stalo se, že trubači a zpěváci společně jednohlasně zvučeli, vzdávali díky a chválili Hospodina; a když pozvedli hlas s trubkami, činely a dalšími hudebními nástroji a chválili Hospodina, že je dobrý, navěky je jeho milosrdenství, dům, Hospodinův dům, naplnil oblak,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'takže kněží nemohli kvůli tomu oblaku stát a sloužit, protože Hospodinova sláva naplnila Boží dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tehdy Šalomoun řekl: Hospodin pravil, že bude přebývat v husté temnotě:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Postavil jsem ti dům k přebývání, sídlo, kde bys pobýval navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Pak se obrátil král a požehnal celému shromáždění Izraele; celé shromáždění Izraele stálo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Řekl: Požehnán buď ⌈Hospodin, Bůh Izraele,⌉ který svými ústy promluvil k mému otci Davidovi a svou rukou to naplnil. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Ode dne, kdy jsem vyvedl svůj lid z egyptské země, jsem nevyvolil žádné město mezi všemi izraelskými kmeny pro stavbu domu, aby tam přebývalo mé jméno, a nevyvolil jsem nikoho, aby byl vévodou nad mým lidem Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Až jsem vyvolil Jeruzalém, aby tam přebývalo mé jméno, a vyvolil jsem Davida, aby byl nad mým lidem Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Můj otec David měl na srdci postavit dům pro jméno Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Hospodin však mému otci Davidovi řekl: Když jsi měl na srdci postavit dům pro mé jméno, dobře jsi udělal, že jsi to měl na srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Ovšem ty nepostavíš ten dům, nýbrž tvůj syn, který vzejde z tvých beder, ten postaví dům pro mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Hospodin naplnil své slovo, které promluvil. Povstal jsem po svém otci Davidovi a usedl jsem na izraelský trůn, jak Hospodin promluvil. Postavil jsem dům pro jméno Hospodina, Boha Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'a postavil jsem tam truhlu, v níž je Hospodinova smlouva, kterou uzavřel se syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Nato se před celým shromážděním Izraele postavil před Hospodinův oltář a vztáhl své dlaně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Šalomoun totiž udělal bronzové pódium a dal ho doprostřed nádvoří; bylo pět loket dlouhé, pět loket široké a tři lokte vysoké. Postavil se na ně, před celým shromážděním Izraele poklekl na kolena, vztáhl dlaně k nebesům');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'a řekl: Hospodine, Bože Izraele, není Bůh jako ty na nebesích ani na zemi, který zachovává smlouvu a milosrdenství svým otrokům, kteří chodí před tebou celým svým srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Ty jsi zachoval svému otroku, mému otci Davidovi, to, cos mu řekl; promluvil jsi svými ústy a naplnil jsi to svou rukou, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nyní, Hospodine, Bože Izraele, zachovej svému otroku, mému otci Davidovi, to, cos mu řekl: Nebude ti vyhlazen přede mnou ten, kdo by seděl na izraelském trůnu, pokud ovšem tvoji synové budou dbát na svoji cestu a chodit podle mého zákona tak, jak jsi chodil přede mnou ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nyní, Hospodine, Bože Izraele, kéž se ukáže jako spolehlivé tvé slovo, které jsi promluvil ke svému otroku Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Což opravdu bude sídlit Bůh s člověkem na zemi? Vždyť nebesa ani nebesa nebes tě ne mohou pojmout, tím méně tento dům, který jsem postavil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'A přece pohleď, Hospodine, můj Bože, na modlitbu svého otroka a na jeho úpěnlivou prosbu a vyslyš volání a modlitbu, kterou se tvůj otrok před tebou modlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Kéž jsou tvé oči otevřené k tomuto domu dnem i nocí, k místu, o kterém jsi řekl, že tam položíš své jméno. Vyslyš modlitbu, kterou se tvůj otrok bude modlit na tomto místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Vyslyš úpěnlivé prosby svého otroka a svého lidu Izraele, když se bude modlit na tomto místě; vyslyš z místa, kde sídlíš, z nebes, vyslyš a odpusť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Jestliže někdo zhřeší proti svému bližnímu a ten na něm vymůže přísahu, aby přísahal, on přijde a vysloví přísahu před tvým oltářem v tomto domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'uslyš z nebes, konej a zjednej právo svým otrokům: Odplať ničemovi a uval jeho cestu na jeho hlavu a spravedlivého prohlaš za spravedlivého a dej mu podle jeho spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Jestliže bude tvůj lid Izrael poražen od nepřítele, protože proti tobě zhřeší, ale pak se obrátí, vzdají chválu tvému jménu, budou se modlit a prosit před tebou v tomto domě o smilování,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'uslyš z nebes, odpusť hřích svého lidu Izraele a přiveď je zpět do země, kterou jsi dal jim a jejich otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Jestliže budou uzavřena nebesa a nebude déšť, protože proti tobě zhřeší, ale pak se budou na tomto místě modlit, vzdají chválu tvému jménu a odvrátí se od svého hříchu, protože je pokoříš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'uslyš v nebesích, odpusť hřích svých otroků a svého lidu Izraele, až je vyučíš dobré cestě, po níž by měli jít, a dej déšť na svou zemi, kterou jsi dal svému lidu do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Jestliže bude v zemi hlad, jestliže bude mor, obilná rez a sněť, jestliže budou kobylky arbe či kobylky chasíl, jestliže mu v zemi, v některém z jeho měst způsobí jeho nepřátelé soužení, ať je to jakákoliv rána, jakákoliv nemoc,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'každou modlitbu a každou úpěnlivou prosbu, která vzejde od kteréhokoliv člověka, z celého tvého lidu Izraele -- znají přece každý svou ránu a svou bolest -- když vztáhnou své dlaně k tomuto domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'vyslyš z nebes, sídla, kde pobýváš, odpusť a dej každému podle všech jeho cest, jak znáš jeho srdce. Vždyť ty jediný znáš srdce lidských synů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'aby se tě báli a chodili po tvých cestách po všechny dny, co budou naživu na povrchu země, kterou jsi dal našim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Také když cizinec, který není ze tvého lidu Izraele, přijde z daleké země kvůli tvému velkému jménu, tvé mocné ruce a tvé vztažené paži, přijde a bude se modlit v tomto domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'vyslyš z nebes, sídla, kde pobýváš, a učiň všechno, za co k tobě bude volat ten cizinec, aby všechny národy země poznaly tvé jméno, bály se tě jako tvůj lid Izrael a poznaly, že tento dům, který jsem postavil, se nazývá tvým jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Když tvůj lid vytáhne do boje proti svým nepřátelům, cestou, kterou je pošleš, a budou se modlit k tobě směrem k tomuto městu, které sis vyvolil, a domu, který jsem postavil pro tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'vyslyš z nebes jejich modlitbu a jejich úpěnlivou prosbu a zjednej jim právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Když proti tobě zhřeší -- neboť není člověk, který by nezhřešil -- budeš se na ně hněvat, vydáš je nepříteli a jejich věznitelé je odvedou do země vzdálené či blízké,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'ale pak změní své smýšlení v zemi, kam byli odvedeni, obrátí se, budou tě v zemi svého zajetí prosit o smilování slovy: Zhřešili jsme, spáchali jsme zlo a jednali jsme ničemně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'a jestliže se k tobě obrátí celým svým srdcem a celou svou duší v zemi svých věznitelů, kteří je zajali, budou se modlit směrem ke své zemi, kterou jsi dal jejich otcům, k městu, které sis vyvolil, a k domu, který jsem postavil pro tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'vyslyš z nebes, sídla, kde pobýváš, jejich modlitbu a jejich úpěnlivou prosbu, zjednej jim právo a odpusť svému lidu, který proti tobě zhřešil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Nechť jsou nyní, můj Bože, tvé oči otevřené a tvé uši pozorné k modlitbě z tohoto místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Nyní povstaň, Hospodine Bože, na místo svého odpočinku, ty i truhla tvé moci. Tvoji kněží, Hospodine Bože, ať obléknou záchranu a tvoji věrní ať se radují z dobra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Hospodine Bože, neodmítni svého pomazaného, pamatuj na ⌈zbožné skutky ⌉ svého otroka Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Když se Šalomoun domodlil, sestoupil oheň z nebes, strávil zápalnou oběť i obětní hod a Hospodinova sláva naplnila dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Kněží nemohli vejít do Hospodinova domu, protože Hospodinova sláva naplnila Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Když všichni synové Izraele viděli, jak sestoupil oheň a Hospodinovu slávu na domě, poklekli na dlažbu tváří k zemi, klaněli se a vzdávali Hospodinu díky, protože je dobrý a navěky je jeho milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Nato král a všechen lid obětovali před Hospodinem oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Král Šalomoun obětoval jako oběti dvacet dva tisíc býků a sto dvacet tisíc ovcí. Tak král a všechen lid zasvětili Boží dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Kněží stáli na místech své služby i lévité s hudebními nástroji pro Hospodina, které udělal král David pro vzdávání díků Hospodinu, že navěky je jeho milosrdenství -- jak chválil skrze ně David. Kněží před nimi troubili a všichni Izraelci stáli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Šalomoun posvětil střed nádvoří, které je před Hospodinovým domem, neboť tam připravil zápalné oběti a tučné části pokojných obětí, protože bronzový oltář, který Šalomoun udělal, nebyl schopen pojmout zápalné a přídavné oběti i tučné části pokojných obětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Šalomoun a s ním celý Izrael, převeliké shromáždění lidí, kteří přišli od Lebo–Chamátu až po egyptský potok, slavil v ten čas svátek po sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Osmého dne se konalo shromáždění, neboť posvěcení oltáře slavili sedm dní a svátek dalších sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Dvacátého třetího dne sedmého měsíce propustil lid a oni šli ke svým stanům radostně a s veselou myslí nad dobrem, které Hospodin učinil Davidovi, Šalomounovi a svému lidu Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Tak Šalomoun dokončil Hospodinův dům i královský palác; zdárně vykonal všechno, co přišlo na jeho srdce, aby udělal v Hospodinově domě a ve svém paláci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Hospodin se ukázal Šalomounovi v noci a řekl mu: Vyslyšel jsem tvou modlitbu a vyvolil jsem toto místo za obětní dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Jestliže uzavřu nebesa a nebude déšť, jestliže přikáži kobylkám, aby požíraly zemi, či pokud pošlu na svůj lid mor,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'ale pak se můj lid, který se nazývá mým jménem, pokoří, budou se modlit, hledat moji tvář a odvrátí se od svých zlých cest, vyslyším z nebes, odpustím jejich hřích a uzdravím jejich zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Moje oči budou otevřené a moje uši pozorné k modlitbě z tohoto místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Nyní jsem vyvolil a posvětil tento dům, aby tam navěky přebývalo mé jméno. Mé oči a mé srdce tam budou obráceny po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'A co se tebe týče, jestliže budeš přede mnou chodit, jako chodil tvůj otec David, a činit všechno, co jsem ti přikázal, a budeš zachovávat má ustanovení a nařízení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'upevním tvůj královský trůn, tak jak jsem uzavřel smlouvu s tvým otcem Davidem se slovy: Nebude ti vyhlazen muž vládnoucí nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Jestliže se však odvrátíte a opustíte má ustanovení a mé příkazy, které jsem vám předložil, půjdete a budete sloužit jiným bohům a klanět se jim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'vyrvu je ze své země, kterou jsem jim dal, a tento dům, který jsem posvětil pro své jméno, od sebe odvrhnu a učiním jej pořekadlem a posměškem mezi všemi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'A nad tímto domem, který byl vyvýšený, se každý, kdo bude procházet kolem něj, zhrozí a zeptá se: Proč tohle Hospodin provedl této zemi a tomuto domu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'A bude se odpovídat: Protože opustili Hospodina, Boha svých otců, který je vyvedl z egyptské země, chytili se jiných bohů, klaněli se jim a sloužili jim, proto na ně přivedl všechno toto zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'I stalo se po dvaceti letech, kdy Šalomoun stavěl dům Hospodinův a dům svůj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'že Šalomoun vybudoval města, která mu dal Chúram, a usídlil tam syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Pak vytáhl Šalomoun na Chamát–sóbu a zmocnil se jí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Postavil Tadmór v pustině a všechna města pro sklady, které postavil v Chamátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Postavil Bét–chorón Horní a Bét–chorón Dolní, opevněná města s hradbami, vraty a závorami,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Baalat a všechna města pro sklady, které patřily Šalomounovi, všechna města pro vozbu, města pro koně a všechno, co si přál Šalomoun a toužil postavit v Jeruzalémě, na Libanonu a na celém území své vlády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Všechen lid, který zbyl z Chetejců, Emorejců, Perizejců, Chivejců a Jebúsejců, z těch, kteří ne byli z Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'jejich syny, kteří po nich zbyli v zemi, které synové Izraele nezničili, Šalomoun povolal na nucené práce, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Ale ze synů Izraele nevzal Šalomoun otroky pro svou práci, protože byli bojovníky, jeho kapitány, veliteli jeho vozby a jeho jezdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Toto byla ustanovená knížata, která měl král Šalomoun: Dvě stě padesát těch, kteří panovali nad lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Faraonovu dceru vyvedl Šalomoun z Města Davidova do domu, který jí postavil, protože si řekl: Moje žena nemůže bydlet v domě izraelského krále Davida, neboť místa, na která se dostala Hospodinova truhla, jsou svatá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Tehdy přinesl Šalomoun Hospodinu zápalné oběti na Hospodinově oltáři, který postavil před chrámovou předsíní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Podle každodenního určení pro přinášení obětí, jak přikázal Mojžíš o sobotách, o novoluních a o svátcích třikrát za rok: ve svátek nekvašených chlebů, svátek týdnů a svátek stánků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Podle nařízení svého otce Davida ustanovil skupiny kněží do jejich služby a lévity do jejich služby, aby chválili Hospodina a sloužili naproti kněžím podle každodenního určení, a také vrátné do jejich skupin ⌈pro každou bránu,⌉ neboť to byl příkaz Davida, muže Božího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'V žádné věci neustoupili od královských příkazů o knězech a lévitech a o pokladech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Tak byla uskutečněna všechna Šalomounova práce ode dne, kdy byly položeny základy Hospodinova domu až do úplného dokončení Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tehdy se Šalomoun vydal do Esjón–geberu a do Elótu na břehu moře v edómské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Chúram mu poslal po svých otrocích lodě a otroky znalé moře a připluli s Šalomounovými otroky do Ofíru, vzali odtamtud čtyři sta padesát talentů zlata a přivezli králi Šalomounovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Když se královna ze Šeby doslechla zprávy o Šalomounovi, přišla ho do Jeruzaléma vyzkoušet hádankami. Přijela s ohromným majetkem; velbloudi nesli balzámy, množství zlata a drahokamy. Přišla k Šalomounovi a mluvila s ním o všem, co ⌈měla na srdci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Šalomoun jí od pověděl na všechny její věci; Šalomounovi nebylo nic skryto, na co by jí ne od pověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Když královna ze Šeby viděla Šalomounovu moudrost a dům, který postavil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'jídlo na jeho stole, sídlo jeho otroků, ⌈obsluhu jeho služebníků⌉ a jejich oděv, jeho číšníky a jejich oděv i jeho ⌈zápalné oběti, které přinášel⌉ v Hospodinově domě, byla bez dechu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Řekla králi: To, co jsem slyšela ve své zemi o tvých slovech a tvé moudrosti, je pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Nevěřila jsem jejich zprávám, dokud jsem nepřišla a ne viděla jsem to na vlastní oči. Hle, nebyla mi oznámena ani polovina z velikosti tvé moudrosti. Předčil jsi zvěsti, které jsem slyšela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Šťastní jsou tvoji muži a šťastní jsou tito tvoji otroci, kteří ti stále slouží a naslouchají tvé moudrosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Ať je požehnán Hospodin, tvůj Bůh, který si tě oblíbil a ustanovil tě na svůj trůn za krále Hospodinu, tvému Bohu. Protože si tvůj Bůh zamiloval Izrael, aby ho navěky upevnil, ustanovil tě nad nimi za krále, abys vykonával právo a spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Pak dala králi sto dvacet talentů zlata, velké množství balzámů a drahokamů. ⌈ Již nikdy nebylo přivezeno takové množství balzámu⌉ jako dala králi Šalomounovi královna ze Šeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Také Chúramovi otroci a Šalomounovi otroci, kteří přivezli zlato z Ofíru, přivezli algumínové dřevo a drahokamy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Král udělal z algumínového dřeva schodiště Hospodinova domu a královského paláce i lyry a harfy pro zpěváky. Nikdy předtím nebylo v judské zemi vidět nic takového.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Král Šalomoun dal královně ze Šeby všechno, po čem toužila a oč požádala, více nežli ona přinesla králi. Pak se svými otroky odešla do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Váha zlata, které přivezli Šalomounovi v jednom roce, byla šest set šedesát šest talentů zlata,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'kromě toho, co přivezli kupci a obchodníci. Všichni arabští králové a místodržitelé země přiváželi Šalomounovi zlato a stříbro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Král Šalomoun udělal dvě stě velkých štítů z tepaného zlata -- šest set šekelů tepaného zlata dal na jeden velký štít');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'a tři sta malých štítů z tepaného zlata -- tři sta šekelů zlata dal na jeden malý štít. Král je dal do domu Libanonského lesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Král udělal též velký trůn ze slonoviny a potáhl ho čistým zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'K trůnu vedlo šest schodů a k trůnu byla připojena zlatá podnož. Z jedné i druhé strany sedadla byla opěradla. Vedle opěradel stáli dva lvi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Stálo tam dvanáct lvů na šesti schodech z jedné i druhé strany. Takový trůn nebyl zhotoven v žádném království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Všechny nádoby na nápoje krále Šalomouna byly zlaté a všechny nádoby domu Libanonského lesa byly z čistého zlata. Nic nebylo ze stříbra, to bylo ve dnech Šalomounových považováno za nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Král měl lodě, které pluly do Taršíše s Chúramovými otroky. Jednou za tři roky taršíšské lodě připlouvaly a přivážely zlato, stříbro, slonovinu, opice a paviány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Tak král Šalomoun převyšoval všechny krále země bohatstvím a moudrostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Všichni králové země vyhledávali Šalomounovu přítomnost, aby naslouchali jeho moudrosti, kterou mu Bůh vložil do srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Přinášeli každý svůj dar -- stříbrné a zlaté předměty, pláště, zbraně a balzámy, koně a mezky, a to rok co rok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Šalomoun měl čtyři tisíce stájí pro koně a vozy a dvanáct tisíc jezdeckých koní. Umístil je ve městech pro vozy a ⌈u krále⌉ v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Tak vládl nad všemi králi od řeky Eufratu až k pelištejské zemi a k hranici Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Král učinil stříbro v Jeruzalémě tak hojné jako kamení a cedry jako sykomory v Šefele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Koně pro Šalomouna přiváželi z Egypta a ze všech zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Ostatní Šalomounovy činy, ⌈první i poslední,⌉ jsou zapsány v letopisech proroka Nátana, v proroctví Achijáše Šíloského a ve viděních vidoucího Jeeda o Jarobeámovi, synu Nebatovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Šalomoun kraloval v Jeruzalémě nad celým Izraelem čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Pak Šalomoun ulehl se svými otci a pohřbili ho v městě jeho otce Davida. Po něm se stal králem jeho syn Rechabeám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rechabeám šel do Šekemu, neboť do Šekemu přišel celý Izrael, aby ho ustanovili králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Když se to Jarobeám, syn Nebatův, doslechl, byl ještě v Egyptě, kam utekl před králem Šalomounem. Jarobeám se vrátil z Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Poslali pro něj a zavolali ho. Jarobeám přišel s celým Izraelem a promluvili k Rechabeámovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Tvůj otec učinil naše jho těžkým. Ty nyní ulehči tvrdou otročinu svého otce a jeho těžké jho, které na nás vložil, a budeme ti sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Řekl jim: Po třech dnech se ke mně vraťte. Nato lid odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Král Rechabeám se radil se staršími, kteří sloužili jeho otci Šalomounovi, dokud byl živ: Co radíte odpovědět tomuto lidu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Řekli mu: Jestliže budeš k tomuto lidu laskavý, laskavě je přijmeš a promluvíš k nim laskavá slova, budou po celou dobu tvými otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Nedbal na radu, kterou mu dali starci, a radil se s mladíky, kteří vyrůstali s ním a sloužili mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Zeptal se jich: Co vy radíte, abychom odpověděli tomuto lidu, který mi řekl: Ulehči jho, které na nás vložil tvůj otec?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Mladíci, kteří s ním vyrůstali, mu odpověděli: Toto pověz lidu, který ti řekl: Tvůj otec učinil naše jho těžkým, ty nám ulehči, takto k nim promluv: Můj malík je tlustší nežli bedra mého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Nuže, můj otec na vás naložil těžké jho a já k vašemu jhu přidám. Můj otec vás káznil biči, já vás budu káznit důtkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Jarobeám a všechen lid přišel k Rechabeámovi třetího dne, tak jak král řekl: Třetího dne se ke mně vraťte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Král odpověděl tvrdě. Tak král Rechabeám nedbal na radu starších.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Promluvil k nim podle rady mladíků: ⌈ Můj otec učinil⌉ vaše jho těžkým a já k němu přidám. Můj otec vás káznil biči, já vás budu káznit důtkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Král nevyslyšel lid, neboť nastal zvrat od Boha, aby Hospodin naplnil své slovo, které promluvil prostřednictvím Achijáše Šíloského k Jarobeámovi, synu Nebatovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Když celý Izrael viděl, že je král nevyslyšel, odpověděl lid králi: Jaký máme podíl v Davidovi? Nemáme dědictví v synu Jišajovu! Každý ke svým stanům, Izraeli! Nyní hleď na svůj dům, Davide! A celý Izrael šel ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Nad syny Izraele, kteří sídlili v judských městech, nad těmi však kraloval Rechabeám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Král Rechabeám poslal Hadoráma, který byl nad nucenými pracemi, ale synové Izraele na něj házeli kamení, takže zemřel. Král Rechabeám honem vystoupil na vůz a utekl do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Tak se Izrael vzbouřil proti domu Davidovu, jak je tomu dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Když přišel Rechabeám do Jeruzaléma, shromáždil dům Judův a Benjamínův, sto osmdesát tisíc vybraných bojovníků, aby bojovali s Izraelem a navrátili království Rechabeámovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'I stalo se Hospodinovo slovo k Šemajášovi, muži Božímu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Řekni judskému králi Rechabeámovi, synu Šalomounovu, a celému Izraeli v Judsku a Benjamínovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Toto praví Hospodin: Netáhněte a nebojujte se svými bratry. Vraťte se všichni domů, neboť tato věc se stala ode mě. Poslechli Hospodinova slova a vrátili se z tažení proti Jarobeámovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Rechabeám pobýval v Jeruzalémě a postavil v Judsku opevněná města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Postavil Betlém, Étam, Tekóu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bét–súr, Sóko, Adulám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gat, Maréšu, Zíf,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adórajim, Lakíš, Azeku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Soreu, Ajalón a Chebrón; to byla opevněná města v Judsku a Benjamínovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Posilnil pevnosti a dal jim vévody i sklady potravin, oleje a vína');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'a do každého jednotlivého města dal štíty a oštěpy; tak je převelice posilnil. Jemu patřili Juda a Benjamín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Kněží a lévité, kteří byli po celém Izraeli, mu sloužili, každý přišel ze svého území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Lévité totiž opustili své pastviny a své vlastnictví a šli do Judska a Jeruzaléma, protože Jarobeám i jeho synové je odvrhli, aby nesloužili Hospodinu jako kněží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'a ustanovil si vlastní kněze pro návrší, pro běsy a pro telata, která učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Za nimi šli do Jeruzaléma ze všech izraelských kmenů ti, kdo přiložili svá srdce k hledání Hospodina, Boha Izraele, aby obětovali Hospodinu, Bohu svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Posilnili judské království a posilnili Rechabeáma, syna Šalomounova, po tři roky, neboť po tři roky chodili po cestě Davidově a Šalomounově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Rechabeám si vzal za ženu Machalatu, dceru Jerímóta, syna Davidova, a Abíchajil, dceru Elíaba, syna Jišajova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Porodila mu syny: Jeúše, Šemarjáše a Zahama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Po ní si vzal Maaku, dceru Abšalómovu. Porodila mu Abijáše, Ataje, Zízu a Šelomíta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Rechabeám si zamiloval Maaku, dceru Abšalómovu, nad všechny své ženy a konkubíny; vzal si totiž osmnáct žen a šedesát konkubín. Zplodil dvacet osm synů a šedesát dcer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Rechabeám ustanovil do čela Abijáše, syna Maaky, za vévodu mezi jeho bratry, neboť ho chtěl ustanovit králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, '⌈Uvážlivě rozmístil⌉ všechny své syny po celém území Judy a Benjamína, do všech opevněných měst a dal jim hojnost potravin a vyžádal pro ně množství žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'I stalo se, když se upevnilo Rechabeámovo království a on zesílil, že opustil Hospodinův zákon a celý Izrael s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'I stalo se v pátém roce vlády krále Rechabeáma, že vytáhl proti Jeruzalému egyptský král Šíšak, protože se zpronevěřili Hospodinu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 's tisíci dvěma sty vozy, šedesáti tisíci jezdci a bezpočtem lidu, který s ním šel z Egypta: Lúbíjci, Sukejci a Kúšijci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Dobyl opevněná města, která patřila Judovi, a přitáhl až k Jeruzalému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Nato přišel prorok Šemajáš k Rechabeámovi a judským velitelům, kteří se shromáždili před Šíšakem do Jeruzaléma, a řekl jim: Toto praví Hospodin: Vy jste opustili mě, a tak já přenechám vás do Šíšakovy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Izraelští velitelé a král se pokořili a řekli: ⌈Hospodin je spravedlivý.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Když Hospodin viděl, že se pokořili, stalo se Hospodinovo slovo k Šemajášovi: Pokořili se; nezničím je, ale zanechám jim několik, kteří vyváznou, nerozleje se má zloba v Jeruzalémě skrze Šíšaka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Avšak stanou se jeho otroky, aby poznali rozdíl mezi službou mně a službou královstvím zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Egyptský král Šíšak vytáhl proti Jeruzalému a pobral poklady Hospodinova domu i poklady královského paláce, všechno to pobral. Vzal také zlaté malé štíty, které udělal Šalomoun.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Král Rechabeám místo nich udělal štíty bronzové a svěřil je pod velení velitelů běžců, kteří střežili vchod do královského paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Pokaždé, když šel král do Hospodinova domu, běžci šli a přinášeli je a pak je vraceli zpět do síně běžců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Když se pokořil, odvrátil se od něj Hospodinův hněv a nezničil ho zcela. Také v Judsku se děly dobré věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Král Rechabeám se vzchopil v Jeruzalémě a kraloval dále. Rechabeámovi bylo čtyřicet jedna let, když se stal králem, kraloval sedmnáct let v Jeruzalémě, městě, které Hospodin vyvolil ze všech izraelských kmenů, aby tam položil své jméno. Jeho matka se jmenovala Naama Amónská.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Páchal to, co je zlé, neboť nezaměřil své srdce na hledání Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'První i poslední Rechabeámovy činy jsou zapsány v letopisech proroka Šemajáše a vidoucího Ida jako rodokmen. Po celou dobu byly boje mezi Rechabeámem a Jarobeámem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Rechabeám ulehl se svými otci a byl pohřben v Městě Davidově. Po něm se stal králem jeho syn Abijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'V osmnáctém roce vlády krále Jarobeáma se stal králem nad Judou Abijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Kraloval v Jeruzalémě tři roky. Jeho matka se jmenovala Míkaja, dcera Uríelova z Gibeje. Mezi Abijášem a Jarobeámem trval boj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abijáš rozpoutal boj s vojskem bojovníků, se čtyřmi sty tisíci vybranými muži. Jarobeám se proti němu sešikoval do boje s osmi sty tisíci vybranými muži, udatnými hrdiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Abijáš se postavil na hoře Semárajimu, která je v Efrajimském pohoří, a řekl: Slyšte mě, Jarobeáme a celý Izraeli!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Což vám není známo, že Hospodin, Bůh Izraele, dal království nad Izraelem navěky Davidovi, jemu a jeho synům, skrze smlouvu soli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Povstal však Jarobeám, syn Nebatův, otrok Šalomouna, syna Davidova, aby se vzbouřil proti svému pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Shromáždili se k němu ničemní muži, ničemníci a byli silnější než Rechabeám, syn Šalomounův. Rechabeám byl mladý a nerozhodný a nepočínal si proti nim zmužile.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'A teď si říkáte, že odoláte Hospodinovu království v ruce synů Davidových. Je vás velké množství a máte u sebe zlatá telata, která vám udělal Jarobeám jako bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Což jste ale nezahnali Hospodinovy kněze, syny Áronovy, a lévity a ne udělali si kněze, jako mají národy zemí? Každý, kdo přišel s býčkem, mládětem býka, a sedmi berany, aby se zasvětil, stal se knězem nebohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Co se nás týče, Hospodin je náš Bůh a neopustili jsme ho. Kněží, kteří slouží Hospodinu, jsou syny Áronovými a lévité jsou při práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Pálí Hospodinu zápalné oběti ráno co ráno, večer co večer a vonné kadidlo a předkladné chleby dávají na čistý stůl; zlatý svícen a jeho lampy zapalují večer co večer, neboť my ⌈zachováváme službu⌉ Hospodina, našeho Boha, ale vy jste ho opustili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Hle, s námi v čele je Bůh a jeho kněží s poplašnými trubkami, aby proti vám spustili křik. Nebojujte s Hospodinem, Bohem svých otců, protože neuspějete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Jarobeám nechal zálohu obejít, aby se dostal za ně. Tak byli před Judejci a záloha za nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Judejci se ohlédli a uviděli, že je proti nim boj z předu i zezadu. I křičeli k Hospodinu, kněží troubili na trubky');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'a judští muži spustili křik. I stalo se, když judští muži spustili křik, že Bůh porazil Jarobeáma a celý Izrael před Abijášem a Judejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Synové Izraele utíkali před Judejci a Bůh je vydal do jejich ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abijáš a jeho lid jim způsobili velkou porážku a padlo pobitých z Izraele pět set tisíc vybraných mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Synové Izraele byli v té době pokořeni a synové judští byli silnější, protože spoléhali na Hospodina, Boha svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abijáš pronásledoval Jarobeáma a dobyl od něj některá města: Bét–el a jeho vesnice, Ješánu a její vesnice a Efrón a jeho vesnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jarobeám již za Abijášových dnů nezískal moc. Hospodin ho postihl, takže zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Ale Abijáš se vzmáhal. Vzal si čtrnáct žen a zplodil dvacet dva synů a šestnáct dcer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Ostatní Abijášovy činy, jeho jednání a slova jsou zapsána ve výkladu proroka Ida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, 'Abijáš ulehl se svými otci a pohřbili ho v Městě Davidově. Po něm se stal králem jeho syn Ása. Za jeho dnů měla země deset let klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Ása činil to, co bylo ⌈dobré a správné v očích⌉ Hospodina, jeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Odstranil cizí oltáře a návrší, roztřískal posvátné sloupy a pokácel posvátné kůly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Řekl Judejcům, aby hledali Hospodina, Boha svých otců, a plnili zákon a příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Odstranil ze všech judských měst návrší a kadidlové oltáře a království mělo za něj klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Postavil v Judsku opevněná města, protože země měla klid. V těch letech proti němu ne vypukla válka, neboť Hospodin mu dal odpočinek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Řekl Judejcům: Stavme tato města a obežeňme je hradbami s věžemi, vraty a závorami. Země je dosud naše, neboť jsme hledali Hospodina, svého Boha. Hledali jsme jej a dal nám odpočinek ⌈od okolních nepřátel.⌉ Stavěli a dařilo se jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Ása měl vojsko: Z Judska tři sta tisíc těch, kteří nosili velký ⌈štít a oštěp,⌉ a z Benjamína dvě stě osmdesát tisíc těch, kteří nosili malý štít a napínali luk. Ti všichni byli udatní hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Vytáhl proti nim Kúšijec Zerach s milionovým vojskem a třemi sty vozy a přitáhl až k Maréše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Ása vytáhl proti nim a sešikovali se k boji v údolí Sefaty u Maréši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Nato volal Ása k Hospodinu, svému Bohu, a řekl: Hospodine, mimo tebe není pomoci pro boj mezi mocným a bezmocným. Pomoz nám, Hospodine, náš Bože, vždyť spoléháme na tebe a ve tvém jménu jsme vytáhli proti tomuto davu. Hospodine, ty jsi náš Bůh. Ať ⌈tě člověk nepřemůže.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Hospodin porazil Kúšijce před Ásou a před Judejci a Kúšijci utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Ása a lid, který byl s ním, je však pronásledovali až ke Geraru. ⌈Kúšijci padali a⌉ nikdo z nich nezůstal naživu, protože byli od Hospodina a jeho vojska rozdrceni. Judejci odnesli velmi mnoho kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Vybili všechna města kolem Geraru, neboť na ně padl ⌈strach z Hospodina.⌉ Vyplenili všechna města, protože v nich bylo mnoho kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Přepadli také stany pro pastevce dobytka a odvedli množství ovcí a velbloudů. Pak se vrátili do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Tehdy na Azarjášovi, synu Ódedovu, spočinul Boží Duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Vyšel před Ásu a řekl mu: Slyšte mě, Áso a všichni Judejci a Benjamínci! Hospodin bude s vámi, když budete s ním. Jestliže ho budete hledat, dá se vám nalézt, ale jestliže ho opustíte, opustí vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Po mnoho dní byl Izrael bez pravého Boha, bez vyučujícího kněze a bez zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Ve své tísni se vrátil k Hospodinu, Bohu Izraele; hledali ho a dal se jim nalézt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'V oněch dobách ⌈nebyl pokoj pro toho, kdo vycházel a vcházel,⌉ neboť na všechny obyvatele země padly velké zmatky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Národ drtil národ, město jiné město, protože je Bůh skrze všelijaké soužení přivedl do zmatku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Ale vy buďte silní a vaše ruce ať neochabnou, neboť je mzda za vaši práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Když Ása uslyšel tato slova a proroctví proroka ⌈ Azarjáše, syna ⌉ Ódedova, vzchopil se a odstranil ohavné modly z celého území Judy a Benjamína i z měst, která dobyl v Efrajimském pohoří, a obnovil Hospodinův oltář, který byl před Hospodinovou předsíní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Shromáždil všechny Judejce a Benjamínce a z Efrajima, Manasesa a z Šimeóna ty, kteří u nich pobývali jako cizinci, neboť k němu přeběhli mnozí z Izraele, když viděli, že Hospodin, jeho Bůh, je s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Shromáždili se do Jeruzaléma ve třetím měsíci patnáctého roku Ásova kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Onoho dne obětovali Hospodinu z kořisti, kterou přivedli, sedm set býků a sedm tisíc ovcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Vstoupili do smlouvy, že budou hledat Hospodina, Boha svých otců, celým svým srdcem a celou svou duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'A každý, kdo by nehledal Hospodina, Boha Izraele, ať je usmrcen, ⌈malý i velký, muž i žena.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Hlasitě přísahali Hospodinu s pokřikem, trubkami a beraními rohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Všichni Judejci se radovali z té přísahy, neboť přísahali celým svým srdcem a se vším zalíbením ho hledali a dal se jim nalézt. A Hospodin jim dal odpočinek od okolních nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Král Ása také odstranil svou matku Maaku z postavení královny, protože učinila ohavnou modlu pro Ašeru. Ása její ohavnou modlu pokácel, rozdrtil a spálil v údolí Kidrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Návrší sice nebyla z Izraele odstraněna, ovšem Ásovo srdce bylo po všechny jeho dny neporušené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Přinesl do Božího domu svaté věci svého otce i své vlastní -- stříbro, zlato a různé předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Až do třicátého pátého roku Ásova kralování nebyla válka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'V třicátém šestém roce Ásova kralování vytáhl izraelský král Baeša proti Judsku. Postavil Rámu, aby nedovolil judskému králi Ásovi vycházet a vcházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Ása vynesl stříbro a zlato z pokladnic Hospodinova domu i královského paláce a poslal to aramejskému králi Ben–hadadovi, sídlícímu v Damašku, se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Mezi mnou a tebou, mezi mým otcem a tvým otcem je smlouva. Hle, posílám ti stříbro a zlato. Jdi a zruš svou smlouvu s izraelským králem Baešou, ať ode mě odtáhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Ben–hadad uposlechl krále Ásu, poslal velitele vojsk, které měl, proti izraelským městům. Pobili Ijón, Dan, Ábel–majim a všechna města pro sklady z Neftalího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'I stalo se, když to Baeša uslyšel, že přestal stavět Rámu a ukončil svou práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Král Ása pak vzal všechny Judejce a odnesli kameny z Rámy i dřevo, ze kterého Baeša stavěl, a postavil z toho Gebu a Mispu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'V té době přišel k judskému králi Ásovi vidoucí Chananí a řekl mu: Protože jsi spoléhal na aramejského krále a nespoléhal jsi na Hospodina, svého Boha, proto vojsko aramejského krále ⌈uniklo ze tvé ruky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Což neměli Kúšijci a Lúbíjci velké vojsko, vozy a velmi mnoho jezdců? Ale když jsi spoléhal na Hospodina, vydal je do tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Vždyť Hospodinovy oči obzírají celou zemi, aby posílil srdce těch, kteří jsou cele s ním. Jednal jsi v tomto bláznivě, proto ti od nynějška nastanou boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Ása se rozzlobil na vidoucího a dal ho do vězení, protože se na něj kvůli tomu hněval. V oné době Ása utiskoval některé z lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Hle, první i poslední Ásovy činy jsou zapsány v Knize judských a izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'V třicátém devátém roce svého kralování Ása onemocněl na nohy a jeho nemoc byla úporná. Ale ani ve své nemoci nehledal Hospodina, nýbrž lékaře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Pak Ása ulehl se svými otci. Zemřel v čtyřicátém prvním roce svého kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Pohřbili ho v jeho hrobě, který si vykopal v Městě Davidově. Položili ho na lože, které bylo naplněno balzámy a různými druhy připravených mastí. Zapálili pro něj převeliký oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Po něm se stal králem jeho syn Jóšafat. Počínal si v Izraeli zmužile.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Do všech opevněných judských měst umístil vojsko a umístil posádky na judském území i v efrajimských městech, která dobyl jeho otec Ása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Hospodin byl s Jóšafatem, protože ⌈chodil po prvních cestách svého otce Davida⌉ a nedotazoval se baalů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'ale dotazoval se Boha svých otců a žil podle jeho příkazů, a ne podle skutků Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Hospodin upevnil království v jeho ruce a všichni Judejci dávali Jóšafatovi dary, takže měl mnoho bohatství a slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Když ⌈získal na Hospodinových cestách více odvahy,⌉ ještě odstranil návrší a posvátné kůly z Judska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Ve třetím roce svého kralování poslal svá knížata Ben–chajila, Obadjáše, Zekarjáše, Netanela a Míkajáše, aby učili v judských městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'S nimi byli lévijci Šemajáš, Netanjáš, Zebadjáš, Asáel, Šemiramót, Jónatan, Adónijáš, Tobijáš a Tób–adónijáš, lévijci, a s nimi kněží Elíšama a Jóram.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Učili v Judsku a měli s sebou knihu Hospodinova zákona. Obcházeli všechna judská města a učili mezi lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Strach z Hospodina padl na všechna království zemí, které byly okolo Judska, a nebojovala s Jóšafatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Někteří z Pelištejců přinášeli Jóšafatovi dávky a náklad stříbra. Také Arabové mu přiváděli brav: sedm tisíc sedm set beranů a sedm tisíc sedm set kozlů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Jóšafat ⌈stále velmi bohatl,⌉ takže postavil v Judsku pevnosti a města pro sklady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'V judských městech měl mnoho zásob a v Jeruzalémě bojovníky, ⌈udatné hrdiny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Toto byly jejich počty podle domu jejich otců: z Judska, velitelé nad tisíci: velitel Adna a s ním tři sta tisíc udatných hrdinů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'vedle něj velitel Jóchanan a s ním dvě stě osmdesát tisíc;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'vedle něj Amasjáš, syn Zikrího, Hospodinův dobrovolník, a s ním dvě stě tisíc udatných hrdinů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'z Benjamína udatný hrdina Eljáda a s ním dvě stě tisíc ozbrojených lukem a štítem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'vedle něj Józabad a s ním sto osmdesát tisíc vojenských ozbrojenců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Tito sloužili králi kromě těch, které král umístil do opevněných měst po celém Judsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Jóšafat měl mnoho bohatství a slávy a spříznil se s Achabem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Po několika letech sestoupil k Achabovi do Samaří. Achab pro něj a pro lid, který byl s ním, zabil množství bravu a skotu a naváděl ho, aby vytáhl proti Rámot–gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Izraelský král Achab se zeptal judského krále Jóšafata: Půjdeš se mnou proti Rámot–gileádu? Ten mu odpověděl: Jsem jako ty a můj lid jako tvůj lid. Půjdu s tebou do války.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Jóšafat dále řekl izraelskému králi: Dotaž se nejprve na Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Izraelský král shromáždil proroky, čtyři sta mužů a zeptal se jich: Máme jít do boje proti Rámot–gileádu, nebo mám od toho upustit? Odpověděli: Vytáhni, Bůh ho vydá do královy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Jóšafat se zeptal: To už tady není žádný Hospodinův prorok, abychom se dotázali skrze něj?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Izraelský král Jóšafatovi odpověděl: Ještě je tu jeden muž, skrze něhož je možno se dotázat Hospodina, ale já ho nenávidím, protože mi neprorokuje dobro, nýbrž po celou dobu zlo. Je to Míkajáš, syn Jimlův. Jóšafat řekl: Ať král takto nemluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Izraelský král zavolal jednoho dvorního úředníka a řekl: Rychle sem přiveď Míkajáše, syna Jimlova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Izraelský král a judský král Jóšafat seděli každý na svém trůnu, oblečeni v roucha; seděli na humně u vchodu do samařské brány a všichni proroci před nimi prorokovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Sidkijáš, syn Kenaanův, si udělal železné rohy a řekl: Toto praví Hospodin: Těmito rohy budeš trkat Aramejce, dokud s nimi neskoncuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Tak prorokovali všichni proroci: Vytáhni proti Rámot–gileádu a uspěješ. Hospodin jej vydá do královy ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Posel, který šel Míkajášovi vstříc, mu řekl: Hle, proroci mluví jednomyslně dobro pro krále. Ať jsou tvoje slova jako řeč jednoho z nich. Mluv dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Míkajáš řekl: Jakože živ je Hospodin, to, co můj Bůh promluví, to budu mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Když přišel ke králi, král se ho zeptal: Míko, máme jít do boje proti Rámot–gileádu, nebo mám od toho upustit? Odpověděl: Vytáhněte a uspějete. Budou vydáni do vaší ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Král mu řekl: Kolikrát tě mám zapřísahat při Hospodinově jménu, abys mi neříkal nic než pravdu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Nato Míkajáš řekl: Viděl jsem celý Izrael rozptýlený po horách jako ovce, které nemají pastýře. Hospodin řekl: Nemají pána. Ať se všichni vrátí domů v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Izraelský král řekl Jóšafatovi: Což jsem ti neříkal, že mi nebude prorokovat dobro, ale zlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Míkajáš dále řekl: Slyšte Hospodinovo slovo: Viděl jsem Hospodina sedícího na trůnu a celý nebeský zástup stál po jeho pravici a levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Hospodin řekl: Kdo přemluví izraelského krále Achaba, aby vytáhl a padl u Rámot–gileádu? Jeden říkal tohle a druhý říkal tohle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'I vyšel jeden duch, postavil se před Hospodinem a řekl: Já ho přemluvím. Hospodin se ho zeptal: Čím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Odpověděl: Vyjdu a stanu se lživým duchem v ústech všech jeho proroků. Hospodin řekl: Ty ho přemluvíš, ano, dokážeš to. Jdi a učiň to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'A hle, nyní Hospodin dal lživého ducha do úst těchto tvých proroků. Ale Hospodin promluvil o tobě zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Sidkijáš, syn Kenaanův, přistoupil, udeřil Míkajáše po tváři a řekl: Jakým způsobem Hospodinův Duch přešel ode mě, aby mluvil skrze tebe?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Míkajáš řekl: Hle, uvidíš to v onen den, kdy vejdeš do nejzazšího pokoje, aby ses skryl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Nato izraelský král řekl: Chopte se Míkajáše a odveďte ho veliteli města Amónovi a královskému synu Jóašovi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'a řekněte: Toto praví král: Dejte ho do věznice a krmte ho troškou chleba a vody, dokud se nevrátím v pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Míkajáš řekl: Jestliže se opravdu vrátíš v pokoji, nemluvil skrze mě Hospodin. A prohlásil: Slyšte, všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Nato vytáhl izraelský král s judským králem Jóšafatem proti Rámot–gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Izraelský král řekl Jóšafatovi: Chci se přestrojit a tak jít do boje, ale ty si obleč své roucho. Izraelský král se přestrojil a šel do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Aramejský král přikázal svým velitelům vozby: Nebojujte proti malému ani velkému, jenom proti samotnému izraelskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'I stalo se, když velitelé vozby uviděli Jóšafata, že si řekli: To je izraelský král! A obklíčili ho, aby proti němu bojovali. Jóšafat volal o pomoc a Hospodin mu pomohl. Bůh je od něj odvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'I stalo se, když velitelé vozby uviděli, že to není izraelský král, odvrátili se od něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Tu kdosi napjal nahodile luk a zasáhl izraelského krále mezi spoje pancíře. Král řekl vozatajovi: Obrať koně a odvez mě z bojiště, protože jsem raněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Zatímco boj onen den silně vzplál, izraelský král zůstal podepřený ve voze naproti Aramejcům až do večera a při západu slunce zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Judský král Jóšafat se vrátil v pokoji domů do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Vyšel proti němu vidoucí Jehú, syn Chananího, a řekl králi Jóšafatovi: Měl jsi chodit na pomoc ničemovi a milovat toho, kdo nenávidí Hospodina? Za to na tebe dopadne rozhořčení od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Ale jsou u tebe i dobré věci, neboť jsi vyhladil ze země posvátné kůly a zaměřil jsi své srdce na hledání Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Jóšafat sídlil v Jeruzalémě. Pak znovu vyšel mezi lid od Beer–šeby až k Efrajimskému pohoří a přivedl je zpět k Hospodinu, Bohu jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Ustanovil v zemi soudce, v každém opevněném městě v Judsku, ⌈v každém městě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Řekl soudcům: Hleďte si toho, co děláte, neboť nesoudíte pro člověka, ale pro Hospodina. On je s vámi, když vyslovujete rozsudek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Ať na vás nyní padne strach z Hospodina. Dbejte ⌈ na to, jak jednáte,⌉ neboť u Hospodina, našeho Boha, není zvrácenosti, ⌈braní ohledů⌉ ani braní úplatků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Také v Jeruzalémě ustanovil Jóšafat některé z lévitů, kněží a z předáků izraelských rodů pro Hospodinovo právo a pro spory a ⌈ oni se vrátili do ⌉ Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Přikázal jim: Toto čiňte z bázně před Hospodinem, s poctivostí a neporušeným srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Při každém sporu, který se k vám dostane od vašich bratrů, jež sídlí ve svých městech -- ať už jde o krveprolití, o zákon, příkazy, ustanovení či nařízení -- je varujte, aby se neprovinili proti Hospodinu a aby na vás a vaše bratry ne dopadlo jeho rozhořčení. Tak jednejte a neproviníte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Hle, vrchní kněz Amarjáš bude nad vámi pro všechny Hospodinovy záležitosti a Zebadjáš, syn Jišmaelův, vévoda domu judského, pro všechny záležitosti královy. A jako správci budou před vámi lévité. ⌈Buďte silní⌉ a jednejte a Hospodin ať je s ⌈tím, kdo jedná dobře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'I stalo se potom, že synové Moábovi, synové Amónovi a s nimi někteří z Meunejců vytáhli do boje proti Jóšafatovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Tu přišli a oznámili Jóšafatovi: Táhne proti tobě velký dav z druhé strany moře, od Aramu. Hle, jsou v Chasesón–támaru, to je v Én–gedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Jóšafat dostal strach; rozhodl se hledat Hospodina a vyhlásil v celém Judsku půst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Judejci se shromáždili, aby hledali pomoc od Hospodina. Také ze všech judských měst přišli, aby hledali Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Jóšafat se postavil ve shromáždění Judejců a obyvatel Jeruzaléma v Hospodinově domě před novým nádvořím');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'a řekl: Hospodine, ⌈Bože našich otců,⌉ což ty nejsi Bůh na nebesích? Ty vládneš nad všemi královstvími národů. Ve tvé ruce je ⌈síla a udatnost.⌉ Není, kdo by se ti mohl postavit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Což jsi ty, náš Bože, nevyhnal před svým lidem Izraelem obyvatele této země a ne dal jsi ji navěky potomstvu svého přítele Abrahama?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Usadili se v ní a postavili ti v ní svatyni pro tvé jméno se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Jestliže na nás přijde zlo, meč, přísný soud, mor či hlad, postavíme se před tento dům a před tebe, neboť tvé jméno je v tomto domě, a budeme k tobě ze svého soužení volat o pomoc, vyslyšíš a zachráníš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'A nyní, hle, synové Amónovi i Moábovi a obyvatelé pohoří Seír -- proti nimž jsi nedovolil Izraelcům vytáhnout, když šli z egyptské země, takže se od nich odvrátili a nevyhladili je --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'hle, odplácejí se nám tím, že vytáhli, aby nás vyhnali ze tvého vlastnictví, které jsi nám podrobil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Bože náš, což je nebudeš soudit? Vždyť v nás není síla proti tomuto velkému davu, který táhne proti nám. Nevíme, co máme dělat, ale k tobě obracíme oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Všichni Judejci stáli před Hospodinem, i jejich malé děti, jejich ženy a jejich synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Potom na Jachazíelovi, synu Zekarjáše, syna Benajáše, syna Jeíela, syna Matanjášova, lévitovi ze synů Asafových, spočinul uprostřed shromáždění Hospodinův Duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Řekl: Pozorně naslouchejte, všichni Judejci, obyvatelé Jeruzaléma a králi Jóšafate. Toto vám praví Hospodin: Nebojte se a neděste se tohoto velkého davu, protože boj není váš, ale Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Zítra sestupte proti nim. Potáhnou průsmykem Cíc. Naleznete je na konci údolí před pustinou Jerúel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Vy zde nebudete bojovat. Postavte se, stůjte a dívejte se na Hospodinovu záchranu pro vás, Judejci a obyvatelé Jeruzaléma. Nebojte se a neděste se! Zítra vytáhněte proti nim a Hospodin bude s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Jóšafat poklekl tváří k zemi a všichni Judejci a obyvatelé Jeruzaléma padli před Hospodinem a klaněli se Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Nato povstali lévité ze synů Kehatovců a ze synů Kórachovců, aby chválili Hospodina, Boha Izraele, zvlášť silným hlasem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Časně ráno vstali a vytáhli k tekójské pustině. Když vycházeli, Jóšafat zůstal stát a řekl: Slyšte mě, Judejci a obyvatelé Jeruzaléma! Věřte Hospodinu, svému Bohu, a obstojíte! Věřte jeho prorokům a uspějete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Když se poradil s lidem, ustanovil ⌈ty, kdo zpívali Hospodinu⌉ a chválili ⌈slávu jeho svatosti.⌉ Jak šli před ozbrojenci, říkali: Vzdávejte Hospodinu díky, protože navěky je jeho milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Když začali s jásotem a chválou, Hospodin uvedl zálohy na syny Amónovy, Moábovy a obyvatele pohoří Seír, kteří táhli proti Judejcům, a byli poraženi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Synové Amónovi a Moábovi se postavili proti obyvatelům pohoří Seír, aby je zasvětili zkáze a zničili. Když skoncovali s obyvateli Seíru, pomáhali ke zkáze jeden druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Když Judejci přišli na vyhlídku do pustiny a pohleděli k tomu davu, hle, na zemi ležely mrtvoly; nikdo neunikl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Jóšafat a jeho lid přišel, aby loupili kořist a našli množství majetku, oděvy a cenné předměty. Nabrali si toho k neunesení. Tři dny loupili kořist, protože jí bylo mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Čtvrtého dne se shromáždili v údolí Beraka, neboť tam dobrořečili Hospodinu. Proto se nazývá to místo údolí Beraka až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Potom se všichni Judejci a obyvatelé Jeruzaléma s Jóšafatem v čele vrátili s radostí zpět do Jeruzaléma, neboť jim Hospodin dal radost nad jejich nepřáteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Přišli s harfami, lyrami a trubkami do Jeruzaléma, do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'A strach před Bohem padl na všechna království země, když uslyšeli, že Hospodin bojoval proti nepřátelům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Jóšafatovo království mělo klid a jeho Bůh mu dal odpočinek od okolních nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Jóšafat kraloval nad Judou. Bylo mu třicet pět let, když se stal králem, a kraloval v Jeruzalémě dvacet pět let. Jeho matka se jmenovala Azúba, dcera Šilchího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Chodil po cestě svého otce Ásy, neodvrátil se od ní a činil to, co je správné v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Jenom návrší nebyla odstraněna. Lid stále nezaměřil své srdce k Bohu svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Ostatní Jóšafatovy činy, první i poslední, jsou zapsány v letopisech Jehúa, syna Chananího, které byly zaneseny do Knihy izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Potom se judský král Jóšafat spojil s izraelským králem Achazjášem, který jednal ničemně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Spojil se s ním, aby udělal lodě schopné plout do Taršíše. Lodě udělali v Esjón–geberu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Elíezer, syn Dódavahův z Maréši, prorokoval o Jóšafatovi: Protože ses spojil s Achazjášem, Hospodin se obořil na tvé dílo. Lodě se rozlámaly a nemohly plout do Taršíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Jóšafat ulehl se svými otci a byl pohřben se svými otci v Městě Davidově. Po něm se stal králem jeho syn Jóram.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Měl bratry, syny Jóšafatovy: Azarjáše, Jechíela, Zekarjáše, Azarjáše, Michaela a Šefatjáše. Ti všichni byli synové izraelského krále Jóšafata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Jejich otec jim dal mnohé dary: stříbro, zlato a jiné vzácné dary, spolu s opevněnými městy v Judsku. Ale království dal Jóramovi, protože byl prvorozený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Když se Jóram ujal království svého otce a vzchopil se, zabil mečem všechny své bratry a také některé z izraelských knížat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Jóramovi bylo třicet dva let, když se stal králem, a kraloval v Jeruzalémě osm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Chodil po cestě izraelských králů, tak jak to činil dům Achabův, protože Achabova dcera byla jeho ženou. Páchal to, co je zlé v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Hospodin však nechtěl zničit dům Davidův, kvůli smlouvě, kterou uzavřel s Davidem, a protože slíbil, že dá jemu a jeho synům po všechny dny lampu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Za jeho dnů se Edómci vzbouřili proti judské moci a ustanovili si nad sebou krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Jóram tehdy vytáhl se svými veliteli a s ním celá vozba. I stalo se, že v noci vstal a udeřil na Edómce, kteří obkličovali jej i velitele vozby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Edómci se proti judské moci bouřili až do tohoto dne. Tak se vzbouřila v té době proti jeho moci i Libna, protože opustil Hospodina, ⌈Boha svých otců.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'On také udělal na judských horách návrší; přivedl ke smilstvu obyvatele Jeruzaléma a svedl Judejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Přišel mu dopis od proroka Elijáše: Toto praví Hospodin, Bůh tvého otce Davida: Protože jsi nechodil po cestách svého otce Jóšafata a po cestách judského krále Ásy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'ale chodil jsi po cestě izraelských králů a přivedl jsi Judejce a obyvatele Jeruzaléma ke smilstvu, jako přiváděl ke smilstvu dům Achabův, a také jsi zabil své bratry, dům svého otce, kteří byli lepší nežli ty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'hle, Hospodin postihne velikou ranou tvůj lid, tvé syny a tvé ženy i všechen tvůj majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'A ty dostaneš ⌈těžké nemoci,⌉ nemoc vnitřností, až tvé vnitřnosti vyjdou ⌈kvůli dlouhodobé nemoci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Potom vzbudil Hospodin proti Jóramovi ducha Pelištejců a Arabů, kteří sídlili vedle Kúšijců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Vytáhli proti Judsku, pronikli do něj a odnesli všechen majetek, který se nacházel v královském paláci, a také jeho syny a jeho ženy, takže mu nezůstal žádný syn, kromě jeho nejmladšího syna Jóachaza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Po tom všem jej Hospodin postihl v jeho vnitřnostech nevyléčitelnou nemocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'I stalo se po mnoha dnech, když uplynula dvě léta, že vyšly jeho vnitřnosti kvůli jeho nemoci a zemřel na ⌈těžkou nemoc.⌉ Jeho lid pro něho neudělal oheň, jako dělali pro jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Bylo mu třicet dva let, když se stal králem, a kraloval v Jeruzalémě osm let. Odešel jako nežádoucí. Pohřbili ho v Městě Davidově, ale ne v královských hrobech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Obyvatelé Jeruzaléma ustanovili místo něj králem jeho nejmladšího syna Achazjáše, protože všechny předchozí syny zabila loupežná horda, která přitáhla do tábora s Araby. Tak se stal judským králem Achazjáš, syn Jóramův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Achazjášovi bylo čtyřicet dva let, když se stal králem, a kraloval v Jeruzalémě jeden rok. Jeho matka se jmenovala Atalja, dcera Omrího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Také on chodil po cestách domu Achabova, protože jeho matka mu byla rádkyní k páchání ničemností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Páchal to, co je zlé v Hospodinových očích jako dům Achabův, neboť po smrti jeho otce mu tito byli rádci k jeho zkáze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Na jejich radu také šel a vytáhl k Rámot–gileádu s izraelským králem Jóramem, synem Achabovým, do boje proti aramejskému králi Chazaelovi, ale Aramejci Jórama ranili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Nato se Jóram vrátil do Jizreelu, aby se vyléčil z ran, které mu způsobili v Rámě, když bojoval s aramejským králem Chazaelem. Judský král Achazjáš, syn Jóramův, se přišel na Jórama, syna Achabova, do Jizreelu podívat, protože byl nemocný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Od Boha nastal Achazjášův pád poté, co šel k Jóramovi. Když přišel, šel s Jóramem k Jehúovi, synu Nimšího, kterého Hospodin pomazal, aby vyhladil dům Achabův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'I stalo se, když Jehú ⌈konal soud⌉ nad domem Achabovým, že našel judská knížata a syny Achazjášových bratrů, kteří sloužili Achazjášovi, a zabil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Potom hledal Achazjáše. Polapili ho, když se skrýval v Samaří. Přivedli ho k Jehúovi a usmrtili ho. Pohřbili ho, neboť si řekli: Byl to syn Jóšafata, který hledal Hospodina celým svým srdcem. Dům Achazjášův ne měl nikoho, kdo ⌈by byl schopen kralovat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Když Atalja, Achazjášova matka, viděla, že její syn zemřel, povstala a zahubila všechny královské potomky z domu judského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Ale Jóšeba, královská dcera, vzala Jóaše, syna Achazjášova, ukradla ho zprostřed královských synů, kteří byli usmrcováni, a dala jej i jeho kojnou do ložnice. Jóšeba, dcera krále Jórama, manželka kněze Jójady, ho skryla před Ataljou, protože byla Achazjášovou sestrou, takže nebyl usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Byl s nimi ukryt v Božím domě po šest let, zatímco Atalja kralovala nad zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'V sedmém roce se Jójada vzchopil a vzal velitele nad sty -- Azarjáše, syna Jerochámova, Jišmaela, syna Jóchananova, Azarjáše, syna Obédova, Maasejáše, syna Adajášova, a Elíšafata, syna Zikrího, a uzavřeli s ním smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Obešli Judsko a shromáždili lévity ze všech judských měst a předáky izraelských rodů a přišli do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Celé shromáždění uzavřelo v Božím domě smlouvu s králem. Jójada jim řekl: Hle, králův syn! Ať kraluje, jak řekl Hospodin o Davidových synech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Uděláte toto: Třetina z vás kněží a lévitů, kteří přicházíte v sobotu, bude jako vrátní prahů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'třetina bude v královském paláci a třetina v Základové bráně. Všechen lid bude na nádvořích Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Nikdo ať nevstoupí do Hospodinova domu kromě kněží a sloužících lévitů. Ti mohou vstoupit, neboť jsou svatí. Všechen lid ať ⌈zachovává Hospodinův řád.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Lévité obklopí krále, každý se zbraní v ruce, a ten, kdo by vešel do domu, bude usmrcen. Buďte s králem při jeho vcházení i vycházení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Lévité a všichni Judejci učinili všechno tak, jak přikázal kněz Jójada. Každý si vzal své muže -- ty, kteří přicházejí v sobotu do služby, s těmi, kteří odcházejí v sobotu ze služby, protože kněz Jójada nepropustil žádný oddíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Kněz Jójada dal velitelům nad sty kopí a malé i velké štíty krále Davida, které byly v Božím domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Postavil všechen lid okolo krále, každého s oštěpem v ruce, od pravé strany domu až k levé straně domu, u oltáře i u domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Vyvedli králova syna, vložili na něj korunu a svědectví. Ustanovili ho králem; Jójada a jeho synové ho pomazali a volali: Ať žije král!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Když Atalja uslyšela hlas lidu a běžců, kteří opěvovali krále, přišla k lidu do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Rozhlédla se a uviděla krále stojícího u svého sloupu u vchodu a velitele i trubače u krále; všechen lid země se radoval a troubil na trubky a zpěváci s hudebními nástroji oznamovali oslavu. Atalja roztrhla své roucho a volala: Spiknutí, spiknutí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Kněz Jójada vydal příkaz velitelům nad sty ustanoveným nad vojskem a řekl jim: Vyveďte ji z domu mezi řadami; ten, kdo by šel za ní, ať je usmrcen mečem. Kněz totiž řekl: Ať není usmrcena v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Vztáhli na ni ruce a šla ke vchodu Koňské brány královského paláce a tam ji usmrtili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Jójada uzavřel smlouvu mezi sebou, vším lidem a králem, že budou Hospodinovým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Všechen lid vešel do Baalova domu a strhl ho. Jeho oltáře a jeho obrazy roztřískali a Baalova kněze Matána před oltářem zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Jójada vložil dozor nad Hospodinovým domem do ruky lévijských kněží, které David přidělil nad Hospodinovým domem, aby přinášeli Hospodinu zápalné oběti, jak je napsáno v Mojžíšově zákoně, s radostí a zpěvem podle Davidových pokynů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Ustanovil vrátné nad branami Hospodinova domu, aby nemohl vejít nikdo, kdo je jakýmkoliv způsobem nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Vzal velitele nad sty, vznešené předáky, vládce lidu a všechen lid země a odvedl krále z Hospodinova domu; šli Horní bránou do královského paláce. Pak posadili krále na královský trůn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Všechen lid země se radoval a město mělo klid. Atalju usmrtili mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Jóašovi bylo sedm let, když se stal králem. Kraloval v Jeruzalémě čtyřicet let. Jeho matka se jmenovala Sibja z Beer–šeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Jóaš činil to, co je správné v Hospodinových očích, po všechny dny kněze Jójady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Jójada pro něho vzal dvě ženy, takže zplodil syny a dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Potom se stalo, že ⌈přišlo Jóašovi na mysl⌉ obnovit Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Shromáždil kněze a lévity a řekl jim: Vyjděte do judských měst a rok co rok shromažďujte od všech Izraelců stříbro na opravu domu vašeho Boha. Pospěšte si s tím. Ale lévité nepospíchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Potom si král zavolal vrchního kněze Jójadu a zeptal se ho: Proč jsi nedohlédl na lévity, aby přinesli z Judska a z Jeruzaléma daň, kterou ustanovil Hospodinův otrok Mojžíš a shromáždění Izraele, do stanu svědectví?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Vždyť ničemnice Atalja a její synové vtrhli do Božího domu a všechny svaté věci z Hospodinova domu použili pro baaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Král řekl, aby udělali jednu truhlu a dali ji zvenku do brány Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Potom rozhlásili v Judsku a v Jeruzalémě, aby přinášeli Hospodinu daň, kterou ustanovil Izraeli v pustině Boží otrok Mojžíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Všichni předáci a všechen lid se radovali, přinášeli daň a házeli do truhly, až byla plná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'I stalo se, když přinesli prostřednictvím lévitů truhlu ke královskému dozorci a když viděli, že je tam již mnoho stříbra, přišel královský písař a dohlížitel vrchního kněze, vyprázdnili truhlu, vzali ji a vrátili ji zpět na místo. Toto dělali den co den a nashromáždili množství stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Král a Jójada ho pak dávali dílovedoucím práce na Hospodinově domě. Ti najímali kameníky a řemeslníky na obnovu Hospodinova domu a také kováře a kovo tepce na opravu Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Dílovedoucí konali svou práci, takže opravné práce pod jejich vedením postupovaly. Postavili Boží dům do původní podoby a opravili ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Když to dokončili, přinesli před krále a Jójadu zbytek stříbra. Ten z něho udělal předměty pro Hospodinův dům, předměty pro bohoslužbu a přinášení obětí, kadidlové pánvičky a jiné zlaté a stříbrné předměty. Zápalné oběti se přinášely v Hospodinově domě ustavičně po všechny Jójadovy dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Jójada zestárl, byl sytý dnů a zemřel. Bylo mu sto třicet let, když zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Pohřbili ho spolu s králi v Městě Davidově, protože prokazoval dobro Izraeli, Bohu i jeho domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Po Jójadově smrti však přišla judská knížata a klaněla se králi. ⌈Tehdy je král uposlechl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Opustili dům Hospodina, Boha svých otců, a sloužili posvátným kůlům a modlářským zpodobeninám. Kvůli tomuto jejich provinění dopadlo na Judsko a Jeruzalém rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Posílal jim proroky, aby je obrátili zpět k Hospodinu. Varovali je, ale oni neposlouchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'A Duch Boží vyzbrojil Zekarjáše, syna kněze Jójady. Postavil se před lid a řekl jim: Toto praví Bůh: Proč přestupujete Hospodinovy příkazy? Neuspějete! Protože jste opustili Hospodina, on opustí vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Spikli se proti němu a na nádvoří Hospodinova domu na něj z králova příkazu házeli kamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Král Jóaš nepamatoval na milosrdenství, které mu prokázal jeho otec Jójada, a zabil jeho syna. Když Zekarjáš umíral, řekl: Ať pohledí na to Hospodin a povolá ho k odpovědnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'I stalo se ⌈na konci roku,⌉ že proti němu vytáhlo aramejské vojsko. Přitáhli do Judska a Jeruzaléma, pozabíjeli z lidu všechny předáky lidu a všechnu kořist po nich poslali králi do Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Ačkoliv aramejské vojsko přitáhlo s nemnoha muži, Hospodin vydal do jejich ruky velmi veliké vojsko, protože opustili Hospodina, Boha svých otců. Tak vykonali soud nad Jóašem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Když od něj odtáhli, zanechali ho ⌈těžce nemocného.⌉ Spikli se proti němu jeho otroci za prolitou krev synů kněze Jójady a zabili ho na jeho posteli. Zemřel a pohřbili ho v Městě Davidově. Nepohřbili ho však v královských hrobech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Toto jsou ti, kdo se proti němu spikli: Zábad, syn Amónky Šimeáty, a Józabad, syn Moábky Šimríty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Jeho synové, množství výnosů proti němu a základní opravy Božího domu jsou zapsány ve výkladu Knihy králů. Po něm se stal králem jeho syn Amasjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amasjášovi bylo dvacet pět let, když se stal králem, a kraloval v Jeruzalémě dvacet devět let. Jeho matka se jmenovala Jóadan z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Činil to, co je správné v Hospodinových očích, ovšem ne celým srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'I stalo se, když bylo království pevně ⌈v jeho ruce,⌉ že zabil své otroky, kteří ubili krále, jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Ale jejich syny neusmrtil, jak je napsáno v zákoně, v knize Mojžíšově, že přikázal Hospodin: Ať nezemřou otcové kvůli synům ani synové ať nezemřou kvůli otcům, ale každý ať zemře za svůj hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Amasjáš shromáždil Judejce a ustanovil je podle ⌈otcovských domů⌉ za ⌈velitele nad tisíci a za velitele nad sty⌉ v celém Judovi a Benjamínovi. Spočítal je od věku dvaceti let výše a shledal, že jich je tři sta tisíc vybraných mužů schopných táhnout s armádou a chopit se ⌈oštěpu a štítu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Najal také v Izraeli sto tisíc ⌈udatných hrdinů⌉ za sto talentů stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Přišel však k němu muž Boží a řekl: Králi, izraelská armáda ať s tebou netáhne, protože Hospodin není s Izraelem, s žádným ze synů Efrajimových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ale táhni sám, připrav a posilni se k boji, jinak tě Bůh přivede k pádu před nepřítelem. Vždyť Bůh má sílu pomoci i přivést k pádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amasjáš se zeptal muže Božího: A co mám dělat se sty talenty, které jsem dal izraelskému oddílu? Muž Boží odpověděl: Hospodin ti může dát mnohem víc než to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Amasjáš oddělil oddíl, který k němu přišel z Efrajima, aby šli domů. Ti vzpláli proti Judejcům velkým hněvem a vrátili se domů s planoucím hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amasjáš se však vzchopil a vedl svůj lid. Vytáhl do Solného údolí a pobil deset tisíc synů Seíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Deset tisíc zajali synové Judovi živých. Přivedli je na vrchol skály a hodili je z vrcholu skály, takže se všichni roztříštili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Příslušníci oddílu, který Amasjáš poslal zpět, aby netáhli s ním do boje, vtrhli do judských měst od Samaří až po Bét–chorón, pobili v nich tři tisíce lidí a uloupili mnoho kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'I stalo se potom, co Amasjáš přišel z boje proti Edómcům, že přinesl bohy synů Seíru, ustanovil si je za bohy, klaněl se před nimi a pálil jim oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Hospodin vzplanul proti Amasjášovi hněvem a poslal k němu proroka, který mu řekl: Proč se dotazuješ bohů národa, kteří nevysvobodili svůj lid ze tvé ruky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'I stalo se, když k němu mluvil, že mu Amasjáš řekl: Cožpak jsme tě ustanovili za králova rádce? Přestaň! Proč by tě měli zabít? Prorok přestal, ale řekl: Vím, že Bůh se rozhodl tě zničit, protože jsi toto spáchal a neuposlechl jsi mou radu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Judský král Amasjáš se poradil a vzkázal izraelskému králi Jóašovi, synu Jóachaza, syna Jehúova: Pojď, střetneme se tváří v tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Izraelský král Jóaš vzkázal judskému králi Amasjášovi: Libanonské trní vzkázalo libanonskému cedru: Dej svou dceru mému synovi za ženu. Polní zvěř libanonská prošla a pošlapala to trní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Říkáš si: Hle, pobils Edómce -- a tvé srdce ⌈prahne po slávě.⌉ Jen seď doma. Proč by ses měl zaplétat se zlem a padnout ty a Juda s tebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Ale Amasjáš neposlechl. Bylo to totiž od Boha, aby je vydal do jeho ruky, protože se dotazovali edómských bohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Izraelský král Jóaš vytáhl a střetl se tváří v tvář s judským králem Amasjášem v Bét–šemeši v Judsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Juda byl od Izraele poražen a všichni utíkali ke svým stanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Judského krále Amasjáše, syna Jóaše, syna Jóachazova, chytil izraelský král Jóaš v Bét–šemeši. Přivedl jej do Jeruzaléma a protrhl jeruzalémské hradby od Efrajimské brány až k bráně Rohové, na čtyři sta loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Pobral všechno zlato a stříbro a všechny předměty, které se nacházely v Božím domě, u Obéd–edóma a v pokladnicích královského paláce, i rukojmí a vrátil se do Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Judský král Amasjáš, syn Jóašův, žil po smrti izraelského krále Jóaše, syna Jóachazova, patnáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Ostatní Amasjášovy činy, první i poslední, jsou zapsány v Knize judských a izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Od doby, kdy se Amasjáš odvrátil od Hospodina, osnovali proti němu spiknutí v Jeruzalémě, a tak utekl do Lakíše. Poslali však za ním do Lakíše a usmrtili ho tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Naložili ho pak na koně a pohřbili ho s jeho otci v městě Judově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Všechen judský lid vzal Uzijáše, kterému bylo šestnáct let, a ustanovili ho králem místo jeho otce Amasjáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'On vystavěl Elót a vrátil ho Judsku potom, co král Amasjáš ulehl se svými otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Uzijášovi bylo šestnáct let, když se stal králem, a kraloval v Jeruzalémě padesát dva let. Jeho matka se jmenovala Jekolja z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Činil to, co bylo správné v Hospodinových očích, stejně jako to činil jeho otec Amasjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'I stalo se, že hledal Boha ve dnech Zekarjáše, ⌈zkušeného v Božích viděních.⌉ Ve dnech, kdy hledal Hospodina, mu Bůh dopřával úspěch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Vytáhl a bojoval s Pelištejci. Protrhl hradby Gatu, hradby Jabne a hradby Ašdódu a vystavěl města kolem Ašdódu a mezi Pelištejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'A Bůh mu pomáhal proti Pelištejcům, proti Arabům sídlícím v Gúr–baalu a Meúnejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Amónci dávali Uzijášovi dávky a ⌈pověst o něm se dostala⌉ až na hranice Egypta, neboť se velmi vzmáhal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Uzijáš vystavěl v Jeruzalémě věže, a to na Rohové bráně, na Údolní bráně a na rohu, a opevnil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Vystavěl také věže v pustině a vytesal mnoho cisteren, protože měl mnoho dobytka v Šefele a na rovině; měl také ⌈zemědělce a vinaře⌉ na horách a na Karmelu, neboť ⌈miloval půdu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Uzijáš měl vojsko bojovníků schopných táhnout s armádou v oddílech podle počtu vyměřeného skrze písaře Jeíela a správce Maasejáše, pod velením Chananjáše, jednoho z králových velitelů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Celkový počet předáků rodů, udatných hrdinů, byl dva tisíce šest set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Pod jejich velením bylo armádní vojsko, tři sta sedm tisíc pět set bojovníků schopných vojensky pomáhat králi proti nepříteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Uzijáš pro ně, pro celou armádu, připravil štíty, ⌈oštěpy, přilby, pancíře,⌉ luky a praky na vrhání kamenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Udělal v Jeruzalémě důmyslné vynálezy, vymyšlené ⌈pro umístění⌉ na věžích a rozích ke střílení šípů a vrhání velkých kamenů. Jeho jméno proniklo až do dalekých končin, neboť se mu dostalo podivuhodné pomoci, takže se stal velmi mocným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Když zesílil, povýšilo se jeho srdce, až nakonec ⌈jednal zvráceně.⌉ Zpronevěřil se Hospodinu, svému Bohu, a vešel do Hospodinova chrámu, aby pálil kadidlo na kadidlovém oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Přišel za ním kněz Azarjáš a s ním osmdesát Hospodinových kněží, udatných mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, '⌈Postavili se proti⌉ králi Uzijášovi a řekli mu: Tobě, Uzijáši, nenáleží pálit Hospodinu kadidlo, ale kněžím, synům Áronovým, kteří jsou posvěceni, aby pálili kadidlo. Odejdi ze svatyně, protože ses zpronevěřil a nebude ti to ke cti od Hospodina Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Uzijáš se rozčílil. V ruce měl kadidelnici, aby pálil kadidlo. A jak se rozčílil na kněze, vyrazilo se mu na čele malomocenství v přítomnosti kněží v Hospodinově domě u kadidlového oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Když na něj pohleděl vrchní kněz Azarjáš se všemi kněžími, uviděli, že je na čele malomocný, takže ho odtamtud rychle vyváděli. On sám si pospíšil, aby odešel, neboť jej Hospodin zasáhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Král Uzijáš byl postižen malomocenstvím až do dne své smrti. Bydlel v odděleném domě jako malomocný, neboť byl vyobcován z Hospodinova domu. Jeho syn Jótam byl nad královským palácem a soudil lid země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Ostatní Uzijášovy činy, první i poslední, zapsal prorok Izajáš, syn Amósův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Uzijáš ulehl se svými otci a pohřbili ho s jeho otci na pohřebišti, které patřilo králům, neboť řekli: Byl malomocný. Po něm se stal králem jeho syn Jótam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jótamovi bylo dvacet pět let, když se stal králem, a kraloval v Jeruzalémě šestnáct let. Jeho matka se jmenovala Jerúša, dcera Sádokova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Činil to, co je správné v Hospodinových očích, stejně jako to činil jeho otec Uzijáš. Nevešel ovšem do Hospodinova chrámu. Lid stále jednal zvráceně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'On postavil Horní bránu Hospodinova domu a také velmi stavěl na ófelských hradbách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Vystavěl města v judských horách a v lesích postavil pevnosti a věže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Bojoval také s králem synů Amónových a přemohl je. Synové Amónovi mu v tom roce dali sto talentů stříbra, deset tisíc kórů pšenice a deset tisíc kórů ječmene. To mu přinesli synové Amónovi i ve druhém a třetím roce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Jótam se vzmáhal, protože ⌈upevnil své cesty⌉ před Hospodinem, svým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Ostatní Jótamovy činy, všechny jeho boje a cesty, jsou zapsány v Knize izraelských a judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Bylo mu dvacet pět let, když se stal králem, a kraloval v Jeruzalémě šestnáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Jótam ulehl se svými otci a pohřbili ho v Městě Davidově. Po něm se stal králem jeho syn Achaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Achazovi bylo dvacet let, když se stal králem, a šestnáct let kraloval v Jeruzalémě. Nečinil to, co je správné v Hospodinových očích, jako to činil jeho otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Chodil po cestách izraelských králů a také udělal lité modly baalům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Obětoval v údolí Hinómova syna a spálil své syny ohněm podle ohavností pohanských národů, které Hospodin před syny Izraele vyhnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Obětoval a pálil kadidlo na návrších a kopcích a pod každým zeleným stromem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Hospodin, jeho Bůh, jej vydal do ruky aramejského krále; Aramejci na něj udeřili a odvedli mu ⌈mnoho zajatců⌉ a přivedli je do Damašku. Také byl vydán do ruky krále izraelského, který mu způsobil velikou porážku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pekach, syn Remaljášův, zabil v Judsku v jediném dni sto dvacet tisíc mužů, samé bojovníky, protože opustili Hospodina, Boha svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Efrajimský hrdina Zikrí zabil králova syna Maasejáše, Azríkama, představeného paláce, a Elkánu, druhého po králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Synové Izraele zajali ze svých bratrů dvě stě tisíc žen, synů a dcer a také uloupili mnoho kořisti. Přinesli tu kořist do Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Byl tam Hospodinův prorok jménem Óded. Vyšel proti armádě přicházející do Samaří a řekl jim: Hle, pro svou zlobu vůči Judejcům, je Hospodin, Bůh vašich otců, vydal do vaší ruky. Povraždili jste je však s běsněním dosahujícím do nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'A teď si hodláte podmanit obyvatele Judska a Jeruzaléma za otroky a otrokyně. Cožpak není dost vašich provinění proti Hospodinu, vašemu Bohu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Nyní mě poslechněte a pošlete zajatce, které jste odvedli od svých bratrů, zpět. Vždyť je na vás Hospodinův planoucí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Někteří z předáků synů Efrajimových -- Azarjáš, syn Jóchananův, Berekjáš, syn Mešilemótův, Chizkijáš, syn Šalúmův, a Amasa, syn Chadlajův, -- povstali proti těm, kteří přicházeli z válečného tažení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'a řekli jim: Nevoďte sem ty zajatce! ⌈Vždyť hodláte přidat naše provinění vůči Hospodinu k našim hříchům a proviněním, ačkoliv⌉ naše provinění je velké a na Izraeli je Hospodinův planoucí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Ozbrojenci tedy propustili zajatce a kořist před knížaty a ⌈celým shromážděním.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Povstali muži, kteří byli jmenovitě určeni, ujali se zajatců a z kořisti oblékli všechny nahé ⌈ mezi nimi.⌉ Když je oblékli a obuli, nakrmili a napojili a pomazali je olejem, všechny vyčerpané vedli na oslech a přivedli je do Jericha, Palmového města, k jejich bratrům. Pak se vrátili do Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'V té době vzkázal král Achaz asyrskému králi, aby mu pomohl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Edómci totiž znovu přitáhli, pobili Judejce a odvedli zajatce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'A Pelištejci vtrhli do měst v Šefele a v Negebu Judově a dobyli Bét–šemeš, Ajalón, Gederót, Sóko a jeho vesnice, Timnu a její vesnice, Gimzo a jeho vesnice a usadili se tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Hospodin pokořil Judejce kvůli izraelskému králi Achazovi, protože ⌈dovolil, aby se v Judsku šířila nepravost,⌉ a zpronevěřil se věrolomností vůči Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Přitáhl proti němu Tilgat–pilneser, způsobil mu soužení a neposílil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Achaz totiž vyraboval Hospodinův dům a královský palác i knížata a dal to asyrskému králi, ale nebylo mu to ku pomoci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'V době, kdy mu bylo úzko, se tento král Achaz ještě více zpronevěřil vůči Hospodinu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Obětoval bohům Damašku, kteří ho porazili. Řekl si totiž: Bohové aramejských králů jim pomohli. Budu jim obětovat a pomůžou mi. Oni však přivedli k pádu jej i celý Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Achaz sebral předměty Božího domu, usekal předměty Božího domu, zavřel dveře Hospodinova domu a udělal oltáře na každém nároží v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'V každém jednotlivém judském městě udělal návrší, aby se tam pálilo kadidlo jiným bohům. Tak provokoval ke hněvu Hospodina, Boha svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Ostatní jeho činy a všechno jeho jednání, první i poslední, jsou zapsány v Knize judských a izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Achaz ulehl se svými otci a pohřbili ho ve městě, v Jeruzalémě, ale nepřinesli ho do hrobů izraelských králů. Po něm se stal králem jeho syn Chizkijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Chizkijášovi bylo dvacet pět let, když se stal králem, a kraloval v Jeruzalémě dvacet devět let. Jeho matka se jmenovala Abíjá, dcera Zekarjášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Činil to, co je správné v Hospodinových očích, stejně jako to činil jeho otec David.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'V prvním měsíci prvního roku svého kralování otevřel dveře Hospodinova domu a opravil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Přivedl kněze a lévity a shromáždil je na východním náměstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Řekl jim: Poslyšte mě, lévité! Nyní se posvěťte a posvěťte dům Hospodina, Boha svých otců, a vyneste ze svatyně nečisté věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Neboť naši otcové se zpronevěřili a páchali to, co je zlé v očích Hospodina, našeho Boha. Opustili ho, odvrátili svou tvář od Hospodinova příbytku a ⌈obrátili se k němu zády.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Zavřeli také dveře předsíně, uhasili lampy, neobětovali kadidlo a nepřinášeli ve svatyni zápalné oběti Bohu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Hospodinovo rozhořčení dopadlo na Judsko a Jeruzalém a učinil je předmětem úděsu, hrůzy a úžasu, jak vidíte na vlastní oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Proto naši otcové padli mečem, naši synové, naše dcery a ženy jsou kvůli tomu v zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nyní mám na srdci uzavřít smlouvu s Hospodinem, Bohem Izraele, aby se od nás odvrátil jeho planoucí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Nyní, moji synové, nebuďte nedbalí, protože vás Hospodin vyvolil, abyste před ním stáli, sloužili mu, byli jeho služebníky a pálili mu kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Povstali tito lévité: Machat, syn Amsajův, a Jóel, syn Azarjášův, ze synů Kehatových; ze synů Merarího: Kíš, syn Abdího, a Azarjáš, syn Jehalelélův; z Geršónovců: Jóach, syn Zimův, a Eden, syn Jóachův;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'ze synů Elísáfanových: Šimrí a Jeíel; ze synů Asafových: Zekarjáš a Matanjáš;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'ze synů Hémanových: Jechíel a Šimeí; ze synů Jedútúnových: Šemajáš a Uzíel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Shromáždili své bratry, posvětili se a na králův příkaz šli podle Hospodinova slova očistit Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Kněží vešli dovnitř Hospodinova domu, aby ho vyčistili. Každou nečistotu, kterou nalezli v Hospodinově chrámu, vynesli na nádvoří Hospodinova domu. Tam to převzali lévité a vynesli to ven do údolí Kidrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Začali se posvěcovat prvního dne prvního měsíce a osmého dne toho měsíce vešli do Hospodinovy předsíně. Osm dní posvěcovali Hospodinův dům a šestnáctého dne prvního měsíce to dokončili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Pak vešli dovnitř ke králi Chizkijášovi a řekli: Očistili jsme celý Hospodinův dům, oltář pro zápalné oběti a všechny jeho předměty i stůl pro předkladné chleby a všechny jeho předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Všechny předměty, které král Achaz během svého kralování ve své věrolomnosti odstranil, jsme připravili a posvětili. Jsou před Hospodinovým oltářem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Král Chizkijáš časně vstal, shromáždil knížata města a vystoupil do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Přivedli sedm býčků, sedm beranů, sedm beránků a sedm kozlů jako oběť za hřích za království, za svatyni a za Judsko. Král řekl synům Áronovým, kněžím, aby to obětovali na Hospodinově oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Zabíjeli skot, kněží chytali krev a kropili oltář. Zabíjeli berany a krví kropili oltář. Zabíjeli beránky a krví kropili oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Pak přivedli před krále a shromáždění kozly jako oběť za hřích a vložili na ně ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Kněží je zabili a jejich krev přinesli na oltář jako očištění od hříchu, aby získali smíření pro celý Izrael, neboť král přikázal, aby zápalná oběť a oběť za hřích byla za celý Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Ustanovil v Hospodinově domě lévity s činely, harfami a lyrami podle příkazu Davida a Gáda, králova vidoucího, a proroka Nátana, neboť to byl příkaz od Hospodina prostřednictvím jeho proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Lévité stáli s Davidovými nástroji a kněží s trubkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Chizkijáš přikázal, aby přinášeli zápalnou oběť na oltáři. Ve chvíli, kdy ta zápalná oběť začala, začala ⌈Hospodinova píseň⌉ a trubky pod vedením nástrojů izraelského krále Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Celé shromáždění se sklánělo, zpívala se píseň a trubky troubily, a to všechno se dělo, dokud nebyla zápalná oběť dokončena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Když obětování skončilo, král a všichni, kdo byli s ním, poklekli a klaněli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Král Chizkijáš s knížaty řekl lévitům, aby chválili Hospodina slovy Davida a vidoucího Asafa. Chválili s radostí, poklekali a klaněli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Chizkijáš promluvil a řekl: Nyní jste se zasvětili pro Hospodina. Přistupte a přineste do Hospodinova domu obětní hody a oběti díků. Shromáždění přineslo obětní hody a oběti díků a všichni ochotného srdce i zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Počet zápalných obětí, které shromáždění přineslo, byl sedmdesát býků, sto beranů a dvě stě beránků; to všechno přinesli jako zápalnou oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Svatých obětí bylo šest set býků a tři tisíce ovcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Ovšem kněží bylo málo, takže nebyli schopni stáhnout kůži ze všech zápalných obětí. Proto je posílili jejich bratři lévité, dokud nebyla práce dokončena a dokud se neposvětili další kněží. Lévité ⌈se totiž posvěcovali horlivěji⌉ nežli kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Také zápalných obětí bylo mnoho s tukem pokojných obětí a s úlitbami pro zápalnou oběť. Tak byla obnovena služba Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Chizkijáš se vším lidem se radoval z toho, co Bůh připravil pro lid, neboť se to stalo náhle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Chizkijáš vzkázal celému Izraeli a Judsku a také napsal dopisy Efrajimovi a Manasesovi, aby přišli do Hospodinova domu v Jeruzalémě slavit Velikonoce Hospodinu, Bohu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Král se dohodl se svými knížaty a s celým shromážděním v Jeruzalémě, že budou slavit Velikonoce ve druhém měsíci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'protože je nemohli slavit v tom čase, neboť kněží se nestačili posvětit a lid se neshromáždil v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, '⌈Líbilo se to králi i celému⌉ shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Stanovili, ⌈aby se rozšířila zpráva⌉ po celém Izraeli od Beer–šeby až po Dan, aby přišli slavit Velikonoce Hospodinu, Bohu Izraele, do Jeruzaléma, neboť to dlouho nedělali tak, jak je psáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Běžci běželi s dopisy od krále a jeho knížat po celém Izraeli a Judsku a podle králova příkazu ohlašovali: Synové Izraele, navraťte se k Hospodinu, Bohu Abrahama, Izáka a Izraele, aby se vrátil k těm z vás, kteří zůstali, kteří vyvázli z ruky asyrských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Nebuďte jako vaši otcové a vaši bratři, kteří se zpronevěřili Hospodinu, Bohu svých otců, a učinil je předmětem hrůzy, jak to vidíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Nezatvrzujte nyní svou šíji jako vaši otcové. Poddejte se Hospodinu a vejděte do jeho svatyně, kterou navěky posvětil. Služte Hospodinu, svému Bohu, aby se od vás odvrátil jeho planoucí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Jestliže se navrátíte k Hospodinu, vaši bratři a vaši synové dojdou slitování před svými vězniteli a vrátí se do této země. Vždyť Hospodin, váš Bůh, je milostivý a soucitný, neodvrátí od vás svou tvář, jestliže se k němu navrátíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Běžci procházeli od města k městu ⌈územím Efrajima a Manasesa⌉ až k Zabulónu. Tam se jim však vysmívali a posmívali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Jenom někteří z Ašera, Manasesa a Zabulóna se pokořili a přišli do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Také na Judejcích spočinula ⌈Boží ruka⌉ a dala jim jednomyslnost, aby splnili příkaz krále a knížat podle Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'V Jeruzalémě se shromáždilo množství lidu, aby v druhém měsíci slavili svátek nekvašených chlebů; bylo to převeliké shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Povstali a odstranili oltáře, které byly v Jeruzalémě. Odstranili také všechny kadidlové oltáře a hodili je do údolí Kidrónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Čtrnáctého dne druhého měsíce zabíjeli velikonoční oběti. Kněží a lévité byli zahanbeni; posvětili se a přinesli do Hospodinova domu zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Stáli na svém místě podle nařízení pro ně, podle zákona ⌈Mojžíše, muže Božího.⌉ Kněží kropili krví převzatou od lévijců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Protože ve shromáždění byli mnozí, kteří se neposvětili, lévijci zabíjeli velikonoční oběti pro všechny nečisté, aby je posvětili Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Většina lidu totiž, mnozí z Efrajima, Manasesa, Isachara a Zabulóna, se neočistili, a nejedli velikonoční oběť tak, jak je psáno. Ale Chizkijáš se za ně modlil slovy: Ať ⌈dobrotivý Hospodin⌉ daruje smíření');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'každému, kdo zaměřil své srdce na hledání Boha, Hospodina, Boha svých otců, ačkoliv není čist podle očišťování platného pro svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Hospodin ⌈Chizkijáše vyslyšel⌉ a uzdravil lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Synové Izraele, kteří se nacházeli v Jeruzalémě, slavili svátek nekvašených chlebů po sedm dní s velikou radostí. Lévité a kněží chválili Hospodina den co den ⌈se silnými nástroji Hospodina.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Chizkijáš promluvil ⌈k srdci⌉ všech lévijců, kteří byli ⌈velmi zruční ve službě Hospodinu,⌉ aby jedli sváteční oběti po sedm dní, obětovali pokojné oběti a chválili Hospodina, Boha svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Celé shromáždění se dohodlo slavit dalších sedm dní. A tak slavili svátek dalších sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Judský král Chizkijáš totiž daroval shromáždění tisíc býčků a sedm tisíc ovcí. Knížata darovala shromáždění tisíc býčků a deset tisíc ovcí. Kněží se posvětili ve velkém množství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'A tak se radovalo celé shromáždění Judejců, kněží i lévijci, celé shromáždění těch, kteří přišli z Izraele, cizinci, kteří přišli z izraelské země i ti, kteří bydleli v Judsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'V Jeruzalémě byla veliká radost, neboť ode dnů izraelského krále Šalomouna, syna Davidova, nebylo v Jeruzalémě nic takového.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Lévijští kněží povstali a požehnali lidu. Jejich hlas byl vyslyšen a jejich modlitba přišla do jeho svatého příbytku, do nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Když to všechno skončilo, všichni Izraelci, kteří se tam nacházeli, vyšli do judských měst a roztřískali posvátné sloupy, pokáceli posvátné kůly, strhli návrší a oltáře po celém území Judy, Benjamína, Efrajima a Manasesa; úplně je zničili. Pak se všichni synové Izraele vrátili -- každý na své vlastnictví, do svých měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Chizkijáš ustanovil ⌈oddíly kněží a⌉ lévijců podle jejich oddílů, každého podle jeho služby, kněze i lévijce, pro zápalné i pokojné oběti, aby sloužili, vzdávali díky a chválili v branách ⌈Hospodinova tábora.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Určil též králův podíl z jeho majetku pro zápalné oběti: Pro zápalné oběti ranní a večerní, zápalné oběti pro soboty, novoluní a svátky, jak je psáno v Hospodinově zákoně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Přikázal lidu, obyvatelům Jeruzaléma, aby dávali podíly kněžím a lévitům, aby se posilnili v Hospodinově zákoně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Když se ten příkaz rozšířil, synové Izraele přinášeli velké množství prvotin obilí, nového vína, oleje, medu a vší úrody pole. A také přinesli velký desátek ze všeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Synové Izraele a Judy, kteří bydleli v judských městech, také přinášeli desátek ze skotu a bravu a desátek ze svatých věcí posvěcených Hospodinu, jejich Bohu, a dávali to na ⌈velké hromady.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Ve třetím měsíci začali hromady zakládat a v sedmém měsíci to dokončili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Když přišli Chizkijáš a knížata a uviděli ty hromady, dobrořečili Hospodinu a jeho lidu Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Chizkijáš se vyptával kněží a lévitů na ty hromady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Odpověděl mu vrchní kněz Azarjáš z domu Sádokova a řekl: Od doby, kdy začali přinášet dary pozdvihování do Hospodinova domu, jedli jsme, nasytili se a mnoho ještě zůstalo. Protože Hospodin požehnal svému lidu, toto množství zbylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Chizkijáš přikázal připravit komory v Hospodinově domě. Připravili je');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'a přinášeli tam poctivě dary pozdvihování, desátek a svaté věci. Vévodou nad nimi byl lévita Kónanjáš a jako druhý jeho bratr Šimeí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jechíel, Azazjáš, Nachat, Asáel, Jerímót, Józabad, Elíel, Jismakjáš, Machat a Benajáš byli z určení krále Chizkijáše a představeného Božího domu Azarjáše dohlížiteli pod vedením Kónanjáše a jeho bratra Šimeího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Lévita Kóré, syn Jimny, vrátný Východní brány, byl nad dobrovolnými dary Bohu, aby vydával z Hospodinových darů pozdvihování a z nejsvětějších věcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Pod jeho vedením byli Eden, Minjamín, Jéšua, Šemajáš, Amarjáš a Šekanjáš v kněžských městech, aby vydávali poctivě svým bratrům podle oddílů, jak ⌈velkému tak i malému.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Kromě toho i těm mužského pohlaví od věku tří let výše, kteří byli zapsáni do rodokmenu, každému, kdo přicházel do Hospodinova domu podle každodenního určení podle jejich práce podle jejich služby, podle jejich oddílů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Rodokmeny kněží byly podle domu jejich otců a lévité od věku dvaceti let výše podle jejich služby, podle jejich oddílů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Do rodokmenů byli zapsáni se všemi svými malými dětmi, svými ženami, syny a dcerami, v celém shromáždění, protože věrně posvětili svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Synům Áronovým, kněžím, žijícím na polích pastvin jejich měst, pro každé jednotlivé město byli jmenovitě určeni muži, aby dávali podíly všem mužského pohlaví mezi kněžími a všem, kdo byli zapsáni mezi lévijci do rodokmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Tak jednal Chizkijáš po celém Judsku. Činil to, co je dobré, správné a pravé před Hospodinem, jeho Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Všechno dílo, které začal -- ohledně služby Božího domu, ohledně zákona a ohledně příkazu hledat svého Boha -- činil ⌈celým svým srdcem⌉ a dařilo se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Po těchto událostech a Chizkijášově věrnosti přitáhl asyrský král Sancheríb. Přitáhl do Judska a utábořil se kolem opevněných měst. Myslel si, že do nich pronikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Když Chizkijáš viděl, že Sancheríb přitáhl a ⌈zamýšlí bojovat⌉ proti Jeruzalému,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'dohodl se se svými knížaty a hrdiny, že ucpou vodní prameny, které jsou venku za městem, a oni mu pomohli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Shromáždilo se mnoho lidu a ucpali všechny prameny a potok proudící uprostřed země se slovy: Proč by měli asyrští králové přitáhnout a najít hojnost vody?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Vzchopil se a postavil všechny pobořené hradby a vyhotovil na nich věže a další hradby. Opravil Miló, Město Davidovo, a připravil množství oštěpů a štítů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Ustanovil nad lidem válečné velitele, shromáždil je k sobě na náměstí u městské brány a promluvil k jejich srdcím:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '⌈Posilněte se a buďte odvážní, nebojte se a neděste⌉ se asyrského krále a celého davu, který je s ním, protože s námi ⌈ jich je víc⌉ než s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'S ním je ⌈tělesná síla,⌉ ale s námi je Hospodin, náš Bůh, aby nám pomohl a bojoval náš boj. Lid se opřel o slova judského krále Chizkijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Potom poslal asyrský král Sancheríb své otroky do Jeruzaléma, (zatímco on byl u Lakíše a s ním celé jeho vojsko), k judském králi Chizkijášovi a ke všem Judejcům v Jeruzalémě se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Toto praví asyrský král Sancheríb: Na co spoléháte, že zůstáváte v obležení v Jeruzalémě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Chizkijáš vás navádí, aby vás nechal zemřít hladem a žízní, když říká: Hospodin, náš Bůh, nás vysvobodí z ruky asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Což to nebyl Chizkijáš, kdo odstranil jeho návrší a jeho oltáře a řekl Judejcům a obyvatelům Jeruzaléma: Před jediným oltářem se klaňte a na něm obětujte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Cožpak nevíte, jak jsem naložil já a moji otcové se všemi národy země? Byli bohové národů těch zemí opravdu schopni vysvobodit svou zemi z mé ruky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Který ze všech bohů těchto národů, jež moji otcové zasvětili zkáze, byl schopen vysvobodit svůj lid z mé ruky? Že by byl váš Bůh schopen vysvobodit vás z mé ruky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Nuže ať vás Chizkijáš nepodvádí a ať vás takto nenavádí. Nevěřte mu, protože žádný bůh žádného národa a království nebyl schopen vysvobodit svůj lid z ruky mé ani z ruky mých otců. Tak ani vaši bohové nevysvobodí vás z mé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'A ještě další věci mluvili jeho otroci proti Bohu a proti jeho otroku Chizkijášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Napsal také dopisy, aby hanobil Hospodina, Boha Izraele, a mluvil proti němu takto: Jako nevysvobodili bohové národů těch zemí svůj lid z mé ruky, tak ani Bůh Chizkijášův nevysvobodí jeho lid z mé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Volali hlasitě judsky na jeruzalémský lid, který byl na hradbách, aby je zastrašili a vyděsili, aby dobyli město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Mluvili o Bohu Jeruzaléma jako o bozích národů země, ⌈díle lidských rukou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Král Chizkijáš i prorok Izajáš, syn Amósův, se proto modlili a volali o pomoc k nebesům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Hospodin poslal anděla, který vyhladil všechny udatné hrdiny, vévody a velitele v táboře asyrského krále, takže se vrátil s hanbou do své země. Když vešel do domu svého boha, někteří z jeho potomků jej tam srazili mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Hospodin zachránil Chizkijáše a obyvatele Jeruzaléma z ruky asyrského krále Sancheríba a z ruky všech a ⌈dal jim odpočinek od okolních nepřátel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Mnozí přinášeli přídavné oběti Hospodinu do Jeruzaléma a vzácné dary judskému králi Chizkijášovi. Od té doby stoupl v očích všech národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'V oněch dnech Chizkijáš na smrt onemocněl. Modlil se k Hospodinu a ten k němu promluvil a dal mu znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Chizkijáš se však neodvděčil za to, co bylo pro něj vykonáno, nýbrž jeho srdce se povýšilo, a tak dopadlo rozhořčení na něj i na Judu a Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Pak se Chizkijáš v povýšenosti svého srdce pokořil, on i obyvatelé Jeruzaléma, takže Hospodinovo rozhořčení na ně nepřišlo ve dnech Chizkijášových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Chizkijáš měl velmi mnoho bohatství a slávy. Pořídil si pokladnice na stříbro, zlato, drahokamy, balzámy, štíty a všelijaké vzácné předměty');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'a také sklady na úrodu obilí, nového vína a oleje a stáje pro ⌈všelijaké druhy dobytka⌉ a ⌈stáda pro stáje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Pořídil si také města a mnoho stád bravu a skotu, protože Bůh mu dal velmi mnoho majetku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Byl to Chizkijáš, kdo ucpal zdroj vody Horního Gíchónu a svedl ho spodem na západ do Města Davidova. Chizkijášovi se dařilo při všem jeho díle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Když ale dorazili vyslanci babylonských knížat poslaní k němu poptat se na znamení, které se v zemi stalo, Bůh ho opustil, aby ho vyzkoušel a poznal vše, co je v jeho srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Ostatní Chizkijášovy činy a jeho ⌈zbožné skutky ⌉ jsou zapsány ve vidění proroka Izajáše, syna Amósova, a v Knize judských a izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Chizkijáš ulehl se svými otci a pohřbili ho ⌈ve svahu⌉ do hrobů synů Davidových. Při jeho smrti mu všichni Judejci a obyvatelé Jeruzaléma vzdávali čest. Po něm se stal králem jeho syn Menaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Menašemu bylo dvanáct let, když se stal králem, a kraloval v Jeruzalémě padesát pět let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Páchal to, co je zlé v Hospodinových očích, podle ohavností národů, které Hospodin před syny Izraele vyhnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Znovu postavil návrší, která jeho otec Chizkijáš strhl. Postavil oltáře baalům, udělal posvátné kůly a klaněl se celému nebeskému zástupu a sloužil mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Též postavil oltáře v Hospodinově domě, o kterém Hospodin řekl: V Jeruzalémě bude navěky mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Na obou nádvořích Hospodinova domu postavil oltáře pro celý nebeský zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'On provedl své syny ohněm v údolí syna Hinómova, zabýval se hadačstvím, znameními a čarováním, ustanovil ty, kdo vyvolávají duchy zemřelých, a věštce. Páchal mnoho toho, co je zlé v Hospodinových očích, a tak jej provokoval k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Tesanou sochu modly, kterou udělal, postavil v Božím domě, o kterém Bůh Davidovi a jeho synu Šalomounovi řekl: V tomto domě a v Jeruzalémě, který jsem vyvolil ze všech izraelských kmenů, postavím navěky své jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Nezpůsobím již, aby noha Izraelců odešla ze země, kterou určil vašim otcům, pokud ovšem budou zachovávat a plnit všechno, co jsem jim přikázal, celý zákon, ustanovení a nařízení vydaná prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Avšak Menaše svedl Judejce a obyvatele Jeruzaléma, takže páchali horší věci nežli národy, které před syny Izraele Hospodin vyhladil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Hospodin mluvil k Menašemu a k jeho lidu, ale nevěnovali mu pozornost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Proto na ně Hospodin přivedl velitele armády asyrského krále. Ti zajali Menašeho s háčky, spoutali ho bronzovými okovy a dovedli ho do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Když mu bylo úzko, snažil se udobřit tvář Hospodina, svého Boha, a velmi se pokořil před Bohem svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Modlil se k němu a on se k němu sklonil, vyslyšel jeho úpěnlivou prosbu a přivedl ho zpět do Jeruzaléma, do jeho království. Tak Menaše poznal, že ⌈Hospodin je Bůh.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Potom postavil vnější hradby Města Davidova západně od Gíchónu, v údolí a kudy se jde do Rybné brány, obehnal Ófel a postavil je velmi vysoko. Do všech opevněných měst v Judsku ustanovil velitele vojska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Odstranil cizí bohy a sochu z Hospodinova domu a všechny oltáře, které postavil na hoře Hospodinova domu a v Jeruzalémě, a hodil je ven za město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Obnovil Hospodinův oltář a obětoval na něm oběti pokojné a oběti díků. Řekl Judejcům, aby sloužili Hospodinu, Bohu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Lid ale stále obětoval na návrších, ovšem Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Ostatní Menašeho činy, jeho modlitba k jeho Bohu i slova vidoucích, kteří k němu mluvili ve jménu Hospodina, Boha Izraele, jsou v letopisech izraelských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Jeho modlitba a jak se k němu Bůh sklonil, všechny jeho hříchy a jeho věrolomnost, místa, na kterých postavil návrší a vztyčil posvátné kůly a modlu, dříve než se pokořil, jsou zapsány v letopisech vidoucích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Menaše ulehl se svými otci a pohřbili ho v jeho domě. Po něm se stal králem jeho syn Amón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amónovi bylo dvacet dva let, když se stal králem, a kraloval v Jeruzalémě dva roky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Páchal to, co je zlé v Hospodinových očích, tak jako to činil jeho otec Menaše. Amón obětoval všem modlám, které udělal jeho otec Menaše, a sloužil jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Nepokořil se před Hospodinem, jako se pokořil jeho otec Menaše, ale Amón rozmnožil provinění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Jeho otroci se proti němu spikli a usmrtili ho v jeho domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Avšak lid země ubil všechny, kdo se proti králi Amónovi spikli. Lid země ustanovil králem místo něj jeho syna Jóšijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Jóšijášovi bylo osm let, když se stal králem, a kraloval v Jeruzalémě třicet jedna let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Činil to, co je správné v Hospodinových očích, a chodil po cestách svého otce Davida, neodvrátil se napravo ani nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'V osmém roce svého kralování, když byl ještě mladý, začal hledat Boha svého otce Davida a ve dvanáctém roce začal očišťovat Judsko a Jeruzalém od návrší, posvátných kůlů a tesaných i litých model.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'V jeho přítomnosti strhli oltáře baalů a pokácel kadidlové oltáře, které byly nahoře na nich. Posvátné kůly a tesané i lité modly roztřískal, rozdrtil a rozsypal na hroby těch, kdo jim obětovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Kosti kněží spálil na jejich oltářích. Tak očistil Judsko a Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Ve městech Manasesa, Efrajima, Šimeóna až k Neftalímu a ⌈v troskách okolo nich⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'strhl oltáře a posvátné kůly, tesané modly rozbil a rozdrtil, pokácel všechny kadidlové oltáře v celé izraelské zemi a vrátil se do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'V osmnáctém roce svého kralování, když očistil zemi a chrám, poslal Šáfana, syna Asaljášova, předáka města Maasejáše a kancléře Jóacha, syna Jóachazova, aby opravili dům Hospodina, jeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Přišli k veleknězi Chilkijášovi a dali mu stříbro, přinesené do Božího domu, které shromáždili lévité, strážci prahu, od Manasesa, Efrajima a z celého ostatku Izraele a z celého Judy a Benjamína i od obyvatel Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Dali to do správy dílovedoucích ustanovených nad Hospodinovým domem a ti ho vydávali dělníkům, kteří pracovali v Hospodinově domě na odstranění poškození a na opravě domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Dávali ho tesařům a stavitelům na nákup tesaných kamenů a dřeva na vazby a k zhotovení trámů pro domy, které nechali poničit judští králové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Muži jednali při práci poctivě. Byli nad nimi ustanoveni jako dozorci Jachat a Obadjáš, lévité ze synů Merarího, a Zekarjáš a Mešulám, ze synů Kehatových. Jiní lévité, všichni zkušení ve hře na hudební nástroje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'byli nad nosiči a jako dozorci pro všechny dělníky pro každou práci. Někteří z lévitů byli písaři, správci a vrátní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Když vynášeli stříbro přinesené do Hospodinova domu, našel kněz Chilkijáš knihu Hospodinova zákona vydaného prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Tu se Chilkijáš ozval a řekl písaři Šáfanovi: Našel jsem v Hospodinově domě knihu zákona. A Chilkijáš dal tu knihu Šáfanovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Šáfan přinesl knihu ke králi a ještě podal králi zprávu: Vše, co bylo svěřeno tvým otrokům, to učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Roztavili stříbro, které se našlo v Hospodinově domě, a dali ho do rukou ustanovených dozorců a do rukou dělníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Pak písař Šáfan oznámil králi: Kněz Chilkijáš mi dal knihu. Nato z ní Šáfan před králem četl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'I stalo se, když král uslyšel slova zákona, že roztrhl své roucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Potom král přikázal Chilkijášovi, Achíkamovi, synu Šáfanovu, Abdónovi, synu Míkovu, písaři Šáfanovi, královskému otroku Asajášovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Jděte a dotažte se Hospodina za mě a za ty, kteří zůstali v Izraeli a v Judsku, ohledně slov této nalezené knihy. Vždyť Hospodinova zloba, která je na nás vylita, je veliká, protože naši otcové nezachovávali Hospodinovo slovo a ne plnili vše, co je zapsáno v této knize.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Chilkijáš a ti, kterým to král přikázal, tedy šli k prorokyni Chuldě, ženě strážce rouch Šalúma, syna ⌈Tokhata, syna Chasrova,⌉ (bydlela v Jeruzalémě v Mišne) a promluvili s ní v tom smyslu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Ona jim řekla: Toto praví Hospodin, Bůh Izraele: Řekněte muži, který vás ke mně poslal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Toto praví Hospodin: Hle, přivedu zlo na toto místo a na jeho obyvatele všechna prokletí zapsaná v knize, kterou četli před judským králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Protože mě opustili a pálili oběti jiným bohům, aby mě provokovali k hněvu každým dílem svých rukou, je má zloba rozlita na toto místo a neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Judskému králi, který vás poslal dotázat se Hospodina, tomu řekněte toto: Takto praví Hospodin, Bůh Izraele, o věcech, které jsi slyšel:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Protože tvé srdce změklo a pokořil ses před Bohem, když jsi slyšel jeho slova o tomto místě a jeho obyvatelích, pokořil ses přede mnou, roztrhl jsi své roucho a plakal jsi přede mnou, také já jsem slyšel, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Hle, připojím tě ke tvým otcům a odebereš se do svého hrobu v pokoji. Tvé oči neuvidí nic z toho zla, které přivedu na toto místo a na jeho obyvatele. Podali tedy králi zprávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Král ⌈dal shromáždit⌉ všechny judské a jeruzalémské starší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Pak král vystoupil do Hospodinova domu a s ním všichni Judejci i obyvatelé Jeruzaléma, kněží, lévité a všechen lid od největšího až po nejmenšího a četl jim všechna slova knihy smlouvy nalezené v Hospodinových domech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Král stál na svém místě a uzavřel před Hospodinem smlouvu, že půjde za Hospodinem, bude celým svým srdcem a celou svou duší zachovávat jeho příkazy, svědectví a ustanovení a plnit slova smlouvy zapsaná v této knize.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Nato k tomu zavázal všechny, kdo byli v Jeruzalémě a Benjamínovi. A obyvatelé Jeruzaléma jednali podle smlouvy Boha, Boha svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Jóšijáš odstranil všechny ohavnosti ze všech zemí, které patřily synům Izraele. Všechny, kdo byli v Izraeli, nutil sloužit Hospodinu, jejich Bohu. Po všechny jeho dny se neodvrátili od Hospodina, Boha svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Jóšijáš slavil v Jeruzalémě Velikonoce Hospodinu. Čtrnáctého dne prvního měsíce zabíjeli velikonoční oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Ustanovil kněze do jejich služby a posilnil je pro službu Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Řekl lévitům, kteří vyučovali celý Izrael a byli svatí Hospodinu: Dejte svatou truhlu do domu, který postavil izraelský král Šalomoun, syn Davidův. Nemusíte ji už nosit na ramenou. Nyní služte Hospodinu, svému Bohu, a jeho lidu Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Připravte se podle domu svých otců, podle svých oddílů, jak je v zápisu izraelského krále Davida a v zápisu jeho syna Šalomouna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Postavte se ve svatyni podle tříd domu otců svých bratrů, synů lidu, oddíl domu otců na lévity.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Zabíjejte velikonoční oběti, posvěťte se a připravte to pro své bratry, aby se jednalo podle Hospodinova slova vydaného prostřednictvím Mojžíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Jóšijáš daroval synům lidu brav, beránky a kůzlata, to vše na velikonoční oběti pro všechny, kdo tam byli, v počtu třicet tisíc kusů a tři tisíce kusů skotu. To bylo z králova majetku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Také jeho knížata darovala lidu, kněžím a lévitům dobrovolné oběti. Chilkijáš, Zekarjáš a Jechíel, představený Božího domu, dali kněžím na velikonoční oběti dva tisíce šest set kusů bravu a tři sta kusů skotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Kónanjáš, Šemajáš a Netanel, jeho bratři, Chašabjáš, Jeíel a Józabad, předáci lévitů, darovali lévitům na velikonoční oběti pět tisíc kusů bravu a pět set kusů skotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Služba byla připravena: Kněží se postavili na své místo a lévité do svých oddílů podle králova příkazu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Zabíjeli velikonoční oběti, kněží ⌈kropili jejich krví ⌉ a lévité stahovali kůži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Oddělovali části pro zápalné oběti, aby je dali skupinám synů lidu podle domu otců na obětování Hospodinu, jak je psáno v knize Mojžíšově. Totéž činili se skotem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Velikonoční oběť pekli na ohni podle nařízení, zatímco svaté věci vařili v hrncích, kotlících a mísách a rychle nosili všem synům lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Potom připravili také pro sebe a kněze, protože kněží, synové Áronovi, přinášeli zápalné oběti a tučné části až do noci, takže lévité připravili oběť pro sebe a kněze, syny Áronovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Zpěváci, synové Asafovi, byli na svých stanovištích podle příkazu Davida, Asafa, Hémana a králova vidoucího Jedútúna; tak i vrátní byli v každé bráně. Nemuseli opustit svou službu, protože jejich bratři lévité pro ně oběť připravili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Onoho dne byla připravena všechna Hospodinova služba, aby slavili Velikonoce a přinášeli zápalné oběti na Hospodinově oltáři podle příkazu krále Jóšijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'V té době slavili synové Izraele, kteří tam byli, Velikonoce a svátek nekvašených chlebů po sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Takové Velikonoce se v Izraeli neslavily ode dnů proroka Samuela. Žádný z izraelských králů neslavil takové Velikonoce, jaké slavil Jóšijáš, kněží, lévité a všichni Judejci a Izraelci, kteří tam byli, a obyvatelé Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Tyto Velikonoce se slavily v osmnáctém roce Jóšijášova kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Po tom všem, kdy Jóšijáš obnovil chrám, vytáhl egyptský král Néko, aby bojoval v Karkemíši u Eufratu. Jóšijáš vytáhl proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Néko k němu poslal posly se slovy: ⌈Co je ti do mě,⌉ judský králi? ⌈Ne táhnu dnes proti tobě, ale proti království, které válčí se mnou,⌉ a Bůh řekl, abych si pospíšil. ⌈Zanech protivení se Bohu,⌉ který je se mnou, ať tě nezničí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Jóšijáš se od něj však neodvrátil, ale bojoval proti němu v přestrojení. Neuposlechl Nékova slova z Božích úst a vytáhl bojovat na pláň Megido.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Střelci krále Jóšijáše postřelili. Král řekl svým otrokům: Vezměte mě odsud, protože jsem velmi raněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Jeho otroci ho vzali z válečného vozu, naložili ho na jeho druhý vůz a dovezli ho do Jeruzaléma. Zemřel a byl pohřben v hrobech svých otců. Všichni Judejci a obyvatelé Jeruzaléma nad Jóšijášem truchlili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremjáš zazpíval nad Jóšijášem žalozpěvy a všichni zpěváci a zpěvačky je pronášejí ve svých žalozpěvech nad Jóšijášem až dodnes. Staly se v Izraeli zvykem a jsou zapsány v žalozpěvech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Ostatní Jóšijášovy činy a jeho zbožné skutky, jak je psáno v Hospodinově zákoně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'jeho činy první i poslední, jsou zapsány v Knize izraelských a judských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Lid země vzal Jóachaza, syna Jóšijášova, a ustanovili ho v Jeruzalémě králem místo jeho otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Jóachazovi bylo dvacet tři let, když se stal králem, a kraloval v Jeruzalémě tři měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Egyptský král ho v Jeruzalémě odstranil a uložil zemi pokutu sto talentů stříbra a talent zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Egyptský král ustanovil králem nad Judskem a Jeruzalémem jeho bratra Eljakíma. Změnil jeho jméno na Jójakím. Jeho bratra Jóachaza Néko vzal a odvedl ho do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Jójakímovi bylo dvacet pět let, když se stal králem, a kraloval v Jeruzalémě jedenáct let. Páchal to, co je zlé v očích Hospodina, jeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Vytáhl proti němu babylonský král Nebúkadnesar a svázal ho bronzovými okovy, aby ho odvedl do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Některé z předmětů Hospodinova domu Nebúkadnesar odnesl do Babylona a dal je do svého paláce v Babyloně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Ostatní Jójakímovy činy a jeho ohavnosti, které páchal, a co bylo shledáno proti němu, jsou zapsány v Knize izraelských a judských králů. Po něm se stal králem jeho syn Jójakín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jójakínovi bylo osm let, když se stal králem, a kraloval v Jeruzalémě tři měsíce a deset dní. Páchal to, co je zlé v Hospodinových očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Na přelomu roku poslal král Nebúkadnesar a odvedl ho do Babylona spolu se vzácnými předměty Hospodinova domu. Králem nad Judskem a Jeruzalémem ustanovil jeho bratra Sidkijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sidkijášovi bylo dvacet jedna let, když se stal králem, a kraloval v Jeruzalémě jedenáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Páchal to, co je zlé v očích Hospodina, jeho Boha, a nepokořil se před ⌈ slovy proroka Jeremjáše z Hospodinových úst.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Také se vzbouřil proti králi Nebúkadnesarovi, který ho nechal přísahat při Bohu. Zatvrdil svou šíji a své srdce, ⌈takže se⌉ nenavrátil k Hospodinu, Bohu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Také všichni předáci kněží a lid se zpronevěřili mnohou věrolomností podle všech ohavností pohanských národů a znečistili Hospodinův dům, který on posvětil v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Hospodin, Bůh jejich otců, jim posílal slovo prostřednictvím svých poslů, ⌈stále znovu⌉ posílal, protože měl soucit se svým lidem a se svým příbytkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Oni si však z Božích poslů ⌈tropili žerty,⌉ pohrdali jeho slovy, posmívali se jeho prorokům, dokud nevystoupila Hospodinova zloba proti jeho lidu, takže nebylo uzdravení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Přivedl na ně chaldejského krále a ten zabil jeho mládence mečem v domě jeho svatyně. Neměl soucit s mládencem, pannou, starcem ani sešlým věkem, Bůh vydal všechny do jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Všechny předměty Božího domu, velké i malé, poklady Hospodinova domu i poklady krále a jeho knížat, to vše odnesl do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Spálili Boží dům, strhli jeruzalémské hradby, všechny jeho paláce spálili ohněm a všechny jeho vzácné předměty zničili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Ty, kteří zbyli po meči, odvedl do Babylona a byli otroky jeho a jeho synů až do začátku kralování království perského,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'aby se naplnilo Hospodinovo slovo skrze ústa Jeremjášova, dokud země nenahradila svůj odpočinek. Po celou dobu svého zpustošení odpočinula, až se naplnilo sedmdesát let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'V prvním roce vlády perského krále Kýra, když se dovršilo Hospodinovo slovo skrze ústa Jeremjášova, vzbudil Hospodin ducha perského krále Kýra, aby nechal rozhlásit po celém svém království a také napsal slova:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Toto praví perský král Kýros: Hospodin, Bůh nebes, mi dal všechna království země a ustanovil mě, abych mu postavil dům v Jeruzalémě, který je v Judsku. Kdokoliv z vás, ze všeho jeho lidu -- Hospodin, jeho Bůh, je s ním -- ať jde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'V prvním roce vlády perského krále Kýra, ⌈když se dovršilo⌉ Hospodinovo slovo z Jeremjášových úst, vzbudil Hospodin ducha perského krále Kýra, aby nechal rozhlásit po celém svém království a také napsal slova:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Toto praví perský král Kýros: Hospodin, ⌈Bůh nebes,⌉ mi dal všechna království země a ⌈uložil mi,⌉ abych mu postavil dům v Jeruzalémě v Judsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kdokoliv z vás, ze všeho jeho lidu, jeho Bůh ať je s ním, může jít do Jeruzaléma v Judsku a stavět dům Hospodina, Boha Izraele, Boha, který je v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Každého, kdo zůstal na jakémkoliv místě, kde pobývá jako cizinec, ať místní lidé podpoří stříbrem, zlatem, majetkem a dobytkem spolu s dobrovolnou obětí pro dům Boží v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Nato povstali předáci rodů ⌈judských a benjamínských,⌉ kněží, lévité, každý, jehož ducha Bůh vzbudil, aby vyšli stavět Hospodinův dům v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'A všichni jejich okolní obyvatelé ⌈je podpořili⌉ stříbrnými nádobami, zlatem, majetkem, dobytkem a vzácnými dary kromě toho, co obětovali dobrovolně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Král Kýros vydal nádoby Hospodinova domu, které Nebúkadnesar odnesl z Jeruzaléma a dal je do domu svého boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Perský král Kýros je vydal prostřednictvím správce pokladu Mitredata, který je odpočítal judskému předáku Šéšbasarovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Toto je jejich výčet: třicet zlatých misek, tisíc stříbrných misek, dvacet devět nožů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'třicet zlatých pohárů, čtyři sta deset druhořadých stříbrných pohárů a tisíc jiných nádob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Všech zlatých a stříbrných nádob bylo pět tisíc čtyři sta. To vše odnesl Šéšbasar spolu s vyhnanci, kteří vyšli z Babylonu do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Toto jsou obyvatelé provincie, ⌈kteří vyšli⌉ ze zajetí, vyhnanci, které odvedl babylonský král Nebúkadnesar do Babylonu a vrátili se do Jeruzaléma a Judska, každý do svého města,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'ti, kteří přišli se Zerubábelem, Jéšuou, Nehemjášem, Serajášem, Reelajášem, Mordokajem, Bilšánem, Misparem, Bigvajem, Rechúmem, Baanou. Toto je výčet mužů izraelského lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Synů Pareóšových dva tisíce sto sedmdesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'synů Šefatjášových tři sta sedmdesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'synů Árachových sedm set sedmdesát pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'synů Pachat–moábových, totiž synů Jéšuových a Jóabových, dva tisíce osm set dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'synů Élamových tisíc dvě stě padesát čtyři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'synů Zatúových devět set čtyřicet pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'synů Zakajových sedm set šedesát;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'synů Baního šest set čtyřicet dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'synů Bebajových šest set dvacet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'synů Azgadových tisíc dvě stě dvacet dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'synů Adoníkamových šest set šedesát šest;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'synů Bigvajových dva tisíce padesát šest;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'synů Adínových čtyři sta padesát čtyři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'synů Aterových, totiž Chizkijášových, devadesát osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'synů Besajových tři sta dvacet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'synů Jórových sto dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'synů Chašumových dvě stě dvacet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'synů Gibarových devadesát pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'synů Bét–lechemových sto dvacet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'mužů z Netófy padesát šest;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'mužů z Anatótu sto dvacet osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'mužů z Azmávetu čtyřicet dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'mužů z Kirjat–jearímu, Kefíry a Beerótu sedm set čtyřicet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'mužů z Rámy a Geby šest set dvacet jedna;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'mužů z Mikmásu sto dvacet dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'mužů z Bét–elu a Aje dvě stě dvacet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'mužů z Neba padesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'mužů z Magbíše sto padesát šest;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'mužů z jiného Élamu tisíc dvě stě padesát čtyři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'mužů z Charimu tři sta dvacet;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'mužů z Lódu, Chadídu a Óna sedm set dvacet pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'mužů z Jericha tři sta čtyřicet pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'synů Senáových tři tisíce šest set třicet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Kněží: synů Jedajášových z domu Jéšuova devět set sedmdesát tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'synů Imerových tisíc padesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'synů Pašchúrových tisíc dvě stě čtyřicet sedm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'synů Charimových tisíc sedmnáct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Lévité: synů Jéšuových a Kadmíelových, totiž synů Hódavjášových, sedmdesát čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Zpěváci: synů Asafových sto dvacet osm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Synové vrátných: synů Šalúmových, synů Aterových, synů Talmónových, synů Akúbových, synů Chatítových, synů Šobajových celkem sto třicet devět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Chrámoví nevolníci: Synové Síchovi, synové Chasúfovi, synové Tabaótovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'synové Kérosovi, synové Síaovi, synové Padónovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'synové Lebánovi, synové Chagábovi, synové Akúbovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'synové Chágabovi, synové Šalmajovi, synové Chánanovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'synové Gidélovi, synové Gacharovi, synové Reajášovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'synové Resínovi, synové Nekódovi, synové Gazamovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'synové Uzovi, synové Paséachovi, synové Besajovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'synové Asnovi, synové Meúnejců, synové Nefíšesejců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'synové Bakbúkovi, synové Chakúfovi, synové Charchúrovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'synové Baslútovi, synové Mechídovi, synové Charšovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'synové Barkósovi, synové Síserovi, synové Tamachovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'synové Nesíachovi, synové Chatífovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Synové Šalomounových otroků: Synové Sótajovi, synové Sóferetovi, synové Perídovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'synové Jaalovi, synové Darkónovi, synové Gidélovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'synové Šefatjášovi, synové Chatílovi, synové Pokereta Sebajimského, synové Amiovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Všech chrámových nevolníků a synů Šalomounových otroků bylo tři sta devadesát dva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Toto jsou ti, kteří přišli z Tel–melachu, Tel–charšy, Kerúb–adánu a Imeru, ale nemohli určit rodinu svých otců a jejich potomstvo, zdali jsou z Izraele:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Synů Delajášových, synů Tóbijášových, synů Nekódových šest set padesát dva');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'a ze synů kněží synové Chobajášovi, synové Kósovi, synové Barzilaje, který si vzal ženu z dcer Barzilaje a byl nazván podle jejich jména.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ti hledali svůj zápis v rodokmenech, ale nenašli se a byli jako nečistí vyloučeni z kněžství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Místodržitel jim řekl, že ne smějí jíst z nejsvětějšího jídla, dokud nepovstane kněz s urím a tumím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Celé shromáždění dohromady čítalo čtyřicet dva tisíc tři sta šedesát lidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'kromě jejich otroků a otrokyň, jichž bylo sedm tisíc tři sta třicet sedm. Měli také dvě stě zpěváků a zpěvaček,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'sedm set třicet šest koní, dvě stě čtyřicet pět mezků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'čtyři sta třicet pět velbloudů a šest tisíc sedm set dvacet oslů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Někteří z předáků rodů, když přišli k Hospodinovu domu v Jeruzalémě, se rozhodli dobrovolně dát na Boží dům, aby ho postavili na jeho základech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Podle svého jmění dali na poklad určený pro práci šedesát jedna tisíc zlatých darejků, pět tisíc stříbrných hřiven a sto kněžských rouch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'I usadili se kněží, lévité, někteří z lidu, zpěváci, vrátní a chrámoví nevolníci ve svých městech; celý Izrael se usadil ve svých městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Když nastal sedmý měsíc, synové Izraele byli ve městech, lid se shromáždil jako jeden muž do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'I povstal Jéšua, syn Jósadakův, se svými bratry kněžími a Zerubábel, syn Šealtíelův, se svými bratry a postavili oltář Boha Izraele, aby na něm přinášeli zápalné oběti, jak je psáno v zákoně Mojžíše, muže Božího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Obnovili oltář na jeho základech, protože na ně doléhala hrůza z národů zemí, a přinášeli na něm zápalné oběti Hospodinu, zápalné oběti ráno i večer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Slavili svátek stánků, jak je psáno, a připravovali každodenní zápalné oběti podle patřičného počtu nařízeného pro každý den');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'a potom ustavičné zápalné oběti, oběti při novoluních a při všech posvěcených Hospodinových svátcích a pro každého, kdo dobrovolně obětoval dobrovolné oběti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Od prvního dne sedmého měsíce začali přinášet zápalné oběti Hospodinu, ačkoliv základy Hospodinova chrámu nebyly položeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'A dali stříbro kameníkům a řemeslníkům i jídlo, pití a olej Sidóňanům a Týřanům, aby přiváželi po moři cedrové dřevo z Libanonu do Jafy dle povolení, ⌈které měli⌉ od perského krále Kýra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'V druhém roce po svém příchodu k Božímu domu do Jeruzaléma, v druhém měsíci, začali Zerubábel, syn Šealtíelův, a Jéšua, syn Jósadakův, a ostatní jejich bratři kněží a lévité a všichni, kdo přišli ze zajetí do Jeruzaléma, stavět a ustanovili lévity od věku dvaceti let výše jako dozorce nad dílem Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Jéšua, jeho synové a jeho bratři, Kadmíel a jeho synové, synové Judovi, nastoupili společně jako dozorci nad těmi, kteří konali práci na Božím domě. Též synové Chenadadovi, jejich synové a jejich bratři lévité.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Když stavitelé položili základy Hospodinova chrámu, zaujali místa kněží oblečení v roucha s trubkami a lévité, synové Asafovi, s činely, aby chválili Hospodina podle pokynů izraelského krále Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'S chválením a vzdáváním díků zpívali Hospodinu, že je dobrý, neboť jeho milosrdenství nad Izraelem je věčné. A všechen lid hlaholil s velkým pokřikem a chválil Hospodina za to, že byly položeny základy Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Mnozí z kněží, lévitů a předáků rodů, starci, kteří viděli první dům, hlasitě plakali, když byly před jejich očima kladeny základy tohoto domu. Mnozí však radostně pokřikovali a pozvedali hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Lid nebyl schopen rozeznat zvuk radostného křiku od zvuku pláče lidu, neboť lid hlaholil s velikým křikem; zvuk bylo slyšet do daleka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Když se protivníci Judy a Benjamína doslechli, že navrátilí vyhnanci stavějí chrám Hospodinu, Bohu Izraele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'přistoupili k Zerubábelovi a k předákům rodů a řekli jim: Budeme stavět s vámi, vždyť hledáme vašeho Boha tak jako vy a obětujeme mu ode dnů asyrského krále Esarchadóna, který nás sem přivedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Zerubábel, Jéšua a ostatní předáci izraelských rodů jim řekli: Neexistuje, abychom společně stavěli dům našemu Bohu. My sami budeme stavět Hospodinu, Bohu Izraele, jak přikázal král Kýros, král perský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'I stalo se, že lid země oslaboval ruce judského lidu a zastrašoval je, aby ne stavěli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Podpláceli proti nim i rádce, aby mařili jejich plán po všechny dny perského krále Kýra až do kralování perského krále Dareia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'A za kralování Achašvéroše, na počátku jeho kralování, napsali žalobu proti obyvatelům Judska a Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Ve dnech Artaxerxa napsal Bišlám, Mitredat, Tabel a ostatní jejich spolupracovníci perskému králi Artaxerxovi. List byl psán aramejsky a překládán. Aramejsky zní:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Kancléř Rechúm a sekretář Šimšaj píší králi Artaxerxovi list ohledně Jeruzaléma, ⌈jak uvedeno⌉ níže,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'potažmo kancléř Rechúm, sekretář Šimšaj a ostatní jejich spolupracovníci z Dínu, Afarsatku, Tarpelu, Afarsu, z Erechu, z Babylonu a ze Sús neboli Elamu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'a z jiných národů, které veliký a vznešený Osnappar přestěhoval a usadil v samařských městech a ostatním Zaeufratí. Nuže');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'toto je text listu, který poslali králi Artaxerxovi: Tví otroci, obyvatelé Zaeufratí. A sice:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Známo budiž králi, že ti Judejci, kteří od tebe dorazili k nám, přišli do Jeruzaléma. Stavějí to odbojné a zlé město, hodlají dokončit hradby a už položili základy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Známo tedy budiž králi, že bude–li toto město vystavěno a jeho hradby dokončeny, daně, dávky ani poplatky odvádět nebudou, což bude nakonec ke škodě ⌈královské pokladně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Nyní tedy poněvadž ⌈užíváme dobrodiní paláce⌉ a znevažování krále se nám nesluší přihlížet, proto vzkazujeme a oznamujeme to králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Nechť se hledá v archivech tvých otců. V archivech nalezneš a dozvíš se, že to město bývalo město odbojné a působilo škodu králům i státům a ke vzbouřením uvnitř něho docházelo od starodávna. Proto bylo to město zničeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Oznamujeme králi, že pakli to město bude vystavěno a hradby budou dokončeny, tedy podíl v Zaeufratí již mít nebudeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Odpověď posílá král kancléři Rechúmovi, sekretáři Šimšajovi a ostatním jejich spolupracovníkům bydlícím v Samaří a ostatním Zaeufratí: Pokoj. Nuže:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Dopis, který jste nám poslali, byl ⌈přede mnou⌉ čten ⌈slovo za slovem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Vydal jsem tedy nařízení, i hledali a nalezli, že to město od starodávna povstává proti králům a dochází v něm ke vzpourám a vzbouřením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Avšak nad Jeruzalémem bývali mocní králové a panovali po celém Zaeufratí a byly jim odváděny daně, dávky i poplatky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Vydejte proto nařízení, aby ti muži přestali a to město se nestavělo, dokud nevydám nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Varujte se být v konání této věci nedbalí. Proč by se měla zvětšovat škoda utrpěná královstvím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Hned, jakmile byl text dopisu krále Artaxerxe přečten před Rechúmem i sekretářem Šimšajem a jejich spolupracovníky, odjeli rychle do Jeruzaléma k Judejcům a ⌈s veškerou mocí⌉ je donutili přestat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Práce na domě Božím v Jeruzalémě tehdy ustala a stála až do druhého roku kralování perského krále Dareia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Tu prorokoval prorok Ageus a Zacharjáš, syn Idův, proroci, Judejcům v Judsku a v Jeruzalémě ve jménu Boha Izraele ⌈nad nimi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Tehdy povstali Zerubábel, syn Šealtíelův, a Jéšua, syn Jósadakův, a dali se do budování domu Božího v Jeruzalémě a s nimi Boží proroci, kteří je povzbuzovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'V té době k nim přišel Tatenaj, místodržitel v Zaeufratí, a Šetar–bóznaj se svými spolupracovníky a takto se jich otázali: Kdo vám dal povolení k výstavbě tohoto domu a ke shromažďování tohoto materiálu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Tehdy jsme jim náležitě odpověděli, jak se jmenují muži, kteří tuto budovu stavějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'A nad judskými staršími bdělo oko jejich Boha, takže je nedonutili přestat, dokud nedošlo hlášení Dareiovi a dokud potom neobdrželi dopis ohledně té věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Text listu, který poslal Tatenaj, místodržitel v Zaeufratí, a Šetar–bóznaj se svými spolupracovníky z Afarseku v Zaeufratí králi Dareiovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Poslali mu sdělení a v něm se psalo toto: Králi Dareiovi veškerý pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Známo buď králi, že jsme přišli do judské provincie k domu velikého Boha. Staví se z hlazeného kamene a do stěn jsou vkládány trámy. Toto dílo se koná důkladně a daří se pod jejich rukama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Otázali jsme se tedy oněch starších a řekli jsme jim: Kdo vám dal povolení k výstavbě tohoto domu a ke shromažďování tohoto materiálu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Ptali jsme se jich rovněž na jejich jména, abychom ti to oznámili a mohli napsat jména těch mužů v jejich čele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Dali nám následující odpověď: My jsme otroci Boha nebes a země a stavíme dům, jenž byl postaven již před mnoha lety; stavěl ho i dokončil jeden velký izraelský král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Ale protože naši otcové rozhněvali Boha nebes, vydal je do ruky Chaldejce Nebúkadnesara, krále babylonského. On tento dům zničil a lid vystěhoval do Babylonu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Nicméně v prvním roce vlády babylonského krále Kýra vydal král Kýros nařízení tento dům Boží stavět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Dokonce i zlaté a stříbrné nádoby domu Božího, které Nebúkadnesar odnesl z jeruzalémského chrámu a zanesl do babylonského chrámu, král Kýros z babylonského chrámu odnesl a byly dány komusi jménem Šéšbasar, kterého ustanovil místodržitelem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'a přikázal mu: Vezmi tyto nádoby, jdi a ulož je v jeruzalémském chrámě. Dům Boží ať se staví na svém místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Tehdy onen Šéšbasar přišel a položil základy domu Božího v Jeruzalémě. Od tehdy se staví až dodnes a není dokončen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Nyní tedy, ⌈pokud se králi zlíbí,⌉ ať se hledá v královských archivech tam v Babyloně, zdali existuje od krále Kýra vydané nařízení, aby byl stavěn onen dům Boží v Jeruzalémě. Pak ať je nám posláno královo rozhodnutí v této věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Nato král Dareios vydal nařízení a v archivní knihovně prohledali, co bylo uloženo tam v Babyloně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Ale až na hradě v Ekbataně v médské provincii se nalezl jistý svitek a v něm bylo psáno toto: Památný zápis:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'V prvním roce vlády krále Kýra vydal král Kýros nařízení o domě Božím v Jeruzalémě: Dům ten budiž vystavěn na místě, kde se obětují oběti a jeho základy budiž zachovány. Jeho výška šedesát loket, jeho šířka šedesát loket,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'tři řady hlazených kamenů a řada nových trámů. Náklady ať se hradí z královského domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Nadto zlaté a stříbrné nádoby domu Božího, které Nebúkadnesar odnesl z jeruzalémského chrámu a zanesl do Babylonu, nechť se vrátí. Ať jsou zaneseny na své místo do jeruzalémského chrámu a uložíš je v domě Božím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Nyní tedy, Tatenaji, místodržiteli v Zaeufratí, Šetar–bóznaji a jejich spolupracovníci z Afarseku v Zaeufratí, ⌈nevměšujte se do toho.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Práci na onom domě Božím nechte být. Ten dům Boží nechť na jeho místě stavějí judští místodržitelé a kdo náležejí k judským starším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Vydávám tímto nařízení, jak máte postupovat vůči těm judským starším při budování onoho domu Božího: že totiž náklady mají být oněm mužům pečlivě propláceny z královských prostředků, jež pocházejí z daní v Zaeufratí, aby nedocházelo k prostojům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Též cokoliv by bylo potřeba, ať býčci, berani či jehňata k zápalným obětem Bohu nebes, pšenice, sůl, víno i olej podle přání jeruzalémských kněží jim budou dodávány každodenně bez nedbalostí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'aby přinášeli Bohu nebes ⌈příjemné oběti ⌉ a modlili se za život krále a jeho synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Dále pak vydávám nařízení, aby komukoliv, kdo tento výnos poruší, byl z jeho domu vytržen trám a on byl vyzdvižen a naražen na něj; jeho dům ať je za to proměněn v ⌈hromadu sutin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'A Bůh, jenž tam dává přebývat svému jménu, ať svrhne každého krále i lid, který by vztáhl svou ruku, aby to porušil či poškodil onen dům Boží v Jeruzalémě. Já, Dareios, vydávám toto nařízení. Budiž provedeno pečlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Tatenaj, místodržitel v Zaeufratí, Šetar–bóznaj a jejich spolupracovníci tedy postupovali pečlivě v souladu s tím, jak vzkázal král Dareios.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Judští starší stavěli a dařilo se jim ⌈za prorokování⌉ proroka Agea a Zacharjáše, syna Idova. Pak dostavěli a dokončili z nařízení Boha Izraele a z nařízení Kýra i Dareia i Artaxerxa, krále perského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Tento dům byl dokonán třetího dne měsíce adaru, což bylo šestého roku kralování krále Dareia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Pak synové Izraele -- kněží, lévíté a ostatní vysídlenci -- s radostí ⌈slavili posvěcení⌉ tohoto domu Božího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Při posvěcení tohoto domu Božího obětovali sto býků, dvě stě beranů, čtyři sta jehňat a jako oběť za hřích pro celý Izrael dvanáct kozlů podle počtu izraelských kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'A ustanovili kněze podle jejich tříd a lévíty podle jejich oddílů ke službě Boží v Jeruzalémě, jak je psáno v knize Mojžíšově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Navrátilí vyhnanci slavili Velikonoce čtrnáctého dne prvního měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Kněží i lévité se do jednoho očistili, všichni byli čistí. Zabíjeli velikonoční oběti pro všechny vyhnance, pro své bratry kněze i pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'I jedli synové Izraele, kteří se vrátili z vyhnanství, a ⌈s nimi⌉ všichni, kdo se oddělili od nečistoty národů země, aby hledali Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'A slavili s radostí svátek nekvašených chlebů po sedm dní, neboť jim Hospodin způsobil radost, když vůči nim změnil srdce asyrského krále, takže posilnil jejich ruce při práci na domě Boha, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Po těchto událostech, za kralování perského krále Artaxerxa, Ezdráš, syn Serajáše, syna Azarjáše, syna Chilkijáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'syna Šalúma, syna Sádoka, syna Achítúba,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'syna Amarjáše, syna Azarjáše, syna Merajóta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'syna Zerachjáše, syna Uzího, syna Bukího,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'syna Abíšúy, syna Pinchase, syna Eleazara, syna Árona, vrchního kněze,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'tento Ezdráš vyšel z Babylonu. Byl písařem, zběhlým v Mojžíšově zákoně, který vydal Hospodin, Bůh Izraele. Protože ruka Hospodina, jeho Boha, byla nad ním, král mu dal vše, o co jej žádal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Také někteří ze synů Izraele, z kněží, lévitů, zpěváků, vrátných a chrámových nevolníků vyšli do Jeruzaléma v sedmém roce vlády krále Artaxerxa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Do Jeruzaléma přišel v pátém měsíci sedmého roku vlády krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Prvního dne prvního měsíce určil vyjít z Babylonu a prvního dne pátého měsíce přišel do Jeruzaléma, protože dobrotivá ruka jeho Boha byla nad ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Ezdráš ⌈zaměřil své srdce⌉ na to, aby zkoumal Hospodinův zákon a plnil jej a aby učil v Izraeli ustanovení a nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'A toto je text dopisu, který dal král Artaxerxes knězi a písaři Ezdrášovi, písaři záležitostí ohledně Hospodinových příkazů a jeho ustanovení o Izraeli:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artaxerxes, král králů, Ezdrášovi, knězi a znalci zákona Boha nebes ⌈a tak dále.⌉ Nuže:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Vydávám tímto nařízení, že každý, kdo je v mém království z izraelského lidu, jeho kněží a lévítů ochoten jít do Jeruzaléma s tebou, nechť jde,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'jelikož jsi poslán samotným králem a jeho sedmi rádci k dozírání na Judsko a Jeruzalém podle zákona tvého Boha, který ⌈máš u sebe;⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'také abys donesl stříbro a zlato, které král a jeho rádci dobrovolně věnovali Bohu Izraele, jehož příbytek je v Jeruzalémě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'i všechno stříbro a zlato, které získáš po celé babylonské provincii spolu s dobrovolnými dary lidu a kněží, věnovanými domu jejich Boha v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Proto za to stříbro pečlivě nakoupíš býky, berany a jehňata s patřičnými obětními dary a úlitbami a budeš je obětovat na oltáři v domě vašeho Boha v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Cokoliv se pak tobě a tvým bratřím bude zdát za dobré učinit se zbytkem stříbra a zlata, to učiňte podle vůle svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Avšak nádoby, jež jsou ti dány pro bohoslužbu v domě tvého Boha, odevzdej před Bohem v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Ostatní potřeby domu tvého Boha, které musíš dodat, dodej z královské pokladnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Já, král Artaxerxes, vydávám nařízení všem pokladníkům v Zaeufratí, aby vše, o č vás požádá Ezdráš, kněz a znalec zákona Boha nebes, bylo pečlivě provedeno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'a to až do sta talentů stříbra, do sta kórů pšenice, do sta batů vína, do sta batů oleje a soli bez omezení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, '⌈Cokoliv Bůh nebes přikáže,⌉ budiž domu Boha nebes přesně provedeno, aby ne dopadlo rozhořčení na královu říši ani jeho syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Dále vám budiž známo, že na žádné kněze, lévíty, zpěváky, vrátné, chrámové nevolníky a vůbec služebníky tohoto domu Božího uvalovat daně, dávky ani poplatky není dovoleno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Ty, Ezdráši, podle moudrosti svého Boha, kterou máš při sobě, pověř správce a soudce, kteří budou soudit všechen lid v Zaeufratí, všechny ⌈vědomé si⌉ zákonů tvého Boha; neznalé poučte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Kdokoliv zákon tvého Boha ani zákon královský plnit nebude, nad tím se bude bez okolků konat soud, ať smrtí, ať vyhnanstvím, ať exekucí majetku nebo vězením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Požehnán buď Hospodin, ⌈Bůh našich otců,⌉ který položil něco takového králi na srdce, aby ozdobil Hospodinův dům v Jeruzalémě');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'a ⌈získal mi přízeň u krále,⌉ jeho rádců a všech mocných králových knížat; a já jsem se vzchopil, protože ruka Hospodina, mého Boha, byla nade mnou, a shromáždil jsem izraelské předáky, aby vyšli se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Toto jsou předáci svých rodů a rodokmeny těch, kteří vyšli se mnou z Babylonu za kralování krále Artaxerxa:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Ze synů Pinchasových: Geršóm; ze synů Ítamarových: Daniel; ze synů Davidových: Chatúš;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'ze synů Šekanjášových: Ze synů Pareóšových: Zekarjáš a s ním sto padesát mužů zapsaných do rodokmenů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'ze synů Pachat–moábových: Eljóenaj, syn Zerachjášův, a s ním dvě stě mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'ze synů Šekanjášových: syn Jachazíelův a s ním tři sta mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'ze synů Adínových: Ebed, syn Jónatanův, a s ním padesát mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'ze synů Élamových: Ješajáš, syn Ataljášův, a s ním sedmdesát mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'ze synů Šefatjášových: Zebadjáš, syn Michaelův, a s ním osmdesát mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'ze synů Jóabových: Obadjáš, syn Jechíelův, a s ním dvě stě osmnáct mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'ze synů Šelomítových: syn Jósifjášův a s ním sto šedesát mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'ze synů Bebajových: Zekarjáš, syn Bebajův, a s ním dvacet osm mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'ze synů Azgadových: Jóchanan, syn Hakatanův, a s ním sto deset mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'ze synů Adoníkamových, poslední, jejichž jména jsou: Elífelet, Jeíel, Šemajáš a s nimi šedesát mužů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'ze synů Bigvajových: Útaj a Zakúr a s nimi sedmdesát mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Shromáždil jsem je u řeky tekoucí do Ahavy a tábořili jsme tam tři dny. Porozhlédl jsem se po lidu a kněžích, ale ze synů Léviho jsem tam nenašel nikoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Poslal jsem tedy pro předáky Elíezera, Aríela, Šemajáše, Elnátana, Jaríba, Elnátana, Nátana, Zekarjáše a Mešuláma a pro učitele Jójaríba a Elnátana');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'a dal jsem jim příkaz pro Ida, předáka místa zvaného Kasifja, a vložil jsem jim do úst slova, která mají promluvit k Idovi a jeho bratrům, chrámovým nevolníkům, v místě zvaném Kasifja, aby nám přivedli služebníky pro dům našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Protože dobrotivá ruka našeho Boha byla nad námi, přivedli nám rozumného muže ze synů Machlího, syna Léviho, syna Izraelova, totiž Šerebjáše, jeho syny a jeho bratry, celkem osmnáct,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'a Chašabjáše a s ním Ješajáše ze synů Merarího, jeho bratry a jeho syny, celkem dvacet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'a z chrámových nevolníků, které určil David s knížaty k službě lévitům, dvě stě dvacet chrámových nevolníků, všichni byli jmenovitě určeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Vyhlásil jsem tam u řeky Ahavy půst, abychom se pokořovali před svým Bohem a vyprosili si od něj přímou cestu pro sebe, pro své děti a pro všechen svůj majetek,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'neboť jsem se styděl žádat od krále vojsko a jezdce, aby nás po cestě chránili před nepřáteli. Řekli jsme totiž králi: Dobrotivá ruka našeho Boha je nade všemi, kdo ho hledají, ale jeho moc a hněv je proti všem, kdo ho opouštějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Postili jsme se a žádali jsme toto od svého Boha a on se dal pohnout našimi prosbami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Potom jsem oddělil z předáků dvanáct kněží, Šerebjáše, Chašabjáše a s nimi deset jejich bratrů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'a odvážil jsem jim stříbro, zlato a nádoby, oběť pro dům našeho Boha, kterou přinesli král, jeho rádci, jeho knížata a všichni Izraelci, kteří tam byli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Odvážil jsem jim do rukou šest set padesát talentů stříbra, sto stříbrných nádob po talentu a sto talentů zlata');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'a dvacet zlatých pohárů po tisíci darejcích a dvě nádoby z pěkného nazlátlého bronzu, cenné jako zlato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Nato jsem jim řekl: Jste svatí Hospodinu i nádoby jsou svaté; stříbro a zlato jsou dobrovolné oběti pro Hospodina, Boha vašich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Bděte a střežte je, dokud je neodvážíte před předáky kněží a lévitů a předáky izraelských rodů v Jeruzalémě v komorách Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Kněží a lévité přijali odvážené stříbro, zlato a nádoby, aby je přivezli do Jeruzaléma do domu našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Od řeky Ahavy jsme vyrazili dvanáctého dne prvního měsíce, abychom šli do Jeruzaléma. Ruka našeho Boha byla nad námi a on nás vysvobodil z moci nepřátel a těch, kdo číhali po cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Přišli jsme do Jeruzaléma a pobývali jsme tam tři dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Čtvrtého dne bylo odváženo stříbro, zlato a nádoby v domě našeho Boha do správy kněze Meremóta, syna Urijášova; s ním byl Eleazar, syn Pinchasův, a s nimi byli lévité Józabad, syn Jéšuův, a Nóadjáš, syn Binújův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'všechno podle počtu a podle váhy; a všechna váha byla toho času zapsána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Ti, kteří přišli ze zajetí, vyhnanci, obětovali zápalné oběti Bohu Izraele: dvanáct býčků za celý Izrael, devadesát šest beranů, sedmdesát sedm beránků a dvanáct kozlů jako oběť za hřích. To byla celá zápalná oběť Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'A královská nařízení dali královským satrapům a místodržitelům v Zaeufratí a ti podporovali lid i Boží dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Když toto skončilo, přistoupila ke mně knížata se slovy: Izraelský lid, kněží a lévité se neoddělili od národů země ⌈a od jejich⌉ ohavností, totiž od Kenaanců, Chetejců, Perizejců, Jebúsejců, Amónců, Moábců, Egypťanů a Emorejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Neboť si brali jejich dcery pro sebe a pro své syny a vmísili svaté símě mezi národy země. Ruka knížat a správců byla v této věrolomnosti první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Když jsem to uslyšel, roztrhl jsem své roucho a svůj plášť, rval jsem si vlasy z hlavy a vousy a seděl jsem zděšen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Shromáždili se ke mně všichni, kdo se třásli před slovy Boha Izraele kvůli věrolomnosti vyhnanců. Ale já jsem seděl zděšen až do večerní přídavné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'V čase večerní přídavné oběti jsem vstal ze svého pokoření a s roztrženým rouchem a pláštěm jsem klesl na kolena a vztáhl jsem dlaně k Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Řekl jsem: Můj Bože, stydím se a hanbím se pozvednout svou tvář k tobě, můj Bože, protože naše viny ⌈ nám přerostly přes hlavu⌉ a naše provinění vzrostlo až k nebesům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Ode dnů svých otců až dodnes jsme vězeli ve velkém provinění a pro své viny jsme byli vydáni my, naši králové i kněží do ruky králů země, pod meč, do zajetí, jako kořist a k veřejnému zahanbení, jak je tomu až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'A nyní se nám na malou chvíli dostalo smilování od Hospodina, našeho Boha; zanechal nám ty, kteří vyvázli, a dal nám kolík na svém svatém místě. Náš Bůh dal světlo našim očím a dal nám trochu obživnout v našem otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Vždyť jsme otroky, ale náš Bůh nás v našem otroctví neopustil a ⌈získal nám přízeň u perských králů,⌉ dal nám obživnout, abychom obnovili dům svého Boha a postavili ho ⌈z jeho trosek,⌉ a dal nám zeď v Judsku i v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'A nyní, co můžeme říct po tomto? Vždyť jsme opustili tvé příkazy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'které jsi dal prostřednictvím svých otroků proroků, když jsi řekl: Země, kterou jdete obsadit, je země poskvrněná nečistotou národů země, jejich ohavnostmi, kterými ji ve své nečistotě naplnily od jednoho konce na druhý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Proto nedávejte své dcery jejich synům a jejich dcery neberte pro své syny. Neusilujete nikdy o jejich pokoj a dobro, abyste byli silní a jedli dobré věci země a navěky ji podrobili pro své syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Po tom všem, co na nás přišlo pro naše zlé skutky a pro naše velké provinění -- třebaže ty, náš Bože, jsi nás ušetřil, trestal jsi nás méně, nežli naše viny zasloužily a dal jsi nám ty, kteří takto vyvázli --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'cožpak budeme znovu porušovat tvé příkazy a spřízňovat se s těmito ohavnými národy? Což se na nás nebudeš hněvat tak, že budeme vyhubeni, bez ostatku a bez těch, kteří by vyvázli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Hospodine, Bože Izraele, jsi spravedlivý, že nám zůstali ti, kteří vyvázli, jak je tomu dnes. Hle, jsme před tebou se svým proviněním, ačkoliv kvůli tomu nemůže před tebou nikdo obstát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Když se Ezdráš modlil a vyznával, plakal a vrhal se k zemi před Božím domem, shromáždili se k němu z Izraele jako převeliké shromáždění muži, ženy i děti; i lid plakal velkým pláčem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Nato promluvil Šekanjáš, syn Jechíelův, ze synů Élamových a řekl Ezdrášovi: Zpronevěřili jsme se vůči svému Bohu a brali jsme si ženy cizinky z národů země. Přesto je pro Izrael ještě naděje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Nuže, uzavřeme smlouvu se svým Bohem, že propustíme všechny ženy a ty, kteří se z nich zrodili, podle rozhodnutí Panovníka a těch, kdo se třesou před příkazem našeho Boha. Ať se stane podle zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Povstaň, neboť je to tvoje věc a my jsme s tebou. Posilni se a jednej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Nato Ezdráš povstal a zapřisáhl předáky kněží a lévitů a celý Izrael, aby jednali podle tohoto slova. A odpřisáhli to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Ezdráš vstal z místa před Božím domem a šel do komory Jóchanana, syna Eljašíbova. Když tam přišel, nejedl pokrm ani nepil vodu, protože truchlil nad věrolomností vyhnanců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Potom nechali provolat v Judsku a Jeruzalémě ke všem vyhnancům, aby se shromáždili v Jeruzalémě');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'a že každému, kdo by nepřišel do tří dnů, podle rozhodnutí předáků a starších bude zkáze zasvěcen všechen jeho majetek a on bude oddělen od shromáždění vyhnanců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Všichni muži z Judy a Benjamína se shromáždili do Jeruzaléma do tří dnů; to bylo devátého měsíce, dvacátého dne toho měsíce. Všechen lid zůstal na náměstí Božího domu a třásl se kvůli této záležitosti a kvůli dešťům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Kněz Ezdráš povstal a řekl jim: Zpronevěřili jste se, brali jste si ženy cizinky, a tak jste přidali k provinění Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Nyní vzdejte chválu Hospodinu, Bohu svých otců, a učiňte to, co je mu milé: Oddělte se od národů země a od žen cizinek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Celé shromáždění odpovědělo a hlasitě řeklo: Ano, musíme jednat podle tvých slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Ale lidu je mnoho a je čas dešťů. Nejsme schopni zůstat venku. To není práce na den či dva, neboť je nás mnoho, kdo jsme přestoupili v této věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Ať zůstanou naši předáci za celé shromáždění a všichni, kdo si vzali v našich městech ženy cizinky, ať přijdou v určený čas a s nimi starší ⌈jednotlivých měst⌉ a soudci, aby se od nás odvrátil planoucí hněv našeho Boha kvůli této záležitosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Pouze Jónatan, syn Asáelův, a Jachzejáš, syn Tikvův, se postavili proti tomu a Mešulám a lévita Šabetaj jim pomáhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Vyhnanci tak učinili. Kněz Ezdráš oddělil muže, předáky rodů podle domu jejich otců, všechny jmenovitě, a zasedli prvního dne desátého měsíce, aby tu záležitost zkoumali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Do prvního dne prvního měsíce skončili se všemi muži, kteří si vzali ženy cizinky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Mezi syny kněží, kteří si vzali ženy cizinky, byli tito: ze synů Jéšuy, syna Jósadakova, a jeho bratrů: Maasejáš, Elíezer, Jaríb a Gedaljáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, '⌈Podáním ruky slíbili,⌉ že propustí své ženy, a jako viníci obětovali berana ze stáda za své provinění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Ze synů Imerových: Chananí a Zebadjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Ze synů Charimových: Maasejáš, Elijáš, Šemajáš, Jechíel a Uzijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Ze synů Pašchúrových: Eljóenaj, Maasejáš, Jišmael, Netanel, Józabad a Eleása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Z lévitů: Józabad, Šimeí, Kelajáš, to je Kelíta, Petachjáš, Juda a Elíezer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Ze zpěváků: Eljašíb. Z vrátných: Šalúm, Telem a Urí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Z Izraele: Ze synů Pareóšových: Ramjáš, Jizijáš, Malkijáš, Mijamín, Eleazar, Malkijáš a Benajáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Ze synů Élamových: Matanjáš, Zekarjáš, Jechíel, Abdí, Jeremót a Elijáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Ze synů Zatúových: Eljóenaj, Eljašíb, Matanjáš, Jeremót, Zábad a Azíza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Ze synů Bebajových: Jóchanan, Chananjáš, Zabaj a Atlaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Ze synů Baního: Mešulám, Malúk, Adajáš, Jašúb, Šeal a Ramót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Ze synů Pachat–moábových: Adna, Kelal, Benajáš, Maasejáš, Matanjáš, Besaleel, Binúj a Menaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Synové Charimovi: Elíezer, Jišijáš, Malkijáš, Šemajáš, Šimeón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamín, Malúk a Šemarjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Ze synů Chašumových: Matenaj, Matata, Zábad, Elífelet, Jeremaj, Menaše a Šimeí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Ze synů Baního: Maadaj, Amrám, Úel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benajáš, Bedjáš, Keluhú,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanjáš, Meremót, Eljašíb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matanjáš, Matenaj, Jaasaj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Baní, Binúj, Šimeí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Šelemjáš, Nátan, Adajáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadbaj, Šašaj, Šaraj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azarel, Šelemjáš, Šemarjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Šalúm, Amarjáš a Josef.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Ze synů Nebóvých: Jeíel, Matitjáš, Zábad, Zebína, Jadaj, Jóel a Benajáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Všichni tito si vzali ženy cizinky a ⌈některé z nich jim daly syny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Slova Nehemjáše, syna Chakaljášova. Stalo se v měsíci kislevu, ve dvacátém roce, když jsem byl na hradě v Šúšanu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'že přišel Chananí, jeden z mých bratrů, s muži z Judska. Zeptal jsem se jich na Judejce, ty, kteří unikli a zůstali po zajetí, a na Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Řekli mi: Pozůstalí, kteří zůstali po zajetí tam v provincii, jsou ve velké nouzi a v potupě; hradby Jeruzaléma jsou zbořeny a jeho brány jsou spáleny ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Stalo se, když jsem uslyšel tato slova, že jsem usedl, plakal a truchlil jsem po několik dnů. Postil jsem se a modlil před Bohem nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Řekl jsem: Ach, prosím, Hospodine, Bože nebes, Bože velký a hrozný, ⌈který zachovává smlouvu a milosrdenství⌉ těm, kdo ho milují a zachovávají jeho příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Nechť je tvé ucho pozorné a tvoje oči otevřené, abys slyšel modlitbu svého otroka, kterou se dnes před tebou modlím, ve dne i v noci za syny Izraele, tvé otroky, a vyznávám hříchy synů Izraele, kterými jsme hřešili proti tobě; také já a dům mého otce jsme hřešili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Jednali jsme vůči tobě velmi zle; nezachovávali jsme příkazy, ustanovení a nařízení, která jsi přikázal svému otroku Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Pamatuj, prosím, na slovo, které jsi přikázal svému otroku Mojžíšovi: Jestliže se zpronevěříte, rozptýlím vás mezi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Když se však navrátíte ke mně, budete zachovávat mé příkazy a plnit je, i kdyby byli vaši zapuzení na konci nebes, shromáždím je odtamtud a přivedu je na místo, které jsem vyvolil, aby tam přebývalo mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Jsou přece tvými otroky a tvým lidem, který jsi vykoupil svou velkou silou a svou mocnou rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ach, prosím, Panovníku, nechť je tvoje ucho pozorné k modlitbě tvého otroka a k modlitbě tvých otroků, kteří se chtějí bát tvého jména. Dopřej dnes, prosím, svému otroku úspěch a dej mu dojít slitování před tímto mužem. Byl jsem totiž královským číšníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Stalo se v měsíci nísanu ve dvacátém roce vlády krále Artaxerxa, když bylo víno před ním, že jsem pozvedl víno a podal králi. Nebýval jsem v jeho přítomnosti skleslý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Král mi řekl: Proč ⌈vypadáš sklesle?⌉ Přece nejsi nemocen! To může být jedině skleslost srdce. Hrozně moc jsem se bál,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'ale řekl jsem králi: Ať žije král navěky! Jak ⌈bych nevypadal sklesle,⌉ když město, místo hrobů mých otců, je zcela zpustošené a jeho brány jsou stráveny ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Král mi řekl: O co žádáš? Modlil jsem se k Bohu nebes');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'a řekl jsem králi: Jestliže ⌈se to králi líbí⌉ a jestliže je ⌈ti tvůj otrok milý,⌉ pošli mě do Judska, do města, kde jsou hroby mých otců, abych ho znovu vystavěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Král mi řekl -- královna seděla vedle něj --: Jak dlouho bude trvat tvá cesta a kdy se vrátíš? Když jsem mu udal určitý čas, ⌈králi se to líbilo⌉ a poslal mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Řekl jsem králi: Jestliže ⌈se to králi líbí,⌉ ať jsou mi dány dopisy pro místodržitele Zaeufratí, které ⌈mi zaručí průchod,⌉ než přijdu do Judska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'A také dopis pro Asafa, strážce královského lesa, aby mi dal dřevo na trámy k zhotovení bran hradu, který patří k Božímu domu, pro městské hradby a pro dům, do něhož se nastěhuji já. Král mi to dal, protože dobrotivá ruka mého Boha byla nade mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Potom jsem přišel k místodržitelům Zaeufratí a dal jsem jim královské dopisy. Král se mnou poslal velitele vojska a jezdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Když se to doslechl Sanbalat Chorónský a Tóbijáš, amónský otrok, hrozně moc se jim nelíbilo, že přišel někdo, kdo usiluje o dobro pro syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Přišel jsem do Jeruzaléma a byl jsem tam tři dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'V noci jsem vstal a se mnou několik mužů. Nikomu jsem neoznámil, co mi můj Bůh položil na srdce, abych učinil pro Jeruzalém. Ne bylo se mnou žádné zvíře kromě toho, na kterém jsem jel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Vyjel jsem v noci Údolní bránou směrem k Dračímu prameni a k Hnojné bráně. Prohlížel jsem hradby Jeruzaléma, které byly pobořeny, a jeho brány, které byly stráveny ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Projel jsem k Studniční bráně a ke královskému rybníku, ale tam ne bylo místo pro zvíře pode mnou, aby prošlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Vystupoval jsem v noci údolím a prohlížel jsem hradby. Pak jsem se obrátil, vjel jsem Údolní bránou a vrátil jsem se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Správcové nevěděli, kde jsem chodil a co jsem dělal. Dosud jsem to Judejcům, kněžím, šlechticům, správcům a ostatním, kteří konali práci, neoznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Potom jsem jim řekl: Vidíte nouzi, ve které jsme; že Jeruzalém je zcela zpustošený a jeho brány jsou spáleny ohněm. Pojďte, vystavíme hradby Jeruzaléma a nebudeme už v potupě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Oznámil jsem jim, jak nade mnou byla dobrotivá ruka mého Boha a také slova, která mi král řekl. Nato řekli: Povstaňme a stavějme. A jejich ruce se posilnily k dobrému dílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Když se to doslechl Sanbalat Chorónský, Tóbijáš, amónský otrok, a Arab Gešem, vysmívali se nám a pohrdali námi. Říkali: Co to má znamenat, co tady provádíte? Bouříte se proti králi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, '⌈Odpověděl jsem jim⌉ a řekl jsem jim: Sám Bůh nebes nám dopřeje úspěch. My, jeho otroci, povstaneme a budeme stavět. Vy ale nemáte žádný podíl, nárok a památku v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Pak povstal velekněz Eljašíb a jeho bratři, kněží, a stavěli Ovčí bránu. Posvětili ji a vsadili její vrata; stavěli až k věži Meá, posvětili ji, a až k věži Chananeel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, '⌈Vedle něho⌉ stavěli muži z Jericha a vedle něho stavěl Zakúr, syn Imrího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Rybnou bránu stavěli synové Senáovi. Zhotovili ji z trámů a vsadili její vrata, zámky a závory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Vedle nich opravoval Meremót, syn Urijášův, vnuk Kósův. Vedle nich opravoval Mešulám, syn Berekjášův, vnuk Mešézabelův. Vedle nich opravoval Sádok, syn Baanův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Vedle nich opravovali Tekójští; ale jejich vznešení předáci nesklonili své šíje do služby svých pánů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Starou bránu opravovali Jójada, syn Paséachův, a Mešulám, syn Besódjášův. Zhotovili ji z trámů a vsadili její vrata, zámky a závory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Vedle nich opravoval Melatjáš Gibeónský a Jadón Meronótský, muži z Gibeónu a Mispy, ⌈ která byla ⌉ ⌈pod správou⌉ místodržitele Zaeufratí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Vedle něho opravoval Uzíel, syn Charhajášův, jeden ze zlatníků. Vedle něho opravoval Chananjáš, jeden z mastičkářů. Obnovili Jeruzalém až k Široké hradbě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Vedle nich opravoval Refajáš, syn Chúrův, hejtman poloviny jeruzalémského okresu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Vedle nich opravoval Jedajáš, syn Charúmafův, naproti svému domu. Vedle něho opravoval Chatúš, syn Chašabnejášův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, '⌈Další úsek⌉ a Pecnou věž opravoval Malkijáš, syn Charimův a Chašúb, syn Pachat–moábův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Vedle něho opravoval Šalúm, syn Lóchešův, hejtman poloviny jeruzalémského okresu, se svými dcerami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Údolní bránu opravoval Chanún a obyvatelé Zanóachu. Vystavěli ji a vsadili její vrata, zámky a závory; opravili také tisíc loket hradeb až ke Hnojné bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Hnojnou bránu opravoval Malkijáš, syn Rekábův, hejtman bétkeremského okresu. Vystavěl ji a vsadil její vrata, zámky a závory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Studniční bránu opravoval Šalún, syn Kolchozův, hejtman mispanského okresu. Vystavěl ji a zastřešil, vsadil její vrata, zámky a závory. Opravil také hradby při Šíloašském rybníku u královské zahrady a až ke schodům sestupujícím z Města Davidova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Za ním opravoval Nehemjáš, syn Azbúkův, hejtman poloviny bétsúrského okresu, až k místu naproti Davidovým hrobům, až k Umělému rybníku a až k domu hrdinů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Za ním opravovali lévité: Rechúm, syn Baního, vedle něho opravoval Chašabjáš, hejtman poloviny keílského okresu, za svůj okres.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Za ním opravovali jejich bratři: Bavaj, syn Chenadadův, hejtman druhé poloviny keílského okresu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Vedle něho opravoval Ezer, syn Jéšuův, mispanský hejtman, další úsek naproti vchodu do zbrojnice na rohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Za ním horlivě opravoval Báruk, syn Zabajův, další úsek od rohu až ke vchodu do domu velekněze Eljašíba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Za ním opravoval Meremót, syn Urijášův, vnuk Kósův, další úsek od vchodu do Eljašíbova domu až na konec Eljašíbova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Za ním opravovali kněží, muži z Jordánské roviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Za ním naproti svým domům opravovali Benjamín a Chašúb. Za ním vedle svého domu opravoval Azarjáš, syn Maasejášův, vnuk Ananjášův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Za ním opravoval Binúj, syn Chenadadův, další úsek od Azarjášova domu až na roh, až na nároží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Pálal, syn Úzajův, opravoval naproti rohu a věž vyčnívající nad horní královský palác na nádvoří stráží. Za ním opravoval Pedajáš, syn Pareóšův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Chrámoví nevolníci, kteří bydleli na Ófelu, opravovali až k místu naproti Vodní bráně na východě a vyčnívající věži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Za ním opravovali Tekójští další úsek od místa naproti velké vyčnívající věži až k ófelským hradbám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Od Koňské brány opravovali kněží, každý naproti svému domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Za ním naproti svému domu opravoval Sádok, syn Imerův. Za ním opravoval Šemajáš, syn Šekanjášův, strážce Východní brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Za ním opravoval Chananjáš, syn Šelemjášův a Chanún, šestý syn Salafův, další úsek. Za ním naproti svému pokoji opravoval Mešulám, syn Berekjášův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Za ním opravoval Malkijáš, jeden ze zlatníků, až k domu chrámových nevolníků a obchodníků, naproti Strážné bráně a až k horní místnosti na nároží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Mezi horní místností na nároží a Ovčí bránou opravovali zlatníci a obchodníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 33, 'Stalo se, když Sanbalat uslyšel, že stavíme hradby, že se rozzlobil, velice se rozhněval a vysmíval se Judejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 34, 'Řekl před svými bratry a samařským vojskem: Co to ti ubozí Judejci dělají? Cožpak ⌈obnoví Jeruzalém?⌉ Cožpak budou obětovat? Dokončí to za den? Copak oživí kameny z hromady trosek a prachu? Vždyť jsou spáleny!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 35, 'Tóbijáš amónský stál vedle něho a řekl: ⌈I když stavějí,⌉ vyskočí na to liška a jejich kamennou hradbu zboří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 36, '⌈Slyš, Bože⌉ náš, že jsme v opovržení! Obrať jejich potupu na jejich hlavu a vydej je za kořist v zemi vyhnanství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 37, 'Nepřikrývej jejich vinu, ať jejich hřích není smazán před tebou, protože ⌈se zlobili na ty,⌉ kdo stavějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 38, 'Stavěli jsme hradby dál a všechny hradby byly spojeny do poloviny výšky. Lid měl srdce při díle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Když Sanbalat, Tóbijáš, Arabové, Amónci a Ašdóďané uslyšeli, že zacelení jeruzalémských hradeb postoupilo, že se začaly trhliny uzavírat, hrozně se rozzlobili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Společně se všichni spikli, že vytáhnou bojovat proti Jeruzalému a způsobí v něm zmatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Nato jsme se modlili ke svému Bohu a postavili jsme proti nim ⌈ve dne i v noci⌉ stráž na obranu před nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Juda řekl: Ochabla síla nosičů, je ještě mnoho sutin a my nejsme schopni stavět na hradbách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Naši protivníci řekli: Nic nepoznají a nic neuvidí, dokud ne přijdeme mezi ně; zabijeme je a zastavíme tu práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Stalo se, když přišli Judejci, kteří bydleli blízko nich, že nám desetkrát řekli: ⌈Ze všech míst, kam se obrátíte, táhnou proti nám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Tehdy jsem postavil muže na nejnižších místech za hradbami, na otevřených místech, postavil jsem lid podle čeledí s jejich meči, oštěpy a luky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Když jsem viděl, že se bojí, vstal jsem a řekl jsem šlechticům, správcům a ostatnímu lidu: Nebojte se jich! Pamatujte na Panovníka velkého a hrozného, a bojujte za své bratry, za své syny a dcery, za své ženy a domy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Když naši nepřátelé uslyšeli, že jsme se to dozvěděli, a že Bůh zmařil jejich plán, vrátili jsme se všichni k hradbám, každý ke své práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Stalo se, že od onoho dne polovina mých služebníků konala práci a polovina jich držela oštěpy, štíty, luky a pancíře. Knížata stála za celým judským domem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'který stavěl na hradbách. Nosiči břemen nosili takto: Jednou rukou konali práci a jednou drželi oštěp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Každý ze stavitelů měl svůj meč připoután na bedrech a stavěli. Trubač na beraní roh byl vedle mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Řekl jsem šlechticům, správcům a ostatnímu lidu: Práce je mnoho, je rozsáhlá a my jsme rozděleni na hradbách, daleko jeden od druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Na místo, odkud uslyšíte zvuk beraního rohu, tam se k nám shromážděte. Náš Bůh bude bojovat za nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Od východu jitřenky až do vyjití hvězd jsme konali práci, zatímco polovina držela oštěpy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'V onom čase jsem také řekl lidu: Ať každý se svým služebníkem zůstává přes noc uvnitř Jeruzaléma. Tak nám pomohou v noci jako stráž a ve dne v práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Já ani moji bratři, moji služebníci ani strážci, kteří ⌈mě následovali,⌉ jsme nesvlékali svůj oděv; každý měl svůj oštěp ⌈ v pravici.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Nastalo velké volání lidu a jejich žen proti jejich bratrům Judejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Někteří říkali: Našich synů a našich dcer ⌈je mnoho.⌉ ⌈ Musíme dostat⌉ obilí, abychom se najedli a zůstali naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Jiní říkali: Dáváme do zástavy svá pole, své vinice a své domy, abychom dostali obilí v tomto hladu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'A jiní říkali: Na svá pole a své vinice jsme si vypůjčili peníze na královskou daň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, '⌈A nyní je naše tělo jako tělo našich bratrů⌉ a naši synové jsou jako jejich synové; avšak hle, my musíme nechávat podmanit své syny a své dcery za otroky a některé z našich dcer již byly podmaněny; jsme bezmocní, když naše pole a naše vinice patří jiným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Když jsem uslyšel jejich úpěnlivý křik a tato slova, hrozně jsem se rozzlobil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, '⌈Porozmýšlel jsem o tom ⌉ a vedl jsem při proti šlechticům a správcům. Řekl jsem jim: Vymáháte lichvářský úrok od svých bratrů! A svolal jsem proti nim velké shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Řekl jsem jim: My, pokud ⌈jsme mohli,⌉ vykupovali jsme své bratry Judejce, prodané pohanským národům. A vy dokonce prodáváte své bratry, aby byli zase prodáni nám! Mlčeli a nenašli slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Dále jsem řekl: To, co děláte, ne ní dobré! Cožpak nebudete žít v bázni před naším Bohem, abyste nebyli na potupu pohanským národům, našim nepřátelům?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Také já, moji bratři a moji služebníci jsme jim půjčovali peníze a obilí. Odpusťme jim ten úrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Vraťte jim ještě dnes jejich pole, jejich vinice, jejich olivové háje a jejich domy i úrok z peněz, obilí, nového vína a oleje, které jste jim půjčili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Nato řekli: Vrátíme a nebudeme od nich nic požadovat. Učiníme tak, jak říkáš. Pak jsem svolal kněze a nechal je přísahat, že budou jednat podle tohoto slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Vytřepal jsem i záhyb svého oděvu a řekl jsem: Takto ať Bůh vytřepe z jeho domu a z jeho majetku každého, kdo nenaplní toto slovo; takto bude vytřepán a vyprázdněn. Nato celé shromáždění řeklo: Amen a chválilo Hospodina. Potom lid jednal podle tohoto slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Navíc ode dne, kdy mě král ustanovil, abych byl jejich místodržitelem v judské zemi, od dvacátého roku až do třicátého druhého roku vlády krále Artaxerxa, po dvanáct let, jsem já ani moji bratři nejedli potravu určenou pro místodržitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Dřívější místodržitelé, kteří byli přede mnou, zatěžovali lid a brali od něj potravu a víno a ⌈k tomu⌉ čtyřicet šekelů stříbra. Také jejich služebníci svévolně panují nad lidem. Ale já jsem to nedělal z bázně před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Také jsem se zapojil do práce na těchto hradbách. Pole jsme nekoupili, ale všichni moji služebníci tam byli shromážděni k práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Dále u mého stolu byli Judejci a správci, sto padesát mužů, a ti, kteří k nám přišli z pohanských národů okolo nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Na jeden den bylo připravováno toto: Jeden býk a šest vybraných ovcí; také pro mě připravovali drůbež a každých deset dnů množství různých druhů vína. Přitom jsem nepožadoval potravu určenou pro místodržitele, protože služba už tak dost zatěžovala tento lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Pamatuj na mě, ⌈můj Bože,⌉ k mému dobru, na všechno, co jsem učinil pro tento lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Stalo se, když se Sanbalat, Tóbijáš, Arab Gešem a ostatní naši nepřátelé doslechli, že jsem postavil hradby a že v nich nezůstala žádná trhlina, ačkoliv v té době jsem ještě nevsadil do bran vrata,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Sanbalat a Gešem mi vzkázali: Přijď, setkáme se spolu ⌈ve vesnicích⌉ na pláni Ónu. Zamýšleli mi však provést zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Poslal jsem k nim posly se slovy: Konám velkou práci a nemohu přijít. Proč by měla práce přestat, když bych ji opustil a přišel k vám?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Takto ke mně poslali čtyřikrát a já jsem jim vždy takto odpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Sanbalat takto ke mně poslal popáté svého služebníka s otevřeným dopisem v ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'V něm bylo napsáno: Mezi národy se proslýchá, i Gešem to říká, že ty a Judejci se zamýšlíte bouřit. Proto stavíš hradby a staneš se takto jejich králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Ustanovil jsi také proroky, aby o tobě v Jeruzalémě provolávali: V Judsku je král! Teď se o tom doslechne král. Tak přijď a poradíme se spolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Poslal jsem k němu se slovy: Ty věci, které jsi říkal, se nestaly, ale sám sis je vymyslel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Všichni nás chtěli zastrašit slovy: ⌈Jejich ruce ochabnou od práce⌉ a nebude vykonána. Proto nyní posilni mé ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Když jsem vstoupil do domu Šemajáše, syna Delajášova, vnuka Mehétabelova, který byl zadržován, řekl: Sejděme se v Božím domě, uvnitř chrámu a zavřeme chrámové dveře, protože přijdou, aby tě zabili; v noci přijdou, aby tě zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Nato jsem řekl: Cožpak člověk jako já bude utíkat? Cožpak by někdo jako já mohl vstoupit do chrámu, a zůstat naživu? Nevstoupím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Rozpoznal jsem, že ho neposlal Bůh, ale mluvil proroctví proti mně, protože ho najali Tóbijáš a Sanbalat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Byl najat proto, abych ⌈ ze strachu takto jednal⌉ a zhřešil. Měli by tak záminku k poškození mého jména, aby mě mohli tupit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Můj Bože, pamatuj na Tóbijáše a na Sanbalata za tyto jejich skutky, a také na prorokyni Nóadju a na ostatní proroky, kteří mě zastrašovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, '⌈Hradby byly dokončeny⌉ dvacátého pátého dne měsíce elúlu, za padesát dva dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Stalo se, když to uslyšeli všichni naši nepřátelé a když to uviděly všechny pohanské národy okolo nás, že velmi klesli ve svých očích, protože poznali, že tato práce byla vykonána od našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'V oněch dnech také dopisy mnoha judských šlechticů chodily Tóbijášovi a Tobijášovy přicházely jim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'protože mnozí v Judsku s ním byli spojeni přísahou, neboť byl zetěm Šekanjáše, syna Árachova, a jeho syn Jóchanan si vzal za ženu dceru Mešuláma, syna Berekjášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Povídali také přede mnou o jeho dobrých vlastnostech a donášeli mu má slova. Tóbijáš posílal dopisy, aby mě zastrašoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Stalo se, když ⌈byly vybudovány hradby⌉ a vsadil jsem vrata, že byli určeni vrátní, zpěváci a lévité.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Ustanovil jsem nad Jeruzalémem svého bratra Chananího a Chananjáše, velitele hradu, protože byl spolehlivým člověkem a bál se Boha víc než mnozí jiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Řekl jsem jim: Jeruzalémské brány nebudou otevírány, dokud slunce ne bude hřát. Zatímco budou stát stráže na stráži, budou zavírat dveře; pak zamkněte. Postavte stráže z obyvatel Jeruzaléma; každého na jeho strážné stanoviště, každého před jeho dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Město bylo rozlehlé a velké, ale lidu v něm bylo málo a domy se nestavěly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Můj Bůh mi položil na srdce, abych shromáždil šlechtice, správce a lid, aby se zapsali do rodokmenů. Našel jsem knihu s rodokmeny prvních přistěhovalců a našel jsem v ní napsáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Toto jsou obyvatelé judské provincie, kteří vyšli ze zajetí, vyhnanci, které odvedl babylonský král Nebúkadnesar a navrátili se do Jeruzaléma a do Judska, každý do svého města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Přišli se Zerubábelem, Jéšuou, Nehemjášem, Azarjášem, Raamjášem, Nachamaním, Mordokajem, Bilšánem, Misperetem, Bigvajem, Nechúmem a Baanou. Toto je výčet mužů izraelského lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Synů Pareóšových dva tisíce sto sedmdesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'synů Šefatjášových tři sta sedmdesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'synů Árachových šest set padesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'synů Pachat–moábových, totiž synů Jéšuových a Jóabových, dva tisíce osm set osmnáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'synů Élamových tisíc dvě stě padesát čtyři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'synů Zatúových osm set čtyřicet pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'synů Zakajových sedm set šedesát;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'synů Binújových šest set čtyřicet osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'synů Bebajových šest set dvacet osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'synů Azgadových dva tisíce tři sta dvacet dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'synů Adoníkamových šest set šedesát sedm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'synů Bigvajových dva tisíce šedesát sedm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'synů Adínových šest set padesát pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'synů Aterových, totiž Chizkijášových, devadesát osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'synů Chašumových tři sta dvacet osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'synů Besajových tři sta dvacet čtyři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'synů Charífových sto dvanáct;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'synů Gibeónových devadesát pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'mužů z Betléma a Netófy sto osmdesát osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'mužů z Anatótu sto dvacet osm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'mužů z Bét–azmávetu čtyřicet dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'mužů z Kirjat–jearímu, Kefíry a Beerótu sedm set čtyřicet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'mužů z Rámy a Geby šest set dvacet jedna;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'mužů z Mikmásu sto dvacet dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'mužů z Bét–elu a Aje sto dvacet tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'mužů z jiného Neba padesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'synů jiného Élama tisíc dvě stě padesát čtyři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'synů Charimových tři sta dvacet;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'mužů z Jericha tři sta čtyřicet pět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'mužů z Lódu, Chadídu a Óna sedm set dvacet jedna;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'synů Senáových tři tisíce devět set třicet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Kněží: synů Jedajášových z domu Jéšuova devět set sedmdesát tři;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'synů Imerových tisíc padesát dva;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'synů Pašchúrových tisíc dvě stě čtyřicet sedm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'synů Charimových tisíc sedmnáct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Lévitů: synů Jéšuových, totiž Kadmíelových a Hódavjášových sedmdesát čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Zpěváků: synů Asafových sto čtyřicet osm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Vrátných: synů Šalúmových, synů Aterových, synů Talmónových, synů Akúbových, synů Chatítových, synů Šobajových sto třicet osm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Chrámových nevolníků: synů Síchových, synů Chasúfových, synů Tabaótových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'synů Kérosových, synů Síaových, synů Padónových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'synů Lebánových, synů Chagábových, synů Šalmajových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'synů Chánanových, synů Gidélových, synů Gacharových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'synů Reajášových, synů Resínových, synů Nekódových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'synů Gazamových, synů Uzových, synů Paséachových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'synů Besajových, synů Meúnejců, synů Nefíšesejců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'synů Bakbúkových, synů Chakúfových, synů Charchúrových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'synů Baslítových, synů Mechídových, synů Charšových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'synů Barkósových, synů Síserových, synů Tamachových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'synů Nesíachových, synů Chatífových;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'synů Šalomounových otroků: Synů Sótajových, synů Sóferetových, synů Perídových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'synů Jaalových, synů Darkónových, synů Gidélových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'synů Šefatjášových, synů Chatílových, synů Pokereta Sebajimského, synů Amónových --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'všech chrámových nevolníků a synů Šalomounových otroků bylo tři sta devadesát dva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Toto jsou ti, kteří přišli z Tel–melachu, Tel–charšy, Kerúb–adónu a Imeru, ale nemohli určit ⌈rodinu svých otců a jejich potomstvo,⌉ zdali jsou z Izraele:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Synů Delajášových, synů Tóbijášových, synů Nekódových šest set čtyřicet dva');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'a z kněží synové Chobajášovi, synové Kósovi, synové Barzilaje, který si vzal ženu z dcer Barzilaje Gileádského a byl nazván podle jejich jména.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ti hledali svůj zápis v rodokmenech, ale nenašel se a byli jako nečistí vyloučeni z kněžství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Místodržitel jim řekl, že ne smějí jíst z nejsvětějšího jídla, dokud nepovstane kněz s urím a tumím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Celé shromáždění dohromady čítalo čtyřicet dva tisíc tři sta šedesát,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'kromě jejich otroků a otrokyň, jichž bylo sedm tisíc tři sta třicet sedm. Měli také dvě stě čtyřicet pět zpěváků a zpěvaček,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'čtyři sta třicet pět velbloudů, šest tisíc sedm set dvacet oslů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Někteří z předáků rodů dali dary na práci. Místodržitel dal na poklad tisíc zlatých darejků, padesát misek a pět set třicet kněžských rouch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'A někteří z předáků rodů dali na poklad určený pro práci dvacet tisíc zlatých darejků a dva tisíce dvě stě stříbrných hřiven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Toho, co dal ostatní lid, bylo dvacet tisíc zlatých darejků, dva tisíce stříbrných hřiven a šedesát sedm kněžských rouch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'I usídlili se kněží, lévité, vrátní, zpěváci i někteří z lidu, chrámoví nevolníci a celý Izrael ve svých městech. Když nastal sedmý měsíc, byli synové Izraele ve svých městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, '');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Všechen lid se shromáždil ⌈jako jeden muž⌉ na náměstí, které bylo před Vodní bránou a řekli písaři Ezdrášovi, aby přinesl knihu Mojžíšova zákona, jenž dal Hospodin Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Prvního dne sedmého měsíce kněz Ezdráš přinesl zákon před shromáždění ⌈mužů i žen,⌉ všech, kteří byli schopni rozumět tomu, co slyší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'a četl z něho na náměstí, které bylo před Vodní bránou, od svítání až do poledne před muži, ženami a těmi, kteří byli schopni rozumět; ⌈všechen lid pozorně naslouchal ⌉ knize zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Písař Ezdráš stál na dřevěném pódiu, které k tomu účelu postavili, a vedle něho stál po jeho pravici Matitjáš, Šema, Anajáš, Urijáš, Chilkijáš a Maasejáš a po jeho levici Pedajáš, Míšael, Malkijáš, Chašum, Chašbadána, Zekarjáš a Mešulám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Ezdráš otevřel knihu před očima všeho lidu, protože stál výše než všechen lid. Když ji otevřel, všechen lid povstal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Ezdráš dobrořečil Hospodinu, velikému Bohu, a všechen lid odpověděl: Amen, amen a ⌈pozvedal přitom⌉ své ruce; poklekali a klaněli se Hospodinu ⌈tváří k zemi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Jéšua, Baní, Šerebjáš, Jamín, Akúb, Šabetaj, Hódijáš, Maasejáš, Kelíta, Azarjáš, Józabad, Chánan, Pelajáš, lévité, vyučovali lid zákonu, zatímco lid stál na svém místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Četli z knihy Božího zákona po oddílech a vykládali smysl, aby všichni rozuměli tomu, co se četlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Potom Nehemjáš, který byl místodržitelem, kněz a písař Ezdráš a lévité, kteří vyučovali lid, řekli všemu lidu: Tento den je svatý Hospodinu, vašemu Bohu. Netruchlete a neplačte! Všechen lid totiž plakal, když slyšel slova zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Řekl jim: Jděte, jezte tučná jídla, pijte sladké nápoje a posílejte podíly těm, kteří nic nemají, protože tento den je svatý našemu Pánu. Netrapte se, protože radost z Hospodina bude vaší silou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Lévité přikazovali všemu lidu, aby se utišil. Říkali: Uklidněte se, protože tento den je svatý, a netrapte se!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Všechen lid šel, aby jedli, pili, posílali podíly a slavili velký svátek, protože porozuměli slovům, která jim oznámili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Druhý den se předáci rodů všeho lidu, kněží a lévité shromáždili k písaři Ezdrášovi, aby porozuměli slovům zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'A nalezli napsáno v zákoně, který dal Hospodin prostřednictvím Mojžíše, že synové Izraele mají při svátku v sedmém měsíci bydlet ve stáncích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'a že mají rozhlásit a provolat ve všech svých městech a v Jeruzalémě slova: Vyjděte do hor a přineste větve oliv šlechtěných i planých, větve myrtové, palmové i jiných listnatých stromů, abyste udělali stánky, jak je napsáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Lid vyšel, přinesli větve a udělali si stánky, každý na své střeše, na svých dvorech a na nádvořích Božího domu, na náměstí u Vodní brány a na náměstí Efrajimovy brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Celé shromáždění těch, kteří se navrátili ze zajetí, si udělalo stánky a bydleli ve stáncích, ačkoliv tak synové Izraele nečinili ode dnů Jozua, syna Núnova, až do onoho dne. A byla velmi veliká radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Četl z knihy Božího zákona den co den, od prvního dne až do posledního. Sedm dní slavili svátek a osmého dne se konalo shromáždění podle nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Dvacátého čtvrtého dne toho měsíce se synové Izraele shromáždili ⌈v postu,⌉ žíněných rouchách a ⌈na svých hlavách měli prsť.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Potomstvo Izraele se oddělilo od všech cizích obyvatel. Stáli a vyznávali své hříchy a viny svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Povstávali na svých místech a čtvrtinu dne četli z knihy zákona Hospodina, svého Boha, a další čtvrtinu vyznávali a klaněli se Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Potom Jéšua, Baní, Kadmíel, Šebanjáš, Buní, Šerebjáš, Baní a Kenaní vystoupili na stupínek lévitů a hlasitě volali k Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Lévité Jéšua, Kadmíel, Baní, Chašabnejáš, Šerebjáš, Hódijáš, Šebanjáš, Petachjáš řekli: Povstaňte, dobrořečte Hospodinu, svému Bohu, od věků až navěky! Ať dobrořečí tvému slavnému jménu, které je vyvýšeno nad každé dobrořečení a chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ty jediný jsi Hospodin. Ty jsi učinil nebesa, nebesa nebes i všechen jejich zástup, zemi i všechno, co je na ní, moře i všechno, co je v nich. Ty oživuješ všechno, tobě se klanějí nebeské zástupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Ty jsi Hospodin, Bůh, který vyvolil Abrama, vyvedl ho z chaldejského Úru a změnil mu jméno na Abraham.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Shledal jsi jeho srdce věrným před sebou a uzavřel jsi s ním smlouvu, že mu dáš zemi Kenaanců, Chetejců, Emorejců, Perizejců, Jebúsejců a Girgašejců, že ji dáš jeho potomstvu; a naplnil jsi svá slova, protože jsi spravedlivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Pohleděl jsi na soužení našich otců v Egyptě a vyslyšel jsi jejich úpěnlivý křik u Rákosového moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Učinil jsi znamení a divy na faraonovi, na všech jeho otrocích a na všem lidu jeho země, protože jsi věděl, že s nimi jednali povýšeně. ⌈Učinil sis jméno, jak je tomu dodnes.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Rozpoltil jsi před nimi moře a prošli prostředkem moře po suchu, ale jejich pronásledovatele jsi uvrhl do hlubin jako kámen do dravých vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Ve dne jsi je vodil oblakovým sloupem a v noci ohnivým sloupem, aby jim osvěcoval cestu, po které měli jít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Sestoupil jsi na horu Sínaj a mluvil jsi s nimi z nebes. Dal jsi jim správná nařízení a spolehlivé zákony, dobrá ustanovení a příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Dal jsi jim poznat svou svatou sobotu a dal jsi jim prostřednictvím svého otroka Mojžíše příkazy, ustanovení a zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Dal jsi jim chléb z nebe na jejich hlad a vyvedl jsi jim vodu ze skály na jejich žízeň. Řekl jsi jim, aby šli a získali do vlastnictví zemi, o které ⌈ jsi pozvednutím ruky přísahal,⌉ že jim ji dáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Ale oni, naši otcové, jednali povýšeně a zatvrdili svou šíji a neposlouchali tvé příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Odmítali poslouchat a nepamatovali na tvoje obdivuhodné činy, které jsi s nimi konal. Zatvrdili svou šíji a ⌈vzali si do hlavy vrátit⌉ se do svého otroctví ⌈v Egyptě.⌉ Ale ty jsi Bůh odpouštějící, milostivý a soucitný, pomalý k hněvu, hojný v milosrdenství a neopustil jsi je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'I když si udělali slité tele a řekli: Toto je tvůj Bůh, který tě vyvedl z Egypta, a ⌈velice se rouhali,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'ty, ve svém mnohém slitování, jsi je v pustině neopustil. Ve dne od nich neodstupoval oblakový sloup, aby je vedl po cestě, ani v noci ohnivý sloup, který jim osvěcoval cestu, po níž měli jít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Dával jsi jim svého dobrého ducha, aby je přiváděl k porozumění. ⌈Jejich ústům jsi neodepřel⌉ svou manu a na jejich žízeň jsi jim dával vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Čtyřicet let jsi o ně pečoval v pustině, neměli nedostatek. Jejich pláště se neobnosily, jejich nohy neopuchly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Dal jsi jim království a národy, přidělil jsi jim každý kout. Dostali do vlastnictví zemi Síchona, zemi chešbónského krále a zemi bášanského krále Óga.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Jejich syny jsi rozmnožil jako nebeské hvězdy a přivedl jsi je do země, o které jsi řekl jejich otcům, aby šli a získali ji do vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Synové vešli a dostali zemi do vlastnictví. Pokořil jsi před nimi obyvatele země, Kenaance, a dal jsi jim do ruky krále a národy země, aby s nimi učinili, jak se jim zlíbí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Dobyli opevněná města a úrodnou zemi, dostali do vlastnictví domy plné všelijakých dobrých věcí, vykopané studny, vinice, olivové háje a množství ovocných stromů. Jedli, nasytili se a ztloustli, ⌈žili v blahobytu⌉ ze tvé velké dobroty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Vzpírali se však a vzbouřili se proti tobě, odvrhli tvůj zákon za svá záda; zabili tvé proroky, kteří je napomínali, aby je navrátili k tobě. Velice se rouhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Vydal jsi je do ruky jejich protivníků, kteří jim způsobili soužení. Potom v čase svého soužení křičeli k tobě, ty jsi slyšel z nebe a podle svého mnohého slitování jsi jim dal zachránce, kteří je zachránili z ruky jejich protivníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Jakmile měli klid, znovu páchali, co je před tebou zlé. Tak jsi je přenechal do ruky jejich nepřátel a ti nad nimi panovali. Znovu k tobě volali o pomoc, ty jsi slyšel z nebe a mnohokrát jsi je vysvobodil podle svého mnohého slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Napomínal jsi je, aby se navrátili k tvému zákonu. Ale oni jednali povýšeně, neuposlechli tvé příkazy a hřešili proti tvým nařízením, jejichž plněním bude člověk žít. ⌈Obrátili se však vzpurně zády,⌉ zatvrdili svou šíji a neposlouchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Mnoho let jsi ⌈s nimi měl trpělivost,⌉ napomínal jsi je svým Duchem prostřednictvím svých proroků, ale neposlouchali. Proto jsi je dal do ruky národů zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Ve svém mnohém slitování jsi je nezničil úplně a neopustil jsi je, protože jsi Bůh milostivý a soucitný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'A nyní, náš Bože, Bože velký, mocný a hrozný, který zachováváš smlouvu a milosrdenství, nezlehčuj všechny těžkosti, které postihly nás, naše krále, naše knížata, naše kněze, naše proroky, naše otce a všechen tvůj lid ode dnů asyrských králů až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Ty jsi spravedlivý ve všem, co na nás přišlo, protože jsi jednal spolehlivě, ale my jsme jednali ničemně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Také naši králové, naše knížata, naši kněží a naši otcové nejednali podle tvého zákona a nevěnovali pozornost tvým příkazům a tvým napomenutím, kterými jsi je napomínal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Ve svém království, přes tvoji mnohou dobrotu, kterou jsi jim dal, v rozlehlé a úrodné zemi, kterou jsi před ně položil, tobě nesloužili a od svých zlých činů se neodvrátili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Hle, my jsme dnes otroci a země, kterou jsi dal našim otcům, aby jedli její ovoce a její dobrotu, hle, jsme na ní otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Její hojná úroda patří králům, které jsi ustanovil nad námi pro naše hříchy a vládnou nad našimi těly i nad naším dobytkem, jak se jim zlíbí. Jsme ve velikém soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, '⌈Kvůli všemu tomuto⌉ uzavíráme a sepisujeme smlouvu; na zapečetěné listině jsou naše knížata, naši lévité a naši kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Na zapečetěných listinách byli: Místodržitel Nehemjáš, syn Chakaljášův, a Sidkijáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Serajáš, Azarjáš, Jeremjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Pašchúr, Amarjáš, Malkijáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Chatúš, Šebanjáš, Malúk,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Charim, Meremót, Obadjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Daniel, Ginetón, Báruk,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mešulám, Abijáš, Mijamín,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Maazjáš, Bilgaj, Šemajáš; to jsou kněží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Lévité: Jéšua, syn Azanjášův, Binúj ze synů Chenadadových, Kadmíel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'a jejich bratři Šebanjáš, Hódijáš, Kelíta, Pelajáš, Chánan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Míka, Rechób, Chašabjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Zakúr, Šerebjáš, Šebanjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hódijáš, Baní, Benínú.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Předáci lidu: Pareóš, Pachat–moáb, Élam, Zatú, Baní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Buní, Azgad, Bebaj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Adónijáš, Bigvaj, Adín,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Ater, Chizkijáš, Azúr,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hódijáš, Chašum, Besaj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Charíf, Anatót, Nébaj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Magpíaš, Mešulám, Chezír,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Mešézabel, Sádok, Jadúa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Pelatjáš, Chánan, Anajáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hóšea, Chananjáš, Chašúb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Lócheš, Pilchá, Šobek,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Rechúm, Chašabna, Maasejáš');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'a Achijáš, Chánan, Anan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Malúk, Charim, Baana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Ostatek lidu, kněží, lévité, vrátní, zpěváci, chrámoví nevolníci a všichni, kdo se oddělili z národů zemí pro Boží zákon, jejich ženy, jejich synové a jejich dcery, všichni, kdo byli schopni znát a rozumět,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'se připojili ke svým bratrům a svým vznešeným předákům a vstoupili pod prokletí a pod přísahu, že budou žít podle Božího zákona, který byl vydán prostřednictvím Božího otroka Mojžíše, a že budou zachovávat a plnit všechny příkazy Hospodina, našeho Pána, jeho nařízení a jeho ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'A že nebudeme dávat své dcery národům země ani nebudeme brát jejich dcery pro své syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Jestliže národy země přinášejí zboží a jakékoliv obilí v sobotní den, aby je prodávali, v sobotu, ve svatý den, nebudeme od nich nic brát. V sedmém roce se zřekneme úrody a vymáhání ⌈jakéhokoliv dluhu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, '⌈Přijímáme pro sebe také závazek,⌉ že budeme dávat třetinu šekelu za rok pro službu domu našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Na předkladný chléb, ustavičnou přídavnou oběť, na ustavičnou zápalnou oběť, na oběti o sobotách, o novoluních, na svátky, na svaté dary, na oběti za hřích k získání smíření pro Izrael a veškerou službu domu našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Nechali jsme také padnout losy mezi kněžími, lévity a lidem na dodávky dřeva, aby je přinášeli do domu našeho Boha podle rodin v určený čas, rok co rok, aby bylo zapalováno na oltáři Hospodina, našeho Boha, jak je napsáno v zákoně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Budeme přinášet také prvotiny ze své země a prvotiny ze všeho ovoce každého stromu rok co rok do Hospodinova domu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'budeme přinášet do domu svého Boha kněžím, kteří slouží v domě našeho Boha, prvorozené ze svých synů a zvířat, jak je napsáno v zákoně, a prvorozené ze svého skotu a svých ovcí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'prvotiny ze svého těsta, ze svých darů pozdvihování, z ovoce každého stromu, nového vína a oleje budeme přinášet kněžím do komor domu našeho Boha a desátek ze své země lévitům. Lévité totiž budou vybírat desátek ve všech ⌈našich venkovských městech.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Když budou lévité vybírat desátek, bude s lévity kněz, syn Áronův. Lévité pak přinesou desátek z desátku do domu našeho Boha, do komory skladu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'neboť do těchto komor budou synové Izraele a synové lévitů přinášet dávky z obilí, nového vína a oleje. Tam jsou nádoby svatyně, kněží, kteří slouží, vrátní a zpěváci. Nebudeme zanedbávat dům svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Knížata lidu bydlela v Jeruzalémě; ostatek lidu nechal padnout losy, aby přivedl jednoho z deseti, aby bydlel v Jeruzalémě, svatém městě, a ostatních devět aby zůstalo v jiných městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Lid požehnal všem mužům, kteří se dobrovolně rozhodli bydlet v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Toto jsou předáci provincie, kteří bydleli v Jeruzalémě; (v judských městech každý bydlel na svém vlastnictví, ve svých městech: Izraelci, kněží, lévité, chrámoví nevolníci a synové Šalomounových otroků):');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'V Jeruzalémě bydleli někteří ze synů Judových a synů Benjamínových. Ze synů Judových: Atajáš, syn Uzijáše, syna Zekarjáše, syna Amarjáše, syna Šefatjáše, syna Mahalalela ze synů Peresových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'A Maasejáš, syn Báruka, syna Kolchoza, syna Chazajáše, syna Adajáše, syna Jójaríba, syna Zekarjáše, ⌈syna Šílona.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Všech synů Peresových, kteří bydleli v Jeruzalémě, bylo čtyři sta šedesát osm udatných mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Toto jsou synové Benjamínovi: Salu, syn Mešuláma, syna Jóeda, syna Pedajáše, syna Kólajáše, syna Maasejáše, syna Ítiela, syna Ješajášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'A ⌈jeho potomci⌉ Gabaj a Salaj, devět set dvacet osm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Jóel, syn Zikrího, byl dohlížitelem nad nimi, a Juda, syn Senúův, byl druhý nad městem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Z kněží: Jedajáš, syn Jójaríbův, Jakín,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Serajáš, syn Chilkijáše, syna Mešuláma, syna Sádoka, syna Merajóta, syna Achítúbova, vrchní dohlížitel nad Božím domem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'a jejich bratři, kteří konali službu v domě: osm set dvacet dva. Dále Adajáš, syn Jerocháma, syna Pelaljáše, syna Amsího, syna Zekarjáše, syna Pašchúra, syna Malkijášova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'a jeho bratři, předáci nad rody: dvě stě čtyřicet dva. Amašsaj, syn Azarela, syna Achazaje, syna Mešilemóta, syna Imerova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'A jejich bratři, udatní hrdinové: sto dvacet osm. Dohlížitelem nad nimi byl Zabdíel, syn Gedólímův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Z lévitů: Šemajáš, syn Chašúba, syna Azríkama, syna Chašabjáše, syna Buníova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Šabetaj a Józabad z předáků lévitů byli nad venkovní prací Božího domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Matanjáš, syn Míky, syna Zabdího, syna Asafova, vedoucí chvály, který při modlitbě začíná chválu, a Bakbukjáš, druhý mezi svými bratry. Dále Abda, syn Šamúy, syna Gálala, syna Jedútúnova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Všech lévitů ve svatém městě bylo dvě stě osmdesát čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Vrátní: Akúb, Talmón a jejich bratři, kteří střežili v branách, sto sedmdesát dva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Ostatní Izraelci, kněží a lévité, byli ve všech judských městech, každý na svém dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Chrámoví nevolníci bydleli na Ófelu; Sícha a Gišpa byli nad chrámovými nevolníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Dohlížitelem lévitů v Jeruzalémě byl Uzí, syn Baního, syna Chašabjáše, syn Matanjáše, syna Míky, ze synů Asafových, kteří zpívali při službě v Božím domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Existoval o nich totiž královský příkaz, pevný předpis o zpěvácích s každodenním určením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petachjáš, syn Mešézabelův, ze synů Zeracha, syna Judova, byl ⌈králi po ruce⌉ pro všechny záležitosti lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Někteří ze synů Judových se usadili ve dvorcích na svých polích v Kirjat–arbě a jejích vesnicích, v Díbónu a jeho vesnicích, v Jekabseelu a jeho dvorcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'V Ješúe, v Móladě a v Bét–peletu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'v Chasar–šúalu, v Beer–šebě a jejích vesnicích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'v Siklagu, v Mekóně a v jejích vesnicích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'v Én–rimónu, v Soreji, v Jarmútu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanóachu, Adulámu a jejich dvorcích, Lakíši a jeho polích, Azece a jejích vesnicích. Utábořili se od Beer–šeby až k Hinómskému údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Synové Benjamínovi žili od Geby dále v Mikmásu, Aji, Bét–elu a jeho vesnicích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anatótu, Nóbu, Ananji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Chasóru, Rámě, Gitajimu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Chadídu, Seboímu, Nebalatu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lódu, Ónu a údolí řemeslníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Z lévitů některé judské skupiny patřily Benjamínovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Toto jsou kněží a lévité, kteří se vrátili se Zerubábelem, synem Šealtíelovým, a Jéšuou: Serajáš, Jeremjáš, Ezdráš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarjáš, Malúk, Chatúš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Šekanjáš, Rechum, Meremót,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Idó, Ginetój, Abijáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, '⌈Mijamín, Maadjáš, Bilga,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Šemajáš, Jójaríb, Jedajáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Salú, Amók, Chilkijáš, Jedajáš. To byli předáci kněží a jejich bratři za dnů Jéšuy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Lévité: Jéšua, Binúj, Kadmíel, Šerebjáš, Juda, Matanjáš, ⌈ který měl se svými bratry na starost písně díkůvzdání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, '⌈Bakbukjáš, Uni a jejich bratři⌉ stáli podle ⌈služebních oddílů⌉ proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jéšua zplodil Jójakíma, Jójakím zplodil Eljašíba, Eljašíb Jójadu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jójada zplodil Jónatana, Jónatan zplodil Jadúu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Ve dnech Jójakíma byli kněžími tito předáci rodů: za rodinu Serajášovu Merajáš, za Jeremjášovu Chananjáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'za Ezdrášovu Mešulám, za Amarjášovu Jóchanan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'za Malúkovu Jónatan, za Šebanjášovu Josef,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'za Charimovu Adna, za Merajótovu Chelkaj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'za Idovu Zekarjáš, za Ginetónovu Mešulám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'za Abijášovu Zikrí, za Minjamínovu a za Móadjášovu Piltaj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'za Bilgovu Šamúa, za Šemajášovu Jónatan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'za Jójaríbovu Matenaj, za Jedajášovu Uzí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'za Salajovu Kalaj, za Amókovu Eber,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'za Chilkijášovu Chašabjáš, za Jedajášovu Netanel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Ve dnech Eljašíba, Jójady, Jóchanana a Jadúy byli zapsáni lévité, předáci rodů, i kněží až do kralování Dareia perského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Synové Léviho, předáci rodů, byli zapsáni do knihy Letopisů až do dnů Jóchanana, syna Eljašíbova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Předáci lévitů: Chašabjáš, Šerebjáš, Jéšua, syn Kadmíelův, a jejich bratři stáli proti nim, aby chválili a vzdávali díky podle příkazu Davida, ⌈muže Božího,⌉ oddíl vedle oddílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanjáš, Bakbukjáš, Obadjáš, Mešulám, Talmón, Akúb byli strážci, kteří drželi stráž vrátných ve skladech u bran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Tito byli ve dnech Jójakíma, syna Jéšuova, vnuka Jósadakova, ve dnech místodržitele Nehemjáše a kněze a písaře Ezdráše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Při posvěcení hradeb Jeruzaléma vyhledali lévity ze všech míst, aby je přivedli do Jeruzaléma a slavili svátek posvěcení s písněmi díků a se zpěvem, činely, harfami a lyrami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, '⌈Ti, kteří patřili k zpěvákům,⌉ se shromáždili z Jordánské roviny, okolí Jeruzaléma a z netófatských dvorců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'z Bét–gilgálu, z polností Geby a Azmávetu, protože zpěváci si postavili dvorce okolo Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Kněží a lévité se očistili a očistili lid, brány a hradby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Pak jsem přivedl judská knížata na hradby a ustanovil jsem dva velké sbory. ⌈ Jeden šel⌉ napravo po hradbách k Hnojné bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Za nimi šel Hóšajáš a polovina judských knížat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Azarjáš, Ezdráš, Mešulám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamín, Šemajáš, Jeremjáš');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'a ze synů kněží s trubkami: Zekarjáš, syn Jónatana, syna Šemajáše, syna Matanjáše, syna Míkajáše, syna Zakúra, syna Asafova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'A jeho bratři: Šemajáš, Azarel, Milalaj, Gilalaj, Maaj, Netanel, Juda a Chananí s hudebními nástroji Davida, muže Božího. Písař Ezdráš šel před nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'U Studniční brány vystoupili přímo po schodech Města Davidova a u vstupu na hradby nad Davidovým domem a až k Vodní bráně na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Druhý sbor šel opačným směrem; já a polovina lidu za ním po hradbách nad Pecnou věží až k Širokým hradbám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'nad Efrajimovou bránou, ke Staré bráně, k Rybné bráně, Chananeelově věži, věži Meá, až k Ovčí bráně a zastavili se ve Strážní bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'V Božím domě stály dva sbory, já a polovina správců se mnou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'kněží Eljakím, Maasejáš, Minjamín, Míkajáš, Eljóenaj, Zekarjáš, Chananjáš s trubkami,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Maasejáš, Šemajáš, Eleazar, Uzí, Jóchanan, Malkijáš, Élam, Ezer. Zpěváci zpívali a Jizrachjáš byl jejich dirigentem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'V onen den obětovali veliké oběti a radovali se, protože jim Bůh dal velikou radost. Také ženy a děti se radovaly. Radost Jeruzaléma byla slyšet zdaleka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'V onen den byli určeni muži nad komorami pro poklady, dávky, prvotiny a desátky, aby do nich vybrali za městská pole podíly podle zákona pro kněze a lévity, protože ⌈Juda měl radost z kněží a lévitů,⌉ kteří stáli ve službě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Zachovávali řád svého Boha a řád očišťování. Také zpěváci a vrátní sloužili podle příkazu Davida a jeho syna Šalomouna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Neboť odedávna, už ve dnech Davida a Asafa, byli předáci zpěváků a písně chvály a díků Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Ve dnech Zerubábela a ve dnech Nehemjáše ⌈celý Izrael dával⌉ podíly zpěvákům a vrátným, každodenní podíl. Posvátné dary dávali lévitům a lévité dávali posvátné dary synům Áronovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'V onen den se četlo z knihy Mojžíšovy lidu a našlo se v ní napsáno, že Amónec a Moábec nesmí nikdy vejít do Božího shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Protože nevyšli synům Izraele vstříc s chlebem a vodou, ale najali proti nim Bileáma, aby je proklel; ale náš Bůh změnil kletbu v požehnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Stalo se, když slyšeli zákon, že oddělili z Izraele všechen míšený lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Předtím však kněz Eljašíb, určený nad komorami Božího domu, příbuzný Tóbijáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'mu zřídil velkou komoru. Předtím tam byly dávány přídavné oběti, kadidlo, nádoby, desátek z obilí, nového vína a oleje, přikázané lévitům, zpěvákům a vrátným a dávky pro kněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Při všem tom jsem nebyl v Jeruzalémě, protože ve třicátém druhém roce vlády babylonského krále Artaxerxa jsem šel ke králi. Po určitém čase jsem si od krále vyžádal dovolení odcestovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Jakmile jsem přišel do Jeruzaléma a porozuměl jsem tomu zlu, které spáchal Eljašíb pro Tóbijáše, když mu zřídil pokoj na nádvoří Božího domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'hrozně se mi to nelíbilo. Vyhodil jsem všechny věci Tóbijášovy domácnosti ven z komory');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'a řekl jsem, aby vyčistili komory. Pak jsem tam vrátil nádoby Božího domu, přídavné oběti a kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Dozvěděl jsem se, že lévitům nebyly dávány podíly, takže všichni lévité a zpěváci, kteří konali službu, utíkali na svá pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Vedl jsem při proti správcům a řekl jsem: Proč je Boží dům opuštěn? Shromáždil jsem je a ustanovil jsem je zpět na jejich místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, '⌈Všichni Judejci⌉ přinesli desátek z obilí, nového vína a oleje do skladů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Za skladníky ⌈nad sklady jsem určil⌉ kněze Šelemjáše, písaře Sádoka a z lévitů Pedajáše, a k ruce jim byli Chánan, syn Zakúrův, vnuk Matanjášův, protože byli považováni za věrné. Na nich bylo, aby rozdělovali svým bratrům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Pamatuj za to na mě, můj Bože, a nevymaž moji věrnost, kterou jsem prokázal domu svého Boha a ⌈jeho strážným.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'V oněch dnech jsem uviděl v Judsku ty, kdo lisují hrozny v sobotu, i ty, kteří přinášejí hromady obilí a nakládají na osly; přinášeli v sobotní den do Jeruzaléma také vinné hrozny, fíky a různý náklad. Varoval jsem je v den, kdy prodávali potraviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Týřané, kteří v něm bydleli, přinášeli ryby a různé zboží a prodávali v sobotu synům judským i v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Vedl jsem při proti judským šlechticům a řekl jsem jim: Co má znamenat toto zlo, které pácháte, když znesvěcujete sobotní den?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Cožpak takto nejednali vaši otcové, takže náš Bůh na nás a toto město přivedl všechno toto zlo? Když znesvěcujete sobotu, umocňujete planoucí hněv nad Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Stalo se, jakmile jeruzalémské brány před sobotou setměly, že jsem řekl, aby byla zavřena vrata. Pak jsem řekl, aby je neotevřeli dříve než skončí sobota. Některé ze svých služebníků jsem postavil k branám, aby v sobotní den nebyl přinesen žádný náklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Obchodníci a prodavači různého zboží zůstávali přes noc jednou či dvakrát vně Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Varoval jsem je a říkal jsem jim: Proč nocujete před hradbami? Jestliže to uděláte znovu, vztáhnu proti vám ruku. Od té doby v sobotu nepřicházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Řekl jsem lévitům, aby se očišťovali, když půjdou střežit brány, aby se světil sobotní den. Také v tomto na mě pamatuj, můj Bože, a slituj se nade mnou podle svého hojného milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'V oněch dnech jsem také viděl Judejce, kteří si brali za ženy Ašdóďanky, Amónky a Moábky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Polovina jejich synů mluvila ašdódsky a neuměli mluvit judsky, ale ⌈ mluvili jazykem toho či onoho lidu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Vedl jsem s nimi při a proklel jsem je; bil jsem některé z nich, rval jsem jim vlasy a zapřísahal jsem je při Bohu: Nedávejte své dcery jejich synům a neberte jejich dcery pro své syny ani pro sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Cožpak kvůli nim nezhřešil izraelský král Šalomoun? Mezi mnohými pohanskými národy nebyl král, jako byl on. Byl milý svému Bohu a Bůh ho ustanovil králem nad celým Izraelem. A také jeho svedly k hříchu cizí ženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Co že se o vás teď proslýchá, že pácháte všechno to velké zlo, když jste nevěrní svému Bohu a berete si cizí ženy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Jeden ze synů Jójady, vnuk velekněze Eljašíba, byl zetěm Sanbalata Chorónského. Vyhnal jsem ho od sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Pamatuj na ně, můj Bože, pro znečištění kněžství i kněžské a lévijské smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Vyčistil jsem je od všeho cizího a ustanovil jsem řády pro kněze i pro lévity, každému podle jeho služby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'pro dodávky dřeva v ⌈určený čas⌉ i pro prvotiny. Pamatuj na mě, můj Bože, k mému dobru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'I stalo se ve dnech Achašvéroše -- to byl ten Achašvéroš, který kraloval od Indie až po Kúš nad sto dvaceti sedmi provinciemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'V oněch dnech, kdy král Achašvéroš seděl na ⌈svém královském trůnu,⌉ který byl na hradě Šúšanu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 've třetím roce svého kralování uspořádal hostinu pro všechna svá knížata a své otroky. Vojsko Peršanů a Médů, šlechta a knížata provincií se před ním shromáždili,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'když ukazoval ⌈slavné bohatství⌉ svého království a drahocennost nádhery své velikosti, po mnoho dní -- sto osmdesát dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'A když se tyto dny naplnily, uspořádal král pro všechen lid nacházející se na hradě Šúšanu, od ⌈největšího až po nejmenšího,⌉ sedmidenní hostinu na nádvoří zahrady královského paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, '⌈Sněhobílá lněná tkanina,⌉ bavlna a modrá látka, spojené provazy z mořského hedvábí a purpuru visely na stříbrných kruzích a sloupech z bílého mramoru. Zlatá a stříbrná lůžka stála na dlažbě z alabastru a bílého mramoru, perleti a drahokamů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, '⌈Nápoje se podávaly⌉ ve zlatých nádobách a nádoby se od ⌈ sebe navzájem ⌉ lišily. Královského vína bylo mnoho podle králova pokynu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Ale do popíjení -- podle nařízení -- nikdo nikoho nenutil, protože tak král uložil každému hodnostáři svého domu, aby každý jednal podle libosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Také královna Vašti uspořádala hostinu pro ženy královského domu, ⌈který patřil⌉ králi Achašvérošovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Sedmého dne, ⌈když byl král v dobrém rozmaru⌉ z vína, zavolal ⌈Mehúmana, Biztu, Charbónu, Bigtu a Abagtu, Zetara a Karkase,⌉ sedm eunuchů, kteří sloužili v přítomnosti krále Achašvéroše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'aby přivedli královnu Vašti před krále s královskou korunou. Chtěl ukázat národům a knížatům její krásu; byla totiž hezkého vzhledu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Avšak královna Vašti odmítla přijít podle králova slova, které jí bylo sděleno prostřednictvím eunuchů. Král se velmi rozhněval a vzplanula v něm zloba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Tu král promluvil k mudrcům znalým časů, neboť králova záležitost se řešila přede všemi znalými nařízení a práva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Nejbližší mu byli Karšena, Šetar, Admata, Taršíš, Meres, Marsena a Memúkan, sedm perských a médských knížat, ⌈hledících na královu tvář,⌉ kteří sedávali na předním místě v království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Co se má podle nařízení provést s královnou Vašti za to, že nejednala podle výroku krále Achašvéroše, který jí byl sdělen prostřednictvím eunuchů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Nato řekl Memúkan před králem a knížaty: Ne jen proti samotnému králi se provinila královna Vašti, nýbrž proti všem knížatům a proti všem národům, které žijí ve všech provinciích krále Achašvéroše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Neboť jednání královny se donese ke všem ženám, takže ve svých očích budou pohrdat svými manžely, až si řeknou: Král Achašvéroš přikázal, aby před něho přivedli královnu Vašti, ale ona nepřišla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'A ještě tohoto dne totéž řeknou perské a médské kněžny, které slyšely o královnině jednání, všem královým knížatům. Pohrdání a rozhořčení ⌈bude víc než dost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Jestliže se to králi líbí, nechť od něj vyjde královské slovo, je zapsáno do perských a médských nařízení a nepomine, že Vašti už před krále Achašvéroše nepředstoupí, a její královskou hodnost nechť dá král jiné, lepší než je ona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Královská vyhláška, kterou vydá, bude rozhlášena v celém jeho království, ⌈které je velké,⌉ a všechny ženy prokáží čest svým manželům, od největšího až po nejmenšího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Ta řeč ⌈se králi i knížatům líbila.⌉ Král učinil podle Memúkanova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Poslal dopisy do všech královských provincií, do každé provincie jejím písmem a každému národu v jeho jazyku, aby byl každý muž vládcem ve svém domě ⌈a mluvil jazykem svého národa.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Po těchto událostech, jakmile zloba krále Achašvéroše opadla, vzpomněl si na Vašti, na to, co provedla, i na to, co ⌈se spolu s ní ztratilo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Tu řekli královi mládenci, kteří mu sloužili: Ať vyhledají pro krále dívky, panny hezkého vzhledu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Nechť král ustanoví ve všech provinciích svého království dohlížitele a ti ať shromáždí všechny dívky, panny hezkého vzhledu, na hrad Šúšan do domu žen k ruce královského eunucha Hegaje, strážce žen, kde ⌈se jim poskytne náležitá péče.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Ta dívka, která ⌈se bude králi líbit,⌉ se stane královnou namísto Vašti. To slovo se králi líbilo a učinil tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Na hradě Šúšanu byl jeden Judejec jménem Mordokaj, syn Jaíra, syna Šimeího, syna Kíšova, Benjamínec,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'který byl odveden z Jeruzaléma s vyhnanci, kteří byli odvedeni s judským králem Jekonjášem, jehož odvedl babylonský král Nebúkadnesar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Byl vychovatelem Hadasy, čili Estery, dcery svého strýce, už totiž neměla otce ani matku. Byla to dívka krásného vzezření a hezkého vzhledu a při smrti jejího otce a její matky ji Mordokaj přijal za dceru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'I stalo se, když bylo vyhlášeno královo slovo a jeho nařízení a když byly shromážděny mnohé dívky na hrad Šúšan k ruce Hegaje, že byla vzata i Ester do královského domu k ruce Hegaje, strážce žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Ta dívka se mu líbila a získala u něj přízeň. Kvapně jí tedy zařídil náležitou péči, aby jí dávali její příděly a aby jí dali sedm vyhlédnutých dívek z královského domu. Přemístil ji a její dívky na lepší místo v domě žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ester neprozradila svůj národ ani své příbuzenstvo, protože Mordokaj jí přikázal, aby to nikomu nepovídala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Každý den znovu se pak Mordokaj procházel před nádvořím domu žen, aby se dozvěděl, ⌈jak se Esteře daří⌉ a co se s ní bude dít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Vždy, když dojde na tu či onu dívku řada, aby vešla ke králi Achašvérošovi, po dovršení ⌈ toho, co pro ni nastalo podle nařízení o ženách⌉ během dvanácti měsíců (protože tak se naplní dny jejich ⌈péče o tělo⌉ -- šest měsíců myrhovým olejem, šest měsíců balzámy a náležitou ženskou péčí),');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'takto ta dívka přichází ke králi: Vše, o co si řekne, jí bude dáno, aby s tím přišla z domu žen až do královského paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Večer přichází a ráno se opět navrací do domu žen k ruce královského eunucha Šaašgaze, strážce konkubín. Nevejde již ke králi, jen pokud ⌈by si ji král oblíbil⌉ a byla by zavolána jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Když tedy došla řada na Esteru, dceru Abíchajila, strýce Mordokajova, kterou Mordokaj přijal za dceru, aby přišla ke králi, nepožadovala nic než to, co určí královský eunuch Hegaj, strážce žen. A Ester se stala nositelkou milosti v očích všech, kteří ji viděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ester byla vzata ke králi Achašvérošovi do jeho královského domu v desátém měsíci, to je v měsíci tebetu, v sedmém roce jeho kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'I zamiloval si král Esteru nade všechny ženy a získala u něj milost a milosrdenství ⌈více než všechny ostatní panny.⌉ Vložil na její hlavu královskou korunu a ⌈ustanovil ji královnou⌉ místo Vašti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Král pak uspořádal velkou hostinu pro všechna svá knížata a své otroky, Esteřinu hostinu. Prokázal provinciím úlevu a ⌈daroval dar podle královské moci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, '⌈Když se shromáždily panny podruhé,⌉ Mordokaj seděl v královské bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Ester nepovídala nikomu o svém příbuzenstvu ani o svém národě, jak jí Mordokaj přikázal. Ester jednala dle Mordokajova výroku, jako když byla ⌈pod jeho výchovou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'V oněch dnech, kdy Mordokaj seděl v královské bráně, se rozhněvali ⌈Bigtan a Tereš,⌉ dva královští eunuši ze strážců prahu, a chtěli vztáhnout ruku na krále Achašvéroše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Ta záležitost se donesla k Mordokajovi a on to oznámil královně Esteře. Ester to Mordokajovým jménem řekla králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Ta záležitost se pak vyšetřovala, byla vyšetřena a ti dva byli pověšeni na kůl. Bylo to zapsáno v králově přítomnosti do knihy Letopisů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Po těchto událostech povýšil král Achašvéroš Hamana, syna Hamedatova, Agagovce, a povznesl jej. Ustanovil jeho křeslo nade všechna knížata, která byla s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Všichni královi otroci, kteří byli v královské bráně, klekali a klaněli se Hamanovi, protože tak o něm král přikázal. Mordokaj však neklekal a neklaněl se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Královi otroci, kteří byli v královské bráně, Mordokajovi říkali: Proč přestupuješ králův příkaz?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'I stalo se, když mu to říkali den co den a neuposlechl je, že to oznámili Hamanovi, aby viděli, zdali Mordokajova slova obstojí, protože jim oznámil, že je Judejec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Tu Haman uviděl, že Mordokaj nekleká a ne klaní se mu. Haman byl naplněn zlobou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, '⌈Pohrdl však ve svých očích tím, že by vztáhl ruku jen na samotného Mordokaje, protože mu pověděli o Mordokajově národu. Haman⌉ chtěl vyhladit všechny Judejce, kteří byli v celém Achašvérošově království, ⌈národ Mordokajův.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'V prvním měsíci, to je v měsíci nísanu, v dvanáctém roce vlády krále Achašvéroše nechali padnout v Hamanově přítomnosti púr, to je los, ode dne ke dni a od měsíce k měsíci, ⌈ až ke dvanáctému měsíci, to je k měsíci adaru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Nato řekl Haman králi Achašvérošovi: Je tu jeden národ, roztroušený a oddělený mezi národy ve všech provinciích tvého království. Jejich nařízení jsou odlišná od jakéhokoliv národa, královská nařízení neplní a pro krále není vhodné, aby jim dopřával odpočinutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Pokud by se králi líbilo, nechť je zapsáno, aby je vyhubili. Odvážím deset tisíc talentů stříbra do rukou těm, kteří konají službu, aby je vnesli do královských pokladů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Tu sňal král ze své ruky prsten a podal jej Agagovci Hamanovi, synu Hamedatovu, utiskovateli Judejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Král řekl Hamanovi: Je ti dáno to stříbro i ten národ, abys s ním naložil, ⌈jak je ti libo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Třináctého dne v prvním měsíci byli svoláni královští písaři a bylo sepsáno vše, co Haman přikázal královským satrapům a místodržitelům v každé provincii a knížatům každého národa, každé provincii jejím písmem a každému národu jeho jazykem; napsáno jménem krále Achašvéroše a pečetěno královým prstenem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Dopisy byly poslány prostřednictvím běžců do všech královských provincií, aby vyhladili, zabili a vyhubili všechny Judejce, ⌈mládence i starce, malé děti a ženy,⌉ v jednom dni, ⌈třináctého dne ⌉ dvanáctého měsíce, to je měsíce adaru, a kořist aby jim uloupili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Opis toho zápisu ⌈měl být vydán⌉ jako nařízení v každé provincii; byl zveřejněn všem národům, aby byly přichystány na tento den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Běžci vyšli, pobízeni královým slovem. Nařízení bylo vydáno na hradě Šúšanu. Král a Haman usedli, aby pili, avšak město Šúšan upadlo ve zmatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Mordokaj se dozvěděl o všem, co se stalo. I roztrhl Mordokaj své roucho a vzal na sebe pytlovinu a popel. Vyšel doprostřed města a dal se do hrozného a hořkého křiku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Přišel až před královskou bránu. Do královské brány se totiž nesmělo vejít v oděvu z pytloviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Ve všech provinciích, na místech, kam dorazilo královo poselství a jeho nařízení, nastal pro Judejce velký smutek, půst, pláč a kvílení. Žíněné roucho a popel byly rozprostřeny na mnohé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Když přišli Esteřiny dívky a její eunuchové, oznámili jí to a královna se velmi rozrušila. Poslala roucho, aby Mordokaje oblékli a aby z něj sňali jeho pytlovinu, ale nepřijal je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Tu Ester zavolala na Hatáka z královských eunuchů, kterého král ustanovil k její obsluze, a přikázala mu ohledně Mordokaje, aby zjistil, proč a kvůli čemu se to děje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Haták vyšel k Mordokajovi na náměstí, které je před královskou branou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'A Mordokaj mu oznámil všechno, co ho postihlo, i přesný údaj o stříbře, o kterém Haman řekl, že je odváží do královských pokladů za Judejce, aby byli vyhubeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Dal mu i opis zápisu toho nařízení o jejich vyhlazení, které bylo vydáno v Šúšanu, aby ho Esteře ukázal, oznámil jí to a přikázal jí, aby vešla ke králi prosit u něj o milost a přimlouvat se před jeho tváří za svůj národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Haták přišel a oznámil Esteře Mordokajova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Ester však promluvila k Hatákovi a přikázala mu, aby Mordokajovi vyřídil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Všichni královi otroci i lid královských provincií vědí, že o jakémkoliv muži nebo ženě, kteří přijdou ke králi do vnitřního nádvoří, aniž budou zavoláni, platí jediné nařízení -- aby je usmrtili. Jen když k nim král vztáhne zlaté žezlo, zůstanou naživu. Já jsem už třicet dnů nebyla zavolána, abych přišla ke králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Esteřina slova oznámili Mordokajovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Nato Mordokaj řekl, aby Esteře odpověděli: Nepředstavuj si, že v královském domě unikneš, jediná ze všech Judejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Vždyť jestliže budeš v této době zarytě mlčet, úleva a osvobození povstane Judejcům z jiné strany, ale ty a dům tvého otce zahynete. Kdo ví, zda jsi ne dosáhla královského stavu pro chvíli, jako je tato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Tu Ester řekla, aby Mordokajovi odpověděli:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Jdi, shromáždi všechny Judejce nacházející se v Šúšanu a postěte se ⌈za mne.⌉ Nebudete jíst ani pít tři dny, v noci ani ve dne. Také já a mé dívky se budeme takto postit. S tím půjdu ke králi, ⌈ačkoliv to ne odpovídá ⌉ nařízení, a ⌈jestliže zahynu, zahynu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mordokaj odešel a udělal všechno, co mu Ester přikázala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'I stalo se třetího dne, že se Ester oblékla do královského roucha a postavila se na vnitřním nádvoří královského domu naproti královskému domu. Král seděl na ⌈svém královském trůnu⌉ v královském domě naproti vchodu do domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'I stalo se, jakmile král uviděl královnu Esteru stojící na nádvoří, že získala v jeho očích milost. Král vztáhl k Esteře zlaté žezlo, které držel v ruce. Ester přistoupila a dotkla se hlavice žezla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Tu se jí král zeptal: ⌈Co je s tebou,⌉ královno Estero? Jaká je tvá žádost až do poloviny království? Bude ti to dáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Nato Ester odpověděla: Pokud by se králi líbilo, nechť přijde král s Hamanem dnes na hostinu, kterou jsem pro něho uspořádala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Král řekl: Pospěšte za Hamanem, ať učiní podle Esteřina slova. Král i Haman přišli na hostinu, kterou Ester uspořádala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Při pití vína se král Estery zeptal: Jaká je tvá prosba? Bude ti to dáno. Jaká je tvá žádost až do poloviny království? Bude to vykonáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Ester odpověděla a řekla: Toto je má prosba a má žádost:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Pokud bych nalezla milost v králových očích a pokud by se králi líbilo, aby dal na mou prosbu a splnil mou žádost, nechť přijde král a Haman na hostinu, kterou pro ně uspořádám. Zítra učiním podle králova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'V onen den Haman odcházel radostný a dobré mysli. Jakmile však Haman uviděl Mordokaje v královské bráně a ten nepovstal ani se strachem z něj ne třásl, byl Haman vůči Mordokajovi naplněn zlobou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Haman se však ovládnul a došel do svého domu. Vzkázal a dal si přivést své přátele a svou ženu Zereš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Pak jim Haman vypočítával své slavné bohatství a množství svých synů i všechno, čím ho král povýšil a čím ho povznesl nad knížata a královy otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Haman nadto řekl: Královna Ester neuvedla s králem na hostinu, kterou uspořádala, nikoho, jedině mě. Také na zítra jsem k ní s králem pozván.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Ale tohle všechno mi není nic platné pokaždé, když vidím Judejce Mordokaje sedícího v královské bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Tu mu řekla jeho žena Zereš i všichni jeho přátelé: Ať udělají kůl vysoký padesát loket, a ráno řekni králi, ať na něj Mordokaje pověsí, a vejdi radostný s králem na hostinu. Ta řeč ⌈se Hamanovi líbila⌉ a udělal ten kůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Oné noci se od krále vzdálil spánek. Řekl, aby přinesli knihu Letopisů pamětihodností, a byly předčítány v králově přítomnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Našlo se zapsáno, co oznámil Mordokaj ohledně Bigtany a Tereše, dvou královských eunuchů ze strážců prahu, kteří chtěli na krále Achašvéroše vztáhnout ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Král se zeptal: Jaké ocenění a co významného bylo pro Mordokaje za tohle vykonáno? Královi mládenci, kteří mu sloužili, odpověděli: Nebylo pro něj vykonáno nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Tu se král zeptal: Kdo je na nádvoří? (Na vnější nádvoří královského domu vešel Haman říci králi, aby Mordokaje pověsili na kůl, který pro něho připravil.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Královi mládenci mu odpověděli: Hle, Haman stojí na nádvoří. Král řekl: Ať vejde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Haman vešel a král se ho zeptal: Co se má udělat pro muže, kterému by král chtěl vzdát poctu? Haman si řekl ve svém srdci: Komu bude chtít král prokázat poctu víc nežli mně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Haman tedy králi odpověděl: Muži, kterému by král chtěl vzdát poctu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'ať přinesou královský oděv, do něhož se oblékal král, a koně, na němž jezdil král, ⌈a královskou korunu, která byla vložena na jeho hlavu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Ať vydají ten oděv a toho koně někomu z králových knížat, šlechticů, a ti obléknou toho muže, kterému chce král vzdát poctu. Posadí jej na koně na náměstí města a budou před ním provolávat: Takto se jedná s mužem, jemuž chce král vzdát poctu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Tu řekl král Hamanovi: Pospěš, vezmi ten oděv a koně ⌈tak, jak⌉ jsi pověděl, a učiň tak Judejci Mordokajovi, který sedí v královské bráně. Nenech padnout ⌈žádné slovo z⌉ toho, co jsi pověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Haman tedy vzal oděv a koně a oblékl Mordokaje. Nechal jej jezdit na náměstí města a provolával před ním: Takto se jedná s mužem, kterému chce král vzdát poctu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Pak se Mordokaj vrátil do královské brány a Haman si pospíšil do svého domu truchlící a se zakrytou hlavou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Tam vypočítával Haman své ženě Zereši a všem svým přátelům všechno, co ho postihlo. Jeho mudrci i jeho žena Zereš mu řekli: Jestliže je Mordokaj, před nímž jsi začal upadat, z judejského potomstva, nepřemůžeš ho, nýbrž jistě před ním padneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Ještě s ním mluvili, když dorazili královští eunuši. Spěchali, aby Hamana přivedli na hostinu, kterou uspořádala Ester.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Tak král s Hamanem přišel, aby pili s královnou Esterou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Také druhého dne při pití vína řekl král Esteře: Jaká je tvá prosba, královno Estero? Bude ti to dáno. Jaká je tvá žádost až do poloviny království? Bude to vykonáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Tehdy královna Ester odpověděla a řekla: Pokud bych nalezla milost ve tvých očích, králi, a pokud by se králi líbilo, nechť je mi na mou prosbu dán můj život a na mou žádost můj národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Neboť jsme byli prodáni, já i můj národ, aby nás ⌈vyhladili, zabili a vyhubili.⌉ Kdybychom byli prodáni za otroky a za otrokyně, mlčela bych, protože by ta tíseň nebyla vhodná k obtěžování krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Vtom promluvil král Achašvéroš a zeptal se královny Estery: Kdo to je a kde je ten, který nadmul své srdce, aby tohle provedl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Ester odpověděla: Tím protivníkem a nepřítelem je tento zlý Haman. Haman se před králem a královnou vyděsil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Tu král vystoupil ve své zlobě od pití vína do zahrady u paláce. Haman zůstal stát, aby usiloval u královny Estery o svůj život, protože viděl, že král je rozhodnut vykonat proti němu něco zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Král se vracel ze zahrady paláce do domu, ⌈ kde popíjeli víno,⌉ zrovna když Haman padl na lůžko, na němž byla Ester. Král řekl: Chceš snad ještě znásilnit královnu u mě v domě? Jakmile to slovo vyšlo z králových úst, zakryli Hamanovi tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Vtom řekl Charbóna, jeden z eunuchů, před králem: Hle, také ten kůl, který Haman připravil pro Mordokaje, jenž promluvil dobro ohledně krále, stojí v Hamanově domě, vysoký padesát loket. Král řekl: Pověste ho na něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Pověsili tedy Hamana na kůl, který připravil pro Mordokaje. Králova zloba pak opadla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Onoho dne dal král Achašvéroš královně Esteře dům Hamana, utiskovatele Judejců. Mordokaj předstoupil před krále, protože Ester oznámila, čím pro ni je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Král sňal svůj prsten, který vzal Hamanovi, a dal ho Mordokajovi. Ester ustanovila Mordokaje nad Hamanovým domem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Ester pak pokračovala, promluvila před králem a padla k jeho nohám. Rozplakala se a prosila jej o smilování, aby odvrátil zlo Agagovce Hamana a jeho plán, který zamýšlel proti Judejcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Král vztáhl k Esteře zlaté žezlo. Ester vstala a postavila se před krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Řekla: Pokud by se králi líbilo, pokud bych nalezla u něj milost a ta věc by byla před králem prospěšná a já ⌈se mu líbila,⌉ nechť je zapsáno, aby se vrátily ty dopisy s plánem Agagovce Hamana, syna Hamedatova, které napsal, aby vyhubili Judejce, kteří jsou ve všech královských provinciích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Vždyť jak budu moci snést zlo, které postihne můj národ, a pohlédnout na ně? Jak budu moci snést zánik svého příbuzenstva a pohlédnout na něj?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Nato král Achašvéroš odpověděl královně Esteře a Judejci Mordokajovi: Hle, Hamanův dům jsem dal Esteře a jeho pověsili na kůl za to, že vztáhl svou ruku na Judejce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Vy teď královým jménem napište Judejcům, co ⌈se vám líbí,⌉ a zapečeťte královým prstenem. Zápis, který je napsán královým jménem a pečetěn královým prstenem, totiž není možné vzít zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'V onen čas byli tedy svoláni královští písaři ve třetím měsíci, to je v měsíci sívánu, dvacátého třetího dne, a bylo sepsáno všechno, co přikázal Mordokaj Judejcům a satrapům a místodržitelům a knížatům provincií, které jsou od Indie až po Kúš, sto dvaceti sedmi provincií; každé provincii jejím písmem a každému národu jeho jazykem i Judejcům jejich písmem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Napsal to jménem krále Achašvéroše a zapečetil královým prstenem. Poslal dopisy prostřednictvím běžců jezdících na koních, plnokrevných ořích, chovancích hřebčinců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'že král dovolil Judejcům, kteří jsou v jakémkoliv městě, aby se shromáždili, povstali k obraně svého života, aby vyhladili, zabili a vyhubili každé vojsko národa či provincie, dotírající na ně, i malé děti a ženy, a kořist aby jim uloupili,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'v jeden den ve všech provinciích krále Achašvéroše, třináctého dne dvanáctého měsíce, to je měsíce adaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Opis toho zápisu, aby bylo vydáno nařízení ve všech provinciích, je zveřejněn všem národům, aby byli Judejci přichystáni pro tento den, aby se pomstili svým nepřátelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Běžci jezdící na plnokrevných ořích kvapně vyšli, pobízeni královým slovem; to nařízení bylo vydáno na hradě Šúšanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mordokaj vyšel od krále v královském oděvu z modré a sněhobílé lněné tkaniny, s velkou zlatou korunou a pláštěm z mořského hedvábí a purpuru. Město Šúšan jásalo a radovalo se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Judejcům vzešlo světlo a radost, jásot a ocenění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Ve všech provinciích a ve všech městech, na místech, kam dorazilo královo poselství a jeho nařízení, nastala pro Judejce radost a jásot, hodování a příjemný den. Mnohé z národů země ⌈se připojovaly k Judejcům,⌉ protože na ně padl strach z Judejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Ve dvanáctém měsíci, to je v měsíci adaru, třináctého dne, kdy mělo nastat uskutečnění králova poselství a jeho nařízení, v den, který nepřátelé Judejců vyhlíželi, aby se jich zmocnili, však nastal zvrat tím, že se Judejci zmocnili těch, kdo je nenáviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Judejci se shromáždili ve svých městech ve všech provinciích krále Achašvéroše, aby vztáhli ruku na ty, kdo usilovali způsobit jim trápení. Nikdo před nimi neobstál, protože strach z nich padl na všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'A všechna knížata provincií, satrapové, místodržitelé a ti, kteří konali službu pro krále, podporovali Judejce, protože na ně padl strach z Mordokaje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Mordokaj byl totiž v královském domě vysoko postavený a po všech provinciích o něm šla pověst, neboť ten muž Mordokaj postupoval a vzmáhal se výše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Judejci tedy ranili všechny své nepřátele ranou meče, vraždění a zániku. S těmi, kdo je nenáviděli, naložili, jak se jim zlíbilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'I na hradě Šúšanu Judejci zabíjeli a vyhubili pět set mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'I Paršandatu, Dalfóna a Aspatu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Póratu, Adalju a Arídatu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmaštu a Arísaje, Arídaje a Vajzatu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'deset synů Hamana, syna Hamedatova, utiskovatele Judejců, zabili, ale nevztáhli ruku na kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Onoho dne se donesl počet pobitých na hradě Šúšanu před krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Tu řekl král královně Esteře: Na hradě Šúšanu Judejci zabíjeli a vyhubili pět set mužů i deset Hamanových synů. Jak si počínali v ostatních královských provinciích? Jaká je tvá prosba? Bude ti to dáno. Jaká je tvá další žádost? Bude to vykonáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Ester odpověděla: Pokud by se králi líbilo, ať je také zítra dovoleno Judejcům, kteří jsou v Šúšanu, aby jednali podle dnešního nařízení. A deset synů Hamanových ať pověsí na kůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Král řekl, aby to bylo vykonáno, a v Šúšanu bylo vydáno nařízení. Deset Hamanových synů pověsili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Judejci, kteří byli v Šúšanu, se pak shromáždili také čtrnáctého dne měsíce adaru a zabili v Šúšanu tři sta mužů, ale nevztáhli svou ruku na kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'I ostatní Judejci, kteří byli v královských provinciích, se shromáždili, povstali k obraně svého života a měli klid od svých nepřátel. Zabili mezi těmi, kdo je nenáviděli, ⌈sedmdesát pět tisíc⌉ lidí, ale nevztáhli svou ruku na kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Stalo se to třináctého dne měsíce adaru. Čtrnáctého dne měli klid a učinili ho dnem hodování a radosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Judejci, kteří byli v Šúšanu, se shromáždili třináctého a čtrnáctého dne téhož měsíce. Patnáctého měli klid a učinili ho dnem hodování a radosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Proto venkovští Judejci, bydlící v neopevněných městech, činí čtrnáctý den měsíce adaru dnem radosti a hostiny a slavnostním dnem, kdy ⌈jeden druhému⌉ posílají dárky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Mordokaj pak tyto události sepsal. Poslal dopisy veškerým Judejcům, kteří byli ve všech provinciích krále Achašvéroše, blízkým i vzdáleným,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'aby jim ustanovil zachovávání čtrnáctého dne měsíce adaru i dne patnáctého v každém roce');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'jako dnů, v nichž si Judejci odpočinuli od svých nepřátel, a jako měsíce, který se jim obrátil ze žalu v radost a ze smutku v slavnostní den; aby je zachovávali jako dny hostiny a radosti a aby posílali ⌈jeden druhému⌉ dárky a dary chudým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'A Judejci přijali to, co začali dělat, to, co jim Mordokaj napsal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Vždyť Agagovec Haman, syn Hamedatův, utiskovatel všech Judejců, vymýšlel proti Judejcům, jak by je vyhubil. Nechal padnout púr, to je los, aby je vyděsil a aby je vyhubil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Když ale Ester vešla před krále, ten dopisem přikázal, ať se na Hamanovu hlavu obrátí zlý plán, který zamýšlel proti Judejcům. Jej i jeho syny pověsili na kůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Proto nazvali tyto dny púrím podle názvu toho púru. Podle všech slov tohoto dopisu a kvůli tomu, co přitom viděli a co je postihlo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Judejci ustanovili a přijali pro sebe a pro své potomstvo i pro všechny, kdo se k nim připojí, že nepomine, aby zachovávali tyto dva dny podle zápisu o nich a podle času pro ně určeného v každém roce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Tyto dny budou připomínány a zachovávány v každé generaci, čeledi, provincii a městě. Tyto dny púrím uprostřed Judejců nepominou a památka na ně u jejich potomstva nezanikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Pak napsala královna Ester, dcera Abíchajilova, i Judejec Mordokaj se vší naléhavostí, aby to potvrdili, tento druhý dopis o púrím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'A poslal dopisy ke všem Judejcům do sto dvaceti sedmi provincií Achašvérošova království, slova pokoje a pravdy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'aby dodržovali tyto dny púrím v jejich určených časech, jak to pro ně ustanovil Judejec Mordokaj a královna Ester, jak to ustanovili i pro sebe samé a pro své potomstvo, úmluvy o postech a svém úpěnlivém křiku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Esteřin výrok ustanovil poselství těchto púrím a byl zapsán do knihy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Pak uložil král Achašvéroš nucené práce zemi i mořským ostrovům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Každý jeho vlivný a udatný čin i přesné údaje o velikosti Mordokaje, jehož král povýšil, jsou přece zapsány do knihy Letopisů králů médských a perských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Vždyť Judejec Mordokaj byl druhý po králi Achašvérošovi, významný u Judejců a oblíbený u množství svých bratrů, usiloval o dobro pro svůj národ a přimlouval se za pokoj pro všechno své potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Byl muž v zemi Úsu, jménem Jób. Tento muž byl bezúhonný a přímý, bohabojný a ⌈odvracející se od zlého.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Narodilo se mu sedm synů a tři dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Jeho statek vydal na sedm tisíc ovcí a tři tisíce velbloudů, pět set spřežení skotu a pět set oslic a velmi mnoho čeledi; onen muž byl nejzámožnější ze všech synů východu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Jeho synové chodívali a pořádali hostinu, každý doma ve svůj den. Posílali pro své tři sestry a zvali je, aby jedly a pily s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'I stávalo se, když proběhly dny hostiny, že Jób pro ně posílal a posvěcoval je, vstával časně ráno a přinášel zápalné oběti podle počtu jich všech; neboť Jób říkal: Moji synové možná zhřešili a ve svém srdci zlořečili Bohu. Takto činil Jób po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Tu nastal den, kdy přišli Boží synové, aby se postavili před Hospodina; mezi nimi přišel také Satan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Hospodin tehdy Satanovi řekl: Odkud přicházíš? Satan Hospodinu odpověděl: Z obchůzky na zemi, z procházení po ní sem a tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Hospodin se pak Satana zeptal: Jestlipak sis všiml mého otroka Jóba? Neboť není na zemi jemu podobného, muže bezúhonného a přímého, bohabojného a odvracejícího se od zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Satan nato Hospodinu odpověděl: Bojí se snad Jób Boha bezdůvodně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Cožpak ty jsi neohradil jej, jeho dům a všechno, co má, ze všech stran? Nepožehnal jsi dílo jeho rukou a nerozhojnil se jeho statek na zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Avšak vztáhni nyní svou ruku a zasáhni vše, co má; určitě ti bude do tváře zlořečit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Hospodin řekl Satanovi: Hle, vše, co má, je ve tvé ruce; pouze na něho ruku nevztahuj. A Satan odešel z Hospodinovy přítomnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Nastal den, kdy jeho synové a dcery jedli a pili víno v domě svého prvorozeného bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Tu přišel k Jóbovi posel a řekl: Skot právě oral a oslice se pásly ⌈vedle něj.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Vtom vpadli Šebovci, pobrali je a služebníky zabili ostřím meče. Unikl jsem pouze já sám, abych ti to oznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Ještě mluvil, když přišel jiný a řekl: Boží oheň padl z nebes, zapálil ovce i služebníky a strávil je. Unikl jsem pouze já sám, abych ti to oznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Ještě mluvil, když přišel jiný a řekl: Chaldejci postavili tři oddíly, vtrhli na velbloudy, pobrali je a služebníky zabili ostřím meče. Unikl jsem pouze já sám, abych ti to oznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Zatímco mluvil, přišel jiný a řekl: Tvoji synové a dcery jedli a pili víno v domě svého prvorozeného bratra');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'a hle, silný vítr se přihnal přes pustinu a opřel se do čtyř rohů domu; ten se zřítil na ty mladé a zemřeli. Unikl jsem pouze já sám, abych ti to oznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Nato Jób vstal, roztrhl své roucho a ostříhal si hlavu; pak padl na zem a klaněl se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Řekl: Nahý jsem vyšel z nitra své matky a nahý se tam navrátím; Hospodin dal a Hospodin vzal. Budiž požehnáno Hospodinovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'V tom všem Jób nezhřešil a nepřiřkl Bohu ⌈ nic bláhového.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Tu nastal den, kdy přišli Boží synové, aby se postavili před Hospodina; mezi nimi přišel také Satan, aby se postavil před Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Hospodin tehdy Satanovi řekl: Odkud přicházíš? Satan Hospodinu odpověděl: Z obchůzky na zemi, z procházení po ní sem a tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Hospodin se pak Satana zeptal: Zdali sis všiml mého otroka Jóba? Neboť není jemu podobného na zemi, muže bezúhonného a přímého, bohabojného a odvracejícího se od zlého. Stále se drží své bezúhonnosti, i když jsi mne podnítil proti němu, abych jej bezdůvodně pohltil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Satan však Hospodinu odpověděl. Řekl: Kůži za kůži, ale vše, co člověk má, dá za svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Avšak vztáhni nyní svou ruku a zasáhni až k jeho kosti a k jeho masu; určitě ti bude do tváře zlořečit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Tu Hospodin Satanovi řekl: Hle, ⌈ je ve tvé ruce;⌉ avšak zachovej jeho duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Satan pak odešel z Hospodinovy přítomnosti a ranil Jóba zlými vředy od paty až k hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'A on si vzal střep, aby se jím drápal, a když seděl v popelu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'jeho žena mu řekla: Ty se stále držíš ⌈své bezúhonnosti?⌉ Zlořeč Bohu a zemři!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Odpověděl jí však: Mluvíš, jako by promlouvala jedna z bláznivých žen. Což budeme přijímat od Boha dobré, a zlé přijímat nebudeme? V tom všem Jób nezhřešil svými rty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Když tři Jóbovi přátelé uslyšeli o všem tom zlu, které na něho dolehlo, přišli, každý ze svého domova: Elífaz Témanský, Bildad Šúchský a Sófar Naamatský. Dohodli se spolu, že přijdou, aby ⌈mu projevili účast⌉ a aby jej potěšili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Když zpovzdálí pozvedli oči a ne mohli jej poznat, ⌈pozvedli hlas a rozplakali se.⌉ Roztrhli každý své roucho a rozhazovali prach nad své hlavy k nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Pak s ním seděli na zemi ⌈sedm dnů⌉ a sedm nocí a nepromluvili na něj ani slovo, protože viděli, že jeho bolest je tuze veliká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Potom otevřel Jób svá ústa a proklínal svůj den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Jób promluvil a řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Ať zanikne den, v němž jsem byl zrozen, a noc, která řekla: Byl počat mládenec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Onen den ať se stane temnotou, ať po něm Bůh nahoře nepátrá, ať se nad ním nezaskví svítání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Ať se ho ujmou temnota a nejhlubší tma, ať se na něm usídlí bouřkový mrak, ať ho poděsí ponurost dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Onu noc ať vezme setmění, ať se netěší mezi dny roku, do počtu měsíců ať nepřijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Hle, ona noc ať se stane neplodnou, ať jí nepronikne radostný křik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Ať ji zatratí ti, kteří proklínají den, připravení vzbudit livjátána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Ať se zatmějí hvězdy jejího soumraku, ať napjatě čeká na světlo, a žádné není, ať neuzří paprsky rozbřesku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'neboť ⌈nezavřela dveře nitra⌉ mé matky a ne skryla trápení před mýma očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Proč jsem nezemřel vycházeje z lůna matky, ne vyšel z nitra a ne vydechl naposled?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Proč ⌈mě vzali na kolena⌉ a k čemu jsou prsy, že je mám sát?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Vždyť bych nyní ležel a byl bych v klidu; spal bych a tehdy by se mi to odpočívalo');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 's králi a rádci země, kteří si znovu budují trosky;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'nebo s knížaty, kteří mají zlato a své domy naplňují stříbrem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'nebo jako ⌈ukrytý potracený plod -- nebyl bych;⌉ jako děti, které neviděly světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tam ničemové zanechali nepokoje, tam odpočinou ⌈únavou vysílení;⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'tam ⌈vězňové zůstali spolu bezstarostní,⌉ neslyšeli hlas biřice;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'je tam ⌈malý i velký⌉ a otrok je svobodný od svých pánů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Proč je dáváno světlo udřenému a život těm, kdo mají hořkost v duši,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'těm, kteří čekají na smrt, a ona nepřichází, ač po ní slídili více než po ⌈skrytých pokladech,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'těm, kdo se budou s jásotem radovat, budou se veselit, že najdou hrob,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, '⌈muži, jehož cesta je ukryta,⌉ za nímž ji Bůh zatarasil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Vždyť mé vzdychání přichází místo mého chleba, mé nářky se rozlévají jako voda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Neboť jsem se velmi strachoval, a stalo se mi to. To, čeho jsem se lekal, na mne přichází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Neměl jsem pohodu, neměl jsem klid a neodpočinul jsem, až přišla vřava.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Tu odpověděl Elífaz Témanský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Což ne budeš mrzutý, zkusí–li s tebou někdo mluvit? Jenže kdo by dokázal zadržet řeč?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Hle, sám jsi mnohé káznil a posiloval jsi malátné ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Tvé výroky podpíraly klopýtajícího, upevňoval jsi klesající kolena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Protože však teď došlo na tebe, jsi mrzutý; udeřilo to právě na tebe a děsíš se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, '⌈Což není boha bojnost tvým spolehnutím a bezúhonnost tvých cest tvou nadějí?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Uvědom si konečně: Kdo nevinný kdy zahynul a kde byli přímí vyhlazeni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Podle toho, co jsem viděl, ti, ⌈kdo orají nepravost⌉ a rozsévají trápení, také ho sklidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Hynou ⌈Božím dýchnutím⌉ a závanem jeho hněvu pomíjejí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Řev lva, hlas krále zvířat, je umlčen, zuby mladých lvů jsou vyraženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Starý lev hyne nedostatkem potravy, mláďata lvice budou rozptýlena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, '⌈Ke mně pak se přikradlo slovo, mé ucho z něj zachytilo šepot.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Při přemítání zneklidněném z ⌈nočních vidění,⌉ když na lidi padá ⌈hluboký spánek,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'obestřel mne strach a třes a všechny mé kosti se rozechvěly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Pak přes mou tvář přechází závan, zježí mi chlupy na těle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Zastaví se, ale nerozeznám jeho vzhled; nějaký zjev je před mýma očima. Nastane ticho a uslyším hlas:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Což může být smrtelný člověk ⌈před Bohem spravedlivý? Může snad být muž čistý před svým Tvůrcem?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Jestliže nevěří svým otrokům a ⌈své anděly pokládá za omylné,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'čím spíše ti, kteří bydlí v domech z hlíny, jejichž základy tkví v prachu, budou sraženi ⌈snáze než⌉ mol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Od rána do večera budou rozdrceni; bez povšimnutí navždy zahynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, '⌈Což jim nebylo vytrženo stanové lano?⌉ Zemřou, ne však s moudrostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Jen volej. Je snad někdo, kdo ti odpoví? A ke komu ze svatých se obrátíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Vždyť hlupáka zabije nespokojenost a prostoduchého usmrtí žárlivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Sám jsem viděl hlupáka, jak se zakořeňuje, a hned jsem zatratil jeho příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Jeho synové budou daleko od záchrany; budou zdeptáni v bráně a nebude nikoho, kdo by je vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, '⌈Jeho sklizeň sní hladový, a až z trní ji bude vybírat; smyčka bude lapat jeho majetek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Vždyť nepravost nevyrazí z prachu a trápení nevzejde z půdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Člověk byl totiž zrozen pro trápení, ⌈stejně jako⌉ jiskry létají vzhůru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Já bych nejspíše pátral po Bohu a svou záležitost bych předložil Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'který činí veliké věci, jež ne lze vyzpytovat, divy, jež ne lze spočítat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'který dává déšť na povrch země a sesílá vodu na pole,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'takže postavil ponížené na vysoké místo a naříkající byli vyzdviženi do bezpečí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'který maří plány chytráků, takže jejich ruce nebudou mít úspěch,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'který přistihuje moudré v jejich chytráctví; rada potměšilců bývá ukvapená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Ve dne se potýkají s temnotou, jako v noci tápou za poledne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Ale nuzného zachránil od meče, z jejich úst a z ruky mocného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'A tak se pro chudého objevila naděje, ale bezpráví zavřelo svá ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Hle, šťastný je člověk, ⌈kterého Bůh kárá;⌉ a proto ponaučení Všemohoucího nezavrhuj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Vždyť on způsobí bolest i obváže, zdeptá, ale jeho ruce vyléčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'V šesti úzkostech tě vysvobodí, ba v sedmi tě nezasáhne zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'V hladu tě jistě vykoupil ze smrti a ve válce z moci meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Budeš ukryt před bičem jazyka a nebudeš se bát zkázy, až přijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Budeš se vysmívat zkáze a hladomoru a zemské zvěře se ⌈nebudeš muset bát.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, '⌈Máš totiž smlouvu s kameny na poli⌉ a polní zvěř je vůči tobě pokojná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'I zjistíš, že tvůj stan je v pořádku, když navštívíš svou pastvinu a nic nebudeš postrádat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Zjistíš také, že tvé símě je početné, tvých potomků jako zemské zeleně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'V zralosti vejdeš do hrobu jako navršený stoh obilí ve svůj čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Hle, toto jsme vyzpytovali, tak to je. Vyslechni si to a sám se o tom přesvědč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Kéž by byla pečlivě zvážena má nespokojenost a spolu s mým neštěstím byla vyzvednuta na miskách vah.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Vždyť je již těžší než mořský písek; kvůli tomu byla má slova neuvážená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Vždyť ve mně vězí šípy Všemohoucího, jejichž jed saje můj duch; Boží pohromy se zaměří proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Cožpak bude divoký osel hýkat nad trávou? Bude snad býk bučet nad svou pící?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Cožpak se dá jíst něco, co samo nemá chuť, bez soli? Je snad nějaká chuť ve vaječném bílku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Má duše se nechce dotýkat těch věcí; ⌈jsou pro mě nechutným pokrmem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, '⌈Kéž se tak stane,⌉ že se naplní má prosba a Bůh dá, v co skládám svou naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, '⌈Ať se Bůh odhodlá a srazí mě, povolí svou ruku a odtrhne mě,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'ať už nastane má útěcha a já mohu radostně poskakovat v bolesti, ačkoli mě Bůh nebude šetřit; neboť jsem nezatajil řeči Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Jakou mám sílu, že bych měl vytrvat, a jaký můj konec, že bych měl prodlužovat svůj život?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Je snad má síla silou kamenů? Je snad mé tělo z bronzu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, '⌈Není snad pro mne pomoc a obezřetnost byla ode mne zahnána?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, '⌈Zoufalému náleží milosrdenství jeho přítele, i když opustí bázeň před Všemohoucím.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Moji bratři ⌈jednali zrádně⌉ jako potok, pominou jako řečiště potoků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, '⌈kalných od ledu, v nichž je skryt roztátý sníh.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'V době sucha se ztratily; v jeho žáru zmizely ze svého místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, '⌈Stezky jejich pouti se vinou,⌉ přecházejí v pustotu a hynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Karavany z Témy je vyhlížely, průvody ze Šeby na ně čekaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, '⌈Styděly se, protože každý si byl jistý; přišly až k nim a hanbily se.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Teď jste se tedy stali něčím takovým jako ony; když uvidíte něco děsného, bojíte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Zdalipak jsem řekl: Dejte mi něco anebo zaplaťte za mě ze svého jmění');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'a zachraňte mě z ruky protivníka, z ruky násilníků mě vykupte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Poučte mě a já umlknu, dejte mi porozumět, v čem jsem zbloudil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, '⌈Čím jsou hrozné upřímné řeči? Co však kárá vaše kárání?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Rozhodnete se snad kárat výroky a nechat znít do větru řeči zoufalce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'To potom necháte padnout los na sirotka a zaprodáte svého bližního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, '⌈Nyní tedy buďte tak laskavi, pohleďte na mě, copak vám budu do očí lhát?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Přestaňte prosím, ať se nespáchá zvrácenost, přestaňte už, jde tu o mou spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Cožpak je na mém jazyku zvrácenost? Nerozpozná snad mé patro zhoubné choutky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Což není na smrtelného člověka na zemi vložena povinnost služby a nejsou jeho dny jako dny najatého dělníka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Jako otrok baží po stínu a jako najatý dělník čeká na svou mzdu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, '⌈tak jsem pro sebe dostal do dědictví⌉ měsíce nicoty a noci trápení mi přidělili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Kdybych ulehl, řeknu: Kdy vstanu a kdy se nachýlí večer? Tak se nasytím svým neklidem až do rozednění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mé tělo obléklo larvy a chumáče prachu, kůže mi popraskala a zhnisala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Mé dny byly rychlejší než tkalcovský člunek a pominuly v beznaději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Pamatuj, že můj život je jen vítr; mé oko neuvidí znovu blaho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Nebude mě sledovat oko toho, který mě vidí; tvé oči budou po mně pátrat, ale já už tu nebudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Pominul oblak a zmizel; tak ani ten, kdo sestupuje do podsvětí, už nevyjde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Nenavrátí se už domů, jeho domov už jej nezpozoruje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Ani já nezadržím svá ústa, promluvím ⌈v tísni svého ducha,⌉ přemýšlet budu ⌈v hořkosti své duše.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Cožpak jsem moře či drak, že nade mnou musíš ustanovit stráž?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Kdybych řekl: Potěší mě má pohovka, má postel mě unese při mém stěžování,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'ty mě vyděsíš sny, viděními mě ohromíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, '⌈Tu si má duše zvolila zardoušení, ano, smrt, raději než mé kosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Pohrdám tím, nebudu žít navěky; ⌈nech mě být,⌉ vždyť mé dny jsou marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Co je smrtelný člověk, že si ho ceníš a že si ho všímáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Navštěvuješ ho každé ráno, neustále jej budeš zkoušet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, '⌈Jak dlouho⌉ ode mne neodvrátíš pohled, ⌈nenecháš mě aspoň spolknout⌉ slinu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Pokud bych zhřešil, co tím provedu tobě, strážci člověka? Proč jsi mě pro sebe určil za terč, až jsem se stal břemenem sám sobě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'A co že neodpustíš mé přestoupení a ne odejmeš mou zvrácenost? ⌈Vždyť nyní ulehnu do prachu;⌉ budeš mě usilovně hledat, ale já už tu nebudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Tu odpověděl Bildad Šúchský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Jak dlouho budeš povídat tyto věci ⌈a řeči tvých úst budou jako prudký vítr?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Cožpak Bůh pokřiví právo? Pokřiví snad Všemohoucí spravedlnost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Jestliže tví synové proti němu zhřešili, vydal je do moci jejich přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Pokud ty budeš usilovně hledat Boha a Všemohoucího budeš prosit o smilování,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'pokud jsi čistý a přímý, nyní se tedy dá kvůli tobě pohnout a obnoví příbytek tvé spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Tvůj počátek se bude zdát nepatrný, zatímco tvá budoucnost půjde rychle vzhůru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Jen se přece zeptej u dřívější generace a ověř to podle bádání jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Neboť my jsme tu od včera a nedozvíme se to, naše dny jsou totiž jako stín na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Cožpak to nejsou oni, kdo tě poučí, promluví k tobě a vynesou výroky ze svého srdce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Což vyroste papyrus mimo bažinu? Vzroste sítí bez vody?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Ten ve svém rozpuku ještě ne může být utržen, ale uschne dříve než jakákoliv tráva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Tak dopadnou všichni, kdo zapomínají na Boha; zanikne i naděje bezbožného,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'jemuž se stane důvěra zklamáním, naděje pavučinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Opře se o svůj dům, ale nezůstane stát; chytí se ho, ale neobstojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Na slunci je svěží a jeho ratolest vyrazí nad jeho zahradou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Na hromadě kamení se budou proplétat jeho kořeny, pronikne do kamenného domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Jestliže jej vykoření z jeho místa, ono jej zapře: Nikdy jsem tě nevidělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Inu, taková je radost jeho cesty; a z prachu vyraší zase další.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Hle, Bůh nezavrhne bezúhonného ani nebude pevně držet za ruku zločince.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Nakonec naplní smíchem tvá ústa a tvé rty radostným křikem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'ti, kdo tě nenávidí, oblečou hanbu a stan ničemů, ten pomine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '⌈Opravdu vím, že to tak⌉ je, ale ⌈jak může být smrtelný člověk⌉ spravedlivý před Bohem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Jestliže s ním bude chtít vést spor, neodpoví mu na jedinou věc z tisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Má moudré srdce a ohromnou sílu. Kdo se proti němu kdy zatvrdil a uspěl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'On přenáší hory, aniž by poznaly, kdo je ve svém hněvu vyvrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'On pohybuje zemí z jejího místa, až se rozechvějí její sloupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'On domlouvá slunku, a to nezazáří, ⌈vůkol hvězd umístí⌉ pečeť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'On sám roztahuje nebesa a kráčí po návrších moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Tvoří Medvěda, Orion a Plejády i jižní souhvězdí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, '⌈Činí veliké věci, jež ani ne lze vyzpytovat, divy, jež ani ne lze spočítat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Jestliže projde nade mnou, nic neuvidím, a přejde– li, ani jej nerozpoznám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Jestliže něco uchvátí, kdo ho přinutí to vrátit? Kdo mu řekne: Co to děláš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Bůh neodvrátí svůj hněv. Před ním se sklonili i pomocníci obludy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Jak bych mu tím spíše mohl odpovídat já? Jak mám volit slova při rozhovoru s ním?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Vždyť i kdybych byl v právu, ⌈ne byl bych schopen odpovědět;⌉ svého soudce bych jen prosil o smilování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Pokud bych volal a odpověděl by mi, nevěřil bych, že vyslyší můj hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Neboť mě drtí bouří a bezdůvodně rozmnožuje mé modřiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, '⌈Nedovolí, aby se mi vrátil dech,⌉ nýbrž sytí mě hořkostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Pokud jde o sílu, ano, je udatný, a pokud jde o soud, kdo jiný mě předvolá?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'I když budu v právu, má ústa mě usvědčí z viny; jsem bezúhonný, ale prohlásila mě za zvráceného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Jsem bezúhonný. Nebudu se starat o svou duši, zavrhnu svůj život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Je to jedno, proto říkám: On ⌈skoncuje s bezúhonným stejně jako s ničemou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Jestliže bič náhle usmrtí, posmívá se zoufalství nevinného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Země je vydána do ruky ničemy, on zakrývá tvář jejích soudců. Pokud ne on, kdo je to tedy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'A mé dny byly rychlejší než běžec; utekly, neviděly blaho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Pominuly spolu s rákosovými loděmi, jako se orel střemhlav vrhá na kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Řeknu–li si: Zapomenu na své stěžování, opustím svou utrápenou tvář a pookřeji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'lekám se všech svých bolestí, vím, že mě nenecháš bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Já platím za ničemníka, nač se mám unavovat marností?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Kdybych se omyl vodou ze sněhu a dlaně si očistil louhem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'jednou mě ponoříš do jámy a bude mnou opovrhovat i můj plášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Vždyť on není člověk jako já, abych mu odpověděl a ⌈vešli jsme spolu v soud.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Není mezi námi rozhodčí, který položí na nás oba svou ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Ať ode mě odejme svou hůl, ⌈ať mě hrůza z něj neděsí,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'ať mohu promluvit, aniž se ho budu bát; ⌈tak tomu totiž u mě není.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Má duše si zhnusila můj život, ⌈dám průchod svému stěžování⌉ nad sebou. Budu mluvit v hořkosti své duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Řeknu Bohu: Neprohlašuj mě vinným. Oznam mi, proč se mnou vedeš při.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Cožpak je pro tebe dobré, že utlačuješ, že zavrhuješ výtěžek svých dlaní? Dovolil jsi, aby se zaskvěl ⌈plán ničemů?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Máš tělesné oči, díváš se snad, jako se dívá smrtelný člověk?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Cožpak jsou tvé dny jako dny smrtelného člověka, jsou snad tvé roky jako dny muže,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'že hledáš mou zvrácenost a pátráš po mém hříchu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Podle svého poznání víš, že nejednám ničemně, a není, kdo by vysvobodil ze tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tvé ruce mě utvořily a uspořádaly mě ⌈spolu se vším okolo. A teď bys mě pohltil?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Rozpomeň se přece, že jsi mě udělal jako hlínu a ⌈do prachu mě zase chceš vrátit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Cožpak mě nesléváš jako mléko a nezahušťuješ jako sýr?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Oblékáš mi kůži a maso, proplétáš mě kostmi a šlachami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, '⌈Daroval jsi mi⌉ život a prokázal milosrdenství a tvá starost zachovala mého ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Avšak tyto věci jsi uchovával ve svém srdci; vím, že takhle je to s tebou:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Kdybych zhřešil, ty mě budeš střežit a pro mou zvrácenost mě nenecháš bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Kdybych jednal ničemně, běda mi; i kdybych byl spravedlivý, ne smím zvednout hlavu. Jsem nasycen hanbou, pohleď na mé soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Až se však povýší, budeš mě lovit jako lev a znovu budeš na mně ukazovat svou obdivuhodnou moc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Znovu proti mně postavíš své svědky, abys vystupňoval svou nespokojenost se mnou. Střídání a množství toho všeho přichází proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Proč jsi mě tedy vyvedl z matčina lůna? Naposled bych vydechl a oko by mě nespatřilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Byl bych, jako kdybych nebyl. Byl bych odnesen z břicha do hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Cožpak není maličko mých dnů? Přestaň a ⌈upusť ode mě,⌉ ať maličko pookřeji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'dříve než odejdu -- a už se nenavrátím -- do země temnoty a nejhlubší tmy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'země temné jako zatmění nejhlubší tmy a bez řádů, kde se rozbřesklo tak, jako by to bylo zatmění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Tu odpověděl Sófar Naamatský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Cožpak tohle množství slov ne má být zodpovězeno? Zdalipak bude žvanil v právu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Umlčí tvé prázdné řeči muže? Posmíval ses a nikdo tě nezahanbí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Řekl jsi pak: Má nauka je ryzí, jsem čistý ve tvých očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Avšak kéž by se Bůh rozhodl promluvit a otevřel by proti tobě své rty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Kéž ti oznámí tajnosti moudrosti, protože ⌈obezřetnost má dvě stránky,⌉ ⌈a věz,⌉ že Bůh ⌈kvůli tobě zapomíná část tvé zvrácenosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Cožpak vystihneš pochopení Boha, vystihneš snad Všemohoucího v jeho dokonalosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, '⌈Vyšší než nebesa⌉ -- co s tím uděláš? Hlubší než podsvětí -- co o tom zjistíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Její míra je delší než země a širší než moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, '⌈Pokud chce něco změnit, uzavřít, shromáždit, kdo jej od toho odvrátí? ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Vždyť on rozezná podvodníky, zahlédne nepravost, aniž by to musel pozorně zkoumat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'I tupec nabude rozumu a z hřebce divokého osla se zrodí člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Pokud ty připravíš své srdce a vztáhneš k němu své dlaně --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'je –li ve tvé ruce nepravost, vzdal ji od sebe, a nenech ve svých stanech zabydlet zvrácenost --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'tehdy totiž pozvedneš svou tvář bez potupy, budeš jako odlitý z kovu a nebudeš se bát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Ty totiž zapomeneš na trápení. Budeš na něj vzpomínat jako na vodu, která odtekla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'A nastane věk jasnější než poledne; byť by bylo všechno ponuré, bude to jako ráno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Budeš doufat, protože je tu naděje, rozhlédneš se a ulehneš v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Budeš ležet a nikdo tě ne bude děsit a mnozí budou hledat tvou přízeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, '⌈Zeslábnou oči⌉ ničemů, ⌈jejich útočiště zaniklo⌉ a jejich nadějí je vydechnutí duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Opravdu vidím, že vy jste ten pravý lid a s vámi vymře moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'I já mám rozum jako vy, ⌈nejsem zpozdilejší než vy.⌉ S kým nepřicházejí poznatky podobné těmto?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Budu předmětem posměchu pro svého bližního, tím, kdo volal k Bohu, a odpověděl mu. ⌈Ryzí a spravedlivý⌉ je na posměch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, '⌈Neštěstí je hodno opovržení podle mínění bezstarostného člověka; je připraveno pro ty, kdo mají nejistý krok.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Stany ničitelů mají klid a bezpečí mají ti, kdo popouzejí Boha, ten, kdo přinesl boha ve své ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Avšak jen se zeptej zvěře, ať tě poučí, a nebeského ptactva, ať ti to oznámí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Nebo promlouvej s rozmyslem k zemi a vyučí tě; mořské ryby ti budou vyprávět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kdo z nich všech neví, že toto učinila ruka Hospodina?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'V jeho ruce je duše všeho živého a duch veškerého lidského těla?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Ucho přece zkoumá výroky a patro ochutnává jídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Mezi kmety je moudrost a ⌈dlouhý život⌉ dává rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'S ním je však moudrost a síla, jeho je rada a rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Jestliže něco zboří, nebude to vybudováno, zavře za člověkem a nebude mu otevřeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Jestliže zadrží vody, vyschnou, vypustí je a vyvracejí zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'S ním je moc a obezřetnost, jemu patří svedený i svůdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Rádce vodí naboso a ze soudců dělá potřeštěnce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, '⌈Rozvázal pouta⌉ králů a na jejich bedra uvázal pás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Kněze vodí naboso a podvrací ty, kdo pevně stojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Spolehlivým odnímá řeč a starcům bere rozvahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Na šlechtice vylévá pohrdání, uvolnil ⌈pás mocných.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Odhaluje hlubiny z temnoty, vyvedl na světlo nejhlubší tmu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Vyvyšuje národy a hubí je, rozprostírá národy a zavádí je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Odnímá rozum vůdcům ⌈lidu země,⌉ nechal je bloudit v bezcestné pustotě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Tápou temnotou bez světla, nechal je bloudit jako opilce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Inu, mé oko vše vidělo, mé ucho slyšelo a porozumělo tomu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Ve srovnání s vaším poznáním jsem také já obeznámen; ⌈nejsem zpozdilejší než vy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Já však promluvím se Všemohoucím a budu chtít ⌈od Boha rozsoudit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Vy šíříte klam, ano, všichni jste lékaři k ničemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, '⌈Kéž se stane,⌉ že nadobro zmlknete, to ať je vaší moudrostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Slyšte přece mou stížnost, věnujte pozornost námitkám mých rtů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Cožpak budete kvůli Bohu prohlašovat zvrácenost, budete kvůli němu prohlašovat záludnost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, '⌈Budete mu snad nadržovat,⌉ pokud za Boha povedete při?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Bude to snad dobré, až vás prověří, jestliže ho chcete podvádět, jako se podvádí člověk?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Přísně vás pokárá, pokud budete tajně nadržovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Což vás neohromí jeho vznešenost a nepadne na vás strach z něj?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vaše vzpomínky jsou pořekadla z popela, vaše obranné valy jsou jako valy z hlíny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Mlčte a nechte mě být, ať mohu promluvit já, ať ⌈na mě přijde⌉ cokoliv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Proč mám ⌈nést své maso ve svých zubech⌉ a svůj život brát do svých rukou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Jestli mě skolí, ⌈budu v něho⌉ skládat naději; pouze nechám rozsoudit v jeho přítomnosti své cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, '⌈I to je mi ke spáse,⌉ neboť bezbožný před jeho tvář nepřijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Poslouchejte bedlivě mé slovo a můj výrok ať pronikne do vašich uší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Hle, nyní jsem se připravil na soud; vím, že já budu v právu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kdo to se mnou chce vést při? ⌈Vždyť bych teď umlkl a vydechl naposled.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Jen dvě věci se mnou nedělej; tehdy se před tebou nebudu muset skrývat:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Svou ruku ode mě vzdal a ⌈hrůza z tebe ať mě neděsí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Pak volej a já odpovím, anebo budu mluvit já a ty mi odpověz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Kolik mám zvráceností a hříchů? Dej mi poznat mé přestoupení a můj hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Proč chceš skrývat svou tvář a považovat mě za svého nepřítele?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Cožpak chceš strašit odváté listí a pronásledovat vyschlou plevu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Vždyť ⌈si o mně zapisuješ⌉ trpké věci a dáváš mi zakusit důsledky zvráceností mého mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Vkládáš mé nohy do klády a střežíš všechny mé stezky. ⌈Do mých stop si vyryješ⌉ značky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'A ⌈on zchřadne jako hniloba;⌉ jako roucho ⌈rozežrané moly.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Člověk narozený z ženy je ⌈ukrácen na životě⌉ a nasycen nepokojem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Jako květ vzchází a uvadá, prchá jako stín a trvání nemá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Ano, na takového otvíráš své oči a chceš mě přivést na soud se sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Kdo učiní z nečistého čisté? Nikdo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Jestliže jsou určeny jeho dny, počet jeho měsíců je u tebe; jeho hranice jsi ustanovil a nepřekročí je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Odhlédni od něj, ať si odpočine, dokud si neoblíbí svůj den jako najatý dělník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Vždyť pro strom je naděje: Jestliže bude vyťat, zase obrazí, jeho ratolest nepřestane růst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'I kdyby jeho kořen v zemi zestárl a jeho pařez odumřel v hlíně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, '⌈jen ucítí vodu,⌉ vypučí a vydá ratolesti jako mladý štěp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Avšak muž zemře a bezvládně leží; člověk vydechl naposled a kde je mu konec?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Vody z jezera zmizely, řeka se vsákne a vyschne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Tak i muž ulehl a nevstane až do zániku nebes. Neprocitnou a neprobudí se ze svého spánku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Kéž se stane, že mě schováš v podsvětí, skryješ mě, než se odvrátí tvůj hněv; určíš pro mě lhůtu a pak se na mě rozpomeneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, '⌈Zemře–li muž, ⌈ožije snad opět?⌉ Všechny dny své povinné služby budu očekávat, dokud nepřijde mé vystřídání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Zavoláš a já ti odpovím, až budeš dychtit po díle svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Nyní tedy spočítáš mé kroky; ⌈nedbej na můj hřích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Mé přestoupení je zapečetěno do váčku, mou zvrácenost jsi zastřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Avšak padající hora zvětrá a skála se pohne ze svého místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Voda omlela kameny, její proudy odplaví prach země. Tak i naději člověka jsi zahubil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Navždy ho přemáháš, až odchází; měníš jeho tvář a posíláš jej pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Jeho synové budou vážení, ale nedozví se to; budou bezvýznamní, ale nebude jim to známo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Jen nad sebou cítí bolest jeho tělo a jeho duše nad ním truchlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Tu odpověděl Elífaz Témanský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Cožpak bude mudrc odpovídat ⌈závanem vědomosti⌉ a naplní si břicho východním větrem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Ospravedlňovat se slovem, které nepřinese užitek, a výroky, kterými člověk nic nezíská?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Ty chceš dokonce mařit Boží bázeň a omezovat rozjímání před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Vždyť tvá zvrácenost poučuje tvá ústa, volíš si jazyk chytráků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Vlastní ústa tě usvědčují z viny, nikoli já; tvé rty svědčí proti tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Cožpak ses narodil jako první člověk, byl jsi zrozen dříve než kopce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Nasloucháš snad Božímu důvěrnému sdělení, chceš omezovat moudrost jen na sebe?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Co víš, aniž bychom to věděli my? Čemu rozumíš, aniž by se to shledalo i při nás?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Mezi námi je také prošedivělý i kmet, ctihodnější věkem než tvůj otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Cožpak je ti málo Boží útěcha a slovo, kterým s tebou laskavě promlouvá?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, '⌈Kam tě vede⌉ tvé srdce a ⌈proč se blýskají⌉ tvé oči,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'že obracíš svůj hněv proti Bohu a necháváš ze svých úst vyjít takové výroky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Co je smrtelný člověk, že by mohl být neposkvrněný a že by mohl být v právu, kdo se narodil z ženy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Inu, on nevěří svým svatým, ani nebesa ⌈nejsou v jeho očích čistá.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Tím spíše, když je to člověk ohavný a zvrhlý, muž, který pije zvrácenost jako vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Chci ti něco sdělit, naslouchej mi, ať mohu vyprávět o tom, co jsem viděl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'co povídají moudří; nezatajili, co vědí od svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Jim jediným byla dána země a žádný cizinec ⌈mezi ně nepřišel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Po všechny dny se ničema sám svíjí úzkostí; po vyměřená léta, jež byla uspořena pro násilníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Děsivý zvuk zní v jeho uších; v době pokoje na něho přijde ničitel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Neuvěří, že se navrátí z temnoty, je vyhlédnutý pro meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, '⌈Vyplašeně bloudí za chlebem -- kde může být;⌉ ví, že den temnoty ⌈je mu pohotově po ruce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Poděsí ho tíseň a sklíčenost, přemůže jej jako král přichystaný k útoku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'neboť vztáhl svou ruku proti Bohu, vypíná se proti Všemohoucímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Běží proti němu s drzou šíjí, ⌈s tlustými hřbety⌉ svých štítů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Pokryl si totiž tváře svým tukem a nahromadil sádlo na slabinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'A osídlil zničená města, měli domy, kde lidé ne mají bydlet, ⌈které byly určeny, aby se staly hromadami kamení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Nezbohatne a jeho majetek neobstojí ani neskloní k zemi svůj poklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Neujde temnotě, ⌈jeho ratolest vysuší plamen, zajde dechem jeho úst.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, '⌈Ať nevěří v klam; svádí se, neboť klam bude jeho odměnou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, '⌈Naplní se mimo jeho čas,⌉ jeho mladý výhonek se nezazelená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Jako réva setřese svůj trpký hrozen a jako oliva odvrhne svůj květ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Vždyť shromáždění bezbožných je neplodné, oheň strávil stany milovníků úplatku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Počali trápení a porodili nepravost, jejich lůno připravuje podvod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Slov, jako jsou tato, jsem už slyšel mnoho. Jste všichni ⌈mizerní utěšitelé.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, '⌈Jestlipak budou mít konec ta nadutá slova? Nebo co tě popouzí, že takhle odpovídáš?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'I já bych mohl mluvit jako vy, ⌈kdybyste byli na mém místě,⌉ ohánět se proti vám výroky a potřásat nad vámi hlavou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Posiloval bych vás svými ústy a soustrast mých rtů ⌈by byla šetrná.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Jestliže promluvím, má bolest tím nebude zmírněna; zanechám– li toho, ⌈v čem se mi ulehčí?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Už mě zcela unavil. Zpustošil jsi celou mou pospolitost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Dopadl jsi mě, stalo se to na svědectví; povstala proti mně má lež a vypovídá proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Jeho hněv propukl a ⌈zanevřel na mě,⌉ skřípal na mě zuby; můj protivník na mě zaostřuje své oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Otevřeli na mě ⌈svá ústa,⌉ ⌈potupně mě bili do tváře,⌉ společně se proti mně hrnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Bůh mě vydá v plen padouchovi, vydá mě na pospas do rukou ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Byl jsem spokojený, ale zacloumal se mnou, ⌈uchopil mě za šíji a roztříštil mě.⌉ Postavil si mě za terč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Obklíčí mě jeho lukostřelci, probodne mé ledviny a nebude mít soucit. Mou žluč vylije na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, '⌈Bude mě drásat, rána za ranou;⌉ vyběhne proti mně jako hrdina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Na kůži ⌈jsem si sešil pytlovinu,⌉ svůj roh jsem sklonil do prachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Tvář mi opuchla od pláče, na mých víčkách je nejhlubší tma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Při tom na mých rukou není násilí a má modlitba je čistá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Země, nepřikrývej mou krev, ať není místo odpočinku pro můj úpěnlivý křik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Již nyní, hle, na nebesích je můj svědek a na výšinách můj přímluvce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, '⌈Mí přátelé jsou mi prostředníky; mé oko prolévá slzy před Bohem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Nechť může někdo vést za muže spor s Bohem, lidský syn za svého bližního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Protože přejdou vyměřená léta, a půjdu stezkou, z níž se nevrátím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Můj duch byl zlomen, mé dny dohasly, hroby jsou mi údělem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, '⌈Copak kolem mě ne zaznívají úsměšky? Můj zrak musí spočívat⌉ na jejich vzdoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Slož záruku, ⌈zaruč se za mě. ⌈Kdo jiný by se za mě zavázal rukou dáním?⌉⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Protože jsi jejich mysl skryl před rozumností, proto je nevyvýšíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Kvůli podílu někdo udá přátele, načež oči jeho synů zeslábnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Vystavil mě lidem za pořekadlo, jsem ⌈tím, komu se plivá⌉ do tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Můj zrak zeslábl zármutkem, všechny mé údy jsou jako stín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Přímí se nad tím zhrozí, nevinný bude pobouřen nad bezbožným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Spravedlivý se přidrží své cesty, a kdo má čisté ruce, nabude síly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Avšak vy všichni, vraťte se, opět přijďte, nenajdu mezi vámi moudrého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Mé dny pominuly, mé úmysly jsou zpřetrhány, přání mého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Noc budou vydávat za den, světlo v přítomnosti je prý bližší nežli temnota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'I kdybych ⌈doufal, podsvětí je mým domovem,⌉ své lože jsem si ustlal v temnotě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'jámě jsem vyhlásil: Jsi můj otec, larvě: Má matko, má sestro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Kde je tedy má naděje? Ano, mou naději, kdo ji zpozoruje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Závory podsvětí klesnou, až se spolu budeme děsit v prachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Tu odpověděl Bildad Šúchský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Za jak dlouho uděláte konec výrokům? Pochopte to a potom si promluvíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, '⌈Proč jsme považováni za dobytek? Stali jsme se nečistými⌉ ve vašich očích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, '⌈ Ty, který ve svém hněvu sápeš⌉ vlastní duši, cožpak kvůli tobě má být země opuštěna? Pohne se snad skála ze svého místa?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Ano, světlo ničemů zhasne a plamínek jeho ohně nezazáří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Světlo v jeho stanu ztemnělo, jeho lampa nad ním zhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Jeho rázné kroky budou stísněné, vlastní plán jej přivede k pádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Neboť se svýma nohama zapletl do sítě, bude se procházet po mříži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Past ho uchopí za patu, zmocní se jej smyčka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Provaz na něho je skryt v zemi, past na něho na pěšině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Ze všech stran ho poděsily hrozby, ⌈hnaly se v jeho šlépějích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Ať je jeho síla vyčerpaná a pohroma připravená pro jeho pád.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, '⌈Pohltí údy jeho těla,⌉ jeho údy pohltí prvorozený smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, '⌈Bude odtržen od svého stanu, své naděje;⌉ to ho přinutí vykročit za králem hrůz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'V jeho stanu se usídlí, ⌈ co mu nepatří;⌉ po jeho příbytku bude roztroušena síra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Zdola uschnou jeho kořeny a shora zvadnou jeho ratolesti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Jeho památka vymizela ze země, na ulici nemá jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, '⌈Vypudí ho ze světla do tmy,⌉ ze světa ho zapudí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Mezi svým lidem nemá ⌈nástupce ani následníka,⌉ není nikoho, kdo by přežil na místech jeho dočasného pobytu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Nad jeho dnem byli zděšeni západní sousedé a východní ⌈byli zachváceni hrůzou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Jistě, tak je tomu s příbytky bídáka, toto je místo člověka, který nezná Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Jak dlouho chcete skličovat mou duši a deptat mě výroky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Už podesáté mě takhle vystavujete hanbě. Nestydíte chovat se ke mně drze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'A kdybych se snad opravdu mýlil, můj omyl ⌈zůstane na mně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Jestliže se opravdu nade mě budete povyšovat a posuzovat mě podle mé potupy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'vězte tedy, že mi Bůh ukřivdil a obklopil mě svou loveckou sítí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Hle, ⌈úpěnlivě volám: Násilí, ale ne dočkám se odpovědi;⌉ křičím o pomoc, ale není právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Zazdil mou cestu, takže neprojdu; uvede temnotu na mé stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Svlékl ze mě mou slávu a z hlavy mi sundal korunu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Zbořil mě ze všech stran, až jsem zašel; mou naději vyvrátil jako strom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Rozpálil proti mně svůj hněv a považoval mě za jednoho ze svých protivníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Jeho loupežné hordy společně přitáhly, navršily proti mně svou cestu a utábořily se kolem mého stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, '⌈Vzdálil ode mne mé bratry, zcela se mi odcizili moji známí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Mí příbuzní mě zanechali, zapomněli na mě moji přátelé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Příchozí v mém domě i mé služebnice mě považují za cizího, stal jsem se cizincem v jejich očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Zavolal jsem na svého otroka, ale neodpovídá; musím ho prosit o smilování vlastními ústy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Můj dech se mé ženě zhnusil, ⌈začal jsem páchnout⌉ ⌈synům svého lůna.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Zavrhli mě i malí hoši; když vstanu, mluví proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Opovrhli mnou všichni mí důvěrníci a ti, které jsem miloval, se obrátili proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Kost mi přilnula ke kůži a k masu, ⌈vyvázl jsem jen s kůží kolem zubů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Slitujte se nade mnou, slitujte se nade mnou, vy, moji přátelé, protože mě zasáhla Boží ruka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Proč mě pronásledujete jako Bůh a ne můžete se nasytit mého masa?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, '⌈Kéž se tedy stane,⌉ že by mé výroky byly zapsány, kéž by byly vyryty do knihy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'vytesány natrvalo do skály železným rydlem a olovem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Ale já vím, že můj vykupitel žije a na konec ⌈se postaví nad⌉ prachem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'A poté, co tihle sedřeli mou kůži, bez svého těla uvidím Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Toho já uvidím při sobě; mé oči jej budou vidět a ne cizí. Ledviny v mém klíně po tom prahnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Vždyť řeknete: Jak ho nachytáme? Ve mně byla totiž shledána příčina problému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Mějte strach z meče, vždyť meč je trestem za zlobu. Tak poznáte, že nastane právní pře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Tu odpověděl Sófar Naamatský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Proto mě mé ⌈zneklidněné přemítání nutí odpovědět;⌉ pro nepokoj, který je ve mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Vyslechnu ponaučení ke své potupě a ⌈odpověď mi dá duch podle mého porozumění.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Což to ne víš odedávna, od doby kdy byl na zemi postaven člověk,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'že radostný křik ničemů přijde zkrátka a radost bezbožného je jen na chvíli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'I kdyby jeho povznesenost vystoupila do nebes a jeho hlava by dosáhla do oblak,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'zmizí navždy jako jeho výkal; ti, kdo ho vídali, řeknou: Kde je?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Odlétne jako sen a nenajdou ho, jako noční vidění bude zaplašen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Zahlédlo jej oko, ale více ne zahlédne, jeho domov už ho nezpozoruje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Jeho synové budou hledat přízeň chudých, jeho ruce musejí vrátit jeho majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Svěžesti byly plné jeho kosti, ta ale ulehne do prachu s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Ačkoliv zlo v jeho ústech sládne, pod svým jazykem ho přechovává,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'je k němu shovívavý a neopouští ho, na svém patře jej zadržuje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'jeho pokrm se mu změnil ve vnitřnostech, v jeho nitru se stal hadím jedem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Pohltil majetek a zase jej vyzvrátil, Bůh mu ho vyžene z břicha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Bude sát hadí jed, jazyk zmije ho zabije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Nepodívá se na proudy, řeky, potoky medu a smetany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Výtěžek vrací zpět, nespotřebuje jej a nad výnosem svého obchodu nebude jásat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Vždyť utiskoval, opouštěl chudé; uchvátil dům, ale nebude ho budovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Protože ve své chuti nepoznal uspokojení, nezachrání se ⌈s tím, co je mu nejmilejší.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nic neuniklo jeho žravosti; kvůli tomu jeho blaho nebude trvalé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Když vzroste jeho hojnost, bude mu úzko; zasáhne jej ⌈ruka každého udřeného. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Ať se snaží naplnit břicho, pošle na něj svůj planoucí hněv; ať na něj dští svými střelami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Uteče– li před železnou zbraní, prostřelí ho bronzový luk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Vytáhl střelu, ale šíp mu vyšel ze hřbetu, blesk vyjde z jeho žluče, hrůzy na něm spočinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, '⌈Jen temnota je připravena pro ty, kdo jsou mu drazí,⌉ stráví jej oheň, který nebyl rozdmýchán; ať spase, co zůstalo v jeho stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Nebesa odhalí jeho zvrácenost, povstane proti němu i země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Úroda z jeho domu ať se vystěhuje, v den jeho hněvu se rozplyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Toto je Bohem určený podíl ničemného člověka a dědictví Bohem mu přiřknuté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Bedlivě naslouchejte mému výroku, ⌈to ať je útěcha od vás.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Sneste mě, když chci mluvit já, a poté, co já promluvím, se můžete vysmívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Cožpak já si naříkám nad člověkem? Pokud ano, jak by ne měl být můj duch netrpělivý?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Pohleďte na mě a užasněte; položte si ruku na ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Když na to pomyslím, vyděsím se a mé tělo zachvátí hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Proč zůstávají ničemové naživu? ⌈Dožili se stáří⌉ a majetek také rozmnožili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'S nimi jejich potomstvo, je u nich zajištěné, své potomky mají před očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Jejich domy mají pokoj, jsou beze strachu, Boží hůl nad nimi není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Jeho býk obskočil, ⌈nikoli nadarmo,⌉ jeho kráva se otelí a nepotratí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Své malé hochy vypouštějí jako stádo a jejich děti skotačí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Pozvedají hlas podle tamburíny a lyry a radují se za zvuku flétny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Své dny dovrší v blahobytu, v okamžiku se pohrouží do podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Tu řekli Bohu: Odstup od nás, nemáme zalíbení v poznání tvých cest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Co je Všemohoucí, že bychom mu měli sloužit, a co získáme, když se u něj budeme přimlouvat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Inu, jejich blaho není v jejich moci; kéž by se ode mne vzdálila rada ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Jak často zhasne lampa ničemů a jejich pohroma na ně přijde, on ve svém hněvu rozdělí díly zkázy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Budou jako sláma ve větru, vichřice ho uchvátila jako plevy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Uchová Bůh jeho trest pro jeho syny? Ať odplatí jemu, aby to poznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Ať jeho oči spatří jeho zkázu, ať se napije z kalicha zloby Všemohoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Vždyť co po něm zbylo z jeho zájmu o vlastní dům, když byl odměřen počet jeho měsíců?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Cožpak bude někdo učit Boha poznání, když on bude vznešené soudit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Jeden zemře ve své naprosté bezúhonnosti, je úplně bezstarostný a spokojený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Plné mléka jsou jeho dížky a do jeho kostí nasákl morek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Jiný pak zemře s hořkostí v duši, aniž se nasytil dobrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Ulehnou společně do prachu a pokryjí je larvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Inu, poznal jsem vaše úmysly a plány, jak se mnou chcete násilně jednat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Vždyť říkáte: Kde je dům šlechtice a kde je stan s příbytky ničemů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, '⌈Cožpak jste se nezeptali těch, kdo prochází kolem? Snad nebudete popírat jejich znamení:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Ano, zlý bude ušetřen v den pohromy, budou odneseni v den zuřivosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kdo mu vytkne jeho jednání do očí a kdo mu odplatí za to, co on spáchal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'On pak bude odnesen k hrobům a nad jeho rovem se bude bdít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Hroudy v údolí jsou mu sladkými, potáhne se za ním každý člověk, bezpočet jich bylo před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Jak mě potom chcete potěšit marností? A vaše odpovědi -- zůstala jen věrolomnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Tu odpověděl Elífaz Témanský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Cožpak bude muž Bohu prospěšný, bude mu snad rozumný člověk prospěšný?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Cožpak má Všemohoucí zalíbení v tom, že budeš v právu, anebo nekalý zisk z toho, že dovedeš své cesty k dokonalosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Cožpak tě kárá kvůli tvé bázni, ⌈vejde proto s tebou v soud?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Což není tvá špatnost velká a ⌈tvé zvrácenosti bez konce?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Vždyť jsi bezdůvodně brával zástavu od svých bratrů a svlékal jsi šaty ze spoře oděných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Nedával jsi žíznivému napít vody, chléb jsi odpíral hladovému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Země náleží muži silné paže, bude v ní pobývat muž vznešené tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'S prázdnou jsi poslal pryč vdovy, paže sirotků bývala sražena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Proto jsou okolo tebe pasti a roztřese tě náhlý strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Anebo nevidíš temnotu a spoustu vody, která tě přikryje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Což není Bůh vyšší než nebesa? Pohleď na nejvyšší hvězdy, jak jsou vyvýšeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'A přece říkáš: Co ví Bůh? Což může soudit to, co je za hustou temnotou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Za úkryt má mračna, nevidí; prochází se po nebeském obzoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Chceš se snad držet dávné stezky, po níž šlapali muži propadlí nepravosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'kteří byli dopadeni, ačkoliv ne nadešel čas? Jejich základ bude zaplaven proudem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Ti Bohu říkávali: Odstup od nás, a: Co nám může Všemohoucí provést?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Přitom blahobytem jejich domy naplnil on; kéž by se ode mne vzdálila ⌈rada ničemů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Spravedliví to uvidí a budou se radovat, nevinný se jim bude posmívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Naši odpůrci jistě byli vyhlazeni a oheň strávil to, co po nich zbylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Jen se s ním důvěrně stýkej a užívej pokoje, dobro ti skrze to bude vzcházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Přijmi přece poučení z jeho úst a v srdci si ulož jeho řeči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Pokud se vrátíš k Všemohoucímu, budeš zbudován, vzdálíš zvrácenost od svého stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Valoun zlata polož do prachu a zlato z Ofíru mezi potoční kameny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, '⌈Pak bude Všemohoucí tvými valouny zlata a hromadami stříbra.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Tehdy budeš totiž mít z Všemohoucího rozkoš a svou tvář budeš pozvedat k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Budeš– li k němu úpět, vyslyší tě a ty splníš své sliby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'A když ⌈se pro něco rozhodneš,⌉ ať ti to vyjde; na tvých cestách zazáří světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Když budou druzí klesat, řekneš: Taková pýcha. Sklíčeného on zachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Vychvátí ⌈ toho, kdo není nevinný,⌉ bude vychvácen čistotou ⌈tvých dlaní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'I dnes je mé stěžování vzpurné; jeho ruka na mě těžce dolehla kvůli mému vzdychání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Kéž se stane, že bych věděl, jak ho naleznu; jak se dostanu k jeho sídlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Předložil bych před něj svůj spor, stížnostmi bych naplnil svá ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Dozvěděl bych se výroky, kterými mně odpoví, a porozuměl bych tomu, co mi řekne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Cožpak se mnou povede při s plnou silou? Nikoli, on si mě jistě všimne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tam by se s ním přímý domlouval a já bych navždy unikl svému soudci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Půjdu–li na východ, on tam není, pak liže nazpět, nepochopím ho;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'když koná něco nalevo, nezahlédnu ho, jestliže se skryje napravo, rovněž ho neuvidím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Vždyť on zná mou cestu, kdyby mě vyzkoušel, vyjdu jako zlato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Má noha se přidržela jeho kroku, zachoval jsem jeho cestu a ne chtěl se odvrátit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Příkaz jeho rtů? Od toho neustoupím! Řeči jeho úst jsem uchovával více než vlastní ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'On pak zůstává stejný a kdo ho od toho odvrátí? Po čem jeho duše zatoužila, to vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Vždyť vykoná, co mi určil; při něm se najde mnoho tomu podobného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Proto jsem z něj vyděšený, pozoruji se a třesu se před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Tak Bůh naplnil mé srdce zoufalstvím, Všemohoucí mě vyděsil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Avšak nebyl jsem umlčen temnotou, setmění se přede mnou ukrylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Proč nejsou časy skryty před Všemohoucím, ale ti, kdo jej znají, nespatřili jeho dny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Lidé posouvají meze, uloupí stádo a pasou ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Sirotkům odhánějí osla, vdově berou býka do zástavy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Chudáky z cesty odstrkují, nuzní v zemi se společně musejí skrývat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Hle, divocí osli v pustině jdou za svým dílem, usilovně hledají potravu, step ⌈jim dává pokrm⌉ pro mladé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Sklízejí jeho píci na poli, paběrkují na vinici ničemy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Bez oděvu přenocují nazí, v chladu bez přikrývky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Jsou promočení horským přívalem, skálu obejmuli z nedostatku útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Sirotka od prsu uchvacují, berou zástavu od nuzného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Chodí nazí, bez oděvu, hladoví snášejí snopy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Lisují olej mezi jejich terasami, šlapou v lisech, a přece mají žízeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, '⌈Muži z města⌉ sténají, o pomoc bude křičet duše pobitých, avšak Bůh si bláznovství nevšímá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Oni patří mezi ty, kdo se bouří proti světlu, nepoznali jeho cesty ani nepobývají na jeho stezkách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Vrah vstává za svítání, skolí chudého a nuzného a v noci se objeví jako zloděj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Oko cizoložníka vyhlíží soumrak a on si říká: Nikdo si mě nevšimne; a roušku si položí na tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Za tmy se prokopal do domů, ⌈ kde se ve dne uzavřeli;⌉ světlo neznají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Pro ně je totiž ráno zároveň nejhlubší tmou, protože pozná hrůzy nejhlubší tmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Je lehký na vodní hladině, jejich díl v zemi je zlořečen, nevydá se směrem k vinicím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Vyprahlá země i žár pohlcují vodu ze sněhu, podsvětí ty, kdo zhřešili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Zapomene na něho matčino lůno, larvám se stal sladkým, už nebude připomínán. Zvrácenost bude jako strom zlomena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Vyjídá neplodnou, která nerodila, a vdově neprokazuje dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Zachovává vznešené svou silou. Povstane a nikdo si ⌈není jist životem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Dopřeje mu uchýlit se do bezpečí a člověk se spolehne. Jeho oči bdí nad jejich cestami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Nakrátko jsou pozdviženi a již nejsou, budou sehnuti, uzavřou se jako všichni ostatní. Zvadnou jako vršek klasu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'A pokud tomu tak přece není, kdo mě usvědčí ze lži a obrátí můj výrok v nic?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Tu odpověděl Bildad Šúchský. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Vladařství a strach jdou s tím, kdo působí pokoj na svých výšinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Cožpak ⌈je možné spočítat jeho oddíly?⌉ Nad kým nevzchází jeho světlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, '⌈Jak může být smrtelný člověk spravedlivý⌉ před Bohem a jak může ⌈být neposkvrněný člověk narozený z ženy?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Hle ď, ani měsíc nesvítí jasně a hvězdy také nejsou v jeho očích čisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Tím méně smrtelný člověk, který je larva a lidský syn, červ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Nato Jób odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Ó jak jsi pomohl bezmocnému, zachránil jsi vysílenou paži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Jak jsi poradil nemoudrému a obezřetnost jsi dal poznat mnohým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Komu jsi sdělil své výroky a čí duch z tebe vyšel?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, '⌈Chvějí se před ním nebožtíci⌉ v hlubinách vod i ti, kdo v nich přebývají?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Podsvětí je před ním nahé, není přikrývky pro říši mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Roztáhl sever nad pustotou, zavěšuje zemi nad nicotou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Uzavírá vody do svých mračen, oblak se pod nimi neroztrhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, '⌈Zahaluje vzhled trůnu,⌉ rozprostírá nad ním svůj oblak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Vykroužil obzor na vodní hladině až po mez světla a temnoty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Nebeské sloupy se chvějí a jsou ohromeny jeho napomenutím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Svou silou zklidnil moře, svou rozumností zdeptal obludu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Svým duchem dal nebesům velkolepost, jeho ruka probodla mrštného hada.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Hle, toto jsou okraje jeho cest, zaslechneme o něm jen něco jako šepot. Kdo porozumí hromobití jeho sil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'A Jób pokračoval v pronášení své promluvy. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Jakože živ je Bůh, on, který mi odňal právo, Všemohoucí, který způsobil mé duši hořkost:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Dokud je všechen můj dech ve mně a duch Boží v mém chřípí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'mé rty nepromluví zvrácenost a můj jazyk nebude přemítat o záludnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Ať je to ode mne vzdáleno, abych vás prohlásil za spravedlivé. Dokud nevydechnu naposled, neodložím svou bezúhonnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Držím se své spravedlnosti a neopustím ji. Mé srdce mě nebude hanobit za mé dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Ať je na tom můj nepřítel jako ničema a můj protivník jako bídák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Vždyť jakou naději má bezbožný, když bude sražen, vezme–li mu Bůh život?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Cožpak Bůh vyslyší jeho volání, až na něho přijde soužení?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Zdalipak ⌈bude mít rozkoš z Všemohoucího?⌉ Bude volat Boha v každém čase?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Poučím vás o Boží moci, nezatajím, jak je tomu s Všemohoucím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Hle, vy, vy všichni jste to viděli. Proč tedy vršíte marnost na marnost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Toto je podíl ničemného člověka u Boha, dědictví, které od Všemohoucího přijmou násilníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'I když bude mít mnoho synů, pak jen pro meč, jeho potomci se chlebem nenasytí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Ti, kteří ho přežijí, budou pohřbeni smrtí a jejich vdovy je nebudou oplakávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Jestliže nahromadí stříbra jako prachu a oděvu navrší jako hlíny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'navrší, avšak obleče se spravedlivý a stříbro rozdělí nevinný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Svůj dům postavil jako mol, ⌈jako stan, který si udělal hlídač.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Bohatý ulehne a už se nesebere, otevře své oči a už to není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Hrůza ho dostihne jako voda, v noci ho uchvátí vichřice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Odnese jej východní vítr a zmizí, odvane jej z jeho místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Ať se na něho vrhne a nemá soucit, před jeho rukou bude spěšně utíkat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Budou nad nimi tleskat rukama, bude se nad ním pošklebovat z jeho místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Stříbro má přece své naleziště a zlato místo, kde ho přečistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Z prachu se získává železo a kámen vyplavuje měď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Temnotě určuje konec a zkoumá temný kámen v nejhlubší tmě po nejzazší mez.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, '⌈Prorazil šachtu údolím⌉ daleko od místa, kde pobývá člověk. Zapomenutí lidskou nohou houpou se na laně, daleko od člověka se klátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Země, z níž vzchází úroda, je zespodu převrácena jakoby ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Její kameny jsou nalezištěm safírů, obsahuje zlatý prach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Pěšinu k němu, tu dravec nezná, ani oko luňáka černého ji nezahlédlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Pyšná mláďata po ní nešlapala, lev po ní nevlekl kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Člověk svou rukou sáhl na křemen, hory od základů převrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Vyrubal kanály ve skalách, jeho oko vidělo kdejakou drahocennost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, '⌈Zamezil přetékání řek,⌉ tajnosti vynáší na světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Avšak moudrost, kde může být nalezena? A kde je to naleziště rozumnosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Její hodnotu smrtelný člověk nezná, ne může být nalezena v zemi živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Hlubina říká: Ve mně není, moře říká: Není u mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Lístkové zlato za ni ne může být dáno ani stříbro ne může být odváženo na její úhradu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Ne může být zaplacena zlatem z Ofíru, vzácným karneolem a safírem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Nevyrovná se jí zlato či sklo, nedá se směnit za předměty z ryzího zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Perly a křišťál nebudou připomínány, cena moudrosti je nad drahokamy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Kúšský topas se jí nevyrovná, ne může být zaplacena čistým zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Odkud tedy moudrost přijde? A kde je to naleziště rozumnosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Byla totiž skryta před očima všeho živého, ukryta před nebeským ptactvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Říše mrtvých a smrt říkají: Zprávu o ní jsme slyšely na vlastní uši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Bůh rozumí její cestě, on zná její naleziště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Vždyť on hledí až do končin země, vidí všechno pod nebesy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Takže dodal větru váhu a vodu odměřil mírou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'když dešti stanovil hranici a hromobití cestu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'tehdy ji uviděl a vyprávěl o ní, upevnil ji a také ji prověřil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'A řekl člověku: Hle, bázeň před Panovníkem, toť moudrost a odvrátit se od zlého, toť rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'A Jób pokračoval v pronášení své promluvy. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Kéž je mi dopřáno žít jako za dávných měsíců, jako za dnů, kdy mě Bůh chránil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'když nad mou hlavou nechával svítit svou lampu, šel jsem temnotou za jeho světlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Tak jako jsem byl ve dnech své sklizně v ⌈důvěrném společenství s Bohem⌉ nad svým stanem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'když ještě se mnou byl Všemohoucí a moji služebníci okolo mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Když jsem ve smetaně umýval své nohy a proudy oleje na mě vyplavovala skála.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Když jsem vycházel branou k městu a své sedadlo si připravoval na náměstí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'viděli mě mládenci a vytratili se, kmeti vstali a zůstali stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Knížata ustala v řečech, na ústa si položila ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Vytratily se hlasy předáků, jazyk jim přilnul k patru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Vždyť ucho, které mi naslouchalo, nazývalo mě šťastným, oko, které mě vidělo, svědčilo pro mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Vždyť jsem zachraňoval nuzného, když křičel o pomoc, i sirotka, který neměl pomocníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Přicházelo na mne požehnání hynoucího, k jásotu jsem přiváděl srdce vdovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Oblékal jsem si spravedlnost a ona si oblékala mne, právo mi bylo jako roucho a turban.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Slepému jsem byl očima a chromému nohama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Chudým byl jsem otcem a prověřil jsem spor, který jsem neznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'I tesáky bídáka jsem vyrazil a kořist vytrhoval z jeho zubů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Řekl jsem si: Naposled vydechnu se svým hnízdem a rozmnožím dny jako písek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Můj kořen dosahuje k vodě, rosa přenocuje v mých ratolestech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Má sláva je se mnou vždy nová, obnovuje se i luk v mé ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Naslouchali mi a očekávali na mě, umlkali při mé radě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Po mém slovu již nic neopakovali, kanul na ně můj výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Jako na déšť na mě počkali, jak pro jarní déšť otevřeli svá ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, '⌈Usmíval jsem se na ně, když nevěřili,⌉ a neodvrhli světlo mé tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Volil jsem jejich cestu, sedával jsem v čele a přebýval jsem jako král s oddílem, jako ten, kdo potěší truchlící.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'A nyní se mi smějí ti, kteří jsou věkem mladší než já, jejichž otci jsem pohrdl tak, že jsem je odmítl nasadit ke svým ovčáckým psům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Nač mi také je síla jejich rukou? Zralost u nich přišla vniveč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Nedostatkem a hladomorem vyčerpaní ohlodávají suchopár uplynulé noci, zkázu a zpustošení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Trhají lebedu, listí z křoví a kořen janovce, aby je zasytily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Jsou vypuzeni ze společenství, křičí na ně jako na zloděje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Musejí přebývat v údolním srázu, dírách v podzemí a skalách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'hýkají mezi křovím, zalezlí pod plevelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Blázni, ano bezejmenní, byli vymrskáni ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'A teď jsem se stal jejich písničkou, stal jsem se námětem jejich výroku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Opovrhují mnou, vzdalují se ode mne a ⌈nemají zábrany plivat mi do tváře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Jelikož on rozvázal mé lano a pokořil mě, oni si přede mnou povolili uzdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Napravo povstávají jako mladická chátra, podrážejí mi nohy, vrší proti mně své zhoubné stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Mou pěšinu boří, přispívají k mé zkáze. Není před nimi pomocníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Přicházejí jako široká trhlina, valí se jako zkáza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Hrůza se obrátila proti mně, mou důstojnost pronásleduje jako vítr; jako mračno pominula má spása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'A teď je má duše rozlita nade mnou, dny soužení mě zachvacují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Noc ze mě vyloupala kosti. Neutichnou mé hlodající bolesti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Velkou silou se můj oděv změnil k nepoznání, mé roucho mě přepásá jako obojek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Vrhl mě do bláta, stal jsem se podobným prachu a popelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Křičím k tobě o pomoc, a neodpovídáš mi. Když ⌈jsem se dříve postavil k modlitbě, měl jsi pro mě pochopení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Změnil ses mi v krutého nepřítele, strojíš mi úklady silou své ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Zvedneš mě, posadíš mě na vítr, necháš mě zmítat se v bouři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Vždyť vím, že mě přivedeš k smrti, do domu setkání pro všechno živé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, '⌈ On jistě nevztáhne ruku do sutin, když při své zkáze někdo volá o pomoc.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Zdalipak jsem neplakal nad tím, kdo prožíval těžké dny? Ne starala se má duše o nuzného?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Vždyť jsem čekal dobro, a přišlo zlo, očekával jsem světlo, a přišlo setmění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Mé nitro bylo přivedeno do varu a nemělo pokoj, potkaly mě dny soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Chodil jsem v nářku, ne v žáru slunce, ve shromáždění jsem povstal a křičím o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Šakalům jsem se stal bratrem, pštrosům bližním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Zčernala na mně kůže, ⌈horečkou ⌈vzplanuly mé kosti.⌉⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'I má lyra je naladěna pro smuteční obřad, pro hlas plačících má flétna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Se svýma očima jsem uzavřel smlouvu, jak bych se mohl zadívat na pannu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'A jaký je podíl od Boha nahoře, dědictví od Všemohoucího shůry?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Cožpak jím pro bídáka není pohroma a pro pachatele nepravosti neštěstí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Cožpak on mé cesty neuvidí a nespočítá všechny mé kroky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Jestliže jsem jednal falešně a má noha spěchala za podvodem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'ať mě na miskách spravedlnosti odváží, ať mou bezúhonnost Bůh pozná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Pokud by se odvrátil z cesty můj krok, mé srdce by šlo za mýma očima a poskvrna by ulpěla na mých dlaních,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'ať tedy zaseji a sní to někdo jiný a ať jsou vykořeněny moje výpěstky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Jestliže se mé srdce dalo přivábit k cizí ženě a číhal jsem u vchodu svého bližního,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'ať má žena ⌈jinému mele a jiní ať se nad ní sklánějí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Vždyť je to hanebnost, zvrácenost hodná odsouzení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Neboť je to oheň, který stravuje až k zahynutí, vykoření všechnu mou úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Pohrdnu–li právem svého otroka či své otrokyně v jejich sporu se mnou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'co udělám, až Bůh povstane? Až mě navštíví, co mu odpovím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Cožpak ten, který učinil v nitru mě, neučinil i jej? Což nás ⌈tentýž ne připravil v lůně?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Jestliže jsem chudému odepřel jeho přání a nechal jsem vyhasnout oči vdovy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'jestliže jsem jídal své sousto sám, aniž by z něj jedl i sirotek --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'vždyť u mě vyrůstal jako u otce od mého mládí a vdovu jsem vedl od lůna své matky --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'jestliže jsem viděl hynoucího bez oděvu a nuzného, že nemá přikrývku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'jestliže mi jeho bedra nežehnala, že se zahřál vlnou ze stříže mých beránků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'jestliže jsem se rozehnal rukou proti sirotkovi, protože jsem viděl, že mám v bráně podporu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'ať mi odpadne rameno od zad a vylomí se mi paže z lokte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Vždyť Boží pohroma mi nahání strach, ⌈nemohl bych snést jeho vznešenost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Pokud bych svou důvěru složil ve zlato, čistému zlatu bych řekl: Má naděje!,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'jestliže bych se radoval, že mám hojný majetek a že má ruka mnoho získala,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'jestliže bych pohleděl na sluneční světlo, jak se třpytí a jak spanile putuje měsíc');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'a mé srdce by se dalo ve skrytu svést a ⌈polibek mých úst by poslala má ruka,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'také to je zvrácenost hodná odsouzení, protože bych zapřel Boha nahoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Zdalipak bych se radoval ze zkázy toho, kdo mě nenávidí, a rozjařil bych se, že ho postihlo něco zlého?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Svým ústům jsem nedovolil hřešit, žádat ⌈kletbou o jeho život.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Cožpak muži z mého stanu neříkali: Kdo by nebyl nasycen jeho masem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Příchozí nenocoval venku, otvíral jsem své dveře pro poutníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Jestliže jsem svá přestoupení přikryl ⌈jako Adam,⌉ takže jsem svou vinu uschoval ve své hrudi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'protože jsem měl strach z velkého davu a děsilo mě pohrdání lidských čeledí, umlkl jsem a nevycházel ze vchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Kéž je mi dopřán někdo, kdo by mi naslouchal. Zde je mé znamení. Ať mi odpoví Všemohoucí. Můj odpůrce sepsal záznam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Cožpak bych ho nenosil na rameni? Připoutal bych jej k sobě jako korunu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Oznámil bych mu počet svých kroků, přistupoval bych k němu jako vévoda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Jestliže má půda ⌈křičí proti mně⌉ a její brázdy pláčou spolu s ní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'jestliže jsem bez placení jedl její úrodu a ⌈přiváděl jsem duši jejích vlastníků k zoufalství,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'ať mi vzejde trní namísto pšenice a býlí namísto ječmene. Tím končí Jóbova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Nato již přestali ti tři muži Jóbovi odpovídat, protože byl ve vlastních očích spravedlivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Tu vzplanul hněv Elíhúa, syna Berakeela, Búzijce z čeledi Rámovy. Jeho hněv vzplanul proti Jóbovi, pro tože prohlásil sám sebe za spravedlivějšího, než je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Jeho hněv vzplanul i proti jeho třem přátelům, pro tože nenašli odpověď, a přesto Jóba prohlašovali vinným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elíhú však ⌈se slovy k Jóbovi⌉ vyčkával, protože byli věkem starší než on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Když Elíhú viděl, že v ústech těch tří mužů není odpověď, jeho hněv vzplanul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Tu Búzijec Elíhú, syn Berakeelův, odpověděl. Řekl: Věkem jsem mladý, zatímco vy jste kmeti. Proto jsem se ostýchal a bál jsem se sdílet s vámi své poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Říkal jsem si: Ať promluví dny, hojná léta ať oznámí moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Avšak je to duch v smrtelném člověku, dech Všemohoucího, který jim dává porozumět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Nikoli velcí zmoudří, aniž starci porozumí právu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Proto pravím: Poslouchej mě, ano, i já sdělím své poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Hle, čekal jsem na vaše slova, naslouchal jsem vašim rozumným řečem, dokud neprověříte ty výroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Pozorně jsem vás sledoval, avšak hle, Jób nemá, kdo by ho usvědčil, kdo z vás by odpověděl na jeho řeči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Jenom neříkejte: Nalezli jsme moudrost: Ať jej odvane Bůh, ne člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Jób své výroky nezaměřil proti mně a já mu nebudu odpovídat vašimi řečmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Zděsili se, už neodpovídají, došla jim slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Budu tedy předpokládat, že nepromluví, protože přestali a už neodpovídají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'I já odpovím svým dílem, ano, i já sdělím své poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Neboť jsem plný výroků, duch mě svírá v mém nitru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Hle, mé nitro je jako víno, které není otevřeno, praskne jako nové měchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Promluvím a uleví se mi; otevřu rty a odpovím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Nikomu jistě nebudu nadržovat a nebudu lichotit člověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Vždyť ani neumím lichotit. ⌈Jak snadno by mě můj Tvůrce odstranil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Přece však bedlivě slyš mé výroky, Jóbe, a naslouchej všem mým slovům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Hle, nyní jsem otevřel svá ústa a jazyk v mých ústech promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, '⌈Mé řeči pocházejí z přímosti mého srdce,⌉ mé rty vytříbeně vyjádřily poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Učinil mě duch Boží, při životě mě zachová dech Všemohoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Pokud můžeš, odpověz mi; připrav se, postav se proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Hle, jsem na tom před Bohem jako ty, i já jsem byl zformován z hlíny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Hle, ⌈neohromí tě hrůza ze mě⌉ ani na tebe nedolehne těžce mé naléhání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Zajisté jsi ke mně promluvil a já poslouchám hlas tvých výroků. Prý:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Jsem čistý, bez přestoupení, jsem bezúhonný, není při mně zvrácenost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'jenže Bůh proti mně hledá záminky, považuje mě za nepřítele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'mé nohy dává do klády, střeží všechny mé stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Inu, v této věci jsi nebyl v právu -- tak ti odpovím, neboť Bůh je větší než člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Proč proti němu vedeš při? Že neodpovídá vždy lidskými slovy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Vždyť Bůh promluví jednou i podruhé, ale člověk to nezpozoruje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Ve snu, v nočním vidění, když hluboký spánek padne na lidi, v dřímotách na posteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Tehdy to lidem ⌈dá na vědomí⌉ a zapečetí je v ⌈ tom, o čem byli poučeni,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'aby odvrátil člověka od jeho špatného díla a vzdálil pýchu od muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Chrání jeho duši před jámou, před tím, aby jeho život zašel oštěpem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Bolestí je kárán na své posteli, ⌈třesení jeho kostí⌉ je stálé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Jeho život mu znechutil chléb, jeho duše lákavou potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Jeho tělo ztrácí na vzhledu, obnaženy jsou jeho kosti, které nebylo vidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'K jámě přistoupila jeho duše, jeho život k poslům smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, '⌈Kdyby s ním byl posel, prostředník, jeden z tisíce, aby člověku oznámil, v čem spočívá jeho přímost,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, '⌈a Bůh by se nad ním smiloval a řekl by: Vykup jej, aby nesestoupil do jámy; našel jsem za něho výkupné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Jeho tělo bude svěžejší než v mládí, vrátí se tak do dnů své svěžesti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Bude úpět k Bohu, který ho laskavě přijme, uvidí za radostného křiku jeho tvář a on odplatí smrtelnému člověku za jeho spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Ať zazpívá před lidmi a řekne: Zhřešil jsem a zkazil jsem, co bylo správné, ale nebylo mi odplaceno stejně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Mou duši vykoupil, aby nepřešla do jámy, můj život uzří světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Hle, Bůh při člověku udělá všechny tyto věci dvakrát i tři krát,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'aby odvrátil jeho duši od jámy, aby byl osvícen světlem živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Věnuj mi pozornost, Jóbe, poslouchej mě. Mlč a já budu mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Pokud máš po ruce výroky, odpověz mi. Promluv, protože bych tě chtěl prohlásit za spravedlivého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Pokud nemáš, poslouchej ty mě; mlč, ať tě naučím moudrosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'A Elíhú vypovídal dále. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Slyšte, moudří, mé výroky, vzdělaní, naslouchejte mi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Ucho přece zkoumá výroky a patro ochutnává jídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Zvolme si, co je spravedlivé, zjistěme mezi sebou, co je dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Neboť Jób prohlásil: Jsem spravedlivý, a Bůh mi odňal právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Mám snad lhát ohledně svého práva? Aniž bych se dopustil přestoupení, moje rána od šípu je nevyléčitelná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Který muž pije jako Jób výsměch jako vodu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'vchází do spolku s pachateli nepravosti a chodí s ničemníky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Protože řekl: Muži nepřinese užitek, když najde zalíbení v Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Proto mě poslouchejte, rozumní muži: Ať je to od Boha vzdáleno, že by spáchal ničemnost a že by Všemohoucí spáchal špatnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Neboť odplatí člověku jeho skutek, postihne každého podle jeho stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Ano, opravdu, Bůh nejedná ničemně, Všemohoucí nepokřiví právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kdo ⌈jej ustanovil nad zemí⌉ a kdo ⌈ jej určil nad celým světem?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Kdyby zaměřil svou pozornost jen na sebe a vzal zpět k sobě svého ducha a svůj dech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'všechno tvorstvo by společně naposled vydechlo a člověk by se ⌈obrátil v prach.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Pokud ti tedy nechybí rozumnost, vyslechni toto, naslouchej hlasu mých výroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Což si opravdu myslíš, že může vládnout ten, kdo nenávidí právo? Anebo chceš prohlásit vinným ⌈spravedlivého a mocného?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Cožpak se sluší králi říkat: Ničemníku a šlechticům: Ničemo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Tomu, který nenadržuje knížatům ani nestraní urozenému před chudým, neboť oni jsou všichni dílem jeho rukou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'V okamžiku i o půlnoci umírají, lidé jsou rozechvěni a pomíjejí. Vznešený je odstraněn bez zásahu lidské ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Neboť jeho oči hledí na cesty člověka, on uvidí všechny jeho kroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Není taková temnota, ani nejhlubší tma nestačí, aby se tam pachatelé nepravosti mohli skrýt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Neboť nikomu není uloženo více, než aby šel na soud před Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Bez vyšetřování drtí mocné, namísto nich ustanovil jiné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Jistě zná jejich počiny, vyvrátí je v noci a budou potřeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Jako ničemy je bije na místě, kde to všichni vidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'protože se od něj odvrátili a žádné z jeho cest nerozuměli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'takže k němu nechali přijít volání chudého, uslyší volání nuzného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Zůstane–li on klidný, kdo jej prohlásí vinným? Když skryje tvář, kdo jej zpozoruje? Přitom bdí zároveň nad národem i nad jednotlivým člověkem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'aby se bezbožný člověk nestal králem, aby ne byl lidu léčkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Vždyť řekl snad někdo Bohu: Odnesl jsem si to, nebudu už jednat zle?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Co sám nevidím, tomu ty mě uč. Jestliže jsem provedl špatnost, nebudu v tom pokračovat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Má snad za to odplatit podle tvého? Vždyť jsi ho zavrhl, protože ty si můžeš vybrat a já ne. Jen pověz, co víš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Řeknou mi to rozumní muži i moudrý člověk, který mě poslouchá:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Jób nemluví na základě poznání, jeho slova ne přicházejí z porozumění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Kéž je Jób ⌈ jednou provždy⌉ přezkoušen za odpovědi po způsobu mužů propadlých nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Neboť ke svému hříchu přidává vzpouru, tleská mezi námi. Jen ať množí své řeči proti Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'A Elíhú odpovídal dále. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Považuješ tohle za správné? Řekl jsi: Má spravedlnost je ⌈před Bohem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Vždyť se ptáš: Jaký užitek ti to přinese? Co víc získám než svým hříchem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Já odpovím několika výroky tobě a s tebou i tvým přátelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Pohleď na nebesa a viz, pozoruj oblaky, jak tě převyšují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Hřešíš–li, co to s ním provede? Je– li tvých přestoupení mnoho, co mu to způsobí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Pokud jsi byl spravedlivý, co mu tím dáš nebo co od tebe získá?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Tvá ničemnost se týká jen člověka, jako jsi ty, tvá spravedlnost lidského syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Lidé se dávají do křiku pro množství útlaku, pro tvrdou paži mocných křičí o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'A nikdo neříká: Kde je Bůh, můj Tvůrce, který dává v noci písně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'vyučuje nás více než zemská zvířata, činí nás moudřejšími než nebeské ptactvo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Jednou budou úpěnlivě volat, ale on neodpoví, kvůli pýše zlých lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Bůh nebude poslouchat pouhý klam, Všemohoucí si toho nebude všímat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Tím spíše když říkáš, že si nebudeš všímat jej. Tvůj spor je před ním a ty na něj musíš čekat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Avšak nyní, protože jeho hněv tě ještě nenavštívil a o zpupnost se zatím příliš nestaral.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'I Jób svá ústa otvírá marně, bez rozmyslu zbytečně rozmnožuje výroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'A Elíhú pokračoval. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Měj se mnou trochu strpení, ať ti sdělím, že výroky o Bohu ještě neskončily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Své poznání vezmu zdaleka, spravedlnost přiznám svému Učiniteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Neboť mé výroky opravdu nejsou klam, mluví s tebou člověk úplného poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Hle, mocný je Bůh, ale člověkem nepohrdá, silou smýšlení je mocný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Ničemu při životě nezachová, avšak chudým dopřeje právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Neodvrátí svůj zrak od spravedlivých, s králi je navždy přivede na trůn a budou povýšeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Pokud však jsou spoutáni řetězy, polapeni do provazů soužení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'vytýká jim jejich skutky a to, že se rozmáhají jejich přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Otvírá jim ucho pro ponaučení a říká, že se mají odvrátit od nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Pokud uposlechnou a budou mu sloužit, dovrší v blahobytu své dny, v potěšení svá léta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Pokud ale neuposlechnou, zajdou oštěpem a vydechnou naposled jako člověk bez poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Lidé bezbožného srdce budou v srdci ukládat hněv, nebudou křičet o pomoc, když je spoutá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Jejich duše zemře v mládí, mezi chrámovými smilníky skončí jejich život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Zkroušeného vysvobodí skrze jeho soužení, bude jim otvírat ucho skrze útlak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Tak i tebe lákal ze chřtánu soužení do volného prostoru, v němž není stísněnost. Tučností naplnil pohodu u tvého stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Avšak ty jsi naplnil podstatu právní pře ničemy. Právní pře a soud se tě budou držet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Jenom ať tě zloba nepodnítí k tleskání. Množství výkupného ať tě neodkloní stranou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Cožpak tvé volání o pomoc způsobí, že ne zůstaneš v úzkých? Nebo ⌈vypětí všech sil?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Nebaž po noci, ⌈která by vytrhla národy z jejich místa.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Měj se na pozoru, ať se neobrátíš k nepravosti, protože bys raději zvolil ji nežli soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Hle, jak vyvýšený je Bůh ve své síle. Kdo je takový učitel jako on?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kdo mu určil cestu? A kdo řekl: Provedl jsi zvrácenost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Pamatuj, že máš vyvyšovat jeho dílo, o němž lidé zpívají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Na ně patřili všichni lidé, smrtelný člověk na něj zdaleka pohledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Hle, veliký je Bůh, nepochopíme jej, počet jeho let je nevyzpytatelný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Neboť vyzvedne kapky vody a ony kanou v podobě deště, jako jeho mlha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'oblaka je řinou, kanou na mnoho lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Ano, mohl by někdo porozumět rozprostření oblaku, hřmění z jeho stánku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Hle, rozprostřel nad sebou své světlo, přikryl základy moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Vždyť jimi soudí národy, jídla dává do sytosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Světlo blesku ukryl v dlaních, přikázal mu zasáhnout cíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Jeho hřmot o něm vypovídá, i dobytek o tom, že přichází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Ano, mé srdce se kvůli tomu otřese, že až ze svého místa vyskočí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Naslouchejte bedlivě burácení jeho hlasu, rachotu hromu, jež vychází z jeho úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Pod celými nebesy ho posílá, k okrajům země své světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Za ním zařve hlas, jeho vznešenost hlasitě zahřmí. Blesky nezadrží, až bude jeho hlas slyšet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Bůh obdivuhodně zahřmí svým hlasem, činí velké věci, které nepochopíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Neboť zavolá na sníh: Padej na zem, též i na průtrž deště, a ve své síle padá průtrž dešťů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Na ruku každého člověka umístí pečeť, aby všichni lidé poznali jeho dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Zvěř zalézá do houští a přebývá ve svých doupatech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Vichřice se přižene ze své kobky, chlad od ⌈severního větru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Božím dechem vzniká led, vodní plocha se ocitá v sevření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'I mračno obtěžká vláhou, jeho světlo rozptýlí oblak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Ty se pak podle jeho úmyslů valí v kruzích, aby na povrchu ⌈celé země⌉ vykonaly všechno, co jim přikáže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Užije toho ať už jako trestající hole, ať už ku prospěchu své země, ať už na důkaz milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Naslouchej tomu, Jóbe, zastav se a zvažuj obdivuhodné Boží skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Rozumíš snad tomu, čím je Bůh pověří, když dovolí, aby se zaskvělo světlo jeho oblaku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Rozumíš snad letům oblaku a podivuhodným skutkům toho, jehož poznání je úplné?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Ty, jenž máš horká roucha, když se v poledne země utiší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'můžeš spolu s ním rozprostřít oblaka pevná jako zrcadlo odlité z kovu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Oznam nám, co mu máme říci? Kvůli zatemněnosti si to ne dokážeme srovnat v hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Bude mu snad sděleno, že hodlám promluvit? Copak mu mohl někdo něco říci, když je zmatený?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Lidé však ještě ne mohli spatřit světlo zářící v oblacích, dokud ne přešel vítr a ne pročistil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Od severu přichází zlatá záře, hrůzu vzbuzující majestát kolem Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Všemohoucího, toho jsme ne mohli postihnout. Jeho moc je veliká a přitom právo ani plnou spravedlnost nepotlačuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Proto se ho lidé bojí, ⌈nehledí ani na žádného, kdo má moudré srdce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Tu odpověděl Hospodin Jóbovi z vichřice. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Kdo je tento člověk, který zatemňuje radu výroky bez poznání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Přepásej si nyní bedra jako muž. Vyptám se tě a pouč mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kde jsi byl, když jsem zakládal zemi? Pověz, pokud víš něco rozumného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kdo určil její rozměry, jestlipak víš? Anebo kdo nad ní roztáhl měřicí šňůru?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Do čeho byly zapuštěny její podpěry, nebo kdo založil její rohový kámen,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'když jitřní hvězdy společně jásaly a všichni Boží synové hlaholili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'A kdo zahradil moře vraty, když se vyvalilo, vyšlo z lůna?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Když jsem na něj položil oblak jako oděv a hustou temnotu jako plenku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, '⌈určil jsem mu svou hranici,⌉ umístil jsem závoru a vrata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Řekl jsem: Dosáhneš až sem a dál už ne, tvé vlny hrdě dorazí pouze sem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Dal jsi snad někdy za svůj život příkaz ránu? Obeznámil jsi jitřenku s jejím místem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'aby uchopila zemi za okraje a ničemové z ní byli setřeseni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Proměňuje se jako hlína pod pečetním prstenem a oni slouží jako oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Ničemům bude jejich světlo odepřeno, povýšená paže bude zlomena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Přišel jsi snad až k pramenům moře a procházel ses po dně hlubiny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Byly ti snad odhaleny brány smrti, uvidíš snad brány nejhlubší tmy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Prozkoumal jsi zemi až do jejích šířek? Pověz, pokud to všechno znáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Kudy vede ta cesta, na níž sídlí světlo, a temnota, kde má to své místo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'že bys je vzal na jejich území, že bys rozpoznal stezky k jejich domu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Věděl jsi, že se jednou narodíš a jak velký bude počet tvých dnů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Přišel jsi snad ke skladům sněhu? Uvidíš snad sklady krup,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'které jsem ušetřil pro čas soužení, pro den bitvy a boje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, '⌈Kudy vede ta cesta, kde ⌉ se rozděluje světlo, odkud se rozptyluje po východní zemi vítr?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kdo vymezil koryto povodni a cestu pro hromobití,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'aby seslal déšť na zemi bez lidí, na pustinu, v níž člověka není,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'aby napojil místo zkázy a zpustošení a dal vzrůst výhonku trávy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Má snad déšť otce či kdo zplodil krůpěje rosy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Z čího lůna vyšel led a kdo porodil nebeské jíní?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Voda tuhne jako kámen a povrch hlubiny se uzavírá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Dokážeš snad spoutat uskupení Plejád či rozvázat pouta Orionu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Můžeš snad v pravý čas vyvést hvězdy zvěrokruhu či vést Medvěda spolu s jeho mláďaty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Znáš snad nebeská ustanovení? Zdalipak ustanovíš na zemi Jeho dohled?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Můžeš snad pozvednout svůj hlas k oblaku, takže tě přikryje spousta vod?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Vypustíš snad blesky, takže se dají do pohybu? Budou ti hlásit: Tady jsme?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kdo vložil do ibisů moudrost či kdo dal kohoutovi rozumnost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kdo díky své moudrosti spočítá oblaka, kdo vyprázdní nebeské měchy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'když prach odlijí v slitinu a hroudy se sklíží?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Můžeš snad lovit potravu pro lvici a utišit hlad mladých lvů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'až se v doupatech skrčí, budou čekat v úkrytu houští?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kdo připraví úlovek havranovi, až jeho mláďata budou křičet k Bohu o pomoc a budou bloudit bez potravy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Znáš snad čas porodu skalních kozorožců? Střežíš laň, když se svíjí v porodních bolestech?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Počítáš měsíce, ⌈ kdy jsou březí,⌉ znáš čas jejich porodu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Skloní se, vrhnou svá mláďata, zbaví se svých bolestí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Jejich mláďata sílí, rostou v přírodě. Pak odejdou a už se k nim nevrátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kdo propustil divokého osla na svobodu, kdo rozvázal pouta stepního osla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'kterému jsem dal pustinu za obydlí a slatinu za příbytky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Městskému ruchu se vysmívá, neslyší povely poháněče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Na horách si hledá svou pastvu, pátrá po jakékoliv zeleni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Bude ti snad chtít sloužit divoký tur? Zdalipak přenocuje u tvého žlabu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Přivážeš snad divokého tura popruhem k brázdě? Zdalipak bude za tebou údolí vláčet?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Spolehneš se snad na něho, protože má velkou sílu, a přenecháš mu svou námahu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Uvěříš mu snad, že tvé zrno sveze a shromáždí na tvé humno?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Křídlo pštrosice vesele mává; je to snad čapí peruť s peřím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Vždyť svá vejce nechává na zemi, dává je zahřívat na hlíně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Zapomíná, že je může rozmáčknout noha, pošlapat polní zvěř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Se svými mláďaty zachází tvrdě, jako by jí nepatřila, beze strachu z marnosti své námahy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'protože Bůh jí odepřel moudrost a nedal jí podíl na rozumnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Když se vymrští do výše, vysmívá se koni a jeho jezdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Dáš snad koni udatnost, oblékneš snad hřívou jeho šíji?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Naučíš ho snad skákat jako kobylku? Z jeho majestátního frkání jde hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'V údolí hrabe nohama a raduje se ze své síly, vytáhne vstříc zbraním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Vysmívá se strachu, neděsí se a neustoupí před mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Toulec chřestí proti němu, kopí a srpáč se blyští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'S duněním a burácením dusá zemi, nedá se zadržet, když zazní zvuk beraního rohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Kdykoli sytě zazní beraní roh, spokojeně zařehtá, zdálky větří boj, hromování velitelů a válečný pokřik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Cožpak sokol podle tvé rozumnosti létá a rozprostírá křídla k jihu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Zdalipak se orel vznáší na tvůj příkaz, takže vysoko staví své hnízdo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Sídlí na skále, nocuje na skalním výběžku jako v pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Odtamtud slídí za potravou, jeho oči ji vidí z daleka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Jeho mláďata hltají krev a na místě, kde jsou pobití, tam je i on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'A Hospodin Jóbovi dále odpovídal. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Smí snad nějaký kritik vést spor s Všemohoucím? Nechť na to odpoví ten, kdo Boha kárá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Nato Jób Hospodinu odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Hle, jsem nepatrný, co ti mám odpovědět? Kladu si ruku na ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Promluvil jsem jednou a již odpovídat nebudu, i po druhé, ale více krát ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Tu Jóbovi odpověděl Hospodin z vichřice. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Nyní si přepásej bedra jako muž, ať se tě vyptám, a pouč mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Chceš snad zrušit i můj soud, prohlásit mě vinným, a tak se ospravedlnit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Zdalipak máš paži jako Bůh a můžeš hřímat hlasem, jakým hřímá on?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Nyní se ozdob ⌈vznešeností a vyvýšeností,⌉ oděj se majestátem a důstojností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Rozlij zuřivost svého hněvu, pohleď na každého pyšného a sniž ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Pohleď na každého pyšného a pokoř ho, ničemy sraz na jejich místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Skryj je společně do prachu, jejich ⌈tváře obvaž na skrytém místě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'I já ti budu vzdávat chválu, že ti pomůže tvá pravice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Jen si všimni behemóta, kterého jsem učinil stejně jako tebe; žere trávu jako býk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Jen pohleď, jeho síla je v jeho bedrech a jeho zdatnost v jeho břišních svalech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Vzpřímí ocas jako cedr, šlachy jeho stehen jsou propletené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Jeho kosti jsou jako bronzové roury, jeho kostra jako železný sochor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'On je prvotina Božího jednání, jeho Tvůrce ať mu přinese jeho meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Neboť hory mu poskytují pastvu, kde dovádí všechna polní zvěř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Uléhá pod lotosy v úkrytu z rákosí a bahna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Lotosy jej zahalí svým stínem, obklopují jej potoční topoly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Jestliže se řeka vzdouvá, nepodléhá panice, je si jist, ačkoliv se proti jeho tlamě valí jako Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Může se ho člověk zmocnit svým pohledem, protáhnout mu chřípí návnadami?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, 'Vytáhneš livjátána udicí, zkrotíš provazem jeho jazyk?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, 'Vložíš snad do jeho chřípí rákos, probodneš jeho čelist háčkem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, 'Zahrne tě snad úpěnlivými prosbami? Zdalipak k tobě promluví vlídnými slovy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, 'Uzavře snad s tebou smlouvu? Přijmeš jej navěky za otroka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 29, 'Budeš si s ním hrát jako s ptáčkem, uvážeš ho pro svá děvčata?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 30, 'Budou o něm vyjednávat společníci, rozdělí jej mezi obchodníky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 31, 'Zaplníš snad jeho kůži oštěpy, jeho hlavu rybářskou harpunou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 32, 'Polož na něho svou dlaň, připomeň si boj a už v tom nepokračuj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Hle, číhat na něho by bylo ošidné. Cožpak se člověk ne zhroutí již při pohledu na něj?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Nikdo není tak smělý, že by jej probudil. Kdo by se potom chtěl postavit proti mně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Kdo mě v něčem předstihl, abych mu to musel odplatit? Cokoli se objeví pod celými nebesy, patří to mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Nebudu mlčet o jeho údech, popisu jeho zdatnosti a o půvabu stavby jeho těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Kdo odhalí jeho svrchní oděv? Kdo může proniknout ⌈jeho dvojitým chrupem?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Kdo kdy mohl otevřít jeho tlamu? Kolem jeho zubů číhá hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Jeho pýchou jsou řady štítů ⌈sevřených těsnou pečetí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Tisknou se jeden ke druhému, ani vítr mezi ně nepronikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Jsou spjaty ⌈jeden s druhým,⌉ jsou sevřeny a neoddělí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Jeho supění zažehne světlo, jeho oči jsou jako víčka jitřenky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Z tlamy mu vycházejí pochodně, unikají ohnivé jiskry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Z nozder mu vychází kouř jako z roztopeného kotlíku s rákosem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Jeho dýchání rozpaluje uhlíky, z tlamy mu vychází plamen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'V jeho šíji přebývá síla, před ním předchází zoufalství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Laloky jeho těla přilnuly k sobě, nepohne se, co je na něm slito.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Jeho srdce je slité jako kámen, slité jako spodní mlýnský kámen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Z jeho vznešenosti dostávají hrdinové strach, hrůzou jsou celí bez sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Meč, který jej zasáhne, neobstojí, ani kopí, střela či šíp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Železo považuje za slámu, bronz za ztrouchnivělé dřevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Šíp z luku jej nezažene, kameny z praku se před ním změnily v plevu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Kyj považuje za plevu, vysmívá se mávání srpáčem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Zespodu má ostré hrany, valí se blátem jako smyk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Hlubinu přivádí do varu jako hrnec, moře pokládá za kelímek na mast.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Zanechá za sebou světélkující dráhu, člověk si až myslí, že hlubina má šediny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Není mu podobného na prachu země, takového, který je zbaven všeho děsu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Na každého vyvýšeného dohlédne, je králem nad všemi potomky šelmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Nato Jób Hospodinu odpověděl. Řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Vím, že dokážeš cokoliv a žádný plán pro tebe není nemožný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kdo že je tento člověk, který bez rozmyslu zakrývá radu? Jistě, povídal jsem o něčem, co nikdy nepochopím. Ve srovnání se mnou jsou to obdivuhodné věci a ne mohu je poznat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Řekl jsi: Nyní slyš, já promluvím. ⌈Zeptám se tě a ty mě pouč.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Slyšel jsem tě jen z doslechu, a nyní tě vidělo mé oko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Proto odvolávám, lituji toho v prachu a popelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'I stalo se poté, co Hospodin k Jóbovi promluvil tato slova, že řekl Elífazovi Témanskému: Proti tobě a proti oběma tvým přátelům vzplanul můj hněv, protože jste o mně nemluvili správně jako můj otrok Jób.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Nuže vezměte si sedm býčků a sedm beranů a jděte k mému otroku Jóbovi, přinesete za sebe zápalnou oběť a můj otrok Jób se za vás bude modlit. Neboť na něho jistě budu brát ohled, abych s vámi nenaložil podle vašeho bláznovství, že jste o mně nemluvili správně jako můj otrok Jób.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Tak Elífaz Témanský, Bildad Šúchský a Sófar Naamatský šli a zachovali se podle toho, jak k nim Hospodin promluvil. A Hospodin bral ohled na Jóba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Hospodin tehdy změnil Jóbův úděl, když se k němu modlil za své přátele. A ke všemu, co Jób měl, Hospodin dvojnásobně přidal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Také všichni jeho bratři a všechny jeho sestry a všichni, kdo ho předtím znali, k němu přišli, jedli s ním v jeho domě chléb, projevovali mu účast a utěšovali jej po všem tom neštěstí, které na něho Hospodin přivedl. Dali mu každý jednu kesítu a jeden zlatý kroužek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Hospodin tehdy požehnal Jóbův konec více než jeho počátek. Jób měl čtrnáct tisíc kusů bravu a šest tisíc velbloudů, tisíc spřežení skotu a tisíc oslic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Dále měl sedm synů a tři dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'První dal jméno Jemíma, druhé jméno Kesía a třetí jméno Keren–ha–púk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'V celé zemi se nenašly ženy tak krásné jako Jóbovy dcery. Jejich otec jim dal dědictví mezi jejich bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Jób potom žil ještě sto čtyřicet let a viděl své syny a syny svých synů po čtyři generace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'I zemřel Jób starý a sytý dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Blahoslavený je muž, který nežije podle rady ničemů, na cestě hříšníků se nezastaví a ⌈v zasedání posměvačů neusedne,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'ale oblíbil si Hospodinův zákon, nad jeho zákonem rozjímá ⌈ve dne i v⌉ noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Bude jako strom zasazený u ⌈přívodů vody,⌉ který ve svůj čas přináší ovoce a listí mu neopadává, a vše, co dělá, se daří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Ne tak ničemové. Ti jsou jako plevy odvívané větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Proto ničemové na soudu neobstojí, ani hříšníci v shromáždění spravedlivých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Cestu spravedlivých totiž Hospodin zná, cesta ničemů se ztrácí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Proč se bouří národy, proč lidé přemítají ⌈ o prázdných věcech?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Srocují se králové světa a mocnáři se spolu radí proti Hospodinu a proti jeho pomazanému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Zpřetrhejme jejich pouta, odvrhněme jejich provazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Ten, jenž trůní na nebesích, se směje. Panovník se jim vysmívá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Jednou k nim promluví v hněvu, ve svém rozlícení je vyděsí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Já jsem ustanovil svého krále na Sijónu, na své svaté hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, '⌈Přednesu Hospodinovo ustanovení. Řekl mi:⌉ Ty jsi můj syn, já jsem tě dnes zplodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Požádej mě a dám ti národy do dědictví. Tvým vlastnictvím budou i končiny země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Roztlučeš je železnou holí a jako hliněnou nádobu je roztříštíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Nuže, králové, ⌈jednejte rozumně!⌉ Soudcové země, ⌈dejte si poradit!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Služte Hospodinu s bázní a ⌈jásejte s chvěním!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Líbejte syna, ať se nerozhněvá. Jinak zahynete na cestě, jestliže jen málo vzplane jeho hněv. Blahoslavení jsou všichni, kdo v něm hledají útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, '⌈Žalm Davidův,⌉ když utíkal před svým synem Abšalómem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Hospodine, jak mnoho je mých protivníků! Mnozí povstávají proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Mnozí ⌈o mé duši⌉ říkají: Není pro něj záchrany v Bohu. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Ty, Hospodine, jsi štítem vůkol mě. Má Slávo, pozvedáš mi hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Můj hlas zní k Hospodinu, volám a on mi ze své svaté hory odpovídá. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, '⌈Ulehl jsem a usnul. A ⌉ probudím se, neboť Hospodin mě podepírá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Nebojím se desetitisíců lidu, které se kladou kolem mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Povstaň, Hospodine! Zachraň mě, ⌈můj Bože!⌉ ⌈Rozbiješ čelisti všem mým nepřátelům,⌉ ničemům vyrazíš zuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Spása náleží Hospodinu. Na tvém lidu je požehnání! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, '⌈Pro vedoucího chval.⌉ ⌈Na strunné nástroje.⌉ Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Když volám, ⌈odpověz mi,⌉ ⌈můj spravedlivý Bože!⌉ V tísni mi zjednej prostor! Smiluj se nade mnou a vyslyš mou modlitbu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Synové lidští, jak dlouho bude má Sláva v potupě? Milujete nicotu, ⌈vyhledáváte lež.⌉ Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Vězte, že Hospodin si oddělil věrného. Hospodin slyší, když k němu volám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Chvějte se, ale nehřešte. Přemýšlejte o tom v srdci, na svém lůžku, a utište se! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Obětujte spravedlivé oběti a důvěřujte Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Mnozí říkají: ⌈Kdo nám ukáže dobré?⌉ Pozdvihni nad námi jas své tváře, Hospodine!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Dáváš do mého srdce větší radost, než když mají mnoho obilí i vína!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'V pokoji budu uléhat i spát. Hospodine, ty sám mi připravuješ bezpečné bydlení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Pro vedoucího chval. Na flétny. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Naslouchej mým slovům, Hospodine, porozuměj mému sténání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Věnuj mi pozornost, když volám o pomoc, můj králi a můj Bože, vždyť se modlím k tobě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Hospodine, ráno uslyšíš můj hlas. Ráno ti připravím oběť a budu očekávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Vždyť ty ne jsi Bůh, který má zalíbení v ničemnosti; zlý s tebou přebývat nemůže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Namyšlení se ti nemohou postavit před oči; nenávidíš všechny činitele nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Zahubíš ty, kdo mluví lživě. Hospodin opovrhuje lidmi krvelačnými a podlými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Já však pro tvé hojné milosrdenství vstoupím do tvého domu. V ⌈bázni před tebou⌉ se budu klanět ke tvému svatému chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Veď mě, Hospodine, ve své spravedlnosti, vždyť na mě číhají! Napřim přede mnou svou cestu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Vždyť ⌈v jejich ústech není spolehlivost,⌉ jejich nitro je zkáza, jejich hrdlo je otevřený hrob, jazyk mají úlisný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Vyjev jejich vinu, Bože! Kéž pro ty své plány padnou! Rozežeň je pro množství jejich přestoupení, vždyť se proti tobě vzepřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Kéž se radují všichni, kteří v tobě mají útočiště. Navěky budou jásat a ty je budeš chránit. Kéž se z tebe veselí ti, kdo milují tvé jméno!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Vždyť ty, Hospodine, žehnáš spravedlivému, jako pavézou ho obklopuješ přízní!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Pro vedoucího chval. ⌈Na strunné nástroje ⌉ k ⌈nízkému zpěvu⌉. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Hospodine, nekárej mě ve svém hněvu, ve své zlobě mě nekázni!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Smiluj se nade mnou, Hospodine, neboť jsem zemdlený! Uzdrav mě, Hospodine, vždyť mé kosti se třesou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'I má duše je velmi vyděšená. A ty, Hospodine, až dokdy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Navrať se, Hospodine, vytrhni mou duši, zachraň mě pro své milosrdenství!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, '⌈Mezi mrtvými na tebe nikdo ne vzpomíná!⌉ Kdo by ti vzdával chválu v podsvětí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Jsem vyčerpán svým vzdycháním. Každé noci promáčím své lůžko, slzami svou postel rozmočím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Trápením mi slábne zrak, ochabl kvůli všem mým nepřátelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Odstupte ode mě, všichni činitelé nepravosti! Hospodin slyšel ⌈můj pláč.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Hospodin vyslyšel mou úpěnlivou prosbu, Hospodin přijal mou modlitbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Všichni mí nepřátelé se budou stydět a třást, náhle se obrátí a zastydí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Davidova ⌈vášnivá píseň,⌉ kterou zpíval Hospodinu ohledně Benjamínce Kúše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, '⌈Hospodine, můj Bože,⌉ v tobě hledám útočiště! Zachraň mě před všemi mými pronásledovateli! Vysvoboď mě od nich!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'aby nerozsápali mou duši jako lev. Odvlečou mě a nebude, kdo by mě vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Hospodine, můj Bože, jestliže jsem to spáchal, jestliže na mých dlaních opravdu lpí špatnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'jestliže jsem odplácel zlem tomu, kdo se vůči mně měl pokojně, jestliže jsem bezdůvodně loupil ty, kdo se ke mně měli nepřátelsky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'pak ať nepřítel pronásleduje mou duši, ať mě dostihne a zadupe můj život do země a mou slávu ať uvrhne v prach! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Povstaň, Hospodine, ve svém hněvu, pozdvihni se ⌈proti zuřivosti mých nepřátel,⌉ ⌈postav se za mou věc,⌉ ⌈vynes rozsudek!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Obklopí tě pospolitost národů; kvůli nim se navrať na výšinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Hospodin rozsoudí národy. ⌈Zjednej mi právo,⌉ Hospodine, podle mé spravedlnosti a podle mé bezúhonnosti, ⌈ které na mně jsou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Kéž by už skončilo zlo ničemů a kéž by byl upevněn spravedlivý, ⌈Bože spravedlivý, který zkoumáš srdce i ledví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Svůj ⌈štít mám v Bohu,⌉ jenž zachraňuje lidi ⌈přímého srdce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Bůh je spravedlivý soudce, Bůh je rozhořčen každý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Jestliže se neobrátí, bude si brousit meč; napne luk a bude mířit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Připraví si smrtící zbraně, z šípů udělá hořící střely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Hle, kdo počal špatnost, otěhotněl trápením a porodil klam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Vykopal cisternu a vyhloubil ji, a upadl do jámy, kterou udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Jeho trápení se mu vrátí na hlavu a na temeno mu padne jeho násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Budu vzdávat chválu Hospodinu za jeho spravedlnost a budu opěvovat jméno Hospodina, Nejvyššího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Pro vedoucího chval. Na gittít. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Hospodine, náš Pane, jak vznešené je tvoje jméno na celé zemi! Tys dal svou velebnost na nebesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Z úst dětí a kojenců jsi ustanovil sílu kvůli těm, kdo se mají nepřátelsky. Tak jsi skoncoval s nepřítelem a s tím, kdo se mstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Když hledím na tvá nebesa -- dílo tvých prstů, měsíc a hvězdy, které jsi upevnil --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'co je člověk, že na něj pamatuješ, ⌈syn člověka,⌉ že jej navštěvuješ?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Trochu jsi jej omezil, aby ne byl božskou bytostí, a korunoval jsi ho slávou a důstojností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Svěřil jsi mu vládu nad dílem svých rukou, všechno jsi mu položil pod nohy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'všechen brav a skot i polní zvěř,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'nebeské ptactvo, mořské ryby i vše, co se brodí mořskými stezkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'Hospodine, náš Pane, jak vznešené je tvoje jméno na celé zemi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Pro vedoucího chval. Na mút labben. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Hospodine, celým srdcem ti budu vzdávat chválu, budu vyprávět o všech tvých divech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'V tobě se budu radovat a veselit, budu opěvovat tvé jméno, ó Nejvyšší!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Když se moji nepřátelé obrátili nazpět, upadli a zmizeli před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Zjednal jsi mi právo a obhájil jsi mě, usedl jsi na trůn, ty, spravedlivý soudce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Napomenul jsi národy, zničil jsi ničemy, jejich jméno jsi vymazal ⌈navěky a navždy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, '⌈Nepřátelé? Na věky skončili v troskách!⌉ Jejich města jsi vyvrátil, ano, jejich památka zašla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Hospodin ale navěky trůní. Svůj trůn připravil k soudu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'on bude soudit celý svět spravedlivě; národy rozsoudí s přímostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Hospodin je ⌈nepřístupným hradem⌉ utlačených, je nepřístupným hradem v dobách soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'V tebe budou doufat ⌈ti, kdo znají tvé jméno,⌉ neboť ty, Hospodine, neopustíš ty, kteří tě hledají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Opěvujte Hospodina, sídlícího na Sijónu, oznamujte mezi národy jeho činy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Neboť ⌈vyhledává krev,⌉ pamatuje na ně, nezapomíná na volání zkroušených.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Smiluj se nade mnou, Hospodine! Pohleď na mé soužení od těch, kdo mě nenávidí! Ty mě vyzdvihuješ z bran smrti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'abych v branách ⌈dcery sijónské⌉ vyprávěl o všech tvých ⌈chvályhodných skutcích⌉ a jásal nad tvou spásou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Národy se topí v jámě, kterou udělaly, jejich noha byla polapena do sítě, kterou nastražily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Hospodin se dal poznat, ⌈vykonal soud:⌉ Ničema se zapletl do díla svých rukou. Higgajón. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Ničemové se vrátí do podsvětí -- všechny národy zapomínající na Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Nuzný totiž nebude napořád zapomenut, naděje pokorných ne zahyne nastálo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Povstaň, Hospodine! Ať člověk nenabude moci! Ať jsou národy souzeny před tebou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Vlož na ně bázeň, Hospodine, ať národy poznají, že jsou jen lidé. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Hospodine, proč stojíš opodál? Proč se skrýváš v dobách soužení?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Ničema v pýše pronásleduje chudého. Kéž by byli lapeni ⌈do piklů, které kuli!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Vždyť ničema se vychloubá tužbami své duše, ⌈ten, kdo hrabe pro sebe, zlořečí⌉ a Hospodinem pohrdá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Ničema ⌈pro svou povýšenost⌉ moc nepřemýšlí. Bůh není -- toť všechno jeho uvažování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Jeho cesty jsou v každém čase úspěšné, vysoko před ním jsou tvé soudy. Všichni jeho nepřátelé? Nad těmi si odfrkne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'V srdci si říká: ⌈Z pokolení do pokolení⌉ mnou nic nepohne, vždyť ne upadnu do zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Jeho ústa jsou plná klení, klamu a útisku; pod jazykem skrývá trápení a nepravost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Sedí na číhané na ⌈uzavřených místech,⌉ v skrýších nevinného vraždí, svým okem skrytě vyhlíží ubožáka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Číhá v skrýších jako lev v houští, číhá, aby se zmocnil ubohého. Zmocňuje se ubohého, táhne ho svou sítí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'takže je zkrušen a pokořen. Kvůli hordám ničemy bezmocní padají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'V srdci si říká: Bůh zapomíná, ⌈skryl svou tvář,⌉ nikdy nic neuvidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Povstaň, Hospodine! Bože, ⌈pozvedni svou ruku!⌉ Nezapomeň na zkroušené!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Jak to, že ničema pohrdá Bohem? Říká si v srdci: ⌈Nebudeš se tím zabývat, Bože!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Ty však vidíš, hledíš na trápení a zášť a vezmeš to do své ruky. Vždyť ubožák ⌈se spoléhá na tebe.⌉ Sirotkovi ⌈se staneš pomocí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zlom paži ničemy i zlého! Odhal jeho ničemnost, až již žádnou nenajdeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Hospodin je králem navěky a navždy. Pohanské národy z jeho země zmizí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Hospodine, touhu pokorných jsi vyslyšel. Upevníš jim srdce, popřeješ jim sluchu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'abys zjednal právo sirotkovi a utlačenému. Člověk ze země je už nebude děsit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Pro vedoucího chval. Davidův žalm. Hledám útočiště v Hospodinu. Jak to, že říkáte mé duši: Uleť na tu vaši horu, ptáčku!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Hle, ničemové napínají luk, k tětivě přikládají šíp, aby v přítmí stříleli na lidi přímého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, '⌈Co má dělat spravedlivý,⌉ když se základy hroutí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Hospodin je ve svém svatém chrámu, Hospodin je v nebesích na svém trůnu, jeho oči vidí, jeho pohled zkoumá ⌈lidské syny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Hospodin zkoumá ⌈spravedlivého i ničemu. Jeho duše nenávidí lidi milující násilí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Na ničemy sešle řeřavé uhlí a síru; žhoucí vichr bude jejich údělem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'neboť Hospodin je spravedlivý. Miluje ⌈spravedlivé činy.⌉ Upřímný spatří jeho tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Pro vedoucího chval. K nízkému zpěvu. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Pomoz, Hospodine! S věrnými je konec! Mezi syny lidskými vymizeli pravdiví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Každý ⌈obelhává svého bližního,⌉ ⌈z dvojakého srdce mluví úlisnými rty.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Kéž by Hospodin vyhladil všechny úlisné rty i jazyk, jenž mluví velikášsky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Takoví říkají: ⌈Svým jazykem zvítězíme.⌉ ⌈Máme ústa⌉ -- kdo je naším pánem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Pro ⌈zkázu zkroušených⌉ a pro nářek chudých nyní povstanu, praví Hospodin, ⌈postavím do bezpečí⌉ toho, nad nímž si odfrkují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Hospodinovy řeči jsou čisté, jsou jako stříbro přetavené v hliněné peci, sedmkrát přečištěné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Hospodine, ty je budeš navěky chránit a střežit před tím pokolením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'Ničemové obcházejí kolem, protože mezi syny lidskými je vyvýšena nízkost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Dokdy, Hospodine, na mě budeš zapomínat? Navěky? Dokdy budeš přede mnou skrývat svou tvář?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Dokdy ⌈se budu muset radit jen se svou duší⌉ a v srdci mít každého dne žal? Dokdy se bude nade mnou můj nepřítel vyvyšovat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Pohleď na mě a odpověz mi, Hospodine, můj Bože! Osviť mi oči, jinak usnu smrtelným spánkem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Aby můj nepřítel neřekl: Zdolal jsem ho. Padnu–li, moji protivníci budou jásat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Já však doufám v tvé milosrdenství; mé srdce jásá nad tvou spásou. Budu Hospodinu zpívat, protože mi prokázal dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Pro vedoucího chval. Davidův žalm. Blázen si v srdci říká: Bůh není. Lidé jednají zvráceně, páchají ohavné činy. Není, kdo by činil dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Hospodin shlíží z nebes na lidské syny, aby viděl, zda je někdo rozumný, zda někdo hledá Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Všichni se společně odvrátili a jsou zvrácení. Není, kdo by činil dobro, není ani jednoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Opravdu tomu nerozumí nikdo z činitelů nepravosti, kteří pojídají můj lid, jako by jedli chléb, a kteří k Hospodinu nevolají?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, '⌈Jednou se budou třást strachem,⌉ neboť Bůh je s pokolením spravedlivých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Radu chudého zesměšňujete, avšak Hospodin je jeho útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Kéž by byla Izraeli dána spása ze Sijónu! Až Hospodin změní úděl svého lidu, bude Jákob jásat, Izrael se bude radovat!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Davidův žalm. Hospodine, kdo bude hostem ve tvém stanu? Kdo bude přebývat na tvé svaté hoře?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Ten, kdo žije bezúhonně, ⌈činí spravedlnost⌉ a mluví pravdu ⌈v srdci,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'kdo ⌈svým jazykem⌉ nepomlouvá, nečiní svému druhovi zlo a nekydá na svého blízkého hanu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'pohrdá ve svých očích zavrženíhodným, váží si však těch, kdo se bojí Hospodina. Odpřisáhl–li něco ke své škodě, nezmění to;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'své peníze nedává na lichvu, úplatek proti nevinnému nepřijímá. Kdo takto jedná, nepohne se až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Davidův ⌈pamětní zápis.⌉ Chraň mě, Bože, neboť v tobě hledám útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Řekni Hospodinu: ⌈Pane, ty jsi mé dobro, mimo tebe žádné nemám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Co se týče svatých, kteří jsou na zemi: Ti jsou vznešení. Mám v nich velké zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Bolesti si rozmnožují ti, kdo běhají za jinými bohy. Těm jejich krvavé úlitby nepřinesu. Jejich jména si ani nevezmu na rty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Hospodin je ⌈můj výtečný podíl⌉ a můj kalich; ty sám držíš můj los.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, '⌈ Vyměřovací provazce mi padly na rozkošných místech. Ano, připadlo mi nádherné dědictví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Budu dobrořečit Hospodinu, který mi radí. I v noci mě kázní mé svědomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Stále si ⌈stavím Hospodina před sebe.⌉ Když je mi po pravici, nepadnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Proto se mé srdce raduje a má sláva jásá. I mé tělo bude přebývat v bezpečí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'neboť mou duši nepřenecháš podsvětí; nedáš svému věrnému spatřit jámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Dáváš mi poznat stezku života, hojnost radosti je tvá přítomnost, ve tvé pravici je ⌈věčné blaho.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Davidova modlitba. Slyš, Hospodine, spravedlivou při, věnuj pozornost mému nářku. Naslouchej mé modlitbě, ne pochází z klamných rtů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Kéž soud nade mnou vyjde přímo od tebe, tvé oči vidí přímost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Zkoumal jsi mé srdce, navštěvovals mě v noci, tříbils mě, nic jsi nenalezl. ⌈ Mé záměry nepředcházejí má ústa.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Co se týče lidských skutků, podle slova tvých rtů jsem se chránil cest lupičů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Mé kroky ⌈se držely⌉ ve tvých stezkách, mé nohy neuklouzly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Volám k tobě, Bože, protože mi odpovídáš. ⌈Nakloň ke mně své ucho,⌉ slyš mou řeč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Prokaž své milosrdenství, spasiteli těch, kdo před protivníky hledají útočiště ve tvé pravici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Chraň mě jako zřítelnici svého oka, ve stínu svých křídel mě skryj');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'před ničemy, kteří mě ničí, před úhlavními nepřáteli, kteří mě obklopují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Zarostli tukem, ⌈jejich ústa mluví povýšeně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Nyní ⌈mě už vystopovali,⌉ obklíčili mě, zkoumají, jak mě dostat na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Podobá se lvu, bažícímu po trhání kořisti, mladému lvu, jenž ve skrytu číhá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Povstaň, Hospodine, předejdi ho a sraz ho, svým mečem vysvoboď mou duši od ničemy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'a svou rukou, Hospodine, od lidí, od lidí tohoto věku, ⌈ kteří mají podíl na životě.⌉ Ze své pokladnice jim plníš břicho -- i jejich synové se nasytí a zbytek zanechají svým dětem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Já ale spatřím tvou tvář ⌈v spravedlnosti;⌉ až procitnu, budu nasycen tvým zjevem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Pro vedoucího chval. Od Hospodinova otroka Davida, jenž pověděl Hospodinu slova této písně v den, kdy jej Hospodin vysvobodil z moci všech jeho nepřátel i z ruky Saulovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Řekl: ⌈Vroucně tě miluji,⌉ Hospodine, moje sílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Hospodin je má skála, má tvrz, můj vysvoboditel. Můj Bůh je má skála, v něm hledám útočiště; je můj štít a ⌈roh mé záchrany,⌉ můj nedobytný hrad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Volal jsem k Hospodinu, jenž je chvályhodný, a byl jsem zachráněn od svých nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Omotaly mě provazy smrti, zachvátily mě proudy Beliálovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Ovinuly mě provazy podsvětí, v ústrety mi vyšly léčky smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'V tísni jsem volal k Hospodinu, křičel jsem ke svému Bohu. Ze svého chrámu uslyšel můj hlas a můj křik před ním pronikl k jeho uším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Země se zachvěla a zatřásla. Otřásly se i základy hor, zakymácely se, neboť vzplanul hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Z chřípí mu vystupoval dým a z úst stravující oheň, od nějž chytalo uhlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Roztáhl nebesa a sestupoval, pod nohama hustou temnotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Vsedl na cheruba a letěl, vznášel se na křídlech větru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Temnotu učinil svou skrýší, stánkem kolem sebe temné vody, hustá oblaka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Ze záře před ním vystupovala mračna, krupobití a řeřavé uhlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Hospodin zahřměl na nebesích, Nejvyšší vydal svůj hlas -- krupobití a řeřavé uhlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Poslal své šípy a rozptýlil je, množstvím blesků je přivedl do zmatku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, '⌈Když jsi zahrozil,⌉ Hospodine, ukázala se koryta vod, odhalily se základy světa -- ⌈před dechem tvého hněvivého ducha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Vztáhl ruku z výšiny, uchopil mě a vytrhl mě z mocných vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Vysvobodil mě od mocného nepřítele, od těch, kdo mě nenáviděli, kdo byli silnější než já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Postupovali proti mně v den mé pohromy, Hospodin mi však byl oporou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Vyvedl mě na prostranno, vytrhl mě, neboť si mě oblíbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Hospodin mi odplatil podle mé spravedlnosti, podle čistoty mých rukou mě odměnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Vždyť jsem dbal na Hospodinovy cesty a neodvrátil jsem se svévolně od svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Všechna jeho nařízení jsou přede mnou, jeho ustanovení jsem neodložil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Byl jsem ⌈před ním⌉ bezúhonný; měl jsem se na pozoru, abych se neprovinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Hospodin mě odměnil podle mé spravedlnosti, podle čistoty mých rukou před jeho zrakem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'S věrným jednáš věrně, s člověkem bezúhonným bezúhonně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Čistému se jevíš čistě a se zvráceným ⌈jednáš převráceně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Vždyť ty zachraňuješ nuzný lid, povýšené oči však snižuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Ty, Hospodine, ⌈rozsvěcíš mou lampu.⌉ Můj Bůh prozařuje mou temnotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Vždyť v tobě proběhnu nepřátelskou hordu, ve svém Bohu přeskočím zeď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Bůh -- jeho cesta je bezúhonná. Hospodinova řeč je protříbená. On je štítem všem, kdo v něm hledají útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Vždyť kdo je Bohem kromě Hospodina? Kdo je skálou, ne–li náš Bůh?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Tento Bůh mě odívá silou, on činí mou cestu bezúhonnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Mé nohy činí jako nohy laně, upevňuje mě na mých výšinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Učí mé ruce boji, takže mé paže napnou bronzový luk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Dals mi i štít své spásy. Tvá pravice mě podepírá, tvá mírnost mě zvelebuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, '⌈Zjednals mi prostor,⌉ kotníky se mi nepodvrtnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Pronásledoval jsem své nepřátele a dostihl jsem je. Nevrátím se, dokud s nimi neskoncuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Zdeptám je tak, že nebudou moci povstat; padnou mi pod nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Vždyť jsi mě přepásal silou k boji, mé protivníky srazíš pode mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Vydals mi šíji mých nepřátel; zničím ty, kdo mě nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Budou křičet, a zachránce není, volat k Hospodinu, ale neodpoví jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Rozdrtím je a budou jako prach ve větru, odstraním je jako bláto z ulic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Vytrhls mě ze srocení lidu, učinils mě hlavou národů. Bude mi sloužit i lid, který jsem neznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Hned jak mě uslyší, poslechnou mě. Cizinci mi budou lichotit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Cizinci zvadnou a ⌈v děsu vyjdou⌉ ze svých pevností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Živ je Hospodin! Požehnaná je moje skála! Ať je vyvýšen Bůh, má spása!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Bůh mi dává vykonat pomstu a podrobuje mi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Vysvobozuje mě od mého nepřítele, ano, vyvyšuješ mě nad mé protivníky, zachráníš mě před násilníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Proto ti budu vzdávat chválu mezi národy, Hospodine, a budu opěvovat tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, 'který tak ⌈úžasně zachraňuješ⌉ svého krále a prokazuješ milosrdenství svému pomazanému, Davidovi, a jeho potomstvu až navěky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Nebesa vypravují o Boží slávě; obloha vypovídá o díle jeho rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Den dni vylévá řeč, noc noci sděluje poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Není to řeč, nejsou to slova, jejich hlas není slyšet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Do celé země proniká jejich zvuk a jejich výroky do končin světa. Slunci na nich postavil stan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Ono jako ženich vychází ze své komnaty; veselí se jako hrdina běžící svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Od konce nebes vychází a ⌈obíhá opět ke konci;⌉ před jeho žárem se nic neskryje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Hospodinův zákon je ryzí, obnovuje duši. Hospodinovo svědectví je spolehlivé, prostým lidem dává moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Hospodinova přikázání jsou přímá, obšťastňují srdce. Hospodinův příkaz je vytříbený, dává očím světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Hospodinova bázeň je čistá, obstojí navždy. Hospodinova rozhodnutí jsou spolehlivá i spravedlivá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Jsou žádoucnější než zlato, než množství ryzího zlata. Jsou sladší než med, med tekoucí z plástve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Ano, tvůj otrok se jimi nechává varovat, dbát na ně přináší hojnou odměnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Kdo rozpozná pochybení? Zbav mě těch skrytých');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'a zdržuj svého otroka i od těch troufalých, aby mě neopanovaly. Pak budu ryzí a prost velikého přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, 'Kéž jsou ti příjemná slova mých úst, stejně jako rozjímání mého srdce, Hospodine, má skálo a můj vykupiteli!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Kéž ti Hospodin odpoví v den soužení, kéž ti ⌈poskytne bezpečí⌉ jméno Boha Jákobova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Kéž ti sešle pomoc ze svatyně, kéž tě podepře ze Sijónu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Kéž pamatuje na všechny tvé obětní dary, kéž má tvé zápalné oběti za tučné! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Kéž ti dá podle tvého srdce, kéž naplní všechny tvé plány!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Budeme jásat nad tvým vítězstvím a ve jménu svého Boha ⌈vyzdvihneme korouhve.⌉ Kéž Hospodin vyplní všechny tvé prosby!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Nyní vím, že Hospodin zachrání svého pomazaného, že mu odpoví ze svého svatého nebe mocnými spásnými činy své pravice!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Jedni doufají ve vozy, druzí zase v koně, my však připomínáme jméno ⌈Hospodina, našeho Boha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Oni klesali a padli, my jsme povstali a jsme obnovováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, 'Hospodine, ⌈zachraň nás! Kéž nám Král odpoví⌉ v den, kdy budeme volat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Hospodine, král se raduje ze tvé síly! A jak velice jásá nad tvým vítězstvím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Dal jsi mu touhu jeho srdce, prosbě jeho rtů jsi neodepřel. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Vyšel jsi mu vstříc s ⌈požehnáním dobrých věcí⌉ a na hlavu jsi mu vložil korunu z ryzího zlata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Žádal tě o život a dal jsi mu jej, dlouhý život navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Díky tvému vítězství je jeho sláva velká, oděl jsi jej nádherou a důstojností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Učinil jsi jej navždy požehnáním, oblažuješ jej radostí ze své přítomnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Vždyť král doufá v Hospodina a pro milosrdenství Nejvyššího se nepohne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Tvá ruka najde všechny tvé nepřátele, tvá pravice najde ty, kdo tě nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Až se objevíš, ⌈učiníš je ohnivou pecí.⌉ Hospodin je ve svém hněvu pohltí, pozře je oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Jejich plod vyhladíš ze země a jejich símě ze synů lidských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, '⌈Chystali ti sice zlé⌉ a kuli pikle, nic však nezmohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Tětivy jim namíříš do tváře, a tak je přinutíš ukázat záda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, 'Vyvyš se, Hospodine, ve své moci! Budeme zpívat a opěvovat tvé mocné činy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Pro vedoucího chval. Podle „Laně za úsvitu“. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Bože můj, Bože můj, proč jsi mě opustil? ⌈ Jsi daleko od mé spásy, od slov mého naříkání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Bože můj, volám ve dne -- ty neodpovídáš, volám v noci -- není pro mě utišení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Ty jsi svatý, trůníš na chvalách Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'V tebe doufali naši otcové, doufali, a tys je vytrhoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Volali k tobě a byli zachráněni, doufali v tebe a nebyli zahanbeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Ale já jsem červ a ne člověk, potupa pro lidi, lidem opovržený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Všichni, kdo mě vidí, se mi posmívají. Pošklebují se, potřásají hlavou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, '⌈Spolehni se na Hospodina!⌉ Ať ho vytrhne, ať ho vysvobodí, když si ho oblíbil!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Vždyť ty jsi mě vyvedl z lůna, dals mi doufat na prsech mé matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Na tebe jsem odkázán od narození, od lůna matky jsi mým Bohem ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Nevzdaluj se ode mě, neboť soužení je blízko a pomocníka není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Obklíčilo mě množství býků, ti silní z Bášanu mě obklopili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Otvírají na mě tlamu jako lev, který trhá kořist a řve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Rozlévám se jak voda a všechny mé kosti se uvolňují. ⌈Mé srdce je jako vosk,⌉ rozpustilo se v mém nitru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Jak hliněný střep vyschla má síla, jazyk se mi lepí na patro, určils mi místo v prachu smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Obklíčili mě psi, roj zlovolníků mě obklopil, spoutali mi ruce a nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Počítám všechny své kosti. Oni civí, sledují mě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'dělí si mé roucho, vrhají los o můj oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Ale ty, Hospodine, se nevzdaluj, má sílo, ⌈pospěš mi na pomoc!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Vysvoboď mou duši od meče, mou jedinou z moci psů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Zachraň mě ze lví tlamy a před rohy divokých turů! Tys mi odpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Tvé jméno budu zvěstovat svým bratřím, ve shromáždění tě budu chválit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Vy, kdo se bojíte Hospodina, chvalte ho! Veškeré potomstvo Jákobovo, ctěte ho! Třeste se před ním, všechno potomstvo Izraelovo!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Neboť nepohrdl a neopovrhl trápením zkroušeného, ⌈neskryl před ním svou tvář.⌉ Když k němu volal, vyslyšel ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Od tebe pochází má chvála ve velikém shromáždění, své sliby splním před těmi, kdo se ho bojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Pokorní budou jíst a nasytí se. Ti, kdo hledají Hospodina, ho budou chválit. Vaše srdce bude žít navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Všechny končiny země se rozpomenou a obrátí se k Hospodinu. Všechny čeledi národů se budou klanět před tvojí tváří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Vždyť království náleží Hospodinu, on panuje nad národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Všichni, ⌈jimž se na zemi daří,⌉ budou jíst a klanět se před jeho tváří, pokleknou před ním všichni, kdo sestupují v prach, i ten, kdo svou duši při životě nezachová.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Potomstvo mu bude sloužit. Panovníkovi bude přičteno k pokolením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, 'Přijdou a budou zvěstovat jeho spravedlnost lidu, který se zrodí -- vždyť ji vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Davidův žalm. Hospodin je můj pastýř, nebudu mít nedostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Dává mi uléhat na travnatých pastvinách, přivádí mě k ⌈vodě na místech odpočinku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Obnovuje mou duši, ⌈pro své jméno⌉ mě vodí po pravých stezkách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'I kdybych šel údolím ⌈nejhlubší tmy,⌉ nebudu se bát zlého, neboť ty jsi se mnou. Tvé žezlo a tvá hůl mě potěšují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Připravuješ mi stůl před zraky mých nepřátel, mažeš mi hlavu olejem, můj kalich přetéká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Dobrota a milosrdenství mě budou jistě provázet po všechny dny mého života. Po dlouhé časy se budu vracet do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Davidův žalm. Hospodinu patří země a ⌈vše, co je na ní,⌉ celý svět a všichni jeho obyvatelé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Vždyť on ji založil na vodách, upevnil ji na vodních proudech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kdo vystoupí na Hospodinovu horu? Kdo stane na jeho svatém místě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Ten, kdo má nevinné ruce a čisté srdce, kdo nepozvedá svou duši ke klamu a nepřísahá falešně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Ten vezme od Hospodina požehnání, přijme spravedlnost od Boha, své spásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Takové je pokolení těch, kdo hledají Boha. Jákob -- to jsou ti, kteří vyhledávají tvou tvář. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Brány, pozdvihněte své hlavy. Věčné vchody, zvedněte se! Vchází Král slávy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kdo to je, ten Král slávy? Hospodin, silný a udatný, Hospodin, ⌈udatný válečník.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Brány, pozdvihněte své hlavy. Věčné vchody, pozdvihněte se! Vchází Král slávy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kdo to je, ten Král slávy? Hospodin zástupů -- on je Král slávy! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Davidův žalm. K tobě, Hospodine, pozvedám svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Bože můj, v tebe doufám, kéž nejsem zahanben, kéž nade mnou moji nepřátelé nejásají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Ano, ti, kdo na tebe očekávají, se stydět ne musejí. Budou se stydět ti, kdo bezdůvodně jednají věrolomně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Hospodine, dej mi poznat svoje cesty, vyuč mě svým stezkám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, '⌈Uváděj mě do své pravdy,⌉ vyučuj mě, vždyť jsi můj Bůh, má spása. Po ⌈celý den⌉ očekávám na tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Vzpomeň na své slitování, Hospodine, i na své milosrdenství, vždyť je od věčnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Nevzpomínej však na hříchy mého mládí, na má přestoupení. Vzpomeň na mě podle svého milosrdenství, kvůli své dobrotě, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Hospodin je dobrý a přímý, proto vyučuje hříšníky cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Pokorné uvádí do práva, pokorné učí své cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Všechny Hospodinovy stezky jsou ⌈milosrdenství a věrnost⌉ pro ty, kdo dbají na jeho smlouvu a jeho svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Pro své jméno, Hospodine, mi odpusť mou vinu; ano, je velká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, '⌈Jak je na tom⌉ člověk, který se bojí Hospodina? Bude ho vyučovat cestě, kterou si má zvolit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Jeho duše bude přebývat v dobru a jeho potomstvo zdědí zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'S těmi, kdo se ho bojí, má Hospodin důvěrný vztah, dává jim poznat svou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mé oči stále hledí k Hospodinu, neboť on vyprošťuje mé nohy z léčky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Pohleď na mě a smiluj se nade mnou, protože jsem osamělý a zkroušený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Soužení mého srdce se množí, vyveď mě z mých úzkostí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Pohleď na mé soužení a mé trápení a sejmi všechny mé hříchy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Pohleď, jak mnoho je mých nepřátel, jakou zuřivou nenávistí mě nenávidí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Chraň mou duši a vysvoboď mě, ať nejsem zahanben, vždyť hledám útočiště v tobě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Nechť mě střeží bezúhonnost a upřímnost, vždyť na tebe očekávám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Bože, vykup Izraele ze všech jeho soužení!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Davidův žalm. Zjednej mi právo, Hospodine! ⌈Žil jsem bezúhonně,⌉ doufal jsem v Hospodina, nebyl jsem v tom nejistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Zkoumej mě, Hospodine, zkoušej mě, prověř mé ledví i srdce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Vždyť tvé milosrdenství mám před očima, chodím ve tvé pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Nesedávám s podvodníky, nechodím mezi pokrytce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Nenávidím shromáždění zlovolníků, nevysedávám s ničemy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Umývám si ruce v nevinnosti a držím se při tvém oltáři, Hospodine,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'abych hlasitě zvěstoval tvou chválu a vyprávěl o všech tvých divech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Hospodine, miluji přebývání ve tvém domě, místo, ⌈kde přebývá⌉ tvá sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, '⌈Nezahrň mou duši mezi⌉ hříšníky a můj život mezi ty, kdo prolévají krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Ti rukama páchají hanebnost a jejich pravice je plná úplatků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Já však žiji bezúhonně; vykup mě, smiluj se nade mnou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Má noha stojí na rovině. Budu Hospodinu dobrořečit ve shromážděních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Davidův žalm. Hospodin je mé světlo i má spása, koho bych se bál? Hospodin je záštita mého života, koho bych se lekal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Když se ke mně přiblížili zlovolníci, aby ⌈pozřeli mé tělo,⌉ moji protivníci a nepřátelé, sami klopýtli a padli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Kdyby se proti mně položilo vojsko, mé srdce se nebude bát. Kdyby se proti mně zvedla bitva, i tehdy budu doufat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'O jedno jsem Hospodina žádal, to jedno jsem hledal: A bych přebýval v domě Hospodinově po všechny dny svého života, abych mohl hledět na Hospodinovu nádheru a abych mohl přemítat v jeho chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'V den zlý mě schová ve své skrýši, skryje mě v úkrytu svého stanu, na skálu mě zdvihne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'A teď ⌈zvedám hlavu⌉ nad své nepřátele kolem sebe. V jeho stanu budu obětovat oběti radostných výkřiků, budu zpívat a opěvovat Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, '⌈Slyš, Hospodine, když hlasitě volám,⌉ smiluj se nade mnou a odpověz mi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, '⌈Ohledně tebe svému srdci⌉ připomínám slova: Hledejte mou tvář! A já tvou tvář hledám, Hospodine!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Neskrývej přede mnou svou tvář, neodvracej se hněvivě od svého otroka -- býval jsi mou pomocí. Nenech mě, neopouštěj mě, Bože, má spáso!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'I kdyby mě opustili můj otec a má matka, Hospodin mě k sobě přivine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Vyuč mě, Hospodine, své cestě, veď mě rovnou stezkou, vždyť na mě číhají!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Nevydávej mě choutkám mých protivníků, neboť proti mně povstávají lživí svědkové a zlovolný žalobce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Jak bych nevěřil, že budu hledět na Hospodinovu dobrotu v zemi živých!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Očekávej na Hospodina! Buď pevný a posilni své srdce! Očekávej na Hospodina!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Davidův žalm. K tobě volám, Hospodine, má skálo, nebuď ke mně hluchý! ⌈Neozveš–li se mi,⌉ budu podobný těm, kdo sestupují v jámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Vyslyš mé úpěnlivé prosby, když k tobě volám, když pozvedám ruce ke tvé nejsvětější svatyni!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Neodvleč mě s ničemy, s činiteli nepravosti, s těmi, kdo se svými bližními mluví pokojně, ale v jejich srdci je zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Dej jim podle jejich skutků, podle jejich zvrácených činů, podle díla jejich rukou jim dej, vrať jim, co vykonali!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Oni neuvažují o Hospodinově jednání, o díle jeho rukou. Strhne je a už je nezbuduje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, '⌈Požehnán buď Hospodin,⌉ neboť vyslyšel mé úpěnlivé prosby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Hospodin je má síla a můj štít, v něho doufá mé srdce. Dostalo se mi pomoci, proto mé srdce jásá, proto mu budu vzdávat chválu svou písní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Hospodin je silou ⌈svého lidu,⌉ je spásnou záštitou svému pomazanému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Zachraň svůj lid, žehnej svému dědictví, pas jej, nos jej stále!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Davidův žalm. ⌈Vzdejte Hospodinu, synové Boží, vzdejte Hospodinu⌉ slávu a sílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Vzdejte Hospodinu slávu jeho jména, klaňte se Hospodinu v nádheře svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Hlas Hospodinův nad vodami, slavný Bůh zahřměl, Hospodin nad mocnými vodami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Hospodinův hlas je mocný, Hospodinův hlas je nádherný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Hospodinův hlas láme cedry, Hospodin tříští libanonské cedry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Působí, že Libanon poskakuje jako tele a Sirjón jako mládě divokého tura.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Hospodinův hlas rozkřesává plameny ohně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Hospodinův hlas působí, že se poušť svírá bolestí, Hospodin k bolesti přivádí poušť Kádeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Hospodinův hlas přivádí laně ku porodu a obnažuje lesy. A v jeho chrámu všichni říkají: Sláva!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Hospodin trůnil nad potopou, Hospodin bude trůnit jako král navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Hospodin dává svému lidu sílu, Hospodin žehná svému lidu pokojem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, '⌈Žalm. Píseň při posvěcení Davidova domu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Budu tě vyvyšovat, Hospodine, protože jsi mě vytáhl z hlubin a nedal jsi mým nepřátelům, aby se nade mnou radovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, '⌈Hospodine, můj Bože,⌉ křičel jsem k tobě a tys mě uzdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Hospodine, vyvedl jsi mou duši z podsvětí, obživil jsi mě, abych nesestoupil do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Opěvujte Hospodina, jeho věrní, vzdávejte chválu ⌈jeho svatému jménu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Vždyť jeho hněv trvá jen chvíli, jeho přízeň však celý život. Večer se uhostí pláč, ale ráno jásot.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'V ⌈ dobách pohody⌉ jsem si řekl: Nikdy ⌈se nepohnu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Hospodine, svou přízní jsi mocně upevnil mou horu. Když jsi však skryl svou tvář, zděsil jsem se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'K tobě, Hospodine, volám, prosím Panovníka o smilování:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, '⌈K čemu ti bude má krev,⌉ když sestoupím v jámu? Bude tě chválit prach? Ten bude zvěstovat tvoji věrnost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Vyslyš mě, Hospodine! Smiluj se nade mnou! Hospodine, buď mým pomocníkem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Mé kvílení jsi mi změnil v tanec, rozvázal jsi mi žíněné roucho a přepásal jsi mě radostí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, 'aby tě sláva opěvovala a neumlkla. Hospodine, můj Bože, navěky tě budu chválit!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'V tobě, Hospodine, hledám útočiště; kéž nejsem nikdy zahanben. Vytrhni mě pro svou spravedlnost!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Nakloň ke mně své ucho, rychle mě vysvoboď, buď mi pevnou skálou, opevněným domem, abys mě zachránil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Neboť ty jsi má skála a má tvrz! Pro své jméno mě tedy veď a posiluj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Vyveď mě z léčky, kterou mi nastražili. Vždyť tys má záštita!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Do tvých rukou poroučím svého ducha. Ty jsi mě vykoupil, Hospodine, Bože pravý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Nenávidím ty, kdo se oddávají klamným nicotnostem. Já spoléhám na Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Budu jásat, budu se radovat v tvém milosrdenství, neboť jsi pohleděl na mé soužení a znáš úzkosti mé duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Nevydal jsi mě do ruky nepřátel, mé nohy jsi postavil na rovné zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Smiluj se nade mnou, Hospodine, neboť je mi úzko. Trápením mi slábne zrak, duše i tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Život mi pomíjí žalem, mé roky vzdycháním, pro mé provinění ochabuje má síla a mé kosti slábnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Pro všechny své nepřátele jsem se stal potupou, zvláště pro své sousedy, pro své známé ⌈ předmětem hrůzy;⌉ ti, kdo mě ⌈venku vidí,⌉ přede mnou prchají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Vypadl jsem jim ze srdce jako mrtvý, jsem jako rozbitá nádoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Slyším mnoho pomluv, všude kolem hrůza! Když se proti mně radí, zvažují, jak mě připravit o život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Já však doufám v tebe, Hospodine! Řekl jsem: Tys můj Bůh!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Mé časy jsou ve tvé ruce. Vysvoboď mě z ruky mých nepřátel a od těch, kdo mě pronásledují!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Rozjasni svou tvář nad svým otrokem, zachraň mě svým milosrdenstvím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Hospodine, kéž nejsem zahanben -- vždyť jsem volal k tobě! Kéž jsou zahanbeni ničemové, kéž zmlknou v podsvětí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Kéž oněmí lživé rty, které mluví o spravedlivém drze, povýšeně a pohrdavě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Jak velká je dobrota, kterou chováš vůči těm, kdo se tě bojí! Před lidskými syny ji prokazuješ těm, kdo v tobě hledají útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Skrýváš je v úkrytu své přítomnosti před lidskými intrikami, schováváš je v stánku před svárlivými jazyky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, '⌈Požehnán buď Hospodin,⌉ neboť ⌈mě udivil svým milosrdenstvím⌉ v obleženém městě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Když jsem se unáhlil, řekl jsem, že jsem zapuzen od tvých očí. Tys ale vyslyšel mé úpěnlivé prosby, když jsem k tobě volal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Milujte Hospodina, všichni jeho věrní! Pravdivé lidi Hospodin střeží, leč odplácí plně těm, kdo jednají povýšeně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, 'Buďte pevní a posilněte svá srdce, všichni, kdo ⌈očekáváte na⌉ Hospodina!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Davidův žalm k meditaci. Blahoslavený je ten, z něhož je sňato přestoupení a jehož hřích je přikryt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Blahoslavený je člověk, jemuž Hospodin nepočítá vinu a v jehož duchu není záludnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Když jsem mlčel, mé kosti chřadly, neboť jsem celé dny naříkal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Ve dne i v noci na mně těžce ležela tvá ruka. Morek se mi kazil jako v letním žáru. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Pak jsem ti svůj hřích oznámil; svou vinu jsem neukryl. Řekl jsem: Vyznám na sebe svá přestoupení Hospodinu. A tys sňal vinu mého hříchu. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Proto ať se k tobě modlí každý věrný v čase, kdy tě lze nalézt. Ani příval velkých vod k němu nedosáhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tys mou skrýší, střežíš mě před soužením; ⌈obklopíš mě jásotem nad vysvobozením.⌉ Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Dám ti chápání, vyučím tě cestě, kterou máš jít, ⌈budu ti radit, spočine na tobě mé oko.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Nebuďte jako kůň či jako mezek bez rozumu. ⌈Ty je třeba krotit uzdou a udidlem⌉ -- jinak k tobě nepřijdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Mnohé jsou bolesti ničemy, ale toho, kdo doufá v Hospodina, obklopuje milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Radujte se v Hospodinu a plesejte, spravedliví, jásejte, všichni lidé přímého srdce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Jásejte, spravedliví, v Hospodinu, ⌈přímým přísluší⌉ chvála.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Chvalte Hospodina na lyru, opěvujte jej při harfě o deseti strunách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Zpívejte mu novou píseň, dobře hrajte s radostným křikem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Neboť Hospodinovo slovo je přímé, každé jeho dílo se děje v pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, '⌈Miluje spravedlnost a právo,⌉ země je plná Hospodinova milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Hospodinovým slovem byla učiněna nebesa a dechem jeho úst všechen jejich zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Hromadí jako val mořské vody, do skladů dává hlubiny vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Boj se Hospodina, celá země! Třeste se před ním, všichni obyvatelé světa!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Vždyť on řekl a stalo se. On přikázal a uskutečnilo se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Hospodin ruší rady národů, maří lidské plány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Rada Hospodinova obstojí navěky, plány jeho srdce ⌈z pokolení do pokolení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Blahoslavený je národ, jehož Bohem je Hospodin; lid, který si vyvolil za dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Hospodin hledí z nebe, vidí všechny lidské syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Ze sídla svého přebývání pozoruje všechny obyvatele země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Ten, který všem jim vytvořil srdce, rozumí též všem jejich skutkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Král se nezachrání velkým vojskem, hrdina se nevysvobodí velkou silou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Kůň je k záchraně nespolehlivý; svou velkou silou nezachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Hle, Hospodinovo oko hledí na ty, kdo se ho bojí, na ty, kdo očekávají na jeho milosrdenství,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'aby vysvobodil jejich duše od smrti, aby je zachoval při životě v čas hladu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Naše duše očekává na Hospodina. On je naše pomoc i náš štít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Vždyť v něm se raduje naše srdce; vždyť spoléháme na jeho svaté jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Kéž je s námi tvé milosrdenství, Hospodine, protože na tebe očekáváme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Davidův žalm. (Když změnil své chování před Abímelekem. Ten ho vyhnal a David odešel).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'V každém čase budu dobrořečit Hospodinu. V mých ústech bude ustavičně ⌈jeho chvála.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Má duše se chlubí Hospodinem. Pokorní to uslyší a budou se radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Velebte se mnou Hospodina! Vyvyšujme společně jeho jméno!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Hledal jsem Hospodina, a odpověděl mi!, vysvobodil mě ode všeho, ⌈čeho jsem se hrozil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Ti, kdo na něj hledí, budou zářit. ⌈ Na jejich tvářích ne bude stud.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Tento chudý volal, a Hospodin ho vyslyšel. Zachránil ho ze všech jeho soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Hospodinův anděl táboří kolem těch, kdo se ho bojí, a vytrhuje je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Okuste a vizte, že Hospodin je dobrý. Blahoslavený je muž, který v něm hledá útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Bojte se Hospodina, jeho svatí! Ti, kdo se ho bojí, ne trpí nouzi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, '⌈Mladí lvi strádají⌉ a hladovějí, ale ti, kteří hledají Hospodina, nemívají nedostatek v ničem dobrém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Pojďte, synové, a poslouchejte mě, vyučím vás bázni před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Jaký je člověk, který si oblíbil život a miluje ⌈dny, kdy uvidí⌉ dobro?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Střež svůj jazyk od zlého a své rty před klamnými řečmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Odvrať se od zlého a čiň dobré, hledej pokoj a usiluj o něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Hospodinovy oči hledí na spravedlivé, jeho uši slyší jejich volání o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Hospodinova tvář je proti těm, kdo páchají zlo, aby vyhladil ze země jejich památku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Když úpěnlivě volají, Hospodin je vyslýchá, vysvobozuje je ze všech jejich soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Hospodin je blízko těm, kdo jsou zkroušeni v srdci, zachraňuje ty, kdo mají zdeptaného ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Mnoho zla přichází na spravedlivého, ale Hospodin jej ze všeho vysvobodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Střeží všechny jeho kosti, ani jedna z nich nebude zlomena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Ničemu zahubí zlo. Kdo nenávidí spravedlivého, ponese vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, 'Hospodin vykoupí duše svých otroků. Nikdo z těch, kteří v něm hledají útočiště, neponese vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Davidův žalm. Hospodine, veď při s mými odpůrci, bojuj proti těm, kdo se mnou bojují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Uchop štít a pavézu a povstaň mi na pomoc!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Vezmi kopí a uzavři cestu ke střetu s mými pronásledovateli. Řekni mé duši: Jsem tvá záchrana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Ať se stydí a hanbí ti, kdo usilují o můj život. Ať se stáhnou zpět a zastydí ti, kdo mi chystají zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Budou jako plevy před větrem. To anděl Hospodinův je požene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Ať je jejich cesta temná a kluzká a ať je anděl Hospodinův pronásleduje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Vždyť na mě bezdůvodně nastražili jámu, bezdůvodně vykopali past pro mou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Ať na něj přijde zkáza, aniž to tuší. A do té pasti, kterou nastražil, se lapí sám, ať padne do té zkázy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Ale má duše bude jásat v Hospodinu, bude se veselit z jeho spásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Každá má kost řekne: Hospodine, kdo je jako ty? Vysvobozuješ chudého od mocnějšího, než je sám, chudého a nuzného od uchvatitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Povstávají zlovolní svědkové, kteří se mě vyptávají na věci, které nevím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Odplácejí mi zlem za dobré, aby ⌈ způsobili zármutek mé duši.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'A já měl za oděv žíněné roucho, když byli nemocní! Pokořoval jsem svou duši postem, ale má modlitba se mi vracela do klína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Jednal jsem, jako by mi byli přítelem či bratrem. Naříkal jsem, skláněl se, jako bych truchlil kvůli matce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'A oni se z mého pádu radovali, dávali se dohromady, spojili se proti mně, křiváci, a já to nevěděl. ⌈Utrhali mi a neumlkli.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Posměvači s bezbožnými na mě skřípou zuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Panovníku, jak dlouho se budeš jen dívat? Odvrať mou duši od jejich zkázy, zachraň mou jedinou před mladými lvy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Budu ti vzdávat chválu ve velikém shromáždění, mezi nespočetným lidem tě budu chválit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Ať se nade mnou mí zrádní nepřátelé neradují. Ti, kdo mě bezdůvodně nenávidí, ať nemhouří oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Ti nemluví pokojně! Proti poklidným v zemi vymýšlejí zradu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Otvírají na mě svá ústa a říkají: Cha, cha! ⌈Naše oči to vidí!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Viděl jsi to, Hospodine, nebuď hluchý! Panovníku, nebuď mi vzdálen!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Vzbuď se, procitni k mému soudu, můj Bože a můj Pane, a veď mou při!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, '⌈Zjednej mi právo⌉ podle své spravedlnosti, ⌈Hospodine, můj Bože,⌉ ať se nade mnou neradují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Ať si v srdci neříkají: Cha, ⌈to jsme chtěli!⌉ Ať neříkají: Zhltli jsme ho!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Ať se společně stydí a hanbí ti, kdo se radují z mého trápení! Ať obléknou hanbu a potupu ti, kdo se nade mnou vyvyšují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Ať výskají a radují se ti, kdo si přejí mou spravedlnost! Ať stále říkají: Veliký je Hospodin, jenž dopřává pokoj svému otroku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Můj jazyk bude opakovat tvou spravedlnost, každý den tvou chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Pro vedoucího chval. Žalm Davida, otroka Hospodinova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Výrok přestoupení o ničemovi: V hloubi mého srdce není strach z Boha -- nemá jej před očima,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'protože lichotí sám sobě ve svých očích, a tak ⌈bude shledán vinným, hodným nenávisti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Slova jeho úst jsou zlá a klamná, přestal ⌈chápat, co je správné jednání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Vymýšlí špatnosti i na svém loži; postavil se na nedobré cestě, zlem nepohrdá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Hospodine, až k nebesům sahá tvé milosrdenství a tvá věrnost až k oblakům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Tvá spravedlnost je jako nejvyšší hory, tvé soudy jako ⌈velká hlubina.⌉ Zachraňuješ lidi i zvířata, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, '⌈Jak vzácné je tvé⌉ milosrdenství, Bože! ⌈Synové lidští⌉ hledají útočiště ve stínu tvých křídel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Sytí se tučností tvého domu, napájíš je proudem svých rozkoší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Neboť u tebe je pramen života; díky tvému světlu vidíme světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Vztáhni své milosrdenství na ty, kteří tě znají, a svou spravedlnost na lidi přímého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Kéž na mě nevstoupí noha pyšných a ruka ničemů kéž mě neodežene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, 'Tam padli činitelé nepravosti, jsou sraženi a nemohou povstat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Davidův žalm. Nerozčiluj se kvůli zlovolníkům, nezáviď těm, kdo páchají zvrácenosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'neboť brzy uschnou jako tráva a zvadnou jako zelené býlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Důvěřuj Hospodinu a čiň dobré; přebývej v zemi a pěstuj poctivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Měj rozkoš z Hospodina -- on naplní prosby tvého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, '⌈Uval na Hospodina⌉ svou cestu a důvěřuj mu, on bude jednat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Vyvede tvou spravedlnost jako světlo, tvé právo jako polední jas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Umlkni před Hospodinem a toužebně na něj očekávej. Nerozčiluj se kvůli těm, kterým se na jejich cestě daří, kvůli lidem, kteří kují pikle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Přestaň se hněvat a zanech zloby, nerozčiluj se, ať se nedopustíš zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Protože zlovolníci budou vyhlazeni, ale ti, kdo očekávají na Hospodina, ti obdrží zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Ještě chvilku a ničema už nebude. Zadíváš se na jeho místo a nebude tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Ale pokorní obdrží zemi a budou si užívat množství pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Ničema spravedlivému chystá zlo a skřípe proti němu zuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Panovník se mu ale směje, vždyť vidí, že přichází jeho den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Ničemové tasí meč, napínají luk, aby srazili chudého a nuzného, aby porazili ty, kdo žijí v upřímnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Ale jejich meč jim pronikne do srdce a jejich luk bude rozlámán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Lepší je málo, které má spravedlivý, než bohatství mnoha ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Neboť paže ničemů budou zlomeny, spravedlivé však Hospodin podepírá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Hospodin zná dny bezúhonných, jejich dědictví potrvá navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Ve zlých dobách nebudou zahanbeni a ve dnech hladu budou nasyceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Ničemové ale zahynou; Hospodinovi nepřátelé pominou jak to nejlepší z pastvin, zmizí v dýmu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Ničema si půjčuje, ale nesplácí. Spravedlivý se slitovává a dává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Jím požehnaní obdrží zemi, ale jím zlořečení budou vyhlazeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Hospodin upevňuje kroky muže, oblíbil si jeho cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Když upadne, nebude zavržen, vždyť Hospodin mu podepírá ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Byl jsem mladý a teď jsem starý, ale neviděl jsem spravedlivého, který by byl opuštěn a jehož potomstvo by žebralo o chléb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Každého dne se slitovává a půjčuje a jeho potomstvo je požehnáním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Odvrať se od zlého a čiň dobré, a budeš přebývat navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Neboť Hospodin miluje právo a neopouští své věrné. Navěky je bude střežit. Potomstvo ničemů však bude vyhlazeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Spravedliví obdrží zemi a budou v ní přebývat navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Ústa spravedlivého přemítají o moudrosti a jeho jazyk mluví o právu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'V srdci má zákon svého Boha, jeho kroky nebudou nejisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Ničema pozorně sleduje spravedlivého a hledá, jak by ho usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Hospodin ho nenechá v jeho ruce a až bude souzen, nebude usvědčen z viny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Očekávej na Hospodina a dbej na jeho cestu. On tě vyvýší a obsadíš zemi, až budou ničemové vyhlazeni, uvidíš to!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Viděl jsem ničemu, násilníka, který se rozvaloval jako nepřesazovaná zeleň,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'ale pominul a hle, už není. Hledal jsem ho, ale nebyl nalezen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, '⌈Drž se bezúhonného,⌉ hleď na přímého, vždyť ⌈pokojným lidem⌉ patří budoucnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'ale vzpurníci budou společně zničeni, budoucnost ničemů bude zmařena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Spása spravedlivých je od Hospodina, on je jejich záštitou v čas soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Hospodin jim pomáhá a vytrhuje je, vytrhuje je od ničemů a zachraňuje je, neboť v něm hledají útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Davidův žalm -- k připomínání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Hospodine, nekárej mě ve svém rozhořčení, ve své zlobě mě ne kázni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Tvé šípy mě zasáhly a dolehla na mě tvá ruka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Pro tvé rozhořčení není na mém těle zdravé místo, pro můj hřích není pokoje v mých kostech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'neboť mé viny mi přerostly přes hlavu; ⌈tíží mě jako ohromné břemeno.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Kvůli mé pošetilosti páchnou a hnisají mé rány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Jsem velmi sklíčen a pokořen, celý den chodím v nářku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Mé slabiny jsou zcela zanícené; na mém těle není zdravé místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Jsem otupělý a velmi zkrušen; řvu, ⌈neboť mé srdce sténá.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Panovníku, před tebou jsou všechny mé tužby, mé vzdychání není před tebou skryto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Srdce mi buší, opustila mě síla, ani mé oči už nemají jas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Moji přátelé i druzi kvůli mé ráně poodstupují a moji blízcí stojí opodál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Ti, kdo usilují o můj život, mi chystají past, ti, kdo si žádají mého zla, promlouvají zkázu a celý den přemítají o zradě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Ale já jsem jako hluchý a neslyším, jako němý, který neotvírá ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Ano, jsem jako člověk, který neslyší a v jehož ústech není námitek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Protože čekám na tebe, Hospodine, ty odpověz, Panovníku, můj Bože!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Říkám: Ať se nade mnou neradují! Když mi uklouzne noha, budou se nade mnou vytahovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Vždyť mám blízko k pádu, má bolest je ustavičně se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Proto vyznávám svou vinu a hrozím se svého hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Mých zdatných nepřátel je bezpočtu; mnoho je těch, kdo mě zrádně nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Odplácejí zlem za dobro, protiví se mi za to, že usiluji o dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Neopouštěj mě, Hospodine! Bože můj, nevzdaluj se ode mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, 'Pospěš mi na pomoc, Panovníku, moje spáso!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Pro vedoucího chval, pro Jedútúna. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Řekl jsem: Budu střežit svou cestu, abych nezhřešil jazykem. Budu střežit svá ústa náhubkem, dokud bude přede mnou ničema.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Dočista jsem oněměl, nadobro jsem umlkl, ale má bolest se jen jitřila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Srdce mi v nitru hořelo. ⌈Když jsem tesknil,⌉ plál ve mně oheň. Pak jsem promluvil svým jazykem:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Hospodine, dej mi poznat můj konec a jaký je počet mých dnů, ať si uvědomím, jak jsem pomíjivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Hle, dal jsi mi jen maličko dnů, jako nic je před tebou můj věk; každý člověk, jakkoli pevně stojí, je jen vánek. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Jen jako přelud putuje člověk, hlučí, přestože je jen vánek, shromažďuje, ale neví, kdo to sklidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Nuže, v co budu doufat, Panovníku? Mé očekávání se upíná k tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Vysvoboď mě od všech mých přestoupení, nevystavuj mě posměchu bláznů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Oněměl jsem, neotvírám svá ústa, neboť jsi to způsobil ty!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Odejmi ode mě svou ránu, vždyť hynu od úderů tvé ruky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Když člověka tresty kázníš za vinu, sžíráš jak mol, co je mu drahé. Každý člověk je jen vánek! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Vyslyš, mou modlitbu, Hospodine, naslouchej mému volání o pomoc, nebuď hluchý k mému pláči! Vždyť jsem u tebe jen hostem, příchozím, stejně jako moji otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, 'Odvrať ode mě svůj pohled a já pookřeji, než odejdu a již nebudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Napjatě jsem očekával na Hospodina a on se ke mně sklonil a vyslyšel mé volání o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Vytáhl mě z hlučící jámy, z blátivého bahna a postavil mé nohy na skálu, upevnil mé kroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Do úst mi vložil novou píseň, chválu našemu Bohu. Mnozí to uvidí, pojme je bázeň a budou doufat v Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Blahoslavený je ten muž, ⌈který vkládá své naděje v Hospodina⌉ a ⌈neobrací se k nestvůrám a k těm, kdo se uchylují ke lži.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, '⌈Hospodine, můj Bože,⌉ ty jsi s námi učinil mnoho svých divů a úmyslů; nikdo ⌈ se s tebou nemůže měřit.⌉ Chci je oznamovat a hovořit o nich -- je jich víc, než se dá vypovědět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Obětní hod ani přídavnou oběť jsi nechtěl, ale ⌈prorazil jsi mi uši.⌉ Zápal ani oběť za hřích jsi nežádal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Tu jsem řekl: Hle, přicházím. Ve svitku knihy je o mně psáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, '⌈Oblíbil jsem si⌉ dělat to, co je ti milé, můj Bože. Tvůj zákon je v mém nitru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Zvěstoval jsem spravedlnost ve velikém shromáždění; hle, neomezoval jsem své rty. Hospodine, ty to víš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Tvou spravedlnost jsem neukryl uvnitř svého srdce, mluvil jsem o tvé věrnosti a spáse, nezatajil jsem tvé milosrdenství a tvou pravdu ve velikém shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Hospodine, ty mi neodepřeš své slitování. Kéž mě stále střeží tvé milosrdenství a tvá věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Vždyť mě obklopilo tolik zla, že se nedá sečíst. Dostihly mě mé viny, takže nemohu ani vzhlédnout; je jich víc než vlasů na mé hlavě, ⌈odvaha mě opustila.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, '⌈ Kéž mě, Hospodine, zatoužíš⌉ vysvobodit! Hospodine, pospěš mi na pomoc!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Ať se stydí a hanbí všichni, kteří usilují o mou duši a chtějí ji zničit; ať odtáhnou zpět a jsou zahanbeni ti, kdo mi přejí zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, '⌈Kéž se zhrozí své vlastní hanby⌉ ti, kdo mi říkají: Cha, cha!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Ať se veselí a radují v tobě všichni, kdo tě hledají! Ti, kdo milují tvou spásu, ať říkají stále: Veliký je Hospodin!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, 'Ač jsem chudý a nuzný, Panovník na mě myslí. Tys má pomoc a můj vysvoboditel, můj Bože, neotálej!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Blahoslavený je ten, kdo má porozumění pro slabého, ve zlý den jej Hospodin zachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Hospodin ho bude chránit, zachová ho naživu a ⌈učiní ho na zemi šťastným,⌉ nevydá ho choutkám jeho nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Na posteli nemocných jej Hospodin posilní. V nemoci mu změníš celé lože!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Říkám: Hospodine, smiluj se nade mnou, uzdrav mou duši, neboť jsem proti tobě zhřešil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Moji nepřátelé o mně mluví zle: Kdy zemře? Kdy vymizí jeho jméno?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Pokud se na mě někdo přijde podívat, jeho srdce mluví klam, shromažďuje si špatnosti, pak vyjde ven a vykládá o tom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Všichni, kdo mě nenávidí, si o mně spolu šeptají, vymýšlejí proti mně zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, '⌈Postihlo jej něco ničemného;⌉ když ulehl, již nevstane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'I ⌈můj důvěrný přítel,⌉ jemuž jsem důvěřoval, který jídal můj chléb, ⌈proti mně vyvýšil patu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Hospodine, ty se však nade mnou smiluj a pozdvihni mě, a já jim odplatím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Podle toho poznám, že sis mě oblíbil, že nade mnou nebudou mí nepřátelé hlaholit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Kdežto mě jsi podepřel pro mou bezúhonnost a postavils mě před svou tvář navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, '⌈Požehnán buď Hospodin, Bůh Izraele,⌉ od věků až navěky. Amen i Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Pro vedoucího chval. Meditace -- synové Kórachovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Jako laň dychtí po vodních tocích, tak má duše dychtí po tobě, ó Bože!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Má duše žízní po Bohu, po živém Bohu! Kdy předstoupím, abych se ukázal před Boží tváří?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Slzy jsou mi chlebem ve dne i v noci, když mi každý den říkají: Kde je ten tvůj Bůh?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Na to vzpomínám a vylévám v sobě svou duši, jak jsem chodíval v zástupu a ubíral jsem se do Božího domu za zvuku jásotu a děkovných písní davu slavícího svátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Proč jsi tak skleslá, má duše, proč jsi ⌈ve mně⌉ tak rozrušená? Jen čekej na Boha -- vždyť mu budu znovu vzdávat chválu za ⌈spásu jeho přítomnosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Můj Bože, duše je ve mně tak skleslá, a tak na tebe vzpomínám v jordánské zemi, na Chermónu, na hoře Miseáru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Hlubina volá na hlubinu za zvuku tvých přívalů, převalily se přese mě všechny tvé příboje a tvá vlnobití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Ve dne Hospodin přikazuje svému milosrdenství a v noci je se mnou jeho píseň, modlitba k ⌈Bohu mého života.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Říkám Bohu, své skále: Proč na mě zapomínáš? Proč mám chodit v nářku, utlačován nepřítelem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, '⌈Zkázou pro mé kosti je mi utrhání⌉ mých nepřátel. Každý den mi říkají: Kde je ten tvůj Bůh?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, 'Proč jsi tak skleslá, má duše, proč jsi ve mně tak rozrušená? Jen čekej na Boha -- vždyť mu budu znovu vzdávat chválu za spásu jeho přítomnosti, za svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Zjednej mi právo, Bože, a veď mou při. Vytrhni mě od ⌈nemilosrdných pohanů,⌉ od lidí podlých a zvrácených.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Vždyť ty jsi, Bože, má záštita. Proč jsi mě odvrhl? Proč mám chodit v nářku, utlačován nepřítelem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sešli své světlo a svou pravdu, ty ať mě vedou a přivedou na tvou svatou horu, do tvých příbytků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Přistoupím k Božímu oltáři, k Bohu, své jásavé radosti, a budu ti vzdávat chválu na lyru, Bože, můj Bože!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Proč jsi tak skleslá, má duše, proč jsi ve mně tak rozrušená? Jen čekej na Boha -- vždyť mu budu znovu vzdávat chválu za spásu jeho přítomnosti, za svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Pro vedoucího chval. Synové Kórachovi -- meditace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Bože, na vlastní uši jsme slýchávali, naši otcové nám vyprávěli o skutcích, které jsi vykonal za jejich dnů, za dnů dávnověkých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Ty jsi svou rukou vyhnal pohany a je jsi zasadil, zlomil jsi národy a vyhnal jsi je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Zemi však neobsadili díky svému meči, ⌈nezachránila je jejich paže,⌉ nýbrž tvá pravice, tvá paže a světlo tvé tváře, protože jsi v nich našel zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Ty jsi můj král, ⌈Bože. Přikaž⌉ ⌈vítězství pro Jákoba!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, '⌈S tebou⌉ jsme nabrali na rohy své protivníky, ve tvém jménu jsme pošlapali ⌈ty, kdo proti nám povstali.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Proto se nespoléhám na svůj luk; můj meč mě nezachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Neboť ty jsi nás zachránil před našimi protivníky a zahanbil jsi ty, kdo nás nenáviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Bohem se chlubíme každý den; navěky budeme vzdávat chválu tvému jménu. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Avšak odvrhl jsi nás a vystavil jsi nás hanbě; nevycházíš s naší armádou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Před protivníkem nás obracíš nazpět a ti, kdo nás nenávidí, nás poplenili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Vydáváš nás jak ovce k sežrání a rozptýlil jsi nás mezi pohany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Prodal jsi svůj lid lacino, nepožadoval jsi za něj dobrou cenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Vystavil jsi nás potupě našich sousedů, posměchu a pošklebkům našeho okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Učinil jsi nás pořekadlem mezi pohany, ⌈národy nad námi potřásají hlavou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Každý den mám před sebou svou potupu; ⌈hanba mi zakrývá tvář,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'a to kvůli tomu, kdo mě hanobí a ostouzí, kvůli nepříteli a tomu, kdo se mstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'To vše na nás přišlo, ač jsme na tebe nezapomněli a ⌈tvou smlouvu jsme nezradili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Naše srdce se nestáhlo zpět, naše kroky neuhnuly z tvé stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Přestože jsi nás zdeptal v kraji šakalů a přikryl jsi nás nejhlubší tmou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Pokud bychom zapomněli na jméno svého Boha, pokud bychom vztáhli dlaně k bohu cizímu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'zdali by na to Bůh nepřišel? On přece zná tajnosti srdce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'A přece jsme kvůli tobě denně vražděni, považují nás za ovce na porážku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Vzbuď se, Panovníku, proč spíš? Probuď se a neodvrhni nás navždy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Proč skrýváš svou tvář? Zapomínáš na naše soužení a útisk?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Vždyť naše duše klesla v prach; naše nitro je přitištěno k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, 'Povstaň nám na pomoc, vykup nás pro své milosrdenství!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, '⌈Pro vedoucího chval -- podle „Lilií“.⌉ (Synové Kórachovi -- meditace: Píseň lásky).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, '⌈Mé srdce přetéká dobrým slovem,⌉ přednesu tedy své dílo králi. Můj jazyk je jako rydlo zběhlého písaře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Jsi nejkrásnější ze synů lidských, ze tvých rtů plyne milost. Proto ti Bůh požehnal navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'K boku si připaš meč, hrdino, v nádheře a důstojnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'A ve své důstojnosti uspěj. Vytáhni ve věci pravdy, pokory a spravedlnosti a tvá pravice ať tě učí hrůzu vzbuzující činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, '⌈ Od tvých ostrých šípů budou před tebou padat národy. Šípy proniknou až do srdce⌉ králových nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Tvůj trůn, Bože, trvá navěky a navždy. Žezlo přímosti je žezlo tvého království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Miluješ spravedlnost a nenávidíš ničemnost. Proto tě, Bože, tvůj Bůh pomazal olejem veselí nad tvé druhy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Myrhou, aloe a kasií voní všechna tvá roucha, z paláců ze slonoviny tě obveselují strunné nástroje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Dcery královské jsou mezi tvými nejvzácnějšími, královna v ofírském zlatě zaujímá místo po tvé pravici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Poslyš, dcero, a pohleď, nakloň své ucho. Zapomeň na svůj lid a na dům svého otce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Král touží po tvé kráse, vždyť je to tvůj pán, skláněj se před ním!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Týrská dcera přichází s darem; zámožní lidé ⌈si tě budou předcházet.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Celá v nádheře je královská dcera uvnitř paláce, její plášť je protkávaný zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'V pestře tkaných šatech je uváděna ke králi; za ní k tobě přicházejí i panny, její družičky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Budou provázeny v radosti a jásotu, vstoupí do královského paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Místo otců budeš mít syny; ustanovíš je za knížata po celé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, 'Po všechna pokolení budu připomínat tvé jméno, proto tě budou národy chválit navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Pro vedoucího chval. Synové Kórachovi. Na alamót. Píseň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Bůh je naším útočištěm i silou, ⌈velkou pomocí, kterou nacházíme v souženích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Proto se nebudeme bát, i kdyby se převrátila země a hory se zřítily do ⌈mořských hlubin,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'byť by jeho vody burácely a pěnily, byť by se hory pro jeho zpupnost třásly. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Řeka svým proudem oblažuje Boží město, svaté příbytky Nejvyššího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Bůh je uprostřed něj, nezhroutí se. Bůh mu přijde na pomoc hned za rozbřesku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Národy hlučí, království se otřásají. Vydá svůj hlas a země se rozplývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Hospodin zástupů je s námi, nepřístupným hradem je nám Bůh Jákobův. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Pojďte a pohleďte na Hospodinovy skutky, jakou hroznou spoušť udělal na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Činí přítrž bojům až do končin země, láme luky a přesekává kopí, vozy pálí ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Přestaňte! Uznejte, že já jsem Bůh, vyvýšený nad národy, vyvýšený nad zemí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, 'Hospodin zástupů je s námi, nepřístupným hradem je nám Bůh Jákobův. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Pro vedoucího chval. Synové Kórachovi. Žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Všechny národy, tleskejte v dlaně, hlaholte Bohu s ⌈hlasitým jásotem!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Vždyť Hospodin je Nejvyšší, je hrůzu ⌈vzbuzující král, veliký nad celou zemí!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Podrobuje nám národy, podrobuje národy pod naše nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Vybral pro nás naše dědictví -- pýchu Jákoba, kterého miloval. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Vystoupil Bůh za radostného křiku, vystoupil Hospodin za zvuku beraních rohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Zpívejte žalmy Bohu, pějte, pějte našemu králi, zpívejte žalmy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'neboť Bůh je králem celé země, zpívejte žalmy s porozuměním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Bůh kraluje nad národy, Bůh sedí na svém svatém trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, 'Přední muži národů ⌈se připojili k lidu Boha Abrahamova.⌉ Vždyť Bohu náleží štíty země -- je velmi vyvýšený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Žalmová píseň -- synové Kórachovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Veliký je Hospodin, nejvýš chvályhodný -- ve městě našeho Boha, na své svaté hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Krásně vyvýšená, radost celé země je hora Sijón -- nejzazší sever, město velkého krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Bůh je v jeho palácích; je znám jako nepřístupný hrad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Hle, králové se smluvili, společně přitáhli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'spatřili to a užasli, zděsili se a ⌈v hrůze se rozprchli.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Zachvátilo je tam chvění, bolesti jako rodičku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Východním větrem jsi roztřískal taršíšské lodě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'To, co jsme slýchali, to jsme viděli ve městě Hospodina zástupů, ve městě našeho Boha. Bůh je upevňuje navěky. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Bože, uprostřed tvého chrámu ⌈rozvažujeme o tvém⌉ milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Jak tvé jméno, tak tvá chvála sahá až do končin země. Tvá pravice je plná spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Nad tvými soudy se raduje hora Sijón, jásají nad nimi judské dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Obejděte Sijón, projděte kolem něj, spočtěte jeho věže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, '⌈Všimněte si pozorně⌉ jeho valů, projděte jeho paláce, abyste o tom vyprávěli budoucím pokolením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, 'Protože tento Bůh je naším Bohem navěky a navždy; on nás povede proti smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Pro vedoucího chval. Synové Kórachovi. Žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Slyšte to, všechny národy, naslouchejte, všichni obyvatelé světa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'vy, ⌈synové Adamovi, vy, synové člověka,⌉ jak bohatí, tak nuzní!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Má ústa budou promlouvat moudrost a přemýšlení mého srdce rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, '⌈Nakloním své ucho⌉ k přísloví, při lyře předložím svou hádanku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Proč bych se bál ve zlých dnech, kdy mě obklopuje zvrácenost ⌈mých pronásledovatelů?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Spoléhají na svůj majetek; chlubí se svým velkým bohatstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '⌈ Nikdo nevykoupí ani bratra, člověk Bohu za sebe nedá výkupné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Cena za jeho duši je tak vysoká -- ⌈nikdy na ni nebude mít,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'aby žil navždy a neviděl zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, '⌈Vždyť je zřejmé, že moudří⌉ umírají stejně jako hlupák či tupec; hynou a zanechávají svůj majetek jiným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, '⌈ V jejich nitru je, že jejich domy jsou tu navěky,⌉ jejich příbytky z pokolení do pokolení; svými jmény nazývají pozemky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Ale ani člověk, který je vážený, nepřetrvá. Je podobný zvířatům, která hynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, '⌈Taková je cesta těch, kteří spoléhají⌉ sami na sebe, i ⌈jejich následovníků,⌉ kteří našli zalíbení ⌈v jejich ústech.⌉ Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Do podsvětí směřují jako ovce, smrt je pase, přímí je opanují hned za jitra. Jejich výtvory pohltí podsvětí, daleko od jejich příbytků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Bůh jistě vykoupí mou duši z moci podsvětí -- vždyť mě přijme! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Neboj se, když někdo bohatne, když rozmnožuje slávu svého domu --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'vždyť při své smrti si nevezme nic, jeho sláva za ním nesestoupí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Ačkoliv za svého života své duši dobrořečil -- a když se ti daří dobře, tak tě chválí --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'přijde k pokolení svých otců, kteří již nikdy neuvidí světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, 'Ani vážený člověk to nechápe a je podobný zvířatům, která hynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Žalm Asafův. Bůh, Bůh Hospodin promluvil a volá zemi od východu slunce až po západ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Bůh se zaskvěl ze Sijónu, místa dokonalé krásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Náš Bůh přichází a nebude mlčet. Před ním stravující oheň, kolem něj to hrozně běsní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Povolává nebesa shůry, povolává i zemi, aby soudil svůj lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Shromážděte mi mé věrné, ty, kteří při oběti uzavřeli mou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Nebesa zvěstují jeho spravedlnost, vždyť Bůh je soudce! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Slyš, můj lide, budu mluvit, Izraeli. ⌈Svědčím proti tobě.⌉ Jsem Bůh, tvůj Bůh!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nekárám tě kvůli tvým obětem. I tvé zápaly jsou stále přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Nevezmu si býčka z tvého domu, kozly ze tvých ohrad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Vždyť mi patří všechna lesní zvěř i dobytek na tisíci horách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Vím o každém ⌈horském ptáku,⌉ u mě je i ⌈polní havěť.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Kdybych měl hlad, neřeknu ti to; vždyť mně patří celý svět a vše, co je na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Což jím maso býků? Což piji krev kozlů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Obětuj Bohu oběť díků, plň své sliby Nejvyššímu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Volej mě v den soužení, vytrhnu tě a ty mě budeš oslavovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Ale ničemovi Bůh říká: Proč si odříkáváš má ustanovení? Proč si bereš do úst mou smlouvu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'když nenávidíš kázeň a když jsi má slova hodil za hlavu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Když vidíš zloděje, máš v něm zalíbení a svůj podíl máš s cizoložníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Svá ústa ⌈propůjčuješ zlu⌉ a tvůj jazyk se zaplétá se lstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Posadíš se, mluvíš proti svému bratru, haníš syna své matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Takto jsi jednal a já jsem mlčel. Představoval sis, že jsem jako ty. Kárám tě a předložím ti to před oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Pochopte to, vy, kdo na Boha zapomínáte, abych vás nerozsápal a nebylo by, kdo by vás vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Ten, kdo obětuje oběť díků, ten mě ⌈oslaví. Kdo napraví svou cestu, tomu⌉ ukážu Boží spásu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Když k němu přišel prorok Nátan poté, co David vešel k Bat–šebě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Smiluj se nade mnou, Bože, podle svého milosrdenství! Podle svého hojného slitování vymaž má přestoupení!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Dokonale mě umyj od mého provinění a od mého hříchu mě očisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Já svá přestoupení uznávám, svůj hřích mám před sebou ustavičně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Proti tobě samému jsem zhřešil, udělal jsem to, co je zlé v tvých očích. A tak jsi spravedlivý, když mluvíš, jsi dokonalý, když konáš soud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Hle, byl jsem zplozen v nepravosti, matka mě počala v hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Hle, ty máš zalíbení v ⌈niterné opravdovosti a vskrytu mi dáváš poznat moudrost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Očisti mě od hříchu yzopem, a budu čistý, umyj mě, a budu nad sníh bělejší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Dej, ať uslyším ⌈veselí a radost,⌉ ať se zaradují kosti, kterés zdeptal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, '⌈Skryj svou tvář⌉ před mými hříchy a všechna má provinění vymaž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Stvoř mi čisté srdce, ó Bože! Obnov v mém nitru pevného ducha!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Neodvrhuj mě ⌈od své tváře,⌉ svého svatého Ducha mi neber!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Vrať mi veselí ze své spásy a ⌈upevni ve mně šlechetného ducha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Budu vyučovat vzpurníky tvým cestám a hříšníci se navrátí k tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Uchraň mě před proléváním krve, Bože! Bože, má spáso, můj jazyk jásá nad tvou spravedlností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Panovníku, otevři mé rty, má ústa budou zvěstovat tvou chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Neměl bys zalíbení v oběti, i kdy bych ji předložil; po zápalné oběti netoužíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Oběť Bohu je zkroušený duch. Bože, ty nepohrdneš zkroušeným a pokořeným srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, 'Ve své přízni prokaž dobro Sijónu, vybuduj jeruzalémské hradby!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, 'Pak se ti zalíbí spravedlivé oběti, zápalné oběti i celopaly. Tehdy budou obětovat býčky na tvém oltáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Pro vedoucího chval. Davidův žalm -- meditace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Když přišel Dóeg Edómský a oznámil Saulovi: David přišel do Achímelekova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Proč se chlubíš zlem, ty hrdino? Boží milosrdenství trvá každého dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Tvůj jazyk vymýšlí zkázu, je ostrý jako břitva, páchá záludnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Miluješ zlo více než dobro, klam víc než spravedlivou řeč. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Miluješ každé sžírající slovo, jazyku klamný!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Avšak Bůh tě navždy zničí: Popadne tě, vyrve tě ze stanu a vykoření tě ze země živých. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Spravedliví to uvidí a pojme je bázeň. Ale jemu se budou vysmívat:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Hle, muž, který nepokládal Boha za svou záštitu. Spoléhal na své velké bohatství, nabýval moci skrze rozsévání zkázy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, 'Ale já jsem jako zelená oliva v Božím domě; spoléhám na Boží milosrdenství navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, 'Navěky ti budu vzdávat chválu, protože jsi jednal. A budu vzhlížet ke tvému jménu, neboť je dobré vůči tvým věrným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Pro vedoucího chval -- na machalat. Davidův žalm k meditaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Blázen si v srdci říká: Bůh není. Lidé jednají zvráceně, páchají špatnosti. Není, kdo by činil dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Bůh shlíží z nebes na lidské syny, aby viděl, zda je někdo rozumný, zda někdo hledá Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Všichni společně odpadli, jsou zvrácení. Není, kdo by činil dobro, není ani jednoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Opravdu tomu nerozumějí činitelé nepravosti, kteří pojídají můj lid, jako by jedli chléb, a kteří k Bohu nevolají?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Jednou se budou třást strachem, jaký ještě nebyl. Vždyť Bůh rozmetal kosti těch, kdo tě obléhali. Zahanbils je, neboť Bůh je zavrhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, 'Kéž by byla Izraeli dána ze Sijónu spása! Až Bůh změní úděl svého lidu, bude Jákob jásat, Izrael se bude radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Pro vedoucího chval. Na strunné nástroje. Žalm Davidův k meditaci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'když přišli Zífejci a řekli Saulovi: Což se David neskrývá u nás?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Bože, pro své jméno mě zachraň, svou silou mi zjednej právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Bože, vyslyš mou modlitbu; naslouchej slovům mých úst!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Neboť proti mně povstali cizáci, násilníci usilují o můj život! Ti s Bohem nepočítají! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Hle, Bůh je mým pomocníkem. Panovník je s těmi, kdo podpírají mou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Obrať zlo na ty, kdo na mě číhají. Svou pravdou je znič!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, 'Rád ti budu obětovat, budu vzdávat chválu tvému jménu, Hospodine, protože je dobré --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, 'vždyť jsi mě vysvobodil ze všeho soužení a mé oko hledělo na nepřátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Pro vedoucího chval. Na strunné nástroje. Davidův žalm k meditaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Naslouchej, Bože, mé modlitbě, nebuď lhostejný k mé úpěnlivé prosbě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Věnuj mi pozornost a odpověz mi -- motám se ve svém reptání a střečkuji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, '⌈když slyším nepřítele, když na mě tlačí ničema;⌉ házejí na mě nepravosti a hněvivě mě osočují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Srdce se ve mně svírá, dolehly na mě hrůzy smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Přepadá mě strach a chvění a zachvacuje mě hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Řeknu: ⌈Kéž bych měl⌉ holubičí křídla -- odletěl bych a měl bych klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Ano, uletěl bych daleko a zůstal bych v pustině. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Spěchal bych do bezpečí před poryvy vichru, před bouří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Uveď je ve zmatek, Panovníku, rozděl jim jazyky -- ve městě totiž vidím násilí a svár.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Dnem i nocí obcházejí po hradbách, je v něm nepravost a trápení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Zkáza je uprostřed něj, z jeho ulic se nevzdalují útisk a zrada.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Netupí mě nepřítel; to bych snesl. Nevyvyšuje se nade mnou ten, kdo mě nenávidí; před tím bych se ukryl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Ale jsi to ty, člověk jako já, můj přítel, můj známý,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 's nímž mě pojila sladká důvěrnost! V průvodu jsme chodívali do domu Božího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Ať je převeze smrt, ať zaživa sestoupí do podsvětí, protože ⌈se v jejich nitru uhostilo⌉ zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Já ale budu volat k Bohu a Hospodin mě zachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Večer, ráno i v poledne k němu budu promlouvat, budu úpět a on mé volání vyslyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'V pokoji vykoupí mou duši ⌈z bojů proti mně,⌉ přestože je jich proti mně tolik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Bůh, který trůní odedávna, slyší a odpoví jim -- Sela -- těm, kteří se ne chtějí změnit a Boha se nebojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Vztáhne ruku proti pokojnému a znesvětí jeho smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, '⌈ Z úst mu vycházejí lahůdky,⌉ ale v srdci má boj. Jeho slova jsou měkčí než olej, jsou to ale vytasené meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Uvrhni svou starost na Hospodina, on se o tebe postará. Nedopustí, aby se spravedlivý navěky zhroutil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, 'Ty je, Bože, svrhneš do jámy zkázy. Člověk krvelačný a podlý ⌈se nedožije ani poloviny⌉ svých dnů. Já však doufám v tebe!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Pro vedoucího chval. Podle „Holubice utichlé v dáli“. Davidův pamětní zápis, když ho v Gatu lapili Pelištejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Smiluj se nade mnou, Bože, neboť po mně šlape člověk; celý den mě utlačují bojovníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Ti, kdo na mě číhají, celý den po mně šlapou. Mnoho je těch, kdo proti mně bojují z výšin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'V den, kdy bych se měl bát, já doufám v tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'V Boha, jehož slovo chválím, v Boha doufám. Nebudu se bát -- co mi může udělat tělo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Celý den překrucují má slova; proti mně jsou všechny jejich plány ke zlému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Srocují se, číhají na mě, střeží mé kroky, jak by si počíhali na mou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Při vší té nepravosti budou v bezpečí? Bože, sraz takové národy v hněvu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Mé bloudění máš zapsáno; ulož do měchu mé slzy -- což nejsou ve tvých záznamech?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Jednou se mí nepřátelé obrátí zpět, v den kdy budu volat. To vím, že Bůh je se mnou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'V Boha, jehož slovo chválím, v Hospodina, jehož slovo chválím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'v Boha doufám. Nebudu se bát -- co mi může udělat člověk?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, '⌈Jsem vázán, Bože, splnit sliby tobě dané,⌉ odplatím se ti oběťmi díků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, 'neboť jsi vysvobodil mou duši ze smrti. Což jsi ne vytrhl mé nohy od klopýtnutí, abych chodil před Bohem ve světle živých?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Pro vedoucího chval. Podle: „Nevyhlazuj!“Davidův pamětní zápis, když utekl před Saulem do jeskyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Smiluj se nade mnou, Bože, smiluj se nade mnou! Vždyť má duše hledá útočiště v tobě! Hledám útočiště ve stínu tvých křídel, dokud nepomine zkáza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Volám k Bohu nejvyššímu, k Bohu, který jedná v můj prospěch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Pošle z nebe a zachrání mě, zahanbí ty, kdo po mně šlapou. Sela. Bůh pošle své milosrdenství a svou věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Má duše je uprostřed lvů. Uléhám s běsnícími -- s lidmi, jejichž zuby jsou kopí a šípy a jejichž jazyk je ostrý meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Vyvyš se nad nebesa, Bože! Tvá sláva ať je po vší zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Nastražili síť mým krokům, což sklíčilo mou duši. Vykopali přede mnou jámu, padli do ní. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mé srdce je pevné, Bože, mé srdce je pevné, budu zpívat a pět žalmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Probuď se, má slávo, probuď se, harfo a lyro, ať jitřenku vzbudím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, '⌈Budu ti vzdávat chválu⌉ mezi lidmi, Panovníku, budu tě opěvovat mezi národy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'protože tvé milosrdenství je velké, sahá až k nebesům, a až do oblak tvá věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, 'Vyvyš se nad nebesa, Bože! Tvá sláva je po vší zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Pro vedoucího chval. Podle: „Nevyhlazuj!“Davidův pamětní zápis.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Bohové, opravdu vyhlašujete spravedlnost? ⌈Synové lidští,⌉ soudíte upřímně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Kdepak! Jednáte v zemi podle svého zvráceného srdce; činíte cestu násilí svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Ničemové se odcizili již z matčina lůna; bloudili od početí ⌈ a mluvili lež.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Jejich jed je jako jed hada, jsou jako hluchá zmije, jež si zacpává uši,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'která neuslyší hlas zaříkávače, zaklínače zkušeného v zaklínání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Bože, vylámej jim zuby v ústech! Vyraz tesáky těch mladých lvů, Hospodine!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Ať se rozplynou jako voda, která se ztrácí. Napnou–li luk, ať mají šípy tupé!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Kéž se odplazí jako slizký hlemýžď; jako potracený plod ženy kéž neuzří slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Dříve než pochopí, že jejich trny jsou jako živý bodlák, kéž jsou odváti jakoby rozlícením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Spravedlivý se bude radovat, neboť uzří pomstu; umyje si nohy v krvi ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, 'Člověk řekne: Ano, spravedlivý má ovoce. Ano, existuje Bůh, který soudí na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Pro vedoucího chval. Podle: „Nevyhlazuj!“Davidův pamětní zápis, když Saul poslal střežit dům, aby jej usmrtili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Vysvoboď mě od mých nepřátel, ⌈můj Bože!⌉ Před těmi, kdo proti mně povstávají, mě uveď do bezpečí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Vysvoboď mě od činitelů nepravosti, zachraň mě před lidmi prolévajícími krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Hle, číhají na mou duši, mocní se srocují proti mně, ne však kvůli mému přestoupení, ani kvůli mému hříchu, Hospodine!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, '⌈Neprovinil jsem se, a přece se sbíhají⌉ a chystají. Probuď se, vyjdi mi vstříc a pohleď!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Ty, Hospodine, Bože zástupů, ⌈Bože Izraele,⌉ procitni a navštiv všechny ty pohany, neměj slitování s těmi věrolomníky! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'K večeru se vracejí, vyjí jako psi a krouží kolem města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Hle, ⌈teče jim z huby,⌉ na jejich rtech jsou meče -- prý: Kdo to slyší?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Ty se jim však, Hospodine, směješ, všechny národy jsou ti k smíchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Má sílo, budu tě vyhlížet, vždyť Bůh je můj nepřístupný hrad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Můj milosrdný Bůh mě předchází; Bůh mi ukáže ty, kdo na mě číhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Nepobíjej je, aby můj lid nezapomněl; svou silou je rozežeň, svrhni je, Panovníku, štíte náš!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, '⌈ Ty hříchy jejich úst! Ta slova jejich rtů!⌉ Ale budou polapeni ve své pýše, za ⌈proklínání a za klamání, které vypouštěli z úst.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Ukonči to v rozlícení! Ukonči to a oni už nebudou. Pak poznají, že Bůh panuje v Jákobovi, a až do končin země! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'K večeru se vracejí, vyjí jako psi a krouží kolem města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Potácejí se, aby se nažrali, a vrčí, když se nenasytí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Ale já budu zpívat o tvé síle a z jitra budu jásat nad tvým milosrdenstvím. Vždyť jsi mi nepřístupným hradem, jsi mi útočištěm v den soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, 'Má sílo, budu tě opěvovat, neboť Bůh je můj nepřístupný hrad, můj milosrdný Bůh! ...');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Pro vedoucího chval. Podle „Lilie svědectví“. Davidův pamětní zápis -- k poučení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Když válčil s Aramejci z Dvojříčí a s Aramejci ze Sóby. Když se tehdy Jóab vrátil, pobil Edómce v Solném údolí, dvanáct tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Bože, odvrhls nás, poničils nás, hněval ses; navrať se k nám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Otřásls zemí a rozpoltils ji. Uzdrav ⌈ji ze zkázy,⌉ vždyť se hroutí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Ukázals svému lidu přísnost, dals nám pít vína, až vrávoráme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Uložils těm, kdo se tě bojí, aby vyzdvihli korouhev před lukem. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Aby byli vysvobozeni ti, které miluješ, zachraň nás svou pravicí, odpověz nám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Bůh promluvil ve své svatyni: Budu jásat, rozdělím Šekem, rozměřím údolí Sukót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Můj je Gileád, můj je i Manases, Efrajim je přilba mé hlavy a Juda můj palcát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moáb je mé umyvadlo, na Edóm hodím svůj sandál. Jen proti mně, Pelišteo, křič!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Kdo mě přivede do opevněného města? Kdo mě dovedl do Edómu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Zdali ne ty, Bože? Odvrhls nás, Bože, a nevycházíš s naší armádou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, 'Zajisti nám pomoc proti protivníkům, vždyť lidská záchrana je klamná!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, 'S Bohem si budeme počínat udatně, on pošlape naše protivníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Pro vedoucího chval. Na strunné nástroje. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Slyš, Bože, můj nářek, věnuj pozornost mé modlitbě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Se zemdleným srdcem k tobě volám z konce světa: Doveď mě na skálu, která je vyšší než já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Jsi mým útočištěm, pevnou věží před nepřítelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Budu navěky přebývat ve tvém stanu, mám útočiště v úkrytu tvých křídel. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Ty jsi, Bože, slyšel mé sliby. Dal jsi mi do vlastnictví ty, kdo se bojí tvého jména.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Přidávej dny králi, kéž jsou jeho léta z pokolení do pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Kéž navěky přebývá před Boží tváří. Připrav milosrdenství a věrnost, ať ho střeží!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, 'Tak budu neustále opěvovat tvé jméno, den co den tím budu plnit své sliby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Pro vedoucího chval, pro Jedútúna. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, '⌈Jen u Boha je utišení mé duše;⌉ od něj pochází má spása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Jen on je má skála a spása, můj nepřístupný hrad, nikdy se nepohnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Až dokdy budete napadat člověka? Z vás všech jde smrt jak z bortící se stěny, jak z padající zdi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Pořád se radí, jak ho připravit o čest. Oblíbili si lež, svými ústy žehnají, avšak v nitru proklínají. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Jen se ztiš před Bohem, má duše, vždyť od něj je má naděje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Jen on je má skála a spása, můj nepřístupný hrad -- nepohnu se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'V Bohu je má spása a sláva, on je má pevná skála -- v Bohu mám útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Lidé, doufejte v něj v každý čas, vylévejte před ním své srdce -- Bůh je naše útočiště. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Synové Adamovi jsou jen vánek, synové lidští jen zdání. Na misce vah stoupají vzhůru, dohromady jsou lehčí než vánek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Nespoléhejte na útlak a na loupení, nestaňte se marností! I kdyby majetku přibývalo, nepřikládejte k tomu srdce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Bůh promluvil jednou a já jsem slyšel toto dvojí: že Bohu patří moc,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, '(a tvé je, Panovníku, i milosrdenství) a že odplatíš každému podle jeho skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Davidův žalm, když byl v Judské pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Bože, ty jsi můj Bůh! Usilovně tě hledám, má duše po tobě žízní, mé tělo po tobě touží ve vyprahlé, vyschlé, bezvodé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Proto tě vyhlížím ve svatyni -- chci hledět na tvou moc i slávu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'neboť tvé milosrdenství je lepší než život. Mé rty tě budou oslavovat --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'tak ti budu dobrořečit po celý svůj život, ve tvém jménu budu pozvedat dlaně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Má duše se sytí tukem, tučnou stravou. A mé rty? Radostným křikem tě chválí má ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Když si tě připomínám na svém loži, o tobě rozjímám za nočních hlídek,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'jak jsi mi býval ku pomoci. Budu jásat ve stínu tvých křídel;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'má duše přilnula k tobě. Podpírá mě tvá pravice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'A ti, kteří usilují o zkázu mé duše, se dostanou do útrob země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Budou vydáni pod meč, stanou se kořistí lišek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, 'Ale král se bude radovat v Bohu; každý, kdo při něm přísahá, se bude chlubit, ale ústa mluvící lež budou zacpána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Slyš, Bože, můj hlas, ⌈když naříkám.⌉ Ochraň můj život před hrůzou z nepřítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Skryj mě před piklemi zlovolníků, před srocením činitelů nepravosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'kteří si nabrousili jazyky jak meče, napjali své šípy jedovatých slov,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'aby z úkrytů stříleli na bezúhonného. Náhle na něj vystřelí a ničeho se nebojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Utvrzují se ve zlé věci, počítají, že skryjí své léčky, říkají: Kdo nás vidí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Obmýšlejí zvrácenosti: Přivedli jsme k dokonalosti vypracovaný plán. Nitro člověka i jeho srdce je hlubší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Bůh však na ně vystřelí šíp a náhle budou porážka sama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Jejich vlastní jazyk je přivede k pádu, vyhne se jim každý, kdo je uvidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Všechny lidi pojme bázeň, budou dosvědčovat Boží skutek a porozumí jeho jednání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, 'Spravedlivý se bude radovat v Hospodinu a bude v něm mít útočiště. Všichni lidé přímého srdce ho budou chválit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Pro vedoucího chval. Davidův žalm, píseň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, '⌈K tobě směřuje tichá chvála,⌉ Bože na Sijónu, tobě splníme slib.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'K tobě, jenž vyslýcháš modlitby, přichází veškeré tvorstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, '⌈ Naše hříšné záležitosti nás přemohly,⌉ ty nás však zprostíš přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Blahoslavený je ten, koho vyvolíš a komu dovolíš, aby přebýval na tvých nádvořích. Sytíme se dobrem tvého domu, tvého svatého chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Ve své spravedlnosti k nám promlouváš činy vzbuzujícími hrůzu, Bože, naše spáso, naděje všech končin země i mořských dálav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Svou mocí jsi upevnil hory, opásal ses udatností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Tišíš hukot moří, hukot jeho vln, stejně jako halas národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Obyvatele končin jímá bázeň z tvých znamení; přivádíš vše k jásotu od samého jitra až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Navštěvuješ zemi, ⌈zahrnuješ ji hojností,⌉ činíš ji velmi bohatou. Boží proud je plný vody. Připravuješ obilí, protože jsi to tak určil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Napájíš její brázdy, urovnáváš její hroudy, zvláčňuješ ji hojnými dešti, žehnáš tomu, co na ní vzchází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Korunuješ rok svou dobrotou a tvé šlépěje přetékají tukem --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'ten kane i na stepní pastviny. I návrší se přepásávají jásotem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, 'Lučiny se oděly stády, údolí jsou pokryta obilím, výskají a prozpěvují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Pro vedoucího chval. Žalmová píseň. Hlahol Bohu, celá země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Opěvujte slávu jeho jména, ⌈učiňte jeho chválu slavnou!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Řekněte Bohu: Jakou hrůzu vzbuzují tvé skutky! Pro tvou velkou sílu ti lichotí tví nepřátelé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Ať se ti klaní celá země, ať tě opěvuje, ať opěvuje tvé jméno! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Pojďte a pohleďte na Boží skutky, na hrůzu vzbuzující činy, jež se týkají lidských synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Moře proměnil v souš, řeku přešli suchou nohou. Tehdy jsme se v něm radovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Navěky vládne svou udatností. Svým zrakem sleduje národy, vzpurníci ať se nepozdvihují! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Dobrořečte, národy, našemu Bohu, hlasitě rozhlašujte jeho chválu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, '⌈On zachoval⌉ naši duši při životě a nedovolil, aby naše nohy uklouzly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Ano, zkoušel jsi nás, Bože, přečišťoval jsi nás jako zlatník stříbro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Zavedls nás do lovecké sítě, vložils na naše bedra těžké břemeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Nechals nám lidi jezdit po hlavě, prošli jsme ohněm i vodou, ale vyvedls nás do hojnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Vstoupím do tvého domu se zápalnými oběťmi, splním ti své sliby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'jež vyslovily mé rty, jež vyřkla má ústa, když jsem byl v tísni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'K zápalným obětem ti přinesu tučné kusy, s kadidlem beranů připravím skot i kozly. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Pojďte, slyšte! Všem bojícím se Boha budu vypravovat, co učinil mé duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Volával jsem k němu svými ústy, ⌈na jazyku jsem měl⌉ jeho chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Kdybych viděl ve svém srdci nepravost, Panovník by mě nevyslyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Avšak Bůh slyšel, věnoval pozornost hlasu mé modlitby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Požehnaný Bůh, který nezamítl mou modlitbu a neodňal mi své milosrdenství!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Pro vedoucího chval. Na strunné nástroje. Žalm. Píseň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Kéž je nám Bůh milostiv a kéž nám žehná, kéž nad námi rozjasní svou tvář -- Sela --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'aby byla na zemi známa tvá cesta a mezi všemi národy tvá spása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Bože, kéž ti lidé vzdají chválu, kéž ti vzdají chválu všichni lidé!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Kéž se národy radují a jásají, neboť soudíš národy podle práva. Ty vodíš národy země. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Bože, kéž ti lidé vzdají chválu, kéž ti vzdají chválu všichni lidé!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Země vydala úrodu -- Bůh, náš Bůh, nám žehná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, 'Ano, Bůh nám žehná. Kéž se ho bojí všechny končiny země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Pro vedoucího chval. Davidův žalm. Píseň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Povstane Bůh a jeho nepřátelé se rozprchnou, ti, kdo ho nenávidí, před ním utečou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Odvaneš je jako pomíjivý dým. Jako taje vosk před ohněm, tak zhynou ničemové před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Avšak spravedliví se budou radovat a veselit před Bohem, budou radostně jásat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Zpívejte Bohu, opěvujte jeho jméno! Navršte cestu tomu, kdo jede pustinami! Hospodin je jeho jméno, jásejte před ním!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Bůh ve svém svatém příbytku je otcem sirotkům a ochráncem vdov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Bůh usazuje osamělé v domech a vězně přivádí k blahobytu. Ovšem vzpurníci zůstanou ve vyprahlé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Bože, když jsi táhl před svým lidem, když jsi kráčel pustou krajinou -- Sela --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'třásla se země a z nebes kanulo před Bohem -- tím ze Sínaje -- před Bohem, ⌈Bohem Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Vydatnými dešti jsi skrápěl, Bože, své dědictví; a když bylo vysíleno, tys je posiloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Tvé houfy se v něm usadily. Bože, ve své dobrotě ses postaral o chudého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Panovník pronáší výrok. Zvěstuje jej veliký zástup žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Králové se svými zástupy prchali, prchali ... a domácnosti si dělily kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Což budete ležet mezi ohradami? Křídla holubice jsou pokrytá stříbrem a jejich perutě zelenkavým zlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Když v něm Všemohoucí rozptýlil ty krále, na Salmónu sněžilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Hora Bášan je hora Boží? Hora Bášan, hora strmých štítů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Hory strmých štítů, proč ⌈závistivě hledíte na ⌉ horu, kterou si Bůh oblíbil, aby tam přebýval? Hospodin se tam usídlil natrvalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Božích vozů jsou desetitisíce, tisíce tisíců. Panovník je na nich -- ve svatosti jako na Sínaji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Vystoupils na výšinu, vedl jsi zajatce, přijals dary v podobě lidí, dokonce i vzpurníků. Vystoupils, abys tam přebýval, Hospodine Bože.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Požehnán buď Panovník, den ze dne ⌈nás nosí jako břímě;⌉ Bůh je naše spása. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Tento Bůh je nám Bohem, který vytrhuje. Hospodin je Pánem i končin smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Bůh jistě srazí hlavu svých nepřátel, vlasaté temeno ⌈těm, kdo se⌉ brodí ve svých vinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Panovník praví: Vyvedu své z Bášanu, vyvedu je i z hlubin moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Proto je tvá noha srazí v krvi, i jazyk tvých psů bude mít z nepřátel svůj podíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Viděli tvůj průvod, Bože, průvody mého Boha, mého krále, do svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Vepředu šli zpěváci, vzadu hudebníci, uprostřed dívky ⌈s bubínky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Vy z pramene izraelského, dobrořečte Bohu Hospodinu ve shromážděních!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Je tam malý Benjamín, který panoval, dále velitelé judští se svými oddíly, velitelé Zabulóna a Neftalího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, '⌈Tvůj Bůh ti přikázal, abys byl silný.⌉ Potvrď, Bože, to, co pro nás děláš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'ze svého chrámu nad Jeruzalémem. Tobě budou králové přinášet dary.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Okřikni zvěř v rákosí, stádo býků mezi telaty, národy, které se snižují kvůli kousku stříbra, rozpraš národy, které mají zálibu v boji!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Přijdou vyslanci z Egypta, Kúš vztáhne ruce k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Království země, zpívejte Bohu! Opěvujte Panovníka -- Sela --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'jezdícího po nebesích, po nebi dávnověkém. Hle, vydává hlas, hlas přesilný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Předejte Bohu moc! Jeho velebnost je nad Izraelem a jeho moc sahá k oblakům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, 'Bože, ze svých svatých míst vzbuzuješ hrůzu. Bůh Izraele, on dává lidu sílu a moc. Bůh buď požehnán!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Pro vedoucího chval -- podle „Lilií“. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Zachraň mě, Bože, vody mi pronikly až k duši!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Topím se v hlubokém bahně a pevného místa není! Klesám do vodních hlubin, strhává mě proud!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Jsem vysílen voláním, hrdlo mám ochraptělé; oči mi slábnou, jak vyhlížím svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Těch, kdo mě bezdůvodně nenávidí, je víc než vlasů na mé hlavě. Je mnoho zrádných nepřátel, kteří mě chtějí zničit. Vracím to, co jsem neuchvátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Bože, ty znáš mou pošetilost; má provinění ti nejsou skryta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Kéž se kvůli mně nestydí ti, kdo na tebe očekávají, Panovníku, Hospodine zástupů, kéž se nehanbí kvůli mně ti, kdo hledají tebe, Bože Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Vždyť kvůli tobě snáším potupu, hanba mi pokryla tvář,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'cizím jsem se stal svým bratřím, cizincem jsem pro syny své matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Neboť mě strávila horlivost pro tvůj dům, padla na mě potupa těch, kdo tupí tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'V postu jsem si vyplakal duši, i to mi bylo ku potupě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Vzal jsem si za oděv žíněné roucho a stal jsem se jim pořekadlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Žvaní o mně ti, kdo sedávají v bráně, i písničky pijanů piva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Ale já jdu se svou modlitbou k tobě, Hospodine. Je čas přízně. Bože, ve svém hojném milosrdenství mi odpověz ⌈pravdou své spásy!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Vysvoboď mě z bahna, abych se neutopil! Kéž jsem vysvobozen od těch, kdo mě nenávidí, i z vodních hlubin!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Ať mě neodplaví vodní proud, ať mě nepohltí hlubina a ať se za mnou nezavře jáma!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Odpověz mi, Hospodine, vždyť tvé milosrdenství je dobré! Podle svého hojného slitování na mě shlédni!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Neskrývej svou tvář před svým otrokem, neboť je mi úzko. Rychle mi odpověz!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Buď nablízku mé duši, ujmi se jí, kvůli mým nepřátelům mě vykup!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Ty víš, jak mě tupí, haní a ostouzejí; máš před sebou všechny mé nepřátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Potupa mi láme srdce, jsem ochromen. ⌈Doufal jsem v soucit, leč nebylo ho, v utěšitele,⌉ avšak nenašel jsem je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Do jídla mi dali žluč a na žízeň mě napájeli octem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Kéž se jim stůl před nimi stane pastí, kéž je léčkou těm, kdo jsou v pohodě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Ať se jim zatmějí oči, aby neviděli, kéž se jim stále třesou bedra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Vylej na ně své rozhořčení, kéž je dostihne tvůj planoucí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Jejich hradiště nechť je zpustošeno a v jejich stanech ať nikdo nebydlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Protože pronásledují toho, kterého ty jsi bil, a ⌈berou si do úst⌉ bolest tebou raněných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Sečti jejich viny! Kéž nevstoupí do tvé spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Kéž jsou vymazáni z knihy živých a nejsou zapsáni mezi spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Já jsem nuzný a rozbolavělý, ale tvá spása, Bože, je mi bezpečím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Zpěvem budu chválit Boží jméno, budu ho velebit písní díků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'To bude Hospodinu milejší než býk, než býček s rohy a paznehty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Uvidí to pokorní a budou se radovat. Vy, kdo hledáte Boha, ⌈vaše srdce bude žít!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Vždyť Hospodin chudé slyší a svými vězni nepohrdá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Chvalte jej nebesa i země, moře a vše, co se v nich hýbe!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Neboť Bůh zachrání Sijón a vybuduje judská města; usadí se tam a obsadí jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, 'Dostane ho do dědictví potomstvo jeho otroků. Budou v něm bydlet ti, kdo milují jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Pro vedoucího chval. Davidův žalm -- k připomínání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Bože, vysvoboď mě! Hospodine, pospěš mi na pomoc!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Ať se zastydí a hanbí ti, kdo usilují o mou duši; ať odtáhnou zpět a jsou zahanbeni ti, kdo mi přejí zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Ať ustoupí kvůli své hanbě ti, kdo říkají: Cha, cha!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Ať se veselí a radují v tobě všichni, kdo tě hledají. Ti, kdo milují tvou spásu, ať říkají stále: Bůh je veliký!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, 'Jsem ⌈chudý a nuzný;⌉ Bože, pospěš ke mně! Tys má pomoc, můj vysvoboditel. Hospodine, neotálej!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'V tobě, Hospodine, hledám útočiště, kéž nejsem nikdy zahanben!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Ve své spravedlnosti mě vysvoboď a vytrhni! Nakloň ke mně své ucho a zachraň mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Buď mi skalním příbytkem, ⌈kam budu stále přicházet. Přikázal jsi, abych byl zachráněn,⌉ neboť jsi má skála a má tvrz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, '⌈Bože můj,⌉ vytrhni mě z moci ničemy, z rukou bídáka a surovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Tys má naděje, Panovníku Hospodine; od mládí mám k tobě důvěru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'O tebe se opírám od mateřského lůna; od života matky sis mě oddělil. Budu tě ustavičně chválit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Mnohým jsem byl za znamení, ale tys byl mé ⌈pevné útočiště.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Má ústa jsou plná tvé chvály, celý den tě oslavuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Nezamítej mě v čas stáří; když končí mé síly, neopouštěj mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Vždyť nepřátelé mluví proti mně, střeží mou duši, radí se spolu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'a říkají: Bůh ho opustil. Pronásledujte ho a chyťte ho, není, kdo by ho vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Bože, nevzdaluj se ode mě; Bože můj, pospěš mi na pomoc!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Ať se stydí, ať pominou ti, kdo obviňují mou duši. Potupa a hanba ať přikryje ty, kdo usilují o mé zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Ale já budu vytrvale čekat a stále více tě budu nade vše chválit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Má ústa vyprávějí o tvé spravedlnosti, celý den hovoří o tvé spáse -- vždyť ji nedokážu vypovědět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, '⌈Přistoupím k⌉ mocným činům Panovníka Hospodina. Tvoji spravedlnost, jen tvoji, budu připomínat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Bože, vyučoval jsi mě od mého mládí, doposud zvěstuji tvé divy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Bože, neopouštěj mě ani ve stáří, v šedinách, dokud neoznámím tvou moc své generaci a tvé mocné činy všem, kteří přijdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Tvá spravedlnost, Bože, sahá až k výšinám. To, cos udělal, je velké; Bože, kdo je jako ty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Dals mi spatřit mnohá a zlá soužení. Vracíš mě k životu a znovu mě vyvádíš z hlubin země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Zvyšuješ mou velikost a znovu mě potěšuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'I já tě budu chválit při harfě, tvou věrnost, můj Bože. Budu tě opěvovat při lyře, Svatý Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Mé rty budou jásat, když tě budu opěvovat, i má duše, kterou jsi vykoupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'I můj jazyk ⌈si bude opakovat denně⌉ o tvé spravedlnosti, neboť ti, kdo usilovali o mé zlo, byli zahanbeni a museli se stydět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Šalomounův. Bože, dej své soudy králi a svou spravedlnost královskému synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Pak bude soudit tvůj lid spravedlivě a tvé chudé podle práva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Hory přinesou lidu pokoj; i pahorky ve spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Bude soudit chudé z lidu, bude spásou synům nuzného -- utlačovatele však srazí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, '⌈Budou se tě bát,⌉ ⌈dokud bude slunce⌉ i ⌈dokud bude ⌉ měsíc, ⌈ po všechna pokolení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Sestoupí jak déšť na posečenou louku, jako přeháňky skrápějící zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'V jeho dnech rozkvete spravedlivý a bude hojný pokoj, dokud ne přestane měsíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Bude panovat od moře k moři, od řeky až do končin země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Skloní se před ním obyvatelé pouště a jeho nepřátelé budou lízat prach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Králové Taršíše i ostrovů budou přinášet dary, králové Šeby a Seby budou odvádět tribut.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Budou se mu klanět všichni králové, všechny národy mu budou sloužit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'neboť vysvobodí nuzného, když volá, chudého, který nemá pomocníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Slituje se nad chudým a nuzným a duše nuzných zachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Vykoupí jejich duše z útisku a od násilí, jejich krev je v jeho očích vzácná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Kéž žije! Kéž se mu dostane z šebejského zlata, kéž se za něj stále modlí a každý den mu dobrořečí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Na zemi bude hojnost obilí, na vrcholcích hor se budou jako Libanon vlnit jeho plody a lidé z města pokvetou jako zemská zeleň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Jeho jméno bude trvat navěky; jeho jméno poroste, dokud bude slunce, budou si jím žehnat, všechny národy je budou blahoslavit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Požehnán buď Bůh Hospodin, Bůh Izraele, jenom on koná divy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Ať je navěky požehnáno jeho slavné jméno a celá země ať je plná jeho slávy. Amen i Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Končí modlitby Davida, syna Jišajova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Žalm Asafův. Jak je Bůh dobrý k Izraeli, k lidem čistého srdce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ale já ... mé nohy málem uklouzly, mé kroky téměř klopýtly,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'neboť jsem záviděl namyšleným, když jsem viděl, ⌈jak se daří ničemům.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Vždyť nejsou spoutáni, aby směřovali k smrti, jejich tělo je tučné,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'lidské trápení se jich netýká, nebývají postiženi jako ostatní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'a tak je pýcha jejich náhrdelníkem; násilí je halí jako oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Jejich oči vystupují z tuku, ukazuje se smýšlení jejich srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Posmívají se, mluví ve zlém, ve své povýšenosti promlouvají o útlaku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Svými ústy směřují proti nebesům a jejich jazyk prochází zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'A tak se jejich lid obrací sem a vybryndá se jim spousta vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Říkají: Což se to Bůh dozví? Což to Nejvyšší pozná?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Hle, takoví jsou ničemové. Pořád bezstarostně rozmnožují majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Jistě, zbytečně jsem udržoval své srdce v čistotě a umýval dlaně v nevinnosti!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Denně dostávám rány -- a po ránu pokárání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Kdybych řekl: Budu mluvit jako oni, byl bych nevěrný ⌈pokolení tvých synů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Když jsem přemýšlel, jak to pochopit, ⌈připadalo mi to obtížné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Až když jsem vstoupil do Božích svatyní, pochopil jsem jejich konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Ano, postavíš je na kluzká místa, necháš je padnout do klamu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Jaký děs vyvolají, když náhle zmizí, zahynou hrůzou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Panovníku, až se vzbudíš, pohrdneš jejich přeludem jako snem po procitnutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Když bylo mé srdce zahořklé, když se jitřilo mé nitro,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'byl jsem tupý a nechápavý, byl jsem před tebou jako hovádko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Nicméně jsem stále u tebe. Uchopils mě za pravici,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'povedeš mě podle svého úradku a pak mě přijmeš do slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Koho mám na nebesích? A jsem–li s tebou, nemám na zemi zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Mé tělo i mé srdce chřadne. Bůh je však navěky skálou mého srdce a mým podílem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Hle, kdo se ti vzdalují, zahynou; zničíš každého, kdo je ti nevěrný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Co se mě týče, Boží blízkost je pro mě dobrá. Učinil jsem si útočiště v Panovníku Hospodinu, abych vyprávěl o celém tvém díle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Meditace -- Asafův žalm. Proč jsi nás, Bože, nadobro odvrhl? Tvůj hněv plane proti ovcím tvého stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Pamatuj na svou obec, kterou si s dávno získal, na svůj dědičný kmen, kterýs vykoupil, na horu Sijón, na níž přebýváš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Obrať své kroky k tomu, co bylo dlouho v troskách, k vší té zkáze, kterou nepřítel způsobil ve svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Tví nepřátelé řvali uprostřed tvého shromáždění, vztyčili tam svá znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Je známo, že jako se zvedají vzhůru sekery v houští,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'tak nyní otloukali tvé řezby -- jak širočinou, tak mlatem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Tvou svatyni podpálili, strhli k zemi, příbytek tvého jména znesvětili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'V srdci si řekli: Vyhubme je všechny! Vypálili všechna Boží shromaždiště v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Svá znamení nevidíme, není již proroka, a ⌈nikdo z nás neví,⌉ dokdy to potrvá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Bože, dokdy se bude protivník rouhat? To bude nepřítel pořád znevažovat tvé jméno?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Proč odvracíš svou ruku? Zvedni pravici z klína a skoncuj s tím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Bůh je můj král odedávna. Uprostřed země koná spásné činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Tys svou mocí rozbouřil moře, roztříštils hlavy drakům na vodách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Tys rozdrtil hlavy livjátána, dals ho za potravu pouštnímu lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Tys ⌈dal vytrysknout⌉ prameni i potoku, tys vysušil i stálé řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Tobě patří den, tobě patří i noc. Tys upevnil světlo i slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Tys ustanovil všechny hranice země, tys utvořil léto i zimu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Vzpomeň si, Hospodine, jak se nepřítel rouhal, jak ten bláznivý lid znevažoval tvé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Nevydávej dravé zvěři život své hrdličky, nezapomeň nikdy na život svých chudých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Shlédni na smlouvu! Vždyť temná místa země se zaplnila příbytky násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Kéž už utlačovaný není znovu ostouzen. Chudý a nuzný ať chválí tvé jméno!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Povstaň, Bože, veď svou při! Připomeň si, že blázen tě denně tupí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Nezapomeň na křik svých nepřátel, na stále rostoucí hukot svých protivníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Pro vedoucího chval, podle: „Nevyhlazuj!“Asafův žalm -- píseň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Vzdáváme ti chválu, Bože, vzdáváme ti chválu! Tvé jméno je blízko, vypráví se o tvých divech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, '⌈Určím čas.⌉ Já budu soudit spravedlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Země i všichni její obyvatelé propadají malomyslnosti. Já rozhoduji o jejích sloupech. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Namyšleným říkám: Nevynášejte se! A ničemům: Nezvedejte rohy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Nezvedejte svoje rohy vzhůru, ne mluvte s drzou šíjí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Nikdo od východu ani od západu ani od hornaté pustiny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'ale Bůh bude soudit. Jednoho ponižuje a druhého povyšuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Hospodin má v ruce kalich s pěnivým vínem plným příměsků. Nalévá z něj a jistě jej i s kalem do dna vypijí všichni ničemové země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ale já budu navěky zvěstovat, budu opěvovat Boha Jákobova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, 'A srazím rohy všem ničemům, rohy spravedlivého však budou pozdviženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Pro vedoucího chval. Na strunné nástroje. Asafův žalm -- píseň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'V Judsku je Bůh znám; v Izraeli je jeho jméno velké.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Jeho stánek je v Šálemu, příbytek má na Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Tam rozlámal ohnivé střely, štít i meč, skoncoval s válkou. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Záříš, ty vznešený, více než hory kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Siláci se stali kořistí, dřímají svým spánkem, a žádní bojovníci nenašli v rukách sílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Bože Jákobův, od tvých hrozeb zemdleli válečné vozy i koně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Ty vzbuzuješ hrůzu. Kdo před tebou obstojí, když se rozhněváš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Z nebes jsi vyhlásil právo. Zemi pojala bázeň a utichla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'když Bůh povstal k soudu, aby zachránil všechny pokorné země. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Vždyť tebe chválí i lidské rozlícení. Opášeš se tím, co po hněvu zbude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Čiňte sliby Hospodinu, svému Bohu, a plňte je! Všichni kolem něj ať přinesou dar Přehroznému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, 'Sráží ducha vládců a vzbuzuje hrůzu u králů země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Pro vedoucího chval, pro Jedútúna. Asafův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Můj hlas zní k Bohu, úpěnlivě volám, můj hlas zní k Bohu, on mi bude naslouchat!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'V den svého soužení jsem hledal Panovníka, v noci jsem k němu vztahoval ruku a neoblevoval jsem, má duše se nenechala utěšit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Rozpomínám se na Boha a úpím, přemýšlím a ⌈klesám na duchu.⌉ Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Držel jsi víčka mých očí, byl jsem rozrušen a nemohl jsem mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Přemýšlím o dávných dnech, o předvěkých letech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'V noci vzpomínám, jak jsem na struny hrával, přemýšlím v srdci a v duchu si kladu otázku:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Což mě Panovník zavrhl navěky? Nikdy již neprojeví své zalíbení?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Což jeho milosrdenství nadobro skončilo? Nebude už mluvit k dalším pokolením?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Což Bůh zapomněl na smilování? Cožpak zavřel v hněvu své slitování? Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Řekl jsem tedy: ⌈Mou bolestí je,⌉ že se změnila pravice Nejvyššího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Připomínám si Hospodinovy činy, ano, vzpomínám na tvé divy v dávnověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Rozjímám o všech tvých skutcích a přemýšlím o tvých činech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Bože, tvá cesta je svatá. Který bůh je velký jako tento Bůh?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Ty jsi Bůh, který koná divy. Dal jsi národům poznat svou moc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Svůj lid jsi vykoupil vlastní paží -- syny Jákobovy a Josefovy. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Spatřily tě vody, Bože, spatřily tě vody, rozvířily se, ba rozzuřily se hlubiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Voda se lila z mračen, z oblaků hřmělo, i tvé šípy se rozlétly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Vřava tvého hromobití, víření, blesky osvítily celý svět, země se chvěla a třásla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Tvá cesta vedla mořem, tvá stezka množstvím vod, ale tvé stopy nebyly znát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, 'Svůj lid jsi vedl jako stádo rukou Mojžíše a Árona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Meditace -- Asafův žalm. Lide můj, naslouchej mému poučení, nakloňte ucho k řeči mých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Otevřu ústa v příslovích, vypovím hádanky dávnověké.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Co jsme slýchali a pochopili a o čem nám naši otcové vyprávěli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'nezatajíme jejich synům. Budoucí generaci budeme vypravovat o Hospodinových chvályhodných skutcích, o jeho síle a jeho divech, které učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Ustanovil svědectví v Jákobovi, v Izraeli vydal zákon a přikázal našim otcům, aby s ním seznamovali své syny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'aby ho poznalo budoucí pokolení -- synové, kteří se jim narodí. Ti povstanou a budou to vyprávět svým synům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'aby složili svou důvěru v Boha, nezapomínali na Boží činy, jeho příkazy střežili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'a nebyli jako jejich otcové, pokolení umíněné a vzpurné, pokolení ⌈nestálého srdce,⌉ jehož duch nebyl Bohu věrný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Efrajimci, vyzbrojení lukostřelci, se v den bitvy obrátili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Nedbali na Boží smlouvu, odmítli žít podle jeho zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Zapomněli na jeho činy, na jeho divy, které jim ukázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Před jejich otci činil divy v egyptské zemi, na sóanském poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Rozpoltil moře a provedl je, postavil vody jako hráz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Ve dne je vedl skrze oblak a celou noc skrze ohnivé světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Rozpoltil skály v pustině a napojil je jako z velkých hlubin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Vyvedl bystřiny ze skály a dal jim rozlít se jako vodní proudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Oni však proti němu dále hřešili, ve vyprahlé zemi se vzpírali Nejvyššímu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'a ve svých srdcích Boha pokoušeli -- žádali si potravu podle svých choutek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Mluvili proti Bohu a říkali: Což může Bůh prostřít stůl v pustině?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Hle, udeřil do skály a vytryskla voda a rozlily se proudy. Což ale může dát i chléb? Což opatří i maso pro svůj lid?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Hospodin to slyšel a rozhněval se. Tu se rozpálil oheň proti Jákobovi a proti Izraeli vzplanul hněv,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'protože nevěřili Bohu a nedoufali v jeho spásu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'On však přikázal oblakům nahoře, otevřel nebeské brány');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'a seslal na ně manu k jídlu, dal jim nebeské zrno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Lidé jedli chléb vznešených. Seslal jim potravy do sytosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Nechal na nebi vát východnímu větru, svou mocí přivedl i vítr jižní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Seslal na ně masa jako prachu a okřídleného ptactva jako mořského písku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Nechal je padat do jejich tábora, kolem jejich příbytků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Jedli až do přesycení; dal jim, po čem toužili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Ještě si svou touhu nezošklivili, ještě měli potravu v ústech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'když ⌈na ně dolehl⌉ Boží hněv. Pobil jejich vypasené, izraelské mládence srazil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Přes toto vše stále hřešili a nevěřili jeho divům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Skončil jejich dny v marnosti a jejich léta v děsu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Když je hubil, hledali ho. Ano, navraceli se a ⌈usilovně hledali⌉ Boha');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'a rozpomínali se, že Bůh je jejich skála, že Bůh Nejvyšší je jejich vykupitel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'ale klamali ho svými ústy, svým jazykem mu lhali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'jejich srdce nebylo pevně při něm, nebyli věrni jeho smlouvě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'On se však slitovával, ⌈zprošťoval je nepravosti⌉ a nezničil je. ⌈Mnohdy odvracel⌉ svůj hněv a nedal zcela procitnout své zlobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Pamatoval, že jsou tělo, závan, který pomine a nevrátí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kolikrát se mu v pustině vzepřeli, trápili ho v pusté krajině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Stále znovu pokoušeli Boha, zraňovali Svatého Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Nepamatovali na jeho moc, na den, kdy je vykoupil z moci protivníka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'když učinil v Egyptě svá znamení a své divy na sóanském poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Jejich řeky proměnil v krev, a tak ze svých toků ne mohli pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Seslal na ně mouchy, aby je kousaly, a žáby, aby je ničily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Jejich úrodu dal kobylkám chasíl, jejich výtěžek kobylkám arbe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Jejich révu zničil krupobitím a jejich sykomory mrazem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Jejich dobytek vydal v plen krupobití a jejich stáda moru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Seslal na ně svůj planoucí hněv, zuřivost, rozhořčení a soužení -- komando zlých andělů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, '⌈Urovnal pěšinu⌉ svému hněvu. Jejich duše neušetřil smrti a jejich život vydal moru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Pobil vše prvorozené v Egyptě, prvotinu síly ve stanech Chámových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Svůj lid však vyvedl jako ovce, jako stádo je vedl pustinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Vedl je bezpečně, nebáli se; jejich nepřátele přikrylo moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Tak je přivedl na své svaté území -- k oné hoře, kterou si získal svou pravicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Vyhnal před nimi pohanské národy, rozměřil provazcem jejich dědičné podíly a usadil v jejich stanech izraelské kmeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Oni však pokoušeli Boha Nejvyššího, vzpírali se mu a jeho svědectví nezachovávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Odvraceli se, jednali ⌈věrolomně jako⌉ jejich otcové, selhávali jako záludný luk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Popouzeli ho svými návršími a dráždili ho svými modlami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Bůh to slyšel a rozhněval se. Zcela Izraele zavrhl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Opustil příbytek v Šílu, stan, kde přebýval mezi lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Svou sílu vydal do zajetí, svou nádheru do ruky protivníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Svůj lid vydal meči, na své dědictví se rozhněval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Jejich mládence pozřel oheň a jejich panny nebyly chváleny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Jejich kněží padli mečem a jejich vdovy neplakaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Pak Panovník procitl -- jako kdyby spal -- jako hrdina rozjařený vínem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Pobíjel své protivníky zezadu, uvedl na ně věčnou potupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Pohrdl stanem Josefovým, kmen Efrajimův si nevyvolil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'nýbrž zvolil si kmen Judův, horu Sijón, kterou si zamiloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Svou svatyni zbudoval jako něco vznešeného, jako zemi, kterou založil navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Vyvolil si Davida, svého otroka. Vzal ho od ovčích ohrad,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'přivedl ho od ovcí s jehňaty, aby pásl Jákoba, jeho lid, Izraele, jeho dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'I pásl je s bezúhonným srdcem a vodil je svou zkušenou rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Asafův žalm. Bože, pohanské národy pronikly do tvého dědictví, poskvrnily tvůj svatý chrám, Jeruzalém obrátily v sutiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Mrtvoly tvých otroků přenechaly za potravu nebeskému ptactvu, těla tvých věrných zemské zvěři,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'jejich krev prolévaly kolem Jeruzaléma jako vodu a nebylo, kdo by pohřbíval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Stali jsme se předmětem potupy pro své sousedy, posměchu a pošklebků pro své okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Až dokdy, Hospodine? Budeš se stále hněvat? Bude tvá žárlivost plát jako oheň?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Vylej svou zlobu na národy, které tě neznají; na království, která nevzývají tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'neboť pozřely Jákoba a zpustošily jeho nivy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Nepřipomínej nám dřívější viny; pospěš, předejdi nás svým slitováním, vždyť jsme zcela zubožení!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Pomoz nám, Bože, naše spáso, pro slávu svého jména! Vysvoboď nás a pro své jméno nás zprosti našich hříchů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Proč by měly národy říkat: Kde je ten jejich Bůh? Ať se před našima očima mezi národy pozná pomsta za prolitou krev tvých otroků!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Kéž před tebe pronikne nářek vězňů! Zachovej ⌈svou mocnou paží⌉ syny smrti!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Sedminásobně vrať našim sousedům do klína potupu, kterou tupili Panovníka!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'A my, tvůj lid, ovce tvé pastvy, tě budeme chválit navěky, z pokolení do pokolení budeme zvěstovat tvou chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Pro vedoucího chval. Na „Lilie svědectví“-- Asafův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Pastýři Izraele, naslouchej! Ty, jenž vodíš Josefa jako ovce, jenž trůníš na cherubech, zaskvěj se');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'před Efrajimem, Benjamínem a Manasesem! Probuď svou sílu a pojď nás zachránit!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Bože, obnov nás! Rozjasni svou tvář a budeme zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Hospodine, Bože zástupů, jak dlouho budeš planout při modlitbách svého lidu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Krmil jsi je chlebem slz, napájel jsi je slzami ⌈plnou měrou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Pro své sousedy jsi nás učinil předmětem sváru a naši nepřátelé se nám posmívají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Bože zástupů, navrať nás zpět! Rozjasni svou tvář a budeme zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Vyjmul jsi vinnou révu z Egypta, vyhnal jsi pohanské národy a zasadil jsi ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Připravil jsi ⌈pro ni vše.⌉ ⌈Zapustila své⌉ kořeny a naplnila zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Přikryla hory svým stínem, její větvoví bylo jako nejvyšší cedry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Vyhnala své ratolesti až k moři a své větve k řece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Proč jsi pobořil její zdi? Teď z ní trhá každý, kdo jde kolem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Rozrývá ji kanec z lesa, spásá ji polní havěť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Bože zástupů, navrať se, shlédni z nebes a pohleď; a postarej se o tu révu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'o kmen, který zasadila tvá pravice, o výhonek, který sis vypěstoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Je spálena ohněm, je porubaná -- od tvé výhrůžné tváře hynou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Budiž tvá ruka nad mužem tvé pravice, nad synem člověka, kterého sis vypěstoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'My se tě nepustíme, zachovej nás při životě a budeme vzývat tvé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, 'Hospodine, Bože zástupů, navrať nás zpět! Rozjasni svou tvář a budeme zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Pro vedoucího chval na gittít. Asafův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Jásejte Bohu, naší síle, hlaholte Bohu Jákobovu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Pozdvihněte zpěv, chopte se tamburíny, líbezné lyry i harfy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'při novoluní trubte na beraní roh, při úplňku, v den našeho svátku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'neboť to je ustanovení pro Izrael, nařízení Boha Jákobova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Ustanovil to jako svědectví v Josefovi, když vytáhl proti zemi egyptské. Slýchal jsem tam řeč, kterou jsem neznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '⌈Zbavil jsem⌉ jeho ⌈rameno břemene,⌉ jeho ruce mohly pustit koš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'V soužení jsi volal a já jsem tě vytrhoval, odpovídal jsem ti skryt v hromobití, zkoušel jsem tě při Vodách sváru. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Slyš, můj lide, svědčím proti tobě! Izraeli, kéž bys mě poslechl!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Nebude v tobě cizí bůh, nebudeš se klanět cizáckému bohu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Já Hospodin jsem tvůj Bůh, který tě vyvedl z egyptské země. Otevři ústa a naplním je!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Ale můj lid mě neposlechl, Izrael se mi nepodvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Tak jsem je vydal umíněnosti jejich srdce. ⌈Ať si jdou za svými plány.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Kdyby mě můj lid poslouchal, kdyby Izrael chodil po mých cestách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'brzy bych pokořil jeho nepřátele a obrátil bych svou ruku proti jeho protivníkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Ti, kdo nenávidí Hospodina, by mu lichotili; jejich čas by byl věčně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, 'Krmil by ho ⌈tou nejlepší pšenicí⌉ a ⌈sytil bych tě⌉ medem ze skály.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Asafův žalm. Bůh povstane ve shromáždění bohů, mezi bohy vynese soud:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '⌈Jak dlouho⌉ budete soudit špatně a ⌈stranit ničemům?⌉ Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Zjednejte právo bezmocnému a sirotkovi, nuznému a chudému zjednejte spravedlnost!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Vytrhněte chudého a nuzného vysvoboďte z ruky ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Nerozumějí tomu, nechápou to, chodí v temnotách. A všechny základy země se hroutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Řekl jsem: Jste bohové, všichni jste synové Nejvyššího,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'ale takto zemřete jako lidé, padnete jako někdo z knížat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Povstaň, Bože, zjednej na zemi právo, vždyť tobě dědičně patří všechny národy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Píseň. Asafův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Bože, nebuď netečný, nebuď hluchý! Nezůstávej v klidu, Bože!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Neboť hle, tvoji nepřátelé běsní a ti, kdo tě nenávidí, zvedají hlavu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Proti tvému lidu ⌈kují pikle⌉ a smlouvají se proti těm, ⌈kdo jsou ti drazí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Říkají: Pojďme a vyhlaďme je, ⌈aby ne byli národem!⌉ A jméno Izraele již nebude připomínáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Tak se jednomyslně uradili, uzavřeli proti tobě smlouvu --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'stany edómské, Izmaelité, Moáb a Hagrejci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Gebal, Amón a Amálek, Pelištea i obyvatelé Týru');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'a Ašúr se k nim také přidal. Stali se paží ⌈synů Lotových.⌉ Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Učiň jim jako Midjánu, jako Síserovi, jako Jabínovi u potoka Kíšónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Byli zničeni u Én–dóru, stali se hnojem pro půdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Nalož s nimi -- s jejich předními muži -- jako s Órébem a Zébem a se všemi jejich knížaty jako se Zebachem a Salmunou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'kteří si řekli: Obsaďme Boží nivy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Bože můj, učiň, ať jsou jako chmýří, jako stéblo ve větru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Jako oheň stravuje les, jako plameny spalují hory,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'tak je stíhej svým vichrem, vyděs je svou bouří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Jejich tváře pokryj hanbou, aby hledali tvé jméno, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Ať se stydí, ať se jen a jen třesou, ať se hanbí a zahynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, 'Ať pochopí, že ty, jehož jméno je Hospodin, jen ty jsi Nejvyšší nad celou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Pro vedoucího chval -- na gittít. Žalm synů Kórachových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Jak milé jsou tvé příbytky, Hospodine zástupů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Má duše touží, ano, chřadne steskem po Hospodinových nádvořích; ⌈mé srdce i tělo⌉ ⌈radostně volá⌉ k živému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'I vrabec si najde domov, i vlaštovka má hnízdo, kam klade svá mláďata... Tvé oltáře, Hospodine zástupů, ⌈můj králi a můj Bože!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Blahoslavení jsou ti, kdo přebývají ve tvém domě a stále tě chválí! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Blahoslavený je člověk, jehož síla je v tobě, ⌈který je odhodlán putovat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Procházejí údolím balzámovníků a ⌈učiní je pramenem,⌉ nadto je raný déšť halí požehnáním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Putují -- ⌈stále silní⌉ -- a objeví se před Bohem na Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Hospodine, Bože zástupů, slyš mou modlitbu. Naslouchej, Bože Jákobův! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Štíte náš, Bože, viz, pohleď na tvář svého pomazaného!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Den ve tvých nádvořích je lepší než tisíc jinde. Zvolím raději ⌈stát na prahu⌉ v domě svého Boha, než pobývat ve stanech ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Vždyť Bůh Hospodin je slunce i štít. Hospodin dává milost i slávu, neodepře dobro těm, kdo žijí bezúhonně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, 'Hospodine zástupů, blahoslavený je člověk, který doufá v tebe!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Pro vedoucího chval. Žalm synů Kórachových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Hospodine, našel jsi zalíbení ve své zemi, změnil jsi Jákobův úděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Sňal jsi vinu svého lidu, přikryl jsi všechny jejich hříchy. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Odložil jsi všechno své rozhořčení, odvrátil ses od svého planoucího hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Obnov nás, Bože, naše spáso, skoncuj se svou hněvivostí vůči nám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Což se na nás budeš hněvat navěky? Potáhne se tvůj hněv z pokolení do pokolení?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Což nás opět neobživíš, aby se tvůj lid v tobě radoval?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Ukaž nám, Hospodine, své milosrdenství, daruj nám svou spásu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Poslechnu, co říká Bůh Hospodin. Vždyť promlouvá pokoj ke svému lidu, ke svým ⌈věrným. Kéž se nevracejí k bláznovství!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Vskutku, jeho spása je blízko těm, kdo se ho bojí, a tak bude v naší zemi přebývat jeho sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Milosrdenství a věrnost se potkají, spravedlnost a pokoj se políbí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Ze země vyraší věrnost, z nebes bude vyhlížet spravedlnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Hospodin dá i dobro a naše země vydá úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, 'Před ním bude kráčet spravedlnost a připraví cestu jeho krokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Modlitba Davidova. Nakloň, Hospodine, své ucho a odpověz mi, neboť jsem chudý a nuzný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Chraň mou duši, neboť jsem věrný. Ty, Bože můj, zachraň svého otroka, jenž v tebe doufá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Smiluj se nade mnou, Panovníku, vždyť k tobě celé dny volám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Dej radost duši svého otroka, neboť k tobě, Panovníku, pozvedám svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Neboť ty jsi, Panovníku, dobrý a ⌈ochotný odpouštět;⌉ jsi hojný v milosrdenství ke všem, kdo k tobě volají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Naslouchej, Hospodine, mé modlitbě, věnuj pozornost mým úpěnlivým prosbám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'V den svého soužení k tobě volám -- jistě mi odpovíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Mezi bohy není nikdo jako ty, Panovníku, není nic jako tvé skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Všechny národy, které jsi učinil, přijdou a budou se před tebou klanět, Panovníku, a budou oslavovat tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'protože jsi veliký a konáš divy; ty jediný jsi Bůh!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Vyuč mě, Hospodine, své cestě -- ⌈chodím ve tvé pravdě.⌉ Soustřeď mé srdce, abych se bál tvého jména!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Budu ti vzdávat chválu celým srdcem, Panovníku, můj Bože, navěky budu oslavovat tvé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'protože je nade mnou tvé velké milosrdenství. Mou duši jsi vysvobodil z nejhlubšího podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Bože, povstávají proti mně domýšlivci, pospolitost násilníků mi usiluje o život, o tobě nepřemýšlejí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Ale ty jsi, Panovníku, Bůh soucitný a milostivý, pomalý k hněvu, hojný v milosrdenství a věrnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Pohleď na mě a smiluj se nade mnou! Dej svou sílu svému otroku, zachraň syna své služebnice!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Učiň ⌈pro mě⌉ znamení k dobrému! Ti, kdo mě nenávidí, to uvidí a zastydí se -- vždyť ty, Hospodine, mi pomůžeš a potěšíš mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Zpívaný žalm synů Kórachových. Jeho základ je na svatých horách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Hospodin miluje brány Sijónu nade všechny příbytky Jákobovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Vyprávějí se o tobě slavné věci, město Boží! Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Připomenu Rahab a Bábel ⌈z těch,⌉ kdo mě znají. Hle, Pelištea a Týr, ba i Kúš -- ti všichni se zrodili tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'O Sijónu se bude říkat: Zrodil se v něm ⌈ten i onen.⌉ A sám Nejvyšší ho činí pevným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Hospodin si zapíše při soupisu národů: Tento se tam narodil. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'A budou při tanci zpívat: Všechny mé zdroje jsou v tobě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Žalmová píseň ⌈synů Kórachových.⌉ Pro vedoucího chval -- na machalat leannót. Meditace Hémana Ezrachejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Hospodine, Bože, má spáso, ve dne úpěnlivě volám, v noci jsem před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Kéž má modlitba přijde před tebe, nakloň své ucho k mému volání!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Má duše se sytí trápením, můj život spěje do podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Jsem počítán mezi ty, kdo sestupují do jámy, jsem jako muž, ⌈ jemuž není pomoci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Jsem odložen mezi mrtvými, podoben pobitým, ležícím v hrobě, na které již nevzpomínáš -- jsou odříznuti od tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Odložils mě kamsi na dno jámy, do temných míst, do hlubin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Leží na mně tvé rozlícení, všemi svými příboji mě trýzníš. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Vzdálils ode mě mé známé, učinils mě pro ně ohavností. Jsem sevřen a ne mohu z toho vyváznout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Soužením mi ochably oči. Hospodine, každý den tě volám, vztahuji k tobě dlaně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Což budeš dělat divy pro mrtvé? Či snad povstanou nebožtíci a budou ti vzdávat chválu? Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Což se vypráví v hrobě o tvém milosrdenství? O tvé věrnosti v říši zániku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Což jsou známy v temnotách tvé divy? Tvá spravedlnost v zemi zapomnění?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Já přece volám o pomoc k tobě, Hospodine! Z jitra k tobě stoupá má modlitba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Hospodine, proč odvrhuješ mou duši? Proč přede mnou skrýváš svou tvář?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Jsem nuzný a od mládí skomírám; snáším tvé hrůzy, jsem bezradný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Přehnalo se přese mě tvé rozlícení, tvé rány mě dorazily,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'obklopily mě jako vody, po všechny dny mě obkličují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, 'Vzdálil jsi ode mě přítele i druha, ⌈mým důvěrníkem je jen temnota.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Meditace Étana Ezrachejského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Navěky ⌈budu zpívat o ⌉ Hospodinově milosrdenství, z pokolení do pokolení budu svými ústy oznamovat tvou věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Řekl jsem totiž: Navěky je zbudováno milosrdenství v nebesích, v nich jsi upevnil svou věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Uzavřel jsem smlouvu se svým vyvoleným, přísahal jsem Davidovi, svému otroku:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Navěky upevním tvé potomstvo, zbuduji z pokolení do pokolení tvůj trůn. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Nebesa vzdávají chválu za tvé divy, Hospodine, i za tvou věrnost v shromáždění svatých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Vždyť kdo v oblacích je roven Hospodinu? Kdo je podoben Hospodinu mezi Božími syny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Bůh je strašný v společenství svatých, veliký a hrozný mezi všemi kolem sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Hospodine, Bože zástupů, ⌈kdo je jako ty? Jsi mocný,⌉ Hospodine, a tvá věrnost ⌈tě obklopuje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Ty panuješ nad ⌈majestátným mořem;⌉ když se pozvedají jeho vlny, ty je utišuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Ty jsi srazil obludu jako raněného, svou mocnou paží jsi rozptýlil své nepřátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Tvá jsou nebesa, tvá je i země, ty jsi založil svět i vše, co ho naplňuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Ty jsi stvořil sever i jih; Tábor i Chermón jásají ve tvém jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Tvá paže je udatná, tvá ruka je silná, tvá pravice je vyvýšená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Spravedlnost a právo jsou základ tvého trůnu; milosrdenství a věrnost kráčejí před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Blahoslavený je lid, který zná radostný křik, Hospodine, ti budou chodit ve světle tvé tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Ve tvém jménu jásají každý den, pozvedají se ve tvé spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Vždyť tys ⌈nádhera jejich síly,⌉ díky tvé přízni se zvedá náš roh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Neboť naším štítem je Hospodin a naším králem Svatý Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Jednou jsi ve vidění promluvil ke svým věrným. Řekl jsi: Oděl jsem hrdinu pomocí, vyvýšil jsem vybraného z lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Nalezl jsem Davida, svého otroka, pomazal jsem ho svým svatým olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Stále s ním bude má ruka, ano, má paže jej upevní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Nepřítel na něj nevyzraje, bídák ho nepokoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Potřu před ním jeho protivníky, porazím ty, kdo ho nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Bude s ním má věrnost i mé milosrdenství, v mém jménu se pozvedne jeho roh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Jeho ruku položím na moře, jeho pravici na řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'On ke mně bude volat: Tys můj otec, můj Bože, tys skála mé spásy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'A já ho ustanovím prvorozeným, nejvyšším z králů země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Navěky mu zachovám své milosrdenství, má smlouva s ním bude trvalá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Ustanovím natrvalo jeho potomstvo a jeho trůn po všechny dny nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Pokud jeho potomci opustí můj zákon a nebudou žít podle mých nařízení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'jestliže má ustanovení znesvětí a nebudou zachovávat mé příkazy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'navštívím jejich přestoupení holí a jejich zvrácenost ranami,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'ale své milosrdenství vůči němu nezruším a nezradím svou věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Neznesvětím svou smlouvu, nezměním, co vyšlo z mých rtů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Jednou jsem přísahal při své svatosti. ⌈Což bych lhal Davidovi?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Jeho potomstvo tu bude navěky a jeho trůn bude přede mnou jako slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Jako měsíc bude pevně stát navěky -- a svědek v oblacích je spolehlivý. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Ale tys ho odvrhl a odmítl, rozhněval ses na svého pomazaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Opustil jsi smlouvu svého otroka, jeho korunu jsi znesvětil, pohodil na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Pobořils všechny jeho zdi, jeho pevnosti jsi proměnil v trosky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Plení ho všichni, kdo procházejí kolem, je pro posměch svým sousedům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Vyvýšils pravici jeho protivníků, rozradostnil jsi všechny jeho nepřátele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'ano, otupils i ostří jeho meče a v bitvě jsi ho nepodepřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Zbavil jsi ho lesku a jeho trůn jsi svrhl na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Zkrátil jsi dny jeho mládí a pokryl jsi ho hanbou. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Až dokdy, Hospodine? Budeš se pořád skrývat? Bude plát tvá zloba jako oheň?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Rozpomeň se na mě! Co je lidský věk? K jaké nicotě jsi stvořil všechny lidské syny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Který člověk kdy žil a nespatřil smrt? Kdo zachránil svou duši z moci podsvětí? Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Kde je tvé dřívější milosrdenství, Panovníku, které jsi odpřisáhl Davidovi ve své věrnosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Pamatuj, Panovníku, na potupu svých otroků! Nosil jsem ji ve svém klíně od všech možných národů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Jak tupili tví nepřátelé, Hospodine, jak tupili kroky tvého pomazaného!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, 'Požehnán buď Hospodin navěky. Amen i Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Modlitba Mojžíše, muže Božího. Panovníku, tys býval naším příbytkem od pokolení do pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Dříve než se zrodily hory, než jsi zrodil zemi a celý svět, od věků navěky jsi ty, Bože.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Vracíš člověka k prachu a říkáš: Vraťte se, synové Adamovi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Vždyť tisíc let je v tvých očích jako včerejší den, který pominul, či ⌈jako noční⌉ hlídka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Odplavuješ je, jsou jako spánek zrána, vadnou jako tráva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Zrána rozkvétá, mění se, k večeru vadne a usychá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'To pro tvůj hněv chřadneme a děsíme se před tvým rozlícením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Kladeš si před sebe naše nepravosti a to, co skrýváme, do světla své tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'A tak všechny naše dny míjejí pro tvé rozhořčení, naše léta ⌈hasnou jako povzdech.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Časy našich let -- je jich sedmdesát, a je–li člověk při síle, osmdesát. A jejich pýchou je jen trápení a nepravost -- proto rychle pomíjejí a my odlétáme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Kdo zná sílu tvého hněvu? A ⌈tvé rozhořčení podle bázně před tebou?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Počítat naše dny, o tom nás pouč, ⌈a uvedeme do srdce moudrost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Obrať se, Hospodine! Jak dlouho ještě? Slituj se nad svými otroky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Nasyť nás zrána svým milosrdenstvím, abychom mohli jásat a radovat se po všechny své dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Daruj nám radost podle dnů, kdys nás pokořoval, podle let, kdy jsme viděli zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Ukaž svým otrokům své dílo a svou nádheru na jejich synech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Kéž je nad námi vlídnost Panovníka, našeho Boha! Upevni nám dílo našich rukou, ano, upevni dílo našich rukou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Ten, kdo přebývá v úkrytu Nejvyššího, přečká noc ve stínu Všemohoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Říkám o Hospodinu: Je mé útočiště, má tvrz, můj Bůh, v něho doufám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'On tě uchrání před osidlem ptáčníkovým, před morovou zkázou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Přikryje tě svými perutěmi, pod jeho křídly máš útočiště, jeho věrnost je pavézou i štítem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Nebudeš se bát nočního děsu, ani toho, že ve dne přiletí šíp,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'ani moru, obcházejícího po setmění, ani zhouby, jež ničí za poledne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Po tvém boku padne tisíc, deset tisíc po tvé pravici, k tobě se to nepřiblíží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Jistě uvidíš na vlastní oči, ano uzříš odplatu ničemům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Protože jsi Hospodina, mé útočiště, protože jsi Nejvyššího učinil svým příbytkem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'nestane se ti nic zlého, rána se ke tvému stanu nepřiblíží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'neboť svým andělům vydal o tobě příkaz, aby tě střežili na všech tvých cestách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Na rukou tě ponesou, aby tvá noha neklopýtla o kámen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Budeš šlapat po lvu i po zmiji, pošlapeš mladého lva i draka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Protože ke mně přilnul, vytrhnu ho; uvedu ho do bezpečí, protože zná mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Bude ke mně volat a já mu odpovím, budu s ním v soužení, vytrhnu ho a obdařím ho slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Nasytím ho vysokým věkem a dám mu spatřit svou spásu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Žalm, píseň ke dni sobotnímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Je dobré vzdávat Hospodinu díky a opěvovat tvé jméno, ó Nejvyšší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'zvěstovat z rána tvé milosrdenství a v noci tvou věrnost');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'při deseti strunném nástroji, při harfě a ⌈při znění lyry.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Hospodine, svým dílem mi působíš radost, jásám nad skutky tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Jak velké jsou tvé skutky, Hospodine! Tvé úradky jsou přehluboké!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Tupec nechápe, hlupák tomu nerozumí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'že ničemové vyrážejí jako zeleň a všichni činitelé nepravosti kvetou, aby byli navždy vyhlazeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Ale ty, Hospodine, jsi navěky vyvýšený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Hle, tvoji nepřátelé, Hospodine, hle tvoji nepřátelé zahynou, budou rozprášeni všichni činitelé nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Vyvýšil jsi můj roh jako roh divokého tura, natřel jsem se čerstvým olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Mé oko uvidí ty, kdo na mě číhají, mé uši uslyší o zlovolnících, kteří proti mně povstávají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Spravedlivý pokvete jako palma, bude růst jako cedr na Libanonu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Jsou zasazeni v domě Hospodinově, kvetou na nádvořích našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'I v šedinách budou plodní, budou zdatní a svěží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, 'aby zvěstovali, že Hospodin, má skála, je přímý a ne ní v něm podlost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Hospodin kraluje! Oděl se důstojností! Oděl se Hospodin, silou se opásal! Ano, i svět ⌈stojí pevně,⌉ nezhroutí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Tvůj trůn pevně stojí odedávna. Ty jsi od věčnosti!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Pozdvihly proudy, Hospodine, pozdvihly proudy svůj hlas, zvedají proudy své vlnobití!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Nad majestátný hukot mnohých vod, nad mořský příboj je majestátný Hospodin na výšině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Tvá svědectví jsou naprosto spolehlivá. Hospodine, tvému domu sluší svatost po dlouhé časy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Bože pomsty, Hospodine, Bože pomsty, zaskvěj se!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Pozdvihni se, soudce země, uveď odplatu na pyšné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Až dokdy, Hospodine, až dokdy budou ničemové jásat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, '⌈Chrlí drzé řeči,⌉ vychloubají se všichni činitelé nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Deptají tvůj lid, Hospodine, utlačují tvé dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Hubí vdovu a příchozího, i sirotky vraždí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Říkají: Hospodin to nevidí, Bůh Jákobův se tím nezabývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Uvažujte, vy tupci z lidu. Hlupáci, kdy to pochopíte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Což neslyší ten, kdo udělal ucho? Což nevidí ten, kdo vytvořil oko?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Což nekárá ten, kdo vychovává národy? On dává člověku poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Hospodin zná lidská uvažování, ví, že jsou marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Blahoslavený je muž, kterého kázníš, Hospodine; vyučuješ ho ze svého zákona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'abys ho utišil ve zlých dnech, zatímco se kope jáma pro ničemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Vždyť Hospodin svůj lid nezanechá, své dědictví neopustí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Soud se vrátí k spravedlnosti a za ním všichni lidé přímého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kdo se za mě postaví proti zlovolníkům? Kdo se mě zastane proti činitelům nepravosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Kdyby Hospodin nebyl mou pomocí, brzy by má duše spočinula v ⌈říši ticha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, '⌈Řeknu–li: Uklouzne mi noha, tvé milosrdenství, Hospodine, mě podepře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Když sám v sobě moc přemýšlím, tvé potěšování utěší mou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Což se k tobě připojí ⌈zkázonosný trůn⌉ působící trápení -- proti všem Božím ustanovením?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Napadají duši spravedlivého a obviňují nevinnou krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Hospodin je mi však nedobytným hradem, můj Bůh je mou útočištnou skálou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Odplatí jim jejich nepravosti a pro jejich špatnosti je zničí. Ano, Hospodin, náš Bůh, je zničí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Pojďme, jásejme Hospodinu, hlaholme skále své spásy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Vstupme před něj s chvalami, hlaholme mu písněmi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Vždyť Hospodin je velký Bůh a velký král nade všemi bohy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'V jeho rukou jsou končiny země, patří mu i vrcholky hor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Jemu patří moře -- on je udělal, souš vytvořily jeho ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Pojďme, klaňme se, skloňme se, poklekněme před Hospodinem, který nás učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Vždyť on je náš Bůh a my jsme lid jeho pastvy, ovce ⌈jeho rukou.⌉ ⌈Jestliže dnes uslyšíte jeho hlas,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'nezatvrzujte svá srdce jako v Meribě, jako v den Massy v pustině,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'kde mě vaši otcové pokoušeli. Zkoušeli mě, přestože viděli mé skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Čtyřicet let jsem se s tím pokolením trápil. Řekl jsem si: Je to lid, který bloudí srdcem -- ti mým cestám neporozuměli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Tak jsem se ve svém hněvu zapřisáhl: Nevejdou do mého odpočinutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Zpívejte Hospodinu novou píseň, zpívej Hospodinu, celá země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Zpívejte Hospodinu, dobrořečte jeho jménu, zvěstujte den ze dne jeho spásu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Vypravujte mezi národy o jeho slávě, mezi všemi lidmi o jeho divech!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Vždyť Hospodin je velký, nejvýš chvályhodný, vzbuzuje bázeň nade všechny bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Vždyť všichni bohové národů jsou nicotnosti; Hospodin však učinil nebesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Nádhera a důstojnost před ním, moc a okrasa v jeho svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Vzdejte Hospodinu, čeledi národů, vzdejte Hospodinu slávu a moc!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Vzdejte Hospodinu slávu jeho jména, přineste dar a vstupte na jeho nádvoří!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Klaňte se Hospodinu v nádheře svatyně! Svíjej se před ním, celá země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Říkejte mezi národy: Hospodin kraluje! Ano, svět stojí pevně, nezhroutí se. Hospodin spravedlivě rozsoudí národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Radujte se, nebesa, jásej, země, ať burácí moře a vše, co je v něm!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Vesel se, pole, a vše, co je na něm. Tehdy bude jásat všechno lesní stromoví');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'před Hospodinem, neboť přichází -- přichází, aby na zemi konal soud. Spravedlivě bude soudit celý svět, národy ve své pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Hospodin kraluje! Ať země jásá, ať se raduje i množství ostrovů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Kolem něj je oblak a hustá temnota, spravedlnost a právo jsou základem jeho trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Předchází ho oheň, spaluje kolem jeho protivníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Jeho blesky osvěcují celý svět; země to vidí a svíjí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Hory se rozplývají jako vosk před Hospodinem, před ⌈Pánem vší země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Nebesa zvěstují jeho spravedlnost a všechny národy vidí jeho slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Budou zahanbeni všichni, kdo slouží modlám, ti, kdo se chlubí nicotnostmi. Jemu se klanějí všechny božské bytosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sijón to slyší a raduje se, dcery judské jásají nad tvými soudy, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Neboť ty, Hospodine, jsi nejvyšší nade vší zemí, velmi převyšuješ všechny božské bytosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Kdo milujete Hospodina, mějte v nenávisti zlo. On střeží duše svých věrných a vysvobozuje je z ruky ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Pro spravedlivého je zaseto světlo a radost těm, kdo jsou přímého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Radujte se, spravedliví, v Hospodinu! Vzdejte chválu ⌈jeho svatému jménu!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Žalm. Zpívejte Hospodinu novou píseň, protože vykonal divy! Pomohla mu jeho pravice, jeho svatá paže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Hospodin dal poznat svou spásu, zraku pohanů odhalil svou spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Rozpomenul se na své milosrdenství a na svou věrnost izraelskému domu. Všechny končiny země uvidí spásu našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Hlahol Hospodinu, celá země! Propukněte v jásot a pějte žalmy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Opěvujte Hospodina při lyře, při lyře a ⌈hlasitém zpěvu,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'na trubky a zvukem beraních rohů hlaholte před Hospodinem králem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Ať burácí moře a vše, co je v něm, celý svět i jeho obyvatelé!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Řeky ať tleskají v dlaně, ba i hory ať jásají');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'před Hospodinem, jenž přichází, aby soudil zemi, aby soudil celý svět v spravedlnosti a národy s přímostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Hospodin kraluje -- národy se chvějí. Trůní na cherubech -- země se zmítá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Velký je Hospodin na Sijónu, je vyvýšený nade všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Nechť vzdávají chválu tvému jménu, velkému a budícímu bázeň -- je svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Králova moc miluje právo. Ty jsi zárukou přímosti; vykonáváš v Jákobovi právo a spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Vyvyšujte ⌈Hospodina, našeho⌉ Boha, klaňte se u podnože jeho nohou -- on je svatý!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mojžíš a Áron byli mezi jeho kněžími, Samuel patřil mezi ty, kdo vzývali jeho jméno. Volali k Hospodinu a on jim odpovídal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Mluvil k nim z oblakového sloupu a oni zachovávali jeho svědectví a ustanovení, která jim dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Hospodine, Bože náš, tys jim odpovídal. Byl jsi jim Bohem, který odpouští, ale mstil ses za jejich křivé jednání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Vyvyšujte Hospodina, našeho Boha, klaňte se k jeho svaté hoře, neboť Hospodin, náš Bůh, je svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Děkovný žalm. Hlahol Hospodinu, celá země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Služte Hospodinu s radostí, předstupte před něj s jásáním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Vězte, že Hospodin je Bůh, on nás učinil, a ⌈ne my sami sebe.⌉ Jsme jeho lid, ovce jeho stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Vejděte do jeho bran s děkovnými písněmi, na jeho nádvoří s chválami! Vzdávejte mu chválu, dobrořečte jeho jménu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'protože Hospodin je dobrý, jeho milosrdenství je věčné a jeho věrnost od pokolení do pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Davidův žalm. Budu zpívat o milosrdenství a právu, tebe, Hospodine, budu opěvovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Budu ⌈pečlivě dbát na bezúhonnou cestu.⌉ Kdy už ke mně přijdeš? Budu žít ⌈v bezúhonnosti svého srdce⌉ ve svém domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, '⌈Nekladu si před oči⌉ ničemnosti, nenávidím jednání odpadlíků -- neulpí na mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Zvrácené srdce ode mě odstoupí -- zlo neuznávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Kdo tajně pomlouvá svého bližního, toho zničím; člověka povýšených očí a nadutého srdce nebudu snášet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Můj zrak spočine na věrných v zemi; budou se mnou přebývat. Kdo chodí bezúhonnou cestou, ten mi bude sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'V mém domě nebude přebývat ten, kdo jedná záludně; ten, kdo mluví lži, v mých očích neobstojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Po ránu budu hubit všechny ničemy v zemi, abych z Hospodinova města vyhladil všechny činitele nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Modlitba zkroušeného, když umdlévá a vylévá před Hospodinem svůj nářek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Hospodine, slyš mou modlitbu, kéž k tobě pronikne mé volání o pomoc!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'V den mého soužení neskrývej přede mnou svou tvář, nakloň ke mně své ucho. V den, kdy volám, mi rychle odpověz!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Mé dny minuly jako dým a mé kosti jsou rozpálené jak ohniště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mé srdce je ubité a schne jako bylina, i svůj chléb jíst zapomínám;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'pro mé vzdychání přilnuly mi kosti k tělu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Podobám se stepnímu pelikánu, jsem jako sova z rozvalin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Nespím a jsem jako osamělý ptáček na střeše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Celý den mě mí nepřátelé tupí. Potřeštěnci při mně přísahají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Místo chleba jím popel, do svého nápoje přimíchávám slzy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'To od tvého rozhořčení a hněvu. Zvedl jsi mě a odvrhl jsi mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mé dny jsou jako stín, který se prodlužuje, a já schnu jako bylina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Ale ty, Hospodine, zůstáváš navěky; ⌈jsi připomínán⌉ od pokolení do pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Ty povstaneš, slituješ se nad Sijónem -- vždyť nastal čas, aby ses nad ním smiloval; vždyť nadešla ta chvíle!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Vždyť tví otroci si oblíbili jeho kameny; jímá je lítost nad jeho sutinami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Národy se budou bát Hospodinova jména a všichni králové země tvé slávy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'až Hospodin zbuduje Sijón a ukáže se ve své slávě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'až shlédne na modlitbu bezmocného, nepohrdne jejich modlitbami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Toto je zapsáno pro budoucí pokolení. Lid, který bude stvořen, bude chválit Hospodina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'který shlédl ze svých svatých výšin. Hospodin pohlédl z nebes na zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'aby vyslyšel nářek vězňů a rozvázal syny smrti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'aby vypravovali na Sijónu o Hospodinově jménu a o jeho chvále v Jeruzalémě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'když se společně shromáždí národy i království, aby sloužily Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Cestou pokořil mou sílu a zkrátil mé dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Pravím: Můj Bože, neber mě uprostřed mých dnů -- tvá léta jsou od pokolení do pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Dávno jsi založil zemi, nebesa jsou dílo tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Ta zaniknou, ale ty zůstaneš. Všechna jako roucho zvetší, vyměníš je jako plášť a budou proměněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Ale ty jsi stále týž -- tvá léta nekončí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, 'Synové tvých otroků budou mít klid a jejich símě bude před tebou upevněno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Davidův. Dobrořeč, má duše, Hospodinu, a celé mé nitro jeho svatému jménu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Dobrořeč, má duše, Hospodinu, a nezapomínej, co vše vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'On odpouští všechny tvé viny, on uzdravuje všechny tvé nemoci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'On vykupuje z jámy tvůj život, korunuje tě milosrdenstvím a slitováním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'On napájí tvé trvání dobrem, tvé mládí se obnovuje jako mládí orla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Hospodin zjednává spravedlnost, zjednává právo všem utlačovaným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Dal poznat své cesty Mojžíšovi a synům Izraele své činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Soucitný a milostivý je Hospodin, pomalý k hněvu a velkého milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Nebude se pořád přít a nebude se hněvat věčně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Nenakládá s námi podle našich hříchů, neodplácí nám podle našich provinění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Vždyť jak vysoko jsou nebesa nad zemí, tak ⌈mocné je⌉ jeho milosrdenství nad těmi, kdo se ho bojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Jak daleko je východ od západu, tak od nás vzdálil naše přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Jako má otec soucit se svými syny, tak se slitovává Hospodin nad těmi, kdo se ho bojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'On přece ví, jak jsme utvořeni, pamatuje, že jsme prach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Dny člověka jsou jako tráva, rozkvétá jako polní květ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Vítr na něho zafouká a je po něm, a už si nepovšimnou, že tu není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Ale Hospodinovo milosrdenství je od věků až navěky nad těmi, kdo se ho bojí, a jeho spravedlnost nad syny jeho synů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'nad těmi, kdo zachovávají jeho smlouvu a pamatují na jeho přikázání, aby je plnili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Hospodin upevnil svůj trůn na nebesích a jeho kralování vládne všemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Dobrořečte Hospodinu, jeho andělé, vy mocní hrdinové, kteří činíte jeho slovo, poslušní jeho slova!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Dobrořečte Hospodinu všechny jeho zástupy, vy, kdo mu sloužíte a činíte, v čem má zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Dobrořečte Hospodinu všechny jeho skutky -- na všech místech jeho vlády! Dobrořeč, má duše, Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Dobrořeč, má duše, Hospodinu! ⌈Hospodine, můj Bože,⌉ jsi velmi veliký! Oblékls nádheru a důstojnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Halíš se světlem jako pláštěm, roztahuješ nebesa jako stanovou plachtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Na vodách kladeš trámy svých komnat, z oblaků si činíš vůz, vznášíš se na perutích větru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Činíš si z větrů své posly, své služebníky z planoucího ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Založil zemi na základech -- nepohne se na věky věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Hlubinu jsi přikryl jako pláštěm, nad horami stály vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Před tvými hrozbami utíkaly, před hřmotem tvého hromobití se v hrůze rozprchly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Vystoupila pohoří, vody klesly do údolí, do míst, která jsi jim určil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Vymezils jim hranice, které nepřekročí. Nevrátí se, aby zaplavily zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Posíláš prameny do potoků, jež tečou mezi horami,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'napájejí všechnu polní zvěř; divocí oslové tu tiší žízeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Sídlí u nich nebeské ptactvo, štěbetá mezi listovím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Ze svých komnat zavlažuješ hory, země se sytí ovocem tvého díla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Dáváš vyrůst trávě pro dobytek a rostlinám, ⌈které pěstuje člověk,⌉ aby ze země vydobyl potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'I víno, které dává radost lidskému srdci, takže se tvář leskne olejem, i chléb, jenž posilňuje lidské srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Sytí se i Hospodinovo stromoví, libanonské cedry, které zasadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Hnízdí na nich ptactvo; ⌈čáp má domov na cypřiších.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Vysoká pohoří patří kozorožcům, skály jsou útočištěm pro damany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Učinil jsi měsíc ⌈k určování času,⌉ slunce ví, ⌈kdy zapadnout.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Navodíš tmu, nastane noc. V ní se hemží všechna lesní zvěř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Mladí lvi řvou po kořisti a žádají od Boha svou potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Vzchází slunce -- stahují se a uléhají do svých doupat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Člověk vychází ke svému dílu a ke své službě až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Jak mnohá jsou tvá díla, Hospodine! Všechna jsi je moudře učinil. Země je plná tvých tvorů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Hle moře, velké a široširé -- tam se toho hýbe! Bezpočet živočichů malých i velikých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Plují tam lodě -- i livjátán, kterého jsi vytvořil, aby ses z něj radoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Ti všichni vzhlížejí k tobě, že jim dáš potravu ve svůj čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Dáváš jim, a oni si berou, otvíráš svou ruku a sytí se dobrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Když skryješ svou tvář, děsí se, když jim odejmeš ducha, hynou a navracejí se v prach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Když posíláš svého ducha, jsou stvořeni. Tak obnovuješ tvář země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Kéž Hospodinova sláva trvá věčně! Kéž se Hospodin raduje ze svého díla!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Pohlédne na zemi a ta se roztřese, dotkne se hor a vzplanou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Budu zpívat Hospodinu po celý svůj život, budu opěvovat svého Boha, dokud budu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Kéž ho mé promlouvání potěší -- já se raduji v Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Kéž hříšníci vyhynou ze země, kéž už ničemové zmizí! Dobrořeč, má duše, Hospodinu. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Vzdávejte chválu Hospodinu! Vzývejte jeho jméno! Oznamujte mezi národy jeho činy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Zpívejte mu, opěvujte ho, přemýšlejte o všech jeho divech!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Chlubte se jeho svatým jménem! Ať se raduje srdce těch, kdo hledají Hospodina!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Hledejte Hospodina a jeho sílu! Ustavičně vyhledávejte jeho tvář!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Pamatujte na divy, které vykonal, na jeho znamení, na rozsudky jeho úst,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'vy, símě Abrahama, jeho otroka, synové Jákobovi, jeho vyvolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'On je Hospodin, náš Bůh. Jeho soudy jsou nad celou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Navěky pamatuje na svou smlouvu, na slovo, které přikázal tisíci pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Uzavřel ji s Abrahamem a odpřisáhl ji Izákovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Potvrdil ji Jákobovi jako ustanovení, Izraeli jakožto věčnou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Řekl: Tobě dám kenaanskou zemi, váš dědičný úděl!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Byla vás jen hrstka, nevelký počet, a pobývali jste v ní jako cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Putovali od národa k národu, od jednoho království k jinému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Nedovolil, aby je někdo utlačoval, káral kvůli nim i krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Nesahejte na mé pomazané, mým prorokům neubližujte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Přivolal na zemi hlad, zlomil každou hůl chleba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Poslal před nimi muže prodaného do otroctví -- Josefa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Sevřeli mu nohy do okovů, na jeho duši dolehlo železo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'až do chvíle, kdy došlo na jeho slovo -- řeč Hospodinova ho protříbila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Král poslal a uvolnil ho; vládce národů ho rozvázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Učinil ho pánem svého domu a vládcem všeho svého majetku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Aby připoutal svá knížata ke své duši a aby starcům dal moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'I přišel Izrael do Egypta a Jákob se stal hostem v zemi Chámově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Svůj lid učinil velmi plodným a učinil jej silnějším, než byli jeho protivníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Těm změnil srdce, takže jeho lid nenáviděli a jednali s jeho otroky lstivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Poslal Mojžíše, svého otroka, a Árona, kterého si vyvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Předložili jim záležitosti jeho znamení a divů v Chámově zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Seslal temnotu, způsobil tmu, a ne mohli odporovat jeho slovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Jejich vody proměnil v krev a jejich ryby nechal uhynout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Země se zahemžila žábami -- i v jejich královských komnatách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Přikázal a na celé jejich území se přihnali mouchy a komáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Z jejich dešťů učinil krupobití a blesky po celé jejich zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Potloukl jejich révu i fíkovníky a polámal stromy na jejich území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Přikázal a přitáhly kobylky jelek, kobylky arbe bezpočtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Sežraly veškerou zeleň v jejich zemi, sežraly plody půdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Pobil v jejich zemi vše prvorozené -- prvotinu veškeré jejich síly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Své však vyvedl se stříbrem a zlatem a nikdo z jeho kmenů nebyl vyčerpaný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egypt se radoval, když odcházeli, protože na ně padla hrůza z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Rozprostíral oblak jako oponu -- a v noci oheň, aby jim svítil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Žádali a přivedl jim křepelky; sytil je nebeským chlebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Otevřel skálu a vytryskla voda, jak řeka tekla vyprahlou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'On totiž pamatoval na své svaté slovo a na Abrahama, svého otroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'A tak s veselím vyvedl svůj lid, s jásotem své vyvolené,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'a dal jim země pohanských národů -- obdrželi to, co národy vydřely,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'aby zachovávali jeho ustanovení a střežili jeho zákony. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Haleluja! Chválu vzdejte Hospodinu, protože je dobrý, vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kdo vylíčí Hospodinovy mocné činy? Kdo rozhlásí všechnu jeho chválu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Blahoslavení jsou ti, kdo zachovávají právo, kdo jednají v každé době spravedlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Rozpomeň se na mě, Hospodine, pro přízeň ke svému lidu, navštiv mě svou spásou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'abych viděl dobro tvých vyvolených, abych se radoval radostí tvého národa, abych se chlubil tvým dědictvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Zhřešili jsme jako naši otcové, páchali jsme zlo, jednali jsme ničemně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Naši otcové v Egyptě nepochopili tvé divy, nepřipomínali si tvé hojné milosrdenství, byli vzpurní při moři, při moři Rákosovém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Ale on je zachránil pro své jméno, aby dal poznat svou udatnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Obořil se na Rákosové moře a vyschlo. Vedl je vodními hlubinami jako pustinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Zachránil je z rukou toho, kdo je nenáviděl, vykoupil je z ruky nepřítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Jejich protivníky přikryla voda, nezbyl z nich ani jeden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'I uvěřili jeho slovům, zpívali k jeho chvále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, '⌈Rychle však zapomněli⌉ na jeho skutky, nečekali na jeho rozhodnutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'V pustině ⌈propadli chtivosti,⌉ v pusté krajině pokoušeli Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Splnil jim tedy jejich prosby, leč postihl je úbytěmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'V táboře ⌈žárlili na⌉ Mojžíše i na Árona, Hospodinova svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Země se otevřela a pohltila Dátana a přikryla spolek Abíramův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Proti jejich spolku vzplanul oheň, plamen spálil ničemy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Na Chorébu udělali tele a klaněli se lité modle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Zaměnili svou Slávu za zpodobení býka, který žere trávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Zapomněli na Boha, svého zachránce, který učinil v Egyptě veliké věci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'divy v zemi Chámově, hrůzu vzbuzující činy u Rákosového moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Řekl tedy, že je vyhladí. Ale Mojžíš, jeho vyvolený, se postavil do trhliny před ním, a tak odvrátil jeho rozlícení, aby je nezničil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Pohrdli výbornou zemí, nevěřili jeho slovu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'reptali ve svých stanech, neuposlechli Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Pozvedl tedy proti nim ruku, že je v pustině nechá padnout');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'a že jejich potomstvo nechá padnout mezi pohany a že je rozpráší do různých zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Pak se spřáhli s Baal–peórem a jedli oběti mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Svými činy ho popouzeli k hněvu a dopadla na ně rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'I povstal Pinchas, vykonal soud a rána byla zastavena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Bylo mu to přičteno k spravedlnosti od pokolení do pokolení -- až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'U Vod sváru ho podnítili ke hněvu, kvůli nim se zle vedlo i Mojžíšovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'neboť se vzepřeli jeho Duchu a on svými rty mluvil nerozvážně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Nevyhladili národy, o nichž Hospodin mluvil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'ale smísili se s pohanskými národy a učili se jejich skutkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Sloužili jejich modlářským zpodobeninám a ty se jim staly léčkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Své syny a své dcery obětovali démonům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Prolévali nevinnou krev, krev svých synů a dcer, které obětovali kenaanským modlářským zpodobeninám, a proléváním krve znesvětili zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Svými skutky se poskvrnili; svými činy se dopouštěli smilstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Hospodin vzplál proti svému lidu hněvem a své dědictví si zošklivil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Vydal je do ruky pohanských národů, takže nad nimi vládli ti, kdo je nenáviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Utlačovali je jejich nepřátelé, byli pokořeni, byli pod jejich mocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Mnohokrát je vysvobodil, leč oni se svými úradky vzpírali a pro své viny byli pokořeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'I pohleděl na jejich soužení a vyslyšel jejich nářek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Pamatoval kvůli nim na svou smlouvu a slitovával se podle svého hojného milosrdenství');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'a dal jim dojít slitování před všemi, kdo je odvedli do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Zachraň nás, Hospodine, náš Bože, shromáždi nás z národů, a budeme vzdávat díky tvému svatému jménu a uctívat tě chválami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Požehnán buď Hospodin, Bůh Izraele, od věků až navěky. A všechen lid ať řekne: Amen. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Chválu vzdejte Hospodinu, protože je dobrý, vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Tak ať řeknou Hospodinovi vykoupení, ti, které vykoupil z ruky protivníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Shromáždil je ze zemí, od východu i od západu, od severu i od moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Bloudili pouští, pustou krajinou, cestu ⌈ do města, kde by mohli sídlit,⌉ však nenalezli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Hladověli a žíznili, klesali na duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Když ale ve své tísni úpěnlivě volali k Hospodinu, vysvobozoval je z jejich úzkostí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'a vedl je přímou cestou, až přišli do města, kde mohli sídlit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Ať vzdávají Hospodinu chválu za jeho milosrdenství a za divy, které pro lidi koná:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Duši lačnou nasytil a duši hladovou naplnil dobrými věcmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Seděli v temnotách, v nejhlubší tmě, uvězněni v soužení i v okovech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'neboť se vzepřeli řeči Boží a pohrdli úradkem Nejvyššího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Pokořil tedy jejich srdce trápením; padli, a pomocníka nebylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Když ale ve své tísni úpěnlivě volali k Hospodinu, zachránil je z jejich úzkostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Vyvedl je z temnoty, z nejhlubší tmy, a zpřetrhal jejich pouta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Ať vzdávají Hospodinu chválu za jeho milosrdenství a za divy, které pro lidi koná:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Neboť rozlámal bronzová vrata a rozbil železné závory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Hlupáci bývají pokořeni pro svou věrolomnou cestu a pro své viny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Jejich duše si ošklivila veškerý pokrm, dospěli až k branám smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Když ale ve své tísni úpěnlivě volali k Hospodinu, zachránil je z jejich úzkostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Poslal své slovo a uzdravil je; zachránil je z jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Ať vzdávají Hospodinu chválu za jeho milosrdenství a za divy, které pro lidi koná;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'ať obětují oběti díků a s jásotem vyprávějí o jeho skutcích!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Ti, kdo se na lodích vydali na moře, kdo konali práci na velkých vodách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'ti viděli Hospodinovy skutky a jeho divy na hlubině:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Promluvil a povstal bouřlivý vichr, který zvedal vlny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Stoupali k nebi, klesali do hlubin, jejich duše se v té zhoubě rozplývaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Motali se, potáceli se jako opilec. A veškerá jejich moudrost byla k ničemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Když ale ve své tísni úpěnlivě volají k Hospodinu, vyvádí je z jejich úzkostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Proměnil bouři v utišení, vlnobití utichlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Oni se radovali, že utichlo, a on je dovedl do vytouženého přístavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Ať vzdávají Hospodinu chválu za jeho milosrdenství a za divy, které pro lidi koná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Ať ho vyvyšují v shromáždění lidu, v zasedání starších ať ho chválí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Proměňuje řeky v pustinu, prameny vod ve vyprahlou zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, '⌈úrodnou zemi⌉ v slatinu -- pro zlo těch, kdo v ní sídlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Pustinu mění v jezero, vyprahlou zemi v prameny vod,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'a usazuje tam vyčerpané, aby tam založili město, kde by mohli sídlit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Oseli pole, vysadili vinice -- a sklidili úrodu plodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Bůh jim žehnal a velmi se rozmnožili; nedovoloval, aby jejich dobytka ubývalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Jich však ubývalo a klesali pod hrozným a bolestným útlakem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'když Bůh vylil pohrdání na šlechtice a nechal je bloudit v pustém bezcestí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Nuzného však uvedl do bezpečí před soužením a rodiny rozmnožil jako stádo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Přímí to vidí a radují se, ale každá podlost zavírá ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Kdo je moudrý, bude tyto věci zachovávat a porozumí Hospodinovým milosrdným činům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Píseň. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Mé srdce je pevné, Bože, budu zpívat, pět budu žalmy -- i má sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Probuď se, harfo a lyro, ať jitřenku vzbudím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Budu ti vzdávat chválu mezi lidmi, Hospodine, budu tě opěvovat mezi národy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'protože tvé milosrdenství je velké, sahá až nad nebesa a až do oblak tvá věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Vyvyš se nad nebesa, Bože! Tvá sláva je po vší zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Aby byli vysvobozeni ti, které miluješ, zachraň nás svou pravicí, odpověz mi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Bůh promluvil ve své svatyni: Budu jásat, rozdělím Šekem, rozměřím údolí Sukót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Můj je Gileád, můj je i Manases, Efrajim -- přilba mé hlavy a Juda můj palcát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moáb je mé umývadlo, na Edóm hodím svůj sandál, nad Pelišteou vítězně zakřičím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Kdo mě přivede do opevněného města? Kdo mě dovede do Edómu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Zdali ne ty, Bože? Odvrhls nás, Bože, a nevycházíš s naší armádou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Zajisti nám pomoc proti protivníkům, vždyť lidská záchrana je klamná!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, 'S Bohem si budeme počínat udatně, on pošlape naše protivníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Pro vedoucího chval. Davidův žalm. Bože, má chválo, nebuď hluchý,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'neboť se otevřela proti mně ústa ničemná a podlá! Lživý jazyk mluví proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Obklopili mě nenávistnými slovy, bojují proti mně bezdůvodně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Za mou lásku se mi jen protiví, ⌈ale já jsem modlitba sama.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Za dobro mi připravují zlo a za mou lásku nenávist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Ustanov nad ním ničemu, protivník ať se mu postaví po pravici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Až bude souzen, ať vyjde najevo, že je ničema, a jeho modlitba budiž pokládána za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Kéž jsou jeho dny nemnohé; jeho pověření ať převezme jiný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Kéž jsou z jeho synů sirotci a z jeho ženy vdova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Kéž se jeho synové neustále potácejí po žebrotě; kéž jsou vypuzeni ze svých trosek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Kéž si lichvář políčí na vše, co mu patří, kéž cizáci zaberou výtěžek jeho práce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Kéž nemá nikoho, kdo by mu prokázal milosrdenství; kéž se nikdo nesmiluje nad sirotky po něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Jeho potomstvo ať je vyťato; v příštím pokolení budiž jeho jméno vymazáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Kéž je u Hospodina připomenuta vina jeho otců a hřích jeho matky ať není vymazán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Kéž jsou před Hospodinem ustavičně; kéž je ze země vyhlazena jejich památka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'protože nepamatoval, že má prokazovat milosrdenství, pronásledoval člověka ⌈chudého a nuzného⌉ a zkroušeného v srdci chtěl usmrtit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Miloval proklínání, ⌈ať na něj přijde!⌉ Neměl zalíbení v žehnání, ať se mu vzdálí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Oblékal proklínání jako šaty, ⌈kéž mu zalije nitro jako voda; kéž je mu⌉ jako olej v kostech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Ať je mu jako roucho, kterým se halí, jako opasek, kterým je stále přepásán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'To ať je odměnou od Hospodina těm, kdo mě obviňují, těm, kdo svolávají zlo na mou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Ty však, ⌈Panovníku Hospodine,⌉ jednej se mnou kvůli svému jménu, vždyť tvé milosrdenství je dobré -- vysvoboď mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Vždyť jsem chudý a nuzný, v mém nitru je zraněné srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Scházím jako stín, který se prodlužuje, setřásli mě jako kobylku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Kolena mi klesají postem, mé tělo hubne, ztrácí tuk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Jsem jim jen pro potupu, když mě uvidí, potřásají hlavou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Pomoz mi, Hospodine, můj Bože! Zachraň mě podle svého milosrdenství!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Aby poznali, že to byla tvá ruka, žes to učinil ty, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Oni proklínají, ale ty žehnáš. Povstali, ale budou zahanbeni a tvůj otrok se bude radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Ať obléknou ostudu ti, kdo mě obviňují; ať se přikryjí svou hanbou jak pláštěm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Budu svými ústy mocně vzdávat chválu Hospodinu, uprostřed mnohých ho budu chválit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'neboť se postavil nuznému po pravici, aby ho zachránil před těmi, kdo soudí jeho duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Davidův žalm. Výrok Hospodinův mému pánu: Usedni po mé pravici, dokud nepoložím tvé nepřátele za podnož tvých nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Tvé mocné žezlo vyšle Hospodin ze Sijónu: Panuj uprostřed svých nepřátel!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Tvůj lid přijde dobrovolně v den tvého vojska v důstojné svatosti. ⌈Tvá mládež ti bude rosou z lůna úsvitu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Hospodin přísahal a nebude toho litovat: Ty jsi kněz navěky na způsob Malkísedeka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Panovník po tvé pravici srazí v den svého hněvu krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Bude soudit národy, naplní vše mrtvými těly, srazí hlavu nad velkou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Napije se z potoka na cestě, proto zvedne hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Haleluja! Celým srdcem budu vzdávat Hospodinu chválu v společenství přímých, v shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Velké jsou skutky Hospodinovy, vyhledávané všemi, kdo v nich mají zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Nádherné a důstojné je jeho dílo, jeho spravedlnost trvá navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Zjednal památku svým divům. Hospodin je milostivý a soucitný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Dal potravu těm, kdo se ho bojí, navěky pamatuje na svou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Svému lidu dosvědčil ⌈své mocné jednání:⌉ dal mu dědictví národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Skutky jeho rukou jsou pravda a právo; všechna jeho přikázání jsou věrná,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'spolehlivá navždy a navěky, vydaná v pravdě a přímosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Seslal svému lidu vykoupení, navěky ustanovil svou smlouvu, jeho jméno je svaté a vzbuzuje bázeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Počátek moudrosti je bázeň před Hospodinem; je to velmi rozumné od všech, kdo tak činí. Jeho chvála zůstává navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Haleluja! Blahoslavený je muž, který se bojí Hospodina! Má velké zalíbení v jeho příkazech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Jeho ⌈potomci budou mocnými⌉ v zemi -- pokolení přímých bude požehnané.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'V jeho domě je majetek a bohatství a jeho spravedlnost trvá navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Přímým vzchází v temnotách světlo -- Bůh je milostivý, soucitný a spravedlivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Dobře je tomu, kdo se slitovává a půjčuje; své záležitosti spravuje dle práva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Nikdy se nezhroutí; spravedlivý zůstane v paměti navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Nebojí se zlé zprávy; jeho srdce je pevné, doufá v Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Jeho srdce je upevněné, nebude se bát, až jednou pohlédne na své protivníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Rozděluje, dává chudým, jeho spravedlnost trvá navždy, jeho roh se pozdvihne v slávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Ničema to vidí a hněvá se, skřípe zuby a ochabuje. Choutky ničemů pominou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Haleluja! Chvalte, ⌈otroci Hospodinovi,⌉ chvalte Hospodinovo jméno!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Budiž Hospodinovo jméno požehnáno od nynějška až navěky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Od východu slunce až po západ budiž chváleno jméno Hospodinovo!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Hospodin je vyvýšený nade všemi národy, jeho sláva sahá nad nebesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kdo je jako Hospodin, náš Bůh, jenž tak vysoko trůní?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Sestupuje, aby pohlédl na nebesa a na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Pozvedá chudého z prachu, ze smetiště vytahuje nuzného,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'aby ho posadil s předními muži, s předními muži svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Neplodnou usazuje v domě jako šťastnou matku synů. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Když vyšel Izrael z Egypta, dům Jákobův z lidu ⌈cizí řeči,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'byl Juda jeho svatyní, Izrael jeho vladařstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Moře to vidělo a uteklo, Jordán se obrátil nazpět,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'hory poskakovaly jako berani a pahorky jako jehňata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Co je ti, moře, že utíkáš, Jordáne, že se obracíš nazpět?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Hory, proč poskakujete jako berani, a vy, pahorky, jako jehňata?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Svíjej se, země, před Pánem, před Bohem Jákobovým,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'jenž proměňuje skálu v jezero, křemen ve vodní pramen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ne nás, Hospodine, ne nás, ale své jméno učiň slavným pro své milosrdenství, pro svou věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Proč mají pohanské národy říkat: Nuže, kdepak je ten jejich Bůh?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Náš Bůh je v nebesích. Činí vše, co si přeje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Jejich modlářské zpodobeniny jsou stříbro a zlato, dílo lidských rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Mají ústa, a nemluví, mají oči, a nevidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'mají uši, a neslyší, mají nos, a necítí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'mají ruce, a nehmatají, mají nohy, a nechodí, hrdlem ani nehlesnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Ti, kdo je zhotovují, budou jako ony, všichni, kdo v ně doufají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Izraeli, doufej v Hospodina! On je jejich pomocí a štítem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Dome Áronův, doufej v Hospodina! On je jejich pomocí a štítem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Kdo se bojíte Hospodina, doufejte v něj! On je jejich pomocí a štítem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Hospodin na nás pamatuje a žehná nám; žehná domu Izraelovu, žehná domu Áronovu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'žehná bojícím se Hospodina, malým i velkým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Kéž vám Hospodin přidá -- vám i vašim synům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Jste Hospodinovi požehnaní -- on učinil nebesa i zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Nebesa, nebesa patří Hospodinu, ale zemi dal synům lidským.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Mrtví již nechválí Hospodina, ani nikdo z těch, kdo sestupují do říše ticha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Ale my budeme dobrořečit Hospodinu od nynějška až navěky. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Miluji Hospodina, vždyť slyší můj hlas, mé úpěnlivé prosby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'naklonil ke mně ucho. Po všechny své dny k němu budu volat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Omotaly mě provazy smrti, dolehla na mě tíseň podsvětí, postihlo mě soužení a žal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Vzývám však Hospodinovo jméno. Ach, Hospodine, zachraň mou duši!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Milostivý je Hospodin a spravedlivý, náš Bůh se slitovává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Hospodin chrání prostoduché. Byl jsem zubožený a on mi pomohl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Vrať se, má duše, do svého odpočinutí, protože Hospodin ti prokázal dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Vytrhls mou duši ze smrti, mé oči před slzami, mé nohy před klopýtnutím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Budu chodit před Hospodinem v zemi živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Důvěřoval jsem, i když jsem říkal: Jsem velmi ponížený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Když jsem se unáhlil, řekl jsem: Každý člověk je lhář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Jak se odvděčím Hospodinu za všechno jeho dobrodiní vůči mně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Zvednu kalich spásy a budu vzývat Hospodinovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Své sliby Hospodinu splním před veškerým jeho lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Vzácná je v očích Hospodinových smrt jeho věrných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ach, Hospodine, jsem tvůj otrok, tvůj otrok, syn tvé otrokyně; tys mi rozvázal pouta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Tobě obětuji oběť díků a budu vzývat Hospodinovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Své sliby Hospodinu splním před veškerým jeho lidem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'v nádvořích Hospodinova domu, ve tvém středu, Jeruzaléme. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Chvalte Hospodina, všechny národy, oslavujte ho, všichni lidé,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'neboť ⌈je mocné⌉ nad námi jeho milosrdenství. Hospodinova věrnost trvá navěky. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Chválu vzdejte Hospodinu, protože je dobrý, vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Ať řekne Izrael: Jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Ať řekne dům Áronův: Jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Ať řeknou ti, kdo se bojí Hospodina: Jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'V tísni jsem volal Hospodina. Hospodin mi odpověděl a uvedl mě na prostranno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Hospodin je se mnou, nebojím se. Co mi může udělat člověk?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Hospodin je se mnou, jako můj pomocník. Podívám se na ty, kdo mě nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Lépe je hledat útočiště v Hospodinu než spoléhat na člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Lépe je hledat útočiště v Hospodinu než spoléhat na přední muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Všechny národy mě obklíčily; ve jménu Hospodinově jsem je však odrazil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Obklíčily mě, jak mě obklíčily! Ve jménu Hospodinově jsem je však odrazil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Obklíčily mě jako včely, zhasly jako oheň z trní! Ve jménu Hospodinově jsem je odrazil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Pořádně jsi do mě strčil, abych padl, ale Hospodin mi pomohl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Hospodin je má síla i píseň; stal se mou spásou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, '⌈Hlasitý jásot⌉ i vítězství jsou ve stanech spravedlivých. Hospodinova pravice vykonala ⌈mocné činy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Hospodinova pravice se vyvýšila, Hospodinova pravice vykonala ⌈udatné činy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Nezemřu, budu žít a vypravovat o Hospodinových skutcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Hospodin mě přísně káznil, ale nevydal mě smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Otevřete mi brány spravedlnosti, vejdu jimi a budu vzdávat chválu Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Toto je brána pro Hospodina; touto branou vcházejí spravedliví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Tobě vzdávám chválu, žes mi odpověděl a stal ses mi spásou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Kámen, který zavrhli stavitelé, se stal ⌈hlavou úhlu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Bylo to od Hospodina. V našich očích je to podivuhodné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Tento den učinil Hospodin. Jásejme a radujme se v něm!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ach, prosím, Hospodine, pomoz! Ach, prosím, Hospodine, dopřej úspěch!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Požehnaný, jenž přichází ve jménu Hospodinově! Žehnáme vám z Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Hospodin je Bůh a svítí nám; važte sváteční oběti provazy k rohům oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Ty jsi můj Bůh, budu ti vzdávat chválu. Můj Bože, budu tě vyvyšovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Chválu vzdejte Hospodinu, protože je dobrý, vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Blahoslavení jsou ti, jejichž cesta je bezúhonná, ti, kteří žijí podle zákona Hospodinova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Blahoslavení jsou ti, kdo střeží jeho svědectví a hledají ho celým srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Takoví nepáchají podlosti, chodí po jeho cestách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tys dal svá přikázání, aby se pečlivě zachovávala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Kéž by byly mé cesty upevněny pro zachovávání tvých ustanovení!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Tehdy nebudu zahanben, když si budu hledět všech tvých příkazů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'V upřímnosti srdce ti budu vzdávat chválu, když se učím tvým spravedlivým nařízením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Budu zachovávat tvá ustanovení -- jen mě neopouštěj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Jak si chlapec udrží svou stezku čistou? Tím, že bude zachovávat tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Hledám tě celým svým srdcem, nenech mě zbloudit od svých příkazů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Tvou řeč uchovávám v srdci, abych proti tobě nehřešil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Hospodine, jsi požehnaný! Vyuč mě svým ustanovením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Svými rty vyprávím o všech nařízeních tvých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Z cesty tvých svědectví se veselím jako z celého svého majetku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Přemýšlím o tvých přikázáních a hledím na tvé stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Tvá ustanovení jsou mi potěšením; nezapomínám na tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Prokazuj svému otroku dobro -- budu žít a zachovávat tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Otevři mi oči, abych viděl divy tvého zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Jsem na zemi jen cizincem, neskrývej přede mnou své příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Mou duši stravuje touha po tvých nařízeních za každého času.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Oboříš se na domýšlivce, na proklaté, kteří pobloudili od tvých příkazů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Odval ode mě potupu a pohrdání, neboť střežím tvá svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'I když zasednou knížata a budou mluvit proti mně, tvůj otrok bude přemýšlet o tvých ustanoveních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'I tvá svědectví jsou mým potěšením, jsou to mí rádci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Do prachu je přitištěna má duše; obživ mě podle svého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Vyprávěl jsem o svých cestách a tys mi odpověděl. Vyuč mě svým ustanovením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Dej mi porozumět cestě svých přikázání; přemýšlím o tvých divech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Má duše se rozplývá žalem; pozdvihni mě podle svého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Odvrať ode mě cestu klamu; ⌈milostivě mě obdaruj⌉ svým zákonem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Vyvolil jsem si cestu pravdy, stavím si před sebe tvá nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Přilnul jsem ke tvým svědectvím, Hospodine, kéž nejsem zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Poběžím cestou tvých příkazů, neboť jsi rozšířil mé srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Vyuč mě, Hospodine, cestě svých ustanovení a já je budu důsledně střežit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Dej mi porozumět, budu střežit tvůj zákon a jej zachovávat celým srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Veď mě stezkou svých příkazů, neboť jsem si ji oblíbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Nakloň mé srdce ke svým svědectvím, nikoli k zištnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Odvracej mé oči, abych nehleděl na klam; na své cestě mě obživ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Naplň svému otroku své slovo, jež vede k bázni před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Odvrať ode mě potupu, které se lekám, vždyť tvá nařízení jsou dobrá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Hle, toužím po tvých přikázáních; obživ mě ⌈ve své⌉ spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Kéž ke mně přijde tvé milosrdenství, Hospodine, tvá spása, podle tvého slova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'a já dám odpověď tomu, kdo mě tupí -- vždyť spoléhám na tvé slovo!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Nikdy zcela neodejmi mým ústům pravdivé slovo, protože skládám naději ve tvá nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Tvůj zákon budu zachovávat ustavičně, navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Budu chodit volně, protože jsem vyhledával tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'O tvých svědectvích budu mluvit před králi a nebudu zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Tvé příkazy jsou mi potěšením, zamiloval jsem si je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Zvedám dlaně ke tvým příkazům, jež jsem si zamiloval, přemýšlím o tvých ustanoveních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Pamatuj na slovo ke svému otroku, jímž jsi ve mně vzbudil naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Útěchou v mém soužení mi je, že mi tvé slovo navrací život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Domýšlivci se mi hrozně posmívají; od tvého zákona se neodvrátím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Připomínám si tvá odvěká nařízení, Hospodine, a nacházím útěchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Přepadá mě vztek kvůli ničemům, kteří opouštějí tvůj zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Tvá ustanovení byla mými písněmi v domě, kde jsem hostem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'V noci si připomínám tvé jméno, Hospodine, a zachovávám tvůj zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Tak tomu se mnou bylo, protože jsem střežil tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Řekl jsem: Můj podíl je Hospodin, a tak budu zachovávat tvá slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Celým srdcem ⌈hledám tvou přízeň,⌉ smiluj se nade mnou podle svého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Přemýšlím o svých cestách a obracím své nohy ke tvým svědectvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Spěchám a neotálím zachovávat tvé příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Omotávají mě provazy ničemů, na tvůj zákon však nezapomínám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Vstávám o půlnoci, abych ti vzdal díky za tvá spravedlivá nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Jsem společníkem všech, kteří se tě bojí, těch, kdo zachovávají tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Hospodine, země je plná tvého milosrdenství; vyuč mě svým ustanovením!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Hospodine, podle svého slova jsi prokázal svému otroku dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Nauč mě rozvážnosti a poznání, vždyť já tvým příkazům věřím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Dokud jsem nebyl pokořen, bloudil jsem; teď však zachovávám tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Jsi dobrý a prokazuješ dobro; vyuč mě svým ustanovením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Domýšlivci ⌈mě obestřeli klamem,⌉ já však celým srdcem střežím tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Bezcitné jak tuk je jejich srdce, já se však těším ze tvého zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Bylo pro mě dobré, že jsem byl pokořen, neboť jsem se naučil tvým ustanovením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Zákon tvých úst je pro mě lepší než tisíce ve zlatě či stříbře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Tvé ruce mě učinily a upevnily. Dej mi porozumět, ať se naučím tvým příkazům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Ti, kdo se tě bojí, mě uvidí a budou se radovat, protože očekávám na tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Vím, Hospodine, že tvá nařízení jsou spravedlivá; pokořils mě pravdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Kéž je mi tvé milosrdenství útěchou, jak jsi svému otroku zaslíbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Kéž na mě přijde tvé slitování, ⌈abych mohl žít,⌉ neboť tvůj zákon je mým potěšením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Kéž jsou domýšlivci zahanbeni, neboť mi zrádně křivdí; já ale přemýšlím o tvých přikázáních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Kéž se ke mně vrátí ti, kdo se tě bojí, ti, kdo znají tvá svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Kéž je mé srdce bezúhonné podle tvých ustanovení, abych nebyl zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Má duše chřadne touhou po tvé spáse; očekávám na tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Zrak mi slábne, jak vyhlížím, kdy promluvíš. Říkám si: Kdy už mě potěšíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Byl jsem sice jako měch v dýmu, na tvá ustanovení jsem ale nezapomněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Kolik dnů ještě má tvůj otrok? Kdy už vykonáš soud nad mými pronásledovateli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Domýšlivci mi vykopali jámy, což není podle tvého zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Všechny tvé příkazy jsou pravda. Zrádně mě pronásledují, pomoz mi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Málem už se mnou v zemi skoncovali, ale já jsem tvá přikázání neopustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Podle svého milosrdenství mě zachovej při životě; budu střežit svědectví tvých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Hospodine, tvé slovo je navěky ustaveno v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Z pokolení do pokolení trvá tvá pravda. Upevnil jsi zemi a ona stojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Dodnes stojí podle tvých nařízení, neboť to vše jsou tvoji otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Kdyby tvůj zákon ne byl mým potěšením, byl bych už ve svém soužení zahynul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Na tvá přikázání nikdy nezapomenu, neboť mi dávají život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Jsem tvůj -- pomoz mi, vždyť vyhledávám tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Ničemové na mě čekají, aby mě zničili. Rozvažuji o tvých svědectvích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Vidím dovršení všeho dokonalého. Šíře tvých příkazů je nezměrná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Jak jsem si zamiloval tvůj zákon! Celý den ⌈ o něm rozjímám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Tvé příkazy mě činí moudřejším nad mé nepřátele -- navěky jsou mé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Jednám rozumněji než všichni mí učitelé, neboť ⌈rozjímám o tvých svědectvích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Pochopil jsem víc než starci, protože střežím tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Před každou zlou stezkou jsem zdržel své nohy, abych zachoval tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Neodchýlil jsem se od tvých nařízení, neboť tys mě vyučil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Jak ⌈příjemné jsou⌉ mému patru tvé řeči, mým ústům jsou sladší než med.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Díky tvým přikázáním jsem mnohému porozuměl, proto nenávidím každou stezku klamu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Tvé slovo je lampou pro mé nohy, je světlem na mé stezce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Přísahal jsem -- a také to splním -- že budu dbát na tvá spravedlivá nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Byl jsem velmi pokořen, Hospodine, obživ mě podle svého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Kéž laskavě přijmeš dobrovolné oběti mých úst, Hospodine, nauč mě svým nařízením!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Stále vystavuji svůj život nebezpečí, na tvůj zákon nezapomínám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Ničemové mi nastražili past; od tvých přikázání jsem však nezbloudil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Tvá svědectví jsem obdržel do věčného dědictví, ano, jsou radostí mému srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, '⌈Uložil jsem si v srdci,⌉ že budu navěky a důsledně plnit tvá ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Nenávidím polovičaté lidi, ale miluji tvůj zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Jsi má skrýš a můj štít; očekávám na tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Odstupte ode mě, zlovolníci! Budu dodržovat příkazy svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Podpírej mě, jak jsi řekl, abych mohl žít; nezahanbuj mě v mé naději!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Posilni mě, abych byl zachráněn; stále budu hledět na tvá ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Zavrhuješ všechny, kdo zbloudili od tvých ustanovení, neboť jejich záludnost je zrádná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Všechny ničemy v zemi odstraňuješ jako strusku, proto jsem si zamiloval tvá svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Mé tělo se chvěje strachem z tebe, bojím se tvých nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Konám právo a spravedlnost; neponechej mě mým utlačovatelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, '⌈Zaruč se za svého otroka⌉ k dobrému, ať mě domýšlivci neutlačují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Zrak mi slábne, jak vyhlížím tvou spásu a tvůj spravedlivý výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Jednej se svým otrokem podle svého milosrdenství; vyuč mě svým ustanovením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Jsem tvůj otrok -- dej mi porozumět, abych poznal tvá svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Je čas, aby Hospodin jednal, porušují tvůj zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Proto miluji tvé příkazy více než zlato, víc než zlato ryzí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Proto považuji všechna přikázání za zcela správná, nenávidím každou stezku klamu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Tvá svědectví jsou podivuhodná, proto je má duše střeží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Otevření tvých slov osvěcuje, dává porozumět prostoduchým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Otvírám ústa a ⌈jsem plný dychtivosti,⌉ jak toužím po tvých příkazech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Pohleď na mě a smiluj se nade mnou, ⌈jak je tvým zvykem⌉ vůči těm, kdo milují tvé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Mé kroky upevni svými výroky, aby mě neovládla žádná nepravost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Vykup mě z útlaku lidí a budu zachovávat tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Svou tvář rozjasni nad svým otrokem, vyuč mě svým ustanovením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Proudy slz se mi řinou z očí, protože lidé nezachovávají tvůj zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Spravedlivý jsi, Hospodine, a tvá nařízení jsou přímá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Přikázal jsi, aby tvá svědectví byla spravedlivá a zcela pravdivá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Má horlivost mě strávila, neboť mí protivníci zapomněli na tvá slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Tvá řeč je důkladně protříbená; tvůj otrok ji miluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Jsem nepatrný a pohrdaný, ale na tvá přikázání jsem nezapomněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Tvá spravedlnost je spravedlivá navěky; tvůj zákon je pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Dolehla na mě tíseň a úzkost; tvé příkazy jsou mi potěšením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Spravedlnost tvých svědectví je věčná. Dej mi porozumět, abych mohl žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Volám celým srdcem, odpověz mi, Hospodine! Tvá ustanovení dodržuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Volám k tobě: Zachraň mě! Budu zachovávat tvá svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Vstávám před rozedněním a volám o pomoc -- očekávám na tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Mé oči se probouzí dřív než noční hlídky, abych přemýšlel nad tvými výroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Vyslyš můj hlas podle svého milosrdenství, Hospodine, podle svých nařízení mě obživ!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Blíží se ⌈ti, kdo se ženou⌉ za hanebností a vzdalují se od tvého zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Ty jsi blízko, Hospodine; všechny tvé příkazy jsou pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Již dávno jsem z tvých svědectví poznal, že jsi je založil navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Pohleď na mé soužení a vytrhni mě, vždyť na tvůj zákon nezapomínám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Veď mou při a vykup mě, obživ mě podle svého slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Ničemům je spása vzdálena, protože se nedotazují na tvá ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Tvé slitování je veliké, Hospodine, podle svých nařízení mě obživ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Mnoho je mých pronásledovatelů a protivníků, neodvracím se však od tvých svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Vidím věrolomníky a pociťuji odpor, vždyť nezachovávají tvé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Pohleď, Hospodine, zamiloval jsem si tvá přikázání. Podle svého milosrdenství mě obživ!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Princip tvého slova je pravda a každé tvé spravedlivé nařízení je navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Knížata mě bezdůvodně pronásledují; mé srdce se třese před tvým slovem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Jásám nad tvým slovem jako ten, kdo nalezl velikou kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Nenávidím klam, oškliví se mi; miluji tvůj zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sedmkrát za den tě chválím za tvá spravedlivá nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Hojný pokoj mají ti, kdo milují tvůj zákon; nic jim není překážkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Vyhlížím tvou spásu, Hospodine, a plním tvé příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Má duše zachovává tvá svědectví; velmi je miluji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Zachovávám tvá přikázání a tvá svědectví, neboť všechny mé cesty jsou před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Kéž můj nářek předstoupí před tebe, Hospodine, podle svého slova mi dej porozumět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Kéž má úpěnlivá prosba přijde před tebe, podle svého slova mě vysvoboď!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Mé rty překypují chválou, neboť mě učíš svým ustanovením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Ať můj jazyk promlouvá tvé slovo, protože všechny tvé příkazy jsou spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Kéž je mi tvá ruka ku pomoci, vždyť jsem si zvolil tvá přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Toužím po tvé spáse, Hospodine, tvůj zákon je mi potěšením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Kéž má duše žije a chválí tě, kéž mi tvá nařízení pomáhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Bloudím jako ztracená ovce -- hledej svého otroka, vždyť jsem na tvé příkazy nezapomněl!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Píseň stupňů. K Hospodinu jsem volal ve svém soužení a on mi odpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Hospodine, vysvoboď mou duši od lživých rtů, od záludného jazyka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Co ti učiní a co ti přidá, záludný jazyku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Hrdinovy ostré šípy, k tomu řeřavé uhlí z janovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, '⌈Běda mi!⌉ Vždyť pobývám v Mešeku, přebývám při stanech Kédarců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Již dlouho přebývá má duše s tím, kdo nenávidí pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, '⌈Jsem člověk pokojný,⌉ ale když promluvím, oni chtějí bojovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Píseň stupňů. Pozvedám svůj zrak k horám. Odkud mi přijde pomoc?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Pomoc mi přijde od Hospodina, který učinil nebesa i zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Nedovolí, aby tvá noha uklouzla, tvůj strážce nedříme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Ano, strážce Izraele nedříme a nespí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Hospodin je tvůj strážce, Hospodin je ti stínem po pravici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Ve dne tě nebude bít slunce, ani měsíc v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Hospodin tě bude chránit ode všeho zlého, bude chránit tvou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Hospodin bude chránit tvé vycházení i vcházení od nynějška až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Píseň stupňů, Davidova. Zaradoval jsem se, když mi řekli: Půjdeme do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Naše nohy již stojí ve tvých branách, Jeruzaléme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jeruzalém je zbudován jako město, které je uzavřeným celkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Tam vystupují kmeny, kmeny Hospodinovy, ⌈svědectví Izraeli,⌉ aby vzdávaly díky jménu Hospodinovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Vždyť tam stojí soudní stolce, stolce domu Davidova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Žádejte o pokoj pro Jeruzalém! Ať se daří těm, kdo tě milují!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Budiž pokoj na tvých valech, mír ve tvých palácích!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Kvůli svým bratřím a svým blízkým prohlašuji: Kéž je v tobě pokoj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Kvůli domu Hospodina, našeho Boha, usiluji o tvé dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Píseň stupňů. Pozvedám své oči k tobě, jenž na nebesích trůníš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Hle, jako oči otroků k rukám jejich pánů, jako zraky otrokyně k rukám její paní, tak naše zraky vzhlížejí k Hospodinu, našemu Bohu, dokud se nad námi nesmiluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Smiluj se nad námi, Hospodine, smiluj se nad námi, už jsme dost nasyceni pohrdáním!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Naše duše je zcela přesycena posměchem sebejistých a pohrdáním pyšných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Píseň stupňů, Davidova. Kdyby Hospodin nebyl s námi -- Izrael ať řekne --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'kdyby Hospodin nebyl s námi, když proti nám povstali lidé,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'tu by nás zaživa zhltli, jak proti nám pláli hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Tu by nás zaplavily vody, převalil by se přes nás proud,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'tu by se přes nás valily zpěněné vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Požehnán buď Hospodin, že nás nevydal za kořist jejich zubům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Naše duše unikly jako ptáček z čihařského osidla. Osidlo je protrženo -- a my jsme unikli!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Naše pomoc je ve jménu Hospodinově, který učinil nebesa i zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Píseň stupňů. Kdo doufají v Hospodina, jsou jako hora Sijón -- nepohne se, zůstává navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, '⌈ Jako je Jeruzalém obklopen horami,⌉ tak Hospodin obklopuje svůj lid -- od nynějška až na věky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Žezlo ničemnosti nesetrvá nad losem spravedlivých, aby spravedliví nevztáhli své ruce k zvrácenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Hospodine, prokaž dobro dobrým, těm, kdo jsou přímí v srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Ty, kdo se uchylují na své křivolaké stezky, zavede Hospodin mezi činitele nepravosti. Pokoj s Izraelem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Píseň stupňů. Když Hospodin ⌈vrátil sijónské navrátilce,⌉ ⌈bylo nám jak ve snách.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Tehdy naše ústa naplnil smích a náš jazyk jásal; tehdy se mezi národy říkalo: Hospodin s nimi učinil velké věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Hospodin s námi učinil velké věci -- byli jsme plni radosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Hospodine, změň náš úděl, jako měníš řečiště v Negebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ti, kdo v slzách rozsévají, budou s jásotem sklízet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Ten, kdo chodí a s pláčem ⌈nosí mošnu se semenem,⌉ přijde a s jásotem bude snášet snopy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Píseň stupňů, Šalomounova. Pokud Hospodin nebuduje dům, marně se na něm namáhají stavitelé. Pokud Hospodin nestřeží město, marně bdí strážce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Marné je pro vás časně vstávat, pozdě usedat a jíst chléb trápení, vždyť Bůh dává svému milému spánek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Hle, synové jsou dědictví od Hospodina, plod lůna je mzda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Jako šípy v ruce hrdiny jsou synové zrození v mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Blahoslavený je muž, který jimi naplnil svůj toulec! Nebudou zahanbeni, až budou v bráně mluvit s nepřáteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Píseň stupňů. Blahoslavený je každý, kdo se bojí Hospodina, ten, kdo chodí po jeho cestách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Jistě budeš jíst výtěžek svých rukou, bude ti blaze, bude ti dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Tvá žena bude jako úrodná réva uvnitř tvého domu, tví synové jako výhonky oliv kolem tvého stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Hle, takto bude požehnáno muži, který se bojí Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Kéž ti požehná Hospodin ze Sijónu -- pak budeš hledět na dobro Jeruzaléma po všechny dny svého života');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'a uvidíš syny svých synů. Pokoj nad Izraelem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Píseň stupňů. Velice mě sužovali od mého mládí -- Izrael ať řekne --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'velice mě sužovali od mého mládí, avšak nepřemohli mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Po zádech mi orali oráči, a to pěkně dlouhé brázdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Spravedlivý Hospodin přeťal provazy ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Ať se zastydí, ať odtáhnou zpět všichni, kdo nenávidí Sijón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Ať jsou jako tráva na střechách, která uschne dřív, než ji vytrhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Žnec si jí dlaň nenaplní, ani náruč ten, kdo sbírá snopy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'A ti, kdo je potkají, jim neřeknou: Požehnání Hospodinovo budiž s vámi; žehnáme vám ve jménu Hospodinově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Píseň stupňů. Z hlubin k tobě volám, Hospodine!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Panovníku, vyslyš můj hlas! Kéž jsou tvé uši pozorné k mým úpěnlivým prosbám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Pokud budeš ⌈hledět na nepravosti,⌉ Panovníku Hospodine, kdo obstojí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Ale u tebe je odpuštění -- proto vzbuzuješ bázeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Očekávám na Hospodina, očekává duše má, čekám na jeho slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Má duše ⌈ vyhlíží Panovníka víc než strážní jitro,⌉ víc než strážní jitro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Čekej, Izraeli, na Hospodina, vždyť u Hospodina je milosrdenství, hojné je u něho vykoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'On vykoupí Izrael ze všech jeho nepravostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Píseň stupňů, Davidova. Hospodine, mé srdce se nepovyšuje a mé oči nejsou povýšené. Nevstupuji do velkých věcí, do divů, které jsou nade mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Což jsem nezklidnil a ne utišil svou duši? Jako odstavené dítě u své matky, jako odstavené dítě je ve mně má duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Čekej, Izraeli, na Hospodina, od nynějška až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Píseň stupňů. Hospodine, pamatuj na Davida, na všechnu jeho starostlivost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'jak přísahal Hospodinu, slib učinil Mocnému Jákobovu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Nevejdu do stanu svého domu, nevstoupím na své lože,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'nedám spánek svým očím, dřímotu svým víčkům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'dokud nenaleznu místo pro Hospodina, příbytky Mocnému Jákobovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Hle, slyšeli jsme o ní v Efratě, nalezli jsme ji na Jaarských polích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Vstupme do jeho příbytků, klaňme se u podnože jeho nohou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Povstaň, Hospodine, k místu svého odpočinku, ty i truhla tvé moci!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Tvoji kněží ať obléknou spravedlnost, tví věrní ať jásají!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Pro Davida, svého otroka, neodmítni svého pomazaného!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Hospodin přísahal Davidovi věrnost, neodvrátí se od ní: Dosadím na tvůj trůn z plodu tvých beder.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Jestliže tví synové budou zachovávat mou smlouvu a má svědectví, kterým je budu učit, i jejich synové budou sedět na tvém trůnu až na věky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Hospodin totiž vyvolil Sijón, zatoužil mít jej za sídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Toto je místo mého odpočinku až navěky, tady budu sídlit, neboť po něm toužím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Velice požehnám jeho zásobám, jeho chudé budu sytit chlebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Jeho kněze oději spásou, jeho věrní budou radostně jásat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Tam dám vyrůst Davidovu rohu, připravím lampu svému pomazanému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Jeho nepřátele obléknu hanbou, ale na něm rozkvete jeho koruna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Píseň stupňů, Davidova. Hle, jak je dobré a příjemné, když bratři přebývají pospolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Jako vonný olej na hlavě, stékající na vous, na vous Áronův, stékající na otvor jeho roucha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'jako chermónská rosa, jež padá na sijónské hory. Tam totiž Hospodin přikázal své požehnání, život až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Píseň stupňů. Hle, dobrořečte Hospodinu všichni jeho otroci, kteří stojíte za nocí v Hospodinově domě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Pozvedejte ruce ke svatyni a dobrořečte Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Hospodin ti žehnej ze Sijónu; on učinil nebesa i zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Haleluja! Chvalte Hospodinovo jméno, chvalte je, Hospodinovi otroci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'kteří stojíte v domě Hospodinově, v nádvořích domu našeho Boha!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Chvalte Hospodina, neboť Hospodin je dobrý, opěvujte jeho jméno, neboť je líbezné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Vždyť Hospodin si vyvolil Jákoba, Izraele za své vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Ano, vím, že Hospodin je velký -- náš Pán je nade všechny bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Hospodin činí vše, co chce -- na nebesích, na zemi, v moři i ve všech hlubinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Přivádí mlhu od končin země, s deštěm působí i blesky, ze svých skladů vyvádí vítr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Egyptské prvorozené pobil od člověka až po dobytče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Seslal znamení a divy doprostřed tebe, Egypte, na faraona a na všechny jeho otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Vyhubil mnohé národy a pobil mocné krále --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Síchona, krále emorejského, a Óga, krále bášanského, a všechna království Kenaanu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'a dal jejich zemi v dědictví, v dědictví Izraeli, svému lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Hospodine, tvé jméno je věčné! Hospodine, tvá památka od pokolení do pokolení!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Vždyť Hospodin zjedná právo svému lidu a nad svými otroky pocítí lítost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Pohanské modlářské zpodobeniny jsou stříbro a zlato, dílo lidských rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Mají ústa, a nemluví, mají oči, a nevidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'mají uši, a nenaslouchají. A v jejich ústech není dech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Ti, kdo je zhotovují, budou jako ony, všichni, kdo v ně doufají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Dome Izraelův, dobrořečte Hospodinu! Dome Áronův, dobrořečte Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Dome Léviův, dobrořečte Hospodinu! Kdo se bojíte Hospodina, dobrořečte Hospodinu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Požehnán buď Hospodin ze Sijónu -- ten, jenž přebývá v Jeruzalémě. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Chválu vzdejte Hospodinu, protože je dobrý -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Chválu vzdejte Bohu bohů -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Chválu vzdejte Pánu pánů -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Tomu, jenž jediný koná veliké divy -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Nebesa učinil s důmyslem -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Rozprostřel zemi nad vodami -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Učinil veliká světla -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Slunce, aby vládlo ve dne -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Měsíc a hvězdy, aby vládly v noci -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Pobil Egypt v jeho prvorozených -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'A vyvedl Izraele z jejich středu -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Mocnou rukou a vztaženou paží -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Rákosové moře rozpoltil ve dví -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'A provedl Izraele jeho středem -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Faraona i jeho vojsko uvrhl do Rákosového moře -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Svůj lid vodil pustinou -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Pobil veliké krále -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'A zabil vznešené krále -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Síchona, krále emorejského -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'A Óga, krále bášanského -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Jejich zemi dal do dědictví -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Do dědictví Izraelovi, svému otroku -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'V našem ponížení na nás pamatoval -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'A vytrhl nás z moci našich protivníků -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Dává pokrm veškerému tvorstvu -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Chválu vzdejte Bohu nebes -- vždyť jeho milosrdenství je věčné!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'U řek babylonských -- tam jsme sedávali a plakali, když jsme vzpomínali na Sijón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Své lyry jsme tam věšeli na topoly,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'neboť tam se nás naši věznitelé ptali na slova písní, naši trýznitelé chtěli, abychom se radovali: Zazpívejte nám některé ze sijónských písní!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Jak bychom mohli zpívat Hospodinovu píseň v cizí zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Jestli na tebe zapomenu, Jeruzaléme, ať na mě zapomene má pravice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Ať mi jazyk přilne k patru, jestliže si tě nebudu připomínat, jestliže nebudu považovat Jeruzalém za vrchol své radosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Připomeň, Hospodine, synům Edómu den Jeruzaléma -- jak říkali: Ničte, ničte jej až do základů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Dcero babylonská, budeš zničena -- blahoslavený, kdo ti odplatí za to, cos nám způsobila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Blahoslavený, kdo vezme tvé děti a roztříští je o skálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Davidův. Celým srdcem ti budu vzdávat chválu, před bohy tě budu opěvovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Budu se klanět ke tvému svatému chrámu, tvému jménu budu vzdávat chválu pro tvé milosrdenství a pro tvou věrnost, neboť jsi vyvýšil svou řeč nad každé své jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'V den, kdy jsem volal, jsi mi odpověděl, ⌈naplnil jsi mou duši silou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Hospodine, všichni králové země ti budou vzdávat chválu, až uslyší řeč tvých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Budou zpívat o Hospodinových cestách, neboť Hospodinova sláva je velká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Vždyť Hospodin je vyvýšený, vidí však poníženého. Povýšeného pozná zdaleka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'I kdybych chodil v soužení, zachováš mě při životě. Vztáhneš ruku proti hněvu mých nepřátel a tvá pravice mě zachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Hospodin dokoná za mě. Hospodine, tvé milosrdenství je věčné! Neopouštěj dílo svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Pro vedoucího chval. Davidův žalm. Hospodine, tys mě vyzpytoval a ⌈znáš mě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Ty víš, kdy si sedám a kdy vstávám -- už dávno znáš mé úmysly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Rozebrals mé putování i mé uléhání a dobře znáš všechny mé cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Ještě nemám slovo na jazyku -- hle, Hospodine, ty už všechno víš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Oblehls mě zezadu i zepředu a položils na mě svou dlaň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Úžasné poznání! Úplně mě přesahuje! To nezvládám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kam odejdu před tvým duchem? Kam uteču před tvou tváří?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Vystoupím–li na nebesa, tam jsi ty. Ustelu si v podsvětí, jsi i tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, '⌈ Když se vznesu na křídlech jitřenky⌉ a usadím se ⌈za koncem moře,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'i tam mě bude provázet tvá ruka, tvá pravice se mě chopí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'I kdybych řekl: Jistě mě přikryje tma, i noc se kvůli mně stane světlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Ani tma před tebou není temná, noc ti svítí jako den, temnota jako světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Vždyť tys utvořil mé ledví, utkal jsi mě v lůně mé matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Vzdávám ti chválu za to, jak jsem úžasně stvořen -- vzbuzuje to bázeň. Tvé dílo je obdivuhodné -- má duše to velmi dobře ví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Před tebou nebyla skryta má kostra, když jsem byl utvářen vskrytu, utkán v útrobách země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Tvé oči viděly můj zárodek a do tvé knihy se zapisovaly všechny dny -- utvářely se, ne byl ani jeden z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'A jak vzácné jsou pro mě tvé úmysly, Bože! Jak mnoho jich je!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Kdybych je chtěl spočítat, je jich víc než písku! Procitnu a již jsem s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Bože, kéž bys skolil ničemy. Odstupte ode mě, vy, kdo proléváte krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Oni o tobě mluví se zlými úmysly; nadarmo vyvyšují tvé protivníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Což nemám, Hospodine, nenávidět ty, kdo tě nenávidí? A pociťovat odpor proti těm, kdo proti tobě povstávají?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, '⌈Mám je v dokonalé nenávisti;⌉ jsou mi za nepřátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Vyzpytuj mě, Bože, a poznej mé srdce, zkoumej mě a poznej mé myšlení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'a pohleď, není–li ve mně cesta trápení, a veď mě cestou věčnosti!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Pro vedoucího chval. Davidův žalm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Vysvoboď mě, Hospodine, od člověka zlého, ochraň mě před násilníky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'kteří v srdci vymýšlejí špatnosti a každý den se chystají k bojům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Jazyk si brousí jako hadi, za svými rty mají zmijí jed. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Chraň mě, Hospodine, před rukama ničemů, ochraň mě před násilníky, kteří vymýšlejí, jak mi podrazit nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Pyšní mi nastražili past, rozprostřeli síť z provazů u stezky, položili mi léčky. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Řekl jsem Hospodinu: Ty jsi můj Bůh! Hospodine, vyslyš mé úpěnlivé prosby!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Panovníku Hospodine, má mocná spáso! V den boje mi kryješ hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Hospodine, nesplň ničemovi jeho touhy, ať nedosáhne svých cílů -- vyvyšovali by se. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Hlavu těch, kdo mě obkličují, ať zachvátí trápení jejich rtů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Ať na ně padne řeřavé uhlí, ať je srazí do ohně, někam do rokliny, aby už nepovstali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Člověk pomlouvačného jazyka v zemi neobstojí, ⌈zlo dopadne násilníka ráz na ráz.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Vím, že Hospodin zjedná nuznému právo, chudému spravedlivý soud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, 'Ano, spravedliví budou vzdávat chválu tvému jménu, přímí budou přebývat před tvou tváří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Davidův žalm. Hospodine, volám tě! Pospěš ke mně, vyslyš mě, když tě volám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Kéž je má modlitba přijata jak kadidlo před tvou tváří, pozdvižení mých dlaní jak večerní obětní dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Hospodine, postav stráž k mým ústům, ostrahu ke dveřím mých rtů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Nenakloň mé srdce k něčemu zlému, abych se nedopouštěl ničemností s lidmi, kteří jsou činiteli nepravosti, a nejedl z jejich lahůdek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Ať mě spravedlivý ztluče -- bude to milosrdenství; ať mě kárá. ⌈ Ať se má hlava nebrání nejlepšímu oleji -- a ještě se budu v jejich nouzi⌉ modlit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Ti, kdo je soudí, budou svrženi ze skály. A oni uslyší, že mé řeči potěšují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Jako když se země převrací a poltí, naše kosti se válejí u chřtánu podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'K tobě, Panovníku Hospodine, hledí mé oči, v tobě hledám útočiště, nevylij mou duši!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Chraň mě před těmi, kdo mi nastražili osidlo, před léčkami činitelů nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Ničemové ať sami upadnou do svých tenat, zatímco já projdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Davidova meditace. Modlitba, když byl v jeskyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Můj hlas zní k Hospodinu -- o pomoc volám; můj hlas zní k Hospodinu -- prosím o smilování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Vylévám před ním svůj nářek, povídám před ním o svém soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Když můj duch ve mně umdlévá, ty znáš moji stezku. Na cestě, kterou kráčím, mi nastražili past.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Pohleď napravo a uvidíš, že nikdo není na mé straně. Pozbyl jsem svého útočiště, na mé duši nikomu nezáleží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Volám k tobě o pomoc, Hospodine! Říkám: Tys mé útočiště, můj podíl v zemi živých!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Věnuj pozornost mému nářku, vždyť jsem velmi zubožený. Vysvoboď mě od mých pronásledovatelů, neboť jsou silnější než já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, 'Vyveď mou duši z vězení, abych vzdával díky tvému jménu. Obklopí mě spravedliví, neboť mi prokazuješ dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Davidův žalm. Hospodine, slyš mou modlitbu, vyslyš mé úpěnlivé prosby! ⌈Ve své věrnosti mi odpověz pro svou spravedlnost!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Nevcházej v soud se svým otrokem, neboť před tebou není spravedlivý nikdo z živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Nepřítel pronásleduje mou duši, sráží můj život k zemi, nutí mě přebývat v temnotách jako ty, kdo jsou již dávno mrtví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Můj duch ve mně umdlévá, mé srdce je v mém nitru zmateno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Připomínám si dávné dny, rozjímám o všech tvých skutcích, přemýšlím o díle tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Vztahuji své ruce k tobě, má duše po tobě žízní jak vyprahlá zem. Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Pospěš, Hospodine, odpověz mi, můj duch chřadne. Neskrývej přede mnou svou tvář! Byl bych podobný těm, kdo sestupují do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Oznam mi zrána své milosrdenství, vždyť doufám v tebe! Dej mi poznat cestu, kterou mám jít; vždyť k tobě pozvedám svou duši!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Vysvoboď mě od nepřátel, Hospodine, v tobě se skrývám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Nauč mě dělat to, co je ti milé, vždyť jsi můj Bůh! Tvůj dobrý Duch nechť mě vede po rovné zemi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Pro své jméno, Hospodine, mě zachovej při životě, ve své spravedlnosti vyveď mou duši z tísně!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Ve svém milosrdenství znič mé nepřátele, odstraň všechny protivníky mé duše, vždyť jsem tvůj otrok!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Davidův. Požehnán buď Hospodin, má skála! On učí mou ruku boji a mé prsty válčit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Mé milosrdenství a má tvrz, můj ⌈nedobytný hrad,⌉ můj vysvoboditel! Je mi štítem, u něj hledám útočiště, on mi podrobuje lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Hospodine, co je člověk, že se k němu znáš? Syn člověka, že na něj myslíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Člověk se podobá vánku, jeho dny pomíjejí jako stín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Hospodine, nakloň svá nebesa a sestup! Dotkni se hor a vzplanou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Udeř bleskem a rozptyl je! Vyšli své šípy a přiveď je do zmatku!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Vztáhni ruku z výše, vyprosť mě a vysvoboď mě z mnohých vod, z ruky cizozemců!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Svými ústy promlouvají klam, jejich pravice je pravice zrádná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Bože, budu ti zpívat novou píseň, budu tě opěvovat při deseti strunné harfě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Ty dáváš spásu králům; ty svého otroka Davida vysvobozuješ od zlého meče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Vyprosť a vysvoboď mě z ruky cizozemců, kteří svými ústy promlouvají klam a jejichž pravice je pravice zrádná!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Naši synové ať jsou ve svém mládí jak vzrostlé štěpy, naše dcery jako vytesané rohové kvádry, jako u chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Naše sýpky ať se naplní ⌈nejrůznějším zbožím,⌉ našeho bravu na našich polích ať jsou tisíce, ba desetitisíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Náš skot ať je obtěžkán, ať nejsou trhliny ani odvlékání ani žalostný křik na náměstích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Blahoslavený lid, s nímž je tomu takto. Blahoslavený lid, jemuž je Hospodin Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Davidova chvála. Budu tě vyvyšovat, Bože můj, králi, a dobrořečit tvému jménu -- navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Každý den ti budu dobrořečit a chválit tvé jméno navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Veliký je Hospodin, je nejvýš chvályhodný, jeho velikost nelze vyzpytovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Od pokolení do pokolení oslavují tvé skutky a zvěstují tvé mocné činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Tvá nádhera je důstojná a slavná, přemýšlím o záležitostech tvých divů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Bude se mluvit o síle tvých hrůzu vzbuzujících činů; ⌈ já budu⌉ vyprávět o tvé velikosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, '⌈Budou vypovídat o památce na tvou velkou dobrotu,⌉ budou jásat nad tvou spravedlností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Hospodin je milostivý a soucitný, pomalý k hněvu a velkého milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Hospodin je ke všem dobrý, má slitování s každým svým dílem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Hospodine, všechna tvá díla ti budou vzdávat chválu; tví věrní ti budou dobrořečit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Budou mluvit o slávě tvého království, budou hovořit o tvé udatnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'aby seznamovali ⌈lidské syny⌉ s tvými mocnými činy a se slávou a nádherou tvého království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Tvé království je království všech věků, tvá vláda trvá po všechna pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Hospodin podpírá všechny padající a pozvedá všechny sklíčené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Oči všech k tobě vzhlížejí a ty jim dáváš potravu ve svůj čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Otvíráš svou ruku a napájíš ⌈přízní všechno živoucí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Hospodin je spravedlivý ve ⌈všech svých cestách⌉ a věrný ve všech svých skutcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Hospodin je blízko všem, kdo k němu volají, všem, kdo ho vzývají v pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Touhu těch, kdo se ho bojí, naplňuje, slyší jejich volání o pomoc a zachraňuje je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Hospodin chrání všechny, kdo ho milují, ale všechny ničemy vyhladí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Má ústa budou mluvit o Hospodinově chvále, veškeré tvorstvo bude dobrořečit jeho svatému jménu navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Haleluja! Chval, duše má, Hospodina!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Budu chválit Hospodina po celý svůj život, budu opěvovat svého Boha, dokud budu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Nespoléhejte na přední muže, na člověka, v němž není záchrana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Jeho duch odchází, on se vrací zpět do své země; v ten den ⌈je po⌉ jeho nápadech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Blahoslavený je ten, jehož pomocí je Bůh Jákobův, ten, jenž má naději v Hospodinu, svém Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'který učinil nebesa i zemi, moře a vše, co je v nich, který navěky zachovává věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'On zjednává právo utlačovaným a dává chléb hladovým. Hospodin osvobozuje vězně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Hospodin otvírá oči slepým, Hospodin pozvedá sklíčené, Hospodin miluje spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Hospodin chrání cizince, podpírá sirotka a vdovu, maří však cestu ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Hospodin bude kralovat věčně, tvůj Bůh, Sijóne, po všechna pokolení. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, '⌈Haleluja! Jak dobré je ⌉ opěvovat našeho Boha, jak líbezná, krásná je chvála!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Hospodin buduje Jeruzalém, on shromažďuje zapuzené Izraelce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Uzdravuje ty, kdo mají zlomené srdce; obvazuje jejich rány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'On ⌈určuje počet⌉ hvězd a všem jim dává jména.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Velký je náš Pán, je velmi mocný, jeho rozumnost nelze změřit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Hospodin podpírá pokorné, ničemy snižuje až k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Zpívejte Hospodinu děkovnou píseň, při lyře opěvujte našeho Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'který pokrývá nebesa oblaky a připravuje zemi déšť, který dává vyrůst trávě na horách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'dává dobytku jeho potravu, i havraním mláďatům, když křičí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Nemá zalíbení v síle koně, netouží po lýtkách muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Hospodin nachází zalíbení v těch, kdo se ho bojí; v těch, kdo očekávají na jeho milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Jeruzaléme, oslavuj Hospodina! Chval svého Boha, Sijóne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'On upevnil závory tvých bran, požehnal tvým synům ve tvém středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Na tvém území zajišťuje pokoj, sytí tě tou ⌈nejlepší pšenicí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Posílá svůj výrok na zem -- rychle běží jeho slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Dává sníh jako vlnu, jíní sype jako popel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Vrhá celé kousky ledu -- kdo obstojí před jeho mrazem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Pošle své slovo a taje, vyžene svůj vítr a vody se řinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Oznámil své slovo Jákobovi, svá ustanovení a nařízení Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Tak žádnému národu neučinil -- jeho nařízení nepoznaly. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Haleluja! Chvalte Hospodina z nebes! Chvalte jej na výšinách!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Chvalte jej, všichni jeho andělé! Chvalte jej, všechny jeho zástupy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Chvalte jej, slunce i měsíc! Chvalte jej, všechny jasné hvězdy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Chvalte jej, nebesa nebes, i vody, které jsou nad nebesy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Ať chválí jméno Hospodinovo, neboť on přikázal a byly stvořeny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'upevnil je navěky a navždy, stanovil hranice, které nepřekročí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Chvalte Hospodina ze země, draci a všechny propasti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Ať ho chválí oheň a kroupy, sníh a mlha, bouřlivý vítr, jenž činí jeho slovo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'pohoří a všechny pahorky, ovocný strom i všechno cedroví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'divá zvěř a všechna dobytčata, plazi i okřídlené ptactvo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'králové země a všechny národy, knížata i všichni, kdo soudí zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'mládenci i panny, staří i mladí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Ať chválí Hospodinovo jméno, neboť jen jeho jméno je vyvýšené, jeho velebnost je nad zemí i nebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Vyvýšil roh svého lidu, chválu všech svých věrných, synů Izraele, lidu, který je mu blízký. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Haleluja! Zpívejte Hospodinu novou píseň, jeho chválu v shromáždění věrných!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Ať se Izrael raduje ze svého Tvůrce, ať synové Sijónu jásají nad svým králem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Ať chválí tancem jeho jméno, ať ho opěvují s tamburínou a lyrou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Hospodin má zalíbení ve svém lidu, pokorné ozdobí spásou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Věrní ať se radují v slávě, ať jásají ve svých leženích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Ať svým hrdlem vyvyšují Boha -- s oboustranným mečem v rukách');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, '-- aby vykonali pomstu nad pohany, tresty nad národy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'aby řetězy spoutali jejich krále a jejich slovutné železnými okovy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'aby na nich vykonali soud, jak byl zapsán. Je to čest pro všechny jeho věrné. Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Haleluja! Chvalte Boha v jeho svatyni! Chvalte ho na nebeské klenbě, plné jeho moci!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Chvalte ho za jeho mocné činy! Chvalte ho za jeho nesmírnou velikost!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Chvalte ho dutím na beraní roh, chvalte ho na harfu a lyru!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Chvalte ho tamburínou a tancem, chvalte ho strunami a píšťalou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Chvalte ho činely hlasitými, chvalte ho činely zvučnými!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, '⌈Vše, co dýchá,⌉ ať chválí Hospodina! Haleluja!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Přísloví izraelského krále Šalomouna, syna Davidova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'k poznání moudrosti a kázně, k porozumění řečem rozumným,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'k ⌈přijetí rozumné kázně,⌉ spravedlnosti, práva a přímosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'aby dala prostoduchým chytrost a mládenci poznání a rozvahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Ať je slyší moudrý a přibude mu bystrosti, ať rozumný získá schopnost vést,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'aby dokázal porozumět přísloví a podobenství, slovům moudrých i jejich hádankám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Počátek poznání je bázeň ⌈ před Hospodinem,⌉ moudrostí a kázní pohrdají hlupáci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Můj synu, slyš naučení svého otce, nezavrhuj poučení své matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Neboť jsou půvabným věncem na tvou hlavu a náhrdelníkem na tvůj krk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Můj synu, kdyby tě hříšníci lákali, nepřivoluj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Kdyby říkali: Pojď s námi, nastražíme léčku, ⌈abychom prolili krev,⌉ počíháme si bezdůvodně na nevinného,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'jako podsvětí je pohltíme zaživa, muže v plné síle jako ty, kdo sestupují do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Získáme všelijaký vzácný majetek, naplníme si domy kořistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, '⌈Nech svůj los padnout s námi,⌉ budeme mít všichni jeden měšec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Můj synu, ⌈nechoď s nimi po cestě,⌉ ⌈zdrž svou nohu od jejich stezky,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'neboť jejich nohy běží za zlem, pospíchají prolévat krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Vždyť nadarmo se roztahuje síť před zraky ⌈těch, co mají křídla.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Ale tito nastražují léčku k prolití vlastní krve, číhají na svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, '⌈Tak dopadne každý,⌉ kdo pro sebe nekalý zisk hrabe. Připraví svého pána o duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Moudrost křičí na ulicích, na náměstích pozvedá svůj hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Volá na nároží rušných ulic, u vchodů do bran, ve městě pronáší svou řeč:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Dokdy budou prostoduší milovat prostoduchost, posměvači si budou libovat v posmívání a hlupáci budou nenávidět poznání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Obraťte se, ⌈když vás kárám!⌉ Hle, vyleji na vás svého ducha, dám vám poznat svá slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Protože jsem volala, ale odmítali jste, vztahovala jsem svou ruku, ale nikdo nedával pozor,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'nevšímali jste si žádné mé rady a mému pokárání jste se nepodvolili,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'také já se budu vysmívat vaší pohromě, posmívat se, když přijde ⌈to, čeho se strachujete, ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'když jako ničivá bouře přijde ⌈to, čeho se strachujete⌉ a vaše pohroma jako vichřice, když na vás přijde soužení a strast.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Tehdy mě budou volat, ale neodpovím, budou mě usilovně hledat, ale nenaleznou mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Protože nenáviděli poznání a nezvolili si bázeň před Hospodinem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'nepodvolili se mé radě a odvrhli každé moje pokárání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'budou jíst ovoce své cesty, nasytí se svými radami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Vždyť odvrácení prostoduchých je zabije, bezstarostnost hlupáků je zahubí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Ale kdo mě poslouchá, bude přebývat v bezpečí, ⌈bude bezstarostný, beze strachu ze zla.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Můj synu, jestliže přijmeš mé řeči a uchováš u sebe mé příkazy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'učiníš své ucho vnímavé pro moudrost a nakloníš své srdce k rozumnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'jestliže zavoláš na porozumění a pozvedneš svůj hlas k rozumnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'jestliže ji budeš hledat jako stříbro, pátrat po ní jako po skrytých pokladech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'tehdy porozumíš bázni před Hospodinem a získáš poznání Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Vždyť moudrost dává Hospodin a z jeho úst pochází poznání a rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Uchovává úspěch pro přímé, je štítem pro ty, kdo žijí bezúhonně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'střeží stezky práva a chrání cestu svých věrných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Tehdy porozumíš spravedlnosti, právu a přímosti, každé dobré stezce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'neboť moudrost vstoupí do tvého srdce a poznání ⌈tvou duši potěší;⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'rozvaha bude tebe chránit, rozumnost tě bude střežit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Vysvobodí tě od zlé cesty, od člověka, který mluví obojace,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'od těch, kteří opouštějí přímé stezky, aby chodili po temných cestách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'od těch, kdo mají z páchání zla radost a nad zlými obojakostmi kdo jásají,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'jejichž cesty jsou křivolaké, kteří bloudí na svých stezkách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Vysvobodí tě od cizí ženy, od cizinky s jejími ⌈úlisnými řečmi,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'od té, která opouští důvěrníka svého mládí a na smlouvu svého Boha zapomněla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Vždyť její dům se nachyluje k smrti, její stezka vede k nebožtíkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Nikdo z těch, kdo k ní vcházejí, se nenavrátí, nedosáhnou ⌈stezek života.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Proto choď po cestě dobrých lidí a zachovávej stezky spravedlivých,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'neboť přímí se usídlí v zemi a bezúhonní v ní zůstanou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'ale ničemové budou ze země vyhlazeni a nevěrníci z ní budou vyrváni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Můj synu, nezapomínej na mé poučení, ať tvé srdce střeží moje příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Vždyť ti přidají dlouhá léta a roky života i pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, '⌈Milosrdenství a věrnost⌉ ať tě neopouštějí! Přivaž si je ke svému krku, napiš je na tabulku svého srdce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Tak nalezneš milost a oblibu v očích Božích i lidských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Důvěřuj Hospodinu celým svým srdcem, nespoléhej se na svoji rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Poznávej ho na všech svých cestách, a on napřímí tvé stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Nebuď moudrý ve svých očích, boj se Hospodina a odvrať se od zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'To bude uzdravením pro tvé tělo a občerstvením pro tvé kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Cti Hospodina svým majetkem a prvotinami ze vší své úrody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Tvé sýpky se naplní hojností a tvé sudy budou přetékat novým vínem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Hospodinovu kázeň, můj synu, nezavrhuj, neměj odpor k jeho pokárání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'neboť koho Hospodin miluje, toho kárá jako otec syna, jehož si oblíbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Blahoslavený je člověk, který našel moudrost, člověk, který získal rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Neboť ⌈zisk z ní je lepší, nežli zisk ze stříbra⌉ a její výnos je nad zlato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Je vzácnější nežli drahokamy, ⌈nic z toho, po čem toužíš,⌉ se jí nevyrovná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'V její pravici jsou dlouhá léta a v její levici bohatství a sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Její cesty jsou cesty příjemné, všechny její stezky jsou pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Je ⌈stromem života⌉ pro ty, kdo se jí chopí, ti, kdo se jí drží, jsou šťastní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Moudrostí Hospodin položil základy země, rozumností upevnil nebesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Jeho poznáním se rozevřely hlubiny a oblaky kanou rosu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Můj synu, ať nesejdou z tvých očí; střež obezřetnost a rozvahu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'a budou životem pro tvou duši a ozdobou pro tvůj krk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Tehdy půjdeš bezpečně svou cestou a tvoje noha neklopýtne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Když ulehneš, nebudeš se strachovat; lehneš si, a tvůj spánek bude příjemný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Neboj se náhlého strachu, ani když přijde ničivá bouře na ničemy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Neboť Hospodin ti bude po boku a bude chránit tvou nohu před polapením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Neodpírej dobro ⌈těm, kterým náleží,⌉ když je ve tvé moci ho prokázat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Neříkej svému bližnímu: „Odejdi a pak se vrať, dám ti zítra,“když to máš u sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Nekuj zlo proti svému bližnímu, když s tebou v důvěře bydlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Neveď s nikým bezdůvodně při, jestliže ti nezpůsobil zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Nezáviď násilníkovi, nevol žádnou z jeho cest,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'neboť Hospodinu je odporný ten, kdo bloudí, ale s přímými důvěrně hovoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Na domě ničemy je Hospodinova kletba, ale příbytku spravedlivých žehná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Posměvačům se posmívá, ale pokorným dává milost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Moudří zdědí slávu, ale hlupáci si odnesou hanbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Synové, slyšte otcovo naučení, pozorně naslouchejte, abyste poznali rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Vždyť vám dávám dobrou nauku, moje poučení neopouštějte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Když jsem byl synem u svého otce, útlým jedináčkem pro svou matku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'učil mě a říkal mi: Ať tvé srdce uchopí má slova, zachovávej mé příkazy a budeš žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Získej moudrost, získej rozumnost! Nezapomínej a neodvracej se od řečí mých úst!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Neopouštěj ji a bude tě chránit, miluj ji a bude tě střežit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Počátek moudrosti je: Získej moudrost! Za všechno své vlastnictví získej rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Vysoce si jí važ a vyvýší tě; když ji obejmeš, poctí tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Vloží na tvou hlavu půvabný věnec, předá ti krásnou korunu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Slyš, můj synu, přijmi mé řeči, a rozmnoží se ti roky života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Učím tě moudré cestě, vedu tě po přímých stezkách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Když půjdeš, nebude zdržován tvůj krok, když poběžíš, neklopýtneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Uchop naučení a neopouštěj, střež ho, vždyť je tvůj život!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Na stezku ničemů nevstupuj, nechoď po cestě zlých lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Nevšímej si jí, neprocházej po ní, odvrať se od ní a přejdi ji!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Neboť neusnou, pokud nespáchají zlo, je jim odebrán spánek, pokud nepřivedou někoho k pádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Protože jedí chléb ničemnosti a pijí víno násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Stezka spravedlivých je jako záře úsvitu, září víc a víc, až do bílého dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Ale cesta ničemů jako tma, nevědí, oč klopýtnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Můj synu, věnuj pozornost mým slovům, nakloň ucho k mým řečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Ať nesejdou z tvých očí, střež je v hloubi svého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Neboť jsou životem pro ty, kdo je nalézají, uzdravením pro celé jejich tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Víc než ⌈cokoliv jiného ⌉ střež své srdce, protože z něj ⌈ vycházejí prameny života.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Odstraň ⌈faleš ze svých úst⌉ a ⌈převrácené rty od sebe vzdal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Ať tvé oči hledí vpřed a tvá víčka ⌈míří přímo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Srovnej stezku pro svůj krok, všechny tvé cesty ať jsou připravené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Neuchyl se v pravo, v levo, odvrať nohu od zlého!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Můj synu, věnuj pozornost mé moudrosti, nakloň ucho k mé rozumnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'abys zachoval rozvahu a aby tvé rty střežily poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Vždyť ze rtů cizí ženy kape med a její řeč je hladší nežli olej,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'ale ⌈její konec je hořký jako pelyněk, ostrý jako dvojsečný meč.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Její nohy sestupují ke smrti, ⌈ do podsvětí její kroky směřují.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Nesrovnává cestu života, ⌈její stezky se klátí, ani to neví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Nyní mě, synové, slyšte, neodvracejte se od řečí mých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, '⌈Vzdal od ní svou cestu,⌉ nepřibližuj se ke vchodu jejího domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'jinak dáš svou slávu jinému a svoje roky ukrutníkovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'jinak se cizinci nasytí tvojí silou a tvoje námaha půjde do cizího domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Nakonec budeš úpět, až bude celé tvé tělo úplně zničeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Pak řekneš: Jak to, že jsem nenáviděl kázeň a mé srdce odvrhlo pokárání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Neposlouchal jsem své učitele a k těm, kteří mě učili, jsem nenakláněl ucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, '⌈Málem jsem se uprostřed shromáždění a obce ocitl ve všem zlu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Pij vodu ze své cisterny, bystrou vodu ze své studny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Mají se tvoje prameny rozlévat na ulici, proudy vody na náměstí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Ať ⌈patří tobě samému,⌉ a ne cizím spolu s tebou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Ať je požehnaný tvůj pramen, raduj se z ženy svého mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Ta líbezná laň, ta půvabná srna, její prsy ať tě uspokojují v každé době, její láskou se opájej ustavičně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Proč by ses měl, můj synu, opájet cizí ženou, objímat klín cizinky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Vždyť cesty člověka jsou před očima Hospodina, on srovnává všechny jeho stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Ničemu polapí jeho vlastní viny, provazy svého hříchu bude zajat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Zemře, protože ne měl kázeň, pro velikost své hlouposti bude vrávorat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Můj synu, jestliže ses zaručil za svého bližního, ⌈zavázal ses rukoudáním⌉ za cizince,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'a byls řečmi svých úst chycen, řečmi svých úst byls polapen,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'učiň tedy toto, můj synu, aby ses zachránil. Protože ses dostal do ruky svého bližního, jdi, pokoř se a naléhej na svého bližního!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Nedopřej svým očím spánku ani dřímoty svým víčkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Zachraň se jako gazela z ruky lovce a jako pták z ruky ptáčníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Jdi k mravenci, lenochu, podívej se na jeho cesty, abys zmoudřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Ačkoliv nemá vůdce, dozorce ani vládce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'připravuje si v létě pokrm, shromažďuje ve žni svou potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Dokdy budeš ležet, lenochu? Kdy se probereš ze spánku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Trochu spánku, trochu dřímoty, trochu složit ruce a poležet si --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'a tvá chudoba přijde jako tulák a tvá nouze jako ozbrojenec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Ničemník a darebák je ten, kdo chodí s falešnými ústy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'mrká očima, dává znamení nohama, ukazuje svými prsty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, '⌈V jeho srdci je obojakost, v každé době kuje zlo, zasévá sváry.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Proto náhle přijde na něj pohroma, v okamžiku bude rozdrcen a nebude pro něj uzdravení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Šest věcí Hospodin nenávidí a sedmá je pro něj ohavností:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Povýšené oči, lživý jazyk, ruce, které prolévají nevinnou krev,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'srdce, které kuje zlé plány, nohy, které ⌈rychle běží⌉ za zlem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'falešného svědka, který šíří lži, a toho, jenž zasévá sváry mezi bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Můj synu, střež příkaz svého otce, nezavrhuj poučení své matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Přivaž si je nastálo ke svému srdci, připoutej si je ke krku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Když budeš chodit, povede tě; když budeš ležet, bude tě chránit a když se probudíš, ⌈zaujme tvou pozornost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Vždyť příkaz je lampou, poučení světlem, pokárání a naučení cestou života,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'aby tě ochránily před zlou ženou, před úlisným jazykem cizinky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Nebuď ve svém srdci žádostiv po její kráse, ať se tě nezmocní svými víčky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'protože za prostitutku je jen bochník chleba, ale vdaná žena loví tvůj vzácný život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Cožpak si může někdo shrnout oheň do klína, a nespálit si oděv?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Zdalipak může někdo chodit po řeřavém uhlí, a nespálit si nohy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tak je tomu s tím, kdo vchází k ženě svého bližního; kdokoliv se jí dotkne, nezůstane bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Nepohrdají zlodějem, že kradl, aby se nasytil, když hladoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Když však je dopaden, nahradí to sedmkrát, ⌈ i kdyby měl dát⌉ ⌈všechen majetek svého domu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Kdo cizoloží s ženou, tomu chybí rozum; ničí svou duši, kdo to dělá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Pocítí rány a hanbu, jeho potupa nebude smazána,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'protože žárlivost rozněcuje hněv muže, v den pomsty nebude mít soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, '⌈Nebere ohled⌉ na žádné odškodné, nepodvolí se, i kdyby s rozmnožil dary.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Můj synu, zachovávej mé řeči a mé příkazy chovej u sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Zachovávej mé příkazy a budeš žít, střež moje poučení jako zřítelnici svých očí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Přivaž si je na prsty, napiš je na tabulku svého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Řekni moudrosti: „ Jsi moje sestra,“rozumnost nazvi svojí příbuznou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'aby tě chránily před cizí ženou, před cizinkou s jejími úlisnými řečmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Když ⌈ jsem byl u⌉ okna svého domu, pohleděl jsem za okenní mříž');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'a uviděl jsem mezi prostoduchými, rozpoznal jsem mezi mládeží chlapce, jemuž chyběl rozum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Přecházel po ulici poblíž nároží, kráčel směrem k jejímu domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'za soumraku, k večeru, uprostřed noci a tmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'A hle, jde mu naproti žena, oblečená jako prostitutka a se srdcem záludným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Je halasná a nevázaná, její nohy ⌈nemají doma stání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Hned je na ulici, hned na náměstích, na každém rohu číhá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Už ho drží, políbí ho a s nestoudnou tváří mu řekne:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '⌈Měla jsem obětovat pokojné oběti,⌉ dnes jsem splnila svoje sliby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Proto jsem ti vyšla naproti, abych tě usilovně hledala a našla jsem tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Pokryla jsem svou pohovku přikrývkami, pestrobarevným egyptským plátnem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Navoněla jsem svou postel myrhou, aloe a skořicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Tak pojď, opájejme se milováním až do rána, potěšme se láskou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Vždyť můj muž ne ní doma, odešel na dalekou cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Měšec s penězi si vzal s sebou, přijde domů v den úplňku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Přesvědčila ho svým mnohým přemlouváním, svými úlisnými rty jej svedla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Hned za ní jde, jako chodí vůl na porážku, či jako skáče jelen do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Až mu šíp probodne játra; jako pták pospíchá do pasti a neví, že mu jde o život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Nyní mě, synové, slyšte, věnujte pozornost řečem mých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Ať se tvé srdce neobrátí k jejím cestám, ať nezabloudíš na její stezky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'neboť je mnoho pobitých, které nechala padnout, všech, které zabila, je bezpočet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Její dům -- toť cesty do podsvětí, vedoucí dolů do kobek smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Cožpak moudrost nevolá, rozumnost ne pozvedá svůj hlas?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Na vrchu výšin, podél cest, na křižovatce postává;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'u bran, při vstupu do města, u vchodu do bran křičí:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Na vás, muži, volám, můj hlas zní k lidským synům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Prostoduší, získejte chytrost, hlupáci, dostaňte rozum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Slyšte, protože promluvím znamenité věci, ⌈mé rty vysloví, co je správné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Vždyť má ústa ⌈si opakují pravdu,⌉ ničemnost je ohavností pro mé rty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Všechny řeči mých úst jsou spravedlivé, ne ní v nich nic pokrouceného ani pokřiveného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Všechny jsou jasné pro toho, kdo je schopen rozumět, přímé pro ty, kdo nalézají poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Přijměte mé naučení, a ne stříbro, poznání je víc než pročištěné zlato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Vždyť moudrost je lepší nežli drahokamy, nic z toho, po čem toužíš, se jí nevyrovná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Já, moudrost, bydlím s chytrostí, nalézám poznání a rozvahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Bázeň před Hospodinem znamená nenávidět zlo; povýšenost, pýchu, zlou cestu a obojaká ústa, to nenávidím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Má je rada i úspěch, jsem rozumnost, má je síla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Skrze mě králové kralují a mocnáři ustanovují spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Skrze mě vládnou vládcové i šlechtici, všichni spravedliví soudcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Já miluji ty, kteří milují mě; kdo mě usilovně hledají, naleznou mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'U mne je bohatství i sláva, trvalý majetek i spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Mé ovoce je lepší nežli zlato, byť seberyzejší, výnos ze mne je nad pročištěné stříbro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Chodím po cestě spravedlnosti a po stezkách práva,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'abych dala dědictví těm, kteří mě milují a naplnila jejich sklady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Hospodin mě vytvořil na počátku své cesty, dávno před svými činy, již tenkrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Odvěků jsem byla utvořena, od počátku, od dávnověku země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Když ještě nebyly hlubiny, zrodila jsem se, ještě když nebyly prameny obtěžkány vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Dříve nežli byly hory ponořeny, před kopci jsem se zrodila;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'když ještě neučinil zemi a pláně, ani první prach světa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'když založil nebesa, byla jsem tam; když vyměřoval obzor nad mořskou hlubinou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'když upevnil oblaka nahoře, když posilnil prameny mořské hlubiny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'když postavil moři jeho hranici, aby voda nepřekračovala jeho příkaz, když vyměřoval základy země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'byla jsem vedle něho jako řemeslník, byla jsem jeho potěšením den za dnem, radovala jsem se před ním po celou dobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Radovala jsem se z celé jeho země, ⌈mé potěšení bylo ⌉ s lidskými syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Nyní mě, synové, slyšte: Blahoslavení jsou ti, kdo dbají na mé cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Poslechněte naučení, abyste zmoudřeli, nebuďte nevšímaví!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Blahoslavený je člověk, který mě poslouchá, den za dnem bdí u mých dveří, střeží veřeje mých bran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Vždyť kdo mě nachází, nachází život, dosáhne zalíbení u Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Ale kdo proti mně hřeší, činí násilí své duši, všichni, kdo mě nenávidí, milují smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Moudrost postavila svůj dům, vytesala svých sedm sloupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Porazila ⌈svůj jatečný dobytek,⌉ namíchala své víno, připravila také svůj stůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Poslala své služky, volá na nejvyšších místech města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '„Kdo je prostoduchý, ať sem odbočí!“Komu chybí rozum, tomu říká:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '„Pojďte a jezte z mého pokrmu, napijte se z vína, které jsem namíchala!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Opusťte prostoduchost a budete žít, jděte zpříma po cestě rozumnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Ten, kdo poučuje posměvače, sklidí hanbu a kdo kárá ničemu, bude mít potupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Nekárej posměvače, jinak tě bude nenávidět. Kárej moudrého a bude tě milovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Dej moudrému a ještě zmoudří, pouč spravedlivého a přibude mu bystrosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Počátek moudrosti je bázeň před Hospodinem, poznání Svatého je rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Neboť skrze mne se rozmnoží tvé dny a přibude ti let života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Jestliže jsi zmoudřel, zmoudřel jsi pro sebe, jestliže se budeš posmívat, sám ⌈poneseš důsledky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Paní Hloupost je halasná, prostoduchá, ⌈nic neví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Usadila se u vchodu do svého domu, na křesle na vysokých místech města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Aby volala na ty, kdo procházejí kolem, kdo jdou přímo po svých stezkách:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '„Kdo je prostoduchý, ať sem odbočí!“Komu chybí rozum, tomu říká:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '„Kradená voda je sladká, potajmu získaný pokrm potěší.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'On však neví, že jsou tam nebožtíci, že ti, které pozvala, jsou v hlubinách podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Šalomounova přísloví. Moudrý syn dělá radost otci, ale hloupý syn je žalem pro svou matku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Ničemně získané poklady neprospějí, ale spravedlnost vysvobodí od smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Hospodin nenechá hladovět spravedlivého, ale maří choutky ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Nedbalá ruka způsobuje chudobu, avšak ruka pilných získává bohatství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Rozumný syn v létě sklízí, ale syn, který zaspí žeň, jedná hanebně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Požehnání je na hlavě spravedlivého, avšak ústa ničemů přikrývají násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Památka spravedlivého je požehnaná, ale jméno ničemů zpráchniví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Kdo má moudré srdce, přijme příkazy, avšak ⌈žvanivý hlupák⌉ bude sražen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kdo žije bezúhonně, bude žít v bezpečí, kdo však převrací své cesty, bude odhalen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Kdo mrká okem, působí bolest, avšak žvanivý hlupák bude sražen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Ústa spravedlivého jsou pramenem života, ale ústa ničemů přikrývají násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Nenávist podněcuje sváry, ale láska přikrývá všechna přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Na rtech rozumného se nalézá moudrost, ale hůl je na záda toho, komu chybí rozum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Moudří si ukládají poznání, ale hlupákova ústa jsou blížící se zkázou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Majetek bohatého je jeho pevným městem, zkázou chudých je jejich chudoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Výdělek spravedlivého je k životu, výnos ničemy ke hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Kdo zachovává naučení, je na stezce k životu, kdo však opouští pokárání, vede do bludu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Kdo zakrývá nenávist, má lživé rty, a kdo vynáší pomluvy, je hlupák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Při množství slov se člověk nevyhne přestoupení, kdo však ovládá své rty, je rozumný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Jazyk spravedlivého je jako pročištěné stříbro, srdce ničemů má malou cenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Rty spravedlivého budou pást mnohé, ale hlupáci zemřou na nedostatek rozumu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Hospodinovo požehnání obohacuje a ⌈námaha k němu nic nepřidá.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Pro hlupáka je povyražením provádět zlé úmysly, pro rozumného muže je jím však moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Čeho se ničema hrozí, to na něj přijde, ale touha spravedlivých bude naplněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Když se přežene vichřice, ničema již není, spravedlivý však má věčný základ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Čím je ocet pro zuby a kouř pro oči, tím lenoch pro ty, kteří ho posílají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Bázeň před Hospodinem přidá mnohá léta, ale roky ničemů budou zkráceny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Očekávání spravedlivých je radost, avšak naděje ničemů zahyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, '⌈Hospodinova cesta⌉ je pevností pro bezúhonného, ale zkázou pro zločince.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Spravedlivý se nikdy nepohne, ničema však zemi neosídlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Ústa spravedlivého plodí moudrost, ale obojaký jazyk bude vyťat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Rty spravedlivého znají, ⌈co je milé,⌉ ústa ničemů však obojakost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Falešné váhy jsou pro Hospodina ohavností, ⌈milé je mu⌉ ⌈správné závaží.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Když přijde domýšlivost, přijde i hanba, s pokornými je však moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, '⌈Přímé povede jejich bezúhonnost,⌉ kdežto podvodníky zničí jejich lest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Majetek neprospěje v den hněvu, ale spravedlnost vysvobodí od smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Bezúhonnému napřímí cestu spravedlnost, avšak ničema svou ničemností padne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Přímé vysvobodí jejich spravedlnost, ale podvodníci budou polapeni svými choutkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Při smrti ničemného člověka hyne jeho naděje a očekávání násilníků zahyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Spravedlivý je vysvobozen ze soužení, ničema se však dostane na jeho místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Bezbožný ústy ničí svého bližního, ale spravedliví budou vysvobozeni poznáním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Když je spravedlivým dobře, město se veselí a když hynou ničemové, volá radostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Požehnáním přímých se město pozvedá, ale ústy ničemů se boří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Kdo pohrdá svým bližním, tomu chybí rozum, zatímco rozumný muž bude mlčet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, '⌈Kdo roznáší pomluvy,⌉ odhaluje důvěrnosti, kdo však je spolehlivý, přikrývá věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Když není vedení, lid padne, záchrana je v množství rádců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Velmi zle se bude tomu dařit, kdo se zaručí za cizince, kdo však nenávidí zaručování, je v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Půvabná žena získá slávu, udatní muži získají bohatství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Milosrdný člověk ⌈působí své duši dobro,⌉ ale ukrutník ⌈činí svému tělu potíže.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Ničema získává klamný výdělek, avšak ten, kdo rozsévá spravedlnost, sklízí pravou mzdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Věru, spravedlnost vede k životu, ale kdo se žene za zlem, míří k smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, '⌈ Ti, kdo mají pokřivené srdce, jsou pro Hospodina ohavností,⌉ avšak ti, kteří žijí bezúhonně, jsou mu milí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Zcela jistě zlý nezůstane bez trestu, ale potomstvo spravedlivých unikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Zlatý kroužek na rypáku vepře je žena krásná, ale nerozvážná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Touhou spravedlivých je jen dobro, avšak nadějí ničemů je hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Někdo rozhazuje, a ještě mu přibývá, jiný šetří víc než je správné, a je mu to jen k nouzi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Štědrý člověk bude prospívat, ten, kdo napájí, také sám bude napojen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Toho, kdo zadržuje zrno, budou lidé proklínat, ale požehnání spočine na hlavě toho, kdo ho prodává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kdo usilovně hledá dobro, hledá oblibu, avšak kdo hledá zlo, na toho zlo přijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Ten, kdo doufá ve své bohatství, padne, ale spravedliví se budou zelenat jako listí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kdo činí potíže své rodině, zdědí vítr, a hlupák bude otrokem tomu, kdo má moudré srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Ovoce spravedlivého je stromem života a ten, kdo získává duše, je moudrý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Jestliže spravedlivému bude na zemi odplaceno, tím spíše ničemovi a hříšníkovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kdo miluje kázeň, miluje poznání, ale kdo nenávidí pokárání, je tupec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Dobrý člověk dosáhne zalíbení u Hospodina, ale pleticháře Hospodin prohlásí vinným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Člověk nebude pevně stát skrze ničemnost, avšak kořen spravedlivých se nepohne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Zdatná žena je korunou svého manžela, ale jako hniloba v jeho kostech je ta, která dělá hanbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Myšlenky spravedlivých jsou právo, úmysly ničemů jsou podvod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Slova ničemů -- číhání na krev, kdežto přímé vysvobodí jejich ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Vyvrátit ničemy a už nejsou, ale dům spravedlivých obstojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Člověk bude chválen podle své rozumnosti, kdo však má zvrácenou mysl, bude v pohrdání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Je lepší být znevažován a mít otroka, nežli se vytahovat a nemít pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Spravedlivý bere ohled na život svého zvířete, avšak i slitovné činy ničemů jsou kruté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kdo obdělává svou půdu, nasytí se pokrmem, ale tomu, kdo se žene za prázdnými věcmi, chybí rozum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Ničema dychtí po kořisti zlých, avšak kořen spravedlivých vydává ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'V přestoupení rtů je léčka pro zlého člověka, ale spravedlivý vyjde ze soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Ovocem svých úst se každý nasytí dobrem, ⌈to, co člověk rukama vykoná,⌉ se mu vrátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, '⌈Hlupákova cesta je přímá v jeho očích,⌉ ale ten, kdo poslouchá radu, je moudrý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Hlupákův hněv se hned projeví, chytrý však hanbu skrývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kdo dává průchod pravdě, oznamuje spravedlnost, falešný svědek ale podvod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Někdo žvaní, jako když bodá mečem, ale jazyk moudrých přináší uzdravení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Pravdivé rty obstojí navěky, kdežto lživý jazyk jen na okamžik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'V srdci těch, kdo kují zlo, je podvod, ale ti, kdo radí ku pokoji, mají radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Spravedlivému se nestane žádné neštěstí, avšak ničemové jsou naplněni zlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Lživé rty jsou pro Hospodina ohavností, avšak ⌈milí jsou mu⌉ ti, kdo jednají věrně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Chytrý člověk skrývá poznání, ale srdce hlupáků vykřikuje hloupost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Ruka pilných bude vládnout, kdežto nedbalá ruka bude konat nucenou práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Obava v srdci člověka zdrcuje, ale dobré slovo mu dává radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Spravedlivý ⌈povede svého bližního,⌉ ničemy však svede jejich cesta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Nedbalý člověk nepeče svůj úlovek, ale ⌈píle je pro člověka vzácný majetek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na cestě spravedlnosti je život, ⌈ na její stezce ne ní smrt.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Moudrý syn přijímá otcovo naučení, ale posměvač neposlouchá napomenutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Z ovoce svých úst bude každý jíst dobro, avšak touhou nevěrných je násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kdo střeží svá ústa, chrání svou duši; kdo příliš otvírá své rty, na toho přijde zkáza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Lenoch dychtí a nic nemá, ale ⌈touha pilných se naplní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Spravedlivý nenávidí klam, ale ničema ⌈jedná odporně a je pro ostudu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Spravedlnost bude střežit toho, ⌈kdo žije bezúhonně,⌉ avšak hříšníka zničí ničemnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Někdo předstírá, že je bohatý, a nic ne má, jiný předstírá, že je chudý, a má mnoho majetku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Výkupné za život člověka je jeho bohatství, ale chudý neslyší hrozbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Světlo spravedlivých bude jasně zářit, avšak lampa ničemů zhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Jen domýšlivost vypůsobí hádku, ale s těmi, kdo se radí, je moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Snadno získaný majetek se bude zmenšovat, kdežto ten, kdo pracně shromažduje, rozmnoží ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Prodlužované očekávání působí srdci bolest, ale naplněná touha je stromem života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Tomu, kdo pohrdá slovem, se povede špatně, avšak kdo se bojí příkazu, tomu bude odplaceno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Poučení moudrého je pramenem života, aby se člověk vyhnul léčkám smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Rozumnost působí milost, ale cesta nevěrných je jejich záhubou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Každý chytrý člověk bude jednat podle poznání, avšak hlupák bude šířit svoji hloupost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Ničemný posel padne do zla, ale spolehlivý vyslanec přinese uzdravení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Chudoba a hanba přijde na toho, kdo si nevšímá naučení, ale kdo zachovává pokárání, bude vážený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Naplněná touha potěší duši, avšak pro hlupáky je ohavností se odvrátit od zla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kdo chodí s moudrými, zmoudří, ale kdo se stýká s hlupáky, tomu se bude dařit zle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Hříšníky bude pronásledovat zlo, avšak spravedlivým bude odplaceno dobrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Dobrý člověk dá dědictví synům synů, ale hříšníkův majetek bude uschován pro spravedlivého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Mnoho jídla vydá úhor chudých, ⌈ale je to smeteno bezprávím.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Kdo zadržuje svou hůl, nenávidí svého syna, kdo ho však miluje, usilovně ho kázní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Spravedlivý jí do sytosti své duše, ale břicho ničemů bude mít nedostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, '⌈Moudrá žena⌉ svůj dům staví, kdežto hloupá ho svýma rukama boří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Ten, kdo žije ve své přímosti, bojí se Hospodina, ale ⌈kdo bloudí po svých cestách,⌉ opovrhuje jím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'V ústech hlupáka je hůl na hrdost, avšak moudré budou chránit jejich rty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Kde není dobytek, je žlab čistý, ale síla býka dává hojnou úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Spolehlivý svědek nelže, avšak falešný svědek šíří lži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Posměvač hledá moudrost, ale ne najde; pro rozumného však je poznání snadné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Odejdi od hloupého muže, tam se nedozvíš rozumná slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Moudrost chytrého člověka je rozumět své cestě, ale hloupost hlupáků je podvod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Hlupáci se budou posmívat oběti za vinu, avšak mezi přímými je v oblibě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Jen srdce zná hořkost své duše, ani ⌈do jeho radosti se cizí člověk nevmísí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Dům ničemů bude zničen, ale stan přímých bude vzkvétat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Některá cesta připadá člověku správná, avšak nakonec je cestou smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'I při smíchu může bolet srdce, na konci radosti je žal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Kdo má odpadlé srdce, nasytí se svými cestami, i dobrý člověk svými skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Prostoduchý věří všemu, ale chytrý zvažuje své kroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Moudrý se bojí a odvrací se od zla, kdežto hlupák jedná ⌈nadřazeně a sebejistě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Popudlivý člověk dělá hlouposti, pletichář bude nenáviděn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Prostoduší zdědí hloupost, ale chytří lidé budou korunováni poznáním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Zlí se sklánějí před dobrými a ničemové v branách spravedlivého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Chudý bude nenáviděn i svým bližním, ale bohatý má mnoho přátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Kdo pohrdá svým bližním, hřeší, avšak kdo se slitovává nad ubohými, je blahoslavený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Cožpak nezabloudí ti, kdo kují zlo? Milosrdenství a věrnost je však s těmi, kdo zamýšlejí dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, '⌈Každá námaha přinese⌉ prospěch, ale prázdné mluvení je jenom k nouzi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Korunou moudrých je jejich bohatství, hloupostí hlupáků je hloupost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Spolehlivý svědek vysvobozuje duše, kdežto falešný šíří lži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'V bázni před Hospodinem má člověk pevnou naději, bude útočištěm pro jeho syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Bázeň před Hospodinem je pramenem života, aby se člověk vyhnul léčkám smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Množství lidu je slávou krále, ale nedostatek lidu je zkázou mocnáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Kdo je pomalý k hněvu, je velice rozumný, kdo však je vznětlivý, ⌈vystavuje na odiv⌉ hloupost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Uzdravené srdce je životem tělu, kdežto závist je hnilobou kostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kdo utlačuje chudého, tupí jeho Tvůrce; kdo se však smilovává nad nuzným, ten ho ctí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Ničema bude sražen, když se mu bude dařit zle, ale spravedlivý má útočiště i při své smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'V srdci rozumného moudrost odpočívá, avšak v nitru hlupáků bude odhalena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Spravedlnost vyvýší národ, ale hřích je hanbou národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Rozumný otrok je králi milý, jeho hněv však přijde na toho, kdo jedná hanebně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Vlídná odpověď odvrátí zlobu, ale slovo, které zraňuje, budí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Jazyk moudrých používá poznání správně, kdežto z úst hlupáků prýští hloupost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Hospodinovy oči jsou na každém místě, pozorně sledují zlé i dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Uzdravený jazyk je stromem života, ale lest na něm je zkázou ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Hlupák odvrhuje naučení svého otce, kdo však zachovává pokárání, je rozumný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'V domě spravedlivého je mnohé bohatství, ale výnos ničemy přináší těžkosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Rty moudrých ⌈budou šířit⌉ poznání, avšak srdce hlupáků nepravost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Oběť ničemů je pro Hospodina ohavností, ale modlitba přímých je mu milá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Pro Hospodina je ohavností cesta ničemy, avšak toho, kdo následuje spravedlnost, bude milovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, '⌈Kázeň je zlem pro toho, kdo opouští stezku,⌉ kdo nenávidí pokárání, zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Před Hospodinem je podsvětí a říše zániku, tím spíše srdce lidských synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Posměvač nebude milovat toho, kdo ho kárá, nepůjde k moudrým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Radostné srdce ⌈prospívá tváři,⌉ ale s bolestí srdce přichází ubitý duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Srdce rozumného bude hledat poznání, avšak ústa hlupáků se budou pást na hlouposti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Všechny dny chudého jsou zlé, ale dobré srdce má ustavičně hostinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Lepší je málo s bázní před Hospodinem, nežli velký poklad a s ním zmatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, '⌈Lepší je jídlo ze zeleniny tam, kde je láska, nežli vykrmený býk a s ním nenávist.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Hněvivý člověk podněcuje svár, kdo však je pomalý k hněvu, uklidňuje hádku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Cesta lenocha je jako trnitý plot, kdežto stezka přímých je připravená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Moudrý syn dělá radost otci, ale hloupý člověk opovrhuje svou matkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Hloupost je radostí pro toho, komu chybí rozum, avšak rozumný člověk ⌈bude napřimovat svou cestu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Kde není důvěrné společenství, plány se hatí, ale při množství rádců se naplní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Člověk má radost z vhodné odpovědi -- jak dobré je slovo v pravý čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Pro rozumného vede stezka života nahoru, aby se vyhnul podsvětí dole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Hospodin strhne dům pyšných, avšak upevní mezník vdovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Pro Hospodina jsou ohavností zlé plány, ale laskavá slova jsou mu čistá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Kdo pro sebe hrabe nekalý zisk, činí potíže své rodině, kdo však nenávidí úplatky, bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Srdce spravedlivého přemítá, jak má odpovědět, kdežto ⌈ z úst ničemů prýští zlé věci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Hospodin je daleko od ničemů, ale modlitbu spravedlivých vyslyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, '⌈Zářivý pohled⌉ dává radost srdci, dobrá zpráva ⌈občerstvuje kosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ucho, které poslouchá života dárné pokárání, bude zůstávat mezi moudrými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kdo si nevšímá naučení, opovrhuje svou duší, ale kdo poslouchá pokárání, získává rozum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Bázeň před Hospodinem je ⌈kázní moudrosti,⌉ ⌈před slávou je ⌉ pokora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Člověk zvažuje v srdci, ale odpověď jazyka je od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Všechny cesty člověka jsou čisté v jeho očích, Hospodin však zkoumá motivy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Uval své dílo na Hospodina a tvé plány obstojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Hospodin všechno udělal pro svůj účel, i ničemu pro zlý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Pro Hospodina je ohavností každý povýšenec, zcela jistě nezůstane bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Milosrdenstvím a věrností bude usmířena vina, od zla se člověk odvrací bázní před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Když Hospodin najde zalíbení v cestách člověka, ⌈dává mu pokoj i od jeho nepřátel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Lepší je málo se spravedlností, nežli hojné výnosy s bezprávím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Srdce člověku vymýšlí cestu, ale jeho kroky určuje Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Věštba je na rtech krále, jeho ústa se nezpronevěří při soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Váhy i spravedlivé misky patří Hospodinu, každé závaží v měšci je jeho dílem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Pro krále je ohavností páchat ničemnost, protože trůn bude pevně stát skrze spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Králům jsou milé spravedlivé rty, milují toho, kdo mluví správné věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Králův hněv je poslem smrti, ale moudrý člověk jej usmíří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'V jasu královy tváře je život, jeho obliba je jako oblak jarního deště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Získat moudrost je mnohem lepší nežli zlato, získat rozumnost je lepší vyvolit nežli stříbro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Cesta přímých je odvrátit se od zla, kdo střeží svou cestu, chrání svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Před zkázou je pýcha, před klopýtnutím bývá povýšenost ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Je lepší být pokorný s chudými nežli dělit kořist s pyšnými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, '⌈Kdo je rozumný v jednání,⌉ nalezne dobro, blahoslavený ten, kdo doufá v Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Kdo má moudré srdce, bude nazván rozumným, příjemná slova přidávají přesvědčivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Rozumnost je pramenem života pro ⌈ty, kdo ji mají,⌉ hloupost je trestem hlupáků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Srdce moudrého člověka činí jeho ⌈řeč rozumnou,⌉ ⌈jeho slovům⌉ přidává přesvědčivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Laskavá slova jsou jako plástev medu, sladká pro duši a uzdravení kostem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Některá cesta ⌈připadá člověku správná,⌉ avšak ⌈nakonec je cestou smrti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Dříč pro sebe dře, neboť ho popohání jeho ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Ničemný člověk připravuje zlo, ⌈na jeho rtech je ⌉ jakoby spalující oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Obojaký člověk zasévá svár, pomlouvač rozlučuje přátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Násilník láká svého bližního a přivede ho na nedobrou cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Kdo mhouří své oči, dělá to, aby vymýšlel obojakost, kdo svírá své rty, dokonal zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Šediny jsou krásnou korunou, na cestě spravedlnosti ji naleznou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, '⌈ Ten, kdo je pomalý k hněvu, je lepší než hrdina,⌉ a kdo ⌈ovládá svůj hněv,⌉ je lepší než ten, kdo dobyl město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Los se vrhá do klína, ale každé rozhodnutí je od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Lepší je suchý kousek chleba a s ním klid, nežli dům plný obětních hodů a hádky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Rozumný otrok bude vládnout nad synem, který jedná hanebně, rozdělí si dědictví s bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Na stříbro je kelímek, na zlato pec, ale srdce zkoumá Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Zločinec věnuje pozornost zlým rtům, lhář poslouchá zkázonosný jazyk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kdo se posmívá chudému, tupí jeho Tvůrce, kdo se raduje z pohromy, nezůstane bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Korunou starců jsou vnuci, okrasou synů jejich otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Pro blázna se nehodí ⌈vznešená slova,⌉ tím méně pro šlechtice slova klamná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Úplatek je jako ⌈kouzelný kámen⌉ v očích jeho dárce, kamkoli se obrátí, bude mít úspěch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kdo přikrývá přestoupení, usiluje o lásku, ale kdo věc roznáší, rozlučuje přátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Toho, kdo je schopen rozumět, zasáhne napomenutí víc než hlupáka sto ran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Zlý hledá jen vzpouru, bude proti němu ale poslán krutý posel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Raději potkat medvědici připravenou o mláďata, jenom ne hlupáka s jeho hloupostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kdo odplácí zlem za dobro, tomu se zlo nehne z domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Začít svár je jako pustit vodu, zanech hádky dříve, než vypukne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kdo ospravedlňuje ničemu, i ten, kdo odsuzuje spravedlivého, oba jsou pro Hospodina ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Na co jsou peníze v ruce hlupáka? Aby si koupil moudrost, když nemá rozum?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Přítel miluje v každé době, bratr se zrodil pro čas soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Člověk, kterému chybí rozum, se zavazuje rukoudáním a zaručuje se za svého bližního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Kdo miluje hádky, miluje přestoupení, kdo si zvyšuje vchod, usiluje o zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Kdo má převrácené srdce, nenalezne dobro, kdo převrací svůj jazyk, padne do zla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Hlupák je svému rodiči k žalu, otec blázna se nebude radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Radostné srdce prospívá jako lék, ale ubitý duch vysušuje kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Ničema bere tajně úplatek, aby převracel stezky práva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Ten, kdo je schopen rozumět, má moudrost přímo před sebou, ale oči hlupáků jsou upřeny do končin země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Syn hlupák je k hněvu svého otce a k hořkosti své rodičce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Pokutovat spravedlivého ne ní dobré, natož bít šlechtice za přímost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Kdo ovládá svou řeč, došel poznání, kdo je rozvážný, je rozumný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'I hlupák, když mlčí, může být považován za moudrého, když zavře své rty, za rozumného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Kdo se odděluje, hledá vlastní touhy, ⌈rozzuří se proti každé obezřetnosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Hlupák nemá zálibu v rozumnosti, ale ⌈ v odkrývání svého vlastního rozumu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Když přijde ničema, přichází také pohrdání a s hanbou potupa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Slova z úst člověka jsou jako hluboká voda, pramen moudrosti je jako proudící potok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ne ní dobré ⌈stranit ničemovi⌉ a ⌈křivdit spravedlivému při soudu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Hlupákovy rty ⌈se dostávají do sporu,⌉ jeho ústa ⌈volají po ranách.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Hlupákovi jsou ústa ke zkáze, vlastní rty jsou jeho duše léčkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Slova pomlouvače jsou jako pamlsky, sestupují do ⌈nejzazších útrob.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Také ⌈ten, kdo je nedbalý⌉ při své práci, je bratrem ničitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Hospodinovo jméno je ⌈pevnou věží,⌉ spravedlivý do ní poběží a bude v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Majetek bohatého je jeho pevným městem a jako vysoká hradba v jeho představě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Před zkázou se srdce člověka povýší, před slávou je pokora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kdo odpovídá dříve, nežli vyslechl, je to jeho hloupost a ostuda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Duch člověka vydrží jeho nemoc, ale kdo unese ubitého ducha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Srdce rozumného poznání získá, ucho moudrých poznání hledá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Dar člověku otevře dveře, povede ho před vysoko postavené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, '⌈ Kdo je první při sporu,⌉ zdá se být spravedlivý, přijde však jeho bližní a prověří ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Los zastaví sváry, rozhodne mezi mocnými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Ukřivděný bratr je nedostupnější nežli pevné město, sváry jsou jako závora pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Ovocem úst člověka se nasytí jeho nitro, nasytí se výnosem svých rtů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'V moci jazyka je smrt i život, kdo ho miluje, nají se jeho ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kdo nalezl ženu, nalezl dobro, dosáhl zalíbení u Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Chudý ⌈úpěnlivě prosí,⌉ ale bohatý odpovídá tvrdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, '⌈Někdo má přátele ke své zkáze,⌉ ale některý přítel přilnul víc než bratr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Lepší je chudý, který žije bezúhonně, nežli ten, kdo má proradné rty a je hlupák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Bez poznání jistě ne ní touha dobrá, ⌈kdo je ukvapený,⌉ hřeší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, '⌈Hloupost člověku podvrací jeho cestu,⌉ ale jeho srdce se rozčiluje na Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Majetek přidává množství přátel, ale chudák ⌈bude svým přítelem opuštěn.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Falešný svědek nezůstane bez trestu, kdo šíří lži, neunikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Mnozí si předcházejí šlechtice, každý je přítelem toho, kdo rozdává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Chudého nenávidí všichni jeho bratři, tím spíše se od něj vzdalují jeho přátelé. ⌈ Svými řečmi je uhání, ale oni nic.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Kdo získá rozum, ⌈miluje svou duši;⌉ kdo zachovává rozumnost, ⌈nalezne dobro.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Falešný svědek nezůstane bez trestu, kdo šíří lži, zahyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Pro hlupáka se nehodí přepych, tím méně, aby otrok vládl nad knížaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Rozumnost činí člověka pomalým k hněvu, jeho okrasou je pomíjet přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Králův hněv je jako řvaní mladého lva, ale jeho obliba je jako rosa na zeleň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Syn hlupák je svému otci pohromou, sváry se ženou jsou jako stálé kapání vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Dům a majetek jsou dědictvím otců, ale rozumná žena je od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Lenost uvrhne do spánku, nedbalý člověk bude hladovět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Kdo zachovává příkaz, chrání svou duši, ⌈kdo opovrhuje svými cestami,⌉ zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Kdo se smilovává nad chudým, půjčuje Hospodinu, ⌈odplatí mu za to, co vykonal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Kárej svého syna, když je naděje, ale ⌈ne dej se unést,⌉ abys ho usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Hněvivý člověk zaplatí pokutu; i když ho vysvobodíš, ještě mu přidáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Poslechni radu, přijmi naučení, abys nakonec zmoudřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'V srdci člověka je mnoho plánů, ale Hospodinův plán se naplní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, '⌈ Od člověka se očekává oddanost,⌉ lépe je být chudý nežli lhář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Bázeň před Hospodinem je k životu, člověk ⌈nasycen uléhá,⌉ ⌈zlo jej nepostihne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Lenoch ponoří ruku do mísy, už ani k ústům ji nezvedne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Udeř posměvače a prostoduchý nabude chytrosti, kárej rozumného a získá poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Syn, který ničí otce či vyhání matku, jedná hanebně a je pro ostudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Můj synu, přestaň poslouchat naučení a zabloudíš od řečí poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Ničemný svědek se bude posmívat právu, ústa ničemů budou hltat zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Pro posměvače jsou připraveny soudy, na záda hlupáků rány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Víno je posměvač, pivo je výtržník; každý, kdo ⌈se jím dává zavést,⌉ není moudrý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, '⌈Hrůza, kterou král nahání,⌉ je jako řvaní mladého lva, kdo ho provokuje, hřeší proti své duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Pro člověka je ctí upustit od hádky, rozzuří se každý hlupák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Lenoch na podzim neorá, potom se při žni dožaduje, ale nic ne ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Plán v srdci člověka je jako hluboká voda, rozumný člověk ji však načerpá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Mnoho lidí vyhlašuje svou oddanost, ale kdo najde věrného člověka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Spravedlivý žije bezúhonně, blahoslavení jsou jeho synové po něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Král sedí na soudcovském stolci a provívá svýma očima každé zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kdo může říct: Očistil jsem své srdce, jsem čistý od svého hříchu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, '⌈ Dvojí závaží⌉ a ⌈dvojí míra,⌉ obojí je pro Hospodina ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Již chlapec se pozná podle svých činů, jestli jsou jeho skutky čisté a správné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ucho, které slyší, a oko, které vidí, Hospodin učinil obojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Nemiluj spánek, jinak zchudneš, otevři své oči a nasytíš se pokrmem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'To je špatné, špatné, říká kupující, ale když odejde, začne se chlubit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, '⌈ Někdo má⌉ zlato a množství drahokamů, ale vskutku drahocenná věc jsou ⌈rozumné rty.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Vezmi mu roucho, neboť se zaručil za cizince a vezmi to od něj do zástavy za cizinku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Člověku je sladký pokrm získaný klamem, ale potom se jeho ústa naplní štěrkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Plány s radou se uskutečňují, proto válku veď se strategií.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Kdo roznáší pomluvu, odhaluje důvěrnosti, proto se nezaplétej se žvanilem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Tomu, kdo proklíná svého otce či svou matku, zhasne jeho lampa v nejhlubší temnotě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Dědictví na počátku kvapně získané nakonec nebude požehnané.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Neříkej: „Odplatím zlo!“Čekej na Hospodina a zachrání tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Pro Hospodina je ohavností dvojí závaží, falešné váhy ne jsou dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Kroky muže jsou od Hospodina; a člověk, jak porozumí své cestě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Léčkou pro člověka je rychle vyslovit: Je to svaté!, a teprve po slibech přemýšlet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Moudrý král provívá ničemy, obrací na ně mlátící kolo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Duch člověka je lampou od Hospodina, prozkoumává nejhlubší nitro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Oddanost a věrnost bude střežit krále, milosrdenstvím podepře svůj trůn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Okrasou mládenců je jejich síla, ozdoba starců šediny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Jizvy a modřiny vyčistí zlo, rány také nejhlubší nitro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Královo srdce je v Hospodinově ruce jako proudy vody, nakloní ho, kamkoli se mu zalíbí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, '⌈Člověku připadá správná každá jeho cesta,⌉ avšak srdce zkoumá Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, '⌈Jednat podle spravedlnosti a práva⌉ je Hospodinu milejší nežli oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Povýšené oči a pýcha srdce, lampa ničemů, je hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Plány jsou pilnému jenom ku prospěchu, ale každý, kdo je ukvapený, dojde jenom nouze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Poklady získané lživým jazykem jsou pomíjivou nicotou těch, kdo usilují o smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Ničemy odvleče jejich násilí, neboť odmítali jednat podle práva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Cesta člověka obtíženého vinou je pokřivená, ale skutky čistého jsou správné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Lepší je bydlet v koutě na střeše nežli společně v domě se svárlivou ženou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Duše ničemy dychtí po zlu, jeho bližní ne najde v jeho očích slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Když je posměvač pokutován, prostoduchý zmoudří, když je moudrý přiváděn k porozumění, přijme poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Spravedlivý pozoruje dům ničemy, ⌈vrhá ničemy do zla.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Kdo zavírá své ucho před voláním chudého o pomoc, bude také volat, a nebude mu odpovězeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Tajný dar utiší hněv, úplatek ve skrytu i silnou zlobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Jednat podle práva je radostí pro spravedlivého, ale zkázou pro zločince.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Člověk, který zabloudí z cesty porozumění, bude odpočívat ve shromáždění nebožtíků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Kdo miluje radovánky, bude nuzným člověkem, kdo miluje víno a olej, nezíská bohatství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Výkupné za spravedlivého je ničema, za přímého podvodník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Lepší je bydlet v pusté zemi, nežli se svárlivou a hněvivou ženou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'V příbytku moudrého je vzácný poklad a olej, avšak hloupý člověk ho pohltí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kdo se žene za spravedlností a milosrdenstvím, nalezne život, spravedlnost a slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Moudrý vstoupil do města hrdinů a strhl pevnost, ve kterou důvěřovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kdo si hlídá ústa a jazyk, chrání svou duši před soužením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Pyšný domýšlivec, jehož jméno je posměvač, jedná v nadutosti domýšlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Lenocha usmrtí jeho touha, protože jeho ruce odmítají pracovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Celý den ⌈touží plný touhy,⌉ zatímco spravedlivý ⌈dá a nebude šetřit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Oběť ničemů je ohavností, tím spíše, když ji přinese se zlým úmyslem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Lživý svědek zahyne, ale člověk, který poslouchá, bude stále promlouvat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Ničemný člověk ⌈ukazuje nestoudnou tvář,⌉ přímý však rozumí své cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Není moudrost, není rozumnost, není plán proti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Kůň se připravuje pro den boje, ale záchrana je od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Lepší je vyvolit dobré jméno nežli velké bohatství, oblibu nežli stříbro a zlato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Bohatý i chudý se potkávají, ⌈Tvůrcem obou je Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Chytrý vidí zlo a ukryje se, prostoduší jdou dál a doplatí na to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Důsledkem pokory a bázně před Hospodinem je bohatství, sláva a život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Na cestě zvráceného člověka jsou trny a pasti; ten, kdo chrání svou duši, bude se od nich držet dále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Vyuč chlapce na počátku jeho cesty, neodvrátí se od ní, ani když zestárne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Bohatý vládne chudým, dlužník je otrokem věřitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Ten, kdo rozsévá zvrácenost, sklidí zlo, hůl jeho hněvu pomine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Kdo je štědrý, bude požehnán, protože dává ze svého pokrmu chudému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Vyžeň posměvače a odejde svár, ustane pře a hanba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kdo miluje čisté srdce ⌈ a rty jsou jeho ozdobou,⌉ bude mít krále za přítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Hospodinovy oči střeží poznání, podvrací záměry nevěrného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Lenoch říká: Na ulici je lev, budu zabit uprostřed náměstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Ústa cizích žen jsou hlubokou jámou; ⌈na koho se Hospodin⌉ hněvá, ten tam spadne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'V srdci chlapce vězí hloupost, hůl a naučení ji od něj vzdálí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Kdo utlačuje chudého, aby rozmnožil svůj majetek, a kdo dává bohatému, oba budou mít jen nouzi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Nakloň své ucho a poslouchej slova moudrých, připrav své srdce pro mé poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Vždyť je příjemné, když je zachováš ve svém nitru, nechť jsou také připravena na tvých rtech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Abys měl v Hospodinu svoji naději, ⌈oznámím to dnes také tobě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Vždyť jsem ti napsal třica tero s radami a poznáním,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'abych tě přivedl k poznání pravdy spolehlivých slov, abys odpověděl pravá slova těm, kteří tě poslali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Neokrádej chudého, protože je chudý, nesrážej nuzného v bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Neboť Hospodin povede jejich spor a oloupí o duši ty, kteří loupí je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Se vzteklounem se nespolčuj, nezůstávej s hněvivým člověkem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'jinak se naučíš jeho způsobům a ⌈dostaneš svou duši do léčky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Nebuď mezi těmi, kdo se zavazují rukoudáním, kdo se zaručují za dluhy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Když nemáš čím zaplatit, proč by měl někdo vzít tvou postel pod tebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Neposouvej dávné mezníky, které postavili tvoji otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Vidíš člověka zběhlého v jeho práci? ⌈Bude sloužit králům,⌉ nebude sloužit obyčejným lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Když se posadíš, abys jedl s vládcem, dobře porozuměj tomu, ⌈co je před tebou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, '⌈Polož si nůž na hrdlo,⌉ ⌈jestliže máš velkou chuť!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Nedychti po jeho lahůdkách, je to podvodný pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Neunavuj se získáváním bohatství, ⌈kvůli své rozumnosti přestaň.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, '⌈ Jen na to zaměříš své oči,⌉ a není tu; jistě si udělá křídla a jako orel odletí do nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Nejez pokrm lakomce, nedychti po jeho lahůdkách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, '⌈vždyť jak v duchu uvažuje, takový opravdu je.⌉ Říká ti: Jez a pij, ale ⌈jeho srdce ne ní s tebou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Vyzvrátíš i ten kousek, jež jsi snědl, a promarníš svá příjemná slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Nemluv k hlupákovi, neboť pohrdne rozumností tvých řečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Neposouvej dávné mezníky a nevstupuj na pole sirotků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'protože jejich Vykupitel je silný, on povede jejich spor s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Přilož své srdce k naučení a své uši k řečem poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Neodpírej chlapci kázeň; když mu nabiješ holí, nezemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Ty mu nabiješ holí a jeho duši vysvobodíš z podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Můj synu, jestliže bude tvé srdce moudré, bude se radovat i mé vlastní srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Moje nitro jásá, když tvoje rty mluví, ⌈ co je správné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Ať tvé srdce nezávidí hříšníkům, ale každý den buď horlivý v bázni před Hospodinem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'neboť máš budoucnost a tvoje naděje nebude zmařena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Můj synu, poslouchej a buď moudrý, veď své srdce po dobré cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Nebuď mezi pijany vína, ani mezi žrouty masa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Protože pijan i žrout zchudne, dřímota je oblékne do cárů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Poslouchej svého otce, který tě zplodil, a nepohrdej svou matkou, když zestárne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kup si pravdu a neprodávej ji, moudrost, naučení a rozumnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Velmi bude jásat otec spravedlivého, rodič moudrého se z něj bude radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Ať se raduje tvůj otec i tvá matka, ať jásá tvoje rodička.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Můj synu, dej mi své srdce, tvé oči ať střeží moje cesty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'protože prostitutka je hlubokou jámou, cizinka úzkou studnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Také ona číhá jako lupič, množí nevěrné mezi lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, '⌈Komu běda? Komu žal?⌉ Komu sváry? Komu stěžování? Kdo má bezdůvodné modřiny? Kdo má ⌈kalný zrak?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Ti, kdo ⌈prodlévají u vína,⌉ přicházejí ochutnat míšené víno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Nedívej se na víno, jak je rudé, jak jiskří v poháru a hladce klouže dolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Nakonec uštkne jako had, kousne jako zmije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Tvoje oči uvidí divné věci a tvé srdce bude mluvit obojace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Budeš jako ten, kdo leží uprostřed moře, kdo leží při vrcholu stěžně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Zbili mě, ale necítil jsem bolest, ztloukli mě, ani jsem to nepoznal. Kdy se probudím? Už ho zase chci!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Nezáviď zlým lidem, nedychti být s nimi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, '⌈protože jejich srdce přemítá o zkáze a jejich rty mluví o trápení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Dům se vybuduje moudrostí, upevní se rozumností');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'a skrze poznání naplní se pokoje všelijakým vzácným a příjemným majetkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Moudrý muž je ⌈víc než silák, rozumný člověk je víc než mocný;⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'proto veď válku se strategií, záchrana je v množství rádců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Moudrost je pro hlupáka příliš vysoko, v bráně neotevře svá ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kdo vymýšlí, jak páchat zlo, toho nazvou pletichářem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, '⌈Úmysl hloupého⌉ je hříchem, posměvač je pro lidi ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Jsi–li skleslý v den soužení, tvá síla je malá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Vysvoboď vedené na smrt a zadrž potácející se na popravu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Když řekneš: Hle, nevěděli jsme to!, cožpak ten, který zkoumá srdce, to nerozpozná a ten, kdo střeží tvou duši, se to ne dozví? On odplatí každému podle jeho skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Můj synu, jez med, protože je dobrý, med z plástve je sladký na jazyku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Poznej, že taková je moudrost pro tvou duši. Když ji nalezneš, budeš mít budoucnost a tvoje naděje nebude zmařena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Nečíhej na příbytek spravedlivého jako ničema, nenič místo jeho odpočinku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'neboť spravedlivý může sedmkrát upadnout a zase povstane, ale ničema ⌈padne ve zlu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Neraduj se, když tvůj nepřítel padne, a když klopýtne, ať tvé srdce nejásá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'jinak to Hospodin uvidí a bude to zlé v jeho očích a odvrátí od něj svůj hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Nezlob se kvůli pachatelům zla, nezáviď ničemům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'neboť zlý nemá budoucnost, lampa ničemů zhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Můj synu, boj se Hospodina a krále, nezaplétej se ⌈s těmi, kdo si jinak počínají.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Neboť náhle povstane od nich pohroma a kdo ví, ⌈ jakou zkázu mohou oba přivodit?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Také toto jsou slova moudrých: Stranit lidem při soudu ne ní dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Kdo říká ničemovi: Jsi spravedlivý, toho budou národy proklínat, tomu budou lidé zlořečit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'ale těm, kdo ho kárají, bude dobře, přijde na ně ⌈dobré požehnání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Líbá na rty, kdo odpovídá správná slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Připrav si svoji práci venku, nachystej si ji na poli; a potom si postav dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Nebuď bezdůvodně svědkem proti svému bližnímu, ne podváděj svými rty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Neříkej: Jak učinil mně, tak učiním jemu, odplatím každému podle jeho skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Procházel jsem kolem lenochova pole, kolem vinice člověka, kterému chyběl rozum,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'a hle, celá byla zarostlá kopřivami, její povrch byl pokryt plevelem, její kamenná zeď byla zbořená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Když jsem to uviděl, ⌈vzal jsem si to k srdci,⌉ uzřel jsem to a vzal jsem si ponaučení:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Trochu spánku, trochu dřímoty, trochu složit ruce a poležet si --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'a tvá chudoba přijde jako tulák a tvá nouze jako ozbrojenec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Také toto jsou Šalomounova přísloví, která sebrali a opsali muži judského krále Chizkijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Boží ctí je ukrýt věc, čest králů je zkoumat věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, '⌈ Jako nebesa pro výšku a země pro hloubku, tak je nevyzpytatelné srdce králů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Když se odstraní ze stříbra struska, zlatníkovi vzejde nádoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Když se odstraní ničema z přítomnosti krále, jeho trůn bude pevně stát spravedlností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Nedělej důležitého před králem a nestav se na místo vysoko postavených lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Protože je lepší, když ti řekne: Postup sem, nežli být sesazen před šlechticem. Co viděly tvé oči,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, '⌈nepřinášej ukvapeně na soud.⌉ Co jinak budeš dělat na jeho konci, když tě tvůj bližní zahanbí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Veď svůj spor se svým bližním, ale neodhaluj důvěrnosti jiného člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Jinak ten, kdo to uslyší, tě pohaní a pomluva o tobě se nezastaví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Jako zlatá jablka na stříbrných mísách je slovo promluvené v pravý čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Jako zlatý kroužek či ornament z čistého zlata je moudrý karatel pro naslouchající ucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Jako ⌈chlad od sněhu⌉ v čas žně je spolehlivý posel pro ty, kteří ho posílají, neboť občerství duši svých pánů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Jako oblaka a vítr bez deště je člověk, který se chlubí jenom slibovaným darem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Vůdce se dá přemluvit tím, kdo je pomalý k hněvu, vlídný jazyk zlomí kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Když nalezneš med, jez s mírou; jinak se ho přesytíš a vyzvrátíš ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, '⌈Čiň svou nohu vzácnou v domě⌉ svého bližního, jinak se tě přesytí a bude tě nenávidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Kyj, meč a ostrý šíp, to je člověk, který vypovídá proti svému bližnímu jako falešný svědek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Jako spoléhat na zlomený zub či vyvrtnutou nohu je vkládat naděje v nevěrného člověka v den soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Jako ten, kdo svléká oděv ve chladném dni, či jako ocet na sodu, je ten, kdo zpívá písně skleslému srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Jestliže ten, kdo tě nenávidí, hladoví, nakrm ho chlebem, jestliže žízní, napoj ho vodou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'neboť mu nahrneš řeřavé uhlí na hlavu a Hospodin ti odplatí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Severní vítr přinese déšť, potajmu mluvící jazyk nahněvané tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Lepší je bydlet v koutě na střeše nežli společně v domě se svárlivou ženou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Jako chladná voda pro ⌈člověka vyčerpaného žízní⌉ je dobrá zpráva z daleké země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Jako zkalený pramen a znečištěný zdroj je spravedlivý, který se potácí před ničemou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Ne ní dobré jíst mnoho medu a také hledat ⌈vlastní slávu není sláva.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Jako pobořené město bez hradeb je člověk, který ⌈neovládá svého ducha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Jako sníh v létě a déšť ve žni, tak se nehodí pro hlupáka sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Jako vrabec poletuje, jako vlaštovka létá, tak i ⌈bezdůvodná kletba: Nikam se nedostane.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Na koně bič, na osla uzdu, a na záda hlupáků hůl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Neodpovídej hlupákovi podle jeho hlouposti, jinak ⌈budeš jako on.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Odpověz hlupákovi podle jeho hlouposti, jinak ⌈bude moudrý ve svých očích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Kdo posílá poselství po hlupákovi, je jako ten, kdo si usekává nohy a pije násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Jako volně visí nohy chromého, tak je přísloví v ústech hlupáků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, '⌈Jako přivázat kámen k praku, takové je dát hlupákovi slávu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Jako trní, které se dostalo do ruky opilce, tak je přísloví v ústech hlupáků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, '⌈ Jako lukostřelec, který každého zraňuje, je ten,⌉ kdo najímá hlupáka, kdo najímá kolemjdoucí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Jako se pes navrací ke svému zvratku, tak hlupák opakuje svoji hloupost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Viděl jsi člověka ⌈moudrého ve svých očích?⌉ Pro hlupáka je víc naděje než pro něj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Lenoch říká: Lev je na cestě, lev je v ulicích!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Jako se dveře otáčejí na svém pantu, tak lenoch na své posteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Lenoch ponoří svou ruku do mísy a je mu zatěžko zvednout ji do svých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Lenoch ⌈ je moudřejší ve svých očích⌉ než sedm lidí, kteří rozvážně odpovídají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Kdo prochází kolem a nazlobí se kvůli sporu, který se ho ne týká, je jako ten, kdo chytá psa za uši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Jako šílenec, který střílí ohnivé střely a ⌈smrtící šípy,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'je člověk, který podvede svého bližního a potom řekne: Já jsem jenom vtipkoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Kde ne ní dostatek dřeva, oheň uhasne, kde není pomlouvač, utichne svár.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Uhlí na žár, dřevo na oheň, svárlivý člověk pro zažehnutí sporu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Slova pomlouvače jsou jako pamlsky, ⌈sestupují do nejzazších útrob.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Jako stříbrná glazura potažená na hliněnou nádobu jsou horoucí rty a zlé srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Ten, kdo nenávidí, ⌈ to svými rty zastírá,⌉ ale ve svém nitru ⌈připravuje podvod.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'I když bude ⌈jeho hlas vlídný, nevěř mu, protože v jeho srdci je sedm ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Jeho nenávist může být zakryta lstivostí, ale jeho zlo se zjeví ve shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kdo kope jámu, spadne do ní, kdo valí kámen, na něj se obrátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Lživý jazyk nenávidí ty, které utlačuje, lichotivá ústa působí zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Nechlub se zítřejším dnem, neboť nevíš, co den přinese.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Ať tě chválí někdo jiný, a ne tvoje ústa, někdo cizí, a ne tvoje rty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Kámen je těžký, ⌈písek váží hodně,⌉ ale ⌈hlupákův hněv je těžší nežli obojí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Zloba je krutá, hněv je jako povodeň. Kdo však obstojí před žárlivostí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Otevřené pokárání je lepší než skrytá láska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Věrně míněné jsou modřiny od přítele, ale polibků od toho, kdo nenávidí, je mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, '⌈Nasycená duše⌉ pošlape i med z plástve, ale ⌈hladové duši⌉ je ⌈všechno hořké sladkým.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Jako ptáku, který uletí ze svého hnízda, tak je tomu, kdo uteče ze svého domova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Olej a kadidlo dává radost srdci, ⌈milý přítel dává radu z duše.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Neopouštěj svého přítele ani přítele svého otce; nechoď do domu svého bratra v den své pohromy. Lepší je blízký soused nežli vzdálený bratr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Buď moudrý, můj synu, a dělej radost mému srdci, abych mohl odpovědět tomu, kdo mě hanobí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Chytrý vidí zlo a ukryje se, prostoduší jdou dál a doplatí na to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Vezmi mu roucho, neboť se zaručil za cizince, a vezmi to od něj do zástavy za cizinku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Jestliže ně kdo brzy z rána příliš hlasitě žehná svému bližnímu, bude se mu to počítat za kletbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Stálé kapání vody v deštivý den a svárlivá žena jsou si rovny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Kdo ji zadrží, zadrží vítr, uchopí svou pravicí olej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Jako se železo ostří železem, tak člověk ostří tvář svého bližního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kdo pečuje o fíkovník, bude jíst jeho ovoce, kdo pečuje o svého pána, bude vážený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Jako ⌈ ve vodě odpovídá tvář tváři,⌉ tak srdce člověka člověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Jako se nenasytí podsvětí a říše mrtvých, tak se nenasytí oči člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Na stříbro je kelímek, na zlato je pec, člověk je zkoušen podle své chvály.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'I kdybys tloukl hlupáka v hmoždíři paličkou spolu se zrnem, jeho hloupost se od něho neodvrátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, '⌈Znej dobře⌉ poměry svého bravu, ⌈přilož své srdce k péči o⌉ svá stáda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'protože bohatství ne trvá navěky, ani koruna z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Když je odklizena tráva a je vidět nová, zeleň hor je shromážděna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'beránci budou na tvůj oděv, kozel na cenu za pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Bude dostatek ⌈kozího mléka⌉ na tvůj pokrm, na potravu tvé domácnosti i obživu pro tvé služky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Ničema utíká, ⌈ačkoliv ho nikdo ne honí,⌉ ale spravedlivý si je jistý jako mladý lev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, '⌈Když je země ve vzpouře,⌉ má mnoho vládců, ale ⌈s člověkem rozumným a znalým⌉ bude řád prodloužen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Chudý muž, který utlačuje chudé, je jako odplavující déšť, který ničí úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Ti, kdo opouštějí zákon, budou ničemy chválit, ale ti, kdo zachovávají zákon, se s nimi pustí do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Zlí lidé nerozumějí právu, ale ti, kdo hledají Hospodina, porozumějí všemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Lepší je chudý, který žije bezúhonně, nežli ten, jehož cesty jsou křivolaké, ačkoliv je bohatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kdo zachovává zákon, je rozumný syn, kdo se stýká se žrouty, vystaví svého otce hanbě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kdo rozmnožuje svůj majetek lichvou a úrokem, shromáždí ho pro toho, kdo se smilovává nad chudými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kdo odvrací své ucho od slyšení zákona, i jeho modlitba je ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kdo svádí přímé na zlou cestu, sám padne do vlastní jámy, ale bezúhonní zdědí dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Bohatý člověk ⌈ je moudrý ve svých očích,⌉ ale chudý, nicméně rozumný, ho prověří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Když se spravedliví veselí, ⌈ je veliká sláva,⌉ když ale povstávají ničemové, lidé se skrývají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kdo zakrývá svá přestoupení, neuspěje, ale kdo je vyznává a opouští, nalezne slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Blahoslavený je člověk, který má ustavičně bázeň, ale kdo zatvrzuje své srdce, padne do zla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Řvoucím lvem a útočícím medvědem je ničemný vládce nad chudým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Vévoda, kterému chybí rozumnost, se dopouští mnohého vydírání, kdo nenávidí nekalý zisk, prodlouží své dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Člověk obtížený krví člověka bude až do smrti utíkat; ať ho nikdo nedrží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kdo žije bezúhonně, bude zachráněn, ale ten, jehož cesty jsou křivolaké, najednou padne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kdo obdělává svou půdu, nasytí se pokrmem, ale ten, kdo se žene za prázdnými věcmi, nasytí se chudobou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Věrný člověk má mnoho požehnání, ale ⌈kdo je ukvapený, aby získal bohatství,⌉ nezůstane bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Stranit člověku ne ní dobré, ačkoliv člověk se vzbouří i kvůli kousku chleba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Lakomec ⌈se žene za majetkem⌉ a neví, že na něho přijde nedostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Ten, kdo kárá člověka, později nalezne milosti víc než ten, kdo lichotí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kdo okrádá svého otce a svou matku a říká: To ne ní přestoupení, je společníkem ničitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Nenasytný člověk podněcuje svár, ale kdo doufá v Hospodina, bude prospívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kdo spoléhá na svůj rozum, je hlupák, ale kdo žije moudře, unikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kdo dává chudým, ne bude mít nouzi, kdo však zavírá oči, sklidí mnoho kleteb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Když povstávají ničemové, lidé se ukrývají, když však hynou, množí se spravedliví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, '⌈Kdo po mnohém pokárání⌉ zatvrzuje šíji, bude v okamžiku rozdrcen a nebude pro něj uzdravení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Když se množí spravedliví, lid se raduje, když vládne ničema, lidé vzdychají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Kdo miluje moudrost, dělá svému otci radost, ale kdo se stýká s prostitutkami, zničí majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Král upevňuje zemi právem, kdo však zvyšuje dávky, boří ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Kdo lichotí svému bližnímu, rozprostírá síť na jeho nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'V přestoupení zlého člověka je léčka, ale spravedlivý volá a raduje se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Spravedlivý bere ohled na právní nárok chudých, ničema ohledy nechápe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Posměvači rozruší město, ale moudří odvrátí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Když se moudrý soudí s hlupákem, ⌈třese se zlostí či vysmívá,⌉ klidu ne má.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Krvelační nenávidí bezúhonného, avšak přímí hledají jeho život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Hlupák nechá propuknout celý svůj hněv, ale moudrý ho zadrží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Když vládce věnuje pozornost lživému slovu, všichni jeho služebníci budou ničemy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Chudý a utlačovatel se potkávají, světlo očím dává oběma Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Když král soudí chudé podle pravdy, jeho trůn bude navěky pevně stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Hůl a pokárání dá moudrost, ale chlapec ⌈ponechaný sám sobě⌉ dělá hanbu své matce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Když se množí ničemové, množí se přestoupení, ale spravedliví uvidí jejich pád.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Kárej svého syna ⌈a dá ti⌉ odpočinek, dá potěšení tvé duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Když ne ní vidění, lid je bez zábran, ale šťastný je ten, kdo zachovává zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Otrok se nedá pokárat pouhými slovy, i když rozumí, nereaguje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Viděl jsi člověka, který je ukvapený ve svých slovech? Pro hlupáka je víc naděje než pro něj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, '⌈Kdo od mládí hýčká svého otroka,⌉ nakonec ⌈bude mít žal.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Hněvivý člověk podněcuje svár, vztekloun se dopouští mnoha přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Člověka poníží jeho pýcha, ale ponížený duch získá slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Kdo se dělí se zlodějem, ⌈nenávidí svou duši;⌉ uslyší prokletí, ale neoznámí to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, '⌈Strach z lidí⌉ klade léčku, kdo však doufá v Hospodina, bude v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Mnozí usilují o přízeň vládce, ale právo pro člověka pochází od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Pro spravedlivého je ohavností špatný člověk, pro ničemu je ohavností ten, kdo ⌈jde přímou cestou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Slova Agúra, syna Jákeova z Massy. Výrok toho muže k Ítielovi, k Ítielovi a Ukalovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Vždyť jsem tupější nežli kterýkoliv člověk, nemám lidskou rozumnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'nenaučil jsem se moudrosti ani ne mám poznání Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kdo vystoupil na nebesa a sestoupil? Kdo sebral vítr do svých hrstí? Kdo svázal vodu do pláště? Kdo ustanovil všechny končiny země? Jaké je jeho jméno a jaké je jméno jeho syna, jestlipak víš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Každá Boží řeč je přečištěná, on je štítem těm, kteří v něm mají útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Nepřidávej k jeho slovům, jinak tě pokárá a budeš shledán lhářem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Dvojí od tebe žádám; neodpírej mi to, dříve nežli zemřu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Vzdal ode mě klam a lživé slovo, nedávej mi chudobu ani bohatství, zaopatřuj mě pokrmem určeným pro mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Jinak bych se mohl přesytit, zapřít tě a říct: Kdo je Hospodin? Anebo bych mohl zchudnout, krást a zneuctít jméno svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Nepomlouvej otroka před jeho pánem, jinak tě prokleje a poneseš vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Je pokolení, které proklíná svého otce a své matce nežehná;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'pokolení, které je čisté ve svých očích, ale od své nečistoty ne ní obmyto;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'je pokolení, ⌈jehož oči jsou povýšené⌉ a jeho víčka povznesená;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'je pokolení s meči místo zubů, s noži místo řezáků, k požírání chudých v zemi a chudáků mezi lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Pijavice má dvě dcery: Dej! Dej! Jsou tři věci, které se nenasytí, čtyři neřeknou: Dost!:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Podsvětí, neplodné lůno, země, která se nenasytí vodou, a oheň, jenž neřekne: Dost!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Oko, které se posmívá otci a pohrdá poslušností matce, vyklovou havrani z údolí, zhltnou ho orlí mláďata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Jsou tři věci, které jsou pro mě nepochopitelné, a čtyři, kterým nerozumím:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Cestě orla na nebesích, cestě hada na skále, cestě lodi uprostřed moře a cestě mládence s dívkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Taková je cesta cizoložnice. Nají se, utře si ústa a řekne: Neudělala jsem nic zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Pod třemi věcmi se země třese, čtyři není schopna snést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Otroka, který kraluje, blázna, který se přesytí pokrmem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'tu, která je nemilována a vdá se, a služku, která vypudí svou paní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Jsou čtyři, kteří jsou malí na zemi, ale jsou nesmírně moudří:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Mravenci ne jsou národ příliš silný, ale připravují si v létě pokrm;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'damani ne jsou národ příliš mocný, ale stavějí si své obydlí ve skalách;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'kobylky nemají krále, a přece vytáhnou všechny sešikovány;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'ještěrku chytíš rukama, a přece je v královských palácích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Jsou tři, kteří ⌈si hezky vykračují,⌉ čtyři, kteří ⌈si hezky jdou:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Lev, hrdina mezi zvířaty, před nikým neustoupí;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, '⌈naparující se kohout⌉ či kozel a král, ⌈ když je s ním jeho vojsko.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Jestliže jsi jednal bláznivě tím, že ses vyvyšoval, nebo jestliže jsi zamýšlel zlo, dej si ruku na ústa!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, '⌈Tlak na mléko působí máslo, tlak na nos působí krev a tlak hněvu působí hádku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Slova Lemúela, krále z Massy, kterými ho vychovávala jeho matka:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Co, můj synu, co, synu ⌈mého lůna, co, synu mých slibů?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Nedávej svou udatnost ženám, a své cesty těm, kdo ničí krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ne přísluší králům, Lemúeli, ne přísluší králům pití vína, ani mocnářům ⌈ říkat: Kde je ⌉ pivo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Jinak se někdo napije, zapomene, co bylo ustanoveno, a převrátí právní nárok všech soužených.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dejte pivo hynoucímu a víno těm kdo, mají hořkost v duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Napije se, zapomene na svou chudobu a na své trápení již nebude myslet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, '⌈Otevři svá ústa za němého,⌉ za právo všech určených k záhubě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Otevři svá ústa, suď spravedlivě, pomoz získat právo chudému a nuznému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Kdo nalezne zdatnou ženu? ⌈Je daleko cennější než⌉ drahokamy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Srdce jejího manžela jí důvěřuje, nebude mít nedostatek kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Po všechny dny svého života mu působí dobro, a ne zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Vyhledává vlnu a len, se ⌈zálibou pracuje svýma rukama.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Je jako obchodní lodě; zdaleka přiváží svou potravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Vstává, ještě když je noc, aby dala potravu svému domu a práci svým služkám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Vyhlédne si pole a dostane ho, ⌈z ovoce svých rukou⌉ vysadí vinici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Svá bedra přepásává silou, posiluje své paže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Zakouší, že má dobrý zisk, v noci její lampa nehasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Svýma rukama sahá po přeslenu, její dlaně uchopují vřeteno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Svou dlaň otvírá chudému, své ruce vztahuje k nuznému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Když přijde sníh, nebojí se o svůj dům, protože celý její dům se obléká do karmínu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Dělá si přikrývky, její oděv je z jemného plátna a purpuru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Její manžel je znám v městských branách, když sedává se staršími země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Dělá plátno a prodává ho, dodává obchodníkovi pásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Jejím oděvem je síla a důstojnost, s úsměvem vyhlíží budoucnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Svá ústa otvírá moudře, na jejím jazyku je laskavé poučení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Pozorně sleduje chod svého domu, nejí chléb lenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Její synové povstávají a nazývají ji šťastnou, také její manžel ji chválí:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Mnohé dcery si počínaly zdatně, ale ty je všechny převyšuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Půvab je klamný, krása je nicotná, ale žena, která se bojí Hospodina, bude chválena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dejte jí z ovoce jejích rukou, ať ji chválí v městských branách její skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Slova kazatele, syna Davidova, krále v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Marnost všech marností, řekl kazatel, marnost všech marností, všechno je to marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Jaký užitek bude člověk mít z veškeré své námahy, když se bude namáhat pod sluncem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Generace odchází, generace přichází a země navěky zůstává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Slunce bude vycházet, slunce bude zapadat. Baží po místě, kde vychází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Vítr odchází k jihu a stáčí se k severu. ⌈Stáčí se a stáčí, obchází a při svém oběhu se zas vítr vrací.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, '⌈Všechny potoky tečou do moře a přece není moře plné.⌉ Na místo, z něhož potoky vytékají, tam se i vracejí, aby opět vytékaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, '⌈Všechny věci jsou únavné; člověk to nedokáže vyjádřit.⌉ ⌈Oko se nenasytí viděním a⌉ ucho se nenaplní slyšením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, '⌈To, co bylo, je to, co i bude,⌉ a to, co se dělalo, je to, co se bude dělat. Není nic nového pod sluncem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Je nějaká věc, o níž někdo řekne: Podívej, tohle je něco nového? Už to dávno bylo, v dobách, které byly před námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Není žádná památka na věci první. ⌈Ani na poslední, které budou; nebude na ně památka u těch, kteří budou naposled.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Já, kazatel, jsem byl králem nad Izraelem v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Uložil jsem svému srdci, aby pátralo a aby zkoumalo s moudrostí všechno, co bylo vykonáno pod nebem. ⌈Ono zlé plahočení uložil Bůh lidským⌉ synům, aby se při něm osvědčili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Viděl jsem všechny skutky, které byly vykonány pod sluncem, a hle, to vše je marnost a ⌈honba za větrem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Co je ⌈zkřivené, nelze narovnat⌉ a nedostatek nelze sečíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Takto jsem hovořil se svým srdcem: Hle, já jsem rozšiřoval a nabýval moudrosti ⌈nad každého, kdo byl v Jeruzalémě přede mnou.⌉ Mé srdce užilo množství moudrosti a poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Uložil jsem tedy svému srdci, aby poznalo moudrost a ⌈poznalo i ztřeštěnosti a pomatenost.⌉ Poznal jsem, že také tohle je honička za větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Vždyť v množství moudrosti je množství mrzutosti. Kdo bude přidávat poznání, bude šířit bolest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Řekl jsem si ve svém srdci: Pojď přece, ať tě vyzkouším s radovánkami, užívej si dobrých věcí. Hle, také to je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'O zábavě jsem řekl: Jsi šílená, o radovánkách: Co to provádíte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Zkoumal jsem ve svém srdci, jak rozjařit své tělo vínem, zatímco mé srdce vede k moudrosti, abych se udržoval v pomatenosti, jen dokud nezjistím, co z toho, co vykonají pod nebem ve vyměřených dnech svých životů, je dobré pro lidské syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Zvětšil jsem svůj statek: Vystavěl jsem si domy, vysadil jsem si vinice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Založil jsem si zahrady a parky a vysadil jsem v nich stromoví s kdejakým ovocem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Zřídil jsem si jezírka s vodou, abych z nich napájel les, v němž vyrážely stromy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Koupil jsem si otroky a otrokyně a měl jsem i doma narozené; také dobytka, skotu i bravu jsem měl více než všichni, kdo byli v Jeruzalémě přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Nashromáždil jsem si také stříbro a zlato i vlastnictví králů a provincií. Získal jsem pro sebe zpěváky a zpěvačky i potěšení lidských synů, ⌈mnoho konkubín.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Tak jsem se vzmáhal a pokračoval jsem v tom více než všichni, kteří byli v Jeruzalémě přede mnou. Nadto při mně stála má moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Nic, o co žádaly mé oči, jsem od nich nevzdaloval. Neodpíral jsem svému srdci žádnou radost, vždyť mé srdce se radovalo ze vší mé námahy, a to byl můj podíl ze vší mé námahy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Pak jsem se ohlédl na všechny své skutky, které vykonaly mé ruce, a na námahu, kterou jsem se namáhal, abych to vykonal. A hle, to všechno je marnost a honba za větrem a není z toho pod sluncem žádný užitek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Ohlédl jsem se, abych se podíval na moudrost i ztřeštěnosti a pomatenost; vždyť ⌈jaký to bude člověk, který přijde po králi, jehož si dříve ustanovili?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Já jsem tehdy viděl, že z moudrosti je větší užitek než z pomatenosti, stejně jako je větší užitek ze světla než ze tmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Moudrý má na hlavě oči, zatímco hlupák chodí ve tmě. Také jsem však poznal, že je oba postihne stejný úděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Tu jsem si v duchu řekl: I mě postihne tentýž úděl jako toho hlupáka. Proč jsem potom já nadmíru zmoudřel? A v duchu jsem prohlásil, že také toto je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Vždyť památka na moudrého stejně jako na hlupáka nezůstává navěky. To všechno bude dávno zapomenuto v přicházejících dnech. Jak to, že moudrý zemře stejně jako hlupák?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Tu jsem začal nenávidět život, protože je pro mě špatné to dílo, které se koná pod sluncem. Je to všechno totiž jen marnost a honba za větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Začal jsem nenávidět všechnu svou námahu, kterou se namáhám pod sluncem, protože ji zanechám člověku, jenž bude po mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'A kdo ví, zdali bude moudrý nebo blázen; bude však panovat nade vší mou námahou, kterou jsem se namáhal a při níž jsem pod sluncem zmoudřel. Také toto je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'A já jsem se odvrátil, abych si v srdci zoufal nad vší tou námahou, kterou jsem se pod sluncem namáhal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Neboť je člověk, který sám usiloval o moudrost, o poznání a o prospěch, ale odevzdá to jako svůj podíl člověku, který o to neusiloval. Také toto je marnost a velké zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Vždyť co člověk má ze vší své námahy a z honičky svého srdce, když se pod sluncem namáhá?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Všechny jeho dny totiž přinášejí bolesti a jeho plahočení mrzutost; jeho mysl neutichne ani v noci. Také toto je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Není pro člověka dobré, když bude jíst a pít a užije si ze své námahy blaho pro svou duši? I to jsem zjistil, že je z Boží ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Vždyť kdo jí a kdo si užívá víc než já?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Neboť člověku, který se mu líbí, dal moudrost, poznání a radost. Hříšníkovi však dal plahočení, aby sbíral a hromadil, aby to pak předal tomu, kdo se Bohu líbí. Také toto je marnost a honba za větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Všechno má svou chvíli, každý záměr pod nebem má svůj čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Je čas rodit a čas umírat, čas sázet a čas vytrhávat, co bylo zasazeno;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'čas zabíjet a čas uzdravovat, čas bořit a čas stavět;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'čas plakat a čas se smát, čas naříkat a čas poskakovat;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'čas házet kameny a čas kameny shromažďovat, čas objímat a čas vzdálit se od objímání;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'čas hledat a čas ztrácet, čas uchovávat a čas odvrhovat;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'čas trhat a čas šít, čas být zticha a čas mluvit;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'čas milovat a čas nenávidět, čas boje a čas pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Jaký užitek má ten, kdo pracuje, z toho, při čem se namáhá?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Viděl jsem plahočení, které Bůh uložil lidským synům, aby se při něm osvědčili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'To všechno učinil krásné ve svůj čas. Také věčnost dal do jejich srdce, aniž by člověk ovšem postihl dílo, které Bůh vykonal, od počátku až do konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Poznal jsem, že ⌈pro ně není nic lepšího,⌉ než aby se radovali a aby konali ve svých životech dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'A také, že když kterýkoli člověk ⌈jí a pije a užívá⌉ blaho při vší své námaze, je to Boží dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Poznal jsem, že všechno, co Bůh učiní, to bude pro věčnost; není možné k tomu nic přidat a není možné od toho nic ubrat. Bůh to udělal, aby lidé měli před ním bázeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, '⌈To, co je, je odedávna, i co má být, už dávno bylo.⌉ Bůh ⌈posoudí to, co pominulo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Dál jsem pak viděl pod sluncem: ⌈Tam, kde mělo být právo, byla ničemnost, tam, kde měla být spravedlnost, byla ničemnost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'V duchu jsem si řekl: ⌈Spravedlivého i ničemu bude soudit Bůh,⌉ protože ⌈tam nastane čas pro každý záměr a pro každé dílo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'A tu jsem si v duchu o záležitosti lidských synů řekl, že je Bůh tříbí, aby viděli, že jsou sami o sobě jako zvířata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Neboť pokud jde o úděl lidských synů i o úděl zvířete, mají stejný úděl: Jak umírá jeden, tak umírá i druhý, a obojí stejně dýchá. Člověk nemá před zvířetem žádnou přednost, vždyť je to všechno marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Všechno to odchází na stejné místo; vše to vzešlo z prachu a vše se to navrací v prach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kdo ví, zda duch lidských synů vystupuje vzhůru? A duch zvířat sestupuje dolů do země?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Viděl jsem tedy, že není nic lepšího, než že ⌈se člověk bude radovat ze svého díla, neboť⌉ to je jeho podíl. ⌈Vždyť kdo mu umožní, aby se podíval na to, co bude po něm?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'A znovu jsem viděl všechno utlačování, které se pod sluncem páchá. Hle, slzy utlačovaných, a ti nemají utěšitele; v ruce jejich utlačovatelů je soustředěna moc, a utlačovaní nemají utěšitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'A chvalořečil jsem mrtvé, kteří dávno zemřeli, více než živé, kteří jsou ještě naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Avšak lépe než oni oba je na tom ten, kdo ještě nebyl, kdo nespatřil zlé dílo, které se pod sluncem páchá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Viděl jsem všechnu námahu i veškerý prospěch z díla, že je za tím žárlivost ⌈jednoho na druhého.⌉ Také toto je marnost a honba za větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Hlupák ⌈skládá své ruce v klín⌉ a užírá se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Lepší je jedna dlaň plná klidu než dvě hrsti plné námahy a honby za větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'A znovu jsem viděl marnost pod sluncem:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Někdo je sám a nikoho jiného nemá, ani syna nebo bratra nemá; všechna jeho námaha nemá konce, ani jeho oko se nenasytí bohatstvím. Pro koho se namáhám a připravuji svou duši o blaho? Také toto je marnost a zlé plahočení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Lépe je dvěma než jednomu, ⌈neboť mají lepší⌉ mzdu za svou námahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Vždyť jestliže upadnou, jeden pomůže svému druhovi vstát. Ale běda jednomu, když upadne a nemá druhého, který by mu pomohl vstát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Také jestliže dva ulehnou, bude jim teplo, ale jak bude teplo jednomu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'A jestliže někdo přemůže jednoho, dva před ním obstojí. A trojitá šňůra se nepřetrhne snadno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Je lepší nuzné a moudré dítě než starý a hloupý král, který by už neuměl nechat se varovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Vždyť vyšlo z vězení, aby kralovalo, ačkoliv ještě za jeho kralování se narodilo chudé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Viděl jsem všechny živé, kteří chodí pod sluncem, že byli při tom dítěti, při tom druhém, které se postaví na jeho místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Není konce všemu lidu, všemu, který byl před nimi. Ani ti budoucí se z něj nebudou radovat, protože také toto je marnost a honička za větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 17, 'Střež své kroky, když půjdeš do Božího domu, a buď blíže k naslouchání, ⌈než abys dával oběť jako hlupáci.⌉ Vždyť oni nevědí, že provádějí, co je zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Neukvapuj se v řeči a tvé srdce ať nepospíchá vynést slovo před Bohem, protože Bůh je na nebesích a ty na zemi; proto ať jsou tvá slova nemnohá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Neboť s mnohým plahočením přichází sen a ⌈hlas hlupáka s mnohými slovy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Jakmile učiníš slib Bohu, neváhej ho splnit, protože nemá zalíbení v hlupácích. Co slíbíš, to splň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Je lepší, když neslíbíš, než když slíbíš a nesplníš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Nedovol svým ústům, aby sváděla tvé tělo ke hříchu, a neříkej v přítomnosti anděla, že to bylo nedopatření. Proč se má Bůh hněvat na to, co říkáš, a zničit dílo tvých rukou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Vždyť při množství snů se množí i marnosti a řeči. ⌈ Ty se však boj Boha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Uvidíš–li v provincii útlak chudého a znásilnění ⌈práva a spravedlnosti,⌉ nebuď tou zvůlí ohromený. Vždyť vysoce postavený střeží jiného vysoce postaveného a nad nimi jsou ještě výše postavení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Ale přes to všechno je země užitečná; polem je obsloužen i král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Kdo miluje stříbro, stříbra se nenasytí a kdo miluje bohatství, ne nasytí se výnosem. Také toto je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Když se rozmnožil blahobyt, byli i mnozí, kteří jej požírali. Jaký prospěch z toho měl jeho vlastník, než jen pohled svých očí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Sladký spánek má ten, kdo pracuje, ať bude jíst málo nebo mnoho. Hojnost nedopřává bohatému, aby se vyspal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Je bolestné zlo, které jsem viděl pod sluncem: Bohatství uchované pro jeho vlastníka je mu ke zlému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Ono bohatství přišlo vniveč při zlém plahočení. Zplodil syna a nemá v ruce nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Jak vyšel z lůna své matky, tak se nahý vrátí, aby odešel tak, jak přišel. Ze své námahy si neodnese nic, co ⌈by si vzal s sebou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'I to je také bolestné zlo: Jak kdo přišel, tak odejde. Jaký užitek bude mít z toho, že se namáhá pro vítr?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'K tomu ještě po všechny své dny jí ve tmě, s mnohým hněváním, nemocí a rozhořčením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Hle, co jsem já viděl dobrého: Jak krásné je ⌈jíst a pít⌉ a užívat blaho při vší své námaze, kterou se člověk namáhá pod sluncem v počtu dnů svého života, které mu Bůh dal, neboť to je jeho podíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, '⌈Když nějakému člověku dal Bůh bohatství a poklady⌉ a také mu dovolil z toho jíst, brát svůj podíl a ⌈radovat se ze své námahy;⌉ je to Boží dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Nebude totiž příliš vzpomínat na dny svého života, protože Bůh zaměstnává jeho srdce radostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Je zlo, které jsem viděl pod sluncem, a ⌈velmi na člověka doléhá:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Muž, jemuž dá Bůh bohatství, poklady i slávu a jeho duše nemá nedostatek v ničem, po čem touží; ale Bůh mu z toho nedovolí jíst, bude to totiž jíst někdo cizí. Toto je marnost a zlá nemoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Řekl jsem: Jestliže muž zplodí sto dětí, bude žít mnoho let a budou–li mnohé dny jeho let, ale jeho duše se přitom nenasytí dobrem a ⌈nebude mít ani pohřeb, pak⌉ je na tom potracený plod lépe než on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Vždyť přišel do marnosti, odejde do temnoty a temnotou bude přikryto jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Ani slunce neviděl a nepoznal. Ten má více klidu než onen muž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'I kdyby žil dvakrát tisíc let, ale blaho nezažil, což neodchází oba na ⌈stejné místo?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Všechna lidská námaha je pro ústa, touha se ale nenaplní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Vždyť jakou výhodu má moudrý oproti hlupákovi? Co má chudý, který se umí chovat ⌈před živými?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Vidění očí je lepší než bloumání duše. Také toto je marnost a honba za větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'To, co už bylo, dostalo své jméno. A ví se, kdo je člověk. Nemůže se přít s tím, kdo je silnější než on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Mnohá slova totiž množí marnost. ⌈Jakou z toho má člověk výhodu?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Vždyť kdo ví, co je pro člověka v životě dobré, ⌈ v počtu dnů jeho marného života, které stráví jako stín?⌉ ⌈Takže kdo člověku oznámí, co pod sluncem bude po něm?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, '⌈Dobré jméno je nad dobrý olej⌉ a den smrti nad den narození.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Lepší je jít do domu smutku než jít do domu hodování, v němž je konec každého člověka. Živý ať si to vezme k srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Je lepší mrzutost než smích, protože zatímco tvář je zachmuřená, srdci se vede dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Srdce moudrých je v domě smutku, ale srdce hlupáků v domě radosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Je lepší poslouchat napomenutí moudrého, než když člověk poslouchá zpěv hlupáků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Neboť jako praskot trní pod hrncem, tak zní smích hlupáka. Také toto je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Vždyť útlak dělá z moudrého potřeštěnce a dar ničí srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Je lepší konec jednání než jeho počátek. ⌈Trpělivost je lepší než povýšenost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Neukvapuj se v duchu, aby ses rozzlobil, protože mrzutost spočine v klíně hlupáků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Neříkej: Čím to bylo, že dřívější dny byly lepší než tyto? Na tohle ses totiž nezeptal moudře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Dobrá je moudrost jako dědictví; je výhodou pro ty, kteří vidí slunce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'neboť jsou pod ochranou moudrosti jako pod ochranou stříbra. Užitkem poznání je, že moudrost zachová při životě toho, kdo ji má.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Podívej se na Boží dílo. Vždyť kdo bude moci narovnat, co on pokřivil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'V den dobrý spočívej v blahu a v den zlý pohleď: Také tento ⌈podobně jako onen⌉ učinil Bůh ⌈z toho důvodu, aby člověk nezjistil⌉ nic o tom, co bude po něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'To obojí jsem viděl ve dnech své marnosti: Spravedlivý ve své spravedlnosti hyne a ničema je ve své špatnosti dlouho živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Nebuď příliš spravedlivý a nepočínej si nadmíru moudře. Nač se budeš ničit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Nejednej příliš ničemně a nebuď blázen. ⌈Proč bys měl zemřít mimo svůj čas?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Bude dobré, když se tohoto přidržíš a ani ⌈tamto neopustíš,⌉ protože kdo se bojí Boha, vyjde z toho obojího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Moudrost posílí moudrého více než deset mocných, kteří jsou ve městě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Vždyť na zemi není spravedlivý člověk, který by konal dobro a nehřešil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Ani nepřikládej své srdce ke všem slovům, která lidé říkají. Přece nebudeš poslouchat svého otroka, který tě proklíná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Vždyť sis také sám mnohokrát uvědomil, že i ty jsi proklínal jiné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'To všechno jsem zkoušel s moudrostí. Řekl jsem: Nechť zmoudřím. Avšak moudrost ode mě byla daleko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Vzdálené je to, co bylo; hluboko, hluboko, kdo to postihne?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Usiloval jsem poznat, zkoumat a hledat moudrost a smysl a poznat i ničemnost a bláznovství, pomatenost a ztřeštěnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'A nalézám něco trpčího než smrt: ženu, která je pastí, jejíž srdce jsou sítě a její ruce pouta. ⌈Kdo se líbí Bohu,⌉ zachrání se před ní, kdo však hřeší, bude jí polapen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Pohleď, toto jsem nalezl, řekl kazatel, jedno po druhém, když jsem nalézal smysl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Co stále hledala má duše, jsem nenalezl. Nalezl jsem ⌈jediného člověka z tisíce,⌉ ale ženu jsem mezi těmito všemi nenalezl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Zvlášť se podívej na tohle: Shledal jsem, že ⌈Bůh učinil člověka přímého.⌉ Oni však hledali mnohé výmysly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kdo si počíná jako moudrý a kdo zná výklad slova? Lidská moudrost rozjasní jeho tvář a ⌈tvrdost jeho tváře⌉ bude proměněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Já pravím: Králův příkaz zachovávej, ale z důvodu přísahy při Bohu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, '⌈se neunáhli. Až budeš od něj odcházet,⌉ nezůstávej ve zlém záměru, protože on učiní všechno, co chce;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'na to má královské slovo pravomoc. ⌈Kdo mu může říct: Co to děláš?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kdo zachovává příkaz, nepozná nic zlého. Moudré srdce rozezná čas i správný způsob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Neboť každý záměr má svůj čas i správný způsob, přestože na něm lpí velké lidské zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Nikdo totiž neví, co se stane. ⌈Vždyť kdo mu oznámí to, co se stane?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Není člověka panujícího nad větrem tak, že by zadržel vítr, nikdo ⌈ne má pravomoc nade dnem smrti,⌉ ⌈ne může se vyhnout boji.⌉ A ničemnost ⌈nepomůže těm, kdo ji páchají.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Tohle všechno jsem viděl, když jsem obrátil svou pozornost k veškerému dílu, které se konalo pod sluncem: Čas, kdy člověk panoval nad člověkem k jeho škodě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Přitom jsem viděl pohřbené ničemy, že přicházeli; odejdou ze svatého místa a budou zapomenuti ve městě, kde správně jednali. Také toto je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Když není rozsudek nad zlým činem vykonán rychle, srdce lidských synů se díky tomu nadme, takže páchají zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'I když hříšník páchá zlo sto krát a ⌈prodlužuje se mu život,⌉ ano, já přece vím, že nastane blaho pro ty, kdo se bojí Boha, kteří mají před ním bázeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Avšak pro ničemu blaho nebude, ani se neprodlouží jeho dny jako stín, když nemá před Bohem bázeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Je však marnost, která se na zemi děje: že ⌈jsou spravedliví, na které to doléhá podle jednání ničemů, a jsou ničemové, na které to doléhá podle jednání spravedlivých.⌉ Prohlásil jsem, že také toto je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'A tak jsem oslavoval radost, neboť pro člověka není nic lepšího pod sluncem, než jen ⌈aby jedl, aby pil a aby se radoval.⌉ To ho bude provázet při jeho námaze ve dnech jeho života, které mu dal Bůh pod sluncem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Jakmile jsem svou pozornost obrátil, abych poznal moudrost a abych viděl plahočení, které se na zemi konalo až tak, že ve dne ani v noci nikdo nedopřeje spánek svým očím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'viděl jsem veškeré Boží dílo, že člověk nedokáže postihnout dílo, které se koná pod sluncem; když člověk usiluje posoudit to, nepostihne to. Ani když moudrý řekne, že to zná, nedokáže to postihnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Tohle všechno jsem totiž uložil do svého srdce, abych to všechno objasnil; jak ⌈spravedliví a moudří i jejich činy jsou v Boží ruce.⌉ Ani lásku ani nenávist člověk nezná, všechno je před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Stejně tak tohle všechno platí pro každého: Stejný úděl má spravedlivý i ničema, dobrý a čistý i nečistý, obětující i ten, který neobětuje; jak je tomu s dobrým, tak i s hříšníkem, s tím, který přísahá, tak jako s tím, kdo se přísahy bojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Na všem, co se děje pod sluncem, je zlé to, že všichni mají stejný úděl, a pak i to, že ⌈srdce lidských synů je plné zla.⌉ Po celý život mají v srdci ztřeštěnost a potom odcházejí k mrtvým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Ten totiž, kdo bude připojen ke všem živým, má naději. Vždyť živému psu je lépe než mrtvému lvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Neboť živí vědí, že zemřou; ⌈mrtví, ti však nevědí nic,⌉ ani už nemají odměnu, protože jejich památka byla zapomenuta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Jak jejich láska tak jejich nenávist i jejich žárlivost dávno zanikla a nebudou mít už nikdy podíl na ničem, co se pod sluncem koná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Jdi, jez v radosti svůj chléb a pij v dobrém rozmaru své víno, protože Bůh dávno našel zalíbení ve tvém díle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Ať je tvé roucho v každé době bílé a na tvé hlavě ať není nedostatek oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Užívej života se ženou, kterou sis zamiloval, po všechny dny ⌈tvého marného života,⌉ které ti Bůh dal pod sluncem, všechny dny tvé marnosti, protože to je tvůj podíl ze života a ze tvé námahy, když se namáháš pod sluncem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Všechno, co se ti naskytne udělat, dělej ⌈ celou svou silou,⌉ protože není žádná činnost ani úmysl ani poznání ani moudrost v podsvětí, kam odcházíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Znovu jsem viděl pod sluncem, že běh ne záleží na rychlých a boj ne záleží na hrdinech, ani chléb ne záleží na moudrých, ani bohatství ne záleží na rozumných a ani milost ne záleží na vzdělaných. Čas a nahodilost je totiž postihne všechny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Vždyť ⌈člověk ani nepozná svůj čas;⌉ jako ryby, které jsou chyceny ve zhoubné síti, a jako ptáci, chycení do pasti. Jako oni i lidští synové jsou polapeni ve zlý čas, jakmile na ně náhle připadne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Viděl jsem, že také to je moudrost pod sluncem, a byla pro mě velká:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Bylo malé město a v něm málo mužů. Přitáhl k němu velký král, obklíčil je a postavil proti němu velké obléhací věže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Nacházel se v něm nuzný moudrý muž a ten by to město zachránil svou moudrostí. Nikdo si však na onoho nuzného muže nevzpomněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Tu jsem řekl: Lepší je moudrost než udatnost; avšak moudrostí nuzného se opovrhuje a jeho slova nejsou slyšena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Slova moudrých v klidu vyslechnutá jsou lepší než křik toho, kdo vládne nad hlupáky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Moudrost je lepší než válečné zbraně; ⌈jediný hříšník však zničí mnoho dobrého.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Mrtvé mouchy způsobí páchnutí a zakvasí mastičkářův olej. Trocha pomatenosti ⌈převáží nad⌉ moudrostí a ctí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Srdce moudrého je po jeho pravici, kdežto srdce hlupáka po jeho levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'I když jde blázen po cestě, chybí mu rozum. ⌈Každému říká, že je blázen.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Pokud proti tobě vzplane hněv vládce, ⌈neopouštěj své místo.⌉ Vždyť mírnost zastaví velké hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Je zlo -- jak jsem viděl pod sluncem -- jakožto nedopatření, které pochází od panovníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Pomatenost byla dosazena na mnohá vysoká místa, zatímco bohatí zůstávají v poníženosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Viděl jsem otroky na koních a knížata chodit po zemi jako otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Kdo kope jámu, spadne do ní; kdo boří zeď, toho uštkne had.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kdo táhne kameny, ⌈ může si jimi ublížit;⌉ kdo kácí stromy, je jimi ohrožen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Pokud by se ztupila sekera a on by nenabrousil ostří, musí zvýšit své úsilí. Moudrost má napomáhat k užitečnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Uštkne–li had, když není použito zaklínadlo, ⌈zaklínač z toho nemá užitek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Slova moudrých úst přinášejí milost, kdežto rty hlupáka pohltí jej samého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Počátek slov jeho řeči je pomatenost, konec jeho řeči je zlá ztřeštěnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Blázen množí slova. Člověk se nedozví, co se stane; ⌈kdo mu oznámí, co bude po něm?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Námaha hlupáků bude vyčerpávat toho, který nezjistil, kudy jít do města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Běda ti, země, bude –li tvým králem služebník a ⌈tvá knížata budou zrána hodovat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Šťastná jsi, země, je –li tvým králem syn šlechticů a hodují– li tvá knížata v pravý čas kvůli posilnění a ne kvůli popíjení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Kvůli líným rukám se bude sesouvat krov a kvůli zahálení rukou bude dům prosakovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Pro obveselení připravují jídlo a ⌈víno dá radost živým.⌉ ⌈Peníze pak dají na všechno odpověď.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Krále neproklínej ani ve své mysli a ani ve svých ložnicích neproklínej bohatého. Nebeské ptactvo totiž donese tu zprávu a okřídlenec vyzradí řeč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Pošli svůj chléb po vodní hladině, neboť po mnohých dnech jej nalezneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Dej podíl ⌈sedmi nebo i osmi,⌉ protože nevíš, co zlého se stane na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Jestliže se mračna naplní ⌈deštěm, vyprázdní se na zemi,⌉ jestliže padne strom k jihu nebo k severu, kam ten strom padne, tam zůstane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kdo hlídá vítr, nezaseje, a kdo se dívá do mračen, nebude sklízet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Tak jako nevíš, jaká je cesta větru nebo jak se tvoří kosti v obtěžkaném lůně, stejně tak nepoznáš dílo Boha, který to všechno působí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Zrána zasévej své semeno a k večeru nedávej svým rukám odpočinout. Vždyť nevíš, co z toho bude prospěšné, zda to či ono, anebo jestli to obojí bude stejně dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Sladké je světlo; pro oči je dobré ⌈vidět slunce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Vždyť bude–li člověk žít mnoho let, ať se z nich všech raduje, ale ať pamatuje na ⌈dny temnoty,⌉ protože jich bude mnoho; všechno, co přišlo, je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Raduj se, mládenče, ve svém dětství a ať tě tvé srdce oblažuje ve dnech tvého jinošství, ⌈choď cestami svého srdce a za tím co vidí tvé oči.⌉ Ale věz, že za všechny tyto věci tě ⌈Bůh přivede k soudu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Odstraň ze svého srdce vztek a ze svého těla odveď, co je zlé, neboť dětství a úsvit je marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Pamatuj na svého stvořitele ve dnech svého jinošství, dříve nežli přijdou zlé dny a dorazí léta, o kterých řekneš: Nemám v nich zalíbení;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'dříve nežli ztemní slunce a světlo, měsíc a hvězdy, a vrátí se mračna po dešti;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'v den, kdy se budou strachem třást strážci domu a udatní muži se budou křivit, ⌈mlečky přestanou pracovat, protože ubyly,⌉ a ty, ⌈kdo se dívají skrze průduchy,⌉ budou temné');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'a zavřou se dveře do ulice, až se ztiší zvuk mlýnu. Bude se vstávat za hlasu ptactva a všechny popěvky budou přidušeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Lidé se budou bát i výšek a postrachu na cestě; rozkvete mandlovník, kobylka se sotva povleče a kapara už nebude působit. Vždyť člověk se ubírá do svého věčného domu a ulicí budou obcházet ti, kdo naříkají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Dříve nežli se přetrhne stříbrný provaz a praskne zlatá mísa, bude roztříštěn džbán nad zřídlem a zlomí se kolo u studny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Až se navrátí prach na zem tak, jak dříve byl, a ⌈duch se navrátí k Bohu,⌉ který jej dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Marnost všech marností, řekl ten kazatel, všechno je to marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'A dodatek: Že byl kazatel moudrý, stále učil lid poznání, uvažoval a bádal, uspořádal mnohá přísloví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Kazatel se snažil nalézt žádoucí slova; je zapsáno to, co je přímé, pravdivá slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Slova moudrých jsou jako bodce a jako hřebíky zatlučené sběrateli. Byla vydána jedním pastýřem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'A dodatek: Můj synu, nech se jimi varovat. Tvořit mnohé knihy, to nemá konce, a mnohé dumání působí únavu těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Slovo na závěr všeho, co bylo řečeno: Boha se boj a jeho příkazy zachovávej, protože toto se týká každého člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Vždyť ⌈Bůh každé dílo přivede na soud⌉ se vším, co je skryto, ať dobrým nebo zlým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Píseň písní. Šalomounova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Kéž v polibcích mě ústy svými zlíbá! Nad víno lepší je tvé milování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, '⌈Vzácné tvé oleje tak voní!⌉ Tvé jméno je ⌈esence aromatická.⌉ Proto dívky tě milují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Vtáhni mě za sebou, pojďme honem! Už mne král uvedl do komnat u sebe! Výskejme, radost mějme z tebe. Oslavíme lásku tvou, a ne vínem. Zcela právem tě milují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Jsem černá, ale krásná, vy dcery v Jeruzalémě, jak stany kédarského kmene, jak závěsy ve stanu Šalomouna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Nehleďte na mne, že jsem osmahlá, že slunce tak opálilo mne. Proti mně vzpláli mé matky synové, ⌈postavili mne, ať vinohrady hlídám.⌉ Vlastní vinohrad jsem neuhlídala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Miláčku můj, pověz, kde je tvá pastvina, kde přes poledne dáváš ležet stádu? Vždyť proč mám stát jak zastřená před stády tvých kamarádů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Když to nevíš sama, ⌈ženo mnoha krás,⌉ vyjdi si po stopách stáda a kozičky své pas před příbytky pastevců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Jako klisna mezi hřebci faraona ⌈připadáš mi,⌉ lásko má.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, '⌈ Po líci se ti vinou⌉ pramínky, korále tvou šíji vroubí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Pramínky zlaté uděláme ti, ⌈v nich stříbro jako kapičky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Dokud král u sebe si hoví, můj nard vůni vydává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Voničkou myrhy je mi můj milý, v mých prsech když spočívá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Keříkem henny je mi můj milý na vinicích v Én–gedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Jak jsi krásná, lásko má, jak jsi krásná. Oči máš jako holoubky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Jak jsi krásný, můj milý, jak hezounký jsi! Naše lože prostírá se v zeleni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Dům náš cedrové má trámy, hřeben cypřišový.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'A já -- šáronský kvítek, lilie údolní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Pak tedy lilie mezi bodláky, to je má láska mezi dívkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Pak tedy jabloň v lese mezi stromy, to je můj milý mezi mládenci. Po jeho stínu ⌈jsem zatoužila.⌉ Sedím a na jeho sladkém ovoci pochutnávám si.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Zaveďte mne, ⌈kde víno dávají,⌉ a ⌈podávejte mi lásku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Oživte mne ⌈hrozinkovými koláči,⌉ z jablek mi dodejte sílu, neboť jsem láskou nemocná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, '⌈Hlavou mu na levici ležím,⌉ svou pravicí mne objímá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Zapřísahám vás, dcery Jeruzaléma, při plachých gazelách a laních, ať nebudíte, neprobouzíte lásku, dokud nebude chtít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, '⌈Slyš! To je můj milý!⌉ Hleďte, už jde! Už skáče přes hory, přeskakuje kopce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Jako srnec je můj milý, jak samec gazely. Hleďte, už stojí u ⌈nás za zdí,⌉ do okének nahlíží, mřížkami hledí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Ozval se můj milý, toto mi praví: Vstávej, má lásko, pojď, ty má krásko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Vždyť skončila už zima, pominuly deště, ⌈jsou ty tam.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Květinky z ⌈půdy prokvétají,⌉ přišel čas révu prořezat, hrdliččin hlas je slyšet ⌈po kraji.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Na fíkovníku dozrávají fíky první, réví už rozkvétá, vydává vůni. Vstávej, má lásko, pojď, ty má krásko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Holoubku můj ve skále schovaný, ukrytý na srázu u stěny, jak vypadáš, ukaž se mi, ⌈ať slyším⌉ tvůj hlas! Vždyť hlas tvůj tak libě zní a ⌈pohled na tebe⌉ je plný krás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Pochytejte nám lišky, lištičky, co na vinicích škodí. Vždyť naše vinice rozkvétá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Můj milý je můj a já jeho. V liliích se pase.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Než zavane den a prchnou stíny, ukaž se, ⌈můj milý, ⌈buď jako⌉ srnec, jak samec gazely⌉ na ⌈horách mezi vrcholy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Miláčka svého jsem hledala celou noc na loži. Hledala jsem, a nenašla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Musím vstát a město obejít, po ulicích a po náměstích svého hledat miláčka. Hledala jsem, a nenašla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Našli mne strážci, kteří město obcházejí. -- Miláčka mého, ne viděli jste ho?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Sotva jsem od nich poodešla, už jsem miláčka svého našla. Držím ho a nepustím, dokud ho nepřivedu ⌈k matičce své domů,⌉ do ⌈maminčina pokoje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Zapřísahám vás, dcery Jeruzaléma, při plachých gazelách a laních, ať nebudíte, neprobouzíte lásku, dokud nebude chtít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kdo je ta, jež z pouště stoupá jako sloup dýmu, ⌈myrhou provoněná i kadidlem z dovážených koření?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Hle, nosítka samého Šalomouna! Šedesát hrdinů okolo nich z ⌈Izraele nejudatnějších.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Mečem vládnou všichni, ⌈ v boji zkušení,⌉ každý ⌈se mečem opásal,⌉ ani noc je ne zaskočí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Nosítka pořídil si Šalomoun král ze dřeva z Libanonu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Sloupky jim ze stříbra udělal, ze zlata ⌈oporu trůnu,⌉ sedadlo purpurové. Láskou jsou uvnitř vystlána od dívek z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, '⌈Pojďte ven pohledět,⌉ vy dcerky Sijónu, na krále Šalomouna, ⌈na jeho korunu,⌉ již mu jeho matka nasadila v den svatby jeho, v den, ⌈ kdy mu srdce plesalo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Jak jsi krásná, lásko má, jak jsi krásná. Oči máš jako holoubky, když zpod závoje hledí. Vlasy tvé co ve stádu kozičky z pohoří Gileád sbíhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Tvé zuby -- ⌈ovečky čerstvě umyté, když stádo ke střiži stoupá⌉ z koupele. Každá z nich po dvou rodí a neplodné mezi nimi není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Karmínová stuha jsou tvé rty, tvá ústa nádherná. Jak z rozpuklého jablka granáty zpod závoje skráň hledí tvá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Jako věž Davidova je tvá šíje ztepilá. Na tisíc zavěšeno na ní štítů, výstroj samých to hrdinů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Dva koloušci je dvojice prsů tvých, dvojčátka gazelí, jež pasou se v liliích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Než zavane den a prchnou stíny, vyjdu si k té hoře myrhy, k pahorku ⌈vonných pryskyřic.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Celá jsi krásná, lásko má, není na tobě poskvrna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Nevěsto, se mnou z Libanonu, se mnou z Libanonu sestup dolů. Shlédneš z vrcholu Amány, z vrcholu Seníru a Chermónu, ze lvích doupat, z hor leopardů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, '⌈Srdce jsi mi odjala,⌉ ⌈nevěsto má nejdražší,⌉ srdce jsi mi odjala očkem svým jediným, zákrutem jediným svého náhrdelníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Jak je krásné milování tvé, nevěsto má nejdražší, oč lepší je nad víno tvé milování. Nade všechny balzámy tvé oleje voní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Tvé rty, nevěsto, medem kanou, mléko a med máš pod jazykem, ⌈roucho tvé vůní Libanonu voní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Zahrada zavřená jsi, nevěsto má nejdražší, valem zahrazená, pramen zapečetěný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tvé údy královská je obora, granátovníky s lahodným ovocem, hennou a nardem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'nardem a šafránem, citronelou a skořicí, ⌈k tomu⌉ všemožné ⌈vonné dřeviny,⌉ myrha i aloe a ty nejvzácnější balzámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Pramenem zahrad jsi, studnou vody živé, až z Libanonu tekoucí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Zvedni se, od severu větře, přijď, větře od jihu, prověj mou zahrádku, ať vlastní vůní orosí se. Ať do své zahrady přijde můj milý a její ovoce lahodné okusí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Do své přišel jsem zahrady, ⌈nevěsto má nejdražší.⌉ Svou myrhu i své balzámy natrhal jsem, ze své plástve se svým medem pojedl jsem, víno své i se svým mlékem popíjel jsem. ⌈ Jen jezte, milí, pijte, opojte se milováním.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Spím. Mé srdce ale bdí. Slyš! To klepe můj milý! Otevři mi, má lásko nejdražší, holoubku můj, zlato mé! Vždyť hlavu mám plnou rosy, krůpějí noci své kadeře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Svlékla jsem si šaty, mám je zase oblékat? Umyla jsem si nohy, to si je mám špinit zas?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Můj milý rukou vnikl ke mně, až jsem se pro něj v nitru zachvěla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Já vstala milému svému otevřít a myrha mi z rukou skanula, myrha z mých prstů ulpívá tam, kde zasouvá se závora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Já svému milému otevřela, můj milý však ⌈náhle zmizel.⌉ ⌈ Skoro jsem život vypustila,⌉ že takhle odešel. Hledala jsem jej, ale nenašla. Volala jsem ho, už se mi neozval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Našli mne strážci, kteří město obcházejí. Zbili mě do krve, šál strhli ze mne ti strážci hradeb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Zapřísahám vás, dcery Jeruzaléma, když mého milého najdete, co jemu povíte? Že láskou jsem nemocná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Čím je tvůj milý nad jiné, ženo mnoha krás? Čím je tvůj milý nad jiné, že tak zapřísaháš nás?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Můj milý, jiskrný a růžolící, ⌈znát je⌉ mezi statisíci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hlavu má jak z ryzího zlata, černé jak havran kučery jeho kadeří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Oči jeho nad vodními proudy holoubata v mléce umytá nad ⌈hojnou vodou⌉ sedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Jeho líce záhon balzámový osetý kořením, co lilie rty jeho kanoucí myrhou tekutou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Ruce má jak válce zlaté osázené topazem. Jeho břicho vykládané slonovinou pokryto je safíry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Mramorové sloupy jeho stehna, na patkách zlata ryzího postaveny. ⌈Zjevem se Libanonu podobá,⌉ ušlechtilý jako ty cedry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Jeho ústa jsou přesladká a ve všem je přitažlivý. To je můj milý a to je můj druh, dcery Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Kampak tvůj milý šel, ty ženo mnoha krás? Kam se tvůj milý poděl, ať s tebou najdeme ho zas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Do zahrádky své sestoupil můj milý na záhony balzámové, v zahradách ⌈se pást,⌉ lilie nasbírat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Můj milý má mne, můj milý je můj. V liliích se pase.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Krásná jsi, lásko má, jako město Tirsa, jak Jeruzalém nádherná. ⌈Respekt budíš⌉ jak ⌈nazbrojená armáda.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Odvrať ode mne své oči, ⌈nebo mne o rozum připraví.⌉ Vlasy tvé co ve stádu kozičky dolů z Gileádu sbíhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Tvé zuby -- ⌈ovečky čerstvě umyté, když stádo stoupá⌉ z koupele. Každá z nich po dvou rodí a není mezi nimi neplodná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Jak z rozpuklého jablka granáty zpod závoje skráň hledí tvá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Na šedesát je královen a družek na osmdesát a dívek bezpočet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'ona je však jediná, holoubek můj, zlato mé. Ona je však jediná pro matičku svou, pro maminku, jež ji má za vyvolenou. Jak ji děvčata uzřela, ⌈zahrnula ji chválou.⌉ Královny a družky počaly ji velebit:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Kdo je ta, jež dolů jako úsvit hledí, jako luna krásná, jako slunce jasná? Respekt budí jak nazbrojená armáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Do sadu sešel jsem k ořeší podívat se na zeleň ve vádí, podívat se, zda réva vyraší, zda rozkvetly už granáty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Ne ž má duše zvěděla, na vozy mne stavěla lidu mého šlechetného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Tanči, tanči, Šulamít, tanči, tanči, chcem tě zřít! Co uzříte na Šulamít, že má v tanci sólo mít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Jaká je krása tvých kroků v opáncích, dívko ty šlechetná! ⌈Klenotem je křivka tvých boků,⌉ rukama umělce vykroužená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Tvůj klín se jak mísa klene. Ať ⌈víno mísit⌉ nepřestane. Tvé bříško pšenice navršená, liliemi obroubená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Dva koloušci dvojice prsů tvých, dvojčátka gazelí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Šíje tvá věži ze slonoviny se podobá. Tvé oči ⌈batrabimskou bránu zračí jak v chešbónských nádržích.⌉ Tvůj nos jako věž Libanonu si Damašek prohlíží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Hlava na tobě jako Karmel vyjímá se a ⌈ v plášti tvých vlasů šarlatovém⌉ král kvůli té kučeravé kráse zajatcem je rázem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Jak krásná jsi, jak líbezná, lásko přerozkošná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Neseš se tak, že připomínáš palmu a tvé prsy ⌈vzdouvají se datlemi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Chci vylézt na palmu, říkám si, datlové trsy popadnu. Nebo ať jsou tvé prsy bobulová réva, ať po jablkách ti voní dech');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'a v ústech -- jako bys to nejlepší víno měla. Pro mého milého kane! Hladce po rtech starců klouzá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'můj milý má mne. Po mně prahne jeho touha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Jen pojď, můj milý, pojďme ven do polí, ať venku přespíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Podíváme se ráno na vinice, réva jestli vyraší, zda její květ rozvírá se a rozkvetly už granáty. Tam ti dám své milování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'Laskavec vůni už přivání a nad našimi dveřmi dozrály lahůdky, nové i staré. Pro tebe, můj milý, schovala jsem je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Kéž bys byl bratr mé rodiny, ⌈maminkou mou odkojený.⌉ Jak bych tě potkala, hned bych tě líbala. A nikdo by mě nepomluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Jak bych se s tebou vodila, hned bych s tebou zamířila k mámě domů, ta mě učívala. Ukojila bych tě vermutem, svých granátů nektarem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Hlavou mu na levici ležím, svou pravicí mne objímá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Zapřísahám vás, dcery Jeruzaléma, nač budit, nač probouzet lásku, dokud nebude chtít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kdo je ta, jež stoupá z pouště, o milého se opírá? Pod jabloní probouzela jsem tě, tam počala tě matka tvá, tam počala i zrodila tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Chovej mne jak pečetidlo u srdce, měj mě jako pečetítko při ruce. Vždyť láska je silná jako smrt, žárlivost jako záhrobí tvrdá, žár její žárem ohně zhrdá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Tu lásku neuhasí velká voda, ⌈odplavit ji nedokáže⌉ dravý proud. Byť by kdo za lásku dával vše, ⌈co má,⌉ ⌈vypadal by jak prostoduchý bloud.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Sestřičku malou máme, ani prsa ještě nemá. Co se sestřičkou uděláme, ⌈až začne být žádaná?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Je–li hradbou, cimbuří stříbrné postavíme na ní. Je–li však bránou, deskou cedrovou ⌈ musíme ji zahradit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Já jsem hradba. A prsa mám jako věže. Už jsem se ⌈pro něj⌉ stala tou, kterou nepřemůže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Vinohrad v ⌈Baal Hamon⌉ měl Šalomoun. Svěřil ten vinohrad správcům, za výnos ať mu každý stříbrných tisíc platí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Vinice má ⌈ je jenom moje.⌉ Šalomoune, ten tisíc si nech. Dvě stě ať mají i správcové na jejích výnosech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Ty, která přebýváš v zahradách, přátelé naslouchají tvému hlasu. Ať slyším ho i já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Chvátej, můj milý, buď jako srnec, jak samec gazely na horách provoněných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Vidění Izajáše, syna Amósova, které viděl o Judsku a Jeruzalému za dnů judských králů Uzijáše, Jótama, Achaza a Chizkijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Slyšte, nebesa, naslouchej, země, protože Hospodin promluvil: Syny jsem vychoval a vycvičil, ale oni se proti mně vzbouřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Býk zná svého hospodáře a osel žlab svého majitele, ale Izrael mě nezná, můj lid nerozumí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ach, hřešící národe, lide obtížený vinou, potomstvo zločinců, děti ničitelů! Opustili Hospodina, znevážili Svatého Izraele, odvrátili se zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Proč máte být ještě biti? Jste stále umíněnější. Celá hlava je nemocná a celé srdce zemdlené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Od paty k hlavě na něm není zdravého místa -- samá modřina a šrám a čerstvá rána; nejsou vymačkány ani obvázány ani změkčeny olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Vaše země je zpustošená, vaše města jsou vypálena ohněm, vaši půdu před vámi sžírají cizinci; je zpustošená jako po rozvrácení cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Dcera sijónská zůstala jako stánek na vinici, jako budka v okurkovém poli, jako obležené město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Kdyby nám Hospodin zástupů neponechal maličko těch, kteří přežili, byli bychom jako Sodoma, byli bychom podobní Gomoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Slyšte Hospodinovo slovo, vůdcové sodomští, naslouchej, lide gomorský, zákonu našeho Boha!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'K čemu je mi množství vašich obětí? praví Hospodin. Jsem syt zápalných obětí beranů a tuku krmného dobytka. V krvi býčků, beránků a kozlů nemám zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Když přicházíte, abyste se přede mnou ukazovali, kdo to od vás žádal, abyste šlapali po mých nádvořích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Nepřinášejte už falešné obětní dary; kadidlo je mi ohavností. Novoluní a soboty, svolávání shromáždění; nesnáším ⌈shromáždění, kde je zlo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Vaše novoluní a svátky má duše nenávidí; jsou mi břemenem, jsem vyčerpán jejich snášením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Když rozprostíráte své dlaně, zavírám před vámi oči. I když rozmnožíte své modlitby, neposlouchám: Vaše ruce jsou plné krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Umyjte se, pročistěte se, odstraňte mi zkaženost svých činů pryč z očí; přestaňte páchat zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Naučte se konat dobro. Hledejte právo, kárejte násilníka, zjednejte právo sirotkovi, zastaňte se vdovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Jen pojďte a proberme to, praví Hospodin; jsou–li vaše hříchy jako šarlat, zbělejí jako sníh, jsou–li rudé jako purpur, budou jako vlna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Podvolíte–li se a budete poslouchat, budete jíst ⌈dobré věci⌉ země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Jestliže však odmítnete a budete vzpurní, budete požíráni mečem. Neboť Hospodinova ústa promluvila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Jak jen se stalo nevěstkou to město věrné, plné práva! Zůstávala v něm spravedlnost, a nyní -- vrahové!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Tvé stříbro se stalo struskou, tvůj nápoj je zředěn vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Tvá knížata jsou umíněnci a spojenci zlodějů; každý miluje dar a žene se za úplatky. Sirotkovi právo nezjednají a spor vdovy se k nim nedostane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Proto je výrok Panovníka, Hospodina zástupů, Mocného Izraele: Běda! Potěším se na svých protivnících a pomstím se na svých nepřátelích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Obrátím svou ruku proti tobě a tvé strusky očistím jako louhem. Odstraním veškeré tvé příměsi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'A obnovím tvé soudce jako na počátku a tvé rádce jako zprvu. Potom tě budou nazývat městem spravedlnosti, ⌈městem věrným.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, '⌈Soudem bude vykoupen Sijón a ti, kdo se v něm obrátí, budou vykoupeni spravedlností.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Zkáza vzpurných a hříšníků bude společná; ti, kdo opouštějí Hospodina, pominou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Neboť budou zahanbeni kvůli dubům, jichž jste byli žádostiví, budete se stydět kvůli zahradám, jež jste zvolili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Protože budete jako dub, jehož listí padá, a jako zahrada, která vodu nemá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'A ⌈silný se stane koudelí a jeho skutek⌉ jiskrou. Vzplane to obojí spolu a nebude, kdo by to uhasil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Slovo, které Izajáš, syn Amósův, viděl o Judsku a Jeruzalému:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'I stane se v posledních dnech, že hora Hospodinova domu bude pevně stát jako přední z hor a bude vyvýšena nade všechna návrší. Budou k ní proudit všechny národy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'a mnozí lidé přijdou a řeknou: Pojďte a vystupme na horu Hospodinovu, do domu Boha Jákobova. Bude nás vyučovat podle svých cest a budeme chodit po jeho stezkách. Neboť ze Sijónu vyjde zákon a Hospodinovo slovo z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'A bude soudit mezi těmi národy a domlouvat mnohým lidem. I překují své meče v radlice a svá kopí ve vinařské nože; národ proti národu nepozdvihne meč a už se nebudou učit boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Pojďte, ⌈dome Jákobův,⌉ a choďme v Hospodinově světle!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Hospodine, vždyť jsi zavrhl svůj lid, dům Jákobův, protože jsou plni ⌈východního věštění ⌉ a hádání z oblaků jako Pelištejci; s dětmi cizozemců si potřásají rukama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Jeho země je plná stříbra a zlata a jeho pokladům není konce; jeho země je plná koní a jeho válečným vozům není konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Jeho země je plná nicotností. Klanějí se dílu svých rukou, které učinily jeho prsty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Člověk se hrbí, muž je ponížený. Neodpouštěj jim!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Vejdi do skal, skryj se do prachu ⌈ze strachu z Hospodina⌉ a před nádherou jeho vznešenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Domýšlivý pohled člověka bude snížen -- skloní se hrdost lidí. Hospodin sám bude vyvýšen v onen den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Neboť den Hospodina zástupů přichází na všechno pyšné a povýšené, na vše, co se pozvedá, a bude to sníženo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Na všechny vznešené a vyvýšené libanonské cedry a na všechny bášanské duby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'na všechny vysoké hory a na všechna vyvýšená návrší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'na každou vysokou věž a na každou opevněnou hradbu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'na všechny taršíšské lodě a na všechny vzácné jachty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'A skloní se domýšlivost člověka, bude snížena hrdost lidí. Hospodin sám bude v ten den vyvýšen');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'a nicotnosti zcela pominou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'A vejdou do skalních jeskyní a do roklin prachu země ze strachu z Hospodina a před nádherou jeho vznešenosti, když povstane, aby otřásl zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'V onen den člověk své stříbrné i zlaté nicotnosti, které mu udělali, aby se jim klaněl, odvrhne krysám a netopýrům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'aby vešel do dutin těch skal a do skalních trhlin ze strachu z Hospodina a před nádherou jeho vznešenosti, když povstane, aby otřásl zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, '⌈Přestaňte se spoléhat na člověka,⌉ jehož dech je v jeho chřípí; vždyť ⌈za co má být považován?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Vždyť hle, Panovník, Hospodin zástupů, odnímá Jeruzalému a Judsku ⌈veškerou pomoc;⌉ všechnu podporu chleba i všechnu podporu vody,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'hrdinu i bojovníka, soudce i proroka, věštce i starce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'velitele nad padesáti, vznešeného i rádce, zběhlého v čárech a rozumějícího zaříkávání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'A dám jim mládence za knížata a budou jim vládnout uličníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'V lidu bude útlak -- jeden bude dotírat na druhého, každý na svého bližního; mládenec bude naléhat na starce a bezectný na váženého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Když se člověk chopí bratra z domu svého otce: Máš plášť, buď naším vůdcem a měj tuto spoušť pod svou rukou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'ten v onen den zvolá: Nebudu ovazovat ty rány, v mém domě není pokrm ani plášť, nečiňte mne vůdcem lidu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Vždyť Jeruzalém klopýtl a Juda padl, protože jejich jazyk i jejich činy byly proti Hospodinu na odpor očím jeho slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Svědčí o nich výraz jejich tváře a svůj hřích oznamují jako Sodoma -- netají jej. Běda jim, protože na sebe uvedli zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, '⌈ O spravedlivém řekněte,⌉ že mu bude dobře, protože bude jíst ovoce svých činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Běda ničemovi! Bude zle! Protože se mu stane podle toho, co vykonaly jeho ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Ó můj lid! Jeho utlačovatelé ⌈jednají svévolně⌉ a vládnou mu ženy. Ó můj lide! Tvoji vůdcové vedou do bludu a směr tvých stezek zmátli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Hospodin přistupuje k soudnímu procesu; povstává, aby soudil národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Hospodin vejde v soud se staršími svého lidu a s jeho knížaty: Vy jste vyplenili tu vinici, to, co jste vyrvali chudému, je ve vašich domech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Proč deptáte můj lid a drásáte tváře chudých? je výrok Panovníka, Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'I řekl Hospodin: Protože se dcery sijónské povyšují, chodí s nataženým hrdlem, svádějí očima, chodí cupitavou chůzí a chřestí kroužky na nohou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Panovník raní temeno dcer sijónských prašivinou a jejich čelo Hospodin obnaží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'V onen den Panovník odstraní ozdobné nánožníky, čelenky a půlměsíčky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'náušnice, náramky a závoje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'klobouky, řetízky a pentle, nádobky vůní a amulety,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'prsteny a nosní kroužky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'róby a pláště, plachetky a vaky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'zrcadla a košilky, turbany a řízy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'I stane se, že místo balzámu bude zápach a místo pásu oprátka, místo úpravy účesu lysina a místo skvostného roucha přepásání pytlovinou; vypálené znamení namísto krásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Tvoji muži padnou mečem a tvoji udatní ve válce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Tvé brány se budou rmoutit a budou truchlit a ty, o vše připravená, budeš sedět na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'V onen den se chopí sedm žen jednoho muže se slovy: Budeme jíst vlastní pokrm a budeme si oblékat vlastní oděv, jen ať jsme nazvány tvým jménem; odejmi naši potupu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'V onen den bude výhonek Hospodinův nádherný a slavný, plod země pýchou a okrasou pro ty z Izraele, kteří vyváznou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'I stane se, že ten, kdo zůstane na Sijónu a bude ponechán v Jeruzalémě, bude nazván svatý -- každý zapsaný k životu v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Když Panovník smyje nečistotu dcer sijónských a vypláchne krev Jeruzaléma z jeho středu duchem soudu a duchem ohnivé očisty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Hospodin stvoří nad každým sídlem hory Sijón a nad jejími shromážděními oblak ve dne a kouř a zář plápolajícího ohně v noci; protože nad vší slávou bude baldachýn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Bude to stánek jako zastínění před horkem ve dne a jako útočiště a úkryt před přívalem i před deštěm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Nuže, budu zpívat svému milému ⌈píseň mého milého⌉ o jeho vinici: Můj milý měl vinici ⌈na úrodném vrchu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Zkypřil ji, vybral z ní kamení, vysadil ji vybranou révou; vystavěl uprostřed ní věž a také v ní vytesal lis. Očekával, že vydá hrozny, ale vydala ⌈páchnoucí bobule.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'A teď, obyvatelé Jeruzaléma a muži judští, jen suďte mezi mnou a mou vinicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Co ještě se mělo udělat pro mou vinici, co jsem v ní neudělal? Proč, když jsem očekával, že vydá hrozny, vydala páchnoucí bobule?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'A teď vám chci oznámit, co učiním se svou vinicí: Odstraním její plot a přijde vniveč, zbořím její zeď a bude k pošlapání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Určil jsem ji ke zkáze: Nebude prořezávána ani pleta a vyroste na ní trní a bodláčí; oblakům přikáži, aby na ni nesesílala déšť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Vždyť vinicí Hospodina zástupů je dům izraelský a muži judští jsou sadbou jeho potěšení. Čekal na právo, a hle -- bezpráví, na spravedlnost, a hle -- křik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Běda těm, kteří připojují dům k domu, přibližují pole k poli, až už není místo a zůstáváte v zemi bydlet sami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, '⌈Slyšel jsem Hospodina⌉ zástupů: Jistě mnohé domy zpustnou, i veliké a hezké domy budou bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Neboť deset jiter vinice vydá jeden bat a chómer zrna vydá éfu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Běda těm, kteří vstávají brzy ráno a shánějí pivo, těm, kdo za soumraku prodlévají, až je víno rozpálí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Na jejich hostinách je lyra a harfa, tamburína a flétna i víno, ale na Hospodinovy skutky nehledí a dílo jeho rukou nevidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'A tak bude můj lid vystěhován pro nedostatek poznání, ⌈jeho vážení lidé budou hynout hladem⌉ a jeho dav bude vyprahlý žízní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Proto podsvětí rozevřelo svůj chřtán a bezmezně otevřelo svá ústa a důstojnost Jeruzaléma i jeho dav, jeho hukot i jásání do něho sestoupí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, '⌈Shrbí se člověk a ponížen bude muž⌉ a oči povýšené budou sníženy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Hospodin zástupů bude vyvýšen v soudu a svatý Bůh bude posvěcen v spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Beránci se budou pást ⌈jako na ⌉ svých pastvinách a pustiny ⌈ po vykrmených kusech budou spásat příchozí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Běda těm, kdo táhnou vinu provazy klamu a jako popruhem u vozu hřích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'kteří říkají: Ať si pospíší, ať uspíší své dílo, abychom viděli, ať se přiblíží a ⌈naplní plán⌉ Svatého Izraele, abychom to poznali!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Běda těm, kdo zlu říkají dobro a dobru zlo, kdo pokládají temnotu za světlo a světlo za temnotu, kdo pokládají hořké za sladké a sladké za hořké.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Běda těm, kdo jsou moudří ve vlastních očích a před sebou samými rozumní!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Běda hrdinům v pití vína a mužům udatným v řezání piva,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'těm, kdo kvůli daru ospravedlňují ničemu a spravedlivým jejich spravedlnost upírají!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Proto jako jazyk ohně požírá strniště a suchá tráva v plamenu klesne, tak jejich kořen shnije a jejich květ odlétne jako prach, protože pohrdli zákonem Hospodina zástupů a řeč Svatého Izraele znevážili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Proto vzplanul proti jeho lidu Hospodinův hněv, vztáhl proti němu ruku a ubil ho. Hory se třásly a jejich mrtvoly byly jako smetí na ulicích. Ani v tom všem se jeho hněv neodvrátil a jeho ruka je stále vztažená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Pozvedne korouhev k dalekému národu a hvízdne na něho od konce země; a hle, přijde spěšně a hbitě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Nebude v něm nikdo vyčerpaný ani klopýtající, nikdo nebude dřímat ani spát a nikomu se neuvolní pás na bedrech ani se nepřetrhne řemínek boty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Jeho šípy jsou ostré a všechny jeho luky jsou napnuty, kopyta jeho koní jsou jako křemen a jeho kola jako vichřice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Jeho řev je jako řev lvice; zařve jako mladý lev, zavrčí, uchopí kořist a bezpečně odnese; není nikdo, kdo by ji vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'A v ten den na něj zavrčí, ⌈jako když burácí⌉ moře. Pohledí– li kdo na zemi, hle, tísnivá temnota a světlo ztemnělo v oblacích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, '⌈V roce, kdy zemřel král Uzijáš,⌉ jsem viděl Panovníka sedícího na trůnu vysokém a vyvýšeném a lem jeho roucha naplňoval chrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Nad ním stáli serafové, každý měl po šesti křídlech: Dvěma si zakrývali tvář, dvěma si zakrývali nohy a dvěma létali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'a jeden na druhého volal: Svatý, svatý, svatý je Hospodin zástupů; celá země je plná jeho slávy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'A čepy prahu se otřásaly od hlasu toho, který volal, a dům byl plný kouře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'I řekl jsem: Běda mi, jsem zničen, protože jsem člověk nečistých rtů a bydlím uprostřed lidu nečistých rtů, a mé oči viděly Krále, Hospodina zástupů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Vtom ke mně přilétl jeden z těch serafů a v ruce měl žhavý uhel, který vzal kleštěmi z oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Dotkl se mých úst a řekl: Hle, tento uhel se dotkl tvých rtů; tvá vina je odvrácena a tvůj hřích je usmířen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Potom jsem uslyšel hlas Panovníka, jak říká: Koho pošlu a kdo nám půjde? Řekl jsem: Zde jsem, pošli mne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'I řekl: Jdi a řekni tomuto lidu: Stále poslouchejte, ale nebudete rozumět, stále hleďte, ale nebudete znát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Učiň srdce tohoto lidu tučným a jeho uši zacpi a jeho oči zalep, aby očima neviděl a ušima neslyšel a jeho srdce nerozumělo, neobrátil se a já ho neuzdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Nato jsem řekl: Až dokdy, Panovníku? A on odpověděl: Až dokud města nezpustnou a nebudou bez obyvatel a domy bez lidí a země nebude zpustošena -- zcela opuštěná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Hospodin vzdálí lidi daleko -- veliká opuštěnost bude uprostřed této země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'A ještě v ní zbude desetina, ale znovu přijde vniveč; jako terebint a jako dub, ze kterých po pokácení zůstane jen pahýl. Ten pahýl je svaté símě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'I stalo se za dnů judského krále Achaza, syna Jótama, syna Uzijášova, že vytáhl Resín, král aramejský, a Pekach, syn Remaljášův, král izraelský, do boje proti Jeruzalému. Ale nemohl ho dobýt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'A domu Davidovu bylo oznámeno: Aram ⌈se spojil s Efrajimem.⌉ Srdce krále i srdce jeho lidu se roztřáslo, jako se třesou lesní stromy ve větru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'A Hospodin řekl Izajášovi: Teď vyjdi vstříc Achazovi, ty a tvůj syn Šearjašúb, na konec strouhy Horního rybníka, na silnici k Valchářovu poli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'a řekni mu: Měj se na pozoru a uklidni se, neboj se a tvé srdce ať neochabne před těmito dvěma čadícími opálenými špalky, kvůli planoucímu hněvu Resína a Aramu a syna Remaljášova');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'proto, že na tebe Aram s Efrajimem a synem Remaljášovým připravili zlo se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Vytáhneme proti Judovi, ochromíme ho, rozdělíme si ho a ustanovíme v něm králem syna Tabealova!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Toto praví Panovník Hospodin: To se nenaplní a nestane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Neboť hlavou Aramu je Damašek a hlavou Damašku Resín; a během šedesáti pěti let bude Efrajim otřesen tak, že již nebude lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Hlavou Efrajima je Samaří a hlavou Samaří syn Remaljášův. Nebudete–li věřit, jistě neobstojíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Hospodin dále mluvil k Achazovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Vyžádej si od Hospodina, svého Boha, znamení, ⌈žádej, ať to je hluboko dole ⌉ nebo vysoko nahoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Ale Achaz řekl: Nebudu žádat a nebudu zkoušet Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Nato Izajáš řekl: Slyšte nyní, dome Davidův. Málo je vám unavovat lidi, že budete unavovat i mého Boha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Proto vám Panovník dá znamení sám: Hle, dívka otěhotní, porodí syna a dá mu jméno Immanuel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Bude jíst máslo a med, aby uměl zavrhnout zlé a zvolit dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Protože dříve než ten chlapec bude umět zavrhnout zlé a zvolit dobré, země, jejíchž dvou králů se děsíš, bude opuštěna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Hospodin uvede na tebe, na tvůj lid a na dům tvého otce dny, jaké nepřišly ode dne odstoupení Efrajima od Judy -- přivede asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, '⌈I stane se v onen den,⌉ že Hospodin hvízdne na mouchy na konci egyptských řek a na včely v asyrské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Přitáhnou a všechny se usadí v korytech potoků a ve skalních trhlinách, ve všech křovinách a ve všech napajedlech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'V onen den Panovník oholí čepelí najatou za Řekou -- asyrským králem -- hlavu a chlupy nohou, a také plnovous odstraní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'V onen den člověk zachová při životě ze skotu jalovici a dvě ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Avšak pro množství získaného mléka bude jíst máslo, neboť máslo a med bude jíst každý, kdo bude ponechán v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'I stane se v onen den, že na každém místě, na kterém je tisíc vinných keřů za tisíc stříbrných, bude trní a bodláčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Člověk tam půjde s lukem a s šípy, protože celá země bude trní a bodláčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'A na žádnou horu, která se okopává motykou, nebudeš chodit ze strachu z trní a bodláčí; bude výběhem pro skot a k pošlapání ovcím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Hospodin mi řekl: Vezmi si velikou tabuli a napiš na ni ⌈běžným způsobem:⌉ ⌈Spěšná kořist, rychlý lup.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'I povolal jsem si spolehlivé svědky: kněze Urijáše a Zekarjáše, syna Jeberekjášova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Přiblížil jsem se k prorokyni, otěhotněla a porodila syna. Hospodin mi řekl: ⌈Dej mu⌉ jméno Spěšná kořist, rychlý lup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Protože dříve než bude chlapec umět volat otče a matko, odnesou majetek Damašku a kořist ze Samaří před asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Hospodin ke mně mluvil ještě dále:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Protože tento lid pohrdl klidně plynoucími vodami Šíloach a raduje se s Resínem a synem Remaljášovým,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'proto hle, Panovník na ně přivádí mocné a hojné vody Řeky -- asyrského krále a všechnu jeho slávu -- a vystoupí nad všechna svá řečiště a půjde přes všechny své břehy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Projde Judou, zaplaví ho a půjde přes něj, dosáhne až k šíji; rozepjetím jeho křídel bude naplněna šíře tvé země, Immanueli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Jednejte zle, národy, a zděsíte se, naslouchejte všechny dálavy země. Opásejte se a zděsíte se, opásejte se a zděsíte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Udělejte plán, a bude zmařen, ⌈řekněte slovo,⌉ a nenaplní se, protože s námi je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Vždyť toto mi řekl Hospodin, ⌈když mě uchopil za ruku⌉ a varoval mě, abych nechodil po cestě tohoto lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Neříkejte spiknutí všemu, čemu tento lid říká spiknutí; toho, z čeho má on strach, se nebojte a nestrachujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Hospodin zástupů -- jen ⌈on vám budiž svatý;⌉ ⌈on je vaše bázeň a on je vaše strachování.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'On vám bude svatyní, ale ⌈kamenem úrazu⌉ a skálou pohoršení pro oba domy izraelské, pastí a léčkou pro obyvatele Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Mnozí z nich klopýtnou, padnou a polámou se, budou chyceni a zajati.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Zavaž svědectví a zapečeť zákon mezi mými učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Budu vyčkávat na Hospodina, který skrývá svou tvář před domem Jákobovým; budu očekávat na něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Hle, já a děti, které mi dal Hospodin, jsme v Izraeli za znamení a divy od Hospodina zástupů, který přebývá na hoře Sijón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'A jestliže vám řeknou: Dotazujte se ⌈těch, kdo vyvolávají duchy zemřelých,⌉ a věštců, kteří piští a mumlají ... ⌈Což se lid nemá dotazovat svého Boha? Kvůli živým má hledat mrtvé?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'K zákonu a ke svědectví! Nebudou–li mluvit podle tohoto slova, ⌈tak v něm pro ně není úsvit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Každý zkroušený a hladový bude procházet zemí, a jak bude hladový a vzteklý, bude proklínat svého krále i svého Boha. Obrátí se vzhůru');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'a pohledí k zemi, a hle, soužení a temnota, ponurá sklíčenost -- vkrádá se soumrak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, 'Avšak ne zůstane pochmurná, jako teď, když na ni dolehla tíseň. Jako v době, kdy nejprve zlehčil zemi Zabulón a zemi Neftalí, ale nakonec jí dodá vážnost -- cestě u moře, Zajordání a Galileji národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Lid, který chodí v temnotě, uvidí veliké světlo. Na ty, kdo bydlí v zemi nejhlubší tmy, na ně zazáří světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Rozmnožil jsi ten národ a zvětšil jsi jeho radost. Radovali se před tebou, jako když mají radost ze žně, jako když jásají při dělení kořisti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'protože jho jeho břemene i ⌈hůl na jeho ramena⌉ i žezlo jeho utlačovatele jsi rozdrtil jako v den Midjánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Proto každá bota, ⌈která šlape⌉ ve vřavě, a plášť, který se válí v krvi, bude ke spálení, jako pokrm ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Neboť chlapec se nám ⌈narodil, syn je nám dán; na jeho rameni spočinulo⌉ panství. ⌈Dal mu⌉ jméno Podivuhodný rádce, mocný Bůh, Věčný Otec, Kníže pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Nebude konce ⌈vzrůstu jeho panství⌉ a pokoje na Davidově trůnu a nad jeho královstvím, aby ho mohl upevnit a ⌈posilnit v právu a v spravedlnosti⌉ ⌈od nynějška až navěky. Horlivost Hospodina zástupů to učiní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Panovník poslal slovo proti Jákobovi, a dopadlo na Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Ví to všechen lid, Efrajim i obyvatelé Samaří, kteří v pýše a velikášství srdce říkají:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Cihly spadly, budeme stavět z tesaného kamene; sykomory jsou pokáceny, nahradíme je cedry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Ale Hospodin postavil jeho protivníky od Resína vysoko nad něho a popudil jeho nepřátele:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Aramejce od východu a Pelištejce zezadu a budou požírat Izrael plnými ústy. V tom všem se jeho hněv neodvrátí a jeho ruka bude stále vztažená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Ale lid se nenavrátí k tomu, kdo ho bije, Hospodina zástupů hledat nebudou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Pak jednoho dne Hospodin utne Izraeli hlavu i ocas, palmovou ratolest i rákos.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Stařec a vznešený je tou hlavou, prorok vyučující klam je tím ocasem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Vůdcové tohoto lidu se stali svůdci, takže ti, kteří byli vedeni, byli uváděni do zmatku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Proto se Panovník z jeho mládenců nebude radovat a nad jeho sirotky a vdovami se neslituje, neboť každý z nich je bezbožný a zločinec a každá ústa mluví hanebnost. V tom všem se jeho hněv neodvrátí a jeho ruka bude stále vztažená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Vždyť ničemnost vzplála jako oheň, stravuje trní i bodláčí; zapálí lesní houštiny, a ty se vířivě vznesou ve sloupu kouře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Kvůli hněvu Hospodina zástupů se země zatmí; lid bude pokrmem ohně, nikdo nebude mít soucit ani se svým bratrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Uřízl si kus napravo a je hladový, zhltnul něco nalevo a není nasycen; člověk bude požírat maso své vlastní paže --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Manases Efrajima a Efrajim Manasesa, oni společně potáhnou proti Judovi. Ani v tom všem se jeho hněv neodvrátí a jeho ruka bude stále vztažená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Běda těm, kdo vydávají zlá ustanovení, a těm, kdo předpisují trápení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'aby převraceli právní nárok chudých a uchvacovali právo nuzných mého lidu, aby se vdovy staly jejich kořistí a aby oloupili sirotky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Co uděláte v den navštívení a ve zkáze, jež přijde zdaleka? Ke komu utečete pro pomoc a kde zanecháte svou slávu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Nezbyde než se sehnout jako zajatci nebo padnout jako zabití. Ani v tom všem se jeho hněv neodvrátí a jeho ruka bude stále vztažená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Běda Asýrii, metle mého hněvu. Hůl, jež je v jejích rukou, je mé rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Pošlu ji do národa bezbožného a přikáži jí, aby lid, proti němuž plane má zuřivost, zcela vyplenila a vyloupila, aby ho určila k pošlapání jako hlínu na ulicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Ale ona si to tak nepředstavuje a její srdce to tak nezamýšlí, protože v jejím srdci je úmysl vyhladit a vytnout nemálo národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Vždyť si říká: Což nejsou moji velitelé zároveň králi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Což není Kalné jako Karkemíš? Zdalipak není Chamát jako Arpád? Zdalipak není Samaří jako Damašek?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Tak jako má ruka dopadla na království nicotnosti -- a jejich modly byly nad jeruzalémské i nad samařské --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'cožpak nenaložím s Jeruzalémem a s jeho modlářskými zpodobeninami tak, jak jsem naložil se Samařím a s jeho nicotnostmi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'A stane se, když Panovník dokončí celé svoje dílo na hoře Sijón a v Jeruzalémě, že si řekne: navštívím ovoce velikášství srdce asyrského krále a pýchu jeho hrdých očí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'protože si řekl: Vykonal jsem to ⌈svou mocnou rukou⌉ a svou moudrostí, protože jsem rozumný. Odstranil jsem hranice národů a vyplenil jsem jejich poklady, jako silák jsem strhl jejich vládce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Má ruka nalezla majetek národů jako hnízdo a jako se sbírají opuštěná vejce, tak jsem já sebral celou tuto zemi. Nebyl, kdo by máchnul křídlem nebo otevřel zobák či zapištěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Což se sekera vychloubá nad toho, kdo s ní seká? Cožpak se pila vytahuje nad toho, kdo jí řeže? Jako kdyby metla mávala tím, kdo ji zvedá, jako kdyby ⌈ se hůl vyzdvihovala, že není dřevěná.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Proto Panovník, Hospodin zástupů, pošle úbytě na jeho vykrmené a pod jeho slávou zažehne plamen jako plamen ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Světlo Izraele se stane ohněm a jeho Svatý plamenem. V jednom dni zapálí a stráví jeho bodláčí i jeho trní');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'a dočista zničí slávu jeho lesa a ovocného sadu. Bude to, jako když potácejícímu se ubývá sil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Zbylých stromů jeho lesa bude jen tolik, že je sepíše i chlapec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, '⌈I stane se v onen den,⌉ že ostatek Izraele -- ti z domu Jákobova, ⌈kteří vyváznou⌉ -- už dále nebude spoléhat na toho, kdo ho bije, ale opravdu bude spoléhat na Hospodina, Svatého Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, '⌈Ostatek se navrátí,⌉ ostatek Jákoba, k mocnému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Vždyť i kdyby bylo tvého lidu, Izraeli, jako písku v moři, jen ostatek z nich se navrátí. Je rozhodnuto o záhubě, která s sebou přivalí spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Ano, konec, o němž je rozhodnuto, učiní Panovník, Hospodin zástupů, v celé této zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Proto praví Panovník, Hospodin zástupů, toto: Můj lide, který bydlíš na Sijónu, neboj se Asýrie, která tě bije metlou a zvedá na tebe hůl ⌈tak jako⌉ Egypt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Protože ještě velmi krátce a mé rozhořčení pomine a můj hněv bude k jejich zničení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Hospodin zástupů bude proti němu podněcovat bič, jako při porážce Midjánu u skály Oréb, a jeho hůl bude nad mořem a pozdvihne ji tak jako v Egyptě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'I stane se v onen den, že bude odstraněno jeho břemeno ze tvých ramen a jeho jho ze tvé šíje. Jho se bude ⌈lámat pro tučnost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Přišel k Ajátu, prošel Migrónem, v Mikmásu uloží svou zbroj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Prošli průsmykem: Nocleh budeme mít v Gebě. Ráma se třásla, Saulova Gibea utekla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, '⌈Rozezni svůj hlas,⌉ dcero Galímu, pozorně naslouchej, Lajšo, ubohý Anatóte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madména se rozprchla, obyvatelé gebímští hledají bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Ještě ten den se zastaví v Nóbu. Rukou pohrozí hoře dcery sijónské, návrší Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Hle, Panovník, Hospodin zástupů, s děsivou mocí klestí ratolesti: Ty vysoko vzrostlé jsou pokáceny, i ty nejvyšší budou sníženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Proklestí houštinu toho lesa sekerou a Libanon ⌈se vznešeným stromovím ⌉ padne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'I vzejde proutek z pařezu Jišajova a výhonek z jeho kořenů ⌈ponese ovoce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'A spočine na něm Duch Hospodinův: Duch moudrosti a rozumnosti, Duch rady a udatnosti, Duch poznání a bázně před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, '⌈Bude mít zálibu v bázni⌉ před Hospodinem a nebude soudit podle toho, co vidí svýma očima, ani rozhodovat podle toho, co slyší svýma ušima,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'ale bude spravedlivě soudit chudé a podle práva rozhodovat pro pokorné v zemi. Bude bít zemi holí svých úst a duchem svých rtů usmrtí ničemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Spravedlnost bude pásem jeho boků a věrnost pásem jeho beder.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Pak vlk bude pobývat s beránkem a leopard uléhat s kůzletem. Tele, mladý lev a krmný dobytek budou spolu a malý chlapec je povede.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Kráva i medvědice se budou pást, i jejich mláďata budou uléhat spolu. Lev bude požírat píci jako skot.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Kojenec si bude hrát ⌈nad hadí dírou⌉ a odstavené dítě strčí ruku do doupěte zmije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Nikdo nikomu neublíží ani neuškodí na celé mé svaté hoře, protože země bude naplněna poznáním Hospodina, tak jako vody pokrývají moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'I stane se v onen den, že na kořen Jišajův, který bude stát jako korouhev národů, se budou dotazovat pohané. Jeho místo odpočinku bude sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'I stane se v onen den, že Panovník podruhé přiloží svou ruku, aby získal ostatek svého lidu, který zůstal v Asýrii, v Egyptě, v Patrósu, v Kúši, v Élamu, v Šineáru, v Chamátu a na mořských ostrovech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Pozdvihne korouhev k národům a posbírá zapuzené z Izraele, shromáždí rozptýlené z Judy ode čtyř stran země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Efrajimova žárlivost odstoupí a ⌈Judovi nevraživci⌉ budou odňati; Efrajim nebude závidět Judovi a Juda nebude nevražit na Efrajima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'A vletí na rameno Pelištejců na západě, společně oloupí syny východu. K Edómu a Moábu dosáhne jejich moc, synové Amónovi jim budou poddáni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Hospodin zasvětí záliv egyptského moře zkáze a v prudkosti svého dechu zamává rukou nad Řekou, rozbije ji na sedm potoků tak, že se tam bude chodit jen v sandálech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'A bude silnice pro ostatek jeho lidu, který zůstane v Asýrii, tak jako byla pro Izrael v den, kdy vyšel z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'I řekneš v onen den: ⌈Budu ti vzdávat chválu,⌉ Hospodine! Ačkoliv ses na mne hněval, tvůj hněv se odvrátil a potěšil jsi mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Hle, Bůh je má záchrana, budu mu důvěřovat a nebudu se strachovat, vždyť ⌈Hospodin je mou silou i mocí -- stal se mou záchranou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'S jásotem budete čerpat vodu z pramenů té spásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'V onen den řeknete: Vzdávejte chválu Hospodinu, vzývejte jeho jméno, oznamujte mezi národy jeho činy; připomínejte, že jeho jméno je vyvýšené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, '⌈Hrajte chvalozpěvy Hospodinu,⌉ protože jednal vznešeně -- ať je to známo po celé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Jásej a výskej, obyvatelko Sijóna, protože velikým je uprostřed tebe Svatý Izraele!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Prorocký výnos o Babylonu, který viděl Izajáš, syn Amósův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Zvedněte korouhev na lysé hoře, pozvedněte k nim hlas, zamávejte rukou, ať vejdou branami předních mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Vydal jsem příkaz svým posvěceným, k vykonání svého hněvu jsem také povolal své hrdiny, ⌈jásající nad mou velebností.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Slyš! Rachot na horách jakoby mnohého lidu. Slyš! Hukot království -- ⌈shromažďovaných národů:⌉ Hospodin zástupů formuje armádu k boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Přicházejí z daleké země, od konce nebes -- Hospodin se zbraněmi svého rozhořčení -- aby pohubil celou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Naříkejte, protože den Hospodinův je blízko. Přijde jako zkáza od Všemohoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Proto všechny ruce ochabnou a srdce každého člověka se rozplyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Vyděsí se, zachvátí je křeče a bolesti, budou se svíjet jako rodička. Jeden bude užasle hledět na druhého, jejich tváře ⌈ budou jako plamen.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Hle, den Hospodinův přichází, krutý, se zuřivostí a s planoucím hněvem, aby učinil tuto zemi hroznou pustinou a vyhladil z ní hříšníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Neboť hvězdy nebes ani ⌈jejich souhvězdí⌉ se nezatřpytí svým světlem, slunce bude vycházet temné a měsíc nezazáří svým světlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'A navštívím svět za zlo a ničemy za jejich vinu; způsobím, že zmizí pýcha domýšlivců a hrdost tyranů ponížím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Způsobím, že bude člověk vzácnější než ryzí zlato, člověk nad zlato z Ofíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Proto rozbouřím nebesa a rozkymácí se země ze svého místa -- v rozhořčení Hospodina zástupů a ve dni jeho planoucího hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'I stane se, že jako zaplašená gazela nebo jako stádo, když není, kdo by ho shromáždil, tak se každý vrátí ke svému lidu a každý uteče do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Každý, kdo bude nalezen, bude proboden, a každý chycený na útěku padne mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Jejich děti budou rozdrceny před jejich očima, jejich domy budou vypleněny a jejich ženy budou zneuctěny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Podnítím proti nim Médy, kteří si stříbra nebudou cenit a ve zlatě nebudou mít zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Svými luky rozstřílí chlapce a nad plodem lůna nebudou mít slitování -- nad syny se neslituje jejich oko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'A Babylon -- ozdoba království, okrasa vznešenosti Chaldejců -- bude, jako když Bůh vyvrátil Sodomu a Gomoru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Nebude nikdy obydlen, nebude osídlen z generace na generaci; nerozbije tam stan Arab a pastýři se stády se tam neuloží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Budou tam uléhat divoká zvířata a jeho domy budou plné výrů, usídlí se tam pštrosi a budou tam skotačit běsi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'V jeho pevnostech se budou ozývat divocí psi a v rozkošných palácích šakalové. Jeho čas je blízko -- už přichází -- jeho dny nebudou prodlouženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Vždyť Hospodin se slituje nad Jákobem a znovu vyvolí Izrael, dá jim spočinout ⌈v jejich zemi;⌉ připojí se k nim příchozí, připojí se k domu Jákobovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Národy je vezmou a přivedou je na jejich místo. Dům izraelský je přijme v Hospodinově zemi do dědictví za otroky a za služky. Tak se ti, kdo je odvedli do zajetí, stanou jejich zajatci. Budou panovat nad svými utlačovateli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'I stane se v den, kdy ti Hospodin dopřeje odpočinutí od tvého trápení a nepokoje i od tvrdé otročiny, jíž jsi byl zotročen,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'že proneseš o babylonském králi toto pořekadlo: Jak přestal utlačovatel, jak přestal útok!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Hospodin zlomil hůl ničemů, žezlo vládců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'které se zuřivostí bilo národy ranami bez ustání, které panovalo v hněvu nad národy s bezmeznou tyranií.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Celá země odpočinula a má klid; lidé propukli v jásot.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'I cypřiše se nad tebou radují i libanonské cedry: Od té doby, co jsi lehl, nepřichází, kdo by nás kácel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Podsvětí dole se třese na tebe, vstříc tvému příchodu; zburcovalo kvůli tobě nebožtíky -- všechny vůdce země -- ze svých trůnů dalo povstat všem králům národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Ti všichni promluví a řeknou ti: I ty jsi zbaven síly jako my? Stal ses nám podobným!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Do podsvětí je svržena tvá vznešenost, hudba tvých harf; ⌈pod tebou jsou rozprostřeny larvy⌉ a červi jsou tvou přikrývkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Jak jsi spadl z nebes, ⌈třpytivá hvězdo, synu úsvitu?⌉ Byl jsi odseknut k zemi, ⌈ ty, který jsi porážel národy!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'A ty sis řekl ve svém srdci: Vystoupím do nebes, nad hvězdy Boží vyvýším svůj trůn; usednu na Hoře shromáždění na nejzazším severu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Vystoupím na výsosti oblaku, vyrovnám se Nejvyššímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Jenže jsi svržen do podsvětí, do největších hlubin jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Ti, kteří tě uvidí, na tebe budou zírat a pozorně tě sledovat: Což to není ten muž, jenž znepokojoval zemi a otřásal královstvími?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Obracel svět v pustinu a jeho města bořil, své vězně nepropouštěl domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Všichni králové ⌈národů, všichni⌉ leží ve slávě, každý ve vlastní hrobce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Ale tebe ⌈pohodili mimo tvůj hrob⌉ jako ohavný výhonek, zahalený pobitými, probodenými mečem, těmi, kdo sestupují ke kamenům jámy -- jako rozšlapanou mršinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nebudeš s nimi mít jeden hrob, protože jsi ničil svou zemi a zabíjel svůj lid. Potomstvo zločinců nebude zmiňováno navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Připravte místo porážení pro jeho syny kvůli vině jejich otců, ať nevstanou a nedostanou do vlastnictví zemi a ne naplní povrch světa městy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Povstanu proti nim, je výrok Hospodina zástupů, a vyhladím ⌈jméno Babylona⌉ i jeho ostatek, nástupce i následníka, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'A učiním ho vlastnictvím ježků a ⌈vodní mokřinou;⌉ a zametu ho koštětem vyhlazení, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Hospodin zástupů přísahal: Jistěže tak, jak jsem si usmyslil, ⌈se stane, a jak jsem se rozhodl,⌉ tak se to naplní:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Rozdrtím Ašúra ve své zemi a na svých horách ho pošlapu. Stáhnu z nich jeho jho a odstraním jeho břemeno z jejich ramen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'To je plán, který je naplánován pro celou zemi, a to je paže, která je vztažena proti všem národům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Vždyť to naplánoval Hospodin zástupů, kdo to zruší? A jeho paže je vztažena, kdo ji odvrátí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'V roce, kdy zemřel král Achaz, přišel tento prorocký výnos:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Neraduj se, celá Pelišteo, že je zlomena hůl, která tě bije: Neboť z hadího kořenu vyjde zmije a jejím plodem bude létající ohnivý had.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, '⌈Prvorození nuzných⌉ se budou pást a chudí budou uléhat v bezpečí. Ale tvůj kořen nechám zemřít hladem a tvůj ostatek zabiji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Naříkej, bráno, křič o pomoc, město! Propadni malomyslnosti, celá Pelišteo, protože od severu přichází kouř a není, kdo by zůstal stranou svého shromaždiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Co odpovědí poslům toho národa? Že Hospodin založil Sijón a v něm budou mít útočiště nuzní jeho lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Prorocký výnos o Moábu: Ano, přes noc je zničen ⌈Ar Moábský -- je umlčen.⌉ Ano, přes noc je zničen Kír Moábský -- je umlčen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Vystoupil do chrámu, ⌈ do Díbónu na svá návrší, aby plakal.⌉ Nad Nebó a nad Médebou bude Moáb naříkat; na každé hlavě lysina, každá brada je ostříhaná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Na jeho ulicích se přepásali pytlovinou; na střechách a na náměstích všechno naříká, rozplývá se v pláči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Křičí Chešbón i Eleále, až do Jahasu je slyšet jejich hlas; proto ozbrojenci Moábu křičí, jeho duše se v něm chvěje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mé srdce naříká nad Moábem; jeho uprchlíci jsou až po Sóar a Eglat–šelišiji. Po luchítském svahu vystupují s pláčem; na cestě do Chóronajimu propukají v úpěnlivý křik nad zkázou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Vždyť vody nimrímské jsou zpustošené; vždyť uschla tráva, zašlo rostlinstvo, není zeleň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Proto přebytek, který získali a uložili, odnášejí přes Topolový potok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Vždyť celým moábským územím proběhl úpěnlivý křik; jeho nářek došel až do Eglajimu, jeho nářek došel až do Beer–élímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Vždyť vody Dímónu jsou plné krve a připravím pro Dímón další rány: Lva na Moábce, kteří vyváznou, i na ostatek v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Pošlete beránka vládci země ⌈ze Sély v pustině⌉ na horu dcery sijónské.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Jako poletující pták vyhnaný z hnízda, tak budou dcery moábské u arnónských brodů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Dejte radu, udělejte rozhodnutí. Připrav v pravé poledne svůj stín jako noc. Ukryj zapuzené, uprchlého neodhaluj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, '⌈Moji zapuzení ať pobývají u tebe, Moábe.⌉ Buď jim úkrytem před ničitelem. Vždyť přestane útlak, pomine zkáza, utlačovatelé vymizí ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'A milosrdenstvím bude upevněn trůn a usedne na něj ve stanu Davidově v pravdě ten, kdo bude soudit podle práva a vyhledávat je a bude zběhlý ve spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Slyšeli jsme o Moábově pýše, je velice pyšný. O jeho vypínavosti, povýšenosti i zpupnosti -- nesprávné jsou jeho prázdné řeči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Proto bude Moáb nad sebou naříkat, celý Moáb bude naříkat. Pro kírcharesetské hrozinkové koláče budete vzdychat -- zcela ubití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Neboť zvadla chešbónská pole i réva sibemská. Páni národů otloukli to ušlechtilé révoví, které dosahovalo až k Jaezeru, které se vinulo pustinou. Jeho výhonky se rozpínaly, táhly se až za moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Proto budu plakat pláčem Jaezeru nad sibemskou révou, zavlažím tě svými slzami, Chešbóne a Eleále, protože jásot nad tvým letním ovocem i nad tvou sklizní opadl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'A bude vzata radost i jásání z té úrodné zahrady -- na vinicích se nebude výskat a hlaholit; ten, kdo lisuje v lisech, nebude šlapat víno, jásot lisujících ukončím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Proto jako lyra budou vzlykat mé útroby nad Moábem a mé nitro nad Kir–cheresem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'I stane se, když ⌈se Moáb ukáže a bude se namáhat na návrší,⌉ že vejde do své svatyně, aby se modlil, ale nic nezmůže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'To je slovo, které Hospodin k Moábovi promluvil již tenkrát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Ale teď Hospodin řekl: V průběhu tří let, jako jsou léta najatého dělníka, zlehčím slávu Moába ⌈s celým⌉ jeho velkým davem a ostatek bude velmi skrovný, bezvýznamný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Prorocký výnos o Damašku: Hle, Damašek přestane být městem a stane se hromadou sutin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Města Aróeru budou opuštěna, budou patřit stádům -- ta budou uléhat a nebude, kdo by je vyplašil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Zmizí pevnost z Efrajima i království z Damašku. S ostatkem Aramejců to dopadne jako se slávou synů Izraele, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'I stane se v onen den, že Jákobova sláva zeslábne a jeho vykrmené tělo zhubne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'A dopadne, jako když žnec sklízí nepožaté obilí a jeho paže kosí klasy -- bude to jako sbírání klasů v údolí Refájců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Zůstanou na něm paběrky, jako po otlučení olivy: Dvě, tři olivky na samém vrcholu, čtyři, pět na jejích plodících větvích, je výrok Hospodina, Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'V onen den bude člověk vzhlížet ke svému Tvůrci a jeho oči budou s úctou hledět ke Svatému Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Nebude vzhlížet k oltářům, dílu svých rukou; nebude s úctou hledět na to, co zhotovily jeho prsty, na ašéry a kadidlové oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'V ten den budou jeho bezpečná města ⌈jako opuštěná houština nebo pahorek, který opustili nepřátelé ⌉ před syny Izraele. Země bude zcela opuštěná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Ano, zapomněla jsi na Boha své záchrany a na skálu svého bezpečí nepamatuješ. Proto, ačkoliv vysazuješ nejlíbeznější sadbu a zaséváš cizokrajnou révu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'v den své ⌈setby ji oplotíš a⌉ ráno ⌈tvé semeno bude⌉ vzkvétat, avšak sklizeň v den tvé nemoci a nevyléčitelné bolesti uletí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Běda! Rachot mnohých národů! Budou burácet jako burácení moří. Hukot lidí! Budou hučet jako hukot mocných vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Lidé budou hučet jako hukot mnohých vod. Ale okřikne je a utečou daleko a budou se hnát před větrem jako plevy po horách a jako prašný vír před vichřicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Navečer hle, hrozba! Dříve než přijde ráno, už nejsou. To je podíl těch, kdo nás plení, a los těch, kdo na nás kořistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Běda zemi okřídlených cvrčků, která je za řekami Kúše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'která posílá posly po moři, i v plavidlech z papyru po hladině vod. Jděte, rychlí poslové, k národu ⌈vysokých postav a hladké pleti,⌉ k lidu obávanému ⌈široko daleko,⌉ národu mocnému a pošlapávajícímu, jehož zemi rozdělují řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Všichni obyvatelé světa a vy, kteří bydlíte na zemi, když pozdvihnou na horách korouhev, hleďte, a když budou troubit na beraní roh, slyšte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Neboť toto mi řekl Hospodin: Pokojně budu hledět ze svého sídla jako třpytivý žár nad světlem slunce, jako oblak rosy v žáru žně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Protože ještě před sklizní, když odkvete květ a trpký hrozen zraje a stane se zralým ovocem, se odříznou jalové výhonky vinařskými noži a úponky se odlomí a odstraní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Budou zanechány společně dravému ptactvu z hor a zemské zvěři; stráví na tom léto dravé ptactvo a všechna zemská zvěř na tom přezimuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'V té době bude přinesen dar úcty Hospodinu zástupů od lidu vysokých postav a hladké pleti, od lidu obávaného široko daleko, národa mocného a pošlapávajícího, jehož zemi rozdělují řeky, k místu přebývání jména Hospodina zástupů, hoře Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Prorocký výnos o Egyptu: Hle, Hospodin jede na rychlém oblaku a přichází do Egypta. Egyptské nicotnosti se před ním roztřesou a srdce Egypta se v něm rozplyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'A popudím Egypťany proti Egypťanům a budou bojovat jeden proti druhému a každý se svým bližním, město proti městu a království proti království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Duch Egypta v něm bude rozrušen a jeho plán zmatu. Budou se dotazovat nicotností, zaklínačů mrtvých, těch, kdo vyvolávají duchy zemřelých, a věštců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Pak vydám Egypťany do moci tvrdého pána a surový král jim bude vládnout, je výrok Panovníka, Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Ztratí se voda z moře a řeka vyprahne a vyschne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Řeky zasmrádnou, ramena egyptské řeky zeslábnou a vyschnou; třtina a rákos povadnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Lučiny u Nilu, u ústí Nilu a všechno osení v okolí Nilu uschne, bude odváto a nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Rybáři se budou rmoutit a truchlit budou všichni, kdo házejí do Nilu udice; ti, kdo na vodní hladině rozprostírají sítě, budou chřadnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Zahanbeni budou ti, kdo pracují se lnem, česačky a tkalci ⌈bílého plátna.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, '⌈Opory země budou rozdrceny,⌉ všem pracujícím za mzdu ⌈ bude smutno v duši.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Knížata Sóanu jsou jen hlupáci, rada moudrých faraonových rádců je hloupá. Jak můžete říkat faraonovi: Já jsem synem moudrých, synem ⌈dávných králů?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Kdepak jsou tvoji mudrci? Jen ať ti oznámí a zjistí, jak rozhodl Hospodin zástupů o Egyptu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Sóanská knížata jednala hloupě, knížata memfidská jsou podvedena -- vůdcové jeho kmenů Egypt svedli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Hospodin v jeho středu namíchal ducha závrati, aby svedli Egypt v každém jeho díle, jako opilec vrávorá ve svých zvratcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Egyptu se nepovede žádné dílo, ať ho udělá hlava či ocas, palmová ratolest nebo rákos.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'V onen den bude Egypt jako žena: Bude se třást a strachovat před máváním ruky Hospodina zástupů, který proti němu bude mávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Judská země se stane Egyptu postrachem: Každý, kdo si ji připomene, se bude strachovat před plánem Hospodina zástupů, který proti němu připravuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'V onen den bude v egyptské zemi pět měst mluvících kenaanskou řečí a přísahajících věrnost Hospodinu zástupů; jednomu se bude říkat Město ruin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'V onen den bude Hospodinův oltář uprostřed egyptské země a u její hranice Hospodinův posvátný sloup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'A bude to na znamení a na svědectví Hospodina zástupů v zemi egyptské, protože budou křičet k Hospodinu před utiskovateli, a pošle jim zachránce a obhájce, který je vysvobodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Hospodin se dá Egyptu poznat a Egypťané v onen den poznají Hospodina; a budou mu sloužit obětí a přídavnou obětí a učiní Hospodinu slib a splní ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Hospodin Egypt postihne -- postihne a pak uzdraví. I navrátí se k Hospodinu, a on se dá pohnout jejich prosbami a uzdraví je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'V onen den bude silnice z Egypta do Asýrie; Asyřané ⌈budou chodit do Egypta a Egypťané do Asýrie a budou sloužit Hospodinu Egypt s Asýrií.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Onoho dne bude Izrael jako třetí s Egyptem a s Asýrií -- požehnání uprostřed země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'jíž Hospodin zástupů požehnal slovy: Požehnaný můj lid Egypt, dílo mých rukou Asýrie a mé dědictví Izrael!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'V roce, kdy vojevůdce vyslaný asyrským králem Sargónem přitáhl k Ašdódu, bojoval proti Ašdódu a dobyl ho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'v onen čas promluvil Hospodin skrze Izajáše, syna Amósova: Jdi, odvaž si pytlovinu ze svých beder a sandály zuj ze svých nohou. I učinil tak a chodil nahý a bosý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'I řekl Hospodin: Tak jako můj otrok Izajáš chodil tři roky nahý a bosý -- jako znamení a div pro Egypt a pro Kúš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'tak bude asyrský král hnát egyptské zajatce a kúšské vysídlence, chlapce i starce, nahé a bosé, s obnaženými zadky, k hanbě Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Zděsí se a budou zahanbeni kvůli Kúši, své naději, a kvůli Egyptu, své slávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Obyvatelé toho pobřeží v onen den řeknou: Hle, toto je naše naděje, ke které jsme se utíkali pro pomoc, abychom byli vysvobozeni od asyrského krále! Jak se potom zachráníme my?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Prorocký výnos o pustině u moře: Jako vichřice, které procházejí Negebem, tak to přichází z pustiny, z obávané země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Bylo mi oznámeno tvrdé zjevení: Věrolomník jedná věrolomně a ničitel ničí. Vytáhni, Élame, oblehni, Méde: Zastavím veškeré to vzdychání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Proto jsou má bedra naplněna úzkostí, zachvátily mne křeče jako křeče rodičky; ⌈jsem sklíčen tak, že neslyším, jsem vyděšen tak, že nevidím.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, '⌈Mé srdce se potácí,⌉ hrůza mne ohromila; ⌈soumrak, který jsem si přál,⌉ se mi změnil ve zděšení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, '⌈Připravit stůl, prostřít ubrus, jíst a pít ...⌉ Vstaňte, velitelé, mažte štíty!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Vždyť toto mi řekl Panovník: Jdi, postav hlídku. Ať oznámí, co uvidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Až uvidí vozy s páry koní, vozy s osly a vozy s velbloudy, ať dává velký pozor, velký pozor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'I zvolal ⌈ jako lev:⌉ Na hlídce, Panovníku, stojím ve dne ustavičně, a na své stráži zůstávám stát celé noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'A hle, tu přichází: Vůz, muž a pár koní. A promluvil: Padl, padl Babylon a všechny tesané obrazy jeho bohů roztřískal o zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, '⌈Můj vymlácený lide a synu mého humna, co jsem slyšel od Hospodina zástupů, Boha Izraele, to jsem vám oznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Prorocký výnos o Dúmě: Volá ke mně ze Seíru: Strážce, co zbývá z noci? Strážce, co zbývá z noci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Strážce řekl: Přichází ráno a také noc; jestliže se budete tázat, tažte se, navraťte se, přijďte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Prorocký výnos proti Arábii: Budete nocovat v arabské houštině, karavany Dedánců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Přineste vodu vstříc žíznivému, obyvatelé země Témy, vyjděte s chlebem vstříc utečenci!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Vždyť uprchli před meči! Před vytaseným mečem, před napnutým lukem a před útrapami války.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Neboť toto mi řekl Panovník: Během roku, jako jsou léta najatého dělníka, pomine veškerá sláva Kédaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'A zbylý počet luků hrdinů Kédaru bude malý, neboť Hospodin, Bůh Izraele, to řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Prorocký výnos o Údolí vidění: Copak je s tebou, že jsi celé vystoupilo na střechy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'ty halasné město plné hukotu, město rozjařené? Tvoji pobití nejsou pobití mečem, nezemřeli v boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Všichni tvoji vůdcové spolu uprchli, byli spoutáni bez výstřelu z luku; všichni tvoji utečenci, již byli nalezeni, byli rovněž spoutáni, ačkoliv utekli daleko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Proto jsem řekl: Nedívejte se na mě, budu hořce plakat; nesnažte se mě potěšit nad zkázou dcery mého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Neboť den porážky, pošlapání a zmatku má Panovník, Hospodin zástupů, ⌈v Údolí vidění; den stržení zdi a volání o pomoc k Hoře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Élam pozdvihl toulec -- ve vozech lidé a jezdci; Kír obnažil štít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'A stalo se, že tvá nejlepší údolí jsou plná vozů a jezdci se dočista usadili ve tvé bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Bylo odkryto Judovo zaštítění; v onen den jsi pohleděl ke zbroji Domu lesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'A viděli jste průlomy ve zdi Davidova města, že je jich mnoho, a shromažďovali jste vodu Dolního rybníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Spočetli jste jeruzalémské domy a strhli jste domy, abyste opevnili hradby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Mezi dvěma hradbami jste udělali nádrž na vodu Starého rybníka, aniž jste se ohlíželi na jeho Tvůrce, a na toho, který ho již dávno utvořil, jste nehleděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'A v onen den povolal Panovník, Hospodin zástupů, k pláči a ke kvílení, k lysině a k přepásání pytlovinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'A hle! Veselí a radost, zabíjení skotu a porážení ovcí, požírání masa a pití vína: Jezme a pijme, neboť zítra zemřeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Hospodin zástupů zjevil mému sluchu: Tato vina vám nebude vymazána, dokud nezemřete, praví Panovník, Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Toto praví Panovník, Hospodin zástupů: Jdi, zajdi k tomu správci, k Šebnovi, který ⌈ je ustanoven nad domem,⌉ a řekni mu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '⌈Co ty tu pohledáváš ⌉ a ⌈ za koho se tu máš,⌉ že sis tu vytesal hrob? Tesáš nahoře svůj hrob, ve skále si vyměřuješ příbytek?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Hle, Hospodin tě odvrhne ⌈daleko, člověče,⌉ rázně tě popadne,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'důkladně tě zamotá do klubka jako míč a hodí tě do ⌈rozlehlé země;⌉ tam zemřeš a tam skončí tvé slavné vozy, pohano domu svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Srazím tě ze tvého postavení a ze tvého stanoviště tě strhnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'I stane se v onen den, že povolám svého otroka Eljakíma, syna Chilkijášova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'a obléknu mu tvou suknici, tvou šerpou ho upevním a tvou vladařskou moc vložím do jeho rukou. I bude otcem obyvatelům Jeruzaléma a domu judskému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Na jeho rameno položím klíč domu Davidova. Když on otevře, nikdo nezavře, a když zavře, nikdo neotevře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Zarazím jej jako kolík na spolehlivém místě a stane se slavným trůnem domu svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'A zavěsí na něj všechnu slávu domu jeho otce -- výhonky i odnože -- všechny malé nádoby, od talířků až po všechny džbány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'V onen den, je výrok Hospodina zástupů, se pohne ten kolík zaražený na spolehlivém místě; bude odseknut, spadne a břemeno, které na něm bylo, bude zničeno, neboť Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Prorocký výnos o Týru: Naříkejte, lodě taršíšské, protože ⌈je zničen: Bez domu, bez přístupu. Bylo mu to ukázáno⌉ z kitejské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Umlkněte, obyvatelé pobřeží! ⌈Naplňovali tě sidónští obchodníci⌉ brázdící moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Po vodách mnohých k tobě přicházelo zrno Šíchoru, žeň Nilu. Stal ses ⌈ziskem z obchodování ⌉ národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Styď se, Sidóne, vždyť moře řeklo, mořská pevnost řekla: Nesvíjela jsem se bolestí a nerodila jsem, nevychovávala jsem mládence ani jsem nepěstovala panny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Jakmile se to doslechnou v Egyptě, ⌈budou se nad zprávou o Týru svíjet bolestí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Přeplavte se do Taršíše, naříkejte, obyvatelé pobřeží!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Toto je to vaše rozjařené město, jehož starobylost je od dávných časů, jehož nohy je odvedly daleko, aby tam pobývalo jako cizinec?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kdo to rozhodl proti Týru -- proti tomu, jenž udílí koruny, jehož obchodníci jsou knížata a jehož kramáři jsou vážení země?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Hospodin zástupů to rozhodl, aby znesvětil pýchu všech slavných, aby zlehčil všechny vážené země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, '⌈Projdi svou zemí jako Nil,⌉ taršíšská dcero, už není žádná loděnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Vztáhl svou ruku na moře a rozbouřil království; Hospodin vydal příkaz proti Kenaanu, aby byly zničeny jeho pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'A řekl: Nebudeš už jásat, ty utištěná panno, dcero sidónská. Vstaň, přeplav se ke Kitejcům! Ani tam nebudeš mít odpočinek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Hle -- země chaldejská -- její lid už není. Asýrie ji určila pro divoká zvířata. Postavili své obléhací věže, strhli její paláce, proměnili ji v ruinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Naříkejte, taršíšské lodě, protože vaše pevnost byla zničena!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'I stane se v onen den, že Týr bude zapomenut na sedmdesát let, jako jsou dny života jednoho krále. Po sedmdesáti letech to s Týrem bude jako v písničce o nevěstce:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Vezmi lyru, obcházej město, nevěstko zapomenutá. Hraj dobře, ⌈zpívej mnoho⌉ písní, aby ses připomenula.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Stane se po sedmdesáti letech, že Hospodin navštíví Týr. A ten se navrátí ke své nevěstčí mzdě a bude smilnit se všemi královstvími světa na povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'A jeho zisk, jeho nevěstčí mzda, bude svatý Hospodinu; nebude uskladňován ani uschováván, nýbrž jeho zisk bude pro ty, kdo zůstávají před Hospodinem, na jídlo k nasycení a na ⌈vybraný oděv.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Hle, Hospodin nechává zemi zpustnout a pustoší ji, rozvrátí její povrch a rozptýlí její obyvatele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Pak na tom bude lid stejně jako kněz, otrok stejně jako jeho pán, služka stejně jako její paní, kupující stejně jako prodávající, věřitel stejně jako dlužník, lichvář stejně jako ten, kdo je u něj zadlužen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Země bude zcela zpustlá a naprosto vypleněna, protože Hospodin promluvil toto slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Usychá, vadne země, chřadne, vadne svět, ⌈chřadnou velikáni lidu země⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'a země je znesvěcena pod svými obyvateli. Vždyť přestoupili zákony, změnili ustanovení, porušili věčnou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Proto sžírá zemi prokletí a její obyvatelé nesou vinu. Proto ubude obyvatel země a lidí zůstane maličko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Bude usychat mladé víno, bude chřadnout réva, budou vzdychat všichni radostného srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Ustane veselí tamburín, přestane hukot rozjařených, ustane veselí lyry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Nebudou za zpěvu pít víno, pivo pijanům zhořkne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Zdrceno bude město marnosti, každý dům bude zavřen, ⌈takže bude nemožné vejít.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Na ulicích bude slyšet žalostný křik pro víno, veškerá radost potemní, veselí se vystěhuje ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Ve městě zůstane hrozná spoušť a brána bude rozbita v troskách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Neboť tak bude uprostřed země, mezi národy, jako po otlučení olivy, jako paběrky, když pominulo vinobraní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ti pozvednou hlas a budou výskat, v Hospodinově vznešenosti budou jásat od západu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Proto na východě ctěte Hospodina, na mořském pobřeží jméno Hospodina, Boha Izraele!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Od konce země jsme slyšeli zpěvy: Sláva Spravedlivému! Řekl jsem: ⌈Jsem zničen, jsem zničen, běda mi! Zrádci jednají zrádně. Zrádci jednají naprosto zrádně!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, '⌈Strach, propast a past na tebe,⌉ obyvateli země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'I stane se, že kdo uteče ⌈před tou děsivou vřavou,⌉ spadne do propasti, a kdo vyleze z propasti, chytne se do pasti; protože se otevřely průduchy z výšin a otřásly se základy země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Země se zcela rozbila, země se úplně rozdělila, země se velice rozkolísala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Země se bude velmi potácet, jako opilec, bude se klátit jako strážní budka; těžce na ni dolehne její přestoupení. Padne a již nepovstane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'I stane se v onen den, že Hospodin na výšině navštíví armádu výšiny a na zemi krále země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'A budou sebráni do shromáždění vězňů do jámy a budou zavřeni ve vězení; po mnohých dnech budou navštíveni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Zastydí se měsíc a bude zahanbeno slunce, když bude Hospodin zástupů kralovat na hoře Sijón a v Jeruzalémě, a před jeho starci ⌈ bude jeho sláva.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Hospodine, ty jsi můj Bůh! Budu tě vyvyšovat a vzdávat chválu tvému jménu, neboť jsi učinil podivuhodnou věc, plány odedávna připravené, jisté a pravé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Neboť jsi proměnil město v hromadu kamení, opevněné město v ruinu; pevnost cizinců zmizela z města, nebude vybudována navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Proto tě bude ctít mocný lid, budou se tě bát města násilnických národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Protože jsi byl pevností pro chudého, pevností pro nuzného v jeho tísni; útočištěm před přívalem, stínem před horkem, neboť hněv násilníků je jako příval proti zdi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, '⌈Jako horko ve vyprahlém kraji pokoříš⌉ hukot cizinců, jako horko ve stínu oblaku je potlačen zpěv násilníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Hospodin zástupů uspořádá pro všechny národy na této hoře hostinu z tučných jídel, hostinu z ⌈vyzrálých vín;⌉ z jídel tučných, dužnatých, a z přečištěných ⌈vyzrálých vín.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'A pohltí na této hoře zahalení, které zahaluje všechny lidi, a přikrývku, která přikrývá všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Navždy pohltí smrt a Panovník Hospodin setře slzy z každé tváře; potupu svého lidu odstraní na celé zemi, neboť Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'A řeknou v onen den: Hle, toto je náš Bůh, očekávali jsme na něho a zachránil nás. Toto je Hospodin, na něhož jsme očekávali, jásejme a radujme se v jeho záchraně!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Neboť Hospodinova ruka spočine na této hoře, ale Moáb bude na svém místě zadupán, jako ⌈se zadupává sláma do hnojiště.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'A bude uprostřed něj rozhazovat rukama, tak jako jimi rozhazuje plavec při plavání. Poníží jeho hrdost spolu s dovednostmi jeho rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Nepřístupné opevnění tvých hradeb sehnul, snížil a srazil k zemi, až do prachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'V onen den se bude v judské zemi zpívat tato píseň: Máme pevné město, Bůh připravil záchranu, hradby a val.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Otevřete brány, ať vejde spravedlivý národ, který zachovává věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, '⌈Mysl upevněnou v tobě ⌉ budeš střežit ⌈dokonalým pokojem,⌉ protože ⌈tobě důvěřuje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Důvěřujte Hospodinu až navěky, protože v Hospodinu, v Hospodinu je skála věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Vždyť sehnul obyvatele výšiny -- město, které je vyvýšené, sníží, sníží je až k zemi, srazí je až do prachu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'pošlape je noha, nohy chudého, kroky chudáků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Cestou spravedlivého je poctivost; ⌈ ó, Přímý, ty budeš urovnávat stezku spravedlivého!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Také na cestě tvých soudů, Hospodine, očekáváme na tebe; po tvém jménu a po tvém připomenutí touží naše duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Toužím po tobě v noci celou svou duší, hledám tě ve svém nitru celým svým duchem. Vždyť když se dějí tvé soudy na zemi, obyvatelé světa se učí spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Když se udílí milost ničemovi, nenaučí se spravedlnosti; v zemi správných způsobů bude páchat bezpráví a na Hospodinovu důstojnost nebude hledět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Hospodine, tvá ruka je pozdvižena, ale oni to nevidí; uvidí a budou zahanbeni pro ⌈horlivost tvého lidu,⌉ ⌈nadto tvé protivníky stráví oheň.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Hospodine, ty nám ⌈uchystáš pokoj;⌉ ⌈vždyť i všechna naše díla jsi udělal za nás.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Hospodine, Bože náš, panovali nad námi páni jiní než ty; jen tvé jméno budeme připomínat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Mrtví neožijí, nebožtíci nevstanou; protože jsi je navštívil a vyhladil, ba zničil jsi každou památku na ně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, '⌈Rozmnožil jsi národ,⌉ Hospodine, rozmnožil jsi národ a oslavil ses, daleko jsi vzdálil všechny hranice země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Hospodine, v tísni tě hledali, ⌈šeptali naučenou modlitbu⌉ ⌈kvůli tvému káznění.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Jako těhotná, když se přibližuje ku porodu, se svíjí a křičí v bolestech, takoví jsme byli před tebou, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Otěhotněli jsme, svíjeli jsme se bolestí a jako bychom porodili vítr; nezpůsobíme záchranu zemi, ani se nezrodí obyvatelé světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Tvoji mrtví ožijí, moje mrtvoly vstanou. Probuďte se a jásejte, obyvatelé prachu, protože tvoje rosa je rosou světla úsvitu a země vyvrhne nebožtíky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Jdi, lide můj, vejdi do svých pokojů a zavři za sebou dveře; ukryj se na malou chvíli, dokud nepřejde rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Neboť hle, Hospodin vychází ze svého místa, aby navštívil obyvatele země za jejich vinu. Země odhalí svou prolitou krev a nebude již zakrývat své zavražděné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'V onen den Hospodin svým tvrdým, velikým a mocným mečem navštíví livjátána, hada mrštného, a livjátána, hada zkrouceného, a zabije draka, který je v moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'V onen den hle: Překrásná vinice, opěvujte ji!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Já, Hospodin, jsem její strážce, co chvíli ji budu zavlažovat; aby ⌈jí někdo neublížil,⌉ budu ji střežit v noci i ve dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Zloba ve mně není. ⌈ Ať mi někdo dá⌉ k boji trní a bodláčí. Vkročím do toho a společně to zapálím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Nebo ať se chopí mé záštity a dojedná se mnou pokoj. Ať se mnou dojedná pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Přicházejí dny, kdy se zakoření Jákob, rozpučí a rozkvete Izrael a zaplní povrch světa ovocem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Zdalipak ho pobil tak, jak byl zcela pobit ten, kdo bil jeho? Zdalipak byl zavražděn tak, ⌈jak byli zavražděni ti, které zavraždil?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Jejím zaplašením a vyhoštěním s ní povede při. Odklidil ji svým ostrým větrem v den ⌈východního větru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Protože jen takto bude usmířena Jákobova vina a to bude celé ovoce odstranění jeho hříchu, když všechny oltářní kameny roztříští jako vápenné kameny, takže neobstojí ašéry ani kadidlové oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Ale opevněné město bude osamělé -- sídliště vyklizené a zanechané jako pustina. Bude se tam pást tele, bude tam uléhat a spase jeho větve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Když uschnou jeho ratolesti, budou rozlámány. Přijdou ženy a spálí je. Vždyť ten lid nemá rozum. Proto se nad ním jeho Tvůrce neslituje a ⌈ten, který ho utvořil,⌉ se nesmiluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'I stane se v onen den, že Hospodin bude mlátit od proudu Řeky až k egyptskému potoku, a vy, synové Izraele, budete sbíráni jeden po druhém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'I stane se v onen den, že se bude troubit na veliký beraní roh a přijdou hynoucí v asyrské zemi a zapuzení do egyptské země a budou se klanět Hospodinu na svaté hoře v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Běda vznešené koruně Efrajimových opilců, vadnoucímu květu jeho skvostné ozdoby, který je ⌈na vrchu úrodného údolí, koruně zmožených⌉ vínem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Hle, Panovník má cosi silného a ohromného jako příval krupobití, jako smršť zhouby; ⌈ cosi jako příval mocných rozvodněných vod mocně spustí na zem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Vznešená koruna Efrajimových opilců bude nohama pošlapána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'A vadnoucí květ slávy její nádhery, který je na vrchu úrodného údolí, bude jako raný fík před létem -- kdo ho uvidí, zhltne ho, jen co ho uchopí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'V onen den bude Hospodin zástupů slavnou korunou a nádherným věncem ostatku svého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'A duchem práva tomu, jenž zasedá na soudu, a udatností těm, kdo ⌈odvracejí boj v bráně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Ale i tito vrávorají při víně a klopýtají při pivu: Kněz i prorok vrávorají při pivu, jsou zmateni z vína, klopýtají z piva. Chybují ve vidění, ⌈jsou vratkého úsudku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Neboť všechny stoly jsou plné ⌈hnusných zvratků,⌉ není čistého místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Koho bude vyučovat poznání a ⌈koho naučí rozumět zprávě?⌉ Odstavené od mléka? Vzaté od prsu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Vždyť říká: ⌈Pokyn za pokynem, pokyn za pokynem, míru k míře, míru k míře, trochu sem, trochu tam.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Ano, žvatlavou řečí a cizím jazykem bude mluvit k tomuto lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Ten, který jim řekl: Toto je místo odpočinku, dejte odpočinek vyčerpanému, toto je místo odpočinutí; ale nechtěli poslechnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'I bude pro ně Hospodinovo slovo ⌈pokyn na pokyn, pokyn na pokyn, míru k míře, míru k míře, trochu sem, trochu tam,⌉ a tak půjdou, upadnou dozadu, polámou se, budou chyceni a zajati.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Proto slyšte Hospodinovo slovo, posměvači vládnoucí tomuto lidu, který je v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Protože jste řekli: Uzavřeli jsme smlouvu se smrtí a s podsvětím jsme udělali ujednání; i když bude procházet valící se bič, nepřijde na nás, protože jsme učinili lež svým útočištěm a v klamu jsme se ukryli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Proto toto praví Panovník Hospodin: Hle, já kladu jako základ na Sijónu kámen, vyzkoušený kámen, drahocenný, úhelný základ, pevně založený. Kdo věří, nebude spěchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Učiním právo mírou a spravedlnost závažím. Krupobití smete lživé útočiště a úkryt zaplaví vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'A bude zrušena vaše smlouva se smrtí a vaše ujednání s podsvětím neobstojí. Když bude procházet valící se bič, zůstanete mu k pošlapání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Kdykoli bude procházet, zmocní se vás: vždyť bude procházet ráno co ráno, ve dne i v noci. Bude to čirá hrůza, jen porozumět té zprávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Protože lehátko bude krátké k protáhnutí a přikrývka bude úzká na zabalení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Neboť Hospodin povstane jako na hoře Perasímu, rozzuří se jako v Gibeónském údolí, aby vykonal své dílo, sobě cizí dílo, a aby vykonal svou službu, pro něj neobvyklou službu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Nuže nebuďte drzí, aby nebyla zesílena vaše pouta, protože od Panovníka Hospodina zástupů jsem slyšel o konci, o němž je rozhodnuto pro celou tuto zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Naslouchejte a slyšte můj hlas, pozorně naslouchejte a poslechněte mou řeč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Což bude oráč celý den orat, aby zasel? Bude neustále kypřit a vláčet svou půdu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Když vyrovnal její povrch, což nerozhází černuchu a nerozsype kmín, nevloží pšenici, proso i ječmen ⌈na jejich místo⌉ a špaldu na své meze?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Jeho Bůh jej vychovává ke správným způsobům a vyučuje ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Vždyť černucha se nemlátí smykem a po kmínu se nejezdí koly vozu, ale černucha se vyklepává metlou a kmín holí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Zrno se musí rozdrtit, vždyť ho jistě nebude mlátit stále, bude ho rozrušovat koly svého vozu a koňmi, ale nerozdrtí ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'To také pochází od Hospodina zástupů: Je podivuhodný v radě a velký v obezřetnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ach Aríeli, Aríeli, město, kde tábořil David! Přidávejte rok k roku, ať se opakuje koloběh svátků!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Způsobím Aríelovi soužení a nastane smutek a žal, a bude pro mě jako obětní ohniště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Utábořím se dokola proti tobě, oblehnu tě s náspy a postavím proti tobě obléhací pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Budeš sníženo, ze země budeš mluvit a v prachu se bude dusit tvá řeč. Jako duch zemřelého bude ze země vycházet tvůj hlas a z prachu bude sípat tvá řeč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'A dav tvých nepřátel bude jako jemný prach a množství násilníků jako plevy hnané větrem. Stane se to v okamžiku, náhle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Od Hospodina zástupů přijde tvé navštívení s hromobitím, se zemětřesením a velikou vřavou, s vichřicí a smrští a s plamenem stravujícího ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'A množství všech národů válčících proti Aríelovi -- všech válčících proti němu a jeho pevnosti a sužujících ho -- bude jako sen, jako noční vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Bude to, jako když hladový má sen, že jí; pak se probudí a ⌈ je stále hladový.⌉ Nebo jako když žíznivý má sen, že pije; pak se probudí a je stále žíznivý a ⌈jeho duše lační.⌉ Tak tomu bude s množstvím všech národů válčících proti hoře Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Otálejte a buďte ohromeni, ⌈oslepujte se a buďte slepí!⌉ Opili se, ale ne vínem, potáceli se, ale ne z piva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Neboť Hospodin na vás vylil ducha hlubokého spánku, zavřel vaše oči -- proroky, přikryl vaše hlavy -- vidoucí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Celé toto zjevení je pro vás jako slova zapečetěné knihy, kterou dají někomu, kdo umí číst, se slovy: Přečti to. I řekne: Nemohu, protože je zapečetěná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Pak bude ta kniha dána někomu, kdo neumí číst, se slovy: Přečti to. I řekne: Neumím číst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Panovník řekl: Protože se tento lid přibližoval svými ústy a ctili mne svými rty, ale jeho srdce se ode mne daleko vzdálilo -- jejich bázeň přede mnou je ⌈naučena z příkazu lidí,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'proto hle, já znovu podivuhodně naložím s tímto lidem, podivuhodně a neobyčejně. A zahyne moudrost jeho moudrých a rozumnost jeho rozumných bude zahalena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Běda těm, kdo ⌈se drží hluboko od Hospodina, aby skrývali⌉ svůj plán. Jejich dílo se děje v temnotě a říkají: Kdo nás vidí? Kdo o nás ví?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Ta vaše převrácenost! Zdali se hlína cení stejně jako hrnčíř? Což řekne dílo o svém Tvůrci: Neučinil mě, a výtvor poví o tom, kdo ho utvořil: Ničemu nerozumí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Což to nebude už velmi brzy a Libanon se změní v ovocný sad a ovocný sad bude mít cenu lesa?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'V onen den hluší uslyší slova knihy a ze zatmění a temnoty prohlédnou oči slepých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Pokorní ⌈se budou opět radovat⌉ v Hospodinu a nejchudší z lidí budou jásat ve Svatém Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Neboť bude konec s násilníkem, pomine posměvač a všichni pohotoví ke špatnosti budou vyhlazeni,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'ti, kteří svádějí člověka ke hříchu slovem, kladou léčku tomu, kdo kárá v bráně, a ⌈nicotností převracejí při ⌉ spravedlivého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Proto toto praví Hospodin, který vykoupil Abrahama, o domu Jákobovu: Jákob se už nebude stydět a jeho tvář už nezbledne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Neboť když ⌈uvidí své děti,⌉ dílo mých rukou, ve svém středu, budou posvěcovat mé jméno; budou posvěcovat Svatého Jákobova a budou se strachovat Boha Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'A ⌈bloudící duchem⌉ poznají rozumnost a reptající se naučí poučení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Běda umíněným synům, je Hospodinův výrok, kteří provádějí plán, ale ⌈ne ode mne,⌉ a vylévají úlitbu, ale ne podle mého ducha, jen aby vršili hřích na hřích;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'těm, kteří zamýšlejí sestoupit do Egypta -- avšak mých úst se přitom nedoptávají -- aby hledali bezpečí pod záštitou faraona a našli útočiště ve stínu Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Faraonova záštita vám bude k hanbě a útočiště ve stínu Egypta k potupě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Ačkoliv jeho knížata byla v Sóanu a jeho poslové dorazí do Chánesu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'každý bude zahanben kvůli lidu, který mu neprospěje. Nebude k pomoci ani k prospěchu, ale k hanbě a k potupě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Prorocký výnos o zvířatech Negebu: Zemí soužení a sklíčenosti -- odkud jsou lvice a lev, zmije i létající ohnivý had -- tam nesou na zádech oslů svůj majetek a na hrbech velbloudů své poklady lidu, který jim neprospěje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'A Egypťané? Budou pomáhat marně a zbytečně. Proto jsem o nich vyhlásil: Jsou umlčený bouřlivák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Teď jdi a zapiš to ⌈před nimi⌉ na tabulku a na listinu to zaznamenej, ať je to pro budoucí dny jako svědectví až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Neboť to je vzpurný lid, prolhaní synové, synové neochotní poslouchat Hospodinův zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Říkají vidoucím: Nehleďte, a prorokům: Neprorokujte nám správné věci, říkejte nám hladká slova, prorokujte klamy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Ustupte z cesty, uhněte ze stezky, přestaňte nám mluvit o Svatém Izraele!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Proto toto praví Svatý Izraele: Protože jste zavrhli toto slovo a spoléháte na útlak a vychytralost a o to se opíráte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'proto vám tato vina bude jako trhlina zapříčiňující pád, která se rozšiřuje ve vysoké hradbě, jejíž zkáza přijde náhle, v okamžiku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Rozbije se tak, jako když se dočista rozbije hrnčířův džbán, rozdrcen bez lítosti, takže se v té drti nenajde ani střep k shrnutí ohně z ohniště nebo k nabrání vody z louže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Neboť toto řekl Panovník Hospodin, Svatý Izraele: V návratu a klidu budete zachráněni, v utišení a v důvěře bude vaše síla. Ale nechtěli jste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Řekli jste: Ne, ale budeme utíkat na koních -- proto budete utíkat -- a: Pojedeme na rychlonohých -- proto vaši pronásledovatelé budou rychlonozí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tisíc bude utíkat před válečným pokřikem jediného, před pokřikem pěti utečete, dokud nezůstanete jako žerď na vrcholku hory a jako korouhev na návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Proto Hospodin vyčkává, aby se nad vámi slitoval, proto se pozdvihne, aby se nad vámi smiloval, protože Hospodin je Bůh práva -- blahoslavení jsou všichni, kdo na něho toužebně očekávají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Neboť lid bude bydlet na Sijónu, v Jeruzalémě. Nebudeš již plakat, Hospodin ti bude velice milostivý při zvuku tvého úpěnlivého křiku: Jakmile jej uslyší, odpoví ti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Ačkoliv vám Panovník dá chléb úzkosti a vodu útisku, tvoji učitelé se již nebudou skrývat, ale na vlastní oči uvidíš své učitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'A na vlastní uši uslyšíš za sebou říkat: To je ta cesta, po ní jděte, ať se dáte napravo nebo nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Pak prohlásíte za nečisté své stříbrem potažené tesané modly i svou pozlacenou litou modlu, odvrhneš je jako věci poskvrněné menstruací. Řekneš jim: Táhněte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'A on dá ⌈déšť pro tvé zrno,⌉ kterým oseješ zemi, ⌈ dá pokrm z úrody země a⌉ bude šťavnatý a tučný. Tvůj dobytek se bude v onen den pást na rozlehlých pastvinách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'býci a osli obdělávající zemi budou žrát smíšenou slanou píci, která se prohazuje lopatou a vidlemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'A na každé vysoké hoře a na každém vyvýšeném návrší budou koryta tekoucí vody, v den velkého vraždění, kdy padnou věže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'I bude světlo měsíce jako světlo slunce a světlo slunce bude sedminásobné, jako světlo sedmi dnů -- v den, kdy Hospodin ováže zlomeninu svého lidu a ⌈jeho zdrcující ránu⌉ uzdraví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Hle, Hospodinovo jméno přichází zdaleka, planoucí hněvem, v ⌈hustém oblaku⌉ dýmu; jeho rty jsou plné rozhořčení, jeho jazyk jako stravující oheň');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'a jeho dech bude jako valící se potok dosahovat až k šíji, aby ⌈vláčel národy ve jhu⌉ nicoty a aby je udidly na čelistech národů zaváděl z cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Budete mít na rtech píseň jako v noci zasvěcení svátku a v srdci radost jako ten, kdo jde za zvuku flétny, aby vstoupil na Hospodinovu horu, ke Skále Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'A Hospodin nechá zaznít svůj majestátný hlas a ukáže ⌈svou pádnou paži⌉ s běsněním hněvu a plamenem stravujícího ohně, s pleskáním a přívalem deště a s kamenným krupobitím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Neboť Asýrie se zděsí Hospodinova hlasu, když ji udeří holí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'I stane se, že každý úder trestající hole, který na ni Hospodin dopustí, bude s tamburínami a s lyrami. Bude s ní bojovat v bitvách s máváním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Protože již dlouho je připraven Tófet, také pro krále je připraven: Je ⌈vyhlouben doširoka.⌉ Jeho ohnivá hranice s množstvím dříví -- Hospodinův dech ji rozpaluje jako potok síry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Běda těm, kdo sestupují do Egypta pro pomoc a opírají se o koně. Spoléhají na vozbu, že je početná, a na koně, že ⌈jsou velice zdatní,⌉ avšak ke Svatému Izraele nevzhlížejí a Hospodina se nedotazují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Také on je moudrý, přivede zlo a svá slova nevezme zpět. Povstane proti domu zločinců i proti pomoci pachatelů zla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Egypťané jsou lidé, a ne Bůh, jejich koně jsou maso, a ne duch. Hospodin vztáhne ruku, a klopýtne pomocník a padne ten, kdo pomoc očekává, a všichni společně zajdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Neboť toto mi řekl Hospodin: Tak jako lev či mladý lev mručí nad svou kořistí a neděsí se hlasu spousty pastýřů, kteří byli svoláni proti němu, před jejich halasem se nekrčí, tak Hospodin zástupů sestoupí, aby bojoval na hoře Sijónu a na jejím návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Jako ptáci poletují, tak bude Hospodin zástupů Jeruzalému štítem; zaštítí a vysvobodí, projde a vyprostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Navraťte se k tomu, od kterého jste se hluboce odcizili svou umíněností, synové Izraele!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Ano, v onen den zavrhnete každý své stříbrné nicotnosti i své zlaté nicotnosti, které vám vaše hříšné ruce udělaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Ašúr padne mečem, nikoli člověka, pozře ho meč, nikoli lidský. Bude utíkat před mečem a jeho mládenci půjdou na nucené práce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, '⌈Jeho skála ho v hrůze pomine⌉ a jeho velitelé se budou děsit každé korouhve, je výrok Hospodina, jehož plamen je na Sijónu a pec v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Hle, král bude kralovat spravedlivě a knížata budou vládnout podle práva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Každý z nich bude jako skrýše před větrem a úkryt před přívalem, jako proudy vody ve vyprahlém kraji, jako stín ohromné skály v žíznivé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Oči těch, kdo vidí, nebudou zalepené a uši těch, kdo slyší, budou pozorně naslouchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Srdce nerozvážných porozumí poznání a jazyk koktavých bude mluvit hbitě a jasně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Blázen už nebude nazýván šlechetným a podlému nebudou říkat urozený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Protože blázen mluví pošetilost a jeho srdce působí špatnost, aby jednal pokrytecky a mluvil o Hospodinu převráceně, aby nechal ⌈hladového lačnět⌉ a nápoj žíznivého zmařil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'A podlec? Jeho nástroje jsou zlé. Připravuje zlé úmysly, aby zničil nuzného lživými řečmi, i když ⌈je právo na straně nuzného.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Ale šlechetný připravuje šlechetné věci a na šlechetných věcech trvá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Bezstarostné ženy, vstaňte, slyšte můj hlas! Sebejisté dcery, naslouchejte mojí řeči!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Do roka a několika dnů se budou třást sebejisté ženy, protože pomine vinobraní, sklizeň nepřijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Třeste se, bezstarostné, chvějte se, sebejisté, svlékněte se, obnažte se a přepásejte svá bedra žíní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'a ⌈bijte se v prsa⌉ nad překrásnými poli, nad úrodnou révou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'nad zemí mého lidu, kde vyroste trní a bodláčí, ano, nad všemi domy radosti rozjařeného města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Neboť palác bude zanedbaný, ruch opustí město; citadela se strážnou věží se stanou navěky jeskyněmi, radostí divokých oslů, pastvinou stád,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'dokud na nás nebude vylit Duch shůry. Pak se pustina stane ovocným sadem a ovocný sad bude mít cenu lesa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'v pustině se usídlí právo a spravedlnost bude pobývat v ovocném sadu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Dílem spravedlnosti bude pokoj a službou spravedlnosti utišení a bezpečí navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'A můj lid bude bydlet v pokojném obydlí, v bezpečných příbytcích a v klidných místech odpočinku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'I když padne na les krupobití a město bude úplně sníženo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'blahoslavení jste vy, kdo rozséváte při všech vodách a dáváte volnost býku i oslu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Běda tobě, ničiteli, který jsi nebyl ničen, zrádce, s kterým nejednali zrádně. Jakmile dokonáš ničení, budeš sám zničen, jakmile dovršíš zradu, budou zrádně jednat s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Hospodine, buď nám milostiv, na tebe očekáváme. Buď jejich silou každé ráno i naší záchranou v čase soužení!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Před zvukem hřmotu se lidé rozprchnou, když se pozvedneš, národy se rozptýlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Vaše kořist bude sebrána, jako by ji sebraly kobylky chasíl; zaútočí na ni, jako když vpadne hejno kobylek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Hospodin je vyvýšený, vždyť přebývá vysoko; naplní Sijón právem a spravedlností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Bude jistotou tvých časů, bohatstvím záchrany, moudrosti a poznání; bázeň před Hospodinem je jeho pokladem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Hle, Aríelci úpěnlivě volají na ulici, poslové pokoje hořce pláčou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Silnice jsou zpustošené, zmizeli cestující; zrušil smlouvu, zavrhl města, člověka si neváží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Země truchlí a zvadla. Libanon je zahanben a povadl. Šáron je jako Araba, Bášan a Karmel setřásá listí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Teď povstanu, praví Hospodin, teď se pozvednu, teď se povznesu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, '⌈Otěhotníte suchou trávou, porodíte strniště. Váš dech vás stráví jako oheň.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Národy budou jako vypalování vápna, vzplanou ohněm jako posekané trní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Slyšte, vzdálení, co jsem učinil, poznejte, blízcí, moji udatnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Hříšníci na Sijónu se strachují, bezbožné zachvátil třes: Kdo z nás bude pobývat u stravujícího ohně? Kdo z nás bude pobývat u věčných plamenů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Ten, kdo ⌈chodí v spravedlnosti⌉ a mluví, co je správné; kdo zavrhuje nekalý zisk z vydírání, ⌈vytřásá ruce, aby nepřijal⌉ úplatek, kdo zavírá uši, aby neslyšel o prolití krve, a přivírá oči, aby se nedíval na zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Ten bude přebývat na výšinách, skalní pevnosti budou jeho nepřístupným hradem. Bude mu dáván chléb a ⌈voda mu nevyschne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Tvé oči uvidí Krále v jeho kráse, spatří i ⌈rozlehlou zemi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Tvé srdce bude přemítat o dřívější hrůze: Kde je ten, kdo počítá? Kde je ten, kdo váží? Kde je ten, kdo počítá věže?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Neuvidíš už lid lítý, lid ⌈nesrozumitelné řeči,⌉ ⌈které se nedá rozumět,⌉ a žvatlavého, nesrozumitelného jazyka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Pohleď na Sijón, město našich svátků, tvé oči uvidí Jeruzalém, klidný příbytek, stan, který se nepohne, jeho kolíky se nikdy nevytrhnou a žádný jeho provaz se nepřetrhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Neboť ⌈tam pro nás bude vznešený Hospodin místem⌉ řek -- ⌈velmi širokých⌉ kanálů -- jímž nepoplyne loďstvo s vesly, ani jím nepropluje vznešená loď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Neboť Hospodin je náš soudce, Hospodin je náš zákonodárce; Hospodin je náš král, on nás zachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Tvoje lana jsou svěšena; neupevní správně stěžeň, nenapnou plachtu. Tehdy bude rozdělena hojná kořist, i chromí zaberou lup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'A žádný obyvatel Sijónu neřekne: Jsem nemocen. Lid, který v něm bude bydlet, ⌈bude zproštěn viny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Přistupte, národy, abyste slyšely, a pozorně naslouchejte, lidé! Ať slyší země a všechno, co je v ní, svět a ⌈vše, co na něm vzchází.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Protože Hospodinovo rozhořčení je proti všem národům a jeho zloba proti všem jejich zástupům. ⌈Zasvětil je zkáze,⌉ vydal je na porážku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Jejich pobití budou pohozeni venku a z jejich mrtvol bude vystupovat smrad. Hory budou rozmáčené jejich krví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Veškerý nebeský zástup se rozloží a nebesa se svinou jako kniha. Všechen jejich zástup bude padat, jako padá listí z révy nebo jako padavka z fíkovníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Neboť na nebesích se napojí můj meč; hle, sestoupí na Edóm, na ⌈lid, na nějž jsem uvalil klatbu,⌉ ⌈aby zjednal právo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Hospodinův meč je plný krve, nasycený tukem a krví jehňat a kozlů, tukem z ledvin beranů; neboť Hospodin má obětní hod v Bosře a veliká jatka v edómské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'S nimi klesnou divocí tuři i býčci s hřebci, a jejich země bude napojena krví a prach bude prosycen tukem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'protože to je den Hospodinovy pomsty, rok odplaty v soudním sporu Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Jeho potoky se změní ve smolu a jeho prach v síru; jeho země se stane planoucí smolou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'V noci ani ve dne neuhasne, navěky bude vystupovat její kouř; z generace na generaci zůstane v troskách, na věky věků jí nikdo nebude procházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Do vlastnictví ji dostanou pelikán a sýček, usídlí se v ní výr a havran; roztáhne na ní šňůru marnosti a závaží prázdnoty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, '⌈Nebudou tam její šlechtici, které by povolali ke královské autoritě,⌉ ze všech jejích knížat nikdo nezůstane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Na jejích palácích vyroste trní, kopřivy a houští v jejích pevnostech; stane se příbytkem šakalů, hnízdištěm pštrosů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, '⌈Divoká zvířata⌉ se budou setkávat s divokými psy a běs zavolá na svého druha; také se tam usadí Lilit a nalezne si místo odpočinku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Uhnízdí se tam šípovitý had a naklade vejce, vysedí je a shromáždí ve svém stínu. Také se tam shromáždí luňáci, každý se svým druhem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Hledejte v Hospodinově knize a čtěte, ani jedno z nich nechybí, žádný svého druha nepostrádá, protože ⌈má ústa⌉ to přikázala a jeho Duch je shromáždil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'On nechal padnout jejich los a jeho ruka jim ji rozdělila měřicí šňůrou: Budou ji vlastnit až navěky, z pokolení do pokolení v ní budou přebývat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Pustina i bezvodá zem budou jásat, Araba zaplesá a rozkvete jako narcis.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Krásně rozkvete a zaplesá s jásáním a radostným křikem, bude jí dána sláva Libanonu, nádhera Karmelu a Šáronu; ty uzří Hospodinovu slávu, nádheru našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Posilujte malátné ruce, upevňujte klopýtající kolena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Řekněte těm, kdo mají ustrašené srdce: Buďte silní, nebojte se; hle, váš Bůh! Přijde s pomstou, s Boží odplatou. On sám přijde a zachrání vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Tehdy prohlédnou oči slepých a uši hluchých se otevřou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Tehdy chromý bude skákat jako jelen a jazyk němého bude výskat, neboť v pustině vytrysknou vody a potoky v Arabě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, '⌈Horký písek⌉ se změní v jezero a žíznivá země ve vodní zřídla; ⌈z příbytku šakalů bude místo odpočinku dobytka, z trávy bude třtina⌉ a papyrus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'A bude tam silnice, cesta, která se bude nazývat cestou svatou: Neprojde po ní nečistý, ⌈bude jen pro toho, kdo jde svatou cestou. Ani⌉ hlupáci nezabloudí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Nebude tam lev a dravá zvěř na ni nevstoupí, ani se tam nebude nacházet, ale půjdou po ní vykoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Hospodinovi vykoupení se navrátí, přijdou s výskáním na Sijón a věčná radost bude na jejich hlavách. Dojdou veselí a radosti, žal a vzdychání utečou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'I stalo se ve čtrnáctém roce vlády krále Chizkijáše, že asyrský král Sancheríb vytáhl proti všem opevněným judským městům a zmocnil se jich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Nato asyrský král poslal ⌈nejvyššího číšníka⌉ s ohromným vojskem z Lakíše do Jeruzaléma ke králi Chizkijášovi. Zastavil se u strouhy Horního rybníka na silnici k Valchářovu poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Vyšel k němu Eljakím, syn Chilkijášův, který byl nad domem, písař Šebna a kancléř Jóach, syn Asafův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Nejvyšší číšník jim řekl: Povězte Chizkijášovi: Toto praví veliký král, král asyrský: Co je to za naději, v niž doufáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, '⌈Myslíš si, že prázdné řeči jsou plánem a silou k boji?⌉ Nuže, na koho spoléháš, že ses proti mně vzbouřil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Hle, spoléháš na tu zlomenou třtinovou hůl -- na Egypt, o kterou když se člověk opře, pronikne do jeho ruky a probodne ji. Takový je faraon, egyptský král, pro všechny, kdo na něho spoléhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'A jestliže mi řekneš: Spoléháme na Hospodina, svého Boha! -- což to není on, jehož návrší a oltáře Chizkijáš odstranil a Judovi a Jeruzalému řekl: Před tímto oltářem se budete klanět!?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Tak se nyní vsaď s mým pánem, asyrským králem: Dám ti dva tisíce koní; jestlipak na ně budeš schopen dodat jezdce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Jak bys mohl ⌈odrazit místodržitele, jednoho z nejmenších otroků mého pána, i když ses spolehl⌉ na Egypt, na vozbu a koně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Cožpak jsem nyní bez Hospodina vytáhl proti této zemi, abych ji zničil? Hospodin mi řekl: Vytáhni proti této zemi a znič ji!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Eljakím, Šebna a Jóach nejvyššímu číšníkovi řekli: Mluv přece ke svým otrokům aramejsky, vždyť my rozumíme. Nemluv k nám judsky před lidem, který je na hradbách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Nejvyšší číšník řekl: Což mě poslal můj pán mluvit tato slova jen ke tvému pánu a k tobě? Cožpak ne k těm mužům, kteří pobývají na hradbách a budou s vámi jíst svá lejna a pít ⌈svoji moč?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Nejvyšší číšník stál a hlasitě judsky volal: Slyšte slova velikého krále, krále asyrského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Toto praví král: Ať vás Chizkijáš nepodvádí, protože vás není schopen vysvobodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'A ať Chizkijáš ve vás nevzbuzuje doufání v Hospodina slovy: Hospodin nás jistě vysvobodí. Toto město nebude vydáno do ruky asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Neposlouchejte Chizkijáše; neboť toto praví asyrský král: ⌈Sjednejte se mnou pokoj⌉ a vyjděte ke mně a budete jíst každý ze své révy a ze svého fíkovníku a budete pít každý vodu ze své studny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'dokud nepřijdu a nevezmu vás do země podobné vaší zemi, země obilí a vína, země chleba a vinic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Ať vás Chizkijáš nenavádí slovy: Hospodin nás vysvobodí. Cožpak některý z bohů národů vysvobodil svou zemi z ruky asyrského krále?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kde jsou bohové Chamátu a Arpádu? Kde bohové Sefarvajimu? Kde jsou bohové samařské země? Jestlipak vysvobodili z mé ruky Samaří?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Který ze všech bohů těchto zemí vysvobodil svou zemi z mé ruky? Že by Hospodin vysvobodil z mé ruky Jeruzalém?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Oni mlčeli a nic mu neodpověděli, protože králův příkaz byl: Neodpovídejte mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'A Eljakím, syn Chilkijášův, který byl nad domem, písař Šebna a kancléř Jóach, syn Asafův, vešli k Chizkijášovi s roztrženými rouchy a oznámili mu slova nejvyššího číšníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'I stalo se, když to král Chizkijáš uslyšel, že roztrhl své roucho, zahalil se pytlovinou a vešel do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'A poslal Eljakíma, který byl nad domem, písaře Šebnu a starší z kněží zahalené do pytloviny k proroku Izajášovi, synu Amósovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Řekli mu: Toto praví Chizkijáš: Tento den je dnem soužení, trestu a znevážení, protože děti se přiblížily k vyjití, ale není síla ku porodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Snad Hospodin, tvůj Bůh, uslyší slova nejvyššího číšníka, kterého jeho pán, asyrský král, poslal, aby hanobil živého Boha, a pokárá ho za slova, která Hospodin, tvůj Bůh, slyšel. Pozdvihni tedy modlitbu za ostatek, který se tu nachází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Otroci krále Chizkijáše přišli tedy k Izajášovi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'a Izajáš jim řekl: Toto řekněte svému pánu: Toto praví Hospodin: Neboj se slov, která jsi slyšel, jimiž mi služebníci asyrského krále utrhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Hle, dávám do něj ducha, že když uslyší zprávu, navrátí se do své země a nechám ho v jeho zemi padnout mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Když se nejvyšší číšník vrátil, nalezl asyrského krále, jak bojuje proti Libně. Slyšel totiž, že odtáhl od Lakíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Asyrský král uslyšel o kúšském králi Tirhákovi: Vytáhl, aby s tebou bojoval. Když to uslyšel, poslal k Chizkijášovi posly se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Toto řekněte judskému králi Chizkijášovi: Ať tě tvůj Bůh, v něhož doufáš, nepodvádí slovy: Jeruzalém nebude vydán do ruky asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Hle, sám jsi slyšel, jak naložili asyrští králové se všemi těmi zeměmi, že je zcela vyhladili. A ty bys byl vysvobozen?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Bohové těch národů, jež moji otcové zničili -- bohové Gózanu, Cháranu, Resefu a synů Edenu, kteří byli v Telasáru -- je snad vysvobodili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kde je král Chamátu, král Arpádu a král města Sefarvajim, Heny a Ivy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Chizkijáš vzal dopis od poslů a přečetl ho. Pak Chizkijáš vstoupil do domu Hospodinova a rozprostřel ho před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Chizkijáš se modlil k Hospodinu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Hospodine zástupů, Bože Izraele, sedící na cherubech, ty jediný jsi Bůh všech království země; ty jsi ⌈učinil nebesa i zemi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Nakloň, Hospodine, své ucho a slyš; otevři, Hospodine, své oči a pohleď! Slyš všechna Sancheríbova slova, která vzkázal, aby hanobil živého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Hospodine, asyrští králové všechna ta království i jejich území opravdu zpustošili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'a jejich bohy uvrhli do ohně, protože to nejsou bohové, nýbrž ⌈dílo lidských rukou, dřevo a kámen⌉ -- proto je zničili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'A teď, Hospodine, náš Bože, zachraň nás z jeho ruky, aby všechna království země poznala, že ty, Hospodine, jsi jediný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Izajáš, syn Amósův, vzkázal Chizkijášovi: Toto praví Hospodin, Bůh Izraele: Modlil ses ke mně ohledně asyrského krále Sancheríba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Toto je slovo, které o něm řekl Hospodin: Pohrdá tebou a posmívá se ti panna, dcera sijónská, potřásá nad tebou hlavou dcera jeruzalémská.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Koho jsi hanobil a komu jsi utrhal? Proti komu jsi pozvedl ⌈hlas? Vysoko jsi pozdvihl oči proti Svatému Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Skrze své otroky jsi hanobil Panovníka a řekl sis: S množstvím svých vozů jsem vytáhl na výšiny hor, do nejvzdálenějších částí Libanonu; pokácel jsem jeho vysoké cedry, jeho nejlepší cypřiše; vstoupil jsem do jeho nejzazší výše, do jeho úrodné lesní zahrady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Já jsem vykopal studny a pil jsem vodu, chodidly svých nohou jsem vysušil všechny egyptské řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Cožpak jsi neslyšel, že jsem to již dávno připravil, před dávnými časy jsem to vytvořil? Nyní to naplňuji: Nastalo pustošení, opevněná města se hroutí v hromady kamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Jejich obyvatelé byli bezmocní, vyděšeni a zahanbeni, byli jako polní zeleň a zelené býlí, jako tráva na střechách a pole sežehnuté ⌈východním větrem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Tvé bydlení, tvé vycházení i vcházení znám, také tvé běsnění proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Protože tvé běsnění proti mně a tvá sebejistota vystoupila do mých uší, vložím ti kruh do nosu a uzdu do tvých pysků a odvedu tě zpět cestou, kterou jsi přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'A toto ti bude znamením: Tento rok se bude jíst to, co vyroste samo, v druhém roce to, co z toho ještě vyroste, a ve třetím roce ⌈zasévejte a sklízejte, vysazujte vinice a jezte⌉ jejich ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'A ostatek -- ti z domu judského, ⌈kteří vyváznou⌉ -- se opět hluboko zakoření a ponese ovoce vzhůru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'neboť z Jeruzaléma vyjde ostatek a z hory Sijón ti, kteří vyváznou: Horlivost Hospodina zástupů to učiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Proto toto praví Hospodin o asyrském králi: Nevejde do tohoto města, ani šíp tam nevystřelí, nevyjde proti němu se štítem ani proti němu nenavrší násep.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Cestou, kterou přišel, se vrátí, a do tohoto města nevejde, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Budu tomuto městu štítem, abych je zachránil kvůli sobě a kvůli svému otroku Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Tehdy vyšel Hospodinův anděl a pobil v asyrském táboře sto osmdesát pět tisíc mužů. Když lidé časně ráno vstali, hle, ti všichni byli ⌈dočista mrtví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'A asyrský král Sancheríb odtáhl, šel, vrátil se a pobýval v Ninive.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'I stalo se, když se klaněl v chrámu svého boha Nisrocha, že jeho synové Adramelek a Sareser ho zabili mečem a sami unikli do země Ararat. Po něm se stal králem jeho syn Esarchadón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'V oněch dnech Chizkijáš na smrt onemocněl. Přišel k němu prorok Izajáš, syn Amósův, a řekl mu: Toto praví Hospodin: Dej příkazy ohledně svého domu, protože zemřeš; nezotavíš se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Chizkijáš odvrátil tvář ke stěně a modlil se k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Řekl: Ach, Hospodine, jen se rozpomeň, jak jsem chodil před tebou věrně a s celým srdcem a činil jsem to, co je dobré ve tvých očích. A Chizkijáš se dal do velikého pláče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Tu se stalo Hospodinovo slovo k Izajášovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Jdi a řekni Chizkijášovi: Toto praví Hospodin, Bůh tvého otce Davida: Slyšel jsem tvou modlitbu a viděl tvé slzy. Hle, přidávám ke tvým dnům patnáct let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Vysvobodím tebe i toto město z ruky asyrského krále a budu tomuto městu štítem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Toto ti bude znamením od Hospodina, že Hospodin učiní tu věc, kterou řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Hle, vrátím stín po stupních, po kterých slunce sestoupilo na stupních Achazových slunečních hodin, nazpět o deset stupňů. A slunce se vrátilo o deset stupňů, těch stupňů, po kterých předtím sestoupilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Zápis judského krále Chizkijáše o jeho nemoci a o tom, jak se ze své nemoci zotavil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Řekl jsem: Uprostřed svých dnů mám jít do bran podsvětí! ⌈Jsem připraven o ⌉ zbytek svých let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Řekl jsem si: Už nespatřím Hospodina, Hospodina v zemi živých, už neuvidím člověka spolu s obyvateli ⌈ místa odloučení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Mé pobývání bylo strženo a stěhuje se ode mne jako pastýřský stan; jako tkadlec jsem svinul svůj život, vždyť mne odtrhne od stavu, v němž jsem byl tkán. ⌈Než den dospěje k noci,⌉ se mnou skoncuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, '⌈Stavěl jsem si před oči až do jitra, že ⌉ jako lev rozláme všechny mé kosti. Než den dospěje k noci, se mnou skoncuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Jako rorejs nebo jeřáb, tak sípu, lkám jako holubice; mé oči zeslábly hleděním vzhůru: Panovníku, jsem utištěn, zastaň se mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Co mám ⌈mluvit? Jak mi řekl, tak i učinil.⌉ Poputuji všechna svá léta s hořkostí duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, '⌈Panovníku, pro tyto věci lidé žijí a pro všechno v nich je život mého ducha.⌉ Uzdrav mě a zachovej mne při životě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Hle, ⌈k pokoji mi byla hořkost nejhořčí. Ty⌉ ⌈jsi zadržel mou duši od⌉ jámy nicoty, protože všechny moje hříchy jsi odvrhl za svá záda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Protože podsvětí ti nebude vzdávat chválu, smrt tě nebude chválit; tvou pravdu nebudou vyhlížet ti, kdo sestupují do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Živý, jen živý ti bude vzdávat chválu jako já dnes; otec synům bude oznamovat tvou pravdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Hospodine, pospěš mě zachránit! A po všechny dny svého života budeme v Hospodinově domě hrát na strunné nástroje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Izajáš řekl: Ať vezmou placku sušených fíků a třou jí vřed, a zůstane naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'A Chizkijáš řekl: Co bude znamením, že vstoupím do Hospodinova domu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'V té době babylonský král Meródak–baladán, syn Baladánův, poslal dopis a dar Chizkijášovi. Slyšel totiž, že byl nemocen a zotavil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Chizkijáš se z nich radoval a ukázal jim svou klenotnici, stříbro a zlato, balzámy a vonný olej, celou svou zbrojnici -- všechno, co se nacházelo v jeho skladech. Nebylo nic, co by jim Chizkijáš ve svém paláci a v celém svém panství neukázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Pak přišel ke králi Chizkijášovi prorok Izajáš a zeptal se ho: Co říkali ti muži a odkud k tobě přišli? Chizkijáš odpověděl: Přišli ke mně z daleké země, z Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Nato se ho zeptal: Co viděli ve tvém paláci? Chizkijáš odpověděl: Viděli všechno, co je v mém paláci. Nebylo nic, co bych jim ve svých skladech neukázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Izajáš Chizkijášovi řekl: Slyš slovo Hospodina zástupů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Hle, přicházejí dny, kdy všechno, co je ve tvém paláci a co až dodnes tvoji otcové nahromadili, bude odneseno do Babylona. Nezůstane nic, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'A vezmou z tvých synů, kteří z tebe vzejdou, které zplodíš, a stanou se ⌈dvorními úředníky⌉ v paláci babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Chizkijáš řekl Izajášovi: Hospodinovo slovo, které jsi vyslovil, je dobré. A sobě řekl: Protože ⌈za mých dnů⌉ bude pokoj a bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Potěšte, potěšte můj lid, říká váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Promlouvejte ⌈k srdci⌉ Jeruzaléma, volejte k němu, že se naplnila jeho povinná služba, že je zaplaceno za jeho viny; vždyť přijal z Hospodinovy ruky dvojnásobně za všechny své hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Hlas ⌈volá v pustině: Připravte⌉ cestu Hospodinovu, napřimte v pustině silnici pro našeho Boha!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Každé údolí bude pozdviženo a každé pohoří a návrší sníženo; ⌈pahorkatina se stane rovinou⌉ a útesy plání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'A zjeví se Hospodinova sláva a uvidí to spolu veškeré tělo; protože Hospodinova ústa promluvila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Hlas říká: Volej! I zeptal se: Co mám volat? Veškeré tělo je jako tráva a všechna jeho oddanost jako polní květ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Tráva usychá, květ vadne, když na něj zavane Hospodinův dech. Jistě, ⌈lid je⌉ jen tráva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Tráva usychá, květ vadne, ale slovo našeho Boha obstojí navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Vystup si na vysokou horu, Sijóne, nositeli dobré zprávy, pozvedni mocně hlas, Jeruzaléme, nositeli dobré zprávy. Pozvedni hlas, neboj se, řekni judským městům: Hle, váš Bůh!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Hle, Panovník Hospodin přichází s mocí a jeho paže pro něj vládne. Hle, jeho mzda s ním a jeho odměna před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Bude pást své stádo jako pastýř, svou paží shromáždí jehňata a v náruči je ponese, březí povede pomalu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kdo svou dlaní odměřil vody a nebesa pídí vyměřil a do třetinky nabral prach země? Kdo odvážil hory na váze a na miskách kopce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kdo vystrojil ⌈Hospodinova ducha,⌉ kdo byl jeho rádce a poučil ho?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'S kým se radil, aby mu dal porozumět a vyučil ho ⌈cestě práva,⌉ naučil ho poznání a dal mu poznat cestu rozumnosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Hle, národy jsou před ním jako kapka na vědru nebo jako poprašek na vahách. Hle, ostrovy nadzvedá jako smítko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Stromy Libanonu nestačí na oheň a jeho zvěř nestačí na zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Všechny národy jsou před ním jako nic. Mají pro něj cenu menší než nic, než marnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Ke komu tedy připodobníte Boha? ⌈Jakou představu si o něm učiníte?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Řemeslník odlil modlu a zlatník ji potáhne zlatem; stříbrný řetěz k ní udělá zlatník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, '⌈Kdo je chudý na takovou oběť, vybere⌉ nepráchnivějící dřevo; vyhledá si zručného řemeslníka, aby modlu upevnil, takže se nepohne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Což to nevíte? Což jste o tom neslyšeli? Což se vám to neoznamuje od počátku? Což jste neporozuměli, kdo položil základy země?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Ten, který sídlí nad obzorem země, jejíž obyvatelé jsou jako kobylky, který jako závoj roztahuje nebesa a napíná je jako stan k bydlení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'který proměňuje mocnáře v nic, soudce země učinil marností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Sotva byli zasazeni, sotva byli zaseti, sotva jejich odnož zakořenila v zemi, již na ně zaduje a oni uschnou a vichřice je odnese jako stéblo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Ke komu mne tedy připodobníte? Komu jsem roven? praví ten Svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Pozvedněte své oči vysoko a pohleďte: Kdo stvořil tyto věci? Ten, kdo vyvádí podle počtu jejich zástup, všechny je volá jménem, pro jeho velkou sílu a ohromnou moc žádná z nich nechybí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Proč říkáš, Jákobe, proč povídáš, Izraeli: Má cesta je před Hospodinem ukryta a ⌈mé právo mému Bohu uniká?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Což to nevíš? Cožpak jsi neslyšel, že věčný Bůh, Hospodin, stvořitel končin země, neochabne ani se neunaví? Jeho rozumnost je nevyzpytatelná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Unavenému dává sílu a ⌈bezmocného zahrnuje zdatností.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Chlapci ochabnou a unaví se a mládenci vyčerpáním padají,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'ale ti, kdo očekávají na Hospodina, ⌈nabývají nové⌉ síly, vznášejí se na křídlech jako orli; běží, a neunaví se, chodí, a neochabnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Tiše ⌈mi naslouchejte,⌉ ostrovy, a národy ať obnoví svou sílu. Ať se přiblíží, pak ať promluví. Přistupme spolu k soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kdo vzbudil vítěze od východu? ⌈ Kdo ho řádně povolá do své služby?⌉ Vydá mu národy a nechá ho pošlapat krále, dá je jako prach jeho meči, jako odvívané stéblo jeho luku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Bude je pronásledovat, bude táhnout v pokoji, na stezku nohama nevstoupí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kdo to udělal a způsobil? Ten, kdo povolává generace od počátku. Já, Hospodin, jsem první, a také u posledních já budu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Ostrovy to viděly a bály se, končiny země se budou třást, přiblíží se a přijdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Jeden bude pomáhat druhému a řekne svému bratru: Buď silný!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Tak posiluje řemeslník zlatníka, ten, kdo vyhlazuje kladivem, toho, kdo buší do kovadliny, říkaje o spoji: Je to dobré. A upevní to hřebíky, takže se to nepohne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Ale ty, Izraeli, můj otroku, Jákobe, kterého jsem vyvolil, semeno ⌈mého přítele Abrahama,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'ty, kterého jsem uchopil z končin země a povolal z jejích odlehlých míst -- tobě jsem řekl: Ty jsi můj otrok! Vyvolil jsem tě a nezavrhl jsem tě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Neboj se, protože já jsem s tebou, nehleď ustrašeně, protože já jsem tvůj Bůh. Budu tě posilovat, ano, budu ti pomáhat a držet tě svou spravedlivou pravicí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Hle, budou se stydět a budou zahanbeni všichni, kteří proti tobě planou hněvem, stanou se ničím a zahynou tvoji odpůrci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Budeš je hledat a nenalezneš ty, kdo se s tebou hádají. Stanou se ničím a nebudou ti, kdo s tebou válčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Protože já jsem Hospodin, tvůj Bůh, který drží tvoji pravici a říká ti: Neboj se, já ti budu pomáhat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Neboj se, červíčku Jákobův, hrstko Izraelova, já ti budu pomáhat, ⌈ je Hospodinův výrok. Tvůj vykupitel je Svatý Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Hle, učinil jsem tě novým oboustranným mláticím smykem. Budeš mlátit hory a rozdrtíš je a návrší proměníš v plevy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Prověješ je a vítr je odnese, vichřice je rozptýlí. Ty však budeš jásat v Hospodinu, budeš se chlubit Svatým Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Nuzní a chudí hledají vodu, ale žádná není. Jejich jazyk je vyprahlý žízní. Já, Hospodin, jim odpovím, já, Bůh Izraele, je neopustím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Otevřu na holých návrších řeky a uprostřed plání prameny; proměním pustinu v jezero vod a zemi bezvodou ve vodní zdroje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Dám vyrůst v pustině cedru a akácii, myrtoví a plané olivě, v Arabě vysadím cypřiš a jilm spolu se zimostrázem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Aby viděli a poznali, zvážili a společně pochopili, že ruka Hospodinova to učinila a Svatý Izraele to stvořil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Předložte svůj spor, praví Hospodin, přineste své pádné argumenty, praví král Jákobův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Ať je přinesou a oznámí nám, co se má přihodit. Oznamte, co jsou ty dřívější věci, ať si to vezmeme k srdci a poznáme jejich konec, nebo nám zvěstujte věci přicházející.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Oznamte, co má přijít potom, a poznáme, že jste bohové. Také vykonejte něco dobrého nebo zlého, ať na to s hrůzou hledíme a společně to spatříme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Hle, nejste nic a vaše skutky nejsou na nic. Ohavností je ten, kdo si vyvolí vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Vzbudil jsem vítěze od severu a přišel -- od východu slunce ten, kdo ⌈bude vzývat mé jméno.⌉ ⌈Podupe správce jako hlínu,⌉ jako hrnčíř bude šlapat bláto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kdo to oznámil od počátku, abychom to věděli, a odedávna, abychom se ptali: Má pravdu? Avšak nikdo nic neoznámil, ano, nikdo nic nezvěstoval a nikdo neslyšel vaše řeči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Já jsem první, kdo mluvil k Sijónu, a hle, zde jsou. Jeruzalému dám svého zvěstovatele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Podíval jsem se a není nikdo, není mezi nimi rádce, aby odpověděli, když se jich zeptám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Hle, jsou samá špatnost, jejich díla jsou nicota, jejich modly jsou větrem a marností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Hle, můj otrok, kterého budu ⌈pevně držet,⌉ můj vyvolený, jehož si má duše oblíbila. Vložil jsem na něj svého Ducha, a přinese právo národům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Nebude křičet ani se pozdvihovat ani nebude venku slyšet jeho hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Nalomenou třtinu nezlomí a hasnoucí knot neuhasí, ⌈bude vynášet pravdivý soud.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Nezemdlí ani se nenalomí, dokud neustanoví v zemi právo. I ostrovy budou očekávat na jeho zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Toto praví Bůh, Hospodin, jenž stvořil nebesa a roztahuje je, rozprostírá zemi i to, co na ní vzchází, který dává dech lidu na ní a ducha těm, kdo po ní chodí:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Já, Hospodin, jsem tě povolal ve spravedlnosti a uchopím tě za ruku. ⌈Budu tě opatrovat⌉ a dám tě za smlouvu lidu a za světlo národů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'abys otevřel oči slepé a vyvedl z vězení vězně -- ⌈z žaláře ty, kdo pobývají v temnotě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Já jsem Hospodin, to je mé jméno, a svou slávu jinému nedám, ani svou chválu modlám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Ty první věci -- hle -- přišly. A nové oznamuji: Dříve než budou vzcházet, ohlásím je vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Zpívejte Hospodinu píseň novou, pějte jeho chválu od končin země, vy, kdo se vydáváte na moře, i všechno, co je v něm, ostrovy i jejich obyvatelé!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Ať pozdvihne svůj hlas pustina i její města, dvory, v nichž pobývá Kédar. Ať výskají obyvatelé Sély, ať pokřikují z vrchu hor,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'ať přiznají Hospodinu slávu a ať oznamují na ostrovech jeho chválu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Hospodin vyjde jako hrdina, ⌈jako bojovník vzbudí svou horlivost.⌉ Rozkřikne se, ano, spustí válečný pokřik, ukáže převahu nad svými nepřáteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Odedávna jsem mlčel. Budu dále hluchý, budu se ovládat? Jako rodička budu vzdychat, supět a lapat po dechu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Vysuším hory i návrší a všechna jejich zeleň uschne. Řeky proměním v ostrovy a jezera nechám vyschnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Povedu slepé cestou, kterou neznali, dám jim kráčet stezkami, které neznali. Temnotu před nimi proměním ve světlo a ⌈hrbolatá místa v rovinu.⌉ Toto jsou věci, které učiním a kterých nezanechám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Stáhnou se nazpět a budou zcela zahanbeni ti, kdo spoléhají na tesané modly, kteří říkají litým modlám: Vy jste naši bohové!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Hluší, slyšte a slepí, pohleďte ⌈a vizte!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kdo je slepý, ne–li můj otrok, a hluchý tak jako můj posel, kterého posílám? Kdo je slepý jako ten, ⌈za něhož jsem zaplatil,⌉ a slepý jako Hospodinův otrok?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Je vidět mnohé, ale nevěnuješ ničemu pozornost, uši jsou otevřené, ale neslyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Kvůli jeho spravedlnosti se Hospodinu zalíbilo učinit zákon významným a zvelebit ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Ale toto je lid oloupený a popleněný. Všichni jsou polapeni v jamách, ukryti v žalářích. Stali se kořistí a není, kdo by vysvobodil, stali se lupem, a není, kdo by řekl: Navrať!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, '⌈Kdo z vás tomu bude naslouchat? Kdo bude⌉ věnovat pozornost, aby slyšel, ⌈ co bude potom?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kdo vydal Jákoba k plenění a Izraele lupičům? Což to nebyl Hospodin? Ten, proti němuž jsme zhřešili? A po jehož cestách chodit nechtěli a jehož zákon neposlouchali?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'A tak na něj vylil žár svého hněvu a sílu boje, který ho spaloval ze všech stran, ale nepoznal to, vzplanul proti němu, ale nevzal si to k srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Ale nyní toto praví Hospodin, ⌈jenž tě stvořil,⌉ Jákobe, a ⌈který tě zformoval,⌉ Izraeli: Neboj se, neboť jsem tě vykoupil, ⌈povolal jsem [tě] tvým jménem,⌉ jsi můj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Když půjdeš přes vody, budu s tebou, a přes řeky, nezalijí tě. Když půjdeš ohněm, nespálíš se a plamen tě neožehne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Protože já Hospodin jsem tvůj Bůh, Svatý Izraele, tvůj zachránce. Dal jsem jako výkupné za tebe Egypt. Kúš a Sebu jsem dal místo tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Protože jsi byl vzácný v mých očích a vážený, a já jsem tě miloval, dal jsem lidi za tebe a národy za tvůj život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Neboj se, protože já jsem s tebou. Přivedu tvé potomstvo od východu, shromáždím tě od západu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Severu řeknu: Vydej! A jihu: Nezadržuj! Přiveď mé syny z daleka a mé dcery od končin země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'každého, kdo je nazýván mým jménem, jehož jsem stvořil ke své slávě, jehož jsem utvořil i učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Vyveď lid slepý, ačkoliv má oči, a hluchý, ačkoliv má uši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Ať se spolu shromáždí všechny národy, ať se shromáždí lidé! Kdo z nich to oznámí a zvěstuje nám ty dřívější věci? Ať vydají svá svědectví a ospravedlní se! Lidé to uslyší a řeknou: To je pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vy jste mými svědky, je Hospodinův výrok, jste ⌈mým otrokem,⌉ kterého jsem vyvolil, abyste mne poznali a uvěřili mi a porozuměli, že ⌈to jsem já.⌉ Přede mnou nebyl vytvořen žádný Bůh ani po mně žádný nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Já, já jsem Hospodin a kromě mne žádný zachránce není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Já jsem oznamoval, zachraňoval a zvěstoval, a nebyl jiný⌉ bůh mezi vámi. Vy jste mí svědkové, je Hospodinův výrok, a já jsem Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'I od onoho dne já jsem a není, kdo by vyrval z mé ruky. ⌈Budu jednat, a⌉ kdo ji odvrátí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Toto praví Hospodin, váš vykupitel, Svatý Izraele: Kvůli vám jsem poslal do Babylona a ⌈zahnal jsem je všechny na útěk⌉ -- ⌈i Chaldejce na jejich lodích plných výskání.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Já jsem Hospodin, váš Svatý, stvořitel Izraele, váš král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Toto praví Hospodin, který činí cestu skrze moře a stezku skrze dravé vody,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'který vyvádí vozbu i koně, vojsko i vojenskou moc. Najednou ulehnou a už nevstanou, dohořeli, zhasli jako knot:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Nepřipomínejte si dřívější věci a dávnými věcmi se nezabývejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Hle, činím novou věc a už vzchází, což to nevíte? Ano, učiním v pustině cestu, v pusté krajině řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Bude mne ctít polní zvěř, šakali a pštrosi, neboť dám vodu v pustině a řeky v pusté krajině, abych dal pít svému lidu, svému vyvolenému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Ten lid jsem utvořil pro sebe: budou vypravovat moji chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Ale ty, Jákobe, jsi mne nevzýval, ⌈neboť jsi mnou unavený,⌉ Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Nepřivedl jsi mi ovci ke svým zápalným obětem, ani jsi mne nepoctil svými oběťmi. Nenutil jsem tě sloužit mi přídavnou obětí, ani jsem tě neunavoval kadidlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Nekoupil jsi mi za stříbro vonné koření, ani tukem svých obětí jsi mne neosvěžil. Avšak svými hříchy jsi mne nutil ti sloužit, unavoval jsi mne svými proviněními.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Já, já jsem ten, kdo mažu kvůli sobě tvá přestoupení a tvé hříchy připomínat nebudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Připomeň mi to a suďme se spolu: Ty vypočítej, proč bys měl být ospravedlněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Tvůj praotec zhřešil a tvoji prostředníci se proti mně vzbouřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Proto jsem znesvětil knížata svatyně, vydal jsem Jákoba do klatby a Izraele ke zhanobení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Ale nyní slyš, Jákobe, můj otroku, a Izraeli, jehož jsem vyvolil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Toto praví Hospodin, který tě učinil, který tě formoval od lůna matky a bude ti pomáhat: Neboj se, můj otroku Jákobe, a Ješúrúne, jehož jsem vyvolil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'neboť vyleji vody na žíznivého a bystřiny na suchou zemi; vyleji svého Ducha na tvé potomstvo, své požehnání na tvé potomky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'A budou vzcházet mezi trávou jako topoly u tekoucí vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Tento řekne: Jsem Hospodinův. A tenhle se nazve jménem Jákobovým. Tento napíše na svou ruku: Hospodinův a jako titul si dá jméno Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Toto praví Hospodin, král Izraele a jeho vykupitel, Hospodin zástupů: Já jsem první a já jsem poslední; kromě mne není žádný Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, '⌈Kdo jako já to může vyhlásit a oznámit?⌉ Ať to přede mnou seřadí od doby, kdy jsem postavil lid dávný! A věci přicházející, které teprve přijdou, ať jim oznámí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Nestrachujte se a nebuďte ochromeni! Což ti to odedávna nezvěstuji a neoznamuji? Vy jste mými svědky. Cožpak je Bůh kromě mne? Není jiná skála, o žádné nevím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Ti, kdo vytvářejí tesané modly, jsou všichni marnost a jejich vzácnosti jim neprospějí. Jsou jejich svědky: Nic nevidí ani nevědí -- jsou jim k zahanbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kdo by formoval boha nebo odlil modlu, když mu to nijak neprospěje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Hle, všichni jeho společníci se budou stydět. Řemeslníci jsou jen lidé. Ať se všichni shromáždí, ať se postaví. ⌈Budou se bát a stydět spolu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Kovář ⌈ dělá sekeru, pracuje s uhlím a formuje ji kladivy. Dělá to⌉ svou silnou paží, navíc hladoví, až je vysílený, nepije vodu a je unavený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Tesař roztáhl míru, vyznačuje modlu rudkou, upravuje ji dláty a kružidly ji vyznačuje. Zhotoví ji jako napodobeninu muže, jako krásného člověka, aby ji usadil v domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Pokácel si cedry nebo vzal cypřiš či dub, který si ⌈nechal vyrůst⌉ mezi lesními stromy. Vysadil vavřín a déšť mu dá vzrůst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Pak to je člověku k topení -- vzal z toho, aby se zahřál, také zatopí a napeče chléb; také udělá boha a bude se klanět: Zhotovil si tesanou modlu, aby se před ní rozprostíral tváří k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Polovinu toho spálil v ohni: Tedy na polovině upeče maso, sní pečeni a nasytí se. Také se zahřeje a řekne: Výborně, zahřál jsem se a ⌈užil jsem si tepla!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'A z toho, co zbylo, udělal boha, svoji tesanou modlu. Bude se před ní rozprostírat tváří k zemi, klanět se a modlit se k ní: Vysvoboď mě, protože jsi můj bůh!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Nic nevědí a ničemu nerozumějí, protože zalepil jejich oči, aby neviděli, a jejich srdce, aby nerozuměli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, '⌈Nepřijde mu to na mysl,⌉ nemá poznání ani rozum, aby si řekl: Polovinu toho jsem spálil v ohni, také jsem napekl na řeřavém uhlí chléb. Upeču maso a sním ho, ze zbytku mám zhotovit ohavnost a před dřevěným špalkem se mám rozprostírat tváří k zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Sytí se popelem, svedená mysl ho odklání stranou. Nevysvobodí svou duši ani si neřekne: Není to, co je v mé pravici, falešné?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Pamatuj si tyto věci, Jákobe, a Izraeli, vždyť jsi můj otrok; utvořil jsem tě, jsi můj otrok, Izraeli, ⌈ u mne nebudeš zapomenut.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Setřel jsem jako oblak tvá přestoupení a jako mračno tvé hříchy. Navrať se ke mně, neboť jsem tě vykoupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Výskejte, nebesa, protože Hospodin to učinil, hlaholte, útroby země, ať propuknou v jásot hory i les a všechny stromy v něm, protože Hospodin vykoupil Jákoba a na Izraeli ⌈zjeví svou slávu!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Toto praví Hospodin, tvůj vykupitel, a ten, který tě utvářel od lůna matky: Já jsem Hospodin, který činím všechno: Já sám ⌈roztahuji nebesa,⌉ ⌈kdo byl se mnou, když jsem rozprostíral zemi?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'On hatí znamení žvanilů a z věštců dělá potřeštěnce, moudré obrací nazpět a jejich poznání mění v bláznovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Naplňuje slovo svého otroka a vykoná radu svých poslů. O Jeruzalému říká: Bude obydlen, a o judských městech: Budou vybudována. Dám mu povstat z trosek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Mořské hlubině říká: Vyschni! Tvoje řeky vysuším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'O Kýrovi říká: Hle, můj pastýř. Vykoná celé mé přání a řekne o Jeruzalému: Bude vybudován, a o chrámu: Bude založen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Toto praví Hospodin o svém pomazaném, o Kýrovi, jehož uchopím za pravici, abych mu podrobil národy a ⌈rozvázal bedra králů,⌉ abych ⌈před ním⌉ otevřel vrata, takže brány nebudou zavřeny:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Já půjdu ⌈před tebou⌉ a hory vyrovnám, bronzová vrata rozlámu a železné závory odsekám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'A dám ti poklady temnoty a skryté zásoby z úkrytů, abys poznal, ⌈že jsem to já, Hospodin, který tě povolávám jménem, Bůh Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Kvůli svému otroku Jákobovi a kvůli Izraeli, svému vyvolenému, jsem tě povolal tvým jménem a dal jsem ti titul, ačkoliv mě neznáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Já jsem Hospodin a ⌈jiného není,⌉ kromě mě není Boha. Přepásám tě, ačkoliv mě neznáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'aby poznali od východu slunce ⌈i ti od [jeho] západu,⌉ že není nikoho mimo mě: Já jsem Hospodin a jiného není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Formuji světlo a tvořím tmu, činím pokoj a tvořím zlé; já, Hospodin, činím toto všechno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Vydejte, nebesa, krůpěje shůry a z oblaků ať plyne spravedlnost. Ať se otevře země a nese ovoce spásy a zároveň dá vyrůst spravedlnosti. Já, Hospodin, jsem to stvořil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Běda tomu, kdo vede spor se svým Tvůrcem, střep mezi střepy země! Což hlína řekne svému hrnčíři: Co to děláš! ⌈nebo: Tvé dílo nemá ruce?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Běda tomu, kdo říká otci: Co to plodíš? a ženě: Co to rodíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Toto praví Hospodin, Svatý Izraele a jeho Tvůrce: Na přicházející věci se mě vyptávejte! Ohledně mých synů, díla mých rukou, mi chcete přikazovat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Já jsem učinil zemi i člověka na ní jsem stvořil. Já -- mé ruce roztáhly nebesa -- a přikazuji celému jejich zástupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Já jsem ho vzbudil ve spravedlnosti a napřímím všechny jeho cesty. On vystaví mé město a mé vysídlence pošle domů, ne za peníze ani ne za dar, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Toto praví Hospodin: Výtěžek Egypta, zisk z obchodu Kúše i Sebajci, muži obrovití, k tobě přijdou a budou tvoji. Půjdou za tebou, přijdou v řetězech. Budou se ti klanět, k tobě se modlit: Jenom ⌈u tebe⌉ je Bůh a jiného není, bohové nejsou nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Přece ty jsi Bůh, který se skrývá, Bůh Izraele, zachránce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Stydí se a jsou všichni zahanbeni -- výrobci modlářských výtvorů s potupou společně odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Izrael je Hospodinem zachráněn věčnou spásou. Nebudete se stydět a nebudete zahanbeni na věky věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Neboť toto praví Hospodin, jenž stvořil nebesa, on je Bůh, který vytvořil zemi a připravil ji, on ji upevnil, nestvořil ji zbytečně, vytvořil ji k bydlení: Já jsem Hospodin a jiného není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nemluvil jsem tajně v temném místě země, neřekl jsem ⌈potomstvu Jákobovu zbytečně: Hledejte mě.⌉ Já, Hospodin, mluvím spravedlnost, oznamuji přímost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Shromážděte se a přijďte, přibližte se spolu, uprchlíci z národů! Ničemu nerozumějí ti, kdo nosí své dřevěné modly a modlí se k bohu, který nemůže zachránit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Oznamte a předložte fakta, jen ať se spolu poradí. Kdo to odedávna zvěstoval, odedávna to oznamoval? Zdali ne já, Hospodin? Vždyť není jiného Boha kromě mě. Jiný Bůh, spravedlivý a zachraňující, mimo mě není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Obraťte se ke mně a zachraňte se, všechny končiny země, protože já jsem Bůh a jiného není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Při sobě jsem přísahal, z mých úst vyšla spravedlnost, slovo, které se neodvrátí, že přede mnou klesne každé koleno, každý jazyk bude přísahat:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Jenom v Hospodinu, řekne, ⌈mám spravedlnost⌉ a sílu. ⌈Přijde až k němu, a všichni, kteří proti němu planou hněvem, se budou stydět.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'V Hospodinu budou ospravedlněni a jím se bude chlubit všechno potomstvo Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bél klesl, Nebó se sklání; jejich modlářské zpodobeniny byly na zvěři a na dobytku. ⌈Vaše zavazadla jsou naložena -- břemeno pro vyčerpané zvíře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Sklonili se a společně klesli, nemohli zachránit své břemeno a oni sami odešli do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Poslouchejte mne, dome Jákobův a celý pozůstatku domu izraelského, kteří jste nadnášeni od svého početí, kteří jste nošeni od svého zrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Až do vašeho stáří ⌈jsem tu já,⌉ až do šedin vás já ponesu. Já jsem udělal a já pozvednu, já budu nést a zachráním!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Ke komu mne připodobníte a komu mne postavíte na roveň, ke komu mne přirovnáte, abychom si byli podobni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Vytřásají z měšce zlato a na vahadle váží stříbro. Najmou zlatníka, aby z toho udělal boha, a pak se rozprostírají tváří k zemi a klaní se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Zvednou ho na ramena, nesou ho a položí ho na místo. Zůstane stát, ze svého místa se neodebere. I když k němu bude někdo úpěnlivě volat, on neodpoví, z jeho soužení ho nezachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, '⌈Pamatujte na to⌉ a buďte pevní, vezměte si to k srdci, vzpurníci!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Pamatujte na ty první věci odedávna, protože já jsem Bůh ⌈a jiného není, Bůh, a⌉ není nikdo jako já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Od počátku oznamuji budoucnost a od dávnověku, co se ještě nestalo. Říkám: Můj plán se naplní a každé své přání vykonám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Volám dravce od východu, muže podle svého úradku z daleké země. Ano, promluvil jsem, a také to naplním. Připravil jsem to, a také to učiním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Poslouchejte mne, vy tvrdohlavci, vzdálení od spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Přiblížil jsem svou spravedlnost, nebude daleko a má záchrana se neopozdí. Dám záchranu na Sijónu a pro Izrael svou slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Sestup a seď v prachu, ⌈panno, dcero babylonská,⌉ seď na zemi, žádný trůn, dcero chaldejská, protože tě již nebudou nazývat něžnou a zhýčkanou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Vezmi ruční mlýnek a mel mouku, odkryj závoj, zvedni vlečku, odhal stehna, přebroď řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Odhalí se tvá nahota, ano, ukáže se tvá potupa. Chopím se pomsty a ⌈nikdo mi nebude bránit. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Náš vykupitel, jehož jméno je Hospodin zástupů, Svatý Izraele [praví]:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Seď mlčky a vejdi do temnoty, dcero chaldejská, protože tě již nebudou nazývat královnou království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Rozhněval jsem se na svůj lid, znesvětil jsem své dědictví a vydal jsem je do tvé ruky; neprojevila jsi jim slitování, starce jsi velice obtížila jhem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Řekla sis: Budu královnou až navěky. Nevzala sis tyto věci k srdci a nepamatovalas na jejich konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Nuže, slyš toto, ty požitkářko sídlící v bezpečí, která si v srdci říkáš: Já, a mimo mne nikdo více. Nebudu sedět jako vdova, nepoznám ztrátu dětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Obě tyto věci na tebe přijdou náhle, v jednom dni, ztráta dětí i vdovství. Přijdou na tebe ve své plnosti pro množství tvých kouzel, pro velikou spoustu tvých zaklínadel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Spoléhala jsi na svou špatnost; řekla sis: Nikdo mne nevidí. Tvá moudrost a tvé poznání -- to tě zavedlo. Říkala sis ve svém srdci: Já, a mimo mne nikdo více.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Přijde na tebe zlo a ⌈nebudeš vědět, jak je uplatit,⌉ padne na tebe neštěstí a nebudeš je moci odvrátit. Náhle na tebe přijde zkáza, ani nepoznáš jak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Nuže, postav se se svými zaklínadly a s množstvím svých kouzel, do nichž jsi od mládí vkládala úsilí; snad budeš moci uspět, snad někoho postrašíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Jsi unavená množstvím svých plánů: ať se postaví a zachrání tě -- ti, kdo rozdělují nebesa, kteří čtou ve hvězdách a předpovídají podle novoluní -- ať tě zachrání od toho, co na tebe přijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Hle, jsou jako strniště, spálí je oheň; z moci plamene nevysvobodí ani sebe. Nejsou řeřavé uhlí k zahřátí, ani ohniště, aby před ním člověk poseděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Takoví budou k tobě ti, [do] nichž jsi vkládala úsilí. Od tvého mládí jsou ve tvé službě, každý bloudí ⌈svou cestou,⌉ není, ⌈ kdo by tě zachránil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Slyšte toto, dome Jákobův, totiž ti, kdo se nazývají Izraelovým jménem a vyšli z Judových beder, přísahají v Hospodinově jménu a připomínají Boha Izraele, avšak ne ⌈v pravdě ani ve spravedlnosti,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'ačkoliv se nazývají podle svatého města a opírají se o Boha Izraele -- Hospodin zástupů je jeho jméno:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Dřívější věci jsem odedávna oznámil, z mých úst vyšly a rozhlásil jsem je, náhle jsem způsobil, že přišly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Protože jsem věděl, že jsi zatvrzelý, šlacha železná je tvoje šíje a tvé čelo je bronzové,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'oznamoval jsem ti ty věci předem. Zvěstoval jsem ti je dříve, než přišly, abys neřekl: Mé zpodobení to učinilo, moje tesaná modla či má odlitá modla to přikázala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Slyšel jsi to a nyní na to všechno pohleď. A vy -- což to nebudete oznamovat? Způsobil jsem, že od nynějška uslyšíš nové věci, skryté, které jsi neznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Nyní byly stvořeny, nikoli dříve, dodnes jsi o nich neslyšel, abys neřekl: Hle, věděl jsem to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Neslyšel jsi, ani jsi nevěděl; tvé ucho nebylo dříve otevřeno, protože jsem věděl, že budeš stále jednat zrádně, vždyť vzbouřencem jsi byl nazván od matčina lůna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Kvůli svému jménu zdržuji svůj hněv a pro svou chválu se vůči tobě krotím, abych tě nevyhladil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Hle, přečistil jsem tě, ale ne jako stříbro, vyzkoušel jsem tě v peci soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Kvůli sobě, kvůli sobě samému to učiním, vždyť jak může být ⌈ [mé jméno] ⌉ znesvěcováno? Svou slávu jinému nedám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Slyš mě, Jákobe, Izraeli, můj povolaný. Já jsem, já jsem první, já jsem také poslední.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Ano, má ruka založila zemi a má pravice rozestřela nebesa; volám na ně a společně se postaví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, '⌈Shromážděte se, vy všichni, a slyšte:⌉ Kdo ⌈z nich⌉ oznámil tyto věci? Ten, kterého Hospodin miluje, vykoná jeho záměr s Babylonem ⌈a jeho paže bude na Chaldejcích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Já, já sám jsem promluvil a také jsem ho povolal. Přivedl jsem ho a dopřeji úspěch jeho cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Přistupte ke mně, slyšte toto: Od počátku jsem nemluvil tajně, od chvíle, kdy to nastalo, já jsem při tom. A nyní mne poslal Panovník Hospodin ⌈se svým Duchem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Toto praví Hospodin, tvůj ⌈vykupitel, Svatý Izraele:⌉ Já jsem Hospodin, tvůj Bůh, který tě vyučuje ke tvému prospěchu, který tě vodí cestou, po níž půjdeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Kéž bys pozorně naslouchal mým příkazům! Tvůj pokoj by byl jako řeka a tvá spravedlnost jako mořské vlny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'tvého potomstva by bylo jako písku, potomků z tvého lůna jako jeho zrnek; nebylo by vyhlazeno ani vyhubeno jeho jméno přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Vyjděte z Babylona, utečte od Chaldejců, se zvukem jásotu to oznamujte a rozhlašujte, přineste to až na konec země. Prohlašte: Hospodin vykoupil svého otroka Jákoba!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Neměli žízeň, když je vodil pustinami. Nechal pro ně prýštit vodu ze skály; rozdělil skálu a vytryskla voda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, '⌈Ničemové nemají pokoj, praví Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Poslechněte mne, ostrovy, dávejte pozor, daleké národy! Hospodin mne povolal ⌈ již v lůně,⌉ od nitra mé matky připomínal mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Učinil má ústa jako ostrý meč, ukryl mne ve stínu své ruky, učinil mne zaostřeným šípem, skryl mne ve svém toulci');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'a řekl mi: Ty jsi můj otrok, Izraeli, na němž zjevím svou slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Já jsem však řekl: Zbytečně jsem se namáhal, pro marnost a nicotnost jsem vyplýtval svou sílu, avšak mé právo je u Hospodina a má odměna u mého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'A nyní řekl Hospodin, který mě od lůna matky utváří za svého otroka, abych k němu navrátil Jákoba ⌈a aby pro něj byl shromážděn⌉ Izrael. Stal jsem se váženým v Hospodinových očích, můj Bůh se stal mou silou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'a řekl: Nestačí, abys byl mým otrokem k pozdvižení kmenů Jákobových a k navrácení zachovaných z Izraele, nýbrž dám tě za světlo národům, abys byl mou záchranou až na konec země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Toto praví Hospodin, vykupitel Izraele, jeho Svatý, tomu opovrženému, tomu, kterého si národ oškliví, otroku vládců: Králové tě uvidí a povstanou, i knížata, a budou se klanět kvůli Hospodinu, který je věrný, Svatému Izraele, který tě vyvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Toto praví Hospodin: Odpovím ti v čase přízně a pomůžu ti ve dni záchrany, budu tě opatrovat a dám tě za smlouvu lidu, abys pozdvihl zemi a znovu přidělil opuštěná dědictví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'abys řekl vězňům: Vyjděte, a těm, kteří jsou v temnotě: Ukažte se. Budou se pást podél cest a na všech holých návrších bude jejich pastva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Nebudou hladovět ani žíznit, nebude je ubíjet žhavý vítr ani slunce, protože je povede ten, kdo s nimi má soucit, a pomalu je povede ke zřídlům vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Všechny své hory proměním v cestu a mé silnice budou vyvýšeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Hle, tito přijdou zdaleka, hle, tito od severu a od západu, a tito ze země Siním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, '⌈Výskejte, nebesa,⌉ jásej, země, hory, propukněte v radostný křik, protože Hospodin potěšil svůj lid a nad svými zkroušenými se slituje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Ale Sijón říkal: Hospodin mě opustil, Panovník na mne zapomněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Cožpak může žena zapomenout na své miminko a nesmilovat se nad synem svého lůna? I když ony mohou zapomenout, já však na tebe nezapomenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Hle, vyryl jsem si tě do dlaní: tvé hradby jsou ustavičně přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Tvoji synové už pospíchají zpět, ti, kdo tě bořili a pustošili, od tebe odejdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, '⌈Rozhlédni se kolem a viz: Ti všichni se shromáždili a přišli k tobě.⌉ ⌈ Jakože jsem živ,⌉ je Hospodinův výrok, všechny si je oblékneš jako ozdobu a přivážeš si je jako nevěsta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Neboť tvé trosky, zpustošená místa a tvá pobořená země teď budou těsné pro množství obyvatel. A ti, kteří tě požírali, se vzdálí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Synové tvé bezdětnosti ti ještě budou říkat: To místo je mi těsné, přidej mi, abych se usídlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'V srdci si řekneš: Kdo mi tyto děti porodil? Vždyť jsem byla bezdětná a neplodná, vystěhovaná a zapuzená. A kdo je vychoval? Hle, já jsem zůstala samotná. Odkud jsou tito?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Toto praví Panovník Hospodin: Hle, pozdvihnu ruku k národům a pozvednu korouhev k lidem. A v náruči přinesou tvé syny a tvé dcery budou neseny na ramenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Králové budou tvými vychovateli a jejich kněžny tvými kojnými; budou se ti klanět tváří k zemi a prach tvých nohou budou lízat. I poznáš, že já jsem Hospodin, takže nebudou zahanbeni ti, kdo na mne očekávají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Cožpak lze vzít hrdinovi lup, či ⌈násilníkovi vychvátit zajatce?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Avšak toto praví Hospodin: I zajatec bude vzat hrdinovi a lup bude vychvácen násilníkovi. Tvému odpůrci budu já odporovat a tvé syny já zachráním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Tvé utiskovatele nakrmím jejich vlastním masem a opijí se vlastní krví jako sladkým vínem, a pozná veškeré tělo, ⌈že já jsem Hospodin, tvůj zachránce a vykupitel, Mocný Jákobův.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Toto praví Hospodin: Kde je rozlukový list vaší matky, jímž jsem ji propustil? Nebo kdo je tu z mých věřitelů, jemuž jsem vás prodal? Hle, pro své viny jste byli prodáni a pro vaše přestoupení byla propuštěna vaše matka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Proč jsem přišel a nikdo tu nebyl, volal jsem a nikdo neodpověděl? Což je má ruka příliš krátká na vykoupení? Nebo snad ve mně není síla k vysvobození? Hle, pouhou svou hrozbou vysušuji moře a řeky měním v pustinu, že jejich ryby páchnou z nedostatku vody a hynou žízní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Nebesa odívám ⌈ponurou temnotou⌉ a za oděv jim pokládám pytlovinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Panovník Hospodin mi dal jazyk učedníků, abych uměl unaveného podpírat slovem; ráno co ráno mi probouzí uši, abych slyšel jako učedníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Panovník Hospodin mi otevřel ucho a já jsem nebyl vzpurný. Zpět jsem neustoupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Svá záda nastavuji těm, kdo mě bijí, a své tváře ⌈těm, kdo rvou můj vous;⌉ tvář neskrývám před potupou a slinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Panovník Hospodin mi pomáhá, proto nebudu zahanben; proto jsem nastavil svou tvář jako křemen a vím, že se nebudu stydět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Blízko je ten, kdo mne ospravedlňuje, kdo se mnou povede při? Povstaňme spolu! Kdo bude mým žalobcem? Ať ke mně přistoupí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Hle, Panovník Hospodin mi pomáhá, kdo mě chce prohlásit vinným? Hle, ti všichni se obnosí jako oděv, sežere je mol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kdo se mezi vámi bojí Hospodina ⌈ a poslouchá⌉ hlas jeho otroka? Kdo chodí v temnotách a nemá žádnou zář, ať doufá v Hospodinovo jméno a spoléhá na svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Hle, vy všichni, kdo zapalujete oheň a zahalujete se jiskrami, choďte v jasu svého ohně a v jiskrách, které jste zapálili! Toto budete mít ode mne: Ulehnete do místa bolesti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Poslechněte mě, kdo usilujete o spravedlnost a hledáte Hospodina: Pohleďte na skálu, z níž jste vytesáni, a na hlubokou jámu, z níž jste vykopáni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Pohleďte na Abrahama, svého otce, a na Sáru, která vás v bolestech porodila. Neboť ⌈ byl sám, když jsem ho⌉ povolal, požehnal jsem mu a rozmnožil jsem ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Ano, Hospodin potěší Sijón, potěší všechny jeho trosky, jeho pustinu promění v zahradu Eden, jeho step v Hospodinovu zahradu. Bude se v něm nacházet veselí a radost, písně díků a zvuk prozpěvování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, '⌈Věnuj mi pozornost, můj lide, naslouchej mi, můj národe,⌉ protože ode mne vyjde zákon a náhle dám své právo za světlo národům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Má spravedlnost ⌈ je blízko,⌉ má záchrana vzejde a mé paže budou soudit národy. Na mne očekávají ostrovy a v mou paži skládají naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Pozvedněte své oči k nebesům a pohleďte na zemi dole, neboť nebesa se rozplynou jako kouř a země zvetší jako oděv a její obyvatelé právě tak zemřou; moje záchrana však zůstane navěky a moje spravedlnost nepomine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Slyšte mne vy, kdo znáte spravedlnost, lide, v jehož srdci je můj zákon: Nebojte se lidského posměchu, jejich hanobení se neděste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Vždyť je sežere mol jako oděv, červi je sežerou jako vlnu, ale má spravedlnost zůstane navěky a má záchrana ⌈z generace na generaci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, '⌈Probuď se, probuď,⌉ oděj se silou, Hospodinova paže, probuď se jako za dávných dnů, odvěkých generací! Což jsi to nebyla ty, která jsi rozrazila obludu a probodla draka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Což jsi to nebyla ty, která jsi vysušila moře, velikou vodní hlubinu a učinila mořské hloubky cestou, aby prošli vykoupení?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Hospodinovi vykoupení se navrátí, přijdou s výskáním na Sijón a věčná radost bude na jejich hlavách. Dojdou veselí a radosti, žal a vzdychání utečou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Já, já jsem váš utěšitel. Kdo jsi ty, že se bojíš člověka, který umírá, a lidského syna, který dopadá jako tráva?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Zapomínáš na Hospodina, který tě učinil, který roztáhl nebesa a založil zemi, a stále po celý den se chvěješ strachem před zlobou utiskovatele, protože se připravil působit zkázu. A kdepak je nyní ta jeho zloba?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Spoutaný vězeň bude rychle uvolněn, nezemře v jámě a nebude mít nedostatek chleba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Já jsem Hospodin, tvůj Bůh, který vzdouvá moře, až jeho vlny burácejí -- jeho jméno je Hospodin zástupů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Svá slova jsem vložil do tvých úst a přikryl jsem tě stínem své ruky, abys sázel nebesa a založil zemi a řekl Sijónu: Ty jsi můj lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Probuď se, probuď, povstaň dcero Jeruzaléma, která jsi vypila z Hospodinovy ruky kalich jeho zloby, do dna jsi vypila kalich závrati.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Není, kdo by ji opatrně vedl, ze všech dětí, které porodila; není, kdo by ji držel za ruku, ze všech synů, které vychovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Tyto dvě rány tě potkaly, kdo ti projeví účast? Zkáza a pohroma, hlad a meč. Kdo tě potěší?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tvoji synové leží bezvládně na všech nárožích jako ⌈divoká ovce⌉ v síti; jsou nasyceni Hospodinovou zlobou, napomenutím tvého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Proto nyní slyš toto, zkroušená a opilá, ale ne vínem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Toto praví tvůj Panovník Hospodin, tvůj Bůh, který vede při svého lidu: Hle, beru z tvé ruky kalich závrati, kalich své zloby; už ho nebudeš více pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Vložím ho do ruky těm, kdo tě skličovali, kteří říkali tvé duši: Sehni se, ať přejdeme. A pokládala jsi svá záda jako zemi, jako ulici pro ty, kdo procházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, '⌈Probuď se, probuď,⌉ oděj se silou, Sijóne, oděj se svými skvostnými rouchy, Jeruzaléme, město svaté, protože již nikdy do tebe nevejde neobřezaný ani nečistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Otřes se z prachu, povstaň, ⌈usídli se,⌉ Jeruzaléme, rozvaž pouta na své šíji, zajatá dcero sijónská!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Neboť toto praví Hospodin: Zadarmo jste byli prodáni, ⌈nikoli za stříbro⌉ budete koupeni zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Neboť toto praví Panovník Hospodin: Nejprve můj lid sestoupil do Egypta, aby tam pobýval jako cizinec, ale Ašúr ho bezdůvodně utlačoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Nuže, co tu mám? je Hospodinův výrok. Vždyť můj lid byl vzat zadarmo a jeho vládci ⌈ jej přivádějí k nářku,⌉ je Hospodinův výrok, a mým jménem je ustavičně po celý den pohrdáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Jistě můj lid pozná moje jméno, ⌈jistě je pozná,⌉ neboť v onen den ⌈já budu ten, kdo bude říkat: Zde jsem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Jak příhodné jsou na horách nohy toho, kdo přináší novinu, kdo zvěstuje pokoj, kdo přináší dobrou novinu, kdo zvěstuje záchranu a kdo říká Sijónu: Tvůj Bůh se ujal kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Slyš! Tví strážní pozvedli hlas, společně jásají. Vždyť ⌈tváří v tvář⌉ uvidí, jak se Hospodin vrací na Sijón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Propukněte společně v jásot, jeruzalémské trosky, protože Hospodin potěšil svůj lid, vykoupil Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Hospodin obnažil svou svatou paži před očima všech národů a všechny končiny země uvidí záchranu našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Pryč, pryč, vyjděte odtud, nečistého se nedotýkejte! Vyjděte z jeho středu, očistěte se, kdo nosíte Hospodinovy nádoby!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Avšak nemusíte vycházet ve spěchu, ani nemusíte utíkat, protože před vámi půjde Hospodin a váš průvod bude uzavírat Bůh Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Hle, můj otrok ⌈bude mít úspěch,⌉ bude vyvýšen, povznesen a velice zveleben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Tak jako mnozí se nad ním zhrozí -- tak nelidsky zohaven bude jeho vzhled, jeho vzezření nepodobné lidským synům --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'tak ⌈přivede v úžas⌉ mnohé národy. Králové kvůli němu zavřou svá ústa, protože uvidí to, co jim nebylo vyprávěno, a pochopí to, o čem neslyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, '⌈Kdo by jen uvěřil zprávě, kterou jsme slyšeli?⌉ A při kom se zjevila Hospodinova paže?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Vyrostl před ním jako výhonek a jako kořen z vyprahlé země. Neměl vzezření ani důstojnost, abychom na něho hleděli s úctou, ani vzhled, ⌈abychom po něm toužili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Opovržený a ⌈lidmi zavržený,⌉ muž bolestí, který znal nemoci; ⌈jako někdo, před nímž člověk skryje tvář⌉ -- všemi opovržený, takže jsme si ho nevážili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Jenže to byly naše nemoci, které snášel, a naše bolesti, které nesl; a my jsme si o něm mysleli, že je zasažen a ubit Bohem a zkrušen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Ale on byl proboden za naše přestoupení, zdeptán za naše provinění, na něho dolehla kázeň pro náš pokoj a jeho šrámy jsme uzdraveni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'My všichni jsme zabloudili jako ovce, jeden každý jsme se obrátili na svou cestu, a Hospodin na něho nechal dopadnout vinu nás všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Byl ⌈zdrcen, ale pokořil se a⌉ neotevřel ústa: jako beránek vedený na porážku a jako ovce před střihači byl němý, ústa neotevřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, '⌈Skrze útlak a soud byl vzat,⌉ ⌈kdo se bude zabývat jeho údělem?⌉ Neboť byl vyťat ze ⌈země živých,⌉ jeho rána přišla za přestoupení mého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'A určili mu hrob mezi ničemy, ale byl s bohatým ve své smrti, protože se nedopustil násilí a v jeho ústech nebylo lsti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Hospodin si přál zdeptat ho nemocí: Když položí svou duši jako oběť za vinu, uvidí potomstvo, prodlouží své dny, a Hospodinovo přání se jeho prostřednictvím zdaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Z námahy své duše uvidí ovoce a nasytí se. Svým poznáním můj spravedlivý otrok ospravedlní mnohé a jejich provinění on sám ponese.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Proto ⌈mu dám podíl ve velikých zástupech a s nespočetnými bude dělit kořist,⌉ protože vylil na smrt svou duši a byl započten mezi vzpurné. On odnesl hřích mnohých a je přímluvcem za vzpurné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Výskej, neplodná, ty, která jsi nerodila, propukni v radostný křik a jásej, ty, která ses nesvíjela bolestí, protože více bude synů opuštěné nežli synů provdané, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Rozšiř místo svého stanu, roztáhni celty svých příbytků, nedrž se zpět! Prodluž svá lana a upevni své kolíky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Protože se rozhojníš napravo i nalevo a tvé potomstvo zdědí národy a osídlí zpustošená města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Neboj se, protože se nebudeš stydět, neostýchej se, protože nebudeš zahanbena. Neboť zapomeneš na hanbu svého mládí a na potupu svého vdovství již nevzpomeneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Vždyť tvým manželem je tvůj Tvůrce, jeho jméno je Hospodin zástupů, a tvým vykupitelem je Svatý Izraele -- nazývá se Bohem vší země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Neboť Hospodin tě povolal jako ženu propuštěnou a ztrápenou, ⌈ženu mládí,⌉ když byla zavržena, praví tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Na malou chvíli jsem tě opustil, ale ve velikém slitování tě shromáždím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'V návalu rozhořčení jsem před tebou na chvíli skryl svou tvář, avšak ve věčném milosrdenství se nad tebou slituji, praví tvůj vykupitel Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, '⌈Vždyť je to pro mne jako při vodách Noeho,⌉ kdy jsem přísahal, že už vody Noeho nezaplaví zemi. Tak jsem přísahal, že se na tebe nerozlítím, ani že tě neokřiknu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Neboť hory mohou ustoupit a kopce se otřást, ale mé milosrdenství od tebe neustoupí a má smlouva pokoje se neotřese, praví tvůj slitovník, Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Zkroušená, bouří zmítaná, která jsi nedošla potěšení, hle, já uložím v antimonu tvé kameny a tvé základy položím na safírech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Tvá cimbuří učiním z rubínu, tvé brány z berylů a celé tvé ohraničení z drahých kamenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Všichni tvoji synové budou Hospodinovými učedníky a ⌈hojný bude pokoj tvých synů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Budeš upevněna spravedlností. Jistě budeš vzdálena od útlaku, neboť se nebudeš bát, a od zkázy, neboť se k tobě nepřiblíží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Hle, kdo se proti tobě srotí, srotí se beze mne. Kdo se proti tobě srotí, kvůli tobě padne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Hle, já jsem stvořil kováře, který rozdmýchává z uhlí oheň a vytváří ⌈nástroj pro⌉ své dílo, a já jsem stvořil ničitele, aby hubil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Žádný nástroj vytvořený proti tobě neuspěje a každý jazyk, který povstane proti tobě na soudu, usvědčíš z viny. Toto je dědictví Hospodinových otroků, jejich spravedlnost ode mne, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Aj, všichni žízniví, pojďte k vodám, i ten, kdo nemá peníze. Pojďte, kupujte a jezte, pojďte, kupujte bez peněz a bez úhrady víno a mléko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Proč vydáváte peníze za to, co není chléb, a svůj výdělek za to, co není k nasycení? Bedlivě mě poslouchejte a budete jíst dobré věci, vaše duše si bude libovat v tuku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Nakloňte ucho a ⌈pojďte ke mně,⌉ poslouchejte a vaše duše ožije. Uzavřu s vámi věčnou smlouvu -- spolehlivá milosrdenství zaslíbená Davidovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Hle, ustanovil jsem ho za svědka národů, za předáka a správce národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Hle, národy, které neznáš, povoláš, a národy, které tebe neznaly, k tobě poběží; kvůli Hospodinu, tvému Bohu, pro Svatého Izraele, neboť tě oslavil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, '⌈Hledejte Hospodina,⌉ dokud se dává najít, volejte ho, dokud je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Ať ničema opustí svou cestu a zlý člověk své úmysly, ať se navrátí k Hospodinu, a on se nad ním slituje -- k našemu Bohu, protože je připraven mnoho odpustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Vždyť moje myšlení nejsou myšlení vaše, ani vaše cesty nejsou cesty mé, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Neboť jako jsou nebesa ⌈vyšší než země,⌉ tak jsou mé cesty vyšší než cesty vaše a má myšlení vyšší než myšlení vaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Tak jako déšť či sníh padá z nebe a nevrací se tam zpět, nýbrž zavlažuje zemi a činí ji plodnou a úrodnou -- dává zrno tomu, kdo rozsévá, a chléb tomu, kdo jí --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'tak bude mé slovo, které vyjde z mých úst: Nenavrátí se ke mně s prázdnou, nýbrž vykoná to, co si přeji, a zdárně dokáže to, k čemu ho pošlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Neboť s radostí vyjdete a budete vedeni v pokoji. Hory a návrší před vámi propuknou v jásot a všechny stromy na poli budou tleskat rukama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Namísto křoviny vyroste cypřiš a místo plevele vyroste myrtoví. Bude to k Hospodinovu věhlasu jako věčné znamení, které nebude zmařeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Toto praví Hospodin: Zachovávejte právo a ⌈jednejte spravedlivě,⌉ protože brzy přijde má záchrana a bude zjevena má spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Blahoslavený je člověk, který to činí, a lidský syn, který se toho drží; který zachovává sobotu před znesvěcením a střeží svou ruku před pácháním čehokoliv zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Ať neříká cizinec, který se připojuje k Hospodinu: Hospodin mě jistě oddělí od svého lidu. A eunuch ať neříká: Hle, jsem suchý strom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Neboť toto praví Hospodin o eunuších, kteří zachovávají mé soboty, zvolili si to, v čem mám zalíbení, a drží se pevně mé smlouvy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Dám jim ve svém domě a mezi svými hradbami ⌈místo a jméno⌉ lepší než synů a dcer, dám jim věčné jméno, které nebude zmařeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Také cizince, kteří se připojují k Hospodinu, aby mu sloužili a aby milovali Hospodinovo jméno, aby byli jeho otroky, kteří všichni zachovávají sobotu před znesvěcením a drží se pevně mé smlouvy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'ty přivedu na svou svatou horu a rozradostním je ve svém domě modlitby; jejich zápaly a jejich oběti budou vystupovat pro zalíbení nad mým oltářem. Vždyť můj dům se bude nazývat domem modlitby pro všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Výrok Panovníka Hospodina, který shromažďuje zapuzené Izraelovy: Ještě mu k jeho shromážděným shromáždím další.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Přijďte se nažrat, všechna polní zvěři, všechna zvěři lesní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Všichni ⌈jeho strážní⌉ jsou slepí, nic nevědí; všichni jsou němí psi, neumějí štěkat. Hekají, leží, milují dřímotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Ale jsou to psi hltaví, neznají nasycení. A to jsou pastýři! Nemají porozumění. Všichni se obrátili na svou cestu, ⌈všichni bez výjimky⌉ k svému nekalému zisku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Říkají: Přijďte, přinesu víno, zpijeme se pivem a zítřejší den bude jako tento a ještě mnohem větší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Spravedlivý hyne a nikdo ⌈si to nebere k srdci.⌉ ⌈Zbožní lidé⌉ ⌈jsou bráni pryč,⌉ a přitom není, kdo by rozuměl, že ⌈před příchodem zla⌉ je spravedlivý vzat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Ten, kdo ⌈žije správně,⌉ dojde pokoje, odpočine na svém loži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Ale vy přistupte sem, synové věštkyně, potomstvo cizoložníka a nevěstky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Z koho si děláte legraci, na koho si otvíráte ústa a vyplazujete jazyk? Což nejste vy děti vzpoury a potomstvo klamu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Vy, kteří se rozpalujete modloslužbou mezi duby, ⌈pod každým zeleným stromem⌉ a pobíjíte děti u potoků ⌈pod skalními převisy?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Mezi hladkými potočními kameny je tvůj podíl, ano, ty jsou tvým údělem. Dokonce jsi jim vylévala litou oběť, přinášela přídavnou oběť. Cožpak se z těchto věcí potěším?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Na vysokou a vyvýšenou horu jsi umístila své lože. A tam jsi vystoupila obětovat svou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'A za dveře a veřeje jsi umístila své znamení. Ano, opustila jsi mne a vyšla jsi nahoru, rozšířila jsi své lože a ⌈koupila sis od nich přízeň.⌉ Zamilovala sis jejich lože, viděla jsi jejich moc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Putovala jsi ke králi s olejem, připravila sis mnoho vonných mastí, posílala jsi do daleka posly a ponížila ses až do podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Unavila ses množstvím svých cest, ale neřekla jsi: ⌈Je to zbytečné.⌉ Nalezla jsi život ve své moci, proto jsi nezeslábla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Koho ses obávala a před kým jsi měla strach, že jsi lhala, na mne jsi nepamatovala a nevzala sis to k srdci? Mlčel jsem příliš dlouho. Proto se mě nebojíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Já oznámím tvou spravedlnost a tvé skutky, ale neprospějí ti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Když budeš volat o pomoc, ať tě vysvobodí tvé sbírky model; všechny je odnese vítr a sebere vánek. Ale ten, kdo má útočiště ve mně, zdědí zemi a obsadí mou svatou horu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'A řekne: Navršte, navršte násep, připravte cestu, zvedněte každou překážku z cesty mého lidu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Toto praví Vznešený a Vyvýšený, který přebývá ve věčnosti a jehož jméno je Svatý: Bydlím na vysokém a svatém místě, i s tím, kdo má zdeptaného a poníženého ducha, abych oživoval ducha ponížených a abych oživoval srdce zdeptaných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Vždyť nebudu navěky vést při, ani se nebudu hněvat navždy, protože jinak by duch přede mnou zemdlel, i dech všeho, co jsem učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Pro jeho ⌈zvrácenou zištnost jsem se⌉ rozhněval a bil jsem ho, ukryl jsem se a hněval jsem se, ale on šel odvrácen dál cestou svého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Viděl jsem jeho cesty a uzdravím ho. Povedu ho a odplatím mu útěchou. Jeho truchlícím');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'stvořím ovoce rtů. Pokoj, pokoj dalekému i blízkému, praví Hospodin, a uzdravím ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Ale ničemové budou jako vzedmuté moře, když se nemůže utišit, jehož vody vyvrhují špínu a bláto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Ničemové nemají pokoj, praví můj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Volej z plna hrdla, bez zábran; pozdvihni svůj hlas jako beraní roh a oznam mému lidu jejich přestoupení a domu Jákobovu jejich hříchy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Den co den se mě dotazují a mají zalíbení v poznání mých cest jako národ, který koná spravedlnost a neopouští právo svého Boha. Doptávají se mě na spravedlivá rozhodnutí, mají zalíbení v Boží blízkosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Proč, když se postíme, ty to nevidíš, pokořujeme svou duši, a ⌈ ty o tom nevíš?⌉ Hle, v den svého půstu si hledíte svých zájmů a utlačujete všechny své dělníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Hle, postíte se jen ke sporům a hádkám a abyste bili ničemnou pěstí. Nepostěte se tak jako dnes, má–li být na výšině slyšet váš hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Což je toto půst, který si přeji, a den, kdy člověk pokořuje svou duši? Aby svěsil hlavu jako rákos a podestlal si pytlovinu a popel? Toto chceš nazývat postem a dnem, který je Hospodinu milý?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Toto je půst, který si přeji: Rozvázat ⌈pouta ničemnosti,⌉ uvolnit řemeny jha a propustit utlačované na svobodu, zpřetrhat každé jho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, '⌈Když budeš⌉ lámat hladovému svůj chléb a chudé bezdomovce přivedeš do domu, když uvidíš nahého, zakryješ ho a vůči vlastnímu tělu a krvi nebudeš lhostejný,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'tehdy tvé světlo vytryskne jako rozbřesk a rychle vzejde tvé uzdravení; před tebou půjde tvá spravedlnost a ⌈za tebou půjde⌉ Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Tehdy zavoláš a Hospodin odpoví, budeš křičet o pomoc a řekne: Zde jsem; jestliže odstraníš ze svého středu jho, ukazování prstem a mluvení zla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Poskytneš– li ze svého hladovému a strádajícího nasytíš, v temnotě vyjde tvé světlo a tvůj soumrak bude jako poledne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'A Hospodin tě povede ustavičně, nasytí tvou duši i na vyprahlých místech a dodá svěžesti tvým kostem. Budeš jako zavlažovaná zahrada a jako vodní zdroj, jehož voda nebude vysychat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, '⌈ Ti, kteří z tebe vyjdou, vybudují⌉ odvěké trosky, upevníš ⌈základy, které trvaly z generace na generaci.⌉ A nazvou tě tím, kdo zazdívá trhliny a obnovuje stezky ⌈k obydlím.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Jestliže odvrátíš svou nohu od pošlapávání soboty, od konání svých zálib v můj svatý den, a nazveš sobotu rozkošnou a svatý den Hospodinův ctihodným a budeš ho ctít tak, že nebudeš konat své cesty, nebudeš hledat své záliby a mluvit planá slova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'potom budeš mít rozkoš v Hospodinu a ⌈nechám tě jezdit na návrších země⌉ a ⌈budu tě krmit dědictvím⌉ tvého otce Jákoba, neboť ústa Hospodinova promluvila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Hle, Hospodinova ruka není krátká, že by nezachránil, ani jeho ucho není zalehlé, že by neslyšel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'nýbrž vaše zvrácenosti se staly hradbou mezi vámi a vaším Bohem a vaše hříchy skryly jeho tvář před vámi, aby neslyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Vždyť vaše ruce jsou poskvrněné krví a vaše prsty zvráceností. Vaše rty mluví klam a váš jazyk opakuje zvrácenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Nikdo ⌈nevolá po spravedlnosti⌉ a nikdo se nesoudí pravdivě. Spoléhají na marnost a mluví klam, ⌈počnou trápení⌉ a zplodí špatnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Vyseděli zmijí vejce a spřádají pavoučí vlákna. Kdo z jejich vajec jí, umírá, a když se některé rozmáčkne, vyrazí z něj zmije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Jejich vlákna se nehodí na oděv a svými výtvory se nepřikryjí. Jejich díla jsou díla špatnosti a v jejich rukou je skutek násilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, '⌈Jejich nohy běží za zlem, pospíchají prolévat nevinnou krev.⌉ Jejich úmysly jsou úmysly zlé, na jejich silnicích číhá zkáza a pohroma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Cestu pokoje neznají, právo není na jejich stezkách. Své pěšiny si pokřivili, žádný, kdo po nich kráčí, nezná pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Proto se od nás právo vzdálilo a spravedlnost nás nedostihuje. Čekáme na světlo a hle, temnota, na úsvit, a chodíme v hluboké tmě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Jako slepí ohmatáváme stěnu, hmatáme jako bychom neměli oči. V poledne klopýtáme jako za soumraku, ⌈mezi zdatnými⌉ jsme jako mrtví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Všichni bručíme jako medvědi a stále lkáme jako holubice, čekáme na právo, ale není, na záchranu, ale je od nás daleko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Protože našich přestoupení před tebou je mnoho a naše hříchy svědčí proti nám. Naše přestoupení jsou s námi, i naše provinění, známe je:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Vzpírání se a lhaní proti Hospodinu, odstoupení od našeho Boha, mluvení o útlaku a vzpouře, vymýšlení lživých slov a jejich vypouštění ze srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Právo je potlačeno a spravedlnost zůstává daleko, ano, na náměstí klopýtá pravda a to, co je správné, nemůže vejít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Pravdy se nedostává, kdo se odvrací od zla, bývá vykořistěn. Hospodin to vidí a je zlé v jeho očích, že není právo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'A viděl, že není nikoho, a užasl, že není přímluvce. Záchranu mu tedy poskytla jeho paže a jeho spravedlnost, ta ho podepřela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Oděl si spravedlnost jako pancíř a přilba záchrany je na jeho hlavě. Roucho pomsty si vzal jako oděv a horlivostí se zahalil jako pláštěm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Podle činů odplatí zlobou svým protivníkům, odplatou svým nepřátelům. Ostrovům odplatí podle toho, co vykonaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'A budou se bát Hospodinova jména na západě a na východě slunce jeho slávy, když přijde ⌈jako vzedmutá řeka, kterou požene⌉ Hospodinův Duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'A na Sijón přijde vykupitel -- k těm, kdo se v Jákobovi odvrátí od přestoupení, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Co se mne týče, toto je moje smlouva s nimi, praví Hospodin: Můj Duch, který je na tobě, a moje slova, která jsem vložil do tvých úst, se nevzdálí od úst tvých ani od úst tvého potomstva ani od úst potomstva tvého potomstva, praví Hospodin, od nynějška až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Povstaň, rozjasni se, protože přišlo tvé světlo a vzešla nad tebou Hospodinova sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Neboť hle, tma přikryje zemi a hustá temnota národy, ale nad tebou zazáří Hospodin a bude nad tebou vidět jeho sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'A národy ⌈půjdou ke tvému světlu a králové k⌉ záři tvého svítání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, '⌈Rozhlédni se kolem a viz: Ti všichni se shromáždili a přišli k tobě.⌉ Tvoji synové přijdou zdaleka a tvé dcery budou ⌈chovány po tvém boku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Tehdy to uvidíš a budeš zářit, tvé srdce se zachvěje a rozšíří, protože se k tobě obrátí bohatství moře, přijde k tobě majetek národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Přikryje tě spousta velbloudů; mladí velbloudi z Midjánu a Éfy, všichni přijdou ze Šeby, ponesou zlato a kadidlo a budou zvěstovat Hospodinovy ⌈slavné skutky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Všechna stáda Kédaru se k tobě shromáždí, nebajótští berani ti budou sloužit. Přinesou libou oběť na mém oltáři a já oslavím svůj slavný dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kdo jsou ti, kteří se slétají jako oblak a jako holubice ke svým holubníkům?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, '⌈Vždyť na mne očekávají ostrovy⌉ a taršíšské lodě ⌈ jsou první,⌉ aby zdaleka přivezly tvé syny a s nimi jejich stříbro a zlato ke jménu Hospodina tvého Boha a k Svatému Izraele, protože tě oslavil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Cizinci postaví tvé hradby a jejich králové ti budou sloužit. Vždyť ve svém rozhořčení jsem tě pobil, ale ve své přízni jsem se nad tebou slitoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Tvé brány budou ustavičně otevřeny, ve dne ani v noci nebudou zavírány, aby k tobě byl přinášen majetek národů a aby byli přiváděni i jejich králové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Protože národ nebo království, jež ti nebude sloužit, zahyne. Tyto národy naprosto zpustnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'K tobě přijde sláva Libanonu -- ⌈cypřiš a jilm spolu se zimostrázem⌉ -- k ozdobení místa mé svatyně; oslavím místo svých nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Pokořeni k tobě půjdou synové těch, kdo pokořovali tebe, a budou se sklánět k chodidlům tvých nohou všichni, kdo tebou pohrdali. A nazvou tě Městem Hospodinovým, Sijónem Svatého Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Místo toho, abys byl opuštěný a nenáviděný a nikdo tebou neprocházel, proměním tě ve věčnou vznešenost, ve veselí z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'A budeš sát mléko národů, budeš sát z královských prsů a poznáš, že já jsem Hospodin, tvůj zachránce a tvůj vykupitel, Mocný Jákobův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Místo bronzu přinesu zlato a místo železa přinesu stříbro, místo dřeva bronz a místo kamení železo. Za tvého dohližitele ustanovím pokoj a za tvé nadřízené spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Ve tvé zemi již nebude slyšet o násilí, na tvém území o ⌈zkáze a pohromě.⌉ Své hradby nazveš záchranou a své brány chválou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nebude ti již slunce za světlo ve dne, ani měsíc pro svou zář ti nebude svítit v noci. Hospodin bude tvým věčným světlem a tvůj Bůh tvou slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Tvé slunce již nezapadne a tvůj měsíc se neschová, protože Hospodin bude tvým věčným světlem a dny tvého smutku skončí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'A tvůj lid -- všichni budou spravedliví -- obdrží navěky zemi. Bude to výhonek mé setby, ⌈dílo mých rukou,⌉ abych byl oslaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Z nejmenšího vzejde tisíc a z nejnepatrnějšího mocný národ. Já Hospodin to v pravý čas uspíším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Duch Panovníka Hospodina je na mně, protože mne Hospodin pomazal. Poslal mne přinášet radostnou novinu pokorným, ovázat rány zlomeným v srdci, vyhlásit zajatcům propuštění a ⌈vězňům otevření žaláře;⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'vyhlásit rok Hospodinovy přízně a den pomsty našeho Boha; potěšit všechny truchlící;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'zajistit pro truchlící na Sijónu, aby jim byla dána čelenka místo popela, olej veselí místo truchlení, závoj chvály místo ducha malomyslnosti. Budou nazváni: Duby spravedlnosti, setba Hospodinova, aby byl oslaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Oni ⌈vybudují odvěké trosky,⌉ dají povstat místům od počátku opuštěným, obnoví zpustlá města, opuštěná z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Cizinci povstanou a budou pást vaše stáda a synové cizozemce budou vašimi oráči a vašimi vinaři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'A vás budou nazývat Hospodinovými kněžími, budou vám říkat služebníci našeho Boha. Budete užívat majetek národů a jejich slávou se budete chlubit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Místo své dvojnásobné hanby, a protože volali: Potupa je jejich podíl!, obdrží ve své zemi dvojnásobný podíl a bude jim patřit věčná radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Neboť já, Hospodin, miluji právo a nenávidím ⌈podlou loupež.⌉ Dám jim věrně jejich odměnu a uzavřu s nimi věčnou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Jejich potomstvo bude známé mezi národy a jejich potomci uprostřed lidí. Všichni, kdo je uvidí, uznají, že oni jsou potomstvem, které požehnal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Velice se budu veselit v Hospodinu, má duše bude jásat v mém Bohu, protože mne oděl rouchem záchrany, zahalil mne pláštěm spravedlnosti. Jsem jako ženich, který má kněžský turban, jako nevěsta, která se zdobí svými předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Neboť jako země nechává vzejít svůj výhonek a jako zahrada dává vyrůst své setbě, tak Panovník Hospodin dá vyrůst spravedlnosti a chvále přede všemi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Kvůli Sijónu nebudu zticha a kvůli Jeruzalému nebudu mít klid, dokud jeho spravedlnost nevzejde jako záře a jeho záchrana nevzplane jako pochodeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Národy uzří tvou spravedlnost a všichni králové tvou slávu a budou tě nazývat novým jménem, které určí Hospodinova ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'A budeš skvostnou korunou v Hospodinově ruce a královským turbanem v dlani svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Již se o tobě nebude říkat: Opuštěná a o tvé zemi se již nebude říkat: Pustá, ale budeš nazývána: ⌈Mám v ní zalíbení⌉ a tvá země: Provdaná, protože Hospodin bude mít v tobě zalíbení a tvá země bude mít manžela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Neboť jako se žení mládenec s pannou, ožení se ⌈tvoji synové⌉ s tebou a radostí ženicha z nevěsty se z tebe bude radovat tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Na tvých hradbách, Jeruzaléme, jsem ustanovil strážce, po celý den i celou noc nikdy nebudou zticha. Vy, kteří připomínáte Hospodina, ne dopřávejte si klidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Ani jemu nedopřejte klidu, dokud Jeruzalém neupevní a dokud ho neučiní na zemi slavným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Hospodin ⌈přisáhl svou pravicí⌉ a svou mocnou paží: Nedám již tvé obilí za potravu tvým nepřátelům, ani nebudou synové cizozemce pít tvé nové víno, na němž ses namáhal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Neboť je sklidí, budou je jíst a budou chválit Hospodina. Shromáždí je a budou je pít na mých svatých nádvořích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Projděte, projděte branami! Připravte cestu pro lid! ⌈Navršte, navršte⌉ silnici, odstraňte kamení! Pozvedněte korouhev pro národy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Hle, Hospodin rozhlásil do končin země: Řekněte dceři sijónské, hle, tvůj zachránce přichází! Hle, jeho mzda je s ním a jeho odměna před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'A nazvou je: Lid svatý, Hospodinovi vykoupení; a ty budeš nazvána: Vyhledávaná, ⌈Město neopuštěné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kdo to přichází z Edómu, v rudém rouchu z Bosry? Kdo je ten velebný ve svém oděvu, který kráčí ve své velké síle? Já, který ⌈mluvím spravedlivě, mocný k záchraně.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Proč je tvůj oděv krvavě rudý a tvé roucho jako toho, kdo šlape v lisu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'V kádi vinného lisu jsem šlapal sám a nikdo z národů se mnou nebyl. Šlapal jsem je ve svém hněvu a pošlapal jsem je ve své zlobě. Jejich šťáva stříkala na mé roucho, celý oděv jsem si poskvrnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Neboť ⌈v mém srdci byl ⌉ den pomsty a přišel rok mého vykoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Ohlédl jsem se a nebylo pomocníka, užasl jsem, že není opory. Záchranu mi poskytla vlastní paže a má zloba, ta mne podepřela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Ve svém hněvu jsem pošlapal národy a ⌈opil jsem je svou zlobou.⌉ Jejich šťávu jsem vyléval na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Budu připomínat Hospodinovy milosrdné činy, Hospodinovy slavné skutky -- za všechno, co nám Hospodin prokázal; prokázal domu Izraele mnoho dobrého, prokázal jim to podle svého slitování a podle svého hojného milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'I řekl: Zajisté jsou mým lidem, syny, kteří nebudou lhát. A stal se ⌈jejich zachráncem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'V každém jejich soužení měl soužení i on. Anděl jeho přítomnosti⌉ je zachraňoval. On je ve své lásce a ve svém soucitu vykoupil. Zvedal je a nosil je po všechny dávné dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Ale oni byli vzpurní a zarmucovali jeho svatého Ducha. Tedy se jim změnil v nepřítele a sám proti nim bojoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, '⌈Ale jeho lid si připomenul dávné dny Mojžíše:⌉ Kde je ten, kdo je vyvedl z moře ⌈s pastýři⌉ svého stáda? Kde je ten, kdo do jeho středu umístil svého svatého Ducha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Ten, který po pravici Mojžíšově nechal jít svou krásnou paži, kdo před nimi rozdělil vody a učinil si věčné jméno?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Vodil je hlubinami jako koně v pustině, že neklopýtali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'jako když dobytek sestupuje do údolí. Duch Hospodinův mu dává odpočinout, tak jsi vodil svůj lid a učinil sis slavné jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Shlédni z nebes a pohleď ze svého svatého a slavného obydlí. Kde je tvá horlivost a tvé udatné činy? Pohnutí tvého nitra a tvé slitování ⌈je mi zadrženo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Vždyť ty jsi náš otec, neboť Abraham nás nezná a Izrael si nás nevšímá. Ty, Hospodine, jsi náš otec, tvé jméno je od věčnosti: Náš vykupitel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Proč nás, Hospodine, necháváš bloudit od svých cest, zatvrzuješ naše srdce, abychom se tě nebáli? ⌈Navrať kvůli svým otrokům kmeny⌉ svého dědictví!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Nakrátko ji vlastnil tvůj svatý lid, než tvou svatyni pošlapali naši protivníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Jsme ⌈ tvoji odedávna, nad nimi jsi nevládl, oni se nenazývali⌉ tvým jménem. Kéž bys roztrhl nebesa a sestoupil, aby se před tebou hory zapotácely!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Jako oheň zapaluje suché roští a oheň uvádí do varu vodu, dej poznat svým protivníkům své jméno a národy se před tebou budou třást.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Když jsi konal hrozné věci, které jsme neočekávali, sestoupil jsi a hory se před tebou zapotácely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Od věků lidé neslyšeli ani nezaslechli, oko to nevidělo, aby byl Bůh -- kromě tebe -- který by ⌈dělal něco pro⌉ toho, kdo na něj očekává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Vycházíš vstříc tomu, kdo s radostí koná spravedlnost a ⌈na tvých cestách pamatuje na tebe.⌉ Hle, ty ses hněval, že jsme ⌈proti nim⌉ dávno hřešili; a ⌈ jak budeme zachráněni?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Všichni jsme jako nečistý a všechny naše spravedlnosti jsou jako poskvrněné roucho. Všichni jsme zvadli jako listí a naše viny nás odnášejí jako vítr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Není, kdo by vzýval tvé jméno, kdo by se vyburcoval, aby se držel tebe; neboť jsi před námi skryl svou tvář a vydal jsi nás do moci naší zvrácenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Ale nyní, Hospodine, ty jsi náš otec. My jsme hlína a ty hrnčíř; všichni jsme dílo tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Hospodine, nehněvej se tolik a nepřipomínej neustále vinu. Hle, jen pohleď, všichni jsme tvůj lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Tvá svatá města se stala pustinou, Sijón se stal pustinou, Jeruzalém je zcela opuštěný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Náš svatý a slavný dům, kde tě naši otcové chválili, je spálen ohněm a vše, co pro nás bylo vzácné, je v troskách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Při tom všem se budeš držet zpátky, Hospodine? Budeš mlčet a budeš nás tolik pokořovat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, '⌈Dal jsem se poznat⌉ těm, kdo se na mne nevyptávali, dal jsem se nalézt těm, kdo mne nehledali. Řekl jsem: Zde jsem, zde jsem, národu, který ⌈nebyl nazván mým jménem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Celý den jsem vztahoval ruce k umíněnému lidu, který chodí nedobrou cestou za vlastními úmysly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Ten lid mě ustavičně do očí provokuje ke hněvu: Obětují v zahradách a pálí kadidlo na cihlách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'pobývají v hrobech a nocují na skrytých místech, jedí vepřové maso a v jejich nádobách je vývar z nečistých věcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Říkají: ⌈Zůstaň, kde jsi,⌉ nepřistupuj ke mně, protože jsem světější než ty! Ti jsou kouřem v mém nose, ohněm plápolajícím po celý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Hle, je to přede mnou napsáno: Nebudu mlčet, pokud neodplatím. Odplatím jim do klína');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'za provinění vaše stejně jako za provinění vašich otců, kteří pálili oběti na horách a hanobili mě na návrších, praví Hospodin. Plně odměřím jejich odměnu do jejich klína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Toto praví Hospodin: Jako když se najde v hroznu víno a řekne se: Nenič ho, protože je v něm požehnání, tak se zachovám kvůli svým otrokům, abych to vše nezničil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Z Jákoba vyvedu símě a z Judy dědice mých hor. Zdědí to moji vyvolení a moji otroci tam budou přebývat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'A Šáron bude pastvinou ovcí a údolí Ákór místem odpočinku skotu. To pro můj lid, který mne vyhledává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ale vás, kdo Hospodina opouštíte, kdo zapomínáte na moji svatou horu, kteří připravujete stůl pro Štěstí a kteří naléváte míšené víno pro Určení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'vás jsem určil pro meč: Vy všichni se skloníte k zabití, protože jsem volal a neodpověděli jste, mluvil jsem a neposlouchali jste. Páchali jste to, co je zlé v mých očích, a vybrali jste si to, v čem nemám zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Proto toto praví Panovník Hospodin: Hle, moji otroci budou jíst, ale vy budete hladovět, hle, moji otroci budou pít, ale vy budete žíznit. Hle, moji otroci se budou radovat, ale vy se budete stydět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Hle, moji otroci budou výskat s radostí v srdci, ale vy budete křičet kvůli bolesti srdce a budete naříkat kvůli zdrcenému duchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Svoje jméno zanecháte mým vyvoleným k ⌈proklínání: Ať tě Panovník Hospodin usmrtí!⌉ Ale ⌈své otroky Bůh nazve⌉ jiným jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Kdokoli si bude v zemi žehnat, bude si žehnat v Bohu pravém, a kdo bude v zemi přísahat, bude přísahat v Bohu pravém; ano, budou zapomenuta dřívější soužení a budou ukryta před mýma očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Neboť hle, tvořím nová nebesa a novou zemi; dřívější věci nebudou připomínány, ani nepřijdou na mysl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Jen se veselte a jásejte až navěky nad tím, co tvořím, neboť hle, tvořím Jeruzalém plný plesání a jeho lid samé veselí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Budu jásat nad Jeruzalémem a veselit se ze svého lidu. Nebude už v něm slyšet zvuk pláče ani zvuk úpěnlivého křiku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nebude tam již miminko živé jen několik dnů a stařec, který nenaplní své dny. Neboť mládenec zemře ve věku sta let a ten, ⌈kdo nedosáhne⌉ sta let, bude považován za zlořečeného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Vystavějí domy a budou v nich bydlet, vysadí vinice a budou jíst jejich ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Nebudou stavět, aby bydlel jiný, nebudou vysazovat, aby jedl jiný. Vždyť dny mého lidu budou jako dny stromu, a moji vyvolení sami spotřebují, co svýma rukama vytvoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nebudou se namáhat zbytečně a nebudou rodit pro ohrožení, protože jsou símě požehnaných Hospodinových, ⌈a jejich potomci s nimi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Dříve nežli zavolají, já odpovím; ještě budou mluvit, a já je vyslyším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Vlk a jehně se budou pást spolu, lev bude požírat píci jako skot a hadu bude pokrmem prach. Nebudou páchat zlo a nebudou škodit na celé mé svaté hoře, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Toto praví Hospodin: Nebesa jsou mým trůnem a země podnoží mých nohou. ⌈Kde je ten dům, který mi chcete postavit,⌉ a kde místo mého odpočinutí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Všechny tyto věci učinila má ruka, ⌈tak to všechno nastalo,⌉ je Hospodinův výrok. Ale k tomu shlédnu: Ke zkroušenému a ubitému v duchu a k tomu, kdo se třese při mém slovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Kdo poráží k oběti býka, také ubíjí člověka, kdo obětuje ovci, také láme vaz psu, kdo přináší přídavnou oběť, také obětuje vepřovou krev, kdo přináší kadidlo k připomínce, také dobrořečí modle. Jak si oni vyvolili své cesty a jejich duše našla zálibu v ohavnostech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'tak i já pro ně vyvolím zlé zacházení a přivedu na ně to, čeho se hrozí, protože jsem volal, a nikdo neodpověděl, mluvil jsem, a neposlouchali; páchali to, co je zlé v mých očích, a vybrali si to, v čem nemám zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Slyšte Hospodinovo slovo, kdo se třesete před jeho slovem: Vaši bratři, kteří vás nenávidí a vylučují vás pro mé jméno, říkají: Ať se Hospodin oslaví a uvidíme vaši radost! Ale budou zahanbeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Slyš, hukot z města, zvuk z chrámu, ⌈zvuk, jak Hospodin odplácí⌉ svým nepřátelům za to, co vykonali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Dříve než se svíjela bolestí, porodila, dříve než na ni přišly bolesti, porodila chlapce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kdo slyšel něco takového? Kdo viděl něco takového? Cožpak se země zrodí v jediném dni? Zdalipak se národ narodí naráz? Vždyť sotva se Sijón začal svíjet bolestí, již porodil své syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Což bych já, který otevírám lůno, nedal zrození? říká Hospodin. Nebo já, který dávám rodit, bych uzavřel lůno? praví tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Radujte se s Jeruzalémem a jásejte nad ním všichni, kdo ho milujete. Jásejte s ním s radostí všichni, kteří nad ním truchlíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Protože budete sát a nasytíte se z ⌈prsu jeho útěchy,⌉ protože budete hltat s požitkem z ⌈prsu jeho slávy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Neboť toto praví Hospodin: Hle, přivádím k němu pokoj jako řeku a slávu národů jako valící se potok a budete z toho sát. Budete nošeni na boku a hýčkáni na kolenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Jako když někoho utěšuje matka, tak vás budu já utěšovat. V Jeruzalémě dojdete potěšení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Uvidíte to a vaše srdce bude jásat a vaše kosti rozkvetou jako tráva. Bude známo, že Hospodinova ruka je s jeho otroky a jeho rozhořčení je proti jeho nepřátelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Neboť hle, Hospodin přijde v ohni a jeho válečné vozy jako vichřice, aby v rozlícení vylil svůj hněv a své hrozby v plamenech ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Neboť ohněm a mečem bude Hospodin soudit veškeré tělo a pobitých Hospodinem bude mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Ti, kdo se posvěcují a očišťují kvůli zahradám po jednom uprostřed a jedí vepřové maso, ⌈ věci hodné opovržení⌉ i myši, ti společně zaniknou, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Já odpovím na jejich skutky a jejich úmysly: přijde čas k shromáždění všech národů a jazyků. I přijdou a uvidí mou slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Vložím na ně znamení a pošlu z nich ty, kdo vyváznou, k národům: Do Taršíše, do Púlu a do Lúdu, k těm, kdo napínají luk, do Túbalu a do Jávanu, na daleké ostrovy, které neslyšely zprávu o mně a neviděly mou slávu, a oznámí mou slávu mezi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'A přinesou všechny vaše bratry ze všech národů jako obětní dar Hospodinu na koních a na vozech, na nosítkách, na mezcích a na dromedárech na mou svatou horu do Jeruzaléma, praví Hospodin, tak jako synové Izraele přinášejí obětní dar v čisté nádobě do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Vezmu z nich také některé za kněze a za lévity, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Neboť tak jako přede mnou zůstávají nová nebesa a nová země, které dělám, je Hospodinův výrok, tak bude zůstávat vaše potomstvo a vaše jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'A novoluní co novoluní, sobotu co sobotu bude přicházet veškeré tělo, aby se sklánělo přede mnou, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'I vyjdou a pohlédnou na mrtvoly těch, kteří proti mně byli vzpurní. Ano, jejich červ neumírá a jejich oheň nehasne. Budou k opovržení veškerému tělu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Slova Jeremjáše, syna Chilkijášova, z kněží, kteří byli v Anatótu v zemi Benjamín,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'ke kterému se stalo Hospodinovo slovo ve dnech judského krále Jóšijáše, syna Amónova, ve třináctém roce jeho kralování');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'a stávalo se ve dnech judského krále Jójakíma, syna Jóšijášova, až do konce jedenáctého roku vlády judského krále Sidkijáše, syna Jóšijášova, až do ⌈vystěhování Jeruzaléma⌉ v pátém měsíci toho roku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Dříve, nežli jsem tě utvořil v nitru, znal jsem tě a dříve, nežli jsi vyšel z lůna matky, posvětil jsem tě a dal jsem tě za proroka národům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Řekl jsem: Ach, ⌈Panovníku Hospodine,⌉ podívej, neumím mluvit, vždyť jsem jen mládenec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Hospodin mi řekl: Neříkej, jsem jen mládenec, ale ke všem, ke kterým tě pošlu, jdi a vše, co ti přikáži, mluv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Neboj se jich, protože já jsem s tebou, abych tě vysvobodil, ⌈ je Hospodinův výrok.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Pak Hospodin vztáhl svou ruku a dotkl se mých úst. Hospodin mi řekl: Hle, dal jsem svoje slova do tvých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Pohleď, dnes tě ustanovuji nad národy a nad královstvími, abys vyvracel a ničil, hubil a bořil, abys budoval a sázel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Stalo se ke mně Hospodinovo slovo: Co vidíš, Jeremjáši? Řekl jsem: Vidím prut mandlovníku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Hospodin mi řekl: Dobře jsi viděl, protože bdím nad svým slovem, ⌈abych ho uskutečnil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Stalo se ke mně Hospodinovo slovo podruhé: Co vidíš? Řekl jsem: Vidím kouřící hrnec, obrácený sem od severu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Hospodin mi řekl: Od severu se bude valit zlo na všechny obyvatele země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'neboť hle, já volám všechny čeledě severních království, je Hospodinův výrok. Přijdou a každé si postaví trůn u vstupu do bran Jeruzaléma, proti všem jeho hradbám okolo i proti všem judským městům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'A já ⌈nad nimi vyslovím svůj rozsudek⌉ za všechno jejich zlo, že mě opustili a pálili oběti ⌈jiným bohům⌉ a ⌈klaněli se dílu⌉ svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Ty však ⌈přepásej svá bedra,⌉ vstaň a mluv proti nim všechno, co ti já přikáži. Netřes se před nimi, jinak tě roztřesu strachem z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'A já, hle, ⌈dal jsem tě dnes za opevněné město,⌉ za železný sloup a za bronzové hradby proti celé té zemi, proti judským králům a proti jejím knížatům, proti jejím kněžím i proti lidu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Budou proti tobě bojovat, ale nepřemohou tě, protože já jsem s tebou, je Hospodinův výrok, abych tě vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Jdi a ⌈volej k Jeruzalému:⌉ ⌈Toto praví Hospodin:⌉ Pamatuji na tebe, na oddanost tvého mládí, na lásku tvého zasnoubení, ⌈ kdy jsi za mnou chodila⌉ pustinou, zemí neosetou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Izrael je svatý Hospodinu, prvotina jeho úrody -- všichni, kdo jej sžírají, se proviňují; přijde na ně zlo, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, '⌈Slyšte Hospodinovo slovo,⌉ ⌈dome Jákobův⌉ a všechny čeledi domu izraelského:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Toto praví Hospodin: Co na mně vaši otcové našli špatného, že se ode mne vzdálili? Chodili za nicotností a nicotností se stali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Neřekli: Kde je Hospodin, ten, který nás vyvedl z egyptské země, ten, který nás vodil pustinou, zpustlou zemí plnou jam, ⌈vyprahlou zemí nejhlubší tmy,⌉ zemí, jíž nikdo neprochází a ve které člověk nebydlí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Přivedl jsem vás do země sadů, abyste jedli její ovoce a její dobré věci. Přišli jste však a mou zemi jste poskvrnili a mé dědictví jste učinili ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Kněží neřekli: Kde je Hospodin? Ti, kteří se zabývají zákonem, mě neznají. Pastýři se proti mně vzbouřili. Proroci prorokovali ⌈skrze Baala⌉ a šli za tím, co jim neprospěje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Proto s vámi ještě povedu při, je Hospodinův výrok, a povedu při i se syny vašich synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Vždyť projděte ⌈ostrovy Kitejců a dívejte se, pošlete do Kédaru⌉ a velmi pozorně sledujte, dívejte se, jestli se tam stalo něco takového.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Cožpak nějaký národ vyměnil bohy? A přitom to bohové nejsou! Ale můj lid zaměnil svoji slávu za to, co mu neprospěje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Zhrozte se nad tím, nebesa, zděste se, strňte, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Vždyť můj lid spáchal dvojí zlo: Opustili mne, pramen živé vody a vykopali si cisterny, puklé cisterny, které vodu nedrží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Je snad Izrael otrokem? Nebo ⌈ snad doma zrozeným otrokem?⌉ Proč se stal kořistí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Řvou nad ním mladí lvi, pozvedají svůj hlas. Učinili jeho zemi hroznou pustinou, jeho města jsou vypálena a bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Také synové Memfidy a Tachpanchésu se ti budou pást na temeni hlavy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Zdali sis to nezpůsobila ⌈tím, že jsi opustila⌉ Hospodina, svého Boha, tehdy, kdy tě vodil po cestě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'A teď? K čemu je ti cesta do Egypta? Abys pila vodu z Šíchoru? A k čemu je ti cesta do Asýrie? Abys pila vodu z řeky Eufratu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Bude tě vychovávat tvé vlastní zlo a budou tě kárat tvá odvrácení. Jen poznej a viz, že je zlé a trpké, když opouštíš Hospodina, svého Boha, a není v tobě bázeň přede mnou, je výrok Panovníka, Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Neboť již dávno ⌈jsem zlomil tvé jho, zpřetrhal jsem tvá pouta, a ty jsi řekla: Nebudu hřešit. A přece⌉ na každém vyvýšeném návrší a pod každým zeleným stromem roztahuješ nohy a smilníš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Já jsem tě zasadil jako vybranou révu, zcela spolehlivé símě. Jak to, že ses mi změnila v ⌈podřadné cizí víno?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'I když se umyješ sodou a naděláš si spoustu louhu, poskvrna tvé viny přede mnou zůstává, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Jak to, že říkáš: Neposkvrnila jsem se, za baaly jsem nechodila? Pohleď na svou cestu tam v údolí, poznej, cos učinila, ty mladá rychlá velbloudice, ⌈ která se proháníš po svých cestách,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'ty divoká oslice, navyklá pustině. V touze své duše větří ve větru. Kdo ji může odvrátit ⌈ od její vášně?⌉ Všichni, kdo ji hledají, se vůbec neunaví, najdou ji v ⌈čas říje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, '⌈Chraň svou nohu, aby nebyla bosá,⌉ a své hrdlo před žízní. Na to říkáš: ⌈Není naděje!⌉ Kdepak! Vždyť jsem si zamilovala cizince a budu chodit za nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Jako je zahanben zloděj, když ho dopadnou, tak bude zahanben dům izraelský -- oni, jejich králové, jejich knížata, jejich kněží i jejich proroci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'kteří říkají dřevu: Ty jsi můj otec, a kameni: Ty jsi nás zplodil, neboť se ke mně obrátili zády, a ne tváří, ale ⌈když se jim daří zle, říkají:⌉ Povstaň a zachraň nás!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Kde jsou tvoji bohové, které sis učinil? Ať povstanou, jestli tě zachrání, když se ti daří zle. Vždyť kolik je tvých měst, tolik je, Judo, tvých bohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Proč se mnou vedete při? Všichni jste se proti mně vzbouřili, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Nadarmo jsem bil vaše syny, kázeň nepřijali. Váš meč vám požral proroky jako lev zabiják.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Pohleďte, vy z této generace, na Hospodinovo slovo! Což jsem byl Izraeli pustinou? Či zemí temnoty? Proč můj lid říká: ⌈Jsme svobodní,⌉ už k tobě nepřijdeme?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Cožpak zapomene panna na své ozdoby nebo nevěsta na svoje pentle? Ale můj lid na mě již dávno zapomněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Jak vylepšuješ svoji cestu, abys hledala lásku! ⌈Proto i špatné ženy jsi naučila svým cestám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'I na okraji tvého roucha se nachází krev nevinných chudáků. Nedopadla jsi je při vloupání, ⌈ani při čemkoliv takovém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Avšak⌉ říkáš: Protože jsem nevinná, jeho hněv ode mě bude jistě odvrácen. Hle, soudím tě podle tvých řečí: Nezhřešila jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Jak velice lehkovážně měníš svou cestu! Tak jako jsi byla zklamána Asýrií, budeš zklamána i Egyptem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Také odtamtud vyjdeš s rukama na hlavě, protože Hospodin zavrhl tvé naděje a neuspěješ s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, '⌈Řekněme, že⌉ muž propustí svou ženu a ta od něho odejde a stane se ženou jiného muže. Cožpak se k ní ještě navrátí? Cožpak by ta země nebyla zcela znesvěcena? A ty jsi smilnila s mnoha druhy, a navracíš se ke mně? je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Pozvedni oči k ⌈holým návrším⌉ a podívej se, kdepak jsi neležela! Usadila ses kvůli nim na cestách jako Arab v pustině. Znesvětila jsi zemi svým smilstvem a svým zlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Přestože přeháňky byly zadrženy a jarní déšť nepřišel, měla jsi drzé čelo prostitutky, odmítla ses stydět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Copak i nyní ke mně nevoláš: Můj otče, ty jsi důvěrník mého mládí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Což se bude hněvat navěky? Neustále bude chovat hněv? Podívej, to jsi říkala, ale to zlo jsi páchala, kdykoli jsi mohla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Ve dnech krále Jóšijáše mi Hospodin řekl: Viděl jsi, co páchala izraelská odpadlice? Chodila na každou vyvýšenou horu, pod každý zelený strom a tam smilnila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Řekl jsem si: Po tom všem, co učinila, se ke mně navrátí. Ale nenavrátila se. Její nevěrná judská sestra to viděla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Viděl jsem to, vždyť právě proto, že izraelská odpadlice cizoložila, jsem ji propustil a dal jsem jí rozlukový lístek. Ale její nevěrná judská sestra se nebála a také ona chodila a smilnila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, '⌈Pro lehkost, s jakou smilnila,⌉ znesvětila zemi; cizoložila s kamenem i se dřevem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'A ani po tom všem se ke mně její nevěrná judská sestra nenavrátila celým svým srdcem, nýbrž jen falešně, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Hospodin mi řekl: Izraelská odpadlice se ukázala být spravedlivější nežli Juda, ta nevěrnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Jdi a volej ⌈na sever⌉ tato slova. Říkej: Navrať se izraelská odpadlice! je Hospodinův výrok. ⌈Nebudu se na vás tvářit zamračeně,⌉ vždyť jsem milosrdný, je Hospodinův výrok, nebudu se hněvat navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Jen uznej svou vinu, že ses vzbouřila proti Hospodinu, svému Bohu, a ⌈proplýtvala jsi svou přízeň⌉ na cizince pod každým zeleným stromem a mě jste neposlouchali, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Navraťte se, odvrácení synové, je Hospodinův výrok, protože já jsem vaším Pánem; vezmu vás po jednom z města, po dvou z čeledi a přivedu vás na Sijón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Dám vám pastýře podle svého srdce a budou vás pást s poznáním a s porozuměním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'I stane se, až se v oněch dnech rozmnožíte a rozplodíte v této zemi, je Hospodinův výrok, nebudou už říkat: Truhla Hospodinovy smlouvy; nepřijde jim na mysl, nebudou si ji připomínat, nebude jim chybět a nebude už zhotovena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'V onen čas nazvou Jeruzalém Hospodinovým trůnem a shromáždí se k němu všechny národy kvůli Hospodinovu jménu v Jeruzalémě a nebudou už žít podle svého umíněného a zlého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'V oněch dnech půjde dům judský s domem izraelským a přijdou spolu ze severní země do země, kterou jsem dal do dědictví vašim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'A já si říkal: Jak rád bych tě zařadil mezi syny a dal ti výbornou zemi, nádherné dědictví zástupů národů! Říkal jsem si, že mě budeš nazývat: Můj otče, a nebudeš se ode mě odvracet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Avšak tak jako žena nevěrně opouští svého druha, tak jste se nevěrně zachovali ke mně, dome izraelský, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Na holých návrších je slyšet hlas pláče a úpěnlivých proseb synů Izraele, protože zkazili svou cestu a zapomněli na Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Navraťte se, odvrácení synové, vyléčím vaše odvrácení. Hle, přicházíme k tobě, protože ty, Hospodine, jsi náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, '⌈Jistě je klamné čekat pomoc z kopců a ruchu na horách,⌉ vždyť spása Izraele je v ⌈Hospodinu, našem Bohu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Už od mládí nám ta hanebnost pohlcuje ⌈výtěžek práce ⌉ našich otců, jejich ovce a jejich skot, jejich syny a jejich dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Ať ležíme ve své hanbě a přikryje nás naše ostuda, protože jsme hřešili proti Hospodinu, svému Bohu, my i naši otcové, od svého mládí až dodnes a neuposlechli jsme Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Jestliže se, Izraeli, navrátíš, je Hospodinův výrok, jestliže se navrátíš ke mně, a jestliže z mé přítomnosti odstraníš své ohavné modly a nebudeš se toulat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'ale budeš přísahat: Jakože živ je Hospodin! -- pravdivě, podle práva a spravedlivě -- potom si jím budou žehnat národy a jím se budou chlubit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Neboť toto praví Hospodin judským mužům a Jeruzalému: Zorejte si úhor a nezasévejte do trní!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Obřežte se pro Hospodina a odstraňte předkožky svého srdce, judští muži a obyvatelé Jeruzaléma. Jinak můj hněv vyšlehne jako oheň, vzplane a kvůli vašim zvráceným činům neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Oznamte v Judsku, rozhlaste v Jeruzalémě a řekněte: Trubte v zemi na beraní roh. Hlasitě volejte a říkejte: Shromážděte se a pojďme do opevněných měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Pozdvihněte korouhev k Sijónu, rychle do bezpečí, neotálejte! Protože ze severu přivedu zlo a velkou zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Lev vystoupil ze svého houští a ničitel národů vyrazil; vyšel ze svého místa, aby tvou zemi učinil předmětem hrůzy; tvá města padnou, budou bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Proto se přepásejte pytlovinou, bědujte a naříkejte, protože se od nás neodvrátil Hospodinův planoucí hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, '⌈I stane se v onen den,⌉ je Hospodinův výrok, že ⌈král i knížata ztratí odvahu,⌉ kněží se zděsí a proroci budou ohromeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Řekl jsem: Ach, Panovníku Hospodine, vždyť tys tak podvedl tento lid i Jeruzalém! Prý: budete mít pokoj, a přitom k duši sahá meč!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'V oné době bude tomuto lidu a Jeruzalému řečeno: ⌈Žhavý vítr⌉ se valí ⌈z holých návrší pustinou⌉ přímo k ⌈dceři mého lidu.⌉ Ne, aby províval, ani aby čistil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Vítr silnější než tento se přižene ke mně; nyní také já ⌈nad nimi vyslovím rozsudek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Hle, zdvihne se jako mračna a jeho válečné vozy jako vichřice; jeho koně jsou rychlejší než orlové. Běda nám, neboť jsme zničeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Jeruzaléme, umyj své srdce od zla, abys byl zachráněn. Dokdy budou ve tvém nitru zůstávat ⌈tvé ničemné myšlenky?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Neboť hlas oznamuje z Danu a z Efrajimského pohoří se hlásí zkáza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, '⌈Ohlašte národům,⌉ hle, ⌈zvěstujte v Jeruzalémě:⌉ Z daleké země přicházejí obléhatelé a volají proti judským městům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Jako hlídači pole jsou okolo něj, protože byl vůči mně vzpurný, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Tvé jednání a tvoje činy ti to způsobily; to je ⌈tvé zlo,⌉ jak je to trpké a zachvátilo to i tvé srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, '⌈Nitro, mé nitro!⌉ Svíjím se bolestí. ⌈Srdce mám sevřené,⌉ srdce mi buší! Nebudu mlčet, protože jsi slyšela, má duše, zvuk beraního rohu a válečný křik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Hlásí se zkáza za zkázou, protože je ničena celá země; náhle jsou zničeny mé stany, v okamžiku mé celty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Dokdy budu vidět korouhev a slyšet zvuk beraního rohu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Vždyť můj lid je jako hlupák, neznají mě. Jsou to ⌈synové bláznů⌉ a ničemu nerozumějí. Moudrost mají pro páchání zla, ale jak konat dobro, to nevědí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Pohleděl jsem na zemi, a hle, byla pustá a prázdná, a k nebesům, ale jejich světlo nebylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Pohleděl jsem na hory, a hle, třásly se, i všechny kopce se otřásaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Pohleděl jsem, a hle, nebyl žádný člověk a všechno nebeské ptactvo uletělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Pohleděl jsem, a hle, ovocný sad se stal pustinou a všechna jeho města byla zbořena před Hospodinem, před jeho planoucím hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Neboť toto praví Hospodin: Celá země bude zpustošena, ale nezničím ji úplně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Proto bude země truchlit a nebesa se svrchu zachmuří, neboť jsem vyslovil, co zamýšlím, a nebudu toho litovat, neodvrátím se od toho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Před zvukem jezdce a lukostřelce utíká celé město, jdou do houštin a vystupují do skal, ⌈všechna města jsou opuštěná⌉ a nikdo v nich nebydlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'A ty, zpustošená, co to děláš, že se oblékáš do karmínu, že se zdobíš zlatou ozdobou, že si líčidlem zvýrazňuješ oči? Nadarmo se krášlíš! Milenci tebou pohrdají. Usilují o tvůj život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Neboť jsem slyšel jakoby křik ženy svíjející se bolestí, jakoby úzkostné sténání prvorodičky, křik dcery sijónské, která lapá po dechu, vztahuje dlaně a volá: Běda mi, protože má duše umdlela kvůli vrahům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Procházejte ulicemi Jeruzaléma, jen se dívejte a zkoumejte, hledejte na jeho náměstích, jestli najdete někoho, jestli je někdo, kdo ⌈jedná podle práva⌉ a kdo usiluje o věrnost, a já Jeruzalému odpustím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'I když říkají: Jakože živ je Hospodin, jistě přísahají lživě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Hospodine, cožpak tvoje oči ne hledí na věrnost? Ranil jsi je, ale ⌈necítili bolest,⌉ ničil jsi je, ale odmítali přijmout kázeň. Zatvrdili se víc než skála, odmítali se navrátit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Já jsem si myslel: Jsou to jen chudáci; jednali hloupě, protože neznají ⌈Hospodinovu cestu,⌉ nařízení svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Zajdu si k ⌈vysoko postaveným⌉ a promluvím si s nimi, protože oni znají Hospodinovu cestu, nařízení svého Boha. Jenže i tihle zlomili jho, zpřetrhali pouta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Proto je zabije lev z houštiny, zničí je stepní vlk. Před jejich městy číhá leopard; každého z nich, kdo vyjde, roztrhá na kusy, protože jejich přestoupení je mnoho, mnoho je jejich odvrácení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Proč bych ti měl odpustit? Tvoji synové mě opustili a přísahali při těch, kdo ne jsou bohy. Nasytil jsem je, ale oni cizoloží a houfují se v nevěstinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Jsou to vykrmení, bujní hřebci; všichni dychtí po ženě svého bližního.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Cožpak je za to ne mám navštívit?, je Hospodinův výrok. Zdalipak se moje duše nepomstí na národě, jako je tento?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Vystupte na jeho vinohrady a ničte, ale nezničte je úplně. Odstraňte jeho výhonky, protože nejsou Hospodinovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Dům izraelský i dům judský mi totiž byl zcela nevěrný, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Lhali o Hospodinu a říkali: ⌈Kdepak on.⌉ Zlo na nás nepřijde, nezažijeme meč ani hlad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Ti proroci ⌈jsou jen vítr⌉ a Hospodinovo slovo v nich není. Tak se jim stane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Proto takto praví Hospodin, Bůh zástupů: Protože jste mluvili toto slovo, hle, svá slova učiním ve tvých ústech ohněm a tento lid dřívím a stráví je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Hle, dome izraelský, přivedu na vás zdaleka národ, je Hospodinův výrok, národ prastarý, národ odvěký, národ, jehož jazyk neznáš, ani nerozumíš, co mluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Jeho toulec je jako otevřený hrob, všichni jsou hrdinové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Pohltí tvoji sklizeň a tvůj chléb, pohltí tvoje syny a tvoje dcery, pohltí tvůj brav a tvůj skot, pohltí tvou révu i tvůj fíkovník. Mečem rozboří tvá opevněná města, na která ty spoléháš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Ale ani v oněch dnech, je Hospodinův výrok, vás nezničím úplně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'I stane se, až se budete ptát: Proč nám Hospodin, náš Bůh, toto všechno provedl? že jim odpovíš: Jako jste mě opustili a sloužili jste ve své zemi cizím bohům, tak budete sloužit cizincům v zemi, která není vaše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Oznamte to v domě Jákobově a zvěstujte to v Judsku:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Slyšte to přece, lide bláznivý a bez rozumu! Mají oči, ale nevidí. Mají uši, ale neslyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Cožpak se mě nebudete bát? -- je Hospodinův výrok. Zdalipak se nebudete třást přede mnou, který jsem umístil písek jako hráz, věčnou hranici moře, kterou nepřekročí? Jeho vlny se sice dmou, ale nezdolají ji, burácejí, ale nepřekročí ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Avšak tento lid má umíněné a vzpurné srdce; odvrátili se a odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Neříkají si v srdci: Bojme se Hospodina, svého Boha, který dává podzimní i jarní déšť ve svůj čas a zachovává nám týdny ustanovené pro sklizeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Narušily to vaše viny a vaše hříchy ⌈před vámi zadržely⌉ dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Protože se v mém lidu našli ničemové, každý číhá jako přikrčený ptáčník -- nastražili past a lapají lidi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Jako klec plná ptáků, tak jsou jejich domy plné podvodu; takto ⌈dosáhli vysokého postavení⌉ a získali bohatství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Ztloustli a ⌈dosáhli blahobytu,⌉ překročili i ⌈ každou hranici⌉ zla. Nepomohou získat právo, sirotka nehájí, ⌈ale těší se z vlastního úspěchu.⌉ ⌈Chudým právo nezjednají.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Cožpak je za to ne mám navštívit? je Hospodinův výrok. Zdalipak se moje duše nepomstí na národě, jako je tento?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'V zemi dochází k hrozné a otřesné věci:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Proroci prorokují lživě a kněží ⌈berou věci do svých rukou,⌉ ⌈a mému lidu se to tak líbí!⌉ Co však ⌈budete dělat na konci toho všeho?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Rychle do bezpečí, synové Benjamínovi, pryč z Jeruzaléma. V Tekóji trubte na beraní roh a nad Bét–keremem zapalte signální oheň, protože ze severu shlíží zlo a velká zkáza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, '⌈Zničím tu krásnou a zhýčkanou dceru sijónskou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Přijdou k ní pastýři se svými stády, postaví si stany okolo ní a každý spase svůj podíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Nachystejte proti ní válku. Povstaňte a vyrazme v poledne. Běda nám, protože den se chýlí ke konci a večerní stíny se prodlužují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Povstaňte, vyrazme v noci a zničme její paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Neboť toto praví Hospodin zástupů: Pokácejte stromy a navršte proti Jeruzalému obléhací násep. Je to město k tomu určené, uvnitř je plné útlaku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Jako studna uchovává svou vodu svěží, tak ono uchovává svěží své zlo. Je v něm slyšet násilí a zkáza, stále je přede mnou nemoc a rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, '⌈Dej si poradit,⌉ Jeruzaléme, jinak se od tebe má duše odvrátí, jinak tě učiním zcela opuštěnou, neobydlenou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Toto praví Hospodin zástupů: Jistě budou paběrkovat ostatek Izraele jako révu. Vztáhni znovu svoji ruku jako česač hroznů na ratolesti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Ke komu mám mluvit, koho varovat, aby slyšeli? Hle, ⌈mají ucpané uši,⌉ nejsou schopni dávat pozor. Hle, Hospodinovo slovo jim bylo k posměchu, nemají v něm zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Jsem plný Hospodinova hněvu, jsem vyčerpán tím, že ho musím snášet. Vylej ho na dítě na ulici a ⌈na mládence, kteří spolu důvěrně hovoří,⌉ vždyť i muž s ženou budou polapeni, stařec s tím, kdo je plný dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Jejich domy stejně jako pole a ženy budou předány jiným, neboť vztáhnu svou ruku proti obyvatelům této země, je Hospodinův výrok,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'protože všichni od nejmenšího do největšího pro sebe hrabou nekalý zisk, od proroka až po kněze všichni podvádějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Napravují zkázu mého lidu povrchně slovy: ⌈Pokoj, pokoj,⌉ ale ⌈ žádný pokoj⌉ není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Styděli se, že páchali odpornou věc? Ani trochu se nestyděli, ani se hanbit neumějí. Proto padnou s padajícími; v čase, kdy je navštívím, se zapotácejí, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Toto praví Hospodin: Zastavte se na cestách a rozhlížejte se! Ptejte se na dávné stezky: Kde je ta dobrá cesta? Jděte po ní a najděte místo odpočinutí pro své duše. Říkají však: Nepůjdeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Ustanovil jsem vám strážné se slovy: Dávejte pozor na zvuk beraního rohu. Říkají však: Nebudeme dávat pozor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Proto slyšte, národy, a znej, shromáždění, co se s nimi stane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Slyš, země: Hle, přivedu na tento lid zlo, ovoce jeho úmyslů, protože nenaslouchali pozorně mým slovům. A můj zákon? Tím pohrdli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Na co je mi kadidlo pocházející ze Šeby a vonné koření z daleké země? Vaše zápaly se mi nezalíbí a vaše oběti mě nepotěší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Proto takto praví Hospodin: Hle, já kladu tomuto lidu překážky a klopýtnou o ně otcové spolu se syny, soused i jeho přítel a zahynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Toto praví Hospodin: Hle, ze severní země přichází lid, do pohybu se dává velký národ z nejvzdálenějších částí země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, '⌈Chopí se luku⌉ a srpáče, jsou krutí a nebudou mít slitování. Jejich křik bude burácet jako moře. Připraveni jako muž do boje pojedou na koních proti tobě, dcero sijónská.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Když jsme uslyšeli zvěst ⌈o něm,⌉ naše ruce ochably, zmocnila se nás tíseň, porodní bolesti jako rodičky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Nevycházejte na pole a nechoďte po cestě, protože nepřítel má meč a všude kolem hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Dcero mého lidu, přepásej se pytlovinou, válej se v popelu; konej smuteční obřady jako nad jedináčkem, hořké kvílení, neboť náhle na nás přijde ničitel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Ustanovil jsem tě za prubíře svého lidu, za zkoušeče, abys poznal a vyzkoušel jejich cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Všichni jsou to ⌈odvrácení umíněnci,⌉ chodí a pomlouvají, ⌈ jsou jen bronz a železo, všichni jsou zkažení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Měch dmýchá, z ohně se odděluje jen olovo. Zlatník přečišťoval nadarmo, zlí nejsou odstraněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, '⌈Nazvali je zavrženým stříbrem, protože Hospodin je zavrhl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Postav se v bráně Hospodinova domu a volej tam toto slovo. Říkej: Slyšte Hospodinovo slovo, ⌈všichni Judejci,⌉ kteří vcházíte těmito branami, abyste se klaněli Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Toto praví ⌈Hospodin zástupů, Bůh Izraele:⌉ Dejte do pořádku své cesty a své činy a nechám vás přebývat ⌈na tomto místě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Nespoléhejte na lživá slova: Toto je Hospodinův chrám, Hospodinův chrám, Hospodinův chrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Avšak jestliže opravdu dáte do pořádku své cesty a své činy, jestliže ⌈mezi sebou⌉ opravdu budete jednat podle práva,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'jestliže nebudete utlačovat příchozího, sirotka a vdovu a nebudete na tomto místě prolévat krev nevinného a nebudete chodit ⌈k vlastní škodě⌉ za jinými bohy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'pak ⌈vás nechám⌉ přebývat na tomto místě, v zemi, kterou jsem dal vašim otcům od věků až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Hle, vy však spoléháte na lživá slova, která neprospějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Cožpak můžete krást, vraždit a cizoložit, lživě přísahat, obětovat Baalovi a chodit za jinými bohy, které jste neznali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'a potom přijít, postavit se přede mnou v tomto domě, ⌈který se nazývá mým jménem,⌉ a říci: Jsme zachráněni, jen abyste mohli dál páchat všechny tyto odporné věci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Cožpak se tento dům, ⌈který se nazývá mým jménem,⌉ stal ve vašich očích jeskyní lupičů? Avšak vizte, já to vidím, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Vždyť jděte k mému místu, které bylo v Šílu, kde jsem poprvé nechal přebývat své jméno, a podívejte se, co jsem s ním udělal za zlo svého lidu Izraele!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'A nyní, protože jste spáchali všechny tyto skutky, je Hospodinův výrok, a mluvil jsem k vám, ⌈stále znovu⌉ jsem mluvil, ale neslyšeli jste, volal jsem vás, ale neodpovídali jste,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'hodlám s domem, který se nazývá mým jménem, s domem, na který spoléháte, a s místem, které jsem dal vám a vašim otcům, učinit to, co jsem udělal se Šílem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Odvrhnu vás ⌈od sebe,⌉ jako jsem odvrhl všechny vaše bratry, celé potomstvo Efrajimovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Ty se za tento lid nemodli, nepozdvihuj za ně nářek ani modlitbu, ⌈nepřimlouvej se u mne,⌉ ⌈neboť tě nevyslyším.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Cožpak nevidíš, co páchají v judských městech a na ulicích Jeruzaléma?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Děti sbírají dříví, otcové zapalují oheň a ženy zadělávají těsto, aby pekly koláče královně nebes. Lijí úlitby jiným bohům, aby mě rozzlobili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Cožpak ⌈zlobí mě? je Hospodinův výrok. Cožpak nebudou zahanbeni sami před sebou?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Proto takto praví Panovník Hospodin: Hle, můj ⌈hněv a má zloba⌉ se vyleje na toto místo, na lidi i na zvířata, na polní stromy i na plody země. Vzplane a neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Toto praví Hospodin zástupů, Bůh Izraele: ⌈ Jen si přidejte své zápalné oběti ke svým obětním hodům a jezte maso,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'protože já jsem vašim otcům v den, kdy jsem je vyvedl z egyptské země, ohledně zápalné oběti a obětního hodu nic neřekl ani nepřikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Toto jsem jim však přikázal: Poslouchejte mě a budu ⌈vaším Bohem a vy budete mým lidem.⌉ ⌈Choďte jenom po té cestě, kterou⌉ vám přikáži, aby se vám vedlo dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Avšak neposlouchali a nenakláněli ucho, ale žili podle rad svého umíněného a zlého srdce; ⌈otočili se ke mně zády, a ne tváří.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Od toho dne, kdy vaši otcové vyšli z egyptské země, až dodnes jsem vám posílal všechny své otroky proroky, denně, stále znovu jsem je posílal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'avšak neposlouchali mne a nenakláněli ucho, ale zatvrdili svou šíji a páchali větší zlo než jejich otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Budeš k nim mluvit ⌈všechna tato slova,⌉ ale nebudou tě poslouchat, budeš k nim volat, ale neodpovědí ti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Řekni jim: Toto je národ, který neposlouchal Hospodina, svého Boha, a nepřijímal kázeň. Zahynula věrnost, je odříznuta od jejich úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Ostříhej si vlasy a odhoď je. Pozdvihni nářek na holých návrších, protože Hospodin zavrhl a opustil ⌈generaci, která provokovala jeho hněv.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Protože synové Judy páchali to, ⌈co je zlé v mých očích,⌉ je Hospodinův výrok, postavili své ohavné modly v domě, který se nazývá mým jménem, aby jej znečistili,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'vystavěli návrší Tófet, které je v údolí Hinómova syna, aby spalovali své syny a své dcery ohněm, což jsem jim nepřikázal, ani mi nic takového nepřišlo na mysl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Proto ⌈hle, přicházejí dny, je Hospodinův výrok,⌉ kdy se už nebude říkat: Tófet ani údolí Hinómova syna, ale údolí zabíjení, a budou pohřbívat v Tófetu, až už ne bude místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Mrtvoly tohoto lidu se stanou potravou nebeského ptactva a zemské zvěře a nebude, kdo by je zaplašil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Způsobím, že z judských měst a z ulic Jeruzaléma zmizí hlas jásotu i hlas radosti, hlas ženicha i hlas nevěsty, protože se země stane troskami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'V onen čas, je Hospodinův výrok, vyberou z jejich hrobů kosti judských králů, kosti jejich knížat, kosti kněží, kosti proroků a kosti obyvatel Jeruzaléma');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'a rozházejí je před sluncem, před měsícem a před celým nebeským zástupem, které si zamilovali, kterým sloužili, za kterými chodili, které vyhledávali a kterým se klaněli; nebudou sebrány, nebudou pohřbeny, budou jako hnůj na povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Celý ostatek pozůstalých z této zlé čeledi na každém místě, kam jsem ty pozůstalé zahnal, si raději vyvolí smrt nežli život, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Řekni jim: Toto praví Hospodin: Padnou–li lidé, nepovstanou? Jestliže se někdo odvrátí, nenavrátí se zase zpět?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Proč se tedy tento lid, Jeruzalém, odvrátil trvalým odvrácením? Drží se pevně klamu a odmítají se navrátit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Pozorně jsem naslouchal a slyšel, že nemluví správně; není nikdo, kdo by litoval svého zla a řekl: Co jsem to provedl? Každý ⌈se odvrací ke svému způsobu života,⌉ jako se kůň řítí do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'I čáp na nebi zná svůj určený čas, hrdlička, vlaštovka i jeřáb zachovávají dobu svého příletu, ale můj lid nezná Hospodinovo nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Jak to, že říkáte: Jsme moudří, máme Hospodinův zákon? Jenže podívejte, lživé rydlo písařů ho udělalo lživým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Mudrci se zastydí, zděsí se a budou polapeni. Hle, pohrdli Hospodinovým slovem, ⌈jakou to mají moudrost?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Proto dám jejich ženy jiným a jejich pole dobyvatelům, protože všichni od nejmenšího do největšího pro sebe hrabou nekalý zisk, od proroka až po kněze všichni podvádějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Napravují zkázu dcery mého lidu povrchně slovy: ⌈Pokoj, pokoj,⌉ ale ⌈ žádný pokoj⌉ není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Styděli se, že páchali odpornou věc? Ani trochu se nestyděli, ani se hanbit neumějí. Proto padnou s padajícími; v čase svého navštívení se zapotácejí, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, '⌈Přivodím jejich konec,⌉ je Hospodinův výrok. Na révě nebudou hrozny, na fíkovníku nebudou žádné fíky, listy zvadnou, ⌈a co jsem jim dal, od nich odstoupí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Proč sedíme? Shromážděte se a pojďme do opevněných měst a zahyneme tam, protože Hospodin, náš Bůh, nás vydal záhubě a dal nám pít ⌈otrávenou vodu,⌉ protože jsme zhřešili proti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Čekáme pokoj, ale ⌈dobro ne přichází,⌉ čas uzdravení, ⌈a hle, jen ⌉ hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Od Danu je slyšet frkání jeho koní, zvukem ržání jeho hřebců se třese celá země. Přiženou se a zhltnou zemi i všechno, co ji naplňuje; města i jejich obyvatele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Protože hle, posílám mezi vás hady, zmije, na které není zaklínadlo, a pokoušou vás, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, '⌈Nevyléčitelný je můj žal,⌉ mé srdce je zemdlené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Hle, slyš! Volání dcery mého lidu o pomoc z daleké země: Cožpak Hospodin není na Sijónu? Zdalipak v něm není jeho král? Proč mě zlobili svými modlami, cizími nicotnostmi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Přešla sklizeň, pominulo léto, a my nejsme zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Jsem zlomen zkázou dcery mého lidu, truchlím, zmocnila se mě hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Což není balzám v Gileádu, cožpak tam není lékař? Proč jen nepřišlo uzdravení dcery mého lidu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 23, '⌈Kdo dá mé hlavě vodu a mým očím zdroj slz,⌉ abych plakal ve dne i v noci nad pobitými dcery mého lidu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, '⌈Kdyby mi někdo dal⌉ v pustině útulek pro poutníky, opustil bych svůj lid a odešel od nich, protože to jsou všichni cizoložníci, sebranka nevěrníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Ohýbají svůj jazyk jako luk ke klamu, a ne k věrnosti, převládli v zemi, neboť postupují od zla ke zlu a mě neznají, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Mějte se každý na pozoru před svým přítelem, nedůvěřujte žádnému bratru, protože všichni bratři podvádějí a všichni přátelé pomlouvají, kudy chodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Každý podvádí svého přítele, nikdo nemluví pravdu; učí svůj jazyk mluvit klam a jsou unaveni činěním zla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, '⌈Bydlíš uprostřed podvodu; kvůli podvodu⌉ mě odmítli znát, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Proto takto praví Hospodin zástupů: Hle, já je přečistím a vyzkouším, protože jak jinak bych měl jednat s dcerou svého lidu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Jejich jazyk je jako smrtící šíp, ⌈svými ústy podvádějí. Vyslovuje pokoj pro svého přítele,⌉ ale ve svém nitru mu strojí léčku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Cožpak je za to ne mám navštívit? je Hospodinův výrok. Zdalipak se moje duše nepomstí na národě, jako je tento?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Pláču a běduji nad horami, naříkám nad stepními pastvinami, protože jsou vypáleny, nikdo jimi ani neprochází a není slyšet hlas dobytka. Od nebeského ptactva až po zvěř, všichni uletěli a utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, '⌈Proměním Jeruzalém v⌉ hromady kamení a doupě šakalů, judská města ⌈proměním ve ⌉ zcela opuštěná místa bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Kdo je natolik moudrý, aby tomu porozuměl? Ke komu promluvila Hospodinova ústa, aby to oznámil? Proč zahynula země a byla vypálena jako pustina, kterou nikdo neprochází?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'A Hospodin řekl: Protože opustili můj zákon, který ⌈jsem jim předložil,⌉ a neposlouchali mě a nežili podle zákona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'ale žili podle svého umíněného srdce i chodili za baaly, jak je to naučili jejich otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Proto takto praví Hospodin zástupů, Bůh Izraele: Hle, nakrmím tento lid pelyňkem a dám jim pít otrávenou vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Rozptýlím je mezi národy, které neznali oni ani jejich otcové. Pošlu za nimi meč, dokud s nimi neskoncuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Toto praví Hospodin zástupů: Uvažte to a zavolejte plačky, ať přijdou! Pošlete pro moudré ženy, ať přijdou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Ať si pospíší a ⌈začnou nad námi bědovat.⌉ Ať z našich očí plynou slzy, ať se z našich víček řine voda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'vždyť ze Sijónu je slyšet hlas bědování: Jak jsme zničeni! Velmi se stydíme, neboť jsme opustili zemi, protože strhli naše příbytky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Proto ženy, slyšte Hospodinovo slovo a ať vaše ucho přijme slovo jeho úst. Naučte své dcery bědovat a své přítelkyně naříkat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'protože do našich oken vystoupila smrt. Přišla do našich paláců, aby vyhladila děti z ulic i mládence z náměstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Promluv: Toto je Hospodinův výrok: Lidské mrtvoly padnou na povrch pole jako hnůj a jako pokos za žencem a nebude, kdo by je posbíral.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Toto praví Hospodin: Ať se moudrý nechlubí svou moudrostí, ať se hrdina nechlubí svou zdatností, ať se bohatý nechlubí svým bohatstvím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'ale kdo se chlubí, ať se chlubí ⌈ tím, že je rozumný a zná mě,⌉ že já, Hospodin, vykonávám na zemi milosrdenství, právo a spravedlnost, ⌈protože v těchto věcech ⌉ mám zalíbení, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Hle, přicházejí dny, je Hospodinův výrok, kdy navštívím všechny obřezané pouze na předkožce:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Egypt, Judu, Edóm, syny Amónovy, Moába, všechny s vyholenými skráněmi, kteří žijí v pustině, protože všechny tyto národy jsou neobřezané i celý dům izraelský má neobřezané srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Slyšte slovo, které k vám promluvil Hospodin, dome izraelský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Toto praví Hospodin: Neučte se cestě pohanských národů a nebeských znamení se neděste, ačkoliv se jich děsí pohanské národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Vždyť náboženské zvyklosti národů jsou nicotnost. ⌈ Vezmou třeba⌉ kus pokáceného stromu z lesa, dílo řemeslníkovy ruky zhotovené sekerou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Okrášlí ho stříbrem a zlatem, hřebíky a kladivy ho upevní, aby se nekymácelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Jejich bohové jsou jako ⌈strašák v okurkovém poli;⌉ nemluví, musejí se nosit, protože neumějí chodit. Nebojte se jich, protože ⌈ nic zlého nedělají a ani dobro konat nemohou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Není nikdo jako ty, Hospodine. Jsi velký, ⌈velké a mocné je tvé jméno.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kdo by se tě nebál, králi národů, protože tobě to náleží. Vždyť mezi všemi mudrci národů a ve všech jejich královstvích není nikdo jako ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Vespolek jsou hloupí a blázniví, ⌈naučení nicotných model je jen dřevo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Tepané stříbro, dovezené z Taršíše a zlato z Úfázu; je to dílo řemeslníka a zlatníkových rukou. Jejich oděv je modrý a purpurový, všechno je to dílo zručných mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Ale Hospodin je pravý Bůh, on je živý Bůh a věčný král. Před jeho hněvem se třese země, národy nevydrží jeho rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Toto jim řekněte: Bohové, kteří nebesa a zemi neučinili, zmizí ze země a zpod těchto nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Svou silou Hospodin učinil zemi, svou moudrostí založil svět a svou rozumností roztáhl nebesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Když ⌈vydá hlas,⌉ bouří se voda v nebesích, dává vystupovat mlze z končin země, působí blesky s deštěm, ze svých skladů vyvádí vítr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, '⌈Všichni lidé jsou⌉ hloupí a bez poznání, ⌈všichni zlatníci jsou⌉ zahanbeni svými modlami, protože jejich modly jsou falešné, ne ní v nich duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Jsou nicotností, směšným dílem, v čase svého navštívení zahynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Podíl Jákobův jim není podobný, neboť on je Tvůrcem všeho a Izrael je jeho dědičným kmenem; jeho jméno je Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, '⌈Seber ze země své zavazadlo,⌉ ty, která zůstáváš v obležení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'neboť toto praví Hospodin: Hle, tentokrát vyvrhnu obyvatele této země a způsobím jim soužení, aby to pocítili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Běda mi pro mou zkázu, moje rána je nevyléčitelná. Řekl jsem: Ovšem, je to utrpení, které unesu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Můj stan je zničen, všechna má lana jsou zpřetrhána. Moji synové mi odešli, a už zde nejsou. Není, kdo by mi znovu postavil stan a upevnil mi stanové plachty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Vždyť pastýři byli hloupí a nehledali Hospodina, proto nejednali rozumně a celé jejich stádo bylo rozptýleno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Slyš! Hle, přichází zpráva a hřmot ze severní země, aby judská města učinil zcela opuštěnými místy, doupětem šakalů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Vím, Hospodine, že ⌈člověk nemá svou cestu ve své moci a že ten, kdo chodí, neurčuje svoje kroky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Naprav mě, Hospodine, jen podle práva, ne ve svém hněvu, jinak ⌈mě vyhladíš.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Vylej svou zlobu na národy, které tě neznají a na čeledě, které nevzývají tvé jméno, protože pohltily Jákoba, pohltily jej a zničily, zpustošily jeho bydliště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Slyšte slova této smlouvy! Promlouvej je k judským mužům a k obyvatelům Jeruzaléma;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'řekni jim: Toto praví Hospodin, Bůh Izraele: Proklet je každý, kdo neposlouchá slova této smlouvy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'kterou jsem přikázal vašim otcům v den, kdy jsem je vyvedl z egyptské země, z ⌈pece na tavení železa,⌉ se slovy: Poslouchejte mě a ⌈jednejte podle všeho, co⌉ vám přikazuji, a budete ⌈mým lidem a já budu vaším Bohem,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'abych naplnil přísahu, kterou jsem přísahal vašim otcům, že jim dám zemi oplývající mlékem a medem, jak je tomu dnes. Odpověděl jsem: Amen, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Hospodin mi řekl: Volej všechna tato slova v judských městech i na ulicích Jeruzaléma, řka: Poslouchejte slova této smlouvy a ⌈jednejte podle nich.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Vždyť jsem naléhavě napomínal vaše otce ode dne, kdy jsem je vyvedl z egyptské země, až dodnes, stále znovu jsem je napomínal slovy: Poslouchejte mě!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Avšak neposlouchali a nenakláněli ucho, ale žili každý podle svého umíněného a zlého srdce. Přivedl jsem na ně všechna slova této smlouvy, ⌈kterou jsem jim přikázal plnit, ale neplnili ji.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Hospodin mi řekl: Mezi judskými muži a mezi obyvateli Jeruzaléma došlo k spiknutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Navrátili se k vinám svých praotců, kteří odmítali poslouchat má slova, chodili za jinými bohy a sloužili jim. Dům izraelský i dům judský porušoval mou smlouvu, kterou jsem uzavřel s jejich otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Proto takto praví Hospodin: Hle, přivedu na ně zlo, před nímž nebudou moci ujít. Budou ke mně volat, ale ⌈nevyslyším je.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Judská města a obyvatelé Jeruzaléma půjdou a budou volat k bohům, kterým obětují. V čase, kdy se jim bude dařit zle, je určitě nezachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Vždyť kolik je tvých měst, Judo, tolik je tvých bohů, a kolik je jeruzalémských ulic, tolik jste postavili oltářů pro hanebnost, oltářů pro pálení kadidla Baalovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Ty se za tento lid nemodli, nepozdvihuj za ně nářek a modlitbu, protože je nevyslyším, až budou ke mně volat kvůli tomu, že se jim daří zle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, '⌈Co chce můj miláček v mém domě?⌉ Provádět pletichy? Cožpak od tebe sliby a posvátné ⌈maso odstraní zlo? Tehdy se budeš radovat?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Hospodin ⌈tě pojmenoval⌉ zelenou olivou s krásně narostlým ovocem, ale se zvukem velké bouře na ní zapálí oheň a její větve se polámou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Hospodin zástupů, který tě zasadil, proti tobě vyslovil zlo kvůli zlu domu izraelského a domu judského, ⌈které páchali -- aby mě rozzlobili, obětovali Baalovi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Hospodin mi to dal poznat a dozvěděl jsem se to. Tehdy jsi mi ukázal jejich činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Byl jsem jako krotký beránek vedený na porážku, ani jsem nevěděl, že proti mně ⌈vymýšlejí plán:⌉ Zničme strom i s jeho ovocem, vytněme jej ze země živých a jeho jméno už nebude připomínáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Hospodine zástupů, ⌈ který soudíš spravedlivě,⌉ který zkoumáš ⌈ledví i srdce,⌉ kéž na nich uzřím tvoji pomstu, protože tobě jsem přenechal svůj spor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Proto takto praví Hospodin o anatótských mužích, kteří usilují o tvůj život a říkají: Neprorokuj v Hospodinově jménu, ⌈abys nezemřel⌉ naší rukou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'proto takto praví Hospodin zástupů: Hle, navštívím je s trestem. Mládenci zemřou mečem a jejich synové a jejich dcery zemřou hladem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'ani ostatek z nich nezůstane, protože na anatótské muže přivedu zlo, rok jejich navštívení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Jsi spravedlivý, Hospodine, ⌈proto si u tebe chci stěžovat.⌉ ⌈Jen s tebou chci mluvit o věcech práva.⌉ Proč je cesta ničemů úspěšná a proč se ⌈všem podvodníkům daří?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Zasadil jsi je a oni i zakořenili, rostou a dokonce vydávají plody. ⌈Mají tě plná ústa, ale jejich nitru jsi daleko.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Ty, Hospodine, mě znáš, vidíš mě a zkoumáš mé srdce, že je s tebou. Odtáhni je jako stádo na porážku, odděl je pro den popravy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Dokdy bude země usychat a vadnout všechna polní zeleň? Pro zlo těch, kteří v ní bydlí, zmizela zvěř i ptactvo; a to proto, že řekli: On nevidí ⌈náš konec.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Když jsi běžel s pěšáky a unavili tě, jak chceš potom závodit s koňmi? Když se v pokojné zemi cítíš bezpečný, co budeš dělat v jordánské houštině?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Vždyť i tvoji bratři a ⌈dům tvého otce,⌉ i oni tě podvedli, i oni za tebou hlasitě pokřikují. Nevěř jim, i když s tebou mluví hezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Opustil jsem svůj dům, zanechal jsem své dědictví, vydal jsem svou milovanou do moci jejích nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mé dědictví se pro mě stalo podobné lvu v houštině, pozvedlo proti mně svůj hlas, proto ho nenávidím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Cožpak mi není mé dědictví skvrnitým dravcem? Což okolo něj nejsou jiní dravci? Jděte, shromážděte všechnu polní zvěř, přijďte ⌈se nažrat!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Mnozí pastýři zničili mou vinici, pošlapali můj díl pole, proměnili můj vzácný díl ve zcela opuštěnou pustinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Učinili ji zcela opuštěnou, zpustošená přede mnou truchlí. Celá země je zpustošená a ⌈nikdo si to nebere k srdci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Na všechna holá návrší v pustině přicházejí ničitelé, protože Hospodin má meč, který požírá ⌈od jednoho konce země až na druhý⌉ a ⌈nikdo ne má pokoj.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Zaseli pšenici, ale sklidili trní; ⌈unavili se, ale nic tím nezískali.⌉ Styďte se za svou úrodu kvůli Hospodinovu planoucímu hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Toto praví Hospodin: O všech mých zlých sousedech, kteří sahají na dědictví, jež jsem dal do vlastnictví svému lidu, Izraeli: Hle, vyrvu je z jejich země a dům judský vyrvu z jejich středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'I stane se, že až je vyrvu, znovu se nad nimi slituji a přivedu je zpět, každého do jeho dědictví a každého do jeho země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'A jestliže se opravdu naučí cestám mého lidu a budou přísahat v mém jménu: Jakože živ je Hospodin, tak jako učili můj lid přísahat při Baalovi, pak budou zbudováni uprostřed mého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Jestliže však nebudou poslouchat, zcela onen národ vyrvu a vyhubím, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Hospodin mi řekl toto: Jdi a kup si lněný pás. Vezmi si ho na bedra, ale do vody ho nedávej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Koupil jsem si podle Hospodinova slova pás a vzal si ho na bedra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Stalo se ke mně Hospodinovo slovo podruhé:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Vezmi pás, který jsi koupil a jenž je na tvých bedrech; vstaň, jdi k Para a skryj ho tam ve skalní rozsedlině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Šel jsem a skryl jsem ho u Para, jak mi přikázal Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Po mnoha dnech se stalo, že mi Hospodin řekl: Vstaň, jdi k Para a vezmi odtamtud pás, který jsem ti přikázal tam skrýt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Šel jsem tedy k Para, ⌈vykopal jsem ten pás a vzal ho ⌉ z místa, kam jsem ho ukryl. A hle, pás byl zničen, ne byl vůbec k ničemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Tu se ke mně stalo Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Toto praví Hospodin: Takto zničím pýchu Judy i velkou pýchu Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Tento zlý lid, který odmítá poslouchat má slova, žije podle svého umíněného srdce a chodí za jinými bohy, aby jim sloužil a klaněl se jim, dopadne jako tento pás, který ne ní vůbec k ničemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Protože tak jako pás přiléhá k bedrům muže, tak jsem k sobě přivinul celý dům izraelský a celý dům judský, je Hospodinův výrok, aby byl mým lidem, věhlasem, chválou a slávou, ale neposlouchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Řekni jim toto slovo: Toto praví Hospodin, Bůh Izraele: Každý džbán bude naplněn vínem. Řeknou ti: Copak to nevíme, že každý džbán bude naplněn vínem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Řekni jim: Toto praví Hospodin: Hle, naplňuji opilostí všechny obyvatele této země, krále, kteří sedí ⌈na Davidově trůnu,⌉ kněze, proroky i všechny obyvatele Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Roztříštím je ⌈jednoho o druhého,⌉ otce spolu se syny, je Hospodinův výrok, nebudu mít soucit, ani lítost, neslituji se, dokud je nezničím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Slyšte a poslouchejte, nepovyšujte se, protože Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Vzdejte slávu Hospodinu, svému Bohu, dříve nežli způsobí tmu, dříve nežli vaše nohy za soumraku klopýtnou na horách. Budete čekat na světlo, ale on ho promění v nejhlubší tmu, učiní ho hustou temnotou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Jestliže ⌈toto varování ⌉ neuposlechnete, ve skrytu se moje duše rozpláče nad vaší pýchou, bude hořce plakat, z mých očí poplynou slzy, protože Hospodinovo stádo bude vzato do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Řekni králi a královně: ⌈Sesedněte dolů,⌉ protože vaše krásná koruna spadne z vašich hlav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Jižní města budou zavřena a nebude, kdo by je otevřel; celý Juda bude vzat do zajetí, zcela vzat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Pozvedni oči a podívej se na ty, kteří přicházejí od severu. Kde je stádo, které ti bylo dáno, ⌈tvé krásné ovce?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Co řekneš, až nad tebou ustanoví za vůdce ty, které ses naučila mít za důvěrníky? Zdali tě nezachvátí bolesti jako rodící ženu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Když se zeptáš ve svém srdci: Proč mě tohle postihlo? Pro množství tvých vin zvedli tvoje sukně, ⌈natloukli ti na zadek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Cožpak může Kúšijec změnit svou kůži, anebo leopard svoje skvrny? Pak také vy dokážete konat dobro, když jste si zvykli páchat zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Rozptýlím je jako plevy hnané stepním větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Toto je tvůj úděl, ⌈míra, již jsem ti odměřil,⌉ je Hospodinův výrok, za to, že jsi na mne zapomněla a spoléhala na klam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'I já zvednu tvoje sukně přes tvou tvář a bude vidět tvoje hanba,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'tvé cizoložství a tvoje žádostivost, tvé hnusné smilstvo. Na návrších i na poli jsem viděl tvé ohavné modly. Běda ti, Jeruzaléme! ⌈Jak dlouho ještě budeš nečistý?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Hospodinovo slovo, které se stalo k Jeremjášovi ohledně velkého sucha:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juda truchlí a jeho brány se zhroutily; ⌈v chmurách leží na zemi⌉ a křik Jeruzaléma stoupá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Jejich vznešení posílají své služebníky pro vodu; přicházejí k cisternám, vodu nenacházejí a vracejí se s prázdnými nádobami. Stydí se, jsou zahanbeni a zakrývají si hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Kvůli rozpraskané zemi -- protože v zemi není déšť -- se zemědělci stydí a zakrývají si hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Také laň na poli rodí a opouští svá mláďata, protože není tráva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Divoké oslice postávají na návrších, lapají po dechu jako šakali, jejich zrak slábne, protože není zeleň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ačkoliv proti nám svědčí naše viny, Hospodine, jednej pro své jméno, protože našich odvrácení je mnoho, hřešili jsme proti tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Naděje Izraele, jeho spasiteli v čas soužení, proč bys měl být v zemi jako cizinec a jako poutník, který si postavil stan jenom k přenocování?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Proč bys měl být jako ohromený muž, jako hrdina, který nedokáže zachránit? Ale ty, Hospodine, jsi uprostřed nás, nazýváme se tvým jménem. Neopouštěj nás!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Toto praví Hospodin o tomto lidu: Že si tak zamilovali toulky a ⌈své nohy nekrotili,⌉ proto si je Hospodin neoblíbil; nyní bude pamatovat na jejich viny a navštíví s trestem jejich hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Pak mi Hospodin řekl: Nemodli se za tento lid, za jeho dobro.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Když se budou postit, jejich volání nevyslyším, až budou přinášet zápalnou a přídavnou oběť, nenajdu v nich zalíbení, ale skoncuji s nimi ⌈mečem a hladem a morem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Řekl jsem: Ach, Panovníku Hospodine! Hle, proroci jim říkají: Nezažijete meč, nebudete mít hlad, ale dám vám na tomto místě trvalý pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Hospodin mi řekl: Klam prorokují proroci v mém jménu. Neposlal jsem je a nepřikázal jsem jim nic, nemluvil jsem k nim. Prorokují vám klamné vidění, věštbu, nicotnost a podvod svého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Proto takto praví Hospodin o prorocích, kteří prorokují v mém jménu, ačkoliv jsem je neposlal, a kteří říkají, že v této zemi meč ani hlad nebude: Mečem a hladem zahynou tito proroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'A lid, kterému prorokují, bude kvůli hladu a meči vržen na ulice Jeruzaléma. Nebude kdo by je pohřbil, je, jejich ženy, jejich syny ani jejich dcery; tak na ně vyleji jejich zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Řekni jim tato slova: Z mých očí plynou slzy ⌈nocí i dnem,⌉ ne jsou k zastavení, neboť panna, dcera mého lidu, je zasažena velkou zkázou, zcela nevyléčitelnou ranou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Když vyjdu na pole, podívej -- probodení mečem; když přijdu do města, podívej -- nemocní hladem; protože jak prorok, tak i kněz procházejí zemi, obchodují a mě neznají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Cožpak jsi Judu zcela zavrhl? Opravdu si tvá duše Sijón zošklivila? Proč jsi nás ranil, takže pro nás není uzdravení? Čekáme pokoj, ale dobro není, čas uzdravení, a hle, jen hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Hospodine, známe svoji ničemnost, vinu našich otců, vždyť jsme hřešili proti tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Pro své jméno neopovrhuj Jeruzalémem, nejednej opovržlivě ⌈ s trůnem své slávy!⌉ Rozpomeň se na ni a neruš svou smlouvu s námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Cožpak jsou mezi nicotnými modlami národů takové, které působí déšť? Zdalipak nebesa vydávají sama od sebe přeháňky? Copak to nejsi ty, Hospodin, náš Bůh? Na tebe čekáme, protože ty činíš všechny tyto věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Hospodin mi řekl: I kdyby se přede mne postavili Mojžíš a Samuel, moje duše nebude nakloněna k tomuto lidu. Pošli je ⌈ode mě⌉ pryč, ať odejdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Až se tě zeptají: Kam půjdeme? odpověz jim: Toto praví Hospodin: Kdo je určen k smrti, na smrt, kdo pro meč, pod meč, kdo pro hlad, do hladu a kdo pro zajetí, do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Určím nad nimi čtyři druhy ničení, je Hospodinův výrok: Meč, aby zabíjel, psy, aby odvlékali, nebeské ptáky a zemskou zvěř, aby žrali a ničili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Učiním je úděsem pro všechna království země, kvůli judskému králi Menašemu, synu Chizkijášovu, za to, co páchal v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Vždyť kdo s tebou bude mít soucit, Jeruzaléme? Kdo ti projeví účast? Kdo odbočí, aby se zeptal, jak se ti daří?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Ty jsi mě opustil, je Hospodinův výrok, a ukazuješ mi záda; vztáhl jsem proti tobě svou ruku a zničil tě. Už jsem unaven slitováváním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Provál jsem je věječkou v branách země. Učinil jsem svůj lid bezdětným a zahubil jej, protože se neodvrátili od svých cest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Jeho vdov je bezpočtu, víc než mořského písku; za poledne jsem na ně, na matky mládenců, přivedl ničitele; náhle jsem na ně nechal dopadnout hrůzu a děs.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Uvadla rodička sedmi synů, vydechla svou duši. Její slunce zašlo, ještě když byl den; styděla se a byla zahanbena. Jejich ostatek vydám meči před jejich nepřáteli, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Běda mi, má matko, že jsi mě porodila, muže hádky a ⌈muže sváru⌉ pro celou zemi! Nepůjčoval jsem, ani mi nepůjčovali, a přece mě všichni proklínají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Hospodin řekl: Copak jsem ⌈ti nesloužil k dobru?⌉ Copak jsem nezpůsobil, že se na tebe nepřítel obracel v čase zla a soužení s prosbou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Cožpak se dá ⌈zlomit železo, železo⌉ ze severu, a bronz?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Tvůj majetek a tvůj poklad vydám jako kořist, ⌈ne za úhradu,⌉ a to kvůli všem tvým hříchům, páchaným na celém tvém území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Způsobím, že tvoji nepřátelé tě ⌈přivedou do země,⌉ kterou neznáš, protože mým hněvem byl zanícen oheň, který bude hořet proti vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ty to víš, Hospodine, pamatuj na mě, ⌈postarej se o mne⌉ a pomsti se za mě na těch, kdo mě pronásledují. ⌈Pro svou trpělivost mě neodvrhuj.⌉ Věz, že kvůli tobě snáším posměch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Byla nalezena tvá slova a snědl jsem je. Tvé slovo mi bylo k jásotu a k radosti mého srdce, protože mě nazývá tvým jménem, Hospodine, Bože zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Nesedával jsem při důvěrném setkání vtipálků a ne radoval se; kvůli tvé ruce jsem seděl sám, protože jsi mě naplnil rozhořčením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Proč je má bolest trvalá a moje rána nevyléčitelná, nechce se uzdravit? Opravdu mi budeš jako klamný potok, nespolehlivá voda?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Proto takto praví Hospodin: Jestliže se obrátíš, přivedu tě zpět a budeš zase stát přede mnou, jestliže oddělíš vzácné od bezcenného, budeš jako má ústa. Ať se oni obrátí k tobě, ale ty se k nim neobracej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Učiním tě tomuto lidu pevnou bronzovou hradbou. Budou proti tobě bojovat, ale nepřemohou tě, protože já jsem s tebou, abych tě zachránil a vysvobodil, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Vysvobodím tě z ruky zlých lidí a vykoupím tě z moci násilníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Neber si ženu a neměj na tomto místě syny a dcery,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'protože toto praví Hospodin o synech a dcerách, zrozených na tomto místě, a o jejich matkách, které je porodily, a o jejich otcích, kteří je zplodili v této zemi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Zemřou na smrtelné nemoci. Nebudou oplakáváni ani pohřbeni. Budou jako hnůj na povrchu země, zajdou mečem a hladem. Jejich mrtvoly se stanou potravou nebeského ptactva a zemské zvěře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Neboť toto praví Hospodin: Nevstupuj do domu smutku, nechoď naříkat a neprojevuj jim účast, protože od tohoto lidu odejmu svůj pokoj, je Hospodinův výrok, ⌈ své milosrdenství i slitování.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'V této zemi zemřou velcí i malí, nebudou pohřbeni, ani je nebudou oplakávat, nikdo si kvůli nim nebude zasazovat rány, ani vyholovat hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Na smutečním obřadu nebudou lámat chléb, aby poskytli útěchu nad zemřelým, nedají jim napít z kalicha útěchy nad jejich otcem či matkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Nevstupuj do domu hostiny, abys s nimi seděl, jedl a pil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Neboť toto praví Hospodin zástupů, Bůh Izraele: Hle, způsobím, že zmizí na tomto místě, před vašimi zraky a za vašich dnů hlas jásotu i hlas radosti, hlas ženicha i hlas nevěsty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Stane se, až oznámíš tomuto lidu všechna tato slova, že ti řeknou: Proč Hospodin proti nám vyslovil všechno toto veliké zlo? Jaká je naše vina? Jaký je náš hřích, kterým jsme zhřešili proti Hospodinu, svému Bohu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Řekni jim: Protože mě vaši otcové opustili, je Hospodinův výrok, a chodili za jinými bohy, sloužili jim a klaněli se jim; a mne opustili a můj zákon nezachovávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'A vy jste páchali ještě větší zlo, nežli vaši otcové; hle, žijete každý podle svého umíněného a zlého srdce a mne neposloucháte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Proto vás vyvrhnu z této země do země, kterou jste neznali vy ani vaši otcové; tam budete sloužit ve dne i v noci jiným bohům, protože se nad vámi neslituji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Ale hle, přicházejí dny, je Hospodinův výrok, kdy se už nebude říkat: Jakože živ je Hospodin, který vyvedl syny Izraele z egyptské země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'nýbrž: Jakože živ je Hospodin, který vyvedl syny Izraele ze severní země a ze všech zemí, kam je zahnal. A přivedu je zpět ⌈do jejich země,⌉ kterou jsem dal jejich otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Hle, posílám pro mnoho rybářů, je Hospodinův výrok, a budou je chytat jako ryby a potom pošlu pro mnoho lovců a budou je lovit ze všech hor a ze všech návrší a ze skalních trhlin,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'neboť moje oči hledí na všechny jejich cesty; nejsou přede mnou ukryty a jejich vina se před mým zrakem neskryje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Avšak nejprve odplatím dvojnásobně za jejich vinu a jejich hřích, protože znesvětili mou zemi mrtvolami svých ohavných model a mé dědictví naplnili svými odpornými věcmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Hospodine, moje sílo a má záštito, mé útočiště v den soužení, k tobě přijdou národy od končin země a řeknou: Naši otcové jistě zdědili klam, nicotné modly, které neprospějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Cožpak si lidé mohou udělat bohy? To přece nejsou bohové!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Proto hle, přivedu je k poznání, tentokrát jim dám poznat svoji moc a svoji udatnost a poznají, že mé jméno je Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Judův hřích je zapsán železným rydlem, diamantovým hrotem; je vyryt na tabulku jejich srdcí a na rohy vašich oltářů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Jejich synové myslí na své oltáře a na své posvátné kůly, na zelené stromy, na vyvýšená návrší,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, '⌈ na horách, na poli. Tvůj⌉ majetek a všechny tvé poklady vydám za kořist, tvá návrší kvůli hříchu páchanému na celém tvém území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Opustíš, a to kvůli sobě, své dědictví, které jsem ti dal, a nechám tě otročit tvým nepřátelům v zemi, kterou neznáš; protože jste zanítili oheň mého hněvu, a ten bude hořet navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Toto praví Hospodin: Prokletý je muž, který spoléhá na člověka, tělo pokládá za svou sílu a jeho srdce se odvrací od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Bude jako jalovec v pustině, neuvidí, když přijde dobro, usídlí se na vyprahlých místech v pustině, v solné, neobydlené zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Požehnaný je muž, který spoléhá na Hospodina a jehož nadějí je Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Bude jako strom zasazený u vody, zapustí své kořeny u potoka; nebojí se, když přijde žár, jeho listí bude zelené; neobává se ani v roce velkého sucha, nepřestává nést ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Srdce je ⌈lstivé nade vše,⌉ je nevyléčitelné. Kdo mu porozumí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Já, Hospodin, zkoumám ⌈srdce a zkouším ledví,⌉ abych každému dal podle jeho cest, podle ovoce jeho činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Podobný koroptvi, která sedí na vejcích, ⌈ale nezplodí mladé,⌉ je ten, kdo neprávem získává bohatství; uprostřed ⌈svého života⌉ ho opustí a na konci bude vypadat jako blázen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Trůne slávy, vyvýšený od počátku, místo naší svatyně!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Naděje Izraele, Hospodine! Všichni, kdo tě opouštějí, se budou stydět. Ti, kteří se ⌈ od tebe⌉ odvrátili, budou zapsáni do země stínů, protože opustili pramen živé vody, Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Uzdrav mě, Hospodine, a budu uzdraven, zachraň mě a budu zachráněn, ⌈protože ty jsi má chvála.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Hle, oni mi říkají: Kde je Hospodinovo slovo? Ať konečně přijde!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, '⌈Já jsem se nedral, abych byl tvým pastýřem,⌉ netoužil jsem po žalostném dni. Ty znáš to, co vyšlo z mých rtů, bylo to před tvou tváří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Nebuď mi postrachem, ty jsi moje útočiště ve zlý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Ať jsou zahanbeni ti, kdo mě pronásledují, ale já ať zahanben nejsem; oni ať jsou vyděšeni, ale já ať vyděšen nejsem. Přiveď na ně zlý den, zlom je dvojnásobným zlomením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Hospodin mi řekl toto: Jdi a postav se v bráně synů lidu, kterou vcházejí a vycházejí judští králové, a ve všech jeruzalémských branách');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'a řekni jim: Slyšte Hospodinovo slovo, judští králové, všichni Judejci i všichni obyvatelé Jeruzaléma, kteří vcházíte těmito branami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Toto praví Hospodin: ⌈Kvůli svému životu se mějte na pozoru⌉ a v sobotní den nenoste náklad ani ho ne vnášejte jeruzalémskými branami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Nevynášejte v sobotní den náklad ze svých domů, nedělejte žádnou práci, ale svěťte sobotní den, jak jsem přikázal vašim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Avšak neposlouchali a nenakláněli ucho, ale zatvrdili svou šíji, aby neposlouchali a nepřijímali kázeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Stane se, jestliže mě opravdu uposlechnete, je Hospodinův výrok, a nebudete v sobotní den vnášet branami tohoto města žádný náklad, ale budete světit sobotní den a nebudete v něm dělat žádnou práci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'že pak budou vcházet branami tohoto města králové a knížata, kteří sedí na Davidově trůnu, kteří jezdí na voze a na koních, oni i jejich knížata, judští muži a obyvatelé Jeruzaléma a toto město bude obydlené navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Pak přijdou lidé z judských měst, z okolí Jeruzaléma, ze země Benjamín, ze Šefely, z pohoří a z Negebu a přinesou zápalnou oběť, obětní hod, přídavnou oběť a kadidlo a přinesou oběť díků do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Ale jestliže mě neuposlechnete, abyste světili sobotní den a nenosili náklad a ne vcházeli v sobotní den jeruzalémskými branami, potom zapálím v jeho branách oheň a stráví jeruzalémské paláce a neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Vstaň a sestup do hrnčířova domu a tam ti oznámím svá slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Sestoupil jsem tedy do hrnčířova domu. Právě ⌈zhotovoval výrobek⌉ na ⌈hrnčířském kruhu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Nádoba, kterou z hlíny dělal, se v hrnčířově ruce pokazila. Předělal ji v jinou nádobu, tak jak to ⌈hrnčířovi připadalo správné.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Cožpak s vámi nemohu učinit to, co učinil tento hrnčíř, dome izraelský? je Hospodinův výrok. Hle, jako je v hrnčířově ruce hlína, tak jste v mé ruce vy, dome izraelský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Jednou promluvím o národu a o království, že je vyvrátím, zničím a vyhubím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'ale když se ten národ, o kterém jsem promluvil, od svého zla odvrátí, budu litovat toho zla, které jsem zamýšlel mu učinit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Jindy promluvím o národu a o království, že je zbuduji a zasadím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'ale když bude páchat to, ⌈co je zlé v mých očích,⌉ a nebude mě poslouchat, budu litovat dobra, které jsem řekl, že mu prokážu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Teď tedy řekni judským mužům a obyvatelům Jeruzaléma: Toto praví Hospodin: Hle, já proti vám tvořím zlo a vymýšlím proti vám plán. Odvraťte se každý od své zlé cesty a dejte do pořádku své cesty a své činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Říkají však: Není naděje, protože budeme žít podle svých plánů a každý bude jednat podle svého umíněného a zlého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Proto takto praví Hospodin: Ptejte se mezi národy! Slyšel někdo něco takového? Něco velmi otřesného spáchala panna izraelská!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Cožpak sníh Libanonu opustí skalní útesy Sirjónu či vyschne horská, chladná a bystrá voda?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Ale můj lid na mě zapomněl. ⌈Nadarmo pálí oběti. Klopýtli na svých⌉ cestách, věčných stezkách, aby šli pěšinami, nepřipravenou cestou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'aby učinili svou zemi předmětem hrůzy a věčného ⌈úžasu; každý, kdo jí bude procházet, se zhrozí a bude potřásat⌉ hlavou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Rozptýlím je před nepřítelem jako východní vítr; v den jejich pohromy jim dám vidět záda, a ne tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Oni však řekli: Pojďte, ukujeme proti Jeremjášovi plán. Vždyť knězi nechybí zákon, ani rada mudrci, ani slovo prorokovi. Pojďte, ubijeme ho jazykem a jeho slovům nebudeme vůbec věnovat pozornost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Hospodine, věnuj mi pozornost a slyš hlas mých protivníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Cožpak se za dobro odplácí zlem? A přece pro mou duši vykopali jámu! Pamatuj, že jsem stával před tebou, abych se přimlouval za jejich dobro, abych od nich odvracel tvůj hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Proto vydej jejich syny hladu. Uvrhni je v moc meče, jejich ženy ať se stanou bezdětnými a vdovami, jejich muže ať skosí smrt, jejich mládence ať ve válce pobije meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Z jejich domů ať je slyšet volání o pomoc, až na ně náhle přivedeš loupežnou hordu, protože vykopali jámu, aby mě polapili a mým nohám nastražili pasti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Hospodine, ty znáš všechny jejich plány jak mě usmrtit. Nedej se usmířit za jejich vinu a jejich hřích ať před tebou není vymazán. Ať před tebou klopýtnou, jednej s nimi v čase svého hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Hospodin řekl toto: Jdi a kup hliněnou lahvici vytvořenou hrnčířem. Vezmi s sebou některé ze starších lidu a ze starších kněží');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'a vyjdi do údolí Hinómova syna, které leží u vchodu do Střepné brány a volej tam slova, která k tobě budu mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Řekni: Slyšte Hospodinovo slovo, judští králové a obyvatelé Jeruzaléma. Toto praví Hospodin zástupů, Bůh Izraele: Hle, přivedu na toto místo takové zlo, že každému, kdo o něm uslyší, bude znít v uších,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'protože mě opustili a odcizili mi toto místo, pálili na něm oběti jiným bohům, které neznali oni, ani jejich otcové, ani judští králové a naplnili toto místo krví nevinných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Vystavěli Baalova návrší, aby své syny spalovali ohněm jako zápalné oběti Baalovi, což jsem nepřikázal, ani jsem o tom nemluvil, ani mi to nepřišlo na mysl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Proto hle, přicházejí dny, je Hospodinův výrok, kdy se už toto místo nebude nazývat Tófet, ani údolí Hinómova syna, ale údolí zabíjení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Na tomto místě zmařím plán Judejců a obyvatel Jeruzaléma a před jejich nepřáteli je nechám padnout mečem a rukou těch, kdo usilují o jejich život. Jejich mrtvoly vydám za potravu nebeského ptactva a zemské zvěře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Učiním toto město předmětem hrůzy a úžasu; každý, kdo jím bude procházet, se zhrozí a podiví se všem jeho ranám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Způsobím, že budou jíst maso svých synů a maso svých dcer; budou jíst maso jeden druhého v obležení a v úzkosti, kterou jim přivodí jejich nepřátelé a ti, kdo usilují o jejich život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Potom před očima mužů, kteří půjdou s tebou, rozbij lahvici');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'a řekni jim: Toto praví Hospodin zástupů: Tak jako se rozbije hrnčířova nádoba, že ji už není možné dát dohromady, tak rozbiji tento lid a toto město. V Tófetu budou pohřbívat, až už ne bude místo k pohřbívání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'To udělám tomuto místu, je Hospodinův výrok, a jeho obyvatelům a učiním toto město podobné Tófetu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Jeruzalémské domy a domy judských králů budou nečisté jako místo Tófet -- všechny domy, na jejichž střechách pálili oběti celému nebeskému zástupu a lili úlitby jiným bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Jeremjáš přišel z Tófetu, kam ho Hospodin poslal prorokovat, postavil se na nádvoří Hospodinova domu a řekl všemu lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Toto praví Hospodin zástupů, Bůh Izraele: Hle, přivedu na toto město a na všechna jeho města všechno to zlo, které jsem proti němu mluvil, protože zatvrdili svou šíji a má slova neposlouchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Když kněz Pašchúr, syn Imerův, který byl vrchním dohlížitelem v Hospodinově domě, uslyšel Jeremjáše prorokovat tato slova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Pašchúr proroka Jeremjáše udeřil a dal ho do klády, která byla v Horní Benjamínově bráně, jež je v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Příštího dne se stalo, že Pašchúr vyvedl Jeremjáše z klády. Jeremjáš mu řekl: Hospodin tě nepojmenoval Pašchúr, ale: Magórmi–sábíb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'protože toto praví Hospodin: Hle, vydám tě hrůze, tebe a všechny tvé přátele. Padnou mečem svých nepřátel a tvoje oči se na to budou dívat. ⌈Celého Judu⌉ vydám do ruky babylonského krále a odvedu je do Babylona a pobiji je mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Vydám všechno bohatství tohoto města, všechen jeho majetek, všechny jeho drahocennosti; všechny poklady judských králů vydám do ruky jejich nepřátel. Ukořistí je, vezmou je a odnesou je do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'A ty, Pašchúre, i všichni obyvatelé tvého domu, půjdete do zajetí. Přijdeš do Babylona a tam zemřeš. Tam budeš pohřben ty i všichni tvoji přátelé, kterým jsi lživě prorokoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, '⌈Přemlouvals mě,⌉ Hospodine, a dal jsem se přemluvit. Přemáhal jsi mě a zdolal. Celý den jsem na posměch, všichni se mi posmívají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Protože pokaždé, když promluvím, křičím a vyhlašuji: Násilí a zkáza. Ano, Hospodinovo slovo se mi stalo zdrojem potupy a pošklebků po celý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Řekl jsem si: Už ho nebudu připomínat, ani mluvit v jeho jménu, ale jeho slovo se stalo v mém srdci jakoby planoucím ohněm zadržovaným v mých kostech. ⌈Namáhal jsem se ho v sobě zadržet,⌉ ale nedokážu to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Vždyť slyším šeptání ⌈mnohých: Všude kolem⌉ hrůza. Udejte ho, udáme ho. ⌈Všichni moji důvěrní přátelé⌉ čekají na můj pád: Možná se dá svést, pak ho zdoláme a pomstíme se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Ale Hospodin je se mnou jako udatný hrdina, proto se ti, kdo mě pronásledují, zapotácejí a nepřemohou mne. Budou se velmi stydět, protože jednali nerozumně, jejich věčná ostuda nebude zapomenuta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Hospodine zástupů, který zkoumáš spravedlivého a vidíš ledví i srdce, kéž na nich uzřím tvou pomstu, protože tobě jsem přenechal svůj spor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Zpívejte Hospodinu, chvalte Hospodina, protože vysvobodil duši nuzného z ruky zločinců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Ať je proklet den, ve kterém jsem byl zrozen; ať není požehnán den, kdy mě má matka porodila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Ať je proklet muž, který přinesl mému otci zprávu: Narodil se ti syn, chlapec a udělal mu tím velikou radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Ať je ten muž jako města, která Hospodin vyvrátil a neslitoval se; ať slyší ráno volání o pomoc a v polední čas křik,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'protože mě neusmrtil hned v matčině lůně; má matka by se mi stala mým hrobem a její lůno by zůstalo navěky těhotné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Proč jsem vyšel z matčina lůna? Abych viděl trápení a žal a mé dny minuly v hanbě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina, když k němu král Sidkijáš poslal Pašchúra, syna Malkijášova, a kněze Sefanjáše, syna Maasejášova, se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '⌈Dotaž se, prosím, za nás⌉ Hospodina, protože babylonský král Nebúkadnesar proti nám vede válku. Snad s námi Hospodin bude jednat podle všech svých dřívějších obdivuhodných činů a on od nás odtáhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Nato jim Jeremjáš řekl: Takto odpovězte Sidkijášovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Toto praví Hospodin, Bůh Izraele: Hle, obrátím válečné zbraně, které jsou ve vašich rukou, jimiž vedete válku proti babylonskému králi a proti Chaldejcům, kteří vás obléhají venku za hradbami, a shromáždím je doprostřed tohoto města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Já sám budu bojovat proti vám ⌈vztaženou rukou a silnou paží,⌉ v hněvu, v zlobě a ve velikém rozhořčení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'a pobiji obyvatele tohoto města, lidi i zvěř. Zemřou velkým morem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Potom, je Hospodinův výrok, vydám judského krále Sidkijáše, jeho otroky, lid a ty, kteří zůstanou v tomto městě po moru, meči a hladu, do ruky babylonského krále Nebúkadnesara, do ruky jejich nepřátel a do ruky těch, kdo usilují o jejich život. Pobije je ostřím meče, neslituje se nad nimi, nebude mít soucit ani slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'A tomuto lidu řekni: Toto praví Hospodin: Hle, kladu před vás cestu života a cestu smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Ten, kdo zůstane v tomto městě, zemře mečem, hladem a morem; ale ten, kdo vyjde a přeběhne ke Chaldejcům, kteří vás obléhají, bude žít, ⌈kořistí se mu stane jeho duše.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Protože jsem obrátil svou tvář proti tomuto městu ke zlu a ne k dobru, je Hospodinův výrok, bude vydáno do ruky babylonského krále a ten ho spálí ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Domu judského krále řekni: Slyšte Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Dome Davidův, toto praví Hospodin: Zrána pomozte získat právo a vysvoboďte okradeného z ruky utlačovatele, jinak vyšlehne můj hněv jako oheň, vzplane a kvůli vašim zvráceným činům neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Hle, jsem proti tobě, obyvatelko údolí, skálo roviny, je Hospodinův výrok. Říkáte: Kdo by nás napadl? Kdo by pronikl do našich příbytků?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Navštívím vás za ovoce vašich činů, je Hospodinův výrok, zapálím oheň v jejím lese a ten stráví celé její okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Toto praví Hospodin: Sestup do paláce judského krále a mluv tam toto slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Řekni: Slyš Hospodinovo slovo, judský králi, který sedíš na Davidově trůnu, ty i tvoji otroci i tvůj lid, který vchází do těchto bran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Toto praví Hospodin: Vykonávejte právo a spravedlnost, vysvoboďte okradeného z ruky utlačovatele. Neutiskujte příchozího, sirotka ani vdovu a nejednejte s nimi násilně. Neprolévejte na tomto místě nevinnou krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Jestliže toto slovo budete opravdu činit, pak budou do bran tohoto domu vcházet králové, kteří ⌈budou po Davidovi sedět na jeho trůnu⌉ a budou jezdit na voze a na koních, oni a jejich otroci a jejich lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Jestliže však tato slova neuposlechnete, přísahám při sobě, je Hospodinův výrok, že se tento dům stane troskami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Neboť toto praví Hospodin ohledně domu judského krále: Jsi pro mne jako Gileád, jako vrchol Libanonu; avšak učiním tě pustinou, neobydlenými městy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Nachystám na tebe ničitele, každého s jeho zbraněmi, a vytnou tvoje nejlepší cedry a nechají je padnout na oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Mnohé národy budou procházet kolem tohoto města a budou se ptát jeden druhého: Proč tohle Hospodin tomuto velkému městu provedl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'A budou odpovídat: Protože opustili smlouvu Hospodina, svého Boha, klaněli se jiným bohům a sloužili jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Neplačte nad zemřelým a nenaříkejte nad ním! ⌈Plačte raději⌉ nad tím, kdo odchází, protože se už nenavrátí a ne uvidí svou rodnou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Neboť toto praví Hospodin o judském králi Šalúmovi, synu Jóšijášovu, který kraloval po svém otci Jóšijášovi a jenž vyšel z tohoto místa: Už se sem nenavrátí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'protože na tom místě, kam ho odvedli, zemře, a už tuto zemi nikdy neuvidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Běda tomu, kdo staví svůj dům nespravedlivě a své horní místnosti s bezprávím, kdo nechává sloužit svého bližního zadarmo a nedává mu mzdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Kdo říká: Vystavím si rozměrný dům s prostornými horními místnostmi. Vyseká v něm okna, obloží ho cedrovým dřevem a natře ho ⌈červenou barvou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, '⌈Staneš se snad králem, protože všechny předčíš cedrovým dřevem?⌉ ⌈Cožpak tvůj otec ne měl co jíst a pít, ačkoliv vykonával⌉ právo a spravedlnost? Tehdy mu bylo dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Pomáhal získat právo ⌈chudému a nuznému,⌉ tehdy bylo dobře. ⌈Neznamená toto znát mě?⌉ je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Avšak tvoje oči i tvé srdce je zaměřeno jen na tvůj nekalý zisk, na prolévání krve nevinného, na provádění útlaku a vydírání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Proto takto praví Hospodin o judském králi Jójakímovi, synu Jóšijášovu: Nebudou ho oplakávat: Ach, můj bratře! Ach, sestro! Nebudou ho oplakávat: Ach, pane! Ach, jeho Veličenstvo!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Bude pohřben pohřbem osla, vyvlečen a pohozen za jeruzalémskými branami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Vystup na Libanon, jeruzalémská dcero, a křič, v Bášanu pozvedni svůj hlas; křič z Abarímu, protože všichni tví milenci jsou rozdrceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Mluvil jsem k tobě ve tvé bezstarostnosti, ale řekla jsi: Nebudu poslouchat. To byl tvůj způsob od tvého mládí, že jsi mě neposlouchala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Všechny tvé pastýře spase vítr a tvoji milenci půjdou do zajetí. Tehdy se budeš stydět a budeš zahanbena pro všechno své zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Ty, která ses usadila na Libanonu, která ses uhnízdila v cedroví, jak budeš vzdychat až na tebe přijdou bolesti, porodní bolesti jako na rodičku!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, '⌈ Jakože jsem živ,⌉ je Hospodinův výrok, i kdyby byl judský král Konjáš, syn Jójakímův, pečetním prstenem na mé pravé ruce, přece tě odtamtud strhnu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'a vydám tě do ruky těch, kdo usilují o tvůj život a do ruky těch, jichž se strachuješ, do ruky babylonského krále Nebúkadnesara a do ruky Chaldejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Vyvrhnu tebe i tvou matku, která tě porodila, do jiné země, kde jste se nenarodili a tam zemřete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Do země, kam se jejich duše touží navrátit, tam se nenavrátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Cožpak je tento muž, Konjáš, opovrženou a rozbitou nádobou? Zdalipak je nádobou, v níž nikdo ne má zalíbení? Proč je on a jeho potomstvo odmrštěno a uvrženo do země, kterou neznali?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Země, země, země, slyš Hospodinovo slovo!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Toto praví Hospodin: Zapište tohoto muže jako bezdětného, jako muže, který ve svých dnech neuspěje, neboť nikdo z jeho potomstva neuspěje, aby seděl na Davidově trůnu a znovu vládl nad Judou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Běda pastýřům, kteří hubí a rozptylují ovce mé pastvy, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Proto takto praví Hospodin, Bůh Izraele, o pastýřích, kteří pasou můj lid: Vy jste rozptýlili mé ovce, rozehnali je a nestarali se o ně. Hle, postarám se o vás za vaše zvrácené činy, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Já sám shromáždím ostatek svých ovcí ze všech zemí, kam jsem je rozehnal, přivedu je zpět na jejich pastvinu, budou plodné a rozmnoží se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, '⌈Ustanovím jim⌉ pastýře a budou je pást; nebudou se už bát ani děsit a nebudou pohřešovány, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Hle, přicházejí dny, je Hospodinův výrok, kdy vzbudím Davidovi spravedlivý Výhonek. Bude kralovat jako král, jednat rozumně a vykonávat v zemi právo a spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, '⌈V jeho dnech⌉ bude Juda zachráněn a Izrael bude bydlet v bezpečí. Toto bude jeho jméno, kterým ho budou nazývat: Hospodin je naše spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Proto hle, přicházejí dny, je Hospodinův výrok, kdy se už nebude říkat: Jakože živ je Hospodin, který vyvedl izraelské syny z egyptské země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'ale: Jakože živ je Hospodin, který vyvedl a přivedl potomstvo domu izraelského ze severní země a ze všech zemí, kam jsem je zahnal. Pak budou bydlet ve své zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'O prorocích. Mé srdce je zlomeno v mém nitru, všechny mé kosti se třesou. Jsem jako opilec a jako muž ⌈zmožený vínem,⌉ kvůli Hospodinu a kvůli jeho svatým slovům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Vždyť země je plná cizoložníků, kvůli prokletí země uschla, stepní pastviny vyschly. ⌈Způsob jejich života⌉ je zlý, ⌈zneužívají svou sílu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Vždyť jak prorok, tak i kněz mě znesvěcují, dokonce i ve svém domě jsem nalezl jejich zlo, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Proto se jim jejich cesta stane ⌈kluzkou stezkou, budou vyhnáni do tmy a padnou v ní,⌉ protože na ně přivedu zlo, rok jejich navštívení, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'I na samařských prorocích jsem viděl bláznovství: Prorokovali ⌈skrze Baala⌉ a sváděli můj lid, Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Na jeruzalémských prorocích jsem viděl otřesnou věc: cizoloží a žijí ve lži. Posilují ruce zločinců, neodvracejí nikoho od jeho zla. Všichni jsou pro mě jako Sodoma a jeho obyvatelé jako Gomora.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Proto takto praví Hospodin zástupů o těch prorocích: Hle, nakrmím je pelyňkem a dám jim pít otrávenou vodu, protože od jeruzalémských proroků vyšla hanebnost do celé země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Toto praví Hospodin zástupů: Neposlouchejte slova proroků, kteří vám prorokují. ⌈Balamutí vás.⌉ Vyslovují vidění svého srdce a ne to, co je z Hospodinových úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, '⌈Těm, kteří mnou pohrdají, stále říkají: Hospodin promluvil:⌉ Budete mít pokoj a každému, kdo žije podle svého umíněného srdce, říkají: ⌈Nepřijde na vás zlo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Vždyť kdo z nich ⌈byl přítomen důvěrnému setkání s Hospodinem,⌉ aby viděl a slyšel jeho slovo? Kdo dával na jeho slovo pozor a uslyšel je?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Hle, spustila se Hospodinova vichřice hněvu, vířivý vichr. Bude vířit na hlavě ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Hospodinův hněv se neodvrátí, dokud ne vykoná a ne naplní plány jeho srdce. V posledních dnech tomu zcela porozumíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Neposlal jsem ty proroky, ale oni běželi, nemluvil jsem k nim, ale oni prorokovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Kdyby byli přítomni důvěrnému setkání se mnou, zvěstovali by mému lidu má slova, odvrátili by je od jejich zlé cesty a od jejich zvrácených činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Cožpak jsem Bohem jen nablízku, je Hospodinův výrok, a ne také Bohem v dáli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'I když se někdo ukryje ve skrýších, copak ho já neuvidím? je Hospodinův výrok. Cožpak nenaplňuji nebesa i zemi?, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Slyšel jsem, co říkali proroci, kteří v mém jménu prorokují klam: Měl jsem sen, měl jsem sen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Jak dlouho bude v srdci proroků, kteří prorokují klam, ⌈kteří prorokují podvod svého srdce,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'myšlenka, že svými sny, jež vypravují jeden druhému, způsobí, že můj lid zapomene na mé jméno, tak jako na mé jméno zapomněli jejich otcové ⌈kvůli Baalovi?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Prorok, který má sen, ať vypravuje sen, a který má mé slovo, ať vyslovuje mé slovo pravdivě. ⌈Co je slámě do zrna?⌉ je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Cožpak ne ní mé slovo jako oheň, je Hospodinův výrok, a jako kladivo, které tříští skálu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Proto hle, jsem proti prorokům, je Hospodinův výrok, kteří má slova kradou jeden druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Hle, jsem proti prorokům, je Hospodinův výrok, kteří používají svůj jazyk a pronášejí výrok jako prorok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Hle, já jsem proti těm, kdo prorokují klamné sny, je Hospodinův výrok, vypravují je a svádějí můj lid svými klamy a svou nadutostí, ale já jsem je neposlal ani jim nic nepřikázal. Jistě tomuto lidu neprospějí, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Když se tě tento lid nebo prorok nebo kněz zeptá: Jaký je Hospodinův výnos? Řekneš jim: Vy jste to břemeno! Odvrhnu vás, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Když prorok, kněz anebo kdokoliv z lidu bude říkat: ⌈ To je Hospodinův výnos,⌉ takového člověka i jeho dům navštívím s trestem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, '⌈Toto říkejte jeden druhému a každý svému bratru:⌉ Co odpověděl Hospodin? Co řekl Hospodin?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Slova: Hospodinův výnos už nepřipomínejte, protože každému je výnosem jeho vlastní slovo. Překrucujete slova živého Boha, Hospodina zástupů, našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, '⌈Toto řekni proroku:⌉ Co Hospodin odpověděl? Anebo: Co řekl Hospodin?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Jestliže však budete říkat: Hospodinův výnos, tedy toto praví Hospodin: Protože říkáte toto slovo: Hospodinův výnos, přestože jsem k vám poslal se slovy: Neříkejte: Hospodinův výnos,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'proto hle, zcela na vás zapomenu a odvrhnu od sebe vás i město, které jsem dal vám a vašim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Uvedu na vás věčnou potupu a věčnou hanbu, která nebude zapomenuta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Hospodin mi ukázal, hle, dva koše fíků postavené před Hospodinovým chrámem. (To se stalo potom, co babylonský král Nebúkadnesar odvedl do zajetí judského krále Jekonjáše, syna Jójakímova, a judská knížata, řemeslníky a kováře z Jeruzaléma a přivedl je do Babylona.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Jeden koš velmi dobrých fíků, jako jsou rané fíky, a jeden koš velice špatných fíků, tak špatných, že se nejedí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Hospodin mi řekl: Co vidíš, Jeremjáši? Řekl jsem: Fíky. Ty dobré fíky jsou velmi dobré a ty špatné jsou velice špatné, tak špatné, že se nedají jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Toto praví Hospodin, Bůh Izraele: Jako na tyto dobré fíky, tak budu k dobru hledět na judské vyhnance, které jsem poslal pryč z tohoto místa do chaldejské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Obrátím na ně svůj zrak k dobru a přivedu je zpět do této země. Vystavím je a nezbořím, zasadím je a nevyrvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Dám jim srdce, aby mě poznali, že já jsem Hospodin. Budou mým lidem a já budu jejich Bohem, protože se ke mně navrátí celým svým srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Jako se nakládá se špatnými fíky, které ⌈jsou tak špatné, že se nedají jíst⌉ -- toto praví Hospodin -- tak naložím s judským králem Sidkijášem, s jeho knížaty a s ostatkem Jeruzaléma, který zůstal v této zemi, i s těmi, kdo bydlí v egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, '⌈Učiním je úděsem,⌉ zlem pro všechna království země, potupou a pořekadlem, posměškem a kletbou na všech místech, kam je zaženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Pošlu na ně meč, hlad a mor, dokud ne budou zcela vyhlazeni ze země, kterou jsem dal jim a jejich otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Slovo, které se stalo k Jeremjášovi o všem judském lidu ve čtvrtém roce vlády judského krále Jójakíma, syna Jóšijášova (byl to první rok vlády babylonského krále Nebúkadnesara),');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'a které prorok Jeremjáš mluvil ke všemu judskému lidu a ke všem obyvatelům Jeruzaléma:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Od třináctého roku vlády judského krále Jóšijáše, syna Amónova, až dodnes, těchto dvacet tři let, stávalo se ke mně Hospodinovo slovo. Mluvil jsem k vám, stále znovu jsem mluvil, ale neposlouchali jste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Hospodin vám posílal všechny své otroky proroky, stále znovu je posílal, ale neposlouchali jste a nenakláněli jste ucho, abyste slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Říkali: Odvraťte se každý od své zlé cesty a od svých zvrácených činů a budete bydlet v zemi, kterou Hospodin dal vám a vašim otcům od věků až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Nechoďte za jinými bohy, abyste jim sloužili a klaněli se jim. Nezlobte mě dílem svých rukou, a neudělám vám nic zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Ale neposlouchali jste mě, je Hospodinův výrok, jen abyste mě ⌈ke své vlastní škodě⌉ rozzlobili dílem svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Proto takto praví Hospodin zástupů: Protože jste neposlouchali má slova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'hle, pošlu a vezmu všechny severní čeledě, je Hospodinův výrok, pošlu i pro svého otroka, babylonského krále Nebúkadnesara, a přivedu je proti této zemi, proti jejím obyvatelům i proti všem těmto okolním národům. Zasvětím je zkáze a učiním je předmětem hrůzy a úžasu a věčnými troskami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Odstraním od nich hlas jásotu i hlas radosti, hlas ženicha i hlas nevěsty, zvuk ručních mlýnků i světlo lampy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Tato celá země se stane troskami, hroznou pustinou, a tyto národy budou sedmdesát let sloužit babylonskému králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Stane se, že až se naplní sedmdesát let, navštívím s trestem ⌈za jejich vinu babylonského krále i ten⌉ národ -- je Hospodinův výrok -- i chaldejskou zemi a učiním ji navěky zcela opuštěnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Přivedu na tuto zemi všechna svá slova, která jsem o ní promluvil, všechno, co je zapsáno v této knize, jak prorokoval Jeremjáš o všech národech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Vždyť i je samé zotročí mnohé národy a velcí králové. Odplatím jim podle jejich skutků a podle díla jejich rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Hospodin, Bůh Izraele, mi řekl toto: Vezmi z mé ruky tento kalich s vínem hněvu a dej z něj napít všem národům, ke kterým tě posílám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Až se napijí, budou se potácet a šílet ⌈kvůli meči,⌉ který mezi ně posílám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Vzal jsem kalich z Hospodinovy ruky a dal jsem napít všem národům, ke kterým mě Hospodin poslal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jeruzalému, judským městům, jeho králům a jeho knížatům, abych je učinil troskami, předmětem hrůzy a úžasu a kletby, jako je tomu dnes;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'faraonovi, egyptskému králi, jeho otrokům, jeho knížatům a všemu jeho lidu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'všemu míšenému lidu, všem králům země Úsu, všem králům pelištejské země, Aškalónu, Gaze, Ekrónu, ostatku Ašdódu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edómu, Moábu a synům Amónovým,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'všem týrským králům, všem sidónským králům, králům pobřeží za mořem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedánovi, Témovi, Búzovi a všem s vyholenými skráněmi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'všem arabským králům, všem králům ⌈míšeného lidu,⌉ kteří bydlí v pustině,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'všem zimríjským králům, všem élamským králům, všem médským králům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'všem severním králům, blízkým i dalekým, jednomu po druhém a všem královstvím světa, která jsou na povrchu země. Král Šéšaku se napije po nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Řekni jim: Toto praví Hospodin zástupů, Bůh Izraele: Pijte, opijte se a zvracejte, padněte a nevstanete kvůli meči, který mezi vás posílám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Stane se, že odmítnou přijmout kalich z tvé ruky, aby pili. Řekni jim: Toto praví Hospodin zástupů: Musíte pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Neboť hle, s městem, které se nazývá mým jménem, již začínám nakládat zle a vy byste zůstali zcela bez trestu? Nezůstanete bez trestu, protože povolávám meč na všechny obyvatele země, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Ty však jim prorokuj všechna tato slova a řekni jim: Hospodin zařve z výšiny, ze svého svatého příbytku vydá svůj hlas, hlasitě zařve nad svou pastvinou, rozkřičí se jako ti, kdo lisují hrozny, na všechny obyvatele země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Hukot proniká až do končin země, protože Hospodin vede spor s národy, soudí každé tělo a ničemy vydá meči, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Toto praví Hospodin zástupů: Hle, od národa k národu vychází zlo, dává se do pohybu velký vichr z nejvzdálenějších částí země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'V onen den budou Hospodinem pobití ležet od jednoho konce země až na druhý. Nebudou oplakáváni, nebudou sebráni ani pohřbeni, budou jako hnůj na povrchu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Naříkejte, pastýři, a křičte! Válejte se v prachu vznešení předáci stáda, protože se naplnily dny pro vaši porážku a rozptýlení, padnete jako vzácná nádoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Zmizí útočiště pro pastýře i únik pro vznešené předáky stáda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Slyš! Volání pastýřů a nářek vznešených předáků stáda, protože Hospodin ničí jejich pastvu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'a pokojné pastviny jsou zpustošené kvůli Hospodinovu planoucímu hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Opouští svou skrýši jako mladý lev, jejich země se stala předmětem hrůzy kvůli krutému meči a kvůli jeho planoucímu hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Na počátku kralování judského krále Jójakíma, syna Jóšijášova, stalo se od Hospodina toto slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Toto praví Hospodin: Postav se na nádvoří Hospodinova domu a mluv ke všem judským městům, která se přicházejí klanět do Hospodinova domu, všechna slova, jež jsem ti přikázal, abys k nim mluvil. Nevynech ani jedno slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Snad poslechnou a každý se odvrátí od své zlé cesty; budu litovat zla, které jim zamýšlím provést kvůli jejich zvráceným činům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Řekni jim: Toto praví Hospodin: Jestliže mě neuposlechnete, ⌈abyste žili⌉ ⌈podle mého zákona,⌉ který jsem ⌈vám předložil, ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, '⌈abyste poslouchali⌉ slova mých otroků proroků, které vám posílám, stále znovu posílám -- a vy jste neposlouchali --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'učiním s tímto domem to, co se Šílem, a toto město učiním kletbou pro všechny národy země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Kněží, proroci a všechen lid slyšeli Jeremjáše mluvit v Hospodinově domě tato slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Stalo se, že když Jeremjáš domluvil všechno, co Hospodin přikázal, aby mluvil ke všemu lidu, kněží, proroci a všechen lid ho chytili a řekli: Jistě zemřeš!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Proč jsi prorokoval v Hospodinově jménu, že se s tímto domem stane to, co s Šílem, a toto město zpustne, bude bez obyvatel? Všechen lid se shromáždil v Hospodinově domě k Jeremjášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Když se judská knížata doslechla tato slova, vyšla z královského paláce vzhůru do Hospodinova domu a zasedla u vchodu do Nové brány Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Potom kněží a proroci řekli knížatům a všemu lidu: Tomuto muži náleží rozsudek smrti, protože prorokoval proti tomuto městu, jak jste slyšeli na vlastní uši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Jeremjáš řekl všem knížatům a všemu lidu: Hospodin mě poslal, abych prorokoval proti tomuto domu a proti tomuto městu všechna slova, která jste slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Nyní dejte do pořádku své cesty a své činy a uposlechněte Hospodina, svého Boha a Hospodin bude litovat zla, které proti vám mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Hle, já jsem ve vaší ruce. Udělejte se mnou to, co je dobré a správné ve vašich očích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Ovšem s jistotou vězte, že když mě dáte usmrtit, uvalíte na sebe i na toto město a jeho obyvatele nevinnou krev, protože mě k vám opravdu poslal Hospodin, abych ⌈k vám⌉ mluvil všechna tato slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Knížata a všechen lid řekli kněžím a prorokům: Tomuto muži ne náleží rozsudek smrti, protože k nám mluvil ve jménu Hospodina, našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Pak povstali někteří ze starších země a řekli celému shromáždění lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Za dnů judského krále Chizkijáše prorokoval Micheáš Mórešetský a řekl všemu judskému lidu: Toto praví Hospodin zástupů: Sijón bude zorán jako pole, Jeruzalém se stane sutinami a chrámová hora zalesněným návrším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Dal ho snad judský král Chizkijáš a celý Juda usmrtit? Cožpak se nebál Hospodina a ne snažil se udobřit Hospodinovu tvář a Hospodin litoval zla, které proti nim vyslovil? Ale my pácháme velké zlo ⌈proti svým duším.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Ještě někdo prorokoval v Hospodinově jménu, Úrijáš, syn Šemajášův z Kirjat–jeárímu; prorokoval proti tomuto městu a proti této zemi stejnými slovy jako Jeremjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Když král Jójakím, všichni jeho hrdinové a všechna knížata uslyšeli jeho slova, král ⌈ho chtěl dát usmrtit.⌉ Když to Úrijáš uslyšel, bál se, utekl a šel do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Král Jójakím poslal do Egypta muže, totiž Elnátana, syna Akbórova, a s ním jiné muže do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Vyvedli Úrijáše z Egypta a přivedli ho ke králi Jójakímovi. Ten ho zabil mečem a jeho mrtvolu odhodil do hrobu ⌈obyčejných lidí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Ovšem ruka Achíkama, syna Šáfanova, byla s Jeremjášem a nebyl dán do ruky lidu, aby ho usmrtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Na počátku kralování judského krále Sidkijáše, syna Jóšijášova, stalo se k Jeremjášovi od Hospodina toto slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Hospodin mi řekl toto: Udělej si pouta a jho a dej si je na šíji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Pošli je edómskému králi, moábskému králi, králi synů Amónových, týrskému králi a sidónskému králi po poslech, kteří přicházejí do Jeruzaléma k judskému králi Sidkijášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Přikaž jim, aby řekli svým pánům: Toto praví Hospodin zástupů, Bůh Izraele: Toto řekněte svým pánům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Já jsem svou velkou silou a svou vztaženou paží učinil zemi, lidi a zvěř, která je na povrchu země, a dávám ji tomu, komu je v mých očích správné ji dát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Nyní jsem dal všechny tyto země do ruky svého otroka, babylonského krále Nebúkadnesara; dal jsem mu i polní zvěř, aby mu sloužila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Všechny národy budou sloužit jemu, jeho synovi i vnukovi, dokud pro jeho zemi i pro něj ne přijde čas; potom ho zotročí mnohé národy a velcí králové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Kdyby byl národ či království, které by babylonskému králi Nebúkadnesarovi nesloužilo a nedalo svou šíji do jha babylonského krále, ten národ navštívím mečem, hladem a morem -- je Hospodinův výrok -- dokud jej jeho rukou zcela ne vyhladím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Proto neposlouchejte svoje proroky, svoje věštce, svoje sny, svoje hadače ani svoje čaroděje, kteří vám říkají: Neslužte babylonskému králi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'neboť vám prorokují klam, aby vás odvedli daleko z vaší země. Rozeženu vás a zahynete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Ale národ, který dá svou šíji do jha babylonského krále a bude mu sloužit, ponechám v jeho zemi, je Hospodinův výrok, bude ji obdělávat a bydlet v ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'K judskému králi Sidkijášovi jsem promluvil ⌈všechna tato slova:⌉ Dejte svou šíji do jha babylonského krále, služte jemu a jeho lidu ⌈a tak budete žít.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Proč byste měli zemřít ty a tvůj lid mečem, hladem a morem, jak promluvil Hospodin o národu, který nebude sloužit babylonskému králi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Neposlouchejte slova proroků, kteří vám říkají: Neslužte babylonskému králi, neboť vám prorokují klam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Neposlal jsem je, je Hospodinův výrok, a oni prorokují v mém jménu lživě, abych vás rozehnal; zahynete vy i proroci, kteří vám prorokují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Kněžím a všemu tomuto lidu jsem řekl: Toto praví Hospodin: Neposlouchejte slova svých proroků, kteří vám prorokují slovy: Hle, nádoby Hospodinova domu budou nyní brzy navráceny zpět z Babylona, protože vám prorokují klam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Neposlouchejte je! Služte babylonskému králi ⌈a tak budete žít!⌉ Proč by se mělo toto město stát troskami?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Jestliže jsou opravdu proroci a jestliže mají Hospodinovo slovo, ať ⌈se přimlouvají u⌉ Hospodina zástupů, aby nádoby ponechané v Hospodinově domě, v paláci judského krále a v Jeruzalémě nepřišly do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Neboť toto praví Hospodin zástupů o sloupech, o bronzovém moři, o podstavcích a o zbytku nádob ponechaných v tomto městě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'které babylonský král Nebúkadnesar nevzal, když odvedl do zajetí z Jeruzaléma do Babylona judského krále Jekonjáše, syna Jójakímova, a všechny judské i jeruzalémské šlechtice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Neboť toto praví Hospodin zástupů, Bůh Izraele, o nádobách ponechaných v Hospodinově domě, v paláci judského krále a v Jeruzalémě:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Budou doneseny do Babylona a tam zůstanou až do dne, kdy se o ně postarám, je Hospodinův výrok, kdy je vynesu a navrátím je zpět na toto místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Stalo se v tomtéž roce, na počátku kralování judského krále Sidkijáše, ve čtvrtém roce, v pátém měsíci, že mi prorok Chananjáš, syn Azúrův, který byl z Gibeónu, řekl v Hospodinově domě ⌈před očima⌉ kněží a všeho lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Toto praví Hospodin zástupů, Bůh Izraele: Zlomím jho babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, '⌈Za dva roky⌉ navrátím na toto místo všechny nádoby Hospodinova domu, které vzal babylonský král Nebúkadnesar z tohoto místa a odnesl je do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'I judského krále Jekonjáše, syna Jójakímova, a všechny judské vyhnance, kteří přišli do Babylona, navrátím na toto místo, je Hospodinův výrok, protože zlomím jho babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Prorok Jeremjáš řekl proroku Chananjášovi ⌈před očima⌉ kněží a ⌈před očima⌉ všeho lidu, který stál v Hospodinově domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Prorok Jeremjáš řekl: Amen! Ať tak Hospodin učiní! Ať Hospodin naplní tvá slova, která jsi prorokoval o navrácení nádob Hospodinova domu a všech vyhnanců z Babylona na toto místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Ovšem poslouchej nyní toto slovo, které řeknu ⌈tobě i všemu lidu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Proroci, kteří byli přede mnou a před tebou odedávna, prorokovali proti mnohým zemím a proti velkým královstvím o válce, zlu a moru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Když bude prorok prorokovat o pokoji, to, že tohoto proroka opravdu poslal Hospodin, se pozná podle naplnění prorokova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Prorok Chananjáš vzal jho ze šíje proroka Jeremjáše a zlomil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Chananjáš řekl ⌈před očima⌉ všeho lidu: Toto praví Hospodin: Takto za dva roky zlomím jho babylonského krále Nebúkadnesara ⌈ze šíje⌉ všech národů. Nato šel prorok Jeremjáš svou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Potom, co prorok Chananjáš zlomil jho ze šíje proroka Jeremjáše, stalo se k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Jdi a řekni Chananjášovi: Toto praví Hospodin: Zlomil jsi jho dřevěné, ale učiníš místo něho jho železné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Neboť toto praví Hospodin zástupů, Bůh Izraele: Dal jsem na šíji všech těchto národů železné jho, aby otročili babylonskému králi Nebúkadnesarovi, a budou mu sloužit. Dal jsem mu i polní zvěř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Potom prorok Jeremjáš řekl proroku Chananjášovi: Poslouchej, Chananjáši! Hospodin tě neposlal, ale ty vzbuzuješ u tohoto lidu doufání v klam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Proto toto praví Hospodin: Hle, odstraním tě z povrchu země. Tento rok zemřeš, protože jsi naváděl ke vzpouře proti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'V tomtéž roce, v sedmém měsíci, prorok Chananjáš zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Toto jsou slova dopisu, který prorok Jeremjáš poslal z Jeruzaléma zbytku starších mezi vyhnanci, kněžím, prorokům a všemu lidu, který Nebúkadnesar odvedl z Jeruzaléma do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(To bylo po vyjití krále Jekonjáše, královny, dvorních úředníků, judských a jeruzalémských knížat, řemeslníků a kovářů z Jeruzaléma.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Poslal jej prostřednictvím Eleásy, syna Šáfanova, a Gemarjáše, syna Chilkijášova, které poslal judský král Sidkijáš k babylonskému králi Nebúkadnesarovi do Babylona:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Toto praví Hospodin zástupů, Bůh Izraele, všem vyhnancům, které jsem odvedl z Jeruzaléma do Babylona:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Stavějte domy a bydlete v nich. Vysazujte zahrady a jezte jejich plody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Berte si ženy a ploďte syny i dcery. Berte pro své syny ženy a své dcery vydávejte za muže, aby rodily syny i dcery; množte se tam a ať vás neubývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, '⌈Hledejte pokoj⌉ města, do kterého jsem vás odvedl, a modlete se za něj k Hospodinu, protože v jeho pokoji budete mít pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Neboť toto praví Hospodin zástupů, Bůh Izraele: Ať vás nepodvádějí vaši proroci, kteří jsou uprostřed vás, ani vaši věštci. Neposlouchejte ⌈sny, které míváte.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Vždyť vám v mém jménu prorokují klam. Neposlal jsem je, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Neboť toto praví Hospodin: Až se pro Babylon naplní sedmdesát let, ⌈postarám se o vás⌉ a naplním na vás své dobré slovo o tom, že vás navrátím na toto místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Vždyť já znám úmysly, které s vámi zamýšlím, je Hospodinův výrok. Úmysly o pokoji a ne o zlu, ⌈abych vám dal⌉ budoucnost a naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, '⌈Když mě budete volat, půjdete a budete se ke mně⌉ modlit, ⌈vyslyším vás.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, '⌈Když mě budete hledat,⌉ naleznete mě, pokud mě budete hledat celým svým srdcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Dám se vám nalézt, je Hospodinův výrok. Změním váš úděl a shromáždím vás ze všech národů a ze všech míst, kam jsem vás zahnal, je Hospodinův výrok, a přivedu vás zpět na místo, odkud jsem vás odvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Řekli jste: Hospodin nám ustanovil v Babyloně proroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Avšak toto praví Hospodin o králi, který sedí na Davidově trůnu, a o všem lidu, který bydlí v tomto městě, o vašich bratřích, kteří s vámi neodešli do vyhnanství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Toto praví Hospodin zástupů: Hle, posílám proti nim meč, hlad a mor a vydám je jako shnilé fíky, tak špatné, že se nedají jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Budu je stíhat mečem, hladem a morem, učiním je úděsem pro všechna království země, prokletím, předmětem hrůzy a úžasu a potupou mezi všemi národy, kam jsem je zahnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Za to, že neposlouchali má slova, je Hospodinův výrok, když jsem jim stále znovu posílal své otroky proroky, ale neposlouchali, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Proto vy všichni vyhnanci, které jsem poslal pryč z Jeruzaléma do Babylona, slyšte Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Toto praví Hospodin zástupů, Bůh Izraele, o Achabovi, synu Kólajášovu, a o Sidkijášovi, synu Maasejášovu, kteří vám v mém jménu prorokují klam: Hle, dávám je do ruky babylonského krále Nebúkadnesara; zabije je před vašima očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, '⌈Od nich vzejde⌉ kletba používaná mezi všemi judskými vyhnanci, kteří jsou v Babylonu: Ať ti Hospodin učiní to, co Sidkijášovi a Achabovi, které babylonský král upražil na ohni,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'protože v Izraeli páchali hanebnost, cizoložili s ženami svých bližních a mluvili v mém jménu klamné slovo, které jsem jim nepřikázal. Já to vím a jsem toho svědkem, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'K Šemajášovi Nechalamskému promluv slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Toto praví Hospodin zástupů, Bůh Izraele: Protože jsi ⌈svým jménem⌉ poslal dopisy všemu lidu, který je v Jeruzalémě, knězi Sefanjášovi, synu Maasejášovu, i všem kněžím se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Hospodin tě ustanovil knězem místo kněze Jójady, abys byl dohlížitelem v Hospodinově domě nad každým potřeštěncem a nad tím, kdo vystupuje jako prorok, abys ho dal do klády či do železného chomoutu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Proč jsi tedy nyní nenapomenul Jeremjáše Anatótského, který mezi vámi vystupuje jako prorok?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Vždyť proto nám poslal do Babylona zprávu se slovy: Bude to trvat dlouho. Stavte domy a bydlete v nich. Vysazujte zahrady a jezte jejich plody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Kněz Sefanjáš tento dopis přečetl ⌈proroku Jeremjášovi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Potom se stalo k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Pošli ke všem vyhnancům zprávu se slovy: Toto praví Hospodin o Šemajášovi Nechalamském: Protože vám prorokoval, ale já jsem ho neposlal, a vzbuzoval u vás doufání v klam,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'proto takto praví Hospodin: Hle, navštívím Šemajáše Nechalamského a jeho potomstvo; nebude mít nikoho, kdo by žil uprostřed tohoto lidu, a neuvidí dobro, které svému lidu učiním, je Hospodinův výrok, protože naváděl ke vzpouře proti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Toto praví Hospodin, Bůh Izraele: Zapiš si do knihy všechna slova, která jsem k tobě promluvil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'protože hle, přicházejí dny, je Hospodinův výrok, kdy změním úděl svého izraelského a judského lidu, praví Hospodin, a přivedu je zpět do země, kterou jsem dal jejich otcům a budou ji vlastnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Toto jsou slova, která promluvil Hospodin o Izraeli a o Judovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Ano, toto praví Hospodin: Slyšeli jsme ⌈křik hrůzy.⌉ Všude je jen strach, a ne pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Jen se ptejte a dívejte, jestli ⌈rodí muž!⌉ Proč vidím, že všichni muži mají ruce na bedrech jako rodička a zbledly všechny tváře?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Běda, neboť veliký je tento den, není žádný jako on; pro Jákoba je to čas soužení, ale bude z něho zachráněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'I stane se v onen den, je výrok Hospodina zástupů, že zlomím jeho jho na jejich šíji, jejich pouta zpřetrhám a cizinci je už nebudou zotročovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Budou sloužit Hospodinu, svému Bohu, a svému králi Davidovi, kterého jim ustanovím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'A ty se neboj, můj otroku Jákobe, je Hospodinův výrok, neděs se, Izraeli, protože hle, zachráním tě z ⌈dalekých končin⌉ a tvé potomstvo ze země jejich zajetí. Jákob se navrátí a bude mít klid, bude bezstarostný a nikdo ho nevyděsí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Vždyť já jsem s tebou, je Hospodinův výrok, abych tě zachránil, protože úplně zničím všechny národy, mezi které jsem tě rozptýlil. Pouze tebe nezničím úplně, ale napravím tě podle práva; jistě tě nenechám bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Ano, toto praví Hospodin: Nevyléčitelná je tvoje zlomenina, těžká je tvoje rána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Není, kdo by vedl tvou právní při, není pro tebe uzdravení vředu ani zacelení rány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Všichni tvoji milenci na tebe zapomněli, nevyhledávají tě, protože jsem tě ranil ranou nepřítele, krutou kázní za množství tvých vin; tvých hříchů bylo bezpočtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Co naříkáš nad svou ⌈zlomeninou? Tvá⌉ bolest je nevyléčitelná. Provedl jsem ti to za množství tvých vin a protože tvých hříchů bylo bezpočtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Ale všichni, kteří tě požírají, budou pozřeni a všichni tvoji utlačovatelé, úplně všichni, půjdou do zajetí; ti, kteří tě plení, budou vypleněni a všechny, kdo na tobě kořistí, vydám za kořist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Vždyť ti přivedu uzdravení a ze tvých ran tě vyléčím, je Hospodinův výrok, protože tě nazvali Zapuzenou: To je Sijón, nikdo ⌈ho ne vyhledává.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Toto praví Hospodin: Hle, změním úděl ⌈stanů Jákobových⌉ a slituji se nad jeho příbytky; město bude zbudováno na svých ruinách a palác bude stát ⌈na svém místě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Bude odtamtud zaznívat píseň díků a hlas radujících se. Rozmnožím je a nebude jich ubývat; způsobím, že budou vážení a nebudou bezvýznamní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Jeho synové budou jako za dávnověku a jeho shromáždění bude trvale přede mnou; všechny jeho utiskovatele navštívím s trestem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Stane se, že jeho vznešený bude pocházet z něho samotného i jeho vládce vyjde z jeho středu. Přivedu ho blíž a přiblíží se ke mně. Vždyť ⌈kdo by nasadil svůj život,⌉ aby se ke mně přiblížil? je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Budete mým lidem a já budu vaším Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Hle, spustila se Hospodinova vichřice hněvu, vířivý vichr. Bude vířit na hlavě ničemů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Hospodinův planoucí hněv se neodvrátí, dokud ne vykoná a ne naplní plány jeho srdce. V posledních dnech tomu porozumíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'V onen čas, je Hospodinův výrok, budu Bohem všech izraelských čeledí a oni budou mým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Toto praví Hospodin: Lid, který ⌈přežil meč,⌉ našel v pustině milost, ⌈Izrael vešel do svého odpočinutí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Zpovzdálí se mi ukázal Hospodin a řekl: Miluji tě věčnou láskou, proto ⌈ti stále zachovávám milosrdenství.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Znovu tě vystavím a zbuduji, panno izraelská. Znovu se ozdobíš svými tamburínami a vyjdeš s tancem s těmi, kdo se radují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Znovu budeš sázet vinice na samařských horách. Sadaři je vysadí a budou je i užívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Neboť nastane den, kdy strážci na Efrajimském pohoří zvolají: Vstaňte a vystupme na Sijón k Hospodinu, svému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Neboť toto praví Hospodin: Volejte s radostí nad Jákobem, křičte nad předním z národů. Zvěstujte, chvalte a říkejte: ⌈Hospodin zachránil⌉ svůj lid, ostatek Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Hle, přivedu je ze severní země, shromáždím je z nejvzdálenějších částí země. Mezi nimi slepého a chromého, těhotnou spolu s rodičkou; navrátí se zpět jako velké shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Přijdou s pláčem a přivedu je s úpěnlivými prosbami. Uvedu je k potokům plným vody přímou cestou, na níž neklopýtnou, protože jsem se stal Izraeli otcem, Efrajim je můj prvorozený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Národy, slyšte Hospodinovo slovo a oznamte je na vzdálených ostrovech; říkejte: Ten, který rozptýlil Izrael, ho shromáždí a bude ho střežit jako pastýř své stádo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Vždyť Hospodin vyplatil Jákoba, vykoupil ho z ruky silnějšího nežli on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Přijdou a budou radostně volat na sijónské výšině. ⌈Budou zářit nad Hospodinovou dobrotou, nad obilím,⌉ novým vínem a olejem, nad mláďaty bravu a skotu. Jejich duše bude jako zavlažovaná zahrada a nebudou už déle strádat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Tehdy se bude panna radovat tancem spolu s mládenci i starci. Změním jejich smuteční obřady v jásot, potěším je a místo jejich žalu jim dám radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Duši kněží napojím tukem a můj lid se nasytí mojí dobrotou, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Toto praví Hospodin: Slyš! V Rámě je slyšet bědování a hořký pláč. Ráchel oplakává své syny. Nechce se dát potěšit kvůli svým synům, protože už nejsou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Toto praví Hospodin: Zdrž svůj hlas od pláče a své oči od slz, protože je mzda za tvou práci, je Hospodinův výrok: Navrátí se z nepřátelské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Je naděje pro tvoji budoucnost, je Hospodinův výrok; synové se navrátí zpět na své území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Zřetelně jsem slyšel, jak nad sebou Efrajim naříká: Káral jsi mě a dal jsem se pokárat jako nezkrocené tele. Přiveď mě zpět a navrátím se, protože ty, ⌈Hospodine, jsi můj Bůh.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Po svém navrácení toho lituji, potom, co jsem dosáhl poznání, se biju v prsa. Stydím se a jsem zahanben, protože nosím potupu svého mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Je Efrajim mým drahým synem? Je dítětem, v němž mám potěšení? Vždyť pokaždé, když proti němu mluvím, na něj stále pamatuji. Proto je mé nitro kvůli němu rozrušeno; jistě se nad ním slituji, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Postav si patníky, udělej si ukazatele a zamysli se nad silnicí, nad cestou, po které jsi chodila. Navrať se, panno izraelská, navrať se do těchto svých měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Dokdy se budeš toulat sem a tam, odpadlá dcero? Vždyť Hospodin stvořil na zemi novou věc: Žena ⌈bude kroužit kolem muže.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Toto praví Hospodin zástupů, Bůh Izraele: Až změním jejich úděl, znovu budou v judské zemi a v jejích městech říkat tato slova: Požehnej ti Hospodin, příbytku spravedlnosti, horo svatá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, '⌈V Judsku i ve všech jeho městech budou bydlet pospolu⌉ zemědělci i ti, kdo putují se stádem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Vždyť napojím vyčerpanou duši a každou ochablou duši naplním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Nato jsem se probudil a rozhlédl; můj spánek mi byl příjemný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Hle, přicházejí dny, je Hospodinův výrok, kdy oseji dům izraelský i dům judský semenem lidským i semenem zvířecím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Stane se, že tak, jako jsem nad nimi bděl, aby byli vyvráceni, zničeni, pobořeni, vyhubeni a aby jim bylo zlo učiněno, tak nad nimi budu bdít, aby byli zbudováni a zasazeni, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'V oněch dnech už nebudou říkat: Otcové jedli trpké hrozny a synům trnou zuby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'ale každý zemře za svou vinu. Každému člověku, který jí trpké hrozny, budou trnout jeho zuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Hle, přicházejí dny, je Hospodinův výrok, kdy uzavřu s domem izraelským i s domem judským novou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Ne jako smlouvu, kterou jsem uzavřel s jejich otci v den, kdy jsem je uchopil za ruku, abych je vyvedl z egyptské země -- smlouvu, kterou porušili, ačkoliv jsem byl jejich Pánem, je Hospodinův výrok,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'ale toto je ta smlouva, kterou uzavřu s domem izraelským po těchto dnech, je Hospodinův výrok: Svůj zákon dám do jejich nitra a zapíšu jej na jejich srdce. Budu jejich Bohem a oni budou mým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Nebudou již učit ⌈jeden druhého⌉ ani každý svého bratra slovy: Poznejte Hospodina! Protože mě budou znát všichni, od ⌈nejmenšího do největšího,⌉ je Hospodinův výrok, protože odpustím jejich vinu a na jejich hřích již nevzpomenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Toto praví Hospodin, který dává slunce za světlo ve dne, který ustanovuje měsíc a hvězdy za světlo v noci, který vzdouvá moře, až jeho vlny burácejí -- jeho jméno je Hospodin zástupů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Jestliže ode mne ustoupí tato ustanovení, je Hospodinův výrok, pak také potomstvo Izraele přede mnou přestane být národem po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Toto praví Hospodin: Jestliže budou změřena nebesa nahoře a prozkoumány základy země dole, také já zavrhnu celé potomstvo Izraele za všechno, co páchali, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Hle, přicházejí dny, je Hospodinův výrok, kdy bude toto město znovu vybudováno Hospodinu, od věže Chananeel až po Rohovou bránu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'A měřicí šňůra půjde dál ⌈naproti ní⌉ na kopec Garéb a obrátí se ke Goje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Celé údolí mrtvol a popela a všechna pole až k potoku Kidrónu, až na roh Koňské brány na východě budou svaté Hospodinu. Nikdy už nebudou vyvráceny ani zbořeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina v desátém roce vlády judského krále Sidkijáše. Tento rok byl osmnáctým rokem vlády Nebúkadnesara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Tehdy vojsko babylonského krále obléhalo Jeruzalém a prorok Jeremjáš byl vězněn na nádvoří stráží, které bylo v paláci judského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Uvěznil ho judský král Sidkijáš se slovy: ⌈Proč prorokuješ,⌉ řka: Toto praví Hospodin: Hle, vydám toto město do ruky babylonského krále a dobude ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Judský král Sidkijáš z ruky Chaldejců neunikne, protože bude jistě vydán do ruky babylonského krále a ⌈bude s ním mluvit tváří v tvář, na vlastní oči ho uvidí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Uvede Sidkijáše do Babylona a tam ⌈bude, dokud ho ne navštívím, je Hospodinův výrok. Když budete bojovat s Chaldejci, neuspějete.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Jeremjáš řekl: Stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Hle, přijde k tobě Chanameel, syn tvého strýce Šalúma, se slovy: Kup si mé pole, které je v Anatótu, protože máš příbuzenské výkupní právo, abys ho koupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Potom ke mně podle Hospodinova slova přišel Chanameel, syn mého strýce, na nádvoří stráží a řekl mi: Kup si, prosím, mé pole, které je v Anatótu, jenž je v zemi Benjamín, protože máš vlastnické a příbuzenské výkupní právo. Kup si ho. A poznal jsem, že to bylo Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Koupil jsem si tedy pole od Chanameela, syna mého strýce, které je v Anatótu a odvážil jsem mu stříbro: Sedmnáct šekelů stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Zapsal jsem to na listinu a zapečetil, povolal jsem svědky a odvážil jsem stříbro na vahách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Vzal jsem ⌈zapečetěnou kupní listinu s příkazy a ustanoveními⌉ i otevřený opis');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'a dal jsem kupní listinu Bárukovi, synu Nerijáše, vnuku Machsejášovu, před očima Chanameela, syna mého strýce a před očima svědků, kteří podepsali kupní listinu před očima všech Judejců, kteří seděli na nádvoří stráží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Před jejich očima jsem Bárukovi přikázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Toto praví Hospodin zástupů, Bůh Izraele: Vezmi tyto listiny, tuto zapečetěnou kupní listinu i tento otevřený opis a dej je do hliněné nádoby, aby se uchovaly po mnoho dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Protože toto praví Hospodin zástupů, Bůh Izraele: Znovu se budou v této zemi kupovat domy, pole a vinice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Potom, co jsem dal kupní listinu Bárukovi, synu Nerijášovu, modlil jsem se k Hospodinu slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ach, Panovníku Hospodine! Hle, ty jsi svou velkou silou a svou vztaženou paží ⌈učinil nebesa i zemi.⌉ Pro tebe ⌈žádná věc ne ní nesnadná.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Prokazuješ milosrdenství tisícům a odplácíš vinu otců do klína jejich synů, kteří přijdou po nich. Velký a mocný Bože, jehož jméno je Hospodin zástupů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'velký v radě a mocný v činu, jehož oči jsou otevřeny na všechny cesty lidských synů, abys dal každému podle jeho cest a podle ovoce jeho činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Ty jsi činil znamení a divy v egyptské zemi a až do tohoto dne, v Izraeli i mezi ostatními lidmi; učinil sis jméno, jak je tomu i dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Vyvedl jsi svůj lid Izrael z egyptské země se znameními a divy, ⌈mocnou rukou a vztaženou paží,⌉ s ⌈velkými bázeň vzbuzujícími činy,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'a dal jsi jim tuto zemi, o které jsi přísahal jejich otcům, že jim ji dáš, zemi oplývající mlékem a medem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Přišli a vlastnili ji, ale tebe neposlouchali a podle tvého zákona nežili. Nečinili nic, co jsi jim přikázal, aby činili, a tak jsi způsobil, aby na ně přišlo všechno toto zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Hle, postavili k městu obléhací náspy, aby ho dobyli. Mečem, hladem a morem bude vydáno město do ruky Chaldejců, kteří proti němu vedou válku. Jak jsi promluvil, tak se stalo; a hle, ty to vidíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Ty, Panovníku Hospodine, jsi mi řekl: Kup si za stříbro pole a povolej svědky, ačkoliv město bude vydáno do ruky Chaldejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Potom se stalo k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Hle, já jsem Hospodin, Bůh veškerého těla. Cožpak je pro mě nějaká věc nesnadná?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Proto toto praví Hospodin: Hle, dávám toto město do ruky Chaldejců a do ruky babylonského krále Nebúkadnesara a dobude ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Chaldejci, kteří proti tomuto městu vedou válku, vejdou, zapálí toto město a spálí ho i s domy, na jejichž střechách pálili oběti Baalovi a lili úlitby jiným bohům, aby mě rozzlobili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Vždyť synové izraelští i synové judští od svého mládí jen páchali to, ⌈co je zlé v mých očích.⌉ Vždyť synové izraelští mě jen zlobili dílem svých rukou, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Vždyť toto město mi bylo k hněvu a k zlobě ode dne, kdy ho vystavěli, až dodnes, takže ho od sebe odstraním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'A to za všechno zlo synů izraelských a synů judských, které páchali, aby mě rozzlobili -- oni, jejich králové, jejich knížata, jejich kněží i jejich proroci, judští muži i obyvatelé Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Obrátili se ke mně zády a ne tváří; stále znovu jsem je učil, ale neposlouchali a kázeň ne přijímali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Postavili své ohavné modly v domě, který se nazývá mým jménem, aby jej znečistili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Vystavěli Baalova návrší, která jsou v údolí Hinómova syna, aby prováděli ohněm své syny a své dcery Molekovi, což jsem jim nepřikázal a ani mi nepřišlo na mysl, aby činili takovou ohavnost a sváděli Judu ke hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Proto nyní toto praví Hospodin, Bůh Izraele, o tomto městě, o kterém říkáte: Bude vydáno do ruky babylonského krále mečem, hladem a morem:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Hle, shromáždím je ze všech zemí, kam jsem je zahnal ve svém hněvu, zlobě a velikém rozhořčení, přivedu je zpět na toto místo a způsobím, že budou bydlet v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Budou mým lidem a já budu jejich Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Dám jim ⌈jedno srdce⌉ a ⌈jednu cestu,⌉ aby se mě báli po všechny dny, aby se dobře dařilo jim i jejich synům po nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Uzavřu s nimi věčnou smlouvu, že jim nepřestanu prokazovat dobro, a dám do jejich srdce bázeň přede mnou, aby se ode mě neodvrátili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Rozjásám se nad nimi, abych jim prokazoval dobro; spolehlivě je v této zemi zasadím, celým svým srdcem a celou svou duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Neboť toto praví Hospodin: Jako jsem přivedl na tento lid všechno toto velké zlo, tak na ně přivedu i všechno dobro, o kterém k nim mluvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Opět se budou kupovat pole v této zemi, o které říkáte: Je zcela opuštěná, bez lidí i zvěře, je vydána do ruky Chaldejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Budou se kupovat pole za stříbro, zapíší to do listiny a zapečetí ji a povolají svědky v zemi Benjamín, v okolí Jeruzaléma i v judských městech, v městech pohoří i v městech Šefely a v městech Negebu, protože ⌈změním jejich úděl,⌉ je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Stalo se Hospodinovo slovo k Jeremjášovi podruhé, zatímco byl stále zadržován na nádvoří stráží:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Toto praví Hospodin, který ⌈ zemi učinil, Hospodin, který ji vytvořil a upevnil⌉ -- Hospodin je jeho jméno:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Volej ke mně a odpovím ti, oznámím ti velké a skryté věci, které neznáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Neboť toto praví Hospodin, Bůh Izraele o domech tohoto města a o palácích judských králů, které byly zničeny kvůli náspům a meči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Vyjdou bojovat proti Chaldejcům, aby je naplnili mrtvolami lidí, které jsem pobil ve svém hněvu a ve své zlobě, protože jsem pro všechno jejich zlo skryl před tímto městem svou tvář:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Hle, přivedu mu zahojení a uzdravení, uzdravím je a zjevím jim hojnost pokoje a pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Změním úděl Judy i úděl Izraele a vybuduji je jako na počátku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Očistím je od každé jejich viny, kterou proti mně hřešili a odpustím všechny jejich viny, kterými proti mně hřešili a jimiž se proti mně bouřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Toto město ⌈mi získá věhlas,⌉ chválu a slávu před všemi národy země, které uslyší o všem dobru, které jim způsobím. Budou se bát a chvět nad vším dobrem a nad vším pokojem, který mu způsobím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Toto praví Hospodin: Na tomto místě, o kterém říkáte, že je zcela zpustošené, bez lidí a bez zvěře, v judských městech a na jeruzalémských ulicích, které jsou opuštěné, bez lidí, bez obyvatel a bez zvěře, bude znovu slyšet');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'hlas jásotu a hlas radosti, hlas ženicha a hlas nevěsty, hlas těch, kteří říkají: Vzdejte chválu Hospodinu zástupů, protože Hospodin je dobrý, protože jeho milosrdenství je navěky, když přinášejí do Hospodinova domu oběť díků. Změním totiž úděl této země jako na počátku, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Toto praví Hospodin zástupů: Na tomto zcela zpustošeném místě, bez lidí i zvěře, a ve všech jeho městech bude znovu příbytek pastýřů, kteří nechávají odpočívat stádo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Ve městech pohoří, ve městech Šefely, ve městech na Negebu, v zemi Benjamín, v okolí Jeruzaléma i v judských městech bude znovu pod rukama toho, kdo je počítá, procházet stádo, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Hle, přicházejí dny, je Hospodinův výrok, kdy naplním to dobré slovo, které jsem promluvil o domě izraelském a o domě judském.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'V oněch dnech a v oné době způsobím, aby Davidovi vyrašil spravedlivý Výhonek. Bude v zemi vykonávat právo a spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'V oněch dnech bude Juda zachráněn a Jeruzalém bude bydlet v bezpečí. Toto je jméno, jímž ho budou nazývat: Hospodin je naše spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Neboť toto praví Hospodin: Davidovi nebude vyhlazen muž sedící na trůnu domu izraelského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'A lévijským kněžím nebude vyhlazen přede mnou ten, kdo by přinášel zápalnou oběť, pálil přídavnou oběť a konal obětní hod po všechny dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Potom se stalo k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Toto praví Hospodin: Jestliže budete moci zrušit mou smlouvu se dnem a mou smlouvu s nocí, takže den a noc nebude ve svůj čas,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'pak bude zrušena také má smlouva s mým otrokem Davidem -- že bude mít syna, který by kraloval na jeho trůnu -- a s lévijskými kněžími, mými služebníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Jak nemohou být spočítány nebeské zástupy a nemůže být změřen mořský písek, tak rozmnožím potomstvo Davida, svého otroka, a Lévijce, kteří mi slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Potom se stalo k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Cožpak jsi neviděl, co tento lid říká: Dvě čeledě, které Hospodin vyvolil, ty zavrhl? Mým lidem opovrhují, už pro ně není národem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Toto praví Hospodin: Jestliže ne bude platit má smlouva se dnem a s nocí, pokud jsem nedal ustanovení pro ⌈nebesa a zemi,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'potom zavrhnu potomstvo Jákoba a svého otroka Davida a nevezmu z jeho potomstva vládce nad potomstvem ⌈Abrahama, Izáka a Jákoba.⌉ Ano, změním jejich úděl a slituji se nad nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina, když babylonský král Nebúkadnesar a celé jeho vojsko, všechna království země pod vládou jeho moci a všechny národy vedly válku proti Jeruzalému a proti všem jeho městům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Toto praví Hospodin, Bůh Izraele: Jdi a mluv k judskému králi Sidkijášovi. Řekni mu: Toto praví Hospodin: Hle, dávám toto město do ruky babylonského krále a ten ho spálí ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Ty z jeho ruky neunikneš, ale jistě budeš chycen a vydán do jeho ruky. Na vlastní oči uvidíš babylonského krále a ⌈bude s tebou mluvit tváří v tvář⌉ a přijdeš do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Jenom slyš Hospodinovo slovo, judský králi Sidkijáši! Toto o tobě praví Hospodin: Nezemřeš mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Zemřeš v pokoji. Jako pálili ohně pro tvé otce, dřívější krále, kteří byli před tebou, tak budou pálit oheň pro tebe a oplakávat tě: Ach, pane! protože já jsem promluvil slovo, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Prorok Jeremjáš promluvil v Jeruzalémě k judskému králi Sidkijášovi všechna tato slova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'když vojsko babylonského krále vedlo válku proti Jeruzalému a proti všem zbývajícím judským městům, proti Lakíši a proti Azece, protože ⌈ to byla jediná opevněná judská města, která zůstala.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Slovo, které se stalo k Jeremjášovi od Hospodina poté, co král Sidkijáš uzavřel smlouvu se vším lidem, který byl v Jeruzalémě, o vyhlášení propuštění,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'že každý propustí jako svobodného svého hebrejského otroka a svou hebrejskou služku, že Judejci nebudou zotročovat jeden druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Tehdy uposlechla všechna knížata i všechen lid, který vstoupil do smlouvy, že každý propustí jako svobodného svého otroka a svou služku, že už je nebudou zotročovat. Uposlechli a propustili je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Potom si to ale rozmysleli a přivedli otroky a služky, které propustili jako svobodné, nazpět a podmanili je za otroky a za služky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Nato se stalo Hospodinovo slovo k Jeremjáši od Hospodina:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Toto praví Hospodin, Bůh Izraele: Já jsem uzavřel smlouvu s vašimi otci v den, kdy jsem je vyvedl z egyptské země, z domu otroctví, se slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Po sedmi letech propustíte každý svého hebrejského bratra, který se ti prodá; bude ti sloužit šest let a pak ho od sebe propustíš jako svobodného. Ale vaši otcové mě neposlouchali a nenakláněli ucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Vy jste se dnes obrátili a učinili jste to, co je správné v mých očích tím, že jste každý vyhlásil propuštění svému bližnímu a uzavřeli jste přede mnou smlouvu v domě, který se nazývá mým jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Pak jste znovu znesvětili mé jméno; přivedli jste nazpět každý svého otroka a svou služku, které jste propustili jako svobodné podle jejich touhy a podmanili jste je, aby vám byli za otroky a za služky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Proto takto vám praví Hospodin: Neposlechli jste mě, abyste každý vyhlásil propuštění svému bratru a svému bližnímu. Hle, já vyhlašuji propuštění vám, je Hospodinův výrok, propuštění pro meč, mor a hlad a učiním vás úděsem pro všechna království země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'S muži, kteří přestupují mou smlouvu, kteří nenaplnili slova smlouvy, kterou přede mnou uzavřeli, učiním jako s teletem, které rozetli ve dví a mezi jehož částmi prošli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Judská i jeruzalémská knížata, dvorní úředníky, kněze i všechen lid země, který prošel mezi částmi telete --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'ty vydám do ruky jejich nepřátel a do ruky těch, kdo usilují o jejich život. Jejich mrtvoly se stanou potravou nebeského ptactva a zemské zvěře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Judského krále Sidkijáše a jeho knížata vydám do ruky jejich nepřátel a do ruky těch, kdo usilují o jejich život a do moci vojska babylonského krále, které od vás právě odtáhlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Hle, přikáži, je Hospodinův výrok, a přivedu ho zpět k tomuto městu; budou proti němu bojovat, dobudou ho a spálí ho ohněm. Judská města učiním zcela opuštěnými, bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Slovo, které se stalo k Jeremjášovi od Hospodina ve dnech judského krále Jójakíma, syna Jóšijášova:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Jdi ⌈do domu Rekábejců⌉ a mluv s nimi; přiveď je do Hospodinova domu, do jednoho z pokojů a dej jim napít víno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Vzal jsem Jaazanjáše, syna Jeremjášova, vnuka Chabasinjášova, jeho bratry, všechny jeho syny, celý dům Rekábejců');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'a přivedl jsem je do Hospodinova domu, do pokoje ⌈synů muže Božího Chánana,⌉ syna Jigdaljášova, který byl vedle pokoje knížat, jenž byl nad pokojem strážce prahu Maasejáše, syna Šalúmova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Dal jsem před syny domu Rekábejců džbány plné vína a kalichy a řekl jsem jim: Napijte se vína!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Ale oni řekli: Nebudeme pít víno, protože náš otec Jónadab, syn Rekábův, nám přikázal: Nikdy nepijte víno vy ani vaši synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Nestavte si domy, nezasévejte semeno, nevysazujte vinice a nevlastněte je, ale po všechny své dny bydlete ve stanech, abyste žili po mnoho dní na povrchu země, ve které pobýváte jako cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Uposlechli jsme svého otce Jónadaba, syna Rekábova, ve všem, co nám přikázal, ⌈abychom nepili víno⌉ po všechny své dny my, naše ženy, naši synové ani naše dcery');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'a ⌈abychom nebudovali domy⌉ k bydlení. Nevlastníme vinice ani pole ani semeno');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'a bydleli jsme ve stanech. Uposlechli jsme a učinili jsme všechno, co nám přikázal náš otec Jónadab.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Stalo se, když babylonský král Nebúkadnesar přitáhl do země, řekli jsme: Pojďme, vejděme před ⌈chaldejským vojskem⌉ a před aramejským vojskem do Jeruzaléma. A tak bydlíme v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Potom se stalo k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Toto praví Hospodin zástupů, Bůh Izraele: Jdi a řekni judským mužům a obyvatelům Jeruzaléma: Cožpak nepřijmete kázeň, abyste uposlechli má slova? je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Slova Jónadaba, Rekábova syna, která přikázal svým synům, aby nepili víno, jsou dodržována. Nepili ho až dodnes, protože poslechli příkaz svého otce. A já jsem k vám mluvil stále znovu, ale neposlouchali jste mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Stále znovu jsem vám posílal všechny své otroky proroky se slovy: Odvraťte se každý od své zlé cesty a dejte do pořádku své činy, nechoďte za jinými bohy, abyste jim sloužili a budete bydlet v zemi, kterou jsem dal vám a vašim otcům. Ale nenakláněli jste ucho a neposlouchali jste mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Vždyť synové Jónadaba, Rekábova syna, naplňovali příkaz svého otce, který jim dal, ale mě tento lid neposlouchal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Proto takto praví Hospodin, Bůh zástupů, Bůh Izraele: Hle, brzy na Judu a na všechny obyvatele Jeruzaléma přivedu všechno zlo, které jsem proti nim vyslovil, protože jsem k nim mluvil, ale neposlouchali, volal jsem je, a neodpovídali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Domu Rekábejců Jeremjáš řekl: Toto praví Hospodin zástupů, Bůh Izraele: Protože jste poslouchali příkaz svého otce Jónadaba, zachovali jste všechny jeho příkazy a učinili jste všechno, co vám přikázal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'proto takto praví Hospodin zástupů, Bůh Izraele: Jónadabovi, synu Rekábovu, ⌈nebude po všechny dny vyhlazen muž, který by stál přede mnou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Ve čtvrtém roce vlády judského krále Jójakíma, syna Jóšijášova, se stalo k Jeremjáši od Hospodina toto slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Vezmi si svitek a napiš na něj všechna slova, která jsem k tobě mluvil o Izraeli, o Judovi a o všech národech ode dne, kdy jsem k tobě promluvil, ode dnů Jóšijášových až dodnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Snad dům judský uslyší všechno zlo, které jim zamýšlím provést, a každý se odvrátí od své zlé cesty a odpustím jim jejich vinu a jejich hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Jeremjáš zavolal Báruka, syna Nerijášova, a Báruk zapsal z Jeremjášových úst na svitek všechna Hospodinova slova, která k němu Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Jeremjáš Bárukovi přikázal: Já jsem zadržován, nemohu jít do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Jdi ty a v postní den čti lidu v Hospodinově domě ze svitku to, co jsi napsal z mých úst, Hospodinova slova, a čti je také ⌈všem Judejcům,⌉ kteří přicházejí ze svých měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Snad jejich úpěnlivá prosba přijde před Hospodina a každý se odvrátí od své zlé cesty, protože hněv a zloba, kterou Hospodin promluvil proti tomuto lidu, je veliká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Báruk, syn Nerijášův, udělal vše, co mu prorok Jeremjáš přikázal, a v Hospodinově domě četl z knihy Hospodinova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'V pátém roce vlády judského krále Jójakíma, syna Jóšijášova, v devátém měsíci se stalo, ⌈ že pro všechen lid v Jeruzalémě a všechen lid, který přišel z judských měst do Jeruzaléma, vyhlásili⌉ půst před Hospodinem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'a Báruk četl z knihy všemu lidu Jeremjášova slova v Hospodinově domě v pokoji Gemarjáše, syna písaře Šáfana, na horním nádvoří u vchodu do Nové brány Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Míkajáš, syn Gemarjášův, vnuk Šáfanův, uslyšel všechna Hospodinova slova z té knihy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'a sestoupil do královského paláce do písařovy síně. Hle, tam seděla všechna knížata: Písař Elíšama, Delajáš, syn Šemajášův, Elnátan, syn Akbórův, Gemarjáš, syn Šáfanův, Sidkijáš, syn Chananjášův, a všechna ostatní knížata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Míkajáš jim oznámil všechna slova, která slyšel, když Báruk četl lidu z knihy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Všechna knížata poslala pro Báruka Jehudího, syna Netanjáše, syna Šelemjáše, syna Kúšího, se slovy: Vezmi ⌈s sebou⌉ ten svitek, ze kterého jsi četl lidu a přijď sem. Báruk, syn Nerijášův, vzal ⌈s sebou⌉ ten svitek a přišel k nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Pak mu řekli: Posaď se a čti nám z něj. Báruk jim tedy četl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Stalo se, když ⌈uslyšeli všechna ta slova,⌉ že polekaně pohlédli jeden na druhého a řekli Bárukovi: Určitě ⌈všechna tato slova⌉ oznámíme králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Báruka se zeptali: Pověz nám, jak jsi všechna tato slova napsal? ⌈Z jeho úst?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Báruk jim odpověděl: ⌈Svými ústy mi říkal⌉ všechna tato slova a já jsem je zapisoval inkoustem do knihy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Knížata řekla Bárukovi: Jdi, ukryj se, ty i Jeremjáš, aby nikdo nevěděl, kde jste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Oni pak šli na nádvoří ke králi. Svitek ponechali v pokoji písaře Elíšamy a oznámili králi všechna ta slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Král poslal Jehudího, aby vzal svitek. Vzal ho z pokoje písaře Elíšamy. Jehudí ho četl králi a ⌈všem knížatům,⌉ která stála okolo krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Král seděl v zimním paláci -- byl devátý měsíc -- a na ohništi před ním hořelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Když Jehudí přečetl tři nebo čtyři odstavce, král je odřízl písařským nožem a házel je do ohně, který byl na ohništi, dokud ne byl zničen celý svitek na ohni, který byl na ohništi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'A král ani žádní jeho otroci, kteří slyšeli všechna tato slova, se nepolekali a neroztrhli svá roucha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'I když Elnátan, Delajáš a Gemarjáš naléhali na krále s prosbou, aby svitek nepálil, neuposlechl je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Potom král přikázal Jerachmelovi, synu královu, Serajášovi, synu Azríelovu, a Šelemjášovi, synu Abdeelovu, aby písaře Báruka a proroka Jeremjáše zajali. Ale Hospodin je skryl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Potom, co král spálil svitek a slova, která napsal Báruk z Jeremjášových úst, stalo se k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Znovu si vezmi jiný svitek a napiš na něj všechna původní slova, která byla na prvním svitku, jejž judský král Jójakím spálil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'O judském králi Jójakímovi řekni: Toto praví Hospodin: Ty jsi spálil tento svitek se slovy: Proč jsi na něj napsal: Babylonský král jistě přijde a zničí tuto zemi; způsobí, že z ní zmizí lidé i zvěř?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Proto takto praví Hospodin o judském králi Jójakímovi: Nebude mít nikoho, kdo by seděl na Davidově trůnu, a jeho mrtvola bude uvržena ve dne na horko a v noci na mráz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Navštívím s trestem za jejich viny jeho, jeho potomstvo i jeho otroky a přivedu na ně, na obyvatele Jeruzaléma a na všechny Judejce všechno to zlo, které jsem vyslovil proti nim, ale ⌈ne chtěli slyšet.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Jeremjáš vzal jiný svitek a dal ho písaři Bárukovi, synu Nerijášovu. Ten na něj napsal z Jeremjášových úst všechna slova té knihy, kterou spálil ohněm judský král Jójakím, a ještě k nim bylo přidáno mnoho slov jako tato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Namísto Konjáše, syna Jójakímova, kraloval král Sidkijáš, syn Jóšijášův, kterého ustanovil králem v judské zemi babylonský král Nebúkadnesar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Ani on, jeho otroci ani lid země neposlouchali Hospodinova slova, která mluvil prostřednictvím proroka Jeremjáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Král Sidkijáš poslal Júkala, syna Šelemjášova, a kněze Sefanjáše, syna Maasejášova, k proroku Jeremjášovi se slovy: Modli se za nás, prosím, k Hospodinu, našemu Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, '(Tehdy Jeremjáš ⌈vcházel a vycházel⌉ mezi lidem; ještě ho nedali do vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Mezitím faraonovo vojsko vytáhlo z Egypta. Když ⌈ o nich⌉ Chaldejci, kteří obléhali Jeruzalém, uslyšeli zprávu, odtáhli od Jeruzaléma.)');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Potom se stalo k proroku Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Toto praví Hospodin, Bůh Izraele: Toto řekněte judskému králi, který vás poslal ke mně, abyste se mě dotázali: Hle, faraonovo vojsko, které vám táhne na pomoc, se navrátí do své země, do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Chaldejci se navrátí zpět, budou proti tomuto městu bojovat, dobudou ho a spálí ho ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Toto praví Hospodin: ⌈Nepodvádějte své duše⌉ slovy: Chaldejci od nás jistě odtáhnou, protože neodtáhnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'I kdybyste pobili celé chaldejské vojsko, které vede proti vám válku a zůstali by v něm jen probodení muži, všichni ve svých stanech povstanou a spálí toto město ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Stalo se, když chaldejské vojsko odtáhlo před faraonovým vojskem od Jeruzaléma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'že Jeremjáš vyšel z Jeruzaléma, aby šel do Benjamínovy země a tam ⌈obdržel svůj podíl vlastnictví mezi lidem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Když ⌈byl v Benjamínově bráně,⌉ stál tam ⌈vrchní dozorce⌉ jménem Jirijáš, syn Šelemjášův, vnuk Chananjášův. Ten proroka Jeremjáše chytil se slovy: ⌈Ty chceš zběhnout⌉ ke Chaldejcům!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremjáš řekl: To je lež! Nechci zběhnout ke Chaldejcům. Ale neposlouchali ho. Jirijáš Jeremjáše chytil a přivedl ho ke knížatům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Knížata se na Jeremjáše rozhněvala; zbila ho a dala ho do vězení, do domu písaře Jónatana, protože z něj udělala věznici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Jeremjáš se tedy dostal do žaláře, do kobky. Tam Jeremjáš pobyl ⌈mnoho dní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Potom pro něj král Sidkijáš poslal a přijal ho. Král se ho ve svém paláci tajně zeptal: Máš slovo od Hospodina? Jeremjáš řekl: Mám. A řekl: Budeš vydán do ruky babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Pak Jeremjáš králi Sidkijášovi řekl: Čím jsem zhřešil proti tobě, proti tvým otrokům a proti tomuto lidu, že jste mě dali do věznice?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Kde jsou vaši proroci, kteří vám prorokovali, že babylonský král nepřitáhne proti vám ani proti této zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Nyní, prosím, slyš, můj pane a králi! Kéž před tebe přijde moje úpěnlivá prosba! Neposílej mě zpět do domu písaře Jónatana, abych tam nezemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Král Sidkijáš přikázal, aby ponechali Jeremjáše na nádvoří stráží a aby mu dávali na den bochník chleba z pekařské ulice, dokud ve městě nedojde všechen chléb. Jeremjáš tedy pobýval na nádvoří stráží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Šefatjáš, syn Matánův, Gedaljáš, syn Pašchúrův, Júkal, syn Šelemjášův a Pašchúr, syn Malkijášův, slyšeli slova, která mluvil Jeremjáš ke všemu lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Toto praví Hospodin: Ten, kdo zůstane v tomto městě, zemře mečem, hladem a morem, ale ten, kdo vyjde ke Chaldejcům, bude žít; ⌈kořistí se mu stane jeho duše⌉ a bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Toto praví Hospodin: Toto město bude jistě vydáno do moci vojska babylonského krále a dobude ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Nato knížata řekla králi: Ať je tento muž konečně usmrcen, neboť takto oslabuje ruce bojovníků, kteří v tomto městě zůstali, a ruce všeho lidu, když k nim mluví taková slova. Vždyť tento muž nehledá pro tento lid pokoj, ale zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Král Sidkijáš řekl: Hle, je ve vaší ruce, protože král ⌈proti vám nic nezmůže.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Vzali Jeremjáše a hodili ho do cisterny královského syna Malkijáše, která byla na nádvoří stráží; spustili Jeremjáše po provaze. V cisterně ne byla voda, ale jen bahno, takže se Jeremjáš v bahně topil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Kúšijec Ebedmelek, dvorní úředník, který byl v královském paláci, uslyšel, že Jeremjáše dali do cisterny. Král seděl v té době v Benjamínově bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Ebedmelek odešel z královského paláce a promluvil ke králi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Můj pane a králi, zle jednali tito muži ve všem, co spáchali vůči proroku Jeremjášovi, že ho hodili do cisterny. Zemře tam hladem, protože ve městě už ne ní chléb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Nato král Kúšijci Ebedmelekovi přikázal: Vezmi s sebou odsud třicet mužů a vyndej proroka Jeremjáše z cisterny, dříve nežli zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Ebedmelek vzal s sebou muže, vešel ⌈dolů do skladu⌉ v královském paláci, vzal odtamtud ⌈obnošené a roztrhané hadry⌉ a spustil je po provaze Jeremjášovi do cisterny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Kúšijec Ebedmelek Jeremjášovi řekl: Polož si, prosím, obnošené a roztrhané hadry ⌈do podpaží⌉ pod provazy. Jeremjáš to udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Vytáhli Jeremjáše na provazech a vyndali ho z cisterny. Jeremjáš opět pobýval na nádvoří stráží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Král Sidkijáš poslal pro proroka Jeremjáše a nechal si ho přivést ke třetímu vchodu, který byl v Hospodinově domě. Král Jeremjášovi řekl: Ptám se tě na slovo. Nic přede mnou nezatajuj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremjáš Sidkijášovi řekl: Cožpak mě určitě nedáš usmrtit, když ti ho oznámím? A když ti poradím, neposlechneš mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Král Sidkijáš Jeremjášovi tajně přísahal: Živ je Hospodin, který nám ⌈dal tento život,⌉ že tě ne dám usmrtit, a že tě ne vydám do ruky těchto mužů, kteří usilují o tvůj život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Jeremjáš řekl Sidkijášovi: Toto praví Hospodin, Bůh zástupů, Bůh Izraele: Jestliže opravdu vyjdeš ke knížatům babylonského krále, tvá duše bude žít, toto město nebude spáleno ohněm a budeš žít ty i tvůj dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Jestliže však ke knížatům babylonského krále nevyjdeš, toto město bude vydáno do ruky Chaldejců a spálí ho ohněm; ani ty neunikneš z jejich ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Král Sidkijáš Jeremjášovi řekl: Bojím se Judejců, kteří přeběhli ke Chaldejcům, že mě vydají do jejich ruky a budou se mi posmívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Jeremjáš řekl: Nevydají. Poslechni, prosím, Hospodina, ohledně toho, co ti říkám. ⌈Povede se ti dobře⌉ a tvoje duše bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Jestliže se zdráháš vyjít, toto je slovo, které mi Hospodin ukázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Hle, všechny ženy, které zůstaly v paláci judského krále, budou vyvedeny ke knížatům babylonského krále a budou říkat: Tví ⌈důvěrní přátelé⌉ tě naváděli a přemohli tě. ⌈Tvoje nohy jsou ponořeny do bahna, oni se stáhli zpět.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Všechny tvé ženy a tvé syny vyvedou ke Chaldejcům, a ty jim neunikneš, ale budeš chycen ⌈babylonským králem⌉ a toto město bude spáleno ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Sidkijáš Jeremjášovi řekl: Ať se o ⌈těchto slovech⌉ nikdo nedozví, ⌈abys nezemřel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Když se knížata doslechnou, že jsem s tebou mluvil, přijdou k tobě a řeknou ti: Oznam nám, co jsi povídal králi? Nic před námi nezatajuj, ⌈ ať tě nedáme usmrtit.⌉ A co povídal král tobě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, '-- pak jim řekni: ⌈Předložil jsem⌉ před krále svoji úpěnlivou prosbu, aby mě neposílal zpět do Jónatanova domu, abych tam ne zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Všechna knížata přišla k Jeremjášovi a vyptávala se ho. On jim oznámil všechna ta slova, která mu přikázal král. Umlkla tedy před ním, protože se o té věci nikdo nedoslechl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Jeremjáš pobýval na nádvoří stráží až do dne, kdy byl Jeruzalém dobyt. Stalo se, když byl Jeruzalém dobýván,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'v devátém roce vlády judského krále Sidkijáše, v desátém měsíci, že k Jeruzalému přitáhl babylonský král Nebúkadnesar a celé jeho vojsko a oblehli ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'V jedenáctém roce vlády Sidkijáše, ve čtvrtém měsíci, v devátém dni toho měsíce, byl do města učiněn průlom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Všechna knížata babylonského krále vešla a usadila se v Prostřední bráně: Nergal–sareser, Samgar–nebú, vrchní úředník Sarsekím, vrchní mág Nergal–sareser a všechna ostatní knížata babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Stalo se pak, že když je uviděl judský král Sidkijáš a všichni bojovníci, utekli a vyšli v noci z města směrem ke královské zahradě bránou mezi dvěma hradbami; vyšli směrem k Arabě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Chaldejské vojsko je pronásledovalo a dostihlo Sidkijáše na jerišských pustinách. Zajali ho a přivedli ho k babylonskému králi Nebúkadnesarovi do Ribly v zemi Chamátu. Ten ⌈nad ním vyslovil rozsudek.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Babylonský král pobil před jeho zraky v Rible Sidkijášovy syny a také pobil všechny judské šlechtice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Oslepil Sidkijášovy oči, svázal ho bronzovými okovy, aby ho přivedl do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Královský palác i domy lidu spálili Chaldejci ohněm a jeruzalémské hradby strhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Zbytek lidu, který zůstal ve městě, přeběhlíky, kteří k němu přeběhli, zbytek lidu, který zůstal, odvedl velitel tělesné stráže Nebúzaradán do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Ale některé z chudých lidí, kteří nic neměli, ponechal velitel tělesné stráže Nebúzaradán v judské zemi a dal jim v onen den vinice a pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'O Jeremjášovi babylonský král Nebúkadnesar prostřednictvím velitele tělesné stráže Nebúzaradána přikázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Vezmi ho a ⌈dohlédni na něj.⌉ Nečiň mu nic zlého, ale co ti poví, to ⌈s ním⌉ učiň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Velitel tělesné stráže Nebúzaradán, vrchní úředník Nebúšazbán, vrchní mág Nergal–sareser a všichni velitelé babylonského krále');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, '⌈poslali pro Jeremjáše a nechali ho přivést⌉ z nádvoří stráží; dali ho Gedaljášovi, synu Achíkamovu, vnuku Šáfanovu, aby jej zavedl domů. Tak pobýval mezi svým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Když byl ještě zadržován na nádvoří stráží, stalo se k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Jdi a řekni Kúšijci Ebedmelekovi: Toto praví Hospodin zástupů, Bůh Izraele: Hle, naplním svá slova o tomto městě, k jeho zlu, a ne k dobru; v onen den se před tebou uskuteční.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Avšak tebe v onen den vysvobodím, je Hospodinův výrok, nebudeš vydán do ruky mužů, jichž se strachuješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Jistě tě zachráním, nepadneš mečem a tvoje duše se ti stane kořistí, protože jsi doufal ve mě, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, '⌈Slovo, které se stalo⌉ k Jeremjášovi od Hospodina poté, co ho velitel tělesné stráže Nebúzaradán propustil z Rámy; když ho nechal přivést, byl totiž spoután pouty mezi všemi jeruzalémskými a judskými vyhnanci, kteří byli odváděni do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Velitel tělesné stráže nechal Jeremjáše přivést a řekl mu: Hospodin, tvůj Bůh, vyslovil proti tomuto místu toto zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Hospodin to naplnil a učinil, jak promluvil, protože jste hřešili proti Hospodinu a neposlouchali jste ho. Proto se vám stala tato věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'A nyní hle, rozvázal jsem tě dnes z pout, která byla na tvých rukou. Jestliže ⌈ti připadá dobré⌉ jít se mnou do Babylona, pojď a ⌈dohlédnu na tebe.⌉ Ale jestli ⌈ti připadá zlé⌉ jít se mnou do Babylona, zastav se. Pohleď, celá země je před tebou. Jdi, kam ⌈ti připadá dobré a správné jít.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Když se stále nevracel, řekl mu: Vrať se ke Gedaljášovi, synu Achíkamovu, vnuku Šáfanovu, kterého babylonský král ustanovil za správce v judských městech; pobývej s ním mezi lidem nebo kamkoli ti připadá správné jít, jdi. Velitel tělesné stráže mu dal jídlo a dar a propustil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Jeremjáš tedy šel ke Gedaljášovi, synu Achíkamovu, do Mispy a pobýval s ním mezi lidem, který v zemi zůstal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Když všichni ⌈velitelé vojsk,⌉ kteří byli ještě v poli, oni i jejich muži uslyšeli, že babylonský král ustanovil v zemi za správce Gedaljáše, syna Achíkamova, a že s ním ponechal muže, ženy, malé děti, chudé země, kteří nebyli odvedeni do Babylona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'přišli ke Gedaljášovi do Mispy, totiž Jišmael, syn Netanjášův, Jóchanan a Jónatan, synové Karéachovi, Serajáš, syn Tanchumetův, synové Efaje Netófského, Jaazanjáš, syn Maakaťanův, oni i jejich muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Gedaljáš, syn Achíkamův, vnuk Šáfanův, ⌈jim a jejich mužům přísahal slovy:⌉ Nebojte se otročit Chaldejcům. Pobývejte v zemi, služte babylonskému králi a povede se vám dobře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, '⌈Co se mne týče,⌉ hle, já zůstanu v Mispě, abych vás zastupoval před Chaldejci, kteří k nám přijdou. Ale vy sklízejte víno, letní ovoce a olej a ukládejte si to do nádob a pobývejte ve svých městech, která jste zabrali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Také všichni Judejci, kteří byli v Moábu, mezi syny Amónovými, v Edómu a ve všech dalších zemích uslyšeli, že babylonský král zanechal Judovi ostatek a že nad nimi ustanovil za správce Gedaljáše, syna Achíkamova, vnuka Šáfanova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Všichni Judejci se navrátili ze všech míst, kam byli zahnáni a přišli do judské země ke Gedaljášovi do Mispy. Sklidili velmi mnoho vína a letního ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Jóchanan, syn Karéachův, a všichni velitelé vojsk, kteří byli v poli, přišli ke Gedaljášovi do Mispy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'a řekli mu: Jestlipak to víš, že Baalis, král synů Amónových, poslal Jišmaela, syna Netanjášova, aby ⌈tě ubil k smrti?⌉ Ale Gedaljáš, syn Achíkamův, jim nevěřil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Jóchanan, syn Karéachův, tajně Gedaljášovi v Mispě řekl: Půjdu a zabiju Jišmaela, syna Netanjášova, takže se to nikdo nedozví. ⌈Proč by tě měl ubít k smrti?⌉ Celý Juda, který se k tobě shromáždil, by byl rozptýlen a ostatek Judy by zahynul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Gedaljáš, syn Achíkamův, řekl Jóchananovi, synu Karéachovu: Nedělej to, protože o Jišmaelovi říkáš lež.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Stalo se v sedmém měsíci, že přišel Jišmael, syn Netanjášův, vnuk Elíšamův, z královského potomstva a z královských hodnostářů, a s ním deset mužů ke Gedaljášovi, synu Achíkamovu, do Mispy a jedli tam v Mispě pospolu pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Potom povstal Jišmael, syn Netanjášův, a deset mužů, kteří byli s ním, a zabili Gedaljáše, syna Achíkamova, vnuka Šáfanova, mečem. Tak usmrtil toho, koho babylonský král ustanovil za správce v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Jišmael zabil i všechny Judejce, kteří byli ⌈s Gedaljášem⌉ v Mispě a chaldejské bojovníky, kteří se tam nacházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Druhý den poté, co usmrtil Gedaljáše a nikdo o tom ještě nevěděl, se stalo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'že přišli muži z Šekemu, z Šíla a ze Samaří, osmdesát mužů, kteří měli ⌈ostříhané vousy, roztržená roucha a zasazené rány,⌉ s sebou měli přídavnou oběť a kadidlo, aby to přinesli do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Jišmael, syn Netanjášův, jim vyšel z Mispy naproti; šel a přitom plakal. A stalo se, když se s nimi setkal, že jim řekl: Jděte ke Gedaljášovi, synu Achíkamovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Stalo se však, když přišli doprostřed města, že Jišmael, syn Netanjášův, je pobil a hodil do cisterny, on a muži, kteří byli s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Ale bylo mezi nimi deset mužů, kteří Jišmaelovi řekli: Neusmrcuj nás, protože máme v poli skryté zásoby: Pšenici a ječmen, olej a med. Nechal je a neusmrtil je ⌈spolu s ostatními.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Cisterna, do níž hodil Jišmael všechny mrtvoly mužů, jež zabil ⌈spolu s Gedaljášem,⌉ byla ta, kterou udělal král Ása kvůli izraelskému králi Baešovi. Tu Jišmael, syn Netanjášův, naplnil pobitými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Potom Jišmael zajal celý ostatek lidu, který byl v Mispě: Královské dcery a všechen lid, který zůstal v Mispě, který velitel tělesné stráže Nebúzaradán ponechal s Gedaljášem, synem Achíkamovým. Jišmael, syn Netanjášův, je zajal a chtěl přejít k synům Amónovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Když Jóchanan, syn Karéachův, a všichni velitelé vojsk, kteří byli s ním, uslyšeli o všem tom zlu, které Jišmael, syn Netanjášův, spáchal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'vzali všechny své muže a vytáhli bojovat s Jišmalem, synem Netanjášovým. Našli ho u velkého rybníka, který je v Gibeónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Stalo se, když všechen lid, který byl s Jišmalem, uviděl Jóchanana, syna Karéachova, a všechny velitele vojsk, kteří byli s ním, že se zaradovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Všechen lid, který Jišmael zajal v Mispě, se odvrátil a navrátil a šel k Jóchananovi, synu Karéachovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Jišmael, syn Netanjášův, s osmi muži před Jóchananem unikl a šel k synům Amónovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Jóchanan, syn Karéachův, a všichni velitelé vojsk, kteří byli s ním, vzali celý ostatek ⌈lidu, který Jišmael, syn Netanjášův, odvedl z Mispy poté, co zabil⌉ Gedaljáše, syna Achíkamova -- muže, bojovníky, ženy, malé děti a dvorní úředníky, které přivedl zpět z Gibeónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Vytáhli a pobyli v Gerút Kimháma, který je blízko Betléma; chtěli jít dál do Egypta');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'před Chaldejci, neboť se jich báli, že Jišmael, syn Netanjášův, zabil Gedaljáše, syna Achíkamova, kterého babylonský král ustanovil za správce v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Potom všichni velitelé vojsk, Jóchanan, syn Karéachův, Jaazanjáš, syn Hóšajášův, a všechen lid, od nejmenšího do největšího, přistoupili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'a řekli proroku Jeremjášovi: Kéž před tebe přijde naše úpěnlivá prosba. Modli se za nás k Hospodinu, svému Bohu, za celý tento ostatek, neboť nás zůstalo jen málo z mnoha, ⌈jak nás tvoje oči vidí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Ať nám Hospodin, tvůj Bůh, oznámí cestu, po které máme jít, a co máme dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Prorok Jeremjáš jim řekl: Dobře. Hle, budu se modlit k Hospodinu, vašemu Bohu, podle vašich slov. I stane se, že vám oznámím ⌈všechno, co⌉ vám Hospodin odpoví. Nic před vámi nezatajím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Oni Jeremjášovi řekli: Ať je Hospodin spolehlivým a věrným svědkem proti nám, jestliže neučiníme ⌈všechno tak, jak nám po tobě vzkáže⌉ Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, '⌈Ať to bude dobré či zlé,⌉ uposlechneme Hospodina, svého Boha, k němuž tě posíláme, aby se nám dobře vedlo, když uposlechneme Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Po deseti dnech se stalo k Jeremjášovi Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Zavolal tedy Jóchanana, syna Karéachova, všechny velitele vojsk, kteří s ním byli i všechen lid od nejmenšího do největšího');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'a řekl jim: Toto praví Hospodin, Bůh Izraele, k němuž jste mě poslali, abych před něj předložil vaši úpěnlivou prosbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Jestliže opravdu budete pobývat v této zemi, vystavím vás a nezbořím, zasadím vás a nevyrvu, protože budu litovat zla, které jsem vám učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Nebojte se babylonského krále, jehož se bojíte. Nebojte se ho, je Hospodinův výrok, protože já jsem s vámi, abych vás zachránil a vysvobodil z jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Dám vám slitování a slituji se nad vámi a přivedu vás zpět do vaší země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Jestliže však řeknete: Nebudeme pobývat v této zemi, neuposlechnete Hospodina, svého Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'a místo toho řeknete: Ne, my půjdeme do egyptské země, kde neuvidíme válku a neuslyšíme zvuk beraního rohu a kde nebudeme hladovět, tam budeme pobývat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'potom nyní, ostatku Judy, jistě slyšte Hospodinovo slovo: Toto praví Hospodin zástupů, Bůh Izraele: Jestliže ⌈jste opravdu rozhodnuti⌉ jít do Egypta a přijdete tam pobývat jako cizinci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'pak se stane, že meč, kterého se bojíte, vás tam v egyptské zemi dostihne a hlad, kterého se obáváte, na vás tam v Egyptě dolehne a zemřete tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Stane se, že všichni muži, kteří ⌈jsou rozhodnuti⌉ jít do Egypta, aby tam pobývali jako cizinci, zemřou mečem, hladem a morem. Nikdo z nich nepřežije ani ne unikne před zlem, které na ně přivedu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Neboť toto praví Hospodin zástupů, Bůh Izraele: Jako byl vylit můj hněv a má zloba na obyvatele Jeruzaléma, tak se rozleje má zloba na vás, když půjdete do Egypta. Stanete se prokletím, předmětem hrůzy, kletbou a potupou a toto místo už neuvidíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Hospodin k vám, ostatku Judy, promluvil: Nechoďte do Egypta! To vězte, že jsem vás dnes varoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Vždyť ⌈jste se nechali svést vlastní duší.⌉ Vy jste mě přece poslali k Hospodinu, svému Bohu, se slovy: Modli se za nás k Hospodinu, našemu Bohu, a všechno, co řekne Hospodin, náš Bůh, nám oznam a uděláme to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Dnes jsem vám to oznámil, ale neuposlechli jste Hospodina, svého Boha ani nic z toho, co vám po mně vzkázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'A nyní s jistotou vězte, že mečem, hladem a morem zemřete na tom místě, kam se vám zalíbilo jít, abyste tam pobývali jako cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Stalo se, když Jeremjáš domluvil ke všemu lidu všechna slova Hospodina, jejich Boha, která jim po něm vzkázal Hospodin, jejich Bůh, všechna tato slova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Azarjáš, syn Hóšajášův, Jóchanan, syn Karéachův, a všichni domýšliví muži Jeremjášovi řekli: Mluvíš lež! Hospodin, náš Bůh, tě neposlal se slovy: Nechoďte do Egypta, abyste tam pobývali jako cizinci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'ale Báruk, syn Nerijášův, tě proti nám podněcuje, aby nás vydal do ruky Chaldejců, aby nás usmrtili či nás odvedli do zajetí do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Jóchanan, syn Karéachův, všichni velitelé vojsk a všechen lid tedy neuposlechli Hospodina, aby bydleli v judské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Jóchanan, syn Karéachův, a všichni velitelé vojsk vzali celý ostatek Judy, ty, kteří se navrátili ze všech národů, kam byli zahnáni, aby pobývali v judské zemi jako cizinci --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'muže, ženy a malé děti, královské dcery i všechny lidi, které ponechal velitel tělesné stráže Nebúzaradán s Gedaljášem, synem Achíkamovým, vnukem Šáfanovým, a také proroka Jeremjáše a Báruka, syna Nerijášova, --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'a šli do egyptské země, protože neuposlechli Hospodina. Došli až do Tachpanchésu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'V Tachpanchésu se stalo k Jeremjášovi Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Vezmi si velké kameny, před zraky Judejců je ukryj maltou v cihlové dlažbě, která je u vchodu do faraonova paláce v Tachpanchésu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'a řekni jim: Toto praví Hospodin zástupů, Bůh Izraele: Hle, pošlu a vezmu babylonského krále Nebúkadnesara, svého otroka, a ⌈postavím jeho⌉ trůn nad těmito kameny, které jsem ukryl, a roztáhne nad nimi svůj baldachýn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Přitáhne a bude bít egyptskou zemi: Kdo je určen k smrti, půjde na smrt, kdo pro zajetí, do zajetí a kdo pro meč, pod meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Zapálí oheň v domech egyptských bohů; spálí je či odvede. Odvšiví egyptskou zemi jako pastýř odvšivuje své roucho. Pak odtamtud v pokoji odtáhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Roztříská posvátné sloupy v Bét–šemeši, který je v egyptské zemi, a domy egyptských bohů spálí ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Slovo, které se stalo k Jeremjášovi o všech Judejcích, bydlících v egyptské zemi, bydlících v Migdólu, v Tachpanchésu, v Memfidě a v zemi Patrósu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Toto praví Hospodin zástupů, Bůh Izraele: Viděli jste všechno zlo, které jsem přivedl na Jeruzalém a na všechna judská města. Hle, jsou z nich dnes trosky a nikdo v nich ne bydlí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'kvůli jejich zlu, které páchali, aby mě rozzlobili, když chodili obětovat a sloužit jiným bohům, které neznali oni, ani vy, ani vaši otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Posílal jsem vám všechny své otroky proroky, stále znovu jsem je posílal se slovy: Nečiňte tuto odpornou věc, kterou nenávidím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Ale neposlouchali a nenakláněli ucho, aby se odvrátili od svého zla a neobětovali jiným bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Moje zloba a můj hněv se rozlily a vzplály v judských městech a v jeruzalémských ulicích. Staly se troskami a zcela opuštěnými místy, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'A nyní toto praví Hospodin, Bůh zástupů, Bůh Izraele: Proč pácháte tak velké zlo ⌈svým duším,⌉ aby vám byl vyhlazen muž i žena, dítě i kojenec zprostřed Judy a nezůstal vám ostatek?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Abyste mě rozzlobili dílem svých rukou, obětujete jiným bohům v egyptské zemi, kam jste přišli pobývat jako cizinci? Abyste byli vyhlazeni? Abyste se stali kletbou a potupou mezi všemi národy země?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Cožpak jste zapomněli na zlé skutky svých otců, zlé skutky judských králů, zlé skutky jejich žen, na své vlastní zlé skutky i zlé skutky svých žen, které páchali v judské zemi a na ulicích Jeruzaléma?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Dodnes se nepokořili, nebáli a nežili podle mého zákona a podle mých ustanovení, která jsem předložil vám a vašim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Proto takto praví Hospodin zástupů, Bůh Izraele: Hle, ⌈jsem rozhodnut uvést na vás zlo⌉ a vyhladit celého Judu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Vezmu ostatek Judy, ty, kteří ⌈se rozhodli jít⌉ do egyptské země pobývat tam jako cizinci. V egyptské zemi všichni zahynou, padnou mečem a hladem. Zahynou od nejmenšího do největšího, zemřou mečem a hladem. Stanou se prokletím, předmětem hrůzy, kletbou a potupou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Tak jako jsem navštívil Jeruzalém, navštívím ty, kteří bydlí v egyptské zemi, mečem, hladem a morem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, '⌈Neunikne ani ne přežije nikdo z ostatku⌉ Judy, z těch, kteří přijdou pobývat do egyptské země jako cizinci; nenavrátí se do judské země, kam se jejich duše touží vrátit bydlet; ale nevrátí se, jen pár utečenců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Nato všichni muži, kteří věděli, že jejich ženy obětovaly jiným bohům, a všechny ženy, které stály ve velkém shromáždění, a všechen lid, který bydlel v egyptské zemi, v Patrósu, Jeremjášovi odpověděli slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Co se týče slova, které jsi k nám mluvil v Hospodinově jménu, nebudeme tě poslouchat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'nýbrž jistě splníme všechno, co ⌈vyšlo z našich úst;⌉ budeme obětovat královně nebes a lít jí úlitby tak, jak jsme to dělávali my i naši otcové, naši králové a naše knížata v judských městech a na ulicích Jeruzaléma. Nasytili jsme se chlebem, bylo nám dobře a zlo jsme neviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Ale od té doby, co jsme přestali obětovat královně nebes a lít jí úlitby, jsme měli nedostatek ve všem a hynuli jsme mečem a hladem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'A když jsme obětovaly královně nebes a lily jí úlitby, cožpak jsme jí pekly koláče, ⌈abychom ji zobrazily,⌉ a lily jí úlitby bez vědomí svých mužů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Jeremjáš všemu lidu, mužům, ženám a všemu lidu, který mu toto odpovídal, řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Cožpak si Hospodin nepamatoval oběti, které jste pálili v judských městech a na ulicích Jeruzaléma vy, vaši otcové, vaši králové, vaše knížata a lid země, a ne přišlo mu to na mysl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Hospodin už nemohl snést vaše zvrácené činy a ohavnosti, které jste páchali. Proto se vaše země stala troskami, hroznou pustinou, kletbou, bez obyvatel, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Protože jste pálili oběti, protože jste hřešili proti Hospodinu a neposlouchali jste Hospodina, nežili jste podle jeho zákona, jeho ustanovení a jeho varování, proto vás postihlo toto zlo, jak je tomu dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Potom Jeremjáš všemu lidu a všem ženám řekl: Slyšte Hospodinovo slovo, ⌈všichni Judejci,⌉ kteří jste v egyptské zemi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Toto praví Hospodin zástupů, Bůh Izraele: Vy i vaše ženy jste svými ústy vyslovili a svýma rukama pak naplnili slova: Jistě splníme svoje sliby, které jsme učinili, že budeme obětovat královně nebes a lít jí úlitby. Jen si svoje sliby plňte, jen si svoje sliby uskutečňujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Proto slyšte Hospodinovo slovo, ⌈všichni Judejci,⌉ kteří bydlíte v egyptské zemi: Hle, přísahám při svém velikém jménu, praví Hospodin: V celé egyptské zemi se už ne stane, že by bylo vzýváno mé jméno ústy nějakého Judejce, který říká: Jakože živ je Panovník Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Hle, bdím nad nimi ke zlu a ne k dobru. Všichni Judejci, kteří jsou v egyptské zemi, budou hynout mečem a hladem až budou úplně zničeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Ti, kteří unikli meči, se z egyptské země do země judské navrátí v malém počtu, a celý ostatek Judy, ti, kteří přišli do egyptské země pobývat jako cizinci, poznají, čí slovo se naplní, zda ⌈moje, anebo jejich.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'A toto vám bude znamením, je Hospodinův výrok, že vás navštívím na tomto místě, abyste poznali, že ⌈se jistě naplní má slova o vás ke zlému:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Toto praví Hospodin: Hle, dávám faraona Chofru, egyptského krále, do ruky jeho nepřátel a do ruky těch, kdo ⌈usilují o jeho život,⌉ tak jako jsem dal judského krále Sidkijáše do ruky babylonského krále Nebúkadnesara, jeho nepřítele, který usiloval o jeho život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Slovo, které mluvil prorok Jeremjáš k Bárukovi, synu Nerijášovu, když zapisoval tato slova z Jeremjášových úst do knihy, ve čtvrtém roce vlády judského krále Jójakíma, syna Jóšijášova:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Toto praví Hospodin, Bůh Izraele, o tobě, Báruku:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Říkáš: Běda mi, neboť Hospodin přidal k mé bolesti žal. Jsem unaven svým vzdycháním a upokojení nenacházím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Řekni mu toto: Takto praví Hospodin: Hle, co jsem vystavěl, bořím, co jsem zasadil, vyvracím -- celou tuto zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Hledáš pro sebe velké věci? Nehledej! Protože hle, přivedu zlo na každé tělo, je Hospodinův výrok, ale tobě dám tvou duši za kořist na každém místě, kamkoliv půjdeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Hospodinovo slovo, které se stalo k proroku Jeremjášovi ⌈proti národům:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'O Egyptu; proti vojsku faraona Néka, egyptského krále, které bylo u řeky Eufratu v Karkemíši a které pobil babylonský král Nebúkadnesar ve čtvrtém roce vlády judského krále Jójakíma, syna Jóšijášova:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Připravte malý i velký štít a ⌈pusťte se do boje!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Zapřáhněte koně a nasedněte, jezdci! Postavte se v přilbách, naleštěte oštěpy, oblečte si pancíře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, '⌈Proč vidím, že jsou⌉ naplněni děsem a ustupují zpět? Jejich hrdinové jsou zabíjeni, utíkají do útočiště, ani se ne otáčejí -- všude kolem hrůza, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, '⌈Rychlonohý neuteče, hrdina⌉ neunikne, na severu u řeky Eufratu klopýtnou a padnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kdo to vystupuje jako Nil, jako řeky, jejichž vody se dmou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egypt vystupuje jako Nil, jako řeky, jejichž vody se dmou. Řekl: Vystoupím a přikryji zemi, odstraním město i jeho obyvatele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Nasedněte na koně! Zběsile jeďte, vozy! Ať vytáhnou hrdinové, Kúšijci a Pútejci, kteří nosí štít, i Lúďané, kteří nosí a napínají luk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Tento den patří Panovníku, Hospodinu zástupů, je dnem pomsty, aby se pomstil nad svými protivníky. Meč bude požírat, nasytí a napojí se jejich krví, neboť Panovník, Hospodin zástupů, má obětní hod v severní zemi, u řeky Eufratu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Vystup do Gileádu a vezmi balzám, panno, egyptská dcero! Nadarmo si děláš spoustu léků, zacelení rány pro tebe ne ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Národy uslyšely o tvé hanbě a tvůj křik naplnil zemi, protože ⌈ jeden hrdina klopýtl přes druhého,⌉ oba společně padli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Slovo, které promluvil Hospodin k proroku Jeremjášovi o tom, že babylonský král Nebúkadnesar přitáhne, aby pobil egyptskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Oznamte v Egyptě, zvěstujte v Migdólu, zvěstujte v Memfidě a v Tachpanchésu! Řekněte: Postav se a připrav se, protože meč požírá ⌈tvé okolí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Proč ⌈utekl Apis? Proč nezůstal tvůj býk stát? Protože⌉ ho srazil Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Způsobil, že mnozí klopýtli, jeden padal přes druhého. Říkali: Vstaňme a vraťme se ke svému lidu a do své rodné země před krutým mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, '⌈Faraona, egyptského krále, nazvěte:⌉ Hukot, který nechal minout určený čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Jakože jsem živ, je výrok krále, jehož jméno je Hospodin zástupů: Jako ční Tábor mezi horami a Karmel ⌈nad mořem,⌉ ⌈ někdo takový přijde.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Sbal si věci do vyhnanství, usazená egyptská dcero, protože Memfis se stane děsivou krajinou, bude vypálena, bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Egypt je překrásná jalovice, ⌈letí, ano letí na ni ⌉ střeček ze severu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'I jeho žoldnéři jsou uprostřed něj jako vykrmená telata, ale i oni se obrátili a společně utekli, ⌈nezůstali stát, protože na ně přišel⌉ den jejich pohromy, čas jejich navštívení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, '⌈ Bude vydávat zvuk jako prchající had,⌉ až přitáhnou s vojskem a půjdou proti Egyptu se sekerami jako dřevorubci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Pokácejí jeho les, je Hospodinův výrok, ačkoliv je neproniknutelný, protože jich je víc než kobylek, je jich bez počtu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Egyptská dcera je zahanbena, je vydána do ruky lidu ze severu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Hospodin zástupů, Bůh Izraele, praví: Hle, navštívím Amóna z Théb, faraona a Egypt, jeho bohy i jeho krále; faraona i ty, kteří v něho doufají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Vydám je do ruky těch, kdo usilují o jejich život, do ruky babylonského krále Nebúkadnesara a do ruky jeho otroků. Později však bude osídlen jako za dávných časů, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Ty však se neboj, můj otroku Jákobe, a neděs se, Izraeli, protože hle, já tě zachráním z dalekých končin a tvé potomstvo ze země jejich zajetí. Jákob se navrátí, bude mít klid, bude bezstarostný a nikdo ho nevyděsí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ty se neboj, můj otroku Jákobe, je Hospodinův výrok, protože já jsem s tebou, protože úplně zničím všechny národy, mezi které jsem tě rozehnal. Ale tebe nezničím úplně, nýbrž napravím tě podle práva; jistě tě nenechám bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Hospodinovo slovo, které se stalo k proroku Jeremjášovi o Pelištejcích, dříve nežli faraon pobil Gazu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Toto praví Hospodin: Hle, voda vystupuje od severu a stane se rozvodněným potokem. Zaplaví zemi i všechno, co ji naplňuje, města i jejich obyvatele. Lidé budou volat o pomoc a všichni obyvatelé země budou naříkat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Pro zvuk dusotu kopyt jeho hřebců, hřmotem jeho vozů a pro rachot jeho kol ⌈se otcové neobrátili k synům,⌉ ⌈pro ochablost rukou⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'kvůli dni, který přichází zničit všechny Pelištejce, vyhladit Týru a Sidónu každého zbylého pomocníka, protože Hospodin zničí Pelištejce, ostatek ostrova Kaftór.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, '⌈Gaza oplešatěla,⌉ Aškalón umlkl. Ostatku Anákovců, dokdy si budeš zasazovat rány?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ach, Hospodinův meči! Jak dlouho nebudeš mít klid? Stáhni se do pochvy, zastav a ustrň!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Jak může mít klid, když mu Hospodin dal příkaz? Proti Aškalónu a proti mořskému pobřeží, tam jej určil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'O Moábu. Toto praví Hospodin zástupů, Bůh Izraele: Běda Nebó, protože je zničeno. Kirjatajim je zahanben, je dobyt; pevnost je zahanbena a rozdrcena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Už ne ní Moábovy chvály. V Chešbónu proti němu zamýšlejí zlo: Pojďte a vyhlaďme ho ⌈jako národ.⌉ Také ty, Madméne, umlkneš, půjde za tebou meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Slyš! Volání z Chóronajimu, zkáza a velká pohroma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moáb je rozdrcen! ⌈Rozhlašují úpěnlivým křikem jeho služebníci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Po luchítském svahu vystupují ve stálém pláči, na stráni do Chóronajimu ⌈je slyšet úzkostný⌉ křik nad zkázou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Utečte, zachraňte své duše a budete jako jalovec v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Protože jsi spoléhal na své statky a na své poklady, také tebe dobudu. Kemóš půjde do vyhnanství spolu se svými kněžími a knížaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Ničitel přijde do každého města a žádné město neunikne. Údolí zahyne, rovina bude zničena, jak řekl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, '⌈Postavte Moábovi náhrobní kámen,⌉ neboť ⌈jistě padne.⌉ Jeho města se stanou děsivou věcí, budou bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Proklet je ten, kdo činí Hospodinovu práci nedbale! Proklet je ten, kdo zadržuje svůj meč od krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Od svého mládí byl Moáb bezstarostný, byl usazen jako víno na svém kalu, nebyl přeléván z nádoby do nádoby, ani nešel do vyhnanství; proto mu zůstala jeho chuť a jeho vůně se nezměnila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Proto hle, přicházejí dny, je Hospodinův výrok, kdy mu pošlu ty, kteří stáčejí víno, a ti jej stočí, jeho nádoby vyprázdní a jeho džbány roztříští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Moáb se bude stydět za Kemóše, tak jako se dům izraelský styděl za Bét–el, svou naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Jak to, že říkáte: Jsme hrdinové, udatní bojovníci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moáb je zničen, ⌈ muži vystoupili do jeho měst,⌉ nejlepší z jeho mládenců sestoupili na porážku, je výrok krále, jehož jméno je Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Moábova pohroma přijde brzy; jeho zlo velmi pospíchá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Naříkej nad ním ⌈celé jeho okolí,⌉ všichni, kdo znáte jeho jméno! Říkejte: ⌈Jak to, že⌉ je zlomeno ⌈mocné žezlo, nádherná berla?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Sestup ze slávy a usaď se ⌈ve vyprahlém kraji,⌉ obyvatelko, díbónská dcero, protože ničitel Moába vytáhl proti tobě a zničil tvoje pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Stůj na cestě a vyhlížej, obyvatelko Aróeru! Vyptávej se ⌈ muže, který utíká, i ženy, která se snaží uniknout!⌉ Zeptej se: Co se stalo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moáb se stydí, protože je rozdrcen. Naříkejte, křičte! Oznamte v Arnónu, že je Moáb zničen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Soud přišel na Rovinu -- na Cholón, na Jahas i na Méfaat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'na Díbón, na Nebó, na Bét–diblatajim,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'na Kirjatajim, na Bét–gamúl, na Bét–meón,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'na Kerijót, na Bosru i na všechna vzdálená i blízká města moábské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, '⌈Moábův roh byl useknut a jeho paže⌉ byla zlomena, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Opijte ho, protože se vyvyšoval na Hospodina. ⌈ Ať se Moáb válí ve svých zvratcích;⌉ i on se stane posměchem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Cožpak se ti nestal Izrael posměchem? Cožpak byl nalezen mezi zloději, že pokaždé, kdy o něm mluvíš, potřásáš hlavou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Opusťte města, usídlete se na skále, obyvatelé Moábu! Buďte jako holubice, která hnízdí na okraji ústí rokliny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Slyšeli jsme o Moábově pýše, je velice pyšný, o jeho povýšenosti, o jeho pýše, o jeho hrdosti i o domýšlivosti jeho srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Já znám jeho nadutost, je Hospodinův výrok, ⌈nesprávné jsou prázdné řeči,⌉ nesprávně jednali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Proto naříkám nad Moábem, volám o pomoc pro celý Moáb, vzdychám nad muži Kir–cheresu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, '⌈Víc než nad Jaezerem⌉ pláču nad tebou, révo Sibmy. Tvoje úponky překročily moře, dosáhly až k Jaezeru, na tvé letní ovoce i na tvé vinobraní vpadl ničitel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Vzaty byly ⌈radost i jásání⌉ z ovocného sadu, z moábské země. Způsobil jsem, že zmizelo víno z lisů, nikdo nebude šlapat víno s jásotem; jásot ne bude radostným jásotem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, '⌈Úpěnlivý křik z Chešbónu zní až do Eleále, až do Jahasu, volají od Sóaru až do Chóronajimu⌉ a Eglat–šelišiji, protože i vody nimrímské budou zpustošené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Způsobím, je Hospodinův výrok, že z Moába zmizí ti, kdo vystupují na návrší a pálí oběti svým bohům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Proto mé srdce vzlyká nad Moábem jako flétna, mé srdce vzlyká jako flétna nad muži Kir–cheresu, protože úspory, které získal, přišly vniveč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Vždyť každá hlava je lysá, každý vous je ostříhán, na všech rukách jsou zářezy a kolem beder pytlovina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Na všech Moábových střechách a na jeho náměstích je jen kvílení, protože jsem Moába rozbil jako nádobu, v níž nikdo ne má zalíbení, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Jak je rozdrcen, naříkají! Jak ⌈Moáb obrací záda a stydí se!⌉ Moáb se stane posměchem a postrachem pro celé svoje okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Neboť toto praví Hospodin: Hle, poletí jako orel a roztáhne nad Moábem svá křídla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerijót je zajat a pevnosti dobyty. Srdce moábských hrdinů bude v onen den jako srdce ženy v porodních bolestech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Moáb bude zničen jako národ, protože se vyvyšoval na Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Strach, propast a past na tebe, obyvateli Moábu, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Kdo uteče strachem, padne do propasti, a kdo vyleze z propasti, bude polapen do pasti, protože na něj, na Moába, přivedu rok navštívení, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Vysílení utečenci zůstali stát ve stínu Chešbónu. Avšak z Chešbónu vyšlehl oheň a z domu Síchona plamen a strávil skráně Moába a temeno synů hukotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Běda tobě, Moábe! Kemóšův lid zahynul, neboť tvoji synové byli vzati do zajetí a tvoje dcery do vyhnanství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Ale v posledních dnech Moábův úděl změním, je Hospodinův výrok. Až potud soud nad Moábem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'O synech Amónových. Toto praví Hospodin: Cožpak Izrael nemá syny? Copak nemá dědice? Proč Milkóm vlastní Gáda a jeho lid se usadil v jeho městech?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Proto hle, přicházejí dny, je Hospodinův výrok, kdy nechám zaznít válečný křik proti Rabě synů Amónových. Stane se zcela opuštěnou ruinou a její vesnice budou vypáleny ohněm. Izrael dostane do vlastnictví své vlastníky, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Naříkej Chešbóne, protože Aj je zničen! Křičte, dcery Raby, přepásejte se pytlovinou, bědujte a ⌈bloumejte mezi ohradami,⌉ protože Milkóm půjde do vyhnanství, jeho kněží spolu s jeho knížaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Proč se chlubíš ⌈údolími, svým oplývajícím údolím,⌉ odpadlá dcero, která doufáš ve své poklady a říkáš: ⌈Kdo přijde proti mně?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Hle, přivedu na tebe strach ⌈z celého tvého okolí,⌉ je výrok Panovníka, Hospodina zástupů. Budete zahnáni každý jinam a ne bude, kdo by utečence shromáždil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Potom však změním úděl synů Amónových, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'O Edómu. Toto praví Hospodin zástupů: Cožpak už v Témanu ne ní moudrost? Rozumným zmizela rada? Byla jejich moudrost zmařena?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Utečte, obraťte se a usídlete se v hlubinách, obyvatelé Dedánu! Protože na něj přivedu Ezauovu pohromu, čas, kdy ho navštívím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Kdyby na tebe přišli česači hroznů, což nezanechají paběrky? Kdyby přišli zloději v noci, budou ničit, dokud nebudou mít dost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Neboť já jsem obnažil Ezaua, odhalil jsem jeho skrýše, nebude se moci ukrýt. Jeho potomstvo je zničeno, jeho bratři i jeho sousedi -- ⌈ už není.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Zanech svoje sirotky, já je zachovám při životě a ať tvoje vdovy doufají ve mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Neboť toto praví Hospodin: Hle, ti, ⌈kteří pít kalich správně neměli,⌉ pít musejí a ty bys měl zůstat bez trestu? Nezůstaneš bez trestu, ale musíš pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Vždyť jsem přísahal při sobě, je Hospodinův výrok, že Bosra se stane předmětem hrůzy, potupou, pustinou a kletbou a všechna její města se stanou věčnými troskami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Slyšel jsem zprávu od Hospodina, vyslanec byl poslán mezi národy: Shromážděte se a vytáhněte proti ní, povstaňte k boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Neboť hle, učiním tě malým mezi národy, opovrženým mezi lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Hrůza, ⌈kterou jsi budil,⌉ tě podvedla, i domýšlivost tvého srdce, tebe, který bydlíš ve skalních rozsedlinách, tebe, jenž jsi obsadil vrchol kopce. Ačkoliv stavíš své hnízdo vysoko jako orel, svrhnu tě odtamtud, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Edóm se stane děsivou krajinou; ⌈každý, kdo jím bude procházet, se zhrozí a podiví se všem jeho ranám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Jako po vyvrácení Sodomy, Gomory a jejich sousedních měst, praví Hospodin, nikdo se tam neusadí, ⌈syn člověka⌉ v něm nebude pobývat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Hle, vystupuje jako lev z jordánské houštiny na stále zelenou pastvinu, ale v okamžiku ho z ní zaženu a určím nad ní toho, kdo je vyvolený. Neboť kdo je jako já? Kdo mě předvolá k soudu? Kdo je ten pastýř, který přede mnou obstojí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Proto slyšte Hospodinovo rozhodnutí, které učinil o Edómu, jeho plány, které vymýšlí proti obyvatelům Témanu: Jistě je budou vláčet, i nejmenší ze stáda. Jistě kvůli nim zpustoší jeho pastvinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Zvukem jejich pádu se třese země. Zní volání, jeho zvuk je slyšet až u Rákosového moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Hle, vzlétne jako orel, poletí a roztáhne svá křídla nad Bosrou. V onen den bude srdce edómských hrdinů jako srdce ženy v porodních bolestech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'O Damašku. Chamát a Arpád je zahanben, protože slyšeli zlou zprávu. ⌈Jsou bezradní, jako když je na moři nepokoj⌉ a nemůže se utišit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damašek ochabl, obrátil se na útěk. Zmocnilo se ho zděšení, zachvátila jej tíseň a bolest jako rodičku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, '⌈Jak je opuštěné⌉ ⌈slavné město,⌉ město radosti!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Proto jeho mládenci padnou na jeho náměstích a v onen den všichni bojovníci zahynou, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Zapálím oheň na hradbách Damašku a ten stráví Ben–hadadovy paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'O Kédaru a o královstvích Chasóru, která pobil babylonský král Nebúkadnesar. Toto praví Hospodin: Povstaňte, vytáhněte proti Kédaru a zničte syny východu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Vezmou jejich stany a jejich stáda, jejich stanové plachty a všechny jejich nástroje; jejich velbloudy odvedou pro sebe a budou na ně volat: Všude kolem hrůza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Utečte, rychle prchněte, usídlete se v hlubinách, obyvatelé Chasóru, je Hospodinův výrok, protože babylonský král Nebúkadnesar o vás učinil rozhodnutí a vymýšlí proti vám plán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Vstaňte, vytáhněte proti národu, který bezstarostně bydlí v bezpečí, je Hospodinův výrok; nemá vrata ani závory, bydlí o samotě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Jejich velbloudi se stanou kořistí, stáda jejich dobytka lupem. Rozptýlím je do všech větrů, ty s vyholenými skráněmi, a ze všech stran na ně přivedu pohromu, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Chasór se stane doupětem šakalů, zcela opuštěným místem navěky, nikdo se tam neusadí, syn člověka v něm nebude pobývat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Hospodinovo slovo, které se stalo k proroku Jeremjášovi o Élamu na počátku kralování judského krále Sidkijáše:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Toto praví Hospodin zástupů: Hle, ⌈zlomím luk Élamu, prvotinu jeho síly.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, '⌈Přivedu proti Élamu čtyři větry od čtyř konců nebes⌉ a rozptýlím je do všech těchto větrů a nebude národ, kam by zapuzení z Élamu nepřišli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Roztřesu Élam strachem před jejich nepřáteli, před těmi, kdo usilují o jejich život. Přivedu na ně zlo, svůj planoucí hněv, je Hospodinův výrok. Pošlu za nimi meč, dokud s nimi ne skoncuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Postavím v Élamu svůj trůn a odstraním odtamtud krále i knížata, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Ale v posledních dnech se stane, že změním Élamův úděl, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Slovo, které mluvil Hospodin o Babylonu, o chaldejské zemi, prostřednictvím proroka Jeremjáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Oznamte a rozhlaste to mezi národy, pozdvihněte korouhev; rozhlaste to a nezatajujte. Řekněte: Babylon je dobyt, Bél se stydí, Marduk se třese; jeho modlářské zpodobeniny jsou zahanbeny, jeho bůžkové se třesou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Protože ze severu proti němu vytáhl národ, který jeho zemi učiní děsivou krajinou. Nebudou v ní obyvatelé, ⌈lidé i zvířata⌉ prchnou, utečou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'V oněch dnech a v onom čase, je Hospodinův výrok, přijdou synové izraelští spolu se syny judskými; půjdou a přitom budou plakat a budou hledat Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, '⌈Cestou se budou vyptávat⌉ na Sijón, tam budou obráceny jejich tváře. Přijdou a připojí se k Hospodinu věčnou smlouvou, jež nebude zapomenuta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Můj lid byl ztracené stádo. Jejich pastýři je svedli, odvraceli je na horách. Chodili z hory na návrší a na místo svého odpočinku zapomněli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Všichni, kdo je našli, je požírali a jejich protivníci říkali: Neproviníme se, protože hřešili proti Hospodinu, pravé pastvině a naději svých otců, Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Prchněte z Babylona, vyjděte z chaldejské země a buďte jako beran před stádem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Protože hle, podnítím a přivedu proti Babylonu shromáždění velkých národů ze severní země. Sešikují se proti němu, bude odtamtud dobyt. Jejich šípy jsou jako úspěšní hrdinové, nenavrátí se s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Chaldejsko se stane kořistí; všichni ⌈jeho kořistníci⌉ se nasytí, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Ačkoliv se radujete, ačkoliv jásáte, pustošitelé mého dědictví, ačkoliv poskakujete jako ⌈jalovice při mlácení⌉ a řehtáte jako koně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'vaše matka se velice stydí, vaše rodička se hanbí. Hle, je poslední z národů. Pustina, bezvodá a pustá země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Kvůli Hospodinovu hněvu ne bude obydlen, bude zcela opuštěný, každý, kdo bude Babylonem procházet, se zhrozí a podiví se všem jeho ranám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Sešikujte se proti Babylonu ze všech stran, všichni, kdo napínáte luk, střílejte na něj a ⌈nešetřte šípem,⌉ protože zhřešil proti Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Křičte proti němu ze všech stran! Vzdal se, jeho pilíře padly, jeho hradby jsou zbořeny, protože to je Hospodinova pomsta. Pomstěte se na něm! To, co dělal on, udělejte jemu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Vyhlaďte z Babylona rozsévače i toho, kdo nosí srp v čas žně! Před krutým mečem se každý vrátí ke svému lidu a každý uteče do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Izrael je zaplašená ovce, kterou zahnali lvi. Nejprve ho požíral asyrský král a nakonec mu ohlodal kosti babylonský král Nebúkadnesar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Proto takto praví Hospodin zástupů, Bůh Izraele: Hle, navštívím babylonského krále a jeho zemi tak, jako jsem navštívil asyrského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Přivedu Izrael zpět na jeho pastvinu a bude se pást na Karmelu i v Bášanu, jeho duše se nasytí v Efrajimském pohoří a v Gileádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'V oněch dnech a v onom čase, je Hospodinův výrok, bude vyhledávána vina Izraele, ale žádná nebude, a hříchy Judy, ale nebudou nalezeny, protože těm, které zanechám, odpustím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Proti meratajimské zemi: Vytáhni proti ní a proti obyvatelům Pekódu! Pobij je a i ⌈posledního z nich zasvěť zkáze,⌉ je Hospodinův výrok; učiň všechno, co jsem ti přikázal!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'V zemi je ⌈válečná vřava⌉ a velká zkáza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Jak je rozbito a rozdrceno kladivo celé země! Jak se Babylon stal děsivou věcí mezi národy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Nastražil jsem na tebe past a byl jsi polapen, Babylone, ani jsi to nevěděl. Byl jsi dopaden a chycen, protože ses pustil do boje s Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Hospodin otevřel svoji zbrojnici a vybral zbraně svého rozhořčení, neboť Panovník, Hospodin zástupů, má v chaldejské zemi práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Přitáhněte proti němu ze všech končin, otevřete jeho sýpky, navršte ho jako hromady obilí a zasvěťte jej zkáze! Ať z něj nezůstane ani ostatek!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Pobijte všechny jeho býčky, ať sestoupí na porážku! Běda jim, neboť přišel jejich den, čas jejich navštívení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Slyš! Utečenci a uprchlíci z babylonské země přicházejí oznámit na Sijón pomstu Hospodina, našeho Boha, pomstu za jeho chrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Svolejte proti Babylonu lukostřelce, všechny, kdo napínají luk. Utábořte se kolem něho, ať nemá úniku! Odplaťte mu podle jeho skutků, podle všeho, co učinil, učiňte jemu, neboť se choval drze vůči Hospodinu, ⌈Svatému Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Proto jeho mládenci padnou na jeho náměstích a všichni jeho bojovníci v onen den zahynou, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, '⌈Hle, jsem proti⌉ tobě, domýšlivče, je výrok Panovníka, Hospodina zástupů, neboť přišel tvůj den, čas, kdy tě navštívím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Domýšlivec klopýtne a padne a ne bude, kdo by ho pozdvihl. V jeho městech zapálím oheň a ten stráví celé jeho okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Toto praví Hospodin zástupů: Synové izraelští jsou utlačováni spolu se syny judskými. Všichni, kdo je odvedli do zajetí, je pevně drželi a nechtěli je propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Jejich Vykupitel je silný, jeho jméno je Hospodin zástupů. Jistě povede jejich spor, aby dal odpočinutí zemi, ale znepokojil obyvatele Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Meč proti Chaldejcům, je Hospodinův výrok, proti obyvatelům Babylona, proti jeho knížatům i jeho mudrcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Meč proti žvanilům a ⌈dokáží, že jsou blázni.⌉ Meč proti jeho hrdinům a vyděsí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Meč proti jejich koňům a jejich vozům, proti všemu míšenému lidu, který je uprostřed něho; budou slabí jako ženy. Meč proti jeho pokladům a budou vypleněny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Sucho na jeho vody, ať vyschnou, protože je to země model, protože šílí u svých hrůzných stvůr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Proto tam budou sídlit divoká zvířata s šakaly, budou v ní pobývat pštrosi. Nebude již nikdy obydlena, nebude osídlena z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Jako když Bůh vyvrátil Sodomu, Gomoru a jejich sousední města, je Hospodinův výrok, tak se tam nikdo neusadí, ⌈syn člověka⌉ v ní nebude pobývat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Hle, ze severu přichází lid, velký národ, mnozí králové se dávají do pohybu z nejvzdálenějších částí země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Chopí se luku a srpáče, jsou krutí a nebudou mít slitování. Jejich křik bude burácet jako moře. Připraveni jako muž do boje pojedou na koních proti tobě, babylonská dcero.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Babylonský král ⌈ o nich uslyšel zprávu⌉ a jeho ruce ochably, zmocnila se ho tíseň, porodní bolesti jako rodičky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Hle, vystupuje jako lev z jordánské houštiny na stále zelenou pastvinu, ale v okamžiku ho z ní zaženu a určím nad ní toho, kdo je vyvolený. Neboť kdo je jako já? Kdo mě předvolá k soudu? Kdo je ten pastýř, který přede mnou obstojí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Proto slyšte Hospodinovo rozhodnutí, které učinil o Babylonu, jeho plán, který vymýšlí proti chaldejské zemi: Jistě je budou vláčet, i nejmenší ze stáda. Jistě kvůli nim zpustoší pastvinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Voláním: Babylon je dobyt! Třese se země. Jeho úpěnlivý křik je slyšet mezi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Toto praví Hospodin: Hle, vzbudím proti Babylonu a proti obyvatelům Léb–Kamaje ničivý vítr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Pošlu do Babylona cizince, ti ho provějí a vyprázdní jeho zemi, protože v den zla budou proti němu ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, '⌈Střelec ať napne svůj luk proti tomu, kdo napíná luk, a proti tomu, kdo se vypíná⌉ ve svém pancíři. Nemějte soucit s jeho mládenci, zasvěťte zkáze celou jeho armádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'V chaldejské zemi budou padat pobití, probodení na ulicích Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Neboť Izrael ani Juda ⌈ne byl opuštěn jako vdova⌉ svým Bohem, Hospodinem zástupů, ačkoliv jejich země je plná viny proti Svatému Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Utečte z Babylona, zachraňte si každý svou duši, ať nezahynete ⌈pro jeho viny,⌉ neboť toto je čas pomsty pro Hospodina; odplácí mu za to, co vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Babylon byl zlatým kalichem v Hospodinově ruce, opíjel celou zemi. Národy pily z jeho vína, proto národy zešílely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Babylon náhle padl, je rozdrcen. Naříkejte nad ním! Vezměte na jeho bolest balzám! Snad se uzdraví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Léčili jsme Babylon, ale nebyl uzdraven. Opusťte jej a pojďme každý do své země, protože jeho soud dosáhl k nebesům, povznesl se až k oblakům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Hospodin vyvedl na světlo naši ⌈spravedlivou při.⌉ Pojďme a vypravujme na Sijónu o díle Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Naostřete šípy, ⌈uchopte štíty!⌉ Hospodin vzbudil ducha médských králů, protože jeho plán je namířen proti Babylonu, aby ho zničil, neboť toto je Hospodinova pomsta, pomsta za jeho chrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Pozdvihněte korouhev proti babylonským hradbám, zesilte stráž, ustanovte hlídky, připravte zálohy, protože Hospodin má v úmyslu a také provede to, co vyslovil proti obyvatelům Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Ty, který bydlíš na velkých vodách, a máš mnoho pokladů, přišel tvůj konec, naplnila se míra tvého nekalého zisku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Hospodin zástupů přísahal při ⌈sobě samém:⌉ Naplním tě lidmi jako kobylkami a vydají nad tebou vítězný pokřik.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Svou silou učinil zemi, svou moudrostí založil svět a svou rozumností roztáhl nebesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Když vydá hlas, bouří se voda v nebesích, dává vystupovat mlze z končin země, působí blesky s deštěm, ze svých skladů vyvádí vítr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Všichni lidé jsou hloupí a bez poznání, všichni zlatníci jsou zahanbeni svými modlami, protože jejich modly jsou falešné, není v nich duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Jsou nicotností, směšným dílem, v čase svého navštívení zahynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Podíl Jákobův jim není podobný, neboť on je Tvůrcem všeho a Izrael je jeho dědičným kmenem; jeho jméno je Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Jsi mým kladivem, válečnou zbraní, ⌈skrze tebe⌉ roztříštím národy, skrze tebe zničím království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Skrze tebe roztříštím koně i jeho jezdce, skrze tebe roztříštím vůz i jeho vozataje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Skrze tebe roztříštím muže i ženu, skrze tebe roztříštím starce i chlapce, skrze tebe roztříštím mládence i pannu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Skrze tebe roztříštím pastýře i jeho stádo, skrze tebe roztříštím oráče i jeho spřežení, skrze tebe roztříštím místodržitele i správce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Před vašima očima odplatím Babylonu a všem obyvatelům Chaldejska za všechno jejich zlo, které páchali na Sijónu, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, '⌈Hle, jsem proti tobě,⌉ horo ničiteli, je Hospodinův výrok, ničiteli celé země. Vztáhnu proti tobě svou ruku a svalím tě ze skály a učiním tě horou spálenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Nevezmou z tebe ⌈úhelný kámen⌉ ani ⌈kámen základní,⌉ protože budeš navěky zcela opuštěným místem, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Pozdvihněte korouhev v zemi, trubte na beraní roh mezi národy, nachystejte národy do boje proti němu! Svolejte proti němu království Ararat, Miní a Aškenaz! Ustanovte nad ním verbíře, přiveďte koně jako sršaté kobylky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Nachystejte do boje proti němu národy, médské krále, jejich místodržitele, všechny správce a celou zemi pod jejich vládou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Země se třese a svíjí bolestí, protože se plní Hospodinův plán proti Babylonu, aby učinil babylonskou zemi děsivou krajinou bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Babylonští hrdinové přestali bojovat, sedí v pevnostech; jejich síla vyschla, stali se slabými jako ženy. Jeho příbytky byly zapáleny, jeho závory zlomeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, '⌈Běžec běží, aby potkal dalšího běžce,⌉ posel, aby potkal dalšího posla, aby babylonskému králi oznámil, že celé jeho město bylo dobyto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Brody jsou obsazeny, bašty spáleny ohněm a bojovníci se děsí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Neboť toto praví Hospodin zástupů, Bůh Izraele: Dcera babylonská je jako humno v čase, kdy je udusáváno. Už jen málo a přijde čas její žně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Babylonský král Nebúkadnesar mě požíral a přivedl do zmatku, odložil mě jako prázdnou nádobu. Spolkl mě jako mořský drak, své břicho naplnil mými lahůdkami a vyvrhl mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, '⌈Násilí spáchané na mně a na mém těle⌉ ať dopadne na Babylon, ať řekne obyvatelka Sijónu. Má krev na obyvatele Chaldejska, ať řekne Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Proto takto praví Hospodin: Hle, povedu tvůj spor a vykonám tvou pomstu. Vysuším jeho moře a nechám vyschnout jeho pramen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Babylon se stane hromadou kamení, doupětem šakalů, předmětem hrůzy a úžasu; bude bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Společně budou řvát jako mladí lvi, kňučet jako lví mláďata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Až se rozpálí, připravím jim hostinu, opiji je do bujarosti; pak usnou věčným spánkem a neprobudí se, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Povedu je na porážku jako jehňata, jako berany s kozly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Jak byl Šéšak polapen a chvála celé země byla dobyta! Jak se Babylon stal děsivou věcí mezi národy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Na Babylon vystoupilo moře, byl přikryt množstvím jeho vln.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Jeho města se stala děsivou krajinou, bezvodou a pustou zemí; nikdo v nich nebude bydlet, ⌈syn člověka⌉ jimi nebude procházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Navštívím Béla v Babyloně a vyberu z jeho úst to, co pozřel. Nebudou již k němu proudit národy. Také hradby Babylona padnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Vyjděte z něho, můj lide! Zachraňte každý svou duši před Hospodinovým planoucím hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Vaše srdce ať neochabne, ne bojte se zprávy, která je slyšet v zemi! V jednom roce přijde jedna zpráva a v dalším roce další zpráva; v zemi bude násilí, vládce proti vládci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Proto hle, přicházejí dny, kdy modly Babylona navštívím s trestem. Celá jeho země se bude stydět a všichni jeho probodení padnou ⌈v jeho středu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Nebesa i země a všechno, co je v nich, budou nad Babylonem radostně volat, protože na něj od severu přijdou ničitelé, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Také Babylon musí padnout za pobité Izraele, jako kvůli Babylonu padli pobití celé země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Utečenci před mečem, jděte, nestůjte! Připomínejte si z daleka Hospodina, na vaši mysl ať přijde Jeruzalém!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Stydíme se, protože jsme slyšeli o potupě. Naše tváře přikryla ostuda, protože do svatyní Hospodinova domu vešli cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Proto hle, přicházejí dny, je Hospodinův výrok, kdy navštívím s trestem jeho modly a po celé jeho zemi budou sténat pobití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'I kdyby Babylon vystoupil až k nebesům a kdyby učinil svou mocnou výšinu nedostupnou, přijdou na něho ode mě ničitelé, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Slyš! Úpěnlivý křik z Babylona a velká zkáza z chaldejské země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Neboť Hospodin ničí Babylon a ⌈tiší jeho halas,⌉ ačkoliv jeho vlny burácejí jako množství vod a zaznívá hukot jejich zvuku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Neboť na něho, na Babylon, přišel ničitel. Jeho hrdinové jsou polapeni, jejich luky jsou zlomeny, protože Hospodin je Bohem odplaty, jistě odplatí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Opiji jeho knížata i jeho mudrce, jeho místodržitele, jeho správce a jeho hrdiny; pak usnou věčným spánkem a neprobudí se, je výrok krále, jehož jméno je Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Toto praví Hospodin zástupů: Široké hradby Babylona budou zcela zbořeny, jeho vysoké brány budou spáleny ohněm. Národy se namáhají zbytečně, ⌈lidé se unavují jen pro oheň.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Slovo, které přikázal prorok Jeremjáš Serajášovi, synu Nerijášovu, vnuku Machsejášovu, když šel s judským králem Sidkijášem do Babylona, ve čtvrtém roce jeho kralování. Serajáš byl velitelem ubytování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Jeremjáš zapsal všechno zlo, které mělo přijít na Babylon, do jedné knihy, totiž všechna tato slova napsaná proti Babylonu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'A Jeremjáš řekl Serajášovi: Až přijdeš do Babylona, hleď, abys přečetl všechna tato slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Řekni: Hospodine, ty jsi promluvil proti tomuto místu, že ho vyhladíš, takže v něm ne budou obyvatelé ani člověk ani zvířata, ale bude navěky zcela opuštěné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Až dočteš tuto knihu, přivaž k ní kámen, hoď ji doprostřed Eufratu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'a řekni: Takto klesne Babylon a nepovstane kvůli zlu, které na něj přivedu. Unaví se. Až potud Jeremjášova slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Sidkijášovi bylo dvacet jedna let, když se stal králem, a kraloval v Jeruzalémě jedenáct let. Jeho matka se jmenovala Chamútal, byla to dcera Jeremjáše z Libny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Páchal to, co ⌈je zlé v Hospodinových očích,⌉ stejně jako to dělal Jójakím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Neboť kvůli Hospodinovu hněvu se v Jeruzalémě a v Judsku stalo to, že je od sebe odvrhl. Sidkijáš se proti babylonskému králi vzbouřil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'V devátém roce jeho kralování, v desátém měsíci, desátého dne toho měsíce se stalo, že proti Jeruzalému přitáhl babylonský král Nebúkadnesar a celé jeho vojsko, utábořili se kolem něj a vystavěli proti němu ze všech stran obléhací val.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Město zůstalo v obležení až do jedenáctého roku vlády krále Sidkijáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Ve čtvrtém měsíci, devátého dne toho měsíce, když se ve městě rozmohl hlad a lid země neměl chléb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'byly hradby města prolomeny. Všichni bojovníci utekli. V noci vyšli z města bránou mezi dvěma hradbami u královské zahrady, přestože Chaldejci byli ze všech stran kolem města. Potom šli směrem k Arabě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Chaldejské vojsko pronásledovalo krále a dostihlo Sidkijáše na jerišských pustinách; celé jeho vojsko se od něj rozprchlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Krále chytili a přivedli ho k babylonskému králi do Ribly v zemi Chamátu. Ten nad ním vyslovil rozsudek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Babylonský král pobil Sidkijášovy syny před jeho zraky a také pobil v Rible všechna judská knížata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Oslepil Sidkijášovy oči, svázal ho bronzovými okovy a pak ho babylonský král přivedl do Babylona. Dal ho do vězení až do dne jeho smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'V pátém měsíci, desátého dne toho měsíce, což byl devatenáctý rok vlády ⌈babylonského krále Nebúkadnesara,⌉ přitáhl velitel tělesné stráže Nebúzaradán, který ⌈stával před babylonským králem,⌉ do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Spálil Hospodinův dům i královský palác, všechny jeruzalémské domy; každý velký dům spálil ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Celé chaldejské vojsko, které bylo s velitelem tělesné stráže, strhlo celé hradby kolem Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Některé z chudých lidí, zbytek lidu, který ve městě zůstal, i přeběhlíky, kteří přeběhli k babylonskému králi, a zbytek řemeslníků velitel tělesné stráže Nebúzaradán odvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Ale některé z chudých země ponechal velitel tělesné stráže Nebúzaradán jako vinaře a rolníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Bronzové sloupy, které patřily k Hospodinovu domu, podstavce a bronzové moře, které bylo v Hospodinově domě, Chaldejci roztřískali a všechen bronz z toho odnesli do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Vzali hrnce, lopaty, nůžky na knoty, misky, kadidlové pánvičky a všechny bronzové nádoby, s nimiž konali bohoslužbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Velitel tělesné stráže vzal i číše, pánvičky na uhlíky, misky, hrnce, svícny, kadidlové pánvičky a obětní misky; ⌈co bylo ze zlata, jako zlato, co bylo ze stříbra, jako stříbro.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Dva sloupy, jedno moře, dvanáct bronzových býků, kteří byli pod ním, a podstavce, které udělal král Šalomoun pro Hospodinův dům. Bronz ze všech těchto předmětů se nedal ani zvážit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Co se sloupů týká, osmnáct loket byla výška jednoho sloupu, obepnula ho šňůra dvanáct loket dlouhá; jeho síla byla ⌈čtyři prsty a byl dutý.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Byla na něm bronzová hlavice; výška jedné hlavice byla pět loket. Kolem hlavice bylo mřížování a granátová jablka; to všechno bylo z bronzu. Takový byl i druhý sloup s granátovými jablky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Granátových jablek bylo po stranách devadesát šest; všech granátových jablek kolem mřížování bylo sto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Velitel tělesné stráže vzal vrchního kněze Serajáše, druhého kněze Sefanjáše a tři strážce prahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Z města vzal jednoho dvorního úředníka, který byl dohlížitelem nad bojovníky, a sedm mužů z těch, kteří bývali v přítomnosti krále, kteří se nacházeli ve městě, i písaře velitele armády, jenž povolával lid země do vojenské služby a šedesát mužů z lidu země, kteří se nacházeli uprostřed města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Velitel tělesné stráže Nebúzaradán je pak vzal a předvedl je k babylonskému králi do Ribly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Babylonský král je pobil a usmrtil je v Rible v zemi Chamátu. Tak byl Juda odveden ze své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Toto je lid, který Nebúkadnesar odvedl: V sedmém roce tři tisíce dvacet tři Judejců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'v osmnáctém roce vlády Nebúkadnesara osm set třicet dva duší z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Ve dvacátém třetím roce vlády Nebúkadnesara odvedl velitel tělesné stráže Nebúzaradán sedm set čtyřicet pět Judejců; všech duší bylo čtyři tisíce šest set.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'V třicátém sedmém roce vyhnanství judského krále Jójakína, ve dvanáctém měsíci, dvacátého pátého dne toho měsíce se stalo, že babylonský král Evíl–merodak v prvním roce svého kralování omilostnil judského krále Jójakína a vyvedl ho z vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Mluvil s ním laskavě a jeho trůn ustanovil nad trůny králů, kteří s ním byli v Babyloně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Jójákín svlékl své vězeňské šaty a jídal po všechny dny svého života stále v jeho přítomnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Jeho zaopatření, stálé zaopatření, mu bylo poskytováno babylonským králem, ⌈každodenní podíl⌉ po všechny dny jeho života až do dne jeho smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Jak sedí osaměle město, které mělo mnoho lidu! Je jako vdova to, jež bylo velké mezi národy. ⌈Kněžna mezi provinciemi⌉ je vydána nuceným pracím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'V noci hořce pláče a slzy jí tečou po tvářích. Mezi všemi svými milenci nemá utěšitele. Všichni její přátelé ji nevěrně opustili, stali se jejími nepřáteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda byl vystěhován v soužení a v těžké otročině. Bydlí mezi národy, nenalezl místo odpočinku. Všichni, kdo jej pronásledují, ho dostihnou uprostřed velké tísně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Cesty na Sijón truchlí, protože na svátky nikdo nepřichází. Všechny jeho brány jsou opuštěné, jeho kněží vzdychají, jeho panny jsou sklíčené a jemu je hořko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Jeho protivníci ⌈získali navrch,⌉ jeho nepřátelům se daří, protože Hospodin ho sklíčil pro množství jeho přestoupení. Jeho děti odešly před zraky protivníka do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Od ⌈dcery sijónské⌉ odešla všechna její ozdoba, její knížata jsou jako jeleni, kteří nenašli pastvu, utekli vysílení před pronásledovatelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jeruzalém vzpomíná ve dnech svého soužení a svého bezdomovství na všechny své drahocennosti, které měl od dávných časů. Když jeho lid padl do ruky protivníka a ⌈neměl pomocníka,⌉ protivníci se na něj dívali a vysmívali se jeho zániku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jeruzalémská dcera velmi zhřešila; proto se stala nečistou. Všichni, kdo ji ctili, jí opovrhují, protože viděli její nahotu; ona sama vzdychá a obrací se zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Na jejích sukních je její nečistota, nepamatovala na svoji budoucnost. Padla prapodivným způsobem, nemá utěšitele. Hospodine, pohleď na mé soužení, protože nepřítel se vyvyšuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Protivník vztáhl svou ruku na všechny její vzácnosti, ano, viděla pohanské národy, jak přicházejí do její svatyně, ty, o nichž jsi přikázal, aby do tvého shromáždění nevcházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Všechen její lid vzdychá, hledají pokrm. Dali svoje vzácnosti za jídlo, aby zachovali život. Podívej se, Hospodine, a pohleď, že jsem opovržená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Je to ničím pro vás všechny, kteří procházíte kolem? Pohleďte a podívejte se, jestli je bolest jako moje bolest, kterou mě ranil, kterou mě Hospodin sklíčil v den svého planoucího hněvu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Z výšiny poslal oheň do mých kostí a opanoval je. Rozprostřel síť pro mé nohy, obrátil mě zpět. Učinil mě opuštěnou, celý den jsem nemocná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Má přestoupení jsou svázána do jha, jeho rukou jsou propletena. Vstoupila na mou šíji, přivedl k pádu moji sílu. Panovník mě vydal do rukou těch, proti nimž nemohu obstát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Panovník zavrhl všechny mé siláky v mém středu, svolal proti mně shromáždění, aby rozdrtil mé mládence. Jako v lisu šlapal Panovník pannu, dceru judskou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Nad tím pláču, z mých očí, z mých očí plyne voda, protože je ode mě daleko utěšitel, který ⌈by obnovil mou duši.⌉ Moji synové se stali opuštěnými, protože zvítězil nepřítel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Dcera sijónská rozhazuje rukama, nemá utěšitele. Hospodin přikazuje o Jákobovi, že národy okolo něj se stanou jeho protivníkem. Jeruzalémská dcera se ⌈mezi nimi⌉ stala nečistou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Hospodin je spravedlivý, protože jsem se vzpírala jeho příkazu. Poslyšte, prosím, všechny národy a pohleďte na mou bolest. Moje panny a moji mládenci odešli do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Volala jsem své milence, ale oni mě podvedli. Moji kněží a starci vydechli ve městě naposled, když si hledali jídlo, aby si zachovali život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Hospodine, pohleď, neboť je mi úzko, mé nitro vře; srdce se ve mně převrací, protože jsem byla velmi vzpurná. Venku činí bezdětným meč, v domě je smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Slyšeli, že vzdychám, nemám utěšitele, všichni moji nepřátelé slyšeli o mém trápení a rozjásali se, žes to učinil. Přiveď den, který jsi vyhlásil, aby byli jako já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Všechno jejich zlo ať přijde před tebe a jednej s nimi, jako jsi jednal se mnou za všechna má přestoupení. Vždyť mnoho vzdychám a mé srdce je zemdlené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Jak Panovník přikryl dceru sijónskou oblakem svého hněvu! Svrhl z nebes na zem okrasu Izraele, ⌈v den svého hněvu⌉ nepamatoval na podnož svých nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Panovník pohltil bez soucitu všechny Jákobovy příbytky, ve svém hněvu zbořil pevnosti dcery judské, srazil k zemi, znesvětil království i jeho knížata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Usekl v planoucím hněvu všechny rohy Izraele, stáhl zpět svou pravici před blížícím se nepřítelem, vzplál v Jákobovi jako plápolající oheň, který strávil vše kolem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Napjal svůj luk jako nepřítel, pozvedl svou ⌈pravici; jako protivník zabil⌉ všechno vzácné oku; ve stanu dcery sijónské vylil svůj hněv jako oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Panovník se stal nepřítelem, pohltil Izrael, pohltil všechny jeho paláce, zničil jeho pevnosti, rozmnožil dceři judské smutek a žal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Jednal se svým stánkem násilně jako se ⌈zahradní budkou,⌉ zničil své místo setkávání. Hospodin způsobil, že na Sijónu byly zapomenuty svátky i soboty, ve svém prudkém hněvu odvrhl krále i kněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Panovník odvrhl svůj oltář, opustil svou svatyni, do ruky nepřítele vydal hradby jeho paláců. ⌈Pozvedli hlas⌉ v Hospodinově domě jako v den svátku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Hospodin se rozhodl zničit hradby dcery sijónské, ⌈natáhl měřicí šňůru⌉ a neodvrátil svou ruku od ničení. Způsobil, že truchlily val i hradby, společně se zhroutily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Její brány se ponořily do země, ⌈zničil a rozlámal⌉ její závory. Její král i její knížata jsou mezi pohanskými národy, ne ní už zákon, ani její proroci nepřijímají vidění od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Starší dcery sijónské sedí na zemi, mlčí. Házely si prach na hlavu, přepásaly se pytlovinou. Jeruzalémské panny svěsily hlavu k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Zrak mi slábne pro slzy, mé nitro vře, moje žluč se vylila na zem pro ⌈zkázu dcery mého lidu,⌉ když děti a kojenci omdlévají na náměstích města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Svým matkám říkají: Kde je ⌈obilí a víno?,⌉ zatímco omdlévají na náměstích města jako probodení, zatímco vypouštějí svou duši do klína svých matek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, '⌈Jak mám o tobě svědčit,⌉ k čemu tě mám připodobnit, jeruzalémská dcero? S čím tě mám srovnat, abych tě potěšil, panno, dcero sijónská? Vždyť tvá zkáza je veliká jako moře. Kdo tě uzdraví?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Tvoji proroci pro tebe viděli klam a nesmysly; neodhalili tvoji vinu, aby změnili tvůj úděl. Viděli pro tebe klamné a svůdné výnosy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Všichni, kdo procházejí kolem, nad tebou tleskají rukama; pošklebují se a potřásají hlavou nad jeruzalémskou dcerou: To je to město, o kterém říkali: Dokonalost krásy, radost pro celou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Všichni tvoji nepřátelé si na tebe otvírají ústa, pošklebují se a skřípou zuby. Říkají: Pohltili jsme ji. Jistě toto je den, na který jsme čekali. ⌈Dočkali jsme se ho a uviděli⌉ jsme ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Hospodin učinil to, co měl v úmyslu, naplnil své slovo, co přikázal od dávných časů, zbořil a neměl soucit. Dal nepříteli radovat se nad tebou, vyvýšil roh tvého protivníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, '⌈Jejich srdce křičelo⌉ k Panovníku. Hradbo dcery sijónské, vylévej slzy jako potok ve dne i v noci. Nedopřej si odpočinku, ať nemá pokoje zřítelnice tvého oka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Povstaň, křič v noci, na počátku nočních hlídek! Vylévej své srdce jako vodu před tváří Panovníka! Pozdvihni k němu své ruce za život svých dětí, které omdlévají hladem na každém nároží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Podívej se, Hospodine, a pohleď, s kým jsi takto jednal?! Cožpak mají ženy jíst svůj plod, ⌈zdravě narozené⌉ děti?! Cožpak má být kněz a prorok zabíjen v Panovníkově svatyni?!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Na zemi po ulicích leží chlapec i stařec, moje panny a moji mládenci padli mečem. Zabil jsi je v den svého hněvu, pobil a neměl soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Svolal jsi jako na den svátku ⌈ty, kterých se děsím⌉ ze všech stran. V den Hospodinova hněvu nikdo neunikl ani ne přežil. Ty, které jsem porodila jako zdravé a vychovala, můj nepřítel zničil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Já jsem muž, který zažil soužení skrze hůl jeho hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Hnal mě a přivedl do temnoty, ne do světla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Jen proti mně obrací znovu a znovu svou ruku, ⌈celý den.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Nechal chřadnout mé tělo a mou kůži, rozlámal mé kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Oblehl mě a obklopil jedem a těžkostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Způsobil, že bydlím v temnotách jako dávno zemřelí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Zazdil mě, abych ne mohl vyjít, ⌈obtížil mě bronzovým řetězem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'I když volám a křičím o pomoc, zadržuje mou modlitbou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Moje cesty zazdil tesanými kameny, zkazil moje stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Je pro mě jako číhající medvěd, jako lev ve skrýši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Odvlekl ⌈mě z cesty⌉ a roztrhal mě na kusy, učinil mě opuštěným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Napjal svůj luk a učinil mě terčem pro šíp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Střelil do mého nitra šípy ze svého toulce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Stal jsem se posměchem všemu ⌈svému lidu,⌉ po celý den jejich posměšnou písničkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Nasytil mě hořkostí, napojil mě pelyňkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Moje zuby rozdrtil štěrkem, přimáčkl mě do popela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Má duše ⌈byla zbavena pokoje,⌉ zapomněl jsem, co je dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Takže jsem řekl: ⌈Je pryč⌉ moje síla i ⌈mé očekávání na pomoc od Hospodina.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Pamatuj na mé soužení a mé bezdomovství, na pelyněk a jed.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Má duše na to stále pamatuje a klesá ve mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'To si ⌈připomínám v mysli,⌉ proto mám naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, '⌈ Je to Hospodinovo milosrdenství, že jsme nezahynuli,⌉ neboť nepominulo jeho slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Je nové každé ráno, tvá věrnost je velká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Mým podílem je Hospodin, říká má duše, proto v něm mám naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, '⌈Hospodin je dobrý⌉ k tomu, kdo na něho očekává, k člověku, jenž ho hledá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Je dobré, aby člověk měl naději a mlčky čekal na Hospodinovu záchranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Pro muže je dobré, když nosí jho ve svém mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Ať sedí o samotě a mlčí, když to na něj vloží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Ať položí svá ústa do prachu, snad je ještě naděje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Ať nastaví tvář tomu, kdo ho bije, ať se nasytí potupou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Neboť Panovník neodvrhne navěky;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'neboť jestliže sklíčil, slituje se ⌈podle svého hojného milosrdenství.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Neboť ne ⌈z vlastního rozmaru⌉ pokořuje či skličuje syny člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Srazit pod nohy všechny vězně země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'převracet právo muže před tváří Nejvyššího,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'podvádět člověka při jeho sporu, ⌈ to Panovník ne chce vidět!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, '⌈ Je někdo, kdo⌉ řekl a stalo se, když to Panovník nepřikázal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Cožpak zlé věci i dobro nevychází z úst Nejvyššího?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Co si má co stěžovat živý člověk na trest za svoje hříchy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Prozkoumejme svoje cesty, vyzpytujme je, a navraťme se k Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Pozvedněme svoje srdce i ruce k Bohu v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Bouřili jsme se a byli vzpurní a ty jsi neodpustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Zahalil ses hněvem a stíhal jsi nás, zabíjel jsi a neměl jsi soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Zahalil ses oblakem, aby nepronikla žádná modlitba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Učinil jsi nás ⌈smetím a odpadem⌉ mezi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Všichni naši nepřátelé si na nás otvírali ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Přišel na nás strach a propast, zpustošení a zkáza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Z mých očí plynou proudy vody nad zkázou dcery mého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Moje oči ⌈vylévají slzy,⌉ ne dají se zastavit, bez odpočinku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'dokud Hospodin ne pohledí a ne podívá se z nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, '⌈Moje oči⌉ působí mé duši bolest pro ⌈všechny dcery mého města.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Moji nepřátelé mě bezdůvodně lovili jako ptáka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Snažili se ukončit můj život v cisterně a hodili na mě kamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Na mou hlavu natekla voda. Řekl jsem: Jsem ztracen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Ze dna cisterny jsem vzýval tvé jméno, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Uslyšel jsi můj hlas: Nezavírej své ucho před mojí prosbou o úlevu, před mým voláním o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Přiblížil ses v den, kdy jsem tě volal. Řekl jsi: Neboj se!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Vedl jsi, Panovníku, spory mé duše, vykoupil jsi můj život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Viděl jsi, Hospodine, ⌈mně způsobenou křivdu.⌉ ⌈Zjednej mi právo!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Viděl jsi všechnu jejich pomstu, všechny jejich plány proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Slyšel jsi jejich hanění, Hospodine, všechny jejich plány proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Slova mých protivníků a jejich mumlání proti mně po celý den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Pohleď, ⌈ ať sedí nebo stojí,⌉ jsem jejich posměšnou písničkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Odplať jim, Hospodine, za to, co vykonali, za skutky jejich rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Dej jim zatvrzelé srdce, ať na ně dopadne tvoje kletba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Stíhej je s hněvem a vyhlaď je zpod nebes, Hospodine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Jak zčernalo zlato, jak se změnilo ryzí zlato! Kameny svatyně leží rozmetány na každém nároží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Vzácní synové Sijónu, vážení s ryzím zlatem, jak to, že jsou nyní ceněni jen jako hliněný džbán, dílo hrnčířových rukou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'I šakalové obnažují prs a kojí svá mláďata, ale dcera mého lidu se stala krutou jako pštros v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Jazyk kojence přilnul žízní k patru; děti se dožadují chleba, nikdo jim ho ne láme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ti, kdo jídali lahůdky, hynou na ulicích; ti, kdo byli vychováni v purpuru, objímají smetiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Vina dcery mého lidu je větší nežli hřích Sodomy, která byla v okamžiku vyvrácena, aniž by na ni byly položeny ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Její nazíři byli čistší nežli sníh, bělejší nežli mléko; jejich tělo bylo růžovější nežli drahokamy, jejich vzhled se podobal safíru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Teď je jejich vzezření temnější nežli saze, nedají se na ulicích poznat; kůže jim svraštila na kostech, uschla jako dřevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Lépe na tom byli probodení mečem nežli pobití hladem, kteří hynou nedostatkem polních plodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Ruce soucitných žen vařily svoje děti; staly se jejich jídlem při zkáze dcery mého lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Hospodin dovršil svoji zlobu, vylil svůj planoucí hněv, zapálil na Sijónu oheň, který strávil jeho základy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Králové země ani všichni obyvatelé světa by nevěřili, že do jeruzalémských bran vejde protivník či nepřítel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Stalo se to pro hříchy jeho proroků a viny jeho kněží, kteří prolévali v jeho středu krev spravedlivých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Jako slepí se potáceli po ulicích, znečištění krví, takže se lidé nesměli dotknout jejich oděvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Ustupte! Nečistý!, volali na ně lidé, ustupte! Ustupte! Nedotýkejte se! Proto odešli a potáceli se. Mezi pohanskými národy lidé říkali: Nebudou už s námi pobývat jako cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, '⌈Hospodinova tvář je rozdělila,⌉ nebude již ⌈ na ně hledět;⌉ nebrali ohled na kněze, neslitovali se nad staršími.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Ještě nám zrak slábne od hledění k naší nicotné pomoci; ve svém vyhlížení jsme vyhlíželi k národu, který ne může zachránit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Sledovali naše kroky, abychom ne mohli chodit po svých náměstích; náš konec se přiblížil, naplnily se naše dny, ano, přišel náš konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Naši pronásledovatelé byli rychlejší nežli nebeští orlové. Honili nás na horách, v pustině na nás číhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Dech našeho života, Hospodinův pomazaný, byl polapen do jejich jam, ten, o kterém jsme si mysleli: ⌈V jeho stínu⌉ budeme živi mezi pohanskými národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Jásej a raduj se, dcero edómská, která bydlíš v zemi Úsu! I k tobě přijde kalich, opiješ se a obnažíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Skončil trest za tvou vinu, dcero sijónská, již tě neodvede do zajetí. K odpovědnosti za tvou vinu povolá tebe, dcero edómská, a odhalí tvoje hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Pamatuj, Hospodine, na to, co se nám stalo, pohleď a podívej se na naši potupu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Naše dědictví bylo předáno cizincům, naše domy cizozemcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Stali jsme se sirotky bez otce, naše matky jsou vdovami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Vlastní vodu pijeme za stříbro a vlastní dřevo dostáváme za peníze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Jho je na naší šíji, jsme pronásledováni; jsme unaveni a nemáme odpočinek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, '⌈Dali jsme ruku Egyptu a Asýrii,⌉ abychom se nasytili chlebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Naši otcové hřešili a už nejsou; my neseme trest za jejich viny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Vládnou nám otroci a ne ní, kdo by nás vyrval z jejich ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, '⌈S nasazením vlastního života⌉ přinášíme svůj pokrm, kvůli ⌈meči z pustiny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Naše kůže je rozpálená jako pec od palčivého hladu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Znásilnili ženy na Sijónu, panny v judských městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Knížata byla jejich rukou pověšena, starci nebyli ctěni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Mládenci ⌈nosili mlýnek,⌉ chlapci klopýtali pod nákladem dříví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Starci zmizeli z brány, mládenci zanechali své hudby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Ustalo veselí našeho srdce, náš tanec se změnil v smuteční obřad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Koruna spadla z naší hlavy, běda nám, že jsme hřešili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Proto onemocnělo naše srdce, proto ztemněly naše oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Pro horu Sijón, která je zpustošená, takže po ní chodí lišky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Ty, Hospodine, zůstáváš navěky, tvůj trůn z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Proč na nás neustále zapomínáš a opouštíš nás na mnoho dnů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Vrať nás, Hospodine, zpět k sobě a navrátíme se. Obnov naše dny jako za dávnověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Nebo jsi nás zcela zavrhl? Přespříliš ses na nás rozhněval?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'I stalo se ve třicátém roce ve čtvrtém měsíci, pátého dne toho měsíce, když jsem byl mezi vyhnanci u řeky Kebaru, že se otevřela nebesa a spatřil jsem Boží vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Pátého dne v měsíci -- byl to pátý rok vyhnanství krále Jójakína --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'se opravdu stalo Hospodinovo slovo ke knězi Ezechielovi, synu Buzího, v chaldejské zemi u řeky Kebaru. ⌈Spočinula tam na něm Hospodinova ruka.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'A hle, viděl jsem toto: Od severu přichází bouřlivý vichr, velký oblak, okolo něj planoucí oheň a zář a zprostřed ní něco jako třpyt jantaru zprostřed ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'A zprostřed ní jakoby čtyři bytosti a mají vzhled podobný člověku:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Každá má čtyři tváře a čtyři křídla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Jejich nohy jsou rovné a jejich chodidla jsou jako kopyta telete a jiskří jako třpyt leštěného bronzu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Zpod jejich křídel vycházejí lidské ruce na čtyřech jejich stranách. Ty čtyři mají své tváře a svá křídla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Svými křídly se jedna druhé dotýkají. Když se dají do pohybu, neotáčejí žádná při chůzi svými tvářemi na stranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Jejich tváře jsou podobné lidským tvářím, napravo mají všechny čtyři tváře lva, zleva mají všechny čtyři tváře býka, i tváře orla mají všechny čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, '⌈Jejich tváře⌉ a jejich křídla jsou k sobě nahoře rozepjata, každou spojují dvě křídla s druhou a dvě zakrývají jejich těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'A všechny se pohybují na stranu svých tváří, pohybují se, kam bude chtít jít duch; neotáčejí se při své chůzi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Podoba těch bytostí, jejich vzhled je jako žhavé uhlíky, planoucí oheň, jako vzhled pochodní. Chodí mezi těmi bytostmi a oheň má zář a z toho ohně vychází blesk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'A ty bytosti ⌈běhají tam a zpět,⌉ na pohled jako blýskání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Díval jsem se na ty bytosti a hle, vedle těch bytostí před jejich čtyřmi tvářemi je na zemi jedno kolo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Vzhled těch kol a jejich zpracování je jako třpyt chryzolitu, všechna čtyři mají stejnou podobu a jejich vzhled a jejich zpracování vypadá, jako když je kolo uprostřed kola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Když se dají do pohybu, pohybují se na čtyři strany; neotáčejí se, když se dají do pohybu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Mají loukotě a výšku a budí bázeň; všechna čtyři mají okolo loukotě plné očí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'A když ty bytosti jdou, dají se do pohybu i ta kola vedle nich a když se ty bytosti pozvedají od země, pozvednou se i ta kola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Když duch bude chtít ně kam jít, půjdou, kam ⌈duch chce jít,⌉ a ta kola se pozvednou vedle nich, protože duch té bytosti je v kolech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Při jejich chůzi se dají do pohybu také, když se zastaví, zůstanou také stát, a když se pozvedají od země, pozvednou se i ta kola vedle nich, protože duch té bytosti je v kolech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'A nad hlavami každé té bytosti je cosi podobné klenbě jako třpyt hrozivého ledu roztaženého odshora nad jejich hlavami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Pod tou klenbou pak jsou jejich křídla vzpřímená jedno k druhému. Každá má dvě, která je zakrývají, a každá má dvě, která jim zakrývají jejich těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Slyšel jsem zvuk jejich křídel jako zvuk mnohých vod, jako hlas Všemohoucího, když chodily; zvuk bouře jako zvuk vojska; když se zastavily, svěsily svá křídla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'I stal se hlas svrchu nad klenbou, která byla nad jejich hlavou; když se zastavily, svěsily svá křídla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'A shora nad klenbou, která byla nad jejich hlavou, bylo cosi podobné trůnu vzhledem jako safír a nahoře na tom jakoby trůnu kdosi vzhledem podobný člověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'A viděl jsem něco jako třpyt jantaru; vzhledem to mělo vnitřek okolo jako oheň; od jeho jakoby beder nahoru i od jeho jakoby beder dolů jsem uviděl cosi vzhledem jako oheň a mělo to okolo sebe zář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Jako vzhled duhy, která je na oblaku v deštivý den, takový byl vzhled záře okolo něho, ⌈vzhled podobný Hospodinově slávě.⌉ Když jsem to viděl, padl jsem na tvář a slyšel jsem hlas mluvícího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Tu mi řekl: Lidský synu, postav se na nohy, chci s tebou mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Jakmile ke mně promluvil, vstoupil do mě duch, postavil mě na nohy a já jsem poslouchal, co ke mně mluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Řekl mi: Lidský synu, posílám tě k synům Izraele, k těm vzpurným pohanům, kteří se proti mně vzbouřili. Oni a jejich otcové se vzepřeli proti mně právě až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Jsou to synové ⌈tvrdých tváří a krutého srdce.⌉ Já tě k nim posílám. Řekneš jim: ⌈Toto praví Panovník Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'A oni poznají, ať uposlechnou nebo ať nedbají (vždyť jsou dům vzpoury), že uprostřed nich byl prorok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'A ty, lidský synu, neboj se jich a neboj se jejich slov, že jsou zarputilci, kteří jsou proti tobě jako trny, jako bys bydlel se štíry. Jejich slov se neboj a před nimi se netřes, že jsou dům vzpoury.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Promluvíš k nim má slova, ať uposlechnou nebo ať nedbají (protože jsou vzpurní).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'A ty, lidský synu, slyš to, co k tobě mluvím; nebuď vzpurný jako ten dům vzpoury, otevři svá ústa a sněz to, co ti dávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Tu jsem viděl, hle, ruka vztažená ke mně a hle, v ní svitek knihy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Rozprostřel jej přede mnou. Měl popsaný líc i rub a na něm byly zapsány žalozpěvy, lkání a bědování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'A řekl mi: Lidský synu, sněz to, co nalezneš. Sněz tento svitek a jdi, promluv k domu izraelskému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Otevřel jsem tedy svá ústa a on mi dal sníst tento svitek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Řekl mi: Lidský synu, nakrmíš své břicho a naplníš své útroby tímto svitkem, který ti dávám. Snědl jsem ho tedy a byl v mých ústech sladký jako med.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Pak mi řekl: Lidský synu, jdi, předstup před dům izraelský. Promluvíš k nim mými slovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Vždyť nejsi poslán k lidu nesrozumitelné řeči a těžkého jazyka, ale k domu izraelskému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Nikoli k mnohým národům nesrozumitelné řeči a těžkého jazyka, jejichž slovům bys nerozuměl -- pokud bych tě poslal k nim, oni by tě poslechli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Avšak dům izraelský tě nebude chtít poslouchat. ⌈Nejsou totiž ochotní poslouchat mě,⌉ protože celý dům izraelský má tuhé čelo a tvrdé srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Hle, dal jsem ti právě tak tuhé tváře jako jejich tváře a právě tak tuhé čelo jako jejich čelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Dal jsem ti čelo jako křemen, silnější než pazourek. Nebudeš se jich bát a nebudeš se před nimi třást (že jsou dům vzpoury).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Dále mi řekl: Lidský synu, všechna má slova, která k tobě promluvím, přijmi do svého srdce a poslouchej na vlastní uši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, '⌈Jdi, předstup před vyhnance, před syny svého lidu. Promluvíš k nim⌉ a řekneš jim: Toto řekl Panovník Hospodin, ať uposlechnou nebo ať nedbají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Pak mě Duch pozdvihl a slyšel jsem za sebou zvuk velkého hřmotu: Požehnaná je Hospodinova sláva ze svého místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'A zvuk křídel těch bytostí ⌈těsně se dotýkajících⌉ jedno druhého, zvuk kol vedle nich a zvuk velkého hřmotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Duch mě pozdvihl, zmocnil se mě a já jsem šel rozhořčený v hněvu svého ducha a Hospodinova ruka na mně mocně spočívala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Přišel jsem k vyhnancům v Tel Abíbu sídlícím u řeky Kebaru, ⌈pobýval jsem, kde oni bydlí,⌉ zůstal jsem tam sedm dnů a budil jsem uprostřed nich úžas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Když uplynulo sedm dnů, ⌈stalo se ke mně Hospodinovo slovo:⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Lidský synu, ustanovil jsem tě strážným domu izraelského. Vyslechneš slovo z mých úst a předáš jim ode mne výstrahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Když řeknu o ničemovi: Jistě zemřeš, a ty bys mu nepředal výstrahu a nepromluvil, abys ničemu varoval před jeho ničemnou cestou, abys mu daroval život; onen ničema zemře kvůli své zvrácenosti; ⌈jeho krev však vyhledám z tvé ruky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Ale pokud ty bys ničemu varoval a ten ničema by se neodvrátil od své ničemnosti a od své cesty, on pro svou zvrácenost zemře, zatímco ty jsi vysvobodil svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'A když se odvrátí spravedlivý od své spravedlnosti, provede špatnost a položím před něho pohoršení, on zemře, protože jsi ho nevaroval. Zemře ve svém hříchu a nebude připomínána jeho spravedlnost, kterou vykonal, a jeho krev vyhledám z tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Ale pokud ty bys toho spravedlivého varoval, aby nehřešil, a on by nehřešil, určitě zůstane naživu, neboť se nechal varovat a ty jsi vysvobodil svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'I spočinula tam na mně Hospodinova ruka a řekl mi: Vstaň, vyjdi na tu pláň, tam s tebou promluvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Vstal jsem, vyšel jsem na tu pláň a tam hle, Hospodinova sláva tam stála, stejně jako ⌈jsem ji⌉ spatřil u řeky Kebaru. I padl jsem na tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Pak do mě vstoupil duch, postavil mě na nohy a promluvil na mě. Řekl mi: Vejdi a zavři se uprostřed svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'A ty, lidský synu, pohleď: Vloží na tebe popruhy, svážou tě jimi a nebudeš moci mezi ně vycházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Přitom ti nechám jazyk přilnout k patru a budeš němý. Nebudeš pro ně mužem, který kárá, protože jsou dům vzpoury.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Když však s tebou budu mluvit já, otevřu tvá ústa a řekneš jim: Toto řekl Panovník Hospodin. Ten, kdo poslouchá, ať poslechne, a kdo je nedbalý, ať nedbá, neboť jsou dům vzpoury.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'A ty, lidský synu, vezmi si cihlu. Položíš ji před sebe a vyryješ na ni město Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Položíš proti němu obležení, vybuduješ proti němu obléhací val, navršíš proti němu násep a rozmístím proti němu vojska. Postav proti němu okolo válečné berany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Ty si pak vezmi plochou železnou pánev. Dáš ji jako železnou stěnu mezi sebe a to město. Zaměříš na něho svou tvář a bude v obležení; oblehneš jej. Je to znamení pro dům izraelský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Ty pak ulehni na svůj levý bok. Vložíš na něj zvrácenost domu izraelského. Podle počtu dnů, po který na něm budeš ležet, poneseš jejich zvrácenost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Já jsem ti převedl léta jejich zvrácenosti na počet dnů: tři sta devadesát dnů, a poneseš zvrácenost domu izraelského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Až tyto dny dovršíš, ulehneš podruhé, a to na pravý bok, a poneseš zvrácenost domu judského čtyřicet dnů: Jeden ⌈den za každý rok;⌉ vložil jsem ji na tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Pak zaměříš svou tvář a svou obnaženou paži k obležení Jeruzaléma a budeš proti němu prorokovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Hle, vložil jsem na tebe popruhy a nebudeš se moci převracet z boku na bok, dokud nedovršíš dny svého obléhání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Ty si teď vezmi ⌈pšenici, ječmen, fazole, čočku, proso a špaldu.⌉ Dáš je do jedné nádoby a budeš si z nich dělat pokrm tolik dnů, co budeš ležet na svém boku; budeš jej jíst tři sta devadesát dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Tvá potrava, kterou budeš jíst, bude na váhu dvacet šekelů na den. Budeš ji jíst ⌈po určený čas.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'I vodu budeš pít podle odměrky: ⌈šestinu hínu.⌉ Budeš pít ⌈po určený čas.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Budeš jíst ječný chléb a budeš jej péci na výkalech lidské nečistoty před jejich očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Nato řekl Hospodin toto: Synové Izraele budou jíst svůj chléb ⌈nečistý mezi národy,⌉ kam je zaženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'I řekl jsem: ⌈Ach, Panovníku Hospodine,⌉ hle, má duše není poskvrněná. Mršinu či rozsápané zvíře jsem nepojedl od svého mládí až do teď a do mých úst nepřišlo znehodnocené maso.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Řekl mi tedy: Pohleď, dal jsem ti kravská lejna místo lidských výkalů; svůj chléb budeš péci na nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Dále mi řekl: Lidský synu, hle, zlomím hůl chleba v Jeruzalémě. ⌈Budou jíst chléb na váhu a v nepokoji a vodu budou pít podle odměrky a v skleslosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Proto budou mít nedostatek chleba a vody, zděsí se ⌈jeden jako druhý⌉ a ⌈pro svou zvrácenost budou chřadnout.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'A ty, lidský synu, vezmi si ostrý meč jako holičskou čepel. Vezmeš si ho a přejedeš si jím ⌈přes hlavu a přes bradu.⌉ Pak si vezmeš misky na vážení a rozdělíš to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Třetinu zapálíš na ohništi uprostřed města, jakmile se naplní dny obléhání. Vezmeš další třetinu a rozsekáš mečem okolo něho a další třetinu rozptýlíš do větru. Já za nimi vytasím meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Ale vezmeš odtamtud trochu a uzavřeš to ⌈v cípech svého pláště.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'I z toho ještě vezmeš, hodíš to doprostřed ohně a spálíš to v ohni. Z něj vyjde oheň na celý dům izraelský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Toto řekl Panovník Hospodin: Postavil jsem tento Jeruzalém uprostřed národů a okolo něj jsem postavil země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Ale pro svou ničemnost se vzpíral mým nařízením více než národy a mým ustanovením více než země, které jsou okolo něj. Vždyť mými nařízeními pohrdli a ⌈podle mých ustanovení nežili.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Proto řekl Panovník Hospodin toto: Jelikož ⌈křiklavěji než národy, které jsou okolo vás,⌉ jste nežili podle mých ustanovení a má nařízení jste nekonali ani jste nejednali podle nařízení národů, které jsou okolo vás:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Proto řekl Panovník Hospodin toto: Hle, já zase ⌈jsem proti tobě⌉ a vykonám uprostřed tebe soudy před očima těch národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'A vykonám v tobě to, co jsem ještě nevykonal a co už nevykonám tomu podobného, kvůli všem tvým ohavnostem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Proto ⌈otcové uprostřed tebe budou jíst syny a synové budou jíst své otce.⌉ Vykonám nad tebou soudy a rozptýlím veškerý tvůj ostatek do všech větrů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Jakože jsem živ, ⌈ je výrok Panovníka Hospodina,⌉ jelikož jsi znečistil mou svatyni všemi svými ohavnými modlami a všemi svými odpornými věcmi, já se od tebe zase stáhnu, ⌈mé oko se neslituje a ani já nebudu mít soucit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Třetina z tebe ⌈zemře na mor a zajde od hladu uprostřed tebe, další třetina padne mečem⌉ okolo tebe a další třetinu rozptýlím do všech větrů a vytasím za nimi meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Pak pomine můj hněv, zanechám své zloby proti nim a pocítím lítost. I poznají, že ⌈já Hospodin jsem promluvil⌉ ve své žárlivosti, když skoncuji se svou zlobou proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Proměním tě v trosky a v potupu mezi národy, které jsou okolo tebe, před očima každého kolemjdoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'A staneš se potupou a zhanobením, ponaučením a úžasem pro národy, které jsou okolo tebe, až nad tebou vykonám soudy v hněvu, v zlobě a v hněvivém trestání. Já Hospodin jsem promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Až proti nim vystřelím zlé šípy hladu, které se staly ničitelem, které vystřelím, aby vás zničily, přidám vám hlad a zlomím vám hůl chleba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Pošlu na vás hlad a divou zvěř a ⌈učiní tě bezdětným,⌉ projde tebou mor a krev a přivedu na tebe meč. Já Hospodin jsem promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Lidský synu, ⌈nastav svou tvář proti⌉ izraelským horám a prorokuj proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Řekneš: ⌈Izraelské hory,⌉ slyšte slovo Panovníka Hospodina. Toto řekl Panovník Hospodin ⌈horám a návrším, řečištím a údolím:⌉ Hle, přivedu na vás meč a zničím vaše návrší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Vaše oltáře budou zpustošeny, vaše kadidlové oltáře budou rozdrceny a vaše pobité nechám padnout před vašimi bůžky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Mrtvoly synů Izraele zanechám před jejich bůžky a ⌈vaše kosti rozmetám okolo vašich oltářů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Ve všech vašich sídlech budou zpustošena města a zpustnou návrší, protože vaše oltáře budou zpustošeny a zničeny; vaši bůžkové budou rozdrceni a odklizeni, vaše kadidlové oltáře budou rozbity a vaše výtvory budou zahlazeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Pobitý padne uprostřed vás a pak ⌈poznáte, že já jsem Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Avšak, až se to stane, ⌈ponechám vám mezi národy ty, kdo uniknou meči, až budete roztroušeni do různých zemí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Pak si na mě ti z vás, kdo uniknou, vzpomenou mezi národy, kam byli vzati do zajetí, jak jsem byl zdrcen jejich smilnícím srdcem, které se ode mne odvrátilo, a jejich očima ⌈smilnícíma s⌉ jejich bůžky, a ⌈zhnusí se ⌈sami sobě⌉ pro zlo, které spáchali všemi svými ohavnostmi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'A poznají, že já Hospodin jsem nepromluvil bezdůvodně, že jim způsobím toto zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Toto řekl Panovník Hospodin: Udeř do své dlaně, dupni nohou a řekni: Ach! kvůli všem zlým ohavnostem domu izraelského, neboť padnou ⌈mečem, hladem a morem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Ten, kdo je daleko, zemře na mor, ten, kdo je blízko, padne mečem a ten, kdo zůstane a bude v obležení, zemře hladem, a tak proti nim dovrším svou zlobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'A poznáte, že já jsem Hospodin, až budou jejich pobití mezi jejich bůžky okolo jejich oltářů ⌈na každém vyvýšeném návrší, na všech vrcholech hor i pod každým zeleným stromem a pod každým košatým terebintem,⌉ na místě, kde předložili příjemnou vůni všem svým bůžkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Vztáhnu proti nim svou ruku a proměním tu zemi ve ⌈spoušť a zpustošenou krajinu,⌉ více než je ⌈pustina u Dibly,⌉ ve všech jejich sídlech. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Ty, lidský synu, slyš: Toto řekl Panovník Hospodin izraelské zemi: Konec, přišel konec na ⌈čtyři strany země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Teď je s tebou konec. Pošlu na tebe svůj hněv, budu tě soudit podle tvých cest a uvalím na tebe všechny tvé ohavnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Mé oko se nad tebou neslituje ani nebudu mít soucit, neboť na tebe uvalím tvé cesty a tvé ohavnosti budou uprostřed tebe. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Toto řekl Panovník Hospodin: ⌈Zlo za zlem⌉ právě přichází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Konec přišel, přišel ⌈konec, probudil⌉ se proti tobě. Hle, přichází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Přišel na tebe tvůj úděl, obyvateli země. Přišel ten čas, blízko je ⌈den zmatku, nikoli jásot hor.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Už brzy na tebe ⌈vyliji svou zlobu,⌉ dovrším svůj hněv proti tobě, budu tě soudit podle tvých cest a uvalím na tebe všechny tvé ohavnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Mé oko se neslituje ani nebudu mít soucit. Naložím s tebou podle tvých cest a tvé ohavnosti budou uprostřed tebe. I poznáte, že já Hospodin jsem ten, kdo bije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Hle, ten den, hle přichází. ⌈Kruh se uzavřel,⌉ ⌈rozkvetla hůl,⌉ rozpučela domýšlivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Násilí vzešlo v hůl ničemnosti. Nic z nich nebude, ani z jejich množství, ani z jejich hlučícího davu, ⌈ani žádné bědování nad nimi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Přišel ten čas, nastal ten den. Kupující ať se neraduje a prodávající ať netruchlí, protože přichází rozlícení proti všemu davu ⌈ té země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Vždyť prodávající se nenavrátí k prodané věci, i když ⌈oba zůstanou⌉ naživu, protože vidění pro všechen její dav se neodvrátí a lidé žijící ve svých zvrácenostech se nevzchopí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Zatroubili na trubku a vše je zajištěno, ale nikdo ne jde do boje, protože přichází mé rozlícení proti všemu jejímu davu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, '⌈Na ulici⌉ meč a doma mor a hlad. Kdo je na poli, zemře mečem a kdo ve městě, toho stráví hlad a mor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Když utečou ti z nich, kdo unikli, a dostanou se k horám, všichni budou sténat jako holubice z údolí, každý ⌈pro svou zvrácenost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Všechny ruce ochabnou a všechna kolena ⌈se rozplynou jako voda.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Přepásají se pytlovinou a přikryje je hrůza; na všech tvářích hanba a na všech jejich hlavách lysina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Své stříbro pohodí na ulice a zlato jim bude za nečisté. Jejich stříbro a jejich zlato je nebude moci vysvobodit v den Hospodinovy zuřivosti. Nenasytí svou duši a nenaplní své útroby, protože ⌈jejich zvrácenost je jim ku pohoršení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, '⌈Svou nádhernou ozdobu,⌉ ⌈tu vystavil jako svou pýchu,⌉ z té udělali obrazy svých ohavností, svých ohavných model. Kvůli tomu jsem jim ji proměnil v nečistotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'A dám ji do ruky cizinců za lup a ničemům země za kořist a znesvětí ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Odvrátím od nich svou tvář a oni znesvětí ⌈můj poklad.⌉ Vstoupí do něj lupiči a znesvětí jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Udělej řetěz, protože země se naplnila ⌈vinou za prolitou krev⌉ a město se naplnilo násilím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Přivedu nejhorší národy a ⌈obsadí jejich domy,⌉ skoncuji s pýchou silných a jejich svatyně budou znesvěcovány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Přišla stísněnost, budou hledat pokoj, ale žádný není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Přijde neštěstí za neštěstím a dojde zpráva za zprávou. Budou hledat vidění od proroka, ale knězi se ztratí zákon a starším rada.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Král bude truchlit, kníže si obleče úděs a ruce ⌈lidu země⌉ se budou třást. Naložím s nimi podle jejich cesty, budu je soudit podle jejich právních nařízení. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'I stalo se ⌈v šestém roce v šestém měsíci, pátého dne toho měsíce,⌉ když jsem seděl ve svém domě a judští starší seděli přede mnou, že tam na mě dolehla ruka Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Tu jsem viděl, hle, ⌈ muž vzhledem jakoby podobný ohni:⌉ Od jeho jakoby beder dolů oheň a od jeho beder nahoru vzhled jako záře, jako třpyt jantaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Vztáhl cosi jako ruku a vzal mě za kštici na hlavě. Duch mě pozdvihl mezi zemi a nebesa a přenesl mě v Božím vidění do Jeruzaléma ke vchodu vnitřní brány obrácené k severu, tam kde je sídlo sochy žárlivosti, která dráždí k žárlivosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'A tam hle, sláva Boha Izraele ⌈podobná vidění,⌉ které jsem spatřil na pláni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Řekl mi: Lidský synu, pozvedni nyní své oči směrem k severu. Pozvedl jsem tedy své oči směrem k severu a hle, na sever od oltářní brány byla ve vstupu tato socha žárlivosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Pak mi řekl: Lidský synu, vidíš přece, co páchají, velké ohavnosti, které tu páchá dům izraelský, abych se vzdálil od své svatyně. Znovu uvidíš ještě větší ohavnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Nato mě přivedl ke vchodu do nádvoří a hle, ve zdi jsem viděl nějakou díru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Řekl mi: Lidský synu, prokopej se nyní skrze zeď. Prokopal jsem se tedy skrze zeď a hle, nějaký vchod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Pak mi řekl: Vejdi a podívej se na ty zlé ohavnosti, které tady páchají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Tu jsem vešel a hle, viděl jsem všelijaká ⌈zpodobení plazů a zvířat⌉ hodných opovržení a všelijaké bůžky domu izraelského vyryté na zdi kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'A ⌈sedmdesát mužů ze starších domu izraelského⌉ s Jaazanjášem, synem Šáfanovým, stojícím uprostřed nich, stojí před nimi, každý se svou kadidelnicí v ruce a z ⌈kadidla vystupuje oblak⌉ vonného kouře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Tu mi řekl: Viděl jsi přece, lidský synu, co páchají starší domu izraelského potmě, každý v pokojích svých obrazů, neboť si říkají: Hospodin nás nevidí, Hospodin opustil zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Pak mi řekl: Znovu uvidíš ještě větší ohavnosti, které páchají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Přivedl mě ke vchodu do brány Hospodinova domu, která směřuje k severu, a hle, tam sedí ženy a ⌈oplakávají Tamúza.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Řekl mi: Viděl jsi přece, lidský synu. Znovu uvidíš ještě větší ohavnosti, než jsou tyto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Pak mě přivedl na vnitřní nádvoří Hospodinova domu a hle, u vchodu do Hospodinova chrámu ⌈mezi předsíní a oltářem⌉ je asi dvacet pět mužů zády k Hospodinovu chrámu a tvářemi k východu a ⌈sklánějí se před sluncem⌉ na východě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Nato mi řekl: Viděl jsi to, lidský synu? Cožpak bylo domu judskému málo páchat ty ohavnosti, které páchali tady? Vždyť naplnili zemi násilím, znovu mě provokovali ke hněvu a hle, ⌈podávají si vinnou ratolest k nosu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Také já budu jednat v zlobě, mé oko se neslituje ani nebudu mít soucit. Budou ke ⌈mně hlasitě⌉ volat, ale nevyslyším je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Pak on na mě hlasitě zavolal: Přiblížili se dozorci města, každý se svou zkázonosnou zbraní v ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'A hle, šest mužů přichází cestou od Horní brány, která je obrácena k severu, každý má v ruce svou ničivou zbraň a jeden muž uprostřed nich oděný lněným oděvem s písařským kalamářem na svých bedrech. Přišli a postavili se vedle bronzového oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'A sláva Boha Izraele se vznesla z cheruba, na němž spočívala, k prahu domu. Bůh zavolal na toho muže oděného lněným oděvem, který měl na bedrech písařský kalamář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Hospodin mu řekl: Projdi středem města, středem Jeruzaléma. Označíš značkou na čelech ty muže, kteří vzdychají a sténají nad všemi těmi ohavnostmi, které se uprostřed něho páchají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'A oněm řekl, jak jsem slyšel: Procházejte městem za ním a pobíjejte; vaše oko ⌈ať se neslituje,⌉ nemějte soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Starce, mládence a pannu i malé dítě a ženy zabíjejte až do úplného vyhubení, ale k žádnému člověku, na kterém je ta značka, nepřistupujte. Začnete od mé svatyně. Začali tedy mezi staršími muži, kteří byli před domem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Řekl jim: Znečistěte ten dům a naplňte nádvoří pobitými, jděte. I vyšli a pobíjeli ve městě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'A když je pobíjeli a já zůstal sám, padl jsem na tvář a volal jsem o pomoc. Řekl jsem: Ach, Panovníku Hospodine, cožpak ty zničíš celý ostatek Izraele, že vyléváš svou zlobu na Jeruzalém?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Odpověděl mi: Zvrácenost domu izraelského a judského je nadmíru velká. Země se naplnila ⌈prolitou krví⌉ a město naplnilo převracení práva, protože řekli: Hospodin zemi opustil, Hospodin nic nevidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Ani mé oko se neslituje a nebudu mít soucit. ⌈Jejich cestu jsem uvalil na jejich hlavu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Tu hle, ten muž oděný lněným oděvem, který má na bedrech kalamář, podává zprávu: Udělal jsem všechno, cos mi přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'A hle, viděl jsem, že na klenbě, která je nad hlavami cherubů, se nad nimi ukázalo cosi jako safír, vzhledem podobné trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Pak promluvil Panovník k tomu muži oděnému lněným oděvem a řekl: Vejdi do meziprostoru k podvozku pod cherubem a naplň si hrsti žhavými uhlíky ohně z meziprostoru u cherubů a rozsypej je na město. I vešel tam před mýma očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Když ten muž vcházel, stáli cherubové na pravé straně domu. Vnitřní nádvoří naplnil oblak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Hospodinova sláva se pozdvihla od cheruba k prahu domu, dům byl naplněn oblakem a nádvoří naplnila zář Hospodinovy slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'A zvuk křídel cherubů bylo slyšet až na vnější nádvoří jako hlas Všemohoucího Boha, když mluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'I stalo se, když přikázal tomu muži oděnému lněným oděvem: Vezmi oheň z meziprostoru u podvozku, z meziprostoru u cherubů, že přišel a postavil se vedle kola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Tu jeden cherub vztáhl svou ruku z meziprostoru u cherubů k ohni, který vyplňoval meziprostor cherubů, nabral a dal do hrstí tomu muži oděnému lněným oděvem. Ten si to vzal a vyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'U cherubů se tehdy ukázalo cosi jako lidská ruka pod jejich křídly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'A hle, viděl jsem čtyři kola vedle cherubů, jedno kolo vedle jednoho cheruba a další kolo vedle dalšího cheruba. Vzhled těch kol byl jako třpyt chryzolitu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Takže pokud jde o jejich vzhled: Všechna čtyři měla stejnou podobu, jako ⌈kdyby bylo⌉ kolo uprostřed kola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Když se dají do pohybu, pohybují se na všechny čtyři strany. Když se dají do pohybu, neotáčejí se, protože na místo, kam se obrátí hlava, tam se za ní pohybují. Při svém pohybu se neotáčejí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Celé své tělo i své hřbety, své ruce, svá křídla a ta kola mají ty čtyři bytosti kolem plná očí, u všech svých kol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Kolům, těm byl dán název podvozek, ⌈jak jsem slyšel.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Každá bytost má čtyři tváře. První tvář je tvář cheruba, druhá tvář je tvář lidská, třetí je tvář lva a čtvrtá je tvář orla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Cherubové se také vznášeli. Jedná se o stejnou bytost, jakou jsem viděl u řeky Kebaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Když se cherubové dají do pohybu, pohybují se ta kola vedle nich, a když cherubové roztáhnou svá křídla, aby se vznesli od země, kola ⌈neuhýbají; také ona zůstávají vedle nich.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Když se oni zastaví, zastaví se i kola, a když se vznesou, vznášejí se kola s nimi, protože je v nich duch té bytosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'I vyšla Hospodinova sláva od prahu domu a postavila se nad cheruby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Cherubové roztáhli křídla a vznesli se před mýma očima od země, když vycházeli, a kola měli vedle sebe. Zůstali stát u vchodu do východní brány Hospodinova domu a ⌈sláva Boha Izraele byla nahoře nad nimi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'To ⌈jsou ty bytosti, které⌉ jsem spatřil ⌈pod Bohem Izraele⌉ u řeky Kebaru, a poznal jsem, že jsou to cherubové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Každý má čtyři tváře, každý má čtyři křídla a pod svými křídly mají ruce podobné lidským.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Jejich tváře jsou podobné tvářím, které jsem spatřil u řeky Kebaru. ⌈Vypadali stejně -- byli to oni.⌉ Všichni se pohybují, kam směřují jejich tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Tu mě Duch pozdvihl, přivedl mě k východní bráně Hospodinova domu obrácené k východu; a hle, ve vchodu do brány bylo dvacet pět mužů. Uprostřed nich jsem viděl Jaazanjáše, syna Azúrova, a Pelatjáše, syna Benajášova, knížata lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Tehdy mi řekl: Lidský synu, tito muži vymýšlejí zlo a připravují v tomto městě zlý plán,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'když říkají: V blízké době nestavte domy; ono je hrnec a my jsme maso.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Proto prorokuj proti nim, prorokuj, lidský synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'I padl na mě Duch Hospodinův a on mi řekl: Promluv: Toto praví Hospodin: Tak jste promluvili vy, dome izraelský, a ⌈já vím, co vám přišlo na mysl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Rozmnožili jste v tomto městě počet pobitých, naplnili jste pobitými jeho ulice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Proto praví Panovník Hospodin toto: ⌈Vaši pobití, které jste nechali ležet uprostřed něho, jsou tím masem a ono je tím hrncem,⌉ ale vás jsem vyvedl z jeho středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Meče jste se báli a meč na vás přivedu, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Vyvedu vás z jeho středu, vydám vás do ruky cizinců a vykonám nad vámi soudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, '⌈Padnete mečem na izraelské hranici.⌉ Budu vás soudit a poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Ono se vám nestane hrncem ani vy se ne stanete uprostřed něho masem. Budu vás soudit na izraelské hranici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'I poznáte, že já jsem Hospodin, podle jehož ustanovení jste nežili a jehož nařízení jste nekonali, ale jednali jste ⌈podle nařízení národů, které jsou okolo vás.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'I stalo se, jakmile jsem prorokoval, že Pelatjáš, syn Benajášův, zemřel. Padl jsem na tvář, volal jsem hlasitě o pomoc a ⌈řekl jsem: Běda, Panovníku Hospodine, ty činíš konec s ostatkem Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Lidský synu, tvým bratrům, ⌈tvým příbuzným, po nichž můžeš dědit,⌉ a celému domu izraelskému, každému, komu obyvatelé Jeruzaléma řekli: Vzdalte se od Hospodina, ona země byla dána do vlastnictví nám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Proto řekni: Toto praví Panovník Hospodin: Ačkoliv jsem je vzdálil mezi národy a ačkoliv jsem je rozptýlil po zemích, stal jsem se jim na chvilku svatyní v zemích, do nichž přišli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Proto řekni: Toto praví Panovník Hospodin: I shromáždím vás z těch národů a vezmu vás z těch zemí, do nichž jste byli rozptýleni, a dám vám izraelskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Přijdou tam a odstraní z ní všechny její ohavné modly a všechny její odporné věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'A dám jim jedno srdce a nového ducha vložím do vašeho nitra, ⌈odstraním z jejich těla srdce kamenné a dám jim srdce masité,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'aby žili podle mých ustanovení, zachovávali má nařízení a plnili je. I ⌈budou mým lidem a já budu jejich Bohem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Avšak ohledně srdce těch, jejichž srdce chodí za jejich ohavnými modlami a za jejich odpornými věcmi: ⌈Jejich cestu jsem uvalil na jejich hlavu,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Tu cherubové pozdvihli svá křídla, kola měli vedle sebe a ⌈sláva Boha Izraele byla nahoře nad nimi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'A Hospodinova sláva vystoupila zprostřed města a zůstala stát nad horou, která je na východ od města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, '⌈Pak mě Duch pozdvihl a přivedl mě ve vidění v Božím Duchu do Chaldejska k vyhnancům⌉ a to vidění, které jsem spatřil, ode mě vystoupilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'A já jsem k vyhnancům promluvil o všech Hospodinových záležitostech, které mi ukázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Lidský synu, bydlíš uprostřed domu vzpoury, těch, kteří ⌈mají oči k vidění, ale nevidí, mají uši k slyšení, ale neslyší,⌉ protože jsou dům vzpoury.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'A ty, lidský synu, připrav si věci pro vyhnanství a odstěhuj se ve dne před jejich očima. Odstěhuješ se ze svého místa na jiné místo před jejich očima. Snad prohlédnou, že jsou dům vzpoury.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, '⌈Své věci vyneseš jako věci pro vyhnanství ve dne před jejich očima. Sám pak vyjdeš večer před jejich očima jako při odchodu vyhnanců.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Před jejich očima si pro sebe prokopej otvor ve zdi a vyneseš to skrze ni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Před jejich očima si to vyzvedneš na rameno, vyneseš za soumraku, ⌈zakryješ si tvář a nepodíváš se na zemi, protože jsem tě dal domu izraelskému jako znamení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'I učinil jsem tak, jak mi bylo přikázáno. Své věci jsem vynesl ve dne jako věci pro vyhnanství a večer jsem pro sebe ručně prokopal ve zdi otvor. Za soumraku jsem to vynesl a vyzvedl na rameno před jejich očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'I stalo se ke mně zrána Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Lidský synu, ⌈cožpak se tě nezeptali, dům izraelský, dům vzpoury, co to děláš?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Řekni jim: Toto praví Panovník Hospodin: Tento výnos je pro knížete v Jeruzalémě a pro celý dům izraelský, pro ty, kteří jsou uprostřed nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Řekni: Já jsem pro vás znamením. Jak jsem to udělal já, tak se stane jim. Půjdou do vyhnanství, do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'A ⌈kníže, který je uprostřed nich, si za soumraku vyzvedne na rameno věci a vyjde.⌉ Prokopají se skrze zeď, aby ho vyvedli skrze ni. Zakryje si tváře, jelikož je to on, kdo nezahlédne okem zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Rozprostřu nad ním svou síť, bude chycen do mé lovecké sítě a ⌈přivedu ho do Babylona, do země Chaldejců, ale neuvidí ji; tam zemře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'A všechny, kteří jsou okolo něj, jemu ku pomoci a všechny jeho šiky rozptýlím do všech stran a vytasím za nimi meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'A poznají, že já jsem Hospodin, až je rozptýlím mezi národy a rozmetám je po zemích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Ale zachovám z nich tolik mužů před mečem, před hladem a před morem, aby vyprávěli o všech svých ohavnostech mezi národy, kamkoli přijdou. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'A stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Lidský synu, svůj chléb jez s třesením a svou vodu pij s chvěním a s obavou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'A řekneš lidu země: Toto praví Panovník Hospodin o obyvatelích Jeruzaléma v izraelské zemi: Svůj chléb budou jíst s obavou a svou vodu budou pít v skleslosti, protože ⌈země bude zbavena všeho, co ji naplňuje, kvůli násilí všech obyvatel v ní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Obydlená města budou zpustošena a země se stane spouští. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Lidský synu, co to máte za pořekadlo o izraelské zemi, když říkáte: Dny budou dlouhé a každé vidění přijde vniveč?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Proto jim řekni: Toto praví Panovník Hospodin: Skoncoval jsem s tímto pořekadlem a už ho v Izraeli nebudou užívat. Nýbrž promluv k nim: Přiblížily se ty dny i záměr každého vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Už totiž nebude uprostřed domu izraelského žádné klamné vidění a lichotivá věštba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Vždyť já Hospodin promluvím to, co promluvím, slovo, které bude vykonáno, už se neoddálí. Ve vašich dnech totiž, dome vzpoury, ⌈promluvím slovo a vykonám ho, je výrok Panovníka Hospodina.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Lidský synu, pohleď na dům izraelský. ⌈Říkají: Vidění, které on vidí, se týká doby po mnoha dnech, prorokuje pro vzdálené časy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Proto jim řekni: Toto praví Panovník Hospodin: Už se neoddálí žádné z mých slov. Slovo, které promluvím, se uskuteční, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Lidský synu, prorokuj proti izraelským prorokům, kteří prorokují. Řekneš těm, kteří prorokují ze svého srdce: Slyšte Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Toto praví Panovník Hospodin: Běda těm bláznivým prorokům, kteří jdou za svým duchem, aniž by viděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Jako lišky v troskách jsou tví proroci, Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, '⌈Nevstoupili jste do trhlin a ne zazdívali jste zeď domu izraelského,⌉ aby obstál v boji v den Hospodinův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Viděli klam a lživou věštbu, ti, kdo říkají: Hospodinův výrok. Hospodin je neposlal, a přece očekávali na potvrzení slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Cožpak jste neviděli klamné vidění a ne pronesli jste lživou věštbu? Říkáte: Hospodinův výrok, a já jsem přitom nepromluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Proto praví Panovník Hospodin toto: Jelikož mluvíte klam a vidíte lež, proto hle, já jsem proti vám, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Má ruka bude proti těm prorokům, kteří vidí klam a kteří věští lež. Nebudou v důvěrném společenství mého lidu, nebudou zapsáni v zápisu domu izraelského ani nevejdou na izraelskou půdu. ⌈I poznáte, že já jsem Panovník Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Jelikož a protože zmátli můj lid slovy: ⌈Pokoj! Ale žádný pokoj není.⌉ On staví stěnu a hle, oni ji omítají omítkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Řekni těm, kdo omítají omítkou: Spadne to. Přišel ⌈přívalový déšť a vy, kameny jako krupobití,⌉ spadnete a bouřlivý vítr to prolomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'A hle, ta zeď spadla. Cožpak vám neřeknou: Kde je ta omítka, kterou jste omítali?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Proto praví Panovník Hospodin toto: Prolomím to bouřlivým větrem ve své zlobě, přijde i přívalový déšť v mém hněvu a krupobití kamenů v zlobě, abych s tím skoncoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Zbořím tu zeď, kterou jste omítali omítkou, srazím ji k zemi a bude odhalen její základ, spadne a vy pominete uprostřed ní. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Tehdy dovrším svou zlobu proti zdi a proti těm, kdo ji omítají omítkou, a řeknu vám: Už není ta zeď ani ti, kdo ji omítali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'izraelští proroci, kteří prorokovali o Jeruzalému a kteří pro něho viděli vidění pokoje. Žádný pokoj však není, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'A ty, lidský synu, ⌈nastav svou tvář⌉ proti dcerám svého lidu, které ⌈prorokují ze svého srdce,⌉ a prorokuj proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Řekneš: Toto praví Panovník Hospodin: Běda těm, kdo splétají pásky na každé zápěstí a zhotovují kukly na hlavu každé velikosti, aby lovily duše. Budete lovit duše mého lidu a své duše zachováte při životě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Znesvětily jste mě před mým lidem za hrst ječmene a za kus chleba, abyste usmrtily duše, které nemají zemřít, a abyste darovaly život duším, které nemají žít, když obelháváte můj lid, který poslouchá lež.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Proto praví Panovník Hospodin toto: Hle, jsem proti vašim páskám, do kterých lovíte duše ⌈jako ptáky.⌉ Strhnu je z vašich paží a propustím ty duše, duše, které vy lovíte jako ptáky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Strhnu i vaše kukly a vysvobodím svůj lid z vaší ruky. Už nebudou úlovkem ve vaší ruce. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Jelikož mučíte srdce spravedlivého klamem, ačkoliv já jsem mu nepůsobil bolest, aby se posilnila ruka ničemy, aby se neodvrátil od své zlé cesty, aby ne byl zachován při životě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Proto už nebudete prorokovat klam a nebudete věštit věštbu, ale vysvobodím svůj lid z vaší ruky. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Tu ke mně přišli někteří z izraelských starších a posadili se přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Lidský synu, tito muži vnesli své bůžky do svého srdce a položili před sebe ⌈pohoršení své zvrácenosti.⌉ Cožpak jim ⌈opravdu dovolím se dotazovat?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Proto s nimi promluv. Řekneš jim: Toto praví Panovník Hospodin: Každému muži z domu izraelského, který vnese své bůžky do svého srdce, položí před sebe pohoršení své zvrácenosti a přijde k prorokovi -- ⌈každému takovému, kdo přijde, odpovím já Hospodin podle množství jeho bůžků.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'A tak uchopím dům izraelský za srdce, kterým se ode mne oni všichni odvrátili ke svým bůžkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Proto řekni domu izraelskému: Toto praví Panovník Hospodin: Obraťte se a odvraťte od svých bůžků, od všech svých ohavností odvraťte svou tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Neboť každému muži z domu izraelského i z příchozích, kteří budou pobývat v Izraeli, když se ode mne oddělí, vnese své bůžky do svého srdce, položí před sebe pohoršení své zvrácenosti a přijde k prorokovi, aby se jej na mě dotázal, já Hospodin mu sám odpovím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Nastavím svou tvář proti onomu muži, učiním ho znamením a pořekadlem a ⌈vyhladím ho zprostřed svého lidu.⌉ I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'A když se ten prorok dá svést a promluví slovo, ⌈svedl jsem ho já Hospodin.⌉ Vztáhnu proti němu svou ruku a vyhladím jej zprostřed svého izraelského lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'I ponesou svou zvrácenost. Zvrácenost toho, kdo se dotazuje, bude stejná jako zvrácenost proroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'To aby už ode mne dům izraelský nezbloudil a neposkvrňoval se už žádnými přestoupeními. I ⌈budou mým lidem a já budu jejich Bohem,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Lidský synu, pokud proti mně země zhřeší tím, že se zpronevěří věrolomností, vztáhnu proti ní ruku, zlomím jí hůl chleba, pošlu do ní hlad a vyhladím z ní ⌈člověka i zvíře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'A budou– li uprostřed ní tito tři muži: ⌈Noe, Daniel a Jób,⌉ ti ve své spravedlnosti vysvobodí jen svou duši, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Kdybych přivedl do země divou zvěř, ta by ji učinila bezdětnou a země by se stala spouští, aniž by jí kdo kvůli té zvěři procházel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'zdalipak tito tři muži uprostřed ní -- jakože jsem živ, je výrok Panovníka Hospodina -- vysvobodí syny a dcery? Oni vysvobodí sami sebe, ale země se stane spouští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Anebo přivedu– li na onu zemi meč a řeknu, ať meč projde skrze zemi, a vyhladím z ní člověka i zvíře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'ani tito tři muži uprostřed ní -- jakože jsem živ, je výrok Panovníka Hospodina -- nevysvobodí syny ani dcery; oni totiž vysvobodí jen sami sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Anebo pošlu– li na onu zemi mor a vyliji na ni svou zlobu skrze krveprolití, abych z ní vyhladil člověka i zvíře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'a zdalipak Noe, Daniel a Jób uprostřed ní -- jakože jsem živ, je výrok Panovníka Hospodina -- vysvobodí syna nebo dceru? Oni ve své spravedlnosti vysvobodí jen svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Neboť toto praví Panovník Hospodin: I kdybych poslal na Jeruzalém své čtyři zlé soudy: ⌈meč a hlad, divou zvěř a mor,⌉ abych z něj vyhladil člověka i zvíře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'hle, zůstalo by v něm útočiště vyváznuvších synů a dcer; ano, oni vám jdou naproti a až uvidíte jejich jednání a jejich činy, dojdete útěchy nad tím zlem, které jsem uvedl na Jeruzalém, po všem, co jsem na něj uvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'A potěší vás, protože uvidíte jejich jednání a jejich činy, a poznáte, že jsem nevykonal bezdůvodně nic, co jsem v něm vykonal, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Lidský synu, ⌈čím bude dřevo vinné révy lepší než jiný strom, vinná ratolest, která byla mezi stromy v lese?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Cožpak z něj bude vzato dřevo, aby se použilo k nějakému dílu? Vezmou z něj snad na kolík, aby na něm visel jakýkoliv nástroj?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Hle, byl dán za pokrm ohni; ⌈jeho dva konce strávil oheň a jeho střed byl ožehnut,⌉ cožpak se bude hodit pro nějaké dílo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Hle, když je ještě celý, ⌈ne dá se z něj nic udělat,⌉ tím spíše, když ho strávil oheň a byl ožehnut, ⌈bude se ještě k něčemu hodit?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Proto praví Panovník Hospodin toto: Jako keř vinné révy mezi lesním dřevem, který jsem vydal ohni za pokrm, tak jsem vydal obyvatele Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Nastavím proti nim svou tvář. ⌈Z ohně vyšli⌉ a ten ⌈oheň je stráví.⌉ I poznáte, že já jsem Hospodin, ⌈až obrátím svou tvář proti nim.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'A tu zemi proměním ve spoušť, jelikož se zpronevěřili věrolomností, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Lidský synu, pouč Jeruzalém o jeho ohavnostech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Řekneš: Toto praví Panovník Hospodin o Jeruzalému: Svým původem a svým rodištěm jsi z kenaanské země, ⌈tvůj otec je Emorejec a tvá matka Chetejka.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'A ohledně tvého narození: V den, kdy ses narodila, nebyla přeříznuta tvá ⌈pupeční šňůra a nebylas obmyta vodou k očištění, vůbec jsi nebyla potřena solí⌉ a vůbec jsi nebyla obvinuta plenkami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Žádné oko se nad tebou neslitovalo, aby pro tebe udělali jednu z těchto věcí ze soucitu nad tebou, ale bylas pohozena na povrchu pole v hnusu nad tvou bytostí v den, kdy ses narodila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Procházel jsem nad tebou, viděl jsem tě, jak se zmítáš ve vlastní krvi, a řekl jsem ti, když jsi ležela ⌈ve své krvi: Zůstaň naživu.⌉ Řekl jsem ti, když jsi ležela ve své krvi: Zůstaň naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Dal jsem ti vzrůst jako stéblu na poli, rostla jsi, vzmáhala ses a předstoupila jsi v ⌈ nádherné ozdobě.⌉ Prsy se zpevnily, vlasy ti bohatě narostly a ty jsi byla obnažená a nahá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Procházel jsem nad tebou, viděl jsem tě a hle, byl tvůj čas, čas něžností. ⌈Rozprostřel jsem nad tebou cíp svého pláště ⌉ a přikryl jsem tvou nahotu. Přísahal jsem ti a vešel jsem s tebou ve smlouvu, je výrok Panovníka Hospodina, a stala ses mou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Umyl jsem tě vodou, opláchl jsem z tebe tvou krev a pomazal jsem tě olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Oblékl jsem ti pestře utkané šaty, obul jsem ti tachaší opánky, ovinul jsem tě jemným plátnem a zakryl jsem tě hedvábím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Ozdobil jsem tě ozdobami, na tvé ruce jsem dal náramky a na tvé hrdlo náhrdelník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Dal jsem ti kroužek na nos, náušnice do uší a krásný věnec na hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Zdobila ses zlatem a stříbrem, tvým oděvem bylo jemné plátno, hedvábí a pestře utkané šaty. Jedla jsi jemnou mouku, med a olej, stala ses převelice krásnou a uchvátila jsi královskou autoritu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Tvé jméno proniklo mezi národy pro tvou krásu, protože byla dokonalá díky mé důstojnosti, kterou jsem na tebe vložil, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Spoléhala jsi však na svou krásu a smilnila jsi proti svému jménu, vylévala jsi své smilnění na každého kolemjdoucího, jen ať je to jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Brala jsi ze svých rouch, dělala jsi pro sebe strakatá návrší a smilnila jsi na nich, jak se to dříve nedělo a nemá dít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Brala jsi i své ozdobné předměty z mého zlata a z mého stříbra, které jsem ti dal, a dělala jsi pro sebe mužské obrazy a smilnila jsi s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Brala jsi pestře utkaná roucha, přikrývala jsi je a před ně jsi položila můj olej a mé kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'I můj pokrm, který jsem ti dal -- nakrmil jsem tě jemnou moukou, olejem a medem -- kladla jsi jej před ně jako příjemnou vůni. A to se skutečně dělo, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Brala jsi i své syny a své dcery, které jsi mi porodila, a obětovala jsi jim je k jídlu. Bylo snad tvého smilnění málo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Zabíjela jsi mé syny a vydávala jsi je jim, když jsi je pro ně prováděla ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Při všech svých ohavnostech a svém smilnění sis nevzpomněla na dny svého mládí, kdy jsi byla obnažená a nahá, zmítající se ve své krvi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'I stalo se po všem tvém zlu -- běda, běda tobě, je výrok Panovníka Hospodina --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'že jsi pro sebe postavila násep a udělala jsi pro sebe výšinu na každém náměstí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Na každé křižovatce jsi postavila svou výšinu. Opovrhovala jsi svou krásou, roztahovala jsi své nohy pro každého kolemjdoucího a množila jsi své smilnění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Smilnila jsi se syny Egypta, svými sousedy statného těla, a množila jsi své smilnění, abys mě provokovala ke hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'A hle, vztáhl jsem proti tobě svou ruku, ⌈zkrátil jsem tvůj podíl⌉ a vydal jsem tě touze těch, ⌈kdo tě nenávidí, pelištejských dcer,⌉ které se stydí za tvé hnusné jednání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Nenasytně jsi smilnila se syny Asýrie, smilnila jsi s nimi a ještě ses nenasytila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Rozšířila jsi své smilnění ⌈po zemi kramářů ke Chaldejcům⌉ a ani tím ses nenasytila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Jak zchřadlé je tvé srdce, je výrok Panovníka Hospodina, že pácháš všechny tyto věci, činy nestydaté prostitutky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'když jsi postavila násep na každé křižovatce a svou výšinu jsi udělala na každém náměstí? Ale nebylas jako prostitutka, když jsi pohrdala nevěstčí mzdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Cizoložnice namísto svého muže přijímá cizáky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Všem prostitutkám dávají dar, zatímco ty jsi dávala své dary všem svým milencům a odměňovala jsi je, aby k tobě vcházeli z okolí za tvým smilněním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Bylas odlišná od jiných žen při smilnění. ⌈Ty jsi totiž kvůli smilstvu nebyla vyhledávána,⌉ když jsi sama dávala nevěstčí mzdu, zatímco tobě nevěstčí mzda dávána nebyla; tím jsi byla odlišná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Proto slyš Hospodinovo slovo, prostitutko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Toto praví Panovník Hospodin: Jelikož ⌈byl rozhazován tvůj bronz⌉ a byla odhalována tvá nahota při smilnění s tvými milenci a se všemi ⌈tvými ohavnými bůžky,⌉ stejně jako prolitá ⌈krev tvých synů, které jsi jim vydala,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'proto hle, shromažďuji všechny tvé milence, s nimiž ses těšila, a všechny, které jsi milovala, se všemi, které jsi nenáviděla. Shromáždím je k tobě z okolí, ⌈odhalím před nimi tvou nahotu⌉ a oni všechnu tvou nahotu uvidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, '⌈Budu tě soudit ⌈ podle právních nařízení⌉ pro cizoložnice⌉ a pro ty, které prolévají krev, a vydám tě krveprolití se zlobou a žárlivostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Vydám tě do jejich ruky. ⌈Zboří tvůj násep a strhnou tvé výšiny,⌉ svléknou ti tvá roucha, seberou tvé ozdobné předměty a ponechají tě obnaženou a nahou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Přivedou proti tobě shromáždění, budou na tebe házet kamení a probodnou tě svými meči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Tvé domy spálí ohněm a vykonají nad tebou soudy před očima mnohých žen. Odradím tě od prostituce a také nevěstčí mzdu už nebudeš dávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Zanechám své zloby proti tobě a má žárlivost se od tebe odvrátí, budu mít klid a již se nebudu hněvat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'A proto jako ty sis nevzpomněla na dny svého mládí a dráždila jsi mě tímhle vším, právě tak ⌈jsem zase já uvalil tvou cestu na tvou hlavu,⌉ je výrok Panovníka Hospodina. Nespáchala jsi tu hanebnost navíc ke všem svým ohavnostem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Hle, každý, kdo užívá pořekadla, o tobě užije toto: Jaká matka, taková její dcera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Jsi dcerou své matky, která si oškliví svého muže i své syny, a jsi sestrou svých sester, které si zošklivily své muže i své syny. ⌈Vaše matka je Chetejka a váš otec Emorejec.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Tvou starší sestrou je pak Samaří se svými dcerami sídlící po tvé levici a tvou mladší sestrou sídlící zprava od tebe je Sodoma a její dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Ne jen že jsi chodila po jejich cestách, páchala jsi jejich ohavnosti, ale zakrátko omrzelá ses vrhala na všech svých cestách do zkázy více než ony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Jakože jsem živ, je výrok Panovníka Hospodina, tvá sestra Sodoma se svými dcerami nespáchala to, co jsi spáchala ty a tvé dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Hle, toto byla zvrácenost tvé sestry Sodomy: Vznešenost, nasycenost chlebem a utěšená bezstarostnost, to měla ona i její dcery, ale ruku chudého a nuzného neposilovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Povyšovaly se a páchaly přede mnou ohavnost. Odstranil jsem je tedy, jakmile jsem to spatřil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Samaří nezhřešilo ani do poloviny tvých hříchů. Rozmnožila jsi své ohavnosti více než ony, a tak jsi své sestry prohlásila za spravedlivé všemi svými ohavnostmi, které jsi spáchala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Ano, ty tedy nes svou ostudu, kterou jsi přisoudila svým sestrám. Pro hříchy, jimiž jsi jednala ohavněji než ony, budou spravedlivější než ty. Ano, ty se tedy styď a nes svou ostudu, když jsi své sestry prohlásila za spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'I změním jejich úděl, úděl Sodomy a jejích dcer, úděl Samaří a jeho dcer a také úděl, tvůj úděl uprostřed nich,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'abys nesla svou ostudu a zahanbila se za všechno, co jsi spáchala, když ses pro ně stala útěchou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Tvé sestry, Sodoma a její dcery, se navrátí k svému dřívějšímu stavu. I Samaří a její dcery se navrátí k svému dřívějšímu stavu a také ty a tvé dcery se navrátíte k svému dřívějšímu stavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'V době, kdy byla znát tvá vznešenost, ⌈nebylo z tvých úst o tvé sestře Sodomě slyšet,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'dříve než bylo odhaleno tvé zlo jako v době tupení od dcer Aramu a celého jeho okolí, ⌈pelištejských dcer, které tebou ze všech stran opovrhují.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Sama poneseš svou hanebnost a své ohavnosti, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Neboť toto praví Panovník Hospodin: Budu s tebou tedy jednat tak, jako jsi jednala ty, když jsi pohrdla přísahou, takže jsi porušila smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Já si však vzpomenu na svou smlouvu s tebou, uzavřenou ve dnech tvého mládí, a ustanovím pro tebe smlouvu věčnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Pak si vzpomeneš na své cesty a budeš zahanbena, až přijmeš své sestry, od těch starších než jsi ty, po ty mladší než jsi ty, a dám ti je za dcery, ne však podle smlouvy s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Já tedy ustanovím svou smlouvu s tebou a poznáš, že já jsem Hospodin,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'aby ses rozpomenula a styděla ses a už sis kvůli své ostudě nedovolila otevřít ústa, až se s tebou usmířím za všechno, co jsi spáchala, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Lidský synu, dej domu izraelskému hádanku a užij podobenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Řekneš: Toto praví Panovník Hospodin: Převeliký orel s dlouhými křídly a perutěmi plnými peří, které má pestré zbarvení, přiletěl k Libanonu a uchopil vrcholek cedru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Utrhl vrcholek jeho výhonků a přinesl jej do země kramářů, položil jej ve městě prodejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Potom vzal jiný ze semene té země a dal jej do plodné země, vzal ho u hojných vod, jako vrbu jej zasadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'I vzešel a stal se ⌈bujnou vinnou révou nízkého vzrůstu,⌉ aby k němu obracel své větve a jeho kořeny byly pod ním. Stal se vinnou révou, vyrazil haluze a vyhnal ratolesti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Pak se objevil další velký orel s velkými křídly a hojným peřím a hle, tato vinná réva k němu upnula své kořeny a vztáhla k němu své větve, aby ji napájel ze záhonů, kde byla vysazena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Byla zasazena na dobrém poli u hojných vod, aby vyrazila větvoví a aby nesla ovoce, aby se stala proslulou vinnou révou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Řekni: Toto praví Panovník Hospodin: Vydaří se? Cožpak nezpřetrhá její kořeny a ne otrhá její ovoce a ne uschne? ⌈Každý její čerstvě utržený výhonek uschne.⌉ Nebude třeba velké síly a početného lidu, aby ji vytrhli z kořenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Hle, byla zasazena, cožpak se ale vydaří? Což rychle neuschne, jakmile se jí dotkne východní vítr? Na záhonech, kde vzešla, uschne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Řekni nyní domu vzpoury: Což nechápete, co tyhle věci znamenají? Řekni: Hle, babylonský král přišel do Jeruzaléma, vzal jeho krále a jeho knížata a přivedl je k sobě do Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Vzal muže z královského potomstva, uzavřel s ním smlouvu, uvedl jej pod přísahu a zajal mocnáře země,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'aby království bylo poníženo, aby se nevyvyšovalo, aby zachovávalo jeho smlouvu a tak obstálo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'On se však proti němu vzbouřil, když poslal své posly ⌈ do Egypta, aby mu dali koně a početný lid.⌉ Jestlipak uspěje, jestlipak unikne ten, kdo dělá takové věci? Poruší smlouvu a měl by uniknout?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Jakože jsem živ, je výrok Panovníka Hospodina, jistě zemře na území toho krále, který ho ustanovil králem, jehož přísahou pohrdl a jehož smlouvu porušil, zemře u něj uprostřed Babylona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Ani s velkým vojskem a s početným davem pro něho faraon v boji nic ne zmůže, když navrší násep a když vybuduje obléhací val, aby vyhladil mnoho lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Pohrdl však přísahou, až i zmařil smlouvu. Hle, dal na to ruku, a přece spáchal všechny tyto věci. Neunikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Proto praví Panovník Hospodin toto: Jakože jsem živ, uvidíme, jestli svou přísahu, kterou on pohrdl, a svou smlouvu, kterou on porušil, neuvalím na jeho hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Rozprostřu nad ním svou síť a chytí se do mé lovecké sítě, přivedu ho do Babylona a budu se tam s ním soudit. Sám sobě se zpronevěřil, když se zpronevěřil mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'A všichni jeho uprchlíci ve všech jeho šicích padnou mečem a pozůstalí budou rozptýleni do všech stran. I poznáte, že já Hospodin jsem promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Toto praví Panovník Hospodin: Já vezmu z vrcholku toho vzrostlého cedru a uložím to, z vrcholu utrhnu jeho útlé ratolesti a sám je zasadím na vysoké čnící hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Zasadím jej vysoko na izraelské hoře a rozvine větvoví, vydá plod a stane se vznešeným cedrem. ⌈Usídlí se pod ním každý pták,⌉ všelijaký okřídlenec; budou přebývat ve stínu jeho větví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Pak poznají všechny polní stromy, že já Hospodin ⌈jsem snížil strom vysoký, vyvýšil jsem strom nízký,⌉ nechal jsem vyschnout strom syrový a nechám rozpučet strom vyschlý. ⌈Já Hospodin jsem promluvil a také to vykonám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Co máte na mysli, když užíváte o izraelské zemi toto přísloví: ⌈Otcové jedí trpké hrozny a synům trnou zuby?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Jakože jsem živ, je výrok Panovníka Hospodina, uvidíme, jestli se v Izraeli mezi vámi toto přísloví ještě bude užívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Vždyť mně patří všechny duše, patří mi jak duše otcova, tak i duše synova. ⌈Duše, která hřeší, ta zemře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Avšak bude–li někdo spravedlivý a bude konat právo a spravedlnost --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'nehodoval na horách, své oči nepozvedl k bůžkům domu izraelského, ⌈neznečistil ženu svého bližního⌉ a ⌈nepřiblíží se k menstruující ženě,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'nikoho nebude utiskovat, vrátí zástavu dluhu, neuchvátí lup, svůj chléb dá hladovému a obnaženého zakryje oděvem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, '⌈nebude dávat na lichvu a nebude vybírat úrok,⌉ odvrátí svou ruku od špatnosti, ⌈bude konat pravdivý soud mezi člověkem a člověkem,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'bude chodit podle mých ustanovení, zachovávat i má nařízení, aby uskutečňoval pravdu -- takový spravedlivý určitě bude žít, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Když zplodí syna násilníka, který prolévá krev a udělá bratru kteroukoli z těchto věcí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, '(ačkoliv jeho otec sám nic z těchto věcí nespáchal), vždyť i hodoval na horách a znečistil ženu svého bližního,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'utiskoval chudého a nuzného, uchvátil lup a nevrací zástavu, pozvedl své oči k bůžkům a páchal ohavnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'dával na lichvu a vybíral úrok. Bude žít? Nebude žít! Spáchal všechny tyto ohavnosti, jistě bude usmrcen, zůstane na něm jeho krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'A hle, zplodil by syna a ten by viděl všechny hříchy, které spáchal jeho otec; i když je viděl, nebude jednat podle nich:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Na horách nehodoval a své oči nepozvedl k bůžkům domu izraelského, ženu svého bližního neznečistil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'nikoho neutiskoval, nevzal zástavu a neuchvátil lup, svůj chléb dával hladovému a obnaženého zakrýval oděvem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'neublížil chudému -- lichvu ani úrok nevybíral, plnil má nařízení, chodil podle mých ustanovení; takový nezemře pro zvrácenost svého otce, určitě bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Jeho otec, protože se dopouštěl útlaku, oloupil bratra a činil uprostřed svého lidu to, co není dobré, hle, zemřel pro svou zvrácenost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Řeknete však: Proč syn nesnášel trest za zvrácenost otce? Protože ten syn konal právo a spravedlnost, zachovával všechna má ustanovení a konal je, určitě bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Duše, která hřeší, ta zemře. ⌈Syn neponese trest za zvrácenost otce ani otec neponese trest za zvrácenost syna.⌉ ⌈Spravedlnost spravedlivého zůstane na něm a rovněž ničemnost ničemy zůstane na něm.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Pokud se však ničema odvrátí od všech svých hříchů, které spáchal, bude zachovávat všechna má ustanovení a bude konat právo a spravedlnost, určitě bude žít, nezemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Žádná jeho přestoupení, kterých se dopustil, mu nebudou připomínána; podle své spravedlnosti, kterou vykonal, bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Copak si opravdu přeji smrt ničemy, je výrok Panovníka Hospodina? Ne mám snad v oblibě, když se odvrátí od svých cest a bude žít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Když se ale spravedlivý odvrátí od své spravedlnosti a spáchá špatnost, bude jednat podle všech ohavností, které spáchal ten ničema, bude žít? Žádné jeho spravedlivé činy, které konal, nebudou připomínány. Zemře ve své věrolomnosti, kterou se zpronevěřil, a ve svém hříchu, kterým zhřešil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Vy však řeknete: Panovníkova cesta není v pořádku. Slyšte přece dome izraelský! Má cesta že není v pořádku? Cožpak nejsou v nepořádku vaše cesty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Když se spravedlivý odvrátí od své spravedlnosti a spáchá špatnost, zemře kvůli ní. Zemře pro svou špatnost, kterou spáchal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Když by se však odvrátil ničema od své ničemnosti, kterou spáchal, a konal by právo a spravedlnost, takový zachová svou duši při životě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Prohlédl a odvrátil se od všech svých přestoupení, kterých se dopustil; určitě bude žít, nezemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Dům izraelský ale řekne: Panovníkova cesta není v pořádku. Mé cesty nejsou v pořádku, dome izraelský? Cožpak nejsou v nepořádku vaše cesty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Proto vás budu soudit, každého podle jeho cest, dome izraelský, je výrok Panovníka Hospodina. Obraťte se, odvraťte se od všech svých přestoupení a zvrácenost vám nebude ku pohoršení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Odvrhněte od sebe všechna svá přestoupení, jimiž jste se vzepřeli a získejte nové srdce a nového ducha. Proč máte zemřít, dome izraelský?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Vždyť nemám zalíbení ve smrti toho, kdo umírá, je výrok Panovníka Hospodina. Obraťte se a zůstaňte naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Ty pak pozvedni žalozpěv za izraelské předáky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Řekneš: Co byla tvá matka? ⌈Lvice, mezi lvy uléhala, uprostřed mladých lvů vychovala svá mláďata.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Když odchovala jedno ze svých mláďat, stal se z něj mladý lev a naučil se rozsápat kořist. Žral lidi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Slyšely o něm národy, byl chycen do jejich jámy a přivedli jej za kruhy do egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Když viděla, že čekala marně, její naděje zahynula; vzala jedno ze svých mláďat a učinila z něj mladého lva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Procházel se uprostřed lvů, stal se z něj mladý lev a naučil se rozsápat kořist. Žral lidi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, '⌈Zbořil jejich paláce⌉ a zničil jejich města. Zvukem jeho řvaní zpustla země i všechno, co ji naplňuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Vydaly se tedy na něho národy z okolních krajin a rozprostřely nad ním svou síť. Byl chycen do jejich jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Pak ho dali s kruhy do klece a přivedli jej k babylonskému králi. Přivedli ho do pevností, aby už nebylo slyšet jeho hlas na izraelských horách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Tvá matka byla jako vinná réva na tvé vinici, zasazená u vod. ⌈Nesla ovoce⌉ a byla rozvětvená díky hojnosti vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Její větve byly dost silné na žezla vládců, svým vzrůstem se vyvýšila mezi hustými větvemi a bylo ji vidět pro její výšku a pro množství jejích větví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Byla však s hněvem vyvrácena, byla pohozena na zem a východní vítr vysušil její ovoce. Její silné větve byly vyrvány a uschly. Strávil to oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Nyní je tedy zasazena v pustině, v bezvodé a vyprahlé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, '⌈Z větve jejích haluzí pak vyšel oheň, strávil její ovoce⌉ a nezůstala na ní žádná silná větev vhodná na žezlo pro vládce. To je žalozpěv a byl určen, aby se zpíval jako žalozpěv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'I stalo se v sedmém roce v pátém měsíci, desátého dne toho měsíce, že přišli muži z izraelských starších, aby se dotázali Hospodina, a posadili se přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Lidský synu, promluv s izraelskými staršími. Řekneš jim: Toto praví Panovník Hospodin: Co to, že přicházíte, abyste se mě dotázali? Jakože jsem živ, dovolím vám snad, abyste se mě dotazovali, je výrok Panovníka Hospodina?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Budeš je soudit? Budeš soudit, lidský synu? Pouč je o ohavnostech jejich otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Řekneš jim: Toto praví Panovník Hospodin: V den, kdy jsem si vyvolil Izrael, jsem pozvedl svou ruku k potomstvu Jákobova domu a dal jsem se jim poznat v egyptské zemi. Pozvedl jsem k nim svou ruku se slovy: Já jsem Hospodin, váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'V onen den jsem k nim pozvedl svou ruku, abych je vyvedl z egyptské země do země oplývající mlékem a medem, kterou jsem pro ně vyhlédl. ⌈Ona je ozdobou všech ostatních zemí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Nato jsem jim řekl: Odvrhněte každý ohavné modly od svých očí a neposkvrňujte se egyptskými bůžky. Já jsem Hospodin, váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Ale vzpírali se proti mně a nechtěli mě poslouchat, nikdo od svých očí ohavné modly neodvrhl a egyptské bůžky neopustili. Řekl jsem si tedy, že na ně vyliji svou zlobu, abych dovršil svůj hněv proti nim uprostřed egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Způsobil jsem však, aby mé jméno nebylo znesvěceno před zraky národů, uprostřed nichž byli, před jejichž zraky jsem se jim dal poznat, když jsem je vyvedl z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Vyvedl jsem je tedy z egyptské země a přivedl jsem je do pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Dal jsem jim svá ustanovení a oznámil jsem jim svá nařízení, ⌈v nichž bude mít člověk život, když je bude plnit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Dal jsem jim také své soboty, aby se staly znamením mezi mnou a jimi, aby poznali, že já Hospodin je posvěcuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Ale dům izraelský se proti mně v pustině vzpíral, nechodil podle mých ustanovení a pohrdl mými nařízeními, v nichž bude mít člověk život, když je bude plnit, i mé soboty velmi znesvětili. Řekl jsem si tedy, že na ně v pustině vyliji svou zlobu, abych s nimi skoncoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Způsobil jsem však, aby mé jméno nebylo znesvěceno před očima národů, před jejichž očima jsem je vyvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Já jsem k nim také v pustině pozvedl ruku, že je nepřivedu do té země, kterou jsem jim dal, do země oplývající mlékem a medem. Ona je ozdobou všech ostatních zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'To proto, že pohrdli mými nařízeními, nechodili podle mých ustanovení a znesvětili mé soboty, protože ⌈jejich srdce chodilo za jejich bůžky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Avšak mé oko se nad nimi slitovalo, takže jsem je nezničil a v pustině jsem s nimi neučinil konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Jejich synům jsem pak v pustině řekl: Podle ustanovení svých otců nechoďte, jejich nařízení nezachovávejte a jejich bůžky se neposkvrňujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Já jsem Hospodin, váš Bůh. Podle mých ustanovení choďte, má nařízení zachovávejte a plňte je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Svěťte mé soboty a budou znamením mezi mnou a vámi, abyste poznali, že já jsem Hospodin, váš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'I synové se proti mně vzpírali, nechodili podle mých ustanovení a nezachovávali má nařízení, aby je konali, ta, v nichž bude mít život člověk, když je bude plnit, a znesvětili mé soboty. Řekl jsem si tedy, že na ně vyliji svou zlobu, abych proti nim v pustině dovršil svůj hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Ale stáhl jsem svou ruku a učinil jsem tak, aby mé jméno nebylo znesvěceno před očima národů, před jejichž očima jsem je vyvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Já jsem k nim také v pustině pozvedl svou ruku, že je rozptýlím mezi národy a že je rozmetám po zemích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'jelikož neplnili má nařízení, pohrdli mými ustanoveními, znesvětili mé soboty a ohlíželi se za bůžky svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Já jsem jim tedy také dal nedobrá ustanovení a nařízení, v nichž nebudou mít život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'A znečistil jsem je s jejich dary, když prováděli ohněm vše otvírající lůno, ⌈abych v nich vzbudil úděs, aby poznali, že já jsem Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Proto promluv k domu izraelskému, lidský synu. Řekneš jim: Toto praví Panovník Hospodin: Ještě i tímto mě hanobili vaši otcové, když se proti mně zpronevěřili věrolomností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Přivedl jsem je do země, o které jsem pozvedl svou ruku, že jim ji dám, ale když viděli jakékoliv vyvýšené návrší a jakýkoliv košatý strom, obětovali tam své oběti a kladli tam své provokativní obětní dary, předkládali tam své příjemné vůně a vylévali tam své lité oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'I řekl jsem jim: Co je to za návrší, na které vcházíte? A nazývá se Návrší až do tohoto dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Proto řekni domu izraelskému: Toto praví Panovník Hospodin: ⌈Proč se znečišťujete po způsobu svých otců⌉ a smilníte s jejich ohavnými modlami?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Když přinášíte své dary, když provádíte své syny ohněm, znečišťujete se až dodnes před všemi svými bůžky. Dome izraelský, copak ⌈já vám dovolím, abyste se mě dotazovali?⌉ Jakože jsem živ, je výrok Panovníka Hospodina, uvidíme, jestli vám dovolím se dotazovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Co vám přichází na mysl, se opravdu nestane, když říkáte: ⌈Budeme jako národy, jako čeledi jiných zemí,⌉ takže budeme sloužit dřevu a kameni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Jakože jsem živ, je výrok Panovníka Hospodina, budu nad vámi kralovat silnou rukou, vztaženou paží a ve zlobě, kterou vyliji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'A vyvedu vás z národů a shromáždím vás ze zemí, do nichž jste byli rozptýleni silnou rukou, vztaženou paží a ve zlobě, kterou jsem vylil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, '⌈Přivedu vás do pustiny národů⌉ a budu se tam s vámi soudit tváří v tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Tak jako jsem se soudil s vašimi otci v pustině egyptské země, tak se budu soudit s vámi, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'A provedu vás pod holí a uvedu vás do závazku smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Budu však tříbit ty z vás, kdo se bouří a kdo jsou proti mně vzpurní. Vyvedu je ze země jejich dočasného pobytu, ale ⌈na izraelskou půdu nevejdou.⌉ I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'A vy, dome izraelský, toto praví Panovník Hospodin: ⌈Jděte, služte každý svým bůžkům i nadále, když mě neposloucháte,⌉ ale ⌈mé svaté jméno už neznesvěcujte⌉ svými dary a svými bůžky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Neboť na mé svaté hoře, vysoko na izraelské hoře, je výrok Panovníka Hospodina, tam mi budou sloužit, celý dům izraelský, každý v zemi. ⌈Tam v nich najdu zalíbení⌉ a tam ⌈budu vyhledávat vaše dary pozdvihování a prvotinu vašich darů ze všech vašich svatých věcí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Najdu ve vás zalíbení pro příjemnou vůni, až vás vyvedu z národů a shromáždím vás ze zemí, do nichž jste byli rozptýleni, a budu ve vás posvěcen před očima národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'I poznáte, že já jsem Hospodin, až vás přivedu na izraelskou půdu, do země, o které jsem pozvedl svou ruku, že ji dám vašim otcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Tam si vzpomenete na své cesty a na všechny své činy, jimiž jste se poskvrnili, a zhnusíte se sami sobě pro všechno to zlo, které jste spáchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Tu poznáte, že já jsem Hospodin, když s vámi pro své jméno naložím ne podle vašich zlých cest a podle vašich zkažených činů, dome izraelský, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Lidský synu, nastav svou tvář směrem k Témanu, kaž proti Dárómu a prorokuj proti lesu na poli Negebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Řekneš Negebskému lesu: Slyš Hospodinovo slovo: Toto praví Panovník Hospodin: Hle, roznítím v tobě oheň a stráví v tobě každý strom syrový i každý strom vyschlý. Plápolající plamen neuhasne a budou jím popáleny ⌈všechny tváře⌉ ⌈od jihu na sever.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Tehdy každé tělo uvidí, že jsem jej zapálil já, Hospodin, a neuhasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Tu jsem řekl: Ach, Panovníku Hospodine, ⌈oni mi říkají: Cožpak on nepředkládá pouze podobenství?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Lidský synu, nastav svou tvář proti Jeruzalému, kaž proti svatyním a prorokuj proti izraelské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Řekneš izraelské zemi: Toto praví Hospodin: Hle, jsem proti tobě, vytáhnu svůj meč z pochvy a ⌈vyhladím z tebe spravedlivého i ničemu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Kvůli tomu, abych z tebe vyhladil spravedlivého i ničemu, proto vyjde můj meč ze své pochvy na veškeré tělo od jihu na sever.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'I pozná, každé tělo, že já Hospodin jsem vytáhl svůj meč z pochvy; už se nevrátí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'A ty, lidský synu, vzdychej ⌈zlomený v bedrech.⌉ S hořekováním budeš vzdychat před jejich očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'I stane se, že se tě zeptají: Nad čím vzdycháš? Nato řekneš: Nad tím, že přichází zpráva. Ochabne každé srdce a klesnou všechny ruce, pohasne každý duch a všechna kolena ⌈se rozplynou jako voda.⌉ Hle, přichází a stane se to, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Lidský synu prorokuj. Řekneš: Toto praví Pán: Řekni: Meč, meč byl naostřen a také vyleštěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Byl naostřen, aby vykonal porážku, byl vyleštěn, aby měl lesk. Nebo ⌈budeme jásat nad žezlem mého syna, když meč každým stromem opovrhuje?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'I dal jej vyleštit, aby se dal uchopit do dlaně. Meč, ten byl naostřen a byl vyleštěn, aby jej dal do ruky katovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Volej o pomoc a naříkej, lidský synu, protože on byl určen proti mému lidu, je proti všem izraelským předákům. Byli vrženi na meč spolu s mým lidem, proto se bij v prsa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Vždyť byl přezkoušen. A co když ani žezlo, jímž meč opovrhuje, už nebude, je výrok Panovníka Hospodina?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'A ty, lidský synu, prorokuj a tleskej, ať se meč zopakuje dvakrát i třikrát; je to meč na probodené, velký meč na probodeného, kroužící kolem nich');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'kvůli tomu, aby kolísalo srdce a rozmnožila se pohoršení. Ve všech jejich branách jsem ustanovil zabíjení mečem. Ach, je připraven, aby měl lesk, vybroušen pro porážku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Soustřeď se, obrať se napravo, slož, obrať se nalevo, kde je žádána tvá přítomnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Já také zatleskám a ⌈zanechám své zloby.⌉ Já Hospodin jsem promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Ty pak, lidský synu, vyměř si dvě cesty, po nichž má přijít meč babylonského krále. Obě dvě vyjdou z jedné země. A vytvoř ukazatel, vytvoř ho na městské křižovatce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Vyměříš cestu, po které má přijít meč na Rabu synů Amónových a na Judu v opevněném Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Protože babylonský král se zastaví na rozcestí, na křižovatce dvou cest, aby získal věštbu; potřásal šípy, doptával se domácího bůžka, ⌈pohleděl do jater.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'V jeho pravici bude věštba o Jeruzalému, aby postavili válečné berany, aby vydali příkaz k zabíjení, aby pozvedli hlas k pokřiku, aby postavili válečné berany proti branám, aby navršili násep, aby vybudovali obléhací val.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'I bude to pro ně, jako když se věští klam. V jejich očích to vypadá tak, že s nimi přece byly složeny přísahy. ⌈On však připomene zvrácenost, aby mohli být pochytáni.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Proto praví Panovník Hospodin toto: Jelikož připomínáte svou zvrácenost tím, že se odhalují vaše přestoupení, aby se ukázaly vaše hříchy ve všech vašich činech, jelikož se připomínáte, budete chyceni za ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'A ty, znesvěcený ničemný izraelský předáku, jehož den přišel v době dovršení zvrácenosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'toto praví Panovník Hospodin: Sejmi turban a sundej korunu, ⌈takhle už to nebude;⌉ je na čase ⌈vyvýšit poníženého a ponížit vyvýšeného.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Sutiny, sutiny, v sutiny ji proměním. ⌈Ani ty ještě takové nebyly,⌉ až do ⌈příchodu toho, jemuž náleží soud -- já mu ho dám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, 'A ty, lidský synu, prorokuj. Řekneš: Toto praví Panovník Hospodin o synech Amónových a o jejich hanění. Řekneš: Meč, meč je tasen pro porážku, vyleštěn, aby hodně vydržel, aby měl lesk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, 'Když pro tebe vidí klam, když pro tebe věští lež, aby tě položili na probodené šíje ničemů, jejichž den přišel v době dovršení zvrácenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, 'Navrať ho zpět do jeho pochvy. Budu tě soudit na místě, kde jsi byla stvořena, dcero amónská, v zemi tvého původu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, 'A vyliji na tebe své rozhořčení, budu na tebe sálat ohněm své zuřivosti a vydám tě do ruky rozpálených mužů, řemeslníků zkázy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, 'Budeš pokrmem pro oheň, tvá krev spočine uprostřed země, nebudeš připomínána, protože já Hospodin jsem promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Ty pak, lidský synu, budeš soudit? Budeš soudit ⌈město prolévající krev?⌉ Poučíš ho o všech jeho ohavnostech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Řekneš: Toto praví Panovník Hospodin: Město, které prolévá krev ve svém středu, aby přišel jeho čas, a zhotoví samo proti sobě bůžky, aby se poskvrňovalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Svou krví, kterou jsi prolilo, ses provinilo, a svými bůžky, které jsi zhotovilo, ses poskvrnilo, přivedlo jsi blíž své dny a přišlo jsi do svých let. Kvůli tomu jsem tě učinil předmětem potupy pro národy a posměchu pro všechny země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Ty, které jsou ti blízko, i ty, které jsou od tebe daleko, se ti budou posmívat: To nečisté jméno, ten velký zmatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Hle, izraelští předáci, každý ⌈podle toho, jakou měl moc, byli pohotoví prolévat v tobě krev.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Otce a matku v tobě znevážili, příchozímu uprostřed tebe působili útlak, sirotka a vdovu v tobě utiskovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Pohrdlo jsi mými svatými věcmi a znesvětilo jsi mé soboty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Byli v tobě pomlouvači připravení prolévat krev a hodovali v tobě na horách. Páchali uprostřed tebe hanebnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Syn v tobě odhalil nahotu otce, ponížili v tobě nečistou v době menstruace.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Někdo spáchal ohavnost se ženou svého bližního, jiný znečistil hanebností svou snachu a další v tobě ponížil svou sestru, dceru svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Přijímali v tobě úplatek, aby prolévali krev, bralo jsi lichvu a úrok, odíralo jsi své bližní útlakem a na mě jsi zapomnělo, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'A hle, ⌈zatleskal jsem nad tvým nekalým ziskem, který jsi nahromadilo, a nad tvou krví, která byla⌉ uprostřed tebe prolita.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Jestlipak obstojí tvé srdce, zdalipak budou pevné tvé ruce ve dnech, kdy s tebou budu jednat? ⌈Já Hospodin jsem promluvil a také to vykonám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Rozptýlím tě mezi národy, rozmetám tě po zemích a ⌈odstraním z tebe tvou nečistotu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Znesvěcuješ se samo před očima národů. I poznáš, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Lidský synu, dům izraelský se pro mě stal struskou. Stali se všichni mědí a cínem, železem a olovem uprostřed pece, struskou ze stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Proto praví Panovník Hospodin toto: Jelikož vy všichni jste se stali struskami, proto hle, shromažďuji vás doprostřed Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Stříbro, měď a železo, olovo a cín je shromážděn doprostřed pece, aby na něho dmýchal oheň, aby tavil. Tak vás shromáždím ve svém hněvu a ve své zlobě, uložím vás do pece a budu vás tavit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Shrnu vás, budu na vás dmýchat ohněm své zuřivosti a budete se tavit uprostřed něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Jako probíhá tavení stříbra uprostřed pece, tak budete roztaveni uprostřed něj a poznáte, že já Hospodin jsem na vás vylil svou zlobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Lidský synu, řekni jí: Ty jsi neočištěná země. Ta nebyla skropena deštěm v den rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Uprostřed ní je spiknutí jejích proroků, jako když řvoucí lev sápe kořist. Pohltili duši, vezmou bohatství a každou drahocennou věc, rozmnožili uprostřed ní počet jejích vdov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Její kněží znásilnili můj zákon a znesvěcovali mé svaté věci, ⌈nerozlišovali mezi svatým a obyčejným, nepoučili o rozdílu mezi nečistým a čistým⌉ a ⌈zavírali oči před mými sobotami,⌉ a tak jsem byl uprostřed nich znesvěcován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Její knížata uprostřed ní sápou kořist jako vlci, když prolévají krev, když hubí duše, aby pro sebe hrabali nekalý zisk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'A její proroci jim to omítali omítkou, když ⌈viděli klam a věštili pro ně lež. Říkají: Toto praví Panovník Hospodin, a Hospodin přitom nepromluvil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Lid země se dopouštěl útlaku, uchvátili lup, utiskovali chudého a nuzného a bezprávně utlačovali příchozího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, '⌈I hledal jsem mezi nimi muže, který by stavěl zeď a postavil se za tu zemi před mou tvář do trhliny, abych ji nezničil,⌉ ale nenalezl jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Vylil jsem tedy na ně své rozhořčení, skoncoval jsem s nimi ohněm své zuřivosti, ⌈uvalil jsem jejich cestu na jejich hlavu,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Lidský synu, dvě ženy byly dcerami jedné matky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, '⌈Smilnily v Egyptě,⌉ smilnily ve svém mládí. Tam byly mačkány jejich prsy a tam ohmatávali ⌈jejich panenské bradavky.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Jmenovaly se: Starší Ohola a její sestra Oholíba. Byly mé a rodily syny a dcery. Jejich jména znamenají: Ohola Samaří a Oholíba Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ohola smilnila, ⌈místo aby byla má,⌉ a vášnivě toužila po svých milencích, po blízkých Asyřanech');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'oděných rouchy z modré látky, po ⌈místodržitelích a správcích,⌉ samých překrásných mládencích, jezdcích jezdících na koních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Jim, všem nejlepším asyrským synům, dopřávala své smilnění a poskvrnila se se všemi, po kterých vášnivě toužila, se všemi jejich bůžky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Ani svého smilnění z dob Egypta nezanechala, protože tam s ní leželi v jejím mládí; oni ohmatávali její panenské bradavky a vylévali na ni své smilnění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Proto jsem ji vydal do ruky jejích milenců, do ruky asyrských synů, po nichž vášnivě toužila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, '⌈Oni odhalili její nahotu,⌉ vzali její syny i její dcery a ji zabili mečem. Mezi ženami se stala pojmem a ⌈vykonali nad ní přísné soudy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Její sestra Oholíba to viděla, a přece se vrhala svou vášní do zkázy více než ona a její smilnění bylo větší než smilstva její sestry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Vášnivě toužila po asyrských synech, blízkých místodržitelích a správcích dokonale oblečených, jezdcích jezdících na koních, samých překrásných mládencích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'I viděl jsem, že se poskvrnila. ⌈Obě šly stejnou cestou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Pokračovala dále ve svém smilnění a viděla muže vyryté na zdi, obrazy Chaldejců provedené ⌈červenou barvou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Byli přepásáni ⌈na bedrech pásem,⌉ na hlavách převislé turbany -- všichni měli vzhled osádky válečného vozu, podobní babylonským synům, jejichž rodištěm je chaldejská země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Vášnivě po nich toužila, ⌈když je její oči spatřily,⌉ a posílala k nim do Chaldejska posly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Tehdy k ní babylonští synové vstoupili na lože něžností a znečistili ji svým smilněním. Poskvrnila se s nimi a její duše se od nich odvrátila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Odhalila své smilnění, odhalila i svou nahotu a ⌈má duše se od ní odvrátila,⌉ tak jako se má duše odcizila od její sestry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Rozmnožila své smilnění, když vzpomínala na dny svého mládí, kdy smilnila v egyptské zemi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'a vášnivě toužila po tehdejších záletnících, jichž úd je jako úd oslů a jejichž výron je jako výron koní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'I hledala jsi hanebnost svého mládí, kdy si muži z Egypta užívali bradavek ⌈na tvých mladých prsech.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Proto, Oholíbo, toto praví Panovník Hospodin: Hle, já proti tobě podnítím tvé milence, od nichž se odcizila tvá duše, a přivedu je na tebe z okolí:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, '⌈Babylonské syny a všechny Chaldejce,⌉ Pekóda, Šóu a Kóu, s nimi všechny asyrské syny, překrásné mládence, samé místodržitele a správce, samé osádky válečných vozů a vyhlášené jezdce na koních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Přitáhnou na tebe s válečnou vozbou i povozy a ve shromáždění národů položí proti tobě dokola ⌈velké i malé štíty a přilby.⌉ Vydám před nimi rozsudek a budou tě soudit ⌈podle svých právních nařízení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Dám na tobě průchod své žárlivosti. Naloží s tebou v zlobě: ⌈Uřežou ti nos a uši⌉ a tvůj ostatek padne mečem. Oni vezmou tvé syny a tvé dcery a tvůj ostatek bude stráven ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Svléknou tvá roucha a seberou tvé ozdobné předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Odklidím totiž od tebe tvou hanebnost a tvé smilstvo z egyptské země; už k nim nepozvedneš své oči a na Egypt si nevzpomeneš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Neboť toto praví Panovník Hospodin: Hle, vydám tě do ruky těch, které jsi nenáviděla, do ruky těch, od kterých se odcizila tvá duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Naloží s tebou v nenávisti a poberou všechen tvůj výtěžek, ⌈zanechají tě obnaženou a nahou a ukáže se hanba tvých záletů, tvá hanebnost a tvé smilnění.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Tyto věci na tobě budou páchat, protože jsi chodila smilnit podle způsobu národů, přičemž ses poskvrňovala s jejich bůžky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Šla jsi cestou své sestry, dám ti tedy do ruky její kalich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Toto praví Panovník Hospodin: Budeš pít kalich své sestry, bude hluboký a široký, aby pojal množství nápoje k zesměšňování a k výsměchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Opilostí a žalem budeš naplněna, kalichem hrůzy a úděsu, kalichem své sestry Samaří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Budeš pít a ⌈vypiješ jej do dna,⌉ rozhryžeš jeho střepy a ⌈rozdrásáš si prsy,⌉ protože já jsem promluvil, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Proto praví Panovník Hospodin toto: Jelikož jsi na mě zapomněla a odvrhla jsi mě za svá záda, nes i ty svou hanebnost a své smilnění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'I řekl mi Hospodin: Lidský synu, budeš soudit Oholu a Oholíbu? ⌈Oznam jim jejich ohavnosti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Neboť cizoložily a na jejich rukou je krev. Cizoložily se svými bůžky a dokonce své syny, které mi porodily, jim ⌈přivedly za pokrm.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Ještě toto mi provedly: V onen den znečistily mou svatyni a ⌈znesvětily mé soboty.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Když pobíjeli své syny pro své bůžky, v onen den přišli do mé svatyně, aby ji znesvětili. Hle, toto spáchali uprostřed mého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Nadto však budou posílat pro muže přicházející zdaleka. Když k nim byl poslán posel, hle, přišli. Umyla ses pro ně, ⌈nalíčila sis oči⌉ a ozdobila ses ozdobou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Posadila ses na drahocenné lůžko, před ním byl prostřený stůl a na něj jsi postavila mé kadidlo a můj olej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Hlas spokojeného davu zněl ve městě, naproti mužům z množství lidí, pijanům přivedeným z pustiny. I dávali jim náramky na ruce a krásnou korunu na hlavy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'I řekl jsem o ní, opotřebované cizoložstvím: Teď s ní budou páchat smilnění a ona s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'A vcházel k ní, jako se vchází k prostitutce. Tak vcházeli k Ohole a k Oholíbě, hanebným ženám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Avšak spravedliví muži, ⌈ti je budou soudit soudem pro cizoložnice a soudem pro ty, které prolévají krev,⌉ protože jsou cizoložnice a mají na rukou krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Neboť toto praví Panovník Hospodin: ⌈Svolej proti nim shromáždění a vydej je úděsu a loupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Shromáždění pak na ně bude házet kamení a vymýtí je svými meči.⌉ Jejich syny i jejich dcery zabijí a jejich domy spálí ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Odstraním ze země hanebnost, všechny ženy se dají varovat a nebudou jednat podle vaší hanebnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Uvalí na vás vaši hanebnost a ponesete hříchy smilnění se svými bůžky. I poznáte, že já jsem Panovník Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'I stalo se ke mně Hospodinovo slovo v devátém roce v desátém měsíci, desátého dne toho měsíce:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Lidský synu, zapiš si jméno dne, právě tohoto dne. Babylonský král právě v tento den oblehl Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Užij pro dům vzpoury podobenství. Řekneš jim: Toto praví Panovník Hospodin: Postav hrnec, postav, a také do něj nalij vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Shromáždi do něj díly masa, všechny dobré díly, bok i rameno, naplň ho vybranými kostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Potom vezmi vybranou ovci a kosti narovnej také pod ni. Nech ji vřít varem, aby se v tom uvařily i ty kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Proto praví Panovník Hospodin toto: Běda městu prolévajícímu krev, hrnci, v němž je připálenina a jehož připálenina z něj nebyla odstraněna. Vybírej ho, ⌈díl po dílu;⌉ ⌈nepadl pro něho los.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Neboť jeho krev zůstala uprostřed něho, uvedlo ji na holou skálu, nevylilo ji na zem, aby ji zakryl prach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Abych vyvolal zlobu, abych vykonal pomstu, nechal jsem jeho krev na holé skále, aby nebyla zakryta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Proto praví Panovník Hospodin toto: Běda městu, ve kterém byla prolita krev. Také já udělám velkou hranici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Nadělej spoustu dříví, zapal oheň, abys dovařil maso a vmísil koření. I kosti se připálí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'A postav ho prázdný na žhavé uhlíky, aby se zahřál a rozpálil se jeho bronz, až se bude uprostřed něj tavit jeho nečistota, bude se oddělovat jeho připálenina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Unavil mé usilovné snahy, nevyjde z něj mnoho jeho připáleniny. Jeho připálenina zůstává i v ohni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'V tvé nečistotě je hanebnost. ⌈Ačkoliv jsem tě očišťoval, nezbavilo ses své nečistoty.⌉ Budeš stále nečisté, ⌈dokud nedopřeji odpočinutí své zlobě proti tobě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Já Hospodin jsem promluvil. Přichází to a já budu jednat. Nebudu nevšímavý, nebudu mít lítost a neslituji se. Podle tvých cest a podle tvých činů tě odsoudili, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Lidský synu, hle, náhlou ranou ti beru to, co je vzácné tvým očím, ale nebudeš bědovat ani se nerozpláčeš a ⌈neskanou ti slzy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Sténej potichu, nebudeš konat smuteční obřad za mrtvé. Oviň si turban. A na nohy si vezmeš sandály, nebudeš si zakrývat vous a nebudeš jíst chléb truchlících mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Ráno jsem tedy promluvil k lidu a večer zemřela moje žena. Ráno jsem pak jednal, jak mi bylo přikázáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'A lid se mě ptal: Cožpak nám neoznámíš, co to pro nás znamená, že takto jednáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Nato jsem jim řekl: Stalo se ke mně slovo Hospodinovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Řekni domu izraelskému: Toto praví Panovník Hospodin: Hle, já znesvěcuji svou svatyni, ⌈vaši mocnou pýchu,⌉ to, co je vzácné vašim očím, a slast vaší duše. Vaši synové a vaše dcery, které jste zanechali, padnou mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Potom budete jednat tak, jako jsem jednal já. Nebudete si zakrývat vous a nebudete jíst chléb truchlících mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Vaše turbany budou na vašich hlavách a vaše sandály na vašich nohách. Nebudete bědovat ani se nerozpláčete. Pro svou zvrácenost budete chřadnout a úpět jeden s druhým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Tak se pro vás Ezechiel stane znamením. Uděláte vše, jako to udělal on. Až to přijde, poznáte, že já jsem Panovník Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'A ty, lidský synu, cožpak v den, kdy od nich vezmu jejich záštitu, jejich slavnou radost, to, co je vzácné jejich očím, a to, po čem jejich duše touží, jejich syny a jejich dcery,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'nepřijde k tobě v onen den ten, kdo unikl, aby předal uším zprávu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'V onen den budou uvolněna tvá ústa v přítomnosti toho, kdo unikl. Promluvíš a nebudeš již němý a staneš se pro ně znamením. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Lidský synu, nastav svou tvář proti synům Amónovým a prorokuj proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Řekneš synům Amónovým: Slyšte slovo Panovníka Hospodina. Toto praví Panovník Hospodin: Jelikož říkáš: Výborně! o mé svatyni, že byla znesvěcena, a o izraelské zemi, že byla zpustošena, a o domu judském, že odešli do vyhnanství,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'proto hle, dávám tě za vlastnictví synům východu a ti v tobě osídlí svá hradiště a postaví si v tobě své příbytky. Ti budou jíst tvé ovoce, ti budou pít tvé mléko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Rabu dám za pastvinu velbloudům a syny Amónovy za ležení ovcím. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Panovník Hospodin totiž praví toto: Jelikož jsi tleskal rukou, dupal jsi nohou a se vším opovržením ses z duše radoval nad izraelskou zemí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'proto hle, já vztáhnu proti tobě ruku a dám tě za lup národům. Vyhladím tě z národů a vyhubím tě ze zemí. Zničím tě. I poznáš, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Toto praví Panovník Hospodin: Jelikož Moáb a Seír říkají: Hle, dům judský je jako všechny národy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'proto hle, já odkrývám moábské úbočí od měst, jeho měst od jeho okraje -- nádheru země, Bét–ješimót, Baal–meón až do Kirjatajimu --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'pro syny východu, spolu se syny Amónovými, a dám jim to do vlastnictví, aby se na syny Amónovy mezi národy nevzpomínalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'I nad Moábem vykonám soudy. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Toto praví Panovník Hospodin: Kvůli tomu, co prováděl Edóm, když nad domem judským konal pomstu -- těžce se provinili a mstili se jim --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'proto praví Panovník Hospodin toto: Vztáhnu tedy svou ruku proti Edómu, vyhladím z něj člověka i zvíře a proměním ho v trosky. Od Témanu po Dedán padnou mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Svou pomstu nad Edómem vložím do ruky svého lidu Izraele. Budou v Edómu jednat podle mého hněvu a podle mé zloby. I poznají mou pomstu, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Toto praví Panovník Hospodin: Kvůli tomu, co prováděli Pelištejci při pomstě -- konali pomstu s opovržením v duši, aby pro odvěké nepřátelství přinesli zkázu --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'proto praví Panovník Hospodin toto: Hle, vztáhnu svou ruku na Pelištejce, vyhladím Keretejce a vyhubím ostatek z mořského pobřeží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Vykonám nad nimi velkou pomstu hněvivým trestáním. I poznají, že já jsem Hospodin, až na nich dám průchod své pomstě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'I stalo se v jedenáctém roce prvního dne v měsíci; stalo se ke mně slovo Hospodinovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Lidský synu, kvůli tomu, že Týr řekl o Jeruzalému: Výborně!, vrata k národům byla rozdrcena, byl předán mně, naplním se, když je v troskách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'proto praví Panovník Hospodin toto: Hle, jsem proti tobě, Týre, a ⌈přivedu na tebe mnohé národy, jako moře přivádí své vlny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Tehdy zničí hradby Týru a zboří jeho věže. Pak z něj vymetu prach a proměním jej v holou skálu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Stane se místem k rozprostírání sítí uprostřed moře, protože já jsem promluvil, je výrok Panovníka Hospodina. Bude za lup národům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'A jeho vesnice, které jsou v krajině, budou vybíjeny mečem. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Neboť toto praví Panovník Hospodin: Hle, přivádím na Týr od severu babylonského krále Nebúkadnesara, krále králů, s koňmi, s vozbou a s jezdci, shromáždění a početný lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Tvé vesnice v krajině vybije mečem, položí proti tobě obléhací val, navrší proti tobě násep a postaví proti tobě obléhací věž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Potom dá svým obléhacím strojem úder do tvých hradeb a tvé věže strhne svými zbraněmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Od spousty jeho koní tě přikryje prach, od vřavy jezdců, povozů a vozby se budou třást tvé hradby, až bude on vcházet do tvých bran jako do průchodů dobytého města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Kopyty svých koní pošlape všechny tvé ulice, tvůj lid vybije mečem a posvátné sloupy tvé moci klesnou na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Vyplení tvůj majetek a uloupí tvé zboží, zboří tvé hradby a tvé výborné domy strhnou, tvé kameny a tvé stromy i tvou hlínu svrhnou doprostřed vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Tak způsobím, že zmizí halas tvých písní a zvuk tvých lyr již nebude slyšet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Proměním tě v holou skálu, staneš se místem k rozprostírání sítí, nebudeš znovu vybudován, protože já Hospodin jsem promluvil, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Toto praví Panovník Hospodin o Týru: Nebudou se snad třást ostrovy zvukem tvého pádu, až budou sténat pobití, až bude ve tvém středu pácháno vraždění?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Tu sestoupí ze svých trůnů všechna knížata západu, sundají své pláště a svléknou svá pestře utkaná roucha, oblečou se do hrůz, posadí se na zem, ⌈budou se neustále třást⌉ a zhrozí se nad tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'I pozvednou nad tebou žalozpěv a řeknou ti: Jak to, že jsi zmizel, ty obydlený od moří, vychvalované město, které bylo silné na moři, ono i jeho obyvatelé, kteří uváděli svůj děs na všechny jeho obyvatele?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Teď se ostrovy třesou dnem tvého pádu a ostrovy, které jsou v moři, se děsí nad tvým odchodem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Neboť toto praví Panovník Hospodin: Až tě učiním městem v troskách jako města, která nebyla obydlena, až ⌈na tebe vyvedu hlubinu a přikryjí tě mnohé vody,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'svrhnu tě spolu s těmi, kdo sestupují do jámy, k dávnému lidu a usídlím tě v útrobách země jako odvěké trosky s těmi, kdo sestupují do jámy, abys nebyl obydlený. I prokáži slávu v zemi živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Dám tě za výstrahu a nebude tě více, budou tě hledat, ale už tě nikdy nenajdou, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'A ty, lidský synu, pozvedni nad Týrem žalozpěv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Řekneš o Týru, který sídlí nad mořskými vchody, o ⌈prodejci národů⌉ pro mnohé ostrovy: Toto praví Panovník Hospodin: Týre, ty jsi řekl: Já jsem dokonalá krása.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Tvé hranice jsou uprostřed moří, tví stavitelé dovedli tvou krásu k dokonalosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Použili pro tebe cypřiše ze Seníru k vyrobení všech prken, vzali cedr z Libanonu, aby na tebe zhotovili stěžeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Z bášanských dubů udělali tvá vesla, tvé desky udělali ze slonoviny a cypřiše z kitejských ostrovů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Jemné pestře utkané plátno z Egypta bylo tvým plachtovím, aby ti bylo za korouhev, modrá a purpurová látka z Elíšských ostrovů se stala tvým přikrytím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Obyvatelé Sidónu a Arvadu ti byli za veslaře, tví znalci, Týre, kteří v tobě byli, byli tvými lodníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Starší Gebalu a jeho znalci byli v tobě ⌈těmi, kdo utěsňovali tvé spáry.⌉ Všechny mořské lodě a jejich námořníci v tobě přebývali, aby obchodovali s tvým směnným zbožím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Ve tvém vojsku byli Peršané, Lúďané a Pútejci tvými bojovníky; zavěsili v tobě štít a přilbu. Oni ti dodávali důstojnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Synové Arvadu a tvé vojsko byli dokola na tvých hradbách a Gamáďané v tvých věžích; své štíty zavěsili okolo na tvé hradby. Oni dovedli k dokonalosti tvou krásu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Taršíš byl tvým obchodním partnerem díky množství všelijakého majetku. Poskytovali tvému zboží odbyt za stříbro, železo, cín a olovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Jávan, ⌈Túbal a Mešek⌉ byli tvými prodejci. Za lidské duše a bronzové nádoby dodávali tvé směnné zboží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Z Bét–togarmy ⌈dodávali tvým tržištím⌉ tažné koně, jezdecké koně a mezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Synové Dedánu byli tvými prodejci, mnohé ostrovy ti byly k ruce jako překupníci; odváděli ti tribut v sloních klech a ebenovém dřevu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Aram byl tvým obchodním partnerem díky množství tvých výrobků. Poskytovali pro tvé zboží odbyt za malachit a purpur, pestře utkané šaty a mořské hedvábí, perly a rubín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Judsko a izraelská země byli tvými prodejci. Za minítskou pšenici a proso, med, olej a balzám dodávali tvé směnné zboží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damašek byl tvým obchodním partnerem pro množství tvých výrobků; díky množství všelijakého majetku je směňoval za chelbónské víno a sacharskou vlnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedan a Jávan z Úzalu dodávali na tvá tržiště opracované železo, kasii a třtinu; bylo to za tvé směnné zboží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedán byl prodejcem tvého zboží za sedlové pokrývky pro jízdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, '⌈Arabové a všechna knížata Kédaru⌉ byli ⌈tvými obchodními příručími⌉ za jehňata, berany a kozly; v tom byli tvými obchodními partnery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Prodejci ze Šeby a Raemy byli prodejci tvého zboží za ⌈všelijaké nejlepší balzámy⌉ a poskytovali odbyt tvému zboží za všelijaké drahokamy a zlato.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Cháran, Kané a Eden, prodejci Šeby, Ašúru a Kilmadu byli tvými prodejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Na tvém trhu byli prodejci tvého zboží za prvotřídní roucha, modré i pestře utkané pláště a za poklady dvoubarevných tkanin, s kroucenými a pevnými provazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Taršíšské lodě byly karavanami s tvým směnným zbožím. Byl jsi naplněn bohatstvím a byl jsi velmi vážený uprostřed moří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Tví veslaři tě přivedli do mnohých vod; východní vítr tě rozbil uprostřed moří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Tvůj majetek a tvá tržiště, tvé směnné zboží, tví námořníci a tví lodníci, ti, kdo utěsňují tvé spáry a obchodují s tvým směnným zbožím a všichni tví bojovníci, kteří jsou v tobě a v celém tvém shromáždění, které je ve tvém středu, padnou uprostřed moří v den tvého pádu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Pastviny se otřesou, až zazní hlasité volání tvých lodníků o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Tu vystoupí ze svých lodí všichni, kteří se chápou vesla, námořníci a všichni mořští lodníci budou stát na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Zazní nad tebou jejich hlas, hořce budou volat o pomoc a budou si házet prach nad hlavu, ⌈v popelu se budou válet.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Vyholí si kvůli tobě lysinu, přepásají se pytlovinou a budou pro tebe plakat v hořkosti duše hořkým kvílením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Při svém bědování pozvednou za tebe žalozpěv a zazpívají nad tebou: Kdo byl jako Týr, jako zničený uprostřed moře?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Když díky mořím vzkvétal odbyt tvého zboží, nasytil jsi mnohé národy ⌈množstvím svého majetku a svým směnným zbožím⌉ jsi obohacoval krále země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Nyní jsi díky mořím rozlomen v hloubkách vod, tvé směnné zboží a celé tvé shromáždění ve tvém středu padlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Všichni obyvatelé ostrovů se nad tebou zhrozili a jejich králové se zděsili, hrůzou křivili tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Obchodníci mezi národy se nad tebou podivili, stal ses výstrahou a už navěky nebudeš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Lidský synu, řekni předákovi Týru: Toto praví Panovník Hospodin: Jelikož se tvé srdce povýšilo a řekl jsi: Jsem bůh, obydlil jsem božské sídlo uprostřed moří -- ale jsi člověk, a ne bůh a vydával jsi své srdce za srdce božské --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'hle, jsi moudřejší než Daniel, nic tajného ti neuniklo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Svou moudrostí a svou rozumností jsi pro sebe získal majetek, získal jsi i zlato a stříbro do svých pokladnic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Dík množství své moudrosti jsi ⌈obchodováním rozmnožil svůj majetek⌉ a ⌈tvé srdce se kvůli tvému majetku povýšilo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Proto praví Panovník Hospodin toto: Jelikož vydáváš své srdce za srdce božské,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'proto hle, já na tebe přivedu cizince, násilnické národy. Vytasí meč na tvoji krásnou moudrost a znesvětí tvou skvělost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Svrhnou tě do jámy a zemřeš smrtelně raněn uprostřed moří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Opravdu budeš říkat: Jsem bůh, před svým katem? Jsi člověk, a ne bůh v ruce těch, kdo tě ubijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Zemřeš smrtí neobřezanců v ruce cizinců, protože já jsem promluvil, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Lidský synu, pozvedni žalozpěv nad týrským králem. Řekneš mu: Toto praví Panovník Hospodin: Ty pečetíš vzor plné moudrosti a dokonalé krásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Byl jsi v Edenu, Boží zahradě, pokrývaly tě ⌈všechny drahokamy:⌉ ⌈rubín, topas a jaspis, chryzolit, karneol a onyx, safír, malachit a smaragd i zlato.⌉ Zhotovení tvých bubínků a fléten pro tebe zajistili v den, kdy jsi byl stvořen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Ty jsi byl zastírající cherub ochránce a tak jsem tě ustanovil, byl jsi na svaté Boží hoře, procházel ses uprostřed ohnivých kamenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Byl jsi bezúhonný na svých cestách ode dne, kdy jsi byl stvořen, dokud v tobě nebyla nalezena zvrácenost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Pro množství tvého obchodování se tvé nitro naplnilo násilím a zhřešil jsi. Tu jsem tě zbavil svatosti a vykázal z Boží hory a vyhladil jsem tě, zastírající cherube, zprostřed ohnivých kamenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Tvé srdce se povýšilo kvůli tvé kráse, promarnil jsi svou moudrost pro svou skvělost. Svrhl jsem tě na zem před krále, dal jsem tě, aby se na tebe dívali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Pro množství svých zvráceností jsi špatností svého obchodování znesvětil své svatyně. I vyvedl jsem z tvého středu oheň a ten tě strávil, proměnil jsem tě v popel na zemi před očima všech, kteří tě vidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Všichni mezi národy, kdo tě znají, se nad tebou zhrozili, ⌈stal ses výstrahou a už navěky nebudeš.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Lidský synu, nastav svou tvář proti Sidónu a prorokuj proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Řekneš: Toto praví Panovník Hospodin: Hle, jsem proti tobě, Sidóne, a oslavím se uprostřed tebe. I poznají, že já jsem Hospodin, až nad ním vykonám soudy a posvětím se v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Pošlu na něho ⌈mor a krev⌉ do jeho ulic, ⌈pobití padnou⌉ uprostřed něj, mečem na něj dolehnu ze všech stran. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Pak už nebude Sidón pro dům izraelský zhoubným trnem a trním působícím bolest všude kolem, těmi, kdo jím opovrhují. I poznají, že já jsem Panovník Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Toto praví Panovník Hospodin: Až shromáždím dům izraelský z národů, do nichž byli rozptýleni, a posvětím se mezi nimi před očima těch národů, budou bydlet na své půdě, kterou jsem dal svému otroku Jákobovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Budou na ní bydlet v bezpečí, ⌈postaví domy a vysadí vinice.⌉ Budou bydlet v bezpečí, až vykonám soudy nade všemi z jejich okolí, kteří jimi opovrhují. I poznají, že já jsem Hospodin, jejich Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'V desátém roce v desátém měsíci, dvanáctého dne toho měsíce se ke mně stalo Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Lidský synu, nastav svou tvář proti faraonovi, egyptskému králi, a prorokuj proti němu a proti celému Egyptu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Promluv a řekni: Toto praví Panovník Hospodin: Hle, jsem proti tobě, faraone, egyptský králi, ty velký draku, odpočívající uprostřed svých řek, který říkáš: Můj Nil patří mně, já jsem si ho udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Dám kruhy do tvých čelistí, ryby tvých řek nechám přilnout ke tvým šupinám a vytáhnu tě zprostřed tvých řek; se všemi rybami tvých řek, které přilnou ke tvým šupinám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Odvrhnu tě do pustiny, tebe i každou rybu tvých řek. Padneš na povrch pole, ⌈nebudeš sebrán ani nebudeš shromážděn.⌉ ⌈Dám tě za pokrm zemské zvěři a nebeskému ptactvu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'I poznají všichni obyvatelé Egypta, že já jsem Hospodin, jelikož ⌈byli pro dům izraelský jako třtinová hůl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Když tě uchopí za dlaň, rozštípneš se a pronikneš celým jejich ramenem, a když se o tebe opřou, zlomíš se a ⌈necháš je ležet na zádech.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Proto praví Panovník Hospodin toto: Hle, přivedu na tebe meč a vyhladím z tebe člověka i zvíře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Egyptská země se stane spouští a troskami. I poznají, že já jsem Hospodin, jelikož faraon řekl: Nil patří mně, já jsem ho udělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Proto hle, jsem proti tobě a proti tvým řekám a proměním egyptskou zemi v trosky, sucho a spoušť ⌈od Migdólu po Sevénu⌉ a až k hranici Kúše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Nebude přes ni procházet lidská noha ani ⌈zvířecí noha přes ni nebude procházet⌉ a nebude obydlena po čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Proměním egyptskou zemi ve spoušť mezi zpustošenými zeměmi a její města budou mezi zničenými městy spouští čtyřicet let, ⌈rozptýlím Egypťany mezi národy a rozmetám je po zemích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Neboť toto praví Panovník Hospodin: Po čtyřiceti letech ⌈shromáždím Egypťany z národů, do nichž byli rozptýleni.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Pak změním úděl Egypta, přivedu je zpět do země Patrósu, do země jejich původu, a stanou se tam poníženým královstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Bude to nejponíženější z království a nebude se už povznášet nad národy. Umenším je, aby nepanovali mezi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'A nebude už pro dům izraelský nadějí připomínající zvrácenost, že se kdysi za nimi obracel. I poznají, že já jsem Panovník Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'I stalo se v dvacátém sedmém roce v prvním měsíci, prvního dne toho měsíce; stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Lidský synu, babylonský král Nebúkadnesar nutil své vojsko sloužit těžkou službou proti Týru. Každá hlava olysala a každé rameno je odřeno, ale z Týru neměl mzdu ani on, ani jeho vojsko za službu, kterou proti němu vykonalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Proto praví Panovník Hospodin toto: Hle, ⌈já dávám babylonskému králi Nebúkadnesarovi egyptskou zemi.⌉ Odnese její bohatství, ⌈ukořistí její kořist a uloupí její lup,⌉ a tak se jeho vojsku dostane mzdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Jako jeho odměnu, za niž sloužil, jsem mu dal egyptskou zemi, neboť pracovali pro mě, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'V onen den způsobím, aby domu izraelskému vyrostl roh a tobě mezi nimi otevřu ústa. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Lidský synu, prorokuj a řekni: Toto praví Panovník Hospodin: Naříkejte: Ach, ten den,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'neboť ⌈blízko je den,⌉ blízko je den Hospodinův, den mračna, nastane čas národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Na Egypt přijde meč a v Kúši bude úzkost, až v Egyptě padnou pobití, poberou jeho bohatství a jeho základy budou zbořeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Kúš, ⌈Pút a Lúd,⌉ ⌈všechen míšený lid,⌉ Kúb i synové země smlouvy s nimi padnou mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Toto praví Hospodin: Padnou ti, kdo podpírají Egypt, a klesne jeho mocná pýcha. ⌈Od Migdólu po Sevénu⌉ v něm padnou mečem, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Budou zpustošeni mezi zpustošenými zeměmi a jeho města budou mezi městy v troskách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'I poznají, že já jsem Hospodin, až založím v Egyptě oheň a všichni jeho pomocníci budou rozdrceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'V onen den ode mne vyplují poslové na lodích, aby vyděsili bezstarostný Kúš, a v den Egypta bude mezi nimi úzkost; neboť hle, již přichází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Toto praví Panovník Hospodin: Odklidím egyptský dav ⌈rukou babylonského krále Nebúkadnesara.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'On a s ním jeho lid, ⌈násilnické národy, přivedené, aby ničily zemi, vytasí své meče⌉ na Egypt a naplní zemi pobitými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Proměním řeky v suchou zemi a vydám tu zemi do ruky zlých lidí, zpustoším zemi i všechno, co ji naplňuje, rukou cizinců. Já Hospodin jsem promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Toto praví Panovník Hospodin: ⌈Odstraním bůžky a odklidím nicotnosti⌉ z Memfidy, ⌈z egyptské země již nevzejde kníže.⌉ ⌈Do egyptské země uvedu bázeň.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Zpustoším Patrós, v Sóanu založím oheň a nad Thébami vykonám soudy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Vyliji svou zlobu na Sín, záštitu Egypta, a vyhladím dav z Théb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Založím oheň v Egyptě, Sín se bude svíjet hroznou bolestí, Théby budou rozpolceny a Memfidu napadnou protivníci za bílého dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Mládenci Ávenu a Pí–besetu padnou mečem a ta města půjdou do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'V Tachpanchésu se zatmí ten den, až tam zlomím egyptské jho. I bude z něj odklizena jeho mocná pýcha. Jej samého přikryje oblak a jeho dcery půjdou do zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Vykonám nad Egyptem soudy. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'I stalo se v jedenáctém roce v prvním měsíci, sedmého dne toho měsíce; stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Lidský synu, zlomil jsem paži faraona, egyptského krále, a hle, nebyla obvázána, tak že by podali léky, že by přiložili dlahu, že by ji ovázali, až by zesílila, až by uchopila meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Proto praví Panovník Hospodin toto: ⌈Hle, jsem proti faraonovi, egyptskému králi,⌉ a ⌈zlomím mu paže,⌉ tu silnou i tu zlomenou, a nechám vypadnout meč z jeho ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Egypťany pak rozptýlím mezi národy a rozmetám je po zemích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Posilním paže babylonského krále a vložím mu do ruky svůj meč, zlomím paže faraona a bude před ním sténat, jako sténá pobitý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Posilním paže babylonského krále, ale paže faraonovy klesnou. I poznají, že já jsem Hospodin, až vložím svůj meč do ruky babylonského krále a on jej vztáhne proti egyptské zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Tu rozptýlím Egypťany mezi národy a rozmetám je po zemích. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'I stalo se ⌈v jedenáctém roce ve třetím měsíci, prvního dne toho měsíce;⌉ stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Lidský synu, řekni faraonovi, egyptskému králi, a jeho davu: ⌈Komu jsi byl podobný⌉ ve svém velikášství?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Hle, Asýrie, libanonský cedr krásného větvoví a stínící houština vysokého vzrůstu; jeho vrcholek byl mezi hustými větvemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vody mu daly vzrůst, hlubina jej vyvýšila, své řeky nechávala plynout okolo místa, kde byl vysazen, a své strouhy vypouštěla ke všem polním stromům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Tak jeho vzrůst převýšil všechny polní stromy, jeho větví bylo mnoho a díky hojným vodám jeho ratolesti vyrostly do délky, když je vypouštěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'V jeho větvích se uhnízdilo všelijaké nebeské ptactvo, pod jeho korunou rodila všechna polní zvířata a v jeho stínu pobývaly veškeré početné národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Stal se krásným svou velikostí, délkou svých větví, protože jeho kořen dosahoval k hojným vodám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Cedry v Boží zahradě ho nepřesahovaly, cypřiše nebyly podobné jeho větvím ani platany nebyly jako jeho ratolesti; žádný strom v Boží zahradě mu nebyl svou krásou podobný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Učinil jsem jej krásným pro množství jeho větví. Všechny stromy Edenu, které byly v Boží zahradě, mu záviděly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Proto praví Panovník Hospodin toto: Kvůli tomu, že se povyšoval vzrůstem, nastavoval svůj vrcholek mezi husté větve a ⌈jeho srdce se pozvedlo⌉ pro jeho výšku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'vydám jej do ruky mocnáře národů, jistě s ním naloží podle jeho ničemnosti; vyhnal jsem ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'I pokáceli jej cizinci, násilnické národy, a opustili jej. K horám a do všech údolí spadly jeho větve a jeho ratolesti byly rozlámány do všech řečišť země. Všechny národy země vystoupily z jeho stínu a opustily jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Na jeho torzu se usídlí všelijaké nebeské ptactvo, k jeho ratolestem se vydala všechna polní zvířata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'To aby se nepovyšovaly svým vzrůstem žádné stromy u vod, nenastavovaly svůj vrcholek doprostřed hustých větví a žádné stromy zavlažované vodami nevystavovaly svá klenutí ve své povýšenosti, protože ⌈všechny byly vydány na smrt, do útrob země mezi lidské syny, k těm, kdo sestupují do jámy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Toto praví Panovník Hospodin: V den, kdy sestoupil do podsvětí, dal jsem popud k truchlení, zakryl jsem nad ním hlubinu, zadržel jsem její řeky a hojné vody byly zastaveny, nechal jsem nad ním zachmuřit Libanon a všechny polní stromy jsou kvůli němu vysílené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Zvukem jeho pádu jsem otřásl národy, když jsem jej přiváděl do podsvětí s těmi, kdo sestupují do jámy, a ⌈v útrobách země byly potěšeny všechny stromy Edenu, to nejlepší a skvělé z Libanonu,⌉ všechny stromy zavlažované vodami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Také oni s ním sestoupili do podsvětí k pobitým mečem, i ti, kdo byli jeho paží a pobývali v jeho stínu uprostřed národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Komu jsi byl takto podobný slávou a velikostí mezi stromy Edenu? Budeš svržen se stromy Edenu do útrob země, s těmi, kdo byli pobiti mečem, ulehneš mezi neobřezance. Tak je tomu s faraonem a vším jeho davem, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'I stalo se ⌈v dvanáctém roce v dvanáctém měsíci, prvního dne toho měsíce;⌉ stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Lidský synu, pozvedni žalozpěv nad faraonem, egyptským králem. Řekneš mu: Byl jsi připodobněn k mladému lvu národů a byl jsi jako drak v mořích, vyvaloval ses ve svých tocích, čeřil jsi vody svýma nohama a kalil jsi jejich toky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Toto praví Panovník Hospodin: Rozprostřu však nad tebou svou síť ve shromáždění mnohých národů a vytáhnou tě v mé síti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Zanechám tě na zemi, na povrch pole tě vyvrhnu, usadím na tobě všelijaké nebeské ptactvo a nasytím tebou zvěř celé země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Na horách zanechám tvé maso a hromadou tvých ostatků zaplním údolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Napojím zemi záplavou tvé krve až k horám a řečiště budou z tebe plná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Až uhasneš, zakryji nebesa a hvězdy na nich nechám potemnět. ⌈Slunce, to zakryji oblakem,⌉ a měsíc nebude svítit svým světlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Všechna světla svítící na nebesích nad tebou nechám potemnět a uvedu temnotu na tvou zemi, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Tehdy znepokojím srdce mnohého lidu, až roznesu tvou zkázu mezi národy do zemí, které neznáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Způsobím, že se nad tebou mnohý lid zhrozí a ⌈jejich králové se nad tebou zděsí hrůzou,⌉ až před nimi zamávám svým mečem, a v den tvého pádu se budou neustále třást -- každý o svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Neboť toto praví Panovník Hospodin: Přijde na tebe meč babylonského krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Tvůj dav nechám padnout meči hrdinů, všech těch násilnických národů. Zničí pýchu Egypta a všechen jeho dav bude vyhuben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'A odstraním všechnu jeho zvěř z hojných vod a nebude už je čeřit lidská noha ani zvířecí kopyta je nebudou čeřit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Tehdy nechám usadit jejich vody a jejich toky nechám plynout jako olej, je výrok Panovníka Hospodina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'až proměním egyptskou zemi ve spoušť. Země bude zbavena všeho, co ji naplňuje, až v ní pobiji všechny obyvatele. I ⌈poznají, že já jsem Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'To je žalozpěv a budou jej zpívat. Zazpívají jej dcery národů. Zazpívají jej nad Egyptem a nade vším jeho davem, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'I stalo se v dvanáctém roce patnáctého dne toho měsíce; stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Lidský synu, běduj nad egyptským davem a nech jej sestoupit, jej i dcery vznešených národů, do útrob země s těmi, kdo sestupují do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Nad koho jsi byl milejší? Sestup a buď uložen s neobřezanci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Padnou uprostřed pobitých mečem. Meč byl předán. Odtáhli jej a všechny jeho davy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Mocní hrdinové s jeho pomocníky k němu promluví zprostřed podsvětí: Sestoupili, ulehli neobřezanci pobití mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Je tam Asýrie a celé její shromáždění, okolo ní její hroby; jsou to samí pobití, padlí mečem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'kterým byly dány její hroby na ⌈odlehlých stranách jámy,⌉ a její shromáždění bylo okolo jejího hrobu; jsou to samí pobití, padlí mečem, kteří působili děs v zemi živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Je tam Élam a celý jeho dav okolo jeho hrobu; jsou to samí pobití, padlí mečem, kteří sestoupili neobřezaní do útrob země, ti, kteří působili děs v zemi živých a nesou svoji ostudu s těmi, kdo sestupují do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Uprostřed pobitých mu dali lože se vším jeho davem, okolo něhož jsou jeho hroby. Jsou to samí neobřezanci pobití mečem, neboť jejich děs byl předáván v zemi živých a nesou svou ostudu s těmi, kdo sestupují do jámy; byl dán doprostřed pobitých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Je tam ⌈Mešek, Túbal⌉ a celý jeho dav, okolo něj jeho hroby; samí to neobřezanci pobití mečem, neboť působili děs v zemi živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Neulehnou však s padlými hrdiny z neobřezanců, kteří sestoupili do podsvětí ve své válečné zbroji a pod své hlavy si dali meče. Jejich zvrácenosti zůstaly na jejich kostech, protože v zemi živých šel z těch hrdinů děs.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'I ty budeš zdrcený uprostřed neobřezanců a ulehneš s pobitými mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Je tam Edóm, jeho králové a všechna jeho knížata, ti, kteří byli ve své síle vydáni spolu s pobitými mečem. Oni ulehnou s neobřezanci a s těmi, kdo sestupují do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Přišli sem všichni severní vazalové a všichni Sidónci, kteří sestoupili s pobitými ve svém děsu. Neobřezaní se stydí za své siláctví. Ulehli s pobitými mečem a nesli svou ostudu s těmi, kdo sestupují do jámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Faraon je uvidí a potěší se nad celým jejich davem. Faraon a všechno jeho vojsko jsou pobiti mečem, je výrok Panovníka Hospodina,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'neboť jsem uvedl do země živých svůj děs. Faraon a celý jeho dav bude uložen mezi neobřezance spolu s pobitými mečem, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Lidský synu, promluv k synům svého lidu. Řekneš jim: ⌈Jestliže přivedu na zemi meč⌉ a lid země vezme jednoho muže ze svého kraje a ustanoví si jej za strážného');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'a on uvidí ten meč přicházející na zemi, zatroubí na beraní roh a bude varovat lid');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'a ten, kdo poslouchá, uslyší zvuk beraního rohu, ale nenechal by se varovat a meč by přišel a zmocnil by se jej, ⌈jeho krev pak zůstane na jeho hlavě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Uslyšel zvuk beraního rohu, ale nenechal se varovat, jeho krev na něm zůstane; kdo by se nechal varovat, zachránil by svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Jestliže by však strážný uviděl ten přicházející meč, ale nezatroubil by na beraní roh a lid by nebyl varován, přišel by meč a zmocnil by se někoho z nich, ten by byl zachvácen ⌈pro svou zvrácenost,⌉ ale jeho krev budu vyhledávat z ruky toho strážného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Tebe pak, lidský synu, tebe jsem ustanovil strážným domu izraelského. Vyslechneš slovo z mých úst a předáš jim ode mne výstrahu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Když řeknu o ničemovi: Ničemo, jistě zemřeš, a ty bys nepromluvil, abys ničemu varoval před jeho cestou, onen ničema zemře pro svou zvrácenost, ale jeho krev vyhledám z tvé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Pokud bys však ty ničemu varoval před jeho cestou, aby se od ní odvrátil, ale on by se od své cesty neodvrátil, zemře pro svou zvrácenost, zatímco ty jsi vysvobodil svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Ty teď, lidský synu, řekni domu izraelskému: Mluvili jste takto: ⌈Když na nás spočívají naše přestoupení a naše hříchy a my v nich chřadneme, jak přežijeme?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Řekni jim: Jakože jsem živ, je výrok Panovníka Hospodina, cožpak si přeji smrt ničemy? Vždyť jestliže se ničema odvrátí od své cesty, zůstane naživu. Odvraťte se, odvraťte se od svých zlých cest. Proč byste měli zemřít, dome izraelský?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ty pak, lidský synu, řekni synům svého lidu: Spravedlnost spravedlivého jej nevysvobodí v den jeho přestoupení, a pokud jde o ničemnost, ⌈ničema kvůli ní neklesne v den, kdy se od ní odvrátí.⌉ Spravedlivý nebude kvůli ní moci žít v den, kdy zhřeší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Když řeknu o spravedlivém: Určitě bude žít, a on by spoléhal na svou spravedlnost, ale provedl by špatnost, žádné jeho spravedlivé činy nebudou připomínány a pro svou špatnost, kterou provedl, pro tu zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Když dále řeknu o ničemovi: Jistě zemřeš, ale on se odvrátí od svého hříchu a bude konat právo a spravedlnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'vrátí zástavu, a pokud ten ničema nahradí lup -- ⌈ pokud by žil podle ustanovení života, aby nepáchal špatnost -- určitě bude žít, nezemře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Žádné jeho hříchy, kterými zhřešil, mu nebudou připomínány; konal právo a spravedlnost, určitě bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Synové tvého lidu říkají: Panovníkova cesta není v pořádku, zatímco sami mají v nepořádku svou cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Když se spravedlivý odvrátí od své spravedlnosti a bude páchat špatnost, zemře pro ni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Když se však ničema odvrátí od své ničemnosti a bude konat právo a spravedlnost, on díky tomu bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Vy však říkáte: Panovníkova cesta není v pořádku. Budu vás soudit, každého podle jeho cest, dome izraelský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'I stalo se v dvanáctém roce našeho vyhnanství, v desátém měsíci, pátého dne toho měsíce, že ke mně ⌈přišel uprchlík z Jeruzaléma se slovy: Město bylo vybito.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, '⌈Hospodinova ruka na mně spočinula⌉ večer, předtím než přišel ten uprchlík, a má ústa se otevřela, než ke mně ráno přišel. Má ústa byla uvolněna a nebyl jsem již němý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Lidský synu, obyvatelé těchto trosek na izraelské půdě říkají: ⌈Abraham byl jediný a obsadil zemi.⌉ Nás je mnoho, nám byla dána země do vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Proto jim řekni: Toto praví Panovník Hospodin: Myslíte si, že ⌈budete jíst maso s krví,⌉ ⌈budete pozvedat oči ke svým bůžkům,⌉ budete prolévat krev a přitom obsadíte zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Spoléhali jste se na svůj meč, páchali jste ohavnost, ⌈znečistili jste každý ženu svého bližního⌉ a chcete obsadit zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Takto k nim promluvíš: Toto praví Panovník Hospodin: Jakože jsem živ, určitě ti, kteří jsou v troskách, padnou mečem, kdo je na povrchu pole, toho jsem vydal zvěři, aby ho sežrala, a ti kdo jsou ⌈v pevnostech a v jeskyních,⌉ zemřou na mor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Zemi pak proměním ve spoušť a zpustošenou krajinu, bude odklizena ⌈její mocná pýcha.⌉ Izraelské hory budou zpustošeny tak, že jimi nikdo ne bude procházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'I poznají, že já jsem Hospodin, až proměním zemi ve spoušť a zpustošenou krajinu kvůli všem jejich ohavnostem, které spáchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'A pokud jde o tebe, lidský synu, synové tvého lidu se proti tobě domlouvají u zdí a ve vchodech domů. Jeden mluví s druhým, každý se svým bratrem slovy: Pojďte přece a poslechněte, jaké slovo to vychází od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Přijdou k tobě jako sejití lidu a posadí se před tebou jako můj lid, budou poslouchat tvá slova, ale nebudou podle nich jednat. Oni totiž provozují vášnivou lásku svými ústy, jejich srdce však jde za jejich nekalým ziskem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Hle, ty jsi pro ně jako píseň vášnivé lásky, krásného zvuku a dobře hraješ; budou poslouchat tvá slova, ale jednat podle nich nebudou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Až to přijde -- a právě to přichází -- ⌈poznají, že uprostřed nich byl prorok.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Lidský synu, prorokuj proti pastýřům Izraele. Prorokuj a řekni jim, těm pastýřům: Toto praví Panovník Hospodin: Běda pastýřům Izraele, kteří byli pastýři sami sobě. Ne mají snad ti pastýři pást ovce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Budete jíst tuk a budete se oblékat do vlny, budete zabíjet, co je tučné, a ovce pást nebudete?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Nevyléčitelné jste neposilnili, nemocnou jste neléčili a polámanou jste neobvázali, zapuzenou jste nepřivedli zpět a ⌈hynoucí jste nevyhledali;⌉ panovali jste nad nimi násilím a se surovostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Bez pastýře se rozprchly; staly se pokrmem pro veškerou polní zvěř a rozprchly se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Mé ovce bloudí po všech horách a na kdejakém vyvýšeném návrší; mé ovce jsou rozptýleny po celém povrchu země a nikdo po nich ne pátrá ani je nehledá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Proto, pastýři, slyšte Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Jakože jsem živ, je výrok Panovníka Hospodina -- protože je mé stádo lupem a mé ovce se staly bez pastýřů pokrmem pro všechnu polní zvěř, pastýři nepátrali po mých ovcích, naopak ti pastýři pásli sami sebe a mé ovce nepásli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'proto -- vy, pastýři, slyšte Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Toto praví Panovník Hospodin: Hle, jsem proti těm pastýřům a budu vyhledávat své ovce z jejich ruky, zbavím je pasení stáda a ti pastýři už nebudou pást sami sebe. Vysvobodím své ovce z jejich úst a nebudou jim za pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Neboť toto praví Panovník Hospodin: Hle, ⌈to jsem já.⌉ ⌈Vyhledám své ovce a budu o ně pečovat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Jako věnuje pastýř péči svému stádu v den, kdy je uprostřed svých roztroušených ovcí, tak budu pečovat o své ovce a vysvobodím je ze všech míst, na která byly rozptýleny v ⌈den mračna a husté temnoty.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, '⌈Vyvedu je z národů, shromáždím je ze zemí a přivedu je na jejich půdu.⌉ ⌈Budu je pást na izraelských horách, v řečištích a na všech osídlených místech země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, '⌈Budu je pást na dobré pastvině a vysoko v izraelských horách bude jejich lučina. ⌈Tam budou uléhat na dobré lučině⌉ a na úrodné pastvině na izraelských horách se budou pást.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Já budu pást své ovce a já je budu ukládat, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Hynoucí vyhledám a zapuzenou přivedu zpět, polámanou obváži a nemocnou posilním. Tučnou a silnou vyhladím; budu je pást spravedlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'A o vás, mé stádo, toto praví Panovník Hospodin: Hle, já konám soud mezi dobytčetem a dobytčetem, mezi berany a kozly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Což je vám to málo, když spasete dobrou pastvinu, že zbytek svých pastvin pošlapete svýma nohama? Napijete se čiré vody a tu zbývající svýma nohama zakalíte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'A mé ovce se budou pást na tom, co pošlapaly vaše nohy, a budou pít, co vaše nohy zkalily?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Proto o nich praví Panovník Hospodin toto: Hle, to jsem já. Vykonám soud mezi dobytčetem tučným a mezi dobytčetem vyhublým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Jelikož srážíte bokem a ramenem všechny nevyléčitelné a trkáte je svými rohy, a tak jste je rozptýlily pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Já však své ovce zachráním a nebudou již lupem; vykonám soud mezi dobytčetem a dobytčetem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'A ustanovím nad nimi jednoho pastýře a bude je pást, svého otroka Davida. On je bude pást, on jim bude pastýřem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Já Hospodin jim budu Bohem a můj otrok David bude uprostřed nich knížetem. Já Hospodin jsem promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Uzavřu s nimi smlouvu pokoje a odklidím ze země divou zvěř. Budou pobývat bezpečně i v pustině a spát v lesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Obdařím je i okolní místa svého návrší požehnáním; sešlu déšť v jeho čas -- budou to požehnané deště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Polní stromoví pak vydá své ovoce, země vydá svou úrodu a lidé budou v bezpečí na své půdě. I poznají, že já jsem Hospodin, až zlámu kolíky jejich jha a vysvobodím je z ruky těch, kdo je zotročují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Už nebudou lupem pro národy a zemská zvěř je nesežere. ⌈Budou bydlet v bezpečí a nikdo je ne vyděsí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Dám pro ně povstat ⌈znamenité setbě⌉ a nebudou už v zemi souženi hladem ani už nebudou snášet hanění národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'I poznají, že já Hospodin, jejich Bůh, jsem s nimi a oni jsou můj lid, dům izraelský, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Vy jste totiž mé ovce, ovce mé pastvy, vy lidé. Já jsem váš Bůh, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Lidský synu, nastav svou tvář proti pohoří Seíru a prorokuj proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Řekneš mu: Toto praví Panovník Hospodin: ⌈Hle, jsem proti tobě,⌉ pohoří Seíre, vztáhnu proti tobě ruku a proměním tě ve ⌈spoušť a zpustošenou krajinu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Tvá města proměním v trosky a ty se staneš spouští -- i poznáš, že já jsem Hospodin --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'jelikož v sobě máš odvěké nepřátelství a uvrhl jsi syny Izraele ⌈pod moc meče⌉ v době pohromy, v době dovršení zvrácenosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Proto -- jakože jsem živ, je výrok Panovníka Hospodina -- tě vydám krveprolití a krveprolití tě bude pronásledovat. Jestliže jsi neměl krveprolití v nenávisti, krveprolití tě bude pronásledovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Proměním pohoří Seír v hlušinu a spoušť a vyhladím z něj toho, kdo prochází a vrací se zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Jeho hory naplním jeho pobitými; tvá návrší, tvá údolí a všechna tvá řečiště -- v nich padnou pobití mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Proměním tě ve věčnou spoušť a tvá města už nebudou obývána. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Jelikož říkáš: Ty dva národy a ty dvě země budou mé a obsadíme je, ačkoliv tam přebýval Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Proto, jakože jsem živ, je výrok Panovníka Hospodina, budu jednat podle tvého hněvu a podle tvé žárlivosti tak, jak jsi jednal ze své nenávisti proti nim. Dám se mezi nimi poznat podle toho, jak tě budu soudit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'I poznáš, že já Hospodin jsem slyšel všechna tvá znevažování, která jsi pronesl proti izraelským horám slovy: Byly zpustošeny, byly nám dány za pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Vyvyšovali jste se nade mnou svými ústy a množili jste svá slova proti mně. Já jsem to slyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Toto praví Panovník Hospodin: Zatímco se celá země raduje, udělám z tebe spoušť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Podle tvé radosti nad tím, že dědictví domu izraelského bylo zpustošeno, tak naložím s tebou. Pohoří Seír i celý Edóm, to všechno bude spouští. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'A ty, lidský synu, prorokuj proti izraelským horám. Řekneš: Izraelské hory, slyšte Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Toto praví Panovník Hospodin: Jelikož o vás nepřítel řekl: Výborně! I starodávná návrší se nám dostala do vlastnictví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'proto prorokuj a řekni: Toto praví Panovník Hospodin: Právě proto, že vás pustoší a baží po vás ze všech stran, abyste se staly vlastnictvím ostatních národů, a ⌈zatáhli vás do řečí⌉ a pomluv lidu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'proto izraelské hory, slyšte slovo Panovníka Hospodina: Toto praví Panovník Hospodin ⌈k horám a návrším, řečištím a údolím⌉ i ke zpustošeným troskám a opuštěným městům, která se stala lupem a předmětem výsměchu ostatních okolních národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Proto praví Panovník Hospodin toto: Copak jsem nepromluvil ⌈se svou ohnivou žárlivostí⌉ proti ostatním národům a proti všem Edómcům, kteří zabrali mou zemi pro sebe do vlastnictví s radostí z celého srdce a s opovržením v duši, aby jako lup získali její pastviny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Proto prorokuj proti izraelské půdě. Řekneš horám a návrším, řečištím a údolím: Toto praví Panovník Hospodin: Hle, já jsem promluvil ve své žárlivosti a ve své zlobě, jelikož jste snášeli hanění národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Proto praví Panovník Hospodin toto: Já jsem pozvedl svou ruku: Národy, které jsou okolo vás, ony jistě ponesou svou ostudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'A vy, izraelské hory, poskytnete své větvoví a ponesete své ovoce pro můj izraelský lid, protože ⌈se přiblížil jeho příchod.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Vždyť hle, já jsem s vámi. Obrátím se k vám a budete obdělávány a osívány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'A rozmnožím na vás lidi, úplně celý dům izraelský. Města budou obydlena a ⌈trosky budou vybudovány.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Rozmnožím na vás lidi i zvěř, ⌈rozmnoží se a rozplodí se.⌉ Osídlím vás jako dřív a budu vám prokazovat dobro více než ve vašich počátcích. ⌈I poznáte, že já jsem Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Uvedu na vás lidi, svůj izraelský lid, obsadí vás a budete pro ně dědictvím. Už je více nebudete připravovat o děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Toto praví Panovník Hospodin: Jelikož vám říkají: ⌈Ty jsi požírala lidi⌉ a připravovala jsi své národy o děti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'proto už nebudeš lidi požírat a své národy už ⌈nebudeš připravovat o děti,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Nenechám už k tobě zaznít hanění národů a nebudeš už snášet tupení lidí. Své národy už nepřivedeš k pádu, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Lidský synu, když dům izraelský sídlil na své půdě, znečistili ji svým jednáním a svými činy. Jejich jednání bylo přede mnou jako nečistota při menstruaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Tu jsem na ně vylil svou zlobu kvůli krvi, kterou vylévali na zemi; znečistili ji svými bůžky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Rozptýlil jsem je mezi národy, byli rozmetáni po zemích. Soudil jsem je podle jejich cesty a podle jejich činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Přišli k národům tam, kde šli, a znesvěcovali mé svaté jméno, když o nich národy říkaly: Tito jsou Hospodinovým lidem a přitom odešli z jeho země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Avšak měl jsem soucit se svým svatým jménem, které dům izraelský ⌈znesvětil mezi národy,⌉ kamkoli přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Proto řekni domu izraelskému: Toto praví Panovník Hospodin: ⌈Já to nedělám kvůli vám, dome izraelský,⌉ nýbrž pro své ⌈svaté jméno, které jste znesvětili mezi národy, kamkoli jste přišli.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Posvětím své velké jméno, znesvěcené mezi národy, které jste mezi nimi znesvětili. I poznají ty národy, že já jsem Hospodin, je výrok Panovníka Hospodina, až budu mezi vámi posvěcen před jejich očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Tehdy vás vezmu z těch národů, shromáždím vás ze všech těch zemí a přivedu vás na vaši půdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Pokropím vás čistou vodou a budete čistí; očistím vás od všech vašich nečistot a od všech vašich bůžků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Dám vám nové srdce a nového ducha dám do vašeho nitra. Odstraním srdce kamenné z vašeho těla a dám vám srdce masité.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Svého ducha dám do vašeho nitra a způsobím, že budete žít podle mých ustanovení a má nařízení budete zachovávat a plnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Budete bydlet v zemi, kterou jsem dal vašim otcům. I budete mým lidem a já budu vaším Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Zachráním vás ode všech vašich nečistot. Zavolám na obilí, rozmnožím je a neuvedu na vás hlad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Rozmnožím ovoce na stromech a polní plodiny, takže už neponesete potupu hladu mezi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Pak si vzpomenete na své zlé cesty a na své činy, které nebyly dobré, a zhnusíte se sami sobě pro své zvrácenosti a pro své ohavnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Já to nedělám kvůli vám, je výrok Panovníka Hospodina, to ať je vám známo. Styďte se a hanběte se za své cesty, dome izraelský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Toto praví Panovník Hospodin: V den, kdy vás očistím ode všech vašich zvráceností, ⌈osídlím města a trosky budou vybudovány.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'A zpustošená země bude obdělávána místo toho, aby byla spouští před očima každého kolemjdoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'I řeknou: Tato země, tak zpustošená, se stala podobnou zahradě Eden a města, zničená, zpustošená a zbořená, byla opevněna a obydlena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'I poznají národy, které zůstanou okolo vás, že já Hospodin jsem vystavěl ta zbořená města a osadil jsem tu zpustošenou zemi. ⌈Já Hospodin jsem promluvil a vykonám to.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Toto praví Panovník Hospodin: Co víc -- ⌈dám se domu izraelskému poznat, že pro ně tohle učiním:⌉ Rozmnožím jejich lidi jako stádo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Jako posvátné ovce, jako stádo v Jeruzalémě při jeho svátcích, tak budou ta zničená města plná stáda lidí. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Spočinula na mně Hospodinova ruka a ⌈Hospodin mě vyvedl v duchu,⌉ ponechal mě uprostřed pláně; ta byla plná kostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Pak mě nad nimi provedl kolem dokola; hle, bylo jich na povrchu pláně velmi mnoho, a hle, byly velmi vyschlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Tu mi řekl: Lidský synu, jestlipak tyto kosti ožijí? Odpověděl jsem: Panovníku Hospodine, ty to víš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Pak mi řekl: Prorokuj k těmto kostem a řekni jim: Vyschlé kosti, slyšte Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Toto praví Panovník Hospodin o těchto kostech: ⌈Hle, uvedu do vás ducha a vy ožijete.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Dám na vás šlachy, nanesu na vás maso a natáhnu na vás kůži, vložím do vás ducha a ožijete. I poznáte, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'I prorokoval jsem, tak jak mi bylo přikázáno. Jakmile jsem prorokoval, nastal hluk a hle, hřmot a kosti se přiblížily ⌈jedna k druhé.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Potom hle, spatřil jsem na nich šlachy, maso vyrostlo a odshora se na ně natáhla kůže, ale duch v nich nebyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Nato mi řekl: Prorokuj k duchu. Prorokuj lidský synu a řekni tomu duchu: Toto praví Panovník Hospodin: Přijď, duchu, od čtyř větrů a vdechni do těchto pobitých, ať ožijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'I prorokoval jsem, jak mi to přikázal. ⌈Tu do nich přišel duch, ožili a postavili se na nohy,⌉ převelice velké vojsko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Nato mi řekl: Lidský synu, tyto kosti jsou celý dům izraelský. ⌈Hle, říkají: Naše kosti uschly a naše naděje zahynula, jsme ztraceni. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Proto prorokuj a řekni jim: Toto praví Panovník Hospodin: Hle, ⌈otevřu vaše hroby a vyvedu vás z vašich hrobů,⌉ můj lide. ⌈Přivedu vás na izraelskou půdu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'I poznáte, že já jsem Hospodin, až otevřu vaše hroby a až vás vyvedu z vašich hrobů, můj lide.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Vložím do vás svého ducha a ožijete. Pak vám dám spočinout na vaší půdě. I poznáte, že já Hospodin jsem promluvil a také to vykonám, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'A ty, lidský synu, vezmi si jedno dřevo a napiš na ně: Judovi a synům Izraele, jeho druhům. Pak vezmi další dřevo a napiš na ně: Dřevo Efrajimovo, Josefovi a celému domu izraelskému, jeho druhům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Přilož si je jedno k druhému jako jediné dřevo a stanou se ve tvé ruce jedním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Jakmile se tě zeptají synové tvého lidu: Cožpak nám neoznámíš, co tohle pro tebe znamená?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Promluv k nim: Toto praví Panovník Hospodin: Hle, já beru dřevo Josefa a izraelských kmenů, jeho druhů, které je v ruce Efrajimově. Položím ⌈s nimi na ně⌉ dřevo Judovo a učiním je jediným dřevem, stanou se v mé ruce jedním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Ta dřeva, na něž budeš psát, budou ve tvé ruce ⌈před jejich očima.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Promluv k nim: Toto praví Panovník Hospodin: Hle, beru syny Izraele zprostřed národů, kam odešli, shromáždím je ze všech stran a přivedu je na jejich půdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Pak je učiním jediným národem v zemi, na izraelských horách, a ⌈jediný král bude králem pro ně všechny.⌉ Už ⌈nebudou dvěma národy ani už nebudou znovu rozděleni na dvě království.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Neznečistí se už svými bůžky, svými ohavnými modlami ani žádnými svými přestoupeními. Zachráním je ze všech jejich sídel, v nichž zhřešili, a očistím je, ⌈budou mým lidem a já budu jejich Bohem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Můj otrok David bude nad nimi králem a jediný pastýř bude pro ně všechny. ⌈Budou žít podle mých nařízení, budou zachovávat má ustanovení a plnit je.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Budou bydlet v zemi, kterou jsem dal svému otroku Jákobovi, v níž bydleli vaši otcové. V ní budou bydlet oni i jejich synové a synové jejich synů až navěky a můj otrok David bude navěky jejich knížetem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Uzavřu s nimi smlouvu pokoje, bude to věčná smlouva s nimi. Obdařím je, rozmnožím je a ⌈ustanovím uprostřed nich navěky svou svatyni.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Můj příbytek bude nad nimi, ⌈ já budu jejich Bohem a oni budou mým lidem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'I poznají národy, že já Hospodin posvěcuji Izrael, když bude má svatyně navěky uprostřed nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Lidský synu, nastav svou tvář proti Gógovi v zemi Magógu, ⌈přednímu knížeti⌉ ⌈Mešeku a Túbalu,⌉ a prorokuj proti němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Řekneš: Toto praví Panovník Hospodin: Hle, jsem proti tobě, Gógu, přední kníže Mešeku a Túbalu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Obrátím tě zpět, ⌈vložím do tvých čelistí kruhy⌉ a vyvedu tě i celé tvé vojsko, koně a jezdce, všechny dokonale oblečené, početné shromáždění, s velkými i malými štíty, všechny, kteří nosí meče,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, '⌈Peršany, s nimi Kúšijce a Pútejce, všechny se štíty a přilbami,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomera a všechny jeho šiky, Bét–togarmu ⌈ z odlehlých končin severu⌉ a všechny jeho šiky, mnohé národy s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Pevně stůj a připrav se, ty a všechna tvá shromáždění, která jsou shromážděna kolem tebe. Budeš pro ně stráží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, '⌈Po mnohých dnech budeš navštíven, v⌉ posledních letech přijdeš do země zotavené od meče, shromážděné z mnohých národů, ⌈na izraelské hory,⌉ které byly stále pustinou. Ona je vyvedená z národů a ⌈všichni budou pobývat v bezpečí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Tu vystoupíš, ⌈přijdeš jako bouře, budeš jako oblak,⌉ abys zakryl zemi, ty i všechny tvé šiky a mnohé národy s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Toto praví Panovník Hospodin: ⌈I stane se v onen den,⌉ že něco vstoupí do tvého srdce a ty ukuješ zlý plán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Tu řekneš: Vytáhnu na neopevněnou zemi, přijdu k těm poklidným, kteří bydlí v bezpečí, ke všem obyvatelům, kteří nemají hradbu ani závoru ani vrata,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'abych ukořistil kořist a uloupil lup. Abys obrátil svou ruku na obydlené trosky a k lidu shromážděnému z národů, který se zabývá dobytkem a zbožím, k těm, kteří bydlí ve středu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Šeba a Dedán, obchodníci z Taršíše a všechny jeho vesnice ti řeknou: Přicházíš snad, abys ukořistil kořist? Svolal jsi snad své shromáždění, abys uloupil lup? Abys odnesl stříbro a zlato, abys vzal dobytek a zboží, abys ukořistil velkou kořist?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Proto prorokuj, lidský synu, a řekni Gógovi: Toto praví Panovník Hospodin: Což se to v onen den, až bude můj lid Izrael bydlet v bezpečí, nedozvíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Vyjdeš ze svého místa z odlehlých končin severu, ty a s tebou mnohé národy, všichni jezdci na koních, velké shromáždění a početné vojsko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Vytáhneš na můj lid Izrael jako oblak pokrývající zemi. V posledních dnech se stane, že tě přivedu na svou zemi, ⌈aby mě poznaly národy, až budu skrze tebe posvěcen před jejich očima,⌉ Gógu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Toto praví Panovník Hospodin: Ty jsi ten, o němž jsem promluvil v dávných dnech prostřednictvím svých otroků, izraelských proroků, kteří v oněch dnech léta prorokovali, že tě na ně přivedu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'I stane se v onen den, v den příchodu Góga na izraelskou půdu, je výrok Panovníka Hospodina, že má zloba vzplane na mé tváři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Ve své žárlivosti, v ⌈ohni své zuřivosti⌉ jsem promluvil. Jistě v onen den nastane na izraelské půdě velké země třesení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Tehdy se přede mnou budou třást ⌈mořské ryby a nebeské ptactvo, polní zvěř a každý plaz, plazící se po zemi,⌉ i každý člověk, který přebývá na povrchu země. ⌈Hory se zbortí, skalní převisy spadnou a každá hradba padne k zemi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Povolám proti němu ke všem svým horám meč, je výrok Panovníka Hospodina. ⌈Meč jednoho bude proti druhému.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Vykonám nad ním soud skrze mor a krveprolití. ⌈Přívalový déšť a krupobití kamenů, ⌈oheň a síru⌉ sešlu na něho a na jeho šiky i na mnohé národy, které jsou s ním.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Vyvýším se, posvětím se a dám se poznat před očima mnohých národů. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'A ty, lidský synu, prorokuj proti Gógovi a řekni: Toto praví Panovník Hospodin: Hle, jsem proti tobě, Gógu, přední kníže Mešeku a Túbalu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Obrátím tě zpět, povleču tě a vyvedu tě z odlehlých končin severu. ⌈I přivedu tě na izraelské hory.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, '⌈Vyrazím ti luk z levé ruky a šípy z pravé ruky ti nechám vypadnout.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Na izraelských horách padneš ty a všechny tvé šiky i národy, které jsou s tebou. Dám tě za pokrm dravému ptactvu, kdejakému okřídlenci a polní zvěři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Padneš v otevřené krajině, protože já jsem promluvil, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Pak pošlu oheň do Magógu a na ty, kdo v bezpečí obývají ostrovy. I poznají, že já jsem Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Své svaté jméno dám poznat uprostřed svého lidu Izraele a nenechám už své svaté jméno znesvěcovat. I poznají národy, že já, Hospodin, jsem Svatý v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Hle, přichází a stane se to, je výrok Panovníka Hospodina. To je ten den, o němž jsem mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Obyvatelé izraelských měst vyjdou, zapálí oheň a budou topit zbraněmi, malými a velkými štíty, luky a šípy, ručními kopími a oštěpy. Zapálí na nich oheň na sedm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Nebudou nosit stromy z pole a nebudou je rubat v lesích, protože zapálí oheň pod zbraněmi. Vyplení své plenitele a oloupí své lupiče, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'I stane se v onen den, že tam dám Gógovi místo pro hrob, v Izraeli v údolí vetřelců na východ od moře, v údolí, které zadržuje vetřelce. Tam pohřbí Góga a celý jeho dav a nazvou je Údolím Gógova hlučícího davu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Dům izraelský je bude pohřbívat sedm měsíců, aby očistil zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Všechen lid země bude pohřbívat a ⌈bude jim to ke cti. V ten den budu oslaven, je ⌉ výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'A lid nastálo oddělí muže procházející zemí, kteří budou pohřbívat padlé vetřelce ponechané na povrchu země, aby ji očistili. Budou ji prohlížet poté, co uplyne sedm měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Ti procházející projdou zemí, a kdo uvidí kost člověka, postaví vedle ní pomník, dokud ho hrobaři ne pohřbí v Údolí Gógova hlučícího davu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Bude také město jménem Hamóna. Tak očistí zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'A ty, lidský synu, toto praví Panovník Hospodin: Řekni ptactvu, každému okřídlenci a veškeré polní zvěři: Shromážděte se a přijďte, seberte se z okolí na můj obětní hod, který vám předkládám, velký obětní hod na izraelských horách. Najíte se masa a napijete se krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Budete jíst maso hrdinů a budete pít krev knížat země; beranů, jehňat, kozlů a býčků, samých to vykrmených bášanských dobytčat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'A budete jíst tuk do nasycení a pít krev do opilosti z mého obětního hodu, který jsem vám předložil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Nasytíte se u mého stolu ⌈koňmi a vozbou, hrdiny a všemi bojovníky,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Svou slávu uvedu mezi národy. Všechny národy uvidí můj soud, který jsem vykonal, a mou ruku, kterou jsem na ně vložil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'I pozná dům izraelský, že já Hospodin jsem jejich Bůh, od onoho dne i nadále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'I poznají národy, že dům izraelský byl vystěhován pro svou zvrácenost, kvůli tomu, že se mi zpronevěřili, a ⌈ já jsem před nimi skryl svou tvář.⌉ ⌈Vydal jsem je do ruky jejich protivníků⌉ a všichni padli mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Naložil jsem s nimi podle jejich nečistoty a podle jejich přestoupení a skryl jsem před nimi svou tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Proto praví Panovník Hospodin toto: Nyní změním Jákobův úděl a slituji se nad celým domem izraelským. Vzplanu žárlivostí pro své svaté jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Ponesou svou ostudu a všechnu svou věrolomnost, kterou se mi zpronevěřili, když pobývali v bezpečí na své půdě a ⌈ nikdo je neděsil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Až je navrátím z národů a shromáždím je ze zemí jejich nepřátel, ⌈budu skrze ně posvěcen před očima mnohých národů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'I poznají, že já Hospodin jsem jejich Bůh, podle toho, že jsem je odvedl do zajetí k národům, ale shromáždím je na jejich půdu; už tam z nich nikoho neponechám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Nebudu už před nimi skrývat svou tvář, já, který ⌈jsem vylil svého ducha na dům izraelský,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Ve dvacátém pátém roce našeho vyhnanství na počátku roku, desátého dne toho měsíce, čtrnáct let po tom, co bylo vybito město, právě tohoto dne na mně spočinula Hospodinova ruka a přivedl mě tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'V Božím vidění mě přivedl do izraelské země. Ponechal mě na velmi vysoké hoře, na níž byla od jihu jakoby výstavba města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Přivedl mě tam a hle, byl tam muž, který ⌈vypadal jako z ⌉ bronzu a ⌈měl v ruce lněnou šňůrku a měřicí třtinu.⌉ Ten stál v bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Ten muž ke mně promluvil: Lidský synu, dívej se svýma očima a svýma ušima slyš, věnuj pozornost všemu, co ti ukazuji, protože jsi sem byl přiveden, abych ti to ukázal. Všechno, co vidíš, oznam domu izraelskému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'A hle, vně domu byla kolem dokola hradba. Ten muž měl v ruce třtinu měřící šest loket (každý na loket a dlaň) a změřil šířku stavby: jedna třtina a výšku: jedna třtina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Pak přišel k bráně, která byla obrácená směrem na východ, a vystoupil po jejích stupních. Změřil práh brány: měl jednu třtinu na šířku a další práh: měl jednu třtinu na šířku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Světnice měla jednu třtinu na délku, jednu třtinu na šířku a mezi světnicemi bylo pět loket. Práh brány u předsíně směrem od vnitřku brány měřil jednu třtinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Pak změřil předsíň brány zevnitř: jedna třtina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Dále změřil předsíň brány: osm loket a její pilíře: dva lokte, totiž předsíň uvnitř brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Světnice v bráně směrem na východ byly ⌈tři z jedné strany a tři z druhé strany;⌉ ty tři měly stejný rozměr. Stejný rozměr měly také pilíře z jedné strany i z druhé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Pak změřil šířku vchodu do brány: deset loket. Délka brány činila třináct loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Prostor před světnicemi měřil jeden loket a jeden loket měřil prostor z druhé strany. Světnice měla šest loket z jedné strany a šest loket z druhé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Pak změřil bránu od střechy světnice k její střeše: šířka dvacet pět loket; vchod naproti vchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, '⌈Stejně naložil s pilíři:⌉ měřily šedesát loket. K pilířům dosahovalo nádvoří brány kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Dále, přes průčelí vstupní brány k předku předsíně vnitřní brány to bylo padesát loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Dovnitř do brány kolem dokola vedla okna zúžená do světnic a k jejich pilířům a tak tomu bylo i u podloubí. Okna kolem dokola vedla dovnitř a na každém pilíři byly palmové ozdoby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Pak mě přivedl k vnějšímu nádvoří a hle, byly tam síně a na nádvoří kolem dokola byla zhotovena dlažba. Na té dlažbě bylo třicet síní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Dlažba dosahovala k boku bran po celé délce bran. To byla spodní dlažba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'A odměřil šířku od průčelí dolní brány k předku vnitřního nádvoří: zvenku sto loket; na východ i na sever.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'I u brány, která byla obrácená směrem na sever k vnějšímu nádvoří, změřil její délku a šířku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Její světnice byly tři z jedné strany a tři z druhé strany i její pilíře a její podloubí. Byla udělaná podle rozměrů první brány: padesát loket její délka a šířka v loktech dvacet pět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'I její okna, její podloubí a její palmové ozdoby byly podle rozměrů té brány, která byla obrácená směrem na východ. Vystupuje se do ní po sedmi stupních; před nimi bylo její podloubí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Brána do vnitřního nádvoří pak byla naproti bráně na severu jako i na východě. Od brány k bráně naměřil sto loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'I přivedl mě směrem na jih a hle, byla zde brána směrem na jih. Změřil její pilíře a její podloubí -- vše jako předchozí rozměry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Ona i její podloubí měla okna kolem dokola jako tamta okna. Padesát loket činila délka a šířka dvacet pět loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Pro ⌈vystupování do ní⌉ bylo postaveno sedm stupňů a před nimi její podloubí. Měla palmové ozdoby, jednu z jedné strany a jednu z druhé strany na svých pilířích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'I brána do vnitřního nádvoří mířila směrem na jih. Od brány k bráně směrem na jih naměřil sto loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Pak mě přivedl k vnitřnímu nádvoří v jižní bráně a změřil jižní bránu -- vše jako předchozí rozměry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Její světnice, její pilíře a její podloubí byly podle předchozích rozměrů; ona i její podloubí měla okna kolem dokola. Padesát loket činila délka a šířka dvacet pět loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Podloubí kolem dokola měla délku dvacet pět loket a šířku pět loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Její podloubí vedla k vnějšímu nádvoří a na jejích pilířích byly palmové ozdoby. Její vstup má osm stupňů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Pak mě přivedl k vnitřnímu nádvoří směrem na východ a změřil bránu -- vše jako předchozí rozměry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Její světnice, ⌈její pilíře⌉ a její podloubí byly podle předchozích rozměrů; ona i její podloubí měla okna kolem dokola. Délka činila padesát loket a šířka dvacet pět loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Její podloubí vedla k vnějšímu nádvoří a palmové ozdoby byly na jejích pilířích z jedné strany i z druhé strany. Její vstup měl osm stupňů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Pak mě přivedl k severní bráně a změřil ji -- vše jako předchozí rozměry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Její světnice, její pilíře a její podloubí; okna měla kolem dokola. Délka činila padesát loket a šířka dvacet pět loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Její pilíře byly u vnějšího nádvoří a palmové ozdoby byly na jejích pilířích z jedné strany i z druhé strany. Její vstup měl osm stupňů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Byla tam i síň, jejíž vchod byl mezi pilíři bran. ⌈Tam se oplachují zápalné oběti.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, '⌈V předsíni brány pak stály dva stoly z jedné strany a dva stoly z druhé strany, aby se na nich porážela zápalná oběť, oběť za hřích a oběť za vinu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, '⌈Na boku zvenku, kde se vystupuje ke vchodu do severní brány, stály dva stoly a na druhém boku, tam u předsíně brány, stály také dva stoly.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Čtyři stoly byly z jedné strany a čtyři stoly z druhé strany u boku brány; celkem osm stolů, na nichž se poráží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Čtyři kamenné stoly pro zápalnou oběť byly z tesaného kamene o délce jednoho a půl lokte, šířce jednoho a půl lokte a výšce jednoho lokte. Na ně se odkládají nástroje, jimiž se poráží zápalná oběť a obětní hod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Dvojháky velké na jednu dlaň byly v domě upevněny kolem dokola a na stolech leželo maso obětního daru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'A zvenku u vnitřní brány se nacházely síně zpěváků na vnitřním nádvoří; ta, která byla u boku severní brány a svým čelem mířila směrem na jih, druhá pak u boku východní brány s čelem směrem na sever.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Tu ke mně promluvil: Ta síň, která svým čelem míří směrem na jih, je pro kněze držící stráž u domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'A síň, která svým čelem míří směrem na sever, je pro kněze držící stráž u oltáře. To jsou synové Sádokovi, kteří se jako jediní ze synů Léviho přibližují k Hospodinu, aby mu sloužili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'I změřil nádvoří: délka sto loket a šířka sto loket -- je čtvercové. A před domem stál oltář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Pak mě přivedl k předsíni domu a změřil pilíř předsíně: pět loket z jedné strany a pět loket z druhé strany. Šířka brány činila tři lokte z jedné strany a tři lokte z druhé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Délka předsíně činila dvacet loket a šířka jedenáct loket; byly tam stupně, po kterých se k ní vystupuje. U pilířů stály sloupy, jeden z jedné strany a další z druhé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Pak mě přivedl k chrámu a změřil pilíře: šest loket na šířku z jedné strany a šest loket na šířku z druhé strany, šířka stanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Šířka vchodu činila deset loket a boků vchodu pět loket z jedné strany a pět loket z druhé strany. Změřil jeho délku: čtyřicet loket a šířku: dvacet loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Pak vešel dovnitř a změřil pilíř vchodu: dva lokte. Vchod měřil šest loket a šířka vchodu činila sedm loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Nato změřil jeho délku: dvacet loket a šířku: dvacet loket u průčelí chrámu. Řekl mi: Toto je svatyně svatých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Změřil i zeď domu: šest loket a šířku ochozu: čtyři lokte kolem dokola na domu ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'A ty ochozy byly ⌈jeden nad druhým⌉ třikrát po třiceti a zapadaly na zdi, která je na domě, do sebe kolem dokola, takže byly navzájem spojené. Nejsou spojené se zdí domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Ta se rozšiřovala a stáčela se stále vzhůru k ochozům, protože věnec domu stoupal stále vzhůru kolem dokola podle domu, proto ⌈ měl dům největší šířku⌉ nahoře. ⌈Tak se ze spodního ochozu vystupuje na horní přes prostřední.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Viděl jsem na domě vyvýšeninu kolem dokola. Základy těch ochozů měřily ⌈celou třtinu, celkem šest loket.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Šířka zdi, která byla u ochozu zvenku, činila pět loket. Ta, která zůstala volná mezi ochozy, které byly na domě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'a mezi síněmi, měla šířku dvacet loket ze všech stran domu kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Vchod z ochozu byl na volném prostranství, jeden vchod směrem na sever a druhý vchod na jih. Šířka místa, které zůstalo volné, činila kolem dokola pět loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Stavba, která stála po straně odděleného prostoru směrem na západ, měla šířku sedmdesát loket. Zeď té stavby měla šířku pět loket kolem dokola a její délka činila devadesát loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Pak změřil dům; měl délku sto loket. I oddělený prostor, budova a její zdi měly délku sto loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Šířka průčelí domu a odděleného prostoru na východě činila sto loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Pak změřil délku stavby před odděleným prostorem, který je vzadu, a jeho galerie z jedné strany i z druhé strany: sto loket. ⌈Vnitřní chrám a předsíně nádvoří,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'prahy a zúžená okna i galerie okolo měly na svých třech stranách naproti prahu kolem dokola dřevěné obložení od země až k oknům. Okna byla pokryta');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'na ploše od vchodu až k vnitřnímu domu i zvenku⌉ a po celé zdi kolem dokola na vnitřní i na vnější ploše');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'byli pak zhotoveni cherubové a palmové ozdoby. Palmová ozdoba byla vždy mezi cherubem a cherubem a ⌈ každý cherub měl dvě tváře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Lidská tvář směřovala k palmové ozdobě z jedné strany a tvář mladého lva k palmové ozdobě z druhé strany. Byly zhotoveny u celého domu kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Cherubové a palmové ozdoby byli zhotoveni od země až nad vchod i na zdi chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Veřeje chrámu byly čtyřhranné. Před svatyní stálo něco, co ⌈vypadalo jako⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'dřevěný oltář tři lokte vysoký. Jeho délka činila dva lokte, měl rohy a ⌈stěny po celé jeho délce byly dřevěné.⌉ Promluvil ke mně: Toto je stůl, který stojí před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Chrám a svatyně měly dvojité dveře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Dveře měly dvě křídla. Obě křídla byla otočná, dvě měly jedny dveře a dvě křídla měly další.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Na těch chrámových dveřích byli zhotoveni cherubové a palmové ozdoby, tak jako byli zhotoveni na zdech. Před předsíní byla zvenku dřevěná stříška.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Zúžená okna a palmové ozdoby jsou z jedné strany i z druhé strany na bocích předsíně, též ochozy domu a ty stříšky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Pak mě vyvedl na vnější nádvoří cestou směrem na sever a přivedl mě k síni, která stála naproti oddělenému prostoru a naproti stavbě na severu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Zepředu měla délku sto loket u severního vchodu a šířku padesát loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Naproti dvaceti loktům na vnitřním nádvoří a naproti dlažbě, která byla na vnějším nádvoří, stála galerie čelem ke galerii ve třech poschodích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Před síněmi byl přístup o šířce deseti loket, cesta dovnitř měřila jeden loket. Jejich vchody mířily na sever.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Horní síně stavby byly zmenšené oproti spodním a prostředním, protože galerie část z nich zabíraly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Byly totiž trojité a neměly sloupy, jako jsou sloupy na nádvořích. Proto se stavba mimo spodní a mimo prostřední síně od země zužovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Zeď, která se táhla zvenku podél síní směrem k vnějšímu nádvoří, vedla při přední straně síní. Její délka činila padesát loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Délka síní, které byly u vnějšího nádvoří, totiž činila padesát loket, avšak hle, délka síní u průčelí chrámu sto loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'A odspodu těchto síní vedl příchod z východu, když se do nich vcházelo z vnějšího nádvoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Podél zdi nádvoří směrem na východ před odděleným prostorem a před stavbou byly síně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Cesta před nimi vypadala jako u síní, které byly směrem na sever. Jak jejich délka, tak jejich šířka i všechny jejich východy byly stejné jako uspořádání a jako vchody oněch síní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Jako vchody síní, které byly směrem jih, byl také vchod na začátku cesty -- cesty podél příslušné zdi, kudy se přicházelo směrem od východu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Tu mi řekl: Severní síně a jižní síně, které jsou před odděleným prostorem, jsou síně svaté, ⌈kde budou jíst nejsvětější věci kněží,⌉ kteří se přibližují k Hospodinu. Tam budou ukládat nejsvětější věci, přídavnou oběť, oběť za hřích a oběť za vinu, protože to místo je svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Když kněží vejdou, nebudou vycházet ze svatyně na vnější nádvoří, ale ponechají tam svá roucha, v nichž budou konat bohoslužbu, protože jsou svatá. Oblečou si jiná roucha a pak teprve ⌈budou přistupovat do prostoru, který je určen pro lid.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Tu ukončil měření u vnitř domu, vyvedl mě cestou k bráně, která svým průčelím míří směrem na východ, a změřil jej kolem dokola.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Změřil východní stranu měřicí třtinou: Obvod měl pět set měr měřicí třtiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Změřil severní stranu: Obvod měl pět set měr měřicí třtiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Na jižní straně naměřil pět set měr měřicí třtinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Obrátil se k západní straně a naměřil pět set měr měřicí třtinou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Změřil jej ze čtyř stran; má kolem dokola hradbu o délce pěti set a šířce pěti set měr, aby ⌈oddělovala svaté od obyčejného.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Pak mě přivedl k bráně, k té, která byla obrácená směrem na východ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'A hle, sláva Boha Izraele přicházela směrem od východu; jeho hlas zněl jako zvuk mnohých vod a ⌈země zasvítila od jeho slávy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'A to vidění, které jsem spatřil, bylo podobné jinému vidění, bylo podobné vidění, které jsem spatřil, když jsem přišel kvůli zničení města. ⌈A ta vidění byla i jako vidění, které jsem spatřil u řeky Kebaru. I padl jsem na tvář.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Hospodinova sláva vstoupila do domu cestou od brány, která svým průčelím mířila směrem na východ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Tu mě Duch pozdvihl, přenesl mě na vnitřní nádvoří a hle, ⌈Hospodinova sláva naplnila dům.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'A uslyšel jsem, jak ke mně mluví z domu, zatímco muž zůstal stát vedle mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Řekl mi: Lidský synu, spatřil jsi místo mého trůnu a místo mých chodidel tam, kde se navěky usídlím uprostřed synů Izraele. Dům izraelský, oni ani jejich králové již neznečistí mé svaté jméno svým smilstvem a mrtvolami svých králů na ⌈svých návrších,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'tím, že by kladli svůj práh u mého prahu a svou veřej vedle mé veřeje a že by mezi mnou a jimi byla pouze zeď. Znečistili mé svaté jméno svými ohavnostmi, které páchali, a já jsem s nimi ve svém hněvu skoncoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Nyní ode mne daleko vzdálí své smilstvo a mrtvoly svých králů a já se navěky usídlím uprostřed nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Ty, lidský synu, pověz domu izraelskému o tom domě, ať jsou zahanbeni pro své zvrácenosti a zaměří se na vzor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'A jestliže se zahanbí pro všechno, co spáchali, dej jim poznat uspořádání domu a jeho zařízení, jeho východy a jeho vchody, veškeré jeho uspořádání a všechna ustanovení o něm, všechna jeho uspořádání a všechny jeho zákony a zapiš před jejich očima, ať zachovávají veškeré jeho uspořádání a všechna ustanovení o něm a plní je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Toto je zákon domu: Celé jeho území na vrcholu hory kolem dokola je svatosvaté. Hle, toto je zákon domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'A toto byly rozměry oltáře v loktech (loket měřil loket a dlaň). Strouha byla loket hluboká, loket široká a obrubník na jejím lemu dokola byl široký jednu píď. Toto byla výška oltáře:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Od strouhy v zemi ke spodní římse byly dva lokte a šířka římsy jeden loket. Od malé římsy k velké to byly čtyři lokte a šířka římsy jeden loket.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Ohniště měřilo čtyři lokte. Od ohniště nahoru mířily čtyři rohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Ohniště mělo dvanáct loket délky na dvanáct šířky. Svými čtyřmi stranami tvořilo čtverec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'A římsa měla čtrnáct loket délky na čtrnáct šířky do čtyř stran. Obrubník okolo ní byl na půl lokte, okolo měla strouhu na loket. Stupně oltáře byly obráceny k východu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Pak mi řekl: Lidský synu, toto praví Panovník Hospodin: Toto jsou ustanovení ohledně oltáře pro den, kdy bude připraven, aby na něm přinášeli zápalnou oběť a aby na něj kropili krev:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Lévijským kněžím ze Sádokova potomstva, kteří se ke mně přibližují, aby mi sloužili -- je výrok Panovníka Hospodina -- dáš býčka, mládě ze skotu, pro oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Pak vezmeš z jeho krve a dáš na jeho čtyři rohy, ke čtyřem rohům římsy a k okolnímu obrubníku. Očistíš ho od hříchu a usmíříš jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Potom vezmeš býčka k oběti za hřích. Spálí ho na určeném místě domu venku mimo svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'A druhého dne přivedeš chlupatého kozla bez vady k oběti za hřích. Očistí oltář od hříchu tak, jako jej očistili od hříchu skrze býčka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Až jej přestaneš zbavovat od hříchu, přivedeš býčka, mládě bez vady ze skotu, a berana bez vady z bravu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Přivedeš je před Hospodinovu tvář. Kněží je posypou solí a přinesou je jako zápalnou oběť pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Po sedm dnů budeš obětovat jednoho chlupatého kozla na den v oběť za hřích. Budou též obětovat býčka, mládě ze skotu, a berana z bravu, oba bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Sedm dnů budou získávat smíření pro oltář a očišťovat jej. I ⌈posvětí jej.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Tak se ty dny dovrší. I stane se osmého dne, že kněží budou nadále konat na oltáři vaše zápalné a pokojné oběti a ⌈najdu ve vás zalíbení,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, '⌈Potom mě přivedl zpět cestou k bráně do vnější svatyně obrácené k východu.⌉ Ta byla zavřena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Hospodin mi řekl: Tato brána zůstane zavřena, nebude otevírána a člověk do ní nebude vstupovat, protože skrze ni vešel Hospodin, Bůh Izraele. Zůstane zavřena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Až na knížete; sám kníže v ní bude sedávat, aby ⌈jedl chléb před Hospodinem.⌉ Přijde cestou z předsíně brány a stejnou cestou odejde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Pak mě přivedl skrze severní bránu před dům a hle, uviděl jsem, jak Hospodinova sláva naplnila Hospodinův dům. Tu jsem padl na tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Hospodin mi řekl: Lidský synu, věnuj tomu pozornost, pohleď svýma očima a svýma ušima poslyš všechno, co ti povídám o všech ustanoveních Hospodinova domu a o všech jeho zákonech. Budeš věnovat pozornost ⌈vchodu do domu s veškerými východy⌉ ze svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, '⌈Řekni vzpurnému domu izraelskému:⌉ Toto praví Panovník Hospodin: Dost bylo všech vašich ohavností, dome izraelský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'když jste přiváděli cizince ⌈neobřezaného srdce⌉ a neobřezaného těla, aby byli v mé svatyni, aby ji znesvěcovali s celým mým domem, když jste mi přinášeli za pokrm tuk a krev a oni porušovali mou smlouvu -- mimo všech vašich dalších ohavností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Nekonali jste službu při mých svatých věcech. Ustanovili jste je, aby konali mou službu v mé svatyni za vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Toto praví Panovník Hospodin: ⌈Žádný cizinec neobřezaného srdce a neobřezaného těla nevstoupí do mé svatyně. To platí pro každého cizince, který přebývá uprostřed synů Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Pokud jde totiž o Lévijce, kteří se ode mne vzdálili, když Izrael zbloudil, kteří ode mne zbloudili za svými bůžky, ti ponesou svou zvrácenost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Budou v mé svatyni sloužit jako dozorci u bran domu a sloužit kolem domu. Oni budou porážet zápalnou oběť a obětní hod pro lid, oni budou před nimi stát, aby jim sloužili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Jelikož budou pro dům izraelský zvráceností ku pohoršení, když s nimi budou konat bohoslužbu před jejich bůžky, proto jsem proti nim pozvedl ruku, je výrok Panovníka Hospodina, a ponesou svou zvrácenost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Nepřiblíží se ke mně, aby mi sloužili jako kněží a aby se přiblížili ke všem mým svatým věcem, natož k těm nejsvětějším. Ponesou svou ostudu a své ohavnosti, které spáchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Dám je, aby konali službu u domu, pro veškerou práci kolem něj a pro všechno, co se v něm má konat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Avšak lévijští kněží, synové Sádokovi, kteří konali službu u mé svatyně, když ode mne synové Izraele zbloudili, ti se ke mně budou přibližovat, aby mi sloužili. Budou stát přede mnou, aby mi přinášeli tuk a krev, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Oni budou vcházet do mé svatyně, oni se budou přibližovat k mému stolu, aby mi sloužili; budou konat mou službu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'I stane se, když budou vcházet do bran vnitřního nádvoří, že ⌈si oblečou lněná roucha.⌉ Nepřijde na ně vlna, když budou sloužit v branách vnitřního nádvoří a v domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Na jejich hlavě budou lněné turbany a na jejich bedrech budou lněné spodky. Nepřepásají se ⌈ ničím, co by vyvolalo pocení.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Když budou vycházet do vnějšího nádvoří, do vnějšího nádvoří k lidu, svléknou svá roucha, v nichž slouží, a ponechají je ve svatých síních. Oblečou si jiná roucha a nebudou svými rouchy posvěcovat lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Nebudou si holit hlavu ani si nebudou rozpouštět narostlé vlasy. Hlavy si pečlivě ostříhají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Žádný kněz nebude pít víno, má –li vstoupit do vnitřního nádvoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Vdovu ani zapuzenou si nevezmou za ženu, nýbrž vezmou si jedině panny z potomstva domu izraelského nebo vdovu po knězi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Můj lid budou vyučovat rozdílu mezi svatým a obyčejným a budou jim oznamovat rozdíl mezi nečistým a čistým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Oni se při sporu postaví za právo a rozhodnou jej podle mých právních nařízení. Budou zachovávat mé zákony a má ustanovení o všech mých svátcích a budou světit mé soboty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'K mrtvému člověku žádný z nich nepřistoupí, aby se neposkvrnil. Mohou se poskvrňovat pouze při otci nebo při matce, při synovi nebo při dceři, při bratrovi nebo při sestře, která se nevdala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Po očišťování kněze k němu připočtou ještě sedm dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'V den, kdy přijde do svatyně na vnitřní nádvoří, aby sloužil ve svatyni, přinese svou oběť za hřích, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Toto jim bude za dědictví: ⌈Já budu jejich dědictvím. Nedáte jim vlastnictví v Izraeli; já jsem jejich vlastnictvím.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Oni budou jíst přídavnou oběť, oběť za hřích a oběť za vinu. ⌈Bude jim patřit všechno, co bude v Izraeli zasvěceno zkáze.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Prvotina všech prvotin ze všeho a každý dar pozdvihování ze všeho, ze všech vašich darů pozdvihování, bude pro kněze. Prvotinu svého těsta dáte knězi, aby na vašem domě spočinulo požehnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Kněží nebudou jíst žádnou mršinu ani rozsápané zvíře z ptactva a ze zvěře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Až převezmete zemi do dědictví, přinesete Hospodinu dar pozdvihování, svatý díl ze země o délce dvacet pět tisíc a šířce deset tisíc měr. Bude svatý kolem dokola na celém svém území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Z toho připadne pro svatyni čtvercový díl pět set na pět set po obvodu. Okolo bude mít padesát loket pastviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Z této plochy tedy odměříš délku dvacet pět tisíc a šířku deset tisíc měr. Tam bude svatyně, nejsvětější místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'To bude ⌈svatý díl ze země⌉ pro kněze, služebníky svatyně, kteří se přibližují, aby sloužili Hospodinu. Bude to místo na domy pro ně a svaté místo pro svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Dvacet pět tisíc měr délky a deset tisíc šířky. Bude pro lévity, služebníky domu; budou mít ve vlastnictví ⌈dvacet síní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Městu dáte do vlastnictví pět tisíc měr šířky a dvacet pět tisíc délky podél svatého dílu -- daru pozdvihování. Bude pro celý dům izraelský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'A kníže bude mít díl z jedné i z druhé strany svatého dílu pro dar pozdvihování i vlastnictví města, u svatého dílu pro dar pozdvihování a u vlastnictví města, ze západní strany na západ a z východní strany na východ. Délka bude odpovídat jednomu z dílů od západní hranice k východní hranici');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'země; bude pro něho vlastnictvím v Izraeli. A má knížata už nebudou utiskovat můj lid, ale zemi dají domu izraelskému, jejich kmenům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Toto praví Panovník Hospodin: Bylo toho dost, izraelská knížata! Odstraňte násilí a zkázu, konejte právo a spravedlnost. Zanechte vyhánění mého lidu, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Budete mít spravedlivé misky vah, spravedlivou éfu a spravedlivý bat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, '⌈Éfa a bat bude jedna míra, takže bat bude obsahovat desetinu chómeru. I éfa bude desátý díl chómeru, její výměr bude podle chómeru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Dále: Šekel bude mít dvacet gér. Dvacet šekelů, dvacet pět šekelů a patnáct šekelů pro vás bude jedna hřivna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Toto je dar pozdvihování, který budete přinášet: šestinu éfy z chómeru pšenice a na šest částí rozdělíte i éfu z chómeru ječmene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Dále ustanovení o oleji: Bat je míra oleje, desetina batu z kóru; deset batů na chómer, protože chómer je deset batů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Dále: Jedna ovce na stádo o dvou stech kusech ze zavlažované oblasti Izraele na přídavnou oběť, ⌈na zápalnou oběť a na pokojnou oběť, aby pro ně bylo získáno smíření,⌉ je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Všechen lid země bude zavázán k tomuto daru pozdvihování knížeti v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'A na knížeti bude spočívat odpovědnost za zápalné oběti, přídavnou oběť a litou oběť o svátcích, při novoluních a o sobotách, ve všech shromážděních domu izraelského. On vykoná oběť za hřích a přídavnou oběť, zápalnou oběť i pokojné oběti, aby za dům izraelský získal smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, '⌈Toto praví Panovník Hospodin: V prvním měsíci, prvního dne toho měsíce vezmeš býčka, mládě bez vady ze skotu, a očistíš svatyni od hříchu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Kněz tehdy vezme trochu krve oběti za hřích a dá na veřej domu, na čtyři rohy římsy na oltáři i na veřej brány vnitřního nádvoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, '⌈Tak učiníš i sedmého dne v měsíci za každého bloudícího a za prostoduchého. Získáš pro dům smíření.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'V prvním měsíci, čtrnáctého dne toho měsíce budete mít Velikonoce. ⌈ Po svátek týdnů se budou jíst denně nekvašené chleby.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Kníže v onen den připraví za sebe a za všechen lid země býčka jako oběť za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Sedm dnů svátku bude připravovat jako zápalnou oběť Hospodinu sedm býčků a sedm beranů bez vady na den po sedm dnů a jako oběť za hřích chlupatého kozla na den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Dále připraví jako přídavnou oběť éfu na býčka a éfu na berana a hín oleje na éfu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'V sedmém měsíci, patnáctého dne toho měsíce, ve svátek, učiní totéž jako v těch sedmi dnech, jak při oběti za hřích, tak i při zápalné i přídavné oběti a při obětování oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Toto praví Panovník Hospodin: Brána vnitřního nádvoří obrácená k východu zůstane zavřena šest pracovních dnů. Bude otevírána v den sobotní, bude otevírána i v den novoluní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, '⌈Tehdy přijde kníže zvenku cestou z předsíně brány a postaví se k veřeji brány.⌉ Kněží vykonají jeho zápalnou oběť a jeho pokojnou oběť, on se bude klanět na prahu brány a pak odejde. Brána však nebude zavřena až do večera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'I lid země se bude klanět u vchodu té brány o sobotách a při novoluních před Hospodinem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Zápalná oběť, kterou kníže přivede Hospodinu v den sobotní: ⌈šest beránků bez vady a berana⌉ bez vady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Dále přídavná oběť: éfa na berana a na beránky jako přídavná oběť, kolik může dát; též hín oleje na éfu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, '⌈V den novoluní pak býček, mládě bez vady ze skotu, šest beránků a beran; budou bez vady.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Připraví i přídavnou oběť: éfu na býčka, éfu na berana a na beránky, tak, jak bude stačit; též hín oleje na éfu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Až bude kníže přicházet, přijde cestou z předsíně brány a stejnou cestou zase odejde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Ale když bude přicházet lid země před Hospodinem do shromáždění, ten, kdo přichází skrze severní bránu, aby se klaněl, odejde skrze bránu jižní a ten, kdo přichází skrze jižní bránu, odejde skrze bránu severní. ⌈Nebude se vracet skrze tu bránu, kterou přišel, nýbrž odejde naproti ní.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'I kníže vejde uprostřed nich, když vejdou oni a když oni vyjdou, vyjde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'O svátcích a při shromážděních bude jako přídavná oběť éfa na býčka, éfa na berana a na beránky, kolik může dát; též hín oleje na éfu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Pokud kníže připraví dobrovolnou zápalnou oběť nebo dobrovolnou pokojnou oběť Hospodinu, otevře se mu brána obrácená na východ a on vykoná svou zápalnou oběť a svou pokojnou oběť stejně, jako to učiní v den sobotní. Odejde a brána se zavře poté, co on vyjde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Beránka bez vady ve věku jednoho roku připravíš denně jako zápalnou oběť Hospodinu. Ráno co ráno jej připravíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Připravíš k němu též přídavnou oběť, ráno co ráno šestinu éfy a třetinu hínu oleje k pokropení jemné mouky. To jsou trvale věčná ustanovení přídavné oběti pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Připraví beránka, přídavnou oběť a olej ráno co ráno; ustavičnou zápalnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Toto praví Panovník Hospodin: Pokud dá kníže dar někomu ze svých synů, bude to jeho dědictví pro jeho syny. Bude to jejich vlastnictví v dědičném podílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Pokud však dá dar ze svého dědictví jednomu ze svých otroků, bude mu patřit až do léta propuštění a pak to knížeti vrátí. Jeho dědictví náleží jen jeho synům, bude patřit jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Kníže nevezme z dědictví lidu, aby je vytlačoval z jejich vlastnictví. Svým synům dá dědictví ze svého vlastnictví, aby se tak můj lid nerozprchl, každý od svého vlastnictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Potom mě přivedl vchodem, který je na boku brány, ⌈ke svatým síním pro kněze,⌉ obráceným na sever. Hle, tam je místo na dvou odlehlých stranách na západě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'A řekl mi: Toto je to místo, kde budou kněží vařit oběť za vinu a oběť za hřích; kde budou péci přídavnou oběť, aby to nevynášeli na vnější nádvoří, aby ne posvěcovali lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Pak mě vyvedl k vnějšímu nádvoří a provedl mě podle čtyř rohů nádvoří. A hle, ⌈v každém rohu nádvoří bylo ještě jiné nádvoří.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Ve čtyřech rozích nádvoří jsou nezastřešená nádvoří čtyřicet měr na délku a třicet na šířku. Všechna čtyři mají stejný rozměr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'A všechna čtyři jsou v nich obehnána dokola ohradou. Pod hradbami všude okolo jsou udělána topeniště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'A řekl mi: Toto jsou kuchyně, kde budou služebníci domu vařit obětní hod lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Potom mě přivedl zpět ke vchodu do domu a hle, odspodu prahu domu vyvěrala voda na východ; průčelí domu totiž mířilo na východ. Voda plynula zdola z pravé strany domu jižně od oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Vyvedl mě skrze severní bránu a vedl mě okolo směrem ven k venkovní bráně ⌈obrácené směrem na východ.⌉ A hle, voda crčela z pravé strany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Když ten muž vycházel k východu ⌈ se šňůrou v ruce,⌉ odměřil tisíc loket a provedl mě skrze vodu; vody bylo po kotníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Pak odměřil další tisíc a provedl mě skrze vodu; vody bylo po kolena. Opět odměřil tisíc a provedl mě vodou po bedra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Potom odměřil další tisíc a byl tu potok, kterým jsem nebyl schopen projít, protože voda vystoupila na úroveň vody k plavání, potoka, který se ne dá přebrodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'A řekl mi: Viděl jsi přece, lidský synu. Vedl mě a přivedl mě zpět na břeh toho potoka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Když jsem se vrátil, hle, na jednom i druhém břehu potoka bylo velmi mnoho stromoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Pak mi řekl: Tato voda vytékající do východní oblasti stekla do Araby. Pronikla až do moře, a když se vlila do moře, byla jeho voda uzdravena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'I stane se, že každá živá duše, která se bude hemžit všude, kam pronikne potok, bude žít a bude tam velmi mnoho ryb, neboť tam pronikla tato voda. Kamkoli potok pronikne, všechno bude uzdraveno a ožije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'A stane se, že se k němu postaví rybáři. Od Én–gedí až do Én–eglajimu budou místa k rozprostírání sítí. Co se týče druhu, bude tam ryb velmi mnoho, jako ryb Velikého moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Jeho bažiny a jeho mokřiny však nebudou uzdraveny; byly vydány pro těžbu soli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'A podle toho potoka vyroste na jednom i druhém břehu všelijaké ovocné stromoví; jeho listí nebude vadnout a jeho ovoce neopadá. Po všechny měsíce ponese rané ovoce, protože voda pro něj vytéká ze svatyně. Jeho ovoce bude k jídlu a jeho listí k léčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Toto praví Panovník Hospodin: Toto je území, na kterém rozdělíte zemi do dědictví pro dvanáct izraelských kmenů. ⌈Josef bude mít dva díly.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, '⌈Jeden jako druhý⌉ ji zdědíte, zemi, o níž jsem pozvedl svou ruku k přísaze, že ji dám vašim otcům. Tato země vám připadne do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'A toto je hranice země: Na severní straně od Velikého moře cestou k Chetlonu, kudy se přichází k Sedadu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Chamát, Beróta a Sibrajim, který je mezi územím Damašku a územím Chamátu; Chasér–tíkón, který leží při hranici Chavránu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Od moře pak bude hranicí Chasar–énón, hranice Damašku, daleký sever a hranice Chamátu. To je severní strana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Východní stranu odměříte mezi Chavránem a mezi Damaškem, mezi Gileádem a mezi izraelskou zemí; Jordán od hranice k Východnímu moři. To je východní strana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Jižní strana pak vede na jih od Támaru až k ⌈Vodám sváru v Kádeši,⌉ k Nachale k Velikému moři. To je jižní strana na jihu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'A západní strana: Veliké moře od hranice až proti Lebo–Chamátu. Toto je západní strana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Rozdělíte si tuto zemi mezi izraelské kmeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'I stane se, že ji přidělíte do dědictví sobě a příchozím, kteří pobývají jako cizinci uprostřed vás, kteří uprostřed vás zplodili syny. ⌈Budou pro vás jako domorodec mezi syny Izraele, budou s vámi spadat do dědictví uprostřed izraelských kmenů.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'I stane se, že v kmeni, v němž s vámi ten příchozí pobýval, tam mu dáte dědictví, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Toto jsou jména kmenů: Od severní končiny vedle cesty do Chetlonu, Lebo–Chamátu a Chasar–énanu, u hranice Damašku na sever vedle Chamátu bude mít Dan od východní strany k západní jeden díl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Při Danově území pak od východní strany až po stranu západní jeden díl Ašerovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Při Ašerově území pak od východní strany až po stranu západní jeden díl Neftalímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Při území Neftalího od východní strany až po stranu západní jeden díl Manasesovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Při Manasesově území od východní strany až po stranu západní jeden díl Efrajimovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Při Efrajimově území od východní strany až po stranu západní jeden díl Rúbenovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Při Rúbenově území od východní strany až po stranu západní jeden díl Judovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Při Judově území od východní strany až po stranu západní bude dar pozdvihování, který přinesete -- o šířce dvacet pět tisíc měr a délce jako každý z jiných dílů od východní strany až po stranu západní -- a uprostřed něj bude svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Dar pozdvihování, který přinesete Hospodinu, bude mít délku dvacet pět tisíc a šířku deset tisíc měr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Těmto pak bude ten svatý dar pozdvihování určen: Kněžím. Na severu dvacet pět tisíc a na západě deset tisíc měr šířky, na východě deset tisíc měr šířky a na jihu dvacet pět tisíc měr délky. Uprostřed něj bude Hospodinova svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Bude pro kněze, ty posvěcené ze synů Sádokových, kteří konali mou službu, ⌈kteří nezbloudili, když zbloudili synové Izraele, tak jako bloudili Lévijci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Bude jim patřit část z daru pozdvihování té svatosvaté země při lévijském území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Lévijci pak budou mít podél území kněží díl o délce dvacet pět tisíc a šířce deset tisíc měr. Veškerá délka činí dvacet pět tisíc a šířka deset tisíc měr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Nebudou z něj prodávat, vyměňovat ani převádět prvotinu země, protože je svatý pro Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Zbývajících pět tisíc měr na šířku naproti dvaceti pěti tisícům je pak obyčejný díl pro město, pro sídlo i pro pastvinu. Město bude uprostřed něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'A toto jsou jeho rozměry: severní strana čtyři tisíce pět set a jižní strana čtyři tisíce pět set měr. Z východní strany čtyři tisíce pět set a západní strana čtyři tisíce pět set měr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Město bude mít pastvinu dvě stě padesát měr na sever a dvě stě padesát na jih, dále dvě stě padesát měr na východ a dvě stě padesát na západ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Zbývající díl na délku podél svatého daru pozdvihování: Deset tisíc měr na východ a deset tisíc na západ bude podél svatého daru pozdvihování. Jeho úroda bude za pokrm těm, kdo pracují pro město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Budou na něm sloužit ti, kdo pracují pro město, ze všech izraelských kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Celý dar pozdvihování činí dvacet pět tisíc na dvacet pět tisíc měr. Čtverec přinesete jako svatý dar pozdvihování do vlastnictví města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Zbývající díl pak bude pro knížete z jedné i z druhé strany svatého daru pozdvihování a vlastnictví města podél dvaceti pěti tisíců měr daru pozdvihování až k území na východě a na západě podél dvaceti pěti tisíců měr na území na západě vedle dílu pro knížete. Svatý dar pozdvihování a svatyně domu bude uprostřed.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Též z vlastnictví Lévijců a z vlastnictví města, uprostřed něhož bude patřit díl knížeti. Mezi územím Judovým a územím Benjamínovým bude díl pro knížete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Dále zbytek kmenů: Od východní strany až po stranu západní jeden díl Benjamínovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Při Benjamínově území od východní strany až po stranu západní jeden díl Šimeónovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Při Šimeónově území od východní strany až po stranu západní jeden díl Isacharovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Při Isacharově území od východní strany až po stranu západní jeden díl Zabulónovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Při Zabulónově území od východní strany až po stranu západní jeden díl Gádovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Při Gádově území k jižní straně na jih. Území bude dosahovat od ⌈Támaru k Vodám sváru v Kádeši, k Nachale u Velikého moře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Toto je země, kterou převezmete jako dědictví pro izraelské kmeny. A toto jsou jejich příděly, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Toto jsou východy z města: Ze severní strany rozměr čtyři tisíce pět set měr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Brány města jsou pak podle jmen izraelských kmenů; tři brány na sever: jedna brána Rúbenova, jedna brána Judova a jedna brána Léviho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'K východní straně čtyři tisíce pět set měr a tři brány: jedna brána Josefova, jedna brána Benjamínova a jedna brána Danova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Jižní strana má rozměr čtyři tisíce pět set měr a tři brány: jedna brána Šimeónova, jedna brána Isacharova a jedna brána Zabulónova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Západní strana -- čtyři tisíce pět set měr a tři jejich brány: jedna brána Gádova, jedna brána Ašerova a jedna brána Neftalího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Obvod měří osmnáct tisíc měr. ⌈Město má od toho dne jméno: ⌈Hospodin tam⌉ přebývá.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Ve třetím roce kralování judského krále Jójakíma přitáhl babylonský král Nebúkadnesar k Jeruzalému a oblehl jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Panovník Hospodin mu tehdy do ruky vydal judského krále Jójakíma i některé předměty domu Božího, on je vzal s sebou do země Šineár, do domu svého boha, a ty předměty přinesl do chrámové klenotnice svého boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Král pak řekl Ašpenazovi, vrchnímu komorníkovi, aby ze synů Izraele, jak z královského potomstva, tak ze šlechty, přivedl');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'mladíky, kteří nemají žádnou vadu, hezkého vzhledu, rozumné v každém ohledu, vzdělané i chápavé, kteří jsou schopni sloužit v královském paláci a učit se chaldejskému písemnictví a jazyku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Král jim nechal stanovit denní dávku z královského přídělu a z jeho banketního vína, aby je tři roky vychovával a někteří z nich aby sloužili králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Mezi nimi byli ze synů Judových Daniel, Chananjáš, Míšael a Azarjáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Vrchní komorník jim dal jména -- Danielovi dal Beltšasar, Chananjášovi Šadrak, Míšaelovi Méšak a Azarjášovi Abed–nego.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Daniel si ale vzal na srdce, že se nebude poskvrňovat královským přídělem a jeho banketním vínem, a snažil se dosáhnout u vrchního komorníka, aby se ne musel poskvrňovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Tehdy Bůh dal dojít Danielovi u vrchního komorníka milosrdenství a slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Přesto řekl vrchní komorník Danielovi: Bojím se svého pána, krále, který vám nechal stanovit jídlo a pití. ⌈Jestliže uvidí, že vypadáte přepadleji než mladíci vašeho věku, připravíte mě u krále o hlavu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Daniel tedy řekl správci, kterého Danielovi, Chananjášovi, Míšaelovi a Azarjášovi přidělil vrchní komorník:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Vyzkoušej prosím své otroky během deseti dnů. Ať nám dávají ⌈k jídlu nějakou zeleninu a k pití vodu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Pak se před tebou ukáže, jak vypadáme a jak vypadají ti mladíci, kteří se stravují z královského přídělu. A jak uvidíš, tak se svými otroky nalož.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'On je v této věci poslechl a po deset dnů je zkoušel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Po uplynutí deseti dnů bylo vidět, že vypadali dobře a více při těle než všichni ti mladíci stravující se z královského přídělu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Proto jim správce odnášel královský příděl i jejich banketní víno a dával jim zeleninu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Této čtveřici mladíků dal Bůh, že znali všechno písemnictví i moudrost a rozuměli tomu, Danielovi nadto dal chápat každé vidění a sny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Po uplynutí doby, kdy měli být přivedeni, jak řekl král, přivedl je vrchní komorník před Nebúkadnesara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Král s nimi hovořil a mezi nimi všemi se nenašel nikdo jako Daniel, Chananjáš, Míšael a Azarjáš. Nastoupili tedy službu před králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'A ⌈vždy, kdykoli po nich král žádal moudré chápání,⌉ shledal, že desetkrát převyšují všechny kouzelníky a věštce v celém jeho království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Daniel sloužil až do prvého roku krále Kýra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Ve druhém roce Nebúkadnesarova kralování se Nebúkadnesarovi zdály nějaké sny. ⌈ V duchu se rozrušil, ale spánek jej opět přemohl.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Později král přikázal svolat kouzelníky a věštce i čaroděje a chaldejce, aby králi vyprávěli jeho sny. Ti tedy přišli a postavili se před králem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Král jim řekl: Zdál se mi nějaký sen. ⌈Můj duch je rozrušen, musím ten sen znát.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Chaldejci promluvili ke králi (aramejsky): Králi, navěky buď živ! Pověz ten sen svým otrokům a my předneseme výklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Nato ⌈král chaldejcům odpověděl:⌉ Už ⌈jsem se v té věci rozhodl.⌉ Jestliže mi ten sen ani jeho výklad nesdělíte, budete rozčtvrceni a z vašich domů bude hromada sutin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Jestliže ale přednesete sen i jeho výklad, obdržíte z mé strany dary a odměnu i velikou čest. Raději mi sen i jeho výklad předneste!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Odpověděli po druhé a řekli: Král nechť ten sen řekne svým otrokům a my předneseme jeho výklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Nato král odvětil: S jistotou vím, že získáváte čas, jelikož jste zjistili, že v té věci jsem se už rozhodl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'že pokud mi ten sen nesdělíte, je pro vás jediný soud. Vy jste se totiž domluvili, že budete přede mnou říkat věci lživé a pokroucené, dokud se nezmění čas. Raději mi ten sen řekněte, a tak zjistím, že mi budete moci přednést i jeho výklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Chaldejci odpověděli před králem takto: Není člověka na zemi, který by dokázal ⌈vykládat podle králova slova.⌉ Vždyť žádný veliký král ani pán něco takového nežádal po žádném kouzelníkovi ani věštci ani chaldejci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Ta věc, kterou král žádá, je totiž příliš vznešená a není nikoho jiného, kdo by ji mohl přednášet před králem, kromě bohů, ⌈kteří své sídlo u lidí nemají.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Kvůli tomu se král rozzlobil, ba převelice rozlítil a všechny babylonské mudrce rozkázal vyhladit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Vyšlo tedy nařízení a ti mudrci byli pobíjeni. Vyhledali také Daniela a jeho přátele, aby je zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Tehdy Daniel odpověděl pohotově i rozvážně veliteli královské stráže Arjókovi, který vyšel pobíjet babylonské mudrce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Odpověděl Arjókovi a řekl: Královský pane, proč to nařízení ze strany krále tolik spěchá? Arjók tedy oznámil tu věc Danielovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Daniel potom ⌈šel prosit u krále,⌉ aby mu dal nějakou dobu, že ten výklad králi přednese.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Pak Daniel odešel do svého domu a tu věc oznámil svým přátelům Chananjášovi, Míšaelovi a Azarjášovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'ať ohledně toho tajemství vyprošují slitování od Boha nebes, aby Daniela a jeho přátele nezahladili s ostatními babylonskými mudrci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Tehdy bylo to tajemství Danielovi zjeveno v nočním vidění, tehdy Daniel dobrořečil Bohu nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel promluvil a řekl: Budiž jméno Boží požehnáno od věků na věky. Neboť moudrost i sílu má on;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'časy i příležitosti mění on. Krále sesazuje, krále nastoluje; mudrcům moudrost dává a poznání těm, kdo umějí pochopit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'On zjevuje hlubiny a věci ukryté. Ví, co je v temnotě; s ním však přebývá světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Tebe, ⌈Bože mých otců,⌉ chválím a uctívám, dals mi totiž moudrost i sílu a oznámils mi teď, čeho jsme si od tebe prosili, věc královu oznámil jsi nám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Proto se Daniel vydal k Arjókovi, kterého král pověřil vyhlazením babylonských mudrců. Přišel a toto mu řekl: Babylonské mudrce nevyhlazuj! Uveď mne před krále a já ten výklad králi přednesu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Nato Arjók Daniela poděšeně uvedl před krále a toto mu řekl: Nalezl jsem muže ze synů judských vysídlenců, který může ten výklad králi sdělit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Král promluvil a řekl Danielovi, jehož jméno bylo Beltšasar: Ty že bys byl schopen mi sdělit ten sen, který jsem viděl, a jeho výklad?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Nato Daniel před králem prohlásil: To tajemství, na něž se král táže, žádní mudrci, věštci, kouzelníci ani drobopravci přednést králi ne mohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Avšak jest Bůh na nebesích, zjevující tajemství -- a ten králi Nebúkadnesarovi sdělil, co se stane v budoucích dnech. Tvůj sen a vidění, která jsi ve svém nitru měl na loži, byla tato:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Tobě, králi, na loži přišlo na mysl, co se asi stane později. A ten, kdo zjevuje tajemství, ti sdělil, co se stane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'A pokud jde o mne, mně to tajemství zjevil nikoli pro moudrost, jež by ve mně byla nade vše živé, ale z toho důvodu, aby ten výklad mohli sdělit králi, abys poznal to, o čem tvé nitro přemýšlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Tys, králi, hleděl a vtom hle, jakási náramná socha. Byla to socha veliká, vzhledu neobyčejného. Stála před tebou a její vzezření budilo úděs.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Byla to socha mající hlavu z ryzího zlata, hruď a paže ze stříbra, břicho a boky bronzové,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'lýtka železná, chodidla zčásti železná, zčásti keramická.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Jak ses díval, vylomil se bez rukou nějaký kámen a udeřil té soše do chodidel ze železa i keramiky a rozdrtil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Tehdy se železo, keramika, bronz, stříbro i zlato naráz rozpadly a byly jako plevy v létě na mlatech. Tu je roznesl vítr a už pro ně nebylo místo. Avšak ten kámen, jenž udeřil do sochy, se stal velikou horou a zaplnil celou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'To byl ten sen. Také jeho výklad povíme králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, '⌈Ty, králi, jsi král králů, neboť Bůh nebes dal tobě království, moc, sílu i čest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'A všechno, kde přebývají lidští synové, polní zvěř i nebeské ptactvo, dal tobě do ruky a učinil tě vládcem nad tím vším. Ta zlatá hlava jsi ty.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Ale po tobě povstane jiné království, země horší než tvá, a jiné, třetí království, bronzové, které bude vládnout nad celou zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'A pak čtvrté království, to bude silné jako železo, neboť železo drtí a podrobuje všechno, a jako železo, jež tyhle všechny rozbíjí, tak bude drtit a rozbíjet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'A že jsi viděl ta chodidla a prsty částečně z hrnčířské keramiky a částečně ze železa, půjde o království rozdělené a bude v něm cosi z pevnosti železa, neboť jsi viděl železo promíšené s hliněnou keramikou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Pak ty prsty chodidel částečně železné a částečně keramické: To království bude z jedné strany silné a z druhé strany bude křehké.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Že jsi viděl železo promíšené s hliněnou keramikou -- lidé se budou mísit, ale držet jeden s druhým nebudou, právě tak jako se železo nemísí s keramikou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Za dnů oněch králů ale Bůh nebes nastolí království, jež nebude zničeno navěky ani to království nebude přenecháno jinému lidu. Ono rozdrtí a ukončí všechna tato království, ale samo bude stát navěky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'neboť jsi viděl, jak se bez rukou z té hory vylomil kámen a rozdrtil železo, bronz, keramiku, stříbro i zlato. Veliký Bůh oznámil králi, co se stane potom. Ten sen je pravdivý a jeho výklad spolehlivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Nato král Nebúkadnesar padl na tvář, Danielovi se klaněl a rozkázal jej obdarovat i oblažovat vůní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Král Danielovi odpověděl a řekl: Opravdu, váš bůh je bůh bohů a pán králů, ten, kdo zjevuje tajemství. Vždyť tys dokázal toto tajemství odhalit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Poté král Daniela povýšil, dal mu mnoho velikých darů a učinil jej vládcem nad celou babylonskou provincií a nejvyšším prefektem nade všemi babylonskými mudrci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Daniel si ale od krále vyžádal, aby správou babylonské provincie pověřil Šadraka, Méšaka i Abed–nega, kdežto Daniel zůstal na královském dvoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Král Nebúkadnesar vyrobil zlatou sochu. Její výška byla šedesát loket, její šířka šest loket. Dal ji postavit na pláni Dúra v babylonské provincii.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Potom král Nebúkadnesar vzkázal shromáždit satrapy, prefekty a místodržitele, radní, pokladníky, soudce, komisaře a všechny úředníky provincií, aby přišli k zasvěcení té sochy, kterou dal postavit král Nebúkadnesar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Nato se shromáždili satrapové, prefekti a místodržitelé, radní, pokladníci, soudcové, komisaři a všichni úředníci provincií k zasvěcení té sochy, kterou dal postavit král Nebúkadnesar. Když stáli před tou sochou, kterou dal postavit Nebúkadnesar,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'hlasatel mocně volal: Přikazuje se vám, lidé, národy a jazyky:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'V čase, kdy uslyšíte hrát roh, píšťalu, citeru, lyru, cymbál, orchestr ⌈či jiný hudební nástroj,⌉ padnete a budete se klanět té zlaté soše, kterou dal postavit král Nebúkadnesar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Kdokoli by však nepadl a neklaněl se, v tom okamžiku bude uvržen doprostřed rozpálené ohnivé pece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Proto v té době, jakmile všichni lidé slyšeli hrát roh, píšťalu, citeru, lyru, cymbál ⌈či jiný hudební nástroj,⌉ padali všichni lidé, národy i jazyky a klaněli se zlaté soše, kterou dal postavit král Nebúkadnesar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Kvůli tomu předstoupili v oné době nějací muži Chaldejci a pustili se do Judejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Promluvili a řekli králi Nebúkadnesarovi: Králi, navěky buď živ!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Sám jsi, králi, vydal nařízení, aby každý člověk, jenž uslyší hrát roh, píšťalu, citeru, lyru, cymbál, orchestr ⌈či jiný hudební nástroj,⌉ padl a klaněl se té zlaté soše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Kdokoli by však nepadl a neklaněl se, bude uvržen doprostřed rozpálené ohnivé pece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Jsou nějací muži -- Judejci, které jsi pověřil správou babylonské provincie: Šadrak, Méšak a Abed–nego -- tihle muži na tebe, králi, neberou zřetel, tvé bohy neuctívají a té zlaté soše, kterou jsi dal postavit, se neklanějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Nato Nebúkadnesar v hněvu a rozlícení poručil přivést Šadraka, Méšaka i Abed–nega. Oni muži byli hned přivedeni před krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebúkadnesar promluvil a řekl jim: Je to úmysl, Šadraku, Méšaku a Abed–nego, že mé bohy neuctíváte a té zlaté soše, kterou jsem dal postavit, se neklaníte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Jestlipak jste teď připraveni, že v čase, kdy uslyšíte hrát roh, píšťalu, citeru, lyru, cymbál, orchestr ⌈či jiný hudební nástroj,⌉ padnete a budete se klanět té soše, kterou jsem vyrobil? Ale jestli se klanět nebudete, v tu hodinu budete uvrženi doprostřed rozpálené ohnivé pece. A kdo je bůh, že by vás vysvobodil z mé ruky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Šadrak, Méšak i Abed–nego odpověděli a řekli králi: Ó, Nebúkadnesare, na to my tobě nemusíme dávat žádnou odpověď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Je–li tomu tak, náš Bůh, jehož uctíváme, nás může vysvobodit z rozpálené ohnivé pece. I ze tvé ruky, králi, nás vysvobodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Ale i kdyby ne, známo buď tobě, králi, že tvé bohy uctívat nebudeme a té zlaté soše, kterou jsi dal postavit, se nebudeme klanět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Rázem Nebúkadnesara naplnil hněv a výraz jeho tváře se vůči Šadrakovi, Méšakovi i Abed–negovi změnil. Ihned přikázal tu pec rozpálit sedmkrát více, než ji obvykle rozpalovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Pak ⌈udatným bojovníkům ze svého vojska⌉ přikázal, aby Šadraka, Méšaka i Abed–nega svázali, aby byli uvrženi do rozpálené ohnivé pece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Oni muži byli hned svázáni ještě ve svých kabátech, kalhotách, turbanech a ve svém oblečení a uvrženi doprostřed rozpálené ohnivé pece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Protože králův rozkaz byl tak prudký a ta pec byla neobyčejně rozpálena, ony muže, kteří Šadraka Méšaka i Abed–nega zvedali, pozabíjel plamen ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Ale ti tři muži, Šadrak, Méšak i Abed–nego, svázáni dopadli doprostřed rozpálené ohnivé pece.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Král Nebúkadnesar se náhle zhrozil a poděšeně vstal. Promluvil na své rádce a řekl: Copak jsme doprostřed ohně neuvrhli trojici svázaných mužů?! Odpověděli králi a řekli: Určitě, králi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Nato řekl: Hle, vidím čtveřici mužů rozvázaných, jak si chodí uprostřed ohně, nemají žádné zranění a vzhled toho čtvrtého připomíná nějakého syna bohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Pak Nebúkadnesar přistoupil ke vstupu do rozpálené ohnivé pece a řekl: Šadraku, Méšaku a Abed–nego, otroci boha Nejvyššího, vylezte a pojďte sem! Nato Šadrak, Méšak i Abed–nego vylezli zprostřed ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Shromáždili se i satrapové, prefekti a místodržitelé i královští rádcové a hleděli na ony muže, nad jejichž těly neměl oheň moc, ba ani vlasy na hlavě se jim neožehly, ani na kabátech nebylo nic znát, dokonce se okolo nich nešířil ani zápach ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nebúkadnesar nato prohlásil: Požehnán bůh Šadrakův, Méšakův i Abed–negův, jenž poslal svého anděla a vysvobodil své otroky, kteří se na něho spolehli. I královské slovo porušili a svá těla od dali tomu, že nebudou žádného boha uctívat a nebudou se klanět nikomu vyjma boha svého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'A tak mnou bude vydáno nařízení každému lidu, národu i jazyku, že kdo by lehkovážně mluvil o bohu Šadrakově, Méšakově i Abed–negově, aby byl rozčtvrcen a z jeho domu se stala hromada sutin, protože není jiného boha, jenž by dokázal takto zachraňovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Potom král Šadrakovi, Méšakovi i Abed–negovi v babylonské provincii pomohl ku zdaru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 31, 'Král Nebúkadnesar všem lidem, národům a jazykům přebývajícím v celé zemi: Nechť se vám pokoj rozhojní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 32, 'Znamení a zázraky, které na mně vykonal Bůh Nejvyšší, jevilo se mi za vhodné přednést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 33, 'Jak veliká jsou jeho znamení, jak mocné jeho divy! Jeho království je království věčné, jeho vláda z pokolení na pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Já, Nebúkadnesar, jsem spokojeně pobýval ve svém domě, ve svém paláci jsem jen kvetl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Tu jsem viděl sen a ten mi naháněl strach. Zděsily mne představy na mém loži, to, co má hlava viděla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Ode mne tedy vyšlo nařízení přivést přede mě všechny babylonské mudrce, aby mi sdělili výklad toho snu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Tehdy přišli kouzelníci, věštci chaldejci a drobopravci. Ten sen jsem jim vyprávěl, ale jeho výklad mi sdělit ne mohli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Až nakonec přede mne předstoupil Daniel, jehož jméno podle jména mého boha je Beltšasar a v němž dlí duch svatých bohů. I jemu jsem vyprávěl ten sen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Beltšasare, největší z kouzelníků, o němž já vím, že v tobě dlí duch svatých bohů a žádné tajemství ti nedělá potíže, pověz ta vidění mého snu, která jsem viděl, a jeho výklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Co tedy má hlava viděla, když jsem byl na loži: Díval jsem se a hle, nějaký strom uprostřed země a tyčil se náramně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Ten strom vyrostl, zesílil a svou výškou dosahoval až k nebi, takže byl vidět na sám kraj světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Listí měl krásné i ovoce hojné a byla na něm potrava pro každého. Pod ním nalézala stín polní zvěř, v jeho větvích přebývalo nebeské ptactvo a každý tvor se z něho živil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Má hlava ve vidění na loži hleděla dále a hle, jakýsi strážný a svatý sestoupil z nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Mocně volal a říkal toto: Podetněte ten strom a osekejte mu větve, připravte ho o listí a jeho ovoce rozházejte. Ať zpod něho prchne zvěř i ptactvo z jeho větví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Avšak pařez mu s kořeny ponechte v zemi a v poutech železných i bronzových mezi polní trávou ať se nebeskou rosou smáčí a se zvěří se dělí o porost zemský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Jeho srdce z lidského ať se promění a srdce budiž mu dáno zvířecí, než by přes něho přešlo sedm časů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Prohlášení to výrokem strážných jest, slovem svatých ta záležitost, ⌈aby živí poznali,⌉ že v lidském kralování Nejvyšší vládne a on je dává, komukoli ráčí, ba i nejnižšího z lidí nad ním ustanovuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Tento sen viděl jsem já, král Nebúkadnesar. A ty, Beltšasare, pověz výklad. Neboť všichni mudrci mého království nejsou schopni mi ten výklad oznámit, ty však můžeš. Vždyť duch svatých bohů dlí v tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Nato Daniel, jehož jméno bylo Beltšasar, zůstal asi hodinu vylekán, ta pomyšlení ho zděsila. Promluvil tedy znovu král: Beltšasare, nechť nezděsí tě ani sen, ani výklad. Beltšasar odpověděl a řekl: Můj pane, tvým nepřátelům ten sen a můj výklad tvým protivníkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Strom, který jsi viděl -- jenž vyrostl a zesílil a svou výškou dosahoval až k nebi, takže byl vidět na sám kraj světa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'jenž listí měl krásné i ovoce hojné a na němž byla potrava pro každého, pod nímž přebývala polní zvěř, v jehož větvích se zdržovalo nebeské ptactvo --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'to jsi ty, králi, jenž jsi vyrostl a zesílil, ⌈svou velikostí vyrostls a dosáhl jsi k nebi a svou vládou⌉ na sám kraj světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'A že král viděl strážného a svatého, jak sestupuje z nebes a praví: Podetněte ten strom a zničte jej, avšak pařez mu s kořeny ponechte v zemi a v poutech železných i bronzových mezi polní trávou ať se nebeskou rosou smáčí a se zvěří polní se dělí, dokud by přes něho nepřešlo sedm časů --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'tento výklad, králi, je i výrok Nejvyššího, který zasáhl na mého pána, krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Vyženou tě totiž od lidí a tvůj příbytek bude mezi polní zvěří. Budou ti dávat spásat porost jako dobytku a nechají tě smáčet nebeskou rosou. Tak přes tebe přejde sedm časů, dokud nepoznáš, že v lidském kralování vládne Nejvyšší a dává je, komukoli ráčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'A že přikázali pařez tomu stromu s kořeny ponechat, tvé království se ti dostane poté, co poznáš, že vládnou nebesa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Raději, králi, kéž bys dal na mou radu a své hříchy ve prospěch spravedlnosti odvrhl a své nepravosti ve prospěch dobročinnosti vůči chudým. Třeba se tvá spokojenost prodlouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'To vše krále Nebúkadnesara zasáhlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Když se totiž po uplynutí dvanácti měsíců procházel po babylonském královském paláci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'prohlásil král: Tak tedy toto je ten velký Babylon, který jako sídlo královské jsem já vybudoval silou své moci a ke cti svého majestátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Ještě měl král to slovo v ústech, když tu z nebes dolehl hlas: Tobě se praví, králi Nebúkadnesare: Království od tebe odešlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Od lidí tě vyženou a tvůj příbytek bude mezi polní zvěří. Budou ti dávat spásat porost jako dobytku. Tak přes tebe přejde sedm časů, dokud nepoznáš, že v lidském kralování vládne Nejvyšší a dává je, komukoli ráčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'V té chvíli se ono slovo o Nebúkadnesarovi naplnilo. Od lidí byl vyhnán, porost jako dobytek spásal a tělo se mu nebeskou rosou smáčelo, až mu vlasy vyrostly jako orlí peří a nehty měl jako ptačí drápy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Avšak po uplynutí té doby jsem já, Nebúkadnesar, pozdvihl své oči k nebesům a mé poznání se mi navrátilo. Nejvyššímu jsem dobrořečil a věčně živého chválil a oslavoval, neboť jeho vláda je vláda věčná a jeho království trvá z pokolení na pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Všichni obyvatelé země se počítají za nic, vždyť jak se mu zlíbí, nakládá s vojskem nebeským i s obyvateli země. Není, kdo by mu mohl dát přes ruku a říci mu: Cos to provedl?!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'V té době mi navrátil mé poznání, také čest mého kralování a můj majestát, dokonce mi vrátil i můj vzhled, a tu mne mí rádcové a velmoži vyhledali. Byl jsem znovu nastolen ve svém království a přidána mi byla neobyčejná velikost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Nyní já, Nebúkadnesar, uctívám a vyvyšuji a oslavuji Krále nebes, jehož všechny činy jsou pravda, jehož stezky právo a jenž je mocen pokořit ty, kdo si vedou pyšně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Král Belšasar připravil tisícovce svých velmožů veliký hodokvas a sám popíjel víno ⌈v čele⌉ té to tisícovky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Když okusil víno, poručil Belšasar přinést zlaté a stříbrné nádoby, které jeho otec Nebúkadnesar odnesl z jeruzalémského chrámu. Že prý král, jeho velmoži, jeho ženy i jeho družky budou pít z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Hned přinesli zlaté nádoby, odnesené z chrámu Božího domu v Jeruzalémě, a král, jeho velmoži, jeho ženy i jeho družky se z nich napili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Popíjeli víno a chválili bohy zlaté a stříbrné, bronzové, železné, dřevěné i kamenné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'V té chvíli se objevily prsty lidské ruky a psaly před svícnem na omítce stěny královského paláce. Král jen hleděl na hřbet jakési ruky, jak píše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'A tu se králi úplně změnil výraz, z hloubi duše byl zděšen, sotva se držel na nohou a kolena mu klepala o sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Potom se král hlasitě rozkřičel, aby přivedli věštce a chaldejce a drobopravce. Král k babylonským mudrcům promluvil a řekl jim: Každý, kdo přečte tento nápis a přednese mi jeho výklad, šarlat oblékne a zlatý řetěz okolo krku obdrží a bude vládnout jako třetí v království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Pak předstupovali všichni královští mudrci, ale nápis přečíst nedokázali ani sdělit králi jeho výklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'To už byl král Belšasar úplně zděšený a byl téměř k nepoznání. Také jeho velmoži byli zmateni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Vzhledem k řečem, které vedli král a jeho velmoži, vstoupila do hodovní síně i královna matka. Promluvila a řekla: Králi, navěky buď živ. Ne musíš se z hloubi duše děsit a svůj výraz si zachovej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Ve tvém království je muž, ve kterém dlí duch svatých bohů a v němž se za dnů tvého otce nalezlo osvícení a jasnozřivost ⌈i moudrost, jakou mívají bohové.⌉ A král Nebúkadnesar, tvůj otec, jej ustanovil představeným kouzelníků, věštců, chaldejců, drobopravců... ⌈Tvůj otec, králi,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'jelikož neobyčejný duch a poznání i jasnozřivost vykládající sny a záhadné výroky a rozplétající obtíže se nalezla v Danielovi, jemuž dal král jméno Beltšasar. Nyní tedy budiž zavolán Daniel a on přednese výklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Před krále byl tedy předveden Daniel. Král k Danielovi promluvil a řekl: Ty jsi ten Daniel ze synů judských vysídlenců, které přivedl král, můj otec, z Judska?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Už jsem o tobě slyšel, že v tobě dlí duch bohů a nalezlo se v tobě osvícení a jasnozřivost i neobyčejná moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Teď byli přede mne předvedeni mudrci a věštci, aby ten nápis přečetli a sdělili mi jeho výklad, ale nejsou schopni mi přednést výklad těch slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Já jsem ale slyšel o tobě, že dokážeš výklady vysvětlovat a obtíže rozplétat. Jestli teď dokážeš přečíst ten nápis a sdělit mi jeho výklad, šarlat oblékneš a zlatý řetěz okolo krku obdržíš a budeš vládnout jako třetí v království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Nato Daniel odpověděl a před králem řekl: Tvé dary nechť zůstanou tobě a své odměny dej někomu jinému. Avšak ten nápis králi přečtu a výklad mu sdělím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Nuže, králi, Bůh Nejvyšší dal království a velikost i čest a majestát tvému otci Nebúkadnesarovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'A pro tu velikost, kterou mu dal, se před ním třásli a báli se jej všichni lidé, národy a jazyky. Koho chtěl, pobíjel, a koho chtěl, ⌈nechával naživu,⌉ koho chtěl, povyšoval, a koho chtěl, ponižoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Když se však jeho srdce povýšilo a jeho duch zesílil v pýše, byl z trůnu svého království sesazen, ba i čest mu odňali');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'a byl vyhnán od lidských synů, jeho srdce se připodobnilo zvířecímu a přebýval mezi divokými osly. Dávali mu spásat porost jako dobytku a nebeskou rosou se mu tělo smáčelo, dokud nepoznal, že v lidském kralování vládne Bůh Nejvyšší a ustanovuje v něm, kohokoli ráčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Ani ty, jeho syn, jsi Belšasare, nepokořil své srdce, přestožes o tom všem věděl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'nýbrž proti pánu nebes ses povýšil, když před tebe přinesli nádoby jeho domu a ty i tví velmoži tvé ženy i tvé družky z nich popíjeli víno, tehdy jsi chválil bohy stříbrné a zlaté, bronzové, železné, dřevěné i kamenné, kteří nevidí a neslyší ani nic nevědí, ale Boha, jenž má v ruce tvůj dech i celé tvé putování, jeho jsi neoslavil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Nato byl od něho poslán hřbet té ruky a nápis tento zapsán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'A tímto nápisem je zapsáno: MeNé, MeNé, TeKéL, uFaRSín.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Toto je výklad toho slova: MeNé -- sečetl Bůh tvé kralování a ukončil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'TeKéL -- byl jsi zvážen na vahách a shledán jsi byl nedostatečným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'PeRéS -- ⌈rozpůleno bylo tvé království⌉ a bylo dáno Médům a Peršanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Nato Belšasar poručil a Daniela přioděli šarlatem i zlatým řetězem okolo krku a rozhlašovali před ním, že bude v království vládnout jako třetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Té noci byl chaldejský král Belšasar zabit');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'a kralování se ujal Dareios Médský, když mu bylo šedesát dva roků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Dareiovi se zdálo vhodné ustanovit nad královstvím sto dvacet satrapů, aby byli po celém království,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'a nad nimi ještě tři vezíry, z nichž jedním byl Daniel. Jim tito satrapové podávali hlášení, aby král netrpěl škodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Tento Daniel ovšem nad vezíry i satrapy vynikal, protože v něm byl neobyčejný duch, a král byl nakloněn ustanovit jej nad celým královstvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Tehdy se vezíři a satrapové snažili proti Danielovi nalézt něco ohledně království, ale nemohli nalézt vůbec nic ani žádnou závadu, neboť byl spolehlivý ⌈a žádná nedbalost ani závada se u něho nenalézala.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Tu si ti muži řekli: Proti tomuhle Danielovi nenajdeme vůbec nic, ledaže bychom proti němu našli něco v zákoně jeho boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Pak se vezíři a satrapové shlukli okolo krále a takto na něho naléhali: Králi Darei, navěky buď živ!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Všichni královští vezíři, prefekti a satrapové, rádci a místodržitelé se shodli, aby král vystavil dekret a vyšel zákaz, aby každý, kdo by nějakou prosbou po třicet dnů prosil u jakéhokoliv boha nebo u člověka jiného než u tebe králi, byl uvržen do lvího doupěte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Nyní nechť král ten zákaz vystaví a vydá předpis, jaký podle nepomíjivého zákona Médů a Peršanů není možno změnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Král Dareios tedy vydal onen předpis a zákaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Když se Daniel dověděl, že byl vydán takový předpis, šel domů, kde měl ve střešní místnosti okna otevřená směrem k Jeruzalému, a tam jako vždy třikrát denně poklekal na kolena, modlil se a vzdával chválu před svým Bohem, neboť tak to činil i dříve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Nyní se ale shlukli ti muži a nalezli Daniela, jak prosí a přimlouvá se před svým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Předstoupili tedy před krále a hovořili o královském zákazu: Nevydal jsi snad zákaz, aby každý člověk, který bude po třicet dnů prosit u jakéhokoliv boha nebo u člověka jiného než tebe, králi, bude uvržen do lvího doupěte? Král promluvil a řekl: Tak to platí podle nepomíjivého zákona Médů a Peršanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Nato před králem promluvili takto: Daniel ze synů judských vysídlenců na tebe, králi, nebere zřetel, ani na zákaz, který jsi vydal, a svou prosbu přednáší třikrát denně!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Jakmile to král uslyšel, byl velmi znechucen a lámal si hlavu, jak Daniela vysvobodit. Až do západu slunce se ho snažil zachránit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Jenomže ti muži se okolo krále shlukli a naléhali na krále: Považ, králi, že médským a perským zákonem je, aby jakýkoliv zákaz i dekret, který král stanoví, ne bylo možno změnit!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Král nakonec přikázal, aby Daniela přivedli a uvrhli do lvího doupěte. Král Daniela oslovil a řekl mu: Tvůj bůh, kterého ty stále uctíváš, ten kéž tě vysvobodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Pak byl přinesen nějaký balvan, přiložen na ústí toho doupěte a král jej zapečetil svým pečetidlem i pečetidlem svých velmožů, aby tu záležitost ohledně Daniela ne bylo možno změnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Král potom odešel do svého paláce a strávil noc bez jídla, nepovolal k sobě ani radovánky, i spánek ho opustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Nakonec král musel vstát ještě za svítání, jakmile se rozednilo, a poděšeně spěchal ke lvímu doupěti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Když se král k doupěti přiblížil, zavolal zarmouceným hlasem Daniela. Král Daniela oslovil takto: Danieli, otroku toho živého boha, jestlipak tě tvůj bůh, kterého ty stále uctíváš, dokázal vysvobodit od lvů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Vtom ke králi promluvil Daniel: Králi, navěky buď živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Můj Bůh poslal svého anděla a lvům zavřel ústa, takže mě nezranili, poněvadž jsem byl před ním shledán nevinným a také vůči tobě, králi, jsem nic špatného neprovedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Tu se král nad tím velice zaradoval a rozkázal Daniela vytáhnout z doupěte. Daniel byl tedy vytažen z doupěte a nenašlo se na něm žádné zranění, neboť věřil ve svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Král pak rozkázal, aby přivedli ty muže, kteří se tak pouštěli do Daniela, a do lvího doupěte uvrhli je i jejich syny a jejich ženy. Ještě nedopadli na dno doupěte, a už se jich zmocnili lvi a rozdrtili jim všechny kosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Potom král Dareios napsal všem lidem, národům a jazykům přebývajícím v celé zemi: Nechť se vám pokoj rozhojní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, '⌈Vydávám nařízení,⌉ aby se po celém mém královském panství třásli před Danielovým Bohem a báli se jej, neboť on je Bůh živý a stálý navěky, i jeho království, jež nebude zničeno, a jeho vláda bude až do konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'On vysvobozuje a zachraňuje, znamení a divy koná na nebesích i na zemi, on vysvobodil Daniela ze lvích spárů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 29, 'A tak se tedy Danielovi dobře dařilo za kralování Dareiova i za kralování Kýra Perského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'V prvním roce krále babylonského Belšasara viděl Daniel sen, měl totiž ve svém nitru jistá vidění, když byl na loži. Ten sen potom sepsal. Věc začala takto:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel promluvil: Ve vidění jsem během noci přihlížel tomu, jak hle, čtyři nebeské větry vzdouvají Veliké moře');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'a z moře vystupují čtyři veliké šelmy, každá jiná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'První byla jako lev, ale měla orlí křídla. Přihlížel jsem, jak jí byla potom ta křídla utržena, šelma byla zvednuta ze země, postavena na nohy jako člověk a bylo jí dáno lidské srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'A hle, další šelma, druhá, podobná medvědu. Byla postavena k jedné straně, mezi zuby měla v tlamě tři žebra a takto k ní hovořili: Vstaň, sežer hodně masa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Po tomto jsem přihlížel dále a hle, další. Byla jako levhart a na bocích měla čtyři ptačí křídla. Ta šelma měla čtyři hlavy a byla jí dána vláda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Po tomto jsem v oněch nočních viděních přihlížel dále a hle, čtvrtá šelma strašlivá, úděsná a neobyčejně silná. Měla veliké železné zuby. Požírala, drtila a to ostatní svýma nohama pošlapávala. Ta byla ale odlišná ode všech šelem, které byly před ní, a měla deset rohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Sledoval jsem ty rohy a hle, mezi nimi vyrostl další roh, nepatrný, ale tři z dřívějších rohů byly před ním vykořeněny. A hle, na tomto rohu byly oči jako oči lidské a ústa mluvící velké věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Přihlížel jsem, jak byly potom rozloženy trůny a usedl Věkovitý. Roucho měl jako sníh bílé a vlasy jeho hlavy čisté jak vlna, jeho trůn -- plamen ohně, jeho kola -- oheň hořící.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Proudí a od něho vychází ohnivá řeka. Tisíců na tisíc mu slouží a myriády myriád stojí před ním. Soud zasedl a byly otevřeny knihy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Přihlížel jsem poté, co zazněla ta veliká slova, jaká promlouval onen roh, a hleděl jsem, dokud nebyla ta šelma zabita, její tělo zahubeno a ona dána ohni ke spálení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'I zbylým šelmám odňali jejich vládu, ale prodloužení života jim bylo dáno až do jisté doby a času.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'V těch nočních viděních jsem přihlížel a hle -- s oblaky nebes přicházel synu člověka podoben, přiblížil se až k Věkovitému a před něj směl předstoupit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Byla mu dána vláda a čest i království a všichni lidé, národy a jazyky jej budou uctívat. Jeho vláda je vládou věčnou, nepomíjivou, také jeho království, jež nebude zničeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, '⌈ V duchu jsem se znepokojil,⌉ já Daniel, v hloubi svého nitra, a děsilo mne, co má hlava viděla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Přistoupil jsem k jednomu z přístojících, ⌈abych od něho nabyl o tom všem jistotu.⌉ On mi řekl, že i výklad těch věcí mi sdělí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Ty veliké šelmy, které jsou čtyři, to ze země povstanou čtyři králové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Ale kralování obdrží svatí Nejvyššího a ti budou královstvím vládnout až na věky, ba na věky věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Chtěl jsem tedy mít jistotu o té čtvrté šelmě, která se od nich ode všech odlišovala -- byla neobyčejně strašlivá, měla zuby železné a drápy bronzové, požírala, drtila a to ostatní svýma nohama pošlapávala --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'i o těch deseti rozích na její hlavě a o dalším, který vyrostl, a padly před ním tři, rohu takovém, že měl oči a ústa mluvící velké věci, a na pohled větším než jeho druhové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Přihlížel jsem, jak onen roh vede válku se svatými a jak je přemáhá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'až přišel Věkovitý a soud byl dán svatým Nejvyššího a nadešla doba, že to království ovládli svatí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Takto pravil: Ta čtvrtá šelma bude čtvrté království na zemi, které se bude ode všech těch království odlišovat, požere celou zemi, podupe ji a bude ji drtit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'A těch deset rohů, to deset králů povstane z toho království a po nich povstane jiný, jenž se od předešlých bude lišit a tři krále pokoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Bude pronášet slova proti Nejvyššímu a svatým Nejvyššího nedá pokoj. Bude také uvažovat, že změní doby a právo, a budou mu do ruky vydány až do času a časů a půl času.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Zasedne však soud a vládu mu odejmou. Bude zničen a úplně zahlazen,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'zatímco království a vláda i velikost všech království pod nebesy bude dána lidu svatých Nejvyššího. Jeho království je království věčné a všechny vlády jej budou uctívat a poslouchat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Zde to slovo končí. Já, Daniel, jsem byl těmi myšlenkami zcela vyděšen a bylo to znát i na mém výrazu. To slovo jsem si ale ponechal v srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Ve třetím roce kralování krále Belšasara se ukázalo mně, Danielovi, vidění následující po tom vidění, které jsem měl na počátku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Ve vidění jsem spatřil, že hledím, jak jsem v opevnění Šúšanu v provincii Élamu. Spatřil jsem ve vidění, jak jsem byl u brány Úlaj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Pozvedl jsem oči a viděl, hle, nějaký beran stál před branou a měl dva rohy, a to rohy vysoké, ale jeden vyšší než druhý a ten vyšší vyrostl později.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Viděl jsem, jak beran trkal na západ a na sever a na jih, a žádné zvíře před ním ne mohlo obstát ani nebylo, kdo by z jeho ruky vysvobodil. Dělal si, co se mu zlíbilo, a vyvýšil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Zatímco jsem se to snažil pochopit, hle, od západu přes celou zemi přicházel kozel, aniž by se dotýkal země, a ten kozel měl mezi očima viditelný roh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Když se přiblížil až k beranovi ⌈vybavenému dvěma rohy,⌉ kterého jsem spatřil stát před branou, rozeběhl se k němu se zuřivou silou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Viděl jsem, jak na berana naběhl. Rozzuřil se na něj a zasáhl toho berana, až mu roztříštil oba rohy. Beran neměl sílu, aby před ním obstál. Ten ho porazil na zem, podupal ho a nebylo, kdo by berana z jeho ruky vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Kozel se nadmíru vyvýšil. Ale když zesílil, jeho veliký roh se zlomil a místo něho vyrostly viditelné čtyři, a to na čtyři strany světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Pak z jedné z nich vyrazil jakýsi nepatrný roh, ale neobyčejně vzrostl k jihu i k východu i k Ozdobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Vzrostl až k vojsku nebes a shodil na zem některé z toho vojska i některé z hvězd a pošlapal je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Ba až k veliteli toho vojska se vyvýšil a od něho odebral soustavnou bohoslužbu a povrženo bylo sídlo jeho svatyně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'kdežto nad tou soustavnou bohoslužbou bylo věrolomně dáno vojsko, a byť pravdu povrhlo na zem, ⌈úspěšně se prosadilo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Slyšel jsem také, jak jeden svatý hovoří. A jeden svatý pravil tomu dotyčnému, který hovořil: Za jak dlouho nastane to vidění o té soustavné bohoslužbě a té pustošící věrolomnosti, vydávající v pošlapání jak svatyni, tak vojsko?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'A řekl mi: Až do večera i jitra dvoutisícího třístého, a napravena bude svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Když jsem já, Daniel, sledoval to vidění a snažil se, abych je pochopil, stalo se náhle, že přede mnou stál kdosi vzhledem jako člověk');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'a uprostřed Úlaje jsem slyšel volat lidský hlas. Říkal: Gabrieli, dej tomuto pochopit to vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'On se přiblížil k mému místu, ale když přicházel, vyděsil jsem se a padl jsem na tvář. Tehdy ke mně promluvil: Pochop, lidský synu, že to vidění je pro čas konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Když se mnou hovořil, tvrdě jsem spal tváří k zemi. On se mne ale dotkl a postavil mne zpříma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Pak řekl: Hle, oznámím ti, co nastane koncem rozhořčení, neboť určenou dobou nastane konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Ten beran, kterého jsi viděl, vybavený dvěma rohy, jsou králové médští a perští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'A ten chlupatý kozel je král řecký a ten velký roh mezi jeho očima je ten první král.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Pak se zlomil a místo něho povstali čtyři, to čtyři království povstanou z národa, ne však v jeho síle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'A koncem jejich kralování, až dokonají vzpurníci, povstane král drzý a zkušený v záludnostech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Jeho síla bude mocná, ne však v jeho síle, a bude mimořádně ničit a prosadí se, vykoná to, zničí i mocné, ba i lid svatých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'A pro svou vychytralost dokáže prosadit i podvod. Když se v srdci vyvýší a v míru bude ničit mnohé, ano i proti Veliteli velitelů bude se stavět, tehdy bez zásahu ruky bude rozdrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Vidění o večeru a jitru a co řečeno, je pravda. Ty ale to vidění uzavři, je totiž na velmi dlouho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Tehdy jsem se já Daniel roznemohl a dlouho mi nebylo dobře. Když jsem opět vstal a konal službu u krále, zůstával jsem zdeptán z toho vidění, ale nic jsem nechápal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'V prvním roce Dareia, syna Achašvérošova, z potomstva médského, jenž ⌈byl učiněn králem⌉ nad královstvím chaldejským,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'v prvém roce jeho kralování jsem já, Daniel, pochopil z knih, co se stalo jako Hospodinovo slovo k proroku Jeremjášovi, že počet roků, který se má naplnit ohledně trosek Jeruzaléma, je sedmdesát let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Tehdy jsem obrátil svou tvář k Panovníku Bohu, abych jej hledal modlitbou a úpěnlivými prosbami, v postu, žíněném rouchu a popelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'A tak jsem se modlil k Hospodinu, svému Bohu, vyznával jsem a říkal: Ach, Panovníku, Bože veliký a hrozivý, zachovávající smlouvu a milosrdenství těm, kdo tě milují a zachovávají tvé příkazy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'zhřešili jsme, páchali jsme zlo, jednali jsme ničemně, vzbouřili jsme se, odvrátili se od tvých příkazů a nařízení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'a neposlouchali jsme tvé služebníky proroky, kteří ve tvém jménu mluvili k našim králům, velitelům, našim otcům i ke všemu lidu země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Tobě, Panovníku, náleží spravedlnost, ale nám zbývá tohoto dne jenom hanba -- Judejcům a obyvatelům Jeruzaléma i celého Izraele, blízkým i vzdáleným ve všech zemích, kam jsi je zahnal za jejich věrolomnost, kterou se tobě zpronevěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Hospodine, nám náleží jenom hanba -- našim králům, našim velitelům i našim otcům -- neboť jsme zhřešili proti tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Panovníkovi, našemu Bohu, zůstávají slitování a odpuštění. To proto, že jsme se proti němu vzbouřili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'a neposlouchali jsme Hospodina, svého Boha, abychom žili podle jeho zákonů, které nám předkládal prostřednictvím svých služebníků proroků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'ale všichni v Izraeli přestoupili tvůj zákon, odvrátili se a neposlouchali tě. Proto se na nás sesypala prokletí a zlořečení, jak je psáno v zákoně Mojžíše, otroka Božího, neboť jsme vůči němu zhřešili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'On naplnil svá slova, jenž promluvil proti nám a proti našim správcům, kteří nás spravovali, že na nás uvede velké zlo; co se nestalo pod celým nebem, to se stalo v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Takové, jaké je zapsáno v zákoně Mojžíšově, veškeré takové zlo přišlo na nás. A my jsme se nesnažili udobřit Hospodina, svého Boha, abychom se odvrátili od svých zvráceností a abychom porozuměli tvé pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Proto Hospodin bděl nad tím zlem a uvedl je na nás, neboť Hospodin, náš Bůh, je spravedlivý ve všech svých činech, jež učinil; vždyť my jsme ho neposlouchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'A teď, Panovníku, Bože náš, jenž jsi vyvedl svůj lid z egyptské země mocnou rukou a učinil sis jméno až do tohoto dne -- zhřešili jsme, ničemně jsme jednali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Panovníku, pro všechny tvé spravedlivé činy, kéž se tvůj hněv i tvé rozlícení odvrátí od tvého města Jeruzaléma, tvé svaté hory; vždyť to kvůli našim hříchům a zvrácenostem našich otců Jeruzalém i tvůj lid je v potupě ode všech okolo nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Teď ale vyslyš, Bože náš, modlitbu svého otroka i jeho úpěnlivé prosby a rozjasni svou tvář nad svou zpustošenou svatyní, pro Panovníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Nakloň, Bože můj, své ucho a slyš! Otevři své oči a viz, jak jsme zpustošeni -- my i město, které se nazývá tvým jménem. Vždyť své úpěnlivé prosby před tebe přednášíme ne pro své spravedlivé činy, nýbrž pro tvé mnohé slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Ach, Panovníku, slyš! Ach, Panovníku, odpusť! Ach, Panovníku, pozorně naslouchej a jednej, neotálej! Kvůli sobě samému, Bože můj, vždyť tvým jménem se nazývá tvé město i tvůj lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Ještě jsem hovořil, modlil se a vyznával hřích svůj i hřích svého lidu Izraele a před Hospodinem, svým Bohem, přednášel svou úpěnlivou prosbu za svatou horu svého Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'ještě jsem hovořil a modlil se, a vtom ten muž, Gabriel, jehož jsem spatřil ve vidění na počátku, se mne vyčerpaného únavou dotkl v čase večerní přídavné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Aby mne poučil, promluvil a řekl: Danieli, vyšel jsem teď, abych ti dal porozumět smyslu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Na počátku tvých úpěnlivých proseb vyšlo slovo a já jsem přišel, abych ho oznámil, neboť jsi převzácný. Pochop tedy to slovo a rozuměj tomu vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Pro tvůj lid a pro tvé svaté město je vyděleno sedmdesát sedmi letí k zadržení té věrolomnosti a ke zpečetění hříchů i k usmíření zvrácenosti, též ku přivedení věčné spravedlnosti a zapečetění vidění a proroka i ku pomazání nejsvětějšího místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Věz tedy a rozuměj: Od vyjití slova k návratu a k budování Jeruzaléma až k Pomazanému vůdci bude sedm sedmi letí a šedesát dva sedmi letí. Znovu se vybuduje náměstí a příkop, v tísni oněch časů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Ale po těch šedesáti a dvou sedmi letích bude vyhlazen Pomazaný a nebude mít nic, a to město i tu svatyni bude ničit lid jednoho vůdce, který přichází. Ale jeho konec bude v záplavě. A až do konce bude odhodlaný boj po místech zpustošených.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'A prosadí smlouvu mnohým jednoho sedmi letí, leč uprostřed onoho sedmi letí ukončí obětní hod i přídavnou oběť. Tehdy na křídle ohavností bude pustošící, dokud se zkáza i rozhodnutí nebude vylévat na pustošenou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Ve třetím roce perského krále Kýra byla Danielovi, jenž byl nazván jménem Beltšasar, zjevena jistá věc, a to věc pravdivá -- o velikém válečném tažení. On tu věc pochopil i její smysl ve vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'V oné době jsem já, Daniel, truchlil již tři týdny dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Nejedl jsem chutný pokrm, maso ani víno se mi nepřiblížilo k ústům. Také jsem se ničím nemazal, dokud se nenaplnily ty tři týdny dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Dvacátého čtvrtého dne prvního měsíce, když jsem byl na břehu té velké řeky, totiž Tigridu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'pozvedl jsem oči a spatřil jsem, hle, jakéhosi muže, oděného lněným oděvem, boky přepásané zlatem z Úfázu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'tělo měl jako drahokam, ve tváři oslnivý jas, oči jak ohnivé pochodně, jeho paže a chodidla se leskly jako leštěný bronz a hřmot jeho slov byl hřmotem davu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Na to vidění jsem ale hleděl jen já sám, Daniel, kdežto muži, kteří byli se mnou, to vidění neviděli, nýbrž padlo na ně veliké zděšení a utekli se schovat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'zatímco já zůstal sám. Jakmile jsem spatřil to veliké vidění, nezůstala ve mně síla, má důstojnost rázem přišla vniveč a nedokázal jsem se vzchopit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Pak jsem uslyšel hřmot jeho slov, a jak jsem ten hřmot jeho slov zaslechl, už jsem tvrdě spal na tváři. Když jsem tak byl tváří k zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'vtom se mě dotkla ruka, otřásla mnou a pozvedla na kolena a dlaně mých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Promluvil ke mně: Danieli, muži převzácný, pochop ta slova, která ti budu říkat, a postav se zpříma, neboť jsem byl teď vyslán za tebou. Když ke mně to slovo promlouval, stál jsem a třásl se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Promluvil ke mně: Neboj se, Danieli, neboť od prvního dne, kdys přiložil své srdce, abys pochopil i aby ses pokořoval před svým Bohem, jsou tvá slova vyslyšena a kvůli tvým slovům jsem přišel také já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Ale velitel perského království se stavěl proti mně dvacet jedna dní, až hle, Michael, jeden z předních velitelů, mi přišel na pomoc, když jsem tam zůstal u perských králů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'A přišel jsem, abych ti dal pochopit, co potká tvůj lid koncem oněch dnů. Neboť pro ty dny je další vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Jakmile ke mně promluvil tato slova, sklonil jsem tvář k zemi a oněměl jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'A hle, kdosi podobný synům lidským se dotkl mých rtů. Otevřel jsem tedy ústa, abych promluvil a řekl tomu, jenž stál naproti mně: Můj pane, kvůli tomu vidění na mě přišly křeče a nedokázal jsem se vzchopit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Jak by tedy mohl takovýhle otrok mého pána hovořit s takovýmto mým pánem? Vždyť ve mně ⌈už vůbec⌉ nepozůstává síla ani dech nezůstal ve mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Ale znovu se mne dotkl kdosi vzhledem jako člověk a posílil mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Pravil: Neboj se, muži převzácný. Pokoj tobě. Buď silný, jen buď silný. A když se mnou hovořil, posílil jsem se, takže jsem řekl: Nechť můj pán hovoří, neboť jsi mi dodal sílu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Pravil: Zdali víš, proč jsem za tebou přišel? Já se totiž zase vrátím, abych bojoval s velitelem Persie. A zatímco já odcházím, hle, přichází velitel Řeků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Já ti však oznámím, co je zapsáno v přípisu pravdy. Není totiž jiného, kdo by se odhodlal zasahovat se mnou proti nim, kromě vašeho velitele Michaela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'V prvním roce ⌈Dareia Médského⌉ jsem tedy i já zaujal postoj, abych jej podporoval a poskytoval mu ochranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Teď ti tedy oznámím pravdu: Hle, v Persii povstanou ještě tři králové a pak čtvrtý zbohatne jměním nade všechny větším. Když se pro své bohatství prosadí, podnítí všechny při království řeckém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Pak povstane chrabrý král, ten bude vládnout veliké říši a dělat si, co se mu zlíbí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Ale až povstane, jeho království se rozpadne a rozdělí čtyřem větrům nebes, ne jeho potomstvu a ne taková vláda, jakou vládl, protože jeho kralování bude vytrženo a připadne jiným kromě těchto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Potom zesílí král jihu i jeden z jeho velitelů a ten zesílí nad něho a bude vládnout říši větší než říše jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Uplynou roky, oni se spojí a dcera krále jihu přijde ke králi severu, aby se uskutečnilo právo, ale tu paži opustí všechna síla a neobstojí on ani ta jeho paže a vydána bude ona, i kdo ji přivedli a kdo ji zplodil, i ten, kdo ji v těch časech podporoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Pak na jeho místo nastoupí jeden z výhonků jejích kořenů, přitáhne k vojsku, přitáhne do pevnosti krále severu, vypořádá se s nimi a přemůže je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Také jejich bohy s jejich ⌈litými modlami,⌉ s drahocenným náčiním, stříbrem a zlatem, odnese do zajetí v Egyptě. Pak se několik let bude od krále severu držet nazpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Ten však přijde do království krále jihu, ale vrátí se do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Avšak jeho syn, když budou mobilizovat a shromáždí veliké množství vojska, půjde ⌈dál a dále,⌉ až projde jako záplava, ⌈pak se obrátí a⌉ zaútočí na samu jeho pevnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'To se král jihu rozzuří, vytáhne a s tím králem severu se pustí do boje. Ten postaví veliké množství vojska, avšak to množství bude vydáno do ruky onoho');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'a celé množství bude rozneseno. Jeho srdce se pozvedne, že porazí desítky tisíc. Nezvítězí však.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Král severu se vrátí. Postaví totiž množství větší než to předchozí. Až ty časy uplynou, bude po několik roků přicházet s velikým vojskem a četným vybavením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'V oněch časech proti králi jihu povstanou mnozí, také dravci ze tvého lidu se pozvednou, aby ustavili vidění, ale upadnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Král severu přijde, navrší násep a obsadí opevněné město, proto paže jihu neobstojí, ani ⌈jeho nejlepší vojáci⌉ ⌈nebudou moci obstát.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Jeho dobyvatel si tedy bude dělat, co se mu zlíbí, a nikdo před ním neobstojí. Stane i ⌈na Ozdobě země,⌉ v rukou zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Rozhodne se získat nadvládu nad celým jeho královstvím, nabídne a také uskuteční vyrovnání a dá mu svou dceru, aby je zničil. To se mu ale nepodaří, to mu nevyjde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Zaměří tedy svou pozornost na přímořské oblasti a mnohých se zmocní. Jeden vojevůdce mu však zatrhne jeho pohrdání. ⌈Ne zbude mu než své pohrdání vzít nazpět.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Obrátí tedy svou tvář k pevnostem své země, ale klopýtne, padne a nebude nalezen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Pak na jeho místo nastoupí jeden, který nechá procházet vymahače majestátem království, ale za několik dnů bude potřen, ne však ve hněvu nebo ve válce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Pak na jeho místo nastoupí pohrdaný. Nevloží sice na něho královskou důstojnost, avšak přijde v míru a království se zmocní úlisnostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Před ním budou smeteny nespočetné síly a budou rozdrceny, ba i vůdce smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'A ze spojenectví s ním učiní podvod a vystoupí a bude silný s trochou národa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'V míru a do nejúrodnějších míst provincie přijde a učiní, co nečinili jeho otcové ani otcové jeho otců. Kořist a lup i majetek jim rozhodí a proti opevněním bude vymýšlet své plány, ale až do času.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Také podnítí svou sílu i své srdce proti králi jihu při velikém vojsku. Král jihu tedy zmobilizuje k boji nadmíru veliké a mocné vojsko, ale neobstojí, neboť oni proti němu vymyslí plány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Rovněž strávníci z jeho zásob ho porazí a jeho vojsko odplaví on. Tehdy mnozí padnou probodeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, '⌈Srdce obou králů budou nakloněna ke zlu,⌉ i u jednoho stolu budou mluvit lež, ale bez úspěchu, neboť konec nastane teprve určenou dobou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'On se vrátí do své země s velkým majetkem a jeho srdce bude jednat i proti svaté smlouvě. Pak se vrátí do své země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Určenou dobou se bude vracet a přijde na jih. Nebude to však jako prve ani jako naposled.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Setkají se s ním totiž kitejské lodě. Dá se odradit a vrátí se, ale bude rozhněván a bude jednat proti svaté smlouvě. Vrátí se tedy a zaměří na ty, kdo opouštějí svatou smlouvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Tehdy z něho povstanou síly a znesvětí svatyni -- pevnost. Odstraní také soustavnou bohoslužbu a dají tam tu pustošící ohavnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'A ty, kdo kazí smlouvu, on poskvrní úlisností, ale lid, který zná svého Boha, projeví sílu a bude jednat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Kdo mezi lidem rozumějí, budou učit mnohé, ač budou po jistou dobu klesat kvůli meči a v palbě, v zajetí i při plenění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Ale až budou klesat, dostane se jim trochu pomoci, avšak mnozí se k nim připojí úlisnostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'I z těch, kdo rozumějí, budou klesat, aby byli mezi nimi tříbeni a čištěni i běleni až do času konce, neboť nastane teprve určenou dobou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Ten král si bude dělat, co se mu zlíbí, pozvedne se a vyvýší nad každé božstvo. I proti Bohu bohů bude říkat mimořádné věci a prosadí se, dokud neskončí rozhořčení, neboť rozhodnutí se uskuteční.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Ani Bohu svých otců se nebude věnovat, ani touze žen, ani žádnému jinému bohu se nebude věnovat, neboť nade vše vyvýší sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Na jeho místě bude ctít boha pevností a boha, kterého neznali jeho otcové, bude ctít zlatem a stříbrem i drahokamy a vzácnostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Postaví také opevněné pevnosti s cizím bohem, jehož uznává, rozmnoží slávu a nechá je ovládat mnohé. Také půdu bude rozdělovat za odměnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Potom v čase konce se s ním bude trkat král jihu, ale král severu jej smete vozbou a jezdci a mnoha loděmi. Přijde do různých zemí, zaplaví je a projde jimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Přijde také do Ozdoby země. Mnohé budou tehdy klesat, ale z jeho ruky uniknou tyto: Edóm a Moáb i přední ze synů Amónových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Svou ruku ale vztáhne po různých zemích, takže ani země egyptská nebude moci uniknout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Ovládne poklady zlata i stříbra a všechny vzácnosti Egypta, Lúbíjci a Kúšijci budou následovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Avšak poplaší ho zprávy z východu a ze severu, proto vytáhne velice rozhořčen, aby vyhladil a zkáze zasvětil mnohé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Postaví také svůj hlavní stan mezi moři a horou Ozdoby svatosti. Tehdy dospěje až ke svému konci a nebude, kdo by mu pomohl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'A právě v onom čase povstane Michael, ten velký velitel, jenž zastává tvůj lid, a nastane čas soužení, k jakému nedošlo, co jsou národem, až do onoho času. A právě v onom čase unikne tvůj lid, každý, kdo se nachází zapsán v knize.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Tu mnozí z těch, kdo spí v prachu země, procitnou, jedni pro ⌈život věčný,⌉ ale druzí k naprosté hanbě pro věčnou ohavnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Ti rozumní však budou zářit jasem oblohy, a kdo ke spravedlnosti dopomáhají mnohým, jako hvězdy navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Ale ty, Danieli, ta slova uzavři a tu knihu zapečeť až do času konce. Mnozí budou prohledávat a poznání se rozmnoží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Nato jsem já, Daniel, spatřil, jak jiní dva stojí, jeden na tomto břehu řečiště a druhý na onom břehu řečiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Jeden řekl muži oděnému lněným oděvem nahoře nad vodami v řečišti: Za jak dlouho nastane konec těch podivuhodností?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Pak jsem slyšel onoho muže oděného lněným oděvem nahoře nad vodami v řečišti, jak pozdvihl pravici i levici k nebesům a přisáhl při Věčně živém, že k určené době, dobám a polovině, a až skončí tříštění ruky svatého lidu, toto vše pomine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Já jsem to sice slyšel, ale nechápal, a proto jsem řekl: Pane můj, co přijde koncem těch věcí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Nato mi odvětil: Běž, Danieli, neboť ta slova jsou uzavřena a zapečetěna až do času konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Mnozí budou čištěni a běleni a tříbeni. Zatímco ničemové budou jednat ničemně a žádní ničemové nic nepochopí, ti rozumní však pochopí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'A od doby odstranění soustavné bohoslužby a k dání pustošící ohavnosti uplyne tisíc dvě stě devadesát dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Blaze tomu, kdo počká a dospěje ke dnům tisíci třem stům třiceti a pěti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Ty ale dojdi do konce a budeš odpočívat. Na konci dnů pak povstaneš ke svému údělu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Hospodinovo slovo, které se stalo k Ozeášovi, synu Beérovu, ve dnech judských králů Uzijáše, Jótama, Achaza a Chizkijáše a ve dnech izraelského krále Jarobeáma, syna Jóašova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Počátek ⌈Hospodinova mluvení⌉ skrze Ozeáše. Hospodin řekl Ozeášovi: Jdi, vezmi si ⌈ženu smilstva⌉ a měj děti smilstva, protože země strašlivě smilní a odvrací se od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Tak šel a vzal si Gómeru, dceru diblajimskou. Ona otěhotněla a porodila mu syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Hospodin mu řekl: Pojmenuj ho Jizreel, protože už jen chvilku a navštívím dům Jehúův s trestem za krev prolitou v Jizreelu a ukončím kralování domu izraelského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, '⌈I stane se v onen den,⌉ že zlomím Izraelův luk v údolí Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Otěhotněla znovu a porodila dceru. Řekl mu: Pojmenuj ji Lórucháma, protože už nebudu mít déle slitování nad domem izraelským, ale jistě se postavím proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Nad domem judským se slituji a zachráním je kvůli Hospodinu, jejich Bohu. Nezachráním je kvůli luku, meči, boji, koňům či jezdcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Odstavila Lóruchámu, otěhotněla a porodila syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Řekl: Pojmenuj ho: Ló–amí, protože vy ne jste mým lidem a já nebudu vaším Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Avšak počet synů Izraele bude jako počet mořského písku, který nemůže být změřen ani spočítán. I stane se, že místo toho, že jim bylo řečeno: ⌈Nejste můj lid,⌉ jim bude řečeno: Jste synové ⌈živého Boha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Synové Judy i synové Izraele budou společně shromážděni, ustanoví si jednoho předáka a vyjdou ze země, neboť velký bude den Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Řekněte svým bratrům: Můj lide a svým sestrám: Omilostněná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Veďte při se svou matkou, veďte, protože ona ne ní mou ženou a já ne jsem jejím mužem. Ať ⌈od sebe⌉ odstraní svá smilstva a znaky svého cizoložství zprostřed svých prsů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Jinak ji svléknu do naha a vystavím ji, jak byla v den svého zrodu; proměním ji, že bude jako pustina, učiním ji podobnou bezvodé zemi a nechám ji zemřít žízní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Ani nad jejími syny se neslituji, protože jsou to synové smilstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Protože jejich matka smilnila, nestydatě jednala ta, jež je počala. Vždyť říkala: Půjdu za svými milenci, kteří mi dávají chléb a vodu, vlnu a len, olej a nápoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Proto hle, zatarasím její cestu trním, ⌈zazdím ji zdí,⌉ aby nenašla své stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Bude honit své milence, ale nedostihne je, bude je hledat, ale nenajde je. Pak řekne: Půjdu a navrátím se ke svému prvnímu muži, protože tehdy mi bylo lépe než nyní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Neví, že já jsem jí dával obilí, nové víno i olej a rozmnožil jsem jí stříbro a zlato, které oni použili pro Baala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Proto si vezmu zpět své obilí ⌈v jeho době⌉ i své nové víno v jeho určený čas; odejmu svoji vlnu a svůj len, které měly zakrývat její nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Nyní odhalím její hanbu před očima jejích milenců a nikdo ji nevysvobodí z mé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Ukončím všechny její oslavy, její každoroční svátky, její novoluní, její soboty -- všechny její určené svátky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Zpustoším její révu a její fíkovníky, o nichž říkala: ⌈To je moje mzda, kterou mi dali moji milenci.⌉ Proměním je v houštinu a bude je požírat polní zvěř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Navštívím ji s trestem za dny baalů, kdy jim obětovala, zdobila se svými náušnicemi a šperky, chodila za svými milenci, ale na mě zapomněla, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Ale hle, já ji přivábím, přivedu ji do pustiny a ⌈budu mluvit k jejímu srdci. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Tam jí dám její vinici a údolí Akór jako bránu naděje. Tam ⌈bude povolná⌉ jako za dnů svého mládí, jako v den, kdy vyšla z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, '⌈I stane se v onen den,⌉ je Hospodinův výrok, že budeš volat: ⌈Můj muži,⌉ a nebudeš už na mě volat: ⌈Můj Baale.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Odstraním ⌈jména baalů⌉ z jejích úst a nebudou připomínáni už svým jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'V onen den pro ně uzavřu smlouvu s polní zvěří, s nebeskými ptáky a zemskými plazy. Odstraním ze země luk, meč i válku a dám jim pobývat v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Zasnoubím si tě navěky, zasnoubím si tě spravedlností, právem, milosrdenstvím a slitováním,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'zasnoubím si tě věrností a poznáš Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'I stane se v onen den, že odpovím, je Hospodinův výrok, odpovím nebesům a ona odpovědí zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'Země odpoví obilí, novému vínu a oleji a ony odpovědí Jizreelu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Zaseji si ji do země a slituji se nad Ló–ruchámou. Řeknu Ló–amímu: Ty jsi můj lid a on řekne: Můj Bože!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Hospodin mi řekl: Znovu jdi a miluj ženu, milenku jiného, cizoložnici, jako Hospodin miluje syny Izraele, ačkoliv se obracejí k jiným bohům a milují hrozinkové koláče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Koupil jsem si ji tedy za patnáct šekelů stříbra a chómer a létech ječmene.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Řekl jsem jí: Pobývej se mnou po mnoho dní. Nesmilni a ⌈neměj styk s mužem⌉ a ⌈ani já nevejdu k tobě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Neboť ⌈ po mnoho dní⌉ budou synové Izraele pobývat bez krále, bez knížete, bez obětního hodu, bez posvátného sloupu, bez efódu a domácích bůžků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Potom se synové Izraele navrátí a budou hledat Hospodina, svého Boha, a svého krále Davida. ⌈V posledních dnech⌉ se s třesením obrátí k Hospodinu a k jeho dobrotě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Slyšte Hospodinovo slovo, synové Izraele, neboť Hospodin vede spor s obyvateli země, protože v zemi ne ní ⌈věrnost ani milosrdenství⌉ ani poznání Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Rozhojnilo se proklínání a lhaní, vraždy a krádeže a cizoložství, ⌈nastává jedno prolévání krve za druhým.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Proto truchlí země a chřadnou všichni, kdo v ní bydlí, s polní zvěří a s nebeským ptactvem; i ⌈mořské ryby⌉ zahynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Jen ať nikdo nevede při, ať nikdo nekárá. ⌈Tvůj lid je jako ti, kdo vedou při s knězem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Klopýtneš ve dne, klopýtne s tebou i prorok v noci, ⌈zničím tvou matku.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Můj lid hyne ⌈pro nedostatek⌉ poznání. Protože jsi zavrhl poznání, zavrhl jsem tebe, nebudeš mi sloužit jako kněz. Zapomněl jsi na zákon svého Boha, i já zapomenu na tvé syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Čím jich bylo víc, tím víc proti mně hřešili. ⌈Jejich slávu proměním v hanbu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Pojídají oběti za hřích mého lidu, ⌈prahnou po jejich vině.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, '⌈Knězi se stane tak jako lidu:⌉ Navštívím ho s trestem za jeho cesty a odplatím mu za jeho činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Budou jíst, ale nenasytí se, budou smilnit, ale nerozmnoží se, protože opustili Hospodina, aby se oddali');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'smilstvu. Staré a nové víno připravuje o rozum');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'můj lid. Doptává se svého dřeva, ⌈jeho hůlka mu věští;⌉ protože je svedl duch smilstva, ⌈smilstvem se odvrátili od svého Boha.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Obětují na vrcholcích hor, na návrších pálí oběti, pod dubem, styraxem a řečíkem terebintem, protože jeho stín je příjemný. Proto vaše dcery smilní a vaše snachy cizoloží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Nenavštívím s trestem vaše dcery, že smilní, a vaše nevěsty, že cizoloží, neboť oni sami ⌈chodí stranou⌉ s prostitutkami a obětují s chrámovými nevěstkami. Lid bez porozumění bude sražen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Jestliže smilníš ty, Izraeli, ať se neproviní Juda! Nechoďte do Gilgálu! Nevstupujte do Bét–ávenu! Nepřísahejte: Jakože živ je Hospodin!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Vždyť Izrael je umíněný jako umíněná kráva. Hospodin je nyní bude pást jako beránka na širých pastvinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efrajim se spolčil s modlářskými zpodobeninami, nech ho být.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Když skončili s pitím, ⌈propadli smilstvu.⌉ Milovali víc hanbu nežli svoji čest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Vítr je ⌈uchvátí svými křídly,⌉ bude se stydět za své oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Slyšte to, kněží! Pozorně naslouchejte, dome izraelský! Poslouchejte, dome královský, protože ⌈tento rozsudek je proti vám!⌉ Neboť jste byli pastí pro Mispu, rozprostřenou sítí na Táboře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, '⌈jámou, kterou vyhloubili v Šitímu.⌉ Já mám kázeň pro ně pro všechny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Já znám Efrajima, Izrael ne ní přede mnou skryt. Protože jsi teď smilnil, Efrajime, Izrael je poskvrněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Jejich činy jim nedovolí navrátit se k jejich Bohu, protože v jejich nitru je duch smilstva, Hospodina neznají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Pýcha Izraele svědčí proti němu, Izrael a Efrajim klopýtnou pro své viny, s nimi klopýtne i Juda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Se svým ⌈bravem a skotem⌉ půjdou hledat Hospodina, ale nenajdou ho, vzdálil se od nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Nevěrně opustili Hospodina, protože zplodili cizí syny. Nyní je i s jejich podíly pohltí novoluní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Trubte na beraní roh v Gibeji, na trubku v Rámě! Křičte v Bét–ávenu, třes se, Benjamíne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efrajim se stane v den trestu děsivou krajinou. Mezi kmeny Izraele oznamuji ⌈ to, co je spolehlivé.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Judská knížata jsou jako ti, kdo posouvají mezníky, vyleji na ně svůj hněv jako vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efrajim je utlačován, drcen soudem, protože byl odhodlán chodit za marností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Já jsem pro Efrajima jako mol, pro dům judský jako hniloba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Když Efrajim uviděl svou nemoc a Juda svůj vřed, šel Efrajim do Asýrie, poslal k mocnému králi. Ale on vás není schopen uzdravit ani ⌈zbavit vás⌉ vředu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Neboť já jsem pro Efrajima jako lev a pro dům judský jako mladý lev. Já, já rozsápu a odejdu, odnesu a není, kdo by vysvobodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Odejdu a navrátím se na své místo, dokud ne uznají vinu a ne budou hledat moji přítomnost. Ve své tísni mě budou usilovně hledat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Pojďte, navraťme se k Hospodinu, protože on rozsápal, on nás i vyléčí. Zranil, on nás i obváže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Po ⌈dvou dnech⌉ nás oživí, ⌈třetího dne⌉ nám dá povstat, abychom žili ⌈před ním.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Poznejme, usilujme poznat Hospodina! Vyjde jistě jako jitřenka, přijde k nám jako déšť, jako jarní déšť, který zavlažuje zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Co s tebou mám udělat, Efrajime? Co s tebou mám udělat, Judo? Vždyť vaše věrnost je jako ranní oblak, jako rosa, která brzy odchází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Proto jsem tě srazil skrze proroky, zabil jsem tě ⌈řečí svých úst⌉ ⌈a můj soud vyjde jako světlo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Neboť já mám zalíbení v milosrdenství, a ne v obětech, poznání Boha jsem si oblíbil víc než zápalné oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Avšak oni přestoupili smlouvu ⌈jako Adam,⌉ ⌈v tom⌉ mě nevěrně opustili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gileád je městem zločinců, plným krvavých stop.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Houf kněží je jako číhající loupežná horda; vraždí na cestě do Šekemu, spáchali hnusnou věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'V domě izraelském jsem viděl něco otřesného: Efrajim tam smilní, Izrael je poskvrněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'I pro tebe, Judo, je připravena žeň! ⌈Když měním úděl svého lidu,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'když uzdravuji Izrael, je zjevena Efrajimova vina a zlo Samaří. Neboť podvádějí, zloděj proniká do domu, na ulici vtrhla loupežná horda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, '⌈Nemyslí na to,⌉ že pamatuji na všechno jejich zlo. Nyní je jejich činy obklopují, jsou přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Svým zlem dělá radost králi a svými podvody knížatům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Všichni jsou cizoložníci; jsou jako rozpálená pec, kterou pekař přestane rozdmýchávat od zadělání těsta až do jeho vykynutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'V den našeho krále onemocněla knížata rozpálená vínem. ⌈Bude vztahovat svou ruku s⌉ posměvači.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Vždyť jejich srdce jsou podpálena lstí jako pec, jejich hněv spí celou noc, ráno plane jako plápolající oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Všichni jsou rozpáleni jako pec, požírají své soudce. Všichni jejich králové padli, nikdo z nich ke mně nevolá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efrajim se mísí mezi národy, Efrajim se stal neobráceným chlebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Cizinci pohlcují jeho sílu, ⌈a on to neví,⌉ vplížily se mu také šediny, a on to neví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Pýcha Izraele svědčí proti němu, ale neobracejí se k Hospodinu, svému Bohu, ani po tom všem ho nehledají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Efrajim je jako holubice, nezkušená a bez rozumu. Volají po Egyptu, chodí do Asýrie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Když půjdou, rozprostřu nad nimi svou síť, svrhnu je jako nebeské ptactvo, napravím je, jak bylo oznámeno jejich shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Běda jim, že ode mě uletěli! Zkáza na ně, že se proti mně vzbouřili! Já jsem je chtěl vykoupit, ale oni proti mně mluvili lži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Nevolali ke mně o pomoc ve svém srdci, ale naříkali na svých ložích. ⌈Zasazují si rány⌉ kvůli obilí a novému vínu a odvracejí se ode mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Já jsem je napravoval a posiloval jejich paže, oni však proti mně vymýšlejí zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Obracejí se, ⌈ ale ne ke mně,⌉ jsou jako záludný luk. Jejich knížata ⌈padnou mečem⌉ pro svůj hněvivý jazyk. To ⌈jim bude v egyptské zemi ku posměchu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Beraní roh ke tvým ústům! Jako orel je nad ⌈Hospodinovým domem,⌉ protože přestoupili moji smlouvu, vzbouřili se proti mým zákonům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, '⌈Volají ke mně o pomoc: Můj Bože! My, Izraelci, tě známe.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Izrael odvrhl dobro, bude ho pronásledovat nepřítel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Sami si ustanovili krále, ne vzešlo to ode mne; určili si vládce, ale já jsem je neuznal. Ze svého stříbra a zlata si učinili modlářské zpodobeniny, aby byli zničeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, '⌈Odvrhl tvoje tele,⌉ Samaří. Můj hněv vzplál proti nim. Jak dlouho budou neschopni čistoty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Vždyť je z Izraele, udělal ho řemeslník, ne ní to Bůh. Samařské tele bude roztřískáno na kousky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Protože zasévají vítr, sklidí bouři. Stéblo nemá zrno, nevydá mouku. I kdyby snad vydalo, zhltnou to cizinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Izrael je pohlcen. Nyní jsou mezi pohanskými národy jako nádoba, v níž nikdo ne má zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Vždyť šli do Asýrie; Efrajim je osamělý divoký osel, najímali si milence.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'I když si je najímali mezi pohanskými národy, nyní je shromáždím. Brzy začnou pociťovat břemeno krále knížat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Když si Efrajim nadělal spoustu oltářů ⌈k očištění hříchu, staly se mu oltáři k hříchu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'I kdybych mu napsal sebevíc ze svého zákona, bylo by to považováno za něco cizího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Obětují obětní hod a maso, aby se najedli, ⌈Hospodin si je neoblíbil. Nyní bude pamatovat na jejich viny a navštíví je s trestem za jejich hříchy.⌉ Navrátí se do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Izrael zapomněl na svého Tvůrce a vystavěl si paláce, Juda si nadělal spoustu opevněných měst. ⌈Pošlu oheň⌉ na jejich města a ten stráví jejich paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Neraduj se, Izraeli! Nejásej jako národy. Vždyť jsi smilnil, odpadl od svého Boha a miloval jsi nevěstčí mzdu na každém obilním humně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Humno a lis je nenasytí, nové víno je ⌈nechá na holičkách.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, '⌈Nebudou sídlit⌉ v Hospodinově zemi, Efrajim se vrátí do Egypta, v Asýrii budou jíst nečisté věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Nebudou vylévat Hospodinu víno v úlitbu, jejich obětní hod ho nepotěší. Je pro ně chlebem truchlících. Všichni, kdo ho jedí, se znečistí, neboť jejich chléb je jen pro ně, nepřijde do Hospodinova domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Co budete dělat v den svátku, v den svátku Hospodinova?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Hle, i kdyby utekli zkáze, shromáždí je Egypt, Memfis je pohřbí. Vzácné je jejich stříbro, zdědí je kopřivy; trny budou v jejich stanech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Přišly dny navštívení, přišly dny odplaty; Izrael ⌈ to pozná.⌉ Je prorok hlupák? Muž ducha potřeštěnec? To pro tvou velkou vinu a velké nepřátelství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, '⌈Prorok je strážným Efrajima pro svého Boha.⌉ Na všech jeho cestách je ptáčníkova past, v domě jeho Boha nepřátelství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Hluboce propadli zvrácenosti jako za dnů Gibeje; bude pamatovat na jejich viny, navštíví je s trestem za jejich hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Nalezl jsem Izrael jako hrozny v pustině. Vaše otce jsem viděl jako ⌈rané ovoce ⌉ na fíkovníku, když poprvé rodí. Oni však šli za Baal–peórem, zasvětili se hanebnosti a stali se ohavností, jako ⌈to, co milovali.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, '⌈Efrajim je jako pták, jejich sláva odletí,⌉ budou bez porodu, bez těhotenství i bez početí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'I když vychovají své syny, učiním je bezdětnými, bez lidí. Ano běda jim, až se od nich odvrátím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efrajim, jak jsem viděl, ⌈ je jako Týr zasazený na pastvině,⌉ avšak Efrajim vyvede své syny na zabití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Dej jim, Hospodine! Co jim dáš? Dej jim lůno, které potratí a vyschlé prsy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Všechno jejich zlo se stalo zjevné v Gilgálu, proto jsem je tam začal nenávidět. Za jejich zvrácené činy je vyženu ze svého domu. Nebudu je již déle milovat, všechna jejich ⌈knížata jsou umíněnci.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efrajim je ubit, jejich kořen uschl, nevydá ovoce. I když porodí, nechám ty vzácné plody jejich lůna zemřít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Můj Bůh je zavrhl, protože jej neposlouchali. Stali se utečenci mezi pohanskými národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Izrael je rozbujelá réva, která ⌈vydává hojné ovoce.⌉ Čím více měl ovoce, tím více nadělal oltářů, čím ⌈lépe se dařilo jeho zemi,⌉ tím více dávali do pořádku posvátné sloupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Jejich srdce je rozdělené, nyní ponesou vinu. On rozbije jejich oltáře, zničí jejich posvátné sloupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Vždyť teď říkají: Nemáme krále! Protože jsme se nebáli Hospodina, ⌈co pro nás může udělat král?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Vyslovují ⌈ prázdná slova,⌉ falešně přísahají a uzavírají smlouvy, takže právo bují na brázdách pole jako jedovatý plevel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Obyvatelé Samaří se strachují o betávenské tele. Jeho lid bude nad ním truchlit, ⌈jeho žreci budou naříkat nad ním, nad jeho slávou,⌉ protože se od něho odstěhovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Také to tele bude odneseno do Asýrie jako dar mocnému králi. Efrajima se zmocní hanba, Izrael se bude stydět za své rozhodnutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, '⌈Samaří i jeho král⌉ zahyne jako pěna na povrchu vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Návrší Ávenu, hřích Izraele, budou zničena. Na jejich oltářích vyroste trní a bodlák. Tehdy řeknou horám: Přikryjte nás! A kopcům: Padněte na nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Ode dnů Gibeje jsi hřešil, Izraeli, tam zůstali stát. Nedostihne je v Gibeji válka proti ⌈vzpurným synům?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, '⌈Podle své touhy⌉ je budu káznit; shromáždím proti nim národy, ⌈až budou spoutáni pro svoji⌉ dvojí vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efrajim byl jhu navyklá jalovice, která ráda mlátí. Já jsem položil jho na její krásnou šíji. Zapřáhnu Efrajima, Juda bude orat, Jákob bude vláčet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Zasévejte si pro spravedlnost, ⌈sklízejte podle⌉ milosrdenství, zorejte si úhor! Je čas hledat Hospodina, dokud ne přijde a ne zavlaží vás spravedlností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Orali jste ničemnost, sklidili jste zvrácenost, jedli jste ovoce podvodu. Protože jsi doufal ve svou cestu, ve množství svých hrdinů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'povstane válečná vřava ⌈proti tvému lidu⌉ a všechny tvoje pevnosti budou zničeny. Jako Šalman zničil Bét–arbél v den boje, kdy byly rozdrceny matky se syny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, '⌈tak učiním s vámi, Bét–ele,⌉ za ⌈vaše strašné zlo.⌉ ⌈Za rozbřesku⌉ jistě izraelský král zahyne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Když byl Izrael mládencem, zamiloval jsem si ho, ⌈z Egypta jsem povolal svého syna.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, '⌈ Čím víc jsem je volal,⌉ ⌈tím víc ode mě odcházeli,⌉ obětovali baalům a pálili oběti modlám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Já jsem učil Efrajima chodit, ⌈bral ho na své paže,⌉ ale nepoznali, že jsem je uzdravil já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Táhl jsem je lidskými provazy, pouty lásky, byl jsem pro ně jako ten, kdo nadlehčuje jho na jejich čelistech, nakláněl jsem se k nim a krmil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Ne! Navrátí se do egyptské země a jeho králem bude Asýrie, protože se odmítli obrátit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'V jeho městě bude řádit meč, bude ničit jeho žvanily, pohltí je za jejich rady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Můj lid se drží odvrácení ode mě, společně volají k Baalovi, ale on je nevyvýší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Jak bych tě mohl vydat, Efrajime? Jak bych tě mohl předat, Izraeli? Jak bych tě mohl vydat jako Admu? Jak bych s tebou mohl učinit to co se Sebójimem? Mé srdce se ve mně změnilo, je vzbuzen všechen můj soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nevykonám svůj planoucí hněv, nezničím znovu Efrajima, protože já jsem Bůh, a ne člověk, Svatý uprostřed tebe, nepřijdu s hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Přijdou za Hospodinem. Bude řvát jako lev. Když on zařve, přiběhnou s třesením synové od západu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'přiletí s třesením jako pták z Egypta a jako holubice z asyrské země a způsobím, že budou bydlet ve svých domech, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efrajim mě obklopil lží, dům izraelský podvodem; Juda ještě chodí s Bohem a je věrný Svatému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Efrajim pase vítr, po celý den se honí za východním větrem, rozmnožuje lež a zkázu. Uzavírají smlouvu s Asýrií, olej je odnášen do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Hospodin vede spor také s Judou, navštíví Jákoba s trestem za jeho cesty a odplatí mu podle jeho činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'V lůně matky držel svého bratra za patu, v ⌈ mužné síle⌉ zápasil s Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Zápasil s andělem a přemohl ho. Plakal a prosil ho o smilování, nalezl ho v Bét–elu a tam s námi mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Hospodin je Bohem zástupů, Hospodin je jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Proto ty se navrať ke svému Bohu, zachovávej milosrdenství a právo, ustavičně čekej na svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Obchodník, v jehož ruce jsou falešné váhy, rád vydírá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Efrajim říká: Jak jsem zbohatl, získal jsem majetek. Ve všem ⌈mém výtěžku⌉ mi neshledají provinění, které by bylo hříchem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Já jsem Hospodin, tvůj Bůh, z egyptské země; znovu tě nechám bydlet ve stanech jako za dnů setkání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Mluvil jsem k prorokům, já sám jsem rozmnožil vidění a skrze proroky ⌈mluvím v podobenstvích.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Je v Gileádu modloslužba? Jistě se stanou nicotou. Obětují v Gilgálu býky? I jejich oltáře se stanou hromadami kamení na brázdách pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Jákob utekl do aramejské roviny, Izrael sloužil za ženu, za ženu střežil stádo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Skrze proroka Hospodin vyvedl Izrael z Egypta a skrze proroka byl Izrael střežen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Efrajim hořce provokoval ke hněvu, jeho Pán na něj dopustí krev, kterou prolil, odplatí mu za jeho hanění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Když Efrajim mluvil, ⌈ nastalo zděšení;⌉ byl vyvýšen v Izraeli, provinil se však s Baalem a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Nyní ⌈dále hřeší,⌉ dělají si slitou modlu ze svého stříbra, podle své zručnosti modlářské zpodobeniny; všechny jsou dílem řemeslníků. Říkají o nich: ⌈Ti, kdo obětují,⌉ líbají telata!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Proto budou jako ranní oblak a jako rosa, která brzy odchází, jako plevy odváté z humna, jako kouř z komína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Ale já jsem Hospodin, tvůj Bůh, z egyptské země. Neznáš Boha kromě mě, mimo mě jiný zachránce ne ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Já jsem tě pásl v pustině, ⌈ve velmi vyprahlé zemi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Když jsem je pásl, nasytili se. Nasytili se a pozdvihlo se jejich srdce, proto na mě zapomněli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Stanu se pro ně lvem, budu číhat u cesty jako leopard.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, '⌈Napadnu je⌉ jako medvědice zbavená mláďat, rozervu ⌈jim hruď,⌉ sežeru je tam jako lvice, rozsápu je jako polní zvěř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, '⌈Zničím tě,⌉ Izraeli, neboť ⌈kdo ti pomůže?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Kde je tedy tvůj král, aby tě zachránil ⌈ve všech tvých městech? A kde jsou tví soudcové,⌉ o nichž jsi řekl: Dej mi krále a knížata?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Dal jsem ti krále ve svém hněvu a vezmu ho ve svém rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Efrajimova vina je svázána, jeho hřích je bezpečně uschován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Přijdou kvůli němu porodní bolesti, on je však nemoudrý syn, neboť v pravý čas nevejde do rodidel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Mám je vyplatit z moci podsvětí? Mám je vykoupit ze smrti? Smrti, kde je tvá morová rána? Podsvětí, kde je tvůj osten? Soucit je ukryt před mým zrakem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Ačkoliv vzkvétá ⌈jako rákosí,⌉ přijde východní vítr, Hospodinův vítr zavane z pustiny; jeho pramen vyschne, vyprahne jeho zdroj; vyplení jeho poklady, všechny vzácné předměty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Samaří ponese vinu, protože bylo vzpurné vůči svému Bohu. Padnou mečem, jejich děti budou rozdrceny, jejich těhotné ženy budou rozpárány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Navrať se, Izraeli, k Hospodinu, svému Bohu, neboť jsi klopýtl pro svoji vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Vezměte s sebou slova a navraťte se k Hospodinu! Řekněte mu: Sejmi celou vinu, přijmi ⌈ naši řeč⌉ a my ti odplatíme býčky svých rtů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Asýrie nás nezachrání, nepojedeme na koních; nebudeme říkat už dílu svých rukou: Náš Bože! V tobě nalezne sirotek slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Vyléčím jejich odvrácení, rád si je zamiluji, neboť můj hněv se odvrátil od Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Budu pro Izrael jako rosa; pokvete jako lilie, zapustí své kořeny jako libanonský cedr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Jeho ratolesti se rozrostou, jeho nádhera bude jako nádhera olivy, jeho ⌈vůně jako vůně libanonského cedru.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Obyvatelé se navrátí do jeho stínu, ⌈znovu budou pěstovat⌉ obilí, pokvetou jako réva, jejíž jméno bude slavné jako jméno libanonského vína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, '⌈Efrajim řekne: K čemu jsou mi ještě modlářské zpodobeniny?⌉ To já jsem mu odpověděl a dohlížel jsem na něj. Jsem jako zelený cypřiš, ode mě pochází tvé ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 10, '⌈Kdo je moudrý, ať těmto věcem porozumí! Kdo rozumný, ať je pozná! Neboť Hospodinovy cesty⌉ jsou přímé, spravedliví po nich půjdou, ale vzpurní na nich klopýtnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Hospodinovo slovo, které se stalo k Jóelovi, synu Petúelovu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Slyšte to, starší, poslouchejte, všichni obyvatelé země! Stalo se něco takového ve vašich dnech nebo ve dnech vašich otců?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Vypravujte o tom svým synům, vaši synové svým synům a jejich synové další generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Zbytek po kobylkách gázám sežraly kobylky arbe, zbytek po kobylkách arbe sežraly kobylky jelek, zbytek po kobylkách jelek sežraly kobylky chasíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Probuďte se, opilci, a plačte! Všichni pijani vína, naříkejte nad sladkým vínem, neboť bylo odňato od vašich úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Protože do mé země vstoupil národ, mocný a bez počtu; jeho zuby jsou jako zuby lva, má tesáky lvice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Proměnil moji révu v děsivou věc, moje fíkovníky v třísky; zcela je obnažil a odvrhl, její ratolesti zbělely.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Naříkej jako panna přepásaná pytlovinou nad snoubencem svého mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Přídavná i litá oběť byla odstraněna z Hospodinova domu; kněží, Hospodinovi služebníci, truchlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Pole je zničeno, země truchlí, neboť obilí je zničeno. Nové víno vyschlo, olej chybí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Styďte se, zemědělci, vinaři, naříkejte nad pšenicí a ječmenem, neboť žeň pole přišla vniveč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Réva uschla, fíkovník zvadl, granátovník i palma a jabloň, všechny polní stromy uschly, uschl jásot lidských synů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Přepásejte se a bědujte, kněží! Naříkejte, služebníci oltáře! Vejděte, nocujte v žíněných rouchách, služebníci mého Boha, protože z domu vašeho Boha byla vzata oběť přídavná i litá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Nachystejte půst, svolejte shromáždění, shromážděte starší a všechny obyvatele země do domu Hospodina, vašeho Boha, a volejte k Hospodinu o pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, '⌈Běda tomu dni!⌉ Neboť ⌈Hospodinův den⌉ je blízko, přijde jako zkáza od Všemohoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Což nebylo odňato před našima očima jídlo, ⌈radost a jásání⌉ z domu našeho Boha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, '⌈Zrna pod svými hroudami zaschla,⌉ sklady zpustošené, sýpky zbořené, protože obilí uschlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Jak vzdychá dobytek! Stáda skotu se zmateně potulují, protože pro ně není pastva. I stáda ovcí trpí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, '⌈K tobě, Hospodine, volám,⌉ neboť stepní pastviny strávil oheň, všechny polní stromy spálil plamen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'I polní zvěř dychtí po tobě, neboť vodní toky vyschly, stepní pastviny strávil oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Trubte na beraní roh na Sijónu, křičte na mé svaté hoře! Ať se chvějí všichni obyvatelé země, neboť přichází Hospodinův den, ano, je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Den temnoty a soumraku, den mračna a husté temnoty, jako rozbřesk se rozprostírá na horách; početný a mocný národ, jakého nebylo od věků ani po něm nebude po mnoho let, z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Před ním stravuje oheň, za ním spaluje plamen. Před ním je země jako zahrada Eden, za ním zcela opuštěná pustina. A není před ním úniku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Jeho vzhled je jako vzhled koní, běží jako jezdečtí koně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Když poskakují po vrcholcích hor, je to jako zvuk válečných vozů, jako zvuk plamene ohně, který požírá strniště, jako mocný lid připravený k boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Před ním se budou národy svíjet bolestí, všechny tváře budou blednout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Poběží jako hrdinové, jako bojovníci vystoupí na hradby. Každý půjde svou cestou a neodchýlí se od své stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Nebudou vrážet jeden do druhého, každý půjde svou silnicí. Ačkoliv padnou na oštěpy, nezastaví se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Vtrhnou do města, poběží po hradbách, vstoupí do domů, proniknou okny jako zloděj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Před ním se chvěje země, třesou se nebesa, slunce a měsíc se zatměly, hvězdy ztratily svou zář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Hospodin pozvedl hlas před svým vojskem, neboť jeho tábor je velmi velký, neboť mocný je ten, kdo činí jeho slovo. Ano, Hospodinův den je velký, velice hrozný. Kdo ho vydrží?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Avšak i nyní je Hospodinův výrok: Navraťte se ke mně celým svým srdcem, s postem, s pláčem a s kvílením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Roztrhněte svá srdce, ne svá roucha a navraťte se k Hospodinu, svému Bohu, protože je milostivý a soucitný, pomalý k hněvu, hojný v milosrdenství, slitovává se nad zlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Kdo ví, snad se odvrátí, slituje a zanechá za sebou požehnání. ⌈Přídavná a litá oběť patří Hospodinu,⌉ vašemu Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Trubte na beraní roh na Sijónu, nachystejte půst, svolejte shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Shromážděte lid, posvěťte shromáždění! Shromážděte starší, shromážděte děti i kojence od prsů! Ať vyjde ženich ze své komnaty a nevěsta ze své svatební komůrky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, '⌈Mezi předsíní a oltářem⌉ ať pláčou kněží, Hospodinovi služebníci. Ať říkají: Hospodine, ⌈pohleď s lítostí na⌉ svůj lid a nevydávej své dědictví v potupu, za pořekadlo mezi pohanskými národy. Proč by měli říkat mezi národy: Kde je jejich Bůh?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Nato Hospodin vzplál žárlivostí pro svou zemi a měl soucit se svým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Odpověděl Hospodin a řekl svému lidu: Hle, posílám vám obilí, nové víno a olej a nasytíte se tím. Nevydám vás už v potupu mezi pohanskými národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Vzdálím od vás seveřana a zaženu ho do bezvodé a zcela opuštěné země; jeho přední voj do moře východního a jeho zadní voj do moře západního. Vystoupí jeho smrad, vystoupí jeho zápach, neboť se vyvyšoval tím, co prováděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Neboj se, země, jásej a raduj se, neboť Hospodin vykonal velké věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Nebojte se, polní zvířata, neboť stepní pastviny se zazelenaly, protože stromy přinesly ovoce, fíkovník a réva vydaly svůj výnos.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Synové Sijónu, jásejte a radujte se v Hospodinu, svém Bohu, protože vám dal učitele spravedlnosti, seslal vám déšť, podzimní i jarní déšť jako na počátku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Humna budou plná zrna a sudy budou oplývat novým vínem a olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Nahradím vám roky, které sežraly kobylky arbe, kobylky jelek, kobylky chasíl a kobylky gázám, mé velké vojsko, které jsem poslal proti vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Dobře a dosyta se najíte a budete chválit jméno Hospodina, svého Boha, který s vámi podivuhodně jednal. Můj lid nebude nikdy zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Poznáte, že jsem uprostřed Izraele a že ⌈já, Hospodin, jsem vaším Bohem,⌉ a nikdo jiný. Můj lid nebude nikdy zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Potom se stane, že vyleji svého Ducha na každé tělo. Vaši synové a vaše dcery budou prorokovat, vaši starci budou mít sny a vaši mládenci budou mít vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Také na otroky a otrokyně vyleji v oněch dnech svého Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Učiním divy na nebi i na zemi, krev, oheň a sloupy kouře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Slunce se změní v temnotu a měsíc v krev, dříve než přijde Hospodinův den, velký a hrozný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'I stane se, že každý, kdo bude vzývat Hospodinovo jméno, se zachrání, protože na hoře Sijón a v Jeruzalémě bude útočiště, jak pravil Hospodin, mezi vyváznuvšími, které Hospodin povolává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, 'Neboť hle, v oněch dnech a v onom čase, kdy změním úděl Judy a Jeruzaléma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'shromáždím všechny národy, zavedu je do údolí Jóšafat a tam se s nimi budu soudit kvůli svému lidu, svému dědictví Izraeli, které rozptýlili mezi národy. Moji zemi si rozdělili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'a o můj lid vrhali los. Dali chlapce za prostitutku a děvče prodali za víno, aby se napili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Co máte proti mně, Týre a Sidóne i všechny pelištejské kraje? Chcete mi odplatit za to, co jsem vykonal? Opravdu chcete něco vykonat proti mně? Snadno a rychle vrátím to, co jste vykonali, na vaši hlavu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'protože jste vzali mé stříbro a mé zlato a přinesli jste mé nejlepší vzácnosti do svých chrámů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'Prodávali jste judské a jeruzalémské syny synům Jávanovým, aby byli odvedeni daleko od svého území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, 'Hle, vzbudím je z místa, kam jste je prodali, a to, co jste vykonali, vrátím na vaši hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'Prodám vaše syny a vaše dcery do ruky synů Judy a oni je prodají Šebajcům, dalekému pohanskému národu, protože Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, 'Volejte to mezi národy: Nachystejte válku, vzbuďte hrdiny! Všichni bojovníci ať přistoupí a vyrazí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, '⌈Překujte své radlice v meče a své vinařské nože v oštěpy!⌉ Slabý ať řekne: Jsem hrdina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'Pospěšte a přijďte, všechny okolní národy, shromážděte se tam. Přiveď, Hospodine, své hrdiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, 'Ať se pohanské národy dají do pohybu a vystoupí do údolí Jóšafat, protože tam usednu, abych soudil všechny okolní národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Pošlete srp, protože žeň dozrála. Pojďte a šlapejte, neboť lis se naplnil, sudy oplývají, protože jejich zla je mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'Bezpočetné davy jsou v Údolí rozhodnutí, protože Hospodinův den v Údolí rozhodnutí je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'Slunce a měsíc se zatměly, hvězdy ztratily svou zář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, 'Hospodin zařval ze Sijónu, z Jeruzaléma vydal svůj hlas, nebesa i země se třesou. Hospodin je útočištěm pro svůj lid, pevností pro syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 17, 'Poznáte, že já Hospodin jsem vaším Bohem, a přebývám na Sijónu, na své svaté hoře. Jeruzalém bude svatý a cizinci skrze něj již neprojdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 18, '⌈I stane se v onen den,⌉ že hory budou kapat sladké víno, návrší budou oplývat mlékem, všechny judské toky budou oplývat vodou, z Hospodinova domu bude vyvěrat pramen a napojí údolí akácií.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 19, 'Egypt se stane pustinou, Edóm se stane pustou stepí, kvůli násilí na synech Judy, protože v jejich zemi prolévali nevinnou krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 20, 'Juda však bude obydlen navěky a Jeruzalém z generace na generaci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 21, 'Pomstím jejich prolitou krev, kterou jsem nepomstil. Hospodin přebývá na Sijónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Slova Ámose, který byl z chovatelů ovcí v Tekóji, jež viděl o Izraeli ve dnech judského krále Uzijáše a ve dnech izraelského krále Jarobeáma, syna Jóašova, dva roky před země třesením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Řekl: Hospodin zařve ze Sijónu, z Jeruzaléma vydá svůj hlas; pastviny pastýřů uschnou, vrchol Karmelu vyschne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, '⌈Toto praví Hospodin:⌉ Kvůli třem přestoupením Damašku, kvůli čtyřem, to neodvrátím, protože mlátili Gileád železnými smyky:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Pošlu oheň na dům Chazaelův a stráví Ben–hadadovy paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Zlomím závoru Damašku, vyhladím vládce z údolí Áven, toho, kdo drží hůl z Bét–Edenu a aramejský lid bude odveden do Kíru, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Toto praví Hospodin: Kvůli třem přestoupením Gazy, kvůli čtyřem, to neodvrátím, protože odvedli všechny vyhnance do zajetí, aby je vydali Edómu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Pošlu oheň na hradby Gazy a ten stráví její paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Vyhladím vládce z Ašdódu a toho, kdo drží hůl z Aškalónu, vztáhnu svoji ruku proti Ekrónu a ostatek Pelištejců zahyne, praví ⌈Panovník Hospodin.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Toto praví Hospodin: Kvůli třem přestoupením Týru, kvůli čtyřem, to neodvrátím, protože vydali všechny vyhnance Edómu a nepamatovali na bratrskou smlouvu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Pošlu oheň na hradby Týru a ten stráví jeho paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Toto praví Hospodin: Kvůli třem přestoupením Edómu, kvůli čtyřem, to neodvrátím, protože pronásledoval mečem svého bratra, udusil své slitování a jeho hněv neustále propuká, jeho rozhořčení trvale zuří:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Pošlu oheň na Téman a ten stráví paláce Bosry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Toto praví Hospodin: Kvůli třem přestoupením synů Amónových, kvůli čtyřem, to neodvrátím, protože rozpárali těhotné Gileádu, aby rozšířili své území:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Zapálím oheň na hradbách Raby a stráví její paláce za válečného křiku v den boje, za vichru v den vichřice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Jejich král půjde do vyhnanství ⌈spolu se svými knížaty,⌉ praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Toto praví Hospodin: Kvůli třem přestoupením Moába, kvůli čtyřem, to neodvrátím, protože spálil kosti edómského krále na vápno:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Pošlu oheň na Moába, ten stráví paláce Kerijótu a Moáb zemře při válečné vřavě, křiku a za zvuku beraního rohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Vyhladím soudce z jeho středu a s ním zabiju všechna jeho knížata, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Toto praví Hospodin: Kvůli třem přestoupením Judy, kvůli čtyřem, to neodvrátím, protože pohrdli Hospodinovým zákonem a nezachovávali jeho ustanovení -- ⌈svedly je jejich lživé modly, za nimiž chodili⌉ jejich otcové:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Pošlu oheň na Judu a ten stráví jeruzalémské paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Toto praví Hospodin: Kvůli třem přestoupením Izraele, kvůli čtyřem, to neodvrátím, protože prodali spravedlivého za stříbro a nuzného za pár sandálů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, '⌈Baží po tom, aby prach země byl na hlavě chudých,⌉ ⌈pokřivují cestu pokorných,⌉ syn i jeho otec chodí k téže děvce, a tak znesvěcují mé svaté jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Roztahují se vedle každého oltáře na roucha vzatá do zástavy, pijí víno pokutovaných v domě svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Já jsem před nimi zničil Emorejce, ⌈jehož výška byla jako výška cedrů⌉ a silný byl jako duby. Zničil jsem jeho plody nahoře i jeho kořeny dole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Já jsem vás vyvedl z egyptské země a vodil jsem vás čtyřicet let pustinou, abyste získali do vlastnictví emorejskou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Ustanovil jsem z vašich synů proroky a z vašich mládenců nazíry. Nebo to tak ne ní, synové Izraele? je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Ale vy jste dávali nazírům pít víno a prorokům jste přikazovali: Neprorokujte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Hle, ⌈nechám vás klesnout tak, jako klesá⌉ vůz plně naložený pokosem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, '⌈Zmizí útočiště pro rychlonohého,⌉ silný si nepomůže svou silou, hrdina nezachrání svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Ten, kdo nosí luk, neobstojí, rychlonohý se nezachrání pro své nohy ani ten, kdo jezdí na koni, nezachrání svou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'I nejodvážnější z hrdinů uteče v onen den nahý, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Slyšte toto slovo, které Hospodin promluvil proti vám, synové Izraele, proti celé čeledi, kterou jsem vyvedl z egyptské země:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Pouze vás jsem poznal ze všech čeledí země, proto vás navštívím s trestem za všechny vaše viny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Cožpak půjdou dva spolu, aniž by se sešli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Cožpak zařve lev v houštině, když nemá kořist? Cožpak mladý lev vydá svůj hlas ze svého doupěte, aniž by něco lapil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Cožpak padne pták do pasti na zemi, když na něj ne ní léčka? Cožpak vyskočí past ze země, když nic nepolapila?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Zdalipak se zatroubí na beraní roh ve městě a lid se netřese? Zdalipak nastane zlo ve městě, aniž by jednal Hospodin?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Vždyť Panovník Hospodin nebude činit nic, pokud neodhalil své důvěrné sdělení svým otrokům prorokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Lev zařval, kdo by se nebál, Panovník Hospodin promluvil, kdo by neprorokoval?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Rozhlaste v palácích v Ašdódu a v palácích v egyptské zemi. Říkejte: Shromážděte se na samařských horách a pohleďte na velké zmatky uprostřed něj a útlak v jeho středu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Neumějí činit, co je správné, je Hospodinův výrok, kupí násilí a zkázu ve svých palácích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Proto takto praví Panovník Hospodin: Protivník ⌈obklíčí zemi,⌉ ⌈strhne tvé pevnosti⌉ a vyplení tvé paláce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Toto praví Hospodin: Jako vysvobozuje pastýř z tlamy lva dva hnáty nebo kus ucha, tak budou vysvobozeni synové Izraele, kteří bydlí v Samaří -- s rohem postele a částí pohovky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Slyšte a svědčete proti ⌈domu Jákobovu,⌉ je výrok Panovníka Hospodina, Boha zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'V den, kdy navštívím Izrael s trestem za jeho přestoupení, navštívím také oltáře Bét–elu; rohy oltáře budou useknuty a padnou na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Udeřím na dům zimní spolu s domem letním, vniveč přijdou domy plné slonoviny, mnoho domů zmizí, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Slyšte toto slovo, ⌈bášanské krávy,⌉ které jste na samařské hoře, které utlačujete chudáky, vydíráte chudé a říkáte svým manželům: Přines, ať se napijeme!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Panovník Hospodin přísahal při své svatosti, že hle, přicházejí na vás dny, kdy vás vyzvedne na hácích, ⌈váš konec⌉ bude na rybářských háčcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Vyjdete trhlinami, každá před sebou, budete uvrženy na Harmón, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Jděte do Bét–elu a bouřete se, do Gilgálu a rozmnožte vzpoury. Ráno přineste své oběti, třetího roku své desátky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Palte oběti díků z kvašeného, vyhlašujte dobrovolné oběti, rozhlašujte je! Vždyť to jste si zamilovali, synové Izraele, je výrok Panovníka Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Ačkoliv jsem vám dal ⌈čistotu zubů⌉ ve všech vašich městech, nedostatek potravy na všech vašich místech, přece jste se ke mně nenavrátili, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Ačkoliv jsem vám odepřel déšť, když byly ještě tři měsíce do sklizně, na jedno město jsem déšť seslal a na druhé jsem ho neseslal. Na jedno pole pršelo a pole, na které nepršelo, uschlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, '⌈Dvě, tři města⌉ se potácela k jinému městu, aby se napili vody, avšak nenasytili se. A přece jste se ke mně nenavrátili, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Bil jsem vás obilnou rzí a snětí, vaše mnohé zahrady, vaše vinice, vaše fíkovníky a vaše olivy sežraly kobylky, a přece jste se ke mně nenavrátili, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Poslal jsem na vás mor tak jako na Egypt, zabil jsem mečem vaše mládence spolu s vašimi zajatými koňmi, způsobil jsem, aby stoupal smrad vašeho tábora do vašich nosů, a přece jste se ke mně nenavrátili, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Vyvrátil jsem vás, jako Bůh vyvrátil Sodomu a Gomoru, byli jste jako poleno zachráněné ⌈z ohně,⌉ a přece jste se ke mně nenavrátili, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Proto s tebou naložím takto, Izraeli. A protože s tebou naložím takto, připrav se na setkání se svým Bohem, Izraeli!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Hle, ⌈ten, kdo vytváří hory a tvoří vítr,⌉ kdo oznamuje člověku, jaké je jeho myšlení, kdo činí rozbřesk temnotou a kráčí po návrších země, Hospodin, Bůh zástupů je jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Slyšte toto slovo, které pronáším nad vámi, tento žalozpěv, dome izraelský:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Padla a již nevstane, panna izraelská, opuštěná leží na své zemi, ne ní, kdo by ji pozdvihl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Neboť toto praví Panovník Hospodin: Městu, které vytáhne s tisícem, zůstane sto, a které vytáhne se stem, zůstane deset ⌈pro dům izraelský.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Neboť toto praví Hospodin domu izraelskému: Hledejte mě a budete žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Nevyhledávejte Bét–el, nechoďte do Gilgálu, neputujte do Beer–šeby, protože Gilgál bude zcela jistě odveden do exilu a Bét–el se stane ničím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Hledejte Hospodina a budete žít, jinak pronikne dům Josefův jako oheň, bude ho stravovat a nikdo ho neuhasí, aby zachránil Bét–el,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, '⌈který převrací⌉ právo v pelyněk a spravedlnost hází na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Hledejte toho, kdo učinil Plejády i Orion, kdo obrací nejhlubší tmu v ráno a den zatmívá nocí, kdo volá na vodu moře a vylévá ji na povrch země; Hospodin je jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, '⌈Nechává zazářit⌉ zkázu nad mocným, takže zkáza přijde na pevnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Nenávidí toho, kdo v bráně kárá, opovrhují tím, kdo mluví bezúhonně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'A tak, protože ⌈zvyšujete chudému nájemné⌉ a berete od něho obilnou daň -- postavili jste si domy z tesaného kamene, ale bydlet v nich nebudete, vysadili jste překrásné vinice, ale víno z nich pít nebudete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Neboť znám vaše mnohá přestoupení, bezpočet vašich hříchů: Utlačujete spravedlivého, berete úplatek a odstrkujete chudé v bráně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Proto ten, kdo je rozumný, v této době umlkne, neboť je zlá doba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Hledejte dobro a ne zlo, abyste byli živi, a Hospodin, Bůh zástupů, s vámi bude tak, jak jste řekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Nenáviďte zlo a milujte dobro, ustanovte v bráně právo! Snad se Hospodin, Bůh zástupů, nad ostatkem Josefa slituje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Proto takto praví Hospodin, Bůh zástupů, Panovník: Na všech náměstích bude kvílení, na všech ulicích budou říkat: Běda, běda! Zemědělce budou svolávat ke smutečnímu obřadu, ke kvílení ⌈ty, kdo znají žalozpěv.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Na všech vinicích bude kvílení, protože projdu tvým středem, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Běda těm, kdo dychtí po Hospodinově dni! Nač je vám Hospodinův den? Bude temnotou, a ne světlem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Jako když člověk utíká před lvem a potká ho medvěd, vejde do domu, položí svou ruku na stěnu a uštkne ho had.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Cožpak ne ní Hospodinův ⌈den temnotou, a ne světlem,⌉ tmou, ve které ne ní záře?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Nenávidím a zavrhuji vaše svátky, nemohu snést vaše slavnostní shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'I když mi přinášíte své zápalné a přídavné oběti, neoblíbím si je, nepohledím na pokojnou oběť z vašeho krmného dobytka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Odstraň ode mě hluk svých písní, zvuk tvých harf ne chci slyšet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Ale ať se valí právo jako voda a spravedlnost jako stále proudící potok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Přinášeli jste mi v pustině čtyřicet let obětní hody a přídavné oběti, dome izraelský?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Pozvednete Sikúta, svého krále, a Kijúna, svého boha hvězd, své modly, které jste si udělali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'a odvedu vás za Damašek, praví Hospodin; Bůh zástupů je jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Běda bezstarostným na Sijónu, sebejistým na samařské hoře, vznešeným nejlepšího z národů, ke kterým přichází dům izraelský!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Projděte Kalné a dívejte se! Odtamtud jděte do velkého Chamátu a sestupte do pelištejského Gatu! Cožpak jsou lepší nežli tato království? Zdalipak je jejich území větší nežli vaše?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Oddalujete zlý den a nastolujete vládu násilí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Leží na postelích ze slonoviny, povalují se na svých pohovkách, jedí jehňata ze stáda a telata z chléva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Improvizují na harfu, jako David si vymýšlejí na hudební nástroje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Pijí víno z obětních misek, mažou se nejlepším olejem, ale nad Josefovou zkázou nejsou zarmouceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Proto nyní budou jako první odvedeni do exilu a skončí hlučné oslavy povalečů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Přísahal Panovník Hospodin při sobě samém, je výrok Hospodina, Boha zástupů: Hnusí se mi Jákobova pýcha, nenávidím jeho paláce. Vydám město i ⌈všechno, co je v něm.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'I stane se, že když zůstane deset mužů v jednom domě, zemřou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Když jeho příbuzný, jeho pozůstalý, někoho zvedne, aby vynesl kosti z toho domu, řekne někomu v nejvzdálenější části domu: Je ještě někdo s tebou? Odpoví: Nikdo. Řekne: Ticho! Ať není připomínáno Hospodinovo jméno!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Neboť hle, Hospodin přikáže a rozbije velký dům na trosky a malý dům na kusy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Cožpak poběží koně po skalách? Nebo ⌈se na ní orá se skotem?⌉ Avšak vy jste převrátili právo v jedovatý plevel a ovoce spravedlnosti v pelyněk,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'vy, kteří se radujete nad Lódebarem a říkáte: Cožpak jsme se nezmocnili Karnajimu svou silou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Neboť hle, nechávám proti vám, dome izraelský, povstat pohanský národ -- je výrok Hospodina, Boha zástupů, a budou vás utlačovat od ⌈Lebo–Chamátu až k potoku Araby.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Toto mi ukázal Panovník Hospodin: Hle, tvořil kobylky, když začala vzcházet jarní setba. A hle, jarní setba vzchází po královské žatvě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Stalo se, když ⌈zcela sežraly⌉ zeleň země, že jsem řekl: Panovníku Hospodine, odpusť, prosím! Jak Jákob obstojí? Vždyť je malý!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Hospodin toho litoval. Nestane se to, řekl Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Toto mi ukázal Panovník Hospodin: Hle, Panovník Hospodin ⌈zavolal na soud⌉ ohněm. Ten strávil velkou hlubinu a stravuje díl země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Řekl jsem: Panovníku Hospodine, přestaň, prosím! Jak Jákob obstojí? Vždyť je malý!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Hospodin toho litoval. Ani toto se nestane, řekl Panovník Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Toto mi ukázal: Hle, Panovník stál na ⌈hradbě postavené podle olovnice⌉ a v jeho ruce byla olovnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Hospodin mi řekl: ⌈Co vidíš,⌉ Ámosi? Odpověděl jsem: Olovnici. Panovník řekl: Hle, umístím olovnici doprostřed ⌈svého lidu,⌉ Izraele. Nebudu mu již déle promíjet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Izákova návrší budou zpustošena, izraelské svatyně zpustnou a proti domu Jarobeámovu povstanu s mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Tehdy bételský kněz Amasjáš poslal k izraelskému králi Jarobeámovi se slovy: Ámos se proti tobě spikl uprostřed domu izraelského. Země není schopna snášet všechna jeho slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Neboť Ámos řekl toto: Jarobeám zemře mečem a Izrael bude ze své země zcela jistě odveden do exilu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Amasjáš řekl Ámosovi: Vidoucí, jdi, uteč do judské země, tam ⌈jez chléb⌉ a tam prorokuj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Ale v Bét–elu již déle neprorokuj, protože to je svatyně králova a královský palác.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Ámos odpověděl Amasjášovi: Já jsem ne byl prorok ani prorocký žák, ale byl jsem chovatel dobytka a pěstitel fíkovníků sykomor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Hospodin mě však vzal od ⌈ chovu ovcí⌉ a řekl mi: Jdi a prorokuj mému lidu Izraeli!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Nyní slyš Hospodinovo slovo: Ty říkáš: Neprorokuj proti Izraeli a nemluv proti domu Izákovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Proto takto praví Hospodin: Tvá žena ⌈bude smilnit ve městě,⌉ tvoji synové a tvé dcery padnou mečem, tvá země bude rozdělena provazem a ty zemřeš v nečisté zemi. ⌈Izrael bude ze své země zcela jistě odveden do exilu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Toto mi ukázal Panovník Hospodin: Hle, koš letního ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Řekl: Co vidíš, Ámosi? Řekl jsem: Koš letního ovoce. Hospodin mi řekl: Přišel konec pro můj lid Izrael. Nebudu mu již déle promíjet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'V onen den ⌈budou palácové zpěvačky naříkat,⌉ je výrok Panovníka Hospodina, na každém místě bude pohozeno mnoho mrtvol. Ticho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Slyšte to, vy, kteří bažíte po nuzném, chcete odstranit chudé v zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Říkáte: Kdy přejde novoluní, abychom prodávali obilí, sobota, abychom otevřeli obilnice, umenšovali míru a zvyšovali cenu a podváděli falešnými váhami,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'abychom chudé kupovali za stříbro, nuzného za pár sandálů a prodávali obilný odpad?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Hospodin přísahal při Jákobově pýše: Nikdy nezapomenu na žádné jejich skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Cožpak se nad tím nebude třást země, ne budou truchlit ⌈všichni, kdo v ní bydlí?⌉ Celá vystoupí jako Nil, vzedme se a klesne jako egyptská řeka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, '⌈I stane se v onen den,⌉ je výrok Panovníka Hospodina, že skloním slunce v poledne a způsobím na zemi tmu ⌈za jasného dne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Změním vaše svátky v smuteční obřad, všechny vaše písně v žalozpěv; dám na každé bedro pytlovinu a na každou hlavu lysinu; proměním zemi ve smuteční obřad nad jedináčkem a její konec bude jako hořký den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, '⌈Hle, přicházejí dny, je výrok⌉ Panovníka Hospodina, kdy pošlu na zemi hlad. Nikoli hlad po chlebu ani žízeň po vodě, ale po slyšení Hospodinových slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Budou se potácet od moře k moři, ze severu až na východ, budou pobíhat, aby hledali Hospodinovo slovo, ale nenaleznou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'V onen den budou krásné panny omdlévat a mládenci budou vyprahlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Ti, kdo přísahají při ⌈vině Samaří⌉ a říkají: Jakože živ je tvůj bůh, Dane, jakože je živa ⌈cesta do Beer–šeby,⌉ padnou a už nevstanou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Viděl jsem Panovníka stojícího na oltáři. Řekl: Udeř na hlavice sloupů, až se zatřesou prahy. Sraz je na jejich hlavu. Poslední z nich zabiju mečem. Žádný utečenec neuteče, žádný uprchlík neunikne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'I kdyby se prokopali do podsvětí, má ruka je odtamtud vezme. I kdyby vystoupili na nebesa, svrhnu je odtamtud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'I kdyby se ukryli na vrcholu Karmelu, vyhledám je a vezmu je odtamtud. I kdyby se ukryli před mým zrakem na dno moře, přikáži hadovi a uštkne je tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'I kdyby šli před svými nepřáteli do zajetí, přikáži meči a zabije je tam. Obrátím na ně svůj zrak ke zlu a ne k dobru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Panovník, Hospodin zástupů, se dotýká země a ta se rozplývá; truchlí všichni, kdo v ní bydlí. Celá vystupuje jako Nil a klesá jako egyptská řeka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Buduje na nebesích své pokojíky, své klenbě položil základy na zemi, povolává vodu moře a vylévá ji na povrch země. Hospodin je jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Cožpak pro mě nejste jako synové Kúšijců, synové izraelští? je Hospodinův výrok. Cožpak jsem nevyvedl Izrael z egyptské země a také Pelištejce z Kaftóru a Aramejce z Kíru?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Hle, oči Panovníka Hospodina hledí na hříšné království, vyhladím ho z povrchu země, ale nevyhladím zcela dům Jákobův, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Neboť hle, přikáži a zatřesu s domem izraelským mezi všemi národy jako se třese se sítem, a ani kamínek nepadne na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Mečem zemřou všichni hříšníci z mého lidu, kteří říkají: Nepřiblíží se ani nás ne potká to zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'V onen den dám povstat Davidovu padajícímu stánku, jeho trhliny zazdím a jeho troskám dám povstat, vystavím ho jako za dávných dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Aby dostali do vlastnictví ostatek Edómu a všechny národy, ⌈které byly nazvány⌉ mým jménem, je výrok Hospodina, který to učiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Hle, přicházejí dny, je Hospodinův výrok, kdy se přiblíží oráč k ženci a ten, kdo lisuje hrozny, k rozsévači; z hor bude kanout sladké víno a všechny kopce budou oplývat hojností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Změním úděl svého lidu Izraele: Vystavím opuštěná města a budou v nich bydlet, budou vysazovat vinice a pít jejich víno, budou zakládat zahrady a jíst jejich ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Zasadím je do jejich půdy a nebudou již vyrváni ze své země, kterou jsem jim dal, praví Hospodin, tvůj Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Vidění Abdiášovo. Toto praví Panovník Hospodin o Edómu: Slyšeli jsme zprávu od Hospodina, byl poslán vyslanec mezi národy: Vstaňte, povstaňme proti němu k boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Hle, učiním tě malým mezi národy, velmi opovrženým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Domýšlivost tvého srdce tě podvedla, tebe, který bydlíš ve skalních rozsedlinách, toho jenž sedí na vysokých místech a říká si v srdci: Kdo mě může svrhnout na zemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'I kdybys byl vysoko jako orel, i kdyby sis postavil hnízdo mezi hvězdami, i odtamtud tě svrhnu, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Kdyby na tebe přišli zloději či ničitelé v noci -- jak jsi zničen -- což nebudou krást, dokud nebudou mít dost? Kdyby na tě přišli česači hroznů, což nezanechají paběrky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Jak bude Ezau prozkoumán, jeho skrýše budou prohledány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Na hranici tě opustí všichni tvoji spojenci. Podvedou tě, přemohou tě ti ⌈tví důvěrní přátelé.⌉ Ti, kdo jedli tvůj chléb, ti nastraží léčku. ⌈Není v něm rozumnost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Což v onom dni, je Hospodinův výrok, neodstraním z Edómu moudré a rozumnost z Ezauovy hory?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Tvoji hrdinové ⌈se budou třást,⌉ Témane, protože všichni z Ezauovy hory budou vyvražděni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Pro násilí na tvém bratru Jákobovi přikryje tě hanba, budeš vyhlazen navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'V den, kdy jsi stál stranou, v den, kdy cizinci odvedli do zajetí jeho vojsko, cizozemci vešli do jeho bran a vrhali los o Jeruzalém, i tys byl jako jeden z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Nehleď škodolibě na den svého bratra v den jeho neštěstí, neraduj se nad syny judskými v den, kdy hynou, ať se nevyvyšují tvá ústa v den soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Nevcházej do brány mého lidu v den jejich pohromy, ani ty nehleď na jeho zlo v den jeho pohromy, nesahej na jeho majetek v den jeho pohromy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Nestůj na křižovatce, abys vyťal jeho utečence, nevydávej jeho vyváznuvší v den soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Hospodinův den je blízko pro všechny národy. Jak jsi činil ty, tak bude učiněno tobě, ⌈to, co jsi vykonal,⌉ se vrátí na tvou hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Jako jste pili na mé svaté hoře, tak budou pít všechny národy ustavičně. Budou pít a hltat, a budou, jako by nikdy nebyly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Ale na hoře Sijón bude útočiště a bude svatá. ⌈Dům Jákobův⌉ bude vlastnit ⌈své vlastnictví.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Dům Jákobův bude ohněm, dům Josefův plamenem, dům Ezauův strništěm, ⌈zapálí jej⌉ a stráví ho. Nikdo z domu Ezauova nevyvázne, neboť Hospodin promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Lid Negebu bude vlastnit Ezauovu horu, lid z Šefely pelištejskou zemi, budou vlastnit též Efrajimovo území a samařské území a Benjamín bude vlastnit Gileád.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Vyhnanci ⌈ z tohoto vojska synů izraelských⌉ ⌈ budou vlastnit kenaanskou zemi ⌉ až do Sarepty a vyhnanci z Jeruzaléma, kteří jsou v Sefaradu, budou vlastnit města Negebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Zachránci vystoupí na horu Sijón, aby ⌈soudili Ezauovu horu.⌉ A království bude patřit Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Stalo se Hospodinovo slovo k Jonášovi, synu Amítajovu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Vstaň, jdi do Ninive, toho velkého města, a volej proti němu, protože jeho zlo vystoupilo přede mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Jonáš vstal, aby utekl pryč od Hospodina do Taršíše. Přišel do Jafy a našel loď plující do Taršíše. ⌈Zaplatil jízdné⌉ a nastoupil na ni, aby se s nimi plavil do Taršíše pryč od Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Hospodin však seslal na moře velký vítr, na moři nastala veliká bouře a ⌈hrozilo, že se loď rozlomí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Námořníci se báli a volali každý ke svému bohu. Předměty, které měli na lodi, vrhali do moře, aby jí odlehčili. Jonáš mezitím sestoupil do zadní části lodi, lehl si a tvrdě spal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Přistoupil k němu velitel posádky a řekl mu: Co je s tebou, ospalče? Vstaň, volej ke svému bohu. Snad si na nás tvůj bůh vzpomene a nezahyneme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Nato řekli jeden druhému: Pojďte, ⌈necháme padnout losy,⌉ abychom poznali, kvůli komu nás potkalo toto zlo. Nechali padnout losy a los padl na Jonáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Zeptali se ho: Pověz nám, prosím, kvůli komu nás potkalo toto zlo? Jakou máš práci? Odkud přicházíš? Jaká je tvá země a z kterého lidu jsi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Odpověděl jim: Jsem Hebrej a bojím se Hospodina, Boha nebes, který učinil moře i souš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Ti muži se převelice báli a řekli mu: Cos to provedl? Ti muži totiž věděli, že utíká pryč od Hospodina, neboť jim to oznámil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Zeptali se ho: Co s tebou máme udělat, aby moře okolo nás utichlo? Moře totiž stále bouřilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Odpověděl jim: Zvedněte mě a vrhněte mě do moře, a moře okolo vás utichne; neboť já vím, že tato velká bouře ⌈na vás přišla ⌉ kvůli mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Ti muži přesto ⌈veslovali ze všech sil,⌉ aby se vrátili k souši, ale nic nezmohli, neboť moře ⌈proti nim⌉ stále bouřilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'A tak volali k Hospodinu: Ach, prosíme, Hospodine, ať nezahyneme ⌈kvůli duši⌉ tohoto muže. Nepřičítej nám nevinnou krev. Vždyť ty, Hospodine, ⌈co chceš, to činíš.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Potom zvedli Jonáše, vrhli ho do moře, a moře ⌈přestalo zuřit.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'A ti muži se Hospodina převelice báli, obětovali Hospodinu oběti a činili mu sliby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Hospodin připravil velkou rybu, aby Jonáše spolkla, a Jonáš byl v břiše té ryby tři dny a tři noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Tehdy se Jonáš modlil k Hospodinu, svému Bohu, z břicha té ryby');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'a řekl: Volal jsem ze svého soužení k Hospodinu, a odpověděl mi, z lůna podsvětí jsem křičel o pomoc, a uslyšel jsi můj hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Uvrhl jsi mě do hlubiny, doprostřed moří, obklopil mě proud, převalily se přese mne všechny tvé příboje a tvé vlny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Řekl jsem si: Byl jsem vyhnán ⌈od tvého zraku.⌉ ⌈ Moci tak znovu⌉ hledět na tvůj svatý chrám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Voda mě obstoupila ⌈až k duši,⌉ obklopila mě hlubina, chaluha ovázala mou hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Sestoupil jsem k základům hor, ⌈země za mnou navěky zavřela své závory,⌉ ale ty jsi vyvedl můj život z jámy, Hospodine, můj Bože.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Když ⌈ve mně umdlévala má duše,⌉ rozpomínal jsem se na Hospodina, má modlitba pronikla k tobě do tvého svatého chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, '⌈Ti, kdo se oddávají klamným nicotnostem,⌉ opouštějí svou věrnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ale já ti budu obětovat ⌈za zvuku písně díků;⌉ co jsem slíbil, splním. Záchrana ⌈ je v⌉ Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'Hospodin pak promluvil k rybě a ta vyvrhla Jonáše na souš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Stalo se Hospodinovo slovo k Jonášovi podruhé:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Vstaň, jdi do Ninive, toho velkého města, a volej k němu zvěst, kterou ti říkám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Jonáš vstal a šel do Ninive podle Hospodinova slova. Ninive bylo velmi veliké město, na tři dny cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Jonáš začal procházet městem první den cesty a volal: Ještě čtyřicet dní, a Ninive bude vyvráceno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Ninivští uvěřili Bohu, vyhlásili půst a všichni, od největšího až po nejmenšího, si oblékli žíněné roucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Když se to dostalo k ninivskému králi, vstal ze svého trůnu, odložil svůj plášť, přikryl se žíněným rouchem a posadil se do popela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, '⌈Vyhlásil: V Ninive,⌉ z rozhodnutí krále a jeho velmožů: Lidé ani zvířata, skot ani brav ať nic neokusí, ať se nesytí ani nepijí vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Ať se lidé i zvířata přikryjí žíněným rouchem a volají ⌈ze vší síly⌉ k Bohu, ať se každý odvrátí od své zlé cesty a od násilí, které je na jeho rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kdo ví, snad se Bůh odvrátí a slituje, odvrátí se od svého planoucího hněvu a nezahyneme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Bůh viděl jejich skutky, že se odvrátili od své zlé cesty. Proto Bůh litoval zla, které prohlásil, že jim učiní, a neučinil to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Jonášovi se to však hrozně moc nelíbilo a rozzlobil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Modlil se k Hospodinu: Ach, Hospodine, což ⌈jsem to neříkal,⌉ když jsem byl ve své zemi? Kvůli tomu jsem chtěl utéct do Taršíše. Vždyť vím, že ty jsi Bůh milostivý a soucitný, ⌈pomalý k hněvu,⌉ hojný v milosrdenství, a slitováváš se nad zlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Nyní, Hospodine, vezmi ode mě prosím můj život. ⌈ Je pro mě lepší, abych zemřel, než abych žil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Hospodin se zeptal: ⌈ Je to dobře, že ses tak rozzlobil?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Jonáš vyšel z města a usadil se na východ od města. Postavil si tam stánek a pobýval pod ním ve stínu, ⌈aby viděl,⌉ co se s městem stane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Hospodin Bůh připravil ricinovník, který vyrostl nad Jonášem, aby byl stínem pro jeho hlavu a vysvobodil ho z jeho trápení. Jonáš se z ricinovníku ⌈převelice radoval.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Když vyšla druhého dne jitřenka, Bůh připravil červa, který napadl ricinovník, takže uschl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'I stalo se, že když vyšlo slunce, připravil Bůh horký východní vítr a slunce bilo na Jonášovu hlavu, takže omdléval. ⌈Přál si zemřít⌉ a řekl: Je pro mě lepší, abych zemřel, než abych žil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Nato se Bůh Jonáše zeptal: Je to dobře, že ses tak rozzlobil kvůli ricinovníku? Ten odpověděl: Je to dobře, že jsem se rozzlobil ⌈až na smrt!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Hospodin řekl: ⌈Tobě je líto⌉ ricinovníku, se kterým ses nenamáhal ani jsi ⌈mu nedal vzrůst;⌉ přes noc vzešel, přes noc zašel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'A mně by ne mělo být líto toho velkého města Ninive, ve kterém je víc než sto dvacet tisíc lidí, ⌈kteří nerozeznají pravici od levice,⌉ a ještě množství zvířat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Hospodinovo slovo, které se stalo k Micheáši Mórešetskému ve dnech judských králů Jótama, Achaza a Chizkijáše, to, co viděl o Samaří a Jeruzalému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Slyšte, ⌈všechny národy,⌉ pozorně naslouchej, země, i všechno, co ji naplňuje. Ať je Panovník Hospodin proti vám svědkem, Panovník ze svého svatého chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Neboť hle, Hospodin vychází ze svého místa, sestoupí a bude šlapat po návrších země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Hory se pod ním rozplynou, údolí se rozpoltí, jako vosk od ohně, jako voda proudící po stráni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'To všechno kvůli Jákobovu přestoupení a kvůli hříchům domu izraelského. Co je Jákobovým přestoupením? Přece Samaří! Co jsou návrší Judy? Přece Jeruzalém!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, '⌈Proměním Samaří v sutiny⌉ na poli, v místo pro vysazení vinice. Jeho kameny uvrhnu do údolí a jeho základy odhalím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Všechny jeho tesané modly budou rozbity, všechny jeho nevěstčí mzdy budou spáleny ohněm, všechny jeho modlářské zpodobeniny proměním v pustinu. Protože je shromáždilo jako nevěstčí mzdu prostitutky, znovu se stanou nevěstčí mzdou prostitutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Proto budu bědovat a naříkat, půjdu bosý a nahý, ⌈budu kvílet jako šakali a truchlit jako⌉ pštrosi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Neboť jeho rána je nevyléčitelná, dostala se až do Judska, dosáhla až k bráně mého lidu, až do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Neoznamujte to v Gatu, vůbec neplačte! V Bét–leafře se válej v prachu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, '⌈Obyvatelé Šafíru, jděte dál⌉ v ⌈nahotě a hanbě.⌉ Obyvatelé Saanánu ne mohli vyjít. Kvílení Bét–eselu ⌈vás připraví o⌉ místo k přebývání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Obyvatelé Marótu ⌈zeslábli touhou po dobru,⌉ ale od Hospodina sestoupilo do brány Jeruzaléma zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Zapřáhněte vozy k ořům, obyvatelé Lakíše! Zde je počátek hříchu pro dceru sijónskou, neboť v tobě tkví přestoupení Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Proto dáš ⌈dary na rozloučenou Mórešet–gatu.⌉ ⌈Domy Akzíbu⌉ budou zklamáním pro izraelské krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Znovu na vás přivedu dobyvatele, obyvatelé Maréši, ⌈až do Adulámu přijde sláva Izraele.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Vyhol si lysinu a ostříhej se kvůli ⌈svým rozkošným synům,⌉ rozšiř svou lysinu jako sup, protože byli od tebe vystěhováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Běda těm, kdo vymýšlejí špatnosti a ⌈páchají zlo⌉ na svých ložích. Provedou ho za svítání, neboť je to v jejich moci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Dychtí po polích a uchvacují je, po domech a zabírají je; utlačují člověka i jeho dům, muže a jeho dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Proto Hospodin praví toto: Hle, zamýšlím proti této čeledi zlo, otrocké jho, ⌈ze kterého nevytáhnete⌉ své šíje. Nebudete chodit povýšeně, neboť to bude ⌈zlá doba.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'V onen den pronesou o vás pořekadlo, budou hořce bědovat a říkat: Jsme zcela zničeni. Podíl mého lidu proměnil. Jak to, že mi ho odebral a mé pole rozdělil odpadlíkům?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Proto nebudeš mít nikoho, kdo by v Hospodinově shromáždění házel los o svůj díl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '⌈Neprorokujte, prorokují, neprorokujte takové věci. Potupa nás nezasáhne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, '⌈ Má se říkat toto, dome Jákobův?⌉ ⌈ Došla Hospodinu trpělivost?⌉ Cožpak jsou toto jeho činy? ⌈Což nejsou mé záměry dobré vůči tomu, kdo žije správně?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, '⌈Můj lid nedávno povstal⌉ jako nepřítel. Svlékáte plášť z oděvu těch, kdo bezstarostně procházejí, ⌈ těch, kdo se navracejí z boje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Ženy mého lidu vyháníte z ⌈jejich rozkošných domovů,⌉ ⌈jejich děti připravujete⌉ navěky o mou důstojnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Vstaňte a odejděte, neboť toto není místo odpočinku ⌈kvůli nečistotě, která přináší zkázu, naprostou zkázu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Kdyby někdo ⌈plácal do větru a⌉ lhal: Budu ti prorokovat o víně a o pivu, to by byl prorok pro tento lid!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Jistě posbírám Jákoba, tebe celého, jistě shromáždím ostatek Izraele. Dám ho pospolu jako ovce do ohrady, jako stádo na pastvinu; bude se to hemžit lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Ten, kdo proráží cestu, vytáhne před nimi. Prorazí, projdou bránou a vyjdou skrze ni. Jejich král půjde před nimi, Hospodin v jejich čele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Řekl jsem: Slyšte, předáci Jákobovi, vůdcové domu izraelského. Což nemáte znát právo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Nenávidíte dobro a milujete zlo, rvete z nich kůži a maso z jejich kostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Ano, jedí maso mého lidu, kůži z nich svlékají, jejich kosti lámou. Kouskují je jako do hrnce, jako maso do kotle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Potom budou volat k Hospodinu, ale neodpoví jim, v ten čas skryje před nimi svou tvář, protože páchali zlé činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Toto praví Hospodin o prorocích, kteří vedou můj lid do bludu, kteří -- když mají co zuby kousat -- vyhlašují pokoj, ale na toho, kdo jim do úst nic nedá, chystají válku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Proto budete mít noc místo vidění, ⌈budete mít tmu⌉ místo věštění. Zajde slunce nad těmi proroky, zatmí se jim den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Vidoucí se budou stydět, věštci se budou hanbit, všichni si budou zakrývat vousy, protože ⌈nebude Boží odpověď.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Avšak já jsem plný moci Ducha Hospodinova, práva a udatnosti, abych oznámil Jákobovi jeho přestoupení a Izraeli jeho hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Slyšte toto, předáci domu Jákobova a vůdcové domu izraelského, kteří opovrhujete právem a všechno, co je správné, převracíte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'kteří stavíte Sijón proléváním krve a Jeruzalém zvráceností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Jeho předáci soudí za úplatek, jeho kněží učí za peníze, jeho proroci věští za stříbro, a pak spoléhají na Hospodina se slovy: Což není Hospodin uprostřed nás? Zlo na nás nepřijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Proto kvůli vám bude Sijón zorán jako pole, Jeruzalém se stane sutinami a chrámová hora zalesněným návrším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'I stane se v ⌈posledních dnech,⌉ že hora Hospodinova domu bude stát pevně jako ⌈přední z hor⌉ a bude vyvýšena nad návrší. Budou k ní proudit lidé');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'a mnohé národy přijdou a řeknou: Pojďte a vystupme na Hospodinovu horu, do domu ⌈Boha Jákobova.⌉ Bude nás učit svým cestám a my budeme chodit po jeho stezkách. Vždyť ze Sijónu vyjde zákon a Hospodinovo slovo z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Bude soudit mezi mnohými národy, kárat mocné ⌈a vzdálené⌉ národy. I překují své meče v radlice a svá kopí ve vinařské nože; národ proti národu nepozdvihne meč a nebudou se již učit boji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Každý bude pobývat pod svou révou a pod svým fíkovníkem a nikdo ho ne vyděsí. Vždyť ⌈promluvila ústa Hospodina⌉ zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, '⌈Každý národ chodí⌉ ve jménu ⌈svého boha,⌉ ale my budeme ⌈chodit ve jménu Hospodina,⌉ našeho Boha, navěky a navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, '⌈V onen den, je Hospodinův výrok, posbírám kulhavou a shromáždím zapuzenou, tu, s níž jsem jednal zle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Proměním kulhavou v ostatek, vyhnanou v mocný národ. A Hospodin nad nimi bude kralovat na hoře Sijón od nynějška až navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'A ty, ⌈věži stáda,⌉ kopci dcery sijónské, k tobě ⌈přijde, vrátí se⌉ prvotní vláda, království jeruzalémské dcery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Proč nyní tak křičíš? Což v tobě není král? Cožpak zahynul tvůj rádce, že se tě zmocnily porodní bolesti jako rodičky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Svíjej se bolestí a křič jako rodička, dcero sijónská, neboť nyní vyjdeš z města, budeš přebývat na poli a přijdeš až do Babylona. Tam budeš zachráněna, tam tě Hospodin vykoupí z ruky tvých nepřátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Nyní se proti tobě shromáždily mnohé národy, které říkají: Ať je znesvěcen, ať se naše oči vynadívají na Sijón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Oni však neznají Hospodinovy úmysly, nerozumějí jeho plánu, že je shromáždil jako snopy na humno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Povstaň a mlať, dcero sijónská, neboť tvé rohy proměním v železo, tvá kopyta proměním v bronz a rozdrtíš mnohé národy. Jejich nekalý zisk pro Hospodina zasvětím zkáze a jejich majetek pro ⌈Pána celé země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Nyní se houfuj, dcero loupežné hordy. Nachystal na nás obležení. Holí budou bít po tváři soudce Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'A ty, Betléme efratský, který jsi nejmenší mezi judskými rody, z tebe mi vzejde ten, kdo bude vládnout nad Izraelem, ten, jehož původ je odedávna, ode dnů věčných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Proto je vydá až do času, kdy rodička porodí. Pak se zbytek jeho bratří navrátí k synům Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Bude stát a pást své stádo v Hospodinově síle, ve vznešenosti jména Hospodina, svého Boha. A budou pobývat v bezpečí, protože bude veliký až do končin země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'A on bude pokoj. Když přitáhne Asýrie do naší země, když vstoupí do našich pevností, ustanovíme ⌈proti ní⌉ sedm pastýřů, osm vazalů lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Bude pást asyrskou zemi mečem, zemi Nimrodovu v jejích branách. On nás vysvobodí od Asýrie, až přitáhne do naší země, až vstoupí na naše území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Ostatek Jákoba bude uprostřed mnohých národů jako rosa od Hospodina, jako přeháňka na zeleň, která neočekává na člověka a ⌈neskládá naději v⌉ syny člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Ostatek Jákoba bude mezi národy, uprostřed mnohých národů jako lev mezi lesní zvěří, jako mladý lev ⌈ve stádu⌉ ovcí, který když projde, všechno pošlape a rozsápe, a ⌈není, kdo by je vysvobodil.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Tvá ruka ⌈se pozdvihne proti tvým⌉ protivníkům a všichni tví nepřátelé budou vyhlazeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, '⌈I stane se v onen den,⌉ je Hospodinův výrok, že vyhladím tvé koně ze tvého středu a odstraním tvé válečné vozy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Vyhladím města tvé země a zbořím všechny tvé pevnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Vyhladím ⌈od tebe⌉ kouzelníky a nebudeš mít hadače.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Vyhladím tvé tesané modly a posvátné sloupy ze tvého středu a nebudeš se již klanět dílu svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Vyvrátím tvé posvátné kůly ze tvého středu a vyhladím tvá města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'V hněvu a zlobě vykonám pomstu nad národy, které neposlouchaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Slyšte nyní to, co říká Hospodin: Vstaň a veď při před horami, ať návrší slyší tvůj hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Slyšte, hory, Hospodinův spor, vy pevné základy země, protože Hospodin vede spor se svým lidem, bude se soudit s Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Co jsem ti provedl, můj lide? Čím jsem tě unavil? Vypovídej proti mně!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Vždyť jsem tě vyvedl z egyptské země, ⌈vykoupil jsem tě z domu otroctví⌉ a poslal jsem před tebou Mojžíše, Árona a Mirjam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Vzpomeň si, můj lide, co plánoval moábský král Balák a co mu odpověděl Bileám, syn Beórův, ⌈ a co se stalo ⌉ od Šitímu až do Gilgálu, abys poznal Hospodinovy spravedlivé činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'S čím mohu ⌈vyjít vstříc Hospodinu,⌉ sklonit se před ⌈vyvýšeným Bohem?⌉ Což mu mohu vyjít vstříc se zápalnými oběťmi, s ročními telaty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Cožpak Hospodin ⌈najde zalíbení v⌉ tisících beranů a v desetitisících potoků oleje? Což mohu dát svého prvorozeného za své přestoupení, plod svého lůna za hřích své duše?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Oznámil ti, člověče, co je dobré a co od tebe Hospodin žádá: Jenom abys jednal podle práva, miloval milosrdenství a pokorně chodil se svým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Slyš! Hospodin volá k městu -- ⌈a bázeň před tvým jménem znamená obezřetnost⌉ -- Slyšte, ⌈pokolení a shromáždění města.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Což mohu zapomenout ⌈ na ničemně získané poklady⌉ v domě ničemy a ošizenou míru, ⌈která je zlořečená?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Což ⌈ mohu za poctivé prohlásit ničemné váhy⌉ a měšec s falešným závažím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Bohatí toho města jsou plni násilí, jeho obyvatelé mluví lež, jazyk v jejich ústech je záludný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Proto tě ⌈tvrdě zbiji,⌉ budu tě pustošit za tvůj hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Budeš jíst, ale nenasytíš se, tvůj hlad bude uprostřed tebe. Odtáhl ses stranou, ale do bezpečí si nic neodneseš. A co si do bezpečí odneseš, vydám meči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Budeš zasévat, ale nebudeš sklízet; budeš šlapat olivy, ale nepomažeš se olejem; šlapat nové víno, ale nebudeš pít víno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Protože ⌈jsi měl na zřeteli⌉ ustanovení Omrího a ⌈všechny skutky⌉ domu Achabova a protože jste žili podle jeho rad, proto tě učiním předmětem hrůzy a obyvatele toho města předmětem úžasu. Ponesete potupu národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Běda mi, protože ⌈se mi vede jako po sklizni⌉ letního ovoce, jako po paběrkování vinobraní: Ani hrozen k jídlu, ani raný fík, po kterém toužím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Vymizel věrný ze země, přímý ⌈mezi lidmi⌉ není. Všichni ⌈číhají, aby prolévali krev,⌉ ⌈jeden druhého⌉ loví se sítí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, '⌈Na zlo používají své ruce správně:⌉ Kníže žádá o dary, soudce soudí za odplatu, velmož mluví své choutky a oni to tak překrucují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Nejlepší z nich je jako trní, nejpřímější z nich horší než trnitý plot. Nastal den ⌈tvých strážných, přišlo⌉ tvé navštívení. Nyní nastane jejich zmatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Nevěřte bližnímu, nespoléhejte na přítele; před tou, která leží ve tvém klíně, ⌈střež vchod svých úst.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Neboť syn jedná opovržlivě vůči otci, dcera povstává proti matce, snacha proti tchyni; nepřáteli člověka jsou ⌈lidé z jeho vlastní rodiny.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Já však budu vyhlížet k Hospodinu, ⌈naději budu mít v Bohu,⌉ ⌈který mě zachraňuje.⌉ Můj Bůh mě vyslyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Neraduj se nade mnou, má nepřítelkyně. Ačkoliv jsem padl, povstanu, přestože pobývám v temnotě, Hospodin je mým světlem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Protože jsem proti němu zhřešil, ponesu Hospodinův hněv, dokud ⌈se mě nezastane⌉ a ⌈nezjedná mi⌉ právo. Vyvede mě na světlo a budu hledět na jeho spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Uvidí to má nepřítelkyně a přikryje ji hanba, tu, která mi říkala: Kde je Hospodin, tvůj Bůh? Moje oči ji uvidí, teď je k pošlapání jako bláto na ulicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Nastane den pro budování tvých zdí, v onen den se rozšíří tvé hranice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, '⌈ V onen den⌉ k tobě přijdou z Asýrie ⌈až po Egypt,⌉ z Egypta až po řeku Eufrat, ⌈od moře k moři a od hory k hoře.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Země se stane zcela opuštěnou kvůli svým obyvatelům, kvůli ovoci jejich činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Pas svůj lid svou holí, ovce ⌈svého dědictví,⌉ přebývající o samotě v lese uprostřed ovocného sadu. Ať se pasou v Bášanu a Gileádu jako za dávných dnů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Jako za dnů, kdy jsi vyšel z egyptské země, ⌈ukaž nám⌉ obdivuhodné činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Ať to vidí národy a stydí se za všechnu svou sílu, ať si položí ruku na ústa a jejich uši ať ohluchnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Ať lížou prach jako had, jako ⌈ti, co se plazí po zemi;⌉ ať vyjdou s třesením ze svých pevností k Hospodinu, našemu Bohu; ať se strachují a bojí se tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, '⌈Kdo je Bůh jako ty,⌉ ⌈který snímá vinu⌉ a promíjí přestoupení ostatku svého dědictví? Nebude držet neustále svůj hněv, protože má zalíbení v milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Znovu se nad námi slituje, pošlape naše viny a všechny naše hříchy uvrhneš do hlubin moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Prokážeš věrnost Jákobovi, milosrdenství Abrahamovi, jak jsi přísahal našim otcům od dávných časů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Výnos o Ninive. Kniha vidění Nahuma Elkóšského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Hospodin je Bůh žárlivý a mstící se; Hospodin ⌈se mstí a je plný hněvu.⌉ Hospodin se mstí svým protivníkům, drží hněv proti svým nepřátelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Hospodin je pomalý k hněvu, avšak velký v moci; Hospodin jistě nenechá viníka bez trestu. ⌈Jeho cesta je ⌉ ve vichřici a bouři, oblaka jsou prachem jeho nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Okřikne moře a vysuší ho, všechny řeky vysuší. Vadne Bášan a Karmel, i květ Libanonu vadne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Hory se před ním třesou, kopce se rozplývají, zvedá se před ním země, svět i všichni, kdo na něm bydlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Před jeho rozhořčením kdo obstojí, kdo obstojí před jeho planoucím hněvem? Jeho zloba se rozlévá jako oheň a skály se před ním tříští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Hospodin je dobrý, je záštitou v den soužení, zná ty, kteří v něm mají útočiště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Avšak valící se povodní učiní konec ⌈jeho území,⌉ své nepřátele zažene do tmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, '⌈Co chcete vymýšlet proti Hospodinu? On⌉ učiní konec! ⌈Soužení dvakrát nepovstane.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Jako zapletené trní a jako pijani opití svým pitím budou stráveni jako úplně vyschlé strniště.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Z tebe, Ninive, vyšel ten, kdo vymýšlí zlo proti Hospodinu, ⌈ničemný rádce.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Toto praví Hospodin: Ačkoliv ⌈byli plni síly,⌉ tak početní, stejně budou zničeni a zajdou. Jako jsem tě pokořil, již tě nepokořím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Nyní tedy zlomím ⌈jeho jho⌉ ⌈na tobě⌉ a tvá pouta zpřetrhám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Hospodin o tobě vydal příkaz: ⌈Tvému jménu již nebude získáno potomstvo.⌉ Z domu tvých bohů vyhladím tesanou i litou modlu. Nachystám ti hrob, neboť ⌈jsi byl shledán lehkým.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Hle, po horách kráčejí nohy ⌈nositele dobré zprávy,⌉ který zvěstuje pokoj. Slav, Judo, své svátky, splň svoje sliby, protože již nikdy tebou nebude procházet ničemník: byl zcela vyhlazen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Vytáhl proti tobě zhoubce. Střež pevnost, pozorně sleduj cestu, posilni bedra, ⌈seber všechny své síly.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Neboť Hospodin obnovil vznešenost Jákoba jako vznešenost Izraele, ačkoliv je pustošitelé zpustošili a jejich vinné ratolesti zničili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Štít jeho hrdinů je zbarven rudě, bojovníci jsou oděni do šarlatu. Vozba je v ohnivém lesku oceli v den, kdy je připravena. Oštěpy z cypřiše se chvějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Vozy zběsile jedou po ulicích, řítí se po náměstích, vypadají jako pochodně, míhají se jako blesky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Přikáže svým důstojníkům, a ti klopýtají, ⌈jak postupují,⌉ pospíchají k hradbám, kde byl postaven útočný kryt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, '⌈Brány řek⌉ se otevřely, palác se rozplynul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Huccab je odvedena do zajetí a odvlečena. Její otrokyně truchlí jako holubice a bijí se v prsa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Ninive je odedávna jako rybník vody; teď utíkají. Stůjte, stůjte! Ale nikdo se ne obrací.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Zaberte stříbro, zaberte zlato! Není konce pokladů, bohatství všelijakých vzácných předmětů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Spoušť, zpustnutí, zpustošení, srdce ochabuje, kolena se třesou, ⌈úzkost na všech bedrech,⌉ všechny tváře blednou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, '⌈Kde je to lví doupě,⌉ ta pastvina pro mladé lvy, kam chodili lev, lvice i lví mláďata, a nebyl, kdo by je vyplašil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Lev sápal pro svá mláďata, rdousil pro své lvice, své díry naplnil kořistí a svá doupata rozsápanými zvířaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, '⌈Hle, jsem proti tobě,⌉ je výrok Hospodina zástupů, spálím v kouři tvou vozbu a tvoje mladé lvy pozře meč. Vyhladím ze země tvoji kořist a nebude již slyšet hlas tvých poslů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Běda městu ⌈prolévajícímu krev⌉ -- je ⌈plné podvodu,⌉ lupem naplněné, kořistění nepřestává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Práskání biče a hřmot kola, kůň cválá a vůz poskakuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Jezdec se řítí, ⌈meč se třpytí,⌉ ⌈kopí se blyští;⌉ množství pobitých, hromady mrtvol, není konce mrtvých těl -- klopýtají přes jejich těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Pro mnohá smilstva prostitutky, velmi půvabné kouzelnice, která podmaňovala národy svými smilstvy a čeledě svými kouzly --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, '⌈hle, jsem proti tobě,⌉ je výrok Hospodina zástupů. Zvednu tvé sukně přes tvou tvář a ukážu národům tvou nahotu, královstvím tvoji hanbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Uvrhnu na tebe ohavnosti, budu s tebou jednat opovržlivě a ⌈proměním tě v⌉ podívanou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'I stane se, že každý, kdo tě uvidí, od tebe uprchne a řekne: Ninive je zničeno, kdo ⌈nad ním bude naříkat?⌉ Odkud ti mám vyhledat utěšitele?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Což jsi lepší nežli Nó–amón, ležící na Nilu, obklopeno vodou, jehož valem bylo moře, z moře byla jeho hradba?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Kúšijci a Egypťané byli jeho silou, bez konce Pútejců a Lúbíjců bylo tobě na pomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Také on musel do vyhnanství, šel do zajetí. I jeho děti byly rozdrceny na ⌈každém nároží.⌉ O jeho vážené muže vrhali los, všichni jeho velmoži byli spoutáni řetězy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'I ty, Ninive, budeš opilé, budeš skryto, i ty budeš hledat záštitu před nepřítelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Všechny tvé pevnosti budou jako fíkovníky s prvotinami; jak se jimi zatřese, padnou do úst toho, kdo chce jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Hle, tvůj lid ve tvém středu je jako ženy, brány tvé země se dokořán otevřely pro tvé nepřátele, oheň strávil tvé závory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Načerpej si vodu pro dobu obležení! Opevni své pevnosti! Vstup do bláta a šlapej hlínu, chop se formy na cihly!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Tam tě stráví oheň, vyhladí tě meč, pozře tě jako kobylky. Rozmnož se jako kobylky jelek, rozmnož se jako kobylky arbe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Rozmnožilo jsi své obchodníky víc než je hvězd na nebi. Kobylky jelek se svléknou a odletí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Tví dvořané jsou jako kobylky arbe, tvoji úředníci jako mraky kobylek, které táboří v chladný den na zdech. Když vyjde slunce, uletí a nikdo neví, kde jsou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Tvoji pastýři dřímou, asyrský králi, tví vznešení předáci v klidu leží. Tvůj lid je rozptýlen po horách, není, kdo by je shromáždil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Na tvou zlomeninu není léku, nevyléčitelná je tvá rána. Všichni, kdo slyší zprávu o tobě, tleskají nad tebou rukama. Vždyť na koho nepřišlo tvé ustavičné zlo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Prorocký výnos, který viděl prorok Abakuk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, '⌈Jak dlouho⌉ mám, Hospodine, křičet o pomoc, a ty neslyšíš, volat k tobě: Násilí! a ty nepomůžeš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Proč mi ukazuješ zlo a hledíš na trápení? Zkáza a násilí je přede mnou, trvá spor a pozvedá se svár.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Proto je zákon ochromen a právo nikdy nepronikne, protože ničema obkličuje spravedlivého, proto pronikne právo pokřivené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Dívejte se mezi národy, pohleďte, žasněte a buďte ohromeni, protože ve vašich dnech vykonám takový skutek, že neuvěříte, i když vám to bude vyprávěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Neboť hle, dám povstat Chaldejcům, národu krutému a dravému, který půjde do širé země, aby obsadil příbytky, jež nejsou jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Vzbuzuje strach, je obávaný; ⌈od něj samého pochází jeho právo a vznešenost.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Jeho koně jsou rychlejší než leopardi a hbitější nežli vlci ⌈ k večeru.⌉ Jeho koně poskakují, jeho jezdci se přiženou zdaleka, přiletí jako orel nedočkavý se nažrat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Všichni se ⌈ženou za násilím,⌉ odhodlaně ⌈ postupují kupředu,⌉ sbírají zajatce jako písek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Králům se posmívají, mocnáři jsou jim k smíchu, všem pevnostem se vysmívají, ⌈navrší náspy⌉ a dobudou je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Potom přejdou jako vítr a pominou. Ten, jenž má svou sílu za boha, však ponese vinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Ty jsi přece odedávna, Hospodine, můj Bože, můj Svatý, ⌈ ty neumíráš.⌉ Hospodine, ustanovil jsi ho k soudu, Skálo, určil jsi ho ke kárání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, '⌈ Tvoje oči jsou příliš čisté, než aby se dívaly na zlo,⌉ nemohou hledět na trápení. Proč tedy hledíš na podvodníky a mlčíš, zatímco ničema pohlcuje spravedlivějšího, nežli je on?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Učinil jsi lidi jako mořské ryby, jako plazy, kteří nad sebou nemají vládce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Všechny je může vytáhnout na udici, odvléct je ve své síti, sebrat je do svého nevodu; proto se raduje a jásá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Proto obětuje své síti, pálí kadidlo svému nevodu, neboť díky nim ⌈ je jeho podíl úrodný⌉ a jeho potrava tučná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Cožpak smí takto vyprazdňovat svou síť, stále bez soucitu pobíjet národy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Budu stát na své stráži, postavím se na opevnění a budu pozorně sledovat, abych viděl, jak ke mně promluví, co odpoví na mou stížnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Hospodin mi odpověděl: Zapiš vidění, ⌈zřetelně ho napiš⌉ na tabulky, aby ⌈to čtenář⌉ mohl ⌈přeběhnout zrakem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Vždyť vidění je svědkem pro určený čas, ⌈svědectvím o konci,⌉ a neselže. Ačkoliv otálí, vyčkávej na něj, neboť se jistě naplní a neopozdí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Hle, ten, jehož touha není správná, je umdlený, ale spravedlivý bude žít díky své věrnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, '⌈Ano, víno podvede pyšného muže,⌉ nemá stání; otvírá svůj chřtán jako podsvětí, je nenasytný jako smrt; posbíral k sobě všechny národy, shromáždil k sobě všechny lidi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Což o něm tito všichni nepronesou pořekadla, podobenství a hádanky? Bude se říkat: Běda tomu, kdo množí, co není jeho -- jak dlouho to potrvá? -- tomu, kdo se obohacuje vydíráním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Což nepovstanou v okamžiku tvoji věřitelé, ne proberou se ti, kdo tě děsí, a ne staneš se jejich kořistí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Protože jsi vyplenil mnohé národy, všechny zbylé národy vyplení tebe -- za prolitou lidskou krev a násilí spáchané na zemích, městech a všech jejich obyvatelích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Běda tomu, kdo hrabe pro svůj dům nekalý zisk, aby si vysoko postavil své hnízdo, a tak byl vysvobozen z moci zla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Připravil jsi hanbu pro svůj dům, zničil jsi mnohé národy, hřešil jsi ⌈ proti své duši.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Vždyť kámen ze zdi bude křičet a odpoví mu trám z krovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Běda tomu, kdo staví město proléváním krve a upevňuje ho zvráceností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Hle, což to není od Hospodina zástupů: Národy se namáhají pro oheň a lidé se zbytečně unavují?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Neboť země bude naplněna poznáním Hospodinovy slávy, tak jako voda pokrývá moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Běda tomu, kdo dává svým bližním pít ⌈ z číše⌉ svého hněvu a opíjí je, aby se díval na jejich nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Nasytíš se hanbou místo slávy. Pij i ty a odhal se! Kalich v Hospodinově pravici se obrátí proti tobě, ostuda přijde na tvou slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Neboť tě přikryje násilí spáchané na Libanonu a zkáza způsobená zvěří tě roztřese strachem za prolitou lidskou krev a násilí spáchané na zemích, městech a všech jejich obyvatelích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Co prospěje tesaná modla, když ji vytesal její tvůrce, či litá modla, učitel lži? Vždyť tvůrce spoléhá na svůj výtvor, když dělá němé nicotnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Běda tomu, kdo říká dřevu: Probuď se! a němému kameni: Vzbuď se! Ten tě má učit? Hle, je pokryt zlatem a stříbrem, ale dech v něm vůbec není!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Ale Hospodin je ve svém svatém chrámu. Zmlkni před ním celá země!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Modlitba proroka Abakuka na šigjonót.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Hospodine, slyšel jsem zprávu o tobě; bojím se, Hospodine, o tvé dílo. Obnov jej v těchto letech, dej ho poznat v těchto letech; v nepokoji pamatuj na slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Bůh přichází z Témanu, Svatý z hory Páranu. Sela. Jeho nádhera přikryla nebesa, jeho chvála naplnila zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Jeho zář je jako svítání, ⌈paprsky šlehají z jeho ruky,⌉ tam ⌈se skrývá jeho síla.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Před ním jde mor, v jeho stopách táhne nákaza.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Zůstane stát a zatřese zemí, pohlédne a ⌈národy se chvějí;⌉ odvěká pohoří se tříští, dávná návrší klesají, ⌈jde dávnou cestou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, '⌈Vidím, že stany Kúšanců jsou vystaveny zkáze,⌉ stanové plachty v midjánské zemi se třesou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, '⌈Cožpak proti řekám, Hospodine,⌉ zdali proti řekám plane tvůj hněv, zdali proti moři tvé rozhořčení, že jedeš na svých koních, na svých vítězných vozech?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Holý a připravený je tvůj luk. ⌈Vysíláš své šípy.⌉ Sela. Řekami rozděluješ zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Hory tě zahlédnou a svíjejí se, příval vody se valí, hlubina vydala svůj hlas, vysoko zvedá své ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Slunce i měsíc ⌈vejdou do svého obydlí,⌉ odejdou v jasu tvých šípů, v záři tvého blýskavého kopí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'S rozhořčením projdeš zemi, v hněvu pošlapeš národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Vyjdeš k záchraně svého lidu, k záchraně svého pomazaného; srazíš hlavu z ničemova domu, obnažíš ho od ⌈paty až k šíji.⌉ Sela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Jeho vlastními šípy probodneš hlavu jeho knížat, kteří se ženou jako bouře, aby nás rozptýlili, jásají, jako by chtěli pohltit chudého v skrýši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Svými koňmi šlapeš po moři, množství bouřících vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Zaslechl jsem to a mé nitro se chvělo, ⌈když jsem to uslyšel,⌉ mé rty se třásly, hniloba vešla do mých kostí. Třesu se, ⌈tam kde stojím,⌉ ⌈protože musím čekat do dne soužení, kdy přitáhne národ, jenž na nás vtrhne.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'I kdyby fíkovník nerozkvetl a na révě nebyla úroda, selhal výnos olivy a pole nevydala potravu, z ohrady zmizel brav a ve stájích nebyl skot,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'já se budu radovat v Hospodinu, budu jásat v Bohu, který ⌈mě zachraňuje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, '⌈Panovník Hospodin⌉ je ⌈má síla,⌉ činí mé nohy podobné laním, dává mi kráčet po návrších. Pro vedoucího chval na strunné nástroje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Hospodinovo slovo, které se stalo k Sofonjášovi, synu Kúšího, syna Gedaljáše, syna Amarjáše, syna Chizkijášova, ve dnech judského krále Jóšijáše, syna Amónova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, '⌈Zcela sklidím⌉ všechno z povrchu země, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Sklidím ⌈člověka i zvěř,⌉ sklidím nebeské ptactvo i mořské ryby, ⌈pohoršení spolu s ničemy;⌉ vyhladím člověka z povrchu země, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Vztáhnu svou ruku proti Judovi a proti všem obyvatelům Jeruzaléma. Vyhladím z tohoto místa ⌈Baalův ostatek⌉ i jméno žreců spolu s kněžími,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'i ty, kdo se klanějí na střechách nebeskému zástupu, ty, kdo se klanějí a přísahají při Hospodinu, a také přísahají při Milkómovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'i ty, kdo odstupují od Hospodina, kdo Hospodina nehledají a nedotazují se ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Zmlkni před Panovníkem Hospodinem, protože ⌈Hospodinův den je blízko,⌉ protože Hospodin připravil obětní hod, posvětil ty, které pozval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'I stane se v den Hospodinova obětního hodu, že navštívím s trestem knížata a královské syny i všechny, kdo oblékají cizí oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'V onen den navštívím s trestem všechny, kdo přeskakují práh, ty, kdo naplňují dům svého pána násilím a podvodem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'V onen den, je Hospodinův výrok, bude znít hlasité volání od Rybné brány, nářek z Mišne a velké drcení z kopců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Naříkejte, obyvatelé Machteše, neboť zahynul všechen kramářský lid, všichni, ⌈kdo⌉ váží stříbro, byli vyhlazeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'I stane se v onen čas, že prohledám Jeruzalém s lampami a navštívím s trestem muže usazené na svém kalu, kteří si v srdci říkají: Hospodin neudělá nic dobrého ani zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Jejich majetek se stane kořistí a jejich domy pustinou. Postaví domy, ale nebudou v nich bydlet, vysadí vinice, ale víno z nich pít nebudou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Blízko je Hospodinův velký den, blízko a velmi pospíchá. Slyš! Hospodinův ⌈den je trpký, hrdina ⌈v něm⌉ bude křičet.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Onen den bude dnem hněvu, dnem soužení a sklíčenosti, dnem zkázy a zpustošení, dnem temnoty a soumraku, dnem mračna a husté temnoty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'dnem troubení na beraní roh a válečného křiku proti opevněným městům a proti vysokým rohovým věžím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Způsobím lidem soužení a budou chodit jako slepí, protože hřešili proti Hospodinu. Jejich krev bude vylita jako prach a jejich vnitřnosti jako výkaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ani jejich ⌈stříbro ani jejich zlato je nebude moci vysvobodit v den Hospodinova hněvu.⌉ Ohněm jeho žárlivosti bude strávena celá země, ano, náhlý konec učiní se všemi obyvateli země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Shromážděte se jako sláma, shromážděte se, bezostyšný národe,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'dříve nežli se zrodí lhůta a jako plevy pomine den, dříve nežli na vás přijde Hospodinův planoucí hněv, dříve nežli na vás přijde den Hospodinova hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Hledejte Hospodina, všichni pokorní země, kteří vykonáváte jeho nařízení, hledejte spravedlnost, hledejte pokoru; snad se ukryjete v den Hospodinova hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, '⌈Gaza bude opuštěná,⌉ Aškalón se stane pustinou, Ašdód za poledne vyženou a ⌈Ekrón bude vykořeněn.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Běda obyvatelům přímořské oblasti, národu Keretejců. Hospodinovo slovo je proti vám, Kenaane, pelištejská země, vyhubím tě, budeš bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Přímořská oblast se stane ⌈pastvinami pasoucích se jehňat⌉ s ohradami pro ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Oblast bude patřit ostatku domu Judova, na nich budou pást, v domech Aškalónu budou večer uléhat, neboť Hospodin, jejich Bůh, je navštíví a změní jejich úděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Slyšel jsem potupu Moába, hanobení synů Amónových, kterým tupili můj lid a vyvyšovali se nad jeho hranici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Proto, jakože jsem živ, je výrok Hospodina zástupů, Boha Izraele, Moáb bude jako Sodoma a synové Amónovi jako Gomora: zaplevelená zem, solná jáma a pustina až navěky. Ostatek mého lidu je oloupí, zbytek mého národa je zdědí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'To jim patří za jejich pýchu, protože tupili lid Hospodina zástupů a vyvyšovali se nad něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, '⌈Hospodin v nich bude vzbuzovat hrůzu,⌉ neboť vyhubí všechny bohy země; a budou se mu klanět, každý ze svého místa, všechny ostrovy národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Také vy, Kúšijci, budete probodeni mým mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Vztáhne svou ruku proti severu, zahubí Asýrii, promění Ninive v pustinu, vyprahlou jako poušť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Budou v něm uléhat stáda, zvěř všeho druhu, pelikán i sýček budou nocovat na ⌈jeho hlavicích.⌉ ⌈Slyš, zpívá⌉ do okna, na prahu zničení, že cedrové obložení je osekáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'To je to rozjařené město bydlící v bezpečí, které si říkalo: Já, a nikdo více. Jak se stalo hroznou pustinou, ležením pro zvěř. Každý, kdo jím bude procházet, se podiví, bude potřásat rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Běda vzpurnému a poskvrněnému, tomu násilnickému městu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Neuposlechlo, nepřijalo naučení, na Hospodina nespoléhalo, k svému Bohu se nepřiblížilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Jeho knížata uprostřed něj jsou řvoucí lvi, jeho soudcové jak vlci k večeru, do rána ne nechají nic ne ohryzaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Jeho proroci jsou namyšlenci a podvodníci, jeho kněží znesvěcují svaté věci, znásilňují zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Spravedlivý Hospodin je uprostřed něj, nečiní zvrácenost. ⌈Ráno co ráno⌉ dává své právo jako světlo, nepochybí, ale bídák nezná hanbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Vyhladil jsem národy, zpustošené jsou jejich rohové věže, zničil jsem jejich ulice, nikdo jimi neprochází, pustá jsou jejich města, bez lidí, bez obyvatel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Říkal jsem si: Jistě se mě budeš bát a přijmeš naučení. Jeho příbytek by pak nebyl zničen ničím, čím jsem ho chtěl navštívit. Jenže oni si přivstali a jednali zvráceně ve všech svých činech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Proto čekejte na mě, je Hospodinův výrok, na den, kdy povstanu ⌈jako svědek,⌉ neboť mé rozhodnutí je sebrat národy, shromáždit království, vylít na ně své rozhořčení, všechen svůj planoucí hněv, neboť celá země bude strávena ohněm mé žárlivosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Tehdy změním národům rty v čisté, všichni budou vzývat Hospodinovo jméno a budou mu svorně sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Zpoza kúšských řek mi moji ctitelé, dcery Pusaj, přinesou přídavnou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'V onen den se nebudeš stydět za žádné své činy, kterými ses proti mně bouřil, protože tehdy odstraním ze tvého středu tvé pyšně rozjařené a nebudeš se již déle povyšovat na mé svaté hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Ponechám ve tvém středu lid ⌈nuzný a chudý⌉ a budou mít útočiště v Hospodinově jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Ostatek Izraele neučiní zvrácenost, nepromluví lživě, v jejich ústech se nenajde podvodný jazyk. Budou se pást a uléhat, a nikdo je ne vyděsí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Výskej, dcero sijónská, hlahol, Izraeli, raduj se a jásej celým srdcem, dcero jeruzalémská!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Hospodin odstranil rozsudek nad tebou, odvrátil tvého nepřítele. Král Izraele, Hospodin, je ve tvém středu, neboj se již zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'V onen den řeknou Jeruzalému: Neboj se, Sijóne, tvé ruce ať neochabnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Hospodin, tvůj Bůh, je ve tvém středu, hrdina, který zachraňuje. Rozjásá se nad tebou radostně, obnoví tě svou láskou, zaplesá nad tebou s výskáním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, '⌈Sklíčené ze svátků vzal jsem od tebe, byli břemenem, potupou na tobě.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Hle, v onen čas budu jednat se všemi, kteří tě pokořovali. Zachráním kulhavou a zapuzenou shromáždím, a proměním je ve chválu a věhlas po celé zemi, ⌈ kde zakoušeli hanbu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'V onen čas vás přivedu, v onen čas vás shromáždím, ano, učiním vás věhlasem a chválou mezi všemi národy země, když před vašima očima změním váš úděl, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'V druhém roce vlády krále Dareia, v šestém měsíci, prvního dne toho měsíce, stalo se Hospodinovo slovo prostřednictvím proroka Agea k judskému místodržiteli Zerubábelovi, synu Šealtíelovu, a k veleknězi Jóšuovi, synu Jósadakovu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Toto praví Hospodin zástupů: Tento lid říká: Nepřišel ještě čas, čas, aby byl postaven Hospodinův dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'I stalo se Hospodinovo slovo prostřednictvím proroka Agea:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Pro vás je již čas, abyste bydleli ve svých obložených domech, zatímco tento dům je zcela zpustošený?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nyní toto praví Hospodin zástupů: ⌈Přemýšlejte o svých cestách!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Zaseli jste mnoho, sklízíte málo; jíte, ale nejste nasyceni, pijete, ale opít se ne můžete, oblékáte se, ale nezahřejete se, a ten, kdo se nechává najmout za mzdu, ⌈dává ji do⌉ děravého váčku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Toto praví Hospodin zástupů: ⌈Přemýšlejte o svých cestách!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Vystupte do hor, přivezte dřevo a stavte dům; oblíbím si ho a budu oslaven, praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, '⌈Vyhlíželi jste mnoho,⌉ a hle, je málo, a když jste to přinesli domů, odfoukl jsem to. Proč? je výrok Hospodina zástupů. Protože můj dům je zcela zpustošený, a vy si běháte každý za svým domem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Proto nebesa nad vámi zadržela rosu a země zadržela svou úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Přivolal jsem sucho na zemi a na hory, na obilí a mladé víno, na olej a na všechno, co země přináší, na lidi i zvířata, na všechen výtěžek rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Zerubábel, syn Šealtíelův, a velekněz Jóšua, syn Jósadakův, i celý ostatek lidu uposlechli Hospodina, svého Boha, a slova proroka Agea, protože ho poslal Hospodin, jejich Bůh; a lid se bál Hospodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'A Hospodinův posel Ageus řekl lidu jako Hospodinovo poselství: ⌈Já jsem s vámi,⌉ je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'A Hospodin vzbudil ducha judského místodržitele Zerubábela, syna Šealtíelova, a ducha velekněze Jóšuy, syna Jósadakova, i ducha celého ostatku lidu. Přišli a konali práci v domě Hospodina zástupů, svého Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'dvacátého čtvrtého dne, šestého měsíce, ve druhém roce vlády krále Dareia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Sedmého měsíce, dvacátého prvního dne se stalo Hospodinovo slovo prostřednictvím proroka Agea:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Řekni judskému místodržiteli Zerubábelovi, synu Šealtíelovu, a veleknězi Jóšuovi, synu Jósadakovu, i ostatku lidu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kdo ⌈z vás,⌉ kteří jste zůstali, viděl tento dům v jeho první slávě? A jaký jej vidíte nyní? Není ve vašich očích jen pouhé nic?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Nuže, posilni se, Zerubábeli, je Hospodinův výrok, posilni se, veleknězi Jóšuo, synu Jósadakův, posilni se, všechen lide země, je Hospodinův výrok, a jednejte, neboť já jsem s vámi, je výrok Hospodina zástupů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'kvůli úmluvě, kterou jsem uzavřel s vámi, když jste vycházeli z Egypta. Můj duch stojí uprostřed vás, nebojte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Neboť toto praví Hospodin zástupů: ⌈Ještě jednou zakrátko⌉ zatřesu nebem i zemí, mořem i souší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Zatřesu všemi národy, ⌈přijde to, po čem touží⌉ všechny národy, a naplním tento dům slávou, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Mně patří stříbro, mně patří zlato, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Větší bude budoucí sláva tohoto domu nežli první, praví Hospodin zástupů; na tomto místě ⌈způsobím pokoj,⌉ je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Dvacátého čtvrtého dne devátého měsíce, ve druhém roce vlády Dareia stalo se Hospodinovo slovo k proroku Ageovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Toto praví Hospodin zástupů: ⌈Zeptej se kněží na zákon⌉ slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Jestliže někdo vezme posvátné maso do okraje svého roucha a tím okrajem se dotkne chleba, vařeného jídla, vína, oleje či jakékoliv potravy, bude to svaté? Kněží odpověděli: Ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Ageus se dále zeptal: Jestliže se ⌈někdo nečistý⌉ dotkne čehokoliv z toho, bude to nečisté? Kněží odpověděli: Bude to nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Nato Ageus odpověděl: Takový je tento lid a takový je tento národ přede mnou, je Hospodinův výrok; takové jsou všechny skutky jejich rukou. Co tam obětují, je nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Nuže přemýšlejte, ⌈ jak tomu bylo před tímto dnem,⌉ dříve nežli byl položen kámen na kámen v Hospodinově chrámu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Tehdy, když někdo přišel k hromadě obilí o dvaceti mírách, vydala jen deset, když přišel k lisu, aby nabral padesát měr, vydal jen dvacet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Bil jsem vás obilnou rzí, snětí a krupobitím všechno dílo vašich rukou, ale ⌈ne obrátili jste se i⌉ ke mně, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Přemýšlejte, jak tomu bylo ⌈před tímto dnem,⌉ před dvacátým čtvrtým dnem devátého měsíce, před dnem, kdy byly položeny základy Hospodinova chrámu. Přemýšlejte o tom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Což je ještě zrno v obilnici? A víno, fíkovník, granátovník ani olivovník nepřinesly plody. Od tohoto dne budu žehnat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'I stalo se Hospodinovo slovo podruhé k Ageovi dvacátého čtvrtého dne toho měsíce:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Řekni judskému místodržiteli Zerubábelovi: Zatřesu nebem i zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Převrátím trůny království, vyhladím sílu království národů, převrátím válečné vozy i jejich jezdce, klesnou koně i jejich jezdci, ⌈jeden mečem druhého.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'V onen den, je výrok Hospodina zástupů, tě vezmu, můj otroku Zerubábeli, synu Šealtíelův -- je Hospodinův výrok -- a učiním tě pečetním prstenem, neboť tebe jsem vyvolil, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'V osmém měsíci druhého roku vlády Dareia se stalo Hospodinovo slovo k proroku Zacharjášovi, synu Berekjáše, syna Idova:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Hospodin se velice rozhněval na vaše otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Řekni jim: ⌈Toto praví Hospodin⌉ zástupů: Navraťte se ke mně, je výrok Hospodina zástupů, a vrátím se k vám, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Nebuďte jako vaši otcové! Když je dřívější proroci volali slovy: Toto praví Hospodin zástupů: Odvraťte se od svých zlých cest a od svých zlých činů, neposlouchali a nevěnovali mi pozornost, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Kde jsou vaši otcové, a proroci, cožpak budou žít navěky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Avšak má slova a má ustanovení, která jsem přikázal svým otrokům prorokům, vaše otce dostihla. Navrátili se a řekli: Jak měl Hospodin zástupů v úmyslu s námi naložit podle našich cest a našich činů, tak s námi naložil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Dvacátého čtvrtého dne jedenáctého měsíce, to je v měsíci šebatu, ve druhém roce vlády Dareia se stalo Hospodinovo slovo k proroku Zacharjášovi, synu Berekjáše, syna Idova:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Viděl jsem v noci, hle, nějaký jezdec na rudém koni, stojí mezi myrtovím v hlubině a za ním koně rudí, plaví a bílí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Zeptal jsem se: Co mají tito znamenat, můj pane? Anděl, který se mnou mluvil, mi odpověděl: Ukážu ti, co mají tito znamenat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Ten muž, který stál mezi myrtovím, promluvil a řekl: To jsou ti, které Hospodin poslal, aby procházeli zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Ti odpověděli Hospodinovu andělovi, který stál mezi myrtovím, a řekli: Prošli jsme zemí a hle, celá země si poklidně bydlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Hospodinův anděl promluvil a řekl: Hospodine zástupů, jak dlouho nebudeš mít slitování s Jeruzalémem a s judskými městy, na nichž je tvé rozhořčení po sedmdesát let?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Hospodin andělovi, který se mnou mluvil, odpověděl slova dobrá, slova útěšná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Anděl, který se mnou mluvil, mi řekl: Volej: Toto praví Hospodin zástupů: Horlím pro Jeruzalém a pro Sijón velkou horlivostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Ale převelice se hněvám na sebejisté národy. Když jsem se trochu rozhněval, oni napomáhali ke zlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Proto takto praví Hospodin: Navrátím se do Jeruzaléma se slitováním, zbuduji v něm svůj dům, je výrok Hospodina zástupů, a nad Jeruzalémem bude natažena měřící šňůra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Znovu volej: Toto praví Hospodin zástupů: Znovu budou má města přetékat dobrem, Hospodin znovu potěší Sijón, znovu vyvolí Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Pozvedl jsem oči a vtom jsem uviděl čtyři rohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Zeptal jsem se anděla, který se mnou mluvil: Co mají tyto věci znamenat? Odpověděl mi: To jsou rohy, které rozptýlily Judu, Izrael a Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Pak mi Hospodin ukázal čtyři kováře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Zeptal jsem se: Co jdou dělat? Odpověděl: Toto jsou rohy, které rozptýlily Judu, takže nikdo nepozvedl hlavu. Ale tito je přišli vyděsit, aby urazili rohy národů, které pozvedly roh proti judské zemi, aby ji rozptýlily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Pozvedl jsem oči a vtom jsem uviděl muže, který měl v ruce měřicí provaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Zeptal jsem se: Kam jdeš? Odpověděl mi: Změřit Jeruzalém, abych viděl, ⌈jak má být široký a dlouhý.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Vtom anděl, který se mnou mluvil, vyšel a druhý anděl mu vyšel naproti');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'a řekl mu: Běž a pověz tomu mládenci: Jeruzalém bude obydlen jako ⌈město bez hradeb⌉ pro množství lidí a dobytka v jeho středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'A já, je Hospodinův výrok, budu ohnivou hradbou okolo něj a slávou v jeho středu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Běda, běda, utečte ze severní země, je Hospodinův výrok, neboť jsem vás rozehnal do čtyř nebeských větrů, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Běda! Zachraň se, Sijóne, bydlící u dcery babylonské.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Neboť toto praví Hospodin zástupů -- kvůli své slávě mě poslal k národům, které vás plenily: Kdo se dotýká vás, dotýká se zřítelnice mého oka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Hle, zamávám proti nim rukou a stanou se kořistí svých otroků. A poznáte, že mě poslal Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 14, 'Výskej a raduj se, dcero sijónská, neboť hle, přijdu a budu přebývat ve tvém středu, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 15, 'V onen den národy mnohé se připojí k Hospodinu, budou mým lidem, budu přebývat ve tvém středu a poznáš, že mě k tobě poslal Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 16, 'Hospodin dostane do dědictví Judu jako svůj podíl ve svaté zemi a znovu vyvolí Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 17, 'Zmlkni před Hospodinem, veškeré tělo, neboť se dal do pohybu ze svého svatého příbytku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Potom mi ukázal velekněze Jóšuu stojícího před Hospodinovým andělem a Satan stál po jeho pravici, aby ho obžaloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Hospodin řekl Satanovi: Ať tě napomene Hospodin, Satane! Ať tě napomene Hospodin, který vyvolil Jeruzalém. Což to není poleno zachráněné z ohně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Jóšua byl oblečen do špinavých šatů, když stál před andělem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Ten promluvil a řekl těm, kteří stáli před ním: Sundejte z něj ty špinavé šaty. A jemu řekl: Pohleď, odňal jsem od tebe tvou vinu a obléknou tě do slavnostních šatů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'A řekl: Ať mu vloží na hlavu čistý turban. Vložili mu na hlavu čistý turban a oblékli mu šaty, zatímco anděl Hospodinův stál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Potom Hospodinův anděl napomínal Jóšuu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Toto praví Hospodin zástupů: Jestliže budeš chodit po mých cestách a zachovávat můj řád, také ty budeš obhajovat můj dům a střežit má nádvoří a dovolím ti přicházet mezi ty, kteří zde stojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Slyš, veleknězi Jóšuo, ty i tvoji druzi, kteří sedí před tebou, neboť tito muži jsou znamením, že přivedu svého otroka, Výhonek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Neboť pohleďte na kámen, který jsem dal před Jóšuu -- na jednom kameni sedm očí. Hle, vyryji na něm nápis, je výrok Hospodina zástupů, a vzdálím vinu této země v jediném dni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'V onen den, je výrok Hospodina zástupů, budete zvát jeden druhého pod révu a pod fíkovník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Anděl, který se mnou mluvil, mě znovu vzbudil, jako se budí muž ze spánku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Zeptal se mě: Co vidíš? Odpověděl jsem: Vidím svícen celý ze zlata a na jeho vrchu nádrž na olej; na něm sedm lamp a sedm nálevek k lampám, které jsou na jeho vrchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'U něho jsou dvě olivy, jedna napravo od nádrže a druhá nalevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Promluvil jsem a zeptal jsem se anděla, který se mnou mluvil: Co mají tyto věci znamenat, můj pane?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Anděl, který se mnou mluvil, mi řekl: Nevíš, co mají znamenat? Odpověděl jsem: Ne vím, můj pane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Promluvil a řekl mi: Toto je Hospodinovo slovo k Zerubábelovi: Ne silou ani mocí, ale mým Duchem, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Čím jsi, veliká horo? Před Zerubábelem se staneš rovinou. Pak vynese nahoru ⌈vrcholový klenák⌉ za radostného volání ⌈o něm: Jak půvabný, jak půvabný!⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Zerubábelovy ruce položily základy tohoto domu a jeho ruce ho dokončí. A poznáš, že mě k vám poslal Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Vždyť kdo pohrdl dnem malých věcí, bude se radovat, až uvidí olovnici v Zerubábelově ruce. Těch sedm jsou Hospodinovy oči obzírající celou zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Promluvil jsem a zeptal jsem se ho: Co znamenají ty dvě olivy napravo a nalevo od svícnu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Promluvil jsem podruhé a zeptal jsem se ho: Co znamenají ty dvě olivové větve, ⌈z nichž se vylévá zlato prostřednictvím dvou zlatých trubic?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Zeptal se mě: Nevíš, co znamenají? Odpověděl jsem: Ne vím, můj pane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Řekl: To jsou dva pomazaní, kteří stojí před ⌈Pánem celé země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Znovu jsem pozvedl oči a vtom jsem uviděl letící svitek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Zeptal se mě: Co vidíš? Odpověděl jsem: Vidím letící svitek, ⌈dvacet loket dlouhý⌉ a ⌈deset loket široký.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Řekl mi: To je prokletí, které vychází na celou zemi. Neboť každý, kdo kradl, jak je psáno ⌈na jedné straně svitku,⌉ zůstal bez trestu a každý, kdo lživě přísahal, jak je psáno na druhé straně svitku, zůstal bez trestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Vyvedl jsem ho však, je výrok Hospodina zástupů, a vstoupí do domu zloděje a do domu toho, kdo lživě přísahá v mém jménu. Zůstane v jeho domě a zničí ho i s krovem a s kamením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Anděl, který se mnou mluvil, vyšel a řekl mi: Pozvedni oči a pohleď, co to vychází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Zeptal jsem se: Co je to? Odpověděl: To je vycházející éfa. A řekl: To je ⌈jejich oko⌉ po celé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Vtom se zdvihlo olověné víko a tam uvnitř éfy seděla nějaká žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Řekl: To je ničemnost, a hodil ji dovnitř éfy a na otvor hodil olověné závaží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Pak jsem pozvedl oči a vtom jsem uviděl vycházet dvě ženy. Vítr vál do jejich křídel, měly totiž křídla jako čáp, a nesly éfu mezi zemí a nebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Zeptal jsem se anděla, který se mnou mluvil: Kam odnášejí tu éfu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Odpověděl mi: Aby jí postavily dům v šineárské zemi. Až bude připraven, spočine tam na podstavci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Znovu jsem pozvedl oči a vtom jsem uviděl čtyři vozy, jak vyjíždějí mezi dvěma horami. Ty hory byly bronzové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'V prvním voze byli zapřaženi koně rudí, ve druhém voze koně černí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 've třetím voze koně bílí a ve čtvrtém voze koně strakatí, silní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Promluvil jsem a zeptal jsem se anděla, který se mnou mluvil: Co mají tito znamenat, můj pane?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Anděl promluvil a řekl mi: To jsou čtyři nebeské větry, které vycházejí poté, co stály před ⌈Pánem celé země.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Černí koně vyjíždějí do země severní, bílí vyjeli ⌈na západ,⌉ strakatí vyjeli do země jižní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Silní vyjeli a chtěli jít a procházet zemí. A on řekl: Jděte a procházejte zemí. A procházeli zemí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Zavolal na mě a promluvil ke mně: Pohleď, ti, kteří vyjíždějí do severní země, ⌈utišili můj hněv⌉ v severní zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'I stalo se ke mně Hospodinovo slovo:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Vezmi od vyhnanců Cheldaje, Tóbijáše a Jedajáše, v tentýž den jdi a vejdi do domu Jóšijáše, syna Sefanjášova, kam přišli z Babylona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'vezmi stříbro a zlato, udělej korunu a vlož ji na hlavu velekněze Jóšuy, syna Jósadakova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Řekni mu: Toto praví Hospodin zástupů: Hle, muž jménem Výhonek, vzejde ze svého místa a postaví Hospodinův chrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'On postaví Hospodinův chrám a ponese majestát. Bude sedět a vládnout na svém trůnu a bude knězem na svém trůnu; a mezi oběma bude ⌈rada pokoje.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Koruna bude Chelemovi, Tóbijášovi, Jedajášovi a Chénovi, synu Sefanjášovu, ⌈na památku⌉ v Hospodinově chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Ti, kdo jsou zdaleka, přijdou a budou stavět Hospodinův chrám. A poznáte, že mě k vám poslal Hospodin zástupů. To se stane, jestliže opravdu uposlechnete Hospodina, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Ve čtvrtém roce vlády krále Dareia se stalo Hospodinovo slovo k Zacharjášovi čtvrtého dne devátého měsíce, tedy kislevu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Tehdy Bét–el poslal Saresera a Regem–meleka s jeho muži udobřit si Hospodinovu tvář');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'a zeptat se kněží, kteří patřili domu Hospodina zástupů, a proroků: Mám plakat v pátém měsíci a postit se, jako jsem to dělal po mnoho let?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'I stalo se ke mně slovo Hospodina zástupů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Řekni všemu lidu země a kněžím: Když jste se postili a naříkali v pátém a v sedmém měsíci po těchto sedmdesát let, opravdu jste se postili kvůli mně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'A když jíte a pijete, což nejíte a ne pijete kvůli sobě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Což toto nebyla slova, která volal Hospodin prostřednictvím dřívějších proroků, když bezstarostně bydlel Jeruzalém i jeho města okolo něj, a tak i Negeb a Šefela?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'I stalo se Hospodinovo slovo k Zacharjášovi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Toto praví Hospodin zástupů: Suďte pravdivým soudem a prokazujte jeden druhému ⌈milosrdenství a slitování.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Neutlačujte vdovu ani sirotka, příchozího ani chudého, nevymýšlejte v srdci zlo jeden vůči druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Nechtěli věnovat pozornost, obrátili se vzpurně zády, zacpali si uši, aby neslyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Svá srdce proměnili v křemen, aby neslyšeli zákon a slova, která poslal Hospodin zástupů svým Duchem prostřednictvím dřívějších proroků, a tak na ně od Hospodina zástupů dopadlo velké rozhořčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'I stalo se, že jako volal, ale neslyšeli, tak budou volat, ale já nebudu slyšet, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Odvál jsem je do všech národů, které neznali. Země po nich byla zpustošena, takže jí nikdo neprochází sem ani tam. Tak proměnili výbornou zemi v hroznou pustinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'I stalo se slovo Hospodina zástupů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Toto praví Hospodin zástupů: Horlím pro Sijón velkou horlivostí a velkým rozlícením horlím pro něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Toto praví Hospodin: Vrátím se na Sijón a budu přebývat v Jeruzalémě. Jeruzalém se bude nazývat městem bezpečným a hora Hospodina zástupů horou svatou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Toto praví Hospodin zástupů: V jeruzalémských ulicích budou znovu sedět starci a stařeny, každý se svou holí v ruce pro ⌈vysoký věk.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Ulice města budou plné chlapců a děvčat radujících se na jeho ulicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Toto praví Hospodin zástupů: Jestliže to bude nemožné v očích ostatku tohoto lidu v oněch dnech, bude to nemožné také v mých očích? je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Toto praví Hospodin zástupů: Hle, zachráním svůj lid ⌈ze země východní i ze země na západ slunce,⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'přivedu je a budou bydlet v Jeruzalémě. Budou mým lidem a já budu jejich Bohem, věrně a spravedlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Toto praví Hospodin zástupů: Posilněte své ruce, vy, kteří jste v těchto dnech slyšeli tato slova z úst proroků, v den, kdy byly položeny základy domu Hospodina zástupů, aby byl znovu postaven chrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Neboť před oněmi dny nebylo mzdy pro člověka ani mzdy pro zvíře nebylo, a ten, kdo vycházel a vcházel, neměl pokoj od protivníka, protože jsem poštval všechny lidi jednoho proti druhému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Nyní však nebudu jednat s ostatkem tohoto lidu jako v dřívějších dnech, je výrok Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Neboť setbě se bude dařit, réva vydá plody, země vydá úrodu a nebesa dají rosu. To všechno dám do vlastnictví ostatku tohoto lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'I stane se, že jako jste byli mezi národy kletbou, dome judský a dome izraelský, tak vás zachráním a budete požehnáním. Nebojte se, posilněte své ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Neboť toto praví Hospodin zástupů: Jako jsem měl v úmyslu naložit s vámi zle, když mě vaši otcové podněcovali ke hněvu, praví Hospodin zástupů, a neslitoval jsem se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'tak mám zase v těchto dnech v úmyslu prokázat Jeruzalému a domu judskému dobro. Nebojte se!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Toto jsou věci, které konejte: ⌈Mluvte pravdu každý se svým bližním,⌉ pravdu a pokojný soud vynášejte ve svých branách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Nikdo ať nezamýšlí ve svém srdci zlo proti svému bližnímu a nemilujte lživou přísahu, neboť toto všechno nenávidím, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'I stalo se ke mně slovo Hospodina zástupů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Toto praví Hospodin zástupů: Půst čtvrtého, půst pátého, půst sedmého a půst desátého měsíce změním domu judskému v jásot, radost a veselé svátky. Proto milujte pravdu a pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Toto praví Hospodin zástupů: Znovu se stane, že přijdou národy a obyvatelé mnoha měst --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'obyvatelé jednoho města půjdou do druhého a řeknou: Pojďme, vydejme se udobřit si Hospodinovu tvář a hledat Hospodina zástupů. Já také půjdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'A půjdou mnozí lidé a mocné národy hledat Hospodina zástupů v Jeruzalémě a udobřit si Hospodinovu tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Toto praví Hospodin zástupů: V oněch dnech se stane, že deset mužů z národů všech jazyků se chytí, ano, chytnou se Judejce za cíp roucha a řeknou: Půjdeme s vámi, protože jsme slyšeli, že je s vámi Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Výnos. Hospodinovo slovo je proti zemi Chadraku a Damašek je místem, kde spočine. Vždyť k Hospodinu jsou obráceny oči lidí a všech izraelských kmenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'A také Chamát, který s ním hraničí, Týr a Sidón, neboť je příliš moudrý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Týr postavil opevnění a navršil stříbra jako prachu a zlata jako bláta na ulicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Hle, Panovník si ho podrobí, ⌈jeho majetek srazí do moře⌉ a samo bude stráveno ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Aškalón to uvidí a dostane strach, Gaza se bude hrozně třást i Ekrón, neboť zklame jeho naděje. Z Gazy zmizí král a Aškalón nebude obydlen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'V Ašdódu budou bydlet potomci ze smilstva, vyhladím pýchu Pelištejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Odstraním jeho krev z jeho úst a jeho ohavnosti z jeho zubů. Ten, kdo zůstane, bude také patřit jeho Bohu, stane se v Judsku náčelníkem a Ekrón bude jako Jebúsejec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Utábořím se ve svém domě jako stráž před tím, kdo by chtěl procházet sem a tam. Utlačovatel již přes ně nebude procházet, neboť nyní jsem to viděl na vlastní oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Velice jásej, dcero sijónská, hlahol, dcero jeruzalémská! Hle, přichází k tobě tvůj král. Je spravedlivý a vítězný. Pokorný, jede na oslu, na hříběti, osličím mláděti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Vyhladím vozy z Efrajima a koně z Jeruzaléma, válečné luky budou zničeny. Vyhlásí pokoj národům a jeho vláda bude od moře k moři, od Řeky až do končin země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Navíc, co se tebe týče, ⌈pro krev smlouvy s tebou,⌉ propustím tvé vězně z cisterny, ve které není voda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Navraťte se ⌈do pevnosti,⌉ ⌈vězňové mající naději.⌉ Dnes také oznamuji: Dvojnásobně ti odplatím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Neboť jsem napjal Judu jako luk a naplnil jsem jej Efrajimem jako šípy. Zamávám tvými syny, Sijóne, nad tvými syny, Jávane, a proměním tě v hrdinův meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Ukáže se nad nimi Hospodin, jeho šíp vyrazí jako blesk. Panovník Hospodin zatroubí na beraní roh, vytáhne v jižních vichřicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Hospodin zástupů ⌈jim bude štítem a⌉ oni budou jíst a pošlapou ⌈praky na vrhání kamenů.⌉ Budou pít a burácet jako po vínu, budou plní jako obětní miska, jako rohy oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Hospodin, jejich Bůh, je zachrání v onen den jako ovce svého lidu. Budou jako draho kamy v koruně, budou zářit v jeho zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Neboť jaká je jeho dobrota a jaká jeho krása! Obilí dá vzrůst mládencům a nové víno pannám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Od Hospodina žádejte déšť v čase jarního deště. Hospodin působí bouřky a dá jim silný déšť a každému zeleň na poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Vždyť domácí bůžci mluvili marnost, věštci viděli klam, mluví klamné sny, utěšují nicotnostmi. Proto putují jako ovce, krčí se, protože nemají pastýře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Můj hněv vzplál proti pastýřům, navštívím s trestem vůdce stáda. Neboť Hospodin zástupů navštíví své stádo, dům judský, a promění je v svého nádherného koně do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Z něho vzejde úhelný kámen, z něho vzejde kolík, z něho vzejde válečný luk, z něho vzejde i každý nadřízený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'A budou jako hrdinové šlapat v boji bláto na ulicích. Budou bojovat, protože Hospodin bude s nimi, a zahanbí jezdce na koních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Povýším dům judský a dům Josefův zachráním, přivedu je zpět, protože jsem se nad nimi slitoval. Budou, jako bych je neodvrhl, neboť já jsem Hospodin, jejich Bůh, a odpovím jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Efrajimci budou jako hrdina a jejich srdce se bude radovat jako po vínu. Jejich synové to uvidí, budou se radovat a jejich srdce bude jásat v Hospodinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Hvízdnu na ně a shromáždím je, neboť jsem je vykoupil, a bude jich tak mnoho, jako jich bývalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Ačkoliv jsem je zasel mezi národy, na vzdálených místech si na mě vzpomenou, ⌈budou žít se svými syny⌉ a navrátí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Přivedu je zpět z egyptské země, shromáždím je z Asýrie a uvedu je do země gileádské a na Libanon, ale nebude jim to místo stačit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, '⌈Soužení projde mořem⌉ a bude bít do mořských vln a všechny hlubiny Nilu vyschnou. Pýcha Asýrie bude svržena a žezlo Egypta zmizí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Povýším je v Hospodinu a v jeho jménu budou chodit, je Hospodinův výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Otevři svá vrata, Libanone, oheň ať stráví tvé cedry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Naříkej, cypřiši, neboť padl cedr, vznešené stromy jsou zničeny. Naříkejte, bášanské duby, neboť klesl nepřístupný les.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Slyš! Nářek pastýřů, neboť byly zničeny jejich pastviny. Slyš! Řev mladých lvů, neboť byla zničena jordánská houština.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Toto praví Hospodin, můj Bůh: Pas ovce určené na zabití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Ti, kdo je kupují, je zabíjejí a nenesou vinu, ti, kdo je prodávají, řeknou: Požehnaný je Hospodin, zbohatl jsem, a jejich pastýři s nimi nemají soucit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Nebudu již tedy mít soucit s obyvateli země, je Hospodinův výrok. Hle, ponechám každého člověka v ruce jeho bližního a v ruce jeho krále. Ti rozbijí zemi a já nikoho z jejich ruky nevysvobodím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Pásl jsem ovce určené na zabití, ⌈nejubožejší z ovcí.⌉ Vzal jsem si dvě hole. Jednu jsem nazval Laskavost, druhou jsem nazval Svornost a pásl jsem ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Vyhladil jsem tři pastýře v jednom měsíci, ⌈byl jsem s nimi netrpělivý⌉ a také ⌈oni si protivili⌉ mě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Řekl jsem: Nebudu vás pást. Ta, která má zemřít, ať zemře, a ta, která má být vyhlazena, ať je vyhlazena a ty, které zůstanou, ať sežerou maso jedna druhé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Vzal jsem hůl Laskavost a zlomil jsem ji, abych zrušil svou smlouvu, kterou jsem uzavřel se všemi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'V onen den byla zrušena a nejubožejší z ovcí, co mě pozorovaly, tak poznaly, že to je Hospodinovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Řekl jsem jim: Jestliže se vám to líbí, dejte mi mzdu, jestliže nikoli, upusťte od toho. Odvážili mi mzdu třicet šekelů stříbra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Hospodin mi řekl: Hoď to hrnčířovi, tu ⌈skvělou cenu,⌉ jíž mě ocenili. Vzal jsem těch třicet šekelů stříbra a hodil jsem to v Hospodinově domě hrnčířovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Pak jsem zlomil druhou hůl, Svornost, abych zrušil bratrství mezi Judou a Izraelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Hospodin mi dále řekl: Vezmi si ještě výstroj hloupého pastýře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Neboť hle, dám v zemi povstat pastýři, který se nebude starat o hynoucí, zatoulanou nebude hledat, polámanou nebude léčit, o zdravou nebude pečovat, ale bude jíst maso z tučných a jejich paznehty strhne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Běda mému ničemnému pastýři, který opouští ovce! Meč proti jeho paži a proti jeho pravému oku! Jeho paže zcela uschne a jeho pravé oko jistě zeslábne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Výnos. Hospodinovo slovo o Izraeli, výrok Hospodina, který roztáhl nebesa, založil zemi a vytvořil ducha člověka v jeho nitru:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Hle, učiním Jeruzalém opojnou číší pro všechny okolní národy. I na Judsko dojde při obléhání Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, '⌈I stane se v onen den,⌉ že učiním Jeruzalém vzpěračským kamenem pro všechny národy. Všichni, kdo jej budou zvedat, se velmi zraní a všechny národy země se proti němu shromáždí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'V onen den, je Hospodinův výrok, raním každého koně pomateností a jeho jezdce šílenstvím. Na dům judský ⌈otevřu své oči,⌉ ale všechny koně národů raním slepotou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Judští náčelníci si v srdci řeknou: Obyvatelé Jeruzaléma jsou mojí posilou skrze Hospodina zástupů, svého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'V onen den učiním judské náčelníky kotlíkem s ohněm na dřevě a ohnivou pochodní mezi snopy. Stráví všechny okolní národy napravo i nalevo a obyvatelé Jeruzaléma budou znovu pobývat na svém místě v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Hospodin nejprve zachrání judské stany, aby sláva domu Davidova a sláva obyvatel Jeruzaléma nebyla větší než Judova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'V onen den bude Hospodin štítem pro obyvatele Jeruzaléma a stane se v onen den, že klopýtající mezi nimi bude jako David a dům Davidův bude před nimi jako Bůh, jako Hospodinův anděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'I stane se v onen den, že budu chtít vyhladit všechny národy, které přitáhnou proti Jeruzalému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Vyleji na dům Davidův a na obyvatele Jeruzaléma ducha milosti a úpěnlivých proseb. Pohledí na mě, toho, kterého probodli, a budou ho oplakávat jako se kvílí nad jedináčkem, budou nad ním hořce naříkat, jako se naříká nad prvorozeným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'V onen den bude veliké kvílení v Jeruzalémě jako bylo kvílení v Hadad–Rimón na pláni u Megida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Země bude naříkat, ⌈každá čeleď⌉ zvlášť: Čeleď domu Davidova zvlášť a jejich ženy zvlášť, čeleď domu Nátanova zvlášť a jejich ženy zvlášť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'čeleď domu Léviho zvlášť a jejich ženy zvlášť, čeleď Šimeího zvlášť a jejich ženy zvlášť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'všechny čeledi, které zůstaly, ⌈každá čeleď⌉ zvlášť a jejich ženy zvlášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'V onen den bude pro dům Davidův a pro obyvatele Jeruzaléma otevřen pramen k očištění od hříchu a nečistoty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, '⌈I stane se v onen den,⌉ je výrok Hospodina zástupů, že vyhladím ze země jména modlářských zpodobenin a nebudou již připomínány. Také proroky a ducha nečistoty odstraním ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'I stane se, když bude ještě někdo prorokovat, že mu jeho otec a matka, kteří ho zrodili, řeknou: Nezůstaneš naživu, protože jsi mluvil klam v Hospodinově jménu! A jeho otec a matka, kteří ho zrodili, jej probodnou, když bude prorokovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'I stane se v onen den, že se budou proroci stydět, každý za své vidění, když prorokovali, a nebudou již oblékat chlupatý plášť, aby klamali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'A každý řekne: Nejsem prorok. Jsem rolník. Kdosi si mě koupil v mém mládí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'A zeptá– li se ho někdo: A co ty rány na prsou, on odpoví: Tak jsem byl bit v domě svých přátel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Probuď se, meči, proti mému pastýři, proti mému druhu, je výrok Hospodina zástupů. Bij pastýře a ovce se rozprchnou. Vztáhni ruku proti bezvýznamným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'I stane se v celé zemi, je Hospodinův výrok, že dva díly z ní budou vyhlazeny a zahynou a zůstane z ní třetina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Tu třetinu provedu ohněm, přečistím je jako se čistí stříbro, vyzkouším je, jako se zkouší zlato. Bude vzývat mé jméno a já mu odpovím. Řeknu: Je mým lidem. A on řekne: ⌈Hospodine, můj Bože.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Hle, přichází den Hospodinův, kdy ve tvém středu bude rozdělena ⌈tvá kořist.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Shromáždím všechny národy k Jeruzalému do boje. Město bude dobyto, domy budou vypleněny a ženy zneuctěny. Polovina města odejde do vyhnanství, ale zbytek lidu z města vyhlazen nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Hospodin vytáhne a bude bojovat proti těmto národům, jako když bojoval v den bitvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'V onen den se jeho nohy postaví na Olivové hoře, která je východně naproti Jeruzalému. Olivová hora se rozštěpí na poloviny od východu k západu a vznikne převeliké údolí. Polovina hory ustoupí na sever a polovina na jih.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Budete utíkat údolím mých hor, neboť horské údolí dosáhne k Ásalu. Budete utíkat, jako jste utíkali před země třesením ve dnech judského krále Uzijáše. Tehdy přijde Hospodin, můj Bůh, a všichni svatí s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, '⌈I stane se v onen den,⌉ že nebude světlo, ⌈hvězdy pohasnou.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Nastane jediný den, známý jen Hospodinu; nebude den a nebude noc, ale stane se, že ve večerním čase bude světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'I stane se v onen den, že z Jeruzaléma bude vyvěrat živá voda, polovina jí poteče do moře východního a polovina do moře západního. Tak to bude v létě i v zimě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Hospodin bude králem nad celou zemí. V onen den bude Hospodin jediný a jeho jméno bude jediné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Celá země se promění a bude jako Araba, od Geby po Rimón jižně od Jeruzaléma. Ale Jeruzalém bude vyvýšen a zůstane na svém místě od brány Benjamínovy až po místo brány První, až k bráně Rohové, věže Chananeel až ke královským lisům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Budou v něm pobývat a klatba již nebude, Jeruzalém bude bydlet v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'A toto bude rána, kterou Hospodin postihne všechny národy, jež vytáhly do boje proti Jeruzalému: Jejich tělo bude uhnívat, zatímco budou stát na nohou, jejich oči jim budou zahnívat v důlcích a jejich jazyk jim bude zahnívat v ústech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'I stane se v onen den, že bude mezi nimi velký zmatek od Hospodina. Jeden uchopí ruku druhého a ruka jednoho bude vztažena proti ruce druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Také Juda bude bojovat v Jeruzalémě. Bude nashromážděn majetek všech okolních národů, ⌈velké množství⌉ zlata, stříbra a oděvů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'A stejná rána, jako je tato, dopadne na koně, mezky, velbloudy, osly a na všechna zvířata, která budou v oněch táborech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'I stane se, že všichni zbývající ze všech národů, jež vytáhly proti Jeruzalému, budou rok co rok přicházet, aby se klaněli králi, Hospodinu zástupů, a slavili svátek stánků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'I stane se, když některá z čeledí země nepřijde do Jeruzaléma klanět se králi, Hospodinu zástupů, že nebude mít déšť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Jestliže egyptská čeleď nevystoupí a nepůjde, nedopadne na ně ta rána, kterou Hospodin postihne národy, jež nepřijdou slavit svátek stánků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Toto bude trest za hřích Egypta a trest za hřích všech národů, které nepřijdou slavit svátek stánků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'V onen den bude na zvoncích koní napsáno: Svatý Hospodinu a hrnce v Hospodinově domě budou jako obětní misky před oltářem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'I stane se, že každý hrnec v Jeruzalémě a v Judsku bude svatý Hospodinu zástupů; všichni ti, kdo obětují, přijdou, vezmou je a budou v nich vařit. A v domě Hospodina zástupů již v onen den nebude obchodník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Výnos. Hospodinovo slovo k Izraeli prostřednictvím Malachiáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, '⌈Zamiloval jsem si⌉ vás, praví Hospodin. Ptáte se: Jak jsi nám prokázal lásku? Což nebyl Ezau Jákobův bratr, je Hospodinův výrok, a přece jsem si Jákoba zamiloval,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'ale Ezaua jsem nenáviděl. Proměnil jsem jeho hory v pustinu a jeho dědictví jsem dal stepním šakalům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Když Edóm prohlašuje: Jsme pobořeni, ale znovu postavíme ⌈ to, co bylo v troskách,⌉ Hospodin zástupů praví toto: Ať si stavějí, já budu bořit. Nazvou je územím ničemnosti, lidem, na němž je Hospodinovo rozhořčení navěky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Vaše oči to uvidí a řeknete: Hospodin je veliký i za územím Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Syn ctí otce a otrok svého pána. Jestliže jsem otec, kde je ⌈úcta ke mně?⌉ Jestliže jsem Pán, kde je ⌈bázeň přede mnou?⌉ -- praví Hospodin zástupů vám kněžím, kteří opovrhujete mým jménem. Ptáte se: Jak opovrhujeme tvým jménem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Přinášíte na můj oltář poskvrněný chléb. Ptáte se: Čím tě poskvrňujeme? Tím, že říkáte: Hospodinovým stolem je možno pohrdat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Když přinášíte ⌈k oběti⌉ slepé zvíře, což to není zlé? Když přinášíte chromé a nemocné, což to není zlé? Jen to přines svému místodržiteli! Zdalipak si tě oblíbí, zdalipak tě milostivě přijme? -- praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Nuže, jen si hledejte přízeň Boha, aby se nad vámi smiloval! Toho se mu od vás dostalo -- cožpak vás milostivě přijme? -- praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Kéž by tak někdo z vás zavřel dveře, abyste nadarmo nezapalovali oheň na mém oltáři! Nemám ve vás zalíbení, praví Hospodin zástupů, ani přídavnou oběť od vás si neoblíbím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Neboť od východu slunce až na západ velké bude mé jméno mezi národy a na každém místě bude přinášeno kadidlo mému jménu a čistá přídavná oběť, neboť mé jméno je velké mezi národy, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Ale vy ho znesvěcujete, když říkáte: Panovníkův stůl je poskvrněný, ⌈jeho ovocem, jeho potravou je možno pohrdat.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Říkáte také: Hle, jak otravné! -- a ošklíbáte se nad tím, praví Hospodin zástupů. Přinášíte ukradené, chromé a nemocné; to přinášíte jako přídavnou oběť. Takovou oběť mám od vás se zalíbením přijmout? -- praví Hospodin.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Proklet buď ten, kdo jedná lstivě -- má ve svém stádu samce, učiní slib, ale obětuje Panovníkovi poškozené -- neboť jsem velký král, praví Hospodin zástupů, mé jméno vzbuzuje bázeň mezi národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'A nyní o vás kněžích je tento příkaz:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Jestliže neposlechnete a nevezmete si k srdci, abyste vzdávali slávu mému jménu, praví Hospodin zástupů, pošlu na vás kletbu a vaše požehnání ⌈změním v kletbu.⌉ Ano, již jsem ho změnil v kletbu, protože si to neberete k srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Hle, okřiknu vaše potomstvo, rozmetám výměty na vaši tvář, výměty z vašich svátečních obětí, a odstraní vás spolu s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'I poznáte, že jsem vám poslal tento příkaz, aby byla upevněna má smlouva s Lévim, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Má smlouva s ním byla život a pokoj. Dal jsem mu je k bázni. Bál se mě a děsil se před mým jménem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Pravdivý zákon byl v jeho ústech, zvrácenost nebyla nalezena na jeho rtech, v pokoji a podle práva chodil se mnou a mnohé odvrátil od provinění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Neboť rty kněze uchovávají poznání a z jeho úst se vyhledává poučení, neboť je poslem Hospodina zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Vy jste se však odvrátili od cesty, mnohé jste poučením přivedli k pádu, zkazili jste lévijskou smlouvu, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Také já jsem vás učinil opovrženými a poníženými před vším lidem, tak jako jste vy nezachovávali mé cesty a při poučení jste stranili lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Což nemáme všichni jednoho otce? Cožpak nás nestvořil jeden Bůh? Proč jednáme věrolomně jeden vůči druhému a znesvěcujeme smlouvu svých otců?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda byl nevěrný, ohavnost se páchala v Izraeli i v Jeruzalémě, neboť Juda znesvětil Hospodinovu svatyni, kterou on miluje, když se oženil s dcerou cizího boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Hospodin ať vyhladí ze ⌈stanů Jákobových⌉ každého, kdo to páchá, ⌈toho, kdo bdí, a toho, kdo odpovídá,⌉ i ⌈toho, kdo přináší⌉ přídavnou oběť Hospodinu zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'A ještě toto činíte: Zakrýváte Hospodinův oltář slzami, pláčem a nářkem, zatímco on již nehledí na přídavnou oběť, nepřijme ji od vás se zalíbením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'A ptáte se: Proč? Protože Hospodin je svědkem mezi tebou a ženou tvého mládí, vůči níž jsi byl nevěrný, ačkoliv ona je tvou družkou, ženou tvé smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, '⌈Ten, kdo má ostatek ducha, to nebude dělat.⌉ A co udělal ten jeden, když hledal potomka od Boha? Mějte se na pozoru ve svém duchu, vůči ženě svého mládí ať není nikdo nevěrný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Neboť nenávidím propuštění, praví Hospodin, Bůh Izraele, a toho, kdo přikrývá násilí na svém oděvu, praví Hospodin zástupů. Mějte se na pozoru ve svém duchu a nebuďte nevěrní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Unavujete Hospodina svými slovy. Ptáte se: Čím ho unavujeme? Tím, že říkáte: Každý, kdo páchá zlo, je dobrý v Hospodinových očích, v takových on má zalíbení, anebo: Kde je spravedlivý Bůh?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Hle, posílám svého posla a připraví cestu přede mnou. Panovník, kterého hledáte, vstoupí náhle do svého chrámu, posel smlouvy, jehož si přejete, hle, přijde, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Kdo vydrží den jeho příchodu? Kdo obstojí, až se ukáže? Vždyť on je jako zlatníkův oheň a pradlákův louh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Posadí se jako zlatník a čistič stříbra, pročistí syny Léviho, přečistí je jako zlato a stříbro a budou Hospodinu přinášet spravedlivé přídavné oběti');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'a Hospodinu bude přídavná oběť Judy a Jeruzaléma příjemná jako za dnů dávných, jako v letech pradávných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Přiblížím se k vám se soudem a budu rychlým svědkem proti čarodějům, cizoložníkům a těm, kdo lživě přísahají, těm, kdo utlačují za mzdu najatého, vdovu a sirotka, křivdí příchozímu a nebojí se mě, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Neboť já Hospodin jsem se nezměnil, ⌈ani vy jste nepřestali být synové Jákobovi.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Ode dnů svých otců jste se odvrátili od mých ustanovení a nezachovávali jste je. Vraťte se ke mně a vrátím se k vám, praví Hospodin zástupů. Ptáte se: Jak se máme navrátit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Což smí člověk okrádat Boha? Ale vy mě okrádáte! Ptáte se: Jak tě okrádáme? Na desátcích a darech pozdvihování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Kletbou jste prokleti, protože mě okrádáte, celý národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Přineste celý desátek do skladu, ať je potrava v mém domě. Vyzkoušejte mě takto, praví Hospodin zástupů, zdali vám neotevřu nebeské průduchy a ne vyleji na vás požehnání, dokud ne bude dostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Kvůli vám okřiknu žrouta a nezničí vám výnos země; ani réva na poli vás nepřipraví o plody, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Budou vás blahoslavit všechny národy, neboť budete oblíbenou zemí, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, '⌈Protivili jste se mi svými slovy,⌉ praví Hospodin. Ptáte se: Co jsme mluvili proti tobě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Říkáte: Sloužit Bohu je k ničemu! Jaký zisk z toho máme, že zachováváme jeho řád, když chodíme před Hospodinem zástupů ve smutku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Nuže, nazýváme domýšlivce šťastnými -- nejenže ⌈se dobře daří⌉ těm, kdo páchali ničemnost, ale provokovali Boha, a unikli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Tehdy ti, kdo se bojí Hospodina, mluvili jeden s druhým a Hospodin dával pozor a slyšel. Pamětní kniha byla před ním sepsána ⌈pro ty,⌉ kdo se bojí Hospodina a kdo si váží jeho jména.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Budou mým vlastnictvím -- praví Hospodin zástupů -- v den, který učiním. Budu mít s nimi soucit, jako má člověk soucit se svým synem, který mu slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Znovu budete vidět rozdíl mezi spravedlivým a ničemou, mezi tím, kdo Bohu slouží, a tím, kdo mu neslouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 19, 'Neboť hle, přichází den planoucí jako pec a všichni domýšlivci i všichni, kdo páchají ničemnost, se stanou strništěm. Ten přicházející den je spálí, praví Hospodin zástupů, nezanechá z nich kořen ani větev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 20, 'Avšak vám, kdo se bojíte mého jména, vzejde slunce spravedlnosti a na jeho paprscích bude uzdravení. Vyjdete a budete poskakovat jako vykrmené tele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 21, 'Pošlapete ničemy, ano, budou popelem pod chodidly vašich nohou v den, který já učiním, praví Hospodin zástupů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 22, 'Pamatujte na zákon mého otroka Mojžíše, který jsem mu dal na Chorébu, ustanovení a nařízení pro celý Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 23, 'Hle, pošlu vám proroka Elijáše, dříve než přijde Hospodinův den, velký a hrozný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 24, 'On obrátí srdce otců k synům a srdce synů k otcům, abych nepřišel a nestihl zemi klatbou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Rodokmen Ježíše Krista, syna Davidova, syna Abrahamova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham zplodil Izáka, Izák zplodil Jákoba, Jákob zplodil Judu a jeho bratry,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda zplodil Farese a Záru z Támary, Fares zplodil Chesróma, Chesróm zplodil Arama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram zplodil Amínadaba, Amínadab zplodil Naasona, Naason zplodil Salmóna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmón zplodil Bóaza z Rachaby, Bóaz zplodil Obéda z Rút, Obéd zplodil Isaje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Isaj zplodil Davida krále. [Král] David zplodil Šalomouna z ženy Uriášovy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Šalomoun zplodil Roboáma, Roboám zplodil Abiu, Abia zplodil Asafa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asaf zplodil Jóšafata, Jóšafat zplodil Jórama, Jóram zplodil Uziáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Uziáš zplodil Jótama, Jótam zplodil Achaza, Achaz zplodil Ezechiáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezechiáš zplodil Manasese, Manases zplodil ⌈Amose, Amos⌉ zplodil Joziáše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Joziáš zplodil Jechoniáše a jeho bratry za babylonského zajetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Po babylonském zajetí Jechoniáš zplodil Salathiela, Salathiel zplodil Zorobabela,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel zplodil Abiuda, Abiud zplodil Eljakima, Eljakim zplodil Azóra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azór zplodil Sádoka, Sádok zplodil Achima, Achim zplodil Eliuda,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud zplodil Eleazara, Eleazar zplodil Mattana, Mattan zplodil Jákoba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jákob zplodil Josefa, muže Marie, z níž se narodil Ježíš řečený Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Všech pokolení od Abrahama do Davida bylo tedy čtrnáct, od Davida po babylonské zajetí čtrnáct a od babylonského zajetí do Krista čtrnáct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'S narozením Ježíše Krista to bylo takto: Jeho matka Marie byla zasnoubena Josefovi. Dříve než se sešli, zjistilo se, ⌈že je těhotná⌉ z Ducha Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Její muž Josef byl ⌈spravedlivý, ale nechtěl⌉ ji vystavit hanbě; rozhodl se propustit ji tajně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Když to rozvážil, hle, Pánův anděl se mu ukázal ve snu a řekl: „Josefe, synu Davidův, neboj se přijmout Marii, svou ženu; neboť co v ní bylo počato, je z Ducha Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Porodí syna a ⌈dáš mu jméno⌉ Ježíš, neboť on vysvobodí svůj lid z jeho hříchů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'To všechno se událo, aby se naplnilo, co bylo řečeno od Pána skrze proroka:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Hle, ta panna otěhotní a porodí syna a dají mu jméno Immanuel, což v překladu znamená: Bůh s námi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Když se Josef probudil ze spánku, učinil, jak mu nařídil Pánův anděl, a přijal svou ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Ale nepoznal ji, dokud neporodila [svého prvorozeného] syna. A dal mu jméno Ježíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Když se Ježíš narodil v judském Betlémě za dnů krále Heroda, hle, mágové od východu přišli do Jeruzaléma');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'a říkali: „Kde je ten narozený král Židů? Spatřili jsme jeho hvězdu, ⌈když vycházela⌉, a přišli jsme se mu poklonit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Když to uslyšel král Herodes, ⌈znepokojil se⌉ a s ním celý Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Shromáždil všechny velekněze a ⌈učitele Zákona⌉ z lidu a vyptával se jich, kde se má Mesiáš narodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Oni mu řekli: „V judském Betlémě; neboť tak je napsáno skrze proroka:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'A ty, Betléme, země Judova, vůbec nejsi nejmenší mezi vladaři Judy, neboť z tebe vyjde vůdce, který bude pást můj lid, Izrael. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Tehdy Herodes tajně zavolal mágy a podrobně se jich vyptal na ⌈čas, kdy se hvězda ukazovala⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'poslal je do Betléma a řekl: „Jděte a pečlivě se vyptejte na to dítě; a jakmile je naleznete, oznamte mi to, abych se mu i já přišel poklonit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Vyslechli krále a vyšli. A hle, hvězda, kterou spatřili, ⌈když vycházela⌉, šla před nimi, až se zastavila nad místem, kde bylo to dítě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Když spatřili hvězdu, nesmírně se zaradovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Vešli do domu a uviděli dítě s Marií, jeho matkou. Padli na zem a poklonili se mu. Pak otevřeli své pokladnice a obětovali mu dary: zlato, kadidlo a myrhu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'A poněvadž dostali ve snu pokyn, aby se k Herodovi nevraceli, odebrali se do své země jinou cestou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Když odešli, hle, ukázal se Josefovi ve snu Pánův anděl a řekl: „Vstaň, vezmi dítě a jeho matku, uteč do Egypta a buď tam, dokud ti neřeknu, protože Herodes bude dítě hledat, aby je zahubil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'On tedy vstal, vzal v noci dítě i jeho matku a odešel do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'A byl tam až do Herodovy smrti, aby se naplnilo,co bylo řečeno od Pána skrze proroka: Z Egypta jsem povolal svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Když Herodes uviděl, že ho mágové oklamali, velice se rozlítil a dal pobít všechny chlapce v Betlémě i v celém jeho okolí, od dvouletých níže, podle času, který vyzvěděl od mágů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Tehdy se naplnilo,co bylo řečeno skrze proroka Jeremjáše:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Hlas v Ráma bylo slyšet, [nářek a] pláč a velké bědování; Ráchel oplakává své děti a nechce se dát utěšit, protože jich není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Když Herodes zemřel, hle, Pánův anděl se ukázal ve snu Josefovi v Egyptě');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'a řekl: „Vstaň, vezmi dítě a jeho matku a jdi do země izraelské, neboť ti, kteří ⌈ukládali dítěti o život⌉, již zemřeli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'On tedy vstal, vzal dítě a jeho matku a vešel do izraelské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Když však uslyšel, že v Judsku kraluje místo svého otce Heroda Archelaos, bál se tam odejít. Na pokyn ve snu odešel do oblasti Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'I přišel a usadil se ve městě zvaném Nazaret, aby se naplnilo, co bylo řečeno skrze proroky: Bude nazýván Nazaretský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'V těch dnech přichází Jan Křtitel hlásající v judské pustině:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '„⌈Čiňte pokání,⌉ neboť se přiblížilo království Nebes.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'To je ten, o němž bylo řečeno skrze proroka Izaiáše: Hlas volajícího v pustině: Připravte Pánovu cestu, vyrovnávejte jeho stezky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Sám Jan pak měl na sobě oděv z velbloudí srsti a kolem beder kožený pás a jeho potravou byly kobylky a med divokých včel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Tehdy vycházel k němu Jeruzalém a celé Judsko i celé okolí Jordánu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'a dávali se od něho pokřtít v [řece] Jordánu, vyznávajíce své hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Když však uviděl, jak mnozí farizeové a saduceové přicházejí k jeho křtu, řekl jim: „⌈Plemeno zmijí⌉! Kdo vám ukázal, jak utéci před nadcházejícím hněvem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Vydávejte tedy ovoce ⌈svědčící o⌉ pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'A nedomnívejte se, že si můžete říkat: Náš otec je Abraham. Neboť vám pravím, že Bůh může Abrahamovi vzbudit děti z těchto kamenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Sekera je už přiložena ke kořeni stromů; každý strom, který nenese dobré ovoce, bude vyťat a hozen do ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Já vás křtím ve vodě k pokání; ale ten, který přichází za mnou, je silnější než já; jemu nejsem hoden ani nést sandály. On vás bude křtít ⌈v Duchu Svatém a ohni⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'V jeho ruce je lopata; i pročistí svůj mlat a shromáždí svou pšenici do sýpky, plevy však bude pálit ohněm neuhasitelným.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Tehdy Ježíš přišel z Galileje k Jordánu za Janem, aby byl od něho pokřtěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Ale Jan se mu v tom ⌈snažil zabránit⌉ a říkal: „Já bych měl být pokřtěn od tebe, a ty přicházíš ke mně?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Ježíš mu odpověděl: „Nech to nyní; neboť takto je třeba, abychom naplnili všechnu spravedlnost.“On ho tedy nechal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Když byl Ježíš pokřtěn, vystoupil hned z vody. A hle, otevřela se [mu] nebesa a spatřil Ducha Božího, jak sestupuje jako holubice a přichází na něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'A hle, ozval se hlas z nebes, který říkal: „Toto je ⌈můj Syn, Milovaný⌉, v němž ⌈jsem nalezl zalíbení⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Tehdy Duch Ježíše vyvedl do pustiny, aby byl pokoušen od Ďábla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'A když se postil čtyřicet dní a čtyřicet nocí, nakonec vyhladověl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Tu přistoupil Pokušitel a řekl mu: „Jsi–li Syn Boží, řekni, ať se z těchto kamenů stanou chleby.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'On však ⌈na to⌉ řekl: „Je napsáno: Člověk nebude živ jen chlebem, ale každým slovem, které vychází z Božích úst. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Potom ho Ďábel vzal do svatého města, postavil ho na okraj střechy chrámu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'a řekl mu: „Jsi–li Syn Boží, vrhni se dolů; vždyť je napsáno: Svým andělům přikáže o tobě, a na rukou tě ponesou, abys snad nenarazil nohou na kámen. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Ježíš mu řekl: „Je také napsáno: Nebudeš pokoušet Pána, svého Boha. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Pak ho Ďábel vzal na velmi vysokou horu a ukázal mu všechna království světa a jejich slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'A řekl mu: „Toto všechno ti dám, jestliže padneš na zem a pokloníš se mi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Tu mu Ježíš řekl: „Odejdi, Satane. Vždyť je napsáno: Pánu, svému Bohu, se budeš klanět a jeho jediného uctívat. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'A tehdy ho Ďábel opustil. A hle, andělé přistoupili a sloužili mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Když [Ježíš] uslyšel, že byl Jan uvězněn, odebral se do Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Opustil Nazaret, šel a usadil se v Kafarnaum, které je u moře, v oblastech Zabulón a Neftalí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'aby se naplnilo, co bylo řečeno skrze proroka Izaiáše:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Země Zabulón a země Neftalí, cestou u moře, za Jordánem -- Galilea pohanů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'lid sedící v temnotě uviděl veliké světlo, těm, kteří seděli v krajině a stínu smrti, vzešlo světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Od té chvíle začal Ježíš hlásat a říkat: „Čiňte pokání, neboť se přiblížilo království Nebes.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Když se procházel podél Galilejského moře, uviděl dva bratry, Šimona zvaného Petr a jeho bratra Ondřeje, jak do moře vrhají kruhovou síť; byli totiž rybáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Řekl jim: „Pojďte za mnou a učiním z vás rybáře lidí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Oni hned opustili sítě a následovali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'A když odtamtud poodešel, uviděl jiné dva bratry, Jakuba, syna Zebedeova, a jeho bratra Jana, jak v lodi se svým otcem Zebedeem spravují své sítě. I povolal je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Oni ihned opustili loď i svého otce a následovali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Procházel celou Galilejí, učil v jejich synagogách, hlásal ⌈evangelium království⌉ a uzdravoval každou nemoc a každou slabost v lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Pověst o něm se roznesla po celé Sýrii. Přinesli k němu všechny nemocné, kteří byli sužováni rozličnými nemocemi a trápeními, démonizované, náměsíčné i ochrnuté a on je uzdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Šly za ním veliké zástupy z Galileje, Dekapole, Jeruzaléma, Judska i Zajordání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Když spatřil zástupy, vystoupil na horu. A když se posadil, přistoupili k němu jeho učedníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Otevřel ústa a učil je:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '„Blahoslavení chudí duchem, neboť jejich je království Nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Blahoslavení plačící, neboť oni budou potěšeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Blahoslavení tiší, neboť oni dostanou zemi do dědictví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Blahoslavení ti, kdo hladovějí a žízní po spravedlnosti, neboť oni budou nasyceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Blahoslavení milosrdní, neboť oni dojdou milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Blahoslavení čistého srdce, neboť oni uvidí Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Blahoslavení ti, kdo působí pokoj, neboť oni budou nazváni Božími syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Blahoslavení ti, kdo jsou pronásledováni pro spravedlnost, neboť jejich je království Nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Když vás budou tupit a pronásledovat a mluvit proti vám lživě všecko zlé kvůli mně, jste blahoslavení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Radujte se a jásejte, neboť hojná je vaše odplata v nebesích; vždyť takto pronásledovali proroky, kteří byli před vámi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, '„Vy jste sůl země. Jestliže sůl ztratí chuť, čím bude osolena? Nehodí se již k ničemu, než aby ji vyhodili a lidé po ní šlapali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vy jste světlo světa. Nemůže být ukryto město ležící na hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'A když rozsvítí lampu, nekladou ji pod nádobu, ale na stojan; a svítí všem, kteří jsou v domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Tak ať vaše světlo září před lidmi, aby uviděli vaše dobré skutky a vzdali slávu vašemu Otci, který je v nebesích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, '„Nedomnívejte se, že jsem přišel zrušit Zákon nebo Proroky; nepřišel jsem je zrušit, nýbrž naplnit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Neboť ⌈amen, pravím vám:⌉ Dokud nepomine nebe a země, nepomine jediné ⌈nejmenší písmenko⌉ ani jedna čárka ze Zákona, dokud se všechno nestane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Kdo by tedy zrušil jediné z těchto nejmenších přikázání a tak učil lidi, bude v království Nebes nazván nejmenším. Kdo by je však ⌈činil a učil⌉, ten bude v království Nebes nazván velkým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Neboť vám pravím: Nebude–li vaše spravedlnost o mnoho převyšovat spravedlnost učitelů Zákona a farizeů, do království Nebes určitě nevstoupíte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, '„Slyšeli jste, že bylo řečeno předkům: Nezavraždíš. Kdo by zavraždil, propadne soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Já vám však pravím, že soudu propadne každý, kdo se [bez příčiny] hněvá na svého bratra. Kdo by svému bratru řekl: Raka, propadne veleradě. Kdo by mu řekl: Blázne, propadne ohnivé Gehenně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Jestliže tedy přinášíš svůj dar na oltář a tam si vzpomeneš, že tvůj bratr má něco proti tobě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'zanech tam před oltářem svůj dar a odejdi; nejprve se usmiř se svým bratrem, a pak přijď a obětuj svůj dar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, '⌈Dohodni se⌉ se svým odpůrcem rychle, dokud jsi s ním na cestě, aby tě snad odpůrce nevydal soudci a soudce strážci, a byl bys uvržen do vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, '⌈Amen, pravím⌉ tobě: Jistě odtamtud nevyjdeš, dokud nezaplatíš poslední haléř.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, '„Slyšeli jste, že bylo řečeno [předkům]: Nezcizoložíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Já však vám pravím, že každý, kdo hledí na ženu tak, ⌈že po ní zatouží⌉, již s ní zcizoložil ve svém srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Jestliže tě tvé pravé oko svádí, vyjmi je a odhoď od sebe; neboť je pro tebe lépe, aby zahynul jeden z tvých údů, než aby celé tvé tělo bylo vrženo do Gehenny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'A jestliže tě svádí tvá pravá ruka, utni ji a odhoď od sebe; neboť je pro tebe lépe, aby zahynul jeden z tvých údů, než aby celé tvé tělo odešlo do Gehenny.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, '„Také bylo řečeno: Kdo propustí svou ženu, ať jí dá rozlukový list.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Ale já vám pravím, že každý, kdo propouští svou ženu, kromě případu smilstva, uvádí ji do cizoložství, a kdo by se s propuštěnou oženil, cizoloží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, '„Dále jste slyšeli, že bylo řečeno předkům: ⌈Nebudeš křivě přísahat⌉, ale splníš Pánu své přísahy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Já však vám pravím, abyste nepřísahali vůbec; ani při nebi, protože je to trůn Boží;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'ani při zemi, protože je to podnož jeho nohou; ani při Jeruzalému, protože je to město velikého Krále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Nepřísahej ani při své hlavě, protože ani jediný vlas nemůžeš učinit bílým nebo černým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Ať je tedy vaše slovo ano, ano -- ne, ne; co je nad to, je ze Zlého.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, '„Slyšeli jste, že bylo řečeno: Oko za oko a zub za zub.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Já však vám pravím, abyste neodporovali zlému člověku, ale když tě někdo udeří do [tvé] pravé tváře, nastav mu i druhou tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'A tomu, kdo se s tebou chce soudit a vzít ti košili, nech i plášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'A když tě někdo bude nutit k službě na jednu míli, jdi s ním dvě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Tomu, kdo tě žádá, dej a od toho, kdo si od tebe chce vypůjčit, se neodvrať.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, '„Slyšeli jste, že bylo řečeno: Budeš milovat svého bližního a nenávidět svého nepřítele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Já však vám pravím: Milujte své nepřátele, [žehnejte těm, kdo vás proklínají, dobře čiňte těm, kdo vás nenávidí,] a modlete se za ty, kteří vás [urážejí a] pronásledují,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'abyste byli syny svého Otce, který je v nebesích; neboť on nechává své slunce vycházet nad zlými i dobrými a déšť posílá na spravedlivé i nespravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Jestliže si zamilujete ty, kteří vás milují, jakou máte odměnu? Což i celníci nečiní totéž?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'A pozdravíte–li jen své bratry, co činíte navíc? Nečiní totéž i pohané?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Buďte tedy dokonalí, jako je dokonalý váš nebeský Otec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '„Dávejte si pozor, abyste nekonali ⌈svou spravedlnost⌉ před lidmi, ⌈jim na odiv⌉; jinak nemáte odměnu u svého Otce, který je v nebesích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, '„Když tedy ⌈dáváš almužnu⌉, nevytrubuj to před sebou, jak to činí pokrytci v synagogách a na ulicích, aby je lidé pochválili. Amen, pravím vám: Mají už svou odměnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Ale když ty ⌈dáváš almužnu⌉, ať tvá levice nepozná, co činí pravice,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'aby tvá almužna zůstala skrytá. A tvůj Otec, který vidí v skrytu, ti odplatí [zjevně].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, '„A když se modlíte, nebuďte jako pokrytci; neboť ti se rádi modlí, stojíce v synagogách a na rozích ulic, aby je viděli lidé. Amen, pravím vám: Mají už svou odměnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Když ty se modlíš, vejdi do svého pokoje, zavři za sebou dveře a pomodli se k svému Otci, který je v skrytu, a tvůj Otec, který vidí v skrytu, ti odplatí [zjevně].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Když se modlíte, ⌈neopakujte naprázdno slova⌉ jako pohané, neboť ti se domnívají, že budou vyslyšeni pro množství svých slov.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Nebuďte proto jako oni; vždyť [Bůh,] váš Otec ví, co potřebujete, dříve, než jej poprosíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vy se modlete takto: Otče náš, který jsi v nebesích, buď posvěceno tvé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Přijď tvé království. Staň se tvá vůle jako v nebi, tak i na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Náš denní chléb dej nám dnes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'A odpusť nám naše viny, jako jsme i my odpustili ⌈těm, kdo se provinili proti nám⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'A neuveď nás do pokušení, ale vysvoboď nás od ⌈toho Zlého⌉ [, neboť tvé je království i moc i sláva na věky. Amen].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Neboť jestliže odpustíte lidem jejich provinění, odpustí váš nebeský Otec i vám;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'jestliže však lidem [jejich provinění] neodpustíte, ani váš Otec vám neodpustí vaše provinění.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, '„Když se postíte, nebývejte zasmušilí jako pokrytci; ⌈ ti se totiž tváří ztrápeně⌉, aby lidem ukázali, že se postí. Amen, pravím vám: Mají už svou odměnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Ale ty, když se postíš, potři svou hlavu olejem a svou tvář umyj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'abys neukázal lidem, že se postíš, ale svému Otci, který je v skrytu. A tvůj Otec, který vidí v skrytu, ti odplatí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, '„Neshromažďujte si poklady na zemi, kde je ničí mol a rez a kde se zloději prokopávají a kradou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Shromažďujte si poklady v nebi, kde je neničí mol ani rez a kde se zloději neprokopávají ani nekradou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Neboť kde je tvůj poklad, tam bude i tvé srdce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, '„Lampou těla je oko. Je–li tvé oko čisté, celé tvé tělo bude ⌈plné světla⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Ale je–li tvé oko špatné, celé tvé tělo bude temné. Je–li tedy i světlo v tobě tmou, jak velká je pak temnota!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, '„Nikdo nemůže být otrokem dvou pánů; buď bude totiž jednoho nenávidět a druhého milovat, nebo se k jednomu upne a druhým pohrdne. Nemůžete sloužit Bohu i mamonu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, '„Proto vám pravím: Nedělejte si starosti o svůj život, o to, co budete jíst [a co budete pít], ani o své tělo, o to, co si obléknete. Není život víc než pokrm a tělo víc než oděv?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Pohleďte na nebeské ptáky: nesejí, nežnou ani neshromažďují do stodol, a váš nebeský Otec je živí. Což vy nejste o mnoho cennější než oni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Kdo z vás dokáže svou starostlivostí přidat ⌈k délce svého věku⌉ jediný loket?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'A proč si děláte starosti o oděv? Podívejte se pozorně na polní lilie, jak rostou. Nenamáhají se ani nepředou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'a pravím vám, že ani Šalomoun v celé své slávě nebyl oblečen jako jedna z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Jestliže tedy Bůh tak obléká polní trávu, která dnes je a kterou zítra hodí do pece, nebude tím spíše oblékat vás, malověrní?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Nepropadněte tedy starostem a neříkejte: Co budeme jíst? nebo: Co budeme pít? nebo: Co si oblečeme?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Neboť o to všechno horlivě usilují pohané. Vždyť váš nebeský Otec ví, že to všechno potřebujete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Hledejte však nejprve Boží království a jeho spravedlnost, a to všechno vám bude přidáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Nedělejte si tedy starost kvůli zítřku, neboť zítřek ⌈bude mít své vlastní starosti⌉. Každý den má dost vlastního trápení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '„Nesuďte, abyste ⌈nebyli souzeni⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Neboť jakým soudem soudíte, takovým budete souzeni, a jakou měrou měříte, takovou vám bude naměřeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Proč tedy hledíš na třísku v oku svého bratra, ale trámu ve svém oku si nevšímáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Anebo jak můžeš říkat svému bratru: Dovol, ať vyjmu třísku z tvého oka, a hle, ve tvém oku je trám?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Pokrytče, nejprve vyjmi trám ze svého oka, a pak jasně uvidíš, jak vyjmout třísku z oka svého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Nedávejte psům, co je svaté,a neházejte své perly před svině, aby je snad nohama nepošlapaly, neotočily se a neroztrhaly vás.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, '„Žádejte, a bude vám dáno; hledejte, a naleznete; tlučte, a bude vám otevřeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Neboť každý, kdo žádá, dostává, a kdo hledá, nalézá a tomu, kdo tluče, bude otevřeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Kdo z vás je takový člověk, který podá svému synu kámen, když ho požádá o chléb?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Nebo mu podá hada, když ho požádá o rybu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Jestliže tedy vy, ač jste zlí, umíte svým dětem dávat dobré dary, čím spíše dá dobré věci těm, kteří ho žádají, váš Otec, který je v nebesích!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Všechno, co byste chtěli, aby lidé činili vám, čiňte i vy jim; neboť to je ⌈Zákon a Proroci.“⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, '„Vejděte těsnou branou, protože široká je [brána] a prostorná cesta, která vede do záhuby; a mnoho je těch, kteří jí vcházejí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Jak těsná je brána a zúžená cesta, která vede do života, a málo je těch, kdo ji nalézají!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, '„Mějte se na pozoru před falešnými proroky, kteří k vám přicházejí v rouchu ovčím, ale uvnitř jsou draví vlci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Po jejich ovoci je poznáte. Což se sbírají z trní hrozny nebo z bodláčí fíky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Tak každý dobrý strom nese dobré ovoce, ale prohnilý strom nese špatné ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Dobrý strom nemůže nést špatné ovoce ani prohnilý strom dobré ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Každý strom, který nenese dobré ovoce, bývá vyťat a hozen do ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Poznáte je tedy po jejich ovoci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, '„Ne každý, kdo mi říká: Pane, Pane, vejde do království Nebes, ale ten, kdo činí vůli mého Otce, který je v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Mnozí mi v onen den řeknou: Pane, Pane, což jsme tvým jménem neprorokovali a tvým jménem nevyháněli démony a tvým jménem neučinili mnoho ⌈mocných činů⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'A tehdy jim vyznám: Nikdy jsem vás neznal. Odejděte ode mne, činitelé nepravosti. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, '„Každý, kdo slyší tato má slova a činí je, bude tedy podoben muži prozíravému, který postavil svůj dům na skále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'A spadl déšť a přihnaly se vody a zaduly větry a udeřily na ten dům -- ale nezřítil se, neboť byl založen na skále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'A každý, kdo slyší tato má slova a nečiní je, bude podoben muži pošetilému, který postavil svůj dům na písku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'A spadl déšť a přihnaly se vody a zaduly větry a udeřily na ten dům -- a zřítil se a jeho pád byl veliký.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'A stalo se, že když Ježíš dokončil tato slova, byly zástupy ohromeny jeho učením,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'neboť je učil jako ten, kdo má pravomoc, a ne jako [jejich] učitelé Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Když sestoupil z hory, vydaly se za ním velké zástupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'A hle, přišel malomocný, klaněl se mu a říkal: „Pane, chceš–li, jsi mocen mne očistit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'On vztáhl ruku, dotkl se ho a řekl: „Chci, buď očištěn.“A hned byl očištěn od svého malomocenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Ježíš mu řekl: „Hleď, abys o tom nikomu neřekl. Ale jdi, ukaž se knězi a obětuj dar, který Mojžíš přikázal, jim na svědectví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Když vešel do Kafarnaum, přistoupil k němu jeden setník ⌈a prosil ho⌉:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, '„Pane, můj sluha leží doma ochrnutý a hrozně trpí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, '[Ježíš] mu řekl: „Já ⌈přijdu a uzdravím ho.⌉“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Setník však odpověděl: „Pane, nejsem hoden, abys vstoupil pod mou střechu; ale řekni jen slovo, a můj sluha bude uzdraven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Vždyť i já jsem člověk ⌈ postavený pod pravomocí⌉ a mám pod sebou vojáky; a řeknu– li tomuto: Jdi, on jde; řeknu–li jinému: Přijď, přijde; a řeknu–li svému otroku: Udělej toto, pak to udělá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Když to Ježíš uslyšel, podivil se a řekl těm, kteří ho následovali: „Amen, pravím vám, takovou víru jsem v Izraeli nenašel u nikoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Pravím vám, že mnozí přijdou od východu i západu a budou stolovat s Abrahamem, Izákem a Jákobem v království Nebes;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'avšak synové království ⌈budou vyvrženi⌉ do nejzazší temnoty; tam bude ⌈pláč a skřípění zubů.⌉“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'I řekl Ježíš setníkovi: „Jdi, [a] staň se ti, jak jsi uvěřil.“A v tu hodinu byl [jeho] sluha uzdraven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Když Ježíš přišel do Petrova domu, uviděl, že jeho tchyně leží a má horečku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Dotkl se její ruky a horečka ji opustila; i vstala a obsluhovala ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Když nastal večer, přinesli k němu mnoho démonizovaných; i vyhnal duchy slovem a všechny nemocné uzdravil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'aby se naplnilo, co bylo řečeno skrze proroka Izaiáše: On sám naše slabosti vzal a nemoci nesl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Když Ježíš kolem sebe uviděl zástup, rozkázal ⌈přeplavit se⌉ na druhou stranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Tu přišel jeden učitel Zákona a řekl mu: „Učiteli, budu tě následovat, kamkoli půjdeš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'A Ježíš mu řekl: „Lišky mají doupata a nebeští ptáci hnízda, ale Syn člověka nemá, kde by hlavu složil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Jiný z [jeho] učedníků mu řekl: „Pane, dovol mi nejprve odejít a pohřbít svého otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Ježíš mu však řekl: „Následuj mě a nech mrtvé, ať pohřbí své mrtvé.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Pak vstoupil do lodi a jeho učedníci ho následovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'A hle, na moři se strhla veliká bouře, takže vlny zakrývaly loď; on však spal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'I přišli [jeho učedníci], vzbudili ho a řekli: „Pane, zachraň [nás], hyneme!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Řekl jim: „Proč jste ustrašení, vy malověrní?“Pak vstal, pohrozil větrům i moři; a nastal úplný klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Lidé užasli a říkali: „Kdo to asi je, že ho i větry a moře poslouchají?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'A když se dostal na druhou stranu do krajiny Gadarenských, setkali se s ním dva démonizovaní, kteří vyšli z hrobů. Byli velmi nebezpeční, takže tou cestou nemohl nikdo projít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'A hle, zakřičeli: „⌈Co je ti po nás⌉, [Ježíši,] Synu Boží? Přišel jsi sem, abys nás trýznil před ustanoveným časem?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Daleko od nich se páslo stádo mnoha vepřů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Démoni ho prosili: „Jestliže nás vyháníš, ⌈pošli nás⌉ do toho stáda vepřů!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Řekl jim: „Jděte!“Oni vyšli a odešli do vepřů; a hle, celé stádo [vepřů] se zřítilo po svahu do moře a zahynulo ve vodách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Pasáci utekli, a když přišli do města, vyprávěli všechno, i to o těch démonizovaných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'A hle, celé město vyšlo naproti Ježíšovi; a když ho spatřili, poprosili ho, aby odešel z jejich území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Ježíš vstoupil na loď, přeplavil se a přišel do svého města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'A hle, přinášeli k němu ochrnutého, položeného na lůžku. Když Ježíš uviděl jejich víru, řekl ochrnutému: „⌈Buď dobré mysli⌉, synu, ⌈odpouštějí se⌉ ti [tvé] hříchy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'A hle, někteří z učitelů Zákona si řekli: „Ten člověk se rouhá!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Ježíš uviděl jejich myšlenky a řekl: „Proč smýšlíte ve svých srdcích zle?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Vždyť co je snadnější? Říci: ⌈Odpouštějí se ti⌉ hříchy, nebo říci: Vstaň a choď?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Abyste však věděli, že Syn člověka má pravomoc odpouštět na zemi hříchy ...“Tu řekne ochrnutému: „Vstaň, vezmi své lůžko a jdi do svého domu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'A on vstal a odešel do svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Když to uviděly zástupy, ⌈zmocnil se jich strach⌉ a vzdaly chválu Bohu, který dal lidem takovou pravomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'A když Ježíš odtamtud odcházel, uviděl v celnici sedět člověka jménem Matouš a řekl mu: „Následuj mne!“Matouš vstal a následoval ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'A stalo se, když byl Ježíš u stolu v domě, hle, přišlo mnoho celníků a hříšníků, aby stolovali s ním a s jeho učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Když to uviděli farizeové, říkali jeho učedníkům: „Proč váš Učitel jí s celníky a hříšníky?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Když to [Ježíš] uslyšel, řekl [jim]: „Lékaře nepotřebují zdraví, ale nemocní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Jděte a naučte se, co znamená: Milosrdenství chci, a ne oběť. Neboť jsem nepřišel povolat spravedlivé, ale hříšníky [k pokání].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Tehdy k němu přišli Janovi učedníci a řekli: „Proč se my a farizeové [často] postíme, ale tvoji učedníci se nepostí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Ježíš jim řekl: „Mohou svatebčané truchlit, dokud je s nimi ženich? Přijdou však dny, kdy jim bude ženich odebrán, a tehdy se budou postit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Nikdo nedává záplatu z neseprané látky na starý šat; ta ková výplň se totiž ze šatu vytrhne a trhlina se ještě zhorší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Ani se nedává mladé víno do starých měchů, jinak se ty měchy roztrhnou, víno vyteče a měchy se zničí. Mladé víno se dává do nových měchů, a obojí zůstane zachováno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Když jim to říkal, hle, přišel jeden z ⌈představených synagogy ⌉, klaněl se mu a řekl: „Má dcera právě zemřela; ale pojď, vlož na ni svou ruku, a bude žít.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Ježíš vstal a šel za ním i se svými učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'A hle, žena dvanáct let trpící krvotokem přišla zezadu a dotkla se třásní jeho šatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Neboť si říkala: „Jestliže se jen dotknu jeho šatu, budu zachráněna.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Ježíš se otočil, a když ji spatřil, řekl: „Buď dobré mysli, dcero, tvá víra tě zachránila.“A od té hodiny byla ta žena zachráněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Když Ježíš vstoupil do domu představeného synagogy a uviděl pištce a hlučící zástup,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'říkal: „Odejděte! Vždyť ta dívka nezemřela, ale spí.“I posmívali se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'A když byl zástup vyhnán, vešel, uchopil její ruku a děvče se probudilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'A zpráva o tom se rozšířila do celé té země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Když odtamtud Ježíš odcházel, vydali se za ním dva slepci, ⌈kteří křičeli⌉: „Smiluj se nad námi, synu Davidův!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'A když vešel do domu, přistoupili ti slepci k němu. Ježíš jim řekl: „Věříte, že ⌈to mohu⌉ učinit?“Řekli mu: „Ano, Pane.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Nato se dotkl jejich očí a řekl: „Staň se vám podle vaší víry!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'A jejich oči se otevřely. Ježíš jim pohrozil a řekl: „Hleďte, ať o tom nikdo neví!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Oni však vyšli a ⌈rozšířili zprávu o něm⌉ po celé té zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Když odcházeli, hle, přivedli k němu němého démonizovaného [člověka].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'A když byl démon vyhnán, němý promluvil. A zástupy užasly a říkaly: „ Něco takového se v Izraeli nikdy nestalo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Ale farizeové říkali: „⌈V moci ⌉ vládce démonů vyhání démony.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Ježíš obcházel všechna města i vesnice, učil v jejich synagogách, hlásal evangelium království a uzdravoval každou nemoc a každou slabost [v lidu].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Když uviděl zástupy, byl nad nimi hluboce pohnut, protože byli utrápení a sklíčení jako ovce, které nemají pastýře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Tehdy řekl svým učedníkům: „Žeň je velká, dělníků je však málo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Proste tedy Pána žně, aby poslal dělníky na svou žeň.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Zavolal si svých dvanáct učedníků a dal jim pravomoc nad nečistými duchy, aby je vyháněli a aby uzdravovali každou nemoc i každou slabost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Jména těch dvanácti apoštolů jsou tato: první Šimon zvaný Petr, jeho bratr Ondřej, Jakub Zebedeův a jeho bratr Jan,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filip, Bartoloměj, Tomáš, celník Matouš, Jakub Alfeův, Tadeáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Šimon Kananejský a Juda Iškariotský, který ho pak zradil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Těchto dvanáct Ježíš poslal, když jim předtím nařídil: „Nechoďte na cestu pohanů a do samařského města nevstupujte;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'ale jděte raději k zahynulým ovcím z domu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Cestou hlásejte: Přiblížilo se království Nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Uzdravujte nemocné, probouzejte mrtvé, očišťujte malomocné, vyhánějte démony -- zadarmo jste přijali, zadarmo dejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Neopatřujte si do svých opasků zlato ani stříbro ani měď;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'neberte si na cestu ani mošnu ani dvě košile ani sandály ani hůl, neboť dělník je hoden své obživy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Do kteréhokoli města nebo vesnice vejdete, vyptejte se, kdo v něm je toho hoden; a tam zůstaňte, dokud neodejdete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Když budete vcházet do domu, pozdravte jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Bude–li toho ten dům vskutku hoden, ať na něj přijde váš pokoj. Nebude–li však toho hoden, ať se váš pokoj navrátí k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'A když vás někdo nepřijme a nevyslechne vaše slova, při odchodu z toho domu nebo onoho města vytřeste prach se svých nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Amen, pravím vám, v den soudu bude snesitelněji sodomské a gomorské zemi než onomu městu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, '„Hle, já vás posílám jako ovce mezi vlky; buďte tedy obezřetní jako hadi a prostí jako holubice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Mějte se na pozoru před lidmi, neboť vás budou vydávat soudům, budou vás bičovat ve svých synagogách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'dokonce před vladaře a krále vás budou vodit kvůli mně, jim i pohanům na svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'A když vás vydají, nestarejte se, jak nebo co promluvit; neboť v tu hodinu vám bude dáno, co máte promluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Vždyť to nejste vy, kdo mluví, ale ⌈Duch vašeho Otce⌉, jenž mluví ve vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Vydá na smrt bratr bratra a otec dítě, povstanou děti proti rodičům a usmrtí je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'A všichni vás budou nenávidět pro mé jméno. Kdo však vytrvá do konce, bude zachráněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Když vás budou pronásledovat v jednom městě, utečte do jiného; neboť amen, pravím vám, jistě nebudete hotovi s izraelskými městy, než přijde Syn člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, '„Učedník není nad učitele ani otrok nad svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Stačí, aby učedník byl jako jeho učitel a otrok jako jeho pán. Jestliže hospodáře nazvali Belzebulem, tím spíše jeho čeleď!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, '„Nebojte se jich tedy; neboť není nic zahaleného, co nebude zjeveno, a nic skrytého, co nebude poznáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Co vám pravím ve tmě, řekněte na světle; a co slyšíte šeptem do ucha, vyhlaste ze střech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'A nebojte se těch, kdo zabíjejí tělo, ale duši zabít nemohou. Raději se bojte toho, kdo může i duši i tělo zahubit v Gehenně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Neprodávají se dva vrabci za haléř? A ani jeden z nich nespadne na zem bez vůle vašeho Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'I všechny vlasy na vaší hlavě jsou spočteny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Nebojte se tedy; vy jste cennější než mnoho vrabců.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, '„Ke každému, kdo se ke mně přizná před lidmi, se i já přiznám před svým Otcem, který je v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Kdo mě však před lidmi zapře, toho i já zapřu před svým Otcem, který je v nebesích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, '„Nemyslete si, že jsem přišel uvést na zem pokoj; nepřišel jsem uvést pokoj, ale meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Neboť jsem přišel postavit člověka proti jeho otci, dceru proti její matce a snachu proti její tchyni');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'a nepřáteli člověka budou členové jeho domácnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kdo má rád otce nebo matku víc než mne, není mne hoden; a kdo má rád syna nebo dceru víc než mne, není mne hoden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'A kdo jde za mnou a nebere svůj kříž, není mne hoden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kdo nalezne ⌈svou duši⌉, ztratí ji; a kdo ztratí ⌈svou duši⌉ kvůli mně, nalezne ji.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, '„Kdo přijímá vás, přijímá mne; a kdo přijímá mne, přijímá toho, který mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kdo přijímá proroka ⌈proto, že je to prorok⌉, obdrží odměnu proroka; a kdo přijímá spravedlivého ⌈proto, že je to spravedlivý,⌉ obdrží odměnu spravedlivého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'A kdo by jednomu z těchto maličkých dal napít ⌈proto, že je učedník⌉, i kdyby mu dal jen pohár studené [vody], amen, pravím vám, jistě nepřijde o svou odměnu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'A stalo se, když Ježíš dokončil příkazy svým dvanácti učedníkům, že odtamtud odešel, aby učil a kázal v jejich městech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Jan uslyšel ve vězení o Kristových činech, poslal ⌈ vzkaz po svých učednících⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, '⌈a otázal se ho:⌉ „Ty jsi ⌈Ten, který má přijít⌉, nebo máme očekávat jiného?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Ježíš jim odpověděl: „Jděte a oznamte Janovi, co slyšíte a vidíte:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Slepí opět vidí, chromí chodí, malomocní jsou očišťováni, hluší slyší, mrtví vstávají a chudým se zvěstuje evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Blahoslavený je ten, kdo by se nade mnou nepohoršil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Zatímco odcházeli, začal Ježíš říkat zástupům o Janovi: „Co jste vyšli spatřit do pustiny? Třtinu zmítanou větrem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Nebo co jste vyšli uvidět? Člověka oblečeného do jemných [šatů]? Hle, ti, kdo nosí jemné šaty, jsou v ⌈královských palácích⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Ale co jste vyšli uvidět? Proroka? Ano, pravím vám, a více než proroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'To je ten, o němž je napsáno: Hle, já posílám svého posla před tvou tváří, který upraví tvou cestu před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Amen, pravím vám, mezi těmi, kdo se narodili z ženy, nepovstal nikdo větší než Jan Křtitel; avšak ten nejmenší v království Nebes je větší než on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Ode dnů Jana Křtitele až dosud ⌈je království Nebes vystaveno tlaku a ti, kdo se do něho tlačí,⌉ je uchvacují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Neboť všichni Proroci i Zákon prorokovali až do Jana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'A chcete–li to přijmout, on je Eliáš, který má přijít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kdo má uši [k slyšení], ať naslouchá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, '„Ke komu připodobním toto pokolení? Je podobné dětem, které sedí na tržištích a volají na ostatní:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Pískali jsme vám, a vy jste netancovali; naříkali jsme, a vy ⌈jste se nebili v prsa⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Přišel Jan, nejedl a nepil, a říkají: Má démona!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Přišel Syn člověka, jí a pije, a říkají: Hle, člověk žrout a pijan vína, přítel celníků a hříšníků! Ale moudrost je ospravedlněna svými dětmi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Tehdy začal Ježíš kárat města, ve kterých se stalo nejvíc jeho mocných činů, že nečinila pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '„Běda tobě, Chorazin! Běda tobě, Betsaido! Protože kdyby se byly v Týru a Sidónu staly ty mocné činy, které se staly ve vás, dávno by v žíni a popelu učinili pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Ale pravím vám: Týru a Sidónu bude v den soudu snesitelněji než vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'A ty, Kafarnaum, ⌈budeš snad vyvýšeno⌉ až do nebe? Až do podsvětí budeš strženo! Neboť kdyby se v Sodomě staly mocné činy, které se staly v tobě, zůstala by až do dnešního dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Ale pravím vám, že sodomské zemi bude v den soudu snesitelněji nežli tobě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'V ten čas pak Ježíš řekl: „Vzdávám ti chválu, Otče, Pane nebe i země, že jsi skryl tyto věci před moudrými a rozumnými a zjevil jsi je maličkým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ano, Otče, protože tak ⌈se ti zalíbilo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Všechno mi předal můj Otec; a nikdo nezná Syna, jen Otec, ani Otce nikdo nezná, jen Syn a ten, komu by ho Syn chtěl zjevit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Pojďte ke mně všichni, kteří těžce pracujete a jste přetíženi, a já vám dám odpočinek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Vezměte na sebe mé jho a učte se ode mne, neboť jsem tichý a pokorný v srdci; a naleznete odpočinutí svým duším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Vždyť mé jho je příjemné a mé břemeno je lehké.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'V ten čas šel Ježíš v sobotu obilím. Jeho učedníci dostali hlad a začali trhat klasy a jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Když [je] uviděli farizeové, řekli mu: „Hle, tvoji učedníci dělají, co se v sobotu dělat nesmí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'On jim však řekl: „Nečetli jste, co udělal David, když vyhladověl, on i ti, kdo byli s ním?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Jak vešel do Božího domu a jak snědli ⌈chleby předložení⌉, které nesměl jíst ani on ani ti, kdo byli s ním, ale jen kněží?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Anebo nečetli jste v Zákoně, že o sobotách kněží v chrámě porušují sobotu, a přece jsou bez viny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Pravím vám, že zde je někdo větší než chrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Kdybyste věděli, co znamená: Milosrdenství chci, a ne oběť, neodsoudili byste nevinné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Vždyť Syn člověka je pánem soboty.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'A když odtamtud odešel, přišel do jejich synagogy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'A hle, byl tam člověk, který měl odumřelou ruku. I otázali se ho: „Je dovoleno v sobotu uzdravovat?“To proto, aby jej obžalovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'On jim řekl: „⌈Kdyby měl někdo z vás ovci⌉ a ta by mu v sobotu spadla do jámy, což by ji neuchopil a nevytáhl?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Oč je člověk cennější než ovce! Proto je dovoleno v sobotu činit dobře.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Potom tomu člověku řekl: „Natáhni svou ruku.“Natáhl ji, a byla zase v pořádku a zdravá jako ta druhá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Farizeové však vyšli a radili se proti němu, jak by ho zahubili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Ježíš to věděl a odešel odtamtud. A následovaly jej ⌈velké zástupy⌉ a on je všechny uzdravil;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'a přísně jim domluvil, aby ⌈nerozšiřovali pověst o něm⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'To proto, aby se naplnilo, co bylo řečeno skrze proroka Izaiáše:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Hle, můj služebník, kterého jsem si vyvolil, můj milovaný, kterého si oblíbila má duše. Vložím na něho svého Ducha a ohlásí soud národům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Nebude se přít ani křičet, na ulicích nikdo neuslyší jeho hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Nalomený rákos nedolomí a doutnající knot neuhasí, dokud nepřivede právo k vítězství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'A v jeho jméno budou národy skládat naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Tehdy k němu přivedli démonizovaného, který byl slepý a němý. Uzdravil ho, takže ten němý [a slepý] mluvil a viděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'A všechny zástupy byly ohromeny a říkaly: „Snad to není ten Syn Davidův?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Když to uslyšeli farizeové, řekli: „Ten člověk vyhání démony jen ⌈v moci ⌉ Belzebula, vládce démonů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, '[Ježíš] však znal jejich myšlenky a řekl jim: „Každé království samo proti sobě rozdělené pustne a žádné město nebo dům sám proti sobě rozdělený neobstojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'A vyhání–li Satan Satana, rozdělil se sám proti sobě. Jak tedy obstojí jeho království?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'A vyháním–li já démony ⌈v moci ⌉ Belzebula, v čí moci je vyhánějí vaši synové? Proto oni budou vašimi soudci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Jestliže však já vyháním démony ⌈v moci ⌉ Ducha Božího, pak už k vám přišlo Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Nebo jak může někdo vejít do domu siláka a uloupit jeho majetek, jestliže siláka nejdříve nespoutá? A teprve pak vyloupí jeho dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kdo není se mnou, je proti mně, a kdo neshromažďuje se mnou, rozptyluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Proto vám pravím: Každý hřích i rouhání bude lidem odpuštěno, ale rouhání proti Duchu odpuštěno nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'A tomu, kdo by řekl slovo proti Synu člověka, bude odpuštěno; ale tomu, kdo by promluvil proti Duchu Svatému, nebude odpuštěno ani v tomto věku, ani v budoucím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, '„Vypěstujte krásný strom, a jeho ovoce bude krásné, nebo vypěstujte špatný strom, a jeho ovoce bude špatné. Vždyť strom se pozná podle ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Plemeno zmijí, jak můžete mluvit dobré věci, když jste zlí? Vždyť ústa mluví z přebytku srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Dobrý člověk z dobrého pokladu vynáší dobré, a zlý člověk ze zlého pokladu vynáší zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Pravím vám, že z každého neužitečného výroku, který lidé promluví, vydají počet v den soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Neboť podle svých slov budeš ospravedlněn a podle svých slov odsouzen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Tehdy mu někteří z učitelů Zákona a farizeů řekli: „Učiteli, chceme od tebe uvidět znamení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'On jim však odpověděl: „Pokolení zlé a cizoložné vyhledává znamení, ale znamení mu nebude dáno, kromě znamení proroka Jonáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Vždyť jako byl Jonáš v břiše velké ryby tři dny a tři noci, tak bude Syn člověka tři dny a tři noci v srdci země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Ninivští muži povstanou na soudu s tímto pokolením a odsoudí je, neboť učinili pokání na Jonášovo kázání-- a hle, zde je někdo většínež Jonáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Královna jihu po vstane na soudu s tímto pokolením a odsoudí je, protože přišla od končin země, aby uslyšela Šalomounovu moudrost -- a hle, zde je někdo větší než Šalomoun.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, '„Když pak nečistý duch vyjde od člověka, prochází bezvodými místy, hledaje odpočinutí, ale nenalézá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Tehdy si říká: Vrátím se do svého domu, odkud jsem vyšel. A když přijde, nalézá dům prázdný, zametený a vyzdobený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Potom jde a vezme s sebou sedm jiných duchů, horších, než je sám; vejdou a bydlí tam. A poslední věci onoho člověka se stávají horšími než ty první. Tak bude i s tímto zlým pokolením.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Když ještě mluvil k zástupům, hle, venku stáli jeho matka a bratři a chtěli s ním mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, '[Kdosi mu řekl: „Hle, tvá matka a tvoji bratři stojí venku a chtějí s tebou mluvit.“]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'On však tomu, kdo mu to říkal, odpověděl: „Kdo je má matka a kdo jsou moji bratři?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, '⌈Ukázal rukou⌉ na své učedníky a řekl: „Hle, má matka a moji bratři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Neboť každý, kdo činí vůli mého Otce v nebesích, to je můj bratr, má sestra i matka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Toho dne vyšel Ježíš z domu a sedl si u moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'I shromáždily se k němu velké zástupy. Proto vstoupil na loď a posadil se. Celý ten zástup stál na břehu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'A pověděl jim mnoho v podobenstvích: „Hle, vyšel rozsévač, ⌈aby rozséval⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'A jak rozséval, padla některá zrna podél cesty; i přiletěli ptáci a sezobali je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Jiná padla na skalnatá místa, kde neměla mnoho země, a hned vzešla, protože neměla hlubokou zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Když vyšlo slunce, spálilo je; a protože neměla kořen, uschla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Jiná padla do trní; a trní vzešlo a udusilo je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Jiná padla do dobré země a vydávala úrodu, některá sto násobnou, jiná šedesát inásobnou, jiná třicet inásobnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kdo má uši [k slyšení], ať poslouchá!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Tu přistoupili učedníci a řekli mu: „Proč k nim mluvíš v podobenstvích?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'On jim odpověděl: „Vám je dáno poznat tajemství království Nebes, ale jim to dáno není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Neboť kdo má, tomu bude dáno a bude mít nadbytek; avšak tomu, kdo nemá, bude odňato i to, co má.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Proto k nim mluvím v podobenstvích, protože hledíce nevidí a naslouchajíce neslyší ani nechápou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Naplňuje se na nich Izaiášovo proroctví, které říká: Vskutku budete slyšet, a jistě nepochopíte, budete ustavičně hledět, a určitě neuvidíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Neboť srdce tohoto lidu ztučnělo, ušima začali slyšet ztěžka a své oči zavřeli, aby očima neuviděli a ušima neuslyšeli, srdcem nepochopili a neobrátili se, a já je neuzdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Blahoslavené jsou vaše oči, že vidí, a vaše uši, že slyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Amen, pravím vám, že mnozí proroci a spravedliví toužili spatřit, co vidíte vy, ale nespatřili, a slyšet, co vy slyšíte, ale neslyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Vy tedy poslyšte ⌈podobenství o rozsévači⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Ke každému, kdo slyší slovo o království a nerozumí, přichází ten Zlý a uchvacuje to, co bylo zaseto v jeho srdci; to je ten, který byl zaset podél cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Zasetý na skalnatá místa, to je ten, kdo Slovo slyší a hned je s radostí přijímá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'nemá však v sobě kořen, ale je nestálý. Když pak nastane soužení nebo pronásledování pro Slovo, ihned odpadá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Zasetý do trní, to je ten, kdo Slovo slyší, ale starost [tohoto] věku a svod bohatství Slovo dusí, a tak se stává neplodným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Zasetý na dobrou půdu, to je ten, kdo Slovo slyší a rozumí mu; ten pak nese úrodu, jeden sto násobnou, druhý šedesát inásobnou, jiný třicet inásobnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Předložil jim jiné podobenství: „Království Nebes ⌈je podobné⌉ člověku, který na svém poli zasel dobré semeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Zatímco lidé spali, přišel jeho nepřítel, rozesel mezi pšenici plevel a odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Když pak osení vyrostlo a ⌈nasadilo na klas⌉, ukázal se i plevel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Přišli otroci toho hospodáře a řekli mu: Pane, cožpak jsi nezasel na svém poli dobré semeno? Odkud ⌈se tedy vzal⌉ plevel?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'On jim odpověděl: Nepřítel člověk to udělal. A otroci mu řekli: Chceš tedy, abychom šli a posbírali jej?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'On však řekl: Ne, abyste snad při sbírání plevele nevytrhli z kořenů spolu s ním i pšenici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Nechte, ať obojí roste spolu až do žně; a v čas žně řeknu žencům: Nejprve posbírejte plevel a svažte ho do otýpek, abyste jej zcela spálili, ale pšenici shromážděte do mé stodoly. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Předložil jim jiné podobenství: „Království Nebes je podobné zrnu hořčice, které člověk vzal a zasel na svém poli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Je sice menší než všecka semena, ale když vyroste, je větší než ostatní zahradní byliny a ⌈je z něho⌉ strom, takže přilétají nebeští ptáci a hnízdí v jeho větvích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Pověděl jim jiné podobenství: „Království Nebes je podobné kvasu, který žena vzala a skryla do tří měřic mouky, dokud to všecko nezkvasilo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'To všechno mluvil Ježíš k zástupům v podobenstvích a bez podobenství k nim [vůbec] nemluvil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'aby se naplnilo,co bylo řečeno skrze proroka [Izaiáše]: Otevřu svá ústa v podobenstvích, vypovím, co bylo skryté od založení [světa].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Potom opustil [Ježíš] zástupy a vešel do domu. I přistoupili k němu jeho učedníci a řekli: „Vylož nám to podobenství o plevelu na poli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'On [jim] odpověděl: „Rozsévač dobrého semena je Syn člověka');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'a pole je svět. Dobré semeno, to jsou synové království, plevel jsou synové toho Zlého;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'nepřítel, který je zasel, je Ďábel. Žeň je skonání věku a ženci jsou andělé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Jako se tedy sbírá plevel a ⌈pálí se v ohni⌉, tak bude při skonání [tohoto] věku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Syn člověka pošle své anděly, i seberou z jeho království všechna pohoršení a ty, kdo činí nepravost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'a hodí je do ohnivé pece; tam bude pláč a skřípění zubů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Tehdy se spravedliví rozzáří jako slunce v království svého Otce. Kdo má uši [k slyšení], ať poslouchá!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, '„Království Nebes je podobné pokladu skrytému v poli, který člověk nalezl a skryl; a z radosti nad ním jde a prodává všechno, co má, a kupuje ono pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Království Nebes je dále podobné člověku kupci, hledajícímu krásné perly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Když našel jednu drahocennou perlu, odešel a prodal vše, co měl, a koupil ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Dále je království Nebes podobné síti, která byla spuštěna do moře a shromáždila všechny druhy ryb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Když se naplnila, vytáhli ji na břeh, posadili se, dobré sebrali do nádob a špatné vyhodili ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Tak tomu bude při skonání věku: Vyjdou andělé, oddělí zlé zprostředka spravedlivých');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'a hodí je do ohnivé pece; tam bude pláč a skřípění zubů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, '[Ježíš jim řekl:] „Rozuměli jste tomu všemu?“Řekli mu: „Ano, [Pane].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'On jim řekl: „Proto se každý učitel Zákona, ⌈který se stal učedníkem⌉ království Nebes, podobá člověku hospodáři, který ze svého pokladu vynáší nové i staré.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Když Ježíš dokončil tato podobenství, odešel odtamtud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Přišel do svého domovského města a učil je v jejich synagoze, takže ohromeni říkali: „Odkud se u něj vzala taková moudrost a mocné činy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Není to ten syn tesařův? Nejmenuje se jeho matka Marie a jeho bratři Jakub, Josef, Šimon a Juda?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'A nejsou všechny jeho sestry u nás? Odkud tedy má toto všechno?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'A pohoršovali se nad ním. Ale Ježíš jim řekl: „Prorok není beze cti, leda ve [své] vlasti a ve svém domě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'A pro jejich nevěru tam neučinil mnoho mocných činů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'V ten čas uslyšel tetrarcha Herodes pověst o Ježíšovi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'a řekl svým sluhům: „To je Jan Křtitel. Vstal z mrtvých, a proto v něm působí ty to moci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Herodes se totiž zmocnil Jana, spoutal [ho] a uvrhl do vězení kvůli Herodiadě, ženě svého bratra Filipa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'neboť Jan mu říkal: „Není ti dovoleno ji mít.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Herodes ho chtěl zabít, ale bál se lidu, protože ho pokládali za proroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, '⌈Když však nastal den Herodových narozenin⌉, zatančila dcera té Herodiady mezi hosty, a zalíbila se Herodovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'takže jí s přísahou slíbil dát, o cokoli požádá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Ona pak, navedena svou matkou, řekla: „Dej mi zde na míse hlavu Jana Křtitele.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Král se zarmoutil, ale kvůli těm přísahám a spolustolovníkům poručil, aby [jí] byla dána;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'dal tedy Jana ve vězení stít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Jeho hlavu přinesli na míse a dali ji té dívce a ta ji donesla své matce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'I přišli jeho učedníci, vzali tělo a pohřbili je; pak šli a oznámili to Ježíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Jakmile to Ježíš uslyšel, odplul odtamtud v lodi do ústraní na opuštěné místo; ale zástupy o tom uslyšely a vydaly se z měst pěšky za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Když vystoupil, uviděl veliký zástup, byl nad nimi hluboce pohnut a uzdravil jejich nemocné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'A když nastal večer, přistoupili k němu učedníci a řekli: „Toto místo je opuštěné a hodina již pokročila; propusť zástupy, ať odejdou do vesnic a nakoupí si jídlo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, '[Ježíš] jim řekl: „Nemusejí odejít; vy jim dejte najíst!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Oni mu řekli: „Nemáme zde než pět chlebů a dvě ryby.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'On však řekl: „Přineste mi je sem!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'A poručil zástupům, aby se rozložily na trávě, vzal těch pět chlebů a dvě ryby, vzhlédl k nebi, požehnal, rozlámal chleby a dal je učedníkům a učedníci zástupům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Všichni jedli a nasytili se. A sebrali dvanáct plných nůší zbylých úlomků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Těch, kdo jedli, bylo asi pět tisíc mužů, kromě žen a dětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'A Ježíš hned přinutil [své] učedníky, aby nastoupili do lodi a jeli před ním na druhou stranu, než on propustí zástupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'A když zástupy propustil, vystoupil na horu, aby se o samotě pomodlil. Když nastal večer, byl tam sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Loď již byla ⌈od země vzdálena mnoho stadií⌉, zmítána vlnami, protože vítr vál proti ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'O čtvrté noční hlídce šel [Ježíš] k nim, kráčeje po moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Když ho učedníci uviděli kráčet po moři, vyděsili se a řekli: „ To je přízrak!“A strachem vykřikli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, '[Ježíš] na ně hned promluvil: „Vzchopte se, já jsem to, nebojte se!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Petr mu odpověděl: „Pane, jsi–li to ty, poruč mi, ať přijdu k tobě po vodě!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'On řekl: „Pojď!“Petr vystoupil z lodi, kráčel po vodě a přišel k Ježíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Ale když viděl [silný] vítr, dostal strach. ⌈Začal tonout⌉ a vykřikl: „Pane, zachraň mě!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Ježíš hned vztáhl ruku, zachytil ho a řekl mu: „Malověrný, proč jsi zapochyboval?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'A když vstoupili na loď, vítr přestal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Ti, kdo byli v lodi, se mu poklonili a řekli: „Opravdu jsi Boží Syn.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Přeplavili se a dorazili k zemi u Genezaretu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Jakmile ho muži z toho místa poznali, poslali zprávu do celého okolí. Přinesli k němu všechny nemocné');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'a prosili ho, aby se směli jen dotknout třásní jeho šatu; a všichni, kdo se dotkli, byli uzdraveni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Tehdy přišli k Ježíšovi z Jeruzaléma farizeové a učitelé Zákona a řekli:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '„Proč tvoji učedníci přestupují tradici starších? Vždyť si neomývají [své] ruce, když jedí chléb.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'On jim odpověděl: „Proč i vy přestupujete Boží příkaz kvůli své tradici?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Vždyť Bůh řekl: Cti otce a matku a kdo zlořečí otci nebo matce, ať zemře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Vy však říkáte: Kdo by řekl otci nebo matce: To z mého majetku, co by ti mohlo pomoci, je dar určený Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'ten již není povinen uctít svého otce [nebo svou matku]. Zrušili jste Boží slovo pro svou tradici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Pokrytci! Dobře o vás prorokoval Izaiáš, když říkal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '⌈Tento lid mne ctí rty⌉, ale jejich srdce je ode mne velmi daleko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Marně mne však uctívají, vyučujíce nauky, jež jsou jen lidskými příkazy. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Zavolal k sobě zástup a řekl: „Slyšte a rozumějte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Člověka neznečišťuje to, co vchází do úst, nýbrž člověka znečišťuje to, co z úst vychází.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Tu k němu přistoupili [jeho] učedníci a řekli mu: „Víš, že se farizeové pohoršili, když to slovo uslyšeli?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'On odpověděl: „Každá rostlina, kterou nezasadil můj nebeský Otec, bude vykořeněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Nechte je! Slepí jsou vůdci [slepých]. Jestliže slepý vede slepého, oba spadnou do jámy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Petr mu ⌈na to⌉ řekl: „Vylož nám [toto] podobenství!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, '[Ježíš] řekl: „I vy jste ještě nechápaví?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Nerozumíte, že všechno, co vchází do úst, jde do břicha a vypouští se do záchodu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Co však z úst vychází, vystupuje ze srdce, a to znečišťuje člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Neboť ze srdce vycházejí špatné myšlenky, vraždy, cizoložství, smilstva, krádeže, lživá svědectví, urážky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'To jsou věci, které člověka znečišťují; ale jíst neomytýma rukama člověka neznečišťuje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Ježíš odtamtud vyšel a odebral se do končin Týru a Sidónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'A hle, z těch končin vyšla nějaká kananejská žena a křičela: „Smiluj se nade mnou, Pane, Synu Davidův! Mou dceru zle ⌈trápí démon⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Ale on jí neodpověděl ani slovo. I přistoupili k němu jeho učedníci a prosili ho: „⌈Pošli ji pryč⌉, vždyť za námi křičí!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'On řekl: „⌈Byl jsem poslán jen⌉ ke ztraceným ovcím z domu Izraele.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Ona však přišla, ⌈klaněla se mu⌉ a říkala: „Pane, pomoz mi!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'On odpověděl: „Není správné vzít chléb dětem a hodit jej psům.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Ona řekla: „Ano, Pane, ale vždyť i psi jedí z drobtů, které padají se stolu jejich pánů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Tehdy jí Ježíš odpověděl: „Ó ženo, tvá víra je veliká. Staň se ti, jak chceš.“A od té hodiny byla její dcera uzdravena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'A přecházeje odtamtud, prošel Ježíš kolem Galilejského moře, vystoupil na horu a posadil se tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Tu k němu přišly veliké zástupy, které měly s sebou chromé, slepé, zmrzačené, němé a mnohé jiné. Položili mu je k nohám a on je uzdravil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'takže zástup užasl, když viděl, že němí mluví, zmrzačení jsou zdraví, chromí chodí a slepí vidí; i vzdali chválu ⌈Bohu Izraele⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Ježíš si pak zavolal své učedníky a řekl: „Jsem hluboce pohnut nad tím zástupem, protože již tři dny zůstávají se mnou a nemají co jíst. A nechci je propustit hladové, aby nezemdleli na cestě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'A učedníci mu řekli: „Kde vezmeme v pustině tolik chlebů, abychom nasytili takový zástup?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Ježíš jim řekl: „Kolik máte chlebů?“Oni řekli: „Sedm a několik rybiček.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Nařídil zástupu posadit se na zem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'vzal těch sedm chlebů a ty ryby, vzdal díky, rozlámal a dával učedníkům a učedníci zástupům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Všichni pojedli a nasytili se; a sebrali sedm plných košů zbylých úlomků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Těch, kteří jedli, bylo čtyři tisíce mužů kromě žen a dětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Potom zástupy propustil, vstoupil na loď a připlul na území Magadan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'I přistoupili k němu farizeové a saduceové a zkoušeli ho; chtěli, aby jim ukázal znamení z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'On jim však odpověděl: „[Když nastane večer, říkáte: Bude pěkně, neboť se nebe červená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'A ráno: Dnes bude bouřka, neboť se červená zamračené nebe. Vzhled nebe tedy rozeznávat umíte, a znamení časů nikoli?]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Pokolení zlé a cizoložné vyhledává znamení, ale znamení mu nebude dáno, kromě znamení [proroka] Jonáše.“A zanechal je tam a odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, '[Jeho] učedníci přišli na druhou stranu a zapomněli vzít chleby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Ježíš jim pověděl: „Dávejte si pozor a varujte se kvasu farizeů a saduceů!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Oni se pak mezi sebou dohadovali a říkali: „ To proto, že jsme nevzali chleby.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Ježíš to poznal a řekl: „Proč se mezi sebou dohadujete, malověrní, že nemáte chleby?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ještě nerozumíte? Ani se nepamatujete na těch pět chlebů pro pět tisíc, a kolik nůší jste nasbírali?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Ani na těch sedm chlebů pro čtyři tisíce, a kolik košů jste nasbírali?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Jak to, že nerozumíte, že jsem k vám nemluvil o chlebech? Varujte se kvasu farizeů a saduceů!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Tehdy pochopili, že neřekl, aby se varovali chlebového kvasu, nýbrž učení farizeů a saduceů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Když Ježíš přišel do oblasti Cesareje Filipovy, ptal se svých učedníků: „Za koho lidé pokládají Syna člověka?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Oni řekli: „Ti za Jana Křtitele, jiní za Eliáše, jiní za Jeremjáše nebo za jednoho z proroků.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Řekl jim: „A za koho mě pokládáte vy?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Šimon Petr odpověděl: „Ty jsi Mesiáš, Syn živého Boha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Ježíš mu ⌈na to⌉ řekl: „Blahoslavený jsi, Šimone Bar–Jona, protože ti to nezjevilo tělo a krev, ale můj Otec, který je v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'A já ti pravím, že ty jsi Petr, a na té skále vybuduji svou církev a brány podsvětí ji nepřemohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, '[A] tobě dám klíče království Nebes, a cokoli svážeš na zemi, bude již svázáno v nebesích, a cokoli rozvážeš na zemi, bude již rozvázáno v nebesích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Tehdy přísně domluvil [svým] učedníkům, aby nikomu neřekli, že on je Mesiáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Od té doby Ježíš začal svým učedníkům ukazovat, že musí odejít do Jeruzaléma a mnoho vytrpět od starších, velekněží a učitelů Zákona, být zabit a třetího dne ⌈být vzkříšen⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Petr si ho vzal stranou a začal ho kárat: „ Bůh tě chraň, Pane, to se ti určitě nestane!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Ale on se otočil a řekl Petrovi: „Jdi ode mne, satane! Jsi mi kamenem úrazu, protože nemáš na mysli věci Boží, ale věci lidské.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Tehdy Ježíš řekl svým učedníkům: „Chce–li kdo jít za mnou, ať zapře sám sebe, vezme svůj kříž a následuje mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Neboť kdo by chtěl svou duši zachránit, zahubí ji; kdo by však svou duši zahubil kvůli mně, nalezne ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Vždyť co člověku prospěje, získá–li celý svět, ale uškodí své duši? Anebo co dá člověk výměnou za svou duši?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Syn člověka má přijít v slávě svého Otce se svými anděly, a tehdy odplatí každému podle jeho jednání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Amen, pravím vám, [že] někteří z těch, kdo zde stojí, určitě neokusí smrti, dokud nespatří Syna člověka přicházejícího ve ⌈své královské moci⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Po šesti dnech vzal Ježíš s sebou Petra, Jakuba a jeho bratra Jana a vyvedl je na vysokou horu, kde byli sami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'A byl před nimi proměněn. Jeho tvář zazářila jako slunce a jeho šaty zbělely jako světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'A hle, ukázal se jim Mojžíš a Eliáš a rozmlouvali s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Petr ⌈na to⌉ Ježíšovi řekl: „Pane, je pro nás dobré tu být. Chceš–li, udělám tu tři stánky, tobě jeden, Mojžíšovi jeden a Eliášovi jeden.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Když ještě mluvil, hle, zastínil je zářivý oblak a z oblaku se ozval hlas: „Toto je můj milovaný Syn, v němž jsem nalezl zalíbení; toho poslouchejte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Když to učedníci uslyšeli, padli na tvář a velmi se báli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Ježíš k nim přistoupil, dotkl se jich a řekl: „Vstaňte a nebojte se.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Když pozvedli oči, neviděli nikoho, jen samotného Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'A když sestupovali z hory, Ježíš jim přikázal: „Nikomu o tom vidění neříkejte, dokud Syn člověka nebude vzkříšen z mrtvých.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, '[Jeho] učedníci se ho zeptali: „Jak to, že učitelé Zákona říkají, že nejprve musí přijít Eliáš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'On odpověděl: „Eliáš opravdu přichází a všechno obnoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Avšak pravím vám: Eliáš již přišel, a nepoznali ho, ale udělali s ním, co chtěli; tak bude od nich trpět i Syn člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Tehdy učedníci pochopili, že jim to řekl o Janu Křtiteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Když přišli k zástupu, přistoupil k němu jeden člověk a padl před ním na kolena');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'řka: „Pane, smiluj se nad mým synem, neboť je náměsíčný a ⌈zle trpí⌉; často totiž padá do ohně a často do vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'A přivedl jsem ho k tvým učedníkům, ale nemohli ho uzdravit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Ježíš odpověděl: „Ach, pokolení nevěřící a zvrácené, jak dlouho ještě budu s vámi? Jak dlouho vás mám snášet? Při veďte ho sem ke mně!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Ježíš mu pohrozil a démon od něho vyšel; a od té hodiny byl chlapec uzdraven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'V soukromí potom k Ježíšovi přistoupili učedníci a řekli: „Proč jsme ho nemohli vyhnat my?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'On jim řekl: „Pro vaši malověrnost! Amen, pravím vám, budete–li mít víru jako zrno hořčice, řeknete této hoře: Přejdi odtud tam, a přejde; a nic vám nebude nemožné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, '[Tento rod nevychází jinak než v modlitbě a půstu.] “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Když se zdržovali v Galileji, řekl jim Ježíš: „Syn člověka má být vydán do rukou lidí;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'zabijí ho, ale třetí den ⌈bude vzkříšen⌉.“A oni se velmi zarmoutili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Když přišli do Kafarnaum, přistoupili k Petrovi výběrčí dvojdrachem a řekli: „Copak váš Učitel neplatí dvojdrachmu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Řekl: „ Ale ano.“Jakmile vešel do domu, Ježíš ho předešel otázkou: „Co myslíš, Šimone? Od koho vybírají králové země poplatky a daň? Od svých synů, nebo od cizích?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Když [Petr] řekl: „Od cizích“, pověděl mu Ježíš: „Synové jsou tedy svobodni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Abychom je však nepohoršili, jdi k moři, hoď udici a vytáhni první rybu, která se vynoří. Až otevřeš její ústa, nalezneš statér; ten vezmi a dej jim za mne i za sebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'V tu hodinu přistoupili učedníci k Ježíšovi a říkali: „Kdo je tedy v království Nebes největší?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, '[Ježíš] přivolal dítě, postavil je doprostřed nich');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'a řekl: „Amen, pravím vám: Neobrátíte–li se a nebudete–li jako děti, jistě nevejdete do království Nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Kdo se tedy pokoří jako toto dítě, ten bude největší v království Nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'A kdo přijme jedno takové dítě na základě mého jména, mne přijímá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, '„Kdo by však ⌈svedl k hříchu ⌉ jednoho z těchto maličkých, kteří věří ve mne, pro toho by bylo lépe, aby mu na krk pověsili velký mlýnský kámen a potopili ho do mořské hlubiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Běda světu pro svody! Svody sice musí přijít, avšak běda tomu člověku, skrze kterého svod přichází!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Jestliže tě tvá ruka nebo tvá noha ⌈svádí k hříchu ⌉, utni ji a odhoď; lépe je pro tebe, abys vešel do života zmrzačený nebo chromý, než abys měl obě ruce nebo obě nohy, a byl uvržen do věčného ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'A jestliže tě svádí tvé oko, vyjmi je a odhoď; lépe je pro tebe, abys vešel do života jednooký, než abys měl obě oči, a byl uvržen do ohnivé Gehenny.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, '„Dávejte si pozor, abyste nepohrdli ani jedním z těchto maličkých. Neboť vám pravím, že jejich andělé v nebesích stále hledí na tvář mého Otce, který je v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, '[Vždyť Syn člověka přišel zachránit, co zahynulo.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Co myslíte? Kdyby nějaký člověk měl sto ovcí a jedna z nich by zabloudila, nenechá těch devadesát devět na horách a nevydá se hledat tu, která bloudí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'A stane–li se, že ji nalezne, amen, pravím vám, že se z ní raduje víc než z těch devadesáti devíti, které nezabloudily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Právě tak není vůle ⌈vašeho Otce⌉, který je v nebesích, aby zahynul jediný z těchto maličkých.“...');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, '„Jestliže tvůj bratr [proti tobě] zhřeší, jdi a pokárej ho ⌈mezi čtyřma očima⌉. Poslechne–li tě, získal jsi svého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Jestliže by však neposlechl, vezmi s sebou ještě jednoho nebo dva, aby ústy dvou nebo tří svědků byl potvrzen každý výrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Jestliže by je neposlechl, pověz to shromáždění, a jestliže by neposlechl ani shromáždění, ať je ti jako pohan a celník.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, '„Amen, pravím vám, cokoli svážete na zemi, bude již svázáno v nebi, a cokoli rozvážete na zemi, bude již rozvázáno v nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, '[Amen,] opět vám pravím: Shodnou–lise dva z vás na zemi v jakékoli věci, o niž požádají, stane se jim od mého Otce, který je v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Neboť kde jsou dva nebo tři shromážděni ⌈v mé jméno⌉, tam jsem já uprostřed nich.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Tehdy přistoupil ⌈Petr a řekl mu⌉: „Pane, kolikrát mám odpustit svému bratru, když proti mně zhřeší? Až sedmkrát?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Ježíš mu řekl: „Pravím ti, ne sedmkrát, ale až sedmdesátkrát sedm krát.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, '„Proto je království Nebes podobné králi, který chtěl provést vyúčtování se svými otroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Když začal účtovat, přivedli mu jednoho, který mu dlužil deset tisíc talentů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Protože však neměl čím zaplatit, rozkázal ho [jeho] pán prodat i se ženou a dětmi i se vším, co má, aby tak splatil svůj dluh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, '[Onen] otrok padl na zem, klaněl se mu a říkal: Měj se mnou trpělivost, [pane,] a všechno ti vrátím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'I slitoval se pán onoho otroka, propustil ho a dluh mu odpustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Ale když onen otrok vyšel, nalezl jednoho ze svých spoluotroků, který mu byl dlužen sto denárů; popadl ho a začal ho škrtit, říkaje: Zaplať, co [mi] dlužíš!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Jeho spoluotrok padl [k jeho nohám] a prosil ho: Měj se mnou trpělivost, a zaplatím ti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'On však nechtěl, ale šel a uvrhl ho do vězení, dokud nezaplatí dluh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Když jeho spoluotroci uviděli, co se přihodilo, velmi se zarmoutili; šli a oznámili svému pánu všechno, co se stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Tehdy si ho jeho pán zavolal a řekl mu: Otroku zlý, celý ten dluh jsem ti odpustil, protože jsi mě poprosil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Neměl ses také ty smilovat nad svým spoluotrokem, jako jsem se i já smiloval nad tebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'A jeho pán se rozhněval a předal ho mučitelům, dokud [mu] nezaplatí celý dluh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Tak i můj nebeský Otec učiní vám, jestliže ze srdce neodpustíte každý svému bratru [jeho přestoupení].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'A stalo se, že když Ježíš dokončil tato slova, odebral se z Galileje a přišel na území Judska za Jordán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Šly za ním velké zástupya on je tam uzdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Přistoupili k němu farizeové, aby ho pokoušeli. Říkali: „Je dovoleno, aby [člověk] propustil svou ženu z jakéhokoli důvodu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'On [jim] odpověděl: „Nečetli jste, že ten, který stvořil člověka, od počátku učinil je jako muže a ženu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'A řekl: Proto člověk opustí otce i matku a přilne ke své ženě a ti dva budou jedno tělo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'takže již nejsou dva, ale jedno tělo. Co tedy Bůh spojil, ať člověk neodděluje!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Řekli mu: „Proč tedy Mojžíš nařídil dát ženě rozlukový list a propustit [ji]?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Řekl jim: „Pro tvrdost vašeho srdce vám Mojžíš dovolil propouštět vaše ženy, od počátku však tomu tak nebylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Pravím vám, že kdo by propustil svou ženu, ⌈ pokud by to ne bylo na základě⌉ smilstva, a oženil se s jinou, cizoloží; [a kdo by se s propuštěnou oženil, cizoloží].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, '[Jeho] učedníci mu řekli: „Jestliže je to mezi mužem a ženou takové, je lépe se neženit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'On jim řekl: „Ne všichni chápou [toto] slovo, ale jen ti, kterým je to dáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Jsou totiž eunuchové, kteří se už takto narodili z matčina lůna; a jsou eunuchové, které učinili eunuchy lidé; a jsou eunuchové, kteří se sami stali eunuchy pro království Nebes. Kdo může chápat, chápej.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Tehdy k němu přinesli děti, aby na ně vložil ruce a pomodlil se; ale učedníci je pokárali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Ježíš však řekl: „Nechte děti a nebraňte jim přijít ke mně, neboť takovým patří království Nebes.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'A vložil na ně ruce a šel odtamtud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'A hle, přistoupil k němu jeden člověk a řekl: „Učiteli, co dobrého ⌈mám učinit⌉, abych obdržel věčný život?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'On mu řekl: „⌈Proč se mě ptáš na dobré? Jeden je dobrý [: Bůh] ⌉. Chceš–li vstoupit do života, zachovej přikázání!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Řekl mu: „Která?“Ježíš řekl: „Nezavraždíš, nezcizoložíš, neukradneš, nevydáš křivé svědectví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'cti otce a matku, budeš milovat svého bližního jako sebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Mladík mu řekl: „To všechno zachovávám [od svého mládí]. Co mi ještě schází?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Ježíš mu řekl: „Chceš–li být dokonalý, jdi, prodej svůj majeteka dej chudým, a budeš mít poklad v nebesích; pak přijď a následuj mne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Když mladík uslyšel [toto] slovo, odešel zarmoucen, neboť měl mnoho majetku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Ježíš řekl svým učedníkům: „Amen, pravím vám, že bohatý do království Nebes vejde těžko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Opět vám pravím, je snadnější, aby velbloud prošel uchem jehly, než aby bohatý vešel do Božího království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Když to učedníci uslyšeli, byli velice ohromeni a říkali: „Kdo tedy může být zachráněn?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Ježíš na ně pohleděl a řekl jim: „U lidí je to nemožné, ale u Boha je možné všechno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, '⌈Na to⌉ mu řekl Petr: „Hle, my jsme opustili všechno a vydali se za tebou. Co tedy budeme mít?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Ježíš jim řekl: „Amen, pravím vám, ⌈až se Syn člověka při obnovení všech věcí posadí na trůn své slávy, usednete také vy, kteří jste mne následovali,⌉ na dvanáct trůnů a budete soudit dvanáct kmenů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'A každý, kdo opustil domy nebo bratry nebo sestry nebo otce nebo matku [nebo ženu] nebo děti nebo pole pro mé jméno, vezme stokrát víc a získá věčný život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Mnozí první budou poslední a poslední první.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '„Neboť království Nebes je podobné hospodáři, který časně zrána vyšel najmout dělníky na svou vinici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Smluvil s dělníky denár na den a poslal je na vinici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'A když vyšel kolem deváté hodiny, spatřil jiné, jak stojí nečinně na tržišti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'a řekl jim: Jděte i vy na vinici a dám vám, co bude spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Oni šli. Opět vyšel kolem ⌈dvanácté a třetí hodiny⌉ odpoledne a učinil stejně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Vyšel kolem páté hodiny a našel jiné, jak tam stojí, a řekl jim: Proč tu stojíte celý den nečinně?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Řekli mu: Protože nás nikdo nenajal. Řekl jim: Jděte i vy na [mou] vinici [a dostanete, co bude spravedlivé].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Když nastal večer,řekl pán vinice svému správci: Zavolej dělníky a vyplať jim mzdu, počna od posledních až k prvním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Přišli ti, kteří byli najati okolo páté hodiny, a každý dostal denár.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Když přišli ti první, myslili, že dostanou víc; ale i oni dostali po denáru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, '⌈Vzali si jej, ale reptali⌉ proti hospodáři:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Tito poslední dělali jedinou hodinu a postavil jsi je na roveň nám, kteří jsme nesli tíhu dne a vedro!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'On však jednomu z nich odpověděl: Příteli, nekřivdím ti! Nesmluvil jsi se mnou denár za den?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Vezmi, co ti patří, a odejdi! Chci i tomu poslednímu dát jako tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Nemám [snad] právo udělat si ve svých záležitostech, co chci? Anebo závidíš, že já jsem dobrý?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Tak budou poslední první a první poslední. [Neboť je mnoho pozvaných, ale málo vybraných.] “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Když Ježíš vystupoval do Jeruzaléma, vzal si stranou dvanáct [učedníků] a cestou jim řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '„Hle, vystupujeme do Jeruzaléma a Syn člověka bude vydán velekněžím a učitelům Zákona. Odsoudí ho k smrti');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'a vydají pohanům, aby se mu vysmáli, zbičovali ho a ukřižovali; a třetího dne bude vzkříšen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Tehdy k němu přistoupila matka synů Zebedeových se svými syny, klaněla se mu a o něco ho žádala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'On jí řekl: „Co chceš?“Řekla mu: „Ustanov, aby ve tvém království tito dva moji synové usedli jeden po tvé pravici a druhý po tvé levici.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Ježíš odpověděl: „Nevíte, co žádáte. Můžete pít kalich, který mám pít já?“Řekli mu: „Můžeme.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Řekl jim: „Můj kalich sice pít budete, ale není mou věcí, abych dal někomu usednout po mé pravici a po mé levici, neboť tam usednou ti, pro které je to připraveno od mého Otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Když to uslyšelo těch deset, rozhořčili se na ty dva bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Ježíš si je zavolal a řekl: „Víte, že vládci národů panují nad nimi a velcí nad nimi ⌈vykonávají svou svrchovanou moc⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Mezi vámi tomu tak nebude; ale kdo by se chtěl mezi vámi stát velkým, bude vaším služebníkem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'a kdo by chtěl být mezi vámi první, bude vaším otrokem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Stejně jako Syn člověka nepřišel, aby si nechal posloužit, ale aby posloužil a dal svůj život jako výkupné za mnohé.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Když vycházeli z Jericha, vydal se za ním velký zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'A hle, dva slepí seděli u cesty; jakmile uslyšeli, že jde kolem Ježíš, vykřikli: „Smiluj se nad námi, [Pane], synu Davidův!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Zástup jim přísně domluvil, aby utichli. Oni však vykřikli ještě silněji: „Smiluj se nad námi, Pane, synu Davidův!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Ježíš se zastavil, zavolal je a řekl: „Co chcete, abych vám učinil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Řekli mu: „Pane, ať se nám otevřou oči!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Ježíš byl hluboce pohnut, dotkl se jejich očí, a hned prohlédli a šli za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Když se přiblížili k Jeruzalému a přišli do Betfage na Olivové hoře, poslal Ježíš dva učedníky');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'a řekl jim: „Jděte do protější vesnice a hned naleznete uvázanou oslici a s ní oslátko. Odvažte je a přiveďte ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'A kdyby vám někdo něco řekl, povězte: ⌈ Pán je potřebuje a hned je pošle. ⌉“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Toto [všechno] se stalo, aby se naplnilo, co bylo řečeno skrze proroka:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Řekněte dceři siónské: Hle, tvůj král k tobě přichází, tichý a sedící na oslici a [na] oslátku, synu té pod jhem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Učedníci šli a učinili, jak jim Ježíš nařídil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Přivedli oslici i oslátko, položili na ně pláště a on se na ně posadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Mohutný zástup rozprostřel své pláště na cestu, jiní zase odsekávali větve ze stromů a stlali je na cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Zástupy, které šly před ním, i ty, které ho doprovázely, křičely: „Hosana synu Davidovu! Požehnaný, který přichází ve jménu Pána! Hosana na výsostech!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Když vjel do Jeruzaléma, celé město se zatřáslo a říkalo: „Kdo to je?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Zástupy říkaly: „To je ⌈prorok Ježíš, ten⌉ z Nazareta v Galileji.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Ježíš vstoupil do [Božího] chrámu a vyhnal všechny, kteří v chrámě prodávali a kupovali, zpřevracel stoly směnárníků i sedadla prodavačů holubů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'a řekl jim: „Je napsáno: Můj dům bude nazván domem modlitby, ale vy z něj děláte jeskyni lupičů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'A přistoupili k němu v chrámě ⌈slepí a chromí⌉, a uzdravil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Když velekněží a učitelé Zákona spatřili ty ⌈podivuhodné věci⌉, které učinil, i děti volající v chrámě: „Hosana synu Davidovu“, byli pobouřeni');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'a řekli mu: „Slyšíš, co tihle říkají?“Ježíš jim řekl: „Ano. Nikdy jste nečetli: Z úst nemluvňat a kojenců sis připravil chválu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'I nechal je a vyšel ven z města do Betanie, kde přenocoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Když se časně ráno vracel do města, dostal hlad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Spatřil u cesty fíkovník a šel k němu, ale nenašel na něm nic, jen pouhé listí. Řekl mu: „Ať se z tebe již nikdy ovoce neurodí!“A fíkovník ihned uschl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Když to učedníci uviděli, užasli se a říkali: „Jak ten fíkovník hned uschl!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Ježíš jim ⌈na to⌉ řekl: „Amen, pravím vám, budete–li mít víru a nezapochybujete–li, učiníte nejen to, co jsem učinil s fíkovníkem, ale kdybyste i této hoře řekli: Zvedni se a vrhni se do moře, stane se to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'A všechno, oč byste v modlitbě požádali, ⌈budete–li věřit⌉, dostanete.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Když přišel do chrámu a vyučoval, přistoupili k němu velekněží a starší lidu a řekli: „⌈V jaké pravomoci⌉ činíš tyto věci? Kdo ti dal tuto pravomoc?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Ježíš jim odpověděl: „I já se vás zeptám na jednu věc. Jestliže mi to řeknete, i já vám povím, v jaké pravomoci tyto věci činím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Odkud byl křest Janův? Z nebe, či z lidí?“Oni se mezi sebou dohadovali: „Řekneme–li z nebe, řekne nám: Proč jste mu tedy neuvěřili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Řekneme–li však z lidí, obáváme se zástupu, neboť všichni mají Jana za proroka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Odpověděli Ježíšovi: „Nevíme.“A on jim řekl: „Ani já vám nepovím, v jaké pravomoci tyto věci činím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, '„Co myslíte? Jeden člověk měl dva syny. Přistoupil k prvnímu a řekl: Synu, jdi dnes pracovat na [mou] vinici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'On odpověděl: Nechci. Ale potom toho litoval a šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Přistoupil k druhému a řekl totéž. On odpověděl: Ano, pane, ale nešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Který z těch dvou vykonal otcovu vůli?“Řekli: „Ten první.“Ježíš jim řekl: „Amen, pravím vám, že celníci a nevěstky vás předcházejí do Božího království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Neboť Jan k vám přišel cestou spravedlnosti, ale neuvěřili jste mu. Celníci a nevěstky mu však uvěřili. A když jste to uviděli, ani potom jste toho nelitovali, abyste mu uvěřili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, '„Poslyšte jiné podobenství: Byl jeden člověk, hospodář, který vysadil vinici, obehnal ji zdí, vykopal v ní lis a vystavěl věž; pak ji pronajal vinařům a odcestoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Když se přiblížil čas úrody, poslal své otroky k vinařům, aby pře vzali jeho úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Ale vinaři jeho otroky chytili, jednoho zbili, druhého zabili, dalšího ukamenovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Znovu poslal jiné otroky, bylo jich ještě více než těch prvních, ale učinili jim totéž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Naposled k nim poslal svého syna a řekl: ⌈Zastydí se před mým synem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Když však vinaři uviděli syna, řekli si: To je dědic. Pojďte, zabijme ho a zmocněme se jeho dědictví!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'I chytili ho, vyhodili ven z vinice a zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Když tedy přijde pán vinice, co učiní oněm vinařům?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Řekli mu: „Ty zlé zle zahubí a vinici pronajme jiným vinařům, kteří mu budou úrodu odevzdávat v určených časech.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Ježíš jim řekl: „Copak jste nikdy nečetli v Písmech: Kámen, který stavitelé po prozkoumání zavrhli, se stal hlavou úhlu. Od Pána se to stalo a je to podivuhodné v našich očích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Proto vám pravím, že vám bude Boží království odňato a bude dáno národu, který přináší jeho úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Kdo padne na ten kámen, roztříští se, a na koho padne, toho rozdrtí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Když velekněží a farizeové uslyšeli tato jeho podobenství, poznali, že mluví o nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Chtěli se ho zmocnit, ale báli se zástupů, protože ty ho měly za proroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'A Ježíš k nim znovu promluvil v podobenstvích:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '„Království Nebes ⌈je podobné⌉ králi, který vystrojil svatbu svému synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'A poslal své otroky, aby zavolali pozvané na svatbu; ale ti nechtěli přijít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Poslal znovu jiné otroky ⌈se slovy⌉: Řekněte pozvaným: Hle, přichystal jsem svou hostinu, moji býci a krmný dobytek jsou poraženi, všechno je připraveno, přijďte na svatební hostinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Ale oni nedbali a odešli, jeden na své pole, jiný za svým obchodem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Ostatní se zmocnili jeho otroků, ztýrali je a zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, '⌈Král se rozhněval⌉, poslal svá vojska, zahubil ony vrahy a jejich město vypálil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Potom řekl svým otrokům: Svatba je sice připravena, ale pozvaní jí nebyli hodni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Jděte tedy na křižovatky cest a každého, koho naleznete, pozvěte na svatební hostinu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'I vyšli ti otroci na cesty a shromáždili všechny, které nalezli, zlé i dobré. A ⌈svatební síň⌉ se naplnila stolovníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Když král vstoupil, aby se na stolovníky podíval, spatřil tam člověka, který na sobě neměl svatební šat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'I řekl mu: Příteli, jak jsi sem vešel bez svatebního roucha? A on oněměl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Tehdy řekl král služebníkům: Svažte mu nohy a ruce a vyhoďte ho do nejzazší temnoty; tam bude pláč a skřípění zubů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Neboť je mnoho pozvaných, ale málo vybraných.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Tehdy farizeové šli a poradili se, jak by ho chytili za slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'A poslali k němu své učedníky spolu s herodiány, kteří řekli: „Učiteli, víme, že jsi pravdivý a Boží cestě učíš podle pravdy. A nedbáš na nikoho, neboť ⌈nebereš ohled na postavení člověka⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Řekni nám tedy, co myslíš: Je dovoleno dát daň císaři, nebo ne?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Ježíš poznal jejich ⌈zlý úmysl⌉ a řekl: „Proč mne zkoušíte, pokrytci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Ukažte mi peníz daně.“Přinesli mu denár.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Řekl jim: „Čí je ten obraz a nápis?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Odpověděli mu: „Císařův.“Tu jim řekl: „Co je tedy císařovo, odevzdejte císaři, a co je Boží, Bohu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Když to uslyšeli, užasli, nechali ho a odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'V ten den k němu přišli saduceové, kteří říkají, že není vzkříšení, a zeptali se ho:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, '„Učiteli, Mojžíš řekl: Zemře–li někdo bezdětný, jeho bratr si podle řádu švagrovství vezme jeho ženu a svému bratrovi ⌈vzbudí potomka⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'U nás bylo sedm bratrů. První se oženil a zemřel; a protože neměl potomka, zanechal svou ženu svému bratrovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Stejně i druhý a třetí, až do sedmého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Poslední ze všech zemřela ta žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Kterému z těch sedmi bude tedy ta žena patřit při vzkříšení? Vždyť ji měli všichni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Ježíš jim odpověděl: „Bloudíte, protože neznáte Písma ani Boží moc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Při vzkříšení se totiž lidé nežení ani nevdávají, ale jsou jako [Boží] andělé v nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Pokud jde o vzkříšení mrtvých, nečetli jste, co vám bylo od Boha řečeno slovy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Já jsem Bůh Abrahamův, Bůh Izákův a Bůh Jákobův? [Bůh] není Bohem mrtvých, ale živých.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Když to zástupy uslyšely, byly ohromeny jeho učením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Když farizeové uslyšeli, že umlčel saduceje, sešli se spolu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'a jeden z nich, [zákoník], ho chtěl zkoušet a zeptal se:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '„Učiteli, které přikázání je v Zákoně největší?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'On mu řekl: „ Miluj Pána, svého Boha, celým svým srdcem, celou svou duší a celou svou myslí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'To je největší a první přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Druhé je mu podobné: Miluj svého bližního jako sebe samého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Na těchto dvou přikázáních spočívá celý Zákon a Proroci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Když se farizeové shromáždili, Ježíš se jich zeptal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '„Co si myslíte o Mesiáši? Čí je syn?“Řekli mu: „Davidův.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Řekl jim: „Jak to tedy, že ho David v Duchunazývá Pánem, když praví:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Řekl Pán mému Pánu: Seď po mé pravici, dokud tvé nepřátele nepoložím ⌈za podnož tvých nohou⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Jestliže ho tedy David nazývá Pánem, jakpak je jeho synem?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'A nikdo mu nemohl odpovědět ani slovo; od toho dne se ho již nikdo neodvážil zeptat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Tehdy Ježíš promluvil k zástupům a ke svým učedníkům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, '„Na stolci Mojžíšově usedli učitelé Zákona a farizeové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Proto udělejte a zachovávejte všechno, co by vám řekli, avšak podle jejich skutků nečiňte; neboť mluví, ale nečiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Svazují těžká [a neúnosná] břemena a vkládají je lidem na ramena, ale sami jimi nechtějí hnout ani prstem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'A všecky své skutky dělají proto, aby je lidé viděli. Rozšiřují své ⌈modlitební řemínky⌉ a prodlužují třásně [svých oděvů],');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'mají rádi přední místa na hostinách a přední sedadla v synagogách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'pozdravy na tržištích a jsou rádi, když je lidé oslovují Rabbi [Rabbi].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Vy se však nenechte nazývat Rabbi, neboť jediný je váš Učitel, vy pak všichni jste bratři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'A nikoho nenazývejte na zemi svým Otcem, neboť jediný je váš Otec, ten nebeský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Ani se nenechte nazývat Vůdci, neboť váš Vůdce je jeden, Mesiáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Ale největší z vás bude vaším služebníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Kdo se bude povyšovat, bude ponížen, a kdo se poníží, bude povýšen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože zavíráte království Nebes před lidmi; sami totiž nevstupujete, a ⌈těm, kdo by chtěli vstoupit,⌉ vstoupit nedovolujete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '[Běda vám, učitelé Zákona a farizeové, pokrytci, protože vyjídáte domy vdov a okázale dlouho se modlíte; proto vezmete těžší odsouzení.] “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože obcházíte moře i souš, abyste získali jednoho proselytu; a když se jím stane, děláte z něho syna Gehenny, dvakrát horšího, než jste sami.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, '„Běda vám, slepí vůdcové! Říkáte: Kdo by učinil přísahu při svatyni, nic to neznamená; ale kdo by učinil přísahu při zlatu svatyně, je vázán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Blázni a slepci, co je větší: zlato, nebo svatyně, která to zlato posvětila?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'A kdo by učinil přísahu při oltáři, nic to neznamená, ale kdo by vyslovil přísahu při daru, který je na něm, je vázán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, '[Blázni a] slepci, co je větší: dar, nebo oltář, který ten dar posvěcuje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Kdo tedy přísahá při oltáři, přísahá při něm i při všem, co je na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'A kdo přísahá při svatyni, přísahá při ní i při Tom, kdo v ní přebývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'A kdo přísahá při nebi, přísahá při trůnu Božím i při Tom, který na něm sedí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože dáváte desátky z máty, kopru a kmínu, ale zanedbali jste závažnější věci Zákona: právo, milosrdenství a věrnost. Toto bylo třeba udělat a tamto nezanedbávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Slepí vůdcové! Cedíte komára, ale velblouda polykáte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože čistíte číše a mísy zvnějšku, ale uvnitř jsou plné chamtivosti a nezdrženlivosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Slepý farizeji! Napřed vyčisti vnitřek číše [a mísy], aby se stal čistým i jejich zevnějšek.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože se podobáte obíleným hrobům, které se zvenčí zdají pěkné, ale uvnitř jsou plné kostí mrtvých a veškeré nečistoty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Tak i vy se navenek zdáte lidem spravedliví, ale uvnitř jste plni pokrytectví a bezzákonnosti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože stavíte náhrobky prorokům a zdobíte pomníky spravedlivých');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'a říkáte: Kdybychom žili ve dnech svých otců, neměli bychom s nimi ⌈na prolévání krve⌉ proroků podíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Tak svědčíte sami proti sobě, že jste synové těch, kteří proroky zavraždili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'I vy naplňte míru svých otců!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Hadi, ⌈plemeno zmijí⌉! Jak uniknete trestu Gehenny?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Hle, proto já k vám posílám proroky a moudré muže i ⌈učitele Zákona⌉; některé z nich zabijete a ukřižujete, některé z nich budete bičovat ve svých synagogách a pronásledovat od města k městu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'aby na vás padla všechna spravedlivá krev vylévaná na zemi, od krve spravedlivého Ábela až po krev Zachariáše, syna Barachiášova, kterého jste zavraždili mezi svatyní a oltářem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Amen, pravím vám, to všechno přijde na toto pokolení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, '„Jeruzaléme, Jeruzaléme, který zabíjíš proroky a kamenuješ ty, kteří jsou k tobě posláni, kolikrát jsem chtěl shromáždit tvé děti, tak jako slepice shromažďuje svá kuřata pod křídla, ale nechtěli jste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Hle, váš dům se vám zanechává [pustý].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Neboť pravím vám, od nynějška mne již neuvidíte, dokud neřeknete: Požehnaný, který přichází ve jménu Pána! “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Ježíš vyšel z chrámu a odcházel. Tu přistoupili jeho učedníci, aby mu ukázali na chrámové stavby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Ale on jim ⌈na to⌉ řekl: „Vidíte to všechno? Amen, pravím vám, jistě zde nezůstane kámen na kameni, který nebude stržen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Když seděl na Olivové hoře, v soukromí k němu přistoupili učedníci a říkali: „Řekni nám, kdy to bude a jaké bude znamení tvého příchodu a skonání věku?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Ježíš jim odpověděl: „Dávejte si pozor, aby vás někdo nesvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Neboť mnozí přijdou ⌈v mém jménu⌉ a budou říkat: Já jsem Kristus a svedou mnohé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Budete slýchat o válkách a uslyšíte válečné zvěsti. Dejte si pozor, neděste se. To [všechno] musí nastat, ale to ještě není konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Povstane totiž národ proti národu a království proti království, budou hladomory a země třesení na různých místech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Ale to všechno bude počátek porodních bolestí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Pak vás budou vydávat do soužení a budou vás zabíjet; a všechny národy vás budou nenávidět pro mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'A tehdy ⌈mnohým to bude kamenem úrazu,⌉ budou se navzájem zrazovat a jeden druhého nenávidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Také povstanou mnozí lživí proroci a mnohé svedou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'A protože vzroste bezzákonnost, ochladne láska mnohých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Ten však, kdo vytrvá do konce, bude zachráněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Toto evangelium království bude vyhlášeno po celém světě na svědectví všem národům. A tehdy přijde konec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, '„Když pak uvidíte ohavnost zpustošení, o níž mluvil prorok Daniel, jak stojí na svatém místě -- kdo čte, ať rozumí --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'tehdy ti, kdo budou v Judsku, ať utíkají do hor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Kdo bude na střeše, ať nesestupuje, aby si vzal věci ze svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'A kdo bude na poli, ať se nevrací zpátky, aby si vzal svůj plášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Běda těhotným a kojícím v oněch dnech!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Modlete se, aby k vašemu útěku nedošlo v zimě nebo v sobotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Neboť tehdy bude velké soužení, jaké nenastalo od počátku světa až do nynějška, a nikdy již nenastane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'A kdyby nebyly ty dny zkráceny, nebylo by zachráněno žádné tělo; ale kvůli vyvoleným budou ony dny zkráceny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Tehdy, když by vám někdo řekl: Hle, zde je Kristus!, nebo: Je zde!, nevěřte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Povstanou totiž falešní kristové a falešní proroci a budou ukazovat veliká znamení a divy, že by, kdyby to bylo možné, svedli i vyvolené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Hle, všechno jsem vám řekl předem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Řeknou–li vám tedy: Hle, je v pustině, nevycházejte; hle, v úkrytech, nevěřte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Neboť jako když blesk vychází od východu a je vidět až na západ, tak bude [i] příchod Syna člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Kdekoli je mrtvola, tam se shromáždí supi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, '„Ihned po soužení oněch dnů se zatmí slunce a měsíc nebude vydávat svou zář, hvězdy budou padat z nebe a mocnosti nebes se zatřesou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Potom se ukáže znamení Syna člověka na nebi, a tehdy se budou bít v prsa všechny kmeny země. A uvidí Syna člověka přicházejícího na nebeských oblacích s mocí a velikou slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'A pošle své anděly s mohutným [zvukem] polnice a ti shromáždí jeho vyvolené ze čtyř větrů, od jednoho nejzazšího konce nebes až k jejich druhému nejzazšímu konci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, '„Od fíkovníku se naučte podobenství: Když již jeho větev změkne a vyhání listy, víte, že léto je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Tak i vy, až toto všechno uvidíte, vězte, že je to blízko, přede dveřmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Amen, pravím vám, že určitě nepomine toto pokolení, dokud se toto všechno nestane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Nebe a země pominou, ale má slova jistě nepominou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, '„O tom dni a hodině nikdo neví, ani andělé nebes, [ani Syn,] jenom sám Otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Neboť jak tomu bylo za dnů Noe, tak tomu bude [i] při příchodu Syna člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Jako totiž v oněch dnech před potopou jedli, pili, ženili se a vdávaly, až do dne, kdy Noe vešel do korábu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'a nic nepoznali, dokud ne přišla potopa a všechny ne smetla, takový bude i příchod Syna člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Tehdy budou dva na poli, jeden bude vzat a druhý bude zanechán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Dvě budou mlít na obilném mlýnku, jedna bude vzata a druhá bude zanechána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Bděte tedy, protože nevíte, v který den váš Pán přijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'To však vězte, že kdyby hospodář věděl, v kterou noční hlídku přijde zloděj, zůstal by vzhůru a nedovolil by mu prokopat se do domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Proto i vy buďte připraveni, protože neznáte hodinu, v níž přijde Syn člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, '„Kdo je tedy věrný a rozumný otrok, jehož pán ustanovil nad svou čeledí, aby jí dával pokrm v pravý čas?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Blahoslavený ten otrok, kterého jeho pán po svém příchodu nalezne, že tak činí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Amen, pravím vám, že ho ustanoví nade vším svým majetkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Kdyby si však onen zlý otrok ve svém srdci řekl: Můj pán ⌈dlouho nepřichází⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'a začal by bít své spoluotroky, jíst a pít s opilci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'přijde pán onoho otroka v den, kdy to nečeká, a v hodinu, kterou nezná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Oddělí ho a určí mu úděl s pokrytci. Tam bude pláč a skřípění zubů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '„Tehdy bude království Nebes podobné deseti pannám, které vzaly své lampy a vyšly naproti ženichovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Pět z nich bylo pošetilých a pět rozumných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Pošetilé vzaly [své] lampy, ale nevzaly s sebou olej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Rozumné však se svými lampami vzaly i olej v nádobkách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Když ženich dlouho nepřicházel, začaly všechny podřimovat a usnuly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Uprostřed noci se však ozval křik: Hle, ženich! Vyjděte mu vstříc!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Tehdy všechny panny vstaly a daly své lampy do pořádku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Pošetilé řekly rozumným: Dejte nám ze svého oleje, neboť naše lampy dohasínají!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Ale rozumné odpověděly: Ne, nemuselo by vystačit pro nás i pro vás. Jděte raději k prodavačům a kupte si!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Zatímco odcházely, aby nakoupily olej, přišel ženich, a ty, které byly připravené, s ním vešly na svatební hostinu; a dveře byly zavřeny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Později přišly i ostatní panny a říkaly: Pane, pane, otevři nám!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Ale on odpověděl: Amen, pravím vám, neznám vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Bděte tedy, protože neznáte den ani hodinu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, '„ Je to totiž jako s člověkem, který se chystal odcestovat: zavolal své otroky a svěřil jim svůj majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Jednomu dal pět talentů, druhému dva, třetímu jeden, každému podle jeho schopností, a ihned odcestoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Ten, který přijal pět talentů, šel a vložil je do obchodu, a získal jiných pět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Stejně [i] ten, který dostal dva, získal jiné dva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Ale ten, který dostal jeden, odešel, vykopal ⌈v zemi jámu ⌉ a ukryl peníze svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Po dlouhé době pak přišel pán oněch otroků a začal s nimi účtovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Přistoupil ten, který dostal pět talentů, přinesl jiných pět talentů a řekl: Pane, pět talentů jsi mi svěřil; hle, jiných pět talentů jsem [jimi] získal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Jeho pán mu řekl: Dobře, otroku dobrý a věrný, byl jsi věrný nad málem, ustanovím tě nad mnohým; vejdi v radost svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Přistoupil také ten, [který dostal] dva talenty a řekl: Pane, dva talenty jsi mi svěřil; hle, jiné dva talenty jsem získal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Jeho pán mu řekl: Dobře, otroku dobrý a věrný, byl jsi věrný nad málem, ustanovím tě nad mnohým; vejdi v radost svého pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Přistoupil pak i ten, který dostal jeden talent, a řekl: Pane, poznal jsem, že jsi tvrdý člověk; sklízíš, kde jsi nezasel, a shromažďuješ, kde jsi nerozsypal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Dostal jsem strach, odešel jsem a ukryl tvůj talent v zemi. Hle, zde máš, co je tvoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Jeho pán mu odpověděl: Zlý a lenivý otroku, věděl jsi, že sklízím, kde jsem nezasel, a shromažďuji, kde jsem nerozsypal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Měl jsi tedy mé peníze dát směnárníkům, a já bych si ⌈po návratu⌉ vzal, co je moje, i s úrokem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Vezměte tedy od něho ten talent a dejte tomu, který má deset talentů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Neboť každému, kdo má, bude dáno a bude mít hojnost. Tomu, kdo nemá, však bude odňato i to, co má.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'A toho neužitečného otroka vyhoďte do nejzazší temnoty. Tam bude pláč a skřípění zubů. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, '„Až přijde Syn člověka ve své slávě a všichni [svatí] andělé s ním, tehdy se posadí na trůn své slávy;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'a budou před něj shromážděny všecky národy. A oddělí jedny od druhých, jako pastýř odděluje ovce od kozlů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Ovce postaví po své pravici, kozly po levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Potom řekne Král těm po své pravici: Pojďte, požehnaní mého Otce, přijměte do dědictví království, které je pro vás připraveno od založení světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Neboť jsem hladověl a dali jste mi najíst, žíznil jsem a dali jste mi napít, byl jsem cizincem a ujali jste se mě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'byl jsem nahý a oblékli jste mě, byl jsem nemocen a navštívili jste mě, byl jsem ve vězení a přišli jste za mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Tehdy mu spravedliví odpovědí: Pane, kdy jsme tě spatřili hladového a dali jsme ti najíst, nebo žíznivého a dali jsme ti napít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Kdy jsme tě spatřili jako cizince a ujali jsme se tě, nebo nahého a oblékli jsme tě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Kdy jsme tě spatřili nemocného nebo ve vězení a přišli jsme za tebou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Král jim odpoví: Amen, pravím vám, cokoliv jste učinili jednomu z těchto mých nejmenších bratří, mně jste učinili. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, '„Potom řekne i těm po levici: Jděte ode mne, prokletí, do věčného ohně, který je připraven pro Ďábla a jeho anděly!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Neboť jsem hladověl, a nedali jste mi najíst, žíznil jsem, a nedali jste mi napít,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'byl jsem cizincem, a neujali jste se mne, byl jsem nahý, a neoblékli jste mne, byl jsem nemocný a ve vězení, a nenavštívili jste mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Tu mu odpovědí i oni: Pane, kdy jsme tě spatřili hladového, žíznivého, jako cizince, nahého, nemocného nebo ve vězení, a neposloužili jsme ti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Pak jim odpoví: Amen, pravím vám, cokoliv jste neučinili jednomu z těchto nejmenších, ani mně jste neučinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'A tito půjdou do věčného trápení, ale spravedliví do věčného života.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'I stalo se, že když dokončil všechna tato slova, řekl Ježíš svým učedníkům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '„Víte, že za dva dny bude ⌈Hod beránka⌉ a Syn člověka bude vydán, aby byl ukřižován.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Tehdy se shromáždili velekněží a starší lidu ve dvoře velekněze, který se jmenoval Kaifáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'a společně se poradili, jak by se lstí Ježíše zmocnili a zabili ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Říkali však: „Ne ve svátek, aby nenastalo pobouření mezi lidem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Když byl Ježíš v Betanii v domě Šimona Malomocného,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'přistoupila k němu žena, která měla alabastrovou nádobku drahocenného oleje, a když byl u stolu, vylila mu ji na hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Když to [jeho] učedníci uviděli, rozhořčili se a řekli: „K čemu tato ztráta?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Vždyť se to mohlo draze prodat a peníze dát chudým.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Ježíš to poznal a řekl jim: „Proč působíte té ženě těžkosti? Vykonala na mně dobrý skutek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Vždyť chudé máte stále s sebou, mne však nemáte stále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Když ona vylila tento olej na mé tělo, učinila to k mému pohřbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Amen, pravím vám, kdekoli po celém světě bude hlásáno toto evangelium, bude se na její památku mluvit také o tom, co ona učinila.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Potom jeden ze Dvanácti, který se jmenoval Juda Iškariotský, šel k velekněžím');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'a řekl: „Co jste ochotni mi dát, když vám ho vydám?“A oni mu odvážili třicet stříbrných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Od té chvíle hledal vhodnou příležitost, aby jim ho vydal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Prvního dne svátku nekvašených chlebů přistoupili učedníci k Ježíšovi a řekli: „Kde chceš, abychom ti připravili k jídlu ⌈velikonočního beránka⌉?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'On pak řekl: „Jděte do města k jistému člověku a řekněte mu: Učitel říká: Můj čas je blízko. Budu u tebe se svými učedníky slavit velikonočního beránka. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'A učedníci učinili, jak jim Ježíš nařídil, a připravili velikonočního beránka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Když nastal večer, stoloval s Dvanácti [učedníky].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'A když jedli, řekl: „Amen, pravím vám, že jeden z vás mě zradí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Velmi se rmoutili a jeden každý [z nich] [mu] začal říkat: „Jsem to snad já, Pane?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'On odpověděl: „Kdo se mnou namočil ruku v míse, ten mě zradí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Syn člověka sice odchází, jak je o něm napsáno, ale běda tomu člověku, skrze něhož bude Syn člověka zrazen. ⌈Pro toho by bylo lépe, kdyby se⌉ nenarodil!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Juda, který ho zrazoval, ⌈na to⌉ řekl: „Jsem to snad já, Rabbi?“[Ježíš] mu odpověděl: „Tys to řekl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Když jedli, vzal Ježíš chléb, požehnal, rozlomil ho, dal učedníkům a řekl: „Vezměte, jezte. Toto je mé tělo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Pak vzal kalich, vzdal díky a dal jim ho ⌈se slovy⌉: „Napijte se z něho všichni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Neboť toto je má krev [nové] smlouvy, která se vylévá za mnohé na odpuštění hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Pravím vám, [že] od této chvíle již nebudu pít z tohoto plodu vinné révy až do toho dne, kdy jej budu pít s vámi nový v království svého Otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'A zazpívali chvalozpěv a vyšli na Olivovou horu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Tehdy jim Ježíš řekl: „Vy všichni ode mne této noci odpadnete, neboť je napsáno: Budu bít pastýře a ovce stáda se rozptýlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Ale po svém vzkříšení vás předejdu do Galileje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, '⌈Na to⌉ mu Petr řekl: „Kdyby všichni od tebe odpadli, já nikdy neodpadnu!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Ježíš mu řekl: „Amen, pravím tobě, že mě této noci, dřív než kohout zakokrhá, třikrát zapřeš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Petr mu řekl: „I kdybych měl s tebou zemřít, určitě tě nezapřu.“Podobně mluvili i ostatní učedníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Tehdy s nimi Ježíš přišel na místo zvané Getsemane a řekl učedníkům: „Posaďte se zde, zatímco se tamhle odejdu pomodlit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Vzal s sebou Petra a oba Zebedeovy syny; tu se začal rmoutit a znepokojovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Pak jim řekl: „Má duše je smutná až k smrti. Zůstaňte zde a bděte se mnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'A trochu poodešel, padl na tvář, modlil se a říkal: „Můj Otče, je–li to možné, ať mne mine tento kalich. Avšak ne jak já chci, ale jak chceš ty.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Potom přišel k učedníkům a nalezl je spící, i řekl Petrovi: „To jste se mnou nemohli bdít jedinou hodinu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Bděte a modlete se, abyste nevešli do pokušení. Duch je sice ochotný, ale tělo slabé.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Opět podruhé odešel a pomodlil se, říkaje: „Můj Otče, není–li možné, aby [mne] tento [kalich] minul, musím–li ho vypít, staň se tvá vůle.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Pak šel a nalezl je opět spící, protože měli velmi těžká víčka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'I nechal je, znovu odešel a pomodlil se potřetí, říkaje [opět] stejnou prosbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Tehdy přišel ke [svým] učedníkům a řekl jim: „⌈Ještě spíte a odpočíváte?⌉ Hle, přiblížila se ta hodina a Syn člověka je vydáván do rukou hříšníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Vstávejte, pojďme! Hle, přiblížil se ten, který mne zrazuje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Když ještě mluvil, hle, přišel Juda, jeden z Dvanácti, a s ním veliký zástup od velekněží a starších lidu s meči a holemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Ten, který ho zrazoval, ⌈s nimi domluvil znamení⌉: „Je to ten, kterého políbím; toho se zmocněte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'A hned přistoupil k Ježíšovi a řekl: „Buď zdráv, Rabbi,“a vroucně ho políbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Ježíš mu řekl: „Příteli, proč jsi přišel?“Tu přistoupili, vztáhli na Ježíše ruce a zmocnili se ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'A hle, jeden z těch, kteří byli s Ježíšem, natáhl ruku, vytasil meč, udeřil veleknězova otroka a uťal mu ucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Tehdy mu Ježíš řekl: „Vrať svůj meč na místo. Neboť všichni, kdo se chápou meče, mečem zahynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Či myslíš, že nemohu poprosit svého Otce, a on mi hned pošle víc než dvanáct legií andělů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Jak by se však naplnila Písma, že se tak musí stát?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'V onu hodinu řekl Ježíš zástupům: „Jako na lupiče jste vyšli s meči a holemi, abyste mě zatkli. Den co den jsem sedával v chrámě a učil, a nezmocnili jste se mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Toto všechno se však stalo, aby se naplnila Písma proroků.“A v té chvíli ho všichni učedníci opustili a utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Ti, kdo se Ježíše zmocnili, ho odvedli k veleknězi Kaifášovi, kde se shromáždili učitelé Zákona a starší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Petr šel zpovzdálí za ním až k veleknězovu dvoru; vešel dovnitř a seděl se služebníky, aby uviděl konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Velekněží, [starší] a celá velerada hledali proti Ježíšovi křivé svědectví, aby ho mohli odsoudit k smrti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'ale nenašli, ačkoli předstoupilo mnoho křivých svědků. Nakonec předstoupili dva [křiví svědkové]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'a řekli: „Tento člověk říkal: Mohu zbořit Boží svatyni a ve třech dnech [ji] vybudovat.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Tu velekněz povstal a řekl mu: „Nic neodpovídáš? Co tito lidé svědčí proti tobě?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Ježíš však mlčel. Velekněz mu řekl: „Zapřísahám tě při živém Bohu, abys nám řekl, zda jsi Mesiáš, Syn Boží!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Ježíš mu říká: „Tys to řekl. Avšak pravím vám, od nynějška spatříte Syna člověka sedícího po pravici Moci a přicházejícího na nebeských oblacích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Tu velekněz roztrhl svá roucha a řekl: „Rouhal se! Nač ještě potřebujeme svědky? Hle, teď jste slyšeli rouhání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Co si o tom myslíte?“Oni odpověděli: „Je hoden smrti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Pak mu naplivali do tváře a ztloukli ho pěstmi; někteří ho uhodili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'a říkali: „Prorokuj nám, Mesiáši, kdo je ten, který tě udeřil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Petr seděl venku na dvoře. Přistoupila k němu jedna služka a řekla: „Také ty jsi byl s Ježíšem Galilejským!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Ale on to přede všemi zapřel, říkaje: „Nevím, o čem mluvíš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'A když [on] vyšel k bráně, spatřila ho jiná a řekla těm, kdo tam byli: „[I] tenhle byl s Ježíšem Nazaretským.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'A on opět zapřel s přísahou: „Neznám toho člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Za chvilku přistoupili ti, kteří tam stáli, a řekli Petrovi: „Skutečně i ty jsi z nich, vždyť i tvá řeč tě prozrazuje!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Tehdy se začal zaklínat a zapřísahat: „Neznám toho člověka!“A hned nato zakokrhal kohout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Tu si Petr vzpomněl na Ježíšovo slovo, jak řekl: Dříve než kohout zakokrhá, třikrát mne zapřeš. I vyšel ven a hořce se rozplakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Když nastalo ráno, uradili se všichni velekněží a starší lidu proti Ježíšovi, že ho usmrtí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Spoutali ho, odvedli a vydali vladaři [Pontiu] Pilátovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Když ⌈jeho zrádce Juda⌉ uviděl, že byl Ježíš odsouzen, pocítil lítost a vrátil třicet stříbrných velekněžím a starším,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'říkaje: „Zhřešil jsem, zradil jsem nevinnou krev!“Oni však řekli: „Co je nám po tom? ⌈To je tvoje věc⌉!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Tu pohodil ty stříbrné ⌈do svatyně⌉ a vzdálil se; pak odešel a oběsil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Velekněží vzali ty stříbrné a řekli: „Není dovoleno v hodit je do chrámové pokladny, protože je to cena za krev.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Uradili se a koupili za ně hrnčířovo pole k pohřbívání cizinců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Proto je ono pole až dodnes nazýváno Polem krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Tehdy se naplnilo, co bylo řečeno skrze proroka Jeremjáše: I vzali třicet stříbrných, cenu Oceněného, který byl oceněn od synů Izraele;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'a dali je za hrnčířovo pole, jak mi nařídil Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Ježíš byl postaven před vladaře. Vladař se ho otázal: „Ty jsi král Židů?“Ježíš [mu] řekl: „Ty to říkáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'A když ho velekněží a starší obviňovali, nic neodpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Tu mu Pilát řekl: „Neslyšíš, co všechno proti tobě vypovídají?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Ale on mu neodpověděl ani na jedno obvinění, takže se vladař velmi divil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'O svátcích měl vladař ve zvyku propouštět zástupu jednoho vězně, kterého chtěli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Tehdy tam měli významného vězně, který se jmenoval Barabáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Když se tedy lidé shromáždili, řekl jim Pilát: „Koho chcete, abych vám propustil, Barabáše, nebo Ježíše, zvaného Kristus?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Věděl totiž, že ho vydali ze závisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Když seděl na soudní stolici, ⌈vzkázala mu jeho žena⌉: „Neměj nic s tím spravedlivým, neboť jsem dnes kvůli němu ve snu mnoho vytrpěla.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Velekněží a starší přesvědčili zástupy, aby si vyžádaly Barabáše, ale Ježíše aby daly zahubit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Vladař jim tedy řekl: „Kterého z těch dvou chcete, abych vám propustil?“Oni řekli: „Barabáše!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilát jim řekl: „Co tedy ⌈mám udělat⌉ s Ježíšem, zvaným Kristus?“Všichni [mu] řekli: „Ať je ukřižován!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'A [vládce] řekl: „Co tedy udělal zlého?“Oni však ještě víc křičeli: „Ať je ukřižován!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Když Pilát uviděl, že to ničemu neprospívá, ale že pozdvižení je čím dál větší, vzal vodu, umyl si před zástupem ruce a řekl: „Jsem nevinen ⌈touto krví⌉. Je to vaše věc.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'A všechen lid na to řekl: „Jeho krev na nás a na naše děti!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Pak jim propustil Barabáše. Ježíše dal zbičovat a vydal ho, aby byl ukřižován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Tehdy vladařovi vojáci vzali Ježíše do ⌈vládního paláce⌉ a shromáždili k němu celý oddíl vojska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Svlékli ho a oblékli mu šarlatový plášť,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'upletli věnec z trní a vložili jej na jeho hlavu a do pravé ruky mu dali rákos ovou hůl. Padali před ním na kolena a posmívali se mu: „Buď zdráv, králi Židů!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'A když ho poplivali, vzali tu hůl a začali ho bít po hlavě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Když se mu naposmívali, svlékli mu plášť a oblékli mu jeho šaty. A odvedli ho, aby ho ukřižovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Když vycházeli, potkali jednoho člověka z Kyrény, jménem Šimon; toho přinutili, aby vzal jeho kříž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Když přišli na místo zvané Golgota, což znamená Místo lebky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'dali Ježíšovi pít víno smíchané se žlučí. Okusil, ale nechtěl pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Ukřižovali ho a rozdělili si jeho šaty házejíce o ně los;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'pak seděli a střežili ho tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Nad hlavu mu dali ⌈nápis o jeho provinění⌉: „Toto je Ježíš, král Židů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Zároveň s ním byli ukřižováni dva lupiči, jeden po pravici a druhý po levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Kolemjdoucí ho uráželi, potřásali hlavou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'a říkali: „Ty, který boříš svatyni a ve třech dnech ji stavíš, zachraň se, jsi–li Syn Boží, [a] sestup s kříže!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Podobně se posmívali i velekněží s učiteli Zákona a staršími. Říkali:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '„Jiné zachránil, sám sebe zachránit nemůže. Je králem Izraele, ať nyní sestoupí s kříže, a my v něho uvěříme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Složil naději v Bohu, ať [ho] nyní vysvobodí, ⌈stojí–li o něho⌉. Vždyť řekl: Jsem Boží Syn! “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Stejně ho tupili i lupiči, kteří byli ukřižováni spolu s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Od šesté hodiny nastala tma po celé zemi až do hodiny deváté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Kolem deváté hodiny zvolal Ježíš silným hlasem: „Eli, Eli, lema sabachthani?“To jest: Můj Bože, můj Bože, proč jsi mne opustil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'A když to uslyšeli někteří z těch, kdo tam stáli, říkali: „Ten člověk volá Eliáše.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Jeden z nich ihned vyběhl, vzal houbu, naplnil ji octem, připevnil na rákos ovou hůl a dával mu pít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Ostatní však říkali: „Nech ho, ať uvidíme, jestli přijde Eliáš a zachrání ho!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Ale Ježíš znovu vykřikl silným hlasem a vypustil ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'A hle, opona svatyně se roztrhla ve dví odshora až dolů a země se zatřásla a skály se roztrhly');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'a hroby se otevřely a mnohá těla zesnulých svatých byla vzkříšena;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'když vyšli z hrobů po jeho vzkříšení, vstoupili do svatého města a ukázali se mnohým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Když setník a ti, kdo s ním střežili Ježíše, uviděli zemětřesení a to, co se stalo, velmi se ulekli a řekli: „Opravdu to byl Boží Syn!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Bylo tam mnoho žen dívajících se zdaleka, které se vydaly za Ježíšem z Galileje a sloužily mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Mezi nimi byla Marie Magdalská, Marie, matka Jakubova a Josefova, a matka synů Zebedeových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Když nastal večer, přišel bohatý člověk z Arimatie, jménem Josef, který se také sám stal Ježíšovým učedníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Ten přišel k Pilátovi a požádal o Ježíšovo tělo. Tehdy Pilát rozkázal, aby mu [to tělo] vydali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Josef tělo vzal, zavinul je do čistého plátna');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'a položil [je] do své nové hrobky, kterou vytesal ve skále. Pak ke vchodu do hrobky přivalil veliký kámen a odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Byla tam Marie Magdalská a ta druhá Marie a seděly naproti hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Nazítří, to je po přípravě na svátek, se u Piláta shromáždili velekněží a farizeové');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'a řekli: „Pane, vzpomněli jsme si, že onen svůdce ještě za svého života řekl: Po třech dnech vstanu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Rozkaž tedy, ať je do třetího dne hrob zajištěn, aby nepřišli [jeho] učedníci, neukradli ho a neřekli lidu: Vstal z mrtvých. A bude poslední blud horší než ten první.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilát jim řekl: „Máte stráž. Jděte a zabezpečte to, jak umíte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Oni pak šli a zabezpečili hrob ⌈tak, že zapečetili kámen a postavili k němu stráž⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Po sobotě, když už svítalo na první den týdne, přišla Marie Magdalská a ta druhá Marie, aby se podívaly na hrob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'A hle, nastalo veliké zemětřesení, neboť Pánův anděl sestoupil z nebe, přistoupil, odvalil kámen a posadil se na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Jeho vzhled byl jako blesk a jeho roucho bílé jako sníh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Strachem z něho se strážci roztřásli a zůstali jako mrtví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Anděl promluvil k ženám: „Vy se nebojte. Vždyť vím, že hledáte Ježíše, toho ukřižovaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Není zde, neboť byl vzkříšen, jak řekl. Pojďte a podívejte se na místo, kde ležel [Pán].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'A rychle jděte a povězte jeho učedníkům, že byl vzkříšen [z mrtvých]; a hle, jde před vámi do Galileje, tam ho spatříte. Hle, řekl jsem vám to.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Rychle odešly od hrobky a se strachem i velikou radostí to běžely oznámit jeho učedníkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'A [jak šly dát zprávu jeho učedníkům,] hle, Ježíš je potkal a řekl: „Buďte pozdraveny!“Ony přistoupily, objaly mu nohy a poklonily se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Tehdy jim Ježíš řekl: „Nebojte se! Jděte a oznamte mým bratřím, aby odešli do Galileje; tam mě uvidí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Když ženy odcházely, hle, někteří ze stráže přišli do města a oznámili velekněžím všechno, co se přihodilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Ti se shromáždili se staršími, poradili se a dali vojákům hodně peněz');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, '⌈se slovy⌉: „Řekněte: Jeho učedníci přišli v noci, a když jsme spali, ho ukradli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Doslechne–li se o tom vladař, my [ho] uchlácholíme a vás zbavíme starostí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Oni vzali peníze a učinili, jak byli poučeni. A ⌈tato zpráva je mezi Židy rozšířena⌉ až do dnešního dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Jedenáct učedníků odešlo do Galileje na horu, kterou jim Ježíš určil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Když ho spatřili, poklonili se [mu]; ale někteří pochybovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Ježíš přistoupil a promluvil k nim: „Byla mi dána veškerá pravomoc na nebi i na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Jděte [tedy] a čiňte učedníky ze všech národů, křtěte je ve jméno Otce i Syna i Ducha Svatého');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'a učte je zachovávat všechno, co jsem vám přikázal. A hle, já jsem s vámi po všechny dny až do skonání tohoto věku. [Amen.]“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Počátek evangelia Ježíše Krista, [Syna Božího] ⌈.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Jak⌉ je napsáno ⌈v proroku Izaiášovi⌉: Hle, [já] posílám svého posla před tvou tváří, který upraví tvou cestu [před tebou].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Hlas volajícího v pustině: Připravte Pánovu cestu, vyrovnávejte jeho stezky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Objevil se Jan, který křtil v pustině a hlásal křest pokání na odpuštění hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'A vycházela k němu celá judská krajina a všichni jeruzalémští a dávali se od něho pokřtít v řece Jordánu, vyznávajíce své hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Jan byl oděn velbloudí srstí a přepásán koženým pásem kolem svých beder a jedl kobylky a polní med.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Hlásal: „Za mnou přichází někdo silnější než já; nejsem hoden sklonit se a rozvázat řemínek jeho sandálů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Já ⌈jsem vás křtil⌉ ve vodě, ale on vás bude křtít v Duchu Svatém.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'V těch dnech přišel Ježíš z Nazareta v Galileji a byl pokřtěn od Jana v Jordánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'A hned když vystupoval z vody, uviděl roztrhávající se nebesa a Ducha jako holubici, jak sestupuje ⌈k němu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'A z nebes [zazněl] hlas: „Ty jsi ⌈můj Syn, Milovaný,⌉ v tobě jsem nalezl zalíbení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'A hned ho Duch vypudil do pustiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'V té pustině byl čtyřicet dní pokoušen Satanem. Byl tam s dravou zvěří a andělé mu sloužili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Po Janově uvěznění přišel Ježíš do Galileje a hlásal evangelium Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'A říkal: „Naplnil se čas a přiblížilo se Boží království; čiňte pokání a věřte evangeliu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'A když šel podél Galilejského moře, uviděl Šimona a Šimonova bratra Ondřeje, jak do moře vrhají [síť]; byli totiž rybáři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Ježíš jim řekl: „Pojďte za mnou a učiním, že se stanete rybáři lidí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'A hned opustili sítě a následovali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'A když šel kousek dál, uviděl Jakuba Zebedeova a jeho bratra Jana, jak v lodi spravují sítě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'A hned je povolal. Zanechali svého otce Zebedea v lodi s najatými pomocníky a odešli za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'I vešli do Kafarnaum. Hned v sobotu vstoupil do synagogy a učil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Byli ohromeni jeho vyučováním, neboť je učil jako ten, kdo má pravomoc, a ne jako učitelé Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'V jejich synagoze byl [právě] člověk ⌈s nečistým duchem⌉. Vykřikl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, '„⌈Co je ti po nás⌉, Ježíši Nazaretský? Přišel jsi nás zničit? Znám tě, vím, kdo jsi: Ten Svatý Boží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Ježíš mu pohrozil: „Umlkni a vyjdi z něho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'A ten nečistý duch jím zalomcoval, zvolal silným hlasem a vyšel z něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Všichni užasli, takže se dohadovali mezi sebou, říkajíce: „Co to je? ⌈Nové učení! S pravomocí⌉ dokonce přikazuje nečistým duchům, a poslouchají ho!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'A pověst o něm ⌈se hned rozšířila⌉ [všude] po celém okolí Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'A hned, když ⌈vyšli ze synagogy, přišli⌉ s Jakubem a Janem do domu Šimona a Ondřeje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Šimonova tchyně ležela ⌈v horečce⌉. Hned mu o ní pověděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Ježíš přistoupil, uchopil [její] ruku a pozdvihl ji. [Ihned] ji horečka opustila a ona je obsluhovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Když nastal večer a slunce zapadlo, přinášeli k němu všechny nemocné a všechny démonizované.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Celé město se shromáždilo přede dveřmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'I uzdravil mnoho trpících rozličnými chorobami a vyhnal mnoho démonů. A těm démonům nedovoloval mluvit, neboť ho znali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Časně ráno, ještě za tmy, vstal a vyšel ven; odešel na opuštěné místo a tam se modlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Šimon a ti, kteří byli s ním, se pustili spěšně za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, '⌈Když ho našli,⌉ řekli mu: „Všichni tě hledají.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Říká jim: „Pojďme jinam, do sousedních městeček, abych i tam hlásal evangelium, neboť kvůli tomu jsem vyšel.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'A hlásal evangelium v jejich synagogách po celé Galileji a vyháněl démony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Tu k němu přišel malomocný, padl [před ním] na kolena a prosil ho: „Chceš–li, jsi mocen mne očistit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Ježíš, hluboce pohnut, vztáhl svou ruku, dotkl se ho a řekl mu: „Chci, buď očištěn.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'A [když to řekl,] hned od něho malomocenství odešlo a byl očištěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Ježíš mu přísně domluvil a hned ho poslal pryč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Řekl mu: „Hleď, abys nikomu nic neřekl! Ale jdi, ukaž se knězi a obětuj za své očištění, co nařídil Mojžíš, jim na svědectví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'On však vyšel a začal to velice rozhlašovat a rozšiřovat, takže Ježíš již nemohl veřejně vstoupit do města, ale zůstával venku na opuštěných místech. A přicházeli k němu odevšad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'A když po několika dnech opět vstoupil do Kafarnaum, rozneslo se, že je doma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'A [hned] se shromáždilo mnoho lidí, takže už nebylo místo ani přede dveřmi. A mluvil k nim Slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Tu přicházeli lidé a nesli k němu ochrnutého; nesli ho čtyři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'A ⌈protože ho k němu pro zástup nemohli přinést⌉, odkryli střechu tam, kde byl, prorazili otvor a lehátko, na kterém ochrnutý ležel, spustili dolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Když Ježíš viděl jejich víru, řekl ochrnutému: „Synu, ⌈tvé hříchy jsou odpuštěny⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Seděli tam někteří z učitelů Zákona a uvažovali ve svých srdcích:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '„Proč takhle mluví? Rouhá se! Kdo je mocen odpouštět hříchy, ne–li jediný: Bůh.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Ježíš hned svým duchem poznal, že takto uvažují, a řekl jim: „Proč tak uvažujete ve svých srdcích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Co je snadnější? Říci ochrnutému: ⌈Tvé hříchy jsou odpuštěny⌉, nebo říci: Vstaň, vezmi své lehátko a choď?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Abyste však věděli, že Syn člověka má pravomoc odpouštět hříchy na zemi ...“, říká ochrnutému:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '„Tobě pravím: Vstaň, vezmi své lehátko a jdi do svého domu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'On vstal, vzal hned své lehátko a přede všemi vyšel, takže tím byli všichni ohromeni, oslavovali Boha a říkali: „Něco takového jsme ještě nikdy neviděli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Ježíš opět vyšel podél moře a celý ten zástup k němu přicházel a on je vyučoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Cestou uviděl Léviho, syna Alfeova, sedícího v celnici, a řekl mu: „Následuj mne.“On vstal a následoval ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'A když Ježíš stoloval v jeho domě, mnozí celníci a hříšníci stolovali spolu s Ježíšem a jeho učedníky, neboť jich bylo mnoho a následovali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Když učitelé Zákona ⌈z farizeů⌉ viděli, že jí s hříšníky a celníky, říkali jeho učedníkům: „Jak to, že jí [a pije] s celníky a hříšníky?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Když to Ježíš uslyšel, řekl jim: „Lékaře nepotřebují zdraví, nýbrž nemocní. Nepřišel jsem povolat spravedlivé, ale hříšné.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Janovi učedníci a farizeové se právě postili. I přijdou k němu a říkají: „Proč se Janovi učedníci a učedníci farizeů postí, ale tvoji učedníci se nepostí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Ježíš jim řekl: „Mohou se svatebčané postit, když je ženich s nimi? Dokud mají ženicha s sebou, nemohou se postit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Přijdou však dny, kdy jim bude ženich odebrán, a tehdy v onen den se budou postit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, '„Nikdo nepřišívá záplatu z neseprané látky na starý šat, jinak se ta výplň odtrhne, nové od starého, a trhlina se ještě zhorší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'A nikdo nedává mladé víno do starých měchů, jinak víno ty měchy roztrhne a víno [se vylije] a měchy se zničí. Ale mladé víno [se má dávat] do nových měchů!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'I stalo se, že v sobotu procházel obilím a jeho učedníci začali cestou trhat klasy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Farizeové mu řekli: „Podívej, proč dělají v sobotu, co se nesmí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Ježíš jim říká: „Nikdy jste nečetli, co udělal David, když se ocitl v nouzi a dostal hlad, on i ti, kdo byli s ním?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Jak za velekněze Abiatara vešel do domu Božího a snědl chleby předložení, které nesmí jíst nikdo kromě kněží, a dal i těm, kteří byli s ním?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'A řekl jim: „Sobota byla učiněna pro člověka, a ne člověk pro sobotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Takže Syn člověka je také pánem soboty.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Vstoupil opět do synagogy. A byl tam člověk, který měl odumřelou ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Pozorně jej sledovali, zda ho v sobotu uzdraví, aby jej obžalovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'A on tomu člověku s odumřelou rukou řekl: „Postav se doprostřed.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'A jim řekl: „Je v sobotu dovoleno učinit dobře, nebo zle, duši zachránit, nebo zahubit?“Ale oni mlčeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Rozhněvaně se po nich rozhlédl a hluboce zarmoucen nad tvrdostí jejich srdce řekl tomu člověku: „Natáhni [svou] ruku.“Natáhl ji, a jeho ruka byla uzdravena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Když farizeové vyšli, hned se s herodiány proti němu radili, jak by ho zahubili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Ježíš se se svými učedníky odebral k moři. A vydalo se za [ním] velké množství lidí z Galileje a z Judska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Také z Jeruzaléma, z Idumeje a Zajordání, z okolí Týru a Sidónu přišlo k němu velké množství lidí, když slyšeli, co všechno činil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Řekl tedy svým učedníkům, aby pro něj měli stále připravenou loďku, aby se na něho zástup netlačil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Neboť mnohé uzdravil, takže všichni, kteří měli trápení, se k němu hrnuli, aby se ho dotkli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'A nečistí duchové, kdykoli ho viděli, padali před ním a křičeli: „Ty jsi Syn Boží!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Ostře je káral, aby nezjevili, kdo je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Vystoupil na horu a zavolal k sobě ty, které sám chtěl. I odešli k němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Ustanovil jich dvanáct, aby byli s ním, aby je posílal hlásat evangelium');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'a aby měli pravomoc vyhánět démony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, '[Ustanovil těchto Dvanáct:] Šimona, kterému přidal jméno Petr,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Jakuba Zebedeova a Jakubova bratra Jana a přidal jim jméno Boanerges, což znamená synové hromu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Ondřeje, Filipa, Bartoloměje, Matouše, Tomáše, Jakuba, toho Alfeova, Tadeáše, Šimona Kananejského');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'a Judu Iškariotského, který ho pak zradil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Přišli do domu a opět se shromáždil zástup, takže nemohli ani chleba pojíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Když to uslyšeli jeho příbuzní, vyšli, aby se ho zmocnili, neboť říkali: „Pomátl se.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Učitelé Zákona, kteří sestoupili z Jeruzaléma, říkali: „Má Belzebula. ⌈V moci ⌉ vládce démonů vyhání démony!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Zavolal je k sobě a mluvil k nim v podobenstvích: „Jak může Satan vyhánět Satana?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Je–li království proti sobě rozděleno, takové království nemůže obstát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Bude–li dům proti sobě rozdělen, takový dům nebude moci obstát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Jestliže Satan povstal sám proti sobě a rozdělil se, nemůže obstát, ale je s ním konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Avšak nikdo nemůže vejít do domu siláka a uloupit jeho majetek, jestliže siláka nejdříve nespoutá, a teprve pak vyloupí jeho dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, '⌈Amen, pravím⌉ vám, že všechno bude lidským synům odpuštěno, prohřešení i rouhání, jakkoliv by se rouhali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Kdo by však ⌈vědomě promluvil zle⌉ proti Duchu Svatému, nemá odpuštění v tomto věku, ale je vinen věčným prohřešením.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Říkali totiž: „Má nečistého ducha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Tu přichází jeho matka a jeho bratři a stojíce venku ⌈dali ho zavolat⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Kolem něho seděl zástup. Říkají mu: „Hle, tvá matka a tvoji bratři [a tvé sestry] tě venku hledají.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, '⌈Odpověděl jim⌉: „Kdo je má matka a moji bratři?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'A rozhlédl se po těch, kteří seděli v kruhu kolem něho, a řekl: „Hle, má matka a moji bratři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Neboť kdo činí Boží vůli, to je můj bratr, má sestra i matka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'A opět začal učit u moře. A shromáždil se k němu veliký zástup, takže vstoupil do lodi na moři a posadil se; celý ten zástup byl u moře na břehu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'A učil je mnohému v podobenstvích. Ve svém vyučování jim říkal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '„Poslouchejte! Hle, rozsévač vyšel zasít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'A když rozséval, stalo se, že některé zrno padlo podél cesty; i přiletěli ptáci a sezobali je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'A jiné padlo na skalnaté místo, kde nemělo mnoho země, a hned vzešlo, protože nemělo hlubokou zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Když vyšlo slunce, spálilo je; a protože nemělo kořen, uschlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Jiné padlo do trní; trní vzešlo a udusilo je, a zrno nevydalo úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'A jiná padla do dobré země, vzcházela, rostla a vydávala úrodu; a neslo jedno úrodu třicet inásobnou, jedno šedesát inásobnou a jedno sto násobnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'A říkal: „Kdo má uši k slyšení, ať poslouchá!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Když se ocitl o samotě, ptali se ho ti, kdo byli s ním, spolu s Dvanácti, na ta podobenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Říkal jim: „Vám je dáno tajemství Božího království, avšak těm, kteří jsou vně, se to všechno děje v podobenstvích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'aby hledíce hleděli a neuviděli, slyšíce slyšeli a nechápali, neobrátili se ⌈a nebylo jim odpuštěno.⌉“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'A řekl jim: „Nerozumíte tomuto podobenství; jak budete chápat všechna ta podobenství?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Rozsévač rozsévá Slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Tito pak jsou podél cesty, kde se rozsévá Slovo: Když je uslyší, hned přichází Satan a bere Slovo ⌈do nich⌉ zaseté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'A [podobně] tito jsou na skalnatá místa zaséváni: Ti, když uslyší Slovo, hned je s radostí přijímají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'A nemají v sobě kořen, ale jsou nestálí. Když nastane soužení nebo pronásledování pro Slovo, ihned odpadají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'A další jsou ti, kteří jsou rozséváni do trní: To jsou ti, kteří uslyšeli Slovo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'ale potom přicházejí starosti toho to věku, svod bohatství a žádosti po ostatních věcech a dusí Slovo, takže se stává neplodným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Ale tito jsou na dobrou zem zaseti: Slyší Slovo, přijímají je a nesou úrodu, jedni třicet inásobnou, jedni šedesát inásobnou a jedni sto násobnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'A říkal jim: „Zdali přinášejí lampu, aby ji postavili pod nádobu nebo pod postel? Ne proto, aby ji postavili na stojan?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Vždyť [nic] není skryté, než aby bylo zjeveno; ani nic nebylo ukryto, leč aby vyšlo najevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Má–li kdo uši k slyšení, ať poslouchá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'A říkal jim: „Dávejte pozor, co slyšíte. Jakou měrou měříte, takovou bude naměřeno vám a bude vám přidáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Neboť kdo má, tomu bude dáno, a tomu, kdo nemá, bude odňato i to, co má.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'A říkal: „S Božím královstvím je to tak, jako když člověk hodí semeno na zem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'v noci spí a ve dne vstává a semeno klíčí a roste, on ani neví jak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Země sama od sebe plodí, nejprve stéblo, potom klas, potom plné obilí v klasu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'A když úroda dozraje, člověk hned posílá srp, neboť nastala sklizeň.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'A říkal: „K čemu přirovnáme Boží království nebo jakým podobenstvím je znázorníme?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Je jako zrno hořčice. Když je zaseto do země, je menší než všechna semena na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'A když je zaseto, vzchází a stává se větším než všechny zahradní byliny a vytváří velké ratolesti, takže ⌈v jeho stínu⌉ mohou hnízdit nebeští ptáci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'A v mnoha takových podobenstvích k nim mluvil Slovo, jak byli schopni slyšet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Bez podobenství k nim nemluvil, ale v soukromí svým učedníkům všechno vysvětloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Toho dne, když nastal večer, jim říká: „Přeplavme se na druhou stranu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Opustili zástup a vzali ho v té lodi, v níž byl; byly s ním také jiné lodě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Tu nastala veliká větrná bouře a vlny se přelévaly do lodě, takže se loď již naplňovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'A on spal na zádi na podušce. Vzbudili ho a řekli mu: „Učiteli, nezajímá tě, že hyneme?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Probudil se, pohrozil větru a řekl moři: „Mlč, buď zticha!“A vítr přestal a nastal úplný klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Řekl jim: „Proč jste [tak] ustrašení? Ještě nemáte víru?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Padla na ně veliká bázeň a říkali jeden druhému: „Kdo to tedy je, že ho poslouchají i vítr i moře?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Přišli na druhou stranu moře do krajiny Gerasenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'A jak vystoupil z lodi, hned proti němu z hrobů vyšel člověk ⌈s nečistým duchem⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'který měl v hrobech obydlí. Ani řetězy ho již nikdo nemohl spoutat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'neboť byl častokrát spoután okovy a řetězy, ale on vždy řetězy na sobě roztrhal a okovy rozlámal. Nikdo ho nedokázal zkrotit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'A stále dnem i nocí mezi hroby a na horách řval a sekal se kameny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Když Ježíše z dálky uviděl, přiběhl a poklonil se mu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'a silným hlasem zařval: „Co je ti po mně, Ježíši, synu Boha Nejvyššího? Zapřísahám tě při Bohu, netrýzni mne!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Ježíš mu totiž říkal: „Duchu nečistý, vyjdi z toho člověka!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'A tázal se ho: „Jaké je tvé jméno?“Řekl mu: „Mé jméno je Legie, protože je nás mnoho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'A velice ho prosil, aby je neposlal pryč z toho kraje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Tam u hory se páslo veliké stádo vepřů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, '[Všichni ti démoni] ho poprosili: „Pošli nás do těch vepřů, abychom do nich vstoupili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'On jim to dovolil. Nečistí duchové vyšli a vstoupili do těch vepřů. A stádo se zřítilo po svahu do moře, asi dva tisíce kusů, a utopilo se v moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Ti, kteří je pásli, utekli a oznámili to ve městě i ve vesnicích. A lidé přišli, aby se podívali, co se stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Přišli k Ježíši a pozorovali toho démonizovaného, jak sedí oblečený a má zdravou mysl -- toho, který měl Legii -- a ulekli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'A ti, kteří to viděli, jim popsali, jak se to stalo tomu démonizovanému a to o těch vepřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Začali ho prosit, aby odešel z jejich území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Když vstupoval do lodi, prosil ho ten, který byl předtím démonizovaný, aby mohl být s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Nedovolil mu to, ale řekl mu: „Jdi domů ke svým a oznam jim, jak veliké věci ti učinil Pán a jak se nad tebou slitoval.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'On odešel a začal v Dekapoli hlásat, jak veliké věci mu učinil Ježíš; a všichni se divili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Když se Ježíš přeplavil [v lodi] opět na druhou stranu, shromáždil se k němu velký zástup; a byl u moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'A [hle], přišel jeden z představených synagogy, jménem Jairos. Když Ježíše spatřil, padl k jeho nohám');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'a velmi ho prosil: „Má dceruška umírá! Pojď a vlož na ni ruce, aby byla zachráněna a ožila.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Ježíš odešel s ním. Následoval ho velký zástup a tlačili se na něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'A byla tam žena, která měla dvanáct let krvotok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Mnoho vytrpěla od mnoha lékařů a vynaložila všechny své prostředky, nic jí to však neprospělo, ale spíše jí bylo hůře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Když uslyšela o Ježíši, přišla v zástupu zezadu a dotkla se jeho šatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Neboť si říkala: „Jestliže se dotknu třeba jen jeho šatů, budu zachráněna.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'A hned vyschl pramen její krve a pocítila na těle, že je uzdravena ze svého trápení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Ježíš hned v sobě rozpoznal tu moc, která z něho vyšla, otočil se v zástupu a řekl: „Kdo se dotkl mých šatů?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Jeho učedníci mu řekli: „Vidíš, jak se na tebe zástup tlačí, a říkáš: Kdo se mne dotkl?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Ježíš se rozhlížel, aby spatřil tu, která to učinila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Žena se ulekla, a protože věděla, co se jí stalo, s třesením přišla a padla před ním a řekla mu celou pravdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'A on jí řekl: „Dcero, tvá víra tě zachránila. Jdi v pokoji a buď uzdravená ze svého trápení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Zatímco ještě mluvil, přišli z domu představeného synagogy a říkali: „Tvá dcera zemřela; proč ještě obtěžuješ Učitele?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Ale Ježíš neposlechl ⌈to, co říkali⌉, a řekl představenému synagogy: „Neboj se, jen věř!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'A nedovolil nikomu s ním jít, kromě Petra, Jakuba a Jakubova bratra Jana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Přišli do domu představeného synagogy a Ježíš viděl rozruch a ty, kteří velice plakali a hlučně naříkali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Vešel a řekl jim: „Proč se rozrušujete a pláčete? To dítě nezemřelo, ale spí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'I posmívali se mu. Ale on všechny vyhnal a vzal s sebou otce a matku dítěte i ty, kteří byli s ním, a vešel tam, kde bylo dítě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Uchopil ruku dítěte a řekl mu: „Talitha kúm“, což přeloženo znamená: Děvče, říkám ti, vstaň!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'A děvče ihned vstalo a začalo chodit; bylo jí dvanáct let. A zmocnil se jich [ihned] veliký úžas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Ježíš jim důrazně nařídil, aby se to nikdo nedověděl, a řekl, aby jí dali najíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Vyšel odtamtud a přišel do své vlasti; jeho učedníci ho doprovázeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Když nastala sobota, začal učit v synagoze. A mnozí, kteří ho slyšeli, byli ohromeni a říkali: „Odkud to tento člověk má? Jaká je to moudrost, která mu byla dána? A jaké mocné činy se dějí skrze jeho ruce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Není to ten tesař, syn Marie a bratr Jakuba, Josese, Judy a Šimona, a nejsou jeho sestry zde s námi?“A pohoršovali se nad ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Ježíš jim říkal: „Prorok není beze cti, leda ve své vlasti, mezi svými příbuznými a ve svém domě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'A nemohl tam učinit žádný mocný skutek, jen na několik neduživých vložil ruce a uzdravil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'A divil se pro jejich nevěru. A procházel okolní vesnice a učil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Zavolal si Dvanáct a začal je posílat dva a dva a dával jim pravomoc nad nečistými duchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Přikázal jim: „Neberte si nic na cestu, jen hůl, ne chleba, ani mošnu, ani měďáky do opasku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'ale mějte uvázané sandály a neoblékejte si dvojí spodní oděv.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'A říkal jim: „Kdekoli vstoupíte do domu, tam zůstávejte, dokud odtamtud neodejdete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'A když by vás ⌈některé místo nepřijalo⌉ a neposlechli by vás tam, až budete odtamtud vycházet, vytřeste prach zpod svých nohou jim na svědectví. [Amen, pravím vám, v den soudu bude snesitelněji zemi sodomské a gomorské než onomu městu.] “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Vyšli a vyhlásili, aby lidé činili pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Vyháněli mnoho démonů, mazali olejem mnohé neduživé a uzdravovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Uslyšel to král Herodes, neboť se Ježíšovo jméno stalo známým. Říkalo se: „Jan Křtitel vstal z mrtvých, a proto v něm působí ty to moci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Jiní však říkali: „Je to Eliáš!“Jiní zase říkali: „Prorok -- jeden z těch proroků.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Když to uslyšel Herodes, říkal: „Jan, kterého jsem já sťal, vstal [z mrtvých].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Neboť sám Herodes dal Jana zajmout a spoutat ve vězení kvůli Herodiadě, ženě svého bratra Filipa, protože se s ní oženil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Jan totiž Herodovi říkal: „Nesmíš mít ženu svého bratra!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'A Herodias to měla proti němu a chtěla ho zabít, ale nemohla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Herodes se totiž Jana bál, věděl, že je muž spravedlivý a svatý, a ochraňoval ho. Mnohdy, když ho vyslechl, ⌈byl v úzkých, ale⌉ rád mu naslouchal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Vhodný den nastal, když Herodes o svých narozeninách uspořádal hostinu pro své velmože, vojevůdce a přední muže z Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Tu vešla ⌈dcera té Herodiady⌉, zatančila a Herodovi i jeho spolustolovníkům se zalíbila. Král té dívce řekl: „Požádej mě, oč chceš, a dám ti to.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'A zapřísahal se jí: „O cokoliv bys mě požádala, to ti dám, až do polovice svého království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'I vyšla a řekla své matce: „Oč bych měla požádat?“Ona řekla: „O hlavu Jana Křtitele!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'A hned spěšně vešla ke králi a požádala ho: „Chci, abys mi hned dal na míse hlavu Jana Křtitele!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Král se velmi zarmoutil, ale kvůli těm přísahám a spolustolovníkům ji nechtěl odmítnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Král hned poslal kata a nařídil přinést Janovu hlavu. Ten odešel a sťal ho ve vězení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'přinesl na míse jeho hlavu a dal ji té dívce a dívka ji dala své matce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Když to uslyšeli jeho učedníci, přišli, vzali jeho mrtvé tělo a uložili je do hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Apoštolové se shromáždili k Ježíšovi a oznámili mu všechno, co činili i co učili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Řekl jim: „Pojďte vy sami stranou na opuštěné místo a trochu si odpočiňte.“Mnozí totiž stále přicházeli a odcházeli, neměli ani čas se najíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Odjeli tedy v lodi do ústraní na opuštěné místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Mnozí je uviděli odjíždět a poznali je; seběhli se tam pěšky ze všech měst a předešli je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Když vystoupil a uviděl veliký zástup, byl nad nimi hluboce pohnut, protože byli jako ovce, které nemají pastýře. A začal je učit mnohým věcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Když už se připozdilo, přistoupili k němu jeho učedníci a říkali: „Toto místo je opuštěné a je již pozdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Propusť je, aby odešli do okolních statků a vesnic a nakoupili si něco k jídlu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'On jim však odpověděl: „Vy jim dejte najíst!“Řekli mu: „Když odejdeme a nakoupíme za dvě stě denárů chleby, dáme jim najíst?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'On jim řekl: „Kolik máte chlebů? Jděte [a] podívejte se.“Když to zjistili, řekli: „Pět a dvě ryby.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Nařídil jim, aby všechny usadili po skupinách na zelenou trávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Uložili se do řad po stu a do řad po padesáti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Vzal těch pět chlebů a dvě ryby, vzhlédl k nebi, požehnal a rozlámal chleby a dával [svým] učedníkům, aby jim je předkládali. Také ty dvě ryby rozdělil všem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Všichni jedli a nasytili se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'A sebrali plných dvanáct nůší úlomků chleba i ryb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Těch, kteří jedli [ty chleby], bylo pět tisíc mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'A hned přinutil své učedníky, aby nastoupili do lodi a jeli napřed na druhou stranu k Betsaidě, než on propustí zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Rozloučil se s nimi a odešel na horu, aby se pomodlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'A když nastal večer, loď [již] byla uprostřed moře a on sám na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Uviděl je, jak se trápí při veslování, neboť vítr vál proti nim. Okolo čtvrté noční hlídky přicházel k nim kráčeje po moři a chtěl ⌈je minout⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Když ho uviděli, jak kráčí po moři, pomysleli si, že to je přízrak, a vykřikli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Všichni ho totiž uviděli a vyděsili se. On s nimi hned promluvil a řekl jim: „Vzchopte se, to jsem já, nebojte se!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'A nastoupil k nim do lodi a vítr přestal. Byli ve svém nitru naprosto ohromeni [a divili se].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Neboť nepochopili, co jim bylo ukázáno na těch chlebech, ale jejich srdce bylo ztvrdlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Když se přeplavili k zemi, přišli do Genezaretu [a tam zakotvili].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Jakmile vystoupili z lodi, hned jej lidé poznali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Oběhli celou tu krajinu a začali na lehátkách přinášet nemocné tam, kde slyšeli, že je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'A kamkoli vcházel do vesnic nebo do měst nebo do statků, kladli nemocné na tržiště a prosili ho, aby se směli dotknout aspoň třásní jeho šatu, a všichni, kdo se ho dotkli, byli uzdravováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Shromáždili se k němu farizeové a někteří z učitelů Zákona, kteří přišli z Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'A uviděli některé z jeho učedníků, že jedí chleby nečistýma, to jest neomytýma rukama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Farizeové a všichni Židé, držíce tradici starších, totiž nejedí, dokud si ⌈k zápěstí⌉ neumyjí ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Když přijdou z tržiště, nejedí, jestliže se neomyjí. A je ještě mnoho jiného, co převzali a drží: omývání pohárů, džbánů, měděných nádob [a lehátek].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Farizeové a učitelé Zákona se ho ptali: „Proč tvoji učedníci nežijí podle tradice starších, ale jedí chléb nečistýma rukama?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'On jim však řekl: „Dobře prorokoval Izaiáš o vás pokrytcích, jak je napsáno: Tento lid mne ctí rty, ale jejich srdce je ode mne velmi daleko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Marně mne však uctívají, vyučujíce nauky, jež jsou jen lidskými příkazy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Opustili jste přikázání Boží a držíte tradici lidí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'A říkal jim: „Krásně odmítáte přikázání Boží, abyste zachovali svou tradici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Vždyť Mojžíš řekl: Cti svého otce a svou matku a kdo zlořečí otci nebo matce, ať zemře!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Vy však říkáte: Řekne–li člověk otci nebo matce: To z mého majetku, co by ti mohlo pomoci, je korbán, to jest dar určený Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'již mu nedovolujete nic učinit pro [jeho] otce nebo [jeho] matku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Rušíte Boží slovo svou tradicí, kterou jste předali, a takových podobných věcí činíte mnoho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, '⌈Opět k sobě zavolal zástup⌉ a řekl jim: „Poslyšte mne všichni a pochopte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nic, co je vně člověka a vchází do něho, ho nemůže znečistit, ale co z člověka vychází, to je to, co ho znečišťuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, '[Má–li kdo uši k slyšení, ať poslouchá.] “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'A když od zástupu vešel do domu, ptali se ho jeho učedníci na to podobenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Řekl jim: „I vy jste tak nechápaví? Nerozumíte, že vše, co zvnějšku vchází do člověka, ho nemůže znečistit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'protože nevchází do jeho srdce, ale do břicha a vychází ⌈do záchodu?“Tak prohlásil za čistévšechny pokrmy.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Říkal však: „To, co z člověka vychází, to člověka znečišťuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Neboť zevnitř ze srdce lidí vycházejí zlé myšlenky, smilstva, krádeže, vraždy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'cizoložství, hrabivost, špatnosti, lest, bezuzdnost, závist, urážky, pýcha, pošetilost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Všechny tyto špatnosti vycházejí zevnitř a znečišťují člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Pak vstal a odešel odtamtud na území Týru [a Sidónu]. Vstoupil do jednoho domu a nechtěl, aby o tom někdo věděl; nemohl se však skrýt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Ale uslyšela o něm žena, jejíž dcerka měla nečistého ducha; hned přišla a padla k jeho nohám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Ta žena byla Řekyně, rodem Syrofeničanka, a prosila ho, aby toho démona z její dcery vyhnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Říkal jí: „Nech nejprve nasytit děti. Není správné vzít chléb dětem a hodit jej psům.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Ona však odpověděla a říká mu: „ [Ano,] Pane, i psi pod stolem jedí z drobtů po dětech.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Řekl jí: „Kvůli tomuto slovu jdi domů; ten démon z tvé dcery vyšel.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Odešla do svého domu a zjistila, že dítě leží na lůžku a démon vyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Ježíš odešel z území Týru a šel opět přes Sidón ke Galilejskému moři středem území Dekapole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Přivedli k němu hluchého a špatně mluvícího člověka a prosili ho, aby na něho vložil ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Vzal si ho stranou od zástupu, vložil své prsty do jeho uší, plivnul a dotkl se jeho jazyka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'vzhlédl k nebi, vzdychl a řekl mu: „Effatha“, což znamená: Otevři se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'A jeho uši se [hned] otevřely a bylo uvolněno pouto jeho jazyka a začal mluvit správně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Ježíš jim nařídil, aby to nikomu neříkali; čím víc jim to však nařizoval, tím víc to rozhlašovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Byli převelice ohromeni a říkali: „Všechno dobře učinil. Dokonce činí, aby hluší slyšeli a němí mluvili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Když tam byl v těch dnech opět veliký zástup a neměli co jíst, zavolal si učedníky a řekl jim:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '„Jsem hluboce pohnut nad zástupem, protože již tři dny zůstávají se mnou a nemají co jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'A propustím–li je hladové domů, zemdlí na cestě; a někteří z nich přišli zdaleka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Jeho učedníci mu odpověděli: „Odkud by někdo mohl zde v pustině získat tolik chleba, aby nasytil tyto lidi?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Ptal se jich: „Kolik máte chlebů?“Oni řekli: „Sedm.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Nařídil zástupu posadit se na zem. Vzal těch sedm chlebů, vzdal díky, rozlámal a dával svým učedníkům, aby je předkládali; i předložili je zástupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Měli i několik rybiček; požehnal je a řekl, aby i tyto předkládali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Pojedli a nasytili se a sebrali toho, co přebývalo, sedm košů úlomků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, '[Těch, kteří jedli,] bylo asi čtyři tisíce. Pak je propustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'A hned vstoupil se svými učedníky na loď a přišel do oblastí Dalmanuthy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Vyšli proti němu farizeové a začali se s ním přít. Žádali od něho znamení z nebe, aby ho zkoušeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Hluboce povzdechl svým duchem a řekl: „Proč toto pokolení hledá znamení? Amen, pravím vám, tomuto pokolení nebude dáno žádné znamení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'A opustil je, opět vstoupil [do lodi] a odjel na druhou stranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Zapomněli vzít chleby; neměli s sebou na lodi víc než jeden chléb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'A on jim nařizoval: „Dávejte si pozor, varujte se kvasu farizeů a kvasu Herodova.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'I dohadovali se mezi sebou, že nemají chleby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Zpozoroval to a řekl jim: „Proč se dohadujete, že nemáte chleby? Ještě nerozumíte ani nechápete? [Ještě] máte své srdce ztvrdlé?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Oči máte a nevidíte, uši máte a neslyšíte? Nepamatujete si,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'když jsem rozlámal těch pět chlebů pro pět tisíc, kolik nůší plných úlomků jste sebrali?“Řekli mu: „Dvanáct.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '„Když těch sedm pro čtyři tisíce, kolik naplněných košů úlomků jste sebrali?“Řekli mu: „Sedm.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'A říkal jim: „Ještě nechápete?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Pak přišli do Betsaidy. Přivedli k němu slepého a žádali ho, aby se ho dotkl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Ježíš uchopil ruku toho slepého, vyvedl ho z vesnice, a když plivl do jeho očí a vložil na něho ruce, tázal se ho: „Vidíš něco?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'On vzhlédl a říkal: „Vidím lidi, vidím je jako stromy, a chodí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Pak opět vložil ruce na jeho oči a on prohlédl, jeho zrak byl obnoven a viděl všechno zřetelně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'A poslal ho domů se slovy: „Do vesnice teď nevstupuj [ani to nikomu ve vesnici neřekni]!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Ježíš se svými učedníky vyšel do vesnic Cesareje Filipovy. Cestou se svých učedníků ptal: „Za koho mne lidé pokládají?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Oni mu řekli: „ Někteří za Jana Křtitele, jiní za Eliáše a jiní za jednoho z proroků.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'A on se jich tázal: „ A za koho mne pokládáte vy?“Petr mu odpovídá: „Ty jsi Mesiáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Přísně jim domluvil, aby to o něm nikomu neříkali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'A začal je učit, že Syn člověka musí mnoho vytrpět a být zavržen od starších, velekněží a učitelů Zákona, být zabit a po třech dnech vstát z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'A mluvil o tom otevřeně. Petr si ho vzal stranou a začal ho kárat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Když se však Ježíš otočil a uviděl své učedníky, pokáral Petra a řekl: „Jdi ode mne, satane, protože nemáš na mysli věci Boží, ale věci lidské.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'A zavolal si zástup se svými učedníky a řekl jim: „Chce–li kdo jít za mnou, ať zapře sám sebe, vezme svůj kříž a následuje mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Neboť kdo by chtěl svou duši zachránit, zahubí ji; kdo by však zahubil svou duši kvůli [mně a] evangeliu, zachrání ji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Vždyť co člověku prospěje, získá–li celý svět, ale své duši uškodí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Neboť co může dát člověk výměnou za svou duši?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Kdo by se styděl za mne a za má slova v tomto cizoložném a hříšném pokolení, za toho se bude stydět i Syn člověka, když přijde ve slávě svého Otce se svatými anděly.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'A říkal jim: „Amen, pravím vám, že jsou někteří z těch, kdo zde stojí, kteří určitě neokusí smrti, dokud neuvidí Boží království, přišlé v moci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'A po šesti dnech vzal Ježíš s sebou Petra, Jakuba a Jana a je jediné vyvedl na vysokou horu, kde byli sami. A byl před nimi proměněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Jeho šaty se rozzářily a velmi zbělely, tak jak by je žádný bělič na zemi nemohl vybělit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'A ukázal se jim Eliáš s Mojžíšem a rozmlouvali s Ježíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Petr ⌈na to⌉ Ježíšovi řekl: „Rabbi, je pro nás dobré tu být. Udělejme tři stánky, tobě jeden, Mojžíšovi jeden a Eliášovi jeden.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Nevěděl totiž, co by na to řekl, neboť se velmi vyděsili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'A objevil se oblak a zastiňoval je, a z oblaku se ozval hlas: „Toto je můj Syn, ten Milovaný, poslouchejte ho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'A náhle, když se rozhlédli, neviděli u sebe již nikoho, kromě samotného Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'A když sestupovali z hory, nařídil jim, aby to, co spatřili, nikomu nevypravovali, dokud Syn člověka nevstane z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Chytili se toho slova a mezi sebou se tázali, co to znamená vstát z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'A ptali se ho: „Proč učitelé Zákona říkají, že nejprve musí přijít Eliáš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'On jim říkal: „Nejprve opravdu přijde Eliáš a všechno obnoví. Ale jak to, že je napsáno o Synu člověka, že má mnoho vytrpět a být znevážen?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Avšak pravím vám, že Eliáš již nejen přišel, ale také mu učinili, co chtěli, jak je o něm napsáno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'A když přišli k učedníkům, uviděli kolem nich veliký zástup a učitele Zákona, jak se s nimi přou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'A hned ⌈všichni v zástupu⌉, jakmile ho uviděli, byli velmi překvapeni; běželi k němu a zdravili ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'I zeptal se jich: „O čem se s nimi přete?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'A jeden člověk ze zástupu mu odpověděl: „Učiteli, přivedl jsem k tobě svého syna, který má němého ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Kdekoli se ho zmocní, trhá jím, a on pění, skřípe zuby a strne. Řekl jsem tvým učedníkům, aby ho vyhnali, ale nemohli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'On jim na to říká: „Ach, pokolení nevěřící, jak dlouho ještě budu u vás? Jak dlouho ještě vás budu snášet? Při veďte ho ke mně.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'I přivedli ho k němu. Jakmile ho duch spatřil, ihned s ním zalomcoval, chlapec padl na zem, válel se a měl pěnu u úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Ježíš se zeptal jeho otce: „Jak je to dlouho, co se mu to stává?“On řekl: „Od dětství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Často ho hodil i do ohně a do vody, aby ho zahubil. Avšak můžeš–li něco udělat, slituj se nad námi a pomoz nám.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Ježíš mu řekl: „Můžeš–li! Všechno je možné tomu, kdo věří.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Otec toho chlapce hned vykřikl a říkal: „Věřím, pomáhej mé nevíře!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Když Ježíš uviděl, že se sbíhá zástup, pohrozil tomu nečistému duchu: „Duchu němý a hluchý, já ti přikazuji, vyjdi z něho a už do něho nikdy nevstupuj!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Ten vykřikl a silně jím zalomcoval a vyšel. Chlapec zůstal jako mrtvý, takže mnozí říkali, že zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Ježíš uchopil jeho ruku, probudil ho a on vstal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Když Ježíš vešel do domu, jeho učedníci se ho v soukromí ptali: „Proč jsme ho nemohli vyhnat my?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Řekl jim: „Tento rod nemůže vyjít jinak, než v modlitbě [a půstu].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'A vyšli odtamtud a procházeli Galileou a nechtěl, aby ho někdo poznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Vyučoval totiž své učedníky a říkal jim: „Syn člověka je vydáván do rukou lidí a ti ho zabijí. A až bude zabit, ⌈po třech dnech⌉ vstane.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Oni však tomu výroku nerozuměli, ale báli se ho zeptat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'A přišli do Kafarnaum. Když byl v domě, tázal se jich: „O čem jste cestou hovořili?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Oni však mlčeli, neboť se cestou mezi sebou dohadovali, kdo je největší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Posadil se, zavolal Dvanáct a řekl jim: „Chce–li být někdo první, bude poslední ze všech a služebník všech.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'A vzal dítě a postavil je doprostřed nich; pak je vzal do náručí a řekl jim:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '„Kdokoli přijme jedno z takových dětí na základě mého jména, mne přijímá; a kdo by mne přijímal, nepřijímá mne, ale toho, který mne poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Jan mu říkal: „Učiteli, viděli jsme někoho, jak ve tvém jménu vyhání démony, a bránili jsme mu v tom, protože nechodil s námi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Ježíš však řekl: „Nebraňte mu, neboť není nikdo, kdo na základě mého jména učiní mocný čin, aby o mně mohl brzy nato promluvit zle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Vždyť kdo není proti nám, je pro nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Neboť kdo by vám dal napít číši vody proto, že jste Kristovi, amen, pravím vám, že určitě nepřijde o svou odměnu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, '„Ale pro toho, kdo by svedl k hříchu jednoho z těchto maličkých, kteří věří [ve mne], by bylo mnohem lepší, kdyby mu přivázali velký mlýnský kámen na krk a hodili ho do moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Svádí–li tě tvá ruka, utni ji. Lépe je pro tebe do života vejít zmrzačený, než mít obě ruce a odejít do Gehenny do neuhasitelného ohně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, '[kde jejich červ neumírá a oheň nehasne].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'A svádí–li tě tvá noha, utni ji. Lepší je pro tebe do života vejít chromý, než mít obě nohy a být hozen do Gehenny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, '[kde jejich červ neumírá a oheň nehasne].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'A svádí–li tě tvé oko, vyjmi je. Lépe je pro tebe do Božího království vejít jednooký, než mít obě oči a být hozen do Gehenny,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'kde jejich červ neumírá a oheň nehasne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Neboť každý bude osolen ohněm [a každá oběť bude osolena solí].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Sůl je dobrá. Kdyby se však sůl stala neslanou, čím ji ochutíte? Mějte sůl v sobě a žijte mezi sebou pokojně.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Vstal odtamtud a přišel na území Judska a Zajordání. A scházely se k němu opět zástupy a jak byl zvyklý, zase je učil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'A přišli farizeové, aby ho pokoušeli. Ptali se ho, je–li muži dovoleno propustit svou ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'On jim odpověděl: „Co vám přikázal Mojžíš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Oni pak řekli: „Mojžíš dovolil napsat rozlukový list a propustit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Ježíš jim řekl: „Pro tvrdost vašeho srdce vám napsal toto přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Od počátku stvoření je [Bůh] učinil jako muže a ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Proto opustí člověk svého otce i matku [a přilne ke své ženě].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'A budou ti dva jedno tělo, takže již nejsou dva, ale jedno tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Co tedy Bůh spojil, ať člověk neodděluje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'V domě se ho na to učedníci opět ptali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Řekl jim: „Kdo by propustil svou ženu a oženil se s jinou, cizoloží vůči ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'A jestliže by ona propustila svého muže a provdala se za jiného, cizoloží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'A přinášeli k němu děti, aby se jich dotkl. Učedníci je však pokárali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Když to Ježíš uviděl, rozhořčil se a řekl jim: „Nechte děti přicházet ke mně, nebraňte jim, neboť takových je Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Amen, pravím vám, kdo nepřijme Boží království jako dítě, jistě do něho nevstoupí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'A bral je do náručí, vkládal na ně ruce a žehnal [jim].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'A když vycházel na cestu, přiběhl jeden člověk, poklekl před ním a ptal se ho: „Dobrý učiteli, co mám učinit, abych získal věčný život?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Ježíš mu řekl: „Proč mne nazýváš dobrým? Nikdo není dobrý, jen jediný: Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Přikázání znáš: Abys nezabil, nezcizoložil, neukradl, nevydal křivé svědectví, [nepodvedl]; cti svého otce a matku.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'On mu řekl: „Učiteli, toto všechno zachovávám od svého mládí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Ježíš na něho pohlédl, ⌈zamiloval si ⌉ ho a řekl mu: „Jedno ti chybí: Jdi, prodej všechno, co máš, a dej chudým a budeš mít poklad v nebi; pak přijď a následuj mne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'On se nad tím slovem zachmuřil a se zármutkem odešel, neboť měl mnoho majetku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Ježíš se rozhlédl a řekl svým učedníkům: „Jak těžko vcházejí do Božího království ti, kteří mají majetek.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Učedníci se při jeho slovech děsili. Ježíš jim zase na to řekl: „Děti, jak nesnadné je [pro ty, kteří spoléhají na majetek,] vejít do Božího království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Snadnější je, aby velbloud prošel uchem jehly, než aby bohatý vešel do Božího království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Oni byli velice ohromeni a říkali ⌈ si mezi sebou⌉: „A kdo může být zachráněn?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Ježíš na ně pohleděl a řekl: „U lidí je to nemožné, ale ne u Boha. Neboť u Boha je možné všechno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Petr mu začal říkat: „Hle, my jsme opustili všechno a následujeme tě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Ježíš říkal: „Amen, pravím vám, není nikdo, kdo opustil dům nebo bratry nebo sestry nebo matku nebo otce nebo děti nebo pole kvůli mně a kvůli evangeliu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'aby nyní v tomto období nedostal stokrát více domů, bratrů a sester, matek a dětí a polí s pronásledováními a v přicházejícím věku život věčný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mnozí první budou poslední a poslední první.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Byli na cestě, vystupovali do Jeruzaléma a Ježíš šel před nimi; a děsili se a ti, kteří je doprovázeli, se báli. Opět si k sobě vzal Dvanáct a začal jim říkat, co se mu má přihodit:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '„Hle, vystupujeme do Jeruzaléma; Syn člověka bude vydán velekněžím a učitelům Zákona a odsoudí ho k smrti a vydají ho pohanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Budou se mu posmívat, plivat na něho, zbičují ho a zabijí; a po třech dnech vstane z mrtvých.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Přistoupili k němu Jakub a Jan, synové Zebedeovi, a řekli mu: „Učiteli, chceme, abys nám učinil, o cokoli tě požádáme.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'On pak jim řekl: „Co chcete, abych vám učinil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Oni mu řekli: „Dej nám, abychom se ve tvé slávě posadili jeden po tvé pravici a jeden po tvé levici.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Ježíš jim řekl: „Nevíte, co žádáte. Můžete pít kalich, který já piji, nebo být pokřtěni křtem, kterým já jsem křtěn?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Oni mu řekli: „Můžeme.“Ježíš jim řekl: „Kalich, který já piji, budete pít a křtem, kterým já jsem křtěn, budete křtěni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Není však má věc, dát někomu usednout po mé pravici nebo levici, ale usednou tam ti, pro které je to připraveno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Když to uslyšelo těch deset, začali být na Jakuba a Jana rozmrzelí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Ježíš si je zavolal a řekl jim: „Víte, že ti, kteří se zdají být vládci pohanů, panují nad nimi a jejich velcí nad nimi ⌈vykonávají svou svrchovanou moc⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Avšak ne tak je tomu mezi vámi, ale kdo by se chtěl mezi vámi stát velkým, bude vaším služebníkem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'a kdo by chtěl být mezi vámi první, bude otrokem všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Vždyť ani Syn člověka nepřišel, aby si nechal posloužit, ale aby posloužil a dal svůj život jako výkupné za mnohé.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Přišlido Jericha. A když se svými učedníky a dosti velikým zástupem vycházel z Jericha, seděl u cesty syn Timaiův, Bartimaios, slepý žebrák.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'A když uslyšel, že je to Ježíš Nazaretský, začal křičet: „Synu Davidův, Ježíši, smiluj se nade mnou!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Mnozí mu přísně domlouvali, aby zmlkl, ale on o to víc křičel: „Synu Davidův, smiluj se nade mnou!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Ježíš se zastavil a řekl: „Zavolejte ho.“Zavolali toho slepého a řekli mu: „Vzchop se, vstaň, volá tě!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'On odhodil svůj plášť, vyskočil a přišel k Ježíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Ježíš mu odpověděl: „Co chceš, abych ti učinil?“Slepý mu řekl: „Rabbuni, ať vidím!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'A Ježíš mu řekl: „Jdi, tvá víra tě uzdravila.“A hned prohlédl a šel tou cestou za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'A když se přiblížili k Jeruzalému, k Betfage a Betanii u Olivové hory, poslal dva ze svých učedníků');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'a řekl jim: „Jděte do protější vesnice, a hned jak do ní vejdete, naleznete uvázané oslátko, na které se ještě nikdo z lidí neposadil. Odvažte je a přiveďte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'A jestliže vám někdo řekne: Co to děláte? řekněte: ⌈ Pán je potřebuje a hned je sem zase pošle. ⌉“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Odešli a nalezli oslátko uvázané venku na ulici u dveří a odvázali je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'A někteří z těch, kteří tam stáli, jim říkali: „Co to děláte, že odvazujete to oslátko?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Oni jim řekli, jak řekl Ježíš, a ti je nechali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'A přivedli oslátko k Ježíšovi, hodili na ně svá roucha a on se na ně posadil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'A mnozí rozprostřeli na cestu svá roucha, jiní pak ratolesti, které nařezali na polích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Ti, kteří šli vpředu, i ti, kteří šli za ním, křičeli: „Hosana! Požehnaný, který přichází ve jménu Pána!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Požehnané přicházející království našeho otce Davida! Hosana na výsostech!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'A vstoupil do Jeruzaléma do chrámu a rozhlédl se po všem. Protože již bylo pozdě, vyšel s Dvanácti do Betanie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Když následujícího dne vyšli z Betanie, dostal hlad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'A z dálky uviděl fíkovník, který měl listí, a přišel, zdali na něm něco nenalezne. Když k němu přišel, nenalezl nic, jen listí; nebylo totiž období fíků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'I řekl mu: „Ať již navěky z tebe nikdo ovoce nejí!“A jeho učedníci to slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'A přišli do Jeruzaléma. Vešel do chrámu a začal vyhánět ty, kteří v chrámu prodávali a kupovali, a zpřevracel stoly směnárníků a sedadla prodavačů holubů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'A nedovoloval, aby někdo skrze chrám pronesl nějaké zboží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Učil a říkal jim: „Což není napsáno: Můj dům bude nazván domem modlitby pro všechny národy? Vy jste jej však učinili jeskyní lupičů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Uslyšeli to velekněží a učitelé Zákona a hledali, jak by ho zahubili, neboť se ho báli; celý ten zástup byl totiž nad jeho učením ohromen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Když nastal večer, vycházeli ven z města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'A když šli ráno kolem, uviděli ten fíkovník uschlý od kořenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Petr se rozpomenul a řekl mu: „Rabbi, hleď, ten fíkovník, který jsi proklel, je uschlý.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Ježíš jim na to řekl: „Mějte víru Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Amen, pravím vám, že kdo by řekl této hoře: Zvedni se a vrhni se do moře a nezapochyboval by ve svém srdci, ale věřil by, že co říká, se děje, bude to mít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Proto vám pravím: Věřte, že jste všechno, za cokoliv se modlíte a oč žádáte, přijali, a budete to mít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'A kdykoliv stojíte a modlíte se, odpouštějte, máte–li proti někomu něco, aby vám i váš Otec, který je v nebesích, odpustil vaše přestoupení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, '');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'A přišli opět do Jeruzaléma, a když se procházel v chrámu, přišli k němu velekněží, učitelé Zákona a starší');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'a říkali mu: „V jaké pravomoci to činíš? A kdo ti dal tuto pravomoc, abys to činil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Ježíš jim řekl: „Zeptám se vás na jednu věc; odpovězte mi a řeknu vám, v jaké pravomoci to činím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Křest Janův byl z nebe, nebo z lidí? Odpovězte mi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Dohadovali se mezi sebou:„Řekneme–li z nebe, řekne: Proč jste mu [tedy] neuvěřili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Máme říci z lidí?“Báli se zástupu, neboť všichni skutečně měli za to, že Jan byl prorok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Odpověděli tedy Ježíšovi: „Nevíme.“A Ježíš jim řekl: „Ani já vám nepovím, v jaké pravomoci tyto věci činím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'A začal k nim mluvit v podobenstvích. „ Jeden člověk vysadil vinici, obehnal zdí, vykopal jámu pro lis, vystavěl věž, pronajal ji vinařům a odcestoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'V stanovený čas poslal k vinařům otroka, aby pře vzal od vinařů díl z úrody vinice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Chytili ho, zbili a poslali s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Znovu k nim poslal jiného otroka a toho zranili na hlavě a potupili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Poslal jiného, toho zabili; poslal i mnoho dalších, z nichž některé bili, jiné zabíjeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Měl ještě jednoho, [svého] milovaného syna. Naposled k nim poslal jeho a říkal: ⌈Zastydí se před mým synem.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Ti vinaři si však řekli: To je dědic. Pojďte, zabijme ho a dědictví bude naše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'A chytili ho, zabili a vyhodili ho ven z vinice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Co tedy učiní pán vinice? Přijde, zahubí ty vinaře a vinici dá jiným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Ani toto Písmo jste nečetli: Kámen, který stavitelé po prozkoumání zavrhli, ten se stal hlavou úhlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Od Pána se to stalo a je to podivuhodné v našich očích?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Chtěli se ho zmocnit, ale báli se zástupu. Poznali totiž, že to podobenství řekl proti nim. I opustili ho a odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Poslali k němu některé z farizeů a herodiánů, aby ho chytili za slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Přišli a řekli mu: „Učiteli, víme, že jsi pravdivý a nedbáš na nikoho, neboť ⌈nebereš ohled na postavení člověka⌉, ale v pravdě učíš cestě Boží. Je dovoleno dát daň císaři, nebo ne? Máme ji dát, či ji dát nemáme?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'On však znal jejich přetvářku a řekl jim: „Proč mne zkoušíte? Přineste mi denár, abych se podíval.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Oni jej přinesli a Ježíš jim řekl: „Čí je ten obraz a nápis?“Oni mu řekli: „Císařův.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Ježíš jim řekl: „Co je císařovo, odevzdejte císaři, a co je Boží, Bohu.“Velice se nad ním divili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Přišli k němu saduceové, kteří říkají, že není vzkříšení, a ptali se ho:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '„Učiteli, Mojžíš nám napsal, že zemře–li něčí bratr a zanechá ženu, ale nezanechá dítě, aby si tu ženu vzal za manželku jeho bratr a vzbudil svému bratru potomka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Bylo sedm bratrů. První si vzal ženu, zemřel a nezanechal potomka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'I druhý si ji vzal, zemřel a nezanechal potomka; a třetí stejně tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Těch sedm bratrů nezanechalo potomka; poslední ze všech zemřela i ta žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, '[Když vstanou] při vzkříšení z mrtvých, komu z nich ta žena bude patřit? Vždyť všech sedm ji mělo za ženu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Ježíš jim říkal: „Nebloudíte právě proto, že neznáte Písma ani Boží moc?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Neboť když vstanou z mrtvých, nežení se ani se nevdávají, ale jsou jako andělé v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'O mrtvých pak, že vstávají, jste nečetli v Mojžíšově knize, jak mu u keře Bůh řekl: Já jsem Bůh Abrahamův, Bůh Izákův a Bůh Jákobův?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Není Bohem mrtvých, ale žijících. Velmi bloudíte!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Tu přistoupil jeden z učitelů Zákona, který je uslyšel, jak se spolu dohadují. Když uviděl, že jim Ježíš dobře odpověděl, zeptal se ho: „Které přikázání je první ze všech?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Ježíš odpověděl: „První je: Slyš, Izraeli, Pán, náš Bůh, Pán jediný jest');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'a budeš milovat Pána, svého Boha, z celého svého srdce, z celé své duše, z celé své mysli a z celé své síly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Druhé je toto: Budeš milovat svého bližního jako sebe samého. Není jiné přikázání větší než tato.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'I řekl mu ten učitel Zákona: „Dobře, Učiteli, pravdivě jsi řekl, že je jediný a není jiného mimo něho');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'a milovat ho z celého srdce, z celého porozumění, z celé síly a milovat bližního jako sebe je větší než všechny celopaly a oběti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Když Ježíš uviděl, že odpověděl uváženě, řekl mu: „Nejsi daleko od Božího království.“A nikdo se ho již neodvažoval zeptat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'A když Ježíš odpověděl, začal vyučovat v chrámě: „Jak to, že učitelé Zákona říkají, že Kristus je syn Davidův?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Sám David řekl v Duchu Svatém: Řekl Pán mému Pánu: Seď po mé pravici, dokud nepoložím tvé nepřátele ⌈za podnož tvých nohou⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Sám David ho nazývá Pánem; jakpak je tedy jeho synem?“A velký zástup mu rád naslouchal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Ve svém učení říkal: „Varujte se učitelů Zákona, kteří se chtějí procházet v dlouhých rouchách a ⌈být pozdravováni⌉ na tržištích');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'a chtějí přední sedadla v synagogách a přední místa na hostinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Vyjídají domy vdov a okázale se dlouho modlí; ti dostanou větší odsouzení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, '[Ježíš] se posadil proti pokladnici a pozoroval, jak zástup vhazuje do pokladnice měděné mince. A mnozí bohatí vhazovali hodně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'A přišla jedna chudá vdova a vhodila do ní dvě lepta, což je kvadrans.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Přivolal své učedníky a řekl jim: „Amen, pravím vám, že tato chudá vdova dala víc než všichni ostatní, kteří vhazovali do pokladnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Všichni totiž dali ze svého přebytku, tato však ze svého nedostatku dala vše, co měla, celé svoje živobytí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Když vycházel z chrámu, řekl mu jeden z jeho učedníků: „Učiteli, pohleď, jaké kameny a jaké stavby!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Ježíš mu řekl: „Hledíš na tyto veliké stavby? Jistě [zde] nezůstane kámen na kameni, který by nebyl stržen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'A když seděl na Olivové hoře naproti chrámu, ptali se ho v soukromí Petr, Jakub, Jan a Ondřej:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '„Pověz nám, kdy to bude a jaké bude znamení, až se to všechno začne naplňovat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Ježíš jim začal říkat: „Dávejte si pozor, aby vás někdo nesvedl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, '[Neboť] mnozí přijdou ⌈v mém jménu⌉ a budou říkat: Já jsem a svedou mnohé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Když uslyšíte o válkách a válečné zvěsti, neděste se, musí to nastat, ale ještě ne bude konec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Povstane totiž národ proti národu a království proti království. Na různých místech budou země třesení, budou hladomory [a nepokoje]. To bude začátek porodních bolestí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Vy se však mějte na pozoru. Budou vás vydávat ⌈soudům a do synagog, budete biti a⌉ kvůli mně budete stavěni před vladaře a krále, jim na svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Všem národům musí být nejprve vyhlášeno evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'A když vás budou vodit a vydávat, nestarejte se předem, co byste řekli, ale co by vám v tu hodinu bylo dáno, to mluvte. Neboť to nejste vy, kdo mluví, ale Duch Svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'A vydá na smrt bratr bratra a otec dítě, děti povstanou proti rodičům a usmrtí je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'A všichni vás budou nenávidět pro mé jméno. Kdo však vytrvá do konce, ten bude zachráněn.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, '„Když pak uvidíte ohavnost zpustošení postavenou, kde nemá být -- kdo čte, ať rozumí -- tehdy ti, kteří budou v Judsku, ať utíkají do hor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Kdo bude na střeše, ať nesestupuje a nevstupuje dovnitř, aby si vzal něco ze svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'A kdo bude na poli, ať se neobrací k věcem, které jsou vzadu, aby si vzal svůj plášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Běda těhotným a kojícím v oněch dnech!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Modlete se, aby [k vašemu útěku] nedošlo v zimě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Neboť v oněch dnech bude takové soužení, jaké nenastalo od počátku stvoření, které stvořil Bůh, až do dneška a nikdy již nenastane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'A kdyby Pán nezkrátil ty dny, nebylo by zachráněno žádné tělo. Ale kvůli vyvoleným, které vyvolil, zkrátil ty dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'A tehdy, když by vám někdo řekl: Hle, zde je Kristus!, [nebo:] Hle, tam!, nevěřte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Neboť povstanou falešní kristové a falešní proroci a budou činit znamení a divy, aby, kdyby to bylo možné, svedli vyvolené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Vy se tedy mějte na pozoru. Všechno jsem vám již předem řekl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, '„Ale v oněch dnech, po onom soužení se zatmí slunce a měsíc nebude vydávat svou zář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Hvězdy budou padat z nebe a mocnosti, které jsou v nebesích, se zatřesou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'A potom uvidí Syna člověka přicházejícího v oblacích s velikou mocí a slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'A tehdy pošle anděly a shromáždí své vyvolené ze čtyř větrů od nejzazšího konce země až po nejzazší konec nebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, '„Od fíkovníku se naučte podobenství: Když již jeho větev změkne a vyhání listy, víte, že léto je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Tak i vy, když uvidíte, že se tyto věci dějí, vězte, že je to blízko, přede dveřmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Amen, pravím vám, že určitě nepomine toto pokolení, dokud se toto všechno nestane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Nebe a země pominou, ale má slova jistě nepominou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, '„O tom dni či hodině nikdo neví, ani andělé v nebi, ani Syn, jedině Otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Dávejte si pozor, bděte [a modlete se], neboť nevíte, kdy je ten určený čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Jako člověk, který je na cestách: opustil svůj dům, dal svým otrokům plnou moc, každému jeho práci a dveřníkovi přikázal, aby bděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Bděte tedy, neboť nevíte, kdy Pán domu přijde, zda večer, či o půlnoci, nebo za kuropění, či před rozbřeskem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'aby nepřišel neočekávaně a nenalezl vás spící.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Co tedy říkám vám, říkám všem: Bděte!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Byly dva dny před ⌈Hodem beránka⌉ a svátky nekvašených chlebů. Velekněží a učitelé Zákona hledali, jak by se ho lstí zmocnili, aby ho zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Říkali totiž: „Ne ve svátek, aby snad nebylo pobouření lidu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Když byl v Betanii v domě Šimona Malomocného a byl u stolu, vešla žena, která měla alabastrovou nádobku pravého, velmi drahého nardového oleje; rozbila tu nádobku a olej vylila na jeho hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Někteří se mezi sebou rozhořčovali: „K čemu je ta ztráta oleje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Vždyť se ten olej mohl prodat za víc než tři sta denárů a ty dát chudým!“A hněvali se na ni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Ježíš řekl: „Nechte ji. Proč jí působíte těžkosti? Vykonala na mně dobrý skutek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Vždyť chudé máte stále s sebou, a kdykoli chcete, můžete jim učinit dobře; mne však nemáte stále.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Učinila, co mohla; předem pomazala mé tělo olejem k pohřbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Amen, pravím vám, kdekoli po celém světě bude hlásáno [toto] evangelium, bude se na její památku mluvit také o tom, co ona učinila.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'A Juda Iškariotský, jeden z Dvanácti, odešel k velekněžím, aby jim ho vydal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Když to uslyšeli, zaradovali se a slíbili mu dát peníze. I hledal vhodnou příležitost, jak by jim ho vydal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Prvního dne nekvašených chlebů, když obětovali ⌈velikonočního beránka⌉, mu řekli jeho učedníci: „Kam chceš, abychom odešli a připravili ti k jídlu ⌈velikonočního beránka⌉?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'I poslal dva ze svých učedníků a řekl jim: „Jděte do města a potká vás člověk, který ponese džbán vody. Jděte za ním');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'a tam, kam vejde, řekněte hospodáři: Učitel říká: Kde je moje místnost, kde bych se svými učedníky pojedl ⌈velikonočního beránka⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'A on vám ukáže velkou horní místnost, již prostřenou a připravenou, a tam nám připravte jídlo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Učedníci vyšli, přišli do města a nalezli vše, jak jim řekl, i připravili ⌈velikonočního beránka⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Když nastal večer, přišel s Dvanácti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'A když byli u stolu a jedli, Ježíš řekl: „Amen, pravím vám, že jeden z vás mne zradí, ten, který jí se mnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Začali se rmoutit a jeden po druhém mu říkali: „Snad ne já?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'On jim řekl: „Jeden z Dvanácti, který se mnou namáčí v míse.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Syn člověka opravdu odchází, jak je o něm napsáno, běda však onomu člověku, skrze kterého je Syn člověka zrazován. ⌈Pro toho [by bylo] lépe, kdyby se byl⌉ nenarodil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'A když jedli, vzal [Ježíš] chléb, požehnal a rozlomil, dal jim a řekl: „Vezměte, toto je mé tělo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Pak vzal kalich, vzdal díky a dal jim; a napili se z něj všichni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'A řekl jim: „Toto je má krev [nové] smlouvy, která se vylévá za mnohé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Amen, pravím vám, že se [již více] nenapiji z plodu vinné révy až do onoho dne, kdy jej budu pít nový v Božím království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'A zazpívali chvalozpěv a vyšli na Olivovou horu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'A Ježíš jim řekl: „Všichni [ode mne této noci] odpadnete, neboť je napsáno: Budu bít pastýře a ovce stáda se rozptýlí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Ale po svém vzkříšení vás předejdu do Galileje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Petr mu říkal: „I kdyby všichni odpadli, já však ne!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'A Ježíš mu řekl: „Amen, pravím tobě, že dnes, této noci, dříve než kohout [dvakrát] zakokrhá, právě ty mne třikrát zapřeš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'On však tím více říkal: „I kdybych s tebou musel zemřít, určitě tě nezapřu.“Stejně mluvili i ostatní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'I přicházejí k místu jménem Getsemane. Říká svým učedníkům: „Posaďte se zde, než se pomodlím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'A vzal s sebou Petra, Jakuba a Jana a začal se děsit a znepokojovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Říká jim: „Má duše je smutná až k smrti. Zůstaňte zde a bděte!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Trochu poodešel, padal na zem a modlil se, aby ho, je–li to možné, tato hodina minula.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Říkal: „Abba, Otče, tobě je všechno možné, přenes tento kalich ode mne, ale ne, co chci já, ale co ty.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'A přišel a nalezl je spící. Říká Petrovi: „Šimone, spíš? Nemohl jsi jedinou hodinu bdít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Bděte a modlete se, abyste nevešli do pokušení. Duch je sice ochotný, ale tělo slabé.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'A opět odešel a pomodlil se, říkaje stejnou prosbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'A opět, když přišel, nalezl je spící; měli velmi těžká víčka a nevěděli, co by mu odpověděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'A přichází po třetí a říká jim: „Ještě spíte a odpočíváte? To stačí. Přišla ta hodina, hle, Syn člověka je vydáván do rukou hříšníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Vstávejte, pojďme! Hle, ⌈přiblížil se ten, který mne zrazuje.⌉“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'A hned, když ještě mluvil, přichází Juda, jeden z Dvanácti, a s ním zástup od velekněží, učitelů Zákona a starších, s meči a holemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Ten, který ho zrazoval, ⌈měl s nimi domluvené znamení⌉: „Koho políbím, ten to je. Zmocněte se ho a bezpečně odveďte!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Když přišel, hned k němu přistoupil a řekl: „Rabbi!“A vroucně ho políbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Oni pak na něho vztáhli ruce a zmocnili se ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Jeden z okolostojících tasil meč, udeřil veleknězova otroka a uťal mu ucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Ježíš jim na to řekl: „Vyšli jste s meči a holemi jako na lupiče, abyste mne zatkli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Den co den jsem vyučoval u vás v chrámě, a nezmocnili jste se mne. Ale ⌈musí se naplnit⌉ Písma.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'A všichni ho opustili a utekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Šel s ním nějaký mladík, který měl přes nahé tělo přehozený lněný šat, i zmocnili se ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'On tam však zanechal lněný šat a utekl [od nich] nahý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Ježíše odvedli k veleknězi a shromáždili se [k němu] všichni velekněží, starší a učitelé Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Petr došel zpovzdálí za ním až dovnitř do veleknězova dvora, seděl pak se služebníky a ohříval se u ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Velekněží a celá velerada hledali proti Ježíšovi svědectví, aby ho odsoudili k smrti, ale nenalézali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Neboť mnozí proti němu křivě svědčili, ale jejich svědectví nebyla stejná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Někteří povstali a křivě proti němu svědčili:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '„My jsme ho uslyšeli, jak říká: Já zbořím tuto svatyni udělanou rukama a ve třech dnech vybuduji jinou, ne rukama udělanou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'A ani tak jejich svědectví nebylo shodné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'I povstal uprostřed velekněz a zeptal se Ježíše: „Nic neodpovídáš? Co tito lidé proti tobě svědčí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'On však mlčel a nic neodpovídal. Znovu se ho velekněz otázal a řekl mu: „Jsi ty Mesiáš, Syn Požehnaného?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Ježíš řekl: „Já jsem. A spatříte Syna člověka sedícího po pravici Moci a přicházejícího s nebeskými oblaky.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Velekněz roztrhl svá roucha a říká: „Nač ještě potřebujeme svědky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Slyšeli jste rouhání. Jak se vám to jeví?“Všichni ho odsoudili, že je hoden smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'A někteří na něho začali plivat, zahalovat mu tvář, bít ho pěstmi a říkat mu: „Zaprorokuj!“A biřici ho zasypali ranami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'A zatímco byl Petr dole v nádvoří, přišla jedna z veleknězových služek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Když uviděla Petra, jak se ohřívá, pohlédla na něj a řekla: „I ty jsi byl s Nazaretským, tím Ježíšem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'On však zapřel: „Nevím ani nerozumím, co říkáš.“A vyšel ven do předního dvora [a kohout zakokrhal].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'A když ho ta služka uviděla, začala opět říkat těm, kteří stáli poblíž: „Tento je z nich.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'On však opět zapíral. A za malou chvíli znovu ti, co stáli poblíž, říkali Petrovi: „Skutečně jsi jeden z nich, vždyť jsi také Galilejec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'On se pak začal zaklínat a zapřísahat: „Neznám toho člověka, o kterém mluvíte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'A [hned] kohout [podruhé] zakokrhal. Tu si Petr rozpomněl na výrok, jak mu Ježíš řekl: „Než kohout dvakrát zakokrhá, třikrát mne zapřeš,“a ⌈začal plakat⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'A hned časně zrána ⌈velekněží se staršími a učitelé Zákona⌉ -- celá velerada -- ⌈se poradili⌉, Ježíše spoutali, odvedli a vydali Pilátovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Pilát se ho otázal: „Ty jsi král Židů?“On mu odpověděl: „Ty říkáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Velekněží ho velmi obviňovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilát se ho znovu zeptal: „Nic neodpovídáš? Podívej, z čeho všeho tě obviňují!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Ježíš však již nic neodpověděl, takže se Pilát divil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'O svátcích jim propouštěl jednoho vězně, o kterého žádali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Se vzbouřenci, kteří se při vzpouře dopustili vraždy, byl uvězněný muž zvaný Barabáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Zástup ⌈vystoupil k Pilátovi ⌉ a začal žádat, aby učinil, jak jim činíval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilát jim odpověděl: „Chcete, abych vám propustil krále Židů?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Uvědomoval si totiž, že ho [velekněží] vydali ze závisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Velekněží však podnítili zástup, aby jim raději propustil Barabáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilát jim zase na to říkal: „Co tedy [chcete,] abych učinil s [tím, kterého nazýváte] králem Židů?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Oni opět zvolali: „Ukřižuj ho!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilát jim říkal: „Co tedy udělal zlého?“Oni pak ještě silněji zvolali: „Ukřižuj ho!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilát pak, chtěje vyhovět zástupu, jim propustil Barabáše; Ježíše dal zbičovat a vydal ho, aby byl ukřižován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Vojáciho odvedli do dvora, to jest do pretoria, a svolali celý oddíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Oblékli mu purpur, upletli trnový věnec a nasadili mu jej');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'a začali ho zdravit: „Buď zdráv, králi Židů!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Bili ho po hlavě rákos ovou holí, plivali na něj, poklekali a klaněli se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Když se mu naposmívali, svlékli ho z purpuru a oblékli mu jeho šaty. Vyvedli ho, aby ho ukřižovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'A přinutili kolemjdoucího Šimona z Kyrény, otce Alexandra a Rufa, jdoucího z pole, aby vzal jeho kříž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Přivedli ho na místo zvané Golgota, což v překladu znamená Místo lebky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Dávali mu [pít] víno smíchané s myrhou, ale on je nepřijal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Pak jej ukřižovali a dělili si jeho šaty, losujíce o ně, kdo si co vezme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Byla třetí hodina, když ho ukřižovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'A byl ⌈napsán nápis o jeho vině⌉: Král Židů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Spolu s ním byli ukřižováni dva lupiči, jeden po pravici a druhý po jeho levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, '[Naplnilo se Písmo, které praví: Byl započten mezi bezzákonné.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'A kolemjdoucí ho uráželi, potřásali hlavou a říkali: „Ó, ty, který boříš svatyni a ve třech dnech ji stavíš!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Sestup s kříže a zachraň se!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Podobně se i velekněží a učitelé Zákona mezi sebou posmívali a říkali: „Jiné zachránil, sebe zachránit nemůže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Ať nyní Kristus, král Izraele, sestoupí s kříže, abychom uviděli a uvěřili.“Také ti, kteří byli ukřižováni spolu s ním, ho haněli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'A když nastala šestá hodina, padla tma na celou zemi až do deváté hodiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'O deváté hodině Ježíš zvolal silným hlasem: „Eloi, Eloi, lema sabachthani?“což v překladu znamená: Můj Bože, můj Bože, proč jsi mne opustil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'A když to uslyšeli někteří z těch, kdo stáli poblíž, říkali: „Hle, volá Eliáše.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Kdosi pak vyběhl, naplnil houbu octem, připevnil na rákos ovou hůl a dával mu pít se slovy: „Nechte ho, ať uvidíme, přijde–li Eliáš, aby ho sundal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Ježíš vydal mocný hlas a ⌈vydechl naposled ⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'A opona svatyně se roztrhla ve dví odshora až dolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Když setník, který stál blízko naproti němu, uviděl, že takto vydechl, řekl: „Tento člověk byl opravdu Boží Syn.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Zdaleka se dívaly také ženy, mezi nimi Marie Magdalská a Marie, matka Jakuba mladšího a Josese, a Salome,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'které chodily s ním a sloužily mu, když byl v Galileji, a mnoho jiných, které spolu s ním vystoupily do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'A když již nastal večer, poněvadž byl den přípravy, to jest den před sobotou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'přišel Josef z Arimatie, vážený člen rady, který také sám očekával Boží království. Osmělil se, vešel k Pilátovi a požádal o Ježíšovo tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilát se podivil, že by byl již mrtev. Zavolal si setníka a otázal se ho, ⌈je–li to dlouho, co ⌉ zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'A když se to od setníka dověděl, daroval mrtvé tělo Josefovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Ten nakoupil jemné plátno, sundal ho s kříže, zavinul tím plátnem a uložil ho v hrobce, která byla vytesána ve skále, a ke vchodu do hrobky přivalil kámen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Marie Magdalská a Marie [matka] Josesova pozorovaly místo, kam byl uložen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Když uplynula sobota, Marie Magdalská, Marie [matka] Jakubova a Salome nakoupily vonné látky, aby přišly a pomazaly ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'A časně ráno prvního dne týdne, když vyšlo slunce, přicházely k hrobce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'A říkaly si: „Kdo nám odvalí kámen od vchodu do hrobky?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'A vzhlédly a vidí, že kámen je odvalen; byl totiž velmi veliký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Když vstoupily do hrobky, spatřily mládence sedícího po pravé straně, oděného bílým rouchem, a vyděsily se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'On pak jim řekl: „Neděste se. Hledáte Ježíše Nazaretského, toho ukřižovaného. Byl vzkříšen z mrtvých, není tu. Hle, místo, kam ho položili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Ale jděte a povězte jeho učedníkům i Petrovi: Jde před vámi do Galileje; tam ho spatříte, tak jak vám řekl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Vyšly a utekly od hrobky; zmocnilo se jich totiž třesení a byly zcela bez sebe. A nikomu nic neřekly, neboť se bály.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Ráno prvního dne týdne, když Ježíš vstal, ukázal se nejprve Marii Magdalské, od níž kdysi vyhnal sedm démonů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ona šla a oznámila to těm, kteří byli s ním a kteří teď plakali a truchlili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'A oni, když uslyšeli, že opět žije a že ho spatřila, neuvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Potom se v jiném způsobu ukázal dvěma z nich cestou, když šli na pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'A oni odešli a oznámili to ostatním, ale ani těmto neuvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Nakonec se ukázal Jedenácti, když byli u stolu; pokáral jejich nevěru a tvrdost srdce, protože neuvěřili těm, kteří ho spatřili vzkříšeného [z mrtvých].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'A řekl jim: „Jděte do celého světa a vyhlašte evangelium všemu stvoření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kdo uvěří a bude pokřtěn, bude zachráněn. Kdo neuvěří, bude odsouzen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Tato znamení budou doprovázet ty, kteří uvěří: V mém jménu budou vyhánět démony, budou mluvit [novými] jazyky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'budou brát hady [do rukou] a vypijí–li něco smrtelného, nijak jim to neublíží. Na nemocné budou vzkládat ruce a budou se mít dobře.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Potom, když jim to pověděl, byl Pán [Ježíš] vzat vzhůru do nebe a posadil se po pravici Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Oni vyšli a vyhlásili všude evangelium, Pán pracoval s nimi a potvrzoval to slovo znameními, která je doprovázela. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Protože se již mnozí pokusili sestavit vyprávění o událostech, které se mezi námi naplnily,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'jak nám je předali ti, kteří se od počátku stali očitými svědky a ⌈služebníky slova⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'rozhodl jsem se také já, když jsem vše znovu pečlivě prošel, že ti to po pořádku vypíši, vznešený Theofile,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'abys plně poznal spolehlivost těch věcí, kterým jsi byl vyučen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Za dnů judského krále Heroda byl jeden kněz, jménem Zachariáš, z oddílu Abiova; měl ženu z dcer Áronových a její jméno bylo Alžběta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Oba byli spravedliví před Bohem a žili bezúhonně podle všech Pánových příkazů a ustanovení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Neměli však dítě, neboť Alžběta byla neplodná a oba již byli ⌈pokročilého věku⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Stalo se pak, když v pořadí svého oddílu konal před Bohem kněžskou službu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'podle zvyku kněžského úřadu, připadlo na něj losem, aby vešel do Pánovy svatyně a obětoval kadidlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'A v hodinu obětování kadidla se celé shromáždění lidu modlilo venku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Tu se mu ukázal Pánův anděl, stojící po pravé straně oltáře pro obětování kadidla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Když ho Zachariáš uviděl, rozrušil se a padl na něj strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Anděl mu řekl: „Neboj se, Zachariáši, neboť tvá prosba byla vyslyšena, a tvá žena Alžběta ti porodí syna a dáš mu jméno Jan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'A budeš mít radost a veselí a mnozí se budou radovat z jeho narození.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Neboť bude veliký před Pánem, vína a opojného nápoje se nenapije a již od lůna své matky bude naplněn Duchem Svatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'A mnohé ze synů Izraele obrátí k Pánu, jejich Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'A sám půjde před ním v duchu a moci Eliášově, aby obrátil srdce otců k dětem a neposlušné k smýšlení spravedlivých a přichystal Pánu připravený lid.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'I řekl Zachariáš andělovi: „Podle čeho to poznám? Vždyť jsem stařec a má žena je již pokročilého věku.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Anděl mu odpověděl a řekl: „Já jsem Gabriel, který stojí před Bohem, a byl jsem poslán, abych k tobě promluvil a oznámil ti tuto radostnou zprávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'A hle, budeš němý a nebudeš moci promluvit až do dne, kdy se to stane, protože jsi neuvěřil mým slovům, která se ve svůj čas naplní.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Lid čekal na Zachariáše a divil se, že tak dlouho prodlévá ve svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Když vyšel, nemohl k nim promluvit, i poznali, že spatřil ve svatyni vidění. Dorozumíval se s nimi posunky a zůstával němý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'I stalo se, že jakmile se naplnily dny jeho služby, odešel ⌈do svého domu.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Po těch dnech jeho žena Alžběta otěhotněla, a skrývala se po pět měsíců a říkala:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '„Tak mi učinil Pán ve dnech, v nichž na mne pohlédl, aby odňal mé pohanění mezi lidmi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'V šestém měsíci byl anděl Gabriel poslán od Boha do galilejského města, které se jmenuje Nazaret,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'k panně zasnoubené muži jménem Josef, z domu Davidova; jméno té panny bylo Marie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'I vešel k ní a řekl: „⌈Buď zdráva⌉, ⌈milostí obdařená⌉, Pán je s tebou. [Požehnaná tys mezi ženami.] “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Ona však byla tím slovem velmi rozrušena a uvažovala, jaký je to pozdrav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'A anděl jí řekl: „Neboj se, Marie, neboť jsi nalezla milost u Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'A hle, otěhotníš a porodíš syna a dáš mu jméno Ježíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Ten bude veliký a bude nazván synem Nejvyššího a Pán Bůh mu dá trůn jeho otce Davida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Na věky bude kralovat nad domem Jákobovým a jeho kralování nebude konce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Marie řekla andělovi: „Jak se to stane, vždyť nepoznávám muže?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'A anděl jí odpověděl: „Duch Svatý přijde na tebe a moc Nejvyššího tě zastíní; proto také to Svaté, co se [z tebe] narodí, bude nazváno Syn Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Hle, tvá příbuzná Alžběta -- také ona počala ve svém stáří syna a toto je šestý měsíc té, která je nazývána neplodnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Neboť u Boha nebude žádná věc nemožná.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Marie řekla: „Hle, jsem Pánova otrokyně; nechť se mi stane podle tvého slova.“A anděl od ní odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'V těch dnech Marie vstala a vydala se spěšně na cestu do hor do města Judova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Vešla do Zachariášova domu a pozdravila Alžbětu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'I stalo se, že jakmile Alžběta uslyšela Mariin pozdrav, poskočilo dítě v jejím lůně; a Alžběta byla naplněna Duchem Svatým');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'a zvolala silným hlasem: „Požehnaná jsi ty mezi ženami a požehnaný plod tvého lůna!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Jak se mi to stalo, že ke mně přišla matka mého Pána?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Neboť hle, jakmile se zvuk tvého pozdravu dotkl mých uší, poskočilo radostí dítě v mém lůně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'A blahoslavená, která uvěřila, neboť se splní, co jí bylo řečeno od Pána.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'A Marie řekla:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, '„Má duše velebí Pána a můj duch se rozveselil v Bohu, mém Zachránci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'že pohlédl na ponížení své otrokyně. Hle, vždyť od této chvíle mě budou blahoslavit všechna pokolení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'protože mi Mocný učinil veliké věci. Svaté je jeho jméno');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'a jeho milosrdenství od pokolení do pokolení těm, kdo se ho bojí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Svou paží učinil mocný skutek, rozptýlil ty, kteří jsou pyšní v smýšlení svého srdce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'svrhl vládce z trůnů a povýšil pokorné,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'hladovějící nasytil dobrými věcmi a bohaté poslal pryč s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Ujal se Izraele, svého služebníka, pamatoval na své milosrdenství,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'jak mluvil k našim otcům, Abrahamovi a jeho potomstvu až ⌈na věčnost⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Marie s ní zůstala asi tři měsíce a pak se vrátila do svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Alžbětě se naplnila doba k jejímu porodu, i porodila syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Její sousedé a příbuzní uslyšeli, že jí Pán učinil své veliké milosrdenství, a radovali se spolu s ní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'I stalo se, že osmého dne přišli chlapce obřezat a chtěli ho nazvat podle jména jeho otce Zachariáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'A jeho matka odpověděla: „Ne, ale bude se jmenovat Jan.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Řekli jí: „Z tvého příbuzenstva není nikdo, kdo se tak jmenuje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Dávali znamení jeho otci, jak by si přál, aby bylo dítě nazýváno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Požádal o tabulku a napsal: Jeho jméno je Jan. A všichni se podivili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Ihned se otevřela jeho ústa a jeho jazyk se uvolnil a on mluvil a dobrořečil Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Na všechny, kdo žili v jejich sousedství, padl strach a po celém judském pohoří se mluvilo o všech těchto událostech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'A všichni, kteří to uslyšeli, si to uložili ve svém srdci a říkali: „Co z toho dítěte bude?“A Pánova ruka byla s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'A jeho otec Zachariáš byl naplněn Duchem Svatým a prorocky promluvil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '„⌈Požehnaný Pán, Bůh Izraele,⌉ protože navštívil a ⌈vykoupil svůj lid⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'a vzbudil nám roh záchrany v domě Davida, svého služebníka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'jak mluvil skrze ústa svých svatých proroků od pradávna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'zachránil nás od našich nepřátel a z rukou všech, kteří nás nenávidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'aby ⌈prokázal milosrdenství našim otcům⌉ a rozpomenul se na svou svatou smlouvu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'na přísahu, kterou se zavázal našemu otci Abrahamovi, že nám dá,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'abychom vysvobozeni z rukou [našich] nepřátel mu beze strachu sloužili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 've svatosti a spravedlnosti před ním po všechny své dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'A ty, dítě, budeš nazváno prorokem Nejvyššího, neboť půjdeš před Pánem připravit jeho cesty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'aby dal jeho lidu poznání záchrany v odpuštění jejich hříchů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'pro milosrdný soucit našeho Boha, v němž nás navštíví Úsvit z výsosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'aby se ukázal těm, kdo sedí ve tmě a stínu smrti, a uvedl naše nohy na cestu pokoje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Chlapec rostl a sílil na duchu a pobýval na pustých místech až do dne, kdy otevřeně vystoupil před Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Stalo se v oněch dnech, že vyšlo nařízení od císaře Augusta, aby byl po celém obydleném světě proveden soupis obyvatelstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Tento ⌈soupis se konal před tím soupisem, který byl proveden, když⌉ v Sýrii vládl Quirinius.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'I šli všichni dát se zapsat, každý do svého města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Také Josef vyšel z Galileje, z města Nazareta, do Judska, do města Davidova, které se nazývá Betlém, neboť byl z domu a rodu Davidova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'aby se dal zapsat s Marií, ⌈svou snoubenkou⌉, která byla těhotná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Stalo se, když tam byli, že se naplnily dny, aby porodila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'I porodila svého ⌈syna, toho prvorozeného⌉, zavinula ho do plenek a položila do jeslí, protože pro ně nebylo místo v útulku pro pocestné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'V téže krajině byli pastýři, kteří pobývali venku a v noci drželi hlídky nad svým stádem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'A [hle,] postavil se k nim Pánův anděl a Pánova sláva je ozářila; i zmocnil se jich veliký strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Anděl jim řekl: „Nebojte se. Hle, zvěstuji vám dobrou zprávu o veliké radosti, která bude pro všechen lid,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'že se vám dnes narodil Zachránce, který je ⌈Kristus Pán⌉, v městě Davidově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Toto vám bude znamením: Naleznete děťátko zavinuté do plenek a ležící v jeslích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'A náhlese s andělem objevilo množství nebeského vojska chválícího Boha a říkajícího:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '„Sláva na výsostech Bohu a na zemi pokoj ⌈mezi lidmi Božího zalíbení⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'A stalo se, že jakmile od nich andělé odešli do nebe, ⌈začali si pastýři mezi sebou říkat⌉: „Pojďme tedy až do Betléma a podívejme se na to, co se tam stalo, co nám Pán oznámil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Pospíšili si tam a nalezli Marii i Josefa a děťátko, které leželo v jeslích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Když je spatřili, oznámili slovo, které jim bylo o tom dítěti řečeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'A všichni, kdo to uslyšeli, užasli nad tím, co jim pastýři řekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Marie však ⌈toto všechno⌉ uchovávala ve svém srdci a rozvažovala o tom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Pastýři se pak navrátili, oslavujíce a chválíce Boha za všechno, co uslyšeli a uviděli, jak jim to bylo řečeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Když se naplnilo osm dní, aby byl obřezán, ⌈dali mu⌉ jméno Ježíš; byl tak pojmenován od anděla před svým početím v lůně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'A když se naplnily dny jejich očišťování podle Mojžíšova zákona, přinesli jej do Jeruzaléma, aby ho postavili před Pána,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'jak je napsáno v Pánově zákoně: Každý mužského pohlaví, který otevírá lůno, bude nazván svatý Pánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'a aby dali oběť podle toho, co je řečeno v Pánově zákoně, párek hrdliček nebo dvě holoubata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'A hle, v Jeruzalémě byl člověk, který se jmenoval Simeon. Byl to člověk spravedlivý a zbožný, očekávající potěšení Izraele, a Duch Svatý byl na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Jemu bylo Duchem Svatým zjeveno, že nespatří smrt, dokud neuvidí Pánova Mesiáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Ten přišel ⌈v Duchu⌉ do chrámu. Když rodiče přinesli chlapce Ježíše, aby s ním učinili podle obyčeje Zákona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'on si ho vzal do náručí, vzdal chválu, dobrořečil Bohu a řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '„Nyní, Panovníku, podle svého výroku propouštíš svého otroka v pokoji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'neboť mé oči spatřily tvou záchranu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'kterou jsi připravil před tváří všech lidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'světlo ke zjevení národům a slávu tvého lidu Izraele.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, '⌈Jeho otec a⌉ matka se podivovali nad tím, co bylo o něm mluveno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Simeon jim požehnal a řekl Marii, jeho matce: „Hle, on je určen k pádu a povstání mnohých v Izraeli a jako znamení, jemuž bude odpíráno --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'i tvou vlastní duší pronikne meč -- aby bylo zjeveno myšlení mnohých srdcí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'A byla tam prorokyně Anna, dcera Fanuelova, z kmene Ašerova. Ta ⌈již byla velmi pokročilého věku⌉; s mužem žila sedm let od svého panenství');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'a vdovou byla až do svých osmdesáti čtyř let. Neopouštěla chrám, postya prosbami sloužila Bohu dnem i nocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'A v té hodině přistoupila, děkovala Bohu a říkala o něm všem, kteří očekávali vykoupení Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'A když vykonali všechno podle Pánova zákona, vrátili se do Galileje do svého města Nazareta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Dítě pak rostlo a sílilo naplňováno moudrostí a Boží milost byla ⌈s ním⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Jeho rodiče chodívali každý rok do Jeruzaléma na svátek velikonoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Také když mu bylo dvanáct let, vystupovali [do Jeruzaléma], jak bylo o této slavnosti zvykem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'A když se po dokonání těch dnů vraceli domů, zůstal chlapec Ježíš v Jeruzalémě, aniž to ⌈jeho rodiče⌉ zpozorovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Protože se domnívali, že je ve skupině poutníků, ušli den cesty a hledali ho mezi příbuznými a známými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'A když ho nenalezli, vrátili se do Jeruzaléma a hledali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'I stalo se, že ho po třech dnech nalezli v chrámě, jak sedí uprostřed učitelů, naslouchá jim a vyptává se jich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Všichni, kteří ho slyšeli, žasli nad jeho rozumností a odpověďmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Když ho rodiče spatřili, zhrozili se a jeho matka mu řekla: „Synu, co jsi nám to udělal? Hle, tvůj otec a já jsme tě s úzkostí hledali.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'A on jim řekl: „Jak to, že jste mne hledali? Nevěděli jste, že ⌈musím být ve věcech svého Otce⌉?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Ale oni neporozuměli tomu slovu, které jim pověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'I sestoupil s nimi, přišel do Nazareta a byl jim poddán. Jeho matka pečlivě uchovávala ⌈všechna [tato] slova⌉ ve svém srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'A Ježíš prospíval v moudrosti a v tělesném růstu a v přízni u Boha i u lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'V patnáctém roce vlády císaře Tiberia, když v Judsku vládl Pontius Pilát a v Galileji byl tetrarchou Herodes, jeho bratr Filip byl tetrarchou na území Itureje a Trachonitidy a Lyzanias byl tetrarchou v Abiléně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'za velekněze Annáše a Kaifáše, stalo se slovo Boží k Janovi, synovi Zachariáše, v pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'I šel do celého okolí Jordánu a hlásal křest pokání k odpuštění hříchů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'jak je napsáno v knize slov proroka Izaiáše: Hlas volajícího v pustině: Připravte Pánovu cestu, vyrovnávejte jeho stezky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Každé údolí bude zaplněno, každá hora a pahorek bude snížen; co je křivé, bude rovné, drsné cesty budou hladké;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'a každé tělo uvidí Boží záchranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Zástupům, které vycházely, aby se od něho daly pokřtít, říkal: „Plemeno zmijí! Kdo vám ukázal, jak utéci před nadcházejícím hněvem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Vydávejte tedy ovoce svědčící o pokání a nezačínejte si říkat: Náš otec je Abraham. Neboť vám pravím, že Bůh může Abrahamovi vzbudit děti z těchto kamenů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'A sekera už je přiložena ke kořeni stromů. Každý strom, který nenese dobré ovoce, bude vyťat a hozen do ohně.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Zástupy se ho ptaly: „Co tedy máme dělat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Odpověděl jim: „Kdo má dvě košile, ať dá tomu, který nemá, a kdo má co k jídlu, ať činí podobně.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Přišli i celníci, aby byli pokřtěni, a řekli mu: „Učiteli, co máme dělat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'On jim řekl: „Nevybírejte víc, než je vám nařízeno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Ptali se ho i vojáci: „A co bychom měli udělat my?“Řekl jim: „Nikoho neolupujte ani nevydírejte, a buďte spokojeni se svým žoldem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Zatímco lid byl plný očekávání a všichni ve svých srdcích rozvažovali o Janovi, není–li snad on ten Kristus,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'řekl na to Jan všem: „Já vás sice křtím vodou, avšak přichází silnější než já, jemuž nejsem hoden rozvázat řemínek u jeho sandálů; on vás bude křtít v Duchu Svatém a ohni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'V jeho ruce je lopata, aby pročistil svůj mlat a pšenici shromáždil do své sýpky, ale plevy bude pálit ohněm neuhasitelným.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Tak i mnoha jinými slovy napomínaje lid, hlásal dobrou zprávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Ale tetrarcha Herodes, který byl od něho kárán kvůli Herodiadě, ženě svého bratra [Filipa], a za všechno zlé, co učinil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'přidal ke všemu [ještě] to, že Jana zavřel do vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Stalo se, když byl křtěn všechen lid, a když i Ježíš byl pokřtěn a modlil se, že se otevřelo nebe');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'a sestoupil na něho Duch Svatý v tělesné podobě jako holubice a z nebe zazněl hlas: „Ty jsi ten můj ⌈Syn, Milovaný, v tobě jsem nalezl zalíbení⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Když Ježíš začínal, bylo mu asi třicet let, byl synem, jak se myslelo, Josefa, ten Heliho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'ten Mathata, ten Léviho, ten Melchiho, ten Janaie, ten Josefa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'ten Matathiáše, ten Amose, ten Nahuma, ten Esliho, ten Nagaje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'ten Mahata, ten Matathiáše, ten Semeina, ten Josecha, ten Jody,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'ten Johanana, ten Resy, ten Zorobabela, ten Salathiela, ten Neriho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'ten Melchiho, ten Addiho, ten Kosama, ten Elmadama, ten Era,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'ten Jesův, ten Eliezera, ten Jorima, ten Mathata, ten Léviho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'ten Simeona, ten Judy, ten Josefa, ten Jonama, ten Eliakima,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'ten Meleie, ten Menny, ten Mattathy, ten Nathama, ten Davida,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'ten Isaje, ten Obéda, ten Bóaza, ten Saly, ten Naasona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'ten Amínadaba, ten Admina, ten Arniho, ten Chesróma, ten Farese, ten Judy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'ten Jákoba, ten Izáka, ten Abrahama, ten Thareho, ten Nachora,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'ten Serucha, ten Ragaua, ten Faleka, ten Hebera, ten Saly,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'ten Kainama, ten Arfaxada, ten Sema, ten Noema, ten Lámecha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'ten Mathusalema, ten Henocha, ten Jareda, ten Maleleela, ten Kainama,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'ten Enóše, ten Šéta, ten Adama, ten Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Ježíš pak plný Ducha Svatého se vrátil od Jordánu. Duch ho vodil pustinou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'čtyřicet dní a Ďábel ho pokoušel. V oněch dnech Ježíš nic nesnědl, a když se skončily, vyhladověl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Ďábel mu řekl: „Jsi–li Syn Boží, řekni tomuto kameni, ať se stane chlebem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Ježíš mu odpověděl: „Je napsáno: Člověk nebude živ jen chlebem [, ale každým Božím slovem]. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Ďábel ho vyvedl vzhůru, v jediném okamžiku mu ukázal všechna království světa');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'a řekl mu: „Všechnu tuto pravomoc a jejich slávu dám tobě, protože mně je dána, a komukoli chci, tomu ji dám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Jestliže se tedy ty přede mnou pokloníš, všechna bude tvá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Ježíš mu odpověděl: „Je napsáno: Pánu, svému Bohu, se budeš klanět a jemu jedinému sloužit. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Přivedl jej pak do Jeruzaléma, postavil ho na vrcholek chrámu a řekl mu: „Jsi–li Syn Boží, vrhni se odtud dolů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'vždyť je napsáno, že svým andělům přikáže o tobě, aby tě ochránili');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'a na rukou tě ponesou, abys snad svou nohou nenarazil na kámen. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Ježíš mu odpověděl: „Je řečeno: Nebudeš pokoušet Pána, svého Boha. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Když Ďábel dokončil všechno pokušení, odstoupil od něho až do příhodné doby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Ježíš se v moci Ducha vrátil do Galileje a pověst o něm se rozšířila do celého okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'A vyučoval v jejich synagogách, oslavován ode všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'I přišel do Nazareta, kde byl vychován. Podle svého zvyku vstoupil v sobotní den do synagogy. A povstal, aby četl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Byl mu podán svitek proroka Izaiáše; rozvinul svitek a našel místo, kde bylo napsáno:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Pánův Duch je ⌈na mně⌉, protože mne pomazal, abych zvěstoval evangelium chudým; poslal mne vyhlásit zajatcům propuštění a slepým nabytí zraku, propustit zlomené na svobodu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'vyhlásit vítaný Pánův rok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'A svinul svitek, odevzdal ho sluhovi a posadil se. Oči všech v synagoze se upíraly na něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Začal jim tedy říkat: „Dnes se naplnilo toto Písmo ⌈ve vašich uších.⌉“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Všichni mu přisvědčovali a divili se těm slovům milosti, vycházejícím z jeho úst, a říkali: „Není tento syn Josefův?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Řekl jim: „Jistě mi řeknete toto přísloví: Lékaři, uzdrav sám sebe! To, o čem jsme uslyšeli, že se stalo v Kafarnaum, učiň i zde ve své domovině.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Řekl: „Amen, pravím vám, že žádný prorok není vítaný ve své vlasti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Po pravdě vám pravím, ve dnech Eliášových, když bylo nebe zavřeno na tři roky a šest měsíců, takže nastal veliký hlad po celé zemi, bylo mnoho vdov v Izraeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'A k žádné z nich nebyl Eliáš poslán, nýbrž jen k ženě vdově do Sarepty v Sidónu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'A mnoho malomocných bylo v Izraeli za proroka Elizea, a žádný z nich nebyl očištěn, jen Syřan Náman.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Když to slyšeli, byli všichni v synagoze naplněni hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Vstali, vyhnali ho za město a dovedli ho až na okraj hory, na níž bylo jejich město vystavěno, aby ho svrhli dolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'On však prošel jejich středem a ubíral se dál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Sestoupil do galilejského města Kafarnaum a učil je v sobotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'A byli ohromeni nad jeho učením, protože jeho slovo bylo pronášeno v pravomoci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'V synagoze byl člověk, který měl ducha nečistého démona; i vykřikl velikým hlasem:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '„Ach, co je ti po nás, Ježíši Nazaretský? Přišel jsi nás zničit? Znám tě, kdo jsi: Svatý Boží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Ježíš mu pohrozil: „Umlkni a vyjdi od něho!“A démon jím mrštil doprostřed a vyšel od něho, aniž mu jakkoli uškodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Na všechny padl úžas a říkali si mezi sebou: „Jaké je to slovo, že v pravomoci a síle přikazuje nečistým duchům, a oni vycházejí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'A zpráva o něm se šířila do každého místa okolní krajiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, '⌈Opustil synagogu⌉ a vstoupil do Šimonova domu. Šimonova tchyně byla sužována velikou horečkou; i poprosili ho za ni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Postavil se nad ní, pohrozil horečce, a ta ji opustila. Ihned vstala a obsluhovala je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Když zapadalo slunce, všichni, kteří měli nemocné různými chorobami, přiváděli je k němu; on pak na každého z nich vkládal ruce a uzdravoval je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Od mnohých vycházeli i démoni, kteří křičeli a říkali: „Ty jsi Boží Syn!“Hrozil jim a nedovoloval jim mluvit, protože věděli, že je Mesiáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Když nastal den, vyšel z domu a odešel na opuštěné místo. Zástupy ho hledaly, přišly až k němu a zdržovaly ho, aby od nich neodcházel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'On jim však řekl: „Také ostatním městům musím zvěstovat evangelium Božího království, neboť k tomu jsem byl poslán.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'A hlásal je v judských synagogách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Stalo se, když se na něj tlačil zástup, aby ⌈slyšel Boží slovo,⌉ že stál u Genezaretského jezera');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'a uviděl u břehu jezera dvě lodě. Rybáři z nich vystoupili a prali sítě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Vstoupil do jedné z těch lodí, která patřila Šimonovi, a požádal ho, aby odrazil kousek od břehu. Posadil se a z lodi učil zástupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Když přestal mluvit, řekl Šimonovi: „Zajeď na hlubinu a spusťte své sítě k lovu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Šimon odpověděl: „Mistře, celou noc jsme tvrdě pracovali a nic jsme nechytili.Ale ⌈na tvé slovo⌉ spustím sítě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'A když to učinili, zabrali velké množství ryb; jejich sítě se však začaly trhat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Dali znamení společníkům ve druhé lodi, aby jim přišli pomoci. Oni přišli a naplnili obě lodě, že se až potápěly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Když to Šimon Petr uviděl, padl k Ježíšovým kolenům a řekl: „Odejdi ode mne, Pane, protože jsem hříšný člověk.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Neboť jeho i všech, kteří byli s ním, se zmocnil úžas nad tím úlovkem ryb, které chytili;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'stejně i Jakuba a Jana, synů Zebedeových, kteří byli Šimonovými společníky. Ježíš řekl Šimonovi: „Neboj se, od nynějška budeš lovit lidi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Přirazili s loďmi ke břehu, všechno opustili a vydali se za ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'I stalo se, když byl v jednom z těch měst, hle, byl tam muž plný malomocenství. Jakmile uviděl Ježíše, padl na tvář a poprosil ho: „Pane, chceš–li, jsi mocen mě očistit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'On vztáhl ruku, dotkl se ho a řekl: „Chci, buď očištěn.“A hned od něho malomocenství odešlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Nařídil mu, aby nikomu nic neřekl, nýbrž: „Odejdi, ukaž se knězi a obětuj za své očištění, jak nařídil Mojžíš, jim na svědectví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Pověst o něm se rozšiřovala stále víc a scházely se velké zástupy, aby naslouchaly a byly uzdravovány ze svých nemocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'On se však uchyloval na pustá místa a modlil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'I stalo se, že jednoho dne učil a kolem seděli farizeové a ⌈učitelé Zákona⌉, kteří přišli ze všech galilejských a judských vesnic i z Jeruzaléma. A byla tam Pánova moc, aby [je] uzdravoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'A hle, muži nesli na lůžku člověka, který byl ochrnutý, a snažili se ho vnést dovnitř a položit před něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'A když kvůli zástupu nenalezli způsob, jak by ho vnesli dovnitř, vystoupili na střechu a skrze hliněné tašky ho s nosítky spustili doprostřed před Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Když uviděl jejich víru, řekl: „Člověče, tvé hříchy jsou ti odpuštěny.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Učitelé Zákona a farizeové o tom začali rozvažovat: „Kdo je tento člověk, že mluví tak rouhavě? Kdo může odpustit hříchy, než sám Bůh?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Ježíš však poznal jejich myšlenky a odpověděl jim: „Co rozvažujete ve svých srdcích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Co je snadnější? Říci: Tvé hříchy jsou ti odpuštěny, nebo říci: Vstaň a choď?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Abyste však věděli, že ⌈Syn člověka⌉ má na zemi pravomoc odpouštět hříchy,“řekl ochrnutému: „Tobě pravím, vstaň, vezmi svá nosítka a jdi do svého domu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'A ten hned před nimi vstal, vzal to, na čem ležel, a oslavuje Boha odešel do svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Všech se zmocnil úžas a oslavovali Boha; byli naplněni bázní a říkali: „Dnes jsme uviděli neobyčejné věci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Po těchto událostech Ježíš vyšel a pohlédl na celníka jménem Lévi, sedícího v celnici, a řekl mu: „Následuj mne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'A on všeho zanechal, vstal a následoval ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Lévi mu připravil ve svém domě velkou hostinu. Byl tam veliký zástup celníků i jiných, kteří s nimi byli u stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Farizeové a jejich učitelé Zákona reptali na jeho učedníky a říkali: „Proč jíte a pijete s celníky a hříšníky?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Ježíš jim odpověděl: „Lékaře nepotřebují zdraví, nýbrž nemocní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Nepřišel jsem povolat spravedlivé, ale hříšné k pokání.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Oni mu pak řekli: „⌈Janovi učedníci se⌉ často postí a konají modlitby, stejně i učedníci farizeů; tvoji však jedí a pijí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Ježíš jim řekl: „Můžete přinutit svatebčany, aby se postili, dokud je ženich s nimi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Přijdou však dny, kdy od nich bude ženich vzat; potom v oněch dnech se budou postit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Říkal jim i podobenství: „Nikdo neutrhne záplatu z nového šatu a nepřišívá ji na starý šat; jinak i nový roztrhne a ke starému se záplata z nového nebude hodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'A nikdo nedává mladé víno do starých měchů; jinak mladé víno měchy roztrhne, samo vyteče a měchy se zničí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Ale mladé víno se dává do nových měchů [, a obojí zůstane zachováno].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'A nikdo, kdo se napil starého, nechce mladé, neboť říká: Staré je dobré. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Stalo se, že v [druhou] sobotu procházel obilím a jeho učedníci trhali a jedli klasy, které mnuli rukama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Někteří pak z farizeů řekli: „Proč děláte, co se v sobotu [dělat] nesmí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Ježíš jim odpověděl: „Cožpak jste nečetli, co udělal David, když vyhladověl, on i ti, kdo byli s ním?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Jak vešel do Božího domu a vzal chleby předložení, které nesmí jíst nikdo kromě samotných kněží, jedl je a dal [i] těm, kdo byli s ním?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'A říkal jim: „Syn člověka je [také] pánem soboty.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Stalo se, že v jinou sobotu vstoupil do synagogy a učil. A byl tam člověk, jehož pravá ruka byla odumřelá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Učitelé Zákona a farizeové ho pozorně sledovali, uzdravuje–li v sobotu, aby našli něco, z čeho by jej obžalovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'On však znal jejich myšlenky. Řekl tomu muži ⌈s odumřelou rukou⌉: „Vstaň a postav se doprostřed.“A on se zvedl a postavil se tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Ježíš jim řekl: „Ptám se vás, zda je dovoleno v sobotu učinit dobře, nebo učinit zle -- duši zachránit, či zahubit?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Rozhlédl se po nich po všech a řekl mu: „Natáhni svou ruku.“On to učinil a jeho ruka byla zase v pořádku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Oni byli naplněni nepříčetností a rozmlouvali mezi sebou, co by Ježíšovi učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Stalo se v těch dnech, že vyšel na horu, aby se pomodlil. A celou noc strávil v modlitbě Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Když nastal den, zavolal své učedníky a vybral z nich dvanáct, které také pojmenoval apoštoly:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Šimona, jemuž dal také jméno Petr, jeho bratra Ondřeje, Jakuba, Jana, Filipa, Bartoloměje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matouše, Tomáše, Jakuba Alfeova, Šimona zvaného Zélóta,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judu Jakubova a Judu Iškariotského, jenž se stal zrádcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Sestoupil s nimi dolů a na rovině se zastavil; a s ním veliký zástup jeho učedníků a veliké množství lidu z celého Judska a Jeruzaléma i od pobřeží Týru a Sidónu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'ti všichni přišli, aby ho uslyšeli a aby byli uzdraveni ze svých nemocí. I ti, kteří byli trápeni od nečistých duchů, byli uzdravováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'A celý zástup se ho snažil dotýkat, protože od něho vycházela moc a všechny uzdravovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'A on pozdvihl oči ke svým učedníkům a říkal: „Blahoslavení jste vy chudí, neboť vaše je Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Blahoslavení jste vy, kteří nyní hladovíte, neboť budete nasyceni. Blahoslavení jste vy, kteří nyní pláčete, neboť se budete smát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Blahoslavení jste, když vás lidé budou nenáviděta když vás vyloučí, potupí a zavrhnou vaše jméno jako zlé kvůli Synu člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Radujte se v onen den a jásejte; neboť hle, hojná je vaše odměna v nebi. Vždyť totéž dělali jejich otcové prorokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Běda však vám bohatým, neboť již máte své potěšení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Běda vám, kteří jste nyní nasyceni, neboť budete hladovět. Běda vám, kteří se nyní smějete, neboť budete naříkat a plakat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Běda, když o vás budou všichni lidé mluvit dobře; vždyť totéž činili jejich otcové falešným prorokům.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, '„Ale vám, kteří slyšíte, pravím: Milujte své nepřátele. Dobře čiňte těm, kteří vás nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Žehnejte těm, kteří vás proklínají, modlete se za ty, kteří vám činí příkoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Tomu, kdo tě bije do tváře, nastav i druhou a tomu, kdo ti bere plášť, neodepři ani košili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Každému, kdo tě žádá, dávej, a od toho, kdo ti bere, co je tvoje, nežádej nic nazpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Jak chcete, aby lidé činili vám, [i vy] stejně čiňte jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'A jestliže milujete ty, kteří milují vás, jakou máte zásluhu? Vždyť i hříšníci milují ty, kdo je milují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'A jestliže činíte dobře těm, kteří činí dobře vám, jakou máte zásluhu? I hříšníci dělají totéž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'A půjčíte–li těm, od kterých máte naději dostat to zpět, jakou máte zásluhu? I hříšníci půjčují hříšníkům, aby to zase dostali nazpátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Ale milujte své nepřátele a čiňte dobře, půjčujte a ⌈neočekávejte něco na oplátku⌉. A vaše odměna bude hojná a budete syny Nejvyššího, protože on je dobrotivý k nevděčným i zlým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Buďte milosrdní, jako je milosrdný váš Otec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, '„Nesuďte, ⌈a zajisté nebudete⌉ souzeni. Neodsuzujte, ⌈a zajisté nebudete⌉ odsouzeni. Promíjejte, a bude vám prominuto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dávejte, a bude vám dáno; dobrou míru, natlačenou, natřesenou, překypující vám dají do klína. Neboť ⌈jakou měrou⌉ měříte, takovou vám bude naměřeno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Řekl jim také podobenství: „Může slepý vést slepého? Nespadnou oba do jámy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Učedník není nad učitele. Každý, kdo je dokonale připraven, bude jako jeho učitel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Proč hledíš na třísku v oku svého bratra, avšak trámu ve svém vlastním oku si nevšímáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Jak můžeš říkat svému bratru: Bratře, dovol, ať vyjmu třísku, která je ve tvém oku, a trám ve svém oku nevidíš? Pokrytče, nejprve vyjmi trám ze svého oka, a pak jasně uvidíš, jak vyjmout třísku, která je v oku tvého bratra.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, '„Přece není dobrý strom, který nese špatné ovoce, ani není špatný strom, který nese dobré ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Každý strom se pozná po svém ovoci. Vždyť z trní nesbírají fíky ani z trnitého keře nesklízejí hrozny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Dobrý člověk vynáší z dobrého pokladu [svého] srdce dobré a zlý [člověk] vynáší ze zlého [pokladu svého srdce] zlé; neboť jeho ústa mluví z přebytku srdce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, '„Proč mne oslovujete Pane, Pane, a nečiníte, co říkám?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Každý, kdo ke mně přichází a slyší má slova a činí je -- ukáži vám, komu je podobný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Je podoben člověku stavějícímu dům, který kopal ⌈do hloubky⌉ a položil základy na skále. Nastala povodeň, na ten dům se přivalila řeka, ale nemohla jím otřást, ⌈protože byl dobře postaven.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Kdo však uslyšel a neučinil tak, je podoben člověku, který postavil dům na zemi bez základů. Když se na něj přivalila řeka, ihned se zřítil; a zhroucení toho domu bylo veliké.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Když dokončil všechna svá slova k lidu, vešel do Kafarnaum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Otrok nějakého setníka, který byl setníkovi vzácný, byl na smrt nemocen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Když setník uslyšel o Ježíšovi, poslal k němu židovské starší a žádal ho, aby přišel a zachránil jeho otroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Ti přišli k Ježíšovi a naléhavě ho prosili: „Je hoden, abys mu to prokázal;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'neboť miluje náš národ, i synagogu nám sám vystavěl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Ježíš šel s nimi. Když již byl nedaleko od jeho domu, poslal k němu setník své přátele, aby mu řekli: „Pane, neobtěžuj se; vždyť nejsem hoden, abys vešel pod mou střechu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Proto jsem se ani nepokládal za hodna k tobě přijít. Ale řekni slovo, a můj sluhabude uzdraven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Vždyť i já jsem člověk podřízený autoritě a mám pod sebou vojáky; řeknu– li některému: Jdi, pak jde; jinému: Přijď, pak přijde; a svému otroku: Udělej to, pak to udělá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Když to Ježíš uslyšel, užasl nad ním, obrátil se k zástupu, který ho doprovázel, a řekl: „Pravím vám, ani v Izraeli jsem nenalezl tak velkou víru.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Když se ti, kteří byli posláni, vrátili do domu, nalezli toho [nemocného] otroka zdravého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'A stalo se, že ⌈hned nato⌉ šel do města zvaného Naim. A šli s ním [mnozí] jeho učedníci a veliký zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Když se přiblížil k městské bráně, hle, vynášeli mrtvého, jediného syna jeho matky, a ta byla vdova; byl s ní velký zástup z města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Když ji Pán uviděl, byl nad ní hluboce pohnut a řekl jí: „Neplač!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Pak přistoupil a dotkl se már. Ti, kteří je nesli, se zastavili. Řekl: „Chlapče, pravím ti, probuď se!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Mrtvý se posadil a začal mluvit; a Ježíš ho dal jeho matce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Všech se zmocnil strach, oslavovali Boha a říkali: „Veliký prorok povstal mezi námi“a „Bůh navštívil svůj lid.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'A toto slovo o něm se rozšířilo po celém Judsku a po všem okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'O tom všem podali Janovi jeho učedníci zprávu. Jan si zavolal dva ze svých učedníků');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'a poslal je k Ježíšovi se slovy: „Ty jsi ⌈Ten, který má přijít, nebo máme očekávat⌉ jiného?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Ti muži k němu přišli a řekli: „Jan Křtitel nás k tobě poslal se slovy: Ty jsi Ten, který má přijít, nebo máme očekávat jiného?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'V tu hodinu uzdravil mnoho lidí z nemocí, z trápení a od zlých duchů a mnohým slepým daroval zrak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'A jim odpověděl: „Jděte, podejte zprávu Janovi, co jste uviděli a uslyšeli: Slepí opět vidí, chromí chodí, malomocní jsou očišťováni, hluší slyší, mrtví vstávají, chudým se zvěstuje evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'A blahoslavený je ten, kdo by se nade mnou nepohoršil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Když Janovi poslové odešli, začal Ježíš říkat zástupům o Janovi: „Co jste vyšli spatřit do pustiny? Třtinu zmítanou větrem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Nebo co jste vyšli uvidět? Člověka oblečeného do jemných šatů? Hle, ti, ⌈kdo nosí nádherné šaty⌉ a žijí v přepychu, jsou v královských palácích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Nebo co jste vyšli uvidět? Proroka? Ano, pravím vám, a více než proroka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'To je ten, o němž je napsáno: Hle, posílám svého posla před tvou tváří, který upraví tvou cestu před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, '[Amen,] pravím vám, mezi těmi, kdo se narodili z ženy, nikdo není větší [prorok] než Jan [Křtitel]; avšak ten nejmenší v Božím království je větší než on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'A všechen lid, který ho slyšel, i celníci uznali Boha za spravedlivého tím, že se dali pokřtít Janovým křtem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Farizeové a zákoníci odmítli Boží radu pro sebe, když se nedali od něho pokřtít.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, '„ K čemu tedy přirovnám lidi tohoto pokolení? Komu jsou podobni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Jsou podobni dětem, které sedí na tržišti, volají na sebe a říkají: Pískali jsme vám, a netancovali jste; naříkali jsme, a neplakali jste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Neboť přišel Jan Křtitel, nejedl chléb ani nepil víno, a říkáte: Má démona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Přišel Syn člověka, jí a pije, a říkáte: Hle, člověk žrout a pijan vína, přítel celníků a hříšníků!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Ale moudrost je ospravedlněna všemi svými dětmi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Jeden z farizeů ho prosil, aby s ním pojedl. I vstoupil do domu toho farizea a ⌈zaujal místo⌉ u stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Hle, v tom městě byla žena, hříšnice. Jakmile se dozvěděla, že je Ježíš u stolu ve farizeově domě, přinesla alabastrovou nádobku vonného oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'A s pláčem se postavila zezadu k jeho nohám, slzami začala smáčet jeho nohy a otírat je ⌈svými vlasy⌉, vroucně líbala jeho nohy a mazala je vonným olejem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Když to uviděl farizeus, který ho pozval, řekl si v mysli: „Kdyby tento byl prorok, věděl by, kdo a jaká je ta žena, která se ho dotýká, že je hříšná.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Ježíš mu na to řekl: „Šimone, musím ti něco říci.“On řekl: „Učiteli, řekni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '„Jakýsi věřitel měl dva dlužníky. Jeden mu dlužil pět set denárů, druhý padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Když mu neměli z čeho vrátit, odpustil oběma. Který z nich ho tedy bude více milovat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Šimon odpověděl: „Mám za to, že ten, kterému odpustil víc.“On mu řekl: „Správně jsi usoudil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Pak se obrátil k ženě a říkal Šimonovi: „Vidíš tuto ženu? Vešel jsem do tvého domu, ale vodu na nohy jsi mi nepodal; tato žena však skropila mé nohy slzami a otřela je svými vlasy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Nepolíbil jsi mne, ale ona od té chvíle, co jsem vešel, nepřestala vroucně líbat mé nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Nepomazal jsi mou hlavu olejem, ona však vonným olejem pomazala mé nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Proto ti pravím: Její mnohé hříchy jsou odpuštěny, protože mnoho milovala. Komu se málo odpouští, málo miluje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Jí pak řekl: „Jsou ti odpuštěny hříchy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'A spolustolovníci si začali říkat: „Kdo to je, že dokonce hříchy odpouští?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Řekl té ženě: „Tvá víra tě zachránila. Jdi v pokoji.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'A stalo se, že potom procházel městy a vesnicemi a hlásal a zvěstoval jako radostnou zvěst Boží království; bylo s ním těch Dvanáct');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'a některé ženy, které byly uzdraveny od zlých duchů a nemocí: Marie zvaná Magdalská, od níž kdysi vyšlo sedm démonů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Jana, žena Herodova správce Chuzy, Zuzana a mnohé jiné, které se o ně staraly ze svých prostředků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Když se scházel veliký zástup a z jednotlivých měst k němu přicházeli lidé, řekl jim v podobenství:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '„Vyšel rozsévač zasít své semeno. A jak rozséval, některé padlo podél cesty a bylo zašlapáno, a nebeští ptáci je sezobali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'A jiné padlo na skálu, vyrostlo a uschlo, protože nemělo vláhu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'A jiné padlo mezi trní; a trní vyrostlo spolu s ním a udusilo je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'A jiné padlo do dobré země, vyrostlo a vydalo stonásobnou úrodu.“To řekl a volal: „Kdo má uši k slyšení, ať poslouchá!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Jeho učedníci se ho tázali, co to podobenství znamená.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'On řekl: „Vám je dáno poznat tajemství Božího království, ostatním však v podobenstvích, aby hledíce neviděli a slyšíce nechápali.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, '„Toto podobenství znamená: Semeno je Boží slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Podél cesty jsou ti, kteří uslyšeli, a pak přichází Ďábel a bere Slovo z jejich srdce, aby neuvěřili a nebyli zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Ti na skále, když uslyší, s radostí přijímají Slovo. Protože však nemají kořen, věří jen po určitou dobu a v čas zkoušky odpadají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Do trní padlé, to jsou ti, kteří uslyšeli, ale jak jdou svou cestou, dusí je zájmy, bohatství a rozkoše života, a nenesou zralé plody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'V dobré zemi, to jsou ti, kteří, když uslyšeli Slovo, drží je pevně v ušlechtilém a dobrém srdci a s vytrvalostí nesou ovoce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, '„Nikdo, když rozsvítí lampu, ji nepřikrývá nádobou, ani ji nestaví pod postel, ale staví ji na svícen, aby ti, kdo vcházejí, viděli světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Vždyť nic není skrytého, co se nestane zjevným, ani ukrytého, co by zajisté nebylo poznáno a nevyšlo najevo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Dávejte tedy pozor, jak slyšíte. Neboť tomu, kdo má, bude dáno, a tomu, kdo nemá, bude odňato i to, co myslí, že má.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Přišla za ním matka a jeho bratři, ale nemohli se s ním pro zástup setkat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, '[A] oznámili mu: „Tvoje matka a tvoji bratři stojí venku a chtějí tě vidět.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'On jim však odpověděl: „Má matka a moji bratři jsou ti, kteří slyší Boží slovo a činí je.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Stalo se, že jednoho dne vstoupil do lodi se svými učedníky a řekl jim: „Přeplavme se na druhou stranu jezera.“A vypluli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Zatímco se plavili, usnul. A na jezero se snesla větrná bouře; začali se naplňovat vodou a byli v nebezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Přistoupili k němu, vzbudili ho a řekli: „Mistře, Mistře, hyneme!“On vstal, pohrozil větru a přívalu vod; i ustaly a nastal klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Řekl jim: „Kde je vaše víra?“Ulekli se a užasli a říkali mezi sebou: „Kdo to jen je, že přikazuje dokonce větrům a vodě, a poslouchají ho?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Přepluli do krajiny Gerasenů, která je naproti Galileji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Když vystoupil na břeh, potkal ho nějaký muž z toho města, který měl démony a už dlouhou dobu si neoblékl žádný oděv a nebydlel v domě, nýbrž v hrobech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Když uviděl Ježíše, vykřikl, padl před ním na zem a řekl silným hlasem: „Co je ti po mně, Ježíši, Synu Boha Nejvyššího? Prosím tě, abys mne netrýznil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Ježíš totiž tomu nečistému duchu přikázal, aby od toho člověka vyšel. Neboť ho častokrát zachvacoval; ten muž byl spoutáván řetězy a okovy a byl hlídán, ale pouta trhal a démon ho vyháněl na pustá místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Ježíš se ho otázal: „Jaké je tvé jméno?“On řekl: „Legie“, protože do něho vstoupilo mnoho démonů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'A prosili ho, aby jim nepřikazoval odejít do bezedné propasti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Bylo tam početné stádo vepřů, které se páslo na svahu hory. Démoni ho poprosili, aby jim dovolil do nich vejít; a dovolil jim to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Démoni vyšli od toho člověka a vešli do vepřů, a stádo se zřítilo po svahu do jezera a utopilo se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Když pasáci uviděli, co se stalo, utekli a oznámili to ve městě i ve vesnicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Lidé vyšli, aby uviděli, co se stalo; přišli k Ježíšovi a nalezli toho člověka, od něhož vyšli démoni, jak sedí oblečený u Ježíšových nohou a má zdravou mysl. A ulekli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Ti, kteří viděli, jak byl ten démonizovaný zachráněn, jim o tom pověděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'A celé to množství lidí z ⌈okolní krajiny Gerasenů⌉ ho požádalo, aby od nich odešel, protože se jich zmocňoval veliký strach. On vstoupil do lodi a vrátil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Muž, od něhož vyšli démoni, ho prosil, aby směl být s ním. Ježíš ho však propustil a řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '„Vrať se domů a vypravuj, jak veliké věci ti učinil Bůh.“A on odešel a hlásal po celém městě, jak veliké věci mu učinil Ježíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Když se Ježíš vracel, přivítal ho zástup, neboť ho všichni očekávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'A hle, přišel muž jménem Jairos; byl to představený synagogy. Padl k Ježíšovým nohám a prosil ho, aby vešel do jeho domu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'protože měl jedinou dceru, asi dvanáctiletou, a ta umírala. Když Ježíš šel, zástupy ho tísnily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'A byla tam žena, která měla dvanáct let krvotok [a vynaložila na lékaře všechno, co měla,] a nikdo ji nemohl uzdravit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Přistoupila zezadu, dotkla se třásní jeho šatu, a hned jí krvácení přestalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Ježíš řekl: „Kdo se mne dotkl?“Když všichni zapírali, řekl Petr [a ti, kteří byli s ním]: „Mistře, zástupy tě svírají a tísní [, a říkáš: Kdo se mne dotkl].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Ale Ježíš řekl: „Někdo se mne dotkl. Já jsem poznal, že ode mne vyšla moc.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Když žena uviděla, že se to neutajilo, s třesením přišla, padla mu k nohám a přede vším lidem vypověděla, proč se ho dotkla a jak byla hned uzdravena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'On jí řekl: „Dcero, tvá víra tě zachránila. Jdi v pokoji.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Zatímco ještě mluvil, přišel kdosi z domu představeného synagogy a řekl: „Tvá dcera zemřela, [již] učitele neobtěžuj.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Ježíš to uslyšel a odpověděl mu: „Neboj se, jen věř, a bude zachráněna.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Když přišel do domu, nedovolil nikomu, aby s ním vešel, kromě Petra, Jana a Jakuba a otce a matky té dívky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Všichni nad ní plakali a bili se v prsa. On řekl: „Neplačte. Nezemřela, ale spí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Posmívali se mu, protože věděli, že zemřela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'On však [všechny vyhnal ven,] uchopil její ruku a zvolal: „Dívko, vstaň!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'I navrátil se její duch a ona hned vstala. Nařídil, aby jí dali najíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Jejích rodičů se zmocnil úžas. On jim však přikázal, aby nikomu neřekli, co se stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Svolal si Dvanáct [apoštolů] a dal jim sílu a pravomoc nad všemi démony i k léčení nemocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Poslal je hlásat Boží království a uzdravovat [nemocné].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'A řekl jim: „Nic si neberte na cestu, ani hůl ani mošnu ani chléb ani peníze ani nemějte dvě košile.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'A do kteréhokoli domu vejdete, tam zůstávejte a odtamtud vycházejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Kde by vás nepřijali, při odchodu z toho města setřeste prach ze svých nohou na svědectví proti nim.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Vydali se na cestu a procházeli jednotlivé vesnice, hlásali evangelium a všude uzdravovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Tetrarcha Herodes uslyšel o všem, co se dálo, a byl na rozpacích, protože někteří říkali, že Jan vstal z mrtvých,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'jiní, že se zjevil Eliáš, a jiní, že vstal některý z dávných proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Herodes řekl: „Jana jsem sťal. Kdo je ten, o němž slyším takové věci?“A usiloval ho uvidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Když se apoštolové vrátili, vypravovali mu, co všechno učinili. Vzal je s sebou a odebral se stranou do města zvaného Betsaida.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Když se to zástupy dozvěděly, vydaly se za ním. On je přijal a mluvil k nim o Božím království a uzdravoval ty, kteří potřebovali uzdravení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Den se začal nachylovat. Přistoupilo k němu těch Dvanáct a řekli mu: „Propusť zástup, ať jdou do okolních vesnic a statků opatřit si nocleh a nalézt potravu, protože jsme zde na pustém místě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Řekl jim: „Vy jim dejte najíst!“Oni řekli: „Nemáme víc než pět chlebů a dvě ryby. Nebo snad máme my jít a nakoupit pokrm pro všechen tento lid?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Bylo tam totiž asi pět tisíc mužů. Řekl svým učedníkům: „Rozsaďte je do skupin asi po padesáti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'I učinili tak a všechny rozsadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Potom vzal těch pět chlebů a dvě ryby, vzhlédl k nebi, požehnal je, rozlámal a dával učedníkům, aby je předložili zástupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'A jedli a nasytili se všichni. A bylo sebráno, co jim zbylo -- dvanáct nůší úlomků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'I stalo se, když se o samotě modlil a když s ním byli jeho učedníci, že se jich otázal: „Za koho mne zástupy pokládají?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Oni odpověděli: „ Někteří za Jana Křtitele, jiní za Eliáše a jiní říkají, že vstal některý z dávných proroků.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Řekl jim: „Za koho mne pokládáte vy?“Petr odpověděl: „Za Božího Pomazaného.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Důrazně jim přikázal, aby to nikomu neříkali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'a řekl: „Syn člověka musí mnoho vytrpět, být zavržen od starších, velekněží a učitelů Zákona, být zabit a třetího dne být vzkříšen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Všem pak říkal: „Chce–li kdo jít za mnou, ať zapře sám sebe a [každý den] vezme svůj kříž a následuje mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Neboť kdo by chtěl svou duši zachránit, zahubí ji; kdo by však svou duši zahubil kvůli mně, ten ji zachrání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Vždyť co člověku prospívá, když získal celý svět, ale sebe poškodil nebo zahubil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Neboť kdo by se styděl za mne a za má slova, za toho se bude stydět Syn člověka, když přijde v slávě své i Otcově a svatých andělů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Vpravdě vám pravím: Jsou někteří z těch, kdo tu stojí, kteří určitě neokusí smrti, dokud nespatří Boží království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Asi osm dní po těchto slovech vzal s sebou Petra, Jana a Jakuba a vystoupil na horu, aby se pomodlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'A když se modlil, vzhled jeho tváře se změnil a jeho oděv se bělostně rozzářil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'A hle, dva muži s ním rozmlouvali -- byli to Mojžíš a Eliáš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'kteří se ukázali v slávě a mluvili o jeho odchodu, který se měl naplnit v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Petr a jeho druhové byli obtíženi spánkem. Když se probudili, uviděli jeho slávu a ty dva muže stojící s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'I stalo se, když se od něho oddělovali, že Petr řekl Ježíšovi: „Mistře, je pro nás dobré tu být. Udělejme tři stánky, jeden tobě, jeden Mojžíšovi a jeden Eliášovi.“Nevěděl, co mluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Zatímco to říkal, objevil se oblak a zastiňoval je. Ulekli se, když vcházeli do oblaku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'A z oblaku se ozval hlas: „Toto je můj Syn, Vyvolený, toho poslouchejte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'A když zazněl ten hlas, nalezli Ježíše samotného. Umlkli a nikomu v oněch dnech nepověděli nic o tom, co uviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Stalo se příštího dne, když sestoupili s hory, že mu vyšel vstříc veliký zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'A hle, jakýsi muž ze zástupu zvolal: „Učiteli, prosím tě, podívej se na mého syna, je můj jediný!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Hle, zachvacuje ho duch a on znenadání křičí, lomcuje jím, až má pěnu kolem úst, a jen stěží od něho odchází; tak ho moří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Poprosil jsem tvé učedníky, aby ho vyhnali, ale nemohli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Ježíš odpověděl: „Ach, pokolení nevěřící a zvrácené, jak dlouho ještě budu s vámi a budu vás snášet? Přiveď sem svého syna.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Ještě když přicházel, démon ho povalil a zalomcoval jím. Ježíš pohrozil nečistému duchu, uzdravil dítě a vrátil je jeho otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Všichni byli ohromeni nad Boží velebností. Zatímco se všichni podivovali nad tím vším, co činil, řekl svým učedníkům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '„Vložte si do svých uší tato slova: Syn člověka bude vydán do rukou lidí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Oni však tomuto výroku nerozuměli, byl před nimi zahalen, aby jej nepochopili; a báli se ho na tento výrok zeptat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, '⌈Napadla je myšlenka⌉, kdo že je z nich největší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Protože Ježíš znal uvažování jejich srdce, uchopil dítě, postavil je vedle sebe');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'a řekl jim: „Kdo by přijal toto dítě na základě mého jména, mne přijímá, a kdo by přijal mne, přijímá toho, který mne poslal. Neboť kdo je nejmenší mezi vámi všemi, ten je veliký.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Jan na to řekl: „Mistře, viděli jsme kohosi, jak ve tvém jménu vyhání démony, a bránili jsme mu, protože nechodí s námi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Ježíš mu řekl: „Nebraňte mu, neboť kdo není proti vám, je pro vás.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Stalo se, když se naplňovaly dny, kdy měl být vzat vzhůru, že ⌈se pevně rozhodl⌉ jít do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Poslal ⌈před sebou⌉ posly; ti vyšli a vstoupili do jedné samařské vesnice, aby pro něho vše připravili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Ale tam jej nepřijali, protože ⌈byl rozhodnut jít⌉ do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Když to uviděli učedníci Jakub a Jan, řekli: „Pane, chceš, abychom přikázali ohni sestoupit s nebe a zahubit je [jako to učinil i Eliáš]?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Obrátil se a pokáral je. [Řekl: „Nevíte, jakého jste ducha. “]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'A šli do jiné vesnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Když šli cestou, kdosi mu řekl: „Budu tě následovat, kamkoli půjdeš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'A Ježíš mu řekl: „Lišky mají doupata a nebeští ptáci hnízda, ale Syn člověka nemá, kde by hlavu složil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Jinému řekl: „Následuj mne!“On řekl: „[Pane,] dovol mi, abych odešel nejprve pohřbít svého otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Řekl mu: „Nech mrtvé pohřbít jejich mrtvé; ty však jdi a rozhlašuj Boží království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Také jiný řekl: „Budu tě následovat, Pane, jen mi napřed dovol se rozloučit s těmi, kteří jsou v mém domě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Ježíš mu řekl: „Nikdo, kdo vloží [svou] ruku na pluh a ohlíží se zpět, není způsobilý pro Boží království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Potom určil Pán [ještě] jiných sedmdesát [dva] a poslal je ⌈před sebou⌉ po dvou do každého města a místa, kam měl sám jít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Říkal jim: „Žeň je velká, dělníků je však málo. Proste tedy Pána žně, aby poslal dělníky na svou žeň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Jděte! Hle, posílám vás jako ovce mezi vlky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Neberte si měšec ani mošnu ani sandály; s nikým se cestou nepozdravujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Do kteréhokoli domu vejdete, řekněte nejprve: Pokoj tomuto domu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'A bude–li tam syn pokoje, váš pokoj na něm spočine; ne–li, navrátí se k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'V tom domě zůstávejte, jezte a pijte, ⌈co vám dají⌉, neboť hoden je dělník své mzdy. Nepřecházejte z domu do domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'A do kteréhokoli města vstoupíte a přijmou vás, jezte, co vám předloží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'uzdravujte v něm nemocné a říkejte jim: Přiblížilo se k vám Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Když vstoupíte do nějakého města a nepřijmou vás, vyjděte do jeho ulic a řekněte:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'I ten prach z vašeho města, který nám ulpěl na nohou, vám vytřásáme. Avšak to vězte: Přiblížilo se Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Pravím vám, že Sodomě bude v onen den snesitelněji než tomu městu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, '„Běda tobě, Chorazin! Běda tobě, Betsaido! Protože kdyby se byly v Týru a Sidónu staly ty mocné činy, které se staly ve vás, dávno by seděli v žíni a popelu a učinili pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Ale Týru a Sidónu bude na soudu snesitelněji než vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'A ty, Kafarnaum, budeš snad vyvýšeno až do nebe? Až do podsvětí sestoupíš!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kdo slyší vás, slyší mne, a kdo odmítá vás, odmítá mne; kdo odmítá mne, odmítá toho, který mne poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Těch sedmdesát [dva] se vrátilo s radostí a říkali: „Pane, i démoni se nám poddávají ve tvém jménu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Řekl jim: „Viděl jsem, jak Satan spadl s nebe jako blesk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Hle, dal jsem vám pravomoc šlapat po hadech a štírech, i nad veškerou silou Nepřítele, a naprosto nic vám neublíží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Ale z toho se neradujte, že se vám poddávají duchové; radujte se, že vaše jména jsou zapsána v nebesích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'V tu hodinu [Ježíš] zajásal v Duchu [Svatém] a řekl: „Vzdávám ti chválu, Otče, Pane nebe i země, že jsi skryl tyto věci před moudrými a rozumnými a zjevil jsi je nemluvňatům. Ano, Otče, protože tak ⌈se ti zalíbilo⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, '„Všechno mi bylo předáno od mého Otce; a nikdo neví, kdo je Syn, než Otec, a kdo je Otec, než Syn a ten, komu by to Syn chtěl zjevit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'V soukromí se obrátil k učedníkům a řekl: „Blahoslavené oči, které vidí, co vy vidíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Pravím vám, že mnozí proroci a králové chtěli spatřit, co vy vidíte, ale nespatřili, a slyšet, co vy slyšíte, ale neslyšeli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'A hle, jeden zákoník povstal a zkoušel ho: „Učiteli, co mám učinit, abych získal věčný život?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'On mu řekl: „Co je napsáno v Zákoně? Jak to tam čteš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'On odpověděl: „Budeš milovat Pána, svého Boha, z celého svého srdce, celou svou duší, celou svou silou a celou svou myslí, a svého bližního jako sebe samého.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Řekl mu: „Správně jsi odpověděl. To čiň a budeš živ.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'On se však chtěl ospravedlnit, a řekl Ježíšovi: „A kdo je můj bližní?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Ježíš se ujal slova a řekl: „Jeden člověk sestupoval z Jeruzaléma do Jericha a padl do rukou lupičům; ti ho svlékli, zbili, nechali ho tam polomrtvého a odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Náhodou sestupoval po té cestě jeden kněz, ale když ho uviděl, obešel ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Podobně [se tam objevil] i levita; když přišel k tomu místu, uviděl ho a vyhnul se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Ale jeden Samařan na své cestě přišel k němu, a když ho uviděl, byl pohnut soucitem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Přistoupil, na jeho rány nalil olej a víno a obvázal je, položil ho na svého mezka, zavezl do hostince a postaral se o něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Druhého dne vyjmul dva denáry, dal je hostinskému a řekl: Postarej se o něj, a co bys vynaložil navíc, to ti zaplatím, až se budu vracet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Kdo z těch tří, myslíš, byl bližním tomu, který upadl mezi lupiče?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'On řekl: „Ten, který mu prokázal milosrdenství.“Ježíš mu řekl: „Jdi a jednej také tak.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, '[Stalo se,] když šli dále, že vešel do jedné vesnice. Nějaká žena jménem Marta jej přijala [do svého domu].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Měla sestru, která se jmenovala Marie. Ta se posadila k Pánovým nohám a poslouchala jeho slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Ale Marta měla plno práce s obsluhováním. Přistoupila k němu a řekla: „Pane, nezáleží ti na tom, že mě má sestra nechala sloužit samotnou? Řekni jí přece, ať mi pomůže!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Pán jí odpověděl: „Marto, Marto, děláš si starosti a znepokojuješ se mnoha věcmi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'jedno je však potřeba. Marie si vybrala dobrý díl, jenž jí nebude odňat.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Jednou se Ježíš modlil na nějakém místě; a stalo se, když přestal, že mu jeden z jeho učedníků řekl: „Pane, nauč nás modlit se, jako tomu naučil své učedníky i Jan.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Řekl jim: „Když se modlíte, říkejte: Otče [náš, který jsi v nebesích], buď posvěceno tvé jméno. Přijď tvé království. [Buď vůle tvá jako v nebi, tak i na zemi.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Náš denní chléb nám dávej každého dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'A odpusť nám naše hříchy, neboť i my odpouštíme každému, kdo se proviňuje proti nám. A neuveď nás do pokušení [,ale vysvoboď nás od toho Zlého].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Řekl jim: „Někdo z vás bude mít přítele a půjde k němu o půlnoci a řekne mu: Příteli, půjč mi tři chleby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'protože můj přítel ke mně přišel z cesty a nemám, co bych mu předložil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'A on zevnitř odpoví: Neobtěžuj mne! Dveře jsou již zavřeny a mé děti jsou se mnou na lůžku. Nemohu vstát a dát ti to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Pravím vám, i když nevstane a nedá mu kvůli tomu, že je jeho přítel, pro jeho neodbytnost se zvedne a dá mu vše, co potřebuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'A já vám pravím: Žádejte, a bude vám dáno, hledejte, a naleznete, tlučte, a bude vám otevřeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Neboť každý, kdo žádá, dostává, a kdo hledá, nalézá, a tomu, kdo tluče, bude otevřeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Což je mezi vámi takový otec, že když ho syn požádá o [chléb, podá mu kámen? Nebo o] rybu, že mu místo ryby podá hada?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Nebo požádá– li o vejce, podá mu štíra?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Jestliže tedy vy, ač jste zlí, umíte svým dětem dávat dobré dary, čím spíše Otec z nebe dá Ducha Svatého těm, kteří ho žádají.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'A vyháněl ⌈démona, a ten byl němý⌉. Stalo se, když ten démon vyšel, že němý promluvil, a zástupy užasly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Někteří z nich však řekli: „⌈V moci ⌉ Belzebula, vládce démonů, vyhání démony!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Jiní ho zkoušeli tím, že od něho žádali znamení z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Protože znal jejich myšlenky, řekl jim: „Každé království samo proti sobě rozdělené pustne a dům rozdělený proti domu padá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Je–li tedy také Satan proti sobě rozdělen, jak bude moci obstát jeho království? Neboť říkáte, že vyháním démony Belzebulem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Jestliže já vyháním démony ⌈v moci ⌉ Belzebula, v čí moci je vyhánějí vaši synové? Proto oni budou vašimi soudci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Jestliže však vyháním démony prstem Božím, pak už k vám přišlo Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Když plně ozbrojený silák střeží svůj palác, je jeho majetek v bezpečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Přijde–li však silnější než on a přemůže ho, vezme mu jeho zbroj, na kterou spoléhal, a jeho kořist rozdělí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kdo není se mnou, je proti mně, a kdo neshromažďuje se mnou, rozptyluje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, '„Když nečistý duch vyjde od člověka, prochází bezvodými místy a hledá odpočinutí; a když je nenachází, [tehdy] si říká: Vrátím se do svého domu, odkud jsem vyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'A když přijde, nalezne dům [prázdný,] zametený a vyzdobený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Potom jde a vezme s sebou sedm jiných duchů, horších, než je sám; vejdou a bydlí tam. A poslední věci onoho člověka se stávají horšími než ty první.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Stalo se, když toto říkal, že jedna žena ze zástupu pozvedla hlas a řekla mu: „Blahoslavené lůno, které tě nosilo, a prsa, z nichž jsi sál!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Ale on řekl: „Spíše jsou blahoslavení ti, kteří slyší Boží slovo a zachovávají je.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Když se dále shromažďovaly zástupy, začal říkat: „Toto pokolení je pokolení zlé; žádá znamení, ale znamení mu nebude dáno, leč znamení [proroka] Jonáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Jako se totiž Jonáš stal znamením pro Ninivské, tak bude i Syn člověka tomuto pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Královna jihu povstane na soudu s muži tohoto pokolení a odsoudí je, protože přišla od končin země, aby uslyšela Šalomounovu moudrost -- a hle, zde je někdo větší než Šalomoun.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Ninivští muži povstanou na soudu s tímto pokolením a odsoudí je, neboť učinili pokání na Jonášovo kázání-- a hle, zde je někdo větší než Jonáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, '„Nikdo, když rozsvítí lampu, ji nestaví do skrýše [ani pod nádobu], ale na svícen, aby ti, kdo vcházejí, viděli světlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Lampou těla je tvé oko. Je–li tvé oko čisté, i celé tvé tělo je plné světla. Je–li však špatné, i tvé tělo je temné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Hleď tedy, ať světlo, které je v tobě, není tmou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Jestliže je tedy celé tvé tělo světlé a nemá žádnou část temnou, bude celé tak světlé, jako když tě lampa ozařuje svým jasem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Jakmile domluvil, zval ho jeden farizeus, aby u něho posnídal. Ježíš vstoupil a uložil se ke stolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Farizeus se podivil, když uviděl, že se před jídlem nejprve neomyl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Pán mu řekl: „Nyní vy, farizeové, očišťujete povrch číše a mísy, ale váš vnitřek je plný chamtivosti a špatnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Pošetilci! Což ten, který učinil zevnějšek, neučinil také vnitřek?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Raději dejte to, co je uvnitř, jako almužnu, a hle, všechno vám bude čisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Ale běda vám farizeům, protože odevzdáváte desátky z máty, routy a ze všech zahradních bylin, ale nedbáte na právo a lásku Boží. Toto jste měli činit a ono neopomíjet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Běda vám farizeům, protože milujete přední sedadla v synagogách a pozdravy na tržištích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Běda vám, protože jste jako nevyznačené hroby, a lidé, kteří po nich chodí, to nevědí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Na to mu jeden ze zákoníků řekl: „Učiteli, když toto říkáš, urážíš také nás.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'On řekl: „I vám zákoníkům běda, neboť zatěžujete lidi neúnosnými břemeny a sami se těch břemen ani jedním svým prstem nedotýkáte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Běda vám, protože stavíte pomníky prorokům, které vaši otcové zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Tak dosvědčujete skutky svých otců a souhlasíte s nimi; neboť oni proroky zabili, vy [jim] budujete [pomníky].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Proto také pravila Boží moudrost: Pošlu k nim proroky a apoštoly; z nich některé zabijí a jiné budou pronásledovat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'aby byla od tohoto pokolení vyžádána krev všech proroků, prolitá od založení světa,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'od krve Ábelovy až po krev Zachariáše, který zahynul mezi oltářem a domem Božím. Ano, pravím vám, bude vyžádána od tohoto pokolení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Běda vám zákoníkům, protože jste vzali klíč poznání; sami jste nevešli, a těm, kteří chtěli vstoupit, jste v tom zabránili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Když odtamtud vyšel, začali na něho učitelé Zákona a farizeové zle dotírat a vyptávat se na mnohé věci');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'a číhali na něho, ⌈aby ho chytili za slovo⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Tehdy se shromáždil zástup desítek tisíc lidí, takže šlapali jeden po druhém; ⌈začal říkat nejprve svým učedníkům: „Mějte se na pozoru⌉ před kvasem farizeů, to jest před pokrytectvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Není nic zahaleného, co nebude zjeveno, a nic skrytého, co nebude poznáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Proto vše, co jste řekli ve tmě, bude slyšet na světle, a co jste pověděli do ucha v pokojích, bude vyhlášeno ze střech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Pravím vám, svým přátelům: Nebojte se těch, kdo zabíjejí tělo, a potom již nemají, co by učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ukážu vám, koho se máte bát. Bojte se toho, který má pravomoc vás po zabití uvrhnout do Gehenny. Ano, pravím vám, toho se bojte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Což se neprodává pět vrabců za dva haléře? A ani jeden z nich není zapomenut před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Vždyť i všechny vlasy na vaší hlavě jsou spočteny. Nebojte se! Jste cennější než mnoho vrabců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Pravím vám: Ke každému, kdo by se ke mně přiznal před lidmi, se i Syn člověka přizná před Božími anděly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Kdo mne však před lidmi zapře, ten bude zapřen před Božími anděly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'A každému, kdo řekne slovo proti Synu člověka, bude odpuštěno. Tomuvšak, kdo by se rouhal Svatému Duchu, odpuštěno nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Když by vás vedli do synagog a před vlády a vrchnosti, nestarejte se, jak [a čím] byste se obhájili nebo co byste řekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Neboť Svatý Duch vás v té hodině naučí, co je třeba říci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Někdo ze zástupu mu řekl: „Učiteli, řekni mému bratru, ať se se mnou rozdělí o dědictví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'On mu řekl: „Člověče, kdo mě ustanovil nad vámi soudcem nebo rozhodčím?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Řekl jim: „Mějte se na pozoru a střezte se před každou chamtivostí, neboť ⌈ i když má někdo nadbytek, není jeho život zajištěn tím, co vlastní⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Řekl jim podobenství: „Jednomu bohatému člověku přinesla země hojnou úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'A on v sobě o tom rozvažoval a říkal: Co budu dělat? Vždyť nemám, kam bych svou úrodu shromáždil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Pak řekl: Udělám toto: Zbořím své stodoly, postavím větší a tam shromáždím všechno své obilí a zásoby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'A řeknu své duši: Duše, máš hodně zásob na mnoho let; odpočívej, jez, pij, raduj se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Bůh mu však řekl: Blázne! Ještě této noci si od tebe vyžádají tvou duši, a čí bude to, co jsi připravil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Tak je to s tím, kdo si hromadí poklady, a není bohatý v Bohu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Řekl [svým] učedníkům: „Proto vám pravím: Nepečujte úzkostlivě o [svůj] život, co byste jedli, ani o tělo, co byste si oblékli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Neboť život je víc než pokrm a tělo víc než oděv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Pozorně si všimněte havranů, že nesejí ani nežnou, nemají komory ani stodoly, a Bůh je živí. Oč jste vy cennější než ptáci!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Kdo z vás dokáže úzkostlivou péčí přidat k délce svého věku [jediný] loket?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Nemůžete–li tedy ani to nejmenší, proč se úzkostlivě staráte o to ostatní?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Pozorně si všimněte lilií, jak rostou; ⌈nepracují ani nepředou⌉. Avšak pravím vám, ani Šalomoun v celé své slávě nebyl tak oblečen jako jedna z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Jestliže tedy Bůh tak obléká trávu, která dnes je na poli a zítra se hodí do pece, čím spíše obleče vás, malověrní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Ani vy nehledejte, co byste jedli a co byste pili, a nezneklidňujte se tím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Toto všechno horlivě hledají národy tohoto světa. Váš Otec ví, že to potřebujete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Hledejte však jeho království, a toto vám bude přidáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Neboj se, malé stádečko, neboť vašemu Otci se zalíbilo dát vám království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Prodejte svůj majetek a dejte almužnu. Udělejte si měšce, které nevetšejí, nevyčerpatelný poklad v nebesích, kde nepřichází zloděj ani neničí mol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Neboť kde je váš poklad, tam bude i vaše srdce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, '„Ať jsou vaše bedra přepásána a vaše lampy hořící.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Buďte podobni lidem, kteří čekají na svého pána, až se vrátí ze svatební hostiny, aby mu, jakmile přijde a zatluče, hned otevřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Blahoslavení ti otroci, které pán, až přijde, nalezne bdící. Amen, pravím vám, že se opáše, uloží je u stolu, přistoupí a bude je obsluhovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'A přijde–li o druhé nebo třetí noční hlídce a nalezne je tak, blahoslavení jsou ti otroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'To vězte, že kdyby hospodář věděl, v kterou hodinu přijde zloděj, [zůstal by vzhůru a] nedovolil by mu prokopat se do domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Také vy buďte připraveni, protože neznáte hodinu, v níž Syn člověka přijde.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Petr řekl: „Pane, říkáš toto podobenství jen nám, nebo také všem?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'A Pán řekl: „Kdo tedy je věrný, rozumný správce, jehož pán ustanoví nad svým služebnictvem, aby jim v pravý čas dával příděl potravin?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Blahoslavený ten otrok, kterého jeho pán po svém příchodu nalezne, že tak činí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Vpravdě vám pravím, že ho ustanoví nade vším svým majetkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Kdyby si však onen otrok řekl ve svém srdci: Můj pán dlouho nepřichází, a začal by bít sluhy i služky, jíst a pít a opíjet se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'přijde pán onoho otroka v den, kdy to nečeká, a v hodinu, kterou nezná, oddělí ho a určí mu díl s nevěrnými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Ten otrok, který znal vůli svého Pána, a přece všechno nepřipravil a neudělal podle jeho vůle, bude velmi zbit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Kdo ji však neznal a učinil něco, co si zaslouží rány, bude zbit méně. Od každého, komu bylo hodně dáno, bude také hodně vyžádáno, a komu svěřili hodně, od toho budou žádat více.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, '„Oheň jsem přišel uvrhnout na zemi; a jak chci, aby se již vznítil!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Křtem mám být pokřtěn, a jak jsem svírán, dokud se nedokoná!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Myslíte, že jsem přišel dát na zemi pokoj? Ne, pravím vám, ale rozdělení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Neboť od této chvíle bude v jednom domě pět lidí rozděleno: tři proti dvěma a dva proti třem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'budou rozděleni otec proti synu a syn proti otci, matka proti dceři a dcera proti matce, tchyně proti své snaše a snacha proti tchyni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Říkal také zástupům: „Když uvidíte na západě vznikat oblak, hned říkáte: Přijde prudký déšť. A bývá to tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'A když vane jižní vítr, říkáte: Bude horko. A bývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Pokrytci! Vzhled země a nebe umíte rozpoznávat; jak to, že tento čas rozpoznávat neumíte?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, '„Proč i sami od sebe nerozsuzujete, co je správné?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Když jdeš se svým protivníkem k vládci, usiluj o vyrovnání s ním už cestou, aby tě nevlekl k soudci a soudce tě nepředal biřici a biřic tě neuvrhl do vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Pravím ti, že odtamtud jistě nevyjdeš, dokud nevrátíš poslední haléř.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Právě v tu dobu byli přítomni někteří, kteří mu vyprávěli o Galilejcích, jejichž krev Pilát smísil s jejich oběťmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'On jim na to řekl: „Myslíte, že tito Galilejci byli větší hříšníci než všichni ostatní Galilejci, když toto vytrpěli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Ne, pravím vám, ale nebudete–li činit pokání, všichni podobně zahynete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Nebo oněch osmnáct, na které spadla věž v Siloe a zabila je; myslíte, že oni byli větší viníci než všichni ostatní lidé, kteří bydlí v Jeruzalémě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Ne, pravím vám, ale nebudete–li činit pokání, všichni právě tak zahynete.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Říkal toto podobenství: „Kdosi měl na své vinici zasazený fíkovník. I přišel na něm hledat ovoce, ale nenalezl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Řekl vinaři: Hle, po tři léta přicházím a hledám ovoce v tomto fíkovníku, a nenalézám. Vytni jej [tedy]! Proč kazí i tu zem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'On mu odpověděl: Pane, ponech ho i tento rok, až jej okopám a pohnojím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, '⌈neponese–li snad ovoce příště; jestliže ne, vytneš jej⌉. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'V sobotu učil v jedné synagoze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'A hle, byla tam žena, která měla ducha nemoci osmnáct let; byla sehnutá a vůbec se nemohla napřímit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Když ji Ježíš uviděl, zavolal ji a řekl: „Ženo, jsi zproštěna své nemoci“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'a vložil na ni ruce. Ona se ihnednarovnala a oslavovala Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Avšak představený synagogy, rozhněván, že Ježíš uzdravuje v sobotu, říkal zástupu: „Je šest dní, v nichž se má pracovat; v nich tedy přicházejte a buďte uzdravováni, a ne v den sobotní.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Na to mu Pán řekl: „Pokrytci! Neodvazuje každý z vás v sobotu svého vola nebo osla od žlabu a nevede ho napájet?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Tato však, dcera Abrahamova, kterou spoutal Satan, hle, na osmnáct let, neměla být rozvázána z toho pouta v den sobotní?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'A když to říkal, všichni jeho protivníci byli zahanbeni, ale celý zástup se radoval nad všemi těmi slavnými činy, které se od něho dály.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Říkal tedy: „Čemu se podobá Boží království a k čemu je připodobním?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Je podobné zrnu hořčice, které člověk vzal a hodil do své zahrady; vyrostlo, stalo se [velikým] stromem a v jeho větvích se uhnízdili nebeští ptáci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'A opět řekl: „K čemu připodobním Boží království?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Je podobné kvasu, který žena vzala a skryla do tří měřic mouky, dokud to všecko nezkvasilo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'A procházel městy a vesnicemi, učil a pokračoval v cestě do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Kdosi mu řekl: „Pane, je jen málo těch, kteří ⌈jsou zachraňováni⌉?“On jim řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '„Usilujte vejít úzkými dveřmi, neboť mnozí, pravím vám, se budou snažit vejít, ale nebudou schopni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'V tu chvíli, když by hospodář vstal a zavřel dveře, a vy byste zůstali stát venku, začali tlouci na dveře a říkat: Pane, otevři nám, on vám odpoví: Neznám vás a nevím, odkud jste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Tehdy začnete říkat: Jedli jsme ⌈před tebou⌉ i pili a na našich ulicích jsi učil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'A on ⌈vám řekne:⌉ ⌈Neznám vás a nevím, odkud jste⌉. Odstupte ode mne všichni činitelé nepravosti!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tam bude pláč a skřípění zubů, až spatříte Abrahama, Izáka a Jákoba a všechny proroky v Božím království, ale vás vyženou ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'A přijdou mnozí od východu i západu, od severu i jihu a budou stolovat v Božím království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'A hle, jsou poslední, kteří budou první, a jsou první, kteří budou poslední.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Právě v tu hodinu přišli někteří farizeové a řekli mu: „Vyjdi a jdi odtud, protože Herodes tě chce zabít.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'On jim řekl: „Jděte a řekněte té lišce: Hle, vyháním démony a uzdravuji dnes i zítra, a třetího dne dokonám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Avšak dnes, zítra i pozítří musím pokračovat v cestě, neboť není možné, aby prorok zahynul mimo Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jeruzaléme, Jeruzaléme, který zabíjíš proroky a kamenuješ ty, kteří jsou k tobě posláni, kolikrát jsem chtěl shromáždit tvé děti jako slepice svá kuřata pod křídla, ale nechtěli jste.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Hle, váš dům se vám zanechává [pustý]. Pravím vám, že mne zajisté nespatříte, dokud [nepřijde ten den, kdy] řeknete: Požehnaný, který přichází ve jménu Pána. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'A stalo se, když v sobotu vešel do domu jednoho z vůdců farizeů pojíst chleba a oni ho pozorně sledovali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'hle, byl před ním nějaký vodnatelný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Ježíš na to zákoníkům a farizeům řekl: „Je dovoleno v sobotu uzdravit, nebo ne?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Oni však mlčeli. I vzal ho, uzdravil jej a propustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'A jim řekl: „Spadne– li někomu z vás syn nebo vůl do nádrže, nevytáhne ho hned v den sobotní?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Na to nebyli schopni odpovědět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Pozvaným, když pozoroval, jak si vybírají přední místa, pověděl podobenství:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '„Když by tě někdo pozval na svatební hostinu, neuléhej na přední místo, aby snad nebyl pozván někdo vzácnější než ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Když pak přijde ten, kdo tebe i jeho pozval, a řekne ti: Dej tomuto své místo, potom s hanbou zaujmeš poslední místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Ale když jsi pozván, jdi a ulehni na poslední místo, aby ti ten, který tě pozval, až přijde, řekl: Příteli, postup dopředu. Pak budeš poctěn před všemi svými spolustolujícími.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Neboť každý, kdo se povyšuje, bude ponížen, a kdo se ponižuje, bude povýšen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Říkal také tomu, který ho pozval: „Když pořádáš oběd nebo večeři, nevolej své přátele ani své bratry ani své příbuzné ani bohaté sousedy, aby tě snad také nepozvali, a tak by se ti dostalo odplaty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Ale když pořádáš hostinu, zvi chudé, zmrzačené, chromé a slepé,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'a budeš blahoslavený, protože nemají, čím ti odplatit; bude ti odplaceno při zmrtvých vstání spravedlivých.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Když to uslyšel jeden ze spolustolujících, řekl mu: „Blahoslavený, kdo bude jíst chléb v Božím království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Ježíš mu řekl: „Jeden člověk pořádal velikou večeři a pozval mnohé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'A v hodinu večeře poslal svého otroka říci pozvaným: Pojďte, protože [vše] už je připraveno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'I začali se všichni stejně vymlouvat. První mu řekl: Koupil jsem pole a musím se na ně jít podívat. Prosím tě, přijmi mou omluvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'A druhý řekl: Koupil jsem pět párů volů a jdu je vyzkoušet. Prosím tě, přijmi mou omluvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'A další řekl: Oženil jsem se, a proto nemohu přijít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Když otrok přišel, oznámil to svému pánu. Tu se hospodář rozhněval a svému otroku řekl: Vyjdi rychle na náměstí a do ulic města a přiveď sem chudé, zmrzačené, slepé a chromé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'A otrok řekl: Pane, stalo se, co jsi přikázal, a ještě je místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'A pán řekl otroku: Vyjdi na cesty a k ohradám a přinuť je vejít, aby se můj dům naplnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Neboť vám pravím, že nikdo z těch mužů, kteří jsou pozváni, neokusí mé večeře. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Šly s ním velké zástupy. Obrátil se a řekl jim:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '„Přichází–li někdo ke mně a nemá v nenávisti svého otce a matku, manželku a děti, bratry a sestry, ano i vlastní duši, nemůže být mým učedníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Kdo jde za mnou a nenese svůj kříž, nemůže být mým učedníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Neboť když někdo z vás chce postavit věž, což si napřed nesedne a nepočítá náklad, má–li na dokončení stavby?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Jinak by se mu všichni, kteří to vidí, začali posmívat, když by položil základ a nemohl by stavbu dokončit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'a říkali by: Tento člověk začal stavět, ale nemohl dokončit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Nebo táhne–li nějaký král, aby se s jiným králem střetl ve válce, což si napřed nesedne a nerozváží, je–li schopen s deseti tisíci utkat se s tím, kdo proti němu přichází s dvaceti tisíci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Jestliže ne, pošle poselstvo, dokud je ten druhý král ještě daleko, a ptá se na podmínky míru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Tak tedy žádný z vás, kdo neopouští všechno, co mu náleží, nemůže být mým učedníkem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, '„Dobrá je sůl. Jestliže by však i sůl ztratila chuť, čím bude ochucena?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Nehodí se ani do země ani do hnoje; vyhazují ji ven. Kdo má uši k slyšení, ať naslouchá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Přibližovali se k němu všichni celníci a hříšníci, aby ho slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Farizeové a učitelé Zákona reptali: „Tento člověk přijímá hříšníky a jí s nimi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Řekl jim toto podobenství:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '„Kdo z vás, má–li sto ovcí a jednu z nich by ztratil, nezanechá těch devadesát devět v pustině a nejde za tou ztracenou, dokud ji nenalezne?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'A když ji nalezne, vloží si ji s radostí na svá ramena,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'přijde domů, svolá přátele a sousedy a řekne jim: Zaradujte se se mnou, protože jsem nalezl svou ovci, která se ztratila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Pravím vám, že tak bude v nebi větší radost nad jedním hříšníkem, který činí pokání, než nad devadesáti devíti spravedlivými, kteří pokání nepotřebují.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, '„Nebo nějaká žena, která má deset drachem a jednu by ztratila, což nezapálí lampu, nevymetá dům a pečlivě nehledá, dokud ji nenalezne?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'A když ji najde, svolá přítelkyně a sousedky a řekne: Zaradujte se se mnou, protože jsem nalezla drachmu, kterou jsem ztratila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Tak, pravím vám, je radost před anděly Božími nad jedním hříšníkem, který činí pokání.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Řekl: „Jeden člověk měl dva syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Mladší z nich řekl otci: Otče, dej mi díl majetku, který na mne připadá. On jim rozdělil majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Po nemnoha dnech mladší syn všechno sebral, odešel do daleké krajiny a tam rozmařilým životem svůj majetek rozházel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'A když všechno utratil, nastal v té krajině veliký hlad a on začal mít nouzi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Šel a přichytil se jednoho občana té krajiny, a ten ho poslal na svá pole pást vepře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'A toužil ⌈se nasytit⌉ lusky, které žrali vepři, ale nikdo mu je nedával.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Tu přišel k sobě a řekl: Jak mnoho nádeníků mého otce má nadbytek chleba, a já zde hynu hladem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Vstanu, půjdu ke svému otci a řeknu mu: Otče, zhřešil jsem proti nebi i před tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Nejsem již hoden nazývat se tvým synem. Učiň mne jedním ze svých nádeníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'I vstal a přišel ke svému otci. Když byl ještě daleko, jeho otec ho uviděl a byl hluboce pohnut; i běžel, padl mu kolem krku a zlíbal ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Syn mu řekl: Otče, zhřešil jsem proti nebi i před tebou. Nejsem již hoden nazývat se tvým synem. [Učiň mne jedním ze svých nádeníků.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Otec však řekl svým otrokům: Přineste rychle to nejlepší roucho a oblečte ho, a dejte mu na ruku prsten a na nohy sandály.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Přiveďte tučné tele, zabijte je, jezme a radujme se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'protože tento můj syn byl mrtvý, a zase ožil, ztratil se, a byl nalezen. A začali se radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Jeho starší syn byl na poli. Když přicházel a přiblížil se k domu, uslyšel hudbu a tanec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Zavolal si jednoho ze služebníků a vyptával se, co to má znamenat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'On mu řekl: Přišel tvůj bratr a tvůj otec zabil tučné tele, že jej dostal nazpět zdravého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Rozhněval se a nechtěl vejít. Jeho otec vyšel a začal mu domlouvat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'On však svému otci odpověděl: Hle, tolik let ti sloužím a nikdy jsem nepřestoupil tvůj příkaz, ale nikdy jsi mi nedal ani kůzle, abych se poveselil se svými přáteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Když však přišel tenhle tvůj syn, který prožral tvůj majetek s nevěstkami, zabil jsi mu tučné tele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'On mu řekl: Synu, ty jsi vždycky se mnou, a všechno, co je mé, je tvé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Avšak bylo proč se veselit a radovat, protože tento tvůj bratr byl mrtev, a ožil, ztratil se, a byl nalezen. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Učedníkům také říkal: „Byl jeden bohatý člověk, který měl správce, a ten byl u něho obviněn, že rozhazuje jeho majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Zavolal ho a řekl mu: Co to o tobě slyším? Vydej počet ze svého správcovství, neboť dále nemůžeš být správcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Správce si řekl: Co budu dělat, když mi můj pán odnímá správcovství? Kopat nemohu, žebrat se stydím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Vím, co udělám, aby mne přijali do svých domů, až budu zbaven správcovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'A zavolal si dlužníky svého pána jednoho po druhém a řekl prvnímu: Kolik dlužíš mému pánovi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'On řekl: Sto věder oleje. Řekl mu: Vezmi svůj úpis, rychle sedni a napiš padesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Pak řekl druhému: Ty dlužíš kolik? On řekl: Sto měr pšenice. Říká mu: Vezmi svůj úpis a napiš osmdesát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'A pán pochválil nepoctivého správce, že jednal rozumně. Neboť synové tohoto věku jsou vůči svému pokolení rozumnější než synové světla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'A já vám pravím: Učiňte si přátele z mamonu nepravosti, aby vás, až pomine, přijali do věčných stanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Věrný v nejmenším je věrný i ve velkém; nepoctivý v nejmenším je nepoctivý i ve velkém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Jestliže jste tedy nebyli věrní v nepoctivém mamonu, kdo vám svěří to pravé bohatství?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'A jestliže jste nebyli věrní v cizím, kdo vám dá, co je vaše?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Žádný sluha nemůže sloužit dvěma pánům. Neboť jednoho bude nenávidět, a druhého milovat, jednoho se bude držet, a druhým bude pohrdat. Nemůžete sloužit Bohu i mamonu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Toto všechno slyšeli [i] farizeové, kteří byli lakomí, a vysmívali se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Řekl jim: „Vy jste ti, kteří se před lidmi dělají spravedlivými, Bůh však zná vaše srdce; neboť co je u lidí vznešené, je před Bohem ohavnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Zákon a Proroci až do Jana; od té chvíle se zvěstuje Boží království a každý ⌈je do něho naléhavě zván⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Je však snadnější, aby pominuly nebe a země, než aby padla jedna čárka Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Každý, kdo propouští svou ženu a žení se s jinou, cizoloží, a kdo se žení s tou, kterou muž propustil, cizoloží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, '„Byl jeden bohatý člověk, a oblékal se do purpuru a kmentu a den co den skvěle hodoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'U jeho vrat lehával nějaký chudák, jménem Lazar, plný vředů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'a toužil se nasytit aspoň ⌈tím, co padalo⌉ ze stolu toho boháče; dokonce i psi přicházeli a lízali jeho vředy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Stalo se, že ten chudák zemřel a byl anděly odnesen do klína Abrahamova; zemřel pak i boháč a byl pohřben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'A když v podsvětí v mukách pozdvihl oči, uviděl v dáli Abrahama a Lazara v jeho klíně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'I zvolal: Otče Abrahame, smiluj se nade mnou a pošli Lazara, aby namočil špičku svého prstu vodou a ochladil můj jazyk, neboť trpím bolestí v tomto plameni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Abraham řekl: Synu, vzpomeň si, že ⌈sis už vybral⌉ své dobré ve svém životě, a Lazar podobně zlé. Nyní je zde potěšován, ty však jsi sužován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'A k tomu všemu je mezi námi a vámi upevněna veliká propast, aby ti, kdo chtějí, nemohli přejít odtud k vám, ani se přepravit odtamtud k nám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Řekl: Prosím tě tedy, otče, abys ho poslal do domu mého otce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'neboť mám pět bratrů, ať jim svědčí, aby také oni nepřišli do tohoto místa muk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham řekl: Mají Mojžíše a Proroky, ať je poslechnou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'On řekl: Ne, otče Abrahame, ale kdyby k nim přišel někdo z mrtvých, budou činit pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Řekl mu: Neposlouchají–li Mojžíše a Proroky, nedají se přesvědčit, ani kdyby někdo vstal z mrtvých. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Ježíš řekl svým učedníkům: „Není možné, aby nepřišla pohoršení, běda však tomu, skrze koho přicházejí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Pro toho by bylo lépe, kdyby mu přivázali na krk mlýnský kámen a uvrhli ho do moře, než aby pohoršil jednoho z těchto maličkých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Mějte se na pozoru. Zhřeší–li tvůj bratr, pokárej ho, a ⌈uzná–li svou vinu⌉, odpusť mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'A zhřeší–li proti tobě sedmkrát za den a sedmkrát se k tobě obrátí se slovy: Uznávám svou vinu, odpusť mi, odpustíš mu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Apoštolové řekli Pánu: „Přidej nám víry!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Pán řekl: „Kdybyste měli víru jako zrno hořčice, řekli byste této moruši: Vykořeň se a přesaď se do moře, a poslechla by vás.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, '„Kdo z vás, kdo má otroka, který oře nebo pase stádo, mu řekne, když se vrátí z pole: Pojď hned a ulehni ke stolu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Neřekne mu spíše: Připrav něco k jídlu, opaš se a obsluhuj mne, dokud se nenajím a nenapiji; pak budeš jíst a pít ty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Děkuje snad tomu otroku, že udělal, co [mu] bylo přikázáno? [Nemyslím.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Tak i vy, když uděláte všechno, co vám bylo přikázáno, řekněte: Jsme nehodní otroci; udělali jsme, co jsme byli povinni udělat. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'A stalo se, když byl na cestě do Jeruzaléma, že procházel Samařskem a Galileou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Když vcházel do jedné vesnice, setkalo se s ním deset malomocných mužů, kteří zůstali stát opodál');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'a hlasitě zvolali: „Ježíši, Mistře, smiluj se nad námi!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Když je uviděl, řekl jim: „Jděte a ukažte se kněžím.“A stalo se, když odcházeli, že byli očištěni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Jeden z nich, když uviděl, že je uzdraven, se vrátil a velikým hlasem oslavoval Boha;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'padl na tvář k jeho nohám a děkoval mu. A byl to Samařan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Ježíš na to řekl: „Nebylo jich očištěno deset? Kde je těch devět?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Nikdo z nich se nenašel, aby se vrátil a vzdal chválu Bohu, kromě tohoto cizince?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'A řekl mu: „Vstaň a jdi, tvá víra tě zachránila.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Když se ho farizeové otázali, kdy přijde Boží království, odpověděl jim: „Boží království nepřichází ⌈tak, abyste ho mohli pozorovat⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'ani neřeknou: Hle, je tu nebo je tam. Neboť hle, Boží království je mezi vámi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Učedníkům řekl: „Přijdou dny, kdy zatoužíte spatřit aspoň jeden ze dnů Syna člověka, ale nespatříte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'A budou vám říkat: Hle, zde je nebo hle, tam! Nechoďte a neběhejte za nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Neboť jako blýskající se blesk září z jedné končiny pod nebem do druhé končiny pod nebem, tak bude Syn člověka [ve svém dni].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Napřed však musí mnoho vytrpět a být tímto pokolením zavržen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'A jak bylo za dnů Noé, tak bude i za dnů Syna člověka:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'jedli, pili, ženili se a vdávaly až do dne, kdy Noé vešel do korábu a přišla potopa a zahubila všechny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Podobně bylo za dnů Lota: jedli, pili, kupovali, prodávali, sázeli a stavěli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'avšak toho dne, kdy Lot vyšel ze Sodomy, pršel z nebe oheň se sírou a zahubil všechny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Právě tak to bude toho dne, kdy se zjeví Syn člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Kdobude v onen den na střeše a své věci bude mít v domě, ať nesestupuje, aby si je vzal; a podobně kdo bude na poli, ať se nevrací zpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Pamatujte na Lotovu ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Kdo by usiloval svoji duši zachovat, ztratí ji, kdo však by ji ztratil, zachová ji k životu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Pravím vám, že té noci budou dva na jednom lůžku, jeden bude vzat, a druhý zanechán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Dvě budou spolu mlít, jedna bude vzata, a druhá zanechána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '[Dva budou na poli, jeden bude vzat, a druhý zanechán.] “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Řekli mu: „Kde to bude, Pane?“On jim řekl: „Kde je tělo, tam se shromáždí i supi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Vyprávěl jim [také] podobenství, aby viděli, jak je třeba stále se modlit a neochabovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Říkal: „V jednom městě byl soudce, který se Boha nebál a z člověka si nic nedělal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'V tom městě byla vdova, která k němu chodila a říkala: Zastaň se mě proti mému odpůrci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Ale on dlouho nechtěl. Potom si však řekl: I když se Boha nebojím a z člověka si nic nedělám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'zastanu se té vdovy, protože mi působí mnohou nesnáz, aby mě nakonec nepřišla zpolíčkovat. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Pán řekl: „Slyšte, co říká ten nespravedlivý soudce!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Nezastane se Bůh svých vyvolených, kteří k němu volají dnem i nocí? Bude s pomocí pro ně otálet?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Pravím vám, že se jich rychle zastane. Jen až přijde Syn člověka, zdali nalezne víru na zemi?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'A těm, kteří spoléhali na sebe, že jsou spravedliví, a ostatními pohrdali, řekl toto podobenství:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '„Dva lidé vystoupili do chrámu, aby se pomodlili: jeden byl farizeus, druhý celník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Farizeus se postavil a takto se sám u sebe modlil: Bože, děkuji ti, že nejsem jako ostatní lidé, lupiči, nespravedliví, cizoložníci, nebo i jako tento celník.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Postím se dvakrát týdně a dávám desátky ze všeho, co získávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Avšak celník, který stál opodál, nechtěl ani oči k nebi pozdvihnout; bil se do prsou a říkal: Bože, projev milost mně hříšnému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Pravím vám, že ten sestoupil do svého domu ospravedlněn spíše než onen farizeus. Neboť každý, kdo se povyšuje, bude pokořen, kdo se však pokořuje, bude povýšen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Přinášeli k němu i nemluvňata, aby se jich dotýkal. Když to uviděli učedníci, kárali je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Ježíš si je zavolal a řekl: „Nechte děti přicházet ke mně a nebraňte jim, neboť takovým patří Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Amen, pravím vám, kdo nepřijme Boží království jako dítě, jistě do něho nevstoupí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Jeden z předních mužů se ho otázal: „Dobrý učiteli, co ⌈mám učinit, abych získal⌉ věčný život?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Ježíš mu řekl: „Proč mne nazýváš dobrým? Nikdo není dobrý, než jeden: Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Přikázání znáš: Abys nezcizoložil, nezabil, neukradl, nevydal křivé svědectví; cti svého otce i matku.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'On řekl: „To všechno zachovávám od [svého] mládí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Když to Ježíš uslyšel, řekl mu: „Jedno ti ještě schází: Prodej všechno, co máš, rozdej chudým a budeš mít poklad v nebesích; pak přijď a následuj mne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Když to uslyšel, velice se zarmoutil, neboť byl velmi bohatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Když ho Ježíš uviděl, [jak se velice zarmoutil,] řekl: „Jak těžko vcházejí do Božího království ti, kdo mají majetek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Neboť je snadnější, aby velbloud prošel uchem jehly, než aby bohatý vešel do Božího království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Ti, kdo to slyšeli, řekli: „A kdo může být zachráněn?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'On řekl: „Co je nemožné u lidí, je možné u Boha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Petr řekl: „Hle, my jsme opustili [všechno], co jsme měli, a vydali se za tebou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'On jim řekl: „Amen, pravím vám, že není nikdo, kdo opustil dům nebo ženu nebo bratry nebo rodiče nebo děti pro Boží království,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'aby v tomto čase nedostal mnohokrát víc a v přicházejícím věku život věčný.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Vzal k sobě těch Dvanáct a řekl jim: „Hle, vystupujeme do Jeruzaléma a naplní se všechno, co je napsáno skrze proroky o Synu člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Neboť bude vydán pohanům a vysmějí se mu, bude potupen a popliván,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'zbičují ho a zabijí; a třetího dne vstane z mrtvých.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Ale oni ničemu z toho neporozuměli a ten výrok byl před nimi skrytý; nechápali, co bylo řečeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Stalo se, když se přibližoval k Jerichu, že nějaký slepec seděl u cesty a žebral.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Když uslyšel, že jde kolem zástup, vyptával se, co se to děje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Oznámili mu, že tudy jde Ježíš Nazaretský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Tu zvolal: „Ježíši, synu Davidův, smiluj se nade mnou!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Ti, kteří šli vpředu, mu přísně domlouvali, aby zmlkl. On však tím víc křičel: „Synu Davidův, smiluj se nade mnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Ježíš se zastavil a rozkázal, aby ho k němu přivedli. Když se přiblížil, Ježíš se ho zeptal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '„Co chceš, abych ti učinil?“On řekl: „Pane, ať vidím!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Ježíš mu řekl: „Prohlédni! Tvá víra tě uzdravila.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'A hned prohlédl, šel za ním a oslavoval Boha. A všechen lid, který to viděl, vzdal Bohu chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Ježíš vešel do Jericha a procházel jím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'A hle, byl tam muž jménem Zacheus. Ten byl vrchním celníkem a byl bohatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Chtěl uvidět Ježíše, aby se přesvědčil, kdo to je, ale protože byl malé postavy, nemohl ho pro zástup vidět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Běžel tedy napřed a vylezl na ⌈planý fíkovník⌉, aby ho uviděl, neboť tudy měl procházet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Když Ježíš přišel na to místo, vzhlédl a řekl mu: „Zachee, slez rychle dolů, neboť dnes musímzůstat v tvém domě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'On rychle slezl a s radostí ho přijal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Všichni, kdo to uviděli, začali reptat: „Vešel jako host k hříšnému muži!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zacheus se zastavil a řekl Pánu: „Hle, polovinu svého majetku, Pane, dám chudým, a jestliže jsem někoho ošidil, vrátím mu to čtyřnásobně.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Ježíš mu řekl: „Dnes se dostalo záchrany tomuto domu, protože i tento člověk je syn Abrahamův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Neboť Syn člověka přišel vyhledat a zachránit, co je ztraceno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Když to lidé poslouchali, řekl další podobenství, protože byl blízko Jeruzaléma a oni si mysleli, že Boží království se má objevit ihned.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Proto řekl: „Jeden urozený člověk odešel do daleké krajiny, aby se ujal kralování a pak se vrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Zavolal deset svých otroků, dal jim deset hřiven a řekl jim: Hospodařte s nimi, dokud nepřijdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Avšak jeho spolu občané ho nenáviděli a poslali za ním poselstvo se slovy: Nechceme, aby nad námi tento člověk kraloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'A stalo se, když se ⌈jako král⌉ vrátil, že si dal zavolat ty otroky, kterým svěřil peníze, aby se dověděl, ⌈kolik vydělali⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Přišel první a řekl: Pane, tvoje hřivna vynesla deset hřiven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Řekl mu: Výborně, dobrý otroku, protože jsi v nejmenší věci byl věrný, měj pravomoc nad deseti městy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Přišel druhý a řekl: Tvá hřivna, Pane, získala pět hřiven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Také tomuto řekl: I ty buď vládcem nad pěti městy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'A přišel jiný a řekl: Pane, hle, tvá hřivna, kterou jsem měl uloženou v šátku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'neboť jsem se tě bál, protože jsi přísný člověk: bereš, co jsi nedal, a sklízíš, co jsi nezasel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Řekl mu: ⌈Podle tvých slov⌉ tě budu soudit, špatný otroku. Věděl jsi, že jsem člověk přísný a beru, co jsem nedal, a sklízím, co jsem nezasel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Proč jsi nedal mé peníze na stůl směnárníkovi? A já bych si je po příchodu vybral s úrokem!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'A těm, kteří tam stáli, řekl: Vezměte od něho tu hřivnu a dejte tomu, který má deset hřiven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '[Řekli mu: Pane, už má deset hřiven.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Pravím vám, že každému, kdo má, bude dáno; kdo nemá, tomu bude odňato i to, co má.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Avšak ty mé nepřátele, kteří nechtěli, abych nad nimi kraloval, přiveďte sem a přede mnou je pobijte. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Když to pověděl, kráčel napřed a vystupoval do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'A stalo se, když se přiblížil do Betfage a Betanie k hoře, která se nazývá Olivová, že poslal dva z učedníků');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'a řekl: „Jděte naproti do vesnice. Když do ní budete vcházet, naleznete přivázané oslátko, na němž dosud nikdo z lidí neseděl. Odvažte je a přiveďte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'A bude–li se vás někdo ptát: Proč je odvazujete? odpovězte takto: Pán je potřebuje. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Ti, kdo byli posláni, odešli a nalezli vše, jak jim řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Když oslátko odvazovali, řekli jim jeho páni: „Proč odvazujete to oslátko?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Oni odpověděli: „Pán je potřebuje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'A přivedli je k Ježíšovi, hodili na oslátko své pláště a Ježíše na ně posadili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'A jak jel, prostírali své pláště na cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Když se již přibližoval ke svahu Olivové hory, začal celý ten zástup učedníků radostně velikým hlasem chválit Boha za všechny mocné činy, které spatřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Říkali: „⌈Požehnaný král, jenž přichází⌉ ve jménu Pána. V nebi pokoj a sláva na výsostech!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Někteří farizeové ze zástupu mu řekli: „Učiteli, pokárej své učedníky.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Ježíš jim na to řekl: „Pravím vám, budou–li oni mlčet, bude křičet kamení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'A když se přiblížil a uviděl město, dal se nad ním do pláče');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'a řekl: „Kdybys [aspoň] v tento [svůj] den poznalo i ty, co je k [tvému] pokoji. Avšak nyní je to před tvýma očima skryto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Neboť přijdou na tebe dny, kdy tě tvoji nepřátelé obklopí náspem, obklíčí tě a sevřou ze všech stran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Srovnají se zemí tebe i tvé děti v tobě a nenechají v tobě kámen na kameni za to, že jsi nepoznalo čas svého navštívení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'A když vešel do chrámu, začal vyhánět ty, kteří tam prodávali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'a říkal jim: „Je napsáno: A můj dům bude domem modlitby, vy však jste z něj udělali jeskyni lupičů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Každý den vyučoval v chrámě. Velekněží a učitelé Zákona i přední muži z lidu se snažili jej zahubit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'ale nenalézali, co by mohli udělat, neboť všechen lid na něm visel a naslouchal mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'A stalo se v jednom z těch dnů, kdy učil lid v chrámě a zvěstoval evangelium, že k němu přistoupili velekněží a učitelé Zákona se staršími');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'a řekli mu: „Pověz nám, v jaké pravomoci to činíš? Nebo kdo je ten, který ti tuto pravomoc dal?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Odpověděl jim: „I já se vás zeptám na [jednu] věc. Povězte mi:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Křest Janův byl z nebe, nebo z lidí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Oni o tom mezi sebou rozvažovali: „Řekneme–li z nebe, řekne: Proč jste mu neuvěřili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Řekneme–li však z lidí, všechen lid nás bude kamenovat, neboť je přesvědčen, že Jan byl prorok.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'I odpověděli, že nevědí, odkud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'A Ježíš jim řekl: „Ani já vám nepovím, v jaké pravomoci to činím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Začal lidu říkat toto podobenství: „[Jeden] člověk vysadil vinici, pronajal ji vinařům a na dlouhou dobu odcestoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'V stanovený čas poslal k vinařům otroka, aby mu dali díl z úrody vinice. Avšak vinaři ho zbili a poslali s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Poslal ještě jiného otroka; oni však i toho zbili, zneuctili a poslali s prázdnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'A poslal ještě třetího; i toho zranili a vyhnali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Pán vinice řekl: Co mám udělat? Pošlu svého milovaného syna; snad ⌈se před ním zastydí.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Když ho vinaři spatřili, domlouvali se mezi sebou: To je dědic. Zabijme ho, aby dědictví bylo naše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'A vyhodili ho z vinice ven a zabili. Co jim tedy učiní pán vinice?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Přijde, zahubí tyto vinaře a vinici dá jiným.“Když to uslyšeli, řekli: „Kéž se tak nestane!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'On na ně pohlédl a řekl: „Co tedy znamená to, co je napsáno: Kámen, který stavitelé po prozkoumání zavrhli, se stal hlavou úhlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Každý, kdo padne na ten kámen, roztříští se, a na koho padne, toho rozdrtí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'V tu hodinu na něj chtěli učitelé Zákona a velekněží vztáhnout ruce, ale báli se lidu. Poznali totiž, že toto podobenství řekl proti nim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, '⌈Pozorně ho sledovali⌉ a poslali špehy, kteří předstírali, že jsou spravedliví, aby ⌈ho chytili za slovo⌉, a tak ho mohli vydat vrchnosti a vladařově pravomoci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Otázali se ho: „Učiteli, víme, že správně mluvíš a učíš a ⌈nebereš ohled na osobu⌉, ale podle pravdy učíš Boží cestě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Je nám dovoleno dát daň císaři, nebo ne?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Ježíš zpozoroval jejich lstivost a řekl jim:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '„ [Proč mne zkoušíte?] Ukažte mi denár! Čí má obraz a nápis?“Oni řekli: „Císařův.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'On jim řekl: „Odevzdejte tedy to, co je císařovo, císaři, a co je Boží, Bohu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'A nedokázali ho před lidem nachytat v [jeho] řeči; podivili se jeho odpovědi a zmlkli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Přišli někteří ze saduceů, kteří popírají vzkříšení, a zeptali se ho:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, '„Učiteli, Mojžíš nám napsal, že zemře–li něčí bratr, který má ženu a je bezdětný, aby si tu ženu vzal za manželku jeho bratr a vzbudil svému bratru potomka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Bylo tedy sedm bratrů. Oženil se první a zemřel bezdětný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Stejně i druhý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Také třetí si ji vzal a stejně všech sedm; nezanechali děti a zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Nakonec zemřela i ta žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Komu z nich bude tato žena patřit při vzkříšení? Vždyť všech sedm ji mělo za ženu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Ježíš jim řekl: „Synové tohoto věku se žení a vdávají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Avšak ti, kteří budou uznáni za hodny dosáhnout budoucího věku a zmrtvýchvstání, se nebudou ženit ani vdávat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Vždyť již nebudou moci ani zemřít, neboť budou jako andělé a budou synové Boží, jsouce syny zmrtvých vstání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'A že mrtví vstávají, ukázal i Mojžíš při keři, když nazývá Pána Bohem Abrahamovým, Bohem Izákovým a Bohem Jákobovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Bůh není Bohem mrtvých, ale živých, neboť všichni žijí jemu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Někteří z učitelů Zákona na to řekli: „Učiteli, dobře jsi to řekl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'A už se ho neodvažovali na nic ptát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Řekl jim: „Jak mohou říkat, že Kristus je Davidovým synem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Vždyť sám David v knize Žalmů říká: Řekl Pán mému Pánu: Seď po mé pravici,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'dokud nepoložím tvé nepřátele za podnož tvých nohou..');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David ho tedy nazývá Pánem; jakpak tedy je jeho synem?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Když všechen lid poslouchal, řekl [svým] učedníkům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '„Mějte se na pozoru před učiteli Zákona, kteří se chtějí procházet v dlouhých řízách, mají rádi pozdravy na tržištích, přední sedadla v synagogách a přední místa na hostinách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Vyjídají domy vdov a okázale se dlouho modlí; ti dostanou větší trest.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Když vzhlédl, uviděl, jak bohatí vhazují své dary do pokladnice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Uviděl také jednu chudou vdovu, jak tam hází dvě ⌈drobné mince⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'a řekl: „Vpravdě vám pravím, že tato chudá vdova hodila více než všichni ostatní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Neboť ti všichni v hodili k [Božím] darům ze svého přebytku, tato však v hodila ze svého nedostatku celé ⌈svoje živobytí⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Když někteří mluvili o chrámu, že je vyzdoben krásnými kameny a obětními dary, řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '„Přijdou dny, ve kterých z toho, co vidíte, [zde] nezůstane kámen na kameni, který nebude stržen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Otázali se ho: „Učiteli, kdy to bude? A jaké bude znamení, až se to začne dít?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Řekl: „Dávejte si pozor, abyste nebyli svedeni. Neboť mnozí přijdou ⌈v mém jménu⌉ a budou říkat: Já jsem a ten čas je tu. Nechoďte za nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Když byste uslyšeli o válkách a nepokojích, nevyděste se. Neboť to musí nejprve nastat, ale konec ne bude hned.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Potom jim říkal: „Povstane národ proti národu a království proti království,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'budou veliká země třesení a na různých místech hlad a mor, budou hrůzy a veliká znamení z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Avšak před tím vším vztáhnou na vás ruce a budou vás pronásledovat, vydávajíce vás do synagog a do vězení, budete pro mé jméno předváděni před krále a vladaře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'To vám bude svědectvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Uložte si tedy do svých srdcí, abyste se předem nepřipravovali, jak se budete hájit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Neboť já vám dám řeč a moudrost, které nebudou moci odolat ani ji vyvrátit žádní vaši protivníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Vydají vás i rodiče, bratři, příbuzní a přátelé a někteří z vás budou usmrceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'A všichni vás budou nenávidět pro mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Ale ani vlas z vaší hlavy se určitě neztratí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Svou trpělivostí získejte své duše.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, '„Když uvidíte, že Jeruzalém je obkličován vojsky, tehdy vězte, že se přiblížilo jeho zpustošení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Pak ti, kdo jsou v Judsku, ať utíkají do hor, a ti, kdo jsou v jeho středu, ať vyjdou, a kteří jsou na venkově, ať do něho nevcházejí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'protože toto jsou dny trestu, aby se naplnilo všechno, co je napsáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Běda těhotným a kojícím v oněch dnech! Neboť bude veliká tíseň na zemi a hněv proti tomuto lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Padnou ostřím meče a jako zajatci budou odvedeni mezi všecky národy, a po Jeruzalému budou šlapat národy, dokud se nenaplní ⌈jejich čas⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, '„A budou znamení na slunci, měsíci a hvězdách a na zemi úzkost národů, bezradných před řevem a vlnobitím moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Lidé budou omdlévat strachem a očekáváním toho, co přichází na celý svět; neboť mocnosti nebes se zatřesou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'A potom uvidí Syna člověka přicházet v oblaku s mocí a velikou slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Když se toto začne dít, napřimte se a zvedněte hlavy, protože se přibližuje vaše vykoupení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'A řekl jim podobenství: „Podívejte se na fíkovník a na všechny ostatní stromy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Když vidíte, že již vypučely, sami víte, že léto je již blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Tak i vy, až uvidíte, že se toto děje, vězte, že je blízko Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Amen, pravím vám, že určitě nepomine ono pokolení, dokud se toto všechno nestane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Nebe a země pominou, ale má slova jistě nepominou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, '„Mějte se na pozoru, aby vaše srdce nebyla zatížena [flámováním, opilstvím a ⌈starostmi každodenního života⌉ a onen den na vás nepřišel náhle');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, '⌈jako past. Neboť přijde⌉ na všechny, kteří ⌈přebývají na povrchu⌉ celé země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Bděte a proste v každý čas, abyste měli sílu uniknout všemu tomu, co se má dít, a postavit se před Syna člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Ve dne učil v chrámě, ale v noci vycházel a zůstával na hoře zvané Olivová.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'A všechen lid k němu časně zrána přicházel, aby ho v chrámě poslouchal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Blížil se svátek nekvašených chlebů, který se nazývá Pascha, to jest velikonoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Velekněží a učitelé Zákona hledali způsob, jak by ho odstranili, báli se však lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Tu Satan vstoupil do Judy, nazývaného Iškariotský, který byl z počtu Dvanácti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Odešel a promluvil s velekněžími a veliteli chrámové stráže, jak by jim ho vydal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Oni se zaradovali a dohodli se, že mu dají peníze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Juda souhlasil a hledal vhodnou příležitost, aby jim ho vydal někde ⌈stranou od⌉ zástupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Přišel den nekvašených chlebů, ve kterém měl být obětován ⌈velikonoční beránek⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Ježíš poslal Petra a Jana a řekl: „Jděte a připravte nám beránka, abychom pojedli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Oni mu řekli: „Kde chceš, abychom jej připravili?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Řekl jim: „Hle, až vejdete do města, potká vás člověk, který ponese džbán vody. Jděte za ním do domu, do něhož vejde,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'a hospodáři toho domu řekněte: Učitel ti praví: Kde je místnost, kde bych pojedl se svými učedníky ⌈velikonočního beránka⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'A on vám ukáže velkou horní místnost, již prostřenou; tam jej připravte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Odešli a nalezli vše, jak jim řekl, a připravili ⌈velikonočního beránka⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Když nastala ta hodina, zaujal místo u stolu a apoštolové s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Řekl jim: „Toužebně jsem si přál jíst s vámi tohoto beránka, dříve než budu trpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Neboť vám pravím, že ho [již] nebudu jíst, dokud nedojde naplnění v Božím království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'A vzal kalich, vzdal díky a řekl: „Vezměte to a rozdělte mezi sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Neboť vám pravím, že od této chvíle již nebudu pít z plodu vinné révy, dokud nepřijde Boží království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Pak vzal chléb, vzdal díky, rozlomil a dal jim se slovy: „Toto je mé tělo, které se za vás dává. To čiňte na mou památku.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'A právě tak vzal po večeři kalich a řekl: „Tento kalich je nová smlouva v mé krvi, která se za vás vylévá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Avšak hle, ruka toho, který mne zrazuje, je se mnou na stole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Syn člověka jde, jak je určeno, ale běda tomu člověku, který ho zrazuje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'A oni se začali mezi sebou dohadovat, který z nich je ten, kdo to učiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Vznikl mezi nimi také spor, kdo z nich je asi největší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'On jim řekl: „Králové národů panují nad nimi a ti, kteří nad nimi mají pravomoc, jsou nazýváni dobrodinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Avšak ne tak vy; kdo je mezi vámi největší, buď jako ten nejmenší, a kdo je vedoucí, buď jako ten, který slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Neboť kdo je větší: ten, který je u stolu, či ten, kdo obsluhuje? Zdali ne ten, který je u stolu? Já však jsem mezi vámi jako ten, který slouží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'A vy jste ti, kdo se mnou v mých zkouškách vytrvali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'A já vám uděluji království, jako je můj Otec udělil mně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'abyste jedli a pili u mého stolu v mém království; usednete na trůnech a budete soudit dvanáct kmenů Izraele.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, '„Šimone, Šimone, hle, Satan si vás vyžádal, aby vás vytříbil jako pšenici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Já jsem však poprosil za tebe, aby nezanikla tvá víra. A ty, až se jednou obrátíš, posilni své bratry.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'On mu řekl: „Pane, s tebou jsem hotov jít i do vězení a na smrt.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Ježíš řekl: „Pravím ti, Petře, že dnes nezakokrhá kohout, dokud třikrát nezapřeš, že mne znáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'A řekl jim: „Když jsem vás poslal bez měšce, mošny a sandálů, měli jste v něčem nedostatek?“Oni řekli: „V ničem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Řekl jim: „Ale nyní, kdo má měšec, vezmi jej, stejně tak i mošnu, a kdo nemá, prodej svůj plášť a kup meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Neboť vám říkám, že se na mně musí naplnit to, co je napsáno: A byl započten mezi bezzákonné. Neboť to, co se mne týká, spěje ke konci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Oni řekli: „Pane, hle, zde jsou dva meče.“On jim řekl: „ To stačí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'A když vyšel, vydal se podle svého zvyku na Olivovou horu; šli za ním i učedníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Když byl na místě, řekl jim: „Modlete se, abyste nevešli do pokušení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Sám se od nich vzdálil, co by kamenem dohodil, poklekl na kolena a modlil se:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, '„Otče, chceš–li, přenes tento kalich ode mne, avšak ne má vůle, nýbrž tvá se staň.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, '[Ukázal se mu anděl z nebe a posiloval ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Ocitnuv se ve vnitřním zápase, usilovněji se modlil; jeho pot začal být jako kapky krve, které kanuly na zem.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'A když vstal od modlitby, přišel k učedníkům a nalezl je, jak zármutkem spí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Řekl jim: „Proč spíte? Vstaňte a modlete se, abyste nevešli do pokušení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Když ještě mluvil, hle, přicházel zástup, a ten, který se jmenoval Juda, jeden ze Dvanácti, šel před nimi a přiblížil se k Ježíšovi, aby ho políbil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Ježíš mu řekl: „Judo, polibkem zrazuješ Syna člověka?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Když ti okolo něho uviděli, co ⌈se děje⌉, řekli: „Pane, máme udeřit mečem?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'A jeden z nich udeřil veleknězova otroka a uťal mu pravé ucho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Ježíš však odpověděl: „Nechte toho!“A dotkl se jeho ucha a uzdravil jej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Ježíš řekl těm, kteří na něho přišli, velekněžím, velitelům chrámové stráže a starším: „Jako na lupiče jste vyšli s meči a holemi?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Když jsem byl den co den s vámi v chrámě, nevztáhli jste na mne ruce. Ale toto je vaše hodina a vláda temnoty.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Zmocnili se ho a odvedli do veleknězova domu. Petr je zpovzdálí následoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Když uprostřed nádvoří zapálili oheň a posadili se spolu, seděl Petr mezi nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'A spatřila ho jedna služka, jak sedí obrácen ke světlu, pozorně na něho pohlédla a řekla: „Také tenhle byl s ním.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'On [ho] však zapřel: „Neznám ho, ženo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'A krátce nato ho uviděl jiný a řekl: „Ty jsi také z nich.“Ale Petr řekl: „Člověče, nejsem!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'A když uplynula asi jedna hodina, začal někdo jiný tvrdit: „Opravdu, i tenhle byl s ním, vždyť je také Galilejec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Petr řekl: „Člověče, nevím, co povídáš.“A hned, ještě když mluvil, zakokrhal kohout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Pán se obrátil a pohlédl na Petra. A Petr se rozpomenul na Pánův výrok, jak mu řekl: „Dřív než dnes kohout zakokrhá, třikrát mne zapřeš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'I vyšel ven a hořce se rozplakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Muži, kteří Ježíše hlídali, se mu posmívali a bili ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Zahalili ⌈mu tvář⌉ a ptali se ho: „Prorokuj, kdo tě udeřil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'A mnoho jiného mluvili proti němu, urážejíce ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'A když nastal den, shromáždilo se staršovstvo lidu, velekněží a učitelé Zákona, odvedli ho před svou veleradu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'a říkali: „Řekni nám, jsi–li ty Kristus.“Řekl jim: „Řeknu–li vám to, zajisté neuvěříte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'Zeptám–li se, zajisté [mi] neodpovíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Od této chvíle však bude Syn člověka sedět na pravici Moci Boží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Všichni řekli: „Ty tedy jsi Syn Boží?“On jim řekl: „Vy říkáte, že Já jsem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Oni řekli: „Nač ještě potřebujeme svědectví? Vždyť jsme to sami slyšeli z jeho úst.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Celé jejich shromáždění povstalo a odvedli jej k Pilátovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Začali ho obviňovat: „Tohoto člověka jsme nalezli, jak rozvrací náš národ, brání dávat daně císaři a říká, že sám je Mesiáš král.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilát se ho otázal: „Ty jsi král Židů?“On mu odpověděl: „Ty říkáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilát řekl velekněžím a zástupům: „Na tomto člověku nenalézám žádnou vinu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Ale oni naléhali a říkali: „ Svým učením bouří lid po celém Judsku, začal v Galileji a přišel až sem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Jakmile to Pilát uslyšel, otázal se, zda ten člověk je Galilejský.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'A když zjistil, že ⌈podléhá Herodově pravomoci⌉, poslal ho k Herodovi, protože i on byl v těch dnech v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Když Herodes Ježíše uviděl, velmi se zaradoval; neboť si ho už dlouho přál vidět, protože o něm [mnoho] slyšel, a doufal, že od něho uvidí nějaké znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Kladl mu mnoho otázek, ale on mu na nic neodpověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Stáli tam velekněží a učitelé Zákona a prudce ho obviňovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, '[I] Herodes jím se svými vojáky pohrdl, vysmál se mu, oblékl ho do nádherného roucha a poslal ho zpět k Pilátovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'V ten den se Herodes a Pilát spolu spřátelili; předtím totiž žili ve vzájemném nepřátelství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilát svolal velekněze, vůdce a lid');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'a řekl jim: „Přivedli jste mi tohoto člověka, že ⌈podněcuje lid ke vzpouře⌉, a hle, když jsem ho před vámi vyslechl, nenalezl jsem na tomto člověku nic, z čeho jej obviňujete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Ale ani Herodes ne, neboť ⌈ho poslal zpět k nám⌉. A hle, neučinil nic, za co by zasluhoval smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Jakmile ho tedy potrestám, propustím ho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '[O svátcích jim totiž musel propouštět jednoho vězně.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Ale všichni společně vykřikli: „Odstraň tohoto a propusť nám Barabáše!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Ten byl uvržen do vězení pro jakousi vzpouru, vzniklou ve městě, a pro vraždu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilát k nim znovu promluvil, neboť chtěl Ježíše propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Oni však volali: „Ukřižuj, ukřižuj ho!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Řekl jim potřetí: „Co tedy ten člověk udělal zlého? Žádný důvod pro trest smrti jsem u něj nenalezl. Potrestám ho tedy a propustím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Oni však naléhali velikým křikem a žádali, aby byl ukřižován; a křik jejich [a velekněží] sílil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'A tak se Pilát rozhodl ⌈jejich žádosti vyhovět⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Propustil toho, který byl pro vzpouru a vraždu uvržen do vězení a kterého žádali, Ježíše pak vydal jejich vůli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'A když ho odváděli, chytili nějakého Šimona z Kyrény, jdoucího z pole, a vložili na něho kříž, aby ho nesl za Ježíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Za ním šlo veliké množství lidu a žen, které se bily v prsa a oplakávaly ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Ježíš se k nim obrátil a řekl: „Dcery jeruzalémské, nade mnou neplačte, spíše plačte nad sebou a nad svými dětmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Neboť hle, přicházejí dny, v nichž budou říkat: Blahoslavené jsou neplodné, lůna, která nerodila, a prsy, které nekojily!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Tehdy začnou říkat horám: Padněte na nás, a pahrbkům: Přikryjte nás!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Protože dělají–li toto ⌈se zeleným stromem⌉, co se stane ⌈se suchým⌉?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Byli s ním vedeni k popravě i jiní: dva zločinci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'A když přišli na místo, které se nazývá Lebka, ukřižovali tam jeho i ty zločince -- jednoho po pravici a druhého po levici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, '[Ježíš říkal: „Otče, odpusť jim, neboť nevědí, co činí.“] Když si dělili jeho šaty, hodili los.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Lid stál a díval se. I vůdci se mu vysmívali a říkali: „Jiné zachránil, ať zachrání sebe, je–li ten Kristus Boží, ten Vyvolený.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Posmívali se mu i vojáci, kteří přistupovali a přinášeli mu ocet');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'a říkali: „Jsi–li ty ten král Židů, zachraň sám sebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Byl nad ním i nápis [napsaný řeckými, latinskými a hebrejskými písmeny]: „Toto je král Židů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Jeden z pověšených zločinců ho urážel slovy: „Což ty nejsi Kristus? Zachraň sám sebe i nás!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, '⌈Ale druhý ho napomínal⌉: „ To se ani Boha nebojíš? Vždyť jsi stejně odsouzený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'A my spravedlivě, neboť dostáváme, co si zasluhujeme za své skutky, ale tento nic zlého neudělal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, '⌈A říkal: „Ježíši, vzpomeň si na mne, až přijdeš do svého království.“⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, '[Ježíš] mu řekl: „Amen, pravím ti, dnes budeš se mnou v ráji.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Bylo již okolo šesté hodiny; tu nastala tma po celé zemi až do ⌈deváté hodiny⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, '⌈protože se zatmělo⌉ slunce. Opona svatyně se uprostřed roztrhla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'A Ježíš zvolal mocným hlasem: „Otče, do tvých rukou odevzdávám svého ducha.“Když to řekl, vydechl naposled.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Když setník uviděl, co se stalo, slavil Boha řka: „Skutečně, tento člověk byl spravedlivý.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'A všechny ty zástupy, které se sešly na tuto podívanou, když uviděly, co se stalo, odcházely bijíce se do prsou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Opodál stáli všichni jeho známí, i ženy, které ho doprovázely z Galileje, a viděli to.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'A hle, muž jménem Josef, člen rady [a] muž dobrý a spravedlivý--');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'ten nesouhlasil s jejich rozhodnutím a činem -- z židovského města Arimatie, který [také sám] očekával Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Ten přišel k Pilátovi a vyžádal si Ježíšovo tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Sňal je, zavinul do plátna a položil ho do hrobky vytesané ve skále, kde ještě nikdo nebyl pochován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Byl den přípravy a ⌈nastávala sobota.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Ženy, které s ním přišly z Galileje, ho doprovodily; viděly hrob i to, jak bylo jeho tělo uloženo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Pak se vrátily a připravily vonné látky a oleje. V sobotu podle přikázání zachovaly klid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Prvního dne týdne velmi časně ráno přišly k hrobce nesouce vonné látky, které připravily.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Nalezly však kámen od hrobu odvalený.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'Vstoupily, ale tělo [Pána Ježíše] nenalezly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'A stalo se, když nad tím byly bezradné, hle, přistoupili k nim dva muži v zářícím rouchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Polekaly se a sklonily tváře k zemi; oni však jim řekli: „Proč hledáte živého mezi mrtvými?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Není zde, ale byl vzkříšen. Vzpomeňte si, jak k vám mluvil, když byl ještě v Galileji,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'když řekl o Synu člověka, že musí být vydán do rukou hříšných lidí, být ukřižován a třetího dne vstát.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'I vzpomněly si na jeho slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'A když se vrátily [od hrobky], oznámily toto všechno Jedenácti i všem ostatním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, '[Byly to] Marie Magdalská, Jana a Marie Jakubova a ostatní s nimi. Říkaly to apoštolům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'ale jim tato slova připadala jako nesmysl a nevěřili jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, '[Petr však vstal, běžel ke hrobce, naklonil se dovnitř a spatřil jen plátna. I odešel domů v údivu nad tím, co se stalo.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'A hle, téhož dne šli dva z nich do vesnice jménem Emaus, vzdálené [sto] šedesát stadií od Jeruzaléma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'a rozmlouvali spolu o tom všem, co se přihodilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'A stalo se, jak tak spolu rozmlouvali a probírali to, že se k nim přiblížil sám Ježíš a šel s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Ale jejich oči byly drženy, takže ho nepoznali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Řekl jim: „O jakých věcech to spolu cestou rozmlouváte?“I zůstali stát zasmušilí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Jeden z nich, jménem Kleofáš, mu odpověděl: „Ty jsi snad jediný, kdo pobývá v Jeruzalémě a nedověděl se, co se v něm v těchto dnech stalo!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'I řekl jim: „Co to je?“Oni mu řekli: „To s Ježíšem Nazaretským, který byl muž prorok mocný v činu i slově před Bohem i přede vším lidem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'jak ho velekněží a naši vládci vydali k odsouzení na smrt a ukřižovali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'My jsme však doufali, že on je ten, který má vykoupit Izrael. Ale ⌈přes to všechno⌉ je to už třetí den od toho, kdy se to stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Některé z našich žen nás však ohromily. Byly zrána u hrobky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'a když nenalezly jeho tělo, přišly a říkaly, že měly dokonce vidění andělů, kteří řekli, že je živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'A někteří z těch, kteří byli s námi, odešli k hrobce a nalezli vše tak, jak řekly i ženy, jeho však nespatřili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'A on jim řekl: „Ó nerozumní a zpozdilého srdce, abyste věřili tomu všemu, co mluvili proroci!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Což to neměl Kristus vytrpět a vejít do své slávy?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'A začal od Mojžíše a od všech proroků a vysvětlil jim ve všech Písmech to, co o něm bylo napsáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Přiblížili se k vesnici, kam šli, a on si počínal, jako by chtěl jít dál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Oni však na něho naléhali slovy: „Zůstaň s námi, neboť ⌈se připozdívá⌉ a den se již nachýlil.“I vstoupil, aby s nimi zůstal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'A stalo se, když s nimi zaujal místo u stolu, že vzal chléb, požehnal, rozlomil a podával jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Vtom se jim otevřely oči a poznali ho; ale on se pro ně stal neviditelným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'A řekli si spolu: „Což v nás srdce nehořelo, když k nám na cestě mluvil a otvíral nám Písma?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'A v tu hodinu vstali, vrátili se do Jeruzaléma a nalezli shromážděných těch jedenáct i ty, kteří byli s nimi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'a ti jim říkali, že Pán byl skutečně probuzen z mrtvých a ukázal se Šimonovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'A oni vypravovali, co se jim stalo na cestě a jak se jim dal poznat při lámání chleba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Zatímco o tom mluvili, postavil se on uprostřed nich [a řekl jim: „Pokoj vám.“]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Vyděsili se a vystrašeni se domnívali, že vidí ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Řekl jim: „Proč jste tak rozrušeni a proč ve vašem srdci vystupují pochybnosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Podívejte se na mé ruce a na mé nohy, že jsem to já. Dotkněte se mne a podívejte se: duch nemá maso a kosti, jako to vidíte na mně.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, '[A když to řekl, ukázal jim ruce a nohy.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Když tomu ještě pro samou radost nemohli uvěřit a jen se divili, řekl jim: „Máte tu něco k jídlu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Podali mu kus pečené ryby [a plást medu].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Vzal si a pojedl před nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Řekl jim: „To jsou ta má slova, která jsem k vám mluvil, když jsem byl ještě s vámi, že se musí naplnit všechno, co je o mně napsáno v Mojžíšově zákoně, v prorocích a Žalmech.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Potom otevřel jejich mysl, aby rozuměli Písmu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'a řekl jim: „Tak je napsáno, že Kristus měl trpět a třetího dne vstát z mrtvých;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'a na základě jeho jména má být všem národům vyhlášeno pokání k odpuštění hříchů⌈, počínajíc od Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Vy [jste] svědky těchto věcí ⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'A [hle,] já na vás posílám zaslíbení mého Otce; vy však zůstaňte ve městě, dokud nebudete oblečeni mocí z výsosti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Potom je vyvedl až k Betanii, zvedl své ruce a požehnal jim.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'A stalo se, když jim žehnal, že se od nich vzdálil [a byl nesen vzhůru do nebe].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'A [když se mu poklonili,] s velikou radostí se vrátili do Jeruzaléma');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'a byli stále v chrámě, ⌈chválili Boha a dobrořečili mu ⌉. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Na počátku bylo Slovo a to Slovo bylo u Boha a to Slovo bylo Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'To bylo na počátku u Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Všechno vzniklo skrze ně a bez něho nevzniklo ⌈vůbec nic⌉ ⌈, co je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'V něm byl život⌉ a ten život byl světlo lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'A to světlo ve tmě svítí a tma je nepohltila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Objevil se člověk poslaný od Boha, jehož jméno bylo Jan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Ten přišel ⌈jako svědek⌉, aby o tom světle vydal svědectví, aby skrze něho všichni uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'On sám nebyl to světlo, ale přišel, aby o tom světle vydal svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Bylo tu pravé světlo, které osvěcuje každého člověka, ⌈ to přicházelo⌉ na svět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Na světě byl, svět skrze něj vznikl, a svět ho nepoznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Přišel do svého vlastního, a jeho vlastní ho nepřijali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Těm však, kteří ho přijali, dal pravomoc stát se Božími dětmi, těm, kteří věří v jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Ti se nenarodili z krve ani z vůle těla ani z vůle muže, nýbrž z Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'A Slovo se stalo tělem a přebývalo mezi námi. Spatřili jsme jeho slávu, slávu⌈, jakou má od Otce jediný Syn, plný⌉ milosti a pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jan o něm vydával svědectví. Volal: „To je ten, o němž jsem řekl: Ten, který přichází za mnou, je přede mnou, neboť byl dříve než já. “--');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Z jeho plnosti jsme my všichni vzali, milost za milostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Neboť Zákon byl dán skrze Mojžíše, milost a pravda se stala skrze Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Boha nikdo nikdy neviděl; jedinečný Bůh, který je v lůnu Otcově, ten nám o něm pověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Toto je svědectví Janovo, když k němu Židé z Jeruzaléma poslali kněze a Levity, aby se ho zeptali: „Kdo jsi ty?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'I vyznal a nezapřel; vyznal: „Já nejsem Mesiáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Zeptali se ho: „Co tedy? Jsi Eliáš?“Řekl: „Nejsem.“„Jsi ten Prorok?“Odpověděl: „Ne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Řekli mu tedy: „Kdo jsi? Ať můžeme dát odpověď těm, kteří nás poslali. Co říkáš sám o sobě?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Řekl: „Já jsem hlas volajícího v pustině: Vyrovnejte Pánovu cestu, jak řekl prorok Izaiáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, '[Ti] poslaní byli z farizeů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'I zeptali se ho: „Proč tedy křtíš, když nejsi Mesiáš ani Eliáš ani ten Prorok?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Jan jim odpověděl: „Já křtím ve vodě, [ale] uprostřed vás stojí ten, koho vy neznáte:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, '[To je] ten, který přichází za mnou, který byl přede mnou; jemu nejsem hoden rozvázat řemínek jeho sandálu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Tyto věci se udály v Betanii za Jordánem, kde Jan křtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Druhého dne Jan uviděl Ježíše, jak k němu přichází, a řekl: „Hle, Beránek Boží, který snímá hřích světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Toto je ten, o němž jsem řekl: Za mnou přichází muž, který je přede mnou, neboť byl dříve než já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Ani já jsem ho neznal, ale proto jsem přišel a křtil ve vodě, aby byl zjeven Izraeli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'A Jan vydal svědectví: „Viděl jsem, jak Duch sestupoval jako holubice z nebe a zůstal na něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Ani já jsem ho neznal, ale ten, kdo mne poslal křtít ve vodě, mi řekl: Na koho uvidíš sestupovat Ducha a zůstávat na něm, to je ten, který křtí v Duchu Svatém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'A já jsem to viděl a dosvědčuji, že toto je Boží Syn.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Druhého dne tam Jan opět stál se dvěma ze svých učedníků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Pohlédl na Ježíše, jak jde kolem, a řekl: „Hle, Beránek Boží!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Ti dva učedníci slyšeli, co říká, a šli za Ježíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Ježíš se otočil, a když uviděl, že jdou za ním, řekl jim: „Co hledáte?“A oni mu řekli: „Rabbi“, což se překládá Učiteli, „kde bydlíš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Řekl jim: „Pojďte a uvidíte.“Šli tedy, viděli, kde bydlí, a zůstali ten den u něho. Bylo kolem ⌈čtvrté hodiny odpoledne⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Jeden z těch dvou, kteří to uslyšeli od Jana a připojili se k němu, byl Ondřej, bratr Šimona Petra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Ten nalezl nejprve svého bratra Šimona a řekl mu: „Nalezli jsme Mesiáše“(což je v překladu: Kristus).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Přivedl ho k Ježíšovi. Ježíš na něho pohlédl a řekl: „Ty jsi Šimon, syn Jonášův; budeš se jmenovat Kéfas“(což se překládá Petr).');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Druhého dne se Ježíš rozhodl odejít do Galileje. Nalezl Filipa a řekl mu: „Následuj mne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Filip byl z Betsaidy, města Ondřejova a Petrova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filip nalezl Natanaela a řekl mu: „Nalezli jsme toho, o němž psal Mojžíš v Zákoně a proroci, Ježíše, syna Josefova z Nazareta.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Natanael mu řekl: „Může být z Nazareta něco dobrého?“Filip mu řekl: „Pojď a podívej se.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Ježíš uviděl Natanaela, jak k němu přichází, a řekl o něm: „Hle, to je opravdu Izraelita, ve kterém není lsti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natanael mu řekl: „Odkud mne znáš?“Ježíš mu odpověděl: „Viděl jsem tě dříve, než tě Filip zavolal, když jsi byl pod tím fíkovníkem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natanael mu odpověděl: „Rabbi, ty jsi Syn Boží, ty jsi král Izraele.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Ježíš mu odpověděl: „Věříš proto, že jsem ti řekl: Viděl jsem tě pod fíkovníkem? Uvidíš větší věci než toto.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'A řekl mu: „⌈Amen, amen, pravím⌉ vám, [od nynějška] uvidíte nebe otevřené a Boží anděly vystupovat a sestupovatna Syna člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Třetího dne byla svatba v Káně Galilejské a byla tam Ježíšova matka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Na svatbu byl pozván také Ježíš a jeho učedníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Když došlo víno, řekla ⌈Ježíšovi jeho⌉ matka: „Nemají víno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, '[A] Ježíš jí řekl: „⌈Co mi chceš⌉, ženo? Ještě nepřišla má hodina.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Jeho matka řekla služebníkům: „Cokoli vám řekne, učiňte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Bylo tam šest kamenných nádob na vodu, určených k židovskému očišťování, každá na dvě nebo tři míry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Ježíš jim řekl: „Naplňte ty nádoby vodou.“A naplnili je až po okraj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Pak jim řekl: „Teď naberte a neste správci hostiny.“I donesli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Jakmile správce hostiny ochutnal vodu učiněnou vínem -- nevěděl, odkud je, ale služebníci, kteří tu vodu nabrali, to věděli -- zavolal ženicha');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'a řekl mu: „Každý člověk podává nejprve dobré víno, a když se hosté dostatečně napijí, [tehdy] to, které je horší. Ty jsi zachoval dobré víno až do této chvíle.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Toto Ježíš učinil v Káně Galilejské jako počátek svých znamení a zjevil svou slávu. A jeho učedníci v něho uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Potom sestoupil on, jeho matka, jeho bratři i jeho učedníci do Kafarnaum a zůstali tam několik dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Byly blízko židovské velikonoce a Ježíš vystoupil do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'V chrámě našel prodavače dobytka, ovcí a holubů i penězoměnce sedící za stoly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'I udělal z provazů bič a všechny je z chrámu i s ovcemi a dobytkem vyhnal, mince penězoměnců vysypal a stoly převrátil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'A prodavačům holubů řekl: „Odneste to odsud! Nedělejte z domu mého Otce tržnici!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Jeho učedníci si vzpomněli, že je napsáno: Horlivost pro tvůj dům mne stráví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Židé mu na to řekli: „Jaké znamení nám ukážeš, že toto činíš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Ježíš jim odpověděl: „Zbořte tuto svatyni, a ve třech dnech ji postavím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Židé tedy řekli: „Tato svatyně byla budována čtyřicet šest let, a ty ji postavíš ve třech dnech?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'On však mluvil o svatyni svého těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Když byl potom vzkříšen z mrtvých, vzpomněli si jeho učedníci, že toto říkal, a uvěřili Písmu i slovu, které Ježíš řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Když byl o velikonocích v Jeruzalémě na slavnosti, mnozí uvěřili v jeho jméno, ⌈protože viděli znamení⌉, která činil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Ježíš se jim však sám nesvěřoval, protože znal všechny');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'a nepotřeboval, aby mu někdo vydal svědectví o člověku. Sám totiž věděl, co je v člověku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Mezi farizeji byl člověk jménem Nikodém, přední muž mezi Židy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Ten přišel ⌈k Ježíšovi⌉ v noci a řekl mu: „Rabbi, víme, že jsi přišel od Boha jako učitel, neboť nikdo nemůže činit ta znamení, která činíš ty, není–li s ním Bůh.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Ježíš mu odpověděl: „Amen, amen, pravím tobě, nenarodí–li se kdo znovu, nemůže spatřit Boží království.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodém mu řekl: „Jak se může člověk narodit, když je starý? Nemůže podruhé vstoupit do lůna své matky a narodit se.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Ježíš odpověděl: „Amen, amen, pravím tobě, nenarodí–li se kdo z vody a Ducha, nemůže vstoupit do Božího království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Co se narodilo z těla, je tělo, a co se narodilo z Ducha, je duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Nediv se, že jsem ti řekl: Musíte se narodit znovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Vítr vane, kam chce, a slyšíš jeho zvuk, ale nevíš, odkud přichází a kam jde. Tak je to s každým, kdo se narodil z Ducha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodém mu odpověděl: „Jak se to může stát?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Ježíš mu odpověděl: „Ty jsi učitel Izraele, a toto nevíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Amen, amen, pravím tobě, že mluvíme, co víme, a svědčíme o tom, co jsme viděli, a vy naše svědectví nepřijímáte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Když jsem vám pověděl věci pozemské, a nevěříte, jak uvěříte, povím–li vám věci nebeské?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Nikdo nevystoupil do nebe kromě toho, který sestoupil z nebe, Syna člověka, [který je v nebi].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'A jako Mojžíš vyvýšil hada v pustině, tak musí být vyvýšen Syn člověka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'aby každý, ⌈kdo v něho věří, měl život⌉ věčný.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, '„Neboť tak Bůh miluje svět, že dal [svého] jediného Syna, aby žádný, kdo v něho věří, nezahynul, ale měl život věčný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Vždyť Bůh neposlal [svého] Syna na svět, aby svět odsoudil, ale aby byl svět skrze něj zachráněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kdo v něho věří, není souzen, kdo však nevěří, již je odsouzen, protože neuvěřil ve jméno jediného Syna Božího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Toto je ten soud, že světlo přišlo na svět, ale lidé si zamilovali více tmu než světlo, protože jejich skutky byly zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Neboť každý, kdo jedná zle, nenávidí světlo a nepřichází ke světlu, aby jeho skutky nebyly odhaleny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Kdo však činí pravdu, přichází ke světlu, aby se ukázalo, že jeho skutky jsou vykonány v Bohu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Potom přišel Ježíš i jeho učedníci do judské země; tam s nimi pobýval a křtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Také Jan křtil v Ainon, blízko Salim, protože tam bylo hodně vody; a lidé přicházeli a byli křtěni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Jan totiž ještě nebyl uvržen do vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Mezi některými z Janových učedníků a jedním Židem nastal spor o očišťování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Přišli k Janovi a řekli mu: „Rabbi, ten, který byl s tebou za Jordánem a o němž jsi vydal svědectví, hle, ten křtí a všichni přicházejí k němu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Jan odpověděl: „Člověk si nemůže vzít nic, není–li mu to dáno z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vy sami jste [mi] svědky, že jsem řekl: Já nejsem Mesiáš, ale Jsem poslán před ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Ženich je ten, kdo má nevěstu. Přítel ženicha, který stojí a slyší ho, velmi se raduje z ženichova hlasu. Tato má radost je tedy naplněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'On musí růst, já však se menšit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, '„Kdo přichází shůry, je nade všechny. Kdo je ze země, je pozemský a mluví pozemsky. Kdo přichází z nebe, [je nade všechny a]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'svědčí o tom, co viděl a slyšel, ale jeho svědectví nikdo nepřijímá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kdo přijal jeho svědectví, zpečetil, že Bůh je pravdivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Ten, koho poslal Bůh, mluví slova Boží, neboť [Bůh] dává Ducha bez odměřování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Otec miluje Syna a všechno dal do jeho rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kdo věří v Syna, má věčný život; kdo však Syna odmítá, nespatří život, ale zůstává na něm Boží hněv.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Když se Pán dověděl, že farizeové uslyšeli, že on získává a křtí více učedníků než Jan');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '-- ačkoli Ježíš sám nekřtil, nýbrž jeho učedníci --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'opustil Judsko a odešel [opět] do Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Musel však projít Samařskem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Přišel tedy do samařského města zvaného Sychar, blízko pozemku, který dal Jákob svému synu Josefovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Tam byl Jákobův pramen. Ježíš, unaven cestou, ⌈se posadil⌉ u toho pramene. Bylo kolem poledne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Tu přišla samařská žena, aby načerpala vodu. Ježíš jí řekl: „Dej mi napít.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Jeho učedníci totiž odešli do města, aby nakoupili jídlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Samařská žena mu řekla: „Jak to, že ty, ač jsi Žid, žádáš mne, samařskou ženu, abych ti dala napít?“Židé totiž se Samařany ⌈ nic společného neužívají⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Ježíš jí odpověděl: „Kdybys znala ten Boží dar a věděla, kdo je ten, který ti říká: Dej mi napít, požádala bys ty jeho a on by ti dal živou vodu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, '[Žena] mu řekla: „Pane, nemáš ani vědro a studna je hluboká; odkud tedy máš tu živou vodu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Jsi snad větší než náš otec Jákob, který nám tuto studnu dal a pil z ní on sám i jeho synové a jeho dobytek?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Ježíš jí odpověděl: „Každý, kdo pije z této vody, bude opět žíznit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Kdo by se však napil z vody, kterou mu dám já, nebude nikdy žíznit, ale voda, kterou mu dám, se v něm stane pramenem vody tryskající k věčnému životu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Ta žena mu řekla: „Pane, dej mi tuto vodu, abych už nežíznila a ne musela sem chodit nabírat.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, '[Ježíš] jí řekl: „Jdi, zavolej svého muže a přijď sem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Žena mu odpověděla: „Nemám muže.“Ježíš jí řekl: „Dobře jsi řekla: Nemám muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Vždyť jsi měla pět mužů, a ten, kterého máš nyní, není tvůj muž. To jsi řekla pravdu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Žena mu řekla: „Pane, vidím, že jsi prorok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Naši otcové se klaněli Bohu na této hoře, a vy říkáte, že místo, kde je třeba se klanět, je v Jeruzalémě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Ježíš jí řekl: „Věř mi, ženo, že přichází hodina, kdy se nebudete klanět Otci ani na této hoře ani v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vy se klaníte tomu, co neznáte. My se klaníme tomu, co známe, protože záchrana je ze Židů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Ale přichází hodina, a již je zde, kdy praví ctitelé se budou klanět Otci v duchu a pravdě; vždyť sám Otec hledá takové ctitele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Bůh je duch, a ti, kteří se mu klanějí, musí se mu klanět v duchu a pravdě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Žena mu řekla: „Vím, že má přijít Mesiáš, zvaný Kristus. Až on přijde, oznámí nám všechno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Ježíš jí řekl: „Já jsem to -- ten, který k tobě mluví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Vtom přišli jeho učedníci a divili se, že rozmlouvá se ženou. Nikdo však neřekl: Nač se ptáš? nebo Proč s ní mluvíš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Žena tam tedy nechala svůj džbán, odešla do města a řekla lidem:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '„Pojďte ⌈se podívat⌉ na člověka, který mi řekl všechno, co jsem udělala. Není snad on ten Kristus?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Vyšli z města a šli k němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Mezitím ho učedníci prosili: „Rabbi, najez se.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'On jim však řekl: „Já mám jíst pokrm, který vy neznáte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Učedníci se mezi sebou ptali: „Nepřinesl mu někdo něco k jídlu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Ježíš jim řekl: „Můj pokrm je, abych činil vůli toho, který mne poslal, a dokonal jeho dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Což neříkáte: Ještě čtyři měsíce a přijde žeň? Hle, pravím vám: Pozvedněte své oči a pohleďte na pole, že se bělají ke žni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Žnec již bere odměnu a shromažďuje úrodu k věčnému životu, aby se společně radovali rozsévač i žnec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Neboť v tom je pravdivé přísloví, že jiný rozsévá a jiný žne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Já jsem vás poslal žnout to, na čem jste nepracovali. Druzí pracovali a vy jste vstoupili do jejich těžké práce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Mnoho Samařanů z onoho města v něho uvěřilo pro slovo té ženy, která svědčila: „Řekl mi vše, co jsem udělala.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Když tedy k němu ti Samařané přišli, prosili ho, aby u nich zůstal. I zůstal tam dva dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'A mnohem více jich uvěřilo pro jeho slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Té ženě pak říkali: „Teď už věříme ne pro to, co jsi říkala ty, ale sami jsme ho slyšeli a víme, že toto je skutečně Zachránce světa, [Kristus].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Po dvou dnech odtamtud odešel do Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Neboť Ježíš sám vydal svědectví, že prorok ve své vlasti nemá vážnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Když tedy přišel do Galileje, Galilejci ho přijali, protože viděli všechno, co učinil o svátku v Jeruzalémě; neboť i oni přišli na svátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, '[Ježíš] opět přišel do Kány Galilejské, kde z vody učinil víno. Byl tam jeden královský úředník, jehož syn ležel nemocen v Kafarnaum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Když uslyšel, že Ježíš přišel z Judska do Galileje, odešel k němu a prosil [ho], aby přišel a uzdravil jeho syna, neboť již skoro umíral.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Tu mu Ježíš řekl: „Neuvidíte–li znamení a divy, jistě neuvěříte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Královský úředník mu řekl: „Pane, pojď, než mé dítě zemře!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Ježíš mu říká: „Jdi, tvůj syn žije.“Ten člověk uvěřil slovu, které mu Ježíš řekl, a šel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Ještě byl na cestě dolů, když mu vyšli naproti jeho otroci a řekli, že jeho chlapec žije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Vyptal se jich tedy na hodinu, ve které mu začalo být lépe. Řekli mu: „Včera v jednu hodinu ho opustila horečka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Tu otec poznal, že se to stalo v tu hodinu, kdy mu Ježíš řekl: Tvůj syn žije. A uvěřil on i celý jeho dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Toto bylo už druhé znamení, které Ježíš učinil, když přišel z Judska do Galileje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Potom byl židovský svátek a Ježíš vystoupil do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'V Jeruzalémě je u Ovčí brány rybník, hebrejsky zvaný Bethesda, který má pět sloupořadí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'V nich lehávalo množství nemocných, slepých, chromých a ochrnutých, [kteří čekali na pohyb vody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Neboť Pánův anděl občas sestupoval do rybníka a vířil vodu. Kdo po zvíření vody první vstoupil do rybníka, býval uzdraven, ať trpěl kteroukoli nemocí].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Byl tam jeden člověk, nemocný již třicet osm let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Když ho Ježíš spatřil, jak tam leží, a poznal, že je už dlouhou dobu nemocen, řekl mu: „Chceš ⌈být uzdraven⌉?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Nemocný mu odpověděl: „Pane, nemám nikoho, kdo by mě snesl do rybníka, když se voda rozvíří. Zatímco já teprve přicházím, jiný tam sestupuje přede mnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Ježíš mu řekl: „Vstaň, vezmi své lehátko a choď.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'A hned byl ten člověk uzdraven, vzal své lehátko a chodil. Ten den však byla sobota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Židé tomu uzdravenému říkali: „Je sobota; není dovoleno, abys nosil [své] lehátko.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'On jim však odpověděl: „Ten, který mě uzdravil, mi řekl: Vezmi své lehátko a choď. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Otázali se ho: „Kdo je ten člověk, který ti řekl: Vezmi [své lehátko] a choď?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Uzdravený však nevěděl, kdo to je, neboť Ježíš se ztratil v zástupu, který na tom místě byl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Potom ho Ježíš nalezl v chrámě a řekl mu: „Hle, jsi uzdraven. Už nehřeš, aby se ti nepřihodilo něco horšího.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Ten člověk odešel a oznámil Židům, že tím, kdo ho uzdravil, je Ježíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Proto Židé Ježíše pronásledovali [a usilovali ho zabít], že tyto věci činil v sobotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Ježíš jim však odpověděl: „Můj Otec až dosud pracuje, i já pracuji.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Proto ho Židé ještě více usilovali zabít, že nejen rušil sobotu, ale také Boha nazýval svým vlastním otcem, a činil se tak rovným Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Ježíš jim odpověděl: „Amen, amen, pravím vám: Syn nemůže sám od sebe činit nic než to, co vidí činit Otce. Co činí on, to činí stejně i Syn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Neboť Otec miluje Syna a ukazuje mu všechno, co sám činí. A ještě větší skutky než tyto mu ukáže, abyste vy žasli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Jako totiž Otec křísí mrtvé a obživuje, tak také Syn obživuje ty, které chce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Vždyť Otec ani nikoho nesoudí, ale všechen soud svěřil Synu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'aby všichni ctili Syna, jako ctí Otce. Kdo nectí Syna, nectí Otce, který ho poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Amen, amen, pravím vám, že kdo slyší mé slovo a věří tomu, kdo mne poslal, má věčný život a nejde na soud, ale přešel ze smrti do života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Amen, amen, pravím vám, že přichází hodina, a nyní je tu, kdy mrtví uslyší hlas Božího Syna, a ti, kdo uslyší, budou žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Neboť jako Otec má život sám v sobě, tak dal i Synu, aby měl život sám v sobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'A dal mu pravomoc konat soud, protože je Syn člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Nedivte se tomu; vždyť přichází hodina, v níž všichni, kteří jsou v hrobech, uslyší jeho hlas');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'a vyjdou. Ti, kdo činili dobře, ⌈budou vzkříšeni k životu⌉, a ti, kdo jednali zle, ⌈budou vzkříšeni k soudu⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, '„Já sám od sebe nemohu dělat nic. Jak slyším, tak soudím, a můj soud je spravedlivý, protože nehledám svou vůli, ale vůli toho, kdo mne poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, '„Svědčím–li já sám o sobě, není mé svědectví pravé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Je jiný, kdo o mně svědčí, a vím, že svědectví, které o mně vydává, je pravdivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vy jste poslali k Janovi a on vydal svědectví Pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Já sice nepřijímám svědectví od člověka, ale toto říkám, abyste byli zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'On byl lampou hořící a zářící, a vám se zachtělo zaradovat se na chvíli v jeho světle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Já však mám větší svědectví než Janovo: skutky, které mi dal Otec, abych je vykonal. Právě ty skutky, které činím, o mně svědčí, že mne poslal Otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'A sám Otec, který mne poslal, vydal o mně svědectví. Vy jste nikdy neslyšeli jeho hlas ani jste neviděli jeho podobu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'a jeho slovo ve vás nezůstává, protože nevěříte tomu, koho on poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Zkoumáte Písma, protože se domníváte, že v nich máte věčný život, a právě ona svědčí o mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Ale nechcete přijít ke mně, abyste měli život.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, '„Slávu od lidí nepřijímám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Ale vím o vás, že v sobě nemáte lásku ⌈k Bohu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Já jsem přišel ve jménu svého Otce, a nepřijímáte mě. Kdyby přišel někdo jiný ve svém vlastním jménu, toho přijmete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Jak vy můžete uvěřit, když přijímáte slávu jedni od druhých, ale slávu, která je od jediného Boha, nehledáte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Nemyslete si, že já vás budu obviňovat u Otce; vaším žalobcem je Mojžíš, v něhož doufáte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Kdybyste totiž věřili Mojžíšovi, věřili byste mně, protože on psal o mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Nevěříte–li jeho zápisům, jak uvěříte mým výrokům?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Potom Ježíš odešel na druhý břeh Galilejského neboli Tiberiadského moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Šel za ním velký zástup, protože viděli znamení, která činil na nemocných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Ježíš vystoupil na horu a tam se posadil se svými učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Byly blízko velikonoce, židovský svátek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Když Ježíš pozdvihl oči a uviděl, že k němu přichází velký zástup, řekl Filipovi: „Kde nakoupíme chleba, aby se tito lidé najedli?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'To říkal, aby ho zkoušel; sám totiž věděl, co chce dělat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Filip mu odpověděl: „ Ani chleby za dvě stě denárů nestačí, aby si každý trochu vzal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Jeden z jeho učedníků, Ondřej, bratr Šimona Petra, mu řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '„Tady je chlapec, který má pět ječných chlebů a dvě ryby; ale co je to pro takové množství!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Ježíš řekl: „⌈Postarejte se⌉, ať se lidé posadí.“Na tom místě bylo mnoho trávy. I posadili se muži v počtu asi pěti tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Ježíš vzal ty chleby, vzdal díky a rozdělil je sedícím; stejně i z ryb dostali, kolik chtěli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Když se nasytili, řekl svým učedníkům: „Seberte zbylé úlomky, aby nic nepřišlo nazmar.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Sebrali je tedy a úlomky z těch pěti ječných chlebů, které přebyly těm, kteří se najedli, naplnili dvanáct nůší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Když ti lidé viděli znamení, které [Ježíš] učinil, říkali: „To je skutečně ten Prorok, ⌈který má přijít⌉ na svět.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Když Ježíš poznal, že se chystají přijít a zmocnit se ho, aby ho učinili králem, odešel opět na horu, zcela sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Když nastal večer, sestoupili jeho učedníci k moři,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'nastoupili do lodi a plavili se na druhou stranu moře do Kafarnaum. Již se setmělo, a Ježíš k nim ještě nepřišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Moře se začalo vzdouvat, protože vál silný vítr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Když ujeli asi dvacet pět nebo třicet stadií, uviděli Ježíše kráčet po mořia blížit se k lodi, a ulekli se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'On však jim řekl: „Já jsem to, nebojte se.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Chtěli jej vzít do lodi, a hned se loď ocitla u břehu, ke kterému jeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Zástup, který zůstal na druhé straně moře, si druhého dne všiml, že tam nebyl jiný člun než ten jeden, [do kterého nastoupili jeho učedníci,] a že Ježíš nevstoupil se svými učedníky do lodi, ale že jeho učedníci odjeli sami.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Jiné čluny z Tiberiady [však] připluly blízko k místu, kde pojedli chléb, když Pán vzdal díky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Když tedy zástup uviděl, že tam není Ježíš ani jeho učedníci, nastoupili do člunů a přijeli do Kafarnaum, hledajíce Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Když ho na druhé straně moře nalezli, řekli mu: „Rabbi, kdy ses sem dostal?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Ježíš jim odpověděl: „Amen, amen, pravím vám, hledáte mne ne proto, že jste viděli znamení, ale že jste jedli z těch chlebů a nasytili jste se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Pracujte ne pro pokrm, který hyne, nýbrž pro pokrm zůstávající k životu věčnému, který vám dá Syn člověka; neboť jemu Otec, Bůh, vtiskl svou pečeť.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Řekli mu: „Co máme dělat, abychom konali Boží skutky?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Ježíš jim odpověděl: „Toto je ten Boží skutek: abyste věřili v toho, kterého on poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Řekli mu: „Jaké ty tedy činíš znamení, abychom je uviděli a uvěřili ti? Co konáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Naši otcové jedli v pustině manu, jak je napsáno: Dal jim jíst chléb z nebe. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Ježíš jim řekl: „Amen, amen, pravím vám, ne Mojžíš vám dal chléb z nebe, nýbrž můj Otec vám dává ten pravý chléb z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Neboť chléb Boží je ten, který sestupuje z nebe a dává život světu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Řekli mu tedy: „Pane, dávej nám tento chléb stále.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Ježíš jim řekl: „Já jsem ten chléb života. Kdo přichází ke mně, jistě nebude hladovět, a ⌈kdo věří ve mne⌉, nebude nikdy žíznit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Ale řekl jsem vám, že jste mne i viděli, a přece nevěříte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Každý, koho mi Otec dává, přijde ke mně, a toho, kdo ke mně přichází, jistě nevyženu ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Neboť jsem sestoupil z nebe, ne abych činil svou vůli, ale vůli toho, který mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'A toto je vůle toho, který mne poslal, abych neztratil nic z toho, co mi dal, ale vzkřísil to v poslední den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Neboť toto je vůle mého Otce, aby každý, kdo vidí Syna a věří v něho, měl život věčný; a já ho vzkřísím v poslední den.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Židé proti němu reptali, že řekl: Já jsem chléb, který sestoupil z nebe');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'a říkali: „Copak to není Ježíš, syn Josefův? My známe jeho otce i matku. Jak tedy může říkat: Sestoupil jsem z nebe?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Ježíš jim odpověděl: „Nereptejte mezi sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nikdo nemůže přijít ke mně, jestliže ho nepřitáhne Otec, který mne poslal; a já ho vzkřísím v poslední den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'V Prorocích je napsáno: A budou všichni vyučeni od Boha. Každý, kdo od Otce uslyšel a vyučil se, přichází ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ne že by někdo Otce viděl, kromě ⌈toho, kdo je⌉ od Boha; ten viděl Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Amen, amen, pravím vám, kdo věří [ve mne], má život věčný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Já jsem chléb života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vaši otcové jedli v pustině manu, a zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Toto je chléb, který sestupuje z nebe, aby ten, kdo z něho jí, nezemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Já jsem ten živý chléb, který sestoupil z nebe. Kdo jí z tohoto chleba, bude žít ⌈na věčnost⌉. A chléb, který já dám za život světa, je mé tělo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Židé se hádali mezi sebou a říkali: „Jak nám tento člověk může dát k jídlu [své] tělo?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Ježíš jim tedy řekl: „Amen, amen, pravím vám, nebudete–li jíst tělo Syna člověka a nebudete–li pít jeho krev, nebudete mít v sobě život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kdo jí mé tělo a pije mou krev, má život věčný a já ho vzkřísím v poslední den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Neboť mé tělo je pravý pokrm a má krev je pravý nápoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kdo jí mé tělo a pije mou krev, zůstává ve mně a já v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Jako mne poslal živý Otec a já žiji skrze Otce, tak i ten, kdo mne jí, bude žít skrze mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Toto je ten chléb, který sestoupil z nebe; ne jako [vaši] otcové jedli [manu], a zemřeli. Kdo jí tento chléb, bude žít ⌈na věčnost⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Toto řekl, když vyučoval v synagoze v Kafarnaum.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Mnozí z jeho učedníků, když to uslyšeli, řekli: „To je tvrdá řeč. Kdo to může poslouchat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Ježíš v sobě věděl, že jeho učedníci na to reptají, a řekl jim: „To vás pohoršuje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Což tedy, kdybyste viděli Syna člověka vystupovat tam, kde byl dříve?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Duch je ten, který obživuje, tělo nic neznamená. Slova, která jsem vám pověděl já, jsou duch a jsou život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Ale jsou někteří z vás, kteří nevěří.“Ježíš totiž od počátku věděl, kteří jsou nevěřící a kdo je ten, který ho vydá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'A říkal: „Proto jsem vám řekl, že nikdo ke mně nemůže přijít, pokud mu to není dáno od Otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, '⌈Z toho důvodu ⌉ mnozí z jeho učedníků odešli zpět a už s ním nechodili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Ježíš řekl Dvanácti: „I vy chcete odejít?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Šimon Petr mu odpověděl: „Pane, ke komu půjdeme? Máš slova věčného života');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'a my jsme uvěřili a poznali, že ty jsi ⌈ [Kristus,] ten Svatý Boží⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Ježíš jim odpověděl: „Nevyvolil jsem si vás Dvanáct? Ale jeden z vás je ďábel.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'To řekl o Judovi, synu Šimona Iškariotského, neboť ten ho měl zradit, jeden z Dvanácti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Potom chodil Ježíš po Galileji; nechtěl chodit po Judsku, protože ho Židé chtěli zabít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Byl blízko židovský svátek stánků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Jeho bratři mu řekli: „Odejdi odtud a jdi do Judska, aby také tvoji učedníci uviděli tvé skutky, které činíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Vždyť nikdo nedělá nic vskrytu, chce–li být znám na veřejnosti. Činíš–li tyto věci, ukaž se světu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Ani jeho bratři totiž v něho nevěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Ježíš jim řekl: „Můj čas ještě nepřišel; ale váš čas je vždy připraven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Vás nemůže svět nenávidět, mne však nenávidí, protože já o něm svědčím, že jeho skutky jsou zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Vy vystupte na svátek do Jeruzaléma. Já na tento svátek [ještě] nevystoupím, protože můj čas se dosud nenaplnil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'To [jim] řekl a zůstal v Galileji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Když jeho bratři vystoupili na svátek do Jeruzaléma, tehdy i on tam vystoupil, ne veřejně, ale [jakoby] tajně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Židé ho během svátku hledali a říkali: „Kde je ten člověk?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'A ⌈mezi lidem⌉ bylo o něm mnoho řečí. Jedni říkali: Je dobrý, jiní říkali: Není, vždyť svádí zástup.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Nikdo o něm ovšem ze strachu před Židy nemluvil otevřeně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Když již bylo uprostřed svátků, vystoupil Ježíš do chrámu a učil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Židé se divili a říkali: „Jak to, že se tento člověk vyzná v Písmech, když se tomu neučil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Ježíš jim odpověděl: „Mé učení není mé, ale toho, který mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Bude–li někdo chtít činit jeho vůli, pozná, zda je to učení z Boha, nebo mluvím–li sám ze sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Kdo mluví ze sebe, hledá vlastní slávu. Ten však, kdo hledá slávu toho, který ho poslal, je pravdivý a není v něm nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Nedal vám Mojžíš Zákon? A nikdo z vás Zákon neplní. Proč mne usilujete zabít?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Zástup odpověděl: „Máš démona! Kdo tě usiluje zabít?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Ježíš jim odpověděl: „Jeden skutek jsem učinil, a všichni ⌈se tomu divíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Mojžíš⌉ vám dal obřízku -- ne že by byla od Mojžíše, nýbrž od otců -- a vy obřezáváte člověka i v sobotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Jestliže přijímá člověk obřízku v sobotu, aby nebyl porušen Mojžíšův zákon, proč se na mne zlobíte, že jsem v sobotu uzdravil celého člověka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Nesuďte podle zdání, ale suďte spravedlivým soudem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Tu začali někteří z obyvatel Jeruzaléma říkat: „Není to ten, kterého chtějí zabít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'A hle, mluví veřejně, a nic mu neříkají. Což opravdu vůdcové poznali, že je to Mesiáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Ale o něm víme, odkud je. Až přijde Kristus, nikdo nebude vědět, odkud je.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Tu Ježíš, vyučující v chrámě, hlasitě zvolal: „ Vskutku mě znáte a víte, odkud jsem? Nepřišel jsem sám od sebe, ale ten, kdo mne poslal a jehož vy neznáte, je pravdivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Já ho znám, neboť jsem od něho a on mne poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Chtěli ho tedy zajmout, ale nikdo na něho nevztáhl ruku, protože ještě nepřišla jeho hodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Mnozí ze zástupu však v něho uvěřili a říkali: „Když přijde Mesiáš, učiní snad více znamení, než učinil tento člověk?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Farizeové se doslechli, že to zástup o něm říká; a tak velekněží a farizeové poslali strážce, aby ho zajali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Tu Ježíš řekl: „Ještě krátký čas budu s vámi a pak odejdu k tomu, který mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Budete mne hledat, ale nenaleznete mne. A kde jsem já, tam vy přijít nemůžete.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Židé si mezi sebou řekli: „Kam tento člověk hodlá jít, že my ho nenajdeme? Chce snad jít do řecké diaspory a učit pohany?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Co znamená to slovo, které řekl: Budete mne hledat, ale nenaleznete mne, a kde jsem já, tam vy nemůžete přijít?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'V poslední, velký den svátku Ježíš vstal a zvolal: „Žízní–li kdo, ať přijde ke mně a pije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kdo věří ve mne, jak praví Písmo, řeky živé vody poplynou z jeho nitra!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'To řekl o Duchu, kterého měli přijmout ⌈ti, kteří v něho uvěřili⌉; dosud totiž Duch [svatý] nebyl dán, protože Ježíš ještě nebyl oslaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Když někteří ze zástupu uslyšeli tato slova, říkali: To je skutečně ten Prorok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Druzí říkali: To je Mesiáš, a jiní říkali: Což Mesiáš přijde z Galileje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Neříká Písmo, že Mesiáš přijde z potomstva Davidova a z Betléma, ⌈kde žil⌉ David?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Tak vznikl v zástupu kvůli němu rozkol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Někteří z nich ho chtěli zajmout, ale nikdo na něho nevztáhl ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Strážci tedy přišli k velekněžím a farizeům a ti jim řekli: „Proč jste ho nepřivedli?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Strážci odpověděli: „Nikdo nikdy takto nemluvil, [jako mluví tento člověk].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Farizeové jim odpověděli: „I vy jste svedeni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Uvěřil snad v něho některý z vůdců nebo z farizeů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Jen tento zástup, který nezná Zákon -- jsou prokleti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Jeden z nich, Nikodém, který předtím přišel k němu, jim řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '„Odsuzuje náš Zákon člověka, aniž ho nejprve vyslechne a zjistí, co učinil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Odpověděli mu: „Nejsi také ty z Galileje? Prozkoumej to a viz, že z Galileje prorok nepovstane.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'A každý se odebral do svého domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Ježíš však odešel na Olivovou horu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'A časně ráno přišel opět do chrámu a všechen lid přicházel k němu; posadil se a začal je vyučovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Tu [k němu] učitelé Zákona a farizeové přivedli ženu, přistiženou při cizoložství; postavili ji doprostřed');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'a řekli mu: „Učiteli, tato žena byla přistižena při činu cizoložství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'V Zákoně nám Mojžíš přikázal takové kamenovat. Co říkáš ty?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Těmi slovy ho zkoušeli, aby ho mohli obžalovat. Ježíš se však sklonil dolů a psal prstem po zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Když se ho nepřestávali ptát, vzpřímil se a řekl jim: „Kdo z vás je bez hříchu, ať na ni první hodí kámen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'A opět se sklonil a psal po zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Když to uslyšeli, ⌈vytráceli se⌉ jeden po druhém, [zahanbeni ve (svém) svědomí,] starší nejprve, až tam zůstal on sám a žena, která byla uprostřed.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Ježíš se vzpřímil a řekl jí: „Ženo, kde jsou [tvoji žalobci]? Nikdo tě neodsoudil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Ona řekla: „Nikdo, Pane.“Ježíš řekl: „Ani já tě neodsuzuji. Jdi a ⌈od této chvíle⌉ již nehřeš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Ježíš k nim opět promluvil: „Já jsem světlo světa. Kdo mne následuje, nebude chodit ve tmě, ale bude mít světlo života.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Farizeové mu řekli: „Ty svědčíš sám o sobě; tvé svědectví není pravé.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Ježíš jim odpověděl: „I když svědčím sám o sobě, mé svědectví je pravé, protože vím, odkud jsem přišel a kam jdu. Vy nevíte, odkud přicházím ani kam jdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vy soudíte podle těla; já nesoudím nikoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Jestliže já přece soudím, můj soud je pravdivý, protože nejsem sám, ale jsem já a ten, který mne poslal, Otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'A ve vašem Zákoně je napsáno, že svědectví dvou osob je pravé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Jsem to já, kdo svědčí o sobě, a svědčí o mně také ten, který mne poslal, Otec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Řekli mu: „Kde je tvůj Otec?“Ježíš odpověděl: „Neznáte ani mne ani mého Otce; kdybyste znali mne, znali byste i mého Otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Tato slova řekl u pokladnice, když učil v chrámě. A nikdo ho nezajal, protože ještě nepřišla jeho hodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, '[Ježíš] jim opět řekl: „Já odcházím; budete mne hledat, ale zemřete ve svém hříchu. Kam já odcházím, tam vy přijít nemůžete.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Židé říkali: „ Chce se snad zabít, že říká: Kam já odcházím, tam vy přijít nemůžete?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'I říkal jim: „Vy jste zdola, já jsem shůry. Vy jste z tohoto světa, já nejsem z tohoto světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Proto jsem vám řekl, že zemřete ve svých hříších. Jestliže neuvěříte, že ⌈Já jsem⌉, zemřete ve svých hříších.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Říkali mu: „Kdo jsi ty?“Ježíš jim řekl: „⌈Co vám od počátku říkám.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Mnoho mám o vás mluvit a soudit; ale ten, který mne poslal, je pravdivý, a já mluvím ve světě to, co jsem slyšel od něho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Nepoznali, že k nim mluvil o Otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Ježíš [jim] řekl: „Až vyvýšíte Syna člověka, tehdy poznáte, že ⌈Já jsem⌉ a že sám od sebe nečiním nic, ale mluvím tak, jak mě naučil [můj] Otec.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'A ten, kdo mne poslal, je se mnou; nezanechal mne samotného, protože já stále činím to, co se jemu líbí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Když toto mluvil, mnozí v něho uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Ježíš říkal Židům, kteří mu uvěřili: „Zůstanete–li v mém slovu, jste opravdu mými učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Poznáte pravdu a pravda vás vysvobodí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Odpověděli mu: „Jsme potomci Abrahamovi a nikdy jsme nebyli ničími otroky. Jak můžeš říkat, že se staneme svobodnými?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Ježíš jim odpověděl: „Amen, amen, pravím vám, že každý, kdo činí hřích, je otrokem hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'A otrok nezůstává v domě navždy; navždy zůstává syn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Jestliže vás tedy Syn vysvobodí, budete vskutku svobodní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Vím, že jste potomci Abrahamovi, ale usilujete mne zabít, protože mé slovo nemá ve vás místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Já mluvím o tom, co jsem viděl u [svého] Otce, a vy činíte to, co jste slyšeli u [vašeho] otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Odpověděli mu: „Náš otec je Abraham.“Ježíš jim řekl: „⌈Kdybyste byli Abrahamovy děti, činili byste⌉ Abrahamovy skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Nyní mne usilujete zabít, člověka, který vám pověděl pravdu, kterou slyšel od Boha. To Abraham neučinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vy činíte skutky svého otce.“Řekli mu: „My nejsme zrozeni ze smilstva! Máme jednoho Otce, Boha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Ježíš jim řekl: „Kdyby byl Bůh váš Otec, milovali byste mě, neboť z Boha jsem vyšel a od něho přicházím. Nepřišel jsem sám od sebe, ale on mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Proč nerozumíte mé řeči? Proto, že nemůžete slyšet mé slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vy jste z otce Ďábla a chcete činit žádosti svého otce. On byl vrah od počátku a nestál v pravdě, protože v něm pravda není. Když mluví lež, mluví ze svého vlastního, protože je lhář a otec lži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Poněvadž já říkám pravdu, nevěříte mi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kdo z vás mne usvědčí z hříchu? Říkám–li pravdu, proč mi nevěříte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Kdo je z Boha, slyší Boží slova. Vy neslyšíte, protože nejste z Boha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Židé mu odpověděli: „Neříkáme správně, že jsi Samařan a máš démona?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Ježíš odpověděl: „Já nemám démona, ale ctím svého Otce, vy však mne znevažujete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Já nehledám svou slávu; je však někdo, kdo hledá a soudí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Amen, amen, pravím vám, kdo by zachoval mé slovo, nespatří smrt ⌈na věčnost⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Židé mu řekli: „Teď jsme poznali, že máš démona. Abraham zemřel, i proroci, a ty říkáš: Kdo by zachoval mé slovo, neokusí smrti ⌈na věčnost⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Jsi snad větší než náš otec Abraham, který zemřel? Také proroci zemřeli. Co ze sebe děláš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Ježíš odpověděl: „Kdybych já oslavil sám sebe, má sláva by nic nebyla. Můj Otec to je, kdo mne oslavuje a o kom vy říkáte: Je to náš Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Vy jste ho nepoznali, ale já ho znám. Kdybych řekl, že ho neznám, budu lhář jako vy. Ale znám ho a jeho slovo zachovávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Váš otec Abraham zajásal, ⌈že mohl uvidět⌉ můj den; uviděl jej a zaradoval se.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Židé mu řekli: „Ještě ⌈ti nebylo⌉ padesát let, a viděl jsi Abrahama?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Ježíš jim řekl: „Amen, amen, pravím vám, dřív než byl Abraham, já jsem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Zvedli kameny, aby je na něho hodili. Ježíš se však skryl, [prošel mezi nimi] a vyšel z chrámu. [Tak odešel.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Cestou uviděl člověka slepého od narození.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Jeho učedníci se ho zeptali: „Rabbi, kdo zhřešil, že se narodil slepý? On sám, nebo jeho rodiče?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Ježíš odpověděl: „Nezhřešil ani on ani jeho rodiče, ale ⌈mají se na něm zjevit⌉ Boží skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Musím konat skutky toho, kdo mne poslal, dokud je den; přichází noc, kdy nikdo nebude moci pracovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Pokud jsem na světě, jsem světlo světa.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Když to řekl, plivlna zem, udělal ze sliny bláto, pomazal mu tím blátem oči');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'a řekl mu: „Jdi a umyj se v rybníku Siloe (to se překládá Poslaný).“Odešel tedy, umyl se, a když přišel, viděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Sousedé a ti, kteří ho vídali dříve, když byl žebrákem, říkali: „Není to ten, kdo tu sedával a žebral?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Jedni říkali: Je to on! Jiní říkali: Není, ale je mu podobný. On říkal: Jsem to já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Řekli mu tedy: „Jak se otevřely tvé oči?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'On odpověděl: „Člověk, který se jmenuje Ježíš, udělal bláto, potřel mi oči a řekl mi: Jdi do Siloe a umyj se. Šel jsem tedy, umyl jsem se a vidím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Řekli mu: „Kde je ten člověk?“Řekl: „Nevím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Přivedli toho, který byl dříve slepý, k farizeům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Ten den, kdy Ježíš udělal bláto a otevřel jeho oči, byla totiž sobota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Proto se ho i farizeové ptali, jak prohlédl. On jim řekl: „Přiložil mi bláto na oči, umyl jsem se a vidím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Někteří z farizeů říkali: „Tento člověk není od Boha, neboť nezachovává sobotu.“Jiní však říkali: „Jak by mohl hříšnýčlověk dělat taková znamení?“A byl mezi nimi rozkol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Řekli tedy opět tomu slepému: „Co ty o něm říkáš, když ti otevřel oči?“On řekl: „Je to prorok.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Židé neuvěřili tomu, že býval slepý a prohlédl, dokud si nezavolali jeho rodiče');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'a nezeptali se jich: „Je toto váš syn, o kterém říkáte, že se narodil slepý? Jak to, že nyní vidí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Jeho rodiče odpověděli: „Víme, že je to náš syn a že se narodil slepý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Jak to, že nyní vidí, to nevíme; nevíme také, kdo otevřel jeho oči. Jeho se zeptejte, ⌈je dospělý, ať mluví⌉ sám za sebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'To řekli jeho rodiče, protože se báli Židů, neboť Židé se již usnesli, aby ten, kdo by ho vyznal jako Krista, byl vyloučen ze synagogy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Proto jeho rodiče řekli: Je dospělý, zeptejte se jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Zavolali tedy podruhé toho člověka, který byl dříve slepý, a řekli mu: „Vzdej slávu Bohu! My víme, že ten člověk je hříšný.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'On odpověděl: „Nevím, je–li hříšný; jedno však vím, že jsem byl slepý, a teď vidím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Řekli mu: „Co ti učinil? Jak otevřel tvé oči?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Odpověděl jim: „Již jsem vám to řekl, a neslyšeli jste. Proč to chcete slyšet znovu? Chcete se snad i vy stát jeho učedníky?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Osopili se na něho a řekli: „Ty jsi jeho učedník, my jsme učedníci Mojžíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'My víme, že k Mojžíšovi mluvil Bůh, o tomto však nevíme, odkud je.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Ten člověk jim řekl: „To je právě divné, že vy nevíte, odkud je -- a otevřel mi oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Víme, že hříšníky Bůh neslyší; kdo je však zbožný a činí jeho vůli, toho slyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Od pradávna nebylo slýcháno, že by někdo otevřel oči člověka slepého od narození.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Kdyby tento člověk nebyl od Boha, nemohl by dělat nic.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Řekli mu: „Celý ses v hříších narodil, a nás ⌈chceš poučovat⌉?“A vyhnali ho ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Ježíš uslyšel, že ho vyhnali, nalezl ho a řekl: „Ty věříš v Syna člověka?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'On odpověděl: „A kdo to je, Pane, abych v něho mohl věřit?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Ježíš mu řekl: „Viděl jsi ho; je to ten, kdo s tebou mluví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'On řekl: „Věřím, Pane.“A poklonil se mu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'A Ježíš řekl: „Já jsem přišel na tento svět k soudu, aby ti, kteří nevidí, viděli, a ti, kteří vidí, se stali slepými.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Uslyšeli to někteří z farizeů, kteří byli s ním, a řekli mu: „Jsme snad i my slepí?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Ježíš jim řekl: „Kdybyste byli slepí, neměli byste hřích. Vy však říkáte: Vidíme, proto váš hřích zůstává.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '„Amen, amen, pravím vám, kdo nevchází do ovčince dveřmi, ale vniká tam odjinud, to je zloděj a lupič.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Kdo však vchází dveřmi, je pastýř ovcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Tomu hlídač otevírá a ovce slyší jeho hlas; své ovce volá jménem a vyvádí je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Když všechny své vlastní vyžene ven, kráčí před nimi a ovce ho následují, protože znají jeho hlas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Za cizím však jistě nepůjdou, ale utečou od něho, protože hlas cizích neznají.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Ježíš jim pověděl toto přirovnání, ale oni nepochopili, co jim tím ⌈chtěl říci⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Ježíš tedy opět řekl: „Amen, amen, pravím vám, já jsem ⌈dveře pro ovce⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Všichni, kteří přišli [přede mnou], jsou zloději a lupiči, ale ovce je neposlechly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Já jsem dveře. Kdo vejde skrze mne, bude zachráněn; bude vcházet i vycházet a nalezne pastvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Zloděj přichází, jen aby kradl, zabíjel a hubil; já jsem přišel, aby měly život a měly ho hojnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Já jsem ten dobrý pastýř. Dobrý pastýř pokládá svou duši za ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Námezdník, který není pastýř a ovce nejsou jeho vlastní, opouští ovce a utíká, když vidí, že přichází vlk. A vlk je uchvacuje a rozhání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, '[Námezdník utíká,] protože je námezdník a na ovcích mu nezáleží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Já jsem dobrý pastýř; znám svoje ovce a moje ovce znají mne,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'jako Otec zná mne a já znám Otce. A svou duši pokládám za ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Mám ještě jiné ovce, které nejsou z tohoto ovčince. I ty musím přivést. Uslyší můj hlas a bude jedno stádo, jeden pastýř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Proto mne Otec miluje, že já pokládám svou duši, abych ji zase přijal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Nikdo ji ode mne nebere, ale já ji pokládám sám od sebe. Mám moc ji položit, a mám moc ji opět přijmout. Tento příkaz jsem přijal od svého Otce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Pro tato slova došlo mezi Židy opět k roztržce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Mnozí z nich říkali: „Má démona a blázní. Proč ho posloucháte?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Jiní říkali: „Toto nejsou slova démonizovaného. Může snad démon otevřít oči slepým?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Nastal svátek Posvěcení chrámu v Jeruzalémě. Byla zima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Ježíš se procházel v chrámě, v Šalomounově sloupoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Tu ho obklopili Židé a říkali mu: „Jak dlouho chceš naši duši držet v nejistotě? Jsi–li Mesiáš, řekni nám to otevřeně.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Ježíš jim odpověděl: „Řekl jsem vám to, a nevěříte. Skutky, které já činím ve jménu svého Otce, ty o mně svědčí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Ale vy nevěříte, protože nejste z mých ovcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Mé ovce slyší můj hlas, já je znám, jdou za mnou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'a já jim dávám život věčný; nezahynou ⌈na věčnost⌉ a nikdo je nevytrhne z mé ruky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, '⌈Můj Otec, který mi je dal, je větší nade všechny a nikdo je nemůže⌉ vytrhnout z ruky [mého] Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Já a Otec jsme jedno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Židé se opět chopili kamenů, aby jej ukamenovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Ježíš jim řekl: „Ukázal jsem vám mnoho dobrých skutků od [svého] Otce. Pro který z nich mne ⌈chcete kamenovat⌉?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Židé mu odpověděli: „Nechceme tě kamenovat pro dobrý skutek, ale pro rouhání, že ty, člověk, děláš ze sebe Boha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Ježíš jim odpověděl: „Což není ve vašem Zákoně napsáno: Já jsem řekl: Bohové jste?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Jestliže ty, ke kterým se stalo slovo Boží, nazval bohy, -- a nemůže být zrušeno Písmo --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'proč mně, kterého Otec posvětil a poslal na svět, říkáte: Rouháš se, protože jsem řekl: Jsem Boží Syn?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Nečiním–li skutky svého Otce, nevěřte mi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Jestliže je však činím, a nevěříte mně, věřte těm skutkům, abyste poznali a dále poznávali, že Otec je ve mně a já v Otci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Znovu se ho [tedy] chtěli zmocnit, ale on unikl z jejich rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'A odešel opět za Jordán, na místo, kde zpočátku křtil Jan, a zůstal tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Mnozí přišli k němu a říkali: „Jan sice neučinil žádné znamení, avšak všechno, co Jan o něm řekl, byla pravda.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'A mnozí tam v něho uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Byl nemocen jeden člověk, Lazar z Betanie, z vesnice, kde bydlela Marie a její sestra Marta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Byla to ta Marie, která Pána pomazala vonným olejem a jeho nohy vytřela svými vlasy; její bratr Lazar byl nemocen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Sestry mu poslaly vzkaz: „Pane, hle, ten, kterého máš rád, je nemocen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Když to Ježíš uslyšel, řekl: „Tato nemoc není k smrti, ale k Boží slávě, aby Boží Syn byl skrze ni oslaven.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Ježíš miloval Martu i její sestru a Lazara.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Když uslyšel, že je Lazar nemocen, zůstal ještě dva dny na místě, kde byl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Až potom řekl učedníkům: „Pojďme opět do Judska.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Učedníci mu řekli: „Rabbi, teď tě Židé chtěli ukamenovat, a zase tam chceš jít?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Ježíš odpověděl: „Což nemá den dvanáct hodin? Kdo chodí ve dne, neklopýtá, protože vidí světlo tohoto světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Kdo však chodí v noci, klopýtá, poněvadž v něm není světlo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'To pověděl a potom jim řekl: „Náš přítel Lazar usnul; ale jdu, abych ho probudil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Učedníci mu řekli: „Pane, spí–li, bude v pořádku.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Ježíš však mluvil o jeho smrti, zatímco oni si mysleli, že mluví o přirozeném spánku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Tehdy jim Ježíš řekl otevřeně: „Lazar zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'A kvůli vám se raduji, že jsem tam nebyl, abyste uvěřili. Pojďme k němu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Tomáš, řečený Didymos, řekl svým spoluučedníkům: „Pojďme i my, ať spolu s ním zemřeme!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Když Ježíš přišel, shledal, že Lazar je již čtyři dny v hrobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Betanie byla blízko Jeruzaléma, vzdálena asi patnáct stadií.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Mnozí z Židů přišli k Martě a Marii, aby je potěšili ve smutku pro [jejich] bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Když Marta uslyšela, že Ježíš přichází, vyšla mu vstříc; Marie seděla v domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Marta Ježíšovi řekla: „Pane, kdybys byl zde, můj bratr by nezemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, '[Ale] i nyní vím, že o cokoli bys Boha požádal, Bůh ti to dá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Ježíš jí řekl: „Tvůj bratr vstane.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta mu řekla: „Vím, že vstane při vzkříšení v poslední den.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Ježíš jí řekl: „Já jsem vzkříšení i život. Kdo věří ve mne, i kdyby zemřel, bude žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'A každý, kdo žije a věří ve mne, jistě nezemře ⌈na věčnost⌉. Věříš tomu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Řekla mu: „Ano, Pane, já jsem uvěřila, že ty jsi Mesiáš, Syn Boží, ⌈který má přijít⌉ na svět.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Když to pověděla, odešla a zavolala svou sestru Marii; tajně jí řekla: „Učitel je tu a volá tě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Ta, když to uslyšela, rychle vstala a šla k němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Ježíš ještě nepřišel do vesnice, ale byl dosud na tom místě, kde se s ním setkala Marta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Když Židé, kteří byli s Marií v domě a potěšovali ji, uviděli, že rychle vstala a vyšla, vydali se za ní; ⌈domnívali se⌉, že jde k hrobu, aby se tam vyplakala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Jakmile Marie přišla tam, kde byl Ježíš, a uviděla ho, padla mu k nohám a říkala: „Pane, kdybys byl zde, můj bratr by nezemřel.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Když ji Ježíš uviděl, jak pláče a jak pláčou Židé, kteří přišli s ní, v duchu se rozhorlil, zachvěl se');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'a řekl: „Kam jste ho položili?“Řekli mu: „Pane, pojď a podívej se!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Ježíš zaplakal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Židé říkali: „Hle, jak ho měl rád.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Někteří z nich však řekli: „Nemohl ten, který otevřel oči slepého, způsobit také, aby tento člověk nezemřel?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Ježíš, znovu v sobě rozhorlen, přišel k hrobu; byla to jeskyně a na ní ležel kámen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Ježíš pravil: „Odstraňte ten kámen!“Marta, sestra toho zesnulého, mu řekla: „Pane, již zapáchá, vždyť je to čtvrtý den.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Ježíš jí říká: „Neřekl jsem ti, že jestliže uvěříš, uvidíš Boží slávu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Odstranili tedy kámen. Ježíš pozvedl oči vzhůru a řekl: „Otče, děkuji ti, že jsi mne vyslyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Já jsem věděl, že mne vždycky slyšíš, ale řekl jsem to kvůli zástupu, který tu stojí okolo, aby uvěřili, že ty jsi mne poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'A když to řekl, silným hlasem zvolal: „Lazare, pojď ven!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Ten, který byl mrtvý, vyšel, ruce i nohy měl svázány pruhy plátna a jeho tvář byla zavinuta šátkem. Ježíš jim řekl: „Rozvažte ho a nechte ho odejít!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Mnozí z Židů, kteří přišli k Marii a spatřili, co učinil, v něho uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Někteří z nich však odešli k farizeům a řekli jim, co Ježíš učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Velekněží a farizeové shromáždili veleradu a říkali: „Co uděláme? Vždyť tento člověk činí mnohá znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Jestliže ho necháme tak, všichni v něho uvěří a přijdou Římané a vezmou nám toto místo i národ.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Jeden z nich, nějaký Kaifáš, který byl onoho roku veleknězem, jim řekl: „Vy nic nechápete;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'ani nemyslíte na to, že je pro vás lépe, aby jeden člověk zemřel za lid, než aby zahynul celý národ.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Toto však neřekl sám ze sebe, ale jako velekněz onoho roku vyslovil proroctví, že Ježíš má zemřít za národ,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'a ne jenom za národ, ale také za to, aby rozptýlené Boží děti shromáždil v jedno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Od toho dne byli tedy rozhodnuti, že ho zabijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Ježíš pak již nechodil veřejně mezi Židy, ale odešel odtud do kraje blízko pustiny, do města jménem Efraim, a tam zůstal s učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Byly blízko židovské velikonoce a mnozí z venkova vystupovali před svátky do Jeruzaléma, aby se očistili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Hledali Ježíše, a jak stáli v chrámě, říkali si mezi sebou: „Co myslíte? Že by nepřišel na svátky?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Velekněží a farizeové totiž vydali nařízení, že pokud by se někdo dověděl, kde je, má to oznámit, aby ho mohli zajmout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Šest dní před velikonocemi přišel Ježíš do Betanie, kde byl Lazar, [ten, který zemřel a] jehož Ježíš probudil z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Připravili mu tam večeři. Marta je obsluhovala a Lazar byl jeden z těch, kteří s ním stolovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Tu Marie vzala libru velmi drahého pravého nardového oleje, pomazala Ježíšovi nohy a otřela mu je svými vlasy; dům se naplnil vůní toho oleje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Juda [Šimonův], Iškariotský, jeden z jeho učedníků, který jej měl zradit, řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '„Proč nebyl tento olej prodán za tři sta denárů a ty dány chudým?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'To řekl ne proto, že by mu záleželo na chudých, ale protože byl zloděj; měl pokladnici a bral z toho, co se do ní dávalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Ježíš řekl: „Nech ji. ⌈Ať jej zachová⌉ ke dni mé přípravy k pohřbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Vždyť chudé máte vždycky s sebou, ale mne nemáte vždycky.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Velký zástup Židů se dověděl, že tam je; a přišli nejen kvůli Ježíšovi, ale také proto, aby uviděli Lazara, kterého probudil z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Velekněží se rozhodli, že zabijí i Lazara,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'protože mnozí z Židů kvůli němu odcházeli a věřili v Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Nazítří uslyšel velký zástup lidí, kteří přišli na svátky, že Ježíš přichází do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Vzali palmové ratolesti, vyšli mu vstříc a volali: „Hosanna, požehnaný, jenž přichází ve jménu Pána, král Izraele.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Ježíš nalezl oslátko a vsedl na ně, jak je napsáno:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Neboj se, dcero Siónská, hle, tvůj král přichází, sedě na oslátku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Jeho učedníci si to nejprve neuvědomili, ale když byl Ježíš oslaven, tehdy si vzpomněli, že to bylo o něm napsáno a že mu to učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Zástup, který s ním byl, když zavolal Lazara z hrobu a probudil ho z mrtvých, o tom vydával svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Proto mu také vyšel zástup naproti, neboť uslyšel, že učinil toto znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Farizeové si řekli: „Vidíte, že nic nezmůžete. Hle, [celý] svět jde za ním!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Někteří z těch, kteří vystoupili do Jeruzaléma, aby se o tomto svátku poklonili Bohu, byli Řekové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Ti přišli k Filipovi, který byl z galilejské Betsaidy, a žádali ho: „Pane, chceme vidět Ježíše!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filip šel a řekl to Ondřejovi. Ondřej a Filip šli a řekli to Ježíšovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Ježíš jim řekl: „Přišla hodina, aby byl oslaven Syn člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Amen, amen, pravím vám: Jestliže pšeničné zrno, které padlo do země, nezemře, zůstává samo. Zemře–li však, přináší mnohý užitek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kdo má rád svou duši, hubí ji; kdo nenávidí svou duši v tomto světě, uchrání ji k životu věčnému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Jestliže mi někdo slouží, ať mne následuje, a kde jsem já, tam bude i můj služebník. Kdo mi slouží, toho poctí Otec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, '„Nyní je má duše rozrušena. Co mám říci? Otče, zachraň mne od této hodiny? Vždyť proto jsem přišel k této hodině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Otče, oslav své jméno!“Z nebe ⌈se ozval⌉ hlas: „Oslavil jsem a ještě oslavím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Zástup, který tam stál a uslyšel to, říkal: Zahřmělo. Jiní říkali: Anděl k němu promluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Ježíš řekl: „Ten hlas se neozval kvůli mně, ale kvůli vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Nyní je soud nad tímto světem, nyní bude ⌈vládce tohoto světa⌉ vyvržen ven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'A já, až budu vyvýšen ze země, přitáhnu všechny k sobě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Těmito slovy naznačoval, jakou smrtí má zemřít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Zástup mu odpověděl: „My jsme slyšeli ze Zákona, že Mesiáš zůstává ⌈na věčnost⌉. Jak ty můžeš říkat, že Syn člověka musí být vyvýšen? Kdo je tento Syn člověka?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Ježíš jim tedy řekl: „Ještě krátký čas je světlo mezi vámi. Choďte, dokud máte světlo, aby vás nezastihla tma; kdo chodí ve tmě, neví, kam jde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Dokud máte světlo, věřte v to světlo, abyste se stali syny světla.“To Ježíš pověděl, odešel a skryl se před nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Ačkoli před nimi učinil taková znamení, nevěřili v něho;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, '⌈a tak⌉ se naplnilo slovo, které řekl prorok Izaiáš: Pane, kdo uvěřil naší zvěsti? A komu byla zjevena Pánova paže?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Proto nemohli věřit, neboť Izaiáš také řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Oslepil jejich oči a zatvrdil jejich srdce, aby očima neuviděli a srdcem neporozuměli, neobrátili se, a já je neuzdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'To řekl Izaiáš, protože spatřil jeho slávu a mluvil o něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Přece však i mnozí z vůdců v něho uvěřili, ale kvůli farizeům se k němu nepřiznávali, aby nebyli vyloučeni ze synagogy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Zamilovali si lidskou slávu víc než slávu Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Ježíš zvolal: „Kdo věří ve mne, ne ve mne věří, ale v toho, kdo mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'A kdo vidí mne, vidí toho, kdo mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Já jsem přišel na svět jako světlo, aby nikdo, kdo ve mne věří, nezůstal ve tmě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'A jestli někdo uslyší má slova, a nezachová je, já ho nesoudím. Nepřišel jsem, abych svět soudil, ale abych svět zachránil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Kdo mne odmítá a nepřijímá moje slova, má svého soudce. Slovo, které jsem pověděl, to ho bude soudit v poslední den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Neboť já jsem nemluvil sám ze sebe, ale Otec, který mne poslal, ten mi dal příkaz, co mám říci a co promluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'A vím, že jeho přikázání je věčný život. Co tedy já mluvím, mluvím tak, jak mi pověděl Otec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Před velikonočním svátkem Ježíš věda, že přišla jeho hodina, aby z tohoto světa přešel k Otci, ⌈protože miloval⌉ své, kteří byli ve světě, miloval je až do konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Během večeře, když již Ďábel vložil do srdce Judy Šimona Iškariotského, aby jej vydal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Ježíš, vědom si toho, že mu Otec dal všechno do rukou a že od Boha vyšel a k Bohu odchází,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'vstal od večeře a odložil své šaty, vzal lněné plátno a přepásal se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Potom nalil do umyvadla vodu a začal učedníkům umývat nohy a utírat je plátnem, kterým byl přepásán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Přišel k Šimonovi Petrovi. Ten mu řekl: „Pane, ty mi ⌈chceš mýt⌉ nohy?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Ježíš mu odpověděl: „Co já činím, nyní nevíš, potom však to poznáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Petr mu řekl: „Nikdy mi nebudeš mýt nohy!“Ježíš mu odpověděl: „Jestliže tě neumyji, nemáš se mnou podíl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Šimon Petr mu řekl: „Pane, pak tedy nejen mé nohy, ale i ruce a hlavu!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Ježíš mu řekl: „Kdo je vykoupán, nepotřebuje než umýt nohy, neboť je celý čistý. I vy jste čistí, ale ne všichni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Věděl totiž, kdo ho vydává. Proto řekl: Ne všichni jste čistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Když jim umyl nohy [a] vzal si své šaty, opět ⌈zaujal místo u stolu ⌉ a řekl jim: „Chápete, co jsem vám učinil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vy mne nazýváte Učitelem a Pánem a dobře pravíte; jsem jím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Jestliže tedy já, Pán a Učitel, jsem vám umyl nohy, i vy si máte navzájem umývat nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Dal jsem vám příklad, abyste i vy činili, co jsem já učinil vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Amen, amen, pravím vám, otrok není větší než jeho pán, ani apoštol větší než ten, kdo ho poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Jestliže toto víte, jste blahoslavení, budete–li to činit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Nemluvím o vás všech; já vím, které jsem si vyvolil. Ale musí se naplnit Písmo: Ten, kdo jí ⌈se mnou⌉ chléb, pozdvihl proti mně svou patu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Již teď vám to říkám, dříve než se to stane, abyste potom, až se to stane, uvěřili, že Já jsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Amen, amen, pravím vám, kdo přijímá toho, koho pošlu, mne přijímá. A kdo přijímá mne, přijímá toho, který mne poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Když to Ježíš řekl, rozrušil se v duchu a dosvědčil: „Amen, amen, pravím vám, že jeden z vás mne zradí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Učedníci se dívali jeden na druhého v nejistotě, o kom to říká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Jeden z jeho učedníků, kterého Ježíš miloval, spočíval u stolu v Ježíšově náručí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Na toho Šimon Petr kývl, aby zjistil, kdo je ten, o kom mluví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'On se naklonil k Ježíšovým prsům a řekl mu: „Pane, kdo to je?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Ježíš odpověděl: „Je to ten, kterému namočím a podám sousto.“Namočil sousto a podal je Judovi Šimona Iškariotského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Tehdy, po tom soustu, vstoupil do něho Satan. Ježíš mu řekl: „Co činíš, učiň rychle!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Nikdo ze stolujících však neporozuměl, proč mu to řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Protože měl Juda pokladnici, domnívali se někteří, že mu Ježíš říká: „Nakup, co potřebujeme na svátek“, anebo aby dal něco chudým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'On si vzal to sousto a hned vyšel ven. Byla noc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Když Juda vyšel ven, Ježíš řekl: „Nyní byl Syn člověka oslaven a Bůh byl oslaven v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, '[Jestliže byl Bůh oslaven v něm,] oslaví Bůh i jeho v sobě a oslaví ho hned.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Dítky, ještě krátce jsem s vámi. Budete mne hledat, a jako jsem řekl Židům, tak i vám nyní říkám: Kam jdu já, tam vy přijít nemůžete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Dávám vám nové přikázání, abyste se navzájem milovali; jako já miluji vás, abyste se i vy navzájem milovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Podle toho všichni poznají, že jste moji učedníci, budete–li mít lásku jedni k druhým.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Šimon Petr mu řekl: „Pane, kam jdeš?“Ježíš mu odpověděl: „Kam já jdu, tam mne nyní následovat nemůžeš; budeš mne však následovat později.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Petr mu řekl: „Pane, proč tě nemohu následovat teď? Svou duši za tebe položím!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Ježíš odpověděl: „Svou duši za mne položíš? Amen, amen, pravím tobě: Než kohout zakokrhá, třikrát ⌈mě zapřeš⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '„Ať se vaše srdce nechvěje. Věříte v Boha, věřte i ve mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'V domě mého Otce jsou mnohé příbytky. Kdyby ne byly, ⌈řekl bych vám to. [Neboť] vám jdu připravit místo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'A odejdu–li a připravím vám místo, opět přijdu a vezmu vás k sobě, abyste i vy byli tam, kde jsem já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'A kam já jdu, [víte, i] cestu znáte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Tomáš mu řekl: „Pane, nevíme, kam jdeš. Jak můžeme znát cestu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Ježíš mu řekl: „Já jsem ta Cesta, Pravda i Život. Nikdo nepřichází k Otci než skrze mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, '⌈Jestliže znáte mne, poznáte i⌉ mého Otce. A od nynějška ho znáte a viděli jste ho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Filip mu řekl: „Pane, ukaž nám Otce a to nám stačí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Ježíš mu řekl: „Tak dlouho jsem s vámi, Filipe, a ty jsi mne nepoznal? Kdo viděl mne, viděl Otce. Jak můžeš říkat: Ukaž nám Otce?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Nevěříš, že já jsem v Otci a Otec je ve mně? Slova, která k vám mluvím, nemluvím sám ze sebe; Otec, který ve mně přebývá, činí své skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Věřte mi, že já jsem v Otci a Otec ve mně; ne–li, věřte aspoň pro ty skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Amen, amen, pravím vám: Kdo věří ve mne, i on bude činit skutky, které činím já, a bude činit ještě větší skutky než tyto, neboť já jdu k Otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'A oč byste požádali v mém jménu, to učiním, aby byl Otec oslaven v Synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Požádáte–li [mne] o něco v mém jménu, já to učiním.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, '„Jestliže mne milujete, zachovejte má přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'A já požádám Otce a on vám dá jiného Zastánce, aby byl s vámi ⌈na věčnost⌉ --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Ducha pravdy, jejž svět nemůže přijmout, protože ho nevidí ani nezná. Vy jej znáte, neboť u vás zůstává a ve vás bude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Nezanechám vás jako sirotky, přijdu k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Ještě malou chvíli a svět mne již neuvidí, vy však mne u vidíte, protože já žiji a také vy budete žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'V onen den poznáte, že já jsem ve svém Otci, vy ve mně a já ve vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Kdo má moje přikázání a zachovává je, ten mě miluje. A kdo mě miluje, bude milován od mého Otce; i já ho budu milovat a zjevím mu sám sebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Juda, ne ten Iškariotský, mu řekl: „Pane, co se stalo, že chceš zjevovat sám sebe nám, a ne světu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Ježíš mu odpověděl: „Kdo mě miluje, bude zachovávat mé slovo, a můj Otec ho bude milovat; přijdeme k němu a učiníme si u něho příbytek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Kdo mne nemiluje, nezachovává má slova. A slovo, které slyšíte, není moje, ale Otce, který mne poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, '„Toto jsem vám pověděl, dokud zůstávám u vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Ale Zastánce, Duch Svatý, kterého Otec pošle v mém jménu, ten vás naučí všemu a připomene vám všechno, co jsem vám řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Pokoj vám zanechávám, svůj pokoj vám dávám; ne jako dává svět, já vám dávám. Ať se vaše srdce nechvěje a není bázlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Slyšeli jste, že jsem vám řekl: Odcházím a přijdu k vám. Kdybyste mě milovali, zaradovali byste se, že jdu k Otci, neboť Otec je větší než já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Řekl jsem vám to nyní, dříve než se to stane, abyste uvěřili, až se to stane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Již s vámi nebudu mnoho mluvit, neboť přichází vládce tohoto světa. Proti mně nemá vůbec nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Ale ⌈svět má poznat⌉, že miluji Otce a jednám tak, jak mi Otec přikázal. Vstaňte, pojďme odtud!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '„Já jsem ta pravá vinná réva a můj Otec je hospodář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Každou ratolest ve mně, která nenese ovoce, odstraňuje, a každou, která nese ovoce, čistí, aby nesla hojnější ovoce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Vy jste již čistí pro slovo, které jsem vám pověděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Zůstaňte ve mně a já ve vás. Jako ratolest nemůže nést ovoce sama od sebe, nezůstává–li v révě, tak ani vy, jestliže nebudete zůstávat ve mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Já jsem ta vinná réva, vy jste ratolesti. Kdo ⌈zůstává ve mně⌉ a já v něm, ten nese hojné ovoce; neboť beze mne nemůžete činit nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Jestliže někdo ve mně nezůstává, bude jako ta ratolest vyvržen ven a uschne; pak je shromažďují a házejí do ohně, a hoří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Zůstanete–li ve mně a zůstanou–li mé výroky ve vás, požádejte, oč chcete, a stane se vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Tím bude oslaven můj Otec, když ponesete hojné ovoce a stanete se mými učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Jako Otec miluje mne, tak i já miluji vás. Zůstaňte v mé lásce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Zachováte–li má přikázání, zůstanete v mé lásce, jako já jsem zachoval přikázání svého Otce a zůstávám v jeho lásce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, '„Toto jsem vám pověděl, aby moje radost byla ve vás a aby vaše radost byla naplněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'To je mé přikázání, abyste se navzájem milovali, jako já miluji vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Nikdo nemá větší lásku než tu, ⌈že položí svou duši⌉ za své přátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vy jste moji přátelé, činíte–li, co vám přikazuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Už vás nenazývám otroky, protože otrok neví, co činí jeho pán; nazval jsem vás přáteli, protože jsem vám oznámil všechno, co jsem uslyšel od svého Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ne vy jste si vybrali mne, ale já jsem si vybral vás a ustanovil jsem vás, abyste vyšli a nesliovoce a vaše ovoce aby zůstávalo; aby vám Otec dal, oč byste ho požádali v mém jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'To vám přikazuji, abyste se navzájem milovali.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, '„Jestliže vás svět nenávidí, vězte, že mne nenáviděl dříve než vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Kdybyste byli ze světa, svět by miloval to, co je jeho. Že však nejste ze světa, ale já jsem si vás ze světa vybral, proto vás svět nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Pamatujte na slovo, které jsem vám řekl: Otrok není větší než jeho pán. Jestliže pronásledovali mne, i vás budou pronásledovat; jestliže zachovali mé slovo, i vaše zachovají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Ale to všechno vám učiní kvůli mému jménu, protože neznají toho, který mě poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Kdybych nepřišel a nepromluvil k nim, neměli by hřích; nyní však pro svůj hřích nemají výmluvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Kdo mne nenávidí, nenávidí i mého Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Kdybych byl mezi nimi neučinil skutky, které neučinil nikdo jiný, neměli by hřích. Ale nyní viděli, a mají v nenávisti jak mne, tak mého Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'To proto, aby se naplnilo slovo, které je napsáno v jejich Zákoně: Nenáviděli mne bez příčiny. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, '„Až přijde Zastánce, kterého vám pošlu od Otce, Duch Pravdy, jenž vychází od Otce, ten o mně vydá svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Ale i vy ⌈budete svědčit⌉, neboť jste se mnou od počátku.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '„Toto jsem vám pověděl, abyste nebyli pohoršeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Budou vás vylučovat ze synagogy; ano, přichází hodina, že se každý, kdo vás zabije, bude domnívat, že koná svatou službu Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'A to budou činit, protože nepoznali Otce ani mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Ale toto jsem vám pověděl, abyste, až ta hodina přijde, měli v paměti, že jsem vám [to] řekl.“„Tyto věci jsem vám na počátku neřekl, protože jsem byl s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Nyní však odcházím k tomu, kdo mne poslal, a nikdo z vás se mne neptá: Kam jdeš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Ale že jsem vám toto pověděl, zármutek naplnil vaše srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Ale říkám vám pravdu: Je pro vás užitečné, abych odešel. Neboť neodejdu–li, Zastánce k vám nepřijde; odejdu–li, pošlu ho k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'A on, až přijde, ⌈přinese světu důkaz⌉ o hříchu, o spravedlnosti a o soudu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'o hříchu, že nevěří ve mne,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'o spravedlnosti, že odcházím k Otci a již mne neuvidíte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'a o soudu, že vládce tohoto světa je již odsouzen.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, '„Ještě vám mám mnoho co říci, ale nemůžete to nyní snést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Když však přijde On, Duch Pravdy, uvede vás do veškeré pravdy, neboť nebude mluvit sám ze sebe, ale bude mluvit to, co uslyší; oznámí vám i to, co má přijít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'On mne oslaví, neboť z mého vezme a oznámí to vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Všechno, co má Otec, je mé; proto jsem řekl, že z mého bere a vám to oznámí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, '„Zanedlouho mě již nespatříte a zanedlouho mě opět uvidíte, [protože odcházím k Otci].“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Někteří z jeho učedníků si mezi sebou řekli: „Co znamená to, co nám říká: Zanedlouho mě nespatříte a opět zanedlouho mě uvidíte a Odcházím k Otci?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Říkali: „Co znamená to, [co říká]: Zanedlouho? Nevíme, co mluví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Ježíš poznal, že se ho na to chtěli ptát, a řekl jim: „Dohadujete se mezi sebou o tom, že jsem řekl: Zanedlouho mě nespatříte a opět zanedlouho mě uvidíte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Amen, amen, pravím vám, vy budete plakat a naříkat, ale svět se bude radovat; vy budete zarmouceni, ale váš zármutek se změní v radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Žena, když rodí, má zármutek, protože přišla její hodina; ale když porodí dítě, nevzpomíná již na soužení pro radost, že se na svět narodil člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Tak i vy nyní máte zármutek; opět vás však uvidím a vaše srdce se bude radovat a vaši radost vám nikdo nevezme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'V té hodiněse mě nebudete na nic ptát. Amen, amen, pravím vám: Jestliže o něco požádáte Otce ⌈v mém jménu, dá vám to ⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Až dosud jste o nic nepožádali v mém jménu; žádejte a dostanete, aby vaše radost byla úplná.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, '„Tyto věci jsem vám pověděl v přirovnáních. Přichází hodina, kdy k vám již nebudu mluvit v přirovnáních, nýbrž vám budu otevřeně vyprávět o Otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'V tom dni budete žádat v mém jménu, a neříkám vám, že já budu prosit Otce za vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Vždyť sám Otec vás miluje, protože jste si mě zamilovali a uvěřili jste, že já jsem vyšel od Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Vyšel jsem od Otce a přišel jsem na svět; opět opouštím svět a jdu k Otci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Jeho učedníci říkají: „Hle, teď mluvíš otevřeně a neříkáš žádné přirovnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Teď víme, že víš všechno a nepotřebuješ, aby se tě někdo na něco tázal. Proto věříme, že jsi vyšel od Boha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Ježíš jim odpověděl: „Teď věříte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Hle, přichází hodina, a již přišla, kdy budete rozptýleni každý do ⌈svých domovů⌉ a mne necháte samotného. Ale nejsem sám, neboť Otec je se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Toto jsem vám pověděl, abyste ve mně měli pokoj. Ve světě máte soužení. Ale buďte dobré mysli, já jsem přemohl svět.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Když toto Ježíš pověděl, pozdvihl své oči k nebi a řekl: „Otče, přišla ta hodina. Oslav svého Syna, aby [tvůj] Syn oslavil tebe,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'tak jako jsi mu dal pravomoc nad veškerým tělem, aby všem těm, které jsi mu dal, dal život věčný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'A toto je život věčný: Aby poznávali tebe, jediného pravého Boha, a toho, kterého jsi poslal, Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Já jsem tě oslavil na zemi, když jsem dokonal dílo, které jsi mi dal, abych je vykonal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'A nyní ty, Otče, oslav mne u sebe tou slávou, kterou jsem u tebe měl, dříve než byl svět.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, '„Zjevil jsem tvé jméno lidem, které jsi mi dal ze světa. Byli tvoji a mně jsi je dal; a tvoje slovo zachovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Nyní poznali, že vše, co jsi mi dal, je od tebe;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'neboť slova, která jsi mi dal, jsem dal jim a oni je přijali. Skutečně poznali, že jsem od tebe vyšel, a uvěřili, že jsi mě poslal ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Za ně prosím; neprosím za svět, ale za ty, které jsi mi dal, protože jsou tvoji --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'a všechno mé je tvé, a co je tvé, je mé -- a v nich jsem oslaven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'A již nejsem ve světě, ale oni jsou ve světě, a já přicházím k tobě. Otče svatý, zachovej je ve svém jménu, které jsi mi dal, aby byli jedno, jako jsme jedno my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Dokud jsem byl s nimi [ve světě], zachovával jsem je ⌈a střežil ve tvém jménu, které jsi mi dal⌉, a nikdo z nich nezahynul, kromě syna záhuby, aby se naplnilo Písmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Nyní přicházím k tobě a toto mluvím ve světě, aby v sobě měli plnost mé radosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Já jsem jim dal tvé slovo, a svět proti nim pojal nenávist, protože nejsou ze světa, jako já nejsem ze světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Neprosím, abys je vzal ze světa, ale abys je zachoval od zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Nejsou ze světa, tak jako já nejsem ze světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Posvěť je v pravdě; tvé slovo je pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Jako jsi mne poslal na svět, i já jsem je poslal na svět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'A sám sebe za ně posvěcuji, aby i oni byli v pravdě posvěceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Neprosím jenom za ně, ale i za ty, kteří budou skrze jejich slovo věřit ve mne;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'aby všichni byli jedno jako ty, Otče, ve mně a já v tobě, aby i oni v nás byli [jedno], aby svět věřil, že jsi mne poslal ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Slávu, kterou jsi mi dal, jsem dal jim, aby byli jedno, jako my [jsme] jedno --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'já v nich a ty ve mně, aby byli přivedeni k dokonalé jednotě [a] aby svět poznával, že jsi mne poslal ty a že je miluješ tak, jako miluješ mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Otče, chci, aby i ti, které jsi mi dal, byli se mnou tam, kde jsem já, aby viděli mou slávu, kterou jsi mi dal, neboť jsi mne miloval před založením světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Spravedlivý Otče, svět tě nepoznal, ale já jsem tě poznal. I tito poznali, že ty jsi mne poslal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Dal jsem jim poznat tvé jméno a dám poznat, aby láska, kterou jsi mne miloval, byla v nich, i já abych byl v nich.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, '⌈Po těch slovech⌉ vyšel Ježíš se svými učedníky za potok Cedron, kde byla zahrada, do níž vešel on i jeho učedníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Také Juda, který ho zrazoval, to místo znal, protože Ježíš se tam častokrát setkal se svými učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Juda vzal s sebou oddíl vojáků a od velekněží a farizeů strážce a přišli tam se svítilnami, pochodněmi a zbraněmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Ježíš, který věděl o všem, co se mu má přihodit, vyšel a řekl jim: „Koho hledáte?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Odpověděli mu: „Ježíše Nazaretského.“[Ježíš] jim řekl: „Já jsem.“Stál s nimi i Juda, který ho zrazoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Jakmile jim řekl: Já jsem, ustoupili dozadu a padli na zem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Opět se jich tedy zeptal: „Koho hledáte?“Oni řekli: „Ježíše Nazaretského.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Ježíš odpověděl: „Řekl jsem vám, že jsem to já. Hledáte–li mne, nechte tyto lidi odejít.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'To aby se naplnilo slovo, které řekl: Z těch, které jsi mi dal, neztratil jsem nikoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Šimon Petr, který měl meč, jej vytasil, udeřil veleknězova otroka a uťal mu pravé ucho. Jméno toho otroka bylo Malchos.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Ježíš řekl Petrovi: „Schovej meč do pochvy! Což nemám pít kalich, který mi dal Otec?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Oddíl, velitel a židovští strážci Ježíše zatkli a spoutali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Přivedli ho nejprve k Annášovi; byl totiž tchánem Kaifáše, který byl toho roku veleknězem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Byl to právě Kaifáš, který poradil Židům, že je prospěšné, aby jeden člověk zemřel za národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Za Ježíšem šel Šimon Petr a jiný učedník. Ten učedník byl znám veleknězi a vešel spolu s Ježíšem do veleknězova nádvoří,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Petr však zůstal stát před vraty. Ten druhý učedník, který byl znám veleknězi, vyšel, řekl něco vrátné a zavedl Petra dovnitř.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Tu řekla služka vrátná Petrovi: „Nejsi i ty z učedníků tohoto člověka?“On řekl: „Nejsem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Otroci a strážci rozdělali oheň, protože bylo chladno, stáli kolem něho a ohřívali se; i Petr stál s nimi a ohříval se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Velekněz se Ježíše otázal na jeho učedníky a na jeho učení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Ježíš mu odpověděl: „Já jsem mluvil k světu veřejně; učil jsem vždy v synagoze a v chrámě, kde se scházejí všichni Židé, a nic jsem neříkal tajně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Proč se ptáš mne? Zeptej se těch, kteří slyšeli, co jsem jim pověděl; hle, tito vědí, co jsem řekl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Když to řekl, jeden strážce, který stál poblíž, dal Ježíšovi ránu se slovy: „Takto odpovídáš veleknězi?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Ježíš mu odpověděl: „Jestliže jsem promluvil zle, vydej svědectví o tom zlém; jestliže však správně, proč mě biješ?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Annáš ho tedy poslal spoutaného k veleknězi Kaifášovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Šimon Petr stál u ohně a ohříval se. Tu mu řekli: „Nejsi i ty z jeho učedníků?“On zapřel: „Nejsem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Jeden z veleknězových otroků, příbuzný toho, kterému Petr uťal ucho, řekl: „Neviděl jsem tě s ním v té zahradě?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Petr opět zapřel. A vtom zakokrhal kohout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Od Kaifáše vedli Ježíše do vládního paláce. Bylo časně ráno. Oni sami do vládního paláce nevstoupili, aby se neposkvrnili a mohli jíst ⌈velikonočního beránka⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilát k nim vyšel ven a řekl: „Jakou žalobu vznášíte proti tomuto člověku?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Řekli mu: „Kdyby tento člověk nebyl zločinec, nevydali bychom ti ho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Pilát jim řekl: „Vezměte si ho a suďte ho podle svého zákona.“Židé mu řekli: „My nesmíme nikoho usmrtit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, '⌈Tak se mělo naplnit⌉ Ježíšovo slovo, které řekl, aby naznačil, jakou smrtí má zemřít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilát tedy opět vešel do vládního paláce, zavolal si Ježíše a řekl mu: „Ty jsi král Židů?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Ježíš odpověděl: „To říkáš sám od sebe, nebo ti to o mně řekli jiní?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilát odpověděl: „Jsem snad já Žid? Tvůj národ a velekněží mi tě vydali. Co jsi učinil?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Ježíš odpověděl: „Mé království není z tohoto světa; kdyby mé království bylo z tohoto světa, moji strážci by bojovali, abych nebyl vydán Židům; ale mé království není odtud.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilát mu řekl: „Jsi tedy král?“Ježíš odpověděl: „Ty říkáš, že jsem král. Já jsem se proto narodil a proto jsem přišel na svět, abych vydal svědectví pravdě. Každý, kdo je z pravdy, slyší můj hlas.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilát mu řekl: „Co je pravda?“A když to pověděl, vyšel opět k Židům a řekl jim: „Já na něm žádnou vinu nenalézám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Je u vás zvykem, že vám o velikonocích propouštím jednoho vězně. Chcete tedy, abych vám propustil krále Židů?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Znovu zvolali: „Toho ne, ale Barabáše!“Ten Barabáš byl lupič.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Tehdy Pilát vzal Ježíše a ⌈dal ho zbičovat⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Vojáci z trní upletli věnec, vložili mu jej na hlavu a oblékli mu purpurový plášť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'A přicházeli k němu a říkali: Buď zdráv, králi Židů! A dávali mu rány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilát vyšel znovu ven a řekl jim: „Hle, vedu vám ho ven, abyste poznali, že na něm nenalézám žádnou vinu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Ježíš vyšel ven, měl na sobě trnový věnec a purpurový plášť. Pilát jim řekl: „Hle, člověk!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Když ho velekněží a strážci uviděli, zvolali: „Ukřižuj! Ukřižuj!“Pilát jim řekl: „Vezměte ho vy a ukřižujte, neboť já na něm vinu nenalézám.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Židé mu odpověděli: „My máme zákon, a podle toho zákona musí zemřít, protože se ⌈vydával za Syna Božího⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Když Pilát uslyšel toto slovo, ulekl se ještě více.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Vešel znovu do vládního paláce a řekl Ježíšovi: „Odkud jsi?“Ježíš mu však nedal žádnou odpověď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilát mu tedy řekl: „Nemluvíš se mnou? Nevíš, že mám pravomoc tě propustit, a že mám pravomoc tě ukřižovat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Ježíš [mu] odpověděl: „Neměl bys nade mnou žádnou pravomoc, kdyby ti to nebylo dáno shůry. Proto ten, kdo mě tobě vydal, má větší hřích.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Od té chvíle ho Pilát usiloval propustit. Židé však křičeli: „Propustíš–li ho, nejsi přítelem císaře; každý, kdo se vydává za krále, se protiví císaři!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Když Pilát uslyšel tato slova, vyvedl Ježíše ven a usedl na soudní stolici na místě zvaném Kamenná dlažba, hebrejsky Gabbatha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Byl den přípravy před velikonocemi, kolem poledne. I řekl Židům: „Hle, váš král.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Oni zvolali: „Pryč, pryč s ním, ukřižuj ho!“Pilát jim řekl: „Vašeho krále mám ukřižovat?“Velekněží odpověděli: „Nemáme krále, jen císaře.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Tu jim ho vydal, aby byl ukřižován. Vzali Ježíše [a odváděli ho].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Sám si nesl kříž a vyšel na místo zvané Místo lebky, které se hebrejsky nazývá Golgota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Tam ho ukřižovali a s ním jiné dva po obou stranách; Ježíše uprostřed.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilát napsal a upevnil na kříž také nápis, na kterém bylo napsáno: Ježíš Nazaretský -- král Židů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Ten nápis četlo mnoho Židů, protože místo, kde byl Ježíš ukřižován, bylo blízko města; nápis byl napsán hebrejsky, latinsky a řecky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Židovští velekněží říkali Pilátovi: „Nepiš král Židů, nýbrž on řekl: Jsem král Židů. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilát odpověděl: „Co jsem napsal, napsal jsem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Vojáci pak, když Ježíše ukřižovali, vzali jeho šaty a ⌈rozdělili je na⌉ čtyři díly, každému vojákovi jeden díl. Vzali i košili. Byla to košile nesešívaná, odshora vcelku utkaná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Řekli si: „Netrhejme ji, ale losujme o ni, čí bude.“To aby se naplnilo Písmo, [které praví]: Rozdělili si mé šaty a o můj oděv metali los. To tedy vojáci učinili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'U Ježíšova kříže stála jeho matka a sestra jeho matky, Marie Kleofášova a Marie Magdalská.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Když Ježíš uviděl svou matku a učedníka, kterého miloval, jak tu stojí, řekl matce: „Ženo, hle, tvůj syn.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Pak řekl tomu učedníkovi: „Hle, tvá matka.“A od té hodiny si ji ten učedník vzal k sobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Potom, když Ježíš věděl, že už je všechno dokonáno, aby se naplnilo Písmo, řekl: „Žízním.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Stála tam nádoba plná octa; nasadili houbu plnou octa na yzop a podali mu ji k ústům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Když Ježíš okusil octa, řekl: „Dokonáno jest.“Naklonil hlavu a odevzdal ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Poněvadž byl den přípravy a Židé ne chtěli, aby těla zůstala přes sobotu na kříži -- tu sobotu byl totiž velký den --, požádali Piláta, aby byly ukřižovaným zlámány nohy a aby byli sňati z kříže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Přišli tedy vojáci a zlámali nohy prvnímu i druhému, kteří byli ukřižováni spolu s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Když však přišli k Ježíšovi a uviděli, že je již mrtev, nohy mu nezlámali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'ale jeden z vojáků mu kopím probodl bok; a hned vyšla krev a voda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'A ten, který to viděl, vydal svědectví a jeho svědectví je pravdivé; on ví, že mluví pravdu, abyste i vy uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'To se stalo, aby se naplnilo Písmo: Kost mu nebude zlomena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'A zase ⌈na jiném místě⌉ Písmo praví: Uvidí, koho probodli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Po tomto Josef z Arimatie, který byl Ježíšovým učedníkem -- ale ze strachu před Židy tajným -- požádal Piláta, aby směl odnést Ježíšovo tělo. A Pilát svolil. Šel tedy a sňal jeho tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Přišel také Nikodém, který k němu poprvé přišel v noci, a nesl asi sto liber směsi myrhy a aloe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Vzali tedy Ježíšovo tělo a zavinuli je s těmi vonnými věcmi do lněných pláten, jak je to u Židů při pohřbu zvykem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Na tom místě pak, kde byl ukřižován, byla zahrada a v té zahradě nový hrob, v němž ještě nebyl nikdo pochován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Tam kvůli židovskému dni přípravy Ježíše položili, neboť hrob byl blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Prvního dne týdne přišla Marie Magdalská časně ráno, ještě za tmy, ke hrobu a uviděla kámen odvalený od hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Běžela tedy a přišla k Šimonu Petrovi a k druhému učedníkovi, kterého měl Ježíš rád, a řekla jim: „Vzali Pána z hrobu a nevíme, kam ho položili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Petr a ten druhý učedník tedy vyšli a zamířili ke hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Běželi oba spolu, ale ten druhý učedník běžel napřed, rychleji než Petr, a přišel ke hrobu první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Naklonil se dovnitř a uviděl tam ležet plátna, ale dovnitř nevstoupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Potom přišel také Šimon Petr, který šel za ním. Vešel do hrobu a uviděl tam ležet lněná plátna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'avšak šátek, který byl na Ježíšově hlavě, neležel se lněnými plátny, nýbrž byl svinut zvlášť na jednom místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Potom vstoupil i ten druhý učedník, který k hrobu přišel první; i uviděl a uvěřil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Neboť ještě neznali Písmo, že musí vstát z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Učedníci pak opět odešli domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Marie stála venku před hrobem a plakala. Jak plakala, naklonila se do hrobu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'a uviděla dva anděly v bílém rouchu sedící na místě, kde leželo Ježíšovo tělo; jednoho u hlavy a druhého u nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'A ti jí řekli: „Ženo, proč pláčeš?“Řekla jim: „Vzali mého Pána a nevím, kam ho položili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Když to řekla, otočila se dozadu a uviděla tam stát Ježíše; nevěděla však, že je to Ježíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Ježíš jí řekl: „Ženo, proč pláčeš? Koho hledáš?“Ona mu v domnění, že je to zahradník, řekla: „Pane, jestliže tys ho odnesl, řekni mi, kam jsi ho položil, a já si ho vezmu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Ježíš jí řekl: „Marie!“Ona se otočila a hebrejsky mu řekla: „Rabbuni“, což znamená Učiteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Ježíš jí řekl: „Nedrž se mne, neboť jsem ještě nevystoupil ke [svému] Otci. Jdi k mým bratřím a řekni jim: Vystupuji k Otci svému i k Otci vašemu, k Bohu svému i k Bohu vašemu. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marie Magdalská šla a zvěstovala učedníkům: „Viděla jsem Pána“, ⌈a oznámila jim to, co jí řekl⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Když byl večer téhož dne, prvního v týdnu, a učedníci byli ze strachu před Židy [shromážděni] za zavřenými dveřmi, přišel Ježíš, postavil se doprostřed a řekl jim: „Pokoj vám.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Když to řekl, ukázal jim ruce a bok. I zaradovali se učedníci, když uviděli Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, '[Ježíš] jim opět řekl: „Pokoj vám. Jako mne poslal Otec, i já posílám vás.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Po těchto slovech ⌈na ně dechl⌉ a řekl jim: „Přijměte Ducha Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Komu odpustíte hříchy, tomu jsou odpuštěny, komu je zadržíte, tomu jsou zadrženy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Tomáš zvaný Didymos, jeden z Dvanácti, však nebyl s nimi, když Ježíš přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Ostatní učedníci mu říkali: „Viděli jsme Pána.“On jim však řekl: „Pokud neuvidím stopu hřebů v jeho rukou a nevložím svůj prst na místo hřebů a svou ruku do jeho boku, neuvěřím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Po osmi dnech byli jeho učedníci opět uvnitř a Tomáš s nimi. Ježíš přišel zavřenými dveřmi. Postavil se doprostřed a řekl: „Pokoj vám.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Potom řekl Tomášovi: „Vztáhni svůj prst sem a pohleď na mé ruce, vztáhni svou ruku a vlož ji do mého boku; a nebuď nevěřící, ale věřící.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Tomáš mu odpověděl slovy: „Můj Pán a můj Bůh.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Ježíš mu řekl: „Že jsi mne viděl, uvěřil jsi. Blahoslavení, kteří neviděli, a uvěřili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Ještě mnoho jiných znamení, která nejsou zapsána v této knize, učinil Ježíš před [svými] učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Tato však jsou zapsána, abyste uvěřili, že Ježíš je Mesiáš, Syn Boží, a abyste věříce měli život v jeho jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Potom se Ježíš opět zjevil učedníkům u Tiberiadského moře. Zjevil se takto:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Šimon Petr, Tomáš zvaný Didymos, Natanael z Kány Galilejské, synové Zebedeovi a další dva z jeho učedníků byli spolu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Šimon Petr jim řekl: „Jdu ⌈lovit ryby⌉.“Řekli mu: „I my půjdeme s tebou.“Vyšli a vstoupili do lodi. Ale oné noci neulovili nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Když nastalo jitro, postavil se Ježíš na pobřeží, ale učedníci nevěděli, že je to on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Ježíš jim řekl: „Děti, máte něco k jídlu?“Odpověděli mu: „Ne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'On jim řekl: „Hoďte síť na pravou stranu lodi a naleznete.“Hodili ji tedy a už ji nemohli utáhnout pro spoustu ryb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Tu onen učedník, kterého Ježíš miloval, řekl Petrovi: „ To je Pán.“Když Šimon Petr uslyšel, že je to Pán, převázal si plášť, neboť byl nahý, a vrhl se do moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Ostatní učedníci přijeli na lodi, neboť nebyli od země daleko, jen asi dvě stě loktů, a vlekli síť plnou ryb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Když vystoupili na zem, uviděli ⌈žhavé uhlí⌉ a na něm položenou rybu a chléb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Ježíš jim řekl: „Přineste něco z těch ryb, které jste právě chytili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Šimon Petr vystoupil a vytáhl na zem síť plnou velkých ryb, bylo jich sto padesát tři. I když jich bylo tak mnoho, síť se neroztrhla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Ježíš jim řekl: „Pojďte posnídat.“Nikdo z učedníků se ho neodvážil zeptat: „Kdo jsi?“Věděli, že je to Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Ježíš přistoupil, vzal chléb a dával jim; podobně i rybu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'To se již potřetí Ježíš zjevil [svým] učedníkům po svém zmrtvýchvstání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Když posnídali, řekl Ježíš Šimonu Petrovi: „Šimone Janův, miluješ mne více než tito?“Odpověděl mu: „Ano, Pane, ty víš, že tě mám rád.“Řekl mu: „Pas mé beránky.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Řekl mu opět podruhé: „Šimone Janův, miluješ mne?“Odpověděl mu: „Ano, Pane, ty víš, že tě mám rád.“Řekl mu: „Pas mé ovce.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Řekl mu potřetí: „Šimone Janův, máš mě rád?“Petr se zarmoutil, že mu potřetí řekl: Máš mě rád?, a odpověděl mu: „Pane, ty víš všechno, ty víš, že tě mám rád.“Ježíš mu řekl: „Pas mé ovce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Amen, amen, pravím tobě, když jsi byl mladší, sám ses opásával a chodil jsi, kam jsi chtěl; ale až zestárneš, vztáhneš své ruce a jiný tě opáše a povede, kam nechceš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Toto řekl, ⌈aby mu naznačil⌉, jakou smrtí oslaví Boha. Po těchto slovech mu řekl: „Následuj mne.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Petr se obrátil a uviděl, jak za nimi jde učedník, kterého Ježíš miloval a který se také při večeři naklonil k jeho prsům a řekl: Pane, kdo je ten, který tě zrazuje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Když jej Petr uviděl, řekl Ježíšovi: „Pane, co bude s tímto?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Ježíš mu řekl: „Jestliže chci, aby tu zůstal, dokud nepřijdu, co je ti po tom? Ty mne následuj.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'A tak ⌈se mezi bratry rozšířilo⌉ to slovo, že onen učedník nezemře. Ježíš mu však neřekl, že nezemře, nýbrž: Jestliže chci, aby tu zůstal, dokud nepřijdu, co je ti po tom?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'To je ten učedník, který vydává svědectví o těchto věcech a který je zapsal; a víme, že jeho svědectví je pravdivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Je ještě mnoho jiných věcí, které Ježíš učinil; kdyby se o každé zvlášť napsalo, myslím, že by celý svět neobsáhl knihy o tom napsané. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'První zprávu, ó Theofile, jsem napsal o všem, co Ježíš začal činit a učit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'až do dne, kdy byl vzat vzhůru, když skrze Ducha Svatého dal příkazy apoštolům, které si vyvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Jim také po svém utrpení mnoha důkazy prokázal, že žije, po čtyřicet dní se jim dával spatřit a říkal jim o Božím království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'A když s nimi jedl, nařídil jim, aby se nevzdalovali z Jeruzaléma, ale očekávali Otcovo zaslíbení -- „které jste slyšeli ode mne,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'neboť Jan křtil vodou, vy však po nemnohých těchto dnech budete pokřtěni v Duchu Svatém.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Když se tedy sešli, tázali se ho: „Pane, v tomto čase obnovíš království pro Izrael?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Řekl jim: „Nepřísluší vám poznat časy a doby, které Otec uložil ve své vlastní pravomoci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'ale přijmete ⌈moc Ducha Svatého, který na vás přijde⌉, a budete mi svědky v Jeruzalémě a v celém Judsku, Samařsku a až po nejzazší konec země.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Když to pověděl, byl ⌈před jejich zraky⌉ vyzdvižen a oblak jim ho vzal z očí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'A když se upřeně dívali do nebe, jak odchází, hle, stáli vedle nich dva muži v bílých šatech');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'a řekli: „Muži galilejští, co tu stojíte a hledíte do nebe? Tento Ježíš, který byl od vás vzat vzhůru [do nebe], přijde právě tak, jak jste ho viděli odcházet do nebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Potom se vrátili do Jeruzaléma z hory nazývané Olivová, která je blízko Jeruzaléma, ve vzdálenosti sobotní cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Když vešli do města, vystoupili do horní místnosti, kde pobývali Petr, Jan, Jakub, Ondřej, Filip, Tomáš, Bartoloměj, Matouš, Jakub Alfeův, Šimon Zélóta a Juda Jakubův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ti všichni zůstávali jednomyslně oddáni modlitbě spolu se ženami, s Marií, matkou Ježíšovou, a [s] jeho bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'V těch dnech se postavil Petr uprostřed bratří -- byl tam pohromadě zástup asi sto dvaceti osob -- a řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '„⌈Muži bratři,⌉ muselo se naplnit slovo Písma, které předpověděl Duch Svatý ústy Davidovými o Judovi, jenž se stal vůdcem těch, kteří se zmocnili Ježíše;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'byl počítán mezi nás a obdržel podíl na této službě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Z odměny za nepravost získal pole, a když spadl střemhlav, roztrhl se v půli a všechny jeho vnitřnosti vyhřezly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'A to se stalo známým všem obyvatelům Jeruzaléma, takže to pole bylo v jejich vlastním jazyce nazváno Hakeldama, to znamená Krvavé pole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Neboť je napsáno v knize Žalmů: Jeho příbytek ať zpustne, ať není nikoho, kdo by v něm bydlil a Jeho pověření ať obdrží jiný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Proto se musí jeden z těch mužů, kteří s námi chodili po celý ten čas, kdy Pán Ježíš pobýval mezi námi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'od křtu Janova až do dne, kdy byl od nás vzat vzhůru, stát spolu s námi svědkem jeho zmrtvýchvstání.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'I postavili dva: Josefa zvaného Barsabáš, jenž měl příjmení Justus, a Matěje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Pak se pomodlili a řekli: „Ty, Pane, který znáš srdce všech, ukaž, kterého z těchto dvou sis vyvolil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'aby dostal místo v této ⌈službě a v apoštolství⌉, od něhož se Juda odvrátil a odešel na své místo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Dali jim losy a los padl na Matěje; i byl volbou připojen k jedenácti apoštolům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Když nastal den Letnic, byli všichni spolu na jednom místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Náhle se ozval zvuk z nebe, jako když se žene prudký vítr, a naplnil celý dům, kde seděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'A ukázaly se jim jazyky jakoby z ohně, které se rozdělovaly, a na každém z nich se usadil jeden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Všichni byli naplněni Duchem Svatým a začali mluvit jinými jazyky, jak jim Duch dával promlouvat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'V Jeruzalémě pobývali Židé, zbožní muži ze všech národů, které jsou pod nebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'A když se ozval ten zvuk, sešlo se mnoho lidí a byli zmateni, protože každý z nich je slyšel mluvit svou vlastní řečí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, '[Všichni] byli ohromeni a udiveně říkali: „Hle, což nejsou všichni ti, kteří tu mluví, Galilejci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Jak to, že každý z nás slyší svůj vlastní jazyk, ve kterém jsme se narodili?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parthové, Médové a Elamité, obyvatelé Mezopotámie, Judska a Kappadokie, Pontu a Asie,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frygie a Pamfylie, Egypta a oblastí Libye u Kyrény a návštěvníci z Říma,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Židé i proselyté, Kréťané a Arabové: všichni je slyšíme mluvit našimi jazyky veliké věci Boží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Všichni z toho byli ohromeni a zmateni a jeden druhému říkali: „Co to má znamenat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Ale jiní se posmívali a říkali: „Jsou opilí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Petr se postavil spolu s jedenácti, pozvedl svůj hlas a přímo k nim promluvil: „Muži judští a všichni obyvatelé Jeruzaléma, toto ať je vám známo, vyslechněte pozorně má slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Tito lidé nejsou opilí, jak se domníváte. Vždyť je ⌈devět hodin ráno⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Ale toto je to, co je řečeno skrze proroka [Jóela]:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'I stane se v posledních dnech, praví Bůh, že vyleji ze svého Ducha na každé tělo; vaši synové a vaše dcery budou prorokovat, vaši mladíci budou vídat vidění a vaši starci budou mívat sny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'I na své otroky a na své otrokyně [v oněch dnech] vyleji ze svého Ducha, [a budou prorokovat].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'A dám divy nahoře na nebi a znamení dole na zemi, [krev a oheň a sloupy dýmu].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Slunce se obrátí v temnotu a měsíc v krev, než přijde Pánův den, veliký a skvělý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'I ⌈stane se,⌉ že každý, kdo bude vzývat Pánovo jméno, bude zachráněn. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, '„Muži izraelští, slyšte tato slova: Ježíše Nazaretského, muže dosvědčeného vám od Boha mocnými činy, divy a znameními, které Bůh uprostřed vás skrze něho učinil, jak sami víte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'tohoto muže, vydaného podle ustanoveného úradku a předzvědění Božího, jste skrze ruce bezbožníků přibili na kříž a odstranili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Ale Bůh ho vzkřísil, zprostiv ho bolestí smrti, protože nebylo možné, aby byl od ní držen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Neboť David o něm říká: Viděl jsem Pána stále před sebou, neboť je po mé pravici, abych nezakolísal;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'proto se mé srdce zaradovalo a můj jazyk se rozjásal, nadto i mé tělo bude přebývat v naději,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'neboť nezanecháš mou duši v podsvětí, aniž dáš svému Svatému uvidět zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Oznámil jsi mi cesty života, naplníš mě radostí před svou tváří. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, '„Muži bratři, o patriarchovi Davidovi vám mohu směle říci, že zemřel a byl pohřben a jeho hrob je mezi námi až do dnešního dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Byl to prorok a věděl, že se mu Bůh přísahou zavázal, že na jeho trůn posadí ⌈potomka z jeho beder⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'viděl do budoucnosti a promluvil o Kristově zmrtvýchvstání, když řekl, že [jeho duše] nebyla zanechána v podsvětí a jeho tělo nevidělo zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Tohoto Ježíše Bůh vzkřísil a my všichni jsme toho svědky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Když byl tedy vyvýšen pravicí Boží a přijal od Otce ⌈zaslíbeného Ducha Svatého⌉, vylil to, co vy nyní vidíte i slyšíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Neboť David nevystoupil na nebesa, ale sám říká: Řekl Pán mému Pánu: Seď po mé pravici,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'dokud nepoložím tvé nepřátele za podnož tvých nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Ať tedy všechen dům Izraele s jistotou ví, že Bůh učinil toho Ježíše, kterého jste vy ukřižovali, i Pánem i Mesiášem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Když to uslyšeli, byli ⌈hluboce zasaženi⌉ v srdci a řekli Petrovi i ostatním apoštolům: „Co máme dělat, muži bratři?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Petr jim [řekl]: „Učiňte pokání a každý z vás ať se dá pokřtítna základě jména Ježíše Mesiáše na odpuštění svých hříchů, a přijmete dar Ducha Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Neboť to zaslíbení platí vám a vašim dětem i všem, kteří jsou daleko a které si povolá Pán, náš Bůh.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'A ještě mnoha jinými slovy to dosvědčil a vyzýval je: „Zachraňte se z tohoto zvráceného pokolení!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ti, kteří [radostně] přijali jeho slovo, byli pokřtěni a toho dne bylo přidáno asi tři tisíce duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Vytrvale zůstávali v učení apoštolů a ve společenství, v lámání chleba a modlitbách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Každé duše se zmocňoval strach; skrze apoštoly se [v Jeruzalémě] dálo mnoho divů a znamení [a na všech byl veliký strach].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Všichni věřící byli pospolu a měli všechno společné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Prodávali svá zboží a majetky a dělili je mezi všechny, jak kdo potřeboval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Denně zůstávali jednomyslně v chrámě, po domech lámali chléb a přijímali pokrm s veselím a prostotou srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Chválili Boha a ⌈byli oblíbeni⌉ u všeho lidu. A Pán k jejich společenství denně přidával ty, kteří byli zachraňováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, '⌈Petr a Jan⌉ vystupovali o ⌈třetí hodině odpoledne ⌉ -- hodině modlitby -- do chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Právě tam přinášeli nějakého muže, který byl chromý již od lůna své matky; každý den ho kladli ke dveřím chrámu, kterým se říkalo Krásné, aby ty, kdo vcházeli do chrámu, prosil o almužnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Když uviděl Petra a Jana, jak se chystají vejít do chrámu, prosil o almužnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Petr s Janem se na něj upřeně zadíval a řekl: „Pohleď na nás!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Pozorně je sledoval a očekával, že od nich něco dostane.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Petr však řekl: „Stříbro a zlato nemám, ale co mám, to ti dám: ve jménu Ježíše Krista Nazaretského [vstaň a] choď!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Uchopil ho za pravou ruku a pozdvihl jej. Ihned se zpevnily jeho nohy a klouby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Postavil se, vyskakoval a chodil. Vešel s nimi do chrámu, chodil, skákal a chválil Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'A všechen lid ho spatřil, jak chodí a chválí Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Poznali ho, že je to ten, který kvůli almužně sedal u Krásné brány chrámu, a byli naplněni úžasem a ohromením nad tím, co se mu přihodilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Zatímco se držel Petra a Jana, všechen lid se k nim seběhl do sloupoví, které se nazývá Šalomounovo, a byli vyděšení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Když to Petr uviděl, promluvil k lidu: „Muži izraelští, proč nad tím žasnete a proč tak upřeně hledíte na nás, jako bychom vlastní mocí nebo zbožností způsobili, že on chodí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Bůh Abrahamův, [Bůh] Izákův a [Bůh] Jákobův, Bůh našich otců oslavil svého služebníka Ježíše, kterého vy jste vydali a zřekli se ho před tváří Piláta, když se ho rozhodl propustit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Svatého a Spravedlivého jste se zřekli a vyžádali jste si, aby vám byl darován muž vrah.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Zabili jste Původce života, kterého Bůh vzkřísil z mrtvých; my jsme toho svědky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'A tohoto muže, kterého vidíte a znáte, ⌈na základě víry⌉ ⌈v Ježíšovo jméno⌉ toto jméno upevnilo a víra, která je skrze něho, mu dala toto plné zdraví před očima vás všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'A nyní, bratři, vím, že jste to udělali z nevědomosti, stejně jako vaši vůdcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Bůh však takto splnil, co předem ohlásil ústy všech proroků, že jeho Mesiáš bude trpět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Učiňte tedy pokání a obraťte se, aby byly vymazány vaše hříchy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'a přišly časy osvěžení od Pánovy tváře, a aby poslal určeného vám Mesiáše, Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Nebe ho musí přijmout až do časů obnovy všech věcí, jak o tom Bůh od věků mluvil ústy [všech] svých svatých proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Mojžíš řekl: Proroka vám vzbudí Pán, váš Bůh, z vašich bratrů jako vzbudil mne; toho budete poslouchat ve všem, co by vám řekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'A stane se, že každá duše, která neuposlechne toho proroka, bude vyhlazena z lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Také všichni proroci, kteří mluvili od Samuela dále, zvěstovali i tyto dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vy jste synové proroků a smlouvy, kterou Bůh uzavřel s vašimi otci, když řekl Abrahamovi: A v tvém semeni budou požehnány všechny rodinyzemě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Vám nejprve Bůh vzbudil svého služebníka a poslal ho, ⌈aby vám požehnal tím, že každého z vás odvrátí⌉ od vašich špatností.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Když ještě mluvili k lidu, přistoupili k nim kněží, velitel chrámové stráže a saduceové');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'a hněvali se, že učí lid a zvěstují v Ježíši vzkříšení z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Vztáhli na ně ruce a vsadili je do vězení do druhého dne, neboť už byl večer.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Ale mnozí z těch, kteří to slovo uslyšeli, uvěřili, a počet těch mužů vzrostl asi na pět tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Druhý den se v Jeruzalémě shromáždili jejich vůdci, starší a učitelé Zákona,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'velekněz Annáš, Kaifáš, Jan a Alexandr a všichni, kteří byli z velekněžského rodu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'postavili je uprostřed a začali se vyptávat: „Jakou mocí nebo v jakém jménu jste to učinili?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Tu jim Petr naplněn Duchem Svatým řekl: „Vůdcové lidu a starší [Izraele],');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'jsme–li dnes vyslýcháni pro dobrý skutek na nemocném člověku, kým že byl uzdraven,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'ať je známo vám všem a všemu lidu Izraele, že ve jménu Ježíše Krista Nazaretského, kterého jste vy ukřižovali, ale kterého Bůh probudil z mrtvých, v tomto jménu stojí tento člověk před vámi zdráv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'To je ten kámen, který byl zavržen od vás stavitelů, a který se stal hlavou úhlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'A v nikom jiném není záchrana; neboť není pod nebem jiného jména daného lidem, v němž bychom měli být zachráněni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Když pozorovali Petrovu a Janovu smělost a shledali, že jsou to lidé neučení a prostí, žasli; poznávali je, že bývali s Ježíšem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'A když viděli toho uzdraveného člověka, jak tam stojí s nimi, neměli, co by na to řekli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Poručili jim, aby odešli ven z velerady, a radili se mezi sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Říkali: „Co máme učinit s těmito lidmi? Všem obyvatelům Jeruzaléma je jasné, že se skrze ně stalo zřejmé znamení, a my to nemůžeme popřít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Ale aby se to ještě více nerozšířilo mezi lid, pohrozme jim, ať již ⌈k nikomu⌉ nemluví v tomto jménu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Zavolali je a přikázali jim, aby vůbec veřejně nemluvili ani neučili v Ježíšově jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Petr a Jan jim odpověděli: „Posuďte, zda je před Bohem správné, abychom poslouchali vás více než Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Neboť my nemůžeme nemluvit o tom, co jsme viděli a slyšeli.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Oni jim pohrozili a propustili je, protože nenalézali nic, zač by je potrestali, a to kvůli lidu, neboť všichni oslavovali Boha za to, co se stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Tomu člověku, na němž se toto znamení uzdravení stalo, bylo totiž už přes čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Když byli propuštěni, přišli mezi své a oznámili, co jim řekli velekněží a starší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Když to uslyšeli, jednomyslně pozdvihli hlas k Bohu a řekli: „Panovníku, ty, který jsi učinil nebe i zemi i moře a vše, co je v nich,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'ty jsi [skrze Ducha Svatého] ústy svého služebníka, [našeho otce] Davida, řekl: Proč zuří národy a lidé zamýšlejí marné věci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Králové země se postavili a vládcové se shromáždili společně proti Pánu a proti jeho Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'V tomto městě se opravdu sešli Herodes a Pontius Pilát spolu s národy i s lidem Izraele proti tvému svatému služebníku Ježíšovi, kterého jsi pomazal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'aby učinili, co tvá ruka a [tvůj] úradek předem určily, že se má stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'A nyní, Pane, pohleď na jejich hrozby a dej svým otrokům se vší smělostí mluvit tvé slovo;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'vztahuj svou ruku k tomu, aby se dála uzdravení, znamení a divy skrze jméno tvého svatého služebníka Ježíše.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Když se pomodlili, zatřáslo se místo, kde byli shromážděni, a všichni byli naplněni Duchem Svatým a směle mluvili Boží slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Všichni, kdo uvěřili, byli jednoho srdce a jedné duše a nikdo neříkal o ničem, co měl, že je to jeho vlastní, nýbrž měli všechno společné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'A apoštolové vydávali s velikou mocí svědectví o zmrtvých vstání Pána Ježíše [Krista] a veliká milost byla na nich všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Nikdo mezi nimi netrpěl nouzi, neboť ti, kdo byli vlastníky polností nebo domů, svá pole nebo domy prodávali a výtěžky z prodeje přinášeli');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'a kladli k nohám apoštolů. Z toho se pak rozdělovalo každému, jak kdo potřeboval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Také Josef, který byl apoštoly nazván Barnabáš, což v překladu znamená syn potěšení, Levita, rodem z Kypru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'měl pole, které prodal, peníze přinesl a položil k nohám apoštolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Nějaký muž, jménem Ananiáš, prodal se svou ženou Safirou pozemek');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'a s vědomím své ženy dal z výtěžku něco stranou, určitou část přinesl a položil k nohám apoštolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Petr řekl: „Ananiáši, proč Satan naplnil tvé srdce, že jsi lhal Duchu Svatému a dal jsi stranou část z výtěžku za to pole?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Dokud zůstávalo neprodané, což nebylo tvé? A když jsi je prodal, což nebylo v tvé moci, co uděláš s penězi? Proč ses ve svém srdci rozhodl k takové věci? Nelhal jsi lidem, ale Bohu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Když Ananiáš slyšel tato slova, padl a zemřel; a na všechny, kteří to slyšeli, padl veliký strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Mladší z bratří vstali, přikryli jej, vynesli a pohřbili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Uplynuly asi tři hodiny a vstoupila jeho žena, nevědouc, co se stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Petr k ní promluvil: „Pověz mi, prodali jste to pole za tolik peněz?“Ona řekla: „Ano, za tolik.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Petr jí řekl: „Proč jste se smluvili, abyste pokoušeli Pánova Ducha? Hle, kroky těch, kteří pohřbili tvého muže, je slyšet za dveřmi; vynesou i tebe.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'A hned padla k jeho nohám a zemřela. Když ti mladíci vstoupili, našli ji mrtvou. Vynesli ji a pohřbili k jejímu muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'A velký strach padl na celou církev i na všechny, kteří to slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Skrze ruce apoštolů se mezi lidem dálo mnoho znamení a divů. A všichni jednomyslně pobývali v Šalomounově sloupoví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Z ostatních se k nim nikdo neodvažoval připojit, ale lid je velebil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'A ještě více věřících bylo přidáváno Pánu, množství mužů i žen,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'takže dokonce na ulice vynášeli nemocné a kladli je na lůžka a lehátka, aby na některého z nich padl aspoň Petrův stín, když tudy půjde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Scházelo se také množství lidí ⌈z měst okolo⌉ Jeruzaléma, přinášeli nemocné a trápené nečistými duchy, a ti všichni byli uzdravováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Tu povstal velekněz a všichni, kteří byli s ním, totiž strana saduceů; byli naplněni žárlivostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'I vztáhli na apoštoly ruce a vsadili je do veřejného vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Pánův anděl však v noci otevřel dveře vězení, vyvedl je ven a řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '„Jděte, postavte se v chrámě a mluvte k lidu všechna slova tohoto života.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Když to uslyšeli, vešli za úsvitu do chrámu a učili. Když se dostavil velekněz a ti, kteří byli s ním, svolali veleradu, celý sbor starších synů Izraele a poslali do vězení, aby byli apoštolové přivedeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Když tam služebníci přišli, ve vězení je nenalezli. Vrátili se a oznámili:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, '„Vězení jsme našli důkladně zavřené a stráže stojící u dveří, ale když jsme otevřeli, nenašli jsme uvnitř nikoho.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Když ta slova uslyšel velitel chrámové stráže a velekněží, byli tím velmi zmateni. Nechápali, co se to mohlo stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Kdosi však přišel a oznámil jim: „Hle, muži, které jste vsadili do vězení, stojí v chrámě a učí lid.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Pak pro ně velitel se služebníky šel a přivedl je -- ale bez násilí; báli se totiž lidu, [aby] nebyli ukamenováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Když je přivedli, postavili je před veleradu a velekněz se jich otázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, '„Výslovně jsme vám přikázali, abyste neučili v tomto jménu, a hle, naplnili jste Jeruzalém svým učením a chcete na nás uvést krev toho člověka.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Petr a apoštolové odpověděli: „Boha je třeba poslouchat více než lidi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Bůh našich otců probudil z mrtvých Ježíše, kterého jste vy pověsili na dřevo a zabili;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'toho Bůh jako vůdce a zachránce vyvýšil ⌈na svou pravici⌉, aby dal Izraeli pokání a odpuštění hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'My jsme svědkové těchto slov, i Duch Svatý, kterého Bůh dal těm, kdo ho poslouchají.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Když to uslyšeli, rozzuřili se a chtěli je zabít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Tu povstal ve veleradě jeden farizeus jménem Gamaliel, ⌈učitel Zákona⌉, kterého si vážil všechen lid; poručil, aby ty lidi na chvíli vyvedli ven,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'a řekl jim: „Muži Izraelci, dobře si rozvažte, co s těmito lidmi uděláte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Neboť před nedávnem povstal Theudas a říkal, že on je někým [velikým]; i připojil se k němu počet asi čtyř set mužů. Byl však zabit, a všichni, kteří ho poslouchali, byli rozptýleni a obráceni vniveč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Po něm povstal ve dnech soupisu Juda Galilejský a strhl za sebou lid; také on byl zničen a [všichni], kteří ho poslouchali, byli rozptýleni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Proto vám nyní pravím: Nechte tyto lidi a propusťte je. Je–li tento plán či toto dílo z lidí, zanikne;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'je–li však z Boha, nebudete je moci zničit -- abyste snad nakonec nebyli nalezeni jako ti, kdo bojují proti Bohu.“Poslechli ho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'zavolali apoštoly, zmrskali je a přikázali jim, aby nemluvili v Ježíšově jménu, a propustili je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Oni tedy šli z velerady a radovali se, že byli uznáni za hodné, aby byli potupeni pro to jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Každý den v chrámě a po domech nepřestávali učit a zvěstovat Krista Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'V těch dnech, kdy přibývalo učedníků, nastalo reptání Helénistů proti Hebreům, že při každodenní službě jsou jejich vdovy zanedbávány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Proto apoštolové -- oněch Dvanáct -- svolali veškeré množství učedníků a řekli: „Není správné, abychom my zanechali Božího slova a sloužili při stolech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Vyberte si tedy, bratři, mezi sebou sedm osvědčených mužů, plných Ducha [Svatého] a moudrosti, které ustanovíme pro tento úkol;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'my však se oddáme modlitbě a službě slova.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'To slovo se zalíbilo celému shromáždění, i vybrali Štěpána, muže plného víry a Ducha Svatého, Filipa, Prochora, Nikánora, Timóna, Parména a Mikuláše, proselytu z Antiochie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Postavili je před apoštoly, ti se pomodlili a vložili na ně ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Slovo Boží se šířilo a počet učedníků v Jeruzalémě velmi rostl. Také velký zástup kněží byl poslušný víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Štěpán, plný milosti a moci, činil mezi lidem veliké divy a znamení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Tu povstali někteří ze synagogy zvané Libertinských, Kyrénských a Alexandrijských, z Kilikie a Asie, a hádali se se Štěpánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Ale nemohli odolat moudrosti a Duchu, v němž mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Potom tajně navedli muže, kteří říkali: „Slyšeli jsme jej mluvit rouhavé výroky proti Mojžíšovi a proti Bohu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Tak pobouřili lid a starší i učitele Zákona, přišli, násilím se ho chopili a přivedli do velerady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'A postavili lživé svědky, kteří říkali: „Tento člověk nepřestává pronášet výroky proti [tomuto] svatému místu a proti Zákonu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Slyšeli jsme ho, jak říkal, že Ježíš Nazaretský zničí toto místo a změní obyčeje, která nám předal Mojžíš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'A všichni, kteří seděli ve veleradě, na něho upřeně hleděli a viděli, že jeho tvář je jako tvář anděla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Velekněz řekl: „Je tomu [skutečně] tak?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'A on začal mluvit: „Muži bratři a otcové, poslyšte: Bůh slávy se ukázal našemu otci Abrahamovi, když byl v Mezopotámii, dříve než se usadil v Cháranu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'a řekl mu: Vyjdi ze své země a ze svého příbuzenstva a jdi do země, kterou ti ukážu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Potom vyšel z Chaldejské země a usadil se v Cháranu. A odtud jej Bůh po smrti jeho otce přestěhoval do této země, ve které vy nyní bydlíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'A nedal mu v ní za dědictví ani píď země, ale slíbil ji dát do vlastnictví jemu a po něm jeho potomstvu, ačkoliv ještě neměl dítě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Bůh promluvil takto: Jeho potomci budou žít jako cizinci v cizí zemi; tam je zotročí a čtyři sta let s nimi budou zle nakládat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Ale národ, jemuž budou otročit, budu soudit já, řekl Bůh, a potom vyjdou a budou ⌈mi sloužit⌉ na tomto místě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'I dal mu smlouvu obřízky. A tak, když zplodil Izáka, osmý den ho obřezal; podobně i Izák obřezal Jákoba a Jákob dvanáct patriarchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Patriarchové žárlili na Josefa a prodali ho do Egypta; ale Bůh byl s ním,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'vysvobodil ho ze všech jeho soužení a dal mu milost i moudrost před faraonem, egyptským králem, a ten ho ustanovil vládcem nad Egyptem i [nad] celým svým domem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Potom přišel na ⌈celý Egypt⌉ i Kanaán hlad a veliké soužení, a naši otcové nenalézali obživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Když Jákob uslyšel, že v Egyptě je obilí, vyslal tam naše otce poprvé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Při druhé návštěvě se Josef dal svým bratřím poznat a Josefův rod se stal faraonovi známým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Josef poslal vzkaz a zavolal k sobě svého otce Jákoba a celé příbuzenstvo v počtu sedmdesáti pěti duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'A sestoupil Jákob do Egypta a zemřel on i naši otcové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Přenesli je do Sichemu a uložili v hrobce, kterou Abraham koupil za stříbro od synů ⌈Emorových v Sichemu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Jak se však přibližoval čas zaslíbení, které Bůh vyhlásil Abrahamovi, lid v Egyptě rostl a množil se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'dokud [v Egyptě] nepovstal jiný král, který Josefa neznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ten s naším rodem jednal lstivě a zle a přinutil [naše] otce odkládat své novorozence, aby nezůstávali naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'V té době se narodil Mojžíš a byl ⌈krásný před Bohem⌉. Tři měsíce byl chován v domě svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'A když ho odložili, vzala si jej faraonova dcera a starala se o něj jako o svého syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Mojžíš byl vychován ve vší egyptské moudrosti a byl mocný ve slovech i ve svých skutcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'A když se dovršoval jeho čtyřicátý rok, vstoupila mu na srdce myšlenka, aby se podíval na své bratry, syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'A uviděl, jak se jednomu z nich děje křivda; zastal se ho a pomstil utiskovaného tím, že Egypťana zabil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Domníval se, že [jeho] bratři pochopí, že jim Bůh dává skrze jeho ruku vysvobození, ale oni to nepochopili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Druhého dne se u nich objevil, když se hádali; snažil se je přivést k pokoji slovy: Muži, jste bratři, proč ubližujete jeden druhému?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Ale ten, který ubližoval svému bližnímu, ho odstrčil a řekl: Kdo tě ustanovil nad námi vládcem a soudcem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Snad mě nechceš zabít, jako jsi včera zabil toho Egypťana?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, '⌈Kvůli těm slovům⌉ Mojžíš utekl a bydlel jako cizinec v zemi madiánské, kde zplodil dva syny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'A když se dovršilo čtyřicet let, ukázal se mu v pustině u hory Sinaj [Pánův] anděl v plameni hořícího keře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Když to Mojžíš uviděl, divil se tomu vidění; šel blíž, aby se pozorně podíval, a tu zazněl Pánův hlas:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Já jsem Bůh tvých otců, Bůh Abrahamův, [Bůh] Izákův a [Bůh] Jákobův. Mojžíš se roztřásl a neodvažoval se podívat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Pán mu řekl: Zuj si z nohou sandály, neboť místo, na kterém stojíš, je země svatá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Dobře jsem viděl soužení svého lidu, který je v Egyptě, a slyšel jsem jejich sténání. I sestoupil jsem, abych je vysvobodil. A teď jdi, posílám tě do Egypta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Toho Mojžíše, kterého zavrhli, když řekli: Kdo tě [nad námi] ustanovil vládcem a soudcem?, toho Bůh poslal jako vůdce a vysvoboditele prostřednictvím anděla, který se mu ukázal v tom keři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Ten je vyvedl a činil divy a znamení v egyptské zemi, při Rudém moři i v pustině po čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'To je ten Mojžíš, který řekl synům Izraele: Bůh vám z vašich bratrů vzbudí proroka, tak jako mne. [Toho poslouchejte.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'To je ten, který byl ve shromáždění v pustině ⌈ prostředníkem mezi⌉ andělem, který k němu mluvil na hoře Sinaj, a našimi otci. On přijal živá slova, aby nám je dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Jemu se naši otcové nechtěli poddat, ale zavrhli ho a obrátili se ve svých srdcích do Egypta');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'a řekli Áronovi: Udělej nám bohy, kteří půjdou před námi, neboť nevíme, co se stalo s Mojžíšem, který nás vyvedl z egyptské země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'I udělali v těch dnech tele, přinesli té modle oběť a veselili se ze skutků svých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Bůh se od nich odvrátil a vydal je, aby sloužili nebeskému vojsku, jak je napsáno v knize Proroků: Což jste mně po těch čtyřicet let na pustině přinášeli krvavé oběti a dary, dome izraelský?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Nosili jste stánek Molocha a hvězdu [vašeho] boha Remfana, obrazy, které jste si udělali, abyste se jim klaněli. Přestěhuji vás až za Babylon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Naši otcové měli v pustině stánek svědectví, jak nařídil ten, jenž mluvil k Mojžíšovi, aby jej udělal podle vzoru, který uviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Ten také naši otcové převzali a vnesli s Jozuem do země pohanů, které Bůh zahnal před našimi otci. Tak to bylo až do dnů Davidových,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'který nalezl milost před Bohem a žádal, aby směl vyhledat příbytek pro Boha Jákobova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Teprve Šalomoun mu však vystavěl dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Ale Nejvyšší nebydlí v domech zhotovených lidskýma rukama, jak praví prorok:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Nebe je mým trůnem, země podnoží mých nohou. Jaký dům mi vystavíte, praví Pán, nebo jaké bude místo mého spočinutí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Což to všechno neučinila má ruka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Vy tvrdošíjní, vy lidé neobřezaného srdce i uší, stále vzdorujete Duchu Svatému; jak vaši otcové, tak i vy!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Kterého z proroků vaši otcové nepronásledovali? Zabili ty, kteří předpověděli příchod Spravedlivého; vy jste se nyní stali jeho zrádci a vrahy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'vy, kteří jste přijali Zákon ⌈skrze anděly⌉, ale nezachovali jste jej.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Když to slyšeli, běsnili ve svých srdcích a skřípali proti němu zuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Ale on, plný Ducha Svatého, upřeně pohlédl k nebi a spatřil Boží slávu a Ježíše, jak stojí po pravici Boží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'a řekl: „Hle, vidím nebesa rozevřená a Syna člověka, jak stojí po pravici Boží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Oni však vykřikli velikým hlasem, zacpali si uši a společně se na něho vrhli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Vyhnali ho ven z města a kamenovali. Svědkové odložili své pláště k nohám mladíka, který se jmenoval Saul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'A kamenovali Štěpána, který vzýval Pána a říkal: „Pane Ježíši, přijmi mého ducha.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Pak klesl na kolena a zvolal velikým hlasem: „Pane, nepočítej jim tento hřích.“Když to řekl, zesnul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saul souhlasil s jeho usmrcením. V ten den začalo veliké pronásledování církve, která byla v Jeruzalémě; všichni kromě apoštolů se rozprchli po území Judska a Samařska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Zbožnímuži Štěpána pochovali a velmi nad ním naříkali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saul ničil církev: vcházel do jednotlivých domů, odvlékal muže i ženy a dával je do vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ti tedy, kteří se rozprchli, procházeli zemí a zvěstovali slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Filip sestoupil ⌈do města Samaří⌉ a hlásal jim Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Zástupy jednomyslně věnovaly pozornost tomu, co Filip mluvil, když slyšely a viděly znamení, která činil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Neboť z mnoha těch, kteří měli nečisté duchy, tito duchové s velikým křikem vycházeli a mnoho ochrnutých a chromých bylo uzdraveno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'A v onom městě nastala veliká radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Ve městě však byl již dříve nějaký muž jménem Šimon, který provozoval magii a ohromoval samařský národ; říkal o sobě, že je někdo veliký.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Všichni od nejmenšího do největšího mu věnovali pozornost a říkali: „Tento člověk je ta moc Boží, která se nazývá Veliká.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Věnovali mu pozornost proto, že je dlouhý čas ohromoval svou magií.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Když však uvěřili Filipovi, který jim zvěstoval evangelium o Božím království a o jménu Ježíše Krista, dávali se pokřtít muži i ženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Dokonce sám Šimon uvěřil, byl pokřtěn a držel se Filipa. Když viděl, jak se dějí veliká znamení a mocné činy, velmi nad tím žasl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Když apoštolové v Jeruzalémě uslyšeli, že Samaří přijalo slovo Boží, poslali k nim Petra a Jana.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Oni tam sestoupili a pomodlili se za ně, aby dostali Ducha Svatého,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'neboť ještě na nikoho z nich nepadl; byli jen pokřtěni ve jméno Pána Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Potom na ně vkládali ruce a oni dostávali Ducha Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Když Šimon viděl, že se vkládáním rukou apoštolů dává Duch [Svatý], přinesl jim peníze');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'a řekl: „Dejte i mně tuto pravomoc, aby každý, na koho vložím ruce, dostal Ducha Svatého.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Petr mu řekl: „Tvé peníze kéž jsou zatraceny i s tebou, protože ses domníval, že lze ⌈Boží dar⌉ získat za peníze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, '⌈Na této věci⌉ nemáš podíl ani účast, neboť tvé srdce není upřímné před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Proto čiň pokání z této své špatnosti a popros Pána; snad ti úmysl tvého srdce bude odpuštěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Vidím, že jsi ⌈pln hořkosti⌉ a v poutu nepravosti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Šimon odpověděl: „Poproste vy za mne Pána, aby na mne nepřišlo nic z toho, o čem jste mluvili.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Oni se tedy, když vydali svědectví a domluvili ⌈Pánovo slovo,⌉ vraceli do Jeruzaléma a zvěstovali evangelium v mnoha samařských vesnicích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Pánův anděl promluvil k Filipovi: „Vstaň a jdi na jih k cestě, která sestupuje z Jeruzaléma do ⌈Gázy.“Ta cesta je pustá.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'I vstal a šel. A hle, muž z Etiopie, eunuch, dvořan kandaky, etiopské královny, který byl ⌈správcem celého⌉ jejího pokladu, se přijel poklonit Bohu do Jeruzaléma');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'a nyní se vracel. Seděl na svém voze a četl proroka Izaiáše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Duch řekl Filipovi: „Přistup a připoj se k tomuto vozu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Filip přiběhl a uslyšel, že čte proroka Izaiáše, i řekl: „Rozumíš tomu, co čteš?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'On řekl: „Jak bych mohl, když ⌈mi to nikdo nevysvětlí⌉?“A požádal Filipa, aby nastoupil a posadil se k němu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'To místo Písma, které četl, bylo toto: Byl veden jako ovce na porážku a jako je beránek němý před tím, kdo ho stříhá, tak neotevřel svá ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, '⌈Ve [svém] ponížení byl zbaven práva⌉. Kdo bude vyprávět o jeho pokolení? Vždyť jeho život je vzat ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Eunuch Filipovi řekl: „Prosím tě, o kom to prorok mluví? O sobě, či o někom jiném?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Tu Filip otevřel svá ústa, začal od tohoto místa Písma a zvěstoval mu Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Jak pokračovali v cestě, přišli k jakési vodě. Eunuch řekl: „Hle, voda. Co brání, abych byl pokřtěn?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '[Filip řekl: „ Jestliže věříš z celého srdce, je to dovoleno.“Odpověděl: „ Věřím, že Ježíš Kristus je Syn Boží.“]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Rozkázal zastavit vůz a oba, Filip i eunuch, sestoupili do vody, a Filip ho pokřtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Když vystoupili z vody, Pánův Duch uchopil Filipa a eunuch ho již nespatřil, ale pokračoval ve své cestě a radoval se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Filip ⌈se pak ocitl⌉ v Azótu. Procházel všechna města a zvěstoval evangelium, až přišel do Cesareje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Saul stále ještě soptil hrozbami a dychtil po zabíjení Pánových učedníků. Přišel k veleknězi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'a vyžádal si od něho dopisy pro synagogy v Damašku, aby mohl stoupence té Cesty, muže i ženy, jestliže tam nějaké najde, přivést spoutané do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'I stalo se, když byl na cestě a blížil se k Damašku, že ho náhle ozářilo světlo z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Padl na zem a uslyšel hlas, který mu říkal: „Saule, Saule, proč mne pronásleduješ?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Řekl: „Kdo jsi, Pane?“On [odpověděl]: „Já jsem Ježíš, kterého ty pronásleduješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, '[Těžko (je) ti vzpínat se proti bodcům.“(Saul) se třásl a děsil se. Řekl: „ Pane, co chceš, abych učinil?“A Pán mu (odpověděl): „] Vstaň, jdi do města a tam ti bude řečeno, co máš dělat.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Muži, kteří s ním cestovali, stáli oněmělí; slyšeli sice hlas, ale nikoho neviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saul vstal ze země, ale když otevřel oči, nic neviděl. Vzali ho za ruce a dovedli do Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Po tři dny neviděl, nejedl ani nepil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'V Damašku byl jeden učedník, jménem Ananiáš. Pán mu ve vidění řekl: „Ananiáši!“On řekl: „Zde jsem, Pane.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'A Pán mu řekl: „Vstaň a jdi do ulice, která se nazývá Přímá, a v Judově domě vyhledej Saula, jménem Tarského. Hle, právě se modlí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'a uviděl [ve vidění] muže jménem Ananiáš, který vešel a vložil na něho ruce, aby opět viděl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananiáš odpověděl: „Pane, slyšel jsem o tomto muži od mnohých lidí, kolik zla učinil tvým svatým v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Také zde má od velekněží plnou moc spoutat všechny, kteří vzývají tvé jméno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Pán mu řekl: „Jdi, neboť on je mou vyvolenou nádobou, aby přinesl mé jméno před národy i krále a syny Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Ukáži mu, co všechno musí vytrpětpro mé jméno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Ananiáš odešel, vstoupil do toho domu, vložil na něho ruce a řekl: „Bratře Saule, Pán, [Ježíš,] který se ti ukázal na cestě, kterou jsi sem šel, mě poslal, abys opět viděl a byl naplněn Duchem Svatým.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'A hned jako by mu s očí spadly šupiny, zase viděl, vstal a byl pokřtěn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Pak přijal pokrm a posilnil se. Několik dní byl s učedníky v Damašku');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'a hned v synagogách hlásal Ježíše, že on je Syn Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Všichni, kteří ho slyšeli, byli ohromeni a říkali: „Není to ten, který ničil v Jeruzalémě ty, kteří vzývají toto jméno? I sem přišel jen proto, aby je spoutané odvedl k velekněžím!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Ale Saul působil stále mocněji a svými důkazy, že tento Ježíš je Mesiáš, pobuřoval Židy, kteří bydleli v Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Když ⌈to trvalo už dost dlouho⌉, rozhodli se Židé, že ho zabijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Saul se však o jejich úkladech dověděl. Ve dne v noci pečlivě hlídali i brány, aby ho mohli zabít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Učedníci ho však v noci vzali, vysadili ho ⌈ otvorem ve zdi⌉ a spustili v koši dolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Když přišel do Jeruzaléma, pokoušel se připojit k učedníkům; ale všichni se ho báli, protože nevěřili, že je učedníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabáš se ho ujal, přivedl ho k apoštolům a vypravoval jim, jak na cestě uviděl Pána a že k němu mluvil a jak v Damašku otevřeně mluvil v Ježíšově jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'A byl s nimi, ⌈volně chodil⌉ po Jeruzalémě a otevřeně mluvil v Pánově jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Mluvil také s Helénisty a přel se s nimi, ale oni se ho pokoušeli zabít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Když se to bratři dozvěděli, odvedli jej dolů do Cesareje a vyslali do Tarsu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'A shromáždění v celém Judsku, Galileji a Samaří měla pokoj a budovala se; chodila v Pánově bázni a ⌈v povzbuzování Ducha Svatého, a tak vzrůstal jejich počet⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'I stalo se, když Petr procházel všechna ta místa, že sestoupil také ke svatým, kteří bydleli v Lyddě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Tam nalezl jednoho člověka, jménem Eneáš, který byl ochrnutý a byl již osm let upoutaný na lůžko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Petr mu řekl: „Eneáši, Ježíš Kristus tě uzdravuje! Vstaň a ustel si!“A on hned vstal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Viděli ho všichni obyvatelé Lyddy a Sáronu a obrátili se k Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'V Joppe byla nějaká učednice jménem Tabita, což v překladu zní Dorkas. Ta oplývala dobrými skutky a dáváním almužen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Stalo se, že v těch dnech onemocněla a zemřela. Umyli [ji] a položili do horního pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Protože Lydda je blízko Joppe, učedníci uslyšeli, že je tam Petr, a poslali k němu [dva muže] s prosbou: „Rychle přijď k nám!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Petr vstal a šel s nimi. Když tam přišel, zavedli ho do horního pokoje. I přistoupily k němu s pláčem všechny vdovy a ukazovaly mu košile a pláště, které Dorkas dělala, dokud byla s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Petr poslal všechny ven, klekl si a pomodlil se. Potom se obrátil k mrtvé a řekl: „Tabito, vstaň!“Ona otevřela oči, a když uviděla Petra, posadila se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Podal jí ruku a pozdvihl ji. Pak zavolal svaté a vdovy a ukázal jim ji živou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'To se stalo známým v celém Joppe, a mnozí uvěřili v Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'A stalo se, že Petr zůstal v Joppe více dní u nějakého Šimona koželuha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'V Cesareji žil nějaký muž jménem Kornélius, setník pluku zvaného Italský,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'člověk zbožný, který se bál Boha s celým svým domem, ⌈dával mnoho almužen⌉ lidu a stále se modlil k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Kolem ⌈třetí hodiny odpoledne⌉ spatřil jasně ve vidění Božího anděla, jak k němu vešel a řekl mu: „Kornélie!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Pozorně na něho pohlédl, ulekl se a řekl: „Co je, Pane?“Anděl mu řekl: „Tvé modlitby a tvé almužny vystoupily, jako připomínka před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Pošli nyní muže do Joppe a pozvi [jistého] Šimona, který se nazývá Petr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Ten je hostem u nějakého Šimona koželuha, který má dům u moře.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Když anděl, který k němu mluvil, odešel, zavolal si dva ze svých domácích sluhů a zbožného vojáka, jednoho z těch, kteří zůstávali věrně při něm,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'všechno jim vysvětlil a poslal je do Joppe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Druhého dne, když oni byli na cestě a blížili se k městu, vystoupil Petr na střechu domu, aby se kolem poledne pomodlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Dostal hlad a chtěl se najíst. Zatímco mu připravovali jídlo, ocitl se ve vytržení:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'vidí otevřené nebe, z nějž [k němu] sestupuje jakási nádoba jako veliká plachta, za čtyři rohy [svázaná a] spouštěná k zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'V ní byli všichni čtvernožci, [dravá zvěř,] zemští plazi i nebeští ptáci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'I zazněl k němu hlas: „Vstaň, Petře, zabíjej a jez!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Petr řekl: „Ne, Pane! Nikdy jsem nejedl nic poskvrněného a nečistého!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'A opět k němu hlas zazněl podruhé: „Co Bůh očistil, ty nepokládej za poskvrněné!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'To se stalo třikrát a [hned] byla ta nádoba [zase] vzata vzhůru do nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Zatímco byl Petr na rozpacích, co by to vidění, které spatřil, mohlo znamenat, hle, muži poslaní Kornéliem se doptali na Šimonův dům a dorazili k bráně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'zavolali a vyptávali se, je–li tu hostem Šimon zvaný Petr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Když Petr přemýšlel o tom vidění, Duchmu řekl: „Hle, [tři] muži tě hledají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Vstaň, sestup a jdi bez pochybování s nimi, neboť já jsem je poslal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Petr tedy sešel dolů k těm mužům a řekl: „Hle, já jsem ten, kterého hledáte. Co je důvodem vašeho příchodu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Oni řekli: „Setník Kornélius, muž spravedlivý, který se bojí Boha a o němž celý židovský národ vydává dobré svědectví, dostal pokyn od svatého anděla, aby tě pozval do svého domu a vyslechl tvá slova.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Pozval je tedy dovnitř a pohostil je. Druhého dne vstal a vyšel s nimi, i někteří bratři z Joppe šli s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Nazítří vešli do Cesareje. Kornélius je očekával; svolal své příbuzné a nejbližší přátele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Když Petr vstupoval, Kornélius mu vyšel vstříc, padl k jeho nohám a poklonil se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Petr ho pozdvihl a řekl: „Vstaň! Vždyť i já jsem jen člověk.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Za hovoru s ním vešel dovnitř a nalezl tam mnoho shromážděných lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'I řekl jim: „Vy víte, jak nezákonné je pro židovského muže připojovat se k člověku z jiného národa nebo ho navštěvovat. Ale mně Bůh ukázal, abych žádného člověka nepokládal za poskvrněného nebo nečistého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Proto jsem také bez odmluvy přišel, když jsem byl pozván. Ptám se tedy, z jakého důvodu jste mne pozvali.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'A Kornélius odpověděl: „Před čtyřmi dny [jsem se postil] do této hodiny [a o] deváté [hodině] jsem se modlil ve svém domě, a hle, přede mnou stál muž v zářivém rouchu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'a řekl: Kornélie, tvá modlitba byla vyslyšena a tvé skutky milosrdenství byly vzpomenuty před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Pošli tedy do Joppe a povolej Šimona, který je nazýván Petr; ten je hostem v domě Šimona koželuha u moře. [On přijde a bude k tobě mluvit].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Hned jsem tedy pro tebe poslal a ty jsi dobře učinil, že jsi přišel. Nyní tedy my všichni jsme tu před Bohem, abychom vyslechli vše, co ti bylo od Boha nařízeno.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Petr otevřel ústa a řekl: „Opravdu nyní chápu, že Bůh ⌈nikomu nestraní⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'ale v každém národě je mu milý ten, kdo se ho bojí a činí spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'To je slovo, [které] poslal synům Izraele, když zvěstoval pokoj skrze Ježíše Krista -- on je Pánem všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vy sami víte o tom, co se dálo po celém Judsku, počínajíc Galileou, po křtu, který hlásal Jan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Jak Bůh pomazal Duchem Svatým a mocí Ježíše, toho z Nazareta, jenž procházel zemí, činil dobře a uzdravoval všechny, kteří trpěli pod mocí Ďábla, protože Bůh byl s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'My jsme svědky všeho, co učinil v té krajině Židů a v Jeruzalémě. A oni ho pověsili na dřevo a zabili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Bůh jej však třetího dne probudil z mrtvých a dal mu zjevit se;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'ne všemu lidu, ale svědkům předem Bohem určeným, nám, kteří jsme s ním po jeho vzkříšení z mrtvých jedli a pili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'A nařídil nám, abychom lidu vyhlásili a dosvědčili, že on je ten Bohem ustanovený soudce živých i mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Jemu všichni proroci vydávají svědectví, že skrze jeho jméno přijme odpuštění hříchů každý, kdo v něho věří.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Ještě když Petr říkal tato slova, padl Duch Svatý na všechny, kteří tu řeč slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'A ⌈věřící ze Židů⌉, kteří přišli s Petrem, byli ohromeni tím, že i na pohany byl vylit dar Ducha Svatého,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'neboť je slyšeli mluvit jazyky a velebit Boha. Potom Petr prohlásil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '„Může někdo odepřít vodu, aby nebyli pokřtěni ti, kteří přijali Ducha Svatého [tak] jako my?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'A nařídil, aby byli pokřtěni ve jménu ⌈Ježíše Krista⌉. Potom ho poprosili, aby s nimi zůstal několik dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Apoštolové a bratři, kteří byli v Judsku, uslyšeli, že také pohané přijali slovo Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Když Petr vystoupil do Jeruzaléma, věřící ze Židů mu vytýkali:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, '„Vešel jsi k mužům neobřezaným a jedl jsi s nimi!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Petr jim to začal po pořádku vysvětlovat:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '„Byl jsem v městě Joppe a modlil jsem se. A tu jsem ve vytržení spatřil vidění: jakousi nádobu, která sestupovala jako veliká plachta, spouštěná za čtyři rohy z nebe, a přišla až ke mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Když jsem se do ní pozorně zahleděl a pozoroval ji, uviděl jsem zemské čtvernožce i dravou zvěř, plazy a nebeské ptáky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Uslyšel jsem také hlas, který mi říkal: Vstaň, Petře, zabíjej a jez!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Řekl jsem: Ne, Pane, neboť do mých úst nikdy nevešlo nic poskvrněného nebo nečistého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Ale hlas z nebe mi odpověděl podruhé: Co Bůh očistil, ty neměj za poskvrněné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'To se stalo třikrát a vše bylo opět vyzdviženo do nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'A hle, v tu chvíli dorazili k domu, ve kterém jsem byl, tři muži poslaní ke mně z Cesareje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Duch mi řekl, abych šel bez pochybování s nimi. Šlo se mnou také těchto šest bratrů a vstoupili jsme do domu toho muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Oznámil nám, jak uviděl ve svém domě anděla, který stanul před ním a řekl [mu]: Pošli do Joppe a pozvi Šimona, který se nazývá Petr;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'ten ti poví ⌈slova, jimiž⌉ budeš zachráněn ty i celý tvůj dům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Když jsem začal mluvit, padl na ně Duch Svatý, jako i na nás na počátku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Vzpomněl jsem si na Pánův výrok, jak říkal: Jan křtil vodou, ale vy budete pokřtěni v Duchu Svatém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Jestliže jim tedy Bůh dal stejný dar jako nám, když uvěřili v Pána -- Ježíše Krista, kdo jsem já, abych směl překážet Bohu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Když to uslyšeli, utichli a vzdali slávu Bohu; řekli: „Tedy i pohanům dal Bůh pokání k životu!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Ti, kteří se rozprchli před soužením, které nastalo kvůli Štěpánovi, prošli až do Fénicie, na Kypr a do Antiochie; nikomu nehlásali slovo Boží, jen Židům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Někteří z nich byli muži z Kypru a z Kyrény; ti přišli do Antiochie a mluvili i k Helénistům a zvěstovali jim Pána Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'A Pánova ruka byla s nimi; veliký počet lidí uvěřil a obrátil se k Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Zpráva o nich se donesla k sluchu církve v Jeruzalémě, i vyslali Barnabáše, [aby prošel] až do Antiochie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Když tam přišel a uviděl tu Boží milost, zaradoval se a povzbuzoval všechny, aby ⌈ s rozhodným srdcem⌉ zůstávali u Pána;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'neboť to byl dobrý muž, plný Ducha Svatého a víry. A značný zástup se přidal k Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Pak odešel do Tarsu vyhledat Saula,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'a když ho našel, přivedl ho do Antiochie. Stalo se, že celý rok zůstali v společenství církve a vyučili značný zástup; a v Antiochii byli učedníci poprvé nazváni křesťany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'V těch dnech sestoupili z Jeruzaléma do Antiochie proroci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Jeden z nich, jménem Agabos, povstal a naznačil skrze Ducha, že nastane veliký hlad po celém světě; ten skutečně nastal za Klaudia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Proto si všichni učedníci určili, každý podle svých možností, co pošlou ku pomoci bratřím bydlícím v Judsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Také to učinili a sbírku poslali starším prostřednictvím Barnabáše a Saula.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'V té době král Herodes vztáhl ruce, aby ublížil některým z církve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Janova bratra Jakuba zabil mečem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Když viděl, že se to Židům líbí, pokračoval a zmocnil se také Petra. Byly právě dny nekvašených chlebů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Zatkl ho, dal jej do vězení a svěřil ho čtyřem čtveřicím vojáků, aby ho hlídali. Po velikonocích ho chtěl předvést před lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Petr byl tedy střežen ve vězení a církev se za něho vytrvale modlila k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Noc předtím, než jej Herodes hodlal předvést, spal Petr mezi dvěma vojáky, spoután dvěma řetězy, a stráže přede dveřmi hlídaly vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'A hle, Pánův anděl se u něho postavil a v cele zazářilo světlo. Udeřil Petra do boku, vzbudil ho a řekl: „Rychle vstaň!“A řetězy mu spadly s rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'A anděl mu řekl: „Opásej se a obuj si sandály.“On tak učinil. I říká mu: „Obleč si plášť a pojď za mnou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Vyšel a šel za ním, ale nevěděl, že to, co se skrze anděla děje, je skutečné; myslel si, že má vidění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Prošli přes první i druhou stráž, přišli k železné bráně, která vedla do města; ta se jim sama od sebe otevřela. I vyšli, prošli jednou ulicí a náhle od něho anděl odstoupil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Petr se vzpamatoval a řekl: „Teď opravdu vím, že Pán vyslal svého anděla a vysvobodil mě z Herodovy ruky a ze všeho, co židovský lid očekával.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Když si to uvědomil, přišel k domu Marie, matky Jana zvaného Marek, kde byli mnozí shromážděni a modlili se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Zabouchal na dveře brány a přišla otevřít služka jménem Rodé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'A když poznala Petrův hlas, radostí ani neotevřela bránu, ale vběhla dovnitř a oznámila, že Petr stojí před branou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Ale oni jí řekli: „Blázníš!“Ona však tvrdila, že je tomu tak. Oni říkali: „Je to jeho anděl.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Ale Petr nepřestával tlouci. Když otevřeli a spatřili ho, byli ohromeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Pokynul jim rukou, aby mlčeli, a vypravoval jim, jak ho Pán vyvedl z vězení; nakonec řekl: „Oznamte to Jakubovi a bratřím.“Pak vyšel a odebral se na jiné místo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Když nastal den, byl mezi vojáky [nemalý] rozruch nad tím, co se stalo s Petrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Herodes ho hledal a nenalezl, vyslechl stráže a rozkázal je odvést k popravě. Potom sestoupil z Judska do Cesareje a pobýval tam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Herodes se velmi hněval na Týrské a Sidónské. Ti přišli jednomyslně k němu, přesvědčili Blasta, který byl královským komorníkem, a prosili o mír, protože jejich krajina byla zásobována potravinami z jeho královského území.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Ve stanovený den se Herodes, oděn královským rouchem, posadil na řečnické podium a začal k nim mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Lid volal: „ To je hlas Boží, a ne lidský!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'A ihned jej udeřil Pánův anděl za to, že nevzdal slávu Bohu: byl rozežrán červy a zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'A slovo Boží rostlo a rozmáhalo se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabáš a Saul splnili svou službu, vrátili se z Jeruzaléma a vzali s sebou [i] Jana příjmením Marka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'V Antiochii byli v místní církvi proroci a učitelé, [jako] Barnabáš, Šimon zvaný Černý, Lucius Kyrénský, Manahen, společně vychovaný s tetrarchou Herodem, a Saul.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Když konali službu Pánu a postili se, řekl Duch Svatý: „Oddělte mi Barnabáše a Saula k dílu, k němuž jsem je povolal.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Potom, po postu a modlitbách, na ně vložili ruce a propustili je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Oni tedy, vysláni Duchem Svatým, sestoupili do Seleukie a odtamtud odpluli na Kypr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Když dorazili do Salaminy, zvěstovali Boží slovo v židovských synagogách. Měli s sebou i Jana jako pomocníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Když prošli celým ostrovem až do Páfu, nalezli jakéhosi muže, kouzelníka, falešného proroka, Žida jménem Barjezus,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'který byl u místodržitele Sergia Paula, muže rozumného. Ten si zavolal Barnabáše a Saula, protože chtěl ⌈slyšet Boží slovo.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Avšak Elymas, ten kouzelník -- tak se totiž překládá jeho jméno -- se začal stavět proti nim a snažil se odvrátit místodržitele od víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Saul, jehož nazývali také Pavel, byl naplněn Duchem Svatým, upřeně na něho pohlédl');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'a řekl: „Ó, ty plný vší lsti a každé ničemnosti, synu Ďáblův, nepříteli každé spravedlnosti, což nepřestaneš převracet přímé Pánovy cesty?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'A nyní, hle, Pánova ruka je proti tobě, budeš slepý a neuvidíš slunce až do daného času.“Ihned na něj padla mrákota a tma, tápal kolem sebe a hledal, kdo by ho vedl za ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Když místodržitel uviděl, co se stalo, uvěřil, pln zděšení nad Pánovým učením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, '⌈Pavel a jeho společníci⌉ vypluli z Páfu a přišli do Pergy v Pamfylii. Ale Jan se od nich oddělil a vrátil se do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Od Perge šli dál a dorazili do Pisidské Antiochie. V sobotní den vešli do synagogy a posadili se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Po čtení ze Zákona a Proroků jim představení synagogy vzkázali: „Muži bratři, máte–li nějaké slovo povzbuzení pro lid, mluvte.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Pavel vstal, pokynul rukou a řekl: „Muži Izraelci a vy, kdo se bojíte Boha, poslyšte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Bůh tohoto izraelského lidu si vyvolil naše otce, vyvýšil tento lid během pobytu v egyptské zemi a vyvedl je z ní vztaženou paží;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'po dobu asi čtyřiceti let snášel jejich chování na poušti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'a když vyhladil sedm národů v kanaánské zemi, dal jim jejich zemi za dědictví;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, '⌈ to vše trvalo asi čtyři sta padesát let. Potom jim dával⌉ soudce až do proroka Samuele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Pak žádali o krále, a Bůh jim dal Saula, syna Kíšova, muže z kmene Benjamínova, na čtyřicet let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'A když ho odstranil, vzbudil jim za krále Davida, o němž vydal svědectví: Nalezl jsem Davida, syna Jišajova, muže podle mého srdce, který bude činit všechnu mou vůli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Z jeho semene přivedl Bůh Izraeli podle zaslíbení zachránce, Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, '⌈Před jeho příchodem⌉ Jan předem hlásal křest pokání všemu lidu Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'A když Jan dokončoval svůj běh, říkal: Já nejsem ten, za koho mne pokládáte; ale hle, za mnou přichází ten, jemuž nejsem hoden rozvázat sandály na nohou. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, '„Muži bratři, synové rodu Abrahamova, i vy, kteří se u vás bojíte Boha, nám bylo posláno slovo ⌈této záchrany⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Neboť obyvatelé Jeruzaléma ani jejich vůdcové ho nepoznali, odsoudili ho, a tak naplnili slova Proroků, která se čtou každou sobotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'A ačkoli na něm nenalezli žádný důvod pro trest smrti, žádali Piláta, aby byl popraven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Když dokonali všechno, co je o něm napsáno, sňali jej z dřeva a položili do hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Ale Bůh ho probudil z mrtvých');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'a on se po mnoho dní zjevoval těm, kteří s ním vystoupili z Galileje do Jeruzaléma; ti jsou nyní jeho svědky před lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'A my vám hlásáme radostnou zvěst, že to zaslíbení, které ⌈dostali naši otcové⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'splnil Bůh nám, jejich dětem, když vzkřísil z mrtvých Ježíše, jak je to i napsáno v druhém Žalmu: Ty jsi můj Syn, já jsem tě dnes zplodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'A to, že jej vzkřísil z mrtvých, aby se již více nenavracel do zkázy, řekl takto: Dám vám svaté a věrné věci Davidovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Proto i na jiném místě praví: Nedáš svému Svatému uvidět zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'David totiž, když posloužil vlastnímu pokolení ⌈Boží vůlí, usnul⌉, byl připojen ke svým otcům a uviděl zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Ten však, kterého Bůh vzkřísil z mrtvých, neuviděl zkázu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Budiž vám tedy známo, muži bratři, že skrze něho se vám zvěstuje odpuštění hříchů. Od všeho, od čeho jste nemohli být ospravedlněni v zákoně Mojžíšově,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'je v něm ospravedlňován každý, kdo věří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Střezte se proto, aby [na vás] nepřišlo to, co je řečeno v Prorocích:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Pohleďte tedy vy, kteří mnou pohrdáte, užasněte a zmizte, protože já ve vašich dnech u činím skutek, skutek, jemuž jistě neuvěříte, když vám o něm bude někdo vypravovat. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Když vycházeli [ze synagogy], prosili je, aby jim o tom pověděli i příští sobotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Když bylo shromáždění rozpuštěno, mnozí z Židů a zbožných proselytů se vydali za Pavlem a Barnabášem, kteří s nimi mluvili a přesvědčovali je, aby zůstávali v Boží milosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Příští sobotu se shromáždilo téměř celé město, aby vyslechlo Pánovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Když Židé uviděli zástupy, byli naplněni žárlivostí a začali tomu, co Pavel říkal, odporovat a rouhat se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Pavel a Barnabáš směle řekli: „Vám mělo být hlásáno Boží slovo nejprve. Protože je odmítáte a nepovažujete se za hodné věčného života, hle, obracíme se k pohanům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Neboť tak nám nařídil Pán: Ustanovil jsem tě za světlo pohanům, abys byl k záchraně až na konec země. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Když to pohané slyšeli, radovali se a oslavovali Pánovo slovo a uvěřili všichni, kteří byli určeni k věčnému životu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'A Pánovo slovo se šířilo po celé krajině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Židé však poštvali vážené zbožné ženy a přední muže města, podnítili pronásledování proti Pavlovi a Barnabášovi a vyhnali je od svých hranic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Oni proti nim vytřásli prach z nohou a přišli do Ikonia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'A učedníci byli stále naplňováni radostí a Duchem Svatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Stalo se, že rovněž v Ikoniu vešli do židovské synagogy a promluvili tak, že uvěřil četný zástup Židů i Řeků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Ale Židé, kteří neuvěřili, podnítili a rozezlili duše pohanů proti bratřím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Strávili tam tedy značný čas, otevřeně mluvili o Pánu, který dosvědčoval slovo své milosti tím, že dával, aby se skrze jejich ruce dála znamení a divy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Obyvatelstvo města se rozdělilo: jedni byli při Židech, druzí při apoštolech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Když se je pohané a Židé se svými vůdci pokusili potupit a ukamenovat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'oni se to dozvěděli a utekli do lykaonských měst Lystry a Derbe a okolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'I tam hlásali evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'V Lystře sedával nějaký muž nemohoucí na nohy, který byl chromý již od lůna své matky a nikdy nechodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Ten slyšel Pavla mluvit. Pavel se na něho upřeně podíval, a když uviděl, že má víru, aby byl zachráněn,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'řekl silným hlasem: „Postav se zpříma na nohy!“A on vyskočil a začal chodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Když zástupy uviděly, co Pavel učinil, pozdvihly svůj hlas a říkaly lykaonsky: „Bohové se připodobnili lidem a sestoupili k nám.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Barnabáše nazývali Diem, Pavla pak Hermem, protože on byl hlavním mluvčím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Kněz Diova chrámu, který stál před městem, přivedl býky s věnci k branám a chtěl je se zástupy obětovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Když to apoštolové Barnabáš a Pavel uslyšeli, roztrhli svá roucha, vběhli do zástupu a křičeli:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, '„Muži, co to děláte? I my jsme lidé ⌈stejné přirozenosti⌉ jako vy. Hlásáme vám evangelium, abyste se od těchto marností obrátili k živému Bohu, který učinil nebe, zemi, moře a všechno, co je v nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Ten v minulých pokoleních nechal všechny národy chodit po jejich cestách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'ačkoliv nepřestal sám sebe dosvědčovat tím, že činil dobro: dával vám z nebe déšť i úrodná období, vaše srdce sytil pokrmem a radostí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'A těmito slovy jen stěží zadrželi zástupy, aby jim neobětovaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Z Antiochie a Ikonia však přišli Židé, přemluvili zástupy a Pavla ukamenovali. Pak ho vlekli ven z města, protože mysleli, že je mrtev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Ale když ho učedníci obstoupili, vstal a vešel do města. Druhého dne vyšel s Barnabášem do Derbe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Když onomu městu oznámili evangelium a získali dosti učedníků, vrátili se do Lystry, Ikonia a Antiochie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Upevňovali duše učedníků, povzbuzovali je, aby setrvávali ve víře; říkali, že musíme skrze mnohá soužení vejít do Božího království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'V každém sboru jim ustanovili starší a v modlitbách s posty je svěřili Pánu, v něhož uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Prošli Pisidií a přišli do Pamfylie,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'mluvili Slovo v Perge a pak sestoupili do Attalie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Odtamtud odpluli do Antiochie, kde byli kdysi svěřeni Boží milosti k dílu, které nyní dokončili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Když tam přišli a shromáždili církev, vypravovali, co všechno Bůh s nimi učinil a jak pohanům otevřel dveře víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'A strávili s učedníky delší čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Tu sestoupili někteří z Judska a začali bratry učit: „Nebudete–li obřezáni podle Mojžíšova obyčeje, nemůžete být zachráněni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Když se s nimi Pavel a Barnabáš dostali do sporu a velké hádky, stanovili, že Pavel, Barnabáš a někteří další z nich vystoupí k apoštolům a starším do Jeruzaléma a budou o této sporné otázce jednat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Vypraveni tedy církví, procházeli Fénicií a Samařskem, vyprávěli o obrácení pohanů a všem bratrům působili velikou radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Když přišli do Jeruzaléma, byli přijati církví, apoštoly a staršími a oznámili, co všechno s nimi Bůh učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Tu povstali někteří, kteří uvěřili ze strany farizeů, a říkali, že se pohané musí obřezávat a musí se jim nařizovat, aby zachovávali Mojžíšův zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Apoštolové a starší se shromáždili, aby tu věc prozkoumali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Když došlo k velkému sporu, povstal Petr a řekl jim: „Muži bratři, víte, že si mě Bůh odedávna mezi vámi vyvolil, aby skrze má ústa pohané uslyšeli slovo evangelia a uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'A Bůh, jenž zná lidská srdce, jim vydal svědectví, když jim dal Ducha Svatého tak jako i nám');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'a neučinil žádného rozdílu mezi námi a jimi, když vírou očistil jejich srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Proč tedy nyní pokoušíte Boha a chcete vložit na šíji učedníků jho, které nebyli schopni unést ani naši otcové ani my?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Ale věříme, že jsme zachráněni milostí Pána Ježíše stejně jako oni. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Celé shromáždění utichlo a poslouchalo Barnabáše a Pavla, kteří podrobně vypravovali, jaká znamení a divy učinil Bůh skrze ně mezi pohany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Když domluvili, řekl Jakub: „Muži bratři, poslyšte mne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Šimon pověděl, jak se Bůh předem postaral, aby z pohanů vybral lid pro své jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'A s tím se shodují slova proroků, neboť je napsáno:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Potom se vrátím a znovu postavím Davidův zbořený stánek, jeho trosky znovu vystavím a vztyčím jej,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'aby i ostatní lidé horlivě hledali Pána, všechny národy, ⌈nad nimiž je vzýváno moje jméno,⌉ praví Pán, [ten,] který toto ⌈činí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Známé jsou Bohu jeho skutky od pradávna. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Proto soudím, abychom nedělali potíže těm, kteří se z pohanů obracejí k Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'ale napsali jim, aby se zdržovali toho, co bylo poskvrněno modloslužbou, smilstva, zardoušeného a krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Neboť Mojžíš má ode dávných pokolení v každém městě své hlasatele v synagogách, kde bývá čten každou sobotu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Potom apoštolové a starší s celou církví usoudili, že s Pavlem a Barnabášem pošlou do Antiochie muže, které mezi sebou vybrali. Poslali Judu zvaného Barsabáš a Silase, přední muže mezi bratřími.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, '⌈Po nich poslali tento list⌉: „Apoštolové a starší⌈, vaši bratři,⌉ bratřím z pohanů v Antiochii, Sýrii a Kilikii pozdrav.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Doslechli jsme se, že vás někteří, [kteří vyšli] z nás, zneklidnili svými slovy a zmátli vaše duše, [když říkali, že je třeba dát se obřezat a zachovávat Zákon,] ačkoliv jsme jim to nenařídili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Došli jsme k jednomyslnosti a usoudili jsme, že vybereme muže, které k vám pošleme s našimi milovanými Barnabášem a Pavlem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'lidmi, kteří nasadili ⌈svůj život⌉ pro jméno našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Posíláme tedy Judu a Silase a oni vám totéž oznámí ústně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Neboť tak usoudil Duch Svatý i my, že nebudeme na vás klást žádné jiné břemeno než tyto nezbytnosti:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'zdržovat se masa obětovaného modlám, krve, masa zardoušených zvířat a smilstva. Jestliže se těchto věcí budete chránit, dobře uděláte. Buďte zdrávi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Byli tedy propuštěni a sestoupili do Antiochie; tam shromáždili množství věřících a odevzdali jim dopis.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Když jej přečetli, zaradovali se z toho povzbuzení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Juda a Silas, kteří sami také byli proroky, mnohým slovem povzbudili a posílili bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Zůstali tam nějaký čas; potom je bratři s pokojem propustili k těm, kteří je poslali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '[Silas se však rozhodl zůstat.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Pavel a Barnabáš zůstali v Antiochii, učili a s mnohými jinými zvěstovali Pánovo slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Po několika dnech řekl Pavel Barnabášovi: „Vraťme se a navštivme bratry ve všech městech, ve kterých jsme zvěstovali Pánovo slovo, a zjistěme, jak se mají.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabáš chtěl vzít s sebou také Jana, nazývaného Marek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Pavel však nepokládal za správné brát ho s sebou, protože se v Pamfylii od nich odloučil a nešel s nimi do díla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Vznikla z toho ostrá hádka, takže se od sebe oddělili. Barnabáš vzal s sebou Marka a vyplul na Kypr.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Pavel si vybral Silase, a když ho bratři svěřili Pánově milosti, vyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Procházel Sýrií a Kilikií a posiloval církve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Přišel [také] do Derbe a do Lystry. A hle, byl tam jeden učedník jménem Timoteus, syn věřící židovské ženy, jeho otec byl však Řek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Bratři v Lystře a Ikonii o něm vydávali dobré svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Pavel chtěl, aby se s ním ⌈vydal na cestu⌉; vzal jej a obřezal kvůli Židům, kteří byli v oněch místech, neboť všichni věděli, že jeho otec byl Řek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Když procházeli městy, předávali jim ustanovení, na nichž se usnesli apoštolové a starší v Jeruzalémě, aby je zachovávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'A tak se sbory upevňovaly ve víře a denně početně rostly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Potom prošli Frygií a galatskou krajinou, neboť Duch Svatý jim zabránil promluvit Slovo v Asii.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Když přišli k Mysii, pokoušeli se dostat do Bithynie, ale [Ježíšův] Duch jim to nedovolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Prošli tedy Mysii a sestoupili do Troady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'V noci se ukázalo Pavlovi vidění: stál před ním nějaký makedonský muž a prosil ho: „Přejdi do Makedonie a pomoz nám!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Jak uviděl to vidění, hned jsme se snažili vyjít do Makedonie, protože jsme nabyli přesvědčení, že nás Bůh povolal, abychom jim zvěstovali evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Vypluli jsme z Troady a plavili se přímo na Samothráké, druhého dne do Neapole,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'odtamtud do Filip, které jsou předním městem této části Makedonie a římskou kolonií. V tomto městě jsme s trávili několik dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'V sobotní den jsme vyšli za bránu podél řeky, kde jsme se domnívali, že je místo k modlitbě; usedli jsme a mluvili k ženám, které se tam sešly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'A poslouchala nás jedna žena jménem Lydie, prodavačka purpuru z města Thyatir, která uctívala Boha. Pán jí otevřel srdce, aby věnovala pozornost tomu, co Pavel říkal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Když byla pokřtěna ona i její dům, poprosila nás: „Jestliže jste mne uznali za věrnou Pánu, vejděte do mého domu a zůstaňte.“A přinutila nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Stalo se, když jsme se šli modlit, že nás potkala nějaká otrokyně, která měla věšteckého ducha a věštěním přinášela svým pánům značný zisk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ta chodila za Pavlem a za námi a křičela: „Tito lidé jsou otroci Boha Nejvyššího, kteří vám zvěstují cestu záchrany.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'A to dělala po mnoho dní. Pavla to rozhořčilo, obrátil se na toho ducha a řekl: „Přikazuji ti ve jménu Ježíše Krista, abys od ní odešel!“A v tu chvíli od ní odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Když její páni uviděli, že jim ušla naděje na zisk, chopili se Pavla a Silase a vlekli je na náměstí k představeným města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Předvedli je před velitele a řekli: „Tito lidé pobuřují naše město. Jsou to Židé');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'a šíří zvyky, které my nesmíme přijímat ani zachovávat, protože jsme Římané.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Také zástup proti nim povstal a velitelé z nich strhli šaty a poroučeli je bít holí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Když jim vysázeli mnoho ran, uvrhli je do vězení a žalářníkovi nařídili, aby je bezpečně hlídal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Když dostal takový příkaz, uvrhl je do vnitřního vězení a pro jistotu jim dal nohy do klády.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Kolem půlnoci se Pavel a Silas modlili a zpěvem oslavovali Boha a ostatní vězňové je poslouchali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Náhle nastalo veliké zemětřesení, takže se otřásly základy vězení. Rázem se otevřely všechny dveře a všem se uvolnila pouta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Když se žalářník probudil a uviděl otevřené dveře vězení, vytasil meč a chtěl se zabít, protože myslel, že vězňové uprchli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Ale Pavel zvolal silným hlasem: „Neudělej si nic zlého! Jsme tu všichni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Žalářník požádal o světlo, vtrhl dovnitř a s třesením padl před Pavla a Silase.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Vyvedl je ven a řekl: „Páni, co mám dělat, abych byl zachráněn?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Oni řekli: „Uvěř v Pána Ježíše, a budeš zachráněn ty i tvůj dům.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'A promluvili Pánovo slovo k němu i ke všem, kteří byli v jeho domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'I ujal se jich v tu noční hodinu, vymyl jim rány a hned se dal pokřtít on i všichni jeho domácí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Pak je zavedl do domu, prostřel stůl a s celým svým domem se radoval, že uvěřil Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Když nastal den, poslali velitelé ozbrojenou stráž ⌈se vzkazem⌉: „Propusť ty lidi!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Žalářník oznámil tento vzkaz Pavlovi: „Velitelé vzkázali, abyste byli propuštěni. Proto vyjděte a jděte v pokoji.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Ale Pavel jim řekl: „Nás, římské občany, bez soudu veřejně zbili a uvrhli do vězení, a nyní nás tajně vyhánějí? To ne, jen ať sami přijdou a vyvedou nás!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Stráž oznámila tyto výroky velitelům. Ti se ulekli, když uslyšeli, že jsou Římané,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'přišli a omluvili se, vyvedli je a prosili, aby odešli z města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Vyšli z vězení a vešli k Lydii, uviděli bratry, povzbudili je a odešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Procestovali Amfipolis a Apollonii a přišli do Tesaloniky, kde byla židovská synagoga.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Podle svého zvyku k nim Pavel vstoupil a po tři soboty k nim mluvil na základě Písem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Vysvětloval a předkládal jim, že Mesiáš musel trpět a vstát z mrtvých a že „Ježíš, kterého já vám zvěstuji, to je ten Mesiáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Někteří z nich se dali přesvědčit a připojili se k Pavlovi a Silasovi, také velké množství Řeků, kteří uctívali Boha, a nemálo předních žen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Židé si však, zachváceni žárlivostí, přibrali několik ničemných mužů z tržiště, vyvolali srocení davu a pobouřili město; napadli Jásonův dům a snažili se je předvést před lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Když je nenalezli, vlekli Jásona a několik bratří k představeným města a křičeli: „Ti, kteří pobouřili celý svět, přišli také sem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'a Jáson je hostí. Ti všichni jednají proti císařovýmustanovením, neboť říkají, že králem je někdo jiný: Ježíš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Zneklidnili zástup i představené města, kteří to slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Ale když dostali od Jásona a ostatních záruku, propustili je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Bratři hned v noci vyslali Pavla a Silase do Beroje. Když tam přišli, odebrali se do židovské synagogy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'A ⌈tamější Židé⌉ byli ušlechtilejší než ti v Tesalonice: přijali Slovo se vší dychtivostí a denně pečlivě zkoumali Písma, zdali je tomu tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Tak mnozí z nich uvěřili, také nemálo vznešených řeckých žen i mužů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Jakmile se však Židé z Tesaloniky dozvěděli, že Pavel zvěstuje slovo Boží také v Beroji, přišli i tam a podněcovali [a bouřili] zástupy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Tehdy bratři hned vyslali Pavla, aby šel až k moři, ale Silas a Timoteus tam zůstali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Ti, kteří Pavla doprovázeli, ho dovedli až do Athén a vrátili se, když dostali příkaz pro Silase a Timotea, aby k němu co nejdříve přišli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Zatímco na ně Pavel čekal v Athénách, jeho duch se v něm rozhorloval, když pozoroval, že město je plné model.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Proto mluvil v synagoze se Židy a s těmi, kdo ctili Boha, a na náměstí denně s těmi, kteří tam byli právě přítomni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Setkávali se s ním také někteří epikurejští a stoičtí filozofové. Někteří říkali: „Co nám to chce ten mluvka vykládat?“Jiní zase: „Zdá se, že to je hlasatel cizích božstev“; zvěstoval [jim] totiž Ježíše a vzkříšení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Chopili se ho a odvedli do Areopagu a říkali: „Smíme vědět, co je to za nové učení, které hlásáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, '⌈Předkládáš našim uším⌉ jakési cizí věci. Chceme tedy poznat, co to má být.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Všichni Athéňané a cizinci, kteří tam pobývali, se totiž nezabývali ničím jiným, než že říkali nebo poslouchali něco nového.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Pavel se postavil doprostřed Areopagu a říkal: „Muži athénští, pozoruji, že jste v každém ohledu velicí ctitelé božstev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Když jsem totiž procházel a pozorně prohlížel vaše posvátná místa, nalezl jsem i oltář, na kterém je napsáno: Neznámému bohu. Co tedy ctíte, a ještě neznáte, to já vám zvěstuji:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Bůh, který učinil svět a všechno, co je v něm, je pánem nebe i země a nebydlí ve svatyních zhotovených rukou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'ani si nedává sloužit lidskýma rukama, jako by něco potřeboval; on dává všem život, dech i všechno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Učinil z ⌈jedné krve⌉ všechno lidstvo, aby přebývalo na celém povrchu země; ustanovil jim nařízená období a hranice jejich přebývání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'aby hledali Boha, zda by se jej snad mohli dotknout a nalézt ho, a přece není od nikoho z nás daleko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Neboť v něm žijeme, pohybujeme se a jsme, jak to řekli i někteří z vašich básníků: Vždyť jsme i jeho rod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Jsme–li tedy rodem Božím, nesmíme se domnívat, že božstvo je podobno zlatu nebo stříbru nebo kamenu, výtvoru lidské zručnosti a důmyslu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Když tedy Bůh přehlédl ty doby nevědomosti, nařizuje nyní lidem, aby všichni a všude činili pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Neboť ustanovil den, v němž bude spravedlivě soudit obydlený svět skrze muže, kterého k tomu určil. Všem o tom poskytl důkaz tím, že jej vzkřísil z mrtvých.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Jakmile uslyšeli o vzkříšení mrtvých, jedni se mu posmívali a druzí řekli: „Poslechneme si tě o tom ještě jindy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'A tak ⌈od nich⌉ Pavel odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Ale někteří se k němu připojili a uvěřili; mezi nimi i Dionysios Areopagita, žena jménem Damaris a s nimi ještě jiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Po těchto událostech odešel [Pavel] z Athén a přišel do Korintu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Tam nalezl nějakého Žida jménem Akvila, ⌈který pocházel⌉ z Pontu, a jeho ženu Priscillu. Ten nedávno přišel z Itálie, protože Klaudius nařídil, aby všichni Židé odešli z Říma. Pavel k nim přišel,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'a protože měl stejné řemeslo, zůstával u nich a pracoval; byli totiž výrobci stanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Každou sobotu rozmlouval v synagoze a přesvědčoval Židy i Řeky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'A když Silas a Timoteus sestoupili z Makedonie, věnoval se Pavel zcela hlásání slova a dosvědčoval Židům, že Ježíš je Mesiáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Když se vzpírali a rouhali, vytřásl svůj šat a řekl jim: „Vaše krev na vaši hlavu. Já jsem od ní čistý. Od nynějška půjdu k pohanům.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Přešel odtamtud a vstoupil do domu jednoho muže jménem [Titus] Justus, který ctil Boha; jeho dům sousedil se synagogou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Představený synagogy Krispus s celým svým domem uvěřil Pánu; také mnozí Korinťané, kteří poslouchali, ⌈přistupovali k víře a dávali se křtít⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'V noci řekl Pán skrze vidění Pavlovi: „Neboj se, ale mluv a nemlč,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'protože já jsem s tebou, a nikdo se tě nedotkne, aby ti ublížil. Neboť mám mnoho lidu v tomto městě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Usadil se tam na rok a šest měsíců a vyučoval mezi nimi slovo Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Když byl Gallio místodržitelem v Achaji, Židé svorně povstali proti Pavlovi, přivedli jej na soud');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'a říkali: „Tento člověk přemlouvá lidi, aby ctili Boha v rozporu se Zákonem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Zatímco se Pavel chystal promluvit, řekl Gallio Židům: „Kdyby to byla nějaká křivda nebo zločin, Židé, náležitě bych se vámi zabýval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Když však to jsou spory týkající se učení a jmen a vašeho Zákona, ⌈vyřiďte si⌉ to sami mezi sebou. V tom já soudcem být nechci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'A od soudu je odehnal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Tu se všichni [Řekové] chopili představeného synagogy Sosthena a bili ho před soudem, ale Gallio si toho vůbec nevšímal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Když tam Pavel pobyl ještě ⌈nějaký čas⌉, rozloučil se s bratřími a vyplul do Sýrie a s ním i Priscilla a Akvila. V Kenchrejích si dal ostříhat hlavu, neboť učinil slib.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Přišli do Efesu a tam je zanechal; sám pak vešel do synagogy a rozmlouval se Židy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Ačkoli ho žádali, aby zůstal delší dobu, nesvolil k tomu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'ale rozloučil se a řekl: „ [Zcela jistě musím nastávající svátek strávit v Jeruzalémě.] Znovu se k vám vrátím, bude–li Bůh chtít.“Pak odplul z Efesu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'A přišel do Cesareje, odtud vystoupil do Jeruzaléma, pozdravil církev a sestoupil dolů do Antiochie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Když tam nějaký čas pobyl, odešel odtamtud. Postupně procházel galatskou krajinou a Frygií a posiloval všechny učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Do Efesu přišel Žid jménem Apollos, původem z Alexandrie, muž výmluvný, zběhlý v Písmech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Ten byl vyučen Pánově cestě, mluvil s vroucím duchem a učil přesně o Ježíšovi, ale znal jenom křest Janův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Začal směle mluvit v synagoze. Uslyšeli jej Priscilla a Akvila, vzali ho k sobě a ještě přesněji mu vyložili Boží cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'A když chtěl projít do Achaje, bratři ho v tom povzbudili a napsali učedníkům, aby ho přijali. Když tam přišel, velmi prospěl těm, kteří uvěřili skrze milost Boží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'neboť rázně na veřejnosti vyvracel argumenty Židů a ukazoval z Písma, že Ježíš je Mesiáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Stalo se, že když byl Apollos v Korintě, prošel Pavel ⌈hornatým vnitrozemím⌉ a přišel do Efesu; tam nalezl nějaké učedníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Řekl jim: „Přijali jste Ducha Svatého, když jste uvěřili?“Oni mu odpověděli: „Ne, vždyť jsme ani neslyšeli, že je Duch Svatý.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Řekl: „Jak jste tedy byli pokřtěni?“Oni řekli: „⌈Janovým křtem⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Pavel řekl: „Jan křtil křtem pokání a říkal lidu, aby uvěřili v toho, který přijde po něm, to jest v Ježíše.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Když to uslyšeli, ⌈dali se pokřtít⌉ ve jméno Pána Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'A když na ně Pavel vložil ruce, přišel na ně Duch Svatý a oni mluvili jazyky a prorokovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Těch mužů bylo celkem asi dvanáct.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Pavel vstoupil do synagogy a směle v ní mluvil po tři měsíce; rozmlouval s lidmi a přesvědčoval je o věcech Božího království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Když se však někteří zatvrzovali a nechtěli se dát přesvědčit, ba přede všemi tu Cestu tupili, Pavel od nich odstoupil, oddělil učedníky a denně rozmlouval ve škole [nějakého] Tyranna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'To trvalo dva roky, takže všichni obyvatelé provincie Asie uslyšeli Pánovo slovo, Židé i Řekové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'A Bůh skrze Pavlovy ruce konal neobvyklé mocné činy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'takže i na nemocné odnášeli šátky a zástěry, ⌈které se dotkly jeho těla⌉, a nemoci se od nich vzdalovaly a zlí duchové vycházeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Také někteří potulní židovští zaklínači se pokusili nad těmi, kteří měli zlé duchy, vyslovovat jméno Pána Ježíše a říkali: „Zaklínám vás Ježíšem, kterého hlásá Pavel.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'To činilo sedm synů nějakého Skévy, židovského velekněze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Zlý duch jim však odpověděl: „Ježíše znám a o Pavlovi vím, ale kdo jste vy?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'A ten člověk, v němž byl zlý duch, se na ně vrhl, ovládl ⌈dva z nich ⌉ a přemohl je, takže nazí a zranění utekli z toho domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, '⌈Dověděli se o tom všichni⌉ Židé a Řekové, kteří bydleli v Efesu. I padl na všechny strach a jméno Pána Ježíše bylo velebeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'A mnozí z těch, kteří uvěřili, přicházeli, otevřeně vyznávali a odhalovali své skutky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Mnozí, kteří se zabývali magií, snesli své knihy a přede všemi je pálili. A spočítali jejich cenu a shledali hodnotu padesáti tisíc stříbrných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tak ⌈Pánovo slovo mocně rostlo a sílilo⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, '⌈Po těchto událostech⌉ se Pavel v duchu rozhodl, že projde Makedonii a Achaju a půjde do Jeruzaléma. Řekl: „Až tam pobudu, musím spatřit také Řím.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Poslal do Makedonie dva své pomocníky, Timotea a Erasta, a sám zůstal nějaký čas v Asii.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'V té době nastalo nemalé pobouření pro tu Cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Nějaký zlatník jménem Demétrios, který vyráběl stříbrné modely Artemidiny svatyně a poskytoval řemeslníkům nemalý výdělek,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'svolal řemeslníky i ostatní pracovníky v tomto oboru a řekl: „Muži, víte, že z této práce máme blahobyt,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'a vidíte a slyšíte, že tento Pavel nejen v Efesu, nýbrž téměř v celé Asii přesvědčil a svedl značný zástup. Říká, že bohové, kteří jsou děláni rukama, nejsou bohové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Hrozí nebezpečí, že nejenom náš obor přijde v opovržení, ale i chrám veliké bohyně Artemidy nebude považován za nic, a bude stržena velebnost té, kterou uctívá celá Asie i obydlený svět.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Když to uslyšeli, rozpálili se hněvem a začali křičet: „Veliká je efeská Artemis!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Celé město se naplnilo zmatkem; všichni se společně hnali do divadla a vlekli s sebou Pavlovy průvodce na cestách, Makedonce Gaia a Aristarcha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Pavel chtěl vejít mezi lid, ale učedníci mu v tom bránili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Také někteří vysocí úředníci provincie, kteří byli jeho přáteli, mu poslali vzkaz a prosili ho, aby se nevydával do divadla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Každý křičel něco jiného, neboť shromáždění bylo zmatené a většina ani nevěděla, proč se sešli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Ze zástupu vytáhli Alexandra, kterého Židé postrčili dopředu. Alexandr pokynul rukou a chtěl se před lidem hájit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Když však poznali, že je to Žid, zvolali všichni jedním hlasem a asi dvě hodiny křičeli: „Veliká je efeská Artemis!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Městský tajemník utišil zástup a řekl: „Muži efesští, kdo z lidí by nevěděl, že město Efeských je strážcem chrámu veliké Artemidy a ⌈ jejího obrazu spadlého z nebe⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Protože o tom tedy není pochyb, musíte zachovat klid a nedělat nic ukvapeného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Přivedli jste tyto muže, ale oni se nedopustili svatokrádeže, ani neuráží naši bohyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Mají–li tedy Demétrios a řemeslníci, kteří jsou s ním, proti někomu žalobu, konají se přece veřejné soudy a jsou tu místodržitelé. Tam ať žalují jeden druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Žádáte–li něco jiného, bude to vyřešeno v zákonném shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Vždyť jsme v nebezpečí, že budeme kvůli dnešku obviňováni ze vzpoury. Není žádný důvod, kterým ⌈bychom mohli⌉ vysvětlit toto srocení.“Po těch slovech shromáždění rozpustil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Když ten rozruch ustal, svolal si Pavel učedníky, povzbudil je, rozloučil se s nimi a vydal se na cestu do Makedonie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Prošel ty krajiny, povzbudil bratry mnohými slovy a přišel do Řecka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'kde strávil tři měsíce. Židé proti němu nastrojili léčku, právě když se chystal plavit do Sýrie, i rozhodl se, že se vrátí přes Makedonii.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, '[Až do Asie] ho doprovázeli Sopatros, [Pyrrhův syn] z Beroje, z Tesalonických pak Aristarchos a Sekundus, Gaius z Derbe a Timoteus, z Asie Tychikos a Trofimos.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ti ⌈šli napřed⌉ a čekali na nás v Troadě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'My jsme po dnech nekvašených chlebů vypluli z Filip a za pět dní jsme k nim dorazili do Troady, kde jsme strávili sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'První den v týdnujsme se sešli k lámání chleba. Pavel s nimi rozmlouval, protože chtěl druhý den odejít, a protáhl svou řeč až do půlnoci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'V horní místnosti, kde jsme byli shromážděni, bylo mnoho lamp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Nějaký mladík jménem Eutychos seděl na okně. Když Pavel dlouho mluvil, zmáhal ho hluboký spánek. Přemožen spánkem spadl dolů z třetího poschodí. Zdvihli ho mrtvého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Pavel sešel dolů, padl na něho, objal ho a řekl: „Neznepokojujte se, neboť jeho duše je v něm.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Pak vystoupil nahoru, lámal chléb a jedl, a dlouho do rána s nimi rozmlouval; a tak odešel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Chlapce přivedli živého a byli velice povzbuzeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'My jsme ⌈šli napřed⌉ na loď a vypluli jsme k Assu, kde jsme měli přibrat Pavla. Tak nám to totiž nařídil, a sám se chystal ⌈cestovat po souši⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Když se s námi setkal v Assu, vzali jsme ho na loď a přijeli jsme do Mitylény.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'A když jsme odtud odpluli, dostali jsme se druhého dne ⌈do blízkosti⌉ Chiu. Další den jsme připluli k Samu a [po zastávce v Trogylliu] jsme příští den přijeli do Milétu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Pavel se totiž rozhodl minout Efes, aby se nezdržel v Asii, neboť spěchal, aby se dostal na den Letnic do Jeruzaléma, bude–li to jen trochu možné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Z Milétu poslal vzkaz do Efesu a zavolal si starší církve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Když k němu přišli, řekl jim: „Vy víte, jak jsem od prvního dne, kdy jsem vstoupil do Asie, byl s vámi po celý čas');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'a sloužil jako otrok Pánu se vší pokorou, v slzách i zkouškách, které mě potkaly pro úklady Židů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'jak jsem nic nezamlčel z toho, co by vám prospívalo, ale všechno jsem vám oznámil, když jsem vás učil veřejně i po domech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Naléhavě jsem Židům i Řekům svědčil o pokání k Bohu a o víře v našeho Pána Ježíše [Krista].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'A nyní, hle, jsa spoután Duchem, jdu do Jeruzaléma a nevím, co mne tam potká,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'kromě toho, že mi Duch Svatý v každém městě dosvědčuje, že mne čekají pouta a soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Avšak v žádném ohledu si necením své duše víc, než abych dokončil svůj běh a službu, kterou jsem přijal od Pána Ježíše: dosvědčovat evangelium o Boží milosti.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, '„A nyní, hle, já vím, že vy všichni, mezi kterými jsem procházel a hlásal [Boží] království, již nespatříte mou tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Proto vám dnešního dne dosvědčuji, že jsem čistý od krve všech lidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'neboť jsem nic nezamlčel a oznámil jsem vám celou vůli Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Dávejte pozor na sebe a na celé stádo, v němž vás Duch Svatý ustanovil za strážce, abyste pásli Boží církev, kterou si získal ⌈vlastní krví⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Já vím, že po mém odchodu k vám vejdou draví vlci, kteří nebudou šetřit stádo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'I z vás samotných povstanou muži, kteří budou mluvit převrácené věci, aby strhli učedníky za sebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Proto buďte bdělí a mějte na paměti, že jsem po tři roky dnem i nocí nepřestal se slzami napomínat jednoho každého z vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'A nyní vás svěřuji Bohu a slovu jeho milosti, které má moc vás zbudovat a dát vám dědictví mezi všemi posvěcenými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Nezatoužil jsem po stříbře, zlatě ani oděvu nikoho z vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Sami víte, že pro potřeby mé a těch, kteří byli se mnou, sloužily tyto ruce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Ve všem jsem vám ukázal, že takto máme pracovat, ujímat se slabých a pamatovat na slova Pána Ježíše, neboť on řekl: Blaženější je dávat než brát. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, '⌈Po těch slovech⌉ poklekl a s nimi všemi se pomodlil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Všichni se dali do velikého pláče, ⌈objímali Pavla⌉ a líbali ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Nejvíce se rmoutili nad tím slovem, které řekl, že již více nespatří jeho tvář. A doprovázeli ho k lodi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Když jsme se od nich odtrhli, vypluli jsme. Plavili jsme se přímo a přišli jsme na Kós, druhý den na Rodos a odtamtud do Patary.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Našli jsme loď, která plula do Fénicie, nalodili jsme se a vypluli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Přiblížili jsme se na dohled ke Kypru, nechali jej vlevo a plavili se do Sýrie. Přistáli jsme v Týru, neboť tam měla loď vyložit náklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Vyhledali jsme učedníky a zůstali jsme tam sedm dní. Ti skrze Ducha říkali Pavlovi, aby nevstupoval do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Když ty dny uplynuly, vydali jsme se na cestu. Všichni i se ženami a dětmi nás vyprovázeli až za město. Na pobřeží jsme padli na kolena, pomodlili se');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'a rozloučili jsme se. Pak jsme vstoupili na loď a oni se vrátili domů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Dokončili jsme plavbu z Týru a dorazili do Ptolemaidy. Tam jsme pozdravili bratry a zůstali jsme u nich jeden den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Druhý den jsme vyšli a přišli do Cesareje. Vešli jsme do domu evangelisty Filipa, který byl jedním ze sedmi, a zůstali jsme u něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Ten měl čtyři dcery, panny, které prorokovaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Když jsme tam pobývali už několik dní, přišel z Judska nějaký prorok jménem Agabos.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Přišel k nám, vzal Pavlův opasek, svázal si nohy a ruce a řekl: „Toto praví Duch Svatý: Muže, jemuž patří tento opasek, Židé v Jeruzalémě takto svážou a vydají do rukou pohanů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Když jsme to uslyšeli, prosili jsme Pavla my i tamní bratři, aby nevystupoval do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Tu Pavel odpověděl: „Proč pláčete a trápíte mé srdce? Vždyť já jsem připraven nejen nechat se svázat, ale i umřít v Jeruzalémě pro jméno Pána Ježíše.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Protože se nenechal přesvědčit, přestali jsme naléhat a řekli jsme: „Děj se vůle Páně!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Po těchto dnech jsme se připravili na cestu a vystupovali do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Šli s námi také někteří učedníci z Cesareje a vedli nás k jednomu z prvních učedníků, jistému Mnasonovi z Kypru; u něho jsme se měli ubytovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Když jsme přišli do Jeruzaléma, bratři nás radostně přijali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Druhý den šel Pavel s námi k Jakubovi a přišli všichni starší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Pozdravil je a vyprávěl jim podrobně všechno, co Bůh skrze jeho službu učinil mezi pohany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Když to uslyšeli, oslavovali Boha a jemu řekli: „Vidíš, bratře, kolik ⌈tisíc Židů⌉ uvěřilo a všichni jsou horliteli pro Zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'O tobě se doslechli, že učíš všechny Židy, kteří žijí mezi pohany, ⌈aby odpadli⌉ od Mojžíše, říkaje, aby neobřezávali své děti ani ⌈se neřídili⌉ zvyky svých otců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Co teď? Nepochybně [se musí sejít shromáždění, neboť] uslyší, že jsi přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Udělej tedy to, co ti říkáme: Máme tu čtyři muže, kteří ⌈na sebe vzali⌉ slib.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Ty vezmi s sebou, dej se očistit s nimi a zaplať za ně, aby si mohli dát oholit hlavu. A všichni poznají, že na tom, co se o tobě doslechli, nic není, nýbrž že i sám řádně žiješ, zachovávaje Zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Pokud jde o pohany, kteří uvěřili, usoudili jsme a napsali jim, [aby nic z toho nezachovávali kromě toho,] že se mají vystříhat masa obětovaného modlám, krve, zardoušeného a smilstva.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Potom Pavel vzal ty muže k sobě a na druhý den se s nimi dal očistit. Vešel do chrámu a oznámil, ⌈kdy skončí dny⌉ očišťování a bude přinesena oběť za každého z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Když se těch sedm dní chýlilo ke konci, spatřili ho v chrámě Židé z Asie. Pobouřilicelý zástup, vztáhli na Pavla ruce');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'a křičeli: „Muži Izraelci, pomozte! Toto je ten člověk, který všude všechny učí proti tomuto lidu, proti Zákonu a proti tomuto místu. Nadto ještě přivedl do chrámu Řeky a znesvětil toto svaté místo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Viděli s ním totiž předtím ve městě Trofima z Efesu a domnívali se, že ho Pavel přivedl do chrámu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Celé město se rozbouřilo a nastalo srocení lidu. Uchopili Pavla a vlekli ho ven z chrámu. A hned byly zavřeny brány.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Zatímco ho chtěli zabít, došlo veliteli posádky hlášení, že se bouří celý Jeruzalém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Ten vzal okamžitě vojáky i setníky a seběhl ⌈k nim dolů⌉. Jakmile uviděli velitele posádky a vojáky, přestali Pavla bít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Tu se velitel přiblížil, uchopil ho a rozkázal ho spoutat dvěma řetězy. Pak se vyptával, kdo to má být a co učinil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'V zástupu vykřikoval každý něco jiného. Když se nemohl pro ten zmatek dozvědět nic jistého, rozkázal odvést ho do kasáren.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Když se Pavel ocitl na schodišti, stalo se, že ho kvůli násilí lidu museli vojáci nést,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'neboť celé to množství lidu šlo za ním a křičelo: „Pryč s ním!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Když už ho měli odvést do kasáren, říká Pavel veliteli: „Smím ti něco říci?“On řekl: „ Ty umíš řecky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Ty tedy nejsi ten Egypťan, který nedávno pobouřil a na poušť vyvedl čtyři tisíce sikariů?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Pavel řekl: „Já jsem Žid z Tarsu v Kilikii, občan ne bezvýznamného města. Prosím tě, dovol mi promluvit k lidu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'A když to dovolil, Pavel, který stál na schodišti, pokynul rukou lidu. Nastalo veliké ticho a Pavel promluvil hebrejským jazykem:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '„Muži bratři a otcové, poslyšte nyní mou obhajobupřed vámi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Když uslyšeli, že k nim mluví hebrejským jazykem, ještě více se ztišili. I řekl:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '„Já jsem Žid narozený v Tarsu v Kilikii, avšak vychovaný v tomto městě. U nohou Gamalielových jsem byl přesně vyučen otcovskému zákonu ⌈a horlil jsem⌉ pro Boha jako dnes vy všichni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'A pronásledoval jsem tu Cestu až na smrt; muže i ženy jsem spoutával a dával do vězení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'jak mi může dosvědčit i velekněz a ⌈všichni starší⌉. Od nich jsem přijal dopisy pro bratry a šel jsem do Damašku, abych také ty, kteří byli tam, přivedl spoutané do Jeruzaléma k potrestání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Stalo se mi však, když jsem byl na cestě a blížil se k Damašku, že kolem poledne mě náhle ozářilo velmi jasné světlo z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Padl jsem na zem a uslyšel jsem hlas, který mi pravil: Saule, Saule, proč mne pronásleduješ?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Já jsem odpověděl: Kdo jsi, Pane? Řekl mi: Já jsem Ježíš Nazaretský, kterého ty pronásleduješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Ti, kdo byli se mnou, uviděli sice světlo [a ulekli se], ale neslyšeli hlas toho, který ke mně mluvil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Řekl jsem: Co mám učinit, Pane? Pán mi řekl: Vstaň a jdi do Damašku, a tam ti bude řečeno všechno, co ti je nařízeno učinit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Protože jsem od jasu toho světla neviděl, vedli mě moji průvodci za ruku a tak jsem přišel do Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Nějaký Ananiáš, zbožný muž podle Zákona, mající dobré svědectví od všech ⌈ tam bydlících Židů⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'přišel za mnou, postavil se přede mě a řekl mi: Bratře Saule, prohlédni. A já jsem v tu chvíli ⌈na něho pohlédl⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'On řekl: Bůh našich otců si tě vyvolil, abys poznal jeho vůli, uviděl jeho Spravedlivého a uslyšel hlas z jeho úst,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'neboť mu budeš přede všemi lidmi svědkem toho, co jsi viděl a slyšel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'A proč nyní váháš? Vstaň, dej se pokřtít a smyj své hříchy vzývaje jeho jméno. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, '„Stalo se mi, když jsem se vrátil do Jeruzaléma a modlil se v chrámě, že jsem se ocitl ve vytržení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Spatřil jsem Ježíše, jak mi říká: Pospěš si a vyjdi rychle z Jeruzaléma, protože nepřijmou tvé svědectví o mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'A já jsem řekl: Pane, oni vědí, že já jsem dával věznit a bičovat v synagogách ty, kdo v tebe věří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Když byla prolévána krev tvého svědka Štěpána, i já jsem byl při tom, souhlasil jsem s tím a hlídal jsem šaty těch, kdo ho zabíjeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'I řekl mi: Jdi, neboť já tě vyšlu daleko k pohanům. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Až potud ho poslouchali. Ale pak pozdvihli svůj hlas a říkali: „Odstraň ze země takového člověka, neboť nesmí zůstat naživu!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Protože křičeli, rvali si šaty a házeli do vzduchu prach,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'velitel rozkázal, aby Pavla zavedli do kasáren; a nařídil při jeho výslechu použít důtky, aby se dozvěděl, z jakého důvodu na něho tak křičeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Když ho ⌈přivázali řemeny⌉, řekl Pavel setníkovi, který tam stál: „Smíte bičovat římského občana, a to bez soudu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Když to setník uslyšel, přišel k veliteli a oznámil mu to. Řekl: „Co chceš dělat? Vždyť tento člověk je římský občan!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Velitel přišel k Pavlovi a řekl mu: „Řekni mi, jsi římský občan?“On řekl: „Ano.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Velitel mu na to řekl: „Já jsem získal toto občanství za veliké peníze.“Pavel řekl: „Já jsem se však jako římský občan narodil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Okamžitě od něho odstoupili ti, kteří ho měli vyslýchat. Také velitel dostal strach, když se dověděl, že Pavel je římský občan, a on ho dal spoutat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Druhého dne, protože chtěl bezpečně poznat, z čeho jej Židé obviňují, ho odvázal a rozkázal, aby se sešli velekněží a celá velerada. Pak vyvedl Pavla a postavil ho před ně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Pavel upřel zrak na veleradu a řekl: „Muži bratři, až do tohoto dne žiji se zcela dobrým svědomím před Bohem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Velekněz Ananiáš však nařídil těm, kdo stáli u něho, aby ho udeřili přes ústa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Pavel mu řekl: „Tebe bude bít Bůh, ty obílená stěno. Ty zde sedíš, abys mě soudil podle Zákona, a proti Zákonu poroučíš, abych byl bit?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Ti, kdo stáli poblíž, řekli: „ Ty tupíš Božího velekněze?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Pavel řekl: „Nevěděl jsem, bratři, že je veleknězem. Vždyť je napsáno: Vládci svého lidu nebudeš zlořečit. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Protože Pavel věděl, že ve veleradě je jedna část ze saduceů a druhá z farizeů, začal volat: „Muži bratři, já jsem farizeus, syn farizeů. Jsem souzen pro ⌈naději a vzkříšení mrtvých⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Když to řekl, nastala hádka mezi farizeji a saduceji a shromáždění se rozdělilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Saduceové totiž říkají, že není vzkříšení, ani andělé ani duchové, kdežto farizeové to všechno vyznávají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Nastal veliký křik a někteří učitelé Zákona ze strany farizeů povstali a začali prudce namítat: „Nenacházíme na tomto člověku nic zlého. Co když k němu promluvil duch nebo anděl?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Hádka se zvětšovala a velitel dostal strach, aby Pavla nerozsápali. Rozkázal vojákům, aby sešli dolů, vyrvali ho z jejich středu a odvedli do kasáren.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Následující noci se k němu postavil Pán a řekl: „Buď statečný! Jako jsi o mně svědčil v Jeruzalémě, tak musíš svědčit i v Římě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Když nastal den, [někteří] Židé se spikli a zapřisáhli, že nebudou jíst ani pít, dokud Pavla nezabijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Těch, kdo se takto spikli, bylo více než čtyřicet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Ti přišli k velekněžím a starším a řekli: „Slavnostně jsme se zapřisáhli, že ničeho neokusíme, dokud Pavla nezabijeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Tak vy nyní spolu s veleradou ohlašte veliteli, aby ho k vám přivedl, že se chystáte jeho záležitost důkladněji vyšetřit. A my jsme připraveni zabít ho dříve, než se k vám přiblíží.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'O tomto úkladu však uslyšel syn Pavlovy ⌈sestry. Přišel a vešel⌉ do kasáren a oznámil to Pavlovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Pavel si zavolal jednoho ze setníků a řekl: „Tohoto mladíka zaveď k veliteli. Má mu co oznámit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'On ho tedy vzal s sebou, zavedl k veliteli a řekl: „Vězeň Pavel si mě zavolal a požádal, abych tohoto mladíka zavedl k tobě, protože ti má něco říci.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Velitel ho vzal za ruku, odešel s ním stranou a vyptával se: „Co je to, co mi máš oznámit?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'On řekl: „Židé se domluvili, že tě požádají, abys zítra odvedl Pavla do velerady, jako by chtěli něco v jeho případě důkladněji vyšetřit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Ale ty jim nevěř, neboť více než čtyřicet mužů z nich na něho číhá; zapřisáhli se totiž, že nebudou jíst ani pít, dokud ho nezabijí, a nyní jsou připraveni a čekají jen na tvůj souhlas.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Velitel mladíka propustil a nařídil mu: „Nikomu nevyzraď, žes mi to ohlásil.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Pak zavolal dva ze svých setníků a řekl jim: „Připravte na devátou hodinu večer dvě stě vojáků, aby šli do Cesareje, také sedmdesát jezdců a dvě stě lehkooděnců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Ať připraví mezky, aby na ně posadili Pavla a bezpečně ho dopravili k místodržiteli Félixovi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'A napsal dopis tohoto znění:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '„Klaudios Lysias zdraví vznešeného místodržitele Félixe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Tohoto muže se Židé zmocnili a chtěli ho zabít. Přišel jsem s vojskem a vytrhl jim ho, když jsem se dozvěděl, že je římský občan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Chtěl jsem se dozvědět, z čeho jej obviňují, a proto jsem [ho] odvedl do jejich velerady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Shledal jsem, že je obviňován kvůli sporným otázkám jejich Zákona, ale ⌈že na něm není⌉ žádná vina, za niž by zasluhoval smrt nebo vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Protože mi bylo oznámeno, že [Židé] proti tomuto muži chystají úklady, posílám ho hned k tobě. Také žalobcům jsem nařídil, aby to, co mají proti němu, řekli před tebou. [Buď zdráv.]“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Vojáci tedy, podle toho, jak jim bylo nařízeno, vzali Pavla a zavedli ho v noci do Antipatridy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Druhého dne nechali jezdce s ním odjet a sami se vrátili do kasáren.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Jezdci přijeli do Cesareje, odevzdali dopis místodržiteli a postavili před něho i Pavla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Přečetl dopis a zeptal se, ze které je provincie. Když se dověděl, že z Kilikie,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'řekl: „Vyslechnu tě, až přijdou také tvoji žalobci.“A rozkázal, aby ho hlídali v Herodově paláci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Po pěti dnech sestoupil do Cesareje velekněz Ananiáš s některými staršími a s nějakým Tertullem, právníkem, a ti ohlásili místodržiteli žalobu proti Pavlovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Když byl Pavel předvolán, Tertullus začal obžalobu: „⌈Tvou zásluhou⌉ zakoušíme mnohý pokoj a tvou prozíravostí se u tohoto národa mnohé napravuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Vždy a všude to přijímáme, vznešený Félixi, s veškerou vděčností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Abych tě však déle nezdržoval, prosím, abys nás se svou obvyklou vlídností krátce vyslechl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Shledali jsme totiž, že tento muž je jako mor, po celém světě mezi všemi Židy vyvolává nepokoje a je vůdcem sekty Nazorejců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Pokusil se dokonce znesvětit chrám. Zmocnili jsme se ho [a chtěli jsme ho soudit podle našeho Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Avšak přišel velitel Lysias, velkým násilím jej vzal z našich rukou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'a rozkázal, aby jeho žalobci přišli k tobě]. Když ho vyslechneš, sám se můžeš od něho dovědět o tom všem, z čeho jej obviňujeme.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Připojili se i Židé a tvrdili, že je tomu tak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Když mu místodržitel pokynul, aby mluvil, Pavel odpověděl: „Vím, že po mnoho let jsi soudcem v tomto národě, a proto se budu hájit s dobrou myslí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Můžeš se přesvědčit, že tomu není víc než dvanáct dní, kdy jsem vystoupil do Jeruzaléma, abych se poklonil Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'A nenalezli mě, že bych s někým rozmlouval nebo vyvolával srocení davu, ani v chrámu ani v synagogách ani ve městě;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'ani nemohou před tebou dokázat to, z čeho mne nyní žalují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Ale vyznávám ti, že podle té Cesty, kterou nazývají sektou, takto sloužím Bohu svých otců a věřím všemu, co je napsáno v Zákoně a v Prorocích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'A mám naději v Bohu, kterou i oni sami chovají, že jistě nastane vzkříšení spravedlivých i nespravedlivých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Proto i já sám se snažím mít vždy bezúhonné svědomí před Bohem i lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Po několika letech jsem přišel, abych odevzdal svému národu almužny a přinesl oběti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'A při nich mě našli očištěného v chrámě, ne se zástupem ani s hlukem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Ale někteří Židé z Asie by tu měli být před tebou a žalovat, mají–li něco proti mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Nebo tito sami ať řeknou, jaký zločin [na mně] našli, když jsem stál před veleradou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'kromě tohoto jediného výkřiku, který jsem zvolal, když jsem stál mezi nimi: Pro vzkříšení mrtvých mě dnes soudíte. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Avšak Félix, který byl podrobněji obeznámen s tou Cestou, je odkázal na pozdější dobu. Řekl: „Až přijde velitel Lysias, rozhodnu vaši při.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Nařídil setníkovi, aby byl Pavel střežen, měl mírnou vazbu a aby nikomu z jeho přátel nebylo bráněno mu sloužit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Po několika dnech přišel Félix se svou ženou Drusillou, která byla Židovka. Poslal si pro Pavla a poslechl si od něho o víře v Krista [Ježíše].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Když však mluvil o spravedlnosti, sebeovládání a budoucím soudu, Félix se ulekl a řekl: „Pro dnešek ⌈můžeš jít⌉, až budu mít čas, zavolám si tě.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Zároveň doufal, že mu Pavel dá peníze. Proto si ho také k sobě volal častěji a rozmlouval s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Po uplynutí dvou let se stal Félixovým nástupcem Porcius Festus. A protože se Félix chtěl zavděčit Židům, ponechal Pavla ve vězení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Když tedy Festus přišel do provincie, vystoupil po třech dnech z Cesareje do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Velekněží a přední Židé ⌈vznesli u něho žalobu⌉ proti Pavlovi. Naléhali na něho');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, '⌈a žádali, aby jim prokázal laskavost⌉ a poslal ho do Jeruzaléma; chystali totiž léčku, že ho cestou zabijí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Festus odpověděl, že Pavel je ve vězení v Cesareji a on sám že se brzy vydá na cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '„ Ať tedy ti z vás,“řekl, „⌈kteří mají moc⌉, sestoupí se mnou, a je–li na tom muži něco špatného, ať ho žalují.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Nestrávil mezi nimi více než osm nebo deset dní a sestoupil do Cesareje. Na druhý den zasedl ⌈k soudu⌉ a rozkázal přivést Pavla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Když přišel, obstoupili ho Židé, kteří sestoupili z Jeruzaléma, a vznášeli mnoho těžkých obvinění, která nemohli dokázat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Pavel se hájil takto: „Nijak jsem se neprohřešil ani proti zákonu Židů, ani proti chrámu, ani proti císaři.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Avšak Festus, který se chtěl Židům zavděčit, Pavlovi odpověděl: „Chceš vystoupit do Jeruzaléma a tam být z toho přede mnou souzen?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Pavel řekl: „Stojím před císařským soudem, kde mám být souzen. Židům jsem v ničem neublížil, jak i ty velmi dobře víš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Jestliže jsem tedy vinen a učinil jsem něco, co zasluhuje smrt, nezdráhám se zemřít. Není–li však nic na tom, z čeho mne tito lidé obviňují, nikdo mne jim nemůže vydat. Odvolávám se k císaři.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Nato Festus promluvil s radou a odpověděl: „K císaři ses odvolal, k císaři půjdeš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Uplynulo několik dní a do Cesareje přijeli král Agrippa a Bereniké a pozdravili Festa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Když tam ⌈už nějaký čas⌉ pobývali, předložil Festus králi Pavlův případ. Řekl: „Je tu od Félixe jako vězeň ponechán jeden muž,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'o kterém mi velekněží a starší Židů podali zprávu, když jsem byl v Jeruzalémě, a žádali jeho odsouzení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Odpověděl jsem jim, že není římským zvykem vydávat nějakého člověka dřív, než by obžalovaný měl své žalobce tváří v tvář a dostal příležitost k obhajobě proti jejich obvinění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Když se tu tedy sešli, bez odkladu jsem příštího dne zasedl ⌈k soudu⌉ a rozkázal předvést toho muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Jeho žalobci se postavili proti němu, ale nepřinášeli žádné obvinění [ze zlých činů], jak jsem očekával,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'nýbrž měli s ním nějaké spory o své náboženství a o nějakého zemřelého Ježíše, o němž Pavel tvrdil, že žije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Byl jsem na rozpacích, jak tyto věci prozkoumat, a říkal jsem mu, zda by nechtěl jít do Jeruzaléma a tam být v těchto věcech souzen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Avšak Pavel se odvolal, aby byl ve vězení až do rozhodnutí ⌈Jeho Veličenstva⌉; proto jsem ho rozkázal hlídat, dokud ho nepošlu k císaři.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agrippa [řekl] Festovi: „Sám bych si chtěl také toho člověka poslechnout.“„Zítra“, řekl Festus, „ho uslyšíš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Druhý den tedy přišel Agrippa a Bereniké s velkou okázalostí a spolu s veliteli a předními muži města vstoupili do jednací síně. Na Festův rozkaz byl přiveden Pavel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'A Festus řekl: „Králi Agrippo a všichni muži zde s námi přítomní, vidíte tohoto člověka, kvůli němuž všichni Židé jak v Jeruzalémě, tak i zde na mne naléhali a křičeli, že nesmí více zůstat naživu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Já jsem shledal, že neudělal nic, zač by zasluhoval smrt. Ale protože on sám se odvolal k Jeho Veličenstvu, rozhodl jsem se ho k němu poslat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Nemám však nic určitého, co bych o něm svému pánu napsal. Proto jsem ho předvedl před vás a zvláště před tebe, králi Agrippo, abych po výslechu měl co napsat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Zdá se mi totiž nerozumné posílat vězně a neuvést zároveň obvinění proti němu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa řekl Pavlovi: „Dovoluje se ti, abys mluvil sám za sebe.“Nato Pavel vztáhl ruku a začal svou obhajobu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '„Pokládám se za šťastného, králi Agrippo, že proti všemu, z čeho mě Židé obviňují, se smím dnes hájit před tebou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, '⌈který jsi⌉ nejlepším znalcem všech židovských zvyků i jejich sporných otázek. Proto prosím, abys mě trpělivě vyslechl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'O mém životě od mládí, jak jsem jej vedl od počátku ve svém národě i v Jeruzalémě, vědí všichni Židé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Znají mě už od dřívějška, a kdyby chtěli, mohou svědčit, že jsem žil podle nejpřísnější strany našeho náboženství jako farizeus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'A nyní stojím ⌈před soudem⌉ pro naději v zaslíbení, které ⌈Bůh dal⌉ našim otcům');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'a o němž našich dvanáct kmenů doufá, že jej dosáhne vytrvalou službou Bohu dnem i nocí. Pro tuto naději, králi [Agrippo], mě Židé žalují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Proč se u vás pokládá za neuvěřitelné, že Bůh probouzí mrtvé?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Já sám jsem se domníval, že musím mnoho vykonat proti jménu Ježíše Nazaretského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'To jsem také v Jeruzalémě činil. Dostal jsem od velekněží ⌈plnou moc⌉ a mnoho svatých jsem zavřel do vězení, a když byli zabíjeni, ⌈souhlasil jsem s tím ⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Po všech synagogách jsem je často trestal a nutil, aby se rouhali. Nadmíru jsem běsnil a pronásledoval je dokonce až do cizích měst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Když jsem byl na cestě do Damašku s ⌈plnou mocí⌉ a pověřením od velekněží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'cestou jsem spatřil, králi, o poledni světlo z nebe, jasnější než slunce, které ozářilo mne i ty, kdo šli se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'A když jsme všichni padli na zem, uslyšel jsem hlas, který ke mně mluvil hebrejským jazykem: Saule, Saule, proč mne pronásleduješ? Bolestivé je pro tebe kopat proti bodcům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Řekl jsem: Kdo jsi, Pane? Pán odpověděl: Já jsem Ježíš, kterého ty pronásleduješ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Ale vstaň a postav se na nohy, neboť proto jsem se ti ukázal, abych tě ustanovil svým služebníkem a svědkem těch věcí, které jsi viděl, i těch, které ti ještě ukážu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, '⌈Budu tě vysvobozovat⌉ z toho to lidu i z pohanů, ke kterým tě posílám');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'otevřít jejich oči, aby se obrátili od tmy do světla, od moci Satanovy k Bohu, a aby vírou ve mne obdrželi odpuštění hříchů a podíl mezi posvěcenými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Proto, králi Agrippo, nestal jsem se neposlušným toho nebeského vidění,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'ale hlásal jsem nejprve těm, kteří jsou v Damašku, a potom v Jeruzalémě a po celé judské zemi, a také pohanům, aby činili pokání, obraceli se k Bohu a konali skutky, které svědčí o pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Z toho důvodu se mne Židé zmocnili, [když jsem byl] v chrámě, a pokoušeli se mne zabít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, '⌈Bůh mi však až do dnešního dne pomáhal⌉, takže tu stojím a svědčím malému i velikému. Neříkám nic mimo to, co Proroci i Mojžíš pověděli, že se má dít:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'že Mesiáš má trpět, jako první vstane z mrtvých a bude zvěstovat světlo jak lidu izraelskému, tak také pohanům.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Když toto mluvil na svou obranu, Festus ⌈hlasitě zvolal⌉: „Blázníš, Pavle, mnoho vědomostí tě přivádí k šílenství!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'A Pavel řekl: „Neblázním, vznešený Feste, nýbrž jasně vyjevuji slova pravdy a zdravého úsudku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Vždyť král o těch věcech ví, a proto také k němu mluvím otevřeně. Nevěřím, že mu něco z toho uniklo. Vždyť se to nedálo někde v ústraní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Věříš, králi Agrippo, Prorokům? Vím, že věříš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa na to řekl Pavlovi: „Málem bys mě přesvědčil, abych se stal křesťanem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'A Pavel řekl: „Přál bych si od Boha, aby ses nejen ty, ale všichni ti, kdo mě dnes slyší, stali dříve nebo později tím, čím jsem já -- kromě těchto pout.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Král vstal a s ním místodržitel, Bereniké i ti, kteří s nimi seděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'A když se vzdálili, hovořili mezi sebou: „Tento člověk nedělá nic, zač by zasluhoval smrt nebo vězení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa říkal Festovi: „Tento člověk mohl být propuštěn, kdyby se nebyl odvolal k císaři.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Jakmile bylo rozhodnuto, že odplujeme do Itálie, předali Pavla a některé jiné vězně setníkovi jménem Julius z pluku Jeho Veličenstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Nastoupili jsme na loď z Adramytteia, která měla plout do míst podél pobřeží Asie, a vypluli jsme. Byl s námi Makedoňan Aristarchos z Tesaloniky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Druhý den jsme dorazili do Sidónu. Julius se zachoval k Pavlovi laskavě a dovolil mu zajít k přátelům a přijmout jejich péči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Odtud jsme vypluli a plavili jsme se chráněni Kyprem, protože větry vály proti nám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Přepluli jsme moře podél Kilikie a Pamfylie a dorazili jsme do Myry v Lykii.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Tam setník našel alexandrijskou loď, která plula do Itálie, a nalodil nás na ni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Mnoho dní jsme pluli zvolna a stěží jsme se dostali proti Knidu. Protože nám vítr bránil, pluli jsme podél Salmóny chráněni Krétou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'S obtížemi jsme se kolem ní přeplavili a dostali jsme se na jedno místo, které se jmenovalo Krásné přístavy; blízko něho bylo město Lasaia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Protože uplynulo mnoho času a plavba již byla nebezpečná, neboť již minul i půst, Pavel jim domlouval:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, '„Muži, vidím, že plavba bude jistě spojena s nebezpečím a s velkou ztrátou nejen pro náklad a pro loď, ale i pro naše životy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Setník však důvěřoval více kormidelníkovi a majiteli lodi než tomu, co říkal Pavel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'A protože přístav nebyl vhodný k přezimování, většina se rozhodla odtamtud odplout a zkusit, zdali by se jim nepodařilo dorazit do Foiniku a tam přezimovat. Je to krétský přístav, otevřený k jihozápadu a severozápadu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'A když začal vát ⌈jižní vítr,⌉ mysleli si, že provedou svůj úmysl. Zvedli kotvy a pluli co nejblíže podél Kréty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Ale zanedlouho se od ní přihnal prudký vítr, který se nazývá Eurakylón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Loď jím byla stržena a nemohla mu čelit; proto jsme vzdali jakýkoliv odpor a nechali jsme se jím unášet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Dostali jsme se do závětří jakéhosi ostrůvku, který se jmenoval Kauda, a stěží jsme dokázali vytáhnout záchranný člun.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Když ho vytáhli, použili pomocných prostředků a podvázali loď. Protože se báli, aby nenajeli na syrtskou mělčinu, spustili plachty a takto ⌈se nechali unášet⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Protože s námi prudce zmítala bouře, začali druhý den vyhazovat náklad');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'a třetí den vlastníma rukama hodili do moře lodní zařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Po mnoho dní se neobjevovalo ani slunce ani hvězdy a dorážela na nás nemalá bouře, nakonec se již ztrácela veškerá naděje, že se zachráníme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Když už dlouho nic nejedli, postavil se Pavel uprostřed nich a řekl: „Muži, měli jste mne poslechnout a nevyplouvat z Kréty, a mohli jste si ušetřit toto nebezpečí a ztrátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Ale nyní vás vyzývám, abyste byli dobré mysli, neboť nikdo z vás nebude ztracen, nýbrž jen loď.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Tuto noc přišel ke mně anděl toho Boha, jemuž patřím a kterému sloužím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'a řekl: Neboj se, Pavle, ty se musíš postavit před císaře. A hle, Bůh ti daroval všechny ty, kteří se plaví s tebou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Proto, muži, buďte dobré mysli. Věřím totiž Bohu, že to bude tak, jak mi bylo oznámeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Musíme však narazit na nějaký ostrov.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Když jsme byli unášeni po Adrii už čtrnáctou noc, začali mít námořníci kolem půlnoci dojem, že se k nim přibližuje nějaká země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Spustili olovnici a zjistili hloubku dvacet sáhů. Když odpluli kousek dále, opět spustili olovnici a zjistili hloubku patnáct sáhů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Protože se báli, abychom někde nenarazili na skalnatá místa, vyhodili ze zádi čtyři kotvy a ⌈toužebně čekali, až nastane⌉ den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Když se námořníci pokoušeli utéci z lodi a spustili člun na moře pod záminkou, že chtějí vytahovat kotvy z přídi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'řekl Pavel setníkovi a vojákům: „Nezůstanou–li tito na lodi, vy nemůžete být zachráněni.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Tu vojáci přesekli lana u člunu a nechali jej uplavat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Než se začalo rozednívat, vybízel Pavel všechny, aby pojedli. Řekl: „Dnes již čtrnáctý den čekáte, zůstáváte hladoví a nic nejíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Proto vás vybízím, abyste pojedli; je to k vaší záchraně. Vždyť nikomu z vás se neztratí ani vlas z hlavy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, '⌈Po těch slovech⌉ vzal chléb, přede všemi vzdal Bohu díky, rozlomil jej a začal jíst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Všichni nabyli dobré mysli a také oni přijali pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Všech nás bylo na lodi dvě stě sedmdesát šest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Když se nasytili, odlehčovali loď ⌈tím, že vyhazovali⌉ obilí do moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Když však nastal den, nemohli poznat, co je to za zemi; viděli jen nějaký záliv s plochým pobřežím, k němuž zamýšleli s lodí najet, bude–li to možné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Odsekli kotvy a nechali je v moři. Zároveň rozvázali provazy u kormidel, zvedli proti větru přední plachtu a směřovali ke břehu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Najeli však na mělčinu a loď narazila na dno. Příď uvízla a zůstala nehybná, zatímco záď se začala bortit pod náporem vln.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Vojáci se rozhodli, že vězně zabijí, aby některý neuplaval a neutekl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Ale setník chtěl zachránit Pavla, a proto jim v tom úmyslu zabránil. Rozkázal, aby ti, kdo umějí plavat, se první vrhli do moře a vyšli na zem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'a ostatní aby se zachránili na prknech nebo na troskách lodi. A tak se stalo, že se všichni v pořádku dostali na břeh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Když jsme se zachránili, dozvěděli jsme se, že se ten ostrov jmenuje Malta.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Domorodci nám prokazovali neobyčejnou přívětivost. Zapálili oheň a všechny nás k němu pozvali, protože se schylovalo k dešti a bylo chladno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Když Pavel nasbíral něco chrastí a přiložil na oheň, vylezla před teplem zmije a pověsila se mu na ruku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Když domorodci uviděli, že mu zvíře visí na ruce, říkali si mezi sebou: „Tento člověk je jistě vrah. I když se zachránil z moře, Spravedlnost mu nedovolila žít.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Ale on setřásl zvíře do ohně a nic zlého ⌈se mu nestalo⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Oni očekávali, že oteče nebo náhle padne mrtev. Když však dlouho čekali a viděli, že se s ním nic zlého neděje, změnili svůj názor a říkali, že je to bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'V blízkosti toho místa měl pozemky první muž ostrova jménem Publius. Ten nás vzal k sobě a tři dny nás laskavě hostil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'I stalo se, že Publiův otec ležel a byl sužován horečkou a úplavicí. Pavel k němu vešel, s modlitbou na něho vložil ruce a uzdravil ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Když se toto stalo, přicházeli i ostatní nemocní z ostrova a byli uzdravováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Ti nás také zahrnuli mnohými projevy úcty, a když jsme vyplouvali, naložili nám věci pro naši potřebu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Po třech měsících jsme vypluli na alexandrijské lodi, která přezimovala na ostrově a měla ve znaku Blížence.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Připluli jsme do Syrakus a zůstali tam tři dny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Odtamtud jsme pluli podél pobřeží a dorazili do Regia. A když den nato začal vát jižní vítr, přijeli jsme druhého dne do Puteol.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Tam jsme nalezli bratry a ti nás požádali, abychom se zdrželi sedm dní. A tak jsme přišli do Říma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Když o nás tamní bratři uslyšeli, přišli nám naproti až k Appiovu tržišti a ke Třem hospodám. Jakmile je Pavel uviděl, vzdal díky Bohu a nabyl odvahy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Když jsme vstoupili do Říma, [setník předal vězně náčelníkovi tábora, ale] Pavlovi bylo dovoleno, aby bydlel v soukromí s vojákem, který ho hlídal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'I stalo se, že po třech dnech si svolal přední Židy. Když se sešli, řekl jim: „Muži bratři, já jsem se nedopustil ničeho proti našemu lidu ani proti otcovským zvykům, a přesto jsem byl jako vězeň vydán z Jeruzaléma do rukou Římanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Ti mne vyslechli a chtěli mě propustit, protože ⌈jsem se nedopustil žádného provinění, za které bych zasluhoval smrt⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Protože však tomu Židé odporovali, byl jsem nucen odvolat se k císaři, ale ne proto, že bych měl nějakou žalobu na svůj národ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Z toho důvodu jsem vás pozval, abych vás uviděl a promluvil s vámi, neboť pro naději Izraele nosím tento řetěz.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Ale oni mu řekli: „My jsme o tobě z Judska nedostali ani psaní, ani nám o tobě nikdo z bratrů nepřišel podat zprávu nebo povědět něco špatného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Rádi bychom však od tebe slyšeli, jaké je tvé smýšlení, neboť o této straně je nám známo, že jí všude odporují.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Určili mu tedy den a přišli k němu do jeho bytu ve větším počtu. Vykládal jim a dosvědčoval Boží království a od rána do večera je přesvědčoval o Ježíšovi z Mojžíšova zákona i z Proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Někteří se dávali přesvědčit tím, ⌈co jim říkal⌉, jiní nevěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Byli mezi sebou rozděleni a začali se rozcházet, když Pavel řekl jedno slovo: „Dobře promluvil Duch Svatý k vašim otcům skrze proroka Izaiáše:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Jdi k tomuto lidu a řekni: Vskutku uslyšíte, a jistě nepochopíte, ustavičně budete hledět, a určitě neuvidíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Neboť srdce tohoto lidu otupělo, ⌈stali se nedoslýchavými⌉ a své oči zavřeli, aby snad očima neuviděli a ušima neuslyšeli, srdcem nepochopili a neobrátili se a já je neuzdravil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Ať je vám tedy známo, že tato Boží záchrana byla poslána pohanům. Oni uslyší.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '[Když to řekl, Židé odešli a velmi se mezi sebou přeli.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Pavel zůstal po celé dva roky ve svém najatém bytě a přijímal všechny, kteří k němu přicházeli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'hlásal Boží království a učil o Pánu Ježíši Kristu se vší otevřeností a bez překážek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Pavel, otrok Krista Ježíše, povolaný apoštol, oddělený pro Boží evangelium,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'které Bůh předem zaslíbil skrze své proroky ve svatých Písmech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'evangelium o jeho Synu, jenž povstal podle těla z potomstva Davidova');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'a podle Ducha svatosti byl vzkříšením z mrtvých ustanoven za Syna Božího v moci, evangelium o Ježíši Kristu, našem Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Skrze něho jsme přijali ⌈milost a apoštolské poslání⌉ k poslušnosti víry pro jeho jméno mezi všemi národy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'mezi nimiž jste i vy, povolaní Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Všem těm, kdo jsou v Římě, milovaným Božím, povolaným svatým: Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Především děkuji svému Bohu skrze Ježíše Krista za vás všechny, že se zvěst o vaší víře šíří po celém světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Bůh, jemuž sloužím ve svém duchu v evangeliu jeho Syna, je mi svědkem, že se o vás stále zmiňuji');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'a vždy na svých modlitbách prosím, zda by se mi konečně jednou nepodařilo z Boží vůle přijít k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Toužím vás spatřit, abych vám mohl udělit nějaký duchovní dar k vaší posile,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'to jest abychom byli, až budu mezi vámi, navzájem povzbuzeni každý vírou toho druhého -- já vaší a vy mou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Nechci však, bratři, abyste nevěděli, že jsem se často rozhodl přijít k vám, ale až dosud mi bylo zabráněno, abych i mezi vámi sklidil nějaké ovoce jako mezi ostatními národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Jsem dlužníkem Řeků i barbarů, moudrých i nevědomých,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'a tak, pokud to záleží na mně, toužím ⌈posloužit evangeliem⌉ i vám, kteří jste v Římě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Nestydím se za evangelium, neboť je to Boží moc k záchraně pro každého, kdo věří, předně pro Žida, ale i pro Řeka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'V něm se zjevuje Boží spravedlnost z víry k víře, jak je napsáno: Spravedlivý z víry bude živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Boží hněv se zjevuje z nebe proti každé bezbožnosti a nepravosti lidí, kteří v nepravosti potlačují pravdu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'protože to, co lze o Bohu poznat, je jim zřejmé; Bůh jim to zjevil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Jeho věčnou moc a božství, ačkoli jsou neviditelné, lze totiž od stvoření světa jasně vidět, když lidé přemýšlejí o jeho díle, ⌈takže jsou⌉ bez výmluvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Ačkoli poznali Boha, neoslavili ho jako Boha ani mu neprojevili vděčnost, nýbrž upadli ve svých myšlenkách do marnosti a jejich nerozumné srdce ⌈se ocitlo ve tmě⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Tvrdí, že jsou moudří, ale stali se blázny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Zaměnili slávu neporušitelného Boha za zpodobení obrazu porušitelného člověka, ptáků, čtvernožců a plazů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Proto je Bůh skrze žádosti jejich srdcí vydal do nečistoty, aby navzájem zneuctívali svá těla;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'vyměnili Boží pravdu za lež, kořili se a sloužili tvorstvu více než Stvořiteli, jenž je požehnaný na věky. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Proto je Bůh vydal do potupných vášní. Jejich ženy vyměnily přirozený styk za nepřirozený');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'a stejně i muži zanechali přirozeného styku s ženou a ve své touze se rozpálili jeden k druhému, muži s muži páchají hanebnost a sami na sobě dostávají zaslouženou odplatu za svoje poblouzení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Právě tak, jako neuznali za dobré poznávat Boha, vydal je Bůh jejich neosvědčené mysli, aby dělali, co se nesluší:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Jsou naplněni veškerou nepravostí, [smilstvem,] ničemností, chamtivostí, špatností, jsou plni závisti, vraždy, sváru, lsti, zlomyslnosti, jsou donašeči,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'pomlouvači, ⌈Bohu odporní⌉, zpupní, domýšliví, chlubiví. Vymýšlejí zlé věci, neposlouchají rodiče,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'jsou nerozumní, věrolomní, bezcitní a nemilosrdní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Ačkoliv poznali Boží ustanovení, že ti, kdo dělají takové věci, jsou hodni smrti, nejenže je sami činí, ale dokonce to schvalují i jiným, kteří je dělají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Proto jsi bez omluvy, člověče, a to každý, kdo soudíš. V čem soudíš druhého, v tom odsuzuješ sám sebe, neboť soudíš, ale sám činíš totéž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Víme, že Boží soud je podle pravdy proti těm, kdo dělají takové věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Máš za to, člověče, který soudíš ty, kdo takové věci dělají, a sám činíš totéž, že unikneš Božímu soudu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Nebo pohrdáš bohatstvím jeho dobroty, shovívavosti a trpělivosti, a nevíš, že Boží dobrota tě vede k pokání?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Svou tvrdostí a nekajícným srdcem si shromažďuješ hněv ke dni hněvu a zjevení spravedlivého Božího soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'On odplatí každému podle jeho skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Těm, kteří s vytrvalostí v dobrém skutku hledají slávu, čest a neporušitelnost, dá věčný život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Avšak těm, kteří jsou sobečtí a neposlouchají pravdu, nýbrž poslouchají nepravost, odplatí hněvem a zuřivostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Soužení a úzkost padne na duši každého člověka, jenž působí zlo, předně na Žida, ale i na Řeka;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'avšak sláva, čest a pokoj připadne každému, kdo činí dobro, předně Židovi, a také Řekovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'U Boha není přijímání osob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Ti, kdo bez Zákona zhřešili, bez Zákona také zahynou; a ti, kdo zhřešili pod Zákonem, skrze Zákon budou souzeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Neboť u Boha ne jsou spravedliví ⌈ti, kdo Zákon slyší⌉, ale ospravedlněni budou ⌈ti, kdo jej plní⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Když totiž pohané, kteří nemají Zákon, přirozeným způsobem činí to, co Zákon požaduje, pak jsou sami sobě Zákonem, ač Zákon nemají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Ukazují, že mají dílo Zákona napsané ve svých srdcích. Jejich svědomí ⌈ bude svědčit spolu s myšlenkami, jež se navzájem obviňují nebo také obhajují,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'v den⌉, kdy Bůh skrze Ježíše Krista bude podle mého evangelia soudit, co je skryto v lidech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Jestliže se však nazýváš Židem, spoléháš na Zákon a chlubíš se Bohem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'poznáváš jeho vůli a vyučován ze Zákona rozpoznáváš to, na čem záleží;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'jsi o sobě přesvědčen, že jsi vůdcem slepých, světlem těch, kteří jsou ve tmě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'vychovatelem nerozumných, učitelem nedospělých, maje v Zákoně ztělesnění poznání a pravdy --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'ty tedy učíš druhého, a sám sebe neučíš? Ty hlásáš, že se nemá krást, a kradeš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Ty říkáš, že se nemá cizoložit, a cizoložíš? Ty si ošklivíš modly, a ⌈věci z jejich chrámů bereš⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Ty, který se chlubíš Zákonem, přestupováním Zákona zneuctíváš Boha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Neboť kvůli vám je jméno Boží mezi národy v opovržení, jak je napsáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Obřízka prospívá, jestliže děláš to, co přikazuje Zákon. Jsi–li však přestupníkem Zákona, tvá obřízka se stala neobřízkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Jestliže tedy ⌈neobřezaný člověk ⌉ zachovává ustanovení Zákona, nebude mu jeho neobřízka počítána za obřízku?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'A když člověk od přirozenosti neobřezaný plní Zákon, bude soudit tebe, který jsi skrze literu a obřízku přestupníkem Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Neboť pravý Žid není ten, kdo je jím navenek, a pravá obřízka ne ní ta, která je zjevná na těle;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'ale pravý Žid je ten, kdo je Židem uvnitř, a pravá obřízka je obřízka srdce Duchem, nikoli literou. Ten má chválu ne od lidí, nýbrž od Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Co má tedy Žid navíc? Nebo jaký je užitek obřízky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Veliký v každém ohledu. Předně ten, že Židům byly svěřeny Boží výroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Co tedy, když někteří ⌈byli nevěrní? Nezruší jejich nevěrnost věrnost Boží⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Naprosto ne! Ale ať je Bůh pravdivý a každý člověk lhář, jak je napsáno: Abys byl shledán spravedlivým ve svých slovech a zvítězil, když tě soudí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Jestliže však naše nepravost prokazuje Boží spravedlnost, co řekneme? Není Bůh nespravedlivý, když nás stíhá hněvem? Mluvím teď po lidsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Naprosto ne! Vždyť ⌈jak by pak Bůh mohl soudit⌉ svět?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Neboť jestliže se mou lží rozhojnila Boží pravda k jeho slávě, proč ⌈mám být⌉ ještě souzen jako hříšník?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'A ne bylo by to tak, jak nás někteří pomlouvají a tvrdí, že říkáme: „Čiňme zlo, aby přišlo dobro“? Jejich odsouzení je spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Co tedy? Máme (před pohany) výhodu? Vůbec ne! Vždyť jsme už dříve obvinili Židy i Řeky, že jsou všichni pod mocí hříchu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'jak je napsáno: Není spravedlivého, není ani jednoho,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'není, kdo by rozuměl, není, kdo by horlivě hledal Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Všichni se odchýlili, společně se stali nepotřebnými, není, kdo by činil dobro, není ani jeden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Jejich hrdlo je otevřený hrob, svými jazyky mluví lest, pod jejich rty je hadí jed.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Jejich ústa jsou plna kletby a hořkosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'jejich nohy jsou rychlé k prolití krve,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'na jejich cestách je zkáza a trápení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'cestu pokoje nepoznali;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'není bázně Boží před jejich očima.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Víme, že vše, co Zákon praví, praví těm, kdo jsou pod Zákonem, aby byla umlčena každá ústa a aby se před Bohem stal vinným celý svět,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'protože ze skutků Zákona nebude před ním ospravedlněn ⌈žádný člověk⌉, neboť skrze Zákon je poznání hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Nyní však je zjevena Boží spravedlnost bez Zákona, dosvědčovaná Zákonem i Proroky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Boží spravedlnost skrze víru Ježíše Krista pro všechny [a na všechny] ty, kdo věří. Není totiž rozdílu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'všichni zhřešili a postrádají Boží slávu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'ale jsou ospravedlňováni zadarmo jeho milostí skrze vykoupení, které je v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Jeho Bůh ustanovil za prostředek ⌈smíření skrze víru v jeho krev⌉, ⌈aby ukázal⌉ svou spravedlnost s ohledem na prominutí prohřešení, jež byla spáchána již dříve');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'v čase Boží shovívavosti, a aby ukázal svou spravedlnost v nynějším čase, takže sám je spravedlivý a ospravedlňuje toho, kdo žije z víry Ježíšovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Kde je tedy chlouba? Byla vyloučena! Jakým zákonem? Zákonem skutků? Nikoli, nýbrž zákonem víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Soudíme totiž, že člověk je ospravedlňován vírou bez skutků Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Nebo je snad Bůh pouze Bohem Židů? Není i Bohem pohanů? Ano, i pohanů!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, '⌈Vždyť je přece⌉ jeden Bůh, který ospravedlní obřezané z víry a neobřezané skrze víru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Rušíme tedy vírou Zákon? Naprosto ne! Naopak, Zákon potvrzujeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Co tedy řekneme? Čeho dosáhl Abraham, náš praotec podle těla?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Jestliže byl Abraham ospravedlněn ze skutků, má se čím chlubit, ale ne před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Neboť co praví Písmo? Uvěřil Abraham Bohu, a bylo mu to počteno za spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Tomu, kdo pracuje, se mzda nedává z milosti, nýbrž z povinnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Kdo však (pro svou spravedlnost) nepracuje, ale spoléhá na toho, který ospravedlňuje bezbožného, tomu se jeho víra pokládá za spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Tak i David vypravuje o blahoslavenství člověka, jemuž Bůh připisuje spravedlnost bez skutků:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Blahoslavení jsou ti, jejichž nepravosti byly odpuštěny a jejichž hříchy byly přikryty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Blahoslavený je muž, jemuž Pán vůbec nepřipočte hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Vztahuje se toto blahoslavenství jen na obřezané, nebo také na neobřezané? Říkáme totiž: Abrahamovi byla víra počtena za spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Jak mu tedy byla počtena? Byl už obřezán, či ještě ne? Ne byl obřezán, ale byl ještě ⌈před obřízkou⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'a znamení obřízky přijal jako pečeť spravedlnosti z víry, kterou měl ještě ⌈před obřízkou⌉, aby byl otcem všech věřících mezi neobřezanými, aby tak také jim byla připočtena spravedlnost');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'a aby byl otcem těch obřezaných, kteří ne jsou jen obřezáni, ale kráčejí také ve šlépějích víry, kterou měl náš otec Abraham ještě ⌈před obřízkou⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Zaslíbení, že bude dědicem světa, se Abrahamovi a jeho potomstvu ne dostalo skrze Zákon, nýbrž skrze spravedlnost z víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Neboť jsou –li dědici ti, kteří jsou jimi ze Zákona, je víra zbytečná a zaslíbení je zrušeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Zákon působí hněv. Kde však není Zákon, tam není ani přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Dědictví je proto z víry, aby bylo podle milosti a aby bylo to to zaslíbení platné pro veškeré potomstvo, nejen pro ty, kdo jsou ze Zákona, ale i pro ty, kdo jsou z víry Abrahama, jenž je otcem nás všech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'jak je napsáno: Ustanovil jsem tě za otce mnohých národů. Je otcem před tím, jemuž uvěřil, před Bohem, který oživuje mrtvé a povolává to, co není, jako by bylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'On proti naději na základě naděje uvěřil, že se stane otcem mnohých národů podle toho, co je řečeno: Tak bude tvé potomstvo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'A neochabl ve víře, ani když mu bylo asi sto let; ⌈ ačkoliv pohleděl⌉ na své již umrtvené tělo a na ⌈odumřelé lůno Sářino⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'nezačal v nevěře o Božím zaslíbení pochybovat, ale byl posílen ⌈ve víře⌉, když vzdal slávu Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'a nabyl pevného přesvědčení, že to, co Bůh zaslíbil, je mocen i učinit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Proto mu to také bylo počteno za spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'To, že mu to bylo počteno za spravedlnost, nebylo však napsáno jen kvůli němu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'nýbrž také kvůli nám, kterým to má být počítáno, nám, kteří spoléháme na toho, jenž vzkřísil z mrtvých Ježíše, našeho Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'On byl vydán pro naše provinění a vzkříšen pro naše ospravedlnění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Když jsme tedy byli ospravedlněni z víry, máme pokoj s Bohem skrze našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Skrze něho jsme [vírou] získali přístup k této milosti, v níž stojíme a chlubíme se nadějí Boží slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'A nejen to, chlubíme se také souženími, neboť víme, že soužení působí vytrvalost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'vytrvalost osvědčenost a osvědčenost naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'A naděje nezahanbuje, neboť Boží láska je vylita v našich srdcích skrze Ducha svatého, který nám byl dán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Vždyť když jsme ještě byli bezmocní, zemřel Kristus v určený čas za bezbožné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Sotva kdo podstoupí smrt za spravedlivého, i když za dobrého by se snad někdo i odvážil zemřít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Bůh však projevuje svou lásku k nám tím, že Kristus za nás zemřel, když jsme ještě byli hříšní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Tím spíše tedy nyní, když jsme byli ospravedlněni jeho krví, budeme skrze něho zachráněni od Božího hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Jestliže jsme jako nepřátelé byli usmířeni s Bohem smrtí jeho Syna, tím spíše ⌈jako usmíření⌉ budeme zachráněni ⌈jeho životem⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'A nejen to, chlubíme se také Bohem skrze našeho Pána Ježíše Krista, skrze něhož jsme nyní přijali usmíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Proto jako skrze jednoho člověka vešel do světa hřích a skrze hřích smrt, tak se také smrt rozšířila na všechny lidi, protože všichni zhřešili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Do Zákona hřích byl ve světě, ale nezapočítává se, když není Zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Přesto smrt vládla od Adama až po Mojžíše i nad těmi, kdo nezhřešili podobným přestoupením jako Adam; ten je předobrazem toho budoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Avšak s darem milosti tomu není tak jako s proviněním. Jestliže proviněním jednoho člověka mnozí zemřeli, mnohem více se na mnohé rozhojnila ⌈Boží milost⌉ a dar spravedlnosti v milosti toho jednoho člověka, Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'A s darem tomu není tak jako s tím, co přišlo skrze jednoho člověka, který zhřešil. Rozsudek nad jedním proviněním přinesl odsouzení, kdežto dar milosti z mnohých provinění vedl k ospravedlnění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Jestliže proviněním jednoho člověka smrt vládla skrze toho jednoho, tím spíše ti, kteří přijímají hojnost milosti a dar spravedlnosti, budou vládnout v životě skrze toho jednoho, Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'A tak tedy: jako skrze provinění jednoho člověka přišlo na všechny lidi odsouzení, tak i skrze spravedlivý čin jednoho člověka přišlo na všechny lidi ⌈ospravedlnění k životu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Jako se skrze neposlušnost jednoho člověka mnozí stali hříšnými, tak se také skrze poslušnost jednoho stanou mnozí spravedlivými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Do toho vstoupil Zákon, aby se provinění rozhojnilo. A kde se rozhojnil hřích, tam se nadmíru rozhojnila milost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'aby tak, jako vládl hřích ve smrti, i milost vládla skrze spravedlnost k životu věčnému skrze Ježíše Krista, našeho Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Co tedy řekneme? Máme zůstávat v hříchu, aby se rozhojnila milost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Naprosto ne! Jak bychom my, kteří jsme hříchu zemřeli, v něm ještě mohli žít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Což nevíte, že my všichni, kteří jsme byli pokřtěni v Krista Ježíše, jsme byli pokřtěni v jeho smrt?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Skrze křest jsme byli spolu s ním pohřbeni ve smrt, abychom i my, tak jako byl Kristus skrze slávu Otce vzkříšen z mrtvých, ⌈vstoupili na cestu nového života⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Neboť jestliže jsme se stali s ním srostlými ⌈ tím, že jsme mu byli podobni ve ⌉ smrti, jistě mu budeme podobni i v zmrtvýchvstání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, '⌈A víme⌉, že náš starý člověk byl spolu s ním ukřižován, aby tělo hříchu ⌈bylo zbaveno sil⌉ a my už hříchu neotročili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Vždyť ten, kdo zemřel, je ⌈zproštěn hříchu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Jestliže jsme s Kristem zemřeli, věříme, že spolu s ním budeme také žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, '⌈A víme⌉, že Kristus, když byl vzkříšen z mrtvých, už neumírá; smrt nad ním už nepanuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Neboť smrtí, kterou zemřel, zemřel hříchu jednou provždy; a život, který žije, žije Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Tak i vy se považujte za mrtvé hříchu, ale za živé Bohu v Kristu Ježíši, [našem Pánu].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Ať tedy hřích nevládne ve vašem smrtelném těle, tak abyste ⌈poslouchali jeho žádosti⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'ani hříchu nepropůjčujte své údy za nástroje nepravosti, ale vydejte sami sebe Bohu jako ⌈ ti, kteří byli mrtví, a ožili⌉, a své údy vydejte Bohu za nástroje spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Hřích nad vámi nebude panovat; vždyť nejste pod Zákonem, ale pod milostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Co tedy? ⌈Budeme hřešit⌉, protože nejsme pod Zákonem, ale pod milostí? Naprosto ne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Což nevíte, že komu se propůjčujete jako otroci k poslušnosti, koho posloucháte, toho jste otroky: buď hříchu, který vede ke smrti, nebo poslušnosti, která vede ke spravedlnosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Díky Bohu, že jste sice byli otroky hříchu, ale stali jste se ze srdce poslušnými vzoru učení, jemuž jste byli svěřeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Byli jste osvobozeni od hříchu a stali jste se otroky spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Pro slabost vašeho těla to říkám po lidsku: Jako jste propůjčili své údy za otroky nečistotě a nepravosti k činění nepravosti, tak nyní předložte své údy za otroky spravedlnosti k posvěcení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Když jste byli otroky hříchu, byli jste svobodni od spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Jaký jste tehdy měli užitek z těch věcí, za něž se nyní stydíte? Neboť jejich konec je smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Avšak nyní, když jste byli osvobozeni od hříchu a stali jste se otroky Božími, máte svůj užitek ku posvěcení a vašim cílem je věčný život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Mzdou hříchu je smrt, ale darem Boží milosti je život věčný v Kristu Ježíši, našem Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Což nevíte, bratři -- vždyť mluvím k těm, kteří znají Zákon -- že zákon panuje nad člověkem, jen pokud je živ?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Vdaná žena je zákonem vázána k žijícímu muži; jestliže však její muž zemře, je tohoto zákona zproštěna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Nuže tedy, pokud je její muž naživu, oddá–li se jinému muži, bude prohlášena za cizoložnici. Jestliže však její muž zemře, je od toho zákona svobodná, takže nebude cizoložnicí, když se oddá jinému muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Právě tak, moji bratři, jste i vy zemřeli Zákonu skrze tělo Kristovo, abyste se oddali jinému, tomu, který byl vzkříšen z mrtvých, abychom přinesli ovoce Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Neboť když jsme byli v těle, působily v našich údech hříšné vášně probouzené Zákonem, aby přinesly ovoce k smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Nyní však jsme byli zproštěni Zákona, když jsme zemřeli tomu, čím jsme byli pevně drženi, ⌈takže sloužíme⌉ v novotě Ducha, a ne ve zvetšelosti litery.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Co tedy řekneme? Je Zákon hříchem? Naprosto ne! Ale hřích bych nepoznal jinak než skrze Zákon. Vždyť o žádostivosti bych nevěděl, kdyby Zákon neříkal: „Nepožádáš.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Hřích využil příležitosti, které se mu dostalo skrze to přikázání, a probudil ve mně veškerou žádostivost; bez Zákona je totiž hřích mrtev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Já jsem kdysi žil bez Zákona; když však přišlo přikázání, hřích ožil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'a já jsem zemřel. I ukázalo se, že přikázání, které mělo být k životu, bylo mi k smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Neboť hřích využil příležitosti, které se mu skrze přikázání dostalo, oklamal mě a skrze ně mě zabil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'A tak Zákon je svatý i přikázání je svaté, spravedlivé a dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Tedy to dobré mi způsobilo smrt? Naprosto ne! Ale hřích, aby se ukázal jako hřích, působil mi tím dobrým smrt, aby se hřích skrze přikázání stal nadmíru hříšným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Neboť víme, že Zákon je duchovní, já však jsem tělesný, prodaný ⌈ do otroctví hříchu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Nerozumím tomu, co dělám; vždyť nedělám to, co chci, nýbrž činím to, co nenávidím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Činím–li však to, co nechci, souhlasím se Zákonem, že je dobrý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Ale pak již to nekonám já sám, nýbrž hřích, který ve mně přebývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Vím totiž, že ve mně, to jest v mém těle, nepřebývá dobré; neboť chtít dobro dokážu, ale konat už ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Vždyť nečiním dobro, které chci, nýbrž zlo, které nechci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Jestliže však činím to, co nechci, nedělám to již já, ale hřích, který ve mně přebývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Nalézám tedy tento zákon: Když chci činit dobro, je při mně zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Podle vnitřního člověka radostně souhlasím se zákonem Božím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Vidím však jiný zákon ve svých údech,který bojuje proti zákonu mé mysli a činí mě zajatcem zákona hříchu,jenž je v mých údech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Já nešťastný člověk! Kdo mne vysvobodí z těla této smrti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Bohu buď dík skrze Ježíše Krista, našeho Pána. Tak tedy tentýž já svou myslí sloužím jako otrok zákonu Božímu, ale svým tělem zákonu hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Nyní tedy není žádného odsouzení pro ty, kteří jsou v Kristu Ježíši [a nechodí podle těla, ale podle Ducha].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Vždyť zákon Ducha života v Kristu Ježíši mě osvobodil od zákona hříchu a smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Neboť co bylo Zákonu nemožné, protože byl bezmocný kvůli tělu, to učinil Bůh, když poslal svého Syna v podobnosti těla hříchu a jako oběť za hřích a odsoudil hřích v těle,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'aby byl požadavek Zákona naplněn v nás, kteří nechodíme podle těla, ale podle Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Ti, kdo jsou živi podle těla, mají na mysli věci těla; ale ti, kdo jsou živi podle Ducha, myslí na věci Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Myšlení těla znamená smrt, myšlení Ducha život a pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Myšlení těla je totiž v nepřátelství vůči Bohu, neboť se nepodřizuje Božímu zákonu, ba ani nemůže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Ti, kteří jsou v těle, se Bohu líbit nemohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Vy však nejste v těle, ale v Duchu, pokud ve vás vskutku Duch Boží přebývá. Jestliže však někdo nemá Kristova ducha, ten není jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Je –li však Kristus ve vás, je sice tělo mrtvé kvůli hříchu, ale duch je živý kvůli spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Jestliže ve vás přebývá Duch toho, který vzkřísil Ježíše z mrtvých, pak ten, který vzkřísil [Ježíše] Krista z mrtvých, oživí i vaše smrtelná těla skrze svého Ducha, který ve vás přebývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Nuže tedy, bratři, jsme dlužníky, ale ne těla, abychom podle těla žili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Jestliže žijete podle těla, je vám souzeno zemřít; jestliže však Duchem usmrcujete činy těla, budete žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Neboť všichni ti, kdo jsou vedeni Duchem Božím, jsou Boží synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Nepřijali jste ducha otroctví, abyste se opět báli, nýbrž přijali jste Ducha synovství, v němž voláme: Abba, Otče!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Sám ten Duch ⌈svědčí spolu s naším duchem⌉, že jsme děti Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Jsme –li však děti, jsme i dědicové -- dědicové Boží a spoludědicové Kristovi, pokud vskutku spolu s ním trpíme, abychom spolu s ním byli také oslaveni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Mám totiž za to, že utrpení nynějšího času se nedají srovnat s budoucí slávou, která na nás má být zjevena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Vždyť celé tvorstvo toužebně vyhlíží a očekává zjevení Božích synů--');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'neboť tvorstvo bylo poddáno marnosti; ne dobrovolně, ale kvůli tomu, který je poddal -- a má naději,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'že i ono samo bude vysvobozeno z otroctví zániku do slavné svobody Božích dětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Víme přece, že celé tvorstvo až dodnes společně sténá a pracuje k porodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'A nejen to, ale i my, kteří máme prvotiny Ducha, sami v sobě sténáme, očekávajíce synovství, to jest vykoupení svého těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, '⌈V té naději⌉ jsme byli zachráněni; naděje však, kterou je vidět, není naděje. Kdo něco vidí, ⌈proč by v to ještě doufal⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Ale doufáme–li v to, co nevidíme, očekáváme to s vytrvalostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'A stejně tak i Duch se spolu s námi ujímá naší slabosti. Vždyť my nevíme, jak a za co se máme modlit, ale sám ten Duch se [za nás] přimlouvá vzdechy, ⌈které nelze vyjádřit slovy⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'A ten, který zkoumá srdce, ví, jaké je myšlení Ducha, totiž že se podle Boha přimlouvá za svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Víme, že těm, kteří milují Boha, ⌈všechny věci spolu působí k dobrému,⌉ těm, kdo jsou povoláni podle jeho předsevzetí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Neboť ty, které předem poznal, také předem určil, aby byli připodobněni obrazu jeho Syna, tak aby on byl prvorozený mezi mnoha bratřími;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'které předem určil, ty také povolal; a které povolal, ty také ospravedlnil, a které ospravedlnil, ty také oslavil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Co tedy k tomu řekneme? Je–li Bůh pro nás, kdo je proti nám?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'On neušetřil vlastního Syna, ale za nás za všecky ho vydal. Jak by nám spolu s ním nedaroval všechno?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kdo bude žalovat na Boží vyvolené? Vždyť Bůh je ten, kdo ospravedlňuje!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kdo je ten, který je odsoudí? Vždyť Kristus Ježíš, který zemřel a byl i vzkříšen [z mrtvých], je na pravici Boží a přimlouvá se za nás!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kdo nás odloučí od Kristovy lásky? Soužení nebo úzkost, pronásledování nebo hlad, nahota, nebezpečí nebo meč?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Jak je napsáno: Celý den jsme pro tebe ⌈vydáváni na smrt⌉, ⌈pokládají nás⌉ za ovce určené na porážku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Ale v tomto všem dokonale vítězíme skrze toho, který si nás zamiloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Jsem přesvědčen, že ani smrt ani život, ani andělé ani mocnosti, ani přítomnost ani budoucnost, ani moci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'ani výšina ani hlubina, ani žádné jiné stvoření nás nebude moci odloučit od Boží lásky, která je v Kristu Ježíši, našem Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Mluvím pravdu v Kristu, nelžu, a ⌈dosvědčuje mi to ⌉ mé svědomí v Duchu Svatém,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'že mám veliký zármutek a neustálou bolest ve svém srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, '⌈Přál bych si⌉, abych já sám byl ⌈zavržen od Krista⌉ místo svých bratrů, svých příbuzných podle těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Jsou to Izraelci, jim patří synovství, sláva i smlouvy, jim byl dán Zákon, služba a zaslíbení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'jejich jsou otcové a z nich podle těla pochází Mesiáš, který je nade vším, Bůh požehnaný na věky. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Ne že by Boží slovo selhalo. Neboť ne všichni ti, kteří pocházejí z Izraele, jsou Izrael,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'ani ne proto, že jsou potomstvem Abrahamovým, jsou všichni jeho dětmi, nýbrž v Izákovi bude tobě povoláno símě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'To jest: Božími dětmi ne jsou děti těla, nýbrž za potomky se považují děti zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Zaslíbení, kterým bylo toto slovo: V tomto čase přijdu, a Sára bude mít syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'A nejen to, ale také Rebeka z jednoho muže otěhotněla, totiž z našeho otce Izáka;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'ještě se jí synové nenarodili a neučinili nic dobrého ani zlého, aby však zůstalo potvrzeno Boží předsevzetí, které je podle vyvolení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'ne ze skutků, nýbrž z toho, kdo povolává, bylo jí řečeno, že starší bude sloužit mladšímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Jak je napsáno: Jákoba jsem miloval, ale Ezaua jsem nenáviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Co tedy řekneme? Ne ní u Boha nespravedlnost? Naprosto ne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Mojžíšovi říká: Smiluji se, nad kým se smiluji, a slituji se, nad kým se slituji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Ne záleží tedy na tom, kdo chce, ani na tom, kdo běží, ale na Bohu, který se smilovává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Písmo praví faraonovi: Právě proto jsem tě vzbudil, abych na tobě ukázal svou moc a aby mé jméno bylo rozhlášeno po celé zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'A tak se slitovává nad kým chce, a koho chce, toho zatvrzuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Řekneš mi tedy: Proč si ještě stěžuje? Vždyť kdo odolal jeho vůli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Člověče, kdo vlastně jsi, že odmlouváš Bohu? Což výtvor řekne svému tvůrci: Proč jsi mě udělal takto?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Což nemá hrnčíř ve své moci hlínu, aby z téže hroudy učinil jednu nádobu ke cti a druhou k hanbě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Což ne chtěl Bůh ukázat svůj hněva uvést ve známost svou moc, a proto s velikou trpělivostí snášel nádoby hněvu připravené k záhubě?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'A také proto, aby oznámil bohatství své slávy na nádobách milosrdenství, které předem připravil k slávě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'totiž na nás, které také povolal nejen ze Židů, ale i z pohanů?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Jak praví u Ozeáše: Lid, který není můj, nazvu svým lidem, a tu, která nebyla milována, nazvu milovanou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'a stane se, že na místě, kde jim bylo řečeno: Vy ne jste můj lid, tam budou nazváni syny Boha živého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Izaiáš však volá nad Izraelem: Kdyby bylo synů Izraele jako písku v moři, jen ostatek bude zachráněn,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'neboť úplně a rychle vykoná Pán své slovo na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'A jak to Izaiáš předpověděl: Kdyby nám Pán Sabaoth nezanechal símě, byli bychom jako Sodoma, Gomoře bychom byli podobni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Co tedy řekneme? To, že pohané, kteří neusilovali o spravedlnost, dosáhli spravedlnosti, a to spravedlnosti, která je z víry;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Izrael však, ačkoli usiloval o zákon spravedlnosti, k cíli Zákona nedospěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Proč? Protože ne vycházel z víry, nýbrž jakoby ze skutků [Zákona]. Narazili na kámen úrazu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'jak je napsáno: Hle, kladu na Siónu kámen úrazu a skálu pohoršení, a [každý,] kdo v něho věří, nebude zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Bratři, touhou mého srdce a prosbou k Bohu za ně [je], aby byli zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Neboť jim vydávám svědectví, že mají horlivost pro Boha, ale ne podle pravého poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Protože neznají Boží spravedlnost, a místo toho usilují postavit svou vlastní [spravedlnost], nepodřídili se spravedlnosti Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Vždyť Kristus je konec Zákona k spravedlnosti pro každého, kdo věří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Mojžíš píše o spravedlnosti, která je ⌈založena na Zákonu⌉: Člověk, který je bude činit, bude v nich živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Avšak spravedlnost ⌈založená na víře⌉ mluví takto: Neříkej si ve svém srdci: kdo vystoupí do nebe? -- to je ⌈ jako přivést⌉ Krista dolů --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'nebo: kdo sestoupí do propasti? -- to je ⌈ jako vyvést⌉ Krista z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Ale co praví? Blízko tebe je to slovo, ve tvých ústech a ve tvém srdci; je to slovo víry, které hlásáme:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Vyznáš–li svými ústy Pána Ježíše a uvěříš–li ve svém srdci, že ho Bůh vzkřísil z mrtvých, budeš zachráněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Srdcem se věří k spravedlnosti a ústy se vyznává k záchraně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'neboť Písmo praví: Každý, kdo v něho věří, nebude zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Není rozdílu mezi Židem a Řekem: Vždyť ⌈nade všemi⌉ je týž Pán, štědrý ke všem, kdo ho vzývají,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'neboť každý, kdo by vzýval Pánovo jméno, bude zachráněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Ale jak mohou vzývat toho, v něhož neuvěřili? A jak mohou uvěřit v toho, o kom neslyšeli? A jak mohou slyšet bez toho, kdo hlásá?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'A jak mohou hlásat, nebyli–li posláni? Jak je napsáno: Jak jsou krásné nohy [těch, kteří zvěstují pokoj,] těch, kteří zvěstují dobré noviny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Ale ne všichni uposlechli evangelium. Neboť Izaiáš praví: Pane, kdo uvěřil naší zvěsti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Víra je tedy ze slyšení zvěsti a zvěst skrze slovo Kristovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Já však pravím: Což neslyšeli? Ovšemže slyšeli! Do celé země pronikl jejich hlas, do nejzazších končin obydleného světa jejich výroky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Ptám se však: Což to Izrael nepochopil? Už Mojžíš praví: Vzbudím ve vás žárlivost na národ, který není národem, proti národu nerozumnému vás popudím k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'A Izaiáš odvážně říká: Dal jsem se nalézt těm, kteří mě nehledali, dal jsem se poznat těm, kteří se po mně neptali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'O Izraeli však říká: Po celý den jsem vztahoval své ruce k lidu neposlušnému a odmlouvajícímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Pravím tedy: Zavrhl snad Bůh svůj lid? Naprosto ne! Vždyť i já jsem Izraelec, potomek Abrahamův, z kmene Benjamínova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Bůh nezavrhl svůj lid, který předem poznal. Což nevíte, co praví Písmo ⌈o Eliášovi, když vypráví ⌉, jak si stěžuje Bohu na Izrael?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Pane, tvé proroky zabili, tvé oltáře rozbořili; já jediný jsem zůstal, a i o mou duši usilují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Co mu však řekl božský výrok? Ponechal jsem si sedm tisíc mužů, kteří nesklonili koleno před Baalem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Tak i v nynějším čase zůstal ostatek lidu podle vyvolení z milosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Jestliže však z milosti, pak již ne ze skutků, jinak by milost již nebyla milostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Co tedy? Oč Izrael usiluje, toho nedosáhl, ale dosáhli toho vyvolení. Ostatní byli zatvrzeni,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'jak je napsáno: Bůh jim dal ducha otupělosti, oči, aby neviděli, uši, aby neslyšeli, až do dnešního dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'A David praví: Ať se jim jejich stůl stane léčkou a pastí, kamenem úrazu a odplatou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Ať se jejich oči zatmějí, aby neviděli, a jejich záda sehni navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Ptám se tedy: Což klopýtli proto, aby padli? Naprosto ne! Ale jejich proviněním se dostalo záchrany pohanům, aby to vzbudilo jejich žárlivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Jestliže jejich provinění znamená bohatství pro svět a jejich porážka bohatství ⌈pro pohany⌉, oč více bude znamenat jejich plnost!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Ale vám, pohanům, pravím: Právě proto, že jsem apoštolem pohanů, oslavuji svoji službu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'zdali bych nějak nemohl vzbudit žárlivost ⌈svých pokrevních bratrů⌉ a některé z nich zachránit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Neboť jestliže jejich zavržení znamenalo smíření světa, co jiného bude znamenat jejich přijetí než život ⌈ po zmrtvýchvstání⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Jsou –li prvotiny svaté, je svaté i těsto; je –li kořen svatý, jsou svaté i větve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Jestliže však některé větve byly vylomeny a ty, planá oliva, jsi byl naroubován na jejich místo a stal ses účastníkem kořene [i] tučnosti olivy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'nevynášej se nad ty větve! Jestliže se vynášíš, nezapomeň, že ty neneseš kořen, nýbrž kořen tebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Řekneš tedy: Větve byly vylomeny, abych já byl naroubován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Dobře. Nevěrou byly vylomeny, ty však stojíš vírou. Nepovyšuj se, ale boj se!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Jestliže Bůh neušetřil přirozených větví, ani tebe [nijak] neušetří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Považ tedy dobrotu i přísnost Boží: přísnost k těm, kteří padli, avšak dobrotu Boží k tobě, budeš–li se jeho dobroty držet; jinak budeš vyťat i ty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'A oni, nezůstanou–li v nevěře, budou naroubováni, neboť Bůh má moc je znovu naroubovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Jestliže tys byl vyťat z olivy od přírody plané a proti přírodě naroubován na olivu ušlechtilou, tím spíše budou na svou vlastní olivu naroubováni ti, kteří k ní od přírody patří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Nechci totiž, bratři, abyste nevěděli o tomto tajemství -- abyste nebyli moudří sami u sebe -- že část Izraele se zatvrdila, dokud nevejde plnost pohanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, '⌈Bude však⌉ zachráněn celý Izrael, jak je napsáno: Ze Siónu přijde Vysvoboditel, odvrátí od Jákoba bezbožnosti;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'a to bude ⌈má smlouva⌉ s nimi, až odejmu jejich hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Podle evangelia jsou nepřátelé kvůli vám; ale podle vyvolení zůstávají milovanými pro své otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Vždyť dary milosti a Boží povolání jsou neodvolatelné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Jako vy jste kdysi neposlouchali Boha, nyní však se vám dostalo milosrdenství pro jejich neposlušnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'tak i oni nyní upadli v neposlušnost pro milosrdenství ⌈prokázané vám⌉, aby také došli milosrdenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Bůh totiž všechny uzavřel pod neposlušnost, aby se nade všemi slitoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ó hlubino bohatství a moudrosti i poznání Božího! Jak nevyzpytatelné jsou jeho soudy a nepostižitelné jeho cesty!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Kdo poznal Pánovu mysl a kdo se stal jeho rádcem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Anebo kdo mu dal něco dopředu, aby mu to on musel odplatit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Vždyť z něho a skrze něho a ⌈pro něho⌉ jsou všechny věci. Jemu buď sláva na věky. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Vybízím vás tedy, bratři, skrze milosrdenství Boží, abyste vydali svá těla v oběť živou, svatou a příjemnou Bohu; to je vaše rozumná služba Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'A nepřipodobňujte se tomuto věku, nýbrž proměňujte se obnovou [své] mysli, abyste mohli zkoumat, co je ⌈Boží vůle, co je dobré, přijatelné a dokonalé⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Skrze milost, která mi byla dána, pravím každému, kdo je mezi vámi: Nesmýšlejte výš, než je třeba smýšlet, ale smýšlejte tak, abyste jednali rozumně, podle toho, jakou míru víry udělil každému Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Jako máme v jednom těle mnoho údů a všechny ty údy nemají stejný úkol,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'tak i my, i když je nás mnoho, jsme jedno tělo v Kristu, ale jednotlivě jsme údy jeden druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Máme rozdílné dary podle milosti, která nám byla dána: Má –li někdo proroctví, ať ho užívá v souhlase s vírou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Má –li službu, ⌈ať slouží⌉. Je –li vyučující, ⌈ať učí⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Má –li dar povzbuzování, ⌈ať povzbuzuje⌉. Kdo rozdává, ať rozdává upřímně. Kdo stojí v čele, ⌈ať je horlivý⌉. Kdo prokazuje milosrdenství, ať to činí radostně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Láska ať je bez přetvářky. Ošklivte si zlo, lněte k dobrému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Vroucně se navzájem milujte bratrskou láskou, ⌈v prokazování úcty⌉ předcházejte jeden druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'V horlivosti neochabujte, buďte vroucího ducha, služte Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'V naději se radujte, v soužení buďte trpěliví, v modlitbě vytrvalí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Sdílejte se se svatými v jejich potřebách, usilujte o pohostinnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Dobrořečte těm, kteří vás pronásledují, dobrořečte a nezlořečte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Radujte se s radujícími, plačte s plačícími.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, '⌈Mějte jeden k druhému stejný ohled.⌉ Nepomýšlejte na vysoké věci, ale nechte se vést k obyčejným. Nebuďte moudří sami podle sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Nikomu neodplácejte zlým za zlé. Přede všemi lidmi mějte na mysli ušlechtilé věci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Je–li možno, pokud to záleží na vás, mějte pokoj se všemi lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Nemstěte se sami, milovaní, nýbrž dejte místo Božímu hněvu, neboť je napsáno: Mně patří pomsta, já odplatím, praví Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Ale: Jestliže má tvůj nepřítel hlad, dávej mu jíst, a má–li žízeň, dávej mu pít; když to budeš činit, nasypeš žhavé uhlí na jeho hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Nenech se přemáhat zlem, ale přemáhej zlo dobrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Každá duše ať se podřizuje nadřízeným autoritám, neboť není autority, leč od Boha. Ty, které jsou, jsou zřízeny od Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'takže ten, kdo se staví proti autoritě, odporuje Božímu nařízení. Ti, kdo mu odporují, přivolávají na sebe soud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Vládcové nejsou postrachem dobrému jednání, nýbrž zlému. Chceš, aby ses ne musel bát autority? Čiň dobré, a budeš mít od ní chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Vždyť je Božím služebníkem pro tvé dobro. Jednáš–li však zle, boj se, neboť ne nadarmo nosí meč. Je Božím služebníkem, vykonavatelem hněvu nad tím, kdo činí zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Proto je nutno podřizovat se, a to nejen kvůli tomu hněvu, nýbrž i kvůli svědomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Proto také platíte daně, neboť vládcové jsou Božími služebníky a právě tomu se vytrvale věnují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Dejte každému, co jste povinni: komu daň, tomu daň, komu clo, tomu clo, komu bázeň, tomu bázeň, komu čest, tomu čest.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Nikomu nebuďte nic dlužni, než abyste se navzájem milovali, neboť ten, kdo miluje druhého, naplnil Zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Vždyť přikázání nebudeš cizoložit, nebudeš vraždit, nebudeš krást, nebudeš žádat, a je –li ještě nějaké jiné přikázání, jsou shrnuta v tomto slovu: Budeš milovat svého bližního jako sebe samého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Láska bližnímu nepůsobí nic zlého. Naplněním Zákona je tedy láska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Víte také, jaký je čas, že už nastala hodina, abyste procitli ze spánku; vždyť nyní je naše záchrana blíže, než když jsme uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Noc pokročila, den se přiblížil. Odložme proto skutky tmy a oblečme zbroj světla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Žijme řádně jako ve dne: ne ⌈v hýření a opilství⌉, ne v chlípnostech a bezuzdnostech, ne ve sváru a závisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Nýbrž oblečte se v Pána Ježíše Krista a nepečujte o tělo, abyste vyhovovali jeho žádostem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Slabého ve víře přijímejte, ale ⌈ne proto, abyste posuzovali jeho názory⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Někdo věří, že může jíst všechno, slabý však jí jen zeleninu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Ten, kdo jí, nechť nezlehčuje toho, kdo nejí, a kdo nejí, nechť nesoudí toho, kdo jí. Vždyť Bůh ho přijal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Kdo jsi ty, že soudíš cizího sluhu? ⌈Pro svého pána⌉ stojí nebo padá. A on bude stát, neboť Pán je mocen ho postavit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Někdo považuje jeden den za důležitější než druhý, jiný považuje všechny dny za stejně důležité. Každý nechť je plně přesvědčen ⌈o tom, jak sám smýšlí⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Kdo zachovává určitý den, zachovává jej Pánu. Kdo jí, jí Pánu, neboť děkuje Bohu; a kdo nejí, nejí Pánu a také děkuje Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Nikdo z nás nežije sám sobě a nikdo sám sobě neumírá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Neboť žijeme–li, žijeme Pánu, umíráme–li, umíráme Pánu. Ať tedy žijeme či umíráme, patříme Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Vždyť proto Kristus zemřel a ožil, aby se stal Pánem mrtvých i živých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Ty pak, proč soudíš svého bratra? Nebo i ty, proč zlehčuješ svého bratra? Všichni se přece postavíme před soudnou stolici Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Neboť je napsáno: Jakože jsem živ, praví Pán, skloní se ⌈přede mnou⌉ každé koleno a každý jazyk vyzná Bohu chválu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Každý z nás tedy sám za sebe vydá početBohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Nesuďme už tedy jeden druhého, ale raději posuďte, jak si počínat, abyste nekladli bratru do cesty kámen úrazu nebo svod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Vím a jsem přesvědčen v Pánu Ježíši, že nic není nečisté samo v sobě; jen tomu, kdo něco pokládá za nečisté, je to nečisté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Zarmucuje–li se tvůj bratr kvůli pokrmu, nejednáš již podle lásky. Neuváděj svým pokrmem do záhuby toho, za nějž Kristus zemřel!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Ať se nemluví zle o tom, co je pro vás dobré.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Vždyť Boží království není pokrm a nápoj, nýbrž spravedlnost, pokoj a radost v Duchu Svatém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Kdo takto slouží Kristu, je milý Bohu a ⌈lidé ho mají v úctě⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'A tak usilujme o to, co vede k pokoji, a o to, co slouží k společnému budování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Neboř kvůli pokrmu Boží dílo. Všechno je sice čisté, ale slouží ke zlému tomu člověku, který ⌈pohoršuje druhého tím, co⌉ jí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Je dobré nejíst maso a nepít víno ani nedělat to, nad čím se tvůj bratr uráží [nebo co ho přivádí k pádu či zeslabuje].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, '⌈Víru, kterou máš ty, měj⌉ pro sebe před Bohem. Blahoslavený je ten, kdo neodsuzuje sám sebe za to, co pokládá za správné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Ten však, kdo pochybuje a jedl by, je odsouzen, ⌈protože nejednal na základě víry⌉. Všecko, co ne ní z víry, je hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'My silní jsme povinni snášet slabosti těch, kteří nemají sílu, a nemít zalíbení sami v sobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Každý z nás ať se snaží líbit bližnímu k jeho dobru, pro jeho budování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Vždyť i Kristus neměl zalíbení sám v sobě, nýbrž jak je napsáno: Urážky těch, kdo tebe tupili, padly na mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Všecko, co bylo kdysi napsáno, bylo napsáno k našemu poučení, abychom skrze trpělivost a povzbuzení z Písem měli naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Bůh trpělivosti a povzbuzení kéž vám dá být mezi sebou jedné mysli podle Krista Ježíše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'abyste jednomyslně jedněmi ústy slavili Boha a Otce našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Proto přijímejte jeden druhého, tak jako Kristus k slávě Boží přijal vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Neboť pravím, že Kristus se stal služebníkem obřezaných pro pravdu Boží, aby potvrdil zaslíbení daná otcům');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'a aby národy slavily Boha za jeho milosrdenství, jak je napsáno: Proto ti vzdám chválu mezi národy a tvému jménu budu zpívat chvály.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'A dále praví: Zaradujte se, národy, spolu s jeho lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'A opět: Chvalte Pána všechny národy, ⌈ať jej velebí⌉ všichni lidé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'A dále praví Izaiáš: Bude kořen Isajův, ten, jenž povstane, aby vládl národům; v něj budou pohané doufat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Bůh naděje kéž vás naplní veškerou radostí a pokojem ve víře, abyste se rozhojňovali v naději mocí Ducha Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Sám jsem o vás, moji bratři, přesvědčen, že i vy jste plni dobroty, naplněni veškerým poznáním, a že jste schopni se i navzájem napomínat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Přece však jsem vám psal místy směleji, jako připomínku pro vás, pro milost, která mi byla dána od Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'abych byl služebníkem Krista Ježíše mezi pohany. Konám posvátnou službu při evangeliu Božím, aby se pohané stali příjemnou obětí, posvěcenou Duchem Svatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Mám se tedy čím chlubit v Kristu Ježíši ve věcech, které se týkají Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Neodvážil bych se mluvit o něčem, co by Kristus nevykonal skrze mne k poslušnosti pohanů, slovem i skutkem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'v moci znamení a divů, v moci Ducha Božího, takže od Jeruzaléma a dokola až po Illyrii jsem dovršil zvěstování evangelia Kristova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'A zakládám si na tom, že jsem takto evangelium hlásal tam, kde Kristovo jméno ještě nebylo vysloveno, abych nestavěl na cizím základě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'nýbrž tak, jak je napsáno: Ti, jimž o něm nebylo zvěstováno, uvidí, a ti, kteří neslyšeli, porozumí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Proto mi také bylo mnohokrát zabráněno v tom, abych k vám přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Nyní však už ⌈není pro mě⌉ v těchto krajinách místo a mnoho let v sobě nosím touhu k vám přijít,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'až půjdu do Hispanie. Doufám, ⌈že na této cestě⌉ se s vámi uvidím a že mě tam vypravíte, až se s vámi napřed trochu potěším.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Nyní však jdu do Jeruzaléma ⌈s pomocí⌉ pro svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, '⌈Makedonští a Achajští⌉ uznali totiž za dobré uspořádat nějakou sbírku pro chudé, kteří jsou mezi svatými v Jeruzalémě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Uznali za dobré to udělat, protože jsou také jejich dlužníky. Neboť jestliže pohané dostali podíl na jejich duchovních darech, jsou povinni posloužit jim zase ve věcech hmotných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Když tedy ⌈tento úkol⌉ dokončím a zapečetím jim toto ovoce sbírky, vydám se přes vás do Hispanie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Vím, že ⌈až k vám přijdu⌉, přijdu ⌈v plnosti⌉ požehnání [evangelia] Kristova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Prosím vás, bratři, skrze našeho Pána Ježíše Krista a skrze lásku Ducha: Zápaste spolu se mnou v modlitbách za mne k Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'abych byl vysvobozen od nevěřících v Judsku a aby ta to moje služba pro Jeruzalém byla svatým příjemná,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'abych pak z Boží vůle s radostí přišel k vám [a] odpočinul si mezi vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Bůh pokoje buď se všemi vámi. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Doporučuji vám naši sestru Foibé, diakonku církve, která je v Kenchrejích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'abyste ji přijali v Pánu, jak se sluší mezi svatými a pomohli jí ve všem, v čem by vás potřebovala. Vždyť i ona byla pomocnicí mnoha lidem, i mně samému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Pozdravte Prisku a Akvilu, mé spolupracovníky v Kristu Ježíši,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'kteří pro můj život nasadili vlastní hrdlo; jsem jim zavázán vděčností nejen já sám, ale i všechny církve z pohanů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Pozdravte i církev v jejich domě. Pozdravte mého milovaného Epaineta, který je Kristovou prvotinou v Asii.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Pozdravte Marii, která se pro vás mnoho napracovala.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Pozdravte Andronika a Junii, mé příbuzné a mé spoluvězně, kteří jsou ve vážnosti mezi apoštoly a kteří též byli v Kristu přede mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Pozdravte Ampliata, mého milovaného v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Pozdravte Urbana, našeho spolupracovníka v Kristu, a Stachya, mého milovaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Pozdravte Apella, osvědčeného v Kristu. Pozdravte ty, kteří jsou z domu Aristobulova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Pozdravte mého příbuzného Herodiona. Pozdravte ty z domu Narcisova, kteří jsou v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Pozdravte Tryfainu a Tryfósu, které se namáhaly v Pánu. Pozdravte milovanou Persidu, která se mnoho napracovala v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Pozdravte Rufa, vyvoleného v Pánu, a jeho matku, která je i mou matkou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Pozdravte Asynkrita, Flegóna, Herma, Patrobia, Hermia i bratry, kteří jsou s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Pozdravte Filologa a Julii, Nerea a jeho sestru, Olympia a všechny svaté, kteří jsou s nimi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Pozdravte se navzájem svatým políbením. Pozdravují vás všechny církve Kristovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Vybízím vás, bratři, abyste si dávali pozor na ty, kdo působí roztržky a pohoršení proti učení, kterému jste se naučili. Vyhýbejte se jim!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Neboť takoví neslouží našemu Pánu Kristu, nýbrž vlastnímu břichu, a úlisnými a líbivými řečmi svádějí srdce bezelstných lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, '⌈Zpráva o vaší poslušnosti⌉ se dostala ke všem. Mám z vás proto radost; přeji si však, abyste byli moudří v tom, co je dobré, a ⌈prosti toho⌉, co je zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Bůh pokoje brzo srazí Satana pod vaše nohy. Milost našeho Pána Ježíše [Krista] buď s vámi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Pozdravuje vás můj spolupracovník Timoteus i Lucius a Jáson a Sosipatros,moji příbuzní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Pozdravuji vás v Pánu já Tercius, který jsem napsal ten to dopis.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Pozdravuje vás Gaius, který byl hostitelem mně i celému shromáždění. Pozdravuje vás Erastos, správce městské pokladny, a bratr Kvartus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '[Milost našeho Pána Ježíše Krista se všemi vámi. Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Tomu, kdo je mocen vás upevnit podle mého evangelia a zvěsti o Ježíši Kristu, podle zjevení tajemství, které bylo po časy věků zamlčeno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'nyní však bylo zjeveno a skrze prorocká Písma podle příkazu věčného Boha oznámeno všem národům k poslušnosti víry --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'jedinému moudrému Bohu zjevenému skrze Ježíše Krista, jemu buď sláva na věky [věků]. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Pavel, povolaný apoštol ⌈Krista Ježíše⌉ skrze vůli Boží, a bratr Sosthenes');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, '⌈církvi Boží,⌉ která je v Korintu, posvěceným v Kristu Ježíši, povolaným svatým, spolu se všemi, kteří ⌈na kterémkoliv místě vzývají jméno našeho Pána Ježíše Krista, Pána jejich i našeho⌉:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Milost vám a pokoj od Boha, našeho Otce, a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Stále za vás děkuji [svému] Bohu za Boží milost, která vám byla dána v Kristu Ježíši:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Neboť v něm jste byli ve všem obohaceni, v každém slovu i v každém poznání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'tak jak bylo ⌈mezi vámi⌉ utvrzeno ⌈svědectví Kristovo⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'takže nemáte nedostatek v žádném ⌈daru milosti⌉ a dychtivě očekáváte zjevení našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'On vás také bude utvrzovat až do konce, abyste byli bez úhony v den našeho Pána Ježíše [Krista].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Věrný je Bůh, skrze něhož jste byli povoláni do společenství jeho Syna Ježíše Krista, našeho Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Napomínám vás, bratři, jménem našeho Pána Ježíše Krista, abyste všichni mluvili stejně a neměli mezi sebou roztržky, nýbrž abyste byli ⌈dokonale spojeni⌉ v tomtéž smýšlení a v tomtéž úsudku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Neboť lidé z domu Chloé mi o vás, moji bratři, oznámili, že jsou mezi vámi spory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Mluvím o tom, že každý z vás říká: Já jsem Pavlův, Já zase Apollův, Já zase Kéfův, A já Kristův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Je Kristus rozdělen? Byl snad za vás ukřižován Pavel? Anebo jste byli pokřtěni v Pavlovo jméno?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Děkuji Bohu, že jsem kromě Krispa a Gaia nikoho z vás nepokřtil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'aby nikdo nemohl říci, že ⌈jste byli pokřtěni v mé jméno⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Pokřtil jsem i Štěpánův dům. Jinak už nevím, že bych byl ještě někoho jiného pokřtil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Neboť Kristus mne neposlal křtít, ale hlásat evangelium, a to ne ⌈moudrostí slov⌉, aby Kristův kříž nebyl vyprázdněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Slovo kříže je totiž bláznovstvím těm, kteří hynou, ale nám, kteří jsme zachraňováni, je mocí Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Je napsáno: Zahubím moudrost moudrých a rozumnost rozumných zavrhnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Kde je moudrý? Kde je učitel Zákona? Kde je řečník tohoto věku? Neučinil Bůh moudrost [tohoto] světa bláznovstvím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Neboť když svět v Boží moudrosti nepoznal skrze svou moudrost Boha, zalíbilo se Bohu skrze bláznovství této zvěsti zachránit ty, kdo věří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Neboť Židé žádají znamení a Řekové hledají moudrost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'my však hlásáme Krista ukřižovaného: Židům pohoršení, pohanům bláznovství,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'ale těm, ⌈kteří jsou povoláni⌉, Židům i Řekům, Krista -- Boží moc a Boží moudrost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Neboť co je u Boha bláznivé, to je moudřejší než lidé, a co je u Boha slabé, to je silnější než lidé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Vidíte, bratři, ⌈ jak vás Bůh povolal⌉: ne ní mezi vámi mnoho moudrých podle těla, ani mnoho mocných, ani mnoho urozených.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Ale co je u světa bláznivé, to si vybral Bůh, aby zahanboval moudré, a co je u světa slabé, to si vybral Bůh, aby zahanboval silné;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'a co je u světa neurozené a méněcenné, to si vybral Bůh, vybral [dokonce] i to, co není, aby zrušil to, co je,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'aby se žádné tělo nemohlo před Bohem chlubit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Vy však jste z něho v Kristu Ježíši, jenž se nám stal moudrostí od Boha, spravedlností, posvěcením i vykoupením,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'aby se stalo tak, jak je napsáno: Kdo se chlubí, ať se chlubí v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Také já, bratři, když jsem přišel k vám, nepřišel jsem vám hlásat Boží tajemství vznešenými slovy nebo moudrostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Rozhodl jsem se, že ne chci mezi vámi znát nic než Ježíše Krista, a to toho ukřižovaného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'A byl jsem u vás ve slabosti, v bázni a v mnohém chvění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Mé slovo a má zvěst ne spočívaly v přesvědčivých slovech [lidské] moudrosti, ale v ukázání Ducha a moci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'aby vaše víra nebyla ⌈ založena na lidské moudrosti, ale na Boží moci⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'O moudrosti mluvíme mezi zralými, ne ovšem o moudrosti tohoto věku ani o moudrosti vládců tohoto věku, kteří zanikají,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'nýbrž o Boží moudrosti, skryté v tajemství, kterou Bůh před věky předurčil k naší slávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Tu nikdo z vládců tohoto věku nepoznal. Neboť kdyby ji poznali, nebyli by ukřižovali Pána slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Ale jak je napsáno: Co oko nevidělo a ucho neslyšelo a na lidské srdce nevstoupilo, to Bůh připravil těm, kdo ho milují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Nám to Bůh zjevil skrze [svého] Ducha; neboť Duch zkoumá všechno, i Boží hlubiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Vždyť kdo z lidí ví, co je v člověku, než duch člověka, který je v něm? Tak ani Boží věci nezná nikdo, jen Duch Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'A my jsme nepřijali ducha světa, ale Ducha, který je z Boha, abychom věděli, co nám Bůh daroval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'O tom také mluvíme -- ne však slovy, kterým vyučuje lidská moudrost, ale těmi, jimž vyučuje Duch [svatý]; duchovní věci vysvětlujeme duchovními slovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Duševní člověk však nepřijímá věci Ducha [Božího], neboť jsou mu bláznovstvím a nemůže je poznat, protože mají být posuzovány duchovně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Duchovní člověk však posuzuje všechno a sám není od nikoho posuzován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Neboť kdo poznal Pánovu mysl⌈, která mu dá porozumět⌉? My máme mysl Kristovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'A já, bratři, jsem k vám nemohl mluvit jako k duchovním, ale jako k tělesným, jako k nedospělým v Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Dal jsem vám pít mléko, pokrm jsem vám ne dal, neboť ten jste ještě nemohli snést. Ale ani teď ještě nemůžete,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'neboť jste stále ještě tělesní. Vždyť pokud je mezi vámi žárlivost, svár [a rozdělení], zdali nejste tělesní a ⌈nežijete jen po lidsku⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Když jeden říká: Já jsem Pavlův a druhý: Já Apollův, nejste ⌈ jako jiní lidé⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kdo je Apollos? A kdo je Pavel? Služebníci, skrze něž jste uvěřili, jak každému dal Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Já jsem zasadil, Apollos zalil, ale Bůh dával růst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Tedy ani ten, kdo sází, ani ten, kdo zalévá, nejsou něčím zvláštním, ale Bůh, který dává růst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Ten, kdo sází, i ten, kdo zalévá, jsou jedno, každý však dostane svou vlastní mzdu podle své námahy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Neboť jsme Boží spolupracovníci; vy jste Boží pole, Boží stavba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Podle [Boží] milosti, která mi byla dána, jsem jako moudrý stavitel položil základ a jiný na něm staví. Každý ať si dává pozor, jak na něm staví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Neboť nikdo nemůže položit jiný základ nežli ten, který je již položen, a tím je Ježíš Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Jestliže někdo na [tomto] základě staví ze zlata, stříbra, drahých kamenů, dřeva, sena nebo slámy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'dílo každého se stane zjevným. Ten den je ukáže, neboť se zjeví v ohni, a oheň vyzkouší dílo každého, jaké je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Jestliže někdo ⌈ na tomto základě vystaví⌉ dílo a ono mu zůstane, dostane odměnu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'jestliže mu jeho dílo shoří, utrpí škodu; sám se sice zachrání, ale jako skrze oheň.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Nevíte, že jste Boží svatyněa že ve vás bydlí Duch Boží?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Ničí–li někdo Boží svatyni, zničí Bůh jej. Neboť Boží svatyně je svatá, ⌈a tou svatyní ⌉ jste vy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Ať nikdo neklame sám sebe. Jestliže si někdo mezi vámi myslí, že je v tomto věku moudrý, ať se stane bláznem, aby se stal moudrým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Neboť moudrost tohoto světa je před Bohem bláznovstvím. Vždyť je napsáno: On chytá moudré v jejich chytráctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'A opět: Pán zná myšlenky moudrých a ví, že jsou marné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'A tak ať se nikdo nechlubí lidmi. Vždyť všechno je vaše:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'ať Pavel nebo Apollos nebo Kéfas, ať svět nebo život nebo smrt, ať věci přítomné nebo budoucí -- všechno je vaše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'vy pak jste Kristovi a Kristus Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Ať o nás každý smýšlí jako o služebnících Kristových a správcích Božích tajemství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'A od správců se nakonec vyžaduje, aby byl každý shledán věrným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Pro mne je pramálo důležité, zda mě posuzujete vy nebo lidský soud. Ale ani já sám sebe neposuzuji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Ničeho, co by svědčilo proti mně, si sice nejsem vědom, ale tím nejsem ospravedlněn; ten, kdo mne posuzuje, je Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Proto nic nesuďte předčasně, dokud nepřijde Pán, který osvítí i věci skryté ve tmě a zjeví úmysly srdcí. A tehdy se každému dostanepochvaly od Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Toto jsem, bratři, vztáhl na sebe a na Apolla kvůli vám, abyste se na nás naučili [smýšlet] ne nad to, co je napsáno, abyste se kvůli jednomu učiteli nenadýmali jeden nad druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Vždyť kdo ⌈ti dává vyniknout⌉? Co z toho, co máš, jsi nedostal? A když jsi to dostal, proč se chlubíš, jako bys to nedostal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Už jste nasyceni, už jste zbohatli, bez nás jste začali kralovat. Kéž byste kralovali, ale tak, abychom i my kralovali spolu s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Zdá se mi, že nás, apoštoly, Bůh postavil jako poslední, jako odsouzené na smrt, neboť jsme se stali divadlem světu, andělům i lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'My jsme blázni kvůli Kristu, ale vy jste rozumnív Kristu; my jsme slabí, vy však silní; vy slavní, my beze cti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Až do této hodiny hladovíme a žízníme, jsme skoro nazí, dostáváme rány, jsme bez domova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'lopotíme se prací vlastních rukou. Když nám spílají, žehnáme, když nás pronásledují, snášíme to,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'když jsme haněni, domlouváme. Stali jsme se jakoby smetím tohoto světa, vyvrheli pro všechny až doposud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Toto nepíšu, abych vás zahanboval, ale napomínám vás jako své milované děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Neboť i kdybyste měli deset tisíc vychovatelů v Kristu, otců mnoho ne máte, neboť v Kristu Ježíši já jsem vás zplodil skrze evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Prosím vás tedy: ⌈Napodobujte mě⌉!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Proto jsem k vám poslal Timotea, který je mým milovaným a věrným synem v Pánu. On vám připomene moje cesty v Kristu [Ježíši], jak učím všude v každém sboru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Někteří z vás se stali domýšlivými, jako bych k vám už neměl přijít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Ale přijdu k vám brzy, bude–li Pán chtít, a poznám nikoli řeč těch domýšlivců, ale jejich moc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Neboť Boží království ne spočívá v řeči, ale v moci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Co chcete? Mám k vám přijít s holí, nebo s láskou a v duchu mírnosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Skutečně je slyšet o smilstvu mezi vámi, a to o takovém smilstvu, jaké ne ní ani mezi pohany, že totiž někdo má ženu svého otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'A vy jste nadutí, místo abyste raději byli zarmouceni a odstranili ze svého středu toho, kdo se dopustil tohoto činu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Neboť já, ač tělem vzdálen, duchem však přítomen, už jsem, jako bych byl přítomen, vynesl rozsudek nad tím, kdo ⌈takový čin⌉ spáchal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 've jménu [našeho] Pána Ježíše [Krista] -- až se shromáždíte, vy a můj duch spolu s mocí našeho Pána Ježíše --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'vydejte takového člověka Satanu k záhubě těla, aby duch byl zachráněn v den Pána [Ježíše].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Vaše chlouba ne ní správná. Nevíte, že trocha kvasu prokvasí celé těsto?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Vyčistěte proto starý kvas, abyste byli novým těstem, neboť jste nekvašení. Vždyť Kristus, náš ⌈velikonoční Beránek⌉, byl [za nás] obětován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Slavme tedy svátek ne se starým kvasem, ani s kvasem špatnosti a zloby, ale s nekvašenými chleby upřímnosti a pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Napsal jsem vám v dopise, abyste se nesměšovali se smilníky;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'ne míním však všeobecně se smilníky tohoto světa nebo s chamtivci, lupiči a modláři, neboť to byste museli z toho to světa vyjít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Napsal jsem vám však, abyste se nesměšovali s tím, kdo si říká bratr, a přitom je smilník nebo chamtivec nebo modlář nebo utrhač nebo opilec nebo lupič; s takovým ani nejezte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Proč bych měl soudit [i] ty, kdo jsou mimo nás? Nesoudíte snad vy ty, kdo jsou uvnitř?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Ty, kdo jsou mimo, ⌈bude soudit⌉ Bůh. Odstraňte toho zlého ze svého středu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Proč se někdo z vás odvažuje, když má nějakou věc proti druhému, soudit se před nevěřícími místo před svatými?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Nevíte, že svatí budou soudit svět? A ⌈soudíte–li svět⌉, nejste hodni soudit maličkosti?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Nevíte, že budeme soudit anděly? Oč spíše záležitosti tohoto života!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Když tedy máte soudní spory o věci tohoto života, ⌈ustanovujete za soudce⌉ ty, kteří ve sboru nemají vážnost?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'To říkám k vaší hanbě. To není mezi vámi žádný moudrý člověk, který by mohl rozsoudit své bratry?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Bratr s bratrem se soudí, a to před nevěřícími?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Už vůbec to je vaše porážka, že se mezi sebou soudíte. Proč raději nesnášíte křivdu? Proč raději netrpíte škodu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Vy naopak křivdíte a okrádáte, a to bratry!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Což nevíte, že nespravedliví nedostanou do dědictví Boží království? Nemylte se! Ani smilníci ani modláři, cizoložníci, rozkošníci ani lidé praktikující homosexualitu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'zloději ani chamtivci, opilci, utrhači ani lupiči nebudou dědici Božího království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Takoví jste někteří byli. Ale dali jste se omýt, byli jste posvěceni, byli jste ospravedlněni ve jménu [našeho] Pána Ježíše [Krista] a v Duchu našeho Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Všechno mohu, ale ne všechno je užitečné; všechno mohu, ale ničím se nedám ovládnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Pokrmy jsou pro břicho a břicho pro pokrmy. Bůh však zničí jedno i druhé. Tělo však ne náleží smilstvu, nýbrž Pánu, a Pán tělu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'A Bůh i Pána vzkřísil a vzkřísí i vás svou mocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Nevíte, že vaše těla jsou údy Kristovými? Vezmu tedy údy Kristovy a učiním je údy nevěstky? To ať se nestane!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Nebo nevíte, že kdo se připojuje k nevěstce, je s ní jedno tělo? Neboť Písmo praví: ⌈ Stanou se ti dva jedním tělem. ⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Kdo se však připojuje k Pánu, je s ním jeden duch.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Utíkejte před smilstvem! Každé prohřešení, kterého by se člověk dopustil, ⌈se netýká těla⌉. Kdo však smilní, hřeší proti vlastnímu tělu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Nebo nevíte, že vaše tělo je svatyní svatého Ducha, který je ve vás a kterého máte od Boha? ⌈ Nevíte, že nejste sami svoji?⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Byli jste přece koupeni za velikou cenu; oslavte tedy ⌈svým tělem⌉ Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'O tom, co jste [mi] psali: Pro člověka je dobré, aby se nedotýkal ženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Ale ⌈abyste se vyvarovali smilstva⌉, ať má každý svou ženu a každá ať má svého muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Muž ať plní své ženě, čím je povinen, a stejně i žena svému muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Žena nevládne svým tělem, nýbrž její muž, podobně ani muž nevládne svým tělem, nýbrž jeho žena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Neodpírejte se navzájem, leda po vzájemné dohodě na čas, abyste se uvolnili pro modlitbu, a opět buďte spolu, aby vás pro vaši nezdrženlivost nepokoušel Satan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'To říkám jako dovolení, ne jako příkaz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Přeji si, aby všichni lidé byli, jako jsem já. Avšak každý má své vlastní obdarování od Boha, jeden tak, druhý jinak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Svobodným a vdovám pravím: Bylo by pro ně dobré, kdyby zůstali jako já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Jestliže se však neovládají, ať vstoupí do manželství; neboť je lepší vstoupit do manželství, než se pálit žádostivostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Manželům však nařizuji -- ne já, ale Pán -- aby žena od muže neodcházela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Když by však přece odešla, ať zůstává nevdaná nebo ať se s mužem smíří. Také muž ať neopouští ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Ostatním pak pravím já, ne Pán: Jestliže má některý bratr nevěřící ženu a ona je ochotna s ním žít, ať ji neopouští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'A má–li některá žena nevěřícího muže a on je ochoten s ní žít, ať svého muže neopouští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Neboť nevěřící muž je posvěcen ve své ženě a nevěřící žena je posvěcena ⌈ve svém muži⌉. Vždyť jinak by vaše děti byly nečisté, avšak nyní jsou svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Jestliže se však nevěřící ⌈chce rozvést⌉, ať se rozvede. Ten bratr nebo ta sestra nejsou v takových případech otroci. Neboť Bůh nás povolal ku pokoji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Vždyť co ty víš, ženo, zda zachráníš svého muže? Nebo co ty víš, muži, zda zachráníš svou ženu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Jenom ať každý žije tak, jak mu Pán udělil, každý, jak ho Bůh povolal. Tak to také přikazuji ve všech sborech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Byl někdo povolán jako obřezaný? Ať to nezakrývá. Byl někdo povolán jako neobřezaný? Ať se nedává obřezat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Obřízka nic neznamená ani neobřízka nic neznamená, ale zachovávání Božích přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Každý ať zůstává v tom postavení, ve kterém byl povolán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Byl jsi povolán jako otrok? Nedělej si s tím starosti. ⌈Jestliže se však můžeš stát svobodným, raději toho využij⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Neboť kdo byl v Pánu povolán jako otrok, je Pánův propuštěnec; podobně kdo byl povolán jako svobodný, je otrok Kristův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Byli jste koupeni za velikou cenu. Nebuďte otroky lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Bratři, každý ať zůstává před Bohem v tom postavení, v jakém byl povolán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Ohledně panen nemám sice Pánův příkaz, dávám však radu jako ten, kterému se dostalo od Pána milosrdenství být věrným.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Myslím tedy, že vzhledem k ⌈nynější tísni⌉ je dobré, aby člověk ⌈zůstal tak, jak je ⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Jsi připoután k ženě? Nehledej rozluku. Jsi volný? Nehledej si ženu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Ale i když se oženíš, nezhřešíš; a vdá–li se panna, nezhřeší. Takoví lidé však budou mít soužení v těle a toho vás chci ušetřit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Ale toto vám, bratři, říkám, [že] čas je zkrácený. A tak i ti, kdo mají ženy, ať jsou, jako by je neměli;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'a ti, kdo pláčou, jako by neplakali, a ti, kdo se radují, jako by se neradovali, a ti, kdo kupují, jako by nic nevlastnili;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'a ti, kdo užívají [tohoto] světa, jako by ho neužívali; neboť způsob tohoto světa pomíjí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Chci, abyste byli bez starostí. Kdo nežije v manželství, stará se o věci Pána, jak by se zalíbil Pánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'ale kdo se oženil, stará se o věci světské, jak by se zalíbil své ⌈ženě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'a je rozdělený. Neprovdaná žena a panna⌉ se stará o věci Pána, aby byla svatá tělem i duchem. Ale když se provdá, stará se o věci světské, jak by se zalíbila svému muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Toto říkám k vašemu prospěchu, ne abych ⌈vás omezoval⌉, ale abych vás vedl k počestnosti a k nerušené oddanosti Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Jestliže však někdo myslí, že vůči své panně, která je ve zralém věku, jedná nečestně, a že to musí tak být, ať dělá, co chce: nehřeší. Ať se vezmou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Kdo je však pevný ve svém srdci a není ničím nucen, ale ⌈má v moci svou vůli⌉ a rozhodl se ve svém srdci, že zachová svou pannu, dobře učiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Takže ten, kdo provdává svou pannu, činí dobře, a ten, kdo neprovdává, učiní lépe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Žena je vázána [zákonem] po dobu, kdy žije její muž. Když její muž zemře, je svobodná a může se vdát, za koho chce, ale jen v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Podle mého mínění je však blahoslavenější, jestliže zůstane tak, jak je. A myslím, že i já mám Ducha Božího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Pokud jde o maso obětované modlám, víme, že všichni máme poznání. Poznání ⌈činí člověka domýšlivým⌉, ale láska buduje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Jestliže se někdo domnívá, že něco poznal, nepoznal ještě tak, jak je třeba poznat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Jestliže však někdo miluje Boha, Bůh ho zná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Pokud tedy jde o to, zda se smí jíst maso obětované modlám, víme, že modla ve světě není nic a že není žádný [jiný] Bůh, jen Jeden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Neboť i když jsou takzvaní bohové, ať už v nebi nebo na zemi -- jakože jsou mnozí bohové a mnozí páni --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'my máme jediného Boha, Otce, od něhož je všechno a pro něhož jsme my, a jediného Pána, Ježíše Krista, skrze něhož je všechno, i my jsme skrze něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Ale ne ve všech je to poznání. Někteří až dosud ⌈ jsou zvyklí na modlu a ⌉ jedí toto maso jako obětované modlám, a jejich svědomí, protože je slabé, se poskvrňuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Pokrm nás ⌈k Bohu nepřiblíží⌉. Nejíme–li, nic neztrácíme, a jíme–li, nic nezískáváme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Dejte si však pozor, aby se vaše svoboda nestala kamenem úrazu pro slabé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Neboť když někdo tebe, který máš poznání, uvidí sedět za stolem v modlářském chrámě, nebude jeho svědomí, bude–li slabý, přivedeno k tomu, aby jedl maso obětované modlám?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, '[A] tak tvým poznáním hyne ten, který je slabý -- bratr, pro kterého Kristus zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Když takto hřešíte proti bratrům a zraňujete jejich slabé svědomí, hřešíte proti Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Jestliže tedy pokrm ⌈svádí k hříchu⌉ mého bratra, nebudu jíst už nikdy maso, abych ⌈nesvedl k hříchu⌉ svého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Což nejsem svoboden? Nejsem apoštol? Nespatřil jsem Ježíše, našeho Pána? Nejste vy mým dílem v Pánu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Nejsem–li pro jiné apoštolem, pro vás jím přece jsem, neboť pečetí mého apoštolství jste vy v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Toto je má obrana proti těm, kteří mne posuzují:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Což nemáme právo jíst a pít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Což nemáme právo mít s sebou ⌈věřící manželku⌉, jako i ostatní apoštolové a bratři Pána i Kéfas?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Či jenom já a Barnabáš nemáme právo nepracovat?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kdopak kdy koná vojenskou službuna vlastní náklady? Kdo vysazuje vinici, a nejí její plody? Nebo kdo pečuje o stádo, a nepije z mléka stáda?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Říkám to jen podle ⌈lidského úsudku ⌉? Nepraví to i Zákon?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'V Mojžíšově zákoně je přece napsáno: Nedáš náhubek volu, který mlátí obilí. Má tu Bůh na mysli jen voly,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'nebo to říká hlavně kvůli nám? Vskutku pro nás bylo napsáno, že ten, kdo orá, má orat v naději, i ten, kdo mlátí, má mlátit v naději, že dostane svůj podíl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Jestliže jsme u vás zaseli duchovní věci, bude to něco mimořádného, když budeme sklízet vaše tělesné věci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Jestliže se jiní podílejí na tomto právu vůči vám, ne měli bychom tím spíše my? My jsme však tohoto práva nevyužili, nýbrž všechno snášíme, abychom nekladli žádnou překážku evangeliu Kristovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Nevíte, že ti, kdo konají chrámovou službu, jedí z pokrmů chrámu, a ti, kdo slouží při oltáři, mají s oltářem podíl na obětech?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Tak i Pán nařídil, aby ti, kteří evangelium zvěstují, z evangelia žili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Já jsem však nic z toho nevyužil. A toto jsem nenapsal, aby se tak stalo při mně; neboť pro mne by bylo lepší zemřít, než aby někdo zmařil mou chloubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Když hlásám evangelium, není to má chlouba; ⌈je to pro mne⌉ nutnost, a běda mi, kdybych ho nehlásal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Pokud to činím z vlastního popudu, mám odměnu, pokud ne, je mi svěřeno správcovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Co je mi tedy odměnou? To, abych při službě předkládal evangelium zdarma, abych nevyužil svého práva, které mám v evangeliu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Neboť ačkoliv jsem ode všech svoboden, učinil jsem se otrokem všech, abych jich co nejvíce získal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'A stal jsem se Židům jako Žid, abych Židy získal. Těm, kteří jsou pod Zákonem, byl jsem jakoby pod Zákonem [-- i když sám nejsem pod Zákonem --] abych získal ty, kteří jsou pod Zákonem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Těm, kteří jsou bez Zákona, byl jsem jakoby bez Zákona, abych získal ty, kteří jsou bez Zákona, i když nejsem bez zákona Božího, nýbrž jsem podroben zákonu Kristovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Pro slabé jsem se stal [jakoby] slabý, abych získal slabé; všem jsem vším, abych zachránil aspoň některé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Všechno činím kvůli evangeliu, abych se stal jeho spoluúčastníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Nevíte, že ti, kteří běží v závodní dráze, běží sice všichni, ale jen jeden dostane cenu? Běžte tak, abyste ji získali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Každý, kdo závodí, je ve všem zdrženlivý; oni proto, aby dostali pomíjivý věnec, my však nepomíjivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Já tedy běžím ne jako ⌈bez cíle⌉; zápasím pěstmi, ne jako bych tloukl do vzduchu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'ale zasazuji dobře mířené rány svému tělu a podrobuji je, abych se snad -- jiným hlásaje -- sám nestal ⌈tím, kdo se neosvědčil⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Nechci, bratři, abyste nevěděli, že naši otcové byli všichni pod oním oblakem a všichni prošli mořem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'všichni ⌈byli pokřtěni⌉ v Mojžíše v oblaku a v moři,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'všichni jedli týž duchovní pokrm');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'a všichni pili týž duchovní nápoj; pili totiž z duchovní skály, která je doprovázela, a tou skálou byl Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Ale ve většině z nich neměl Bůh zalíbení; vždyť byli pobiti v té pustině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Tyto věci se staly příkladem pro nás, abychom nebyli žádostivi zlých věcí, jako oni byli žádostiví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Nebuďte ani modláři jako někteří z nich; jak je napsáno: Lid se posadil, aby jedl a pil, a potom vstali, aby se rozpustile bavili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Ani nesmilněme, jako někteří z nich smilnili, a padlo jich za jeden den třiadvacet tisíc;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'ani nepokoušejme Krista, jako někteří z nich pokoušeli, a hynuli od ⌈hadího uštknutí⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'ani nereptejte, jako někteří z nich reptali, a byli zahubeni Zhoubcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Tyto [všechny] věci se jim staly jako příklady pro nás a bylo to zapsáno k napomenutí nám, které zastihlo dokonání věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'A tak kdo si myslí, že stojí, ať hledí, aby nepadl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nezachvátilo vás jiné pokušení než lidské; věrný je však Bůh, který vás nenechá zkusit více, než snesete, ale ⌈se zkouškou⌉ dá i východisko, abyste ji mohli snést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Proto, moji milovaní, utíkejte před modlářstvím!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Mluvím jako k rozumným; sami rozsuďte, co říkám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Což není kalich požehnání, který žehnáme, společenstvím krve Kristovy? A což není chléb, který lámeme, společenstvím těla Kristova?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Protože je jeden chléb, jsme jedno tělo, ač jsme mnozí, neboť všichni jsme toho jednoho chleba účastni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Hleďte na Izrael podle těla: nejsou ti, kdo jedí oběti, účastníky oltáře?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Co tedy říkám? Že maso obětované modlám něco znamená? Nebo že modla něco znamená?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Ne, ale říkám, že to, co [pohané] obětují, obětují démonům, a ne Bohu. A já nechci, abyste byli účastníky démonů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Nemůžete pít Pánův kalich i kalich démonů; nemůžete mít podíl na Pánově stolu i na stolu démonů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Či ⌈chceme Pána popouzet⌉ k žárlivosti? Jsme snad silnější než on?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Všechno je dovoleno, ale ne všechno prospívá. Všechno je dovoleno, ale ne všechno buduje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Ať nikdo nehledá vlastní zájmy, nýbrž zájmy toho druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Jezte všechno, co se prodává na masném trhu, a kvůli svědomí se na nic nevyptávejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Vždyť Pánova je země a ⌈její plnost⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Zve–li vás někdo z nevěřících a chcete tam jít, jezte všechno, ⌈co vám předloží⌉, a kvůli svědomí se na nic nevyptávejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Ale když by vám někdo řekl: Toto je obětováno božstvům, nejezte kvůli tomu, kdo vám to oznámil, a kvůli svědomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Svědomí pak míním ne vlastní, ale toho druhého. Neboť proč má být moje svoboda souzena svědomím druhého?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Jestliže já s vděčností jím, proč mám být pomlouván za něco, za co vzdávám díky?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Ať tedy jíte nebo pijete nebo cokoliv činíte, všechno čiňte k Boží slávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Nebuďte kamenem úrazu Židům ani Řekům ani církvi Boží,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'stejně jako i já se chci všem ve všem líbit a nehledám svůj prospěch, nýbrž prospěch mnohých, aby byli zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, '⌈Napodobujte mě⌉, jako i já napodobuji Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Chválím vás, [bratři,] že ve všem na mne pamatujete a držíte se ⌈mých pokynů⌉, jak jsem vám je předal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Chci, abyste věděli, že hlavou každého muže je Kristus, hlavou ženy její muž a hlavou Krista Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Každý muž, který se modlí nebo prorokuje a má zahalenou hlavu, hanobí svou hlavu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Každá žena, která se modlí nebo prorokuje s nezahalenou hlavou, hanobí svou hlavu, neboť je to jedno a totéž, jako kdyby se oholila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Neboť jestliže si žena nezahaluje hlavu, ať se už také ostříhá. A jestliže je pro ženu potupou dát se ostříhat nebo oholit, ať se zahaluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Muž si nemusí zahalovat hlavu, neboť je Božím obrazem a jeho slávou, žena pak je slávou mužovou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Muž totiž není z ženy, nýbrž žena z muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Vždyť nebyl stvořen muž kvůli ženě, ale žena kvůli muži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Proto musí mít žena na hlavě ⌈znamení moci⌉ kvůli andělům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Avšak v Pánu není ani žena bez muže ani muž bez ženy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Neboť jako je žena z muže, tak také muž skrze ženu, a to všechno je z Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Sami posuďte: je vhodné, aby se žena modlila k Bohu nezahalená?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Neučí vás sama příroda, že nosí–li muž dlouhé vlasy, je mu to pro ostudu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'ale nosí–li dlouhé vlasy žena, je jí to k slávě? Neboť dlouhé vlasy jsou jí dány místo pokrývky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Kdyby však měl někdo sklon se přít -- takový zvyk nemáme ani my, ani Boží sbory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Když toto přikazuji, nechválím, že se scházíte spíše k horšímu než k lepšímu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Především slyším, že jsou mezi vámi roztržky, když se scházíte ve sboru, a zčásti tomu věřím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Neboť musí být mezi vámi i ⌈různé skupiny⌉, aby se ti osvědčení stali mezi vámi známými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Když vy se společně scházíte, není to slavení Večeře Páně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Když totiž jíte, každý si bere napřed svou večeři, jeden má hlad a druhý je opilý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Což nemáte domy, ⌈kde můžete jíst a pít⌉? Anebo opovrhujete Boží církví a zahanbujete ty, kteří nic nemají? Co vám mám říci? Mám vás snad pochválit? Za to vás nechválím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Já jsem přijal od Pána, co jsem vám také předal, že Pán Ježíš v tu noc, kdy byl zrazován, vzal chléb,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'vzdal díky, rozlomil jej a řekl: [Vezměte, jezte.] Toto je mé tělo, které [se] za vás [láme]. Toto čiňte na mou památku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Stejně vzal po večeři i kalich a řekl: Tento kalich je nová smlouva v mé krvi; toto čiňte, kdykoliv byste pili, na mou památku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Neboť kdykoliv byste jedli tento chléb a pili [tento] kalich, zvěstujete smrt Páně, dokud on nepřijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Kdo by tedy jedl ten chléb nebo pil kalich Páně nehodně, bude vinen proti tělu a krvi Páně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Ať člověk zkoumá sám sebe, a takto ať z toho chleba jí a z toho kalicha pije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Neboť kdo jí a pije [nehodně], jí a pije sobě odsouzení, neboť nerozsuzuje tělo [Páně].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Proto jsou mezi vámi mnozí slabí a neduživí a mnozí usínají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Kdybychom rozsuzovali sami sebe, nebyli bychom souzeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Když jsme však souzeni od Pána, jsme vychováváni, abychom nebyli odsouzeni spolu se světem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Proto, moji bratři, když se scházíte k jídlu, čekejte jeden na druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Je–li někdo hladový, ať jí doma, abyste se nescházeli k odsouzení. Ostatní věci zařídím, až přijdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Co se týká duchovních projevů, bratři, nechci, abyste byli v nevědomosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Víte, že když jste byli pohané, bývali jste neodolatelně vlečeni k němým modlám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Proto vám oznamuji, že žádný, kdo mluví v Duchu Božím, neřekne: Ježíš buď proklet, a nikdo nemůže říci: Pán Ježíš, jedině v Duchu svatém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, '⌈Jsou rozdíly v darech milosti⌉, ale tentýž Duch;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'jsou ⌈rozdíly v službách⌉, ale tentýž Pán;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'a jsou ⌈rozdíly v⌉ působení, ale tentýž Bůh, který působí všechno ve všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Každému je dáván projev Ducha ke společnému prospěchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Neboť jednomu je skrze Ducha dáváno slovo moudrosti, jinému podle téhož Ducha slovo poznání;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'dalšímu víra v témž Duchu, jinému dary uzdravování v témž Duchu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'jinému působení ⌈mocných činů⌉, jinému proroctví, jinému rozlišování duchů, dalšímu druhy jazyků, jinému pak výklad jazyků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Avšak to všechno působí jeden a týž Duch, který rozděluje každému jednotlivě, jak sám chce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Neboť jako tělo je jedno, a č má mnoho údů, a všechny údy [jednoho] těla, ačkoli je jich mnoho, jsou jedno tělo, tak i Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Neboť v jednom Duchu jsme my všichni byli pokřtěni v jedno tělo, ať Židé nebo Řekové, ať otroci nebo svobodní, a všichni jsme z jednoho Ducha dostali napít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Vždyť také tělo není jeden úd, nýbrž mnoho údů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Kdyby noha řekla: Protože nejsem ruka, ⌈nepatřím k tělu⌉, ⌈nepatří snad proto k tomu tělu⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'A kdyby řeklo ucho: Protože nejsem oko, nepatřím k tělu, nepatří snad proto k tělu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Kdyby celé tělo bylo jen oko, kde by byl sluch? Kdyby celé tělo bylo jen ucho, kde by byl čich?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Ale Bůh umístil údy: každý z nich v těle umístil tak, jak chtěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Kdyby bylo všechno jedním údem, kde by bylo tělo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Je mnoho údů, ale jedno tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Oko však nemůže říci ruce: Nepotřebuji tě, ani hlava nemůže říci nohám: Nepotřebuji vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Naopak ty údy těla, které se zdají být slabší, jsou nezbytné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'A části těla, které pokládáme za méně čestné, obklopujeme zvláštní ctí a ⌈našim neslušným částem dáváme⌉ tím větší slušnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'což naše slušné údy nepotřebují. Ale Bůh sestavil tělo tak, že tomu potřebnému dal zvláštní čest,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'aby v těle nebyla roztržka, ale aby údy navzájem o sebe stejně pečovaly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'A když jeden úd trpí, trpí spolu s ním všechny údy; a když je jeden úd oslavován, radují se všechny údy spolu s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Vy jste tělo Kristovo a jednotlivě jste jeho údy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'A v církvi Bůh ustanovil nejprve apoštoly, za druhé proroky, za třetí učitele, potom projevy moci, potom dary uzdravování, pomoci, vedení, druhy jazyků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Jsou snad všichni apoštolové? Jsou snad všichni proroci? Jsou snad všichni učitelé? Mají snad všichni projevy moci?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Mají snad všichni dary uzdravování? Mluví snad všichni jazyky? Nebo je snad všichni vykládají?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Vy však usilujte o větší dary milosti. A ukazuji vám ještě mnohem vzácnější cestu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Kdybych mluvil jazyky lidskými i andělskými, a lásku bych neměl, jsem jako dunící kov nebo zvučící činel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'A kdybych měl proroctví a znal všechna tajemství a měl všechno poznání a kdybych měl veškerou víru, takže bych přemisťoval hory, ale lásku bych neměl, nic nejsem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'A kdybych dal pro nasycení chudých všechen svůj majetek a kdybych vydal své tělo k spálení, ale lásku bych neměl, nic mi to neprospěje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Láska je trpělivá, dobrotivá, láska nezávidí, [láska] se nevychloubá a není domýšlivá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Nejedná nečestně, nehledá svůj prospěch, nerozčiluje se, nepočítá zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Neraduje se z nepravosti, ale raduje se spolu s pravdou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Všechno snáší, všemu věří, ve vše doufá, všechno vydrží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Láska nikdy nezanikne. Proroctví -- ta pominou; jazyky -- ty utichnou; poznání -- to pomine.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Neboť jen částečně poznáváme a částečně prorokujeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Když však přijde to, co je dokonalé, pomine to, co je částečné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Když jsem byl dítě, mluvil jsem jako dítě, smýšlel jsem jako dítě, uvažoval jsem jako dítě. Když jsem se stal mužem, zanechal jsem dětinských věcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Neboť nyní vidíme ⌈jako v zrcadle⌉, zastřeně, potom však uvidíme tváří v tvář. Nyní poznávám částečně, potom poznám důkladně, jak jsem byl také sám poznán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Nyní zůstává víra, naděje a láska, tyto tři věci. Ale největší z nich je láska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Usilujte o lásku a dychtěte po duchovních projevech, nejvíce však, abyste prorokovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Neboť kdo mluví jazykem, nemluví k lidem, nýbrž k Bohu; nikdo mu nerozumí, duchem mluví tajemství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Kdo však prorokuje, mluví lidem k budování, povzbuzení a útěše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kdo mluví jazykem, buduje sám sebe, ale kdo prorokuje, buduje církev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Chci, abyste všichni mluvili jazyky, avšak ještě více, abyste prorokovali. Kdo prorokuje, je větší než ten, kdo mluví jazyky, ledaže by i vykládal, aby se budovala církev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Tedy, bratři, kdybych k vám přišel a mluvil jazyky, co vám prospěji, když bych k vám nepromluvil ve zjevení, v poznání, v proroctví nebo vyučování?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Stejně je tomu i s neživými nástroji vydávajícími zvuk, ať už s flétnou nebo s lyrou Kdyby ⌈nevydávaly různé tóny⌉, jak by se poznalo, co se na flétnu nebo na lyru hraje?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'A kdyby polnice vydala nejasný zvuk, kdo by se chystal k boji?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Tak i vy: Jestliže jazykem nevydáte jasné slovo, jak se pozná, co bylo řečeno? Neboť budete mluvit do větru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Vždyť na světě je tolik druhů jazyků, a žádný není ⌈bez významu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Jestliže neznám význam jazyka, budu cizincem pro toho, kdo mluví, a ten, kdo mluví, bude cizincem pro mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Tak i vy, poněvadž ⌈horlivě usilujete⌉ o duchovní projevy, snažte se,abyste se v nich rozhojňovali pro budování církve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Proto kdo mluví jazykem, ať se modlí, aby mohl také vykládat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Neboť když se modlím jazykem, můj duch se modlí, avšak má mysl je bez užitku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Co tedy? Budu se modlit duchem, ale budu se modlit i myslí; budu zpívat chvály duchem, ale budu zpívat chvály i myslí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Neboť kdybys dobrořečil jen duchem, jak by mohl ⌈přítomný prostý člověk⌉ k tvému díkůvzdání říci Amen, když neví, co říkáš?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Ty sice dobře děkuješ, ale ten druhý tím není budován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Děkuji Bohu, že mluvím jazyky více než vy všichni;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'ale v církvi -- abych poučil i druhé -- chci raději promluvit pět slov svou myslí než deset tisíc slov v jazyku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Bratři, ve svém myšlení nebuďte jako děti; ve zlém buďte jako nemluvňata, ale v myšlení buďte dospělí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'V Zákoně je napsáno: Jinými jazyky a rty cizinců budu mluvit k tomuto lidu, ale ani tak mě nebudou poslouchat, praví Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Jazyky nejsou tedy znamením pro věřící, nýbrž pro nevěřící, proroctví však ne ní pro nevěřící, nýbrž pro věřící.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Když by se tedy sešel celý sbor a všichni by mluvili jazyky, a vešli by prostí lidé nebo nevěřící, cožpak neřeknou, že blázníte?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Ale když budou všichni prorokovat a vejde někdo nevěřící nebo neznalý, bude ode všech usvědčován a ode všech souzen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Budou se odhalovat skryté věci jeho srdce, a tak padne na tvář, pokloní se Bohu a vyzná: Vskutku, mezi vámi je Bůh!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Co z toho tedy plyne, bratři? Když se sejdete, každý [z vás] má chvalozpěv, má učení, má zjevení, má jazyk, má výklad; všechno ať je k budování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Mluví–li někdo jazykem, ať mluví dva nebo nejvýše tři, a to jeden po druhém, a jeden ať vykládá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'A jestliže tam není vykladač, ať ve shromáždění mlčí; ať mluví k sobě a k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Proroci ať mluví dva nebo tři a ti ostatní ať rozsuzují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'A když by dostal zjevení jiný, který tam sedí, ať ten první umlkne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Jeden po druhém můžete všichni prorokovat, aby se všichni učili a všichni byli povzbuzováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Duchové proroků se podřizují prorokům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'neboť Bůh není Bohem zmatku, nýbrž Bohem pokoje. Jako ve všech shromážděních svatých,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, '[vaše] ženy nechť ve shromážděních mlčí. Nedovoluje se jim, aby mluvily; ať jsou podřízené, jak praví i Zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Chtějí–li se něco naučit, ať se ptají doma svých mužů. Je totiž neslušné, aby žena mluvila ve shromáždění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Vyšlo snad Boží slovo od vás? Nebo přišlo jen k vám samotným?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Považuje–li se někdo za proroka nebo duchovního člověka, ať uznává, že to, co vám píšu, ⌈je Pánovo přikázání⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Jestliže to někdo neuznává, ⌈ sám nebude uznáván⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'A tak, [moji] bratři, horlivě se snažte prorokovat a nebraňte mluvit jazyky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Všechno ať se děje slušně a spořádaně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Připomínám vám, bratři, evangelium, které jsem vám zvěstoval, které jste přijali, v němž stojíte');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'a skrze něž ⌈jste i zachraňováni⌉, držíte–li se ho tak, jak jsem vám je zvěstoval -- ledaže byste uvěřili nadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Předal jsem vám především to, co jsem také sám přijal, že Kristus zemřel za naše hříchy podle Písem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'byl pohřben a třetího dne byl vzkříšen podle Písem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'zjevil se Kéfovi a potom Dvanácti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Dále se zjevil více než pěti stům bratří najednou; většina z nich doposud žije, někteří však již zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Potom se zjevil Jakubovi a potom všem apoštolům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Naposledy ze všech, jako nedochůdčeti, zjevil se také mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Neboť já jsem nejmenší z apoštolů; nejsem hoden nazývat se apoštolem, protože jsem pronásledoval Boží církev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Boží milostí jsem to, co jsem. A jeho milost, kterou mi prokázal, nebyla marná, vždyť jsem usilovně pracoval více než všichni ostatní -- nikoli já, nýbrž Boží milost, [která] byla se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Ať už tedy já, nebo oni -- takto hlásáme a tak jste uvěřili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Když se tedy hlásá o Kristu, že vstal z mrtvých, jak to, že někteří mezi vámi říkají, že není vzkříšení mrtvých?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Není–li vzkříšení mrtvých, pak nevstal ani Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Jestliže však Kristus nevstal z mrtvých, pak je naše zvěstování prázdné, prázdná je i vaše víra');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'a my ⌈jsme se také stali⌉ falešnými Božími svědky -- vždyť jsme vydali svědectví o Bohu, že probudil k životu Krista, on ho však neprobudil, jestliže totiž mrtví nevstávají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Neboť jestliže mrtví nevstávají, není vzkříšen ani Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Není–li však Kristus vzkříšen, je vaše víra marná, ještě jste ve svých hříších.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Pak tedy zahynuli i ti, kteří v Kristu zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Máme–li naději v Kristu jen v tomto životě, jsme ⌈nejubožejší ze všech⌉ lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Avšak Kristus vstal z mrtvých, prvotina těch, kdo zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Když tedy přišla skrze člověka smrt, přišlo skrze člověka také vzkříšení mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Jako v Adamovi všichni umírají, tak také v Kristu budou všichni obživeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Každý však ve svém pořadí: jako prvotina Kristus, potom při jeho příchodu ti, kdo jsou Kristovi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'potom bude konec, až Kristus odevzdá království Bohu a Otci a zruší každou vládu, každou vrchnost i moc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Neboť on musí kralovat, dokud nepoloží všechny nepřátele pod jeho nohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Jako poslední nepřítel bude zahlazena smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Neboť všechno podřídil pod jeho nohy. Když však řekl, že je všechno podřízeno, je zřejmé, že všechno kromě toho, kdo mu všechno podřídil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'A až mu podřídí všechno, pak i sám Syn se podřídí tomu, jenž mu podřídil všechno, aby byl Bůh všechno ve všem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Co potom budou dělat ti, kteří se dávají křtít za mrtvé? Jestliže mrtví vůbec nevstávají, proč se za ně dávají křtít?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'A proč i my se v každou hodinu vydáváme do nebezpečí?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Denně umírám -- jakože [vy, bratři,] jste moje chlouba, kterou mám v Kristu Ježíši, našem Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Jestliže, ⌈po lidsku řečeno ⌉, jsem v Efesu bojoval s šelmami, co mi to prospěje? Jestliže mrtví nevstávají, jezme a pijme, neboť zítra zemřeme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Neklamte se: Špatné řeči ničí dobré mravy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Vystřízlivějte, jak se sluší, a nehřešte. Vždyť někteří z vás nemají ani ponětí o Bohu. Říkám to k vašemu zahanbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Někdo však řekne: Jak vstanou mrtví? V jakém těle přijdou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Pošetilý člověče! To, co zaséváš, neobživne, jestliže to neumře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'A co zaséváš, není to tělo, které má vzniknout, nýbrž holé zrno, například pšeničné nebo nějaké jiné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Bůh mu však dává tělo, jak to sám chtěl: každému semeni jeho vlastní tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ne ní každé tělo stejné, nýbrž jiné je tělo lidské, jiné je tělo dobytka, jiné tělo ptáků a jiné tělo ryb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'A jsou těla nebeská a těla pozemská, ale jiná je sláva nebeských a jiná pozemských.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Jiná je sláva slunce, jiná je sláva měsíce a jiná je sláva hvězd. Neboť hvězda od hvězdy se liší ve slávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Tak je tomu i při vzkříšení mrtvých: Zasévá se v porušitelnosti, vstává v neporušitelnosti;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'zasévá se v potupě, vstává ve slávě; zasévá se v slabosti, vstává v moci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Zasévá se tělo duševní, vstává tělo duchovní. Je–li tělo duševní, je také tělo duchovní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Tak je i napsáno: První člověk, Adam, se stal duší živou, poslední Adam Duchem oživujícím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Ale ne nejprve duchovní, nýbrž duševní, a potom duchovní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'První člověk je ze země, z prachu, druhý člověk [Pán] z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Jaký je ten po zemský, takoví i ti po zemští; a jaký ten nebeský, takoví i ti nebeští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'A jako jsme nesli podobu po zemského, nesme také podobu nebeského.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Toto vám říkám, bratři, že tělo a krev nemůže být dědicem Božího království ani porušitelné nebude dědicem neporušitelného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Hle, říkám vám tajemství: Ne všichni zemřeme, ale všichni budeme proměněni,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'naráz, v okamžiku, při zvuku poslední polnice. Zazní polnice, a mrtví vstanou jako neporušitelní a my budeme proměněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Neboť toto porušitelné tělo musí obléci neporušitelnost a toto smrtelné musí obléci nesmrtelnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Když toto porušitelné tělo oblékne neporušitelnost a toto smrtelné oblékne nesmrtelnost, tehdy se uskuteční slovo, které je napsáno: Smrt byla pohlcena ve vítězství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Kde je, smrti, ⌈tvé vítězství? Kde je, smrti, tvůj osten⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Ostnem smrti je hřích a mocí hříchu je Zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Budiž dík Bohu, který nám dává vítězství skrze našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Tak tedy, moji milovaní bratři, buďte pevní a nepohnutelní, stále se rozhojňujte v Pánově díle, vědouce, že vaše námaha není v Pánu zbytečná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Pokud jde o sbírku pro svaté: jak jsem přikázal galatským sborům, tak učiňte i vy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'V první den týdne ať každý z vás doma dá stranou ⌈ tolik, kolik bude moci uložit⌉, aby se sbírky nemusely konat teprve tehdy, až k vám přijdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Až budu u vás, pošlu s potvrzujícími dopisy ty, které uznáte za hodné, aby odnesli váš dar do Jeruzaléma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Bude–li vhodné, abych šel i já, půjdou se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Přijdu k vám, až projdu Makedonií. Makedonií totiž jen procházím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'ale u vás snad pobudu anebo přečkám zimu, abyste mne potom mohli vypravit, kamkoliv půjdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Nechci vás teď totiž uvidět jen letmo; doufám, že u vás nějaký čas zůstanu, dovolí–li Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Až do letnic zůstanu v Efesu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'neboť jsou zde pro mne otevřeny ⌈dveře k velké a účinné službě ⌉. I protivníků je však mnoho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Přijde–li Timoteus, hleďte, aby u vás neměl žádné potíže, neboť koná Pánovo dílo jako já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Ať jím tedy nikdo nepohrdá. Vypravte ho v pokoji, aby přišel ke mně, neboť na něho čekám spolu s bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Co se týče bratra Apolla, mnoho jsem ho povzbuzoval, aby přišel s bratry k vám. Ale vůbec tu nebyla vůle, aby nyní přišel. Přijde, jakmile bude vhodná doba.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Bděte, stůjte pevně ve víře, ⌈buďte zmužilí⌉, posilujte se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Všechno ať se ⌈mezi vámi⌉ děje v lásce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Vyzývám vás, bratři: Víte o lidech z domu Štěpánova, že jsou prvotinou Achaje a že se oddali službě svatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'I vy se podřizujte takovým lidem, i každému, kdo spolupracuje a namáhá se na Božím díle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Raduji se nad přítomností Štěpána, Fortunata i Achaika, protože oni mi nahradili vaši nepřítomnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Občerstvili mého i vašeho ducha. Uznávejte takové bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Pozdravují vás asijské sbory. Velice vás pozdravuje v Pánu Akvila a Priska spolu se shromážděním v jejich domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Pozdravují vás všichni bratři. Pozdravte se navzájem svatým políbením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Pozdrav mou, Pavlovou rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Kdo nemá rád Pána, ať je proklet! ⌈Marana tha⌉!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Milost Pána Ježíše [Krista] s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Moje láska je se všemi vámi v Kristu Ježíši. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Pavel, z Boží vůle apoštol Krista Ježíše, a bratr Timoteus církvi Boží, jež je v Korintu, se všemi svatými, kteří jsou v celé Achaji:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Požehnaný Bůh a Otec našeho Pána Ježíše Krista, Otec milosrdenství a Bůh veškerého povzbuzení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'který nás povzbuzuje v každém našem soužení, abychom i my mohli povzbuzovat ty, kteří jsou v jakémkoli soužení, tím povzbuzením, kterým Bůh povzbuzuje nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Neboť jako se na nás rozhojňují Kristova utrpení, tak se skrze Krista rozhojňuje i naše povzbuzení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Jsme–li tedy v soužení, je to k vašemu povzbuzení a záchraně; jsme–li povzbuzováni, je to k vašemu povzbuzení, které se projevuje ve vytrvalém snášení týchž utrpení, jež snášíme i my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Naše naděje, pokud jde o vás, je pevná; víme, že jako jste účastni utrpení, tak i povzbuzení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Nechceme, bratři, abyste nevěděli o našem soužení, které [nás] potkalo v Asii; dolehlo na nás nadmíru těžce, nad naši sílu, takže jsme si zoufali, až jsme i pochybovali o svém životě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Sami v sobě jsme však měli ten rozsudek smrti, abychom nespoléhali na sebe, ale na Boha, který křísí mrtvé;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'on nás vysvobodil z takového nebezpečí smrti a ⌈ ještě vysvobodí⌉; v něho jsme složili svou naději, že ještě znovu vysvobodí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'když i vy nám budete pomáhat modlitbou, aby za nás ⌈mnozí děkovali⌉ kvůli ⌈daru milosti⌉, kterého se nám dostalo skrze přímluvy mnohých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Neboť toto je naše chlouba: svědectví našeho svědomí, že jsme si na světě -- a obzvláště mezi vámi -- počínali v prostotě a Boží upřímnosti, ne v tělesné moudrosti, nýbrž v Boží milosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Neboť vám nepíšeme nic jiného, než co čtete a také chápete, a doufám, že dokonale pochopíte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'jako jste nás už i zčásti pochopili, že jsme vaší chloubou, tak jako i vy naší v den [našeho] Pána Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'V této důvěře jsem k vám chtěl už dříve přijít, abyste dostali dvojí milost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'a skrze vás projít do Makedonie a z Makedonie opět přijít k vám a od vás být vypraven do Judska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Když jsem tedy toto chtěl, jednal jsem snad lehkovážně? Nebo snad to, co zamýšlím, je podle těla, takže ano, ano u mne znamená zároveň ne, ne?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Bůh je však věrný, takže naše slovo k vám není ano i ne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Neboť Boží Syn, Ježíš Kristus, který byl mezi vámi skrze nás vyhlášen -- mnou, Silvanem a Timoteem -- nebyl ano i ne, nýbrž v něm se uskutečnilo ano.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Neboť všechna Boží zaslíbení, kolik jich jen je, v něm jsou ano. Proto je také skrze něho řečeno amen k slávě Bohu skrze nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Ten, kdo nás upevňuje spolu s vámi ⌈v Kristu⌉ a pomazal nás, je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'On nás také zapečetil a ⌈do našich srdcí⌉ dal ⌈Ducha jako závdavek⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Volám Boha za svědka na svou duši, že ⌈jen z ohledu na vás⌉ jsem ještě nepřišel do Korintu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, '⌈Nejsme pány⌉ nad vaší vírou, nýbrž jsme pomocníky vaší radosti; vždyť vírou pevně stojíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Rozhodl jsem se však, že k vám nepřijdu opět v zármutku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Neboť jestliže já vás zarmucuji, kdo mi bude působit radost, ne–li ten, koho já zarmucuji?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'A právě toto píšu, abych po svém příchodu neměl zármutek kvůli těm, kdo mi měli působit radost; jsem o vás všech přesvědčen, že moje radost je radostí vás všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Vždyť vám píšu ve velikém soužení, v sevření srdce a s mnohými slzami; ne proto, abyste byli zarmouceni, ale abyste poznali lásku, kterou ⌈k vám překypuji⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Způsobil–li někdo zármutek, nezpůsobil ho jen mně, ale zčásti -- abych nepřeháněl -- vám všem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Takovému člověku stačí pokárání, kterého se mu dostalo od většiny z vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Takže mu raději naopak odpusťte a povzbuďte ho, aby snad přemírou zármutku nebyl takový člověk pohlcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Vybízím vás tedy, abyste ho ujistili svou láskou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Proto vám také píšu, abych vás vyzkoušel a poznal, jste–li ⌈ve všem⌉ poslušni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Komu vy něco odpouštíte, odpouštím i já. Neboť i já, co koliv jsem odpustil -- měl–li jsem co odpustit -- učinil jsem to pro vás před tváří Kristovou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'abychom nebyli oklamáni od Satana; vždyť jeho úmysly nám nejsou neznámy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Když jsem přišel do Troady ⌈hlásat evangelium Kristovo⌉ -- a ⌈naskytla se mi příležitost⌉ v Pánu --,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, '⌈můj duch⌉ neměl pokoje, protože jsem nenalezl svého bratra Tita; rozloučil jsem se s nimi a odešel do Makedonie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Díky Bohu, který nás stále ⌈vede v triumfálním průvodu v Kristu⌉ a zjevuje skrze nás na každém místě vůni své známosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Neboť jsme Kristovou libou vůní Bohu ⌈mezi těmi⌉, kteří jsou zachraňováni, i ⌈mezi těmi⌉, kteří jdou do záhuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Jedněm jsme vůní smrti ke smrti, druhým vůní života k životu. Ale kdo je k tomu způsobilý?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Neboť nejsme jako mnozí, kteří kupčí s Božím slovem, nýbrž jako ti, kdo mluví z upřímnosti, jako ti, kdo mluví z Boha, tak mluvíme před Boží tváří v Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'To začínáme opět doporučovat sami sebe? Nebo snad potřebujeme, jako někteří, doporučující dopisy k vám nebo od vás?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vy jste naším dopisem, který je napsán v našich srdcích a který znají a čtou všichni lidé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Je přece zjevné, že jste dopisem Kristovým, vypůsobeným naší službou a napsaným ne inkoustem, nýbrž Duchem živého Boha, ne na kamenných deskách, nýbrž na ⌈deskách lidských⌉ srdcí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Takovou pak máme skrze Krista důvěru k Bohu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Ne sami ze sebe se pokládáme za způsobilé, jako bychom měli něco sami ze sebe, ale naše způsobilost je z Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'On nás také učinil způsobilými k tomu, abychom byli služebníky Nové smlouvy, ne litery, nýbrž Ducha; neboť litera zabíjí, ale Duch obživuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Jestliže se služba smrti vyrytá literami do kamenů udála v takové slávě, že synové Izraele nemohli pohledět Mojžíšovi do tváře kvůli slávě jeho obličeje, která pomíjela,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'jak by nebyla mnohem slavnější služba Ducha?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Neboť jestliže byla sláva v službě odsouzení, mnohem více oplývá slávou služba spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Neboť vskutku to, co v tomto případě mělo slávu, již nemá slávu vzhledem k té to vše převyšující slávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Neboť jestliže skrze slávu přišlo už to, co pomíjí, oč slavnější je to, co zůstává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Když tedy máme takovou naději, počínáme si zcela otevřeně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Ne jako Mojžíš, který si dával na tvář závoj, aby synové Izraele nehleděli na konec toho, co pomíjí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Avšak jejich myšlení otupělo. Až do dnešního [dne] zůstává při čtení Staré smlouvy tentýž závoj neodkrytý, protože pomíjí jen v Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Ale až dodnes, kdykoli se předčítá Mojžíš, leží závoj na jejich srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Kdykoli se však člověk obrátí k Pánu, je závoj odstraněn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Ten Pán je Duch. Kde je Duch Pánův, [tam] je svoboda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'A my všichni, spatřujíce s odhalenou tváří Pánovu slávu jako v zrcadle, jsme proměňováni v týž obraz, od slávy k slávě, jako od Pána Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Když tedy máme tuto službu podle milosrdenství, kterého se nám dostalo, neochabujeme,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'ale odřekli jsme se věcí ukrývaných kvůli hanbě a nepočínáme si chytrácky ani nepřekrucujeme slovo Boží, nýbrž zjevováním pravdy se představujeme každému lidskému porozumění před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Je–li však naše evangelium zahaleno, je zahaleno těm, kteří hynou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'Jim, nevěřícím, bůh tohoto věku oslepil myšlení, aby jim nevzešlo světlo ⌈evangelia slávy⌉ Krista, jenž je obrazem Božím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Neboť nehlásáme sami sebe, nýbrž Ježíše Krista, Pána, a sebe jako vaše otroky pro Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Neboť Bůh, který řekl: Z temnoty ať zazáří světlo, zazářil v našich srdcích, ⌈aby osvítil lidi poznáním⌉ Boží slávy v osobě Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Tento poklad máme však v hliněných nádobách, aby přemíra té moci byla ⌈z Boha⌉, a ne z nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Ve všem jsme sužováni, ale nejsme vháněni do úzkých; býváme v nejistotě, ale nejsme zoufalí;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'jsme pronásledováni, ale nejsme opouštěni; jsme sráženi, ale nejsme ničeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Stále nosíme na svém těle Ježíšovo umírání, aby byl na našem těle zjeven i Ježíšův život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Neboť my, kteří žijeme, jsme pro Ježíše stále vydáváni na smrt, aby i život Ježíšův byl zjeven na našem smrtelném těle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Takže v nás působí smrt, kdežto ve vás život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Protože však máme téhož Ducha víry podle toho, co je napsáno: Uvěřil jsem, proto jsem mluvil, i my věříme, proto také mluvíme,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'a víme, že ten, který vzkřísil [Pána] Ježíše, také nás s Ježíšem vzkřísí a postaví spolu s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Vždyť to všechno je kvůli vám, aby milost, rozhojněná skrze mnohé lidi, rozmnožila vděčnost ke slávě Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Proto neochabujeme; i když náš vnější člověk chátrá, ten vnitřní se však den ze dne obnovuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'To naše nynější lehké soužení nám totiž působí nesmírně veliké břímě věčné slávy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'když nehledíme na věci viditelné, ale na neviditelné; neboť viditelné věci jsou dočasné, neviditelné však věčné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Víme totiž, že bude–li ⌈stan našeho pozemského přebývání⌉ zbořen, máme příbytek od Boha: ne lidskou rukou postavený, ale věčný dům v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Neboť v tomto stanu sténáme a toužíme si obléci ještě i náš příbytek, který pochází z nebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, '⌈Kdybychom pak byli i svlečeni⌉, nebudeme shledáni nahými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Pokud jsme totiž v tom to stanu, sténáme a je nám těžko, neboť nechceme být svlečeni, nýbrž přioděni, aby to, co je smrtelné, bylo pohlceno životem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Ten, kdo nás právě k tomu připravil, je Bůh, který nám [také] dal Ducha jako závdavek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Jsme tedy vždy plni důvěry a víme, že dokud máme domov v tom to těle, jsme vzdáleni od Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Neboť chodíme vírou, ne ⌈tím, co vidíme⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Jsme plni důvěry a raději chceme odejít z tohoto těla a přijít domů k Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Proto se i horlivě snažíme, abychom se mu líbili, ať zůstáváme doma nebo odcházíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Neboť my všichni se musíme objevit před soudnou stolicí Kristovou, aby každý přijal odplatu za to, co vykonal v těle, ať už to bylo dobré nebo zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Protože tedy známe ⌈bázeň před Pánem⌉, přesvědčujeme lidi a Bohu jsme známí; a doufám, že jsme známí i vašemu svědomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, '[Neboť] se vám ne chceme znovu doporučovat, nýbrž dáváme vám příležitost chlubit se námi, abyste měli ⌈ něco pro ty⌉, kteří se chválí navenek, a ne v srdci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Když jsme byli jako blázni, bylo to pro Boha; když jednáme rozumně, je to pro vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Neboť Kristova láska nás váže, když jsme usoudili toto: Protože jeden zemřel za všechny, tedy všichni zemřeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'A on zemřel za všechny, aby ti, kteří žijí, nežili už sami sobě, nýbrž tomu, kdo za ně zemřel a vstal z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'A tak od nynějška nikoho neznáme podle těla. Ačkoli jsme i znali Krista podle těla, nyní ho již takto neznáme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Proto je –li kdo v Kristu, je nové stvoření. Staré věci pominuly, hle, je tu [všechno] nové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'A to všechno je z Boha, který nás smířil sám se sebou skrze Krista a dal nám službu smíření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Neboť ⌈Bůh byl v Kristu, když smiřoval⌉ svět se sebou a nepočítal lidem jejich provinění, a uložil v nás to ⌈slovo smíření.⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Jsme tedy Kristovi vyslanci a Bůh jako by vás skrze nás vyzýval. ⌈Na místě Kristově⌉ prosíme: Smiřte se s Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Toho, který hřích nepoznal, za nás učinil hříchem, abychom se my v něm stali Boží spravedlností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, '⌈Jako Boží spolupracovníci⌉ vás také napomínáme, abyste Boží milost nepřijali nadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Neboť praví: Ve vítaný čas jsem tě vyslyšel a v den záchrany jsem ti pomohl. Hle, nyní je nanejvýš vítaný čas, hle, nyní je den záchrany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Nikomu nedáváme v ničem důvod k pohoršení, aby ta to služba nebyla pohaněna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Ve všem se představujeme jako Boží služebníci: v mnohé vytrvalosti, v souženích, v tlacích, v úzkostech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'v ranách, ve vězeních, ve zmatcích, v těžkých pracích, ve bděních, v postech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'v čistotě, v poznání, v trpělivosti, v dobrotě, v Duchu svatém, v lásce bez přetvářky,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 've slovu pravdy, v moci Boží; skrze zbroj spravedlnosti ⌈v pravici i v levici⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'skrze slávu i potupu, skrze pomluvu i pochvalu, jako svůdcové, a přece pravdiví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'jako neznámí i uznávaní, jako umírající-- a hle, jsme naživu, jako trestaní, ale ne usmrcovaní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'jako zarmucovaní, avšak stále se radující, jako chudí, avšak mnohé zbohacující, jako nic nemající, a přece všechno vlastnící.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Pro vás, Korinťané, se otevřela naše ústa a rozšířilo se naše srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, '⌈Nejste tísněni v nás⌉, jste tísněni ve svém nitru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Na oplátku -- říkám to jako dětem -- rozšiřte i vy svá srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Nebuďte zapřaženi do cizího jha s nevěřícími. Neboť co má společného spravedlnost s nepravostí? A jaké je společenství světla s tmou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Jaký je souzvuk Krista s Belialem? Jaký podíl věřícího s nevěřícím?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Jaké spojení svatyně Boží s modlami? Neboť ⌈vy jste⌉ svatyní Boha živého, jak řekl Bůh: Budu bydlet uprostřed nich a procházet se mezi nimi, a budu jejich Bohem a oni budou mým lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Proto vyjděte z jejich středu a oddělte se, praví Pán, a nečistého se nedotýkejte; a já vás přijmu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'a budu vám Otcem a vy mi budete syny a dcerami, praví Pán Všemohoucí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Když tedy máme tato zaslíbení, milovaní, očisťme se od každé poskvrny těla i ducha, dokonávajíce své posvěcení v bázni Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Přijměte nás do svého srdce. Nikomu jsme neublížili, nikomu neuškodili, nikoho neoklamali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Neříkám to k vašemu odsouzení. Vždyť jsem již dříve řekl, že jste v našich srdcích, abyste s námi zemřeli i žili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Mám k vám velikou důvěru, velice se vámi chlubím, jsem naplněn potěšením, má radost daleko převyšuje všechno naše soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Vždyť když jsme přišli do Makedonie, ⌈nezakusili jsme žádnou tělesnou⌉ úlevu, ale ve všem jsme byli sužováni; zvenčí boje, zevnitř strachy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Ale Bůh, který potěšuje sklíčené, potěšil i nás příchodem Titovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'A nejen jeho příchodem, ale i tím potěšením, ⌈které měl on ⌉ z vás; takže když nám vypravoval o vaší touze, o vašem nářku a o vaší horlivosti pro mne, velice jsem se zaradoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Ačkoliv jsem vás ve svém dopise zarmoutil, nelituji toho -- třebaže jsem toho i litoval --, neboť vidím, že vás onen dopis -- byť i nakrátko -- zarmoutil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Teď se raduji ne proto, že jste byli zarmouceni, ale proto, že jste byli zarmouceni ku pokání. Byli jste zarmouceni ⌈podle Boha⌉, ⌈takže jste⌉ od nás v ničem neutrpěli škodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Zármutek, který je podle Boha, působí pokání k záchraně, jehož nelze litovat, kdežto zármutek světa působí smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Hle, co u vás vypůsobilo právě to, že jste se zarmoutili podle Boha: jaké zaujetí, jakou obranu, jaké rozhořčení, jaký strach, jakou touhu, jakou horlivost, jaké potrestání. Ve všem jste prokázali, že jste v té věci čistí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'I když jsem vám napsal, ne bylo to kvůli tomu, kdo ublížil, ani kvůli tomu, komu bylo ublíženo, ale proto, aby se u vás projevilo vaše zaujetí pro nás před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Tím jsme povzbuzeni. Ještě mnohem více nad toto povzbuzení jsme však byli potěšeni radostí Titovou, že jeho duch byl ⌈vámi všemi⌉ občerstven.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Jestliže jsem se mu chlubil něčím, co se týkalo vás, nebyl jsem zahanben; ale jako jsme vám všechno řekli pravdivě, tak i naše chlouba před Titem obstála jako pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'A hojná je jeho náklonnost k vám, když si připomíná poslušnost vás všech, jak jste ho s ⌈bázní a třesením⌉ přijali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Raduji se, že se na vás ve všem mohu spoléhat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Oznamujeme vám, bratři, Boží milost, která byla dána sborům v Makedonii:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Ve veliké zkoušce soužením se rozhojnila jejich překypující radost a jejich hluboká chudoba do bohatství štědrosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Dosvědčuji, že dali podle své možnosti, ba i nad možnost; sami od sebe');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'nás velmi naléhavě prosili o tu milost⌈, aby se mohli účastnit⌉ na službě pro svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'A učinili to ne jen tak, jak jsme očekávali, ale dali sami sebe nejprve Pánu a skrze Boží vůli i nám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Vybídli jsme tedy Tita, aby u vás také dokončil i tuto milost tak, jak již dříve začal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Ale jako se ve všem rozhojňujete, ve víře, v slovu, v poznání, ve vší horlivosti i ⌈v lásce, kterou jsme ve vás vzbudili ⌉, tak se rozhojňujte i v této milosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Neříkám to jako příkaz, nýbrž skrze horlivost druhých chci vyzkoušet také ryzost vaší lásky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Znáte přece milost našeho Pána Ježíše Krista: ačkoli byl bohatý, stal se kvůli vám chudým, abyste vy jeho chudobou zbohatli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Řeknu vám o tom své mínění. Je to užitečné pro vás, kteří jste tuto milost nejen začali již od loňska připravovat, ale sami jste ji i chtěli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Nyní ji také dokonejte, aby stejně tak, jako jste pohotově chtěli, jste to i dokonali z toho, co máte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Neboť je–li ochota dát přiměřená tomu, co člověk má, a ne tomu, co nemá, je vítaná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Ne měla by jiným přinést úlevu a vám ⌈soužení, ale mělo by to být na základě vyrovnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'V nynější⌉ době váš přebytek pomůže jejich nedostatku, aby jejich přebytek zase pomohl vašemu nedostatku, a tak aby nastalo vyrovnání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'jak je napsáno: Tomu, kdo nasbíral mnoho, nepřebylo, a ten, kdo nasbíral málo, neměl nedostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Díky Bohu, že dal Titovi do srdce stejný horlivý zájem o vás,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'takže tu výzvu přijal, a tím horlivější sám od sebe odchází k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Spolu s ním posíláme bratra, o jehož počínání ve službě evangelia se šíří chvála skrze všechny sbory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'A nejen to, ale byl také sbory určen za našeho společníka na cestách s touto milostí, o kterou se staráme ke slávě [samého] Pána a podle naší ochoty si navzájem pomoci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Tak se varujeme toho, že by nás někdo podezíral při naší péči o tuto štědrou hojnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Neboť předem dbáme o to, aby vše bylo správné nejen před Pánem, nýbrž i před lidmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'S nimi ještě posíláme našeho bratra, kterého jsme v četných zkouškách shledali horlivým v mnoha ohledech. A nyní je ještě mnohem horlivější pro velkou důvěru, kterou má k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Pokud jde o Tita, je to můj společník a spolupracovník v práci pro vás, pokud jde o naše bratry, jsou to vyslanci sborů a sláva Kristova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Podejte jim tedy před sbory důkaz své lásky a ⌈toho, že se vámi právem chlubíme⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'O této službě pro svaté je zbytečné, abych vám psal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Neboť znám vaši ochotu, pro kterou se vámi chlubím před Makedoňany, že totiž Achaja je už od loňska připravena; vaše horlivost podnítila většinu z nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Posílám ty to bratry, aby naše hrdost na vás v této věci nevyzněla naprázdno, abyste byli připraveni, jak jsem říkal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'a abychom my -- neřku–li vy -- nebyli zahanbeni v ⌈této jistotě⌉, kdyby se mnou přišli Makedonci a nalezli vás nepřipravené.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Proto jsem považoval za nutné vyzvat ty to bratry, aby k vám šli napřed a připravili toto vaše dopředu slíbené požehnání; ať je takto připravené jako požehnání, a ne jako lakota.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Toto však vězte: Kdo skoupě rozsévá, bude také skoupě sklízet; a kdo štědře rozsévá, bude také štědře sklízet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Každý ať dá, jak si předsevzal v srdci, ne se zármutkem nebo z donucení; vždyť radostného dárce miluje Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'A Bůh je mocen rozhojnit při vás ⌈každý dar milosti⌉, abyste měli vždycky ve všem úplný dostatek a měli hojnost pro každý dobrý skutek,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'jak je napsáno: Rozsypal a dal nuzným, jeho spravedlnost zůstává ⌈na věčnost⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Ten, který poskytuje semeno rozsévajícímu a chléb k jídlu, opatří a rozmnoží vaši setbu a dá vyrůst plodům vaší spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, '⌈Vším způsobem⌉ budete obohacováni k veškeré štědrosti, která skrze nás působí vděčnost Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Péče o tuto službu totiž nejenom doplňuje to, čeho se nedostává svatým, nýbrž také ⌈oplývá mnohými díkůčiněními⌉ Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, '⌈Když se osvědčíte v této službě,⌉ budou oni slavit Boha za ⌈to, že se podřizujete Kristovu evangeliu, které vyznáváte,⌉ a za ⌈štědrost, kterou s nimi a se všemi sdílíte⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Budou se za vás modlit a toužit po vás pro nesmírnou milost Boží, která je při vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Díky Bohu za jeho nevýslovný dar!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Já sám, Pavel, vás napomínám skrze tichost a mírnost Kristovu, já, který tváří v tvář jsem mezi vámi pokorný, ale když jsem vzdálen, jsem k vám smělý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Prosím vás, abych se po svém příchodu nemusil odvážit ⌈být smělý, tak jak⌉ se toho hodlám odvážit vůči některým, kteří si o nás myslí, že ⌈žijeme tělesně⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Neboť ⌈ačkoli žijeme⌉ v těle, nebojujeme podle těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Zbraně našeho boje ne jsou tělesné, ale ⌈ mají od Boha sílu⌉ bořit opevnění; boříme rozumování');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'a každou povýšenost, která se pozvedá proti poznání Boha. Uvádíme do zajetí každou myšlenku, aby byla poslušna Krista,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'a jsme připraveni potrestat každou neposlušnost, jakmile bude vaše poslušnost úplná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Hledíte jen na to, co máte ⌈před očima⌉. Je–li někdo o sobě přesvědčen, že je Kristův, ať si uvědomuje i to, že jako je on Kristův, tak jsme i my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Vždyť i kdybych se sebevíc chlubil naší pravomocí, kterou [nám] Pán dal k vašemu budování, a ne k ničení, nebudu zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Ale nečiním tak, abych nevypadal, jako bych vás chtěl svými dopisy zastrašovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Někdo totiž říká: „ Jeho dopisy jsou závažné a mocné, ale ⌈osobní přítomnost⌉ slabá a řeč ubohá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Takový člověk ať si uvědomí, že jací jsme v psaném slovu, když jsme nepřítomni, takoví budeme také v činu, až budeme přítomni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Netroufáme se totiž zařadit mezi ty, kteří doporučují sami sebe, nebo se k některým z nich přirovnat; vždyť oni se měří sami sebou a přirovnávají se k sobě samým, a nechápou, oč jde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Nebudeme se chlubit ⌈nad stanovenou míru⌉, ale v souladu s výměrou oblasti, kterou nám vyměřil Bůh míry, aby chom dosáhli také až k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Neboť se nevypínáme přes míru, jako bychom k vám nedosahovali, vždyť až i k vám jsme přišli s evangeliem Kristovým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Nechlubíme se ⌈bez míry⌉ ⌈cizí prací,⌉ ale máme naději -- poroste–li vaše víra -- že se mnohem hojněji mezi vámi rozšíříme po naší oblasti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'abychom zvěstovali evangelium i mimo vaše území, a ne budeme se chlubit tím, co je hotovo v oblasti druhých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Kdo se chlubí, ať se chlubí v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Neboť není osvědčený ten, kdo doporučuje sám sebe, nýbrž ten, koho doporučuje Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Kéž byste při mně snesli trochu nerozumnosti -- ano, snášejte mne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Neboť na vás žárlím Boží žárlivostí; zasnoubil jsem vás jedinému muži, abych vás jako čistou pannu představil Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Ale bojím se, aby snad [tak], jako had svou vychytralostí svedl Evu, ⌈nebyla porušena i vaše mysl a neodvrátila se od upřímné [a čisté] oddanosti Kristu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Neboť když někdo přichází a hlásá jiného Ježíše, ⌈než jsme hlásali my ⌉, nebo když přijímáte jiného ducha nebo jiné evangelium, ⌈než jste přijali⌉, klidně to snášíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Mám za to, že nejsem v ničem pozadu za těmi veleapoštoly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'A [jsem]–li prostý v řeči, určitě ne v poznání; vždyť při každé příležitosti jsme ⌈vám to ve všem dali najevo⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Nebo jsem se dopustil hříchu, když jsem sám sebe pokořoval, abyste vy byli vyvýšeni, když jsem vám zvěstoval Boží evangelium zadarmo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Jiné sbory jsem oloupil, když jsem přijal mzdu, abych vám sloužil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'A když jsem byl u vás a měl jsem nedostatek, nikomu ⌈jsem nebyl na obtíž⌉, neboť můj nedostatek doplnili bratři, kteří přišli z Makedonie. Ve všem jsem se zachoval a budu se chovat tak, abych vám ne byl zátěží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Jakože je ve mně Kristova pravda, tato má chlouba nebude v achajských krajích umlčena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Proč? Protože vás nemiluji? Bůh to ví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Ale co činím, budu činit i nadále, abych ⌈nedal možnost⌉ těm, kdo chtějí příležitost, aby v tom, čím se chlubí, byli shledáni stejnými jako my.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Neboť takoví lidé jsou falešní apoštolové, lstiví pracovníci, kteří se přestrojují za apoštoly Kristovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'A ne ní divu; vždyť sám Satan se přestrojuje za anděla světla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Ne ní to tedy nic zvláštního, když se i jeho služebníci přestrojují za služebníky spravedlnosti; jejich konec bude podle jejich skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Znova říkám, aby si někdo o mně nemyslel, že jsem nerozumný; a když ano, přijměte mne i jako nerozumného, abych se i já trochu pochlubil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'To, co teď říkám, neříkám podle Pána, ale jako v nerozumu, v této jistotě chlouby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Protože se mnozí chlubí podle těla, i já se pochlubím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Rádi totiž snášíte nerozumné, protože sami jste rozumní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Snášíte, když vás někdo zotročuje, když vás někdo vyjídá, když vás někdo obírá, když se někdo vyvyšuje, když vás někdo bije do tváře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'K vlastní hanbě vyznávám: jako bychom byli v této věci slabí. Ale v čemkoliv si někdo troufá -- mluvím ovšem z nerozumu --, troufám si i já.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Jsou Hebrejci? Já také. Jsou Izraelci? Já také. Jsou potomci Abrahamovi? Já také.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Jsou služebníci Kristovi? Mluvím bez rozumu: Já nad to. Hojněji v těžkých pracích, hojněji ve vězeních, nad míru v ranách, častokrát ⌈v ohrožení života⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Od Židů jsem pětkrát dostal čtyřicet ran bez jedné,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'třikrát jsem byl bit holí, jednou kamenován, třikrát jsem ztroskotal, noc a den jsem strávil ⌈na širém moři⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'častokrát na cestách, v nebezpečích na řekách, v nebezpečích od lupičů, v nebezpečích od vlastního kmene, v nebezpečích od pohanů, v nebezpečích ve městě, v nebezpečích v pustině, v nebezpečích na moři, v nebezpečích mezi falešnými bratřími;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'v těžké práci a v úsilí, často v nočních bděních, o hladu a žízni, často v postech, v zimě a nahotě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Kromě jiného, co na mne denně doléhá, mám starost o všechny sbory.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kdo je slabý, abych i já nebyl slabý? Kdo je něčím pohoršován, aby to i mě nepálilo?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Mám–li se chlubit, budu se chlubit ⌈tím, v čem jsem sláb⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Bůh a Otec Pána Ježíše, který je požehnaný na věky, ví, že nelžu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'V Damašku místodržitel krále Arety hlídal město, ⌈aby se mne zmocnil⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'ale byl jsem v koši spuštěn oknem ve zdi a unikl jsem jeho rukám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Musím se chlubit, ač [mi] to není k užitku, přistoupím k viděním a zjevením ⌈ od Pána⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Znám člověka v Kristu, který byl před čtrnácti lety vytržen až do třetího nebe -- zda v těle, nevím, nebo mimo tělo, nevím, Bůh to ví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'A vím, že tento člověk -- bylo –li to v těle či bez těla, nevím, Bůh to ví --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'byl vytržen do ráje a uslyšel nevypravitelné věci, o nichž není člověku dovoleno promluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Takovým člověkem se budu chlubit, sám sebou se však chlubit nebudu, leda [svými] slabostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Kdybych se totiž chtěl pochlubit, nebyl bych nerozumný, vždyť bych mluvil pravdu. Nechám však toho, aby si někdo o mně nemyslel víc, než co na mně vidí nebo [co] ode mne ⌈slyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'A abych se mimořádností zjevení nepovyšoval, byl⌉ mi dán do těla trn, Satanův anděl, aby mě políčkoval [a já se nepovyšoval].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Kvůli tomu jsem třikrát prosil Pána, aby ⌈ to ode mne odešlo⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'ale on mi řekl: Stačí ti má milost, neboť [má] moc se dokonává ve slabosti. ⌈Velmi rád⌉ se tedy budu chlubit spíše svými slabostmi, aby na mně spočinula moc Kristova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Proto mám zálibu v slabostech, v zlém zacházení, v tísních, v pronásledováních a úzkostech pro Krista. Neboť když jsem slabý, tehdy jsem mocný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Ztratil jsem rozum! K tomu jste mne přinutili vy. Já mám být od vás doporučován, neboť jsem nebyl v ničem pozadu za těmi veleapoštoly, i když nejsem nic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Znamení apoštola byla mezi vámi uskutečněna ve vší vytrvalosti znameními, divya mocnými činy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'V čem jste na tom byli hůř než ostatní sbory, kromě toho, že já sám jsem vám nebyl na obtíž? Odpusťte mi tuto křivdu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Hle, [to] ⌈jsem potřetí připraven k vám přijít⌉. A nebudu vám na obtíž. Nehledám to, co je vaše, nýbrž vás. Neboť nemají děti shromažďovat pro rodiče, nýbrž rodiče pro děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Já velmi rád vynaložím všechno, ano sám sebe vydám pro vaše duše. Když vás více miluji, mám být za to méně milován?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Ale budiž! Já sám jsem vám nebyl na obtíž, ale jsem prý chytrák a obelstil jsem vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Snad jsem vás podvedl skrze někoho, koho jsem k vám poslal?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Vybídl jsem Tita a poslal jsem s ním bratra. Podvedl vás snad Titus? Což jsme nejednali v témž duchu a ne šli ve stejných šlépějích?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Už dávno si myslíte, že se před vámi obhajujeme. Před Bohem v Kristu mluvíme, a to všechno, milovaní, pro vaše budování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Bojím se totiž, abych vás po svém příchodu neshledal takovými, jakými vás nalézt nechci, a abych já nebyl shledán od vás, jakým si mě nepřejete; aby ne povstaly svár, žárlivost, zlosti, soupeření, utrhání, pomluvy, nadutosti, zmatky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Obávám se, aby mě můj Bůh, až opět přijdu, u vás nepokořil a abych neoplakával mnohé, kteří padli do hříchu a neučinili pokání z nečistoty, smilstva a bezuzdnosti, kterých se dopustili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'To je potřetí, co k vám přicházím. Ústy dvou nebo tří svědků bude potvrzena každá věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Řekl jsem už, když jsem byl u vás podruhé, a když jsem nyní vzdálen, znovu předem říkám těm, kteří zůstali v hříchu, i všem ostatním: až zase přijdu, nebudu nikoho šetřit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'poněvadž hledáte potvrzení, že ve mně mluví Kristus, který není vůči vám slabý, nýbrž je ⌈mezi vámi⌉ mocný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Vždyť ⌈byl sice ⌉ ukřižován ze slabosti, ale žije z moci Boží. I my jsme ⌈v něm⌉ slabí, ale pro vás budeme spolu s ním žítz moci Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Sami sebe zkoušejte, jste–li ve víře, sami sebe zkoumejte. Či nepoznáváte sami na sobě, že Ježíš Kristus [je] ⌈ve vás⌉? Ledaže byste byli neosvědčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Doufám však, že poznáte, že my nejsme neosvědčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Modlíme se k Bohu, abyste neučinili nic zlého; ne proto, abychom se my ukázali jako ti, kdo se osvědčili, nýbrž abyste vy činili dobře, a my abychom byli jako neosvědčení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Neboť nezmůžeme nic proti pravdě, nýbrž pro pravdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Radujeme se, když my jsme slabí, ale vy jste mocní. I za to se modlíme, za vaše zdokonalení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Proto píšu tyto věci, dokud jsem nepřítomen, abych po svém příchodu nemusil jednat přísně podle pravomoci, kterou mi Pán dal k budování, a ne k ničení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Nakonec, bratři, radujte se, napravujte své nedostatky, povzbuzujte se, buďte jedné mysli, žijte v pokoji a Bůh lásky a pokoje bude s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Pozdravte se navzájem svatým políbením; pozdravují vás všichni svatí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Milost Pána Ježíše Krista, Boží láska a společenství Svatého Ducha se všemi vámi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Pavel, apoštol vyslaný ne od lidí nebo skrze člověka, ale skrze Ježíše Krista a Boha Otce, který ho vzkřísil z mrtvých,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'a všichni bratři, kteří jsou se mnou, sborům Galacie:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Milost vám a pokoj od Boha ⌈našeho Otce a Pána⌉ Ježíše Krista,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'který dal sám sebe za naše hříchy, aby nás vysvobodil z tohoto přítomného zlého věku podle vůle našeho Boha a Otce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'jemuž buď sláva na věky věků. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Divím se, že se od toho, který vás povolal ⌈ Kristovou milostí⌉, tak rychle odvracíte k jinému evangeliu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Není jiné evangelium, ale jsou někteří, kteří vás uvádějí ve zmatek a chtějí ⌈Kristovo evangelium⌉ překroutit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Ale i kdybychom [vám] my nebo sám anděl z nebe ⌈zvěstoval v evangeliu⌉ něco ⌈jiného než⌉ to, co jsme vám zvěstovali, budiž proklet!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Jak jsme řekli dříve, i nyní říkám znovu: Jestliže vám někdo ⌈zvěstuje jako evangelium⌉ něco mimo to, co jste přijali, budiž proklet!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Získávám si teď lidi, nebo Boha? Či se snažím líbit lidem? Kdybych se chtěl ještě líbit lidem, nebyl bych Kristův otrok.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Oznamuji vám, bratři, že evangelium, které jsem vám zvěstoval, není podle člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Neboť jsem je nepřevzal ani se mu nenaučil od člověka, ale skrze zjevení Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Vždyť jste slyšeli o mém někdejším počínání, když jsem byl v židovství, že jsem do krajnosti pronásledoval Boží církev a ⌈ničil ji⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Předčil jsem v židovství mnohé vrstevníky svého rodu, neboť jsem byl mimořádný horlivec pro otcovské tradice.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Když se však [Bohu], který mne oddělil již ⌈v lůně⌉ mé matky a povolal svou milostí, zalíbilo');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'zjevit ve mně svého Syna, abych evangelium o něm hlásal mezi pohany, neporadil jsem se hned ⌈s tělem a krví⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'ani jsem nevystoupil do Jeruzaléma k těm, kdo byli apoštoly dříve než já, nýbrž odešel jsem do Arábie a pak jsem se zase vrátil do Damašku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Potom po třech letech jsem vystoupil do Jeruzaléma, abych se seznámil s Kéfou, a zůstal jsem u něho patnáct dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Nikoho jiného z apoštolů jsem neviděl, jen Jakuba, Pánova bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Hle, před Bohem prohlašuji, že to, co vám píšu, není lež.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Potom jsem šel do končin Syrie a Kilikie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Ve sborech v Judsku, které jsou v Kristu, mě osobně neznali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Pouze o mně slýchávali, že ten, který nás kdysi pronásledoval, zvěstuje nyní víru, kterou kdysi ničil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'a slavili kvůli mně Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Potom po čtrnácti letech jsem opět vystoupil do Jeruzaléma s Barnabášem a vzal jsem s sebou i Tita.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Vystoupil jsem tam ⌈na základě⌉ zjevení a předložil jsem jim evangelium, které hlásám mezi pohany; předložil jsem je však v soukromí těm, kteří jsou uznáváni, abych snad neběžel nebo nebyl běžel nadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Ale ani Titus, který byl se mnou a je Řek, nebyl přinucen dát se obřezat,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, '⌈jak to chtěli ti⌉ falešní bratři, vetřelci, kteří se tam vloudili, aby vyšpehovali naši svobodu, kterou máme v Kristu Ježíši, a aby nás zotročili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Ale těm jsme ani na chvíli neustoupili a nepodřídili jsme se jim, aby vám zůstala pravda evangelia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Od těch, kteří něco znamenají -- na tom, jací kdysi byli, mi nezáleží, protože Bůh nepřijímá ⌈člověka podle významu jeho osoby⌉ -- ti uznávaní mně tedy nic dalšího neuložili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Naopak když uviděli, že mi bylo svěřeno evangelium ⌈pro neobřezané⌉ jako Petrovi ⌈pro obřezané⌉ --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'neboť ten, který působil u Petra k apoštolství ⌈pro obřezané⌉, působil i u mne k apoštolství pro pohany --;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'když tedy poznali tu milost, která mi byla dána, po dali Jakub, Kéfas a Jan, kteří byli uznáváni za sloupy církve, mně i Barnabášovi pravici na důkaz společenství, abychom my šli mezi pohany a oni mezi obřezané.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Jen žádali, abychom pamatovali na ⌈ jejich chudé⌉, což jsem právě i já sám pilně činil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Ale když přišel Kéfas do Antiochie, postavil jsem se proti němu tváří v tvář, neboť ⌈si zasloužil odsouzení⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Než totiž přišli někteří od Jakuba, jídával společně s pohany. Když však přišli, začal couvat a oddělovat se, protože se bál těch, kteří byli z obřezaných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'A spolu s ním upadli do pokrytectví i ostatní Židé, takže i Barnabáš byl stržen jejich pokrytectvím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Když jsem však uviděl, že nejdou rovně podle pravdy evangelia, řekl jsem Kéfovi přede všemi: „Jestliže ty, ač jsi Žid, žiješ pohansky, a ne židovsky, jak to, že nutíš pohany, aby žili jako Židé?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'My jsme rodem Židé, a ne hříšníci z pohanů;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'když [však] víme, že člověk není ospravedlňován ze skutků Zákona, nýbrž skrze víru v Ježíše Krista, i my jsme v Krista Ježíše uvěřili, abychom byli ospravedlněni z víry Kristovy, a ne ze skutků Zákona, protože ze skutků Zákona nebude ospravedlněn žádný člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Jestliže však i my, kteří hledáme ospravedlnění v Kristu, jsme byli shledáni hříšnými, je snad proto Kristus služebníkem hříchu? Naprosto ne!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Neboť jestliže znovu buduji to, co jsem zbořil, představuji sebe jako přestupníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Vždyť já jsem skrze Zákon umřel Zákonu, abych žil Bohu. S Kristem jsem ukřižován:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Nežiji už já, ale žije ve mně Kristus. Život, který nyní žiji v těle, žiji ve víře v ⌈Syna Božího⌉, který si mne zamiloval a vydal sebe samého za mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Neodmítám milost Boží, neboť jestliže spravedlnost je ze Zákona, potom Kristus zemřel nadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ó, nerozumní Galaťané, kdo vás očaroval, vás, kterým byl před očima vykreslen Ježíš Kristus ukřižovaný?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Toto jediné se chci od vás dovědět: Přijali jste Ducha ⌈na základě⌉ skutků Zákona, nebo ⌈na základě⌉ slyšení víry?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'To jste tak nerozumní? Začali jste Duchem, a nyní dokončujete tělem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Tolik jste vytrpěli nadarmo? Jestliže to skutečně bylo nadarmo!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Tedy ten, který vás vystrojuje Duchem a působí ⌈mezi vámi⌉ mocné věci, činí tak ⌈na základě⌉ skutků Zákona, nebo ⌈na základě⌉ slyšení víry?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Je tomu jako s Abrahamem: uvěřil Bohu a bylo mu to počteno za spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Vězte tedy, že ti, kdo jsou z víry, jsou synové Abrahamovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Písmo předvídalo, že Bůh ospravedlní pohany ⌈na základě⌉ víry; dopředu oznámilo Abrahamovi: V tobě budou požehnány všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Takže ti, kdo jsou z víry, ⌈docházejí požehnání⌉ s věřícím Abrahamem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Neboť všichni ti, kteří jsou ze skutků Zákona, jsou pod prokletím, neboť je napsáno: Proklet je každý, kdo nezůstává ve všem tom, co je napsáno v knize Zákona, aby to činil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Je jasné, že Zákonem není nikdo před Bohem ospravedlňován, neboť spravedlivý bude živ z víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Zákon však není z víry, nýbrž: Kdo ⌈ty věci⌉ bude činit, bude v nich živ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Kristus nás vykoupil z prokletí Zákona tím, že se stal za nás prokletím, neboť je napsáno: Proklet je každý, kdo je pověšen na dřevě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'To proto, aby k pohanům přišlo to Abrahamovo požehnání v Kristu Ježíši a abychom skrze víru přijali zaslíbení Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Bratři, ⌈po lidsku⌉ pravím: Už potvrzenou závěť člověka nikdo neruší ani k ní nic nepřipojuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Zaslíbení byla řečena Abrahamovi a jeho potomku. Písmo neříká: a potomkům, jako by jich bylo mnoho, ale jedná se jen o jednoho: a tvému potomku, a tím potomkem je Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Říkám tedy toto: Zákon, jenž byl dán po čtyřech stech třiceti letech, nemůže zrušit smlouvu již předtím právoplatně potvrzenou od Boha, a tak zmařit to zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Neboť jestliže je to dědictví ze Zákona, ne ní již ze zaslíbení; Abrahamovi je však Bůh daroval skrze zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'K čemu tedy Zákon? Byl přidán kvůli přestoupením, dokud by nepřišel potomek, kterému bylo dáno zaslíbení. Byl ustanoven skrze anděly rukou prostředníka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Prostředník ⌈však není jen pro jednu stranu ⌉, Bůh však je jeden.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Staví se tedy Zákon proti [Božím] zaslíbením? Rozhodně ne! Neboť kdyby byl dán Zákon, který by byl mocen obživit, byla by spravedlnost vskutku ze Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Avšak Písmo uzavřelo všechno pod hřích, aby bylo dáno zaslíbení z víry Ježíše Krista těm, kdo věří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Dokud nepřišla víra, byli jsme hlídáni pod Zákonem, uzavíráni pro víru, která měla být zjevena,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'takže se Zákon stal naším vychovatelem ke Kristu, abychom byli ospravedlněni z víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Když však přišla víra, nejsme již pod řízeni vychovateli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Neboť všichni jste synové Boží skrze víru v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Vždyť vy všichni, kteří jste byli v Krista pokřtěni, Krista jste oblékli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Již není Žid ani Řek, již není otrok ani svobodný, již není muž ani žena, neboť vy všichni jste jedno v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'A jestliže jste Kristovi, jste símě Abrahamovo, dědicové podle zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Říkám však: Pokud je dědic nezletilý, v ničem se neliší od otroka, ač je pánem všeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Je pod řízen poručníkům a správcům až do doby předem určené otcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Stejně i my, když jsme byli nezletilí, byli jsme v otroctví pod živly světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Když však přišla plnost času, vyslal Bůh svého Syna, narozeného z ženy, narozeného pod Zákonem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'aby vykoupil ty, kdo byli pod Zákonem, a abychom přijali synovství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'A protože jste synové, vyslal Bůh ducha svého Syna do našich srdcí, ⌈ ducha, který volá⌉: Abba, Otče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Takže už nejsi otrok, ale syn. A když syn, tedy i dědic ⌈skrze Boha⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'V čase, kdy jste neznali Boha, otročili jste těm, kteří svou přirozeností nejsou bohy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Nyní však, když jste poznali Boha, nebo spíše když jste byli od Boha poznáni, jak to, že se zase obracíte k těm slabým a ubohým živlům, kterým zase znovu chcete otročit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Zachováváte dny, měsíce, období a roky!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Bojím se o vás, abych se pro vás nakonec nelopotil nadarmo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Prosím vás, bratři, buďte jako já, protože i já jsem jako vy. Ničím jste mi neublížili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Víte, že jsem vám poprvé v slabosti těla hlásal evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'A touto zkouškou, ⌈která se týkala mého tělesného stavu⌉, jste nepohrdli ani ⌈jste se neodvrátili⌉, ale přijali jste mne jako posla Božího, jako Krista Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Kde je tedy to vaše blahoslavenství? Neboť vám vydávám svědectví, že kdyby to bylo možné, byli byste si vyloupli oči a dali je mně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Takže jsem se stal vaším nepřítelem, když vám říkám pravdu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Oni pro vás horlí, ale ne k dobrému; chtějí vás odloučit, abyste horlili pro ně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Je dobré horlit v dobrém vždycky, a ne jenom tehdy, když jsem u vás přítomen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mé děti, které opět v bolestech rodím, dokud ve vás nebude zformován Kristus;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'chtěl bych teď být u vás a změnit svůj hlas, neboť si s vámi nevím rady.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Řekněte mi vy, kteří chcete být pod Zákonem: Což neslyšíte Zákon?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Neboť je napsáno, že Abraham měl dva syny, jednoho z otrokyně a druhého ze svobodné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Ten z otrokyně se však narodil podle těla, ten ze svobodné skrze zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Je to řečeno alegoricky: Tyto ženy jsou dvě smlouvy, jedna z hory Sinaj, která rodí děti do otroctví, a to je Hagar.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Hagar je hora Sinaj v Arábii. Ta odpovídá nynějšímu Jeruzalému, neboť ten je v otroctví se svými dětmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Ale horní Jeruzalém je svobodný a ten je ⌈naší matkou⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Neboť je napsáno: Raduj se neplodná, která nerodíš, propukni v jásot a vykřikni ty, která nemáš porodní bolesti, protože mnoho je dětí té osamělé, více než té, která má muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Vy však, bratři, jste jako Izák dětmi zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Ale jako tenkrát ten, který byl zrozený podle těla, pronásledoval toho, který se narodil podle Ducha, tak je tomu i nyní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Co však praví Písmo? Vyžeň otrokyni i jejího syna, neboť syn otrokyně nebude dědicem spolu se synem svobodné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Proto, bratři, nejsme děti otrokyně, nýbrž té svobodné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, '⌈ K té svobodě nás Kristus osvobodil. Stůjte tedy pevně⌉ a nenechte se opět podrobit pod jho otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Hle, já, Pavel, vám pravím, že dáváte–li se obřezávat, Kristus vám nic neprospěje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'A znova dosvědčuji každému člověku, který se dává obřezat, že je povinen zachovat celý Zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Zbavili jste se Krista, vy, kteří hledáte ospravedlnění v Zákoně; vypadli jste z milosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Neboť my v Duchu ⌈na základě⌉ víry očekáváme naději spravedlnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Neboť v Kristu Ježíši nic neznamená obřízka ani neobřízka, ale víra působící skrze lásku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Běželi jste dobře. Kdo vám zabránil poslouchat pravdu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'To přemlouvání ne ní od toho, který vás povolává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Trocha kvasu prokvasí celé těsto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Jsem o vás přesvědčen v Pánu, že nebudete smýšlet jinak. A ten, kdo vás mate, ponese odsouzení, ať je to kdokoliv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Bratři, jestliže dosud hlásám obřízku, proč jsem ještě pronásledován? Pak by se ztratilo pohoršení kříže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Ti, kdo vás znepokojují obřízkou, ať ⌈se třeba i vyklestí⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Byli jste přece povoláni do svobody, bratři. Jen aby se vám ta svoboda ne stala záminkou pro tělo. Vy však skrze lásku služte jedni druhým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Neboť celý Zákon je naplněn v jednom slovu: Budeš milovat svého bližního jako sebe samého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Jestliže se však navzájem koušete a požíráte, dávejte si pozor, abyste nebyli jeden druhým pohlceni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Říkám však: Duchem choďte a žádost těla nedokonáte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Tělo žádá proti Duchu a Duch proti tělu, neboť stojí navzájem proti sobě, abyste nečinili to, co byste chtěli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Jste–li vedeni Duchem, nejste pod Zákonem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Skutky těla jsou zřejmé, jsou to [cizoložstvo,] smilstvo, nečistota, bezuzdnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'modloslužba, čarování, nepřátelství, ⌈svár, žárlivost⌉, hněvy, soupeření, rozdělení, sekty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'závisti, [vraždy,] opilství, hýření a podobné věci. To vám předpovídám, jak jsem již dříve řekl, že ti, kdo takové věci dělají, neobdrží dědičně Boží království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Ovocem Ducha je však láska, radost, pokoj, trpělivost, laskavost, dobrota, věrnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'mírnost, sebeovládání. Proti takovým není žádný zákon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Ti, kdo patří Kristu [Ježíši], ukřižovali tělo s jeho vášněmi a žádostmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, '⌈Jsme–li Duchem živi⌉, Ducha také následujme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, '⌈Nehledejme marnou slávu⌉, navzájem se neprovokujme a jedni druhým nezáviďme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Bratři, kdyby byl někdo i přistižen v nějakém přestoupení, vy, kdo jste duchovní, napravujte takového člověka v duchu mírnosti a dávej si každý pozor sám na sebe, abys i ty neupadl do pokušení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Neste břemena jedni druhých, a tak naplňte zákon Kristův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Myslí–li si totiž někdo, že je něco, ačkoli nic není, klame sám sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Každý ať zkoumá své jednání, a pak se bude moci chlubit pouze ⌈s ohledem na⌉ sebe, a ne na druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Neboť každý ponese svůj vlastní náklad.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Ten, kdo je vyučován slovu, nechť se sdílí ve všech dobrých věcech s tím, kdo vyučuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, '⌈Nemylte se⌉, Bohu se nikdo nebude vysmívat. Co člověk zaseje, to také sklidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Kdo zasévá pro své tělo, z těla sklidí zkázu; kdo zasévá pro Ducha, z Ducha sklidí život věčný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'V činění dobra neochabujme; nezemdlíme–li, budeme ve svůj čas žnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Tak tedy dokud máme čas, čiňme dobro všem, zvláště však ⌈těm, kteří patří do rodiny⌉ víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Pohleďte, jak velkými písmeny jsem vám napsal vlastní rukou!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Ti, kteří chtějí vypadat dobře ⌈před lidmi⌉, vás nutí dávat se obřezat, jen aby nebyli pronásledováni pro kříž Kristův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Neboť ani ti obřezaní sami Zákon nezachovávají, ale na vás chtějí, abyste se dávali obřezat, aby se mohli pochlubit vaším tělem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Kéž se mi nestane, abych se chlubil, leda křížem našeho Pána Ježíše Krista, skrze nějž je pro mne svět ukřižován a já pro svět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Neboť ani obřízka ani neobřízka nic není, nýbrž nové stvoření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'A na ty, kdo se budou držet tohoto pravidla, ať přijde pokoj a milosrdenství, též na Boží Izrael.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Ať mi už nikdo nepůsobí potíže, vždyť já nosím na svém těle ⌈znaky toho, že patřím ⌉ Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Milost našeho Pána Ježíše Krista buď s vaším duchem, bratři. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Pavel, z Boží vůle apoštol ⌈Krista Ježíše⌉, svatým [v Efesu] a věrným v Kristu Ježíši:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Požehnaný Bůh a Otec našeho Pána Ježíše Krista, který nám požehnal veškerým duchovním požehnáním v nebeských věcech v Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'On si nás v něm vybral před založením světa, abychom byli svatí a bez poskvrny před jeho ⌈tváří v lásce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'když nás podle⌉ zalíbení své vůle předurčil sobě k synovství skrze Ježíše Krista');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'ke chvále slávy jeho milosti, kterou nás obdařil ve svém milovaném Synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'V něm máme vykoupení skrze jeho krev -- odpuštění našich provinění podle bohatství jeho milosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'kterou nás hojně zahrnul ve vší moudrosti a rozumnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'když nám oznámil tajemství své vůle, jak se mu líbilo a jak si předsevzal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'aby ⌈pro správu období, v němž budou naplněny příhodné časy,⌉ uspořádal pod jednu hlavu v Kristu všechny věci: ty na nebesích i ty ⌈na zemi, aby je uspořádal v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'V něm⌉ jsme se stali i dědici, když jsme byli předurčeni podle předsevzetí toho, který působí všechno podle rady své vůle,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'abychom tu byli k chvále jeho slávy, my, kteří jsme již předtím doufali v Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'V něm i vy, když jste uslyšeli slovo pravdy, evangelium své záchrany, a když jste uvěřili, v něm jste byli zapečetěni zaslíbeným Duchem Svatým,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'jenž je závdavkem našeho ⌈dědictví až do⌉ vykoupení získaného vlastnictví k chvále jeho slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Proto i já, když jsem uslyšel o vaší víře v Pánu Ježíši a o lásce ke všem svatým,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'nepřestávám za vás děkovat, ⌈když se [o vás] zmiňuji⌉ na svých modlitbách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'aby vám Bůh našeho Pána Ježíše Krista, Otec slávy, dal Ducha moudrosti a zjevení v pravém poznání jeho samého');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'a osvícené oči srdce, abyste věděli, jaká je naděje v jeho povolání, jaké je bohatství slávy jeho dědictví ve svatých');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'a jak nesmírná je velikost jeho moci vůči nám, kteří věříme ⌈v souladu s působením⌉ převahy jeho síly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Tu uplatnil v Kristu, když jej vzkřísil z mrtvých a posadil po své pravici v nebesích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'vysoko nad každou vládu i autoritu i mocnost i panstvo a nad každé jméno, které je jmenováno nejenom v tomto věku, ale i v budoucím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'A všechno podřídil pod jeho nohy a dal ho za hlavu nade vším církvi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'která je jeho tělem, plností toho, jenž všechno ve všem naplňuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Také vás vzkřísil, když jste byli mrtví pro svá provinění a pro své hříchy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'v nichž jste kdysi žili podle věku tohoto světa, podle vládce mocnosti vzduchu, ducha, který nyní působí ⌈v synech neposlušnosti⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Mezi nimi jsme kdysi i my všichni žili v žádostech svého těla, dělali jsme to, co se líbilo tělu a mysli, a tak jsme byli svou přirozeností děti hněvu tak jako ostatní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Ale Bůh, bohatý v milosrdenství, pro svou velikou lásku, kterou nás miloval,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'i když jsme byli mrtvi pro svá provinění, obživil nás spolu ⌈s Kristem⌉ -- milostíjste zachráněni --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'a spolu s ním nás probudil k životu a spolu posadil na nebeských místech v Kristu Ježíši,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'aby ukázal ⌈v budoucích dobách⌉ oplývající bohatství své milosti v dobrotě k nám v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Neboť jste zachráněni milostí skrze víru; a ta záchrana ne ní z vás -- je to Boží dar;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'ne ní ⌈na základě⌉ skutků, aby se nikdo nechlubil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Vždyť jsme jeho dílo, stvořeni v Kristu Ježíši k dobrým skutkům, které Bůh předem připravil, abychom v nich žili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Proto pamatujte, že ⌈vy, kdysi pohané⌉ tělem, kteří jste byli nazýváni neobřízka ⌈těmi, kdo si říkali⌉ obřízka -- ta byla lidskou rukou činěna na těle --,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'že jste byli v tom čase bez Krista, odcizeni společenství Izraele, ⌈bez účasti na smlouvách⌉ zaslíbení, bez naděje a bez Boha na světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Ale nyní v Kristu Ježíši vy, kteří jste byli kdysi daleko, stali jste se blízkými ⌈v krvi Kristově⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Neboť on je náš pokoj; on oboje učinil jedním a zbořil ⌈rozdělující hradbu⌉, ve svém těle zrušil nepřátelství --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, '⌈Zákon s jeho příkazy a ustanoveními⌉ --, aby v sobě z těch dvou stvořil jednoho nového člověka, učinil pokoj');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'a oba dva usmířil s Bohem v jednom těle skrze kříž, v němž zabil to nepřátelství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Přišel a zvěstoval pokoj vám, kteří jste byli daleko, a pokoj těm, kteří byli blízko,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'neboť skrze něho ⌈jedni i druzí⌉ máme přístup k Otci v jednom Duchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Proto již nejste cizinci a přistěhovalci, nýbrž spoluobčané svatých a patříte do Boží rodiny;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, '⌈byli jste vybudováni⌉ na základě apoštolů a proroků, kde je úhelným kamenem sám Kristus Ježíš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'v němž se celá stavba spojuje dohromady a roste ve svatou svatyni v Pánu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'v něm ⌈jste i vy všichni spolu budováni⌉ v Boží příbytek v Duchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Z toho důvodu já, Pavel, ⌈vězeň Krista Ježíše pro vás pohany --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'pokud⌉ jste vskutku slyšeli o správě Boží milosti, jež mi pro vás byla dána,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, '[že] mi bylo ve zjevení oznámeno tajemství, jak jsem o něm předem krátce napsal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Z toho můžete při čtení poznat, ⌈že rozumím tajemství⌉ Kristovu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'které v jiných pokoleních nebylo lidem oznámeno tak, jak to nyní bylo Duchem zjeveno jeho svatým apoštolům a prorokům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'že totiž pohané jsou spoludědicové a údy téhož těla a spoluúčastníci toho zaslíbení v Kristu Ježíši skrze evangelium,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'jehož služebníkem ⌈jsem se stal⌉ podle daru Boží milosti, ⌈která mi byla dána⌉ ⌈v souladu s působením⌉ jeho moci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mně, nejmenšímu ze všech svatých, byla dána tato milost, abych zvěstoval pohanům Kristovo nevystižitelné bohatství');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'a objasnil [všem], jaká je správa toho tajemství od věků ukrytého v Bohu, jenž všechno stvořil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Skrze církev se tak nyní má stát známou vládám a autoritám v nebesích přerozmanitá Boží moudrost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'podle ⌈odvěkého úmyslu, který⌉ uskutečnil v Kristu Ježíši, našem Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, '⌈V něm smíme otevřeně⌉ a s důvěrou skrze ⌈jeho víru⌉ přistupovat k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Proto žádám, abyste neklesali na mysli kvůli mým soužením pro vás, neboť to je vaše sláva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Z toho důvodu ⌈klekám na⌉ kolena před Otcem [našeho Pána Ježíše Krista],');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'po němž má své jméno každá rodina v nebesích i na zemi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'aby ⌈vás podle bohatství své slávy posílil mocí⌉ skrze svého Ducha na vnitřním člověku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'aby Kristus skrze víru přebýval ve vašich srdcích a abyste byli zakořeněni a založeni v lásce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'a tak abyste byli se všemi svatými schopni pochopit, jaká to šíře a délka a výše a hloubka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'a poznat Kristovu lásku, která převyšuje poznání, a tak byli naplněni až do vší plnosti Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Tomu pak, kdo je mocen podle síly, kterou působí v nás, učinit daleko více nade všechno, co žádáme nebo co si můžeme pomyslet,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'jemu buď sláva v církvi a v Kristu Ježíši po všecka pokolení věčnosti věků! Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Prosím vás tedy já, vězeň v Pánu, abyste vedli život hodný toho povolání, ⌈které jste obdrželi⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 's veškerou pokorou a mírností, s trpělivostí se navzájem snášeli v lásce');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'a usilovali zachovávat jednotu Ducha ve svazku pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Je jedno tělo a jeden Duch, jakož jste byli i povoláni v jedné naději svého povolání;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'jeden Pán, jedna víra, jeden křest;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'jeden Bůh a Otec všech, ten ⌈nade všemi, skrze všechny a ve všech [nás]⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Ale každému z nás byla dána milost podle míry Kristova obdarování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Proto praví: Vystoupil do výše, ⌈odvedl s sebou zajatce⌉ [a] dal dary lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Co jiného znamená vystoupil, než že [nejprve] i sestoupil ⌈do nejnižších částí země⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Ten, jenž sestoupil, je také ten, jenž vystoupil vysoko nad všechna nebesa, aby naplnil všechno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'A on dal jedny apoštoly, jiné proroky, některé evangelisty, jiné pastýře a učitele,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'aby připravili svaté k dílu služby, k vybudování těla Kristova,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'dokud nedospějeme všichni k jednotě víry a plného poznání Syna Božího, v dospělého muže, v míru postavy Kristovy plnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'abychom již více nebyli jako děti, zmítáni vlnami a hnáni každým větrem učení v lidské nestálosti, v chytráctví k ⌈nastražené cestě⌉ bludu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'nýbrž abychom ⌈byli pravdiví v lásce a rostli⌉ všemi způsoby v toho, který je hlavou, v Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Z něho celé tělo, spojované a držené pohromadě ⌈pomocí každého kloubu podpory⌉, která je podle činnosti ⌈a míry⌉ jedné každé části, ⌈bere výživu pro svůj růst⌉ ke svému vybudování v lásce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Toto tedy pravím a dosvědčuji v Pánu, abyste již nežili tak, jako žijí pohané, v marnosti své mysli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Mají zatemněné myšlení a jsou odcizeni od Božího života pro nevědomost, která je v nich kvůli zatvrzelosti jejich srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Otupěli a oddali se bezuzdnosti, aby s nenasytností páchali každý druh nečistoty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Vy však jste se ⌈ o Kristu takto neučili⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'pokud jste jej vskutku slyšeli a byli v něm vyučeni tak, jak je pravda v Ježíši,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'že totiž máte odložit toho starého člověka, který žije podle dřívějšího způsobu života a hyne v klamných žádostech,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'obnovovat se duchem své mysli');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'a obléknout toho nového člověka, který byl stvořen podle Boha ve spravedlnosti a svatosti pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Proto odložte lež a mluvte pravdu každý se svým bližním, neboť jsme údy ⌈téhož těla⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Hněvejte se, a nehřešte; slunce ať nezapadá nad vaším hněvem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Nedávejte místo Ďáblu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Zloděj ať již nekrade, ale ať raději pracuje a dělá [vlastníma] rukama něco dobrého, aby měl co dávat tomu, kdo má nedostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Z vašich úst ať nevychází žádné špatné slovo, nýbrž ⌈jen takové, které je ⌉ dobré k potřebnému budování, aby dalo milost těm, kdo je slyší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'A nezarmucujte Ducha Svatého Božího, jímž jste byli zapečetěni ke dni vykoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Všechna hořkost, zuřivost, hněv, křik a rouhání ať jsou od vás odňaty zároveň se vší špatností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Buďte k sobě navzájem laskaví, milosrdní a ⌈odpouštějte si navzájem, jako i Bůh v Kristu odpustil⌉ vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Napodobujte tedy Boha jako milované děti');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'a žijte v lásce, jako i Kristus miloval nás a vydal sám sebe za nás jako dar a oběť Bohu v příjemnou vůni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Smilstvo ani žádná nečistota nebo chamtivost ať nejsou mezi vámi ani zmiňovány, jak se sluší na svaté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Ani hanebnost, hloupé řeči nebo laškování, což se nesluší; nýbrž raději vzdávejte díky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Neboť toto vězte a znejte, že žádný smilník ani nečistý ani lakomec -- to jest modloslužebník -- nemá dědictví v království Kristově a Božím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Ať vás nikdo nesvádí prázdnými slovy, neboť pro tyto věci přichází Boží hněv na ⌈syny neposlušnosti⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Nemějte s nimi tedy nic společného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Kdysi jste byli tmou, ale nyní jste světlem v Pánu. Žijte jako děti světla --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'ovoce světla je ve veškeré dobrotě, spravedlnosti a pravdě --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'zkoumejte, co se líbí Pánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'a nemějte žádnou účast na neplodných skutcích tmy, spíše je usvědčujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Neboť o tom, co se u nich vskrytu děje, je hanba i mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Ale všechno, co je ⌈světlem usvědčováno, je zjevováno⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'neboť všechno, co je zjevováno, je světlo. Proto praví: Probuď se ty, kdo spíš, a vstaň z mrtvých, a zazáří ti Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Dbejte tedy ⌈pečlivě na to, jak žijete;⌉ ne žijte jako nemoudří, ale jako moudří;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'vykupujte čas, protože dny jsou zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Proto nebuďte nerozumní, ale rozumějte, co je Pánova vůle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'A neopíjejte se vínem, v němž je prostopášnost, ale ⌈naplňujte se Duchem⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'mluvíce k sobě v chvalozpěvech, v ⌈oslavných zpěvech⌉ a v [duchovních] písních, svým srdcem zpívajíce Pánu a velebíce ho');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'a vždycky za všechno děkujíce ve jménu našeho Pána Ježíše Krista Bohu a Otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Podřizujte se jeden druhému v bázni před Kristem:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Ženy, [podřizujte se] svým mužům jako Pánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'neboť muž je hlavou ženy, jako je Kristus hlavou církve; on [je] zachráncem těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Ale jako církev je podřízena Kristu, tak i ženy ve všem svým mužům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Muži, milujte své ženy, jako i Kristus miloval církev a sám sebe za ni vydal,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'aby ji posvětil, když ji očistil ⌈vodní koupelí⌉ v slovu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'aby sám sobě postavil slavnou církev, která by neměla poskvrny ani vrásky ani čehokoliv takového, ale byla svatá a bezúhonná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Takto jsou povinni [i] muži milovat své ženy jako svá těla. Kdo miluje svou ženu, miluje sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Neboť nikdo nemá své tělo v nenávisti, ale živí je a pečuje o ně, jako i Kristus o církev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Vždyť jsme údy jeho těla, [z jeho masa a z jeho kostí].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Proto opustí člověk otce i matku a přilne ke své ženě, a budou ti dva jedno tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Toto tajemství je veliké; vztahuji je však na Krista a na církev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Ale také jeden každý z vás ať miluje svou ženu jako sám sebe a žena ať se bojí svého muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Děti, poslouchejte své rodiče [v Pánu], protože to je spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Cti svého otce a matku, to je první přikázání se zaslíbením,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'aby ti bylo dobře ⌈a abys byl⌉ dlouho živ na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'A vy, otcové, ⌈nedrážděte své děti k hněvu⌉, ale vychovávejte je v Pánově kázni a napomenutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Otroci, poslouchejte pozemské pány ⌈s bázní a chvěním,⌉ v upřímnosti srdce jako Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Neslužte naoko jako ti, kdo se chtějí zalíbit lidem, ale jako Kristovi otroci, kteří z duše činí Boží vůli;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'služte ochotně, jako Pánu, a ne jako lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Víte, že každý, kdo vykoná něco dobrého, vezme za to odměnu od Pána, ať je to otrok nebo svobodný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'A vy, páni, ⌈jednejte s nimi také tak a zanechte⌉ vyhrůžek; vždyť víte, že jejich i váš Pán je v nebesích a že u něho není přijímání osob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Nakonec, [moji bratři,] posilujte se v Pánu a v převaze jeho síly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Oblečte si celou výzbroj Boží, abyste se mohli postavit proti Ďáblovým nástrahám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Neboť náš zápas není proti krvi a tělu, ale proti vládám, proti autoritám, proti světovládcům této temnoty, proti duchovním mocnostem zla v nebeských oblastech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Proto vezměte na sebe celou Boží zbroj, abyste se mohli v den zlý vzepřít, všechno vykonat a zůstat stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Stůjte tedy opásáni na bedrech pravdou, oblečeni v pancíř spravedlnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'nohy obuté v připravenosti k službě evangelia pokoje;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'k tomu všemu vezměte štít víry, jímž budete moci uhasit všechny hořící šípy toho Zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'A vezměte přilbu záchrany a meč Ducha, jímž je Boží slovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Každou modlitbou a prosbou se v každý čas modlete duchem a k tomu bděte s veškerou vytrvalostí a prosbou za všechny svaté,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'i za mne, aby mi bylo dáno slovo, když otevřu ústa, abych směle oznámil tajemství evangelia,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'pro něž jsem poslem v řetězech, a osmělil se v něm tak, jak mi náleží mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'A abyste i vy věděli, co je se mnou a co dělám, všechno vám oznámí Tychikos, milovaný bratr a věrný služebník v Pánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'jehož jsem k vám poslal právě proto, abyste se dověděli, co je s námi, a aby povzbudil vaše srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Pokoj bratřím a láska s vírou od Boha Otce a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Milost se všemi, kdo milují našeho Pána Ježíše Krista ⌈nepomíjející láskou ⌉. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Pavel a Timoteus, otroci Krista Ježíše, všem svatým v Kristu Ježíši, kteří jsou ve Filipech, a také biskupům a diakonům:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Milost vám a pokoj od Boha, našeho Otce a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Děkuji svému Bohu při každé vzpomínce na vás');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'a vždy v každé své modlitbě za vás všechny prosím s radostí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'nad vaší účastí na díle evangelia od prvního dne až doposud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Jsem si jist právě tím, že ten, který ve vás začal dobré dílo, dovede je až do dne Krista Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Vždyť je správné, abych takto smýšlel o vás všech, protože vás mám v srdci; jak ve svých poutech, tak při obhajobě a utvrzování evangelia jste vy všichni se mnou spoluúčastníky milosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Bůh je mi svědkem, jak po vás všech toužím v srdci Krista Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'A za to se modlím, aby se vaše láska ještě víc a více rozhojňovala v důkladnějším poznání a ve vší vnímavosti;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'abyste uměli rozpoznat to, na čem záleží, a byli čistí a bezúhonní pro den Kristův,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'naplněni ovocem spravedlnosti, které nesete skrze Ježíše Krista ke slávě a chvále Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Chci však, bratři, abyste věděli, že mé postavení bylo spíše k prospěchu evangelia;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'vždyť to, že moje pouta jsou pro Krista, se stalo známým ⌈v celé císařské gardě⌉ i všem ostatním,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'a většina ⌈bratrů, kteří se spolehli na Pána, se kvůli mým poutům ještě více⌉ odvažují mluvit beze strachu slovo [Boží].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Někteří sice hlásají Krista také ze závisti a řevnivosti, jiní však i z dobré vůle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Jedni z lásky, neboť vědí, že jsem tu k obraně evangelia,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'druzí zvěstují Krista ze sobectví, ne z čistého úmyslu, a domnívají se, že k mým poutům přidají soužení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Co tedy? Jen když se jakýmkoli způsobem, ať s postranním úmyslem, ať pravdivě zvěstuje Kristus; a z toho se raduji. Ale budu se i dále radovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Neboť vím, že mi to bude k záchraně skrze vaši modlitbu a podporu Ducha Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, '⌈Toužebně očekávám a doufám⌉, že v ničem nebudu zahanben, ale se vší otevřeností, jako vždycky i nyní, bude Kristus zveleben na mém těle, ať životem, ať smrtí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Vždyť žít pro mne znamená Kristus a zemřít zisk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Jestliže tedy mám žít dále v těle, znamená to pro mne užitek z práce a nevím, co bych zvolil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Přitahuje mě obojí: Mám touhu odejít a být s Kristem, což je mnohem, mnohem lepší;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'ale zůstat v těle je nutnější pro vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'O tom jsem přesvědčen a vím, že zůstanu a vytrvám se všemi vámi k vašemu pokroku a radosti ⌈ve víře⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'aby se ⌈v Kristu Ježíši rozhojňovala vaše chlouba ze mne⌉, ⌈až k vám opět přijdu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Jenom veďte život hodný Kristova evangelia, abych, přijdu–li k vám, viděl, či jsem–li nepřítomen, o vás slyšel, že pevně stojíte v jednom Duchu, jako jedna duše zápasíte ⌈ve víře⌉ evangelia');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'a v ničem se nelekáte svých protivníků. Jim je to znamením záhuby,vám však záchrany, a to od Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Neboť vám je z milosti pro Krista dáno, abyste nejen v něj věřili, ale i pro něho trpěli;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'vedete týž zápas, jaký jste při mně viděli a o jakém nyní slyšíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Je –li tedy nějaké povzbuzení v Kristu, je –li nějaké potěšení lásky, je –li nějaké společenství Ducha, je –li nějaký soucit a slitování,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'naplňte mou radost a smýšlejte stejně, mějte stejnou lásku, buďte jedné duše, jednoho smýšlení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'nic nedělejte ze soupeření ani z ješitnosti, nýbrž v pokoře pokládejte jeden druhého za přednějšího než sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Nevěnujte pozornost každý jen vlastním zájmům, nýbrž každý i zájmům těch druhých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, '⌈Mějte [tedy] v sobě to smýšlení, které bylo i⌉ v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, '⌈Ačkoli byl⌉ ve způsobu Božím, ⌈nelpěl na tom⌉, že je roven Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'nýbrž sám sebe zmařil, vzal na sebe způsob otroka a stal se podobným lidem. A ⌈když se ukázal⌉ v podobě člověka,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'ponížil se, stal se poslušným až k smrti, a to smrti na kříži.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Proto ho také Bůh povýšil nade vše a dal mu jméno, které je nad každé jméno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'aby se ve jménu Ježíše sklonilo každé koleno; ti, kdo jsou na nebi i na zemi i pod zemí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'a k slávě Boha Otce aby každý jazyk vyznal, že Ježíš Kristus je Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Proto, moji milovaní, jako jste vždycky poslouchali, nikoli jen v mé přítomnosti, ale nyní mnohem více v mé nepřítomnosti, s bázní a chvěním uvádějte ve skutečnost svou záchranu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Neboť Bůh je ten, který ve vás působí i chtění i činění podle své dobré vůle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Všechno dělejte bez reptání a pochybování,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'abyste byli bezúhonní a bezelstní, Boží děti bez poskvrny uprostřed pokolení pokřiveného a zvráceného, v němž záříte jako světla ve světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Držte pevně slovo života, abyste mi byli chloubou ke dni Kristovu, že jsem nadarmo neběžel ani se nadarmo nenamáhal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Ale i kdybych byl obětován při oběti a boho službě vaší víry, raduji a spoluraduji se s vámi se všemi;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'a stejně i vy se radujte a spoluradujte se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Doufám v Pánu Ježíši, že vám brzo pošlu Timotea, abych i já byl dobré mysli, když se dovím, ⌈co je s vámi⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Nemám nikoho jiného stejně smýšlejícího, jenž by se upřímně staral ⌈o vaše dobro⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'neboť všichni hledají svých věcí, a ne věcí Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Víte sami, ⌈jak se Timoteus osvědčil⌉; vždyť se mnou sloužil evangeliu jako dítě otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Jeho tedy, doufám, ihned pošlu, jakmile uvidím, co bude se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Jsem přesvědčen v Pánu, že i sám brzo přijdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Považoval jsem však za nutné poslat k vám Epafrodita, svého bratra a spolupracovníka i spolubojovníka, ⌈kterého jste poslali, aby mi posloužil v tom, co potřebuji⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Toužil totiž ⌈po vás všech⌉ a byl znepokojen, protože jste se doslechli, že onemocněl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'A opravdu byl nemocen, blízko smrti. Ale Bůh se nad ním smiloval, a nejen nad ním, ale i nade mnou, abych neměl zármutek na zármutek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Poslal jsem ho tedy tím ochotněji, abyste měli radost, že ho zase vidíte, a já abych byl méně zarmoucen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Přijměte ho v Pánu se vší radostí a mějte takové lidi v úctě;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'neboť pro dílo Kristovo se přiblížil až k smrti. ⌈Vlastní život⌉ dal v sázku, aby doplnil, co chybělo ve vaší službě pro mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Konečně, moji bratři, radujte se v Pánu. Psát vám opět tytéž věci mně není zatěžko a pro vás to bude ujištěním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Dejte si pozor na ty psy, dejte si pozor na ty špatné dělníky, dejte si pozor na tu rozřízku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Neboť pravá obřízka jsme my, kteří sloužíme ⌈v Duchu Božím⌉, chlubíme se Kristem Ježíšem a nespoléháme ⌈na sebe⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'ačkoli já bych mohl spoléhat i ⌈na sebe⌉. Zdá–li se někomu jinému, že může spoléhat ⌈na sebe⌉, já tím víc:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'obřezán osmého dne, z rodu izraelského, z kmene Benjamínova, Hebrej z Hebrejů, jde–li o Zákon -- farizeus,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'jde–li o horlivost -- pronásledovatel církve, jde–li o spravedlnost, která je v Zákoně, byl jsem bez úhony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, '[Ale] cokoliv mi bylo ziskem, to jsem pro Krista uznal za ztrátu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'A opravdu také pokládám všechno za ztrátu pro nesmírnou vzácnost poznání Krista Ježíše, svého Pána. Pro něho jsem se všeho zřekl a pokládám to za odpad, abych získal Krista');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'a byl nalezen v něm, nemaje svou spravedlnost, která je ze Zákona, ale tu, která je z ⌈víry v Krista⌉, tu spravedlnost, která je z Boha na základě víry,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'a abych poznal jej a moc jeho vzkříšení i účast na jeho utrpeních. Připodobňuji se jeho smrti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'zda bych nějak ne dospěl ke vzkříšení z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ne že bych již toho dosáhl, anebo byl už dokonalý; usilovně však běžím, abych se opravdu ⌈zmocnil toho, k čemu se i mne ⌉ zmocnil Kristus Ježíš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Bratři, já si nemyslím, že jsem se již toho zmocnil; jedno však činím: zapomínaje na to, co je ⌈za mnou⌉, a natahuje se po tom, co je ⌈přede mnou⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'běžím k cíli pro cenu Božího povolání vzhůru v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Všichni tedy, kteří jsme dokonalí, takto smýšlejme.A smýšlíte–li v něčem jinak, i to vám Bůh zjeví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Jen ⌈se držme toho⌉, k čemu jsme již dospěli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Bratři, všichni spolu ⌈mě napodobujte⌉. Hleďte na ty, kdo ⌈žijí podle našeho příkladu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Neboť mnozí, o nichž jsem vám často říkal, a nyní to pravím s pláčem, žijí jako nepřátelé Kristova kříže;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'jejich koncem je zahynutí, jejich bohem je břicho a jejich sláva je v jejich hanebnosti; ti myslí na to, co je pozemské.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Vždyť naše občanství je v nebesích, odkud také dychtivě očekáváme Zachránce, Pána Ježíše Krista,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'který přetvoří tělo naší poníženosti ve stejnou podobu těla jeho slávy působením, kterým je mocen si také všecko podmanit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'A tak, moji bratři, milovaní a vytoužení, má radosti a koruno, takto stůjte pevně v Pánu, milovaní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Napomínám Euodii a napomínám Syntychu, aby stejně smýšlely v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ano i tebe prosím, ⌈ můj vlastní druhu⌉, pomáhej jim, neboť vedly zápas ⌈za rozšíření evangelia⌉ spolu se mnou i s Klementem a ostatními mými spolupracovníky, jejichž jména jsou v knize života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Radujte se v Pánu vždycky, znovu řeknu: radujte se!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Vaše mírnost ať je známa všem lidem. Pán je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'O nic nebuďte úzkostliví, ale ve všem oznamujte Bohu své žádosti v modlitbě a prosbě s děkováním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'A pokoj Boží, který převyšuje všechno porozumění, bude střežit vaše srdce a vaše myšlenky v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Konečně, bratři, přemýšlejte o všem tom, co je pravdivé, ušlechtilé, spravedlivé, čisté, milé, co má dobrou pověst, jestli je nějaká ctnost a jestli je nějaká chvála.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Čemu jste se naučili, co jste přijali a uslyšeli i spatřili u mne, to dělejte. A Bůh pokoje bude s vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Velmi jsem se v Pánu zaradoval, že konečně rozkvetl váš zájem o mne. Jistě jste na to mysleli dříve, ale neměli jste příležitost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Neříkám to proto, že ⌈bych měl nedostatek⌉; vždyť jsem se naučil být spokojen s tím, co mám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Umím se uskromnit a umím mít i nadbytek. Do všeho jsem zasvěcen: být sytý i hladový, mít nadbytek i nedostatek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Všecko mohu v Tom, který mne posiluje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Avšak učinili jste dobře, že jste se mnou v mé tísni měli účast.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Víte i vy, Filipští, že se v počátcích evangelia, když jsem vyšel z Makedonie, se mnou žádný sbor nepodílel v příjmech a vydáních, jen vy jediní;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'vždyť i do Tesaloniky jste mi ⌈víc než jednou⌉ poslali na mé potřeby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ne že bych toužil po daru, ale toužím po ovoci, které se hromadí na váš účet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Mám všechno, a ještě mi přebývá. ⌈Jsem plně opatřen⌉, když jsem přijal od Epafrodita ⌈to, co jste mi poslali⌉, příjemnou vůni, oběť vítanou, Bohu milou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Můj Bůh naplní všechnu vaši potřebu podle svého bohatství ⌈v slávě⌉ v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Našemu Bohu a Otci sláva na věky věků. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Pozdravte každého svatého v Kristu Ježíši. Pozdravují vás bratři, kteří jsou se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Pozdravují vás všichni svatí, zvláště ti, kteří jsou z císařského domu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Milost Pána Ježíše Krista ⌈s vaším duchem⌉. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Pavel, z Boží vůle apoštol Krista Ježíše, a bratr Timoteus');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'svatým a věrným bratřím v Kristu v Kolosách: Milost vám a pokoj od Boha Otce našeho [a Pána Ježíše Krista].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, '⌈Vždy, když se⌉ za vás modlíme, děkujeme Bohu [a] Otci našeho Pána Ježíše Krista --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'neboť jsme slyšeli o vaší víře v Kristu Ježíši a o lásce, kterou máte ke všem svatým --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'pro naději, která je pro vás uložena v nebesích. O ní jste slyšeli již dříve ve slovu pravdy -- evangeliu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'jež k vám přišlo. A jako na celém světě přináší ovoce a roste, tak je tomu i mezi vámi od toho dne, kdy jste je uslyšeli a poznali Boží milost v pravdě');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'tak, jak jste se naučili od Epafry, našeho milovaného spoluotroka, jenž je věrný služebník Kristův pro vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'On nám také pověděl o vaší lásce v Duchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Proto i my, od toho dne, kdy jsme to uslyšeli, nepřestáváme se za vás modlit a vyprošovat, abyste byli naplněni poznáním jeho vůle ve veškeré moudrosti a duchovním pochopení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'abyste vedli život hodný Pána ⌈a ve všem se mu líbili⌉, abyste nesli ovoce v ⌈každém dobrém skutku⌉ a rostli v poznání Boha');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'a abyste byli posilováni každou mocí podle síly jeho slávy k veškeré vytrvalosti a trpělivosti⌈, s radostí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'vzdávajíce⌉ díky [Bohu] [a] Otci, který nás učinil způsobilými k účasti na podílu svatých ve světle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'On nás vysvobodil z pravomoci temnoty a přenesl do království ⌈Syna své lásky⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'v němž máme [skrze jeho krev] vykoupení, odpuštění hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'On je obraz neviditelného Boha, prvorozený ⌈všeho stvoření⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'neboť v něm bylo stvořeno všechno na nebesích i na zemi, věci viditelné i neviditelné, ať trůny nebo panstva, vlády nebo autority; všechno je stvořeno skrze něho a pro něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'On je přede vším a všechno v něm spočívá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'A on je hlavou těla, církve. On je počátek, prvorozený z mrtvých, aby on sám ⌈zaujal ve všem první místo⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'neboť se Otci zalíbilo, aby v něm přebývala veškerá plnost');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'a aby skrze něho smířil všechno se sebou a způsobil pokoj skrze krev jeho kříže -- aby [skrze něho] smířil vše jak na zemi, tak v nebesích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'I vás, kteří jste kdysi byli odcizeni a myslí nepřátelští ve zlých skutcích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'nyní smířil ⌈ve svém lidském těle⌉ skrze [svou] smrt, aby vás před sebou postavil svaté, bez poskvrny a bez úhony,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'zůstáváte–li vskutku na víře založeni a v ní pevni a nevzdálíte–li se od naděje evangelia, které jste slyšeli, které bylo hlásáno v celém stvoření pod nebem a kterého jsem se já, Pavel, stal služebníkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Nyní se raduji v utrpeních pro vás a ve svém těle doplňuji, co zbývá ze soužení Kristových pro jeho tělo, jímž jest církev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Jejím služebníkem jsem se stal podle Boží správy, která mi pro vás byla svěřena, abych naplnil slovo Boží --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'to tajemství, které bylo od věků a od prvních pokolení ukryté, nyní však bylo zjeveno jeho svatým,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'kterým Bůh toužil oznámit, jaké je bohatství slávy tohoto tajemství mezi pohany: tím tajemstvím je Kristus ve vás, naděje slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Jeho my zvěstujeme napomínajíce každého člověka a vyučujíce každého člověka ve vší moudrosti, abychom každého postavili dokonalého v Kristu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Proto také usilovně pracuji a zápasím ⌈v souladu s⌉ jeho působením, které ⌈je ve mně mocné⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Chci, abyste věděli, jaký zápas vedu pro vás a pro ty, kdo jsou v Laodiceji, i pro všechny, kteří ⌈mne ani osobně⌉ neviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Zápasím o to, aby byli povzbuzeni ve svém srdci a navzájem spojeni v lásce byli dovedeni do celého bohatství plné jistoty porozumění, k plnému poznání ⌈Božího tajemství, Krista⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 've kterém jsou skryty všechny poklady moudrosti a poznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Toto říkám proto, aby vás nikdo nemátl zdánlivě přesvědčivými řečmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Neboť i když jsem tělem nepřítomen, přece jsem duchem s vámi a s radostí vidím váš řád a pevnost vaší víry v Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Když jste tedy přijali Krista Ježíše, Pána, pak v něm žijte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'zakořeněni a budováni v něm, upevňujte se ve víře, jak jste byli vyučeni, rozhojňujíce se ⌈v ní s děkováním⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Dávejte si pozor, ať vás někdo neodvede jako zajatce skrze filozofii-- prázdný svod podle lidské tradice, podle živlů světa, a ne podle Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Neboť v něm tělesně přebývá veškerá plnost Božství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'I vy jste v něm naplněni. On je hlavou každé vlády a moci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'V něm jste byli také obřezáni obřízkou, která nebyla udělána lidskou rukou, nýbrž spočívala ve svlečení těla hříchů, v obřízce Kristově,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'když jste byli spolu s ním ve křtu pohřbeni a v něm jste byli spolu i vzkříšeni skrze víru ⌈ v působení Boha⌉, který ho vzkřísil z mrtvých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'I vás, když jste byli mrtvi v proviněních a neobřízce svého těla, spolu s ním obživil, když nám všechna provinění odpustil');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'a vymazal ⌈rukou psaný záznam⌉, který svými ustanoveními svědčil proti nám a který nám byl nepřátelský; odstranil jej z našeho středu tím, že jej přibil na kříž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Tak odzbrojil vlády a autority a veřejně je vystavil na odiv, když je vedl triumfálním průvodem ⌈v něm⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Ať vás tedy nikdo nesoudí pro pokrm a pro nápoj nebo kvůli svátku, novoluní nebo sobotám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'To všechno je stín budoucích věcí, ale ⌈skutečnost je Kristus⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Ať vás nepřipraví o vítěznou cenu nikdo, kdo si libuje v poníženosti a uctívání andělů, ⌈kdo se nechá unášet tím⌉, co viděl, bezdůvodně se nadýmá pod vlivem svého tělesného smýšlení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'a nedrží se hlavy, z níž celé tělo, podporováno a drženo pohromadě klouby a spoji, roste Božím růstem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Jestliže jste s Kristem zemřeli živlům světa, proč si dáváte předpisovat, jako byste žili ve světě:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'toho se nedotýkej, to neochutnávej, na to ani nesáhni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'To ⌈se týká⌉ vesměs věcí, které jsou spotřebováním určeny k zániku -- ⌈jsou to lidské příkazy a nauky⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Ty sice ⌈působí zdáním⌉ moudrosti v ochotném uctívání, v pokoře a tvrdé kázni těla, ale nemají žádnou cenu⌈, leč pro uspokojení⌉ těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Jestliže jste tedy s Kristem vstali, usilujte o to, co je nahoře, kde Kristus sedí na Boží pravici.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Myslete na to, co je nahoře, ne na to, co je na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Neboť jste zemřeli a váš život je ukryt s Kristem v Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'A když se ukáže Kristus, váš život, tehdy i vy se s ním ukážete ve slávě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Umrtvěte tedy [své] údy, které jsou na zemi: smilstvo, nečistotu, vášeň, zlou žádost a lakomství, které je modloslužbou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, '⌈Pro tyto věci⌉ přichází Boží hněv [na ⌈syny neposlušnosti⌉].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'I vy jste ⌈tak kdysi jednali⌉, když jste v nich žili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Ale nyní odložte to všechno: hněv, vztek, špatnost, rouhání a nemístné řeči ze svých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Nelžete jedni druhým, když jste svlékli toho starého člověka s jeho skutky');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'a oblékli toho nového, který se obnovuje ⌈k pravému poznání podle obrazu⌉ toho, který ho stvořil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Potom tu už není Řek a Žid, obřízka a neobřízka, barbar, Skytha, otrok a svobodný, ale všechno a ve všem Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Oblečte se tedy jako vyvolení Boží, svatí a milovaní, v ⌈slitovný soucit,⌉ dobrotu, pokoru, vlídnost a trpělivost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Snášejte se navzájem a odpouštějte si, má–li kdo něco proti druhému. Jako Pán odpustil vám, odpusťte i vy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'A nad to všechno mějte lásku, která je poutem dokonalosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Pokoj Kristův ať rozhoduje ve vašich srdcích; k němu jste byli také povoláni v jednom těle. A buďte vděčni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Slovo Kristovo ať ve vás bohatě přebývá. Ve vší moudrosti se navzájem vyučujte a napomínejte a ⌈s vděčností⌉ zpívejte Bohu ⌈ve svých srdcích⌉ chvalozpěvy, oslavné zpěvy a duchovní písně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'A všechno, cokoli činíte slovem nebo skutkem, čiňte ve jménu Pána Ježíše a skrze něho děkujte Bohu [a] Otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ženy, podřizujte se svým mužům, jak se sluší v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Muži, milujte své ženy a ⌈nebuďte k nim příkří⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Děti, poslouchejte své rodiče ve všem, neboť to je milé ⌈v Pánu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Otcové, nedrážděte své děti, aby nemalomyslněly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Otroci, poslouchejte ve všem pozemské pány, ne jen naoko, jako ti, kdo se chtějí zalíbit lidem, ale v upřímnosti srdce, bojíce se Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Cokoli děláte, dělejte z duše jako Pánu, a ne lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Vždyť víte, že od Pána dostanete za odměnu dědictví. Pánu Kristu služte!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Neboť kdo ⌈činí zlé⌉, dostane zpět to, co zlého učinil. ⌈ Bůh nikomu nestraní⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Páni, prokazujte otrokům, co je spravedlivé a správné; vždyť víte, že i vy máte Pána v nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'V modlitbě buďte vytrvalí; buďte v ní bdělí ⌈a vděční⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Modlete se současně i za nás, aby nám Bůh otevřel dveře slova, abychom mohli mluvit o tajemství Kristovu, pro něž jsem také spoután,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'abych je učinil zjevným tak, jak jsem povinen o něm mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Žijte moudře před těmi, kteří jsou vně, vykupujíce čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Vaše řeč ať je vždy laskavá, okořeněná solí, abyste věděli, jak máte každému odpovědět.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Co je se mnou, vám oznámí Tychikos, milovaný bratr, věrný služebník a spoluotrok v Pánu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'jehož jsem k vám poslal právě proto, ⌈abyste se o nás dověděli⌉ a aby povzbudil vaše srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Posílám ho s Onezimem, věrným a milovaným bratrem, jenž je od vás. Ti vám oznámí všechno, co se zde děje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Pozdravuje vás můj spoluvězeň Aristarchos a Barnabášův bratranec Marek, o němž jste dostali pokyny; až k vám přijde, přijměte ho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Dále Ježíš zvaný Justus. Oni jsou ze Židů moji jediní spolupracovníci pro Boží království; stali se mou útěchou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Pozdravuje vás Epafras, který je od vás, otrok Krista [Ježíše]; on za vás ustavičně zápasí na modlitbách, abyste byli postaveni zralí a úplní v celé vůli Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Dosvědčuji mu, že pro vás a pro ty, kdo jsou v Laodiceji a v Hierapoli, vynakládá mnoho namáhavé práce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Pozdravuje vás milovaný lékař Lukáš a Démas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Pozdravte bratry v Laodiceji i Nymfu a církev, která je v jeho domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'A až bude u vás ten to dopis přečten, zařiďte, aby byl přečten také v laodicejském sboru a abyste i vy přečetli ⌈ dopis Laodicejským⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'A Archippoviřekněte: Hleď si služby, kterou jsi v Pánu přijal, abys ji plnil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Pozdrav mou, Pavlovou rukou. Pamatujte na ⌈má pouta⌉. Milost s vámi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Pavel, Silvanus a Timoteus církvi Tesaloničanů v Bohu Otci a Pánu Ježíši Kristu: Milost vám a pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Stále vzdáváme díky Bohu za vás za všecky, když se [o vás] zmiňujeme na svých modlitbách, a neustále');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'máme na paměti váš skutek víry, vaši námahu lásky a vytrvalost naděje našeho Pána Ježíše Krista před naším Bohem a Otcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Víme, bratři Bohem milovaní, o vašem vyvolení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'neboť naše evangelium k vám nepřišlo jen ve slovu, ale i v moci a v Duchu Svatém a v plné přesvědčivosti; vždyť sami víte, jací jsme byli mezi vámi kvůli vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'A vy jste se stali těmi, kdo napodobují nás i Pána, když jste přijali Slovo v mnohém soužení s radostí Ducha Svatého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Tím jste se stali vzorem všem věřícím v Makedonii a v Achaji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Neboť od vás se rozeznělo Pánovo slovo nejen v Makedonii a v Achaji, ale [i] vaše víra, která směřuje k Bohu, se rozšířila všude, takže není třeba, abychom o tom vůbec mluvili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Oni sami totiž o nás vypravují, jaký ⌈byl náš příchod⌉ k vám a jak jste se obrátili od model k Bohu, abyste sloužili živému a pravému Bohu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'a očekávali z nebes jeho Syna, kterého probudil z mrtvých, Ježíše, který nás vysvobozuje od přicházejícího hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Sami víte, bratři, že náš příchod k vám nezůstal bez užitku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'I když jsme předtím ve Filipech trpěli a byli potupeni, jak sami víte, odhodlali jsme se ve svém Bohu vám v mnohém zápase směle mluvit Boží evangelium.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Vždyť naše povzbuzování není z poblouzení ani z nečistoty ani ve lsti;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'ale Bůh nás vyzkoušel, aby nám svěřil evangelium, proto mluvíme ne tak, jako bychom se chtěli zalíbit lidem, ale tak, abychom se zalíbili Bohu, který zkouší naše srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Jak víte, nikdy ⌈jsme nepoužili lichocení⌉ ani jsme nebyli chtiví zisku -- Bůh je svědek!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Nehledáme ani slávu od lidí, od vás ani od jiných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Jako Kristovi apoštolové můžeme užívat vážnosti, avšak ⌈byli jsme⌉ mezi vámi něžní, jako když žena chová vlastní děti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Tak jsme po vás toužili, že jsme byli ochotni dát vám nejen evangelium Boží, ale i své duše, neboť jste se nám stali drahými.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Jistě pamatujete, bratři, na naši těžkou práci a lopotu, jak jsme dnem i nocí pracovali, abychom nikomu z vás nebyli na obtíž, když jsme vám vyhlásili evangelium Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vy i sám Bůh jste svědky, jak jsme se svatě, spravedlivě a bezúhonně k vám věřícím chovali;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'a jak také víte, jednoho každého z vás jsme napomínali, povzbuzovali a zavazovali jako otec vlastní děti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'abyste žili, jak je důstojné Boha, který vás povolává do svého království a slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'A proto i my vzdáváme neustále díky Bohu, že když jste od nás převzali slovo Boží zvěsti, přijali jste je ne jako slovo lidské, ale tak, jak tomu opravdu je, jako slovo Boží, které také mocně působí ve vás věřících.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Vždyť vy jste, bratři, napodobili církve Boží, které jsou v Judsku v Kristu Ježíši, protože i vy jste ⌈stejně trpěli⌉ od vlastních krajanů, jako i oni od Židů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'kteří zabili Pána Ježíše i [své] proroky a také nás pronásledovali; Bohu se líbit nechtějí a vůči všem lidem jsou nepřátelští.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Brání nám mluvit k pohanům, aby byli spaseni, čímž stále doplňují své hříchy; ale přišel na ně hněv až do krajnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Byli jsme, bratři, od vás ⌈na určitou dobu⌉ odloučeni, bylo to však jen tělem, ne srdcem; o to více jsme s velkou touhou usilovali spatřit vaši tvář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Proto jsme k vám chtěli přijít, já Pavel ⌈víc než jednou⌉, ale Satan nám v tom zabránil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Kdo je naše naděje nebo radost nebo věnec chlouby, ne–li právě vy před naším Pánem Ježíšem při jeho příchodu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Vždyť vy jste naše sláva i radost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Protože jsme to již ne mohli déle vydržet, uznali jsme za vhodné zůstat v Athénách sami');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'a poslali jsme Timotea, našeho bratra a Božího spolupracovníka v Kristově evangeliu, aby vás upevnil a povzbudil ve vaší víře,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'aby se nikdo nezmítal v těchto souženích. Sami přece víte, že k tomu tu jsme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Vždyť když jsme byli u vás, předem jsme vám říkali, že nás čeká soužení. To, jak víte, se i stalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Když jsem to tedy ne mohl déle vydržet, poslal jsem Timotea, abych se dověděl o vaší víře, jestli vás snad Pokušitel nějak nezkusil, aby tak naše námaha nevyšla naprázdno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Nyní však k nám od vás přišel Timoteusa přinesl nám radostnou zprávu o vaší víře a lásce i o tom, že na nás stále v dobrém vzpomínáte a toužíte nás spatřit stejně jako i my vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Proto jsme byli, bratři, ve vší své tísni a soužení povzbuzeni skrze vaši víru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'protože nyní skutečně žijeme, jestliže vy pevně stojíte v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Vždyť jakou vděčností za vás můžeme Bohu odplatit za všechnu tu opravdovou radost, kterou z vás máme před naším Bohem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Ve dne v noci převelice prosíme, abychom vás mohli spatřit a doplnit nedostatky vaší víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Sám Bůh a náš Otec a náš Pán Ježíš kéž urovná naši cestu k vám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'A vás ať Pán rozhojní a dá vám oplývat v lásce k sobě navzájem i ke všem lidem, jako i my máme lásku k vám,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'ať tak upevní vaše srdce, aby byla bezúhonná v svatosti před Bohem a naším Otcem v příchodu našeho Pána Ježíše se všemi jeho svatými. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Nakonec vás, bratři, žádáme a vyzýváme v Pánu Ježíši, abyste se ještě více rozhojňovali v tom, co jste od nás převzali a ⌈co už také činíte⌉ -- totiž jak máte žít, abyste se líbili Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Vždyť víte, které příkazy jsme vám vy dali skrze Pána Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Neboť toto je vůle Boží, vaše posvěcení, abyste se zdržovali smilstva,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'aby každý z vás uměl zacházet se svou nádobou ve svatosti a úctě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'ne v žádostivé vášni jako pohané, kteří neznají Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'a aby nikdo nepřekračoval meze a ⌈neklamal v této věci svého⌉ bratra, protože Pán je mstitelem v těch všech věcech, jak jsme vám také předem řekli a plně dosvědčili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Neboť Bůh nás nepovolal k nečistotě, nýbrž k tomu, abychom žili v posvěcení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Proto kdo toto odmítá, neodmítá člověka, ale Boha, který [také] do vás dává svého Svatého Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'O bratrské lásce vám není potřeba psát, neboť jste sami vyučeni od Boha, abyste milovali jeden druhého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'A opravdu tak činíte všem bratřím v celé Makedonii. Vyzýváme vás však, bratři, abyste se v tom ještě více rozhojňovali');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'a zakládali si na pokojném životě, věnovali se vlastním věcem a pracovali vlastníma rukama, jak jsme vám přikázali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'a abyste žili slušně před těmi, kteří jsou vně, a nikoho nepotřebovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Nechceme vás, bratři, nechávat v nevědomosti o těch, kdo zesnuli, abyste se nermoutili jako ti ostatní, kteří nemají naději.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Jestliže však věříme, že Ježíš zemřel a vstal z mrtvých, tak Bůh také ⌈ty, kdo zemřeli skrze Ježíše, přivede⌉ s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Neboť toto vám říkáme slovem Pánovým: My živí, kteří jsme tu ponecháni do příchodu Pána, jistě nepředejdeme ty, kteří zesnuli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'protože ⌈za zvuku přikazujícího zvolání, hlasu archanděla a⌉ Boží polnice sám Pán sestoupí z nebe a mrtví v Kristu vstanou nejdříve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Potom my živí, kteří tu budeme ponecháni, budeme spolu s nimi uchváceni v oblacích do vzduchu k setkání s Pánem. A tak už na vždy budeme s Pánem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Proto se těmito slovy navzájem povzbuzujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'O časech a dobách, bratři, nepotřebujete, aby vám bylo psáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Vždyť sami přesně víte, že Pánův den přijde jako zloděj v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Když lidé budou říkat: Pokoj a bezpečí, tehdy na ně náhle přijde zkáza jako porodní bolesti na těhotnou ženu, a jistě neuniknou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Vy však, bratři, nejste ve tmě, aby vás ten den přepadl jako zloděj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Neboť vy všichni jste synové světla a synové dne. Nepatříme noci ani tmě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Proto tedy nespěme jako ti ostatní, nýbrž buďme bdělí a střízliví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Vždyť ti, kdo spí, spí v noci, a ti, kdo se opíjejí, opíjejí se v noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'My však, ⌈kteří patříme dni⌉, buďme střízliví, oblečeni v pancíř víry a lásky a v přilbu naděje spasení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Neboť Bůh nás nepostavil k hněvu, nýbrž k získání spasení skrze našeho Pána Ježíše Krista,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'který za nás zemřel, abychom my, ať ⌈bdíme nebo spíme⌉, žili spolu s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Proto se navzájem povzbuzujte a budujte jeden druhého, jak to již činíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Žádáme vás, bratři, abyste uznávali ty, kteří mezi vámi namáhavě pracují, jsou vašimi představenými v Pánu a napomínají vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Převelice si jich v lásce važte pro jejich práci; žijte mezi sebou pokojně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Vyzýváme vás, bratři, napomínejte neukázněné, potěšujte malomyslné, ujímejte se slabých, mějte trpělivost se všemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Hleďte, aby nikdo neodplácel nikomu zlým za zlé, ale vždy usilujte o dobro k sobě navzájem i vůči všem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Vždycky se radujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Neustále se modlete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Ve všem vzdávejte díky, neboť toto je pro vás Boží vůle v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Ducha neuhašujte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Proroctvími nepohrdejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Všechno však zkoušejte; co je dobré, to pevně držte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'a všeho, co vypadá zle, se vystříhejte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'A sám Bůh pokoje kéž vás celé posvětí a celého vašeho ducha i duši i tělo kéž zachová bez poskvrny až k příchodu našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Věrný je ten, kdo vás povolává; on to také učiní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Bratři, modlete se [též] za nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Pozdravte všechny bratry svatým políbením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Zavazuji vás přísahou v Pánu, abyste tento list dali přečíst všem [svatým] bratřím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Milost našeho Pána Ježíše Krista s vámi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Pavel, Silvanus a Timoteus církvi Tesaloničanů v ⌈Bohu, našem Otci,⌉ a v Pánu Ježíši Kristu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Milost vám a pokoj od Boha, [našeho] Otce, a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Bratři, jsme zavázáni stále za vás Bohu vzdávat díky, jak je to správné, protože převelice roste vaše víra a rozhojňuje se láska všech vás k sobě navzájem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'I my sami se tedy vámi chlubíme v církvích Božích pro vaši vytrvalost a víru ve všech vašich pronásledováních a souženích, která snášíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Je to jistým znamením spravedlivého soudu Božího, abyste byli uznáni hodnými Božího království, pro něž také trpíte,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'pokud je spravedlivé u Boha to, aby těm, kteří vás sužují, odplatil soužením,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'a vám, kteří jste v soužení, úlevou spolu s námi, ⌈až se zjeví⌉ z nebe Pán Ježíš ⌈se svými mocnými anděly');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'a v plameni ohně bude trestat ty,⌉ kteří neuznávají Boha, a ty, kteří nejsou poslušni evangelia našeho Pána Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Ti ponesou trest, věčnou zkázu v odloučení od Pánovy tváře a od slávy jeho síly,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'když přijde, aby v onen den byl oslaven ve svých svatých a aby se stal předmětem obdivu ve všech těch, kdo uvěřili, neboť naše svědectví došlo u vás víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Proto se za vás také stále modlíme, aby vás náš Bůh učinil hodnými svého povolání a v moci naplnil každý dobrý úmysl a skutek víry,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'aby tak bylo oslaveno jméno našeho Pána Ježíše ve vás a vy v něm podle milosti našeho Boha a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Pokud jde o příchod našeho Pána Ježíše Krista a naše shromáždění k němu, žádáme vás, bratři,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'abyste se ne nechali snadno otřást ve svém poznání ani vylekat buď skrze ducha, nebo skrze slovo nebo skrze dopis, vydávaný za náš, jako by den Pánův již nastal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Ať vás nikdo žádným způsobem nesvede, protože nenastane, dokud napřed nepřijde odpadnutí a nebude zjeven ten člověk bezzákonnosti, syn záhuby,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'který se staví na odpor proti všemu a pyšně se pozvedá nade všecko, čemu se říká Bůh nebo co se uctívá, takže sám usedne [jako Bůh] do Boží svatyně a bude se ⌈vydávat za Boha⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Nevzpomínáte si, že jsem vám toto říkal, ještě když jsem byl u vás?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Také víte, co ho nyní zdržuje, aby byl zjeven až ve svůj čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Neboť tajemství této bezzákonnosti již působí; jen čeká, dokud ten, kdo je nyní zdržuje, ⌈nebude z prostředku vzat ⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'A potom bude zjeven ten Bezzákonný, kterého Pán Ježíš odstraní dechem svých úst a zahladí jej i jeho skutky jasným zjevením ⌈svého příchodu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, '⌈Příchod Bezzákonného ⌉ je podle působení Satana se vší mocí, znameními a lživými zázraky');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'a s veškerým klamem nepravosti pro ty, kteří hynou, protože nepřijali ⌈lásku k pravdě⌉, aby byli zachráněni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Proto na ně Bůh posílá mocné působení bludu, aby uvěřili lži');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'a aby všichni, kdo neuvěřili pravdě, ale nalezli zalíbení v nepravosti, byli tak odsouzeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'My pak jsme zavázáni, bratři Pánem milovaní, stále za vás vzdávat díky Bohu, že si vás vybral ⌈ jako prvotinu⌉ k záchraně v posvěcení ducha a ⌈víře v pravdu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'K tomu vás [i] povolal skrze naše evangelium, abyste získali slávu našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Proto tedy, bratři, stůjte pevně a držte ⌈učení, která jsme vám předali⌉ a kterým jste byli vyučeni, ať už slovem nebo dopisem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Sám náš Pán Ježíš Kristus a ⌈Bůh, náš Otec⌉, který si nás zamiloval a v milosti nám daroval věčné potěšení a dobrou naději,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'nechť vaše srdce povzbudí a upevní v každém dobrém skutku i slovu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Nakonec, bratři, modlete se za nás, aby se Pánovo slovo ⌈rychle šířilo⌉ a bylo slaveno tak jako u vás');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'a abychom byli vysvobozeni od pobloudilých a zlých lidí; neboť ne všichni mají víru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Věrný je Pán, který vás upevní a ochrání od Zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Vždyť jsme o vás přesvědčeni v Pánu, že věci, které [vám] přikazujeme, činíte a budete činit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Kéž Pán uvede vaše srdce do Boží lásky a do Kristovy trpělivosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Přikazujeme vám, bratři, ve jménu [našeho] Pána Ježíše Krista, abyste se stranili každého bratra, ⌈který žije⌉ neukázněně, a ne podle ⌈toho, co⌉ jste od nás převzali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Vždyť sami víte, jak nás máte napodobovat, protože jsme mezi vámi nebyli neukáznění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Ani jsme u nikoho nejedli zadarmo chléb, ale dnem i nocí jsme s ⌈námahou a úsilím⌉ pracovali, abychom nikomu z vás nebyli na obtíž.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Ne že bychom k tomu neměli právo, ale ⌈takto jsme⌉ vám dali sami sebe za vzor, abyste nás napodobovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Neboť když jsme u vás byli, přikazovali jsme vám toto: Jestliže někdo nechce pracovat, ať také nejí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Slyšíme totiž, že někteří mezi vámi žijí neukázněně, vůbec nepracují, ale zabývají se tím, do čeho jim nic není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Takovým přikazujeme a vyzýváme je ⌈v Pánu Ježíši Kristu⌉, aby s tichostí pracovali a jedli vlastní chléb.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Vy však, bratři, neochabněte v konání toho, co je správné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Jestliže někdo neposlouchá naše slovo v tomto dopise, ⌈dávejte si na něho pozor⌉ [a] nestýkejte se s ním, aby se zastyděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Avšak nepokládejte ho za nepřítele, nýbrž napomínejte ho jako bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Sám Pán pokoje nechť vám daruje pokoj vždy a ⌈každým způsobem⌉. Pán se všemi vámi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Pozdrav mou, Pavlovou rukou, což je znamením v každém dopise; takto píšu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Milost našeho Pána Ježíše Krista s vámi všemi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Pavel, apoštol Krista Ježíše podle příkazu Boha, našeho Zachránce, a Krista Ježíše, naší naděje,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timoteovi, ⌈vlastnímu synu⌉ ve víře: ⌈Milost, milosrdenství a pokoj⌉ od ⌈Boha Otce [našeho]⌉ a Krista Ježíše, Pána našeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Když jsem cestoval do Makedonie, vybídl jsem tě, abys zůstal v Efesu a nařídil jistým lidem, aby neučili odchylným naukám');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'a nezabývali se bájemi a nekonečnými rodokmeny, které vedou spíše k hloubání než k Boží správě, která spočívá na víře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Cílem toho to nařízení je láska z čistého srdce, z dobrého svědomí a z upřímné víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Od toho se někteří odchýlili a obrátili se k prázdnému mluvení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Chtějí být ⌈učiteli Zákona⌉, a nechápou ani to, co říkají, ani to, o čem se tak jistě vyslovují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Víme, že Zákon je dobrý, když ho někdo užívá náležitě');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'a je si vědom toho, že Zákon není dán pro spravedlivého, nýbrž pro lidi nespravedlivé a nepoddajné, bezbožné a hříšné, pro lidi nesvaté a světské, pro otcovrahy a matkovrahy, pro vrahy vůbec,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'smilníky, lidi praktikující homosexualitu, únosce, lháře, křivopřísežníky, a co ještě jiného se příčí zdravému učení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'podle ⌈evangelia slávy⌉ blahoslaveného Boha, které mi bylo svěřeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Děkuji tomu, který mne posilnil, Kristu Ježíši, našemu Pánu, že mě uznal za spolehlivého a ustanovil ke službě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'ačkoli jsem byl předtím rouhač, pronásledovatel a násilník. Došel jsem však milosrdenství, protože jsem to činil z nevědomosti v nevěře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'A tím hojněji se projevila milost našeho Pána s vírou a láskou, která je v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, '⌈Věrohodné je to slovo⌉ a zaslouží si plného přijetí: Kristus Ježíš přišel na svět, aby zachránil hříšníky. Z nich jsem já první,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'avšak proto jsem došel milosrdenství, aby Kristus Ježíš na mně prvním ukázal veškerou svou trpělivost jako příklad pro ty, kdo v něho budou věřit k životu věčnému.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Králi věků, nepomíjejícímu, neviditelnému, jedinému [moudrému] Bohu čest a sláva na věky věků. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Toto nařízení svěřuji tobě, můj synu Timoteji, na základě předešlých proroctví o tobě, abys ⌈s jejich posilou ⌉ bojoval dobrý boj,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'maje víru a dobré svědomí, jímž někteří pohrdli, a proto ztroskotali ve víře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Patří k nim Hymenaios a Alexandr, které jsem vydal Satanu, aby se naučili nerouhat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Především tedy prosím, aby se konaly prosby, modlitby, přímluvy a děkování za všechny lidi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'za králea za všechny ty, kdo jsou ve vysokém postavení, abychom mohli vést tichý a pokojný život ve vší zbožnosti a důstojnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'To je dobré a milé před Bohem, naším Zachráncem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'který chce, aby byli všichni lidé zachráněni a přišli k poznání pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Je totiž jeden Bůh, jeden je také prostředník mezi Bohem a lidmi, člověk Kristus Ježíš,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'který dal sám sebe jako výkupné za všechny, jako svědectví ve svůj čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'K tomu jsem byl ustanoven hlasatelem a apoštolem-- mluvím pravdu [v Kristu], nelžu --, učitelem národů ve víře a v pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Chci tedy, aby se muži modlili na každém místě, pozvedajíce svaté ruce bez hněvu a sváru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Stejně i ženy ať se v slušném oděvu zdobí počestně a střízlivě, ne účesy a zlatem, perlami nebo drahými šaty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'nýbrž dobrými skutky, jak se sluší na ženy, které se přiznávají k zbožnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Žena ⌈ať se učí⌉ v tichosti a ⌈s veškerou podřízeností⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Nedovoluji, aby žena učila nebo měla moc nad mužem, nýbrž má být v tichosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Neboť první byl utvořen Adam, potom Eva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'A nebyl sveden Adam; žena byla zcela svedena a upadla do přestoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Bude však zachráněna skrze rození; ženy jsou zachráněny, setrvají–li ve víře, lásce a v posvěcení spolu se střízlivostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Věrohodné je to slovo: Usiluje–li někdo o biskupství, touží po dobré práci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Biskup tedy má být bezúhonný, muž jedné ženy, střídmý, rozvážný, řádný, pohostinný, schopný učit,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'ne pijan, ne rváč, nýbrž mírný, ne svárlivý nebo hrabivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Má dobře vést svou rodinu a udržovat děti v poslušnosti se vší počestností.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Neumí–li někdo vést svou rodinu, jak se bude starat o Boží církev?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, '⌈Nemá být teprve nedávno obrácený⌉, aby nezpyšněl a neupadl do Ďáblova odsouzení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Musí však mít také dobré svědectví od těch, kdo stojí mimo, aby neupadl do pohanění a do Ďáblovy léčky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Rovněž diakoni mají být čestní, ne neupřímní, ne oddaní mnohému pití vína, ne hanebně ziskuchtiví;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'mají mít tajemství víry v čistém svědomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'I oni ať jsou nejprve zkoumáni, a teprve potom, jsou–li bez úhony, ať konají svou službu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Právě tak ženy mají být čestné, ne pomlouvačné, střídmé, ve všem věrné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Diakoni ať jsou muži jedné ženy, ať dobře vedou své děti a vlastní rodiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Neboť ti, kdo dobře vykonali svou službu, získávají si ⌈dobré postavení⌉ a mnoho smělé důvěry ve víře, která je v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Tyto věci ti píšu ⌈v naději⌉, že k tobě brzo přijdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Kdybych se však opozdil, chci, abys věděl, jak je třeba se chovat v domě Božím, jímž je církev Boha živého, sloup a opora pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'A vpravdě veliké je to tajemství zbožnosti: ⌈ Ten, který⌉ se zjevil v těle, byl ospravedlněn v Duchu, ukázal se andělům, byl hlásán národům, ve světě mu uvěřili, byl přijat ⌈ve slávě⌉ vzhůru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Duch výslovně praví, že v posledních dobách někteří odstoupí od víry, přidržujíce se bludných duchů a učení démonů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'těch, kteří v pokrytectví mluví lež a mají vypálené znamení na vlastním svědomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Zabraňují lidem ženit se a nařizují jim zdržovat se pokrmů, které Bůh stvořil, aby je s děkováním požívali ti, kdo věří a poznali pravdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Neboť ⌈všechno, co Bůh stvořil⌉, je dobré a nemá se zavrhovat nic, co se přijímá s děkováním:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'posvěcuje se to skrze slovo Boží a přímluvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Když budeš toto předkládat bratřím, budeš dobrým služebníkem Krista Ježíše, živeným slovy víry a dobrého učení, které sis osvojil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Světské a babské báje odmítej. Cvič se pro zbožnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Tělesné cvičení je užitečné pro málo věcí, avšak zbožnost je užitečná ke všemu, neboť má zaslíbení nynějšího i budoucího života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Věrohodné je to slovo a ⌈zaslouží si plného souhlasu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Proto se namáháme a zápasíme, že máme naději v živém Bohu, který je Zachráncem všech lidí, zvláště věřících.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'To nařizuj a tomu uč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Nikdo ⌈ať tebou nepohrdá pro tvé mládí⌉, ale těm, kdo věří, buď vzorem v řeči, v chování, v lásce, [v Duchu,] ve víře, v čistotě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Než přijdu,věnuj se předčítání, napomínání, vyučování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Nezanedbávej v sobě dar milosti, který ti byl dán skrze proroctví se vzkládáním rukou staršovstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'O to se starej, v tom buď, aby tvůj pokrok byl všem zřejmý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Dávej si pozor sám na sebe a na učení. V tom setrvávej. Neboť budeš–li to činit, zachráníš jak sám sebe, tak ty, kdo tě poslouchají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Na staršího muže se neosopuj, ale domlouvej mu jako otci, mladším jako bratrům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'starším ženám jako matkám, mladším ve vší čistotě jako sestrám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, '⌈Vdovy měj v úctě, mám na mysli ty⌉, které jsou skutečně vdovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Má–li však některá vdova děti nebo vnoučata, ať se ti učí prokazovat zbožnost především své rodině a odplácet rodičům, neboť to je milé před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Vdova, která je skutečně osamělá, spoléhá na Boha a oddává se vytrvale prosbám a modlitbám ⌈ve dne i v noci⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Ale ta, která se oddává rozkoším, je mrtvá, i když žije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'A toto přikazuj, aby byly bezúhonné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Jestliže se někdo nestará o své vlastní a hlavně ⌈o členy své rodiny⌉, zapřel víru a je horší než nevěřící.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Do seznamu ať je zapsána jen taková vdova, která není mladší než šedesát let, byla ženou jednoho muže,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, '⌈je známá⌉ dobrými skutky, jestliže vychovala děti, byla pohostinná, umývala nohy svatým, pomáhala ⌈lidem v tísni⌉, jestliže šla za každým dobrým skutkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mladší vdovy však odmítej. Neboť když je jejich žádosti odvrátí od Krista, chtějí se vdávat;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, '⌈zaslouží si⌉ odsouzení, protože zrušily první víru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Zároveň se také učí být lenivé, ⌈chodíce po návštěvách⌉. A nejen lenivé, nýbrž i pomlouvačné a všetečné, a mluví, co se nepatří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Chci tedy, aby se mladší vdovy vdávaly, rodily děti, vedly domácnost a nedávaly protivníku žádnou příležitost k pomluvám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Vždyť některé z nich se již odvrátily za Satanem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Má–li [některý věřící muž nebo] některá věřící žena v rodině vdovy, ať jim pomáhá; církev tak nebude zatěžována a bude moci pomáhat skutečným vdovám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Starší, kteří ⌈zastávají dobře svůj úřad⌉, jsou hodni dvojí cti, zvláště ti, kteří se namáhají ⌈kázáním a vyučováním⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Neboť Písmo praví: Volu, který mlátí, nedáš náhubek a hoden je dělník své mzdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Žalobu proti staršímu nepřijímej, leda na základě výpovědi dvou nebo tří svědků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Ty, kteří hřeší, kárej přede všemi, aby i ti ostatní měli strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Zapřísahám tě před Bohem a Kristem Ježíšem a před vyvolenými anděly, abys toto zachoval bez předpojatosti a nic nečinil tak, že bys někomu stranil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Nevzkládej na nikoho ukvapeně ruce. Neměj účast na cizích hříších. Uchovávej se čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Nepij už jen vodu, ale kvůli [svému] žaludku a kvůli svým častým nemocem užívej trochu vína.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Hříchy některých lidí jsou zcela zjevné a předem vedou k soudu, u jiných ⌈se však také ukazují až potom⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Stejně tak i dobré skutky jsou zcela zjevné; a ty, s kterými je to jinak, nemohou zůstat skryté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Všichni, kdo jsou pod jhem jako otroci, ať pokládají své pány za hodny veškeré úcty, aby Boží jméno a učení nebylo tupeno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Ti, kdo mají věřící pány, ať je nemají v menší vážnosti proto, že jsou jejich bratry, nýbrž ať slouží tím raději, že ti, ⌈kteří se ujímají dobrého díla⌉, jsou věřící a milovaní. Tomu uč a k tomu povzbuzuj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Jestliže někdo učí jinak a ⌈nedrží se⌉ zdravých slov, těch, které jsou našeho Pána Ježíše Krista, a učení, které je v souladu se zbožností,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'je zaslepený, ničemu nerozumí, ale má chorobný zájem o sporné otázky a slovní potyčky. Z toho vzniká závist, svár, urážky, zlá podezření,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'ustavičné třenice mezi lidmi, kteří mají porušenou mysl a jsou zbaveni pravdy a kteří se domnívají, že zbožnostje pramenem zisku. [Takovým se vyhni.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Opravdu velkým pramenem zisku je totiž zbožnost, ⌈která se spokojí s tím, co má⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Nic jsme si přece na svět nepřinesli a [je jasné], že si z něho také nemůžeme nic odnést.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Máme–li však jídlo a oděv, spokojíme se s tím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Ti, kdo chtějí být bohatí, upadají do pokušení a do léčky a do mnoha nerozumných a škodlivých žádostí, které ⌈je vtahují⌉ do zkázy a záhuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Neboť kořenem všeho zlého je láska k penězům; a někteří, kdo se po nich pachtili, zbloudili od víry a ⌈způsobili si⌉ mnoho bolestí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Ale ty, Boží člověče, před tím utíkej! Usiluj o spravedlnost, zbožnost, víru, lásku, trpělivost, mírnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Bojuj dobrý boj víry, chop se věčného života, k němuž jsi byl povolán a pro nějž jsi učinil dobré vyznání před mnoha svědky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Přikazuji [ti] před Bohem, který dává všemu život, a Kristem Ježíšem, který před Pontiem Pilátem dosvědčil dobré vyznání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'abys zachoval ten příkaz bez poskvrny a bez úhony až do zjevení našeho Pána Ježíše Krista,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'které svým časem ukáže blahoslavený a jediný Panovník, Král kralujících a Pán panujících.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'On jediný má nesmrtelnost a přebývá v nepřístupném světle; jeho nikdo z lidí nespatřil a nemůže spatřit. Jemu buď čest a věčná moc. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Těm, kteří jsou bohatí v nynějším věku, přikazuj, ať nesmýšlejí povýšeně a nedoufají v nejisté bohatství, nýbrž v [živého] Boha, který nám všechno štědře poskytuje k požitku;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'ať konají dobro, bohatnou v dobrých skutcích, jsou štědří, sdílní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'a tak si shromažďují pěkný základ pro budoucnost, aby se chopili skutečného života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Ó Timoteji, zachovej, co ti bylo svěřeno, vyhýbej se světským prázdným řečem a protikladným tvrzením toho, co se falešně nazývá poznání,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'k němuž se někteří přiznávali, a zbloudili ve víře. Milost s vámi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Pavel, z Boží vůle apoštol Krista Ježíše podle zaslíbení života, který je v Kristu Ježíši,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timoteovi, milovanému synu: Milost, milosrdenství, pokoj od Boha Otce a Krista Ježíše, našeho Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Děkuji Bohu, jemuž sloužím s čistým svědomím ⌈jako moji předkové⌉, když tě neustále připomínám ve svých ⌈modlitbách dnem i nocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Vzpomínám⌉ na tvé slzy a toužím tě spatřit, abych byl naplněn radostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, '⌈Připomenul jsem si⌉ tu upřímnou víru, která je v tobě; ta nejprve přebývala v tvé babičce Loidě a v tvé matce Eunice a jsem přesvědčen, že přebývá i v tobě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Z toho důvodu ti připomínám, abys rozněcoval Boží dar, který je v tobě skrze vzkládání mých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Neboť Bůh nám nedal ducha bázlivosti, nýbrž ducha moci a lásky a rozvahy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Nestyď se tedy za svědectví našeho Pána ani za mne, jeho vězně, nýbrž spolu se mnou snášej útrapy pro evangelium podle moci Boží;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'on nás zachránil a povolal svatým povoláním ne podle našich skutků, nýbrž podle vlastního předsevzetí a podle milosti, kterou nám daroval v Kristu Ježíši před věčnými časy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'a která se nyní ukázala zjevením našeho Zachránce Krista Ježíše. On zničil smrt a skrze evangelium vyvedl na světlo život a neporušitelnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'K tomu jsem já byl ustanoven hlasatelem a apoštolem a učitelem [národů].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Proto také toto snáším, ale nestydím se za to; vím, komu jsem uvěřil, a jsem přesvědčen, že on je mocen ochránit to, co jsem mu svěřil, až do onoho dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Měj za příklad zdravých slov to, co jsi slyšel ode mne ve víře a lásce, která je v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Ten krásný svěřený poklad zachovej skrze Ducha Svatého, který v nás přebývá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Víš o tom, že se ode mne odvrátili všichni, kdo jsou v Asii, ⌈mezi nimi⌉ Fygelos a Hermogenés.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Kéž Pán prokáže milosrdenství domu Oneziforovu, protože mě často občerstvil a nestyděl se za mé řetězy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'nýbrž když přišel do Říma, usilovně mě hledal, a ž mě nalezl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Kéž mu Pán dá, aby našel milosrdenství od Pána v onen den. A jak veliké služby mi prokázal v Efesu, ⌈víš nejlépe sám⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Ty tedy, můj synu, posiluj se v milosti, která je v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Co jsi ode mne slyšel před mnohými svědky, to svěř věrným lidem, kteří budou schopni vyučit také jiné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Snášej spolu se mnou útrapy jako dobrý voják Krista Ježíše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Žádný voják ve službě se nezaplétá do záležitostí každodenního života, aby se zalíbil tomu, kdo ho na vojnu najal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'A stejně i ten, kdo závodí, nebývá ověnčen, nezávodí–li podle pravidel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Rolník, který se namáhá, má jako první dostat podíl z úrody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Uvažuj o tom, co říkám. Pán ti dá ve všem porozumění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Pamatuj na Ježíše Krista vzkříšeného z mrtvých, ze semene Davidova, podle mého evangelia.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Pro ně snáším útrapy ⌈a dokonce pouta⌉ jako zločinec. Ale slovo Boží není spoutáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Proto všechno snáším pro vyvolené, aby i oni dosáhli záchrany v Kristu Ježíši spolu s věčnou slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, '⌈Věrohodné je to slovo:⌉ Jestliže jsme s ním zemřeli, budeme s ním také žít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Jestliže vytrváváme, budeme s ním i kralovat. Zapřeme–li ho, i on nás zapře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Jsme–li nevěrní, on zůstává věrný, neboť nemůže zapřít sám sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Toto připomínej a před tváří Boží zapřísahej bratry, aby se nepřeli o slova. K ničemu to ne ní, jen ke zkáze posluchačů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Horlivě usiluj, aby ses před Boha postavil jako člověk osvědčený, pracovník, který se nemusí stydět a který správně rozděluje slovo pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Vyhýbej se prázdným světským řečem, neboť ti, kdo tak mluví, budou stále víc postupovat k bezbožnosti');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'a jejich nauka se bude šířit jako sněť. ⌈Patří k nim⌉ i Hymenaios a Filétos,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'kteří zbloudili od pravdy, když říkají, že vzkříšení již nastalo, a tím u některých podvracejí víru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Avšak pevný základ Boží stojí, maje tuto pečeť: Pán zná ty, kdo jsou jeho, a ať se odvrátí od nepravosti každý, kdo vyslovuje Pánovo jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Ve velkém domě nejsou jen nádoby zlaté a stříbrné, nýbrž i dřevěné a hliněné, jedny ke cti, druhé k méně čestným účelům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Kdo by se tedy od těchto věcí očistil, bude nádobou ke cti, posvěcenou, Pánu užitečnou, připravenou ke každému dobrému skutku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Utíkej před mladickými žádostmi, usiluj o spravedlnost, víru, lásku, pokoj s těmi, kdo vzývají Pána z čistého srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Hloupé a pošetilé otázky odmítej; víš, že plodí hádky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Pánův otrok se nemá hádat, nýbrž má být přívětivý ke všem, schopný učit, má být trpělivý');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'a v tichosti kárat odpůrce. Snad jim dá Bůh pokání k poznání pravdy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'a proberou se z Ďáblovy léčky, do které byli od něj chyceni, aby činili jeho vůli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Toto však věz, že v posledních dnech nastanou těžké časy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Lidé budou sobečtí, chtiví peněz, chlubiví, domýšliví, rouhaví, rodičů neposlušní, nevděční, nesvatí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'bezcitní, nesmířliví, pomlouvační, nevázaní, hrubí, nepřátelští k dobrému,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'zrádní, lehkomyslní, nadutí, milující rozkoš spíše než milující Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Budou mít vnější formu zbožnosti, ale její moc ⌈jim bude cizí⌉. Od takových se odvracej.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, '⌈K nim patří⌉ ti, kteří vnikají do domů a podmaňují si lehkověrné ženy, které jsou obtížené hříchy a hnané rozličnými žádostmi,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'které se stále učí, a nikdy nemohou přijít k poznání pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Jako se ⌈Jannés a Jambrés⌉ postavili proti Mojžíšovi, tak se i tito lidé stavějí proti pravdě. Jsou to lidé se zvrácenou myslí, neosvědčení ve víře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Ale dále nepostoupí, neboť jejich nerozum bude všem zřejmý, jako byl i nerozum oněch dvou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Ty však jsi sledoval mé učení, můj způsob života, můj úmysl, mou víru, trpělivost, lásku, vytrvalost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'pronásledování a utrpení, jaká ⌈mne stihla⌉ v Antiochii, v Ikoniu a v Lystře. Jaká pronásledování jsem přestál, a ze všech mě Pán vysvobodil!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Všichni, kdo chtějí zbožně žít v Kristu Ježíši, budou pronásledováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Ale zlí lidé a podvodníci budou postupovat stále k horšímu; budou svádět jiné a sami budou sváděni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Ty však zůstávej v tom, čemu ses naučil a o čem jsi byl plně přesvědčen, věda, od koho ses to naučil;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'od dětství přece znáš svatá Písma, jež ti mohou dát moudrost k záchraně skrze víru, která je v Kristu Ježíši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Veškeré Písmo je ⌈vdechnuté Bohem⌉ a je užitečné k učení, k usvědčování, k napravování, k výchově ve spravedlnosti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'aby Boží člověk byl ⌈takový, jaký má být⌉, důkladně vystrojený ke každému dobrému skutku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Zapřísahám tě před Bohem a Kristem Ježíšem, který bude soudit živé i mrtvé, a při jeho zjevení a jeho kralování:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Hlásej slovo, přicházej s ním vhod či nevhod, usvědčuj, domlouvej, napomínej se vší trpělivostí a s vyučováním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Neboť přijde doba, kdy lidé nesnesou zdravé učení, nýbrž si podle vlastních žádostí budou shromažďovat učitele, ⌈aby jim říkali, co je jim příjemné⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'odvrátí sluch od pravdy a obrátí se k bájím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Ty však buď ve všem střízlivý, ⌈snášej útrapy, konej⌉ dílo evangelisty, naplň svou službu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Neboť já jsem už vydáván v oběť a přišel čas mého odchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Dobrý boj jsem bojoval, běh jsem dokončil, víru jsem zachoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Nakonec je pro mne připraven věnec spravedlnosti, který mi v onen den předá Pán, spravedlivý soudce. A nejen mně, nýbrž i všem, kteří milují jeho zjevení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Pospěš si, abys ke mně brzo přišel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Démas mě totiž opustil, protože více miloval ⌈tento svět⌉, a odešel do Tesaloniky, Krescens do Galacie, Titus do Dalmácie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Jediný Lukáš je se mnou. Marka vezmi a přiveď s sebou, neboť je mi užitečný k službě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychika jsem poslal do Efesu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, '⌈Až půjdeš⌉, vezmi s sebou plášť, který jsem nechal v Troadě u Karpa, též svitky a zvláště pergameny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Kovář Alexandr mi způsobil mnoho zlého. Pán mu odplatí podle jeho skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Také ty si dávej před ním pozor. Velmi se totiž postavil proti našim slovům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Při mé první obhajobě nikdo při mně nebyl, nýbrž všichni mě opustili. Kéž jim to není počítáno!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Pán však stál při mně a posilnil mě, aby skrze mne byla dovršena zvěst a aby ji uslyšeli všichni pohané; a byl jsem vysvobozen ze lví tlamy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Pán mě vysvobodí od každého nepřátelského činu a zachová pro své nebeské království. Jemu buď sláva na věky věků! Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Pozdrav Prisku a Akvilu i dům Oneziforův.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastos zůstal v Korintu, Trofima jsem nechal nemocného v Milétu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Pospěš si, abys přišel ještě před zimou. Pozdravuje tě Eubulos, Pudens, Linus, Klaudia a všichni bratři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Pán [Ježíš Kristus] buď s tvým duchem. Milost s vámi! [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Pavel, otrok Boží a apoštol Ježíše Krista pro víru Božích vyvolených a pro poznání pravdy, která je podle zbožnosti');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'na základě naděje věčného života, jejž před ⌈věčnými časy⌉ zaslíbil Bůh, který nemůže lhát');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'a který ve svůj čas zjevil své slovove zvěsti, která mi byla svěřena podle příkazu našeho Zachránce Boha --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Titovi, ⌈vlastnímu synu⌉ podle společné víry: ⌈Milost, [milosrdenství] a pokoj od Boha Otce⌉ a Krista Ježíše, našeho Zachránce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Proto jsem tě zanechal na Krétě, abys dal do pořádku to, co ještě zbývá, a ustanovil v jednotlivých městech starší, jak jsem ti přikázal:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'je–li kdo bez úhony, muž jedné ženy, ⌈jenž má⌉ věřící děti, ⌈ jemuž se nedá vytknout prostopášnost⌉ nebo nepoddajnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Neboť biskup musí být bez úhony jako Boží správce; ne samolibý, ne popudlivý, ne pijan, ne rváč, ne zištný,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'ale pohostinný, milující dobro, rozvážný, spravedlivý, zbožný, ukázněný,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'musí se pevně držet spolehlivého slova, ⌈jak bylo vyučováno⌉, aby byl schopen jak povzbuzovat ve zdravém učení, tak usvědčovat odpůrce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Neboť je mnoho nepoddajných, prázdných mluvků a svůdců, obzvláště těch ze Židů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Těm je třeba zacpávat ústa, neboť rozvracejí celé rodiny, když pro hanebný zisk učí, co by neměli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Jeden z nich, jejich vlastní prorok, řekl: Kréťané byli vždycky lháři, zlá zvěř, líná břicha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Toto svědectví je pravdivé. Z toho důvodu je přísně kárej, aby byli zdraví ve víře');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'a nedbali na židovské báje a příkazy lidí, kteří se odvracejí od pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Čistým je vše čisté. Avšak poskvrněným a nevěřícím nic ne ní čisté, ale je poskvrněná jak jejich mysl, tak svědomí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Vyznávají, že znají Boha, ale svými skutky ho zapírají. Jsou ohavní a neposlušní a nezpůsobilí k jakémukoli dobrému skutku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Ty však mluv, co náleží k zdravému učení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Starší muži mají být střídmí, čestní, rozvážní, zdraví ve víře, lásce a vytrvalosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Podobně starší ženy ⌈ať se chovají uctivě⌉, ne jsou pomlouvačné ani nejsou zotročeny přílišným pitím vína, ale ať vyučují mladé ženy v dobrém');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'a vedou je k tomu, aby měly rády své muže a děti,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'byly rozvážné, cudné, pracovité v domácnosti, dobré, poddané svým mužům, aby slovo Boží nebylo haněno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Taktéž mladší muže napomínej, aby byli rozvážní,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'a sám buď ve všem příkladem ⌈správného jednání⌉: Ukazuj v učení neporušenost, poctivost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'mluv zdravé slovo, jemuž nelze nic vytknout, aby každý odpůrce byl zahanben a neměl nic, co by o nás řekl zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Otroci ať se ve všem podřizují svým pánům, ať jsou úslužní, neodmlouvají,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'ať své pány neokrádají, ale ať ukazují ⌈veškerou dobrou víru⌉, aby ve všem byli ozdobou učení našeho Zachránce Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, '⌈Zjevila se totiž Boží milost, která přináší záchranu všem lidem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'a vychovává nás⌉, abychom se odřekli bezbožnosti a světských žádostí a rozvážně, spravedlivě a zbožně žili v tomto věku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'očekávajíce tu blahoslavenou naději, zjevení slávy velikého Boha a našeho Zachránce Ježíše Krista,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'který dal sám sebe za nás, aby nás vykoupil z veškeré nepravosti a očistil si ⌈svůj zvláštní⌉ lid, horlivý v dobrých skutcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Mluv tyto věci, povzbuzuj a kárej se vší přísností. Nikdo ať tebou nepohrdá!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Připomínej jim, ať se podřizují vládcům [a] vrchnostem, ať je poslouchají a jsou připraveni ke každému dobrému skutku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Ať nikoho neurážejí, ať nejsou svárliví, nýbrž mírní, a ať ukazují veškerou tichost ke všem lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Neboť i my jsme kdysi byli nerozumní, neposlušní, bloudící,byli jsme otroky žádostí a všelijakých rozkoší, trávili jsme život v špatnosti a závisti, byli jsme odporní a navzájem jsme se nenáviděli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Když se však zjevila dobrota a lidumilnost Boha, našeho Zachránce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'zachránil nás ne ⌈na základě⌉ skutků, které jsme my učinili ve spravedlnosti, nýbrž podle svého milosrdenství skrze koupel znovuzrození a obnovou Ducha Svatého,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'kterého na nás vylil hojně skrze Ježíše Krista, našeho Zachránce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'abychom se ospravedlněni jeho milostí stali dědici v naději života věčného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Věrohodné je to slovo, a chci, abys na ty věci kladl důraz, ⌈ totiž aby se⌉ ti, kdo uvěřili Bohu, soustředili na to, jak mají vynikat v dobrých skutcích; je to krásné a lidem užitečné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Hloupým sporům, rodokmenům, svárům a hádkám o Zákon se vyhýbej! Jsou neužitečné a nikam nevedou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Sektáře po jednom a druhém napomenutí odmítni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Víš, že takový člověk je převrácený, hřeší, a sám sebe odsuzuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Jakmile k tobě pošlu Artema nebo Tychika, pospěš si a přijď ke mně do Nikopole, neboť jsem se rozhodl strávit tam zimu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Právníka Zénu a Apolla pečlivě vyprav na cestu, aby jim nic nechybělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Ať se i naši lidé učí vynikat v dobrých skutcích pro naléhavé potřeby, aby nebyli neužiteční.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Pozdravují tě všichni, kteří jsou se mnou. Pozdrav ty, kteří nás ve víře milují. Milost se všemi vámi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pavel, vězeň Krista Ježíše, a bratr Timoteus milovanému Filemonovi, našemu spolupracovníku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'sestře Apfii, našemu spolubojovníku Archippovi a církvi ve tvém domě:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Děkuji svému Bohu vždycky, když se o tobě zmiňuji ve svých modlitbách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'neboť slyším o tvé lásce a víře, kterou máš vůči Pánu Ježíši a ke všem svatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Prosím, aby se společenství tvé víry projevilo v poznání všeho dobrého, jež je v nás pro Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Neboť jsem měl mnoho radosti a povzbuzení ze tvé lásky, protože skrze tebe, bratře, byla občerstvena srdce svatých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Ačkoli mám v Kristu plnou svobodu ti přikazovat, co se patří,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'pro lásku raději prosím já, Pavel, stařec a nyní i vězeň Krista Ježíše:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Prosím tě za svého syna, kterého jsem zplodil ve vězení, za Onezima,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'který ti byl kdysi neužitečný, avšak nyní je tobě i mně prospěšný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Toho ⌈ti posílám nazpět, jeho⌉, to jest moje srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Chtěl jsem si ho ponechat u sebe, aby mi místo tebe sloužil v mém vězení pro evangelium,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'ale bez tvého souhlasu jsem nechtěl nic udělat, aby ⌈tvůj dobrý skutek⌉ nebyl jakoby z vynucení, ale z ochoty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Snad právě proto byl pryč na chvíli, abys jej navždy přijal nazpět --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'ne již jako otroka, nýbrž více než otroka, jako milovaného bratra. Je obzvláště drahý mně, ale tím víc tobě: i ⌈jako člověk⌉, i jako bratr v Pánu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Máš–li mě tedy za společníka, přijmi ho jako mne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Jestliže ti nějak uškodil nebo je ti něco dlužen, přičti to na můj účet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Já Pavel jsem to napsal vlastní rukou: já to nahradím. Abych ti nakonec ne musel říci, že mi dlužíš i sám sebe!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Ano, bratře, ať mám z tebe radost v Pánu. Občerstvi mé srdce v Kristu!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Píšu ti přesvědčen o tvé poslušnosti, neboť vím, že uděláš více, než říkám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Zároveň mi také připrav hostinskou místnost, neboť mám naději, že vám skrze vaše modlitby budu darován.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Pozdravuje tě Epafras, můj spoluvězeň v Kristu Ježíši,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'a moji spolupracovníci Marek, Aristarchos, Démas a Lukáš.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Milost Pána [našeho] Ježíše Krista s vaším duchem. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Mnohokrát a mnoha způsoby mluvil kdysi Bůh k otcům v prorocích;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'na konci těchto dnů k nám promluvil v Synu, jehož ustanovil dědicem všeho a skrze něhož učinil i věky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'On je září jeho slávy a otiskem jeho podstaty, všechno nese ⌈svým mocným slovem⌉. Když [skrze sebe] vykonal očištění od [našich] hříchů, posadil se po pravici Majestátu na výsostech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Stal se tím vznešenější nad anděly, čím význačnější jméno dědičně obdržel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Neboť kterému z andělů kdy řekl: Ty jsi můj syn, já jsem tě dnes zplodil? A opět: Já mu budu otcem a on mi bude synem?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'A ⌈opět, když uvádí⌉ Prvorozeného do světa, praví: Ať se mu pokloní všichni andělé Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'O andělech sice říká: On činí své anděly ⌈ závany větru⌉ a své služebníky plamenem ohně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'avšak o Synovi: Tvůj trůn, Bože, je na věky věků a žezlo přímosti je žezlem tvého království.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Miloval jsi spravedlnost a nenáviděl nepravost; proto pomazal tě, Bože, Bůh tvůj olejem veselí nad tvé společníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'A: Ty, Pane, jsi na počátku založil zemi a nebesa jsou dílem tvých rukou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ona pominou, ty však zůstáváš; všechna jako roucho zestárnou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'a jako plášť je svineš, [jako roucho] budou i proměněna. Ty však jsi stále tentýž a tvá léta nepominou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'A kterému z andělů kdy řekl: Seď po mé pravici, dokud nepoložím tvé nepřátele za podnož tvých nohou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Což nejsou oni všichni služební duchové, posílaní k službě kvůli těm, kdo mají dostat do dědictví záchranu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Proto musíme věnovat mnohem větší pozornost tomu, co jsme slyšeli, abychom nebyli strženi proudem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Neboť jestliže slovo, které bylo řečeno skrze anděly, bylo pevné a každé přestoupení a každá neposlušnost došly spravedlivé odplaty,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'jak unikneme my, zanedbáme–li tak velikou záchranu, která ⌈má svůj původ⌉ v tom, co říkal Pán, a byla nám potvrzena těmi, kteří to slyšeli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'za Božího spoludosvědčování znameními a divy, rozmanitými ⌈projevy moci⌉ a udělováním Ducha Svatého podle jeho vůle?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Bůh nepodřídil andělům budoucí svět, o kterém mluvíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Kdosi někde slavnostně dosvědčil: Co je člověk, že na něj pamatuješ, nebo syn člověka, že ⌈jej navštěvuješ⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Nakrátko jsi ho postavil níže než anděly, slávou a ctí jsi ho ověnčil [a ustanovil jsi ho nad dílem svých rukou].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Všechno jsi poddal pod jeho nohy. Tím tedy, že [mu] poddal všechno, neponechal nic, co by mu ne bylo poddáno. Nyní však ještě nevidíme, že je mu všechno poddáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Avšak toho, který byl nakrátko postaven níže než andělé, Ježíše, vidíme ⌈pro utrpení smrti⌉ ověnčeného slávou a ctí; tak ⌈z milosti Boží⌉ za každého okusil smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Slušelo se totiž na toho, pro něhož je všechno a skrze něhož je všechno, když mnoho synů přivedl do slávy, aby skrze utrpení ⌈učinil dokonalým⌉ původce jejich záchrany.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Neboť ten, který posvěcuje, i ti, kdo jsou posvěcováni, jsou všichni z jednoho. Z toho důvodu se nestydí nazývat je bratry,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'když říká: Budu zvěstovat tvé jméno svým bratřím, uprostřed shromáždění tě budu opěvovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'A opět: Já mu budu důvěřovat; a opět: Hle, já a děti, které mi dal Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Protože děti mají účast na krvi a těle, podobně i on se jich stal účastným, aby skrze smrt zahladil toho, kdo má vládu nad smrtí, totiž Ďábla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'a osvobodil ty, kteří byli strachem ze smrti drženi po celý život v otroctví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Je přece jasné, že se neujímá andělů, ale ujímá se semene Abrahamova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'A tedy musel být ve všem učiněn podobný bratřím, aby se stal milosrdným a věrným veleknězem v Božích věcech, k usmíření hříchů lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Protože sám vytrpěl pokušení, může pomoci těm, kteří jsou pokoušeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Proto, svatí bratři, účastníci nebeského povolání, pohleďte na apoštola a velekněze našeho vyznání, Ježíše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'který je věrný tomu, kdo ho ustanovil, jako i Mojžíš byl věrný v [celém] jeho domě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Ježíš je však hoden větší slávy než Mojžíš, tak jako stavitel domu má větší čest nežli dům sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Neboť každý dům někdo staví; a ten, kdo postavil všechno, je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'A Mojžíš byl věrný v celém jeho domě jako služebník, aby dosvědčil to, co mělo být pověděno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Ale Kristus jako Syn je nad jeho domem. Jeho domem jsme my, zachováme–li si [až do konce pevnou] důvěru a chloubu naděje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Proto, jak praví Duch Svatý: Jestliže dnes uslyšíte jeho hlas,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'nezatvrzujte svá srdce jako při onom rozhořčení ve dni pokušení v pustině,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'kdy [mě] pokoušeli vaši otcové ⌈ tím, že mě zkoušeli⌉, a viděli mé skutky');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'po čtyřicet let. Proto jsem se na toto pokolení rozhněval a řekl jsem: Stále bloudí srdcem; oni nepoznali mé cesty.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Jak jsem přísahal ve svém hněvu: Jistě nevejdou do mého odpočinutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Hleďte, bratři, aby snad v někom z vás nebylo zlé a nevěrné srdce, takže by odpadl od živého Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'a proto se navzájem napomínejte každý den, dokud se říká Dnes, aby nikdo z vás nebyl zatvrzen klamem hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Vždyť jsme se stali účastníky Krista, pokud ⌈ten původ jistoty⌉ zachováme pevný až do konce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Když se říká: Jestliže dnes uslyšíte jeho hlas, nezatvrzujte svá srdce jako při onom rozhořčení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'kdo jsou ti, kteří slyšeli a způsobili rozhořčení? Což to ne byli všichni ti, kdo vyšli z Egypta skrze Mojžíše?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Na koho se hněval čtyřicet let? Zdali ne na ty, kteří zhřešili a jejichž mrtvoly padly v pustině?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'A komu přísahal, že nevejdou do jeho odpočinutí, ne–li těm, kteří neposlechli?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'I vidíme, že nemohli vejít pro nevěru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, '⌈Stále platí⌉ zaslíbení pro vstup do jeho odpočinutí, bojme se tedy, ⌈aby se snad neukázalo, že někdo z vás⌉ je promeškal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Vždyť také nám byla oznámena radostná zvěst, stejně jako i jim. Slovo zvěsti jim však neprospělo, protože ⌈nebyli spojeni vírou s těmi⌉, kteří slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Neboť do odpočinutí vcházíme my, kteří jsme uvěřili, jak řekl: Jak jsem přísahal ve svém hněvu: Nevejdou do mého odpočinutí, ačkoliv to dílo bylo od založení světa hotovo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Neboť kdesi řekl o sedmém dni takto: I odpočinul Bůh sedmého dne od ⌈všeho svého díla⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'A zde zase: Nevejdou do mého odpočinutí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Protože tedy zůstává možnost, aby někteří do něho vešli, a protože ti, kterým to bylo dříve zvěstováno, nevešli pro neposlušnost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'opět určuje jeden den, Dnes, když v Davidovi po tak dlouhém čase říká, jak je předpověděno: Jestliže dnes uslyšíte jeho hlas, nezatvrzujte svá srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Kdyby je totiž Jozue uvedl do odpočinutí, nemluvil by o jiném, pozdějším dni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'A tak zůstává sobotní odpočinutí Božímu lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Kdo totiž vešel do jeho odpočinutí, ten také odpočinul od svého díla, tak jako Bůh od svého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Pospěšme si tedy vejít do onoho odpočinutí, aby nikdo nepadl podle stejného příkladu neposlušnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Neboť Boží slovo je živé, činné a ostřejší než jakýkoli dvousečný meč; proniká až do rozdělení duše a ducha, kloubů a morku a je schopné rozsoudit myšlenky a postoje srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'A žádné stvoření není před ním skryté; před očima toho, jemuž ⌈se budeme zodpovídat⌉, je vše nahé a odkryté.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Když tedy máme velikého velekněze, který prošel nebesy, Ježíše, Syna Božího, držme pevně to vyznání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Neboť nemáme takového velekněze, který by s námi nemohl soucítit v našich slabostech, nýbrž takového, který ve všem prošel zkouškami podobně jako my, avšak bez hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Přistupujme tedy s důvěrou k trůnu milosti, abychom přijali milosrdenství a nalezli milost ku pomoci v pravý čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Každý velekněz, který je brán z lidí, bývá ustanoven pro lidi ⌈v Božích věcech⌉, aby přinášel dary a oběti za hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Dovede být mírný vůči nevědomým a bloudícím, protože i sám je obklopován slabostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'A kvůli ní musí přinášet oběti za hříchy nejen za lid, ale i za sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Tuto čest si nikdo nemůže přisvojit sám, nýbrž je povoláván Bohem, jako i Áron.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Tak ani Kristus neoslavil sám sebe, když se stal veleknězem, neboť ho jím učinil ten, který mu řekl: Ty jsi můj syn, já jsem tě dnes zplodil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Jak říká i na jiném místě: Ty jsi kněz navěky podle řádu Melchisedechova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'On ve dnech svého ⌈pozemského života⌉ s hlasitým křikem a slzami obětoval modlitby a úpěnlivé prosby tomu, který byl mocen ho zachránit ze smrti, a byl vyslyšen pro svou boha bojnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Ačkoli to byl Syn, naučil se poslušnosti tím, co vytrpěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'I dosáhl dokonalosti a stal se všem, kdo ho poslouchají, původcem věčné záchrany,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'když ho Bůh prohlásil za velekněze podle řádu Melchisedechova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'O něm ⌈máme mnoho co říci⌉ a je to obtížné slovy vysvětlit, protože jste se stali ⌈línými ke slyšení⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Neboť ačkoliv jste tou dobou měli být učiteli, opět potřebujete, aby vás někdo učil počáteční základy Božích výroků. Stali jste se těmi, kteří potřebují mléko, a ne hutný pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Neboť každý, kdo ⌈potřebuje mléko⌉, je nezkušený ve slově spravedlnosti, protože je ještě nemluvně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Pro dokonalé je však tuhý pokrm, pro ty, ⌈kteří mají smysly návykem vycvičeny⌉ k rozsuzování dobrého a zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Proto opusťme ⌈počáteční učení o Kristu⌉ a nesme se k zralosti; neklaďme znovu základ y z pokání z mrtvých skutků a z víry v Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'z učení o křtech, o vzkládání rukou, o vzkříšení mrtvých a o věčném soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'A to učiníme, jestliže to Bůh dovolí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Neboť ty, kteří byli jednou osvíceni, okusili nebeského daru a stali se účastníky Ducha Svatého,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'okusili dobrého Božího slova i moci budoucího věku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'a odpadli, je nemožné znovu obnovovat ku pokání, neboť si opět křižují Syna Božího a vystavují ho veřejnému posměchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Vždyť zem, která pije déšť, jenž na ni často přichází, a plodí užitečnou bylinu těm, pro něž je také obdělávána, dostává od Boha požehnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Když však nese trní a bodláky, je neužitečná a blízká prokletí; jejím koncem je spálení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Co se však týká vás, milovaní, jsme přesvědčeni o lepších věcech, o tom, co náleží k záchraně, přestože tak mluvíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Neboť Bůh ne ní nespravedlivý, takže by zapomněl na vaši práci a lásku, kterou jste projevili jeho jménu, když jste posloužili-- a ještě sloužíte -- svatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Toužíme však, aby každý z vás projevoval stejnou horlivost k nabytí plné jistoty naděje, ⌈ která vytrvá až do konce⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'abyste nezlenivěli, ale napodobili ty, kteří jsou skrze víru a trpělivost dědici zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Když Bůh dal zaslíbení Abrahamovi a neměl nikoho vyššího, při kom by učinil přísahu, přísahal při sobě samém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Řekl: Jistě tě ⌈zahrnu požehnáním⌉ a ⌈velmi tě rozmnožím⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'A tak trpělivě vyčkal a dosáhl toho zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Neboť lidé přísahají při větším, než jsou sami; a přísaha je zárukou, která ukončuje každý jejich spor.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Když tedy Bůh chtěl ještě hojněji ukázat dědicům zaslíbení nepohnutelnost svého úmyslu, zaručil jej přísahou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'abychom skrze dvě nepohnutelné skutečnosti, v nichž ne ní možné, aby Bůh lhal, měli mocné povzbuzení my, kteří jsme se utekli k pevnému uchopení předkládané naděje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Máme ji jako kotvu duše, bezpečnou a pevnou, která vchází až do vnitřku za oponu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'kam kvůli nám vešel náš předchůdce Ježíš, který se ⌈na věčnost⌉ stal veleknězem podle řádu Melchisedechova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Tento Melchisedech, král Sálemu, kněz Boha Nejvyššího, který se setkal s Abrahamem, když se navracel od porážky králů, a požehnal mu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'a kterému také Abraham oddělil ze všeho desátek, je nejprve podle překladu král spravedlnosti, dále pak i král Sálemu, což znamená král pokoje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Je bez otce, bez matky, bez rodokmenu, nemá ani počátek dnů ani konec života; a tím je připodobněn Synu Božímu a zůstává knězem navždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Hleďte, jak veliký je ten, jemuž [i] patriarcha Abraham dal desátek z kořisti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'A vskutku ti ze synů Léviho, kteří přijímají kněžský úřad, mají příkaz brát podle Zákona desátek od lidu, to jest od svých bratrů, ačkoliv i oni vyšli z beder Abrahamových.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Avšak ten, který nepochází z jejich rodokmenu, obdržel desátek od Abrahama a požehnal tomu, který měl zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Není sporu, že nižší ⌈přijímá požehnání⌉ od vyššího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'A zde přijímají desátek smrtelní lidé, tam však někdo, o němž se svědčí, že žije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Lze také říci, že skrze Abrahama dal desátek i Lévi, který přijímá desátky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Vždyť byl ještě v bedrech otcových, když mu Melchisedech vyšel vstříc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Kdyby tedy byla dokonalost skrze levitské kněžství -- neboť na jeho základě lid dostal Zákon -- proč by ještě bylo potřeba, aby povstával jiný kněz podle řádu Melchisedechova a nebyl jmenován podle řádu Áronova?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Neboť mění–li se kněžství, nutně nastává i změna zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'A ten, o němž se toto říká, patří k jinému kmeni, z něhož nikdo nesloužil u oltáře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Je přece dobře známo, že náš Pán pochází z Judy, a vzhledem k tomuto kmeni Mojžíš nic neřekl o kněžích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'A je to ještě mnohem zřejmější, povstává–li podle podobnosti Melchisedechovy jiný kněz,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'který není podle zákona ⌈tělesného nařízení⌉, nýbrž podle moci neporušitelného života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Neboť [se o něm] svědčí: Ty jsi kněz ⌈na věčnost⌉ podle řádu Melchisedechova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, '⌈ Tím se sice ruší předchozí nařízení pro jeho slabost a neužitečnost --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'vždyť Zákon nic nepřivedl k dokonalosti -- uvádí se⌉ však lepší naděje, skrze niž se přibližujeme k Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'A tím více, že se to ne stalo bez přísahy -- neboť oni vskutku jsou kněžími bez přísahy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'kdežto on s přísahou od toho, který mu řekl: Přísahal Pán a nebude toho litovat: Ty jsi kněz na věčnost [podle řádu Melchisedechova]. --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'tím spíše se stal Ježíš [také] ručitelem lepší smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'A jich se mnoho stalo kněžími, protože smrt bránila, aby jimi zůstávali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Protože však on sám zůstává na věčnost, má nezměnitelné kněžství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Proto také může dokonale zachránit ty, kteří skrze něho přistupují k Bohu, neboť je stále živ, aby se za ně přimlouval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Takový velekněz byl pro nás vhodný: svatý, bezelstný, neposkvrněný, oddělený od hříšníků, ten, který se stal vyšším nad nebesa');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'a který nemusí jako tam ti velekněží denně přinášet oběti napřed za vlastní hříchy a potom za hříchy lidu, neboť to učinil jednou provždy, když obětoval sebe sama.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Neboť Zákon ustanovuje za velekněze lidi mající slabost i, ale slovo ⌈přísežného ujištění⌉, které bylo dáno po Zákonu, ustanovuje Syna, který se stal dokonalým veleknězem na věčnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, '⌈ To podstatné na tom⌉, co je řečeno, je toto: Máme takového velekněze, který usedl po pravici trůnu Majestátu v nebesích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'je služebníkem svatyně a toho pravého stánku, který postavil Pán, a ne člověk.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Každý velekněz bývá ustanovován k obětování darů a obětí; proto je nutné, aby i on měl něco, co by obětoval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Kdyby tedy byl ještě na zemi, ani by nebyl knězem, protože zde jsou ti, kteří přinášejí dary podle Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Ti slouží náznaku a předobrazu nebeských věcí, jak ⌈bylo zjeveno Mojžíšovi⌉, když měl stavět stánek; neboť říká: Hleď, ať uděláš všechno podle vzoru, který ti byl ukázán na té to hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, '⌈Nyní však⌉ dosáhl význačnější služby, tak jako je i prostředníkem lepší smlouvy, která je založena na lepších zaslíbeních.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Neboť kdyby ona první smlouva byla bez vady, nehledalo by se místo pro druhou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Neboť kárá ⌈svůj lid⌉ a říká: „Hle, přicházejí dny, praví Pán, ⌈kdy uzavřu s domem⌉ Izraele a s domem Judy smlouvu novou;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'ne podle smlouvy, kterou jsem uzavřel s jejich otci v den, kdy jsem je uchopil za ruku, abych je vyvedl z egyptské země; nezůstali totiž v mé smlouvě, a já jsem je zanechal, praví Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Protože toto je smlouva, kterou uzavřu s domem Izraele po oněch dnech, praví Pán: Dám jim své zákony do mysli a napíši jim je na srdce; a budu jim Bohem a oni mi budou lidem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'A nikdo už nebude učit svého spolu občana a nikdo svého bratra slovy: Poznej Pána, neboť mě budou znát všichni, od nejmenšího až do největšího z nich,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'protože se slituji nad jejich nepravostmi a na jejich hříchy [a jejich nezákonnosti] již nikdy nevzpomenu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Když mluví o nové smlouvě, prohlašuje tu první za zastaralou. Co však zastarává či stárne, je blízko zániku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, '[Také] první smlouva měla ustanovení služby Bohu a pozemskou svatyni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Neboť byl zřízen první stánek, ve kterém byl svícen, stůl a předložení chlebů; tomu se říká svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Za druhou oponou byl stánek, kterému se říká nejsvětější svatyně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, '⌈V něm byl⌉ zlatý kadidlový oltář a schrána smlouvy, ze všech stran obložená zlatem, v níž byl zlatý džbán obsahující manu, Áronova hůl, která rozkvetla, a desky smlouvy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Nad ní byli cherubové Slávy, zastiňující slitovnici. O těchto věcech teď není třeba jednotlivě mluvit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Když jsou tedy tyto věci takto připraveny, do prvního stánku vcházejí kněží stále a konají bohoslužebné úkony;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'avšak do druhého jen jednou za rok vchází sám velekněz, a to ne bez krve, kterou obětuje za sebe i za ⌈nevědomosti lidu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Tím Duch Svatý ukazuje, že ještě není zjevná cesta do svatyně, dokud stojí první stánek,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'který je obrazem přítomného času. Podle něho se přinášejí dary a oběti, které nemohou v jeho svědomí přivést k dokonalosti toho, kdo Bohu slouží;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'týkají se pouze pokrmů, nápojů a různých omývání, což jsou jen tělesná ustanovení, uložená do času nápravy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Ale když přišel Kristus jako velekněz ⌈budoucího dobra⌉ skrze větší a dokonalejší stánek, ne rukama udělaný, to jest ne z tohoto stvoření,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'vešel ne skrze krev kozlů a telat, ale skrze svou vlastní krev jednou provždy do svatyně, když získal věčné vykoupení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Jestliže totiž krev kozlů a býků a popel z jalovice kropením posvěcuje znečištěné k čistotě těla,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'čím více krev Krista, který skrze věčného Ducha sebe samého obětoval neposkvrněného Bohu, očistí naše svědomí od mrtvých skutků k službě živému Bohu?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Proto je prostředníkem nové smlouvy, aby po jeho smrti, která nastala pro vykoupení z přestoupení spáchaných za první smlouvy, přijali zaslíbení věčného dědictví ti, kdo jsou povoláni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Neboť kde je závěť, je nutné, aby byla prokázána smrt toho, kdo ji ustanovil,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'neboť závěť je platná jen po mrtvých, protože nikdy nemá platnost, dokud žije ten, kdo ji ustanovil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Proto ani první smlouva nebyla uzavřena bez krve.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Neboť když Mojžíš pověděl všemu lidu každé nařízení podle Zákona, vzal krev telat [a kozlů] s vodou a se šarlatovou vlnou a s yzopem, pokropil samu knihu Zákona i všechen lid');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'se slovy: Toto je krev smlouvy, kterou vám přikázal Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Také stánek a všechno nářadí pro službu Bohu pokropil krví stejným způsobem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'A téměř všechno se podle Zákona očišťuje krví a bez vylití krve není odpuštění.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Bylo tedy nutné, aby obrazy těch věcí, které jsou v nebesích, byly takto očišťovány, avšak samy nebeské věci jsou očišťovány oběťmi lepšími, než jsou tyto.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Neboť Kristus nevešel do ⌈svatyně udělané lidskýma rukama, která je předobrazem té pravé⌉, nýbrž do samého nebe, aby se nyní za nás ukázal před Boží tváří.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Nepřišel ani proto, aby častokrát obětoval sám sebe, jako velekněz každoročně vchází do svatyně s cizí krví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'neboť by musel od založení světa častokrát trpět; nyní však je zjeven jednou při dokonání věků ke zrušení hříchu skrze svou oběť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'A jako je lidem uloženo jednou zemřít a potom bude soud,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'tak i Kristus, když byl jednou obětován, aby vynesl hříchy mnohých, podruhé se bez hříchu ukáže k záchraně těm, kteří ho očekávají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Poněvadž Zákon má pouhý stín budoucího dobra, ne samu podobu těch skutečností, nemůže každoročně stejnými oběťmi, jež jsou stále přinášeny, nikdy učinit dokonalými ty, kdo s nimi přistupují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Což by ⌈nepřestali obětovat⌉, kdyby ti, kdo Bohu slouží, již neměli žádné vědomí hříchu, když jsou jednou očištěni?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Ale v těch obětech je každoročně připomínka hříchů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'neboť je nemožné, aby krev býků a kozlů odstraňovala hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Když tedy vchází do světa, praví: Oběť a obětní dar jsi nechtěl, ⌈připravil jsi mi však tělo⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'nelíbily se ti celopaly a oběti za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Tehdy jsem řekl: Hle, tu jsem -- v svitku knihy je napsáno o mně --, abych vykonal, Bože, tvou vůli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Když napřed říká: Oběti a obětní dary a celopaly a oběti za hřích jsi nechtěl ani se ti nelíbily -- tedy ty, které se obětují podle Zákona --,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'potom řekl: Hle, tu jsem, abych vykonal [, Bože,] tvou vůli. To první ruší, aby ustanovil to druhé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'V této vůli jsme posvěceni skrze oběť těla Ježíše Krista jednou provždy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Každý kněz stojí a koná denně službu a častokrát přináší stejné oběti, které nemohou nikdy odstranit hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'On však ⌈přinesl jedinou oběť za hříchy a navždy usedl⌉ po pravici Boží');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'a nadále jen čeká, až jeho nepřátelé budou položeni za podnož jeho nohou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Neboť jedinou obětí učinil navždy dokonalými ty, kteří jsou posvěcováni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Dosvědčuje nám to i Duch Svatý, neboť po slovech:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Toto je smlouva, kterou s nimi uzavřu po těch dnech, praví Pán: budu dávat své zákony do jejich srdce a napíši je do jejich mysli,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'dodává: a na jejich hříchy a jejich nepravosti již nikdy nevzpomenu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Kde je odpuštění hříchů, tam už ne ní oběti za hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Když tedy, bratři, máme smělou důvěru, ⌈že smíme vstoupit⌉ do svatyně Ježíšovou krví,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'cestou novou a živou, kterou nám otevřel skrze oponu, to jest skrze své tělo,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'a když máme velikého kněze nad domem Božím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'přistupujme s opravdovým srdcem v plnosti víry, se ⌈srdcem očištěným⌉ od zlého svědomí a s tělem obmytým čistou vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Neochvějně držme své vyznání naděje, neboť ten, který dal slib, je věrný;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'a buďme pozorní jedni k druhým, ⌈abychom se rozněcovali v⌉ lásce a dobrých skutcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Nezanedbávejme své společné shromažďování, jak mají někteří ve zvyku, nýbrž povzbuzujme se, a to tím více, čím více vidíte, že se ten den přibližuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Neboť jestliže dobrovolně hřešíme poté, co jsme přijali jasné poznání pravdy, nezůstává již více oběť za hříchy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'nýbrž jakési hrozné očekávání soudu a žár ohně, který bude stravovat odpůrce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Kdo pohrdl Mojžíšovým zákonem, umírá bez slitování na základě svědectví dvou nebo tří svědků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Uvažte, oč horšího trestu bude hoden ten, kdo pošlapal Syna Božího, a krev smlouvy, jíž byl posvěcen, měl za nečistou, a Ducha milosti potupil?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Neboť známe toho, kdo řekl: Mně náleží pomsta, já odplatím. A opět: Pán bude soudit svůj lid.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Je hrozné upadnout do rukou živého Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Připomínejte si dřívější dny, v nichž ⌈jste byli osvíceni a⌉ přestáli jste mnohý zápas s utrpením.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Buď jste byli veřejně vystavováni urážkám a soužením, nebo jste se stali společníky těch, s nimiž se takto nakládalo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Vždyť jste měli soucit s vězni a uloupení svého majetku jste přijali s radostí, vědouce, že máte [v nebi] vlastnictví lepší a trvalé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Neodhazujte tedy svou smělou důvěru, která má velikou odplatu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Je vám totiž třeba vytrvalosti, abyste vykonali Boží vůli a obdrželi zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Neboť ještě velmi, velmi krátký čas, a ⌈ten, který má přijít⌉, přijde a nebude otálet;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, '[můj] spravedlivý bude žít z víry, ale kdyby ustoupil, nebude v něm mít moje duše zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'My však nejsme ⌈ti, kdo ustupují⌉ k záhubě, nýbrž lidé víry k zachování duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Víra jest podstata věcí, v něž doufáme, důkaz skutečností, které nevidíme.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Neboť v ní ⌈naši předchůdci⌉ dostali svědectví Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Vírou rozumíme, že Božím výrokem byly uspořádány světy, takže to, co vidíme, nevzniklo z viditelného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Vírou přinesl Ábel [Bohu] lepší oběť než Kain. Skrze ni se mu dostalo svědectví, že je spravedlivý, když Bůh vydával svědectví při jeho darech, a skrze ⌈tu víru⌉ ještě mluví, i když zemřel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Vírou byl Henoch přenesen, aby nespatřil smrt. A nebyl nalezen, protože ho Bůh přenesl, neboť předtím, než byl přenesen, měl svědectví, že se líbil Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Bez víry však ne ní možné se mu zalíbit, protože ten, kdo přichází k Bohu, musí uvěřit, že Bůh je a že odplácí těm, kdo ho usilovně hledají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Vírou dostal Noe pokyn ohledně toho, co ještě nebylo vidět, a v bázni Boží připravil koráb k záchraně svého domu. Skrze ⌈svou víru⌉ odsoudil svět a stal se dědicem spravedlnosti, která je na základě víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Vírou uposlechl Abraham, když byl volán, aby vyšel na místo, které měl dostat za dědictví; a vyšel, ačkoli nevěděl, kam jde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Vírou se usadil v zaslíbené zemi jako v zemi cizí, bydlel ve stanech s Izákem a Jákobem, spoludědici téhož zaslíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Očekával totiž město mající základy, jehož stavitelem a tvůrcem je Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Vírou i sama Sára, [ač byla] [neplodná,] přijala moc k ⌈početí potomka⌉ a mimo ⌈svůj čas⌉ [porodila], protože měla za věrného toho, kdo dal slib.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Pročež z jednoho, a to z již odumřelého, byli zplozeni mnozí, počtem jako hvězdy nebeské a jako je nespočetný písek na břehu mořském.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Tito všichni zemřeli podle víry, aniž v plnosti přijali ta zaslíbení; jen zdaleka je zahlédli a pozdravili, a vyznali, že jsou cizinci a příchozí na zemi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Neboť ti, kdo to říkají, dávají najevo, že vyhlížejí vlast.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Kdyby totiž myslili na tu, z níž vyšli, měli by čas se navrátit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Avšak touží po lepší vlasti, to jest po vlasti nebeské. Proto se Bůh za ně nestydí, je–li nazýván jejich Bohem, neboť jim připravil město.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Vírou Abraham obětoval Izáka, když byl zkoušen; ten, který přijal ta zaslíbení, obětoval jediného syna,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'o kterém bylo řečeno: ⌈Z Izáka⌉ bude povoláno tvé símě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Usoudil, že Bůh je mocen křísit i z mrtvých. Proto ho dostal zpět ⌈jako předobraz⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Vírou požehnal Izák Jákobovi a Ezauovi i v tom, co se týkalo věcí budoucích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Vírou Jákob, když umíral, požehnal každému ze synů Josefových, a poklonil se Bohu nad vrcholem své berle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Vírou Josef, když dokonával, se zmínil o vyjití synů Izraele a dal příkaz o svých kostech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Vírou Mojžíš, když se narodil, byl svými rodiči po tři měsíce skrýván, protože viděli, že dítě je krásné, a nezalekli se králova nařízení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Vírou Mojžíš, když vyrostl, odmítl být nazýván synem faraonovy dcery');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'a vyvolil si raději spolu s Božím lidem snášet útrapy, než mít dočasný požitek z hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Za větší bohatství než poklady Egypta pokládal pohanu Kristovu, neboť vzhlížel ke své odplatě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Vírou opustil Egypt a nebál se králova hněvu; odolal, jako by viděl Neviditelného.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Vírou ⌈slavil Hod beránka⌉ a pokropení krví, aby se Zhoubce nedotkl jejich prvorozených.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Vírou prošli Rudé moře jako po suché zemi, ⌈když se však o to pokusili⌉ Egypťané, moře je pohltilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Vírou padly zdi Jericha, když je obcházeli po sedm dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Vírou nevěstka Rachab nezahynula spolu s těmi, kteří neuposlechli, protože s pokojem přijala vyzvědače.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'A co mám ještě říkat? Vždyť by mi nestačil čas, kdybych měl vypravovat o Gedeónovi, Barákovi, Samsonovi, Jeftovi, Davidovi, Samuelovi a prorocích,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'kteří skrze víru přemohli královské říše, uskutečnili spravedlnost, dosáhli zaslíbení, zavřeli tlamy lvům,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'uhasili sílu ohně, unikli ostří meče, nabyli moci ve slabosti, stali se silnými ve válce, ⌈zahnali na útěk⌉ vojska cizinců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Ženy dostaly své mrtvé ⌈zpět vzkříšené⌉, jiní byli mučeni ⌈a nepřijali vysvobození⌉, aby dosáhli lepšího vzkříšení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'jiní zas zakusili veřejný posměch a bičování, ba i pouta a vězení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'byli ukamenováni, rozřezáni pilou, [pokoušeni,] zemřeli rozsekáni mečem, toulali se v ovčích rounech, v kozích kůžích, trpěli nedostatkem, zakoušeli útisk a zlé jednání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Ti, jichž svět nebyl hoden, bloudili po pustinách, horách, jeskyních a roklinách země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'A tito všichni, ačkoli se jim dostalo svědectví skrze víru, neodnesli si zaslíbení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'protože Bůh pro nás zamýšlel něco lepšího, ne chtěl, aby dosáhli dokonalosti bez nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Proto i my, majíce ⌈kolem sebe⌉ tak veliký oblak svědků, odložme veškerou zátěž a hřích snadno nás ovíjející a s vytrvalostí běžme závod, který je ⌈před námi⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'upřeně hledíce k původci a dokonavateli víry Ježíši, který pro radost, která byla před ním, podstoupil kříž, pohrdnuv hanbou, a sedí po pravici Božího trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, '⌈Pomyslete na⌉ toho, který snesl od hříšníků proti sobě takový odpor, abyste neochabovali, umdlévajíce ve svých duších.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ještě jste se až do krve nevzepřeli v boji proti hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'A zapomněli jste na napomenutí, které vám praví jako synům: Můj synu, nepodceňuj Pánovu výchovu, ani neochabuj, když jsi od něho kárán;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'neboť koho Pán miluje, toho vychovává, a švihá každého, koho přijímá za syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, '⌈Snášejte to ke své výchově⌉, Bůh s vámi zachází jako se syny. Neboť [je] nějaký syn, jehož by otec nevychovával?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Jste–li však bez výchovy, jíž se stali účastni všichni, potom jste nemanželské děti, a ne synové.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Také v našich tělesných otcích jsme měli vychovatele a měli jsme je v úctě. Nebudeme mnohem více poddáni Otci duchů, ⌈abychom žili⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Vždyť oni vskutku na krátký čas vychovávali, jak jim připadalo správné, on však k užitku, abychom dostali podíl na jeho svatosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Každá výchova se ovšem v tu chvíli nezdá být radostná, ale krušná; potom však vydává pokojné ovoce spravedlnosti těm, kteří jsou jí vycvičeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Proto napravte umdlené ruce a zchromlá kolena');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'a čiňte přímé stezky pro své nohy, aby se to, co je chromé, nevyvrátilo, ale naopak aby se uzdravilo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Usilujte o pokoj se všemi a o posvěcení, bez něhož nikdo neuvidí Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Dbejte na to, aby se někdo nepřipravoval o Boží milost, aby vás netrápil nějaký vzhůru rostoucí kořen hořkosti a aby skrze něj nebyli poskvrněni mnozí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Ať nikdo ne ní smilník nebo bezbožný člověk jako Ezau, který prodal své prvorozenství za jediný pokrm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Neboť víte, že když později chtěl zdědit požehnání, i když je se slzami usilovně hledal, byl odmítnut, neboť nenalezl místo pro pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Neboť jste nepřistoupili k hmatatelné [hoře] a k planoucímu ohni a k temnotě a k mrákotě a vichru');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'a k zvuku polnice a takovému hlasu slov, že ti, kdo ho uslyšeli, prosili, aby k nim nebylo ⌈více mluveno⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'neboť nemohli snést to, co bylo přikazováno: I kdyby se zvíře dotklo té hory, bude ukamenováno,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'a tak strašná byla ta podívaná, že Mojžíš řekl: Jsem zděšen a třesu se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Ale přistoupili jste k hoře Siónu a k městu živého Boha, nebeskému Jeruzalému, a k desetitisícům andělů, k slavnostnímu shromáždění');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'a k církvi prvorozených, kteří jsou zapsáni v nebesích, a k Bohu, soudci všech, a k duchům spravedlivých, kteří jsou učiněni dokonalými,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'a k prostředníku nové smlouvy Ježíšovi, a ke krvi pokropení, která mluví lépe než Ábel.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Hleďte, ať neodmítnete toho, kdo mluví. Neboť jestliže neunikli oni, když odmítli toho, který k nim promlouval na zemi, tím spíše neunikneme my, odvrátíme–li se od toho, kdo mluví z nebes.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Jeho hlas tehdy zatřásl zemí, a nyní zaslíbil řka: Já ještě jednou zatřesu nejenom zemí, ale i nebem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Ono ještě jednou ukazuje na proměnu těch věcí, ⌈jimiž lze otřást⌉, neboť jsou učiněné, aby zůstaly ty věci, ⌈jež jsou neotřesitelné⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Projevujme proto vděčnost, že přijímáme neotřesitelné království, ⌈ a s ní⌉ přinášejme Bohu jemu příjemnou službu s uctivostí a bázní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Neboť náš Bůh je oheň stravující.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Bratrská láska ať zůstává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Nezanedbávejte pohostinnost; vždyť skrze ni někteří nevědomky pohostili anděly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Pamatujte na vězně, jako byste byli uvězněni s nimi; na ty, kteří jsou trápeni, jako ti, kteří jsou sami také v těle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Manželství ať je ⌈u všech⌉ ve vážnosti a manželské lože neposkvrněné, neboť smilníky a cizoložníky bude soudit Bůh.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Žijte bez lásky k penězům, spokojeni s tím, co máte; neboť on sám řekl: Nezanechám tě, ani tě neopustím;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'a tak s důvěrou říkejme: Pán je můj pomocník, nebudu se bát; co mi udělá člověk?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Vzpomínejte na své vůdce, kteří k vám mluvili Boží slovo, pečlivě pozorujte, jaký byl konec jejich života, a napodobujte jejich víru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Ježíš Kristus je tentýž včera i dnes, i na věky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Nenechte se unášet rozličnými a cizími učeními; neboť je dobré mít srdce upevňované milostí, ne zachováváním předpisů o pokrmech, jimiž si neprospěli ti, kdo si tak počínali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Máme oltář, z něhož nemají právo jíst ti, kdo slouží stánku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Neboť těla těch zvířat, jejichž krev je veleknězem vnášena za hřích do svatyně, jsou spalována ⌈venku za táborem⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Proto také Ježíš, aby svou vlastní krví posvětil lid, trpěl ⌈venku za branou⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Tak tedy vycházejme k němu ven za tábor, nesouce jeho potupu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Neboť zde nemáme trvalé město, ale toužebně hledáme to budoucí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Skrze něho [tedy] přinášejme Bohu stále oběť chvály, to jest ovoce rtů, vyznávajících jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'A nezapomínejte činit dobře a ⌈sdílet se⌉, neboť takové oběti se Bohu líbí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Poslouchejte své vůdce a buďte poddajní, neboť oni bdí nad vašimi dušemi jako ti, kdo budou vydávat počet; ať to mohou dělat s radostí, a ne se vzdycháním, neboť to by vám ne bylo k užitku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Modlete se za nás, neboť jsme přesvědčeni, že máme dobré svědomí, když si ve všem chceme počínat správně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Tím více vás však vyzývám, abyste to činili, abych se k vám brzo ⌈dostal zpátky⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'A Bůh pokoje, který vyvedl z mrtvých velkého pastýře ovcí ⌈pro krev⌉ věčné smlouvy, našeho Pána Ježíše,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'ať vás zdokonalí ⌈ve všem dobrém⌉ k vykonání jeho vůle, čině ⌈v nás⌉ to, co je před ním příjemné, skrze Ježíše Krista, jemuž buď sláva na věky [věků]. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Vyzývám vás, bratři, snášejte to slovo napomenutí, neboť jsem vám napsal jen krátce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Vězte, že [náš] bratr Timoteus je již propuštěn. Přijde–li brzo, uvidím vás s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Pozdravte všechny své vůdce a všechny svaté. Zdraví vás ti, kdo jsou z Itálie.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Milost se všemi vámi. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakub,otrokBoží a Pána Ježíše Krista, posílá pozdrav dvanácti kmenům,které jsou v rozptýlení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Pokládejte za velikou radost, moji bratři, když upadnete do rozličných pokušení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Víte, že zkoušení vaší víry působí vytrvalost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'A vytrvalost ať má dokonalý výsledek, abyste byli dokonalí a úplní a aby vám v ničem nic nescházelo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Nedostává–li se někomu z vás moudrosti, ať ji žádá od Boha, který dává všem štědře a nevyčítá, a bude mu dána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Ať však žádá ⌈ve víře⌉ a nic nepochybuje. Neboť kdo pochybuje, podobá se mořské vlně, hnané a zmítané větrem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Ať si takový člověk nemyslí, že něco od Pána dostane;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'je to muž nerozhodný, nestálý ⌈ve všem, co činí⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Bratr v nízkém postavení ať se chlubí ve svém povýšení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'a bohatý ve svém ponížení, protože pomine jako květ trávy:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'vyjde slunce se svým žárem a vysuší trávu, její květ opadne a krása jeho vzhledu zanikne. Tak i boháč uvadne v ⌈tom, co činí⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Blahoslavený muž, který snáší zkoušku, neboť když se osvědčí, dostane věnec života, jejž [Pán] zaslíbil těm, kdo ho milují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Ať nikdo, kdo je pokoušen, neříká: Jsem pokoušen od Boha. Bůh nemůže být pokoušen ⌈ke zlému⌉ a sám také nikoho nepokouší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Každý, kdo je pokoušen, je strháván a váben svou vlastní žádostivostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Žádostivost pak počne a rodí hřích, a dokonaný hřích plodí smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Nemylte se, moji milovaní bratři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Každé dobré dání a každý dokonalý dar je shůry, sestupuje od Otce světel, u něhož není proměny ani ⌈zatmění z odvrácení⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'On se rozhodl a zplodil nás slovem pravdy, abychom byli jakousi prvotinou jeho stvoření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, '⌈Víte to ⌉, moji milovaní bratři: Každý člověk ať je rychlý k naslouchání, ale pomalý k mluvení, pomalý k hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Neboť lidským hněvem se Boží spravedlnost nevypůsobí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Proto odložte veškerou nečistotu a přemíru špatnosti a v tichosti přijměte zaseté slovo, které má moc zachránit vaše duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Buďte však těmi, kdo slovo činí, ne buďte pouze posluchači, kteří klamou sami sebe.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Neboť je–li někdo posluchačem slova, a ne tím, kdo je činí, ten se podobá muži, který v zrcadle pozoruje svou přirozenou tvář;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'podíval se totiž na sebe a odešel, a hned zapomněl, jaký byl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Kdo se však zahledí do dokonalého zákona svobody a vytrvá, kdo se nestane zapomnětlivým posluchačem, nýbrž činitelem skutku, ten bude blahoslavený ve svém jednání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Domnívá–li se někdo, že je zbožný, a přitom nedrží na uzdě svůj jazyk, klame své srdce; jeho zbožnost je marná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Zbožnost čistá a neposkvrněná před Bohem a Otcem je toto: navštěvovat sirotky a vdovy v jejich soužení a zachovávat se neposkvrněným od světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Moji bratři, nespojujte víru v ⌈našeho Pána Ježíše Krista, Pána slávy,⌉ s přijímáním osob.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Když vejde do vašeho shromáždění muž se zlatým prstenem a v nádherném šatě a vejde tam také chudý člověk ve špinavém šatě,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'a vy věnujete pozornost tomu, který nosí nádherný šat, a řeknete mu: Ty si sedni pohodlně sem, a chudému řeknete: Ty postůj támhle nebo si sedni [sem] pod mou podnož,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'cožpak jste neučinili mezi sebou rozdíl a nestali se soudci ⌈se zlými pohnutkami⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Poslyšte, moji milovaní bratři! Což nevyvolil Bůh chudé toho to světa, aby byli bohatí ve víře a stali se dědici království, jež zaslíbil těm, kdo ho milují?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Vy však jste zneuctili chudého. Cožpak vás bohatí neutiskují a nevláčejí vás právě oni před soudy?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Což nehanobí právě oni to drahé jméno, ⌈jímž jste byli nazváni⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Jestliže vskutku plníte královský zákon podle Písma: Budeš milovat svého bližního jako sebe samého, dobře činíte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Jestliže však někomu straníte, dopouštíte se hříchu a Zákon vás usvědčuje jako přestupníky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Kdo by totiž zachoval celý Zákon, ale v jedné věci klopýtl, stal by se vinným ve všech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Vždyť ten, kdo řekl: Nezcizoložíš, řekl také: Nezavraždíš. Jestliže tedy necizoložíš, ale vraždíš, stal ses přestupníkem Zákona.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tak mluvte a tak jednejte jako ti, kteří mají být souzeni podle zákona svobody.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Neboť soud bez milosrdenství je pro toho, kdo neprokázal milosrdenství; milosrdenství přemáhá soud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Co je platné, moji bratři, říká–li někdo, že má víru, ale nemá skutky? Může ho ta ková víra zachránit?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Budou–li bratr nebo sestra nazí a budou mít nedostatek denní obživy,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'a někdo z vás jim řekne: Odejděte v pokoji,zahřejte se a nasyťte se, a přitom jim nedáte to, co potřebují pro své tělo, co je to platné?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Tak i víra:nemá–li skutky, je sama o sobě mrtvá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Někdo však řekne: Ty máš víru a já mám skutky. Ukaž mi tu svou víru bez skutků a já ti ukážu svou víru na svých skutcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ty věříš, že ⌈je jeden Bůh⌉. Dobře činíš. Také démoni tomu věří, a však chvějí se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Chceš však poznat, ó nerozumný člověče, že víra bez skutků je neúčinná?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Cožpak náš otec Abraham nebyl ospravedlněn ze skutků, když na oltáři obětoval svého syna Izáka?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Vidíš, že víra ⌈působila spolu s jeho skutky⌉ a že v těch skutcích se stala víra dokonalou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'I naplnilo se Písmo, které praví: Uvěřil Abraham Bohu, a bylo mu to počteno za spravedlnost a byl nazván Božím přítelem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vidíte, že ze skutků je člověk ospravedlňován, a ne jen z víry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'A nebyla podobně ospravedlněna ze skutků i nevěstka Rachab, když přijala posly a propustila je jinou cestou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Neboť jako je tělo bez ducha mrtvé, tak je mrtvá i víra bez skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Nebuďte mnozí učiteli, moji bratři; víte, že ⌈budeme souzeni přísněji⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Neboť všichni ⌈často chybujeme. Kdo nechybuje⌉ ve slově, ten je dokonalý muž, schopný držet na uzdě i celé tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, '⌈Dáváme–li koňům do huby udidlo, aby nás poslouchali, řídíme tím ⌉ celé jejich tělo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Hle i lodi, ačkoliv jsou tak veliké a bývají hnány prudkými větry, jsou řízeny maličkým kormidlem podle vůle toho, kdo je řídí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Tak i jazyk je malý úd, ale honosí se velkými věcmi. Hle, jak malý oheň, a jak velký les zapálí!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'I jazyk je oheň, svět nepravosti; jazyk je mezi našimi údy ten, který poskvrňuje celé tělo, zapaluje ⌈běh našeho života⌉ a sám je zapalován Gehennou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Každý druh zvířat a ptáků, plazů a mořských živočichů bývá krocen a je zkrocen druhem lidským,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'ale jazyk neumí zkrotit nikdo z lidí. Je to nepokojné zlo, plné smrtonosného jedu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Jím dobrořečíme Pánu a Otci, a jím také zlořečíme lidem, učiněným podle Boží podoby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Z týchž úst vychází žehnání i zlořečení. Moji bratři, tak to nemá být!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Cožpak chrlí pramen z téhož otvoru vodu sladkou i hořkou?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Moji bratři, může fíkovník nést olivy nebo réva fíky? [Tak] ani slaný pramen nevydá sladkou vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kdo je mezi vámi moudrýa rozumný? Ať ukáže dobrým způsobem života své skutky v moudré tichosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Máte–li však v srdci hořkou závist a soupeření, nechlubte se a nelžete proti pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'To není moudrost sestupující shůry, ale pozemská, duševní, démonská.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Vždyť kde je závist a soupeření, tam je zmatek a kdejaká špatná věc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Moudrost shůry je především čistá, potom pokojná, mírná, poddajná, plná milosrdenství a dobrého ovoce, nepochybující, bez přetvářky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Ovoce spravedlnosti je v pokoji zaséváno těm, kdo působí pokoj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Odkud jsou boje a hádky mezi vámi? Zdali ne odtud -- z vašich rozkoší, které bojují ve vašich údech?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Dychtíte, ale nemáte. Zabíjíte a žárlíte, ale nemůžete ničeho dosáhnout. Hádáte se a bojujete, a nic nemáte, protože nežádáte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Žádáte, a nedostáváte, protože žádáte špatně, abyste to vynaložili na své rozkoše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, '[Cizoložníci a] cizoložnice! Nevíte, že přátelství se světem je nepřátelství s Bohem? Kdo tedy chce být přítelem světa, stává se nepřítelem Božím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Či myslíte, že nadarmo praví Písmo: Žárlivě touží ⌈Duch, který v nás přebývá⌉?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Ještě větší je však milost, kterou dává. Proto Písmo praví: Bůh se staví proti pyšným, ale pokorným dává milost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Poddejte se tedy Bohu. Postavte se proti Ďáblu, a uteče od vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Přibližte se k Bohu, a přiblíží se k vám. Očisťte ruce, hříšníci, a očisťte srdce, lidé ⌈dvojí mysli⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Pociťte svou ubohost, naříkejte a plačte. Váš smích ať se obrátí v nářek a vaše radost v sklíčenost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Pokořte se před Pánem, a povýší vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Bratři, nemluvte jeden proti druhému. Kdo mluví proti bratru nebo soudí svého bratra, mluví proti Zákonu a soudí Zákon. Jestliže však soudíš Zákon, nejsi činitelem Zákona, nýbrž soudcem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Jeden je zákonodárce a soudce, ten, který může zachránit i zahubit. Ale kdo jsi ty, jenž soudíš bližního?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nuže nyní vy, kteří říkáte: Dnes nebo zítra půjdeme do toho a toho města a zůstaneme tam rok a budeme obchodovat a vydělávat --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'nevíte, co bude zítra! Co je váš život? Vždyť jste pára, která se na chvilku ukazuje a potom mizí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Místo toho byste měli říkat: „Bude–li Pán ⌈chtít, budeme naživu a uděláme⌉ to nebo ono.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Vy se však chlubíte ve ⌈své chvástavosti⌉. Každé takové chlubení je zlé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Kdo tedy umí činit dobré, ale nečiní, má hřích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Nuže nyní, boháči, plačte a naříkejte nad svými trápeními, která na vás přicházejí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vaše bohatství je shnilé a vaše šatstvo je rozežráno moly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Vaše zlato a stříbro zrezavělo a jejich rez bude na svědectví proti vám a stráví vaše těla jako oheň. Nashromáždili jste si v posledních dnech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Hle, mzda, kterou jste zadrželi dělníkům, kteří požali vaše pole, hlasitě křičí, a volání ženců pronikla k sluchu Pána Sabaoth.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Hýřili jste na zemi a oddávali se rozkoším. Vykrmili jste svá srdce v den porážky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Odsoudili a zavraždili jste spravedlivého; on vám neodporuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Buďte tedy trpěliví, bratři, až do Pánova příchodu. Hle, rolník očekává vzácný plod země, trpělivě na něj čeká, až se mu dostane ⌈podzimního a jarního⌉ [deště].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Buďte i vy trpěliví a upevněte svá srdce, protože Pánův příchod se přiblížil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Nenaříkejte, bratři, jeden na druhého, abyste nebyli souzeni. Hle, soudce stojí přede dveřmi!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Za vzor ve snášení zlého a v trpělivosti si, bratři, vezměte proroky, kteří mluvili v Pánově jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Hle, blahoslavíme ty, kteří vytrvali. Slyšeli jste o Jobově vytrvalosti a viděli jste, ⌈ jaký konec mu Pán připravil ⌉. Neboť Pán je velmi soucitný a milostivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Především nepřísahejte,moji bratři, ani při nebi ani při zemi, ani žádnou jinou přísahou. Vaše ano ať je ano a ne ať je ne, abyste nepropadli soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Vede se někomu z vás zle? Ať se modlí! Je někdo dobré mysli? Ať zpívá Bohu chvály!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Je někdo mezi vámi nemocen? Ať zavolá starší sboru a ti ať se nad ním pomodlí a pomažou ho olejem v Pánově jménu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'A modlitba víry zachrání nemocného a Pán ho pozdvihne; a jestliže se dopustil hříchů, bude mu odpuštěno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Vyznávejte hříchy jeden druhému a modlete se jeden za druhého, abyste byli uzdraveni. Mnoho zmůže ⌈účinná modlitba spravedlivého⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Eliáš byl člověk stejně podrobený utrpení jako my; ⌈pomodlil se opravdově⌉, aby nepršelo,a vskutku nezapršelo v zemi po tři roky a šest měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'A znovu se pomodlil, a nebe dalo déšť a země vydala svou úrodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Moji bratři, zbloudí–li někdo mezi vámi od pravdy a někdo ho obrátí zpět,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, '⌈ať ví⌉, že kdo obrátí hříšníka od jeho bludné cesty, zachrání jeho duši od smrti a přikryje množství hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petr, apoštol Ježíše Krista, vyvoleným příchozím rozptýleným v Pontu, Galacii, Kappadokii, Asii a Bithynii,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'podle předzvědění Boha Otce ⌈v posvěcení⌉ Ducha k poslušnosti a pokropení krví Ježíše Krista. Kéž se vám rozhojní milost a pokoj!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Požehnaný Bůh a Otec našeho Pána Ježíše Krista, který nás podle svého velikého milosrdenství znovu zplodil k živé naději vzkříšením Ježíše Krista z mrtvých,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'k dědictví nezničitelnému, neposkvrněnému a nevadnoucímu, uchovávanému v nebesích pro vás,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'kteří jste mocí Boží střeženi skrze víru k záchraně, ⌈která je připravena⌉, aby byla zjevena v posledním čase.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Proto jásáte, i když jste nyní nakrátko, je–li to nutné, zarmouceni rozličnými zkouškami,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'aby osvědčenost vaší víry, vzácnější než pomíjející zlato, jež je zkoušeno ohněm, byla nalezena k chvále, slávě a cti při zjevení Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Ač jste ho neviděli, milujete ho; ačkoli ho ani nyní nevidíte, věříte v něho a jásáte nevýslovnou radostí, ⌈plnou slávy⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'docházejíce cíle [své] víry, záchrany duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Tuto záchranu horlivě hledali a po ní pátrali proroci, kteří prorokovali o milosti pro vás připravené;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'zkoumali, na který nebo na jaký čas ukazoval Duch Kristův v nich, když předem svědčil o utrpeních určených Kristu a o ⌈velké slávě, která přijde po nich⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Jim bylo zjeveno, že ne sami sobě, nýbrž vám sloužili těmi věcmi, které vám nyní byly oznámeny skrze ty, kteří vám přinesli evangelium v Duchu Svatém, poslaném z nebe, věcmi, do nichž andělé touží nahlédnout.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Proto přepásejte bedra své mysli, buďte střízliví, dokonale upněte svou naději k milosti, která je vám přinášena ve zjevení Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Jako ⌈poslušné děti⌉ se nepřizpůsobujte dřívějším žádostem, ⌈jako když jste byli v nevědomosti⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'ale podle toho Svatého, který vás povolal, se i vy staňte svatými v celém svém způsobu života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Vždyť je napsáno: Buďte svatí, neboť já jsem svatý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Jestliže vzýváte jako Otce toho, kdo nestranně soudí každého podle jeho skutků, pro žijte v bázni čas svého přebývání v cizině.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Víte, že ze svého marného způsobu života, zděděného po otcích, jste byli vykoupeni ne pomíjejícími věcmi, stříbrem nebo zlatem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'nýbrž drahou krví Krista jako beránka bez vady a bez poskvrny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, '⌈ On byl předem poznán⌉ před založením světa a byl na konci časů zjeven pro vás,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'kteří skrze něho věříte v Boha, jenž ho probudil z mrtvých a dal mu slávu, takže vaše víra ⌈i naděje se upíná k Bohu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Když jste poslušností pravdy [skrze Ducha] očistili své duše k bratrské lásce bez přetvářky, vroucně se navzájem milujte z [čistého] srdce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Vždyť jste se znovu narodili ne z pomíjitelného semene, nýbrž z nepomíjitelného, skrze živé a [na věčnost] zůstávající slovo Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Neboť každé tělo je jako tráva a všecka jeho sláva jako květ trávy. Uschne tráva, květ opadne,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'ale Pánovo slovo zůstává na věčnost -- to je to slovo, které vám bylo zvěstováno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Odložte tedy každou špatnost a každou lest, pokrytectví, závist a každou pomluvu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'a jako novorozené děti mějte touhu po nefalšovaném ⌈mléku Božího slova⌉, abyste jím vyrostli [k záchraně],');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'jestliže jste [vskutku] okusili, že Pán je dobrý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, '⌈Když přicházíte⌉ k němu, kameni živému, jenž byl od lidí zavržen, ale před Bohem je vyvolený, vzácný,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'i vy sami jako živé kameny jste budováni jako duchovní dům ve svaté kněžstvo, abyste přinášeli duchovní oběti, příjemné Bohu skrze Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Proto stojí v Písmu: Hle, kladu na Siónu kámen úhelný, vyvolený, vzácný; kdo v něj věří, jistě nebude zahanben.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Vám tedy, kteří věříte, je vzácností, ale nevěřícím je to kámen, který stavitelé zavrhli; ten se stal ⌈kamenem úhelným⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'a kamenem úrazu a skálou pohoršení. Ti ⌈narážejí, protože jsou neposlušnislova; k tomu také byli určeni⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Vy však jste rod vyvolený, královské kněžstvo, národ svatý, lid určený k Božímu vlastnictví, abyste rozhlásili ⌈mocné skutky⌉ toho, jenž vás povolal ze tmy do svého podivuhodného světla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Vy, kdysi Ne–lid, jste nyní lid Boží; vy, kdysi Ne–slitovaní, jste však nyní došli slitování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Milovaní, prosím vás jako cizince a příchozí: zdržujte se tělesných žádostí, které vedou boj proti duši;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'veďte dobrý způsob života mezi pohany, aby v tom, v čem vás pomlouvají jako zločince, ⌈uviděli vaše dobré skutky a oslavili Boha⌉ v den navštívení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Kvůli Pánu se podřiďte každému lidskému zřízení: ať králi jako svrchovanému vládci,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'ať místodržícím jako těm, kteří jsou od něho posíláni k tomu, aby trestali zločince a uznávali ty, kdo jednají dobře;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'neboť taková je vůle Boží, abyste dobrým jednáním umlčovali neznalost nerozumných lidí;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'jako svobodní, a ne jako ti, kteří mají svobodu za plášť špatnosti, nýbrž jako otroci Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Všechny ctěte, bratrstvo milujte, Boha se bojte, krále mějte v úctě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Sluhové, podřizujte se ve vší bázni pánům, nejen dobrým a mírným, nýbrž i zlým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Je to totiž milost, snáší–li někdo bolesti kvůli svědomí před Bohem a trpí nespravedlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Neboť jaká to bude sláva, budete–li snášet rány za to, že hřešíte? Ale budete–li snášet utrpení, ač jednáte dobře, to je milost před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'K tomu jste přece byli povoláni, neboť i Kristus trpěl za vás a zanechal vám příklad, abyste šli v jeho šlépějích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'On se nedopustil hříchu, ani lest nebyla nalezena v jeho ústech.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Když mu spílali, neodplácel spíláním, když trpěl, nehrozil, ale předával vše tomu, jenž soudí spravedlivě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'On sám ve svém těle vynesl naše hříchy na dřevo kříže, abychom zemřeli hříchům a byli živi spravedlnosti. Jeho zraněním jste byli uzdraveni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Neboť jste bloudili jako ovce, ale nyní ⌈jste se obrátili⌉ k pastýři a strážci svých duší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Stejně se i vy, ženy, podřizujte svým mužům, aby i ⌈ti, kdo neposlouchají slovo⌉, byli beze slova získáni jednáním svých žen,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'až zpozorují vaše čisté chování v bázni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Vaše ozdoba ať není vnější: spletené vlasy, navlékání ⌈zlatých šperků ⌉, oblékání šatů,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'nýbrž skrytý člověk srdce v nepomíjitelnosti tichého a pokojnéhoducha, který je před Bohem vzácný.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Tak se kdysi zdobily i svaté ženy, které doufaly v Boha a podřizovaly se svým mužům;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'jako Sára poslouchala Abrahama a nazývala ho pánem. Vy jste se staly jejími dcerami, jednáte–li dobře a nedáte–li se ničím zastrašit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Stejně muži: žijte se svými ženami podle poznání jako se slabší ženskou nádobou a prokazujte jim úctu jako spoludědičkám milosti života, aby vaše modlitby neměly překážku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'A konečně: buďte všichni jednomyslní, soucitní, ⌈plní bratrské lásky⌉, milosrdní a pokorní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Neodplácejte zlým za zlé ani urážkou za urážku, ale naopak žehnejte; vždyť k tomu jste byli povoláni, abyste jako dědictví obdrželi požehnání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Neboť kdo chce milovat život a vidět dobré dny, ať zdržuje jazyk od zlého a rty ⌈od lstivých slov⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'ať se odvrátí od zlého a činí dobré, ať hledá pokoj a ⌈usiluje o něj⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'neboť Pánovy oči jsou obráceny na spravedlivé a jeho uši k jejich prosbě, ale Pánova tvář proti těm, kdo činí zlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'A kdo vám ublíží, budete–li ⌈horlivě usilovat⌉ o dobro?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ale i kdybyste měli trpět pro spravedlnost, jste blahoslavení. Nebojte se jich a nerozrušujte se,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'ale Pána, Krista, posvěťte ve svých srdcích. Buďte stále připraveni k obhajobě před každým, kdo by od vás žádal⌈, abyste vydali počet z⌉ naděje, ⌈kterou máte⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'avšak s tichostí a s bázní, majíce dobré svědomí, aby ti, kteří hanobí váš dobrý způsob života v Kristu, byli zahanbeni v tom, v čem vás pomlouvají [jako zločince].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Neboť je lépe trpět, bude–li to chtít Boží vůle, když jednáte dobře, než když jednáte zle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Vždyť i Kristus jednou provždy trpěl za hříchy, spravedlivý za nespravedlivé, aby vás přivedl k Bohu. V těle byl sice usmrcen, ale v Duchu obživen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'V něm také přišel a vyhlásil zvěst duchům ve vězení,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'kteří kdysi neuposlechli, když Boží trpělivost ve dnech Noemových vyčkávala, zatímco byl stavěn koráb, v němž jen několik, to jest osm duší, bylo zachráněno skrze vodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Naplnění tohoto předobrazu -- křest -- i vás nyní zachraňuje, ne jako odložení tělesné špíny, nýbrž jako ⌈odpověď dobrého svědomí Bohu⌉, skrze zmrtvých vstání Ježíše Krista,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'jenž přišel do nebe, byli mu podřízeni andělé, vlády a moci, a je na pravici Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Když tedy Kristus [za nás] trpěl v těle, i vy se vyzbrojte týmž smýšlením, ⌈ totiž že⌉ ten, kdo trpěl v těle, skoncoval s hříchem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'abyste po zbývající čas života v těle již nežili podle lidských žádostí, nýbrž podle Boží vůle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Dost již zajisté na tom, že jste v uplynulém čase života vykonávali vůli pohanů, když jste žili v bezuzdnostech, v žádostech, v opilství, v hýření, v pitkách a v nedovoleném uctívání model.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Proto se diví, že s nimi neběháte do téhož proudu prostopášnosti, a urážejí vás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Ti vydají počet tomu, kdo je připraven soudit živé i mrtvé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Vždyť proto bylo evangelium zvěstováno i mrtvým, aby žili podle Boha v Duchu, ačkoli byli ⌈podle lidí⌉ v těle odsouzeni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Konec všeho se přiblížil. Staňte se tedy rozvážnými a střízlivými k modlitbám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Především k sobě mějte vroucí lásku, neboť láska přikrývá množství hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Buďte jedni k druhým pohostinní, a to bez reptání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Dary milosti, podle toho, jak jej každý přijal, si služte navzájem jako dobří správci rozličné Boží milosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Mluví–li někdo, ať mluví jakožto Boží výroky. Slouží–li někdo, ať slouží ze síly,kterou poskytuje Bůh, aby byl ve všem oslavován Bůh skrze Ježíše Krista, jemuž patří sláva a moc na věky věků. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Milovaní, nedivte se té výhni ⌈zkoušek mezi vámi⌉, která vám nastává, jako by se vám dálo něco divného,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'ale když máte podíl na Kristových utrpeních, radujte se, abyste se stejně radovali a jásali i při zjevení jeho slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Jste–li tupeni pro jméno Kristovo, jste blahoslavení, neboť na vás spočívá Duch slávy [a moci], Duch Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Ať nikdo z vás netrpí jako vrah nebo zloděj nebo zločinec nebo jako pletichář.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Jestliže však trpí jako křesťan,ať se nestydí, ale slaví Boha ⌈v tomto jménu⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Neboť je čas, aby soud začal od domu Božího. Tedy jestliže nejprve od nás, jaký bude konec těch, kteří jsou neposlušni Božího evangelia?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'A jestliže je stěží zachráněn spravedlivý, kde se ukáže bezbožník a hříšník?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Proto i ti, kteří trpí podle vůle Boží, ať v konání dobra svěří své duše věrnému Stvořiteli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Starší mezi vámi vybízím, já spolustarší a svědek Kristových utrpení a také účastník ⌈budoucí slávy, která bude zjevena⌉:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paste Boží stádo, které je u vás; [dohlížejte na ně] ne z donucení, ale dobrovolně, [podle Boha,] ne z nízké zištnosti, ale ochotně,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'ne jako páni nad svým podílem, ale jako ti, kteří se svému stádu stávají vzorem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'A když se ukáže nejvyšší pastýř, dostanete nevadnoucí věnec slávy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Stejně se vy mladší podřiďte starším. A všichni se oblečte v pokoru jeden vůči druhému, neboť Bůh se staví proti pyšným, ale pokorným dává milost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Pokořte se tedy pod mocnou Boží ruku, aby vás povýšil v příhodný čas.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Všechnu svou starost uvrhněte na něho, neboť mu na vás záleží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Buďte střízliví a bděte! Váš protivník Ďábel obchází jako řvoucí lev a hledá, koho by pohltil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Postavte se proti němu, pevní ve víře, vědouce, že tatáž utrpení se naplňují na vašem bratrstvu po celém světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'A Bůh veškeré milosti, který vás povolal ke své věčné slávě v Kristu [Ježíši], vás, když nakrátko snesete utrpení, sám zdokonalí, utvrdí, posílí, postaví na pevný základ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Jemu buď [sláva a] moc na věky [věků]. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Krátce jsem vám napsal prostřednictvím Silvána, věrného bratra, jak se domnívám. Napomínám vás a dosvědčuji vám, že taková je pravá Boží milost; v ní stůjte.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Pozdravuje vás spoluvyvolená v Babylonu a Marek, můj syn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Pozdravte se navzájem políbením lásky. Pokoj vám všem, kteří jste v Kristu [Ježíši. Amen].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Šimon Petr, otrok a apoštol Ježíše Krista, těm, kdo dostali stejně vzácnou víru jako my spravedlností našeho Boha a Zachránce Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Milost a pokoj kéž se vám rozhojní v poznání Boha a Ježíše [Krista], našeho Pána.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Jeho božská moc nám darovala všechno, čeho je třeba k životu a zbožnosti skrze poznání toho, který nás povolal [vlastní] slávou a mocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Tím nám byla darována vzácná a veliká zaslíbení, abyste se skrze ně stali účastníky božské přirozenosti a unikli zkáze, která je ve světě v žádostivosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'A právě proto vynaložte všechno úsilí a doplňte svou víru ctností, ctnost poznáním,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'poznání sebeovládáním, sebeovládání vytrvalostí, vytrvalost zbožností,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'zbožnost bratrskou náklonností, bratrskou náklonnost láskou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Máte–li totiž tyto vlastnosti a rozhojňují–li se, způsobí, že nebudete nečinní ani neplodní pro poznání našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Kdo však tyto vlastnosti nemá, je slepý, krátkozraký; zapomněl, že byl očištěn od svých starých hříchů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Proto se, bratři, tím více snažte upevňovat svoje povolání a vyvolení; neboť ⌈budete–li to činit⌉, nikdy nepadnete.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Tak vám bude bohatě poskytnut vstup do věčného království našeho Pána a Zachránce Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Proto vám hodlám tyto věci stále připomínat, ačkoliv o nich víte a jste utvrzeni v přítomné pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Považuji však za správné probouzet vás tím, že je připomínám, dokud jsem v tomto stanu svého těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Vím, že složení mého stanu je velice blízko,jak mi to i ukázal náš Pán Ježíš Kristus.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Vynasnažím se, abyste si mohli i po mém odchodu toto všechno pokaždé připomínat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Vždyť jsme nenásledovali vymyšlené báje, když jsme vás seznámili s mocí a příchodem našeho Pána Ježíše Krista, ale sami jsme se stali očitými svědky jeho velebnosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'On přijal od Boha Otce čest a slávu, když k němu z velebné slávy zazněl takovýto hlas: Toto je můj milovaný Syn, v němž jsem nalezl zalíbení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'A tento hlas, který zazněl z nebe, jsme my slyšeli, když jsme s ním byli na té svaté hoře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'A máme ještě pevnější prorocké slovo. Dobře činíte, že se ho držíte jako světla, které svítí v temném místě, dokud se nerozbřeskne den a jitřenka nevzejde ve vašich srdcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Toto především vězte, že žádné proroctví Písma není záležitostí vlastního výkladu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Neboť proroctví nikdy nebylo proneseno z lidské vůle, nýbrž unášeni Duchem Svatým mluvili ⌈lidé poslaní od Boha⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'V lidu se však také objevovali falešní proroci, jako i mezi vámi budou lživí učitelé, kteří budou tajně zavádět zhoubná kacířství a Panovníka, který je vykoupil, budou zapírat. Tím na sebe uvedou rychlou záhubu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'A mnozí budou následovat jejich bezuzdnosti a cesta pravdy bude kvůli nim v opovržení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Z hrabivosti budou z vás těžit podvodnými slovy. Ale jejich odsouzení odedávna nezahálí a jejich zhouba nespí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Neboť Bůh neušetřil ani anděly, kteří zhřešili, ale svrhl je do ⌈temných jeskyní⌉ Tartaru a vydal je, aby byli střeženi k soudu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Ani starý svět neušetřil, ale zachoval jen Noeho, hlasatele spravedlnosti, ⌈ jednoho z osmi⌉, když uvedl potopu na svět bezbožných.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Také města Sodomu a Gomoru obrátil v popel a odsoudil [k zániku] a tím dal varovný příklad budoucím bezbožníkům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Vysvobodil však spravedlivého Lota, sužovaného nezřízeným chováním bezuzdných lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Neboť ⌈tím, co viděl i slyšel⌉ ten spravedlivý, když mezi nimi bydlel, těmito bezzákonnými skutky mučil den za dnem svou spravedlivou duši.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Pán umí vysvobozovat zbožné ze zkoušky, ale nespravedlivé zachovávat ⌈pro trest⌉ ke dni soudu;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'a to hlavně ty, kdo jdou za tělem v poskvrňující žádosti a pohrdají autoritou. Drzí opovážlivci, nebojí se tupit ⌈duchovní mocnosti⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'když ani andělé, ačkoli jsou větší silou a mocí, nevynášejí proti nim [před Pánem] potupný soud.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Tito však jako nerozumná zvířata, zrozená jako pouhá přírodní stvoření k lovení a zkáze, se rouhají tomu, co neznají; ve své záhubě také zahynou');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'a dostane se jim [bezpráví jako] mzdy za bezpráví. Za rozkoš považují denní rozmařilost; jsou poskvrnou a hanbou, jak hýří ⌈ve svých klamech⌉, když s vámi hodují.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Oči mají plné cizoložství a nenasytné hříchu; lákají neupevněné duše, srdce mají vycvičené v hrabivosti; jsou to děti prokletí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Opustili přímou cestu a zabloudili, dali se na cestu Balaáma, syna Bosorova, který ⌈dal přednost mzdě⌉ za nepravost,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'ale byl za svůj zlý čin pokárán. Němé tažné zvíře promluvilo lidským hlasem a zabránilo prorokovu šílenství.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Tito lidé jsou prameny bez vody a mlhy hnané vichřicí; je pro ně [na věky] uchována mrákota tmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Neboť honosně mluví slova marnosti a lákají v žádostech těla výstřednostmi ty, kdo sotva utíkají těm, kteří žijí v bludu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Slibují jim svobodu,ačkoli sami jsou otroky zkázy; vždyť čemu člověk podlehne, tím je zotročen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Jestliže totiž ti, kteří unikli poskvrnám světa poznáním [našeho] Pána a Zachránce Ježíše Krista, se znovu do nich zapletou a podlehnou jim, jsou jejich poslední věci horší než první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Bylo by pro ně lépe, kdyby nepoznali cestu spravedlnosti, než když ji poznali, a odvrátili se od svatého přikázání, které jim bylo předáno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Přihodilo se jim to, co říká toto pravdivé přísloví: Pes se vrátil k vlastnímu vývratku a umytá svině ⌈se opět válí v bahně⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Toto vám, milovaní, píšu již druhý list, ve kterém připomínáním probouzím vaši čistou mysl,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'abyste pamatovali na slova předpověděná svatými proroky a na příkaz Pána a Zachránce, předaný vašimi apoštoly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Především vězte, že v posledních dnech přijdou s posměchem posměvači, ⌈kteří budou žít⌉ podle svých vlastních žádostí');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'a budou říkat: Kde je to zaslíbení jeho příchodu? Od té doby, co zesnuli otcové, všechno zůstává tak, jak to je od počátku stvoření.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Je jim totiž skryté, neboť to chtějí, že nebesa byla od pradávna a země povstala z vody a skrze vodu slovem Božím,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'skrze něž také tehdejší svět zahynul, když byl zatopen vodou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'A týmž slovem jsou nynější nebesa a země uschovány k ohni a střeženy pro den soudu a záhuby bezbožných lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Tato jedna věc ať vám není skryta, milovaní, že jeden den je u Pána jako tisíc let a tisíc let jako jeden den.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Pán neotálí s naplněním svého zaslíbení, ⌈jak si někteří myslí⌉, nýbrž je k vám shovívavý, nechtěje, aby někdo zahynul, ale chce, aby všichni dospěli k pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Pánův den přijde jako zloděj [v noci]. V něm nebesa s rachotem pominou, prvky se žárem uvolní a země a její činy budou spáleny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Když se toto všechno [takto] rozplyne, jací musíte být ve svatém způsobu života a zbožnosti [vy],');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'kteří očekáváte a urychlujete příchod Božího dne! Kvůli němu se nebesa rozplynou v ohni a prvky se žárem roztaví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Podle jeho zaslíbení očekáváme nová nebesa a novou zemi, ve kterých přebývá spravedlnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Proto, milovaní, očekáváte–li tyto věci, vynasnažte se, abyste jím byli nalezeni v pokoji, bez poskvrny a bez úhony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'A trpělivost našeho Pána považujte za záchranu, jak vám to napsal i náš milovaný bratr Pavel podle moudrosti, která mu byla dána,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'a jak to napsal i ve všech dalších listech, v nichž o tom mluví. Jsou v nich některé těžko srozumitelné věci, které neučení a neupevnění lidé překrucují, jako i ostatní Písma, ke své vlastní záhubě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ale vy, milovaní, protože to víte předem, chraňte se, abyste nebyli svedeni bludem bezuzdných lidí a neodpadli od vlastního pevného základu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Rosťte v milosti a poznání našeho Pána a Zachránce Ježíše Krista. Jemu buď sláva i nyní a až do dne věčnosti. [Amen].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Co bylo od počátku, co jsme slyšeli, co jsme na vlastní oči viděli, co jsme spatřili a čeho se naše ruce dotýkaly ohledně Slova života: --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Ten život byl zjeven, viděli jsme a svědčíme a zvěstujeme vám věčný život, který byl u Otce a nám byl zjeven. --');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Co jsme viděli a slyšeli, zvěstujeme i vám, abyste také vy měli společenství s námi. Naše společenství je s Otcem a s jeho Synem Ježíšem Kristem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Toto [vám] píšeme, aby naše radost byla úplná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'A toto je zvěst, kterou jsme od něho slyšeli a vám ji zvěstujeme: Bůh je světlo a není v něm žádná tma.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Řekneme–li, že s ním máme společenství, a přitom chodíme v temnotě, lžeme a nečiníme pravdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Jestliže však chodíme v tom světle, jako on je v tom světle, máme společenství mezi sebou a krev Ježíše [Krista], jeho Syna, nás očišťuje od každého hříchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Řekneme–li, že žádný hřích nemáme, klameme sami sebe a pravda v nás není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Jestliže své hříchy vyznáváme, on je věrný a spravedlivý, aby nám hříchy odpustil a očistil nás od každé nepravosti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Řekneme–li, že jsme nezhřešili, děláme z něj lháře a jeho slovo v nás není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Moje dítky, toto vám píši, abyste nezhřešili; a jestliže by někdo zhřešil, máme u Otce Zastánce, Ježíše Krista, toho spravedlivého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'On je smírčí obětí za naše hříchy, a nejen za naše, ale i za hříchy celého světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'A podle toho víme, že jsme jej poznali, jestliže zachováváme jeho přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Kdo říká: Znám ho, a jeho přikázání nezachovává, je lhář a pravda v něm není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Kdo však zachovává jeho slovo, v tom ⌈se skutečně Boží láska stala dokonalou⌉. Podle toho poznáváme, že jsme v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Kdo říká, že ⌈v něm zůstává⌉, musí sám také žít [tak], jak žil on.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Milovaní, nepíšu vám nové přikázání, ale staré, které jste měli od počátku. To staré přikázání je slovo, které jste [už dávno] slyšeli.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'A opět vám píšu přikázání nové, a to je pravdivé v něm i ve vás, že tma pomíjí a to pravé světlo již svítí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kdo říká, že je ve světle, a přitom nenávidí svého bratra, je dosud ve tmě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kdo svého bratra miluje, zůstává v tom světle a není v něm žádné pohoršení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Kdo však svého bratra nenávidí, je ve tmě, ve tmě chodí a neví, kam jde; neboť tma oslepila jeho oči.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Píšu vám, dítky, že jsou vám odpuštěny hříchy pro jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Píšu vám, otcové, že jste poznali toho, který je od počátku; píšu vám, mládenci, že jste přemohli toho Zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Napsal jsem vám, dítky, že jste poznali Otce; napsal jsem vám, otcové, že jste poznali toho, který je od počátku; napsal jsem vám, mládenci, že jste silní a slovo Boží ve vás zůstává, a přemohli jste toho Zlého.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Nemilujte svět ani to, co je ve světě. Jestliže někdo miluje svět, není v něm ⌈Otcova láska⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Neboť všechno, co je ve světě -- žádost těla, žádost očí a ⌈prázdná chlouba života⌉ -- není z Otce, ale ze světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'A svět pomíjí i jeho žádost; kdo však činí vůli Boží, zůstává ⌈na věčnost⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Dítky, je poslední hodina; a jak jste slyšeli, že přichází Antikrist, tak se nyní již objevilo mnoho antikristů; podle toho poznáváme, že je poslední hodina.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Vyšli z nás, ale nebyli z nás. Kdyby byli z nás, zůstali by s námi. Ale to se stalo, aby ⌈vyšlo najevo⌉, že nejsou všichni z nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Vy však máte pomazání od toho Svatého a ⌈víte to všichni⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Nenapsal jsem vám proto, že neznáte pravdu, ale proto, že ji znáte a víte, že žádná lež není z pravdy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kdo je lhář, ne–li ten, kdo popírá, že Ježíš je Kristus? To je ten antikrist, který popírá Otce i Syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Každý, kdo popírá Syna, nemá ani Otce. Kdo vyznává Syna, má i Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Ať ve vás zůstává⌈, co jste slyšeli od počátku. Zůstane–li ve vás to, co jste slyšeli od počátku⌉, zůstanete také vy v Synu a v Otci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'A toto je to zaslíbení, které nám on zaslíbil: věčný život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Toto jsem vám napsal o těch, kteří vás svádějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Ve vás však zůstává pomazání, které jste od něho přijali, a nepotřebujete, aby vás někdo učil; jeho pomazání vás učí všemu a je pravdivé a neklame; jak vás vyučilo, tak zůstávejte v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Nyní tedy, dítky, zůstávejte v něm, abychom nabyli radostné důvěry, až se zjeví, a nebyli jím zahanbeni při jeho příchodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Víte–li, že je spravedlivý, vězte, že také každý, kdo činí spravedlnost, je z něho zrozen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Pohleďte, jakou lásku nám Otec dal, abychom byli nazváni Božími dětmi; a také jimi jsme. Proto nás svět nezná, neboť nepoznal jeho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Milovaní, nyní jsme děti Boží; a ještě se neukázalo, co budeme. Víme však, že až se zjeví, budeme mu podobni, protože ho uvidíme takového, jaký je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'A každý, kdo v něm má tuto naději, očišťuje se, tak jako on je čistý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Každý, kdo činí hřích, činí také svévoli. Hřích je svévole.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'A víte, že on se zjevil, aby odstranil [naše] hříchy, a hříchu v něm není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Žádný, kdo v něm zůstává, nehřeší. Žádný, kdo hřeší, ho neviděl ani nepoznal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Dítky, ať vás nikdo nesvádí. Kdo činí spravedlnost, je spravedlivý, tak jako on je spravedlivý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Kdo činí hřích, je z Ďábla, neboť Ďábel hřeší od počátku. Proto se zjevil Syn Boží, aby zmařil skutky Ďáblovy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Žádný, kdo je narozen z Boha, nečiní hřích, protože v něm zůstává Boží símě; a nemůže hřešit, protože se narodil z Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Podle toho ⌈se poznají⌉ děti Boží a děti Ďáblovy: žádný, kdo nečiní spravedlnost a kdo nemiluje svého bratra, není z Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Neboť to je ta zvěst, kterou jste slyšeli od počátku: abychom se navzájem milovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Ne jako Kain, který byl ze Zlého a zabil svého bratra. A proč ho zabil? Protože jeho vlastní skutky byly zlé, kdežto skutky jeho bratra byly spravedlivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Nedivte se, bratři, když vás svět nenávidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'My víme, že jsme přešli ze smrti do života, neboť milujeme bratry; kdo nemiluje [bratra], zůstává ve smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Každý, kdo nenávidí svého bratra, je vrah; a víte, že žádný vrah nemá věčný život, který by v něm zůstával.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, '⌈Podle toho⌉ jsme poznali lásku, že on za nás položil svou duši. I my jsme povinni položit své duše za bratry.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Má–li však někdo dostatek v tomto světě a vidí, že jeho bratr má nouzi, a zavře před ním své srdce, jak v něm může zůstávat Boží láska?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Dítky, nemilujme slovem ani jazykem, ale v skutku a v pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, '⌈Podle toho⌉ poznáme, že jsme z pravdy, a tak před ním upokojíme své srdce,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'i když by nás naše srdce odsuzovalo; neboť Bůh je větší než naše srdce a zná všechno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Milovaní, jestliže nás srdce neodsuzuje, máme ⌈radostnou důvěru k Bohu⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'a oč bychom žádali, dostáváme od něho, protože zachováváme jeho přikázání a činíme to, co se jemu líbí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'A toto je jeho přikázání, abychom uvěřili jménu jeho Syna Ježíše Krista a navzájem se milovali, jak nám přikázal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Kdo zachovává jeho přikázání, zůstává ⌈v Bohu a Bůh⌉ v něm; že v nás zůstává, poznáváme podle Ducha, kterého nám dal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Milovaní, nevěřte každému duchu, ale zkoumejte duchy, jsou–li z Boha; neboť do světa vyšlo mnoho falešných proroků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Podle toho poznávejte Ducha Božího: Každý duch, který vyznává Ježíše Krista, jenž přišel v těle, je z Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'A žádný duch, který nevyznává Ježíše [Krista, jenž přišel v těle], není z Boha. To je ten duch Antikrista, o němž jste slyšeli, že přichází, a který již nyní je ve světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Vy, dítky,jste z Boha a přemohli jste je, neboť ten, který je ve vás, je větší než ten, který je ve světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Oni jsou ze světa, proto mluví věci ze světa a svět jim naslouchá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'My jsme z Boha; kdo zná Boha, naslouchá nám, kdo není z Boha, nenaslouchá nám. Podle toho poznáváme Ducha pravdy a ducha bludu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Milovaní, milujme se navzájem, neboť láska je z Boha, a každý, kdo miluje, se z Boha narodil a Boha zná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kdo nemiluje, nepoznal Boha, protože Bůh je láska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'V tom ⌈se ukázala Boží láska k nám⌉, že Bůh na svět poslal svého Syna, toho jediného, abychom skrze něho měli život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'V tom je láska: ne že my jsme si zamilovali Boha, ale že on miloval nás a poslal svého Syna jako oběť smíření za naše hříchy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Milovaní, jestliže Bůh takto miloval nás, i my se máme navzájem milovat.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Boha nikdo nikdy neviděl. Jestliže se milujeme navzájem, Bůh v nás zůstává a jeho láska v nás ⌈dosáhla svého cíle⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Že zůstáváme v něm a on v nás, poznáváme ⌈podle toho⌉, že nám dal ze svého Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'A my jsme viděli a dosvědčujeme, že Otec poslal Syna, Zachránce světa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Kdo by vyznal, že Ježíš je Syn Boží, v tom zůstává Bůh a on v Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'A my jsme uvěřili a poznali lásku, kterou Bůh má k nám. Bůh je láska, a kdo zůstává v lásce, zůstává v Bohu a Bůh v něm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'V tom ⌈dosáhla láska při nás cíle⌉, že máme naprostou důvěru pro den soudu, neboť jaký je on, takoví jsme i my v tomto světě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'V lásce není strach, ale dokonalá láska strach zahání; vždyť strach ⌈působí muka⌉, a kdo se bojí, nedošel dokonalosti v lásce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'My milujeme, neboť on první miloval nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Řekne–li někdo: Miluji Boha, a přitom nenávidísvého bratra, je lhář. Vždyť kdo nemiluje svého bratra, kterého viděl, nemůže milovat Boha, kterého neviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'A toto přikázání máme od něho, aby ten, kdo miluje Boha, miloval také svého bratra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Každý, kdo věří, že Ježíš je Kristus, je zrozen z Boha. A každý, kdo miluje Otce, miluje i ⌈jeho dítě⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, '⌈Podle toho⌉ poznáváme, že milujeme Boží děti, když milujeme Boha a plníme jeho přikázání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'To je totiž láska ⌈ k Bohu⌉, že zachováváme jeho přikázání. A jeho přikázání nejsou těžká,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'neboť vše, co se narodilo z Boha, přemáhá svět. A to je to vítězství, které přemohlo svět: naše víra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kdo je ten, který přemáhá svět, ne–li ten, kdo věří, že Ježíš je Syn Boží?');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'To je ten, který přišel skrze vodu a krev: Ježíš Kristus. Ne pouze ve vodě, ale ve vodě a v krvi. A Duch je ten, který to dosvědčuje, neboť Duch je pravda.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Tři jsou, kteří vydávají svědectví [na nebi -- Otec, Slovo a Duch Svatý -- a ti tři jsou jedno].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, '[A jsou tři, kteří vydávají svědectví na zemi] -- Duch, voda a krev --, a ti tři jsou zajedno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Přijímáme–li svědectví lidí, oč větší je svědectví Boží. Toto je Boží svědectví, protože on sám vydal svědectví o svém Synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kdo věří v Syna Božího, má to svědectví v sobě. Kdo nevěří Bohu, učinil ho lhářem, protože neuvěřil svědectví, které Bůh vydal o svém Synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'A to je to svědectví: Bůh nám dal věčný život a ten život je v jeho Synu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kdo má Syna, má život; kdo nemá Syna Božího, ten život nemá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Toto jsem napsal vám, kteří věříte ve jméno Syna Božího, abyste věděli, že máte věčný život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'A to je ta naprostá důvěra, kterou máme k němu, že když bychom o něco žádali podle jeho vůle, slyší nás.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'A víme–li, že nás slyší, kdykoli o něco žádáme, víme, že máme ⌈to, co⌉ jsme od něho žádali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Uviděl–li by někdo svého bratra, že hřeší hříchem, který ne ní k smrti, ať za něj poprosí, a Bůh mu dá život; těm, kdo nehřeší k smrti. Je hřích k smrti; u takového neříkám, aby prosil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Každá nepravost je hřích, ale je i hřích, který ne ní k smrti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Víme, že kdo je narozen z Boha, nehřeší; ale ten, kdo byl zplozen z Boha, střeží ⌈sebe samého⌉ a ten Zlý se ho nedotýká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Víme, že jsme z Boha a celý svět leží v tom Zlém.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Víme, že Syn Boží přišel a dal nám schopnost poznávat toho pravého, a jsme v tom pravém, v jeho Synu Ježíši Kristu. On je ten pravý Bůh a věčný život.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Dítky,uchraňte se model! [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Já starší píšu vyvolené paní a jejím dětem, které miluji v pravdě-- a nejen já, nýbrž všichni, kteří poznali pravdu --,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'a to pro pravdu, která zůstává v nás a bude s námi ⌈na věčnost⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Bude s námi ⌈milost, milosrdenství a pokoj od Boha Otce⌉ a od [Pána] Ježíše Krista, Syna Otcova, v pravdě a lásce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Velice jsem se zaradoval, že jsem mezi tvými dětmi nalezl takové, které chodí v pravdě podle přikázání, které jsme dostali od Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'A nyní tě prosím, paní -- ne že bych ti psal nové přikázání, nýbrž to, které jsme měli od počátku --, abychom milovali jedni druhé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'A to je ta láska: abychom chodili podle jeho přikázání. To je to přikázání, o kterém jste od počátku slyšeli, že v něm máte chodit.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Neboť do světa vyšli mnozí svůdci, kteří nevyznávají Ježíše Krista přicházejícího v těle; ⌈každý takový člověk je⌉ svůdce a antikrist.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Dávejte si pozor, ⌈abyste nepřišli o to, na čem jsme pracovali, ale abyste dostali⌉ plnou odměnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Každý, kdo ⌈zachází dále⌉ a nezůstává v učení Kristově, nemá Boha; kdo zůstává v učení [Kristově], má i Otce i Syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Přichází–li někdo k vám a nepřináší toto učení, nepřijímejte ho do domu ⌈ani ho nezdravte⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'kdo ho zdraví, má účast na jeho zlých skutcích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Ačkoliv vám mám mnoho co psát, nechtěl jsem to učinit prostřednictvím papíru a inkoustu.Ale doufám, že ⌈se k vám dostanu⌉ a promluvím s vámi tváří v tvář, aby naše radost byla úplná.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Pozdravují tě děti tvé vyvolené sestry. [Amen.]');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Já starší milovanému Gaiovi, jehož miluji v pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Milovaný, modlím se, abys ve všem prospíval a byl zdráv, tak jako prospívá tvá duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, '[Neboť] jsem se velice zaradoval, když přicházeli bratři a vydávali svědectví ⌈ o tom, že stojíš v pravdě⌉, a o tom, jak chodíš v pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Nemám větší radost, než když slyším, že mé děti chodí v pravdě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Milovaný, věrně činíš ve všem, co konáš pro bratry, a zvláště pro cizí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Oni vydali před církví svědectví o tvé lásce. Dobře učiníš, vypravíš–li je, jak je důstojno Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Neboť pro jeho jméno ⌈se vydali na cestu⌉ a od pohanů nic nepřijímají.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'My jsme povinni se takových ujímat, abychom se stávali spolupracovníky pro pravdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, '[Něco] jsem již tomu sboru napsal, ale Diotrefés, který chce být první z nich, nás nepřijímá.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Proto jestliže přijdu, připomenu jeho skutky, které činí, když nás pomlouvá zlými slovy, a že ani na tom nemá dost, ale sám bratry nepřijímá, a těm, kdo je chtějí přijmout, brání a vylučuje je ze sboru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Milovaný, nenapodobuj zlé, ale dobré. Kdo činí dobře, je z Boha; kdo činí zle, Boha neviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demétriovi všichni vydali dobré svědectví, i sama pravda; i my mu vydáváme svědectví a víš, že naše svědectví je pravdivé.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Měl bych ti ještě mnoho co napsat, ale nechci ti psát inkoustem a perem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Doufám však, že tě brzo uvidím a že budeme spolu mluvit ⌈tváří v tvář⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Pokoj tobě. Pozdravují tě přátelé. Pozdravuj přátele, ⌈každého zvlášť⌉!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Juda, otrok Ježíše Krista a bratr Jakubův, povolaným, kteří jsou milovaní v Bohu Otci a zachovávaní pro Ježíše Krista:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Kéž se vám rozhojní milosrdenství, pokoj a láska.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Milovaní, když jsem vynakládal všechnu píli, abych vám psal o [naší] společné záchraně, ⌈pokládal jsem za nutné⌉ vám napsat povzbuzení, abyste vytrvale zápasili o víru, která byla jednou provždy svěřena svatým.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Neboť se vloudili někteří lidé, ⌈kteří jsou dávno předem zapsáni k tomu odsouzení⌉, bezbožní, kteří milost našeho Boha proměňují v bezuzdnost a zapírají našeho jediného vládce a Pána, Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Chci vám připomenout, i když to všechno ⌈víte, že Pán, ač jednou⌉ lid z egyptské země zachránil, podruhé ty, kteří neuvěřili, zahubil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'A anděly, kteří nezachovali své knížectví, ale opustili vlastní příbytek, zachovává ve věčných poutech pod mrákotou k soudu velikého dne.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Podobně Sodoma a Gomora a okolní města, která stejným způsobem jako oni plně propadla smilstvu a ⌈odešla za jiným tělem⌉, jsou předložena jako příklad, když nesou trest věčného ohně.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Stejně i tito ⌈ve svém snění⌉ poskvrňují tělo, neuznávají autoritu, rouhají se slávám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Vždyť ani archanděl Michael, když se s Ďáblem přel o Mojžíšovo tělo, si nedovolil vynést potupný soud, nýbrž řekl: Kéž tě napomene Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Tito se však rouhají věcem, které neznají, a v těch, které jako nerozumná zvířata přirozeně znají, propadají zhoubě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Běda jim, neboť se vydali cestou Kainovou, ⌈vrhli se do bludu⌉ Balaámovy mzdy a zahynuli vzpourou Kore.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Tito jsou poskvrnami na vašich hodech lásky, když s vámi bezostyšně hodují a ⌈pasou sami sebe⌉; jsou jako oblaky bez vody, které jsou hnány větry, stromy na sklonku podzimu, bez ovoce, dvakrát zemřelé, vykořeněné;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'divoké mořské vlny, které jako pěnu vyvrhují své hanebnosti, bloudící hvězdy, jimž je mrákota tmy zachována na věčnost.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'O nich také prorokoval Henoch, sedmý od Adama, když řekl: Hle, Pán přišel s desetitisíci svých svatých,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'aby vykonal soud nade všemi a aby usvědčil každého ze všech skutků bezbožnosti, které bezbožně spáchali, a ze všech tvrdých slov, které proti němu promluvili bezbožní hříšníci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Tito jsou reptalové, nespokojenci, ⌈kteří žijí⌉ podle svých vlastních žádostí, jejich ústa honosně mluví a lichotí lidem kvůli vlastnímu prospěchu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Vy však, milovaní, pamatujte na slova předpověděná od apoštolů našeho Pána Ježíše Krista.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Říkali vám: Na konci času budou posměvači, ⌈kteří budou žít⌉ podle svých vlastních bezbožných žádostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'To jsou ti, kteří ⌈vytvářejí rozdělení⌉, lidé duševní, kteří nemají Ducha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Vy však, milovaní, budujte se ve své nejsvětější víře, modlete se v Duchu Svatém,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'zachovejte se v Boží lásce a očekávejte milosrdenství našeho Pána Ježíše Krista k věčnému životu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'A ⌈nad některými, kteří pochybují, se slitovávejte⌉,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'některé zachraňujte, vytrhujíce je z ohně, a nad některými se slitovávejte v bázni, majíce v nenávisti i košili poskvrněnou od těla.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Nyní tomu, kdo je mocen vás zachovat bez klopýtnutí a postavit bezúhonné s veselím před svou slávu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'jedinému [moudrému] Bohu, našemu Zachránci skrze Ježíše Krista, našeho Pána, jemu buď sláva, velebnost, vláda i pravomoc před veškerým časem, i nyní, i po všechny věky [věků]. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Zjevení Ježíše Krista, které mu dal Bůh, aby svým otrokům ukázal, co se má brzy stát. ⌈ On to prostřednictvím svého anděla⌉ naznačil svému otroku Janovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Ten dosvědčil Boží slovo a svědectví Ježíše Krista, vše, co uviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Blahoslavený, kdo předčítá, i ti, kdo slyší slova tohoto proroctví a zachovávají, co je v něm zapsáno, neboť ten čas je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jan sedmi sborům v Asii: Milost vám a pokoj od ⌈Toho, který jest a který byl a který přichází⌉, i od sedmi duchů, kteří jsou před jeho trůnem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'a od Ježíše Krista, jenž je věrný svědek, prvorozený z mrtvých a vládce králů země. Tomu, jenž nás miluje a svou krví ⌈nás rozvázal z⌉ našich hříchů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'a učinil nás královstvím, kněžími svému Bohu a Otci -- jemu sláva i moc na věky [věků]. Amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Hle, přichází s oblaky a uzří jej každé oko, i ti, kteří jej probodli, a budou se pro něho bít v prsa všechny kmeny země. Ano, amen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Já jsem Alfa i Omega, [počátek i konec,] praví Pán Bůh, Ten, který jest a který byl a který přichází, ten Všemohoucí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Já Jan, váš bratr a spoluúčastník soužení, království a vytrvalosti ⌈v Ježíši Kristu⌉, jsem se ocitl pro Boží slovo a svědectví Ježíše [Krista] na ostrově zvaném Patmos.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'V den Páně jsem se ocitl v Duchu a uslyšel jsem za sebou ⌈mocný hlas⌉ jako zvuk polnice,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'který říkal: „Co vidíš, napiš do svitku a pošli sedmi sborům: Do Efesu, do Smyrny, do Pergama, do Thyatir, do Sard, do Filadelfie a do Laodiceje.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Obrátil jsem se, abych viděl hlas, který se mnou mluvil. A když jsem se obrátil, spatřil jsem sedm zlatých svícnů');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'a uprostřed těch svícnů někoho jako Syna člověka, oděného dlouhým rouchem a přepásaného zlatým pásem až k prsům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Jeho hlava a vlasy byly bílé jako bílá vlna, jako sníh, jeho oči jako plamen ohně;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'jeho nohy podobné bronzu rozžhavenému v peci a jeho hlas jako zvuk mnohých vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'A ve své pravici měl sedm hvězd a z jeho úst vycházel ostrý dvousečný meč a jeho tvář jako když slunce září ve své síle.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Když jsem jej spatřil, padl jsem k jeho nohám jako mrtvý. I položil na mne svou pravici a řekl: „Neboj se. Já jsem první i poslední,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'ten Živý. Byl jsem mrtvý, a hle, žiji na věky věků. [Amen.] Mám klíče smrti i podsvětí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Napiš tedy ty věci, které jsi uviděl, a ty, které jsou, a ty, které se mají stát po nich.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Tajemství těch sedmi hvězd, které jsi spatřil na mé pravici, i těch sedmi zlatých svícnů: Sedm hvězd jsou andělé sedmi sborů, sedm svícnů je sedm sborů.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '„Andělu sboru v Efesu napiš: Toto praví ten, který pevně drží těch sedm hvězd ve své pravici, který se prochází uprostřed těch sedmi zlatých svícnů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Znám tvé skutky, [tvou] námahu i tvou vytrvalost; vím, že nemůžeš snést zlé lidi a vyzkoušel jsi ty, kteří se nazývají apoštoly, ale nejsou, a shledal jsi, že jsou lháři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Máš vytrvalost a snášel jsi těžkosti pro mé jméno, a nezemdlel jsi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Ale to mám proti tobě, že jsi opustil svou první lásku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Rozpomeň se, odkud jsi spadl, ⌈učiň pokání⌉ a ⌈začni jednat jako dřív⌉! Ne–li, přijdu k tobě [brzy] a pohnu tvým svícnem z jeho místa; jestliže neučiníš pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'To však máš k dobru, že nenávidíš skutky Nikolaitů, které i já nenávidím.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kdo má ⌈uši, slyš⌉, co Duch praví sborům: Tomu, kdo vítězí, dám jíst ze stromu života, který je v Božím ráji.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Andělu sboru ve Smyrně napiš: Toto praví ten první a poslední, který byl mrtev a ožil:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Znám tvé soužení a chudobu, ale jsi bohatý. Znám i urážení od těch, kteří sami o sobě říkají, že jsou Židé, ale nejsou, nýbrž jsou synagogou Satanovou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Neboj se toho, co máš trpět. Hle, Ďábel se chystá některé z vás dávat do vězení, abyste byli vyzkoušeni, a budete mít soužení po deset dní. Buď věrný až na smrt, a dám ti věnec života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kdo má ⌈uši, slyš⌉, co Duch praví sborům: Kdo vítězí, tomu druhá smrt neublíží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Andělu sboru v Pergamu napiš: Toto praví ten, který má ostrý dvousečný meč:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Vím, kde bydlíš: tam, kde je trůn Satanův; avšak pevně držíš mé jméno a nezapřel jsi mou víru [ani] ve dnech, [v nichž] můj věrný svědek Antipas byl zabit u vás, kde bydlí Satan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Ale mám několik věcí proti tobě. Že tam máš lidi, kteří drží učení Balaámovo, který učil Baláka položit nástrahu před syny Izraele, aby jedli maso obětované modlám a smilnili;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'tak i ty máš některé, ⌈kteří stejně drží učení Nikolaitů⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Učiň tedy pokání! Ne–li, ⌈brzy k tobě přijdu⌉ a budu s nimi válčit mečem svých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kdo má ⌈uši, slyš⌉, co Duch praví sborům: Tomu, kdo vítězí, dám skrytou manu a dám mu bílý kamének a na tom kaménku napsané nové jméno, které nezná nikdo, než ten, kdo je dostává.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Andělu sboru v Thyatirech napiš: Toto praví Syn Boží, který má oči jako plamen ohně a nohy podobné bronzu:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Znám tvé skutky a tvou lásku, věrnost a službu, tvou vytrvalost a tvé poslední skutky, hojnější než ty první.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Ale to mám proti tobě, že trpíš ženu Jezábel, která si říká prorokyně, vyučuje a svádí mé otroky, aby smilnili a jedli maso obětované modlám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Dal jsem jí čas k pokání, ale ona se nechce odvrátit od svého smilstva.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Hle, ⌈uvrhnu ji na lůžko⌉ a ty, kteří s ní cizoloží, do velkého soužení, jestliže se od jejích činů neodvrátí;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'a její děti zahubím. A všechny sbory poznají, že já jsem ten, který zkoumá ledví i srdce, a každému z vás odplatím podle vašich skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Vám ostatním v Thyatirech, kteří nemáte toto učení, kteří jste, jak oni říkají, nepoznali hluboké věci Satanovy, pravím: Nekladu na vás jiné břemeno;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'pouze držte pevně, co máte, dokud nepřijdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Kdo vítězí a zachovává moje skutky až do konce, tomu dám vládu nad národy;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'bude je pást železnou berlou a budou rozbíjeny jako hliněné nádobí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'jak jsem to i já přijal od svého Otce. A dám mu hvězdu jitřní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kdo má ⌈uši, slyš⌉, co Duch praví sborům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Andělu sboru v Sardách napiš: Toto praví ten, který má sedm duchů Božích a sedm hvězd: Znám tvé skutky; máš jméno, že žiješ, ale jsi mrtvý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Buď bdělý a upevni to, co ještě zbývá ⌈a je⌉ na umření, neboť jsem nenalezl tvé skutky úplné před mým Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Připomínej si, jak jsi mé slovo přijal a slyšel, zachovávej je a učiň pokání. ⌈Neprobudíš–li se⌉, přijdu jako zloděj, a nebudeš vědět, v kterou hodinu na tebe přijdu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Máš však v Sardách několik osob, které neposkvrnily svá roucha; ti budou se mnou chodit v bílých šatech, protože jsou toho hodni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Kdo vítězí, takto se bude oblékat do bílých šatů a jeho jméno nevymažu z knihy života, nýbrž vyznám je před svým Otcem a před jeho anděly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kdo má ⌈uši, slyš⌉, co Duch praví sborům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Andělu sboru ve Filadelfii napiš: Toto praví ten Svatý, ten Pravý, který má klíč Davidův; když on otevírá, nikdo nezavře, a když on zavírá, nikdo neotevře:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Znám tvé skutky. Hle, postavil jsem před tebou otevřené dveře, které nemůže nikdo zavřít. Neboť máš malou moc, a přece jsi zachoval mé slovo a nezapřel jsi mé jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Hle, dávám ti ze synagogy Satanovy ty, kdo o sobě říkají, že jsou Židé, a nejsou, ale lžou. Hle, způsobím, že přijdou a pokloní se před tvýma nohama; a poznají, že já jsem si tě zamiloval.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Protože jsi zachoval ⌈slovo mé vytrvalosti⌉, i já zachovám tebe v hodině zkoušky, která má přijít na celý obydlený svět, aby vyzkoušela obyvatele země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, '⌈Přijdu brzy⌉. Drž pevně, co máš, aby ti nikdo nevzal věnec vítěze.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Kdo vítězí, toho učiním sloupem ve svatyni svého Boha a již nikdy nevyjde ven. Napíšu na něj jméno svého Boha a jméno města svého Boha, nového Jeruzaléma, který sestupuje z nebe od mého Boha, i své nové jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kdo má ⌈uši, slyš⌉, co Duch praví sborům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Andělu sboru v Laodiceji napiš: Toto praví Amen, svědek věrný a pravý, původ Božího stvoření:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Znám tvé skutky; nejsi studený ani horký. Kéž bys byl studený nebo horký!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Takto však, že jsi vlažný, a ne jsi studený ani horký, vyvrhnu tě ze svých úst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Neboť říkáš: Jsem bohatý, zbohatl jsem, nic nepotřebuji. A nevíš, že jsi ubohý, politováníhodný a chudý, slepý a nahý.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Radím ti, abys ode mne koupil zlato v ohni pročištěné, a tak zbohatl, bílé šaty, aby ses oblékl a neukázala se hanba tvé nahoty, a mast k pomazání svých očí, abys viděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Já usvědčuji a kárám ty, které miluji; buď tedy horlivý a učiň pokání.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Hle, stojím u dveří a tluču; kdo by uslyšel můj hlas a otevřel dveře, k tomu vejdu a budu s ním večeřet a on se mnou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Kdo vítězí, tomu dám usednout se mnou na můj trůn, jako i já jsem zvítězil a usedl se svým Otcem na jeho trůn.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kdo má ⌈uši, slyš⌉, co Duch praví sborům. “');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Potom jsem uviděl: Hle, otevřené dveře v nebi, a ten první hlas, který jsem uslyšel jako zvuk polnice mluvící se mnou, říkal: „Vystup sem a ukážu ti, co se má stát potom.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Ihned jsem se ocitl v Duchu. A hle, v nebi stál trůn a na tom trůnu někdo seděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'A ten, kdo na něm seděl, byl na pohled jako kámen jaspis a karneol; a kolem trůnu duha na pohled jako smaragd.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Okolo toho trůnu čtyřiadvacet jiných trůnů a na těch trůnech sedělo čtyřiadvacet starších, oblečených do bílých šatů a na hlavách zlaté věnce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Z trůnu vycházely blesky, hlasy a hromy. Před trůnem hořelo sedm ohnivých pochodní, to jest sedm duchů Božích.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'A před trůnem bylo něco jako skelné moře, podobné křišťálu. Uprostřed trůnu a kolem trůnu čtyři živé bytosti plné očí zpředu i zezadu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'První bytost byla podobná lvu, druhá bytost byla podobná býku, třetí bytost měla tvář jako člověk a čtvrtá bytost byla podobná letícímu orlu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Ty čtyři živé bytosti měly každá po šesti křídlech, dokola i uvnitř plno očí. A bez přestání dnem i nocí říkají: „Svatý, svatý, svatý Pán, Bůh Všemohoucí, ten, který byl a který jest a který přichází.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'A kdykoli ty živé bytosti vzdají slávu a čest a díky Sedícímu na trůnu, Žijícímu na věky věků,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'padne těch čtyřiadvacet starších před Sedícím na trůnu a pokloní se Žijícímu na věky věků; pak hodí své věnce vítězů před trůn a říkají:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '„Hoden jsi, Pane a Bože náš, [Svatý,] přijmout slávu a úctu i moc, neboť ty jsi stvořil všechny věci, z tvé vůle existovaly a byly stvořeny.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'A na pravici Sedícího na trůnu jsem spatřil svitek popsaný zevnitř i zvenčí, zapečetěný sedmi pečetěmi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'A uviděl jsem silného anděla, který hlásal mocným hlasem: „Kdo je hoden otevřít ten svitek a rozlomit jeho pečetě?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'A nikdo v nebi ani na zemi ani pod zemí nemohl otevřít ten svitek a dívat se do něho.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Velmi jsem plakal, že se nenašel nikdo, kdo by byl hoden svitek otevřít a dívat se do něj.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Ale jeden ze starších mi říká: „Neplač. Hle, zvítězil lev, ten z kmene Judova, kořen Davidův, aby otevřel ten svitek a jeho sedm pečetí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'A tu jsem spatřil, že uprostřed trůnu a těch čtyř živých bytostí a uprostřed těch starších stál Beránek jako zabitý; měl sedm rohů a sedm očí, což jest sedm duchů Božích, vyslaných do celé země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'I přišel a vzal ten svitek z pravice sedícího na trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'A když ho vzal, čtyři živé bytosti i čtyřiadvacet starších padlo před Beránkem; každý měl harfu a zlaté misky plné kadidel, což jsou modlitby svatých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'A zpívají novou píseň: „Jsi hoden vzít ten svitek a otevřít jeho pečeti, protože jsi byl zabit a svou krví jsi vykoupil Bohu lidi z každého kmene, jazyka, lidu a národu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'a učinil jsi je králi a kněžími našemu Bohu; a ⌈budou kralovat⌉ na zemi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'I uviděl jsem a uslyšel jsem hlas mnoha andělů okolo trůnu a těch živých bytostí a těch starších, jejich počet byl desetitisíce desetitisíců a tisíce tisíců,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'a říkali mocným hlasem: „Hoden jest Beránek, ten zabitý, přijmout tu moc a bohatství, moudrost, sílu a úctu, slávu a dobrořečení.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'A všechno stvoření, které [je] v nebi, na zemi, pod zemí i na moři, všechno, co je v nich, jsem slyšel volat: „Tomu, jenž sedí na trůnu, a Beránkovi dobrořečení, úcta, sláva i moc na věky věků!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'A ty čtyři živé bytosti říkaly: „Amen.“A starší padli na tvář a poklonili se.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'I uviděl jsem, když Beránek otevřel jednu ze sedmi pečetí, a uslyšel jsem, jak jedna z těch čtyř živých bytostí řekla hromovým hlasem: „Pojď!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, '[A uviděl jsem,] a hle, bílý kůň; a ten, který na něm seděl, měl luk a byl mu dán věnec; a vyšel vítězící, a aby zvítězil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Když otevřel druhou pečeť, uslyšel jsem, jak ta druhá živá bytost řekla: „Pojď!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'A vyšel jiný kůň, ohnivě rudý; a tomu, kdo na něm seděl, bylo dáno, aby vzal ze země pokoj a aby se lidé navzájem zabíjeli; a byl mu dán veliký meč.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'A když otevřel třetí pečeť, uslyšel jsem, jak třetí živá bytost řekla: „Pojď!“[A uviděl jsem,] a hle, černý kůň; a ten, který na něm seděl, měl ve své ruce vahadlo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'A uslyšel jsem cosi jako hlas uprostřed těch čtyř živých bytostí, který řekl: „Mírka pšenice za denár a tři mírky ječmene za denár. Olej a víno nezdražuj.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'A když otevřel čtvrtou pečeť, uslyšel jsem hlas čtvrté živé bytosti, jak řekla: „Pojď!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, '[A uviděl jsem,] a hle, kůň plavý; a jméno toho, který na něm seděl, bylo Smrt,a Hádes ho doprovázel. Byla jim dána moc nad čtvrtinou země, aby zabíjeli mečem, hladem, smrtí a šelmami země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'A když otevřel pátou pečeť, spatřil jsem pod oltářem duše zabitých pro Boží slovo a pro svědectví, které ⌈ věrně drželi⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'A ti zvolali mocným hlasem: „Jak dlouho ještě, Panovníku, svatý a pravý, nebudeš soudit a trestat za naši krev ty, kdo bydlí na zemi?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'A každému z nich bylo dáno bílé roucho a bylo jim řečeno, ať odpočinou ještě krátký čas, dokud se nenaplní počet jejich spoluotroků a jejich bratrů, kteří mají být zabíjeni jako oni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'A když otevřel šestou pečeť, uviděl jsem, že nastalo veliké země třesení, slunce zčernalo jako žíněný pytel a měsíc úplně zkrvavěl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'A nebeské hvězdy spadly na zem, jako když fíkovník zmítaný vichrem shazuje své pozdní fíky;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'a nebe zmizelo, jako když se svinuje svitek, a každá hora i každý ostrov se pohnuly ze svého místa.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Králové země i velmoži a vojevůdci, boháči a mocní, každý otrok i svobodný, se ukryli do jeskyň a do horských skal');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'a říkali těm horám a skalám: „Padněte na nás a skryjte nás před tváří toho, který sedí na trůnu, a před hněvem Beránka!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Neboť přišel veliký den jejich hněvu; kdo bude moci obstát?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Potom jsem uviděl čtyři anděly stát na čtyřech úhlech země a držet čtyři zemské větry, aby vítr nevál na zemi ani na moře ani na žádný strom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'A uviděl jsem jiného anděla, jak vystupuje od východu slunce a má pečetidlo živého Boha. Mocným hlasem zvolal na ty čtyři anděly, kterým bylo dáno škodit zemi a moři:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, '„Neškoďte zemi, moři ani stromům, dokud neoznačíme otroky našeho Boha na jejich čelech!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'A slyšel jsem počet označených: sto čtyřicet čtyři tisíce ze všech kmenů synů Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Z kmene Juda je označeno dvanáct tisíc, z kmene Rúben dvanáct tisíc, z kmene Gád dvanáct tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Z kmene Ašer dvanáct tisíc, z kmene Neftalí dvanáct tisíc, z kmene Manases dvanáct tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Z kmene Šimeón dvanáct tisíc, z kmene Lévi dvanáct tisíc, z kmene Isachar dvanáct tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Z kmene Zabulón dvanáct tisíc, z kmene Josef dvanáct tisíc a z kmene Benjamín je označeno dvanáct tisíc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Potom jsem uviděl, a hle, veliký zástup, který nikdo nemohl spočítat, ze všech národů, kmenů, ⌈jazyků a z každého lidu⌉, jak stojí před trůnem a před Beránkem, oblečeni v bílá roucha, palmové ratolesti v rukou,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'a volají velikým hlasem: „Záchrana náleží našemu Bohu, tomu, který sedí na trůnu, a Beránkovi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'A všichni andělé stáli kolem trůnu, kolem starších i těch čtyř živých bytostí, a padli před trůnem na tvář a poklonili se Bohu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, '⌈se slovy⌉: „Amen! Dobrořečení a sláva, moudrost i vděčnost, úcta a moc i síla náleží našemu Bohu na věky věků. [Amen.]“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Jeden z těch starších ⌈na mne promluvil⌉: „Kdo jsou a odkud přišli tito, kteří jsou oblečeni v bílá roucha?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Řekl jsem mu: „Můj pane, ty to víš.“A on mi řekl: „To jsou ti, kteří přicházejí z velikého soužení a svá roucha vyprali a vybílili v krvi Beránkově.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Proto jsou před Božím trůnem a slouží mu v jeho svatyni dnem i nocí; a ten, který sedí na trůnu, nad nimi roztáhne svůj stan.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Již nebudou hladovět ani žíznit, ⌈neublíží jim⌉ slunce ani jiný žár,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'neboť Beránek, který je uprostřed trůnu, je bude pást a povede je k pramenům vod života. A Bůh jim setře každou slzu z očí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'A když otevřel sedmou pečeť, nastalo v nebi ticho asi na půl hodiny.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'A uviděl jsem sedm andělů, kteří stáli před Bohem; a bylo jim dáno sedm polnic.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'A přišel jiný anděl, který měl zlatou kadidelnici, a postavil se k oltáři; bylo mu dáno množství kadidla, aby je dal s modlitbami všech svatých na zlatý oltář, který je před trůnem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'A dým kadidla spolu s modlitbami svatých vystoupil z ruky anděla před Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Tu vzal anděl kadidelnici, naplnil ji ohněm z oltáře a hodil dolů na zem; i nastaly hromy, hlasy, blesky a země třesení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'A těch sedm andělů, kteří měli sedm polnic, se připravilo, aby zatroubili.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Zatroubil první [anděl]. Nastalo krupobití a oheň smíšený s krví a bylo to svrženo na zem. Třetina země shořela, třetina stromů shořela, veškerá zelená tráva shořela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Zatroubil druhý anděl. Něco jako veliká hora hořící [ohněm] bylo vrženo do moře. Třetina moře se obrátila v krev');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'a zahynula třetina živých tvorů v moři a byla zničena třetina lodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Zatroubil třetí anděl, a z nebe spadla veliká hvězda, hořící jako pochodeň, a padla na třetinu řek a na prameny vod.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Jméno té hvězdy je Pelyněk. Třetina vod se změnila v pelyněk a mnoho lidí zemřelo z těch vod, protože zhořkly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Zatroubil čtvrtý anděl, a byla zasažena třetina slunce, třetina měsíce a třetina hvězd, takže třetina z nich ztemněla a nebylo světlo po třetinu dne a stejně i noci.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Tu jsem uviděl a uslyšel jednoho orla, jak letí ⌈prostředkem nebe⌉ a volá mocným hlasem: „Běda, běda, běda těm, kteří bydlí na zemi, pro zbývající hlasy polnic tří andělů, kteří ještě mají troubit.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Zatroubil pátý anděl. A uviděl jsem hvězdu spadlou z nebe na zem a byl jí dán klíč od jícnu bezedné propasti.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, '[Otevřela jícen bezedné propasti] a z toho jícnu vystoupil dým jako dým z veliké pece; dýmem z jícnu se zatmělo slunce i všechno ovzduší.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Z toho dýmu vyšly na zem kobylky a byla jim dána moc, jakou mají pozemští štíři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'A bylo jim řečeno, aby neškodily trávě na zemi ani žádné zeleni ani žádnému stromu, jenom lidem, kteří na čele nemají Boží pečeť.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'A bylo jim dáno, ne aby je zabíjely, nýbrž aby jim působily trýzeň po pět měsíců; jejich trýzeň byla jako trýzeň od štíra, když bodne člověka.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'V oněch dnech lidé budou hledat smrt, a nenaleznou ji, budou si přát umřít, ale smrt od nich uteče.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Vzhledem se ty kobylky podobaly koním připraveným k boji; na svých hlavách měly něco jako ⌈věnce podobné zlatu⌉, jejich tváře byly jako tváře lidí,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'vlasy měly jako vlasy žen a jejich zuby byly jako zuby lvů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Měly hrudní pancíře jako ze železa a zvuk jejich křídel jako zvuk mnoha vozů s koňmi běžícími do boje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Mají ocasy jako štíři a v nich žihadla, a v jejich ocasech je jejich moc škodit lidem po pět měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Nad sebou mají krále, anděla bezedné propasti, který se hebrejsky jmenuje Abaddon a řecky Apollyón.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'První běda pominulo; hle, ještě dvoje běda přichází potom.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Zatroubil šestý anděl. Uslyšel jsem jakýsi hlas ze [čtyř] rohů zlatého oltáře, který je před Bohem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Ten řekl šestému andělu, který měl polnici: „Rozvaž ty čtyři anděly, kteří jsou svázáni při veliké řece Eufratu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Tu byli rozvázáni ti čtyři andělé, připravení k hodině, dni, měsíci a roku, aby zabili třetinu lidí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, '⌈Vojska jejich jízdy měla⌉ ⌈dvě stě miliónů⌉ mužů -- uslyšel jsem jejich počet.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'A takto jsem ve vidění spatřil koně a ty, kteří na nich seděli: hrudní pancíře měli ohnivé, hyacintové a sírově žluté; hlavy koní jako hlavy lvů, z jejich tlam vychází oheň, dým a síra.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Těmito třemi ranami byla zabita třetina lidí: ohněm, dýmem a sírou, která vycházela z jejich tlam.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Neboť moc koní je v jejich tlamách a v jejich ocasech; jejich ocasy jsou podobné hadům: mají hlavy a těmi škodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Ale ostatní lidé, kteří nebyli těmito ranami zabiti, se neodvrátili od skutků svých rukou: nepřestali se klanět démonům a modlám ze zlata, stříbra, mědi, kamene i dřeva, které nemohou ani vidět ani slyšet ani chodit;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'neodvrátili se od svých vražd ani od svých čárů, od svého smilstva ani od svých krádeží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Tu jsem uviděl sestupovat z nebe jiného silného anděla oděného do oblaku a nad jeho hlavou byla duha; jeho tvář byla jako slunce a jeho nohy jako ohnivé sloupy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'a v ruce měl rozvinutý malý svitek. Pravou nohou se postavil na moře, levou na zem');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'a vykřikl mohutným hlasem, jako když řve lev. A když vykřikl, promluvilo svými hlasy sedm hromů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Jakmile promluvilo těch sedm hromů, chtěl jsem psát, ale uslyšel jsem hlas z nebe, který říkal: „Zapečeť, co promluvilo těch sedm hromů, a nepiš to.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'A anděl, kterého jsem viděl stát na moři i na zemi, zdvihl svou pravou ruku k nebi');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'a přísahal při tom, který je živ na věky věků, který stvořil nebe i to, co je v něm, zemi i to, co je v ní, a moře i to, co je v něm, že čas již více nebude,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'nýbrž ve dnech hlasu sedmého anděla, až bude troubit, bude dokonáno tajemství Boží, jak to ohlásil svým otrokům prorokům.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Hlas, který jsem uslyšel z nebe, se mnou opět mluvil a říkal: „Jdi, vezmi ten rozvinutý svitek, který je v ruce anděla stojícího na moři a na zemi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'I odešel jsem k tomu andělovi a řekl jsem mu, aby mi dal ten malý svitek. Řekl mi: „Vezmi jej a sněz; naplní tvé břicho hořkostí, ale v tvých ústech bude sladký jako med.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Vzal jsem ten malý svitek z ruky anděla a snědl jsem jej; v mých ústech byl sladký jako med, ale když jsem ho snědl, naplnil mé břicho hořkostí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'A řekli mi: „Musíš znovu přinést proroctví mnohým lidem, národům, jazykům i králům.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Byla mi dána třtina podobná holi se slovy: „Vstaň a změř Boží svatyni i oltář a ty, kteří se v ní klanějí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Ale vnější nádvoří svatyně vynech a neměř je, protože bylo dáno pohanům, kteří budou šlapat po svatém městě dvaačtyřicet měsíců.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'A dám pravomoc svým dvěma svědkům, a budou prorokovat tisíc dvě stě šedesát dní, oblečeni v žíněný šat.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'To jsou ty dvě olivy a ty dva svícny, které stojí před Pánem země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Bude–li jim chtít někdo ublížit, z jejich úst vyjde oheň a sežehne jejich nepřátele; kdo by jim chtěl ublížit, musí být takto usmrcen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Tito svědkové mají pravomoc zavřít nebe, aby ve dnech jejich prorocké služby nepršelo, a mají pravomoc nad vodami, aby je obraceli v krev, a aby zasáhli zemi jakoukoli ranou, kdykoli budou chtít.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'A když dokončí své svědectví, bude s nimi bojovat šelma, která vystupuje z bezedné propasti, přemůže je a zabije.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'A jejich ⌈mrtvá těla⌉ budou ležet na náměstí toho velikého města, které se duchovně nazývá Sodoma a Egypt, kde byl také ukřižován jejich Pán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Mnozí z lidí, kmenů, jazyků a národů ⌈budou hledět na⌉ jejich ⌈mrtvá těla⌉ po tři a půl dne a nedovolí je uložit do hrobu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Obyvatelé země ⌈se nad nimi budou radovat, budou jásat⌉ a navzájem si posílat dary, protože tito dva proroci trýznili obyvatele země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Ale po třech a půl dnech do nich vstoupil duch života z Boha, postavili se na nohy a na ty, kteří na ně hleděli, padl veliký strach.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Tu uslyšeli mocný hlas z nebe, který jim řekl: „Vystupte sem!“A vystoupili v oblaku do nebe a jejich nepřátelé je pozorovali.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'V tu hodinu nastalo veliké země třesení, desetina toho města se zřítila a v země třesení bylo zabito sedm tisíc lidí. Ostatní se vyděsili a vzdali slávu nebeskému Bohu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Druhé běda pominulo; hle, třetí běda rychle přichází.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Zatroubil sedmý anděl. A v nebi se ozvaly mocné hlasy, které říkaly: „Království světa se stalo královstvím našeho Pána a jeho Krista, a bude kralovat na věky věků.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Čtyřiadvacet starších, sedících na svých trůnech před Bohem, padlo na tváře a poklonilo se Bohu');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'se slovy: „Děkujeme tobě, Pane Bože, Všemohoucí, který jsi a kterýs byl, že ses chopil své veliké moci a ujal ses kralování.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Rozhněvaly se národy, ale přišel tvůj hněv, čas, aby byli souzeni mrtví a aby byla dána mzda tvým otrokům prorokům a svatým a bojícím se tvého jména, malým i velkým, a aby byli zničeni ti, kteří ničí zemi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Tu byla otevřena Boží svatyně [, která je] v nebi, a byla vidět schrána jeho smlouvy v jeho svatyni; nastaly blesky, hlasy a hromy, [země třesení] a veliké krupobití.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'A ukázalo se veliké znamení v nebi: žena oděná sluncem, pod jejíma nohama měsíc a na její hlavě koruna z dvanácti hvězd.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Byla těhotná a křičela, když v bolestech a mukách pracovala ku porodu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'A ukázalo se jiné znamení v nebi: hle, veliký rudý drak, mající sedm hlav a deset rohů, a na těch hlavách sedm diadémů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Jeho ocas vlekl třetinu nebeských hvězd; i svrhl je na zem. A drak stál před ženou, která měla porodit, aby její dítě sežral, jakmile porodí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'A porodila syna -- muže, který má pást všechny národy železnou berlou. Vtom bylo její dítě vytrženo k Bohu a k jeho trůnu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'A žena utekla do pustiny, kde měla od Boha připravené místo, aby ji tam živili tisíc dvě stě šedesát dní.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'A v nebi nastala válka: Michael a jeho andělé museli bojovat s drakem. Drak i jeho andělé bojovali,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'ale neobstáli, a už pro ně nebylo místo v nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'A byl svržen veliký drak, ten dávný had, nazývaný Ďábel a Satan, který svádí celý obydlený svět. Byl svržen na zem a jeho andělé byli svrženi s ním.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'A uslyšel jsem mocný hlas v nebi, který říkal: „Nyní přišla záchrana, moc a kralování našeho Boha a pravomoc jeho Krista, neboť byl svržen žalobce našich bratří, který je obviňoval před naším Bohem dnem i nocí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Oni nad ním zvítězili pro krev Beránkovu a pro slovo svého svědectví; a nemilovali svou duši až na smrt.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Proto se radujte, nebesa a vy, kdo v nich přebýváte. Běda zemi a moři, neboť k vám sestoupil Ďábel s velikou zuřivostí; ví, že má málo času.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Když drak uviděl, že byl svržen na zem, začal pronásledovat ženu, která porodila toho syna.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Ale té ženě byla dána dvě křídla velikého orla, aby mohla letět do pustiny na své místo, kde ⌈skryta před hadem⌉ bude živena čas a časy a půl času.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'A had vychrlil z tlamy za ženou vodu jako řeku, aby ji strhl proudem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Ale země přispěla ženě na pomoc: země otevřela svá ústa a pohltila řeku, kterou vychrlil drak ze své tlamy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Drak se na tu ženu rozzuřil a odešel, ⌈aby rozpoutal válku proti ostatním⌉ z jejího potomstva, kteří zachovávají Boží přikázání a mají Ježíšovo svědectví.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, 'I postavil se na písku u moře.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Tu jsem uviděl, jak z moře vystupuje šelma, která měla deset rohů a sedm hlav; na svých rozích měla deset diadémů a na svých hlavách jména urážející Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Ta šelma, kterou jsem uviděl, byla podobná levhartovi, její nohy jako tlapy medvěda a její tlama jako tlama lví. A drak jí dal svou sílu, svůj trůn a velikou pravomoc.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'A jednu z jejích hlav jsem viděl jakoby raněnou k smrti, ale její smrtelná rána byla vyléčena. Celá země nad tou šelmou užasla;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'poklonili se drakovi, že dal té šelmě svou pravomoc, a poklonili se také šelmě se slovy: „Kdo je podobný té šelmě a kdo s ní může bojovat?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Byla jí dána ústa mluvící veliké věci a rouhání a byla jí dána moc, ⌈aby činila, co chce ⌉ po čtyřicet dva měsíce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'I otevřela svá ústa k rouhání se Bohu a rouhala se jeho jménu a jeho stánku, ⌈ to jest těm⌉, kteří přebývají v nebi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, '[A bylo jí dáno, ⌈aby rozpoutala válku proti⌉ svatým a aby je přemohla,] a byla jí dána moc nad každým kmenem, lidem, jazykem i národem;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'budou se jí klanět všichni obyvatelé země, jejichž jména nejsou ⌈od založení světa zapsána v knize života toho zabitého Beránka⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Má–li kdo ⌈uši, slyš⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, '⌈Kdo má jít do zajetí, půjde do zajetí; kdo má být zabit mečem⌉, [musí] být mečem zabit. Zde jest vytrvalost a víra svatých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'A uviděl jsem jinou šelmu vystupovat ze země; měla dva rohy jako beránek, ale mluvila jako drak.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Vykonává všechnu pravomoc té první šelmy v její přítomnosti. Nutí zemi a její obyvatele, aby se klaněli té první šelmě, jejíž smrtelná rána byla vyléčena.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Činí veliká znamení, takže nechá i oheň z nebe před zraky lidí sestupovat na zem,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'a svádí obyvatele země znameními, která jí bylo dáno učinit před očima šelmy. Říká obyvatelům země, aby učinili obraz šelmě, která měla ránu od meče a ožila.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'A bylo jí dáno, aby vložila ducha do obrazu té šelmy, takže obraz šelmy promluvil a způsobil, aby byli zabiti všichni, kteří se nepokloní obrazu šelmy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'A působí, aby všem, malým i velkým, bohatým i chudým, svobodným i otrokům, byl dán cejch na pravou ruku nebo na čelo');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, '[a] aby nikdo nemohl kupovat ani prodávat, leda ten, kdo má cejch: jméno šelmy nebo číslo jejího jména.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Zde je moudrost. Kdo má rozum, ať spočte číslo té šelmy. Je to číslo člověka, a jeho číslo je šest set ⌈šedesát šest⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'A uviděl jsem, hle, Beránek stál na hoře Sión a s ním sto čtyřicet čtyři tisíce těch, kdo mají na svých čelech napsáno jméno jeho i jméno jeho Otce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'A uslyšel jsem hlas z nebe jako zvuk mnohých vod a jako zvuk velikého hromu. A hlas, který jsem uslyšel, byl jako hlas harfeníků, hrajících na své harfy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Zpívali novou píseň před trůnem, před těmi čtyřmi živými bytostmi a před staršími. Nikdo se nemohl naučit té písni než těch sto čtyřicet čtyři tisíce vykoupených ze země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'To jsou ti, kteří se neposkvrnili se ženami, jsou to panici. To jsou ti, kteří následují Beránka, kamkoli jde. Ti byli vykoupeni z lidí jako prvotiny Bohu a Beránkovi.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'V jejich ústech nebyla nalezena lež; jsou bez úhony.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Tu jsem uviděl [jiného] anděla, majícího věčné evangelium, jak letí ⌈prostředkem nebe⌉, aby je zvěstoval těm, kteří přebývají na zemi, každému národu, kmenu, jazyku a lidu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Volal mocným hlasem: „Bojte se Boha a vzdejte mu slávu, neboť přišla hodina jeho soudu; pokloňte se tomu, který učinil nebe, zemi, moře i prameny vod.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'A jiný, druhý anděl ho následoval ⌈a volal⌉: „Padl, padl veliký Babylon, který napájel všechny národy vášnivým vínem svého smilstva.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'A jiný, třetí anděl je následoval ⌈a volal⌉ mocným hlasem: „Kdo se klaní šelmě a jejímu obrazu a přijímá cejch na čelo či na ruku,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'bude také pít z vína Božího rozhorlení, které je nalito neředěné v číši jeho hněvu; a bude mučen v ohni a síře před svatými anděly a před Beránkem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Dým jejich muk vystupuje na věky věků a dnem i nocí nemají odpočinutí ti, kdo se klanějí šelmě a jejímu obrazu, a ti, kdo přijímají cejch jejího jména.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Zde je vytrvalost svatých, kteří zachovávají Boží přikázání a ⌈Ježíšovu víru⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Tu jsem uslyšel hlas z nebe, který říkal: „Napiš: Blahoslavení mrtví, kteří od této chvíle umírají v Pánu!“[„Ano,“] praví Duch, „ať odpočinou od svých prací, neboť jejich skutky jdou s nimi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'A uviděl jsem, hle, bílý oblak a na oblaku sedí někdo podobný Synu člověka, na hlavě má zlatou korunu a v ruce ostrý srp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'A další anděl vyšel ze svatyně a volal mocným hlasem na toho, který seděl na oblaku: „Pošli svůj srp a začni žeň, protože přišla hodina žně a dozrála úroda země.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'A ten, který seděl na oblaku, hodil svůj srp na zem a země byla požata.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'A další anděl vyšel ze svatyně, která je v nebi, a také on měl ostrý srp.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'A jiný anděl [vyšel] z oltáře a ten měl moc nad ohněm. Mocným hlasem zvolal na toho, který měl ostrý srp: „Pošli svůj ostrý srp a skliď hrozny z vinné révy země, neboť její plody dozrály.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Tu hodil ten anděl svůj srp na zem a sklidil vinnou révu země a hrozny uvrhl do velikého lisu Božího hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'A ten lis byl stlačen venku za městem a vytekla z něj krev až po uzdy koní na vzdálenost tisíce šesti set stadií.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Tu jsem uviděl v nebi jiné veliké a podivuhodné znamení: sedm andělů, kteří měli sedm posledních ran, protože jimi je dovršen Boží hněv.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Uviděl jsem něco jako skelné moře smíšené s ohněm a ty, kteří vycházeli vítězní z moci té šelmy, z moci jejího obrazu i z moci čísla jejího jména; stáli na skelném moři, měli Boží harfy');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'a zpívali píseň Božího otroka Mojžíše a píseňBeránkovu: „Veliké a podivuhodné jsou tvé skutky, Pane Bože Všemohoucí, spravedlivé a pravdivé jsou tvé cesty, Králi národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kdo by se nebál [tebe], Pane, a neoslavoval tvé jméno? Neboť ty jediný jsi svatý; všechny národy přijdou a pokloní se před tebou, protože tvé spravedlivé soudy vyšly najevo.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Potom jsem uviděl: V nebi byla otevřena svatyně stánku svědectví');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'a ze svatyně vyšlo sedm andělů, kteří měli těch sedm ran; byli oděni lněným rouchem, čistým a zářivým, a kolem prsou měli zlaté pásy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'A jedna z těch čtyř živých bytostí dala sedmi andělům sedm zlatých misek plných hněvu Boha, toho živého na věky věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'A svatyně byla naplněna dýmem z Boží slávy a z jeho moci; nikdo nemohl vstoupit do svatyně, dokud se nedokoná sedm ran těch sedmi andělů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Tu jsem uslyšel mocný hlas ze svatyně, který těm sedmi andělům říkal: „Jděte a vylejte těch sedm misek Božího hněvu na zem.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'První z nich odešel a vylil svou misku na zem, a na lidi, kteří měli cejch šelmy a kteří se klaněli jejímu obrazu, ⌈přišly zlé a zhoubné vředy⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Druhý [anděl] vylil svou misku do moře, a ⌈změnilo se v⌉ krev jako krev mrtvého a všechna živá duše, která byla v moři, zemřela.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Třetí vylil svou misku do řek a pramenů vod, a ⌈objevila se v nich ⌉ krev.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Uslyšel jsem, jak anděl vod říká: „Spravedlivý jsi, který jsi a kterýs byl, ty Svatý, že jsi vynesl tento soud;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'neboť prolili krev svatých a proroků, a dal jsi jim pít krev. Zaslouží si to!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'A uslyšel jsem, jak oltář říká: „Ano, Pane Bože Všemohoucí, pravé a spravedlivé jsou tvé soudy.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'A čtvrtý [anděl] vylil svou misku na slunce, a bylo mu dáno, aby ožehlo lidi ohněm.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Lidé byli ožehnuti velikým žárem a proklínali jméno Boha, který měl moc nad těmito ranami, ale ⌈neobrátili se⌉, aby mu vzdali slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Pátý [anděl] vylil svou misku na trůn šelmy, a její království se zatmělo; lidé se bolestí kousali do jazyka');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'a proklínali nebeského Boha pro své bolesti a pro své vředy, ale neodvrátili se od svých skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Šestý [anděl] vylil svou misku na velikou řeku Eufrat, a její voda vyschla, aby byla připravena cesta králům od východu slunce.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'A uviděl jsem z úst draka a z úst šelmy a z úst falešného proroka vycházet tři nečisté duchy jako žáby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Jsou to duchové démonů, činící znamení; vycházejí ke králům celé obydlené země, aby je shromáždili k boji ve veliký den Boha, Všemohoucího.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Hle, přicházím jako zloděj; blahoslavený, kdo bdí a střeží své šaty, aby nechodil nahý a neviděli jeho nahotu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'I shromáždil je na místo, zvané hebrejsky Harmagedon.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Sedmý [anděl] vylil svou misku na ovzduší, a ze svatyně od trůnu vyšel mocný hlas, který řekl: „Stalo se!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'A nastaly blesky, hlasy a hromy, a nastalo veliké země třesení, jaké nebylo, co je člověk na zemi; tak veliké a silné bylo to země třesení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'A to veliké město se roztrhlo na tři díly a města národů se zřítila. A veliký Babylon byl připomenut před Bohem, a Bůh mu dal číši vína svého planoucího hněvu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, '⌈Všechny ostrovy zmizely⌉ a hory nebyly k nalezení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Veliké kroupy jako závaží padaly z nebe na lidi; a lidé prokleli Boha pro tu ránu krupobití, protože ta rána byla velmi veliká.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Tu přišel jeden ze sedmi andělů, kteří měli těch sedm misek, a promluvil se mnou: „Pojď, ukážu ti soud nad tou velikou smilnicí, která sedí na mnohých vodách,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'se kterou smilnili králové země a vínem jejího smilstva se opili obyvatelé země.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'A odnesl mne v Duchu do pustiny. Tu jsem uviděl ženu, sedící na šelmě šarlatové barvy, plné rouhavých jmen, mající sedm hlav a deset rohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Ta žena byla oděna purpurem a šarlatem a ozdobena zlatem, drahými kameny a perlami; ve své ruce měla zlatou číši plnou ohavností a nečistot ⌈svého smilstva⌉');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'a na svém čele měla napsané ⌈jméno: Tajemství, Babylon⌉, ten veliký, matka smilnic a ohavností země.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Uviděl jsem tu ženu zpitou krví svatých a krví Ježíšových svědků. Velice jsem užasl, když jsem ji uviděl.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Anděl mi řekl: „Proč jsi užasl? Já ti řeknu tajemství té ženy a šelmy, která ji nese a má sedm hlav a deset rohů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Šelma, kterou jsi viděl, byla a není; má vystoupit z bezedné propasti a jít do záhuby; a ti, kdo bydlí na zemi a jejich jméno není zapsáno od založení světa ⌈v knize⌉ života, užasnou, až uvidí, že ta šelma byla a není, a opět přijde.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Zde je třeba mysli, která má moudrost: Těch sedm hlav je sedm hor, na nichž ta žena sedí. A je sedm králů:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'pět jich padlo, jeden je, další ještě nepřišel; a až přijde, musí zůstat jen nakrátko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'A šelma, která byla a není, je tím osmým; je z těch sedmi a jde do záhuby.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Těch deset rohů, které jsi viděl, je deset králů, kteří královskou moc ještě nepřijali, ale pravomoc jako králové ⌈mají přijmout⌉ ⌈ na jednu hodinu⌉ spolu s šelmou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ti ⌈budou mít stejný⌉ úmysl a svou sílu a moc dají šelmě.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ti budou válčit s Beránkem, ale Beránek je přemůže, protože je Pán pánů a Král králů, a ti, kteří jsou s ním, jsou povolaní, vyvolení a věrní.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Ještě mi řekl: „Vody, které jsi viděl, kde ta smilnice sedí, jsou lidé a zástupy, národy a jazyky.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Těch deset rohů, které jsi viděl, i ta šelma budou nenávidět smilnici a učiní ji zpustlou a nahou, budou jíst její maso a spálí ji v ohni.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Neboť Bůh dal do jejich srdcí, aby uskutečnili jeho úmysl, ⌈jednali jednomyslně⌉ a dali šelmě svou ⌈královskou moc⌉, dokud nebudou dokonána Boží slova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'A ta žena, kterou jsi viděl, je veliké město, které má královskou moc nad králi země.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Potom jsem uviděl jiného anděla sestupovat z nebe: měl velikou pravomoc a země byla ozářena jeho slávou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Zvolal mocným hlasem: „Padl, padl veliký Babylon a stal se příbytkem démonů, vězením všech nečistých duchů a vězením každého nečistého ⌈a nenáviděného ptáka⌉;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'neboť z vášnivého vína jejího smilstva pily všechny národy, i králové země s ní smilnili a obchodníci země zbohatli z moci jejího zhýralého přepychu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Tu jsem uslyšel jiný hlas z nebe, který říkal: „Vyjděte z ní, můj lide, abyste neměli účast na jejích hříších a nedostali z jejích ran.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Neboť její hříchy dosáhly až k nebi a Bůh se rozpomenul na ⌈bezpráví, které činila⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Odplaťte jí, jako i ona odplatila vám; a odplaťte jí dvojnásobně podle jejích skutků! Do číše, kterou namíchala, namíchejte jí dvojnásob;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'nakolik oslavila sebe a užila hýření, tolik jí dejte trýzně a žalu. Neboť si ve svém srdci říká: Jsem královna, nejsem vdova a jistě ⌈mne nepotká⌉ žal.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Proto v jednom dni přijdou její rány: smrt, žal a hlad, a bude spálena ohněm. Protože silný je Pán Bůh, který ji soudí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'I budou nad ní plakat a bít se v prsa králové země, kteří s ní smilnili a hýřili, až uvidí dým z jejího požáru.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Z hrůzy nad její trýzní budou stát zdaleka a budou říkat: „Běda, běda, ty veliké město Babylone, ty mocné město, neboť v jedné hodině přišel tvůj soud.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'A obchodníci země nad ní pláčou a truchlí, protože už nikdo nekoupí jejich zboží:');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'náklady zlata a stříbra, drahokamů a perel, kmentu, purpuru, hedvábí a šarlatu, všechny druhy vonného dřeva a veškeré předměty ze slonoviny a všeliké předměty ze vzácného dřeva, mědi, železa a mramoru,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'skořici, ⌈indické koření⌉, voňavky, mast a kadidlo, víno a olej, mouku a obilí, dobytčata a ovce, koně a vozy, otroky i lidské duše.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, '„Ovoce, po kterém toužila tvá duše, od tebe odešlo, všechen lesk a nádhera se ti ztratily a lidé je již nikdy více nenaleznou.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Obchodníci s těmito věcmi, kteří jejím prostřednictvím zbohatli, se ze strachu před její trýzní postaví zdaleka, budou plakat a truchlit');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'a říkat: „Běda, běda, město veliké, kterés bylo oblečeno do kmentu, purpuru a šarlatu, ozdobeno zlatem, drahokamy a perlami,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'neboť v jedinou hodinu bylo zpustošeno tak veliké bohatství.“Každý kormidelník, každý, kdo se plaví ⌈při pobřeží⌉, námořníci a všichni, kdo pracují na moři, se postavili zdaleka');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'a křičeli, když viděli dým jejího požáru: „Které město je podobno tomu velikému městu?“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'A nasypali si prach na hlavu a v pláči a truchlení volali: „Běda, běda, to město veliké, v němž všichni, kdo měli lodě na moři, zbohatli z jeho bohatství, a v jedinou hodinu bylo zpustošeno!“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Raduj se nad ní nebe a svatí, apoštolové i proroci, protože Bůh nad ní vynesl soud ⌈ za to, jak jednala s vámi⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Tu jeden silný anděl zvedl kámen, podobný velkému mlýnskému kameni, hodil jej do moře a řekl: „Takto s prudkostí bude zavržen Babylon, to veliké město, a nikdy více nebude nalezen.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Nikdy se již v tobě neozve hlas harfeníků, zpěváků, pištců a trubačů, nikdy už v tobě nebude žádný mistr jakéhokoliv řemesla, nikdo již v tobě neuslyší zvuk mlýnského kamene,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'nikdy už v tobě nezasvitne světlo lampy, nikdo už v tobě nezaslechne hlas ženicha a nevěsty. Neboť tvoji obchodníci byli velmožové země a tvými kouzly byly svedeny všechny národy.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'V něm byla nalezena krev proroků a svatých a všech zabitých na zemi.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Potom jsem uslyšel něco jako mocný hlas velikého zástupu v nebi, který říkal: „Haleluja! Záchrana, sláva i moc náleží našemu Bohu,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'protože pravé a spravedlivé jsou jeho soudy, neboť odsoudil tu velikou smilnici, která zničila zemi svým smilstvem, a potrestal krev svých otroků⌈, která je na jejích rukou⌉.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'A řekli podruhé: „Haleluja! Její dým vystupuje na věky věků.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'A těch čtyřiadvacet starších a ty čtyři živé bytosti padli na kolena a poklonili se Bohu sedícímu na trůnu se slovy: „Amen. Haleluja.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'A od trůnu vyšel hlas, který říkal: „Chvalte našeho Boha všichni jeho otroci [a] vy, kdo se ho bojíte, malí i velcí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'A uslyšel jsem jakoby hlas velikého zástupu a jakoby zvuk mnohých vod a jakoby zvuk silných hromů: „Haleluja, ujal se kralování Pán, náš Bůh, ten Všemohoucí.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Radujme se a jásejme a vzdávejme mu slávu, protože přišla svatba Beránkova a jeho žena se připravila;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'a bylo jí dáno, aby si oblékla zářivě čistý kment.“Tím kmentem jsou spravedlivé činy svatých.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'A řekl mi: „Napiš: Blahoslavení, kdo jsou pozváni k Beránkově svatební hostině.“Ještě mi řekl: „Toto jsou pravá Boží slova.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Padl jsem mu k nohám, abych se mu poklonil. Ale on mi řekl: „Varuj se toho! Jsem spoluotrok tvůj a tvých bratrů, kteří mají Ježíšovo svědectví. Bohu se pokloň! ⌈Ježíšovo svědectví je Duch⌉ proroctví.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'A uviděl jsem otevřené nebe, a hle, bílý kůň, a ten, kdo na něm seděl, [se jmenoval] Věrný a Pravý; spravedlivě soudí a bojuje.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Jeho oči byly [jako] plamen ohně a na hlavě měl mnoho diadémů; má napsané jméno, které nezná nikdo než on sám.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Je oblečen do pláště zbroceného krví a jeho jméno je Slovo Boží.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'A vojska, která jsou v nebi, jela za ním na bílých koních, oblečená do bělostného čistého kmentu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Z jeho úst vychází veliký ostrý meč, aby jím bil národy; bude je pást železnou berlou. On ⌈bude šlapat⌉ lis vína planoucího hněvu Všemohoucího Boha.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Na plášti a na svém boku má napsáno jméno: Král králů a Pán pánů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'A uviděl jsem jednoho anděla, jak stojí ve slunci. Mocným hlasem zvolal na všechny ptáky, letící ⌈prostředkem nebe⌉: „Pojďte, shromážděte se k veliké Boží hostině,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'abyste jedli těla králů a těla vojevůdců a těla silných, těla koní i těch, kdo na nich sedí, těla všech, svobodných i otroků, malých i velikých.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'A uviděl jsem šelmu a krále země i jejich vojska shromážděná, ⌈aby rozpoutali válku proti⌉ tomu, jenž seděl na koni, a proti jeho vojsku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Ale šelma byla zajata a s ní falešný prorok, který před ní činil znamení, jimiž svedl ty, kdo přijali cejch šelmy a kdo se klaněli jejímu obrazu; ti dva byli za živa uvrženi do ohnivého jezera, hořícího sírou.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Ostatní byli zabiti velikým mečem, který vyšel z úst toho, jenž seděl na koni. A všichni ptáci se nasytili jejich těly.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Uviděl jsem, jak z nebe sestupuje anděl, který měl klíč od bezedné propasti a ve své ruce veliký řetěz.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Zmocnil se draka, toho dávného hada, jenž jest Ďábel a Satan, na tisíc let jej spoutal');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'a uvrhl do bezedné propasti. A zamkl a zapečetil ji nad ním, aby již nesváděl národy, dokud se nedovrší těch tisíc let. Potom musí být ještě na krátký čas rozvázán.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'A spatřil jsem trůny a ty, kteří se na ně posadili, a byl jim svěřen soud; uviděl jsem také duše těch, kteří byli sťati pro Ježíšovo svědectví a pro Boží slovo, i ty, kteří se nepoklonili šelmě ani jejímu obrazu a nepřijali její cejch na čelo ani na ruku. I ožili a kralovali s Kristem tisíc let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Ostatní mrtví neožili, dokud se těch tisíc let nedovršilo. To je první vzkříšení.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Blahoslavený a svatý, kdo má podíl na prvním vzkříšení; nad těmi druhá smrt nemá pravomoc, nýbrž budou kněžími Božími a Kristovými a budou s ním kralovat tisíc let.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Až se těch tisíc let dovrší, bude Satan propuštěn ze svého vězení');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'a vyjde, aby svedl národy, které jsou ve všech čtyřech úhlech země, Góga i Magóga, a shromáždil je k boji; a bude jich jako písku v moři.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Vystoupili na šíři země a obklíčili ležení svatých a milované město. Ale sestoupil oheň z nebe a pohltil je.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'A Ďábel, který je sváděl, byl uvržen do jezera ohně a síry, kde je šelma a falešný prorok. A budou trýzněni dnem i nocí na věky věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'A uviděl jsem veliký bílý trůn a toho, kdo na něm seděl; před jeho tváří zmizela země i nebe a jejich místo již více nebylo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'A uviděl jsem mrtvé, velké i malé, jak stojí před trůnem, a byly otevřeny knihy. Byla otevřena i jiná kniha, to jest kniha života. A mrtví byli souzeni podle svých skutků, zapsaných v těch knihách.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'A moře vydalo mrtvé, kteří v něm byli, i Smrt a Hádes vydali mrtvé, kteří v nich byli, a každý byl souzen podle svých skutků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'A Smrt a Hádes byli uvrženi do ohnivého jezera. To je ta druhá smrt: ohnivé jezero.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'A kdo nebyl nalezen zapsán v knize života, byl uvržen do ohnivého jezera.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'A spatřil jsem nové nebe a novou zemi, neboť první nebe a první země pominuly, a moře již není.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'A to svaté město, nový Jeruzalém, jsem uviděl sestupovat z nebe od Boha, připravené jako nevěsta ozdobená pro svého muže.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'A uslyšel jsem mocný hlas z trůnu, který řekl: „Hle, Boží stánek s lidmi; bude přebývat s nimi a oni budou jeho lid, a sám Bůh bude s nimi [a bude jejich Bohem].');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'A [Bůh] setře každou slzu z jejich očí. A smrti již nebude, ani žalu ani křiku ani bolesti již nebude, [neboť] první věci pominuly.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Ten, který seděl na trůnu, řekl: „Hle, činím všechno nové.“A řekl [mi]: „⌈Napiš: Tato⌉ slova jsou věrná a pravá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'A řekl mi: „Stalo se. Já jsem Alfa i Omega, počátek i konec. Já dám žíznivému zadarmo napít z pramene vody života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Kdo vítězí, dostane toto jako dědictví; budu mu Bohem a on mi bude synem.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Avšak bázliví, nevěřící, ti, kdo propadli modlářské ohavnosti, vrahové, smilníci, kouzelníci, modloslužebníci a všichni lháři mají svůj díl v jezeře, které hoří ohněm a sírou, což je smrt druhá.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Vtom přišel jeden z těch sedmi andělů, kteří měli sedm misek plných sedmi posledních ran, a promluvil se mnou slovy: „Pojď, ukážu ti Nevěstu, ženu Beránkovu.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'V Duchu mne odnesl na velikou a vysokou horu a ukázal mi svaté město Jeruzalém, jak sestupuje z nebe od Boha,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'mající Boží slávu. Jeho jas je podobný nejvzácnějšímu kameni, je jako kámen jaspis, čistý jako křišťál.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Má velikou a vysokou hradbu, má dvanáct bran a na těch branách dvanáct andělů a napsaná jména, která jsou [jmény] dvanácti kmenů [synů] Izraele.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Tři brány jsou na východ, tři brány na sever, tři brány na jih a tři brány na západ.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'A hradba toho města má dvanáct ⌈základních kamenů⌉ a na nich dvanáct jmen dvanácti Beránkových apoštolů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Ten, který se mnou mluvil, měl jako měřidlo zlatou třtinu, aby změřil město, jeho brány i jeho hradbu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Město je rozloženo do čtverce: jeho délka je stejná jako šířka. Změřil město tou třtinou na dvanáct tisíc stadií, jeho délka, šířka i výška jsou stejné.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Změřil také jeho hradbu: sto čtyřicet čtyři loktů podle lidské míry, ⌈která je také mírou andělskou⌉.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Stavivem jeho hradby je jaspis a město je z čistého zlata, podobné čistému sklu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Základy městské hradby jsou ozdobeny všelijakými drahými kameny: první základ ní kámen je jaspis, druhý safír, třetí chalcedon, čtvrtý smaragd,');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'pátý sardonyx, šestý karneol, sedmý chrysolit, osmý beryl, devátý topas, desátý chrysopras, jedenáctý hyacint, dvanáctý ametyst.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'A dvanáct bran, dvanáct perel; každá z těch bran byla z jedné perly. A náměstí města bylo čisté zlato jako průhledné sklo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Avšak svatyni jsem v něm neviděl, neboť jeho svatyní je Pán Bůh Všemohoucí a Beránek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'A to město nepotřebuje slunce ani měsíc, aby mu svítily. Ozářila ho Boží sláva a jeho lampou je Beránek.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'A národy budou chodit ⌈v jeho světle⌉ a králové země do něho přinášejí svou slávu.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Jeho brány nebudou nikdy ve dne uzavřeny, a noci tam už nebude.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'A přinesou do něho slávu a čest národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'A nevstoupí do něho nic nečistého ani ten, kdo činí ohavnost a lež, ale jen ti, kdo jsou zapsáni v Beránkově knize života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'I ukázal mi řeku vody života, čirou jako křišťál, která vycházela z trůnu Božího ⌈a Beránkova.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Uprostřed náměstí toho města, z obou⌉ stran řeky je strom života, nesoucí dvanáctero ovoce; každý měsíc vydává své ovoce a listí toho stromu slouží k léčení národů.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Nic prokletého již nebude. V tom městě bude Boží a Beránkův trůn a jeho otroci mu budou sloužit');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'a budou vidět jeho tvář a na jejich čelech bude jeho jméno.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Noci již nebude ani ⌈nebude třeba⌉ světla lampy nebo světla slunce: Pán Bůh ⌈je bude osvěcovat⌉ a budou kralovat na věky věků.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'I řekl mi: „Tato slova jsou věrná a pravá; Pán Bůh duchů proroků poslal svého anděla, aby svým otrokům ukázal, co se má brzo stát.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'A hle, ⌈přijdu brzy⌉. Blahoslavený, kdo zachovává slova proroctví tohoto svitku.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Já, Jan, jsem ten, kdo tyto věci slyšel a viděl. A když jsem to uslyšel a uviděl, padl jsem k nohám anděla, který mi tyto věci ukazoval, abych se mu poklonil.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Řekl mi: „Varuj se toho! Jsem spoluotrok tvůj a tvých bratrů proroků a těch, kdo zachovávají slova tohoto svitku. Bohu se pokloň.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Ještě mi řekl: „Nezapečeť slova proroctví tohoto svitku, neboť ten čas je blízko.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Kdo ubližuje, ať ještě ubližuje do konce, kdo je špinavý, ať se ještě ušpiní, a kdo je spravedlivý, ať ještě až do konce koná spravedlnost, a kdo je svatý, ať se ještě posvětí.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, '„Hle, ⌈přijdu brzy⌉ a moje mzda se mnou, abych odplatil každému podle toho, jaké je jeho dílo.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Já jsem Alfa i Omega, první i poslední, počátek i konec.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, '„Blahoslavení ti, kdo ⌈si perou roucha⌉, aby měli právo ke stromu života a aby branami vstoupili do města.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Venku zůstanou psi, kouzelníci, smilníci, vrahové a modloslužebníci i každý, kdo miluje a činí lež.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, '„Já, Ježíš, jsem poslal svého anděla, aby vám ve sborech tyto věci dosvědčil. Já jsem kořen a rod Davidův, jasná hvězda jitřní.“');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'A Duch i Nevěsta praví: „Přijď.“A kdo slyší, ať řekne: „Přijď.“A kdo žízní, ať přijde, a kdo chce, ať si zdarma vezme vodu života.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Já dosvědčuji každému, kdo slyší slova proroctví tohoto svitku: kdo by k nim něco přidal, tomu Bůh přidá ran zapsaných v tomto svitku;');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'a kdo by ze slov svitku tohoto proroctví něco odejmul, tomu Bůh odejme jeho díl ze stromu života a ze svatého města, které byly popsány v tomto svitku.');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Ten, který o tom svědčí, praví: „Ano, ⌈přijdu brzy⌉.“Amen, přijď, Pane Ježíši!');
INSERT INTO `CzeCSP_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Milost Pána Ježíše [Krista] se všemi [svatými]. [Amen.]');
